INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(174864, 'ط', '<span class=\"hlight\">ط.</span> (حرف ) نشانه ٔ حرف نوزدهم از حروف تهجی عرب . و نام آن طاء و طی و طِ است و نیز آن را طاء مشالة نامند و آن از حروف مطبقة و حروف هفت گانه ٔ مستعلیه و هم مصمتة و محقوره و مهجوره ٔ نطعیه است و در حساب جمل آن را به <span class=\"hlight\" dir=\"rtl\">٩</span> دارند و در شمار ترتیبی نماینده ٔ عدد شانزده است و در تجوید رمز وقف مطلق باشد و در کتب حدیث نشانه ٔکتاب الموطاء مالک است و در موسیقی علامت طنین است ودر نجوم نشان برج جَدی و این حرف یکی از حروف هشت گانه است که در فارسی نیامده است . لیکن در بعض کلمات فارسی برای رفع اشتباه با حرف دیگر این صورت در کتابت آید مانند: طراز و طپیدن و طپانچه و طبرستان و طافته به معنی پارچه ٔ مخصوص ابریشمین و امثال آن، و گاهی در کتب قدیمه تلخ به معنی (مرّ) را طلخ نوشته اند.<br />ابدالها:<br />> در عربی گاه به «دال » بدل شود:<br />طبق = دبق .<br />عجالط = عجالد.<br />طغر = دعر.<br />طوران = دوران .<br />اجتلاط = اجتلاد.<br />نمط = نمد.<br />بطغ = بدغ .<br />> گاه به «فا» بدل شود:<br />حلط = حلف .<br />> گاه به «زاء» معجمه بدل شود:<br />عجالط = عجالز.<br />« در تعریب :<br />> بدل «دال » آید:<br />قنّبیط = غنبید.<br />> گاه بدل «تاء» منقوطه ٔمثناة باشد چون :<br />طبرستان = تبرستان .<br />طنجه = تنگه .<br /></font></div>'),
(174865, 'طاء', '<span class=\"hlight\">طاء.</span> (اِ) نام حرف ط. حرف شانزدهم از حروف تهجی است .<br /></font></div>'),
(174866, 'طاب', '<span class=\"hlight\">طاب .</span> (ع مص ) طِیب . طِیبة. تَطیاب . خوشمزه وپاک و پاکیزه گردیدن . <BR><font color=\"Blue\">◄</font> طابت الأرض ؛ گیاه ناک گردید زمین . <BR><font color=\"Blue\">◄</font> طِبت به نفساً؛ ای طابت به نفسی ؛ خوش شد دل من به او. <BR><font color=\"Blue\">◄</font> طابه ُ؛ خوش کرد آن را. پاک و پاکیزه ساخت . <BR><font color=\"Blue\">◄</font> ما اطیبه ُ!؛ چه پاکیزه و خوش است آن . (منتهی الارب ).<br /></font></div>'),
(174867, 'طاب', '<span class=\"hlight\">طاب .</span> (اِخ ) (رود...) نهر عظیمی است بفارس مخرج آن از جبال اصفهان نزدیک برج است تا اینکه در نهر مسن میریزد و نهر مسن از حدود اصفهان خارج گشته در ناحیه ٔ سردن به نزدیکی قریه ای که مسن نام دارد ظاهر میشود و سپس تا در ارجان در زیر پل رکان که بین فارس و خوزستان جای دارد جاری شده پس از مشروب ساختن رستاق ریشهر به نزدیکی نهر تستر به دریا میریزد. (معجم البلدان ). آب طاب از کوههای سمیرم لرستان برمیخیزد و همه وقتی گذار اسب ندهد... این آب سر حد فارس و خوزستان است و طولش چهل و هفت فرسنگ باشد. (نزهةالقلوب ص <span class=\"hlight\" dir=\"rtl\">٢٢٤</span>). همان رودخانه ٔ تاب کوه گیلویه است آبش شیرین . گویند از آب دجله ٔ بغداد گواراتر است . آب چشمه ٔ منبی و آب اوسل، در رودخانه ٔ فلات ناحیه ٔ یوسفی کوه گیلویه بهم پیوسته، در دامنه ٔ قلعه ٔ دزکوه به رودخانه ٔ کلات آمیخته، رودخانه ٔ تاب شده از تنگ تکاب ناحیه ٔ حومه ٔ بهبهان میگذرد. در قدیم کنار شهر ارّجان بندی بر این رودخانه بسته اند که دهات حومه ٔبهبهان را آب میداده و اکنون آن بند شکسته است و یکجانب رودخانه دیمی مانده است و دهات جانب دیگر را آب دهد. پس آب چشمه ٔ قیر، و آب چشمه های تشان حومه ٔ بهبهان به این رودخانه آمیخته بعد از چندین فرسخ که از چم نظامی بگذرد، در جایزان رامهرمز چون به رودخانه ٔ ارمش آمیزد رودخانه ٔ جایزان شود. (فارسنامه ٔ ناصری ).رود طاب از کوه دل و کوه گیلویه سرچشمه گرفته دارای سه شعبه است که یکی را آب شیرین یا خیرآباد و دیگری را آب شور یا شولستان نامند و سومی که به اسامی مختلفه زهره و فهلیان موسوم است در مشرق زیدان به آن دوملحق گردیده تشکیل رود طاب را میدهد که از هندیان گذشته بخلیج فارس میریزد. (جغرافی طبیعی کیهان صص <span class=\"hlight\" dir=\"rtl\">٧٩</span> - <span class=\"hlight\" dir=\"rtl\">٧٨</span>). آب رود طاب بواسطه سبکی و گوارائی معروف و سلاطین ایران فقط از این آب می آشامیده اند. (جغرافیای کیهان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٣</span>). و شهر ارّجان بر کنار این رود باشد. نام رودی است میان پارس و خوزستان . (حدود العالم ).<br /></font></div>'),
(174868, 'طاب', '<span class=\"hlight\">طاب .</span> (ع اِ) بوی خوش . <BR><font color=\"Blue\">◄</font> (ص ) پاک . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> لذیذ. <BR><font color=\"Blue\">◄</font> (اِمص ) خوشی . <BR><font color=\"Blue\">◄</font> پاکی . (دهار).<br /></font></div>'),
(174869, 'طاب', '<span class=\"hlight\">طاب .</span> (اِخ ) دهی است ببحرین . (منتهی الارب ).<br /></font></div>'),
(174870, 'طاب ثراه', '<span class=\"hlight\">طاب ثراه .</span> <font color=\"DarkGreen\"><b>[ ب َ ث َ ]</font></b> (ع جمله ٔ فعلیه ٔ دعایی ) پاک و پاکیزه باد خاک او. دعائی است که درباره ٔ مردگان هنگام ذکر نام آنان بر زبان آرند.<br /></font></div>'),
(174871, 'طاب رود', '<span class=\"hlight\">طاب رود.</span> (اِخ ) رودی است که از وسط شهر ارجان میگذرد: آبش <font color=\"DarkGreen\"><b>[ یعنی ارجان ]</font></b> از رود طاب که در میان آن ولایت میگذرد. و بر آن آب پولی ساخته اند. آن را پول ثگان خوانند. (نزهة القلوب چ لیدن ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span>). و رجوع به طاب (رود...) شود.<br /></font></div>'),
(174872, 'طاب طاب', '<span class=\"hlight\">طاب طاب .</span> (اِ) طبطاب <span class=\"hlight\">:</span> و بگذشته شدن او توان گفت که سواری و چوگان و طاب طاب و دیگر آداب این کار مدروس شد. (تاریخ بیهقی ). رجوع به طبطاب شود.<br /></font></div>'),
(174873, 'طاباریوس', '<span class=\"hlight\">طاباریوس .</span> (اِخ ) یکی از قیاصره ٔ روم و او دومین امپراطور روم است پسر لیوی پسر خوانده ٔ اوغسطس، او با آنکه مردی روشن فکر و عفیف بود لکن در تحت سلطه ٔ وزیر خویش سژان ظلم و بیداد را بحد اعلی رسانید. مولد او به سال <span class=\"hlight\" dir=\"rtl\">٤٢</span> ق .م . و وفات <span class=\"hlight\" dir=\"rtl\">٣٧</span> م . بود. و رجوع به قفطی ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span> شود.<br /></font></div>'),
(174874, 'طاباق', '<span class=\"hlight\">طاباق .</span> (ع اِ) خشت پخته ٔ کلان . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> آجر بزرگ . (فهرست مخزن الادویه ).<br /></font></div>'),
(174875, 'طابان', '<span class=\"hlight\">طابان .</span> (اِخ ) دهی است به خابور. (منتهی الارب ).<br /></font></div>'),
(174876, 'طابة', '<span class=\"hlight\">طابة.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ع اِ) شراب انگوری . (منتهی الارب ). خمره خمر. طیّب صافی که به فارسی می خوشخوار نامند. شراب خوشخوار. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> نام ثمری است که در مدینه ٔ منوره یافت میشود. (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> خرما. <BR><font color=\"Blue\">◄</font> (اِخ ) نام مدینه ٔ منوره . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> جایگاهی است در زمین طی . (مراصد الاطلاع ).<br /></font></div>'),
(174877, 'طابث', '<span class=\"hlight\">طابث .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) شهرکی است در نزدیکی شهرابان از اعمال خالص از نواحی بغداد. و صاحب مراصد گوید: و ظاهراً نهری است که از تامرا آغاز شود و در مسیر آن قریه هاست . و یکی از اعمال طریق خراسان است .<br /></font></div>'),
(174878, 'طابح', '<span class=\"hlight\">طابح .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) اولین فرزند ناحور، برادر حضرت ابراهیم علیه السلام که از رؤومة کنیزک فراشی ناحور بدنیاآمده بود. (سفر پیدایش <span class=\"hlight\" dir=\"rtl\">٢٢</span>:<span class=\"hlight\" dir=\"rtl\">٢٤</span>) (قاموس کتاب مقدس ).<br /></font></div>'),
(174879, 'طابخ', '<span class=\"hlight\">طابخ .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) تب سخت گرم . (منتهی الارب ) (دهار) (بحر الجواهر). تب تُند. <BR><font color=\"Blue\">◄</font> طبّاخ . آشپز. دیگ پز. خوالیگر. مطبخی .<br /></font></div>'),
(174880, 'طابران', '<span class=\"hlight\">طابران .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) یکی از نقاط قلمرو ابوخزیمه بوده است . (سفرنامه ٔ مازندران و استراباد رابینو).<br /></font></div>'),
(174881, 'طابران', '<span class=\"hlight\">طابران .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) طبران . یکی از دو شهر باستانی طوس . طابران و نوقان، که مجموعاً طوس نامیده میشدند. (مراصد الاطلاع نقل به معنی ). <BR><font color=\"Blue\">◄</font> یاقوت در معجم البلدان به نقل از بلاد ری گوید: خراسان چهار قسمت بوده، ربع اول ایرانشهر که عبارت بود از نیشابور، قهستان، طبسان، هرات، بوشنج، بادغیس و طوس که نام آن طابران است . (معجم البلدان ). و این شهر مولد شاعر شهیر فردوسی طوسی علیه الرحمه است از قریه ٔ باژ. رجوع به چهار مقاله چ قزوینی چ بریل ص <span class=\"hlight\" dir=\"rtl\">٤٧</span> شود <span class=\"hlight\">:</span> و چون نتواند بر آن راه رفتن اگر براه هرات و سرخس رود ممکن باشد او را گرفتن . پس بر این عزم سوی طابران طوس رفت . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٦١٦</span>). و سبج (شبه ) نیکومعدنش در طابران طوس است . (الجماهر بیرونی ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span>).<br /></font></div>'),
(174882, 'طابرانی', '<span class=\"hlight\">طابرانی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ص نسبی ) منسوب به طابران (طوس ). و آن یکی از دو شهری است که مجموع آندو را طوس مینامیده اند. گاه الف آن را حذف کنند. ولی صحیح همان طابران است . (سمعانی ).<br /></font></div>'),
(174883, 'طابستان', '<span class=\"hlight\">طابستان .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (معرب، اِ مرکب ) معرب تابستان . از آلات ارباب کیمیاست .<br /></font></div>'),
(174884, 'طابع', '<span class=\"hlight\">طابع.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ع اِ) انگشترین . <BR><font color=\"Blue\">◄</font> آنچه بدان بر عطایای مرسوم و مانند آن نشان و علامت کنند. و منه : علیه طابعُ الشهداء؛ ای علامتهم . (منتهی الارب ) (آنندراج ).و کسرالباء لغةُ فی الکل . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> انگشتری و هر چه بدان مهر کنند. <BR><font color=\"Blue\">◄</font> آلت داغ که بدان چارپایان صدقات را نشان کنند. (شمس اللغات ). <BR><font color=\"Blue\">◄</font> مهر خرمن . شگل . (مهذب الاسماء).<br /></font></div>'),
(174885, 'طابع', '<span class=\"hlight\">طابع.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص، اِ) اخلاقی که در مردم پیدا وترکیب یافته باشد از مطعم و مشرب و غیر آن که دفعش ناممکن بود. سرشت . <BR><font color=\"Blue\">◄</font> مُهرزن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> چاپچی .<br /></font></div>'),
(174886, 'طابق', '<span class=\"hlight\">طابق .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (معرب، اِ) معرب تابه است . ج، طوابق و طوابیق . (منتهی الارب ). تابه . و آن ظرف آهنی است مدور که بر آن نان پزند.(آنندراج ) (غیاث اللغات ). تابه . طاجن . (مهذب الاسماء): و امّا الذی <font color=\"DarkGreen\"><b>[ ای خیر الذی ]</font></b> یخبز فی الطابق او یدفن فی الجمر... (ابن البیطار.) رجوع به طاجن شود. تابه . تاوه . (از ماده ٔ تافتن ). خبز طابق ؛ نان که بر آجر تفته پزند. خشت پخته ٔ کلان . (آنندراج ) (منتهی الارب ). نظامی . (یادداشت مؤلف ). <BR><font color=\"Blue\">◄</font> عضو، هر چه باشد: و منه فی غلام آبق، لاقطعن منه طابقاً ان قدرت ُ علیه ؛ ای عضواً. <BR><font color=\"Blue\">◄</font> دست، و منه امر فی السارق بقطع طابقه ؛ ای یده .(منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> آنقدر از بز که سیر کند دو سه کس را. یا نصف بز. (منتهی الارب ).<br /></font></div>'),
(174887, 'طابق', '<span class=\"hlight\">طابق .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) موضعی است در عراق عرب . و شهرهای باجسری و شهرابان (در طریق خراسان ) که دختری ابان نام از تخم کسری ساخته . و اعمال طابق و مهرود از توابع آن عمل است و آن اعمال هشتاد پاره دیه است . (نزهة القلوب چ لیدن ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>).<br /></font></div>'),
(174888, 'طابق', '<span class=\"hlight\">طابق .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) نهر طابق . محله ای بوده است در بغداد که اکنون ویران است و در ذکر آن بیاید. (مراصد الاطلاع ).<br /></font></div>'),
(174889, 'طابق', '<span class=\"hlight\">طابق .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b>(معرب، اِ) طابقة. تَنباک . تَنباکو. تُتن . توتون .<br /></font></div>'),
(174890, 'طابق النعل بالنعل', '<span class=\"hlight\">طابق النعل بالنعل .</span> <font color=\"DarkGreen\"><b>[ ب ِ قُن ْ ن َ ل ِ بِن ْ ن َ ]</font></b> (ع ق مرکب <span class=\"hlight\" dir=\"rtl\">/</span> جمله ٔ فعلیه ) به معنی مطابق کننده ٔ کفش بر کفش . یعنی قدم نهنده بر قدم پیشروندگان . (غیاث اللغات ) (آنندراج ) (بفتح باء موحدة و فتح قاف و ضم ّ لام در کلمه ٔ نعل اول ) به معنی آنکه مطابق آمد کفش با کفش . و به این معنی در جائی استعمال کنند که این چیز با آن چیز مطابق آید. مگر در بهار دانش وجه اول است که سابق مذکور شد. (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کاملاً یکسان و برابر.<br /></font></div>'),
(174891, 'طابقی', '<span class=\"hlight\">طابقی .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع اِ) گویا نام طعامی یا حلوائی بوده از طابق معرب تابه، یا تابک . و ظاهراً اگر کلمه ٔ طائفی حلوای طائف نباشد در شعر ذیل طابقی است <span class=\"hlight\">:</span> <br />و آن زر از تو باز خواهد آنکه تا اکنون ازو<br />چو غری خوردی همی و طابقی ّ و لیولنگ .<br /><font color=\"Red\">غمناک (از فرهنگ اسدی ).</font><br /></font></div>'),
(174892, 'طابقیة', '<span class=\"hlight\">طابقیة.</span> <font color=\"DarkGreen\"><b>[ ب ِ قی ی َ ]</font></b> (ع ص ) عِمّة طابقیة؛ نوعی از دستار بستن . و آن سربستن باشد بی زیر حَنک . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(174893, 'طابن', '<span class=\"hlight\">طابن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) زیرک . فهیم . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> مرد استاد. دریابنده . (مهذب الاسماء).<br /></font></div>'),
(174894, 'طابور', '<span class=\"hlight\">طابور.</span> (ترکی، اِ) صف . فوج . کتیبة. (دراری اللامعات ).<br /></font></div>'),
(174895, 'طابون', '<span class=\"hlight\">طابون .</span> (ع اِ) جای آتش خوابانیدن . (منتهی الارب ) (آنندراج ). جائی که آتش پنهان کنند تا نمیرد. (کنزاللغات ).<br /></font></div>'),
(174896, 'طابیة', '<span class=\"hlight\">طابیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) بنت جزٔبن سعد الریاحی . این زن را در یوم اِراب از ایام عرب ذکری است و در آن روز اسیر شد و پدرش مالی بعنوان سربها داد و او را آزاد ساخت . (عقدالفرید، ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٩٣</span>).<br /></font></div>'),
(174897, 'طابیثا', '<span class=\"hlight\">طابیثا.</span> (اِخ ) (به معنی آهو) زنی که خود از شاگردان مسیح بود در یافا و تمامی قوم، وی را بواسطه ٔ اعمال حسنه اش دوست میداشتند و پس از آنکه سرای فانی را بدرود گفت و او را کفن نمودند بقول پطرس، خداوند وی را زنده فرمود. (اعمال رسولان <span class=\"hlight\" dir=\"rtl\">٣٦/٩</span>، <span class=\"hlight\" dir=\"rtl\">٤٠</span>).<br /></font></div>'),
(174898, 'طاثر', '<span class=\"hlight\">طاثر.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع ص، اِ) شیر خفته . (منتهی الارب ) (آنندراج ). رائب . شیر کلچیده . ماست . شیر تیره . (مهذّب الاسماء).<br /></font></div>'),
(174899, 'طاجن', '<span class=\"hlight\">طاجن .</span> <font color=\"DarkGreen\"><b>[ ج ِ <span class=\"hlight\" dir=\"rtl\">/</span> ج َ ]</font></b> (معرب، اِ) تابه که در آن بریان کنند. طیجن، و هر دو معرّب است . لان ّ الطاءَ والجیم لایجتمعان فی الکلام . (منتهی الارب ) (آنندراج ). تابه ٔ روغن جوشی . (دهار). تابه که چیزی بر آن بریان کنند. (غیاث از شرح نصاب ). فمما اخذوه (ای العرب ) من الفارسیة: الطیجن و الطاجن ُ و اصله طابق . (جمهره ٔ ابن درید به نقل سیوطی در المزهر). و گمان میکنم طاجن و طیجن معرب تیان پارسی باشد و طابق معرّب تابَه و تاوه ٔ پارسی . (یادداشت مؤلف ).<br /></font></div>'),
(174900, 'طاحل', '<span class=\"hlight\">طاحل .</span> <font color=\"DarkGreen\"><b>[ ح ِ ]</font></b> (ع ص ) سپُر زرنگ .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خمر طاحل </span> ؛ خمر کدر تیره رنگ و کذلک غبار طاحل . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(174901, 'طاحن', '<span class=\"hlight\">طاحن .</span> <font color=\"DarkGreen\"><b>[ ح ِ]</font></b> (ع ص ) آردکننده . <BR><font color=\"Blue\">◄</font> گاوی که در مرکز خرمن بندند وقت کوفتن خرمن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(174902, 'طاحنة', '<span class=\"hlight\">طاحنة.</span> <font color=\"DarkGreen\"><b>[ ح ِ ن َ ]</font></b> (ع ص، اِ) دندان آسیا. (دهار). ناجذ (دندان سپسین همه ). یکی از دندانهای آسیا. ج، طواحن <span class=\"hlight\">:</span> دندانی که طاحنه ٔ جسم است و غذاء روح به قوّت آن منهضم میشود، چون مُتآکِل شد و لذّت عیش به الم آن منغص گشت جز قلع و افاتت آن چاره نیست . (ترجمه ٔ تاریخ یمینی ) یکی از دوازده دندان که پس از ضواحک بود. (السامی فی الاسامی نسخه ٔ خطی ص <span class=\"hlight\" dir=\"rtl\">١٥٦</span>). دندان خاینده . دندان نرم کننده ٔ طعام . <BR><font color=\"Blue\">◄</font> آس که بپای گردانند. (مهّذب الاسماء در سه نسخه خطی ).<br /></font></div>'),
(174903, 'طاحون', '<span class=\"hlight\">طاحون .</span> (ع اِ) آسیا. (منتهی الارب ) (آنندراج ). رجوع به طاحونه شود <span class=\"hlight\">:</span> <br />بر در یاران تهیدست آمدن <br />هست بی گندم سوی طاحون شدن .<br /> <font color=\"Red\">مولوی .</font><br />چون شما را حاجت طاحون نماند<br />آبرا از جوی اصلی باز راند.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(174904, 'طاحونة', '<span class=\"hlight\">طاحونة.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) قریه ای است واقع در نیم فرسنگی میانه ٔ جنوب و مشرق شهر خفر. (فارسنامه ٔ ناصری ).<br /></font></div>'),
(174905, 'طاحونة', '<span class=\"hlight\">طاحونة.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (ع اِ) آسیا. و طاحون نیز آمده . (آنندراج ) (منتهی الارب ) (غیاث از شرح نصاب ). <BR><font color=\"Blue\">◄</font> آس آب (آسیائی که به آب گردد). (مهذب الاسماء). آسیای آبی . رَحی َ. آسیا. ناعور. <BR><font color=\"Blue\">◄</font> دست آس . (دهار). ج، طواحین .<br /></font></div>'),
(174906, 'طاحونة', '<span class=\"hlight\">طاحونة.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) موضعی است در قسطنطنیة. (معجم البلدان ).<br /></font></div>'),
(174907, 'طاحونی', '<span class=\"hlight\">طاحونی .</span> (ص نسبی ) منسوب به طاحون و طاحونه است که به معنی آسیاست . (سمعانی ).<br /></font></div>'),
(174908, 'طاحی', '<span class=\"hlight\">طاحی .</span> <font color=\"DarkGreen\"><b>[ حی ی ]</font></b> (ص نسبی ) اسم منسوب به بنی طاحیه که از محله های بصره است . (سمعانی ). <BR><font color=\"Blue\">◄</font> منسوب به طاحیةبن سودبن حجر که بطنی است از اَزد. (منتهی الارب ). رجوع به طاحیه شود. <BR><font color=\"Blue\">◄</font> (ع ص ) کرکس که در هوا گرد مردار گردد. ج، طواحی .<br /></font></div>'),
(174909, 'طاحی', '<span class=\"hlight\">طاحی .</span> (ع ص ) گروه بزرگ . <BR><font color=\"Blue\">◄</font> گسترده . <BR><font color=\"Blue\">◄</font> بالا برآمده . <BR><font color=\"Blue\">◄</font> آنچه پر کند هر چیز را. <BR><font color=\"Blue\">◄</font> درازکشیده . یقال : ضربه ُ ضربة طحا منها؛ ای امتدّ. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(174910, 'طاحیة', '<span class=\"hlight\">طاحیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص، اِ) مظلّةُ طاحیة؛ سایبان بزرگ . <BR><font color=\"Blue\">◄</font> مطحیة. مطحوة. (منتهی الارب ). رجوع به دو کلمه ٔ اخیر شود.<br /></font></div>'),
(174911, 'طاحیة', '<span class=\"hlight\">طاحیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) ابن سودبن حجر. بطنی است از اَزد. طاحی ّ منسوب به وی است . (منتهی الارب ).<br /></font></div>'),
(174912, 'طاحیة', '<span class=\"hlight\">طاحیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) از آبهای بنی العجلان است در زمین قعاقع، دارای نخل بسیار. (معجم البلدان ).<br /></font></div>'),
(174913, 'طاخ', '<span class=\"hlight\">طاخ .</span> <font color=\"DarkGreen\"><b>[ خِن ْ ]</font></b> (ع ص ) ظُلام طاخ ؛ تاریکی سخت تاریک . سخت تاریک . (منتهی الارب ).<br /></font></div>'),
(174914, 'طاخر', '<span class=\"hlight\">طاخر.</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (ع ص، اِ) ابر سیاه . (منتهی الارب ).<br /></font></div>'),
(174915, 'طاخک', '<span class=\"hlight\">طاخک .</span> <font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (اِ) نوعی از درخت که آن را طاق گویند. و به عربی علقم (؟) خوانند. بعضی گویند میوه ٔ درخت طاق است . بعضی دیگر گویند ثمره ٔ درختی است که آن را در گرگان زهر زمین گویند، اگر بهائم برگ آن را بخورند بمیرند. (برهان قاطع). در حاشیه ٔ برهان قاطع چاپ هند متذکر شده که : مننسکی بسند فرهنگ شعوری می نویسد که لفظ طاخک بزبان طبرستان به معنی درختی است که بعضی آن را طغک با طاء و غین و طاق نیز گویند و در تحقیق لغت طغک بسند کتاب مذکور می نویسد که آن شبیه بدرخت سرو و یا درخت صنوبر است . <BR><font color=\"Blue\">◄</font> ثمر آزاد درخت . (آنندراج ) (غیاث اللغات از بحرالجواهر). رجوع به زنز لخت شود.<br /></font></div>'),
(174916, 'طاخیة', '<span class=\"hlight\">طاخیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) نام موری که با سلیمان علیه السلام در سخن درآمد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(174917, 'طاد', '<span class=\"hlight\">طاد.</span> (ع ص ) گران از هر چه باشد. <BR><font color=\"Blue\">◄</font> شتر خواهان ماده . (منتهی الارب ). شتر مست . اشتر گشن خواه .<br /></font></div>'),
(174918, 'طادران', '<span class=\"hlight\">طادران .</span> (اِخ ) محلی است واقع در مغرب دریاچه ٔ وان . (نقشه ٔ بغایری ).<br /></font></div>'),
(174919, 'طادیة', '<span class=\"hlight\">طادیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص )مقلوب واطدَة، ثابت ِ دیرینه . یقال، عادَة طادِیة؛ ای ثابته قدیمة. ج، طیادِی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(174920, 'طاذ', '<span class=\"hlight\">طاذ.</span> (اِخ ) قریه ای است از اصفهان . (معجم البلدان ).<br /></font></div>'),
(174921, 'طاذی', '<span class=\"hlight\">طاذی .</span> (ص نسبی ) منسوب به طاذ که یکی از قُراء اصفهان است . (سمعانی ).<br /></font></div>'),
(174922, 'طار', '<span class=\"hlight\">طار.</span> (اِ) داریه زنگی . (دورویه ٔ زنگوله دار) .<br /></font></div>'),
(174923, 'طار', '<span class=\"hlight\">طار.</span> (اِخ ) کوهی است در بطن السلمی از سرزمین یمامه . (معجم البلدان ).<br /></font></div>'),
(174924, 'طار', '<span class=\"hlight\">طار.</span> <font color=\"DarkGreen\"><b>[ طارر ]</font></b> (ع ص ) غُلام طارّ؛ کودک نوخط. (منتهی الارب ). مرد سبلت دمیده . (مهذب الاسماء).<br /></font></div>'),
(174925, 'طار', '<span class=\"hlight\">طار.</span> (اِ) نوعی از ماهی است که در خلیج فارس صید کنند و مأکول اللحم است .<br /></font></div>'),
(174926, 'طاراب', '<span class=\"hlight\">طاراب .</span> (اِخ ) دهی است به بخارا. (منتهی الارب ). و اهالی این قریه نام آن را تاراب با تاء دو نقطه تلفظ میکنند. (معجم البلدان ).<br /></font></div>'),
(174927, 'طارابی', '<span class=\"hlight\">طارابی .</span> (ص نسبی ) منسوب به طاراب که قریه ای از بخاراست . (سمعانی ).<br /></font></div>'),
(174928, 'طاربند', '<span class=\"hlight\">طاربند.</span> <font color=\"DarkGreen\"><b>[ رَ ب َ ]</font></b> (اِخ ) موضعی است که در شعر مؤمّل بن اَمیل محاربی ذکر آن آمده است . (معجم البلدان ).<br /></font></div>'),
(174929, 'طارد', '<span class=\"hlight\">طارد.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) راننده : وَ مااَنا بطارد الّذین آمنوا. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٩/١١</span>). و ما انا بطارد المؤمنین . (قرآن <span class=\"hlight\" dir=\"rtl\">١١٤/٢٦</span>). سخت راننده . رادع .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاردالریاح </span> ؛ بادکُش . بادشکن . کاسرالریاح . <br /></font></div>'),
(174930, 'طاردالدب', '<span class=\"hlight\">طاردالدب .</span> <font color=\"DarkGreen\"><b>[ رِ دُدْ دُب ب ]</font></b> (اِخ ) (اصطلاح نجوم ) ستاره ٔ عوّاء.بقّار. بؤرطیس حارس . راعی الشاء. حارس الشمال . حارس السماء. فارسی آن گاوچران است . رجوع به بقّار شود.<br /></font></div>'),
(174931, 'طاردالنوم', '<span class=\"hlight\">طاردالنوم .</span> <font color=\"DarkGreen\"><b>[ رِ دُن ْ ن َ ]</font></b> (ع اِ مرکب ) سنگی سفید است که بسیاهی زند و آن گران وزن و خشن بود و باشد که سبز بودبقدر ده حبه به هر که درآویزند خواب نکند و چشم بر هم نزند و بقدر نیمدانگ جذام ببرد. (نزهة القلوب ).<br /></font></div>'),
(174932, 'طارس', '<span class=\"hlight\">طارس .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b>(اِخ ) موضعی است بسواحل بحر فارس . (مراصد الاطلاع ).<br /></font></div>'),
(174933, 'طارسیس', '<span class=\"hlight\">طارسیس .</span> (اِ) تکدرّ. (بحر الجواهر). <BR><font color=\"Blue\">◄</font> علک البطم وآن را <font color=\"DarkGreen\"><b>[ صمغ ]</font></b> حبّةالخضراء نیز نامند . (مخزن الادویه ). رجوع به طارکیس شود.<br /></font></div>'),
(174934, 'طارط', '<span class=\"hlight\">طارط.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) تُنُک موی . سبک موی .خفیف الشعر. (تاج العروس ) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(174935, 'طارطقه', '<span class=\"hlight\">طارطقه .</span> <font color=\"DarkGreen\"><b>[ رَ ق َ ]</font></b> (اِ) دانه ای است که آن را ماهودانه گویند. وبه عربی حب ّالملوک خوانند . و این غیر حب ّ السلاطین است . (برهان ) (آنندراج ).<br /></font></div>'),
(174936, 'طارف', '<span class=\"hlight\">طارف .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) مال نو. مال تازه . مال بهتر. خلاف تالد. (آنندراج )(غیاث الغات ) (مهذب الاسماء). مال مستحدث . مال نو یافته را گویند. (برهان ) .<br /></font></div>'),
(174937, 'طارفة', '<span class=\"hlight\">طارفة.</span> <font color=\"DarkGreen\"><b>[ رِ ف َ ]</font></b> (ع ص ) طارف . جاء بطارفة عین ؛ آورد مال بسیار از. (منتهی الارب ). ج، طوارف . <BR><font color=\"Blue\">◄</font> در عربی بکسر ثالث، شخصی را گویند که میان او و جدّ اکبر او آباء بسیار باشند یعنی از جد اکبر خود بسیار دور باشد. (برهان ). <BR><font color=\"Blue\">◄</font> میوه و جز آن که غریب و نادر بود.<br /></font></div>'),
(174938, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) ابن المرقع. تابعی است . (منتهی الارب ). راوی طارق یکی عطاء و دیگری عبداﷲ پسر طارق بود، و در صحبت او نظر است . اخشی ان یکون حدیثه فی موات الارض ُ مرسلاً. (استیعاب ص <span class=\"hlight\" dir=\"rtl\">٢١٣</span>). او از طایقه ٔ بنی کنانة بوده، و در حدیث میمونة، دختر «کردم »، وی را ذکری است . حدیث میمونة از اخراجات ابوداود و احمد است . میمونة گفت با پدرم در یکی از سفرهای رسول خدا که به مکه میرفت همراه بودم، آن حضرت را دیدم در حالی که پدرم بسوی او نزدیک شد، و پیش پای اورا بگرفت . آن حضرت برای او بایستاد، و بسخن او گوش فراداد، پدرم گفت : یا رسول اﷲ، من در لشکر عثران حاضربودم که طارق بن المرقع گفت کیست که مرا نیزه ای بخشد، و پاداش آن دریابد؟ پدرم پرسید پاداش آن چه باشد؟ طارق گفت نخست دختر خود را بزنی بدو دهم . پدرم در حال نیزه ای بدو داد و پس از آن از یکدیگر جدا شدند. پس از چندی پدرم بازآمد، و گفت خانواده ٔ مرا با جهیزش تسلیم کن، طارق سوگند یاد کرد که بعهد خود وفا نکند، مگر به کابینی تازه و نو. الی آخر الحدیث . ابونعیم گفته است که طارق بن المرقع را برخی حجازی دانسته اند و صحابی، لیکن برای صحت این قول برهانی اقامه نشده است . چه آن کسی که دختر خود را نامزد کرد «کردم » بود که اسلام وی محقق نیست، و اگر طارق بن المرقع مسلمان باشد، کسی دیگر و تابعی است که از صفوان بن امیة روایت می کند، و عطأبن ابی رافع هم راوی اوست . ابونعیم پس از این گفتار سیاق روایت را نقل کرده است . صاحب «الاصابة» گوید: ابن مندة بدین قول اشاره ای کرده، لیکن هردو تن را یکی دانسته، و گفته است که طارق بن المرقع را حدیثی است مسند از صفوان بن امیة. و نیز مؤلف «الاصابة» گوید: آنان بدون تردید دو تن میباشند، آن که صحابی است، مردی سال خورده و دانشمندی بزرگوار است که در حجّة الوداع همراه حضرت پیغمبر صلی اﷲ علیه و آله و سلم بوده، و آن که از صفوان بن امیة روایت دارد، ازتابعین و معدود در طبقه ٔ دوم میباشد. و در خبر کردم، به خوبی روشن است که طارق با آن حضرت و یاران وی همسفر بوده، چه سخن «کردم » میرساند که او میخواست در محضر آن حضرت دادخواهی کند. و ابوعمرو (صاحب الاستیعاب ) گفته است : پسر طارق بن المرقع که عبداﷲ نام داشته راوی پدر خود بوده، و عطاء هم راوی دیگر اوست . اخشی ان یکون حدیثه فی موات الارض مرسلا. - انتهی . مؤلف «الاصابة» گوید قلت هذا هوالتابعی . (الاصابة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٣</span>).<br /></font></div>'),
(174939, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) ابن زیاد. بلاذری در کتاب فتوح البلدان گوید. واقدی نقل کند که طارق بن زیاد عامل موسی بن نصیر بسوی اندلس لشکرکشی کرد. او اوّل کسی بود که به جنگ با اندلسیان پرداخت و اقدام او در جنگ به سال <span class=\"hlight\" dir=\"rtl\">٩٢</span> هَ . ق . بود. اِلیان که والی مجاز اندلس بود با طارق دیدار کرد و طارق او را امان داد مشروط بر آنکه طارق و همراهانش را از دریا با کشتی به اندلس رساند. الیان آن شرط پذیرفت و آنان را به اندلس رسانید. طارق بمجرد رسیدن به اندلس شروع بجنگ کرده و در همان سال <span class=\"hlight\" dir=\"rtl\">٩٢</span> اندلس را فتح کرد. بنابر عقیده ٔ مورّخان پادشاه آنجا از خانواده ٔ اشبان بود که اصلاً ازاصبهان بوده اند. موسی بن نصیر چون از فتح اندلس با خبر شد نامه ای بطارق نبشت مبنی بر آنکه مسلمانان را بهلاکت و فتنه انداختی و رای کارزار دادی و ضمناً فرمان داد که از قرطبه تجاوز نکند و خود بسوی قرطبه رهسپار شد. چون موسی به قرطبه رسید و با طارق دیدار کرد، طارق وسایل ترضیه ٔ او را فراهم ساخت او نیز خشنود گردید. طارق شهر طلیطله را که پایتخت اندلس بود فتح کرد این شهر مجاور افرنجه است . طارق در طلیطله به مائده ای دست یافت که آن را تسلیم موسی کرد و موسی هنگامی که ولیدبن عبدالملک از دمشق بازمیگشت و در آنحال بیمار بود آن مائده را به ولید پیشکش کرد. (فتوح البلدان ص <span class=\"hlight\" dir=\"rtl\">٢٣٩</span>). و بیرونی گوید: طارق غلام موسی بن نصیر از سرداران دوره ٔ خلافت ولیدبن عبدالملک بود که در سال <span class=\"hlight\" dir=\"rtl\">٩٢</span> کشور اندلس را فتح کرد. و جبل الطارق منسوب به او است . رجوع به جبل شود. در سال <span class=\"hlight\" dir=\"rtl\">٩٢</span> طارق غلام موسی بن نصیر از ناحیه ٔ زمین مغرب عبور کرد و خود را به اندلس رسانید. پادشاه آن کشور را در حالی که بر سریری که بر بالای آن گنبدمانندی نهاده شده و به جواهر گرانبها مکلل بود و بر پشت دو چارپا به رسم گردونه های یونانیان (مراکب القتال ) که هندوان آن را «رتو» گویند و مانند رُخ شطرنج ساخته شده سوار بود در میدان جنگ بکشت .و در این وقت بسیار دیده شد که یکی از لشکریان طارق از بر ابره باری را که محتوی گوهرهای قیمتی و دیباهای خسروانی بود به گزافه به یکی از لشکریان تازی به یک یا دو درهم میفروخت . در سال <span class=\"hlight\" dir=\"rtl\">٩٣</span> موسی بن نصیر بسوی اندلس رهسپار شد و در آنجا او را با طارق دیدار افتاد و با یکدیگر بشهر طلیطله شدند و آنجا را فتح کردندو مائده ای را که بحضرت سلیمان علیه السلام نسبت میدادند در آن شهر بیافتند (نسبت مائده به آن حضرت مبنی بر طور و طریقه ٔ همیشگی است که هر چیز شگفت آور و هر ابزار ساخته شده ای را که دور از کار دست آدمی و دور از اندیشه ٔ عامه باشد به سلیمان نسبت دهند یا هر بنا و غوّاصی را بشیاطین مقهور به دست آن حضرت منسوب دارند). و این مائده مرکب و آمیخته از زر و سیم و گوهرنشان بود و در سه طوق (کذا) بار استر نهاده شده بود. آنگاه طارق یکی از پایه های مائده را باز کرده و پایه ای از آهن بجای آن نهاد تا موسی بن نصیر را مغلوب سازد. در یکی از شهرهای اندلس بخانه ای راه یافتند که بیست و چهار تاج از تاجهای پادشاهان اندلس در آنجا بودو هیچکس بهای یکی از آنها نتوانستی کردن، گویا برای نگاهداری یادگار هر پادشاهی تاج او را در آن خانه مینهاده اند تا شماره و تواریخ پادشاهی یکایک را بواجبی ضبط و نگاهداشته باشند. یا آنکه این عمل از جمله ٔ رسوم و آداب معموله ٔ مردم اسپانیا بوده است . و در سال <span class=\"hlight\" dir=\"rtl\">٩٢</span> موسی بن نصیر نزد ولیدبن عبدالملک شد و مائده ٔ معهود را برسم هدیه نزد وی نهاد، طارق گفت من بدین مائده دست یافتم نه موسی، لیکن رعایت حشمت را بدو واگذاشتم . ولید گفتار طارق را دروغ گمان برد، لیکن طارق بواسطه ٔ تصرفی که در پایه ٔ مائده کرده بود با اندیشه ٔ فارغ ولید را گفت از موسی تحقیق کند. موسی گفت من مائده را به همین حال به دست کردم، در آن وقت طارق پایه را بیرون کرد و بنمود، خلیفه بر صدق دعوی وی یقین کرد و وی را جایزه ای بخشید و موسی را دروغزن خواند. (الجماهر ص <span class=\"hlight\" dir=\"rtl\">٦٩</span> و <span class=\"hlight\" dir=\"rtl\">٧٠</span>). مؤلف الاعلام ولادت وی را به سال <span class=\"hlight\" dir=\"rtl\">٥٠</span> و وفات او را به سال <span class=\"hlight\" dir=\"rtl\">١٠٢</span> هَ . ق . دانسته و گوید: وی فاتح اندلس بود و اصل او از بربر است، بر دست موسی بن نصیر اسلام پذیرفت و از نیرومندترین مردان وی بشمار میرفت . چون موسی از فتح طنجه با پیروزی بازگشت طارق را به سال <span class=\"hlight\" dir=\"rtl\">٨٩</span> در طنجه والی گردانید و وی تا اوائل سال <span class=\"hlight\" dir=\"rtl\">٩٢</span> در طنجه اقامت گزید. موسی قریب دوازده هزار تن که بیشتر آنان بربر بودند برگزید و آنان را بفرماندهی طارق بمحاربه ٔ اندلس گسیل داشت . طارق لشکریان را از دریا بگذراند و بر کوهی که بعداً بنام خود اوشهرت یافت (جبل ُ الطّارق ) استیلا یافت و دژ قرطاجنه را بگشود و پس از سوزاندن کشتیهای حامل لشکریان اندلس و پیکار با «ردریک » پادشاه آنجا و کشته شدن وی، طارق نشیب و فراز زمین اندلس را درنوردید، تا اشبیلیه واستجه را نیز بگشود و کسانی را هم برای گرفتن قرطبه و مالقه روانه کرد، و سپس پایتخت اندلس «طلیطله » را تسخیر ساخت . آنگاه بقصد گشودن بلاد شمالی آن کشور، از وادی الحجارة و وادی دیگری که بعداً بنام فج طارق معروف گردید بگذشت، و بر چندین شهر دیگر از شهرهای اندلس که از آن جمله «مدینه ٔ سالم » بود استیلایافت و مائده ٔ حضرت سلیمان را در آن شهر به دست آورد و به سال <span class=\"hlight\" dir=\"rtl\">٩٣</span> به طلیطله بازگشت و با موسی بن نصیر درآنجا دیدار کرد، وی را از دور در رفتن بشهرها و ابرام در فتوحات و بی محابا درآمیختن با مردم ترسانده بود، موسی بن نصیر هم بتلافی این امر در این ملاقات طارق را از فرماندهی لشکر معزول ساخت . لکن ولیدبن عبدالملک میانه ٔ موسی و طارق را گرفت و بین ایشان آشتی افکند و بار دیگر طارق را بفرماندهی لشکر برگزید و طارق نیز به پیکار با اندلسیان ادامه داد و از شرق طلیطله تا سرچشمه ٔ نهر تاجه بالا رفت و در فتح سرقسطه ازموسی بن نصیر استعانت جست و آن شهر را به اتفاق یگدیگر گشودند. آنگاه طارق به شهرهای طرطوشة و بلنسیه و شاطبة و دانیة نیز قدم نهاد و در سال <span class=\"hlight\" dir=\"rtl\">٩٦</span> هَ . ق . بر حسب فرمان ولید به اتفاق موسی بن نصیر بشام رفت . فی الجمله اقوال مورخان در پایان کار طارق در کشور اندلس مضطرب بنظر می آید و ارجح آن است که پس از سال <span class=\"hlight\" dir=\"rtl\">٩٦</span> دیگر فرماندهی نیافت . (الاعلام ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٤٤١</span> - <span class=\"hlight\" dir=\"rtl\">٤٤٢</span>). درباره ٔ اصل و نسب طارق، احمد مقری آرد: طارق بن زیادبن عبداﷲ ایرانی، و از مردم همدان است و برخی گویند وی مولای موسی نبوده بلکه از مردم صدف بوده است و بقولی وی از موالی ایشان بشمار میرفته است ولی برخی از اعقاب او در اندلس ولاء موسی رانسبت به وی بشدت انکار میکنند و برخی هم گفته اند اوبربر و از مردم نفزة است . (نفح الطیب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٩</span>).<br /></font></div>'),
(174940, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص، اِ) ستاره ٔ صبح . ستاره ٔ بام . (مهذب الاسماء). ستاره ٔ روز.(شعوری ) (برهان ) (منتهی الارب ) (آنندراج ). بشب آینده . بعضی طارق زحل را گویند. <BR><font color=\"Blue\">◄</font> زن و شتر ماده ای که بحد اشتهای نر و شوهر رسیده باشند. <BR><font color=\"Blue\">◄</font> فال سنگک زننده . (منتهی الارب ). آنکه سنگ زند. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> حادثه ٔ شدید. <BR><font color=\"Blue\">◄</font> هر شی ٔ که بشب ظاهر شود. <BR><font color=\"Blue\">◄</font> کسی که بشب راه رود. از این باعث دزد و ساحر را نیز طارق گویند . (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> در. باب . <BR><font color=\"Blue\">◄</font> ستاره . کوکب . (برهان ). ج، طُرّاق . <BR><font color=\"Blue\">◄</font> (اِخ ) هشتاد و ششمین سوره ٔ از قرآن مجید، و آن مشتمل بر هفده آیه است و در مکه نازل شده است . و بدین آیت آغاز شود: والسماء والطارق . پس از سوره ٔ بروج و پیش از سوره ٔ اعلی .<br /></font></div>'),
(174941, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) موضعی است . (معجم البلدان ). <BR><font color=\"Blue\">◄</font> قریه ای است به افریقا.<br /></font></div>'),
(174942, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) کوه طارق به طبرستان . در عجائب المخلوقات و آثارالباقیه آمده که در آن کوه غاری است و در آنجا دکه ای که آن را دکه ٔ سلیمان خوانند و به برکت سلیمان آن را معظم دارند و اگر او را بقاذورات ملوث کنند، هوا متغیر شود و صاعقه و بارندگی آرد و تا آن راپاک نکنند فروننشیند. (نزهة القلوب چ لیدن ص <span class=\"hlight\" dir=\"rtl\">١٩٧</span>).<br /></font></div>'),
(174943, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) رجوع به ابومحارش شود.<br /></font></div>'),
(174944, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) غلام عبیداﷲ پسر زیاد. ابن عبدربه از ابن شبرمة القاضی نقل کرده گوید: ابن شبرمة گفت پیش از آنکه پدرم بر مسند قضا نشیند با او نشسته بودم . طارق غلام ابن زیاد بگذشت در حالی که والی بصره بود و گروهی از اشراف با او بودند. چون پدرم او را بدید آهی سرد از دل بر کشید و گفت :<br />اراها و اِن کانت تحب کأنها<br />سحائب صیف عن قریب تقشع.<br />سپس گفت : اللهم لی دینی و لهم دُنیاهم . پس از مدتی پدرم بقضاء برگزیده شد من بدو گفتم آیا آن روز طارق را یاد داری ؟ گفت جانان پدر.آنان جانشین پدر ترا خواهند یافت اما من ایشان را عوض و خلفی نمی یابم . ناچار پدرت نیز همان راهی را که آنان رفتند می پیماید و از ناز و نعمتی که آنان تمتع مییابند بهره میبرد. (عقد الفرید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span>).<br /></font></div>'),
(174945, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) نام پسر اُمیةبن عبدالشمس که بنات طارق که در عرب بحسن ضرب المثلند بدو منسوبند.<br /></font></div>'),
(174946, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) مولی عثمان بن عفان . کان امیراً علی المدینة. (منتهی الارب ). طارق نام پدرش عمرو است و غلام خلیفه ٔ سوم عثمان بن عفان بود.عبدالملک بن مروان او را والی مدینه کرد و پنج ماه در مدینه به امر ولایت اشتغال ورزید. خلیفه ٔ عصفری گوید: طارق در سال <span class=\"hlight\" dir=\"rtl\">٧٢</span> هَ . ق . بر مدینه غلبه کرد و مردم را به بیعت عبداﷲبن زبیر دعوت کرد هنگامی که مصعب بن الزبیر کشته شد و او طلحةبن عبداﷲبن عوف را که از جانب مصعب والی مدینه بود از مدینه بیرون کرد. و خلیفه طارق را در پایان سال <span class=\"hlight\" dir=\"rtl\">٧٣</span> معزول و حجاج بن یوسف را به ولایت مدینه منصوب کرد. ابن سعد گوید عبدالملک بن مروان، طارق بن عمرو را با ششهزار نفر گسیل داشت که ما بین ایله و وادی القری ساخلو و مراقب باشند که اگر لشکریان ابن زبیر بقصد هجوم بسوی مدینه با عمال عبدالملک قصد مبارزه و قتال کنند عمال مزبور را مدد باشندو یاری کنند. ابوبکربن ابی قیس که بر قسمتی از لشکریان ابی زبیر فرماندهی داشت طارق قصد او کرد و با او مبارزه درپیوست و بر او غالب آمد و او را بکشت . در این واقعه از ششصد تن یاران ابوبکربن ابی قیس گروهی کشته شدند آنقدر که از ایشان باقی ماند به اطراف پراکنده گردیدند. حارث بن حاطب نامه ای به عبداﷲبن زبیر فرستاد که عبدالملک بن مروان طارق را با گروهی بسیار فرستاده و اینک بین ایله و ذوخشب مشغول راهزنی و تاراج وغارت اموال و ستم بمردم میباشند چنانکه لشکری گران بمدینه فرستی باشد که مدینه از تاخت و تاز طارق و یارانش مصون ماند. و ابن زبیر پس از وصول این نامه مکتوبی به حارث بن عبداﷲبن ربیعه فرستاد که دو هزار تن بسرکردگی مردی آزموده بمدینه گسیل دار و او حارث بن رواس را با دو هزار مرد کاری بمدینه اعزام داشت . این جماعت چندی مدینه را از لشکریان شام محفوظ داشتند و مردم را از وجود آن جماعت آزاری نمی رسید و شهر مدینه گاهی در دست ابن زبیر و گاهی در تحت امر عبدالملک بن مروان میبود. بعبارة اخری هرگاه یکی از آندو بر دیگری چیره میشد و غلبه می یافت فرمانروائی مدینه او را مسلم بود. لیکن اکثر اوقات غلبه و چیرگی نصیب ابن زبیرمیشد. همین که ابن زبیر از کشته شدن ابوبکربن ابی قیس آگاه گردید، نامه ای به ابن رواس نوشت که با اصحاب و لشکریان خود بر طارق تاخت آرد و این معنی بر اهالی مدینه سخت گران آمد. طارق نیز از اندیشه ٔ ابن رواس و دستور ابن زبیر آگاه شد و یاران خود را برانگیخت وآماده ٔ کارزار شدند و بالاخره بین دو لشکر جنگی سخت درگرفت و در نتیجه طارق غالب آمد و به وادی القری بازگشت . ابن زبیر بوالی خود در مدینه فرمانی نوشت که برای دو هزار تن از اهل مدینه مرسوم بر قرار دارد تا در مواقع سخت برای دفاع از شهر مدینه موجبات تسهیل امر و ضمناً وسیله ٔ راحت و آسایش آنان مهیا و آماده باشد ولی نظر به آنکه مرسوم بمردمان نرسید آن را «فرض الریح » نام نهادند. حافظ و ابویعلی از سلیمان بن یسار روایت کرده اند: که طارق موقعی که والی مدینه بود عمری را برای وارث، حکم شرعی قرار داد و بروایت جابر انصاری از پیغمبر صلی اﷲ علیه و آله و سلم استناد کرد و جابر در حق طارق میگفت : در شگفتم از چند کار که همگی آنها شگفتی آور است . تعجب میکنم از کسی که ناخوش میداشت ولایت عثمان را و نسبت به او کینه میورزید تااو را کشتند و سپس دچار غلام او شدند که بر منبر رسول خدا بالا رفت و خطبه خواند در حالی که از صلحای پیشینیان ما نبود و از ناچاری اهالی مدینه فرمان او بردند. از ابوزرعة کیفیت حال طارق را در روایت حدیث پرسیدند. گفت ثقه است . (تهذیب ابن عساکر ج <span class=\"hlight\" dir=\"rtl\">٧</span> صص <span class=\"hlight\" dir=\"rtl\">٤٠</span>-<span class=\"hlight\" dir=\"rtl\">٤١</span>).<br /></font></div>'),
(174947, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) ابن اَشیم اشجعی . صحابی است . (منتهی الارب ). جدّ او مسعود. و خود وی پدر ابومالک اشجعی مجهول الاسم است . بگفته ٔ بغوی ساکن کوفه بود. مسلم گفته است که فقط راوی او پسر او میباشد و دو حدیث از او روایت کرده است . مؤلف الاصابة گوید یکی از آن دو حدیث را ابن ماجه در سنن خود ایراد و تصریح کرده است که طارق حدیث مزبور را بلاواسطه از حضرت پیغمبر صلی اﷲ علیه و آله و سلم شنیده است . در سنن ابن ماجه حدیث دیگری از ابومالک پسر صاحب ترجمه نقل شده که گوید: «یا ابت انک قد صلیّت الصبح خلف رسول اﷲ صلی اﷲ علیه و آله و سلم و ابی بکر و عمر و عثمان و علی هیهنا بالکوفة نحواً من خمسین سنة کانوا یقنتون قال یا بنی محدث ُ» ترمذی این حدیث را صحیح دانسته ولی خطیب آن را غریب شناخته و در کتاب قنوت گفته است درصحبت ابومالک نظر است . در اینجا مؤلف الاصابه گوید:ندانم بعد از تصریحی که در حدیث مزبور بصحبت ابومالک شده این نظر از چه روی است شاید آنچه را که ابن مندة از طریق ابی الولید از قاسم بن معن روایت کرده دیده است که گفته : از خانواده ٔ ابومالک اشجعی (مراد فرزندان و نواده های اوست ) پرسیدم که پدر شما از حضرت پیغمبر سماع حدیث کرده یا نه ؟ همگی گفتند: نی . و این جواب نفی پاسخی است که پیش از آن اثباتی وجود داشته . ومحتمل است که مراد از «پدر شما» ابومالک باشد و او هم مسلم است که سماع حدیث از پیمبر نکرده است . و مراد از صحابی بودن و سماع حدیث از پیمبر در این ترجمه شخص طارق اشجعی می باشد. (الاصابة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٠</span>) نام ابومالک پسر طارق بنا بگفتار ابن عبدالبر، سعد وراوی طارق ابومالک بود. و طارق را در عداد کوفیان آورده اند. طائفه ای هم او را صحابی گفته اند. (استیعاب ص <span class=\"hlight\" dir=\"rtl\">٢١٣</span>).<br /></font></div>'),
(174948, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) ابن باهیة. ابن عبدربه او را شاعری از بطن خزاعه میشمارد. (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٢</span>).<br /></font></div>'),
(174949, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) ابن شهاب بجلی . صحابی است . او را سماع است از آن حضرت صلی اﷲ علیه و آله و سلم، کم از دیگران است . (منتهی الارب ). مؤلف الاصابة نسب وی را بدین سان آورده است : طارق بن شهاب بن عبد شمس بن هلال بن عوف بن جشم بن عمروبن لوی بن رهم بن معاویةبن اسلم بن احمس البجلی الاحمسی . کنیت وی ابوعبداﷲ است و در سنی بشرف رؤیت با رسول (ص ) نائل آمده است که در زمره ٔ مردان کامل بوده است . برخی گفته اند وی از آن حضرت سماع حدیث نکرده . بغوی گوید: طارق بن شهاب بکوفه فرود آمد. ابن ابی حاتم گفته : از پدرم شنیدم که او را شرف صحبت با آن حضرت حاصل نشده و حدیثی راکه روایت کرده مرسل است، ازینرو من هم او را در زمره ٔ وحدان آوردم، بدان سبب که طارق خود گفته : بشرف زیارت آن حضرت مشرف شده ام . سپس گوید: اگر ثابت شود که او برؤیت آن حضرت نائل آمده است، پس بنابر قول راجح صحابی بودن وی مسلم خواهد بود و چون ثابت شود که وی را سماع از آن حضرت نبوده است روایت او از آن حضرت، حدیث مرسل یک تن صحابی محسوب میشود. و این نظر بنابر قول راجح مقبول است . نسائی چند حدیث از او تخریج کرده و این امر اثبات میکند که طارق درک صحبت کرده است . ابوداود فقط یک حدیث از وی تخریج کرده و گفته است طارق شرف رؤیت را دریافته ولی بشرف صحبت نائل نیامده است . و متن حدیث مزبور در باب غسل جمعه است، و حاکم حدیث مزبور را از طریق خود تخریج کرده و گفته است : عن طارق ابی موسی، ولی حاکم را درباره ٔ آن به خطا نسبت داده اند. ابوداود طیالسی گفته : خبر داد ما را شعبه، از قیس بن مسلم، از طارق بن شهاب که گفت : من رسول صلی اﷲ علیه و آله را زیارت کرده ام و در ایام خلافت ابی بکر هم در غزا و جهاد با کفار بوده ام، و این اسنادرا صحیح شمرده اند، و به همین اسناد هم گفته است : قدم وفد بجیلة علی النبی صلی اﷲ علیه و آله و سلم، فقال ابدأوا بالاحمسیین، و دعا لهم . علی بن المدینی گوید:طارق، برادر کثیربن شهاب است که از عمر روایت می کرده است . ولی صاحب «الاصابة» گوید: حدیث کردن طارق از صحابه در کتب صحاح سته آمده و از جمله ٔ صحابه ٔ مذکور خلفاء اربعه باشند. بغوی از طریق شعبه، از قیس بن مسلم، از طارق تخریج کرده که گفت : دیدم حضرت رسول صلی اﷲعلیه و آله را، و در خلافت ابی بکر در یکی از غزوات شرکت کرده ام . سماک، مخارق، علقمةبن مرثد، و اسماعیل بن ابی خالد نیز از طارق روایت کرده اند. طارق در سال <span class=\"hlight\" dir=\"rtl\">٨٢</span>یا <span class=\"hlight\" dir=\"rtl\">٨٣</span> یا <span class=\"hlight\" dir=\"rtl\">٨٤</span> از دنیا گذشته، و کسی که تاریخ وفات اورا بعد از صد هجرت دانسته خطا کرده است . ابن حبان تاریخ رحلت او را در سال <span class=\"hlight\" dir=\"rtl\">٨٣</span> قطعی شمرده است . (الاصابة ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٢٨١</span> - <span class=\"hlight\" dir=\"rtl\">٢٨٢</span>). ابن عساکر و ابن خلیل از طریق طارق روایت کرده اند که مردی از حضرت پیغمبر صلی اﷲ علیه و آله و سلم، در حالی که پای مبارک وی در رکاب بود، پرسید کدام یک از اقسام جهاد بر دیگر اقسام آن برتراست ؟ آن حضرت فرمود کلمة حق عند سلطان جائر. و نیز ابن عساکر از طریق بغوی روایت کند که آن حضرت فرمود بر شما باد شیر شتر و گاو، چو آنها شاخ و برگ و ریشه ٔ درختان را بتمامی بخایند و بخورند، ازینرو شیر آنان دوای هر دردی باشد. (تهذیب ابن عساکر ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span>).<br /></font></div>'),
(174950, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) ابن عبدالرحمن . تابعی و از اهل کوفه است . (منتهی الارب ).<br /></font></div>'),
(174951, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) ابن عبداﷲ محاربی . صحابی است . (منتهی الارب ). جامعبن شداد، و ربعی بن خراش از او روایت کرده اند. در شمار کوفیان است . (استیعاب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٣</span>).<br /></font></div>'),
(174952, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) ابن علقمةبن ابی رافع والد عبدالرحمن . بغوی گفته است وی در کوفه مسکن داشت . ابن مندة گوید در حدیث ابواسحاق او را ذکری است . و حدیثی مرفوع که در آن اختلاف شده از او روایت گردیده است . وی صحابی بوده است . (الاصابة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٢</span>).<br /></font></div>'),
(174953, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) ابن عمیرة. وی در یکی از ایام معروف عرب «یوم طخفة» اسب قابوس پسر نعمان بن منذر را با تیر بزد و آن راپی کرد. خواست موی پیشانی قابوس را هم بسترد، قابوس گفت ستردن موی پیشانی پادشاهان نه سزاست . طارق دست از این اندیشه بازداشت و ساز سفر او را آماده کرد و بنزد پدرش روانه ساخت . (عقدالفرید چ مصرج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٨٧</span>).<br /></font></div>'),
(174954, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) ابن عوف . مؤلف عقدالفرید نام او را ذیل عنوان (یوم غول الثانی ) یکی از ایام معروف عرب آورده و گوید دو پسر هجیمة در ضمن عده ای از لشکریان، به قبیله ٔ بنی یربوع فرود آمدند و به زنهار طارق بن عوف درآمدند، با وی بموضعی که آبی معروف به کهنل در آنجا بود، رحل اقامت افکندند. (عقدالفرید چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span>ص <span class=\"hlight\" dir=\"rtl\">٩١</span>).<br /></font></div>'),
(174955, 'طارق', '<span class=\"hlight\">طارق .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) ابن المبارک . عتبی از او نقل کند. رجوع به عقدالفرید چ مصر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥</span> شود.<br /></font></div>'),
(174956, 'طارقچی', '<span class=\"hlight\">طارقچی .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) طایفه ٔ مغول به زبان اهل خراسان . (فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>). منظور از زبان خراسان ظاهراً زبان سکنه ٔ صحرای ترکمان و اراضی ترکمان نشین باشد.<br /></font></div>'),
(174957, 'طارقیة', '<span class=\"hlight\">طارقیة.</span> <font color=\"DarkGreen\"><b>[ رِ قی ی َ ]</font></b> (ع اِ) گردن بندی است . (منتهی الارب ). نوعی از گردن بند. ضرب من القلادة. (تاج العروس ).<br /></font></div>'),
(174958, 'طارم', '<span class=\"hlight\">طارم .</span> <font color=\"DarkGreen\"><b>[رَ ]</font></b> (اِخ ) ناحیه ٔ طارم میانه ٔ مشرق و جنوب فرک . درازی آن از قریه ٔ سرچاهان تا قریه ٔ تاشکت دوازده فرسنگ، پهنای آن از سه فرسنگ نگذرد، محدود است از جانب مشرق بناحیه ٔ فارغان و از شمال بناحیه ٔ خشن آباد و از سمت مغرب بناحیه ٔ فرک . هوا و آبش بسی گرم و ناگوار، محصولش گندم و جو و شلتوک و پنبه و کنجد، آبش از رودخانه و چشمه و قنات، نخلستان بسیاری داشته، اکنون کمتر شده . هر کس از آبهای جاری این ناحیه بیاشامد، به اندک زمانی مستسقی گردد، گذران اهلش از آب برکه بارانی است و انواع شکارها در این ناحیه باشد. و مرغ دراج از همه بیشتر است، قصبه ٔ این ناحیه را نیز طارم گویند، شصت و هفت فرسنگ از شیراز و دوازده فرسنگ مشرقی فرک است و نزدیک بچهار صد درب خانه از خشت خام و گل و چینه داشته است و این ناحیه مشتمل بر پانزده قریه است . (فارسنامه ٔ ناصری ). حمداﷲ مستوفی گوید: طارم وبرک دو شهرک اند و برک بزرگتر است، قلعه ای محکم داردو بسر حد کرمان است، حاصلش غله و خرما فراوان بود. (نزهة القلوب چ لیدن ص <span class=\"hlight\" dir=\"rtl\">١٣٨</span> ذیل خطبه ٔ شبانکاره ). طول طارم <span class=\"hlight\" dir=\"rtl\">٧٢</span> و عرض <span class=\"hlight\" dir=\"rtl\">١٨</span> هزار گز، از شمال محدود است به خشن آباد و از جنوب و مشرق بفارغان . آب و هوای آن گرم وناسالم . زمینها باتلاقی و مشجر و دارای محصولات غلات وبرنج و خرما و پنبه، و آب مشروب اهالی از آب باران است . مرکز آن طارم (<span class=\"hlight\" dir=\"rtl\">٥٠٠</span> خانوار) و دارای <span class=\"hlight\" dir=\"rtl\">١٤</span> قریه میباشد. (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٢٣٩</span>). رجوع به کتاب تاریخ مغول عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">٣٨٠</span> و <span class=\"hlight\" dir=\"rtl\">٤١٩</span> شود. نام قلعه ای است در لار فارس نزدیک بندر عباس . (گلشن مراد غفاری ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(174959, 'طارم', '<span class=\"hlight\">طارم .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (معرب، اِ) محجری را گویند که از چوب سازند و اطراف باغ و باغچه بجهت منع از دخول مردم نصب کنند. (برهان ). چوب بست گرد باغ و باغچه .محجری که از چوب سازند و به اطراف باغ نهند تا مانعاز دخول شود. (غیاث اللغات ). نرده . <BR><font color=\"Blue\">◄</font> چوب بندی که از برای انگور و یاسمین و کدوی صراحی کنند و داربست و طارم انگور و داربند هم گویند. این لفظ معرب تارم است و در مصطلحات گفته در حرکت راء طارم اختلاف است، بعضی مفتوح و بعضی مضموم آرند <span class=\"hlight\">:</span> <br />بعون نعمت عشق تو فارغم ز نعیم <br />نه جوی شیر شناسم نه طارم انگور.<br />ثناها همه ایزد پاک را<br />ثریاده طارم تاک را.<br /> <font color=\"Red\">نورالدین ظهوری </font><br />مست ترا بطارم تاک است دیده باز<br />مستغنی از تفرّج این سبز طارم است .<br /> <font color=\"Red\">نورالدین ظهوری .</font><br />و این بیت سالک قزوینی که در مدح جلال اسیر گفته بکسر راء نیز متحقق میشود <span class=\"hlight\">:</span> <br />سیاره ٔ این بلند طارم <br />خوانند ورا ابوالمکارم .<br /> <font color=\"Red\">(از آنندراج ).</font><br />و ضبطت الکلمة فی اللسان و غیره بکسر الراء، و هو الموافق للوزن العربی، و ضبطت فی المعیار و عند ادی شیر، بسکونها و قال الاول (معرب طارم ) یعنی بضم الراء. و قال الثانی معرب عن تارم و لم یضبط الراء. و الظاهر ان ما قاله المعیار اصح، ولکن مع فتح الراء فان فی ترجمة البرهان القاطع ص <span class=\"hlight\" dir=\"rtl\">٤١٢</span> طارم بوزن آدم و معناه مقارب للمعنی الذی هنا و اما تارم بالتاء فانه بفتح الراء ایضاً. (حاشیه ٔ المعرب ص <span class=\"hlight\" dir=\"rtl\">٢٢٤</span>). طارمه . طارمی . <BR><font color=\"Blue\">◄</font> بام خانه . (برهان ). <BR><font color=\"Blue\">◄</font> طاق خانه . (اوبهی ). <BR><font color=\"Blue\">◄</font> خانه ٔ بالا. (بحرالجواهر). <BR><font color=\"Blue\">◄</font> دیدگاه . (اوبهی ) <span class=\"hlight\">:</span> <br />بنشان بطارم اندر مر ترک خویش را<br />با چنگ سغدیانه و با یالغ و کدو.<br /> <font color=\"Red\">عماره .</font><br />زمین ز مرد شود تنگ چون کهن بیشه <br />هوا ز گرد شود تیره چون سیه طارم .<br /> <font color=\"Red\">فرخی .</font><br />لاجرم دشمنان به زندانند<br />خواجه شادان بطارم و گلشن .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> خانه را گویند که از چوب سازند همچو خرگاه و غیره . خانه ٔ چوبین . و به معنی گنبد نیز آمده است . (برهان ). و در بهار عجم آمده خانه ٔ چوبین . چون خرگاه و سراپرده و گنبد. (غیاث اللغات ). خرگاه . (زمخشری ). قبّه . (برهان ) <span class=\"hlight\">:</span> <br />هر آن روزی که بنشستی به طارم <br />بطارم در تو بودی باغ خرم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />کنار بام وی را کاخ و طارم <br />زمین پر گل او را خزّ و ملحم .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />خوشا راها که باشد راه آنان <br />که داند از سفر هنجار جانان <br />اگر چه صعب راهی پیش دارند<br />مر آن را طارم و گلشن شمارند.<br /> <font color=\"Red\">(ویس و رامین ).</font><br />چو رامین آمد از گرگان سوی مرو<br />تهی بد باغ شادیش از گل و سرو<br />نه گلگون دید طارم را زرویش <br />نه مشکین دید ایوان را ز بویش .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />نه با غم خوش بود نه کاخ و میدان <br />نه طارم نه شبستان و نه ایوان <br />کجا جویم ترا ای ماه تابان <br />بطارم یا بگلشن یا به ایوان <br />هر آن روزی که بنشستی به ایوان <br />بایوان درتو بودی ماه و کیوان .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />روز آدینه هرون بطارم آمد، و بونصر سوگندنامه نبشته بود عرض کرد، هرون بر زبان راند، و اعیان و بزرگان گواه شدند. (تاریخ بیهقی ). حاجب غازی که بطارم آمدی بر ایشان گذشتی، و ناچار همگان بر پای خاستندی . (تاریخ بیهقی ). امیر بر خضرا رفت و خواجه بطارم دیوان بنشست . (تاریخ بیهقی ). خواجه به طارم رفت و جمله خواجه شماران و اعیان . (تاریخ بیهقی ). خواجه گفت اگر رأی عالی بیند، تا بنده بطارم نشیند و پیغامی که دارد بزبان معتمدی به مجلس عالی فرستد. (تاریخ بیهقی ). این روز که صدوردیوان و دبیران بر این جمله بنشستند، وی در طارم آمد، و بر دست راست خواجه بونصر بنشست در نیمترک، چنانکه در میانه ٔ هر دو مهتر افتاد در پیش طارم، و کار راندن بگرفت . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span>). مردمان که طاهر را دیده بودند پیش بونصر ایستاده و در وکالت دراین پادشاه <font color=\"DarkGreen\"><b>[ مسعود ]</font></b> و طارم سرای بیرون . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span>). بونصر هم آنجا که بروزگار گذشته نشستی، بر چپ طارم که روشنتر بود بنشست . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span>). و اسبش <font color=\"DarkGreen\"><b>[ حاجب غازی ]</font></b> در سرای بیرونی ببلخ آوردندی چنانکه روزگار گذشته از آن امیر مسعود و محمد و یوسف بودی، و در طارم دیوان نشستی، آنگاه که بار دادندی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>). علی دایه، و خویشاوندان، و سالاران محتشم، درون این سرای دکانی بود سخت دراز، پیش از بار <font color=\"DarkGreen\"><b>[ مسعود ]</font></b> آنجا بنشستندی، و حاجب غازی که بطارم آمدی بر ایشان گذشتی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>). و دیگر روز خواجه <font color=\"DarkGreen\"><b>[ احمد حسن ]</font></b> بیامد، و چون بار بگسست بطارم آمد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٤٩</span>). چون پیدا آمد <font color=\"DarkGreen\"><b>[ مسعود ]</font></b> خدمت کردند، بدر طارم رسیده بود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٥٨</span>). امیر <font color=\"DarkGreen\"><b>[ مسعود ]</font></b> بر خضرا رفت، و خواجه به طارم دیوان بنشست خالی، و استادم را بخواند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>). یکروز خواجه احمد حسن از بار چون باز خواست گشتن، امیر <font color=\"DarkGreen\"><b>[ مسعود ]</font></b> گفت که خواجه تنها بطارم بنشیند که بسوی او پیغامی است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span>). سلطان <font color=\"DarkGreen\"><b>[ مسعود ]</font></b> خواجه را گفت بطارم باید نشست که حسنک را آنجا خواهند آورد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span>). والی حرس با وی و علی رایض و بسیار پیاده از هر دستی وی را <font color=\"DarkGreen\"><b>[حسنک ]</font></b> بطارم بردند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span>). من که بوالفضلم و قومی بیرون طارم بدکان ها بودیم نشسته در انتظار حسنک . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span>). بطارم رفت <font color=\"DarkGreen\"><b>[ خواجه احمد حسن ]</font></b> . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span>). چون نان بخوردند برخاستند و بطارم دیوان بازآمدند و بنشستند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٣</span>). چون به درگاه رسید، بکتکین حاجب پیش او <font color=\"DarkGreen\"><b>[ اریارق ]</font></b> باز شد، و امیر حرس او را فرود آوردند و پیش وی رفتند تا طارم، و آنجا بنشاندند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٦</span>). پس بازگشتند هر دو خواجه با وی <font color=\"DarkGreen\"><b>[ غازی ]</font></b>به طارم نشستند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span>). خواجه به طارم آمد و خواجه بونصر را بخواند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٥٨</span>). گفت بطارم روم پیغام دهم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٥٨</span>). بونصر بطارم بازآمد و آنچه گفته بود شرح کرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٦٠</span>). و سلطان و خواجه ٔ بزرگ و بونصر، صاحب دیوان رسالت خالی کردند و احمد را بخواندند، و مثالهااز لفظ عالی بشنود، و از آنجا بطارم آمدند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٧٠</span>). امیر فرمود تا وی را به طارم نزدیک صفه بنشاندند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٨٥</span>). خواجه گفت نیک آمدو بازگشت، و به طارم دیوان رسالت بنشستند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٩٦</span>). روز آدینه هارون بطارم آمد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٦١</span>). به طارم که میان باغ بود بنشستند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٧٢</span>).<br />از بهر چه این کبود طارم <br />پر گرد شده ست باز و مقتم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />در این فیروزه گون طارم مجوی آرام و آسایش <br />که نارامد همی روز و شب و ناساید این طارم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />این قبه ٔ پرچشمهای بیدار<br />زین طارم پر شمعهای رخشان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />رازیست که می بگفت خواهد<br />با تیره بساط سبز طارم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تودر خز و بز بزیر طارم <br />خویشانت برهنه و پریشان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بر طارم هوای دل خود نشاط کن <br />با مهوشی که قبله ٔ ایوان و طارم است .<br /> <font color=\"Red\">سوزنی .</font><br />جاوید زی به لهو و دمی بی طرب مباش <br />کز غم عدوی جاه ترا عمر یکدم است .<br /> <font color=\"Red\">سوزنی .</font><br />از عکس و لمع انجم رخشنده هر شبی <br />تا آسمان بگونه ٔ پیروزه طارم است .<br /> <font color=\"Red\">سوزنی .</font><br />ایوان تو ز طارم فیروزه ٔ فلک <br />بگذشت از آنکه صاحب ایوان و طارمی .<br /> <font color=\"Red\">سوزنی .</font><br />ای بسا باد و کبر طارم و تیم <br />زیر و بالا به آب چشم یتیم .<br /> <font color=\"Red\">سنائی .</font><br />چو در نی بست تن ایمن نشستی <br />ز دل در جان جانت طارمی کو.<br /> <font color=\"Red\">سنائی .</font><br />ای برسم دولت از آغاز دوران داشته <br />طارم قدر ترا هندی و هفتم چرخ پاس .<br /> <font color=\"Red\">انوری .</font><br />پیش مسند سلطان طارمی زده . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٣٤</span>).<br />نقل است که یک شب هرون الرشید فضل برمکی را که یکی از مقربان بود گفت که امشب مرا برمردی بر، که مرا بمن نماید که دلم از طاق و طارم درتنگ آمده است . (تذکرة الاولیاء).<br />بیا که رایت سلطان شهنشه عالم <br />گذشت از فلک چارطاق و نه طارم .<br /> <font color=\"Red\">بدر جاجرمی .</font><br />چه میخواهم از طارم افراشتن <br />همینم بس از بهر بگذاشتن .<br /> <font color=\"Red\">سعدی .</font><br />گهی برطارم اعلی نشینم <br />گهی درپیش پای خود نبینم .<br /><font color=\"Red\">سعدی (گلستان چ یوسفی ص <span class=\"hlight\" dir=\"rtl\">٩٠</span>).</font><br /></font></div>'),
(174960, 'طارم', '<span class=\"hlight\">طارم .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) یکی از اجداد ایسن قتلغ از امراء عصر سلطان محمد خدابنده . (ذیل جامع التواریخ حافظ ابرو ص <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(174961, 'طارم', '<span class=\"hlight\">طارم .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) (... رود) ظاهراً رودیست که از طارم علیا (تابع زنجان ) میگذرد. در حبیب السیر آمده <span class=\"hlight\">:</span> مرکب همایون پادشاه ربع مسکون از ده ِ سلطانیه به طارم رود و از آنجا بطریق فومن متوجه امیره ٔ دباج شود. (حبیب السیر چ تهران جزو <span class=\"hlight\" dir=\"rtl\">٤</span> از ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٤</span>).<br /></font></div>'),
(174962, 'طارم', '<span class=\"hlight\">طارم .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) یاقوت این کلمه را بدین صورت آورده (طرم ) گوید ناحیه ای است بزرگ در کوههای مشرف بر قزوین طرف بلاد دیلم . آن ناحیه را دیده ام . اراضی و دیه هایی کوهستانی در آن ناحیت یافتم که به اندازه ٔ فرسنگی هم در آن دشت هموار یافت نمیشود. با اینحال زمین این ناحیت گیاهناک و پر آب ودارای دیهای فراوان است . اهالی، آن ناحیت را در زبان بومی خود «ترم » تلفظ کنند. و شاید پنبه ای که بنرمی موصوف است منسوب به یکی از این دو موضع باشد و در این ناحیت بین وهسودان و رکن الدوله ٔ دیلمی محاربه واقع شد و شکست نصیب وهسودان گردید. (معجم البلدان ). حمداﷲ مستوفی گفته طارمین ولایت گرمسیر است بر شمال سلطانیه بر یک روزه راه . و در او ارتفاعات بسیار نیکو باشد و اکثر میوه ٔ سلطانیه از آنجاست . در اول آنجا شهری فیروزآباد نام به زمین طارم سفلی دارالملک بود. اکنون بکلی خراب است . و قصبه ٔ «اندر» به طارم علیا شهرستان آنجا شده . طول آن از جزائر خالدات . فد. و عرض از خط استوا. لومه . مردم آن ولایت سنی شافعی مذهبند. وآن ولایت پنج عمل است : اول طارم علیا، از توابع قلعه تاج بوده است . قریب صد پاره دیه است، و جزلا، شورزد، درام، حیات، قلات، رزید، و شید از معظم قرای آن است . دوم به طارم سفلی، توابع قلعه ٔ شمیران پنجاه پاره دیه و مزرعه بوده است، الون، خورنق، شرز، رلرد و کلچ از معظمات آن است . سوم هم بطارم سفلی، توابع قلعه ٔ فردوس بیست پاره دیه است، و سروان معظم آن . چهارم، نسبار و بریدون . بریدون دودیه معتبر است . و هشت دیه دیگر از توابع آن . پنجم دزآباد سفلی بیست و پنج پاره دیه است . و گلهار و گلچین و بلهل از معظمات آن . حقوق دیوانی آن ولایت با باغات قلات وارد و هیکل شش تومان و چهار هزار دینار است . (نزهة القلوب مقاله ثالثه ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>). صاحب «مرآت البلدان » گوید: طارم اسم دو بلوک است یکی موسوم بطارم علیا و دیگری از بلوکات خمسه است و آن را طارم سفلی گویند...این دو بلوک مشتمل بر پنجاه پارچه قریه ٔ کوچک و بزرگ است و حدودش متصل به ولایت قزوین و گیلان و خمسه است و غالب این بلوک کوهستان است و قرای معتبر آن : سروان، ارکن، نیارک، کلج، سیاه پوش، حصار و آلتین کش است . رودخانه ٔ قزل اوزن از مقابل این قری میگذرد، گویند در ته این رود گاهی طلا یافت شده و اسم قریه و رودخانه به ترکی دلالت بر وجود طلا دارد در قریه ٔ ارکن چهار کاج است که بسیار با عظمت و بزرگ می باشد. از نواب مستطاب والا اعتضادالسلطنه شنیده شد یکی از آنها که اعظم است محیط تنه ٔ درخت نه ذرع وبا ارتفاع زیادی که میزان آن محقق نشده است میباشد و آن سه دیگر قدری با او تفاوت دارد. میرزا طاهر دیباچه نگار در سال <span class=\"hlight\" dir=\"rtl\">١٢٦٧</span> هَ . ق . در خدمت نواب مستطاب والا وزیر علوم و معادن بطارم رفته قطعه ای در عجایب آن گفته است که این دو شعر از آن قطعه است <span class=\"hlight\">:</span> <br />بود ماننده ٔ سرو کشمر<br />چار کاجی که به ارکن دیدم <br />همچو پیوستن دجله بفرات <br />شاه رود و قزل اوزن دیدم .<br />و قریه ٔ کلّج که اهالی طارم کله گویند و غالباً در اسماء پارسی در السنه ٔ اهل این زمان هاء بجیم مبدل میشود نزدیک به اتصال این دو رود است و بعد از اتصال موسوم به سفیدرود می شود. مثل اینکه بعد از اتصال دجله بفرات در قرنه موسوم بشطالعرب میگردد و در قریه ٔ سروان معدن زاج سفید هست که به فارسی زاک و به یونانی قلقدیس مینامند و زاج الاساکفه نیز از این جنس است و این غیر زاج زاجکان قزوین میباشد و زاجکان را نیز راکان میگویند... و در دو قریه ٔ دیگر حسن آباد و مشکین آباد نیز معدن زاج است و طارم معادن بسیار از قبیل مس و سرب و غیره دارد و طلق زیاد بقدر صفحه ای نزدیک کلج یافت میشود که ممکن است به درها و پنجره ها بگذارند و چندین جنگل و بیشه دارد... و نیز رجوع به همان کتاب ذیل تارم شود. کیهان در جغرافیای خود آورده : در ایران چندین نقطه به اسم طارم معروف است که همه کوهستانی میباشند، در این ناحیه (قزوین ) نیز دو طارم است که یکی طارم علیا و جزء خمسه و دیگری طارم سفلی که جزء قزوین محسوب میشود. بلوک طارم سفلی در شمال غربی قزوین و جنوب منجیل واقعشده و اراضی آن حاصل خیز و زراعت آن دیمی و از آب چشمه مشروب میشود، محصولش گندم و جو و شغل اهالی گله داری است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٣٧٣</span>). کیهان بلوک طارم علیا را ذیل ناحیه ٔ زنجان بعنوان طارمات آورده گوید: در شمال زنجان و در اطراف دره ٔ سفیدرود واقع شده، آب و هوای آن گرمتر از زنجان و محصولات آن گرمسیری و دارای <span class=\"hlight\" dir=\"rtl\">١٠٤</span> قریه میباشد. (ص <span class=\"hlight\" dir=\"rtl\">٣٧٨</span>). از حیوانات گربه ٔباتلاقی در نواحی طارم و گیلان و مازندران یافت میشود. معدن سرب در مزرعه ٔ شاه نگاه طارم سفلی از توابع قزوین یافت میشود. (جغرافی اقتصادی کیهان ص <span class=\"hlight\" dir=\"rtl\">٢٧</span> و <span class=\"hlight\" dir=\"rtl\">٤٣</span>). در بلاکوه نزدیک طارم کوره ای مهیا شده که از ورقه های بزرگ سولفور دوپلمب خالص که در سنگ آهک یافت میشود بطور امتحان سرب بعمل می آوردند. در رودبار و طارم رگه های زغال سنگ نسبةً اعلی موجود میباشد. (جغرافیای اقتصادی کیهان ص <span class=\"hlight\" dir=\"rtl\">٥٣</span> و <span class=\"hlight\" dir=\"rtl\">٢٣٠</span>). رجوع به تاریخ مغول اقبال ص <span class=\"hlight\" dir=\"rtl\">٣٩</span> و <span class=\"hlight\" dir=\"rtl\">٥٢٣</span> شود.<br /></font></div>'),
(174963, 'طارم اخضر', '<span class=\"hlight\">طارم اخضر.</span> <font color=\"DarkGreen\"><b>[ رَ م ِ اَ ض َ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از آسمان است . (برهان ). آسمان <span class=\"hlight\">:</span> <br />نیست جای پرفشانی چار دیوار قفس <br />مانده ای در تنگنای طارم اخضر چرا؟<br /><font color=\"Red\">صائب .</font><br /></font></div>'),
(174964, 'طارم اعلی', '<span class=\"hlight\">طارم اعلی .</span> <font color=\"DarkGreen\"><b>[ رَ م ِ اَ لا ]</font></b> (ترکیب وصفی، اِ مرکب ) آسمان . فلک . چرخ <span class=\"hlight\">:</span> <br />گهی بر طارم اعلی نشینم <br />گهی در پیش پای خود نبینم .<br /><font color=\"Red\">سعدی (گلستان چ یوسفی ص <span class=\"hlight\" dir=\"rtl\">٩٠</span>).</font><br /></font></div>'),
(174965, 'طارم فیروزه', '<span class=\"hlight\">طارم فیروزه .</span> <font color=\"DarkGreen\"><b>[ رَ م ِ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ترکیب وصفی، اِ مرکب ) به معنی طارم اخضر است که کنایه از آسمان باشد. (برهان ) <span class=\"hlight\">:</span> <br />خرامید بر تخت فیروزه بختی <br />چو خورشید بر تخت فیروزه طارم .<br /> <font color=\"Red\">؟ (از جهانگشای جوینی ).</font><br />بجز آن نرگس مستانه که چشمش مرساد<br />زیر این طارم فیروزه کسی خوش ننشست .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(174966, 'طارم نیلگون', '<span class=\"hlight\">طارم نیلگون .</span> <font color=\"DarkGreen\"><b>[ رَ م ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) به معنی طارم فیروزه است که کنایه از آسمان باشد. (برهان ). رجوع به طارم اخضر و طارم فیروزه شود.<br /></font></div>'),
(174967, 'طارم چارم', '<span class=\"hlight\">طارم چارم .</span> <font color=\"DarkGreen\"><b>[ رَ م ِ رُ ]</font></b> (ترکیب وصفی، اِ مرکب ) طارم چهارم . فلک چارم . فلک چهارم .<br /></font></div>'),
(174968, 'طارمات', '<span class=\"hlight\">طارمات .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) ناحیه ٔ طارم .<br /></font></div>'),
(174969, 'طارمات', '<span class=\"hlight\">طارمات .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (ع اِ) طارمة. رجوع به طارمة شود.<br /></font></div>'),
(174970, 'طارمة', '<span class=\"hlight\">طارمة.</span> <font color=\"DarkGreen\"><b>[ رَ م َ ]</font></b>(معرب، اِ) خانه ٔ از چوب . معرّب تارم . (منتهی الارب ). خانه ٔ چوبین چون قبه . ج، طارمات . (دستوراللغه ٔ ادیب نطنزی ). بیت من خشب . فارسی معرب، نقله الجوهری، و زاد الازهری : کالقبة. (تاج العروس ). خانه ٔ از چوب چون گنبدی . (زمخشری ). <BR><font color=\"Blue\">◄</font> هر بناء گرد. (زمخشری ). <BR><font color=\"Blue\">◄</font> خرگاه . ج، طوارم . (مهذب الاسماء).<br /></font></div>'),
(174971, 'طارمی', '<span class=\"hlight\">طارمی .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) نرده . پکوک . <BR><font color=\"Blue\">◄</font> دست انداز. ستن آوند. رجوع به طارم شود.<br /></font></div>'),
(174972, 'طارمی', '<span class=\"hlight\">طارمی .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) میردوست از شعرای طارم بوده دوازده سال بمجاورت و خدمت روضه ٔ رضویه اشتغال داشته و همایون پادشاه وی را از هواخواهان خویش میشمرده است . این شعر بدو منسوب است :<br />چاکها کز دست عشقش در گریبان من است <br />هر طرف راهیست کز جانان سوی جان من است .<br /><font color=\"Red\">(از صبح گلشن ص <span class=\"hlight\" dir=\"rtl\">٢٦٠</span>).</font><br /></font></div>'),
(174973, 'طارنة', '<span class=\"hlight\">طارنة.</span> <font color=\"DarkGreen\"><b>[ رِ ن َ ]</font></b> (اِخ ) محلی است به مصر. (ابن البیطار در شرح کلمه ٔ جثجاث ).<br /></font></div>'),
(174974, 'طارنت', '<span class=\"hlight\">طارنت .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) شهری است در صقلیه . (معجم البلدان ). <BR><font color=\"Blue\">◄</font> شهری بجنوب ایتالیا، در ساحل خلیجی به همین نام که از بحر ایونی در سرزمین اُترانت تشکیل شده، دارای <span class=\"hlight\" dir=\"rtl\">٧٢٠٠٠</span> تن سکنه است . و رجوع به طارنطا و طارنطینی شود.<br /></font></div>'),
(174975, 'طارنطا', '<span class=\"hlight\">طارنطا.</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) طارنت . رجوع به طارنت شود. فیثاغورس حکیم، از آن پس که قولون، یکی از ثروتمندان مردم را بر ضد او بشورانید، به طارنطا فرار کرد. (از عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠</span>).<br /></font></div>'),
(174976, 'طارنطینی', '<span class=\"hlight\">طارنطینی .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) طارنت . طارنطا. از بلاد یونان و مسقطالرأس ارخوطس، یکی از حکماء شاگرد افلاطون . (قفطی ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>).<br /></font></div>'),
(174977, 'طارنوس', '<span class=\"hlight\">طارنوس .</span> (اِخ ) خواندمیر بنقل از روضةالصفا گوید: که جان موسوم به طارنوس بوده و اولاد و اعقاب او مادام که اوامر و نواهی الهی را مطیع و منقاد بودند در غایت رفاهیت روزگار میگذرانیدند و چون یک دور ثوابت نزدیک به انتها رسید، و مدّت یک دور ثوابت نزد حکماء اوایل، سی و ششهزار سال است و ابن الاعلم مدت آن را بیست وپنجهزارودویست سال یافته و محی الدین مغربی که قول او نزد علمای متأخرین حجت است بیست وچهارهزار سال گفته، آن جماعت تقریباً آغازعصیان و طغیان کرده منتقم جبار بعد از الزام حجت اکثر ارباب معصیت را به دارالبوار فرستاد، و بقیه ٔ ایشان را که ربقه ٔ اطاعت در رقبه داشتند بتجدید شریعتی عطا فرمود. (حبیب السیر چ <span class=\"hlight\" dir=\"rtl\">١</span> تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> جزو <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(174978, 'طارونی', '<span class=\"hlight\">طارونی .</span> (ص نسبی، اِ) نوعی ازجامه ٔ ابریشمی . (منتهی الارب ). قسمی خز <span class=\"hlight\">:</span> <br />مردم ز علم و فضل شرف یابد<br />نز سیم و زر و از خز طارونی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و ظاهراً طارونی یا خزّ طارونی ادکن اللون وناعم الملمس بوده است . رجوع به کلمه ٔ خلاف در ابن البیطار شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گنبد طارونی </span> ؛ کنایه از آسمان <span class=\"hlight\">:</span> <br />ای گرد گرد گنبد طارونی <br />یکبارگی بدین عجبی چونی .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(174979, 'طارکیس', '<span class=\"hlight\">طارکیس .</span> (اِ) علک البطم . آن را حبّة الخضراء نیز نامند. طارسیس . رجوع به طارسیس شود.<br /></font></div>'),
(174980, 'طاری', '<span class=\"hlight\">طاری .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) درختی است هندی که چون او را زخم کنند آب بسیار از آن تراوش میکند. و از آن خمر و سرکه میسازند و مشهور بشراب طاری است و در افعال و خواص قریب است بشراب مویزی . (تحفه ٔ حکیم مؤمن ). اطواق است و آن خمری است که از آب درختی که به هندی طاری نامند بعمل می آورند و آن را هری گویند و درخت آن به افراط در عظیم آباد و بنگاله هست و در بعضی جاها کمتر است . (فهرست مخزن الادویه ).<br /></font></div>'),
(174981, 'طاری', '<span class=\"hlight\">طاری ٔ.</span> <font color=\"DarkGreen\"><b>[ رِءْ ]</font></b> (ع ص ) آینده . <BR><font color=\"Blue\">◄</font> ناگاه درآینده . (منتهی الارب ). ظاهر شونده بر کسی ناگاه . فرودآینده از جائی . (غیاث اللغات ). ج، طُرّاء و طُرَاء . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ناگاه روی داده . عارض و ظاهر شونده <span class=\"hlight\">:</span> و این آوازه در اطراف گیتی طاری و به اکناف جهان ساری گشت . (جهانگشای جوینی ).<br /></font></div>'),
(174982, 'طاری شدن', '<span class=\"hlight\">طاری شدن .</span> <font color=\"DarkGreen\"><b>[ ش ُ دَ ]</font></b> (مص مرکب ) آمدن از جائی که ندانند. <BR><font color=\"Blue\">◄</font> آمدن از دور.<br /></font></div>'),
(174983, 'طاریة', '<span class=\"hlight\">طاریة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص، اِ) تأنیث طاری . به معنی داهیة است . (منتهی الارب ). داهیه و بلا و آسیب سخت . و رجوع به آفت شود.<br /></font></div>'),
(174984, 'طاریقه', '<span class=\"hlight\">طاریقه .</span> <font color=\"DarkGreen\"><b>[ ق َ ]</font></b> (ع اِ)وند. (فهرست مخزن الادویه ). دانه ای است شبیه به بیدانجیر که کرچک هندی و باتو و بتازی حَب السلاطین نیز گویند. (فرهنگ ناظم الاطباء). رجوع به کرچک هندی شود. به یونانی تخمی است که آن را به عربی، حَب الخطائی و حَب السلاطین خوانند و بشیرازی باتو گویند. (برهان ).<br /></font></div>'),
(174985, 'طازج', '<span class=\"hlight\">طازج .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (معرب، ص ) تازه . معرب است . (منتهی الارب ). سخن راست و نیکو و پاکیزه . (منتهی الارب ) (قطر المحیط). <BR><font color=\"Blue\">◄</font> خالص از هر چیزی . (منتهی الارب ).<br /></font></div>'),
(174986, 'طاس', '<span class=\"hlight\">طاس .</span> (اِ) در اصل فارسی تاس است، فارسی زبانان عربی دان به طاء نویسند و رواج گرفت، از عالم طپیدن و طلا به معنی طشت کلان و گهری . (غیاث اللغات ). و در منتخب نوشته ظرفی که درو آب و شراب خورند و هیچ نگفته که معرب است و در شرح نصاب نوشته که : طاس از لغات مولد است یعنی عربی نیست بلکه از آن گرفته اند. (غیاث اللغات ). ج، طاسات . (مهذب الاسماء). پنگان . (لغتنامه ٔ اسدی ). فنجان . اجانة. ظرفی که در آن آشامند. ظرف شراب . جام . آوند شراب . (دهار). مکّوک ؛ طاس که بدان آب خورند. (منتهی الارب ). پیاله . تشت . طشت <span class=\"hlight\">:</span> <br />تو چه پنداریا که من ملخم <br />که بترسم ز بانگ سینی و طاس .<br /> <font color=\"Red\">خسروی .</font><br />سیه چهره و ریش کافورگون <br />دو چشمش بمانند دو طاس خون .<br /> <font color=\"Red\">فردوسی .</font><br />یکی طاس پر گوهر شاهوار<br />ز دینار چندی ز بهر نثار.<br /> <font color=\"Red\">فردوسی .</font><br />همان هر چه زرین به پیش اندر است <br />اگر طاس و جام است وگر مجمراست .<br /> <font color=\"Red\">فردوسی .</font><br />بجوشید بر هر دو جوشن زخشم <br />چو دوطاس خون کرده از کینه چشم .<br /> <font color=\"Red\">فردوسی .</font><br />بگفت این و از بارگه شد برون <br />دو چشمش بمانند دو طاس خون .<br /> <font color=\"Red\">فردوسی .</font><br />سنگی زده است پیری بر طاس عمر تو<br />کان را بهیچ روی نیارد کس التیام .<br /> <font color=\"Red\">ناصرخسرو.</font><br />اینت مسکر حرام کرد چو خوک <br />وانت گفتا بجوش و پر کن طاس .<br /> <font color=\"Red\">ناصرخسرو.</font><br />این طاس خالی از من و آن کوزه ای که بود<br />پارینه پر ز شهد مصفی از آن تو.<br /> <font color=\"Red\">وحشی .</font><br /> <BR><font color=\"Blue\">◄</font> درفارسی ظرفی که بحمام برند و در آن آب کرده نزد خویش نهند استعمال را. این ظرف را در ترکی هم طاس گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سرطاس نشاندن </span> ؛ به جربزی و مکر کسی را بگفتن راز بازداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاس گم شدن </span> ؛ هیاهوی برپا شدن . قیل و قال برخاستن .<br /> <BR><font color=\"Blue\">◄</font> و نیز نام جامه ٔ زرتار. (از چراغ هدایت ) (غیاث اللغات ).<br /> <BR><font color=\"Blue\">◄</font> قبه مانندی از فلز در گردن نیزه که پرچم را در آن آویزند. (شرح دیوان خاقانی ) <span class=\"hlight\">:</span> <br />جهان بپرچم طاس رماح او نازد<br />کزین دو مادت نور و ظلام او زیبد.<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> آویزهای طلا و نقره که بر علم آویزند. (شرح دیوان خاقانی ) <span class=\"hlight\">:</span> <br />کیوانش پرچم است و مه و آفتاب طاس <br />چون زلف آنکه عید بتان خواند آذرش .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> حقه ٔ سیم ؛ از اسباب زینت است . (شرح دیوان خاقانی ) <span class=\"hlight\">:</span> <br />آن نگویم کز دم شیر فلک در آفتاب <br />پرچم و طاسش برای خنگ و اشقر ساختند.<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> (ص ) سر بیموی . داغسر. دغسر. تاس . داس . داس سر. روخ . روخ چکاد. <BR><font color=\"Blue\">◄</font> (اِ) در بازی نرد، کعب . کعبة. هر دو طاس نرد؛ کعبتین . طاسهای نرد. رجوع به طاسک شود.<br /></font></div>'),
(174987, 'طاس آبگون', '<span class=\"hlight\">طاس آبگون .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) به معنی طارم نیلگون است که کنایه از آسمان باشد. (برهان ).<br /></font></div>'),
(174988, 'طاس افلاک', '<span class=\"hlight\">طاس افلاک .</span> <font color=\"DarkGreen\"><b>[ س ِ اَ ]</font></b>(ترکیب اضافی، اِ مرکب ) کنایه از قبه ٔ آسمان است .<br /></font></div>'),
(174989, 'طاس بقچه', '<span class=\"hlight\">طاس بقچه .</span> <font color=\"DarkGreen\"><b>[ س ِ ب ُ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) مجموع اسباب حمام مردی یا زنی .<br /></font></div>'),
(174990, 'طاس بین', '<span class=\"hlight\">طاس بین .</span> (نف مرکب ) کسی که در طاس فال بیند. (آنندراج ) <span class=\"hlight\">:</span> <br />بر اطراف آن قصرهای متین <br />نشستند چون مردم طاس بین .<br /><font color=\"Red\">ملاحسین صبوحی .</font><br /></font></div>'),
(174991, 'طاس زر', '<span class=\"hlight\">طاس زر.</span> <font color=\"DarkGreen\"><b>[ س ِ زَ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از آفتاب عالمتاب است . (برهان ). <BR><font color=\"Blue\">◄</font> در افواه شنیده شده که صحرای شهر دربند به طاس زر موسوم است و مراد از عقرب (در شعر زیر) مردم شرور آنجا میباشند که در زمین زرخیزی مقام دارند. (شرح دیوان خاقانی ) <span class=\"hlight\">:</span> <br />گویند پر ز عقرب طاس زر است حاشا<br />کز حرمتش فلک را عقرب فکند نشتر.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(174992, 'طاس زرین', '<span class=\"hlight\">طاس زرین .</span> <font color=\"DarkGreen\"><b>[ س ِ زَرْ ری ]</font></b> (ترکیب وصفی، اِ مرکب )کنایه از ساغر می . (شرح دیوان خاقانی ) <span class=\"hlight\">:</span> <br />طاس زرین کش آفتاب آسا<br />کآفتاب است طاس پرچم صبح .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(174993, 'طاس ساعت', '<span class=\"hlight\">طاس ساعت .</span> <font color=\"DarkGreen\"><b>[ س ِ ع َ ]</font></b> (ترکیب اضافی، اِ مرکب ) پیمانه ٔساعت باشد، و آن معروف است . (آنندراج ) <span class=\"hlight\">:</span> <br />بنوازیدم بزخمه، طاعت این است <br />آرید بناله ام، شفاعت این است <br />در هر گریه ام، پر و تهی گردد چشم <br />کریال زنید، طاس ساعت این است .<br /> <font color=\"Red\">نظیری نیشابوری .</font><br />چیست این طاس ساعت گردان <br />کاهش زندگانی مردان .<br /> <font color=\"Red\">(راحة الصدور ص <span class=\"hlight\" dir=\"rtl\">١٢١</span>).</font><br />رجوع به طاس و پنگان شود.<br /></font></div>'),
(174994, 'طاس طاوس', '<span class=\"hlight\">طاس طاوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) حمای ربع. تب سه یک . تب که یک روز آید و سه روز نیاید.<br /></font></div>'),
(174995, 'طاس لغزنده', '<span class=\"hlight\">طاس لغزنده .</span> <font color=\"DarkGreen\"><b>[ س ِ ل َ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ترکیب وصفی، اِ مرکب ) طاس که لغزد. جام لغزان . <BR><font color=\"Blue\">◄</font> لانه ٔ موری مورچه خوار <span class=\"hlight\">:</span> <br />چو در طاس لغزنده افتاد مور<br />رهاننده را چاره باید نه زور.<br /> <font color=\"Red\">سعدی .</font><br />و رجوع به لغزنده شود.<br /></font></div>'),
(174996, 'طاس نگون', '<span class=\"hlight\">طاس نگون .</span> <font color=\"DarkGreen\"><b>[ س ِ ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از آسمان است و عربان فلک خوانند. (برهان ). کنایه از فلک و آسمان است . (ناظم الاطباء).<br /></font></div>'),
(174997, 'طاس و پنگان', '<span class=\"hlight\">طاس و پنگان .</span> <font color=\"DarkGreen\"><b>[ س ُ پ َ ]</font></b> (ترکیب عطفی، اِ مرکب ) طاس ساعت . رجوع به طاس ساعت و پنگان شود.<br /></font></div>'),
(174998, 'طاس پرچم', '<span class=\"hlight\">طاس پرچم .</span> <font color=\"DarkGreen\"><b>[ س ِ پ َ چ َ ]</font></b> (ترکیب اضافی، اِ مرکب ) قبه ای که پرچم علم بر آن نصب میشود. (شرح دیوان خاقانی ) <span class=\"hlight\">:</span> <br />طاس زرین کش آفتاب آسا<br />کآفتاب است طاس پرچم صبح .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(174999, 'طاس پلو', '<span class=\"hlight\">طاس پلو.</span> <font color=\"DarkGreen\"><b>[ پ ُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> لُو ]</font></b> (اِ مرکب ) قسمی از اقسام پلوها است .<br /></font></div>'),
(175000, 'طاس چهل کلید', '<span class=\"hlight\">طاس چهل کلید.</span> <font color=\"DarkGreen\"><b>[ س ِ چ ِ هَِ ک ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) طاس چل کلید. طاسی است که بر یکدسته کلیدهای آهنین ادعیه نقش کنند و بر آن طاس نیز ادعیه بنگارند وبرای حصول مرادات ادعیه را خوانده، آب در طاس انداخته بر سر خود ریزند و بعضی دیگر گویند نوعی است خاص که بر شکلی و وضعی معین سازند. چهل طاس <span class=\"hlight\">:</span> <br />در دهن باشد گرم در وصل او چندین زبان <br />گفتگو از من نمی آید چو طاس چل کلید.<br /> <font color=\"Red\">میرزا طاهر وحید.</font><br />ز برگ بید که در آب ریخت باد خزان <br />حباب یاد ز طاس چهل کلید دهد.<br /> <font color=\"Red\">محمدقلی سلیم .</font><br />از بیت اول معنی اول و از بیت دوم معنی دوم معلوم میشود، پس هر دو درست باشد. (آنندراج ).<br /></font></div>'),
(175001, 'طاس کباب', '<span class=\"hlight\">طاس کباب .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِ مرکب ) نوعی خوراک کثیرالاستعمال مرکب از گوشت و روغن و پیاز و برخی مواد و ادویه .<br /></font></div>'),
(175002, 'طاسا', '<span class=\"hlight\">طاسا.</span> (اِ) مار قشیشاست . (فهرست مخزن الادویة).<br /></font></div>'),
(175003, 'طاسات', '<span class=\"hlight\">طاسات .</span> (ع اِ) ج ِ طاس، به معنی آوند. رجوع به طاس شود.<br /></font></div>'),
(175004, 'طاسباز', '<span class=\"hlight\">طاسباز.</span> (نف مرکب ) در ولایت طایفه ای اند که از زیر خرقه طاسها برآرند و گاهی طاس را در هوا افکنند و بر سر چوب بگیرند، از عالم شیشه باز، و بازیهای عجیب و غریب دیگر نیز کنند، از عالم بهان متی هندوستان . (آنندراج ) (بهار عجم ) <span class=\"hlight\">:</span> <br />ز کشتی چو کردیم هنگامه ساز<br />بگوئیم حرفی هم از طاسباز<br />خورد چرخ از چرخ آن دلربا<br />بمن حال گردید چون آسیا.<br /> <font color=\"Red\">میرزا طاهر وحید.</font><br /> <BR><font color=\"Blue\">◄</font> محیل . مکار. (مجمع التماثیل از بهار عجم و آنندراج ) <span class=\"hlight\">:</span> <br />طاسبازی بدیدم از بغداد<br />چون جنید از سلوکش آگاهی <br />سر برون برد زیر جبه و گفت <br />لیس فی جبتی سوی اﷲ.<br /><font color=\"Red\">کمال خجندی .</font><br /></font></div>'),
(175005, 'طاسبازی', '<span class=\"hlight\">طاسبازی .</span> (حامص مرکب ) نوعی از بازی بازیگران ؛ و آن چنان باشد که طاس را بهوا انداخته بر سر چوبی یا نیی میگیرند و بر آن می گردانند. <BR><font color=\"Blue\">◄</font> به معنی شعبده بازی نیز آمده . (غیاث اللغات ) <span class=\"hlight\">:</span> <br />لباس خضر بپوشید و طاسبازی کرد<br />ز بچگان مشعبدنشان دهد نرگس .<br /> <font color=\"Red\">محمد عرفی .</font><br /><BR><font color=\"Blue\">◄</font> و گاهی مراد از آن فریب باشد. (غیاث اللغات ).<br /></font></div>'),
(175006, 'طاسبند', '<span class=\"hlight\">طاسبند.</span><font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) از دهات همدان است . (معجم البلدان ).<br /></font></div>'),
(175007, 'طاسبندی', '<span class=\"hlight\">طاسبندی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ص نسبی )منسوب به طاسبند که از دهات همدان است . (سمعانی ).<br /></font></div>'),
(175008, 'طاسة', '<span class=\"hlight\">طاسة.</span> <font color=\"DarkGreen\"><b>[ طاس ْس َ ]</font></b> (ع ص ) طعنة طاسةٌ؛ نیزه ای که در شکم درآمده . (منتهی الارب ).<br /></font></div>'),
(175009, 'طاسو قوسیس', '<span class=\"hlight\">طاسو قوسیس .</span><font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) جربی باشد در چشم که پشت پلک از درونسو دارای شکافهائی چون پوست انجیر باشد. (بحرالجواهر).<br /></font></div>'),
(175010, 'طاسچه', '<span class=\"hlight\">طاسچه .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ]</font></b> (اِ مصغر) طاس خرد که دختربچگان در حمام دارند.<br /></font></div>'),
(175011, 'طاسک', '<span class=\"hlight\">طاسک .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِمصغر) مصغرطاس است . (آنندراج ). طاس خرد. (شمس اللغات ). رجوع به طاسچه شود. <BR><font color=\"Blue\">◄</font> در بازی نرد کعب، کعبة، هر دو طاس نرد. کعبتین . رجوع به طاس شود <span class=\"hlight\">:</span> <br />نقش از طاسک زر چون همه شش می آید<br />از چه معنی است فرومانده به ششدر نرگس .<br /> <font color=\"Red\">سلمان ساوجی .</font><br /> <BR><font color=\"Blue\">◄</font> مرادف طاس در معانی آویزهای طلا و نقره و اسباب زینت و حقه ٔ سیم که آنها را از رایت و بر گستوان و گردن اسب و مانند اینها در می آویخته اند <span class=\"hlight\">:</span> <br />بهمه ملک زمین ز آنکه فرو نارد سر<br />مهچه ٔ رایت او گشته فلکسا بینی <br />طاسک رایت مشکین سلبش را که ز دور<br />چون مه بدر فراز شب یلدا بینی .<br /> <font color=\"Red\">اثیرالدین اومانی .</font><br />تیغ را گر آب دادندی ز لطفت دروغا<br />آب حیوان ریختی در طاسک برگستوان .<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />مه طاسک گردن سمندت <br />شب طره ٔ گیسوی سیاهت .<br /><font color=\"Red\">جمال الدین عبدالرزاق .</font><br /></font></div>'),
(175012, 'طاسک منجوق', '<span class=\"hlight\">طاسک منجوق .</span> <font color=\"DarkGreen\"><b>[ س َ ک ِ م َ ]</font></b> (ترکیب اضافی، اِ مرکب )منجوق . ماهچه ٔ علم . و طاسک چیزی است شبیه به طاس کوچک که در منجوق و پرچم تعبیه میشده است <span class=\"hlight\">:</span> <br />ز موج خون که بر میشد بعیوق <br />پر از خون گشته طاسکهای منجوق .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175013, 'طاسک پرچم', '<span class=\"hlight\">طاسک پرچم .</span> <font color=\"DarkGreen\"><b>[ س َ ک ِ پ َ چ َ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به طاس پرچم شود <span class=\"hlight\">:</span> <br />ای ظفر مرکب ترا همراه <br />طاسک پرچم تو قبه ٔ ماه .<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />کاسه ای کز سر بدخواه تو پر سودا بود<br />زود باشد که ترا طاسک پرچم گردد.<br /> <font color=\"Red\">امامی هروی .</font><br />دولت تو هر کجا زد علم کبریا<br />طاسک پرچم شود دشمن وی را جبین .<br /><font color=\"Red\">سیف اسفرنگ .</font><br /></font></div>'),
(175014, 'طاسی', '<span class=\"hlight\">طاسی ٔ.</span> <font color=\"DarkGreen\"><b>[ س ِءْ ]</font></b> (ع ص ) گرفته : یقال نفسی طاسِئَةٌ؛ یعنی دل من گرفته است . (منتهی الارب ).<br /></font></div>'),
(175015, 'طاسی', '<span class=\"hlight\">طاسی .</span> (اِخ ) موضعی است در خراسان . (معجم البلدان ).<br /></font></div>'),
(175016, 'طاسیس', '<span class=\"hlight\">طاسیس .</span> (اِخ ) صاحب مجمل التواریخ و القصص ذیل اخبار ملوک روم گوید: مملکت طاسیس و استسیانوس بمشارکت سیزده سال بوده است . جهودان در این روزگار به بیت المقدس عاصی شدند بر ایشان وسه هزار مردان جهودان بکشتند و زن و فرزند به رومیه آوردند بغارت اندر اول سال و بدین عهد اندر بود برخاستن بلیناس مطلسم . (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span>).<br /></font></div>'),
(175017, 'طاش فراش', '<span class=\"hlight\">طاش فراش .</span> <font color=\"DarkGreen\"><b>[ ش ِ ف َرْ را ]</font></b> (اِخ ) رجوع به تاش فراش شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175018, 'طاش کبری زاده', '<span class=\"hlight\">طاش کبری زاده .</span> <font color=\"DarkGreen\"><b>[ ک ُ را دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِخ ) از فضلای نامی کشور ترکیه است که در قرن دهم میزیسته .وی را کتابی است بنام شقائق النعمانیة فی علماءالدولة العثمانیة، در پایان کتاب مزبور، ترجمه ٔ احوالی ازخود نوشته که ترجمه ٔ آن در ذیل درج میگردد. فاضل مزبور نام و نسب خود را بدین نحو ذکر کرده : و انا العبد الضعیف الذلیل، المحتاج الی رحمة ربه الجلیل، احمدبن مصطفی بن خلیل، عفی اﷲ عنهم بکرمه الجمیل، و لطفه الجزیل، المشتهر بین الناس به طاش کبری زاده، جعل اﷲ الهدی والتقوی زاده، و اوفر کل یوم علمه و زاده ؛ حکایت کرد پدرم که ماهی پیش از تولد من، آهنگ سفری از بروسه به آنقره کرده بود، در آن شبی که فردای آن عازم آنقره میبود، پیری خوش چهره را در خواب دیده که بدو گفته بود: ترا بشارت باد که بدین زودی حق عز اسمه ترا پسری عطا خواهد فرمود، او را احمد نام نه، پدرم خواب خویش را برای مادرم نقل میکند، و سپس بصوب آنقره عازم میگردد. شب چهاردهم ماه ربیع الاول سال <span class=\"hlight\" dir=\"rtl\">٩٠١</span> هَ .ق . از کتم عدم به عالم هستی قدم نهادم . و چون بسن رشد رسیدم با مادرم به آنقره رهسپار شدیم، در آنجا بقرائت کلام اﷲ مشغول شدم، پدرم در همان اوقات مرا به «عصام الدّین » ملقب و به «ابوالخیر» مکنی ساخت . برادری هم داشتم که نامش محمد، لقبش نظام الدین، و کنیه اش ابوسعید، و دو سال از من بزرگتر بود، چون من و برادرم قرآن را ختم کردیم با پدر و مادر و برادر بشهر بروسه باز گشتیم . پدر، ما را پاره ای از لغت عرب آموخت، و سپس پدرم را مسافرتی به اسلامبول پیش آمد، و مرا بعالم عامل علاءالدین ملقب به یتیم سپرد - ترجمه ٔ احوال این عالم را در کتاب شقائق النعمانیه ایراد کرده ام - نزد او کتاب مختصری که نام آن مقصود و در علم صرف بودبخواندم، و نیز صرف را از کتاب مختصر عزالدین زنجانی، و مختصر مراح الارواح نزد وی فرا گرفتم از علم نحومختصر المائة شیخ امام عبدالقادر جرجانی، و کتاب مصباح تألیف امام مطرزی، و کتاب کافیه ٔ علامه ابن حاجب را نیز نزد عالم مذکور بپایان رساندم، و متون کتب مزبور را بمشارکت برادرم از بر داشتیم . سپس شروع کردیم بخواندن کتاب وافیه، شرح بر کافیه، و چون بمباحث مرفوعات آن کتاب رسیدیم، عم من، قوام الدین قاسم بشهر بروسه آمد، و در مدرسه ٔ مولی خسرو بتدریس اشتغال ورزید. من و برادرم مباحث مرفوعات را نزد عم خویش در همان مدرسه بپایان رساندیم، و خواستیم مباحث مجرورات را شروع کنیم، برادرم را بیمارئی مزمن روی داد. از من خواهش کرد تا آنگاه که وی از بیماری برنخیزد من درس خواندن را تعطیل کنم، منهم مسئول وی را مقرون به اجابت داشتم، و با اینحال در مدت بیماری برادر، کتاب هارونیه را که آن نیز در علم صرف است، و الفیه ٔ ابن مالک را که در نحو است، نزد عم خویش خواندم، و چون ازحفظ کردن هر دو کتاب فراغت یافتم، برادرم به سال <span class=\"hlight\" dir=\"rtl\">٩١٤</span> هَ . ق . فرمان یافت . پس از این پیشامد، بخواندن ضوءالمصباح نزد عّم خویش شروع کردم، و از آغاز تا انجام آن کتاب را بخّط خود نبشته و در نهایت اتقان در تصحیح آن کوشیدم . سپس علم منطق را از مختصر ایساغوجی وشرح آن که از حسام الدین گاتی است با قسمتی از شرح شمسیه که شارح آن علامه ٔ رازی میباشد، نزد عم خویش خواندم . در این هنگام پدرم از اسلامبول بشهر بروسه بازگشت، و در مدرسه ٔ حسینیه ٔ آماسیه مشغول تدریس گردید، ازینرو شرح شمسیه را از اول تا به آخر آن باحواشی که سید شریف بر آن کتاب نوشته بعلاوه ٔ کتب مفصله ٔ شرح العقائد علامه ٔ تفتازانی با حواشی مولی خیالی بر آن، و شرح هدایةالحکمة از مولانازاده و حواشی مولی خواجه زاده بر آن، و شرح آداب البحث از مولانا مسعود رومی، و شرح طوالع از علامه ٔ اصفهانی از آغاز تا انجام، با حواشی سید شریف بر آن، و بعضی از مباحث حاشیه ٔ شرح مطالع از سید شریف را نزد پدر خویش در نهایت دقت خواندم .در این هنگام پدر مرا گفت : آنچه بر گردن من حق داشتی ادا کردم، و زین پس با تست که بدانچه صلاح خویش باشد اقدام ورزی، و بعد از آن تاریخ، پدرم تا زمانی که در قید حیات بود حرفی هم بمن نیاموخت . آنگاه نزد دائی خویش، حواشی شرح تجرید سیدشریف را از ابتدای کتاب تا مبحث وجوب و امکان در کمال تدقیق و اتقان خواندم، و شرح مفتاح سید شریف را از اول مبحث مسند تا آخر مبحث فصل و وصل، نزد عالم فاضل مولی محیی الدین فناری فراگرفتم . شرح مواقف سیدشریف را از آغاز الهیات تا مبحث نبوات با نهایت دقت نزد عالم فاضل مولی محیی الدین سیدی محمد قوجوی خواندم . تفسیر سوره ٔ نباء از تفسیر کشاف را هم نزد محمد قوجوی فراگرفتم . سپس نزد عالم فاضل کامل، مولی بدرالدین محمود، پسر قاضی زاده ٔ رومی، مشهور به میرم چلبی کتاب فتحیه را خواندم که در علم هیئت است و مؤلف آن مولی علی قوشچی است و در همان تاریخ هم بر آن شرح مینوشت . مؤلف مزبور پس از آنکه از شرح آن کتاب فراغت یافت، آن را برسم تحفه تقدیم سلطان سلیم داشت . سلطان نیز در ازاء این خدمت، منصب قضای عسکر آناطولی را بمشارالیه تفویض کرد - قسمتی از صحیح بخاری، و اندکی از کتاب الشفاء قاضی عیاض، وعلم جدل و خلاف را نزد عالم کامل شیخ محمد تونسی المولد مشهور به مغوشی آموختم، و با او در علوم عقلیه و عربیه مباحثه ٔ بسیاری داشتم، تا حدی که مرا اجازت شفاهی و کتبی داد که تفسیر و حدیث و سائر علوم، و همگی آنچه را که روایت آن جایز و مقرون به صحّت باشد از او روایت کنم . و وی از شیخ خویش، ولی اﷲ، شهاب الدین احمد البکی المغربی، روایت کند، و شیخ احمد از شیخ خود، حافظ المشرقین، امیرالمؤمنین فی الحدیث، شهاب الدین احمدبن الحجر العسقلانی ثم المصری روایت کند. در علم تفسیر و حدیث از پدر خود نیز اجازت روایت دارم . پدرم از پدر خویش، و جدم از مولی یگان، و او از مولی النکساری، و او از جمال الدین آقسرائی و از شیخ اکمل روایت پدرم کند. از طریق دیگر، تفسیر و حدیث را از مولی خواجه زاده، و او از مولی فخرالدین العجمی المفتی، و او از مولانا حیدر، و او از مولانا سعدالدین تفتازانی روایت کند. سومین اجازتی که مراست در علم تفسیرو حدیث، اجازتی است که از مولی الفاضل، سیدی محیی الدین القوجوی در دست دارم، قوجوی از استاد خویش، عالم عامل، فاضل کامل، مولی حسن چلبی الفناری، روایت کند، و فناری از شاگردان شیخ شهاب الدین، احمدبن الحجر بوده است . نخستین بار در اواخر ماه رجب سال <span class=\"hlight\" dir=\"rtl\">٩٣١</span> هَ . ق . در مدرسه ٔ دیمهتوقه بسمت مدرسی تعیین شدم، و در آنجا به تدریس شرح تلخیص (مطول ) از اول قسم بیان تا بحث استعاره، و تدریس حواشی شرح تجرید، تا آخر مباحث امور عامه، و تدریس شرح فرائض سیدشریف پرداختم . سپس در اوائل ماه رجب <span class=\"hlight\" dir=\"rtl\">٩٣٣</span> هَ . ق . در مدرسه ٔ مولی حاج حسن در شهر اسلامبول بمدرسی منصوب شدم، در آن مدرسه شرح وقایه ٔ صدرالشریعه را از ابتدای کتاب تا کتاب بیع، و شرح مفتاح سیدشریف را از اول کتاب تا مبحث ایجاز واطناب، و حواشی شرح تجرید را از مباحث امور عامه تامباحث وجوب و امکان درس گفتم . کتاب مصابیح را که درعلم حدیث است در آنجا دو نوبت نقل کردم، و چون نقل کتاب مزبور خاتمه یافت، پدرم بجوار رحمت حق پیوست . (در شهر اسلامبول : هنگام نیم چاشت، روز دوازدهم ماه شوال به سال <span class=\"hlight\" dir=\"rtl\">٩٣٥</span> هَ . ق .). در اوائل ماه ذی الحجه ٔ سال <span class=\"hlight\" dir=\"rtl\">٩٣٦</span> به سمت استادی مدرسه ٔ اسحاقیه اسکوب تعیین شدم، و بدانجا انتقال یافتم، در آن مدرسه نیز کتاب مصابیح را از آغاز تا انجام نقل کردم همچنین کتاب مشارق رااز اول تا به آخر در ماه رمضان، کتاب توضیح را از ابتدا تا انتها، شرح وقایه ٔ صدرالشریعه را از اول کتاب بیع تا پایان کتاب، شرح فرائض سیدشریف را تماماً، شرح مفتاح را از اول فن بیان تا آخر کتاب در مدرسه ٔ اسحاقیه ٔ اسکوب درس گفتم . از آن پس به اسلامبول رهسپار شدم و در روز هفدهم ماه شوال <span class=\"hlight\" dir=\"rtl\">٩٤٢</span> در مدرسه ٔ قلندرخانه بسمت استادی نائل آمدم، در آنجا نیز کتاب مصابیح را از ابتدا تا کتاب بیع نقل کردم و شرح مواقف را از اول مبحث وجوب و امکان تا مبحث اعراض، و پاره ای ازوقایه ٔ صدرالشریعه و مختصری از شرح مفتاح سیدشریف را در آن مدرسه درس گفتم، در روز بیست و یکم ربیع الاول <span class=\"hlight\" dir=\"rtl\">٩٤٤</span> مرا از مدرسه ٔ قلندرخانه به مدرسه ٔ مصطفی پاشای وزیر انتقال دادند، کتاب مصابیح را از کتاب بیع تابه آخر کتاب در آن مدرسه نقل کردم وز آن پس بتدریس کتاب هدایة مشعول شدم، بمبحث زکوة که رسیدم، پاره ای از مباحث از اول الهیات شرح مواقف را نیز در آن مدرسه درس گفتم، بعداً در تاریخ <span class=\"hlight\" dir=\"rtl\">٤</span> ذی القعده ٔ <span class=\"hlight\" dir=\"rtl\">٩٤٥</span> به یکی از دو مدرسه ٔ مجاور به ادرنه انتقال یافتم . در آنجا بروایت صحیح بخاری شروع کردم و یک جلد از مجلدات نهگانه ٔ آن کتاب را در آن مدرسه تدریس کردم، کتاب هدایةرا نیز از اول کتاب زکوة تا آخر کتاب حج و کتاب تلویح را از آغاز کتاب تا تقسیم اول آن در آن مدرسه درس گفتم، سپس در <span class=\"hlight\" dir=\"rtl\">٢٣</span> ربیع الاول سال <span class=\"hlight\" dir=\"rtl\">٩٤٦</span> هَ . ق . به یکی از مدارس هشتگانه منتقل شدم، نقل صحیح بخاری و اتمام آن در دو نوبت در آن مدرسه صورت گرفت، تفسیر سوره ٔ بقره از تفسیر بیضاوی را نیز در آن مدرسه درس دادم . کتاب هدایة را از اول کتاب نکاح تا کتاب بیوع و کتاب تلویح را از تقسیم اول تا مباحث احکام هم در آن مدرسه تدریس کردم . در تاریخ یازدهم شوال سال <span class=\"hlight\" dir=\"rtl\">٩٥١</span> بمدرسه ٔ سلطان بایزیدخان که واقع در ادرنه است منتقل شدم، ثلثی از صحیح بخاری را در این مدرسه نقل کردم و کتاب هدایة را از کتاب بیوع تا کتاب شفهة و کتاب تلویح را از قسم احکام تا آخر کتاب، و شرح مواقف و شرح فرایض سیدشریف را تا مباحث تصحیح، در این مدرسه درس گفتم . از آن هنگام امور قضائی شهر بروسه را بمن واگذار کردند - روز <span class=\"hlight\" dir=\"rtl\">٢٦</span> ماه رمضان المبارک سال <span class=\"hlight\" dir=\"rtl\">٩٥٣</span> - فیا ضیعةالاعمار (چه عمرها که به بیهوده سپری میشود). سپس دومین بار بتدریس در یکی از مدارس هشتگانه تعیین شدم -در تاریخ <span class=\"hlight\" dir=\"rtl\">١٨</span> رجب سال <span class=\"hlight\" dir=\"rtl\">٩٥٤</span> - در آنجا صحیح بخاری را از آغاز تا انجام آن درس گفتم، کتاب هدایة را از کتاب شفعة تا پایان کتاب نیز در آن مدرسه و کتاب تلویح را از ابتداء تا تقسیم چهارم و حواشی سید شریف را بر کشاف تا اثناء سوره ٔ فاتحةالکتاب هم در آن مدرسه تدریس کردم و مشغول تدریس بودم که مأمور عهده داری امورقضائی شهر اسلامبول گردیدم - روز <span class=\"hlight\" dir=\"rtl\">١٧</span> شوال سال <span class=\"hlight\" dir=\"rtl\">٩٥٨</span> - وز آن پس مشاغل و امور قضائی بکلی راهی را که در اشتغال بکسب دانش می پیمودم قطع کرد و سد عظیمی برای حصول این مقصود گردید، و کان ذلک فی الکتاب مسطوراً و کان امراﷲ قدراً مقدوراً. آنگاه در هفدهم ربیع الاول سال <span class=\"hlight\" dir=\"rtl\">٩٦١</span> مرا چشم دردی عارض شد که چندین ماه بطول انجامید و از این بیماری زیان بسیاری به من رسید و از درگاه حق جل ذکره امید میدارم که همچنانکه پیغمبر صلی اﷲ علیه و سلم به امت مرحومه بشارت و نوید پاداش عطا فرموده در جهان دیگر تلافی و بهشت جاویدان نصیب گردد.<br />در اثناء اشتغال بتحصیل و کسب علم حق عزاسمه مرا بتصنیف کتابی چند در موضوع های مختلف موفق داشت از قبیل تفسیر اصول دین، اصول فقه و عربیة و غیره و نیز بتأییدات ایزدی به حل ّپاره ای از مسائل مشکله و تحقیق مطالب عالیه توفیق یافتم و برای هر یک از آن مباحث و مطالب رساله نوشتم که مجموع آنها از سی رساله متجاوز است، اما مقدرات وانقلابات روزگار رشته ٔ آرزوی مرا برید و میسر نشد تمامی آنچه را که به سواد آورده بودم به بیاض نقل دهم، این بود شمّه ای از آنچه باری تعالی جل شأنه از علوم و معارف بر من بخشایش فرمود و بر حسب استعداد فطری بهره و نصیب من ساخت، و فوق کل ذی علم علیم و العیاذباللّه، کسی را این اندیشه در دل نگذرد که بیانات مندرجه در این شرح حال برای ابراز علم و فضل بوده بلکه سبب اصلی بیان این مطالب فرمانبرداری حق است که فرموده : و اما بنعمة ربک فحدث و قد فرغت من املائه یوم السبت، آخر شهر رمضان المبارک فی تاریخ سنة خمس و ستین و تسعمائة بمدینة قسطنطینیة المحمیة. (شقایق النعمانیة حاشیه ٔ ج <span class=\"hlight\" dir=\"rtl\">٢</span> ابن خلکان چ مصر) علی افندی بن لالی بالی بن محمد بک المعروف به منق المتوفی سنة <span class=\"hlight\" dir=\"rtl\">٩٩٢</span> در کتاب عقدالمنظوم ذکر افاضل الروم که ذیلی بر شقایق النعمانیه است آورده که : چون طاش کبری زاده از چشم نابینا گردید، از منصب قضا و تدریس استعفا کرد و از آنچه در دوره ٔ تصدی وی به امور قضائی ناشی شده بود توبه کرد و به تبییض مسودات خویش پرداخت . در آن اثناء به بیماری بواسیر نیز دچار شد، خویشان و نزدیکان وی چون او را در پایان روزهای زندگانی یافتند از او درخواستند که اگر از ناحیه ٔ آنان در طول مدت عمر قصوری در انجام وظیفه ٔ خویشاوندی نسبت بخود مشاهده کرده از ایشان درگذرد و اغماض کند، وی نیز که پیک اجل را نزدیک دیده بود در ازاء درخواست آنان این انشاء را املاء کرد:<br />بسم اﷲ الرحمن الرحیم . الحمدﷲ رب العالمین والصلوة والسلام علی نبیه محمد صلی اﷲ علیه و آله و صحبه اجمعین، و علی المشایخ الزاهدین و علی الفقراء الصابرین . و علی الاغنیاء الشاکرین و سلم علیهم سلاماً الی یوم الحشر والدین . ثم انی اشهدک و اشهد ملائکتک بان عشت علی ملة الاسلام و عذت ُ عن البدعة فی الدین و ارجو ان القاک بالاسلام فی یوم الدین . ثم ان اولادی و اقربائی التمسوا منی ان اجعلهم فی حل مما عملوا من الاسائة فیما وجب علیهم من رعایة حقی فیما بعد ذلک . والسلام علی سید الانام و صحبه الکرام . چون از املاء فراغت یافت مرغ روحش از عالم انس پرواز کرد و در حظائر قدس آرمید و کان ذلک فی سنة <span class=\"hlight\" dir=\"rtl\">٩٦٨</span>. و نیز صاحب عقدالمنظوم پس از سطری چند که در توصیف طاش کبری زاده و تمجید اخلاق وی نوشته گوید از زبان کسی که بگفتارش وثوق داشتم شنیدم که آن فقید علم و ادب روزی با دست خویش بزبان خود اشارت کرده گفت هذا فعل ما فعل من التقصیر و الزلل و صدر عنه ما صدر من الحق و الغلط، غیر انه ما تکلم فی طلب المناصب الدنیویة قط. و نیز در کتاب مزبور آورده که : طاش کبری زاده را خطی زیبا و مطبوع بود، و تندنویس بود، بخط خود کتب بسیار می نوشت . یکی از شاگردان او گفت در یکی از شبهای ماه مبارک رمضان، هنگامی که مدرس مدرسه ٔ قلندریه بود، بر سفره ٔ وی حضور یافتم . (عادت بر آن داشت که در لیالی رمضان طلاب علوم را دعوت میکرد). طاش کبری زاده در آن شب گفت از زمانی که متصدی تدریس در مدرسه ٔ اسحاقیه ٔ اسکوب شدم، خویشتن را عادت دادم که در هر سال نسخه ای از تفسیر بیضاوی به خطّ خود نوشته وهر نسخه را به سه هزار دینار بمعرض فروش رسانم، و وجه آن را در راه اطعام طلاب علوم انفاق کنم . و نیز از پاره ای از اهل وثوق شنیدم که از قول طاش کبری زاده نقل کرده میگفت : ببعضی از مشایخ صوفیه پیوستم، و سپاس خدای را که بسبب او از نفایس حالات سلوک بدانچه مشتاق آن بودم مرا پیش آمد، چنانکه وقتی اتفاق افتاد که خود را از جامه ٔ بشریت عاری و روحی بی کالبد یافتم، درآن حالت نیمه ٔ روز دررسید، خواستم وضو سازم، توانائی آن که اعضا را بجنبش درآورم و بکار بازدارم در خودنیافتم، نیمه روز گذشت و هنگام عصر فرا رسید، و آن حالت در من باقی بود و پس از ساعتی چند بحالت اولیه بازگشتم . مؤلف عقدالمنظوم پس از بیانات فوق بذکر اسامی تألیفات او میپردازد؛ و گوید تألیفات وی عبارت است از: تجرید سیدشریف جرجانی، از اول کتاب تا مباحث ماهیت که مقالات مولی علی قوشچی و مولی جلال دوانی ومولی میر صدرالدین و مولی ابن الخطیب را بخلاصه ترین عبارتی در یکجا گرد آورده و سپس از تحقیقات خود آنچه مناسب مقام بوده ایراد کرده است . شرح قسم سوم از کتاب مفتاح العلوم سکاکی . شرح فوائد غیاثیة. و آن شرح جامعی است که بعضی از مواضع شرح مفتاح را رد کرده است . حاشیه از اول شرح مفتاح سیدشریف جرجانی که پاره ای از سخنان مولی مصلح الدین پدرش را هم در آن گنجانیده است . ولی این کتاب به اتمام نرسیده است . از مختصرات : مختصری در علم نحو بر منوال مختصر بیضاوی غیر از آنچه ذکر شد. رسائل دیگر و تحقیقاتی که در بسیاری از مسائل مشکله و مباحث معضله کرده است که اکثر آنها بحال مسوده باقی است و آنچه به بیاض رسیده زیاده از پانزده رساله میباشد. از آنجمله : صورة الخلاص فی سورة الاخلاص و غیره . طاش کبری زاده را اشعار تازی بسیار است از آن جمله چون ابوالسعود افندی جزئی از تفسیر خود را نوشت و برای طاش کبری زاده فرستاد، او این ابیات رادر پاسخ ابوالسعود ارسال داشت :<br />بنفسی جناباً حاز کل فضیلة<br />و صار لاظهار الحقائق ضامناً<br />و اید روح القدس حسان طبعه <br />فجلی من الابرار ما کان کامناً<br />و تافح عن عرض النبی تادباً<br />ففی الحشر یلقاه من الخوف آمناً<br />بک الملة الزهراء اضحت منیرة<br />ففی الکوکب السیار قد صرت ثامناً.<br />و این دو بیت نیز که در هر بیت مصراعی از قصیده ٔ معلقه ٔ امری ءالقیس را تضمین کرده از اوست :<br />وصلت حمی نجد ایا ریح شمأل <br />قفا نبک من ذکری حبیب و منزل <br />فوا اسفا رسم المدارس دارس <br />فهل عند رسم دارس من معول .<br /> <font color=\"Red\">(عقدالمنظوم حاشیه ٔ ج <span class=\"hlight\" dir=\"rtl\">٢</span> ابن خلکان ).</font><br />کتب ذیل نیز از تألیفات طاش کبری زاده است که چون در هیچیک از کتابهائی که ترجمه ٔ احوال او را نوشته اند دیده نشد از مجامیع دیگر نقل و در پایان این ترجمه ٔ احوال ثبت میگردد: شرح اخلاق عضدالدین الایجی . لذة السمع و استغراق المفرد والجمع. الاربعین . نوادر الاخبار فی مناقب الاخیار. روض الدقایق فی حضرات الحقائق . آداب البحث . النهل والعلل فی تخفیف اقسام العلل . مفتتّح الاعراب . غایه التحقیق، فی تقسیم العلم الی التصور والتصدیق . منیة الشبان فی معاشرةالنسوان . شرح منظومه ٔ فیضی در فرائض و به ترکی است .رسالة الشفاء فی دواء الوباء، رسالة در وقف نقود. رسالة در حکمت عملیه . رسالة در حمد. شرح مقدمة الصلوة. این اثر را بفناری نیز نسبت میدهند. حاشیه بر فرائض السراجیة.<br />زرکلی در اعلام آورده، که، طاش کبری زاده مورخ است و ترک نژاد مستعرب، در شهر بروسه تولد یافته، و مکرر بمناصب تدریس و قضاء منصوب گردیده، و آخرین شغلش قضاء حلب بوده در همان اوقات به نابینائی مبتلا شد. از تألیفات اوست : شقائق النعمانیة من علمأالدولة العثمانیة. این کتاب طبع شده است . مفتاح السعادة، طبع شده . نوادر الاخبار فی مناقب الاخیار. که معجمی است در تراجم، و هنوز به طبع نرسیده است . الشفاء فی دواء الوباء طبع شده است و رساله ٔ کوچکی است . الرسالة الجامعة لوصف العلوم النافعة. خطی است و طبع نشده است . (الاعلام ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br />مؤلف معجم المطبوعات پس از نقل خلاصه ٔ ترجمه ٔ احوالی که طاش کبری زاده بقلم خود نوشته گوید: و کان المترجم بحراً من المعارف و العلوم، متسنماً من الفضایل سنامها و غاربها مقیداً من المعانی شواردها و غرائبها. قیل ان تآلیفه تنیف علی الثلاثین، و کان ینظم الشعر العربی . از کتب او که به طبع رسیده فقط کتب ذیل را نام برده است : آداب البحث و المناظرة. این کتاب منظوم است و در ضمن مجموعی از مهمات فنون مکرر به طبعرسیده است . رسالة الشفاء لادواء الوباء. مؤلف این کتاب گفته که : املیتها نفعاً لکافة المسلمین فی امرالاعتقاد و صوناً لعقائد الامة فی حق هذه البلیة عن طرفی الاقتصاء. الخ . در مطبعه ٔ وهبیة به سال <span class=\"hlight\" dir=\"rtl\">١٢٩٢</span> به طبع رسیده است . شرح (طاش کبری زاده ) بر رساله ای که خود درآداب بحث و مناظره نوشته و در اسلامبول به طبع رسیده است . شرح بر فوائدالغیاثیة، در معانی و بیان که از تألیفات عضدالدین الایجی است . (علم بلاغت )، این کتاب نیز در اسلامبول به سال <span class=\"hlight\" dir=\"rtl\">١٣١٤</span> چاپ شده است . شقایق النعمانیة فی علماء الدولة العثمانیة. تألیف این کتاب به سال <span class=\"hlight\" dir=\"rtl\">٩٦٥</span> هَ . ق . خاتمه یافت، و تراجم احوال علما را به ده طبقه بخش کرده و من حیث المجموع پانصد و بیست و یک تن از علما را ذکر کرده که یکصد و پنجاه تن از آنان در ردیف اساتید و مشایخ، و بقیه از دانشمندان میباشند. این کتاب در حاشیه ٔ تاریخ ابن خلکان در دونوبت یکی به سال <span class=\"hlight\" dir=\"rtl\">١٢٩٩</span> و دیگری به سال <span class=\"hlight\" dir=\"rtl\">١٣١٠</span> به طبع رسیده است . مفتاح السعادة و مصباح السیادة؛ فی موضوعات العلوم . مؤلف در این کتاب انواع و اقسام علوم، و موضوع هر علمی، و نام کتبی که در آن علم تصنیف شده با اندکی از ترجمه ٔ احوال مصنفین کتب مصنفه را در هر فنی ذکر کرده، و به سال <span class=\"hlight\" dir=\"rtl\">١٣٢٨</span> در حیدرآباد دکن در دو جلد به طبع رسیده است . (معجم المطبوعات العربیة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢١</span>) و رجوع به احمدبن المصطفی و ابوالخیر در همین لغت نامه شود.<br /></font></div>'),
(175019, 'طاش کسان', '<span class=\"hlight\">طاش کسان .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) یا طاش کَسَن موضعی است در جنوب قره باغ .<br /></font></div>'),
(175020, 'طاش گدوک', '<span class=\"hlight\">طاش گدوک .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) موضعی است در جنوب تخت بنواحی شمالی بورد لیسک .<br /></font></div>'),
(175021, 'طاشتمر', '<span class=\"hlight\">طاشتمر.</span> <font color=\"DarkGreen\"><b>[ ت َ م ُ ]</font></b> (اِخ ) رجوع به طاشتمور شود.<br /></font></div>'),
(175022, 'طاشتمور', '<span class=\"hlight\">طاشتمور.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) در حاشیه ٔ تاریخ سیستان ذیل حدیث محمد واصل با یعقوب و محمد زیدویه آمده است : این محمدبن واصل، پس از بازگشت یعقوب از حرب علی بن الحسین بن قریش و تصرف فارس، از دربار خلافت مأمور عمل فارس و تصرف آنجا شده و بعد بر خلیفه بغی کرده به یعقوب گروید و عاقبت گردن کشی آغازنهاد و یکی از مشاهیر امرای عصر شد و سپاه بغداد راکه بریاست عبدالرحمن بن مفلح و طاشتمور بدفع وی گسیل شد بشکست و طاشتمر را در جنگ بکشت و ابن مفلح را اسیر کرد و بکشت و اهواز را هم ضمیمه ٔ فارس کرد و آنجاببود تا یعقوب بر او تاخت . (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٢٢٦</span>).<br /></font></div>'),
(175023, 'طاشتیمور', '<span class=\"hlight\">طاشتیمور.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) یکی از امراء عصر سلطان ابوسعید که با علی پادشاه آهنگ سؤقصد نسبت بسلطان مذکور کرده بودند. سلطان ابوسعید بوساطت مادر خود (حاجی خاتون ) علی پادشاه را بخشید و به او امر داد که بحدود بغدادبرود و طاشتیمور را که از همدستان او بود بمحاکمه به خواجه غیاث الدین وزیر و امرای دیگر سپرد. اما خواجه که مردی سلیم النفس بود، تصمیم داشت که بعموم دشمنان خود و پدر شهید خویش نیکی کند. با اینکه اطمینان یافت که عصیان امرا بیشتر بدشمنی او بود، از ابوسعید عفو طاشتیمور را گرفت و او را بخراسان فرستاد. طاشتیمور در نزدیکی ابهر زنجان به ناری طغای که بی اجازه عازم اردوی ایلخانی بود رسید و این دو امیر دست یکی کرده مصمم برداشتن دشمنان خود از میان شدند و خواجه غیاث الدین را که در این تاریخ با بغدادخاتون، زمامدار کلیه ٔ امور مملکتی بودند، خصم واقعی خود شمرده درصددقتل آن وزیر دانشمند برآمدند، و محرمانه علی پادشاه را هم بهمدستی خود دعوت کردند. طاشتیمور در قزوین منتظر انجام نقشه ٔ ناری طغای شد و ناری طغای برای تحصیل زمام امور به هر وسیله که باشد بسلطانیه آمد، لکن ابوسعید او را بار نداد و بغدادخاتون که او را مسبب قتل پدر حقیقی و برادر خود میدانست، سلطان را روزبروزبر او بیشتر متغیر میکرد. ناری طغای درصدد همدست کردن امرای مقیم اردوی ابوسعید با خود برآمد و قصه ٔ مواضعه ٔ علی پادشاه و طاشتیمور را بر مخالفت سلطان به ایشان خبر داد ولی ابوسعید که از ظلم و استبداد او درخراسان ناراضی بود بسخنان او التفات نکرد و امرای دیگر هم دعوت او را نپذیرفتند ناچار درصدد قتل خواجه غیاث الدین برآمد و از خواجه تقاضای ملاقات کرد و چون اجازه نیافت که با سلاح بخدمت خواجه رود در رسیدن بحضور وزیر از در عجز در آمده از وزیر خواست که سلطان را نسبت باو بر سر عنایت بیاورد. خواجه پذیرفت و مصمم شد که همان وقت برای انجام این مهم بخدمت ابوسعید رود. ناری طغاری بیرون آمده در خارج مدخل منزل وزیر درکمین او ایستاد ولی خواجه از در دیگر بیرون رفت و خیال زشت ناری طغای صورت عمل نیافت . چون خواجه بحضور ایلخان رسید و ملتمس ناری طغای را به عرض رسانید ابوسعید از پاک طینتی خواجه غیاث الدین تعجب کرده اندیشه ٔ سوء او را در حق خواجه به اطلاع او رساند و امر داد که ناری طغای را دستگیر کنند. ناری طغای که از این قصه خبر یافته بود از کوههای ابهر گریخته به ری آمد تا شاید خود را بخراسان برساند ولی او در آن حدود و طاش تیمور در محال قزوین دستگیر شدند و آن دو را در روز عید قربان سال <span class=\"hlight\" dir=\"rtl\">٧٢٩</span> در سلطانیه به امر ابوسعید سر بریدند و سرهای ایشان را بجای سر دمشق خواجه از قلعه ٔ سلطانیه فروآویختند. (تاریخ مغول اقبال ص <span class=\"hlight\" dir=\"rtl\">٣٤٢</span> و <span class=\"hlight\" dir=\"rtl\">٣٤٣</span>).<br /></font></div>'),
(175024, 'طاشکندی', '<span class=\"hlight\">طاشکندی .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) محمد. او راست : شرح باب الصرف از کتاب میزان الادب، تألیف عصام الدین اسفراینی . این شرح، با اصل کتاب باب الصرف به سال <span class=\"hlight\" dir=\"rtl\">١٢٩٠</span> هَ . ق . در وادی النیل مصر به طبع رسیده است . شرح دیگری هم بر کتاب میزان الادب نوشته که با اصل میزان الادب به سال <span class=\"hlight\" dir=\"rtl\">١٢٨٦</span> در اسلامبول طبع شده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢٢</span>).<br /></font></div>'),
(175025, 'طاشی', '<span class=\"hlight\">طاشی ٔ.</span> <font color=\"DarkGreen\"><b>[ ش ِءْ ]</font></b> (ع ص ) اسم فاعل از ماده ٔ طشاء. مبتلا به زکام .<br /></font></div>'),
(175026, 'طاط', '<span class=\"hlight\">طاط.</span> (ع ص ) مرد دراز. (مهذب الاسماء) (منتخب اللغات ). مرد درازبالا. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مرد سخت خصومت . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> مرد متکبر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دلاور. (منتهی الارب ). شجاع . (اقرب الموارد). مرد دلیر. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> گشن تیزشهوت . (منتهی الارب ). گشن با بانگ . (منتهی الارب ). شتر مست . (مهذب الاسماء). شتر نر که برای گشنی مست شده باشد. (منتخب اللغات ). ج، اطواط.<br /></font></div>'),
(175027, 'طاط', '<span class=\"hlight\">طاط.</span> (اِخ ) نام مردی که هرمس یکی از کتب خود را در صناعت کیمیا بدو خطاب کرده . (فهرست ابن الندیم ).<br /></font></div>'),
(175028, 'طاط', '<span class=\"hlight\">طاط.</span> (اِخ ) نام صاب پسرحضرت ادریس پیغمبر است که طبق روایات، فرقه ٔ صابی را به او منسوب دانسته اند. (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٥</span>).<br /></font></div>'),
(175029, 'طاطاربالا', '<span class=\"hlight\">طاطاربالا.</span> (اِخ ) دهی از دهستان آتابای بخش مرکزی شهرستان گنبدقابوس . در <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی جنوب باختری گنبد و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی شمال شوسه ٔ گنبد به گرگان . دشت معتدل مالاریائی، با<span class=\"hlight\" dir=\"rtl\">٢٦٠</span> تن سکنه . آب آن از چاه . محصول آنجا غلات دیمی و حبوبات و صیفی و لبنیات . شغل اهالی زراعت و گله داری . صنایع دستی زنان قالیچه بافی و راه آن مالرو است . چادرنشین هستند و تغییر مکان میدهند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175030, 'طاطارقان یخمز', '<span class=\"hlight\">طاطارقان یخمز.</span> <font color=\"DarkGreen\"><b>[ ی ُ م َ ]</font></b> (اِخ ) دهی از دهستان آتابای بخش مرکزی شهرستان گنبدقابوس . در <span class=\"hlight\" dir=\"rtl\">٨</span>هزارگزی جنوب گنبد کنار راه گنبد به گرگان . دشت، معتدل با <span class=\"hlight\" dir=\"rtl\">١٩٠</span> تن سکنه . آب آن ازچاه . محصول غلات و حبوبات و صیفی و لبنیات . شغل اهالی زراعت و گله داری . صنایع دستی زنان قالیچه بافی است .چادرنشین هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175031, 'طاطالیس', '<span class=\"hlight\">طاطالیس .</span> (ع اِ) تشنج عام .<br /></font></div>'),
(175032, 'طاطری', '<span class=\"hlight\">طاطری .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) از متکلمین شیعه است و کتاب الامامة از اوست . (ابن الندیم ). ابوسهل اسماعیل بن علی بن النوبخت النوبختی را کتابی است بنام کتاب الرد علی الطاطری فی الامامة. (ابن الندیم ).<br /></font></div>'),
(175033, 'طاطری', '<span class=\"hlight\">طاطری .</span> <font color=\"DarkGreen\"><b>[ری ی ]</font></b> (ع ص ) نسبتی است که در زبان عامه افاده ٔ معنی کرباس فروش و فروشنده ٔ هر جامه ٔ سپیدی میکند. (سمعانی ). یاقوت گوید: لا ادری این هی . و فی کتاب الشام ؛ انبأنا ابوعلی الحداد، انبأنا ابوبکربن زیدة، انبأنا سلیمان بن احمد؛ کُل ُ من یبیع الکرابیس بدمشق، یسمی الطاطری . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span>). رجوع به طاطریة شود.<br /></font></div>'),
(175034, 'طاطریة', '<span class=\"hlight\">طاطریة.</span> <font color=\"DarkGreen\"><b>[ ی ی َ ]</font></b> (ع اِ) نوعی از جامه . رجوع به طاطری شود.<br /></font></div>'),
(175035, 'طاطس', '<span class=\"hlight\">طاطس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) چوب صنوبر است که مانند مشعل مشتعل شود. (فهرست مخزن الادویة).<br /></font></div>'),
(175036, 'طاطم', '<span class=\"hlight\">طاطم .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) رجوع به نفر (ایل ) شود.<br /></font></div>'),
(175037, 'طاطوف', '<span class=\"hlight\">طاطوف .</span> (ص ) زن پیر و گنده باشد. (کذا فی التحفة). رجوع به تلاتوف شود.<br /></font></div>'),
(175038, 'طاطی', '<span class=\"hlight\">طاطی .</span> (اِخ ) یکی از شاگردان هرمس المثلث بالحکمة بوده است . (قفطی ص <span class=\"hlight\" dir=\"rtl\">١٥٠</span>).<br /></font></div>'),
(175039, 'طاطیاوس', '<span class=\"hlight\">طاطیاوس .</span> (معرب، اِ) اسم یونانی نوره است .<br /></font></div>'),
(175040, 'طاع', '<span class=\"hlight\">طاع .</span> (ع ص ) فرمانبردار. (منتهی الارب ).<br /></font></div>'),
(175041, 'طاعات', '<span class=\"hlight\">طاعات .</span> (ع اِ) ج ِ طاعة، طاعت . رجوع به طاعت شود. رسول را بر جمله ٔ طاعات بازگردانید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٠</span>).<br /></font></div>'),
(175042, 'طاعة', '<span class=\"hlight\">طاعة.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص ) طاعت . رجوع به طاعت شود. نزد فرقه ٔ معتزلة سازواری با خواست حق و نزد اهل سنت و جماعت سازواری با فرمان حق است، بی آنکه با خواست او عزاسمه سازوار باشد و مورد اختلاف در این باره آن است که آیا واجب است مأموریت مطمح خواست حق واقع شود یا نه ؟ معتزله برآنند که واجب است و اهل سنت گویند واجب نیست چه حق تعالی گاهی بغیر آنکه به اراده ٔ خود نظری داشته باشد فرمان میدهد مانند آنکه ابولهب را به ایمان فرمان داد با آنکه میدانست صدور ایمان از ابولهب محال باشد. و کسی که بمحال بودن چیزی عالم باشد البته آنچیز را مطمح خواست خود قرار ندهد. پس ثابت شد که فرمان دادن ممکن است بدون خواست و اراده باشد بنابراین باید یقین کرد که فرمانبرداری حق عبارت است از سازواری با فرمان او نه سازواری با خواست او جل شأنه . چنانکه این مطلب از تفسیر کبیر امام فخر مستفاد میشود، در تفسیر این آیه ٔ مبارکه : یا ایهاالذین آمنوا اطیعوااﷲ و اطیعواالرسول . (قرآن <span class=\"hlight\" dir=\"rtl\">٣٢/٣</span>). و طاعت اعم از عبادت است زیرا لفظ عبادت غالباً در مورد بزرگداشت حق جل ذکره استعمال میشود آن هم در غایت تعظیم . و طاعت درسازواری با فرمان خدای و فرمان غیر خدای نیز استعمال گردد و عبودیت اظهار فروتنی و خود را خوار شمردن باشد. از این رو عبادت از حیث معنی رساتر از طاعت است چه عبادت، بتعبیر دیگر عبارت است از تذلل، و طاعت عمل به امر و ترک آنچه نهی شده است، هر چند از روی کراهت باشد. پس اداء وام، و انفاق زن و مانند آن را، فرمانبرداری خدای نامند نه پرستش حق . و روا باشد استعمال طاعت در مورد مخلوق آنهم در غیر معصیت و استعمال عبادت و پرستش در غیر مورد خالق نارواست . اما لفظ قربت از طاعت هم اخص است، لاعتبار معرفة المتقرب الیه فیها و عبادت از قربت و طاعت هم اخص باشد. کذا فی کلیات ابی البقاء. (از کشاف اصطلاحات الفنون ) <span class=\"hlight\">:</span> فجلس مجلساً عاماً بحضرة اولیاء الدعوة... فرغبوا الی امیرالمؤمنین فی القیام بحق اﷲ فیهم، و التزموا ما اوجبه اﷲ من الطاعة علیهم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٠١</span>).<br /></font></div>'),
(175043, 'طاعت', '<span class=\"hlight\">طاعت .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص ) بندگی . (منتهی الارب ). فرمان بردن . (آنندراج ).فرمانبرداری . (مهذب الاسماء). اطاعت . انقیاد. عبودیت . طوع . اِقَه . طواعیة. پرستش . عبادت . بِرّ. دین . ماعون . فرمان <span class=\"hlight\">:</span> قوله تعالی، لهم طاعة و قول معروف . (قرآن <span class=\"hlight\" dir=\"rtl\">٢٠/٤٧</span> و <span class=\"hlight\" dir=\"rtl\">٢١</span>) مراد بطاعت، امتثال فرمان خداست . (تفسیر ابوالفتوح رازی ). ج، طاعات <span class=\"hlight\">:</span> <br />نکنی طاعت و آنگه که کنی سست و ضعیف <br />راست گوئی که همه سخره و شاکار کنی .<br /> <font color=\"Red\">کسائی .</font><br />طبایع گر ستون تن، ستون را هم بپوسد بن <br />نگردد آن ستون فانی، کش از طاعت زنی فانه .<br /> <font color=\"Red\">کسائی .</font><br />طاعت تو چون نماز است و هر آنکس کز نماز<br />سر بتابد بیشک او را کرد باید سنگسار.<br /> <font color=\"Red\">فرخی .</font><br />طاعت خلق باد باشد باد<br />کس گرفتار باد هیچ مباد.<br /> <font color=\"Red\">فرخی .</font><br />ولایت هرات مارا داد و ولایت گوزگانان به برادر ما، پس آنگه او راسوگند داده بودند که در فرمان و طاعت ما باشد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢١٤</span>). اعیان هر دو بطن از بنی هاشم، علویان و عباسیان بر طاعت و متابعت وی بیارامیدند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٨٧</span>) فجلس مجلساً عاماً بحضرة اولیاء الدعوة... فرغبوا الی امیرالمؤمنین فی القیام بحق اﷲ فیهم، و التزموا ما اوجبه اﷲ من الطاعة علیهم . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٠١</span>). الزام نمودند مارا آنچه خداوند بر ایشان واجب ساخته از طاعت امام بواسطه ٔ بیعت . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣١٢</span>). به دست گیرم آنچه را با خدا پیوسته ام بر آن به دست گرفتن اهل طاعت، و اهل حق و وفاء، حق و وفاء خود را. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣١٧</span>). وصیت کنم شما را که خدای عز ذکره را به یگانگی شناسید و وی را طاعت دارید. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٢٨</span>). شحنه علی تکین به بدبوس گریخت، وغازیان ماوراءالنهر و مردم شهر بطاعت پیش آمدند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٤٨</span>). و اگر کشته شوم رواست در طاعت خداوند خویش شهادت یابم . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٥٠</span>). به ضرورت بتوان دانست که از آن دو تن کدام کس را طاعت باید داشت . (تاریخ بیهقی ). پادشاهان را چون دادگر و نیکوکردار و نیکوسیرت و نیکوآثار باشند طاعت باید داشت . (تاریخ بیهقی ). و مردم شهر بطاعت پیش آمدند، و دولت عالی را بندگی نمودند. (تاریخ بیهقی ). دلهای رعیت و لشکری بر طاعت ما بیارامید. (تاریخ بیهقی ). اعیان و مقدّمان بنشسته بودند، و طاعت و بندگی نموده . (تاریخ بیهقی ). من که آلتون تاشم جز بندگی و طاعت راست ندارم . (تاریخ بیهقی ). و ستوده آن است که قوت آرزو و خشم در طاعت قوّت خرد باشد. (تاریخ بیهقی ). رسول فرستاد، و زیاده طاعت و بندگی نمود. (تاریخ بیهقی ). ما در این هفته حرکت خواهیم کرد <font color=\"DarkGreen\"><b>[ مسعود ]</font></b>...جهانی در هوی و طاعت ما بیارامیده . (تاریخ بیهقی ) <font color=\"DarkGreen\"><b>[رعیت ]</font></b> باید که از پادشاه و لشکر بترسند ترسیدنی تمام و طاعت دارند. (تاریخ بیهقی ).<br />چون تو دو چیزی بتن و جان خویش <br />طاعت بر جان و تن تو دوتاست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از طاعت تمام شود ای پسر ترا<br />این جان ناتمام سرانجام کار تام .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تا تن من طاعت او یافته ست <br />طاعت دارد همی اهریمنم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />این عورت بود آنکه پیدا شد<br />در طاعت دیو از آدم و حوا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />مر آن راست فردا نعیم اندرو<br />که امروز بر طاعتش صابریست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بنگر آن را در رکوع و بنگر آن را در سجود<br />پس همین کن تو ز طاعتها که می ایشان کنند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />خار و سنگ دره ٔ یمکان از طاعت تو<br />در دماغ و دهن بنده ات عود و شکر است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آنها که ندانند بطاعت حق روزی <br />بر جور و جفااند، نه بر عدل و وفااند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />گفتمت بنده را که به بی طاعتی بکش <br />وانگه بکشت ار تو نبودی بطاعتش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای آنکه ترا یار نبوده ست و نباشد<br />در طاعت تو جز تو کسی نیست مرایار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />وز طاعت خورشید همی روز و شب آید<br />کو سوی خرد علت روز است و شب تار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />طاعت ارکان ببین مر چرخ و انجم را بطبع<br />تا بطاعت چرخ و انجمشان همی حیوان کنند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />گر مردمی تو طاعت یزدان کن <br />تا از عذاب آتش نازاری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و آنجا نرود مگر که طاعت <br />نه مهتری و نه با فلانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />سنگ یمکان دره زی من رهی از طاعت <br />فضلها دارد بر لؤلؤ عمانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />اکنونت دراز کرد میباید<br />طاعت که گرفت عمر کوتاهی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آن را که او اسیر کند طاعت <br />تیر هوای دل نکند خسته .<br /> <font color=\"Red\">ناصرخسرو.</font><br />من نه همی طاعت از آن دارمش <br />تا می و شیرم دهد و انگبین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />خدای از تو دانش بطاعت پذیرد<br />مبر پیش او طاعت جاهلانه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گر نبدی فضل خدا و رسول <br />کی ز کسی طاعت و نیکیستی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />طاعت بگمانی بنمایدت و لیکن <br />لعنت کندت گر نشود راست گمانیش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />سی سال پادشاهی کرد، و دیوان را در طاعت آورد. (نوروزنامه ).<br />بسته ٔ طاعت تو گردون باد<br />گیتی از نعمت تو قارون باد.<br /> <font color=\"Red\">مسعودسعد.</font><br />درگهش کعبه شد که طاعت خلق <br />چو بسنت کنند مبرور است .<br /> <font color=\"Red\">مسعودسعد.</font><br />و دوست و دشمن در ربقه ٔ خدمت و طاعت ملوک جمع شوند. (کلیله و دمنه ).و مطاوعت ایشان را بطاعت خویش و رسول خود ملحق گردانید. (کلیله و دمنه ). و جباران روزگار در ربقه ٔ طاعت و خدمت کشید. (کلیله و دمنه ). و هوی و طاعت اخلاص و مناصحت ایشان را از لوازم دین شمرد. (کلیله و دمنه ).هر که طاعت را شعار خویش کند از ثمرات دنیی و عقبی بهره ور گردد. (کلیله و دمنه ). و بدانند که طاعت ملوک و خدمت پادشاهان فاضلتر اعمال است . (کلیله و دمنه ).آخر رای من بر عبادت قرار گرفت، چه مشقت طاعت در جنب نجات آخرت وزنی ندارد. (کلیله و دمنه ). و عقل مرد را به هشت خصلت بتوان شناخت ... سوم ؛ طاعت پادشاه عادل . (کلیله و دمنه ). و دلهای خواص و عوام ... بر طاعت و عبودیت بیارامید. (کلیله و دمنه ). و شرف سعادت خویش در طاعت و متابعت او شناختند. (کلیله و دمنه ).<br />می خوری به کز ریا طاعت کنی <br />گفتم و تیر از کمان آید برون .<br /> <font color=\"Red\">خاقانی .</font><br />که بعد طاعت قرآن و سجده در کعبه <br />پس از درود رسول و صحابه در محراب .<br /> <font color=\"Red\">خاقانی .</font><br />حق طاعت وضراعت او به تیسیر اَمَل و تقریر عمل به ادا رسانید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٣٦</span>). خواست تا ناحیت غرشستان را بتدبیر خویش گیرد، و شار را بطاعت آرد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>).<br />طاعت کند سرشک ندامت گناه را<br />باران سپید میکند ابر سیاه را.<br /> <font color=\"Red\">مولوی .</font><br />طاعت عامه گناه خاصگان <br />وصلت عامه حجاب خاص دان .<br /> <font color=\"Red\">مولوی .</font><br />عابدان جزای طاعت خواهند، و بازرگانان بهای بضاعت . (گلستان ).<br />طاعت آن نیست که بر خاک نهی پیشانی <br />صدق پیش آر که اخلاص به پیشانی نیست .<br /> <font color=\"Red\">سعدی .</font><br />عذر تقصیر خدمت آوردم <br />که ندارم بطاعت استظهار.<br /> <font color=\"Red\">سعدی .</font><br />شاه را بی نفاق طاعت کن <br />بقبولی از آن قناعت کن .<br /> <font color=\"Red\">اوحدی .</font><br />در دل دوست به هر حیله رهی باید کرد<br />طاعت از دست نیاید گنهی باید کرد.<br /><font color=\"Red\">نشاط معتمدالدوله .</font><br /></font></div>'),
(175044, 'طاعت داشتن', '<span class=\"hlight\">طاعت داشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (مص مرکب ) فرمان بردن . گوش بر فرمان داشتن <span class=\"hlight\">:</span> بیکدیگر مشغول شوند، و همگان طاعت تو دارند. (فارسنامه ٔ ابن البلخی ).<br /></font></div>'),
(175045, 'طاعت دوست', '<span class=\"hlight\">طاعت دوست .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص مرکب ) دوستدار طاعت . گوش بر فرمان <span class=\"hlight\">:</span> <br />زن پرهیزکار طاعت دوست <br />با تو چون مغز باشد اندرپوست .<br /><font color=\"Red\">اوحدی .</font><br /></font></div>'),
(175046, 'طاعت نمای', '<span class=\"hlight\">طاعت نمای .</span> <font color=\"DarkGreen\"><b>[ ع َ ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ ]</font></b> (نف مرکب ) آن که فرمانبری بنماید. که فرمانبری آشکار دارد <span class=\"hlight\">:</span> <br />فرمانگذار دلبر طاعت نمای من <br />طاعت نمای داده بفرمان گذار دل .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(175047, 'طاعت نمود', '<span class=\"hlight\">طاعت نمود.</span> <font color=\"DarkGreen\"><b>[ ع َ ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ ]</font></b> (مص مرکب مرخم ) فرمانبری نشان دادن . اظهار طاعت کردن <span class=\"hlight\">:</span> رسول به نزدیک امیر اسماعیل آمد و نامه بداد و از طاعت نمود امیر بلخ و گورکانیان خبر داد. (تاریخ بخارا).<br /></font></div>'),
(175048, 'طاعت پیشه', '<span class=\"hlight\">طاعت پیشه .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) طاعت ور. (آنندراج ). عابد.<br /></font></div>'),
(175049, 'طاعتدار', '<span class=\"hlight\">طاعتدار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص مرکب ) مطیع. حاضرفرمان <span class=\"hlight\">:</span> پسر را بدرگاه عالی فرستد وبنده و طاعتدار باشد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٩٩</span>).<br /></font></div>'),
(175050, 'طاعتداری', '<span class=\"hlight\">طاعتداری .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (حامص مرکب ) مواظبت و مراقبت درامر فرمانبرداری <span class=\"hlight\">:</span> توان دانست که اعتقاد وی در دوستی و طاعتداری تا کدام جایگاه باشد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٨٢</span>). تا علی برادرش حسن بوئی را پیش او فرستاد به نوا، و طاعتداری نمود. (مجمل التواریخ والقصص ). معتضد (خلیفه ) را عظیم خوش آمد آن طاعت داری . (مجمل التواریخ و القصص ). ابرهه رسول فرستاد، و عذرخواست، و بندگی و طاعت داری پیدا کرد. (مجمل التواریخ و القصص ). و در کتاب سیر گفته است که گشتاسب او را طاعت داری کرد تا بگذشت . (مجمل التواریخ و القصص ).<br /></font></div>'),
(175051, 'طاعتور', '<span class=\"hlight\">طاعتور.</span> <font color=\"DarkGreen\"><b>[ ع َ وَ ]</font></b> (ص مرکب ) آن که فرمانبری پیشه دارد <span class=\"hlight\">:</span> <br />به دست همت طاعتوران رها کردم <br />در اولین قدم اسباب خلد و حور و قصور.<br /><font color=\"Red\">محمد عرفی (از آنندراج ).</font><br /></font></div>'),
(175052, 'طاعتگاه', '<span class=\"hlight\">طاعتگاه .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ مرکب ) طاعتگه . معبد. پرستشگاه . جایگاه عبادت . مقام پرستش <span class=\"hlight\">:</span> <br />یکی دیر سنگین برافراشتند<br />بجمهور طاعت گهش ساختند.<br /> <font color=\"Red\">نظامی .</font><br />الهی در طاعتم باز کن <br />بطاعت گهم محرم راز کن .<br /> <font color=\"Red\">عبداﷲ هاتفی .</font><br /><BR><font color=\"Blue\">◄</font> جایگاه قربانی . محل مخصوص قربانی . منسک . قربانی جای . (منتهی الارب ).<br /></font></div>'),
(175053, 'طاعل', '<span class=\"hlight\">طاعل .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) تیر راست . (منتهی الارب ). السهم المقوم . (اقرب الموارد).<br /></font></div>'),
(175054, 'طاعلة', '<span class=\"hlight\">طاعلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) جائی است در اندلس . (معجم البلدان ).<br /></font></div>'),
(175055, 'طاعم', '<span class=\"hlight\">طاعم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) بی نیاز. یقال : هو طاعم عن طعامکم ؛ ای مستغن . <BR><font color=\"Blue\">◄</font> خورنده . <BR><font color=\"Blue\">◄</font> چشنده . <BR><font color=\"Blue\">◄</font> مرد نیکوحال در مطعم و مأکل . (منتهی الارب ). آنکه در خورش حال خوشی داشته باشد. (منتخب اللغات ) <span class=\"hlight\">:</span> قل لااجد فیما اوحی الی محرما علی طاعم یطعمه الا ان یکون میتة او دماً مسفوحاً او لحم خنزیر؛ بگو این کافران را که من نمییابم در این قرآن که بر من وحی کرده و فرود آورده هیچ طعامی حرام بر کسی که خورد الا که مرداری باشد یا خون ریخته یا گوشت خوک . (تفسیر ابوالفتوح سوره ٔ انعام <span class=\"hlight\" dir=\"rtl\">١٤٥/٥</span>).<br />دع المکارم لاترحل لبغیتها<br />واقعد فانک انت الطاعم الکاسی .<br /><font color=\"Red\">حطیئة، شاعر عرب (از تاریخ بیهقی ).</font><br /></font></div>'),
(175056, 'طاعن', '<span class=\"hlight\">طاعن .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) نیزه زننده . <BR><font color=\"Blue\">◄</font> طعنه زننده . (کنز اللغات ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br />طاعن و بدگوی اندر سخنش بی سخنند<br />ور چه باشد سخن طاعن و بدگوی ذمیم .<br /> <font color=\"Red\">فرخی .</font><br />اگر طاعنی یا حاسدی گوید که اصل بزرگان این خاندان بزرگ از کودکی آمده است خامل ذکر، جواب وی این است که ایزدتعالی تقدیر چنین کرده است که ملک را انتقال می افتد از آن ملت بدین ملت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٧٧٩</span>). اگر طاعنی گوید که اگر آرزو و خشم نبایستی خدای در تن مردم بیافریدی جواب آن است که ... (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤١٦</span>). ایشان میان بسته اند تا بهیچ حال خللی نیفتد که دشمنی و حاسدی و طاعنی شاد شود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٨٩٩</span>).<br />جهد اسب بر سینه والرمح طاعن <br />شود گرد در دیده و السیف ضارب .<br /> <font color=\"Red\">(منسوب به حسن متکلم یا برهانی یا معزی ).</font><br />به یمن قدم درویشان ... ذمائم اخلاق بحمائد مبدل گشت ... و زبان طاعنان در حق او همچنان دراز که بر قاعده ٔ اول است . (گلستان ).<br /></font></div>'),
(175057, 'طاعون', '<span class=\"hlight\">طاعون .</span> (ع اِ) مرگامرگی . ج، طواعین . (منتهی الارب ). شآمت و مرگ عام . (لطایف ). <BR><font color=\"Blue\">◄</font> وبا. (دهار). داءالشوکة که مرضی است الیافی عام و کشنده . <BR><font color=\"Blue\">◄</font> دبل . زقمة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مجازاً شعرا آن را به معنی تلخ و طاعون و طاعونی را به معنی تلخی به کار برده اند <span class=\"hlight\">:</span> <br />آن را که نوش و شهد و شکر بودی <br />امروز زهر و حنظل و طاعونی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />جیحون خوش است و بامزه و دریا<br />از ناخوشی و زهر چو طاعون است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />به یکی جاهل اگر بیم کند نوشت <br />نوش کی گردد آن شربت طاعونی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />لفظ طاعون در فارسی گاه بصورت مصدر مرکب استعمال شود و در حالی که (لازم ) باشد با مصدر گرفتن و چون متعدی بود با مصادر زدن و رسیدن به کار رود: فلانی طاعون گرفت (لازم ). فلان را طاعون زد یا طاعون رسید. (متعدی ). <BR><font color=\"Blue\">◄</font> جوش . بثره ای باشد کوچک، مانند باقلا سرخ یا سیاه با سوزش بسیار. (غیاث از بحرالجواهر). بثره ای باشدبقدر کُنار صحرائی با کبودی و سوزش و تب وبائی لازم اوست . (غیاث از حدود الامراض ). <BR><font color=\"Blue\">◄</font> ورمی بودکه در خصیه یا پستان یا بغل یا بن ران واقع شود، ازماده ای سمی که عضو را فاسد کند و قی و غثیان و خفقان همراه آن بود. (غیاث از کفایة منصوری ). هر آماس که در گوشت نرم افتدی . چون گوشت پس گوش یا در گوشت غددی چون پستان و خایه و گوشت بن زفان یا در جایگاهی فراخ چون بغل دست و بیغوله ٔ ران، آن را طاعون گویند. پس اتفاق بر آن کردند که طاعون آماس گرم را گویند که در جایها افتد. و حرارت و سوزانیدن آن از اندازه بیرون بود. و ماده ٔ آن مستحیل گشته باشد. و همچون زهری شده و عضو را تباه کند. و رنگ او رنگ حوالی او بگرداند، و مضرت آن بطریق شریانها به دل باز دهد، و خفقان و غشی آرد، طاعون آن را گویند. علامتها: آنچه در گوشت پس گوش و در بغل و در پستان افتد کشنده باشد از بهر آنکه به دماغ و به دل نزدیک بود و آنچه رنگ او سرخ بود یا بزردی گراید سلیم تر باشد و آنچه بسیاهی گراید سخت بد باشد. و طاعون اندر هواهای بد و سالهای وبائی و اندر شهرها که آنجا بیشتر بود بسیار افتد. (ذخیره ٔ خوارزمشاهی ). طاعون، بالیونانیة کل ورم یظهر للحس ثم حصص بالحار القتال السریع التعفن . الکائن فی نحوالمراق والمغابن و یطلق علی الوباء للتلازم الحاصل بینهما غالباً و الا فبینهما عموم و خصوص و جهیان و هوفی الحقیقة بثر کالباقلا فازید مادته الدم المتعفن و فاعله الحرارة الناریة و صورته شی ٔ مستدیر ینزف الدم و الصدید و غایته ازهاق النفس و شره ما فی الابط الشمال لمجاورته القلب فالفخذ الایمن فالابط الایمن فالفخذ الایسر، فالعنق علی الاصح . و قیل آلاباط شر من الفخذین هذا من حیث المکان و من حیث الزمان ما کان عند زیادة الدم و هیجانه و ذلک فی الایام الربیعیة و لو فی الخریف و من حیث اللون الاسود الکمد فالاخضر فالاصفر فالاحمرو متی قارنته حمی و اختلاط عقل و تواتر فی النفس و النبض فمهلک لامحالة لان الکیفیة الردیئة قداتصلت بالقلوب و اسرع الناس هلاکاً به الاطفال فالاغراب خصوصاً نحوالزنجی والهندی لضعف المزاج بکثرة التحلیل فالدموی فالصفراوی و ندر فی السوداوی و هو وبائی فی الاصح من العامة و حقیقته اجتماع بخارات عفنة تصعد بالامطار فی الازمنة الصیفیة و اسبابه حکمیة کثرة الرطوبة و الحرارة و یبس الشتاء و کون السنة ربیعیة و کثرة الملاحم فیعفن الهواء بدم القتلی فیلقی فی الحیوان و الثمار و المیاه و تؤکل فیفسد الدم و تجمعه الی المواضع الرخوة خراجاً ان اشتدت الرطوبة و الافنفاطات نزافة. (داود انطاکی ص <span class=\"hlight\" dir=\"rtl\">١٥٢</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">روی چون طاعون داشتن و روی چون طاعون کردن </span> ؛ کنایه از ترشروئی که شعرا در شعر به کار برده اند <span class=\"hlight\">:</span> <br />آن کنی از بیهشی کز شرم آن گر بررسی <br />وقت هشیاری ز انده روی چون طاعون کنی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />زهد چبْود؟ هر چه جز حق روی از آن برتافتن <br />زهد نبود، روی چون طاعون و قطران داشتن .<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(175058, 'طاعون بقری', '<span class=\"hlight\">طاعون بقری .</span> <font color=\"DarkGreen\"><b>[ ن ِ ب َق َ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به گاومرگی شود.<br /></font></div>'),
(175059, 'طاعون جارف', '<span class=\"hlight\">طاعون جارف .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) نام طاعونی است که در زمان ابن الزبیر رخ داد.<br /></font></div>'),
(175060, 'طاعون زده', '<span class=\"hlight\">طاعون زده .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) طعین . مطعون . ناقةٌ بها عسفات ؛ شتر ماده ٔ طاعون زده . ناقةٌ عاسف ؛ شتر ماده ٔ طاعون زده . (منتهی الارب ).<br /></font></div>'),
(175061, 'طاعون عمواس', '<span class=\"hlight\">طاعون عمواس .</span> <font color=\"DarkGreen\"><b>[ ن ِ ع َم ْ ]</font></b> (ترکیب اضافی، اِ مرکب ) نخستین طاعونی است که در دوره ٔ اسلام پیدا شد.<br /></font></div>'),
(175062, 'طاعون غراب', '<span class=\"hlight\">طاعون غراب .</span> <font color=\"DarkGreen\"><b>[ ن ِ غ ُ ]</font></b> (اِخ ) طاعونی که در زمان ولیدبن یزید حادث شد. و وجه تسمیه ٔ آن آن است که نخستین کس که بدین بیماری بمرد مردی غراب نام بود.<br /></font></div>'),
(175063, 'طاعون فتیات', '<span class=\"hlight\">طاعون فتیات .</span> <font color=\"DarkGreen\"><b>[ ن ِ ف َ ت َ ]</font></b> (اِخ ) آن را طاعون اشراف نیز گویند، در زمان حجاج بروز کرد. و از آن رو بدین دو نام خوانده شده است که بسیاری از دوشیزگان و اشراف بدان هلاک شدند.<br /></font></div>'),
(175064, 'طاعون گاو', '<span class=\"hlight\">طاعون گاو.</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به گاومرگی شود.<br /></font></div>'),
(175065, 'طاعونی', '<span class=\"hlight\">طاعونی .</span> (ص نسبی ) طاعونیة. منسوب به طاعون ؛ هوای طاعونی . خیارک ِ طاعونی .<br /></font></div>'),
(175066, 'طاعیة', '<span class=\"hlight\">طاعیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) زن بیمارجگر. (منتهی الارب ).<br /></font></div>'),
(175067, 'طاغ', '<span class=\"hlight\">طاغ .</span> (ع اِ) تاغ . طاق . غضاة. درختی است . (منتهی الارب ) <span class=\"hlight\">:</span> الا ان اﷲ عزوجل قد لطف بهم فی الحطب و ارخصه علیهم حمل عجلة من حطب الطاغ و هو الغضاء بدرهمین . (معجم البلدان ذیل کلمه ٔ خوارزم ). عرفطة صلعاء؛ طاغ که سرهای شاخ وی رفته باشد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> هیزم . رجوع به طاق شود.<br /></font></div>'),
(175068, 'طاغ طاغ', '<span class=\"hlight\">طاغ طاغ .</span> (اِ صوت مرکب ) آواز نعل درشت، کوفتن پتک و مانند آن .<br /></font></div>'),
(175069, 'طاغا', '<span class=\"hlight\">طاغا.</span> (اِ) عرعر.<br /></font></div>'),
(175070, 'طاغدانه', '<span class=\"hlight\">طاغدانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) رجوع به «طاقدانه » شود. <BR><font color=\"Blue\">◄</font> قرنوس . قرانینا. آل . راهن . سرخک .<br /></font></div>'),
(175071, 'طاغنکوه', '<span class=\"hlight\">طاغنکوه .</span> <font color=\"DarkGreen\"><b>[ غ ُ ]</font></b> (اِخ ) از بلوکات ولایت نیشابور، مرکز قره باغ، حد شمالی یار معدن، شرقی عشق آباد، جنوبی یاکوه، و غربی اربقائی . عده ٔ قری <span class=\"hlight\" dir=\"rtl\">١٨</span>. مساحت آن <span class=\"hlight\" dir=\"rtl\">٣٠</span> فرسخ است .<br /></font></div>'),
(175072, 'طاغو', '<span class=\"hlight\">طاغو.</span> (اِخ ) قریه ای است از محال استرآباد. (حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175073, 'طاغوت', '<span class=\"hlight\">طاغوت .</span> (ع اِ) لات . عزی . بت . (منتهی الارب ). نصب . بدّ نصب . صنم . وثن . جبت . <BR><font color=\"Blue\">◄</font> جادوگر. ساحر. شیطان . دیو. جادو. کاهن . <BR><font color=\"Blue\">◄</font> هر باطل . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> هر چه جز خدا که آن را پرستند. (منتهی الارب ). هرچه آن را پرستند جز خدای عز و جل . (زمخشری ). آنچه پرستند بجز خدای تعالی . (مهذب الاسماء). آنچه پرستند دون از خدای تعالی . (السامی ). هرچیز که پرستند سوای خدای تعالی . <BR><font color=\"Blue\">◄</font> سرکش از اهل کتاب . (منتهی الارب ). مَرَدَه ٔ اهل کتاب . واحد و جمع در وی یکسان است . ج، طواغیت، طواغ . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مَرَدَه از جن . جن مارد. <BR><font color=\"Blue\">◄</font> هر پیشوائی در گمراهی و ضلال . مضل . گمراه کننده . سر و پیشرو ضلالی، صارف از طریق خیر. و در کلام مشایخ است : کل ما شغلک عن الحق فهو طاغوتک . (آنندراج ). و بعقیده ٔ نگارنده، این کلمه از ماده ٔ طغیان می آید، به معنی تورانی است و جبت نیز از قبط است، و عرب زشتی و ظلم تورانی را بوسیله ٔ ایرانیان و قبط را بوسیله ٔ یهود شناخته است، و بعید نیست مراد از طاغوت، خدای مصریان، همان «طُت » یا «ثُت » باشد، چه با جبت (قِبط) در قرآن مجید آمده است . اختلافی هم که در معنی آن شده است، دلیل اجنبی بودن و قدمت ورود آن بزبان و کمی استعمال آن است . رجوع به کلمه ٔ طغیان و توران و ترک و هون شود. <BR><font color=\"Blue\">◄</font> از حد درگذشتن . (تاج المصادر بیهقی ) (دهار) <span class=\"hlight\">:</span> <br />نه چون چیپال هند از جور تختی کرده طاغوتش <br />نه چون خاقان چین از ظلم ناجی داده طغیانش .<br /> <font color=\"Red\">خاقانی .</font><br />آن فرشته ٔ عقل چون هاروت شد<br />سحرآموزدو صد طاغوت شد.<br /> <font color=\"Red\">مولوی .</font><br />تن چو شد بیمار دارو جوت کرد<br />زر قوی شد مر ترا طاغوت کرد.<br /> <font color=\"Red\">مولوی .</font><br />از خدایت چاره هست از قوت نی <br />چاره هست از دین از طاغوت نی .<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> (اِخ ) کعب بن اشرف یهودی . (منتهی الارب ). معنی اخیر در حدیث و در آراء مفسران آمده است <span class=\"hlight\">:</span> زعامت آن ملاعین، با طاغوتی که به چرا معروف بود موکول بود. (ترجمه ٔ تاریخ یمینی ).<br /></font></div>'),
(175074, 'طاغک', '<span class=\"hlight\">طاغک .</span> <font color=\"DarkGreen\"><b>[ غ َ ]</font></b> (اِ) زنزلخت . رجوع به زنزلخت شود.<br /></font></div>'),
(175075, 'طاغی', '<span class=\"hlight\">طاغی .</span> (ع ص ) از حد درگذرنده . (منتهی الارب ). کسی که از حد طاعت و ادب درگذشته باشد. (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> نافرمان . (منتهی الارب ). ج، طغات . (مهذب الاسماء). غیرمنقاد. عاصی . سرکش . مرید. متجاوز از حد و قدر. غالی در کفر. زیاده رو. <BR><font color=\"Blue\">◄</font> ستمکار. (منتهی الارب ) <span class=\"hlight\">:</span> <br />زمین تو گوئی مر خصم ملک را بگرفت <br />بدان زمان که برآمد ز طاغیان فریاد.<br /> <font color=\"Red\">مسعودسعد.</font><br />چو روز رزم تو بر طاغیان خزان باشد<br />ز خون چگونه کند ذوالفقار تو گلشن .<br /> <font color=\"Red\">مسعودسعد.</font><br />تیغ او اندر زمانه حشمتی منکر نهاد<br />تا ازو طاغی و یاغی عبرتی منکر گرفت .<br /> <font color=\"Red\">مسعودسعد.</font><br />ندانستند که تأیید دین محمدی، رایت هر طاغی نگونسار کند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٩٢</span>).<br />زانکه انسان در غنا طاغی شود<br />همچو پیل خواب بین یاغی شود.<br /> <font color=\"Red\">مولوی .</font><br />هارون الرشید را چون ملک و دیار مصر مسلم شد، گفتا بخلاف آن طاغی که بغرور ملک مصر دعوی خدائی کرد، نبخشم این مملکت را الا به خسیس ترین بندگان . (گلستان ). و در فارسی کلمه ٔ طاغی با فعل «شدن » ترکیب میشود و به معنی نافرمانی کردن بصورت فعل لازم به کار میرود.<br /></font></div>'),
(175076, 'طاغیة', '<span class=\"hlight\">طاغیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) تأنیث طاغی . <BR><font color=\"Blue\">◄</font> سخت ستمکار. (منتهی الارب ). و بدین معنی تاء آخر کلمه را برای مبالغه بکلمه می افزایند. بیدادگر. (مهذب الاسماء). جبار عنید. (دهار). سخت ظالم . متمرد. خودکامه . <BR><font color=\"Blue\">◄</font> احمق متکبر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِمص ) بیدادی . (مهذب الاسماء) (زمخشری ). <BR><font color=\"Blue\">◄</font> (اِ) صاعقه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بُت . ج، طواغی . (منتهی الارب ). و منه الحدیث : لاتحلفوا بآبائکم و لا بالطواغی . و رُوی و لا بالطواغیت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آواز سخت در عذاب . و منه قول اﷲ تعالی <span class=\"hlight\">:</span> فاما ثمود فاهلکوا بالطاغیة، (قرآن <span class=\"hlight\" dir=\"rtl\">٥/٦٩</span>)؛ ای الصیحة المفرطة فی العذاب، قاله قتادة. و قال مجاهد بالذنوب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) از حد درگذشته . و آیه ٔ مزبوره را نیز شاهد آورده است . (دهار). <BR><font color=\"Blue\">◄</font> ملک طاغی . (منتهی الارب ). دُش خدای . <BR><font color=\"Blue\">◄</font> لقب ملوک روم . (مفاتیح خوارزمی ). اهل لغت از عرب گویند: لکثرة طغیانه وفساده، قیصر را طاغیةالروم، عظیم الروم، کلب الروم، امبرور خوانند. (بیان الادیان ). و لما قصد قازان طاغیة التتر مدینة حلب، حاصر هذه القلعة ایاماً. (ابن بطوطة ص <span class=\"hlight\" dir=\"rtl\">٤٠</span>). فقالت ام عبداﷲامراءة حبیب لیلئذ له : این موعدک ؟ قال سرادق الطاغیة اوالجنة. (فتوح البلدان ). در اینجا مراد از طاغیة پادشاه ارمنستان است، چنانکه ذیونوسیوس را طاغیه ٔ سوراقوسیا (سرقسطه ) نامند. و در عیون الانباء او را به متمرد سوراقوسیا نام برده است . و کان ذلک (ورود بمدینة سبتة) اثر موت طاغیة الروم الفونس . (ابن بطوطة).<br /></font></div>'),
(175077, 'طاف', '<span class=\"hlight\">طاف .</span> (ع ص ) رجل طاف ؛ مرد بسیارطواف . (منتهی الارب ). بسیار طواف کننده .<br /></font></div>'),
(175078, 'طاف', '<span class=\"hlight\">طاف .</span> (اِخ ) نام رودی به دهستان علیاء نهاوند.<br /></font></div>'),
(175079, 'طافة', '<span class=\"hlight\">طافة.</span> <font color=\"DarkGreen\"><b>[ طاف ْ ف َ ]</font></b> (ع اِ) مابین کوه و دشت . <BR><font color=\"Blue\">◄</font> طافة البستان ؛ نواحی و گرداگرد بوستان . (منتهی الارب ).<br /></font></div>'),
(175080, 'طافح', '<span class=\"hlight\">طافح .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (ع ص ) مست پر از شراب که از خود خبر ندارد. (منتهی الارب ). بدمست که پر شده باشد از شراب . (غیاث اللغات ). مست طافح که بیش نتواند آشامید. پر از شراب . (مهذب الاسماء). سیاه مست . مست ِ مست . مستی مست . لول . مست ِ خراب <span class=\"hlight\">:</span> <br />هر که از خُم ِّ می مدح تو جامی نوش کرد<br />تا نگردد مست طافح کی نهد از دست جام .<br /> <font color=\"Red\">سوزنی .</font><br /><BR><font color=\"Blue\">◄</font> لبالب . سرشار. فایض . پُرِ پُر.<br /></font></div>'),
(175081, 'طافحة', '<span class=\"hlight\">طافحة.</span> <font color=\"DarkGreen\"><b>[ ف ِ ح َ ]</font></b> (ع ص ) تأنیث طافح . خشک هرچه باشد: و منه رکبة طافحة؛ للتی لایقدر ان یقبضها. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زانوی خشک که تا نشود.<br /></font></div>'),
(175082, 'طافی', '<span class=\"hlight\">طافی .</span> (اِخ ) نام اسبی است . (منتهی الارب ).<br /></font></div>'),
(175083, 'طافی', '<span class=\"hlight\">طافی .</span> (ع ص ) بر آب برآینده . (منتهی الارب ). آنچه بر سر آب از سبکی و لطافت بالا برآید. ضد راسب . (غیاث اللغات ). آنچه بر روی آب ایستد. بر سر آب آمده مانند ماهی مرده ٔ در آب . رجوع به ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span> دُکری شود. <BR><font color=\"Blue\">◄</font> (اِ) پرده ای است بر شکم زیر پوست و بر زبر باریطون . یجب ان تعلم ان علی البطن بعد الجلد غشائین احدهما یسمی الطافی ... و الثانی یسمی باریطارون و یسمی المدور. (کتاب ثالث قانون ابوعلی ص <span class=\"hlight\" dir=\"rtl\">٣١١</span>). <BR><font color=\"Blue\">◄</font> کف که بر بالای قاروره و تفسره ٔ بیمار ایستد.<br /></font></div>'),
(175084, 'طافی', '<span class=\"hlight\">طافی .</span> (اِخ ) ناحیتی است به هندوستان با شهرهای آبادان، و نعمت فراخ، و مردمانش اسمرند و سپید. (حدود العالم ).<br /></font></div>'),
(175085, 'طاق', '<span class=\"hlight\">طاق .</span> (اِخ ) نام یکی از ده دروازه ٔ تبریز. حمداﷲ مستوفی گوید: تبریز ده دروازه دارد. و طاق یکی از آنهاست . (نزهةالقلوب چ لیدن مقاله ٔ ثالثه ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>).<br /></font></div>'),
(175086, 'طاق', '<span class=\"hlight\">طاق .</span> (اِ) سقف محدب . آسمانه . درونسو یا جانب انسی سقف . سقفی چون خرپشته کرده . عقد (طاق بنا). (منتهی الارب ) <span class=\"hlight\">:</span> <br />به یک دست ایوان یکی طاق دید<br />ز دیده بلندی او ناپدید.<br /> <font color=\"Red\">فردوسی .</font><br />همه خانه سرگین بد از گوسفند<br />یکی طاق بر پای و جای بلند.<br /> <font color=\"Red\">فردوسی .</font><br />به بوزرجمهر آنگه آواز کرد<br />ز طاق شکسته پس آغاز کرد.<br /> <font color=\"Red\">فردوسی .</font><br />فراوان ازو طاقها کرده بود<br />همانجای قیصر برآورده بود.<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود خسرو بدانجایگاه <br />یکی گنبدی تا به ابر سیاه <br />درازا و پهنای آن ده کمند<br />به گرداندرش طاق های بلند.<br /> <font color=\"Red\">فردوسی .</font><br />شما می گسارید خرم سه روز<br />چهارم چو خورشید گیتی فروز<br />برآید یکی کلبه سازم فراخ <br />سر طاق برتر ز دیوار طاق .<br /> <font color=\"Red\">فردوسی .</font><br />همان تخت پرویز ده لخت بود<br />جهان روشن از فرِّ آن تخت بود<br />همه طاقها بسته بودی ازار<br />ز خزّ و سمور ازدر شهریار.<br /> <font color=\"Red\">فردوسی .</font><br />گور عراقی را دیدم در مسجد، آنجا که مشهد است در طاقی به پنج گز از زمین تا طاق . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٥٤٩</span>). ستودان، گورستان گبران بود؛ همچون طاقی برآرند. (فرهنگ اسدی نخجوانی ).<br />طاق ایوان جهان گیر و وثاق پیرزن <br />از نکونامی طراز فرش ایوان دیده اند.<br /> <font color=\"Red\">خاقانی .</font><br />ور صدائی آید از طاق فلک <br />هم فلک کیوان ستان میخواندش .<br /> <font color=\"Red\">خاقانی .</font><br />بگذار زهد بی نمک، هل تا فرود آید فلک <br />هر رخنه کآید یک به یک، بر طاق ویران آمده .<br /> <font color=\"Red\">خاقانی .</font><br />مرکب همت بتاز یکره و بیرون خرام <br />از سر طاق فلک تا بحد استوا.<br /> <font color=\"Red\">خاقانی .</font><br />گردون چو طاقی از برش، بسته نطاقی بر درش <br />در هر رواقی آزرش، برهان نو پرداخته .<br /> <font color=\"Red\">خاقانی .</font><br />طاقها بمد بصر برکشیدند. (ترجمه ٔ تاریخ یمینی ).<br /> <BR><font color=\"Blue\">◄</font> گنبد طارم و مجازاً به معنی آسمان <span class=\"hlight\">:</span> <br />ورنه قدرش داشتی طاق فلک <br />کرسی خاک از میان برداشتی .<br /> <font color=\"Red\">خاقانی .</font><br />بنا نو کنی این کهن طاق را<br />ز غفلت فروشویی آفاق را.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> ایوان . (لغت فرس اسدی ) <span class=\"hlight\">:</span> <br />نهاده به طاق اندرون تخت زر<br />نشانده به هر پایه ای در گهر.<br /> <font color=\"Red\">فردوسی .</font><br />در طاق صفه ٔ تو چو بستم نطاق خدمت <br />جز در رواق هفت فلک منظری ندارم .<br /> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٢٨٢</span>).</font><br />طاق و رواق ساز بدروازه ٔ عدم <br />باج و دواج نه بسراپرده ٔ امان .<br /> <font color=\"Red\">خاقانی .</font><br />جهان از درگهش طاقی کمینه است <br />بر این طاق آسمان جام آبگینه است .<br /> <font color=\"Red\">نظامی .</font><br />پسر صبحدم سوی بستان شتافت <br />جز آن مرغ بر طاق ایوان نیافت .<br /> <font color=\"Red\">سعدی .</font><br />نگهداشت بر طاق بستانسرای <br />یکی نامور بلبل خوش سرای .<br /> <font color=\"Red\">سعدی .</font><br />بدبخت اگر مسجد آدینه بسازد<br />یا طاق فرود آید یا قبله کج آید.<br /> <font color=\"Red\">سعدی .</font><br />خبر یافت گردنکشی در عراق <br />که میگفت مسکینی از زیر طاق ...<br />حضورش پریشان شد و کار زشت <br />سفر کرد و بر طاق مسجد نوشت .<br /> <font color=\"Red\">سعدی .</font><br />تیرهمام گفت که ما اژدها سریم <br />تا طاق گنج نامه ٔ نصرت کمان ماست .<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> آنچه خمیده باشد از بناها. معرب تاک . (منتهی الارب ) (غیاث ). خمیدگی در نقش و نگار زیورهای عمارات و مجازاً بر خمیدگی ابرو و محراب و کمان اطلاق شود. طاق ابرو. خم ابرو. کمان ابرو. قوس حاجب <span class=\"hlight\">:</span> <br />هزاران بدش اندرون طاق وخم <br />به بجکم درش نقش باغ ارم .<br /> <font color=\"Red\">عنصری .</font><br />هزاران بدو اندرون طاق و خم <br />هزاران نگار اندرو بیش وکم .<br /> <font color=\"Red\">عنصری .</font><br />چون ابروی معشوقان باطاق و رواق است <br />چون روی پریرویان با رنگ و نگار است .<br /> <font color=\"Red\">منوچهری .</font><br />از نیزه طاق ابروی گردون گشادنش <br />وز حمله کرسی سر کیوان شکستنش .<br /> <font color=\"Red\">خاقانی .</font><br />صف صف از مرغان نشاندن جفت جفت <br />همبر طاق ابروان بدرود باد.<br /> <font color=\"Red\">خاقانی .</font><br />به طاق آن دو ابروی خمیده <br />مثالی ز آن دو طغرا برکشیده .<br /> <font color=\"Red\">نظامی .</font><br />بر آن شد سرانجام کار اتفاق <br />که سازند طاقی چوابروی طاق <br />میان دو ابروی طاق بلند<br />حجابی فرود آوردنقشبند.<br /> <font color=\"Red\">نظامی .</font><br />بهمه کس بنمودم خم ابرو که تو داری <br />ماه نو هر که ببیند بهمه کس بنماید.<br /> <font color=\"Red\">سعدی .</font><br />هر دم بخون دیده چه حاجت وضو چو نیست <br />بی طاق ابروی تو نماز مرا جواز.<br /> <font color=\"Red\">حافظ.</font><br />طربسرای محبت کنون شود معمور<br />که طاق ابروی یار منش مهندس شد.<br /> <font color=\"Red\">حافظ.</font><br />طاق ابروی ترا تا بست معمار قضا<br />روی من از قبله ٔ اسلام برگردیده است .<br /> <font color=\"Red\">صائب .</font><br /> <BR><font color=\"Blue\">◄</font> نوعی از جامه . (منتهی الارب ). نوعی از جامه ٔ پوشیدنی، و آن فرجی و جبه ٔ پنبه دار باشد. (برهان ). و طیلسان و ردا را نیز گفته اند و بدین معنی عربی است . (برهان ). قسمی از جامه که بر سرجامه ها پوشند. جامه، یعنی پارچه ای است که آن را یکتا گویند. <BR><font color=\"Blue\">◄</font> چادر. چادر سر. (منتهی الارب ) <span class=\"hlight\">:</span> امیر خلف فرود آمد بر طاق و طیلسان به رسم علما و زهاد، بر خری مصری نشسته، و شمعها افروخته اندر پیش . (تاریخ سیستان ). امیر خلف جامه ٔ لشکری بر طاق نهاد، و سلب علما و فقها پوشید و طاق و طیلسان . (تاریخ سیستان ). دراعه ٔ سپیدی پوشیدی با بسیار طاقهای ملحم . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>).<br />تو که پوشیده همی بینی از دور مرا<br />حال بیرون و برونم نه همانا دانی <br />طاق بوطالب نغمه ای است که دارم ز برون <br />وز درون پیرهن بوالحسن عمرانی .<br /> <font color=\"Red\">انوری .</font><br /> <BR><font color=\"Blue\">◄</font> دست . طاقه . تا. رجوع به طاقه شود <span class=\"hlight\">:</span> چون دوری چند شراب بگشت، چند طاق جامه ٔ مرتفع قیمتی پیش من بنهادند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٥١٧</span>). اسبی قیمتی و بیست طاق جامه و بیست هزار درم بخشید. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٧٩</span>). چون دوری چند شراب بگشت، خزانه دارش <font color=\"DarkGreen\"><b>[ طاهر دبیر ]</font></b> بیامد، و پنج طاق جامه ٔ مرتفع قیمتی پیش من نهاد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٤٢</span>). و هر سال دویست هزار دینار هریوه، و ده هزار طاق جامه از مستعملات آن نواحی بدهد، بیرون هدیه ٔ نوروز و مهرگان . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٦</span>).<br />یکی را ز مردان روشن ضمیر<br />امیر ختن داد طاقی حریر.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> تیزی ایوان و عمارت و پل و رودخانه . (برهان ) <span class=\"hlight\">:</span> طاقهای پل را بگرفت چنانچه آب را گذر نبود. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٦٢</span>). عیوبه ٔ بازرگان، آن مرد پارسای با خیر رحمة اﷲ علیه، چنین پلی برآورد، یک طاق بدین نیکوئی و زیبایی . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٦١</span>).<br />از عدل دید خواهی هم راستی و هم خم <br />در ساق عرش ایزد در طاق پول محشر.<br /> <font color=\"Red\">خاقانی .</font><br />گر به زمین افتدی هندسه ٔ رای تو<br />قوس قزح سازدی طاق پل رود زم .<br /> <font color=\"Red\">خاقانی .</font><br />آبی است بدگوار ز یخ بسته طاق پل <br />سقفی است زرنگار وز مهتاب نردبان .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> رف . (مهذب الاسماء). طاقچه . کوة. رف مانندی که در آن چیزها گذارند. سهوة <span class=\"hlight\">:</span> <br />ای بچه ٔ حمدونه غلیواژ غلیواژ<br />ترسم بربایدت بطاق اندر جه .<br /> <font color=\"Red\">لبیبی .</font><br />کند مشحون همه طاق و رف آن <br />بتفسیر و به اخبار و به اشعار.<br /> <font color=\"Red\">مسعود سعد.</font><br />دیدم از باده ٔ پرندوشین <br />شیشه ای نیم بر کناره ٔ طاق .<br /> <font color=\"Red\">انوری .</font><br />دیده ٔ تو راست نیست لاف یکی زن مزن <br />صورت تو خوب نیست آینه بر طاق نه .<br /> <font color=\"Red\">خاقانی .</font><br />از آن یکی صادق بود، در پیش او نشسته بود، گفت بایزید آن کتاب از طاق فروگیر، بایزید گفت : کدام طاق ؟ گفت : آخر مدتی است که اینجا می آئی و طاق ندیده ای . (تذکرةالاولیاء).<br />در شب قدر ار صبوحی کرده ام عیبم مکن <br />سر خوش آمد یار و جامی بر کنار طاق بود.<br /> <font color=\"Red\">حافظ.</font><br />بر دیوار آن حجره طاقی بود، و در آنجا چند کتابی . (انیس الطالبین نسخه ٔ خطی کتابخانه ٔ مؤلف ص <span class=\"hlight\" dir=\"rtl\">٧٧</span>).<br /> <BR><font color=\"Blue\">◄</font> مقابل جفت . معرب است از تا و تای و بعقیده ٔ صاحب غیاث قاف در آخر آن افزوده اند یا صورت و تعریبی از تک است و در این معنی طاق نعل، لنگه کفش معنی دهد؛ ویقال طاق نعل . (منتهی الارب ). یکتا. (مهذب الاسماء). فرد، طاقی بود. (التفهیم ). توّ. ته . لنگه . بی جفت . بی مانند. مقابل زوج . یگانه . تنها. اوحد. وِتر. وَتر. (منتهی الارب ). بی نظیر. فرید. وحید <span class=\"hlight\">:</span> <br />طاق با جفت هردوان جفتند<br />ز آنکه توحید نیست زیر بیان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />جفتهارا بطاق نشناسی <br />بغلط نوفتی در این و در آن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تو طاق نه ای با تو همان خواهد کرد<br />ایام که کرد و میکند با دگران .<br /> <font color=\"Red\">انوری .</font><br />طاق ابروان رامش گزین در حسن طاق و جفت کین <br />بر زخمه ٔ سحرآفرین شکر ز آوا ریخته .<br /> <font color=\"Red\">خاقانی .</font><br />بحسب طاقت خود طوقدار مدح توام <br />چرا ز طایفه ٔ خاصگان بماندم طاق .<br /> <font color=\"Red\">خاقانی .</font><br />طاق پذیر است عشق جفت نخواهد حریف <br />بر نمط عشق اگر پای نهی طاق نه .<br /> <font color=\"Red\">خاقانی .</font><br />جفت و طاق سپهر درشکند<br />جفته ای کان تکاور اندازد.<br /> <font color=\"Red\">خاقانی .</font><br />سکندر که خورشید آفاق بود<br />به روشندلی در جهان طاق بود.<br /> <font color=\"Red\">نظامی .</font><br />جوابش داد کای از مهتران طاق <br />ندیدم مثل تو مهمان در آفاق .<br /> <font color=\"Red\">نظامی .</font><br />سر و سرخیل شاهان شاه آفاق <br />چو ابرو با سری هم جفت و هم طاق .<br /> <font color=\"Red\">نظامی .</font><br />ابروی بطاق او بهم جفت <br />جفت آمده و بطاق میگفت .<br /> <font color=\"Red\">نظامی .</font><br />گفت شهری ز شهرهای عراق <br />داشت شاهی ز شهریاران طاق .<br /> <font color=\"Red\">نظامی .</font><br />کان در نسفته را در آن سفت <br />با گوهر طاق خود کند جفت .<br /> <font color=\"Red\">نظامی .</font><br />صاحب هنری بمردمی طاق <br />شایسته ترین جمله آفاق .<br /> <font color=\"Red\">نظامی .</font><br />ز تو با آنکه استحقاق دارم <br />سراز طوق نوازش طاق دارم .<br /> <font color=\"Red\">نظامی .</font><br />ز مثل خود جهان را طاق بیند<br />جهان خود را به استحقاق بیند.<br /> <font color=\"Red\">نظامی .</font><br />گفت هر رازی نشاید بازگفت <br />جفت طاق آید گهی گه طاق جفت .<br /> <font color=\"Red\">نظامی .</font><br />گاو ریشی بود او برزیگری <br />داشت جفت گاوی و طاق خری .<br /> <font color=\"Red\">عطار.</font><br />طاقم ز قرار و صبر و آرام <br />زآن روز که با غم تو جفتم .<br /> <font color=\"Red\">سعدی .</font><br />کز فراقت بکشد جان بوصال تو دهم <br />تو گرو بردی اگر جفت اگر طاق آید.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاق ماندن </span> ؛ جدا و تنها و منفرد ماندن . دور افتادن <span class=\"hlight\">:</span> <br />به حسب طاقت خود طوقدار مدح توام <br />چرا ز طایفه ٔ خاجگان بماندم طاق .<br /> <font color=\"Red\">خاقانی (دیوان چ عبدالرسولی ص <span class=\"hlight\" dir=\"rtl\">٢٤١</span>).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاق و جفت باختن </span> ؛ در تداول عامه طاق یا طاق جفت بازی کردن : یقال ُ خَساً او زکاًیعنی طاق یا جفت . (منتهی الارب ).<BR>۩ بازیی است که از چیزی، یک یا چند عدد در دست دارند، و از حریف، جفت یا طاق بودن آن پرسند، جواب حریف اگر مطابق واقع افتد بُرده، وگرنه باخته باشد، بازی معروف قمار و با لفظ باختن و زدن مستعمل است <span class=\"hlight\">:</span> <br />قمار عشق میبازی کنون آن سرگرانی کو<br />که طاق و جفت با ابروی خود بازی نمیکردی .<br /> <font color=\"Red\">سیدحسین خالص .</font><br />چو طاق و جفت زدن بر طریق لعب کنند<br />به نیزه تنها جفت و به تیغ سرها طاق .<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />طاق و جفتی باختم با ابرویش دلدار بُرد<br />طاق بود ابروی او من جفت گفتم یار بُرد.<br /> <font color=\"Red\">میرزاطاهر وحید(آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> سیم طاقا یا جفت ؛ در ماوراءالنهر عادت و رسم است که در مجالس پادشاه و دیگر مجلسها، سیم و زر در طبقها بنقل بنهند، و آن را سیم طاقا یا جفت خوانند؛ و در مجلس خضرخان بخش (را؟) چهار طبق زر سرخ بنهادندی، در هر یکی دویست و پنجاه دینار، و آن بمشت ببخشیدی، (چهارمقاله چ استاد براون ص <span class=\"hlight\" dir=\"rtl\">٤٧</span>). <BR><font color=\"Blue\">◄</font> شادروان . افریز. (آنندراج ). خیمه و در این معنی معرب تاژک است . <BR><font color=\"Blue\">◄</font> در قوسی ایوان خانه . (آنندراج ). <BR><font color=\"Blue\">◄</font> اَزَج . سَغ و آن نوعی ازعمارت طولانی و دراز است . <BR><font color=\"Blue\">◄</font> سنگ بزرگ بیرون آمده از کوه ؛ و کذلک فی البئر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نوعی از صدا و آواز را نیز گویند. (برهان ). <BR><font color=\"Blue\">◄</font> سقف بطن اوسط دماغ . <BR><font color=\"Blue\">◄</font> پرده ٔ تنکی که دماغ را بر دو جزء مقدم و مؤخرّ بخش کند، به معنی باز و گشوده نیز آمده است . (برهان ). <BR><font color=\"Blue\">◄</font> ما بین هر دو چوبی از کشتی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> هر بلندی که باشد. (اسدی ). بر بلندی . (حاشیه ٔ فرهنگ نخجوانی ) <span class=\"hlight\">:</span> <br />چو افتاد این سخن در گوش فرهاد<br />ز طاق کوه چون کوهی در افتاد.<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">از طاق دل افتادن </span> ؛ کنایه از خوار و بی اعتبار شدن <span class=\"hlight\">:</span> <br />فغان بی اثر از طاق دل اسیرترا<br />چو شاخ بی ثمر از چشم باغبان افتاد.<br /> <font color=\"Red\">محمدجان قدسی .</font><br />و سعدی از طاق دل فروریختن بسته و معهذا اطلاق فرو ریختن بر صنم نیز خالی از تازگی نیست <span class=\"hlight\">:</span> <br />نقاب زلف ز عارض اگر براندازی <br />صنم ز طاق دل برهمن فروریزد.<br /> <font color=\"Red\">سعدی (آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بر طاق نهادن، یا بطاق برنهادن، یا بر طاق نسیان و یا فراموشی نهادن </span> ؛ کنایه از فراموش کردن . بالتمام او را ترک گفتن . از یاد دادن . ترک کردن <span class=\"hlight\">:</span> <br />تا سفرهای تو دیدند و هنرهای تو خلق <br />برنهادند از تعجب قصه ٔ شاهان بطاق .<br /> <font color=\"Red\">منوچهری .</font><br />همه حدیث بزرگی اوست در افواه <br />از آن حکایت کسری نهاده شد بر طاق .<br /> <font color=\"Red\">رفیعالدین لنبانی .</font><br />ز پیش آنکه ترا برنهد بطاق جهان <br />تو برنه او را ای پور مردوار به تل .<br /> <font color=\"Red\">ناصرخسرو.</font><br />خط بر خط عالم کش و در خط مشو از کس <br />دل طاق کن از هستی وبر طاق نه اسباب .<br /> <font color=\"Red\">خاقانی .</font><br />طوق غم تو دارم بر طاق از آن نهم دل <br />کز طوق تو برون سر در چنبری ندارم .<br /> <font color=\"Red\">خاقانی .</font><br />کسی که جفت نداند ز خسروان خود را<br />نهد به پیش تو دعوی خسروی بر طاق .<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />فکند قصه ٔ یوسف جمال او در چاه <br />نهاد نامه ٔ کسری زمان او در طاق .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />شد مقرر می پرستی گردش چشمی کجاست <br />تا نهد بر طاق نسیان شیشه وپیمانه را.<br /> <font color=\"Red\">صائب (آنندراج ).</font><br />و رجوع به طاق برنهادن شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بطن طاق </span> ؛ شکمی که در آن طعام نبود. (مهذب الاسماء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به طاق ابرو خم آوردن </span> ؛ به ابرو خم دادن . کنایه از اخم کردن و عبوس بودن <span class=\"hlight\">:</span> <br />بطاق دو ابرو برآورده خم <br />گره بسته بر خنده ٔ جام جم .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چارطاق </span> ؛ نوعی از خیمه ٔ چهارگوشه که آن را در عراق شروانی و در هند راوتی گویند. (برهان ).<BR>۩ خیمه ٔ مطبخ . (برهان ) <span class=\"hlight\">:</span> <br />فلک بر زمین چارطاق افکنش <br />زمین بر فلک پنج نوبت زنش .<br /> <font color=\"Red\">نظامی .</font><br />مزن پنج نوبت در این چارطاق .<br /> <font color=\"Red\">نظامی .</font><BR>۩ اطاقی که در بالای سرای ها بر چهار ستون بنا کنند. (حاشیه ٔ برهان ).<BR>۩ کنایه از عناصر اربعه . (برهان ). و رجوع به چارطاق شود.<BR>۩ و در تداول امروز، دو لنگه در تمامی باز. هر دو مصراع در تمام گشاده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چارطاق خوابیدن </span> ؛ در تداول عامه، طاق باز خوابیدن . رجوع به طاق باز و طاق واز شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چارطاقی </span> ؛ بنای مربعی میانه نه بزرگ نه کوچک که بر سر گورمردگان سازند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چشم بطاق افتادن </span> ؛ حالت خاص در چشم محتضران پیدا شدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سر کسی را بیخ طاق کوبیدن یا بطاق کوبیدن </span> ؛ او را به وعده ٔ دروغین مطلق برفتن داشتن . بفریب کسی را از خود راندن . کسی را فریفتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاق آرایش و آرایش طاق </span> ؛ خم و زیور سقف و ایوان در تداول معماران . و مجازا کنایه از ستارگان <span class=\"hlight\">:</span> <br />گرچه غمخانه ٔ ما را نه حجر ماند و نه بهو<br />هر چه آرایش طاق است ز بر بگشایید.<br /> <font color=\"Red\">خاقانی .</font><br />چرخ و اخترچیست طاق آرایشی و طارمیست <br />ما خراب دوستیم از طاق و طارم فارغیم .<br /> <font color=\"Red\">خاقانی .</font><br />دهر ویران را بجز آرایش طاقی نماند<br />خویشتن زین طاق ویران درکشم هر صبحدم .<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاق ابروگشادن </span> ؛ کنایه از خندیدن <span class=\"hlight\">:</span> <br />گشاده طاق ابرو تا بناگوش <br />کشیده طوق غبغب تا سر دوش .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاق ابرو ناگشادن </span> ؛ کنایه از اخم کردن و عبوس بودن <span class=\"hlight\">:</span> <br />بس است این طاق ابرو ناگشادن <br />بطاقی با نطاقی وانهادن .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاق افتادن </span> ؛ به نهایت بی طاقتی رسیدن <span class=\"hlight\">:</span> <br />نقش می بستم که گیرم گوشه ای زان چشم مست <br />طاقت و صبر از خم ابروش طاق افتاده بود.<br /> <font color=\"Red\">حافظ.</font><BR>۩ یکتا و بیمانند شدن <span class=\"hlight\">:</span> <br />ابروی او جز کمان چرخ نیست <br />زانکه همچون چرخ طاق افتاده است .<br /> <font color=\"Red\">عطار.</font><BR>۩ دور ماندن . تنها ماندن . جدا ماندن <span class=\"hlight\">:</span> <br />در سرای محملی من هم بیابانی شدم <br />چون کنم بیچاره مجنون سخت طاق افتاده بود.<br /> <font color=\"Red\">طالب آملی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">از طاق افتادن و افکندن </span> ؛ از جای بلند افتادن و افکندن <span class=\"hlight\">:</span> <br />جلوه ای کردی که افتاد آفتاب از طاق چرخ <br />دستی افشاندی که مهتاب از کنار بام ریخت .<br /> <font color=\"Red\">فطرت (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">نوطاق </span> ؛ موزاری که تازه کاشته باشند و این ترکیب در جنوب خراسان (گناباد) متداول است .<br /></font></div>'),
(175087, 'طاق', '<span class=\"hlight\">طاق .</span> (اِ) آزاددرخت . برگش پهنا ندارد. رجوع به «هَدَب » در قاموس و جز آن شود. طاق، شامل دو نوع است : یکی مخصوص بسوزانیدن هیمه، که آن را طاق نامند و یکی حب الزلم است از نخود بزرگتر و شبیه به عناب در رنگ و شیرینی و مغز دانه ٔ او بسیار لذیذ است و نیز گویند: طاق اسم درختی است که آن را به فارسی سایه خوش نامند و ثَمر آن بقدر کُنار کوچکی سبزرنگ است و آتش اخگر آن مدتی میماند و گفته اند آزاددرخت است و ثَمر آن را تاخک مینامند. درخت غضاة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ودر تداول جنوب خراسان (گناباد) طاق را هم بر درخت مو و تاک اطلاق کنند و هم آن را به معنی درختی صحرائی به کار برند که برای سوختن است . <BR><font color=\"Blue\">◄</font> درختانی که فروع و شاخ نداشته باشند. رجوع به طاقات شود.<br /></font></div>'),
(175088, 'طاق', '<span class=\"hlight\">طاق .</span> (اِخ ) قلعه ٔ طاق . حمداﷲ مستوفی در نزهة القلوب ذیل شرح بلاد قُهستان و نیمروز آورده که : قلعه ٔ طاق شهری کوچک است و در او انگور بسیار باشد و چند دیه توابع آن است . (نزهةالقلوب مقاله ٔ ثالثه چ لیدن ص <span class=\"hlight\" dir=\"rtl\">١٤٦</span>). شهری است در حدود سیستان در جهت خراسان رستاقی دارد که انگورفراوان دهد و مشتمل بر قری و مزارع و ابوعبداﷲ محمدبن فضل بن محمد طاقی از آنجاست . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٧</span>). شهرکی است از حدود خراسان با حصار محکم و مردم بسیار. (حدود العالم ص <span class=\"hlight\" dir=\"rtl\">٦٣</span>). یمین الدوله محمود بدین انتقام با او <font color=\"DarkGreen\"><b>[ خلف بن احمد ]</font></b> جنگ کرد او منهزم بقلعه ٔ طاق گریخت یمین الدوله قلعه را بعد از محاصره مسخر گردانید. (تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٣٩٦</span>). در سنه ٔ اثنی و تسعین و ثلثمائة <font color=\"DarkGreen\"><b>[ سلطان محمود ]</font></b> به سیستان و خلف بقلعه ٔ طاق که در متانت و مسافت (کذا؟) غیرت افزای طاق حصار فیروزه کار گردون بود متحصن شد. (حبیب السیر چ <span class=\"hlight\" dir=\"rtl\">١</span> طهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣١</span>). خلف از حصار ارک برخاست و بقلعه ٔ طاق رفت و ابوالحسن سیمجور و اولیاء دولت در اندرون حصار رفتند.(ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤١</span>) و رجوع به تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">١٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٨</span>، <span class=\"hlight\" dir=\"rtl\">١٣٧</span>، <span class=\"hlight\" dir=\"rtl\">١٩١</span>، <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>، <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>، <span class=\"hlight\" dir=\"rtl\">٣٤١</span>، <span class=\"hlight\" dir=\"rtl\">٣٤٧</span>، <span class=\"hlight\" dir=\"rtl\">٣٤٨</span>، <span class=\"hlight\" dir=\"rtl\">٣٤٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٥١</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٧١</span>، <span class=\"hlight\" dir=\"rtl\">٣٧٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٨٧</span>، <span class=\"hlight\" dir=\"rtl\">٣٩٠</span>، <span class=\"hlight\" dir=\"rtl\">٤٠٦</span> و <span class=\"hlight\" dir=\"rtl\">٤١١</span> شود.<br /></font></div>'),
(175089, 'طاق', '<span class=\"hlight\">طاق .</span> (اِخ ) محله ای است به بغداد و منسوب به آن محله است، محمدبن النعمان شیعی که بمؤمن الطاق معروف میباشد.<br /></font></div>'),
(175090, 'طاق', '<span class=\"hlight\">طاق .</span> (اِخ ) حصاری است در طبرستان . منصور خلیفه ٔ عباسی ابوالخصیب را والی قومس و جرجان و طبرستان کرد و فرمان داد که از راه جرجان بدانجا درآید و هم به ابن عون نوشت که به طبرستان رود بدان نهج که از قومس بگذرد، در آن هنگام اسپهبد، در شهر اسپهبدان اقامت داشت که تا دریا بیش از دو میل مسافت ندارد، چون از فرارسیدن لشکر آگاه شد، به کوهسار گریخت بموضعی که آن را طاق مینامیدند و از زمان باستان خزانه ٔ پادشاهان ایران بود. نخستین پادشاهی که آنجا را رسماً خزانه قرار داد منوچهر بود. محل خزانه در شکاف کوهی بودکه راهی سخت دشوار داشت و جز پیاده آنهم در نهایت صعوبت دیگر کس از آن نمیتوانست بگذرد. این شکاف به دری کوچک شبیه بود، چون آدمی بدرون آن میشد پس از آن که بقدر یک میل میرفت و تمامی راه را در تاریکی سخت می پیمود بجائی فراخ میرسید که بشهری شباهت داشت، بنحوی که از هر طرف کوههای صعب العبور گرد آن را فرا گرفته بود و اگر کسی هم برنج و مشقت بر فراز آن کوه میشدفرود آمدن از آن بسی دشوار بود و در آن فضای وسیع غارها و شکافهائی که کسی بپایان آنها راه نمیبرد، در وسط آن فضا چشمه ای بود که آبی بسیار از سنگی سخت و بزرگ بر می آمد، و بسنگی دیگر که با سنگ سخت ده گز فاصله داشت فرومیریخت و هیچ آفریننده ای نمیدانست که آخرین مصب آن آب کجاست . در روزگار پادشاهان ایران دوتن پیوسته نگاهبان آن شکاف بودند و همواره با آندو تن نردبانی تعبیه شده از ریسمان بود که بهنگام ضرورت با آن از کوه فرود می آمدند و نیازمندیهای چندین ساله ٔ نگهبانان در آن محل پیوسته فراهم بود، حال خزانه در تمامی مدت سلطنت پادشاهان ایران بدین منوال بود تا دوره ٔ استیلا و پادشاهی تازیان رسید، خواستند از آن کوه بالا روند نتوانستند چون مازیار والی طبرستان شد و آهنگ آن خزانه کرد و روزگاری دراز بدانجا اقامت گزید تا سرانجام آرزوی وی برآمد، یکی از یاران او بر فرازآن کوه شد و با ریسمان مازیار و گروهی از همراهان او را بالا برد، مازیار در آنجا بر آنچه در غارها و شکافها از اموال و اسلحه و گنجینه بود دست یافت و جمعی از خاصان خویش را بر آن ذخائر بگماشت و خود بازگشت و حال بدینگونه بود تا وی اسیر شد و پس ازو گماشتگانش از آنجا فرود آمدند، یا در همانجا بمردند و تا این زمان (عصر یاقوت حموی مؤلف معجم البلدان ) راه آنجامسدود است . ابن الفقیه از سلیمان بن عبداﷲ نقل کند که در جانبی از طاق مزبور جائی است مصطبة (سکو) مانندکه اگر کسی آنجا را بکثافات و پلیدیها آلوده کند درحال ابری عظیم برخیزد و چندان بدان محل ببارد تا آن را از پلیدیها پاکیزه سازد و آثار پلیدی از آنجا محو کند و این گفتار چندان در طبرستان مشهور و معروف است که هیچکس را بر صحت آن شک نباشد از این رو در زمستان و تابستان محل مزبور از هر نوع از پلیدیها پاک است . چون اسپهبد بطاق رفت ابوالخصیب از پی وی سر کردگان و لشکریان را روانه داشت و همین که اسپهبد از آمدن لشکریان آگاه گردید بجانب دیلم گریخت و پس از یکسال بمرد و ابوالخصیب بالاستقلال در شهر اقامت کرد و بر اهالی خراج و گزیت نهاد، و اقامتگاه خود را ساریة (ساری ) قرار داد و در آن شهر مسجد و منبری بساخت همچنین در آمل آثاری از خود باقی گذاشت . مدت فرمانروائی وی در آن حدود دو سال و ششماه بود. (معجم البلدان ).<br /></font></div>'),
(175091, 'طاق', '<span class=\"hlight\">طاق .</span> (اِخ ) مؤمن الطاق ِ یا شیطان الطاق . نجاشی (متوفی <span class=\"hlight\" dir=\"rtl\">٤٥٠</span>) گوید: محمدبن علی بن نعمان بن ابی طریفة بجلی (مولای أحول ) ابوجعفرکوفی صیرفی ملقب به مؤمن الطاق و صاحب الطاق است . (طاق محله ای است به بغداد و وی بدان محله منسوب است ). و مخالفان وی راشیطان الطاق نام دادند. عم پدر او منذربن ابی طریفة از علی بن الحسین و ابوجعفر و ابی عبداﷲ روایت دارد و پسر عم او حسین بن منذربن ابی طریفة نیز از ایشان روایت کند. دکانی در طاق المحال کوفه داشت . چیزهائی به وی نسبت کنند که ثابت نباشد. او راست : کتاب افعل و لاتفعل، آن را نزد احمدبن حسین بن ابی عبیداﷲ (ره ) دیدم و کتاب نیکو و بزرگ بود و بعض متأخران در آن دست برده و احادیثی دال بر تناقض اقوال صحابه و فساد آنها در آن افزوده . و نیز او راست : کتاب الاحتجاج در امامت علی (ع ) و کتاب رد بر خوارج و کتاب مجالس او با ابی حنیفه و مرجئه . از حکایات وی با ابی حنیفه آن است که بدوگفت : ای ابوجفعر برجعت قائلی ؟ طاق جواب داد آری . بوحنیفه گفت : پانصد درم بمن قرض ده و در رجعت بستان . وی گفت : یک ضامن بیاور که در آن دوره بصورت انسان باشی چه اگر بصورت میمون آئی من وجه خود باز ستدن نتوانم . هشام بن حکم که از رجال شیعه است کتابی بنام الرد علی شیطان الطاق نگاشته است . (الذریعه ج <span class=\"hlight\" dir=\"rtl\">١</span>) (رجال نجاشی چ بمبئی <span class=\"hlight\" dir=\"rtl\">١٣١٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٨</span>) و رجوع به مؤمن طاق شود.<br /></font></div>'),
(175092, 'طاق', '<span class=\"hlight\">طاق .</span> (اِخ ) رجوع به ابوالحسن طاق شود.<br /></font></div>'),
(175093, 'طاق آبفام', '<span class=\"hlight\">طاق آبفام .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از آسمان است <span class=\"hlight\">:</span> <br />آب محیطروز کرامات کرده پل <br />بگذشته ز آتشین پل این طاق آبفام .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(175094, 'طاق ابرو نمودن', '<span class=\"hlight\">طاق ابرو نمودن .</span> <font color=\"DarkGreen\"><b>[ ق ِ اَ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) ناز و کرشمه . ابرو نازک کردن . رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span> شود.<br /></font></div>'),
(175095, 'طاق ازرق', '<span class=\"hlight\">طاق ازرق .</span> <font color=\"DarkGreen\"><b>[ ق ِ اَ رَ ]</font></b>(ترکیب وصفی، اِ مرکب ) کنایه از فلک است که آسمان باشد. (برهان ). کنایه از فلک و آسمان . (انجمن آرا).<br /></font></div>'),
(175096, 'طاق البصل', '<span class=\"hlight\">طاق البصل .</span> <font color=\"DarkGreen\"><b>[ قُل ْ ب َ ص َ ]</font></b> (اِخ ) ابن عبدربه صاحب این لقب را در ردیف مجانین و دیوانگان شمرده و گوید با دریافت قیراطی آواز میخواند و با اخذ دانگی خاموش میشد. (عقدالفرید چ محمد سعید العریان ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٢</span>).<br /></font></div>'),
(175097, 'طاق التکک', '<span class=\"hlight\">طاق التکک .</span> <font color=\"DarkGreen\"><b>[ ق ُ ؟ ]</font></b> (اِخ ) نام محلی است در کرخ : و در این ماه (ذی القعده ٔ سال <span class=\"hlight\" dir=\"rtl\">٣٣٢</span>) در کرخ حریقی عظیم روی داد که از حد طاق التکک تا سماکین را فرا گرفت . (از اخبارالراضی باللّه ص <span class=\"hlight\" dir=\"rtl\">٢٦١</span>).<br /></font></div>'),
(175098, 'طاق الحجام', '<span class=\"hlight\">طاق الحجام .</span> <font color=\"DarkGreen\"><b>[ قُل ْ ح َج ْ جا ]</font></b> (اِخ ) جایگاهی است نزدیک حلوان عراق این طاق از سنگ بنا شده و بر جاده ٔ عمومی راه خراسان واقع است در تنگنای بین دو کوه، بنای این طاق شگفت آور و دارای سقفی بلند است . (معجم البلدان ). رجوع به طاق گرّا شود.<br /></font></div>'),
(175099, 'طاق الحرانی', '<span class=\"hlight\">طاق الحرانی .</span> <font color=\"DarkGreen\"><b>[ قُل ْ ح َرْ را ]</font></b> (اِخ ) محله ای است در جانب غربی بغداد، گویند از حد پل جدید و شارع طاق حرانی تا شارع باب الکرخ منسوب است بقریه ای که ورثال نام دارد و مراد از حرّانی ابراهیم بن ذکوان بن الفضل الحرانی است که از غلامان منصور بوده و بعداً به مقام وزارت هادی رسید. (معجم البلدان ).<br /></font></div>'),
(175100, 'طاق ایوان', '<span class=\"hlight\">طاق ایوان .</span> <font color=\"DarkGreen\"><b>[ ق ِ اَ <span class=\"hlight\" dir=\"rtl\">/</span> اِ ]</font></b> (ترکیب اضافی، اِ مرکب ) تیزی پیش ایوان <span class=\"hlight\">:</span> این لطیفه بر طاق ایوان فریدون نوشته بود. (گلستان سعدی ).<br />شهی که بانی کیوان ز طاق ایوانش <br />فراز بارگه خویش طاق دیگر زد.<br /><font color=\"Red\">سلمان .</font><br /></font></div>'),
(175101, 'طاق بازیچه رنگ', '<span class=\"hlight\">طاق بازیچه رنگ .</span> <font color=\"DarkGreen\"><b>[ ق ِ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ رَ ]</font></b> (ترکیب وصفی، اِ مرکب ) به معنی طاق ازرق است که آسمان باشد. (برهان ). کنایه از فلک و آسمان . (انجمن آرا) <span class=\"hlight\">:</span> <br />سوم روز کاین طاق بازیچه رنگ <br />برآورد بازیچه ٔ روم و زنگ .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175102, 'طاق برنهادن', '<span class=\"hlight\">طاق برنهادن .</span> <font color=\"DarkGreen\"><b>[ ب َ ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) یا بر طاق نهادن . کنایه از فراموش کردن . (برهان ) (انجمن آرا). <BR><font color=\"Blue\">◄</font> ترک دادن چیزی . (برهان ) (انجمن آرا). و رجوع به بر طاق نهادن شود <span class=\"hlight\">:</span> <br />مرد از دورنگی طاق به، این رنگها بر طاق نه <br />هم دور خور هم دور ده، وانصاف بستان صبح را.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175103, 'طاق بستان', '<span class=\"hlight\">طاق بستان .</span> <font color=\"DarkGreen\"><b>[ ق ِ ب ُ ]</font></b> (اِخ ) نام محلی کنار راه سنندج و کرمانشاهان بین گاوبنده و کرمانشاهان، در <span class=\"hlight\" dir=\"rtl\">١٤٣٠٠٠</span> گزی سنندج و <span class=\"hlight\" dir=\"rtl\">٧٥٠٠</span> گزی کرمانشاهان . در این محل قریب به سی چهل خانوار سکونت دارند، طاقها و حجاریهای زمان ساسانیان در کنار آبادی سر راه کردستان واقع است، چشمه ای نیز در این محل هست که آب بسیاری از آن جاری میشود، دو طاق در آنجاست که ارتفاع یکی با دیگری متفاوت است، طاق بزرگتر از طاق کوچکتر آرایش بیشتر دارد، نقوش آن بسیار ظریف و در نهایت مهارت ساخته شده، در طاق کوچکتر دو نقش میباشد که دارای کتیبه ای بخط پهلوی است . در مشرق این دو طاق کتیبه ٔ برجسته ای دیده میشود که از روزگار ساسانیان باقی مانده است، در خارج طاق تزییناتی به کار برده اند، روی سنگ بالای قوس طاق صورت دو فرشته حجاری شده که تاجی را با دستهای خود از دو طرف گرفته اند، دیواره ٔ عقب دو طبقه دارد. در قسمت تحتانی صورت سواری است که نیزه ای در دست دارد، زره پوشیده، و حجاری آن بسیار ظریف است . در طبقه ٔ فوقانی صورت سه تن دیگر مشاهده میشودکه معلوم است نفر وسط آنها پادشاه است، و دست به قبضه ٔ شمشیر دارد، در دو طرف نقوش برجسته ای است که میدان شکارگاهی را نشان میدهد، در دیوار سمت غربی تصویرپادشاهی است که در قایقی نشسته و گرازی را با تیر زده است، در عقب شکارها پیلی چند دیده میشود، از طرفی چند تن رقاصه مشغول نواختن ساز میباشند، از طرف دیگر جمعی به کندن پوست شکارها مشغولند، نقش طرف راست تمام نشده و شکارگاه آهوئی را نشان میدهد که شاه بر اسب سوار است و تنی چند از اهل حرم در طرف راست بر تختی نشسته اند، نقشهائی که در طاق کوچک حجاری شده به اهمیت نقشهای طاق بزرگ نیست، و کتیبه ها معلوم است که در زمان بهرام پسر شاپور پسر نرسی حجاری شده، نقش دیواره ٔ راست این طاق صورت شاه است که پا بر روی سینه ٔاسیری نهاده است . مرحوم محمد حسنخان صنیعالدوله، درمرآت البلدان گوید: بُستان . وسطام . بستان طاق . عبارت از دو ایوان و طاق متصل بهم است، در کوهی که حد شمالی صحرای کرمانشاهان و بعبارة اُخری در دنباله ٔ کوه بیستون و مسافت آن تا شهر کرمانشاهان کمتر از دو فرسخ و در سمت شرقی این شهر واقع است . مؤلف دو دفعه طاق بستان را به رأی العین مشاهده کرده، یکی در مراجعت از حکومت لرستان در سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٢٨٠</span> هَ . ق . و وضع آن وقت این محل با حالت حالیه فرق دارد. زیرا که بعد از آن سفر مرحوم عمادالدوله در آنجا مرمتها کردند و بنای اصطخر و عمارتی گذاشته و بدین واسطه تغییراتی در آن پدید آمده، چنانکه در سفرنامه ٔ همایونی مسطور است . سفری دیگر که در رکاب فیروزی انتساب خسروانه بزیارت عتبات عالیات مستسعد گردید طاق بستان را ملاحظه کرد، معلومات این سفر در بهترین سیاق و اسلوبی در کتاب سفرنامه ٔ ملوکانه مسطور و همان را بعینه زیور این سطورقرار میدهد. اما در سفر اوّل اطلاعاتی که از طاق بستان بشهود حاصل و بعد از شهود بنگارش سیاحان و مسافرین عالم رجوع کرد و ثبت اوراق متشتته داشت، آن جمله را اینک جمع و در این مجموعه می نگارد. و هی هذه : این دو طاق را که از میان سنگ تراشیده و بیرون آورده اند یکی بزرگتر و دیگری کوچکتر است، بزرگتر در طرف یسار و از هر حیث عالیتر و خوش وضعتر است و پنجاه یا شصت پی ارتفاع و بیست و چهار پی عرض دارد، در جلو آن سکوئی از سنگ ساخته و تراشیده اند که در این وقت بسبب مرور دهور متغیر و زیاد پست و بلند شده است، آب فراوانی از چشمه ای که در زیر این طاق واقع است جاری و پارچه سنگهای بزرگ که جزء بنیان این سکو بوده است در زیر آب افتاده است، در بالای کمان طاق در وسط، صورت هلالی است و در هر طرف تصویر ملکی که در یکدست عقدی با تاجی از مروارید و در دست دیگر نیز کاسه ای مملو از مروارید دارند. صورتی که در طرف دست راست است بالنسبه تمام ولی از صورت دست چپ جز دست و بازوئی باقی نیست، زیرا که پاره ای از کوه افتاده است و از وضع کوه چنین مینماید که بعضی آثار و صور در بالای آن بوده و مرور زمان آن را خراب کرده است . خلاصه عقیده ٔ مؤلف این است که حجار این دو ملک یونانی بوده، بعلت اینکه از حیثیت دورنماسازی نسبتی بحجاریهای داخل طاق ندارد، و ازاین قبیل صورت حجاری شده در اغلب معابد و عمارات قدیم یونان دیده میشود، در بالای جلو این طاق سابق بر این مسطحه و کنگره ای بجهت نشستن بوده و بواسطه ٔ پله ای که از سنگ درآورده به آن صعود میکردند، ولی آن پله اکنون خراب است و رفتن به پشت بام طاق صعوبت دارد. در دیوار انتهای طاق، محاذی دهنه ای از سنگ، هیئت سواری برجسته ساخته شده، بر سر این سوار کلاه خودی است و از صورت او جز دو چشم، هیچ پیدا نیست، سایر اجزای جبهه ٔ او در زیر زرهی که به خود وصل است پنهان میباشد، و زرهی و قبای بلندی که بر روی زانوی او می افتد و اقسام بوته ها در آن منقور است، در بر دارد و نیزه ٔ بلندی در روی شانه ٔ راست او تکیه داده، در دست سپری و در طرف راست او ترکشی است پر از تیر. اسب ِ سوار که باجُثه ای قوی و بطور تناسب که ملاحظه شود کوتاه است، برگستوانی بر او پوشانیده شده و سمت راست این اسب و نیز یک قسمت از ران سوار، شکسته شده . از قرار مسموع اعراب وقتی که بر عجم غلبه کردند، این یادگار بزرگ سلاطین ایران را ناقص کردند. باری بهترین حجارهای قدیم و جدید دنیا، از این حجاری متحیر شده و میشوند، زیرابا کمال دقّت موهای یال و دُم اسب و حلقه های زره سوار و برگستوان را حجار بسیار خوب نموده . عقیده ٔ بعضی از اهالی بلد این است که سوار، رُستم است . ولی ارباب سیر را در باب سوار دو عقیده است، طایفه ای گویند خسرو کیانی و زُمره ای گویند خسرو پرویز است . بالای صُورِ سوار سه صورت دیگر نقش شده، اگر چه صوَرِ ثلاثه محو شده و چیزی جز خطوط و حدود آنها معلوم نیست، ولی باز چیزی که پدیدار میشود این است که لباس شخص وسطی مرصع بمروارید و کمربندی دارد نیز از چهار رشته ٔ مروارید و بند شمشیرش نیز مروارید است و از جواهر و زینتی که در سر و بر دارد و ترکیب هلالی که بالای تاج اوست و زلفهای بلندی که بشانه های او آویخته و بلندتر بودن قامت او از دو صورت دیگر معین میشود که این صورت، صورت پادشاه است . دست چپ او به قبضه ٔ شمشیر و غلاف شمشیر نیز مرصّع میباشد و در پا نیز کفش گشادی دارد و در دست راست او که بلندتر است، تاجی از مروارید است .شخصی که در دست چپ او است، یک دست او نیز وصل به این تاج است، لباس این شخص دومی از شخص اوّلی ساده تر وصورت آن را اعراب درهم شکسته اند، از وضع لباس او معلوم میشود که این صورت صورت زنی بوده است . شخص سوّمی نیز بسر تاجی دارد، موهای بلندی به شانه ٔ او آویخته، جبّه ٔ بلندی به دوش اوست، شبیه بجبه های یونانی و در هر دست کاسه ای دارد، اما کاسه ای که در دست چپ اوست معلق است مثل اینکه بخواهد به کسی شراب بدهد و اینکه آب از کاسه جاری باشد. در دیوار جنبین این طاق بزرگ، صورت شکارگاهها مرتسم است، در یک سمت در باتلاقی شکارگاهی است . و صید ماهی و شکار مرغابی و گراز در آن مینماید یعنی شخصی که تیر و کمانی در دست دارد صید میکند و جمعی بفیلها سوار و نیز مشغول شکارند. قایق زیادی در این باتلاق دیده میشود و اشخاصی که در قایقها مرتسم شده، نسوان بنظر می آیند. در مقابل این شکارگاه بحری، شکارگاه برّی است که شکارچیها برخی بر فیل و بعضی بر اسب سوار میباشند و آهودوانی میکنند و در بالای این صفحه، پهلوی سکوئی که صورت سازنده زیاد در آن سکو مرتسم کرده اند، شخصی سواره ایستاده، چتری بر سر دارد و تیر و کمانی در دست و همین شخص را در پائین صفحه ساخته اند که آهوی زیادی با تیر صید کرده والعجب که حجّاری این دو دیوار مسطور و حجّاری جاهای دیگر طاق به اتمام نرسیده است و غالب تصاویر ناتمام مانده و ظاهراً حادثه ٔ بزرگی در بین حجّاری اینجا روی داده که تمام نشده است . در دیوار دست چپ، محمدعلی میرزای مرحوم، در زمانی که حکمرانی کرمانشاهان میکرد قسمتی از حجاریهای قدیم را حک و صورت خود را آنجا مرتسم کرده . تاجی بر سر دارد. و لباسش جواهر است . اما درایوان کوچکتر چنانکه مسطور شد، نزدیک ایوان بزرگ و قریب بطاق ؛ دو صورت که مُتوج بقسمی از تاج میباشند مرتسم است، در بالای تاج چیزی مشهود است بشکل کره، این دو صورت پهلوی یکدیگر ایستاده و دستهایشان بقبضه ٔ شمشیر است، ریش و زلف آنها مجعد میباشد. درجه ٔ حجاری این طاق، بسیار پست تر از طاق اول است . دقائق و نکات علم نقاشی در حجاری این طاق، برخلاف طاق اول، مطلقاً ملحوظ نیست، دو لوح بخط پهلوی در دو طرف این دو صورت ارتسام یافته، در سمت راست، شاپور دوم، معروف به ذوالاکتاف، پسر هرمز ثانی . در طرف چپ، بهرام پسر شاپور است . سیلوستر دُساسی ْ، که از علمای فرانسه است و در خواندن خط پهلوی مهارت کامل دارد، این خط را خوانده و ترجمه کرده، بواسطه ٔ ترجمه ٔ او معلوم شده که این دو صورت، شبیه شاپور ذوالاکتاف، و بهرام پسر اوست . و یکی از دو ترجمه این است : این صورت بنده ٔ خدای شاپور عزیز، شاهنشاه ایران و انیران است، که از سلسله ٔ آسمانی پسر بنده ٔ خدای هرمز عزیز، شاهنشاه ایران و انیران، از سلسله ٔ آسمانی پسر بزرگ شاهنشاه نرسی عزیز است . همینطور بعینه شرحی درباب بهرام نوشته، الا اینکه بهرام را وراهرام پسر شاپور و پسر زاده ٔ هرمز می نویسد. در طرف دیگر صورت دو پاشاه است، که دست در یک حلقه دارند و بر زبر یک نفرعسکر رومی که بر روی افتاده است ایستاده اند و به اندک فاصله ای صورتی مرتسم است که منطقه ای از نور دور سر او ساخته اند و گویند این صورت تمثال زردشت است و شک نیست که این تماثیل در عهد بهرام بن شاپور که بانی کرمانشاهان است ارتسام یافته و دو صورت تصویر او و پدر او شاپور است و حلقه ای که در دست ایشان است، شایدعلامت کره ٔ زمین باشد و از افتادن عسکر رومی به آن هیئت، اشاره ای بزوال و انحطاط دولت روم کرده باشند. بالجمله صورتهای طاق بستان را طوری استادانه ساخته اندکه محل حیرت و در خاطر میخلد که اینها نتیجه ٔ هنر صنعتگران روم و یونان باشد که بخواهش پادشاه ایران ساخته باشند، و سنگی که این طاقها را از آن بیرون آورده اند، چنان صلب و خالی از منفذ و شکاف است که اصلاً نباتات از آن نمیروید. اینها اطلاعات سفر اول مؤلف بود که بشهود و ملاحظه ٔ کتب جغرافی و تواریخ ایران و فرنگ حاصل کرده و ثبت داشت . اما سفر ثانی معلوماتی بیش از آنچه در سفرنامه ٔ عتبات، بقلم معجز شیم خسروانی مرقوم است، نه مؤلف را نه دیگری را حاصل نیست لهذا بهمان شرح اقتصار نموده تیمناً می نگارد. و هو هذا:<br />شرحی که در باب طاق بستان در کتاب سفرنامه ٔ همایونی مسطور است :<br />روز یکشنبه ٔ پنجم شعبان، امروز صبح به کالسکه نشسته، بطاق بستان، یا طاق بسطام رفتیم . خلاصه دو طاق حجاری شده است، یکی بزرگتر است و طاقی هلالی در میان سنگ تراشیده اند، ارتفاع آن تخمیناً شش ذرع میشود، عرض و طول هم به همین نسبت، خیلی اثر بزرگی است، در عصر خسرو پرویز ساخته شده است، در سطح مواجه ایوان در قسمت پائین، تمثال خسرو را با لباس حرب و اسلحه ٔ سواره مجسماً از سنگ بیرون آورده اند، هیئت و اندام سوار و اندازه و قواره ٔ اسب، از طبیعت حالیه بزرگتر است، نیزه ای در دست خسرو است، ترکش تیری دارد. پای چپ اسب که برجسته از سنگ بیرون آورده بودند، از موضع ران، نمیدانم به دست کدام بیمروت بی تربیت شکسته شده است . شاید در استیلای عرب اینطور کرده باشند، یک دست خسرو را هم که نیزه گرفته است و قدری از سر اسب هم شکسته شده است، بدین شکستگی ارزد بصد هزار درست . اینطور حجاری و نقاشی به این صحت و درستی، میتوان ادعا کرد که کمتر دیده شده است . اعضاء متناسب، اندام درست، نکات همه جای خود به کاررفته، حالا محال است کسی بتواند اینطور حجاری کند، دم اسب راطوری قلم زده است که موبمو شماره میشود، اسب هم، زره پوش است، حلقه های زره را چنان نموده و با یکدیگر پیوسته است که ملاحظه ٔ آن حیرت انگیز است، زین و برگ اسب بزین فرنگی شبیه است، ساغری اسب باز و نمایان است . منگوله های زیادی چنانکه کردها حالا رسم دارند در سر وگردن اسب است و دو منگوله ٔ دیگر خیلی بزرگ و بلند از دو طرف از عقب آویخته است، بجای ترک بند، یا عوض رکاب، یا محض زینت بوده است . صفحه ٔ بالای این تمثال، باز صورت خسرو است، ایستاده است، شمشیر راستی بطور قداره های قدیم در جلو پا گذاشته، یک دستش بقداره تکیه کرده دست دیگرش به دست موبد موبدان است که در یسار خسرو ایستاده است، هر دو حلقه ای را گرفته اند که علامت اتحاد و یک جهتی است . لباس خسرو تاجی مکلّل بجواهر است . و کلجه ای کوتاه که آویزه های جواهر دارد، شلوار تنگی در پا و کفشی که به همین کفشهای فرنگی متداول حالیه شبیه است، طرز لباس موبد موبدان هم به همین طور است، غیر اینکه تاج و جواهر ندارد، طرف چپ خسرو، صورت زنی است که گویا شیرین باشد، در یک دستش ابریقی است ودست دیگر را بلند کرده حلقه را گرفته است . لباس شیرین بلباس رسمی ملکه ٔ انگلیس و فرانسه، مشابهت دارد. شنل بلندی در دوش شیرین است بطانه ٔ آن پوستی است که در سنگ معلوم نیست چه پوست است . لباسش برزخ لباس هندی و افغانی و ارمنی و فرنگی است . در سمت راست طاق، شکار جرگه ٔ خسرو است که در مرداب و نیزار، با زورق و کرجی صید میکند، شکارشان از خوک و مرغابی و ماهی مرکب، اعیان دولت و عمله ٔ طرب در زورقها نشسته اند، از نیزارها خوک میدوانند. خسرو با تیر میزند مطربان و مغنیان که بعضی زن هستند، آلات طرب، بخصوص چنگ در دست دارند، فیلهای زیاد حجاری شده است، که بعضی جرگه میرانند و بعضی شکارها را حمل میکنند این اشکال با آنکه کوچک است، و ریزه کاری شده است چنان خوب نقش شده است و فیلها و خوکها را طوری خوب حجاری کرده اند که عقل را حیران میکند، بالای این صفحه آغاغنی خواجه باشی محمدعلی میرزای مرحوم که از طوالش گیلان بوده، زحمت کشیده، صورت مرحوم شاهزاده را نشسته، و حشمةالدوله پسرش و پسر دیگر کوچکش را، داده است حجاری نموده، خود آغاغنی را هم، با هیئت مکروه ایستاده، در جلو شاهزاده نقش کرده اند، طوری بد و بیقاعده که واقعاً مهوع است وطاق را ضایع کرده است و بسکه بدحجاری شده، روی اشکال را رنگ آمیزی کرده اند، الحق مایه ٔ تضییع طاق شده است . مقابل این شکارگاه خوک، در صفحه ٔ سمت دست راست طاق، شکار جرگه ٔ مرال نقش شده است، اینجا پادشاه سواره ایستاده، چتر بزرگی بالای سرش نگاه داشته اند، سایر مردم شکار میکنند و مرال میدوانند، اینجا جرگه چیها، سوار اسب و شتر هستند، کشته های مرال را بشتر حمل کرده اند، بعضی از اشکال اینطرف ناتمام است، که از ابتداناقص مانده است اطراف این اشکال، اسلیمی و گل و بوته است بطرز خیلی خوب و درست نقش شده است، به خصوص درجلو ایوان که خیلی خوب منبت کرده اند، روی هلال طاق از طرف بیرون دو ملائکه نقش شده است، یکی شکسته و افتاده است، دیگری بی عیب باقی است، در وسط دو ملک، نقطه ٔوسط قوس هلال هلالی رو ببالا که گویا در آن عصر نشان دولتی بوده است، از سنگ بیرون آورده اند، بسیار ممتاز حجاری شده است، در خارج طاق پله ها از سنگ ساخته اند که از کوه ببالای طاق میرود، لکن از آن پله ها بالا رفتن خالی از اشکال نیست، چند نفر کوه رو که شب در بیستون رفته بودند آتش میکردند اینجا آمدند، از سنگهای صاف و جاهای سخت بالا میرفتند که در قوه ٔ هیچکس و هیچ حیوانی نبود، بسیار مایه تعجب بود عکاسباشی آمد عکس طاقها و عمارات را برداشت . اما یادگارها که مردم در این سنگها نوشته اند، جای سالم باقی نگذاشته است . بعد از این طاق و ایوان طاق دیگری است کوچکتر تمثال دو نفر حجاری شده است، اما نه بخوبی و دقت طاق اول، میگویند صورت شاپور و پسر اوست، خطوط پهلوی هم نوشته شده بود، ترجمه ٔ آن پیش عمادالدوله ملاحظه شد. اینجا نقل میشود: اینکه صورتش اینجاست، بهترین پرستاران دین هرمز است، شاه شاهان، شاپور اصل پادشاه ایران و عراق عرب است، خدای خدایان پسر پرستاران مذهب هرمز، بهترین پادشاهان هرمزیان از این شاخ آسمانی منتشر شدند خدایان و پادشاهان فارسی . (ترجمه ٔ لوح دیگر). صاحب این صورت بهترین پرستاران مذهب هرمز است، و او نرسی شاه پادشاه ایران و عراق عرب اصل آسمانی و بهترین جد او از طایفه ٔ هرمزیه شاه شاهان بوده و نرسی است . از این ایوان که میگذرد، در روی سنگی در کمر کوه سه صورت نقش شده، یکی زردشت است، دیگر شاپور و نرسی، یکنفر دیگر هم در زیر پای شاپور و نرسی افتاده است لگد کرده اند، دورسر زردشت طوق نور و خطوط شعاعی نقش شده است، بطوری که حالا در صور ائمه ٔ علیهم السلام رسم است کشیده میشود، بعد از این طاقها و اشکال عمادالدوله حوضخانه ساخته، در روی آن ایوان و عمارت عالی بنا کرده است، در اینجا شکار بز بسیار است، یک تکه ٔ چرزده آورده بودند، دو سر ستون از زیر خاک بیرون آمده در کنار دریاچه گذاشته بودند خوب حجاری شده و بی عیب مانده است، یک صورت مجسمه هم به هیئت بتهای قدیم از زیر خاک بیرون آمده، اما صورت و سیمای آن درست معلوم نیست، بهیکل و اندام آدمی است بزرگ، گفتند لرها اعتقادی به این سنگ دارند در لرز و تب و نوبه و سایر امراض، نخودو کشمش و سایر نذورات بپای این سنگ می آرند و غالباًمحروم نمیروند، بالطبع مردمان ابله و احمقند. خلاصه امروز هم کسل بودم، اشتها نبود، رنگ چهره و بشره خوب نیست، قدری در مرتبه ٔ فوقانی عمارت خوابیدم، عضدالملک، معیرالممالک، حکیمباشی طولوزان، میرزا علیخان، مهدی قلی خان، محمدعلی خان، و غیره بودند، عصر بعمادیه مراجعت کردیم . سراب قریه ٔ بسطام که در میان عوام بطاق بستان مشهور است، در اوایل بهار، متجاوز از یک صد سنگ آب دارد، رفته رفته کم میشود، در تابستان بیش ازهفت هشت سنگ باقی نمیماند و این آب بمزارع و قراء معینه قسمت میشود: مراد حاصل، چغا کبود، سرخلیجه، گاوبنده و این بلوک که از این آب مشروب میشود، در دفاتربلوک بسطام مینویسند و قصبه ٔ بسطام که هنوز آثار قلعه و خاکریز و بیوتات آن معلوم است، قدری دورتر از محلی است که حالا دهکده ٔ بسطام واقع است - انتهی . از قراری که یاقوت حموی در معجم البلدان در ضمن لفظ «شبدیز» نگاشته، یکی از اسامی طاق بستان شبدیز است . و گوید این محل موسوم شده به اسم شبدیز که در طاق مرتسم است و خلاصه تفصیلی که در باب طاق نوشته، این است :<br />شبدیز - چنانکه نصر گفته، منزلی است میان حلوان و قرمیسین (کرمانشاه ) در آخر کوه بیستون موسوم به اسم اسب خسرو و مسعربن مهلهل گوید: در یک فرسخی شهر کرمانشاه، در آنجا صورت اسب و مردی که بر آن سوار است در سنگ مرتسم و منقور کرده اند، این سوار را خودی بر سر و زرهی در بر و زره را بقدری حجار خوب ساخته است که گوئی زره واقعی و متحرک است، سوار پرویز و اسب شبدیز میباشد و در روی زمین نظیر و مانند این صورت یافت نمیشود و در طاقی که این صورت هست، صورتهای دیگر از مردان و زنان و پیاده و سواره بسیار هست، روبروی صورت پرویز شخصی است، که کلاه او مخروطی، کمربندی بسته است و بیلی در دست دارد، گوئی زمین را حفر میکند و چنان مینماید که آب از زیر پایش جاری است . احمدبن محمد همدانی گوید: از عجایب کرمانشاه که در عداد عجایب دنیامعدود است، صورت شبدیز است که در قریه ٔ خاتان مرتسم شده و مرسم آن قنطوس بن سنمار، معمار معروف بوده که بنای خورنق را در کوفه ساخته، و سبب رسم کردن صورت این اسب در این قریه این است که : شبدیز اسبی بود بهترو قوی جثه تر و با تعلیم تر و زیرکتر از جمیع اسبهای دنیا و آن را پادشاه هند برای خسرو پرویز، برسم هدیه فرستاده بود، بجهت اینکه رونده ترین اسبها بود و صفات خوب داشت، و مادامی که در زیر زین بود، بول نمیکرد، و سرگین نمی انداخت و شش وجب دوره ٔ سم او بود. خسرو نهایت میل و تعشق را به این اسب داشت . وقتی شبدیز ناخوش شد و ناخوشی او شدت یافت، خسرو خبردار شده، گفت اگر شبدیز بمیرد، هر کس خبر مرگ او را بمن دهد، حتماً او را خواهم کشت . اتفاقاً شبدیز مرد و امیرآخور اوبیمناک شد و نمیدانست چگونه این خبر را بخسرو بدهد که مورث هلاکت خود او نگردد، تدبیری که اندیشید این بود که نزد بهلبد، مطرب خسرو آمده صورت حال را به او گفت . (مقصود باربد است ). بهلبد گفت من چاره ٔ این کاررا خواهم اندیشید. وقتیکه خسرو بهلبد را ببزم طرب طلب کرد. باربد در ضمن نغمات اشعاری که اشعار بمرگ شبدیز میکرد، انشاد و تغنی کرد. خسرو گفت : وای بر تو. شبدیز مرد؟ بهلبد بی درنگ گفت اول کسی که مرگ شبدیز را اظهار کرد، پادشاه است . خسرو با وجود تأسفی که برمرگ اسب داشت حسن تدبیر بهلبد را پسندید و بر لطیفه و حیلتی که به کار برد و موجب خلاصی خویش و دیگران از هلاکت شد تحسین کرد. ولی از روی دادن این غائله بسیار جزع و ناله کرد و فرمان داد قنطوس صورت او را مرتسم کرد و چنان قنطوس صورت اسب را نگاشت و در تقدیم خدمت استادی و مهارت به کار برد، که صورت شبدیز به بهترین وضعی و کاملترین سبکی تجسم یافت چنانکه گوئی عیناً خود شبدیز است آنگاه خسرو بمحلی که تمثال شبدیز ترسیم شده بود رفت و بر چهره ٔ او نگریست و مدتی گریست و شرحی در موعظه و خاتمه و مآل کار هر کس و انتقال از این دار از روی اعتبار ایراد کرد بالجمله احمدبن محمد گوید: محاسن این صورت فراوان است و کسی این صورت را مشاهده نمیکند مگر اینکه تعجب بسیار به وی دست میدهد و گوید: از یکی از فقهاء معتزله شنیدم که میگفت اگر کسی از آخر بلاد فرغانه و اقصی بلاد سو برای تماشای این صورت مسافرت کند و بدین محل بیاید بر او ملامتی نیست و چنان است که آن معتزلی گفته : اگر این صورت صورت آدمی است پس این مصور رتبه ای در صنعت داشته که احدی در روی زمین این رتبه را دارا نشده و چنان سنگ او را مسخر بوده که هر لونی را میخواسته است بنماید واضح و آشکار نموده و چیزی که بنظر می آید این است که : الوان را به استعمال ادویه و بعضی فنون ظاهر کرده به هرحال قنطوس در نزدیکی صورت خسرو و شبدیز صورت شیرین کنیزک خسرو را نیز رسم کرده و صورت خود را هم سواره ساخته است که نام او باقی ماند. ابوعمران کردی اشاره بدین محل کرده گوید:<br />و هم نقروا شبدیز فی الصخر عبرةً<br />و راکبه برویز کالبدر طالع<br />علیه بهاءالملک و الوفد عکف <br />یخال به فجر من الافق ساطع<br />تلاحظه شیرین واللحظ فاتن ٌ<br />و تعطو بکف حسنتهاالاشاجع<br />یدوم علی کرالجدیین شخصه <br />و یلقی قویم الجسم و اللون ناصع<br />یکی از ملوک بطاق بستان رسید و در آن جا نزول کرد و پس از نوشیدن جامهای می و تأمل در نقش و نگارها بشگفت آمد و فرمان داد زعفران و سایر مطیبات برتمثالهای خسرو و شیرین و شبدیز مالیدند. یکی از شعراء در این معنی گفته است :<br />کاد شبدیز ان یحمحم لما<br />خلق الوجه منه بالزعفران <br />و کان الهمام کسری و شیر<br />ین مع الشیخ موبذ الموبذان <br />من خلوق قد ضمخوهم جمیعاً<br />اصبحوا فی مطارف الارجوان .<br />مؤلف (مرحوم محمد حسنخان ) گوید: اسکندر در <span class=\"hlight\" dir=\"rtl\">٣٢٦</span> ق . م . که از فتوحات ایران مراجعت کرد و ببابل میرفت و آن سفر آخر او بود که در بابل درگذشت، از کرمانشاهان عبور کرد و آن وقت این شهر موسوم به باغستان بود. دئودر مورخ سیسیلی می نویسد: باغستان ناحیه ای است که سزاوار است مسکن رب النوعها باشد، اشجار بسیار و فواکه فراوان دارد. از هرنوع محصول طبیعی در آنجا یافت میشود و برای زندگانی بهترین جاها است بنابراین میتوان گفت : طاق بستان طاق باغستان بوده زیرا ممکن است جائی که باغات بسیار دارد آنجا را باغستان یا بستان گویند و اطلاق هر دو لفظ صحیح است، یا اینکه باغستان از فرط استعمال بستان شده باشد، یا در آن وقت هم طاق بستان و هم طاق باغستان میگفتند. عقیده ٔ بعضی از مورخین فرنگ این است که :طاق بستان را سمیرامیس ملکه ٔ بابل تقریباً در سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٨٩٠</span> ق . م . بنا کرده، در اینکه سمیرامیس در مابین بابل و همدان بنای باغ و عمارتی کرده، حرفی نیست، تردیدی که هست این است که آیا آن بنا در طاق بستان شده یا در بیستون . واﷲ اعلم . (از مرآت البلدان ). و هیجده هزار اسب بر آخور بودش و در جمله ٔ خاصگان چون شبدیز، آنک به کرمانشاهان صفت او بر نقش کرده است، نزدیک دیهی که آن را بسطام خوانند. و بسطام گستهم بود خال خسرو. (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>). گستهم را «بسطام »و «وسطام » هم ضبط کرده اند و همه یک نام است و طاق وستام، وستان در کرمانشاهان که طاق بستان خوانند و شهر بسطام بسرحد خراسان به وی منسوب است . (حاشیه ٔ مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٧٧</span>). گستهم را به عربی بسطام نویسند و شهر بسطام و طاق وستان منسوب بدو است و من سکه ٔ این گستهم یا بسطام را دیده ام که (یَستهم - گستهم - یَستام - گستام ) خوانده میشود. (حاشیه ٔ مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٩٧</span>). و مرحوم بهار ذیل کتیبه ٔ بیستون آرد: بیستون در اصل بغستان است و تازیان غالباً آن را«بِهستون » خوانده اند و یاقوت گوید: بهستون قریه ای است بین همدان و حلوان و اسم او «ساسبانان » است و از شرحی که در باب غار شبدیز داده است معلوم میدارد که مرادش «طاق وسنان » میباشد... (سبک شناسی ج <span class=\"hlight\" dir=\"rtl\">١</span> حاشیه ص <span class=\"hlight\" dir=\"rtl\">٣١</span>). و در ص <span class=\"hlight\" dir=\"rtl\">٤٣</span> همان جلد آرد: کتیبه کوچک پهلوی ساسانی از شاپور دوم در طاق کوچک طاق وستان کنده شده است . و رجوع به کلمه ٔ «پرویز» در همین لغت نامه و فهرست تاریخ ایران در زمان ساسانیان و فرهنگ ایران باستان ص <span class=\"hlight\" dir=\"rtl\">٦٤</span> و یشتها ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٣٩٠</span> - <span class=\"hlight\" dir=\"rtl\">٤٠٨</span> و جغرافی غرب ایران ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>، <span class=\"hlight\" dir=\"rtl\">٢١٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٧٥</span>، <span class=\"hlight\" dir=\"rtl\">٢٨١</span> و تاریخ صنایع ایران شود.<br /></font></div>'),
(175104, 'طاق بستن', '<span class=\"hlight\">طاق بستن .</span> <font color=\"DarkGreen\"><b>[ ب َ ت َ ]</font></b> (مص مرکب ) ایجاد کردن طاق . ساختن طاق . <BR><font color=\"Blue\">◄</font> خوازه بستن . طاق نصرت بستن . طاق بندی . و رجوع به طاق بندی شود.<br /></font></div>'),
(175105, 'طاق بندی', '<span class=\"hlight\">طاق بندی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (حامص مرکب ) نقشی که بصورت طاق در دیواره ای سازند، برای خوشنمائی <span class=\"hlight\">:</span> <br />به هر روزنی قبله یکسو شده <br />همه طاق بندی ابرو شده .<br /><font color=\"Red\">زلالی (از آنندراج ).</font><br /></font></div>'),
(175106, 'طاق بهار', '<span class=\"hlight\">طاق بهار.</span> <font color=\"DarkGreen\"><b>[ ق ِ ب َ ]</font></b> (ترکیب اضافی، اِ مرکب ) قوس ِ قزح . رنگین کمان . کمان رستم .<br /></font></div>'),
(175107, 'طاق تاجکی', '<span class=\"hlight\">طاق تاجکی .</span> <font color=\"DarkGreen\"><b>[ ق ِ ج َ ]</font></b> (اِخ ) ظاهراً نام طاقی و دروازه ای بوده است به ری چه در کتاب النقض آمده است : و در شهر ری خادم و ابوالقاسم عبودیه و ابوالقاسم شوّاء و غیرهم که امیر قجقرشان بطاق تاجکی برآویخت همه رافضی بودند. (النقض ص <span class=\"hlight\" dir=\"rtl\">٨٥</span>) و در ص <span class=\"hlight\" dir=\"rtl\">٨٩</span> همان کتاب آمده است : و امیر قجقر بفرمود تا بتدارک آن انبان فروش خارجی که قصد ابوالقاسم عبدویه کرده بود از طاق تاجکی درآویختند.<br /></font></div>'),
(175108, 'طاق خان', '<span class=\"hlight\">طاق خان .</span> (اِخ ) یکی از نیاهای سلغریان : حمداﷲ مستوفی ذیل شعبه ٔ اول سلغریان آرد: بروایتی اصل ایشان از نسل سلغر است و او از تخم طاق خان پسر انتموزخان بود. (تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٥٠٣</span>).<br /></font></div>'),
(175109, 'طاق خرپشته', '<span class=\"hlight\">طاق خرپشته .</span> <font color=\"DarkGreen\"><b>[ ق ِ خ َ پ ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) عماری . (از فرهنگ سکندرنامه ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نوعی طاق . رجوع به خرپشته شود.<br /></font></div>'),
(175110, 'طاق دریا شکوه', '<span class=\"hlight\">طاق دریا شکوه .</span> <font color=\"DarkGreen\"><b>[ ق ِ دَرْ ش ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه است از آسمان <span class=\"hlight\">:</span> <br />بر آنم که این طاق دریا شکوه <br />معلق چو دودیست بر اوج کوه .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175111, 'طاق زدن', '<span class=\"hlight\">طاق زدن .</span> <font color=\"DarkGreen\"><b>[ زَ دَ ]</font></b> (مص مرکب ) طاق ساختن . ساختن بنای طاق را. تسقیف . سقف زدن .<br /></font></div>'),
(175112, 'طاق سنگی', '<span class=\"hlight\">طاق سنگی .</span> <font color=\"DarkGreen\"><b>[ ق ِ س َ ]</font></b> (ترکیب وصفی، اِ مرکب ) طاق که از قطعات سنگ ساخته شده باشد. <BR><font color=\"Blue\">◄</font> (اِخ ) نام گردنه ای است معروف به طاق سنگی در راه یزد. رجوع به گردنه ٔ طاق سنگی شود.<br /></font></div>'),
(175113, 'طاق شکربوره', '<span class=\"hlight\">طاق شکربوره .</span> <font color=\"DarkGreen\"><b>[ ق ِ ش ِ ک َ رَ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از قطاب و سنبوسه ٔ شکری است . (برهان ).<br /></font></div>'),
(175114, 'طاق طارم', '<span class=\"hlight\">طاق طارم .</span> <font color=\"DarkGreen\"><b>[ ق ِ رَ ]</font></b> (ترکیب اضافی، اِ مرکب ) به معنی طاق اخضر است که کنایه از آسمان باشد. (برهان ) (انجمن آرای ناصری ) <span class=\"hlight\">:</span> <br />رستخیز است خیز و باز شکاف <br />سقف ایوان و طاق طارم را.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(175115, 'طاق طاق', '<span class=\"hlight\">طاق طاق .</span> (اِ صوت ) حکایت آواز زدن چیزی بر چیزی چنانکه جامه ٔ شسته ٔ گازران بر سنگ و جز آن <span class=\"hlight\">:</span> <br />گه ز طاق طاق گردنها زدن <br />طاق طاق جامه کوبان ممتهن .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(175116, 'طاق فیروزه', '<span class=\"hlight\">طاق فیروزه .</span> <font color=\"DarkGreen\"><b>[ ق ِ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ترکیب اضافی، اِ مرکب ) و طاق فیروزه رنگ هر دو به معنی آسمان است . (برهان ). و رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">١٠</span> شود.<br /></font></div>'),
(175117, 'طاق لاجوردی', '<span class=\"hlight\">طاق لاجوردی .</span> <font color=\"DarkGreen\"><b>[ ق ِ ج ْ وَ ]</font></b> (ترکیب وصفی، اِ مرکب ) به معنی طاق کحلی است که کنایه از آسمان باشد. (برهان ) (انجمن آرا) (مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(175118, 'طاق محامل', '<span class=\"hlight\">طاق محامل .</span> <font color=\"DarkGreen\"><b>[ ق ِ م َ م ِ ]</font></b> (اِخ ) محلی در کوفه بوده است . اقبال آشتیانی ذیل احوال مؤمن الطاق آرد:چون در طاق محامل در کوفه دکان صرافی داشته او را مؤمن الطاق ... لقب داده اند. (خاندان نوبختی ص <span class=\"hlight\" dir=\"rtl\">٧٧</span>).<br /></font></div>'),
(175119, 'طاق مدنی', '<span class=\"hlight\">طاق مدنی .</span> <font color=\"DarkGreen\"><b>[ ق ِ م َ دَ ]</font></b> (ترکیب وصفی، اِ مرکب ) نوعی از طاق عمارت <span class=\"hlight\">:</span> <br />نکنی گر سفر مکه ویثرب چه غم است <br />طاق درگاه ضرور است که باشد مدنی .<br /><font color=\"Red\">واعظ قزوینی (از آنندراج ).</font><br /></font></div>'),
(175120, 'طاق مزار', '<span class=\"hlight\">طاق مزار.</span> <font color=\"DarkGreen\"><b>[ ق ِ م َ ]</font></b> (ترکیب اضافی، اِ مرکب ) طاق که بر سر بالین تربت سازند <span class=\"hlight\">:</span> <br />برو ای نوجوان داد جوانی ده که پیران را<br />خمیدنهای قد طاق مزار آرزو باشد.<br /><font color=\"Red\">ملاقاسم مشهدی (از آنندراج ).</font><br /></font></div>'),
(175121, 'طاق مقرنس', '<span class=\"hlight\">طاق مقرنس .</span> <font color=\"DarkGreen\"><b>[ ق ِ م ُ ق َ ن َ ]</font></b> (اِخ ) صفه ٔ حضرت سلیمان علیه السلام . (برهان ) <span class=\"hlight\">:</span> <br />رنگین تو کنی کمان شیطان <br />چون طاق مقرنس سلیمان .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> (ترکیب وصفی، اِ مرکب ) کنایه است از آسمان . (برهان ). و رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">١٠</span> شود <span class=\"hlight\">:</span> <br />ما باده میخوریم بشادی و خصم ما<br />جز غم بزیر طاق مقرنس نمی خورد.<br /><font color=\"Red\">کاتبی .</font><br /></font></div>'),
(175122, 'طاق میان', '<span class=\"hlight\">طاق میان .</span> (اِخ ) دهی است در چهار فرسنگی مشرق گاوکان .<br /></font></div>'),
(175123, 'طاق مینا', '<span class=\"hlight\">طاق مینا.</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (ترکیب اضافی، اِمرکب ) کنایه است از آسمان . طاق مینائی <span class=\"hlight\">:</span> <br />پیش از این کاین سقف سبز و طاق مینابرکشند<br />منظر چشم مرا ابروی جانان طاق بود.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(175124, 'طاق نصرت', '<span class=\"hlight\">طاق نصرت .</span> <font color=\"DarkGreen\"><b>[ ق ِ ن ُ رَ ]</font></b> (ترکیب اضافی، اِ مرکب ) کازه و تالار و عمارت چوبی و غیره که برای سرداران و پادشاهان پیروز هنگام بازآمدن از سفر یا جنگ آذین بندی کنند. خوازه بستن . قوس النصر. طاق پیروزی . کوپله . خوازه . گنبد. قبه <span class=\"hlight\">:</span> مجلس سنا رأی دادکه شکرانه ٔ خدای را بجا آرند، برای قیصر مقرر داشت مجسمه هائی بسازند، طاقهای نصرت بنا کنند، و او چندین دفعه پی در پی بسمت قنسولی انتخاب شود. و نیز مقرر داشتند که روز فتح، روز اعلان فتح و روز گذشتن آن را در دستور از اعیاد بدانند. (ایران باستان ص <span class=\"hlight\" dir=\"rtl\">٢٤٣٨</span>).<br /></font></div>'),
(175125, 'طاق نما', '<span class=\"hlight\">طاق نما.</span> <font color=\"DarkGreen\"><b>[ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ ]</font></b> (اِ مرکب )ایوانی کم عرض که در جلو اطاق سازند. <BR><font color=\"Blue\">◄</font> نمای دیوار بصورت طاق که عرض و پهنائی نداشته باشد.<br /></font></div>'),
(175126, 'طاق نگون', '<span class=\"hlight\">طاق نگون .</span> <font color=\"DarkGreen\"><b>[ق ِ ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) آسمان . (آنندراج ).<br /></font></div>'),
(175127, 'طاق نیلوفری', '<span class=\"hlight\">طاق نیلوفری .</span> <font color=\"DarkGreen\"><b>[ ق ِ ف َ ]</font></b> (ترکیب وصفی، اِ مرکب ) طاق لاجوردی است که کنایه از آسمان باشد. (برهان ) (انجمن آرا). و رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">١٠</span> شود.<br /></font></div>'),
(175128, 'طاق نیمخانه', '<span class=\"hlight\">طاق نیمخانه .</span> <font color=\"DarkGreen\"><b>[ ق ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) طاق نیم خایه . (برهان ).<br /></font></div>'),
(175129, 'طاق و ترم', '<span class=\"hlight\">طاق و ترم .</span> <font color=\"DarkGreen\"><b>[ ق ُ ت ُ رُ ]</font></b> (اِ مرکب، از اتباع ) رجوع به طاق و طارم شود.<br /></font></div>'),
(175130, 'طاق و ترنب', '<span class=\"hlight\">طاق و ترنب .</span> <font color=\"DarkGreen\"><b>[ ق ُ ت ُ رُمْب ْ ]</font></b> (اِ مرکب، از اتباع ) رجوع به طاق و طارم شود.<br /></font></div>'),
(175131, 'طاق و طارم', '<span class=\"hlight\">طاق و طارم .</span> <font color=\"DarkGreen\"><b>[ ق ُ رُ ]</font></b> (اِ مرکب، از اتباع ) از اتباع است : نقل است که یک شب هارون الرشید فضل برمکی را که یکی از مقربان بود گفت که امشب مرا ببر مردی بر که مرا بمن نماید که دلم از طاق و طارم تنگ آمده است . (تذکرةالاولیاء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٧</span>). رجوع به طاق و طرنب شود.<br /></font></div>'),
(175132, 'طاق و طرم', '<span class=\"hlight\">طاق و طرم .</span> <font color=\"DarkGreen\"><b>[ ق ُ طُ رُ ]</font></b> (اِ مرکب، از اتباع ) رجوع به طاق و طرنب شود <span class=\"hlight\">:</span> <br />از پی طاق و طرم خواری کشید<br />بر امید عزّ در این خواری خوشید.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(175133, 'طاق و طرنب', '<span class=\"hlight\">طاق و طرنب .</span> <font color=\"DarkGreen\"><b>[ ق ُ طُ رُمْب ْ ]</font></b> (اِ مرکب، از اتباع ) طاق و ترم . طاق و ترنب . طاق و طرم . طاق و طارم . از لغات مترادفه است، به معنی کرّ و فر و طمطراق و خودنمائی باشد. (برهان ). فر و شکوه <span class=\"hlight\">:</span> <br />آمد ز پی عروس خواهی <br />با طاق و طرنب پادشاهی .<br /> <font color=\"Red\">نظامی .</font><br />ما ببوش و عارض و طاق و طرنب <br />سر کجا که خود همی ننهیم سنب .<br /> <font color=\"Red\">مولوی .</font><br />غلغل طاق و طرنب و گیرودار<br />که نمی بینم مرا معذوردار.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(175134, 'طاق و طمطراق', '<span class=\"hlight\">طاق و طمطراق .</span> <font color=\"DarkGreen\"><b>[ ق ُ طُ طُ ]</font></b> (اِ مرکب، از اتباع ) نیزاز اتباع است . رجوع به طاق و طارم شود <span class=\"hlight\">:</span> <br />ای خداوندان طاق و طمطراق <br />صحبت گیتی نمی ارزد فراق .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(175135, 'طاق پل', '<span class=\"hlight\">طاق پل .</span> <font color=\"DarkGreen\"><b>[ ق ِپ ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) چشمه ٔ پل <span class=\"hlight\">:</span> <br />در طریق عشقبازی از کسی کم نیستم <br />موج سیلاب غمم پهلو بطاق پُل زند.<br /><font color=\"Red\">محمدقلی سلیم (از آنندراج ).</font><br /></font></div>'),
(175136, 'طاق پیروزه', '<span class=\"hlight\">طاق پیروزه .</span> <font color=\"DarkGreen\"><b>[ ق ِ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه است از آسمان <span class=\"hlight\">:</span> <br />از آنگه که بردم به اندیشه راه <br />در این طاق پیروزه کردم نگاه .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175137, 'طاق کحلی', '<span class=\"hlight\">طاق کحلی .</span> <font color=\"DarkGreen\"><b>[ ق ِ ک ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) به معنی طاق فیروزه رنگ است که کنایه از آسمان باشد. (برهان ) (انجمن آرای ناصری ). و رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">١٠</span> شود.<br /></font></div>'),
(175138, 'طاق کردن', '<span class=\"hlight\">طاق کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) وَتْر. وِتْر. (ترجمان القرآن ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175139, 'طاق کسری', '<span class=\"hlight\">طاق کسری .</span> <font color=\"DarkGreen\"><b>[ ق ِ ک ِ س را ]</font></b> (اِخ ) مشهورترین بنائی که پادشاهان ساسانی ساخته اند. قصری است که ایرانیان طاق کسری یا ایوان کسری مینامند و هنوز ویرانه ٔ آن در محله ٔ اسپانبر موجب حیرت سیاحان است . ساختمان این بنا را در داستانها بخسرو اول نسبت داده اند به عقیده ٔ هرتسلفد از بناهای عهد شاهپور اول است اما مسیو روتر روایات متداوله را تأیید کرده است و گوید: طاق کسری بارگاهی است که خسرو اول بنا نهاد. مجموع خرابه های این کاخ و متعلقات آن مساحتی بعرض و طول <span class=\"hlight\" dir=\"rtl\">٤٠٠</span>*<span class=\"hlight\" dir=\"rtl\">٣٠٠</span> گز را پوشانیده است، در این مساحت آثار چند بنا دیده میشود، علاوه بر طاق کسری عمارتی است در فاصله ٔ <span class=\"hlight\" dir=\"rtl\">١٠٠</span> گز در مشرق طاق و تلی که معروف به حریم کسری است . درسمت جنوب طاق و در جانب شمال ویرانه هائی است که در زیر قبرستان جدید پنهان شده، طاق کسری تنها قسمتی است از کل عمارت که اثر قابل توجهی از آن باقی است . نمای این بنا که متوجه بشرق است و <span class=\"hlight\" dir=\"rtl\">٢٩</span> یا <span class=\"hlight\" dir=\"rtl\">٢٨</span> گز ارتفاع دارد، دیواری بوده است بی پنجره لکن طاقنماهای بسیار و ستونهای برجسته و طاقهای کوچک مرتب بچهار طبقه و دیواری « دهلیزی » داشته است . نظیر آن را باید در بلاد شرقی که نفوذ یونانی در آن راه یافته خاصه در پالمورجستجو کرد. نمای عمارت شاید از صاروج منقش یا سنگهای مرمر یا چنانکه بعضی از نویسندگان جدید ادعا کرده اند از صفحات مسین زراندود و سیم اندود پوشیده بوده است اما هرتسفلد راجع به این قسمت اخیر که این جانب (کریستین سن )، در کتاب خود موسوم به «دولت ساسانی » ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span> اشارتی به آن کرده ام روایتی در هیچیک از مأخذهای قدیم پیدا نکرده است . تا سال <span class=\"hlight\" dir=\"rtl\">١٨٨٨</span> نما و تالار بزرگ مرکزی بر پا بود، اما در آن سال جناح شمالی خراب شد و اکنون جناح جنوبی نیز در شرف انهدام است . در وسط این جلوخان، دهانه ٔ طاق بزرگ بیضی شکلی نمایان است که عمل آن تا آخر بنا پیش میرفته است . این تالار که <span class=\"hlight\" dir=\"rtl\">٢٥/٦٣</span> گز پهنا و <span class=\"hlight\" dir=\"rtl\">٤٣/٧٢</span> گز درازا دارد بارگاه شاهنشاه بوده است . در پشت هر یک از جناحین نمای عمارت، پنج تالار کوتاه تر که طاقنماهائی در بالای آن دیده میشود موجود بوده و از بیرون بوسیله ٔ دیوار بلندی بسته میشده است . در عقب دیواری که حد غربی عمارت است . ظاهراً تالار مربعی در وسط بوده که دنباله ٔ تالار بار شمرده میشده و دو اطاق کوچکتر در طرفین آن وجود داشته است . در حفاریهای جدید که آلمانیها کرده اند چند قطعه تزیینات صاروجی از عهد ساسانیان به دست آمده است . طاق کسری که مقر عادی شاهنشاه بود نه از حیث جزئیات و نه از لحاظ کلیات وجاهتی نداشت . لکن نظارگان از عظمت و شکوه ظاهری و ضخامت اضلاع آن بحیرت و رعب دچار میشدند. ابن خرداذبه گوید: کاخ کسری در مدائن از همه ٔ بناهائی که با گچ و آجر ساخته شده بهتر و زیباتر است و بیتی چند از قصیده ٔ بحتری را که در وصف این ایوان سروده نقل میکند: «ایوان از شگفتی بنا پنداری شکافی است در پهلوی کوهی . کوهی رفیع است که کنگره هایش بر قلل رضوی و قدس مشرف است، کسی نداند که آدمی آن را برای آرامگاه جنیان ساخته است، یا جن برای آدمی کرده است ». بارگاه با شکوه شاهنشاه در این قصر بود و از این جا امور کشور را تمشیت میداد. (ایران در زمان ساسانیان ترجمه ٔ یاسمی ). مؤلف مرآة البلدان ناصری گوید: بزعم بعضی، چند تن از سلاطین این قصر را ساخته و به اتمام رسانیده اند. به هر حال ایوان کسری بهتر و بزرگترین بنائی است از ابنیه ٔ عالم، من خود او را دیده ام، چیزی که از او باقی است طاق ایوان است و بس . بنای آن با آجرهای طولانی است که طول آجرها یک ذرع و عرض آن کمتر از یک شبر است . حمزةبن حسن گوید: در کتابی که ابن مقفع او را نقل کرده است خوانده ام که ایوان مدائن از بناهای شاپوربن اردشیر است لکن موبد موبدان اشیوهست، میگفت ابن مقفع خطا کرده و اینطور نیست، بلکه بنائی که از شاپوربن اردشیر بوده بوجعفر منصور خراب کرده واینکه باقیمانده از خسرو پرویز است . آورده اند که : چون منصور خواست بغداد را بنا کند اراده کرد که ایوان را خراب کند و مصالح او را صرف بنای بغداد کند، در این باب با خالد برمکی مشورت نمود، خالد ابا کرد، منصور گفت این ابای تو جهت تعصبی است که هنوز از عجم در وجود تو باقی است، خالد عرض کرد چنین نیست که خلیفه میفرماید بلکه میخواهم که این بنا باقی باشد و عظمت آن دلالت کند بر کمال بزرگی آن دین و ملتی که بانیهای اینچنین ابنیه ٔ معظمه را منقرض کرد و برانداخت . منصور اعتنائی به این حرف نکرده امر بهدم آن نمود، همین که مشغول خراب کردن شدند دیدند مخارج خراب کردن آن از مصالحی که از او عاید میشود زیادتر است، خواستند دست از خراب کردن بردارند، خالد بخلیفه عرض کرد: حال که به این کار دست زده اند باید تا آخر خراب کنند و الا خواهند گفت بنائی که دیگری از ساختن آن عاجز نماند و به اتمام رسانید خلیفه در کار هدم آن درماند وحال آنکه خراب کردن از ساختن بمراتب آسانتر است و این ننگ در دودمان خلیفه خواهد ماند لهذا آن را بتمامه خراب کردند. پس بنا بر قول موبد موبدان ابوجعفر ایوان شاپور را خراب کرده . و اما بقول بعضی دیگر، گویند: ابوجعفر بقول ثانی خالد نیز اعتنا نکرد و دست از هدم ایوان کشید و ایوان مَقول قَول همین ایوان کسری است که باقی است . مؤلف گوید: مسعودی این را نسبت به هارون الرشید میدهد و میگوید: مکرّر شنیده ام که کسری همین که خواست ایوان را بسازد امر کرد خانه ها و زمینهای حول و حوش را خریدند و داخل عمارت نمودند و در بهای هر محقرخانه قیمت گزافی دادند تا نوبت رسید بخانه ٔ بسیار کوچکی که از پیرزنی در جوار ایوان بود. خواستند این خانه را نیز خریداری کنند. پیرزن از فروش آن اِبا و امتناع کرد و گفت : من همسایگی پادشاه را بعالم نمیدهم . کسری را این حرف بسیار خوش آمد، گفت اورا و خانه ٔ او را بحال خود واگذارید و ایوان را بسازید و عمارت پیرزن را نیز محکم نمائید. وقتی که من ایوان را دیدم قُبه ٔ بسیار کوچک محکمی نزدیک او دیدم که اهل آن ناحیه آن را قُبةالعجوز مینامیدند و میگفتند خانه ٔ همان عجوزه ٔ معروف است . از مشاهده و استماع این خبر تعجب کرده دانستم که قومی که بدین درجه رفق و مهربانی و عدل را نسبت برعیت خود مبذول میداشته اند چگونه مستأصل و منقرض شده اند و هیچ چیز این مشاعل مضیئه را منطفی نکرد مگر شروق آفتاب نبوت حضرت نبوی صلی اﷲ علیه و آله و سلم . ابن حاجب در ایوان گوید:<br />یا من یتیه بشاهق البنیان <br />اَنسیت صنعالدهر بالایوان <br />کتب اللیالی فی ذراها اَسطراً<br />بید البلی و ایادی الحدثان <br />ان ّ الحوادث والخطوب اذا شطت <br />اودت بکل ّ موثَق الارکان <br />ابوعباده ٔ بحتری قصیده ای در ایوان گفته معدودی از ابیات آن این است :<br />حصرت رحلی الهموم فوجهَ<br />-تَ الی ابیض المدائن عَنسی <br />اَ تَسلی عن الحظوظ و آسی <br />لمحل ّ من آل ساسان درسی <br />ذکرتنیهم الخطوب التوالی <br />ولقد تذکرالخطوب و تنسی <br />و هم خافضون فی ظِل ّ علل <br />مشرق یخسرالعیون و یخسی <br />مغلق بابه علی جبل القبق <br />الی دارتی خلاط و مکس <br />حُلل ٌ لم تکن کاطلال سُعدی <br />فی قِفار من البسابس ملس <br />و مساع لولا المحاباة مِنی <br />لم ِتطقه مسعاة عنس و عَبس <br />نقل الدّهرعهدهن ّ عن الجِدة<br />حتی غدون انضاءُ لبس <br />فکان ّ الجرماز من عدم الانس <br />و احلامه بَنیة رَمس <br />لوتراه علمت ان ّ اللیالی <br />جعلت فیه مَأتماً بعد عرس <br />و هو یُنبیک عن عجائب قوم <br />لا یُشاب البیان فیهم بلبس <br />فاذا ما رایت صورة انطا<br />کیةِ ارتعت بین روم و فُرس <br />در ایوان صورت کسری و انطاکیة و محاصره کردن کسری انطاکیه را مرتسم است و علاوه بر صورت محاصره صورت کسری را نقش کرده اند که با اهالی مکالمه میکند و این اشعار مُشعر براین مطالب است :<br />والمنایا مواثل و انوشر<br />وان یزجی الصفوف تحت الدّرفس <br />فی اخضرار من اللباس علی اصفر<br />یختال فی صبیغةورس <br />و عراک الرّجال بین یدیه <br />فی خفوت منهم و اغماض جرس <br />من مشیح یهوی بعامل رمح <br />و مُلیح من السنان بترس <br />وقتی جلال الدوله ٔ دیلمی به ایوان کسری رفته و بخطّ خوداین دو بیت را در ایوان نوشته است :<br />یا ایها المغرور بالدّنیا اعتبر<br />بدیار کسری فهی معتبرالوری <br />غنیت زمانا بالملوک و اصبحت <br />من بعد حادثة الزّمان کماتری <br />مؤلف گوید: از فقراتی که در مطاوی نظم و نثر مورّخین و فضلای عجم دیده شده چنین مستفاد میگردد که عقیده ٔ ایشان این بوده که طاق کسری از بناهای انوشیروان عادل است چه در ساسانیان این پادشاه به وصف عدل و نیکوکاری علم است . ظهیر فاریابی گوید:<br />جزای حُسن عمل بین که روزگار هنوز<br />خراب می نکند بارگاه کسری را<br />خاقانی شیروانی گوید:<br />هان ای دل عبرت بین از دیده نظر کن هان <br />ایوان مدائن را آئینه عبرت دان <br />یکره ز ره دجله منزل بمدائن کن <br />وز دیده دوم دجله بر خاک مداین ران <br />گه گه بزبان اشک آواز ده ایوان را<br />تا بو که بگوش دل پاسخ شنوی ز ایوان <br />دندانه ٔ هر قصری پندی دهدت نونو<br />پند سر دندانه بشنو ز بُن دندان <br />گوید که تو از خاکی ما خاک توایم اینک <br />گامی دو سه بر ما نه اشکی دو سه هم بفشان <br />ما بارگه دادیم این رفت ستم بر ما<br />برقصر ستمکاران گوئی چه رود خذلان <br />دیگری گوید:<br />چه عجب گر بقرنها پاید<br />هر بنا را که عدل بُنیاد است <br />گشت ویران مداین سبعه <br />طاق کسری هنوزآباد است <br />نوّاب والا معتمدالدوله در جام جم نوشته اند: ایوان کسری در شهر طیسفون که یکی از مداین سبعه است درمقابل سلوشیه (سلوسی ) که آن نیز از مداین سبعه میباشد واقع و بعض دیگر گویند: ایوان در اسبانبر که اعراب آن را اسفانبر گویند و در حرف الف و سین ذکر شده بود واقع است . به هر حال بنای آن از خشت پخته و در سمت شمال دجله و ربع فرسخ دور از آن میباشد این قصر <span class=\"hlight\" dir=\"rtl\">١٨٠</span> قدم طول و <span class=\"hlight\" dir=\"rtl\">٨٠</span> قدم ارتفاع دارد و در وسط طاق معروف بنا شده، و <span class=\"hlight\" dir=\"rtl\">٧٦</span> قدم دهنه ٔ آن و <span class=\"hlight\" dir=\"rtl\">١٤٨</span> قدم طول و <span class=\"hlight\" dir=\"rtl\">٨٥</span> پنج قدم ارتفاع طاق بوده، قُطر دیوارها که طاق روی آنها زده اند <span class=\"hlight\" dir=\"rtl\">٢٣</span> قدم است هشت طاقنما مانند که در هر طرفی چهارتای از آن واقع شده، در اطراف ایوان ساخته اند بالای این درگاهها چهار طبقه پنجره است که محض از برای زینت جلو عمارت بنا شده و به اصطلاح بناهای این عصر آنها را سواد مینامند، شاید که در این طاقچه ها در آن وقت مجسمه های مرمر یا فلز میگذارده اند، سقف ایوان شکافی برداشته، جزئی خرابی هم در جلو ایوان روی داده است و این شکاف ایوان بنابر احادیث شریفه و عقیده ٔ بزرگان دین مبین از آثاری است که در ولادت با سعادت حضرت سیدالمرسلین صلی اﷲ علیه و آله الطاهرین ظاهر شد. شریف الدین ابوعبداﷲ محمدبن سعید المصری البوصیری در قصیده ٔ بُرده در ولادت آن بزرگوار گوید:<br />و بات ایوان کسری و هو منصدع <br />کشمل اصحاب کسری غیر ملتئم .<br />شیخ سعدی گوید:<br />چو صیتش در افواه دنیا فتاد<br />تزلزل در ایوان کسری فتاد.<br />دو طرف شمال و جنوب ایوان مسلماً محل قصور و ابنیه ٔ عالیه است که بکلی منهدم شده، در جانب غربی آثار و علامت دیواری است و محتمل است که این عمارت منتهی به این دیوار میشده و اینکه در ضمن بعضی اقوال ضعیفه دیده شده که این عمارت از معابد عجم بوده، اصلاً محل اعتنا نیست، و معیناً از قصور سلطنتی است، چیزی که هست این است که چنانکه در اصطخر ذکر کردیم، میتوان گفت معبد و آتشکده هم جزو این عمارات عالیه بوده، و چون سایر ابنیه محو و منطمس شده است . باری اگر چه در بنای ایوان کسری روایات مختلف است، ولی آنچه بنظر صحیح می آید این است که ایوان را انوشیروان بنا کرد، و خسرو پرویز تمام نمود. تفصیل اینکه انوشیروان، بعد از غلبه به رومیها و تصرف شهر سلوسی، که از بناهای سلوکوس نیکاتور سردار اسکندر بود، خواست از خود بنائی در مقابل این شهر در سمت راست دجله نماید، بنابراین عزیمت شهر طیسفون را که اعراب مداین و فرنگیها اکتزیفون مینامیدند بنا کرد. اگر چه مداین جمع مدینه است و سلاطین ساسانی در دو سمت دجله بنا کرده بودند و قسمت عمده ٔ شهر در سمت شمال بوده و قسمت دیگر در جانب جنوب و الحال در آن محلی که خرابه ٔ شهر طیسفون است آثار قدیم شهر سلوسی نیز برپاست . یا شایداین دو شهر توأم بوده اند، اگر چه نزدیکی شهر طیسفون خرابه ٔ شهر کش هم دیده میشود ولی محتمل است که شهرکش شهر علیحده نبوده و از محلات خارج شهر طیسفون بوده است، اعراب در زمان خلفاء شهر سلوسی را مزیران میگفته اند. بنای شهر طیسفون را بهرام اشکانی کرده، خسروپرویز عمارات عالیه که از جمله همین طاق کسری است در آنجا ساخته است، سلاطین اشکانی در عرض سال اگر چند ماهی در طیسفون توقف کرده اند، عظمت شهر طیسفون بدرجه ای بوده که امپراطور سور قیصر روم بعد از فتح این شهر صد هزار نفر اسیر طیسفونی به روم برد. در عهد خسروپرویز بر دیوارهای ایوان پرده های مرصع و زری آویخته بودند و در زیر ایوان سردابها بود که مملو از طلا و نقره ٔ مسکوک و جواهر آلات و ادویه ٔ گرانبها بود. مؤلف گوید: مورخ در زینت طاق کسری نباید چندان اغراق کرده باشد زیرا بعد از آنکه سعد وقاص مداین را فتح کردو شهر طیسفون و ایوان کسری را متصرف شد از غنائمی که بچنگ لشکر اسلام آمد موافق مسطور است و عقیده ٔ جمیعمورخین یکی بساطی بود ابریشمین که شصت گز در شصت گزو اطراف آن بزمرد ترصیع یافته بود و هیجده ارش از آن بساط بجواهر غیر مکرر مزین بود و چون حواشی و جوانب این بساط را به اصناف ریاحین و ازهار و انواع اشجار و اثمار از جواهر نفیسه مرصع کرده بودند آن را بهارستان مینامیدند. این بساط را بمدینه بردند و قطعه قطعه کرده تقسیم کردند، آن قطعه ای را که بخدمت حضرت امیرالمؤمنین علی بن ابیطالب علیه السلام فرستادند حضرت آن را به بیست هزار درم و به قولی بیست هزار دیناربفروختند. بالجمله سه هزار زن و دوازده هزار خادمه در این عمارت سکنا داشتند ولی خسرو پرویز بهیچیک از این پانزده هزار زن که بهترین و صاحب حسن ترین نسوان و جواری ایران و عربستان و ترکستان و هندوستان بودندتعشق و میلی نداشت و عاشق به ایرن دختر امپراطور مرلس قیصر روم که عجم، آن را شیرین مینامند بود، ولی ایرن یا شیرین میلی بخسرو نداشت، و به فرهاد مایل بود. در تواریخ یونان در بنای ایوان روایت دیگر نیز هست و آن این است که بنای طاق را انوشیروان عادل نمود، و در سقف ناقوسی آویخته بود و رشته ای متصل به آن ناقوس بوده که سر رشته خارج از عمارت و در جلو خان بوده، عارضی که بدربار پادشاه می آمده، سر رشته را حرکت میداد، ناقوس صدا میکرد، انوشیروان مطلع میشد که مظلومی است، او را احضار میکرد و بعرض او میرسید. گویند روزی حماری از آنجا میگذشت، دستش برشته خورده، ناقوس صدا کرده است، انوشیروان گفت : نه اگر خر هم باشد عارض است ؟ خود از عمارت بیرون آمده دید حمار مفلوک لاغری است صاحب او را احضار کرده بعد از تنبیه و تأدیب که چرا این حیوان را لاغر و مفلوک کرده است خر را از او خریده به اصطبل خاصه سپرد و فرمانی بجمیع ولایات واهالی مملکت صادر کرد و مخصوص بحکام سپرد که اعلان دولتی نمایند که هر کس چهارپائی داشته باشد و از او درست توجه نکند و علوفه بقدری که باید به او ندهد مقصر دیوان خواهد بود - انتهی .<br />مؤلف گوید: مداین که جمع مدینه است شاید اسمی باشد که اعراب بجمیع شهرهائی که سلاطین اشکانی و ساسانی در عراق عرب ساختند داده باشند و بعضی گفته اند که مداین اسم شهر طیسفون و سلوسی است . اماوجهی غیر موجه است، اگر مدینتین میگفتند حق با قائل بود، و نیز چون سلاطین مدی که شعبه ای از سلاطین ایران میباشند اغلب آنجا را فتح میکرده اند منسوب به آنها گردیده و مدیانی بوده از فرط استعمال مدائن شده باشد. واﷲ اعلم . طوایف عربی که در حوالی سلوسی و طاق کسری منزل دارند طایفه ٔ «شمر« »منتفج « »بنی لام » میباشند. در تواریخ مسطور است که وقتی هارون الرشید بتماشای ایوان رفته بود. بکنار دجله اردو داشت روزی در چادر نشسته شنید که دو نفر از عمله ٔ خلوت او با هم صحبت میکردند و یکی از آنها با دیگری میگفت هیچ میدانی که این ایوان را چرا اینطور بنا نموده اند؟ شخصی که این عمارت را ساخته خیال داشت از فرط غرور و خیلاء به آسمان صعود نماید. هارون از استماع این حدیث بسیار متغیر شده حکم نمود بگوینده ٔ این کلام صد تازیانه زدند و گفت : میان جمیع طبقات سلاطین ماضی و حال نسبت و رابطه ای هست که تعصب یکدیگر را دارند بلکه از یک سلسله محسوب میشوند، چون این شخص نسبت بپادشاه بزرگی بی احترامی کرد تنبیه او لازم بود، و من راضی نیستم که احدی اسم یکنفر از سلاطین را بی تقدیم شرایط حرمت به زبان آرد - انتهی . قبر سلمان فارسی رضی اﷲ عنه در مدائن است و مسافت کمی به ایوان دارد در زمانی که سلمان از جانب خلیفه ٔ ثانی در مدائن حکومت داشت وفات نموده در این محل مدفون شد. و چون در سفری که موکب مسعود خسروانه به عراق عرب تشریف فرما، و بزیارت سلمان، و سیاحت ایران، نهضت فرمودند و تفصیل ایوان را مفصل از روی تحقیق و دقت، در سفرنامه ٔ همایونی مرقوم فرموده اند، شرح ایوان را اقتصار بمرقومات شاهنامه، و نقل از آن کتاب مستطاب میشود. تفصیل ایوان کسری، نقل از کتاب سفرنامه ٔ همایونی :<br />روز جمعه بیست و نهم رمضان، صبح بعد از حمام رفتن، سوار شدم، امین خلوت دیروز در کشتی با ما نبود، از راه بیابان و صحرا آمده است . قوش هم برای شکار دُراج، آورده است، سوار شده با ما آمد، ابتدا بزیارت قبر سلمان رفته، فاتحه ای خواندم، آداب زیارت تقدیم شد، از آنجا به ملاحظه ٔ طاق کسری رفتم، صبح امین السلطان را فرستاده بودم که آدمی بالای طاق بفرستد با طناب ارتفاع و عرض و طول و دهنه ٔ طاق را معین کند، سابقاً بطور تخمین نوشته شده بود، آنچه بدقت ذرع و معین کرده بودند، از این قرار است :<br />طول فرش انداز ایوان : <span class=\"hlight\" dir=\"rtl\">٤٨</span> ذرع . قطر پایه ٔ دیوار طاق دست راست : <span class=\"hlight\" dir=\"rtl\">٧</span> ذرع و چارک . قطر پایه ٔ درگاه سمت وسط: <span class=\"hlight\" dir=\"rtl\">٤</span> ذرع و نیم . قطر پایه ٔ درگاه دست چپ : <span class=\"hlight\" dir=\"rtl\">٧</span> ذرع و چارک . عرض دهنه ٔ طاق : <span class=\"hlight\" dir=\"rtl\">٣٤</span> ذرع و نیم . ارتفاع طاق : <span class=\"hlight\" dir=\"rtl\">٣٢</span> ذرع . دهنه ٔ پایه ٔ طاق از ابتدا تا انتها سمت شمال : <span class=\"hlight\" dir=\"rtl\">٩</span> ذرع . طول درگاه سمت شمال : <span class=\"hlight\" dir=\"rtl\">٦</span> ذرع . عرض هر درگاهی سمت شمال : <span class=\"hlight\" dir=\"rtl\">٤</span> ذرع . عکاسباشی هم، فتوگرافی بناها و اماکن را برداشته بود. بعد از ملاحظه ٔ طاق، به مقبره ٔ حذیفه ٔ یمانی و عبداﷲ انصاری رفتم، در یک محوطه است که چند نخل دارد، و یکی از نخیلات را تازه باد شکسته بود، چند نفر خدام از عرب بودند، فاتحه خوانده بیرون آمدم، بکشتی بازگشت شد، ناهار را در کشتی خوردم - انتهی . و استحسن (انوشروان ) انطاکیة و ابنیتها فامر بالتأنق فی نقش صورتها. و نفذ الصورة الی خلیفةبالمدائن . و امران یبنی بجنبها مدینة علی هیئة انطاکیة و صورتها... فسماها انوشروان الرومیة... و فی هذه المدینة یقول البحتری عند وصفه ایوان کسری :<br />و کان الایوان من عجب الصنعة<br />جوب فی جنب ارعن جلس .<br />و اذا ما رایت صورة انطاکیة<br />ارتعت بین روم و فرس .<br />و علی ذکر هذا الایوان . فان انوشروان بناه بالمدائن و یقال بل ابرویز. و هو من عجائب الابنیة. و من احسن آثار الاکاسرة. و به یضرب المثل فی الحسن و الوثاقة. و طوله مائة ذراع فی عرض خمسین ذراعاً. فی ارتفاع مائة ذراع . و هو مبنی ٌ بالاَّجر. والجص ّ. و ثخن الازج، خمس آجرات و طول الشرف خمس عشرة ذراعاً. (غرر اخبار ملوک الفرس ).<br />و من الخصائص و النفائس التی اجتمعت لابرویز ایوان المدائن المعروف بایوان کسری الذی ماله نظیر فی الدنیا. و هو باق الی الیوم و به یتمثل فی الابنیة العجیبة. (غرر اخبار ملوک الفرس ).<br />قعقاع از مدائن بگذشت، و از پس یزدگرد بشد، نیافتش، لختی ضعیفان را بیافت و بکشت، و هر چه خواسته یافت برگرفت، و سعد چون قعقاع را بفرستاد، خود با همه ٔ سپاه برنشست، و روی بمدائن نهاد، و چون بمدائن آمد کس را نیافت، و نگاه کرد کوشکها و باغها دید... و سعد اندر شهر فرونیامد، و این ایوان هنوز بمداین بجای است، صد و بیست رسن درازنای، و صد رسن بالا. و بجای خشتهای پخته خشتهای سنگین است تراشیده و بدان بنا کرده، و دوازده ستون بر رواق زده، هر ستونی صد رش از سنگ تراشیده و آن ایوان را کسری بن قباد بنا کرده، تا روز مظالم، تخت زرین آنجا بنهادی، سعد سپاه را گرد کرد، و بدان ایوان فرود آمد، و خودبه ایوان اندر شد، ... و عمروبن مقرن را بر غنایم کرد، و منادی بانگ کرد که همه چیزی باید که نزدیک وی آوردند تا گرد کند، آنگاه میان شما قسمت کند. و خود برنشست، و بمدائن اندرآمد، و بکوشک کسری فرود آمد، و آن خوانها <font color=\"DarkGreen\"><b>[ کذا ]</font></b> آکنده دید از خواسته که عدد آن کس ندانست، الا خدای عز و جل . از زر و سیم و جامه ها و سلاح و فرش، و لشکر پراکندند و خواسته را گرد میکردند.و نزدیک عمروبن مقرن بردند، و قعقاع قابل نهروان برفت، و هر خواسته که خواست برگرفت، تا چندان خواسته گرد آمد تا خمس بیرون کردند. و دیگر بر بخشیدند بر شصت هزار مرد. هر مردی را دوازده هزار درم آمد - انتهی . (ترجمه ٔ تاریخ بلعمی ) و آن استاد که این عمارت همی کرد چون دیوارها تمام برآورد، و بجای خم رسانید، اندازه ٔ ارتفاع آن با ابریشمی بگرفت، و در حقه ای نهاد، و بمهر کرد، و بخزانه دار شاه سپرده و روی درکشید و پنهان شد و چندانکه او را طلبیدند باز نیافتند، تا بعد از دو سه سال بازآمد، و پیش شاه رفت و گفت : بفرمای تا حقه ای که بمهر من خزینه دار را سپردم بیارد، که آن اندازه و قامت دیوارهاست، چون بیاوردند پیمودند، چند ارش از اندازه کمتر بود دیوارها، از آنچه دیوارها در این مدت فرونشسته بود، گفت اکنون از این عیب ایمن شدم و پایه ها قرار گرفت باکی نیست، و او را بدان پسندیده داشتند، و تمام کرد و از جمله ٔ عجائب آن است که گویند بوقت ولادت پیغمبر ما صلی اﷲ علیه و آله و سلم لختی از شرف آن ایوان بیموجبی و سببی ظاهر که دانستند بیفتاد. (نزهتنامه ٔ علائی تألیف حکیم رفهمردان بن ابوالخیر رازی، <span class=\"hlight\" dir=\"rtl\">٤٦٦</span> هَ . ق . گاهنامه ٔ سید جلال الدین طهرانی سال <span class=\"hlight\" dir=\"rtl\">١٣١١</span> هَ . ش .). مستر کوپر، در <span class=\"hlight\" dir=\"rtl\">١٨٩٤</span> م . نوشته است که طاق کسری، در همین وضع اندراس و ویرانی هم محیرالعقول است : «نخستین بار که از سمت مغرب ایوان کسری در نظر ما ظاهر شد شبیه ببرجی عظیم از کارهای نورمان بود، که بر طاقی بسیار بزرگ استوار باشد، دراطراف این قصر باشکوه، کلبه های حقیر و خیمه های ناچیز عرب دیده میشد». بحتری خود ادعا کرده است که از قبیله ٔ طی است، و این طایفه یکی از مهمترین قبایل عرب بشمار آمده، و صیت عظمت آن در اخبار چندین عشیره ٔ عرب مذکور است، بحتری در اکثر قصائد خود بسبکی سخن رانده است که بگمانش شعراء قدیم عرب آنطور سخن میگفته اند، یعنی بمدح و وصف قبایل خاص پرداخته، و وطنخواهی را بتفضیل طایفه ای بر طایفه دیگر مقصور و محدود دانسته است، اما در این قصیده عواطف او از تنگنای حدود مذکور خارج شده و شامل شهریاران ایران گردیده است که این قصر نامدار، از آثار قدرت آنان بر جای است . این قصیده که واسطةالعقد دیوان بحتری است حق آن بود که دراینجا بشعر انگلیسی ترجمه میشد. ولی علی العجاله بدرج ترجمه ٔ منثور چند بیتی از آن اکتفا میکنیم : هنوز پایداری بخرج میدهد، اگرچه سنگینی مصائب او را میفشارد، باک ندارد که از مفرش دیبا و پوشش دمشقی برهنه شده است . کوهی بلند است که کنگره های آن بر قلل رضوی و قدس مشرف است . کس نداند که آن را برای آرامگاه جنیان ساخته است یا جن برای آدمی کرده است . لکن می بینم گواهی میدهد که سازندگانش از پادشاهان ضعیف و ناتوان نبوده اند. چون دیدگان خویش را به کار میبرم گوئی مراتب درگاه نشینان را می بینم و رسولان و فرستادگان را مینگرم که ایستاده و از ازدحام روندگان و بازآیندگان در کمال حسرتند و شامگاهان دختران خوش آواز در میان کنیزکان مشکین موی در اهتزازند. این قصر برای شادی و رامش بنا شد و اینک ویرانه ٔ آن جای حزن و اندوه گردیده است و اینک بر من است که این ویرانه را یاری دهم بسرشکی که سزاوار مرگ نوجوانان است . این است تکلیف، هر چند خانه، خانه ٔ من است، و به جنس جنس من جز اینکه انعام ساکنان این قصور بر همجنسان من ثابت است و بفرهنگ خویش بهترین نهالی در سرزمین ما نشاندند. کشور ما را یاری دادند و نیروی آن را تقویت کردند، با پهلوانانی نیزه گذار و شجعانی زره پوش . (مقام ایران در تاریخ اسلام تألیف پروفسور د.س . مارگولیوث ترجمه ٔ رشید یاسمی ). اینک برای آنکه در هیچیک از مجامیع قصیده بحتری بتمامها درج نگردیده افزونی سود ادبی را قصیده بطرازی که در دیوان وی ثبت است بتمامی در اینجا ثبت افتاد:<br />قال ابوعبیدة الولیدبن عبیدبن یحیی البحتری یصف ایوان کسری :<br />صنت نفسی عما یدنس نفسی <br />و ترفعت عن جدا کل جبس <br />و تماسکت حیث زعزعنی <br />الدهر التماسا منه لتعسی و نکسی <br />بلغ من صبابة العیش عندی <br />طففتها الایام تطفیف بخس <br />و بعید ما بین وارد رفه <br />علل شربه و وارد خمس <br />و کان الزمان اصبح محمو<br />لا هواه مع الاخس الاخس <br />واشترائی العراق خطه غبن <br />بعد بیعی الشآم بیعة و کس <br />لاتزرنی مزاولا لاختباری <br />عند هذی البلوی فتنکر مسی <br />و قدیماً عهدتنی ذاهنات <br />آبیات علی الدنیئات شمس <br />و لقد را بنی نبوابن عمی <br />بعد لین من جانبیه و انس <br />و اذا ما جفیت کنت حریاً<br />ان اری غیر مصبح حیث امسی <br />حصرت رحلی الهموم فوجهَ<br />َت الی ابیض المدائن عنسی <br />اتسلی عن الحظوظ و آسی <br />لمحل من آل ساسان درسی <br />ذکرتینهم الخطوب و التوالی <br />و لقد تذکر الخطوب و تنسی <br />و هم خافضون فی ظل عال <br />مشرق یخسر العیون و یخسی <br />مغلق بابه علی جبل القبق <br />الی دارتی خلاط ومکس <br />حلل لم تکن کاطلال سعدی <br />فی قفار من البسابس ملس <br />و مساع لولاالمحاباة منی <br />لم تطقها مسعاة عنس و عبس <br />نقل الدهر عهدهن عن الجدة<br />حتی غدون انضاء لبس <br />فکان الجرما زمن عدم الانس <br />و احلامه بنیة رمس <br />لوتراه علمت ان اللیالی <br />جعلت فیه مأتماً بعد عرس <br />و هو ینبیک عن عجائب قوم <br />لایشاب البیان فیهم بلبس <br />فاذا مارایت صورة انطاکیة<br />ارتعت بین روم و فرس <br />والمنایا مواثل و انوشر<br />وان یزجی الصفوف تحت الدرفس <br />فی اخضرار من اللباس علی اصفر<br />یختال فی صبیغة ورس <br />و عراک الرجال بین یدیه <br />فی خفوت منهم و اغماض جرس <br />من مشیح یهوی بعامل رمح <br />و ملیح من السنان بترس <br />تصف العین انهم جداحیاء<br />لهم بینهم اشارة خرس <br />یغتلی فیهم ارتیابی حتّی <br />تتقراهم یدای بلمس <br />قدسقانی و لم یصرد ابوالغو<br />ث علی العسکرین شربة خلس <br />من مدام تقولها هی نجم <br />أضواللیل او مجاجة شمس <br />و تراها اذا اجدت سروراً<br />و ارتیاحاً للشارب المتحسی <br />افرغت فی الزحاج من کل قلب <br />فهی محبوبة الی کل نفس <br />و توهمت ان کسری ابرویز<br />معاطی و البلهبند اسی <br />حلم مطبق علی الشک عنی <br />ام امان غیرن ظنی و حدسی <br />و کان الایوان من عجب الصنعة<br />جوب فی جنب ارعن جلس <br />یتظنی من الکآبة ان یبدو<br />لعینی مصبح او ممسی <br />مزعجاً بالفراق عن ُانس اِلف <br />عزا و مرهفاً بتطلیق عرس <br />عکست حظّه اللیالی وبات <br />المشتری فیه و هو کوکب نحس <br />فهویبدی تجلداً و علیه <br />کلکل من کلا کل الدهر مرسی <br />لم یعبه ان بزمن بسط الد<br />یباج و استل من ستورالدمقس <br />مشمخر تعلوله شرفات <br />رفعت فی رؤوس رضوی و قدس <br />لا بسات من البیاض فما تبصر<br />منها الافلائل برس <br />لیس یدری اصنع انس لجن <br />سکنوه ام صنع جن لانس <br />غیر انّی اراه یشهد ان لم <br />یک بانیه فی الملوک بنکس <br />فکانی اری المراتب والقو<br />م اذا ما بلغت آخر حسی <br />و کان الوفود ضاحین حسری <br />من وقوف خلف الزحام و خنس <br />و کان ّ القیان وسط المقاصیر<br />یرجحن بین حو وُ لعس <br />و کان ّ اللقاء اول من امس <br />و وشک الفراق اول امس <br />و کان ّ الذی یرید اتباعاً<br />طامع فی لحوقهم صبح خمس <br />عمرت للسرور دهراً فصارت <br />للتعزّی رباعهم والتاسی <br />فلها ان اعینها بدموع <br />موقفات علی الصبابة حبس <br />ذاک عندی و لیست الدار داری <br />باقتراب منها ولاالجنس جنسی <br />غیر نعمی لاهلها عند اهلی <br />غرسوا من ذکائها خیر غرسی <br />ایدوا ملکنا و شدوا قواه <br />بکماة تحت السنور حمس <br />و اعانوا علی کتائب اریا<br />طِ بطعن علی النحور و دعس <br />و ارانی من بعدا کلف بالاشراف <br />طُراً من ُ کل سنخ ُ واس -انتهی .<br />طاق کسری در طرف مغرب عشایر شمرطوقه واقع شده است . و ایلچی فرستادند تا شهزادگان و سویجاق و بانجونونان و سوسای بتعجیل حاضر شوند، در طاق کسری به بندگی رسیدند. (رشیدی ). و عیسی بهنام در مجله ٔ دانشکده ٔ ادبیات در این باره آرد: خرابه های باقیمانده از شهر قدیم تیسفون را مرحوم ارنست هرتسفلد شرح داده و معرفی نموده است : در <span class=\"hlight\" dir=\"rtl\">١٩٢٨</span> م . بوسیله ٔ هیئتی از آلمانی ها بسرپرستی اُ. رتر کاوشهائی در محل تیسفون شروع شد و در <span class=\"hlight\" dir=\"rtl\">١٩٣٠</span> میسیون امریکائی موزه ٔ مترو پولیتن نیویورک بسرپرستی ژ.م . اپتن با هیئت آلمانی فوق الذکر در کاوشهای تیسفون شرکت کرد. آرتور کریستن سن در کتاب ایران در زمان ساسانیان از صفحه ٔ <span class=\"hlight\" dir=\"rtl\">٣٧٦</span> تا <span class=\"hlight\" dir=\"rtl\">٣٩٠</span> با استفاده ٔ از نتایج کار کاوش کنندگان در تیسفون قبل از تاریخ طبع کتاب خود خلاصه ای از اطلاعاتی را که راجع به این شهر در دست داشته انتشار داده و ما قسمتی از آن اطلاعات را در این مقاله از نظر خوانندگان میگذارنیم : پایتخت شاهنشاهان ایران خصوصاً در زمان خسرو اول وسعت و اعتبار یافت و تیسفون نام شهر عمده ای است که جزو مجموعه ای از چند شهر بود که بزبان شامی مذینه (شهرها) یا مذیناتا یا ماحوزه ملکا مینامیدند و اعراب آن را به المدائن ترجمه کردند و احتمال دارد که این کلمات ترجمه ٔ کلمه ٔ پهلوی شهرستانان باشد. شهرهای مهم این مجموعه، شهر وه اردشیر (سلوقیه قدیم ) و تیسفون بوده است . آمین میگوید: پایتخت ایران غیر قابل تسخیر بود و از چندین شهر تشکیل شده و حصاری آن را احاطه کرده بود واین حصار درهای بسیار محکمی داشت . «تیسفون » در مشرق دجله و «وه اردشیر» در مغرب آن قرار داشت و جسری آن دو را بهم متصل میکرد. و فردوسی در شاهنامه ٔ خود در ضمن بیان تاریخ سلطنت شاپور دوم میگوید چون رفت و آمد روی این پل روز بروز زیاد میشد شاپور در ابتدای سلطنت خود دستور داد پل چوبی دیگری روی دجله انداختند تا عبور از آن پل و مراجعت از پل دیگر انجام گیرد. تیسفون اصلی در مشرق دجله حصاری بصورت نیم دایره داشت و برجهای متعددی در این حصار بود که آثارشان هنوز باقی است و مجموع زمینی که در زیر آن بود از <span class=\"hlight\" dir=\"rtl\">٥٨</span> هکتارتجاوز نمیکرد و آن را بزبان عربی مدینةالعقیقة مینامیدند. در نتیجه کاوشهای سالهای <span class=\"hlight\" dir=\"rtl\">١٩٢٨</span> - <span class=\"hlight\" dir=\"rtl\">١٩٢٩</span> م . در این ناحیه آثار کلیسائی از زمان ساسانیان ظاهر گردیده است . در مشرق تیسفون امروز آرامگاهی بنام سلمان پاک وجود دارد که در محله ٔ سابق اسپانبر واقع است . کاخ شاهنشاهان ساسانی در همین محله قرار داشته و مرکب از حیاطها و طالارها و باغهائی بوده است که طاق کسرای امروزی در میان آن برپا بوده . در جنوب طاق کسری خرابه هائی بنام خزانه ٔ کسری و محل دیگری که بستان کسری نامیده میشود، احتمالاً باقیمانده ٔ شهر «وه آنتیوخ خسرو» میباشد که رومگان نیز نامیده میشد و خسرو اول پس از فتح انتاکیه عده ای از مردم آن شهر را به پایتخت خود انتقال داد و شهر جدید را برای آنها ساخت . قسمتی از مدائن را که در مغرب دجله قرار دارد حصاری از آجر احاطه کرده بود و قسمت مهم آجرهای آن از شهر بابل به این محل حمل شده بود و در محل قدیمترین ساختمان این شهر، یعنی سلوسی، بنا شده بود. اردشیر قسمتی از آن را تعمیر کرد و آن را « وه اردشیر» نامید (ترجمه ٔ کلمه ٔ وه اردشیر خوب اردشیر یا خانه ٔ اردشیر است ) وه اردشیر مرکز عمده ٔ مسیحیان ایران و مقر کاتولیکوس، رئیس مذهبی آنان بود و کلیسیائی در آن بنا شده بود که بفرمان شاپور دوم خراب شد و بعد از مرگ این پادشاه مجدداً آن را بر پا کردند: تقریباً در <span class=\"hlight\" dir=\"rtl\">٥</span> کیلومتری شمال وه اردشیر شهر کوچک درزنیذان قرار داشت . در مغرب وه اردشیر شهری بنام والاشاباذ واقع بود. بنابراین از مجموع شهرهائی که در زمان خسرو اول پایتخت ایران را تشکیل میدادند امروز پنج شهر آن را میشناسیم (تیسفون و رومگان در مشرق دجله، وه اردشیر «سلوس » درزنیذان ووالاشاباذ در مغرب آن .) اگر محله ٔ اسپانبر در مشرق وماحوزه در مغرب را به پنج شهر فوق اضاقه کنیم تعدادشهرهای پایتخت ساسانیان به <span class=\"hlight\" dir=\"rtl\">٧</span> میرسد. در طرفین رود دجله چند کاخ مخصوص شاهنشاه وجود داشته ولی از همه ٔ آنها معروفتر همان «طاق کسری » یا ایوان کسری است که در محله ٔ اسپانبر قرار داشته و خرابه های آن هنوز باعث تعجب و تحسین است . فردوسی بنای آن را به خسرو دوم (خسروپرویز) نسبت داده است :<br />ز ایوان خسرو کنون داستان <br />بگویم که پیش آمد از راستان <br />چنین گفت روشندلی پارسی <br />که بگذشت با کام دل چارسی <br />که خسرو فرستاد کسها بروم <br />بهند و به چین و به آباد روم <br />برفتند کاریگران سه هزار<br />ز هر کشوری آنکه بد نامدار<br />چو صد مرد بگزید اندرمیان <br />از ایران و اهواز و از رومیان <br />از ایشان دلاور گزیدند سی <br />از آن سی دو رومی یکی پارسی <br />گرانمایه رومی که بد هندسی <br />بگفتار بگذشت از پارسی <br />بدو گفت شاه این زمین درپذیر<br />سخن هر چه گویم همه یادگیر<br />یکی جای خواهم که فرزند من <br />همان تا دو صد سال پیوند من <br />نشیند بدو در نگردد خراب <br />ز باران و از برف واز آفتاب <br />مهندس بپذرفت از ایوان شاه <br />بدو گفت من دارم این دستگاه <br />چو دیوار ایوانش آمد بجای <br />بیامد بپیش جهان کدخدای <br />بریشم بیاورد تا انجمن <br />بتابند باریک تابی رسن <br />ز بالای دیوار ایوان شاه <br />بپیمود تا خاک دیوارگاه <br />رسن سوی گنج شهنشاه برد<br />ابا مهر گنجور او را سپرد<br />و ز آن پس بیامد به ایوان شاه <br />که دیوار ایوان برآمد بماه <br />چو فرمان دهد خسرو زودیاب <br />نگیرم بدان کار کردن شتاب <br />چهل روز تا کار بنشیندم <br />ز کاریگران شاه بگزیندم <br />بدو گفت خسرو که چندین زمان <br />چرا خواهی از من تو ای بد گمان ؟<br />نباید که داری تو زین دست باز<br />بزرّ و بسیمت نیاید نیاز<br />بفرمود تا سی هزارش درم <br />بدادند تا وی نباشد دژم <br />بدانست کاریگر راستگوی <br />که عیب آورد مرد دانا بدوی <br />اگر گیرد از کار ایوان شتاب <br />اگر بشکند گم کند نان و آب <br />شب آمد شد آن کارگرناپدید<br />چنان شد کز آن پس کس او را ندید<br />چو بشنید خسرو که فرغان گریخت <br />بگوینده بر خشم فرغان بریخت <br />چنین گفت کو را که دانش نبود<br />چرا پیش ما درفزونی نمود<br />دگر گفت کاریگران آورید<br />گچ و سنگ و خشت گران آورید<br />بجستند هر کس که دیوار دید<br />ز بوم و بر شاه شدناپدید<br />به بیچارگی دست از آن بازداشت <br />همی گوش و دل سوی اهواز داشت <br />کزآن شهر کاریگر آمد کسی <br />نماند چنان کار بی سر بسی <br />همی جست استاد آن تا سه سال <br />ندیدند کاریگری را همال <br />بسی یاد کردند از آن کارجوی <br />به سال چهارم پدید آمد اوی <br />همانگاه رومی بیامد چو گرد<br />بدو گفت شاه ای گنهکار مرد<br />بگو تا چه بود اندرین پوزشت <br />بگفتار پیش آید آموزشت <br />چنین گفت رومی که گر شهریار<br />فرستد مرا با یکی استوار<br />بگویم بدان کارها پوزشم <br />بپوزش کجا باید آموزشم ؟<br />فرستاد و رفتند از ایوان شاه <br />گرانمایه استاد با نیکخواه <br />همی برد دانای رومی رسن <br />همان مرد را نیز با خویشتن <br />بپیمود بالای کار و برش <br />کم آورد کار از رسن هفت رش <br />چنین گفت رومی که گر زخم کار<br />بر افزودمی بر سر ای شهریار<br />نه دیوار ماندی نه طاق و نه کار<br />نه من ماندمی بر در شهریار<br />بدانست خسرو که او راست گفت <br />کسی راستی را نباید نهفت <br />چو شد هفت سال آمد ایوان بجای <br />پسندیده ٔ مردم نیکرای <br />مر او را بسی آب داد و زمین <br />درم داد و دینار و کرد آفرین <br />همی کرد هر کس بایوان نگاه <br />بنوروز رفتی بدان جای شاه <br />کسی در جهان کاخ چونان ندید<br />نه از نامور کاردانان شنید<br />یکی حلقه اززر همی ریختند<br />از آن جای خرم درآویختند<br />فروهشته زو سرخ زنجیر زر<br />به هر مهره ای درفشانده گهر<br />چو رفتی شهنشاه بر تخت عاج <br />بیاویختندی بزنجیر تاج <br />بنوروز چون برنشستی بتخت <br />به نزدیک او مردم نیکبخت <br />فروتر ز موبد مهان را بدی <br />بزرگان و روزی دِهان را بدی <br />بزیر مهان جای درویش بود<br />کجا خوردش از کوشش خویش بود<br />بر آن سان بزرگی کس اندرجهان <br />ندارد بیاد از کهان و مهان .<br />هیئت کاوش کنندگان آلمانی اظهار کرده اند که ایوان بزرگی که امروز پابرجاست به امر خسرو اول ساخته شده . مجموع این کاخ و ساختمانهای فرعی آن در زمینی به وسعت <span class=\"hlight\" dir=\"rtl\">٣٠٠</span>*<span class=\"hlight\" dir=\"rtl\">٤٠٠</span> متر قرار گرفته و مرکب است از ایوان و آثار بنای دیگری در فاصله ٔ <span class=\"hlight\" dir=\"rtl\">١٠٠</span> متر از آن و تپه ٔ مصنوعی کوچکی بنام حرم خسرو، درجنوب ایوان، و در شمال آن خرابه های یک گورستان . ایوان کسری مهمترین قسمتی از مجموع کاخ تیسفون است که امروز برپاست . نمای آن بطرف مشرق است و <span class=\"hlight\" dir=\"rtl\">٢٨</span> و <span class=\"hlight\" dir=\"rtl\">٢٩</span> متر ارتفاع دارد و عبارت بوده است از دیواری بدون پنجره که طاقنماهائی در سرتاسر آن ساخته شده و بین طاقنماهانیم ستونهائی در طرفین قوسهای هلالی وجود دارند. مجموع این طاقنماها و قوسها و نیم ستونها در چهار طبقه ٔاز پائین ببالا گنجانیده شده . احتمالاً روی این بنای آجری را بوسیله ٔ گچ سفید کرده بودند و بعضی از قسمتهای آن را رنگ زده بودند و در بعضی قسمتهای دیگر روپوشی از سنگ مرمر ظاهر نمای بنا را میپوشانده است . تا تاریخ <span class=\"hlight\" dir=\"rtl\">١٨٨٨</span> م . تمام نمای این بنا برپابود و نقشی از آن در کتاب دیولافوآ کشیده شده در همین سال قسمت شمالی ایوان بزرگ خراب شد و اکنون برای قسمت جنوبی ایوان نیز خطر از بین رفتن در بین است . ایوان بزرگ بصورت گهواره ای بیضی شکل در میان نمای بنا قرار گرفته و عرض آن <span class=\"hlight\" dir=\"rtl\">٦٣</span> - <span class=\"hlight\" dir=\"rtl\">٢٥</span> متر و طول آن <span class=\"hlight\" dir=\"rtl\">٧٦</span> - <span class=\"hlight\" dir=\"rtl\">٤٣</span> </font></div>'),
(175140, 'طاق گرا', '<span class=\"hlight\">طاق گرا.</span> <font color=\"DarkGreen\"><b>[ ق ِ گ َرْ را ]</font></b> (اِخ ) در جاده راه کرند به سر پل کنونی (حدود حلوان قدیم ) بین آبادی سرخه دیزه، و پاطاق، گردنه ای است که چون از فراز آن بنشیب شروع شود، در اثناء راه بطاقی رسند که مانند طاق بستان، از کوه کنده شده و آن طاق به طاق گرا معروف میباشد. در افواه آمده که دلاکی آن طاق را ساخته، این طاق ساده و ازهرگونه زینت یا کتیبه و آثار عاری است <span class=\"hlight\">:</span> <br />ز حد بیستون تا طاق گرّا<br />جنیبتها روان با طوق و هرّا.<br /> <font color=\"Red\">نظامی .</font><br />اندر عهد یزدجردبن هرمز قصه ٔ شروین و خورین بوده است، و آنک روم خوانند نه روم بوده است، و شنیده ام روم حلوان خوانده اند، و آن تاه دُزد، که خورین او را بکشت، راه داشته است آنجا که اکنون طاق گرا خوانند. و شروین رااز آن زن جادو دوست گرفت، که مریه خوانندش، و او رامدتی آنجا ببست . چنانکه در قصه گویند، و خدای داند کیفیت آن . و اندر سیرالملوک گفته است که شروین را نوشیروان عادل بروم بگذاشت تا خراج بستاند، در آن وقت که او باز میگردید از جهت خروج پسرش انوش زاده . (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>). از ده کرند تا شهر حلوان بگریوه ٔ طاق گرا فرو باید رفت هشت فرسنگ . (نزهةالقلوب چ لندن ص <span class=\"hlight\" dir=\"rtl\">١٦٥</span>).<br /></font></div>'),
(175141, 'طاق یا جفت', '<span class=\"hlight\">طاق یا جفت .</span> <font color=\"DarkGreen\"><b>[ ج ُ ]</font></b> (اِ مرکب ) بازیی است . رجوع به طاق شود.<br /></font></div>'),
(175142, 'طاقات', '<span class=\"hlight\">طاقات .</span> (ع اِ) ج ِ طاقت و طاقة. رجوع به طاقة شود. تارها. لاها. قُوی . (یعنی تارها). <BR><font color=\"Blue\">◄</font> ج ِ طاق به معنی درختان بی فرع و شاخه : و اذا شرب منه نحو اربعطاقات بالماء اَبراءَ من المغص . (ابن البیطار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span> س <span class=\"hlight\" dir=\"rtl\">٣</span>) و له (دلبوث ) بصلة بیضاء علیها لیف لیس له طاقات . (ابن بیطار) <span class=\"hlight\">:</span> و درختان جوز چون ایشان را فروع و شاخ نباشد و آن درختان را به اصطلاح طاقات گویند و بهر هشت طاق درهمی لازم شود... فاما درخت شفتالو و آلوچه در حساب طاقات اند. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١١٠</span>). طاقات از درختهای بری به هر طاق درخت پنج درم . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>). و در هر سی و شش طاقات فستق و زیتون یک درهم و ما یاد کردیم که مراد بطاقات از درخت درختهائی اند که ایشان را شاخ نباشد. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(175143, 'طاقات ابی سوید', '<span class=\"hlight\">طاقات ابی سوید.</span> <font color=\"DarkGreen\"><b>[ ت ُ اَ س ُ وَ ]</font></b> (اِخ ) موضعی است در بغداد، بانی آن ابی سوید الجارود است این موضع در وسطکوهستانهای باب الشام واقع شده، قطیعه ٔ سوید در آنجاست و ربض آن در جانب غربی میباشد. (معجم البلدان ).<br /></font></div>'),
(175144, 'طاقات الراوندی', '<span class=\"hlight\">طاقات الراوندی .</span> <font color=\"DarkGreen\"><b>[ تُرْرا وَ ]</font></b> (اِخ ) جایگاهی است دربغداد و راوندی یکی از هوی خواهان منصور عباسی و از فرقه ٔ سرخسیة بوده، نام وی محمدبن الحسن است، خواهر علی بن عیسی بن ماهان زوجه ٔ وی بود. (معجم البلدان ).<br /></font></div>'),
(175145, 'طاقات العکی', '<span class=\"hlight\">طاقات العکی .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع َک ْ کی ی ]</font></b> (اِخ ) موضعی است در جانب غربی بغداد، و در گذرگاهی واقع است که بمربعه ٔ (محل اقامت در فصل بهار) شیب بن راح میگذرد. نام عکی مقاتل ابن حکیم است . (معجم البلدان ).<br /></font></div>'),
(175146, 'طاقات الغطریف', '<span class=\"hlight\">طاقات الغطریف .</span> <font color=\"DarkGreen\"><b>[ تُل ْ غ ِ ]</font></b> (اِخ ) محلی است واقع در مغرب بغداد. بانی آن غطریف بن عطاء است که برادر خیزران و دائی موسی الهادی و هارون الرشید بود. (معجم البلدان ).<br /></font></div>'),
(175147, 'طاقان', '<span class=\"hlight\">طاقان .</span> (اِخ ) از دیه های انار است . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span>). و در صفحه ٔ <span class=\"hlight\" dir=\"rtl\">٦٩</span> همان کتاب آرد: عوض دهقان آن را بنا کرده است و از قدیمتر ضیاع انار است .<br /></font></div>'),
(175148, 'طاقان', '<span class=\"hlight\">طاقان .</span> (اِخ ) از طسوج رودبار است . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>).<br /></font></div>'),
(175149, 'طاقان کوه', '<span class=\"hlight\">طاقان کوه .</span> (اِخ ) منزلی است از منازل بین راه از جاجرم تا نیشابور. حمداﷲ مستوفی در تحت عنوان مسافت طرق گوید: از مهماندوست بطریق جاجرم تا نیشابور و از توده تا طاقان کوه هشت فرسنگ و از او تا رباط بوزنگان بدیه احمدآباد شش فرسنگ و از او تا نیشابور چهارفرسنگ . (نزهة القلوب چ لیدن مقاله ٔ ثالثه ص <span class=\"hlight\" dir=\"rtl\">١٧٤</span>).<br /></font></div>'),
(175150, 'طاقباز', '<span class=\"hlight\">طاقباز.</span> (ص مرکب، ق مرکب ) سِتان . طاقواز.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاقباز خوابیدن یا طاقواز افتادن یا طاقواز خفتن </span> ؛ در تداول عامه سِتان خفتن . بر قفا خفتن . بر پشت خوابیدن . استلقاء. چارطاق خوابیدن در تداول عامه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاقباز کردن یاگذاشتن در</span> ؛ آن را بالتمام باز گذاشتن .<br /></font></div>'),
(175151, 'طاقت', '<span class=\"hlight\">طاقت .</span> <font color=\"DarkGreen\"><b>[ ق َ ]</font></b> (ع اِمص ) تاب . توان . (صحاح الفرس ). توانائی . (منتهی الارب ) (مهذب الاسماء) (ترجمان علامه ٔ جرجانی ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>). تیو. تاو. توش . پایاب . (حاشیه ٔ فرهنگ اسدی خطی نخجوانی ). وجد. (ترجمان القرآن ). وسَع. وسُع. وسِع. بَدَد. بِدّة. جَهد. جُهد. قوة. پای . قدرت . ذرع . (منتهی الارب ). قوت تحمل . نیروی تحمل تعبی و رنجی . استطاعت . شکیب . امکان . قدرت درکار. قبل . یقال : مالی به قبل ٌ؛ ای طاقةُ. (منتهی الارب ) <span class=\"hlight\">:</span> فرمانبرداریم آنچه بطاقت ما باشد، که این نواحی تنگ است و مردمانی درویش . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٦٩</span>). راهها تنگ است کرا نکند که رکاب عالی برتر خرامد هر مرادی که هست گفته آید تا بطاعت و طاقت پیش ببرند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٦٢</span>). گفتند <font color=\"DarkGreen\"><b>[ حصیری و پسرش ]</font></b> فرمانبرداریم ... اما مهلتی و تخفیفی ارزانی دارد که داند <font color=\"DarkGreen\"><b>[ خواجه احمد ]</font></b> ما را طاقت ده یک آن نباشد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٦٠</span>). بوسهل زوزنی بر خشم خود طاقت نداشت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨١</span>). خواجه ٔ بزرگ رنجی بزرگ بیرون طاقت بر خویش مینهد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٦٩</span>).<br />گر نیست طاقتم که تن خویش را<br />بر کاروان دیو سلیمان کنم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مکن خویشتن مار بر من که نیست <br />ترا طاقت زهرمار علی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گرد مثل مگرد که علم او<br />از طاقت و تحمل بیرون است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مرا با ملک طاقت جنگ نیست <br />و لیکن به صلحش هم آهنگ نیست .<br /> <font color=\"Red\">آتسزبن قطب الدین محمد.</font><br />بقدر طاقت برداشتمی . (کلیله و دمنه ).<br />طاقت پنجاه روزم نیست تا بینم ترا<br />شاه من بر من از این پنجاه بفکن آه را.<br /> <font color=\"Red\">(اسرارالتوحید).</font><br />طاقتی کو که بسرمنزل جانان برسم <br />ناتوان مورم و خود کی بسلیمان برسم .<br /> <font color=\"Red\">خاقانی .</font><br />بحسب طاقت خود طوقدار مدح توام <br />چرا ز طایفه ٔ خاصگان بماندم طاق .<br /> <font color=\"Red\">خاقانی (دیوان چ عبدالرسولی ص <span class=\"hlight\" dir=\"rtl\">٢٤١</span>).</font><br />در دهن از خنده که راهی نبود<br />طاقت را طاقت آهی نبود.<br /> <font color=\"Red\">نظامی .</font><br />من اندر خود نمی یابم که روی از دوست بردارم <br />بدار ایخواجه دست از من که طاقت رفت و پایابم .<br /><font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">باطاقت </span> ؛ با تاب و توان . باصبر. صبور. شکیبا <span class=\"hlight\">:</span> <br />در طاعت بی طاقت و بی توش چرائی <br />ای گاه ستمکاری با طاقت و با توش .<br /><font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بیطاقت </span> ؛ بیتاب و توان . بی صبر و شکیب <span class=\"hlight\">:</span> <br />کنون جوئی همی حیلت که گشتی سست و بیطاقت <br />ترا دیدم ببرنائی فسار آهخته و لانه .<br /> <font color=\"Red\">کسائی .</font><br />در طاعت بی طاقت و بی توش چرائی <br />ای گاه ستمکاری با طاقت و با توش .<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بیطاقتی </span> ؛ بیصبری . ناشکیبی . بی تاب و توان شدن <span class=\"hlight\">:</span> پسر از بیطاقتی شکایت پیش پدر برد.(گلستان ).<br />چو مسکین و بیطاقتش دید و ریش <br />بدو داد یک نیمه از زاد خویش .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاقت آوردن </span> ؛ برتافتن . بر خود هموار کردن . تاب آوردن <span class=\"hlight\">:</span> صیادی ضعیف را ماهی قوی بدام اندر افتاد، طاقت حفظ او نیاورد. (گلستان ). یکی را از بزرگان بادی مخالف در شکم پیچیدن گرفت طاقت ضبط آن نیاورد. (گلستان ). طاقت جور زبانها نیاورد. (گلستان ).<br />شوق است در جدائی و ذوق است در نظر<br />هم جور به که طاقت شوقت نیاوریم .<br /> <font color=\"Red\">سعدی .</font><br />هر که بخویشتن رود ره نبرد بسوی او<br />بینش ما نیاورد طاقت حسن روی او.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاقت بردن </span> ؛ صبر و شکیب کسی از دست رفتن . تاب و توان نداشتن <span class=\"hlight\">:</span> <br />دلش طاقت نبرد از عشق دلدار<br />رمیده هوش گشت و شد نگونسار.<br /> <font color=\"Red\">نظامی .</font><br />روی گشاده ای صنم طاقت خلق میبری <br />چون پس پرده میروی پرده ٔ خلق میدری .<br /> <font color=\"Red\">سعدی .</font><br />تحمل چاره ٔ عشق است اگر طاقت بری ورنه <br />که بار نازنین بردن بجور پادشا ماند.<br /> <font color=\"Red\">سعدی .</font><br />دوش مرغی بصبح مینالید<br />عقل و صبرم ببرد و طاقت و هوش .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاقت داشتن یا نداشتن </span> ؛ توانائی داشتن یا نداشتن . تاب و تحمل داشتن یا نداشتن <span class=\"hlight\">:</span> چندان رنج دید که جز سنگ خاره بمثل آن طاقت ندارد. (تاریخ بیهقی ). بوسهل زوزنی بر خشم خود طاقت نداشت . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٨١</span>). بیش طاقت سخن نمیدارم و بجان دادن مشغولم . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٦٢</span>). بکتغدی گفت : که طاقت این نواخت را ندارد. (تاریخ بیهقی همان چ ص <span class=\"hlight\" dir=\"rtl\">١٨١</span>).<br />شها ملوک جهان طاقت تو کی دارند<br />شغال ماده کجا زور شیر نر دارد.<br /> <font color=\"Red\">مسعود سعد.</font><br />حالی طاقت حرکت نداشت .(کلیله و دمنه ). و یا رنجی رساند که طاقت آن ندارم نگین انگشتری بدندان برکنم و زهر برمکم . (تاریخ بیهق ).<br />بگستی با فلک بیرون چرا رفتی <br />کجا داری تو با او طاقت گستی .<br /> <font color=\"Red\">خاقانی .</font><br />چگونه کشم بار هجرت به کوهی <br />که من طاقت برگ کاهی ندارم .<br /> <font color=\"Red\">عطار.</font><br />مگو آنچه طاقت نداری شنود<br />که جو کشته گندم نخواهی درود.<br /> <font color=\"Red\">سعدی .</font><br />من طاقت شکیب ندارم ز روی خوب <br />سعدی بعجز خویشتن اقرار میکند.<br /> <font color=\"Red\">سعدی .</font><br />در آن آتش نداری طاقت سوز.<br /> <font color=\"Red\">سعدی .</font><br />نه دسترسی بیار دارم <br />نه طاقت انتظار دارم .<br /> <font color=\"Red\">سعدی .</font><br />آن گوی که طاقت جوابش داری <br />گندم نبری بخانه چون جو کاری .<br /> <font color=\"Red\">سعدی .</font><br />روا باشد ار پوستینم درند<br />که طاقت ندارم که مغزم برند.<br /> <font color=\"Red\">سعدی .</font><br />غم زمانه خورم یا فراق یار کشم <br />به طاقتی که ندارم کدام بار کشم ؟<br /> <font color=\"Red\">سعدی .</font><br />تا کی ای جان اثر وصل تو نتوان دیدن <br />که ندارد دل من طاقت هجران دیدن .<br /> <font color=\"Red\">سعدی .</font><br />دگر ره گر نداری طاقت نیش <br />مکن انگشت در سوراخ کژدم .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاقت رسیدن و بطاقت رسیدن </span> ؛ طاقت کسی طاق شدن . بیتاب و بی شکیب شدن و رجوع به طاق شدن و طاقت طاق شدن شود <span class=\"hlight\">:</span> زید را طاقت برسید از جور بنی امیه و خروج کرد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span>). چون بطاقت رسیدند از حصار بیرون آمدند و مصاف بیاراستند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>). لشکر تاش در مدت مقام نیشابور از تنگی علوفه و نایافت قوت و تعذر اسباب معیشت بطاقت رسیده بودند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاقت طاق شدن کسی را</span> ؛ تاب و توان او بنهایت رسیدن . تحمل از دست دادن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاقت نماندن </span> ؛ صبر و توان نماندن . شکیب و تاب از دست رفتن <span class=\"hlight\">:</span> <br />مشتاقی و صبوری از حد گذشت ما را<br />گر تو شکیب داری طاقت نماندما را.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">طاقت مهمان نداشت خانه به مهمان گذاشت </span> ؛ طاقت دیدن ندارد روی پنهان میکند. (جامع التمثیل ).<br /></font></div>'),
(175152, 'طاقت زدا', '<span class=\"hlight\">طاقت زدا.</span> <font color=\"DarkGreen\"><b>[ ق َ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ زُ ]</font></b> (نف مرکب ) که طاقت و شکیب ببرد. که تاب و توان بزداید.<br /></font></div>'),
(175153, 'طاقت شکن', '<span class=\"hlight\">طاقت شکن .</span><font color=\"DarkGreen\"><b>[ ق َ ش ِ ک َ ]</font></b> (نف مرکب ) که طاقت برد و تاب و توان بشکند و بزداید. و رجوع به طاقت فرسا و طاقت زدا شود.<br /></font></div>'),
(175154, 'طاقت فرسا', '<span class=\"hlight\">طاقت فرسا.</span> <font color=\"DarkGreen\"><b>[ ق َ ف َ ]</font></b> (نف مرکب ) که تاب و توان از دست برد. طاقت زدا.<br /></font></div>'),
(175155, 'طاقدار', '<span class=\"hlight\">طاقدار.</span> (نف مرکب ) دارنده ٔ طاق . رجوع به طاق شود. <BR><font color=\"Blue\">◄</font> ایوان دار. <BR><font color=\"Blue\">◄</font> مجازاً نگهبان و محافظ <span class=\"hlight\">:</span> <br />دین را که بود تو طاقداری <br />زین گونه چهار طاق داری .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175156, 'طاقدانه', '<span class=\"hlight\">طاقدانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) نبق . بار درخت کنار. (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(175157, 'طاقدیس', '<span class=\"hlight\">طاقدیس .</span> (ص مرکب، اِ مرکب ) به معنی طاق مانند، چه دیس مانند را گویند. (برهان ). و رجوع به دیوان رودکی چ نفیسی ص <span class=\"hlight\" dir=\"rtl\">١١١٠</span> شود. <BR><font color=\"Blue\">◄</font> صفه ٔ حضرت سلیمان . (برهان ). <BR><font color=\"Blue\">◄</font> تیزی پیش عمارت . <BR><font color=\"Blue\">◄</font> ایوان پادشاهان . (برهان ) <span class=\"hlight\">:</span> <br />دست بهشت صدر او دست قدر بخدمتش <br />گنبد طاقدیس را بسته بطاق چاکری .<br /> <font color=\"Red\">خاقانی .</font><br />در خطبه شاه کیوان خوانیش وگر بجوئی <br />در زیر طاقدیسش کیهان تازه بینی .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175158, 'طاقدیس', '<span class=\"hlight\">طاقدیس .</span> (اِخ ) تخت طاقدیس . تخت خسرو پرویز را که از فریدون به وی رسیده بود طاقدیس میگفتند. گویند جمیع حالات فلکی و نجومی در آن ظاهر میشده و آن سه طبقه بوده و در هر طبقه جمعی از ارکان دولت او جابجا قرار میگرفته اند و خسرو پرویز بر آن تخت ملحقات و تصرفات کرده بود. (برهان ). طول آن تخت یکصد و هفتاد ذراع و عرض آن یکصد و بیست ذراع و مکلل بجواهر بود. (غیاث اللغات ). و در حاشیه ٔ چاپ جدید برهان که به اهتمام دکتر معین منتشر شده آمده است : هرتسفلد رساله ٔ ممتعی در باب تخت طاقدیس نوشته اشاره بقول مورخ بیزانسی کدرنوس کرده که او از یکی از کتب تئوفان (نیمه ٔ دوم قرن هشتم م .) روایت کرده است . کدرنوس گوید هرقل قیصر پس از انهزام خسرو پرویز در سال <span class=\"hlight\" dir=\"rtl\">٦٢٤</span> وارد کاخ گنزک شد. «بت خسرو را دید که هیأتی مهیب داشت و تصویر پرویز را هم مشاهده کرد که بر بالای کاخ بر تختی قرار گرفته بود. این تخت بکره ٔ بزرگی مانند آسمان شباهت داشت و در گرداگرد آن خورشید و ماه و ستارگان نمودار بودند که کافران آنها را می پرستیدند و تصویر رسولان شاه نیز در گرد آن بود که هر یک عصایی در دست داشت . در این گنبد بفرمان دشمن خدا (یعنی خسرو) آلاتی تعبیه کرده بودند که قطراتی چون باران فرومیریخت و آوایی رعدآسا بگوش میرسانید...» (کریستنسن ایران در زمان ساسانیان ص <span class=\"hlight\" dir=\"rtl\">٤٦٦</span> ببعد) <span class=\"hlight\">:</span> <br />ز تختی که خوانی ورا طاقدیس <br />که بنهاد پرویز دراسپریس ...<br />بیاورد پس تخت شاه اردشیر<br />وز ایران هر آن کس که بد تیز ویر<br />بهم درزدند آن سزاوار تخت <br />بهنگام آن شاه پیروز بخت <br />ورا درگر آمد ز روم و ز چین <br />ز مکران و بغداد و ایران زمین <br />هزار و صد و بیست استاد بود<br />که کردار این تختشان یاد بود...<br />بفرمود تا یکزمان دم زدند<br />بدو سال تا کار بر هم زدند...<br />به رش بود بالاش صد شاه رش <br />چو هفتاد رش بر نهی از برش ...<br />برویش ز زرین صد و چل هزار<br />ز پیروزه برزرّ کرده نگار<br />همه نقره ٔ خام بد میخ و بش <br />یکی ز آن بمثقال بد شصت و شش ...<br /> <font color=\"Red\">(شاهنامه چ بروخیم ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٧٧</span> ببعد).</font><br />با درفش کاویان و طاقریس <font color=\"DarkGreen\"><b>[ طاقدیس ]</font></b>.<br />زر مشت افشار و شاهانه کمر. (حاشیه ٔ فرهنگ اسدی نخجوانی بنقل از رودکی با ضبط «طاقریس »). رجوع به کلمه ٔ پرویز شود <span class=\"hlight\">:</span> <br />بگرداگرد تخت طاقدیسش <br />زبان پادشاهان خاک لیسش .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175159, 'طاقدیس آینه گون', '<span class=\"hlight\">طاقدیس آینه گون .</span> <font color=\"DarkGreen\"><b>[ س ِ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه است از آسمان <span class=\"hlight\">:</span> <br />همی سگالد این طاقدیس آینه گون <br />که جفت ساز جلال تو تیزتر سازد.<br /><font color=\"Red\">مجیر بیلقانی .</font><br /></font></div>'),
(175160, 'طاقدیسی', '<span class=\"hlight\">طاقدیسی .</span> (اِ) نام نوایی است از سی لحن باربد.<br /></font></div>'),
(175161, 'طاقستان', '<span class=\"hlight\">طاقستان .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِ مرکب ) زمین طاقناک . رجوع به طاق شود: عادیة؛ شتران ماننده ٔ در طاقستان که بشوره گیاه میل نکنند. (منتهی الارب ).<br /></font></div>'),
(175162, 'طاقنما بستن', '<span class=\"hlight\">طاقنما بستن .</span> <font color=\"DarkGreen\"><b>[ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ ب َ ت َ ]</font></b> (مص مرکب ) از آنچه افزارو اسباب آرایش باشد بصورت طاق کردن . <BR><font color=\"Blue\">◄</font> طاق را از گونه های مختلف آلات و ادوات زینت دادن . بویژه از اقسام بلورینه و ظروف آبگینه و چراغ و غیره . <BR><font color=\"Blue\">◄</font> در اطراف تکایا و حسینیه ها جاهائی چون طاقی زینت کردن از قالی و چراغ و سلاحهای قدیم چون شمشیر و سپر و غیره که مخصوصاً در عاشورا معمول دارند.<br /></font></div>'),
(175163, 'طاقنی', '<span class=\"hlight\">طاقنی .</span> (اِ) غار است . (فهرست مخزن الادویه ). و رجوع به ذافنی الاسکندرانی شود.<br /></font></div>'),
(175164, 'طاقه', '<span class=\"hlight\">طاقه .</span> <font color=\"DarkGreen\"><b>[ ق َ ]</font></b> (اِخ ) ده کوچکی است از دهستان زیلائی بخش مسجدسلیمان شهرستان اهواز در <span class=\"hlight\" dir=\"rtl\">٢٦</span>هزارگزی شمال باختری مسجدسلیمان و <span class=\"hlight\" dir=\"rtl\">٤</span>هزارگزی خاور مسجدسلیمان به لالی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٥٠</span> نفر است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(175165, 'طاقه', '<span class=\"hlight\">طاقه .</span> <font color=\"DarkGreen\"><b>[ ق َ ]</font></b> (اِخ ) دهی است از بخش قلعه ٔ زراس شهرستان اهواز در <span class=\"hlight\" dir=\"rtl\">٢٨</span>هزارگزی باختری قلعه ٔ زراس . کنار شوسه ٔ مسجدسلیمان به هفت چشمه . جلگه . گرمسیر. مالاریائی با <span class=\"hlight\" dir=\"rtl\">١٤٠</span> تن سکنه . آب آن از چاه وقنات . محصول آن غلات . شغل اهالی زراعت و گله داری و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(175166, 'طاقواز', '<span class=\"hlight\">طاقواز.</span> <font color=\"DarkGreen\"><b>[ طاق ْ ]</font></b> (ص مرکب ) طاقباز. رجوع به طاقباز شود.<br /></font></div>'),
(175167, 'طاقچه', '<span class=\"hlight\">طاقچه .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b>(اِ مصغر) مُصغر طاق . (آنندراج ). طاق خرد. طاقی زیرِ رَف . قسمتهای کوچک فرورفته در دیوار اطاق و جز آن که برای نهادن اشیاء و اسباب خانه سازند. جائی برای نهادن اشیاء و مایحتاج فرودتر از رف بر دیوار. رَف ِ کوتاه . جائی در کمر دیوار اطاق که چیزها در آن نهند.جای آوند و دیگر چیزها که در اطراف اطاقها میسازند.و مجازاً بر خم ابرو نیز اطلاق شده است <span class=\"hlight\">:</span> <br />از طاقچه ٔ دو نرگس مست <br />بر سفت سمن عقیق می بست .<br /> <font color=\"Red\">نظامی .</font><br />طاقچه ٔ قدر او طاق سپهر بلند<br />باغچه ٔ بزم او باغ بهشت برین .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />صفحه ٔ قدر ترا طاقچه طاق فلک <br />گلشن بزم ترا باغچه خلد برین .<br /> <font color=\"Red\">سلمان ساوجی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">دلش طاقچه ندارد</span> ؛ که راز خویش نگه نتواند داشت . که هر چه درد دل دارد گوید.<br /></font></div>'),
(175168, 'طاقچه جق', '<span class=\"hlight\">طاقچه جق .</span> <font color=\"DarkGreen\"><b>[ چ َ ج َ ]</font></b> (اِخ ) دهی از دهستان آتش بیگ بخش سراسکند شهرستان تبریز. واقع در <span class=\"hlight\" dir=\"rtl\">٤٠</span>هزارگزی باختر سراسکند و <span class=\"hlight\" dir=\"rtl\">٢٥</span>هزارگزی بخط آهن میانه - مراغه . کوهستانی، معتدل . با <span class=\"hlight\" dir=\"rtl\">٤٨٦</span> تن سکنه . آب آن از چشمه و رود. محصول آنجا غلات و حبوبات . شغل اهالی زراعت و گله داری . راه آن مالرو است . (از فرهنگ جغرافیائی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٢</span>).<br /></font></div>'),
(175169, 'طاقچه داش', '<span class=\"hlight\">طاقچه داش .</span> <font color=\"DarkGreen\"><b>[ چ َ ]</font></b> (اِخ ) دهی ازدهستان ارشق بخش مرکزی شهرستان مشکین شهر. واقع در <span class=\"hlight\" dir=\"rtl\">٥٠</span>هزارگزی شمال مشکین شهر و <span class=\"hlight\" dir=\"rtl\">٥٠</span>هزارگزی شوسه ٔ گرمی اردبیل . کوهستانی معتدل . با <span class=\"hlight\" dir=\"rtl\">٨٢</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات و حبوبات . شغل اهالی زراعت و گله داری . راه مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(175170, 'طاقچه پوش', '<span class=\"hlight\">طاقچه پوش .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (نف مرکب، اِ مرکب ) جامه ای که کف طاقچه را بدان میپوشیدند و اعیان و توانگران طاقچه پوش عروس را از زر خالص میکردند.<br /></font></div>'),
(175171, 'طاقک', '<span class=\"hlight\">طاقک .</span> <font color=\"DarkGreen\"><b>[ ق َ ]</font></b> (اِ) نوعی درخت . رجوع به طاخک شود.<br /></font></div>'),
(175172, 'طاقگاه', '<span class=\"hlight\">طاقگاه .</span> (اِ مرکب ) محل طاق . آنجا که طاق شروع میشود.<br /></font></div>'),
(175173, 'طاقی', '<span class=\"hlight\">طاقی .</span> (ص نسبی ) منسوب به طاق . رجوع به طاق شود. <BR><font color=\"Blue\">◄</font> (اِ) نوعی از کلاه باشد. (برهان ) (غیاث اللغات ). کلاه که به صورت طاق سازند. طاقین . طاقیه <span class=\"hlight\">:</span> <br />نامد درست طاقی گردون بفرق فقر<br />کشکول تا مگر بسرش باژگون کنند.<br /><font color=\"Red\">ارادتخان واضح (از آنندراج ).</font><br /></font></div>'),
(175174, 'طاقی', '<span class=\"hlight\">طاقی .</span> (اِخ ) یکی از ممالک هند. (اخبارالصین والهند ص <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(175175, 'طاقین', '<span class=\"hlight\">طاقین .</span> (اِ) قبای دوتائی . (دیوان البسه ٔ نظام قاری ) <span class=\"hlight\">:</span> <br />اینکه در دکانها آورده اند<br />صوف طاقین مربع بیشمار.<br /> <font color=\"Red\">نظام قاری (دیوان البسه ).</font><br />تنم تا یافت در بر صوف طاقین <br />سر چتر و دل خارا ندارد.<br /> <font color=\"Red\">نظام قاری (دیوان البسه ).</font><br />قدِ صوف زاغکی بین بر صوف سبز طاقین <br />سر همسری طوطی عجب اینکه زاغ دارد.<br /><font color=\"Red\">نظام قاری (دیوان البسه ).</font><br />نظامی صوف طاقین است و سعدی جامه ٔ دیبا.<br />مرقع را شمر قاری و شرب زرفشان سلمان .<br /> <font color=\"Red\">نظام قاری (دیوان البسه ).</font><br /> <BR><font color=\"Blue\">◄</font> طاقی . نوعی از کلاه . طاقیه <span class=\"hlight\">:</span> <br />ور در خور اقبال تو خدمت کندی چرخ <br />هستی سر او را سم اسبان تو طاقین .<br /><font color=\"Red\">معزی .</font><br /></font></div>'),
(175176, 'طاقیه', '<span class=\"hlight\">طاقیه .</span> <font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (اِ) نوعی کلاه بلند مخروط شبیه بکلاه فعلی درویشان . قسمی از کلاه : طاقیه ٔ ترکمانی ؛ کلاه نظامیان عثمانی . عرقچین . <BR><font color=\"Blue\">◄</font> بافته ٔ سرخ . ج، طاقیات <span class=\"hlight\">:</span> گویند هر که از پوست شیر طاقیه ساخته در سر طفلی نهد که صرع داشته باشد، نفع رساند. (ریاض الادویه ). الب ارسلان هیئتی در غایت مهابت و محاسنی کشیده داشت و طاقیه ٔ طولانی برسر میگذاشت چنانچه بیننده از بدایت طاقیه تا نهایت لحیه ٔ او دو گره میپنداشت . (حبیب السیر چ <span class=\"hlight\" dir=\"rtl\">١</span> تهران جزو <span class=\"hlight\" dir=\"rtl\">٤</span> از ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧١</span>). چشمش بعینه، از دو چشمک که در طاقیه ٔ اطفال جهت چشم زخم دوزند. (نظام قاری ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br />بترگ طاقیه گفتم که برگ گل ماند<br />خیال گفت نگفتی سخن به اندازه .<br /> <font color=\"Red\">نظام قاری (دیوان البسه ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span>).</font><br />صد عرقچین فدای طاقیه باد<br />هیچ از قالبش نیاید یاد.<br /> <font color=\"Red\">نظام قاری (دیوان البسه ص <span class=\"hlight\" dir=\"rtl\">٥٥</span>).</font><br />قلمی فوطه و کرباس و ندافی و قدک <br />یقلق وطاقیه و موزه و کفش و دستار.<br /> <font color=\"Red\">نظام قاری (دیوان البسه ص <span class=\"hlight\" dir=\"rtl\">١٥</span>).</font><br />بر سر بجای طاقیه ام هست کله پوش <br />تخفیفه راجنیبه و دستار میکنم .<br /> <font color=\"Red\">نظام قاری (دیوان البسه ص <span class=\"hlight\" dir=\"rtl\">٢٥</span>).</font><br />ترگها باید که تا یابد اصولی طاقیه <br />ورنه بتوان آستینی از نمد برساخت تاج .<br /><font color=\"Red\">نظام قاری (دیوان البسه ص <span class=\"hlight\" dir=\"rtl\">٥٤</span>).</font><br /></font></div>'),
(175177, 'طاقیه دوز', '<span class=\"hlight\">طاقیه دوز.</span> <font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (نف مرکب ) کسی که طاقیه کند. آنکه طاقیه سازد. رجوع به طاقیه شود <span class=\"hlight\">:</span> <br />من که چون قالب بی جان شدم از سوز جگر<br />هست سودای مه طاقیه دوزم بر سر.<br /><font color=\"Red\">سیفی .</font><br /></font></div>'),
(175178, 'طال', '<span class=\"hlight\">طال .</span> <font color=\"DarkGreen\"><b>[ لِن ْ ]</font></b> (ع ص ) منهل ٌ طال ؛ چشمه ٔ چغزلاوه برآورده . <BR><font color=\"Blue\">◄</font> لیل ٌ طال ؛ شب تاریک . (منتهی الارب ).<br /></font></div>'),
(175179, 'طال بقا', '<span class=\"hlight\">طال بقا.</span> <font color=\"DarkGreen\"><b>[ ل َ ب َ ]</font></b> (از ع، جمله ٔ فعلیه ٔ دعایی، اِ مرکب ) جمله ٔ دعائی مأخوذ از جمله ٔ عربی «طال بقائه ». یعنی زندگانی او دراز باد یا جاودان باد. و فارسی زبانان هاء ضمیر آن را حذف کنند و طال بقا گویند و آن را در درود گفتن و آفرین خواندن و ثناگوئی به کار برند <span class=\"hlight\">:</span> و در ضیافت دولت طفیلیان مملکت را مرحبائی و طال بقائی شنوانیده آید. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>).<br />تا نیاید وحی ز او غرّه مباش <br />تو بدان گلگونه ٔطال بقاش .<br /> <font color=\"Red\">مولوی .</font><br />ثنا و طال بقا هیچ فایده نکند<br />که در مواجهه گویند راکب و راجل .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(175180, 'طال بقا زدن', '<span class=\"hlight\">طال بقا زدن .</span> <font color=\"DarkGreen\"><b>[ ل َ ب َ زَ دَ ]</font></b> (مص مرکب ) آفرین و درود گفتن . ثنا خواندن <span class=\"hlight\">:</span> چون عشق را مرحبا زدی حوادث را طال بقا باید زد. (سند بادنامه ص <span class=\"hlight\" dir=\"rtl\">١٤٠</span>).<br />ور غلام هندوئی آرد وفا<br />دولت او میزند طال بقا.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(175181, 'طالار', '<span class=\"hlight\">طالار.</span> (اِ) تالار. اطاق بزرگ مستطیلی که غالباً در منازل برای پذیرائی اختصاص داده میشود. سالن . رجوع به تالار شود.<br /></font></div>'),
(175182, 'طالار اشرف', '<span class=\"hlight\">طالار اشرف .</span> <font color=\"DarkGreen\"><b>[ رِ اَ رَ ]</font></b> (اِخ ) در اصفهان واقع است، و از جمله ٔ ابنیه ٔ تاریخی ایران میباشد.<br /></font></div>'),
(175183, 'طالان دبسنگ', '<span class=\"hlight\">طالان دبسنگ .</span> <font color=\"DarkGreen\"><b>[ ن ِ دَ س َ ]</font></b> (اِخ ) این کلمه تحریفی است از اصل مغول، دبسنگ را به معنی کوه گرفته اند، ولی در حقیقت مرتفعترین قله ٔ جبال قراقوروم است که ارتفاع آن به <span class=\"hlight\" dir=\"rtl\">٨٥٦٨</span> گز میرسد. (جامع التواریخ چ بلوشه صص <span class=\"hlight\" dir=\"rtl\">٢٦</span> - <span class=\"hlight\" dir=\"rtl\">٢٥</span>).<br /></font></div>'),
(175184, 'طالانیون', '<span class=\"hlight\">طالانیون .</span> (اِ) بعضی آن را ابرون برّی و بعضی رجل الریه نامند. نباتی است ساق آن شبیه بساق رجله، و برگ آن نیز شبیه ببرگ آن، و نزدیک برگی از برگهای آن شاخه ای میروید منشعب به شش شعبه، یا هفت شعبه، همه مملو از برگهای ریزه، و چون برگهای آن ریخته شود، رطوبت لزجی از آن ظاهر میگردد، و گل آن سفید است، و منبت آن زیر درخت انگور. (فهرست مخزن الادویه ).<br /></font></div>'),
(175185, 'طالب', '<span class=\"hlight\">طالب .</span> <font color=\"DarkGreen\"><b>[ ل ِ]</font></b> (اِخ ) ابن عثمان بن محمد، ابواحمدبن ابی غالب الازدی النحوی البصری . وی از ابوبکربن الانباری نحو فراگرفت، و در فنون عربیت بارع، و عارف به لغت بود، در پایان زندگانی نابینا شد. ولادت وی در <span class=\"hlight\" dir=\"rtl\">٣١٩</span> و در <span class=\"hlight\" dir=\"rtl\">٣٩٦</span> هَ . ق . در روزگار خلافت القادر باللّه درگذشت .(معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>). رجوع به عنوان قبل شود.<br /></font></div>'),
(175186, 'طالب', '<span class=\"hlight\">طالب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ابن محمدبن قشیط، ابواحمد، المعروف به ابن السراج النحوی . وی واقف به علوم عربیت بود، و چیره بر آن . نحو را از ابوبکربن الانباری آموخت . او راست : مختصری در نحو، و کتاب عیون الاخبارو فنون الاشعار، در <span class=\"hlight\" dir=\"rtl\">٤٠١</span> هَ . ق . وفات کرد. (معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>) (روضات ص <span class=\"hlight\" dir=\"rtl\">١٦١</span> بدون ذکر تاریخ وفات ).<br /></font></div>'),
(175187, 'طالب', '<span class=\"hlight\">طالب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ابن علی ابهری علوی حسینی .شیخ منتجب الدین قمی در فهرست خود گوید وی فقیه صالح واعظ بود و نزد شیخ جلیل محیی الدین بن الحسین بن المظفر الحمدانی حدیث آموخت، صاحب امل الاَّمل در حق او گوید: عالم و فاضل محقق و عابد و مردی صالح و ادیب و شاعر بوده . او راست : رسائل و مراثی الحسین علیه السلام . دیوانی نیز دارد، و از معاصرین است . (روضات ص <span class=\"hlight\" dir=\"rtl\">٣٣٥</span>).<br /></font></div>'),
(175188, 'طالب', '<span class=\"hlight\">طالب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ابن عثمان الازدی النحوی المقری ٔ المؤدب، المکنی به ابی احمد البغدادی . در روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>، نام و نسب و کنیت وی بشرح مسطور در بالا آمده بدون هیچ توضیح یا ترجمه .<br /></font></div>'),
(175189, 'طالب', '<span class=\"hlight\">طالب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) دهی است از دهستان چهاراویماق بخش قره آغاج شهرستان مراغه در <span class=\"hlight\" dir=\"rtl\">٢٤/٥</span>هزارگزی جنوب قره آغاج و <span class=\"hlight\" dir=\"rtl\">٤٧</span>هزارگزی جنوب شوسه ٔ مراغه به میانه .کوهستانی و معتدل و مالاریائی است . با <span class=\"hlight\" dir=\"rtl\">٥٩</span> تن سکنه . آب آن از رودخانه ٔ قراقلعه . محصول آن غلات و نخود و بزرک . شغل اهالی آن زراعت صنایع دستی و جاجیم بافی . راه آنجا مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(175190, 'طالب', '<span class=\"hlight\">طالب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) رودی است در جنوب خوزستان معروف به رود طالب .<br /></font></div>'),
(175191, 'طالب', '<span class=\"hlight\">طالب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) جوینده . جویا. جویان . خواهنده . خواهان . خواستار. خواستگار. خواهشمند. طلبکار. (منتهی الارب ). طلوب . مُلتمس . ج، طالبون، طالبین، طُلاّب، طلب، طلبه و طُلَّب <span class=\"hlight\">:</span> <br />من طالب خنج وتو شب و روز<br />اندر پی کشتنم چرائی .<br /> <font color=\"Red\">عنصری .</font><br />طالب و صابرو بر سرّ دل امین . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٨٩</span>).<br />تو هم معشوق و هم عاشق تو هم مطلوب و هم طالب <br />توهم منظور و هم ناظر تو هم شاهی و هم دربان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />هنرجو ز آنکه در عقل او نکوتر<br />که باشی در زمانه طالب زر.<br /><font color=\"Red\">ناصرخسرو.</font><br />و اول شرطی طالبان این کتاب را حسن قرائت است . (کلیله و دمنه ). آن سه که طالبند (دنیاجویان ) فراخی معیشت ... (کلیله و دمنه ).<br />طالب آن است که از شیر نگرداند روی <br />تا نباید که بشمشیر بگردد رایت .<br /> <font color=\"Red\">سعدی .</font><br />عنفوان شبابم غالب شدی و هوی و هوس طالب . (گلستان ). و در زبان فارسی با مصادر شدن و کردن فعل مرکب بسازد چنانکه گویند طالب شد یعنی خواهنده و خواستار شد. و طالب کردن، کسی را خواهان چیزی کردن واو را برانگیختن تا راغب چیزی شود <span class=\"hlight\">:</span> <br />قاصدی بفرست کاخبارش کنند<br />طالب این فضل و ایثارش کنند.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> ناشد. (المنجد). <BR><font color=\"Blue\">◄</font> طالب خیر و نیکوئی . مستمطر. <BR><font color=\"Blue\">◄</font> طالب معروف و احسان . عافی . (منتهی الارب ).<br /></font></div>'),
(175192, 'طالب آباد', '<span class=\"hlight\">طالب آباد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) محلی است فعلاً ایستگاه شماره ٔ <span class=\"hlight\" dir=\"rtl\">٣٢</span> راه آهن شمال، با نام بهرام، اما پیشتر طالب آباد خوانده میشد. بواسطه ٔ نزدیکی به تپه ها و خرابه هائی منسوب به بهرام گور، از طرف فرهنگستان بدین نام (بهرام ) نامیده شد. فاصله اش تا تهران، <span class=\"hlight\" dir=\"rtl\">٢٦٥٠٠</span> گز است .<br /></font></div>'),
(175193, 'طالب آباد', '<span class=\"hlight\">طالب آباد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) نام محلی است کنار راه رشت و بندرانزلی میان حسن رود و شالور. در <span class=\"hlight\" dir=\"rtl\">٣٦٩٠٠٠</span> گزی تهران .<br /></font></div>'),
(175194, 'طالب آباد', '<span class=\"hlight\">طالب آباد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) دهی است در دو فرسخ و نیمی میانه ٔ جنوب و مغرب سروستان فارس . (فارسنامه ٔ ناصری ).<br /></font></div>'),
(175195, 'طالب آباد', '<span class=\"hlight\">طالب آباد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b>(اِخ ) دهی است جزء دهستان چهار فریضه بخش مرکزی شهرستان بندر انزلی در <span class=\"hlight\" dir=\"rtl\">٧</span>هزارگزی خاوری غازیان کنار راه شوسه انزلی به رشت . جلگه و کنار مرداب . معتدل و مرطوب و مالاریائی . با <span class=\"hlight\" dir=\"rtl\">١٢٦</span> تن سکنه آب آن از حسن رود و سفیدرود. محصول آنجا برنج و ابریشم . شغل اهالی زراعت و راه آن شوسه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(175196, 'طالب آباد', '<span class=\"hlight\">طالب آباد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) دهی است از دهستان حسین آباد بخش شوش شهرستان دزفول . در <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی خاوری شوش و یکهزارگزی جنوب خاوری شوسه ٔ اهواز به دزفول . دشت و گرمسیر و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> تن سکنه . آب آن از رودخانه ٔ کرخه . محصول آنجا غلات و برنج و کنجد. شغل اهالی زراعت . راه آن در تابستان اتومبیل رو. ساکنین از طایفه ٔ عرب هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(175197, 'طالب آباد', '<span class=\"hlight\">طالب آباد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) دهی است از دهستان ناتل رستاق بخش نور شهرستان آمل . در <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی جنوب خاوری سولده . دشت و معتدل و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٥٥</span> تن سکنه (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175198, 'طالب آباد', '<span class=\"hlight\">طالب آباد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b>(اِخ ) دهی است جزء بخش سنگسر شهرستان سمنان در یکهزارگزی جنوب سنگسر کنار شوسه ٔ سمنان به سنگسر. کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و میوه جات و لبنیات . شغل اهالی زراعت و گله داری . گله دارها تابستان به ییلاقات فیروزکوه رفته پائیز مراجعت میکنند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175199, 'طالب آباد', '<span class=\"hlight\">طالب آباد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) دهی است از دهستان احمدآباد بخش فریمان شهرستان مشهد در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی شمال باختری فریمان . جلگه و گرمسیر با <span class=\"hlight\" dir=\"rtl\">٤٦</span> تن سکنه آب آن از قنات . محصول آنجا غلات و تریاک و چغندر. شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175200, 'طالب آملی', '<span class=\"hlight\">طالب آملی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب ِ م ُ ]</font></b> (اِخ ) از شاعران قرن یازدهم که در <span class=\"hlight\" dir=\"rtl\">١٠٣٦</span> هَ . ق . درگذشته است . صاحب «آتشکده » آرد: از شعرای آمل است و مدتی در هندوستان در خدمت شاه سلیم از معتبرین بوده . صاحب دیوان است و در شاعری طرز خاص که مطلوب شعرای فصیح نیست دارد. بعد از مطالعه ٔ دیوان او این چند بیت انتخاب و ثبت گردید:<br />هستند فی المثل گله ٔ گوسفند خلق <br />کاو را خدای صاحب و راعی شبان بود.<br />چمن کبکیست خندان گل دهان و غنچه منقارش <br />پریشان سایه های سرو و دامنهای کهسارش .<br />ز اشک شام و سحر دیده چند تر ماند<br />دعا کنیم که نه شام و نه سحر ماند... (آتشکده ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>) و این ابیات نیز از اوست :<br />هر سنگ که بر سینه زدم نقش تو بگرفت <br />آنهم صنمی بهر پرستیدن من شد.<br />آسوده لبی که ساغر غم نکشید<br />خوشدل زخمی که ناز مرهم نکشید<br />من بلبل آن گلم که در گلشن دهر<br />پژمرده شد و منت شبنم نکشید.<br />این شاعر را مثنویی است به بحر خسرو و شیرین نامش قضا و قدر و به سبک مثنوی پیر و جوان میرزا نصیر، در دیوان خطی او قصیده ای در مدح شهر لاهور هند دیده شدکه اقامت او را در هند تأیید میکند. ادوارد براون، از ریو نقل کرده گوید: طالب صاحب سبک شعری خاص است که پس از وی فصحاء از پیروی آن احتراز جسته اند، در اوایل عمر به هندوستان رفت، و احترامش بجائی رسید که جهانگیر وی را ملک الشعراء خویش گردانید (<span class=\"hlight\" dir=\"rtl\">١٠٢٨</span> هَ . ق .) بهیچوجه خفض جناح نمیکرد، و مدعی بود که قبل از بیست سالگی هفت علم را بخوبی آموخته است . (کمالات ادعائی طالب ).<br />پا بر دومین پایه ٔ اوج عشراتم <br />وینک عدد فنم از آلاف زیاد است <br />بر هندسه و منطقی و حکمت و هیئت <br />دستی است مرا کش ید بیضا زعباد است <br />وین جمله چو طی شد نمکین علم حقیقت <br />کاسناد علوم است بر این جمله مراد است <br />در سلسله ٔ وصف خط این بس که ز کلکم <br />هر نقطه سویدای دل اهل سواد است <br />پوشم نسب شعر چو دانم که تو دانی <br />کاین پایه مرا ثامن این سبع شداد است <br />آن گلبنم القصه که از هر گل شاداب <br />عطر دگرم در شکن طره ٔ باد است .<br />در رباعی ذیل که شبلی نعمانی در شعرالعجم نقل کرده (ص <span class=\"hlight\" dir=\"rtl\">١٦٨</span> به زبان اردو) بقصد سفر خود به جانب هندوستان اشاره کرده و بخت سیاه خود را در ایران گذارده است زیرا که هندو به هندوستان تحفه بردن کار خردمندان نیست <span class=\"hlight\">:</span> <br />طالب گل این چمن ببستان بگذار<br />بگذار که میشوی پریشان بگذار<br />هندو نبرد تحفه کسی جانب هند<br />بخت سیه خویش به ایران بگذار.<br />محبت طالب به خواهر خود: خواهری داشت از خود بزرگتر که صمیمانه به او علاقمند بود، بعد از هجران مدید، خواهرش از ایران به آگره آمد، تا از وی دیدار کند، وبه همین جهت طالب از پادشاه جهانگیر بوسیله ٔ ابیات ذیل استجازه کرد:<br />صاحبا ذرّه پرورا عرضی <br />به زبان سخن در است مرا<br />پیر همشیره ای است غمخوارم <br />که به او مهر مادر است مرا<br />چارده سال بلکه بیش گذشت <br />کز نظر دور منظر است مرا<br />دور گشتم ز خدمتش بعراق <br />وین گنه جرم منکر است مرا<br />او نیاورد تاب دوری من <br />که به مادر برابر است مرا<br />آمد اینک با اَگره وز شوقش <br />دل تپان چون کبوتر است مرا<br />میکند دل بسوی او آهنگ <br />چه کنم شوق رهبر است مرا<br />گر شود رخصت زیارت او<br />بجهانی برابر است مرا<br />اشعار عاشقانه در فارسی بسیار است اماچون ابیاتی که از محبت عمیق و صمیمی خانواده ای کسی حکایت کند نسبةً قلیل است، این اشعار بنظر مهم و قابل ذکر آمد. (ترجمه ٔ تاریخ ادبیات ادوارد براون ترجمه ٔ رشید یاسمی صص <span class=\"hlight\" dir=\"rtl\">١٦٩</span> - <span class=\"hlight\" dir=\"rtl\">١٧٠</span>). صائب تبریزی درباره ٔ اوگوید:<br />در سخن از عرفی و طالب ندارد کوتهی عیب <br />صائب این بود کز زمزه ٔ اسلاف نیست .<br />طالب آمل گذشت و طبعها افسرده شد<br />از چه رو آن آتشین گفتار در عالم نماند.<br />و رجوع به تاریخ ادبیات ادوارد براون صص <span class=\"hlight\" dir=\"rtl\">١٣٢</span> - <span class=\"hlight\" dir=\"rtl\">١٦٧</span> و سبک شناسی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٦</span> و فهرست کتابخانه ٔ سپهسالار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢٨</span> و تاریخ عصر حافظ ج <span class=\"hlight\" dir=\"rtl\">١</span> ص یج شود.<br /></font></div>'),
(175201, 'طالب الحق', '<span class=\"hlight\">طالب الحق .</span> <font color=\"DarkGreen\"><b>[ ل ِ بُل ْ ح َق ق ]</font></b> (اِخ ) عبداﷲبن یحیی الحضرمی ملقب به طالب الحق . یکی از ائمه ٔ فرقه ٔ اباضیه از مردم یمن است که از فرمانبری مروان بن محمد سرپیچی کرد و مردم با او بیعت خلافت بستند و کار او بالا گرفت، و ابوحمزه از وی پیروی کرد. آنگاه مروان به کار ایشان درنگریست و سپاهی به فرماندهی عبدالملک بن محمد السعدی بسوی آنان گسیل کرد. عبدالملک با ابوحمزة در وادی القری (از اعمال مدینة) روبرو شد و وی را بقتل رسانید وهمچنان با سپاهیان خود بسوی یمن شتافت . طالب الحق برای دفاع با همراهان خویش بجانب او رفت و در نزدیکی صنعاء با یکدیگر تلاقی کردند و به پیکار پرداختند و سرانجام طالب الحق کشته شد و عبدالملک سر او را به شام نزد مروان برد. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٩٠</span>). و ابن اثیر ذیل عنوان «یاد کردن خبر ابوحمزة خارجی با طالب الحق »آرد: نام ابوحمزة خارجی مختاربن عوف ازدی سلمی بصری است . وی در آغاز کار یکی از افراد خوارج اباضیة بودکه همه ساله حج میگزارد و در مکه مردم را بر خلاف مروان بن محمد برمی انگیخت و این روش را ادامه میداد تا در پایان سال <span class=\"hlight\" dir=\"rtl\">١٢٨</span> هَ . ق . عبداﷲبن یحیی معروف به طالب الحق را در مکه ملاقات کرد و به وی گفت : «ای مرد سخنی نیک از من بشنو ترا مردی می بینم که مردم را به راه حق و راستی دعوت میکنی . با من همراه شو. چه من کسی هستم که در میان عشیره ٔ خویش مطاع میباشم .» طالب الحق پذیرفت و از مکه بیرون رفتند و چون به حضرموت رسیدندابوحمزة در آنجا با طالب الحق بیعت بست و او را نامزد خلافت کرد و به دعوت خویش به ضدیت مروان و خاندان او همچنان ادامه میداد تا روزی ابوحمزه از معدن بنی سلیم میگذشت کثیربن عبداﷲ که عامل آن ناحیه بود سخنان ابوحمزة را شنیده بود، ازاین رو او را چهل تازیانه زد. و چون ابوحمزة مدینة را فتح کرد و بر آن استیلا یافت کثیربن عبداﷲ خود را پنهان ساخت و متواری شد. (کامل ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>) وهم ابن اثیر در صفحه ٔ <span class=\"hlight\" dir=\"rtl\">١٧٧</span> همان جلد آرد: در این سال ابوحمزة بلج بن عقبة ازدی خارجی از جانب عبداﷲبن یحیی الحضرمی طالب الحق به حج آمد و آهنگ آن داشت که نخست با مروان بن محمد بستیزد از این رو هنگامی که مردم در عرفه بودند یکباره دیدند گروهی در حدود هفتصد تن علمها و دستارها را بر سر نیزه ها کرده پیش می آیند. مردم در بیم و هراس شدند و از کیفیت حال آنان پرسیدند. گفتند ما بستیز با مروان و خاندان او برخاسته ایم . آنگاه عبدالواحدبن سلیمان بن عبدالملک که در آن هنگام فرمانروای مکه و مدینه بود کسی را نزد آنان گسیل کرد که ایشان را به آرامش بخواند. گفتند ما در هنگام حج گزاری دست از ستیز برمیداریم و آنگاه به مخالفت خویش ادامه میدهیم و قول دادند که تا هنگامی که آخرین تن از حُجاج در مکه باشد، آرامش را حفظ کنند و همین که آخرین کس از حج گزارندگان از مکه بیرون رفت آنان در عرفه توقف کردند و مردم عبدالواحد را از مکه راندند و او در منی در منزل سلطان فرود آمد و ابوحمزة به قرن الثعالب رفت . سپس عبدالواحد عبداﷲبن حسن بن حسن بن علی و محمدبن عبداﷲبن عمروبن عثمان و عبد الرحمن بن قاسم بن محمدبن ابی بکر و عبیداﷲبن عمربن حفص بن عاصم بن عمربن خطاب و ربیعةبن ابی عبدالرحمن را با گروهی ازرجالی که همشأن آنان بودند بسوی ابوحمزة خارجی گسیل کرد و آنان بر ابوحمزة وارد شدند در حالی که جامه ٔپنبه ای خشنی بر تن داشت . آنگاه عبداﷲبن حسن و محمدبن عبداﷲ مقدم بر همه با وی به سخن پرداختند و او از نسب آنان پرسید ایشان نسب خود را بازگفتند. ابوحمزه روی در هم کشید و نسبت به آنان کراهت خویش را آشکار کرد. سپس عبدالرحمن بن قاسم و عبیداﷲبن عمر پیش رفتندو نسب خود را به وی بازگفتند ابوحمزة ابراز شادمانی کرد و با تبسم به آنان نگریست و گفت : به خدای سوگندما خروج نکردیم جز اینکه روش و سیرت پدران شما را پیروی کنیم . عبداﷲبن حسن گفت : ما نزد تو نیامده ایم که به پدران خویش تفاخر کنیم و آنان را بر یکدیگر برتری دهیم بلکه امیر ما را برسالت نزد تو فرستاده است وهم اکنون ربیعة بتو خبر میدهد و چون ربیعة نقض عهد او را بازگفت ابوحمزه پاسخ داد پناه بخدا که عهد خویش را نقض کرده یا در هم شکسته باشم نه بخدا اگر گردنم را بزنند چنین کاری نمیکنم ولی بدان که میان ما و شما آرامش و اطمینان از میان رفته است . آنها نزد عبدالواحد بازگشتند و سخنان ابوحمزة را به وی خبر دادندو نخستین کسی که مکة را تخلیه کرد عبدالواحد بود ازاین رو ابوحمزة بی پیکار بدان شهر درآمد و آن را متصرف شد. برخی از شاعران درباره ٔ عبدالواحد گفته اند:<br />زار الحجیج عصابة قد خالفوا<br />دین الاله ففر عبدالواحد<br />ترک الحلائل و الامارة هاربا<br />و مضی یخبط کالبعیر الشارد.<br />و هم مؤلف مزبور زیر عنوان «ذکر قتل عبداﷲبن یحیی » ذیل حوادث سال <span class=\"hlight\" dir=\"rtl\">١٣٠</span> هَ . ق . گوید: ابن عطیة آهنگ یمن کرد و عبداﷲبن یحیی طالب الحق که در صنعاء اقامت داشت از آمدن وی آگاه شد از این رو با همراهان خویش بسوی او شتافت و با وی بکارزار پرداخت ولی ابن یحیی کشته شد و ابن عطیة سر او را نزد مروان بشام فرستاد و خود بسوی یمن رفت . (کامل ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٦</span>) و مؤلف مجمل التواریخ آرد: پس به یمن عبداﷲبن یحیی بن زید الحسینی بیرون آمد، و از ابومسلم خود خبر نداشت همین سال <span class=\"hlight\" dir=\"rtl\">١٢٨</span> هَ . ق . و اتفاق را همچنان کسوت سیاه ساختند، و خود را طالب الحق نام نهاد، و ابوحمزه نامی ازیمن به کار علوی برخاست، و مکه و مدینه بگرفت، و ازانصار و قریش بسیاری بکشت، و فریاد برخاست و مکه و مدینه مسخر کرد. و فریاد بمروان رسید که سیاه جامگان، مشرق و مغرب بگرفتند، و مروان بن عطیة را بحرب حمزة فرستاد تا وی را بکشت . (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>). خواندمیر گوید: و هم در این سال ابوحمزة، و عبداﷲبن یحیی که ملقب به طالب الحق بود، بی آنکه کسی ایشان را از حال شعار ابومسلم اخبار دهد، در یَمن دستارهای سیاه بر سر بسته و جامه های سیاه پوشیده، اَلویه سودا برافراشتند و مخالفت مروان حمار ظاهر ساختند، و بلده ٔ صنعا را به تحت تصرف درآورده طالب الحق آنجا توقف کرد، و ابوحمزة متوجه ٔ مکه شد، و در موسم حج ناگاه با جمعی سیاه پوش در حرم ریخته، حاجیان و مقیمان آن منزل متبرک به غایت متوهم گشتند، و پرسیدند که چه کسانید، جواب دادند که ما مخالفان بنی امیه و دشمنان مروانیم . عبدالواحدبن سلیمان بن عبدالملک که در آن زمان از قبل مروان حاکم مکه بود، از ابوحمزة التماس نمود که چندان مزاحم مردم نشود که از مناسک حج ّ اسلام فارغ گردند. ابوحمزة این ملتمس را مبذول داشته، بعد از انقضاء ایام حج، عبدالواحد به مدینة گریخت، و ابوحمزةبمکه درآمد، و عبدالواحد در یثرب لشکری از اطراف و جوانب فراهم آورده، متوجه حریم حَرَم گشت . ابوحمزة بر جُرأت او اطلاع یافته از مکه بیرون خرامید و در منزل قَدید قتالی شدید واقع شد. از لشکر عبدالواحد هفتصد مرد بقتل رسید، و او گریخته بمدینه رفت، آنجا نیزمجال توقف نیافته بشام شتافت . ابوحمزة حرمین را در حیز تسخیر درآورده مدّت سه ماه به تمهید بساط نصفت واحسان مردم را شادمان ساخت، و چون عبدالواحد نزد مروان رسید، کیفیت حادثه را معروض گردانید. مروان عبدالملک بن محمدبن عطیة السعدی را با چهار هزار کس جهت دفع خوارج بجانب حجاز ارسال داشت . و ابوحمزة از مدینه به استقبال آن سپاه روان شده در وادی القری تلاقی فریقین اتفاق افتاد و ابوحمزة با اکثر متابعان بزخم تیغ شامیان از پای درآمده، معدودی چند بمدینه گریختند، و مدینیان خون ایشان را بر خاک ریختند، و ابن عطیة بعد از فراغ از مُهم حجاز بصوب یمن شتافته، میان او و طالب الحق محاربه ای واقع شد، و بار دیگر بعنایت واهب العطایا، ابن عطیة ظفر یافت . طالب الحق به قتل آمد و ابن عطیة سرش را بشام فرستاد و روزی چند در صنعا لوای اقامت برافراخت و چون موسم حج نزدیک رسید با دوازده نفر و چهل هزار دینار زر جهت امارت حج بنا بر فرموده ٔ مروان متوجه کعبه شد و در اثنای راه، طائفه ای از بنی مراد بدیشان رسیده همه را گرفتند که شما دزدانید. هر چند ابن عطیه گفت که من بحکم مروان، امیر حاجیانم، و بطرف مکه ٔ مبارکه میروم و اینک منشور امارت به دست دارم، بجائی نرسید. و او را با تمامی غلامان به قتل رسانیدند. در بعضی از نسخ معتبره مسطور است که مذهب ابوحمزه و طالب الحق آن بود که عباد بمجرد ارتکاب زنا و سرقت کافر میشوند. و هر که زانی و سارق را کافر نمیداند، او نیز در سلک کفار انتظام دارد. (حبیب السیر چ <span class=\"hlight\" dir=\"rtl\">١</span> تهران ص <span class=\"hlight\" dir=\"rtl\">٢٦٧</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(175202, 'طالب بن الازهر', '<span class=\"hlight\">طالب بن الازهر.</span> <font color=\"DarkGreen\"><b>[ ل ِ بِب ْ نِل ْ اَ هََ ]</font></b> (اِخ ) مملوک . و شاعری قلیل الشعر است . (ابن الندیم ).<br /></font></div>'),
(175203, 'طالب بن بشیر', '<span class=\"hlight\">طالب بن بشیر.</span> <font color=\"DarkGreen\"><b>[ ل ِ بِب ْ ن ِ ب َ ]</font></b> (اِخ ) محدثی است . عسقلانی گوید: مدنی و مجهول است . (لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span>).<br /></font></div>'),
(175204, 'طالب بن سمیدع', '<span class=\"hlight\">طالب بن سمیدع .</span> <font color=\"DarkGreen\"><b>[ ل ِ بِب ْ ن ِ س َ م َ دَ ]</font></b> (اِخ ) ازدی گوید درباره ٔ او تأمل باید کرد - انتهی . ابن ابی حاتم بروایت از ابولبید گوید جمادبن زیداز او روایت کرده است . (لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span>).<br /></font></div>'),
(175205, 'طالب بن عبدا', '<span class=\"hlight\">طالب بن عبدا.</span> <font color=\"DarkGreen\"><b>[ ل ِ بِب ْ ن ِ ع َ دُل ْ لاه ]</font></b> (اِخ ) ازدی گوید: حدیث او قابل اعتماد نیست آنگاه سلسله ٔ حدیث او را از طریق ابوکریب بدین سان روایت کرده است : موسی بن طالب بن عبداﷲ ما را خبر داد (وی گفت ) پدرم از عطا و او از میسرة واو درباره ٔ علی رضی اﷲ عنه روایت کرد که وی بمسکنی فرود آمد و نبیذ خواست و در کوزه ای نبیذ بیاشامید، واصحاب خود را نیز سقایت کرد. آنگاه مردی را که مست کرده بود فروگرفت تا حد بزند. آن مرد گفت : ای امیرالمؤمنین مرا بر شرابی که خود نوشانیده ای میزنی ؟ گفت :ترا بر شراب حد نمیزنم بلکه بخاطر آنکه مست شده ای ترا شایسته ٔ حد زدن میدانم . مؤلف گوید: این گفتار باطل است و از نوع تکلیف مالایطاق میباشد - انتهی . و این روایت لازم نیست چه همین حدیث را ابوجعفر طحاوی در کتاب اشربه از طریق دیگری درباره ٔ عمربن خطاب (رض ) روایت کرده است . و بخط حسینی دیدم که ازدی گفته است طالب بن عبداﷲ مجهول است . (لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span>).<br /></font></div>'),
(175206, 'طالب بگی', '<span class=\"hlight\">طالب بگی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب َ]</font></b> (اِخ ) دهی است از دهستان حومه بخش سروستان شهرستان شیراز. در ده هزارگزی جنوب باختری سروستان و هشت هزارگزی راه فرعی کوهنجان به خضر. جلگه و معتدل و مالاریائی است با <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و تنباکو و صیفی . شغل اهالی زراعت و قالی بافی . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(175207, 'طالب جاجرمی', '<span class=\"hlight\">طالب جاجرمی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب ِ ج َ ]</font></b> (اِخ ) مؤلف تذکره ٔ دولتشاه آرد: غزل را نیکو میگوید از کدخدازادگان جاجرم بوده و شاگرد شیخ آذری است، در اول حال سفر اختیار کرده . در دارالملک شیراز اقامت ساخت و آنجا قبول تمام یافت . اشعار او در فارس شهرت کُلی گرفته، در جواب شیخ سعدی اشعار دارد. غزل شیخ را که مطلعش این است :<br />دیده از دیدار خوبان برگرفتن مشکل است <br />هر که ما را این نصیحت میکند بی حاصل است <br />طالب در جواب آن تتبع کرده :<br />ای که بی روی تو ما را زندگانی مشکل است <br />تلخی داغ فراغت همچو زهر قاتل است <br />حاصل عمرم تو بودی ای نگار لاله رخ <br />تا تو رفتی از بَرِ من عُمر من بیحاصل است <br />در غمت بگریستم چندانکه آب از سرگذشت <br />از پیت زآن رو نمی آیم که پایم در گل است <br />ای نسیم صبحگاهی با من بیدل بگوی <br />کاین زمان آرام جانم در کدامین منزل است <br />ای همای دولت از ما سایه ٔ خود برمگیر<br />نیر اقبال تو بر هر که تابد مُقبل است <br />ما ز آب دیده ٔ خود غرقه ٔ بحر غمیم <br />از غریق آن کس چه داند کو به روی ساحل است <br />یار رفت و با من طالب حدیثی هم نگفت <br />وه که تا روز قیامت این ز یارم بر دل است .<br />طالب در مناظره ٔ گوی و چوگان در شیراز بنام سلطان عبداﷲبن ابراهیم سلطان نظم کرده، شاهزاده او را صله داد و نوازش فرمود، و او مردی معاشر و ندیم شیوه بود، همواره به جوانان و ظریفان اختلاط نمودی، و به اندک فرصتی آن مال برانداخت، مدت سی سال در شیراز به دلخوشی و ظرافت و عشرت روزگار گذرانیده، در حدود سنه ٔ <span class=\"hlight\" dir=\"rtl\">٨٥٤</span> هَ . ق . وفات یافت و در پهلوی خواجه حافظ در مصلای شیراز، مدفون است - انتهی . تاریخ وفات او را هدایت در ریاض العارفین <span class=\"hlight\" dir=\"rtl\">٨٨٤</span> هَ . ق . نوشته و این رباعی را نیز از او آورده است :<br />در کوچه ٔ عاشقی به پیمان درست <br />میگفت بمن اهل دلی روز نخست <br />طالب مطلب کسی که او غیر تو جست <br />رو طالب آن باش که او طالب تست .<br /> <font color=\"Red\">(ریاض العارفین ).</font><br />لطفعلی بیک آذر در جائی نویسد: جاجرمی، از کدخدازادگان آن دیار، و مردی معاشر و ندیم و از شاگردان شیخ آذری بوده در اوائل حال بشیراز رفته در آنجا قبول تمام یافته، مثنوی مناظره ٔ گوی و چوگان را در شیراز بنام سلطان عبداﷲبن ابراهیم بن شاهرخ گورکان بنظم درآورده، از او صله و نوازش یافته، و هم در آنجا در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٥٢٠</span> (؟) بعالم باقی شتافته و در مقبره ٔ خواجه حافظ شیرازی رحمة اﷲ علیه مدفون است . این یک بیت از اوست :<br />رفتی و بگریستم چندانکه آب از سر گذشت <br />از پیت ز آن رو نمی آیم که پایم در گل است .<br /> <font color=\"Red\">(آتشکده ٔ آذر ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>).</font><br />و هم او در جای دیگر آرد: در شیراز نشو و نما یافته، و مزار او در پائین پای خواجه حافظ است، و این رباعی او در سنگ مزارش کنده بود که فقیر یاد گرفتم :<br />در کوچه ٔ عاشقی به پیمان درست <br />میگفت بمن اهل دلی روز نخست <br />طالب مطلب کسی که آن غیر تو جست <br />تو طالب او باش که او طالب تست .<br />(لطائف نامه ترجمه ٔ مجالس النفائس ص <span class=\"hlight\" dir=\"rtl\">١٩</span>). و در صفحه ٔ <span class=\"hlight\" dir=\"rtl\">١٩٣</span> همان کتاب آرد: مولانا طالب، جاجرمی بوده و لیکن در شیراز نشو و نما یافته و انوار خواجه حافظ بر او تافته زیرا که در مزار او ساکن میبوده . و همان رباعی را می آورد.در ترجمه ٔ مجالس النفائس به قلم حکیم شاه محمد قزوینی آمده : که انوار خواجه حافظ بر او تافته، زیرا که در مزار او میبوده، و این رباعی بر دیوار مزار خواجه حافظ نوشته :<br />در کوچه ٔ عاشقی به پیمان درست . (ترجمه ٔ مجالس النفائس چ حکمت ص <span class=\"hlight\" dir=\"rtl\">١٩٣</span>).<br />و رجوع به تاریخ ادبیات ادواردبراون ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩٤</span> شود.<br /></font></div>'),
(175208, 'طالب جان', '<span class=\"hlight\">طالب جان .</span> <font color=\"DarkGreen\"><b>[ ل ِ]</font></b> (اِخ ) موضعی در شمال چیل نادری از توابع مکران .<br /></font></div>'),
(175209, 'طالب خان', '<span class=\"hlight\">طالب خان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) دهی است از دهستان سراجو بخش مرکزی شهرستان مراغه . در <span class=\"hlight\" dir=\"rtl\">٣</span>هزارگزی باختر مراغه و دوهزارگزی شمال باختری شوسه ٔ مراغه به آذرشهر. جلگه معتدل با <span class=\"hlight\" dir=\"rtl\">٤٣٨</span> تن سکنه ٔ شیعه . آب آن از صوفی چای و محصول آنجا غلات و کشمش و نخود و بادام و زردآلو. شغل اهالی زراعت، صنایع دستی، گلیم بافی و راه آن ارابه رو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(175210, 'طالب خاکروب', '<span class=\"hlight\">طالب خاکروب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب ِ ]</font></b> (اِخ ) صاحب کتاب النقض ذیل احوال ابوالقاسم بن عبدویه آرد: شخصی اصولی مذهب و شیعی بوده پادشاه وقت او را بسبب فتنه و غوغا بفرمود برآویختن و چون او را معلوم شد که طالب خاکروب سنی و دیگران از حنفی و شافعی در حق وی خوابهای نیک دیدندو معتمدان طوایف بر ایمان وی گواهی دادند پشیمان شدو رخصت داد که او را در مقابل تربت سید عبدالعظیم الحسنی رضی اﷲ عنه دفن کردند... (کتاب النقض ص <span class=\"hlight\" dir=\"rtl\">٨٨</span>).<br /></font></div>'),
(175211, 'طالب علم', '<span class=\"hlight\">طالب علم .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب ِ ع ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) دانشجو. جویای دانش . خواستار علم <span class=\"hlight\">:</span> <br />کبک چون طالب علم است و در این نیست شکی <br />مسئله خواند تا بگذرد از شب سیکی .<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(175212, 'طالب علمانه', '<span class=\"hlight\">طالب علمانه .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب ِ ع ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی مرکب، ق مرکب ) طلاب . چون طالب علمان <span class=\"hlight\">:</span> <br />بسته زیر گلو از غالیه تحت الحنکی <font color=\"DarkGreen\"><b>[ کبک ]</font></b><br />پیرهن دارد زین طالب علمانه یکی .<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(175213, 'طالب علمی', '<span class=\"hlight\">طالب علمی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب ِ ع ِ ]</font></b> (حامص مرکب ) دانشجوئی . فراگیری علوم . طلبگی <span class=\"hlight\">:</span> شیخ ما <font color=\"DarkGreen\"><b>[ ابوسعید ]</font></b> گفت که ما بوقت طالب علمی به سرخس بودیم . (اسرارالتوحید ص <span class=\"hlight\" dir=\"rtl\">١٦</span>).<br /></font></div>'),
(175214, 'طالب قشلاقی', '<span class=\"hlight\">طالب قشلاقی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب ِ ق ِ ]</font></b> (اِخ ) دهی است از بخش نمین شهرستان اردبیل در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی شمال باختری اردبیل و سه هزارگزی اردبیل . کوهستانی معتدل .با <span class=\"hlight\" dir=\"rtl\">١١٠٧</span> تن سکنه . آب آن از چشمه و رود قره سو. محصول آنجا غلات و حبوبات . شغل اهالی زراعت و گله داری . راه آن ارابه رو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(175215, 'طالب لاهیجانی', '<span class=\"hlight\">طالب لاهیجانی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب ِ ]</font></b> (اِخ ) اصلش از لاهیجان در خدمت احمدخان بوده ... در قزوین وفات یافته، از او است :<br />بعد عمری گر نگاهی جانب من میکند<br />صد نگه بهر تسلی سوی دشمن میکند.<br /><font color=\"Red\">(آتشکده ٔ آذر ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span>).</font><br /></font></div>'),
(175216, 'طالب نگین', '<span class=\"hlight\">طالب نگین .</span> <font color=\"DarkGreen\"><b>[ ل ِ ن ِ ]</font></b> (ص مرکب ) خواهان نگین و نگین دار. و مجازاً آراسته به نشانه های پادشاهی <span class=\"hlight\">:</span> <br />ای بتو صاحب درفش، چتر فریدون ملک <br />وی ز تو طالب نگین، دست سلیمان دین .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(175217, 'طالب چمنی', '<span class=\"hlight\">طالب چمنی .</span> <font color=\"DarkGreen\"><b>[ ل ِ چ َ م َ ]</font></b> (اِخ ) دهی است از دهستان فوریچای بخش قره آغاج شهرستان مراغه در <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی شمال باختری قره آغاج و <span class=\"hlight\" dir=\"rtl\">١٠/٥</span>هزارگزی جنوب شوسه ٔ مراغه به میانه . کوهستانی معتدل و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> تن سکنه . آب آن از چشمه سار محصول آنجا غلات و نخود شغل اهالی زراعت . صنایع دستی جاجیم بافی و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(175218, 'طالب گیلانی', '<span class=\"hlight\">طالب گیلانی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب ِ ]</font></b> (اِخ ) از اهل گیلان است . شاعری است هموار و پخته . و گویا در آن ولایت بالاتر از وی شاعری نباشد، ابیات خوبی دارد، و دیوانی ترتیب داده است . این بیتها از او است :<br />اجل ز محنت هستی دهد نجات مرا<br />که من حیات نمیخواهم و حیات مرا.<br />چو ره بسوی توام نیست گم شود یارب <br />هوس که در طلب وصل رهنمون من است .<br />آوارگی نصیب من دردمند شد<br />شادی کن ای رقیب که بختت مراد داد.<br />خاک بویان گذرد تا شنود بوی وفا<br />سگ لیلی چو سوی تربت مجنون گذرد.<br />دعوی عشق و جنون اهل وفا را میرسد<br />عاشقی میراث مجنون است ما را میرسد.<br />گر چه طفلی عشوه از خوبان فزون دانسته ای <br />وقت نادانیست حیرانم که چون دانسته ای <br />ای ترا سرو از گرفتاران پا در گل یکی <br />غنچه را در دعوی عشقت زبان با دل یکی .<br /><font color=\"Red\">(از مجمع الخواص ص <span class=\"hlight\" dir=\"rtl\">٢٨٣</span>).</font><br /></font></div>'),
(175219, 'طالبا', '<span class=\"hlight\">طالبا.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ابوطالب کلیم شاعر معروف . رجوع به کلیم و ابوطالب در همین لغت نامه شود.<br /></font></div>'),
(175220, 'طالبان', '<span class=\"hlight\">طالبان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) میر محمدباقر استرآبادی مشهور بطالبان . از تلامذه ٔشیخ بهائی بوده چنانکه در امل الاَّمل آورده . و او راست : شرحی بر زبدة الاصول و غیر ذلک . (روضات ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>).<br /></font></div>'),
(175221, 'طالبة', '<span class=\"hlight\">طالبة.</span> <font color=\"DarkGreen\"><b>[ ل ِ ب َ ]</font></b> (ع ص ) مؤنث طالب . <BR><font color=\"Blue\">◄</font> ماچه خر گشن خواه . (منتهی الارب ).<br /></font></div>'),
(175222, 'طالبو', '<span class=\"hlight\">طالبو.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) یکی از رستاقهای استرآباد. (سفرنامه ٔ مازندران و استرآباد رابینو ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175223, 'طالبوف', '<span class=\"hlight\">طالبوف .</span> <font color=\"DarkGreen\"><b>[ ل ِ ب ُ ]</font></b> (اِخ ) طالب اُف . حاجی ملاعبدالرحیم پسر استاد ابوطالب نجار تبریزی سرخابی در سال <span class=\"hlight\" dir=\"rtl\">١٢٥٠</span> هَ . ق . متولد شد و در حدود شانزده سالگی به تفلیس رفت و به تحصیل زبان روسی و ادبیات آن پرداخت و متدرجاً نزد حکام و علماء روسیه به درستکاری وراست گفتاری شناخته شد و سپس در تمرخان شوره دارالحکومه ٔ داغستان نشیمن گرفت و محل احترام و اعزاز جمیع طوائف اسلام و غیرهم گردید و خانه اش مقصد امرا و علماو اعیان و اشراف و ملجاء نیازمندان و مستمندان گردید. وی یکی از نخستین نگارندگان فارسی است که ابناء وطن خود را به تألیف رمانهای علمی و تئاتر و ترجمه هااز علوم و فنون و صنایع عصریه و مکارم اخلاق بزبان ساده آگاه کرد و این امر روزبروز بر اعتبار و منزلت او نزد همه می افرود. وی را تألیفات عدیده است که اغلب آنها به طبع رسیده و در عصر خود بسیار شهرت کرده مخصوصاً «کتاب احمد» یا «سفینه ٔ طالبی » در سه جلد و دیگر «پندنامه ٔ قیصر» و «مسالک المحسنین » و «مسائل الحیات » و «فیزیک » و «تاریخ مختصر اسلام ». صاحب ترجمه در اواخر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٨</span> هَ . ق . در تمرخان شوره ٔ مذکور وفات یافت در حدود سن هفتاد و نه سالگی . (وفیات معاصرین بقلم محمد قزوینی، مجله ٔ یادگار سال پنجم شماره ٔ <span class=\"hlight\" dir=\"rtl\">٤</span>و <span class=\"hlight\" dir=\"rtl\">٥</span>) و ایرج افشار شرح حال طالبوف و تألیفات او رادر مجله ٔ یغما نوشته اند که عیناً نقل میشود: بنده محب عالم و بعد از آن محب ایران و بعد از آن محب خاک پاک تبریز هستم . «چه کنم حرف دگر یاد نداد استادم ». حاجی عبدالرحیم طالب اف از جمله ٔ مردان تجددطلب و آزادیخواهی است که در قرن اخیر موجبات تنویر افکار و نهضت آزادی را در ایران بوجود آورده اند، و حق آن است که در تاریخ یکصدساله ٔ اخیر نامش جاویدان ماند، چه اودر راه بیداری ایرانیان و آزادی آنان مردی کوشا بودکسی بود که در ترویج تجددطلبی کمال سعی را داشت و مردم را به موازین مشروطیت تشویق میکرد، و نیز نویسنده ای بود که آثار خود را به اسلوب و سبکی ساده و روان نوشت و اصول قدیم نویسندگی را رها کرد و هیچگونه پای بندی به اسالیب قدیمی نشان نداد. به همین جهت او راباید یکی از موجدین و بنیادگذاران نثر جدید بشمار آورد. روشی که طالب اف در نویسندگی اختیار کرده در سبک نثر کنونی تأثیر بخشیده و امروز نامش در زمره ٔ کسانی چون ملکم خان و دیگران که در ایجاد شیوه ٔ جدید نثرنویسی کوشا و سهیم بوده اند برده میشود. متأسفانه تاکنون در احوال و چگونگی زندگی وی تحقیق کافی و لازم نشده بطوری که ترجمه ٔ حالش تاریک و مبهم و فراموش شده مانده است . نویسنده ٔ این سطور مدتها در جستجو بود وبه عموم مراجع و کتبی که در دسترس بود مراجعه کرد ولی این باده ها هیچیک کفاف مستی ما را نداد تا اینکه آقای تقی زاده که با آن مرحوم دیدار کرده بودند اطلاعات ذی قیمت خود را در اختیار نویسنده گذاشتند و در حقیقت وسیله ٔ تألیف این یادداشتها شدند... و اینک موظفم که مراتب امتنان خود را بحضور ایشان تقدیم دارم .<br />زندگی طالب اف . دوران زندگی طالب اف (<span class=\"hlight\" dir=\"rtl\">١٢٥٠</span> - <span class=\"hlight\" dir=\"rtl\">١٣٢٩</span> هَ . ق .) مصادف با زمانی بود که ایران رو به بیداری و آزادی میرفت . اگر بخواهیم آغاز تاریخ نهضت آزادی ایران را بیابیم باید از سال <span class=\"hlight\" dir=\"rtl\">١٢٥٠</span> هَ . ق . به آنسوی تر رویم و از هنگام سلطنت فتحعلی شاه آغاز کرده پیش آئیم . در دوران سلطنت ناصرالدین شاه از طرف مردم کوششهائی برای به دست آوردن آزادی به کار رفت که بی ثمر نبود. واقعه ٔ تحریم تنباکو و فعالیتهای دامنه دار سید جمال الدین مشهور به افغانی، نشر جریده ٔ قانون در لندن توسط میرزا ملکم خان، ارتباط با ممالک اروپائی و بالاخره کشته شدن شخص شاه و عوامل دیگر همه از موجباتی بود که در آن زمان برای بیدار شدن ایران مؤثر بود. در هنگام سلطنت ناصرالدین شاه چون محیط داخلی ایران برای تبلیغ اصول آزادی و بیان افکار «تجددمآبانه » مساعد نبود، جمعی از ایرانیان در خارج از مملکت به کوشش برخاستند مردانی چون میرزا فتحعلی آخوندزاده و طالب اف در بلاد قفقاز، حاجی زین العابدین مراغه ای و میرزا حبیب اصفهانی در اسلامبول، مدیرجریده ثریا در قاهره و جمعی دیگر در هندوستان ندای آزادی در دادند. میرزا ملکم خان هم در این راه خدمات فراموش نشدنی کرد طالب اف نیز بسهم خویش مردی مؤثر بود. نام وی عبدالرحیم و نام پدرش بطوری که خودش در پشت جلد کتاب «مسائل الحیاة» نوشته است شیخ ابوطالب بن علیمراد بود. طالب اف به سال <span class=\"hlight\" dir=\"rtl\">١٢٥٠</span> هَ . ق . در محله ٔ «سرخاب » از شهر تبریز متولد شد و در اوائل سال <span class=\"hlight\" dir=\"rtl\">١٣٢٩</span> هَ . ق . در شهر «تمرخان شوره » (دارالحکومه ٔ داغستان )جهان را بدرود گفت . در تاریخ فوت او اختلاف دیدم، روزنامه ٔ «شمس » چ اسلامبول در شماره ٔ <span class=\"hlight\" dir=\"rtl\">١٨</span> سال سوم مورخ <span class=\"hlight\" dir=\"rtl\">٢٣</span> ربیع الاخر <span class=\"hlight\" dir=\"rtl\">١٣٢٩</span> هَ . ق . نوشته است : «در هفته ٔ گذشته ٔ افول یک ستاره ٔ نورافشان آسمان ادبیات ایران را... با یک ناگواری تلخی مشاهده کردیم ...» و از اینجا معلوم میشود که باید در اوائل ماه ربیعالاَّخر فوت شده باشد. اما مرحوم قزوینی در یاداشت های «وفیات معاصرین » مندرج در مجله ٔ یادگار و همچنین کسان دیگری که درباره ٔ طالب اف مطالبی نوشته اند تاریخ مرگ او را اواخر سال <span class=\"hlight\" dir=\"rtl\">١٣٢٨</span> هَ . ق . ضبط کرده اند. پدرش در شهر تبریز به کار درودگری اشتغال داشت، اما فرزند به آن کار دل نبست و در حدود هفده سالگی از تبریز بار سفر بربست و بشهر تفلیس رفت . در آن زمان ایرانیان مهاجر در شهر قفقاز بسیار بودند که به کار و کسب مشغول بودند. از جمله مردی بود بنام محمد علی خان از خانواده ٔ شیبانی های اهل کاشان که دل از ایران کنده بود و در آنجا به کار «مقاطعه کاری » راههای قفقاز پرداخته بود که بروسی به آنان «پدراتچی » میگویند. محمدعلی خان سالیانی را که در تفلیس و سایر بلاد قفقاز بسر برده بود با کوشش و سعی توانسته بود سرمایه ٔ فوق العاده ای فراهم سازد. وی در آنجا تأهل اختیار کرد و دارای دو پسر یکی بنام اسدخان و دیگری بنام فرخ خان و یک دختر بنام ماهرخ بود. اسدخان و فرخ خان بعدها بمقامات عالیه ٔ دولتی از قبیل سفارت رسیدند. طالب اف بشرحی که خواهیم دید چون در دستگاه محمدعلی خان کار میکرد با اولاد او نیز آشنائی یافت که بعدها در کتابهای خود از «اسد» و «ماهرخ » نام برده است . از جمله اشخاصی که در امور محمد علی خان شرکت داشتند همین عبدالرحیم طالب اف بود که پس از سالها خود ثروتی جمع آورد و توانست به استقلال به کار «مقاطعه کاری » بپردازد. کم کم تمول قابل ملاحظه ای پیدا کرد و در تمرخان شوره مرکز حکومت داغستان منزل آبرومند و بزرگی تهیه کرده زندگی دلخواهی را آغاز نهاد. وی در قفقاز زنی از اهل «دربند» را بزوجیت اختیار کردکه شیعی مذهب بود. مقامی که طالب اف در تاریخ اخیر ایران یافت بیشتر به این علت است که نوشته های خود را بی تکلّف می نوشت و سبک تازه ای در ادبیات فارسی بوجود آورد. اما باید به این نکته اشارت کنم که وی در زبان و ادبیات ایران تبحر و تحصیلات لازم را نداشت و تنها بر اثر شوق و ذوق فطری از این مرحله پیروز برآمد. خودش در نامه ای که بتاریخ <span class=\"hlight\" dir=\"rtl\">١٦</span> رمضان سال <span class=\"hlight\" dir=\"rtl\">١٣١٤</span> هَ . ق . بمرحوم میرزا یوسف اعتصام الملک نوشته می نویسد که : «بنده بزبان روسی آشنا هستم . فرانسه نمیدانم . خط روسی رابسیار بد می نویسم . خط ایرانی طبیعی بنده نیز تعریفی ندارد. عربی هیچ بلد نیستم . فارسی را معلوم است چنان میدانم که عرب و فرانسه را. با وجود این از برکت کثرت مطالعه و زور مداومت، بعضی آثار مختصر بیادگار گذاشتم که اخلاف بنده تکمیل کرده بنده را مهندس انشای جدید بدانند.» طالب اف بخرافات مذهب اسلام بهیچوجه پای بندی نداشت و در تلو نوشته های او تصریحاً و تلویحاً به این نکته برخورد می کنیم، اما بمکه رفت و مراسم حج را بجای آورد. چشم وی در اواخر عمر تار شد بطوری که ... آقای محمود عرفان از قول شخص موثقی میگفتند که هنگام خواندن یا نوشتن کاغذ را آنقدر بچشم نزدیک میکرد که بیش از سه انگشت فاصله نمیماند. ناچار بقصد استعلاج از تمرخان شوره به برلین می رود و آقای تقی زاده می فرمودند آمدن او به برلین مصادف با زمانی بود که مرحوم احتشام السلطنه علامیر سفیر ایران در آنجا بود (<span class=\"hlight\" dir=\"rtl\">١٩٠٢</span> یا <span class=\"hlight\" dir=\"rtl\">١٩٠٣</span> م .) در آغاز این مقال اشاره کردم که سوانح زندگی طالب اف روشن نیست و هر چه نوشته شده در هم آمیخته میباشد، از جمله مرحوم محمدعلی تربیت در کتاب مفید «دانشمندان آذربایجان » نوشته است که طالب اف با همکاری سید محمد شبستری یک شماره روزنامه بنام «شاهسون » به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٦</span> هَ . ق . هجری در اسلامبول نشر کرده است .<br />طالب اف و مشروطیت . طالب اف به ایران واقعاً علاقمند بوده است و می نویسد: بنده محب عالم و بعد از آن محب ایران و بعد از آن محب خاک پاک تبریز هستم «چه کنم حرف دگر یاد نداد استادم » و برحسب این علاقه ٔ ذاتی برای تعالی و ترقی ایران سخن میگفت و کتاب می نوشت تا مگر نتیجه ای حاصل آید. او خوشحال بود تا دیگران هم در این راه کمک و یاورش باشند. وقتی آقای تقی زاده به باکو میرسد شخصی از جانب طالب اف نزد وی رفته به تقی زاده میگوید: وقتی رساله ٔ شما را موسوم به «تحقیق در احوال کنونی ایران » خواندم از مرگ بیم ندارم زیرا می بینم پس از من کسی هست تا آنچه را صلاح هست بیان کند. طالب اف برای آزادی ایران قدمهای نافع و مؤثر برداشت از هنگامی که «مسالک المحسنین » و «مسائل الحیاة» را نوشت و قبل وبعد از آن همتش بر این بود که مفهوم آزادی و مشروطیت را برای ایرانیان توضیح کند. مردم آذربایجان بپاس احترام او در دوره ٔ اول مجلس او را بسمت نمایندگی انتخاب کردند نمایندگان آذربایجان در آن دوره اینها بودند: حاجی میرزا ابراهیم آقا، آقامیرزا فضلعلی، سید حسن تقی زاده، مستشارالدوله، حاجی میرزا یحیی امام جمعه خوئی، احسن الدوله هدایت اﷲ میرزا، حاجی عبدالرحیم طالب اف، حاجی محمد حریری، حاجی میرزامیر هاشم دوچی آقا فرش فروش و شرف الدوله . لکن با وجودی که طالب اف قبل ازشروع انتخابات به یکی از دوستانش نوشته بود: «اگر بنده را انتخاب نمایند سر از قدم نشناخته می آیم اما عقیده من باز همان است که ایرانی و مجلس حکایت گاو دهل زن است .» و پس از انجام انتخابات هم قبول کرد که برای شرکت در مجلس بطهران بیاید ولی وفای بعهد نکرد حتی هنگامی که سایر نمایندگان آذربایجان از تبریز حرکت کرده به بادکوبه رفتند تا از راه دریا بطهران بیایند و در آن شهر بین آنها و طالب اف که از تمرخان شوره بدیدارشان آمده بود ملاقاتی روی داد گفته بوده است وقتی بکارهای شخصی خود سر و سامانی دادم به طهران خواهم آمد. اما در این باب که چرا طالب اف وکالت مجلس را قبول نکرد نظریات مختلفی است . آقای اسماعیل یکانی میگفت که چون او با اتابک دوستی صمیمانه ٔ شخصی داشت و در آن هنگام اتابک مورد انتقاد شدید آزادیخواهان و بالخصوص وکلای آذربایجان بود به طهران نیامد تا در مخالفت بر ضد اتابک شرکتی نکرده باشد. راست است، دوستی وی با اتابک صمیمانه بود به طوری که اتابک هنگام بازگشت به ایران در بادکوبه با طالب اف ملاقاتی کرد و از او سفارشنامه ای بعنوان سعدالدوله که هنوز از آزادیخواهان محسوب میشد گرفت . اتابک در این مورد از ملکم خان هم که مورد علاقه و احترام آزادیخواهان بود چنین مکتوبی را گرفته بود. آقای صادق صادق (مستشارالدوله ) و آقای تقی زاده علت نیامدن او را کهولت و ناتوانی خاصه تاری چشم میدانند. کسروی در کتاب تاریخ مشروطه نوشته است که چون کتاب «مسالک المحسنین » او از طرف شیخ فضل اﷲ نوری قدغن شده بود ناراضی بود و برای احتراز ازعواقب امر بطهران نیامد.<br />نظر طالب اف درباره ٔ مشروطیت .از کتابها و مقالات و مکاتیب طالب اف مستفاد میشود که وی آزادی و مشروطیت را برای ایران لازم میدانسته امانه چنان بی قید و شرط که اشکالات دیگری تولید شود. وی در کتاب «مسائل الحیاة» عقاید خود را در این باره بیان داشته و در پایان آنهم ترجمه ای از قانون اساسی ژاپن را آورده است . در رساله ٔ «ایضاحات درباره ٔ آزادی » نیز نظریات خود را نوشته و بطوری که از این پس خواهیم دید کتاب مزبور را در چگونگی مجلس شورای ملی و لزوم ایجاد آن تدوین کرده است . اما در عین حال به این نکته توجه داشته است که آزادی بی بند و بار مفید فایده نیست و کوشش میکرده مردم را به این معنی متوجه سازد. چنانکه در مکتوبی که به میرزا ابوالقاسم آذر مرتضوی نوشته می نویسد: «باری باید ایستاد و کار را ساخت و شهید راه وطن شد، در کارهای خطیر از این دو یکی ناگزیر است . بخدای لایزال اگر این مجلس و یکصد و شصت وچند نفر وکیل متفق باشند و معتدل حرف بزنند و به دست حکومت اسباب علائم ضعف و سوء ظن ندهند و اول از تعلیم و تربیت ملت شروع نمایند همه ٔ اروپا را متعجب میکنند.» همچنین در مکتوبی که پس از بمباران مجلس به آقای علی اکبر دهخدا نوشته متذکر شده است که : «در خصوص نشر صوراسرافیل امیدوارم که بزودی تمام پراکندگان وطن باز به ایران برگردند و در عوض مجادله و قتال در خط اعتدال کار بکنند». و نیز در مکتوبی که از او در شماره ٔ <span class=\"hlight\" dir=\"rtl\">٣٣</span> روزنامه ٔ انجمن تبریز بچاپ رسیده است نکاتی دقیق وجود دارد طالب اف در آنجا می نویسد: «ایرانی که تاکنون اسیر یک گاو دو شاخه ٔ استبداد بود اما بعد از این اگر اداره ٔ خود را قادر نشود بگاو هزارشاخه ٔ رجاله دچار گردد. آن وقت مستبدین به نابالغی ما میخندند و دشمنان اطراف شادی کنان لاحول گویند. فاش میگویم که این مسئله بیچون و چرا می بینم ». اگر بخواهیم بحث تحلیلی در باب کتابها و نظریات او بکنیم سخن به درازا میکشد که از حوصله ٔ این مقال خارج است . طالب اف همانطور که نوشته شد قصدش بیداری ایرانیان و افکار آنان بوده است و برای رسیدن به این مقصود از هر راه که ممکن بود اقدام کرد و در ایجاد مدارس جدید کوشش داشت . از جمله در سال <span class=\"hlight\" dir=\"rtl\">١٣١٩</span> هَ . ق . با کمک مرحوم ملک المتکلمین (وقتی که از راه بادکوبه به اروپا میرفته ) در بادکوبه مدرسه ای جهت تعلیم و تربیت ایرانیان آنجا تأسیس میکند و این مطلب را سید حبیب اﷲ اشرف الواعظین در ضمن یادداشتهای خود نوشته است و در کتاب «ملک المتکلمین » تألیف دکتر ملکزاده درج میباشد.<br />تألیفات طالب اف .<br /><span class=\"hlight\" dir=\"rtl\">١</span> - پندنامه ٔ مارکوس قیصر روم . این کتاب نتیجه ٔ تفکرات «مارکواوریل انتانیس » است که طالبوف آن را از نسخه ای که «پرنس اوروزوف » از زبان یونانی بروسی ترجمه کرده از تاریخ <span class=\"hlight\" dir=\"rtl\">٢٥</span> شعبان <span class=\"hlight\" dir=\"rtl\">١٣١٠</span> هَ . ق . تا <span class=\"hlight\" dir=\"rtl\">١٢</span> شوال همان سال به فارسی نقل کرده است کتاب مزبور در مطبعه ٔ اختر (اسلامبول ) به طبع رسیده لکن تاریخ چاپ آن معلوم و مشخص نیست .<br /><span class=\"hlight\" dir=\"rtl\">٢</span> - رساله ٔ فیزیک . کتابی که پس از پندنامه ٔ مارکوس تدوین کرد رساله ای است در علم فیزیک ... متأسفانه نویسنده ٔ این سطور با کوششی که کرد نسخه ای از آن را به دست نیاورد تا مشخصات آن را بنویسد.<br /><span class=\"hlight\" dir=\"rtl\">٣</span> - نخبه ٔ سپهری . این کتاب خلاصه ای است در احوال رسول اکرم (ص ) که نخستین بار در اسلامبول به سال <span class=\"hlight\" dir=\"rtl\">١٣١٠</span> هَ . ق . و نیز در سال <span class=\"hlight\" dir=\"rtl\">١٣٢٢</span> هَ . ق . در طهران چاپ شده است .<br /><span class=\"hlight\" dir=\"rtl\">٤</span> - سفینه ٔ طالبی یا کتاب احمد. سفینه ٔ طالبی که کتاب احمد هم نام دارد مشتمل بر دو جلد میباشد که جلد اول آن به سال <span class=\"hlight\" dir=\"rtl\">١٣١١</span> هَ . ق . و جلد دوم آن در سال بعد در اسلامبول به طبع رسیده است . در این کتاب که بصورت صحبت و مباحثه تدوین شده روی سخن طالبوف با پسر موهومی خود بنام احمد است و سخن بر سر مسائل فیزیکی و طبیعی و اختراعات و اکتشافاتی میباشد که در قرن اخیر بوجود آمده است . مؤلف در مقدمه ٔ جلد دوم آن نوشته : «من بنده که سالها است از وطن دور افتاده ام دست تقدیر عنان بسوی غربت معطوف داشته است . به اقتضای حب وطن که خود ازایمان است پیوسته بیاد آن مشعوف بوده ام ...» و کتاب را به میرزا اسداﷲخان ناظم الدوله که سالیان دراز والی فارس و سفیر ایران در اسلامبول بود و طالب اف او را مردی دانشمند و اهل فضل معرفی کرده تقدیم داشته است .<br /><span class=\"hlight\" dir=\"rtl\">٥</span> - رساله ٔ هیئت جدیده . این کتاب ترجمه ٔ اثر معروف «کامیل فلاماریون » دانشمند مشهور فرانسوی است و طالب اف آن را از روی نسخه ای که «ب . چار کسوف » بروسی ترجمه کرده به فارسی نقل کرده و در سال <span class=\"hlight\" dir=\"rtl\">١٣١٢</span> هَ . ق . در مطبعه ٔ اختر (اسلامبول ) به طبع رسانیده است . «رساله ٔ هیئت جدیده » بعدها در سال <span class=\"hlight\" dir=\"rtl\">١٣١٢</span> هَ . ش . ضمیمه ٔ «گاهنامه » و به همت آقای سید جلال الدین طهرانی تجدید چاپ شد.<br /><span class=\"hlight\" dir=\"rtl\">٦</span> - «مسالک المحسنین ». این کتاب از میان آثار طالب اف جنبه ٔ ادبی دارد و بصورت یک سفرنامه نگارش یافته اما شرح یک سفر خیالی است به این شرح که : دوشنبه ٔ <span class=\"hlight\" dir=\"rtl\">١٤</span> ذیقعده <span class=\"hlight\" dir=\"rtl\">١٣٢٠</span> هَ . ق . هیئتی بریاست بنده ٔ راقم محسن بن عبداﷲ، متشکل از دو نفر مهندس مصطفی و حسین، یک نفر طبیب احمد، و یکنفر مهندس شیمی محمد، از اداره ٔ جغرافیای موهومی مظفری مأمور شدیم که بقله ٔ کوه دماوند صعود نمائیم . معدن یخ طرف شمال او را ملاحظه بکنیم، ارتفاع قله را مقیاس، و سایر معلومات و مکاشفات رابا خریطه ٔ معابر خویش به اداره تقدیم نمائیم و این مأموریت را در سه ماه بختام آوردیم ...» مسالک المحسنین با تصاویر و چاپی عالی به سال <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> هَ . ق . در قاهره طبع شده است . طالب اف چون آن را بصورت داستان نوشته خواننده را بدنبال خود میکشد و با دقت تمام بشرح قضایائی که اتفاق افتاده پرداخته وضع اشیاء و حالات افراد را مانند یک رمان نویس وصف میکند.<br /><span class=\"hlight\" dir=\"rtl\">٧</span> - مسائل الحیات یا کتاب احمد. طالب اف پس از اینکه کتاب مسالک المحسنین را نوشت و در ایران مورد توجه واقع شد به نوشتن کتبی پرداخت که از لحاظ اجتماعی برای مردم مفید بود. لهذا در دنبال کتاب مسالک المحسنین کتاب «مسائل الحیات » یا «کتاب احمد» را نوشت که بسیاق سفینه ٔ طالبی در آن با پسر موهومی خود بنام احمد از مسائل سیاسی و حقوقی و اجتماعی سخن میگوید. در کتاب مسائل الحیات بصورت جالبی از فلسفه ٔ مشروطیت و آنچه مربوط به حیات اجتماعی است بحث کرده و سپس سخن را به حقوق اساسی و قانون کشانیده و با نقل ترجمه ٔقانون اساسی ژاپن کتاب را پایان داده است . کتاب مزبور به سال <span class=\"hlight\" dir=\"rtl\">١٣٢٤</span> هَ . ق . در شهر تفلیس طبع گردیده است .<br /><span class=\"hlight\" dir=\"rtl\">٨</span> - ایضاحات در خصوص آزادی . رساله ای است که طالب اف درباره ٔ آزادی و معمای آن در تاریخ اول ذیحجه ٔ سال <span class=\"hlight\" dir=\"rtl\">١٣٢٤</span> هَ . ق . نوشته و حسب الامر مجدالاسلام مدیر روزنامه ٔ ندای وطن در ربیع الثانی <span class=\"hlight\" dir=\"rtl\">١٣٢٥</span> هَ . ق . در تهران چاپ شده و مشتمل است بر ابواب زیر: در تحقیق معنای آزادی . در بیان مجلس شورای ملی . در فواید مجلس شورای ملی . درتکلیف وکلای ملت . در بیان و تکلیف ملت . در بیان قوانین آتیه ٔ ایران . در بیان مالیات . در بیان قانون اساسی .<br />روزنامه «شمس » کتابی بنام «دستور دارالشورا» به او نسبت داده است که نویسنده تا کنون از آن خبر ندارد و در هیچیک از مراجع و مآخذ نیز نام آن نیامده است .<br /><span class=\"hlight\" dir=\"rtl\">٩</span> - سیاست طالبی . آخرین کتابی که از طالب اف پس از مرگش بچاپ رسیده «سیاست طالبی » است که مشتمل بر دو مقاله است یکی «سیاسی » و دیگری «ملکی ». کتاب مزبور به سال <span class=\"hlight\" dir=\"rtl\">١٣٢٩</span> در طهران طبع شده و ناشر در پشت جلد کتاب نوشته است که : «این کتاب عدیم المثال از جمله ٔ کتابهائی است که تا بحال نسخه ٔ آن را احدی ندیده و ابداً در هیچ جا به طبع نرسیده و مقالات و مطالب آن تا حال در هیچ کتابی دیده نشده و مندرجات آن بسیار تازه و جاذب است و مخصوصاً برای مردگان قبور جهل (یعنی ایرانیان ) نفخه ٔ صور آخرین است و حسب المیل خودآن مرحوم در زمان حیاتش به طبع نرسیده، اینک حضرت مستطاب ثقةالاسلام آقای حاجی سید ابراهیم نماینده ٔ محترم فارس مؤسس طبع گردیده و بمراقبت و مداقه ٔ این بنده میرزا حبیب اﷲ شیرازی بحلیه طبع آراسته گردید.<br /><span class=\"hlight\" dir=\"rtl\">١٠</span> - اشعار و مقالات .غیر از کتبی که از آنها سخن رفت طالب اف مقالات پراکنده ای دارد که در جراید آن زمان مثل «انجمن » و «حبل المتین » و غیره درج است . وی بعض اوقات شعر هم میگفت و آنچه از اشعار او در دست میباشد بیشتر جنبه ٔ اجتماعی دارد که بمنظور تهییج افکار ایرانیان سروده است . اما باید توجه داشت که اشعار او از لحاظ شعری قابل توجه نیست و با نثر عالی او قابل ملاحظه نمیباشد. چند قطعه از اشعارش در «مسالک المحسنین » مندرج است و قصیده ای هم از او در شماره ٔ <span class=\"hlight\" dir=\"rtl\">٩</span> روزنامه ٔ تبریز مورخ <span class=\"hlight\" dir=\"rtl\">١٦</span> محرم <span class=\"hlight\" dir=\"rtl\">١٣٢٩</span> هَ . ق . که بمدیریت آقای اسماعیل یکانی در تبریز چاپ میشده به طبع رسیده که ابیاتی از آن در ذیل نقل میشود:<br />تا که دانش و غیرت شد ز خلق ایرانی <br />ملک و ملت ایران رفت رو به ویرانی <br />کشوری همه غافل ملتی همه جاهل <br />مست جام بی علمی محو خمر نادانی <br />هیجده سنه افزون از هزار و سیصد بود<br />کز غم وطن طبعم کرد این نواخوانی .<br />در پایان تذکر دو موضوع را بعنوان تکمله لازم دیدم یکی آنکه وظیفه ٔ خود میدانم از آقای حاج حسین نخجوانی و آقای سلطان القرائی که هر دو از اخیار فضلای تبریز میباشند و مدارکی در احوال مرحوم طالب اف دراختیار اینجانب گذاشتند تشکر کنم که بر من فرض بود دیگر آنکه بموجب شرحی که آقای محمدعلی صفوت تبریزی در کتاب «داستان دوستان » نوشته، طالب اف دارای یک دختربوده که به یکی از اهالی قفقاز شوهر کرده است . مرحوم لعلی ملقب به شمس الاطبا که یکی از فضلای شهر تبریز بوده درباره ٔ طالب اف اشعار متعددی دارد که چند بیت ازآنها را در اینجا نقل میکنیم :<br />زنده باش ای حکیم پندآموز<br />زنده باش ای مربی آدم <br />ای بنای وطن پرستی تو<br />استوار و قویم و مستحکم <br />بخدافیلسوف ایرانی <br />تالیت نیست در دیار عجم <br />گوشه ٔ «شوره » گرچه مسکن تست <br />هست این گوشه رشک باغ ارم .<br /> <font color=\"Red\">(مجله ٔ یغما سال چهارم شماره <span class=\"hlight\" dir=\"rtl\">٥</span> مرداد <span class=\"hlight\" dir=\"rtl\">١٣٣٠</span>).</font><br />و رجوع به سبک شناسی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦٧</span>، <span class=\"hlight\" dir=\"rtl\">٣٧٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٧٣</span>، <span class=\"hlight\" dir=\"rtl\">٤٠٢</span> و همان کتاب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٨</span> شود.<br /></font></div>'),
(175224, 'طالبون', '<span class=\"hlight\">طالبون .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص، اِ) ج ِ طالب در حالت رفعی . جویندگان .<br /></font></div>'),
(175225, 'طالبی', '<span class=\"hlight\">طالبی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ابراهیم بن عبداﷲبن حسن بن علی بن ابی طالب طالبی (<span class=\"hlight\" dir=\"rtl\">٩٧</span> تا <span class=\"hlight\" dir=\"rtl\">١٤٥</span> هَ . ق .)، یکی از امرای سادات دلاور که در بصره بر منصور عباسی خروج کرد، و چهارهزار تن جنگ آور با او بیعت کردند و منصوراز وی در بیم شد و به کوفه انتقال کرد. ولی شیعیان و پیروان طالبی آنقدر فزونی یافتند که وی بر بصره استیلا یافت، و جماعاتی را به اهواز و فارس و واسط حرکت داد، و آنگاه به کوفه حمله ور شد و میان همراهان او و سپاهیان منصور جنگهای خونینی روی داد تا عاقبت حمیدبن قحطبه وی را بکشت . (از الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٥</span>).<br /></font></div>'),
(175226, 'طالبی', '<span class=\"hlight\">طالبی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ص نسبی ) نسبتی است بساداتی که از نسل امیرالمؤمنین علی علیه السلام یا از نسل برادران آن حضرت جعفر و عقیل باشند. (انساب سمعانی ). <BR><font color=\"Blue\">◄</font> علوی . سید. ج، طالبیون که در حال نصب و جر «طالبیین » خوانند: و بین یدیه رجل من اشراف الطالبیین ... فوجد اسم الطالبی فی الجرایة، فقال له و انا اسمع: کانت علیک جرایة... فقال نعم ... و تدمع الطالبی و حضر ذلک العلوی و قضی حقنا. (معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">٢</span> طبع مرجلیوث ).<br /></font></div>'),
(175227, 'طالبی', '<span class=\"hlight\">طالبی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) شاعری است پارسی .او راست : بحرالمعاد فی ارشاد العباد، منظومه ای است پارسی که به سال <span class=\"hlight\" dir=\"rtl\">٩٥٥</span> هَ . ق . در سفر روم گفته است .<br /></font></div>'),
(175228, 'طالبی', '<span class=\"hlight\">طالبی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِ) قسمی خربزه ٔ پیشرس شیرین و لطیف که درون سبز، یا زرد دارد. نوعی گرمک از جنسی شیرین تر و پرآب تر، و آن به اواخر بهار و اوایل تابستان، یک ماه و نیم الی دو ماه پیش از خربزه رسد.<br /></font></div>'),
(175229, 'طالبی', '<span class=\"hlight\">طالبی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ )اسماعیل بن یوسف بن ابراهیم بن عبداﷲبن حسن بن علی بن ابیطالب، یکی از کسانی است که بمخالفت با خلفا برخاسته و به انقلاب دست یازیده است . وی به سال <span class=\"hlight\" dir=\"rtl\">٢٥١</span> هَ . ق . در مکه قیام کرد و بر آن شهر استیلا یافت و والی آن را براند و آنگاه به مدینه لشکر کشید و عامل آن متواری شد، سپس به مکه بازگشت و بعد به جده رفت و اموال بازرگانان را از آنان بازگرفت، و مردم بسبب او دچار رنجها شدند تا درگذشت . (از الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>).<br /></font></div>'),
(175230, 'طالبی', '<span class=\"hlight\">طالبی .</span> <font color=\"DarkGreen\"><b>[ ل ِ]</font></b> (اِخ ) حسین بن علی بن حسن بن حسن بن علی بن ابیطالب . از سادات بزرگوار و دلاور است . وی نزد مهدی عباسی آمد و مهدی چهل هزار دینار به او بخشید، ولی طالبی همه ٔ آن مبلغ را در بغداد و کوفه به مردم بذل و بخشش کرد. آنگاه از هادی رفتاری دید که مایه ٔ خشم او شد و از این رو به مخالفت با وی برخاست و در مدینه خروج کرد ومردم درباره ٔ اینکه کتاب و سنت مخصوص مرتضی از خاندان محمد است با او بیعت بستند، هادی در نتیجه ٔ این قیام تنی چند از سرداران لشکر خویش را بکشتن او مأمور کرد و آنان با وی جنگیدند و وی را به قتل رسانیدند(<span class=\"hlight\" dir=\"rtl\">١٦٩</span> هَ . ق .) و سر او را نزد هادی بردند، ولی هادی محزون و متأسف گردید. (از الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٣</span>).<br /></font></div>'),
(175231, 'طالبی', '<span class=\"hlight\">طالبی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) یحیی بن عمربن یحیی بن زیدبن علی بن حسین السبط. از کسانی است که به انقلاب دست یازیده و به مخالفت با خلفا برخاسته است . در سال <span class=\"hlight\" dir=\"rtl\">٢٣٥</span> هَ . ق . با متوکل عباسی بستیز برخاست و گروهی را گرد خویش فراهم آورد، ولی متوکل او را بگرفت و زندانی کرد و شکنجه داد. از این رو مدتی آرام گرفت، اما پس از چندی در روزگارالمستعین باﷲ در کوفه قیام کرد و کلیه ٔ اموال بیت المال را تصرف کرد و فرمان داد زندانها را باز کردند و زندانیان را آزاد ساختند. وی مردم را بدوستی خاندان محمد دعوت کرد و مردم بیعت او را پذیرفتند آنگاه لشکری به نبرد با وی از جانب خلیفه گسیل شد و طالبی با آنان پیکار کرد و بر آنها ظفر یافت، در نتیجه کارش بالا گرفت و نیرومند شد. سپس سپاه دیگری را بسوی او فرستادند و طالبی با آنان بجنگ پرداخت و در «شاهی » نزدیک کوفه جنگی بزرگ روی داد، و لشکریان طالبی منهزم شدند و گروهی قلیل باقی ماندند و وی کشته شد. طالبی مردی نیک سیرت و دیندار بود و بسیاری از شاعران در رثای او اشعاری سرودند. (از الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥٣</span>).<br /></font></div>'),
(175232, 'طالبی', '<span class=\"hlight\">طالبی .</span> <font color=\"DarkGreen\"><b>[ ل ِ]</font></b> (اِخ ) ابوالحسن علی بن زیدبن عیسی بن زیدبن عبداﷲبن محمدبن عقیل بن ابی طالب الطالبی العقیلی الادیب الشافعی . حافظ ابوعبداﷲ الحاکم در تاریخ نیشابور نام او را آورده و گفته که : ابوالحسن عقیلی ادیب، در پایان زندگانی در رستاق بُست نیشابور سکونت گزید، و در مکه از علی بن عبدالعزیز کتابها استماع کرد، از اقران خودنیز سماع دارد، اما بدان اکتفا نکرده، و ابی الا ان یرتقی الی قوم لعل بعضهم مات قبل ان یولد. المختصر رادر بُست و نیشابور نزد ابراهیم مزنی خواند، وی از جماعتی روایت کرده که پیش از مزنی از دنیا رفته اند. در سال <span class=\"hlight\" dir=\"rtl\">٣٣٧</span> هَ . ق . ما از او <font color=\"DarkGreen\"><b>[ مطالبی فراگرفته ]</font></b> و نوشتیم . و در همین سال بطرثیث (ترشیز) رفت . و در پایان همین سال (<span class=\"hlight\" dir=\"rtl\">٣٣٧</span> هَ . ق .) درگذشت . (انساب سمعانی ).<br /></font></div>'),
(175233, 'طالبی', '<span class=\"hlight\">طالبی .</span> <font color=\"DarkGreen\"><b>[ل ِ ]</font></b> (اِخ ) دهی است از دهستان سرولایت بخش سرولایت، شهرستان نیشابور در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی جنوب باختری چکنه ٔ بالا.کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">٦٩١</span> تن سکنه . آب آن از قنات محصول آن غلات و تریاک . شغل اهالی زراعت و کرباس بافی . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175234, 'طالبی', '<span class=\"hlight\">طالبی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) دهی است از دهستان نهارجانات بخش حومه ٔ شهرستان بیرجند. در <span class=\"hlight\" dir=\"rtl\">٦٨</span>هزارگزی جنوب خاوری بیرجند. دامنه و معتدل با <span class=\"hlight\" dir=\"rtl\">١١٩</span> تن سکنه . آب آن از قنات . محصول آن غلات و لبنیات . شغل اهالی زراعت و مالداری و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175235, 'طالبین', '<span class=\"hlight\">طالبین .</span> <font color=\"DarkGreen\"><b>[ ل ِ]</font></b> (ع ص، اِ) ج ِ طالب در حالت نصب و جر. جویندگان .<br /></font></div>'),
(175236, 'طالبیون', '<span class=\"hlight\">طالبیون .</span> <font color=\"DarkGreen\"><b>[ ل ِ بی یو ]</font></b> (ع اِ) جمع طالبی در حالت رفعی . رجوع به طالبی شود.<br /></font></div>'),
(175237, 'طالبیین', '<span class=\"hlight\">طالبیین .</span> <font color=\"DarkGreen\"><b>[ ل ِ بی یی ]</font></b> (ع اِ) جمع طالبی در حالت نصبی و جری . رجوع به طالبی شود.<br /></font></div>'),
(175238, 'طالة', '<span class=\"hlight\">طالة.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ع اِ) ماده خر. (منتهی الارب ).<br /></font></div>'),
(175239, 'طالح', '<span class=\"hlight\">طالح .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) ضد صالح . و فی الحدیث : لولا الصالحون لهلک الطالحون . ج، طُلَّح . (منتهی الارب ). ج، طالحون و طالحین . مرد بدکردار. (غیاث اللغات ). تبهکار. بدکار. فاسد. بدمرد. (زمخشری ). <BR><font color=\"Blue\">◄</font> بی سامانکار. ج، طُلَحاء. (ربنجنی ). مرد بیسامان . (مجمل اللغة) (تفلیسی ) (دهار) (دستور اللغه ٔ ادیب نطنزی ) <span class=\"hlight\">:</span> <br />صحبت صالح ترا صالح کند<br />صحبت طالح تراطالح کند.<br /> <font color=\"Red\"> مولوی .</font><br />صالح وطالح بصورت مشتبه <br />دیده بگشا بو که گردی منتبه .<br /> <font color=\"Red\">مولوی .</font><br />دختری خواهم ز نسل صالحی <br />نی ز نسل پادشاهی طالحی .<br /> <font color=\"Red\">مولوی .</font><br />صالح و طالح متاع خویش فروشند <br />تا که قبول افتد و چه در نظر آید؟<br /> <font color=\"Red\">حافظ.</font><br /><BR><font color=\"Blue\">◄</font> شترماده ٔ مانده . (منتهی الارب ).<br /></font></div>'),
(175240, 'طالح', '<span class=\"hlight\">طالح .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) نام پیشین ایستگاه شماره ٔ <span class=\"hlight\" dir=\"rtl\">١٥</span> راه آهن شمال بوده است که فرهنگستان آن را به «تاله » تبدیل کرده است . (لغات فرهنگستان <span class=\"hlight\" dir=\"rtl\">١٩</span>، <span class=\"hlight\" dir=\"rtl\">١٣١٨</span> هَ . ش .).<br /></font></div>'),
(175241, 'طالحشقوق', '<span class=\"hlight\">طالحشقوق .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) بقلة الیهودیة. خس کاذب . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩</span>). گیاهی است که معمولاً یکسال عمر میکند و گاهی هم بیشتر دوام میکند. برگهای آن در دو طرف شاخه میروید ولی کاملاً روبروی هم قرار ندارند. گلهای آن یکنوع گل مرکب و زردرنگ است . در حدود سی نوع از این گیاه در دنیا شناخته شده است . وقتی آن را خرد و ریزریز کنند شیره ٔ سفیدرنگی از آن خارج میشود، این گیاه به سرعت نمو کرده و زیادمیشود خوک و خرگوش با رغبت آن را میخورند و برگهای جوان و تازه ٔ آن را بعنوان «سالاد» استعمال میکنند.<br /></font></div>'),
(175242, 'طالحون', '<span class=\"hlight\">طالحون .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص، اِ) ج ِ طالح در حالت رفعی . بدکاران . تبهکاران . بدکرداران . و رجوع به طالح شود.<br /></font></div>'),
(175243, 'طالحین', '<span class=\"hlight\">طالحین .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص، اِ) ج َ طالح در حالت نصب و جر. بدکاران . تبهکاران . بدکرداران . و رجوع به طالح شود.<br /></font></div>'),
(175244, 'طالخونچه', '<span class=\"hlight\">طالخونچه .</span> <font color=\"DarkGreen\"><b>[ چ َ ]</font></b> (اِخ ) قصبه ای از دهستان سمیرم پائین بخش حومه ٔ شهرستان شهرضا، در <span class=\"hlight\" dir=\"rtl\">٤٠</span>هزارگزی شمال باختری شهرضا. متصل براه طالخونچه به شهرضا. جلگه و معتدل با <span class=\"hlight\" dir=\"rtl\">٥٧١٤</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و تریاک و پنبه . شغل اهالی زراعت و گله داری . راه آن ماشین رو است . درمانگاه و در حدود <span class=\"hlight\" dir=\"rtl\">٥٠</span> باب دکان و دبستان دارد. خانه های این آبادی بیشتر بصورت قلاع ساخته شده . صادرات پنبه ٔ این آبادی قابل ملاحظه میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>). در بعضی لهجه ها آن را طالخانچه گویند.<br /></font></div>'),
(175245, 'طالس', '<span class=\"hlight\">طالس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) به یونانی حلبة است . (فهرست مخزن الادویه ).<br /></font></div>'),
(175246, 'طالس', '<span class=\"hlight\">طالس .</span> <font color=\"DarkGreen\"><b>[ ل ُ ]</font></b> (اِخ ) قریه ای است به شیروان .<br /></font></div>'),
(175247, 'طالس', '<span class=\"hlight\">طالس .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ملطی . رجوع به «ثالس » شود. فیلسوف و ریاضیدان معروف یونانی، متولد در شهر ملطیه . و رجوع به ایران باستان ص <span class=\"hlight\" dir=\"rtl\">٢٧٥</span>، <span class=\"hlight\" dir=\"rtl\">١٩٨</span>، <span class=\"hlight\" dir=\"rtl\">٣٨٠</span> وتاریخ ادبیات ایران ترجمه ٔ رشید یاسمی ص <span class=\"hlight\" dir=\"rtl\">١٤٤</span> شود.<br /></font></div>'),
(175248, 'طالسان', '<span class=\"hlight\">طالسان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (معرب، اِ) طیلسان . چادر. (منتهی الارب ). در حاشیه ٔ المعرب جوالیقی آمده است که طیلسان را طیلس و طالسان هم گویند (به کسر لام در طالسان ) و در المعیار وادی شیر آمده که کلمه ٔ طیلسان معرب «تالسان » به کسر لام است، و صاحب المعیار کلمه ٔ طالسان یا طیلسان را چنین تفسیر کرده است : «جامه ای است که آن را بر کتف پوشند.» و هم گوید: «جامه ای است که همه ٔ بدن را فرامی گیرد، برای پوشیدن آن را بافند، و خالی از برش و خیاطی است ». وادی شیر گوید: «عبای مدوری است برنگ سبز که قسمت فرودین ندارد. پود آن از پشم است، خواص علما و مشایخ آن را پوشند، و آن از لباسهای عجمان است ». (المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٧</span>). و صاحب منتهی الارب ذیل طیلسان آرد: کلمه ٔ مزبورمعرب تالشان است . و رجوع به طیلسان و تالشان شود.<br /></font></div>'),
(175249, 'طالسفر', '<span class=\"hlight\">طالسفر.</span> <font color=\"DarkGreen\"><b>[ ل ِ ف َ ]</font></b> (معرب، اِ) بسباسه . دارکیسه . ماقر. لسان العصافیر و گویند برگ زیتون هندی است . و رجوع به طالیسفر شود.<br /></font></div>'),
(175250, 'طالش', '<span class=\"hlight\">طالش .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ )طایفه ای از مردم گیلان . ج، طوالش . صاحب برهان ذیل «تالش » آرد: قومی باشند از مردم گیلان و در حاشیه ٔ آن بقلم دکتر معین چنین است : تالش بقول بعضی مبدل و محرف «کادوس » است و آن قومی بود که در زمان باستان بس انبوه بودند و در کوهستان شمالی ایران نشیمن داشتند و چون بارها به گردنکشی برخاستند و با پادشاهان هخامنشی از در نافرمانی درآمدند از اینجا نام ایشان در تاریخها آمده و امروز مترجمان کادوش را که تلفظ صحیح آن است «کادوس » نویسند. جایگاهی که برای کادوشان در تاریخها یاد کرده اند امروز منطبق با جایگاه تالشان میباشد. رجوع کنید به مقالات کسروی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span> و نامهای شهرها و دیه ها تألیف وی دفتر یکم و رجوع به تاریخ زندیه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨</span> تألیف دکتر هدایتی و طالش دولاب شود.<br /></font></div>'),
(175251, 'طالش', '<span class=\"hlight\">طالش .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) کوه طالش . کوههای طالش بموازات ساحل بحر خزر تا ماسوله امتداد یافته . ارتفاع آن کمتر از قراجه داغ ولی اهمیت جغرافیائیش بیشتر است زیرا که دامنه ٔ آن مستقیماً در بحر خزر فرورفته و فقط حاشیه ٔ باریک و سراشیبی تشکیل داده و هیچ رودی آن را قطع نمیکند. و مانند سدی ما بین فلات آذربایجان و بحر خزر میباشد، و دارای جنگلهای انبوه است، کوههای طالش خط اتصال رشته های درهم و آتش فشانی کوههای نوح و سبلان و رشته ٔ منظم البرز میباشد، و امتداد آن برخلاف کوههای مزبور، شمالی و جنوبی است . مرتفعترین قله ٔ آن در شمال ماسوله، در حوالی باجیلان <span class=\"hlight\" dir=\"rtl\">٢/٤٠٢</span> متر ارتفاع دارد. و کرانه ٔ قیرچم فلات آذربایجان را به دریا متصل مینماید. (جغرافی کیهان ص <span class=\"hlight\" dir=\"rtl\">٣٤</span> ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(175252, 'طالش', '<span class=\"hlight\">طالش .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) رود طالش . رودخانه ای است که ببحر خزر میریزد و درآن رود صید ماهی میشود. (جغرافی کیهان ص <span class=\"hlight\" dir=\"rtl\">٦٧</span> ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(175253, 'طالش دولاب', '<span class=\"hlight\">طالش دولاب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) نام ناحیه ای است در گیلان . مطابق تقسیماتی که در جغرافی کیهان برای گیلان شده، هفدهمین ناحیه محسوب است . از شمال محدود است به اسالم و از مغرب به خلخال، و از جنوب به شاندرمن و گسکر طول آن <span class=\"hlight\" dir=\"rtl\">٤٣١</span> و عرض آن <span class=\"hlight\" dir=\"rtl\">٣٠</span> کیلومتر، و به دو ناحیه تقسیم میشود: اول گل دولاب که دارای اراضی پست است، دوم ناحیه ٔ کوهستانی که آن را طالش دولاب میگویند. آب و هوای قسمت پست آن ناسالم و مهمترین قراء آن پونل است که بین چاپ سرا و شفارود واقع شده، و معدن سنگی دارد، و بواسطه ٔ راه آهن کوچکی به مرداب متصل میشود، و سنگهائی که برای ساختن بندر انزلی لازم بوده از آن معدن حمل شده، جمعیت طالش دولاب در حدود <span class=\"hlight\" dir=\"rtl\">١٥٠٠٠</span> نفر و تقسیمات جزء آن از این قرار است : آب کنار، گیله دولاب، قشلاق طالش دولاب، ییلاق طالش دولاب . و بعلاوه دارای قراء متعدد میباشد. (جغرافی کیهان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٨</span>) در طالش دولاب جنگلهای قابل بهره برداری بسیار است . (جغرافی کیهان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٨</span>). در اطراف طالش دولاب معدن نفط یافت میشود. (همان کتاب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٨</span>). خطی از راه آهن از کنار مرداب از خاک وزان شروع شده و پس از طی دو فرسخ از جنگل به خاک طالش دولاب میرسد، فقطاستفاده ای که از این راه میشده، حمل سنگ از کوه به بندر انزلی، و گاهی هم حمل زغال سنگ و هیزم و برنج بوده، فعلاً این راه متروک، و دائر کردن آن مستلزم مخارج زیادی است . (جغرافی کیهان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٧٠</span>). بعضی تصور می کنند که «کادوسیان » نیاکان طالشهای کنونی بوده اند و کادوس مصحف، یا یونانی شده ٔ تالوش است که در قرون بعد تالش یا طالش شده . مدرکی عجالةً برای تأیید این حدس نداریم . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢٩</span>). در عهدنامه ٔ گلستان که در سال <span class=\"hlight\" dir=\"rtl\">١٢٢٨</span> هَ . ق . برای تعیین حدود سرحدی بین دولتین ایران و روس منعقد گردید، طالش که جزء ایران بود، به تصرف روسها درآمد. سپس در سال <span class=\"hlight\" dir=\"rtl\">١٢٤٣</span> هَ . ق . عهدنامه ٔ ترکمانچای انعقاد یافته و عهدنامه ٔگلستان فسخ شد که تا این تاریخ نیز عهدنامه ٔ ترکمانچای مجری است . (جغرافی کیهان ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٢٢</span>-<span class=\"hlight\" dir=\"rtl\">٢١</span>). نام یکی از بلوک پنجگانه ٔ شهرستان خمسه ٔ طوالش است . این بلوک فعلاً به سه دهستان میانده، بره سر، خشابر تقسیم شده است . طالش دولاب از شمال به دهستان اسالم از جنوب به شاندرمن و از خاور به گیل دولاب و از باختر به کوهستان بین خلخال و دریای خزر محدود است . سکنه ٔ طالش دولاب مسلمان و سنی اند و زبان مادری آنها طالشی و عموماً به ترکی آشنا هستند. قسمت عمده ٔ قراء طالش دولاب از رودخانه ٔ شفارود، دنیاچال و چاف رود مشروب میگردد. محل ییلاقی آنها سرچشمه ٔ رودهای مذکور میباشد. راه شوسه ٔ بندر انزلی به آستارا از وسط دهستان عبور میکند شغل عمده ٔ سکنه زراعت و گله داری است . تابستان اکثر سکنه به ییلاق میروند... (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(175254, 'طالش محله', '<span class=\"hlight\">طالش محله .</span> <font color=\"DarkGreen\"><b>[ ل ِ م َ ح َل ْ ل َ ]</font></b> (اِخ ) دهی از دهستان زوار شهرستان شهسوار. در <span class=\"hlight\" dir=\"rtl\">١٤</span>هزارگزی جنوب خاوری شهسوار و <span class=\"hlight\" dir=\"rtl\">٣/٥</span>هزارگزی جنوب شوسه ٔ شهسوار به چالوس . دشت معتدل و مرطوب و مالاریائی با <span class=\"hlight\" dir=\"rtl\">١٧٠</span> تن سکنه . آب آن از رودخانه ٔزوار. محصول عمده ٔ آن مرکبات و برنج . شغل اهالی زراعت است . راه آن فرعی بشوسه . <span class=\"hlight\" dir=\"rtl\">٥</span> باب دکان و شعبه ٔ قطع اشجار جنگل دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175255, 'طالش محله', '<span class=\"hlight\">طالش محله .</span> <font color=\"DarkGreen\"><b>[ ل ِ م َ ح َل ْ ل َ ]</font></b> (اِخ ) دهی است از دهستان گیلخواران بخش مرکزی شهرستان شاهی . در <span class=\"hlight\" dir=\"rtl\">٨</span>هزارگزی شمال خاوری جویبار. دشت، معتدل و مرطوب و مالاریائی . با <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن سکنه . آب آن از چاه . محصول آنجا برنج و پنبه و غلات و کنجد و صیفی . شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175256, 'طالش محله', '<span class=\"hlight\">طالش محله .</span> <font color=\"DarkGreen\"><b>[ ل ِ م َح َل ْ ل َ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش رامسرشهرستان شهسوار. در <span class=\"hlight\" dir=\"rtl\">٣</span>هزارگزی خاور رامسر و یکهزارگزی جنوب شوسه ٔ رامسر به شهسوار. دشت معتدل و مرطوب و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٧٠</span> تن سکنه . آب آن از نهر چرمر و چاه . محصول آنجا برنج و مرکبات و چای . شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175257, 'طالش محله', '<span class=\"hlight\">طالش محله .</span> <font color=\"DarkGreen\"><b>[ ل ِ م َ ح َل ْ ل َ ]</font></b> (اِخ ) نام محلی کنار راه رامسر و لنگرود میان دریا و کیاکلا در <span class=\"hlight\" dir=\"rtl\">٥٢٦٤٠٠</span> متری تهران . از نواحی نشتا (تنکابن ) محسوب میشود. (سفرنامه ٔ رابینو ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span>). دهی جزء دهستان مرکزی بخش لنگرود شهرستان لاهیجان . در چهارهزارگزی جنوب باختری لنگرود. نزدیک راه شوسه ٔ لنگرود به لاهیجان . کوهستانی، معتدل مرطوب و مالاریائی . با<span class=\"hlight\" dir=\"rtl\">٣٤٠</span> تن سکنه . آب آن از چشمه . محصول آنجا برنج، چای، ابریشم و صیفی . شغل اهلی زراعت و نان برنجی پزی و پارچه ٔ ابریشمی بافی . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(175258, 'طالش کندی', '<span class=\"hlight\">طالش کندی .</span> <font color=\"DarkGreen\"><b>[ ل ِ »َ ]</font></b> (اِخ ) دهی است ازدهستان چهاراویماق بخش قره آغاج شهرستان مراغه . در <span class=\"hlight\" dir=\"rtl\">٣٧</span>هزارگزی شمال خاوری قره آغاج، و <span class=\"hlight\" dir=\"rtl\">٢١</span>هزارگزی جنوب شوسه ٔ مراغه به میانه . کوهستانی . معتدل و مالاریائی . با <span class=\"hlight\" dir=\"rtl\">٨٩</span> تن سکنه . آب آن از چشمه سار. محصول آنجا غلات و نخودو بزرک . شغل اهالی زراعت، صنایع دستی جاجیم بافی و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(175259, 'طالشان', '<span class=\"hlight\">طالشان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) دهی است جزء دهستان حومه ٔ بخش مرکزی شهرستان رشت در چهارهزارگزی جنوب باختری رشت کنار راه شوسه ٔ لاکان . جلگه . معتدل مرطوب . مالاریائی . با <span class=\"hlight\" dir=\"rtl\">١٢٨</span> تن سکنه . آب آن از استخر. محصول آن برنج و چای . شغل اهالی زراعت و مکاری . راه آن مالرو است در فصل خشکی اتومبیل میرود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(175260, 'طالشان', '<span class=\"hlight\">طالشان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِ) تالشان . چادر. و آن اصل کلمه ٔ طیلسان است : طالسان . معرب است و اصله تالشان . (منتهی الارب ). رجوع به طالسان شود.<br /></font></div>'),
(175261, 'طالع', '<span class=\"hlight\">طالع.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) برآینده . (دهار) (غیاث اللغات ). صعودکننده . طلوع کننده . بازغ . شارق، مقابل غارب <span class=\"hlight\">:</span> <br />که من بحسن تو ماهی ندیده ام طالع<br />که من بقد تو سروی ندیده ام مایل .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) دراصطلاح احکامیان جزوی از منطقةالبروج که بر افق شرقی است، حین ولادت مولود یا سؤال سائل . برجی که هنگام ولادت یا وقت سؤال چیزی از افق شرقی نمودار باشد، و اثر هر طالع از بروج دوازده گانه در نحوست و سعادت علیحده است . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> بخت . اقبال . شانس . پیشانی . اختر <span class=\"hlight\">:</span> این زمستان طالع خوب نیست، که حکیمان این حکم کرده اند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٦٧٦</span>). خواجه احمد حسن برخاست و به جامه خانه رفت و تا نزدیک چاشتگاه همی ماند که طالعی نهاده بود. جاسوس فلک خلعت پوشیدن را. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٥٠</span>).<br />ز طالع زبون گشته این اخترم <br />ز سرگشته گردون روان برترم .<br /> <font color=\"Red\">فردوسی .</font><br />وگر طالع تیر فرخنده شیر<br />خداوند خورشید سعد دلیر<br />چو کرد اختر فرخ ایرج نگاه <br />کشف دید طالع خداوند ماه .<br /> <font color=\"Red\">فردوسی .</font><br />وزان پس چنان بُد که شاه اردوان <br />ز اخترشناسان روشن روان <br />بیاورد چندی بدرگاه خویش <br />همی بازجست اختر و راه خویش <br />سه روز اندر آن کار شد روزگار<br />نگه کرده شد طالع شهریار<br />چو گنجور بشنید آوازشان <br />سخن گفتن از طالع رازشان .<br /> <font color=\"Red\">فردوسی .</font><br />چنین رادی چنین آزاده مردی <br />ندانم بر چه طالع زاده مادر.<br /> <font color=\"Red\">فرخی .</font><br />بار خدای جهان خلیفه ٔ مسعود<br />نیکش مولود و نیک طالع مولود.<br /> <font color=\"Red\">منوچهری .</font><br />آن از پی آن نیست که تا نیست شود خلق <br />و آن هست عرض طالع عالم سرطان را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />نیست کس را گنه چو بخت مرا<br />طالعی آفریده حرمانیست .<br /> <font color=\"Red\">مسعودسعد.</font><br />امید بطالع است کز عمر<br />هیلاج بقا چنان ببینم .<br /> <font color=\"Red\">خاقانی .</font><br />کنون نگر که از این طالع نبهره فریب <br />برسم طالع خود واپس است رفتارم .<br /> <font color=\"Red\">خاقانی .</font><br />دی نقش زیاد طالع من <br />در زایچه ٔ فنات جویم .<br /> <font color=\"Red\">خاقانی .</font><br />سیف الحق افضل بن محمد که طالعش <br />دارد خلافة الحق در موضع سهام .<br /> <font color=\"Red\">خاقانی .</font><br />دیدم بطالع خود عشق آمد اختیارم <br />این روز نامرادی بر اختیار من چه .<br /> <font color=\"Red\">خاقانی .</font><br />گر چه از توسنی چو طالع ماست <br />ما کمند وفا دراندازیم .<br /> <font color=\"Red\">خاقانی .</font><br />خسته ام نیک از بد ایام خویش <br />طیره ام بر طالع بدرام خویش .<br /> <font color=\"Red\">خاقانی .</font><br />مرا یاران سپاس ایزد کنند امروز کز طالع<br />بنام ایزد دل یارم چنان آمد که من خواهم .<br /> <font color=\"Red\">خاقانی (دیوان چ عبدالرسولی ص <span class=\"hlight\" dir=\"rtl\">٨١٩</span>).</font><br />طالعش را شهسواری دان که بار هودجش <br />کوهه ٔ عرش معلا برنتابد بیش از این .<br /> <font color=\"Red\">خاقانی .</font><br />هست صدعیب طالعم را لیک <br />یک هنر دیده ام ز طالع خویش <br />من که خاقانیم نموداری <br />مختصر دیده ام ز طالع خویش <br />گر چه هر کوکبی سعادت بخش <br />برگذر دیده ام ز طالع خویش .<br /> <font color=\"Red\">خاقانی .</font><br />عقرب از طالع تبریز دریست <br />نه ز عقرب ضرری خواهم داشت .<br /> <font color=\"Red\">خاقانی .</font><br />هر که در طالعش قران افتاد<br />سایه ٔ او از او کنار کند.<br /> <font color=\"Red\">خاقانی .</font><br />طالعم از برت برون انداخت <br />گر بنالم برون تر اندازد.<br /> <font color=\"Red\">خاقانی .</font><br />موئی شدم که موی شکافم به تیر نطق <br />کآسیب طالعم هدف اضطرار کرد.<br /> <font color=\"Red\">خاقانی .</font><br />قلم بخت من شکسته سر است <br />موی در سر به طالع هنر است .<br /> <font color=\"Red\">خاقانی .</font><br />نسخه ٔ طالع و احکام بقاکاصل نداست <br />هم به کذاب سطرلاب نگر بازدهید.<br /> <font color=\"Red\">خاقانی .</font><br />فلک در طالعم شیری نموده ست <br />ولیکن شیر پشمینم چه سود است ؟<br /> <font color=\"Red\">نظامی .</font><br />طالع جوزا که کمر بسته بود<br />از ورم رگ زدنت رسته بود.<br /> <font color=\"Red\">نظامی .</font><br />بختور از طالع جوزا برآی <br />جوزشکن آنگه و بخت آزمای .<br /> <font color=\"Red\">نظامی .</font><br />ولدالزناست حاسد منم آنکه طالع من <br />ولدالزناکش آمد چو ستاره ٔ یمانی .<br /> <font color=\"Red\">نظامی .</font><br />نماند جاودان طالع به یک خوی <br />نباشد آب دایم در یکی جوی .<br /> <font color=\"Red\">نظامی .</font><br />حساب طالع از اقبال کردش <br />بعون طالع استقبال کردش .<br /> <font color=\"Red\">نظامی .</font><br />در سخا و سخن چه می پیچم <br />کار بر طالع است و من هیچم .<br /> <font color=\"Red\">نظامی .</font><br />طالع کارت بزبونی در است <br />دل به کمی غم بفزونی در است .<br /> <font color=\"Red\">نظامی .</font><br />چو طالع موکب دولت روان کرد<br />سعادت روی در روی جهان کرد.<br /><font color=\"Red\">نظامی .</font><br />بدان طالع که پشتش را قوی کرد<br />پناهش بارگاه خسروی کرد.<br /> <font color=\"Red\">نظامی .</font><br />در طالع من نیست که نزدیک تو باشم <br />می گویمت از دور دعا گر برسانند.<br /> <font color=\"Red\">سعدی .</font><br />چو طالع نباشد هنر هیچ نیست .<br /> <font color=\"Red\">عبید زاکانی .</font><br />طالع اگر مدد کند دامنش آورم به کف <br />گر بکشم زهی طرب ور بکشد زهی شرف .<br /> <font color=\"Red\">حافظ.</font><br />نه در غربت دلم شاد است نه روی اندر وطن دارم <br />الهی بخت برگردد از این طالعکه من دارم .<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بیطالع</span> ؛ بی اقبال . آنکه بخت ناسازگار دارد <span class=\"hlight\">:</span> <br />ندید دشمن بیطالعم هر آنچه بخواست <br />که دوست بر سر لطف آمده ست و دلداری .<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> یکی از اوتاداربعه ٔ منجمین . (مفاتیح خوارزمی ). <BR><font color=\"Blue\">◄</font> (اصطلاح نجوم ) برجی که از مشرق طالع شود، مقابل غارب : طالع آن بود که اندر وقت به افق مشرق آمده باشد از منطقة البروج . برج را برج طالع خوانند و درجه را درجه ٔ طالع (التفهیم ). <BR><font color=\"Blue\">◄</font> ماه نو. <BR><font color=\"Blue\">◄</font> صبح کاذب . <BR><font color=\"Blue\">◄</font> تیری که پس نشانه افتد. (منتهی الارب ).<br /></font></div>'),
(175262, 'طالع', '<span class=\"hlight\">طالع.</span> <font color=\"DarkGreen\"><b>[ ل ِ]</font></b> (اِخ ) دهی است از دهستان راستوبی بخش سوادکوه شهرستان شاهی در <span class=\"hlight\" dir=\"rtl\">٧</span>هزارگزی جنوب ایستگاه پل سفید و یکهزارگزی شوسه ٔ شاهی تهران . کوهستانی و معتدل و مرطوب و مالاریائی . با<span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه . آب آن از چشمه و رودخانه ٔ تالار. محصول آن برنج و غلات و صیفی . شغل اهالی زراعت و تهیه ٔ زغال . صنایع دستی زنان شال و کرباس بافی و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175263, 'طالع بد', '<span class=\"hlight\">طالع بد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ِ ب َ ]</font></b> (ترکیب وصفی، اِ مرکب ) بخت بد. طالع نحس . طالع نگون . بخت نامیمون <span class=\"hlight\">:</span> <br />طالع بد بود و بداختر شدم <br />نامزد کوی قلندر شدم .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175264, 'طالع خجسته', '<span class=\"hlight\">طالع خجسته .</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ِ خ ُ ج َ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ترکیب وصفی ) خجسته طالع. بخت میمون . اقبال . طالع فیروز.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175265, 'طالع دون', '<span class=\"hlight\">طالع دون .</span> <font color=\"DarkGreen\"><b>[ ل ِع ِ ]</font></b> (ترکیب وصفی ) طالع نحس . طالعنگون . بخت بد <span class=\"hlight\">:</span> این چه بخت نگون است و طالع دون . (گلستان ).<br /></font></div>'),
(175266, 'طالع سعد', '<span class=\"hlight\">طالع سعد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ِ س َ ]</font></b> (ترکیب وصفی ) طالع مسعود. بخت فرخنده . طالع خجسته . اقبال . طالع مبارک و میمون <span class=\"hlight\">:</span> <br />زی طالع سعد و در اقبال خداوند<br />فخر بشر و بر سر عالم همه افسر.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(175267, 'طالع شدن', '<span class=\"hlight\">طالع شدن .</span> <font color=\"DarkGreen\"><b>[ ل ِ ش ُ دَ ]</font></b> (مص مرکب ) برآمدن . طلوع کردن . صبح طالع شدن ؛ دمیدن . (دستوراللغه ٔ ادیب نطنزی ). سرزدن آفتاب از پس کوه . برآمدن . تیغ زدن <span class=\"hlight\">:</span> <br />چون حمل ساقط شود میزان همی طالع شود<br />همچنان در دین از ایشان مردمی پیدا شود.<br /><font color=\"Red\">ناصرخسرو (دیوان چ تقوی ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).</font><br /></font></div>'),
(175268, 'طالع فرخنده', '<span class=\"hlight\">طالع فرخنده .</span> <font color=\"DarkGreen\"><b>[ ل ِ ف َخ ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ترکیب وصفی ) فرخنده طالع. طالع خجسته .طالع سعد و میمون . بخت فیروز. بخت نیک <span class=\"hlight\">:</span> <br />خرم آن فرخنده طالع را که چشم <br />بر چنان روی اوفتد هر بامداد.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(175269, 'طالع فیروز', '<span class=\"hlight\">طالع فیروز.</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ِ ]</font></b> (ترکیب وصفی ) طالع سعد. بخت مسعود. طالع خجسته . اقبال فرخ و میمون .<br /></font></div>'),
(175270, 'طالع مسعود', '<span class=\"hlight\">طالع مسعود.</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ِ م َ ]</font></b>(ترکیب وصفی ) بخت فرخنده . اختر فیروز. ستاره ٔ میمون . و رجوع به طالع میمون و طالع سعد شود <span class=\"hlight\">:</span> <br />رایت منصور او را فتح باشد پیشرو<br />طالع مسعود او را بخت باشد پیشکار.<br /> <font color=\"Red\">منوچهری .</font><br />امروز کزو طالع مسعود شده ستم <br />از دهر کی اندیشم وز بیم زوالش .<br /> <font color=\"Red\">ناصرخسرو (دیوان چ مینوی ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span>).</font><br />قاضی صدر ششم را طالع مسعود تو<br />مقتدای فتوی صاحبقرانی آمده .<br /> <font color=\"Red\">سنائی .</font><br />چون فلکت طالع مسعود داد<br />عاقبت کار تو محمود باد.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175271, 'طالع من الکبد', '<span class=\"hlight\">طالع من الکبد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ُ م ِ نَل ْ ک َ ب ِ ]</font></b> (ع اِ مرکب ) الَ ... . یا طالع؛ نام رگی است بزرگ از جانب محدب کبد رسته . آن رگ که از جانب محدب جگر رسته است <span class=\"hlight\">:</span> پس بدان رگ بزرگ که از جانب محدب رسته است برآید، و آن را بتازی الطالع من الکبد گویند. (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(175272, 'طالع میمون', '<span class=\"hlight\">طالع میمون .</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ِ م َ ]</font></b> (ترکیب وصفی ) طالع سعد. طالع مسعود. طالع مبارک . بخت نیک . اختر فیروز <span class=\"hlight\">:</span> <br />همی فزونی جوید آواره بر افلاک <br />که تو بطالع میمون بدو نهادی روی .<br /> <font color=\"Red\">شهید بلخی یا پیروز مشرقی .</font><br />با تو پیاده خواند جهان آفتاب را<br />تا تو شدی بطالع میمون سوار ملک .<br /> <font color=\"Red\">مسعودسعد.</font><br />و آنگاه مثال داد تا روزی مسعود و طالعی میمون برای حرکت او تعیین کردند. (کلیله و دمنه ).<br />امشبم طالع میمون و بخت همایون بدین بقعه رهبری کرد. (گلستان ).<br />همه دعوی طالع میمونش <br />در معانی بدیع برهان باد.<br /><font color=\"Red\">؟</font><br /></font></div>'),
(175273, 'طالع نحس', '<span class=\"hlight\">طالع نحس .</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ِ ن َ ]</font></b> (ترکیب وصفی ) بخت بد. طالع نامیمون . اقبال نامبارک <span class=\"hlight\">:</span> <br />چرخست و لیکن نه درو طالع نحس است <br />خلد است و لیکن نه درو جوی عقار است .<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(175274, 'طالع نگون', '<span class=\"hlight\">طالع نگون .</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ِ ن ِ ]</font></b> (ترکیب وصفی ) نگون طالع. بخت بد.ستاره ٔ نحس . اقبال ناسازگار. طالع نحس <span class=\"hlight\">:</span> <br />ای طالع نگون من ای کجرو حرون <br />ای نحس بی سعادت وی خوف بی رجا.<br /> <font color=\"Red\">مسعودسعد.</font><br />گل آلوده ای راه مسجدگرفت <br />ز بخت نگون طالع اندرشگفت .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(175275, 'طالع همایون', '<span class=\"hlight\">طالع همایون .</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ِ هَُ ]</font></b> (ترکیب وصفی ) طالع خجسته . بخت فرخنده . اختر میمون . طالع مبارک <span class=\"hlight\">:</span> <br />ز مشرق سرکوی آفتاب طلعت تو<br />اگر طلوع کند طالعم همایون است .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(175276, 'طالع پیروز', '<span class=\"hlight\">طالع پیروز.</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ِ ]</font></b> (ترکیب وصفی ) رجوع به طالع فیروز شود.<br /></font></div>'),
(175277, 'طالعور', '<span class=\"hlight\">طالعور.</span> <font color=\"DarkGreen\"><b>[ ل ِ وَ ]</font></b> (ص مرکب ) خوشبخت . بااقبال . بختور. و رجوع به طالعمند شود.<br /></font></div>'),
(175278, 'طالعی', '<span class=\"hlight\">طالعی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ی ی ]</font></b> (اِخ ) از شعراء ترکیه ٔ عصر سلطان سلیم، و با نجاتی و صنعی که آنان نیزاز شعراء معاصر وی بوده اند، مشاعره و بذله گوئی داشته، وی را دیوانی است به ترکی . (قاموس الاعلام ترکی ).<br /></font></div>'),
(175279, 'طالعین', '<span class=\"hlight\">طالعین .</span> <font color=\"DarkGreen\"><b>[ ل ِ ع َ ]</font></b> (ع ص، اِ) تثنیه ٔ طالع <span class=\"hlight\">:</span> این هر دو رگ را که بدین هر دو گرده آمده است <font color=\"DarkGreen\"><b>[ از جگر ]</font></b>، الطالعین گویند. (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(175280, 'طالق', '<span class=\"hlight\">طالق .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) زن رها شده از قید نکاح . (منتهی الارب ). زن طلاق داده . طلاق گرفته . مُطلّقه . زن ِ آزاد شده از بندِ زوجیت . <BR><font color=\"Blue\">◄</font> صاحب رهائی . رَها. (غیاث اللغات ). یَله . آزاد. <BR><font color=\"Blue\">◄</font> طلاق گوینده . طلاق دهنده . ج، طُلَّق . <BR><font color=\"Blue\">◄</font> ناقةٌ طالق ؛ ناقه ٔ بی مهار بر سر خود گذاشته . (منتهی الارب ). لازمام علیها. (مهذب الاسماء). ماده شتری که رها کرده اند تا هر جای خواهد چَرَد. <BR><font color=\"Blue\">◄</font> نَعجةٌ طاِلق ٌ؛ میش بر سر خود گذاشته . میشی که رها کرده اند تا هر جای خواهدچرد. <BR><font color=\"Blue\">◄</font> ناقه ٔ متوجه به طرف ِ آب . (منتهی الارب ). اشتری روی به آبشخور نهاده . (مهذب الاسماء).<br /></font></div>'),
(175281, 'طالقان', '<span class=\"hlight\">طالقان .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) شهری است و یا شهرستانی است میان قزوین و ابهر، و از آنجاست صاحب اسماعیل بن عباد. (منتهی الارب ). طالقان ولایت سردسیر است، در شرقی قزوین . طولش از جزایر خالدات فه . مه و عرض از خطّ استوا، لوی . در کوهستان افتاده است، و کلاتها بوده، و دیه های معتبر کمتر باشد، حاصل آنجا غلّه و اندکی جوز و میوه بود، و مردم آنجا دعوی مذهب سنت کنند، اما ببواطنه مایلتر باشند. ولایت سرانرود و جرود و قهپایه وکن و کرخ از توابع آنجاست، و در این ولایت دیه ها معتبر بود، حقوق دیوانی طالقان با این ولایت یک تومان است . (نزهةالقلوب چ لیدن ص <span class=\"hlight\" dir=\"rtl\">٦٥</span> مقاله ٔ <span class=\"hlight\" dir=\"rtl\">٣</span>). شهرکی است ازجبال، از ری به دیلمان نزدیک . (حدودالعالم ). پنجمین ناحیه است از ایالت تهران، از شمال و مشرق محدود است به مازندران، از جنوب به ساوجبلاغ و از مغرب به قزوین . طالقان ناحیه ای است کوهستانی، و قسمت مهم آن در دره ٔ شاهرود واقع شده، و این رود از مغرب گردنه ٔ کندوان سرچشمه گرفته بطرف مشرق جاری است، و اغلب قرای طالقان در کنار شعب آن واقعند، قرای متعدد طالقان که همه بخوشی آب و هوا معروفند، عبارتند از: شهرک، نسا، و محمودآباد. عده ٔ قرای آن <span class=\"hlight\" dir=\"rtl\">٧٨</span> و جمعیت آن قریب <span class=\"hlight\" dir=\"rtl\">٢٤٣٠٠</span> نفر، و اغلب قریه های آن قدیمی و اشخاص بزرگی منسوب به آن قراء میباشند. (جغرافیای سیاسی کیهان صص <span class=\"hlight\" dir=\"rtl\">٣٥٤</span> - <span class=\"hlight\" dir=\"rtl\">٣٥٥</span>). آب طالقان وارد بحر خزر میشود. (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٣١١</span>). طالقان دارای معدن زغال سنگ است . و رجوع به نزهةالقلوب (چ لیدن مقاله ٔ <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> - <span class=\"hlight\" dir=\"rtl\">٢٢٢</span>) و الارشاد (چ سید جلال الدین تهرانی ص <span class=\"hlight\" dir=\"rtl\">٤</span>) و سفرنامه ٔ مازندران ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>، <span class=\"hlight\" dir=\"rtl\">٢١</span>، <span class=\"hlight\" dir=\"rtl\">٢٠</span>، <span class=\"hlight\" dir=\"rtl\">١٠٨</span>، <span class=\"hlight\" dir=\"rtl\">١١١</span>، <span class=\"hlight\" dir=\"rtl\">١٤٢</span> رابینو شود.<br /></font></div>'),
(175282, 'طالقان', '<span class=\"hlight\">طالقان .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) شهری است به خراسان بر حد میان طخارستان و ختلان، جائی است بر دامن کوه با کشت و برز بسیار.(حدودالعالم ). شهری است به خراسان بر سد حد گوزگانان است و از آن این پادشاهی است، شهری با نعمت بسیار است و از او نبیذ بسیار خیزد و نمد خیزد. (حدود العالم ). شهری است میان بلخ و مروالرود. از آن شهر است ابومحمد، محمودبن خداش الطالقانی . (منتهی الارب ) (آنندراج ). این شهر بین مروالرود و بلخ واقع، و میان این دو شهرستان سه روز یا سه منزل مسافت است، اصطخری گوید: بزرگترین شهرستان طخارستان طالقان میباشد. این شهرستان در زمین همواری واقع شده است و فاصله ٔ آن تا کوه یک تیر پرتاب است، نهری بزرگ و باغهای بسیار دارد، و به اندازه ٔ ثلث بلخ باشد، و بعد از طالقان و زوالین بزرگترین شهرستان طخارستان بشمار رود، جماعتی ازفضلاء از این خاک برخاسته اند، از آن جمله است ابومحمد، محمودبن خداش الطالقانی . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span>). طالقان از ولایت طخارستان است، و از اقلیم چهارم، طولش از جزایر خالدات، فا. و عرض از خط استوا، ک . له . شهر کوچک است اکثر مردم آنجا جولاه باشد، و در او غله و میوه بسیار است، و معمور و آبادان است و از آنجا تا مرو شش فرسنگ مسافت است . (نزهةالقلوب چ لیدن مقاله ٔ <span class=\"hlight\" dir=\"rtl\">٣</span>صص <span class=\"hlight\" dir=\"rtl\">١٧٩</span> - <span class=\"hlight\" dir=\"rtl\">١٥٦</span>). طالقان کرسی ولایت طخارستان، واقع دردومنزلی ولوالج و سه منزلی بدخشان است . (تاریخ مغول ). آقای اقبال در حاشیه ٔ کتاب مذکور توضیح داده اند: هنوز هم به این اسم باقی، و در مشرق قندز و بر سر راه فیض آباد واقع است . (تاریخ مغول عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>). چون یزدجرد بمرد، از پس او هیجده سال ابن هرمز برادر کهتر که پیش پدر بود ملک بگرفت . آن پسر مهتر از سیستان بسوی ملک هیاطله رفت، به غرجستان و طخارستان و بلخ، و خبر خویش بگفت که برادر کهتر ملک بگرفت، و حق من است و از وی سپاه خواست، ملک او را طالقان داد، و گرامی کرد، و لکن سپاه ندادش . (ترجمه ٔ طبری بلعمی ).<br />سوی طالقان آمد و مرورود<br />سپهرش همیداد گفتی درود.<br /> <font color=\"Red\">فردوسی .</font><br />دگر طالقان شهر تا فاریاب <br />همیدون ببخش اندرون اندرآب .<br /> <font color=\"Red\">فردوسی .</font><br />سوی طالقان آمد و مرورود<br />جهان پر شد از ناله ٔ نای و رود.<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٢٦</span> و التفهیم چ تهران ص <span class=\"hlight\" dir=\"rtl\">٣٣٥</span> و تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٠٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٠١</span>، <span class=\"hlight\" dir=\"rtl\">٥٤٤</span>، <span class=\"hlight\" dir=\"rtl\">٥٨٢</span> و جهانگشای جوینی چ لیدن ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٢</span>، <span class=\"hlight\" dir=\"rtl\">١٠٤</span>، <span class=\"hlight\" dir=\"rtl\">١٠٥</span>، <span class=\"hlight\" dir=\"rtl\">١٠٦</span>، <span class=\"hlight\" dir=\"rtl\">١١٩</span>، <span class=\"hlight\" dir=\"rtl\">١٣١</span>، <span class=\"hlight\" dir=\"rtl\">١٣٢</span>. و جهانگشای جوینی چ لیدن ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥١</span>، <span class=\"hlight\" dir=\"rtl\">٥٨</span>، <span class=\"hlight\" dir=\"rtl\">١٣٩</span>، <span class=\"hlight\" dir=\"rtl\">١٩٤</span>، <span class=\"hlight\" dir=\"rtl\">١٩٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> و ترجمه ٔ ایران در زمان ساسانیان رشید یاسمی صص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span> - <span class=\"hlight\" dir=\"rtl\">٢٠٤</span> وحبیب السیر چ <span class=\"hlight\" dir=\"rtl\">١</span> تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٤</span>، <span class=\"hlight\" dir=\"rtl\">٤٣٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٤٨</span>، <span class=\"hlight\" dir=\"rtl\">١٧١</span> و حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦</span>، <span class=\"hlight\" dir=\"rtl\">١٥</span>، <span class=\"hlight\" dir=\"rtl\">٢٦</span>، <span class=\"hlight\" dir=\"rtl\">١٢٧</span> و تاریخ مغول عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>، <span class=\"hlight\" dir=\"rtl\">٤٧</span>، <span class=\"hlight\" dir=\"rtl\">٤٨</span>، <span class=\"hlight\" dir=\"rtl\">٥٠</span>، <span class=\"hlight\" dir=\"rtl\">٥٧</span>، <span class=\"hlight\" dir=\"rtl\">٥٨</span>، <span class=\"hlight\" dir=\"rtl\">٦٢</span>، <span class=\"hlight\" dir=\"rtl\">٦٤</span>، <span class=\"hlight\" dir=\"rtl\">٧٣</span>، <span class=\"hlight\" dir=\"rtl\">١٧١</span>، <span class=\"hlight\" dir=\"rtl\">١٧٦</span> شود.<br /></font></div>'),
(175283, 'طالقان', '<span class=\"hlight\">طالقان .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) لقب پادشاهان «شهرک » از حدود ماوراءالنهر. بنابر روایت کریستنسن دانمارکی، سلاطین ممالکی که مجاور سرحدهای شرقی و شمالی ایران بوده اند، اغلب به القاب مخصوصه معروفند، من جمله «طالقان » لقب پادشاه شهرک از حدود ماوراءالنهر بوده است . (ایران در زمان ساسانیان ترجمه ٔ رشید یاسمی ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>).<br /></font></div>'),
(175284, 'طالقان', '<span class=\"hlight\">طالقان .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) دهی جزء دهستان شفت، بخش مرکزی شهرستان فومن . در <span class=\"hlight\" dir=\"rtl\">٣١</span>هزارگزی جنوب خاوری فومن و<span class=\"hlight\" dir=\"rtl\">٢٢</span>هزارگزی جنوب خاوری شفت . کوهستانی معتدل مرطوب و مالاریائی . با <span class=\"hlight\" dir=\"rtl\">٢٩٧</span> تن سکنه . آب آن از نهر امامزاده ابراهیم . محصول آنجا برنج و ابریشم و عسل و لبنیات . شغل اهالی زراعت و گله داری و شال بافی و راه آن مالرو است . زیارتگاه امامزاده ابراهیم برادر امام رضا (ع ) در چهارهزارگزی جنوب این آبادی واقع و زیارتگاه قراء اطراف محسوب میگردد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(175285, 'طالقانی', '<span class=\"hlight\">طالقانی .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) ابوعبداﷲ سیدی طالقانی از طالقان ری . مردی از کبار مشایخ و بزرگان علم حدیث بوده و پیش از سال <span class=\"hlight\" dir=\"rtl\">٣٢٠</span> هَ . ق . درگذشته است . ابوعبدالرحمن سلمی بدینسان نام او را در تاریخ صوفیه آورده است . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175286, 'طالقانی', '<span class=\"hlight\">طالقانی .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) ابوالخیر احمدبن اسماعیل یوسف طالقانی . از دوستان سمعانی صاحب کتاب الانساب بوده و سمعانی درباره ٔ وی گوید: دوست ما ابوالخیر احمدبن اسماعیل طالقانی قزوینی نیز از مردم همین ناحیه (طالقان قزوین ) است و او جوانی صالح بود و خوی و سیرتی استوار داشت با یکدیگر در نیشابور از ابوعبداﷲ فراوی و ابوالقاسم شحامی حدیث استماع کردیم و با هم کتب کبار را شنیدیم و او با من برای سماع تفسیر ثعالبی به طوس آمد و من صحبت و سیرت او را پسندیدم و او شروع به وعظ کرد و مردم او را پذیرفتند آنگاه بسوی بلاد خود رهسپار گردید. و رجوع به انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف » شود.<br /></font></div>'),
(175287, 'طالقانی', '<span class=\"hlight\">طالقانی .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) از خاندانهای قدیم ایرانی در نجف اند و جد ایشان سید حسن معروف به میرحکیم پسر سیدعبدالحسین است که از شاگردان مجلسی در اصفهان و ابن الوندی در کاظمین بوده است . و شیخ علی حزین (متوفی <span class=\"hlight\" dir=\"rtl\">١١٨٣</span>) و آقا احمد کرمانشاهی بر او تلمذ نموده اند. ایشان احوال وی درتاریخ حزین یاد کرده و دومین او را در «مرآت الاحوال » آورده است . از فرزندان این مرد دانشمندانی در قرن سیزدهم در نجف سکونت داشته اند مانند سید احمدبن الحسین بن الحسن میرحکیم که ترجمه ٔ احوالش در کرام البررة(ص <span class=\"hlight\" dir=\"rtl\">٨٤</span>) آمده است و سید باقربن رضابن احمدبن حسین بن حسن میرحکیم که ترجمه اش در همان کتاب (ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span>) آمده است و سید جعفربن علی بن حسین بن حسن میرحکیم نیز در همان کتاب (ص <span class=\"hlight\" dir=\"rtl\">٢٦٥</span>) و سید جوادبن محمدبن علی بن حسن میرحکیم در همان کتاب (ص <span class=\"hlight\" dir=\"rtl\">٢٨٩</span>) و سید حسن بن محمدبن علی بن حسن میرحکیم که در همان کتاب (ص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span>) یاد شده است .<br /></font></div>'),
(175288, 'طالقانی', '<span class=\"hlight\">طالقانی .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ )ابومحمد محمودبن خداش طالقانی . وی در بغداد سکونت داشت و از یزیدبن هارون و عبداﷲبن مبارک و فضیل بن عیاض و ابن عیینة و نصربن شمیل و وکیعبن جراح حدیث استماع کرده و ابراهیم حربی وحسن بن علی معمری و قاسم بن زکریا و ابویعلی موصلی و ابوالقاسم بغوی و یحیی بن محمدبن صاعد و محمدبن ابراهیم فیروز و ابوعبداﷲ محاملی و غیره از وی روایت دارند. وی در شعبان سال <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> هَ . ق . بسن <span class=\"hlight\" dir=\"rtl\">٩٠</span> سالگی درگذشت . و یعقوب دورقی گوید: هنگامی که محمودبن خداش جان سپرد من در زمره ٔ کسانی بودم که در کفن و دفن او شرکت جستم و پس از آن وی را بخواب دیدم و گفتم : ای ابومحمد با تو چگونه رفتار شد؟ گفت : من و همه ٔ پیروانم رابیامرزیدند. گفتم من نیز از پیروان تو بودم ؟ سپس پوستی از آستین خویش برآورد که بر آن نوشته بود یعقوب بن ابراهیم بن کثیر. (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> «ب »).<br /></font></div>'),
(175289, 'طالقانی', '<span class=\"hlight\">طالقانی .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) سعد طالقانی .مؤلف تاریخ سیستان ذیل عنوان «آمدن فضل بن حمید به امیری سیستان » گوید: فضل بن حمید برفت به حرب او (جیهانی ) سوی بست، روز سه شنبه هشت روز گذشته از جمادی الاولی سنه ٔ اثنی و ثلثمائة، چون بنوزاد رسید، بومنصورجیهانی پذیره ٔ او آمد، و آنجا حربی سخت بکردند و هزیمت بر جیهانی افتاد. با گروه خویش برفت سوی سعد طالقانی شد بزابلستان ... چون جیهانی نزدیک سعد رسید، قصد بُست کردند هر دو، چون برزدان رسیدند، فتح بن مارحوح تاختن کرد بر ایشان، و بسیار مردم کشته شد، آخر فتح بهزیمت شد و جیهانی و سعد هر دو به بست اندرآمدند... فضل بن حمید بیمار صعب شده بود و سوی بدر به پارس نامه نبشته که کسی فرست بجای من و علت خویش و مال خویش یاد کرده و بدر محمدبن طغریل را با سپاهی کاری بفرستاده بود، روز سه شنبه پنجروز مانده از ذی القعده ٔ سنه ٔ اثنی و ثلثمائة به سیستان اندرآمد، و برفت و به زمین داور شد و جیهانی و طالقانی به یک فرسنگی زمین داور با او حرب کردند و جیهانی بهزیمت برفت و طالقانی اسیر ماند، دو شب گذشته از محرم سنه ٔ ثلاث و ثلثمائة، و سعد را به عماری اندر به سیستان فرستاد و خالدبن محمد یحیی به زابلستان رفت با محمدبن طغریل، و آنهمه کارها به صلاح بازآورد و به سیستان بازگشت ... شش روز باقی از جمادی الاولی سنه ٔ ثلاث و ثلثمائة، و سعد طالقانی را خلاص کرد، و با او بسیار نیکوئی کرد. (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> و <span class=\"hlight\" dir=\"rtl\">٣٠٥</span>).<br /></font></div>'),
(175290, 'طالقانی', '<span class=\"hlight\">طالقانی .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) ابوالحسن عبادبن عباس بن عباد طالقانی . وی از ابوخلیفه فضل بن حباب بصری و ابوبکر محمدبن یحیی مروزی بغدادی و جعفربن محمدبن حسن قرمانی و محمدبن حبان مازنی و گروهی از بغدادیان سماع کرده است و او پدر صاحب اسماعیل بن عبادوزیر است . و عباد وزیر حسن بن بویه بوده است . ابواسحاق بن حمزه حافظ و ابوالشیخ و جز آنان از متقدمان از وی روایت کرده و به سال <span class=\"hlight\" dir=\"rtl\">٣٣٥</span> یا <span class=\"hlight\" dir=\"rtl\">٣٣٤</span> هَ . ق . درگذشته است . ابوالعلا احمدبن محمدبن فضل حافظ بزبان خود در اصفهان از قول محمدبن طاهر مقدسی حافظ بمن گفت که کتابی از تألیفات ابوالحسن عبادبن عباس طالقانی پدر صاحب اسماعیل در کتابخانه ٔ پسرش ابوالقاسم اسماعیل بن عباد در شهر ری دیدم . درباره ٔ احکام قرآن که در آن به یاری مذهب اعتزال برخاسته است و این کتاب را هر که ببیند نیکو میشمرد. ابوبکربن مردویه و محدثان اصفهانی و پسرش ابوالقاسم اسماعیل بن عباد طالقانی وزیر معروف به صاحب از آن کتاب روایت کرده اند و صاحب در شعر و ادب در سراسر جهان نامور است و نیازی به شناساندن او نیست . وی از محدثان اصفهانی و بغدادی و رازی سماع کرده و هم خود خبر داده است و او دیگران را به جستن حدیث و کتب آن برمی انگیخته و تشویق میکرده است . و ابوالمناقب حمزةبن اسماعیل علوی بنقل از ابومسعر سلیمان بن ابراهیم حافظ اصفهانی و ابوبکر احمدبن موسی بن مردویه حافظ، روایت کند که از صاحب ابوالقاسم اسماعیل بن عبادبن عباس شنیده اند که گفته است : هر که حدیث ننویسد لذت و شیرینی اسلام را درک نمیکند و او نیز حدیث روایت کرده است . (الانساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> «ب ») و رجوع به بصاحب بن عباد شود.<br /></font></div>'),
(175291, 'طالقانی', '<span class=\"hlight\">طالقانی .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ )(القاضی ) ابوالحسن علی بن المفضل المؤیدی الطالقانی . وی راست : الامثال البغدادیة یا رسالة الامثال البغدادیة التی تجری بین العامه . جمعها سنة <span class=\"hlight\" dir=\"rtl\">٤٢١</span> (؟). این کتاب را استاد لویی ماسینیون به سال <span class=\"hlight\" dir=\"rtl\">١٩١٣</span> م . از روی نسخه ٔ موجوده در کتابخانه ٔ ایاصوفیا در مطبعه ٔ رعمسیس طبع و نشر کرده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢٢</span>).<br /></font></div>'),
(175292, 'طالقانی', '<span class=\"hlight\">طالقانی .</span> <font color=\"DarkGreen\"><b>[ ل َ<span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) ابوبکر سعیدبن یعقوب طالقانی . از ابن مبارک و حمادبن زید و هیثم بن بشیر و نصربن شمیل و وکیعبن جراح و ابوتمیله یحیی بن واضح و ابوبکربن عیاش روایت کند و اسحاق بن ابراهیم قاضی و ابوزرعه ٔ رازی و ابوبکر اثرم و عباس دوری و حرب بن ابواسامة از وی روایت دارند. و ابوزرعة گویدسعید مردی ثقه بود. و اثرم گوید او را نزد احمدبن حنبل دیدم که درباره ٔ حدیث گفتگو میکرد. وی به سال <span class=\"hlight\" dir=\"rtl\">٢٤٤</span> هَ . ق . درگذشت . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> «ب »).<br /></font></div>'),
(175293, 'طالقانی', '<span class=\"hlight\">طالقانی .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) ابواسحاق بن اسماعیل طالقانی . وی در بغداد ساکن بود و از سفین بن عیینة وجریربن عبدالحمید و غیره روایت کرده و ابویعلی موصلی و ابوالقاسم بغوی از او روایت دارند. ابوحاتم بن حبان گوید وی از ثقات و پرهیزگاران مردم عراق است بعضی از کسان بر او حسد بردند از این رو سوگند یاد کرد که تا هنگام مرگ روایت حدیث نکند. و او به سال <span class=\"hlight\" dir=\"rtl\">٢٢٥</span> قسم یاد کرد و در پایان همان سال درگذشت و محدثی بسیارمستقیم حدیث بود. (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> «ب »).<br /></font></div>'),
(175294, 'طالقانی', '<span class=\"hlight\">طالقانی .</span> <font color=\"DarkGreen\"><b>[ ل َ<span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ص نسبی ) منسوب بهر یک از دو طالقان، طالقان بین قزوین و ابهر و طالقان بین بلخ و مروالرود، معروف به طالقان خراسان . و رجوع به انساب سمعانی شود.<br /></font></div>'),
(175295, 'طالقانی', '<span class=\"hlight\">طالقانی .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ص نسبی، اِ) منسوب به طالقان، نوعی جامه ٔ ابریشمی است که آن را اللبود الطالقانیة نامند و در طالقان خراسان ساخته میشود. (یعقوبی ص <span class=\"hlight\" dir=\"rtl\">٦٥</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span>). ابریشم مزبور از نوع ابریشم چین نیست بلکه از ابریشم مغرب است و ارزش آن از ابریشم چین کمتر و برابر با ابریشم مغرب باشد. (لطایف ثعالبی صص <span class=\"hlight\" dir=\"rtl\">١٢٨</span> - <span class=\"hlight\" dir=\"rtl\">١٢٧</span>) معهذاشهرت آن در حدود مغرب بیشتر است . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩</span>).<br /></font></div>'),
(175296, 'طالقون', '<span class=\"hlight\">طالقون .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (معرب، اِ) طالیقون است . رجوع به طالیقون شود. (فهرست مخزن الادویه ).<br /></font></div>'),
(175297, 'طالم', '<span class=\"hlight\">طالم .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) نان پز. ج، طلمة. (منتهی الارب ). خباز. نانوا. <BR><font color=\"Blue\">◄</font> (اِ) زرنیخ زرد.<br /></font></div>'),
(175298, 'طالم', '<span class=\"hlight\">طالم .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام شهری است که در جنوب اراضی یهودا در میانه ٔ زیف و بعلوت واقع بود. (یوشع <span class=\"hlight\" dir=\"rtl\">١٥</span>، <span class=\"hlight\" dir=\"rtl\">٢٤</span>) (قاموس مقدس ).<br /></font></div>'),
(175299, 'طالم سه شنبه', '<span class=\"hlight\">طالم سه شنبه .</span> <font color=\"DarkGreen\"><b>[ ل ُ س ِ شَم ْ ]</font></b> (اِخ ) نام محلی است کنار راه قزوین و رشت . میان سرکاجا و رود برده . در <span class=\"hlight\" dir=\"rtl\">٣٢٣٠٠٠</span> گزی تهران . در فرهنگ جغرافیایی آمده : دهی جزء دهستان سنگر کهدمات بخش مرکزی شهرستان رشت . در <span class=\"hlight\" dir=\"rtl\">١٣</span>هزارگزی جنوب خاوری رشت و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی باختر شوسه ٔ سنگر به رشت و نزدیک دوشنبه بازار. جلگه و معتدل و مرطوب و مالاریائی با <span class=\"hlight\" dir=\"rtl\">١٨٠٥</span> تن سکنه . آب آن از نهر گل رود از سفیدرود. محصول آنجا برنج و ابریشم و صیفی . شغل اهالی زراعت . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(175300, 'طالنطن', '<span class=\"hlight\">طالنطن .</span> <font color=\"DarkGreen\"><b>[ ل ِ طُ ]</font></b> (معرب، اِ) وزنی است معادل یکصدوبیست وپنج رطل . و این رطل یک دوازده ٔ اوقیه باشد. (مفاتیح خوارزمی ) (ابن الندیم ). <BR><font color=\"Blue\">◄</font> پول یونانی . (قفطی ). رجوع به تالان شود.<br /></font></div>'),
(175301, 'طاله جار', '<span class=\"hlight\">طاله جار.</span> <font color=\"DarkGreen\"><b>[ ل َ]</font></b> (اِخ ) دهی است از دهستان سرشیو بخش مرکزی شهرستان سقز در <span class=\"hlight\" dir=\"rtl\">٢٦٠</span>هزارگزی جنوب سقز و <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی جنوب خاوری حسن سالاران . کوهستانی است و سردسیر. با <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه . آب آن از چشمه و رودخانه . محصول آنجا غلات و لبنیات وتوتون . شغل اهالی زراعت و گله داری و راه آن مالرو است . دبستان دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(175302, 'طالو', '<span class=\"hlight\">طالو.</span>(اِخ ) قریه ای است از قراء استرآباد رستاق . (سفرنامه ٔ مازندران و استرآباد رابینو ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span> بخش انگلیسی ).<br /></font></div>'),
(175303, 'طالو', '<span class=\"hlight\">طالو.</span> (اِخ ) نام معدن ذغال سنگ است که در دهستان دامنکو بخش حومه ٔ شهرستان دامغان واقع گردیده است . این معدن در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی شمال طاق و <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی شمال خاوری دامغان واقع شده و فعلاً استخراج میشود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175304, 'طالوار', '<span class=\"hlight\">طالوار.</span> (اِخ ) ده کوچکی است از دهستان سیریک بخش میناب شهرستان بندرعباس . در <span class=\"hlight\" dir=\"rtl\">٤٥</span>هزارگزی جنوب میناب و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی خاور راه مالرو جاسک به میناب . دارای <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175305, 'طالوت', '<span class=\"hlight\">طالوت .</span>(اِخ ) ابن عبداﷲبن محمدبن علی بن ابی طالب بن سوید تکریتی تاج الدین بن نصرالدین بن وجیه الدین . او در سال <span class=\"hlight\" dir=\"rtl\">٦٨٣</span>هَ . ق . متولد شده است و از عمربن قواس سماع کرده وحدیث نقل کرده است وی در دوم ماه جمادی الاخرة سال <span class=\"hlight\" dir=\"rtl\">٧٣٣</span> هَ . ق . درگذشته است . (درر الکامنة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٥</span>).<br /></font></div>'),
(175306, 'طالوت', '<span class=\"hlight\">طالوت .</span> (اِخ ) ابن طالوت . رجوع به ابن طالوت شود.<br /></font></div>'),
(175307, 'طالوت', '<span class=\"hlight\">طالوت .</span> (اِخ ) نام پادشاهی عجمی . و حق تعالی داود را وارث ملکش فرمود. (منتهی الارب ).و نام سرداری از بنی اسرائیل که سقا بود، با جالوت نام کافر جنگ کرده، داود علیه السلام که از سپاهیان طالوت بود، جالوت را کشت . طالوت وعده ها که از داود کرده بود، از آن برگشت و دشمن گردید، بعد مردن او داود علیه السلام ملک راند. (غیاث اللغات ). و جوالیقی آرد: نامی عجمی است خدای تعالی فرماید: «فلما فصل طالوت بالجنود» (قرآن <span class=\"hlight\" dir=\"rtl\">٢٤٩/٢</span>). غیرمنصرف آمدن آن دلیل برآن است که عجمی است زیرا اگر بر وزن فَعلوت و مشتق از «طول »می بود مانند رغبوت و رهبوت و تربوت، نباید غیر منصرف به کار میرفت، هر چند در بعضی از احادیث آمده که وی در زمان خود از بالابلندترین کسان بوده است . (المعرب ص <span class=\"hlight\" dir=\"rtl\">٢٢٧</span>). نام طالوت به سریانی ساول، و به عبرانی شاول پسر قیش بن اَفیل بن صاروبن نحورت بن اَفیح بن انیس بن بنیامین بن یعقوب بن اسحاق بن ابراهیم الخلیل علیه السلام . (عرائس المجالس ثعلبی ). مردی از بنی اسرائیل که به روایت مسلمانان پدر زن حضرت داود، و از سبط بنیامین بن یعقوب بوده، و بپادشاهی ملت بنی اسرائیل رسید. مؤلف مجمل التواریخ والقصص گوید: اسنور نام مادِر کی بهمن معروف به اردشیر درازدست از فرزندان طالوت الملک بود. (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>) و رجوع به فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٥٤</span> شود.<br />مؤلف حبیب السیر گوید که : چون بنی اسرائیل با شموئیل گفتند که : اِبعث لَنا مَلکاً نقاتِل فِی سَبیل ِاﷲ (قرآن <span class=\"hlight\" dir=\"rtl\">٢٤٦/٢</span>) اشموئیل التماس قوم را بدرگاه ملک جلیل جل ّ جلاله، عرض کرد، و به مقتضای خبر جبرئیل دانست که طالوت بن قیس بن ضراربن انس بن بحرف بنیامین بن یعقوب علیه السلام را ایزدتعالی بسلطنت بنی اسرائیل سرافراز میسازد، یهود را از این واقعه آگاه گردانید، و بنا برآنکه پادشاهی بنی اسرائیل پیوسته بسبط یهودا میبود، و نسب طالوت به بنیامین میرسید، و او از غایت فقر به سقائی یا دباغی روزگار میگذرانید، قوم نخست از قبول این امر سرباز زده بزبان آوردند که : اَنی یَکون ُ لَه ُ الملک ُ عَلینا و نَحن ُ اَحَق ُ بِالملک ِ مِنه ُ وَ َلم یُؤت َ سَعَةً مِن المال ِ، (قرآن <span class=\"hlight\" dir=\"rtl\">٢٤٧/٢</span>). اشموئیل گفت مالک الملک او را از میان شما بسلطنت برگزید، بسبب ازدیاد علم و جسم، وَاﷲُ یُؤتِی مُلکه ُ مَن یَشاءُ. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٤٧/٢</span>). بنی اسرائیل گفتند با ما بگوی که علامت پادشاهی طالوت چه باشد. اشموئیل گفت امارت او آن است که تابوت سُکینه باز بتصرف شما درآید، در وقت ظهور او روغن قدس بجوش آید، و روغن قدس بقول مترجم تاریخ طبری، روغنی بود که از یوسف (ع ) برحسب ارث به انبیای بنی اسرائیل میرسید، و او رادر یکی از قرون بقره مذکوره محفوظ میداشتند. بالجمله روز دیگر طالوت بر مجمع یهود عبور نموده، روغن قدس در غَلیان آمد، و اشموئیل مقداری از آن روغن بر سر طالوت ریخته او را تهنیت منصب سلطنت گفت، و مقارن آن حال تابوت سکینه پیدا شد، و کیفیت وجه آن تابوت سکینه، بطریق مختلف در کتب تواریخ سمت گزارش پذیرفته، وراقم حروف خوفاً من الاطناب بر ایراد یک روایت قناعت مینماید. در بعضی از نسخ معتبره مسطور است که چون کفار عمالقه تابوت سُکینه را به دیار خود رسانیدند، آن را به بتخانه برده، در زیر قدم صنمی نهادند، روز دیگر که بدان خانه درآمدند تابوت را بر سر آن بت یافتند، و از دیدن آن صورت متعجب شده، بار دیگر تابوت رابرزمین افکندند و صنم را بر زبر آن نهادند، و پایهایش را بر تابوت دوختند، باز صباح پایهای بت را برزمین دیده، و تابوت را بر فرقش مشاهده نمودند، سَکنه ٔ بتخانه کیفیت واقعه را به عرض پادشاه خود رسانیدند، بعضی حاضران گفتند ما با خدای بنی اسرائیل طاقت مقاومت نداریم، پس آن تابوت را در مزبله ٔ یکی از قراء انداختند و تمام ساکنان آن قریه را در گردن علت ناسور پیدا شد، آن مردم عاجز گشته، عجوزه ای از عجایز بنی اسرائیل بدیشان گفت علاج مرض شما آن است که این تابوت را به اسرائیلیان رسانید، آن جماعت سخن آن ضعیفه را بسمع قبول شنوده تابوت را برگردونی نهادند و گردون را بر دو بقر بسته، راه بیت المقدس که وطن یهود بود روان کردند، ملائکه گاوان را براندند تا به زمین بنی اسرائیل رسید، القصه چون چشم اسرائیلیان بر تابوت سکینه افتاد، خوشحال و مسرور شده دل بر متابعت طالوت نهادند، و او را بر تخت سلطنت نشاندند، و نام طالوت به اعتقاد صاحب معالم التنزیل، شاوک بود. و بروایتی که در روضةالصفا مذکور است، بمشارک است، زیرا که طالوت را طول قامت بود، و بروایت تحفةالملکیه بعد از فوت موسی بچهار صد و هشتاد و نه سال، بسلطنت قیام نمود، و چون زمام مهام ذُریات یعقوب بقبضه ٔ اقتدار طالوت درآمد حاکم فلسطین که چند کرّت لشکر بر سر بنی اسرائیل آورده، و مراسم قتل و غارت بتقدیم رسانیده بود عازم شد، و طالوت با هشتاد هزار نفر از یهود متوجه ٔ آن جانب گشته، از آن جمله هفتاد و ششهزار کس از راه بازگشتند و سببش آن بود که تشنگی بر لشکر طالوت غلبه کرده بود، طالوت با ایشان گفت که چون به آب رسید زیاده از یک جرعه نیاشامید، و آن هفتاد و ششهزار کس بعد از وصول بشهر اردن تا فلسطین علی الاختلاف، خلاف قول طالوت کرده، هر چند آب بیشتر خوردند، تشته تر گردیدند، لاجرم مراجعت نمودند، و چهارهزارنفر دیگر در مرافقت طالوت طی مسافت فرمودند، جالوت با صدهزار سوار در برابر ایشان آمد. و بنی اسرائیل افغان : لاطاقة لناالیوم بجالوت و جنوده، برآوردند، و اکثر بصوب هزیمت شتافتند، بلکه زیاده از سیصد و سیزده کس دیگر نماند، و ایشان از سبطیهودا با دوازده پسر، یا هفت کس داخل آن لشکر بودند، و در تاریخ طبری مسطور است که در وقتی که طالوت متوجه حرب جالوت شد، اشموئیل زرهی تسلیم او کرده گفت این جبه بر قد هر کس راست آید، کشنده ٔ جالوت خواهد بود، و چون هر دو لشکر نزدیک یکدیگر رسیدند، طالوت فرمود تا ندا کردند که هر کس بر قتل جالوت اقدام نماید، ملک او را در ملک شریک ساخته دختر خود را به وی دهد، و چون داود بحسب سن و جثه خردترین اولاد ایشان بود این ندا شنود، به اخوان خود گفت چرا بمقاتله ٔ جالوت نمیروید تا بدین شرف که معین کرده اند برسید، ایشان از این امر استبعاد نمودند و گفتند که هیچکس را طاقت مقاومت با جالوت نیست، داود گفت من با او مبارزت نمایم، و او را بقتل رسانم، آنگاه نزد طالوت به قبول قتل جالوت زبان گشاد، طالوت آن جناب را حقیرالجثه دید، گفت این مهم مشکل که بر دست تو گشاید، گفت امتحان فرمای، طالوت آن زرهی را که اشموئیل داده حاضر ساخت، بر قد آن جناب راست آمد، طالوت دانست که کشنده ٔ جالوت او خواهد بود، لاجرم او را بر حرب جالوت تحریض فرمود، و به ازدواج یکی از بنات خود و شرکت در امر سلطنت وعده داد، فرمود تا اسب و سلاح مناسب آوردند و تسلیم داود نمودند، آن جناب فرمود که مرا بدین اشیاء احتیاجی نیست، و من به همین فلاخن که در دست دارم، با جالوت مقاتله خواهم کرد. نقل است که قبل از مقاتله، بر داود بعضی علامات ظاهر شد که دلالت بر آن می کرد که جالوت بر دست او مقتول خواهد شد. بنابرآن در آن روز بقبول آن امر خطیر مبادرت فرمود، یکی از آن علامات آن بود که در آن روز از سنگی آوازی شنود که ای داود مرا بردار که من حجر موسی ام که اعدای خود را بواسطه ٔ من بقتل رسانید و از سنگ دیگر صدائی بگوش او رسید که من حجر هارونم که فلان دشمن خویش را بسبب من از پای درآورد، و همچنین از حجر دیگر مسموع او شد که من سنگ داودم که جالوت را بوسیله ٔ من خواهی کشت، و داود آن سنگها را برداشته در توبره انداخته، هر سه سنگ بیکدیگر متصل شده، و قولی آنکه اشموئیل با داود علیهما السلام ملاقات کرده، و از وی تفتیش احوال نمود، گفته بود که جالوت بر دست تو مقتول خواهد شد. القصه چون داود باجامه ٔ پشمین و فلاخن و توبره ای که سنگ در آنجا بود، در برابر جالوت رفت، جالوت را از ضعف و حقارت قامت داود، آنچنان تعجب نموده، پرسید که به چه کار آمده ای، داود گفت : آمده ام تا ترا بقتل رسانم . جالوت آغاز تمسخر و استهزا کرد، و داود آن سنگ را که بهم اتصال یافته بود در فلاخن نهاد، و به جانب جالوت انداخت، آن سنگ نیز در فضای هوا سه پاره شد، و یک سنگ بر پیشانی جالوت رسید، و آن دو حجر دیگر یکی بطرف میمنه رفت، وآن جماعت را که در جانب میمنه بودند پریشان ساخت، ویک حجر به جانب میسره افتاد، و آن جماعت را پریشان کرد، جالوت از اسب درافتاد، و سپاهش منهدم شدند، و بنی اسرائیل آغاز قتل و غارت نمودند، داود سر جالوت رابریده بنظر طالوت رسانید. بصحت پیوسته که نسب جالوت به عملیق بن عاد میرسید. و نامش کلیاد، و آن کافر متهور بعظم خلقت موصوف بود، چنانچه خودی که بر سر خود مینهاد سیصد رطل وزن داشت . القصه چون طالوت مظفر و منصور به بیت المقدس رسید، داود نزد او رفت که طالوت بمواعید خود وفا نماید، نخست از قبول آن امر ابا نموده بالاخره بنا بر استمداد اشموئیل و علماء بنی اسرائیل، یکی از بنات خود را در سلک ازدواج او کشید، و محبت آنجناب در دل خاص و عام قرار گرفت، و از این جهت نائره ٔ رشک و حسد در دل طالوت اشتعال پذیرفته، در خاطرگذرانید که رشته ٔ حیات جناب نبوی را بریده، او را هلاک سازد، اما چون اشموئیل در قید زندگانی بود، ضمیر خود را ظاهر نمیساخت، بعد از فوت اشموئیل، طالوت قصدداود کرده، داود وقوف یافت، با منکوحه ٔ خویش که دختر طالوت بود، به موجب کلمه ٔ الفرار مما لایطاق عمل فرموده، طالوت در طلب داود مبالغه نمود، علمای بنی اسرائیل زبان طعن بر او دراز کردند، و طالوت بقتل علما مثال داد، بعد از چند گاه از خواب غفلت بیدار شد، و بر قبایح احوال خود مطلع شده، فرمود که عالمی بیاوریدکه از وی بپرسم که توبه ٔ من بکدام عمل خیر درجه ٔ قبول مییابد، و چون تمامی علمای بنی اسرائیل را بفرمان او کشته بودند، هیچکس نیافتند که به حل ّ مشکل او قیام نماید. بالاخره، حاجب، طالوت را بعجوزه ای مستجاب الدعوه نشان داد، طالوت آن ضعیفه را طلبیده، بزبان تضرع و زاری پرسید که چه کنم که توبه ٔ من قبول درگاه احدیت گردد. عجوزه گفت مرا مهلت ده تا بزیارت یکی از انبیا رفته حاجت ترا عرض نمایم، و آنچه بر من ظاهر شود با تو بگویم . آنگاه آن ضعیفه بسر قبر یوشع یا الیسع، یا اشموئیل رفته، و نماز گزارده و عرض نیاز نموده و در خواب شده، آن پیغمبر را در خواب دیده که با اومیگوید: توبه ٔ طالوت وقتی قبول می افتد که با ده پسرخود بجهاد جباران رود، و چندان حرب نماید که نخست اولاد او بتمام در نظرش شهید شوند. و خود نیز دست از جنگ باز ندارد، تا بدرجه ٔ شهادت رسد. چون آن ضعیفه ازخواب درآمده، کیفیت واقعه را با طالوت عرض نموده، طالوت اولاد خود را طلبیده ایشان را با خود موافق ساخته، و بحرب آن جماعت کفار کوشیده، تا آن زمان که پسران او جمله شهید شدند. آنگاه حرب مینمود تا او هم شهید شد. مدت عمرش بروایت تحفةالملکیة، پنجاه و دو سال بود. و زمان اقبالش را از دو سال تا چهل سال گفته اند. واﷲ اعلم . (حبیب السیر چ طهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢</span>). در مجمل التواریخ والقصص کیفیت پشیمانی طالوت را از قبایح اعمال و تصمیم او به توبه و انابت بدین طریق آورده که طالوت زنی عالمه را بحاجبی داد تا بکشد، نکشت، و نگاهش همی داشت . بعد از مدتی طالوت پشیمان شد، و کسی را می طلبید که از وی بپرسد که توبه ٔ وی چیست، کس را نیافت، حاجب آن زن را بیاورد، و بپرسید، گفت مرا به گورپیغامبری برید تا دعا کنم و او زنده شود و بگوید، پس او را به گور اشموئیل آوردند، زن دعا کرد، اشموئیل سر از گور برآورد، گفتا توبت طالوت چیست، گفت آنکه با دوازده پسر به حرب جباران رود تا کشته گردد. پس طالوت همچنان کرد و به حرب رفت تا شهادت یافت . و داودرا پادشاهی مستخلص گشت . (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٢٠٨</span>). و نیز در کتاب مزبور گوید: دِرع پیغمبر، یکی ذات القصول نام و دیگری الفضة، و آن زره داود بود علیه السلام که روز حرب طالوت پوشیده بود. (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٢٦٣</span>).<br /></font></div>'),
(175308, 'طالوت', '<span class=\"hlight\">طالوت .</span> (اِخ ) ابن ازهر. شاعری است مُقل، و مملوک بوده است . (فهرست ابن الندیم ص <span class=\"hlight\" dir=\"rtl\">٢٣٣</span>).<br /></font></div>'),
(175309, 'طالوت', '<span class=\"hlight\">طالوت .</span> (اِخ ) ابن اعصم الیهودی . این شخص یکی از کسانی است که به خلق قرآن قائل بوده، و ابان بن سمعان از او، و جعدبن درهم از ابان در این قول پیروی کرده است . و این قول بنابر آنچه مورخان نوشته اند، در پایان عصر امویان از جعدبن درهم انتشار یافته است . (ضحی الاسلام ص <span class=\"hlight\" dir=\"rtl\">١٦٢</span> ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175310, 'طالوت', '<span class=\"hlight\">طالوت .</span> (اِخ ) ابن طریف . ابومطیع بلخی از وی حدیث کرده است . مجهول است - انتهی . (لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span>).<br /></font></div>'),
(175311, 'طالوت', '<span class=\"hlight\">طالوت .</span> (اِخ ) ابن عباد صیرفی ... ابن جوزی گوید: علمای نقل و حدیث ضعف او را ثابت کرده اند. مؤلف گوید: تا این لحظه هر چه جستجو کردم آگاه نشدم کسی او را به ضعف نسبت دهد. و حدیث او را در المنتقی درباره ٔ حدیث مخلص نیک یافتم . طالوت به سال <span class=\"hlight\" dir=\"rtl\">٢٣٨</span> درگذشته و بیش از <span class=\"hlight\" dir=\"rtl\">٩٠</span> سال زیسته است - انتهی . و ابن حبان او را در زمره ٔ ثقات یاد کرده و کنیه ٔ وی را ابوعثمان آورده است . حاکم در تاریخ خود گوید: از صالح جرزة درباره ٔ وی سؤال شد گفت : او شیخ راستگو و صدیق است . (لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span> و <span class=\"hlight\" dir=\"rtl\">٢٠٦</span>).<br /></font></div>'),
(175312, 'طالوت', '<span class=\"hlight\">طالوت .</span> (اِ) نهر طالوت . نوعی نبیذ است به نام نهرطالوت . ابن عبد ربه در عقدالفرید آورده که اهالی کوفه، نبیذ را، نهر طالوت مینامیده اند و قال شاعرهم :<br />اشرب علی طرب من نهر طالوت <br />حمراء صافیة فی لون یاقوت <br />من کفت ساحرةالعینین شاطرة<br />تربی علی سحر هاروت و ماروت <br />لها تماویت الحاظ اذا نظرت <br />فنار قلبک من ملک التماویت <br />شبابه خبر داد و گفت غسان بن ابی صباح کوفی از ابوسلمة یحیی بن دینار و او از مظهر وراق حدیث کرد و گفت روزی زیدبن علی در بعضی از کوچه های کوفه میگذشت، ناگاه مردی از شیعیان را دید و او را به خانه ٔ خود خواند و طعامی برای او آماده کرد در این هنگام تنی چند از شیعیان دیگر آگاه شدند و به خانه ٔ وی شتافتند و مجلس پرجمعیتی تشکیل یافت، آنگاه آغاز طعام کردند و سپس آنان را بشراب دعوت کرد. شیعیان پرسیدند ای پسر رسول خدا از کدام شراب به ما مینوشانی ؟ گفت : از استوارترین و سخت ترین آنها. آنگاه قدحی نبیذ آوردند و او خود نوشید و قدح در میان ایشان دور زد و همه نوشیدندسپس گفتند ای پسر رسول خدا! آیا درباره ٔ این نبیذ حدیثی بروایت از پدر و جد خود بیاد داری ؟ اگر چنین حدیثی بیاوری بسزا خواهد بود چه علما درباره ٔ آن اختلاف نظر دارند گفت : آری . پدرم از جدم حدیث کرد که پیامبر (ص ) گفت لترکبن طبقة بنی اسرائیل حدوا لقذة بالقذة و النعل بالنعل الا و ان اﷲ ابتلی بنی اسرائیل بنهر طالوت، احل منه الغُرفة والغرفتین و حرم منه الری، و قد ابتلاکم بهذاالنبیذ، احل منه القلیل و حرم منه الکثیر. (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٨</span> صص <span class=\"hlight\" dir=\"rtl\">٨٦</span> - <span class=\"hlight\" dir=\"rtl\">٨٧</span>).<br /></font></div>'),
(175313, 'طالوطون', '<span class=\"hlight\">طالوطون .</span> (معرب، اِ) به یونانی سلق است که چغندر باشد. (فهرست مخزن الادویة).<br /></font></div>'),
(175314, 'طالوفس', '<span class=\"hlight\">طالوفس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) صفراغون است که آن را طیرالملوک نامند. و به فارسی مرغک سقا و دم جنبان و به هندی مموله گویند. (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویة).<br /></font></div>'),
(175315, 'طالون', '<span class=\"hlight\">طالون .</span> (معرب، اِ) اسم رومی آذریون است . (تحفه ٔ حکیم مؤمن ). <BR><font color=\"Blue\">◄</font> وزنی معادل <span class=\"hlight\" dir=\"rtl\">٩</span> اوقیه .<br /></font></div>'),
(175316, 'طالوی', '<span class=\"hlight\">طالوی .</span> <font color=\"DarkGreen\"><b>[ ل َ وی ی ]</font></b> (اِخ ) ابوالمعالی، درویش بن محمدبن احمد الطالوی الارتقی . وی ادیب و دارای اشعار و ترسلات نیکو است . تولد و وفات وی در دمشق بود و اشعار و ترسلات خویش را در یک مجلد گرد آورده، و آن را «سانحات دُمی القصر» نام نهاده است . تاریخ تولد وی به سال <span class=\"hlight\" dir=\"rtl\">٩٥٠</span> و وفات وی به سال <span class=\"hlight\" dir=\"rtl\">١٠١٤</span> هَ . ق . است .(الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>) و رجوع به درویش شود.<br /></font></div>'),
(175317, 'طالکوه', '<span class=\"hlight\">طالکوه .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b>(اِخ ) دهی جزء بلوک خورگام دهستان عمارلو بخش رودبار شهرستان رشت . در <span class=\"hlight\" dir=\"rtl\">٣٥</span>هزارگزی خاور رودبار و <span class=\"hlight\" dir=\"rtl\">٢٣</span>هزارگزی رستم آباد. کوهستانی، معتدل، مرطوب و مالاریائی . با <span class=\"hlight\" dir=\"rtl\">٤٣٠</span> تن سکنه . آب آن از چشمه . محصول آن غلات و بنشن و لبنیات و ارزن . شغل اهالی زراعت و گله داری و شال بافی و راه آن مالرو است . قلعه ٔ خرابه ٔ کافرقلعه بین خورگام و رحمت آباد از آثار قدیمی است . اکثر سکنه زمستان برای تأمین معاش به گیلان و نصف سکنه تابستان به ییلاق میروند. این ده از چهار محل بالا و پائین، پس و پیش تشکیل شده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(175318, 'طالیا', '<span class=\"hlight\">طالیا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) اصداف صغار است . (فهرست مخزن الادویه ).<br /></font></div>'),
(175319, 'طالیس', '<span class=\"hlight\">طالیس .</span> (اِ) نام هندی زرنب باشد. (مخزن الادویه ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175320, 'طالیسفر', '<span class=\"hlight\">طالیسفر.</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (معرب، اِ) بقول دزی (ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩</span>) بصورتهای طالیشفَر و طالیشقر و طالیَشفَر و طالشقیر در کتب گوناگون عرب آمده است چنانکه در تذکره ٔ داود ضریر انطاکی نیز طالیشقر است ولی صورت معروف آن همین طالیسفر است . آن را مرادف بسباسه، دارکیسه . لسان العصافیر. ماقر بیخ درخت توت، تیواج ختائی، پوست بیخ زیتون هندی، برگ زیتون هندی و غیره آورده اند. صاحب برهان گوید: «طالیسفر» بر وزن فالیزگر به لغت یونانی پوست بیخ زیتون هندی است و بعضی گویند برگ درخت زیتون هندی باشد. ابن البیطار آرد: غافقی آن را دارکیسه خوانده و بسیاری از مردم برآنند که طالیسفر همان بسباسه است ولی این نظر درست نیست و حُنین این دارو را که در کتاب دیسقوریدس طالیفسر آمده است بنام یونانی آن «ماقر» ذکر کرده است . و تنها ابن جلجل گمان کرده که طالیفسر را لسان العصافیر گفته اند و آن را ریشه های درختی هندی دانسته اند. دیگری گفته است : طالیسفر ریشه های گیاهی است که کرم ابریشم از آن تغذیه میکند. مجوسی گوید: داروی مزبور برگ درخت زیتون هندی است . دیگری آن را پوستهای درختی هندی دانسته که به یونانی بنام دارکیسه معروف است . دیسقوریدس در کتاب اول گوید ماقر پوست درختی است که آن را از بلاد یونان آرند. رنگ آن بسرخ سپپدی غلیظی زند، بسیار قابض است و گاهی آن را برای خونروی و زخم روده و سیلان فضولات به شکم، نوشند. جالینوس در کتاب هفتم گوید: این دارو پوست درختی است که آن را از هند آرند. مزه ٔ آن سخت گس و زبان گزو اندکی تیز و قدری معطر است و مانند ادویه ای که ازهند آرند خوشبو باشد و گوئی این پوست از جوهرهای گوناگونی ترکیب یافته است که بیشتر آنها زمینی و اندکی از آنها جوهر لطیف گرم است و به همین سبب سخت مایه ٔخشکی و قبض میشود و آن را به داروهائی در می آمیزند و تر کنند که برای شکم روی و زخم روده سودمنداند زیراداروی مزبور در درجه ٔ سوم چیزهائی است که مایه ٔ خشکی باشند. و اما از لحاظ گرمی و سردی، در هیچیک تأثیر آشکاری ندارد. غافقی گوید: و آنچه از گفتار دیسقوریدس و جالینوس درباره ٔ این دارو مستفاد میشود این است که طالیسفر به هیچ رو از انواع بسباسه نیست، زیرا بسباسه دارای اندکی قبض باشد و حرارت بر آن غالب است در صورتی که طالیسفر بگفته ٔ دیسقوریدس پوست رقیقی است نه درشت و با این خاصیت به «ارماک » شبیه تر است .<br />ابن عمران گوید: طالیسفر ریشه های باریکی است دارای پوست خاکی رنگ و درون زردرنگ و تندمزه و زبان گز میباشد و بوی آن مانند بوی زعفران تند است و آن گرم و خشک در درجه ٔ دوم است و بویژه برای بواسیر و ورمهای درون و بیرون سودمند است .<br />مجوسی گوید: طالیسفر در سردی و خشکی در درجه ٔ دوم است . مطبوخ آن با سرکه درد دندان را سودمند است و هرگاه آب مطبوخ آن را در دهان گیرند بیماری قلاع سفید را سودمند باشد. بدیغورس گوید: بدل طالیسفردو ثلث وزن آن زیره و نصف وزن آن ابهل است . رازی و اسحاق بن عمران نیز گفته ٔ او را آورده اند. (از مفردات ابن البیطار ج <span class=\"hlight\" dir=\"rtl\">٢</span>). و صاحب مخزن الادویه آرد: بفتح طا، در ماهیت آن اختلاف بسیار است بعضی گویند آن پوست درختی است که از بلاد هند آورند. اندک از دارچین ضخیم ترو صلب تر بااندک حدت و خوشبوئی کمی و اشقر و چون کهنه گردد مایل بسیاهی شود و گفته اند عروقی است باریک بیرون آن اغبر و اندرون آن زرد و بوی آن شبیه ببوی زعفران و با عفونت و تیزی و شاید زرنب باشد که به هندی طالیس نیز نامند و آن برگ درختی است باریک بیرون آن اغبر و اندرون آن زردرنگ . طبیعت آن مختلف القوی با جوهر ارضی غالب معتدل در گرمی و سردی و مایل بحرارت و خشک در سوم و بعضی گرم و خشک در دوم دانسته اند.<br />افعال و خواص آن : جهت لقوه و فالج و نفث الدم و نزف الدم و حبس سیلانات و اسهالات بواسیر و قروح امعاء و مضمضه به طبیخ آن با سرکه جهت درد دندان و نگاه داشتن آن در دهان جهت قلاع سفید آن و ضماد آن خشک کننده ٔ دانه ٔ بواسیر. مقدار شربت آن تا یک مثقال . بدل آن چهار دانگ ِ وزن آن کمون و نیم وزن آن ابهل، و گویند بدل آن بوزن آن سنبل و نیموزن ساوج، و گویند ابهل و مقل تساوی آن مضر ریه، مصلح آن عسل است . (مخزن الادویه ص <span class=\"hlight\" dir=\"rtl\">٣٧٤</span>).<br />حکیم مؤمن آرد: طالیسفر در ماهیت آن اختلاف کرده اند بعضی او را برگ زیتون هندی میدانند و حال آنکه در هند زیتون نمیباشد و جمعی بیخ درخت توت و پوست درخت لسان العصافیر و بسباسه دانسته اند و حقیر فرقی میان او و تیواج ختائی در افعال و غیره نمی یابم و در حرف «تا» مذکورشد. وی ذیل تیواج ختائی آرد: پوست درختی است شبیه به پوست درخت چنار و گویند پوست درخت لسان العصافیر بلاد ختا است و ظاهراً طالیسفر باشد در آخر دوم گرم و خشک و قابض و بسیار تلخ و با ماست چکیده و ربوب قابضه جهت اسهال مزمن بارده و قطع خون بواسیر و ضماد او با سرکه جهت درد سر و اورام رخوه و سنون او جهت درد دندان و تقویة لثه و نزله ٔ رطوبی و بخور او جهت رفع وبا و طاعون عجیب الاثر است، و بدستور جهت بواسیر و شقاق مقعد و درد آن و درد رحم و فرزجه ٔ او جهت قطع سیلان رحم و حیض مفید است، و نیم مثقال آن را با یک مثقال نیلوفر در حبس اسهال مجرب و قدر شربتش تا یک مثقال و مضر محرورین و معطش و مورث التهاب احشاء و مصلحش کتیرا و ربوب فواکه . (تحفه ٔ حکیم مؤمن ). داود ضریر انطاکی ذیل طالیسقر آرد: گیاهی است که در سرزمین دکن میروید و دارای فوایدی است برگهای دقیق صلبی دارد که بزردی زند و مزه ٔ آن تند و تلخ است . در میانه ٔ آن خطهائی است و هرگاه خشک شود و در یکدیگر پیچد، چنانکه گوئی پوست درخت است و از اینجا گمان کرده اند که آن بسباسه است و برخی گویند برگ زیتون هندی است در صورتی که در هند زیتون یافت نشود و شگفت ترآنکه گفته اند طالیسقر ریشه های توت است . و آن گرم و خشک در دوم است هر خونروی را سودمند باشد و رطوبت ها را ببرد و شربت و طلاء آن بواسیر را بهبود بخشد و برای بیشتر دردهای دهان و دندانها و قلاع هرگاه آن را با سرکه مطبوخ کنند و در دهن گیرند مفید است . و آن زیان میرساند ولی مصلح آن بستان است و شربت آن بقدر یکدرم است . و بدل آن دو ثلث وزن آن زیره و نیم وزن آن ابهل است . (تذکره ٔ داود ضریر انطاکی ص <span class=\"hlight\" dir=\"rtl\">٢١٨</span>). صاحب اختیارات بدیعی آرد: به یونانی دارکیسه خوانند، و باقر نیز گویند. و صاحب منهاج گوید ورق زیتون هندی است، و آن تسوری هندی بود، و صاحب جامع اقوال بسیار آورده است، اول گفته که بسباسه است دیگر قول ابن حلحل آورده که لسان العصافیر است، و دیگر گفته که عرق شجر هندی است، و دیگر گفته که عرق درخت توت است که کرم ابریشم برگ وی میخورد، و این قولها خلاف است و این موافق قول صاحب منهاج است، و صاحب جامع تحقیق نکرده که چیست، مؤلف گوید:پوست بیخ زیتون هندی است، و باقی همه قولها خلاف است و خطا. و آن پوست سطبرتر از دارصینی است و صلتبر، ومیل به سیاهی زند، و طعم آن بغایت عفص است و قابض، و اندک عطریتی داشته باشد، و جالینوس گوید در وی هیچ گرمی و سردی نبود، و گویند خشک بود. در سوم و ابن عمران گوید گرم و خشک بود در دوم، و مجوسی گوید معتدل بود در گرمی و سردی، و خشک بود در دوم . ذرب را نافعبود و قرحه ٔ امعاء و نزف دم و بواسیر و فالج و لقوه، و مقدار مأخوذ از وی یک مثقال بود، و چون بسرکه پزند و از آن مضمضه کنند درد دندان را نافع بود و قلاع را زایل کند، چون آب وی را در دهان نگاه دارند، و گویند مضر بود به شش، و مصلح وی عسل بود. دیسقوریدس گوید بدل آن چهار دانک وزن آن کمون بود، و نیم وزن ازابهل است، و رازی و اسحاق بن عمران همچنین گویند، و گویند بدل وی بوزن وی سنبل و نیم وزن وی سادج . و گویند بدل وی مقل و ابهل بود مساوی . (اختیارات بدیعی ). و خوارزمی ذیل ماقر آرد ماقر پوست نباتی است که از هند آرند. (مفاتیح ). و صاحب بحرالجواهر گوید برگ زیتون هندی است و آن را لسان العصفور نیز گویند. (بحر الجواهر).<br /></font></div>'),
(175321, 'طالیقون', '<span class=\"hlight\">طالیقون .</span> (معرب، اِ) طالِقون . به فارسی، مس رست گویند. و صفر عربی، و روی لغت فارسی عبارت از اوست، چه در بعضی از معادن مس بدون گداز بهم میرسد، و خودرو است، لهذا به فارسی روی نامیده انددر فلزات تحقیق شده . و آن مسی است زرد ذهبی، شبیه به برنج مصنوع، و از تافتن آتش و کوفتن مطرقه سیاه نشود. بخلاف سایر اقسام مس و مصنوع او مسی است که مکرر گداخته در بول گاو ریزند که در آن اشنان سبز جوشانیده باشند، و چون قدری رصاص اضافه کنند او را نحاس صینی نامند، در آخر سیم گرم و خشک و با سمیت، و از منقاشی که از آن بسازند، چون موی را بکشند دیگر برنیاید.و از قلابه ٔ او هیچ ماهئی خلاصی نپذیرد، و چون گرم کرده در آب اندازند، هیچ حیوانی از آن نخورد، و چون آئینه ٔ صیقلی از آن ساخته در خانه ٔ تاریک صاحب لقوه پیوسته در آن نظر کند، رفع علت شود. (تحفه ٔ حکیم مؤمن ). طالیقون : بزبان رومی هفت جوش را گویند و آن هفت جسد است که طلا و نقره و مس و قلع و سرب و آهن و روح توتیا باشد، آنها را با هم گدازند و از آن چیزها سازند. گویند اگر منقاشی از آن بسازند و موی زیادتی که درچشم باشد با آن منقاش بکنند، دیگر برنیاید. بعضی طالقون (بحذف یای حطی ) هم گفته اند و آن را نوعی از مس میدانند. و گویند مس زرد است و ارباب اکسیر آن را رست خوانند. و گویند در کان مس روئیده است، و به آن سمیتی هم هست . (برهان ). علی بن محمد گوید: طالیقون نحاسی بود که مدبر کرده باشند بتوبال نحاسی که در گمیز گاو خیسانیده باشند، پس در وی سمیتی بود، و حدتی تمام، و دیگر که آن مس زرد باشد، و فرق میان وی و انواع مس به زردی بود، و چون از آتش بیرون آورند، و پتک زنند تمددی در وی پیدا شود و زرد گردد، و شکسته نگردد تا سرد شود. در کتاب احجار آورده که طالیقون از جنس نحاس است غیر آنکه او را با ادویه ٔ گرم مدبر کنند تاسمیت در وی پیدا گردد. اگر از طالیقون منقاشی بسازند، و موی زیادت که در چشم بود بکنند دیگر نروید، خاصه چون مکرر کنند و اگر کسی لقوه داشته باشد، در خانه ٔ تاریک رود که قطعاً روشنی در وی نبود و آئینه ای ازوی در برابر روی خود دارد، و بدان ادمان کند، آن مرض از وی زائل گردد. واگر طالیقون را به آتش سرخ کنند، و در آب فروبرند، هیچ چهارپای گرد آن نگردد. و اگرقلابی از وی بسازند، و در آب آویزند، ممکن نبود که هیچ ماهیی از وی خلاص یابد. و طبری گوید که : طالیقون نحاس مدبر بود بتوبال النحاس . و اگر چنانچه در زمان ریختن مرتفع شود، بقیه در موضع سبیکه در بول گاو خیسانند، مؤلف گوید اکسیریان طالیقون را مس رُست گویند، و گویند در کان مس روید. (اختیارات بدیعی ). قد یجئی فی الکتب ذکر الطالیقون، من غیر ایضاح فیها بمائیته، و لم اتحققه من عیان او سماع معتمد، و یذکر فی کتب الطب ان المنقاش المعمول منه اذانتف به الشعر الزائدفی اهداب الاجفان منع عوده و قطع نباته، و قیل ایضاًان العین ترمد و تفسد بالنظر فی مرآة معمولة من الطالیقون و فی کتاب النخب انه معمول من الشبة و فی کتاب الاحجار، انه جنس من النحاس، الا ان الاوائل اکسبوه من الادویة الحادة، سمیته، حتی اضر باللحم والدم اذا خالطهما. (الجماهیر بیرونی ص <span class=\"hlight\" dir=\"rtl\">٢٦٧</span>). ابن البیطار در کلمه ٔ «طالقوز» <font color=\"DarkGreen\"><b>[ ظ. مصحف طالیقون ]</font></b> گوید: علی بن محمد گوید: نوعی مس است که آن را با توبال (براده ) مس در شاش گاو و مرجان خیسانده در آب اشنان رطب بعمل می آورند و از آن سمیت و تندی نیرومندی پدید می آید و آن گونه ای از مس زرد است و فرق میان آن و دیگر انواع مس زرد این است که این گونه را بتنهائی هرگاه در آتش داغ کنند و هنگام بیرون آوردن از آتش بکشند امتداد می یابدو زرد میشود و نمیشکند تا آنکه سرد شود. طبری گوید:مسی است که آن را به توبال (براده ) مس بعمل آورند وآن را از قبه ای که بر موضع قالب تر نهاده در شاش گاومیباشد برمیدارند. و در کتاب الاحجار آمده است که طالقوز از جنس مس است جز اینکه گذشتگان آن را با ادویه ٔ تند درآمیخته اند چنانکه در جسمیت آن سمیت پدید آمده و هرگاه به سبب جراحتی با خون حیوانی درآمیزد به آن حیوان زیان مفرطی میرسد، و هرگاه از طالیقون قلابی برای شکار ماهی بسازند سپس آن را بماهی درآویزند نمیتواند خود را از آن برهاند. رجوع به اختیارات شود.<br />فی النحاس کالفولاذ فی الحدید، یتخذ بالعلاج و هو ان یذاب و یطفاء فی بول البقر، و قد طبخ فیه الاشنان الاخضر مراراً، و قد یجعل معه قلیل رصاص و یسمی نحاس صینی، و هو شدید الحرارة والیبس یبلغالثالثة، اذا عمل منه ملقاط، و قلع به الشعر مراراًامتنع. او سنارة جلبت السمک و هو مسموم، اذا جرح به قتل . (داود انطاکی ). <BR><font color=\"Blue\">◄</font> وزنی معادل صد و بیست رطل، که هر رطل دوازده اوقیه باشد. برنال . (بحرالجواهر).<br /></font></div>'),
(175322, 'طالینوس', '<span class=\"hlight\">طالینوس .</span> (معرب، اِ) رجوع به طلینا شود. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩</span>).<br /></font></div>'),
(175323, 'طالیوس', '<span class=\"hlight\">طالیوس .</span> (اِخ ) الاسکندرانی . یکی از فلاسفه ای است که در ایام فترت بین ابقراط و جالینوس میزیسته . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br /></font></div>'),
(175324, 'طام', '<span class=\"hlight\">طام .</span> <font color=\"DarkGreen\"><b>[ مِن ْ ]</font></b> (ع ص ) بحر طام و بحر طامی ؛ دریائی پر. (مهذب الاسماء). بحر غزیر.<br /></font></div>'),
(175325, 'طامات', '<span class=\"hlight\">طامات .</span> <font color=\"DarkGreen\"><b>[ طام ْ ما ]</font></b> (ع اِ) اقوال پراکنده . (برهان ) (غیاث اللغات ) (آنندراج ). سخن از چپ و راست، یعنی قول پراکنده و شیادانه <span class=\"hlight\">:</span> <br />به طامات مجلس بیاراستم <br />پس آنگه ز حق مغفرت خواستم .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> هذیان و سخنان هرزه و اراجیف و بی اصل را گویند. (برهان ) (غیاث اللغات ) (آنندراج ). گفتار بیهوده . <BR><font color=\"Blue\">◄</font> خرق عادت و کرامت را نیز میگویند. (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> در رشیدی نوشته که طامات جمع طامه به تشدید میم به معنی داهیه و حادثه ٔ عظیم . (غیاث اللغات )(آنندراج ). <BR><font color=\"Blue\">◄</font> به معنی عجمه در زبان یعنی فصاحت نداشته باشد. (برهان ) (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اصطلاح تصوف ) نزد صوفیه معارفی را گویند که در اوان سلوک بر زبان سالک گذر کند. (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> لاف و گزاف صوفیان در باب اظهار کشف و کرامات خود. (غیاث اللغات از رشیدی ).و در سراج نوشته که طامات در اصل عربی است به تشدیدمیم و فارسیان به تخفیف استعمال کنند، به معنی اقوال پراکنده و سخنان بی اصل و پریشان که بعضی صوفیان برای گرمی بازار خود گویند. (غیاث اللغات ) (آنندراج ). سخن های بلند که صوفیه برای اظهار کرامت و شرافت مرتبه گویند و باعث پندار نفس و سؤاعتقاد مردم شود. (رشیدی ). در مورد این معنی میم مخفف تلفظ گردد <span class=\"hlight\">:</span> لکن عبارتی چند مزیف از طامات صوفیان بگرفته اند. (کیمیای سعادت ).<br />تاروی نمود رمز طامات مرا<br />از ره نبرد رنگ عبادات مرا<br />چون سجده همی نماید آفات مرا<br />محراب ترا باد خرابات مرا.<br /> <font color=\"Red\">سنائی .</font><br />پوشیده مرقعند از این خامی چند<br />بگرفته ز طامات الف لامی چند<br />نارفته ره صدق و صفا گامی چند<br />بدنام کننده ٔ نکونامی چند.<br /> <font color=\"Red\">(منسوب به خیام ).</font><br />سحرگاهی شدم سوی خرابات <br />که رندان را کنم دعوت بطامات .<br /> <font color=\"Red\">عطار.</font><br />هر چه جز خدمت تو عمر هبا و ضایع<br />هر چه جز مدحت تو شعر دروغ و طامات .<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />غیر تشویش و غم و طامات نی <br />همچو عنقا نام فاش و ذات نی .<br /> <font color=\"Red\">مولوی .</font><br />به طامات مجلس بیاراستم <br />ز دادآفرین توبه اش خواستم .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />که فکرش بلیغ است و رایش بلند<br />در این شیوه ٔ زهد و طامات و پند.<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />بصدق و ارادت میان بسته دار<br />ز طامات و دعوی زبان بسته دار.<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />طامات و شطح در ره آهنگ چنگ نه <br />تسبیح و طیلسان به می و میگسار بخش .<br /> <font color=\"Red\">حافظ.</font><br />ما مرد زهد و توبه و طامات نیستیم <br />با ما بجام باده ٔ صافی خطاب کن .<br /> <font color=\"Red\">حافظ.</font><br />ساقی بیا که شد قدح لاله پر ز می <br />طامات تا به چند و خرافات تا به کی ؟<br /> <font color=\"Red\">حافظ.</font><br />خیز تا خرقه ٔ صوفی بخرابات بریم <br />شطح و طامات ببازار خرافات بریم .<br /> <font color=\"Red\">حافظ.</font><br />یکی از عقل می لافد، یکی طامات می بافد<br />بیا کاین داوریها را به پیش داور اندازیم .<br /> <font color=\"Red\">حافظ.</font><br />سوی رندان قلندر، به ره آورد سفر<br />دلق بسطامی و سجاده ٔ طامات بریم .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(175326, 'طاماغا', '<span class=\"hlight\">طاماغا.</span> (معرب، اِ) به یونانی قنطوریون است . (فهرست مخزن الادویة). اسم یونانی قنطوریون کبیر است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(175327, 'طامة', '<span class=\"hlight\">طامة.</span> <font color=\"DarkGreen\"><b>[ طام ْ م َ ]</font></b> (ع اِ) روز قیامت، بدان جهت که غالب و فوق همه چیزهاست . (منتهی الارب ) (آنندراج ). در لغت روز قیامت را گویند کما فی الصراح . (کشاف اصطلاحات الفنون ). نامی است رستاخیز را. (مهذب الاسماء). قیامت . (ترجمان علامه ٔ جرجانی ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>). روز جزا. یوم البعث . یوم النشور. یوم الحساب . روز شمار. روز بازخواست . روز حشر. روز قیام . یوم الیقین . <BR><font color=\"Blue\">◄</font> بلا، که غالب و فوق همه ٔ بلاها باشد. (منتهی الارب ) (آنندراج ). داهیه . (مهذب الاسماء). سختی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طامه ٔ کبری </span> ؛ بلای بزرگ <span class=\"hlight\">:</span> بحصانت آن حصن، از صدمه ٔ اولی، و طامه ٔ کبری محترس شد. (ترجمه ٔتاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٥٩</span>). سیم آنکه، طامه ٔ کبری، و موجب شقاوت و خسران عقبی است تصحیح این وجه سقیم را. (جهانگشای جوینی ).<BR>۩ حادثه ٔ بزرگ . کاری سخت .<BR>۩ روز قیامت <span class=\"hlight\">:</span> چنین حالها میبود، و فترات می افتاد، و دل امیر بر اعیان تباه میشد، تا آنگاه که «الطامةالکبری »، پیش آمد. (منظور حمله ٔ سلاجقه بوده ). (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٦٢٧</span>). چون کار بر این جمله قرار گرفت، الطامةالکبری آن بود که نماز دیگر آن روز که امیر به گرگان رسید... دو سوار از آن بوالفضل سوری دررسیدند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٧٧</span>).<br /></font></div>'),
(175328, 'طامث', '<span class=\"hlight\">طامث .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) زن حائض . (منتهی الارب ) (آنندراج ) (مهذب الاسماء). زن بی نماز. زن خون دیده . زن لک دیده . زن قاعده شده . زن حیض افتاده . ج، طُمُث و طوامث .<br /></font></div>'),
(175329, 'طامح', '<span class=\"hlight\">طامح .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) زن که بی اجازت شوی در اهل خود رود. (منتهی الارب ) (آنندراج ). زن نافرمان . سرکش . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> زن نگرنده بسوی مردان . (منتهی الارب ) (آنندراج ).<BR><font color=\"HotPink\">♦ </font>اِمراة طامح یا امراة طماحة؛ زن که بشهوت به مردان نگرد. زن چشم چران . <BR><font color=\"Blue\">◄</font> بلند از هر چیزی . (منتهی الارب ) (آنندراج ) (غیاث اللغات ). عالی .<br /></font></div>'),
(175330, 'طامذ', '<span class=\"hlight\">طامذ.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) به گمان من یکی از قرای اصفهان است . (انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »). و صاحب مراصدالاطلاع ذیل طامذه آرد: دهی است از دهات اصفهان .<br /></font></div>'),
(175331, 'طامذی', '<span class=\"hlight\">طامذی .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابوالفضل عباس بن اسماعیل طامذی . از عابدان و پارسایان مردم اصفهان بود... او از یعقوب اسحاق بن مهران قعبنی و سهل بن عثمان و علی بن عبید طنافسی و طبقه ٔ ایشان روایت کرده و محمدبن یحیی ذهلی و ابوبکر احمدبن عمروبن ابی عاصم و علی بن رستم و طبقه ٔ آنان از او روایت دارند. وی پس از سال <span class=\"hlight\" dir=\"rtl\">٢٦٠</span> درگذشته است . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175332, 'طامر', '<span class=\"hlight\">طامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع اِ) کیک . (منتهی الارب ) (آنندراج ). برغوث . <BR><font color=\"Blue\">◄</font> (ص ) جهنده . برجهنده . <BR><font color=\"Blue\">◄</font> (اِ) طامربن طامر. آنکه او را و پدرش را کسی نداند که کیست . (منتهی الارب ) (آنندراج ) (مهذب الاسماء).<br /></font></div>'),
(175333, 'طامس', '<span class=\"hlight\">طامس .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) دور. بعید. <BR><font color=\"Blue\">◄</font> ناپدید. ناپیدا. پنهان . <BR><font color=\"Blue\">◄</font> ناپدیدکننده . (منتهی الارب ) (آنندراج ). محوکننده . <BR><font color=\"Blue\">◄</font> رجل طامس القلب ؛ مرد دل مرده . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(175334, 'طامع', '<span class=\"hlight\">طامع.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) آزمند. حریص . طمعکار. با طمع. طمعکننده . طمعدارنده . <BR><font color=\"Blue\">◄</font> امیدوار. (منتهی الارب ) (آنندراج ). آرزوخواه . ج، اطماع . عاسم ؛ مرد طامع. (منتهی الارب ) (قطرالمحیط) <span class=\"hlight\">:</span> <br />دل مرد طامع بود پر ز درد<br />به گرد طمع تا توانی مگرد.<br /> <font color=\"Red\">فردوسی .</font><br />ابومنصور اسفنجانی را در زعامت جیوش خراسان طامع کرد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٥١</span>). در ولایت طامع شد و لشکری سر ایشان فرستاد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢١٧</span>).<br />از الوهیت زند در جاه لاف <br />طامع شرکت کجا باشدمعاف .<br /> <font color=\"Red\">مولوی .</font><br />طمع را سه حرف است هر سه تهی <br />از آن نیست مر طامعان را بهی .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />مرا گر تو بگذاری ای نفس طامع<br />بسی پادشاهی کنم در گدائی .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(175335, 'طامغاز', '<span class=\"hlight\">طامغاز.</span> (اِخ ) پسر امیر سنقر اشقر در بلاد تتار متولد شده وبه قاهره رفته و در آنجا مدت پنجاه سال فرمانروائی کرده است . مردی بخشنده و زیباروی بود و برادری داشت موسوم به ابراهیم که اندکی پیش از مرک طامغاز از جانب بوسعید نزد او به رسالت آمد. طامغاز در محرم سال <span class=\"hlight\" dir=\"rtl\">٧٣١</span> هَ . ق . درگذشته است . (درر الکامنه ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٥</span>).<br /></font></div>'),
(175336, 'طامل', '<span class=\"hlight\">طامل .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) مردپلیدزبان . <BR><font color=\"Blue\">◄</font> بیباک . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) دوقو. (فهرست مخزن الادویه ). رجوع به دوقو شود و آن را طله ملو نیز گویند. دوقوا. (فهرست مخزن الادویه ). تخم گزر. بزرالجزر. تخم حویج .<br /></font></div>'),
(175337, 'طامند', '<span class=\"hlight\">طامند.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) دهی است از دهستان نهارجانات بخش حومه ٔ شهرستان بیرجند. در <span class=\"hlight\" dir=\"rtl\">٦٨</span>هزارگزی جنوب خاوری بیرجند. دامنه، معتدل . با <span class=\"hlight\" dir=\"rtl\">١١٩</span> تن سکنه . آب آن از قنات . محصول آن غلات و لبنیات . شغل اهالی زراعت و مالداری و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175338, 'طامه', '<span class=\"hlight\">طامه .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) دهی است از دهستان جی بخش حومه ٔ شهرستان اصفهان . در چهارهزارگزی شمال اصفهان و سه هزارگزی باختر راه اصفهان به برخواره . جلگه و معتدل . با <span class=\"hlight\" dir=\"rtl\">١٦١</span> تن سکنه . آب آن از چاه . محصول آنجا غلات، پنبه و تریاک و صیفی . شغل اهالی زراعت و راه آن فرعی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(175339, 'طامه', '<span class=\"hlight\">طامه .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) دهی است ازبخش نطنز شهرستان کاشان در <span class=\"hlight\" dir=\"rtl\">٦٠</span>هزارگزی جنوب نطنز به اردستان . کوهستانی سردسیر. با <span class=\"hlight\" dir=\"rtl\">١١٠٠</span> تن سکنه . آب آن از <span class=\"hlight\" dir=\"rtl\">٨</span> رشته قنات . محصول آنجا غلات و حبوبات و میوه جات وگلابی آن به خوبی مشهور است . شغل مردان : زراعت است وعده ای برای تأمین معاش برای کارگری به طهران رفت وآمد میکنند. صنایع دستی زنان قالی بافی است و راه فرعی به شوسه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175340, 'طامهر', '<span class=\"hlight\">طامهر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) دهی است از دهستان رباطات بخش خرانق شهرستان یزد. در<span class=\"hlight\" dir=\"rtl\">٣٠</span>هزارگزی جنوب خرانق و <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی راه خرانق به اشکذر، کوهستانی و معتدل و مالاریائی . با <span class=\"hlight\" dir=\"rtl\">١٢٤</span> تن سکنه . آب آن از چشمه و محصول آنجا غلات . شغل اهالی زراعت و راه آن فرعی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(175341, 'طامور', '<span class=\"hlight\">طامور.</span> (ع اِ)طومار. نامه . کتاب . <BR><font color=\"Blue\">◄</font> دفتر. (منتهی الارب ) (آنندراج ). و رجوع به المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٥</span> شود.<br /></font></div>'),
(175342, 'طاموسونیون', '<span class=\"hlight\">طاموسونیون .</span> (معرب، اِ) به یونانی مزمار الراعی را گویند. (فهرست مخزن الادویة). و آن را طاموسونیوت و لوزن و به عربی زمارةالراعی نیز گویند. (مفردات ابن البیطار).<br /></font></div>'),
(175343, 'طامیج گز', '<span class=\"hlight\">طامیج گز.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) ده کوچکی است از دهستان مارز بخش کهنوج . سر راه مارز - کهنوج با <span class=\"hlight\" dir=\"rtl\">٤</span> تن سکنه . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(175344, 'طامیوس', '<span class=\"hlight\">طامیوس .</span> (معرب، اِ) اسم یونانی مرزنجوش است . (فهرست مخزن الادویه ).<br /></font></div>'),
(175345, 'طان', '<span class=\"hlight\">طان .</span> (ع ص ) جای گلناک . (منتهی الارب ) (آنندراج ). یوم ٌ طان ٌ و ارض ٌ طانةٌ مثله . (منتهی الارب ) (آنندراج ). کثیرالطین . (مهذب الاسماء). پُر گل . جای ِ بسیار گل .<br /></font></div>'),
(175346, 'طانز', '<span class=\"hlight\">طانز.</span><font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع ص ) فسوس کننده . (منتهی الارب ). که مردم را بفسوس گیرد. استهزأکننده . سخن گوینده ٔ بفسوس و لاغ .<br /></font></div>'),
(175347, 'طانیس', '<span class=\"hlight\">طانیس .</span> (اِخ ) بنابر قول ابن رسته، نام رودی است که به دریای لازق جاری و داخل میشود. (حاشیه ٔ مجمل التواریخ والقصص ).<br /></font></div>'),
(175348, 'طاها', '<span class=\"hlight\">طاها.</span> (اِخ ) یا طه . نام سوره ٔ بیستم از قرآن کریم <span class=\"hlight\">:</span> <br />پس از الحمد و الرحمن و الکهف <br />پس از یاسین و طاسین میم و طاها.<br /> <font color=\"Red\">خاقانی .</font><br />نفس طاها راست یک شب قاب قوسین نزد حق <br />گر دو گردد نفس طاها برنتابد بیش از این .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> نام حضرت پیغمبر (ص ) چرا که اشارت است از یا طاهر. (آنندراج ) <span class=\"hlight\">:</span> <br />از علم پاک جانش وز زهد دل ولیکن <br />بر رو نبشته طاها بر طیلسانش یاسین .<br /> <font color=\"Red\">؟</font><br />و رجوع به طه شود.<br /></font></div>'),
(175349, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن هلال . ابن اثیر در ضمن حوادث سال <span class=\"hlight\" dir=\"rtl\">٤٠٤</span> هَ . ق . ذیل ذکر استیلای طاهربن هلال بر شهر زور آرد: درباره ٔ کیفیت شهر زور یاد کردیم که بَدْربن حسنویه آن را تسلیم سردار سپاهیان کرد و وی عمال و جانشینان خود را در آن شهر برگماشت ولی در این سال طاهربن هلال بن بدر بشهر زوررفت و با لشکریان فخرالملک که در آن شهر بودند پیکار کرد و شهر را از آنان در ماه رجب بازستد. و چون وزیر از این خبر آگاه شد فرستاده ای نزد طاهر گسیل کرد و او را مورد نکوهش قرار داد و امر کرد کسانی را که از یاران وی اسیر کرده آزاد کند. طاهر فرمان او را پذیرفت و شهر زور همچنان در تصرف وی بود تا ابوالشوک با او به جنگ پرداخت و شهر را از وی باز گرفت و آن را به برادرش مهلهل سپرد. (از تاریخ کامل ابن اثیر ص <span class=\"hlight\" dir=\"rtl\">١٠١</span> ج <span class=\"hlight\" dir=\"rtl\">٩</span>). و رجوع به مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> شود.<br /></font></div>'),
(175350, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن یحیی النسابه . از محدثان است . رجوع به الذریعه ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٨</span> و <span class=\"hlight\" dir=\"rtl\">٤١٩</span> و ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٥</span> شود.<br /></font></div>'),
(175351, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن یحیی النار بن حسن بن جعفر الحجةبن عبیداﷲ الاعرج بن حسین الاصغربن علی زین العابدین بن حسین بن امیرالمؤمنین علی بن ابیطالب علیهماالسلام، کنیتش ابوالقاسم، و جدّ شرفاء مدینه ٔ طیبه بوده است . (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٠٠</span>) و او را طاهربن یحیی العلوی نیز میگویند. و رجوع به ابوالقاسم طاهر در همین لغت نامه و جامعالتواریخ (نشور المحاضره ) تألیف قاضی ابوعلی تنوخی ص <span class=\"hlight\" dir=\"rtl\">٢٤٦</span> شود.<br /></font></div>'),
(175352, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوعلی طاهر الحسن (ظَ : طاهر ابن الحسن ) بن احمدبن ابراهیم الاسدی الانطاکی . او را جزئی است در حدیث، معروف بجزء ابن فیل . (کشف الظنون ).<br /></font></div>'),
(175353, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن یحیی الیمنی . او راست : کتابی بنام «الاحتجاج الشافی . بالردعلی المعاند فی طلاق التنافی » هنگامی که ابوبکر وعَلَی در طلاق و ربا اعمال حیله را منکر گردید، و در این باب قصیده ای ساخت، طاهر یمنی در رد او این کتاب را تألیف کرد. وعل از دهات اصفهان است . (کشف الظنون ).<br /></font></div>'),
(175354, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوالحسن طاهربن محمدبن ابی تمیم . مؤلف تاریخ سیستان، ذیل عنوان «حدیث نصربن احمد با امیر بوجعفر» گوید: باز ابوالحسن طاهربن محمدبن ابی تمیم دستوری خواست و به خراسان شد، و آنجا بردست وی کارها بسیار رفت و خدمتها کرد امیر خراسان را، و سببها بود او را که بجایگاه باز گفته آید انشأاﷲ، و بسیار چیز عطا داد، و نام وی به مردی اندر خراسان بزرگ گشت، و به درگاه امیر خراسان ببود، و آنجا خلعت و ایجاب بسیار یافت و معروف گشت، وز آنجا با بزرگی به سیستان بازآمد و امیر با جعفر پذیره ٔ او بازشد، و او را با مرتبه ٔ بزرگ بشهر اندرآورد، و شش ماه اینجا ببود، و روز و شب بمجلس او بود، و خلعتها داد، و نیکوئیها کرد با او، باز بست او را داد و آنجا شد، و آنجا اهل علم بسیار بود، و طاهر علم دوست بود، و روز و شب بدان مشغول گشت، و علما و فقهاء بست را روز و شب نزدیک خویشتن داشتی، و مناظره کردندی اندر پیش او، و او اندر آن سخن گفتی . (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٢٥</span>). و نیز ذیل عنوان «کُشتن امیر شهید بوجعفر» گوید: و امیر بوالحسن بن طاهربن ابی علی التمیمی از بست بفراه آمد که آن ناحیت برسم او بود، و آنجا مردم بسیار با او جمع شد و به در شهر آمد، امیر خلف پذیره ٔ او بیرون شد، و یکدیگر را در کنار گرفتند، و امیرخلف گفت تو اندر این مملکت با من شریکی و او را بقصر یعقوبی فرود آورد. (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٢٧</span>). و هم ذیل عنوان «آمدن امیر طاهر بوعلی به سیستان » گوید: و مادر طاهر بوعلی، عایشه بنت محمدبن ابی الحسین بن علی بن اللیث بود و روز دوشنبه درآمد، غُرّه ذی القعدة هم اندر این سال، باز چون شش ماه بگذشت، فتنه اندر شهر برخاست، و اندر این ششماه خطبه چنین کردندی قاضی خلیل بن احمد بر منبر: اللهم اصلح الامیرین ابااحمد و ابی الحسین - بازنگرنوسک با مردمان خویش اندر شب به در قصر یعقوبی آمد و مردم عام و امیر طاهر بوعلی از کوشه (کوشک ) بهزیمت بیرون آمد، و به کوی کوشه فرود آمد، تا مردم بر او جمع شد، و حرب سمک و صَدق کردند، دیگر روز آخر سراسته (کذا) بسوختند، باز امیرخلف گفت که من سوی حج همی خواهم رفت که مرا آن شب که آن محنت پیش آمد نذری کرده ام، اما گفتم تا این کارها استقامت گیرد، پس سیستان بجمله به امیر طاهر بوعلی اسپرد، و بفرمود که هر چه به دست آید زان خونیان قصاص همی کن، و خود برفت غُره ٔ جمادی الاولی سنه ٔ ثلاث و خمسین و ثلاثمائة سوی بیت اﷲ الحرام، و امیر طاهر بوعلی بایوسف محمدبن یعقوب المدرکی را بند کرد، روز دوشنبه دوازده روز گذشته از شهراﷲ المبارک سنه ٔ ست و خمسین و ثلثمائة باز بفرمود تا او را بکشتند شب نوروز چهار روز گذشته از ربیع الاَّخر سنه ٔ سبع و خمسین و ثلاثمائة. و امیر طاهر بوعلی، مردی عالم و کاری بود و سخی و عادل و نیکوخصال، و سیستان بدو آرام گرفت از بس عدل و انصاف که بر رعیت خاص و عام و لشکری بود اندر عهد او، و خراج دِرَمی درمی سِتدی، و امیر بوجعفر هم این عادت داشت، و شب و روز بخوردن مشغول بودی، طاهر هم بر عادت و سیرت او رفت، و قاتلان او را همه به دست کرد و بکشت و بر این حال همی بود؛ و اگر سِیرِ مروت و عیاری امیر طاهر گویم، قصه دراز گردد، اما یک حکایت یاد کنم بروزگار امیر بوجعفر، طاهر بوعلی، و محمد حمدون، بحشم بخراسان شدند به درگاه امیر خراسان، و طاهر از عمرویان بود، و محمدبن حمدون نبیره ٔ مرزبان بود که بروزگار جاهلیت سیستان ایشان را بود، و ایشان از تخم رستم دستان بودند، چون امیر خراسان شدند هر روز بسلام رفتندی و دو سوار تمام بودند چنانکه هر یکی بر هزار سوار نهاده بودند، روزی بربگستان بخارا همی گوی زدند، و دوازده هزاربرنشسته بود آن روز از بزرگان حشم امیر خراسان و طاهر و محمد حمدون ِ عبداﷲ هر دو ایستاده همی نظاره کردند؛ امیر خراسان حاجبی را فرمان داد که رو میرکان سجزی را گوی تا گوی زنند، حاجب فرارفت و گفت، ایشان خدمت کردند و اسب پاشنه برنهادند، و گوی زدند چنانک ازآن دوازده هزار گوی ببردند، سپهسالاری بود عرب را به درگاه امیر خراسان، بانگ برآورد به پارسی گفت آبادباد آن شهر که مردم چنین خیزد و پرورد! محمدبن حمدون گفت کمینه ٔ سواران آن شهر مائیم، و ما را یارگی نباشد که اندر پیش سواران ملک نیمروز به میدان اندر شویم ! امیر خراسان را آن خوش آمد و هر دو را بنواخت و خلعت و مال بی اندازه داد، و فتیک خادم را آن روز طاهر بوعلی را بخشید، و فتیک آن خادم بود که او را دویست غلام ترک دون دیگر چیزها بود؛ و کار طاهر آنجا بالا گرفت تا او را امیر خراسان به سپاه سالاری به حرب ماکان فرستاد، و امیرک طوسی را و عبداﷲ فرغانی را زیر دست او، و آنجا شدند و حرب کردند و ماکان بهزیمت شد، و گرگان غارت کردند، و امیر طاهر بمیدان ماکان شد و خیمه بزد و کسی را نگذاشت که اندر سرای او غارت کرد، و کمتری مالها هزار مرکب تازی و هزار استر بَردعی بر آخور او بود، و خادمی را بخواند و اجراهاء غلامان و سرای زنان او همی داد، بزیادت از آنکه ماکان داده بود.ماکان به طبرستان شد، وز آنجا به ترکستان شد، و سوار جمع کرد، و بتاختن شبیخون آورد، و گرگان بگرفت، و سپاه طاهر را خبر نبود، و امیرک طوسی و عبداﷲ فرغانی و فتیک خادم و بوالحسن کاشنی که حاجب الحجاب بود، وسپاه دیگر که امیر خراسان داده بود، سپاه و بنه ٔ طاهر برگرفتند و برفتند. طاهر حرب کرد و بایستاد با سواری چند و گرفتار شد، و طاهر را و یاران را به قفسهاء آهنین اندرکرد ماکان، و دو سال آنجا ببند ماکان بماند، و ماکان را خبر نبود که طاهر است اندر بند، و همه روز ماکان متأسف بود که من طاهر را بدیدی تا خدمتی کردمی بدان نیکوئی که او کرد. تا روزی آن خادم بدان زندان اندر شد، طاهر را بدید بشناخت، دوان پیش ماکان شد که طاهر اندر بند تست، ماکان به نفس خویش به زندان اندر شد، و طاهر را زمین بوسه کرد و خلاص کرد وعذر خواست، اندرندانستن، و بیاورد او را بجای خویش بنشاند، و خود بخدمت او بایستاد. تا بسیار جهد کرد تا بنشست، و صد غلام و صد کنیزک و بیست هزار دینار و صد هزار درم فرستاد طاهر را، و کوشکی بیاراست از بهر او، و ستوران و مرکبان نیکو چنانکه ماکان و پادشاهان را باشد بفرستاد، و یکماه شب و روز مهمان داشت . پس وزیر خویش را نزدیک او فرستاد که خواهی تو میرباش تامن سپهسالار، و اگر نه تو سپهسالار تا من بگویم که میرالایاری (کذا... ظ: میرالامرائی ) ترا اندر همه کارهاست . طاهر گفت نیکو گوید، اما اگر این همی برای آن همی کند که من بر آستای حرم و اسباب وی کردم تا مکافات آن باشد، من آن از آن کردم که جدان من همه جهان بگرفتند، هر جا که بسرای آزادمردان رسیدند، همان کردند، این عادتی بود که من از نیاکان خویش نگاه داشتم، او مرا سپاه سالار نباید کرد و نه امیر که من مردی دشمن اویم و چاکر امیر خراسان، او را بگوی که بر هر که نپرورده ئی اعتماد مکن، خاصه بر دشمن، من پروده ٔ نعمت امیر خراسانم و از سیستانم، و اگر من ترا به حرب اندربیافتمی بدرگاه فرستادمی، و هیچ محابا نکردمی ؛ پس ماکان گفت فرمان تراست، گفت مرا دستوری ده تا بروم، اما یک ماه بیاسایم، ماکان بازسازی نو فراگرفت راه را، و مالی بسیار بفرستاد، همه بپذیرفت . پس پیغام بفرستاد که مردی کاری باید مرا تا بدین مالها کدخدائی کنم، پس ماکان مردی بفرستاد آن مال همه بدان کدخدای سپرد، و خود دیگر روز برنشست، و آن کدخدای را گفت من بدین دشتها اندر چیزی نهاده ام بروم بیارم، تو اندیشه ٔاین شغلها دار که باشد که یک دو روز بمانم، برفت با جنیبتی و رکابداری و استری، و قدری خوردنی برگرفت، وراه خراسان گرفت، هیچکسی را خبر نبود تا به یک منزل بخارا رسید، سوی امیر خراسان نامه ای نبشت و خبر کرد، دگر روز امیر خراسان سپاه برنشاند و خود تا یک فرسنگ به استقبال او باز شد، و بر یکی بالا بایستاد تا بزرگان و سرهنگان پذیره همی شدند، میدید، پس فتیک خادم، و بوالحسن کاشنی آمدند با غلامی پانصد آراسته با کمرها و سلاح تمام و پذیره ٔ او همی رفتند؛ امیر خراسان گفت کدخدائی این است که بوالحسن کاشنی و فتیک خادم امیر طاهر را کرده اند که بیستگانی همی ستدند، و لشکر او نگاه داشتند و غلام خریدند، و ستور و مرکبان، تا امروز اندر خراسان هیچکسی را آن تجمل نیست که طاهربن بوعلی راست که از بند رسته، و آن مردی که کرده بود ازو پسند کرد از گفتار و کردار و چیز نپذیرفتن از ماکان . و سلطان محمود سبکتکین اندر مجلس خویش این حکایت از امیر طاهر بوعلی برگرفتی و گفتی مرا بایستی که او را زنده بدیدی . پس امیر خراسان او را خلعتهاء نیکوبداد، وز آنجا نامه کرد نزدیک امیر باجعفر تا فراه او را داد و آنجا بود تا این حالها افتاد؛ پس امیری سیستان یافت و روزگار خوش خورد و با مردمان نیکوئی کرد و نام نیکو از او بماند و تا جهان باشد میگویند. باز چون کار سیستان بر او قرار گرفت اندر سنه ٔ سبع وخمسین و ثلاثمائة لشکر کشید و به بست شد، ترکان از بست بهزیمت برفتند و بست خالی بگذاشتند، و امیر طاهر اندر بست شد بی هیچ حربی و کشتنی و او را خطبه کردند، و چندگاه آنجا ببود و هیچ خبر نداشت، تا یوزتمر تاختن آورد، و ایشان غافل بودند، گروهی از پیادگان سجزی بکشتند و طاهر بازگشت به سیستان آمد، و همه ٔ بزرگان خویش را بند برنهاد بارس دیلم را که سپهسالار وی بود، و بوالحسن کاشنی را که حاجب الحجاب بود، و ناصربن منصور را که رئیس لشکر بود، و محمد عزیز را، و احمد عزیز را، و احمدبن ابراهیم، و محمدبن صالح السیاری را، و این اندر سنه ٔ ثمان و خمسین و ثلاثمائة بود. و گفت شما به حرب اندر یاری نکردید؛ تا این بود امیر خلف از حج بازآمد، به نزدیک بوحمدبن منصور شد، امیر خراسان به بخارا، و امیر خراسان او را خلعت و سپاه دادو بیامد به سیستان، و امیر طاهر چون خبر بشنید، عهدرا که کرده بود و سوگندان خورده را، از شهر بیرون شد و برفت و به سفزار شد، و امیر خلف روز یک شنبه یازده روز گذشته از رجب سنه ٔ ثمان و خمسین و ثلاثمائة، بکده ٔ محمد لیث فرود آمد، و دگر روز اندر شهر آمد و اورا خطبه کردند، و به دارالملک بنشست، باز امیر طاهربوعلی بازآمد ساخته، و بمتکران (کذا) و حرب کردند، و امیر خلف بهزیمت برفت به بست شد و آنجا ببود، تا روز آدینه دو شب مانده از شعبان سنه ٔ ثمان و خمسین و ثلاثمائة، و امیر طاهر بوعلی فرمان یافت و امیر حسین به پادشاهی نشست . (تاریخ سیستان از صص <span class=\"hlight\" dir=\"rtl\">٣٢٨</span> - <span class=\"hlight\" dir=\"rtl\">٣٣٤</span>).<br /></font></div>'),
(175355, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوالفتح . وی ممدوح انوری بوده است . رجوع به لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span> و رجوع به افتخارالدین ابوالفتح طاهر و لباب الالباب ص <span class=\"hlight\" dir=\"rtl\">١٣١</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span> شود.<br /></font></div>'),
(175356, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوعلی طاهر مجیرالدین .وی از اعقاب شیخ الرئیس طاهربن عبداﷲ بیهقی است که عمل نیشابور و بیهق داشته است او در روز دوشنبه <span class=\"hlight\" dir=\"rtl\">٢١</span> ذی القعده سال <span class=\"hlight\" dir=\"rtl\">٥٥٠</span> هَ . ق . در قصبه ٔ سبزوار درگذشت . رجوع به تاریخ بیهق ص <span class=\"hlight\" dir=\"rtl\">١٩١</span> و طاهربن عبداﷲ بیهقی شود.<br /></font></div>'),
(175357, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمد، ظهیرالدین فاریابی . با اتابکان آذربایجان معاصر بود. اتابک ابوبکر در تربیتش بیشتر از دیگران اهتمام مینمود. گویند که ظهیر شبی در مجلس اتابک این رباعی در سلک نظم کشید:<br />ای ورد ملائکه دعای سر تو<br />سر نیست زمانه را بجای سر تو<br />با دشمن تو نیام شمشیر تو گفت <br />سرّ دل من باد قضای سر تو.<br />اتابک فرمود تا هزار دینار نثار او کردند. ظهیر متعاقب این رباعی دیگر گفت :<br />شاها ز تو کار ملک و دین بانسق است <br />وز عدل تو جان فتنه جو بی رمق است <br />در عهد تو رافضی و سنی با هم <br />کردند موافقت که بوبکر حق است .<br />وفات ظهیر در سنه ٔ ثمان و تسعین و خمسمائه (<span class=\"hlight\" dir=\"rtl\">٥٩٨</span> هَ . ق .) اتفاق افتاد و در مقبرةالشعراء سرخاب مدفون گشت . (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٥٩</span>). و رجوع به ظهیرالدین فاریابی در همین لغت نامه و مجالس النفایس ص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span> و فهرست کتابخانه ٔ مدرسه ٔ سپهسالار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠١</span>، <span class=\"hlight\" dir=\"rtl\">١٩١</span>، <span class=\"hlight\" dir=\"rtl\">٢١١</span>، <span class=\"hlight\" dir=\"rtl\">٦١٣</span>، <span class=\"hlight\" dir=\"rtl\">٦٣١</span>، <span class=\"hlight\" dir=\"rtl\">٦٣٥</span> شود.<br /></font></div>'),
(175358, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن هارون بن عبید، ابوالحسن المدائنی . حدث عن وجوده فی کتاب ابیه . (کذا) ابوعبداﷲ محمدبن احمدبن ابی خثیمة از او روایت دارد. (تاریخ خطیب ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٦</span>).<br /></font></div>'),
(175359, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن الوزیر. فخرالدین طاهربن الوزیر معین الدین الکاشی . وی در زمان سلطان ارسلان بن طغرل بن محمدبن ملکشاه بر مسند وزارت نشسته، به سرانجام مهام فرق انام قیام و اقدام نمود. و امور مملکت را در سلک استقامت انتظام داده . در بسط بساط عدالت اهتمام تمام فرمود. و در آن ایام حاکم ولایت ری، امیر امیربن علی بار، و معین الدین ساوجی المستوفی بملازمت سلطان رسیده، نسبت به اتابک شمس الدین ایلدگز، که پدر سببی سلطان و پادشاه نشان بود ... و فخرالدین طاهر اطلاع یافته، در خلوتی کیفیت قصد معاندان، و حقیقت حسد و شرارت ایشان را، بر طبق عرض نهاد. و سلطان سخنان وزیر صاحب تدبیر را بسمع رضا اصغا نموده، حکم فرمود تا امیر امیر را مقید به قلعه ٔ نخجوان بردند. و معین الدین ساوجی را مؤاخذه و معاقب ساخته، آنچه در حوزه ٔ تملک داشت، از وی بستدند. و بدین سبب مرتبه ٔ جناب وزارت مآب، سمت ازدیاد پذیرفت . و روزی چند در کمال استقلال، بدولت و اقبال بگذرانید. اما در عنفوان جوانی و غلوای نافذ فرمانی، بواسطه ٔ اصابت عین الکمال، جهان فانی را وداع کرده، رخت به ریاض جاودانی کشید. بیت :<br />در این بستان که جای بیغمی نیست <br />گیاهی بی بقاتر زآدمی نیست .<br /><font color=\"Red\">(دستورالوزراء ص <span class=\"hlight\" dir=\"rtl\">٢٨</span>).</font><br /></font></div>'),
(175360, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن نصربن جهبل الحلبی، ملقب به مجدالدین، برادر عبدالملک بن جهبل . مردی عالم و زاهد و فاضل بوده است در فقه و حساب و فرائض . از جمعی روایت حدیث کرده . کتابی در فضل جهاد بنام نورالدین از سلاطین ایوبیه ٔ مصر پرداخته است . در حلب در مدرسه ٔ نوریّه تدریس میکرد. او اول کسی است که در قدس شریف در مدرسه ٔ صلاحیه تدریس کرد. و نخستین اولاد بنی جهبل از فقهاء دمشقیین است . وفاتش در سال <span class=\"hlight\" dir=\"rtl\">٥٩٦</span> هَ . ق . در سن شصت و چهارسالگی رخ داد. چنانکه ذهبی در کتاب «العبر» و اسنوی در طبقات الشافعیه آورده . در کتاب انس الجلیل، بتاریخ القدس و الخلیل، نیز نزدیک بدانچه ذکر شد، در ترجمه ٔاحوال او آورده و بعلاوه گفته است که در قدس شریف وفات یافت . این شخص و برادرش زین الدین عبدالملک بودند که بر شیخ سهروردی اعتصاب کرده و شوریدند، تا رسید بدو آنچه رسید. (از اعلام النبلا بتاریخ الحلب الشهبا ج <span class=\"hlight\" dir=\"rtl\">٤</span>ص <span class=\"hlight\" dir=\"rtl\">٣١٣</span>). و رجوع به ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٤</span> و <span class=\"hlight\" dir=\"rtl\">٣١٥</span> همان کتاب شود.<br /></font></div>'),
(175361, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ )ابن موسی الکاظم . حمداﷲ مستوفی پسران الکاظم ابراهیم موسی بن جعفربن محمدبن علی بن حسین بن علی المرتضی امام هفتم شیعیان را <span class=\"hlight\" dir=\"rtl\">٣١</span> تن دانسته و نام <span class=\"hlight\" dir=\"rtl\">٢٥</span> تن آنان را آورده است و از آنجمله گوید: و طاهر و مطهر که به فیروزکوه مدفونند. رجوع به تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span> شود. و رابینو آرد: طاهر از فرزندان امام هفتم، امام موسی کاظم علیه السلام . و مزار شریفش در بارفروش است . (سفرنامه ٔ مازندران و استرآباد رابینو ص <span class=\"hlight\" dir=\"rtl\">١٨</span> بخش انگلیسی ).<br /></font></div>'),
(175362, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن مظفربن محمد عمری عدوی ربعی شیخ زین الدین دانشمند بزرگ و عارف نامور که بدانش و پرهیزکاری هر دو متصف بود و راه تدریس و افاده بدیگران را می پیمود. سالیان دراز مردم را در راه خدا موعظه میکرد. او راست : مجموعه هائی در تفسیر و حدیث و فقه و تصوف و تاریخ . و دارای اجازه نامه های عالی از پدرش بود و کتاب جامعالاصول را از قطب الدین محمودبن <font color=\"DarkGreen\"><b>[ مسعودبن ]</font></b> مصلح الشیرازی با تمام قرائت آن بر شیخ صدرالدین قونوی به نقل از شرف الدین هذبانی و او از مصنف کتاب روایت کرده است . و در طلب علم و صحبت مشایخ سفرهای بسیار کرده است و کتابی در فضیلت علم و شرف علما بنام (تحفة الحلفا الی حضرةالخلفا) تألیف کرده است سپس در پایان عمر به جزایر میرفته است و در بعض منازل میان راه با کاروانیان فرودآمده است و در نیمه ٔ شب که ماه میتابیده است برای نماز و عبادت برخاسته و به نماز مشغول شده است . در این هنگام یکی از کاروانیان از خواب برمی خیزد و می بیندکسی خم و راست میشود و گمان میبرد دزدی است که قصد شبیخون به قافله دارد از این رو تیری به سوی او می افکند و آن تیر یکراست بسر پیشانی آن پارسا وارد می آیدو او هنگام سجود تیر را با دست از پیشانی خود بیرون میکشد و آن را برروی سجاده میگذارد و جان به جان آفرین تسلیم میکند جنازه ٔ او را به خاک فارس برمیگردانند و در پشت دروازه ٔ فسا به سال هفتصد و ... دفن میکنند. و از جدم شنیدم که قاتل را حبس کردند و پدرم را در خواب دیدم که گفت من گناهکار را بخشودم و شما هم از وی چشم بپوشید و چون از خواب برخاستم دستور دادم او را آزاد کنند و بخط شریف او این اشعار در نزد من است : (مطلع آن نقل شد).<br />زر والدیک و قم علی قبریهما<br />فکاننی بک قد حضرت لدیهما<br /> <font color=\"Red\">(از شدالازار صص <span class=\"hlight\" dir=\"rtl\">١٨٣</span> - <span class=\"hlight\" dir=\"rtl\">١٨٦</span>)</font><br />و رجوع به ص <span class=\"hlight\" dir=\"rtl\">٣٢٤</span> همان کتاب و حواشی محمد قزوینی در صفحات مزبور شود.<br /></font></div>'),
(175363, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن مسلم علوی . پدر حسن نامی است که هنگام ظهور تاهرتی یکی از دعات باطنیان که در اثناء آنکه مردم را به الحاد و پیروی باطنیان دعوت میکرد خود را بسمت سفارت از طرف سلطان مصر به دربار سلطان محمود غزنوی معرفی کرد، و چون در آن هنگام سلطان مشغول قلع و قمع ملحدان و باطنیان بود، از تاهرتی بدگمان شد و فرمان داد از احوال او استکشاف کنند، در آن حال کتبی چند از صحائف اهل باطن در میان اوراق تاهرتی یافتند. بالنتیجه مجلسی خاص از اعیان ائمه و قضاة حاضر کردند و حسن بن طاهربن مسلم علوی از شاهدان آن محضر انتخاب شد. و به دلیل و برهان ثابت کرد که تاهرتی علوی نیست، و تعیین او نیز به سفارت از طرف سلطان مصر حقیقت نداشته، و به اباحت خون او فتوی داد. سلطان نیز حکم تاهرتی، با حسن انداخت، و حسن او را بکشت . (تاریخ یمینی صص <span class=\"hlight\" dir=\"rtl\">٣٩٨</span> - <span class=\"hlight\" dir=\"rtl\">٤٠٢</span>).<br /></font></div>'),
(175364, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن مسعود. (الشیخ ) ابوالصفا، وی در جامع زیتونة بشهر تونس علوم فراگرفت، و در پایان روزگار ائمه ٔ بکریین تولیت خلافت امامت یافت در سال <span class=\"hlight\" dir=\"rtl\">١٢٢١</span> هَ . ق . پس از تکمیل تحصیلات پیوسته ملازم تدریس و امامت و خطبه بود، تا به سال <span class=\"hlight\" dir=\"rtl\">١٢٣٤</span> به مرض طاعون درگذشت . او راست : کتابی به نام «المواهب الصمدیة لکشف لثام السمرقندیه » که در فن بلاغت نوشته . این کتاب به سال <span class=\"hlight\" dir=\"rtl\">١٨٩٨</span> م . در تونس به طبع رسیده است . و در پایان آن ترجمه ٔ احوال مؤلف نیز ضمیمه شده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢٤</span>).<br /></font></div>'),
(175365, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) محمود الملقب بصدر الاسلام . او راست : کتابی به نام «فوائد صدرالاسلام ». (کشف الظنون ).<br /></font></div>'),
(175366, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمد المقدسی الملقب به ابی زرعة. ابن ابی اصیبعة در تاریخ الاطبا از جمله ٔ اساتید موفق الدین عبداللطیف البغدادی، یکی طاهربن محمدالمقدسی را میشمارد، و میگوید پدر موفق الدین، فرزندش را در کودکی نزد گروهی از دانشمندان به فراگرفتن دانش واداشت که یکی از آنان ابوزرعه بود. (ج <span class=\"hlight\" dir=\"rtl\">٢</span> عیون الانباء ص <span class=\"hlight\" dir=\"rtl\">٢٠٢</span>).<br /></font></div>'),
(175367, 'طاهر', '<span class=\"hlight\">طاهر.</span><font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) محمدطاهر نصرآبادی اصفهانی . معاصر میرزا صائب و میرزا حیدر و از شاعران نامور آن روزگار بشمار میرفت . او راست : تذکرةالشعراء بزبان فارسی که در آن ترجمه ٔ حال قریب هزار تن از شاعران آن عصر را آورده است و از این تذکره شرح حال آقا حسین خونساری و محمدباقر سبزواری در نجوم السماء نقل شده است . و آن از مآخذ تذکره ٔ خزانه ٔ عامره و سرو آزاد و دیگر تذکره ها بشمار میرود و در سال <span class=\"hlight\" dir=\"rtl\">١٣١٧</span> هَ . ق . بتصحیح وحیددستگردی در طهران چاپ شده است و در مقدمه ٔ این طبع شرح حال مختصری از مؤلف آمده است و آن دارای یک مقدمه و پنج فصل و خاتمه ای است . در آغاز تذکره، فهرست عناوین و در آخر آن فهرست اَعلام تنظیم گردیده است . و این میرزا طاهر بجز میرزا طاهر قزوینی ملقب به وحید و صاحب دیوان نثر و نظم به فارسی و عربی و ترکی است که شاه سلیمان پس از مرگ وزیرش شیخ علیخان در سال «<span class=\"hlight\" dir=\"rtl\">١١٠١</span>» او را به وزارت برگزید و پس از مرگ شاه سلیمان، شاه سلطان حسین نیز وزارت را بدو واگذار کرد. (از الذریعه ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>). رجوع به الذریعه ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩٤</span> شود.<br /></font></div>'),
(175368, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) (سلطان ...) پسر سلطان احمد جلایر است، در آن هنگام که قرایوسف ترکمان بر عراق عرب یورش میخواست برد، سلطان احمد در بغداد بود به حله نزد پسر خود سلطان طاهر رفت و آغا فیروز را که جملةالملک طاهر بود بگرفت . بدین سبب پسر از پدر متوهم گشته، به اتفاق امراء عظام، محمد بیک و امیرعلی قلندر، میکائیل و فرخشاه که ایشان نیز از سلطان احمد خوف داشتند یاغی گشت، و بشب از آب بگذشت، و روز دیگر سلطان احمد، جسربریده، در این طرف آب در برابر پسر منزل گزید و کس نزد قرایوسف ارسال داشته، او را بمدد طلبید، قرا یوسف بدو پیوسته به اتفاق از آب عبور نمودند، و با سلطان طاهر حرب کرده، او را شکست دادند و سلطان طاهر در وقت فرار خواست که اسب از جوی بجهاند باجیبه و اسلحه در آب افتاده، شعله ٔ حیاتش فرونشست . (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥١٦</span>). و رجوع به حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠٣</span> شود.<br /></font></div>'),
(175369, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن احمدالنحوی . کنیت وی ابوالحسن، و متوفی در سال <span class=\"hlight\" dir=\"rtl\">٣٨٠</span>. او راست : کتابی بنام «تذکره » در قراآت سبع. (کشف الظنون ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175370, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) (مشهد...) در عسقلان مشهدی است، آنرا مشهدِ طاهر خوانند، و در او همیشه خون تازه بر روی زمین پیدا بود، گویند قابیل هابیل را آنجا کُشته است، و اثر خون اوست که پیداست . (نزهةالقلوب ج <span class=\"hlight\" dir=\"rtl\">٣</span> از تاریخ مغرب ص <span class=\"hlight\" dir=\"rtl\">٢٩٢</span>).<br /></font></div>'),
(175371, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) (سرهنگ ...) طاهر محمد سنجری . رجوع به تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٦٨</span> شود.<br /></font></div>'),
(175372, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) محمد چهره . از سردارانی است که میرزا بایسنقر را دستگیر کرد. رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٤</span> شود.<br /></font></div>'),
(175373, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) محمدبن عمادالدین حسن یکی از مورخان هندوستان است . او را کتابی است موسوم به روضةالطاهرین که شامل وقایع سنوات تا <span class=\"hlight\" dir=\"rtl\">١٠١٥</span> هَ . ق . میباشد. (از قاموس الاعلام ترکی ).<br /></font></div>'),
(175374, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) (کوه ...) حمداﷲ مستوفی آرد: در زمین مصر کوهی است که آنرا کوه طاهر میخوانند، از آنجا آب شیرین بیرون می آید: و در حوض جمع میشود و بهمه جوانب روان میگردد، اگر جنب یا حائض به کنار حوض آن رسد، آب بازایستد، و تا آن کس دور نشود، آن آب که در حوض باشد، بیرون نریزد و روان نشود. (نزهةالقلوب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٠</span>).<br /></font></div>'),
(175375, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) (قاضی ...). صاحب تاریخ سیستان ذیل عنوان : «آمدن امیربیغو به سیستان » آرد: هم بدین سال (<span class=\"hlight\" dir=\"rtl\">٤٦٥</span> هَ . ق .) دیگر باره آمدن ملاحده بدیه ربحن (؟) و حصار بستدن و بردن قاضی طاهر <font color=\"DarkGreen\"><b>[ و ]</font></b> قاضی مسعود را به روز چهارشنبه پنجم جمادی الاخر <font color=\"DarkGreen\"><b>[ ه ]</font></b> بسال پانصد و نود، و یکی شدن لشکر سیستان و غور و خراسان بدر قاین <font color=\"DarkGreen\"><b>[ و ]</font></b> کشتن ملحدان . (تاریخ سیستان <span class=\"hlight\" dir=\"rtl\">٣٩٢</span>).<br /></font></div>'),
(175376, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ )غلام ابی الجیش . نجاشی درباره ٔ او گفته : مردی متکلم بود، و آغاز تحصیل شیخ مفید، نزد او بود. کتابی چند تألیف کرده، شیخ مفید گوید او را کتابی است در علم کلام، و در آن کتاب در قضیه ٔ فدک بیاناتی آورده، همچنین شیخ طوسی نیز از او در فهرست خود نام برده و آنچه را شیخ مفید گفته تأیید کرده است . (روضات ص <span class=\"hlight\" dir=\"rtl\">٣٣٦</span>).<br /></font></div>'),
(175377, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) (سید...) مزار امامزاده ای است در هزارخال از محال کُجورکه بانی آن ملک کیومرث رستمداری بوده است . (سفرنامه ٔ مازندران و استرآباد رابینو بخش انگلیسی ص <span class=\"hlight\" dir=\"rtl\">١٠٨</span>).<br /></font></div>'),
(175378, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابومحمداحمد طاهر حدیف . رجوع به تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٦٠</span> شود.<br /></font></div>'),
(175379, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) زینب . مؤلف تاریخ سیستان آرد: و سپهسالار طاهر زینب بود که آنگاه سرهنگ خواندندی او را. (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٤٧</span>). وی همان طاهر است که در حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٦</span> نام او طاهربن زینب آمده است و متقدمان فارسی زبان اضافه نام فرزند را به نام پدر روا میدانسته، ابن یا پسر را حذف میکرده اند. مثلاً بجای یعقوب بن لیث، یعقوب لیث میگفته اند. رجوع به طاهربن زینب شود.<br /></font></div>'),
(175380, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) حامدی . وی در حامدیه که شهری در صعید مصر از توابعبخش قنا است بسر میبرده و در سال <span class=\"hlight\" dir=\"rtl\">١٣١١</span> درگذشته است . او راست : «الکشف الربانی، علی المورد الرحمانی » و آن عبارت است از شرح ارجوزه ٔ شیخ احمدبن شرقاوی که به «المورد الرحمانی » موسوم میباشد. این کتاب در مطبعه ٔ خیریه، با کتاب «مطیّة السالک، الی مالک الممالک » که در تصوف و آن نیز تألیف مؤلف مزبور است، در حاشیه ٔ آن به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٧</span> هَ . ق . به طبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢٥</span>).<br /></font></div>'),
(175381, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) (حاجی - افندی ) یکی از مشاهیر خوشنویسان و معلم خط عبدالمجیدخان (سلطان عثمانی ) بوده و به سال <span class=\"hlight\" dir=\"rtl\">١٢٦٢</span> هَ . ق . درگذشته است کتیبه هایش را در بعضی مساجد اسلامبول میتوان مشاهده کرد. (قاموس الاعلام ترکی ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(175382, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) جعفربن محمد الصادق علیه السلام امام ششم شیعیان . آن حضرت را القاب بسیار است، اشهرها: الصادق و منها الصابر والفاضل و الطاهر. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧١</span>) و رجوع به جعفربن محمد الصادق شود.<br /></font></div>'),
(175383, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) بصیر معروف به میرزاطاهر بصیر الملک فرزند میرزا احمد کاشانی . مؤلف «کشف الابیات مثنوی » که به سال <span class=\"hlight\" dir=\"rtl\">١٢٩٩</span> چاپ شده است . میرزا طاهر مؤلف «ترجمةالقرآن » به فارسی است و از مقدمه ٔ کتاب «فواید گیاه خواری » معلوم میشود که کتاب ترجمة القرآن در سال <span class=\"hlight\" dir=\"rtl\">١٣١١</span> هَ . ق . طبع شده است و مترجم مزبور پدر میرزا محمودخان شیبانی محاسب الملک بوده که مخارج چاپ کتاب فواید گیاه خواری «صادق هدایت » را پرداخته است . (از الذریعه ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).<br /></font></div>'),
(175384, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) بادار طاهر مأمون درقی . رجوع به تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٩٤</span> شود.<br /></font></div>'),
(175385, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) انجدانی، شاه طاهر از سادات عالی درجات انجدان . من محال قم، موطنش کاشان، مولدش همدان، جامع علوم صوری و معنوی بود، مدتی در کاشان خلایق را ارشاد مینمود، آخرالامر صاحب غرضان، نسبت طریقه ٔ اسماعیلیه به وی داده و سلطان عهد دست ایذاء و آزار به وی گشاده، لهذا سید عنان عزیمت به وادی هزیمت معطوف، و به هندوستان رفته در دکن، توطن گزید. سلطان نظام شاه ارادت وی اختیار کرد، و طریقه ٔ حقه ٔ دین مبین اثناعشری در آن مملکت رواج یافت، هم در آن مملکت در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٩٥٦</span> هَ . ق . به روضه ٔ رضوان شتافت، جسدش را حسب الوصیه ٔ وی به عتبات عالیات برده سپردند. غرض، آن جناب صاحب اشعار متین، و این چند بیت از نتایج طبع آن جناب است : (من نصایحه و مواعظه ):<br />نظر کن بتاریخ شاهان پیشین <br />که رفتند زین دیر دیرین محافل <br />کجا شد فریدون فرخنده سیرت <br />کجا رفت کیخسرو آن شاه عادل <br />روان است پیوسته از شهر هستی <br />بملک عدم از پی هم قوافل <br />همان گیر کز فیض فضل الهی <br />شدی بهره مند از فنون فضایل <br />بکلک بدیع البیان معانی <br />در اقسام حکمت نوشتی رسائل <br />زدی تکیه بر مسند فضل و دانش <br />نهادند نام تو صدرالافاضل <br />چه حاصل که از صوب تحقیق دوری <br />به نزدیک دانا بچندین مراحل .<br />(فردی از غزلیّات او):<br />در غم او لذت عیش از دل ناشاد رفت <br />خو به غم کردیم چندانی که عیش از یاد رفت <br />(و از رباعیات اوست ):<br />در دهر کسی که عشق را شایدنیست <br />یاری که ازو دلی بیاساید نیست <br />صدگونه ملامت که نمیباید هست <br />یک لحظه فراغتی که میباید نیست .<br />گر کسب کمال میکنی میگذرد<br />ور فکر محال میکنی میگذرد<br />دنیا همه سربسر خیال است خیال <br />هر نوع خیال میکنی میگذرد.<br />مائیم که هرگز دم بیغم نزدیم <br />خوردیم بسی خون دل و دم نزدیم <br />بی شعله ٔ آه لب ز هم نگشودیم <br />بی قطره ٔ اشک چشم برهم نزدیم .<br />آنیم که کوس نیکنامی نزدیم <br />چون بیخردان دم از تمامی نزدیم <br />هرگز قدمی بخوشدلی ننهادیم <br />هرگز نفسی بشادکامی نزدیم .<br /> <font color=\"Red\">(ریاض العارفین صص <span class=\"hlight\" dir=\"rtl\">١٠٤</span> - <span class=\"hlight\" dir=\"rtl\">١٠٣</span>).</font><br />مؤلف قاموس الاعلام ترکی گوید: طاهر (شاه ...) یکی از شعرای ایران و اصلاً از سادات همدان بوده و در شهر قم میزیسته است، وی را بقبول طریقه ٔ اسماعیلی متهم ساخته بودند لذا به هندستان فرار کرد ومورد توجه سلطان نظام شاه گردید. اشعار پر معانی نغزدارد.<br /></font></div>'),
(175386, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) اصرم . رجوع به تاریخ سیستان صص <span class=\"hlight\" dir=\"rtl\">٣١٤</span> - <span class=\"hlight\" dir=\"rtl\">٣٢٤</span> شود.<br /></font></div>'),
(175387, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوالنصر در حبیب السیر چ قدیم تهران این صورت مصحف ظاهر ابوالنصر محمدبن الناصر لدین اﷲ عباسی است . رجوع به ظاهر... شود.<br /></font></div>'),
(175388, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن عبداﷲبن طاهربن عمر الطبری القاضی الفقیه الشافعی . کنیتش ابوالطیب . مردی ثقه وراستگو و متدین و پرهیزکار و آشنا به اصول و فروع فقه بود، وی محقق در علم، سلیم الصدر، و نیکخوی، با مذهبی استوار و صحیح بود، بر طریق فقها شعر میگفت . یکصدودو سال عمر یافت بی آنکه اختلالی در عقل یا تغییری در فهم او راه یابد فتوی میداد، و خطاء فقها را استدراک میکرد، و تا پایان عمر در بغداد بود، و همواره درموکب خلفا به دارالخلافه حضور می یافت . در آمل نزد ابوعلی زجاجی از یاران ابن القاص، فقه فرا گرفت . نزد ابوسعد اسماعیلی و ابوالقاسم بن کج نیز مدتی در گرگان تلمذ داشت . سپس به نیشابور رفته، ابوالحسن ماسرجسی رادریافت، و چهار سال مصاحب او بود و فقه را نزد او نیز تکمیل کرد. سپس رهسپار بغداد گردید. و در مجلس درس شیخ ابوحامد اسفراینی حاضر شد. شیخ ابواسحاق شیرازی نزد صاحب ترجمه به فراگرفتن علم اشتغال یافت، و میگفت مابین کسانی که نزد آنها شاگردی کرده ام، از قاضی طبری، کسی را در اجتهاد کاملتر، و در تحقیق دقیقتر و در نظر نیکوتر نیافتم . قاضی طبری، مختصر مزنی، و فروع ابوبکربن الحدّاد المصری را شرح کرد. و در اصول و مذهب و خلاف و جدل نیز تصنیفات بسیاری کرده . شیخ ابواسحاق گفته است بیش از ده سال ملازم مجلس قاضی طبری بودم، و به اذن و اجازه ٔ او برخی از اصحاب او را درس میگفتم، و مرا در حلقه ٔ او رتبتی خاص بود. قاضی طبری در بغداد توطن جسته، و پس از مرگ ابوعبداﷲ الضمیری و متولی امر قضاء ربع کرخ بغداد گردید، و تا هنگام وفاتش به امر قضا اشتغال داشت . مولد او در آمل به سال <span class=\"hlight\" dir=\"rtl\">٣٤٨</span> و وفاتش در دهم ربیعالاول سال <span class=\"hlight\" dir=\"rtl\">٤٥٠</span> هَ . ق . بود.یک روز بعد از وفاتش او را در مقبره ٔ باب حرب مدفون ساختند و در مسجد جامع منصور بر او نماز گذاردند. چنانکه صاحب کتاب وَفیات الاعیان نقل کرده است . (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>). ابن خلکان در وَفیات گوید: سمعانی درذیل آورده که ابواسحاق علی بن احمدبن الحسین بن احمدبن الحسین بن محمویة الیزدی را دستار و پیراهنی بود مشترک مابین او و برادرش . به این معنی که هر وقت یکی از دو برادر از خانه بیرون میشد، آن دستار و پیراهن را به کار میبرد، و برادر دیگر در خانه می نشست، و بالعکس . سمعانی گوید روزی با علی بن الحسین الغزنوی الواعظ بخانه ٔ ابواسحاق بن محمویه رفتیم سلامی دهیم . دیدیم برهنه است و اِزاری بخود پیچیده . او خود از برهنگی عذر خواست و گفت ما وقتی جامه های خود را میشوئیم مدلول شعر قاضی ابوالطیب الطبری درباره ٔ ما صادق آید:<br />قوم اذاغلواثیاب َ جمالهم <br />لبسواالبیوت َالی فراغ الغاسل <br /> <font color=\"Red\">(ابن خلکان چ تهران ص <span class=\"hlight\" dir=\"rtl\">٢٥٣</span>).</font><br />از تألیفات او نیز مختصری است درمولد شافعی، و تراجم احوال جمعی از اصحاب او. در کشف الظنون هم کتابی بنام «مخرج » از تألیفات صاحب ترجمه ایراد کرده است . و رجوع به تاریخ خطیب بغداد ج <span class=\"hlight\" dir=\"rtl\">٩</span> شود. او راست : شرح مختصر مزنی در فقه محتوی یازده جزءو نیز او را اشعاری است . (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٤</span>).<br /></font></div>'),
(175389, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن فضل حلبی . او را از سفیان بن عیینه و حجاج اعور روایت است . ابن حبان گوید: حدیث را به ثقات آن چنان نسبت میدهد که کتب حدیث او را نمیتوان جایز دانست جز با شگفتی و تعجب . محمدبن ایوب بن مشکان نیشابوری در طبریه از وی بما روایت کرده است سپس چهار حدیث پشت در پشت از وی آورده است . و حاکم گوید خبرهای موضوع روایت میکرد - انتهی . و در ثقات ابن حبان نیز درباره ٔ اوهمین داوری شده است . (از لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span>).<br /></font></div>'),
(175390, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن فضل بن سعید. وی ازسفیان بن عیینه روایت کرده است . محمدبن منذربن سعید ازدی به ما خبرداد که خطا میکند و راه خلاف می پیماید و او چنین کسی است و بنابراین یاد کردن نام او در زمره ٔ ثقات بروفق حقیقت نخواهد بود. و ابونسیم گوید: از ابن عیینه و حجاج بن محمد احادیث منکر ناچیزی روایت کرده است . و رجوع به لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> شود.<br /></font></div>'),
(175391, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن فخرالملک بن نظام الملک ملقب بناصرالدین در درج وزارت، و دری برج صدارت بود و بعد از عزل قوام الدین درگزینی به وزارت سلطان سنجر قیام نمود، بحسب تقدیر مقارن آن حال سلطان بی همال، در دست حشم غز گرفتار گشت و ناصرالدین قبل از آنکه از آن منصب تمتعی یابد، از جهان گذران درگذشت :<br />بگذاشته نقد زندگانی <br />بگذشت از این جهان فانی .<br /> <font color=\"Red\">(دستورالوزراء ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span>).</font><br />و صاحب تاریخ بیهق آرد: و عقب از فخرالملک بن نظام الملک صدرالدین محمد بود، و امیر اسحاق، و ناصرالدین طاهر، و امیر ابوالحسن علی، و امیر جمال الملک یوسف . و طاهر، و ابوالحسن و یوسف را، جمالی بود ارواح بدان بازنده، و دلها با آن سازنده، دیبای ملاحت پوشیده داشتند و ماه صباحت سر از افق گریبان ایشان برداشتند:<br />و کان یوسف فی الجمال اقامهم <br />خلفائه فی دهرنا من بعده .<br />صدرالدین محمد کشته آمد به بلخ فی سنة احدی عشرة و خمسمائة. ناصرالدین طاهر بیست سال شمسی، به انفاذ امرو تمکین، بی هیچ چشم زخم، در وزارت مدت یافت . و برسم وزارت دو سلطان، سلطان سنجر اعظم السلاطین که غایب بود، و سلطان سلیمان توقیع میفرمود، در یک دیوان نشسته . (تاریخ بیهق صص <span class=\"hlight\" dir=\"rtl\">٧٦</span> - <span class=\"hlight\" dir=\"rtl\">٧٥</span>). و رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥١٦</span> شود.<br /></font></div>'),
(175392, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن علی الجرجانی . چنانکه از فهرست شیخ منتجب الدین استنباطمیشود فقیهی فاضل بوده است . (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٣٣٦</span>).<br /></font></div>'),
(175393, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن علی بن مشکان ملقب به ثقةالملک . مرحوم قزوینی در حواشی چهارمقاله درباره ٔ وی آرد وزیر سلطان مسعودبن ابراهیم بود و شعرای عصر را از قبیل مسعودسعد و ابوالفرج رونی و مختاری غزنوی و سنائی غزنوی درحق وی مدایح غرّاست و وی برادرزاده ٔ ابونصر منصوربن مشکان دبیر معروف سلطان محمود و سلطان مسعود و مصنف کتاب «مقامات بونصر مشکان » و استاد تاریخ بیهقی صاحب تاریخ مسعودی است و تقریباً صفحه ای از تاریخ بیهقی از ذکر او خالی نیست و وفات وی یعنی بونصر مشکان در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٤٣١</span> هَ . ق . واقع گردید، (چهارمقاله ٔ نظامی چ لیدن حواشی مرحوم قزوینی ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span>) و مرحوم رشید یاسمی در مقدمه ٔ دیوان مسعودسعد مطالب مرحوم قزوینی را درباره ٔ طاهربن علی بدینسان آورده است : مسعودسعد در لاهور تاب مقاومت نیاورده به دادخواهی رهسپار غزنین شد.(ص <span class=\"hlight\" dir=\"rtl\">١٥١</span>) امید او در دربار سلطان مسعود به خواجه طاهربن علی ثقةالملک وزیر و خاص خازن شاه بود که بنابر قول نظامی عروضی برادرزاده ٔ ابونصر منصوربن مشکان (متوفی در <span class=\"hlight\" dir=\"rtl\">٤٣١</span>) رئیس دیوان رسایل سلطان محمود بزرگ و پسرش سلطان مسعود اول و استاد تاریخ بیهقی و صاحب کتاب مقامات بونصر مشکان بود شرح حال خواجه طاهر در لباب الالباب چ اروپا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٦</span> هست . سنائی در کارنامه ٔ بلخ او را مدح کرده است :<br />ثقة الملک طاهربن علی <br />پادشه چون نبی و او چو ولی <br />تا ترا کرد آسمان ظاهر<br />یک زمین است و طاهر و طاهر<br />مختاری هم او را مدح کرده است «طاهر ثقةالملک سردار گردن » یک زمانی حکومت لاهور داشته است . ابوالفرج رونی گوید:<br />بقدوم عزیز لوهاور<br />مصر کرد و ز مصر بیش بجاه <br />در این زمان بود که سلطان مسعود سفری به هندوستان کرد و ثقةالملک پذیرائی شایانی از او در لاهور نمود (ص <span class=\"hlight\" dir=\"rtl\">٣١٦</span>). از قصاید بسیاری که مسعود در ستایش او گفته آشکار است که میان آنان از دیرزمانی سابقه ٔ الفت برقرار بوده است . مسعودسعد بنده ٔ سی ساله من است . (ص <span class=\"hlight\" dir=\"rtl\">٤٣٠</span>) . باری نظر به این سابقه مسعودسعد شکایت لاهوریان را به او برد و پیغام داد که شغلی تازه به او بدهند خواجه طاهر پذیرفت و ابراز شادمانی کرد و مسعودسعد بار دیگر مسرور گشت که از نایبان دیوان شده است . (ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>).<br />گفتم آن شغل را بقوت این <br />ز سر امروز تازه گردانم <br />خواستم تا قباله بنویسم <br />نایبی را بشغل بنشانم .<br />ولی آن کار را باو ندادند و بیگانه ای را بر او ترجیح نهاده او را در چشم دوست و دشمن خوار کردند و شاعر رنجیده چنین گفت :<br />چون ز من مهر آمد اجنبئی <br />خیره اکنون زنخ چه جنبانم <br />در این قصیده اظهار رنجش کرده و بی نیازی خود را از شغلهای دیوانی ظاهر ساخته و توکل بخداوند نموده است ظاهراً حاسدان این رنجش او را چنان آب و تابی دادند که ثقةالملک از حمایت او سرد شد. (مقدمه ٔ دیوان مسعودسعد ص لح ). مسعودسعد این قصیده را در زندان بمدح ثقةالملک طاهربن علی اختصاص داده و درباره ٔ وی گوید:<br />در حال خوب گردد حال من ار شود<br />بر حال من دل ثقةالملک مهربان <br />خورشید سرکشان جهان طاهرعلی <br />آن چرخ با جلالت و آن بحر بیکران <br />ای آن جوان که چون تو ندیده ست چرخ پیر<br />یارست رای پیر ترا دولت جوان <br />هر کو فسون مهر تو برخویشتن دمد<br />ز آهنش ضیمران دمد از خار ارغوان <br />با جوش حشمت تو چه صحرا چه کوهسار<br />با زخم خنجرتو چه سندان چه پرنیان <br />دارد سپهر خوانده ٔ مهر ترا بناز<br />ندهد زمانه رانده ٔ کین تراامان <br />بالای رتبت تو گذشته ز هر فلک <br />پهنای بسطت تو رسیده به هر مکان <br />یکماهه دولت تو نگشته ست هیچ چرخ <br />یک روزه بخشش تو ندیده ست هیچ کان ...<br />و رجوع به «ثقةالملک » خواجه طاهربن علی در همین لغت نامه و احوال و اشعار رودکی صص <span class=\"hlight\" dir=\"rtl\">٦٣٧</span> - <span class=\"hlight\" dir=\"rtl\">٦٣٩</span> و سبک شناسی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٧</span> و فهرست کتب کتابخانه ٔ سپهسالار ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٦٧٦</span> - <span class=\"hlight\" dir=\"rtl\">٦٧٧</span> شود.<br /></font></div>'),
(175394, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ )ابن عرب بن احمد، استاذ القراء الاصبهانی . وفات وی به سال <span class=\"hlight\" dir=\"rtl\">٧٨٦</span> هَ . ق . بوده است . وی را قصیده ای است به نام قصیدةالطاهریة در قراآت عشرة، این قصیده بوزن قصیده ٔ شاطبیه است . قصیده ٔ دیگری نیز در اختلاف آیات بنظم آورده، و آن را نظم الجواهر نام نهاده، و مطالبی سخت تازه و بدیع در آن ایراد کرده است . (کشف الظنون ).<br /></font></div>'),
(175395, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن عبدالمنعم . در تاریخ حلب نسب وی را از تاریخ ذهبی بدین طریق بیان کرده : طاهربن عبدالمنعم بن عبیداﷲبن غلبون ابوالحسن الحلبی ثم المصری المقری . کتاب «التذکرة فی القراآت » از تصنیفات اوست، و جز آن نیز تصنیفات دارد، از بزرگان علماء علم قرائت بود و پدرش نیز، نزد پدر خود و نزد ابوعدی عبدالعزیزبن علی المصری در مصر، و نزد ابوالحسن علی بن محمدبن صالح الهاشمی که از اصحاب ابوالعباس اشنانی بود، و نزد ابوالحسن محمدبن یوسف بن نهار الحرتکی در بصره به فراگرفتن علوم اشتغال ورزید و در علم قرائت مقام پیشوایی یافت ابوعمرو دانی و ابراهیم بن ثابت اقلیسی نزد او علم قرائت را فراگرفتند، ابوالفتح احمدبن بابشاذ، و محمدبن احمدبن علی القزوینی، و جز آن دو تن، گروهی دیگر، کتاب «التذکرة» را از طاهر روایت کرده اند. وفاتش به سال <span class=\"hlight\" dir=\"rtl\">٣٩٩</span> اتفاق افتاد. (تاریخ حلب ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩</span>). رجوع به ابوالحسن طاهربن عبدالمنعم شود. در جلد اول لغت نامه در ابن غلبون بجای عبدالمنعم، عبدالحلیم ضبط شده . ولی در تاریخ حلب و الاعلام زرکلی و کشف الظنون همه جا عبدالمنعم است . و رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٤</span> شود.<br /></font></div>'),
(175396, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن عبداﷲ بیهقی (شیخ الرئیس ) مؤلف تاریخ بیهق آرد: او از دستگرد ربع کاه بوده است و خواجه عبداﷲ دستجردی از فرزندان او بود و این خواجه عبداﷲ را من دیده ام . مردی با فضل و کفایت بود از ادبای قصبه، معانی ابیات پرسیدی و اصلاح المنطق بر طرف اللسان داشتی و خواجه طاهربن عبیداﷲ را که جد او بوده خواجه ابومنصور ثعالبی در کتاب تتمةالیتیمه بیارد و استاد یعقوب ذکر و شعر وی در کتاب جونةالند اثبات کند. خواجه طاهر دستجردی گوید احمدبن عثمان الخشنامی را:<br />یا ابن عثمان یا کریم السجایا<br />حاطک اﷲ من جمیع البلایا.<br />انت فی الفضل والبلاغة و الظر<br />ف و زهر الخصال فقت البرایا<br />صح لما رایتک الیوم عندی <br />قولهم ان فی الزوایا خبایا.<br />و او را اعقاب بود خواجگان با کفایت خواجه سدیدالدین الحسینی که عمل طخارستان داشت، و خواجه ابوعلی طاهر که عمل نیشابور و بیهق داشت، توفی سدیدالحسین یوم السبت الثانی عشر من ذی القعدة سنة خمسین و خمسائة بسبزوار، و توفی اخوه مجیرالدین طاهر ابوعلی یوم الاثنین الحادی والعشرین من ذی القعده سنة خمسین و خمسمائة ایضاً تعصبة السبزوار و کانا فی خدمة الامیر الاسفهسالار حسام الدین قزل السطانی رحمة اﷲ علیهم اجمعین . (تاریخ بیهق ص <span class=\"hlight\" dir=\"rtl\">١٩١</span>). و رجوع به تتمةالیتیمة ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٣٤</span> - <span class=\"hlight\" dir=\"rtl\">٣٥</span> شود.<br /></font></div>'),
(175397, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن عبداﷲ البیع ابی سعید النحوی چنانکه ازتاریخ حافظ محب الدین بن النجار نقل شده، ابوعبدالرحمن السلمی، قطعه ای چند از اشعار طاهر در ضمن امالی ومجموعات خویش روایت کرده است . رجوع به روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>، ذیل ترجمه ٔ طاهربن عبداﷲبن عُمرالطبری شود.<br /></font></div>'),
(175398, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن فضل . برادرزاده ٔ ابوعلی (احمدبن محمدبن المظفربن محتاج ) ابوالمظفر طاهربن الفضل بن محمدبن المظفربن محتاج والی چغانیان بودو در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٣٧٧</span> وفات یافت و ترجمه ٔ حالش در لباب الالباب مذکور است (ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٢٧</span>-<span class=\"hlight\" dir=\"rtl\">٢٩</span>) و وی امیری بغایت فاضل وهنرپرور بود و خود شعر گفتی و شاعران را بغایت دوست داشتی و منجیک ترمذی از مداحان اوست . (حواشی چهارمقاله بقلم قزوینی ص <span class=\"hlight\" dir=\"rtl\">١٦٥</span>) عوفی شرح حال وی را بدینسان آورده است : الامیر ابوالمظفر طاهربن الفضل بن محمد محتاج الچغانی، امرای چغانیان در آن عهد نامدار بودند واین امیر ابوالمظفر نادره ٔ عهد و یگانه ٔ عصر خود بوده است و در دولت و مکنت پای بر فرق فرقد نهاده و دررفعت و قوت کمر از میان جوزا گشاده . و جد او ابوبکرمحمد مظفر محتاج بود که در امارت خود اگر بفلک اشارت کردی از دور خود بازایستادی و اگر بر آتش و آب حکم کردی از اغراق و احراق ممتنع شدندی و عم او امیر عالم ابوعلی احمد مظفر رحمه اﷲ که جهان علم و مکان حلم بود، کان محامد و اختر آسمان . مناقب و ذکر این خاندان معظم در تاریخ ناصری مسطور است و در سایر تواریخ مذکور. امیرطاهر بافضلی ظاهر... وافر بود هم بر ممالک چغانیان ملک و هم در ولایت هنر و بیان سلطان بود وفات او در سنه ٔ سبع و سبعین و ثلث مائة (<span class=\"hlight\" dir=\"rtl\">٣٧٧</span> هَ . ق .) اتفاق افتاد او را اشعار لطیف آبدار است اما آنچه این مجموعه احتمال کند آن است که در فقاع لغزی میگوید در غایت سلاست و لطافت و دقت معنی و رقت فحوی . شعر:<br />لعبتی سبزچهر تنگ دهان <br />بفزاید نشاط پیر و جوان <br />معجر سر چو ز آن برهنه کنی <br />خشم گیرد کف افکند ز دهان <br />ور بخواهی ورا که بوسه زنی <br />او بخندد ترا کند گریان .<br />و امیر سیف الدوله ابوالحسن علی بن عبداﷲ احمد رحمه اﷲ این قطعه ٔ تازی انشا کرده است در صفت قوس و قزح :<br />و ساق صبیح للصبوح دعوته <br />فقام و فی اجفانه سنة الغمض <br />یطوف بکاسات العقار کخمرها<br />فمن بین مستعص علینا و منقض <br />و قد نشرت ایدی الجنوب مطارفاً<br />فاحمر فی اید و اخضر مبیض <br />یطرزها قوس السحاب باصفر<br />علی الجود کناء الحواشی علی الارض <br />کاذیال خود اقبلت فی عذائر<br />مصبغة والبعض اقصر من بعض <br />این ابیات به امیر طاهربن الفضل رسید هر بیتی را بنظم ترجمه کرد با پارسی و آن این است :<br />آن ساقی مهروی صبوحی بر من خورد<br />وز خواب دو چشمش چو دو تا نرگس خورم <br />وآن جام می اندر کف او همچو ستاره <br />ناخورده یکی جام و دگر داده دمادم <br />و آن میغ <font color=\"DarkGreen\"><b>[ جنو ]</font></b> بی چو یکی مطرب خور بود<br />دامن به زمین برزده همچون شب ادهم <br />بربسته هوا چون کمری قوس قزح را<br />از اصفر و از احمرو از ابیض معلم <br />گوئی که دو سه پیرهن است از دو سه گونه <br />وز دامن هر یک ز دگر تار یکی کم <br />و هم او راست در غزل میگوید:<br />دلم تنگ دارد بدان چشم تنگ <br />خداوند دیبای فیروزه رنگ <br />بچشم گوزن است و رفتارکبک <br />بکشی چو گور است و کبر پلنگ <br />سخن گفتنش تلخ و شیرین دو لب <br />چنانک از میان دو شکر شرنگ <br />کمان دو ابروش و آن غمزه ها<br />یکایک بدل بر چو تیر خدنگ <br />بدان ماند آن بت که خون مرا<br />کشیده ست بربور تازیش تنگ <br />یکی فال گیریم و شاید بدان <br />که گیتی به یک سان ندارد درنگ .<br />و گویند او را اسپی بود سیاه تازی که با باد بازی کردی . نظم :<br />چو سب بود و هرگه که بشتافتی <br />بتک روز بگذشته دریافتی .<br />این دو بیت در صفت نرگس خود گفته :<br />چرا باده نیاری ماه رویا<br />که بی می صبر نتوان بر قلق بر<br />بنرگس ننگری تا چون شکفته ست <br />چو رومی جام بر سیمین طبق بر.<br />و هم او در صفت نرگس گوید:<br />آن گلی کش ساق از میناء سبز<br />بر سرش بر سیم و زر آمیخته <br />ناخن حوریست گوئی کرد گرد<br />دیده ٔ باز از میانش انگیخته .<br />و این دو رباعی هموگفته :<br />یک شهر همی فسون و رنگ آمیزند<br />تا بر من و بر تو رستخیز انگیزند<br />با ما بحدیث عشق ما چه استیزند<br />هر مرغی را بپای خویش آویزند.<br />دلدار منا ترا صدف خواهم کرد<br />آخر بمدارات بکف خواهم کرد.<br />(بیت دوم رباعی در لباب الالباب نیامده است ). (لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧</span> تا ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>).<br />سعید نفیسی نوشته است : طاهربن فضل ابوالعباس بن ابوبکر محمدبن ابوسعد مظفربن محتاج چغانی (ابوالمظفر یا ابویحیی ) از امرای چغانیان که شعر پارسی میگفته و منجیک یکی از قطعات اشعار اورا جواب گفته است و نیز کنیه ٔ او را ابویحیی ضبط کرده اند و این کنیه درست تر مینماید و احتمال میرود که با کنیه ٔ احمدبن محمدبن احمدبن محمدبن مظفر که ابوالمظفر بوده است اشتباه کرده باشند. (احوال و اشعار رودکی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦٤</span>) و در صفحه ٔ <span class=\"hlight\" dir=\"rtl\">١٢٩٩</span> همان جلد آورده اند:ابومحمد بدیعبن محمدبن محمود بلخی ... متخلص به بدایعی بلخی مداح امیرابویحیی طاهربن ابوالعباس فضل بن ابوبکر محمدبن ابوسعد مظفربن محتاج چغانی بوده است که پیش از این ذکر او گذشت و منجیک ترمذی و لبیبی نیز مداحان او بوده اند این امیر ابویحیی طاهربن فضل که کنیت او را گویا به خطا ابوالمظفر هم نوشته اند در ادبیات فارسی معروفترین امیر خاندان چغانیان و یا آل محتاج است زیرا که خود نیز شعر فارسی میگفته است . نام ونسب و کنیت او را به خطا ابوالمظفر طاهربن ابوالفضل بن محمد محتاج و محمدبن مظفربن محتاج و طاهربن ابوالفضل محمد هم ضبط کرده اند و گفته اند که در زمان سلطان محمود در بلخ حکمرانی داشته و این نکته درست نیست زیرا که وی در <span class=\"hlight\" dir=\"rtl\">٣٧٧</span> هَ . ق . درگذشته و قطعاً از امرای پیوسته به خاندان سامانی بوده است رجوع کنید به لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٢٧</span> - <span class=\"hlight\" dir=\"rtl\">٢٩</span> و مجمعالفصحا ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٣٧</span> - <span class=\"hlight\" dir=\"rtl\">٣٨</span> و در لباب الالباب و مجمعالفصحا <span class=\"hlight\" dir=\"rtl\">٢٢</span> بیت از اشعار او ثبت شده است از آن جمله این قطعه است که بیت دوم آن ازمنابع دیگر به دست می آید:<br />چرا باده نیاری ماهرویا<br />که بی می صبر نتوان برقلق بر<br />بده باده بیاد ماهروئی <br />که بی وی صبر نتوان در خلق بر<br />بنرگس ننگری تا چون شکفته ست <br />چو رومی جام بر زرین طبق بر.<br />و این رباعی است که بیت اول آن در لباب الالباب آمده و بیت دوم از مأخذ دیگر فراهم میشود:<br />دلدار منا ترا صدف خواهم کرد<br />آخر بمدارات بکف خواهم کرد<br />یا آنکه ترا بمهر خود رام کنم <br />یا عمر بعشق تو تلف خواهم کرد.<br />(از احوال و اشعار رودکی ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">١٢٩٩</span> - <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span>). عوفی این ابیات را از قصیده ای که بدایعی بلخی در مدح طاهربن الفضل الصغانی گفته، در لباب الالباب آورده است :<br />هوا روی زمین را شد مطرّز<br />بساقی آب دریای بقرمز (کذا)<br />نفیر ابر فروردی برآمد<br />ز بانگ رود بانگ رود عاجز<br />بدان منگر که می منع است می خور<br />لوقت الورد شرب الخمر جائز<br />نگاری باید اکنون خلخی زاد<br />برخساره بت چین را مجاهز<br />بمیدان نشاط اندر خرامد<br />نبشته برقدح هل من مبارز<br />بیاد سید حران عالم <br />ابویحیی الذی یحیی به العز<br />مگرد ای چرخ گردان جز به نیکی <br />بر این رستم دل ِ حاتم جوائز.<br /> <font color=\"Red\">(لباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٢٢</span> - <span class=\"hlight\" dir=\"rtl\">٢٣</span>)</font><br />و منجیک شاعر نیز یکی از مداحان طاهربن الفضل است که عوفی در ذیل ترجمه ٔ احوال او گوید و در قصیده ای میگوید در مدح امیر فاضل مفضل ابوالمظفر طاهربن الفضل بن محمدبن محمد المظفر، سقی اﷲ ثراه :<br />مرا ز دیده گرفت آفتاب خواب زوال <br />کجا برآمد خیل ستارگان خیال <br />هزار دستان آواز داد گفت چه بود<br />مرا ز شاخ فکندی بناله بیش منال .<br />و در اینجا میگوید:<br />خدایگانا فرخنده مهرگان آمد<br />ز باغ گشت بتحویل آفتاب احوال <br />کجاست آنکه پدرش آهنست و مادر سنگ <br />عدوی عود و عبیر و جزای کفر و ضلال <br />سرای پرده صحبت کشید سیب و ترنج <br />بطبل رحلت برزد گل و بنفشه دوال <br />بگوی تا بفروزند و برفرازانند<br />بدو بسوزان دی را صحیفه ٔ اعمال <br />به طبع چون جگر عاشقان طپیده و گرم <br />برنگ چون علم کاویان خجسته بفال .<br /> <font color=\"Red\">(لباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">١٣</span> - <span class=\"hlight\" dir=\"rtl\">١٤</span>)</font><br />و این بیت منجیک که در لغت نامه ٔ اسدی در مدح ابوالمظفر آمده، ظاهراً یکی از اشعار مربوط به قصیده ٔ بالاست :<br />ابوالمظفر شاه چغانیان که برید<br />به تیز دشنه ٔ آزادگی گلوی سؤال <br />رجوع به «ابوالمظفر چغانی طاهربن الفضل » شود. مرحوم اقبال، در تعلیقاتی که بر حدائق السحر وطواط ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span> نوشته، آرد: عوفی در لباب الالباب (ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣</span>) این قصیده را (مقصود قصیده ٔ لامیه ٔ منجیک است )، در مدح امیرطاهربن فضل بن محمدبن محتاج چغانی، ممدوح دیگر منجیک، و برادرزاده ٔ ابوعلی چغانی، دانسته و کنیه ٔ او را ابوالمظفر ذکر کرده است .به عقیده ٔ نگارنده عوفی را در این موضوع اشتباه دست داده . چه کنیه ٔ امیر طاهربن فضل که خود از شعرای معروف بوده، بتصریح گردیزی در زین الاخبار ص <span class=\"hlight\" dir=\"rtl\">٥٣</span> از چ برلن، و چ تهران ص <span class=\"hlight\" dir=\"rtl\">٤١</span>، ابوالحسن است، نه ابوالمظفر. در این مورد قاعدةً باید، کنیه ٔ فخرالدوله، احمدبن محمدچغانی، ممدوح مشترک دقیقی و فرخی باشد. فرخی در حق او میگوید:<br />فخر دولت بوالمظفر شاه با پیوستگان <br />شادمان و شادخوار و کامران و کامکار<br />و در قصیده ٔ دیگرمیگوید:<br />میراحمد محمد شاه جهان پناه <br />آن شهریار کشورگیر جهان ستان <br />و منجیک در ضمن قصیده ای که قسمتی از آن در (مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠٧</span>) مضبوط است، گفته :<br />هوی قضاست، هوی را بحیله نتوان زد<br />چه پرنیان ببر تیر او، چه ز آهن سد<br />هوی است اینکه همی داردم در این شبها<br />منادم الدبران و مراعی الفرقد<br />پر از بدایع لفظ و پر از صنایع دست <br />پر از مخاوف چشم و پر از طرائف خد<br />فغان من همه زان جعد بی تکلف تست <br />فکنده طبع بر او بر هزارگونه عقد<br />رسیده آفت نشبیل او به هر گامی <br />فکنده کشته ٔ آسیب او به هر مشهد<br />چنو نبوده نه هست و نه نیز خواهد بود<br />فراق او متواتر هوای او سرمد<br />بسان عمر و عطای خدایگان جهان <br />ابوالمظفر شاه چغانیان احمد<br />همه صفات خداوند بر تو زیبا هست <br />برون از این دو صفت، لم یلد، و لم یولد<br />بدانگهی که برآورده شد زمین از گرد<br />نه وادی از که پیدا، نه ابیض از اسود<br />بپشت مردان بر، پاره کرده زخم زده <br />بروی اسبان بر، سرخ کرده خون مقود<br />ایابدیع شهی کت نظیر نه به جهان <br />میان خلق چو سیمرغ مفردی مفرد<br />اشتباه دیگری که صاحب لباب الالباب را دست داده، در ذکر تاریخ وفات امیرطاهربن فضل است . چه عوفی آن را سال <span class=\"hlight\" dir=\"rtl\">٣٧٧</span> هَ . ق . میداند، درصورتی که در تاریخ یمینی (در ضمن وقایع سلطنت نوح بن منصور، و اخبار فائق خاصه ) و زین الاخبار (ص <span class=\"hlight\" dir=\"rtl\">٥٣</span> چ تهران ص <span class=\"hlight\" dir=\"rtl\">٤١</span>) صریح است که او در ضمن جنگ، با امیر ابوالمظفر، احمدبن محمد چغانی در سال <span class=\"hlight\" dir=\"rtl\">٣٨١</span> فراری و مقتول شده . زمان منجیک از ملاحظه ٔ زندگانی و عصر ممدوحین او مقارن میشود با نیمه ٔ دوم قرن چهارم هجری و این ایام واسطه ٔ بین زمان دقیقی و فرخی است . احتمال قوی میرود که این شاعر و دقیقی و فرخی هر سه، فخرالدوله ابوالمظفر، احمدبن محمد چغانی را مدح گفته باشند، ولی به فواصلی . ظاهراً دقیقی اوایل عهد، و منجیک اواسط، و فرخی اواخر روزگار او را درک کرده، و از صلات و مواهب او که بقول صاحب چهارمقاله «این نوع را تربیت میکرده، و این جماعت را صله و جائزه ٔ فاخره میداد» بهره هابرده اند. امر مسلم اینکه لامیه ٔ منجیک که ذیلا تمام آن را ایراد میکنیم، در مدح امیرابوالحسن طاهربن فضل مقتول در <span class=\"hlight\" dir=\"rtl\">٣٨١</span> هَ . ق . نیست . بلکه در مدح امیرابوالمظفری است که به قرائن باید همان ابوالمظفر فخرالدوله احمدبن محمد چغانی، ممدوح مشترک دقیقی و فرخی باشد. و آن قصیده که ما ابیات متفرق آن را از فرهنگ اسدی، و حدائق السحر، والمعجم، و لباب الالباب، و یک جنگ خطی، و هفت اقلیم، و مجمعالفصحاء استنساخ کرده و بهم پیوسته ایم این است :<br />مرا ز دیده گرفت آفتاب خواب زوال <br />کجا بتابد خیل ستارگان خیال .<br />(الی آخر، <span class=\"hlight\" dir=\"rtl\">٣٨</span> بیت ) (تعلیقات اقبال بر حدائق السحر صص <span class=\"hlight\" dir=\"rtl\">١٣٧</span> - <span class=\"hlight\" dir=\"rtl\">١٤٣</span>). طاهربن الفضل، خود شعر نیک میسروده، و اسدی در فرهنگ خود شواهد بسیاری برای لغات مندرجه در فرهنگش از اشعار او ایراد کرده است . مؤلف مجمعالفصحاءگوید: ملک طاهر چغانی، نامش امیر ابوالمظفر ملک طاهربن ابوالفضل محمد المحتاج الچغانی . و ملک چغانیان از ماوراءالنهر است و صغانی معرب آن است . همه ٔ اجدادش از امرا و ملوک و سلاطین بوده اند. و حکومت طخارستان مینمودند. وی از ملوک معاصر سلطان محمود غزنوی است . و بلخ مرکز حکومت وی بوده، ابوالحسن فرخی نخست به بلخ آمده، بخدمت وی راه یافته، قصیده ٔ داغگاه در مدح وی گفته است، و اسبها از وی بصله برده است . دقیقی مروزی نیز مداح این طبقه بوده است . علی الجمله فرخی بتوسط وی به سلطان رسیده، جامع کمالات محموده و خصائل ستوده و فضل شافی و علم کافی بوده . گاهی بیتی موزون میکرده، از اوست :<br />بچشم گوزن است و رفتار کبک <br />بکشی چو گور و بکینه پلنگ <br />سخن گفتنش تلخ و شیرین دولب <br />چنان کز میان دو شکر شرنگ <br />کمانی دو ابروش وان غمزه ها<br />یکایک بدل بر چو تیر خدنگ .<br />یک شهر همی فسون و رنگ آمیزند<br />تابر من و برتو رستخیز انگیزند<br />با ما بحدیث عشق تا چه استیزند<br />هر مرغی را بپای خود آویزند.<br /> <font color=\"Red\">(مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧</span> و <span class=\"hlight\" dir=\"rtl\">٣٢٧</span>).</font><br />صاحب تاریخ یمینی آرد: طاهربن فضل، کسی است که ناحیت صغانیان را از بوالمظفر محمدبن احمد بستده بود به تغلب . و در ولایت او نشسته . و ابوالمظفر چون از ولایت خویش منزعج شد، به اهتمام فایق التجا ساخت، و از او مدد خواست، و فائق حق وفادت او و خانه و بزرگی و جلالت قدر و وجاهت و نباهت ذکر، و آنکه از امراء خراسان به اصالت و قدمت خاندان و فضائل ذات متفرد بود، به اکرام و ایجاب تلقی کرد، و لشکر خود را در خدمت او بفرستاد تا او را به مقر خویش بازرسانند، طاهر چون خفت حال، و قلت اعوان فائق، و خلو عرصه ٔ بلخ بدانست طمع در استخلاص بلخ بست، با حشم خویش به حصار بلخ آمد. عامه ٔ شهر بیرون آمدند و جنگ آغاز کردند. یکی از جمله ٔ اعراب طاهر را بشناخت، او را از طعنه ٔ از مرکب بینداخت، و فرود آمد و سرش برداشت . و چون لشکر او از حال او خبر یافتند، منهزم شدند، و هر یک از جانبی جان بیرون برد. (تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١١٤</span> و <span class=\"hlight\" dir=\"rtl\">١١٥</span>). فایق به بخارا بازگشت بفرمان . و ایخ حاجب، و بکتوزون با وی حرب کردند. او را هزیمت کردند. به بلخ شد. و چغانیان ابوالحسن طاهربن الفضل را دادند. امیر طاهربن الفضل بیامد.و ابوالمظفر به نزدیک فائق شد. و فائق او را نصرت کرده و با طاهربن الفضل حرب کرد. و طاهر اندرآن معرکه کشته شد. (زین الاخبار گردیزی چ تهران ص <span class=\"hlight\" dir=\"rtl\">٤١</span>). مرحوم قزوینی در تعلیقات چهارمقاله راجع به بیت زیر از قصیده ٔ داغگاه فرخی که میگوید:<br />بر در پرده سرای خسرو پیروز بخت <br />از پی داغ آتشی افروخته خورشیدوار<br />می نویسد مجمعالفصحا عمداً کلمه ٔ خسرو را بدل به طاهر کرده، و قصیده را در مدح ابوالمظفر طاهربن الفضل چغانی دانسته، و آن سهو است . (چهارمقاله ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>) راذویانی در ترجمان البلاغه این دو بیت ازطاهربن الفضل الصغانی آورده است :<br />بر مملکت سوار نگشتی تو از گزاف <br />و آزداگانت بنده نگشتند خیر خیر<br />ایدون بموقعی بمدارای روزگار<br />کز نیش نوش مکی وز باده شیر سیر.<br />در لغت نامه ٔ اسدی ابیات ذیل نیز ازطاهربن الفضل به استشهاد آورده شده است :<br />گر خدو را بر آسمان فکنم <br />بی گمانم که بر چگاد آید.<br /> <font color=\"Red\">(فرهنگ اسدی ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span>)</font><br />روا نبودی زندان و بند و بست تنم <br />اگر نه زلفک مشکین او بدی جلویز.<br /> <font color=\"Red\">(فرهنگ اسدی ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span>)</font><br />فاش شد نام من به گیتی فاش <br />من نترسم ز جنگ و ز پرخاش .<br /> <font color=\"Red\">(فرهنگ اسدی ص <span class=\"hlight\" dir=\"rtl\">٢١٣</span>)</font><br />اشک باریدش و نیوشه گرفت <br />باز بفزود گفته های دراز.<br /> <font color=\"Red\">(فرهنگ اسدی ص <span class=\"hlight\" dir=\"rtl\">٢١٧</span>)</font><br />نادان گمان بری و نه آگاهی <br />از تُنبل و عزیمت و نیرنگش .<br /> <font color=\"Red\">(فرهنگ اسدی ص <span class=\"hlight\" dir=\"rtl\">٢٨٨</span>)</font><br />ای جوجگک به سال و ببالا بلندزه <br />ای با دو زلف بافته چون دو کمندزه .<br /><font color=\"Red\">(فرهنگ اسدی ص <span class=\"hlight\" dir=\"rtl\">٣٠٤</span>)</font><br /></font></div>'),
(175399, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن عبداﷲبن طاهربن الحسین الخزاعی . نواده ٔ طاهر ذوالیمینین، وی بعد از فوت پدر افسر امارت بر سر نهاد، و ایام حکومتش تا زمان المستعین باﷲ امتداد یافته، به اجل طبیعی درگذشت . او در سال <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> هَ . ق . به امارت خراسان منصوب شد و تا سال <span class=\"hlight\" dir=\"rtl\">٢٤٨</span> مدت هیجده سال بدین شغل باقی بود. و در همان سال نیز وفات یافت . رابینو در سفرنامه ٔ مازندران ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span> گوید که طاهربن عبداﷲبن طاهر، یک سال و سه ماه نیز در مازندران امارت داشته است . گردیزی گوید: پس واثق خراسان مر طاهربن عبداﷲ را داد. و کنیت طاهر ابوالطیب بود. ابوالطیب اندر این وقت به طبرستان بود، به نیشابور بازآمد، و مصعب بن عبداﷲ را خلیفه کرد، و واثق بمرد اندر ذوالحجه سنه ٔ <span class=\"hlight\" dir=\"rtl\">٢٣٢</span> هَ . ق .و متوکل به خلافت بنشست . و عهد خراسان سوی طاهر فرستاد، و چون یک چندی برآمد، متوکل را بکشتند. و منتصر به خلافت بنشست، و عهد خراسان به طاهر فرستاد. و ابوالحسن شعرانی چنین گفت که طاهر خادمی داشت سپیدپوست ونیکوروی، به من داد که این را بفروش . و خادم بسیار زاری کرد و بگریست، من توقف کردم که بس خوب خادمی بود، و به امیر رجوع کردم که این خادم را چرا میفروشی، گفت شبی اندرسرای خفته بود، و باد جامه از او بازافکند، و من او را بدیدم، بچشمم خوب آمد، و همی بترسم که مبادا دیو مرا وسوسه کند، پس فرمود تا هدایا بساختند، و او را با هدیه های دیگر نزدیک متوکل بفرستادند. روزی رقعه ای نوشتند بدو، اندر رقعه گفتند: «اگر رای رشید او صواب بیند» توقیع زد که نخواهم که مرا رشید خوانند، که این نام بر کسی نهند که خدای عز و جل او را سزاوار آن کرده باشد. و چون منتصر بمرد، مستعین به خلافت بنشست، و ولایت خراسان بر طاهر نگاهداشت، و طاهر فرمان یافت اندر سنه ٔ <span class=\"hlight\" dir=\"rtl\">٢٤٨</span> هَ . ق . (زین الاخبار ص <span class=\"hlight\" dir=\"rtl\">٤</span> چ تهران ). و صاحب قاموس الاعلام آرد: طاهربن عبداﷲبن طاهر ذوالیمینین نام حکمران چهارم از امرای بنی طاهردر خراسان است وی نوه ٔ طاهر ذوالیمینین بوده و به سال <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> هَ . ق . پس از وفات پدرش عبداﷲ به حکم منشور واثق خلیفه در خراسان حکمرانی کرد و بعدل و طرفداری از حق و حقانیت و کرم و سخاوت شهرت یافت و پس از <span class=\"hlight\" dir=\"rtl\">١٨</span> سال فرمانروائی به سال <span class=\"hlight\" dir=\"rtl\">٢٤٨</span> هَ . ق . درگذشت، آنگاه پسرش محمد که آخرین حکمران آل طاهر است جانشین وی گردید- انتهی . و رجوع به تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">١٩١</span>، <span class=\"hlight\" dir=\"rtl\">١٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٥</span> و مزدیسنا ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span> و تاریخ بیهق ص <span class=\"hlight\" dir=\"rtl\">١٣٨</span>، <span class=\"hlight\" dir=\"rtl\">١٥٧</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٥</span> احوال و اشعار رودکی صص <span class=\"hlight\" dir=\"rtl\">٢٢١</span> - <span class=\"hlight\" dir=\"rtl\">٣٠٩</span> و تاریخ گزیده صص <span class=\"hlight\" dir=\"rtl\">٣٢١</span> - <span class=\"hlight\" dir=\"rtl\">٣٢٧</span> و تتمةالیتیمة ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">١٣٠</span> - <span class=\"hlight\" dir=\"rtl\">١٣١</span> و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٤</span> و حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٢</span> و <span class=\"hlight\" dir=\"rtl\">٣٤٤</span> شود.<br /></font></div>'),
(175400, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b>(اِخ ) ابن عبدالعزیزبن عیسی بن سیار، ابوالحسن الدعاء، معروف به «ابن الحصری » از ابوبکربن مالک قطیعی، واسحاق بن سعدبن الحسن بن سفیان النسوی سماع حدیث کرده . خطیب گوید: من خود از او حدیث فراگرفته و به قید کتابت آوردم . از بندگان صالح خداوند بشمار میرفت . و مردی پارسا بود و صدوق . از او شنیدم که گفت مولدش در سال <span class=\"hlight\" dir=\"rtl\">٣٥٦</span> هَ . ق . بوده، و در ماه جمادی الاخرة یا رجب سال <span class=\"hlight\" dir=\"rtl\">٤٢٥</span> از دنیا رحلت کرد. (تاریخ خطیب ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٨</span>).<br /></font></div>'),
(175401, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن عبدالعزیز، صاحب عقدالفرید. نام وی را (صفحه ٔ <span class=\"hlight\" dir=\"rtl\">١٢١</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span> چ محمد سعید العریان ) ذیل عنوان باب الحلم و دفع السیئة بالحسنة بدینسان آرد: و انشد طاهربن عبدالعزیز:<br />اذا ما خلیلی اسامرةً<br />و قدکان من قبل ذا مجملا<br />تحملت ما کان من ذنبه <br />و لم یفسد الاَّخر الاوّلا.<br />و در صفحه ٔ <span class=\"hlight\" dir=\"rtl\">٣٣٥</span> همان جلد ذیل باب التماس الرزق و مایعود علی الاهل والولد آرد: قال طاهربن عبدالعزیز: اخبرنا علی بن عبدالعزیز قال انشدنا ابوعبید القاسم بن سلام :<br />لاینقص الکامل من کماله <br />ماساق من خیر الی عیاله .<br />و رجوع به ماده ٔ بعد شود.<br /></font></div>'),
(175402, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن عبدالرشید البخاری . او راست : کتابی بنام خلاصة الفتاوی . زیلعی محدث، احادیث کتاب مزبور را تخریج کرده است . وفات طاهر در سال <span class=\"hlight\" dir=\"rtl\">٥٤٢</span> هَ . ق . بود. او حنفی مذهب، و لقبش افتخارالدین است، و جز کتاب خلاصة الفتاوی در دو مجلد در فقه حنفی کتب دیگری نیز در فقه حنفیه تألیف کرده . از آن جمله است : نصاب الفقیه، خزانة الفتاوی، خزانة الواقعات، واقعات فی الفروع . ولادت وی به سال <span class=\"hlight\" dir=\"rtl\">٤٨٢</span> هَ . ق . و از بزرگان فقهاء حنفیه بخارا بود. رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٣</span> شود.<br /></font></div>'),
(175403, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن عبدالرحمن بن اسحاق بن ابراهیم بن سلمة الضبی مولاهم کنیه ٔ وی ابوالقاسم است . پدرش در بغداد قاضی بود. وی از علی بن جعد، و علی بن مدینی، روایت دارد. عبدالصمدبن علی الطستی، و سلیمان بن احمد الطبرانی از او روایت کنند. خبر داد ما را ابوالقاسم الحسن بن الحسن بن علی بن المنذر القاضی خبر داد ما را عبدالصمدبن علی الطستی، خبر داد ما را طاهربن عبدالرحمن بن اسحاق القاضی از علی بن الجعد، از ابویوسف از عبداﷲبن علی، از ابواسحاق، از عمروبن مرة از عبداﷲبن سلمة، از علی علیه السلام که گفت : رسول خدای صلی اﷲ علیه و آله و سلم فرمود: یا علی آگاه باش، می آموزم ترا کلماتی که اگر بدان کلمات متکلم شوی و ترا به اندازه ٔ ذرات هوا خطایا باشد، خدای تعالی ترا خواهد آمرزید. آنگاه این کلمات را به علی علیه السلام آموخت :<br />لااله الااﷲ العظیم، لااله الااﷲ الحلیم الکریم، سبحان اﷲ و لااله الااﷲ رب العرش العظیم، الحمدﷲ رب العالمین . (تاریخ خطیب ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٦</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175404, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن صالح بن احمد جزایری دمشقی . متولد به سال <span class=\"hlight\" dir=\"rtl\">١٢٦٨</span> و متوفی به سال <span class=\"hlight\" dir=\"rtl\">١٣٣٨</span> هَ . ق . مؤلف (تلخیص ادب الکاتب ) تألیف ابن قتیبة. کتاب او در مطبعه ٔ سلفیه در <span class=\"hlight\" dir=\"rtl\">٢٠٦</span> صفحه طبع شده است . و او راست کتاب «اتمام الانس فی عروض الفرس » که در دمشق به طبع رسیده است . (از الذریعه ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤١٩</span>) و صاحب معجم المطبوعات آرد طاهربن صالح بن احمد الجزائری ثم الدمشقی . وی یکی از دانشمندان عصر حاضر و زاده ٔ دمشق است . نخست مفتش مدارس دمشق شد به سال <span class=\"hlight\" dir=\"rtl\">١٢٦٨</span> (چنانکه در کتابی که بخط جزائری در کتابخانه ٔ تیموریه محفوظ است خوانده ام ) عشقی مفرط به گردآوردن کتابهای خطی و تفحص درآنها داشت، و بر اثر آن بختش یاوری کرد، و توفیق ایجاد کتابخانه ای در ظاهریه دمشق یافت، و کتابهائی را که در کتابخانه ها متفرق بود جمعآوری و تمامی را به کتابخانه ٔ ظاهریه نقل کرد. در قدس شریف نیز کتابخانه ای بنام «مکتبةالخالدیة» احداث کرد. سپس در سال <span class=\"hlight\" dir=\"rtl\">١٩١٤</span> از ستم ترکان فراراً از دمشق به مصر شد. و بعد از سالی چند به سال <span class=\"hlight\" dir=\"rtl\">١٩١٨</span> م . به دمشق باز گشت، و بسمت عضو عامل مجمع علمی عربی، و مدیر کتابخانه ٔ ظاهریه منصوب گشت، و سه ماه پس از بازگشت به دمشق در همانجا درگذشت از تصانیف وی کتب مفصله ٔ ذیل به طبع رسیده است :<br /><span class=\"hlight\" dir=\"rtl\">١</span> - اتمام الانس، فی عروض الفرس . این کتاب رساله ای است در علم عروض و قوافی، و در دمشق چاپ شده است . <span class=\"hlight\" dir=\"rtl\">٢</span> - ارشاد الالباء الی طریق تعلیم الفبا. دراین کتاب مباحثی لغوی از حروف هجا و ترتیب و رسم الخط و حرکات و ضوابط و مفردات و اعداد، و فوائد بسیاری درباب نطق و کتابت مندرج داشته . کتاب مزبور در مطبعه ٔ اهلیه به بیروت سال <span class=\"hlight\" dir=\"rtl\">١٣٢١</span> هَ . ق . به طبع رسیده است . <span class=\"hlight\" dir=\"rtl\">٣</span> - بدیعالتلخیص، و تلخیص البدیع. این کتاب عبارت است از قصیده ٔ بدیعیه ای که بدین بیت آغاز میشود:<br />بدیع حسن بدورنحو ذی سلم <br />قد راقنی ذکره فی مطلع الکلم <br />این قصیده را شرحی نیز هست . کتاب مزبور، یک نوبت در ولایت سوریه ٔ دمشق به سال <span class=\"hlight\" dir=\"rtl\">١٢٩٦</span> و نوبت دیگر درچاپخانه ٔ سنگی مطبعه ٔ مصطفی واصف به دمشق سال <span class=\"hlight\" dir=\"rtl\">١٢٩٩</span> طبع و نشر گردیده است . <span class=\"hlight\" dir=\"rtl\">٤</span> - تدریب اللسان، علی تجرید البیان، (بمراقی علم الادب ). به (شماره ٔ <span class=\"hlight\" dir=\"rtl\">٢٢</span> از همین فهرست مصنفات ) رجوع شود. <span class=\"hlight\" dir=\"rtl\">٥</span> - تسهیل المجاز، الی فن المعمی والالغاز. در مطبعه ٔ سوریای دمشق به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٣</span> چاپ شده . <span class=\"hlight\" dir=\"rtl\">٦</span> - التقریب، لاصول التعریب، در این کتاب بعض الفاظ معرب، و روش تعریب را بیان کرده . و در پایان آن فهرستهائی نیز ترتیب داده است . و در چاپخانه ٔ سلفیه به سال <span class=\"hlight\" dir=\"rtl\">١٣٣٧</span> آن را بچاپ رسانده اند. <span class=\"hlight\" dir=\"rtl\">٧</span>- التمرین، علی البیان والتبیین . (بمراقی علم الادب ). به شماره ٔ <span class=\"hlight\" dir=\"rtl\">٢٢</span> از همین فهرست مصنفات رجوع شود. <span class=\"hlight\" dir=\"rtl\">٨</span> - تمهیدالعروض، الی فن العروض . این کتاب در مطبعه ٔ سوریای دمشق به طبع رسیده است . <span class=\"hlight\" dir=\"rtl\">٩</span> - توجیه النظر الی اصول علم الاثر. (مصطلح الحدیث ). مصنف در تعریف این کتاب گفته که : این تصنیف مشتمل است بر فصلی چند که مطالعه کنندگان در کتب حدیث و سیر و اخبار را بسی سودمند باشد. و بیشتر مندرجات آن از کتب اصول فقه و اصول حدیث نقل شده است، ودر مصر به سال <span class=\"hlight\" dir=\"rtl\">١٣٢٠</span> هَ . ق . طبع گردیده . <span class=\"hlight\" dir=\"rtl\">١٠</span> - جدول الحروف العربیة القدیمة و الحدیثة و الهندیة و الیونانیة، الخ . در این کتاب از رسم الخط حروف و حرکات و اعراب آن گفتگو کند. در مطبعه ٔ سنگی بدون تاریخ به طبع رسیده است . <span class=\"hlight\" dir=\"rtl\">١١</span> - الجواهر الکلامیة، فی العقاید الاسلامیة (در توحید) نوبتی به دمشق به سال <span class=\"hlight\" dir=\"rtl\">١٣١٣</span> و نوبت دیگر به مصر و بدون تاریخ، طبع و نشر یافته است . <span class=\"hlight\" dir=\"rtl\">١٢</span> - حدائق الافکار، فی رقائق الاشعار. در دمشق به مطبعه ٔ سنگی چاپ شده است به سال <span class=\"hlight\" dir=\"rtl\">١٢٩٩</span>. <span class=\"hlight\" dir=\"rtl\">١٣</span> - الحکم المنثوره . در مصر به طبع رسیده است . <span class=\"hlight\" dir=\"rtl\">١٤</span>- دائرة فی معرفة الاوقات و الایام (در علم میقات ) در مطبعه ٔ سنگی در دمشق چاپ شده است . <span class=\"hlight\" dir=\"rtl\">١٥</span> - رسائل، فی علم الخط. در مصر به چاپ رسیده . <span class=\"hlight\" dir=\"rtl\">١٦</span> - شرح خطب ابن نباته . در مصر طبع شده . <span class=\"hlight\" dir=\"rtl\">١٧</span> -شرح خطبة الکافی این کتاب از اصول لغت و نشأت و اشتقاق آن گفتگو کند، و در مصر بدون تاریخ به طبع رسیده است . <span class=\"hlight\" dir=\"rtl\">١٨</span> - عمدةالمغرب، و عدةالمعرب . قصیده ای است در ذکر الفاظ نحویه . در مطبعه ٔ سنگی در سوریای دمشق چاپ گردیده است . <span class=\"hlight\" dir=\"rtl\">١٩</span> - الفوائد الجسام، فی معرفة خواص الاجسام . (در طبیعیات ) آغاز کتاب بدین جمله افتتاح شده است : الحمداﷲ الذی اوجدالعالم من العدم، و اودع فیه ابدع الاسرار والحکم . این کتاب در مطبعه ٔ معارف سوریای دمشق به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> به طبع رسیده است . <span class=\"hlight\" dir=\"rtl\">٢٠</span> - مدخل الطلاب، الی علم الحساب در دمشق در <span class=\"hlight\" dir=\"rtl\">٤٦</span> صفحه چاپ شده است . <span class=\"hlight\" dir=\"rtl\">٢١</span> - مد الراحة، لاخذ المساحة. در ولایت سوریا در سال <span class=\"hlight\" dir=\"rtl\">١٣١٠</span> در <span class=\"hlight\" dir=\"rtl\">٢٨</span> صفحه چاپ شده است . <span class=\"hlight\" dir=\"rtl\">٢٢</span> - مراقی علم الادب . قسم اول، در حروف و شکل و اعراب آن، این بخش را به «ارشاد الالباء، الی طریق تعلیم الف باء» نام نهاده، چنانکه در شماره ٔ <span class=\"hlight\" dir=\"rtl\">٢</span> گذشت قسم ثانی در تمرین و آن بنام التمرین، علی البیان والتبیین در مطبعه ٔ اهلیه ٔ بیروت به سال <span class=\"hlight\" dir=\"rtl\">١٣٢٥</span> هَ . ق .به طبع رسیده است قسم ثالث در تجرید؛ و نام آن تدریب اللسان، علی تجریدالبیان است ؛ و آن نیز به سال <span class=\"hlight\" dir=\"rtl\">١٣٢٥</span>هَ . ق . در مطبعه ٔ اهلیه ٔ بیروت طبع شده است . <span class=\"hlight\" dir=\"rtl\">٢٣</span> - منیته الاذکیاء، فی قصص الانبیاء. این کتاب را از زبان ترکی به عربی ترجمه کرده و در دمشق به سال <span class=\"hlight\" dir=\"rtl\">١٢٩٩</span> چاپ گردیده است . <span class=\"hlight\" dir=\"rtl\">٢٤</span> - میزان الافکار، شرح معیارالاشعار. درعروض و قوافی، که به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> در لکنهو به طبع رسیده است .<br />شیخ طاهر جزائری در نشر رسائل ابن المقفع، و اختصار شرح کتاب امنیةالالمعی وغیر آن نیز همتی شایان ذکر مبذول داشته است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨٨</span>). زرکلی در الاعلام آورده که طاهر جزائری بیشتر زبانهای شرقی را نیک فراگرفته بود چنانکه زبانهای ِ عبری، سریانی، حبشی، زواوی، ترکی، و فارسی را خوب میدانست و نیز زرکلی گوید: کتابی هم بنام عقوداللئالی فی الاساتید العوالی دارد که طبع شده است . و تفسیر بزرگی هم تصنیف کرده که هنوز بچاپ نرسیده . وبزرگترین اثری که از او برجای مانده، یادداشتهائی است که مجموع آن بالغ بر ده مجلد شود، و آن یادداشتهاعبارت است از مطالعات و گزیده ٔ آنچه از نفائس کتابهای خطی و چاپی به دست آورده . شیخ محمد سعیدبانی دمشقی را کتابی است بنام «تنویرالبصایر، بسیرة الشیخ طاهر» که تاریخ زندگانی صاحب ترجمه را در آن بتفصیل ذکر، و اخلاق و مزایای وی را کاملاً بیان کرده است و این کتاب نیز بچاپ رسیده است . ولادتش به سال <span class=\"hlight\" dir=\"rtl\">١٢٦٨</span> و وفاتش به سال <span class=\"hlight\" dir=\"rtl\">١٣٣٨</span> هَ . ق . بوده است . (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٢</span>).<br /></font></div>'),
(175405, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن سهل اسفراینی شیخ بن حرستانی است . حافظ ابوالقاسم در ترجمه ٔ احوال او گوید: با اینکه ثقه نبود به کار ناپسند میپرداخت نام برادرش را از کتاب «الشهاب » حک کردو نام خود را در آن نوشت -انتهی . و نام برادر او صاعد است و بدین نکته اشاره کردم تا گمان نشود وی فضل بن سهل است که نام او خواهد آمد. ابن عساکر گوید: طاهربن سهل در ذی الحجه ٔ سال <span class=\"hlight\" dir=\"rtl\">٥٣١</span> هَ . ق . درگذشته است و من از او چند جزو حدیث شنیدم ولی حدیث را نمیدانست واو نام برادر خویش را از اجازه نیز حک کرده و نام خود را بر آن نوشته بود. گوید و از وی در باره ٔ مولدش پرسیدم گفت سال <span class=\"hlight\" dir=\"rtl\">٤٥٠</span>. (از لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span>).<br /></font></div>'),
(175406, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن سلطان العلماء امیرمحمد طاهربن میرسید علی بن سلطان العلماء. او راست : حاشیه ای بر شرح هدایةالاثیریة. (از الذریعه ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span>).<br /></font></div>'),
(175407, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن سعیدبن فضل اﷲبن ابی الخیر ابوالفتح بن ابی طاهربن ابی سعید میهنی صوفی برادر بزرگتر طاهربن سعید، مکنی به ابوالقاسم از خاندان تصوف و ارشاد بوده است و در این طریقت از ثابت قدمان بشمار میرفته است . وی بسفرهای بسیار رفته و از شیوخ کسب فیض کرده است . از جدش فضل و استاد ابوالقاسم قشیری و ابوالغنائم بن مأمون و ابوالحسین بن نقور و گروهی جز آنان استماع کرده است و ابوالفتیان رواسی و دیگران از وی روایت کرده اند. طاهر به سال <span class=\"hlight\" dir=\"rtl\">٥٠٢</span> درگذشته است . از (شدالازار ص <span class=\"hlight\" dir=\"rtl\">٤٠٥</span> بنقل از طبقات سبکی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> و <span class=\"hlight\" dir=\"rtl\">٤٢٣١</span>).<br /></font></div>'),
(175408, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمدبن طاهر عبدالرحمن القرشی الزهری . از فرزندان ابی سلمةبن عبدالرحمن بن عوض بوده، معروف به «ابن الناهض » است اقامتگاه وی سرقسطة بود، از ابوذر هروی روایت کند، از ابوعمرو طلمنکی نیز. خط نیکو نبشتی . ابن جیش، بنقل از ابن الابار، و ابوبکر الکمیت بن الحسن، بشرح مزبور ترجمه ٔ احوال او را ضبط کرده . ابن الابار در کتاب تکملة گفته که او ساکن سرقسطه و از شعراء عمادالدوله، ابی جعفربن المستعین باﷲ، ابی ایوب بن هود بود. حمیدی گفته که من او را ملاقات کرده ام، و بسیاری از اشعاراو را نزد وی خوانده ام . (حلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٤</span>).<br /></font></div>'),
(175409, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمد الجعفی . او راست : کتابی به نام «فصول، فی الاصول .» (کشف الظنون ).<br /></font></div>'),
(175410, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمد الاسفراینی الشافعی، کنیتش ابوالمظفر و وفاتش در <span class=\"hlight\" dir=\"rtl\">٤٧١</span> هَ . ق . بوده، او راست : کتابی به نام «تاج التراجم، فی تفسیر القرآن للاعاجم » و کتابی دیگر بنام «تبصیر فی الدین، و تمییزالفرقة الناجیة عن الفرق الهالکین » کتاب کوچکی است، محتوی بر پانزده باب . کتابی نیز به نام «الملل والنحل » تألیف کرده است . (کشف الظنون ).<br /></font></div>'),
(175411, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمدبن عمرواللیث . نواده ٔ عمرولیث . وی در سیستان به مقام او نشست (عمرولیث ) ولی چون خواست فارس را هم مثل سابق تحت امر صفاریان درآورد، در <span class=\"hlight\" dir=\"rtl\">٢٩٠</span> هَ . ق . اسیر گردید. (ترجمه ٔ طبقات سلاطین اسلام لین پول ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>). مؤلف تاریخ سیستان (صص <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> - <span class=\"hlight\" dir=\"rtl\">٣١٤</span>) آرد: اندرین میانه محمدبن عمرو را پسری بزاد طاهر نام کرد، روز شنبه سیزده روز باقی از شعبان سنه ٔ تسع و تسعین و مائتی . و طاهر را سنت کردند اندر سنه ٔ ست و سبعین و مائتی . چون عمرو اسیر ماند، طاهر و یعقوب، دو پسر محمدبن عمروبن اللیث با سرهنگان و سپاه بهزیمت بخراسان آمدند و عمال خراسان همه جمع شدند، و به هری آمدند، وز آنجا به سیستان آمدند... پس سپاه عمرو همه جمع شدند، و طاهر را بیعت کردند، و طاهر احمدبن شهفور را وزارت داد، و حکم پادشاهی به دست او کرد، و آن روز که طاهر را بیعت کردند، اندر ارگ جداگانه بخزینه اندر سی وشش بار هزار هزار درم بود دون دینار و جواهر و خزانها پر بود و بقلعه ٔ اسپهبد و دیگر قلعه ها همه گنج خانه و خزینه بود، و جامه و سلیح ستوران را کسی عدّ و احصا نداشت که چند بود، و ضیاع و عقار و مرکبان بزرگوار، و ده هزار غلام سرای بود دون بیرونی، و طاهر روز سه شنبه سیزده روز باقی از جمادی الاولی سنه ٔ سبع و ثمانین و مائتی به سیستان اندرآمد. و احمدبن شهفور نامه ای نبشت سوی معتضد و سوی عبیداﷲبن سلیمان و آگاه کرد که عمرو اسیر ماند، و سپاه طاهر را بیعت کردند. و سُبکری مستولی گشته بود بر طاهر و بر سپاه و همه را گرفته بود و نمی بایست او را که احمدبن شهفور وزارت کردی، و نامه ای که او می نبشت نهان همی کرد و لیث بن علی بن اللیث به سیستان نهان بود، و سُبکری سر بااو یکی داشت باز سرهنگان را نزدیک او برد، و اختلاف میان سپاه اندرافتاد، یکی گفت طاهر باید، دیگر گفت نه علی باید که او خود وصی ّ یعقوب بود. پس روز آدینه ده روز گذشته از محرم سنه ٔ سبع و ثمانین و مائتی خطبه ٔ عمرو از همه ٔ منبرها بیفکندند، و طاهر و یعقوب را از پس خلیفه خطبه کردند اندرین روز. باز طاهر عزم رفتن کرد سوی فارس ... و طاهر لیث علی را بر مقدمه به برجان فرستاد، و خود بر اثر همی بخواست رفت، و سپاه را اقطاعها بسیار همی دادو عطیتها، و همه ٔ سپاه به اقطاع و عطا خرسند گشتند، مگر عبداﷲبن محمدبن میکال و فورجه بن الحسن که ایشان عمل و استخراج همی خواستند، پس نامه ٔ عبداﷲبن محمدبن سلیمان رسید سوی طاهر بر دست اباالنجم بدر الصغیر به رسولی، که امیرالمؤمنین همی خواهد که فارس خاصه ٔخویش دارد صید را و خرینه را، و این همه ولایتها بتودست بداشته است و ترا واجب نکند این مایه از او دریغ داشتن، چون نامه فرارسید، و بَدْر به دَرِ شیراز فرود آمد، و کسها همی شدند و همی آمدند آخر بدر همی نیکوئی گفت بر آن جمله که چون من بازگردم، بگویم تا فارس بتو نیز ارزانی دارد، اما تو این فرمان نگاه دارتا خلافی نباشد که او اکنون نونشست است، تا آخر طاهرخرسند شد به کرمان و مکران و خراسان و سیستان، و بدر بحدیث یافتن فارس، و به صلح بازگشت اندر شوال سنه ٔتسع و ثمانین و مائتی . طاهر فورجه بن الحسن را به سیستان و بست فرستاد بمطالبت مالها... چون بدر از فارس برفت، طاهر باز فارس شد دیگر راه، و رسول فرستاد سوی مکتفی و فارس بخواست مکتفی فرا وی داد و عهد بفرستاد. طاهر باز لیث بن علی را به برجان فرستاد، و عمال هر جای بفرستاد اندر نواحی فارس، و خود به لهو و صیدکردن مشغول شد، و همه کار بر سُبکری قرار گرفت، و بر عبداﷲبن محمد میکال، و عبداﷲ همه آن کردی که فرمان سُبکری کردی، بلال بن الازهر خلاف آشکارا کرد بر سُبکری . طاهر بلال را فرمان داد که برو به سیستان، بلال مال و اهل خویش برگرفت و غلامان و سپاه خویش هر چه خاص اوبود و راه سیستان برگرفت، چون به اصطخر فارس برسید، طاهر، یوسف بن یعقوب النقیب را از پس وی فرستاد تا او را آنجا بند کرد و مال او فروگرفت، و اندر قلعه ٔ محمدبن واصل محبوس کرد، و عبدالغفاربن حلبس را آنجا کوتوال کرد، و بلال آنجا کشته شد، و طاهر فتح بن مقبل را با هدیه ها و مال بسیار نزدیک مکتفی فرستاد، و طاهربازگشت و به سیستان آمد شب یک شنبه غُره ٔ رجب سنه ٔ احدی و تسعین و مائتی و هیچکس را بار نداد، و روز و شب به شراب و لهو مشغول شد، نه مشایخ را بار دادی و نه لشکری را، و استران و کبوتر دوست داشتی، همه روز آن جمع کردی و بدان نگاه کردی، و کس فرستاد محمدبن خلف بن اللیث را بخواند و بر همه سرهنگان مهتر کرد، و نیکو داشتی او را، یعقوب (برادر طاهر) نیز یک ساعت بی محمدبن خلف صبر نکردی، و خواهر خویش را، بانوی بنت محمدبن عمرو را بزنی به محمدبن خلف دادند، و الحق مردی بود باخرد تمام و باکمال، و سُبکری را آن خوش نیامد، و تعصب افتاد به سیستان اندر این روزگار میان فریقین، و بسیار مردم کشته شد، و یکی را صدقی نام کردند و یکی را سمکی . (اول تعصب سمک و صدق ) و سبب آن بود که میل یعقوب بیشتر بر اصحاب رأی بود، و آن ِ طاهربر اصحاب حدیث، اما این نام که افتاد بر فریقین، سبب بدان بود که دیوانه ای را پسری زاد اندر دیوانگی وی، اصحاب رای گفتند که آن فرزندی زنی است (فرزند زناست ) و بویعقوب گفت که نیست، چون عقد نکاح پیش از جنون وی درست بود، پس چون مسئله درست کرد طاهر گفت صدَق َابویعقوب و کذب الحائکون . و بدان آن خواست که کسی که چیزی نداند، و اندر آن سخن گوید، او جولاهه باشد. واصل این تعصب به سیستان از عرب افتاده بود، میان تمیمی و بکری، گروهی هواء تمیمی خواستند، و گروهی هواءبکری، آخر تمیمی را نام صَدَقی گشت، و بکری را نام سمکی، تا آخر فورجه بن الحسن آن به صلاح بازآورد. و طاهر برفت بسوی بست روز یک شنبه هشت روز باقی از ذی الحجه ٔ سنه ٔ احدی و تسعین و مائتی، و یعقوب را بر سیستان خلیفت کرد، و از دو برادر هیچکسی این اختلاف را اندر پادشاهی و شهر و رعیت باک نمی داشتند، و می بایست که این مملکت بشود، و اتفاقهای بد همی افتاد، و ایشان برنا بودند، و هر چه مال فراز آوردند اندر بناها و بساتین و لهو و مرادها که بودی صرف همی کردند، چنانکه شاعری آمد بنزد یعقوب، و این بیتها بگفت، چهار هزاردرم داد او را، هر بیتی را از آن ابیات هزار درم :<br />اتیت ابایوسف المرتجی <br />فاصبحت من جوده فی الغنی <br />و کنت امراء خایفاً فی الزّمان <br />فاصبحت فی الامن لما اتی <br />و صیرنی فی ضیاء و نور<br />و قد کنت من قبله فی الدجی <br />هو الملک السید المجتبی <br />به کل نور لدینابدی <br />پس مالها کمتر شدن گرفت و عملها ضعیف گشت، و مؤنات بسیار گشت، و دولت به آخر رسید، و طاهر اندرین میانه از هیچکسی چیزی نستدی و از رعیت مال نخواستی، گفتی ظلم و جور چرا کنم، تا آنچه هست به کار برم تا خود چه باشد که جهان برگذر است اما تبذیر کردی اندر نفقات، و اندر عطیات اسراف کردی، بسیار بره و مرغ بر خوان نهادی و حلاوی، وزیادات بسیار شدی، چندانکه کس از حشم نتوانستی خورد، تا شاگردان مطبخ به بازار بردندی، و بطرح بفروختندی، چنانک هر چه به دیناری خریده بودی به درمی ببازاربفروختندی، چندین غبن بودی، تا آن همه مالها و گنجها بر این جمله بشد، و استران بسیار داشتی و همه را یخ آب دادی، و هر چه مردمان بخرد بودند از وی دوری جستند، به یک ماه یک راه بسلام رفتندی، و بیخردان روز وشب کوش خورش و شکم خویش گرفته بودندی، یک چندی به بست ببود بر این جمله، بازبه سیستان آمد و یک چندی بر این جمله بود، و باز به بست شد، روز سه شنبه ده روز باقی از شهر ربیع الاول سنه ٔ اثنی و تسعین و مائتی، به بست اندر شد، باز برادر، یعقوب از پس وی به بست شد غره ٔ ربیعالاَّخر سنه ٔ اثنی و تسعین و مائتی ؛ و سیستان را خالی کردند، و دخل از جهت سبکری منقطع گشت که هیچ نمی فرستاد از فارس وکرمان، باز طاهر و یعقوب هر دو به سیستان بازآمدند و طاهر قصد فارس کرد روز شنبه نیمه ٔ از ماه ربیع الاَّخر سنه ٔ اثنی و تسعین و مائتی، و یعقوب را بر سیستان خلیفه کرد، یعقوب یک چندی ببود باز قصد رخد کرد، و روز شنبه هشت روز باقی از ماه ربیع الاَّخرسنه ٔ اثنی وتسعین و مائتی برفت، و محمدبن خلف بن اللیث را بر سیستان خلیفت کرد، و محمدبن خلف بن اللیث مردی کاری با خرد تمام بود، وز آنچه همی دید غمگین همی بود، چون شغل به دست وی شد فریقین را بنواخت و نیکوئی گفت و گفت تعصب نباید که ما را خود محنت افتاده هست که بس بفقد عمر و یعقوب و چنین حالها و خلافها که همی بینید شما را دیگر تعصب و خلاف نباید کرد، و تألیف باید که باشد میان شما، تا اگر همه ولایتها بشود، این یکی به دست شما بماند. و به دست غربا و ناسزاآن نیفتد، مردمان سخن او قبول کردند، و دست از تعصب بداشتند، و الفت و نیکوئی میان مردمان پدیدآمد، اما طاهر چون با سپاه برسید، سبکری را خوش نیامد آمدن او به پارس، ترسید که او را عزل کند زآنجا، پس سبکری احمدبن محمدبن اللیث را پذیره ٔ او فرستاد، و گفت تو اکنون بیامدی و اولیا و سرهنگان سپاه اندر تو طمعها کنند، و همچنان امیرالمؤمنین به بغداد، و اینجا چندان مال نیست که این کارها کفایت کند. و گفته بود که جهد باید کرد تابازگردد، و تا من مال و حمل بفرستم، پس احمد نزدیک طاهر آمد، و این سخنان بگفت، طاهر چنان دانست که این از روی نصیحت و شفقت میگوید، پس آن سخن قبول کرد و بدان منت داشت، و سوی سیستان بازگشت، و به سیستان اندرآمد، روز پنجشنبه دوازده روز گذشته از ماه رمضان سنه ٔ اثنی و ثمانین و مائتی، و همان فروگرفت از مالهابه کار بردن بر ناچیز، و به بازی و نشاط مشغول بودن، و اهتمام پادشاهی نابردن، و هر چه بخردان سپاه بودند از عاقبت آن کار بسیار ترسان بودند و دانستند که پادشاهی با کبوتربازی دیر نماند، و با روز و شب شراب خوردن و بر خزینه برداشتن و ننهادن، و هر کسی سر خویش همی گرفت، و یکدیگر را همی گفتند، چون ایاس بن عبداﷲ که مهتر عرب بود مردی کاری باخرد و کمال بود، و یعقوب و عمرو را خدمت کرده بود، و معتمد بوده بود نزدیک ایشان، دستوری خواست و برفت، و گفت این پادشاهی ما بشمشیر ستدیم، و تو به لهو همی خواهی که داری، پادشاهی به هزل نتوان داشت، پادشاه را داد و دین باید وسیاست و سخن و سوط و سیف، این سخن ننیوشید و او را دستوری داد سوی کرمان برفت، و احمدبن محمدبن سلیمان را و احمدبن اسماعیل القرنینی را وکیل کرده بود، و اندر خزینه مال نمانده بود از زر و سیم که همه به کاربرده و داده شد و دست فرا کردند اندر اوانی فروختن و زرینه و سیمینه درم و دینار زدن و به کار بردن اندر حدیث مطبخ و بناها ساختن و استران خریدن و ستوران، که آن هیچ بکار نبود؛ و به بست فرمان داد طاهر تا نه گنبد برآوردند نو، و بستانها ساختند پیرامن آن و میدانهاء و مالی اندر آن شد، و هم به بست خضرائی که بر در دیوان است بطرف میدان برآورد، و مالی اندرآن کرد، و کوشک دیگر کرد هم به بست بر لب هیرمند نزدیک پل، و به سیستان قصر بوالحسنی، این همه قصرها بدرم کردو از هیچکس حشر نخواست ؛ و دیگر اندر نفقات که بکار نبود و عطیتهاء بی معنی که همی داد آن را که بایست نداد و او را که نبایست همی داد؛ و اندر سنه ٔ اربع و تسعین و مائتی مامس خادم را به بست فرستاد طاهر و شغل زی وی کرد، و سبکری لیث بن علی را به مکران فرستاد وآن عمل بدو داد و سلاح برو بفرستاد، چون آنجا شد عیسی بن معدان مال سه ساله ٔ او را داد و او را بازگردانیدو مالها و هدیه هاء بسیار داد و گفت اینجا جای تنگ است و لشکر اینجا بودن قحط خیزد، من خود مال همی دهم هر چند بباید، لیث بازگشت و به جیرفت آمد آنجا نششتنگاه خویش گرفت، باز سبکری به جیرفت آمد و گفت هیچ نبود مکران به دست او نباید گذاشت و به مال بازنباید گشت، و جیرفت احمدبن محمدبن اللیث را داد، و لیث علی را گفت دیگر راه به مکران باید شد، باز لیث با سبکری به پارس شد، و پسر را آنجا بگذاشت و باز به جیرفت آمد و تا به ذی الحجه ٔ سنه ٔ خمس و تسعین و مائتی آنجا ببود، وز آنجا به بم شد، و فورجه را و منصوربن جردین را هر دو بگرفت، و مال ایشان بستد، و منصور را بکشت، و به سیرجان شد، و عبداﷲبن بحر را بکشت و مال او برگرفت، خبر زی سبکری رسید، سپاه فرستاد به حرب لیث علی سپاه او یاری نکردند و او تنها حرب کرد، فورجه آن روز حرب بگریخت، نزدیک سبکری شد، و لیث بحرح آمد، طاهر او را مال فرستاد و کار او راست کرد، و نزدیک طاهر بسیار شکایت نمود از سبکری، پس هیچکس را خبر نبود، تا لیث علی به نِه (نیه ) آمد بااندک مردم، اما مال بسیار بر خویشتن داشت اندر محرم سنه ٔ خمس و تسعین و مائتی .<br />نشستن جعفر المقتدر باﷲ به خلافت در سنه ٔ ست و تسعین و مائتی و فرمان یافت ابومحمد المکتفی باﷲ به مدینة الشلم اندر ذی الحجه ٔ سنه ٔ خمس و تسعین و مائتی . و مقتدر بنشست، و او برادر مکتفی باﷲ بود، و مقتدر عهد عمل فرستاد طاهربن محمدبن عمروبن اللیث را بر همان عملها، و طاهر خلعت داد آورنده را و مالی بزرگ فرستاد مقتدر را، و خود به بست بود، و خبر به طاهر رسید که لیث علی به نِه آمد، اندروقت بیرون آمد سوی سیستان، و علی بن الحسن الدرهمی با او و احمدبن سمی و دیگر سرهنگان، همچنان براند یک سر تا به قوقه فرود آمد و با لیث بن علی چون صدوپنجاه مرد بود، و چنان نمود که با من سپاه بسیار است، و نامه میان ایشان پیوسته گشت، و لیث چنان نمود که من نزدیک تو همی آیم بخدمت، و اندر سر مال میفرستاد نزدیک سرهنگان طاهر، و طاهر را هیچ خبر نبود، تا او از نیه برفت و به سیستان فرود آمد، روز دوشنبه هشت روز باقی از صفر سنه ٔ ست و تسعین و مائتی .<br />آمدن لیث علی به سیستان و به شارستان در شدن و یکسر به میدان کوشک یعقوبی آمد و یعقوب اندر کوشک بود، او را کسهاء یعقوب اندر کوشک نگذاشتند و از بام ستورگاه لیث را بر سر کلوخی زدند، سرش بشکست، لیث سرشکسته بازگشت و از در شارستان که نو کرده اند بدر پارس برشد و به مسجد آدینه شدو آنجا فرود آمد و فرمود تا درهاء شارستان پیش کردند و او و یاران سخت رنجه و ضعیف و درمانده گشته بودند، که از نیه بشبی آمده بود، و دیگر روز تا گاه نماز پیشین . و مردمان شارستان او را یاری کردند. و هواء او خواستند، و طاهر خبر او یافت بر اثر او فرارسید و پیرامن شارستان فروگرفت، یعقوب را برادر خویش را بر در طعام فرستاد، و احمدبن سمی را بدر فارس و بدر کرکوی مازن بن محمد را، و بدر نیشک علی بن الحسن الدرهمی را، و بر هر دری بسر کوره کنده ای بکردند و بر لب کنده دیواری کردند علی لیث منجنیقها برباره برنهاد وبرکار کرد، و طاهر سوی سبکری نامه کرد که مرا مدد فرست، و سبکری، عبداﷲبن محمد القتال را بفرستاد و فورجه بن الحسن را، و با سپاهی به سیستان آمدند، و حرب فروگرفتند، و طاهر را هر روز پنج هزار درم نفقات همیشه اندر خاص جدا زانکه بر لشکر تفرقه میبایست کرد بر درهاء شارستان، و درم و دینار از اوانی همی زد که اندر خزائن بود، و سبکری اندکی مال فرستاد او را و از جای دیگر دخل نبود، پس مردمان دل با لیث یکی کردند که او درم و دینار و جواهر داشت بسیار، و مردمان را همی داد و مردمان ربض با مردمان شارستان یکی شدند، و به حقیقت دل، بر طاهر از لشکر و از رعیت هیچکس نماند که بر لیث علی روی نگرفت، مگر محمدبن خلف بن اللیث، واحمدبن سمی، پس طاهر را معلوم شد این حدیثها و بر علی بن الحسن الدرهمی اشارت کرد که صلح کنیم بر لیث علی بر آنکه او را بگذاریم تا به بست رود، و عمل بست ورخد او را دهیم و قتالی و علی بن الحسن الدرهمی، لیث علی را اندرین باب مطابقت کردند، و حدیث لیث بر طاهر بزرگ همی گردانیدند. پس بر آن خوش شد. چون قتال بدانست اندر شب خود و سرهنگان برفتند که طاهر را از آن خبر نبود، و دیگر روز طاهر مانده بود با اندکی سپاه علی بن الحسن الدرهمی را بخواند، نزدیک لیث بن علی فرستاد برآن جمله که تدبیر کرده بودند و لیث اجابت کرد. دیگر روز کندها راست کردند، و در شارستان گشاده گشت روز آدینه شش روز گذشته از جمادی آلاخرسنه ٔ ست و تسعین و مائتی . پس طاهر فرمان داد تا همه سرهنگان به سلام لیث علی رفتند، لیث نگذاشت که هیچکس از شارستان و از سپاه او نزدیک طاهر شد و معدل بن علی از سیستان پنهان رفته بود بسپاه جمع کردن و مردان، و طاهر فضل بن عنبر را به طلب او فرستاده بود و او را اسیر آورده وبازداشته، آن روز این صلح بکردند و دری شارستان بگشادند و طاهر او را بیرون آورد و خلعت داد و برنشاند سوی برادر فرستاد، تا همه اندر شارستان جمع شدند و طاهر حاجبان همی فرستاد که بروند سوی بست چنانکه علی حسن بر او فرونهاده بود، و لیث علت همی آورد که بر نفس خویش ایمن نباشم که بیرون آیم، پس طاهر را معلوم شد که مردمان با او یکی شده اند و بیشتری از سپاه، عزم درست کرد که برود از سیستان و مال و عیال خویش ببرد، برادر یعقوب گفت نباید، چون روز چهارشنبه بود یازده روز مانده از جمادی آلاخر سنه ٔ ست و تسعین و مائتی، یعقوب علی بن الحسن الدرهمی را بنشاند و بسیار جفا گفت، باز قصد حرب کرد با لیث علی، آخر خذلان طاهر و یعقوب را هر دو اندریافت . تا سوی در طعام از شهر بیرون شدند، و سر کوره و بازاردر طعام بسوختند و بکرکوی رفتند وز آنجا به نیه شدند که نزدیک سبکری روند.<br />رفتن طاهر و یعقوب پسران محمد عمرولیث از سیستان یکبارگی چون ایشان برفتند لیث از شارستان بیرون آمد و خانهاء ایشان غارت کرد و غوغا با او یکجاء و آن روز شیر لباده نام کردند او را که لباده سرخ پوشیده بود، و سپاه و سرهنگان طاهر همه نزدیک لیث آمدند، پیشرو ایشان علی حسن درهمی بود، و کار سیستان لیث را مستقیم شد، و خزائن طاهر فروگرفت، و برحرم او اجری فرمود تا براندند و نگذاشت که کس اندرسرای حرم شد، و خود به قصریعقوبی اندربنشست روز پنجشنبه دو روز باقی از جمادی آلاخر سنه ٔ ست و تسعین و مائتی .<br />نشستن لیث علی به امیری که او را شیر لباده گفتندی و روز آدینه او را خطبه کردند به سیستان، و به فراه و به کش و به بست او را خطبه کردند، و خطبه به بست او را محمدبن زهیر شهمرد کرد که آنجا عامل بود از جهت طاهر، و فورجه بن الحسن با مالی بزرگ و جواهر بسیار از طاهر بازگشت و نامه نبشت و جمازه فرستاد به طاهر و به خدای تعالی بچند جای او را سوگند داد که نزدیک سبکری مرو و بر او اعتمادمکن که او ترا وفا ندارد و کار خویش زی امیرالمومنین ساخته است و ضمان کرده که ترا بند کند و زی او فرستد، و خود برفت و به رخد شد، و احمدبن سمی هم بازگشت و به زمین داور شد، پس طاهر و یعقوب را آن سخن حقیقت شد تا تدبیر کردند که با سبکری حرب کنند، و سرهنگان گروهی با ایشان، و طاهر برفت به حرب سبکری، و لیث علی مالها جبایت کرد اینجا به سیستان و عمال هر سو فرستادن گرفت، سبکری نیز خبر یافت سپاهی فرستاد روز شنبه یازده روز گذشته از ماه رمضان سنه ٔ ست و تسعین ومائتی لشکرها فراهم رسیدند، و سبکری مالی بزرگ فرستاده بود و نامه ها نهان سوی سرهنگان طاهر، و گفته بودکه ایشان خداوندزادگان منند و هیچکسی سزاتر نیست که ایشان را بندگی کند که من، اما ایشان پادشاهی نخواهند کرد و همت آن ندارند و خزینه و مال جمع کرده ٔ یعقوب و عمرو همه بباد دادند، اکنون ایشان را و ما را جان ماند همی کند، مانه ایما ماند و نه ایشان، و می بیند که سیستان خانه ٔ خویش و اهل و فرزندان بگذاشتنداز پیش چاکری از آن خویش و برفتند، کنون از ایشان که شکوه دارد؟ من صواب آن دانم که ایشان را هم با جای بنشانیم و شمشیر بگردن برنهیم و نان خویش و آن ایشان به دست همی داریم تا وهن آن بیخردی که ایشان همی کنند بر ما بیش نباشد، و نیز اگر کسی ایشان را بگیرد و خوار کند سستی بر ما باشد چه سپاه سست کاری ایشان همی دیدند و دینار بیعتی بدیشان رسید خاموشی کردند، تا ایشان را بند نهادند، وسبکری هر دو را به بغداد فرستاد، پس خبر به سیستان آمد، مردمان همه خاص و عام غمگین گشتند، و تأسف خوردند، و لیث علی همچنان بسیار بگریست، و گفت قضا را چیزی نتوان کرد ایزدتعالی داند که من اندر این بیگناهم، بر من اعتماد نکردند و خویشتن عرضه کردم و نپذیرفتند. پس محمد وصیف سجزی این بیتها یاد کرد:<br />مملکتی بود شده بی قیاس <br />عمرو بر آن ملک شده بود راس <br />ازحد هند تا بحد چین و ترک <br />از حد زنگ تا بحد روم و گاس <br />رأس ذنب گشت و بسد مملکت <br />زرِّ زده شد ز نحوست نُحاس <br />دولت یعقوب دریغا برفت <br />ماند عقوبت بعقب بر حواس <br />عمرو عمر رفت وزو ماند بار <br />مذهب روباه به نسل و نواس <br />ای غما کامد وشادی گذشت <br />بود دلم دائم از این پر هراس <br />هر چه بکردیم بخواهیم دید<br />سود ندارد ز قضا احتراس <br />ناس شدند نسناس آنگه همه <br />و از همه نسناس گشتند ناس <br />دور فلک کردن چون آسیا<br />لاجرم این اس همه کرد آس <br />ملک اباهزل نکرد انتساب <br />نور ز ظلمت نکند اقتباس <br />جهد وجد یعقوب باید همی <br />تا که ز جده بدر آید ایاس <br />باز چون خبر بزابلستان شد آنجا اضطراب افتاد که ایشان گفتند که ما بر عهدطاهریم مخالفان او را فرمان نداریم . (اینجا دنباله ٔاخبار طاهر نواده ٔ عمرولیث بریده میشود و دیگر خبری از او در تاریخ سیستان نمی یابیم . ولی ابن اثیر در تاریخ کامل ذیل حوادث سال <span class=\"hlight\" dir=\"rtl\">٣١٠</span> هَ . ق . می نویسد و خلع فی هذه السنة علی طاهر و یعقوب بن محمدبن عمروبن اللیث ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>). و صاحب حبیب السیر آرد: پسر محمدبن عمروبن اللیث، از خانواده ٔ صفاریان . به سال <span class=\"hlight\" dir=\"rtl\">٢٨٧</span> هَ . ق . در سیستان بجای عمرو بر تخت سلطنت سیستان نشست . و درسال <span class=\"hlight\" dir=\"rtl\">٢٩٠</span> به دست سبکری اسیر شد. و او را با برادرش یعقوب، به بغداد فرستادند. اسارت او در موقعی رخ داد که به قصد الحاق فارس به قلمرو خویش اشتغال داشت . اوسومین پادشاه از پادشاهان صفاری است . و نیز آرد: چون اکابر اعیان سیستان، از گرفتاری عمرولیث وقوف یافتند، طاهربن محمدبن عمرو را بر سریر پادشاهی نشاندند.و او در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٢٨٩</span> هَ . ق . لشکری به فارس کشیده، عامل خلیفه را از آن ولایت اخراج نمود، و عزم تسخیر اهواز فرمود، اما قبل از آنکه بر آن مملکت تمکن یابد، مکتوبی از نزد امیر اسماعیل سامانی به وی رسیده، به سیستان بازگشته، به همان ولایت قانع گردید. و به روایت ابن جوزی، خلیفه ٔ بغداد بنابر التماس اسماعیل سامانی، بعضی از ولایت موروثی طاهربن محمد را به وی گذاشت . و در سنه ٔ ثلاث و تسعین و مأتین سبکری، غلام عمروبن لیث بر طاهر خروج نموده، میان ایشان محاربه اتفاق افتاد، و سبکری غالب آمده، طاهر و برادران یعقوب را اسیر ساخت و به دارالخلافه فرستاد. (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> - <span class=\"hlight\" dir=\"rtl\">٣٥١</span>) و حمداﷲ مستوفی آرد: طاهربن محمدبن عمرولیث الصفار چون جدش اسیر گشت ارکان دولت او را بپادشاهی بنشاندند یکسال و چند ماه کر و فری کرد و سرانجام اسماعیل سامانی بر او غلبه کرد و پادشاهی بستدبعد از مدتی حکومت سیستان به نبیره اش احمد داد و ازاو به پسرش خلف رسید بعد از او <font color=\"DarkGreen\"><b>[ به ]</font></b> نبیره ٔ او نصربن احمدبن طاهربن خلف حاکم شد و تا سنه ٔ ثمان و خمسین و خمسمائه (<span class=\"hlight\" dir=\"rtl\">٥٥٨</span> هَ . ق .) حکم کرد و عمرش از صد سال گذشته بود این زمان نسل بر نسل حکومت ایشان به سیستان تعلق دارد. (تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٣٧٨</span>). و رجوع به تجارب الامم ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٥</span>، <span class=\"hlight\" dir=\"rtl\">٤٤</span>، <span class=\"hlight\" dir=\"rtl\">٧٦</span>، <span class=\"hlight\" dir=\"rtl\">١٦٢</span> و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span>ص <span class=\"hlight\" dir=\"rtl\">٤٤٤</span> و قاموس الاعلام ترکی شود.<br /></font></div>'),
(175412, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمدبن علی، ابوالحسین الکاتب . ابوالقاسم ثلاج از طریق یوسف بن محمدبن صاعد از او روایت کند، و گوید یوسف در مجلس ابن السکین البلدی از طاهر سماع حدیث کرده است . (تاریخ خطیب ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>).<br /></font></div>'),
(175413, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمدبن عبداﷲ، ابوعبداﷲ البغدادی . وی به نیشابور فرود آمد، و در آنجا از ابوحامد محمدبن هارون الحضرمی، و احمدبن القاسم برادر ابواللیث الفرائضی، و محدثانی که بعد از آن دو تن بوده اند، روایت حدیث کرد. حاکم ابوعبداﷲ البیّع، از طاهر روایت دارد، طاهر زیرکترین محدث از عداد عراقیان و نیکوترین فتوی دهندگان از آنان بود، و از حیث کتابت نیز نیکوتر از آنها بشمار میرفت، و از همگی آنان بیشتر مورد استفاده بود. خبرد داد مرا محمدبن علی المقبری، ازمحمدبن عبداﷲبن محمد الحافظ که گفت ابوعبداﷲ طاهر البغدادی، روز پنجشنبه ٔ هشتم ربیع الاول سال <span class=\"hlight\" dir=\"rtl\">٣٨٣</span> هَ . ق . در نیشابور وفات یافت . (تاریخ خطیب ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٨</span>).<br /></font></div>'),
(175414, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن عبدالمطلب . فرزند رسول خدای صلی اﷲ علیه وآله و سلم . از بطن خدیجه بنت خویلد. این فرزند قبل از بعثت پیمبر وفات یافت . «مؤلف الاصابه » آورده است : «الطاهر» بن سیدالخلق محمدبن عبداﷲبن عبدالمطلب بن هاشم، صلی اﷲ علیه و آله و سلم، مادر وی خدیجه دختر خویلد است، زبیربن بکار، در ترجمه ٔ خدیجه از کتاب نسب، گوید: خبر داد مرا پسر عمم مصعب که گفت خدیجه از پیغمبر دو پسر آورد قاسم، و طاهر، که طاهر را «طیب » نیز میخواندند. و او بعد از بعثت بدنیا آمد و در کودکی بمرد، و نام او عبداﷲ بود. آنگاه نام چهار دخترخدیجه را یاد کرده است، همچنین یزیدبن عیاض بروایت از زهری بر قاسم و عبداﷲ اقتصار نموده . این حدیث را زبیربن بکار، از محمد، و او از محمدبن حسن، و او از محمدبن فلیح، از وی روایت کرده . زبیر گوید: خبر داد مرا ابراهیم بن حمزة و گفت : خدیجه، قاسم و طاهر را بزاد. و میگویند: عبداﷲ، و طیب را، آنگاه دختران از بطن خدیجه را ذکر کرده است . و از طریق ابن لهیعة از ابی الاسود (یتیم عروة) روایت کرده که خدیجه قاسم، طیب، طاهر، و عبداﷲ را از ذکور آورد، پس از آن نام دختران خدیجه را بیاورده است . و از طریق ابی حمزة، از ابی بکربن عثمان و جز او، روایت کند که خدیجه چهار پسر زائید، و نام هر یک را ذکر کرده است، و چهار دختر نیز آورد، که اسامی آنها را نیز بیان کرده است، آنگاه گفته است اما اولاد ذکور خدیجه، تمامی در مکه بمردند، ولی دختران بشوی رفتند و فرزندان آوردند، و نیز گفت : خبر داد مرا محمدبن فضالة که گفت خدیجه برای پیغمبر، سه پسر آورده قاسم، طاهر، و عبداﷲ. و نیز گفت خبر داد مرا علی بن صالح از جدم عبداﷲبن مصعب که صفیه مادر زبیر، کنیه ٔ ابوطاهر به زبیر داد، بنام برادرزاده طاهر. چه زبیر برادر خدیجه پسر خود را بدان کنیه مکنی ساخته بود و پسر زبیر از زیرکترین جوانان مکه بشمار میرفت، و پیغمبر صلی اﷲ علیه و آله و سلم، پسر خویش را به اسم پسر زبیر طاهر نام نهاد. در موفقیات نیز همین روایت راآورده، از محمدبن فضالة، و نیز در موفقیات ذکر کرده که طاهربن الزبیر، در شعب بدنیا آمد و پیغمبر نیز نام پسر خود را بنام او طاهر نهاد. (الاصابةج <span class=\"hlight\" dir=\"rtl\">٣</span> بخش <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٨</span>). حمداﷲ مستوفی آرد: و خدیجه ... ازپیغمبر(ص ) سه پسر آورد قاسم و طاهر و طیب و هو عبداﷲ پیش از وحی قاسم و طاهر متولد شدند. (تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span>) و رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٩</span> شود.<br /></font></div>'),
(175415, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن طاهر معروف به ابوطیب طاهری . از خاندان طاهریان بوده است که در ماورأالنهر در فضل و ادب شهرتی بسزا داشته و بزبان عربی شعر میسروده و از گویندگان معروف دربار آل سامان بوده است . رجوع به احوال و اشعار رودکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٥</span> شود.<br /></font></div>'),
(175416, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمدبن طاهربن عبداﷲبن طاهر پنجمین و آخرین حکمران خاندان طاهریان که از سال <span class=\"hlight\" dir=\"rtl\">٢٥٩</span> تا سال <span class=\"hlight\" dir=\"rtl\">٢٦١</span> فرمانروائی داشت، تا یعقوب بن اللیث فرمانروائی را از آن خاندان بگرفت . رجوع به احوال و اشعار رودکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٩</span> و <span class=\"hlight\" dir=\"rtl\">٢٢١</span> شود.<br /></font></div>'),
(175417, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن حمزه، مکنی به ابومسلم ازدیه جورذان جی جد مادری صاحب رساله ٔ محاسن است و این قصیده که می آید از گفتار اوست مضمون آن افتخار نفس و اخبار از دولت و سعادت آباء و اجدادخود که احیاء رسوم دین و امانت مخالفت یقین در طبیعت وجود ایشان مجبول و مرتکز بوده و قصیده این است :<br />و ما اناالاالمرء اما فعاله <br />فحسنی و امانعته فجواد<br />له جانب قاسی الصفا و لربما<br />یلین لداعی الحب منه قیاد<br />سجایاه ندفوق نار ذکائه <br />و افکاره فی المعضلات زناد<br />اذا مار آلی حاسد غض طرفه <br />کانی فی طرف الحسود رقاد<br />یخوض حجاجیه بروق فضائلی <br />و فی مسم̍عیه من ثنای رعاد<br />انا ابن الاولی سار وابکل کتیبة<br />و ساموا العدی خسف الحیوة و سادوا<br />رحاب مغانیم سباط اکفهم <br />اذا ارتدت الاَّ مال و هی جواد<br />اولئک قوم ارهفوا طبع دهرهم <br />و ذبوا عن الدین الحنیف و ذادوا<br />فمن صعر الدنیا اقاموا و من ردی <br />اقالواو من فتک الزمان اقادوا<br />اذا مااستجاروهم اجارواوان دعوا<br />اجابوا و ان نصواالخطاب اجادوا<br />نفوسهم للقتل تحیی و مالهم <br />لامضاء حکم الجودفیه یزاد<br />و این صاحب فتوت ابومسلم با وفور کمال شرف و جوانمردی و غرور و جمال و قدر مردی مخصوص بود بنظر تأیید و رحمت الهی و متتبع معدلت و انصاف مصطفوی، از جاده ٔ طور و قدر خود گامی تجاوز نمی نمود و شهنشاه عضدالدوله از میان ابناءجنس جهت نفس خود تشریف اختصاص است خلاص فرمود و چون نور فصاحت و ذلاقت از جبین اقوال و افعال او می تافت وبحس تصنع و لطف تفرس لیاقت و کیاست در ناصیه ٔ اعمال و اشغال او می یافت او را مصاحب بطرف بغداد برد و دراین وقت او در سن چهارده سالگی بود. به مدت یکسال دربغداد تفقه فقه کرد بر خدمت ابوعبداﷲ بصری معروف به ابن جعل امام در فقه و کلام و پس از مدتی اندک و زمانی کمک با خواص غلامان درگاه در حضرت کمربسته به قیام قیام نمودندی . به شش لغت متکلم می بود عربی و پارسی و ترکی و زنگی و رومی و هندی و از کمال فضیلت او آن بود که در بیست وهشت سالگی در مجلس عضدالدوله میان او و صاحب عباد بحثی واقع شد در باب مذهب بعد از جریان مناظرات بسیار و مناقرات بیشمار ابومسلم صاحب را ملزم گردانیده تخجیل و انفعال داد و از آن روز باز این معنی در سینه ٔ صاحب کینه ای شد و پنهان می داشت تا وقتی که عضدالدوله را سفر ملک آخرت و نقل از منزل فنا بدارالملک بقا اتفاق افتاد، ابومسلم را «هوس مسکن مألوف و دیار معهود» که آن خطه ٔ اصفهان است برخاست و اسباب تحویل به عراق آماده کرد و بیاراست چون بحدود همدان رسید و ابوعلی سروی پسر عمه ٔ ابومسلم بر همدان عامل، توقیع آمد به طرف ابوعلی از خدمت صاحب بر این سیاق عبارت صاحب کافی : «هذا کتاب ینذره و یأمره بان یهلکه او یتخبط فیشرکه ». بعد از تمهید معذرت بسیار جهت دفع این تخویف و انداز نهان از ابومسلم که ابوعلی بجانب صاحب از انواع فصل در طوامیر و اجناس حمل قناطیر میفرستاد و در حضرت صاحب بغیر از انتقام هیچ درمحل قبول نمی افتاد قرابت و خویشاوندی ابوعلی برعض شکیمت و اصرار عزیمت صاحبی غالب آمد و سلامت نفس ابومسلم گشت . (ترجمه ٔ محاسن اصفهان صص <span class=\"hlight\" dir=\"rtl\">٧٢</span> - <span class=\"hlight\" dir=\"rtl\">٧٤</span>) و رجوع به کتاب مزبور صص <span class=\"hlight\" dir=\"rtl\">٢٥</span> - <span class=\"hlight\" dir=\"rtl\">٣٧</span> شود.<br /></font></div>'),
(175418, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[هَِ ]</font></b> (اِخ ) ابن محمد الحدادی المروزی البخاری الملقب به تاج الدین، کنیتش ابوعبداﷲ. وی را کتابی است به نام : «عیون المجالس و سرور المدارس ». (کشف الظنون ).<br /></font></div>'),
(175419, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمد الصادق . رجوع به طاهر جعفربن محمد... و رجوع به جعفربن محمد الصادق شود.<br /></font></div>'),
(175420, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمدبن سهلویه بن الحارث بن یزیدبن بحر، ابوالحسین النیسابوری، هنگامی که عازم زیارت خانه ٔ خدا بود به بغداد آمد. و در آنجااز محمدبن اسماعیل بن اسحاق المروزی از یاران علی بن حجر، و از عباس بن منصور الفرندآبادی، و از مکی بن عبدان، و محمدبن احمدبن دلویه الدقاق، و احمدبن محمد الخداشی، و ابوحامد احمدبن محمد الشرقی، و ابوحامدبن بلال، و محمدبن حمدویة المروزی روایت حدیث کرد. ازهری، و ابومحمد خلال، و ابوالحسن محمدبن عبدالواحدبن محمدبن جعفر، از طاهر ما را حدیث روایت کردند. طاهر مردی عدل و ثقه بود، گواهی وی نزد حکام همواره مقبول بود، حسن بن محمد الخلال مرا گفت : چون طاهربن سهلویه از زیارت حج به بغداد بازگشت، در بغداد از او سماع حدیث کردیم . و آن سال <span class=\"hlight\" dir=\"rtl\">٣٧٩</span> بود، و در همان سال نیز طاهربن سهلویه این جهان را بدرود گفت . دیگری گفته است که هنگام مرگ وی هفتادساله بود. (تاریخ خطیب ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>).<br /></font></div>'),
(175421, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمدبن السری بن سهل بن خالدبن البختری، ابوالقاسم الطاهری . خبر داد ما را ابن الثلاج از طاهر که او از احمدبن علی الابار خبر داده است، ابن الثلاج گوید: طاهردر سال <span class=\"hlight\" dir=\"rtl\">٣٤٥</span> هَ . ق . وفات یافت، و طاهر خود گفت که مولد او در سال <span class=\"hlight\" dir=\"rtl\">٢٦٨</span> هَ . ق . بوده است . ابوالفتح بن مسرور از طریق احمدبن عبیداﷲ النرسی نیز از طاهر روایت دارد. طاهر مردی ثقة بود. (تاریخ خطیب ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>).<br /></font></div>'),
(175422, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[هَِ ]</font></b> (اِخ ) ابن محمد. مؤلف حبیب السیر آرد: چون سلطنت از خاندان غزنویان به سلجوقیان انتقال یافت در زمان سلطان سنجر طاهربن محمد که به روایتی از اولاد طاهربن خلف بن احمد بود و بقولی در سلک ملوک عجم انتظام داشت، در آن ولایت به نیابت سلطان سنجر لوای حکومت برافراشت و پس از فوت وی پسرش تاج الدین ابوالفضل در آن مملکت حاکم شد... (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢٧</span>).<br /></font></div>'),
(175423, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن محمد. رجوع به طاهربن امیر ابوالفضل شود. (حاشیه ٔ تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٨٤</span>).<br /></font></div>'),
(175424, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن اللیث . اصطخری در کتاب المسالک و الممالک گوید: پسران لیث چهار برادر بودند یعقوب و عمروو طاهر و علی، و طاهر در جنگی که بر دربست کردند کشته شد... الخ (چ لیدن ص <span class=\"hlight\" dir=\"rtl\">٢٤٥</span>) (تاریخ سیستان حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">١٩٤</span>). نیز رجوع به تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">١٩٨</span> و <span class=\"hlight\" dir=\"rtl\">٣٤٢</span> شود.<br /></font></div>'),
(175425, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن القاسم بن نصر، ابوالعباس الجوهری بن الثلاج گفت که طاهر جوهری از طریق محمدبن عثمان بن ابی شیبة الکوفی، و سعیدبن عجب الانباری وی را حدیث فرا یاد داد. (تاریخ خطیب ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>).<br /></font></div>'),
(175426, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن قاسم بن احمد الانصاری الخوارزمی الحنفی . معروف به سعید نمدپوش، او راست : کتاب جواهرالفقه، کتابی است مختصر در علم فقه و مشتمل بر ده باب این کتاب را در مصر غره ٔ رمضان به سال <span class=\"hlight\" dir=\"rtl\">٧٧١</span> هَ . ق . تألیف کرده است . (کشف الظنون ). وی در مصر سکونت داشت، و از فقهاء حنفیه بشمار می رفت . و در حدود سال <span class=\"hlight\" dir=\"rtl\">٧٧٥</span> هَ . ق . درگذشت . (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٤</span>).<br /></font></div>'),
(175427, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b>(اِخ ) ابن ابراهیم بن سله (کذا). وی جدّ مادری مفضل بن سعد مافرّوخی اصفهانی، و پسر عم ّ استاد ابوالحسن علی ّبن احمدبن العباس الاَّنداآنی است که والی اصفهان بوده است . طاهر گوید: در عنفوان جوانی مردی از آشنایان من عرض حالی مرا داد که به والی برسانم مبنی بر آنکه اگر والی وی را مباشر قریه ٔ ماربانان کند مبلغ پنجهزار درهم علاوه بر خراج مقرّر آن قریه بخزانه ٔ دولت ایصال خواهد داشت . من بخانه ٔ استاد والی رفتم که عرض حال آن مرد برسانم . والی مرا به خلوت پذیرفت، من عرض حال معهود را به وی دادم . والی در عرض حال تأملی کرد و گفت فردا با صاحب عرض حال در دیوان حاضر شو. اینک مرا فراغتی نیست . من نیز چنان کردم . دیگر روز که با صاحب عرض حال به دیوان رفتم . هنگامی که مردم ازصنوف مختلفه برای اصلاح امور خویش در رفت و آمد بودند و ازدحام و جمعیت و دیوانیان سرگرم امر و نهی و به استماع دعاوی مدّعیان و اِنکار منکران مشغول شدند، والی با کمال بشاشت صاحب عرض حال را نزد خود خواند وبنشاند، و بطریق مؤانست با او گرم گفتگو شد، و در نتیجه صاحب عرض حال نیز به آزادی تمام مقصود و منظورخویش را علی رؤوس الاشهاد بسمع والی رسانید، و استادبر او آفرین خواند، و گفت قلم بر دست گیر، و مبلغی را که در عرض حال خود نبشته ای تا آخرین درهم بر عهده گیر، بدون آنکه رسمی را دگرگون کنی، یا از آنچه که بر عهده داری گامی فراتر نهی، یا آنکه سنتی از سنن ِ اداءِ خراج را مهمل گذاری، یا چیزی زیاد و کم کنی، و در پایان سال نیز ملک را باید آباد و پر جمعیت و قابل زراعت به حال کنونی چنانکه هست تسلیم کارکنان دیوان کنی . آن مرد گفت حق تعالی استاد والی را عزیز و گرامی داراد؛ آیا آنچه را که فرمودی در حیطه ٔ توانائی و استطاعت من مییابی ؟ والی گفت : ای احمق نادان من چه دانم، آیا تو اندیشه در دل ره دادی که من بگفتار مُزوِّرِ تو فریب خواهم خورد، و دیهی را که از امهات قراء بشمار است، و معادل پنج هزار دینار محصول غله ٔ آنجاست من در برابر پنج هزار درهم، آن دیه خراب خواهم ساخت، نی، بد اندیشیدی، ای مرد پست فطرت دون همت، حاجتت نارواست، آنگاه والی نظری بسوی حواشی خود افکنده، در حال تنی چند از خدمتکاران پایهای آن مرد را گرفته، کشان کشان وی را از دیوان بیرون بردند، سپس والی فرمان داد که او را تازیانه زنند و باژگونه بر مرکبی سوارش کنند و منادی در شارع عام ندا دردهد که این است کیفر آنکه سخن چینی کند. طاهر گوید: چون حال بدین منوال دیدم، از شرم بنحوی حالم تغییر یافت که پنداشتم در بستری از آتش می غلطم، و در آن حال آرزو میکردم که زمین مرا فروبَرَد، خود را مهیا و آماده ٔ رفتن ساختم، در همان اثنا والی روی بمن آورده، و هنوز اَثر و نشانه ٔ خشم بر چهره ٔ وی آشکار بود که گفت ای طاهر، ازاین پس، از آنکه این گونه قصه ها را واسطه ٔ رساندن بسوی من شوی خودداری کن -انتهی . (محاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">٩٩</span>).<br /></font></div>'),
(175428, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن احمد القزوینی . صاحب روضات الجنات ذیل ترجمه ٔ طاهربن علی الجرجانی، از این شخص نام برده، و گوید: الشیخ بهاءالدین ابومحمد طاهربن احمد القزوینی، الفاضل النحوی . کسی است که شیخ منتجب الدین از او روایت دارد، و طاهربن احمد قزوینی بنص خود بچند واسطه از مردم ثقات، از ادیب فاضل مجمعبن محمدبن السکنی، شارح شرح فصیح و شرط الالفاظ، و دیوان النظم، و دیوان النشر، روایت کند.امام رافعی از طاهربن احمد قزوینی، در کتاب تقریب، ثناء بسیار گفته و گوید وی را مصنفات بسیار است، و در سال <span class=\"hlight\" dir=\"rtl\">٥٧٥</span> هَ . ق . وفات یافته است . (روضات ص <span class=\"hlight\" dir=\"rtl\">٣٣٦</span>).<br /></font></div>'),
(175429, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[هَِ ]</font></b> (اِخ ) ابن احمد ابوالفرج الاصبهانی، معروف به سبطبن عمر المؤدب، وی را در دیهی بسواد دجیل بغداد که موسوم به «شلا» بود ملاقات کردم . احادیثی از طریق ابوالقاسم طبرانی برای من روایت کرد، و این امر به سال <span class=\"hlight\" dir=\"rtl\">٤١٣</span> هَ . ق . اتفاق افتاد. خبر داد ما را طاهربن احمد، خبر داد ما را ابوالقاسم سلیمان بن احمدبن ایوب اللخمی الطبرانی - در اصبهان - خبر داد ما را مقدادبن داود، خبر داد ما را اسدبن موسی، خبر داد ما را حمادبن سلمة، از عبیداﷲبن عمر، از سعید مقبری، از ابی هریره که گفت رسول اکرم، صلی اﷲ علیه و آله و سلم فرمود: چهار تن را ایزد یکتا، دشمن دارد؛ کسی که سوگند بسیار یاد کند، درویشی که کبر ورزد، پیری که زنا کند، پیشوائی که ستم روا دارد. (تاریخ خطیب ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>).<br /></font></div>'),
(175430, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن احمدبن عطیة المری القاضی . اصل وی از وادی الحجارة، از بلاد اندلس است . کنیت او ابومحمد میباشد، از ابوبکربن بشرروایت کند، عبداﷲبن طاهر در سال <span class=\"hlight\" dir=\"rtl\">٥٣٧</span> هَ . ق . به وی و به پسر وی اجازت روایت داد. ابومحمد عبدالحق بن عبدالرحمن اشبیلی، از صاحب ترجمه تحدیث کند، و ابن بشکوال ذکر او آورده است . (حلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٠</span> و <span class=\"hlight\" dir=\"rtl\">٧٩</span>).<br /></font></div>'),
(175431, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن احمدبن زید، ابوبکر المؤدب البغدادی . وی از ابراهیم بن شریک الاسدی، و محمدبن احمدبن صالح الازدی، روایت کند، و ابراهیم بن احمدبن محمد الطبری المقری از طاهر روایت دارد و وی گفته است که در بصره از طاهر مؤدب بغدادی حدیث فرا گرفتم . (تاریخ خطیب ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175432, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن احمدبن بابشاذ النحوی . گویند اصل وی از دیلم بوده و در مصر در علم نحو پیشوای عصر خویش بود وی را تصنیفات سودمند است از آن جمله «المقدمة» که کتابی است مشهور.و شرح آن، و شرح الجمل که از زجاجی است و شرح کتاب الاصول از ابن السراج، و در روزگاری که گوشه نشینی اختیار کرد، از یادداشت هائی که راجع به علم نحو کرده بودزنبیلی بس بزرگ فراهم آمده بود و گفته اند که اگر به بیاض برده میشد به اندازه ٔ پانزده مجلد میگردید، علماء نحوی که بعد از ابن بابشاذ آمدند و بدان زنبیل دست یافتند، آن را «تعلیق الغرفة» نام نهادند و این تعلیقه به شاگرد ابن بابشاذ، ابوعبداﷲ محمدبن برکات السعدی النحوی اللغوی که پس از او دست پیشوائی نحو بدو استقرار یافت انتقال پیدا کرد، و پس از محمدبن برکات به ابومحمد عبداﷲبن بری النحوی که از یاران او بود و قائم مقام او شد، منتقل گردید. و بعد از ابن بری به یکی از یاران وی، شیخ ابوالحسین نحوی ملقب به «ثلط الفیل » که از شاگردان ابن بری و پس از او به جانشینی او برگزیده شد، رسید. گویند هر یک از این جماعت زنبیل مذکور را به شاگردی که استحقاق نیابت او را داشت می بخشید، و گروهی دیگر از شاگردان با نهایت جهد وکوششی که در استنساخ آن اوراق مبذول داشتند، موفقیتی در آن نیافتند. با این حال آنچه مردم بایستی از علم و تصانیف ابن بابشاذ استفاده برند، بردند. وظیفه ٔ ابن بابشاذ در مصر این بود که از دیوان انشاء و رسالت هیچگونه نامه ای بیرون نمی شد، مگر آنکه بایستی آن نامه از نظر وی بگذرد، و بدقت در آن بنگرد که اگر از طریق نحو یا لغت اشتباه و خطائی در آن شده به اصلاحش گراید، وگرنه بحسن قبول نامه را تلقی کند و دستور ارسال آن را به مقصد بدهد و برای این امر ابن بابشاذ را در هر ماه راتبه و مقرری بود که به او میرسید و دیرگاهی بدین شغل منصوب بود، روزی در سطح مسجد جامع مصر که با جمعی از همگنان خود مشغول تناول غذا بود، گربه ای حاضر شد. لقمه ای نزد گربه انداختند. گربه لقمه را در دهان خود گرفته برفت و از نظر آنان پنهان گردید. کرّت دیگر گربه باز آمد، آن جمع دوباره لقمه ای نزد او نهادند. گربه این بار مانند نخستین بار، لقمه را بدهان گرفته، خود را از نظر آن جماعت پنهان ساخت، و چندین نوبت این عمل بین گربه و جمعیت تکرار یافت، در آخر آن جمع از رفتار گربه در شگفتی شدند، چه میدانستند که آن مقدار لقمه ای که برای او مخصوص داشتند از خوراک یک تن گربه افزون است، و به تنهائی نتواند خورد، پی او گرفتند، دیدند از سطح جامع بدیواری برآمدکه پس آن دیوار خرابه ای، و در آن خرابه گربه ای کور و نابینا در گوشه ای خزیده و گربه ٔ معهود لقمه های نصیب خود را برای گربه ٔ کور میبرده، و نزد او مینهاده، و او نیز بدین وسیله روزی خود تناول میکرده است آن جماعت از این حال متعجب ماندند. ابن بابشاذ گفت : حیوانی گنگ و نابینا که از روزی محروم نشود، و کافل ارزاق جهانیان گربه ای دیگر را مسخر فرماید که کفیل رساندن روزی او گردد، چگونه مرا بیهوده و ضایع گذارد. ازینرو قطع علایق دنیویه کرد، و از خدمت مستعفی شد، و ازمقرری ماهیانه ٔ خود چشم پوشید، و در خانه ٔ خود مقیم و به مطالعه و تصنیف که شغل دیرینه ٔ او بود پرداخت، و تا پایان زندگانی، در کنف الطاف الهی محروس و به بی نیازی عمر بسر برد، تا آنکه هنگام غروب روز سوم رجب سال <span class=\"hlight\" dir=\"rtl\">٤٦٩</span> هَ . ق . در مصر وفات یافت . و در قرافه ٔ کبری دفنش کردند. رحمه اﷲ. بزیارت قبر او نائل آمده ام .تاریخ فوت او را بر سنگی که بالای سرش نهاده بودند خواندم، سبب مرگ او این بوده که گویند چون انزوا اختیار و اطراف خود جمع کرد و زوائد آنچه در خانه داشت بفروخت، و آنچه بدان نیازمند بود نزد خود باقی گذاشت .غرفه ای در جامع عمروبن العاص که عبارت از جامع عتیق مصر است اختیار کرد، و در آنجا منزل گزید، شبی خواست از آن غرفه بسطح جامع فرود آید. در یکی از طاقها که برای افشاندن نور به جامع بنا شده بود، پایش بلغزید و بیفتاد، و هنگام بامداد به رحمت ایزدی پیوست . (ابن خلکان چ تهران ). یاقوت گوید: از تألیفات ابن بابشاذ، یکی التعلیق فی النحو است که پانزده مجلد میباشد. شاگردان بعد از او آن را تعلیق الغرفة نام نهادند.دیگر المحتسب در نحو است . و شرح النخبة. (معجم الادباء مرجلیوث ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٥</span>). و رجوع به ابن بابشاذ شود.<br /></font></div>'),
(175433, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن ابی هالة التمیمی الاسدی . وی برادر هند، ربیب ِ (پسرِ زن ِ) پیغامبر صلی اﷲ علیه و آله و سلم بوده است . سیف در اوائل کتاب ردةاز طریق ابوموسی روایت کرده گوید: پیغامبر صلواة اﷲو سلامه علیه پنج نفر را مأمور مخالیف یمن فرمود که من پنجمین آنان بودم و چهار تن دیگر عبارت بودند ازمعاذ، طاهربن ابی هالة، خالدبن سعید، عکاشةبن ثور. بغوی در ترجمه ٔ عبیدبن صخربن لودان بسلسله ٔ اسناد خودروایت کرده که چون بادام بمرد پیغامبر صلواة اﷲ و سلامه علیه عمال خود را بین شهربن بادام، و عامربن شهر، و طاهربن ابی هالة، متقرق ساخت، و گروهی دیگر را نیز یاد کرده است . مرزبانی در معجم الشعراء این دو بیت را در وصف قتال اهل رده، از اشعار طاهر آورده است :<br />فلم ترعینی مثل یوم رایته <br />بخبث المخازی فی جموع الاخابث <br />فواﷲ لو لااﷲ لارب غیره <br />لمافض بالاجزاع جمع العثاعث <br />نخستین قبیله ای که از ازد تهامة بعد از پیغامبر مرتد شدند قبیله ٔ عک بود، طاهربن ابی هالة چون مأمور محاربه با آنان شد، بر آنان غلبه یافت، و راهها را ایمن ساخت، و مرتدان از قبیله ٔ عک را از آن تاریخ اخابث نامیدند. (الاصابة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٣</span>). یاقوت در معجم البلدان، ذیل کلمه ٔ اخابث، دو بیت دیگر علاوه بر دو بیت بالا آورده، با اندک تغییری در دو بیت پیشین بصورت زیر:<br />فواﷲ لولااﷲ لاشیی ٔ مثله <br />لمافض بالاجراع جمعالعثاعث <br />فلم ترعینی مثل جمع رایته <br />بجنب مجاز فی جموع الاخابث <br />قتلنا هم مابین قنة خاص <br />الی القیعة البیضأذات النبائث <br />وفینا باموال الاخابث عنوة<br />جهاراً و لم نحفل بتلک الهثاهث <br /><font color=\"Red\">(معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٦</span>).</font><br />و رجوع به قاموس الاعلام ترکی شود.<br /></font></div>'),
(175434, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن ابی بکر بابونه . محدث است .<br /></font></div>'),
(175435, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b>(اِخ ) ابن ابی الاسد قوقهی . یکی از امرای عهد ملک شمس الدین علی بن مسعود کرت است . (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٩٩</span>).<br /></font></div>'),
(175436, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ]</font></b> (اِخ ) ابن ابراهیم بن یزید الوراق الجرجانی الضبی .کنیت وی ابومحمد است . ابوبکربن المقری، و قاضی از او روایت دارند، و وی از ابوحاتم روایت کند. حدثنا القاضی ابواحمد، محمدبن احمدبن ابراهیم، حدثنی ابومحمدطاهربن ابراهیم بن یزید، حدثنا محمدبن ادریس المنذر، حدثنا عبدالرحمن بن هانی ٔ النخعی، حدثنا شیبان ابومعاویة، عن عتادة، عن انس بن مالک، عن مالک بن صعصعة، قال، قال : رسول اﷲ صلی اﷲ علیه و آله و سلم فی حدیث المعراج : فسمعت صوتاً فی الحجاب، انی قد امضیت سنتی و ادخرت رحمتی و جعلت لامتک لمن یهم بالحسنة لم یعملها، جعلتها له حسنته . و ان هو عملها کتبتها له عشراً. و ان هم بالسیئة و لم یعملها، لم اکتبها علیه . و ان هو عملها، کتبتها علیه سیئةً. (اخبار اصفهان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥١</span>).<br /></font></div>'),
(175437, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن ابراهیم بن محمدبن طاهر السجری . کنیت وی ابوالحسین و پزشکی فاضل، و به صناعت پزشکی عالم، و در آن صناعت بس دقیق و متمیز، و به اعمال پزشکی خبیر و آگاه بود. او راست : کتاب «منهاج محجة الفلاح » که به نام قاضی ابوالفضل حمویه تألیف شده . دیگر کتاب در شرح بول و نبض . تقسیم . کتاب الفصول لابقراط. (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>).<br /></font></div>'),
(175438, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن ابراهیم بن علی ابوالطیب موسوم به زکی . نیای خاندان زکی در بیهق بوده است . علی بن زید بیهقی آرد: زکی ابوالطیب را ضیعتی بوده است که هرسال از آنجا دو هزار من غله دخل بودی و ده دینار و این زکی ابوالطیب با این قدر دخل و ارتفاع دست جمله ٔ خواجگان بیهق فروبسته داشتی به کفایت و کیاست و شهامت و عقلاء گفتندی اگر وی را ثروتی بودی آثار بسیار در خراسان از وی حاصل آمدی . و سپس به ذکر اعقاب او میپردازد و گوید: خواجه حسین الداری در حق خواجه زکی ابوالطیب از طریق مطایبه قصیده ای گوید و در آن قصیده یاد کند کوشران ناحیت را. مطلع قصیده این است :<br />لحیه ٔ طاهربن ابراهیم <br />لحیه ای هست ازدر تعظیم <br />کس چنان لحیه را بکو آرد؟<br />بی سپندی و بی غلاف ادیم <br />کوشران با فغان و با شغب اند<br />کاین نه عدل است ای خدای حکیم <br />کان یکی ده تنانه دارد ریش <br />وین یکی را زنخ ز موی چو سیم <br />اول آنک محمد مختار<br />شه ترک است رخ چو ماهی شیم .<br /><font color=\"Red\">(از تاریخ بیهق ص <span class=\"hlight\" dir=\"rtl\">١٩١</span>).</font><br /></font></div>'),
(175439, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ )ابن سعیدبن ابی سعید فضل اﷲبن ابی الخیر، مکنی به ابوالقاسم . شیخ رباط بسطامی بوده است به بغداد و در همان شهر در روز دوشنبه دوازدهم ربیع الاول سنه ٔ <span class=\"hlight\" dir=\"rtl\">٥٤٢</span> هَ . ق . وفات یافت و در قبرستانی که قبر جنید در آن واقع است مدفون شد. ترجمه ٔ احوال مختصری از او در منتظم ابن الجوزی که معاصر وی بوده در جزو وفیات سنه ٔ <span class=\"hlight\" dir=\"rtl\">٥٤٢</span> هَ . ق . مذکور است از قرار ذیل (ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span>): طاهربن سعیدبن ابی سعیدبن ابی الخیر المیهنی (متن چاپی : الهیتی ) ابوالقاسم، شیخ رباط البسطامی و کان مقدما فی الصوفیة رأیته ظاهرالوقار والسکون و الهیئة و السمت وتوفی یوم الاثنین ثانی عشر ربیع الاول فجاءة و دفن فی مقبرة الجنید و قعدوا للعزاء به فنفذ الیهم من الدیوان من اقامهم » -انتهی . و در ابن الاثیر نیز در حوادث همان سال گوید «و فیها (فی ربیع الاول ) مات ابوالقاسم طاهربن سعیدبن ابی سعیدبن ابی الخیر المیهنی شیخ رباط البسطامی به بغداد» -انتهی . (از شدالازار ص <span class=\"hlight\" dir=\"rtl\">٤٠٤</span>).<br /></font></div>'),
(175440, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن ابراهیم مکنی به «ابوالوفا». اوکسی است که کشته شدن عزّالدوله ٔ بختیاربن معزالدوله دیلمی، با مشورت او و به فرمان عضدالدوله ٔ دیلمی، صورت گرفته است . ابن اثیر در تاریخ کامل گوید: و اسر بختیار، و احضر عند عضدالدوله، فلم یأذن بادخاله الیه، و امر بقتله، فقتل . و ذلک بمشورة ابی الوفاء طاهربن ابراهیم (فی سنة <span class=\"hlight\" dir=\"rtl\">٣٦٧</span>). (تاریخ کامل ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٥</span>). ومؤلف حبیب السیر آرد: طاهر کسی است که صمصام الدوله دیلمی را دستگیر کرده، نزد ابونصربن بختیار برد، و صمصام الدوله به امر ابونصر کشته شد. کیفیت واقعه چنان بود که در سال <span class=\"hlight\" dir=\"rtl\">٣٨٨</span> هَ . ق . صمصام الدوله به عرض لشکرمشغولی فرمود، و نام هر کس را که نسبش به دیلم میپذیرفت، از دفتر حک میکرد، و چون آن لشکریان از مرسوم و علوفه نومید شدند، مستحفظان اولاد بختیار را فریفته، ایشان را از بند بیرون آوردند، و جمعی از رُنود و اوباش به ایشان پیوسته، چون صمصام الدوله از کیفیت حادثه خبر یافت، قصد نمود که در یکی از قلاع فارس متحصن گردد، تا سپاه او از بغداد مراجعت کنند، اما کوتوالان قلعه او را راه ندادند، و صمصام الدوله با سیصد نفراز لشکر در دیه «دمان » که موضعی است در دوفرسخی شیراز فرود آمده، طاهرنامی که رئیس آن منزل بود او را گرفته پیش ابونصربن بختیار برد، و ابونصر در سنه ٔ مذکوره صمصام الدوله را به قتل رسانید، و مادرش را نیز کشته، آن دو قتیل را در دکانچه ٔ سرای امارت دفن کردند، و چون بهاءالدوله به فارس شتافت، ایشان را از آن مدفن بمقبره ٔ آل بویه نقل کردند، و مدت حکومت صمصام الدوله در فارس، نُه سال و هشت ماه بود. (حبیب السیر).<br /></font></div>'),
(175441, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) آل طاهر. رجوع به طاهریان و آل طاهر شود.<br /></font></div>'),
(175442, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) یکی از کارگزاران ایوبیان در حلب بوده است . (رجوع به النقود ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span> شود).<br /></font></div>'),
(175443, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) بروزگار سلطان بایسنغر اناراﷲ برهانه، شاعری زیباسخن بوده است، و این مطلع او راست :<br />از چمن بگذر و آن سرو سهی قد را دان <br />نیست غیر از تو در این باغ کسی خود را دان .<br /> <font color=\"Red\">(تذکره ٔ دولتشاه چ براون ص <span class=\"hlight\" dir=\"rtl\">٤٦٩</span>).</font><br />و رجوع به ترجمه ٔ تاریخ ادبیات براون ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٥٦</span> شود.<br /></font></div>'),
(175444, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) از نعوت حسن بن علی بن محمدبن علی بن موسی بن جعفربن محمدبن علی بن حسین بن علی بن ابی طالب علیهم السلام .<br /></font></div>'),
(175445, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) نام یا لقب یکی از پسران پیغمبر صلی اﷲ علیه و آله و سلم . (نصاب الصبیان ) <span class=\"hlight\">:</span> رسول را سه پسر بوداز خدیجه : قاسم، طیب، طاهر. (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">٢١٦</span>).<br /></font></div>'),
(175446, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص ) پاک . ج، اطهار. (منتهی الارب ) (آنندراج ): رجل طاهر الثیاب ؛ مرد پاکیزه لباس . (منتهی الارب ) (آنندراج ). ثیاب طهاری ؛ ج، طُهران است (گویا غیرقیاسی ). (منتهی الارب ) (آنندراج ). ضد نجس . مقابل پلید. پاکیزه <span class=\"hlight\">:</span> <br />نفس او پاکیزه است و خلق او پاکیزه تر<br />نفس تن چون خلق تن ظاهر شود طاهر شود.<br /> <font color=\"Red\">منوچهری .</font><br />ج، طاهرون و طاهرین . <BR><font color=\"Blue\">◄</font> امراءة طاهر (بدون ها)؛ زن پاک ازحیض . نمازی . امراءة طاهرة؛ زن پاک از نجاست . زن پاک از عیوب و منقصت . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِخ ) نامی از نامهای خدای تعالی . <BR><font color=\"Blue\">◄</font> (ص، اِ) کسی را گویند که حق تعالی او را از مخالفت اوامر و نواهی شرعیه معصوم داشته باشد. (کشاف اصطلاحات الفنون ) (تعریفات جرجانی ). <BR><font color=\"Blue\">◄</font> نامی از نامهای تازیان . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> و نعتی است که پس از لقب ملک بدان می افزوده و میگفته اند ملک الطاهر. رجوع به النقود ص <span class=\"hlight\" dir=\"rtl\">١٣٥</span> شود. <BR><font color=\"Blue\">◄</font> پنجنگشت . (فهرست مخزن الادویه ).<br /></font></div>'),
(175447, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن حسین بن مصعب . ابن خلکان نام و نسب او را بدین طریق یاد کرده است ؛ ابوالطیب، طاهربن الحسین بن مصعب رزیق بن ماهان . و گوید: در جای دیگر دیده ام رزیق بن اسعدبن راذویه و در جای دیگر اسعدبن زاذان واﷲ اعلم . و بعضی هم گفته اند مصعب بن طلحةبن رزیق الخزاعی بالولاء الملقب به ذوالیمینین . جدّ او رزیق بن ماهان غلام طلحة الطلحات الخزاعی، از اسخیاء مشهور به جود و کرم مفرط بوده است . طاهر از بزرگترین یاران و پشتیبانان مأمون بود. مأمون هنگامی که در مرو، کرسی خراسان، اقامت داشت و خلع بیعت از امین برادر خود کرده بود، طاهر را روانه ٔ بغداد ساخت تا با امین کارزار کند، و این واقعه خود مشهور است . امین، علی بن عیسی بن ماهان را برای دفع طاهر بفرستاد. و بین آن دو جنگ در گرفت و در آن اثنا علی بن عیسی کشته شد، و چنانکه طبری در تاریخ آورده، این واقعه در سال <span class=\"hlight\" dir=\"rtl\">١٩٨</span> هَ . ق . رخ داد. برخی گفته اند طاهر رسولی نزد مأمون فرستاد و راجع به این که با امین به چه وجه معامله کند دستور خواست، مأمون پیراهنی گریبان دریده در پاسخ طاهر بفرستاد. طاهر دانست که منظور مأمون کشتن امین است، و چنان کرد، امین را محاصره کرده او را کشت، و سرش را به خراسان بفرستاد، و آن پیش مأمون نهاده شد. و عقد خلافت جهت مأمون راست کرد. از این رو، مأمون همواره او را مراعات کردی و مطمح نظر داشتی، وقتی که طاهر در بغداد به مقامات عالیه رسیده بود، کسی گفتش که باید ترا بدین مقام که هیچیک از همگنانت در خراسان بدان حد نرسیده اند تهنیت گفت . طاهر در جواب گفت این مقامی نیست که مرا تهنیت گویند، چه هنگامی که از پوشنگ میگذشتم، پیرزنان آنجا را ندیدم که برای تماشای من بربام برآمده باشند، و این سخن از آن روی گفت که در پوشنگ بدنیا آمده، و در آنجا نشو و نما یافته بود. جد طاهر والی پوشنگ و هرات، و مردی شجاع و ادیب بود. طاهر روزی دربغداد در حراقه ٔ خود نشسته بود. (حراقه نوعی از کشتی که بدان بسوی دشمن نفطاندازی کنند)، مقدس بن صیفی خلوقی شاعر بدو برخورد در حالی که حراقه ٔ طاهر نزدیک شط رسیده، و طاهر در شرف بیرون آمدن از حراقه بود. مقدس، طاهر را گفت اگر خواهی بیتی چند از من بشنو.طاهر گفت اشعار خود بازخوان . مقدس این ابیات برخواند:<br />عجبت لحراقة ابن الحسین <br />لان غرقت کیف لاتغرق <br />و بحران من فوقها واحد<br />و آخر من تحتها مطبق <br />واعجب من ذاک اعوادها<br />و قد مسها کیف لاتورق .<br />طاهر او را سه هزار دینار حواله داد، و گفت بیفزا تا بیفزائیم . شاعر گفت مرا بسنده است . هنگامی که طاهر مشغول محاصره ٔ بغداد بود، به مبلغی نقد نیازمند شد و نیازمندی خود رابه مأمون گزارش داد مأمون نامه ای به خالدبن جیلویه ٔ کاتب نوشت که بطاهر هر مبلغی را که نیازمند است به رسم وام تحویل ده . خالد از این امر سر پیچید، چون طاهر بغداد را بگرفت، به احضار خالد فرمان داد چون حاضر شد طاهر بدو گفت که من باید ترا به بدترین کیفیتی بکشم . خالد مال بسیاری برای رهائی خود بطاهر بخشید، اما طاهر نپذیرفت، خالد گفت کلمتی گفته ام بشنو طاهر گفت : بگوی . خالد این ابیات بخواند:<br />زعموا بان الصقر صادف مرة<br />عصفور برساقه المقدور<br />فتکلم العصفور تحت جناحه <br />والصقر منقض علیه یطیر<br />ماکنت یاهذا لملک لقمة<br />ولئن شویت فاننی لحقیر<br />فتهاون الصقر المدل لصیده <br />کرماً فافلت ذلک العصفور.<br />طاهر او را گفت نیکو گفتی، و از اودرگذشت . طاهر از بینائی یک چشم عاری، و اعور بود. عمروبن بانه این بیت در وصف او گفته است :<br />یاذالیمینین وعین واحدة<br />نقصان عین و یمین زائدة.<br />حکایت کنند که اسماعیل بن جریر بجلی یکی از مداحان طاهر بود. روزی به طاهر گفتند که اسماعیل، شعر دیگران دزدد و آن اشعاررا در مدح تو ساخته و پرداخته کند، طاهر خواست اسماعیل را بیازماید. بدو گفت مرا هجوی گوی، اسماعیل امتناع ورزید. طاهر او را الزام کرد، و اسماعیل این ابیات در هجو او گفت :<br />رایتک لاتری الابعین <br />و عینک لاتری الا قلیلا<br />فاما اذا صبت بفردعین <br />فخذ من عینک الاخری کفیلا<br />فقد ایقنت انک عن قریب <br />بظهر الکف تلتمس السبیلا.<br />چون طاهر ابیات بشنیداسماعیل را گفت زنهار که این اشعار نزد احدی نخوانی، سپس ورقی را که اشعار بر آن نوشته بود، پاره ساخت، هنگامی که مأمون بعد از کشته شدن برادرش در خراسان استقلال یافت، نامه ای بطاهر که در بغداد بود نوشت، مبنی بر آنکه جمیع بلاد و شهرهائی را که فتح کردی، از عراق عرب، و بلاد جبل و فارس و اهواز و حجاز و یمن، به حسن بن سهل بازگذار، و خود عازم رقة شو، وزان پس شهرهای موصل، و بلاد جزیره ٔ فراتیه، و شامات، و مغرب رانیز ضمیمه ساخته، طاهر را به ایالت آن بلاد بگماشت . و این واقعه در پایان سال <span class=\"hlight\" dir=\"rtl\">١٩٨</span> هَ . ق . رخ داد. ولادت طاهر در سال <span class=\"hlight\" dir=\"rtl\">١٥٩</span> و وفاتش در روز شنبه <span class=\"hlight\" dir=\"rtl\">٢٣</span> ماه جمادی الاخرة سال <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> هَ . ق . در مرو اتفاق افتاد. سلامی در کتاب اخبار ولایت خراسان گوید: مأمون طاهر را والی خراسان ساخت در ربیع الاَّخر سال دویست و پنج یا شش، و طاهر پسر خود را در خراسان جانشین خویش قرار داد. روایت دیگری نیز هست که طاهر از فرمان برداری مأمون سرپیچید و گزارشها و نامه ها در این خصوص از خراسان به مأمون می رسید، مأمون در اضطراب شد، ولی یکی دو روز بعد از وصول خبر سرپیچی طاهر، خبر دیگری رسید که طاهر را بر اثر تبی که عارض او شده بود، در بسترش مرده یافتند. برخی دیگر گفته اند که مرگ طاهر را سبب، حادثه ای بود که بر پلکهای چشم او رسیده و در نتیجه ٔ همان حادثه عمرش بپایان رسید و مرد. هارون بن العباس بن المأمون، در تاریخ خود گوید: روزی طاهر برای انجام امری نزد مأمون شد، و پس از آنکه حاجت طاهر را برآورد، اشک از دو دیده اش روان شد. طاهر پرسید یا امیرالمؤمنین، لاابکی اﷲ عینک، چرا میگریی . دنیا ترا گردن نهاده، به آرزوی خود رسیده ای . مأمون گفت گریه ٔ مرا سبب، خواری یا اندوه نیست، امّا روان آدمی هیچگاه بدون نشانه و هدفی آرام نیابد. طاهر از این پاسخ سخت غمناک شده از حضور مأمون بیرون آمد و به حسین خادم که در مواقع خلوت و تنهائی مأمون سمت دربانی نیز داشت گفت : از تو خواهم که از مأمون سبب گریه اش را هنگام ملاقات من بازپرسی، آنگاه که طاهر به خانه ٔ خویش بازگشت، دویست هزار درهم برای حسین خادم بفرستاد، حسین خادم نیز در روزی که مأمون با خاطری خوش و تنها بود، انتهاز فرصت کرده گفت در آن روز که طاهر شرف حضور داشت گریستن خلیفه را سبب چه بود، خلیفه گفت : حسین وای بر تو! ترا بدین سؤال چه کار؟ حسین گفت من از گریه ٔ خلیفه در آن روز دلسوخته شدم، خلیفه گفت سبب گریه ٔ من امری است که اگر ترا آگاه کنم، و آن راز از تو تراوش کند، جانت در معرض هلاکت باشد، حسین گفت یا سیدی، چه وقت رازی با من در میان نهاده ای که من آن را فاش کرده باشم، خلیفه گفت من در آن روز همین که طاهر را دیدم بیاد برادرم امین افتادم، و از خواریهائی که بدو رسیده بود، از گریه گلوگیر شدم، و طاهر هم هرگزاز کیفر خویش بی بهره نخواهد ماند. حسین چون از حضورخلیفه بیرون رفت، ماجرا را به طاهر خبر داد. فی الحال طاهر سواره نزد احمدبن خالد رفت، و گفت مدح و ستایش من ارزان تمام نشود، و نیکی نزد من بار و ثمر خود ببخشاید. روزی چند مرا از نظر مأمون پنهان دار. احمدبن خالد گفت : بزودی بر وفق مرام تو کنم، فردا بامداد بگاه نزد من آی، این بگفت و نزد مأمون شد، همین که مأمون را بدید، گفت دوش تا بامداد خواب بچشم من آشنا نگردید. مأمون سبب پرسید. احمدبن خالد گفت : غسان پسر عباد را به ولایت خراسان برگزیدی، در صورتی که او با کارکنانش از حیث شمار سخت ناچیزند، و میترسم دشمنان کار او بسازند و او و همراهانش را قلع و قمع کنند. مأمون گفت رأی تو چه باشد؟ احمد گفت : طاهر برای ولایت خراسان شایسته است . مأمون گفت او برادر مراخلع کرد! احمدبن خالد گفت : من ضامن او هستم، مأمون در همان لحظه به احضار طاهر فرمان داد. چون حضور یافت خلیفه رایت ایالت خراسان را بنام او بست و خادمی از تربیت یافتگان دربار خلافت را با او همراه ساخته و بدو سفارش کرد که اگر از طاهر کردار و عملی مشاهده کردی که ناپسند بود و ترا بدگمان ساخت، او را مسموم کن . این بود که طاهر چون در ایالت خراسان استقرار یافت، نام خلیفه را از خطبه بینداخت . کلثوم بن ثابت، متولی امر برید خراسان، حکایت کند که : طاهر در روز جمعه بر منبر شد، و خطبه ای خواند، و چون بذکر خلیفه رسید، از بردن نام او خودداری کرد. این خبر فی الحال بوسیله ٔ برید به مأمون رسید، بامداد روز شنبه طاهر را مرده یافتند، خبر مرگ طاهر نیز بلافاصله برای مأمون گزارش شد، چون مأمون از گزارش نخستین و حذف طاهر نام خلیفه را در خطبه آگاه گردید، احمدبن ابی خالد را امر به احضار داد، و او را گفت چنانکه ضامن طاهر شدی، اینک او را حاضر کن، و او را مجبور ساخت که در همان لحظه برای احضار طاهر عزیمت کند، و احمد با رنج و مشقت بسیاری مأمون را راضی کرد که شب در دارالخلافه بسر برد، و روز دیگر رهسپار شود. در این اثنا گزارش دومین و خبر مرگ طاهر به مأمون رسید. گویند خادمی که مأمون او را بهمراهی طاهر فرستاده بود، سمی در آبکامه تعبیه کرده، و بطاهر خورانده، و وی در اثر آن سم بمرد. سپس مأمون فرزند طاهر را که طلحه نام داشت، در خراسان جانشین پدر قرار داد. برخی دیگر گفته اند: که مأمون ولایت خراسان را بنام عبداﷲبن طاهر، برادر طلحه نامزد کرد و طاهر را خلیفه و جانشین او ساخت . درسبب تلقیب طاهر به ذی الیمینین اقوال مختلف است . جمعی برآنند که طاهر در محاربه با علی بن ماهان با دست چپ ضربتی بر یکی از لشکریان علی زد و او را دو نیمه ساخت یکی از شعرا این مصراع را در آن واقعه سرود که :<br />کلتا یدیک یمین حین تضربه .<br />و از آنگاه مأمون او را بذی الیمینین ملقب ساخت . وغیر این نیز گفته اند. جد طاهر مصعب بن رزیق، کاتب سلیمان بن کثیر الخزاعی صاحب دعوة بنی العباس، و مردی بلیغ بود. از سخنان اوست : مااحوج الکاتب الی نفس تسموبه الی اعلی المراتب، و طبع یقوده الی اکرم الاخلاق، و همة تکفه عن دنس الطمع و دنائة الطبع. (ابن خلکان چ تهران ): دو سال و نیم جنگ بود، تا محمد زبیده، به دست طاهر افتاد و بکشتندش . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٨</span>).<br />ابوجعفر بغدادی گوید: هنگامی که طاهربن الحسین از مأمون خلیفه منقبض شد، و همواره از مأمون بیمناک بود. مأمون غلامی را به نیکوتر وجهی به ادب و فرهنگ پرورش داد، و او را بفنون علم و دانش آشنا ساخت و او را به رسم بخشایش نزد طاهر فرستاد. و از طرائف عراق مصحوب آن غلام جهت طاهر روانه ساخت، و ضمن دستورهائی که بدان غلام داده بود یکی این بود که طاهر را مسموم کند، و سمی هم که در ساعت کشنده بود به غلام سپرد، و به اموال فراوان نیز غلام را نوید داد. چون غلام بخراسان رسید و هدایا را تسلیم طاهر کرد، طاهر نیز هدایا را پذیرفته، و غلام را در سرائی شایسته فرود آورد، و آنچه مورد نیاز یک تن مسافر است در آن سرای جهت غلام فراهم داشت، و چند ماهی او را به حال خود در آن سرای بنهاد. چون غلام از اقامت در آنخانه بستوه آمد نامه ای بدین مضمون بطاهر بنوشت که «سرور من ! اگر مرا پذیرفته ای، بدانچه در خور پذیرفتن است با من همان کن .و در غیر این صورت مرا نزد خلیفه بازگردان !». طاهر غلام را نزد خود خواند آنگاه غلام را گفت : امیرالمؤمنین جز تو هر کس را فرستد او را خواهیم پذیرفت و از پذیرفتن تو معذوریم . و اینک ترا نزد امیرالمؤمنین گسیل میداریم . پاسخی دیگر در ازاء الطاف خلیفه ندارم، جز آنکه حال و کیفیت زندگانی مرا بدان طریق که مشاهده میکنی به عرض امیرالمؤمنین با سلام فراوان برسانی و تقدیم داری . چون غلام به درگاه خلیفه رسید، و سرگذشت خود را با طاهر بسمع او رساند، و حالت او را شرح داد، خلیفه گفت : ایدون، زبان از ذکر نام طاهر بازدارید، و از نیک و بد او هیچگونه سخن نرانید، و خود نیز تا هنگامی که طاهر از دنیا رفت نام طاهر بر زبان نراند. (عقد الفرید ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨</span>). روزی طاهر ذوالیمینین ازابی عبداﷲ مروزی پرسید چندگاه است که به عراق فرود آمده ای ؟ گفت مدّت بیست سال شود، و مدّت سی سال است که روزه میدارم، طاهر گفت ما از تو یک پرسش کردیم، و تو ما را دو پاسخ دادی . (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٨</span>). طاهر مردی شاعر و مترسل و بلیغ بوده . مجموعه رسائلی داشته است . رساله ٔ او که به مأمون خلیفه هنگام فتح بغدادنوشته مشهور است . (ابن الندیم ). ابن ابی اصیبعة گویدیوسف بن ابراهیم از قول میخائیل بن ماسویه نقل کند که : چون مأمون به بغداد رسید، با طاهر ذوالیمینین منادمت میکرد. روزی در اثناء مصاحبت و در حینی که نبیذ قطر بلی در آن مجلس حاضر بود، مأمون بطاهر گفت آیا مانند این شراب هیج دیده ای ؟ گفت آری . مأمون گفت، دررنگ و طعم و بوی ؟ گفت بلی، پرسید در کجا دیدی ؟ گفت در پوشنگ، مأمون گفت دستور ده که از آن شراب برای ما بفرستند، طاهر به نماینده ٔ خود در پوشنگ نوشت که از آن شراب روانه دارد. نماینده ٔ طاهر نیز بر طبق دستور وی عمل کرد، روزی دو بیش نگذشت، مأمون را خبر رسید که از پوشنگ برای طاهر هدایائی رسیده، مأمون متوقع بود که در ضمن هدایا شراب معهود هم رسیده باشد، مع ذلک چون طاهر از شراب به مأمون اطلاعی نداده بود مأمون پرسید آیا در ضمن هدایای واصله شراب هم رسیده یا نه ؟ طاهر گفت پناه میبرم بخدای که امیرالمؤمنین مرا در مقام فضیحت و رسوائی بازدارد، مأمون پرسید چرا؟ گفت شرابی که وصف آن را بسمع خلیفه رساندم، در هنگامی که بینوا بودم، و در دیهی که آرزوی تملک آن را میبردم اقامت داشتم و از آن نوشیده بودم . اینک که درکنف الطاف امیرالمؤمنین افزون از حدّ آرزوی خود رامالک گشته ام، و این شراب را فرستاده اند، آن را یکنوع رسوائی از رسوائیهای این جهان مییابم، مأمون گفت علی ای ّ حال دستور ده که از آن شراب برای ما بفرستند. طاهر فرمان برد و مقداری از آن شراب بار کرده جهت مأمون بفرستاد، مأمون فرمان داد که آن بار را در خزانه برند و بر طریق طیبت سفارش کرد که چون شراب بدی میباشد، روی آن بار بنویسند که محتویات این صندوق «شراب طاهری است » که سخت شراب ردی ٔ و ناپسندی بود، دوسال از این مقدّمه بگذشت، و مأمون را نیاز به داروئی قی آور پیدا شد. پزشکان دستور دادند که خلیفه بشراب ردی ٔ نیاز خود را مرتفع سازد، چون در حدود عراق شرابی ردی ٔتر از شراب طاهری نیافتند، شراب طاهری را ازخزانه بیرون آوردند، و به معرض آزمایش گذاشتند، معلوم گردید که در خوبی مانند شراب قطربلی یا به از آن گردیده، و اثر هوای عراق است که شراب فاسد را باصلاح آورده . همچنانکه آنچه را که در آن هوا روید یا در آن هوا نگاهداشته شود، نیز اصلاح کند. (قفطی ص <span class=\"hlight\" dir=\"rtl\">٣٢٩</span> و <span class=\"hlight\" dir=\"rtl\">٣٣٠</span>). و گفتند که سبب لقب کردن طاهر بوشنجه ای به ذی الیمینین آن بود که دلیلش دو دست راست افتاده بود. (التفهیم ص <span class=\"hlight\" dir=\"rtl\">٤٨٩</span>). ذوالیمینین، از موالی زادگان ایران بود. و قریب پنجاه سال خود و فرزندانش در خراسان فرمان راندند. چنین آورده اند که فضل (ذوالریاستین ) وزیر مأمون خلیفه، به مرو عتاب کرد با حسین مصعب پدر طاهر ذوالیمینین و گفت پسرت طاهر دیگرگونه شده است، او باد در سر کرده و خویشتن را نمی شناسد. حسین گفت ایها الوزیر، من پیریم اندرین دولت بنده و فرمانبردار و دانم که نصیحت و اخلاص من شمارا مقرر است، اما پسرم طاهر از من بنده تر و فرمانبردارتر است، و جواب دارم در این باب سخت کوتاه، اما درشت و دلگیر، اگر دستوری دهی بگویم . گفت دادم . گفت ایداﷲ الوزیر، امیرالمؤمنین وی را از فرود دست تر اولیا و حشم خویش به دست گرفته، و سینه ٔ او بشکافت، و دلی ضعیف که چنوئی را بود از آنجا بیرون گرفت و دلی آنجا نهاد که بدان دل، برادرش را خلیفه ای چون محمد زبیده بکشت، و با آن دل که داد، آلت و قوت و لشکر داد.امروز کارش چون بدین درجه رسید که پوشیده نیست، میخواهی که ترا گردن نهد، و همچنان باشد که اول بود، بهیچ حال این راست نیاید مگر آن را بدین درجه بری که اوّل بود، من آنچه دانستم بگفتم، و فرمان تراست . فضل سهل خاموش گشت چنانکه آن روز سخن نگفت، و از جای بشده بود، و این خبر به مأمون برداشتند، سخت خوشش آمد از جواب حسین مصعب و پسندید و گفت مرا این سخن از فتح بغداد خوشتر آمد. که پسرش کرد. و ولایت پوشنگ بدو داد که حسین بپوشنگ بود. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٣٥</span>).<br />خطیب در تاریخ بغداد گوید خبر داد ما را سلامة ابن الحسین المقری ٔ، به اسنادخود از احمدبن یزیدبن اسیدالسلمی که گفت : من یکی ازفرماندهان لشکر ذوالیمینین، و از خواص او بودم، و پیوسته بر جانب راست او می نشستم . هنگامی که در شهر رقه با او بودم، روزی آهنگ سواری کرد، و من نیز با سایر اصحاب او بهمراه وی بودیم . طاهر بدین ابیات تمثل جست :<br />علیکم بداری، فاهدموها، فانها<br />تراث کریم لایخاف العواقبا<br />اذا هم القی بین عینیه عزمه <br />واعرض َ عن ذکر العواقب جانبا<br />سادحض ُ عنی العاربالسیف جالبا<br />علی ّ قضاء اﷲ ماکان جالبا.<br />پس از آنکه از خواندن ابیات فارغ شد، بر اطراف و جوانب یاران و همراهان گردشی کرد و بازگشت، و بجائی که برای نشستگاه فراهم آورده بودند بنشست و در نامه ها و عرض حالهای وارده بازنگریست، و در آن روز صلات و عطیاتی را که برای مردم توقیع صادر کرد، معادل یک میلیون وهفتصد هزار (کذا) بود. چون صدور توقیعات خاتمه یافت، روی به من آورد گوئی آهنگ آن داشت که مرا بسخن آرد. من منظور او دریافتم، و گفتم : مجلسی مانند مجلس امروز و شریفتر و نیکوتر از آن ندیده بودم، سپس او را دعا کردم و گفتم : لکن این نوع بخشایش اسراف است، طاهر گفت : السرف ُ من الشرف . من خواستم در ازاء گفتار او این آیت از قرآن مجید برخوانم که فرموده : والذین اذاانفقوا، لم یُسرِفوا و لم یقتروا (قرآن <span class=\"hlight\" dir=\"rtl\">٦٧/٢٥</span>)، ولی سهواً این آیت برخواندم که : انَّه لایحب المسرفین َ (قرآن <span class=\"hlight\" dir=\"rtl\">١٤١/٦</span> و <span class=\"hlight\" dir=\"rtl\">٣١/٧</span>)، طاهر گفت صدَق َ اﷲُ و ماقُلناکما قُلنا. خدای راست فرموده و آنچه را هم که ما گفتیم، همچنان است که ما گفتیم . خبر داد ما را حسن بن علی الجوهری، به اسناد خود، از مردی در خراسان که گفت یکی از یاران برای من نقل کرد که روز جمعه ای بود مردی رابحالی سخت بد مشاهده کردم . (از ناچیزی )، پس از هفته ای باز در روز جمعه همان مرد را دیدم که بر ستوری سوار است . گفتم : مَاالخبر؟ گفت سه سال است که به در خِانه ٔ طاهربن الحسین ملازم شده ام به امید آنکه بدو برسم، و مرا میسر نشد. یکی از اصحاب طاهر مرا دید و گفت امیر امروز برای چوگان بازی سواره به میدان خواهد رفت، در خاطر خویش گفتم امروز خود را بدو میرسانم، و راه میدان در پیش گرفتم، چون به میدان رسیدم وضع را طوری دیدم که ملاقات طاهر امروز هم برای من متعذر است، در این اثنا در بستان مجاور رخنه ای بمیدان یافتم . تصمیم گرفتم که از آن رخنه خود را به میدان برسانم، چون گوی بازان مشغول چوگان بازی شدند و بانگ و غوغای آنان بلند شد، خود را از آن رخنه بمیدان انداختم . طاهردر حال متوجه شده نظری بسوی من کرد و گفت کیستی ؟ گفتم نخست به خدا و سپس بتو پناه آورده ام ایهاالامیر، آهنگ تو دارم و از تو میخواهم، دو بیتی سروده ام . طاهرگفت : بیار تا چه داری، میکال بسوی من خواست آید، طاهر او را راند، آنگاه من این دو بیت برای طاهر بازخواندم :<br />اصبحت بین خصاصة و تجمل <br />والحر بینهما یموت هزیلا<br />فامدد الی یداً تعود بطنها<br />بذل النوال وظهرها التقبیلا<br />طاهر ده هزار درهم مرا عطا فرمود، و گفت این خون بهای تست، چه اگر میکال ترا دریافته بود، میکشت، اینهم ده هزار درهم دیگر برای عیالت، راه خود برگیر و برو، آنگاه فرمان داد تا رخنه را سد کنند. و قدغن کرد که من بعد احدی از آن رخنه به اندرون میدان نشود. خبر داد مرا عبیداﷲبن ابی الفتح به اسناد خود از ابوالقاسم السکونی که گفت جعفربن الحسین این دو بیت را از گفته ٔ یکی از محدثان در مرثیه ٔ طاهربن الحسین برای من خواند:<br />فلئن کان للمنیة رهناً<br />ان افعاله رهین الحیاة<br />و لقد اوجب الزکاة علی قو<br />ِم و قد کان عیشهم بالزکاة<br /> <font color=\"Red\">(تاریخ بغداد ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٥٥</span>، <span class=\"hlight\" dir=\"rtl\">٥٤</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٣</span>).</font><br />و صاحب قاموس الاعلام ترکی آرد: طاهر (ابوالطیب بن حسین بن مصعب بن رزیق الخزاعی ) نام مؤسس سلسله ٔ طاهریان در خراسان است که از رجال بزرگ دولتی عباسیان بود و در نزد مأمون خلیفه مقام و منزلت ارجمندی داشت و وی رابا عساکر برای جلوگیری از ابویحیی علی بن عیسی بن ماهان مأمور کرد و به سال <span class=\"hlight\" dir=\"rtl\">١٩٥</span> هَ . ق . در ری تلاقی فریقین اتفاق افتاد و ابویحیی به قتل رسید پس طاهر رو به بغداد نهاد و آن شهر را محاصره کرد و امین را مقتول ساخت و سبب جلوس مأمون به مسند خلافت گردید و از این رو طاهر ظاهراً مظهر احترامات بسیار از طرف مأمون شد ولی در باطن کینه ٔ کشتن برادرش وی را آسوده خاطرنمی گذاشت، از سوی دیگر طاهر هم نگرانی خلیفه را احساس میکرد از این رو برای دوری از حضور استدعای ولایت خراسان کرد و پس از حصول اجازه به سال <span class=\"hlight\" dir=\"rtl\">٢٠٥</span> هَ . ق . بدان ناحیه عزیمت کرد و پس از مدتی به هوس استقلال افتاد ولی فرمانروائی او دولتی مستعجل بود چند روزی خطبه را بنام وی خوانده بودند که به سال <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> درگذشت . یک چشم طاهر کور بوده و لقب «ذوالیمینین » داشته و سبب تلقب وی بدین لقب این است که وقتی مأمون خلیفه حضرت علی بن موسی الرضا را به ولیعهدی برگزید به وی تکلیف بیعت با امام علیه السلام کردند، او دست چپ خویش را پیش آورد و در حال بیعت گفت «دست راستم در قید بیعت به خلیفه است ». مأمون در این حال گفت «دست چپی که به حضرت امام بیعت میکند دست راست محسوب میشود». تولد طاهر به سال <span class=\"hlight\" dir=\"rtl\">١٥٩</span> هجری بوده و در چهل وهشت سالگی درگذشته است و جد وی «رزیق بن ماهان » از بردگان آزادشده ٔ جوانمرد و مشهور طلحة الطلحات خزاعی است که در کرم و سخاوت بی نظیر بوده جدش «مصعب بن رزیق » نیز، کاتب سلیمان بن کثیر الخزاعی از طرفداران و هوی خواهان بزرگ خلافت عباسی بوده و پدرش مصعب در <span class=\"hlight\" dir=\"rtl\">١٩٩</span> هَ . ق . در خراسان درگذشته و مأمون خلیفه نماز میت برو گذارده و تعزیت نامه ای به بغداد برای طاهر فرستاده است . طاهر مردی ادیب و فصیح و مدبر بوده و ارزش زیاد برای شعر و شعرا قائل میشده، دو پسرش طلحه و عبداﷲ در خراسان اخلاف وی بودند. رجوع به کتاب التاج ص <span class=\"hlight\" dir=\"rtl\">٣١</span>، <span class=\"hlight\" dir=\"rtl\">٧٤</span>، <span class=\"hlight\" dir=\"rtl\">١٩٤</span> و التفهیم ص <span class=\"hlight\" dir=\"rtl\">٤٨٢</span>، <span class=\"hlight\" dir=\"rtl\">٤٨٣</span>، <span class=\"hlight\" dir=\"rtl\">٤٨٩</span>، <span class=\"hlight\" dir=\"rtl\">٤٩٠</span>، <span class=\"hlight\" dir=\"rtl\">٤٩١</span> و عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٣</span> و ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٧</span> و الاعلام زرکلی ص <span class=\"hlight\" dir=\"rtl\">٤٤٣</span> و جهانگشای جوینی چ اروپا ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٧</span> و <span class=\"hlight\" dir=\"rtl\">١٨٨</span> و تاریخ الخلفا صص <span class=\"hlight\" dir=\"rtl\">١٩٨</span> - <span class=\"hlight\" dir=\"rtl\">٢٠٣</span> و تاریخ بیهق ص <span class=\"hlight\" dir=\"rtl\">٦٦</span> و النقود صص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>-<span class=\"hlight\" dir=\"rtl\">١٢٤</span> و تاریخ بخارا ص <span class=\"hlight\" dir=\"rtl\">٩٠</span> و کامل ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٦</span> و سبک شناسی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span>و <span class=\"hlight\" dir=\"rtl\">٢٢٢</span> و تاریخ بیهقی چ دکتر فیاض ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٥</span>، <span class=\"hlight\" dir=\"rtl\">١٤٠</span>، <span class=\"hlight\" dir=\"rtl\">١٤١</span>، <span class=\"hlight\" dir=\"rtl\">١٤٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٨٠</span> و احوال و اشعار رودکی گردآورده ٔ سعید نفیسی ص <span class=\"hlight\" dir=\"rtl\">٢٢٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>، <span class=\"hlight\" dir=\"rtl\">٣١٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٢٤</span>، <span class=\"hlight\" dir=\"rtl\">٣٢٧</span> و تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٣٠٨</span>، <span class=\"hlight\" dir=\"rtl\">٣١٢</span>، <span class=\"hlight\" dir=\"rtl\">٣١٥</span>، <span class=\"hlight\" dir=\"rtl\">٣١٦</span>، <span class=\"hlight\" dir=\"rtl\">٣٧٩</span> و فرهنگ ایران باستان ص <span class=\"hlight\" dir=\"rtl\">٢٨١</span> و تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">١٧٢</span>، <span class=\"hlight\" dir=\"rtl\">١٧٧</span>، <span class=\"hlight\" dir=\"rtl\">١٩٠</span> و حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٨</span>. و رجوع به ابوالطیب طاهر و ایضاً ذوالیمینین در همین لغت نامه شود.<br /></font></div>'),
(175448, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن خالدبن نزاربن المغیرةبن سلیم، ابوالطیب الغسانی الایلی . طاهر به «سرمن رای » فرود آمد، و در آن شهر از پدر خود و آدم بن ابی ایاس روایت حدیث کرده یحیی بن محمدبن صاعد، و حسن بن محمدبن شعبه، و محمدبن القاسم الکوکبی، و اسماعیل بن العباس الوراق، و محمدبن مخلد العطار، و محمدبن جعفر المطیری، از او روایت کرده اند. او مردی ثقه بود. ابن ابی حاتم گوید: پدرم در ضمن نامه ای که از سامرا برای من فرستاده بود، بتقریبی نامی از طاهر غسانی ایلی برده، و او را بجمله ٔ «و هو صدوق » توصیف کرده بود. خبر داد ما را ابوعمر عبدالواحدبن محمدبن عبداﷲبن مهدی، خبر داد ما را محمدبن مخلد العطار، خبر داد ما را طاهربن خالد، خبر داد ما را پدرم، خبر داد ما را ابراهیم بن طهمان، خبر داد مرا عامربن عبدالواحد، از صعصعةبن معاویة، از ابی ذر که او گفت پیغمبر صلی اﷲ علیه و آله و سلم فرمود ما من مسلم ینفق من ماله زوجین فی سبیل اﷲ الادعته الجنة هلم هلم - خبر داد ما را سمسار، خبر داد ما را صفار، حدثنا ابن قانع، که طاهربن خالدبن نزار، در سال <span class=\"hlight\" dir=\"rtl\">٢٦٠</span> هَ . ق . در شهر سر من رای وفات یافت . خبر داد ما را عبیداﷲبن احمدبن شاهین از پدرش که گفت در نوشته ٔ جدم یافتم که گفته است از احمدبن محمدبن بکیر شنیدم که گفت طاهربن خالدبن نزار، در سال <span class=\"hlight\" dir=\"rtl\">٢٦٣</span> هَ . ق . وفات یافت . خبر داد مرا احمدبن محمد العتیقی، خبر داد ما را علی ّبن عبدالرحمن بن احمدبن یونس بن عبدالاعلی المصری، خبر داد ما را پدرم که گفت طاهربن خالدبن نزار ایلی در بغداد به سال <span class=\"hlight\" dir=\"rtl\">٢٦٣</span> هَ .ق . زندگانی را بدرود گفت . جز دو روایت اخیر، دیگران نیز چنین گفته اند. جز آنکه در روایت خود افزوده اند که فوت او در ماه شعبان بوده است . (تاریخ خطیب ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٥</span>) و در لسان المیزان آمده است : طاهربن خالدبن نزار ایلی، راستگو است و او را احادیث منکر نیز هست . ابن ابوحاتم گوید با پدرم در سامره از او حدیث نوشتم واو راستگو است . دولابی گوید: برای او کتاب میخریده وبسوی وی میفرستاده و به وی خبر میداده است -انتهی . و ابن عدی گوید او را از پدرش افرادات و غرایبی است .و خطیب گوید محدثی ثقه است . و دارقطنی گوید او و پدرش ثقه اند -انتهی . و هم ابن عدی گوید طاهربن خالدبن نزاربن مغیرةبن سلیم پدرش مکنی به ابویزید و کنیه ٔ خود وی ابوالطیب بوده است . (لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span>).<br /></font></div>'),
(175449, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن حمدان الرازی، ابوعبداﷲ اللاسکی، به اصفهان آمد. و تا زمان بدرود زندگانی، در اصفهان اقامت گزید. و وفات وی بعد از سال شصتم هجرت بود. حدثنا ابوعبداﷲ طاهربن احمدبن حمدان اللاسکی، حدثنا محمدبن جعفر الاشنانی، حدثنا محمدبن یوسف الفراء، حدثنا هشام بن عبیداﷲ، حدثنا محمدبن الفضل، عن صالح بن حسان، عن نافع، عن ابن عمر، قال قال رسول اﷲ صلی اﷲ علیه و آله و سلم لیومکم اقرؤکم و ان کان ولد زنا. (اخبار اصبهان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span>).<br /></font></div>'),
(175450, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن حمادبن عمرو نصیبی . او را از مالک و دیگران روایت است . ثقه و مورد اعتماد نیست . از آزمون های وی این است که گفت عمری از نافع و او از ابن عمر (رض ) به ما خبر داد و گفت در پشت سر پیامبر (ص ) و ابوبکر و عمر نماز خواندم و آنها (بسم اﷲ الرحمن الرحیم ) را بطور جهر قرائت کردند. (لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span>).<br /></font></div>'),
(175451, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ]</font></b> (اِخ ) ابن حفص . یکی از پیشروان عبدالرحمن خارجی که بزینهار یعقوب بن لیث آمدند. رجوع به تاریخ سیستان حاشیه ص <span class=\"hlight\" dir=\"rtl\">٢١٧</span> و زین الاخبار گردیزی چ تهران ص <span class=\"hlight\" dir=\"rtl\">٧</span> شود.<br /></font></div>'),
(175452, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن الحسین القواس . کنیتش ابوالوفا بوده در جامع منصور به فتوی دادن و وعظ اشتغال داشت . تدریس فقه و قرائت قرآن میکرد. مردی زاهد و آمر به معروف بود. نزدیک به پنجاه سال در مسجد منصور اقامت گزید و روان خویش را در طریق عبادت و سختی معیشت همواره قرین مشقت داشتی، در شب جمعه ٔ هفتم شعبان سال <span class=\"hlight\" dir=\"rtl\">٤٧٣</span> هَ . ق . دنیا را بدرود گفت . او را در جوار شریف ابوجعفر دفن کردند. (مناقب احمدبن حنبل ص <span class=\"hlight\" dir=\"rtl\">٥٢٣</span>).<br /></font></div>'),
(175453, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن الحسین الاعور. رجوع به طاهربن الحسین ملقب به ذی الیمینین شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175454, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن خلف بن احمد. حمداﷲ مستوفی آرد: و در سنه ٔ اربع و سبعین و ثلثمائه (یمین الدوله محمود) بجنگ خلف بن احمد به سیستان رفت جهت آنکه خلف پسر خود طاهر را بعد از مراجعت از حج ولیعهد کرده و حکومت داده و خود به طاعت حق تعالی مشغول شده باز پشیمان گشته بود و بر پسر غدر کرد و او را کشت . یمین الدوله محمود بدین انتقام با او جنگ کرد. (تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٣٩٦</span>). و صاحب تاریخ یمینی آرد: خلف بن احمد، در ایام فترت ملک و حدوث واقعه ٔ ناصرالدین، طاهر پسر خویش را به قهستان فرستاده بود، و قهستان و بوشنج از جمله ٔ مضافات هرات بود، و در اعتداد بغراجق عم سلطان معتد، چون از جوانب دیگر فراغ حاصل شد بغراجق از سلطان دستوری خواست تا ولایت خویش را از دست متغلب بیرون کند، و جواب منازع و معارض را بازدهد، اجازت فرمود و بغراجق به بوشنج آمد و طاهر به مناصبت و محاربت او بیرون آمد، و میان ایشان مقاومتی سخت قائم گشت، و خاتمت کارطاهر منهزم گشت، بغراجق برعقب او میرفت و متابعان او را میگشت، و رحل و ثقل او می ستد، و او ساغری چند شراب خورده بود، سورت مستی بر او استیلا یافته، و عنان تحفظ و تیقظ از دست او بستده، و چشم بصیرت و احتراس او از معاقرت چند کأس در سکرت غفلت مانده، تا خود را در ورطه ٔ غرور و خطر انداخت، ناگاه طاهر عطفه ای کرد، و بضربه ای او را از مرکب بینداخت و فرود آمد، و سرش برداشت، و هر دو فرقه از هم متفرق و منهزم شدند.طاهر لشکر خویش را با هم فراهم آورد، و به قهستان رفت، و سلطان از خبر واقعه ٔ عم، مضطرب و غمناک شد و در حال پسر خلف و احداق شقاق، و تحکک او بعوارض بلاء، و تورط وی در مهاوی عنا، و آنکه مثل وی چون مور بود که بال او سبب وبال وی شود، و چون مار که هنگام مصارع هلاک، به مشارع شارع خرامد، بدین ابیات تمثل کرد:<br />اشارت الفرس فی اخبارها مثلاً<br />وللاعاجم فی ایامها مثل ُ<br />قالوا اذا جمل حانت منیته <br />اطاف بالبر حتی یهلک الجمل ُ.<br />و در شهور سنه ٔ تسعین و ثلثمائة به انتقام این واقعه به سیستان رفت، و خلف در حصار قلعه ٔ اسپهبد نشست، قلعه ای که حلیف سماک، و الیف افلاک است، ابر در دامن حضیضش خیمه زند، و ستاره پیرامن اوجش طواف کند، هلال چون ماهچه بر شرف برجش، و زحل چون کوکبی بر آستانه ٔ قصرش (نظم ):<br />از بلندیش فرق نتوان کرد<br />آتش دیده بان ز جرم زحل <br />و خلف در مضیق آن حصار بیقرار شد، و خواب خوش و لذّت زندگانی وداع کرد، و در ظلمت آن حادثه و هول آن واقعه بی آرام گشت، و طریق کار جز زاری و تضرع و لابه و تخشع نمیدید، صدهزار دینار زر سرخ و آنچه ضمیمه ٔ آن باشد، از تحف و مبار، بر سبیل نثار مقدم سلطان قبول کرد، و زنهار خواست، سلطان اگر چه بر استخلاص سیستان و استصفای آن نواحی جازم بود، حالی بحکم مصلحت وقت و نیت غزوی که کرده بود، اطراف آن کار فراهم گرفت . و آن فدیه ازخلف قبول کرد. و عنان بگردانید. و روی بدیار هند نهاد. (تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٤٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٤</span>). و چون از کار هند فراغت یافت . خلف بن احمد در آن اثنا طاهر پسر خویش را ولیعهد کرد و مفاتیح خزائن بدو سپرد، و مقالید ممالک به وی تسلیم کرد، و خود منزوی شد، و روی بعبادت آورد، و به تنسک تمسک جست، و از ملک استعفا نمود، تامگر به وسیلت این حالت کأس یأس، و دور جور سلطان از او درگذرد، و چون مدتی بر این حال بگذشت، از کرده پشیمان شد، و بر ترک ملک، و تجافی از منصب حکم نادم گشت، و مکنت تظاهر و قدرت تجاهر، بوارد خاطر، و حادث اندیشه ٔ خود نداشت، تا حیلتی برانداخت و خود را بیمار ساخت و پسر را از بهر تجدید وصیت، و تمکین از خفایا و خبایای ودیعت پیش خواند، و طایفه ای از خواص خویش در کمین نشاند تا به وقت وصول او، چون خیل زباء، پیرامن جذیمه درآمدند و او را محکم ببستند، و در مطموره ای بازداشتند، و روزی او را مرده از حبس بیرون آوردند، و گفتند خود را هلاک کرد. (تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٤٨</span>).در تاریخ سیستان آورده که امیر عمرو و بانصر و بوالفضل (سه پسر دیگر خلف ) برفتند (یعنی بمردند) و امیر طاهر که شیر باریک خوانند ماند، و بکرم رستم دستان برآمد و عالم همه از او رنگ گرفت، دو راه بست بگرفت و دو راه قاین و یک راه کرمان، و بحرب امیر بوعلی شد بیاری سبکتکین، چون حرب کردند و ظفر یافتند قصد امیر طاهر کردند و بغراجوگ با دوازده هزار سوار از پس او بپوشنج آمدند، طاهر با صد سوار غلامان خویش بازگشت و حرب کرد و بغراجوگ را بکشت و سر اوی بیاورد و هفت پیل از آن لشکر بیاورد و بسیار اسبان و سلاح و خزینه، و مردی شد که همه ٔ جهان خبر او بشد از مردی و مردمی و مروت و خرد و سخاوت، و امیر خلف بدو شاد بود، تا روزگار برآمد و چشم زدگی رسید، و امیر خلف به کوه اسپهبد شد با حرم و خدمتکاران بشغلی، و سبب افتاد که سلطان محمودبن سبکتکین آنجا بگذشت با سپاهی انبوه و پیلان بسیار، و خبر شنید که امیرخلف اینجا با حرم و زنان به کوه است، و سپاه امیرطاهر به سیستان است، سلطان محمود به پای کوه شد، هیجده روز گذشته از جمادی الاخرسنه ٔ تسعین و ثلثمائة و بر امیرخلف هیچکس نبود الا زنان و خادمان سیاه .<br />آمدن سلطان محمودبن سبکتکین رحمه اﷲ به پای کوه اسپهبد - و عدّت سلطان را قیاس نبود، و کوه را فروگرفتند چنانکه هیچکس چراغ نتوانستی افروخت بشب، که اندرساعت آن خانه پر تیر کردندی، و منجنیقها برساخت، آخر امیرخلف بر صلح فروایستاد و صدهزار درم او را بپذیرفت، و خطبه ... و نام محمود بر یک روی نبشت ... و سلطان زانجا بازگشت روزشنبه چهار روز گذشته از رجب سنه ٔ تسعین ؛ و امیرخلف چشم داشت که امیر طاهر و سپاه سیستان شبیخون آرند برسپاه سلطان و ایشان غفلت کرده بودند و تا ساخته شدند سلطان رفته بود؛ امیرطاهر از پدر هراسان گشت، عاصی شد و پیلان پدر و سپاه برگرفت و به کرمان شد و همچنان بشد تا به پارس و هیچکس با او نایستاد.<br />رفتن امیر طاهر به کرمان در شعبان سنه ٔ تسعین و ثلثمائة - و امیرخلف از کوه چون خبر شنید، دل شکسته بیامد هم اندر شعبان به حورندیز آمد و آن مردمان که سپاه محمود را علف داده بودند چون دولت بازگشته بود بفرمود تا غله ٔ ایشان بسوختند، و آن ناهمیون دارند، ایزد سبب کرد اندرآن سال تا آنجا چندانی ترنجبین افتاد که هر مردی رااز آن هزار من به دست آمد، تا خُرد و بزرگ آن غنی گشتند؛ و امیرخلف بقلعه ٔ طاق شد، و بر مردمان سیستان و مشایخ و عیاران خشم گرفت، و ایشان از او ترسان گشتند و هیچکس را یارگی آن نبود که سوی وی شدی، الا فقیه بوبکر نیهی را، و امیرخلف بطاق ببود، ماه روزه آنجابداشت، و عید را بشهر آمد، و هیچکسی را بخویشتن راه نداد، مکر فقیه بوبکر را و بزودی بازگشت و باز طاق شد، باز اندر ذی القعده بشهر آمد، و مشایخ را دستوری داد تا پذیره ٔ او شدند، و سلام کردند بکده ٔ دریشک وز آنجا بشهر اندر آمد، چون عید اضحی بگذشت، روزی چند برآمد، امیر طاهر از کرمان بازآمد با گروهی اندک و حالی تباه .<br />بازآمدن امیر طاهر از کرمان - و رسولی فرستاد سوی پدر که من آنچه کردم زان کردم که از سایه ٔ وی بترسیدم، اکنون رفت آنچه رفت، من بنده ٔ اویم و جان فداء او دارم، باز آمدم، مرا جای پیدا کن تا آنجا شوم، مرا نفقاتی باشد بدان قناعت کنم، امیرخلف دشنام داد رسول را. و او را گفت فرزندِ من نیست و کردنی با او نکنم ! چون رسول پیغام بازآورد امیر طاهر قصد شهر کرد، امیرخلف خبر شنید سپاه بیرون کرد و سپهسالارِ امیرطاهر، طاهر زینب بود که آن گاه سرهنگ خواندندی او را؛ سپاه امیرطاهر و امیرخلف به لب هیرمند هر دو برابر افتادند و حرب کردند، امیر طاهر سپاه پدر را هزیمت داد، ترسناک پیش امیرخلف آمدند، شکسته و خسته و بعضی کشته، و امیرخلف دانست که محنت رسیده است که پیش فرزندهمی باید گریخت، و برفت با خواص خویش به طاق شد، و امیرطاهر بشهر اندرآمد بامداد روز سه شنبه غُرّه محرم سنه ٔ احدی و تسعین، و مردمان قصبه بفرمان امیرخلف درهاء حصار بسته بودند و امیرطاهر اندر قصر یعقوبی فرود آمد و بنشست و سپاه او قوی و بانوا و غنی گشته بودند از سپاه پدر آنجا فرود آمدند و عیاران سیستان سوی او شدند، چون وقت نماز پیشین بود درهاء حصار بگشادند، و شهر امیر طاهر را صافی شد. و حصارها به هر جای، مگر طاق که پدر آن حصار گرفته بود.<br />درآمدن امیرطاهر اندرشهر و گرفتن ولایت - پس دیرگاه برنیامد تا امیرطاهر سپاه و سرهنگان و عیاران و غوغاء شهر جمع کرد و بپای حصار طاق شد و حرب فروگرفتند و منجنیقها از زیر و زبر برکار کردند، بی هیچ حشمت و محابا؛ باز امیرطاهر پس از مدتی ز آنجا بازگشت و بشهر آمد و رسولان اندر میان ایستادند و صلح کردند، و امیرخلف همه خواص خویش را پیش او فرستاد تا خدمتها کردند، و امیرطاهر فریفته گشت، تا برخاست با گروهی اندک که پیش پدر شودو کسانی که گستاخ بودند گفتند نباید شد که امیرخلف مکار است و محنت او را دریافته است، و فرزند تو مانده ای نباید که خطائی رود و مادّت این ملکت و دولت از این خاندان به سبب کینه کشیدن او منقطع گردد، چه هر کس که دولت از او بگردد او را راههاء کژ نماید تا آن مملکت و دولت برود امیرطاهر فرمان نکرد، و بر گروهی اندک برفت، و بپای حصار فرود آمد و به پدر کس فرستاد که اینک من آمدم، و برنشست و به در حصار شد، پدر چون او را بدید از دور، هم از آنجا فرود و پیاده شد، و تتبوی مهتر و تتبوی کهتر، دو زنگی بودند از مبارزان امیرخلف هر دو را از پس در حصار متواری کرده بود که چون من او را اندر برگیرم و گویم که الحمداﷲ، شما بیرون آئید و با من یاری کنید تا او را اندر حصار آرم ؛ امیرطاهر چون پدر را پیاده دید و شکوه ٔ پدری در دل او بود، از اسب فروجست و زمین بوسه داد و سبک فرازوی شد، و پدر او را اندر برگرفت و الحمداﷲ بگفت ؛ تتبویان بیرون جستند و او را محکم کردند که هیچ سلاح باوی نبود و به دل هیچ غش ّ نداشت و عهدها گرفته بود وسوگندان خورده، و امیرخلف هم عهد کرده بود و سوگندان مغلظه خورده، اما خلاف کرد و او را بر قلعه برد و بند برنهاد و سپاه که بر او بودند به هزیمت به قصبه آمدند، و او رحمةاﷲ علیه اندر آن بند فرمان یافت، روزدوشنبه بود چهار روز گذشته از جمادی الاولی سنه ٔ اثنی و تسعین و ثلثمائة. (تاریخ سیستان صص <span class=\"hlight\" dir=\"rtl\">٣٤٥</span>-<span class=\"hlight\" dir=\"rtl\">٣٥١</span>). و رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٣</span> و کامل ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩</span> و حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٥</span>، و <span class=\"hlight\" dir=\"rtl\">٣٧٦</span> و <span class=\"hlight\" dir=\"rtl\">٦٢٧</span> شود.<br /></font></div>'),
(175455, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن رشید. او را از سیف بن محمد به روایت از اعمش خبر باطلی است . ازدی گوید: نمیدانم او در این حدیث به دروغ پرداخته یا سیف ؟ -انتهی . و حدیث او پس از رفع (معنعن کردن ) این است از سیف از اعمش از ابوصالح از ابوهریره عادت به نیکی کنیدچه نیکی عادتی است . (از لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span>).<br /></font></div>'),
(175456, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن زنگی بن طاهر ملقب به عزالدین فریومدی . وزیر خراسان . و مؤیدی دهستانی کتاب الفرج بعدالشدّة را بنام او از تازی به پارسی ترجمه کرده است . (ترجمه ٔ تاریخ ادبیات براون ج <span class=\"hlight\" dir=\"rtl\">٤</span>ص <span class=\"hlight\" dir=\"rtl\">١٣٥</span>) و صاحب «الذریعه » آرد: ابن زنگی فریومدی سلطانی است که حسین بن اسعد (سعد) بن حسین دهستانی مؤیدی مؤلف «جامعالحکایات فی ذکر الفرج بعدالشدة» تألیف خود را بنام وی کرده است . (از الذریعه ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br /></font></div>'),
(175457, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن زید احمد الفقیه . مردی ثقه و دانشمند بوده و نزد شیخ ابوعلی طوسی تلمذکرده است . (روضات ص <span class=\"hlight\" dir=\"rtl\">٣٣٦</span> ذیل ترجمه ٔ طاهر جرجانی ).<br /></font></div>'),
(175458, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن زینب . یکی از سرکردگان عساکرخلف بن احمد فرمانروای سیستان بوده است . (تاریخ یمینی چ تهران ص <span class=\"hlight\" dir=\"rtl\">٢٤٩</span>) و در نسخه ٔ خطی تاریخ یمینی متعلق به کتابخانه ٔ مؤلف ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span> طاهربن ربیب ضبط شده است . مؤلف حبیب السیر (چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٦</span>) آرد: در آن هنگام که خلف بن احمد بدسیسه پسر خود طاهر را بکشت طاهربن زینب و بعضی دیگر از اعیان امراء سیستان که این حرکت شنیع از خلف مشاهده نمودند خاطر برخلاف او قرار داده عریضه ای نزد یمین الدوله فرستادند و استدعا نمودند که لواء ظفر انتها بدان صوب توجه نماید... و رجوع به تاریخ سیستان خلف زینب ص <span class=\"hlight\" dir=\"rtl\">٣٤٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٥١</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٣</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٤</span> شود.<br /></font></div>'),
(175459, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن سعید ابوالقاسم المقری ٔ النیشابوری . وی از عبیداﷲبن موسی العبسی، و ابونعیم، و آدم بن ابی ایاس، سماع حدیث کرده . ابراهیم بن علی الذهلی، و حسن بن سفیان نیز از او روایت دارند. حاکم ابوعبداﷲ، محمدبن عبداﷲ النیسابوری حافظ، ذکر کرده است که طاهر مقری ٔ نیشابوری، در نیشابور و بغداد تحدیث میکرد. محمدبن علی المقری مرا خبر داده، گفت محمدبن عبداﷲ الحافظ مرا خبر داد که بخط ابی عمرو المستملی خواندم که طاهربن سعید المقری در ماه جمادی الاخرة سال <span class=\"hlight\" dir=\"rtl\">٢٤٧</span> هَ . ق . درگذشته است . (تاریخ خطیب ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٥</span>).<br /></font></div>'),
(175460, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن حسین بن یحیی مخزومی بصری، مکنی به ابومحمد. وی در بصره متولد شده و در ری سکونت داشته است . او بر بیشتر شاعران عصر برتری دارد و از شاعران عراق در ردیف ابن نباته و ابن بابک و از شاعران جبل برابر با رستمی و خازن است . او را تصنیفاتی است که از آن جمله میتوان کتاب فتق الکمائم فی تفسیر شعر المتنبی را نام برد. طاهر در ری زندگانی را بدرود گفته است دید چشم او خوب نبود و روزی به درد چشم مبتلا شد والی منبج به او گفت ای ابوالغوث، نزدیک است کور شوی و اگر به کوری مبتلا گردی چه خواهی کرد؟ گفت ای امیر! آن وقت بر سر گورتو قرآن خواهم خواند. والی مزبور از سرعت جواب و ظرافت گوئی او در شگفت شد. از اشعار او شاهکارهائی که بمنزله ٔ سحر است برگزیده ام و از آن جمله منتخبات ذیل است که از نیکوترین و بدیعترین اشعار بشمار میرود:<br />نفسک لاتعطیک کل الرضا<br />فکیف ترجو ذاک من صاحب <br />اجل مصحوب حیوة صفت <br />فهل خلت من هرم عائب <br />و در این معنی شاعری بر او سبقت نجسته است :<br />العیب فی الخامل المغمور مغمور<br />وعیب ذی الشرف المذکور مذکور<br />کفوفة الظفر تخفی من مهانتها<br />و مثلها فی سواد العین مشهور<br />و چه شعری ملیح و شیوا در غزل گفته است :<br />عرضت قلبی للحتوف بعارض <br />کالورد نداه الصباح بطله <br />متوشحا زغب العذار کانما<br />القی علیه الصدغ سمرة ظله <br />و این شعر را درباره ٔ کسی سروده است که از لحاظ رتبه فروتر از وی بوده و بر او پیشی جسته است :<br />جل قدری و خس ّ قدر زمانی <br />فانا العضب فی یمین الاشل <br />و در وصف دنیا گوید:<br />اذا تبرجت الدنیا فعاهرة<br />خضابها دم من تصبی فتعتال <br />کانها حیة راقت منقشة<br />ولان ملمسها والسم قتال <br />مضمون آن را از گفتارامیرالمؤمنین علی بن ابیطالب رضی اﷲ تعالی عنه گرفته است که میفرماید:<br />الدنیا کالحیة لین مسها قاتل سمها یحذرها العاقل و یهوی الیها الجاهل . و درباره ٔ تصوف گوید:<br />لیس التصوف ان یلاقیک الفتی <br />و علیه من نسج النحوس مرقع<br />بطرائق سود و بیض لفقت <br />و کانه فیها غراب ابقع<br />ان التصوف ملبس متعارف <br />یخشی الفتی فیه الاله و یخشع<br /> <font color=\"Red\">(از تتمة الیتیمه ج <span class=\"hlight\" dir=\"rtl\">١</span> به اختصار ص <span class=\"hlight\" dir=\"rtl\">٢٠</span> و <span class=\"hlight\" dir=\"rtl\">٢١</span>).</font><br />و رجوع به تاریخ جهانگشای جوینی ج <span class=\"hlight\" dir=\"rtl\">٢</span> حاشیه ص <span class=\"hlight\" dir=\"rtl\">٢٦٨</span> شود.<br /></font></div>'),
(175461, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن حسین بن عبدالرحمن اهدل از فقیهان و محدثان یمن . مولد او به سال <span class=\"hlight\" dir=\"rtl\">٩١٤</span> در قریه ٔ مراوغه بوده و در روز چهارشنبه <span class=\"hlight\" dir=\"rtl\">١٧</span> ربیعالاول سال <span class=\"hlight\" dir=\"rtl\">٩٠٨</span> هَ .ق . درگذشته است . رجوع به النور السافر ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span> شود.<br /></font></div>'),
(175462, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن الحسن بن الحبیب الحلبی، متوفی به سال <span class=\"hlight\" dir=\"rtl\">٨٠٨</span> هَ . ق . نسب وی چنین است طاهربن الحسن بن عمربن حبیب بن شُویخ الزّین ابوالعزّبن البدر، ابی محمد الحلبی الحنفی ّ. و یعرف بابن الحبیب . ولادت وی در حلب اندکی بعد از سال <span class=\"hlight\" dir=\"rtl\">٧٤٠</span> بوده است، از ابراهیم پسر شهاب محمود و جز او سماع حدیث کرده، شهاب ابوالعباس مرداوی، خاتمه ٔ اصحاب ابن عبدالدائم و محمدبن عمر السلاوی و جز آندو، از دمشق اجازت روایت حدیث برای ابن حبیب به حلب فرستادند. وی دیرگاهی بتحصیل علم و دانش عمر بسر برد، چندی ابوجعفر غرناطی و ابن جابر و جز آندو تن را ملازم بود، خطّ منسوب را نیک نبشتی، در علوم ادب براعت یافت، تلخیص المفتاح را که در معانی و بیان است، و سراجیه را که در فرائض حنفیه است، با محاسن الاصطلاح بلقینی بنظم آورد. قصیده ٔ برده را شرح و تخمیس کرده، ذیلی بر تاریخ پدر خویش نوشته بهمان سبک و روش، سفری به دمشق شام و قاهره ٔ مصر کرد، و در هر یکی از آن دو شهر مدتی اقامت گزید و در حلب به کتابت در دارالانشاء برقرار گردید. در قاهره نیز علاوه بر آنکه بسمت مذکوره چندی ادامه ٔ شغل داشت، به نیابت کاتب سِرّ هم ارتقا یافت . چندین نوبت خواستند تولیت وظیفه را بدو محول کنند، آماده ٔ قبول آن نشد. (بنابر گفته ٔ عینی ). شیخ ما در کتاب «اِنباء» خود (مراد ابن حَجرِ عسقلانی و کتاب «انباء الغمر فی ابناء العمر» است ) گفته که ابن حبیب چند شغل را متولی شد. او با ادباء قدماء عصر خود مطارحاتی داشت، مانند فتح الدین بن الشهید، که دو بیت برای ابن حبیب نوشته جهت او فرستاد، ابن حبیب پاسخ او را در سی و سه بیت فراهم آورده ارسال داشت . با سراج عبداللطیف فیومی نزیل حلب نیز مطارحه داشت . اشعار بسیاری به نظم آورده و ما بین آن اشعار ابیات نظم محاسن الاصطلاح از سایر اشعار او نیکوتر است . و بطور کُلی ابن حبیب در نظم و نثر مُفلق نبوده است . این اشعار از اوست :<br />قلت له اِذماس َفی اخضر<br />وطَرفُه اَلبابُنا یسحرُ<br />لَحظک ذا او اَبیض ُ مُرهف ٌ<br />فقال هذا موتک الاحمر<br />ابن خطیب ناصریه گوید ابن حبیب ناظمی بلیغ بود و فصیح، در صناعت انشاء تام ّ الفضیلة بود بنحوی که او را برای کتابت سِرّ دارالانشاء مصر تعیین کردند. این قطعه که مصراع اخیر آن تضمین است از اوست :<br />اَضحی یُموه ُِ و هو یعلم اننی <br />کلف ٌ به و لذاک لم یَتعطف ِ<br />فغدوت انشدو الغرام یبرنی <br />روحی فداک عرفت ام لم تعرف <br />هنگامی که ملک ظاهر سیف الدین برقوق، مِنطاش را دستگیر کرد و کشت، ابن حبیب این دو بیت بگفت :<br />الملک الطاهر فی عِزّه <br />اَذَل ُ من ضل َ و من طاشا<br />وردّ فی قبضته طائعاً<br />نُعیراً العاصی و منطاشا<br />شیخ ما گفته است با ابن حبیب در یک جای فراهم آمدیم و سخن او شنیدم و گمان میبرم حدیثی نیز از او استماع کردم و از اشعار خود برای من بیتی چند برخواند، لکن اکنون مرا بهیچیک از حدیث و اشعار او دسترس نیست . ابن حبیب در قاهره ٔ مصر روزجمعه ٔ هفدهم ذی الحجه ٔ سال <span class=\"hlight\" dir=\"rtl\">٨٠٨</span> هَ . ق . وفات یافت . شیخ ما در معجم خود و مقریزی در عقود فی تاریخ العهودنام او را ذکر کرده است . (تاریخ حلب ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٨</span> بنقل از الضوء اللامع فی اعیان قرن التاسع). از مؤلفات ابن حبیب، بقول مؤلف تاریخ حلب، مختصری در علم اصول با سه متن دیگر در همان علم، به سال <span class=\"hlight\" dir=\"rtl\">١٣٢٤</span> به یکجا درمصر به طبع رسیده است . بنابر ضبط حاجی خلیفه ذیلی بر تاریخ پدرش موسوم به «دُرةُ الاسلاک، فی تاریخ الاتراک » نوشته . و در کشف الظنون اشتباهاً در مورد ذکر این کتاب تاریخ وفات صاحب ترجمه را سال <span class=\"hlight\" dir=\"rtl\">٨٧٩</span> قید کرده، و آن غلط است . و نیز در کشف الظنون چند کتاب دیگر بنام صاحب ترجمه ذکر کرده یکی «شنف السامع، فی وصف الجامع» مراد جامع بنی امیه است . دیگر «مختصر منارالانوار» که منارالانوار نسفی را مختصر ساخته است . دیگر «وشی ُ البردة» در شرح قصیده ٔ برده . (کشف الظنون ). ترجمه ٔ پدر وی در همین لغت نامه ذیل ابن حبیب بدرالدین آمده است .<br /></font></div>'),
(175463, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن امیر ابوالفضل . نصربن احمد.رجوع به بهاءالدوله (در تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٨٣</span>) شود.<br /></font></div>'),
(175464, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن حسن سیستانی، مکنی به ابی المظفر. در یادداشتها چنین صورتی بود ولی مدرکی برای ترجمه ٔ حال وی به دست نیامد.<br /></font></div>'),
(175465, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابن حسین . حمداﷲ مستوفی ذیل حالات السدید منصوربن عبدالملک سامانی آرد: خلف بن احمد سیستانی هوس حجاز کرد داماد خود طاهربن حسین را نیابت داد و به حج رفت به وقت مراجعت دامادش او را در شهر نگذاشت . خلف پناه به امیر منصور برد امیر منصور اورا لشکر داد تا خلف با لشکر به سیستان رفت دامادش شهر بازگذاشت . خلف بر سیستان مستولی شد لشکر را پیش امیر منصور فرستاد. طاهربن حسین باز آمد و با خلف جنگ کرد و شهر بستد خلف باز به امیر منصور پناه برد و لشکر بستد چون به سیستان رسید طاهر درگذشته بود. (تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٣٨٥</span>). و در تاریخ یمینی آمده است : هنگامی که خلف بن احمد پادشاه سیستان عازم حج گردید در سنه ٔاربع و خمسین و ثلثمائة طاهربن الحسین را که از اقرباء و خویشان او بود قائم مقام و جانشین خود قرار داد، طاهر غیبت خلف را غنیمت شمرده، لشکر را بفریفت، وقلاع و خزائن خلف را با دست بگرفت و در پادشاهی سیستان طمع مستحکم کرد، چون خلف بازگشت، مملکت شوریده دید... به منصوربن نوح سامانی التجا کرد، منصور ملتمس او به ایجاب مقرون داشت ... چون طاهر از مدد لشکر منصور خبر یافت ولایت باز گذاشت، و به اسفزار مقیم شد، تا خلف در دارالملک خویش ممکن بنشست، و اعوان و انصارکه از حضرت منصور آمده بودند از سر استغنا باز گردانید، پس ناگاه طاهر بر سر او تاخت و او را شکسته و منهزم به جانب بادغیس انداخت . خلف دیگر باره از سر اضطرار روی با حضرت منصور نهاد، و بدو پناهنده شد... منصور لشکر جرار به کفایت مهم او نامزد کرد. و چون خلف با آن لشکر به سیستان آمد، طاهر وفات یافته بود.<br /></font></div>'),
(175466, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) (الشیخ ) ابن حسین بن طاهر. او راست : «المسلک القریب، لکل ّ سالک منیب » این کتاب با دُعاء بخاری و طریقه ٔ سادات باعلوی که در تصوّف و از تألیفات شیخ احمد دِحلان است، در مطبعه ٔ حسن طوخی به سال <span class=\"hlight\" dir=\"rtl\">١٢٩٦</span> هَ . ق . چ سنگی، و در مطبعه ٔ عمومیه ٔ مصر به سال <span class=\"hlight\" dir=\"rtl\">١٣١٨</span> هَ .ق . به طبع رسیده است (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢٤</span>).<br /></font></div>'),
(175467, 'طاهر', '<span class=\"hlight\">طاهر.</span> <font color=\"DarkGreen\"><b>[هَِ ]</font></b> (اِخ ) ابن الحسین بن طاهر. رجوع به زین الاخبارچ تهران ص <span class=\"hlight\" dir=\"rtl\">٧</span> و به تاریخ سیستان حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">٢١٩</span> شود.<br /></font></div>'),
(175468, 'طاهر باطنی', '<span class=\"hlight\">طاهر باطنی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ طِ ]</font></b> (ترکیب وصفی، اِ مرکب ) عبارت است از کسی که آفریدگار عزّ و علا، مر او را از وساوس و خاطرات نفس و پیوند با اغیار، رهائی بخشوده باشد. (کشاف اصطلاحات الفنون ). رجوع به طاهرالباطن شود.<br /></font></div>'),
(175469, 'طاهر بخاری', '<span class=\"hlight\">طاهر بخاری .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ب ُ ]</font></b> (اِخ ) یکی از مشاهیر علما و مؤلفان است و سه تألیف مهم بنام خلاصة الفتاوی، خزینة الواقعات و کتاب الانساب داردو به سال <span class=\"hlight\" dir=\"rtl\">٥٤٢</span> هَ . ق . درگذشت . (قاموس الاعلام ترکی ).<br /></font></div>'),
(175470, 'طاهر تاتی', '<span class=\"hlight\">طاهر تاتی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ]</font></b> (اِخ ) وی الکن بود و بجای قاف و کاف، تا میگفت، و او یکی از ملازمان میرزا مهدی که معشوق میرنجات بود بشمار میرفت . از شرح گل کشتی . (غیاث ) (آنندراج ).<br /></font></div>'),
(175471, 'طاهر تنکابنی', '<span class=\"hlight\">طاهر تنکابنی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ت ُ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ُ ب ُ ]</font></b> (اِخ ) فرزند میرزا فرج اﷲ تنکابنی (<span class=\"hlight\" dir=\"rtl\">١٢٨٠</span> - <span class=\"hlight\" dir=\"rtl\">١٣٦٠</span> هَ . ق .) دانشمند و فاضل معروف که از قرار مذکور در حکمت و فلسفه ٔ قدیم بسیار متبحر و با اطلاع بوده و کتب بسیار نفیسی از خطی و چاپی جمع کرده بود، وی از شاگردان مرحوم میرزا ابوالحسن جلوه بود و در مدرسه ٔ سپهسالار جدید تدریس میکرد و از قرار مذکور قدرت مطلقه ٔحکام ناحیه ٔ تنکابن تمام املاک خانواده ٔ او را که به بنی فقیه معروف بودند در آنجا غصب کرده بودند و حتی در تهران نیز گویا او را از تدریس در مدرسه ٔ مزبور منع کرده بودند و لهذا در خانه اش درس می گفت، بدبختانه من که فقط دو سال قبل از وفات او از پاریس به طهران مراجعت کرده و از صیت فضل و دانش او چندان مستحضر نبودم توفیق ملاقات آن عالم جلیل را درنیافتم . صاحب ترجمه در هجدهم رمضان سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٢٨٠</span> هَ . ق . در کلاردشت مازندران متولد شده است و در روز جمعه ٔ شانزدهم ذی القعده ٔ <span class=\"hlight\" dir=\"rtl\">١٣٦٠</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٤</span> آذر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٠</span> هَ . ش . در تهران وفات یافت در حدود سن هشتادویک سالگی و برحسب وصیت خود وی در جوار مزار مرحوم میرزا ابوالحسن جلوه واقع در ابن بابویه شش کیلومتری جنوب تهران مدفون گردید . (وفیات معاصرین به قلم محمد قزوینی . مجله ٔ یادگار سال پنجم شماره <span class=\"hlight\" dir=\"rtl\">٤</span> و <span class=\"hlight\" dir=\"rtl\">٥</span>).<br />و مرحوم عبرت آرد میرزا طاهر تنکابنی مقیم تهران از اجله ٔ حکما و عرفا و امروز در حکمت و عرفان و علم طب قدیم کم نظیر بلکه بی مانند است . ازمبرزین شاگردان میرزای جلوه و میرزا محمد رضای قمشه ای است . چندی در مدرسه ٔ سلطانی به افادت و افاضت مشغول بود اینک بواسطه ٔ کثرت سن و ضعف مزاج انزوا اختیار کرده بمطالعه ٔ کتب حکمت و عرفان اوقات میگذراند. یکی از کتابخانه های مهم تهران کتابخانه ٔ اوست . (از مدینةالادب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣٢</span> تألیف عبرت نسخه ٔ خطی کتابخانه ٔ مجلس شورای ملی ). و مؤلف کتاب مازندران می نویسد: ازطایفه فقیه کلارستاق مازندران در محرم سال <span class=\"hlight\" dir=\"rtl\">١٢٨٠</span> هَ .ق . در قریه ٔ کردی چال کلاردشت متولد و در سن هشتادسالگی در <span class=\"hlight\" dir=\"rtl\">١٤</span> آذر ماه <span class=\"hlight\" dir=\"rtl\">١٣٢٠</span> هَ . ش . پس از یک عمل جراحی در بیمارستان نجمیه وفات یافت . میرزامحمد طاهر تا سن <span class=\"hlight\" dir=\"rtl\">١١</span> سالگی در موطن خود سپس تا <span class=\"hlight\" dir=\"rtl\">١٦</span> سالگی در بلوک لنگای تنکابن به تحصیل مقدماتی اشتغال داشت . و بعد برای تکمیل تحصیلات به تهران عزیمت نمود و نخست در مدرسه ٔ کاظمیه و مدرسه ٔ قنبر علیخان و سپس در مدرسه ٔ سپهسالارمشغول تحصیل گردید و اساتید وی در حکمت میرزا محمدرضا قمشه ای و میرزا ابوالحسن جلوه و آقاعلی حکیم و درهیئت و نجوم میرزا عبداﷲ بوده اند. تنکابنی بواسطه ٔ ذکاوت فطری و عشق و علاقه ٔ مفرطی که در تعلیم و تربیت داشت سرآمد اقران گردید و مرحوم جلوه که استاد تنکابنی بود به فضلش معترف و محصلین را به استفاده ٔ از او توصیه میفرمود. میرزامحمد طاهر علاوه بر احاطه به فلسفه و حکمت در فقه و اصول و نجوم و ادبیات و ریاضیات نیز تخصص داشت . طب قدیم را مطلع و قانون بوعلی سینا را چندین دوره تدریس نمود و حواشی ذی قیمتی بر قانون نوشته است که در کتابخانه ٔ مجلس شورای ملی موجود میباشد آن مرحوم خط خیلی خوب می نوشت کتب و رسائل زیادی بخط وی در دست است . سالیان دراز در مدرسه ٔ سپهسالارمدرس معقول بوده و در مدرسه ٔ علوم سیاسی نیز تدریس می کرد.<br />امور سیاسی : در دوره ٔاول مجلس شورای ملی که انتخابات طبقاتی بود مرحوم میرزا از طرف طبقه ٔ طلاب بنمایندگی در مجلس انتخاب گردید و در دوره ٔ سوم مجلس شورای ملی نیز از تهران به نمایندگی برگزیده شد در سال <span class=\"hlight\" dir=\"rtl\">١٢٩٤</span> هَ . ش . در جنگ بین المللی اول که مهاجرت آزادی خواهان پیش آمد وی نیز با آزادی خواهان مهاجرت کرده و مدتی را در اماکن مقدسه ٔ عتبات مشرف بود و چندی را در موصل بسر برده و در محاورات با علمای آنجا که اهل تسنن بودند خاطرات جالب توجهی از خود گذاشته و فوق العاده مورد تجلیل و احترام واقع گردید. در دوره ٔ چهارم که میرزا در مهاجرت بوداز طرف اهالی تهران به نمایندگی انتخاب ولی به مجلس نرفته است . مرحوم تنکابنی در اول کودتا از طرف آقا سید ضیاءالدین دستگیر و چندی زندانی بود و یک بار دیگر در اواخر سلطنت رضا شاه نیز زندانی شده سپس به کاشان تبعید گردید.<br />ورود بخدمت اداری : در تشکیلات جدید دادگستری از طرف مرحوم داور بخدمت دعوت شده و مدتی ریاست محاکم ابتدائی و استیناف را داشته و اخیراً هم مستشار دیوان عالی کشور و از زمره ٔ قضات عالی مقام بوده است . میرزا کتابخانه ای داشت که تعداد کتابهای آن زیادنبود ولی از حیث کیفیت مهم بوده که آن مرحوم در طول مدت زندگانی توانست بهترین و نفیس ترین نسخ را در علوم مختلف که نایاب بود جمع کند مقداری از این کتب راخود در حین مرض و کسالت به مجلس شورای ملی فروخت و بقیه را بازماندگانش برای ادای قروض وی به کتابخانه ٔمجلس فروختند. مرحوم میرزا محمدطاهر تنکابنی از فضلاو دانشمندان بنام و از مشاهیر علمای اسلام بشمار میرود. (از کتاب مازندران، شرح حال رجال معاصر، تألیف عباس شایان . ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢</span>) و کسروی درباره ٔ افتتاح نخستین دوره ٔ مجلس شورای ملی می نویسد: روز یکشنبه چهاردهم مهر (<span class=\"hlight\" dir=\"rtl\">١٨</span> شعبان ) مجلس گشاده خواستی بود، تا آن روز برگزیدن نمایندگان را بپایان رسانیدند کسان پائین برگزیده شدند: از شاهزادگان ... از علما و طلبه ها: آقامیرزا محسن (برادر صدرالعلما) حاجی شیخ علی نوری، میرزاطاهر تنکابنی . حاجی سیدنصراﷲ اخوی . (تاریخ مشروطه ٔ ایران ص <span class=\"hlight\" dir=\"rtl\">١٦٨</span>). بنابرین مرحوم تنکابنی از وکلای دوره ٔ اول مجلس شورا بشمار میرفته است . و در حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span> وکلائی را که روی زمین و یا روی صندلی نشسته اند شرح میدهد و مرحوم میرزا طاهر را هشتمین تن از بیست تن وکلائی که روی صندلی نشسته اند بشمار آورده است و در صفحه ٔ <span class=\"hlight\" dir=\"rtl\">٢٣</span> ذیل عنوان «تاجگذاری محمدعلی میرزا و بی پروائی او با مجلس » می نویسد همان روز در مجلس گفتگو بمیان آمد، و کسانی از نمایندگان گله کردند و برخی جمله های مغزداری نیز بمیان آمد. میرزا طاهر گفت : «سلطان سلطان ملت است باید از طرف ملت تاج گذارند و مجلس نماینده ٔ ملت است ». و رجوع به الذریعه ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٤١</span> و ص <span class=\"hlight\" dir=\"rtl\">٢٨٥</span> وحاشیه ٔ غزالی نامه ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span> شود.<br /></font></div>'),
(175472, 'طاهر جزری', '<span class=\"hlight\">طاهر جزری .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ج َ زَ ]</font></b> (اِخ ) شدادبن ابراهیم بن حسن، ابوالنجیب الملقب بالطاهر الجزری . ثعالبی در تتمةالیتیمة درباره ٔ او گوید: سالخورده است و دوران فرمانروائی سیف الدوله را درک کرده است و درباب وی گوید:<br />و حاجة قیل لی نبه لها عمراً<br />و نم فقلت علی قدتنبه لی <br />حسبی علیان ان ناب الزمان و ان <br />جاء المعاد بما فی القول و العمل <br />فلی علی بن عبداﷲ منتجع<br />ولی علی امیرالمؤمنین علی <br />و او راست درباره ٔ جوانی که بادب وی متادب شده بود:<br />هذا علی بالمشاکلة التی <br />ما بیننا لی مالک مستاثرُ<br />قالوا صدیقک قلت بل ولدی و قد<br />اعداه طبعی فهو مثلی شاعر<br />و درباره ٔ قوس قزح گوید:<br />الست تری الجو مستعبراً<br />یضاحکه برقه الخلب <br />و قد لاح من قزح قوسه <br />بعیداً و تحسبه یقرب <br />کطاقی عقیق و فیروزج <br />و بینهما آخر مذهب .<br /> <font color=\"Red\">(از تتمةالیتیمة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>).</font><br />و صاحب ریحانةالادب آرد: شدادبن ابراهیم بن حسن، مکنی به ابوالنجیب ملقب به طاهر جزری از شعرای عضدالدوله ٔ دیلمی بوده و وزیر مهلبی را مدیحه گفته و در سال <span class=\"hlight\" dir=\"rtl\">٤٠١</span> هَ . ق .وفات یافته و از او است :<br />ایاجیل التصوف شرجیل <br />لقدجئتم بامر مستحیل <br />افی القرآن قال لکم الهی <br />کلوا مثل البهائم و ارقصوا لی .<br />که در ذم صوفیه گفته است . (ریحانةالادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٠</span>). و رجوع به ابوالنجیب جزری شود.<br /></font></div>'),
(175473, 'طاهر خزاعی', '<span class=\"hlight\">طاهر خزاعی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ خ ُ]</font></b> (اِخ ) رجوع به طاهربن عبداﷲبن طاهربن حسین شود.<br /></font></div>'),
(175474, 'طاهر دبیر', '<span class=\"hlight\">طاهر دبیر.</span> <font color=\"DarkGreen\"><b>[ هَِ رِ دَ ]</font></b> (اِخ ) وی نخست صاحب برید و از خاصان مسعود غزنوی بود، و مکانتی بسزا داشت . چون مسعود بسلطنت رسید، و از ری بجانب خراسان روی نهاد، با مسعود به خراسان شد. و پیش از پیوستن بونصر مشکان به مسعود کارهای دیوان رسالت را میگزارد. مردی با نخوت و تکبّر بود، چنانکه بیهقی در تاریخ خود می نویسد: طاهر دبیر در دیوان رسالت با بادی و عظمتی سخت تمام می نشست، و در باطن امر بر آن بود که دیوان رسالت بالاستقلال بدو واگذار شود. روزی سلطان به احضار بونصر فرمان داد و پس از حضور سبب کناره جوئی او را از دیوان بپرسید، بونصر پیری و ضعف حال خویش را بر سبیل عذر اقامه کرد و گفت طاهر دبیر مردی کافی و بکار است من پیر شده ام و خواهم که باقی عمر به دعاگوئی گذرانم، سلطان در جواب بونصر گوید من ترا شناسم، طاهر را نشناسم، خود شخصاً در دیوان رسالت حاضر شو، پس بونصر فرمان برد. روزی چند بگذشت، امیر روی به بونصر کرد و گفت طاهر را گفته بودیم حدیث منشور اشراف با تو بگوید، آیا نسخت کرده آمده است ؟ گفت سوادی کرده ام، امروز بیاض کنند تا خداوند فرونگردد نبشته آید گفت نیک آمد، و طاهر نیک از جای بشد، و به دیوان بازآمدیم، بونصر قلم دیوان برداشت و نسخت کردن گرفت، خویشتن و مرا پیش بنشاند تا بیاض کردمی، و تا نمازپیشین در آن روز کار شد، و از پرده منشوری بیرون آمد که همه ٔ بزرگان و صدور اقرار کردند که در معنی اشراف، کس آنچنان ندیده است، و نخواهد دید... وزان منشور نسختها نبشته آمد، و طاهر به یکبارگی سپر بیفکند، و اندازه بتمامی بدانست . و پس از آن تا آنگاه که به وزارت عراق رفت با تاش فراش سپهسالار نیز، در حدیث کتابت سخن برننهاد. چندی نگذشت (در سال <span class=\"hlight\" dir=\"rtl\">٤٢٤</span> هَ . ق .) طاهر دبیر را به کدخدائی لشکر ری که به سپهسالاری تاش فراش اداره میشد مأمور ساختند. طاهر در این مأموریت هر چند مدتی وظیفه ٔ خویش ادا میکرد، اما در آخر امر روزگار خویش به عیش و عشرت گذراندی تا بحدی که در سال <span class=\"hlight\" dir=\"rtl\">٤٢٤</span> امیر بونصر را گفت که بوسهل حمدوی به ری خواهد رفت که از طاهر دبیر جز شراب خوردن و رعونت دیگر کاری برنیاید، در همین سال نیز از ری نامه های متواتررسید که طاهر دبیر کدخدای ری و آن نواحی، به لهو و نشاط و آداب آن مشغول میباشد. و بدان جای تهتک است که یک روز، در وقت گل طاهر گل افشانی کرد که هیچ ملک برآن گونه نکند، چنانکه میان برگ گل، دینار و درم بود که برانداختند، و تاش و همه ٔ مقدمان نزدیک وی بودند و همگان را دندان مزد داد، چون بازگشتند مستان همه، وی با غلامان و خاصگان خویش، خلع عذار کرد تا بدان جایگاه سخف رفت که فرمود تا مشربه های زرین و سیمین آوردند، و آن را در علاقه ٔ ابریشمین کشیدند، و بر میان بست چون کمری و تاجی از ورد بافته، با گل سوری بیاراسته، بر سرنهاد و پای کوفت، و ندیمان و غلامانش پای کوفتند با گرزنها بر سر، و پس دیگر روز این حدیث فاش شد، و همه ٔ مردم شهر، غریب و شهری این گفتند... امیرگفت من طاهر را شناخته بودم در رعونت و نابکاری، و محال بود وی را آنجا فرستادن ... بوسهل حمدوی شاید این کار را که هم شهم است و هم کافی و کاردان و شغلهای بزرگ کرده است ... بالاخره در پایان جمادی الاَّخره ٔ سال <span class=\"hlight\" dir=\"rtl\">٤٢٤</span> بوسهل عازم ری گشته، و پس از چندی طاهر دبیر و جمعی دیگر را از ری بیاوردند در یکشنبه <span class=\"hlight\" dir=\"rtl\">١٤</span> صفر سال <span class=\"hlight\" dir=\"rtl\">٤٢٦</span> امیر فرمود، بخیل حرس باز باید داشت، همگان را باز داشتند. نماز دیگر امیر بار داد و پس از بار، یکی از آنان را هزار تازیانه به عقابین بزدند، و پس از وی چهار تن را از اعمال و کسان وی بزدند، هر یکی را هزارگان . طاهر را هم فرمود که بباید زد، اما تلطفها وخواهشها کردند هر کسی، تا چوب را بخشید. و طاهر را به هندوستان بردند، و به قلعت گیری بازداشتند... و طاهر از چشم امیر بیفتاد. و آبش تیره شد، چنانکه نیز هیچ شغل نکرد، و در عطلت گذاشته شد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٠</span>، <span class=\"hlight\" dir=\"rtl\">٢١</span>، <span class=\"hlight\" dir=\"rtl\">٥١</span>، <span class=\"hlight\" dir=\"rtl\">٦٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٤٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٧٣</span>، <span class=\"hlight\" dir=\"rtl\">٣٩٣</span>، <span class=\"hlight\" dir=\"rtl\">٤٤٩</span>). و رجوع به تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>، <span class=\"hlight\" dir=\"rtl\">١٣٦</span>، <span class=\"hlight\" dir=\"rtl\">٨٧</span>، <span class=\"hlight\" dir=\"rtl\">٥٤</span>، <span class=\"hlight\" dir=\"rtl\">٥٩</span> شود.<br /></font></div>'),
(175475, 'طاهر دزفولی', '<span class=\"hlight\">طاهر دزفولی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ دِ ]</font></b> (اِخ ) سیدمحمد طاهربن سید اسماعیل موسوی دزفولی متوفی به سال <span class=\"hlight\" dir=\"rtl\">١٣١٤</span> هَ . ق . در نجف . وی از شاگردان علامه ٔ انصاری و شوهر دختر وی بوده و تمام تقریرات انصاری را که مشتمل بر یک دوره اصول و مباحث (خلل الصلاة والمواریث ) فقه و دیگر فصول آن است نوشته و گردآوری کرده است و کلیه ٔ تقریرات مزبور در نزد فرزند سیدمحمد طاهر، سیداحمد معروف به سبط الشیخ که در طهران درگذشته است موجود بوده است . (از الذریعه ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٧</span>).<br /></font></div>'),
(175476, 'طاهر دکنی', '<span class=\"hlight\">طاهر دکنی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ دَ ک َ ]</font></b> (اِخ ) معروف به شاه محمد طاهر فرزند سید مهدی دکنی متوفی به سال <span class=\"hlight\" dir=\"rtl\">٩٥٦</span> هَ . ق . او راست : تفسیر شاه محمد طاهر که حاشیه ای بر تفسیر بیضاوی است . (از الذریعه ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٠</span>).<br /></font></div>'),
(175477, 'طاهر ذوالیمینین', '<span class=\"hlight\">طاهر ذوالیمینین .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ذُل ْ ی َ ن َ]</font></b> (اِخ ) رجوع به طاهربن الحسین و ذوالیمینین شود.<br /></font></div>'),
(175478, 'طاهر رمزی', '<span class=\"hlight\">طاهر رمزی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ رَ ]</font></b> (اِخ ) رئیس معلمین دانشکده ٔ صنایع شهر خرطوم، در بخش «برادة». او راست : «دررالاستفادة، فی فن البرادة» این کتاب در مطبعة السلفیة (مصر) به سال <span class=\"hlight\" dir=\"rtl\">١٣٤١</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٩٢٣</span> م . به طبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢٥</span>).<br /></font></div>'),
(175479, 'طاهر سر', '<span class=\"hlight\">طاهر سر.</span> <font color=\"DarkGreen\"><b>[ هَِ رِ س ِرر ]</font></b> (ص مرکب، اِ مرکب ) کسی را نامند که طرفةالعینی از یاد حق جل ذکره غافل نباشد. (کشاف اصطلاحات الفنون ) آنکه به یک چشم بر هم زدن از خدا غافل نشود. (تعریفات جرجانی ).<br /></font></div>'),
(175480, 'طاهر سر و علانیه', '<span class=\"hlight\">طاهر سر و علانیه .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ س ِرْ رُ ع َ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (ص مرکب، اِ مرکب ) کسی باشد که در ایفای حقوق حق و خلق، برای آنکه مراعات هر دو جانب را کرده باشد، سعی و کوشش بلیغ مرعی دارد. کذا فی اصطلاحات الصوفیه . (کشاف اصطلاحات الفنون ). کسی که حقوق خدا و خلق را بطور کامل بگزارد و هر دو جانب را رعایت کند. (تعریفات جرجانی ).<br /></font></div>'),
(175481, 'طاهر سنجری', '<span class=\"hlight\">طاهر سنجری .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ س َ ج َ ]</font></b> (اِخ ) یکی از اطبای معروف اسلام است . و سه تألیف ذیل ازاوست : <span class=\"hlight\" dir=\"rtl\">١</span> - ایضاح منهاج محجةالعلاج <span class=\"hlight\" dir=\"rtl\">٢</span> - کتاب فی شرح البول و النبض . <span class=\"hlight\" dir=\"rtl\">٣</span> - تقسیم کتاب الفصول لابقراط. (از قاموس الاعلام ترکی ). و اسماعیل پاشا آرد: ابوالحسین سنجری طاهربن ابراهیم بن محمدبن طاهر سنجری وی به قاضی ابوالفضل محمدبن حمویه مراجعه میکرد... او راست : ایضاح منهاج محجةالعلاج در طب . تقسیم کتاب الفصول از ابقراط. شرح کتاب البول و النبص . (از اسماءالمؤلفین و آثارالمصنفین تألیف اسماعیل پاشای بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣٠</span>).<br /></font></div>'),
(175482, 'طاهر طالقانی', '<span class=\"hlight\">طاهر طالقانی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) از شعرای پارسی زبان و این شعر از اوست :<br />جز لاله دلی داغ نشد بهر هلاکم <br />نگریست بجز شمع کسی بر سر خاکم .<br /><font color=\"Red\">(قاموس الاعلام ترکی ).</font><br /></font></div>'),
(175483, 'طاهر عطار', '<span class=\"hlight\">طاهر عطار.</span><font color=\"DarkGreen\"><b>[ هَِ رِ ع َطْ ط ]</font></b> (اِخ ) رجوع به طاهر مشهدی شود.<br /></font></div>'),
(175484, 'طاهر علوی', '<span class=\"hlight\">طاهر علوی .</span> <font color=\"DarkGreen\"><b>[هَِ رِ ع َ ل َ ]</font></b> (اِخ ) معروف به میرزا طاهر علوی . درتذکره ٔ نصرآبادی شرح حال وی بدینسان آمده است : جوان قابل صالحی است . در تحصیل سعی کرد. شعرش این است :<br />امشبم چون شیشه ٔ می دل ز تنهائی پر است <br />همچو ساغر همدمی کو تا دلی خالی کنم .<br /><font color=\"Red\">(تذکره ٔ نصرآبادی ص <span class=\"hlight\" dir=\"rtl\">٣٧٤</span>).</font><br /></font></div>'),
(175485, 'طاهر علک', '<span class=\"hlight\">طاهر علک .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ع َ ]</font></b> (اِخ ) ممدوح سوزنی بوده است . رجوع به لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٥</span> شود.<br /></font></div>'),
(175486, 'طاهر غسانی', '<span class=\"hlight\">طاهر غسانی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ غ َس ْ سا ]</font></b> (اِخ ) حمداﷲ مستوفی ذیل احوال هرمزد آرد: وهرمزد هیچ فرزند نداشت . ارکان دولت شبستان هرمزد احتیاط کردند؛ مادر شاپور حامله بود و پادشاهی بدو دادند <font color=\"DarkGreen\"><b>[ و ]</font></b> بعد از چهل روز شاپور متولد شد، طفل را بر تخت بخوابانیدند و تاج بالای سر او بیاویختند. چون اوطفل بود ملک پرآشوب شد. از عرب طاهر غسانی لشکر کشید و طیسفون که تختگاه ساسانیان بود غارت کرد و نوشه خواهر هرمزد را بغارت برد و زن کرد و او دختری آورد ملکه نام . چون شاپور بحد مردی رسید به جنگ طاهر رفت . دختر نوشه با او متفق شد او را در قلعه راه داد طاهررا بگرفت و به کشت و ملکه را زن کرد. (تاریخ گزیده ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٧</span>). و رجوع به شاهنامه فردوسی و طایر شود.<br /></font></div>'),
(175487, 'طاهر غسانی ایلی', '<span class=\"hlight\">طاهر غسانی ایلی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِغ َس ْ سا ]</font></b> (اِخ ) رجوع به طاهربن خالدبن نزار شود.<br /></font></div>'),
(175488, 'طاهر قزوینی', '<span class=\"hlight\">طاهرقزوینی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ق َزْ ]</font></b> (اِخ ) معروف به «کاکاطاهرا» از اوباش، و باطناً مردی آدمی معاش، لکن به هجو مایل . طبعش خالی از متانتی، و اسمش خالی از غرابتی نیست . و لفظ کاکا معلوم نیست که اسم یا لقب یا تخلص باشد. بهر تقدیر این شعر از او دیده و نوشته شد:<br />وعده ٔ قتلم بفردا آن پری پیکر دهد<br />بازمیترسم که فردا وعده ٔ دیگر دهد.<br /> <font color=\"Red\">(آتشکده ٔ آذر ص <span class=\"hlight\" dir=\"rtl\">٢٢٨</span>).</font><br />رجوع به ترجمه ٔ تاریخ ادبیات ایران تألیف ادوارد برون ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٦</span> شود.<br /></font></div>'),
(175489, 'طاهر قزوینی', '<span class=\"hlight\">طاهر قزوینی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ق َزْ ]</font></b> (اِخ ) مؤلف تذکره ٔ حزین آرد: وحیدالزمان میرزا طاهر علیه الرحمه یگانه ٔ روزگار و از غایت اشتهار بی نیاز از تعریف است . موطن و مولدش دارالسلطنه ٔ قزوین . در بدایت حال، تحصیل مقدمات علمیه نموده، به فن سیاق و ممارست مهام دفتری و دیوانی ترغیب نموده سرآمد ارباب علم استیفا شد و در مهارت و اقتدار بانشاء و حسن تحریر بی نظیر آفاق گشت . صفای خطش رونق شکن بنفشه زار بناگوش دلبران و طوطی کلک شکرشکنش زنگ زدای آینه ٔ خاطر دانشوران . زلال طبعش رشک افزای کوثر و تسنیم و رای عقده گشایش شکنج غنچه ٔ دلها را فردوس نسیم . در شعر طرز تازه ای که مختار بعض متأخرین است، رواج یافته و رونق بخشیده ٔ او است . در اقسام نظم داد سخنوری داده و دیوانی که از شصت هزار بیت زیاده باشد بیادگار گذارده . تاریخی که در ضبط احوال وقایع صفویه نوشته، بر حسن تقریرش گواه و فصول منشآت بلیغه اش ثبت دفاتر و نیز دائرالسنه و افواه است . در بدایت اشتغال به امور دنیوی به دستور اعظم میرزا تقی پیوسته دخیل بعض مهمات او شد و به قدرشناسی او رتبه اش بلندی گرفت و بعد ازرحلت آن وزیر روشن ضمیر به اعتمادالدوله خلیفه ٔ سلطان توسل نمود. از غایت ظهور کمالات و مهارت در مهمات، منظور نظر عاطفت پادشاه عالی جاه عباس ثانی گشته، به منصب واقعه نویسی مرتبه ٔ تقرب و اختصاص یافت . در زمان سلطان سلیمان الصفوی بر حسب استقلال به وزارت اعظم رسیده، به آن شغل خطیر اشتغال داشت تا آنکه پس از انقضای چند سال از سلطنت شاه سلطان حسین خود از منصب مذکور مستعفی شده، دست از مهام دنیوی کشید. در مدةالعمر با این همه مشاغل، پیوسته از اکابر افاضل اقتناء معالم و معارف کرده، فواصل اوقات را صرف استفاده و افاده ٔ استکمال فضائل میساخت و انصاف آن است که در زمن دولت صفویه من جمیعالوجوه به استعداد و کمالات او کسی پای به میان مهام دنیوی نگذاشته و به ملازمت ملوک سر فرونیاورده . و اگر مذلت چاکری و لوث دنیاداری تشریف لیاقت و کمال او را شوخگن و آلوده نمیساخت، هرآینه در سلک افاضل نامدار منسلک و در ذیل آن والاگهران عالیمقدار در شمار آمدی . فقیر آن دبیر دانشور را چهار پنج نوبت بعد از استعفا از وزارت در منزل والد مرحوم دیده ام . عمرش قریب به صد سال رسیده بود که رحلت نمود. این ابیات از افکار آن سخن گزار حالیا بقلم آمد:<br />هر جا دلی است درپی چشم سیاه توست <br />عالم تمام زیر نگین نگاه توست <br />یارب چه آفتی تو که مجنون بروز وصل <br />رویش بسوی لیلی و چشمش براه توست .<br />چو لاله خامم و در خون برشته اند مرا<br />حدیث زشتم و نیکو نوشته اند مرا<br />چو لاله روزن گلخن بود گریبانم <br />ازین چه سود که در باغ کشته اند مرا.<br />تا نخوانی از درون حال درون تنگ را<br />شرم می گرداند اوراق کتاب رنگ را.<br />عاشق به درد چاره کند باز درد را<br />شویم به اشک چشم خود از چهره گرد را.<br />از هم چو باز شد مژه ام خون دیده ریخت <br />گفتی مگرکه بخیه ٔ زخمم ز هم گسیخت .<br />ما طائران شوقیم آرام نیست جان را<br />بر بال خود نهادیم بنیاد آشیان را.<br />ز یاران کینه هرگز در دل یاران نمی ماند<br />به روی آب جای قطره ٔ باران نمی ماند.<br />چنان کز سنگ و آهن آتش سوزان شود پیدا<br />دو عالم را اگر برهم زنی جانان شود پیدا.<br />ره مده در خط مشکین شانه ٔ شمشاد را<br />نیست حاجت حک و اصلاحی خط استاد را<br />چرخ را آرامگاه عافیت پنداشتم <br />آشیان کردم تصورخانه ٔ صیاد را.<br />الهی جلوه ده در دیده اش حیرانی ما را<br />به گوشش آشنا کن ناله ٔ پنهانی ما را<br />ز بیقدری بوصل او گرم لایق نمیدانی <br />بخاک آستانش روی ده پیشانی ما را.<br />اگر نالم ز زخم خار در پا رفته نامردم <br />ولی در زیر پای من شکست این میکند دردم .<br />چه غم گر تلخ شد چون زهر بر لب جان شیرینم <br />ولیکن چون به کام دشمنانم میکشد اینم .<br />افسوس می خورم ز غم روزگار خویش <br />بر آسیای دست نهادم مدار خویش .<br />خوردندباز با چشم از رشک مردمانم <br />با آنکه توتیا کرد درد تو استخوانم .<br />هرچند که خود گم شده ام راه نمایم <br />در قافله ٔ عشق تو آواز درایم .<br />نمیدانم چرا آهو نگاه من رمید از من <br />چو من هرگز نبودم در میان یارب چه دید از من <br />نه شمعم هر زمان کردی غلط پروانه در محفل <br />که سرافکنده بودم پیش و آتش می چکید از من .<br />خوشا حال جوانمردی که گیرد دامن صحرا<br />به آب زندگی چون خضر شوید دست از دنیا.<br />زبان از دل در اقلیم سخن طرفی نمی بندد<br />نگردد پخته ماهی هرگزاز جوشیدن دریا.<br />درروز عید وصلش منهم برای زینت <br />پوشیده ام بصد رنگ حال خراب خود را.<br />چون شاخ که از میوه ٔ بسیار شود خم <br />از بار هنر بر دل خود نیز گرانم .<br />به همواری توان خاموش کردن هرزه گویان را<br />صدا گردد بیابان مرگ از همواری صحرا.<br />نیست جان پاک را بعد از فنای تن زوال <br />از شکست کوزه در دریا چه نقصان آب را.<br />مرا غیر از ندامت از عبادت بهره ای نبود<br />ز خائیدن کنم مسواک انگشت ندامت را.<br />ای راز دل چه آمده ای بر سر زبان <br />بیرون نمیرود ره از این کوچه بازگرد.<br />بقدر شق قلم گر ز هم جدا مانیم <br />بدست غیر فتدراه یک کتاب سخن .<br />همچو نرگس بچمن ز آمدن فصل بهار<br />چشم وامی شود از مقدم مهمان مارا.<br />مانند شان موم که ریزند شمع از او<br />شد خانه ها خراب که سروت نهال شد.<br />ز بار منت احسان دریا ابر نیسانی <br />کند افغان چو مجروحی که زخمش آب بردارد.<br /> <font color=\"Red\">(از تذکره ٔ حزین صص <span class=\"hlight\" dir=\"rtl\">٤٦</span> - <span class=\"hlight\" dir=\"rtl\">٥١</span>).</font><br />و صاحب قاموس الاعلام آرد: دیوانی محتوی بر <span class=\"hlight\" dir=\"rtl\">٦٠</span> هزار بیت و یک مجموعه منشآت دارد.<br /></font></div>'),
(175490, 'طاهر قزوینی', '<span class=\"hlight\">طاهر قزوینی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ق َزْ ]</font></b> (اِخ ) طاهربن حاتم بن ماهویه ٔ قزوینی . او راست : کتاب الحدیث که نجاشی به چهار واسطه از آن روایت کرده است . (الذریعه ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٠</span>).<br /></font></div>'),
(175491, 'طاهر محتسب', '<span class=\"hlight\">طاهر محتسب .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ م ُ ت َ س ِ ]</font></b> (اِخ ) مافروخی نام وی را در ذیل متقدمان از استادان علم نحو واعراب و تصریف و لغت عرب و فحول شاعران عربی و پارسی و اهل توقیع و انشا آورده است . رجوع به ترجمه ٔ محاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span> و تاریخ اصفهان مافروخی ص <span class=\"hlight\" dir=\"rtl\">٣٢</span> شود.<br /></font></div>'),
(175492, 'طاهر مرعشی', '<span class=\"hlight\">طاهر مرعشی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ م َ ع َ ]</font></b> (اِخ ) سیدمحمد طاهربن سیدعلی بن سیدعلاءالدین بن محمد مرعشی . از شاگردان علامه ٔ مجلسی بوده و نواده ٔ او سیدشهاب الدین که سیدمحمدطاهر یکی از اجداد مادری وی بوده بدین امر اشاره کرده است . او راست : حواشی بر کتب طبی، مانند شفاو قانون ابن سینا و غیره . (از الذریعه ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span>).<br /></font></div>'),
(175493, 'طاهر مروزی', '<span class=\"hlight\">طاهر مروزی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ م َرْ وَ ]</font></b> (اِخ ) ملقب به شرف الزمان . طبیب دربار ملکشاه سلجوقی . او راست : طبایعالحیوان که در ربع اول قرن دوازدهم میلادی این کتاب را در علوم طبیعی تألیف کرده است و هم او را کتابی است در جغرافیای عالم که اخبار چین، ترک و هند را درآن آورده است و مینورسکی در سال <span class=\"hlight\" dir=\"rtl\">١٩٤٢</span> م . کتاب مزبوررا به انگلیسی ترجمه کرده است . رجوع به نشریه ٔ دانشکده ٔ ادبیات تبریز شماره ٔ <span class=\"hlight\" dir=\"rtl\">٧</span> سال <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٣٠</span> - <span class=\"hlight\" dir=\"rtl\">٥٣</span> شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175494, 'طاهر مستوفی', '<span class=\"hlight\">طاهر مستوفی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ م ُ ت َ ]</font></b> (اِخ ) رئیس دیوان استیفاء دربار غزنوی بود. و بعد از عزل احمدبن حسن میمندی، بوزارت نامزد شد، اما سلطان محمود گفت : او از همه شایسته تر است، اما او بسته ٔ کار است و من شتاب زده، در خشم شوم، دست و پای او از کار بشود. (از تاریخ بیهقی چ فیاض صص <span class=\"hlight\" dir=\"rtl\">٣٦٦</span> - <span class=\"hlight\" dir=\"rtl\">٣٦٧</span>). رجوع به ص <span class=\"hlight\" dir=\"rtl\">٩٤</span>، <span class=\"hlight\" dir=\"rtl\">١٣٠</span>، <span class=\"hlight\" dir=\"rtl\">١٣١</span> و <span class=\"hlight\" dir=\"rtl\">٦٦٤</span>همان چاپ شود. طاهر وزارت مودودبن مسعود غزنوی یافت، اما مدت وزارت او بواسطه ٔ ضعف رای و سوء تدبیر بیش از دو ماه بطول نینجامید، و استعفا کرد (در حدود سال <span class=\"hlight\" dir=\"rtl\">٤٤٠</span> هَ . ق .). (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩٤</span>). مدتی منصب استیفای دیوان سلطان محمود به وی متعلق بود، وسلطان مودود بعد از اخذ احمدبن عبدالصمد، امر وزارت را به وی تفویض فرمود، و طاهر بواسطه ٔ ضعف رأی و عجز نفس و سوء تدبیر پس از آنکه مدت دو ماه بدان امر اشتغال داشت استعفا کرده، باقی ایام حیات در کنج عزلت و فراغت روزگار گذرانید. (دستور الوزراء ص <span class=\"hlight\" dir=\"rtl\">١٤٤</span>).<br /></font></div>'),
(175495, 'طاهر مشهدی', '<span class=\"hlight\">طاهر مشهدی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ م َ هََ ]</font></b> (اِخ ) میرزا محمدطاهر مشهور به وزیرخان برادر میرزا محمدرفیعبن محمد مشهدی، متخلص به باذل متوفی به سال <span class=\"hlight\" dir=\"rtl\">١١٢٤</span> یا <span class=\"hlight\" dir=\"rtl\">١١٢٣</span> هَ . ق . رجوع به الذریعه ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٩١</span> شود.<br /></font></div>'),
(175496, 'طاهر مشهدی', '<span class=\"hlight\">طاهر مشهدی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِم َ هََ ]</font></b> (اِخ ) در مشهد مقدس رضوی به عطاری مشغول بوده، گویند در عهد شباب به عالم بقا رفت . از اوست :<br />از فریب باغبان غافل مباش ای عندلیب <br />پیش از این من هم درین باغ آشیانی داشتم .<br /> <font color=\"Red\">(آتشکده ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>) (قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">٤</span>).</font><br />صاحب تذکره ٔ نصرآبادی آرد: ...از شاگردان امتی تربتی است ... از اشعارش اوست :<br />ز بس دورنگی مردم به یکدگر دیدم <br />تسلیم ز شب و روز خود که یکرنگ است .<br />از بس فریب مغلطه خوردیم از سراب <br />لب تشنه در کناره ٔ زمزم گداختیم .<br />ز دیده ام همه عالم پرآب و من لب خشک <br />فرات عالمم و کربلای خویشتنم ...<br />سالها خاکستر مجنون و خاک کوهکن <br />جمع میکردند تا رنگ دل ما ریختند.<br />تمام عمر صرف گریه کردم وز نم اشکی <br />نه گل در باغ و نه خاری به هامون پرورش دادم .<br /><font color=\"Red\">(تذکره ٔ نصرآبادی ص <span class=\"hlight\" dir=\"rtl\">٣٠٥</span>).</font><br /></font></div>'),
(175497, 'طاهر مقدسی', '<span class=\"hlight\">طاهر مقدسی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ م َ دِ <span class=\"hlight\" dir=\"rtl\">/</span> م ُ ق َدْ دَ ]</font></b> (اِخ ) از طبقه ٔ ثالثه است از بزرگان مشایخ شام، و قدمای ایشان . ذوالنون مصری را دیده، و با یحیی جلا صحبت داشته، عالم بوده . گویند شبلی وی را حبرالشام خواندی . طاهر مقدسی گوید: ذوالنون مرا گفت : العلم فی ذات الحق جهل، والکلام فی حقیقة المعرفة حیرة، و الاشارة عن المشیر شرک، شیخ الاسلام گفت که سخن در ذات حق جهل است که هیچکس را در ذات اﷲ سخن نیست، وروا نبود که گوید مگر آنکه خدای تعالی را و پیغمبر وی گفت وی را، و گفت : آن دانستنی نیست و جز تصدیق و تسلیم در آن روی نیست و سخن در معرفت و حقیقت حیرت است که او خود، خود را شناسد بحق الحقیقة، دیگر همه عاجزند و متحیر، و او عجز رهی را از معرفت خود بفضل خودمعرفت می انگارد. و مصطفی صلی اﷲ علیه و آله و سلم میگوید در ثناء و دعاء خداوند: لاابلغ مدحتک و لااحصی ثناء علیک، انت کما اثنیت علی نفسک . حق تعالی میگوید: ولایحیطون به علماً. از وی همین ذاتی که اوست خدای یگانه ٔ بی همتا و اشارت از مشیر شرک، شرک است، یعنی شرک خفی که اشارت را اشارت کننده ای باید داد و به دوگانگی درنیاید. هست بحقیقت اوست، و دیگر همه بهانه، و وی در بود و هستی یگانه . الا کل شی ٔ ما خلااﷲ باطل . طاهرمقدسی گوید: اگر مردمان نور عارف ببینند در آن بسوزند، و اگر عارف نور وجود ببیند در آن بسوزد، و هم وی گوید: حدالمعرفة التجرد من النفوس و تدبیرها فیها یحل و یصغر (کذا؟). (نفحات الانس ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span> چ توحیدی پور).<br /></font></div>'),
(175498, 'طاهر نقاش', '<span class=\"hlight\">طاهر نقاش .</span><font color=\"DarkGreen\"><b>[ هَِ رِ ن َق ْ قا ]</font></b> (اِخ ) رجوع به طاهر کاشی شود.<br /></font></div>'),
(175499, 'طاهر هراتی', '<span class=\"hlight\">طاهر هراتی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ هََ ]</font></b> (اِخ ) اصل او از هرات و نشو و نمایش در قندهار بوده، این شعر از اوست :<br />خوش آنکه بپرسی دل دیوانه ٔ ما را<br />روشن کنی از شمع رُخت خانه ٔ ما را.<br /><font color=\"Red\">(قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">٤</span>).</font><br /></font></div>'),
(175500, 'طاهر هروی', '<span class=\"hlight\">طاهر هروی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ رَ]</font></b> (اِخ ) ابوالقاسم طاهربن احمد هروی . صاحب برید نیشابور بود از ادب بهره ٔ وافر داشت و نامه های نیکو می نوشت و اشعار ملیح میسرود. در فضل از همگنان خود یکتابود این اشعار را خود وی برای من انشاد کرده است :<br />اعیذ علاه ان یکون ابتداؤه <br />زیادة علیاه بنقص صدیقه <br />اذا انتهز الاحرار للجود فرصة<br />فللمنع و التعویق ینتهز الفرص <br />و ان ذکرت بیض الایادی فانما<br />یدلک لاتبیض الا من البرص <br />نمونه ای از رسائل او:<br />من شکر البحر علی التدفق والشمس علی التالق و المسک علی التارج و الصبح علی التبلج فقد عاد بتکلف غیر مربح و سعی غیر منجح . (از تتمة الیتیمة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤</span>).<br /></font></div>'),
(175501, 'طاهر همدانی', '<span class=\"hlight\">طاهر همدانی .</span> <font color=\"DarkGreen\"><b>[هَِ رِ هََ م َ ]</font></b> (اِخ ) مشهور به باباطاهر عریان . ازخاک پاک همدان بوده . او در آن ولایت به دیوانگی شهرت نموده بلی اوست دیوانه که دیوانه نشد. اغلب اوقات وایام در بیغوله و غارش مقام . گویند چنان آتشی در دل آن دیوانه ٔ فرزانه برافروخته و بنیاد صبر و طاقت اورا سوخته بودند که با آنکه برودت هوای آن بلد مشهوراست در فصل زمستان در کوه الوند میان برف عور نشسته، و از گرمی شکایت میکرد و بقدر بیست ذرع اطراف وی برف گداخته و آب میگردید. گویند با عین القضاة و خواجه نصیر معاصر بوده است . و محیی الدین لاری صاحب مرآةالادوار این حکایت را به سیدنعمةاﷲ کرمانی نسبت کرده و به نام او نوشته که در کوهستان خراسان در هرات، امرای شاهرخ این معنی را از او مشاهده کردند. معاصر بودن او با عین القضاة و خواجه نصیرالدین طوسی خطاست که اودر چهارصد و ده وفات یافته، و اینان بعد از او بوده اند. غرض مجذوبی است کامل و مجنونی است عاقل، عاشقی است مجرد، و عارفی مُوحد.سخنانش دوبیتی و بلفظ رازی که در آن زمان اهالی ری و دینور بدان تلفظ میکردند واقع و معروف و بسیار اثرناک است . غزلی بنام او مشهور است . بعضی از اشعار آنرا در دیوان ملا محمد صوفی مازندرانی مشهور به اصفهانی دیدم . از رباعیات آن جناب، چند رباعی قلمی میشود:<br />وِیته سر در بیابانم شو و روج <br />سرشک از دیده پالانم شو و روج <br />نه تَو دیرُم نه جایم میکرو درد<br />همی دانم که نالانم شو و روج <br />به صحرا بنگرم صحرا ته وینم <br />به دریا بنگرم دریا ته وینم <br />چه در شهر و چه در کوه و چه در دشت <br />به هر جا بنگرم آنجا ته وینم .<br /> <font color=\"Red\">(ریاض العارفین ).</font><br />مسلک درویشی و فروتنی او که شیوه ٔ عارفان است، سبب شد که وی گوشه گیر و گمنام زیسته، تفصیلی از زندگانی خود باقی نگذاشت . فقطدر بعض کتب صوفیه ذکرهائی از مقامات معنوی، و مسلک ریاضت و درویشی، و صفت تقوی و استغنای او شده است . آنچه از سوانح زندگانی وی معلوم است، ملاقاتی است که گویا میان او و طغرل، اولین شاه سلجوقی، در حدود سال <span class=\"hlight\" dir=\"rtl\">٤٤٧</span> هَ . ق . در همدان اتفاق افتاده، و از این خبر به دست می آید که دوره ٔ شهرت شیخ، اواسط قرن پنجم هجری و ظاهراً تولدش اواخر قرن چهارم هجری بوده است . باباطاهر از سخنگویان صاحبدل و دردمند صوفیه بوده و نغمه هائی که شاهد سوز درونی اوست سروده و رسالاتی به عربی و فارسی تألیف نموده است . از آن جمله مجموعه ٔ کلمات قصاری است بعربی که عقاید تصوف را در علم و معرفت، ذکر و عبادت و وجد و محبت در جمله های کوتاه و مؤثری بیان میکند. عمده ٔ شهرت باباطاهر در ایران بواسطه ٔرباعیات شیرین و مؤثر عارفانه ٔ اوست . از خصوصیات لفظی این رباعیات آنکه با وزن معمولی رباعی فرق دارد، و نیز در لغتی شبیه به لغت لری سروده شده، و از این لحاظ آنها را در کتب قدیم «فهلویات » نام داده اند. در تمام این رباعیهای ساده و مؤثر، شاعر یاد از پریشانی، تنهائی، ناچیزی و بی چیزی خود کرده، از هجران شکایت نموده، و حس اشتیاق معنوی خود را جلوه داده است .باباطاهر در همدان دار فانی را وداع گفته و در همان شهر مدفون است . (تاریخ ادبیات شفق ). و راوندی آرد: شنیدم که چون سلطان طغرل بیک به همدان آمد، از اولیاءسه پیر بودند: باباطاهر، باباجعفر، و شیخ حمشاد. کوهکی است بر در همدان آنرا خضر خوانند، بر آنجا ایستاده بودند، نظر سلطان بر ایشان آمد، کوکبه ٔ لشکر بداشت و پیاده شد و با وزیر ابونصر اسکندری پیش ایشان آمد و دستهاشان ببوسید. باباطاهر پاره ای شیفته گونه بودی، او را گفت : ای ترک ! با خلق خدا چه خواهی کرد؟ گفت : آنچه تو فرمائی، بابا گفت : آن کن که خدا میفرماید:(اًِن َّ اﷲ یأمر بالعدل و الاحسان ) سلطان بگریست و گفت چنین کنم . بابا دستش بستد، و گفت از من پذیرفتی، سلطان گفت : آری . بابا سرابریقی شکسته که سالها از آن وضو کرده بود در انگشت داشت بیرون کرد، و در انگشت سلطان کرد، و گفت : مملکت عالم چنین در دست تو کردم، بر عدل باش . سلطان پیوسته آن در میان تعویذها داشتی و چون مصافی پیش آمدی آن در انگشت کردی . (مقدمه ٔ دیوان باباطاهر چ محمود عرفان از راحةالصدور). هدایت آرد: نام شریفش باباطاهر است، از علما، حکما و عرفای عهد بوده است، و صاحب کرامات و مقامات عالیه و اینکه بعضی او را معاصر سلاطین سلجوقیه دانسته اند خطا است . وی از قدمای مشایخ است معاصر دیالمه بوده و در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٤١٠</span> هَ . ق . بوده، قبل از عنصری و فردوسی و امثال و اقران ایشان رحلت نموده، رباعیات بدیع، و مضامین رفیع بزبان قدیم دارند (ظ:دارد). گویند رسالات از آن جناب مانده و محققان بر آن شروح نوشته اند. بعضی از دوبیتی های وی در این کتاب ثبت میشود:<br />ز دل نقش جمالت درنشی یار<br />خیال خط و خالت درنشی یار<br />مژه کردم به گرد دیده پرچین <br />که خونابه خیالت درنشی یار.<br />دلی دارم که بهبودش نمیبو<br />نصیحت میکرم سودش نمیبو<br />به بادش میدهم نِش میبره باد<br />بر آذر مینهم دودش نمیبو.<br />نسیمی کز بن آن کاکل آیو<br />مرا خوشتر ز بوی سنبل آیو<br />چو شو گیرم خیالت را در آغوش <br />سحر از بسترم بوی گل آیو.<br />دلم از درد هجرانت غمینه <br />سرینم خشت و بالینم زمینه <br />گناهم اینکه من ته دوست دیرم <br />هر آنکت دوست دارد حالش اینه .<br />هزارت دل بغارت برته ای ویش <br />هزارانت جگر خون کرته ای ویش <br />هزاران داغ ویش از سینم اشمرت <br />همی نشمرته از اشمرته ای ویش .<br />بنالیدن دلم مانند نی بی <br />مدامم درد هجرانت ز پی بی <br />مرا سوزت گدازه تا قیامت <br />خدا دانه قیامت تا بکی بی .<br />خورآئین چهره ات افروته تر بی <br />دلم از تیر عشقت دوته تر بی <br />ز چه خال رخت ذانی سیاهن <br />هر آن نزدیک خور بی سوته تر بی .<br />دلی نازک بسان شیشه ام بی <br />اگر آهی کشم اندیشه ام بی <br />سرشکم گر بود خونین عجب نی <br />مو آن دارم که در خون ریشه ام بی .<br />نگارینا دل و جانم ته دیری <br />همه پیدا و پنهانم ته دیری <br />نمیدانم که این درد ازکه دیرم <br />همی ذونم که درمانم ته دیری .<br />کشیمان گر بزاری اج که ترسی ؟<br />برانی گربخواری اج که ترسی ؟<br />مو با این نیمه دل از کس نترسم <br />جهانی دل ته دیری اج که ترسی ؟<br /><font color=\"Red\">(از مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٠</span>).</font><br /></font></div>'),
(175502, 'طاهر و نجس', '<span class=\"hlight\">طاهر و نجس .</span> <font color=\"DarkGreen\"><b>[ هَِ رُ <span class=\"hlight\" dir=\"rtl\">/</span> وَ ن َ ج ِ ]</font></b> (ترکیب عطفی، اِ مرکب ) این لفظ برای اشخاص و حیوانات وسایر اشیای مستعمل است، و هر آن کس که قصدش اشتراک دخول در کنیسه ٔ یهودیه میبود، میبایست بر وفق شریعت موسوی مختون گشته تطهیر نماید. (قاموس کتاب مقدس ).<br /></font></div>'),
(175503, 'طاهر وحید', '<span class=\"hlight\">طاهر وحید.</span> <font color=\"DarkGreen\"><b>[ هَِ رِ وَ ]</font></b> (اِخ ) محمدطاهر وحید. او راست : مجموعه ای در «توحید» که صاحب الذریعه آنرا در کتابخانه ٔ سیدنصراﷲ تقوی دیده است و مینویسد: ظاهراً وی بجز میرزا طاهر وحید قزوینی است که نصرآبادی در ص <span class=\"hlight\" dir=\"rtl\">١٧</span> تذکره ٔ خود از وی نامبرده و ما در ص <span class=\"hlight\" dir=\"rtl\">٣٦</span> بدان اشاره کردیم . (از الذریعه ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٨٠</span>).<br /></font></div>'),
(175504, 'طاهر وحید', '<span class=\"hlight\">طاهر وحید.</span> <font color=\"DarkGreen\"><b>[ هَِ رِوَ ]</font></b> (اِخ ) میرزا طاهربن حسین خان قزوینی . رجوع به طاهر قزوینی و ترجمه ٔ تاریخ ادبیات ایران تألیف ادوارد براون ص <span class=\"hlight\" dir=\"rtl\">١٨٦</span>، تذکره ٔ نصرآبادی ص <span class=\"hlight\" dir=\"rtl\">١٧</span> و وحید شود.<br /></font></div>'),
(175505, 'طاهر کاشانی', '<span class=\"hlight\">طاهر کاشانی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ]</font></b> (اِخ ) معروف به شاه طاهر کاشانی فرزند رضی الدین اسماعیلی . حسین شاگرد محقق خضری مؤلف کتاب (الحیدریة) فی شرح الجعفریة الکرکیة که آنرا بسال <span class=\"hlight\" dir=\"rtl\">٩٥٠</span> هَ . ق . تألیف کرده است . (الذریعه ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٥</span>). رجوع به ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠٦</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span>ص <span class=\"hlight\" dir=\"rtl\">٦</span> و ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥١٣</span> و ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢</span> و <span class=\"hlight\" dir=\"rtl\">١٤٢</span> همان کتاب شود.<br /></font></div>'),
(175506, 'طاهر کاشی', '<span class=\"hlight\">طاهر کاشی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ]</font></b> (اِخ ) از وزرای سلطان ابوالمظفر رکن الدین ملک ارسلان بن طغرل بن محمدبن ملکشاه بوده است . رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢٠</span> شود.<br /></font></div>'),
(175507, 'طاهر کاشی', '<span class=\"hlight\">طاهر کاشی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ]</font></b> (اِخ ) معروف به محمدطاهر نقاش متخلص به کاشی . صاحب تذکره ٔ نصرآبادی آرد: خامه ٔ فکرش چهره ٔ عروسان معنی گشاید و دیبای زربفت سخن را بی تأمل نقش بندی نماید. طبعش نهایت لطف و دقت را دارد به امر نقش بندی در کاشان مشغول است، اگرچه فقیر بصحبت او نرسیدم اما گاهی مکالمه ٔ روحانی واقع میشود. این اشعار از اوست :<br />خلق نکوبخود در جنت گشادن است <br />تعظیم خلق کاسه ٔ همسایه دادن است <br />دانی که چیست بخیه ٔ زخم زبان خلق <br />دندان ز درد بر سر دندان نهادن است <br />بگشای لب که آمد و رفت نفس ترا<br />هر دم بعمر گرم عنان کوچ دادن است <br />رم خورده ٔ تو الفت کس کی کند قبول <br />دل برگرفتن از تو دل از دست دادن است .<br /> <font color=\"Red\"># # #</font><br />گفتم از قطع نظر کوته کنم سودای زلف <br />چشم حسرت حلقه ٔ دیگر به این زنجیر بست .<br />شکن طرف کلاهش بنظرها نقاش <br />دامن خیمه ٔ لیلی است که بالا زده اند.<br />بی بصیرت را عنان در دست نفس سرکش است <br />میبرد هر جا که میخواهدعصاکش کور را.<br />از طپیدنهای دل رو میدهد افغان مرا<br />گر بود چون زنگ دندان بر سر دندان مرا.<br />قامت خم گشته پشتیبان کنج عزلت است <br />این کمان چون چله میگردد کمند وحدت است .<br />چون قدت خم گشت از تیر اجل غافل مباش <br />کز برای گوشه گیری این کمان پیچیده است .<br />سر رشته ٔ وجود و عدم بسته ٔ منست <br />من در میانه همچو گره هیچکاره ام .<br />دل چو بگشاید بخاطر صد گره پیدا شود<br />عقده ٔ سیماب افزونتر شود چون واشود.<br /><font color=\"Red\">(تذکره ٔ نصرآبادی ص <span class=\"hlight\" dir=\"rtl\">٣٧٠</span>).</font><br /></font></div>'),
(175508, 'طاهر کرخی', '<span class=\"hlight\">طاهر کرخی .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ک َ ]</font></b> (اِخ ) در تاریخ بیهقی نام وی بدین سان آمده است : و بیاید در تاریخ پس از این بابی سخت مشبع آنچه رفت در سالاری تاش و کدخدائی دو عمید بوسهل حمدوی و طاهر کرخی که در آن بسیار سخن است تا دانسته آید. (تاریخ بیهقی چ فیاض ص <span class=\"hlight\" dir=\"rtl\">٢٨٢</span>). و در فهرست اعلام همین چاپ بین الهلالین نوشته اند: (شاید طاهر دبیر). رجوع به طاهر دبیر شود.<br /></font></div>'),
(175509, 'طاهر کنده', '<span class=\"hlight\">طاهر کنده .</span> <font color=\"DarkGreen\"><b>[ هَِ رِ ک َ دَ]</font></b> (اِخ ) وکیل بلگاتگین . بهمین صورت نام طاهری در فهرست اعلام تاریخ بیهقی چ فیاض ص <span class=\"hlight\" dir=\"rtl\">٢٤١</span> آمده و عبارت متن تاریخ بیهقی چنین است : حاجب بزرگ بلگاتگین ایشان (کوتوال ترمذ و سرهنگان ) را به نیم ترک پیش خویش بنشاند و طاهر کنده (؟) وکیل خویش را پیغام داد سوی بوسهل زوزنی عارض که شراب میخورد با سلطان تا بازنماید.<br /></font></div>'),
(175510, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) موضعی است در غربی دستجرد، از نواحی شمالی باطلاق نمکزار.<br /></font></div>'),
(175511, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) قریه ای است از توابع کنگاور، در کنار جاده ٔ کنگاور و جوکار واقع میان کنگاور و گودین در <span class=\"hlight\" dir=\"rtl\">٢٥٠٠</span> گزی کنگاور.و در فرهنگ جغرافیائی ایران آمده است : دهی است از دهستان کنگاور بخش کنگاور شهرستان کرمانشاهان در هشت هزارگزی خاور کنگاور. کنار راه شوسه ٔ کرمانشاه به تویسرکان . دشت و سرد و معتدل . با <span class=\"hlight\" dir=\"rtl\">٤٦٠</span> تن سکنه . آب آن از رود خرم رود و سیاه گر. محصول آنجا غلات آبی و دیمی واشجار و انگور و تریاک و صیفی . شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(175512, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان خانکوک بخش حومه ٔ شهرستان فردوس در <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی شمال باختری بشرویه و<span class=\"hlight\" dir=\"rtl\">١٤</span>هزارگزی شمال باختری شوسه ٔ عمومی فردوس به طبس . جلگه، گرمسیر. با <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و پنبه و ارزن . شغل اهالی زراعت و مالداری و راه آن مالرو است . اهالی برای آب مشروبی آب انبارهائی درست کرده اند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175513, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان درزآب بخش حومه ٔ شهرستان مشهد. در <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی شمال باختری مشهد و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی خاور راه مشهد به ارداک . جلگه، معتدل . با <span class=\"hlight\" dir=\"rtl\">٤٤</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و چغندر و عدس . شغل اهالی زراعت و مالداری و راه آن اتوموبیل رو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175514, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان سنگان بخش رشخوار شهرستان تربت حیدریه در <span class=\"hlight\" dir=\"rtl\">٢٧</span>هزارگزی جنوب باختری رشخوار سر راه مالرو عمومی جنگل به رشخوار. جلگه، گرمسیر. با <span class=\"hlight\" dir=\"rtl\">٧٥</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و پنبه . شغل اهالی زراعت و گله داری و کرباس بافی و قالیچه بافی است . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175515, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان پائین ولایت بخش حومه ٔ شهرستان تربت حیدریه . در <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی خاور تربت حیدریه و <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی جنوب شوسه ٔ عمومی دولت آباد به تربت حیدریه . جلگه و معتدل . با <span class=\"hlight\" dir=\"rtl\">٢٠٤</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و چغندر و پنبه و تریاک . شغل اهالی زراعت و گله داری و کرباس بافی و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175516, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان نهارجانات بخش حومه ٔ شهرستان بیرجند، در <span class=\"hlight\" dir=\"rtl\">٣٣</span>هزارگزی جنوب خاوری بیرجند. دامنه و معتدل . با <span class=\"hlight\" dir=\"rtl\">٨</span> تن سکنه . آب آن از قنات . محصول آن غلات . شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175517, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دیهی است از دیهات بین راه سرخس و مرو. (حبیب السیر) و رجوع به ترجمه ٔ تاریخ ادبیات ایران تألیف براون ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢</span> شود.<br /></font></div>'),
(175518, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان کمازان شهرستان ملایر در <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی جنوب خاوری شهر ملایر. کنار راه شوسه ٔ ملایر به اراک . جلگه و سردسیر. با <span class=\"hlight\" dir=\"rtl\">٤٩</span> تن سکنه . آب آن از قنات . محصول آن غلات و صیفی . شغل اهالی زراعت و صنایع دستی، قالی بافی و راه آن اتومبیل رو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(175519, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است جزء دهستان حومه ٔ بخش مرکزی شهرستان زنجان . در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی شمال زنجان . کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٣٩٥</span> تن سکنه . آب آن از قنات و چشمه . محصول آنجا غلات . شغل اهالی زراعت و مکاری و کرباس بافی است . راه آن مالرو است . و در فصل خشکی اتومبیل میرود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(175520, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ]</font></b> (اِخ ) دهی است جزء دهستان بهنام عرب بخش ورامین شهرستان تهران . در <span class=\"hlight\" dir=\"rtl\">١٣</span>هزارگزی جنوب خاوری ورامین و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی راه آهن و شوسه ٔ ورامین به سمنان . جلگه و معتدل و مالاریائی . با <span class=\"hlight\" dir=\"rtl\">٧٦</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و صیفی کاری و چغندرقند. شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(175521, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است جزء دهستان سیاه رود بخش افجه ٔ شهرستان تهران، در <span class=\"hlight\" dir=\"rtl\">٣١</span>هزارگزی جنوب خاوری گلَندُوَک و دوهزارگزی جنوب راه شوسه ٔ دماوند به تهران . دامنه و سردسیر. با <span class=\"hlight\" dir=\"rtl\">١٨٦</span> تن سکنه . آب آن از رودخانه ٔ سیاهرود. محصول آن غلات و بنشن و میوه جات و قلمستان . شغل اهالی زراعت و راه آن ماشین رو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(175522, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی از دهستان مرکزی بخش بیارجمند شهرستان شاهرود. در <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی خاور بیار و <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی دستجرد. کوهستانی و معتدل . با <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و تنباکو و پنبه . راه آن مالرو است . از بیار اتومبیل در فصل مقتضی می توان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175523, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ده کوچکی است از دهستان دشتابی بخش بوئین شهرستان قزوین . در <span class=\"hlight\" dir=\"rtl\">٣٠</span>هزارگزی شمال باختری بوئین و <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی راه عمومی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٤٠</span> تن است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(175524, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی از دهستان برج اکرم بخش فهرج شهرستان بم . در دوهزارگزی باختر فهرج و یکهزارگزی شوسه ٔ بم به زاهدان . جلگه، گرمسیر، مالاریائی . با <span class=\"hlight\" dir=\"rtl\">٦٦</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و خرما و حنا. شغل اهالی زراعت و راه آن فرعی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175525, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش مشیز شهرستان سیرجان در <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی شمال مشیز و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی باختر راه شوسه ٔ کرمان به سیرجان . کوهستانی و سردسیر. با <span class=\"hlight\" dir=\"rtl\">٩١</span> تن سکنه . آب آن ازقنات . محصول آنجا غلات و حبوبات . شغل اهالی زراعت . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175526, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ده کوچکی است ازدهستان سعیدآباد بخش مرکزی شهرستان سیرجان در <span class=\"hlight\" dir=\"rtl\">١٣</span>هزارگزی شمال سعیدآباد. سرراه فرعی خیرآباد به سعیدآباد. با <span class=\"hlight\" dir=\"rtl\">١٤</span> تن سکنه . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175527, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان باغین بخش مرکزی شهرستان کرمان . در دوهزارگزی جنوب کرمان، سر راه فرعی زرند به کرمان . جلگه و معتدل . با <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و تریاک و میوه جات . شغل اهالی زراعت، صنایع دستی و قالی بافی . راه آن فرعی است . مزرعه رعبه جزء این ده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175528, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان بیزکی بخش حومه ٔ شهرستان مشهد، در <span class=\"hlight\" dir=\"rtl\">٤٥</span>هزارگزی شمال باختری مشهدو دوهزارگزی شوسه ٔ مشهد به قوچان متصل به کلاته ٔ علیخان . جلگه و معتدل . با <span class=\"hlight\" dir=\"rtl\">٨٢</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و چغندر و عدس . شغل اهالی مالداری و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175529, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی از دهستان برکال بخش بردسکن شهرستان کاشمر، در <span class=\"hlight\" dir=\"rtl\">٢٨٠</span>هزارگزی جنوب خاوری بردسکن سر راه مالرو عمومی بردسکن . جلگه و گرمسیر است . <span class=\"hlight\" dir=\"rtl\">١٠١</span> تن سکنه دارد. آب آن از قنات . محصول آنجا غلات و پنبه و زیره ٔ سبز و منداب . شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175530, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان ریوند بخش حومه ٔ شهرستان نیشابور. در هفت هزارگزی جنوب نیشابور. جلگه و معتدل با <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و تریاک . شغل اهالی زراعت و گله داری و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175531, 'طاهرآباد', '<span class=\"hlight\">طاهرآباد.</span> <font color=\"DarkGreen\"><b>[ هَ ِ ]</font></b> (اِخ ) دهی است از دهستان دینور بخش صحنه ٔ شهرستان کرمانشاهان . در <span class=\"hlight\" dir=\"rtl\">٢٨</span>هزارگزی شمال باختری صحنه و <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی باختر شوسه ٔ کرمانشاه و سنقر. دشت سردسیر. با <span class=\"hlight\" dir=\"rtl\">٣٩٥</span> تن سکنه . آب آن از رودخانه ٔ کرتویچ . محصول آنجا غلات و حبوبات و تریاک و توتون و چغندرقند. شغل اهالی زراعت است . تابستان اتومبیل میتوان برد. دبستان دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(175532, 'طاهرآباد جدید', '<span class=\"hlight\">طاهرآباد جدید.</span> <font color=\"DarkGreen\"><b>[هَِ دِ ج َ ]</font></b> (اِخ ) دهی است از دهستان قلعه نو بخش کلات شهرستان درگز. در <span class=\"hlight\" dir=\"rtl\">١٦</span>هزارگزی جنوب خاوری کبودگنبد. دامنه، معتدل . با <span class=\"hlight\" dir=\"rtl\">١٨٥</span> تن سکنه . آب آن از رودخانه . محصول آنجا غلات و بنشن . شغل اهالی زراعت و مالداری و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175533, 'طاهرآباد قدیم', '<span class=\"hlight\">طاهرآباد قدیم .</span><font color=\"DarkGreen\"><b>[ هَِ دِ ق َ ]</font></b> (اِخ ) دهی است از دهستان قلعه نو بخش کلات شهرستان درگز. در <span class=\"hlight\" dir=\"rtl\">١٧</span>هزارگزی خاور کبودگنبد. دامنه و معتدل . با <span class=\"hlight\" dir=\"rtl\">١٩٠</span> تن سکنه . آب آن از رودخانه . محصول آنجا غلات و بنشن . شغل اهالی زراعت و قالیچه بافی و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175534, 'طاهرات', '<span class=\"hlight\">طاهرات .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص، اِ) ج ِ طاهرة. زنان پاکیزه .<br /></font></div>'),
(175535, 'طاهرالباطن', '<span class=\"hlight\">طاهرالباطن .</span> <font color=\"DarkGreen\"><b>[ هَِ رُل ْ طِ ]</font></b> (ع ص مرکب ) آنکه خدا اورا از وسوسه و هوی و هوس هائی که در دل میگذرد حفظ کند. (از تعریفات جرجانی ). رجوع به طاهر باطنی شود.<br /></font></div>'),
(175536, 'طاهرالحریم', '<span class=\"hlight\">طاهرالحریم .</span> <font color=\"DarkGreen\"><b>[ هَِ رُل ْ ح َ ]</font></b> (اِخ ) یا حریم طاهرمحله ای است از محلات بغداد غربی بازار که جامعی داردو منفرد واقع شده، منسوب به طاهر ذوالیمینین میباشد. (مراصد الاطلاع ). و رجوع به قاموس الاعلام ترکی شود.<br /></font></div>'),
(175537, 'طاهربغده', '<span class=\"hlight\">طاهربغده .</span> <font color=\"DarkGreen\"><b>[ هَِب ُ دَ ]</font></b> (اِخ ) گندمان . رجوع به گندمان شود. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>). رجوع به طاهر بوغده شود.<br /></font></div>'),
(175538, 'طاهربوغده', '<span class=\"hlight\">طاهربوغده .</span> <font color=\"DarkGreen\"><b>[ هَِ دَ ]</font></b> (اِخ ) نام آبادیی بوده از توابع سقز که در فرهنگستان بجای آن نام «گندمان » نهاده اند. (فرهنگستان ). رجوع به طاهر بغده شود.<br /></font></div>'),
(175539, 'طاهرتونی', '<span class=\"hlight\">طاهرتونی .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) از قصبه ٔ تون و پدرش دردربار شاه عباس وقایعنگار بوده، این بیت از اوست :<br />سر تا قدمم رفته بتاراج نگاهی <br />از چشم و دلم ماند همین اشکی و آهی .<br /><font color=\"Red\">(قاموس الاعلام ترکی ج <span class=\"hlight\" dir=\"rtl\">٤</span>).</font><br /></font></div>'),
(175540, 'طاهرده', '<span class=\"hlight\">طاهرده .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ]</font></b> (اِخ ) دهی است از توابع فرح آباد مازندران . (سفرنامه ٔ مازندران و استرآباد رابینو ص <span class=\"hlight\" dir=\"rtl\">١٢٠</span> بخش انگلیسی ). دهی است از دهستان اندرود بخش مرکزی شهرستان ساری در نه هزارگزی خاوری ساری و <span class=\"hlight\" dir=\"rtl\">٤/٥</span>هزارگزی شمال شوسه ٔ ساری به بهشهر. دشت و معتدل و مرطوب و مالاریائی . با <span class=\"hlight\" dir=\"rtl\">١١٠</span> تن سکنه . آب آن از رودخانه ٔ تجن، محصول آنجا برنج غلات، پنبه و صیفی . شغل اهالی زراعت و تهیه ٔ زغال . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175541, 'طاهرزاده', '<span class=\"hlight\">طاهرزاده .</span> <font color=\"DarkGreen\"><b>[ هَِ دَ ]</font></b> (اِخ ) میرزاعلی اکبر صابر (تولد <span class=\"hlight\" dir=\"rtl\">١٢٧٨</span> وفات <span class=\"hlight\" dir=\"rtl\">١٣٢١</span> هَ . ق .). وی یکی از شعرای توانا و بزرگ شروان است، و در قرن سیزدهم هجری در شهر شماخه تولدیافته، در هشت سالگی او را به یکی از مکاتب قدیمی سپردند. طرز تدریس این نوع دبستانها خواندن طوطی وار قرآن و کتاب بود، حتی اجازه ٔ نوشتن هم نمیدادند و این کودک هوشیار غلط بودن این اصول را دریافته نقاشی حروف می پرداخت ولی چه چاره که مکتب دار نادان اجازه نمیداد، حتی کار به زدن کودک منجر میشد و صابر در این باره حسب حال و شعری کودکانه ساخته است . چون بسن دوازده رسید وی را به مکتب سیدعظیم شروانی که یکی از شعرای نامدار آن زمان بود سپردند. سید مردی بصیر و واقف بود و آینده ٔ درخشان این کودک را هم از عهد خردی از ناصیه ٔ حالش خواند و در تعلیم و تشویق وی کوششی بسزا نشان میداد و برای تمرین و ورزش طبع او را واداشت که اشعار گلستان و غیره را نظماً به ترکی ترجمه کند چنانکه در ترجمه ٔ شعر «دیدم گل تازه چند دسته » گفته :<br />کوردیم نیچه دسته تازه گل لر<br />با غلانمش ایدی گیاه ایلن تر.<br />متأسفانه پدرش بسیار از این مرحله ها دور و در فکر کار و کاسبی بوده و پس از سه چهار سال تحصیل وی را به کسب و کار وادار کرد و شاید می ترسید که درس و بحث او را از راه راست بازدارد و فرزند دلبندش به ضلالت و گمراهی بیفتد و دین و ایمان از دستش برود، اما در اندرون آن خسته دل چیزی بود که وی را راحت نمی گذاشت و نمیتوانست آسوده و فارغبال به کسب و داد و ستد بپردازد و همه حواسش به شعر و تتبع در نظم و نثر معطوف بود و کار بجائی رسید که پدر بی خبر از حظ و لذت ادب و دانش به نکوهش فرزند هوشیار پرداخت و او را به جرم دانش طلبی اذیت و آزار میکرد و بالاخره دفتر اشعار و سفینه ٔ غزل او را تکه تکه کرد و دور انداخت این واقعه دل حساس شاعر جوان را آزرده ساخت و از کانون خانوادگی متنفر شد و عزم را جزم کرد که ترک میهن خود شروان بگوید و بهمراهی کاروان به خراسان برود چنانکه گوید:<br />من خلیل اﷲ عصرم، پدرم چون آزر<br />سفر از بابل شروان کنم انشأاﷲ<br />گر چه او دفتر اشعار مرا پاره نمود<br />وصله با طبع درافشان کنم انشأاﷲ.<br />امّا پدر زود از قضیه آگاه شد و وسایل برگرداندن او را از بین راه فراهم کرد بعد از این حادثه مراعات ذوق و سلیقه ٔ پدر و هم جنسانش را که در محیط زندگانی اکثریت داشتند، مصلحت دید و شروع به مرثیه گوئی و نوحه خوانی کرد و دردو ماه محرم و صفر در مجالس سوگواری مرثیه میخواند.از آن پس همه کس وی را دوست میداشت، محبوب پدر و ریاکاران دیگر واقع شد. شمعی بود که جمعی بدورش پروانه وار میگردیدند و نکته سنجی و لطیفه گوئی و بذله سرائی وی را بجان می خریدند و همه منتظر بودند که شماره های مجله ٔ ملانصرالدین هر چه زودتر منتشر شود تا چکامه های پر از لطافت و شوخی های نیشدار شاعر شیرین زبان را مطالعه کنند و محظوظ شوند، ادبا و نویسندگان عظام از لوازم عزت احترام در حق او کوتاهی نمیکردند، مخصوصاً استادش حاجی سیدعظیم شیروانی که خود یکی از شعرای نامدار بود فریفته ٔ وی شد. روزی با هم بدیدن دوستی که از سفر برگشته بود رفتند، وی ده عدد لیمو از چمدان درآورد و برسم ارمغان دو عدد به سید و یکی به صابر داد و تقاضای سرودن یک بیت مناسب حال کرد صابر گفت :<br />خمس شرابی سیده ساقی و یروب دیدی <br />صابر فقیر دُر، یترآ نجاق زکاة اونا<br />صابر از شعرای خیال پرست نبود، و در مدح و ذم کس شعر نمی سرود با اشخاص کاری نداشت بلکه هنر خودرا در راه اصلاح معایب جامعه و تهذیب اخلاق به کار میبرد چنانکه گوید:<br />شاعرم چونکه، وظیفه م بودر اشعار یازیم <br />گور دیگم نیک و بدی ایلریم اظهار یازیم <br />گونی پارلاق کونشی آغ، کیجه نی تار یازیم <br />کجی، کج اگر ینی، اگری، دوزی هموار یازیم .<br />نیه بس بویله برولدیرسن آقارو کوزیکی <br />یوقه بوآینه ده اگری گوریرسن اوزیکی <br />وی از مداحی و تملق متنفر بود و در جواب کسانی که می گفتند صابر در قصاید غرا پیاده است گوید من در سرودن قصاید متملقانه اقتدار ندارم، افتخارم بسرودن هجوهای مشتمل بر انتقادات اجتماعی میباشد:<br />شعر بر گوهر یک دانه ٔ ذی قیمت در<br />سالمارام وصف دروغ ایله اولی قیمتدن <br />دیه رم هجو سوزوم دو غرو، کلامم شیرین <br />اهل ذوقه ویژرم نشأه بوخوش شربتدن <br />وقتی به یکی از غزلهای دلنشین سید که ظاهراً در حق صابر ساخته بود نظیره ای بانامه ای بدو فرستاد نامه وقتی رسید که سید مشغول مطالعه ٔ خمسه ٔ نظامی بود. از خواندن نظیره غزل خویش چنان محظوظ شد که همان کتاب را بعنوان صله بدو ارسال داشته در پاسخ نوشت که جز این کتاب چیزی حاضر نبود که برایت صله بدهم هم این را بیادگار استادت نگاهدار.<br />غزل سید عظیم شروانی :<br />ای مه بیلورم فتنه ٔ دوران اولا جاقسان <br />ای قاشی هلالم مه تابان اولا جاقسان <br />نظیره ٔ صابر:<br />سن پیر جهاندیده سن ای سید سرکار<br />مندن چک الگسا ایله گیلن پیرایله گفتار<br />اولماز سگا قسمت دخی بو دولت دیدار<br />بوندان سوگراهجرمده جگرقان اولاجاقسان <br />عاشق بگابرمن کیبی زیبا کرک اولسون <br />مایل گله بربلبل شیدا کرک اولسون <br />سنده بوایشه صبر و شکیبا کرک اولسون <br />اما بیلورم صبر ایوی ویران اولاجاقسان <br />در بیست و دوسالگی بعزم زیارت خراسان بار سفر بست چنانکه گوید:<br />صابر شیدا که ترک شهر شروان ایلدی <br />بلبله بکزردی کیم میل گلستان ایله دی <br />مین اوچ یوزبرده (<span class=\"hlight\" dir=\"rtl\">١٣٠١</span>) هجرتدن شوکر میمون ایلی <br />آخر شوال ده عزم خراسان ایله دی .<br />یکچند در خراسان، سبزوار، نشابور، تربت حیدریه، تربت جام، خواف، سمرقند و بخارا سیاحت کرد و دست فروشی را ممر معاش خود قرار داد، و در خلال این احوال در نواحی خراسان مرض وباظهور کرد و صابر ناچار به شماخه بازگشت، و پس از چندی باز به عزم زیارت کربلا از شماخه بیرون آمد و به عتبات عالیات تشرف جست ضمناً اشعار گوناگون و نوحه ها هم می سرود در همدان از میزبان خود جویای احوال شهر شد و در این باره گوید:<br />دیدی آزایسه ده بوشهر ده سایر مخلوق <br />لیک دباغ ایله صباغ ایله ایشک چو قدر<br />پس از مراجعت از کربلا بار دیگر به خراسان رفت و مصمم شد که در مرو و عشق آباد رحل اقامت افکند ولی در همین اوقات نامه ٔ سوزناکی از مادر بخط برادرش به او رسید که باعث فسخ عزیمت وی گردید، و در نتیجه بوطن خود بازگشت و تأهل اختیار کرد و در عرض پانزده سال صاحب هشت دختر شد و عائله ٔ بزرگی تشکیل داد و برای تحصیل معاش بصنعت صابون پزی پرداخت و بندرت به شعرو شاعری می گرایید و گاه بگاه با عباس صحّت و محمد طراح دو شاعر هم مسلک و دو یار جانی خود ملاقات میکرد و در سال <span class=\"hlight\" dir=\"rtl\">١٩١٣</span> م . با فریدون بک کوچولینسکی که یکی از معارف پروران بود آشنائی یافت و در خلال این احوال در اثر دائر شدن مجله ٔ انتقادی و فکاهی ملانصرالدین میدان وسیعی برای این مرد سخنگوی تهیه شد چنانکه از شماره ٔ <span class=\"hlight\" dir=\"rtl\">٤</span> سال اول مجله مزبور آثار دلکش و شیرین صابر به امضای «هوپ هوپ » در آن مجله دیده میشود. مشروطه ٔ ایران و قهرمانان آن زمینه ٔ خوبی برای او فراهم ساخت، آزادی و استبداد را موضوع مدح و ذم خویش کرد تا آنجا که فارسی زبانان هم بقرائت مجله ٔ ملانصرالدین راغب و طالب شدند، مدیر روشن ضمیر آن جلیل محمدقلی زاده هم یکی از مردمان آزادی خواه و غیرتمند آن عصر بود، از صابر برای مجله ٔ خود استفاده کرد و کمکهای بسیاری به وی نمود نوشته های شاعر اشکهائی در لفافه ٔ خنده یعنی هجوهای حقیقی و ملیح بود، اوضاع جامعه ٔ اسلام و سالوسان وریاکاران و زهدفروشان را بشدت بباد انتقاد می گرفت شخصیتها و طبقات برجسته را در آثار خود حیات جاویدانی می بخشید. عامیان خرافات پرست و زاهدان ریاکار و مقدس مآبان زهدفروش در حق وی بدگوئیها میکردند و او را به بابی گری و کفر و زندقه متهم میساختند و او همه ٔ این یاوه گوئیها را با خونسردی تلقی میکرد و در این باره سروده است :<br />اشهد باللّه العلی العظیم <br />صاحب ایمانم آشروانلی لار<br />یوق یکی بردینه یقینم منم <br />کهنه مسلمانم آشروانلی لار<br />شیعه ام، اما، نه بواشکالدن <br />سنی ام، اما نه بو امثالدن <br />صوفیم اما نه بو ابدالدن <br />حق سرون انسانم آشروانلی لار<br />امت مرحومه و مغفور ایله <br />امرده ام طاعت مزبور له <br />کفریمه حکم ایلمه یک زورایله <br />قائل قرآنم آشروانلی لار<br />صابر مجدد بزرگ ادبیات ترکی آذربایجانی است . وی اشعار را وسیله ٔ ستایش و تملق گوئی به این و آن قرار نداد و به روش مستقیم رآلیزم وحقیقت پرستی به اصلاح جامعه و انتقادات مؤثر پرداخت و طبع خلاق و مصور او به نقاشی و مجسم کردن عیوب معاصران در شکل و مقیاس بسیار برجسته و جالب توجهی آغاز کرد و با ریزه کاریهای بسیار دقیق و ظریف حقایق را برملا میساخت و مبتکر طرز ادا و شیوه ٔ بیان مخصوصی شد. وی طفل یکشبه ای بود که دوره ٔ صد ساله را پیمود و از افکار و از نویسندگان عصر خود قرنها پیش افتاد و در تشریح مسائل اجتماعی و سیاسی ید بیضا کرد و یکی از طرفداران جدی آزادی و حکومت مشروطه بود و در ریشه کن کردن استبداد همه را تحریض و ترغیب میکرد جرائد و مجلات وقت مانند: حیات، فیوضات، رهبر دبستان، ملانصرالدین، الفت، ارشاد، گونش، صدا، حقیقت، ینی حقیقت، معلومات، از نبوغ قلمی وی استفاده میکردند و با این وصف اواز دست هنرهای خویش فریاد میکرد چونکه هر یکی بدگرگونه ناشادش می داشتند چه از طعن و لعن عوام الناس و مردمان خرافات پرست برکنار نبود و حتی از دست عیال خود هم در رنج و عنا بود که مانند دشمن خانگی با وی سازگار نمی آمد. سرانجام بترک «هوپ هوپ » نام مستعار خود هم مجبور شد و آثار خود را بنامهای گوناگون : «دین دیره کی « »مرات » «فاضل » «آغلار کوله گن » «ابونصر شیبانی » امضا میکرد و بالاخره طعن و لعن جهال کار را بجائی رسانید که قصاب ها به بهانه ٔ بابی گری و کافری باو دنبه نمی فروختند که مایه عیش بوسیله ٔ شماعی به دست بیاوردپس ناچار کمابیشی طرز تعلیم نوین را بیاموخت و مدرسه ای به نام مکتب امید دائر کرد، ولی این کار هم چندان نگرفت و ناچار در سال <span class=\"hlight\" dir=\"rtl\">١٩١٠</span> م . عازم شهر بادکوبه شدو از اتفاقات نیک در اوایل قرن بیستم میلادی مختصر جنب و جوشی در بین مسلمانان شهر مزبور پیدا و جمعیت های خیریه ای مانند جمعیت نشر معارف، جمعیت نجات، و جمعیت سعادت با نظامنامه های مصوب، از طرف حکومت تأسیس شده بود و با جدیت مشغول نشر فرهنگ و تعلیمات اجتماعی در میان مسلمانان بودند، وقتی که صابر به باکو آمدجمعیت نشر معارف فرصت را غنیمت شمرد و وی را به معلمی شرعیات و زبان فارسی در مکتب جدیدالتأسیس قصبه ای موسوم به بالاخانه در نزدیکی باکو منصوب ساخت و اشعاری که وی در این دوره میسرود در سال پنجم مجله ٔ ملانصرالدین درج شده است . متأسفانه در سال <span class=\"hlight\" dir=\"rtl\">١٩١١</span> م . وی سخت مریض شد و در نتیجه به شماخه، و از آنجا برای معالجه به تفلیس رفته هیأت تحریریه ٔ مجله ٔ ملانصرالدین مخصوصاً خود و خانم مدیر خوش منش و نیک فطرت آن لازمه ٔ معاونت و کمک را برای شفا یافتن او به کار بردند.<br />لیکن بهبود حاصل نشد و سرانجام به میهن برگشت و در <span class=\"hlight\" dir=\"rtl\">١٢</span> ایلول ماه <span class=\"hlight\" dir=\"rtl\">١٩١٢</span> درگذشت، این رباعی فارسی را در دم آخر سروده است :<br />راهم بدهید روبراه آمده ام <br />بر درگه حضرت اله آمده ام <br />بی تحفه نیامدم نه دستم خالی است <br />با دست پر از همه گناه آمده ام .<br />و صاحب ریحانة الادب آرد: میرزا علی اکبر طاهرزاده متخلص به صابر از مشاهیر شاعران قفقاز، در دهم ذیحجه ٔ <span class=\"hlight\" dir=\"rtl\">١٢٧٨</span> هَ . ق . در شماخی که قصبه ٔ بلاد شیروان روسیه است متولد شده و در <span class=\"hlight\" dir=\"rtl\">٢٨</span> رجب <span class=\"hlight\" dir=\"rtl\">١٣٢٩</span> هَ . ق . درگذشته است شرح حال مختصر وی در آغاز کتاب هوپ هوپ نامه ٔ خود وی بدین سان آمده است : در هشت سالگی به مکتب رفته و بنوشتن درسهای خود شیفته بوده است لیکن از طرف معلم خود بجای تحسین مورد تنبیه واقع شده است و در این باره بزبان ترکی کودکانه گوید:<br />دوتدم اوروجی ایرمضاندا<br />قالدی ایکی گزلریم قازاندا<br />ملامداد و یوریازی یازاندا<br />و در دوازده سالگی به مکتب حاج سیدعظیم رفته و بفاصله ٔ دوسال که اندکی فارسی و ترکی فرا گرفته و به اصول کتابت آشنا شده است دیگر پدرش به درس خواندن وی راضی نشده و او را بهمراهی خود به تجارتخانه اش میبرده، لیکن صابر در آن حال نیز در اثر شوق فطری که داشته به خواندن و نوشتن حریصتر بود تا به تجارت و به همین جهت پدرش او را مورد ملامت قرار داد و کتاب شعرش را پاره کرد و او نیز تصمیم گرفت از مولد خود شماخی فرار کند و این قصیده را سرود:<br />من خلیل اﷲ عصرم پدرم چون آزر<br />سفر از بابل شروان کنم انشأاﷲ<br />گرچه او دفتر اشعار مرا پاره نمود<br />وصله با طبع درافشان کنم انشأاﷲ<br />سپس بهمراهی قافله ٔ خراسان عازم آن سامان بوده ولی پدرش پس از آگاه شدن از این سفر وی را از وسط راه بازگردانده است . آنگاه به سبب نوحه هائی که در مصیبت حضرت سیدالشهدا (ع ) سروده است در نزد پدر و اهالی محبوبیت یافته است وقتی بهمراهی استاد خود حاج سیدعظیم بدیدار مسافری میرود و آن مسافر از ده دانه لیمو که با خود همراه داشته دو دانه به سید ویکی هم به صابر میدهد سید از صابر خواستار شعری در این موضوع میشود و او این بیت را میسراید:<br />خمس شرابی سیده ساقی و یروپ دیدی <br />صابر فقیر دوریتر آنجاق زکاة اونا<br />صابر در سال <span class=\"hlight\" dir=\"rtl\">١٣٠١</span> هَ . ق . در حدود بیست وسه سالگی به زیارت حضرت رضا (ع ) عازم خراسان میشود و مدتی در مشهد و سبزوار و تربت حیدریه و بلاد ترکستان به سیاحت می پردازد و آنگاه به شماخی مولد خویش بازمیگردد و آهنگ سفر کربلای معلی میکند و هنگام ورود به همدان این شعرها را میسراید:<br />همداندا قونا غمدان خبرالدیم کی شیخ <br />هانسی مخلوق سیزون شهرده بیشک چوخدور<br />دیدی آزایسه ده بو شهرده سایر مخلوق <br />لیک دباغ ایله صباغ ایله ایشک چوخدور<br />صابر وقت خویش را صرف مدایح دروغین نکرده و بستایش ارباب قدرت و صاحبان سیم و زر نپرداخته است و در پاسخ کسانی که وی را در این باره به ناتوانی نسبت میداده اند گفته است : اگرچه در مدیحه گوئی دروغین بطمع پول قادر نیستم، لیکن در هجو صادق بسیار توانا هستم . و این اشعار را در این باره سروده است :<br />شعر بیرگوهر یکدانه ذی قیمتدور<br />سالمارام وصف دروغیله اونی قیمتدن <br />دبیرم هجو سوزوم دوغری کلامیم شیرین <br />اهل ذوقه ویررم نشأه بو خوش شربتدن <br />صابر هر موضوعی را موافق ذوق خویش می یافت درباره ٔ آن غزل و قطعه ومرثیه میگفت تا آنکه روزنامه ٔ ملانصرالدین را که در تفلیس انتشار یافت بهترین وسیله ٔ نشر افکار خویش دیدو نخستین شعری که در شماره ٔ چهارم آن روزنامه منتشرساخته است این انتقاد ملیح اوست که به امضای هوپ هوپ چاپ شده است :<br />سس سالما یاتانلا آییلار قوی هله یاتسون <br />یا تمشلاری راضی دگلم کیمسه او یاتسون <br />تک تک آییلان وارسه ده حق دادیمه <br />چاتسون من سالم اولوم جمله جهان باتسادا باتسون <br />ملت نیجه تاراج اولور اولسون نه ایشیم وار<br />دشمن لره محتاج اولور اولسون نه ایشیم وار...<br />و اشعار او نوعاً به طرفداری از رنجبران و فقرا مشتمل بر انتقادات ادبی و اجتماعی و هواخواهی از تمدن ایرانی و حمله بمسامحه ٔ اولیای امور بوده است . دیوان اشعار او که بزبان ترکی قفقازی و مشهور به هوپ هوپ نامه است نخستین بار در سال <span class=\"hlight\" dir=\"rtl\">١٩١٤</span> م . در بادکوبه چاپ شده است و چند سال پیش در تبریز نیز مجدداً به طبع رسیده است .<br />درباره ٔ حقیقت گوئی خود گوید:<br />شاعرم چونکه وظیفم بودور اشعار یازیم <br />گوردوگوم نیک و بدی ایله یم اظهار یازیم .<br />گونی پارلاخ گونشی آغ گیجه نی تاریازیم <br />کجی کج اگرینی اگری دوزی هموار یازیم <br />نیه بس بیله برلدیرسن آقاری گوزووی <br />یوخسابو آینه ده اگری گورورسن اوزووی <br />و در انتقاد از زناشوئی نامتناسب میان مرد باسواد و زن بیسواد گوید:<br />چاتلیورخان باجی غمدن اورکیم <br />قاوو شوب لاپ آجیقیمدن کوره کیم <br />نولا بیرایوده قویایدوزقره باش <br />ویر مییدو زمنی بوابلهه کاش <br />منکه دامنان باجادان با خمازدیم <br />سوکیمی هرطرفه آخماز ایدیم <br />هرزه هرزه دانشوب گرسه زدیم <br />ارنه شی اولاد غونی بیلمزدیم <br />اوتوروب آج کومه سینده آتامین <br />بیش دوشین حاضر ایدردیم آنامین <br />بیتلیور دوم نه نه مین باش یاخاسین <br />یا ما یاردوم بابامون چول چوخاسین <br />تیز دوروب صبح ساغاردیم اینکی <br />خان صنمدن دیلمزدیم کومگی <br />نه ایلیوردوم بزه گی یا دوزگی <br />داما دیواره یاخاردیم تزگی <br />آتام علاف بابام دولگرایدی <br />قارداشیم جولفاعمیم کار گرایدی <br />خان بی بیم فالچی ننم باغ تو خویان <br />بیزده حاشایوخودی بیراوخویان <br />ایویمزده واریدی هرنه دیسن <br />قاتیخ آیرانیله قایماق نه یسن <br />نه بیلوردوخ نه زهیرماردی کتاب <br />بیزاولان ایوده هاچان واریدی کتاب <br />بوسبوتون گل کیمی انسانلاردیق <br />نه معلم و نه درس آنلاردیق <br />دفترین آندراقالمش سوزینی <br />ایشیدوب گورمش ایدیک یوزینی <br />بویله بیرتربیه لی ایوده مدام <br />بسله دوزمن کبیی بیرسروخرام <br />وای اوگوندن که منی آدایلدوز<br />ایله بیلدوزده کی دلشادایلدوز<br />منده ساندیم که دونوپ بخبتوره <br />گیدروم بیرنفر انسانه اره <br />نه بیلوم بیله ده انسان واریمیش <br />شکل انساندادا حیوان واریمیش <br />ار اوخورموش دایاز ارمیش دا آتام ؟!<br />اردگل مهلک آزارمش ده آتام <br />اردگل شاعر یمیش خانه خراب <br />فکری یازماخ اوخوماخ شغلی کتاب <br />سالدوز آخرده یامان حاله منی <br />اره ویر دوزده بوقفاله منی <br />گاه یازور گاه اوخویور گاه دانشیر<br />گونده بیرهرزه کتابنان تانشیر<br />گاه گیدور فکره برلدیر گوزونی <br />محواولور ایله گی بیلمر اوزونی <br />صبح اولنجا گیجه لردار غاکیمی <br />یاتمیور قیرقیر ایلور قارقاکیمی <br />گاه دابیر یاتسارا وقتنده اگر<br />چکمیور یوخلادیقی بیراوقدر<br />غفلةً بیرده گورورسن که دورور<br />یاندیروب لامپانی چیلاق اوتورور<br />باشلیور یاتدیقی یرده تزه دن <br />اوخویوب یازماتایرده تزه دن <br />بیله اوت اولماز آتام بیله الو<br />ات دگل یالفی دگل لودی بولو<br />گاه گورورسن که میزاوسته سخیلور<br />باخیرام حالینه قلبم یخلور<br />بیرقارانداش بیرایکی پاره کاغاذ<br />اوقدر چکمیر اولور قاره کاغاذ<br />خبرینی شرینی قانمیر بوکیشی <br />یور ولوب بیرجه اوساغیر بوکیشی <br />بیزیم ایوده باخاسان هر طرفه <br />طاقچه یه بوقچه یه یا کیم ارفه <br />گوره جک سن بوتون اشکافدا کاغاذ<br />کاسه دانیمچه ده بوشقابدا کاغاذ<br />یغیلوب داغ کیی هر یاندا کتاب <br />ایوده دهلیزده هریاندا کتاب <br />دیورم آی کیشی بیرگل اوزووه <br />بونه ایشدور آکل اولون گوزووه <br />بوعمل ایتیدی سنی خانه خراب <br />پوللارون دوندی بوتون اولای کتاب <br />اوخودو قجاگو زوون قاره سنی <br />اپارورتاپ باشوون چاره سنی <br />پولی گیدیر تاب وتوانون داگیدیر<br />اوسته لیک بیرقوری جانون داگیدیر<br />کسب و کارندان الون چیخدی اوسان <br />اراولان یرده گوروم یوخ اولاسان <br />در استبداد محمدعلی شاه قاجارگوید:<br />مولدائی سالمادی ایل دیل بوغازا<br />عیبی یوخ گرچه قویدلدوخ لوغازا<br />یاز بواعلانمیده بیرکاغاذا<br />آچمشام «ری » ده گینش بیر مغازا<br />چون اوجوز قیمته هر شیئی ساتیرام <br />آی آلان مملکت ری ساتیرام <br />مغازامدا تاپلوز هرجوره زاد<br />جام رأیت کی تخت قباد<br />گرچه بازایمی ایتمکده کساد<br />سعی ایدور بیر پاره ایرانلی نژاد<br />لیک من باخمیورم هی ساتورام <br />آی آلان مملکت ری ساترام <br />نه گرکدور منه بیر بونجه امور<br />که ایده قلبمی بی حسن حضور<br />باباما ویرمدی ال «آبک شور»<br />دگلم ناخلف و نابشعور<br />«قصر شیرین » اثر کی ساتورام <br />آی آلان مملکت ری ساتیرام <br />ایستمم نوری قرانلوق سویورم <br />ملک ایرانی دومانلوق سویورم <br />بوشیلوب شهری یابانلیق سویورم <br />بسدی شهلک داخی خانلوق سویورم <br />«سبزوار» ایله «میامی » ساتورام <br />آی آلان مملکت ری ساتیرام <br />ایستمم نوری قرانلوق سویورم <br />ملک ایرانی دومانلوق سویورم <br />بوشیلوب شهری یامانلیق سویورم <br />بسدی شهلک داخی خایلوق سویورم <br />«سبزوار» ایله «میام » ساتورام <br />آی آلان مملکت ری ساتیرام <br />سوزبنیم ایوبنیم اسرابینم <br />عرض و ناموس بینم عاربنیم <br />مال بنیم مصلحت کار بنیم <br />ساتیرام دولت قاجار بنیم <br />کیمه نه دخلی که من شی ساتیرام <br />آی آلان مملکت ری ساتیرام <br />شاه مشروطه پناه اولماق ایسه <br />ایل قویان وضعله شاه اولماق ایسه <br />گوش بر امر سپاه اولماق ایسه <br />شاه اولوب همدم آه اولماق ایسه <br />خان اولوب نوش ایلیوب می ساتیرام <br />آی آلان مملکت ری ساتیرام .<br /><font color=\"Red\">(از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">١٠</span>- <span class=\"hlight\" dir=\"rtl\">١٣</span>).</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175542, 'طاهرظاهری', '<span class=\"hlight\">طاهرظاهری .</span><font color=\"DarkGreen\"><b>[ هَِ رِ هَِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کسی باشد که خدای عز اسمه، او را از نافرمانیها و معصیتها بازداشته باشد. (کشاف اصطلاحات الفنون ) (تعریفات جرجانی ).<br /></font></div>'),
(175543, 'طاهرلو', '<span class=\"hlight\">طاهرلو.</span> <font color=\"DarkGreen\"><b>[هَِ ]</font></b> (اِخ ) دهی است از دهستان خدابنده لو بخش قروه ٔشهرستان سنندج، واقع در <span class=\"hlight\" dir=\"rtl\">٢٦</span>هزارگزی جنوب خاور گل تپه و <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی خاور دلی محمد. کوهستانی و سردسیر است، با<span class=\"hlight\" dir=\"rtl\">٦٥٠</span> تن سکنه . آب آن از چشمه ها. محصول آنجا غلات، انگور، لبنیات و صیفی . شغل اهالی زراعت و گله داری . راه آن مالرو است . تابستان از طریق بهار و جمشیدآباد میتوان اتومبیل برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(175544, 'طاهرلو', '<span class=\"hlight\">طاهرلو.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است جزء دهستان قشلاقات افشار بخش قیدار شهرستان زنجان، واقع در <span class=\"hlight\" dir=\"rtl\">٤٨</span> هزارگزی باختر قیدار و <span class=\"hlight\" dir=\"rtl\">٣٦</span>هزارگزی راه مالرو عمومی . کوهستانی و سردسیری است، با <span class=\"hlight\" dir=\"rtl\">١٧٠</span> تن سکنه . آب آن از قزل اوزن . محصول آنجا غلات . شغل اهالی زراعت و صنایع دستی زنان گلیم و جاجیم بافی است . راه مالرو دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(175545, 'طاهره', '<span class=\"hlight\">طاهره .</span> <font color=\"DarkGreen\"><b>[ هَِ رَ ]</font></b> (اِخ ) لقب سیدةالنساء فاطمه ٔ زهرا علیهاالسلام . رجوع به فاطمه ٔ زهرا شود.<br /></font></div>'),
(175546, 'طاهره', '<span class=\"hlight\">طاهره .</span> <font color=\"DarkGreen\"><b>[ هَِ رَ ]</font></b> (اِخ ) لقب نجمه مادر امام هشتم علی بن موسی الرضا سلام اﷲ علیهما بوده است . میرخواند مینویسد: در کشف الغمة از هشام بن احمد که در سلک خواص کاظم انتظام داشت مروی است که گفت : روزی کاظم مرا مخاطب کرده، فرمود که هیچ دانسته ای که از تجار مغرب کسی آمده است ؟ گفتم : ندانسته ام گفت که آمده است . پس با وی سوار شدیم و برفتیم تا به تاجر مغربی رسیدیم و او را گفتیم هر کنیزکی که آورده ای بر ما عرض کن . هفت کنیزک به ما نمود و کاظم علیه السلام هیچ کدام را قبول نفرمود و گفت که دیگر عرض کن، جواب داد که دیگر نمانده است مگر جاریه ای بیمار کاظم، گفت : چه شود که آنرا نیز بما نمائی تاجراین التماس را اجابت نموده، کاظم بازگشته روز دیگر مرا گفت : برو و غایت ثمن کنیزک بیمار را از تاجر پرسیده بهرچه بگوید او را بیع نمای و من پیش تاجر مغربی رفتم و از بهای آن جاریه سؤال کردم، جواب داد که او را از مبلغ کذا کم نمیفروشم، گفتم : بدان مبلغ که نام بردی من وی را خریدم، گفت : من هم بتو فروختم، امابگوی که آن مرد که دیروز همراه وی بودی کیست ؟ گفتم :مردی است از بنی هاشم، گفت : از کدام قبیله ٔ هاشم ؟ گفتم : بیش از این نمیدانم . پس گفت : ترا خبری دهم من این کنیزک را در اقصای مغرب خریدم و زنی از اهل کتاب با من گفت که این کنیزک از کیست ؟ گفتم : او را برای مردی خریده ام . گفت : کلا و حاشا هرگز این کنیزک بتو مخصوص نتواند بود باید که او نزد بهترین اهل زمین باشد واز وی به اندک زمانی فرزندی در وجود آید که از شرق تا غرب مانند وی کسی نبود راوی گوید که چون آن جاریه را به کاظم (ع ) رسانیدم، بعد از انقضای اندک وقتی رضا (ع ) از وی تولد نمود و روایتی آنکه والده ٔ امام رضا (ع ) نجمه نام داشت و در اول حال کنیزک حمیده بود که مادر کاظم است و حمیده شبی محمد رسول اﷲ (ص ) را درخواب دید که فرمود نجمه را به پسر خود موسی بخش که زود باشد که از وی فرزندی متولد گردد که بهترین اهل زمین باشد و آن حمیده صفات بر طبق اشارت سید کائنات عمل نمود و امام هشتم از نجمه تولد فرمود. آنگاه حمیده او را طاهره نام نهاد از طاهره مروی است که گفت : در آن ایام که به علی بن موسی الرضا (ع ) حامله بودم اصلاً ثقل احساس نمیکردم و در اوقات نوم از شکم خود آواز تسبیح و تهلیل و تقدیس و تمجید میشنودم و هول و هیبت بر من مستولی شده، چون بیدار میگشتم هیچ صوتی به گوش من نمی رسید و در آن دم که رضا (ع ) در وجود آمد، دیدم که دستها بر زمین نهاده بود و سر بجانب آسمان برداشته و لبهای او می جنبید، چنانکه کسی سخن گوید و مناجات کند. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٨٣</span> - <span class=\"hlight\" dir=\"rtl\">٨٤</span>).<br /></font></div>'),
(175547, 'طاهره', '<span class=\"hlight\">طاهره .</span> <font color=\"DarkGreen\"><b>[ هَِ رَ ]</font></b> (اِخ ) قرةالعین . رجوع به طاهره ٔ زرین تاج و قرةالعین شود.<br /></font></div>'),
(175548, 'طاهره', '<span class=\"hlight\">طاهره .</span> <font color=\"DarkGreen\"><b>[ هَِ رَ ]</font></b> (اِخ ) فاطمه ٔ زهرا علیهاالسلام . رجوع به فاطمه شود.<br /></font></div>'),
(175549, 'طاهره', '<span class=\"hlight\">طاهره .</span> <font color=\"DarkGreen\"><b>[ هَِ رَ ]</font></b> (اِخ ) ست نفیسه بنت حسن بن زیدبن حسن بن علی بن ابیطالب (ع ) که لقبش طاهره و کریمةالدارین است . در سال <span class=\"hlight\" dir=\"rtl\">١٤٥</span> هَ . ق . در مکه متولد شده و در مدینه با زهد و عبادت بسر میبرده و هم بالین اسحاق مؤتمن فرزند حضرت صادق (ع ) بوده و از آن دو نور پاک دوفرزند قاسم و ام کلثوم نامی بوجود آمده، پس با شوهر و فرزندان خود بمصر رفته و بفاصله ٔ هفت سال در رمضان <span class=\"hlight\" dir=\"rtl\">٢٠٨</span> هَ . ق . در آنجا وفات یافته و اسحاق میخواست که جنازه اش را به مدینه نقل دهد، لیکن اهالی مصر از روی عقیده ٔ کاملی که نسبت به آن مخدره ٔ معظمه داشتند درخواست کردند که آن نعش پاک را در خاک ایشان دفن کندکه وسیله ٔ تبرک و میمنت ایشان باشد. اسحاق نیز قبول کرد و وی را در خاک مصر مدفون ساخت و اکنون آرامگاه او زیارتگاه عام و خاص میباشد. طاهره در حق فقرا و بیماران تلطف های بی نهایت مبذول میداشته و همواره روزه دار و شب زنده دار بوده و تا اسحاق حاضر نمیشده، تناول غذا نمیکرده است و در حال احتضار نیز روزه دار بوده و جمعی از حاضران درخواست افطار کردند، گفت : سبحان اﷲ سی سال است که از درگاه خداوندی مسئلت میکنم که روزه دار از دنیا بروم چگونه اکنون از این آرزوی سی ساله دست بردارم و در آن حال این بیت را میخوانده است :<br />اصرفوا عنی طبیبی و دعونی و حبیبی <br />زادنی شوقی الیه و غرامی و نحیبی <br />و پس از آن شروع به تلاوت سوره ٔ انعام کرد وچون به آیه ٔ شریفه ٔ لهم دارالسلام رسید جان بمالک جانان سپرد و امام شافعی در آن اوان ساکن مصر بوده و به زیارت آن خاتون معظمه میرفته و درخواست دعای خیر میکرده است . (از خیرات حسان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span>). و رجوع به ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span> شود.<br /></font></div>'),
(175550, 'طاهره', '<span class=\"hlight\">طاهره .</span> <font color=\"DarkGreen\"><b>[ هَِ رَ ]</font></b> (اِخ ) زرین تاج . عنوانی است که فرقه ٔ بابیه به زرین تاج داده اند چون میرزا علی محمد باب در نامه هائی که درباره ٔ وی مینوشته، او راطاهرة... خطاب میکرده است، چنانکه باب در پاسخ نامه ٔ یکی از بابیان درباره ٔ زرین تاج مینویسد: «و اما سئلت عن المراة التی زکت نفسها و اثرت فیها الکلمة التی انقادت الامور لها و عرفت بارئها فاعلم انها امراة صدیقه عالمة عاملة طاهرة و لاترد الطاهرة فی حکمها فانها ادری بمواقعالامر من غیرها و لیس الا اتباعها». دراینجا باب وی را راستگو و دانا و عمل کننده و طاهره نامیده و عقاید وی را تأیید کرده و مخاطب را به پیروی از او توصیه کرده است و از آن پس در میان بابیان به این نام مشهور و همه به او حضرت طاهره یا جناب طاهره خطاب کرده اند و اما لقب قرةالعین را شیخیه به اوداده اند چه پدرش حاجی ملا محمدصالح قزوینی از فضلا و علمای عصر، خود او را به عقد ازدواج برادرزاده ٔ خویش ملا محمد فرزند حاج ملا تقی برغانی از اعاظم مجتهدین اصولی مشهور به شهید ثالث درآورد و در آن روزگار چون غوغای اختلاف علمای شیخیه و اصولیین در همه جا و از جمله در شهر قزوین بالا گرفته و خصوصاً حاج ملا تقی برغانی نخستین کسی بوده که رایت مخالفت و معاندت با شیخ احسائی را برافراشته بود، مباحثه و مشاجره ٔ این دودسته نظر کنجکاو زرین تاج را که اساس تحصیلاتش بر عقاید علمای اصولی مبتنی بود بخود جلب کرد و پس از یک سلسله مطالعات در آثار شیخیه و حشر و نشر با پیروان این طایفه عاقبت بجانب مسلک شیخیه گرائید و با سیدرشتی جانشین شیخ احسائی که در کربلا اقامت داشت به مکاتبه پرداخت و طولی نکشید که شوق زیارت شیخ در وی برانگیخته شد و عازم سفر کربلا گردید و دو پسر و یک دختر خود را بشوهر سپرد و همراه تنی چند از اهل خاندان که گویا مرضیه خواهرش نیز با وی بوده بسوی کربلا رهسپار شد. و ایام اواخر عمر سیدرشتی را درک کرد و به خوشه چینی از خرمن فضل او پرداخت و از جانب سید به قرةالعین ملقب گردید. خانواده ٔ قرةالعین همه مذهبی بوده و به داشتن علم و ثروت مشهور بوده اند و او در شهر قزوین در چنین خانواده ای متولد شده است و چنانکه یاد کردیم پدرش حاج ملا صالح از علمای عصر خود بشمار میرفته وعموی او حاج ملا تقی برغانی نیز از مجتهدان بوده و عم دیگرش حاج ملا علی از پیروان مسلک شیخ احمد احسائی بشمار میرفته است . طاهره پس از طی دوران کودکی با خواهر خود مرضیه مقدمات علوم را در محضر پدر آموخته و پس از فراگرفتن مقدمات به تحصیل فقه، اصول و کلام و ادبیات عرب پرداخته است، پس از چندی از زنان نامور بشمار میرفت و آثار نظم و نثر وی مایه ٔ شهرت او گردید.میگویند برادرش عبدالوهاب قزوینی که از دانشمندان بوده درباره ٔ قرةالعین گفته است : در حضور او جرأت تکلم نداشتیم و بحدی معلومات وی همه را مرعوب ساخته بود که در مسائل مورد بحث گفتگو میکردیم چنان آنرا واضح و روشن برای ما مدلل میساخت که فوراً همه سرافکنده و خجلت زده بیرون میرفتیم . قرةالعین چنانکه یاد کردیم بعدها به کربلا رفت و پس از تکمیل مطالعات خود و درگذشت سیدکاظم رشتی مجلس درسی در کربلا ایجاد کرد و برای عده ٔ کثیری از طلاب از پس پرده تدریس می کرد و به این ترتیب در آن نواحی نیزشهرت یافت و چون مقارن این روزگار ندای ظهور سیدباب در شیراز به گوشش رسید، از دیدن آثار و نوشته های سید به وی ایمان آورد. و در شمار حروف حی، یعنی نخستین هیجده تنی که به باب گرویده بودند درآمد و از این پس بی پروا در کربلا به تبلیغ و دعوت مردم پرداخت و به اطراف و اکناف نامه مینوشت و مردم را به کیش خویش دعوت میکرد و حتی با پدر و عموی خود نیز به مکاتبه و مباحثه پرداخته است و تا آنجا که آثار بابیان حکایت دارد از بستگان او خواهرش مرضیه و آقا میرزا علی شوهروی و حاجی ملا علی عمویش بباب گرویده اند. قرةالعین در خانه ٔ سیدکاظم رشتی اقامت داشته و عیال سید که به وی ارادت میورزیده، از وی پذیرائی می کرده و بابیان مقیم کربلا در آن منزل فراهم می آمده و به تبلیغات قرةالعین گوش فرامیداده اند. دیری نمی گذرد که بی پروائی اوعلمای کربلا را برمی انگیزد و در نتیجه، حاکم کربلا وی را به خروج از آن شهر تکلیف می کند و وی با تنی چند از زنان و همراهان خود به بغداد میرود و در آنجا بر مفتی شهر وارد می شود و با وی به مُحاجه می پردازد و مدتی در آن شهر میماند و در سال <span class=\"hlight\" dir=\"rtl\">١٢٦٣</span> هَ . ق . عازم ایران می شود. وی هنگام اقامت در عراق عرب نامه ها و رسالاتی به ایرانیان مینوشته که از آنجمله دو رساله یکی بعربی در جواب حاجی محمد کریم خان کرمانی و دیگری بفارسی در جواب ملا جواد خوارولیانی باقی مانده است . هنگامی که قرةالعین عازم ایران می شود جماعتی از همکیشان وی از عراق عرب با او همراه بوده اند که شیخ صالح عرب و شیخ طاهر واعظ و ملا ابراهیم محلاتی و آقا سیدمحمدگلپایگانی را میتوان از خواص اصحاب او نام برد. نخست به کرمانشاه میرود و در آنجا چند روز اقامت میکند و از آنجا بهمدان رهسپار می شود و علمای آن شهر را به دین خود دعوت میکند و در نتیجه، غوغائی در شهر برپامی شود و قصد داشته است یکسره بجانب تهران حرکت کند و محمدشاه را به آیین خود بخواند، ولی پدرش از ورود او به ایران آگاه می شود و کسی را بسوی او میفرستد که بقزوین بیاید از این رو قرةالعین با همراهان خود وارد قزوین می شود. لیکن در این شهر نه تنها نصیحت پدر و بستگانش در او مؤثر نشد، بلکه با آنان به مباحثه پرداخت و سرانجام پدرش او را منع میکند که از خانه خارج شود و چون با عموی خود حاج ملا تقی به مشاجرات و مباحثات می پردازد، عاقبت عمویش او را آزار و اذیت می کند. در این هنگام حادثه ٔ فجیعی روی میدهد که موجب فرار قرةالعین از قزوین و کشته شدن چند تن از همراهان او میشود. شرح فاجعه این است که در قزوین شیخ صالح طاهرنامی از مردم شیراز و از مریدان شیخ احسائی هنگامی که میشنود حاج ملا تقی شیخ را لعن میکند، نزد وی میرود و از مراد خود سخن بمیان می آورد و چون او نسبت به شیخ بدزبانی میکند به عقیده ٔ خود حاج ملا تقی را واجب القتل تشخیص میدهد و منتظر فرصت می شود و روزی در حالی که حاج ملا تقی در محراب مشغول نماز بوده، غفلتاً بر وی میتازد و او را میکشد. این در زمستان سال <span class=\"hlight\" dir=\"rtl\">١٢٦٣</span> هَ . ق . در قزوین روی میدهد، پیداست که کشتن چنین مجتهدی در شهر، هیجان و انقلاب عظیمی برپا کرد و بسابقه ٔ اختلاف عقیده و مباحثات طولانی قرةالعین با وی انظار عموم در این حادثه یکجهت متوجه قرةالعین میشود وهمه او را محرک و مسبب قتل عموی خود میدانند. از این رو زندگی وی و یارانش در معرض خطر واقع می شود و چنانکه صاحب نقطةالکاف مینویسد از این طایفه قریب <span class=\"hlight\" dir=\"rtl\">٦٠</span> یا <span class=\"hlight\" dir=\"rtl\">٧٠</span> تن را بیگناه دستگیر میکنند و آنان را به انواع گوناگون زجر و شکنجه میدهند و از جمله یاران قرةالعین شیخ صالح عرب را چوب بسیار میزنند و میخواهند او را داغ کنند که ناگهان قاتل خود را به حکومت معرفی میکند و با کمال صراحت، حقیقت واقعه را شرح و اقرار به قتل میکند. معالوصف قاتل مزبور را با چند تن از پیروان قرةالعین از قبیل : ملا ابراهیم محلاتی و شیخ صالح عرب و حاجی محمدعلی و حاجی اسداﷲ نام پیرمردی مریض زنجیر میکنند و بتهران روانه میسازند. در تهران قاتل فرار میکند و از بابیه دستگیر شده در اثر پافشاری صدر قزوینی شیخ صالح عرب را سر میبرند و حاجی اسداﷲ را نیز میکشند و دو تن دیگر را بقزوین برمیگردانند و به درختی می بندند و مردم شهر جمع می شوند و هر یک زخمی به آنان میزنند تا به فجیعترین وضع کشته می شوند. این کشتار نخستین خونریزی است که از بابیه در ایران روی داده است، ولی قرةالعین در بحبوحه ٔ این غوغا، یعنی هنگامی که مأموران حکومت در تعقیب وی بوده اند، شبانه به دستیاری چند تن از همکیشان خود موفق به فرار می شود و از بیراهه بجانب خراسان میرود و ملا محمد شوهر وی نیز مقارن این ایام او را طلاق داده است . در این هنگام ملا حسین بشرویه ملقب به باب الباب و معروف به اول من آمن برای تبلیغ در خراسان اقامت داشته و بابیان مکلف به پیوستن به وی بوده اند. قرةالعین هم بهمین مناسبت بجانب خراسان روانه شده و در قریه ٔ بدشت یکفرسنگی شاهرود به گروهی دیگر از بابیان که عازم خراسان بوده اند برمی خورد و در این ضمن ملا محمدعلی بارفروشی، ملقب به قدوس که از سران بابیان بوده، از خراسان وارد و در بدشت به آن گروه می پیوندد و با قرةالعین ملاقات میکند و بابیه که در این موقع از بیشتر شهرهای ایران بسوی خراسان میرفته اند، جمع کثیری شده بودند وپس از ورود قدوس در بدشت توقف میکنند. گویا بر اثر غوغائی که در خراسان بعلت تبلیغات ملا حسین بشرویه برپا می شود، گروه مزبور از رفتن به خراسان صرف نظر می کنند و در بدشت اقامت میگزینند و مجمع مهمی تشکیل میدهند و اختلاف نظری روی میدهد؛ گروهی میگفته اند باید همه اصول باب را به عوام بابیه گفت و گروهی معتقد بوده اند صلاح نیست عوام از همه مطالب آگاه شوند. قرةالعین طرفداری از عقیده ٔ نخستین میکند و دیگران هم رای اورا می پذیرند و وی در بدشت همه روزه از پس پرده برای جماعت مزبور وعظ و نطقهای مهیجی ایراد میکرده است وروزی که تصمیم داشته منظور خود را عملی کند، یعنی حقیقت دین باب را به عوام آن فرقه بازگوید به دو تن از خواص خود دستور میدهد که در ضمن نطق، هنگامی که اواشاره میکند با قیچی بندهای پرده را که از پس آن سخن میگفته پاره کنند و در این روز در برابر جماعت کثیری از همکیشان خود که برای استماع نطق او گرد آمده بودند سخنرانی مهیجی کرد و ناگهان گفت : «سیدباب همان قائم منتظری است که مطابق اخبار اسلام بشرع جدید و کتاب جدید ظهور کرده و همانطور که همه فرستادگان الهی ناسخ آئین قبل خود بوده اند او نیز نسخ کننده ٔ قرآن و شریعت اسلام است ...» در همین اثنا به اشاره ٔ وی پرده ٔحائل نیز افتاده و چهره و اندام وی در برابر آن گروه هویدا می شود. دیدن این منظره و شنیدن بیانات صریح او، شنوندگان را به وحشت و شگفتی عمیقی دچار کرد؛ بعضی چشم خود را بستند که دیدگانشان برخسار زن نامحرمی نیفتد و گروهی از آن انجمن گریختند و عده ٔ کمی هم گفتار و کردار وی را به دیده ٔ قبول نگریستند و آنان که مخالف این روش وی بودند در میان همهمه و جار و جنجال از این عمل نابهنگام او بشدت انتقاد کردند و شکایت وی را نزد قدوس که در آن مجمع حضور نداشت بردند، ولی او گفتار و کردار قرةالعین را تأیید کرد و همه ساکت و آرام شدند. باری اجتماع بابیه در بدشت در نیمه ٔ اول سال <span class=\"hlight\" dir=\"rtl\">١٢٦٤</span> هَ . ق . پایان یافت و قرةالعین بهمراهی قدوس و دیگر همکیشانش روانه ٔ مازندران شد و تا اراضی هزار جریب با آنان بود، ولی در این هنگام اهالی قرا و قصبات آن سامان بابیان را سنگسار کردند و اموالشان را به یغما بردند و از اینجا قرةالعین برای تبلیغ به «نور» مازندران رفت و قدوس و همراهانش عازم بارفروش شد و پس از واقعه ٔ بدشت دیری نگذشت که ملا حسین بشرویه هم از خراسان به مازندران آمد و بابیها که قرار بود در خراسان به وی ملحق شوند در مازندران به وی پیوستند و جنگ معروف قلعه ٔ طبرسی که میان آنان و قوای دولتی روی داد آغاز و منجر به مقاومت شدید بابیان گردید و سرانجام گروهی از آنان کشته شدند. اما قرةالعین پس از یک رشته تبلیغات در نواحی نور عازم بارفروش گردید و به قدوس ملحق گشت و در اینجا میرزا یحیی نوری معروف به صبح ازل را ملاقات کرد و چنانکه نویسنده ٔ نقطةالکاف آرد به دستور قدوس، صبح ازل را بجائی که مأمور بوده بردند و ظاهراً قرةالعین از آنجا بازبه نور روانه شده باشد و چون گرفتاری او در نور پس از واقعه ٔ مازندران واقع شده، قدر مسلم آن است که وی در تمام طول جنگ طبرسی که نزدیک به <span class=\"hlight\" dir=\"rtl\">٩</span> ماه، یعنی از شوال <span class=\"hlight\" dir=\"rtl\">١٢٦٤</span> تا اواخر جمادی الثانی <span class=\"hlight\" dir=\"rtl\">١٢٦٥</span> هَ . ق . بوده است در نواحی مختلف مازندران پنهان و آشکار به تبلیغ و دعوت مردم اشتغال داشته است . و در این مدت صبح ازل را هم مکرر ملاقات کرده و عاقبت پس از خاتمه ٔ جنگ طبرسی در نور بدست اهالی دستگیر و بتهران اعزام شده و در خانه ٔ محمودخان کلانتر محبوس گردیده است . محبس وی در این خانه اطاقی در بالاخانه ٔ بسیار مرتفعی بوده که راه به جائی نداشته و از نردبان بلندی که بوسیله ٔ عبور و مرور آن بوده در مواقع احتیاج آمد و شد میکرده و تا پایان زندگی در زندان بسر برده و بسرودن اشعارو خواندن مناجات نامه ها و ادعیه مشغول بوده است و گاهی هم علما و فضلا برای محاجه و مباحثه بنزد وی میرفته اند. نیکلا در کتاب خود شرح مباحثه ٔ حاجی ملا علی کنی و حاجی ملا میرزا محمد مازندرانی را با قرةالعین یادکرده و مینویسد این مباحثه به امر میرزا آقاخان نوری صدراعظم صورت گرفته و عاقبت همین دو مجتهد حکم تکفیر و قتل او را داده اند. قرةالعین تا قضیه ٔ تیراندازی سه تن از بابیان به ناصرالدین شاه در نیاوران شمیران در روز یکشنبه <span class=\"hlight\" dir=\"rtl\">٢٨</span> شوال <span class=\"hlight\" dir=\"rtl\">١٢٦٨</span> هَ . ق . همچنان در زندان بسر میبرده است . پس از این واقعه که گروهی از بابیان را کشتند، قرةالعین را نیز در همان ایام استنطاق میکنند و او دست از عقیده ٔ خود برنمیدارد و بی پرواپیروی خود را از آئین باب اعلام میدارد. کنت دو گبینو در کتاب فلسفه و مذهب در آسیای وسطی مینویسد: یک روز صبح محمودخان از اردوی سلطنتی بازگشت و داخل اندرون شد و پس از سلام و احترامات لازم به قرةالعین گفت : خبر تازه ٔ خوشی برای شما آورده ام . قرةالعین تبسمی کرد و با کمال شتاب گفت : من آنرا میدانم و احتیاج به گفتن شما ندارم . محمودخان گفت : شما ممکن نیست بدانید قضیه از چه قرار است، زیرا این امری است که صدراعظم مرا مأمور کرده به شما اعلام کنم و تردیدی ندارم که سلامتی تان در آن است و آن این است که شما را به نیاوران میبرند و میپرسند که قرةالعین آیا شما بابی هستیدشما فقط جواب میدهید نه، آنها با اینکه یقین دارند بابی هستید مایلند بیش از این از شما جوابی نشنوند وامیدوارند یک چند شما بحالت انزوا زندگی کنید و با مردم سخن نگوئید و مستخلص شوید. قرةالعین گفت : قضیه چنین نیست که شما نقل میکنید، بلکه بهتر از آن است که خبر میدهید ولی خودتان از آن آگاه نیستید. قضیه این است که فردا ظهر خود شما که کلانتر هستید مرا زنده خواهید سوزانید و من چنانکه آرزوی من است یک شهادت درخشانی به خدا و حضرت خواهم داد. محمودخان متحیرانه گفت : شما در این اندیشه نباشید قضیه چنین نیست، زیرامحققاً شما از آنچه میخواهند امتناع نخواهید کرد و البته هواخواهان شما هم به گفتار شما اطاعت خواهند کرد این چه خیالی است میکنید. قرةالعین با یک لحن جدی گفت : امیدوار نباشید که من آنی هرچند بظاهر هم باشدعقیده ٔ خود را انکار کنم آن هم برای یک امر پوچ و مهمل که یک کالبد موقتی بی قدر و قیمت را چند روز بیشتر حفظ کنم ! نه اگر از من بپرسند و البته خواهند پرسید من سعادتمندم که حیات خود را در راه خدا بدهم و تو محمودخان حالا آنچه را که بتو میگویم و فردا مرگ من بتو ثابت خواهد کرد که ترا فریب نداده ام گوش بده اربابی که تو به او خدمت میکنی پاداش خدمت ترا نخواهد داد، بلکه برعکس تو بحکم ظالمانه ٔ او با کمال بیرحمی تلف خواهی شد، پس سعی کن که قبل از مرگ روحت را به شناسائی حقیقت پرواز دهی . بنابر آنچه نقل شد هنگامی که قرةالعین در استنطاق بابیگری خود را انکار نکرد خواهی نخواهی باید کشته شود، ولی جریان قتل وی مانند دیگر بابیان آشکار نبوده، بلکه شبانه او را از خانه ٔ کلانتر به باغ ایلخانی میبرند و با شتاب بقتل میرسانند. درباره ٔ طرز کشتن او اقوال مختلفی است، نیکلا بتفصیل در فصل دوازدهم کتاب خود این واقعه را آورده است که اینک قسمتی از آن نقل میشود: یکی از برادرزاده های کلانتر درباره ٔ قتل قرةالعین بدینسان حکایت میکند: هنگامی که حاجی ملا میرزا محمد اندرمانی و حاجی ملا علی کنی فتوای قتل قرةالعین را نوشتند و برای شاه فرستادند، شاه به کشتن او امر داد. قضیه محرمانه بود و تنها دو تن از کارکنان دولتی میدانستند چند روزی بود که عمویم امر کرده بود با دقت مواظب پلیس باشم و بتوسط گشتی های بسیار کاملاً اطمینان حاصل کنم که پلیس ها در سر پست خود حاضرند یا نه و اعلان کردند که هیچ کس پس از سه ساعت از شب گذشته حق ندارد در کوچه ها بماند. در این شب به من امر شد که یک دسته پلیس را از خانه ٔ کلانتر تا باغ ایلخانی ردیف قرار دهم . من کسان خود را پنهان کرده بودم و به آنها امر دادم که هر کس از اعضا و کارکنان ما نباشد فوراً دستگیر و بکشند. چهار ساعت پس از غروب آفتاب، کلانتر از من پرسید که آیا تمام احتیاطات لازم را بجا آورده ای یا نه ؟ و نظر به اطمینانی که به او دادم مرابخانه برد و تنها در اندرون داخل شد و بلافاصله با قرةالعین برگشت و پاکت مهر کرده بمن داد و گفت باید این زن را به باغ ایلخانی ببری و به عزیزخان سردار تسلیم کنی و رسید بگیری . اسبی آوردند و قرةالعین را سوار کردم، اما از ترس اینکه مبادا بابیها از واقعه خبردار شوند، شنل خودم را روی سر او انداختم که هر کس او را ببیند خیال کند مرد است . با یک مرکب تمام مسلح براه افتادیم و در وسط کوچه ها میرفتیم، اما با وجودتمام احتیاطات لازم که بعمل آورده بودیم و با وجود قوای مهمی که ما را احاطه کرده بودند یقین دارم که اگر بما حمله میشد تمام افراد ما فرار میکردند؛ زیرا بابیها بقدری ترس و وحشت در مردم تولید کرده بودند که حدی بر آن متصور نبود. همین که داخل باغ شدم نفس راحتی کشیدم . محبوس را در اطاقی گذاردم که در دالان دم در باغ بود و به سربازان امر کردم بدقت پاسبان در باشند، سپس برای دیدن سردار بطبقه اول عمارت رفتم . او تنها بود و انتظار ورود مرا داشت نامه را به او دادم، خواند و گفت : کسی ملتفت نشد که اسیر کیست ؟ گفتم هیچ کس در کوچه نبود خواهش میکنم رسید آنرا بمن بدهید.گفت : نه، تو باید در اجرای قتل حضور داشته باشی بعدرسید خواهم داد. پیشخدمت ترکی داشت او را صدا زد. جوانی خوش چهره بود سردار از او بسیار تعریف کرد و گفت : مدتی است که تو در خدمت من هستی و من چنانکه باید بتو توجهی نکرده ام، اما من ترا دوست دارم و میخواهم گذشته را تلافی کنم و بتو پاداشی بدهم عجالتاًً این بیست اشرفی را بگیر و هر طور دلت میخواهد خرج کن . عنقریب یک شغل خوب برای تو تهیه خواهم کرد فعلاً این دستمال ابریشمی را بگیر و با این افسر برو پائین او ترابه اطاقی خواهد برد که یک زن کافر در آنجاست و مؤمنین را از طریقه اسلام برمیگرداند با این دستمال او را خفه کن، البته خدمت خوبی است که بخدا میکنی و من نیز به تو پاداش خوبی خواهم داد. پیشخدمت تعظیمی کرد و با من به راه افتاد و من او را بردم به اطاق دیدم محبوس بسجده افتاده و دعا میخواند. پیشخدمت جوان بر آن شد که مأموریت خود را انجام دهد قرةالعین سر از سجده بلند کرد نگاه عمیقانه ای به او کرد و گفت : ای جوان ! حیف است دست تو به آدم کشی آلوده شود. نمیدانم این کلام چه تأثیری در روح این جوان کرد که مانند دیوانگان پا به فرار گذاشت، من هم دنبال او دویدم و با هم رسیدیم نزد سردار. پیشخدمت گفت : غیرممکن است که من این کار را انجام دهم، البته میدانم از مرحمت شما محروم خواهم شد و به دست خود اسباب بدبختی خود را فراهم میکنم معهذا نمیتوانم به این زن دست بزنم . عزیزخان با تغیر او را از پیش خود راند و چند ثانیه فکر کرد، سپس یکی از سوارانش را احضار کرد که مدتی بود مغضوب واقع شده و برای تنبیه بخدمات آشپزی مشغول بود وچون حاضر شد بطور دوستانه به او تغیر کرد و گفت : خوب پدرسگ دزد گمان میکنم تنبیه تو کافی باشد، البته عاقل شده ای و بعد از این با فکر کار میکنی و دست از دیوانگی خواهی کشید و مورد التفات من میشوی میدانم دراین مدت بسیار سختی کشیده ای و بتو بد گذشته است . بیا این استکان عرق را بگیر و بخور بتو اجازه میدهم، پس از آن دستمال تازه ای به او داد و همان امری که بجوان ترک کرده بود تجدید کرد. با هم رفتیم به اطاق بمحض ورود خود را روی قرةالعین انداخت و دستمال را به دور گردنش پیچید و چندین دفعه بسختی کشید تا بالاخره نفس او قطع شد. زن بزمین افتاد دوباره یک زانویش را روی پشت او گذاشت و دستمال را با تمام قوت کشید و مانند اینکه از عمل خود میترسید و مهلت جان دادن به او نداد و بفوریت جسدش را بلند کرد و برد تا عقب دیوار یخچال و در حالتی که هنوز کاملاً جان نسپرده بود در چاه انداخت . سردار نوکران را صدا کرد و با عجله چاه را پر کردند که سپیده ٔ صبح نزدیک بود. از اشعار او:<br />جذبات شوقک الجمت بسلاسل الغم و البلا<br />همه عاشقان شکسته دل که دهند جان به ره ولا<br />اگر آن صنم ز سر ستم پی کشتنم بنهد قدم <br />لقد استقام بسیفه فلقد رضیت بما رضی ̍<br />سحر آن نگار ستمگرم قدمی نهاد به بسترم <br />فاذا رأیت جماله طلع الصباح کانما<br />لمعات وجهک اشرقت و شعاع طلعتک اعتلی <br />زچه رو الست بربکم نزنی بزن که بلی بلی <br />بجواب طبل الست تو ز ولا چو کوس بلا زدند<br />همه خیمه زد بدر دلم سپه غم و حشم بلا<br />من و عشق آن مه خوبرو که چو شد صلای بلا برو<br />بنشاط و قهقهه شد فرو که اناالشهید بکربلا<br />نه چوزلف غالیه بار او نه چو چشم فتنه شعار او<br />شده نافه ای بهمه ختن شده کافری بهمه ختا<br />تو که غافل از می و شاهدی پی مرد عابد زاهدی <br />چه کنم که کافر جاحدی ز خلوص نیت اصفیا<br />بمراد زلف معلقی پی اسب و زین مغرقی <br />همه عمر کافر مطلقی ز فقیر فارغ و بینوا<br />تو و تخت و تاج سکندری من و راه و رسم قلندری <br />اگر آن خوشست تو درخوری وگر این بدست مرا سزا<br />بگذر ز منزل ما و من بگزین بملک فناوطن <br />فاذا فعلت بمثل ذا فلقد بلغت بما تشا<br />چو شنید ناله مرگ من پی ساز من شد و برگ من <br />فمشی الی َّ مهرولا و بکی عَلی َّ مجلجلا<br />چه شود که آتش حیرتی زنیم بقله طور دل <br />فسککته و دککته متد کدکا متزلزلا<br />پی خوان دعوت عشق او همه شب ز خیل کروبیان <br />رسد این صفیر مهیمنی که گروه غمزده الصلا<br />تو که فلس ماهی حیرتی چه زنی ز بحر وجود دم <br />بنشین چو طاهره دمبدم بشنو خروش نهنگ لا<br />و هم او راست :<br />در ره عشقت ای صنم شیفته ٔ بلا منم <br />چند مغایرت کنی با غمت آشنا منم <br />پرده به روی بسته ای زلف بهم شکسته ای <br />از همه خلق رسته ای از همگان جدا منم <br />شیر توئی شکر توئی شاخه توئی ثمر توئی <br />شمس توئی قمر توئی ذره منم هبا منم <br />نور توئی تتق توئی ماه توئی افق توئی <br />خوان مرا قنق توئی شاخه ٔ هندوا منم <br />نخل توئی رطب توئی لعبت نوش لب توئی <br />خواجه باادب توئی بنده بیحیا منم <br />من ز یم تو نیم نم نی ز کم و ز بیش هم <br />چون بتو متصل شدم بی حدو انتها منم <br />شاهدشوخ دلبرا گفت بسوی من بیا<br />رسته ز کبر و از ریا مظهر کبریا منم .<br />و رجوع به تاریخ ادبیات ایران ترجمه رشیدیاسمی ص <span class=\"hlight\" dir=\"rtl\">١٤٢</span> و <span class=\"hlight\" dir=\"rtl\">٢٧٢</span>، صبح ازل، باب و بابیه در همین لغت نامه شود.<br />و اوراست :<br />اگر بباد دهم زلف عنبرآسا را<br />اسیر خویش کنم آهوان صحرا را<br />وگر به نرگس شهلای خویش سرمه کشم <br />بروز تیره نشانم تمام دنیا را<br />برای دیدن رویم سپهر هر دم صبح <br />برون برآورد آیینه ٔ مطلا را<br />گذار من به کلیسا اگر فتد روزی <br />به دین خویش برم دختران ترسا را.<br />مخمس با حذف بعضی اشعار:<br />ای بسر زلف تو سودای من <br />وز غم هجران تو غوغای من <br />لعل لبت شهد مصفای من <br />عشق تو بگرفت سراپای من <br /> <font color=\"Red\">من شده تو آمده بر جای من </font><br />گرچه بسی رنج غمت برده ام <br />جام پیاپی ز بلا خورده ام <br />سوخته جانم اگر افسرده ام <br />زنده دلم گرچه ز غم مرده ام <br /> <font color=\"Red\">چون لب تو هست مسیحای من </font><br />عشق به هر لحظه ندا می کند<br />بر همه موجود صدا می کند<br />هرکه هوای ره ما می کند<br />گر حذر از موج بلا می کند<br /> <font color=\"Red\">پا ننهد بر لب دریای من </font><br />گنج منم بانی مخزن تویی <br />سیم منم حاجب معدن تویی <br />دانه منم صاحب خرمن تویی <br />هیکل من چیست اگر من تویی ؟<br /> <font color=\"Red\">گر تو منی چیست هیولای من ؟</font><br />آتش عشقت چو برافروخت دود<br />سوخت مرا مایه ٔ هر هست و بود<br />کفر و مسلمانیم از دل زدود<br />تا به خم ابرویت آرم سجود<br /> <font color=\"Red\">فرق نه از کعبه کلیسای من </font><br />دست قضا چون گل آدم سرشت <br />مهر تو در مزرعه ٔ سینه کشت <br />عشق تو گردید مرا سرنوشت <br />فارغم اکنون ز جحیم و بهشت <br /> <font color=\"Red\">نیست بغیر از تو تمنای من </font><br />عشق عَلَم کوفت به ویرانه ام <br />داد صلا بر در جانانه ام <br />باده ٔ حق ریخت به پیمانه ام <br />از خود و عالم همه بیگانه ام <br /> <font color=\"Red\">حق طلبد همت والای من </font><br />مسمط دارای دو وزن با حذف بعضی اشعار:<br />بود سوی توام راز نهانی <br />که زآنم هست عیش و کامرانی <br />شدم چون آشنای یار جانی <br />به بزم خالی از بیگانه ٔ تو<br />ای ماهرویم ای مشک مویم <br />یارم تویی تو ای شهریارم <br />منم ای سروقد دیوانه ٔ تو<br />از آن دو نرگس مستانه ٔ تو<br />شدم ازعارض جذبانه ٔ تو<br />اسیر عشق جاویدانه ٔ تو<br />ای گلعذارم بردی قرارم <br />نالان ز هجرت هم چون هزارم <br />ز عشقت گر بسوزد استخوانم <br />بجز نام تو را بر لب نرانم <br />به پای آن کسی صد جان فشانم <br />که یک بارم برد بر خانه ٔ تو<br />گاه از وصالت شادم نمائی <br />گاه از فراقت سازی نزارم <br /></font></div>'),
(175551, 'طاهرون', '<span class=\"hlight\">طاهرون .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص، اِ) ج ِ طاهر، در حالت رفع. پاکیزگان . رجوع به طاهر شود.<br /></font></div>'),
(175552, 'طاهرونی', '<span class=\"hlight\">طاهرونی .</span> (اِخ ) دهی است از دهستان سیریک بخش میناب شهرستان بندرعباس، واقع در <span class=\"hlight\" dir=\"rtl\">٨٥</span>هزارگزی جنوب میناب، سر راه مالرو جاسک به میناب . جلگه و گرمسیری است، با <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> تن سکنه . آب آن از چاه . محصول آنجا خرما. شغل اهالی زراعت . راه آن مالرو است . (فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175553, 'طاهرپاشا', '<span class=\"hlight\">طاهرپاشا.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) رجوع به چنگال اوغلی و قاموس الاعلام ترکی شود.<br /></font></div>'),
(175554, 'طاهرگوراب', '<span class=\"hlight\">طاهرگوراب .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) قصبه ای است جزء دهستان گسگر بخش صومعه سرای شهرستان فومن، واقع در <span class=\"hlight\" dir=\"rtl\">١٤</span>هزارگزی شمال باختری صومعه سرا و سر راه شوسه ٔ صومعه سرا به ضیابر. جلگه، معتدل، مرطوب و مالاریائی است، با <span class=\"hlight\" dir=\"rtl\">٧٣٥</span> تن سکنه . آب آن از رودخانه ٔ ماسال . محصول آنجا برنج، ابریشم و توتون سیگار. شغل اهالی زراعت است . از طرف سازمان شاهنشاهی خدمات اجتماعی درمانگاهی در این قصبه بنا گردیده است . پاسگاه ژاندارمری شعبه ٔ دارائی و دخانیات بهداری و یک کارخانه ٔ پیله خفه کنی و در حدود <span class=\"hlight\" dir=\"rtl\">٦٠</span> باب دکان دارد و روزهای پنجشنبه بازار عمومی است . راه فرعی ماسال از این قصبه منشعب میگردد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(175555, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابومنصور عبدالرحمن بن محمدبن عبدالواحدبن رزیق طاهری . منسوب به حریم طاهری و او از قاضی ابوالحسین بن مهتدی بالله هاشمی روایت کرده است . (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175556, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوالعباس محمدبن طاهر بغدادی طاهری . وی از ابوعروبة حرانی روایت کرده است و ابونصر احمدبن علی بن عبدوس اهوازی از او روایت دارد. وی از خاندان طاهر ذوالیمینین بوده است . (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175557, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) طیب بن محمدبن طلحة... رجوع به طاهری ابواسحاق شود.<br /></font></div>'),
(175558, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) (رباطِ...) یکی از منازل بین راه مرو و خوارزم است که از مرو تا رباط طاهری <span class=\"hlight\" dir=\"rtl\">٥٤</span> و از رباط طاهری تا خوارزم <span class=\"hlight\" dir=\"rtl\">٧٠</span> فرسنگ و مجموعاً یکصد و بیست و چهار فرسنگ باشد. (نزهةالقلوب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span>).<br /></font></div>'),
(175559, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) جعفربن محمدبن علی بن حسین ... رجوع به طاهری ابومحمد شود.<br /></font></div>'),
(175560, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابویعلی احمدبن عبدالعزیز طاهری، برادر ابوالحسن علی بن عبدالعزیز... از ابوطاهر مخاض و ابن اخماسمی (کذا) و جز آن دو روایت کرده است . او از خاندان طاهرذوالیمینین بوده است . (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »). رجوع به ابوالحسن علی بن عبدالعزیز... طاهری شود.<br /></font></div>'),
(175561, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابومنصور. از خاندان طاهریان بوده و بزبان عربی شعر میسروده و در ماوراءالنهر از گویندگان دربار سامانیان بشمار میرفته است . رجوع به احوال و اشعار رودکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٦</span> شود.<br /></font></div>'),
(175562, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابومحمد جعفربن محمدبن علی بن حسین بن اسماعیل بن ابراهیم بن مصعب بن رزیق بن محمدبن عبداﷲبن طاهربن حسین طاهری .وی از ابوالقاسم بغوی و یحیی بن صاعد و محمدبن عبداﷲمستعنی روایت کرده است و ابوالحسن عنیقی و ابوطالب بن عساری از او روایت دارند. او مردی ثقه بود در شوال سال <span class=\"hlight\" dir=\"rtl\">٣٨٣</span> هَ . ق . درگذشته است . وی از خاندان طاهر ذوالیمینین بوده است . (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175563, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوالقاسم عبداﷲبن حسین قسامی حنبلی طاهری . وی از ابونصر رسی روایت میکند و منسوب به حریم طاهری است . (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175564, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوطیب رجوع به طاهربن محمدبن عبداﷲبن طاهر شود.<br /></font></div>'),
(175565, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوعمرو احمدبن حسن طاهری نیشابوری . نام او اسعد فرخان است . وی از عبداﷲبن احمدبن حنبل و ابوشعیب حرانی روایت کرده، از خاندان طاهر ذوالیمینین بوده است . (انساب سمعانی ورق ِ <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175566, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوعبداﷲ حسین بن طیب طاهری . رجوع به حسین بن طیب شود.<br /></font></div>'),
(175567, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) حسین بن طیب . رجوع به طاهری ابوعبداﷲ و حسین بن طیب شود.<br /></font></div>'),
(175568, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوسعید عبداﷲبن احمدبن محمدبن عبداﷲبن طاهربن حسین بن طاهربن عبداﷲبن حسین بن مصعب بن رزیق طاهری . ازمردم مرو شیخی صالح بود و نظری استوار داشت و او نواده ٔ دختری ابوسهل عبدالصمدبن عبدالرحمن بن حسین بزاربود و از وی در جامع معمربن راشد حدیث کرده است . سمعانی گوید: عموی شهید من ابومحمد سمعانی از او برای من روایت کرده است . همچنین ابومحمد عبدالغفاربن عبدالسلام عسالی در مرو و ابوالفضل محمدبن احمدبن معاویه خطیب با اجازه و دیگران از او روایت کرده اند. ابوسعید طاهری در سال <span class=\"hlight\" dir=\"rtl\">٤٧١</span> هَ . ق . درگذشته است . (از انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175569, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوالحسن علی بن عبدالعزیزبن حسن بن محمدبن هرون بن عصام بن رزیق بن محمدبن عبداﷲبن طاهربن حسین بن مصعب طاهری . وی از ابوبحر محمدبن حسن بن کوثر واحمدبن جعفربن سلم و ابومالک قطیعی و جز آنان روایت کرده است . در شوال سال <span class=\"hlight\" dir=\"rtl\">٤٨٦</span> هَ . ق . درگذشته است . وی از خاندان طاهر ذوالیمینین بوده است . (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »). رجوع به ابویعلی احمد طاهری شود.<br /></font></div>'),
(175570, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابواسحاق طیب بن محمدبن طلحةبن طاهر نیشابوری طاهری . از بزرگان خاندان طاهری است و به علم و حدیث اشتغال داشت و از مردم نیشابور بود. وی از علی بن حجر و علی بن حشرم و اسحاق بن منصور و دیگر محدثان خراسانی سماع کرده است . و هم در عراق از سعیدبن عبدالجبار قرشی و عبیداﷲبن عمر قواریری سماع دارد. ابوعمر، مستملی و عبداﷲبن محمدبن سیرویه از اوروایت کرده اند. وی در ماه رمضان سال <span class=\"hlight\" dir=\"rtl\">٢٧٩</span> هَ . ق . درگذشته است و در مقبره ٔ امیر در نیشابور به خاک سپرده شده است . (از انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف » و «ب »).<br /></font></div>'),
(175571, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b>(اِخ ) ابوبکر محمدبن محمدبن اسماعیل طاهری . وی از ابوحفص بن شاهین روایت کرده است . او از خاندان طاهر ذوالیمینین بوده است . (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175572, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ابوبکر احمدبن علی بن عبدالوحد اسقر دلال طاهری . از قاضی ابوالحسین بن مهتدی باللّه هاشمی روایت کرده است و منسوب به حریم طاهری میباشد. (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175573, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b>(اِخ ) ده و بندری از دهستان ثلاث بخش کنگان شهرستان بوشهر. در <span class=\"hlight\" dir=\"rtl\">٣٦</span> هزارگزی جنوب خاوری کنگان، کنار شوسه ٔ سابق بوشهر به لنگه . جلگه، گرمسیری و مالاریائی است با <span class=\"hlight\" dir=\"rtl\">٩٨٠</span> تن سکنه . آب آن از چاه و قنات . محصول آنجا غلات، خرما، تنباکو و پیاز. شغل اهالی زراعت و ماهیگیری .پاسگاه ژاندارمری گمرک و گارد مسلح گمرک و یک دبستان <span class=\"hlight\" dir=\"rtl\">٣</span> کلاسه دارد. لنگرگاهی در کنار خلیج کوچک طاهری است به عمق <span class=\"hlight\" dir=\"rtl\">١١</span> متر و فاصله ٔ یک کیلومتر از ساحل و قابل استفاده برای کشتی های معمولی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>). بندری است در جنوب ایران که محل صیدمروارید، و راندن کشتیهای غواصی میباشد. در بلوک دشتی واقع است . شهر سیراف قدیم که خرابه های آن هنوز درحوالی بندر طاهری دیده میشود، در قرن سوم هجری مهم ترین بنادر خلیج فارس، و مرکز تجارت محصولات ممالک اطراف اقیانوس هند بوده، و بناهای بسیار عالی داشته که بواسطه ٔ زلزله ٔ شدیدی همه خراب شده، و دیگر آباد نگشته است . (جغرافیای کیهان قسمت طبیعی ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span>). بندر طاهری در <span class=\"hlight\" dir=\"rtl\">٢٦٨٥٠٠</span> گزی بوشهر میان اختر و نخل تقی واقع شده است . و رجوع به تاریخ سیستان حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span> شود.<br /></font></div>'),
(175574, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ده کوچکی است از دهستان بخش مرکزی شهرستان بندرعباس . در <span class=\"hlight\" dir=\"rtl\">٤٨</span>هزارگزی خاوری بندرعباس و <span class=\"hlight\" dir=\"rtl\">٧</span>هزارگزی راه مالرو بندرعباس به میناب . جلگه و گرمسیری است با <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه . مزارع خشک، تخت کش، مشکی و سوختگی جزء این ده است . (فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175575, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) یکی از شعرای ایران است . از اوست :<br />چو ترک سرکش من مایل شراب شود<br />ز تاب عارض او مرغ دل کباب شود.<br /><font color=\"Red\">(از قاموس الاعلام ترکی ).</font><br /></font></div>'),
(175576, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ص نسبی ) آنکه و آنچه منسوب به آل طاهر، و منسوب به حریم طاهری یکی از محلات بغداد باشد. (سمعانی ).<br /></font></div>'),
(175577, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b>(ص نسبی، اِ) نام قسمی کاغذ در قدیم، منسوب به طاهردوم از امراء طاهریه ٔ خراسان . (فهرست ابن الندیم ).<br /></font></div>'),
(175578, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) محمدبن جنید طوسی طاهری . وی از جانب عبداﷲبن طاهر که از سال <span class=\"hlight\" dir=\"rtl\">٢١٤</span> تا <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> هَ . ق . حکمرانی خراسان داشت نیابت میکرد. رجوع به احوال و اشعار رودکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> شود.<br /></font></div>'),
(175579, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) عبدالرحمن بن محمدبن عبدالواحدبن رزیق . رجوع به طاهری ابومنصور عبدالرحمن ... شود.<br /></font></div>'),
(175580, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) (ملا...) رجوع به طاهر نائینی شود.<br /></font></div>'),
(175581, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) هراتی . از اهالی هرات و یکی از شعرای ایران است که در زمان سلطان حسین میرزا میزیسته . از اوست :<br />ترا به مهر و وفا اعتبار نتوان کرد<br />چرا که عمری و بر عمر اعتباری نیست <br />چو سایه بیخود اگر در پی تومی افتم <br />ز من مبین که مرا هیچ اختیاری نیست .<br /><font color=\"Red\">(از قاموس الاعلام ترکی ).</font><br /></font></div>'),
(175582, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) محمدبن محمدبن اسماعیل ... رجوع به طاهری ابوبکر محمدبن ... شود.<br /></font></div>'),
(175583, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) محمدبن طاهر بغدادی . رجوع به طاهری ابوالعباس شود.<br /></font></div>'),
(175584, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) علی بن عبدالوهاب طاهری . وی از عباس بن فضل اسقاطی روایت کرده است . و ابوالحسن دارقطنی از او روایت دارد. وی از خاندان طاهر ذوالیمینین بوده است . (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175585, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) علی بن عبداﷲ طاهری . وی از هشام بن علی شیرازی روایت کرده است و محمدبن طیب بلوطی از او روایت دارد. وی از خاندان طاهر ذوالیمینین بوده است . (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175586, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) علی بن عبدالعزیزبن حسن ... رجوع به طاهری ابوالحسن شود.<br /></font></div>'),
(175587, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) عبداﷲبن حسین قسامی . رجوع به طاهری ابوالقاسم شود.<br /></font></div>'),
(175588, 'طاهری', '<span class=\"hlight\">طاهری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) عبداﷲبن احمدبن محمدبن عبداﷲ... رجوع به طاهری ابوسعید... شود.<br /></font></div>'),
(175589, 'طاهریان', '<span class=\"hlight\">طاهریان .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) طاهریان یکی از سلسله های ایرانی است که استقلال ایران را پس از تسلط عرب بنیان نهادند و آنان را به اسامی بنی طاهر، آل طاهر و طاهریه میخواندند. آل طاهر، دولتی ایرانی بوده و از سال <span class=\"hlight\" dir=\"rtl\">٢٠٥</span> تا <span class=\"hlight\" dir=\"rtl\">٢٥٩</span> هَ . ق . در خراسان حکمرانی کرده اند. مؤسس این دولت، طاهربن الحسین، ملقب به ذی الیمینین بوده است . مأمون خلیفه، سردار مشهور خود، طاهر ذوالیمینین را که از موالی زادگان ایرانی بود در سال <span class=\"hlight\" dir=\"rtl\">٢٠٥</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">٨٢٠/</span> م . به حکومت خراسان فرستاد. و طاهر و فرزندان او در این سرزمین مستقر شده، سلسله ٔ طاهری را تأسیس کردند و همه وقت تحت امر و تابع خلیفه بودند. هیچ وقت حوزه ٔ متصرفات این سلسله از خراسان تجاوز نکرد و قریب نیم قرن در این حال بودند تا یعقوب بن لیث صفاری، سلسله ٔ ایشان را منقرض کرد.<br />اسامی افراد این سلسله که در خراسان فرمانروائی کردند:<br />طاهر ذوالیمینین <span class=\"hlight\" dir=\"rtl\">٢٠٥</span>. هَ . ق . <span class=\"hlight\" dir=\"rtl\">٨٢٠</span>. م .<br />طلحة <span class=\"hlight\" dir=\"rtl\">٢٠٧</span>. هَ . ق . <span class=\"hlight\" dir=\"rtl\">٨٢٢</span>. م .<br />عبداﷲ <span class=\"hlight\" dir=\"rtl\">٢١٣</span>. هَ. ق . <span class=\"hlight\" dir=\"rtl\">٨٢٨</span>. م .<br />طاهر ثانی <span class=\"hlight\" dir=\"rtl\">٢٣٠</span>. هَ . ق . <span class=\"hlight\" dir=\"rtl\">٨٤٤</span>. م .<br />محمد <span class=\"hlight\" dir=\"rtl\">٢٤٨</span>-<span class=\"hlight\" dir=\"rtl\">٢٥٩</span>. هَ . ق . <span class=\"hlight\" dir=\"rtl\">٨٦٢</span>-<span class=\"hlight\" dir=\"rtl\">٨٧٢</span>. م .<br />(ترجمه ٔ طبقات سلاطین لین پول ص <span class=\"hlight\" dir=\"rtl\">١١٥</span>). و رجوع به آل طاهر و طاهریه در همین لغت نامه والنقود العربیه ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>، <span class=\"hlight\" dir=\"rtl\">١٢٤</span>، <span class=\"hlight\" dir=\"rtl\">١٣٦</span> و تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">١٧٢</span>، <span class=\"hlight\" dir=\"rtl\">٢١٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٨</span> تاریخ بیهق ص <span class=\"hlight\" dir=\"rtl\">٦٦</span> و شرح احوال رودکی ص <span class=\"hlight\" dir=\"rtl\">٩١</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>، <span class=\"hlight\" dir=\"rtl\">٣١٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٤٥</span>، <span class=\"hlight\" dir=\"rtl\">٣٤٦</span>، <span class=\"hlight\" dir=\"rtl\">٣٩٥</span>، <span class=\"hlight\" dir=\"rtl\">٣٣٥</span>، <span class=\"hlight\" dir=\"rtl\">٤٥٥</span>، <span class=\"hlight\" dir=\"rtl\">٤٥٦</span>، <span class=\"hlight\" dir=\"rtl\">٥٦٨</span>، <span class=\"hlight\" dir=\"rtl\">٥٦٩</span>، <span class=\"hlight\" dir=\"rtl\">٨٢٥</span>، <span class=\"hlight\" dir=\"rtl\">٨٧٤</span> و تاریخ اسلام ص <span class=\"hlight\" dir=\"rtl\">١٩٧</span>، <span class=\"hlight\" dir=\"rtl\">١٩٨</span> و تاریخ گزیده <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>، <span class=\"hlight\" dir=\"rtl\">٨٣٩</span> و مزدیسنا ص <span class=\"hlight\" dir=\"rtl\">١٩</span> و <span class=\"hlight\" dir=\"rtl\">٤١٨</span> و سبک شناسی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span> و ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٩</span>، <span class=\"hlight\" dir=\"rtl\">١٦٥</span>، <span class=\"hlight\" dir=\"rtl\">٢٨٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٨٥</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span> شود.<br /></font></div>'),
(175590, 'طاهریان یمن', '<span class=\"hlight\">طاهریان یمن .</span> <font color=\"DarkGreen\"><b>[ هَِ ن ِ ی َ م َ ]</font></b> (اِخ )بنی طاهر در یمن جانشین رسولیان گردیدند، و تا زمان تسخیر عربستان بدست «قانصوه الغوری » از سلاطین ممالیک مصر باقی بودند، عربستان کمی بعد به تصرف ترکان عثمانی درآمد، ولی همین که ایشان آنرا در سال <span class=\"hlight\" dir=\"rtl\">٩٢٣</span> هَ .ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥١٧</span> م . تحت امر خود درآوردند ائمه ٔ یمنی قیام کرده بمخالفت با ترکان برخاستند و بالاخره هم در سال <span class=\"hlight\" dir=\"rtl\">١٦٣٣</span> م . ترکان عثمانی را به ترک یمن مجبور کردند.<br /></font></div>'),
(175591, 'طاهریة', '<span class=\"hlight\">طاهریة.</span> <font color=\"DarkGreen\"><b>[ هَِ ری ی َ]</font></b> (ع اِ) برنجو. (مهذب الاسماء). قسمی از پختنیها.<br /></font></div>'),
(175592, 'طاهریة', '<span class=\"hlight\">طاهریة.</span> <font color=\"DarkGreen\"><b>[ هَِ ری ی َ ]</font></b> (اِخ ) دولت طاهریة در خراسان که از سال دویست و پنج تا دویست و پنجاه ونه فرمانروائی کردند، مؤسس آن طاهربن الحسین الخزاعی ملقب بذی الیمینین بوده، این دولتی فارسی و ایرانی بشمار میرفته . (تاریخ تمدن اسلامی جرجی زیدان جزء <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span>). رجوع به «آل طاهر»، طاهریان و بنی طاهر شود.<br /></font></div>'),
(175593, 'طاهریة', '<span class=\"hlight\">طاهریة.</span> <font color=\"DarkGreen\"><b>[ هَِ ری ی َ ]</font></b> (اِخ ) ناحیه ای است در بالای جیحون که بعد از آمل واقع شده است و عمل خوارزم از آنجا شروع میشود. یاقوت گوید: گمان میبرم که منسوب به طاهربن الحسین باشد. (معجم البلدان ).<br /></font></div>'),
(175594, 'طاهریة', '<span class=\"hlight\">طاهریة.</span><font color=\"DarkGreen\"><b>[ هَِ ری ی َ ]</font></b> (اِخ ) دیهی است نزدیک بغداد که هنگام افزونی آب دجله در هر سال آب بسیاری در آنجا جمع شود. و ماهی معروف به «بنی » در آن آب گرد آید و سلطان آن ماهی را به مالی وافر اجاره دهد. و این ماهی را بر سایر ماهیها برتری و رجحان است . (معجم البلدان ).<br /></font></div>'),
(175595, 'طاهرین', '<span class=\"hlight\">طاهرین .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص، اِ) ج ِ طاهردر حال نصب و جر، ائمه ٔ طاهرین . به اجداد طاهرین .<br /></font></div>'),
(175596, 'طاهریه', '<span class=\"hlight\">طاهریه .</span> <font color=\"DarkGreen\"><b>[ هَِ ری ی َ ]</font></b> (اِخ ) دهی از دهستان نهرهاشم بخش مرکزی شهرستان اهواز، واقع در <span class=\"hlight\" dir=\"rtl\">٤٢</span>هزارگزی جنوب باختری اهواز و <span class=\"hlight\" dir=\"rtl\">١٤</span>هزارگزی راه آهن اهواز به خرمشهر.دشت و گرمسیری است با <span class=\"hlight\" dir=\"rtl\">٢١٠</span> تن سکنه . آب آن از چاه . محصول آنجا غلات . شغل اهالی زراعت و گله داری . راه آن در تابستان اتومبیل رو است . بین طاهریه و شیخ محمد زیارتگاهی به نام قبر شیخ محمد وجود دارد. ساکنین از طایفه ٔ قزلی هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(175597, 'طاهل', '<span class=\"hlight\">طاهل .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص ) آب مزه و رنگ برگردیده . (منتهی الارب ). آب بدبو.<br /></font></div>'),
(175598, 'طاهی', '<span class=\"hlight\">طاهی .</span> (ع ص ) گوشت پز. بریان ساز. <BR><font color=\"Blue\">◄</font> نان پز. <BR><font color=\"Blue\">◄</font> پزنده ٔ هر نوع خوراکی . (منتهی الارب ) (آنندراج ). طباخ . آشپز. دیگ پز. ج، طهاة. (مهذب الاسماء).<br /></font></div>'),
(175599, 'طاهی', '<span class=\"hlight\">طاهی .</span> (اِخ ) اسم سوره ای از قرآن . «طه » یا «طاها<font color=\"DarkGreen\"><b>[ » سوره ٔ بیستم از قرآن ]</font></b> <span class=\"hlight\">:</span> <br />تا خانه ای از فلک بود جوزا<br />تا سوره ای از نُبی بود طاهی .<br /> <font color=\"Red\">جمال الدین عبدالرزاق .</font><br />رجوع به طاها و طه شود.<br /></font></div>'),
(175600, 'طاهیج', '<span class=\"hlight\">طاهیج .</span> (اِخ ) نام زنی است که خالدبن ولید نهری از وی به مصالحه گرفت .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175601, 'طاو', '<span class=\"hlight\">طاو.</span> <font color=\"DarkGreen\"><b>[ وِن ]</font></b> (ع ص ) طَو. گرسنه . (منتهی الارب ) (دهار). <BR><font color=\"Blue\">◄</font> گرسنه دارنده خود را. طاویة مثله فیهما. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> پیچنده . (دهار).<br /></font></div>'),
(175602, 'طاوان', '<span class=\"hlight\">طاوان .</span>(اِخ ) نام جد ابوبکر احمدبن محمدبن عبدالوهاب بن طاوان بزار واسطی است . (انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175603, 'طاوانی', '<span class=\"hlight\">طاوانی .</span> (اِخ ) منسوب به طاوان . رجوع به طاوان شود. ابوبکر احمدبن محمدبن عبدالوهاب بن طاوان بزار واسطی طاوانی از مردم واسط. (انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «الف »).<br /></font></div>'),
(175604, 'طاورومانیون', '<span class=\"hlight\">طاورومانیون .</span> (اِخ ) نام موضعی است : ثم ان فیثاغورس جال فی مدن ایطالیا و سیقلیاو کان الجور و التمرد قدغلب علیهم، فصاروا سماعیه وصدیقیه من اهل طاورومانیون . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠</span>).<br /></font></div>'),
(175605, 'طاوس', '<span class=\"hlight\">طاوس .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (معرب، اِ) طاووس . پرنده ای است معروف و آن را ابوالحسن، وابوالوشی و صرّاخ، و فلیسا، نیز نامند. پرنده ای است از پرندگان بلاد عجم، تصغیر آن طویس است بعد از حذف زیادات . ج، اطواس، و طواویس . (منتهی الارب ) (آنندراج ). کمال الدین دمیری در حیوةالحیوان آورده که : این پرنده در میان سایر پرندگان، مانند اسب است بین سایر چارپایان از حیث ارجمندی و زیبائی . صفات عفت، خودپسندی، تکبر، در پر خویش بشگفتی نگریستن، از دم خویش طاق بستن بویژه هنگامی که جفت وی ناظر و متوجه بسوی اوست، همه در وی جمع میباشد. ماده ٔ این مرغ پس از آنکه سه سال از عمرش بگذرد بیضه نهد، و در همان هنگام هم روئیدن پرهای نر به حد کمال و رنگ آمیزی آن به پایان رسد. سالی یک نوبت ماده ٔ این پرنده بیضه گذارد، حداکثر دوازده، و گاهی کم و بیش از این شماره، بیضه نهادن ماده ٔ طاوس متناوب است و متوالی نیست، در فصل بهار تخم گیری کند، در پائیز چنانکه برگ درخت میریزد، پر این حیوان نیز میریزد، و در آن فصل که برگ درختان بروئیدن آغاز کند، طاوس نیز شروع به پر برآوردن کند. طاوس نر هنگامی که جفتش مشغول حضانت بیضه است، وی را بسیار ببازی گیرد، بحدی که تخمها را میشکند، و از این رو است که تخم طاوس را زیر ماکیان نهند، ماکیان نیزتاب و توان آنکه بیش از دو دانه از تخم طاوس را حضانت کند ندارد، و در آن مدت که تخم طاوس تحت حضانت ماکیان است باید همگی وسائل آسایش ماکیان را از خوراکی و آشامیدنی و غیره فراهم سازند، و الا بیم آن است که ماکیان ترک حضانت کند، و بر اثر تصرف هوای نامناسب بیضه ها فاسد و تباه گردد. جوجه ای که بعد از اتمام ایام حضانت بیرون می آید، خوش شکل نیست، و ناقص الخلقة است، حتی از حیث جثه هم ناقص باشد، مدت حضانت بیضه ٔ طاوس سی روز است . جوجه ٔ طاوس مانند جوجه ٔ ماکیان بمجردبیرون آمدن از غلاف تخم، پوشیده از پر و جوینده ٔ روزی است . یکی از شعرا در وصف این مرغ نیک سروده است :<br />سبحان من من خلقةالطاوس <br />طیرعلی اشکاله رئیس <br />کانه فی نقشه عروس <br />فی الریش منه رکبت فلوس <br />تشرق فی داراته شموس <br />فی الرأس منه شجر مغروس <br />کانه بنفسج یمیس <br />او هوز هر حرم یبیس <br />و شگفت آن است که این پرنده را با حسن و زیبائی که دارد، به فال بد گیرند، و شاید سبب آن باشد که مسبب دخول ابلیس را در بهشت طاوس دانسته اند، و خروج ابوالبشر را از بهشت نیز به وی نسبت دهند، و گویند چون آن حضرت در تمامی مدت زندگانی، از خانه و بنگاه زاد و نژاد و سرای جاودانی خویش آواره گشت، نگاهداری این مرغ درخانه از یمن و برکت دور و قرین شآمت باشد. تفصیل این اجمال آنکه : گویند هنگامی که حضرت آدم علیه السلام در بهشت درخت رز را کاشت، ابلیس در پای آن درخت طاوسی را سربرید، و آن درخت از خون طاوس مشروب شد، همین که درخت آغاز برگ برآوردن کرد، ابلیس میمونی را در بیخ درخت رز ذبح کرد، و آن درخت از خون میمون نیز سیراب گشت، چون هنگام فرا رسیدن انگور شد، ابلیس شیری رادر پای ریشه ٔ آن درخت بکشت، و درخت رز از خون شیر هم آبیاری شد، انگور که به کمال پختگی رسید، ابلیس خوکی را برپایه ٔ آن درخت بیجان کرد، درخت از خون خوک نیز آب خورد، از این رو میخوارگان را هنگام نوشیدن می خوی هر چهار حیوان عارض شود، چه همین که اثر شراب در عروق سرایت کند چهره ٔ آدمی در آغاز برافروخته و چون طاوس رنگین شود، و چون مستی شروع شود، آدمی به رقص و دست و پای کوفتن و بازی گراید، همچون کپی، و چون مستی شدت یابد، خوی شیر و درندگان در وی ظاهر گردد، که نخست با شکار خود بازی کند، و سپس عربده آغازد، وزان پس به بیهوده و هذیان مشغول شود، و در پایان او را رخوتی سخت رخ دهد و چون جسدی بی روح در خواب رود، و رشته ٔ زندگانیش گسیخته گردد. (حیاةالحیوان ). خواندمیر در حبیب السیر آرد: در رسالة الصید مسطور است که از عجائب آنکه طاوس نر و ماده با یکدیگر مجامعت ننمایند، مگر آنکه طاوس نر مست شود، در گرد چشم وی اشکی پدید آید، و طاوس ماده او را بخورد، و این معنی سبب بیضه نهادن وی گردد. اما راقم حروف از نظام الدین علیشیر که طاوس بسیار داشت استماع نمود، به کرات میفرمود که ما چند نوبت جفت شدن طاوس را بسان زوجیت خروس و ماکیان مشاهده کرده ایم . (ج <span class=\"hlight\" dir=\"rtl\">٢</span> حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">٤٢٢</span>). بدیعی در اختیارات آورده که شریف گوید: طاوس بعد از سه سال تمام پرها برآورده باشد، و هر سال یکبار بچه آورد، و این مؤلف گوید عمر طاوس بیست سال بود، و در آن مدت بچند لون برآید، و هر سال وقت خزان پر بیندازد، و در وقت برگ برآوردن درخت وی نیز پر برآورد. شیخ الرئیس گوید در مکانی که طاوس بود، حشرات و هوام نبود، و گوشت و پیه وی مجامعت را قوت دهد، زهره ٔ وی چون با سرکه بیامیزند گزندگی جانوران را سودمند بود، و گوشت و پیه او چون با سفید باج بپزند و مرق آن بخورند، ذات الجنب را نافع بود. جالینوس گوید گوشت بد دارد، و مزاج انسان را موافق نبود. و صاحب جامع از قول صاحب منهاج آورده که نیکوترین آن جوان بود، طبیعت آن گرم و خشک بود، و موافق معده ای بود که هاضمه ٔ وی قوی بود، و اولی آن بود که بعد از کشتن، دو یا سه روز رها کنند، و سنگی در پای وی بندند و بیاویزند، و بعد از آن با سرکه بپزند. ابن زهر گوید که اطباء ماتقدم مرغهائی که گوشت ایشان صلب بودی، یک ساعت پیش از پختن کشته، و همچنان با پر آویخته اند، و این از بهر آن کرده اند که تا زود هضم شود، و چون زمانی درنگ کنند، مانند خمیر که در آرد اندازند تا هضم نان نیکوتر بود، این همچنان است . رازی گوید: طعامی که سمی در وی بود چون طاوس بیند، رقص کند و فریاد دارد. ابن زهر گوید: اگر مبطون زهره ٔ وی با سکنجبین و آب گرم بیاشامد شفا یابد، و اگر خون وی با انزروت و نمک بیامیزند و بر ریشهای بد نهند که ترسند که آزار کند و به آکله رسد، زایل کند، و سرگین وی بر ثآلیل طلا کردن زایل کندو اگر استخوان وی بسوزند و سحق کنند و بر کلف طلا کنند نافع بود، و اگر بر برص مالند، لون آن را بگرداند. (اختیارات بدیعی ). ضریر انطاکی در تذکره آورده که چون طاوس نر دم خویش بیند، اندوه خورد که چرا سایر اندام وی برنگینی دم نیست . درازای دُم وی چندین ذراع است، جثه ٔ نر از جثه ٔ ماده بزرگتر باشد، قوای وی از حین بیرون آمدن از تخم تا سه سال تدریجاً تکمیل گردد. گوشت وی قاطع قولنج و ریاح غلیظه است، مفاصل را تسکین دهد، ولو بطریق نطول به کار برند. (تذکره ٔ داود ضریر انطاکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٤</span>). طلای زهره ٔ او با سرکه جهت گزیدن هوام، و شرب زیره ٔ او بقدر دو دانگ با سکنجبین و آب گرم رفع اسهال کند، و بالخاصیة رؤیت او باعث ضعف قوه ٔ سموم مسمومین است . و حکمای هند تحقیق کرده اند که چون موی دنباله ٔ او را در کوزه کرده بسوزانند، از صد مثقال آن قریب به یک مثقال فلزی شبیه بطلا بهم میرسد، و در دفع کردن بیاض عین و امراض آن مجرب دانسته اند، و خواص غریبه و عجیبه به آن اسناد میدهند. (تحفه حکیم مؤمن ) <span class=\"hlight\">:</span> <br />چرا عمر طاوس و دراج کوته <br />چرا مار و کرکس زید در درازی .<br /> <font color=\"Red\">ابوالطیب مصعبی .</font><br />از خراسان بردمد طاوس فش <br />سوی خاور میشتابد شاد و کش .<br /> <font color=\"Red\">رودکی .</font><br />و اندر دشتها و بیابان وی <font color=\"DarkGreen\"><b>[ هندوستان ]</font></b> جانوران گوناگون اند چون پیل و گرگ و طاوس و گرگری و طوطک و شارک، و آنچه بدین ماند. (حدودالعالم ).<br />صد اشتر ز گنج و درم کرد بار<br />ز دینار پنجه ز بهر نثار<br />به مریم <font color=\"DarkGreen\"><b>[ دختر قیصر ]</font></b> فرستاد چندی گهر<br />یکی نغز طاوس کرده بزر.<br /> <font color=\"Red\">فردوسی .</font><br />ز مادر جدا شد چو طاوس نر<br />به هر موی بر تازه رنگی دگر.<br /> <font color=\"Red\">فردوسی .</font><br />پس و پیش ترکان طاوس رنگ <br />چپ و راست شیران پولادچنگ .<br /> <font color=\"Red\">فردوسی .</font><br />بیت اخیررا شعوری در جلد اول فرهنگ خود بنام فردوسی آورده است، ولی در شاهنامه ٔ طبع ولف نیست .<br />بدیبا زمین کرده طاوس رنگ <br />ز دینار و دیبا چو پشت پلنگ .<br /> <font color=\"Red\">فردوسی .</font><br />ز پستان آن گاو طاوس رنگ <br />برافراختی چون دلاور نهنگ .<br /> <font color=\"Red\">فردوسی .</font><br />بایتکین ...با خویش صدوسی تن طاوس آورده بود که بیشتر در گنبدها بچه آوردندی . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٠٨</span>). آنجا نیز حصاری بود، و بسیار طاوس و خروس بودی، من ایشان رامیگرفتمی . (تاریخ بیهقی ). فرمود تا از آن طاوسان ...با خویشتن آرم، و چند جفت برده آید. (تاریخ بیهقی ).<br />دم هر طوطیکی چون ورق سوسن تر<br />باز چون دسته ٔ سوسن دم هر طاوسی .<br /> <font color=\"Red\">منوچهری .</font><br />طاوس مدیح عنصری خواند<br />دراج مسمط منوچهری .<br /> <font color=\"Red\">منوچهری .</font><br />ماند بسینه و دم طاوس شاخ گل <br />چون مشک و در و دانه درو بر پراکنی .<br /> <font color=\"Red\">منوچهری .</font><br />طاوس میان باغ دمان و کشی کنان <br />چنگش چو برگ سوسن و پایش چو برگ نی .<br /> <font color=\"Red\">منوچهری .</font><br />از دم طاوس نر ماهی سر بر زده ست <br />دستگکی مورد تر گوئی بر پر زده ست .<br /> <font color=\"Red\">منوچهری .</font><br />سراسر بطاوس مانید نر<br />که جز رنگ چیزی ندارد دگر.<br /> <font color=\"Red\">اسدی .</font><br />شاخ گل بود بباغ اندر هنگام بهار<br />خوب و آراسته ماننده ٔ طاوسی نر.<br /> <font color=\"Red\">لامعی .</font><br />نگاه کن که بحیلت همی هلاک کنند<br />ز بهر پر نکو طاوسان پرّان را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />طاوس خواستندت می آفرید از اول <br />طاوس مردمی تو ایدون همی نمائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نگویم که طاوس نرّ است گلبن <br />که گلبن همی زین سخن عار دارد<br />نه طاوس نر از وشی پرّ دارد<br />نه از سرخ یاقوت منقار دارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />آتش دعوت می افروخت، و خود را چون طاوس نر بر نظارگان میفروخت . (مقامات حمیدی ).<br />شبه طاوس شمر فقرکه طاوسان را<br />رنگ زیباست گر آواز نه زیبا شنوند.<br /> <font color=\"Red\">خاقانی .</font><br />بیضه چون طاوس نر خواهم شکست <br />وز برون آشیان خواهم شکست .<br /> <font color=\"Red\">خاقانی .</font><br />دفع سرما را قفس کردند آهن پس در او<br />بچّه ٔ طاوس علوی آشیان افکنده اند.<br /> <font color=\"Red\">خاقانی .</font><br />بر سر خوان جهان خرمگسانند طفیل <br />پر طاوس مگس ران بخراسان یابم .<br /> <font color=\"Red\">خاقانی .</font><br />طاوس بین که زاغ خورد و آنگه از گلو<br />گاورس ریزه های منقّا برافکند.<br /> <font color=\"Red\">خاقانی .</font><br />مگس ران کردن از شهپرّ طاوس <br />عجب زشت است بر طاوس زیبا.<br /> <font color=\"Red\">خاقانی .</font><br />خود باش انیس خود مطلب کس که پیل را<br />هم گوش بهتر از پر طاوس پشّه ران .<br /> <font color=\"Red\">خاقانی .</font><br />گیتی ز گرد لشکرش طاوس بسته زیورش <br />در شرق رنگین شهپرش در غرب منقار آمده .<br /> <font color=\"Red\">خاقانی .</font><br />بیضه بشکن مرغ کم کن تا بوی طاوس نر<br />بیضه پروردن بگنجشکان گذار و ماکیان .<br /> <font color=\"Red\">خاقانی .</font><br />رهبر دیو چو طاوس مدام <br />مایه ٔ فسق چو عصفور مقیم .<br /> <font color=\"Red\">خاقانی .</font><br />از مصحف گردون ار پنج آیت زر کم شد<br />آمد پر طاوسش دیدار بصبح اندر.<br /> <font color=\"Red\">خاقانی .</font><br />دشمنان سر بزرگش را چو بوم <br />حاصل از طاوس دولت پای باد.<br /> <font color=\"Red\">خاقانی .</font><br />طاوس بوده ام بریاض ملوک وقتی <br />امروز پای هست مرا و پری ندارم .<br /> <font color=\"Red\">خاقانی .</font><br />از عارض و روی و زلف داری <br />طاوس و بهشت و مار با هم .<br /> <font color=\"Red\">خاقانی .</font><br />به دست همت از خاطر برانم غم که سلطانان <br />مگس رانها کنند از پرّ طاوسان بستانی .<br /> <font color=\"Red\">خاقانی .</font><br />جوهر حسن به هر خس چه برم <br />پر طاوس مگس ران چه کنم .<br /> <font color=\"Red\">خاقانی .</font><br />باغی است طاوس رخش ماریست افسونگر در او<br />شهری چو من بنهاده سر بر حفظ آن افسون نگر.<br /> <font color=\"Red\">خاقانی .</font><br />پیش که طاوس صبح بیضه ٔ زرّین نهد<br />از می بیضا بساز بیضه مجلس ارم .<br /> <font color=\"Red\">خاقانی .</font><br />چو طاوس خورشید بگشاد بال <br />زراندود شد لاجوردی هلال .<br /> <font color=\"Red\">نظامی .</font><br />چو طاوس فلک بگریخت از باغ <br />به گل چیدن بباغ آمد سیه زاغ .<br /> <font color=\"Red\">نظامی .</font><br />هنر بیند چو عیب این چشم جاسوس <br />تو چشم زاغ بین نه پای طاوس .<br /> <font color=\"Red\">نظامی .</font><br />در پر طاوس که زرپیکر است <br />سرزنش پای کجا درخور است .<br /> <font color=\"Red\">نظامی .</font><br />گر آید نارپستانی در این باغ <br />چو طاوسی نشسته بر پر زاغ .<br /> <font color=\"Red\">نظامی .</font><br />چو طاوسی عقابی بازبسته <br />تذروی بر لب کوثر نشسته .<br /> <font color=\"Red\">نظامی .</font><br />و معلوم شد که جگر بط، چون پر طاوس و بال او آمد. (مرزبان نامه ).<br />اگر زشتخوئی بود در سرشت <br />نبیند ز طاوس جز پای زشت .<br /> <font color=\"Red\">سعدی .</font><br />وز لطافت که هست در طاوس <br />کودکان میکنند بال و پرش .<br /> <font color=\"Red\">سعدی .</font><br />پر طاوس در اوراق مصاحف دیدم <br />گفتم این منزلت از قدر تو می بینم بیش .<br /> <font color=\"Red\">سعدی .</font><br />دوش چون طاوس مینازیدم اندر باغ خلد<br />دیگر امروز از فراق یار می پیچم چو مار.<br /> <font color=\"Red\">سعدی .</font><br />ازین مه پاره ٔ عابدفریبی <br />ملایک صورتی طاوس زیبی .<br /> <font color=\"Red\">سعدی .</font><br />چو طاوس را خانه شد بوستان <br />دگر یاد نارد ز هندوستان .<br /> <font color=\"Red\">امیرخسرو.</font><br />کمال جلوه ٔ طاوس را از آن چه زیان <br />که ابلهی بگزیند غراب بر طاوس .<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاوس آتش پر یا طاوس آتشین پر</span> ؛ کنایه از آفتاب عالمتاب است . (برهان ) (آنندراج ).<br />در آبگون قفس بین طاوس آتشین پر<br />کز پر گشادن او آفاق بست زیور.<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاوس پران اخضر</span> ؛ کنایه از فرشتگان است . ستارگان را نیز گفته اند. (برهان ) (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاوس ِ مشرق خرام </span> ؛ کنایه ازآفتاب است . (برهان ) (آنندراج ).<BR>۩ آسمان را نیز گویند. (برهان ) (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">شب خرکرّه طاوس نماید</span>، نظیر: شب گربه سمور مینماید. هر چیز هنگام شب خوشنماتر باشد.<br /><span class=\"hlight\">مثل طاوس </span> ؛ رنگین و آراسته <span class=\"hlight\">:</span> <br />اندرین ملک چو طاوس بکار است مگس، نظیر: که هر چیزی بجای خویش نیکوست .<br /> <span class=\"hlight\">مثل طاوس در خانه ٔ روستائی </span> ؛ چیزی گرانبها در تصرّف مردی بینوا <span class=\"hlight\">:</span> <br />نماید همی مدح من نزد هر کس <br />چو طاوس در خانه ٔ روستائی .<br /> <font color=\"Red\">کریمی سمرقندی .</font><br /> <span class=\"hlight\">مثل طاوس مست </span> ؛ که مانند طاوس نَر در حال طاق بستن بخود نگرد، و متکبّرانه گذرد.<br /> <span class=\"hlight\">هر کرا طاوس باید، جور هندوستان کشد</span>، نظیر: گنج بیرنج مُیسر نشود. تن آسانی بدون تحمل رنج و مشقت فراهم ناید.<br /><BR><font color=\"Blue\">◄</font> (ص ) مردخوبروی به لغت شام . <BR><font color=\"Blue\">◄</font> (اِ) سیم . (منتهی الارب ) (آنندراج ). نُقره به لغت اهل یمن . (دهار). فِضة. <BR><font color=\"Blue\">◄</font> زمین سبز با هرگونه گیاه . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> آلتی از ذوی الاوتار است در هندوستان .<br /></font></div>'),
(175606, 'طاوس', '<span class=\"hlight\">طاوس .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِخ ) یکی از ابنیه و آثار سلاطین صفویه در شهر اصفهان .<br /></font></div>'),
(175607, 'طاوس', '<span class=\"hlight\">طاوس .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِخ ) موضعی است در نواحی بحر فارس، که غُلاّب حضرمی مالک آنجا بود، از طریق دریا لشکری بدان جای گسیل کرد، چون خلیفه ٔ وقت (عمربن الخطاب ) اجازه ٔچنین امری بدو نداده بود، بر او خشم گرفت . و او را از شغل بازداشت، او نیز شبانگاه بسوی کوفه نزد سعدبن ابی وقاص که از یارانش بود شد، سعد نیز او را معاضدت میکرد تا آنکه در ذی قار کشته شد. (معجم البلدان ).<br /></font></div>'),
(175608, 'طاوس', '<span class=\"hlight\">طاوس .</span> <font color=\"DarkGreen\"><b>[وو ]</font></b> (اِخ ) نام جد ابوحنیفه نعمان بن ثابت بن طاوس بن هرمزدبن ملک بن شیبان است . نام طاوس به روایتی مرزبان بود علمدار مرتضی علی رضی اﷲ عنه و امیرالمؤمنین علی کرم اﷲ وجهه در حق او دعا کرد بارک اﷲ فیک و فی نسلک بدان برکت این مرتبه یافت . (تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٧٥٦</span>).<br /></font></div>'),
(175609, 'طاوس', '<span class=\"hlight\">طاوس .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِخ ) نام مادر المستنجد باﷲ ابوالمظفر یوسف بن المقتفی . از خلفای عبیدیان (فاطمیان ) زنی گرجی بوده است . رجوع به تاریخ الخلفا ص <span class=\"hlight\" dir=\"rtl\">٢٩٣</span> شود.<br /></font></div>'),
(175610, 'طاوس', '<span class=\"hlight\">طاوس .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِخ ) معاصر عمربن عبدالعزیز که در ده کلمه به عمربن عبدالعزیز موعظه کرده است . رجوع به سیرة عمربن عبدالعزیز ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span> شود.<br /></font></div>'),
(175611, 'طاوس', '<span class=\"hlight\">طاوس .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِخ )نام زوجه ٔ اصفهانی فتحعلیشاه قاجار که وی تخت طاوس دوم را بنام وی ساخته است .<br /></font></div>'),
(175612, 'طاوس', '<span class=\"hlight\">طاوس .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِخ )یکی از سرداران عظیم الشأن دوره ٔ تیموری، که بر امیرتیمور یاغی شد، و در سال <span class=\"hlight\" dir=\"rtl\">٧٩٧</span> هَ . ق . به امر و فرمان آن صاحبقران بقتل رسید. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٠</span>).<br /></font></div>'),
(175613, 'طاوس', '<span class=\"hlight\">طاوس .</span> <font color=\"DarkGreen\"><b>[وو ]</font></b> (اِخ ) دهی از بخش میان کنگی شهرستان زابل . در ده هزارگزی شمال باختری ده دوست محمد و سه هزارگزی خاوری راه مالرو برج میرگل به ده دوست محمد. جلگه و گرم و معتدل . با <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه . آب آن از رودخانه ٔ هیرمند. محصول آن غلات و لبنیات . شغل اهلی زراعت و گله داری و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175614, 'طاوس', '<span class=\"hlight\">طاوس .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِخ ) ابن احمد. کنیت وی ابوالحسن، و محدّث است .<br /></font></div>'),
(175615, 'طاوس', '<span class=\"hlight\">طاوس .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِخ ) ابن کیان . از تابعین بود. (تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٨٤٧</span>).<br /></font></div>'),
(175616, 'طاوس', '<span class=\"hlight\">طاوس .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِخ ) ابن مکحول . حمداﷲ مستوفی او را ازصحابه شمرده است . رجوع به تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٢٣١</span> شود.<br /></font></div>'),
(175617, 'طاوس آبگون خضرا', '<span class=\"hlight\">طاوس آبگون خضرا.</span> <font color=\"DarkGreen\"><b>[ وو س ِ ن ِ خ َ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از آسمان است . (مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(175618, 'طاوس آتش پر', '<span class=\"hlight\">طاوس آتش پر.</span> <font color=\"DarkGreen\"><b>[ وو س ِ ت َ پ َ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از آفتاب است و آن را طاوس مشرق خرام نیز گویند. (انجمن آرای ناصری ). کنایه از آفتاب عالمتاب . (برهان ). و رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">١٣</span> شود.<br /></font></div>'),
(175619, 'طاوس الحرمین', '<span class=\"hlight\">طاوس الحرمین .</span> <font color=\"DarkGreen\"><b>[ وو سُل ْ ح َ رَ م َ ]</font></b> (اِخ )حمداﷲ مستوفی در ذیل کلمه ٔ ابرقو گوید: و از مزار اکابر در آنجا طاوس الحرمین است، و آن تربت را خاصیتی هست که اگر مسقف میگردانند خراب میشود، تا بمرتبه ای که سایبان کرباس نیز نمیپذیرد. (نزهة القلوب چ لیدن مقاله ٔ <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span>) و رجوع به تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٧٩٣</span> شود.<br /></font></div>'),
(175620, 'طاوس جمال', '<span class=\"hlight\">طاوس جمال .</span><font color=\"DarkGreen\"><b>[ وو ج َ ]</font></b> (ص مرکب ) بزیبائی طاوس . بجمال طاوس <span class=\"hlight\">:</span> تا غزالی صید کند یا طاوس جمالی در قید آرد.<br />(سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٢٥٩</span>).<br /></font></div>'),
(175621, 'طاوس خرام', '<span class=\"hlight\">طاوس خرام .</span> <font color=\"DarkGreen\"><b>[ وو خ ِ <span class=\"hlight\" dir=\"rtl\">/</span> خ َ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ ]</font></b> (ص مرکب ) خرامنده چون طاوس . با رفتار طاوس .<br /></font></div>'),
(175622, 'طاوس خلد', '<span class=\"hlight\">طاوس خلد.</span> <font color=\"DarkGreen\"><b>[ وو س ِ خ ُ ]</font></b> (ترکیب اضافی، اِمرکب ) کنایه از حور و غلمان بهشتی باشد. (برهان ).<br /></font></div>'),
(175623, 'طاوس دم', '<span class=\"hlight\">طاوس دم .</span> <font color=\"DarkGreen\"><b>[ وو دُ ]</font></b> (ص مرکب ) که دمی چون طاوس دارد <span class=\"hlight\">:</span> <br />ز حلق خروسان طاوس دم <br />فروریخت در طاسها خون خم .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175624, 'طاوس رنگ', '<span class=\"hlight\">طاوس رنگ .</span> <font color=\"DarkGreen\"><b>[ وو رَ ]</font></b> (ص مرکب ) هر رنگ که به طلائی زند. به رنگ طاوس . مطوّس <span class=\"hlight\">:</span> <br />ز پستان آن گاوطاوس رنگ <br />برافراختی چون دلاور پلنک .<br /> <font color=\"Red\">فردوسی .</font><br />نشستنگه رود و می ساختند<br />ز بیگانه خرگه بپرداختند<br />بدیبا زمین کرده طاوس رنگ <br />ز دینار و دیبا چو پشت پلنگ .<br /> <font color=\"Red\">فردوسی .</font><br />ز دیبا در و دشت طاوس رنگ <br />دم نای هر جای و آواز چنگ .<br /> <font color=\"Red\">اسدی .</font><br />پس و پیش ترکان طاوس رنگ <br />چپ و راست شیران پولادچنگ .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175625, 'طاوس زیب', '<span class=\"hlight\">طاوس زیب .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (ص مرکب ) به زیور طاوس <span class=\"hlight\">:</span> <br />ازین مه پاره ٔ عابدفریبی <br />ملایک صورتی طاوس زیبی .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(175626, 'طاوس سمنانی', '<span class=\"hlight\">طاوس سمنانی .</span> <font color=\"DarkGreen\"><b>[ وو س ِ س ِ ]</font></b> (اِخ ) خواجه قطب الدین طاوس سمنانی . بنا بروایت مؤلف دستورالوزراء، در دارالوزاره ٔ سمنان، دو قبیله از سایر متوطنان آن ممتاز بعلوّ دودمان میباشند، یکی بهرامی که نسب آنان به بهرام گور می پیوندد، دیگری بالیجه که همواره مورد قبول عامه، و پناه خرد و بزرگ بوده اند. پدر خواجه از اکابر قوم بهرامی، و مادرش دختر یکی از اعاظم قوم بالیجه بود، و همچنانکه به قوت نسب معروف بود به کثرت حسب نیز موصوف و در سلک اعاظم ارباب قلم، و اصحاب کرم انتظام داشت . در زمان سلطنت میرزا ابوالقاسم بابر، قدم بر مسند وزارت نهاد، در مدت وزارت به دادگستری و رسیدگی به مهام کشور، و دادخواهی لشکری و کشوری، کوشش میکرد. میرزا بابر نیز بااو بیش از همگنان نظر لطف و عنایت داشت، خواجه نوبتی جهت رعایت نام و ناموس، تقریبی انگیخته استدعای حضور میرزا بابر کرده، جشنی پادشاهانه طرح انداخت، بابر ملتمس خواجه را بشرف اجابت اقتران داده، بخانه ٔ آن جناب تشریف قدوم شریف ارزانی فرمود، خواجه بمراسم نثار و نیاز پرداخته، مبلغ سی هزار دینار کپکی ساچق نمود، و از اشربه و اطعمه، و حلوا و فواکه، بیش از حد شمار در آن طوی بنظر درآورد، و در آن روز، خواجه امرا و ارکان دولت را نیز خدمات شایسته نموده، میرزابابر نیز آن وزیر عالی همت را، به انواع انعام و عنایت مفتخر کرد، علاوه ولایت سمنان را برسم سیورغال بدان جناب ارزانی فرمود، و مادام که آن مملکت داخل در حوزه ٔدیوان میرزا بابر بود بدون خلل و نقصان در تصرف آن صاحب آصف نشان میبود، و هیچکس خیال دخل در آن نتوانستی کرد. بعد از فوت میرزابابر، چون سلطان سعید، میرزاسلطان ابوسعید مملکت خراسان را تسخیر فرمود، ایضاً پرتو عنایت بر وجنات حال آن خواجه انداخته، منصب وزارت را بدان جناب تفویض فرمود، و خواجه از روی عدالت وانصاف بتمشیت آن مهم پرداخته، جناح مرحمت و احسان بر مفارق رعایا و مزارعان که ودائع ایزدی اند بگسترد، و به فراغ بال در تکثیر زراعت و عمارت کوشیده، به دانه ٔ انعام و اکرام، مرغ دل خواص و عوام صید کرد، سلطان سعید را نسبت بدان خواجه التفات و عنایت بی انتها پیدا شد، مرتبه ٔ آن جناب از سایر وزراء درگذشت، لاجرم نائره ٔ بغض و حسد در کانون درون همگنان اشتعال یافته، نزد پادشاه، وزیر را بتصرف در اموال متهم داشتند، تا معزول گشت، اما هم در آن اوان حقیقت سخن غرض خواهان، بر ضمیر خورشیدنشان روشن شده، کرت دیگر شغل وزارت به خواجه ٔ پسندیده سیر تفویض افتاد. راقم حروف از بعضی مردم صادق القول استماع نمود که گاهی سلطان سعید، در باب انتظام امور ملک و ملت، و ارتسام قواعد دین و دولت، به عالیجناب، ولایت قباب عوارف اکتساب، المتوجه بالکلیة الی اﷲ، شیخ کمال الملة و الدّین، محمدشاه، که انتساب به ولایت فراه داشتند، مطارحه نمودند، رای آن عالیجناب را بقبول مقرون میفرمود، و در ایام عزل خواجه قطب الدّین طاوس، سبب رفاهیت و جمعیت مخلوقات از ایشان استفسار نمود، حضرت شیخ، بزبان ولایت نشان، نام خواجه عالیشان، بردند، و نوبت دیگر عنان اختیار او را به دست تربیت آن پادشاه سپردند، و اگر چه خواجه از تصدی مُهم ّ وزارت در مقام اعتذار بود، ابواب مخالفت با جناب ولایت منقبت نتوانست گشود ضرورت، ثانیاً آن منصب را قبول نمود، و این نوبت بیشتر از پیشتر منظور نظر همایونی گشت، و منزلتش از مرتبه ٔ وزرای زمانش درگذشت، و از رهگذر درویشی و نیک اندیشی، اعتبار و اختیار بسیار یافت، و به همگی همت، و جملگی نهمت عنان اهتمام بصوب زراعت و دهقنت تافت، چنانکه در ولایت خراسان، هر سال هفت هزار خروار تخم در زمین پاشید، و ظاهراً تخم کشت . هیچیک از وزراء در یک مملکت، هرگز بدین مرتبه نرسید. رشحه ای از بحر آثار آن خواجه، جوی سلطانی است که در جانب شمال دارالسطنه ٔ هرات، ازرود باشتان سمت جریان یافته، و بدان واسطه چندین هزار باغ و بستان و حظیره، در گازرگاه و دامن کوه زنجیرگاه، و مختار، تا چشمه ٔ ماهیان، از خارستان عدم، به گلزار وجود شتافته . هر یک در نضارت نظیر ریاض رضوان، و در خضارت غیرت افزای ساحت آسمان . نقل است که چون خواجه قطب الدین طاوس کمال توجه خاطر سلطان سعید را به جریان آن آب معلوم کرده بود، قرب دویست نفر برزیگرو چاهجو که هر یک فرهادصفت جوی در بیستون کندی و بنوک تیشه خارانگار رخنه در دل سنگ افکندی، از مزارع خود آورد، و آن جماعت مدّت دو سال در آن کار مشقت کشیدند، تا آخر آب امانی و آمال، در جویبار دولت و اقبال جاری دیدند، و چون آب در جریان آمده بدامن کوه مختار رسید، خواجه مقداری در ظرفی کرده، مصحوب تواجی (؟) به اردوی همایون که در آن زمان متوجه عراق بود ارسال نمود، در آن محل که چشم سلطان بر آن آب افتاد، مراسم شکر فیاض علی الاطلاق بجای آورده، زبان به ادای این سخنان بگشاد که احداث جوی سلطانی نزد من بر فتح عراق ترجیح دارد، زیرا که بدان سبب شمال دارالسلطنه ٔ هرات روی بکمال معموری و آبادانی می آورد. و فی الواقع:<br />نسیم خلد و عمر خضر می بخشد اگر دانی <br />هوای دشت گازرگاه و آب جوی سلطانی .<br />القصه بنابر حدوث این جوی که به یمن سعی و اهتمام خواجه بوقوع انجامید میرزاسلطان ابوسعید، در ازدیاد مرتبه ٔ وزیر کوشیده، پایه ٔ قدر و منزلتش را بلندتر گردانید، و فرامین مطاعه مشتمل بر وفور مرحمت و عاطفت نسبت بخواجه، و مبنی از آنکه لشکر پیاده ٔ خراسان را فراهم آورده، به موکب همایون ملحق شود، به دارالسلطنه ٔ هرات رسید، خواجه بموجب فرموده عمل نموده، بر اسب مراد سوار گشته، با سپاه پیاده متوجه ملازمت شاه عالم پناه گردید، در اثنای راه بجمعی از مخالفان که فرزین وار کج روی پیشه داشتند، دچار خورده به خیال محال رایت جنگ و پیکار افراشتند، خواجه پای ثبات فشرده، به عنایت حق بر مخالفان ظفر یافت، منصور و مظفر طی ّ منازل و مراحل نموده، بخدمت پادشاه شتافت، و بعد از وصول بپایه ٔ سریر اعلی، کیفیت محاربه ٔ مخالفان را بعرض رسانید، و میرزاسلطان ابوسعید مراسم عنایت مبذول داشته وزیر صافی ضمیر را ملقب به صاحب السیف و القلم گردانید، و زمام سرانجام مهام ولایات عراق را، به کف اهتمام آن جناب بازداده، مهر بزرگ را بدو تسلیم نمود که حیث یشاء امور جمهور برایا را بکف ّ کفایت مقرون سازد، و لوای عدالت آن حضرت را، بر فرق آفتاب نشینان بلاد ظلم تراکمه برافرازد. و بعد از آنکه سلطان سعید در قراباغ ارّان ویران شده به حکم امیر حسن بیک ترکمان جهان گذران را وداع کرد، همای همت خواجه از وزارت حسن بیک ابا نموده، بر جناح استعجال روی توجه به جانب خراسان آورد. چون ماهچه ٔ لوای فرقدفرسای سلطان عالیشأن سلطان حسین میرزا نوبت اول، آفتاب صفت مرز و بوم خراسان را منوّر گردانید خواجه پسندیده اوصاف به منصب اشراف وزراء که عبارت از رتبه ٔ واسطة العقدی بین الامراء و الوزراء است، مشرّف گردید و در اواخر ذی الحجه ٔ سال <span class=\"hlight\" dir=\"rtl\">٨٧٤</span> هَ . ق . که میرزا یادگار، محمدبن میرزا سلطان محمدبن میرزا بایسنغر، بمدد امیرحسن بیک بهادر خطه ٔ خراسان را تسخیر نمود، پرتو عنایت و التفات، بر وجنات احوال خواجه انداخته، منصب وزارت دیوان را بدان جناب تفویض فرمود، اما تا زمان سلطنت میرزا یادگار محمد، مانند دوران گل، زیاده از چهل روزممتد نگشت . و سلطان صاحبقران ابوالغازی، سلطان حسین میرزا ناگهان نیم شبی در باغ زاغان بر سر آن پادشاه تاخته، بصرصر سیاست، بساط حکومتش درنوشت . و چون خواجه ثانیاً در زمان سلطنت سلطان صاحبقران مشمول لطف و احسان شد، اما هر چند او را بر تکفل مهمات دیوانی تحریض فرمودند، از آن مهام تحاشی نموده، پیرامن حواشی آن مهام نگشت، و به اختیار از سر قبول منصب و حکومت درگذشت، چند سال در دارالسلطنه ٔ هرات، حُمیت عن آلافات، به فراغ بال بگذرانید، و دامن همت از شغل وزارت درچید، خود را بزراعت و عبادت، مشغول گردانید، و در آن سال که خواجه مجدالدین محمد، قدم بر مسند جاه و جلال نهاده، بنابر طمع اموال نسبت بخواجه ٔ ستوده خصال، ابواب نزاع و جدال بگشاد، خواجه از ازاله ٔ عرض و ناموس اندیشیده، عنان عزیمت بصوب عراق و آذربایجان منعطف گردانید و در آن مملکت نیز معزّز و محترم بود و تتمه ٔ اوقات حیات را بپایان آورد، و در سال نُهصد که سن ّ شریفش بهفتاد و دو سال رسید، بحکم «کُل ّ نفس ذائقةالموت » (قرآن <span class=\"hlight\" dir=\"rtl\">١٨٥/٣</span> و <span class=\"hlight\" dir=\"rtl\">٣٥/٢١</span> و <span class=\"hlight\" dir=\"rtl\">٥٧/٢٩</span>). گوش هوشش صفیر عقاب اجل شنید، و مرغ روح مطهرش قفص قالب شکست :<br />همانجا پرّ طاوسی بینداخت <br />جهان از فرّ کاوسی بپرداخت <br />بدنیا خواه سلطان، خواه درویش <br />همه کس را همین راه است در پیش .<br /><font color=\"Red\">(دستورالوزراء صص <span class=\"hlight\" dir=\"rtl\">٣٩٥</span> - <span class=\"hlight\" dir=\"rtl\">٣٨٠</span>).</font><br /></font></div>'),
(175627, 'طاوس علیین', '<span class=\"hlight\">طاوس علیین .</span> <font color=\"DarkGreen\"><b>[ وو س ِ ع ِل ْ لی ]</font></b> (ترکیب اضافی، اِ مرکب ) طاوس بهشتی <span class=\"hlight\">:</span> <br />پس برآمد پوستش رنگین شده <br />که منم طاوس علیین شده .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(175628, 'طاوس فش', '<span class=\"hlight\">طاوس فش .</span> <font color=\"DarkGreen\"><b>[ وو ف َ ]</font></b> (ص مرکب ) طاوس رفتار. طاوس وش .<br /></font></div>'),
(175629, 'طاوس فلک', '<span class=\"hlight\">طاوس فلک .</span> <font color=\"DarkGreen\"><b>[ ووس ِ ف َ ل َ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از آفتاب است، چنانکه زاغ کنایه از سیاهی شب است <span class=\"hlight\">:</span> <br />چو طاوس فلک بگریخت در باغ <br />به گل چیدن بباغ آمد سیه زاغ .<br /> <font color=\"Red\">نظامی .</font><br />طاوس فلک هر شب شد سوخته بال و پر<br />هم شمع رخت سوزد گر بال و پری دارد.<br /><font color=\"Red\">عطار.</font><br /></font></div>'),
(175630, 'طاوس قزوینی', '<span class=\"hlight\">طاوس قزوینی .</span> <font color=\"DarkGreen\"><b>[ وو س ِ ق َزْ ]</font></b> (اِخ ) امام برهان الدین ابراهیم بن محمدبن ابی المکارم قزوینی . او راست : کتاب اربعین .<br /></font></div>'),
(175631, 'طاوس لو', '<span class=\"hlight\">طاوس لو.</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِخ ) دهی از دهستان اوچ تپه بخش ترکمان شهرستان میانه . در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی جنوب ترکمان و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی شوسه ٔ تبریز به میانه . کوهستانی . معتدل . با <span class=\"hlight\" dir=\"rtl\">١٦٠</span> تن سکنه . آب آن از چشمه محصول آنجا غلات و حبوبات . شغل اهالی زراعت و گله داری . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span> و <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(175632, 'طاوس مشرق خرام', '<span class=\"hlight\">طاوس مشرق خرام .</span> <font color=\"DarkGreen\"><b>[ وو س ِ م َ رِ خ ِ <span class=\"hlight\" dir=\"rtl\">/</span> خ َ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از آفتاب است و آسمان را نیز گویند. (برهان ).<br /></font></div>'),
(175633, 'طاوس وار', '<span class=\"hlight\">طاوس وار.</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (ص مرکب، ق مرکب ) مانند طاوس . طاوس خرام . طاوس رفتار <span class=\"hlight\">:</span> <br />در گریه ٔ وداع تذروان کبک لب <br />طاوس وار پای گل آلود می بریم .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(175634, 'طاوس وار رفتن', '<span class=\"hlight\">طاوس وار رفتن .</span> <font color=\"DarkGreen\"><b>[ وو رَ ت َ ]</font></b> (مص مرکب ) نوعی از ورزش کشتی گیران که واژگونه شده خود را مثل طاوس رقصان کنند، و آن رادر عرف هند، مورچال خوانند. (آنندراج ) <span class=\"hlight\">:</span> <br />چتر طاوسی نصیب مرد کشتی گیر نیست <br />گر رود در وقت ورزش صد قدم طاوس وار.<br /> <font color=\"Red\">ملاطغرا.</font><br />بس که عالم گشته سرتاسر بهشت از عدل او<br />کبک در چنگال شاهین میرود طاوس وار.<br /><font color=\"Red\">محمدسعید اشرف (از آنندراج ).</font><br /></font></div>'),
(175635, 'طاوس وش', '<span class=\"hlight\">طاوس وش .</span> <font color=\"DarkGreen\"><b>[ وو وَ ]</font></b>(ص مرکب، ق مرکب ) طاوس رفتار. طاوس خرام <span class=\"hlight\">:</span> <br />از خراسان بردمد طاوس وش <br />سوی خاور میخرامد شاد و کش .<br /> <font color=\"Red\">رودکی .</font><br />همان زنده پیلان گنجینه کش <br />همان تازی اسبان طاوس وش .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175636, 'طاوس پران اخضر', '<span class=\"hlight\">طاوس پران اخضر.</span><font color=\"DarkGreen\"><b>[ وو پ َ ن ِ اَ ض َ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه ازفرشتگان باشد و ستارگان را نیز گفته اند. (برهان ).<br /></font></div>'),
(175637, 'طاوس پیکر', '<span class=\"hlight\">طاوس پیکر.</span> <font color=\"DarkGreen\"><b>[ وو پ َ <span class=\"hlight\" dir=\"rtl\">/</span> پ ِ ک َ ]</font></b> (ص مرکب ) با پیکری چون پیکر طاوس . با اندام زیبا و رنگارنگ <span class=\"hlight\">:</span> <br />دگر ره لعبت طاوس پیکر<br />گشاد از درج لؤلؤ تنگ شکر.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175638, 'طاوس کردار', '<span class=\"hlight\">طاوس کردار.</span> <font color=\"DarkGreen\"><b>[ وو ک ِ ]</font></b> (ص مرکب ) با کردار طاوس . با رفتار طاوس <span class=\"hlight\">:</span> <br />بدین طاوس کرداری همائی <br />روان شد چون تذروی در هوائی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175639, 'طاوس یمانی', '<span class=\"hlight\">طاوس یمانی .</span> <font color=\"DarkGreen\"><b>[ وو س ِ ی َ ]</font></b> (اِخ ) ابن کیسان الخولانی الهمدانی الیمانی اهل یمن و از ابناءالفرس است . یکی از اعلام تابعین بشمار است، از ابن عباس و ابی هریرة استماع حدیث کرده، مجاهد و عمروبن دینار از او روایت کنند، و از طبقه ٔ مالک بن دینار الصوفی و پیروان طریقت اوست . در تلخیص الاَّثار، ذیل لفظ یمن گوید: ینسب الیها، ابوعبدالرحمن طاوس بن کیسان الیمانی کان من اعلم الناس بالحلال والحرام، توّفی بمکة سنة ست ّ و مائة. ابن خلکان گوید: طاوس فقیهی جلیل القدر و نبیه الذکر بود، ابن عیینة گوید: با عبیداﷲبن یزید، ضمن صحبت گفتم با چه کسان نزد ابن عباس شوی ؟ گفت با عطا و یاران او. پرسیدم با طاوس هم ؟ گفت هیهات، او با خواص نزد ابن عباس رود، عمروبن دینار گفته : ندیدم طاوس را مانندی . چون عمربن عبدالعزیز بخلافت رسید طاوس نامه بدین مضمون بدو نبشت که اگر خواهی دانش تو همگی و تمامیش خیرباشد، مردمان خیر و اهل خیر بر کارها بگمار. چون عمر نامه را خواند گفت اگر پند است همین اندرز مرا بسنده باشد. زمانی که بزیارت خانه ٔ خدا رفته بود پیش ازروز ترویه بدار آخرت شتافت، هشام بن عبدالملک بر او نماز خواند، و این واقعه در سال <span class=\"hlight\" dir=\"rtl\">١٠٦</span> هَ . ق . بود. برخی از علماء تاریخ گفته اند که روز وفات طاوس، از بسیاری مردم و ازدحام، بیرون بردن جنازه میسر نبود تا ابراهیم بن هشام مخزومی امیر مکه تنی چند از نگهبانان را مأمور بتفرقه ٔ جمعیت ساخت و در همان حال دیدم که عبداﷲبن الحسن بن علی بن ابیطالب علیه الصلوة والسلام تابوت را بر شانه ٔ خویش گرفته، و قلنسوه اش از سر افتاده و رداء او از پس سر او پاره شده است . و در شهر بعلبک، در اندرون شهر قبری را دیدم که مردم بزیارت آن میرفتند، و عقیده داشتند که آن قبر طاوس یمانی است در صورتی که غلط است . ابوالفرج بن الجوزی در کتاب القاب گفته که : نام طاوس ذکوان، و طاوس لقب او میباشد. زیرا او طاوس القراء بود. ولی قول مشهور آن است که طاوس اسم او بوده است -انتهی . و از جمله ٔ منقولاتی که از طاوس یمانی در کتب ثبت است آن است که گفت : شبی درکنار حجرالاسود بودم که امام علی بن الحسین علیهما السلام داخل شد، با خود گفتم مردی از آل رسول و خانواده ٔ پیغمبر است، باید گوش فرادارم، و دعاء او بشنوم، چون نیک گوش فراداشتم شنیدم که در اثناء دعا خود میگفت : عبدک بفنائک . سائلک بفنائک، مسکینک بفنائک . طاوس گوید این کلمات را در هر مورد سختی که بر طریق دعا خواندم، از آن سختی مرا فرجی حاصل آمد، و بروایت دیگرطاوس از زبان یکی از ائمه ٔ اثنی عشر سلام اﷲ علیهم شنید که هنگام سجود در نماز، بدین جملات گویا بود: الهی عبیدک بفنائک، مسکینک بفنائک، سائلک بفنائک، فقیرک بفنائک . یا آنکه شنید که امام علیه السلام میفرمود در سجود بدین جملات خدای تعالی را بازخوانید که برای اجابت دعاء مجرب است . و چنانچه مرا در خاطر است در پاره ای از مواضع معتبره است که طاوس گوید با گروهی از زهاددر فضای کعبه، وفی موضع من مواضع الخیر، بودیم و باکمال اصرار و الحاح از درگاه حق تعالی باران میخواستیم . و اثری از باران آشکار نمیشد، تا آنکه علی بن الحسین علیهماالسلام بر ما وارد شد، چون ما را بدان حالت مشاهده فرمود، گفت درینجا چه میخواهید؟ گفتیم از دیرگاهی از خدا باران میطلبیم و دعاء ما مقرون به اجابت نمیشود، فرمود آیا بدین صورت از درگاه حق حاجت میطلبید؟ پرسیدیم پس طریق حاجت خواستن از آفریدگار چگونه است ؟ آن حضرت روی خود بر خاک نهاد و شروع بگریه کرد و گفت اسألک اللهم بحبی لک (او بحبک ایای ) ان تنزل علینا الغیث . هنوز آن امام از جای برنخاسته و سر از سجده برنداشته بود که باران عالمیان را سیراب کرد.و نیز از طاوس یمانی نقل است که گفت : مردی را در مسجد الحرام دیدم که در زیر میزاب نماز میگذارد، و خدای تعالی را میخواند و میگریست، من نزد او شدم، در آن هنگام از نماز فراغت یافت، مشاهده کردم که امام علی بن الحسین زین العابدین است، گفتم یابن رسول اﷲ، شما را بچنین حالت می بینم، و شما را سه خصوصیت است که بدان سه رجاء واثق باشد که از خوف روز جزا ایمن و خاطر آسوده داشته باشید، یکی آنکه پسر رسول خدای هستید، دیگر آنکه شفاعت جد شما در روز حساب جهت شما محقق است، سه دیگر بخشایش خداوندی است که آن نیز درباره ٔ خلق ثابت است . آن حضرت فرمود: ای طاوس اینکه گفتی پسر رسول خدایم، این امر سبب ایمن بودن من نخواهد بود. چه البته شینده ای که فلا انساب بینهم یومئذ و لایتسائلون . (قرآن <span class=\"hlight\" dir=\"rtl\">٢٨/٢١</span>) و اما شفاعت جد من، آن نیز در برابر این آیت که : ولایشفعون الالمن ارتضی (قرآن <span class=\"hlight\" dir=\"rtl\">١٠١/٢٣</span>)، امری است احتمالی و غیرمحقق، و اما اینکه گفتی بخشایش خداوندی شامل حالم خواهد بود. آنهم نامعلوم است . چه حق تعالی در قرآن مجید میفرماید: ان رحمة اﷲ قریب من المحسنین (قرآن <span class=\"hlight\" dir=\"rtl\">٥٦/٧</span>) و من خود نمیدانم که در ردیف نیکوکاران بشمار میروم یا نی . (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٣٣٦</span>).<br />جعفربن سلیمان گوید: از عبدالرحمن بن مهدی شنیدم که میگفت ندیدم مردی مانند این چهار تن : عطابن ابی رباح در مکه، طاوس در یمن، محمدبن سیرین در عراق، و رجابن حیوة در شام . (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٣</span>). طاوس را گفتند قتاده دوست دارد که نزد تو آید، گفت اگر او آمد من برخیزم . گفتند او مردی فقیه است . طاوس گفت اگر مقام او را بفقه مینامید، ابلیس از او فقیه تر است، چه گفت «رب بما اغویتنی ...» (قرآن <span class=\"hlight\" dir=\"rtl\">٣٩/١٥</span>) (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠١</span>). زیدبن عمرو از طاوس نقل کند که او گفت : اوقاتی که در مکه بودم بر سبیل اتفاق بسوی حجاج شدم، بالشی برای من نهادند، نشستم . مشغول صحبت شدیم . ناگهان آواز اعرابی که آهنگ تلبیه بلند کرده بود شنیدیم، حجاج به احضار ملبی فرمان داد، او را حاضر ساختند، حجاج از او پرسید کیستی ؟ گفت مردی هستم ناشناس و غریب، حجاج گفت منظورم آن است که اهل کجائی، اعرابی گفت اهل یمنم، پرسید محمدبن یوسف (برادر حجاج ) را چگونه یافتی، (در آن هنگام برادر حجاج عامل یمن بود) گفت مردی بزرگ و تناور و سخت حیله گر دیدم او را. حجاج گفت منظورم این نبود. بازگوی که رفتار او با مردم چگونه بود. اعرابی گفت او را ستمکار و بیدادگر و نسبت به آفریدگار نافرمان و فرمانبر مخلوق یافتم . حجاج از فرط خشم از اعرابی روی بازگردانید و گفت با آنکه میدانی محمدبن یوسف مرا برادر است و مرتبه و قدر او نزد من بلند میباشد چه چیز ترا به جرأت بازداشت که درباره ٔ او این نوع سخن رانی . اعرابی گفت آیامی اندیشی که مرتبه ٔ برادرت نزد تو، از مرتبه ٔ من نزد آفریدگار ارجمندتر است ؟ آنهم در این هنگام که بزیارت خانه ٔ او آمده، و وام خود را به او ادا میکنم، و گواهی به حقانیت پیمبرش میدهم . حجاج را کرت دیگر خشم گرفت و از بسیاری غضب خاموش شد و اعرابی بدون اجازت از مجلس حجاج بیرون رفت . طاوس گوید من در پی اعرابی بیرون شدم . و میرفتیم تا به «ملتزم » رسیدیم اعرابی چنگ در استار کعبه زد، و گفت : بک اعوذ و الیک الوذ. فاجعل لی فی اللهف الی جوارک، و الرضا بضمانک، مندوحة عن منع الباخلین، و غنی عما فی ایدی المستأثرین اللهم عد بفرجک القریب، و معروفک القدیم و عادتک الخسة. طاوس گوید: اعرابی پس از بپایان رساندن دعای خود، خویشتن را میان مردم پنهان ساخت . تا آنکه دیگربار او را در عرفات دیدم که بر پای ایستاده، و این دعا میخواند: اللهم ان کنت لم تقبل حجی و نصبی و تعبی فلا تحرمنی اجرالمصاب علی مصیبة فلااعلم مصیبة اعظم ممن وردحوضک وانصرف محروماً من وجه رغبتک . (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٩</span>-<span class=\"hlight\" dir=\"rtl\">١٠</span>). او از ابناء و تابعین است . (الکنی والاسماءللدولابی ). رجوع به ابی عبدالرحمن طاوس و فهرست کتاب عیون الاخبار هم در قسمت اعلام و هم در قسمت رجال سند، و نیز به الاعلام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٥</span> و تاریخ الخلفا ص <span class=\"hlight\" dir=\"rtl\">١٠</span> و <span class=\"hlight\" dir=\"rtl\">١٥٦</span> و <span class=\"hlight\" dir=\"rtl\">١٦٤</span> و تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٧٥٨</span> و <span class=\"hlight\" dir=\"rtl\">٨٤٨</span> شود.<br /></font></div>'),
(175640, 'طاوسان', '<span class=\"hlight\">طاوسان .</span> <font color=\"DarkGreen\"><b>[ وو]</font></b> (اِخ ) اصلشان از تخم طاوس بن کیان است و او از تابعین بود. در ایشان علمای عالی مرتبه بوده اند چون شیخ محمد و پسرش ابوجعفر عراقی . (تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٨٤٨</span>).<br /></font></div>'),
(175641, 'طاوسی', '<span class=\"hlight\">طاوسی .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (ص نسبی ) منسوب به طاوس .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گل طاوسی </span> ؛ گلی است زردرنگ با عطری ملایم . برگش باریک، ساقش نازک و تابان . در اغلب خانه ها در فصل بهار متجلی است . قندول .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مروحه ٔ طاوسی </span> ؛ بادبیزنی که از پر طاوس یا از پارچه ٔ طاوسی رنگ ساخته شده باشد <span class=\"hlight\">:</span> بار دیگرملک بدیدن او رغبت کرد. عابد را دید... سرخ و سپید برآمده ... و بر بالش دیبا تکیه زده . و غلام پری پیکر با مروحه ٔ طاوسی بالای سر بخدمت ایستاده . (گلستان ).<br /> <BR><font color=\"Blue\">◄</font> (اِ) نوعی از جامه های رنگین . قسمی جامه ٔ ملون . اسم جامه یا پارچه ای . قسمی لباس <span class=\"hlight\">:</span> <br />مرا جامه ٔ خاصه ٔ خویش دادی <br />چه باشد مرا بیش از این افتخاری <br />چو طاوس رنگین مرا جلوه دادی <br />به طاووسئی چون شکفته بهاری .<br /> <font color=\"Red\">فرخی .</font><br />طاوسی پوشان باغ از یکدیگر گشتند دور<br />بر هوا هست از سیه پوشان قطار اندر قطار.<br /> <font color=\"Red\">امیرمعزی (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> (ص نسبی ) سبز زرین . سبز دینارگون <span class=\"hlight\">:</span> آنچه بد است . (از سماروغ ) آن است که سیاه بود، یا سبز، یا طاوسی . (ذخیره ٔ خوارزمشاهی ). برنگ پرطاوس <span class=\"hlight\">:</span> و بعضی وسمه تنها برنهند و رنگ او طاوسی آید. و رنگ وسمه ٔ هندی زودتر گیرد، و تمامتر آید، لکن طاوسی تر آید. و رنگ وسمه ٔ کرمانی کمتر و دیرتر گیرد، لکن سیاهتر بود، و تطویس او کمتر بود. (ذخیره ٔ خوارزمشاهی ) و رجوع به «پرطاوس » شود <BR><font color=\"Blue\">◄</font> نوعی مرواریداست که سفیدی او با سیاهی و سبزی و سرخی ممزوج بود.(جواهرنامه ). <BR><font color=\"Blue\">◄</font> یاقوت که طاوسی رنگ باشد.قالوا ان اجوده الطاوسی . (الجماهر بیرونی ). <BR><font color=\"Blue\">◄</font> آنکه بچند رنگ زند .<br /></font></div>'),
(175642, 'طاوسی', '<span class=\"hlight\">طاوسی .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِخ ) شمس الدین ایوب . شاعری معاصر علاءالدین محمدبن جلال الدین حسن بن محمدبن حسن بن محمدبن بزرگ امید هفتمین پادشاه اسمعیلیان ایران بود که از سال <span class=\"hlight\" dir=\"rtl\">٤٨٣</span> تا سال <span class=\"hlight\" dir=\"rtl\">٦٥٤</span> هَ . ق . یعنی صد و بیست و یک سال فرمانروائی کردند. طاوسی علاءالدین را مرثیه گفت و این دو بیت از آن است :<br />چون بوقت قبض روحش دید عزرائیل مست <br />برد سوی قمطریرا تا خمارش بشکند<br />کاسه داران جهنم آمدندش پیش باز<br />تا بساط دوستکامی در کنارش بشکنند.<br /><font color=\"Red\">(از تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٥٢٦</span> و <span class=\"hlight\" dir=\"rtl\">٥١٩</span>).</font><br /></font></div>'),
(175643, 'طاوسی', '<span class=\"hlight\">طاوسی .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِ) از نوع گیاهان دولپه ای و طایفه ٔ سه برگچه ای هاست . گیاهی علفی یا درختچه ای است و دارای گونه های مختلف میباشد. گونه های آن طاوسی معمولی یا ژنیست تنکتوریا است که برگهای آن ساده هستند. و دیگر طاوسی بالدار یا ژنیستاساژیتالیس که تقریباً بدون برگ و ساقه ٔ آن پهن و بالدار است . و گونه ٔ دیگر آن طاوسی جاروبی که خامه ٔ گل آن مارپیچی است . و برگهای آن بسیار کوچک هستند و ساقه ٔآن سبز و نرم است و عمل کربن گیری به توسط آن انجام میگیرد. طاوسی اسپانیولی ؛درختچه ای است دارای شاخه های کشیده و استوانه ای شکل وگلهای بزرگ زردرنگ که برای زینت کاشته میشود. (از کتاب دو لپه ایها تألیف دکتر زاهدی استاد دانشگاه ).<br /></font></div>'),
(175644, 'طاوسیان', '<span class=\"hlight\">طاوسیان .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (اِخ ) قبیله ای از قبایل قزوین، اصلشان از تخم طاوس بن کیسان است . و او از تابعین بود، در ایشان علمای عالی مرتبه بوده اند، چون شیخ محمد و پسرش ابوجعفر عراقی . (تاریخ گزیده ٔ عکسی چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٨٤٧</span>). و رجوع به تاریخ ادبیات ایران تألیف براون . ترجمه ٔ علی اصغر حکمت ص <span class=\"hlight\" dir=\"rtl\">١١٥</span> شود.<br /></font></div>'),
(175645, 'طاوق', '<span class=\"hlight\">طاوق .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) شهری است در جنوب قارقار واقع در بلاد ترکیه .<br /></font></div>'),
(175646, 'طاول', '<span class=\"hlight\">طاول .</span> <font color=\"DarkGreen\"><b>[ وِ <span class=\"hlight\" dir=\"rtl\">/</span> وَ ]</font></b> (اِ) تاول . آبله ای باشد که بسبب سوختن یا کار کردن بر اعضا و دست و پا بهم رسد. برآمدگی پوست از سوختگی . آبله . برآمدگی جلد بکیفیتی که زیر آن آب جمع شده باشد. رجوع به تاول شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاول زدن </span> ؛ تنفط. ایجاد طاول .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاول طاعونی </span> ؛ سیاه زخم . خراج . <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طاول عظم جلدی </span> ؛ نفاطة. ج، نفاط.<br /></font></div>'),
(175647, 'طاولة', '<span class=\"hlight\">طاولة.</span> <font color=\"DarkGreen\"><b>[ وِ ل َ ]</font></b> (معرب، اِ) معرب تابل . در سوریه طاوله و در مصر ترابیره و درعراق میزونَضَد گویند، و کلمه ٔ منضده خطاست چه در لغت فصیح نیامده است . (از نشوءاللغة العربیه ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>).<br /></font></div>'),
(175648, 'طاوه', '<span class=\"hlight\">طاوه .</span> <font color=\"DarkGreen\"><b>[ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (اِ) ظرفی است فلزی برای سرخ کردن اطعمه به کار رود. در ترکی طابه و در ترکی عامیانه طاوه مأخوذ از تاوه ٔ فارسی است . این کلمه در عربی بصورت طابق درآمده است . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩</span>). و رجوع به تابه و تاوه شود.<br /></font></div>'),
(175649, 'طاوه', '<span class=\"hlight\">طاوه .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) دهی است از دهستان درجزین بخش رزن شهرستان همدان، در <span class=\"hlight\" dir=\"rtl\">٣٠</span>هزارگزی جنوب قصبه ٔ رزن متصل به سناج . جلگه و سردسیر و مالاریائی . با <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و لبنیات و حبوبات . شغل اهالی زراعت و گله داری . صنایع دستی زنان قالی بافی و راه آن مالرو است . تابستان از فامنین اتومبیل میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(175650, 'طاووس', '<span class=\"hlight\">طاووس .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (معرب، اِ) رجوع به طاوس شود.<br /></font></div>'),
(175651, 'طاووسی', '<span class=\"hlight\">طاووسی .</span> <font color=\"DarkGreen\"><b>[ وو ]</font></b> (ص نسبی، اِ) رجوع به طاوسی شود.<br /></font></div>'),
(175652, 'طاویة', '<span class=\"hlight\">طاویة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) گرسنه . <BR><font color=\"Blue\">◄</font> گرسنه دارنده خود را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پیچنده . (دهار). و رجوع به طاو شود.<br /></font></div>'),
(175653, 'طاویر', '<span class=\"hlight\">طاویر.</span> (اِخ ) دهی از دهستان کتول بخش علی آباد شهرستان گرگان در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی جنوب علی آباد. کوهستانی و معتدل و مرطوب، با <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> تن سکنه . آب آن از چشمه سار. محصول آنجا غلات و لبنیات . شغل اهالی زراعت و گله داری . صنایع دستی زنان شال و کرباس بافی و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175654, 'طاویران', '<span class=\"hlight\">طاویران .</span> (اِخ ) دهی از دهستان ماهیدشت بالا بخش مرکزی شهرستان کرمانشاهان در <span class=\"hlight\" dir=\"rtl\">٣٦</span>هزارگزی جنوب روئین تن . دشت، دامنه سردسیر با <span class=\"hlight\" dir=\"rtl\">٣١٠</span> تن سکنه . اغلب ساداتند. آب آن از چشمه و قنات . محصول آنجا غلات و حبوبات و صیفی و تریاک و توتون و لبنیات . شغل اهالی زراعت . راه آن مالرو است . و تابستان از طریق تالاندشت اتومبیل رفت و آمد میکند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(175655, 'طاویق', '<span class=\"hlight\">طاویق .</span> (اِخ ) ده کوچکی است از دهستان مسکون بخش جبال بارز شهرستان جیرفت در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی خاوری شوسه ٔ بم به سبزواران با <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه . مزارع گلدین و گشورود جزء این ده است . ساکنین از طایفه ٔ خواجه هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175656, 'طاویق', '<span class=\"hlight\">طاویق .</span> (اِخ ) ده کوچکی است از دهستان گاوکان بخش جبال بارز شهرستان جیرفت در <span class=\"hlight\" dir=\"rtl\">١٠٥</span>هزارگزی جنوب خاوری مسکون و <span class=\"hlight\" dir=\"rtl\">١٠٠</span>هزارگزی شمال راه مالرو کروک به سبزواران، با <span class=\"hlight\" dir=\"rtl\">٨</span> تن سکنه . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175657, 'طاویقو', '<span class=\"hlight\">طاویقو.</span> (اِخ ) ده کوچکی است از دهستان خبر بخش بافت شهرستان سیرجان در <span class=\"hlight\" dir=\"rtl\">٨٠</span>هزارگزی جنوب باختری بافت . سر راه مالرو ده سرد به خبر، با <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175658, 'طاویقونیه', '<span class=\"hlight\">طاویقونیه .</span> <font color=\"DarkGreen\"><b>[ نی ی َ ]</font></b> (اِخ ) ده کوچکی است از دهستان بهرآسمان بخش ساردوئیه شهرستان جیرفت در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی خاور ساردوئیه و <span class=\"hlight\" dir=\"rtl\">١٩</span>هزارگزی جنوب راه مالرو بافت به ساردوئیه . با <span class=\"hlight\" dir=\"rtl\">٧</span> تن سکنه . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175659, 'طاویله', '<span class=\"hlight\">طاویله .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) دهی است از دهستان پایرود بخش مرکزی شهرستان کرمانشاهان . در <span class=\"hlight\" dir=\"rtl\">١٣</span>هزارگزی خاور کرمانشاه و <span class=\"hlight\" dir=\"rtl\">٤</span>هزارگزی شمال شوسه ٔ کرمانشاه - طهران . کوهستانی وسردسیر. با <span class=\"hlight\" dir=\"rtl\">١٢٥</span> تن سکنه . آب آن از چشمه کوچک . محصول آن غلات دیمی و لبنیات . شغل اهالی زراعت و گله داری . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(175660, 'طاویله', '<span class=\"hlight\">طاویله .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) نام کوهی و ناحیتی است به هرسین .<br /></font></div>'),
(175661, 'طاپوری', '<span class=\"hlight\">طاپوری .</span> (اِخ ) نام طایفه ای بوده است که در ناحیه ٔ شمال شرقی یعنی از کنار رود اَترک تا ساحل رودخانه ٔ آراسپی را برای اقامت و یورت اختیار کرده بودند و نام طبرستان از اسم این طایفه مشتق شده است و در ابتدا طاپورستان می گفته اند یعنی ولایتی که طایفه ٔ طاپور در آن مقیمند. بعد طاپورستان طبرستان شده و در مسکوکات سلاطین مستقل مازندران که تا خلافت بنی عباس بهیچ سلطنتی اطاعت نمیکردند، پادشاه طاپورستان نقش است . (التدوین ).<br /></font></div>'),
(175662, 'طاگانک', '<span class=\"hlight\">طاگانک .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) دهی است از دهستان لار بخش حومه ٔشهرستان شهرکرد در<span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی جنوب شهرکرد، کنار راه طاگانک به شهرکرد. جلگه . معتدل . با <span class=\"hlight\" dir=\"rtl\">٢١٣٨</span> سکنه . آب آن از قنات و رودخانه محصول آنجا غلات . شغل اهالی زراعت گله داری . صنایع دستی قالی بافی . راه آن ماشین رو است . دبستانی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(175663, 'طای', '<span class=\"hlight\">طای .</span> (معرب، اِ) شای . معرب چای . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩</span>). رجوع به چای شود.<br /></font></div>'),
(175664, 'طای', '<span class=\"hlight\">طای .</span> (اِخ ) دهی از دهستان راوه رود بخش کامیاران شهرستان سنندج، واقع در <span class=\"hlight\" dir=\"rtl\">٣٨</span>هزارگزی شمال باختر کامیاران و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی هندیمن . کوهستانی و سردسیر است با <span class=\"hlight\" dir=\"rtl\">١٥٣٢</span>تن سکنه . آب آن از چشمه . محصول آنجا انواع میوه ها ولبنیات . شغل اهالی باغبانی و گله داری است . راه مالرو و دبستان دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(175665, 'طایات', '<span class=\"hlight\">طایات .</span> (ع اِ) سطوح . قال فی اللسان السجج الطایات الممدرة. (از ذیل اقرب الموارد).<br /></font></div>'),
(175666, 'طایانک خان', '<span class=\"hlight\">طایانک خان .</span> (اِخ ) پادشاه یا خان طایفه ٔ نایمان مغول که چنگیزبر او ظفر یافت . حمداﷲ مستوفی آرد: در سنه ٔ تسع و تسعین و خمسمائة چنگیزخان بر او (باونگ خان ) مستولی شدو اسم پادشاهی بر او چنگیز اطلاق رفت و در سنه ٔ ثلث و ستمائة طابانک خان قوم نایمان را قهر کرد نام چنگیزخانی بر او (چنگیز) افتاد. (تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٥٧٢</span>). و در ص <span class=\"hlight\" dir=\"rtl\">٨٤٩</span> ذیل بوتیموریان آرد: اولشان امیر تکش بود ازتخم طابانک خان، پادشاه قوم نایمان بود. ادوارد براون در فهرست تاریخ گزیده کلمه های طابانک خان و طاکیانک خان را به طایانک خان رجوع داده و ما نیز این نام را ذیل طایانک خان آوردیم . و در تاریخ مغول ذیل تایانگ خان آمده است : بعد از آنکه چنگیزخان بر قبیله ٔ کرائیت غلبه کرد تایانگ خان پادشاه قوم نایمان بیم آن داشت که مبادا او نیز مورد تعرض و حمله ٔ خان مغول قرار گیرد. چنگیز در سال <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> هَ . ق . به تایانگ خان حمله برد و در حدود جبال آلتائی او را مغلوب و زخمی کرد و تایانگ خان کمی بعد جان سپرده، قومش مغلوب چنگیزخان گردیدند و پسرش کوچلک خان فرار اختیار کرد. (تاریخ مغول تألیف عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">١٦</span>). و رجوع به تایانک خان شود.<br /></font></div>'),
(175667, 'طایب شه', '<span class=\"hlight\">طایب شه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ش َ ]</font></b> (اِخ ) دهی از دهستان سرشیو بخش مرکزی شهرستان سقز، واقع در <span class=\"hlight\" dir=\"rtl\">٢٩</span> هزارگزی جنوب خاوری سقز و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی بهرام . کوهستانی و سردسیری است با <span class=\"hlight\" dir=\"rtl\">١٣٠</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات، لبنیات و توتون . شغل اهالی آنجا زراعت و گله داری است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(175668, 'طایباد', '<span class=\"hlight\">طایباد.</span> (اِخ ) شهری است از بلاد خراسان . (شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٢</span>). و صاحب آنندراج ذیل تایباد آرد: قریه ای است از باخرز و از آنجا است عارف مرشد شیخ زین الدین پیر امیر تیمور صاحب قران و اصل در آن تائب آباد بوده و تایباد مخفف آن است . رجوع به تایباد، طیبات و حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣٠</span> و <span class=\"hlight\" dir=\"rtl\">٥٤٣</span> شود.<br /></font></div>'),
(175669, 'طایة', '<span class=\"hlight\">طایة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) بام . (منتهی الارب ). سطح . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خشک کردنگاه خرما. (منتهی الارب ). آنجا که خرما گرد کنند. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> خرسنگ در زمین ریگستان . <BR><font color=\"Blue\">◄</font> زمین که در آن سنگ نباشد. (منتهی الارب ).<br /></font></div>'),
(175670, 'طایجو', '<span class=\"hlight\">طایجو.</span> (اِخ ) این کلمه بصورتهای : طایخو، طابخو، تابخو و طابحو در تواریخ آمده، ولی صحیح آن طایجو یا تایجو است که در فهرست حبیب السیر چ خیام تایجو و در تاریخ غازان طایجو ضبط شده است و نام چند تن از امرای مغول بوده است . رجوع به تایجو و عناوین بعد شود.<br /></font></div>'),
(175671, 'طایجو', '<span class=\"hlight\">طایجو.</span> (اِخ ) خواندمیر ذیل عنوان «بیان ایالت طبقه ٔ سیم از سلجوقیان در مملکت روم و قونیه » آرد <span class=\"hlight\">:</span> در ایام غیاث الدین کیخسروبن کیقباد تایجونامی از امرای چنگیزی لشکر به روم کشیده کیقباد منهزم گردید و در سنه ٔ اربع و اربعین و ستمائة هَ . ق . وفات یافت . (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤٠</span>).<br /></font></div>'),
(175672, 'طایجو', '<span class=\"hlight\">طایجو.</span> (اِخ ) پسر جغتای خان بن چنگیزخان و جغتای پسر دوم چنگیزخان بود و پس از مرگ چنگیزخان بر ماوراءالنهر و بعضی از حدود خوارزم و بلاد ایغور، کاشغر، بدخشان، بلخ و غزنین تا کنار آب سند حکومت میکرد. جغتای در سال <span class=\"hlight\" dir=\"rtl\">٦٣٨</span> هَ . ق . درگذشت و طایجو پسر هشتم او بشمار میرفت . رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨</span> «تایجو» شود.<br /></font></div>'),
(175673, 'طایجو', '<span class=\"hlight\">طایجو.</span> (اِخ ) پسر منگوتیمور از شاهزادگانی است که در طغیان چند تن از امرای غازانی شاهزاده «سوکای پسر یشموت و نواده ٔ هولاکو» و «برلا» و «ارسلان اوغول » ظاهراً دعوت طغیان گران را پذیرفت، ولی بیدرنگ امیر نوروز را از توطئه ٔ سوکا و برلا آگاه ساخت . (از تاریخ مغول اقبال ص <span class=\"hlight\" dir=\"rtl\">٢٦٢</span>). صاحب حبیب السیر این واقعه را در حدود سال <span class=\"hlight\" dir=\"rtl\">٦٩٥</span> هَ . ق . یاد کرده است . رجوع به حبیب السیرچ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٧</span> و تاریخ غازان ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span> و <span class=\"hlight\" dir=\"rtl\">١٠٣</span> شود.<br /></font></div>'),
(175674, 'طایجواغول', '<span class=\"hlight\">طایجواغول .</span> <font color=\"DarkGreen\"><b>[ اُ ]</font></b> (اِخ ) یکی از امرا و شاهزادگان عصر غازان خان که در سال <span class=\"hlight\" dir=\"rtl\">٦٩٧</span> هَ . ق . بصرف گفتار شخصی که به او پیش گوئی کرده بود که پس از چهل روز سریر پادشاهی بوجود تو مزین خواهد شد. دود پندار بکاخ دماغ او تصاعد کرد هم در آن ایام خبر بگوش غازانخان رسید و طایجو را با مقربان و امرا و کرامات گوی نادان بیاسا رسانید. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٥١</span>). رجوع به همان جلد ص <span class=\"hlight\" dir=\"rtl\">١٤٠</span> و ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span> و تاریخ غازان ص <span class=\"hlight\" dir=\"rtl\">٩٧</span>، <span class=\"hlight\" dir=\"rtl\">١١٨</span>، <span class=\"hlight\" dir=\"rtl\">١١٩</span> و تاریخ مغول تألیف اقبال ص <span class=\"hlight\" dir=\"rtl\">٢٦٥</span> ذیل «تایجور» شود.<br /></font></div>'),
(175675, 'طایجوبهادر', '<span class=\"hlight\">طایجوبهادر.</span> <font color=\"DarkGreen\"><b>[ ب َ دُ ]</font></b> (اِخ ) از امرای لشکر مغول در عهد غازان و پدر غزان است که با یاغیان همدست بود. رشیدالدین فضل اﷲ ذیل «مخالفت اندیشیدن سوکا و بارولا» آرد <span class=\"hlight\">:</span> و بیشتر جماعت دشمنان (سوکا و بارولا) مقهور شدند و طایفه ای که مانده اند ارسلان اغول را بزرگ خود ساخته اند و بپیلسوار آمده ... و امرا که با ارسلان اغول بودند: تولک پسرعم اوجان امیرسلاح بود و اینه بک پسر اشک توغلی از جلایر و غزان پسر طایجوبهادر و موسی ترخان ...(تاریخ غازان ص <span class=\"hlight\" dir=\"rtl\">٩٩</span>). و رجوع به ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span> و غزان شود.<br /></font></div>'),
(175676, 'طایجونویان', '<span class=\"hlight\">طایجونویان .</span> (اِخ ) خواندمیر ذیل نهضت هلاکوخان و بیان انهدام اساس خلافت بنی عباس از طایجونویان نام میبرد که در حدود سال <span class=\"hlight\" dir=\"rtl\">٦٥٠</span> هَ . ق . وی را منگوقاآن بن تولی خان بن چنگیز با سپاه بی کرانی برای ضبط ممالک ایران نامزد کرده و او از جیحون گذشته، پس از چندگاه از مستعصم و ملاحده ٔ اسماعیلیه شکایت کرده است . از آن پس منگوقاآن برادر خود هلاکو را در سال <span class=\"hlight\" dir=\"rtl\">٦٥٣</span> هَ . ق . با جمعی از لشکر چنگیزخان به محافظت کشور ایران برگزیده است، و آنگاه که هلاکو بتحریک ابن علقمی به بغدادلشکر کشیده سوغونجاق و تایجو را برای جنگ با مستعصم به بغداد گسیل کرده است . (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span> - <span class=\"hlight\" dir=\"rtl\">٣٣٩</span>). و رجوع به همان کتاب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩٤</span> شود.<br /></font></div>'),
(175677, 'طایح', '<span class=\"hlight\">طایح .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) هالک . یا مشرف بر هلاک . <BR><font color=\"Blue\">◄</font> سرگشته . (از اقرب الموارد).<br /></font></div>'),
(175678, 'طایحة', '<span class=\"hlight\">طایحة.</span> <font color=\"DarkGreen\"><b>[ ی ِ ح َ ]</font></b> (ع ص ) تأنیث طائح . حادثه ٔ هلاک کننده . مرد هلاک شده . (شمس اللغات ).<br /></font></div>'),
(175679, 'طایخ', '<span class=\"hlight\">طایخ .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) فرورونده ٔ در باطل . احمقی که خیری در او نیست و بقولی احمق پلید. یقال : رجل طائخ . (ذیل اقرب الموارد از اللسان ).<br /></font></div>'),
(175680, 'طاید', '<span class=\"hlight\">طاید.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (از ع، ص ) طائد. پایدار. ثابت . (از اقرب الموارد).<br /></font></div>'),
(175681, 'طایر', '<span class=\"hlight\">طایر.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) نام یکی از تازیان که بنابه گفته ٔ خواندمیر پس از مرگ نرسی به کشور ایران تاختن آورد. خواندمیر ذیل وقایع سلطنت شاپور ذوالاکتاف آرد: بعد از فوت هرمزبن نرسی در اطراف عالم این خبر شایع شد که پادشاه عجم قدم بصحرای عدم نهاد و از او پسری نمانده که ضبط مملکت نماید. لاجرم حکام اطراف در تسخیر آن ملک طمع نموده، طایرنامی از اعراب با لشکری بسان عقاب بعضی از ممالک فرس را نشیمن ساخت و به چنگال عذاب و منقار عقاب مراسم قتل و غارت بتقدیم رسانید و چون سن شاهپور به شانزده سالگی رسید و از کیفیت جرأت طایر واقف گردید با سپاه موفور به دیار عرب رفته، بسیاری از آن طایفه را به تیغ بیدریغ بگذرانید و از کشیدن انتقام دقیقه ای مهمل و نامرعی نگذاشت . (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span> - <span class=\"hlight\" dir=\"rtl\">٢٣٠</span>). ظاهراً این طایر تصحیف طاهر غسانی باشد که نام وی گذشت . رجوع به طائر، طاهر غسانی و تاریخ گزیده ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٧</span> شود.<br /></font></div>'),
(175682, 'طایر', '<span class=\"hlight\">طایر.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع اِ) رجوع به طائر شود.<br /></font></div>'),
(175683, 'طایر بوقابهادر', '<span class=\"hlight\">طایر بوقابهادر.</span> <font color=\"DarkGreen\"><b>[ ی ِ ب َ دُ ]</font></b> (اِخ ) رجوع به طایر بهادر و تاریخ سیستان حاشیه ٔ صص <span class=\"hlight\" dir=\"rtl\">٣٩٧</span>-<span class=\"hlight\" dir=\"rtl\">٣٩٨</span> شود.<br /></font></div>'),
(175684, 'طایر جرفادقانی', '<span class=\"hlight\">طایر جرفادقانی .</span> <font color=\"DarkGreen\"><b>[ ی ِ رِ ج ُ دَ ]</font></b> (اِخ ) هدایت آرد: نام شریفش آقا سیدمحمد از فضلای آن بلد، سیدی با ذوق و عرفان، و با شوق و ایمان بوده در سفر مکه ٔ معظمه رحلت کرده، این چند بیت از اوست، رحمة اﷲ علیه :<br />اگر گویم ز عشق گُل فغان آموز شد بلبل <br />خطا باشد که این نسبت بود بی اصل وبی مبدا<br />نه بلبل عاشق گُل شد نه گُل معشوق بلبل شد<br />گل و بلبل شده هریک به روئی واله و شیدا<br />هر آن کس زنگ بزداید ز مرآت ضمیر خود<br />ببیند جمله هستی را به ذکر ایزد یکتا<br />همه عاشق به روی او همه مایل بسوی او<br />همه خرم به بوی او و او از جمله ناپیدا<br /> <font color=\"Red\">#</font><br />از لعل ترت خُشک لبم تر خواهم <br />یعنی که ز بوسه شهد و شکر خواهم <br />یک بوسه نه، صدهزار خواهم، زآن روی <br />قند است لب تو و مُکرر خواهم .<br /><font color=\"Red\">(مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span>).</font><br /></font></div>'),
(175685, 'طایر شیرازی', '<span class=\"hlight\">طایر شیرازی .</span> <font color=\"DarkGreen\"><b>[ ی ِ رِ ]</font></b> (اِخ ) هدایت آرد: نام شریفش حسن خان بن عبدالرحیم خان، پدرش برادر اعتمادالدوله حاجی ابراهیم خان شیرازی که پیشکار خاقان سعید شهید بوده، پس از استیصال آن خاندان بقهر قهرمان ایران، از گیتی چشم پوشیده و به عبادت کوشیده، سالها در کرمانشاه، در حضرت شاهزاده ٔ مغفور دولتشاه مبرور، ندیم و محرم، و از امراء معظم بوده . پس از رحلت آن شاهزاده ٔ ذی شان، وی نیز پریشان آمد. کمالاتش بسیار است . از جمله اینکه با عدم بصر شطرنج بازد، و بیشتر حریفان اسب انداز پیل افکن را، بفرزینی فرزانه، یا بیدقی دیوانه، شهمات سازد. پنجهزار بیت دیوان غزلیات اوست . غزل را به سیاقی خوب میفرماید، ودر این فن قدرت کامل ظاهر می نماید، چون غزلیات نیکودارد، اندکی قصاید، و بیشتر از غزلیاتش نوشته شد:<br />شده درخت شکوفه ز پای تا سر چشم <br />چو عاشقی که نشیند به راه وعده ٔ یار<br />اگر نه لاله هم عاشق است و هم معشوق <br />دلش چراست چو عاشق رخش چراست چو نار؟<br />گیتی اگر غلط نکنم رنگ و بو گرفت <br />از رنگ و بوی بزمگه عید شهریار<br />گاه عطا چو دستش میخواندم ابر را<br />باران ابر بود اگر در شاهوار<br /> <font color=\"Red\">#</font><br />سراغ منزل طایر ز من کنی که کجاست <br />بهر کجا که در آنجا رخ نکوئی هست .<br />گشتم آسوده ز بدگوئی دشمن کاکنون <br />ببدی هم نتوان برد بر او نامم .<br /><font color=\"Red\">(مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٣</span>).</font><br /></font></div>'),
(175686, 'طایراوسون', '<span class=\"hlight\">طایراوسون .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) مقدم قوم اوهات مرکیت (از اقوام چنگیزی ). (جامعالتواریخ بلوشه ص <span class=\"hlight\" dir=\"rtl\">٣</span>) خواندمیر در حبیب السیر نام این شخص را بدین طریق ضبط کرده : «طایرالسون » و گوید: قولون دختر طایر السون یکی از پنج نفر زنان چنگیزخان بوده که بر سایر خاتونهای او برتری داشته اند. (حبیب السیر چ قدیم تهران جزء اول از ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧</span>). ولی بلوشه ناشر جامعالتواریخ گوید: ضبط درست این اسم طایراوسون (دایراسون ) است ؛ زیرا در تاریخ مغولهای شرقی تألیف سننگ سچن ص با حروف مغولی به همین نحو ضبطشده است . (جامعالتواریخ رشیدی مقدمه ٔ بلوشه ص <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(175687, 'طایربهادر', '<span class=\"hlight\">طایربهادر.</span> <font color=\"DarkGreen\"><b>[ ی ِب َ دُ ]</font></b> (اِخ ) هنگامی که لشکریان مغول در سال <span class=\"hlight\" dir=\"rtl\">٦١٦</span> هَ . ق . بخارا را فتح و ویران ساختند، طایربهادر فرمانده پیشقراولان چنگیزی بود و ظاهراً همین طایربهادر در سال <span class=\"hlight\" dir=\"rtl\">٦٢٦</span> هَ . ق . فرماندهی قسمتی از اردوی مقیم بادغیس را بر عهده داشت و پس از سرکشی دو تن از سران سپاهی سلطان جلال الدین یکی به نام قراچه و دیگری به نام یغان سنقور در حدود نیشابور به دفع قراچه عازم نیشابور شد و قراچه در آن تاریخ از کلبلات مأمور جنتمور شکست یافته و در قلعه ٔ ارگ سیستان متحصن شده بود. طایربهادر دو سال قلعه ٔ ارگ را در محاصره داشت و در این مدت بین او و جنتمور بر سر حکومت و تولیت کار خراسان اختلاف بروز کرد چه هر کدام از ایشان این مقام را حق خود میدانستند. جور ماغون طرف طایربهادر را گرفت واو را به حکومت خراسان و مازندران انتخاب کرد. هنگام سلطنت ملوک کرت ملک شمس الدین محمد بسبب متهم شدن بهمدستی مسلمین هند به طایربهادر که فرمانده کل قوای مغول در ایران شرقی بود پناه برد و او شمس الدین را تحت حمایت خود گرفت و پس از مرگ طایربهادر که در سال <span class=\"hlight\" dir=\"rtl\">٦٤٥</span> هَ . ق . روی داد، رؤسای مغول ملک شمس الدین را به حضور جغتای فرستادند. رجوع به تاریخ مغول تألیف اقبال ص <span class=\"hlight\" dir=\"rtl\">٢٨</span>، <span class=\"hlight\" dir=\"rtl\">١٦٦</span> و <span class=\"hlight\" dir=\"rtl\">٣٦٨</span> و جهانگشای جوینی چ اروپا ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٨٧</span> و <span class=\"hlight\" dir=\"rtl\">٧٩</span> و تاریخ سیستان حاشیه ٔ صص <span class=\"hlight\" dir=\"rtl\">٣٩٧</span>- <span class=\"hlight\" dir=\"rtl\">٣٩٨</span> شود.<br /></font></div>'),
(175688, 'طایری رازی', '<span class=\"hlight\">طایری رازی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ی ِ ]</font></b> (اِخ ) پسر مولانا امیدی است . این مطلع از اوست :<br />آنکه رفت از سر کوی تو به آزار، منم <br />وآنکه برد از تو به دل حسرت بسیار، منم .<br /><font color=\"Red\">(تحفه ٔ سامی ص <span class=\"hlight\" dir=\"rtl\">١٤١</span>).</font><br /></font></div>'),
(175689, 'طایری مشهدی', '<span class=\"hlight\">طایری مشهدی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ی ِ م َ هََ ]</font></b>(اِخ ) طالب علم بود و در شعر طبع بانگیز داشت (؟)<br />این مطلع از اوست :<br />انگشت بهر عشق چو بر ابروان نهاد<br />تیری برای کشتن من در کمان نهاد.<br /><font color=\"Red\">(تحفه ٔ سامی ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>).</font><br /></font></div>'),
(175690, 'طایسی', '<span class=\"hlight\">طایسی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) از امرای مغول، و سردار مقدمه ٔ لشکر یمه و سبتای در تعاقب محمد خوارزمشاه . (جهانگشای جوینی چ اروپا ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٦</span>، <span class=\"hlight\" dir=\"rtl\">١٢٨</span>، <span class=\"hlight\" dir=\"rtl\">١١٣</span>).<br /></font></div>'),
(175691, 'طایش', '<span class=\"hlight\">طایش .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به طائش شود.<br /></font></div>'),
(175692, 'طایط', '<span class=\"hlight\">طایط.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به طائط شود.<br /></font></div>'),
(175693, 'طایع', '<span class=\"hlight\">طایع.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به طائع شود.<br /></font></div>'),
(175694, 'طایف', '<span class=\"hlight\">طایف .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) رجوع به طایفا شود.<br /></font></div>'),
(175695, 'طایف', '<span class=\"hlight\">طایف .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به طائف شود.<br /></font></div>'),
(175696, 'طایفا', '<span class=\"hlight\">طایفا.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) جربادقانی محمدعلی . فرزند حاج محمدحسین ساکن جربادقان . جد اعلای ایشان ملا کمال الدین حسین در نجف اشرف ساکن بود، چون شیعه بود اهل روم آزار او میکردند به این سبب به جربادقان آمد. پادشاه دیندار شاه اسماعیل ماضی که به آنجا آمد از این معنی اطلاع یافته مهربانی بسیار کرده، چنانچه رقم معافی به او داده و تا حال به امضای پادشاهان رسید. مجملاً ملا محمدعلی به اصفهان آمده بخدمت علامه آقاحسین مشغول به تحصیل است . کمال آدمیت و مردمی دارد و سلیقه اش در نهایت درستی است . چون پیوسته در طواف کعبه ٔ معنی است طایف تخلص دارد. از اوست :<br />زبان و دل موافق ساز هنگام دعا کردن <br />به یک انگشت نتوان عقده ای از رشته واکردن .<br />شکستن همنشین هرکه شد حاجت روا گردد<br />که گردد سجده گاه خلق چون نی بوریا گردد.<br />تا توانی دل به احسان کسان مایل مکن <br />جام جم را کاسه ٔ دریوزه ٔ سایل مکن .<br /> <font color=\"Red\">(از تذکره ٔ نصرآبادی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥١</span>).</font><br />و صاحب تذکره ٔ گلشن ذیل طائف آرد: محمدعلی جربادقانی است و طائف مطاف بلاغت الفاظ و لطافت معانی . از اوست :<br />نه شبنم است به گلزار کامیاب شده <br />دلی که بسته به گل عندلیب آب شده .<br /> <font color=\"Red\">(از تذکره ٔ صبح گلشن ).</font><br />و صاحب قاموس الاعلام آرد: طائف نامش محمدعلی است و یکی از شعرای ایران و از اهالی جرفادقان (گلپایگان ) بوده از اوست :<br />زبان و دل موافق ساز هنگام دعا کردن <br />به یک انگشت نتوان عقده ای از رشته واکردن .<br /></font></div>'),
(175697, 'طایفة', '<span class=\"hlight\">طایفة.</span> <font color=\"DarkGreen\"><b>[ ی ِ ف َ ]</font></b> (ع اِ) رجوع به طائفه شود.<br /></font></div>'),
(175698, 'طایفه آبیل', '<span class=\"hlight\">طایفه آبیل .</span> <font color=\"DarkGreen\"><b>[ ی ِ ف َ ]</font></b> (اِخ ) دهی از بخش پشت آب شهرستان زابل، واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی شمال خاوری بنجار نزدیک دریاچه ٔ هامون . جلگه، گرم و معتدل با <span class=\"hlight\" dir=\"rtl\">٦٩</span> تن سکنه . آب آن از رودخانه ٔ هیرمند. محصول آنجا غلات و لبنیات . شغل اهالی زراعت و گله داری . ساکنان آنجا چادرنشین هستند. راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175699, 'طایفه سارانی', '<span class=\"hlight\">طایفه سارانی .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (اِخ ) دهی از بخش میان کنگی شهرستان زابل، واقع در <span class=\"hlight\" dir=\"rtl\">٨</span>هزارگزی شمال ده دوست محمد نزدیک مرز افغانستان . جلگه، گرم و معتدل با <span class=\"hlight\" dir=\"rtl\">٥٥٨</span> تن سکنه . آب آن از رودخانه ٔ هیرمند. محصول آنجا غلات و لبنیات .شغل اهالی زراعت و گله داری و صنایع دستی زنان آنجا قالیچه، گلیم و کرباس بافی است . و راه آن مالرو است .چادرنشین هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175700, 'طایفو', '<span class=\"hlight\">طایفو.</span> (اِ) دومین مرتبه از مراتب نه گانه ٔ امراء و حکام چنگیزی است و بمعنی امیر لشکر است . (جامعالتواریخ رشیدی چ بلوشه ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٧٠</span>): مناصب امراء و حکام آنجا بحسب مرتبه است و مراتب ایشان بدین ترتیب و موجب میشود مفصلاً: مرتبه ٔ اول : چینکسانک راه وزارت و نیابت داشته باشند. مرتبه ٔ دوم : طایفو امیر لشکر باشد، و هرچند بزرگ باشد رجوع بچینکسانک کند. الی آخرها. (جامعالتواریخ ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٧٠</span>).<br /></font></div>'),
(175701, 'طایفی', '<span class=\"hlight\">طایفی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) محمدبن مسلم طایفی . منسوب به طایف . از عبداﷲبن دینار و ابراهیم بن میسرة روایت کرده است و یحیی بن سلیم طایفی و عراقیان از وی روایت دارند. و عبدالرحمن بن مهدی گفته است که محمدبن مسلم صحاحی نوشته است . (از انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «ب »).<br /></font></div>'),
(175702, 'طایفی', '<span class=\"hlight\">طایفی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ص نسبی ) منسوب به طایف که شهری است در <span class=\"hlight\" dir=\"rtl\">١٢</span>فرسخی مکه . (سمعانی ). رجوع به طائفی شود.<br /></font></div>'),
(175703, 'طایفی', '<span class=\"hlight\">طایفی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) طائفی . ابویعلی عبداﷲبن عبدالرحمن یعلی بن کعب ثقفی طایفی . منسوب به طایف . وی از عطا روایت کرده است . ابن مبارک و ابوعاصم از او روایت دارند. (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «ب »).<br /></font></div>'),
(175704, 'طایفی', '<span class=\"hlight\">طایفی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) طائفی . عبداﷲبن عبدالرحمن ... طائفی . رجوع به ابویعلی عبداﷲ... طائفی شود.<br /></font></div>'),
(175705, 'طایفی', '<span class=\"hlight\">طایفی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) محمدبن سعید طایفی . منسوب به طایف . از اهربن عبداﷲبن حسن خزاعی روایت کرده است . (از انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «ب »).<br /></font></div>'),
(175706, 'طایفی', '<span class=\"hlight\">طایفی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) طائفی . محمدبن عبداﷲبن افلح طایفی ثقفی . منسوب به طایف . از بشربن عاصم روایت کرده است و ثوری و عبداﷲبن مبارک از او روایت دارند. (از انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «ب »).<br /></font></div>'),
(175707, 'طایفی', '<span class=\"hlight\">طایفی .</span> <font color=\"DarkGreen\"><b>[ی ِ ]</font></b> (اِخ ) مسلم بن عبد ربه طایفی . منسوب به طایف . از سفیان ثوری روایت کرده است و حسن بن یزیدبن معاویه از وی روایت دارد. (از انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «ب »).<br /></font></div>'),
(175708, 'طایفی', '<span class=\"hlight\">طایفی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) یحیی بن سلیم طایفی . منسوب به طایف . از محمدبن مسلم طایفی روایت دارد. (از انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «ب »). رجوع به محمدبن مسلم طائفی شود.<br /></font></div>'),
(175709, 'طایق', '<span class=\"hlight\">طایق .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع اِ) میان هر یک از دو چوب کشتی و بقولی یکی از چوبهای زورق . و بگفته ای وسط کشتی . لبید گوید: فالتام طائقهاالقدیم فاصبحت ما ان یقوم دراها ردفان . اصمعی گوید: طائق چیزی است که از کشتی نمودار باشد مانند تندیی که از کوه فرودآمده باشد.(ذیل اقرب الموارد از اللسان ). رجوع به طائق شود.<br /></font></div>'),
(175710, 'طایقان', '<span class=\"hlight\">طایقان .</span> (اِخ ) یکی از قرای بلخ در خراسان است . (معجم البلدان ). رجوع به طایکان و طائقان شود.<br /></font></div>'),
(175711, 'طایقان', '<span class=\"hlight\">طایقان .</span> (اِخ ) دهی است جزء دهستان پشت گدار بخش حومه ٔ شهرستان محلات، واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی شمال محلات و <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی باختر راه شوسه ٔ قم به اصفهان . کوهستانی و سردسیری است با <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> تن سکنه . آب آن از قنات . محصول آنجاغلات، پنبه، صیفی کاری و انگور. شغل اهالی زراعت و قالیبافی . راه آن مالرو است و از طریق دودهک و خورهه میتوان ماشین برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(175712, 'طایقان', '<span class=\"hlight\">طایقان .</span> (اِخ ) دهی است جزء دهستان اراضی بخش مرکزی شهرستان قم، واقع در <span class=\"hlight\" dir=\"rtl\">٢٥</span>هزارگزی جنوب باختری قم متصل به جاده ٔ قم اصفهان . جلگه ٔ کنار رودخانه وسردسیر با <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> تن سکنه . آب آن از رودخانه . محصول آنجا غلات، پنبه، انار و انجیر. شغل اهالی زراعت و کرباس بافی است . مزرعه محمدآباد، حسین آباد، شاه آباد خرابه جزء این ده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(175713, 'طایقانی', '<span class=\"hlight\">طایقانی .</span> (اِخ ) رجوع به طایگانی شود.<br /></font></div>'),
(175714, 'طایل', '<span class=\"hlight\">طایل .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به طائل شود.<br /></font></div>'),
(175715, 'طایلة', '<span class=\"hlight\">طایلة.</span> <font color=\"DarkGreen\"><b>[ ی ِ ل َ ]</font></b> (ع ص ) تأنیث طایل . رجوع به طایل و طائله شود.<br /></font></div>'),
(175716, 'طایمه', '<span class=\"hlight\">طایمه .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) دهی است از دهستان کمازان شهرستان ملایر، واقع در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی جنوب شهر ملایر و <span class=\"hlight\" dir=\"rtl\">٨</span>هزارگزی راه شوسه ٔ ملایر به اراک . کوهستانی، معتدل و مالاریائی . دارای <span class=\"hlight\" dir=\"rtl\">٨٩٨</span> تن سکنه . آب آن از قنات . محصول آنجا غلات . شغل اهالی زراعت و صنایع دستی زنان قالی بافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(175717, 'طایمه', '<span class=\"hlight\">طایمه .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) دهی است از دهستان پائین شهرستان نهاوند، واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی شمال راه شوسه ٔ نهاوند به کرمانشاه . دامنه و سردسیری است با <span class=\"hlight\" dir=\"rtl\">٥٥٠</span> تن سکنه . آب آن از رودخانه ٔ خرم آباد. محصول آنجا غلات، توتون، حبوبات، انگور و لبنیات . شغل اهالی زراعت و گله داری . راه آن مالرو است و تابستان اتومبیل از وهمان میرود. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(175718, 'طاین', '<span class=\"hlight\">طاین .</span> <font color=\"DarkGreen\"><b>[ی ِ ]</font></b> (ع ص ) انداینده . گِل کار. اندودکننده ٔ بامها.<br /></font></div>'),
(175719, 'طایه', '<span class=\"hlight\">طایه .</span> <font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (اِ) در تداول فارسی، توده ٔ بزرگ سرگین که تون تاب بر بام حمام گِرد کند، تا کم کم آنرا در ماهها یا سالی در تون سوزاند. توده ٔ عظیم خشک کرده ٔسرگین اسب و خر است که برای تون حمام ذخیره کنند.<br /></font></div>'),
(175720, 'طایه', '<span class=\"hlight\">طایه .</span> <font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (اِ) نهالی است که جوشانده ٔ برگ آن نظیر چای است منتهی مطبوعتر. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩</span>).<br /></font></div>'),
(175721, 'طایه زدن', '<span class=\"hlight\">طایه زدن .</span> <font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ زَ دَ ]</font></b> (مص مرکب ) گرد آوردن و ذخیره نهادن سرگین ستور را بر بام حمام .<br /></font></div>'),
(175722, 'طایکی خاتون ترمه بالا', '<span class=\"hlight\">طایکی خاتون ترمه بالا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) از درباریان تیمورقاآن بوده است . رشیدالدین فضل اﷲ بدینسان از وی نام میبرد: چون به بندگی قاآن رسید (اولوس بوقا یکی ازشهزادگان ) او را در گناه آورد که چگونه بر سر مرقد چنگیزخان چنین حرکتی کرده ای و او را مقید و محبوس گردانید، او عذر آورد که گریخته آنجا رسیدم و لشکر دوابر عقب می آمدند با ما آمیخته شدند و غارت کردند. عذرمسموع نیفتاد. طایکی خاتون ترمه بالا و پسر او خیشنک که قاآن با ایشان بغایت بعنایت بود و ایشان اولوس بوقا را که عمزاده ٔ ترمه بالا بود شفاعت کردند و اولوس بوقا را خلاص دادند. (جامعالتواریخ چ بلوشه ص <span class=\"hlight\" dir=\"rtl\">٦٠٧</span>).<br /></font></div>'),
(175723, 'طایگان', '<span class=\"hlight\">طایگان .</span> (اِخ ) شهرکی است در نواحی بلخ از ایالت طخارستان و آنرا طایقان نیز گویند. دارای منبر (مسجد) و بازاری است و دو شعبه از رود جیحون از آن میگذرد و ازاین رو در نهایت سرسبزی و خرمی و آب فراوان است . (از انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «ب »). رجوع به طایقان شود.<br /></font></div>'),
(175724, 'طایگانی', '<span class=\"hlight\">طایگانی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابوالحسن علی بن محمدبن محمد بلخی قاضی طایگانی . وی بعنوان سفر حج به بغداد رفت و در آنجا از شعیب بن ادریس بلخی و ابراهیم بن عبداﷲبن داود رازی استماع حدیث کرد. ابوبکر خطیب بغدادی از او نام برده و گفته است در سال <span class=\"hlight\" dir=\"rtl\">٤٢٣</span> هَ . ق . از وی حدیث نوشته ام، ولی از سرانجام کار او باخبر نیستم . (از انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «ب »).<br /></font></div>'),
(175725, 'طایگانی', '<span class=\"hlight\">طایگانی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) محمدبن قاسم طایگانی از مردم بلخ بود و از عراقیان و همشهریانش روایت کرده است . مردم خراسان اقوالی از او روایت کرده اند که یاد کردن آنها در کتب روا نیست تا چه رسد به این که به روایت او توجه شود و در اخبار روایاتی از وی آمده است که ائمه ٔ حدیث به بطلان و نادرستی ثبوت آنها گواهی داده اند که اصحاب ما از آنها آگاه نیستند، ولی اصحاب رأی درباره ٔ روایات او اظهار نظر کرده اند. از این رو من بدان اشاره کردم تا مردم عوامی که از اصحاب ما هستند به اقوال و روایات او فریفته نشوند. و این گفته ٔ ابوجنان بستی است و من میگویم وی از عمربن هارون و او از داودبن ابوهند و وی از سعیدبن مسیب و او از ابوهریره روایت کرده است که رسول (ص )فرموده است : الرجل الصالح یأتی بالخبر الصالح و الرجل الصالح یأتی بالخبر السوء. ما را بدان خبر داد زاهربن طاهر در نیشابور خبر داد ما را ابوسعید الخبرزردی (کذا) خبر داد ما را ابونصربن ابی مروان الصبی حدیث کرد برای ما ابواحمد محمدبن سلیمان بن فارس دلال حدیث کرد برای ما محمدبن قاسم طایگانی حدیث کرد برای ما عمربن هارون . (از انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «ب »).<br /></font></div>'),
(175726, 'طایگانی', '<span class=\"hlight\">طایگانی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) علی بن محمدبن ... طایگانی . رجوع به ابوالحسن ... طایگانی شود.<br /></font></div>'),
(175727, 'طایگانی', '<span class=\"hlight\">طایگانی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) احمدبن حفص طایگانی . بگفته ٔ ابوسعد ادریسی از مردم طایگان بلخ است . وی از یحیی بن سلیم طایفی روایت کرده است و ابویعقوب یوسف بن علی ابار سمرقندی از وی روایت دارد و روایت رااز طایگانی در سمرقند یا کش فراگرفته است . (از انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «ب »).<br /></font></div>'),
(175728, 'طایی', '<span class=\"hlight\">طایی .</span> (ص نسبی ) طائی . منسوب به طَی ّ. پدر قبیله ای از عرب و قیاس طَیّئی است . (از اقرب الموارد). رجوع به طائی شود.<br /></font></div>'),
(175729, 'طب', '<span class=\"hlight\">طب .</span> <font color=\"DarkGreen\"><b>[ طَب ب ]</font></b> (ع اِمص ) رِفق . ملاطفت . و منه : مَن اَحَب َّ طَب َّ؛ هرکه دوست دارد کاری را، باید که آهستگی و نرمی کند و شتابزدگی نکند. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> فُسون . جادوئی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (ص ) دانا. (منتهی الارب ). نیک ماهر در کار خود. یقال : فلان ٌ طَب ٌ بکذا؛ عالم ٌ به . (منتهی الارب ) (آنندراج ). مرد حاذق . (دهار). پزشک دانابه دارو و علاج و درمان . طبیب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> فحل ٌ طَب ٌ؛ دانا و ماهر در طُرُق ضِراب . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر تیزهوش که تا جای نبیند پای ننهد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(175730, 'طب', '<span class=\"hlight\">طب .</span> <font color=\"DarkGreen\"><b>[ طَب ب <span class=\"hlight\" dir=\"rtl\">/</span> طِب ب <span class=\"hlight\" dir=\"rtl\">/</span> طُب ب ]</font></b> (ع اِ) داروی اندام . داروی نفس . (منتهی الارب ) (آنندراج ). و فی المثل قرب طِب ٌ. و یروی طبّا. و الاصل ان رجلا تزوج اِمراءة، فهدیت الیه، فلما قعد منها مقعدالرجال من النساء، قال : ابکرٌ انت ام ثیب ٌ، فقالت المثل . (منتهی الارب ) (تاج العروس ). طب (بحرکات ثلاث ) در لغت سحر است، چنانکه در منتخب گفته . (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> (مص ) دوختن درز مشک به دوال . یقال : طببت ُ السقاء طباً. <BR><font color=\"Blue\">◄</font> دارو کردن و قولهم : اِن کنت ذا طب فطب عینک ؛ اگر دارو کنی چشم خویش دارو کن . <BR><font color=\"Blue\">◄</font> جادویی کردن : طب الرجل ؛ جادوی کرده شد. (منتهی الارب ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175731, 'طب', '<span class=\"hlight\">طب .</span> <font color=\"DarkGreen\"><b>[ طِب ب ]</font></b> (ع اِ) شهوت . خواهانی تن . <BR><font color=\"Blue\">◄</font> شأن . حال مرد. دَهر. خُوی . عادت . یقال : ماذاک بطبی ؛ ای بدهری و عادتی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> سحر. (غیاث اللغات ) (آنندراج ). جادوئی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (مص ) علاج کردن . دارو کردن . علاج جسم و نفس . <BR><font color=\"Blue\">◄</font> (اِمص، اِ) پچشکی . (منتهی الارب ) (آنندراج ) (دهار). علم طب، از علوم طبیعیه ٔ قدماء. علم ابدان . نگاه داشتن تندرستی است بر تندرستان و زائل کردن بیماری است از بیماران . (تعریفات سیدجرجانی ). اساوة. معالجه کردن . علمی که بدان احوال تن آدمی شناسند از درستی و نادرستی آن <span class=\"hlight\">:</span> <br />تا میر به بلخ آمد، با آلت و با عُدّت <br />بیمارشده ملکت برخاست ز بیماری <br />اکنون که طبیب آمد نزدیک به بالینش <br />بهتر شودش درد و کمتر شودش زاری <br />یک هفته زمان باید، لا بلکه دوسه هفته <br />تا دور توان کردن، زو سختی و دشواری <br />بروی نتوان کردن، تعجیل به بِه ْ کردن <br />تعجیل به طب اندر، باشد ز سبکساری .<br /> <font color=\"Red\">منوچهری .</font><br />طب پدر ترا ندهد نفعی <br />تو چونکه گر خویش همی خاری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و در کتب طب هم اشارتی دیده نیامده . (کلیله و دمنه ). که در کتب طب چنین یافته میشود که آبی که اصل آفرینش فرزند آدم است، چون برحم پیوندد... تیره و غلیظ شود. (کلیله و دمنه ).<br />هان برو برخوان کتاب طب را<br />تا شمار ریگ بینی رنجها.<br /> <font color=\"Red\">مولوی .</font><br />صاحب کشاف اصطلاحات الفنون آرد: علم بقوانینی است که بدان چگونگی بدن انسان از لحاظ تندرستی و عدم آن شناخته شود تا سلامت موجود حفظ گردد و آنچه حاصل نیست تا حد امکان به دست آید و فواید قیود در تعریف آشکار است، زیرا (علم ) جنس است و «شناخته شود...» فصل است و بدان اموری که بوسیله ٔ آنها کیفیت بدن آدمی شناخته نشود خارج میگردد. و از اینکه گفتیم «از لحاظ تندرستی و عدم آن » علمی خارج میشود که بدان کیفیات بدن آدمی شناخته میشود اما نه از دو نظر مزبور؛ مانند علم اخلاق و کلام و اینکه گفتیم تا «سلامت موجود حفظ گردد» بیانی برای غایت طب است بجهت احتراز و این بیان ما از گفتار کسانی که گفته اند: «از لحاظ آنچه تندرستی آرد و سلامت را زایل کند» بهتر است چه بر این گفته ایراد میشود که درباره ٔ جنین ناسالم از آغاز فطرت درست نیست گفته شود:تندرستی از آن زایل شده است . در سدیدی شرح موجز چنین است . و در شرح قانونجه آرد: طب علم به احوال بدن انسان است از جهت صحت و مرض تا بدان صحت حفظ شود یا تا حد امکان اعاده گردد و دیگری در تعریف آن گوید: دانش پزشکی، علمی است که در آن درباره ٔ بدن آدمی از لحاظ تندرستی و بیماری به منظور حفظ صحت و ازاله ٔ مرض گفتگو میشود و موضوع آن عبارت است از بدن انسان و هرآنچه بر بدن مشتمل شود، مانند: ارکان و امزجه و اخلاط و اعضا و ارواح و قوی و افعال و احوال تن از نظر تندرستی و بیماری و موجبات آن همچون خوردنیها و آشامیدنیها و هواهای محیط بر بدن و حرکات و سکنات و استفراغات و احتقانات و صناعات و عادات و واردات غریب و علاماتی که بر احوال هر یک دلالت کند، همچون : زیان افعال و حالات بدن و آنچه از آن بروز کند و چاره به خوردنیها و آشامیدنیها و برگزیدن هوای سالم و سنجش حرکت وسکون و داروهای بسیط و مرکب و اعمال ید بمنظور حفظ صحت و درمان بیماریها بر حسب امکان . (مقدمه ٔ کشاف اصطلاحات الفنون ج <span class=\"hlight\" dir=\"rtl\">١</span>). در همان کتاب ذیل کلمه ٔ (طب ) آمده : بحرکات سه گانه و تشدید با در لغت بمعنی سحر است، چنانکه در منتخب آمده است و در اصطلاح، علم به قوانینی است که بتوسط آنها احوال بدن انسان از نظر تندرستی و بیماری شناخته شود و صاحب این دانش را طبیب نامند. حاجی خلیفه آرد: باید دانست که تحقیق و آغاز پدید آمدن طب دشوار است از این جهت که از روزگارهای دور ودراز این دانش متداول بوده و دیگر بسبب اختلاف آراء پیشینیان و نبودن مرجعی برای برگزیدن یکی از اقوال، چنانکه گروهی به قدمت آن قائلند و آنانکه بحدوث اجسام معتقدند طب را نیز حادث دانند و ایشان دو گروه اند:نخست کسانی که گویند طب با انسان آفریده شده و دوم آنانکه برآنند این دانش پس از آفرینش آدمی استخراج شده است . و بیشتر دانشمندان پیرو این نظریه اند و در چگونگی استنباط آن گویند یا از جانب خدای سبحانه و تعالی بر آدمی الهام شده است و این عقیده ٔ بقراط و جالینوس و جمیع اصحاب قیاس و شعرای یونان است . و یا بسبب تجربه ٔ مردم پدید آمده است، و این رای اصحاب تجربه و حیل و ثاسلس مغالط و فیلن است و ایشان را در مقام استخراج آن و اینکه به چه وسیله استخراج شده است اختلاف نظر است برخی گویند مردم مصر آنرا کشف کرده و بوسیله ٔ داروی موسوم به راسن بیماران را بهبود می بخشیده اند، و گروهی برآنند که هرمس طب را با دیگر صنایع کشف کرده و دسته ٔ دیگر گفته اند مردم فولس به استخراج آن نائل آمده اند و بقولی اهل مورسیا و افروجیا آنرا کشف کرده اند و ایشان نخستین کسانی هستند که زمر (غنا) را نیز ابداع کرده اند ودردهای روحی را با الحان و ایقاعات درمان میکرده اند. و برخی گفته اند مردم قوه ٔ طب را کشف کرده اند و قوه جزیره ای است که بقراط و نیاکان وی در آن میزیسته اند. و بسیاری از متقدمان گفته اند که طب در سه جزیره پدید آمده است : نخست رودس دوم فیندس و سوم قوه . و بقولی کاشف طب کلدانیان بوده اند و بقول دیگر ساحران یمن .و برخی گویند در بابل کشف شده است و گروهی گفته اند طب را ایرانیان کشف کرده اند و هم گفته اند هندیان و بقولی صقالبه (اسلاوها) و برای گروهی مردم اقریطش (کرت ) و بقولی مردم طور سینا کاشف آن بوده اند. و کسانی که قائل به الهام شده اند نیز درباره ٔ چگونگی الهام آرای مختلفی دارند. برخی گویند طب در عالم رؤیا الهام شده است، و چنین استدلال میکنند که جماعتی داروهائی در حال رؤیا دیده اند و سپس در بیداری آنها را بکار برده و از بیماریهای صعب شفا یافته اند و از آن پس هربیمار دیگری نیز آن داروها را استعمال کرده، بهبود یافته است . و گروهی گویند خدا سبحانه و تعالی از راه تجربه طب را الهام کرده است و قومی گفته اند خدا سبحانه و تعالی طب را آفریده است ؛ زیرا ممکن نیست عقل آدمی آنرا دریابد و این نظر جالینوس است که صاحب عیون الانباء آنرا نقل کرده است . و اما رای صواب در نظر مااین است که خدا سبحانه و تعالی صناعت طب را آفریده و آنرا بمردم الهام کرده است و آن بزرگتر از آن است که عقل آدمی به درک آن برسد؛ زیرا بنظر ما طب از فلسفه پست تر نیست در صورتی که معتقدند فلسفه از نزد خدابمردم الهام شده است . بنابراین طب هم از جانب خدا سبحانه و تعالی به وحی و الهام پدید آمده است . ابن ابوصادق در آخر شرحی که بر مسائل حنین نوشته گوید: مردم را در روزگارهای گذشته چنین یافتم که بعلم طب قانعنمیشدند جز اینکه بر تمام اجزای این دانش و قوانین طرق قیاس و برهان که در همه دانشها دانستن آنها ضرورت دارد احاطه یابند؛ ولی پس از آنکه همت آنان از این هدف قاصر آمد اجماع کردند که هرکه در این دانش ممارست میکند کافی است احکام <span class=\"hlight\" dir=\"rtl\">١٦</span>گانه ٔ کتاب جالینوس را فراگیرد و این احکام را مردم اسکندریه برای متعلمانی که از خاندانهای شریف بشمار میرفتند تلخیص کرده بودند. و آنگاه که همت مردم از این مقدار هم قاصر آمد اهل معرفت آنان را که به معلوماتی از طب قانع میشدند بی آنکه در آن مهارت یابند به فراگرفتن کتبی از اصول طب توصیه میکردند که عبارت بودند از:<br /><span class=\"hlight\" dir=\"rtl\">١</span> - مسائل حنین .<br /><span class=\"hlight\" dir=\"rtl\">٢</span> - کتاب الفصول بقراط<br /><span class=\"hlight\" dir=\"rtl\">٣</span> - یکی از دو کناش جامع درمان که بهترین آن کناش ابن سرافیون بود. و نخستین کسی که در جهان دانش پزشکی از وی شیوع یافت اسقلنبیوس <font color=\"DarkGreen\"><b>[ اسقلبیوس ]</font></b> بود.او <span class=\"hlight\" dir=\"rtl\">٤٠</span> سال از عمر خویش را بعنوان عالم و معلم طب سپری کرد و دو فرزند ماهر در طب از خویش به یادگار گذاشت و آنان را ملتزم کرد که طب را جز به فرزندان خویش به دیگری نیاموزند و به آنان توصیه کرد که ایشان نیز فرزندان خود را به همین شیوه ملتزم کنند و این شرطدر خاندان آنان همواره مراعات شود تا مبادا طب از خاندان ایشان به دیگری منتقل گردد. و ثابت گوید: اسقلنبیوس <font color=\"DarkGreen\"><b>[ اسقلبیوس ]</font></b> در سراسر جهان <span class=\"hlight\" dir=\"rtl\">١٢</span>هزار شاگرد داشت و او طب را به طریق شفاهی تعلیم میداد. و خاندان اسقلنبیوس صناعت طب را به وراثت از یکدیگر فرامی گرفتندتا بقراط در این امر نگران شد و مشاهده کرد که خاندان و پیروان او تقلیل یافته اند و بیم آن میرود که صناعت طب منقرض شود از این رو وی بطریق ایجاز بتألیف کتب طب آغاز کرد. و علی بن رضوان گوید: صناعت طب پیش از بقراط بمنزله ٔ گنجینه و ذخیره ای بود که پدران آنرا میاندوختند و همچون گنجینه ای به فرزندان خویش میسپردند و تنها یک خاندان در آن مهارت داشتند که منسوب به اسقلنبیوس بودند و این کلمه «اسقلنبیوس » یا نام فرشته ای بوده که خدا سبحانه و تعالی وی را برانگیخته تا مردم را پزشکی آموزد یا نام قوّه ای از خدای تعالی است که مردم را پزشکی آموخته است . و نسبت نخستین آموزنده ٔ طب به متعلم (معلم اول ) بر حسب عادت قدما نسبت فرزند به پدر بوده است و خاندانی که منسوب به اسقلنبیوس بوده اند از آن معلم اول توالد و تناسل کرده اند.و پادشاهان و بزرگان یونان ممکن نبود جز به فرزندان خویش به دیگری پزشکی بیاموزند و روش تعلیم ایشان به فرزندان خویش به مکالمه و شفاهی بدون تدوین بوده است و اگر به تألیف آن ناگزیر میشدند آنرا بشیوه ٔ لغزو معما تدوین میکردند تا بجز خود آنان دیگری آنرا نفهمد، و آن وقت پدران آن لغزها را برای فرزندان خویش تفسیر میکردند و دانش طب تنها در میان پادشاهان و پارسایان بود و آنرا بقصد احسان به مردم بدون گرفتن اجر و پاداشی پیشه ٔ خویش میساختند و این روش همچنان ادامه داشت تا هنگامی که بقراط از مردم (قوه ) و ذمقراط از اهالی (اندرا) پدید آمدند و این دو تن با هم معاصر بودند. ذمقراط همچنان از تدوین طب امتناع ورزید، ولی بقراط از بیم اینکه مبادا آن دانش از دست برود بر آن شد که این علم را در کتابی تدوین کند. و او دوفرزند به نام های ثاسبسالس و درافن و شاگردی موسوم به فولونس داشت و برای این دانش عهد و قانون و وصیتی وضع کرد که بوسیله ٔ آنها پزشک به کلیه ٔ نیازمندیهای خویش آگاه میشد. (از کشف الظنون چ <span class=\"hlight\" dir=\"rtl\">١٩٤٣</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٩٢</span>). در قاموس مقدس آمده که چون عبرانیان در مصر سکونت داشتند، قدری از علم طبابت از آن قوم آموخته بودند، زیرا که علم مذکور در آن زمان در آن مملکت معروف بود، و از جمله ٔ وسایط و جهاتی که اسباب ترقی ایشان در علم طب میشد حنوط و تدهین اموات بود که ناچار بودند ابدان اموات را تشریح کنند، و بدان وسیله علم و اطلاع تامی به اعضاء و اجزای ظاهری و باطنی بدن بهم میرساندند، و بطوری در طب و جراحی شهرت و مهارت داشتند که کورش و داریوش همواره طبیبان را از مصر برای مداوا و معالجه ٔ امراض میطلبیدند. و از قراری که از اجساد اموات مومیائی مستفاد است، مصریان در معالجه ٔ دندان یدطولائی داشته اند، و البته واضح است که حضرت موسی (ع )هم در مدت توقف خود در آنجا در مبادی علم طب دست یافت، چنانکه از قواعد و قوانینی که برای حفظ صحت بنی اسرائیل قرار داده است معلوم میشود. و نتیجه ٔ قوانین مرقومه آنکه بنی اسرائیل به امراض بسیاری که همسایگان ایشان بدانها مبتلا میشدند، مبتلا نمیگردیدند، و با وجودی که علم تشریح در میان بنی اسرائیل معروف نبود، چون که از اجساد اموات همواره نفرت میورزیدند، باز درمیان ایشان قابله های قابل و جراحان حاذق یافت میشد و در شریعت موسویه وارد است که اگر کسی شخصی را اذیت و آزار نمود، بطوری که او را بستری ساخت، البته باید عوض آنرا متحمل شود، و مخارج مداوای وی، یعنی حق طبابت او را بدهد. (سفر خروج <span class=\"hlight\" dir=\"rtl\">٢١</span>:<span class=\"hlight\" dir=\"rtl\">١٩</span>) و در ایام ملوک، عدد اطبا بیفزود. (<span class=\"hlight\" dir=\"rtl\">٢</span> تواریخ ایام <span class=\"hlight\" dir=\"rtl\">١٦</span>:<span class=\"hlight\" dir=\"rtl\">١٢</span>) (ارمیا <span class=\"hlight\" dir=\"rtl\">٨</span>:<span class=\"hlight\" dir=\"rtl\">٢٢</span>) همچنین در ایام خداوند ما عیسی مسیح نیز طبیبان بسیار بودند. (مرقس <span class=\"hlight\" dir=\"rtl\">٥</span>:<span class=\"hlight\" dir=\"rtl\">٢٦</span>) و در خود هیکل طبیب مخصوص، ودر هر مقاطعه ای طبیب و جراح مخصوصی بود. و حضرت سلیمان حکیم در فن پزشکی معروف بوده اشارت طبیه ٔ متعدده در مؤلفات حضرتش یافت میشود: امثال سلیمان <span class=\"hlight\" dir=\"rtl\">٣</span>:<span class=\"hlight\" dir=\"rtl\">٨</span> و <span class=\"hlight\" dir=\"rtl\">٦</span>:<span class=\"hlight\" dir=\"rtl\">١٥</span> و <span class=\"hlight\" dir=\"rtl\">١٢</span>:<span class=\"hlight\" dir=\"rtl\">١٨</span> و <span class=\"hlight\" dir=\"rtl\">١٧</span>:<span class=\"hlight\" dir=\"rtl\">٢٢</span> و <span class=\"hlight\" dir=\"rtl\">٢٠</span>:<span class=\"hlight\" dir=\"rtl\">٣٠</span> و <span class=\"hlight\" dir=\"rtl\">٢٩</span>:<span class=\"hlight\" dir=\"rtl\">١</span> و تلمودیان گویند که وی را کتاب معالجات نیز بوده است، لکن یوسیفوس گوید که آن حضرت طلسمها و حرزها را مثل قدیمیان استعمال مینمود، و برخی از اوقات بعضی مطالب طبیه و دانش آنها از کهنه مطلوب بود، و اعتنا به حفظ صحت خود مینمودند. (دوم پادشاهان <span class=\"hlight\" dir=\"rtl\">٢</span>:<span class=\"hlight\" dir=\"rtl\">٧</span>) و در ایام عهد جدید تمام آراء و خیالات راجع به طب منسوب به یونانیها بود که ایشان نیز از مصریان اقتباس نموده، و در آنها مهارت تامی به هم رسانیده بودند، و بر وفق رساله ٔ کولسیان <span class=\"hlight\" dir=\"rtl\">٤</span>:<span class=\"hlight\" dir=\"rtl\">١٤</span> لوقا طبیب بود، و قبل از آنکه به کلیسای مسیحی دعوت شود، این فن شریف را ممارست مینمود. از جمله امراضی که در کتاب مقدس مذکور است، یکی ضعف چشم (سفر پیدایش <span class=\"hlight\" dir=\"rtl\">٢٩</span>:<span class=\"hlight\" dir=\"rtl\">١٧</span>) و کوری، (دوم پادشاهان <span class=\"hlight\" dir=\"rtl\">٦</span>:<span class=\"hlight\" dir=\"rtl\">١٨</span>) و بسته شدن رحم، یا عقیم بودن . (سفر پیدایش <span class=\"hlight\" dir=\"rtl\">٢٠</span>:<span class=\"hlight\" dir=\"rtl\">١٨</span>) که برای آن مهر گیاه استعمال میکردند. (سفر پیدایش <span class=\"hlight\" dir=\"rtl\">٣٠</span>:<span class=\"hlight\" dir=\"rtl\">١٤</span> - <span class=\"hlight\" dir=\"rtl\">١٦</span>)و دُمل . (سفر لاویان <span class=\"hlight\" dir=\"rtl\">١٣</span>:<span class=\"hlight\" dir=\"rtl\">١٨</span>) و کوژپُشتی و کوتاه قدی ولکه ٔ چشم و جرب و گری و شکسته بیضه . (سفر لاویان <span class=\"hlight\" dir=\"rtl\">٢١</span>:<span class=\"hlight\" dir=\"rtl\">١٩</span>) و شکسته و آبله دار. (سفر لاویان <span class=\"hlight\" dir=\"rtl\">٢٣</span>:<span class=\"hlight\" dir=\"rtl\">٢٢</span>). دمل مصر و بواسیر و خارش و دیوانگی . (سفر تثنیه <span class=\"hlight\" dir=\"rtl\">٢٨</span>:<span class=\"hlight\" dir=\"rtl\">٢٧</span> و <span class=\"hlight\" dir=\"rtl\">٢٨</span>) و دمل بد. (انجیل متی <span class=\"hlight\" dir=\"rtl\">٢٨</span>:<span class=\"hlight\" dir=\"rtl\">٣٥</span>) و برص و فالج و تب و صرع و ضربةالشمس دوم پادشاهان <span class=\"hlight\" dir=\"rtl\">٤</span>:<span class=\"hlight\" dir=\"rtl\">١٩</span> و از جمله ٔ علاجهائی که برای امراض مذکوره مستعمل بود اقسام روغنها و شربتها و عسل و شیر و روغن زیتون و خشخاش و بهار و صفراءالسمک و غار و نمک و لعابیات . و بسا میشد که آب خالص را برای علاج استعمال میکردند (سفر لاویان <span class=\"hlight\" dir=\"rtl\">١٥</span>:<span class=\"hlight\" dir=\"rtl\">١٣</span> و دوم پادشاهان <span class=\"hlight\" dir=\"rtl\">٥</span>:<span class=\"hlight\" dir=\"rtl\">١٠</span>). (قاموس کتاب مقدس ). لاروس بزرگ آرد: دانش پزشکی از روزگارهای ماقبل تاریخ آغاز میگردد. این دانش در آغاز بی آنکه به علم تشخیص بیماریها توجه داشته باشد تنها به کار درمان می پرداخت و خاص طبقه ٔ رؤسا، پادشاهان، شاعران و به ویژه روحانیان بود. نخستین رساله ٔ مربوط به روش درمان و مداوا تحت حمایت و توجه چین ننگ امپراطور چین در <span class=\"hlight\" dir=\"rtl\">٢٧٠٠</span> ق . م . مسیح منتشر گردید. در یونان، اسقلبیوس خداوند طب شناخته شد و کشیشانی که مروج آئین او بودند و اسقلبیوسی نامیده میشدند کشیش طبیب شدند. دیری نگذشت دو مکتب مختلف که رقیب یکدیگر بودند بوجود آمد یکی مکتب کنیدس و دیگری مکتب کس که در آن بقراط تدریس میکرد و از زمان وی دوره ٔ علمی طب آغاز گردید و استقرار یافت و از آن تاریخ علم طب بر اساس مطالعات مستقیم علمی قرار گرفت، سپس مکتب اسکندریه پدید آمد و در آن هروفیلوس و اراسیسطراطس کالبدشناسی توصیفی را بنیان گذاری کردند و برای نخستین بار به تشریح پرداختند. این دوره تا روزگار جالینوس همچنان ادامه یافت، آنگاه قوه ٔ تصور و هوش تند و اندیشه ٔ ظریف و عمیق جالینوس وی را پایه گذار اصول خاصی ساخت که تا دیرزمانی پابرجا ماند. در قرون وسطی مسیحیت از طریق منع تشریح که آنراعملی پلید تلقی میکرد مانع پیشرفت طب گردید. معهذا دانشمندان کشورهای اسلامی از آنجمله (ابن سینا و ابوالقاسم و چند تن دیگر) سنن گذشته را حفظ کردند و بر اطلاعات خویش افزودند. در دوره ٔ رنسانس به متون قدیمی مراجعه شد و پاراسلس به متون مزبور حیات نوینی بخشید. پس از وی به کمک مردانی مانند وزال، آمبروازپاره، استاش، فالوپ، وارول و دیگران علم تشریح به پیشرفت قابل ملاحظه ای نائل آمد، و در نتیجه، بیماری های داءالعرق و تیفوس و سیاه سرفه شرح و تفسیر شد. در قرن هفدهم میلادی، تحت تأثیر عقاید و افکار فلسفی علم طب به پیشرفت خود ادامه داد و در آن موقع سه مکتب طبی بدینسان بوجود آمد:<br /><span class=\"hlight\" dir=\"rtl\">١</span> - طب کیمیاوی از سیلویوس . <span class=\"hlight\" dir=\"rtl\">٢</span>- طب مکانیکی از برلی . <span class=\"hlight\" dir=\"rtl\">٣</span> - طب حیاتی از اشتال کمی بعد هاروی گردش خون (دوران دم ) را که اکتشافی بسیار مهم و جاویدان میباشدکشف کرد و اسلی و پکه به کشف طریقه و دستگاه لنفاوی نائل آمدند. و باری لونهوئک ذره بین (میکرسکپ ) را کشف کرد. در اواخر قرن هیجدهم میلادی و اوایل قرن نوزدهم، لاوازیه به کشفیاتی در شیمی نائل آمد که در نتیجه علم وظایف الاعضاء بر پایه ٔ نوینی استوار شد، و کمی بعد به کمک نظریات پینل و بیئو و کرویسار شیوه ٔ تفکری که مبتنی بر اصول قواعد معینی بود از دانش پزشکی حذف گردید. لائنک امتحان ضربان قلب را کشف کرد و در همان ایام بویان، رستان، رایه، اندرال، تروسو و ریکر طب را بصورت دانشی تجربی درآوردند. آنگاه پاستور با کشف علم میکرب شناسی راه نوینی را که تا آن روز دانشمندان بدان پی نبرده بودند به روی دانش طب بازکرد و در نتیجه، طب و جراحی به پیشرفت عظیمی نایل آمد و در همان روزگار دانش شیمی و فیزیک به صحت علم تشخیص امراض کمک بسزائی کرد و تزریقات زیرجلدی نیز کار استعمال دارو را آسان تر ساخت، و خلاصه در حدود سال <span class=\"hlight\" dir=\"rtl\">١٩٢٠</span> م . اصول درمان و پیشگیری از امراض بوسیله ٔ سرم و معالجه از طریق استعمال عصاره ٔ بعض اعضا بوجود آمد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طب تجربی </span> ؛ پزشکی آزمایشی . (فرهنگستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طب حیاتی </span> ؛ یکی از سه مکتب طب در قرن <span class=\"hlight\" dir=\"rtl\">١٧</span> میلادی که پایه گذار آن اشتال بوده است . رجوع به طب شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طب روحانی </span> ؛ (اصطلاح تصوف ) طب روحانی علمی است به کمالات قلوب و امراض آن و دوای آن و کیفیت حفظ صحت آن و اعتدال جسمانی وروحانی آن، و رد امراض که متوجه است بسوی آن قلب . وطبیب در اصطلاحشان شیخی باشد که عارف بود به طب روحانی، و قادر باشد بر ارشاد و تکمیل قلب . (کشاف اصطلاحات الفنون ). بباید دانست که تدبیر حاصل کردن منفعت آنچه نافع بود از اعراض نفسانی، و دفع مضرت آنچه مضرت است، طبیبان این را طب روحانی گویند. (ذخیره ٔ خوارزمشاهی ). دانش به کمالات دلها و آفات و امراض و داروهای آن و دانستن چگونگی حفظ صحت و اعتدال وی . (از تعریفات جرجانی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طب کیمیاوی </span> ؛ یکی از سه مکتب طبی که در قرن هفدهم میلادی بوجود آمد و پایه گذار آن سیلویوس بود. رجوع به طب شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طب مکانیکی </span> ؛ یکی از سه مکتب طب در قرن هفدهم میلادی که پایه گذار آن برلی بوده است . رجوع به طب شود.<br /></font></div>'),
(175732, 'طب', '<span class=\"hlight\">طب .</span> <font color=\"DarkGreen\"><b>[ طِب ب ]</font></b> (اِخ ) نام شهری است . رجوع به تب شود.<br /></font></div>'),
(175733, 'طب', '<span class=\"hlight\">طب .</span> <font color=\"DarkGreen\"><b>[ طُب ب ]</font></b> (اِخ ) موضعی است . (منتهی الارب ).<br /></font></div>'),
(175734, 'طبا', '<span class=\"hlight\">طبا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) نوشادر. (فهرست مخزن الادویه ).<br /></font></div>'),
(175735, 'طبا', '<span class=\"hlight\">طبا.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) دیهی است از دیه های یمن . (معجم البلدان ). و منسوب بدان طبائی است . (سمعانی ).<br /></font></div>'),
(175736, 'طباب', '<span class=\"hlight\">طباب .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ج ِ طبابة. <BR><font color=\"Blue\">◄</font> ج ِ طبیبة.<br /></font></div>'),
(175737, 'طبابات', '<span class=\"hlight\">طبابات .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ج ِ طباب . <BR><font color=\"Blue\">◄</font> ج ِ طبابة.<br /></font></div>'),
(175738, 'طبابة', '<span class=\"hlight\">طبابة.</span> <font color=\"DarkGreen\"><b>[ طِ ب َ ]</font></b> (ع اِ) نورد ابر. <BR><font color=\"Blue\">◄</font> ریگ . <BR><font color=\"Blue\">◄</font> دراز از زمین و ابر و چرم . (منتهی الارب ) (آنندراج ). زمین .هامون در یکدیگر پیوسته . (مهذب الاسماء). ج، طباب، طبابات . جج، اَطبه . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> جامه ٔ پیش گشاده ٔ درازدامن . <BR><font color=\"Blue\">◄</font> دوال که درزهای مشک به وی گیرند. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> مغز که کفشگر در میان درز گیرد. (مهذب الاسماء). السیر الذی یکون فی اسفل القربة بین الخرزتین . (منتهی الارب ). مَغزی . زِه . <BR><font color=\"Blue\">◄</font> طبابةالمساء و طبابها؛ طره ٔ دراز آسمان که بر افق نمایان باشد. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِمص ) پچشکی . (منتهی الارب ) (آنندراج ). پژشکی . پزشکی . رجوع به طب شود.<br /></font></div>'),
(175739, 'طبابة', '<span class=\"hlight\">طبابة.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ع اِ) کباب . طباهیج . تاهه . <BR><font color=\"Blue\">◄</font> گوشت پخته ٔ نرم و نازک .<br /></font></div>'),
(175740, 'طبابت', '<span class=\"hlight\">طبابت .</span> <font color=\"DarkGreen\"><b>[ طِ ب َ ]</font></b> (ع اِ) رجوع به طبابة شود.<br /></font></div>'),
(175741, 'طبات', '<span class=\"hlight\">طبات .</span> <font color=\"DarkGreen\"><b>[ طَب ْ با ]</font></b> (اِخ ) موضعی است که عساکر مدیانیان از حضور جدعون بدانجا فرار نمودند. (سفر داوران <span class=\"hlight\" dir=\"rtl\">٧</span>:<span class=\"hlight\" dir=\"rtl\">٢٧</span>) و گروف گمان دارد که ارتفاعش تخمیناً <span class=\"hlight\" dir=\"rtl\">٦٠</span> قدم و بطرف اردن مقابل بیان واقع است . (قاموس کتاب مقدس ).<br /></font></div>'),
(175742, 'طباخ', '<span class=\"hlight\">طباخ .</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِمص ) استواری . <BR><font color=\"Blue\">◄</font> توانائی . (منتهی الارب ) (آنندراج ). قوت . (مهذب الاسماء) <BR><font color=\"Blue\">◄</font> فربهی . (منتهی الارب ) (آنندراج ) (مهذب الاسماء).<br /></font></div>'),
(175743, 'طباخ', '<span class=\"hlight\">طباخ .</span> <font color=\"DarkGreen\"><b>[ طَب ْ با ]</font></b> (ع ص ) پزنده . باورچی . (منتهی الارب ) (آنندراج ) (غیاث اللغات ). خورشگر. خوالیگر. (دهار). مطبخی . آشپز. خوردنی پز. خوراک پز. دیگ پز. طابخ : عجاهن ؛ طباخ . (منتهی الارب ).<br />مرد طباخ و نعمت بسیار.<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(175744, 'طباخ', '<span class=\"hlight\">طباخ .</span> <font color=\"DarkGreen\"><b>[ طَب ْ با ]</font></b> (اِخ ) محمد راغب الطباخ . مورخ مشهورمعاصر، اهل حلب و مؤلف اعلام النبلاء در تاریخ حلب است و آن کتابی است در هفت مجلد که در سال <span class=\"hlight\" dir=\"rtl\">١٣٤١</span> هَ . ق . شروع به طبع آن کتاب کرده و جزء هفتم آن در سال <span class=\"hlight\" dir=\"rtl\">١٣٤٥</span> هَ . ق . پایان یافت . این کتاب حاوی تراجم ادبا و اعیان حلب میباشد. و نیز المطالب العلیة فی الدروس الدینیه از تألیفات اوست . و قسم اول از دروس دینیه ٔ این کتاب در مطبعةالبهاء حلب بطبع رسیده در سال <span class=\"hlight\" dir=\"rtl\">١٣٣٠</span>هَ . ق . این ادیب دانشمند به نشر کتب جلیله ٔ دیگری نیز اقدام ورزیده است که شرح آنها در جامعالتصانیف الحدیثة آمده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٦٥٥</span>).<br /></font></div>'),
(175745, 'طباخی', '<span class=\"hlight\">طباخی .</span> <font color=\"DarkGreen\"><b>[ طَب ْ با ]</font></b> (حامص ) آشپزی . باورچیگری . دیگ پزی . طباخة.<br /></font></div>'),
(175746, 'طباخیة', '<span class=\"hlight\">طباخیة.</span><font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُ ی َ ]</font></b> (ع ص ) زن جوان پرگوشت . (منتهی الارب )(آنندراج ). زن جوان آگنده گوشت . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> زن دانای ملیحه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(175747, 'طبار', '<span class=\"hlight\">طبار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) (بنات ...) بلاها و سختیها. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(175748, 'طبار', '<span class=\"hlight\">طبار.</span> <font color=\"DarkGreen\"><b>[ طُب ْبا ]</font></b> (ع اِ) درختی است مانا به درخت انجیر. (منتهی الارب ) (آنندراج ). صنفی از انجیر بزرگ سرخ است . (اختیارات بدیعی ). قسمی انجیر بزرگ سرخ فام . نوعی از انجیرسرخ بزرگ . (فهرست مخزن الادویه ). در برهان آمده است :طِبار نوعی از انجیر است و آن سرخ و بزرگ میباشد.<br /></font></div>'),
(175749, 'طبارتیس', '<span class=\"hlight\">طبارتیس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) مُلکت طبارتیس چهارسال بوده است . آن است که کوشکهای عظیم کرده است . ونشستنگاهها که هر جائی از آن در زر افکند. و بعضی را سیم و بعضی مس . و عجائب تر بناها. (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">١٣٦</span>) . این نام مصحف طباریس (تیبر) است و وی از امپراطوران روم شرقی (بیزانس ) است که از سال <span class=\"hlight\" dir=\"rtl\">٥٧٨</span> تا <span class=\"hlight\" dir=\"rtl\">٥٨٢</span> م . سلطنت داشت .<br /></font></div>'),
(175750, 'طباره', '<span class=\"hlight\">طباره .</span> <font color=\"DarkGreen\"><b>[ طَ رَ هَْ ]</font></b> (اِخ ) محمد عیسی . او راست کتابی در فقه به نام «الاساس » که در مطبعه ٔ ادبیه ٔ بیروت بسال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> هَ . ق .بطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٦</span>).<br /></font></div>'),
(175751, 'طباریس', '<span class=\"hlight\">طباریس .</span> <font color=\"DarkGreen\"><b>[ ی ُ ]</font></b> (اِخ ) طباریوس . نام یکی از امپراطوران روم . مؤلف مجمل التواریخ والقصص آرد: ملکت طباریس : بیست و دو سال بوده است، و اندر روزگار او عیسی علیه السلام بر آسمان بردند، بعد از آن سه سال در پادشاهی بماند، ملکت طباریس چهار سال بوده است و او را هیچ ذکری نخوانده ایم که از آن چیزی نقل شایستی کردن . (مجمل التورایخ صص <span class=\"hlight\" dir=\"rtl\">١٢٨</span> - <span class=\"hlight\" dir=\"rtl\">١٢٩</span>). در تاریخ حمزه ٔاصفهانی این نام بصورت طباریس غابس آمده . (ایضاً ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span>). طباریس یا تیبر دومین امپراطور روم پسر لیوی و فرزندخوانده ٔ اغسطس، پادشاهی روشنفکر، محتاط و لایق بود، ولی بعلت سوء ظن و تحت نفوذ وزیر خود موسوم به سژان مرتکب شقاوتهای بسیار شد. مولدوی روم (<span class=\"hlight\" dir=\"rtl\">٤٢</span> ق . م . و وفات <span class=\"hlight\" dir=\"rtl\">٣٧</span> م .).<br /></font></div>'),
(175752, 'طباریوس', '<span class=\"hlight\">طباریوس .</span><font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) طباریس . رجوع به طباریس و قاموس الاعلام ترکی شود. در حبیب السیر این نام به غلط طبارنوس آمده : طبارنوس بعد از وفات افسطوس بر مسند خسروی نشست . و در سال هفتم از جهانبانی او «هردست » یا «هردوس » که در سلک اعاظم امرا انتظام داشت، بلده ٔ طبریه را بنانهاد. و به روایت تحفةالملکیه، در سال نوزدهم از پادشاهی او رفع عیسی علیه السلام اتفاق افتاد. و طبارنوس بیست و دو سال سلطنت کرد. بعد از فوتش یک سال و نیم سریر سلطنت روم از وجود پادشاهی صاحب حشمت خالی بود.(حبیب السیر چ قدیم ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٦</span> و چ خیام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٥</span>).<br /></font></div>'),
(175753, 'طباسی', '<span class=\"hlight\">طباسی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طُبسی . بشقاب . رجوع به طبسی شود.<br /></font></div>'),
(175754, 'طباشکین', '<span class=\"hlight\">طباشکین .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (مادآباد) دهی جزء دهستان خرقان غربی بخش آوج شهرستان قزوین، واقع در <span class=\"hlight\" dir=\"rtl\">٤٨٠٠٠</span>گزی شمال باختری آوج و <span class=\"hlight\" dir=\"rtl\">٢٦٠٠٠</span>گزی راه عمومی . دامنه، معتدل و مالاریائی دارای <span class=\"hlight\" dir=\"rtl\">٣٥١</span> تن سکنه . آب آن از رودخانه ٔ خررود و شورآب . محصول آنجا غلات و بنشن . شغل اهالی زراعت و صنایع دستی زنان آنجا قالی وجاجیم بافی است . راه آن مالرو است . از طریق رادکان میتوان ماشین برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(175755, 'طباشیر', '<span class=\"hlight\">طباشیر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) تباشیر. دوائی است که از جوف نی هندی بهم رسد. یا آن خاکستر بیخ نی است . و فلوس طباشیر که در شکم نی میباشد مدور است مانند درهم . و گویند چون نی از شدت باریکی بر دیگری بهم میخورد، از آنجا آتش برآید، و در نیستان افتد، طباشیر بندهای نی است که از خاکستر آن جدا کنند، و بهترین آن سپید گردد، با اندک تندی و گزیدگی زبان، و مغشوش آن که از استخوان سر گوسفند میسازند با اندک شوری و بی حدّت میباشد، مقوی دل و معده و جگر و قاطع قی صفراوی و اسهال دموی است . (منتهی الارب ) (آنندراج ). جنسی است دوائی، و به استخوان سوخته میماند، سرد و خشک است در دویم و سیم .(برهان ). دوائی باشد سفید، مایل بقدری کبودی . بهندی بنسلوچن گویند. (غیاث اللغات ). نام دوائی است، و آن در جوف قنا هندی باشد. یا خاکستر بیخ سوخته ٔ قنا هندی . (قاموس ). اصول قنا است که سوخته باشند. (منهاج ).چیزی است که یافت شود در جوف قنای هندی چون بسوزد. (سدیدی ). سوخته ٔ استخوان فیل . (بحر الجواهر). داود ضریر انطاکی گوید: اصل طباشیر همان چیزی است که در درون قنا است، و غشی و دغلی در آن با استخوان مردگان یا استخوان فیل کنند، دوائی است سفید مفرّح دل، که درمیان نی میان خالی میباشد، یا آنکه آن دارو خاکستر بیخ آن نی است - انتهی . دوائی است سپید که در هند از نی مخصوص بوسیله ٔ سوزانیدن بیرون می آورند. و حکیم مؤمن آرد: از جوف نی کهنه ٔ بلاد هند بهم میرسد، و گویند چون از شدت بادها آتش در نیزار آنجا افتد، طباشیر بندهای نی است که از خاکستر نی جدا کنند، بهترین آن سفید مستدیر است که با اندک تندی و گزنده ٔ زبان باشد، و استخوان سوخته ای که به آن مغشوش میسازند با اندک شوری و بی حدت می باشد، و در آب حل نمیشود، در دوم سرد و در سیم خشک و مقوی دل حار و بارد معده و جگر حاره . و قاطع قی صفراوی، و اسهال دموی و حاره . و مجفف رطوبات معده . و جهت خفقان و غشی و تقویت اعضای ضعیفه که از حرارت باشد، شرباً و ضماداً نافع. و جهت بواسیر و تبهای تند و قلاع و با سکنجبین جهت توحش و غم و رفع کرب و التهاب مفید، و سعوط او را با روغن بنفشه جهت تقویت باصره مجرب دانسته اند، و مداومت او مُضر باه . و مُصلحش مصطکی و عسل، و گویند مُضر ریه است . و مُصلحش عناب و عسل، و شربتش تا دو درهم و بدلش بوزن او تخم خُرفه ٔ بو داده، و نصف او سماق است، و گل مختوم و صندل سفید بهترین بدلهاست . (تحفه ٔ حکیم مؤمن ). طباشیر را به هندی توسیر گویند. و بیرحس هم گویند. ارّجانی گوید: طباشیر سرد است در دو درجه و خشک است در سه درجه، تبهای کهنه را منفعت کند، و تشنگی را تسکین دهد، و رفتن شکم را بازدارد. و قی را بنشاند و تسکین دهد، و خفقان را نافع است، و اگر کسی که بواسطه ٔصفرا که در معده بود غشی افتد دفع کند، و درد دهان را که اطبا آنرا قلاع گویند سود دارد. (ترجمه ٔ صیدنه ٔابوریحان بیرونی ). نیکوترین وی سبک بود که زود خرد شود و طبیعت آن سرد و خشک بود در سیم و گویند در دوم، مسیح دمشقی گوید: سرد است در دویم و خشک است در سیم . شیخ الرئیس گوید: مرکب القوی بود مانند کل، و در وی قبض بود که قوت معده بدهد و قلاع را نافع بود و سوختگی آتش را سود دهد و شکم ببندد و تبهای حار و تشنگی را سودمند بود و قی که در مره صفرا بود بازدارد و گرمی حکه بنشاند و جهت ریشها، زهرها و قلاع که در دهان کودکان حادث شود سود دهد و چون تنها با ورق گل سرخ بر آن پاشند دندان متحرک را محکم گرداند تنها سنون ساختن بواسیر را سود دهد و ورم چشم گرم را نافع بود وقوت دل بدهد و خفقان که از حرارت بود ساکن گرداند وتوحش و غم را نافع بود و ضعف معده و التهاب آن و منع خلقه صفراوی و تشنگی را نافع بود و غشی و کرب را نافع بود و مفرح و مقوی قلب باشد و تری کُهن که در معده باشد نشف کند و قوت اعضاء که از حرارت ضعیف شده باشد بدهد و سردمزاج را زعفران معتدل کند و تفریح و تقویت وی بغایت بود و گویند خوردن وی باه را مضر بود، اسحاق گوید: مُضر بود به شش و مصلح وی گلاب بود و گویند مصطکی و انیسون بدل آن عصاره ٔ لحیةالتیس است و گویند بدل آن سه وزن آن تخم خیارزه است و چهار وزن آن بزرقطونا و گویند بدل آن طین مختوم است به وزن آن عصاره ٔ لحیةالتیس است و گویند بدل آن کاغذ مصری سوخته است و گویند به وزن آن تخم کاسنی و نیم وزن آن صندل و ابن مؤلف گوید: در شهر هندوقیس قصبهای دراز بود و بادهای سخت وزد و درهم ساید و آتش از آن برآید و قصب سوخته گردد و حریق وی طباشیر بود و گاه باشد که چندین فرسنگ بسوزد. (اختیارات بدیعی ). طباشیر؛ منه مایوجد فی انابیب القنا و هو الصفائح الشفافة الشدیدة البیاض الحریفة التی تذوب اذا استحلبت و منه مایُحرق .اما من احتکاکه فی بعضه . او بالصناعة و یُعرف بملوحة فیه و عدم حراقه و رمادیة. و قد یغش بعظام الموتی اوالفیل اذا احرقا و یُعرف هذا بغبرة و سواد و کُدر. ارضیة و عدم حدة و هو باردٌ فی الثانیة یابس فی الثالثة یقمع العطش و الحرارة و الخلقه و یحبس الاسهال و الدم . و یقوی القلب و المعدة و الکبد الحارة حتی بالطلاء و یسعط بدهن البنفسج فیحد البصر (من مجربات الکندی ) و یحل الاورام و القلاع طلاء و هو یضر الرئة و یصلحه الصمغ او العسل او العناب و شربته نصف درهم و بدله مثله بزر رجلة محمص و نصفه سماق . (تذکره ٔ داود انطاکی ). و من خرافات الهند: انهم یقولون : ان من الافیله الفائقة مایوجد فی لحوم جباهها درر و تتمیز من سایر الفیلة بشهبةاللون و ارج الرائحة کالیاسمین الهندی و کذالک فی منابت الارماح تحت اصولها و قالوا فی تفصیل ذلک ان ّ تلک الارماح تکون حمراً و اذا کانت شکیراً غضة غیرمستحکمة و مطرت بنوءالغفر و الزبانی ّ تولد فی انابیبها من القطرات لالی تنعقد عند استحکام قنو هذه الرماح و الطباشیر تعمل منها ولو وجدالساحلیون فی رماح الطباشیر شیئاً لما احرقوها الابعد الشق و لاشتهر ذلک . (الجماهر بیرونی ص <span class=\"hlight\" dir=\"rtl\">١٠٨</span>). سرجس گوید: <font color=\"DarkGreen\"><b>[ طباشیر ]</font></b> ماده ای است که در اندرون نی هندی یافت شود. علی بن محمد گوید: طباشیر خاکستر نی هندی است و آنچه استخراج کنند از سواحل هند باشد، اما نقطه ای که فراوانتر از سایر نقاط طباشیر دارد سنداپور است از شهر کلی که در آنجافلفل سیاه فراوان است . هندوان گویند: نیکوترین طباشیر، آن است که سپیدرنگ باشد بویژه بندهای نی آن و فلوس آن که در مدخل نی یافت میشود و شکل آن مدور است مانند درهم . محصول طباشیر را وقتی به دست آورند که بواسطه ٔ تماس و اصطکاک نی ها به یکدیگر، بر اثر بادهای شدید بخودی خود از نی ها احتراقی حاصل آید. طباشیر مصنوعی و مغشوش را نیز با استخوانهای سوخته ٔ میش میسازند، هنگامی که در بلاد خارج از هند قیمتش بالا رود، درصورتی که در همان هنگام قیمت آن در هند از صعود و نزول ایمن است و یک من او از شش تا هشت درهم ترقی کند. مسیح دمشقی گوید: سرد است در دوم و خشک است در سیم، مقوی معده و برای قروح دهان سودمند است . خوزی گوید: برای سوزاندن (مرةالحمراء) صفراء نیکو است، قابض بطن و مقوی معده است چه شربت آن خورند و چه بدان طلا کنند. رازی گوید: برای تب حادّ و تشنگی نافع باشد. اسحاق بن عمران گوید: عطشی را که از صفرا باشد می نشاند و حرارت شدید جگر را به اعتدال می آورد. بر ضد جراحات و جوشها که برفک در دهان کودکان حادث میشود سودمند است، استعمال آن بصورت گرد است . خواه مفرد و خواه باگل سرخ و شکر طبرزد استعمال کنند. در مورد بواسیر نیز طباشیر بکار برند. ابن سینا گفته : طباشیر قابض و دابغ است و اندک تحلیل و تبرید آن از تحلیلش بیش باشد، بواسطه ٔ تلخی اندکی که در اوست و خصائص گل سرخ دراو مجتمع است، برای التهابات چشم سودمند و قلبی را که دچار خفقان حاد باشد تقویت کند و شربت و طلای آن غشی را که بر اثر ریزش صفراء بمعده حادث شده باشد سوددهد، نافع است توحش و غم را و التهاب و ضعف معده و عطش را نیک است، مانع ریزش صفرا بمعده است و گند دهانی را که از صفرا تولید شده باشد سود بخشد. و شرب آن با آب سرد تبهای حاد و حارّ را نافع باشد. در ادویه ٔ قلبیه گفته است : طباشیر را در تقویت و تفریح قلب خاصیت است و خفقان و غشی را منفعت بخشد. و یُعینها قبضه . و در امزجه ٔ حاره تبرید آن در دوم باشد و گاه درامزجه ٔ بارده تعدیل به زعفران شود و تقویت و تفریح آن در قلب، مانا که در روان آدمی نورانیت و متانتی ایجاد کند. رازی در کتاب حاوی از قول جرجس نقل کرده که : طباشیر شرباً مزیل باه است . دیگری گفته است : طباشیر رطوبت کهنه ای را اگر در معده باشد خشک کند و اعضائی را که از حرارت بسستی گرائیده باشد نیرومند و تقویت کند. (مفردات ابن البیطار). <BR><font color=\"Blue\">◄</font> خیزران محرق است . <BR><font color=\"Blue\">◄</font> گچ سفید. طباشیر: تحثرات سیلیکی که مرکب شده اند از سیلیکات پتاس و سیلیکات آهک و متشکل می شوند در تجویف عقود یک قسم نی هندی موسوم به بنبو و گل سفید و نوع گل و گچ و مأخوذ از تازی . (ناظم الاطباء) <span class=\"hlight\">:</span> <br />تنی چون شیر با شکر سرشته <br />طباشیرش برابر شیر هشته .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طباشیر صبح </span> ؛ کنایه است از سپیدی صبح صادق . (برهان ) (غیاث اللغات )(آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طباشیر قلمی </span> ؛ قسمی از طباشیر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طباشیر قمی </span> ؛ گل محلاتی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طباشیر هندی </span> ؛ نوعی از طباشیر.<br /><BR><font color=\"Blue\">◄</font> ظاهراً بمعنی ماده ای است که آنرا در ساختن بعض قدحها بکار می بردند: اقداح طباشریه یا طباشیریه . <BR><font color=\"Blue\">◄</font> خمی بزرگ که در سطح آن قله هائی در طبقات متعدد جای داده اند. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span>). <BR><font color=\"Blue\">◄</font> مژده و بشارت . (ناظم الاطباء).<br /></font></div>'),
(175756, 'طباطبا', '<span class=\"hlight\">طباطبا.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (اِخ ) محمدبن اسماعیل بن قاسم بن ابراهیم طباطبا، مکنی به ابوعبداﷲ. از بزرگان خاندان طباطبا بوده و فرزندان وی در زمره ٔ نقبای مصر بشمار میرفته اند. (از تاج العروس ).<br /></font></div>'),
(175757, 'طباطبا', '<span class=\"hlight\">طباطبا.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b>(اِخ ) اسماعیل بن ابراهیم بن حسن بن حسن بن علی بن ابیطالب علیه السلام . لقب به لانه کان یبدل القاف طاءً. او لانه اعطی قباء، فقال : طباطبا، و یرید قباقبا. (منتهی الارب ). لقب اسماعیل بن ابراهیم بن حسن بن علی علیه السلام که در زبان لکنت داشت و بجای قاف طاء میگفت . آورده اند که در ایام خردسالی بروز عید والد بزرگوار او، به او فرمود که چه نوع جامه برای تو مهیا کنم ؟ او گفت :طباطباء یعنی قباقباء از آن روز اسماعیل به لقب طباطبا مشهور گشت و اولاد او را سادات طباطبائی گویند. (غیاث اللغات ) (آنندراج ). و صاحب قاموس الاعلام آرد: ابراهیم بن اسماعیل بن ابراهیم بن حسن بن حسین بن علی بن ابی طالب یکی از سادات است و زبانش لکنت داشته و بتلفظ «ق » مقتدر نبود و آنرا مانند حرف «ط» تلفظ میکرده است . روزی از خادمش قبای خودرا درخواست میکرد عوض «قباقبا»، «طباطبا» گفته و ازاین رو بهمین کلمه خود و اولاد و احفادش ملقب شدند. رجوع به ابن طباطبا شود. و صاحب تاج العروس مینویسد:لقب شریف اسماعیل الدیباج بن ابراهیم العمربن حسن مثنی بن حسن سبطبن علی بن ابیطالب کرم اﷲ وجهه و رضی عنهم و چنانکه نسب شناسان بدان تصریح کرده اند این کلمه لقب پسر وی ابراهیم بن اسماعیل بوده و رای صواب همین است . و وی را از این رو بدان نامیده اند که بسبب لکنت زبان «ق » را «طا» می گفت یا بدان سبب که قبائی به وی دادند و او گفت : طباطبا و چنانکه پیداست هر دو وجه یکسان است و با هم منافی نیستند. و ابونصر بخاری بنقل از کتاب النسب تألیف امام الناصر للحق آورده است که مردم سواد وی را بدین لقب خواندند و طباطبا بزبان نبطی بمعنی بزرگ بزرگان (سیدالسادات ) است و برخی گفته اند وجه تسمیه ٔ وی بدین لقب این است که پدر وی هنگامی که خردسال بود می خواست برای او جامه ای بسازد و او را میان پیراهن و قبا مخیر ساخت . او گفت : طباطبا، یعنی قباقبا. و در خاندان طباطبا گروهی از لحاظ حدیث وفقه و اصل و نسب شهرت یافته اند و این خاندان در میان طالبیان اهمیتی بسزا داشته اند. (از تاج العروس ).<br /></font></div>'),
(175758, 'طباطبا', '<span class=\"hlight\">طباطبا.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (اِخ ) حسن بن عبداﷲبن محمدبن قاسم بن طباطبا. ملقب به مستنجد. از مشاهیر خاندان طباطبا بوده و ذریه ٔ وی بسبب نام او شهرت یافته اند. (از تاج العروس ).<br /></font></div>'),
(175759, 'طباطبا', '<span class=\"hlight\">طباطبا.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (اِخ ) علی بن حسن بن ابراهیم طباطبا، مکنی به ابوالحسن . ازمشاهیر خاندان طباطبا بوده است . (از تاج العروس ).<br /></font></div>'),
(175760, 'طباطبا', '<span class=\"hlight\">طباطبا.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (اِخ ) محمدبن احمدبن علی طباطبا حفید ابوالحسن علی بن حسن بن ابراهیم طباطبا. از شیوخ خاندان طباطبا بشمار میرفته و فرزندان وی به بزرگی و ریاست نائل آمده اند. (از تاج العروس ).<br /></font></div>'),
(175761, 'طباطبا', '<span class=\"hlight\">طباطبا.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (اِخ ) محمدبن طاهربن علی بن محمدبن احمدبن محمدبن احمدبن ابراهیم طباطبا، مکنی به ابوعلی . از بزرگان خاندان طباطبا بوده و فرزندان وی نیز از بزرگان و محدثان بشمار میرفته اند. (از تاج العروس ).<br /></font></div>'),
(175762, 'طباطبا', '<span class=\"hlight\">طباطبا.</span> <font color=\"DarkGreen\"><b>[ طَطَ ]</font></b> (اِخ ) (بنی ...) دولت کوچکی است که در زمان خلفای عباسی در کوفه پدید آمده و در همین شهر و یمن قریب به <span class=\"hlight\" dir=\"rtl\">١٥٠</span> سال حکمرانی کرده است و مؤسس این سلاله ابوعبداﷲ محمدبن ابراهیم طباطبا بوده که مدت کمی در کوفه حکمرانی کرد و دوست وی ابوالسرایا او را مسموم ساخت و نوه اش یحیی الهادی به تأسیس حکومت در یمن موفق گشت و نسل وی مدت مدیدی در یمن فرمانروائی داشتند. سلاله ٔ بنی طباطبا از هفت تن تشکیل شده که عبارتند از:<br /><span class=\"hlight\" dir=\"rtl\">١</span>- ابوعبداﷲ محمدبن ابراهیم طباطبا <span class=\"hlight\" dir=\"rtl\">١٩٩</span> هجری .<br /><span class=\"hlight\" dir=\"rtl\">٢</span>- امیرالمؤمنین یحیی الهادی <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> \"<br /><span class=\"hlight\" dir=\"rtl\">٣</span>- مرتضی محمد <span class=\"hlight\" dir=\"rtl\">٢٨٠</span> \"<br /><span class=\"hlight\" dir=\"rtl\">٤</span>- ناصراحمد <span class=\"hlight\" dir=\"rtl\">٣٢٠</span> \"<br /><span class=\"hlight\" dir=\"rtl\">٥</span>- منتخب حسین <span class=\"hlight\" dir=\"rtl\">٣٢٣</span> \"<br /><span class=\"hlight\" dir=\"rtl\">٦</span>- مختارقاسم <span class=\"hlight\" dir=\"rtl\">٣٢٩</span> \"<br /><span class=\"hlight\" dir=\"rtl\">٧</span>- محمدهادی <span class=\"hlight\" dir=\"rtl\">٣٤٤</span> \"<br /></font></div>'),
(175763, 'طباطبة', '<span class=\"hlight\">طباطبة.</span> <font color=\"DarkGreen\"><b>[ طَ طِ ب َ ]</font></b> (اِخ ) (مشهد...) مشهدالطباطبة در قبرستان مصر (قاهره ) متعلق به خاندان طباطبا است . (از تاج العروس ).<br /></font></div>'),
(175764, 'طباطبی', '<span class=\"hlight\">طباطبی .</span> <font color=\"DarkGreen\"><b>[ طَ طِ ]</font></b> (ص نسبی ) نسبت به طباطباست . (از تاج العروس ).<br /></font></div>'),
(175765, 'طباطبی', '<span class=\"hlight\">طباطبی .</span> <font color=\"DarkGreen\"><b>[ طَ طِ ]</font></b> (اِخ ) حسین بن کمال الدین . او را در علم هیئت کتابی است مختصر به نام «السبعالشداد» که بسال <span class=\"hlight\" dir=\"rtl\">١٣٠٩</span> هَ . ق . در دهلی هندبطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٦</span>).<br /></font></div>'),
(175766, 'طباع', '<span class=\"hlight\">طباع .</span> <font color=\"DarkGreen\"><b>[ طَب ْ با ]</font></b> (اِخ ) اسحاق بن یوسف طباع . از مردم بغداد که به اذنه رهسپار شد و در آنجا سکونت گزید. وی از مالک بن انس و حمادبن زید و سلام بن ابومطیع و جریریةبن اسما و فرعة (کذا)بن سوید و عبدالرحمن بن ابی الزیاد و شریک و هیثم حدیث کرده و پسر برادرش محمدبن یوسف و ابوحاتم رازی و ابوالولیدبن برد انطاکی و عبدالکریم بن هیثم دیر عاقولی از او روایت دارند و احمدبن حنبل میگفت ابن طباع به آموختن فقه پرداخته و قریب چهل هزار حدیث حفظ کرده است و چه بسا که به تدلیس گرائیده است . وی بسال <span class=\"hlight\" dir=\"rtl\">٢٢٤</span> هَ. ق . درگذشته است . (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٦</span> «الف »).<br /></font></div>'),
(175767, 'طباع', '<span class=\"hlight\">طباع .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ج ِ طبع. سرشت . (دهار) (مهذب الاسماء) (السامی ). طبیعت . سرشت مردم که زایل نشود. (غیاث اللغات ) (آنندراج ). سرشت که مردم را بدان آفریده اند. اخلاقی که از مطعم و مشرب در آدمی پیدا و مستحکم و ممتنعالزوال گردد. (منتهی الارب ). السجیة التی جبل علیهاالانسان، مؤنثةٌ. هو مبداء اول الحرکة ما هی فیه و سکونه بالذات و یطلق ایضا علی الصورة النوعیة. قال السید السند فی حاشیةالمطول : قد اُطلق فی الاصطلاح الطبیعة و الطباع علی الصورة النوعیة و قالوا الطباع اعم منها. لانه یقاله علی مصدر الصفة الذاتیة الاولیة لکل شی ٔ والطبیعة قد تخص بما یصدر عنه الحرکة والسکون فیما هو فیه اولاً و بالذات من غیر ارادة. (کشاف اصطلاحات الفنون ). میرنوراﷲ در شرح گلستان نوشته که طباع بمعنی طبیعت و سرشت مردم و در جائی استعمال شود که صاحب آنرا شعور باشد و طبیعت را در مقامی استعمال کنند که صاحبش را شعور نبوده باشد و طبع را در هر دو محل آرند. (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(175768, 'طباع', '<span class=\"hlight\">طباع .</span> <font color=\"DarkGreen\"><b>[ طَب ْ با ]</font></b> (ع ص ) مُهرزن . <BR><font color=\"Blue\">◄</font> سازنده ٔ هرچه باشد. (منتهی الارب ) (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> سازنده ٔ تیغ. (منتهی الارب ). شمشیرگر. (مهذب الاسماء) سازنده ٔ شمشیر. (سمعانی ). <BR><font color=\"Blue\">◄</font> صاحب طبیعت ذکی . <BR><font color=\"Blue\">◄</font> کوزه گر. (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(175769, 'طباع', '<span class=\"hlight\">طباع .</span> <font color=\"DarkGreen\"><b>[ طَب ْ با ]</font></b> (اِخ ) ابوجعفر محمدبن عیسی الطباع . از مردم بغداد. (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٢٦٥</span> «ب »).<br /></font></div>'),
(175770, 'طباع', '<span class=\"hlight\">طباع .</span> <font color=\"DarkGreen\"><b>[ طَب ْ با ]</font></b> (اِخ ) ابویحیی عیسی بن یوسف بن عیسی الطباع . از مردم بغداد. وی از خلیل بن محمد کلبی و بقولی کلابی و ابوبکربن عیاش و ابن ابی فدیک و بشربن عمر زهرانی و عموی او اسحاق بن عیسی حدیث کرده و برادرش محمدبن یوسف و ابوبکربن ابی الدنیا و عبداﷲبن محمدبن تاحیة (کذا) و قاسم بن زکریا المطرز و یحیی بن محمدبن صاعد و عبدالوهاب بن ابی حیة وراق الجاحظ از وی روایت دارند. او بسال <span class=\"hlight\" dir=\"rtl\">٢٤٧</span> هَ. ق . درگذشته است . (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٦</span> «الف »).<br /></font></div>'),
(175771, 'طباعت', '<span class=\"hlight\">طباعت .</span> <font color=\"DarkGreen\"><b>[ طِ ع َ ]</font></b> (ع اِمص ) شمشیرسازی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> فن چاپ . فن طبع.<br /></font></div>'),
(175772, 'طباق', '<span class=\"hlight\">طباق .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ج ِ طبقة. رجوع به طبقة شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175773, 'طباق', '<span class=\"hlight\">طباق .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) موافق . برابر. و منه : والسموات طباق ٌ، جهت مطابقه بعض مر بعض را. یا آنکه بعض آن بالای بعض است . (منتهی الارب ). قوله تعالی <span class=\"hlight\">:</span> الذی خلق سبع سموات طباقاً ؛ آن خدائی که بیافرید هفت آسمان را طبق بر بالا نهاد. یقال : اطبقت الشی ٔ؛ اذا جعلت بعضه فوق بعض . (تفسیر ابوالفتوح رازی ). و الم تروا کیف خلق اﷲ سبع سموات طباقاً ؛ گفت نمی بینید، یعنی نمیدانید که خدای تعالی این هفت آسمان مطبق چگونه آفرید. (تفسیر ابوالفتوح رازی ). زیر یکدیگر، طبقاتی که بعضی بر بعضی باشند. (غیاث اللغات ). هر چیز که آنرا بترتیب به روی هم چیده باشند. (برهان ). <BR><font color=\"Blue\">◄</font> (مص ) موافق کردن دو چیز را با هم . (غیاث اللغات ). تساوی . توافق . برابری . <BR><font color=\"Blue\">◄</font> طباق الارض ؛ هرچه بالای زمین است . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زمین بلند. (برهان ). <BR><font color=\"Blue\">◄</font> و قولها: زوجی عیایا طباقا؛ ای المطبق علیه حُمقاً. و قیل من یعجز عن الکلام فتنطبق شفتاه . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> هفت آسمان <span class=\"hlight\">:</span> <br />مصطفی بین چونکه صبرش شد براق <br />برکشانیدش ببالای طباق .<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> (اِمص ) (اصطلاح بدیع) یکی از صنایع معنوی است که آنرا تضاد و مطابقه و تکافؤ نیز گویند و آن جمع بین ضدین یا اضداد است . رجوع به تضاد شود. صنعت طباق موافق کردن چند چیز که ضد همدیگر باشند یعنی در پی یکدیگر آوردن آنها. (غیاث اللغات ) (آنندراج ). عنداهل البدیع من المحسنات المعنویة و یُسمی ایضاً بالمطابقة و التطبیق و التضاد و التکافؤ و هو الجمع بین المتضادین و لیس المراد بالمتضادین الامرین الوجودیین المتواردین علی محل واحد بینهما غایةالخلاف کالسواد و البیاض بل اعم من ذلک و هو ما یکون بینهما تقابل و تنافر فی الجملة و فی بعض الاحوال سواء کان التقابل حقیقیاً او اعتباریاً و سواء کان تقابل التضاد اوتقابل الایجاب و السلب او تقابل العدم و الملکة او تقابل التضایُف او ما یشبه شیئاً من ذلک کذا فی المطول و قیل المطابقة و یُسمی بالطباق ایضاً و هی ان یجمع بین الشیئین المتوافقین و بین ضدیهما ثُم اذا شرطت المتوافقین بشرط اوجب اَن تشترط ضدیهما بضد ذلک الشرط. کقوله تعالی : فاما من اعطی و اتقی و صدّق بالحسنی فسنیسره للیسری و اما من بخل و استغنی و کذب بالحسنی فسنیسره للعسری . (قرآن <span class=\"hlight\" dir=\"rtl\">٥/٩٢</span>-<span class=\"hlight\" dir=\"rtl\">١٠</span>). فالاعطاء و الاتقاء و التصدیق ضد البخل و الاستغناء و التکذیب و المجموع الاول شرطٌ للیسری و المجموع الثانی شرطٌ للعسری . (کذا فی الجرجانی ). و التقیید بالمتضادین باعتبار الاخذ بالاقل لا للاحتراز عن الاکثر. فانه جار فیما فوق المتضادین ایضاً و انما قال فی بعض الاحوال لیشتمل طباق السلب . کما فی قوله تعالی : لکن اکثرالناس لایعلمون . (قرآن <span class=\"hlight\" dir=\"rtl\">٢٨/٣٤</span>). فان بینهما و ان لم یکن التقابل موجوداً بناء علی تعلق العلم بشی ٔ و عدم العلم بشی ٔ آخر. الا ان التقابل بینهما فی الحالة التی علق کل واحد منهمابشی ٔ واحد و نظر الی مجرّد مفهومیهما مع قطع النظر عما یتعلقانه، کذا فی بعض الحواشی . فالطباق ضربان ؛ طباق الایجاب سواء کان الجمع فیه بلفظین من نوع اسمین نحو: و تحسبهم ایقاظاً و هم رقود (قرآن <span class=\"hlight\" dir=\"rtl\">١٨/١٨</span>). او فعلین نحو: یحیی و یمیت اوحرفین نحو: لها ما کسبت و علیها ما اکتسبت . (قرآن <span class=\"hlight\" dir=\"rtl\">٢٨٦/٢</span>). فان فی اللام معنی الانتفاع و فی علی معنی التضرر. او کان من نوعین و هذا ثلاثة اقسام اسم مع فعل اوحرف او فعل مع حرف لکن الموجود هو الاول فقط نحو: اءَ وَ من کان میتا فَاءَحییناه . (قرآن <span class=\"hlight\" dir=\"rtl\">١٢٢/٦</span>). فان الموت و الاحیاء مما یتقابلان فی الجمله و طباق السلب و هو ان یجمع بین فعلی مصدر واحد احدهما مثبت و الاَّخر منفی او احدهما امر و الاَّخر نهی، نحو: ولکن َّ اءَکثرالناس لایعلمون . (قرآن <span class=\"hlight\" dir=\"rtl\">٥٧/٤٠</span>). یعلمون ظاهراً من الحیوة الدنیا فلاتخشوا الناس و اخشون . (قرآن <span class=\"hlight\" dir=\"rtl\">٤٤/٥</span>). و من الطباق باسماء البعض تدبیجاً و قد مر و منه ما یخص باسم المقابلة کما یجی ٔ و یلحق بالطباق شیئان احدهما الجمع بین المعنیین یتعلق احد هما بما یقابل الاَّخر نوع تعلق مثل السببیة و اللزوم نحو: اشداء علی الکفاررحماء بینهم . (قرآن <span class=\"hlight\" dir=\"rtl\">٢٩/٤٨</span>). فان الرحمة و ان لم یکن مقابلا للشدة لکنها مسببة للین الذی هو ضدالشدة و نحوقوله تعالی : اءُغرقوا فاُدخلوا ناراً. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٥/٧١</span>). لان ادخال النار یستلزم الاحراق المضاد للاغراق و ثانیهما ما یسمی ایهام التضاد کما مر کذا فی المطول قیل لا وجه لالحاق النوع الاول بالطباق لانه داخل فی تعریفه، لان منافی اللازم، مناف للملزوم فبین المذکورین تناف فی الجملة فیکون طباقاً لا ملحقاً به - انتهی . و یؤید هذا جعله صاحب الاتقان من الطباق و تسمیته بالطباق الخفی . قال : المطابقه و یسمی الطباق الجمع بین التضادین فی الجملة و هو قسمان حقیقی و مجازی و الثانی یسمی التکافو و کل منهما اما لفظی او معنوی و اما طباق ایجاب او سلب، فمن امثلة ذلک : فلیضحکوا قلیلاً ولیبکوا کثیراً. (قرآن <span class=\"hlight\" dir=\"rtl\">٨٢/٩</span>). و انه هو اضحک و ابکی (قرآن <span class=\"hlight\" dir=\"rtl\">٤٣/٥٣</span>). و تحسبهم ایقاظاً و هم رقود (قرآن <span class=\"hlight\" dir=\"rtl\">١٨/١٨</span>). و من امثلةالمجازی : او من کان میتاً فاحییناه (قرآن <span class=\"hlight\" dir=\"rtl\">١٢٦/٦</span>)؛ ای ضالا فهدیناه و من امثلة طباق السلب : تعلم ما فی نفسی و لااعلم ما فی نفسک . (قرآن <span class=\"hlight\" dir=\"rtl\">١٨٨/٧</span>). و من امثلة المعنوی : اًِن اءَنتم الا تکذبون . (قرآن <span class=\"hlight\" dir=\"rtl\">١٥/٣٦</span>). قالوا ربنا یعلم اًِنّا اًِلیکم لَمرسلون . (قرآن <span class=\"hlight\" dir=\"rtl\">١٦/٣٦</span>). معناه : ربنا یعلم انا لصادقون : الّذی جعل لکم الارض فراشاً و السماء بناء. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٢/٢</span>). قال ابوعلی الفارسی لما کان البناء رفعاً للمبنی، قو بل بالفراش الذی هو خلاف البناء و منه نوع یسمی بالطباق الخفی کقوله تعالی : مما خطیئاتهم اءُغرقوا فَاءُدخلواناراً. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٥/٧١</span>). لان الغرق من صفات الماء فکأنّه جمع بین الماء و النار. قال ابن المعتز من املح الطباق و اخفاه . قوله تعالی : و لکم فی القصاص حیوة. (قرآن <span class=\"hlight\" dir=\"rtl\">١٧٩/٢</span>). لان معنی القصاص القتل فصار القتل سبب الحیوة و منه نوع یسمی ترصیعالکلام . و منه نوع یسمی المقابلة - انتهی . ما فی الاتقان . (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(175774, 'طباق', '<span class=\"hlight\">طباق .</span> <font color=\"DarkGreen\"><b>[ طُب ْ با ]</font></b> (ع اِ) درختی است که در کوههای مکه روید. نوشیدن و ضماد آن نافع است مر زهرها را و جهت خارش و گر و تبهای کهنه و مغص و یرقان و سده های جگر شدیدالاسخان است . (منتهی الارب ) (آنندراج ). غافث است و آن گلی باشد لاجوردی و درازشکل و از حوالی کوهستان شیراز آورند گرم و خشک است در اول و دوم . (برهان ). درختی است که در کوهستان مکه میروید و نافع سموم است و امراض دیگر. <BR><font color=\"Blue\">◄</font> سپرم بیابانی . (مهذب الاسماء). طباق : یسمی شجرالبراغیث . یطول نحو قامة مزغب، یدبق بالید، و له زهر الی الصفرة و یدرک بالجوزاء و تبقی قوته زماناً و هوحار یابس فی آخرالثانیة اذا اقترش اورض طرد الهوام کلها خصوصاً البراغیث و طبیخه یحلل الاورام نطولاً و یجلوه و شرباً یفتح السدد و یزیل الیرقان و اوجاع القلب و المعدة. قیل و یفتت الحصی و یدر الطمث، و هو یصدع المحرور و یثقل الرأس و تصلحه الکزبرة و شربته ثلاثة. (تذکره ٔ داود ضریر انطاکی ). نباتی است که در اندلس بجای غافث استعمال میکنند شجره ٔ او بقدر قامتی و برگش مثل برگ زیتون و درازتر از آن و زغب دارد با چسبندگی و با تلخی و تندی و بوی کریه دارد و او را طباق منتن نامند و قسم صغیر او بقدر شبری برگش زودشکن وگلش مایل بزردی و بی بوی و با اندک شیرینی در آخر دوم گرم و خشک و افتراش او گریزاننده ٔ هوام و کیک و کبیرا و قوی تر از صغیر. و گل او مفتح و مقوی جگر و مدرحیض، و مخرج مشیمه و جنین و تریاق سموم و جهت درد جگر و مهیج و برگ و گل آن مسهل اخلاط سوخته و جهت مغص و یرقان سددی و صرع بلغمی و طبخ او جهت درد رحم، و ضمادش جهت درد سر و با روغن جهت کزاز و از تبها و جرب و حکه نافع و مصدع محرورو مصلحش گشنیز و شربتش تا دو درهم است . (تحفه ٔ حکیم مؤمن ). شجرةالبراغیث .<br /></font></div>'),
(175775, 'طبال', '<span class=\"hlight\">طبال .</span> <font color=\"DarkGreen\"><b>[ طَب ْ با ]</font></b> (ع ص ) تبیره زن . (مهذب الاسماء). طبل نواز. (منتهی الارب ) (آنندراج ). طبل زن . دهل زن . نقاره زن . نقاره چی . نوبتی . نوبت زن .طبال . درویش واله هروی خطاب بباد گوید <span class=\"hlight\">:</span> <br />تا ساکن حلقی و دهانی <br />طبال صماخ انس و جانی .<br /> <font color=\"Red\">(از آنندراج ).</font><br />میرطبال با پسر میگفت <br />کای پسر طبل زن به استعجال <br />میر پیرار و میر پیرارین <br />همه بطال و ما همان طبال .<br /><font color=\"Red\">؟</font><br /></font></div>'),
(175776, 'طبال', '<span class=\"hlight\">طبال .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ج ِ طبل . رجوع به طبل شود.<br /></font></div>'),
(175777, 'طبالة', '<span class=\"hlight\">طبالة.</span> <font color=\"DarkGreen\"><b>[ طِل َ ]</font></b> (ع اِمص ) طبل نوازی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(175778, 'طبالة', '<span class=\"hlight\">طبالة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) درای . (مخصوص شتر). (السامی ). جَرَس . زنگ بزرگ .<br /></font></div>'),
(175779, 'طبالوندان', '<span class=\"hlight\">طبالوندان .</span> <font color=\"DarkGreen\"><b>[ طَ بال ْ وَ ]</font></b> (اِخ ) دهی است جزء دهستان خشکبیجار بخش خمام شهرستان رشت، واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی خاور شوسه ٔ خمام متصل به بازار خشکبیجار. جلگه، معتدل، مرطوب و مالاریائی .دارای <span class=\"hlight\" dir=\"rtl\">١٦٨٥</span> تن سکنه . آب آن از نهر خشکبیجار از سفیدرود. محصول آنجا برنج و ابریشم . شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(175780, 'طبالی', '<span class=\"hlight\">طبالی .</span> <font color=\"DarkGreen\"><b>[ طَب ْ با ]</font></b> (حامص ) شغل طبال . طبالة تبیره زنی . دُهل زنی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">طَبّالی بِه ْ که بَطّالی </span> .<br /></font></div>'),
(175781, 'طبانة', '<span class=\"hlight\">طبانة.</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (ع مص ) زیرکی . (منتهی الارب ) (آنندراج ). زیرک شدن . دانا گردیدن . (آنندراج ).<br /></font></div>'),
(175782, 'طبانچه', '<span class=\"hlight\">طبانچه .</span> <font color=\"DarkGreen\"><b>[ طَ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ) در این لفظ بجای طاء تاء فوقانی نوشتن صحیح باشد چرا که لفظ فارسی است ازمُزیل و خان ِ آرزو. و در خیابان نوشته که طبانچه ازمدار به باء موحده معلوم می شود و فصحاء عراق به باءفارسی خوانند. مؤلف گوید: که طاء مطبقه در فارسی نیامده، و متأخرین بسبب اختلاط عرب و عجم در بعض الفاظ تصرف گونه کرده اند و برخی را به طاء مطبقه نوشته اند. مثلاً طلا و طپیدن و طپانچه . تم کلامه . (غیاث اللغات ). اصل طبانچه، توانچه است مرکب از توان بمعنی زور وقوت و چه که کلمه ٔ نسبت است . فصحای عراق به باء فارسی خوانند و با لفظ زدن و خوردن مستعمل <span class=\"hlight\">:</span> <br />نبرد باد اگر بوی تو هر صبح به باغ <br />گل طبانچه زند و غنچه کند جنگ بمشت .<br /> <font color=\"Red\">ملا شیدای هندی (از آنندراج ).</font><br />چو مقبل کمر بست پیش آر کفش <br />طبانچه نشاید زدن با درفش .<br /> <font color=\"Red\">خواجه نظامی (از آنندراج ).</font><br />از تاب سینه شعله برآورد داغ ما<br />صرصر طبانچه چون نخورد از چراغ ما.<br /> <font color=\"Red\">ظهوری (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبانچه ٔ روزگار خوردن </span> ؛ کنایه است از تصدیعات زمانه کشیدن . (آنندراج ). طپانچه . تپانچه .<br /></font></div>'),
(175783, 'طبانیة', '<span class=\"hlight\">طبانیة.</span> <font color=\"DarkGreen\"><b>[ طَ ی َ ]</font></b> (ع اِمص ) زیرکی . (منتهی الارب ). زیرک شدن . (زوزنی ) (تاج المصادر بیهقی ).<br /></font></div>'),
(175784, 'طباهج', '<span class=\"hlight\">طباهج .</span> <font color=\"DarkGreen\"><b>[ طَ هَِ ]</font></b> (معرب، اِ) فارسی معرب . (ثعالبی ). گوشت در روغن سرخ کرده . <BR><font color=\"Blue\">◄</font> کباب شامی . (منتهی الارب ) (آنندراج ). گوشتی است که در روغنها سرخ کنند. و گویند مراد از او کباب شامی است . مقوی معده و مجفف رطوبت آن و موافق ناقهین قوی المعده و مقوی اعضاء و مضر ضعیف الاحشاء است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(175785, 'طباهجات', '<span class=\"hlight\">طباهجات .</span> <font color=\"DarkGreen\"><b>[ طَ هَِ ]</font></b> (اِ) ج ِ طباهجة.<br /></font></div>'),
(175786, 'طبایع', '<span class=\"hlight\">طبایع.</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ ]</font></b>(ع اِ) رجوع به طبائع و شواهد طبایع در آنجا شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبایع اربع</span> ؛ چهار عنصر آب، آتش، باد و خاک .<br /></font></div>'),
(175787, 'طبایعی', '<span class=\"hlight\">طبایعی .</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ ]</font></b> (ص نسبی ) رجوع به طبائعی شود.<br /></font></div>'),
(175788, 'طبب', '<span class=\"hlight\">طبب .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) جایگاهی است در نجد. (معجم البلدان ).<br /></font></div>'),
(175789, 'طبب', '<span class=\"hlight\">طبب .</span> <font color=\"DarkGreen\"><b>[ طِ ب َ ]</font></b> (ع اِ) ج ِ طبة. (منتهی الارب ) (آنندراج ). رجوع به طبة شود.<br /></font></div>'),
(175790, 'طبة', '<span class=\"hlight\">طبة.</span> <font color=\"DarkGreen\"><b>[ طِب ْ ب َ ]</font></b> (ع اِ) نورد ابر. <BR><font color=\"Blue\">◄</font> زمین دراز گیاه ناک . <BR><font color=\"Blue\">◄</font> جامه ٔ پیش گشاده ٔ درازدامن . (منتهی الارب ) (آنندراج ). جامه ٔ دراز. (نسخه ای از مهذب الاسماء). <BR><font color=\"Blue\">◄</font> پوست دراز. <BR><font color=\"Blue\">◄</font> دوال دقیق . <BR><font color=\"Blue\">◄</font> خط شعاع آفتاب . (منتهی الارب ) (آنندراج ). ج، طِبَب . (منتهی الارب ) (آنندراج )(مهذب الاسماء). <BR><font color=\"Blue\">◄</font> گونه . (منتهی الارب ).<br /></font></div>'),
(175791, 'طبة', '<span class=\"hlight\">طبة.</span> <font color=\"DarkGreen\"><b>[ طُب ْ ب َ ]</font></b> (ع اِ) دوال که درزهای مشک به وی گیرند. اوالسیر الذی یکون فی اسفل القربة بین الخرزتین . (منتهی الارب ). مغزی . زِه .<br /></font></div>'),
(175792, 'طبج', '<span class=\"hlight\">طبج .</span> <font color=\"DarkGreen\"><b>[ طَب َ ]</font></b> (ع مص ) گول گردیدن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(175793, 'طبج', '<span class=\"hlight\">طبج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) محکم و استوار شدن حماقت . <BR><font color=\"Blue\">◄</font> زدن بر هر چیز میان کاواک مانند سر و نحو آن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(175794, 'طبحة', '<span class=\"hlight\">طبحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b>(اِخ ) (به معنی کشتن ) اول تواریخ ایام ملاحظه در باطح . جایگاهی است بین حلب و فرات . (قاموس کتاب مقدس ).<br /></font></div>'),
(175795, 'طبخ', '<span class=\"hlight\">طبخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) پختن اِشتواء باشد یا اقتداراً. (خواه به بریان کردن و خواه در دیگ پختن ). یقال : هذه ُ خبزةٌ جیدةالطبخ . و کذا آجُرة. (منتهی الارب ). دیگ پختن . (تاج المصادر بیهقی ) (مجمل اللغة) (زوزنی ). پُخت . پزاندن . (غیاث اللغات ). پوختن . (زوزنی ). (پُخت و پز. بپختن ). <BR><font color=\"Blue\">◄</font> ضرب من المنصف و الجص و الاجرّ. (قطر المحیط). <BR><font color=\"Blue\">◄</font> هو علم واسع علیه مدارُ الانواع الثلاثة و هو عبارة عن انضاج الحرارة الشی ٔ بشرط مؤانسة الرطوبة. و یقال لعادمه النی ٔ و قاصره الفج، و لعمل الحرارة بلارطوبة شی ٔ و بالادهان قلی، و لمافات الاعتدال احتراق، وستحقق . و یحتاج الطبخ الی الطب حاجة شدیدة من حیث الترکیب تألیفاً و التعدیل طبعا و المزاج احکاماً و التحضین اتقاناً. و یحتاج الیه الطبیب فی تبلیغ المزاج غایته و صیرورة المختلف مؤتلفاً و الکثرة وحده ثم الطبخ اما طبیعی و هو تعیین الصورة النوعیة فی المادة و الهیولی متناسبةالجوهر، و سیأتی لهذا فی العلم الالهی مزیداستقصاء او صناعی و هو ما یقصد به محاکاة الطبیعة وان لم یبلغها و اختلافه غیرمحصور و ان امکن رده الی صحةالفکر و خفةالید، و وزن الحرارة کجعلها حضانة فی مؤانسة ما شأنه الصعود و وسطا فیما یراد منه التحلیل و اعلی فیما یراد منه التفریق لما ائتلف و الجمع لما اختلف کالتقطیر و العقد و قد صحح اهل الخواض ان موازین النار لاتعدو ستة عشر ادناها ما عادل حرارةالجناح و ارفعها ما محق رطوبة توازن الیبوسة فی اثنا عشر دقیقة. قال فی حلول الافلاطونیات : و هذا ضابطٌ یکفی العاقل فی تقریرالوسایط ثم تختلف بحسب الزمان و المکان کماقرره فی الکتاب المذکور حیث قال : و قد الفت بین صفارالبیض و الزرنیخ الاصفر فی ثلاثة فی الصیف بانطاکیة، و سبعة فی الشتاء، فلیقس و هذا مأخوذ فی الحقیقة من افعال الطبیعة حیث اختلفت فی المعادن و النبات و اوقات الزهر و الثمر و النضج و الحصاد زماناً و مکاناً. کما سیأتی فی الفلاحة. (تذکره ٔ داود ضریر انطاکی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبخ حضور و طبخ نظر</span> ؛ از غایت اهتمام طبخ طعام فرمودن <span class=\"hlight\">:</span> <br />بر جزو و کل خوش است نظر پخته تر کنم <br />دل گرم شوق گشت که طبخ نظر کنم .<br /> <font color=\"Red\">تأثیر.</font><br />به گرمیهای هندستان صبورم <br />گوارا نیست جز طبخ حضورم .<br /> <font color=\"Red\">راضی (آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبخ کردن </span> ؛ پختن . دیگ پختن . آشپزی . پُخت و پز. سلق .<br /></font></div>'),
(175796, 'طبخ', '<span class=\"hlight\">طبخ .</span> <font color=\"DarkGreen\"><b>[ طُب ْ ب َ ]</font></b> (ع اِ) ج ِ طابخ . فرشتگان عذاب . واحد آن طابخ است . (منتهی الارب ).<br /></font></div>'),
(175797, 'طبخ الذهب', '<span class=\"hlight\">طبخ الذهب .</span> <font color=\"DarkGreen\"><b>[ طَ خُذْ ذَ هََ ]</font></b> (ع اِ مرکب ) تشویه ٔ طلا. پُختن زر. (الجماهر بیرونی ص <span class=\"hlight\" dir=\"rtl\">٢٣٣</span>).<br /></font></div>'),
(175798, 'طبخ خانه', '<span class=\"hlight\">طبخ خانه .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) باورچی خانه . (آنندراج ). مطبخ . آشپزخانه .<br /></font></div>'),
(175799, 'طبخی', '<span class=\"hlight\">طبخی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) وی از قزوین است واوقات خود را بطباخی میگذراند. شخصی است درویش نهاد و نامراد. کهنه شاعر است و شعر خود را چنان دردمندانه و مؤثر میخواند که بشنونده رقت دست میدهد. بمناسبت شغلش که عاشقی نیز بر آن افزوده و مزید علت شده است، همواره گریان و پریشان است . این ابیات از اوست :<br />نی غم ما و نه پروای دل ما یار را<br />در میان بیهوده از ما رنجشی اغیار را<br />نمونه ٔ تن فرسوده ٔ شهید تو بود<br />همای عشق به دشتی که استخوان انداخت <br />کم التفاتی ازغمزه ٔ تو فهمیدم <br />تبسم تو مرا باز در گمان انداخت .<br />یک شب انیس دیده ٔ گریان من شدی <br />بستی به روی دیده ٔ من راه خواب را.<br />فتاد پرتو روی توام بخلوت دل <br />چه شعله ها که برآمد ازین چراغ مرا.<br />طبخی وجود توست درین ره حجاب تو<br />آهی ز دل برآر و بسوز این حجاب را.<br />رجوع به تاریخ ادبیات ایران ادوارد براون ترجمه ٔ رشیدیاسمی ص <span class=\"hlight\" dir=\"rtl\">٨٨</span> شود. (ترجمه ٔ مجمعالخواص ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span>).<br /></font></div>'),
(175800, 'طبخی', '<span class=\"hlight\">طبخی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص نسبی ) منسوب به طبخ . <BR><font color=\"Blue\">◄</font> پُخت . آنچه ویژه ٔ فن آشپزی باشد.<br /></font></div>'),
(175801, 'طبر', '<span class=\"hlight\">طبر.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (معرب، اِ) معرب تبر. فاس .<br /></font></div>'),
(175802, 'طبر', '<span class=\"hlight\">طبر.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) نام ولایت طبرستان است که مازندران باشد و بید طبری که به بید مجنون اشتهار دارد منسوب بدانجاست . (برهان ). طبرستان باشد که دیار استراباد است . و بید طبری به آن منسوب است . و آنرا بید موله نیز گویند <span class=\"hlight\">:</span> <br />همچو مستان صبوحی زده افتان خیزان <br />شاخهای سمن تازه و بید طبری .<br /> <font color=\"Red\">ظهیر.</font><br />رجوع به طبرستان شود.<br /></font></div>'),
(175803, 'طبر', '<span class=\"hlight\">طبر.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) دهی است از بخش هویزه شهرستان دشت میشان، واقع در <span class=\"hlight\" dir=\"rtl\">٣٠</span>هزارگزی باختری هویزه، کنار شعبه ٔ نهر سابله . دشت، گرمسیر با <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> تن سکنه . آب آن از هور. محصول آنجا لبنیات . شغل اهالی گله داری و گاومیش داری . راه آن در تابستان اتومبیل رو است . بنای امامزاده فاضل قدیمی است .ساکنین از طایفه ٔ بنی صالح هستند و برای تعلیف احشام به ییلاق میروند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(175804, 'طبر', '<span class=\"hlight\">طبر.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) دهی است از دهستان شقان بخش اسفراین شهرستان بجنورد، واقع در <span class=\"hlight\" dir=\"rtl\">٨٢</span>هزارگزی شمال باختری اسفراین و <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی جنوب شوسه ٔ عمومی بجنورد به شقان . کوهستانی وسردسیری است با <span class=\"hlight\" dir=\"rtl\">١٦٢٨</span> تن سکنه . آب آن از قنات و چشمه . محصول آنجا غلات . شغل اهالی زراعت و مالداری . راه آن اتومبیل رو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175805, 'طبر', '<span class=\"hlight\">طبر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b>(ع مص ) برجستن . <BR><font color=\"Blue\">◄</font> پنهان گردیدن . <BR><font color=\"Blue\">◄</font> جهیدن اسب بر ماده . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(175806, 'طبر', '<span class=\"hlight\">طبر.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ستون قصر. (منتهی الارب ) (آنندراج ). یک رکن خانه . (منتخب اللغات ).<br /></font></div>'),
(175807, 'طبر ستران', '<span class=\"hlight\">طبر ستران .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ رِ س َ ت َ ]</font></b> (اِخ ) از نواحی ارمینیه محسوب است . و آن ولایت نااستواری است . در کتب فتوح نامی از آن برده شده، و گویند سلیمان بن ربیعة بسال <span class=\"hlight\" dir=\"rtl\">٢٥</span> هَ . ق . آنجا را فتح کرد. (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span>).<br /></font></div>'),
(175808, 'طبراخ', '<span class=\"hlight\">طبراخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) لقب والد علی بن هاشم محدث . (یا آن طِمراخ به میم است ). (منتهی الارب ).<br /></font></div>'),
(175809, 'طبراخی', '<span class=\"hlight\">طبراخی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص نسبی ) منسوب است به طبراخ که لقب جدّ ابوالحسن علی بن ابی هاشم عبیداﷲبن الطبراخ الطبراخی از اهل بغداد است . (سمعانی ).<br /></font></div>'),
(175810, 'طبران', '<span class=\"hlight\">طبران .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) دهی است بسرحد قومس . (منتهی الارب ). شهری است بسرحد قومس . (معجم البلدان ). طابران . یکی از دو شهری بود که مجموع آنها را طوس مینامیده اند. و شهر دیگر نوقان بوده است . (حواشی چهارمقاله ٔ عروضی ص <span class=\"hlight\" dir=\"rtl\">٤٧</span>). و طابران را طبران نیز گفته اند. رجوع به طابران شود. <BR><font color=\"Blue\">◄</font> در سابق نزدیک دروازه ٔ اصفهان نیز جائی موسوم به «طبران » بوده : الی ان وصلنا الی طبران، علی باب اصبهان . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦</span>). رجوع به تاریخ الحکماء قفطی چ لیپسیک ص <span class=\"hlight\" dir=\"rtl\">٤٢١</span> شود.<br /></font></div>'),
(175811, 'طبرانی', '<span class=\"hlight\">طبرانی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ص نسبی ) منسوب است به طبریه که قصبه ای است به اُردن . از آن قصبه است حافظ ابوالقاسم سلیمان بن احمد. (آنندراج ) (منتهی الارب ). منسوب است به طبریه شام . (انساب سمعانی ). رجوع به طبریه شود. <BR><font color=\"Blue\">◄</font> منسوب است به طابران طوس . هنگام نسبت دادن طبرانی گویند و صحیحش طابرانی است . (انساب سمعانی ).<br /></font></div>'),
(175812, 'طبرانی', '<span class=\"hlight\">طبرانی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) ابوالقاسم سلیمان بن احمدبن ایوب بن مطیر اللخمی الشامی . از محدثان بزرگ و مولد او به طبریه ٔ شام بوده، بسال <span class=\"hlight\" dir=\"rtl\">٢٦٠</span> هَ . ق . وی به حجاز، یمن، مصر، عراق و فارس در طلب حدیث سفر گزید، سه معجم در احادیث تصنیف کرد: کبیر، وسط و صغیر، و نیز «تفسیر» و «الاوابل » و «دلائل النبوّة» از تصنیفات اوست و جز آنچه ذکر شد هم تصنیفات دیگر دارد. وفات او بسال <span class=\"hlight\" dir=\"rtl\">٣٤٠</span> هَ . ق . بوده است . (تاریخ وفات طبرانی <span class=\"hlight\" dir=\"rtl\">٣٦٠</span> هَ . ق . بوده، و ظاهراً در طبع ارقام <span class=\"hlight\" dir=\"rtl\">٦٠</span> به <span class=\"hlight\" dir=\"rtl\">٤٠</span> تبدیل شده و سهوی رخ داده است ). (زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨٤</span>). ابن خلکان جّد او را بنام مطیر مصغر مطر یاد کرده، گوید: حافظ عصر خود بود و سی و سه سال در طلب حدیث از شام بسوی عراق، حجاز، یمن، مصر و بلاد جزیره ٔ فراتیه پیوسته در حال کوچ بود و سماع بسیار کرد و شماره ٔشیوخ وی به هزار تن رسد. او راست مصنفات سودمند، ازآن جمله است معاجم سه گانه ٔ او و آن مشهورترین کتابهای وی است . حافظ ابونعیم و خلق بسیاری از او روایت دارند، مولد او به طبریه ٔ شام بوده، ولی اصفهان را برای سکونت و اقامت برگزید، تا آنکه روز شنبه <span class=\"hlight\" dir=\"rtl\">٢٨</span> ذی القعده ٔ <span class=\"hlight\" dir=\"rtl\">٣٦٠</span> هَ . ق . در اصفهان فرمان یافت، و بر این تقدیر یکصد سال زندگانی کرد، برخی هم فوت او را در ماه شوال ذکر کرده اند، واﷲ اعلم . وی را پهلوی مدفن حممةالدوسی از یاران رسول خدای صلی اﷲ علیه و آله و سلم به خاک سپردند. (ابن خلکان چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣١</span>). صاحب معجم المطبوعات نیز ترجمه ٔ احوال طبرانی را با مختصر تغییری آورده، و در آخر گوید: المعجم الصغیر او شامل دو کتاب است : غنیةالالمعی لابی الطیب محمد شمس الحق، التحفة المرضیة للشیخ حسین بن محسن الانصاری که در دهلی بچاپ رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٦</span>). و نیز او راست کتاب الدعوات . (کشف الظنون ج <span class=\"hlight\" dir=\"rtl\">١</span>). و رجوع به الاعلام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٥</span> و سلیمان بن احمدبن ایوب شود.<br /></font></div>'),
(175813, 'طبرج', '<span class=\"hlight\">طبرج .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع اِ) مورچه . (منتهی الارب ).<br /></font></div>'),
(175814, 'طبرخزی', '<span class=\"hlight\">طبرخزی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ خ َ ]</font></b> (ص نسبی ) نسبتی است به طبرستان و خوارزم . سمعانی گوید: ابوبکر (محمدبن عباس خوارزمی ) شاعر معروف بدین نسبت اختصاص یافته است، زیرا پدرش طبری و مادرش خوارزمی بوده است، و از طبری و خوارزمی، اختصاراً نسبت مرکبی استعمال و طبرخزی گفته اند و او نیز بدین نسبت شهرت یافته است . (سمعانی ).<br /></font></div>'),
(175815, 'طبرخشت', '<span class=\"hlight\">طبرخشت .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ خ ِ ]</font></b> (اِ) نوعی است از صمغ و لون او به لون خاکستر مشابهت دارد و معدن او در نواحی سیستان است و از آن موضع تا سیستان مسافت دور است و طعم او از صبر تلختر باشد، او را به شربت خورند از جهت دفع ریشها هرگه در موضع خویش بتدریج زیاده شود، چون شرینه و امثال آن . (ترجمه ٔ صیدنه ٔ ابوریحان ). صمغ رامیثا است . (فهرست مخزن الاودیه ).<br /></font></div>'),
(175816, 'طبرخون', '<span class=\"hlight\">طبرخون .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِ) بید سرخ باشد، و آنرا بید طبری نیز خوانند. (برهان ). نوعی از صفصاف است که به فارسی سرخ بید خوانند و به هندی تن نامند. سرخ بید طبری . (حافظ اوبهی ) (شعوری ). <BR><font color=\"Blue\">◄</font> بعضی گویندطبرخون سه عدد چوب است که آنرا با حلقه های آهنین تعبیه کرده، بهم پیوسته اند و شاطران بر دست گیرند و مرغان و جانوران را بدان زنند و شکار کنند. (برهان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبرخون زدن </span> ؛ هلاک ساختن <span class=\"hlight\">:</span> <br />طبرزد دهم چون شوم آب خیز<br />طبرخون زنم چون کنم غمزه تیز.<br /> <font color=\"Red\">نظامی (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> بمعنی عناب هم آمده است، و آن میوه ای باشد دوائی شبیه به سنجد. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> چوبی سرخ باشد <span class=\"hlight\">:</span> <br />زین هر دو زمین هرچه گیا روید تا حشر<br />بیخش همه روین بود و شاخ طبرخون .<br /> <font color=\"Red\">عنصری (فرهنگ اسدی ).</font><br />چوبی باشد سرخ که بعضی آنرا طفالغو گویند. (صحاح الفرس ). چوبی است سرخ رنگ تلخ . <BR><font color=\"Blue\">◄</font> صندل سرخ . (غیاث اللغات ) (آنندراج ). و در صورالاقالیم گوید: که طبرخون در جبال فرغانه میباشد. (نزهةالقلوب ) <span class=\"hlight\">:</span> و اندر کوههای فرغانه معدن زر و سیم است و چراغ سنگ و سنگ پای زهر و سنگ مغناطیس و داروهای بسیار است و از او طبرخون خیزد، و گیاههائی که اندر داروهای عجیب بکار شود. (حدود العالم ).<br />همه دشت مغز سر و خون گرفت <br />دل سنگ رنگ طبرخون گرفت .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت هیشوی کاین نرّه گرگ <br />سرش برتر است از هیونی سترگ <br />دو دندان او همچو دندان پیل <br />دو چشمش طبرخون و چرمش چو نیل .<br /> <font color=\"Red\">فردوسی .</font><br />چو گلبرگ رخسار و چون مشک موی <br />به رنگ طبرخون لب مشکبوی .<br /> <font color=\"Red\">فردوسی .</font><br />گه معصفرپوش گردد گه طبرخون تن شود<br />گاه دیباباف گردد گه طرائف گر شود.<br /> <font color=\"Red\">فرخی .</font><br />شکر نخواهد وگر تو شکرش گوئی <br />از خجلی روی او شود چوطبرخون .<br /> <font color=\"Red\">فرخی .</font><br />ز کیمخت گردون دوصد بسته تنگ <br />همیدون طبرخون و چینی خدنگ .<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />بجای دگر دید دو بیشه تنگ <br />ازین سو طبرخون از آن سو خدنگ .<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />گیاهان بد از خون طبرخون شده <br />دل خاره زیر تبر خون شده .<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />طبرخون رخانی که خونریزچشمش <br />رُخانم بشوید به آب طبرخون .<br /> <font color=\"Red\">سوزنی .</font><br />چرا که موی تو زو رنگ قیر دارد و مشک <br />رُخانت رنگ طبرخون و طبع تر دارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />به پیش حمله ٔ حیدر چنین روز<br />طبرخون رنگ بودی خاک میدان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />فضل طبرخون نیافت سنجد هرگز<br />گرچه بدیدن چو سنجد است طبرخون .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مرا رنگ طبرخون دهر جافی <br />بشست از روی بیرم باب زریون .<br /> <font color=\"Red\">ناصرخسرو.</font><br />زرد چو زهره است عارض بهی و سیب <br />سرخ چو مریخ روی نار و طبرخون .<br /> <font color=\"Red\">ناصرخسرو.</font><br />طبرخون با سهی سروت قرین باد<br />طبرخون را طبرزد همنشین باد.<br /> <font color=\"Red\">نظامی .</font><br />شخصی او را دویست چوب تازیانه ٔ طبرخون آورد. (جهانگشای جوینی ). <BR><font color=\"Blue\">◄</font> رنگ سرخ . (برهان ) <span class=\"hlight\">:</span> <br />هوا خیره گشت از فروغ درخش <br />طبرخون و شبگون و زرد و بنفش .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(175817, 'طبرخونی', '<span class=\"hlight\">طبرخونی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ص نسبی ) منسوب به طبرخون . قرمز. سرخ . سرخ رنگ <span class=\"hlight\">:</span> <br />گر خون تو نخورد بشب گردون <br />پس کوت آن رخان طبرخونی .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(175818, 'طبردار', '<span class=\"hlight\">طبردار.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (نف مرکب ) حامل طبر. بردارنده ٔ طبر.<br /></font></div>'),
(175819, 'طبرداریة', '<span class=\"hlight\">طبرداریة.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ری ی َ ]</font></b> (ع ص نسبی، اِ مرکب ) منسوب به طبردار، رسته ای از رسته های لشکر که به طبر مسلح بودند و در اواسط قرن هشتم هجری نیز این دسته وجود داشته اند: الوظیفة السابعه (حمل السلاح ) حول الخلیفة فی المواکب و اصحاب هذه الوظیفة یعبر عنهم لزیهم بالرکابیه و بصبیان الرکاب الخاص . و هم الذین یعبر عنهم فی زماننا بالسلاحداریة و الطبرداریة. (صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٨٤</span>). والی الطبر تنسب الطبرداریه و هم الذین یحملون الاطبار حول السلطان . (حاشیه ٔ کتاب التاج ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>).<br /></font></div>'),
(175820, 'طبرزد', '<span class=\"hlight\">طبرزد.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ زَ ]</font></b> (معرب، اِ) معرب تبرزد. مأخوذ از پهلوی تورزت، در سانسکریت (دخیل ). توارجه . (برهان قاطع چ معین ذیل تبرزد). بعضی چنین گفته اند: مُعرب است، گویا که اطراف آن کنده شده به تبر. طبرزن و طبرزل، مثله . (منتهی الارب ) (آنندراج ). شکر. صاحب صحاح گوید: طبرزد، نوعی از شکر است . و قال الاصمعی یقال : سُکر طبرزدٌ علی الصفة. (منتهی الارب ). مُعرب تبرزد است . چون بسیار سخت باشد. گویا که اطرافش را به تبر تراشیده اند، یا آنکه بسبب سختی به تبر شکسته میشود. (غیاث اللغات ) (آنندراج ). اسمی پارسی معرب است و اصل آن تبرزد است، از بهر آنکه صُلب بود نه سست و نرم . و نمک تبرزد از آن گویند که صلب بود. (اختیارات بدیعی ). این کلمه چون صفتی برای شکر و هم برای نوعی نمک (شاید نمک تُرکی ) آمده است : ملح طبرزد <span class=\"hlight\">:</span> و اگر نمک طبرزد بتراشند، و شیاف کنند بول بیارد و شکم براند. (ذخیره ٔ خوارزمشاهی ). شاید نمک طبرزد نمک سنگ باشد مقابل نمک خرد رجوع به ملح شود. شکر طبرزد یا طبرزد. مبرت (بلغة اهل الیمن ). (مهذب الاسماء). شکر پخته . (زمخشری ). طبرزل . طبرزن . طبرزد. هر سه اسم شکر معقود است که بفارسی نبات گویند. (فهرست مخزن الادویه ) (بحر الجواهر). شکر سفید سخت . <BR><font color=\"Blue\">◄</font> اسم فارسی جمیع اجسام صلبه است، مثل قند و نبات و نمک سنگ . (تحفه ٔ حکیم مؤمن ). <BR><font color=\"Blue\">◄</font> ظاهراً طبرزد بمعنی مُتبلور است . ذرورملکانا، انزروت مدبر، نشاسته، شکر طبرزد، صمغ عربی از هر یکی راستا راست . (ذخیره ٔ خوارزمشاهی ). <BR><font color=\"Blue\">◄</font> قند. انطاکی گوید: طبرزد، شکری است که با عشر وزن آن از شیر بجوشانند تا زفت شود. (تذکره ٔ ضریر انطاکی ) <span class=\"hlight\">:</span> <br />لبان از طبرزد، زبان از شکر<br />دهانش مُکلل به درّ و گهر.<br /> <font color=\"Red\">فردوسی .</font><br />کسی کش مارشیبا بر جگر زد<br />ورا تریاک سازد نه طبرزد.<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br />و قمطرها و نبات و شکر و قند و طبرزد و اصناف میوه های خشک و تر پیش هر یک بر طبقها نهادندی . (تاریخ طبرستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عسل طبرزد</span> . رجوع به عسل شود. داروئی که مردم محرور را شاید: بگیرند شیر تازه از گاو جوانه دورطل بغدادی، و دو کف ترنگبین طبرزد پاک کرده برافکنند و بجوشانند تا به قوام انگبین بازآید. (ذخیره ٔ خوارزمشاهی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">نمک طبرزد</span> ؛ <font color=\"DarkGreen\"><b>[ در عسرالبول ]</font></b> نمک طبرزد بشکافند و شاخ کنند، به مجرای قضیب درنهند. (ذخیره ٔ خوارزمشاهی ). و مثال این مراتب همچنان است که قنادی از نیشکر قند سفید بیرون آورد.اول که بجوشانند نبات سفید بیرون آورد. دوم مرتبه که بجوشانند شکر سفید بیرون آورد. سوم مرتبه شکر سرخ .چهارم مرتبه طبرزد. پنجم مرتبه شکر قوالب . ششم مرتبه دُردی ماند که آنرا قُطاره نامند، بغایت سیاه و کدر باشد، و در هر مرتبه صفا و سفیدی کم شود، تا سیاهی و تیرگی بماند و باید که ظُلمت و کدورت در اجزاء وصف قند سفید تعبیه باشد، تا آنکه قند در مقام قندی ازخاصیتی که در ظلمت و کدورت است بقدر احتیاج بهره داشته باشد، و چون بمقام نباتی رسد نبات از آن بهره ٔ خود را بردارد... و چنانکه در نبات ظلمت کدورت مرئی نمیشود در قُطاره سفید مرئی نمیشود، و هر یک در مقام خود کمالی و خاصیتی دارند که در دیگری یافت نمیشود، آنجا که نبات مفید است، شکر بکار نیاید، و جائی که شکر نافع است، نبات فائده ندهد... در این مثال قند صافی روح پاک مُحمدی است ... پس ارواح انبیا را نبات صفت از قند روح محمدی بیرون آوردند. (منتخب مرصادالعباد شیخ نجم الدین رازی ).<br />از دست دوست هرچه ستانی شکر بود<br />وز دست غیر دوست طبرزد طبر بود.<br /> <font color=\"Red\">سعدی .</font><br />نفیر طبرزد چو سُرنا زدند<br />ز میدان خوان طبل گیپا زدند.<br /> <font color=\"Red\">بسحاق اطعمه .</font><br />و رجوع به المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٢٨٨</span> شود.<br /></font></div>'),
(175821, 'طبرزد', '<span class=\"hlight\">طبرزد.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ زَ ]</font></b> (اِخ ) نامی از نامهای ایرانی .<br /></font></div>'),
(175822, 'طبرزدآمیز', '<span class=\"hlight\">طبرزدآمیز.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ زَ ]</font></b> (ن مف مرکب ) آمیخته به طبرزد <span class=\"hlight\">:</span> <br />از لب شکری طبرزدآمیز<br />در بوسه طبرزدی شکرریز.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175823, 'طبرزدانگیز', '<span class=\"hlight\">طبرزدانگیز.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ زَ اَ ]</font></b> (نف مرکب ) ایجادکننده ٔ طبرزد. <BR><font color=\"Blue\">◄</font> شکرانگیز. (وصف لب ) <span class=\"hlight\">:</span> <br />مجنون به جواب آن شکرریز<br />بگشاد لب طبرزدانگیز.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175824, 'طبرزدفشان', '<span class=\"hlight\">طبرزدفشان .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ زَ ف ِ ]</font></b> (نف مرکب ) طبرزدریز <span class=\"hlight\">:</span> <br />فقاع ِ گلابی ِ گلشکری <br />طبرزدفشان از دم عنبری .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175825, 'طبرزل', '<span class=\"hlight\">طبرزل .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ زَ ]</font></b> (معرب، اِ) طبرزد. (بحر الجواهر) شکر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اسم شکر معقود است که به فارسی آنرا نبات نامند. (فهرست مخزن الادویه ). قند ابلوج . شکر تبرزد. (مهذب الاسماء). طبرزن . رجوع به المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٨</span> شود.<br /></font></div>'),
(175826, 'طبرزن', '<span class=\"hlight\">طبرزن .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ زَ ]</font></b> (معرب، اِ) شکر. (منتهی الارب ). شکر تبرزد. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> اسم شکر معقود است که به فارسی آنرا نبات نامند. (فهرست مخزن الادویه ). طبرزل . قند ابلوج . طبرزد. (بحر الجواهر). و رجوع به المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٨</span> شود.<br /></font></div>'),
(175827, 'طبرزک', '<span class=\"hlight\">طبرزک .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی است جزء دهستان افشاریه ٔ بخش آوج شهرستان قزوین، واقع در <span class=\"hlight\" dir=\"rtl\">٢٢٠٠٠</span>گزی شمال خاور آوج . دامنه، معتدل است با <span class=\"hlight\" dir=\"rtl\">٧٧٦</span> تن سکنه . شغل اهالی زراعت و صنایع دستی زنان آنجا قالی و جاجیم بافی می باشد و راه آن مالرو است و از طریق رادکان میتوان ماشین برد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(175828, 'طبرزین', '<span class=\"hlight\">طبرزین .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِ مرکب ) معرب تبرزین . نوعی سلاح است بشکل طبر. رجوع به طبردار، طبرداریه و المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٨</span> شود. تبری دارای دو لبه که غالباً آنرا به قربوس زین آویزان میکردند و هو فأس السرج . ج، طبرزینات . این کلمه را بصورت طربزین هم نقل کرده اند. رجوع به دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span> و تبرزین شود.<br /></font></div>'),
(175829, 'طبرس', '<span class=\"hlight\">طبرس .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ رِ ]</font></b> (ع ص ) نیک دروغگوی .(منتهی الارب ) (آنندراج ). دروغگو. (منتخب اللغات ).<br /></font></div>'),
(175830, 'طبرس', '<span class=\"hlight\">طبرس .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (اِخ ) معرب تفرش . سیدحسین بن سیدرضای بروجردی، معاصر شیخ مرتضی انصاری و صاحب جواهر در رجال منظوم خود گوید <span class=\"hlight\">:</span> <br />و المصطفی الجلیل حبر الطبرسی <br />ذوالنقد عاصرالتقی المجلسی .<br />الامام السعید، ابوعلی الفضل بن الحسین الطبرسی .طبرس منزلی است میان قاشان و اصفهان . (تاریخ بیهق ص <span class=\"hlight\" dir=\"rtl\">٢٤٢</span>). رجوع به طبرسی شود.<br /></font></div>'),
(175831, 'طبرسا', '<span class=\"hlight\">طبرسا.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) یکی از دهات بلوک فخر عمادالدین از توابع استرآبادرستاق که در وقفنامه ٔ مورخ سال <span class=\"hlight\" dir=\"rtl\">٩٨٩</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٨١</span> م . در تصرف سادات شیرنگ میباشد، نامی از آن برده شده است . (سفرنامه ٔ مازندران و استرآباد رابینو ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175832, 'طبرستان', '<span class=\"hlight\">طبرستان .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ رِ ]</font></b> (اِخ ) (از: طبر+ ستان، مزید مؤخر مکان ) لغتاً بمعنی مکان طبر (تپور) ها. و تپور نام قوم قدیمی ساکن آن ناحیت بوده است . (برهان ). بلادی است فراخ و وسیع طبری منسوب به آن . (منتهی الارب ) (آنندراج ). مؤلف روضات الجنات ذیل ترجمه ٔ احمدبن علی بن ابیطالب الطبرسی آورده : من اهل طبرستان بفتح الطاء والباء والراء و اسکان السین، کما قیدها الحازمی و جری علیهاالعامة. او بفتح الاولین مع اسکان السین، کما ذکره ابن قتیبة فی ادب الکاتب، و قال معناه بالفارسیة آخذةالفاس، و کانه لکثرة وجود هذه الاَّلة فیها من جهة ضرورة قطعالاشواک، و قمعالاشجار، و قلع الموانع من طریق المار. و هو عربی مازندران المسمی عند الاعاجم البلاد المعینه من نواحی دارالمرز کما فی تلخیص الاَّثار. (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">١٨</span>). و لقب آنرا دارالملک نیز گفته اند. ناحیتی است بزرگ از این ناحیت دیلمان، و حدش از چالوس است تا تمیشه، و این ناحیتی است آبادان و بسیارخواسته، و بازرگانان بسیار، و طعامشان بیشترین نان برنج وماهی است . بام خانه هاشان همه سفال سرخ است از بسیاری باران که آنجا آید به تابستان و زمستان . و شهرک تمیشه و لمراسک و شهر ساری و شهرک مامطیر و شهرک ترجی و شهر میله و شهر آمل، قصبه ٔ طبرستان و شهرک الهم و شهرک چالوس و شهرک روذان و شهرک ناتل و شهرک کلار و ناحیت کوش از ناحیت طبرستان است . (حدود العالم صص <span class=\"hlight\" dir=\"rtl\">٨٤</span> - <span class=\"hlight\" dir=\"rtl\">٨٥</span>). یاقوت در معجم البلدان آورده که طبرستان بفتح اول و ثانی و کسر ثالث، مرکب از دو کلمه است : طبر که بمعنی تبر است و استان که بمعنی موضع یا ناحیت است، و طبری منسوب بدان است . و آن عبارت است از شهرهای وسیع و بسیاری که من حیث المجموع بدین نام خوانده شده است . از طبرستان چندان مردمان عالم و ادیب و فقیه برخاسته اند که شمار آنان از حد احصاء خارج است . غالب نواحی آن کوهستان است . شهرهای نامی آن دهستان و جرجان و استرآباد و آمل که کرسی آن محسوب می شود و ساریة (ساری ) که مانند آمل است و شالوس که کم از آمل نیست و بسا باشد که جرجان را از توابع خراسان شمارند، و بسا شهرهای دیگر طبرستان را مازندران نیز نامند و ندانم از چه تاریخ نام مازندران را بر طبرستان نهاده اند، چه در کتابهای باستانی این نام را نیافتم، و فقط از افواه مردم طبرستان لفظ مازندران را شنیده ام و بدون شک مفهوم هر دو لفظ یکی است . بلاد طبرستان مجاور جیلان و دیلمان واقع و حدود آن ری و قومس و بحر خزر و دیلم و جیل است . من اطراف و جوانب طبرستان را دیده و کوههای آنرا مشاهده کرده ام . سرزمینی است پرآب و درخت های انبوه با شاخه های فروهشته، دارای میوه ٔ بسیار، اما بلادی است مهیب و هولناک و هوائی بس ناسازوار دارد، ارتفاعات وی کم و اختلاف و منازعه بین مردم آنجا بسیار است . اینک ما گفتار دانشمندان را درباره بلاد طبرستان و شرح فتوحات اسلامیه ای را که در آن ناحیت انجام یافته و مأخذ اشتقاق کلمه ٔ طبرستان را با آنکه مطالعه کنندگان را سودی نبخشد، مع ذلک از نظر آنکه آنچه از زبان قلم جاری می شود نتیجه ٔ مشاهدات و مسموعات خود ما می باشد بیان میکنیم . علمای فن جغرافیا گفته اند:طیلسان (طالشان ) و طالقان و خراسان، جز خوارزم از فرزندان اشبق بن ابراهیم الخلیل علیه السلام اند، و دیلم پسران کماشج بن یافث بن نوح علیه السلام میباشند، و بیشتر آنان کوههای ولایت خود را به نام خویش نامگذاری کرده اند. مگر ایلام که گروهی از دیلمند و آنان از نسل باسل بن ضبةبن ادابن طانجةبن الیاس بن مضر هستند، و ساکنان موقان و جبال آن که آنها نیز از نژاد طبرستانی اند، از اولاد کماشج بن یافث بن نوح علیه السلام بشمار روند.از ایرانیان ثقة و مقبول القول روایت است : وقتی در لشکریان یکی از اکاسره، گروه بسیاری از گنهکاران واجب القتل گرد آمده بودند و از شاهنشاه طلب بخشایش و قبول توبه می کردند، کسری با وزراء خویش در مقام مشاورت برآمد، و نخست از شماره ٔ آنان پرسش کرد، گفتند گنهکاران خلق بسیاری می باشند، کسری گفت : جایگاهی فراهم آورید تا همگی را در یکجای دربند و زندان نهیم، آنگاه فرمان دادند تا در شهرستانهای کشور محلی مناسب و فراخور گنجایش آنان در نظر گرفته گزارش دهند، مأمورین نیز پس از گردش و تفحص در اطراف و جوانب کشور ایران چون به جبال طبرستان رسیدند مکانی مناسبتر از آنجا نیافتند، و موقع آن جایگاه را بعرض کسری رساندند. کسری فرمان داد تا عامه ٔ گنهکاران را بدان محل انتقال دهند، و آنان را در همان جای بازداشت کنند. محل مذکوردر این تاریخ (مقصود تاریخ تألیف معجم البلدان است ) عبارت است از کوهی که دارای سکنه نیست . پس از سالی، کسری از حال گنهکاران بازپرسید، و کسی را بپرسش احوال آنان روان داشت، آن کس فرمان برد، و بجایگاه ایشان برفت، و کیفیت حال آنان را بسی ناخوش یافت و از نیازمندی آنها به اسباب زندگانی پرسش کرد. گنهکاران به اتفاق کلمت گفتند: تبرها تبرها، و «ها» علامت جمع است در کلام ایرانیان و مقصودشان آن بود که به تبر بسیار نیازمندیم تا درختها را ببریم، و از قطعات آن آسایشگاهی جهت خویش فراهم سازیم . مأمور بازگشت و ماجرابه عرض رساند. چون کسری بر حال آنان وقوف یافت، فرمان داد بمیزانی که احتیاج آنان مرتفع شود، برای آنهاتبر آماده سازند، و فرمان بردند. چون سالی بگذشت کسری کرت دیگر کسی را به تفقد احوال ایشان گسیل داشت، چون فرستاده بدان جایگاه رسید هر یک از آنان را صاحب کاشانه ای یافت، هنگام بازگشت نیز از آنان پرسید دیگر چه خواهید، گفتند: زنان زنان، یعنی زن خواهیم . رسول بازگشت و جریان مشاهدات و گفتگوی خویش را با آنان گزارش داد، کسری فرمان داد تا هرچند تن از زنان را که در زندانها هستند بدان کوه نزد گنهکاران فرستند، وچنین کردند. و پس از چندی بر اثر تناسل و توالد بین آنان تعداد آنها روی به فزونی نهاد، و به نام طبرزنان مشهور و معروف گردیده ؛ سپس این لفظ را تعریب کرده طبرستان گفتند. این بود روایتی که از ایرانیان شنیده شده است ؛ ولی آنچه نزد من آشکار و بحقیقت مقرون است و مشاهدتاً نیز از آنها دیده ام این است که اهل این کوهستان پیوسته در جنگ هستند، و بیشتر ساز و سلاح آنها بلکه بطور کلی اسلحه ٔ آنان عبارت از تبر است . و کمتر اتفاق افتد که تنی از درویش یا توانگر آنها را از خرد و بزرگ ببینی که حامل تبر نباشند، گوئی بواسطه ٔ تبر بسیاری که فیمابین آنان مورد استعمال است، این ناحیت را طبرستان نام نهاده اند چه طبرستان را صرف نظر از تعریب، جز «جایگاه تبرها» - موضع الاطبار - معنی دیگری نخواهد بود. واﷲ اعلم . ابوالعلاء السروی در وصف طبرستان گفته است، بروایت ابومنصور النیشابوری :<br />اذا الریح فیها جرت الریح اعجلت <br />فواختها فی الغصن ان تترنما<br />فکم طیرت فی الجوورداً مدثراً<br />یقلبه فیه و ورداً مدرهماً<br />و اشجار تفاح کان ثمارها<br />عوارض ابکاریضا حکن مغرماً<br />فان عقدتها الشمس فیها حسبتها<br />خدواً علی القضبان فذاً و توأماً<br />تری خطباءالطیر فوق غصونها<br />تبث علی العشاق وجداً معتماً<br />در قدیم ابتدای خاک طبرستان، آمل، سپس مامطیر، بوده که بین مامطیر و آمل شش فرسنگ مسافت است . پس از آن، ویمه است که از مامطیر تا آنجا شش فرسنگ مسافت میباشد، بعد از ویمه ساریة و طمیس است که مابین آن دو شهر نیز شانزده فرسنگ راه است، و آنجا پایان حدّ طبرستان و جرجان باشد. واز ناحیه ٔ دیلم بر پنج فرسنگ از آمل، شهری است که آنرا ناتل گویند، سپس شالوس است که سرحد جبل بشمار میرود. این بود شهرهای سهلی (دشتی ) طبرستان و اما شهرهای کوهستانی آن، یکی کلاراست، سپس شهر کوچکی است که سعیدآباد نام دارد، پس از آن شهر رویان است و آن بزرگترین شهرهای کوهستانی طبرستان است . آنگاه در کوهستان آنجا از طرف حدود خراسان، شهری است به نام تمار، و شیّرز و دهستان . چون از ارز بگذری، به کوههای وندادهرمز خواهی رسید، و از آن کوهها که بگذشتی، به جبال شروین رسی، و آن جبال جزو مملکت بن قارن محسوب است . سپس دیلم است و بعد از آن گیلان . بلادری گوید: شهرهای طبرستان هشت است، از آن جمله ساریه است که از زمان طاهریه مقر حکومت واقع شد، و پیش از آن حاکم نشین طبرستان شهر آمل بود. حسن بن زید، و محمدبن زید نیز آمل را مقر و مقام خود قرار دادند. از رساتیق آمل : اُرَم خاست اعلی و اُرَم خاست اسفل و مِهروان و اصپهبد و نامیه و طمیس میباشد. بین ساریة و سلینة از طریق جبال سی فرسنگ و بین ساریة و مهروان ده فرسنگ و بین ساریة و دریا سه فرسنگ و بین جیلان و رویان دوازده فرسنگ و بین آمل و شالوس که در ناحیه ٔ جبال است بیست فرسنگ وطول طبرستان از جرجان تا رویان سی و شش فرسنگ و عرض آن بیست فرسنگ که سی و شش فرسنگ طول در چهار فرسنگ عرض آن در دست شکری و باقی که سی و شش فرسنگ طول و شانزده فرسنگ عرض باشد، دستخوش جنگلهای کوه و دشت است و عرض از کوه بسوی دریا در نظر گرفته شده است .<br />ذکر فتوح طبرستان : پادشاهان ایران را رسم چنان بود که پیوسته سپهبدی را بفرمانروائی طبرستان که در حصانت و استورای مشهور جهان بود میفرستادند، و از هنگامی که عقد لوای فرمانروائی سپهبد بسته میشد، وی را از آن شغل معزول نمیکردند تا رخت از این جهان بربندد، آنگاه اگر او را فرزندی بود فرزند وی را بفرمانروائی برقرار میساختند و الا سپهبدی دیگر بجای سپهبد متوفی منصوب میداشتند و این قاعده تا زمان ظهوردولت اسلام جاری و برقرار بود. چون جهانگشائی مسلمانان توسعه یافت و نوبت فتح طبرستان رسید، صاحب طبرستان در ازاء مالی اندک پیشنهاد صلح کرد و مسلمانان نیزپذیرفتند، چه از صعوبت مسلک طبرستان باخبر بودند و امر طبرستان بدین منوال دوام داشت تا زمانی که عثمان بن عفان بسال <span class=\"hlight\" dir=\"rtl\">٢٩</span> هَ . ق . سعیدبن العاصی را به ولایت کوفه و عبداﷲبن عامربن کریزبن حبیب بن عبد شمس را به ولایت بصره برگماشت . در این هنگام مرزبان طوس نامه ای به سعیدبن العاصی و نامه ای نیز به عبداﷲبن عامر نوشت، و آنان را به خراسان خواند، و به هر یک وعده ٔ تولیت طبرستان داد مشروط بر آنکه به جنگ و کارزار اقدام وبر صاحب طبرستان غلبه کنند. ابن عامر پیشی جست و به خراسان رفت، اما سعیدبن العاصی آهنگ طبرستان کرد و بنابه قول مورخین امام حسن و امام حسین علیهماالسلام نیز در این سفر با سعیدبن العاصی بودند. برخی گفته اند سعیدبن العاصی بی آنکه از کسی نامه ای به او رسد از کوفه رهسپار طبرستان شد چون به طبرستان رسید با صاحب طبرستان کارزار کرد و طمیشة و نامیه را بگشود. (نامیه قریه ای است ) پادشاه جرجان از در صلح داخل شد، و بر عهده خود گرفت که دویست هزار درهم بغلیه ٔ وافیه بپردازد، و ایفاء تعهد کرد: و از جمله شهرهائی را که سعیدبن العاصی گشود، رویان و دنباوند بود، و اهالی جبال سعید را مالی بخشیدند. چون نوبت خلافت به معاویه رسید مصقلةبن هبیرة را والی طبرستان کرد، وی با بیست هزار تن به طبرستان شد و داخل شهر گردید، گروهی را اسیر کرد و بسیاری را بکشت . همین که از تنگه ها و جایهای دشوار کوه بگذشت در حین خروج دشمن بر او و سپاهیان وی ناگهان حمله برد و از قلل جبال او و همراهان وی را سنگباران کردند؛ بنحوی که بیشتر سپاهیان مصقله هلاک شدند، و از آن روز این مثل در زبانها و بین مردم سائر شد: لایکون هذا حتی یرجع مصقلة من طبرستان . از آنگاه مسلمانان هر موقع آهنگ کارزار بلاد طبرستان میکردند از اینکه به اندرون شهرداخل شوند خودداری و سخت پرهیز می کردند تا هنگامی که ایام سلیمان بن عبدالملک، یزیدبن المهلب والی خراسان شد و رحل اقامت بطبرستان افکند، اصبهبذ از دیلم کمک لشکری خواست و دیلمیان برای او مدد فرستادند؛ یزیدبن المهلب روزی چند با اصبهبذ بجنگید تا آنکه اصبهبذخواهان صلح گردید و بر عهده گرفت که در هر سال چهارمیلیون و هفتصدهزار درهم مثقالی بپردازد، و چهارصد بار زعفران هدیه فرستد، و همه ساله چهارصد تن مرد که هر یک سپری بر سر نهاده و قنطاری از سیم و بالشی از حریر همراه داشته باشند روانه دارد. یزیدبن المهلب رویان و دنباوند را فتح کرد: و اهل طبرستان مواد قرارداد صلح را گاهی اجرا و گاهی از انجام آن سرپیچی می کردند، تا دوره ٔ خلافت به مروان بن محمد رسید، اهالی طبرستان نقض عهد کردند و از آنچه تعهد کرده بودند همه ساله به دربار خلافت بفرستند سر باز زدند. چون سفاح برمسند خلافت بنشست، عاملی به طبرستان روانه داشت . اهالی با او نیز از در آشتی درآمدند، و با تقدیم مالی او را از خود راضی کردند. سپس با وی هم بفریب و مکر رفتار کردند و بسیاری از مسلمانان را بکشتند. در این اثنا نوبت خلافت منصور دررسید، وی خازم بن خزیمة التمیمی و روح بن حاتم المهلبی را به همراهی مرزوق ابوالخصیب به طبرستان روانه ساخت و چون وارد طبرستان شدند، تا چندی با اهالی در مدافعه و زد و خورد بودند، لکن از مدافعات خود نتیجه نبردند، و کار بر ایشان تنگ گردید هر سه تن با یکدیگر اتفاق کردند که بحکم : الحرب خُدعةٌ با اهالی طبرستان از در مکر و فریب داخل شوند، از این رو خازم و روح با ابوالخصیب نزاعی دروغین کردند، و او را بسیار بزدند، و موی سر و ریش او را بتراشیدند تا او نیز بر اصبهبذ حیله ورزد. ابوالخصیب با حالی پریشان نزد اصبهبذ رفت و از عمال خلیفه شکایت برد، چون اصبهبذ او را نالان و بدحال یافت، وی را تفقد کرد و رقت برد و رفته رفته او را از خواص دربار خود کرد، از این رو ابوالخصیب نیز به هر حیله ای که توانست ملک طبرستان را از حیطه ٔ اقتدار اصبهبذ بیرون آورد و آنجا را مالک شد. عمربن ابی العلا که بشاربن برد این شعر را در وصف او سروده است :<br />اذا ایقظتک حروب العدی <br />فنبه لها عُمراً ثم نم <br />قصابی بود ازاهل ری، گروهی را با خود همراه ساخت و با دیلمیان کارزار کرد و نیک امر لشکر اسلام را به کفایت مقرون داشت . جهوربن مرار العجلی وی را نزد منصور فرستاد، منصور او را منزلتی بخشید. و فرماندهی لشکر به وی بازگذاشت و روز به روز مقامش بالا رفت تا والی طبرستان شد و سرانجام در خلافت مهدی شهادت یافت . سپس موسی بن حفص بن عمربن العلاء و مازیاربن قارن، جبال شروین طبرستان را که سخت ترین و استوارترین کوهها بشمار میرود در روزگار مأمون خلیفه فتح کردند، مأمون پس از این فتح ولایت طبرستان را بالاستقلال بمازیار سپرد و نام وی را بمحمد تبدیل ساخت، و درجت اصبهبذی به او بخشید، و وی تا پایان زندگانی مأمون والی آنجا بود. معتصم نیز که بخلافت نشست امر ولایت طبرستان را بدو محول داشت . مازیار هم مدتی فرمان خلیفه برد، اما عاقبت پس از آنکه شش سال از خلافت معتصم بگذشت نافرمانی کرد و با خلیفه مخالفت ورزید. معتصم به عبداﷲبن طاهر که از دربارخلافت فرمانروای مشرق بود و بر تمام خراسان، ری، قومس و جرجان حکومت داشت، نامه ای نوشت و به وی فرمان داد که با مازیار بجنگد. طاهر، عبداﷲبن الحسن بن الحسین را با گروهی از مردم خراسان بسوی مازیار گسیل داشت .معتصم نیز محمدبن ابراهیم بن مصعب را با گروهی از لشکریان بمدد عبداﷲبن طاهر بفرستاد. همین که سپاهیان آهنگ مازیار کردند، وی پیشدستی کرد و بدون عهد و پیمانی خویشتن را تسلیم حسن بن الحسین ساخت و حسن نیز مازیار را بگرفت و او را در سال <span class=\"hlight\" dir=\"rtl\">٢٢٥</span> هَ . ق . به سر من رأی نزد معتصم روانه داشت . معتصم فرمان داد او را تازیانه زنند و چندان او را تازیانه زدند که در زیر تازیانه جان بداد و سپس او را با بابک خرمی بر یک دار آویختند (در عقبه ای که در مقابل مجلس شرطه واقع است ). پس از مازیار تقلد امر طبرستان بر عهده ٔ عبداﷲبن طاهر محول شد، در عهد ولات طبرستان که دست نشانده ٔ عباسیان بودند، امر مهمی رخ نداد و تاریخ انتصاب هر یک از آنان نیز بر ما نامحقق است . پس از عبداﷲبن طاهر پسرش طاهربن عبداﷲ به ولایت طبرستان منصوب شد، طاهر برادر خویش سلیمان بن عبداﷲبن طاهر را چندی در طبرستان جانشین خویش ساخت . حسن بن زیدالعلوی الحسنی در سال <span class=\"hlight\" dir=\"rtl\">٢٤٩</span>هَ . ق . بر سلیمان خروج کرد و وی را از طبرستان بیرون راند و خود بر آنجا غلبه یافت و طبرستان او را مسلم گردید تا فرمان یافت . پس از مرگ حسن بن زید برادرش محمدبن زید جانشین وی شد... (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٥٠١</span> - <span class=\"hlight\" dir=\"rtl\">٥٠٧</span>). حمداﷲ مستوفی در نزهةالقلوب آورده که حدود قومس و طبرستان با ولایات خراسان و عراق عجم و مازندران و مفازه پیوسته است و حقوق دیوانی آنجا داخل خراسان است . (نزهةالقلوب چ لیدن ص <span class=\"hlight\" dir=\"rtl\">١٦٠</span>). در التدوین فی جبال شروین آمده است که وجه تسمیه ٔ طبرستان آنچه در افواه مشهور است و نویسندگان اسلامی هم بدان تصریح کرده اند آن است که چون حربه و سلاح این مملکت بواسطه ٔ اشتمال بر جنگل که باید درختها همی انداخت و جاها همی ساخت و بواسطه ٔ کثرت اختلاف و مشاجرات ملکی که هیچوقت این ناحیه ٔ عظیم خالی از آن نبوده و اهالی را حمل اسلحه و ادوات ضرورت داشته همیشه تبر بوده و هست و غالباً مرد و زن آنجا به این آلت مسلح میباشند و هیچوقت بدون این حربه بیرون نمی آیند. لهذا آن مملکت به نام طبرستان مشهور شده است و در تعریب تاء منقوطه را به طاء مشالة تبدیل کرده اند. چنانکه در اسم طهران نیز چنین شده است . (التدوین ). و نیز در مرآت البلدان ناصری آورده : طبرستان ولایتی است مشتمل بر بلاد قدیمه وقصبات عظیمه، جبال سخت و بیشه های پردرخت، به کثرت آب و رطوبت هوا مشهور و تمام آن بلاد از اقلیم چهارم است . هوای بعضی بلاد آن مایل به گرمی و بیشتر شهرهای آنرا هوائی معتدل است، میوه های گرمسیری و سردسیری در آن بسیار. بزعم بعضی طهمورث در آن بنای آبادی نهاده، آمل و ساری و قلعه ٔ مور از قدیم بوده و در عهد افراسیاب و کیقباد همین نام داشته و این مملکت را از آن مازندران گویند که ماز نام کوهی است در آن . منوچهری گفته <span class=\"hlight\">:</span> <br />برآمد ز کوه ابر مازندران <br />چو مار شکنجی و ماز اندر آن .<br />سابقاً اینجا را بیشه ٔ مازون نیز گفته اند. محمدبن حسن بن اسفندیار صاحب تاریخ مازندران که در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٦٠٦</span>هَ . ق . بوده، نوشته : مازندران شهری بوده به حد مغرب و نامی که اکنون بر مازندران استعمال کنند جدید است و کوه آنجا را مور و ماز خوانند و آنچه در درون آن کوه است موز اندرون گویند. و آن کوه از حد گیلان کشیده تا بلاد قصران و تا جاجرم و آنچه را طبرستان خوانند از دینار جاری شرقی تا بملاط باشد. و این مواضع در قدیم جنگل بوده، بیشه را تراشیده و در آن شهرها ساختند و قدیمترین شهر آن لاریجان میباشد و فریدون در آنجا تربیت یافته و دارالملک وی بعد از سلطنت تمیشه بودو آن را بیشه مازون میخواندند و بمرور و دهور بیست و چهار شهر مشهور در مازندران معمور شد که حالا غالباً ویران است . نیز محمدحسن بن اسفندیار سابق الذکر گوید: در قدیم آذربایجان و اهار و گیل و دیلم و ری و قومس و دامغان و گرگان را طبرستان می گفته اند. وجه تسمیه آنکه حربه ٔ ایشان تبر بود و الاَّن کماکان، و طبر معرب تبر است . و تحقیق من بنده این است که تبره و تبرک در لغت پهلوی مازندری و فارسی، بمعنی پشته و تل و کوه است، چنانچه قلعه ای بر تل شهر اصفهان بوده و آنرا تبرک می خوانده اند، و قلعه ٔ دیگر در حوالی شهر ری کهنه بر بالای کوه بوده که آن را طبرو می گفته اند و تبرستان بتای فارسی بمعنی کوهستان است و دخلی بحربه ٔ تبر ندارد، چنانکه وقتی یکی از خلفا شخصی را بتفحص بلاد طبرستان فرستاد، وی بعد از ملاحظه ٔ امتعه و وفور نعمای آن ولایت مراجعت کرد و به خلیفه گفت : طبرستان را برای کثرت ارتفاعات و معموریت فراوان، تبرستان باید خواند، یعنی زرستان، بمعنی معدن زر. علی ای حال، حمداﷲ مستوفی و جمعی گفته اند: مازندران هفت بلوک است : جرجان، موردستان استرآباد، آمل، رستمدار و رویان، رعد و سیاه رستاق . و چنانچه گذشت، گویند طبرستان را ولایت چند است، از جمله : بسطام، سمنان، دامغان، فیروزکوه و خرقان، چون مدتی در تصرف ملوک خراسان بوده، لهذا داخل خراسان می شمارند، مانند مملکت قهستان و سیستان و مفازه که ولایتی جداگانه بوده و اکنون داخل خراسان شده است . (مرآت البلدان ناصری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span>). در الجماهر بیرونی ذیل عنوان «فی ذکرالنحاس » گوید: و مایوجد تحت الارض بطبرستان من المزاریق و الحراب النحاسیه، فیمن بهاالمجوس . (الجماهر چ هند ص <span class=\"hlight\" dir=\"rtl\">٢٤٩</span>). و نیز رجوع به الجماهر ص <span class=\"hlight\" dir=\"rtl\">٢١٩</span> شود. ابن عبد ربه در عقدالفرید آورده که در طبرستان کساء طبریة سازند. (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٧</span>). رجوع به کتاب الجماهر ص <span class=\"hlight\" dir=\"rtl\">٧٠</span> اصل و تتمه ٔ کتاب مزبور شود. و صاحب قاموس الاعلام ترکی آرد: طبرستان نام خطه ای است در جهت شمالی ایران، حدود و موقعش کاملاً معلوم نیست، چنانکه از توصیف و تعریف یاقوت حموی برمی آید این خطه عین خطه ٔ مازندران است . جغرافی دانان دیگر این خطه را در بین مازندران و عراق عجم و خراسان و جرجان، یعنی در جهت جنوبی مازندران فرض و تحدید کرده اند، در هر حال شکی نیست که از نزدیکی تهران، تا نزدیکی بسطام، اراضی واقع در دامنه های جنوبی و شرقی کوه البرز با دو قصبه ٔ سمنان و دامغان خطه ٔ طبرستان را تشکیل میدهند. بعضی از اهل فن تمام مازندران را از طرف شمال تا بحر خزر و از سوی مغرب تا حدود گیلان توسعه داده و جزو طبرستان شمرده اند تا آنجا که یاقوت حموی گوید: کلمه ٔ مازندران از محدثات است . اسم اصلی این خطه طبرستان می باشد. حقیقت این است که جغرافی دانان زمان خلفای عباسی این قطعه را طبرستان نامیده اند، اما در شاهنامه مازندران استعمال شده، پس باید گفت که ایرانیان قدیم در دوره ٔ ساسانیان این اسم را بکار می بردند. در تقسیمات کنونی ایران امروز هم کلمه ٔ طبرستان معمول نیست و آن نواحی را ایالت مازندران میگویند، و پاره ای از مواضع را که در ازمنه ٔ گذشته جزو طبرستان بود مثلاً سمنان، داخل ایالت عراق عجم کرده اند یکی از جغرافی نویسان اروپا، طبرستان را در بین مازندران و عراق عجم و خراسان محدود کرده، آنرا میان <span class=\"hlight\" dir=\"rtl\">٢٥</span> و <span class=\"hlight\" dir=\"rtl\">٣٥</span> دقیقه عرض شمالی و <span class=\"hlight\" dir=\"rtl\">٤٩</span> درجه و <span class=\"hlight\" dir=\"rtl\">٢٠</span> دقیقه با <span class=\"hlight\" dir=\"rtl\">٥٣</span> درجه و <span class=\"hlight\" dir=\"rtl\">٢٠</span> دقیقه طول شرقی میداند. جغرافی دانان عرب گویند: طبرستان از اراضی کوهستانی تشکیل شده، جبال صعب المروری دارد و بالطبع موضعی بسیار متین و مستحکم می باشد، و از این رو در زمان قدیم تحت اداره ٔ رئیس ممتازی مسمی به سپهبد اداره میشد. در اوائل دوران اسلام هم به باج و خراج جزئی اکتفا کردند و بعدها با صعوبت و تدریج تحت انقیاد درآمدند. این ناحیه منشاء و مسقط رأس جمعی از کبار علما و مشاهیر بوده است . (قاموس الاعلام ترکی ). رجوع به کلمه ٔ مازندران شود. ابن قتیبة در ادب الکاتب گفته است که معنای طبرستان، یعنی گیرنده ٔ طبر. بدین جهت که وجود تبر درمازندران برای قطع خارها و از بیخ برکندن درختان ازرهگذر مردم، و برطرف ساختن این قبیل موانع از ضروریات زندگانی بشمار است و لفظ طبرستان، عربی مازندران است که بین ایرانیان عبارت است از شهرهای معینی از نواحی دارالمرز. کما فی تلخیص آلاثار. و رجوع به فهرست کتب ذیل شود: فارسنامه ٔ ابن البلخی چ اروپا، تاریخ سیستان چ خاور، مجمل التواریخ و القصص چ طهران، تاریخ بیهقی چ غنی و فیاض، محاسن اصفهان چ تهران، التفهیم چ تهران، التاج چ مصر، المعرب جوالیقی چ مصر، عیون الاخبار چ مصر، حبیب السیر چ خیام، ایران در زمان ساسانیان، یشتها، ص <span class=\"hlight\" dir=\"rtl\">٢٩٥</span> لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span>، عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨١</span> و حدائق السحر چ اقبال ص <span class=\"hlight\" dir=\"rtl\">١٤٦</span>، تاریخ الحکماء قفطی چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٨٧</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٧٢</span> و تاریخ یمینی خطی ص <span class=\"hlight\" dir=\"rtl\">٦٧</span>، الارشاد (ترجمه ٔ احوال صاحب عباد) چ تهران ص <span class=\"hlight\" dir=\"rtl\">٥</span>، <span class=\"hlight\" dir=\"rtl\">٢٨</span> و(حاشیه ) ایران باستان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span> و یسنا ص <span class=\"hlight\" dir=\"rtl\">٥١</span> و <span class=\"hlight\" dir=\"rtl\">٥٦</span> وتاریخ ادبیات ادوارد براون ترجمه ٔ رشیدیاسمی چ تهران ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٦</span>، <span class=\"hlight\" dir=\"rtl\">٤٤٢</span> و فرهنگ ایران باستان ص <span class=\"hlight\" dir=\"rtl\">٢٥٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٨٢</span> وشدالازار ص <span class=\"hlight\" dir=\"rtl\">٣٢١</span> و تاریخ اسلام صص <span class=\"hlight\" dir=\"rtl\">١٨٦</span> - <span class=\"hlight\" dir=\"rtl\">١٩٩</span> و فهرست اخبارالدولة السلجوقیه و خاندان نوبختی ص <span class=\"hlight\" dir=\"rtl\">٢٦٥</span> و تجارب الامم و فهرست ص <span class=\"hlight\" dir=\"rtl\">٤</span>، <span class=\"hlight\" dir=\"rtl\">١٧</span>، <span class=\"hlight\" dir=\"rtl\">١٠٢</span>، <span class=\"hlight\" dir=\"rtl\">١٥٣</span>، <span class=\"hlight\" dir=\"rtl\">٤٣٣</span>، <span class=\"hlight\" dir=\"rtl\">٤٣٤</span>، <span class=\"hlight\" dir=\"rtl\">٤٥٩</span>، <span class=\"hlight\" dir=\"rtl\">٥٥٤</span> وتتمه ٔ صوان الحکمة ص <span class=\"hlight\" dir=\"rtl\">٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٢</span>، <span class=\"hlight\" dir=\"rtl\">٨٠</span>، <span class=\"hlight\" dir=\"rtl\">١٧٨</span> و فهرست تاریخ گزیده و فهرست سبک شناسی ج <span class=\"hlight\" dir=\"rtl\">١</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> و الاوراق ص <span class=\"hlight\" dir=\"rtl\">١٠٤</span>و مجمل التواریخ گلستانه و فهرست غزالی نامه ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>، <span class=\"hlight\" dir=\"rtl\">٧٥</span>، <span class=\"hlight\" dir=\"rtl\">١٨١</span> مزدیسنا ص <span class=\"hlight\" dir=\"rtl\">٦</span>، <span class=\"hlight\" dir=\"rtl\">١٩</span>، <span class=\"hlight\" dir=\"rtl\">١٢٤</span> و تاریخ الوزراء و الکتاب ص <span class=\"hlight\" dir=\"rtl\">٩٨</span>، <span class=\"hlight\" dir=\"rtl\">١٨١</span>، <span class=\"hlight\" dir=\"rtl\">٢١٥</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٥</span> و الراضی ص <span class=\"hlight\" dir=\"rtl\">١٠٤</span> و فهرست شرح احوال رودکی و تاریخ بخارا نرشخی ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>، <span class=\"hlight\" dir=\"rtl\">١١٠</span>، <span class=\"hlight\" dir=\"rtl\">١١٢</span> و تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٢٢٤</span> و فهرست تاریخ جهانگشای جوینی چ اروپا ج <span class=\"hlight\" dir=\"rtl\">٢</span> و تاریخ کرد ص <span class=\"hlight\" dir=\"rtl\">٩</span>، <span class=\"hlight\" dir=\"rtl\">١٨٨</span>، <span class=\"hlight\" dir=\"rtl\">١٨٩</span> و نخبةالدهر دمشقی ص <span class=\"hlight\" dir=\"rtl\">٢٦٤</span> و فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٨٤</span> و <span class=\"hlight\" dir=\"rtl\">١٢٠</span> و ترجمه ٔمحاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">٩</span>، <span class=\"hlight\" dir=\"rtl\">٥٣</span>، <span class=\"hlight\" dir=\"rtl\">٥٤</span> شود.<br /></font></div>'),
(175833, 'طبرسران', '<span class=\"hlight\">طبرسران .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ س َ ]</font></b> (اِخ ) نام جائی نزدیک دربند. رجوع به تاریخ ادبیات ایران تألیف ادوارد براون ترجمه ٔ رشیدیاسمی شود.<br /></font></div>'),
(175834, 'طبرسو', '<span class=\"hlight\">طبرسو.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) دهی از دهستان حومه ٔبخش کلاردشت شهرستان نوشهر، واقع در <span class=\"hlight\" dir=\"rtl\">٤</span>هزارگزی جنوب خاوری حسن کیف و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی شوسه ٔ حسن کیف به مرزان آباد.کوهستانی و سردسیری است با <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه . قسمتی از سکنه از ایل خواجوند هستند. آب آن از چشمه . محصول آن غلات و ارزن . شغل اهالی زراعت، گله داری و تهیه ٔ زغال و چوب و صنایع دستی زنان آنجا شال و جاجیم بافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175835, 'طبرسی', '<span class=\"hlight\">طبرسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ]</font></b> (اِخ ) محمدبن فضل . صاحب روضات در ذیل ترجمه ٔ فضل بن حسن طبرسی گوید: در باب محامده از کتاب امل الاَّمل شرح حال مردی، مکنی به ابی علی طبرسی که محمدبن فضل نام دارد دیده میشود که گوید: وی عالمی پرهیزکار و عابد بود. از او ابن شهرآشوب روایت کند. وی از تلامذه ٔ شیخ طوسی است . و دور نیست که او از اجداد طبرسی فضل بن حسن بن فضل صاحب ترجمه باشد. (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٥١٤</span>).<br /></font></div>'),
(175836, 'طبرسی', '<span class=\"hlight\">طبرسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ص نسبی ) در نسبت طبرسی دو قول است : یکی اینکه منسوب به طبرستان به معنی طبرستانی است دیگر آنکه معرب تفرشی و منسوب به تفرش از توابع قم است . این اختلاف گاهی در مطلق لفظ طبرسی و گاهی در طبرسی با قید وصف بودن برای شخص معین پیش می آمده و بدین جهت در بحث از حقیقت امر باید نخست تلفظ صحیح و مفهوم واقعی طبرسی را معلوم داریم و آنگاه به نسبت ابوعلی فضل بن حسن که آیا تفرشی است یا طبرستانی بپردازیم . طبرسی بطور مطلق پیش از بحث از لفظ و معنی این کلمه باید دانست که در عربی در نسبت بمرکب مزجی قاعده ٔ اصلی و کلی این است که جزء دوم کلمه را حذف و یاء نسبت را به آخر جزء اول ملحق میکنند. و فی المثل در نسبت به سیبویه و بعلبک سیبی و بعلی میگویند.ملحق کردن یاء نسبت به تمام کلمه نیز مخصوصاً در موردی که سبب سنگینی لفظ نشود و بالاخص در مرکبات فارسی که عرب بترکیب مزجی آنها توجه ندارد جائز است . چنانکه در نسبت به اردستان و خجستان اردستانی و خجستانی گویند. در بعض مرکبات هم از دو جزء کلمه لفظی چهارحرفی بر وزن جعفر بنا میکنند و آن را منسوب قرار میدهند، مانند حضرمی در نسبت به حضرموت . لکن اینگونه نسبت موقوف بر شنیدن از اهل زبان است و بر آن قیاس نتوان کرد. مطابق قاعده ای که یاد شد در نسبت بطبرستان سه وجه تصور میرود طبری، طبرستانی، طبرسی (بر وزن جعفری ). از این سه وجه اهل زبان وجه اول را اختیار نموده و ائمه ٔ لغت و ادب نیز همان را ضبط کرده اند. از جمله یاقوت در معجم البلدان در ذیل طبرستان گوید: و النسبة الی هذا الموضع طبری . و در ذیل طبریه گوید: و النسبة الیها طبرانی علی غیر قیاس فکانه لما کثر النسبه بالطبری الی طبرستان، ارادوا التفرقه بین النسبتین .و صاحب تاج العروس در ماده ٔ (طبر) گوید: و طبرستان بلاد واسعة منها دهستان و جرجان و استرآباد و آمل : و النسبة الیها طبری ایضاً، پس از تمهید این مقدمه گوئیم : طبرسی بفتح اول و دوم، در نسبت به طبرستان با هیچیک از وجوهی که یاد شد درست نمی آید، و بنابراین مخالف قیاس است و کلمات مخالف قیاس را وقتی حکم به صحت میتوان کرد که اهل زبان آنرا استعمال کرده و ائمه ٔ ادب و لغت بضبط آن پرداخته باشند. و طبرسی با تلفظی که یاد شد در کتب لغت و ادب ثبت نشده، و علمای صرف و نحو با همه دقتی که در جمع و ضبط کلمات سماعی و شوّاذ و نوادر لغت داشته اند متعرض ذکر آن نشده اند، پس طبرسی با وزن و حرکتی که یاد شد یا بکلی مجعول و مجهول است، و یا آنکه لفظی صحیح و مستعمل بوده و تحریف شده است، مجعول بودن آن با وارد شدن در کلمات و مؤلفات دانشمندان بزرگ فرضی معقول نیست . بنابراین، لفظی صحیح و در ابتدای وضع و استعمال موافق قیاس بوده و بعدها به بعض اسباب و علل که در پایان این بحث بدان اشاره خواهد شد تحریف شده، و به صورتی که اکنون معمول است درآمده و اتفاقاً چنان شهرت یافته است که تصور تحریف در آن نمیرود، و نظر بهمین شهرت بوده است که مؤلف روضات آنرا صحیح و قیاسی انگاشته و در اثبات قیاسی بودن آن دچار سه اشتباه شده است که از فاضلی چون او عجیب مینماید: یکی اینکه جزء اول طبرستان را طبرس پنداشته و در ذیل ترجمه ٔ علی بن حمزه ٔ طوسی گفته است : (ص <span class=\"hlight\" dir=\"rtl\">٣٩</span> س <span class=\"hlight\" dir=\"rtl\">٢٨</span> و <span class=\"hlight\" dir=\"rtl\">٢٩</span>) بل یُظن ان الطبرس مطلقا انما هونسبةٌ الی تفرش المشارالیها، لا الی طبرس التی هی مازندران، دیگر اینکه در نسبت به طبرستان، طبری را که موافق قیاس و مشهور است مخالف قیاس شمرده، و طبرسی را که مخالف قیاس و نامستعمل است موافق قیاس دانسته، و در ذیل ترجمه ٔ صاحب احتجاج پس از توجیه نسبت طبرسی و لفظ و معنی طبرستان گفته است : (ص <span class=\"hlight\" dir=\"rtl\">١٨</span> س <span class=\"hlight\" dir=\"rtl\">٢٥</span>) و قد یوجد النسبة الیها طبریا علی غیرالقیاس . (و البته اگرمازندران طبرس باشد، در نسبت به آن طبرسی موافق و طبری مخالف قیاس خواهد بود) دیگر آنکه طبرس را بشهادت این عبارت : لاالی طبرس التی هی مازندران، دانسته است، غافل از اینکه در طبرستان و نظائر آن از مرکبات، مدلول هر یک از دو جزء غیر از مدلول هر دو جزء است : وتاکنون شنیده نشده است که در تفسیر سجستان، فی المثل سج یا سجس را بسیستان معنی کنند، پس طبرس یا طبر بمعنی مازندران نیست، و آنچه افاده ٔ این معنی میکند مجموع طبرستان است . بالجمله در ابطال قول کسانی که طبرسی را منسوب به طبرستان میدانند، محکمترین ادله مخالف قیاس و نامستعمل بودن این کلمه است و در تأیید این دلیل (با اینکه محتاج تأیید نیست ) قرائن متعدد که هر یک در واقع دلیلی جداگانه است در دست داریم . ازجمله اینکه در کتب تاریخ و رجال که تا دو قرن پیش تألیف شده است، در نسبت به طبرستان همه جا، بجز در مورد عده ای محدود لفظ طبری به کار رفته و عده ای محدودهم اغلب بنسبت طبرسی و طبری هر دو یاد شده اند، مانند عمادالدین حسن بن علی بن محمد که او را هم عماد طبری و هم عماد طبرسی خوانده اند، و فقط معدودی که شماره ٔآنها بتصریح مؤلف روضات الجنات از سه تن تجاوز نمیکند، به لقب طبرسی تنها اختصاص و اشتهار یافته اند، و این خود قرینه و دلیل آن است که طبرسی غیر از طبری ومنسوب به محلی غیر از طبرستان است، و در تأیید این معنی کافی است که نسبت دو تن از آن سه تن را (ابوعلی طبرسی و پسرش ) صاحب تاریخ بیهق که معاصر و معاشر آنها بوده تعیین کرده، و بصراحت گفته است که ایشان ازبقعه ای موسوم به طبرس بوده اند. دیگر اینکه اهل زبان در نسبت به امکنه هنگامی لفظ مخالف قیاس استعمال میکنند که استعمال لفظ قیاسی سبب اشتباه و التباس باشد، چنانکه در نسبت به طبریه ٔ شام طبرانی گفتند، تا بطبری منسوب به طبرستان مشتبه نگردد. و بدیهی است که در نسبت به طبرستان چنین محذوری پیش نیامده . و فی المثل اگر فضل بن الحسن را ابوعلی طبری میخواندند، جز معنی طبرستانی از آن مفهوم نمیشد. بالجمله بحکم ادله وقرائتی که یاد شد، طبرسی بفتح اول و ثانی، و برای نسبت به طبرستان وضع نشده و اصل آن در وضع بفتح اول وثالث و سکون ثانی، و برای نسبت به طبرس بر وزن تغلب بوده، و طبرس چنانکه خواهد آمد بمعنی تفرش است . و اما طبرس که مؤلف تاریخ بیهق اصل ابوعلی را از آنجا دانسته همان محلی است که در تاریخ قُم به نام طبرش ضبط شده، و طبرش بطور قطع معرب تفرش یا تپرش یا تبرش است . و تبدیل شین آن به سین برای کامل ساختن تعریب بوده و بر قیاس پشت و بُست و تشت و طست است . مؤلف تاریخ قم در وجه تسمیه ٔ طبرش، به روایت از ابن مقفع گوید (ص <span class=\"hlight\" dir=\"rtl\">٧٨</span> و <span class=\"hlight\" dir=\"rtl\">٧٩</span>): ضیعتهای آن را طبرش بن همدان بنا کرده است و بعمارت آن فرموده، و در الحاق آن به قم در جای دیگر گوید (ص <span class=\"hlight\" dir=\"rtl\">٥٩</span> س <span class=\"hlight\" dir=\"rtl\">٣</span>): رستاق طبرش داخل و خارج رااز حیث همدان با قم اضافه کرده اند. طبرش در تاریخ قم به اشکال مختلف، از قبیل رستاق طبرش داخل و خارج، رستاق طبرش همدان و اصفهان، رستاق طبرش همدانی و اصفهانی و در یک موضع نیز بعنوان طسوج طبرش نام برده شده، و از مجموع این اشکال و عناوین چنین مفهوم میشود که طبرش در زمان تألیف تاریخ قم، ناحیه ای وسیع و مشتمل بر قسمتهای مختلف و امتداد آن از حدود اصفهان و کاشان تا حدود قم و همدان بوده است . و عبارت مؤلف نیز که «طبرش منزلی میان کاشان و اصفهان است » این معنی را تأیید، و دوام اهمیت و وسعت عرصه ٔ طبرس را تا زمان او مدلل میکند. (تعلیقات احمد بهمنیار بر تاریخ بیهق صص <span class=\"hlight\" dir=\"rtl\">٣٤٨</span> - <span class=\"hlight\" dir=\"rtl\">٣٥٢</span>). <BR><font color=\"Blue\">◄</font> حدس دیگری که در این باب زده میشود آن است که طبرسی مخفف طبرستانی (طبری ) ساروی است . در صورت صحت این حدس، این کلمه بهمان شکل مشهور یعنی بفتح طاء و باء و سکون راء صحیح است و نسبت آن به طبرستان و ساری و یا ساریه است، بجای طبری ساروی مانند طبرخزی که نسبت آن به طبرستان و خوارزم است، چه دو تن که به نسبت طبرسی مشهورند از مردم ساری طبرستان بوده اند: یکی احمدبن علی بن ابیطالب طبرسی یا شیخ طبرسی، دیگری شاگرد او رشیدالدین شمس الاسلام ابوعبداﷲ محمدبن علی بن شهرآشوب ابی نصر طبرسی که هر دو اهل طبرستان و از اهل ساری میباشند. و اگر طبرسی هم باشد بفتح طاء و سکون باء و کسر راء معرب تفرش، آن موضوع دیگر است و مربوط به اشخاص سابق الذکر نیست . و اگر تحقیقی در شرح حال ابوعلی طبرسی و اولاد او شود، شاید مطلب روشنتر شود. رجوع به ماده ٔ بعد شود.<br /></font></div>'),
(175837, 'طبرسی', '<span class=\"hlight\">طبرسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) مؤلف روضات الجنات آرد (ص <span class=\"hlight\" dir=\"rtl\">١٨</span>): ابومنصور احمدبن علی بن ابی طالب الطبرسی، از مردم طبرستان بفتح طا و با و راء و اسکان سین، چنانکه حازمی بر آن رفته و عامه نیز همین عقیده را دارند، یا فتح دو حرف نخستین با سکون سین صاحب ترجمه اهل ساری که یکی از شهرستانهای مشهور مازندران است بوده، چنانکه شاگرد مشهور او: محمدبن علی بن شهرآشوب السروی المازندرانی رحمةاﷲ نیز منسوب به ساری میباشد. و گاه بر غیر قیاس منسوب به طبرستان را طبری گویند، مانند شیخ ابوعلی طبری، و قاضی ابوالطیب طبری، و نسبت طبری به طبرستان، مانند طبرانی است نسبت به طبریه ٔ اردن از بلاد شام و چنانکه در نسبت بطبرستان گویند فلان الطبری، و الدارهم الطبریة، همچنان گویند:فلان الطبرانی (در نسبت بسوی طبریةاردن از بلاد شام ) و طبرانی مؤلف معجم کبیر نیز از طبریه ٔ شام میباشد، گاهی هم طبریه را در مورد نسبت به قریه ای که نزدیک شهر واسط واقع است استعمال کنند، و در کتاب ریاض از شیخ و استاد خود علامه ٔ مجلسی رحمةاﷲ نقل کرده که او در کتابی چنین دیده که طبرسی معرب تفریشی، نسبت به تفریش یکی از آبادیهای توابع قم است، چنانکه دوریستی معرب درشت، یکی از آبادیهای توابع تهران میباشد. صاحب ریاض بر این سند افزوده است که بعضی از معاصرین نیز با قول آخرین موافقت کرده اند، و هو غریب ٌ. و سوف یأتی فی ترجمة حمزةالدیلمی . و بالجمله این مرد از بزرگان متقدمان اصحاب ما میباشد و از جمله کسانی که ازاو روایت دارند، شاگرد سابق الذکر اوست که در کتاب معالم العلماء نام شریف او را ذکر کرده و گفته است که شیخی احمدبن ابیطالب الطبرسی . او راست : کتاب الکافی فی الفقه، حَسن ٌ، الاحتجاج و مفاخرالطالبیة، تاریخ الائمة و فضائل الزهراء - انتهی . (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">١٨</span>). صاحب معجم المطبوعات عنوان وی را بدین نحو آورده است : ابومنصور احمدبن علی بن ابیطالب الطبرسی . (الشیخ ...) و یعرف بالشیخ الطبرسی الاول . صاحب روضات الجنات در جلداول نام او را ذکر کرده، گوید: عالم و فاضل و محدّث ثقة است . وی راست : کتاب الاحتجاج علی اهل اللجاج، کتابی است نیکو و بسیار سودمند، و سال وفات او را ذکر نکرده است . کتاب مذکور در مذهب طایفه ٔ شیعه و انتصاربر اهل بیت رسول خدا صلوات اﷲ و سلامه علیهم تألیف شده . صاحب روضات گوید: آن کتابی است معتبر و بین طایفه ٔ شیعه شهرتی بسزا دارد و مشتمل است بر آنچه از دلائل نبوت و امامت، بلکه بسیاری از دلایل اصحاب بزرگوار پیغمبر با گروهی از اشقیاء و مخالفین را نیز که به دست آورده و بر آن آگاهی یافته است بر آن افزوده، و در اواخر کتاب نیز تدقیقات بسیاری که از ناحیه ٔ مقدسه به بعضی از بزرگان شیعه صادر شده درج کرده است . کتاب مزبور در سالهای <span class=\"hlight\" dir=\"rtl\">١٢٦٨</span> و <span class=\"hlight\" dir=\"rtl\">١٣٠٢</span> در تهران طبع شده . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٨</span>). و صاحب ریحانة الادب آرد: شیخ احمدبن علی بن ابیطالب، مکنی به ابی منصور. عالم فاضل جلیل فقیه متکلم کامل نسابه و از اهالی ساری مازندران و از ثقات محدثین و اکابر علمای امامیه ٔ اواسط قرن ششم هجری و با ابوالفتوح رازی و فضل بن حسن طبرسی متوفی <span class=\"hlight\" dir=\"rtl\">٥٤٨</span> هَ . ق . معاصر و از اساتید و مشایخ روایت شیخ منتخب الدین متوفی در <span class=\"hlight\" dir=\"rtl\">٥٨٥</span> هَ . ق . و ابن شهرآشوب متوفی <span class=\"hlight\" dir=\"rtl\">٥٨٨</span> هَ . ق . بود. خودش با دو واسطه از شیخ طوسی و با چند واسطه ٔ دیگر از صدوق روایت می نماید و شهید اول در غایةالمراد فتاوی و اقوال او را بسیارنقل میکند و از آثار جلیله ٔ اوست : <span class=\"hlight\" dir=\"rtl\">١</span> - الاحتجاح علی اهل اللجاج . <span class=\"hlight\" dir=\"rtl\">٢</span> - تاج الموالید در انساب، چنانچه بعضی گفته لکن رجوع به شرح حال فضل بن حسن طبرسی کنند. <span class=\"hlight\" dir=\"rtl\">٣</span> -تاریخ الائمه (ع ). <span class=\"hlight\" dir=\"rtl\">٤</span> - فضائل الزهراء. <span class=\"hlight\" dir=\"rtl\">٥</span> - الکافی در فقه . <span class=\"hlight\" dir=\"rtl\">٦</span> - مفاخر الطالبیه . و اشهر از همه کتاب اجتماع مذکور اوست که در السنه دائر و به اجتماع طبرسی معروف و به کثرت فوائد موصوف و بارها به طبع رسیده ... وکسانی که تألیف این کتاب احتجاج را به فضل بن حسن طبرسی نسبت داده اند، بخطا رفته اند. (ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٨</span>). ابن شهرآشوب او را در معالم العلما به این نسبت (طبرسی ) خوانده و گوید: «شیخی احمدبن ابیطالب الطبرسی له الکافی فی الفقه ». رجوع به همین لغت نامه ذیل احمد، روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">١٨</span> و سبک شناسی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> شود.<br /></font></div>'),
(175838, 'طبرسی', '<span class=\"hlight\">طبرسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) حسن بن فضل طبرسی . ملقب به رضی الدین، مکنی به ابونصر. او راست : کتاب مکارم الاخلاق که در سال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> هَ. ق . در بولاق مصر با کتاب الوسیلة العظمی فی شمائل المصطفی خیرالوری تألیف ابی المکارم زین الدین پیرمحمد دده، در حاشیه اش بطبع رسیده، و نیز در سال <span class=\"hlight\" dir=\"rtl\">١٣٠٤</span> درمطبعه ٔ محمد مصطفی، و در سال <span class=\"hlight\" dir=\"rtl\">١٣١١</span> هَ . ق . در مطبعه عثمانیه و هم در آن سال در مطبعه ٔ میمنیّه، و همچنین در سال <span class=\"hlight\" dir=\"rtl\">١٣١٨</span> هَ . ق . با کتاب تهذیب الاخلاق و تطهیرالاعراق ابن مسکویه در حاشیه اش چاپ شده است، در مطبعه ٔخیریه نیز در سال <span class=\"hlight\" dir=\"rtl\">١٣٠٣</span> هَ . ق . بطبع رسیده است . (معجم المطبوعات ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٨</span>). کتاب مکارم الاخلاق، در سال <span class=\"hlight\" dir=\"rtl\">١٣١٤</span> هم در تهران چاپ سنگی شده و کتب ذیل هم در حاشیه ٔ آن با کمال نفاست چاپ شده است : <span class=\"hlight\" dir=\"rtl\">١</span> - طهارةالاعراق . <span class=\"hlight\" dir=\"rtl\">٢</span>- ترتیب السعادات . هر دو از تألیفات ابوعلی مسکویه . <span class=\"hlight\" dir=\"rtl\">٣</span> - کتاب التحصین و صفات العارفین . <span class=\"hlight\" dir=\"rtl\">٤</span> - کتاب الفصول فی دعوات اعقاب الفرائض . هر دو تألیف احمدبن محمدبن فهد الحلی . رجوع به روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٥١٢</span> و صص <span class=\"hlight\" dir=\"rtl\">١٨٤</span> - <span class=\"hlight\" dir=\"rtl\">١٨٥</span> شود. و صاحب ریحانة الادب آرد: حسن بن علی بن محمدبن علی بن حسن طبرسی یا طبری مازندرانی . مشهور به عمادالدین طبرسی یا طبری . از فحول و اکابر علمای امامیه و فقیهی است . بصیر و محدثی خبیر و متکلمی نحریر و از معاصرین محقق حلی و خواجه نصیر طوسی و نظائر ایشان بوده و مصنفات جیده ٔ بسیاری در فقه، حدیث و تحقیق حقایق اصول مذهب و تشیید مبانی دین مقدس اسلامی و دیگر فنون متنوعه داشته و فتاوی او در کتب فقهیه متأخرین منقول و از او به عماد طبرسی یا طبری و گاهی بعمادالدین طبرسی یا طبری تعبیر کنند... سال وفاتش به دست نیامده، ولی از تاریخ تألیف اسرارالامامة «که در سال <span class=\"hlight\" dir=\"rtl\">٦٩٨</span> هَ . ق . تألیف شده » معلوم است تا این سال حیات داشته است و نیز گفته اند این کتاب غیر از اسرارالامامة فضل بن حسن طبرسی است، او از طبرستان مازندران است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>، <span class=\"hlight\" dir=\"rtl\">١٢٨</span>). صاحب الذریعه در نسبت «اسرارالامامه » (ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠</span>) نویسد: الشیخ المتکلم الفقیه عمادالدین الحسن بن علی بن محمدبن الحسن الطبرسی المعروف بالعماد الطبری او عمادالدین الطبری عند نقل اقواله فی الفقه و هو صاحب کامل البهائی الذی الفه سنة <span class=\"hlight\" dir=\"rtl\">٦٧٥</span> <font color=\"DarkGreen\"><b>[ هَ . ق . ]</font></b> و صرح فیه بانه مازندرانی (انتهی موضع الحاجة منه ). خود وی در مقدمه ٔ کتاب کامل بهائی نویسد: «در ملک مازندران که مولد مصنف این کتاب است » ولی از شهری که در آن تولد یافته نام نمیبرد.<br /></font></div>'),
(175839, 'طبرسی', '<span class=\"hlight\">طبرسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) حسین بن محمدتقی نوری طبرسی . او راست : فصل الخطاب فی اثبات تحریف کتاب رب الارباب آغاز کتاب الحمدللّه الذی انزل علی عبده کتاباً ثنئاًلما فی الصدور. در دیباچه ٔ کتاب گوید: این کتابی است لطیف که در اثبات تحریف قرآن، و فضایح اهل جور و عدوان فراهم آورده ام، و آنرا فصل الخطاب فی اثبات تحریف کتاب رب الارباب نام نهادم، و بر سه مقدمه و دو باب قرار دادم . این کتاب در سال <span class=\"hlight\" dir=\"rtl\">١٢٩٨</span> هَ . ق . در ایران بطبع رسیده است . او راست . کتاب دیگری به نام کشف الاستار عن الابصار (المهدی المنتظر). این کتاب را بر یک مقدمه و دو فصل و خاتمه مرتب ساخته است، و در ایران بچاپ سنگی طبع شده است . (معجم المطبوعات ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٨</span>).<br /></font></div>'),
(175840, 'طبرسی', '<span class=\"hlight\">طبرسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) (شیخ ...) شمس الدین طبرسی نحوی . در روضات گوید: کفعمی در بلدالامین از او نقل کند و گمان دارم کتاب جواهر در نحو که بفضل بن حسن طبرسی نسبت کنند ازاو باشد. (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٥١٣</span>) و در کتاب النقض آمده است : و بعد از آن خواجه مکین بوالمفخر قمی ... و شمس الدین محمد بنیامان طبرسی ...؛ این جماعت همه شیعی و معتقد و اصولی بوده اند. (کتاب النقض صص <span class=\"hlight\" dir=\"rtl\">٢٢٤</span> - <span class=\"hlight\" dir=\"rtl\">٢٢٥</span>).<br /></font></div>'),
(175841, 'طبرسی', '<span class=\"hlight\">طبرسی .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (اِخ ) فضل بن حسن طبرسی، مکنی به ابوعلی . طبرس منزلی است میان قاشان و اصفهان و اصل ایشان از آن بقعت بوده است . و ایشان در مشهد سناباد طوس متوطن بوده اندو مرقد او آنجاست، بقرب مسجد قتلگاه، و از اقارب نقبای آل زیاره بودند، رحمهم اﷲ. این امام در نحو فرید عصر بود و با تاج القراء کرمانی اختلاف داشته و در علوم دیگر به درجه ٔ افادت رسیده، و با قصبه انتقال کرد، در سنه ٔ ثلاث و عشرین و خمسمائة، اینجا متوطن گشت، و مدرسه ٔ دروازه ٔ عراق برسم او بود، و او را اشعار بسیار است که در عهد صبی انشا کرده است . در کتاب وشاح بعضی از آن بیاورده ام . و از آن جمله این ابیات است :<br />الهی بحق المصطفی و وصیه <br />وسبطیه و السجاد ذی الثفنات <br />و باقر علم الانبیاء و جعفر<br />و موسی نجی ّاﷲ فی الخلوات <br />و بالطهر مولانا الرضا و محمد<br />تلاه علی ّ خیرةالخیرات <br />و بالحسن الهادی و بالقائم الذی <br />یقوم علی اسم اﷲ بالبرکات <br />اَنِلنی الهی ما رجوت بحبهم <br />و بدل خطئیاتی بهم حسنات <br />وتصانیف بسیار است او را. و غالب بر تصانیف او اختیارات است و اختیار از کتب رتبه ای بلند دارد. فان ّ اختیارالرجل یدل ّ علی عقله . مثلاً از کتاب مقتصد در نحو اختیاری نیکو کرده است بغایت کمال . و از شرح حماسه ٔ مرزوقی اختیاری کرده است بغایت نیکو. و از تفسیر امام زمخشری اختیاری کرده است فی غایةالجودة. و او را تفسیری است مصنف ده مجلد و کتب دیگر، بسیار. وی در علوم حساب و جبر و مقابله مشارالیه بود. توفی بقصبةالسبزوار، لیلةالاضحی العاشر من ذی الحجة سنة ثمان و اربعین و خمسمائة. و تابوت او را بمشهد رضوی علی ساکنه التحیة و السلام نقل کردند. (تاریخ بیهق چ تهران ص <span class=\"hlight\" dir=\"rtl\">٢٤٧</span>). در معجم المطبوعات آمده : ابوعلی فضل بن حسن بن فضل طبرسی مشهدی (شیخ ...) معروف به طبرسی بزرگ، صاحب تفسیر. مؤلف ریاض العلماء گوید: او قدس سره، و فرزندش رضی الدین ابونصر حسن بن فضل صاحب مکارم الاخلاق، و نواده ٔ او ابوالفضل علی بن حسن صاحب شکوه الانوار از اکابر علما بوده اند. ابن بابویه در فهرست خود گفته که او را دیده و نزد او دانش فراگرفته، در مشهد مقدس رضوی وفات یافته است . امیر مصطفی در رجال خود ترجمه ٔ احوالش را آورده و گوید: ثقة فاضل دین، عین ٌ من اجلاء هذه الطائفة له تصانیف حسنةٌ، انتقل من المشهد الرضوی الی سبزوار، سنة <span class=\"hlight\" dir=\"rtl\">٥٢٠</span> <font color=\"DarkGreen\"><b>[ هَ . ق . ]</font></b> و انتقل بها الی دارالخلود سنة <span class=\"hlight\" dir=\"rtl\">٥٤٨</span>. و صاحب معجم المطبوعات گوید: او راست جوامعالجامع در تفسیر، و این کتاب مختصری است از دوتألیف دیگر او، مجمعالبیان، و الکافی الشافی که هردو در تفسیر است و این مختصر در ایران بسال <span class=\"hlight\" dir=\"rtl\">١٣٢١</span> بطبع رسیده است . دیگر از تألیفات وی تفسیر مجمعالبیان است . آغاز آن : الحمدللّه الذی ارتفعت من مطارح الفکر جلاله . تألیف این تفسیر در سال <span class=\"hlight\" dir=\"rtl\">٥٣٤</span> هَ . ق . پایان یافته است . این تفسیر در دو جلد در ایران بطبع رسیده . (معجم المطبوعات ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٧</span>). رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٢٢</span> و <span class=\"hlight\" dir=\"rtl\">٤٤٥</span> شود. تفسیر مجمعالبیان اخیراً در شهر صیدا بطبع رسیده است . در روضات ص <span class=\"hlight\" dir=\"rtl\">٥١٢</span> لقب وی امین الاسلام و در ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٨</span> امین الدین یا امین الاسلام آمده است . صاحب روضات الجنات ولادت او را در عشر <span class=\"hlight\" dir=\"rtl\">٤٧٠</span> هَ . ق . نوشته و وفات وی را بسال <span class=\"hlight\" dir=\"rtl\">٥٤٨</span> هَ . ق . یادکرده است . رجوع به روضات صص <span class=\"hlight\" dir=\"rtl\">٥١٢</span> - <span class=\"hlight\" dir=\"rtl\">٥١٤</span> و ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">١٩</span> - <span class=\"hlight\" dir=\"rtl\">٢١</span> شود. در تاریخ بیهق در ترجمه ٔ وی گوید (ص <span class=\"hlight\" dir=\"rtl\">٢٤٢</span>): طبرس منزلی است میان قاشان و اصفهان و اصل ایشان از آن بقعت بوده <font color=\"DarkGreen\"><b>[ است ]</font></b>.<br /></font></div>'),
(175842, 'طبرسی', '<span class=\"hlight\">طبرسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) هارون بن حسن بن علی بن محمدبن علی، مکنی به ابوعلی یا ابومحمد و ملقب به ضیاءالدین . منسوب به طبرستان و از این رو گاهی به طبری و گاهی به طبرسی خوانده میشود. سال وفات او به دست نیامده، لکن صاحب ریاض العلماء میرزا عبداﷲ افندی نسخه ای خطی از قواعد علامه در دهخوارقان به دست آورده که بخط هارون بوده و تمام آنرا نزد علامه خوانده و علامه با خط خود در پشت کتاب در تاریخ <span class=\"hlight\" dir=\"rtl\">١٧</span> رجب <span class=\"hlight\" dir=\"rtl\">٧٠١</span> هَ . ق . او را با القاب امام عالم فاضل ستوده است . و پدر او عمادالدین حسن بن علی طبرسی را نیز بسیار ستوده است . (تلخیص از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦</span>).<br /></font></div>'),
(175843, 'طبرش', '<span class=\"hlight\">طبرش .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ رِ ]</font></b> (اِخ ) معرب تفرش . ولایتی است که از هر طرف که بدو روند به گریوه فرو باید رفت، سیزده پاره ده است، خم «ظ: فم یا فیم »و طرخوران از معظمات اوست، هوایش معتدل است، آبش ازچشمه ها و کاریز که از آن کوهها برمیخیزد و ارتفاعاتش پنبه و غله و میوه بود، اکثر اوقات آنجا ارزانی بود، و مردم آنجا شیعی اثناعشری اند. حقوق دیوانیش شش هزار دینار است . (نزهةالقلوب چ لندن ص <span class=\"hlight\" dir=\"rtl\">٦٨</span>). تفرش در فرورفتگی واقع شده و کوههائی آنرا احاطه کرده است، و اغلب اهالی تفرش باسواد، و در دوره های اخیر غالباً مصدر مشاغل مهم دولتی و مملکتی بوده اند. (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٣٨٨</span>). رستاق طبرش ؛ روایتی است از ابن المقفع که ضیعتهای آنرا طبرش بن همدان بنا کرده است و بعمارت آن فرموده . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٧٨</span>). رستاق طبرش ؛ سی ودو دیه، از آن جمله طرخران، فیم، جادیده، که مندرس گشته و ناپدید شده است . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>). رجوع به همان کتاب ص <span class=\"hlight\" dir=\"rtl\">١١٧</span> شود. و عوانان بددین از قم و کاشان و آبه و طبرش و ری <span class=\"hlight\">:</span> <br />خسروا هست جای باطنیان <br />قم و کاشان و آبه و طبرش <br />آبروی چهار یار بدار<br />واندرین چار جای زن آتش <br />پس فراهان بسوز و مصلح گاه <br />تا چهارت ثواب گردد شش .<br /><font color=\"Red\">شمس الدین لاغری (از راحةالصدور).</font><br /></font></div>'),
(175844, 'طبرشانه', '<span class=\"hlight\">طبرشانه .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ن َ ]</font></b> (اِخ ) یکی از شهرهای اندلس که بندر است . (الحلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>).<br /></font></div>'),
(175845, 'طبرشی', '<span class=\"hlight\">طبرشی .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (اِخ ) شرف الدین علی طبرشی وزیر عراق . (جهانگشای جوینی ). و نیز در حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">١٣٠</span> از تاریخ نسوی (سیرة جلال الدین منکبرنی ) این عبارت را نقل کرده است : «شرف الدین علی التفرشی وزیر السلطان بالعراق کان ... من رؤساء تفرش و هی کورة من کورالعراق . (تاریخ جهانگشای جوینی چ لیدن ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩١</span>).<br /></font></div>'),
(175846, 'طبرمین', '<span class=\"hlight\">طبرمین .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) قلعه ای است استوار در صقلیه .(معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢</span>) (قاموس الاعلام ). دمشقی در فصل وصف جزائر بحر رومی گوید: و من بلادالجزیرة البریة: الشاقة و... و طبرمین ... (نخبةالدهر ص <span class=\"hlight\" dir=\"rtl\">١٤١</span>).<br /></font></div>'),
(175847, 'طبرنش', '<span class=\"hlight\">طبرنش .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ن َ ]</font></b> (اِخ ) (وادی ...) نام صحرائی است در اندلس . (الحلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175848, 'طبرنه', '<span class=\"hlight\">طبرنه .</span> <font color=\"DarkGreen\"><b>[طَ ب َ ن َ ]</font></b> (معرب، اِ) معرب از اسپانیولی، میخانه . میکده . کاباره . ج، طبرنات، طبارن . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span>).<br /></font></div>'),
(175849, 'طبرنیره', '<span class=\"hlight\">طبرنیره .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ن َ رُ<span class=\"hlight\" dir=\"rtl\">/</span> رَ ]</font></b> (معرب، اِ) (معرب از اسپانیولی ) صاحب میخانه . می فروش . پیر میکده . پیر خرابات . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span>).<br /></font></div>'),
(175850, 'طبره', '<span class=\"hlight\">طبره .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ رَ ]</font></b> (اِخ ) دهی است از دهستان جراحی بخش شادگان شهرستان خرمشهر، واقع در <span class=\"hlight\" dir=\"rtl\">٧٨</span> هزارگزی شمال خاوری شادگان، کنار راه اتومبیل رو تابستانی خلف آباد به بهبهان . دشت، گرمسیر، مالاریائی با <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه . آب آن از چاه . محصول آنجا غلات . شغل اهالی زراعت . راه آن در تابستان اتومبیل رو است . ساکنین از طایفه ٔ آلبوغش هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(175851, 'طبره', '<span class=\"hlight\">طبره .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ رَ ]</font></b> (اِخ ) از طسوج جبل است . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١١٨</span>).<br /></font></div>'),
(175852, 'طبرک', '<span class=\"hlight\">طبرک .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ رَ ]</font></b> (اِخ ) قلعه ای است به ری . (منتهی الارب ). دزی است بر فراز کوهی خرد نزدیک شهر ری بر جانب راست رونده بخراسان که از جانب چپ وی کوه بزرگ ری واقع است . این دز بخرابه ٔ ری پیوسته است که آن را سلطان طغرل بن ارسلان بن طغرل بن محمدبن ملکشاه بن ارسلان بن داودبن سلجوق بسال <span class=\"hlight\" dir=\"rtl\">٥٨٨</span> هَ . ق . خراب کرد. سبب خراب کردن این شهر آن بود که خوارزمشاه تکش بن ایل ارسلان چون به عراق آمدو بر ری استیلا یافت، این دز را نیز متصرف گردید؛ هنگام بازگشت بخوارزم طمغاج نامی را که یکی از امراء بود با دوهزار تن سوار خوارزمی بجای خود در آن دز برقرار و آن دز را بوسیله ٔ اموال و ذخائر نیک استوار ساخت، و دقیقه ای از بذل مجهود در این منظور فرونگذاشت . اتفاقاً در همان سال (<span class=\"hlight\" dir=\"rtl\">٥٨٨</span> هَ . ق .) طغرل که از عهد قزل ارسلان در یکی از قلاع محبوس بود آزاد شد و لشکری گرد آورد و آهنگ ری کرد، قتلغ اینانج ابن البهلوان از بیم طغرل فرار کرد از خوارزمشاه یاری و مدد طلبید، طغرل به ری آمد و آنجا را متصرف شده و بمحاصره ٔ طبرک پرداخت در آن اثناء امیر طمغاج بمرد، و خوارزمیان دل شکسته شدند، از طغرل استدعا کردند که اجازت دهد اموال خویش را از دز با خود بیرون برند و دز را تسلیم کنند. طغرل گفت : برای بیرون بردن اموال شخصی شما مانعی نخواهد بود، اما به احدی اجازت ندهم که دست به ذخائرو سلاح برد و آنها را از دز بیرون سازد، خوارزمیان پذیرفتند و با این شرط از دز بیرون آمدند. طغرل را غلامی بود که فراری و پنهان و بخوارزمیان پناهنده شده بود، و هنگام خروج خوارزمیان از دز، وی نیز خواست به معیت آنان بیرون شود، یاران طغرل غلام را بگرفتند، گفتند: این مملوک ماست، خوارزمیان از تسلیم او سر پیچیدند و در نتیجه خوارزمیان با اصحاب طغرل بیکدیگر افتادند، عاقبت یاران طغرل و اهل ری با هم اتفاق کرده بر خوارزمیان چیره شدند و بسیاری از آنان را کشتند و بر اثر این جنگ و جدال طغرل دز طبرک را متصرف گردید.طغرل پس از این فتح و پیروزی، امراء سپاه خود را احضار کرد و از آنان پرسید این دز را به چه آفریده ای مانند خواهید کرد؟ و هر یک از آنها برای خویش چیزی گفت، طغرل گفتار هیچیک را مقرون به صواب ندانست و گفت :این دز ماری دوسر را ماند که یک سر او در عراق و سردیگرش به خراسان باشد، به هر طرف دهان باز کند اهل آنجا را خواهد بلعید و مرا تصیمم بر آن است که این دز را ویران کنم، امرای طغرل وی را از این تصمیم بازداشتند و گفتند: نیکوتر آن است که شخصاً بدین دز بالا رود و آنجا را نیک بازبیند، پس از معاینه ٔ آن جا به هرچه رای خدایگان تعلق گرفت به اجرای آن فرمان دهد. طغرل گفت : تنی چند از پادشاهان نیز بخراب کردن این قلعه تصمیم گرفتند، اما پس از آنکه دز را بازدید کردند، از خرابی آنجا دل خوش نداشتند و از تصمیم خود بازگردیدند؛ از این رو من بمشاهده ٔ دز نشوم و از عزم خود بازنگردم . آنگاه فرمان داد هرچه سلاح و آلات جنگ در آن جا بود بجای دیگر نقل کنند، پس از نقل سلاح از آن جا به اهالی ری امر کرد تا آن جا را غارت کردند، و آنچه در دز به ذخیره نهاده شده بود به تاراج بردند، وروزی چند اهالی ری مشغول تاراج بودند و چون از تاراج آن جا فارغ شدند، طغرل بدانها گفت : ایدون که از تاراج دز بیاسودید، باید آن را ویران سازید، آنان نیز فرمان بردند، و بامیتین چندان بن و پیهای آن را کاویدند تا آن جا را با خاک یکسان کردند و تا مدت یک سال هر زمان که طغرل از آنجا میگذشت، اگر کمترین اثر و نشانه ای از آن دز می یافت می گفت این را نیز نابود کنید و چندان در این امر جهد ورزید که بعد از آن کوچکترین نشانه ای هم از آن دز بر جای نماند. (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢</span>). خواندمیر در حبیب السیر آورده : منوچهر به دارالملک ری رفت و افراسیاب تهران ری را معسکر خود ساخته، روز به روز آثار نصرت در جانب او ظاهرتر میگشت . بنابراین منوچهر قلعه ٔ طبرک را عمارت فرمودو آن اول قلعه ای است که در عالم بنا یافت، و معنی طبرکوه است . (حبیب السیر چ <span class=\"hlight\" dir=\"rtl\">١</span> تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>). قلعه ٔ طبرک به جانب شمال ری در پای کوه افتاده است . (نزهةالقلوب چ لندن ص <span class=\"hlight\" dir=\"rtl\">٥٣</span>). معدن نقره ٔ طبرک ری هرچند در آنجا خرج کنند، همان قدر باز پس ندهد، بدین سبب اکثر اوقات معطل است، اما در عهد سلاجقه پیوسته در آن جا بکار بودندی، گفتندی اگرچه توفیر ظاهری ندارد، اما نقره در جهان خراج بسیار می شود و این توفیری نیکو باشد. (نزهةالقلوب چ لندن ص <span class=\"hlight\" dir=\"rtl\">٢٠٢</span>). و رجوع به نزهةالقلوب چ لندن ص <span class=\"hlight\" dir=\"rtl\">١٩٨</span>، فهرست حبیب السیر چ خیام، مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٦٤</span>، قاموس الاعلام ترکی، فهرست تاریخ گزیده، رشیدی ص <span class=\"hlight\" dir=\"rtl\">١٤٣</span> و تاریخ جهانگشای جوینی ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٢٨</span> - <span class=\"hlight\" dir=\"rtl\">٣٠</span>، شدالازار ص <span class=\"hlight\" dir=\"rtl\">٣٦٢</span> و اخبارالدولة السلجوقیه ص <span class=\"hlight\" dir=\"rtl\">١٩</span> شود.<br /></font></div>'),
(175853, 'طبرک', '<span class=\"hlight\">طبرک .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) قلعه ای است به اصبهان . (منتهی الارب ). رجوع به ذیل جامعالتواریخ رشیدی ص <span class=\"hlight\" dir=\"rtl\">٤٣</span> و فهرست حبیب السیر چ خیام شود.<br /></font></div>'),
(175854, 'طبرک', '<span class=\"hlight\">طبرک .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ رَ ]</font></b> (اِخ ) (کوه ...) در کتاب النقض در این باره آمده است :دانم که کوه طبرک آن جا نبود. (کتاب النقض ص <span class=\"hlight\" dir=\"rtl\">٥٣٣</span>).<br /></font></div>'),
(175855, 'طبرک', '<span class=\"hlight\">طبرک .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ رَ ]</font></b> (اِخ ) دهی است از دهستان بازفت بخش اردل شهرستان شهرکرد، در <span class=\"hlight\" dir=\"rtl\">٧٠</span>هزارگزی شمال اردل و متصل به راه مالرو عمومی . کوهستانی، معتدل با جنگل بلوط. <span class=\"hlight\" dir=\"rtl\">١٧٨</span> تن سکنه دارد. آب آن از چشمه و آب بازفت . محصول آنجا غلات، پشم و روغن . شغل اهالی زراعت و گله داری و صنایع دستی زنان آنجا جاجیم بافی است . راه مالرو دارد. قشلاق سکنه ٔ عشایر اطراف مسجدسلیمان است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(175856, 'طبرکون', '<span class=\"hlight\">طبرکون .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (معرب، ص ) (معرب تبرکون ) آنکه کفل زاویه نما (نوک تیز) و طویل دارد، چنانکه اسب . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span>). رجوع به تبرکون شود.<br /></font></div>'),
(175857, 'طبرکی', '<span class=\"hlight\">طبرکی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ رَ ]</font></b> (ص نسبی ) منسوب به قلعه ٔ طبرک ری که قلعه ای بوده است . (سمعانی ). رجوع به طبرک شود.<br /></font></div>'),
(175858, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) ابوالعباس احمدبن ابی احمدبن القاص . یکی از مشاهیر فقهای شافعی است و در فقه شاگرد ابن سریج بوده، او راست : التلخیص، ادب القاضی، المواقیت، المفتاح و غیره . اهم آثار وی صغیرالحجم و کثیرالفائده میباشد. او از واعظان معروف بوده و گویند تا طرسوسه سفر کرده و بسال <span class=\"hlight\" dir=\"rtl\">٣٣٥</span> هَ . ق . درگذشته است . (قاموس الاعلام ترکی ). رجوع به ابن قاص و ابوالعباس احمدبن ابی احمد در همین لغت نامه شود.<br /></font></div>'),
(175859, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ص نسبی ) منسوب به طبرستان . (منتهی الارب ). اهل و ساکن مازندران . منسوب به طبرستان که مرکز آن آمل است و بیشتر از علماء که منسوب به طبرستان هستند ازآمل برخاسته اند. (سمعانی ). و هر کجا (طبری ) مطلق گفته شود، مورخ معروف طبرستانی مقصود است <span class=\"hlight\">:</span> <br />زآن سخنها که تازی است و دری <br />در سواد بخاری و طبری .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> کنایه از لب معشوق، منسوب به طبر که در اینجا مخفف طبرزد است که بمعنی نبات باشد. (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br />لب طبری وار طبرخون به دست <br />مغز طبرزد به طبرخون شکست .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بنفشه ٔ طبری </span> ؛ در مازندران و گیلان تقریباً از اوایل اسفند ماه بر هر دیواری و بر هر تل خاکی و مخصوصاً بر کنار جویبارها بنفشه ٔ با طراوت و نضارت بسیار روید و مردم از گل آن دسته بسته و یاران و دوستان را هدیه دهند <span class=\"hlight\">:</span> <br />بمنظر آمد باید که وقت منظر بود<br />نقاب لاله گشودند و لاله روی نمود<br />بنفشه ٔ طبری خیل خیل سر برکرد<br />چو آتشی که ز گوگرد بردویده کبود.<br /> <font color=\"Red\">منجیک .</font><br />چون بهم کردی بسیار بنفشه ٔ طبری <br />باز برگرد و ببستان شو چون کبک دری .<br /> <font color=\"Red\">منوچهری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بید طبری </span> ؛ طبرخون . سرخ بید. (اوبهی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">جامه ٔ طبری </span> ؛ جنس از برودکه تنگ است <span class=\"hlight\">:</span> تَرَکه ُ فی وسط الشتاء و شدةالبرد بقمیص واحد و کساءِ طبری . (ذیل تجارب الامم <span class=\"hlight\" dir=\"rtl\">٣</span>: <span class=\"hlight\" dir=\"rtl\">٤٢٨</span>).<br />یکفیک من سوء حالی ان سألت به <br />انی علی طبری فی الکوانین .<br />ابن الداهیةاحمدبن سیف .<br />رجوع به شرح احوال رودکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">درهم طبری </span> ؛ دو ثلث درهم شامی است . (منتهی الارب ). صاحب کتاب النقود آرد: و طبری منسوب به طبریه ٔواسط است نه طبریه ٔ فلسطین و بجای درهم طبری، درهم طبرک نیز آمده است و در جمع آن گویند: الدراهم الطبریة. رجوع به النقود ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٤</span>، <span class=\"hlight\" dir=\"rtl\">٩١</span> و <span class=\"hlight\" dir=\"rtl\">١٤٩</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مداد طبری </span> ؛ نوعی مداد منسوب به طبرستان <span class=\"hlight\">:</span> <br />وآن دوات بسدین را نه سر است و نه نگار<br />در بنش تازه مداد طبری برده بکار.<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(175860, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) او راست : الواضح، فی الرمی و النشاب . (کشف الظنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢٥</span>).<br /></font></div>'),
(175861, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) طبیبی است که ابن البیطارمکرر در کتاب المفردات از وی نقل کرده، از آنجمله در شرح الفاظ: ارماک، بقر، جوزجندم، صُرف (که در این جا نام کتابی هم از تألیفات وی به نام «الجوهرة» آورده است )، حلبة، طرخون، نان خواه . صاحب ذخیره ٔ خوارزمشاهی نیز از اقوال طبیبی معروف به طبری بسیار نقل کرده است . و مراد یا طبری ابوالحسن احمدبن محمد است و یا طبری الحاسب . رجوع به هر یک از این دو نام شود.<br /></font></div>'),
(175862, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ر ]</font></b>(اِخ ) ابن الطیب الطبری . رجوع به ابن طیب ابوالفرج عبداﷲ در همین لغت نامه و عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٢</span> شود.<br /></font></div>'),
(175863, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) ابوجعفرمحمدبن جریر از مشاهیر مورخان است . در تفسیر، حدیث، فقه و علوم دیگر هم ید طولائی داشته و یکی از ائمه ٔ زمان خود بشمار میرفته است . وی بسال <span class=\"hlight\" dir=\"rtl\">٢٢٤</span> هَ . ق . در شهر آمل از طبرستان تولد یافته، و در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٣١٠</span> هَ . ق . در بغداد درگذشته است . ابواسحاق شیرازی در کتاب «طبقات فقهاء» وی را یکی از مجتهدان عصر بشمار می آورد و ابوبکر خوارزمی معروف همشیره زاده ٔ اوست، و در اکثر علوم تألیفات داشته است و مشهورتر از همه کتاب معروف به «تاریخ طبری » میباشد که وقایع خلقت عالم را از زمان آدم تا عصر خود در آن آورده است . دیگر از تألیفات مهم وی تفسیر کبیر است کتاب تاریخ او از کتب موثق و معتبر بشمار میرود، به اختصار بفارسی هم ترجمه شده و ترجمه ٔ ترکی نیز دارد. وی در شعر و ادب نیز شهره ٔ عصر خویش بوده است . (قاموس الاعلام ترکی ). رجوع به ابن جریر، محمدبن جریر، التفهیم بیرونی ص <span class=\"hlight\" dir=\"rtl\">٤٨٩</span> و عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧</span> و ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٥</span> و ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧</span>، <span class=\"hlight\" dir=\"rtl\">١٤٢</span>، <span class=\"hlight\" dir=\"rtl\">١٤٧</span>، <span class=\"hlight\" dir=\"rtl\">١٥٣</span>، <span class=\"hlight\" dir=\"rtl\">١٥٩</span>، <span class=\"hlight\" dir=\"rtl\">١٦٠</span>، <span class=\"hlight\" dir=\"rtl\">١٦٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٣١</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٤</span> و ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠</span>، ضحی الاسلام ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>، حواشی ص <span class=\"hlight\" dir=\"rtl\">١٧٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٧٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٨٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٨٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٩٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٩١</span>، <span class=\"hlight\" dir=\"rtl\">٣٢٥</span> و <span class=\"hlight\" dir=\"rtl\">٣٢٦</span>، ایران باستان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٠١</span>، <span class=\"hlight\" dir=\"rtl\">١٠٥</span>، <span class=\"hlight\" dir=\"rtl\">٤٧٨</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩٨</span>، <span class=\"hlight\" dir=\"rtl\">٩٥٣</span>، <span class=\"hlight\" dir=\"rtl\">٩٥٦</span>، <span class=\"hlight\" dir=\"rtl\">٩٩١</span>، <span class=\"hlight\" dir=\"rtl\">١١٦٤</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٢٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٣٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٤٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٤٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٥١</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٥٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٥٧</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٥٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٦٠</span>، القفطی ص <span class=\"hlight\" dir=\"rtl\">١١٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٦١</span>، حبیب السیر چ <span class=\"hlight\" dir=\"rtl\">١</span> تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٢</span>، <span class=\"hlight\" dir=\"rtl\">١٨</span>، <span class=\"hlight\" dir=\"rtl\">١٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٢</span>، <span class=\"hlight\" dir=\"rtl\">٤٧</span>، <span class=\"hlight\" dir=\"rtl\">٤٩</span>، <span class=\"hlight\" dir=\"rtl\">٦٢</span>، <span class=\"hlight\" dir=\"rtl\">٧٢</span>، معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣٣</span>، روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٧٠٢</span>، فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٨</span>، معجم المطبوعات ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٩</span>، الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٦</span>، ایران در زمان ساسانیان ص <span class=\"hlight\" dir=\"rtl\">٣٤</span>، <span class=\"hlight\" dir=\"rtl\">٤٠</span>، <span class=\"hlight\" dir=\"rtl\">٥٠</span>، <span class=\"hlight\" dir=\"rtl\">٥٣</span>، <span class=\"hlight\" dir=\"rtl\">٦٣</span>، <span class=\"hlight\" dir=\"rtl\">٦٦</span>، <span class=\"hlight\" dir=\"rtl\">٦٨</span>، <span class=\"hlight\" dir=\"rtl\">٧٢</span>، <span class=\"hlight\" dir=\"rtl\">٧٣</span>، <span class=\"hlight\" dir=\"rtl\">٨٤</span>، <span class=\"hlight\" dir=\"rtl\">٢١٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٤١</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٥</span>، <span class=\"hlight\" dir=\"rtl\">٢٦٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٦٧</span>، <span class=\"hlight\" dir=\"rtl\">٢٨١</span>، <span class=\"hlight\" dir=\"rtl\">٢٩٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>، <span class=\"hlight\" dir=\"rtl\">٣١٠</span>، <span class=\"hlight\" dir=\"rtl\">٣١٥</span>، <span class=\"hlight\" dir=\"rtl\">٣١٦</span>، <span class=\"hlight\" dir=\"rtl\">٣١٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٢٧</span>، <span class=\"hlight\" dir=\"rtl\">٣٢٨</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٥</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٨</span>، <span class=\"hlight\" dir=\"rtl\">٣٦٨</span> و تاریخ ادبیات ایران تألیف ادواردبراون ترجمه ٔ رشیدیاسمی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٩٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٩٧</span> شود.<br /></font></div>'),
(175864, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) ابوالحسن احمدبن محمد الطبری . از اهل طبرستان و در صناعت طب عالم و فاضل بوده است، وی در دربار رکن الدوله به شغل پزشکی مشغول بود. او راست : کناشی معروف به «معالجات البقراطیه » و هومن اجل الکتب و انفعها، در این کتاب بیماریها و مداوای هر یک را بطریق استقصا، و کاملترین صورتی ذکر کرده است و مشتمل بر مقالات بسیار است . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢١</span>). رجوع به ابوالحسن احمدبن محمدالطبری در همین لغت نامه و قاموس الاعلام ترکی شود.<br /></font></div>'),
(175865, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) (الَ ...) ابوالحسن الترنجی الطبری : ابوریحان بیرونی در کتاب «الجماهر» در چند موضع نام این شخص را یاد کرده . وی ظاهراً پزشک بود و او را کناشی نیز هست . بترجمه ٔ احوال او دسترسی نیست . رجوع به الجماهر چ حیدرآباد دکن ص <span class=\"hlight\" dir=\"rtl\">١٤٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٠١</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٩</span> شود.<br /></font></div>'),
(175866, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) ابوالطیب طاهربن عبداﷲ. یکی ازمشاهیر فقهای شافعی است، و در شعر و ادبیات نیز مهارت تامه داشته، وی در شهر آمل از طبرستان نزد ابوعلی الزجاجی از اصحاب ابن القاص درس خوانده و در جرجان ونیشابور هم نزد مشاهیر زمان تلمذ کرده، آنگاه عزیمت بغداد نموده و از خدمت شیخ ابواسحاق اسفراینی استفاده برد، ابواسحاق شیرازی مشهور از طبری تعلم و استماع کرده، و مختصر مزنی و فروع ابوبکر حداد را شرح کرده و کتب بسیار درباره ٔ اصول، مذهب، خلاف و جدل نگاشته، بقضاء محله ٔ کرخ بغداد منصوب شده و تا هنگام وفات در این مقام پایدار بوده و بسال <span class=\"hlight\" dir=\"rtl\">٤٥٠</span> هَ . ق . در بغداد درگذشت و اشعار بسیار دارد. (قاموس الاعلام ترکی ).<br /></font></div>'),
(175867, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) ابوعلی حسن بن قاسم الطبری . از علمای شافعیه است ووی راست : کتاب مختصر مسائل الخلاف فی الکلام و النظر.و صاحب قاموس الاعلام آرد: یکی از مشاهیر فقهای شافعی است علم فقه را از ابوعلی بن ابی هریره اخذ کرده، در بغداد مشغول تدریس بوده است . اثر موسوم به «المحرر فی النظر» وی نخستین تشبثی است که در علم خلاف بعمل آمده و دو تألیف مسمی به الافصاح، و العدة در فقه داردو کتابی دائر بر «جدل و اصول فقه » نیز نگاشته است . او بسال <span class=\"hlight\" dir=\"rtl\">٣٠٥</span> هَ . ق . درگذشته است . (قاموس الاعلام ترکی ). رجوع به ابوعلی حسن بن قاسم طبری، ابوعلی حسین بن قاسم در همین لغت نامه و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٦</span> شود.<br /></font></div>'),
(175868, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) ابوالفیاض طبری . از مداحان صاحب بن عباد بوده است . رجوع به صاحب بن عباد تألیف بهمنیارو همین لغت نامه ذیل صاحب بن عباد (مداحان او) شود.<br /></font></div>'),
(175869, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) (الَ ...) احمدبن عبداﷲ. مُحب الدین الطبری . مردی فاضل بوده، وی را تصانیف است، از آنجمله السمط الثمین فی مناقب امهات المؤمنین . وفات وی بسال <span class=\"hlight\" dir=\"rtl\">٦٩٤</span> هَ . ق . بوده است . (اعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٧</span>). صاحب معجم المطبوعات از طبقات سُبکی و طبقات اسدی نقل کرده، گوید: ابوالعباس احمدبن عبداﷲبن محمد ابن ابی بکربن ابراهیم الطبری المکی، شیخ الحرم و حافظالحجاز. مؤلف دیوان الاسلام گوید: وی را مؤلفاتی است، از آن جمله الاحکام فی الحدیث و شرح التنبیه و المناسک در شهر قوص نزد شیخ مجدالدین قشیری علم فقه فراگرفت، مظفر صاحب یمن برای سماع حدیث او راطلب کرد، وی نیز از مکه بسوی مظفر شد و چندی نزد وی اقامت گزید. وفات وی بسال <span class=\"hlight\" dir=\"rtl\">٩١٤</span> هَ . ق . در مکه بود ودر معلاة بخاک سپرده شد. کتابی خطی از تألیفات محب الدین طبری دیدم، موسوم به خُلاصةُالسیر فی بیان بعض احوال سیدالبشر کتابی بود بسیار نفیس، در دیباچه ٔ آن آورده که از دوازده کتاب برگزیده و گرد آورده است . وسبکی و اسدی هیچیک در ترجمه ٔ احوال طبری نامی از این تألیف نبرده اند. دیگر از تالیفات وی، الریاض النضرة، فی مناقب الاصحاب العشرة است که در دو مجلد در مطبعه ٔ حسینیه به رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣٢</span>). رجوع به احمدبن عبداﷲ محب الدین الطبری شود.<br /></font></div>'),
(175870, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) الحاسب . یکی از پزشکان عصر خلفای بنی عباس . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٠</span>).<br /></font></div>'),
(175871, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) (الَ ...) عبدالقادربن محمد الحسینی الطبری المکی الشافعی، امام ائمةالحجاز. وی در مکه بسال <span class=\"hlight\" dir=\"rtl\">٩٧٦</span> هَ . ق . قدم بعرصه ٔ وجود نهاد و در آن جا نشو و نما یافت و در کنار پدر و مادر خویش پرورده شد، در دوازده سالگی قرآن کریم را از بر داشت، و چندین متن از قبیل اربعین نووی و اشاراتی را که بر آن نوشته اند، عقایدنسفیه، و الفیه ٔ ابن مالک، و ثلث منهج از تألیفات شیخ الاسلام زکریا الانصاری را نیز محفوظ ذهن خویش ساخته بود: و در سال <span class=\"hlight\" dir=\"rtl\">٩٩١</span> هَ . ق . تمامی محفوظات خود را برمشایخ عصر عرضه داشت و به اخذ اجازه ٔ روایت آن محفوظات نائل گردید. سپس در همان سال به تألیف و تصنیف پرداخت و چندین کتاب تألیف و تصنیف کرد و نیک از عهده برآمد. از آن جمله است مقامه ای به نام درةالاصداف السنیة فی ذروةالاوصاف الخفیه، عیون المسائل و شرح بردریدیه و غیرذلک . عیون المسائل وی مشتمل بر سی فن ازفنون است . آغاز آن علم قوافی، و انجام آن علم تقویم است . محمدعمر حسامی بیرونی در مطبعةالسلام این کتاب را در سال <span class=\"hlight\" dir=\"rtl\">١٣١٦</span> هَ . ق . بطبع رسانیده است . وفات وی بمکه بسال <span class=\"hlight\" dir=\"rtl\">١٠٣٣</span> هَ . ق . بوده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣١</span>). رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٦</span> شود.<br /></font></div>'),
(175872, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) علوی از مداحان صاحب بن عباد بوده است . رجوع به صاحب بن عباد تألیف بهمنیار شود.<br /></font></div>'),
(175873, 'طبری', '<span class=\"hlight\">طبری .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) (الَ ...) علی بن سهل بن ربن الطبری . کنیت وی ابوالحسن است . ابن الندیم بغدادی کاتب نام وی را علی بن ربل ضبط کرده و گفته است : او کاتب مازیاربن قارن بود، به دست معتصم عباسی قبول اسلام کرد و بدین وسیله نزد وی قرب و منزلتی یافت . و پایه ٔفضیلت او معلوم و آشکار گردید. متوکل عباسی او را به همنشینی خود برگزید. در ادب و فرهنگ وی را مقامی ارجمند بود و در صناعت طب استاد ابوبکر محمدبن زکریا الرازی بود. مولد و منشاء او طبرستان است . از سخنان اوست که گوید: نادان همواره در معرض مرگ است . او راست : کتاب فردوس الحکمه، و این کتاب را بر هفت نوع بخش کرده است، و همگی هفت بخش آن محتوی بر سی گفتار است، و کلیه سی گفتار بر سیصد و شصت باب بخش شده است . کتاب ارفاق الحیوة. کتاب تحفةالملوک . کتاب کناش الحضرة.کتاب منافع الاطعمه و الاشربة و العقاقیر. کتاب حفظ الصحة. کتاب فی الرقی . کتاب فی الحجامة. کتاب فی ترتیب الاغذیة. (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>). قفطی در کتاب خویش آورده : علی بن ربن الطبری الطبیب ابوالحسن در صناعت پزشکی فاضل است، در طبرستان نزد فرمانروایان آنجا روزگار بسر میبرد و علم حکمت در همان جا فراگرفت، و در طبیعیات یگانه گردید؛ بواسطه ٔ اختلافی که در طبرستان پیش آمد بسوی ری شد. محمد زکریای رازی نزد وی به فراگرفتن دانش مشغول گردید و دانش بسیاری از او استفاده کرد، سپس به «سر من رای » رفت، و در آنجا اقامت گزید، و کناش موسوم به فردوس الحکمه را تألیف کرد و آن کتابی است مختصر جمیل التصنیف و لطیف التألیف، و بر هفت نوع است مشتمل بر سی گفتار و مجموع کتاب شامل سیصد و شصت بخش است و ربن نام سهل پدر وی بوده، زیرااو از علمای بزرگ یهود بشمار میرفت . (قفطی چ لیپزیک ص <span class=\"hlight\" dir=\"rtl\">٢٣١</span>). بیهقی در تتمه ٔ صوان الحکمه گوید: ابن ربن طبری از کتاب مرو بوده است، همتی بلند داشت و به انجیل و پزشکی عالم بود، و ربن بمعنی معلم و استاد بزرگ باشد، وی از دانشمندان بزرگ بشمار میرفت، و گواه این گفتار کتاب فردوس الحکمه ٔ اوست . و او را تصانیف بسیاراست که بیشتر آنها در پزشکی است، و از سخنانی که ازاو روایت کرده اند این جملات است : «تندرستی پایان هر آرزوئی است ». «آزمون بسیار سبب افزایش خرد باشد». «تکلف زیان آور است ». «بدترین گفتار آن است که جزئی از آن جزء دیگر را نقض کند». (تتمه ٔ صوان الحکمه ص <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175874, 'طبریجان', '<span class=\"hlight\">طبریجان .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) دهی از دهستان همت آباد شهرستان بروجرد، واقع در <span class=\"hlight\" dir=\"rtl\">٩</span>هزارگزی جنوب خاوری بروجرد و <span class=\"hlight\" dir=\"rtl\">٨</span>هزارگزی جنوب شوسه . جلگه، معتدل با <span class=\"hlight\" dir=\"rtl\">٥١٧</span> تن سکنه . آب آن از رودخانه . محصول آنجا غلات . شغل اهالی زراعت است و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(175875, 'طبریمون', '<span class=\"hlight\">طبریمون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (رمون : رحیم و مشفق ) پدر بن هدد، اولین پادشاه شام که معاصر آسای پادشاه یهودا بود (کتاب اول پادشاهان فصل <span class=\"hlight\" dir=\"rtl\">١٥</span>؛ آیه ٔ <span class=\"hlight\" dir=\"rtl\">١٨</span>). (قاموس کتاب مقدس ).<br /></font></div>'),
(175876, 'طبریه', '<span class=\"hlight\">طبریه .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ری ی َ ]</font></b> (اِخ ) قصبه ٔ مرکز قضائی است در سنجاق عکا از ولایت بیروت، واقع در <span class=\"hlight\" dir=\"rtl\">٤٣</span>هزارگزی مشرق عکا و در ساحل دریاچه ای موسوم به همین اسم . <span class=\"hlight\" dir=\"rtl\">٣٥٠٠</span> تن جمعیت دارد که دو ثلثش یهودی است، سوری ویران، یک قلعه در گوشه ٔ شمال غربی، چند مسجد و چند معبد یهودی، و یک دیر مخصوص به کاتولیک ها وحمامهای معدنی معروف در حومه ٔ آن وجود دارد. این شهرک در میان ساحل و دو دامنه ٔ کوهی، در شمال دشتی سنگلاخ دیده می شود، و یکی از قصبات بسیار قدیم است . نام قدیمی اش کزط یا راکط بوده و بعدها ویران گشته، و <span class=\"hlight\" dir=\"rtl\">١٦</span> سال قبل از میلاد «هرود» حاکم فلسطین آنرا دوباره بناکرده و به انتساب به نام تیبریا (طباریوس ) امپراطوررومی، «تیبریاده » نامیده شده، معرب آن به صورت «طبریه » درآمده، و پس از تخریب قدس مدت مدیدی مرکز بنی اسرائیل بوده تفسیر تورات و برخی از کتب مذهبی یهودیان در این شهر نوشته شده و از این رو در نزد آنان جنبه ٔ تقدس دارد. بسال <span class=\"hlight\" dir=\"rtl\">١٣</span> هَ . ق . سرجیل بن حسنه این بلد را به صلح فتح کرد. در زمان خلافت عمر اهالی نقض عهد و طغیان نمودند، ابوعبیدةبن الجراح عمروعاص را مأمور سرکوبی نمود و دوباره آنرا فتح کردند و در دوره ٔ اسلامی بسیار معمور و آباد گردید، جمع کثیری ملقب به طبرانی از علمای مشهور از این خاک برخاسته اند. در زمان جنگهای صلیبی، مدت کمی مرکزیت حکومتی کوچک از صلیبیون گردید و به سال <span class=\"hlight\" dir=\"rtl\">١١٨٧</span> م . صلاح الدین آن را از چنگ آن ها بدرآورد و بعد از <span class=\"hlight\" dir=\"rtl\">٥٣</span> سال باز به دست فرنگیان افتاد و مجدداً پس از <span class=\"hlight\" dir=\"rtl\">٧</span> سال به دست مسلمانان درآمد و <span class=\"hlight\" dir=\"rtl\">٦٠</span>سال پیش اکثر اطراف سور آن از زلزله ویران گردید و برخی از جوامع و ابنیه ٔ دیگر نیز صدمه ٔ بسیار دید.<br /></font></div>'),
(175877, 'طبریه', '<span class=\"hlight\">طبریه .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ری ی َ ]</font></b> (اِخ ) (قضای ...) قضائی است در جهت شرقی سنجاق عکا از ولایت بیروت، از طرف شمال به قضای صفد از سمت مغرب به دو قضای ناصره و جنین، و از جانب جنوب بقضای سلط، و از سوی مشرق به سنجاق شام از ولایت سوریه محدود می شود. و <span class=\"hlight\" dir=\"rtl\">٣٨</span> قریه و <span class=\"hlight\" dir=\"rtl\">٦٨٥٢</span> تن سکنه دارد که قریب به نصف آن مسلمان و بقیه نصارا و یهودند. قسمتی از اراضی طبریه کوهستانی و بخش دیگر دشت «غوربیلسان » است . دریاچه ٔ طبریه و نهر شریعه حدود شرقی این قضارا مفروز میسازد و بعضی انهار وارده ٔ به این نهر اراضی قضای مذکور را سیراب میکند. خاکش بسیار حاصلخیز می باشد. و محصولاتش عبارت است از گندم، جو، ارزن، کنجد، نخود، عدس، سیب زمینی زیتون و عسل و غیره، حیوانات اهلی آن عبارت است از گوسفند، بز، اسب، خر و شتر.<br /></font></div>'),
(175878, 'طبریه', '<span class=\"hlight\">طبریه .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ری ی َ ]</font></b> (اِخ ) دهی است بواسط. طبری منسوب به آن است . (منتهی الارب ). ابوبکربن محمدبن موسی گفته است : طبریه نیز جایگاهی است در واسط. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧</span>).<br /></font></div>'),
(175879, 'طبریه', '<span class=\"hlight\">طبریه .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ری ی َ ]</font></b> (اِخ ) جایگاهی است از نواحی دیاربکر. (نخبةالدهر دمشقی ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span>).<br /></font></div>'),
(175880, 'طبریه', '<span class=\"hlight\">طبریه .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ری ی َ ]</font></b> (اِخ ) قصبه ای است به اُردن، طبرانی منسوب به آن . (منتهی الارب ). نام شهری بر ساحل غربی دریاچه ٔ طبریه . محلی است از اردن از مضافات شام . (رساله ٔ مسکوکات مقریزی ) بشام قصبه ٔ ناحیت اردن است، شهری است خرم و آبادان و بانعمت و آبهای روان . (حدود العالم ). قصبه ٔ اردن و شهری است مستطیل و بر کنار دریاچه ٔ طبریه واقع است . (نخبةالدهر دمشقی ص <span class=\"hlight\" dir=\"rtl\">٢١١</span>). شهری است در جانب مغرب . گویند عقرب در آن شهر بسیار است . (برهان ). یاقوت گوید: طبریه در اقلیم سوم است و طول آن از جهت مغرب <span class=\"hlight\" dir=\"rtl\">٥٧</span> درجه و <span class=\"hlight\" dir=\"rtl\">٤٥</span> دقیقه، و عرض آن <span class=\"hlight\" dir=\"rtl\">٣٢</span> درجه است . این شهر در سال <span class=\"hlight\" dir=\"rtl\">١٣</span> هَ . ق . بطریق صلح بر دست شرحبیل بن حسته فتح گردید، مشروط بر آنکه نیمی از منازل و کنایس خود را تسلیم مسلمانان کنند. و بعضی گفته اند که شرحبیل چندین روز طبریه را در محاصره نگاه داشت و اهالی ناگزیر شدند به نفوس و اموال و کنایس خویش صلح کنند، مگر جایهائی را که از سکنه تهی کرده باشند؛ شرحبیل برای مسجد مسلمانان موضعی را مستثنی کرد. در خلافت عمر اهالی طبریه پیمان شکستند و گروهی از رومیان غیربومی نیز با آنان همدست شدند، ابوعبیدة عمروبن العاص را با چهارهزار تن به طبریه گسیل داشت و عمرو آنجا را فتح کرد و اهالی صلحی را که با شرحبیل کرده بودند با همان شروط تجدید کردند؛ عمرو هم بدون پیکار و زد و خورد تمام بلاد اردن را فتح کرد. طبریه بر دریاچه معروف به مجیرة طبریة که بر طرف کوه واقع است مشرف میباشد و کوه طور نیز بر دریاچه مشرف است . این شهر از توابع اردن و بر طرف غور واقع است و از آنجا تا دمشق سه روز راه است و تا بیت المقدس هم مسافت سه روز راه است، ولی بین طبریه و عکا دو روز راه مسافت بیش نیست . طبریه شکلا مستطیل و بر دریاچه ٔ طبریه مشرف است، عرض آن کم است و به کوهی خُرد که پایان آبادی است منتهی میگردد. علی بن ابوبکر هروی گوید: اما حمامهای طبریة، گویند از عجائب دنیاست، ولی باید دانست منظورحمامهائی نیست که بر دروازه ٔ طبریه و بجانب بحیره ٔ طبریه واقعند چه مانند آن حمامها در این جهان بسیار است و ما خود دیده ایم، اینکه گفته است از عجایب دنیاست، مقصود موضعی است از اعمال طبریه در مشرق دیه معروف به حسینیه، واقع در صحرا و آن عبارت است از عمارتی قدیم که در افواه معروف است از بناهای حضرت سلیمان علیه السلام است و آن مجسمه ای بوده است که آب از سینه ٔ آن بیرون می آمده و از آب آن دوازده چشمه تشکیل میشده و آب هر چشمه ای ویژه ٔ شفای بیماری مخصوصی بوده که مریض پس از شستشوی بدن در آن چشمه، از آن بیماری بهبود می یافته است . آبش نیک گرم است و صاف و گوارا و خوشبوی، بیماران بقصد شفا آهنگ آن آب میکردند، و مردم در چشمه هائی که در جایگاه بسیار گرم می ریخته شنا میکرده اند و سود آب تنی در اینگونه چشمه ها آشکار است . وما نظیر آن موضع در هیچ محلی ندیدیم مگر شرمیا را که وصف آن در جای خود گذشت . ابوالقاسم گوید: نخستین کسی که طبریه را بنا کرد یکی از پادشاهان روم موسوم به «طبارا» بود، و آنجا را به نام خود نامید و در طبریه چشمه هائی است که آبش شور و گرم است و حمامهائی برای آن آب ساخته اند که نیازی به گرم شدن ندارند؛ شب وروز آب گرم از آن حمامها جاری است . و نزدیک آن حمامها چشمه ٔ آب گرمی است که مبتلایان به جرب و گر در آن غسل میکنند، و به طبریه از جانب غور بین طبریه و بیسان، چشمه ٔ آب گرم حضرت سلیمان علیه السلام است که بزعم مردم آب آن هر دردی را شفاست . ابوعبداﷲ البناء گوید: طبریه مرکز و قصبه ٔ اردن است (شهر وادی کنعان ) بین کوه و دریاچه واقع شده است، از این رو شهری است غم انگیز و در تابستان هوایش ناسازگار و وبائی است، طول این شهر فرسنگی است و عرض آن در برابر طول وی قابل ذکر نیست . بازارش از دروازه ای تا دروازه ٔ دیگر امتداددارد و مقابر آن بر کوه است . در آنجا هشت گرمابه است که آب آنها بدون هیمه مصرف کردن همواره گرم باشد. مسجد جامع بزرگی دارد که در بازار واقع شده است . زمین مسجد را از سنگهای ریزه پوشانیده اند و دارای ستونهای سنگی پیوسته بهم میباشد. معروف است که اهالی طبریه دوازده ماه سال را بدین طریق بسر میبرند. دو ماه از کثرت کیک در تکاپو هستند و دو ماه با پشه هم آغوشندچه در آن ناحیه پشه فراوان است و دو ماه با زنبورهانبرد میکنند و آنها را از طعام و مواد شیرینی میرانند و دو ماه از کثرت گرما برهنه بسر میبرند و دو ماه نیشکر می مکند و دو ماه از بسیاری گل در لجن زارها فرومیروند. در پایان این شهر پلی است بزرگ که از آن بجاده ٔ دمشق میگذرند، آب آشامیدنی اهالی از دریاچه ٔ طبریه است . در اطراف دریاچه همه جا دیه های پیوسته به یکدیگر و نخلستان ها مشاهده میشود. کشتیهای بزرگ در این دریاچه حرکت میکند و دارای ماهی بسیاری است که خوراک آنگونه ماهیها برای مردم غیربومی ناگوار است . کوه بر این شهر مشرف میباشد. آب دریاچه ٔ مزبور گواراست ولی شیرین نیست . کسی را که بدین شهر منسوب کنند طبرانی گویند بر غیر قیاس، چون منسوبان به طبرستان را طبری میگویند و بسیار مورد استعمال دارد از این رو در نسبت بین این دو موضع فرقی گذاشتند و منسوب به طبریه را طبرانی گفتند، چنانکه در نسبت به صنعاء و بهراء و بحرین گویند صنعانی، بهرانی، بحرانی . و مردم افاضل و علمای بزرگ از این شهربرخاسته اند. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>). ابن بطوطه درسفرنامه خود آورده : طبریه در قدیم شهری بزرگ بوده وجز رسم و نشانه ای که حاکی از عظمت باستانی آن میباشد امروزه از آن چیزی باقی نیست . گرمابه های شگفت آوری در آن شهر هست که مردانه و زنانه آنها از یکدیگر متمایز است آب آنها سخت گرم است ... در این شهر مسجدی است که بمسجد پیمبران معروف است، مزار شعیب و دختر وی که زوجه ٔ حضرت موسی بوده، سلیمان، یهودا، و روبیل علیهم السلام در آن مسجد میباشد. آهنگ زیارت چاهی که حضرت یوسف علیه السلام را در آن افکندند کردیم، این چاه در صحن مسجد کوچکی بر گوشه ای واقع است، چاه خود بزرگ و عمیق است . از آب آن که از آب باران گرد آید، آشامیدیم . متولی آنجا میگفت از این چاه خود نیز آب برآید.(سفرنامه ٔ ابن بطوطه چ مطبعةالازهریة مصر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).و در قاموس کتاب مقدس آمده است : شهری است از جلیل بر ساحل غربی دریای جلیل که آنرا دریای طبریه گویند (یوحنا. باب <span class=\"hlight\" dir=\"rtl\">٦</span>؛ آیه ٔ <span class=\"hlight\" dir=\"rtl\">١</span> و باب <span class=\"hlight\" dir=\"rtl\">٣١</span>؛ آیه ٔ <span class=\"hlight\" dir=\"rtl\">١</span>) و یوحنای حواری که انجیل خود را بعد از تمام اناجیل نوشت، دریای جلیل را که در آیه ٔ اول واقع است دریای طبریه تفسیرنموده است . اما طبریه جز یکدفعه در انجیل مذکور نیست . (یوحنا باب <span class=\"hlight\" dir=\"rtl\">٦</span>؛ آیه ٔ <span class=\"hlight\" dir=\"rtl\">٢٣</span>) و با وجودی که طبریه در ایام مسیح معروف بود، حضرتش در آنجا نرفت، و در آن زمان طبریه از جمله ٔ شهرهای جدید بود، زیرا هیرودیس آنرا در سال <span class=\"hlight\" dir=\"rtl\">١٦</span> - <span class=\"hlight\" dir=\"rtl\">٢٢</span> م . مجدداً بنا کرده، محض احترام نام طباریوس امپراطور، آنرا طبریه نامید. یوسیفوس گوید که هیرودیس طبریه را بر موضعی که قبور قدیمه ٔ بسیار و بقایای شهر قدیم اولاد منسّه بود بنا کرد، بدان لحاظ در انظار یهود ناپاک و مردود بود، و هیرودیس غربا و اجنبیان و غلامان را در آنجا مسکن داده، میدان و حمامها و هیاکل و بناهای عظیمه ٔ دیگر بنا کرد و قناتی در آن حفر کرد که طولش نه میل بود. و در مدت جنگ یهود با رومیان، یوسیفوس در آنجا متحصن بود، و بعد ازانهدام اورشلیم، مجمع سهندریم در آنجا استقرار یافته مرکز مشهور و معروف تعالیم یهود گشت، و منشاء که شریعت تقلیدیه یهود باشد، و ماسوره که کتاب اعراب کلمات تورات و شرح و معنای آن باشد در آنجا تصنیف گشت . اما حالت حالیه طبریه آنکه بر ساحل جنوب غربی دریای طبریه واقع است و قدری از شهر قدیم را که خرابه های آن مسافت یک میل و نیم بطرف جنوب امتداد می یابد پوشانیده است و بسیاری از سنگهای قدیم بساختمانهای شهر جدید نقل و انتقال یافته، ولی فعلاً باز در بعضی از خرابه های شهر قدیم سنگهای مرمر صیقلی و غیره یافت شود. (ملاحظه در دریای جلیل ) و شهر حالیه را از جانب دشت، حصار مخروبه ای است، و اغلب کوی های شهر در زلزله ای که در روز اول سال <span class=\"hlight\" dir=\"rtl\">١٨٣٧</span> م . واقع شده، خراب گشته و ششصدتن از اهالی مقتول گردیدند. و در مکانی که گویند خانه ٔ پطرس در آنجا بوده فعلاً کنیسه ای است . و هرچند منظر شهر از دور بس خوش و نیکو و باصفا بنظر میرسد با وجود آن از کثیفترین شهرهای مشرق میباشد، و گاهی از اوقات درجه ٔ حرارت در آنجا ترقی مینماید که به یکصد درجه فارنهایت بالاتر میرسد و شهر طبریه فعلاً یکی از چهار شهر مقدس یهود محسوب میشود و نصف سکنه ٔ آن یهودند که زیست ایشان معلق و منوط بر صدقاتی است که از برادران دینی ایشان که در اطراف و اکناف دنیا هستند فرستاده میشود، و مسلم و نصاری نیز در آن میباشند، و عدد نفوسش از سه الی چهار هزار میشود. در حوالی شهر مسطور حمامهای طبیعی است که آب آنها <span class=\"hlight\" dir=\"rtl\">١٣١</span> درجه و <span class=\"hlight\" dir=\"rtl\">١٤١</span> درجه فارنهایت گرم است . مقبره ای که بعضی از مشاهیر علمای یهود در آنجا مدفونند بر تلی واقع است که تخمیناً یک میل بطرف غربی شهر مرقوم مسافت دارد. (قاموس کتاب مقدس صص <span class=\"hlight\" dir=\"rtl\">٥٧٨</span> - <span class=\"hlight\" dir=\"rtl\">٥٧٩</span>). و رجوع به مجمل التواریخ و القصص، ص <span class=\"hlight\" dir=\"rtl\">٢٧٢</span>، <span class=\"hlight\" dir=\"rtl\">٤٧٩</span> و عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٤</span> و فارسنامه ٔ ابن البلخی چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٥</span> و تاریخ سیستان حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>و نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٢٥٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٦٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٩٠</span> و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٣٢٣</span> و حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>، <span class=\"hlight\" dir=\"rtl\">١٦٠</span>، <span class=\"hlight\" dir=\"rtl\">١٨٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٩٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٩٢</span>، <span class=\"hlight\" dir=\"rtl\">٤٠٦</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤١١</span> و سفرنامه ٔ ناصرخسرو شود.<br /></font></div>'),
(175881, 'طبریه', '<span class=\"hlight\">طبریه .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ری ی َ ]</font></b> (اِخ ) (دریاچه ٔ...) دریاچه ٔ بزرگی است در قسمت شمالی فلسطین در حدود دو ولایت بیروت و سوریه و از انتشار نهر اردن (به نام دیگر شریعه ) در دشت غور بعمل آید. مابین <span class=\"hlight\" dir=\"rtl\">٣٢</span> درجه و <span class=\"hlight\" dir=\"rtl\">٤١</span> دقیقه و <span class=\"hlight\" dir=\"rtl\">٢١</span> ثانیه و <span class=\"hlight\" dir=\"rtl\">٣٢</span> درجه و <span class=\"hlight\" dir=\"rtl\">٥٣</span> دقیقه و <span class=\"hlight\" dir=\"rtl\">٢٧</span> ثانیه عرض شمالی امتداد یافته، و نقطه ٔ وسطی آن واقعه در خارج نهرالشریعه در <span class=\"hlight\" dir=\"rtl\">٣٣</span> درجه و <span class=\"hlight\" dir=\"rtl\">١٥</span> دقیقه و <span class=\"hlight\" dir=\"rtl\">٢٤</span> ثانیه واقع است . طولش از شمال به جنوب <span class=\"hlight\" dir=\"rtl\">٢١</span> و عرضش در بین <span class=\"hlight\" dir=\"rtl\">٧</span> و <span class=\"hlight\" dir=\"rtl\">١٧</span> هزار گز میباشد.و منابع نهر مزبور که این دریاچه را منشق سازد، <span class=\"hlight\" dir=\"rtl\">٥٦٢</span>گز از مقابل دریا ارتفاع دارد. بحر لوط که منصب از اوست از محل مذکور <span class=\"hlight\" dir=\"rtl\">٣٩٢</span> گز پستی دارد و سطح خود بحر طبریه نیز از سطح دریا <span class=\"hlight\" dir=\"rtl\">٢٠٨</span> و نظر بحساب دیگری <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> گز پست تر است . علاوه بر نهر شریعه ٔ مزبور دو رود عین الزیتون و به نام دیگر وادی السلامه، و وادی السمک هم وارد بحیره ٔ مزبور شود. ساحل شرقی آن از خود دریاچه بلندتر میباشد، گرداگرد وی را جبال مرتفع فراگرفته است . دشت وسیع و پهناور غور هم ساحلی از آن را تشکیل میدهدو در نتیجه، منظره ٔ بسیار دلاویزی دارد. و از بعض آثار و علائم چنان استنباط میشود که در سوابق ایام این بحیره وسیعتر بوده، در عهد رومیان سفائن بزرگ در این آب ایاب و ذهاب داشتند. در ادوار اسلامی هم بقول یاقوت حموی در قرن هفتم هجری سفائن بسیار در این دریاچه رفت و آمد میکردند، ولی در حال حاضر غیر چند زورق صیادی ماهیگیران چیزی مشاهده نمیشود. در سابق این ناحیه قصبات بسیار داشته است و فعلاً غیر از طبریه قصبه ٔدیگری نیست و چند دهکده هم در اطراف وجود دارد. (ازقاموس الاعلام ترکی ). و رجوع به سفرنامه ٔ ناصرخسرو شود. مؤلف حدود العالم، از جمله ٔ دریاچه های هفت گانه، دومین دریاچه را به نام دریای طبریه نام برده و گوید: درازای او دوازده فرسنگ اندر پهنای هشت فرسنگ . (حدود العالم ص <span class=\"hlight\" dir=\"rtl\">١٠</span>). دریاچه ای است واقع در فلسطین، و نهر اردن آن را از جنوب به بحیره ٔ لوط (بحرالمیت ) پیوندد. و صلاح الدین ایوبی قوم فرانگ را در سومین جنگ صلیبی در کنار این دریاچه بشکست . دمشقی در نخبةالدهر آورده که درازای دریاچه ٔ طبریه دوازده و پهنای آن شش میل است و کوهها از هر جانب این دریاچه را احاطه کرده است . و نهرالشریعة از این دریاچه بگذرد و به دریاچه ٔ زغر ریزد، و بر کنار این دریاچه سرچشمه هاست که آب آنها سخت گرم باشد، و آن سرچشمه ها را حمات نامند و آب این منابع نمکی و گوگردی است و آماس بدن و جَرَب را سودمند، و برای دفع زیان غلبه ٔ بلغم و افراط فربهی نافع است، گویند قبر حضرت سلیمان علیه السلام در این دریاچه است . (نخبةالدهر ص <span class=\"hlight\" dir=\"rtl\">٢١٢</span>). رجوع به حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧</span>، عقدالفریدج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٣</span> و اخبارالحکماء قفطی چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٣١٩</span> شود.<br /></font></div>'),
(175882, 'طبز', '<span class=\"hlight\">طبز.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) آرامش کردن با زن . (منتهی الارب ) (منتخب اللغات ) (شمس اللغات ).جماع کردن با زن . (قاموس ). <BR><font color=\"Blue\">◄</font> (اِ) پری هر چیزی . (منتهی الارب ) (منتخب اللغات ) (شمس اللغات ).<br /></font></div>'),
(175883, 'طبز', '<span class=\"hlight\">طبز.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص، اِ) سنگ بزرگ از کوه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کرانه ٔ قویتر از کوه . (منتهی الارب ). جانب کوه . (شمس اللغات ). <BR><font color=\"Blue\">◄</font> شتر دوکوهانه . (منتهی الارب ) (منتخب اللغات ) (شمس اللغات ). دهانج . (منتهی الارب ).<br /></font></div>'),
(175884, 'طبس', '<span class=\"hlight\">طبس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) سیاه از هر چیزی . (منتهی الارب ) (منتخب اللغات ) (شمس اللغات ).<br /></font></div>'),
(175885, 'طبس', '<span class=\"hlight\">طبس .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) گرگ . (منتهی الارب ). ج، طُبوس . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span>).<br /></font></div>'),
(175886, 'طبس', '<span class=\"hlight\">طبس .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) از بلوکات ولایت سبزوار خراسان، عده ٔ قری (<span class=\"hlight\" dir=\"rtl\">٢٧</span>) مرکز طبس، حد شمالی جوین، شرقی نیشابور جنوبی قصبه، غربی بواکره . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٢٠٣</span>). قصبه ٔ مرکزی دهستان طبس بخش صفی آباد شهرستان سبزوار، واقع در <span class=\"hlight\" dir=\"rtl\">٤١</span> هزارگزی جنوب باختری صفی آباد، سر راه اتومبیل رو صفی آباد به طبس . هوای آن کوهستانی و سردسیر، دارای <span class=\"hlight\" dir=\"rtl\">١٠٦٢</span> تن سکنه . آب آن از رودخانه و چشمه سار. محصولات آن غلات، پنبه و باغات کنجد. شغل اهالی زراعت و صنایع دستی زنان آنجا قالیچه و کرباس بافی است . راه آن اتومبیل رو است . پاسگاه ژاندارمری و دبستان دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>). و نیزمؤلف کتاب مزبور آرد: نام یکی از دهستانهای بخش صفی آباد شهرستان سبزوار و محدود است از شمال به دهستان حکم آباد، از جنوب به کوه طبس و اندقان، از خاور به دهستان سلطان آباد و از باختر به دهستان کهنه . موقعیت کوهستانی هوا معتدل آب اغلب قراء از چندین رودخانه محلی تأمین میشود و راههای آن پیاده رو صعب العبور است . این دهستان از <span class=\"hlight\" dir=\"rtl\">٢٦</span> آبادی بزرگ و کوچک تشکیل و مجموع نفوس آن در حدود <span class=\"hlight\" dir=\"rtl\">١٣٥٣٧</span> نفر میباشد. محصول عمده ٔ آنجا غلات، ارزن، بنشن، کنجد، پنبه و انواع میوه و ابریشم است . شغل اهالی زراعت و صنایع دستی زنان قالیچه وکرباس بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175887, 'طبس', '<span class=\"hlight\">طبس .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) شهرستانی است در خراسان، اعجمی است . (منتهی الارب ) (غیاث اللغات ). نام قصبه ای، در معجم البلدان آورده : اصطخری گفته است طبس شهری است کوچک و از قاین کوچکتر و از گرمسیرات محسوب است درخت خرما در آنجا میروید حصاری دارد، ولی دارای قهندز نیست، بنای آنجا از گل است، و آبش از کاریز و نخلستان آنجا از نخلستان قاین بیشتر است . عرب آنجا را دروازه ٔ خراسان میخواند، زیرا در روزگار خلافت عثمان بن عفان که آهنگ فتح خراسان کردند، نخستین فتحی که آنان را نصیب شد، فتح طبس بود. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧</span>). و نیز یاقوت گوید: طبس را پارسیان به لفظ مفرد استعمال میکنند و تازیان بلفظ تثنیه و طبسان میخوانند. ابوسعد گفته است :طبس شهری است واقع در صحرائی بین نیشابور، اصفهان وکرمان و آن عبارت است از دو طبس، یکی طبس گیلکی، و دیگری طبس مسینان که هر دو را طبسان گویند. (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨</span>). و سمعانی آرد: طبس شهری است در فلات که هرگاه از آن خارج شویم بهر سوی روی آوریم ناگزیر باید فلات را بپیمائیم . و آن شهر میان نیشابور، اصفهان و کرمان واقع است و در روزگار عمر فتح شده است و در زمان وی جز این شهر ناحیه ٔ دیگری در ایران فتح نشده است . و در آنجا دو طبس است : یکی طبس گیلکی و دیگری طبس مسینان و آنها را طبسین گویند. (انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ). و بهمنیار آرد: طبس، نام دو محل است، یکی شهرستان طبس در جنوب خراسان که مرکز آن هم طبس است، و دیگر بخش طبس از توابع سبزوار که قصبه ٔ آن نیز موسوم به طبس است، طوائف عرب که در زمان عثمان به ریاست عبداﷲبن عامربن کریز به تسخیر خراسان آمدند، نخست دو محل موسوم به طبس را فتح کردند، آن دو محل را طبسان و طبسین گفتند.و این نام به صیغه ٔ تثنیه اشتهار یافت، و بعدها در بعض کتب تاریخ و جغرافیای عربی نیز به همین صیغه ضبطشد، لکن در فارسی جز بصیغه ٔ مفرد (طبس ) استعمال نمیشود. یاقوت در معجم البلدان در ذیل طبسان گوید: یکی از دو طبس را طبس تمر و دیگری را طبس عناب گویند. و در ذیل طبس گوید: آن دو طبس است یکی طبس مسینان و دیگری طبس گیلکی . ناصرخسرو در سفرنامه ٔ خود در آنجا که طبس تمر را وصف میکند، میگوید: و در آن وقت امیر آن شهر گیلکی ابن محمد بود، و بشمشیر گرفته بود. از این عبارت چنین مستفاد میشود که طبس گیلکی و طبس تمر یکی است، و آنرا نسبت بدین امیر طبس گیلکی گفته اند. (تعلیقات احمد بهمنیار بر تاریخ بیهق ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span>). نام قصبه ای در <span class=\"hlight\" dir=\"rtl\">٣١٨٠٠٠</span>گزی جویمند، و در <span class=\"hlight\" dir=\"rtl\">٤٧٧٠٠٠</span>گزی یزد که دارای پستخانه و تلگرافخانه میباشد. گُلشن امروزه که درسابق به نام طبس معروف بوده است از توابع خراسان و دارای معدن فیروزه است . این شهر مرکز حکومت تون (فردوس ) و طبس سابق، (گلشن امروزه ) در <span class=\"hlight\" dir=\"rtl\">٥٥٦</span> متر ارتفاع بین دو کوه واقع شده که شرقی آن موسوم به شتری و غربی آن موسوم به شوراب است، و در کنار جاده ٔ یزد به مشهدقرار گرفته، حاصل آن انقوزه، تنباکو، خرما، مرکبات و غلات است . آب و هوای طبس (گلشن ) برخلاف مشهور چندان گرم نیست و فقط بواسطه ٔ دوری از نقاط آباد و راههائی که از کویر گذشته به آن متصل میشود، به بدی مشهور شده است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٢٠٣</span>). آثار تاریخی آن عبارت است از مناره ٔ مدرسه و دو مناره ٔ دیگر متعلق به عهد سلجوقی . رجوع به تاریخ صنایع ایران شود. و صاحب قاموس الاعلام آرد: نام قصبه ای است در خطه ٔ ولایت خراسان از کشور ایران در <span class=\"hlight\" dir=\"rtl\">٣٨٥</span>هزارگزی جنوب غربی مشهد، در دامنه ٔ غربی کوهی بنام شوراپست به ارتفاع <span class=\"hlight\" dir=\"rtl\">٣١٠٠</span> گز و ارتفاع ناحیه ٔ مزبور <span class=\"hlight\" dir=\"rtl\">٥٦١</span> گز است . طبس در <span class=\"hlight\" dir=\"rtl\">٣٣</span> درجه و <span class=\"hlight\" dir=\"rtl\">٣٣</span> دقیقه و <span class=\"hlight\" dir=\"rtl\">٣٣</span> ثانیه عرض شمالی و <span class=\"hlight\" dir=\"rtl\">٥٤</span> درجه و <span class=\"hlight\" dir=\"rtl\">٣٦</span> دقیقه و <span class=\"hlight\" dir=\"rtl\">٥٤</span> ثانیه طول شرقی واقع است . جمعیت آن قریب <span class=\"hlight\" dir=\"rtl\">١٠٠٠٠</span> تن مرکب از ایرانی و عرب است و صحرای لوط اکثر اطرافش را فراگرفته و در نقطه ٔ میان خراسان و قهستان بر طریقی که از اصفهان، یزد، شیراز و کرمان بسوی خراسان امتداد یافته واقع است . عربها این جایگاه را باب خراسان خوانده اند، از این رو که بسال <span class=\"hlight\" dir=\"rtl\">٢٩</span> هَ . ق . درزمان عثمان نخستین نقطه ای که به دست مسلمین افتاد اینجا بود، و آن را طبسان نامیده اند، میاه جاریه و باغ ها و باغچه های فراوان دارد. در طرف مشرق قصبه در دامنه ٔ کوه و در مسافتی قریب به یک هزار و پانصد گزی باغها و ییلاقات دیده میشود. سور و خندقی گرداگرد قصبه را فراگرفته و قلعه ای هم در اینجا هست . محصولات آن عبارت است از: خرما، انگور، انار، شفتالو، گلابی، سیب، پرتقال و میوه های فراوان دیگر. صادراتش تنباکو، ماده ٔ طبی به نام انگزه «انغوزه » و محصولات کرم ابریشم میباشد. گوسفند و شتر بسیار دارد. هوایش بسیار گرم است و مسقط رأس بعضی از مشاهیر علما بوده است . (از قاموس الاعلام ترکی ). و در فرهنگ جغرافیائی ایران آمده است : دهستان مرکزی بخش طبس شهرستان فردوس از <span class=\"hlight\" dir=\"rtl\">٣٧</span> آبادی تشکیل یافته و مجموع نفوس آن در حدود <span class=\"hlight\" dir=\"rtl\">١١٥١٣</span> تن است .موقع آن جلگه و هوای آن گرمسیر است . آب کلیه ٔ قراء از قنوات تأمین میشود. محصول عمده ٔ آنجا غلات، برنج، خرما و مرکبات است . شغل اهالی زراعت و کسب می باشد. راه آن اتومبیل رو است . و نیز مؤلف آن آرد: طبس نام یکی از بخشهای سه گانه ٔ شهرستان فردوس محدود است از شمال به بخش بردسکن و کویر نمک، از خاور به بخش بشرویه و بخش بجستان و خوسف و از باختر و جنوب به کویر لوت . این بخش از دو طرف به کویر (کویر نمک و دشت لوط) محدود و دارای تابستان ممتد و طولانی و زمستان کوتاهی میباشد. قسمتهای جلگه ٔ آن گرم و سوزان و هوای آن مانند هوای منطقه ٔ مکران است . کوهستانها نسبتاً معتدل ؛بطوری که میوه های سردسیری در آنجا یافت میشود. بخش طبس در استان خراسان تنها محلی است که خرما و مرکبات بعمل می آید. این بخش از هفت دهستان بنام مرکزی، کریت، سنگردان دیهوک، جوخواه دستگردان، اصفهک که دارای <span class=\"hlight\" dir=\"rtl\">١٩١</span> آبادی بزرگ و کوچک است، تشکیل می یابد و مجموع نفوس آن در حدود <span class=\"hlight\" dir=\"rtl\">٢٧٧٨٦</span> تن است . آب کلیه ٔ قراء از قنوات تأمین میشود. محصول عمده ٔ آنجا خرما، غلات، ذرت، میوه جات و مرکبات است . در بعضی از نقاط آن برنج بعمل می آید. بخش طبس از نظر اداری تابع فرمانداری و ژاندارمری فردوس و از قسمت مالی تابع شهر گناباد است . و نیز آرد: قصبه ٔ مرکزی بخش طبس شهرستان فردوس که در <span class=\"hlight\" dir=\"rtl\">٢١٥</span>کیلومتری فردوس سر راه مشهد و یزد واقع است و مختصات جغرافیائی آن عبارت از طول <span class=\"hlight\" dir=\"rtl\">٥٩</span> درجه و <span class=\"hlight\" dir=\"rtl\">٥٦</span> دقیقه عرض <span class=\"hlight\" dir=\"rtl\">٣٦</span> درجه و <span class=\"hlight\" dir=\"rtl\">٣٣</span> دقیقه قسمتهای شمال خاوری و باختر آن کوهستانی قسمت جنوب آن جلگه به دشت لوط منتهی میشود. موقعیت آن جلگه و هوای گرمسیر است . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٨١١٤</span> تن است . شغل اهالی زراعت، کسب، تجارت، قالیچه بافی، چراغ سازی و گیوه بافی است . راه اتومبیل رو دارد. آب آن ازقنات است و بواسطه ٔ گرمی هوا محصول دیمی بعمل نمی آید، و چون آب کم دارند محصولی که به دست می آید کفایت چهار ماه آنها را نمیکند. ادارات دولتی بخشداری، دارائی، آمار ثبت اسناد، ژاندارمری، دبیرستان و دبستان دارد. از آثار باستانی مسجدی است و چندین باب دکاکین مختلف دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>). رجوع به تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٢٣٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٩٦</span>، <span class=\"hlight\" dir=\"rtl\">٣٦٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٨٥</span>، <span class=\"hlight\" dir=\"rtl\">٣٨٩</span>، تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span>، تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٥٥٦</span>، مجمل التواریخ گلستانه ص <span class=\"hlight\" dir=\"rtl\">١٠٨</span>، <span class=\"hlight\" dir=\"rtl\">١٠٩</span>، <span class=\"hlight\" dir=\"rtl\">١١٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٠٨</span>، <span class=\"hlight\" dir=\"rtl\">٣١٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٢٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٢٧</span>، <span class=\"hlight\" dir=\"rtl\">٣٢٨</span>، ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٩٠</span>، المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span>، فیه مافیه ص <span class=\"hlight\" dir=\"rtl\">٢٨٩</span>، تاریخ عصر حافظ ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥</span>، سفرنامه ٔ ناصرخسرو ص <span class=\"hlight\" dir=\"rtl\">١٤٠</span> و <span class=\"hlight\" dir=\"rtl\">١٤١</span>، تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٤٣٧</span> و <span class=\"hlight\" dir=\"rtl\">٥٤٣</span>، مجالس النفایس ص <span class=\"hlight\" dir=\"rtl\">٨٠</span> و تاریخ جهانگشای جوینی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧١</span> شود.<br /></font></div>'),
(175888, 'طبس تمر', '<span class=\"hlight\">طبس تمر.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ س ِ ت َ ]</font></b> (اِخ ) رجوع به طبس فردوس، طبسان و المعرب ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span> شود.<br /></font></div>'),
(175889, 'طبس عناب', '<span class=\"hlight\">طبس عناب .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ س ِ ع ُن ْ نا ]</font></b> (اِخ ) رجوع به طبس فردوس، طبسان و المعرب ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span> شود.<br /></font></div>'),
(175890, 'طبس مسینا', '<span class=\"hlight\">طبس مسینا.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ س ِ م َ ]</font></b> (اِخ ) نام یکی از دهستانهای بخش درمیان شهرستان بیرجند است که از<span class=\"hlight\" dir=\"rtl\">١٠٦</span> آبادی بزرگ و کوچک تشکیل یافته . مجموع نفوس آن در حدود <span class=\"hlight\" dir=\"rtl\">١٨٢٠٨</span> تن است . موقعیت دهستان جلگه و کوهستانی . آب مزروعی آن از قنوات تأمین میشود. هوای آن گرمسیر است . محصول عمده ٔ آن غلات و ارزن است . شغل اهالی زراعت، گله داری، قالیچه و کرباس بافی است . راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>). و نیز آرد: قصبه ٔ مرکز دهستان طبس مسینا بخش درمیان شهرستان بیرجند، واقع در <span class=\"hlight\" dir=\"rtl\">٣٢</span> هزارگزی جنوب خاوری درمیان، سر راه شوسه ٔ عمومی بیرجند به درج . جلگه، گرمسیر، دارای <span class=\"hlight\" dir=\"rtl\">١٥١٣</span> تن سکنه . آب آن از قنات . محصول آنجا غلات، شلغم و چغندر. شغل اهالی زراعت و مالداری . راه آن اتومبیل رو است . دبستان و پاسگاه ژاندارمری دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>). و رجوع به طبس مسینان شود.<br /></font></div>'),
(175891, 'طبس مسینان', '<span class=\"hlight\">طبس مسینان .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ س ِ م َ ]</font></b> (اِخ ) به خراسان اندر میان کوه و بیابان است و جائی بانعمت است . (حدود العالم ). طبس مسینان : از اقلیم سیم طولش از جزایر خالدات : صدنه، و عرض از خط استوا لج، شهری کوچک و گرمسیر است . و در او نخلیات فراوان بود و آبش از کاریز است .غلات این قصبه در هفتاد روز آب خورد و غلات مواضعی که در حوالی آن است در هفت روز آب خورد، و در آن ولایت چاهی بود که خاک آن مقدار دانه ٔ جاورس، هرکه بخوردی در حال بمردی، اما در این نزدیکی آن چاه را انباشته اند. و هم در آن ولایت چاهی است که در زمستان آب بسیاردر آن چاه میرود و در تابستان بیرون می آید، و بدان زراعت می کنند. و چاهی دیگر هست که هر وقت که در آن چاه نگاه میکنند بشکل ماهی مینماید. (نزهةالقلوب چ اروپا). رجوع به طبس، طبسین، طبسان و طبس مسینا شود.<br /></font></div>'),
(175892, 'طبس گیلکی', '<span class=\"hlight\">طبس گیلکی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ س ِ ل َ ]</font></b> (اِخ ) طبس تمر. شهری است کوچک و از اقلیم سوم است . طولش از جزائر خالدات، صب ط، وعرض از خط استوا لط، در هفت روزه ٔ راه یزد است . هوایش گرم است بغایت، خرما و ترنج و نارنج بسیار است، ودر خراسان غیر از آن جای دیگر نیست . و آبش از چشمه است، مقدار دو آسیاگردان آب باشد، حصاری محکم دارد، و در جوار آن علف نیست، چند پاره دیه از توابع آن است . (این شرح ذیل عنوان بلاد قهستان و نیمروز و زاولستان است ). (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>). و نیز ذیل عنوان بقاع مفازه مابین کرمان و سیستان گوید: طبس گیلکی از اقلیم سوم است، طولش از جزایر خالدات، صب لا، و عرض از خط استوا کج، ولایتی است و حاصلش غله و پنبه و خرما فراوان بود. (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٤٢</span>). و رجوع به طبس، طبسان، طبس تمر و تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">١٨١</span> شود.<br /></font></div>'),
(175893, 'طبسان', '<span class=\"hlight\">طبسان .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) دو طبس . قصبه ٔ ناحیه ای است بین نیشابور واصفهان که آنجا را به نام قهستان قاین نیز میخوانند، و آن عبارت است از دو شهر که هر دو را به نام طبس ذکر میکنند. یکی را طبس عناب و دیگر را طبس تمر میگویند... ابوالحسن علی بن محمد المدائنی گوید: نخستین شهری که از بلاد خراسان در آغاز فتوحات اسلام فتح شد طبسان بوده، و آن دو شهر را دو دروازه ٔ خراسان نام نهادند. فتح این شهر به دست عبداﷲبن بدیل بن ورقاء در روزگار خلافت عثمان بن عفان بسال <span class=\"hlight\" dir=\"rtl\">٢٩</span> هَ . ق . صورت گرفت، و پس از این فتح آهنگ تسخیر خراسان کردند و بدانجا داخل شدند، طبسان بین نیشابور، اصفهان و شیراز و کرمان واقع گردیده است، مالک بن الریب المازنی در این بیت از قصیده ٔ خود طبسان را منظور داشته است که گوید:<br />دعانی الهوی من اهل اودو صحبتی <br />بذی الطبسین فالتفت و رائیا.<br />... و از آنجا گروهی از دانشمندان برخاسته اند... (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧</span>). شهرستانی است به خراسان . (منتهی الارب ). و رجوع به کتاب المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span> شود.<br /></font></div>'),
(175894, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) تبسی . قهوه سینی . دوری ِ لعاب دار که روی آن فنجان قهوه گذارند. <BR><font color=\"Blue\">◄</font> نعلبکی . <BR><font color=\"Blue\">◄</font> بشقاب . ج، طباسی .<br /></font></div>'),
(175895, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) حسن بن محمدبن فیروزان طبسی، مکنی به ابوعلی مردی فقیه و از محدثان متقدم بوده است . وی از ابوالعباس اصم روایت دارد. (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175896, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) علی بن محمدبن زید حداد طبسی، مکنی به ابوالحسن . از محدثان متقدم بوده است . وی از ابن المعرتی روایت کرده است و ابوبکر محمدبن جعفر مزکی از وی روایت دارد. (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175897, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) عبدالرزاق بن محمد طبسی، مکنی به ابوبکر. سمعانی آرد: وی در نزد مشایخ حدیث قرائت میکرد و دیگران را بهره مند میساخت و قرائت وی صحیح بوده است . من صحیحین را به قرائت وی از امام محمدبن فضل فرا وی سماع کردم و به روایت از ابوالفضل محمدبن احمدبن ابوجعفر طبری حافظ که از وی در طبس سماع کرده بود حدیث نوشتم . و او در قرائت حدیث مهارتی داشته است . وی بسال <span class=\"hlight\" dir=\"rtl\">٥٣٠</span> هَ . ق . در نیشابور درگذشته و در کنجرود که آرامگاه امام الائمه ابن حزیمه است دفن شده است و من مدفن وی را زیارت کرده ام . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175898, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) محمدبن ابوبکر مقری طبسی . ابن ماکولا، کنیه ٔ او را ابوحاتم و نسبت او را لیثی آورده است . وی از اسماعیل بن فرات مقری روایت کرده و از محدثان متقدم بوده است . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175899, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[طَ ب َ ]</font></b> (اِخ ) محمدبن احمدبن ابوجعفر طبسی، مکنی به ابوالفضل . حافظ و صاحب تصانیف بسیار بوده . از حاکم ابوعبداﷲ حافظ و ابوطاهربن محمش زیادی و ابوالقاسم بن حبیب مفسر و ابوالحسن محمدبن قاسم فارسی و جز ایشان از اصحاب ابوالعباس اصم حدیث نوشته است و سفری بمرو کرده و در آنجا از ابوغانم کراعی و جز وی حدیث نوشته است . و گروهی از محدثان در نیشابور و هرات از او برای من حدیث روایت کرده اند از قبیل : ابوعبداﷲبن شاه شادیاخی در نیشابور و جنیدبن محمدبن علی قاینی در هرات . وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٤٨٠</span> هَ . ق . در طبس نیشابور (سبزوار) درگذشته است . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175900, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) محمدبن علی بن جعفر طبسی . ملقب به حاکم و مکنی به ابوعبداﷲ. از محدثان متقدم بشمار میرفته و وی از احمدبن ابوجعفر طبسی روایت کرده است و ابوعمرو محمد از او روایت دارد. (انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175901, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَب َ ]</font></b> (اِخ ) عبداﷲبن محمدبن ابراهیم طبسی، مکنی به ابومنصور. وی از قاضی ابوبکر جیری روایت دارد و از محدثان متقدم بوده است . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175902, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) شمس الدین طبسی دوبودند یکی اشعار خوب دارد و دیوانش مشهور و دیگری در حیات است انشا و نظم و نثر بی نظیر دارد و این ضعیف با او دوست است و به نظم و نثر این ضعیف را بکرات مشرف فرموده . (تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٨٢١</span>). و صاحب تذکره ٔ مرآةالخیال آرد: قاضی شمس الدین طبسی از صنادید علما و فضلای خراسان است و سلطان سعید بایسنقر اناراﷲ برهانه مربی اوست و از معاصران سلطان القضاة صدرالشریعه ٔ بخاری بوده و با هم صحبتها داشته اند و مدتی در حوزه ٔ درس وی بود و در آخر حال ندیم مجلس خواجه نظام که به وقت سلطان جلال الدین ملکشاه سلجوقی وزیر خراسان بوده، گردید و در مدح وی قصاید غراء گفته مورد صلات گرانمایه گشت . آورده اند چون شمس الدین طبسی آوازه ٔ فضل و کمال صدرالشریعه شنود بشوق ملازمت وی عزیمت بخارا کرد. روز اول که بمجلس وی درآمددید که صدرالشریعه قصیده ای را که در آن شب گفته بودبحضور اهل مجلس میخواند و هر یک بقوت طبع دخلی میکردند. شمس الدین سلام کرد و بگوشه ای نشست به استماع آن مشغول گردید. بعضی از ابیات قصیده ٔ مذکور این است :<br />برخیز که صبح است و شرابست و من و تو<br />آواز خروس سحری خاست ز هر سو<br />برخیز که برخاست پیاله به یکی پای <br />بنشین که نشسته ست صراحی به دو زانو<br />می نوش از آن پیش که معشوقه ٔ شب را<br />با صبح بگیرند و ببرند دو گیسو ...<br />در اثنای خواندن این ابیات صدرالشریعه در شمس نگریست و او را نیک متوجه دید، گفت : ای مرد غریب در شعر هیچ وقوف داری ؟ گفت : موزون را از ناموزون فرق توانم کرد، گفت : این شعر چطور است ؟ گفت : کلامی موزون است طلبه ٔ درس در او افتادند که چرا بهتر از این صفت نکردی ؟ گفت : اگر من بهتر از این بگویم شما چه میگوئید؟ گفتند: تو را در شعر مسلم داریم و الا بیازاریم . شمس مصالح نوشتن از آنها گرفت و بی تأمل آن قصیده را پنجاه بیت جواب نوشت . چون صدرالشریعه قوت طبع او را دید بر همه ٔ شاگردان مقدم نشاند و در تعظیم و احترام وی به اقصی الغایه پرداخت . این چند بیت از قصیده ٔ شمس الدین است :<br />از روی تو چون بردصبا طره به یکسو<br />فریاد برآورد شب غالیه گیسو<br />از شرم خط غالیه بوی تو فتاده ست <br />در وادی غم با جگر سوخته آهو<br />آن زلف شب آسا و رخ روزنمایت <br />چون عنبر و کافوربهم ساخته هر دو<br />جانا دل مجنون مرا چند برآری <br />زنجیرکشان تا بسر طاق دو ابرو<br />از زلف سیاه تو مگر شد گرهی باز<br />کز مشک برآورده فلک کعبه ٔ هر سو<br />گفتی که چو زر کار تو روزی سره گردد<br />آری همه امید من این است ولی کو؟<br />بستم در اندیشه که چیزی بگشاید<br />زین خانه ٔ شش گوشه و زین پرده ٔ نه تو ...<br /></font></div>'),
(175903, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) سهل بن ابراهیم طبسی، مکنی به ابوالحسین . وی از محدثان متقدم بوده و حسن بن محمد سکونی از او روایت دارد. (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175904, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) محمدبن محمد طبسی و مکنی به ابوجعفر. نزیل جرجان . وی کتاب المجروحین را از ابوحاتم محمدبن حبان بستی روایت کرده است و ابومسعود بحلی حافظ از وی روایت دارد. (انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span>).<br /></font></div>'),
(175905, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) حسن بن حسین بن حسن بن فضل طبسی، مکنی به ابوعلی . از محدثان متقدم بوده است و از ابوالحسن علی بن منصوربن عمربن تقی سمرقندی و او از ابوعیسی ترمذی روایت دارد. و ابوالحسن سمرقندی کتاب جامع ابوعیسی ترمذی را روایت کرده است . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175906, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) احمدبن محمدبن سهل طبسی فقیه بارع شافعی، مکنی به ابوالحسن . از متقدمان و از اصحاب مروزی بوده است . او در نیشابور از ابوبکر محمدبن اسحاق بن حزیمه و در عراق ازابومحمدبن صاعد سماع کرده است و در خانقاه نیشابور سکونت گزید و به تدریس و املای حدیث پرداخت، آنگاه به طبسین رفت و شنیدم وی بسال <span class=\"hlight\" dir=\"rtl\">٣٥٨</span> هَ . ق . درگذشته است . حاکم ابوعبداﷲ حافظ بدینسان ترجمه ٔ وی را آورده و هم گوید: و شنیده ام که ابوالحسن را شرحی بر مذهب شافعی رحمةاﷲ بوده که آنرا در هزار جزو با خطی بسیار دقیق تألیف کرده است . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175907, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) احمدبن محمدبن ابراهیم طبسی تاجر، مکنی به ابونصر نزیل نیشابور. حاکم ابوعبداﷲ حافظ گوید: وی از ابوقریش محمدبن جمعةبن خلف قهستانی و جزوی روایت کرده است و گمان میکنم در نیشابور درگذشته است . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> الف ).<br /></font></div>'),
(175908, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) احمدبن سهل بن بحر طبسی فقیه، مکنی به ابوالحسین . او راست : تصانیفی در لغت . وی از یحیی بن صاعد و ابن حزیمه روایت دارد و از محدثان متقدم بشمار میرفته است . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175909, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) احمدبن ابوجعفر طبسی از محدثان متقدم بوده و از محمدبن حبان سماع کرده است . (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175910, 'طبسی', '<span class=\"hlight\">طبسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ص نسبی ) منسوب به طبس که شهری است بین نیشابور و اصفهان و کرمان . (سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ).<br /></font></div>'),
(175911, 'طبسیل', '<span class=\"hlight\">طبسیل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) قهوه سینی . سینی . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span>).<br /></font></div>'),
(175912, 'طبسین', '<span class=\"hlight\">طبسین .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ س َ ]</font></b> (اِخ ) شهری است بخراسان گرمسیر و اندر وی خرماست . و آب ایشان از کاریز است، و اندر میان بیابان است . (حدود العالم ). رجوع به طبسان و عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩٩</span> و تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٢٦</span>، <span class=\"hlight\" dir=\"rtl\">٢١٩</span> شود.<br /></font></div>'),
(175913, 'طبسین', '<span class=\"hlight\">طبسین .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) دهی از دهستان نهبندان بخش شوسف شهرستان بیرجند، واقع در <span class=\"hlight\" dir=\"rtl\">١٣٠</span>هزارگزی جنوب خاوری شوسف و <span class=\"hlight\" dir=\"rtl\">٧</span>هزارگزی شمال شوسه ٔ عمومی مشهد به زاهدان . دامنه، گرمسیر، دارای <span class=\"hlight\" dir=\"rtl\">٩٦</span> تن سکنه . شغل اهالی زراعت و مالداری . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175914, 'طبش', '<span class=\"hlight\">طبش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) مردم . (منتهی الارب ) (آنندراج ). طمش مثله و منه : ما فی الطبش مثله . و ما ادری ای ّالطمش هو؛ ای ای الناس هو و کذا ای الطبش هو. (منتهی الارب ).<br /></font></div>'),
(175915, 'طبشقوران', '<span class=\"hlight\">طبشقوران .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) از طسوج لنجرود است . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>). و در همان کتاب ص <span class=\"hlight\" dir=\"rtl\">٦٥</span> آمده است : هیثم از عمر کسری روایت کند که او گفت که این دیه قومی از اهل طبشین بنا کرده اند و نام آن طبشگران بوده است، پس معرب گردانیدند و گفتند طبشقوران .<br /></font></div>'),
(175916, 'طبشه', '<span class=\"hlight\">طبشه .</span> <font color=\"DarkGreen\"><b>[ طَ ش َ ]</font></b> (ع اِ) رجوع به طبشی شود.<br /></font></div>'),
(175917, 'طبشکری', '<span class=\"hlight\">طبشکری .</span> <font color=\"DarkGreen\"><b>[ طُ ب َ ک َ]</font></b> (اِخ ) حمداﷲ مستوفی این موضع را یکی از دهات خرقان از تومان همدان میشمارد. (نزهةالقلوب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>).<br /></font></div>'),
(175918, 'طبشی', '<span class=\"hlight\">طبشی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) جام چوبین . طبشه . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span>).<br /></font></div>'),
(175919, 'طبطاب', '<span class=\"hlight\">طبطاب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) آن چوب که گوی بر آن براندازند. (مهذب الاسماء). چوگانی است که سر آن مانند کفچه سازند و گوی در آن نهند و بر هوا افکنند، چون به فرودآمدن رسد باز سر طبطاب بر او زنند، همچنین نگذارند که بر زمین آید تا از هال نگذارند، و به فارسی آن را تخته ٔ گوی بازی گویند. (غیاث اللغات ). تخته ٔ گوی بازی . (منتهی الارب ). دو شاخ . دو شاخ گوی بازی . (زمخشری ). چوبی است پهن که بدان گوی بازند. (منتخب اللغات ) (بحر الجواهر). چوگان . پهنه . (فرهنگ اسدی ) (حاشیه ٔ فرهنگ اسدی نخجوانی ). گوی پهنه . گوی مهین . (بحر الجواهر) <span class=\"hlight\">:</span> <br />ببانگ نخستین از آن خواب خوش <br />بجستیم چون گو ز طبطابها.<br /> <font color=\"Red\">منوچهری .</font><br />در سواری و چوگان و طبطاب یگانه ٔ روزگار بود. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٢٤</span>).<br />ز بیم تو تنشان زخم خورده چون نیزه ست <br />ز سهم تو دلشان همچو گوی در طبطاب .<br /> <font color=\"Red\">مسعودسعد.</font><br />سرگشته چو گویم که سر و پای ندارم <br />خسته به گه خرط و شکسته گه طبطاب .<br /> <font color=\"Red\">خاقانی .</font><br />کوس غارت زد فراقت گرد شهرستان دل <br />شحنه ٔ عشقت سرای عقل در طبطاب داشت .<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> مرغی است کلان گوش . (منتهی الارب ). مرغی است که گوش دراز دارد. (منتخب اللغات ). نام طائری است که آنرا دو گوش بزرگ است . (فهرست مخزن الادویه ).<br /></font></div>'),
(175920, 'طبطابة', '<span class=\"hlight\">طبطابة.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ع اِ) یک تخته ٔ گوی بازی . (منتهی الارب ). طبطاب . رجوع به طبطاب شود.<br /></font></div>'),
(175921, 'طبطبة', '<span class=\"hlight\">طبطبة.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ب َ ]</font></b> (ع اِ) بانگ وآواز تلاطم سیل . (منتهی الارب ). آواز آب . آواز موج زدن سیل . (منتخب اللغات ). بانگ آب . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> حکایت بانگ سیل . <BR><font color=\"Blue\">◄</font> آواز پای وقت دویدن . <BR><font color=\"Blue\">◄</font> آواز تازیانه . (منتهی الارب ).<br /></font></div>'),
(175922, 'طبطبة', '<span class=\"hlight\">طبطبة.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ب َ ]</font></b> (ع مص ) آواز کردن . (منتهی الارب ).<br /></font></div>'),
(175923, 'طبطبه', '<span class=\"hlight\">طبطبه .</span> <font color=\"DarkGreen\"><b>[ طَ طَ ب َ ]</font></b> (ع اِمص ) (الطب ...) من العیوب الخلقیة فی الفرس، و هو ان تسترجی جحفلته السفلی فاذا سار حرکها و طبطبها، کالبعیر الاهدل - و ان یکون فی حنکه شامة سوداء و سائر فمه ابیض . (صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥</span>).<br /></font></div>'),
(175924, 'طبطبیة', '<span class=\"hlight\">طبطبیة.</span> <font color=\"DarkGreen\"><b>[ طَ طَ بی ی َ ]</font></b> (ع اِ) درة. (منتهی الارب ).<br /></font></div>'),
(175925, 'طبطر', '<span class=\"hlight\">طبطر.</span><font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (ع اِ) غلیظ. ج، طباطرة. (تاج العروس ).<br /></font></div>'),
(175926, 'طبطر', '<span class=\"hlight\">طبطر.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (اِ) مرغ آبی است از اقسام اوز. (فهرست مخزن الادویه ). ظاهراً تحریف طبطو مصحف طیطو است .<br /></font></div>'),
(175927, 'طبطو', '<span class=\"hlight\">طبطو.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) نام نوعی از مرغابی باشد. (برهان ). مصحف طیطو. محمد قزوینی نوشته اند: گویا مصحف طیطو باشد. رجوع به طیطو شود.<br /></font></div>'),
(175928, 'طبع', '<span class=\"hlight\">طبع.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) نام جوئی است و در شعر لبید آمده است . (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨</span>).<br /></font></div>'),
(175929, 'طبع', '<span class=\"hlight\">طبع.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ع اِ) گناه . جناح . ذنب . بزه . <BR><font color=\"Blue\">◄</font> عیب . آک . آهو. هر قبیحه ای که باشد. نقیصه . <BR><font color=\"Blue\">◄</font> زنگ . (منتهی الارب ). چرک . ریم . زنگار. (ربنجنی ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> جوی خرد. ج، اطباع . (مهذب الاسماء).<br /></font></div>'),
(175930, 'طبع', '<span class=\"hlight\">طبع.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ع مص ) زنگ گرفتن شمشیر و جز آن . (منتهی الارب ). زنگار گرفتن . شوخگن شدن . (تاج المصادر). <BR><font color=\"Blue\">◄</font> ریمناک شدن مرد. (منتهی الارب ). چرکین شدن . آلوده شدن بعار. (تاج المصادر). <BR><font color=\"Blue\">◄</font> کاهل و دون همت گردیدن مرد. منه : فلان یطبع؛ یعنی او را در مکارم امور نفاذی نیست ؛ بلکه در رذائل امور منهمک و مستغرق است، مانند: شمشیر زنگ آلوده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کاهل شدن . (تاج المصادر).<br /></font></div>'),
(175931, 'طبع', '<span class=\"hlight\">طبع.</span> <font color=\"DarkGreen\"><b>[ طَ ب ِ ]</font></b> (ع ص ) هو طبعٌ طمعٌ؛ او زشتخوی ناکس طبیعت ریمناک است که شرم ندارد از زشتی وناکسی . (منتهی الارب ). دون همت . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> تیغ زنگارگرفته . (مهذب الاسماء) (اقرب الموارد) <span class=\"hlight\">:</span> چاره ای نیست از تقریر شمه ای از آنچ طَبعِ طَبِعِ او بر آن مجبول است . (جهانگشای جوینی ).<br /></font></div>'),
(175932, 'طبع', '<span class=\"hlight\">طبع.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) مهر کردن بر نامه و جز آن . (منتهی الارب ). مهر کردن . (ترجمان علامه ٔ جرجانی ص <span class=\"hlight\" dir=\"rtl\">٦٧</span>). <BR><font color=\"Blue\">◄</font> نقش کردن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> ساختن شمشیر. صاحب منتهی الارب در مورد این معنی عبارتی آورده بدین سیاق : طبع السیف من الطین، و کذا طبع الدرهم من الطین، و طبع الجرة من الطین . دراداةالفضلا گوید: الطبع؛ مهر کردن . درم زدن . شمشیر زدن . مؤلف قطر المحیط آورده : طبع السیف ؛ عمله و صباغه و الدرهم نقشه و سکه و الجرة من الطین عملها. بنابراین لفظ طبع در معنی مصدری، بمعانی، ساختن ِ شمشیر و سکه زدن و ساختن مطلق نیز آمده مشروط بر آنکه قرینه (یا مفعول آن ) ذکر شود. طبع، شمشیر بزدن . (زوزنی ). سبوی کردن ؛ طبع الجرة من الطین . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> طبع الدلو؛ پر ساختن دلو. <BR><font color=\"Blue\">◄</font> طبع قفاه ؛ از دست زدن پس گردن کسی را. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> طبع اﷲ علی قلبه ؛ پرده انداخت بر دل وی . مهر کرد بر وی . رین . ختم . در کلیات ابوالبقاء آمده : قال بعضهم الطبع و الختم و الاکنة و الاقفال، الفاظ مترادفة بمعنی واحد. <BR><font color=\"Blue\">◄</font> سرشته شدن بر چیزی . طبع علی الشی ٔ. بصیغه ٔمجهول . <BR><font color=\"Blue\">◄</font> زشت و ریمناک گردیدن . طبع فلان، بصیغه ٔ مجهول . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> در تداول عوام، چاپ کردن . رجوع به طبع کردن شود.<br /></font></div>'),
(175933, 'طبع', '<span class=\"hlight\">طبع.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) جای پست فروخوردن آب . <BR><font color=\"Blue\">◄</font> پری . چنانکه کیل و مشک و جوی و نهر. <BR><font color=\"Blue\">◄</font> زنگ . ریمناکی . ج، اطباع . <BR><font color=\"Blue\">◄</font> ریمناکی سخت از زنگ . <BR><font color=\"Blue\">◄</font> زشتی . عیب . (منتهی الارب ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175934, 'طبع', '<span class=\"hlight\">طبع.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) سرشت که مردم بر آن آفریده شده . ج، طباع . (منتهی الارب ). خوی . (دستور اللغة ادیب نطنزی ). طبیعت . (مهذب الاسماء). آخشیج . (فرهنگ خطی اسدی متعلق به نخجوانی ). سرشت . (مقدمة الادب زمخشری ). خلقت . فطرت . طینت . خمیره . جبلت . نهاد. آب و گل . منش .(نصاب ). گوهر. گهر. غریزه . آن چیزی که آدمی بر آن آفریده شده است . توس . نحاس . آنچه بر انسان بغیر اراده وارد آید و بقولی جبلتی است که انسان بر آن آفریده شده است . (از تعریفات جرجانی ) <span class=\"hlight\">:</span> و این خرخیزیان مردمانیند که طبع ددگان دارند و درشت صورتند و کم موی و بیدادکار و کم رحمت و مبارز. (حدود العالم ).<br />خواجه یکی غلامک رس دارد<br />کز ناگوارد خانه چو تس دارد<br />ایدون به طبع کیر خورد گوئی <br />چون ماکیان بکون در، کس دارد.<br /> <font color=\"Red\">منجیک .</font><br />فغان من همه زآن زلف بی تکلف اوست <br />فکنده طبع بر او بر هزار گونه عقد.<br /> <font color=\"Red\">منجیک .</font><br />ملول مردم کالوس و بی محل باشند<br />مکن نگارا این طبع و خوی را بگذار.<br /> <font color=\"Red\">ابوالمؤید بلخی .</font><br />ای طبع سازوار چه کردم ترا چه بود<br />با من همی نسازی و دائم همی ژکی .<br /> <font color=\"Red\">کسائی .</font><br />اگر مرگ دارد چنین طبع گرگ <br />پر از می یکی جام خواهم بزرگ .<br /> <font color=\"Red\">فردوسی .</font><br />چنان سیر گشتم ز شاه اردوان <br />که از پیرزن طبع مرد جوان .<br /> <font color=\"Red\">فردوسی .</font><br />در لئیمان به طبع ممتازی <br />در خسیسان بفعل بی جفتی <br />منظرت به ز مخبر است پدید<br />که به تن زفتی و به دل زُفتی .<br /> <font color=\"Red\">علی قرط اندکانی .</font><br />وی <font color=\"DarkGreen\"><b>[سلطان محمود]</font></b> آن را که ساختند خریداری کرد، بطبع بشریت که نتوانست دید کسی را که جای او را سزاوار باشد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢١٤</span>). طاعنان زودزود زبان فرا این پادشاه بزرگ مسعود نکنند و سخن بحق گویند که طبع پادشاهان واحوال و عادت ایشان نه چون دیگران است . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٤٨</span>). بوبکر هم فاضل و ادیب و نیکوخط و مدتی به دیوان ما بماند، طبعش میل به کربزی داشت . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>). طبع این خداوند دیگر است . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٠٧</span>). پادشاهان محتشم را حث باید کرد بر بناء معالی هرچند که اندر طبع ایشان سرشته است . (تاریخ بیهقی چ ادیب ). طبع بشریت است ... که دشوار آید ایشان را دیدن کسی که مستحق جایگاه ایشان باشند. (تاریخ بیهقی چ ادیب ).<br />ز هولش دل و طبع روباه گیرد<br />دل شیر جنگی و طبع غضنفر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />سوی تو ضحاک بدهنراز طبع<br />بهتر و عادلتر از فریدون شد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />تاش همی جستم او بطبع همی جست <br />از من و من زو کنون به طبع جهانم .<br /><font color=\"Red\">ناصرخسرو.</font><br />چون عسلی شد رخانت زرد چرا<br />با غزل و می بطبع چون عسلی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />طبع دلجو خوشتر از گنج زر و کان گهر<br />خوی نیکو بهتر از شاهی و ملک بیکران .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و بسبب آنک پدرش طبع سپاهیان داشت وعالم زیرک نبود، چون انوشروان دید کی او در جوال مزدک رفته بود برفور هیچ نمیتوانست گفتن تا گستاخ تر شود. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٨٦</span>).<br />ز خندان لاله شد گیتی چوخلق خسرو مشرق <br />ز گریان ابرشد دنیا چو طبع خسرو دنیا.<br /> <font color=\"Red\">مسعودسعد.</font><br />خواجه طاهر تو طبع من دانی <br />که نه جنس فلان و بهمانم .<br /> <font color=\"Red\">مسعودسعد.</font><br />ای شاه می ستان بنشاط و طرب که طبع<br />هر خارسان که هست همی گلستان کند.<br /> <font color=\"Red\">مسعودسعد.</font><br />گمان مبر که مگر طبعهای مختلفند<br />گمان مبر که همه طبعها برنجانند .<br /> <font color=\"Red\">مسعودسعد.</font><br />اگر او را به طبع مادرزاد<br />دیده وگوش کور و کر باشد.<br /> <font color=\"Red\">مسعودسعد.</font><br />این دل و طبع رنج چند کشد<br />نه دل و طبع سنگ و سندان است .<br /> <font color=\"Red\">مسعودسعد.</font><br />چون طبع و خلق او گل و سوسن <br />در هیچ باغ و هیچ چمن نیست .<br /> <font color=\"Red\">مسعودسعد.</font><br />ای روشنی طبع تو بر من بلا شدی .<br /> <font color=\"Red\">مسعودسعد.</font><br />هنرش را ز رأی تربیت است <br />دولتش زآن بطبع مأمور است .<br /> <font color=\"Red\">مسعودسعد.</font><br />چو چرخ مرکز جاه ترا شتاب و سکون <br />چو طبع آتش رای ترا سنا و ضیا.<br /> <font color=\"Red\">مسعودسعد.</font><br />ای طبع تو چو بحر و ز بحرت مرا گهر<br />ای رای تو چو مهر و ز مهرت مرا ضیا.<br /> <font color=\"Red\">مسعودسعد.</font><br />بر آنچه ستوده ٔ عقل و پسندیده ٔ طبع است اقبال کنم . (کلیله و دمنه ). که طبع را بسخن منظوم میل بیش باشد. (کلیله و دمنه ). بلکه فوائد آنرا به آهستگی در طبع جای دهد. (کلیله و دمنه ). این ... خصلت از نتایج طبع زنان است . (کلیله و دمنه ).<br />نبینی طبع را طبعی چو کرد انصاف رخ پنهان <br />نیابی دیو را دیوی چو کرد اخلاص رخ پیدا.<br /> <font color=\"Red\">سنائی .</font><br />دوست خواهی که تا بماند دوست <br />آن سخن گو که طبع و عادت اوست .<br /> <font color=\"Red\">سنائی .</font><br />بجنب لفظ تو ای لفظ تو بدیع و غریب <br />بجای طبع تو ای طبع تو جواد و کریم .<br /> <font color=\"Red\">ادیب صابر.</font><br />باشدچو طبع مهر من اندر هوای تو<br />چون تاب گیرد از حرکات خور آینه .<br /> <font color=\"Red\">خاقانی .</font><br />از بوسه سخن نگویم ایرا<br />طبع تو محال برنتابد.<br /> <font color=\"Red\">خاقانی .</font><br />هر روز هزار تازیانه <br />بر طبع طفیل سان شکستم .<br /> <font color=\"Red\">خاقانی .</font><br />چون طبع طفیل آرزو بود<br />حالیش به امتحان شکستم .<br /> <font color=\"Red\">خاقانی .</font><br />خود دل و طبع او ز سیم و شکر<br />کآن طمغاج و باغ شوشتر است .<br /> <font color=\"Red\">خاقانی .</font><br />مساز عیش که نامردمیست طبع جهان <br />مخور کرفس که پُرکژدم است بوم و سرا.<br /> <font color=\"Red\">خاقانی .</font><br />طبع که با عقل به دلالگی است <br />منتظر نقد چهل سالگی است .<br /> <font color=\"Red\">نظامی .</font><br />توسنی طبع چو رامت شود<br />سکه ٔ اخلاص بنامت شود.<br /> <font color=\"Red\">نظامی .</font><br />گرچه بسی طبع ظریفی کند<br />با تو بتنها چه حریفی کند.<br /> <font color=\"Red\">نظامی .</font><br />چرب زبان گشتم از آن فربهی <br />طبع ز شادی پر و از غم تهی .<br /> <font color=\"Red\">نظامی .</font><br />درویشی را شنیدم که در آتش فاقه میسوخت ... کسی گفتش که فلان در این شهر طبعی کریم دارد. (گلستان سعدی ).<br />خبر شد به روم از جوانمرد طی <br />هزار آفرین کرد بر طبع وی .<br /> <font color=\"Red\">سعدی .</font><br />سعدی آن طبع ندارد که ز خوی تو برنجد<br />خوش بود هرچه تو گوئی و شکر هرچه تو باری .<br /> <font color=\"Red\">سعدی (طیبات ).</font><br />غریب از خوی مطبوعت که روی از بندگان پوشی <br />بدیع از طبع موزونت که در بر دوستان بندی .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> خاصیت . مزاج . ترکیب . طبیعت . ج، طباع . اطباع : طبع سودائی ؛ مزاج سودائی . طبع صفراوی ؛ مزاج صفراوی . طبع بلغمی ؛ مزاج بلغمی . طبع دموی ؛ مزاج دموی . صاحب کشاف آرد: الطبع: یطلق تارة مرادفاً للطباع . و تارة مرادفاً للطبیعة، کما عرفت، و یؤید الثانی ما فی مشکوةالانوار من ان الطبع عبارة عن صفة مرکوزة فی الاجسام حالة فیها و هی مظلمة اذ لیس لها معرفة و ادراک، و لا خیر لها من نفسها، و لا مما یصدر منها و لیس له نورٌ یدرک بالبصر الظاهر - انتهی . و طبع الماء عند الفقهاء، هو الرقة و السیلان، و قیل هو کونه سیالا مُرطباً مسکناً للعطش و یرد علی کلا القولین ان ماء بعض الفواکه ایضاً موصوف بالصفات المذکورة، فلذا قال البعض : طبع الماء هو الرقة و السیلان و دفع العطش و الانبات . هکذا فی البیرجندی و الچلپی حاشیة شرح الوقایه . (کشاف اصطلاحات الفنون ) <span class=\"hlight\">:</span> <br />بطعم شکر بودم بطبع مازریون <br />چنان شدم که ندانم ترنگبین از ماز.<br /> <font color=\"Red\">مجلدی (از حاشیه ٔ فرهنگ اسدی نخجوانی ).</font><br />می ده چهارساغر تا خوشگوار باشد<br />زیرا که طبع عالم هم بر چهار باشد.<br /> <font color=\"Red\">منوچهری .</font><br />طبع خرما گیر تا مردم بتو رغبت کنند<br />کی خورد مردم ترا تا بیمزه چون مازوی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گفتم که حد طبع چه چیز است در صفت <br />گفتا که سرد و گرم بود طبع و خشک و تر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />هر کسی را ز جهان بهره ٔ او پیداست <br />گرچه هر چیز ازین طبع چهار آید.<br /> <font color=\"Red\">ناصرخسرو.</font><br />طبع تشرین بنماند به مه نیسان <br />گرچه در سال یکی باشد با تشرین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عالم چو یکی رونده دریا<br />سیاره سفینه، طبع لنگر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />همیشه تا بجهان زیر این دوازده برج <br />بود جهت شش و اقلیم هفت و طبع چهار.<br /> <font color=\"Red\">مسعودسعد.</font><br />گل مورد خندان دو دیده بگشاده <br />دو طبع مختلفش داده فعل باد و سحاب .<br /> <font color=\"Red\">مسعودسعد.</font><br />موافقند به طبع و مزاج و روح و بدن <br />مخالفند به ذات و به گوهر و آتش .<br /> <font color=\"Red\">مسعودسعد.</font><br />ماننده ٔ خور است همیشه بطبع گرم <br />آری شگفت نیست بود گرم طبع خور.<br /> <font color=\"Red\">مسعودسعد.</font><br />امام و عالم مطلق ترا شناختمی <br />اگر شناختمی طبع جهل و اصل جفا.<br /> <font color=\"Red\">مسعودسعد.</font><br />چون طبع اجل سودا تیز کرد... حیلت سود ندارد. (کلیله و دمنه ).<br />اسیر طبع مخالف مدار جان و خرد<br />زبون چار زبانی مکن دو حور لقا.<br /> <font color=\"Red\">خاقانی .</font><br />بطبع آهن بینم صفات مردم را<br />از آن گریزان از هر کسی پری وارم .<br /> <font color=\"Red\">خاقانی .</font><br />طبع چو خاقانیی بسته ٔ سودا مدار<br />بشکن صفرای او زآن لب چون ناردان .<br /> <font color=\"Red\">خاقانی .</font><br />حرام آمد علف تاراج کردن <br />به دارو طبع را محتاج کردن .<br /> <font color=\"Red\">نظامی .</font><br />وگر آبی بماند در هوا دیر<br />بمیل طبع هم راجع شود زیر.<br /> <font color=\"Red\">نظامی .</font><br />باران که در لطافت طبعش خلاف نیست <br />در باغ لاله روید و در شوره زار خس .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> رغبت . میل <span class=\"hlight\">:</span> <br />در آب و آتش جان و روان دهند بطبع<br />بلی کنند همه افتخار از آتش و آب .<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> (اصطلاح تصوف ) ماسبق به العلم فی حق کل شخص . (در پایان تعریفات جرجانی ). <BR><font color=\"Blue\">◄</font> قریحه ٔ شعری . استعداد شعر سرودن . ذوق شعر گفتن <span class=\"hlight\">:</span> <br />چو خوان نهاد نهاری فرونهد پیشت <br />چو طبع خویش بخامی چو یشمه بی چربو.<br /> <font color=\"Red\">منجیک .</font><br />سخن چون بر اینگونه بایدت گفت <br />مگوی و مکن رنج با طبع جفت .<br /> <font color=\"Red\">فردوسی .</font><br />اگر بخت یکباره یاری کند<br />بر این طبع من کامکاری کند.<br /> <font color=\"Red\">فردوسی .</font><br />چو طبعی نداری چو آب روان <br />مبر دست زی نامه ٔ خسروان .<br /> <font color=\"Red\">فردوسی .</font><br />دهد ایزد مرا در نظم شعرت <br />دل بشار و طبع ابن مقبل .<br /> <font color=\"Red\">منوچهری .</font><br />اگر این فاضل از روزگار ستمکار داد یابد و پادشاهی طبع او را مدد دهد... در سخن موئی به دو نیم شکافد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٨١</span>).<br />من اکنون ز طبعم بهار آورم <br />مر این شاخ نو را به بار آورم .<br /> <font color=\"Red\">اسدی .</font><br />گهر یابی همی از حجت اندر طبع خواننده <br />اگر هرگز گهر یابد به شعراندر کسی مدغم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />طبع تو روز روشن و ابیات من چو شب <br />نظم تو در پرثمن و شعر من سفال .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دبیران اسیرند پیش سخن <br />سخن پیش طبعم بطبع است اسیر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چو در و گوهر از سنگ و از صدف دائم <br />ز طبع و خاطر از نظم و نثر دارم راز.<br /> <font color=\"Red\">مسعودسعد.</font><br />بهیچوقت مرا نظم و نثر کم نشود<br />که نظم و نثرم در است و طبع من دریاست .<br /> <font color=\"Red\">مسعودسعد.</font><br />دوری طبعتو نخواهد برد<br />ز آتش طبع من فروغ و شرر.<br /> <font color=\"Red\">مسعودسعد.</font><br />لفظ گوهربار تو پرگوهرم کرده ست طبع<br />لفظ شکربار تو پرشکرم کرده ست کام .<br /> <font color=\"Red\">امیرمعزی .</font><br />دریغ دفتر اشعار ناخوش و سردم <br />که بد نتیجه ٔ طبع فرخج مردارم .<br /> <font color=\"Red\">سوزنی .</font><br />از نظم و نثر خاطر خاقانی <br />طبع کشاجم ازدر لک باشد.<br /> <font color=\"Red\">خاقانی .</font><br />مداح توست و مخلص توست و مرید توست <br />تا طبع ما و سینه ٔ ما و روان ماست .<br /> <font color=\"Red\">خاقانی .</font><br />هرچه من آورم ز طبع آبحیات در دهن <br />تف دل آتش آورد در دهنم دریغ من .<br /> <font color=\"Red\">خاقانی .</font><br />گر در دل تو یافت توانم نشان خویش <br />طبعم شود ز لطف چو از گوهر آینه .<br /> <font color=\"Red\">خاقانی .</font><br />بکر طبعش نقاب هندی داشت <br />کآب حسن از نقاب میچکدش .<br /> <font color=\"Red\">خاقانی .</font><br />مریم طبعش نکاح یوسف وصف تو بست <br />مریمی با حسن یوسف نی چو یوسف کم بها.<br /> <font color=\"Red\">خاقانی .</font><br />شو نمک بر آتش افکن کز سر خوان بهشت <br />خوش نمک در طبع و شکر در زبان آورده ام .<br /> <font color=\"Red\">خاقانی .</font><br />نسبت فرزندی ابیات چست <br />بر پدر طبع بدارد درست .<br /> <font color=\"Red\">نظامی .</font><br />ز طبع تر گشاده چشمه ٔ نوش <br />به زهد خشک بسته بار بر دوش .<br /> <font color=\"Red\">نظامی .</font><br />خیز و شب منتظران روز کن <br />طبع نظامی طرب افروز کن .<br /> <font color=\"Red\">نظامی .</font><br />طبعنظامی که بدو چون گل است <br />بر گل او نغزنوا بلبل است .<br /> <font color=\"Red\">نظامی .</font><br />فهم سخن چون نکند مستمع<br />قوت طبع از متکلم مجوی .<br /> <font color=\"Red\">سعدی .</font><br />مرا طبع ازین نوع خواهان نبود<br />سر مدحت پادشاهان نبود.<br /> <font color=\"Red\">سعدی .</font><br />من ز طبع همچو آب خویش اندر آتشم <br />در قفس از چیست بلبل از زبان خویشتن .<br /> <font color=\"Red\">ابن یمین .</font><br />کنار آب رکناباد و طبع شعر و یاری خوش <br />معاشر دلبری شیرین و ساقی گلعذاری خوش .<br /> <font color=\"Red\">حافظ.</font><br />حافظ ار سیم و زرت نیست برو شاکر باش <br />چه به از دولت لطف سخن و طبع سلیم .<br /> <font color=\"Red\">حافظ.</font><br />صاحب آنندراج آرد: بلند و نکته سنج و قادر و سخن آفرین و سخن ساز و سخن طراز و سخنگوی و سخن سنج و سخن سرای و سخن گستر و روان و لطیف و سلیم و جادوفن و معنی دان و معنی باف و معنی آفرین و موزون ... و شکرگستراز صفات طبع و عروس از تشبیهات اوست <span class=\"hlight\">:</span> <br />مرا بشعر مجرد مدان از آنکه جز این <br />عروس طبعمرا هست چند گونه جهاز.<br /> <font color=\"Red\">کمال اسماعیل .</font><BR><font color=\"HotPink\">♦ </font>انتهی . رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">٢٣٨</span> شود.<br /> <BR><font color=\"Blue\">◄</font> مثل . مانند. <BR><font color=\"Blue\">◄</font> صنیع. ساخت . <BR><font color=\"Blue\">◄</font> هیئت چیزی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> ذات <span class=\"hlight\">:</span> این بوسهل ... شرارت و زعارت در طبع وی مؤکد شده . (تاریخ بیهقی ). کلمه ٔطبع بصورت ترکیب های فارسی بمعانی گوناگون آمده است، از قبیل : آزادطبع، آتش طبع، آینه طبع، چمن طبع، بهارطبع، زهره طبع، سبک طبع، دون طبع و غیره . رجوع به مجموعه ٔمترادفات ص <span class=\"hlight\" dir=\"rtl\">٢٣٨</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آدمی طبع</span> ؛ آنکه خوی انسانی دارد <span class=\"hlight\">:</span> <br />عالم طفلی و خوی حیوانی بگذاشت <br />آدمی طبع و ملکخوی و پری سیما شد.<br /> <font color=\"Red\">سعدی (طیبات ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">باب ِ طبع</span> ؛ باب ِ طبعِ کسی، موافق میل او.بدلخواه کسی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بدطبع</span> ؛ آنکه طبیعت زشت دارد. بدخوی . بدسرشت <span class=\"hlight\">:</span> بدخوی و تلخ گفتار، مردم آزار و بدطبع و ناپرهیزگار. (گلستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بوزینه طبع</span> ؛ بدخوی . ستیزه جوی . بدمنش . <span class=\"hlight\">:</span> <br />کافران اندرمری بوزینه طبع<br />آفتی آمد درون سینه طبع.<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بی طبع</span> ؛ بی ذوق . بی سلیقه <span class=\"hlight\">:</span> <br />عجب از طبع هوسناک منت می آید<br />من خود از مردم بیطبع عجب می آیم .<br /> <font color=\"Red\">سعدی (خواتیم ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">تاریک طبع</span> ؛ آنکه طبیعت و خوی زشت دارد. بدخوی . سیاه دل <span class=\"hlight\">:</span> <br />ناکسان را فراستی است عظیم <br />گرچه تاریک طبع و بدخویند.<br /> <font color=\"Red\">سعدی (صاحبیه ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">جهان طبع</span> ؛ آنکه طبع بلند دارد. بلندهمت <span class=\"hlight\">:</span> <br />الا ای نیک رای نیک تدبیر<br />جوان مرد جهان طبع جهانگیر.<br /> <font color=\"Red\">سعدی (صاحبیه ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چار طبع</span> ؛معمولاً بر سودا و صفرا و دم و بلغم اطلاق میشود؛ ولی شاعران آنرا بمعنی چار مزاج، یعنی رطوبت و یبوست و حرارت و برودت و چار عنصر: آب و خاک و آتش و باد نیزبکار برده اند <span class=\"hlight\">:</span> <br />درین چار طبع مخالف نهاد<br />که آب آمد و آتش و خاک و باد.<br /> <font color=\"Red\">نظامی .</font><br />چار طبع مخالف سرکش <br />چند روزی شوند با هم خوش .<br /> <font color=\"Red\">سعدی .</font><br />مزاجت تر و خشک و گرم است و سرد<br />مرکب ازین چارطبع است مرد.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چهار طبع</span> ؛ رجوع به ترکیب چار طبع شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خام طبع</span> ؛ کژذوق .بی تجربه <span class=\"hlight\">:</span> <br />آتش اندر پختگان افتاد و سوخت <br />خام طبعان همچنان افسرده اند.<br /> <font color=\"Red\">سعدی (طیبات ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خردمندطبع</span> ؛ آنکه طبیعت خردمندانه دارد. عاقل <span class=\"hlight\">:</span> <br />خردمندطبعان منت شناس <br />بدوزند منت بمیخ سپاس .<br /> <font color=\"Red\">سعدی (بوستان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خوش طبع</span> ؛ خوش خوی . نیک سرشت <span class=\"hlight\">:</span> <br />ببرد از پریچهره ٔ زشتخوی <br />زن دیوسیمای خوش طبع گوی .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />کبر یکسو نِه اگر شاهد درویشانی <br />دیو خوش طبع به از حور گره پیشانی .<br /> <font color=\"Red\">سعدی (بدایع).</font><br />یکی مرد شیرین و خوش طبع بود<br />که با ما مسافر در آن ربع بود.<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />مشفق و مهربان، خوش طبع و شیرین زبان . (گلستان ).<br />ترشروی بهتر کند سرزنش <br />که یاران خوش طبع و شیرین منش .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />خوش طبع و شیرین زبان سخنهای لطیف میگویند. (گلستان سعدی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">راست طبع</span> ؛ آنکه طبیعت راست دارد. خوش ذوق .راست خوی . راست سرشت <span class=\"hlight\">:</span> <br />آن کس که نه راست طبع باشد نه نکو<br />نه عاشق کس بودنه کس عاشق او.<br /> <font color=\"Red\">سعدی (رباعیات ).</font><br />مرا یکدم از دست نگذاشتی <br />که با راست طبعان سری داشتی .<br /> <font color=\"Red\">سعدی (بوستان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ساده طبع</span> ؛ ساده دل . آنکه مکر و فریب ندارد <span class=\"hlight\">:</span> <br />تا بدان عشوه های طبعفریب <br />از من ساده طبع برد شکیب .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کریم طبع</span> ؛ بخشنده . آنکه سرشت سخا و جود دارد <span class=\"hlight\">:</span> <br />آن است کریم طبع کو احسان <br />با اهل وفا و فضل خود دارد.<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کریم طبعی </span> ؛ بخشندگی . جود<span class=\"hlight\">:</span> <br />یک گروه ازکریم طبعی خویش <br />مردمی را بجان خریدارند.<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کژطبع و کج طبع</span> ؛ بی ذوق . بدنهاد. بدسرشت <span class=\"hlight\">:</span> <br />اشتر بشعر عرب در حالت است و طرب <br />گر ذوق نیست ترا کژطبع جانوری .<br /> <font color=\"Red\">سعدی (گلستان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گداطبع</span> ؛ فرومایه . بخیل <span class=\"hlight\">:</span> <br />گداطبع اگر در تموز آب حیوان <br />بدستت دهد جور سقا نیرزد.<br /> <font color=\"Red\">سعدی (صاحبیه ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مخالف طبع</span> ؛ ستیزه گر. لجوج <span class=\"hlight\">:</span> <br />چه گر مخالف طبعند و ناموافق جسم <br />موافقند به یک جای از قضا و قدر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />شنیدم کآن مخالف طبع بدخوی <br />به بیشرمی بگردانید ازو روی .<br /> <font color=\"Red\">سعدی (صاحبیه ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ملوک طبع</span> ؛ آنکه طبع شاهان دارد. بلندهمت <span class=\"hlight\">:</span> <br />درین زمین که تو هستی ملوک طبعانند<br />که ملک روی زمین پیششان نیرزد لاش .<br /> <font color=\"Red\">سعدی (صاحبیه ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">هشت طبع</span> ؛ ظاهراً کنایه از چار طبع و چار مزاج است <span class=\"hlight\">:</span> <br />هم با عدم پیاده فرو رو به هشت طبع<br />هم با قدم سوار برون ران به هفت خوان .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> مجازاً زاده ٔ طبع و دختر طبع و مادر طبع و پسر طبع و عروس طبع و گهر طبع بمعنی شعر آمده است <span class=\"hlight\">:</span> <br />زاده ٔ طبع منند اینان و خصمان منند<br />آری آری گربه هست از عطسه ٔ شیر ژیان .<br /> <font color=\"Red\">خاقانی .</font><br />افراسیاب طبع من آن بیژن شجاعت <br />عذر آورد و بهتر ازین دختری ندارم .<br /> <font color=\"Red\">خاقانی .</font><br />یکی دو زایند آبستنان و مادر طبع<br />ز من بزاد بیکبار صدهزار پسر.<br /> <font color=\"Red\">خاقانی .</font><br />عروس طبع بر او عقد بستم از سر عقل <br />بدان صداق که از اهتمام او زیبد.<br /> <font color=\"Red\">خاقانی </font><br />بدگهران را ستودم از گهر طبع<br />گر گهری را ستود می چه غمستی .<br /> <font color=\"Red\">خاقانی .</font><br />شیرینی دختران طبعت <br />شور از متمیزان برآورد.<br /><font color=\"Red\">سعدی (طیبات ).</font><br /></font></div>'),
(175935, 'طبع تیز کردن', '<span class=\"hlight\">طبع تیز کردن .</span> <font color=\"DarkGreen\"><b>[ طَ ک َ دَ ]</font></b> (مص مرکب ) کنایه از مشتاق و حریص گردانیدن طبع را بچیزی . (آنندراج ).<br /></font></div>'),
(175936, 'طبع جامد', '<span class=\"hlight\">طبع جامد.</span> <font color=\"DarkGreen\"><b>[ طَ ع ِ م ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) ناموزون طبع. کندطبع. (آنندراج ).<br /></font></div>'),
(175937, 'طبع کافوری', '<span class=\"hlight\">طبع کافوری .</span> <font color=\"DarkGreen\"><b>[ طَ ع ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از مزاج سرد و خشک باشد. (برهان ). <BR><font color=\"Blue\">◄</font> کنایه از طبع سوداوی . (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از مردم کند طبع و خنک و بارد. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> یخ بسته . (برهان ). <BR><font color=\"Blue\">◄</font> کنایه از فوت و موت . (برهان ). مرگ . (آنندراج ). <BR><font color=\"Blue\">◄</font> شوریده دماغ . آشفته عقل . رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">١٦٩</span> شود.<br /></font></div>'),
(175938, 'طبع کردن', '<span class=\"hlight\">طبع کردن .</span> <font color=\"DarkGreen\"><b>[ طَ ک َ دَ ]</font></b> (مص مرکب ) چاپ کردن . باسمه کردن . <BR><font color=\"Blue\">◄</font> نقش کردن .<br /></font></div>'),
(175939, 'طبعان', '<span class=\"hlight\">طبعان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) هذا طبعان الامیر: گلی که بدان مهر کرده شود. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(175940, 'طبعی', '<span class=\"hlight\">طبعی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) اصفهانی . تخلص یکی ازشعرای ایران است، نامش عبداﷲ وی از اهالی اصفهان بود، در اوایل عبدی و بعد طبعی تخلص میکرد. از اوست :<br />سیل اشکم گرهی در دل جیحون زده است <br />تیر آهم به صف چرخ شبیخون زده است <br />لاله از خجلت همچشمی داغ دل من <br />زین چمن خیمه برون برده، به هامون زده است .<br /><font color=\"Red\">(قاموس الاعلام ترکی ).</font><br /></font></div>'),
(175941, 'طبعی', '<span class=\"hlight\">طبعی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) کلیبولی . یکی از شعرای قرن دهم عثمانی است . وی از اهالی کلیبولی بوده و نامش سلیمان است . مدتی به قضاوت اشتغال داشته و بعدها در بغداد به دفترداری پرداخته است . (قاموس الاعلام ترکی ).<br /></font></div>'),
(175942, 'طبعی', '<span class=\"hlight\">طبعی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) قزوینی . یکی از شعرای ایران و از اهالی قزوین می باشد. وی از تلامذه ٔ حکیم شفائی اصفهانی بوده است :<br />تنها به دیده می نتوان دادِ گریه داد<br />چون ابر باید از همه اعضا گریستن .<br /> <font color=\"Red\">(قاموس الاعلام ترکی ).</font><br />نصرآبادی آرد: طبعی قزوینی خوش طبع و شوخ بود. از شاگردان و مصاحبان حکیم شفائی بوده . از خواجه شاپور رنجیده قطعه ای در هجو او گفته . این است :<br />خواجه شاپور غریبی که مدام از پی رزق <br />صبح عیدش همه چون شام محرم باشد<br />دست خشکیده ٔ او گر بمثل ابر شود<br />غمزه ٔ گل همه خمیازه ٔ شبنم باشد<br />بس که دلگیر ز همکاسه بود میشکند<br />کاسه ای را که در او صورت آدم باشد.<br />و هم از اوست :<br />لذت تنگدلی باد بر آن غنچه حرام <br />که به امداد صبا میل شکفتن دارد.<br />شمع ما را تاب بال افشانی پروانه نیست <br />جانفشانی در برون انجمن خواهیم کرد.<br />گر به یاد لب او جام دهد باده فروش <br />توبه خمیازه کشان تا در میخانه رود.<br />نمیدهم به نگه رخصت نظاره ٔ یار<br />درین زمانه بچشم خود اعتباری نیست .<br />بعمر خویشتن طی کرده ام بسیار وادیها<br />نیامد هیچ وادی بهترم از نامرادیها.<br />و کاملای کاشی بیتی بی معنی گفته بود، <font color=\"DarkGreen\"><b>[ طبعی ]</font></b> در آن باب گفته است :<br />دوش اندر سر بازار شنیدم ز کسی <br />بیتی از کامل جاهل که شنیدن دارد<br />از پی آنکه بخود ره ندهد معنی را<br />حرف حرفش ز نقطسنگ بدامن دارد.<br /><font color=\"Red\">(تذکره ٔ نصرآبادی ).</font><br /></font></div>'),
(175943, 'طبعی', '<span class=\"hlight\">طبعی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) سیستانی . یکی از شعرای ایران است و از اهالی سیستان بوده است . از اوست :<br />زود از برم چنین گله آلود برمخیز<br />باقی نمانده جز نفسی، زود برمخیز.<br /> <font color=\"Red\">(قاموس الاعلام ترکی ).</font><br />نصرآبادی آرد: گویا از اکابر سیستان است .<br />طبعش خیلی لطف داشته از اقران ملازمان یزدی است .شعرش این است :<br />از سوز درونم ببرون هم اثری هست <br />گر راه فغان بسته شود چشم تری هست <br />چندین بپریشانی این زلف چه نازی <br />در زلف تو از زلف تو آشفته تری هست <br />هر خشت ز سرمنزل امید بجائیست <br />از بس که زمین دل ما زلزله دارد.<br />خوش است ناله اگر در دل توره یابد<br />ز هم گشودن درهای آسمان سهل است .<br />کامرانی دگر چه میباشد<br />هرچه خواهد دلم مهیا نیست .<br />زود از دلم چنین گله آلود برمخیز<br />باقی نمانده جز نفسی زود برمخیز<br />روزی به مدعای دل من بشب رسان <br />گو مدعی ز بزم تو خشنود برمخیز.<br /> <font color=\"Red\">(تذکره ٔ نصرآبادی ).</font><br />رجوع به آتشکده ص <span class=\"hlight\" dir=\"rtl\">٨٢</span> شود.<br /></font></div>'),
(175944, 'طبعی', '<span class=\"hlight\">طبعی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) سمنانی . یکی از شعرای ایران و از اهالی سمنان بوده . از اوست :<br />شرح سوز دل که عمری از تو پنهان داشتم <br />گر نگویم دل، وگر گویم زبان میسوزدم .<br /><font color=\"Red\">(قاموس الاعلام ترکی ).</font><br /></font></div>'),
(175945, 'طبعی', '<span class=\"hlight\">طبعی .</span> <font color=\"DarkGreen\"><b>[طَ ]</font></b> (اِخ ) یکی از شعرای عثمانی است . وی در قرن دهم هجری میزیسته و به اشتب زاده شهرت داشته . از اوست :<br />عارضک شوقیله یا قدم سینه م اوزره تازه داغ <br />سینه ده شاه خیالک قوروی بر گلگون اوتاغ .<br /><font color=\"Red\">(قاموس الاعلام ترکی ).</font><br /></font></div>'),
(175946, 'طبعی', '<span class=\"hlight\">طبعی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) یکی از شعرای عثمانی است . وی در قرن دهم هجری میزیسته و از دانشمندان عصر خود و تلامذه ٔ ابوالسعود افندی بود. بعدها حیثیت خود را بانهماک درعیش و عشرت لکه دار کرده است . (قاموس الاعلام ترکی ).<br /></font></div>'),
(175947, 'طبعی', '<span class=\"hlight\">طبعی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص نسبی ) جبلی . صاحب غیاث اللغات گوید: طبعی منسوب به طبیعت است، چرا که حرف ثالث اگر با باشد در حالت نسبت حذف کنند، چنانچه مدنی منسوب به مدینه و بهمین حرکات نام فنی از فنون حکمت . و بفتح اول و سکون ثانی نیز آمده، در این صورت منسوب به طبع باشد. (غیاث اللغات ).ذاتی . فطری . خلقی . گهری . گوهری . نهادی <span class=\"hlight\">:</span> <br />بدین فروخته رویان نگه کنم که همی <br />بفعل طبعی روی زمین فروزانند.<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> آنکه طبیعت پرستد. طبعی مذهب <span class=\"hlight\">:</span> <br />تا هست خلاف شیعی و سنی <br />تا هست وفاق طبعی و دهری .<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(175948, 'طبق', '<span class=\"hlight\">طبق .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) معرب است . اصلش تبوک، و فارسی است . رکابی و خوان . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ظرفی که میخورند بر آن . (منتهی الارب ). ج، اطباق . ظرف معروف . (غیاث اللغات ) (آنندراج ). بشقاب . ظرف پَخ که بر آن طعام خورند. پیشیاره . (طبق ؛ سفر اعداد <span class=\"hlight\" dir=\"rtl\">٧</span>:<span class=\"hlight\" dir=\"rtl\">١٣</span>). بشقاب یا کاسه مانندی بوده است . و بسا میشود که قصد از طبق چینی باشد. (انجیل متی <span class=\"hlight\" dir=\"rtl\">١٤</span>:<span class=\"hlight\" dir=\"rtl\">٨</span> و <span class=\"hlight\" dir=\"rtl\">١١</span>). یابشقاب که از یکی از فلزات ساخته شده باشد. (قاموس کتاب مقدس ). <BR><font color=\"Blue\">◄</font> ظرف مدور پخ و بزرگ از چوب که ظروف یا اشیای دیگری بر وی نهند. پهن مسطح (بی گودی ) از چوب . ظرف مدور بزرگ که از چوب کرده بی لبه یا با لبه ٔ بسیار کوتاه که خوردنی چون توت و انگور بر آن نهاده بر سر حمل کنند. و گاه باشد که اسباب و اثاث خانه بدان برند از جائی به جائی . طبق که از ترکه ٔ بید کنند. ظرف چوبین بزرگ بی دیواره <span class=\"hlight\">:</span> و از وی <font color=\"DarkGreen\"><b>[ آمل ]</font></b> آلاتهای چوبین خیزد، چون کفچه و شانه و شانه ٔ نیام و ترازوخانه و کاسه و طبق . (حدود العالم ).<br />فروزنده ٔ مجلس و می گسار<br />نوازنده ٔ چنگ با گوشوار<br />طبقهای زرین پر از مشک ناب <br />به پیش اندرون آبگیر گلاب .<br /> <font color=\"Red\">فردوسی .</font><br />ز سیمین و زرین شتروار سی <br />طبقها و از جامه ٔ پارسی .<br /> <font color=\"Red\">فردوسی .</font><br />طبقهای زرین وسیمین نهاد<br />نخستین ز قیدافه کردند یاد.<br /> <font color=\"Red\">فردوسی .</font><br />طبقهای زرین و پیروزه جام <br />کمرهای زرین سیمین ستام .<br /> <font color=\"Red\">فردوسی .</font><br />بزرین طبقها فروریختند<br />به سر مشک و عنبر فروبیختند.<br /> <font color=\"Red\">فردوسی .</font><br />زبرجد طبقها و پیروزه جام <br />پر ازنافه ٔ مشک و از عود خام .<br /> <font color=\"Red\">فردوسی .</font><br />چو حورانند نرگسها همه سیمین طبق بر سر<br />نهاده بر طبقها بر ز زرّ ساو ساغرها.<br /> <font color=\"Red\">منوچهری .</font><br />چون آهن سوده که بود بر طبقی بر<br />در زیر طبق مانده ز مغناطیس احجار.<br /> <font color=\"Red\">منوچهری .</font><br />هر آنگاه که آن محدث را بسوی گرگان فرستادی <font color=\"DarkGreen\"><b>[ مسعود ]</font></b> بهانه آوردی که در آنجا تخم سپرغم و ترنج و طبقها و دیگر چیزها آورده می آید. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span>). ندیمان را بخواند امیر، و شراب و مطربان خواست، و این اعیان را بشراب بازگرفت، و طبقهای نواله و سنبوسه روان شد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٨٢</span>). بیست طبق زرین، میوه ٔ آن انواع جوهر. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٣٥</span>). گرد بر گرد این نرگسدانهای سیم، طبق زرین برنهاد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٠٣</span>). گفت : بیارید آن طبق، بیاوردند و از او سرپوش برداشتند سر حسنک را دیدیم . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٨٥</span>). <font color=\"DarkGreen\"><b>[بوسهل ]</font></b> فرموده بود تا سر حسنک از ما پنهان آورده بودند و بداشته در طبقی . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٨٥</span>). آراسته به حوضها و طبقهای زرین و سیمین . (تاریخ یمینی خطی ص <span class=\"hlight\" dir=\"rtl\">٣٣٤</span>).<br />در طبق مجمر مجلس فروز<br />عود شکرساز و شکر عودسوز.<br /> <font color=\"Red\">نظامی .</font><br />چو شیرین در مداین مهد بنهاد<br />ز شیرین لب طبقها شهد بگشاد.<br /> <font color=\"Red\">نظامی .</font><br />عاشقت از جان و دل جان و دلی بر طبق <br />پیش نثار رخت نعره زنان آمده .<br /> <font color=\"Red\">عطار.</font><br />به چه کار آیدت ز گل طبقی <br />از گلستان من ببر ورقی .<br /> <font color=\"Red\">سعدی .</font><br />زهاد سد رمق و پیران تا عرق کنند و جوانان تا طبق بردارند. (گلستان ).<br />لاتخف دان چونکه خوفت داد حق <br />نان فرستد چون فرستادت طبق .<br /> <font color=\"Red\">مولوی .</font><br />همچنین زین قوت ابدال حق <br />هم ز حق دان نز طعام و نز طبق .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> سحق . مساحقه . خواهرخواندگی . عملی است که زنان حکه با هم کنند صرف مالیدن و سائیدن عضو مخصوص با یکدیگر. (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br />اهل بغداد را زنان بینی <br />طبقات طبق زنان بینی .<br /> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٨٠٨</span>).</font><br /> <BR><font color=\"Blue\">◄</font> پشت شرم زن . (منتهی الارب ) <span class=\"hlight\">:</span> <br />چون طبق بر طبق زنند افغان <br />در طبقهای آسمان بینی .<br /> <font color=\"Red\">خاقانی .</font><br />و رجوع به طبق زدن شود. <BR><font color=\"Blue\">◄</font> روی زمین . <BR><font color=\"Blue\">◄</font> یک قرن از زمان . <BR><font color=\"Blue\">◄</font> یا بیست سال . <BR><font color=\"Blue\">◄</font> گروه مردم و ملخ . بسیار از مردم و ملخ . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> حال مردم . و منه قوله تعالی : لترکبن طبقاً عن طبق (قرآن <span class=\"hlight\" dir=\"rtl\">١٩/٨٤</span>)؛ ای حالا عن حال یوم القیامه . (منتهی الارب ) (مهذب الاسماء)؛ یعنی حالا عن حال . (مقدمه ٔ لغت میر سیدشریف جرجانی ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> استخوان تنک که میان دو پیوند استخوان پشت باشد. هر یک از استخوانهای تنک که فقره و مهره از فقرات پشت را از یکدیگر جدا کند. استخوان رقیق فاصل میان هر دو فقره از فقار پشت . <BR><font color=\"Blue\">◄</font> مهره های پشت . <BR><font color=\"Blue\">◄</font> باران عام . و منه فی استسقاء النبی صلی اﷲ علیه و آله و سلم : اللهم اسقنا غیثاً مغیثاً طبقاً. <BR><font color=\"Blue\">◄</font> پاره ای بزرگ از شب و روز. (منتهی الارب ). مضی طبق من اللیل ؛ بگذشت بیشترین از شب . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> پس یکدیگر زاده از بره و بچه . یقال : ولدتها طبقاً و طبقةً؛ ای ولدت بعضها بعد بعض . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> لت لنگه . مصراع . لخت : المصراع ؛ یک طبق در. المصراعان ؛ دو طبق در. (دستور اللغه ٔ ادیب نطنزی ). <BR><font color=\"Blue\">◄</font> نام علتی است که اسب را پیدا شود، و آن ورمی است که گرد ناف اسب بهم رسد. (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> الطبق بالموحدة و القاف کفرس ؛ ظرف یطبخ فیه . معرب تابه، مؤنثة. رجوع به «طابق » شود. <BR><font color=\"Blue\">◄</font> طبق آسمان . (مهذب الاسماء). هر یک از اشکوبهای آسمان، قبه ٔ آسمان . (ناظم الاطباء) <span class=\"hlight\">:</span> <br />رو که ز عکس لبت خوشه ٔ پروین شده ست <br />خوشه ٔ خرمای تر بر طبق آسمان .<br /> <font color=\"Red\">خاقانی .</font><br />بجنب طبقهای نقل تو شاها<br />طبقهای گردون نماید مزور.<br /> <font color=\"Red\">خاقانی .</font><br />چون طبق بر طبق زنند افغان <br />در طبقهای آسمان بینی .<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">لاجوردی طبق </span> ؛ کنایه است از آسمان <span class=\"hlight\">:</span> <br />چنان نادر افتاده در روضه ای <br />که برلاجوردی طبق بیضه ای .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">نه طبق </span> ؛ کنایه از نه آسمان، نه فلک <span class=\"hlight\">:</span> <br />ببین نه طبق برتر از هفت قلعه <br />ببین هفت خاتون بر از چار ماما.<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> تاه هر چیزی . (منتهی الارب ). ته . (نصاب ) (ترجمان علامه ٔ جرجانی ص <span class=\"hlight\" dir=\"rtl\">٦٧</span>). تو. <BR><font color=\"Blue\">◄</font> پوشش هر چیزی . پرده . ج، اطباق، اطبقة، طباق . <BR><font color=\"Blue\">◄</font> مانند و مساوی هر چیز. (منتهی الارب ). موافق و برابر.(غیاث اللغات ). <BR><font color=\"Blue\">◄</font> بیشتر و بزرگتر چیزی . (مقدمه ٔ لغت میر سیدشریف جرجانی ). <BR><font color=\"Blue\">◄</font> همه جا فرارسیده . (مقدمه لغت میر سیدشریف جرجانی ). <BR><font color=\"Blue\">◄</font> برگ و ورق . (ناظم الاطباء). طبق کاغذ. ورق کاغذ. و در تداول محلی شهرهای گناباد و بروجرد و گلپایگان هم اکنون این کلمه را بر ورق کاغذ بصورتهای طبق و طوق اطلاق کنند <span class=\"hlight\">:</span> و بدیعالکتبه علی بن اسماعیل ... خطاط است و ناسخ که در روزی زیادت از دو طبق کاغذ بخط منسوب نویسد. (تاریخ بیهق ). دیوان او بیست طبق کاغذ باشد. (تاریخ بیهق ). و همه حکایتها که بدین کتاب بیاوردیم بر پنج طبق کاغذ نیابد. (اسکندرنامه ٔنسخه ٔ خطی سعید نفیسی ). علاءالدوله ٔ سمنانی در کتاب مفتاح گوید: هزار طبق کاغذ در راه و رسم تصوف سیاه کرده اند. (تذکرةالشعراء دولتشاه چ لیدن ص <span class=\"hlight\" dir=\"rtl\">٢٤٩</span>). <BR><font color=\"Blue\">◄</font> ورق طلا <span class=\"hlight\" dir=\"rtl\">١١٠</span> فوفه یعنی ورق فلزی الوان که در زیر نگین انگشتری گذارند. (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبق از برگ خرما</span> ؛ قنع و قناع . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبق براوگندن </span> ؛ اِطباق . (زوزنی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبق شمع</span> ؛ شمعدان . تور. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبق هدیه </span> ؛ قنع. (دهار).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مِثل ِ طبق </span> ؛ گرد و مدور.<br /></font></div>'),
(175949, 'طبق', '<span class=\"hlight\">طبق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) نزدیک گردیدن بکردن کار. <BR><font color=\"Blue\">◄</font> چسبیدن دست به پهلو و گشاده نشدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بستن کتاب و دست . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>).<br /></font></div>'),
(175950, 'طبق', '<span class=\"hlight\">طبق .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) گروه مردم . <BR><font color=\"Blue\">◄</font> گروه ملخ . بسیار از مردم و ملخ . <BR><font color=\"Blue\">◄</font> سریشم که مرغان را بدان شکار کنند. <BR><font color=\"Blue\">◄</font> بار درختی . <BR><font color=\"Blue\">◄</font> هرچه بدان چیزی را به چیزی چفسانند. (منتهی الارب ). سریش . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> دام که به وی شکار کنند. (منتهی الارب ). بالان . (دهار). <BR><font color=\"Blue\">◄</font> ساعت از روز. <BR><font color=\"Blue\">◄</font> زمان دراز. ومنه : اقمنا عنده طبقاً؛ ای زماناً طویلا. <BR><font color=\"Blue\">◄</font> هذا طبقة و طبقة؛ این موافق و برابر اوست . (منتهی الارب ). طریق . دستور. (مقدمه ٔ لغت میر سیدشریف جرجانی ص <span class=\"hlight\" dir=\"rtl\">٥</span>). وفق . وفاق . مطابق که در فارسی با بر بکار میرود <span class=\"hlight\">:</span> و سلوک کن بر طبق ستوده تر اطوار خود.(تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣١٣</span>). و بر طبق عدالت قضا رانده و میراند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>). <BR><font color=\"Blue\">◄</font> دبق . کشمش کولی . اسم دبق است و آن لبن و تَیّوع درختی است چسبنده، مانند لبن و تَیّوع درخت کتهل که به آن جانوران را صید کنند. (فهرست مخزن الادویه ).<br /></font></div>'),
(175951, 'طبق', '<span class=\"hlight\">طبق .</span> <font color=\"DarkGreen\"><b>[ طِ ب َ ]</font></b> (ع اِ) ج ِ طبقة.<br /></font></div>'),
(175952, 'طبق', '<span class=\"hlight\">طبق .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طبیق .<br /></font></div>'),
(175953, 'طبق', '<span class=\"hlight\">طبق .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) دهی از دهستان نازیل بخش شهرستان زاهدان در <span class=\"hlight\" dir=\"rtl\">٧</span>هزارگزی شمال باختری خاش و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی شوسه ٔ زاهدان به خاش . جلگه، گرمسیر، معتدل و مالاریائی با <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه . آب آن از چاه . محصول آن لبنیات، شغل اهالی گله داری . راه آن مالرو است و ساکنین از طایفه ٔ ریگی هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175954, 'طبق بند', '<span class=\"hlight\">طبق بند.</span> <font color=\"DarkGreen\"><b>[ طَب َ ب َ ]</font></b> (نف مرکب ) چینی بندزن . کاسه بند <span class=\"hlight\">:</span> <br />بر دل هر شکسته زد غم تو<br />چون طبق بند از صنیعت فش .<br /><font color=\"Red\">شهید.</font><br /></font></div>'),
(175955, 'طبق ده', '<span class=\"hlight\">طبق ده .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ دِ ]</font></b> (اِخ ) دهی است از دهستان میان دورود بخش مرکزی شهرستان ساری، واقع در<span class=\"hlight\" dir=\"rtl\">٣</span>هزارگزی شمال خاوری ساری بین رود تجن و نکا. دشت، جنگلی، معتدل، مرطوب مالاریائی با <span class=\"hlight\" dir=\"rtl\">٩٠٠</span> تن سکنه . آب آن از رودخانه ٔ نکا. محصول آن برنج، غلات، پنبه، صیفی ولبنیات . شغل اهالی زراعت و گله داری . راه آن مالرو است . دبستان دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(175956, 'طبق زدن', '<span class=\"hlight\">طبق زدن .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ زَ دَ ]</font></b> (مص مرکب ) آرامش زن با زن . سحق . مساحقه . رجوع به طبق شود.<br /></font></div>'),
(175957, 'طبق زن', '<span class=\"hlight\">طبق زن .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ زَ ]</font></b> (نف مرکب ) سعتری . سَحّاقه <span class=\"hlight\">:</span> <br />اهل بغداد را زنان بینی <br />طبقات طبق زنان بینی .<br /> <font color=\"Red\">خاقانی .</font><br />رجوع به مجموعه ٔمترادفات ص <span class=\"hlight\" dir=\"rtl\">٢٣٨</span> شود.<br /></font></div>'),
(175958, 'طبق زنبور', '<span class=\"hlight\">طبق زنبور.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ق ِ زَم ْ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از خانه ٔ زنبور است . (برهان ).<br /></font></div>'),
(175959, 'طبق زنی', '<span class=\"hlight\">طبق زنی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ زَ ]</font></b> (حامص مرکب ) طبق زدن . مساحقه .<br /></font></div>'),
(175960, 'طبق سر', '<span class=\"hlight\">طبق سر.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ س َ ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش فریمان شهرستان مشهد، واقع در <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی شمال خاوری فریمان و <span class=\"hlight\" dir=\"rtl\">٨</span>هزارگزی شمال شوسه ٔ مشهد به تربت جام . کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">١٦٢</span> تن سکنه . آب آن از قنات .و محصول آن غلات، بنشن و میوه ها. شغل اهالی زراعت . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(175961, 'طبق طبق', '<span class=\"hlight\">طبق طبق .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ طَ ب َ ]</font></b> (ق مرکب ) آنچه بتوالی بر طبقها بود. کنایه است از تعداد بسیار <span class=\"hlight\">:</span> <br />ببین به دیده ٔ انصاف نظم خاقانی <br />طبق طبق ز جواهر بر انتخاب بریز.<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">افاده ها طبق طبق </span> .<br /></font></div>'),
(175962, 'طبق پوش', '<span class=\"hlight\">طبق پوش .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (نف مرکب، اِ مرکب ) مکبة. سرپوش <span class=\"hlight\">:</span> <br />گفت برخیز و این ورق بردار<br />وین طبق پوش ازین طبق بردار.<br /> <font color=\"Red\">نظامی .</font><br />حریفی جنس دید و خانه خالی <br />طبق پوش از طبق برداشت حالی .<br /> <font color=\"Red\">نظامی .</font><br />طبق پوش برداشت ازخوان دُر<br />ز دُر دامن شاه را کرد پُر.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175963, 'طبق کش', '<span class=\"hlight\">طبق کش .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b>(نف مرکب ) طبقدار. حمال که چیزها بطبق بر سر برد.<br /></font></div>'),
(175964, 'طبق کشی', '<span class=\"hlight\">طبق کشی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (حامص مرکب ) شغل طبق کش . باربری به طبق .<br /></font></div>'),
(175965, 'طبق گر', '<span class=\"hlight\">طبق گر.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ گ َ ]</font></b> (ص مرکب ) آنکه طبق سازد.<br /></font></div>'),
(175966, 'طبقا', '<span class=\"hlight\">طبقا.</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (معرب، اِ) بلغت رومی نوعی از گندم باشد، لکن باریکتر از گندم است و آنرا بفارسی کاکل گویند. خوردن آن اسب را ضرر نرساند، لکن آدمی را ضرر به معده رساند. (برهان ) (آنندراج ). نوعی از گندم است، اما باریکتربود، و حشیش وی یک بالای مرد بود، و در سردسیرها کارند، و آنرا کاکل خوانند و مزاج وی مانند مزاج گندم بود، لکن نفاخ بود و نان وی چون گرم بود نیکو بود، اما چون سرد شود بد بود و دیر از معده بگذرد و اگر از آرد وی حسوئی سازند، سینه را پاک گرداند، و سرفه ٔ سخت را نافع بود، و بول براند، گرده و مثانه را پاک کند، و مضر بود بمعده، و نفخ و قراقر پیدا کند، و اگر اسب بخورد هیچ مضرت به وی نرسد، چنانکه از گندم مضرت میرسد. (اختیارات بدیعی ). به یونانی نوعی از گندم باریک است . و بقول جالینوس سلت است . و بقول صاحب تحفه شیلم است . توهم کرده کسی که آنرا خندروس دانسته . (فهرست مخزن الادویه ). شیلم است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(175967, 'طبقات', '<span class=\"hlight\">طبقات .</span><font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ع اِ) ج ِ طبقة. مراتب . درجات . پایه ها. جماعتی از مردمان . (تاریخ بیهقی ): طبقات الناس ؛ اجناس مختلفه از مردم . (منتهی الارب ). گروه ها. دسته ها <span class=\"hlight\">:</span> و ندیدم او را <font color=\"DarkGreen\"><b>[ بوالعسکر ]</font></b> هیچوقت در مجلس سلطان بخوردن شراب و بچوگان و دیگر چیزها، چنانکه ابوطاهر سیمجوری و طبقات ایشان را دیدم . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span>). و سراهنگان و طبقات لشکر را همچون بندگان درم خریده داشتندی . (فارسنامه ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>).<br />اهل بغداد را زنان بینی <br />طبقات طبق زنان بینی .<br /> <font color=\"Red\">خاقانی .</font><br />طبقات مردم از صدق یقین و خلوص اعتقاد دست به مبایعه ٔ او یازیدند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٧٩</span>). تاش آن صلات و مبرات بر طبقات لشکر خویش هزینه کرد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٦٧</span>). <BR><font color=\"Blue\">◄</font> بر کتبی اطلاق میشود که در آنها ترجمه ٔ احوال عالمان و حکیمان و فقیهان و شاعران و پزشکان و محدثان و جز آنان باشد. جرجی زیدان مینویسد: علما برای تحقیق مسائل علوم قرآن وحدیث و نحو و ادب ناگزیر شدند که به بحث در اسانید آنها بپردازند و احادیث یا مسائل ضعیف را از متین بازشناسند و این هدف آنان را به تحقیق درباره ٔ راویان اسانید و ترجمه ٔ احوال آنان برانگیخت تا آنجا که یکی از شرایط اجتهاد در فقه را معرفت اخبار درباره ٔ متون و اسانید احادیث قرار دادند، چنانکه فقیه باید به احوال ناقلان و راویان احاطه داشته باشد و عدول و ثقات و مطعون و مردود از هم بازشناسد و بوقایع مخصوص آنها آگاهی یابد از این رو راویان هر فنی را بطبقاتی تقسیم کردند و در نتیجه، بترجمه ٔ احوال طبقاتی، مانند عالمان و ادیبان و فقیهان و نحویان دست یازیدند و از جمله ٔ آنها میتوان طبقات شاعران و ادیبان و نحویان و فقیهان و شجاعان و محدثان و لغوی دانان و مفسران و حافظان و متکلمان و نسب شناسان و پزشکان و حتی ندیمان و مغنیان و جز آنان را نام برد. و درباره ٔ هر یک کتابی تألیف کردند... و قدیمترین کتب طبقات که ما بدان دست یافته ایم کتاب طبقات صحابه تألیف محمدبن سعید معروف به واقدی است . متوفی بسال <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> هَ . ق . و آن کتاب بزرگی است که چه بسامشتمل بر ده و اند مجلد باشد و در آن تراجم احوال صحابه و تابعین و خلفا تا روزگار مؤلف آمده است . و مجلدات این کتاب در کتابخانه های جهان پراکنده است، از آنجمله جلد دوم آن در کتابخانه ٔ خدیوی مصر موجود است و هنگامی که ما به نوشتن این سطور مشغول بودیم، اطلاع یافتم که یک انجمن علمی آلمانی بطبع آن اهتمام ورزیده و جلد اول آن منتشر شده است . از آن پس طبقات الشعرا تألیف ابن قتیبه متوفی بسال <span class=\"hlight\" dir=\"rtl\">٢٧٦</span> هَ . ق . امسال در لیدن به اهتمام استاد دکویه خاورشناس نامور هلندی چاپ شده است . آنگاه مؤلفان به تألیف طبقات بسیاری در ازمنه ٔ مختلف پرداختند و کتب تراجم بزرگی در این باره استخراج کردند، مانند وفیات الاعیان در وفیات و فوات الوفیات و جز اینها. (از تاریخ تمدن اسلام جرجی زیدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٨٩</span>). گذشته از اینها کتب معروف دیگری نیز درباره ٔ طبقات به فارسی و عربی تألیف و انتشار یافته است، مانند: طبقات الاطبا تألیف ابن اصیبعه و طبقات الشافعیه تألیف عبدالرحیم الاسنوی و طبقات الشیعه تألیف سیدعلیخان کبیر موسوم به الدرجات الرفیعه و طبقات ناصری تألیف منهاج الدین سراج و طبقات النحاة تألیف ابن الازرق و طبقات النحاة تألیف عبدالرحمن جلال الدین قرطبی و غیره .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175968, 'طبقات اجتماع', '<span class=\"hlight\">طبقات اجتماع .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت ِ اِ ت ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) مردمی که از نظر وضع اجتماعی و اقتصادی با هم متفاوتند. مقریزی در رساله ٔ اغاثةالامة بکشف الغمة طبقات اجتماع را بدینسان تقسیم کرده است : <span class=\"hlight\" dir=\"rtl\">١</span> - اهل دولت . <span class=\"hlight\" dir=\"rtl\">٢</span> - توانگران، از قبیل بازرگانان و منعمانی که در رفاه و آسایش بسر میبرند. <span class=\"hlight\" dir=\"rtl\">٣</span> - کسبه ای که نسبت به تجار طبقه ٔ متوسطی هستند و بازاریانی که معاش خود را از خرید و فروش به دست می آورند. <span class=\"hlight\" dir=\"rtl\">٤</span> - فلاحت پیشگانی که به کار کشت و کار میپردازند و ساکنان مزارع . <span class=\"hlight\" dir=\"rtl\">٥</span> - بینوایان و تهی دستان که اکثریت فقیهان و طلاب علوم را تشکیل میدهند. <span class=\"hlight\" dir=\"rtl\">٦</span> - پیشه وران و کارگرانی که در صنایع کار میکنند ومزد میگیرند. <span class=\"hlight\" dir=\"rtl\">٧</span> - مستمندان و بینوایانی که از راه تکدی معاش خود را به دست می آورند. کریستنسن مینویسد: از زمان بسیار قدیم ایرانیان جامعه ٔ دودمانی تشکیل داده بودند که از حیث تقسیمات ارضی مبتنی بر چهار قسمت بود از این قرار: خانه ده طایفه کشور ... ایران هخامنشی هفت دودمان ممتاز داشت که یکی از آنها نژادسلطنتی بود... تصور تسلسل دودمانی جامعه ها تا قرون متمادی در جامعه ٔ زردشتی حتی پس از انقراض ساسانیان حفظ شد. در کتب پهلوی مکرر ذکر «فرماندهان » چهارگانه رفته است از این قرار: رئیس خانه، رئیس ده، رئیس طایفه، رئیس کشور. در قطعاتی از متون مانوی که در تورفان به دست آمده است همین طبقه بندی کهن دیده میشود؛ با این تفاوت که آنرا درباره ٔ موجودات ملکوتی به کار برده اند. (از ایران در زمان ساسانیان صص <span class=\"hlight\" dir=\"rtl\">٢٩</span> - <span class=\"hlight\" dir=\"rtl\">٣١</span>). بر حسب تقسیم اوستا طبقات اجتماع سه طبقه است : <span class=\"hlight\" dir=\"rtl\">١</span>- روحانیون . <span class=\"hlight\" dir=\"rtl\">٢</span>- مردان جنگی . <span class=\"hlight\" dir=\"rtl\">٣</span>- برزگران . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٦</span>). کریستنسن مینویسد: در اوستای جدید جامعه ٔ ایرانی را به سه طبقه تقسیم کرده اند، یکی روحانیون و دیگر جنگیان دیگر کشاورزان . این طبقه بندی از تقسیمات اجتماعی بسیار قدیم است فقط یک عبارت در اوستا (یسنای <span class=\"hlight\" dir=\"rtl\">١٩</span>؛ فقره ٔ <span class=\"hlight\" dir=\"rtl\">١٧</span>) موجود است که از طبقه ٔ رابعی نام می برد و آن طبقه صنعتگران است . چون نوبت به ساسانیان رسید، تشکیلات جدید که آن نیز مبتنی بر چهار طبقه بود پدید آمد. تفاوت این شد که طبقه ٔ سوم را دبیران قرار دادند و کشاورزان و صنعتگران را در رتبه ٔ چهارم گذاشتند. بنابراین، طبقه بندی اجتماعی را به این نحوبا اوضاع سیاسی زمان تطبیق کردند طبقات اربعه ٔ ذیل پیدا شد: <span class=\"hlight\" dir=\"rtl\">١</span> - روحانیون <span class=\"hlight\" dir=\"rtl\">٢</span> - جنگیان <span class=\"hlight\" dir=\"rtl\">٣</span> - مستخدمین ادارات <span class=\"hlight\" dir=\"rtl\">٤</span> - توده ٔ ملت و صنعتگران و شهریان یا هتخشان . هر یک از این طبقات بچند دسته تقسیم میشد؛ طبقه ٔ روحانیان مشتمل بوده است بر قضات، داذور و علمای دینی (پست ترین و متعددترین مرتبه ٔ این علما صنف مغان بوده، پس از مغان موبذان و هیربذان و سایر اصناف روحانی که هر یک شغلی و وظیفه ٔ خاصی داشتند) دیگر از شعب طبقه ٔ روحانی دستوران و معلمان بوده اند و این صنف اخیر را مغان اندرز بد میگفته اند، اما طبقه ٔ جنگیان مشتمل بر دو صنف سوار و پیاده بوده است که وظایف مختلف داشتند. اصنافی که در طبقه ٔ مستخدمین ادارات تشخیص داده شده از این قرار است : منشیان، محاسبان، نویسندگان احکام محاکم، نویسندگان اجازه نامه ها و قراردادها، مورخان، پزشکان و منجمان نیز جزء این طبقه بشمار بوده اند. طبقه ٔ توده هم مرکب از اصناف و شعبی بود، مثل تجار، فلاحان، سوداگران و سایر پیشه وران . هر یک از این طبقات رئیسی داشت رئیس روحانیون موبذان موبذ، رئیس جنگیان ایران سپاه بذ، رئیس دبیران ایران دبیربذ (یا به اصطلاح دیگر دبیران مهشت )، رئیس طبقه ٔ چهارم را واستریوشان سالار (یا به اصطلاح دیگر واستریوش بذ یا هتخشبذ) میگفتند. هر رئیس یک نفر بازرس در تحت اختیار داشت که مأمور سرشماری طبقه ای بود. بازرس دیگرموظف بود که به درآمد هر فردی از افراد رسیدگی کند و نیز یک نفر آموزگار (اندرزبذ) در اختیار او بود «تا هر کس را از اوان کودکی علمی یا پیشه ای بیاموزد و او را بتحصیل معاش قادر کند . در ازمنه ٔ نخستین عهدساسانیان یک تقسیم اجتماعی دیگر وجود داشته که بی شبهه از بقایای عهد اشکانیان بوده است . نام این طبقات را در کتیبه ٔ حاجی آباد که به دو زبان نوشته شده، می بینیم . شاپور در آن سنگ نبشته کیفیت تیراندازی خود رابا حضور شهرداران (امرای دولت ) و واسپوهران (مقصود رؤسا یا بطور کلی افراد خاندانهای بزرگ است ) و زرگان (بزرگان ) و آزادان شرح میدهد. در این صورت فقط طبقات ممتاز ذکر شده است و نمیتوان از روی یقین معلوم کرد که چه نسبتی بین این صورت و طبقه بندی اجتماعی سابق الذکر بوده است . آنچه مسلم است ترتیب مذکور همیشه ثابت نمی مانده است . خلاصه باید گفت ترتیب مقامات و طبقات، امری بسیار پیچیده و تاریک است . (از تاریخ ایران در زمان ساسانیان ترجمه ٔرشیدیاسمی صص <span class=\"hlight\" dir=\"rtl\">١١٧</span> - <span class=\"hlight\" dir=\"rtl\">١٢١</span>). و در ص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span> همین کتاب آرد: جامعه ٔ ایرانی بر دو رکن (در اواخر دوره ٔ ساسانیان ) قائم بود: مالکیت و خون که بنابر نامه ٔ تنسر حدودی بسیار محکم داشت و نجبا و اشراف را از عوام الناس جدا میکرد امتیاز آنان «بلباس و مرکب و سرای و بستان وزن و خدمتکار بود» . و درجای دیگر گوید: «اشراف را بلباس و مراکب و آلات تجمل از محترفه و مهنه ممتاز کردند و زنان ایشان همچنین به جامه های ابریشمین و قصرهای منیف ورانین و کلاه و صید و آنچه آئین اشراف است و مردمان لشکری به آسایش و رفاهیت آمن و مطمئن بخانه ها بمعاش بر سر زن و فرزند فارغ نشسته .» در شاهنامه ٔ فردوسی از خسروانی کلاه و زرینه کفش بسیار سخن رفته است که مایه ٔ امتیاز اشراف بزرگ بوده است . بعلاوه طبقات از حیث مراتب اجتماعی درجاتی داشتند؛ هر کس را در جامعه درجه و مقامی ثابت بود و از قواعد محکم سیاست ساسانیان یکی این را باید شمرد که هیچکس نباید خواهان درجه ای باشد فوق آنچه بمقتضای نسب به او تعلق میگیرد. سعدالدین وراوینی در مرزبان نامه حکایتی نقل میکند که هرچند در صورت فعلی افسانه آمیز است، لیکن در این باب خالی از فایده نیست : صاحب اقبالی بود از خسروان پارس یک روز بفرمود تا جشنی بساختند و اصناف خلق را از اوساط و اطراف مملکت، شهری و لشکری، خواص و عوام، عالم و جاهل، جمله را در صحرائی به یک مجمع جمع آوردند و هر یک را مقامی معلوم و رتبتی مقدور کردند و همه را علی اختلاف الطبقات صف در صف بنشاندند و هرچه مشتهای طبع و منتهای آرزو بود از الوان اباها بساختند و از اهل ایوان طایفه ٔ گماشتگان ملک و دولت از بهر عرض مظالم خلق زیر خوان بنشستند، تا جزای عمل هریک بر اندازه ٔ رسوم و حدود شرع میدادند. خسرو در صدر مسند شاهی بنشست و مثال داد تا منادی بجمع برآمد که ای حاضران حضرت، جمله دیده ٔ بصیرت بگشایید و هر یک از اهل خان و حاضران دیوان، در مرتبه ٔ فرودست خویش نگرید و درجه ٔ ادنی ببیند و نظر بر اعلی منهید تا هرکه دیگری را دون مرتبه ٔ خویش بیند، بر آنچه دارد خرسندی نماید و شکر ایزدی بر مقام خویش بگزارد. جمله خلایق در حال یکدیگر نگاه کردند و بچشم اعتبار علو درجه ٔ خویش و نزول منزلت دیگران مطالعه کردند تا به آخرین صف که موضع اهل ظلامات بود، از آن طوایف نیز هرکه در معرض عتابی و مجرد خطایی بود، در آن کس نگاه کرد که سزاوار زجر و تعزیر آمد و او در حال آن کس که بمثله و امثال آن نکال و عقوبت گرفتار بود، و آنکه بچنین عقوبتی گرفتار شد، حال کسانی میدید اعوذ باللّه، که ایشان را صلب میکردند و گردن میزدند و انواع سیاستها بر ایشان میراندند و این عادت از آن عهد ملوک پارس را معهود شده است . ولی قوانین مملکت حافظ خون خاندانها و حفظ اموال غیرمنقول آنان بود. راجع به خاندان سلطنتی در فارسنامه عبارتی است که ظاهراً مأخوذ از آیین نامگ عهد ساسانیان است : « عادت ملوک فرس و اکاسره آن بودی که از همه ملوک اطراف چون صین و روم و ترک و هند دختران ستدندی وپیوند ساختندی و هرگز هیچ دختر را بدیشان ندادندی . دختران جز با کسانی که از اهل بیت ایشان بودند مواصلت نکردندی . نام خانواده های بزرگ را در دفاتر و دواوین ثبت میکردند دولت حفظ آنرا عهده دار بود و عامه را از خریدن اموال اشراف منع میکرد. با وجود این قهراً بعضی خانواده های نجیب بمرور زمان منقرض میشدند، درنامه ٔ تنسر آمده است : فساد بیوتات و درجات دو نوع است : یکی آنکه خانه را هدم کنند و درجه بغیر وضع روا دارند یا آنکه روزگار، خود بی سعی دیگری عز و بها و جلالت قدر ایشان بازگیرد واعقاب ناخلف در میان افتند اخلاق اجلاف را شعار خود سازند و شیوه ٔ تکرم فروگذارند و وقار ایشان پیش عامه برود و چون مهنه به کسب و مال مشغول شوند و از ادخارفضل بازایستند و مصاهره با فرومایه و نه کفو خویش کنند از آن توالد و تناسل فرومایگان پدید آیند که بتهجین مراتب ادا کنند.» در نامه ٔ اعمال شهیدان اشارات متفرقی راجع به احوال نجبا مذکور است : بعد از مرگ شهرین که از دودمان مهران بود برادرش کس فرستاد و پس شهرین گشن یزداذ (قدیس سابها) را طلب کرد تا مراسم قربانی و غذای مقدس را که حسب المعمول بایستی رئیس خانواده در ملک خانواده انجام دهد بجای آورد، اگرچه آن رئیس صغیر و نابالغ باشد، چنانکه در این مورد بود امااین گشن یزداذ دین عیسی گرفته بود، چون عمش که قیم او بود از این نکته استحضار یافت خود را قانوناً مالک اموال خانواده شناخت . بنابراین، میتوان قیاس کرد که در بعضی از ادوار عهد ساسانی برگشتن از دین رسمی مملکت موجب حرمان از ارث میشده و مرتد از حق مالکیت بی نصیب و املاک او به نزدیکترین خویشاوندانش می رسیده است . در مورد فوق چنین اتفاق افتاد که عم گشن یزداذ پس از چند روز وفات یافت و گشن یزداذ اموال خویش را متصرف شده در میان فقرا تقسیم نمود . معلوم نیست که نسبت به صحت این عمل اعتراضی شده باشد، همچنین در میان طبقات عامه تفاوتهای بارزی بود. هر یک از افراد مقامی ثابت داشت و کسی نمیتوانست به حرفه ای مشغول شود، مگر آنچه از جانب خدا برای آن آفریده شده بود . در کتاب مینوی خرد که مؤلفش معلوم نیست، آمده است : که پیشه وران باید «در کارهائی که نمیدانند وارد نشوند آنچه مربوط به پیشه ٔ آنهاست بخوبی انجام دهند و مزد آنرا بنرخ عادله بگیرند چه هر کس به کاری مشغول شود که از آن آگاه نیست آن کاررا ضایع و بیفایده کرده است ». ابوالفدا گوید: پادشاهان ایران هیچ کاری را ازکارهای دیوانی به مردم پست نژاد نمی سپردند. فردوسی حکایتی نقل کرده است که حاکی از همین ممنوعیت عوام الناس است، در زمانی که نوشیروان لشکر به روم میکشید:<br />از اندازه ٔ لشکر شهریار<br />کم آمد ز دینار سیصدهزار<br />بیامد بر شاه موبدچو گرد<br />بگنج آنچه بود از درم یاد کرد<br />بدو گفت از ایدر دو اسبه برو<br />گزین کن یکی نام بردار گو<br />ز بازارگانان و دهقان شهر<br />کسی را کجا باشد از نام بهر<br />ز بهر سپاه این درم وام خواه <br />به زودی بفرماید از گنج شاه <br />بیامد فرستاده ٔ خوش سخن <br />که نو بُد به سال و به دانش کهن <br />درم خواست وام از پی شهریار<br />بر او انجمن شد بسی مایه دار<br />یکی کفشگر بود موزه فروش <br />بگفتار او پهن بگشاد گوش <br />درم چند باید بدو گفت مرد<br />دلاور شمار درم یاد کرد<br />چنین گفت کای پرخرد مایه دار<br />چهل مر درم هر مری صدهزار<br />بیاورد کپان و سنگ و درم <br />نبد هیچ دفتر به کار و قلم <br />بدو کفشگر گفت کاین من دهم <br />سپاسی ز گنجور بر سر نهم <br />چو بازارگان را درم سخته شد<br />فرستاده از کار پردخته شد<br />بدو کفشگرگفت کای خوب چهر<br />نرنجی بگوئی به بوزرجمهر<br />که اندر زمانه مرا کودکیست <br />که بازار او بر دلم خوار نیست <br />بگوئی مگر شهریار جهان <br />مرا شاد گرداند اندر نهان <br />که او را سپارم به فرهنگیان <br />که دارد سر مایه و هنگ آن <br />فرستاده گفت این ندارم برنج <br />که کوتاه کردی مرا راه گنج <br />بیامد بر شاه بوزرجمهر<br />بر آن خواسته شاد بگشاد چهر<br />بشاه جهان گفت بوزرجمهر<br />که ای شاه نیک اختر خوب چهر<br />یکی آرزو کرد موزه فروش <br />اگر شاه دارد به گفتار گوش <br />فرستاده گفتا که این مرد گفت <br />که شاه جهان با خرد باد جفت <br />یکی پور دارم رسیده بجای <br />بفرهنگ جوید همی رهنمای <br />اگر شاه باشد بدین دستگیر<br />که این پاک فرزند گردد دبیر<br />بیزدان بخواهم همی جان شاه <br />که جاوید باد این سزاوار گاه <br />بدو گفت شاه ای خردمند مرد<br />چرا دیو چشم ترا خیره کرد<br />بر او همچنان بازگردان شتر<br />مبادا کز او سیم خواهیم و در<br />چو بازارگان بچه گردد دبیر<br />هنرمند و بادانش و یادگیر<br />چو فرزند ما برنشیند بتخت <br />دبیری ببایدش پیروزبخت <br />هنر یابد از مرد موزه فروش <br />سپارد بدو چشم بینا و گوش <br />به دست خردمند مرد نژاد<br />نماند جز از حسرت و سرد باد<br />به ما بر پس از مرگ نفرین بود<br />چو آیین این روزگار این بود<br />نخواهیم روزی جز از گنج داد<br />درم زو مخواه و مکن رنج یاد<br />هم اکنون شتر بازگردان زراه <br />درم خواه و از موزه دوزان مخواه <br />فرستاده برگشت و شد با درم <br />دل کفشگر زآن درم پر ز غم <br />این حکایت اهتمام پادشاه را در حفظ حدود طبقات نشان میدهد و کفشگر در اغلب روایات عهد ساسانی نمونه ٔ طبقه دانیه است که هر جا مثالی آورده اند از کفشگر سخن رانده اند. بطور کلی بالارفتن از طبقه ای بطبقه ٔ دیگر مجاز نبود، ولی گاهی استثنا واقع میشد و آن وقتی بود که یکی از آحاد رعیت اهلیت و هنر خاص نشان میداد. در این صورت بنابر نامه ٔ تنسر «آن را بر شهنشاه عرض کنند بعد تجربت موبدان و هرابذه و طول مشاهدات تا اگر مستحق دانندبغیر طایفه الحاق فرمایند اگر آن شخص در پارسائی آزموده بود، او را وارد در طبقه ٔ روحانیون میکردند و اگر قوت و شجاعت داشت او را در طبقه ٔ جنگیان داخل مینمودند و اگر در عقل و قوه ٔ حافظه ممتاز بود در طبقه ٔ دبیران، در هر صورت قبل از رفتن بطبقه ٔ اعلی بایستی تعلیمات کافی و استواری بیابد . بنابراین، رفتن یکی از عامه به طبقه ٔ اشراف بکلی ممتنع نبود. شاه این اختیار را داشت و به این وسیله خونی جدید در عروق نجبا وارد میکرد، اما بسیار نادر اتفاق می افتاد. در هرحال مردمان شهری نسبتاً وضعی خوبی داشتند. آنان هم مانند روستاییان مالیات سرشماری میپرداختند ؛ ولی گویا از خدمات نظامی معاف بودند و بوسیله ٔ صناعت و تجارت صاحب مال و جاه میشدند.اما احوال رعایا بمراتب از آنان بدتر بود مادام العمر مجبور بودند در همان قریه ساکن باشند و بیگاری و در پیاده نظام خدمت کنند. بقول آمیانوس مارسلینوس «گروه گروه از این روستاییان پیاده از پی سپاه میرفتند. گویی ابدالدهر محکوم بعبودیت هستند. بهیچوجه مزدی و پاداشی به آنان نمیدادند . بطور کلی قوانین مملکت برای حمایت روستاییان مقررات بسیاری نداشت و اگر هم پادشاهی رعیت نواز مثل هرمز چهارم لشکریان خود را از اذیت رساندن به روستاییان بی آزار منع میکرد، شاید بیشتر مقصود او دهگانان بود تا افراد رعیت . در باب احوال رعایایی که در زیر اطاعت اشراف ملاک بوده اند اطلاع بیشتری نداریم . آمیانوس گوید: «اشراف مزبور خود را صاحب اختیار جان غلامان و رعایا میدانستند . وضع رعایا در برابر اشراف ملاک بهیچوجه با احوال غلامان تفاوتی نداشت . نمیدانیم که حکام پادشاه نسبت به اقطاعاتی که در قلمرو آنها بوده، قدرتی داشته اند یا نه و آیا این اقطاعات دارای مصونیت تام یا نسبی بوده است یا خیر قدر متیقن این است که رعایا گاه به دولت و گاه به اشراف مالک و گاه به هر دو مالیات میداده اند و مجبور بوده اند در ظل رایت ارباب خود بجنگ بروند. با وجود این، نظر به اهمیت فوق العاده ای که زراعت در شریعت زردشتی داشته، چنانکه کتابهای مقدسی در ستایش این کار مبالغه کرده اند مسلم است که حقوق قانونی زارعین از روی کمال دقت معین بوده است . چند نسک از نسکهای اوستا خاصه هوسپارم و سکازم محتوی قواعد و احکامی در این خصوص بوده اند . مسئله ٔ آبیاری که مبنای زراعت مملکت در سابق بود و امروز نیز هست بتفصیل معین شده بود. راجع به اقسام مختلف قنوات و جداول آب و اسلوب سدبندی و بازرسی قنوات و نگاهداری و شرایط استفاده از آنها و امثال آن احکامی موجود بوده و نسبت به شماره ٔ گوسفندان و احوال شبانان و لزوم نگاهداری گله نیز قواعد ثابتی وضع کرده بودند. چنانکه معلوم است زرتشتیان سگ را بسیار محترم میشمردند و قسمتی از نسک «دزد سرنزد» راجع به محافظت قانونی سگان گله بوده است آنچه مذکور شد راجع به امتیاز افراد از حیث اختلاف طبقه ٔ اجتماعی آنان بود، اما بین ایرانیان و بیگانگان هم موجبات امتیازی بود که آثار آن در خلاصه ٔ نسکهای مفقوده موجود است . اگر مثلاً ایرانیان با کفار در سر یک سفره می نشستند، بایستی قوانین شرعی خاصی را مرعی دارند مزدی که به ملازمان غیرایرانی میدادند با موارد و شرایط معین، غیر از مزدی بود که به یک نفر متدین به دین مزدایی میدادند . در بعضی موارد وصلت با بیگانگان مجاز بوده است، اما در این باب تفصیلی در دست نداریم .(ایران در زمان ساسانیان صص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span> - <span class=\"hlight\" dir=\"rtl\">٣٤٥</span>). و رجوع به صفحات <span class=\"hlight\" dir=\"rtl\">٣٨٨</span> به بعد همان کتاب شود. و در کتاب مزدیسنا ذیل : پیدایش طبقات چهارگانه آمده است : فردوسی در داستان جمشید گوید: <br />ز هر پیشه در انجمن گرد کرد<br />بدین اندرون سال پنجاه خورد<br />گروهی که کاتوزیان خوانیش <br />برسم پرستندگان دانیش <br />جدا کردشان از میان گروه <br />پرستنده را جایگه کرد کوه <br />صفی بر دگر دست بنشاندند<br />همی نام نیساریان خواندند<br />کجا شیرمردان جنگاورند<br />فروزنده ٔ لشکر وکشورند<br />نسودی سه دیگر گره را شناس <br />کجا نیست بر کس از ایشان سپاس <br />بکارند و ورزند و خود بدروند<br />بگاه خورش سرزنش نشنوند<br />چهارم که خوانند اهنوخوشی <br />همان دست ورزان با سرکشی <br />کجا کارشان همگنان پیشه بود<br />روانشان همیشه پراندیشه بود.<br />این داستان از شاهنامه به کتب ادبی پارسی نیز پرتوافکن گردیده . ابن البلخی مؤلف فارسنامه نویسد: «(جمشید) جمله ٔ مردم جهان را بچهار طبقه قسمت کرد، و هر طبقه را به کاری موسوم گردانید: طبقه ٔ اول، کسانی که به فطانت و خردمندی و ذکا و معرفت موسوم بودند. بعضی را فرمود تا علم دین آموزند، تا حدود ملت خویش بدیشان نگاه دارد و بعضی را فرمود تا حکمت آموزند تا صلاح دنیاوی بدیشان رجوع کنند و به رأی روشن ایشان مناظم ملک را مضبوط دارند ازآنچه مصالح ملک بحکمت نگاه توان داشت، همچنانکه مصالح دینی بعلم نگاهداشته شود و مدبر ملک باید که عقل او به دانش آراسته باشد و دانش او استوار باشد و چون در یکی از این هر دو نقصان آید تدبیر او صواب نباشدو سخن در این دراز است اگر سخن از سخندان پرسند شفاتواند داد. اما غرض از این کتاب نه این است . آمدیم باز بر حدیث اول و بعضی هم از این طبقه ٔ اول فرمود تا دبیری و حساب آموختند تا ترتیب ملک و ضبط مال و معاملات بدیشان بگردد از آنچه بزرگترین آلتی نگاهداشت ترتیب ملک را بدور و نزدیک دبیر حاذق هشیاردل است که هیچ از سود و زیان و مصالح ملک بر وی پوشیده نماند ودر ذکا و فطنت به درجتی باشد که چون پادشاه ادنی اشارتی کند، او مقصود پادشاه تا بپایان دریابد و آن رابه عبارتی شیرین سلس نامکلف ادا کند پنداری که در اندرون دل پادشاه مینگرد و از هر علمی شمه ای دارد و هر دبیر که ذکا و دریابندگی و خرد او بر این جمله باشد <font color=\"DarkGreen\"><b>[ ظ: نباشد ]</font></b> جز معلمی را نشاید اگرچه با فضل و دانش و لغت بسیار باشد و از این جهت در روزگار خلفای اسلام قدس اﷲ ارواحهم کسانی را که بمثابه ٔ جاحظ و اصمعی و مانند ایشان بودند معلمی فرمودند با چندان ادب لغت که داشتندی و دبیری نفرمودند چه آداب و رسوم دبیری دیگر است و از آن لغت دیگر. و سبیل دبیر حساب همین است . و طبقه ٔ دوم، مردمانی را که در ایشان شجاعت و قوت و مردانگی شناخت فرمود تا ادب سلاح آموختند و جنگ را بشناختند و گفت : ملکی که بدین درجه رسید از خصم خالی نباشد و دفع خصم جز بمردان جنگی نتوان کرد. و طبقه ٔ سوم را پیشه وری فرمود چون نانوا و بقال و قصاب و بنا و دیگر پیشه ها که در جهان است و بعضی را کشاورزی و برزگری فرمود و مانند آن . و طبقه ٔ چهارم را به انواع خدمت ها موسوم گردانید، چون حواشی از فراش و خربنده و دربان و دیگر اتباع در اوستا برای لغت پیشه پیشترا استعمال شده . از تفحص در سرودهای گاتها برمی آید که در آغاز بسه پیشه قائل بودند و مردم را طبق آنها بسه طبقه تقسیم میکردند از این قرار: <span class=\"hlight\" dir=\"rtl\">١</span> - ائیریامن که بطبقه ٔ پیشوایان دینی و روحانیان اطلاق میشد. این کلمه در ادبیات پهلوی ائرمان و در ادبیات پارسی ایرمان و در شاهنامه سه بار استعمال شده است، از آنجمله در رفتن گشتاسب به روم فردوسی گوید:<br />اگر کشته گردد به دست تو گرگ <br />تو باشی به روم ایرمانی بزرگ .<br />کمال اسماعیل گفته :<br />ای شرع پروری که گذشت از جناب تو<br />دولت بهر کجا که رود ایرمان بود.<br />رفیعالدین لنبانی گوید:<br />بدخواه تو ز خانه ٔ هستی چورفت گفت <br />جاوید زی توخانه خدا کایرمان برفت .<br />در این ابیات ایرمان را بجای (مهمان ) گرفته اند و ایرامانسرای بجای مهمانسرای و سرای سپنج مستعمل است . خاقانی گوید:<br />دارالخلافه ٔ پدرست ایرمانسرای .<br />و نیز ایرمان بمعنی عبد و بنده آمده :<br />چو دانی در خراسان مرزبانی <br />چرا جوئی دگر جا ایرمانی ؟<br />بدیهی است که این واژه در ادبیات پارسی معنی اصلی خود را از دست داده و تحول بسیار پیدا کرده است . در سانسکریت همین کلمه ٔ اریامن به معنی یار و دوست و نیز نام یکی از خدایان ودا میباشد . در اوستای متأخر نیز نامی از ائیریامن ایزد برده شده : در فرگرد <span class=\"hlight\" dir=\"rtl\">٢٢</span> وندیداد، از این فرشته سخن رفته است که اهریمن <span class=\"hlight\" dir=\"rtl\">٩٩٩٩٩</span> بیماری بوجود آورد و آنگاه بفرمان اهورا، ایزد ائیریامن <span class=\"hlight\" dir=\"rtl\">٩٩٩٩٩</span> چاره و درمان فروآورد، پس بدین اعتبار نخستین پزشک جهان ائیریامن بود. در هپتان هائیتی (هفت ها، هفت فصل ) نیز که پس از گاتها قدیمترین قسمت اوستاست و به نثر نوشته شده در موردپیشوایان، کلمه ٔ هخمن استعمال شده که در سانسکریت ساکمن گردیده . هخمن بمعنی دوستی و یگانگی است از مصدر هچ بمعنی پیوستن، همراهی کردن، انبازی کردن . از همین ریشه است هخی بمعنی دوست و هخامنش نام پنجمین نیای داریوش نیز از این ریشه و بمعنی دوست منش میباشد. در جاهای دیگر اوستا پیشوایان دینی را آثرون یا آثه اورون یا اثه اوروئو نامیده اند که در پهلوی آثروک یا آثرون شده که همان آتوربان و آذربان باشد. <span class=\"hlight\" dir=\"rtl\">٢</span> - خوائتو در اوستا از ریشه ٔ خوا که در گزارش پهلوی (خویش ) ترجمه شده . این واژه در گاتها برزمیان اطلاق شده و ظاهراً وجه تسمیه ٔ آن از این جهت است که این گروه متکی به خود و دارای شخصیت ممتاز هستند. در هپتان هائیتی نیز همین واژه در مورد آزادگان و رزمیان آمده، اما در دیگر بخشهای اوستا رثه اشتره و در گزارش پهلوی ارتیشتر آمده است . رثه اشتره بمعنی رزمیان است (ارتش لغتی که به اشتباه بجای مجموعه ٔ سپاهیان کشور انتخاب کرده اند از همین ریشه است ). <span class=\"hlight\" dir=\"rtl\">٣</span> - ورزنا از مصدر ورز بمعنی ورزیدن و کشت و کار است که در پهلوی ورژیتن شده، در گاتها و هپتان هائیتی به طبقه ٔ برزگران اطلاق گردیده . در مورد این طبقه در دیگر قسمتهای اوستا واستریا و استریه آمده که در پهلوی وستریوش شده است . مسعودی «وستریوشان سالار» را ذکر کرده است که به معنی وزیر کشاورزی است . برای هر یک از این سه طبقه آتشکده ای بزرگ اختصاص داشته که شرح آن در مورد خود گذشت .<br />سه طبقه در آئین برهمائی : در آیین برهمائی هندوان (که از حیث نژاد با ایرانیان قرابت تام دارند) نیز همین سه طبقه وجود دارد:<br /><span class=\"hlight\" dir=\"rtl\">١</span> - برهمنه درپارسی برهمن یا روحانیان .<br /><span class=\"hlight\" dir=\"rtl\">٢</span> - خشاتریه (همریشه ٔ خشتره اوستائی و پارسی باستان و شتر پهلوی و شهر پارسی بمعنی شهریاری ) یا طبقه ٔ رزمیان .<br /><span class=\"hlight\" dir=\"rtl\">٣</span> - وئیسه یاطبقه ٔ دستوران و کشاورزان .<br />طبقه چهارم در اوستا: به طوری که مشاهده شد در بخشهای قدیم اوستا وودا سه طبقه تعیین گردیده ولی بعدها، طبقه ٔ چهارمی بدانها افزوده اند نام این طبقه در یسنای <span class=\"hlight\" dir=\"rtl\">١٩</span> بند <span class=\"hlight\" dir=\"rtl\">١٧</span> آمده از اهورا پرسیده میشود، کاایش پیشترائیش یعنی پیشه ها کدامند؟در پاسخ گوید: اتروه ؛ رئه اشتاو و آسترفشونیگس، هوئی تیش یعنی : آتربانان - ارتشتاران - کشاورزان گله پرور - دستورزان، در گزارش پهلوی همین بندهوئی تیش به هوتخش ترجمه شده . واژه ٔ هوئی تیش از ریشه ٔ هوئیتی آمده است . این کلمه معناً با هوتخش پهلوی مترادف، ولی از حیث ریشه با آن فرق دارد چه خود هوئیتی از مصدر هو بمعنی بکار بستن و آماده ساختن و فشردن (در موردهوم ) و پختن و جوشاندن و راندن و زادن (در مورد کودکان اهریمنی ) آمده در صورتی که هوتخش پهلوی کلمه ای است مرکب که اشتقاق آن در ذیل بیاید. (از مزدیسنا وتأثیر آن در ادبیات پارسی تألیف محمد معین صص <span class=\"hlight\" dir=\"rtl\">٤٠١</span>- <span class=\"hlight\" dir=\"rtl\">٤٠٥</span>). و جرجی زیدان درباره ٔ طبقات اجتماعی ایرانیان مینویسد: هنگام پیدایش اسلام در ایران دو طبقه ٔ خاصه و عامه وجود داشت طبقه ٔ عامه از بومیان تشکیل می یافت و به زراعت و صنعت و کسب و کار و خدمت اشتغال داشتند این بومیان مخلوطی از آریائیها و ترکها و تورانیها و دیلمها بودند که به مرور زمان با یکدیگر اختلاطیافته و موقع ظهور اسلام آنها را (طاجیه ) میخواندند که معنای آن معلوم نیست ودر هر حال طاجیه قومی نیرومند و تنومند بودند. طبقه ٔ خاصه ٔ رجال کشوری و لشکری و مذهبی از باقیماندگان پادشاهان پیشین بودند. به این معنی که پس از پادشاه و خاندان سلطنتی شهری گان ها یعنی اشراف شهری درجه ٔ اول محسوب میگشتند و مانند بتریقهای روم بشمار می آمدند، پس از شهری گان طبقه ٔ دهگان از نژاد پادشاهان پیش می آید. دهگانان زمین دار بودند و طاجیه را استثمار میکردند. دهگانان به پنج طبقه تقسیم میشدند و گاه هم به مقام امارت می رسیدند، مانند امیر بخارا که او را بخار خدا میگفتند و در زمان ظهور اسلام «هرات خدا» در هرات حکومت میکرد. گاه دهگانان مانند طاجیان بسادگی میزیستند. در زمان ظهور اسلام کشور ایران تحت نظر پادشاهان ساسانی به دست فرمانروایان متعدد، به نام مرزبان اداره میشد و معنای اصلی مرزبان سرحددار میباشد. بعضی از این مرزبانان بخصوص مرزبانان نقاط دوردست استقلال کامل داشتند و دارای القاب مخصوصی بودند. مثلاً مرزبان سیستان رتبیل و مرزبان سمندگان مرانگان و مرزبان طخارستان جیگویه و مرزبان بلخ سپهبد و مرزبان مرورودباذان و مرزبان طالقان شهرک و مرزبان فرغانه اخشید و غیره لقب داشتند و در پاره ای از نقاط دیگر مانند: سرخس، مرو، طوس، مرزبانان بطور عادی حکومت میکردند. بالاترین و با نفوذترین طبقات ایران موبدان یا کاهنان زرتشتی بودند که حتی بر شهریگان ها نیز برتری داشتند و رئیس آنان را موبد موبدان میخواندند مقام موبدمانند مقام کاهن یهود و اسقف مسیحی است . موبد موبدان مانند رئیس اسقفهای مسیحی میباشد با این فرق که نفوذ موبدان از نفوذ و قدرت پادشاهان بیش بود و داوران نیز از میان موبدان انتخاب شده، میان مردم داوری میکردند. در ممالک ایران دسته ها و گروه هائی بودند که نام و نشان معینی داشتند و در یک شهر میزیستند و یا از این شهر به آن شهر میرفتند، مانند: اسواران، احمران و غیره . (از ترجمه ٔ تاریخ تمدن اسلام صص <span class=\"hlight\" dir=\"rtl\">١٦</span> - <span class=\"hlight\" dir=\"rtl\">١٧</span>). و نیز جرجی زیدان درباره ٔ طبقات مردم در شام و عراق آرد: روابط دولت و رعایا در آن ایام طوری بوده که ا</font></div>'),
(175969, 'طبقات اعلی', '<span class=\"hlight\">طبقات اعلی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت ِ اَ لا ]</font></b> (ترکیب وصفی، اِ مرکب ) از طبقات عالم مثال است . رجوع به طبقات عالم مثال و حکمت اشراق ص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span> شود.<br /></font></div>'),
(175970, 'طبقات افلاک', '<span class=\"hlight\">طبقات افلاک .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت ِ اَ ]</font></b> (ترکیب اضافی، اِ مرکب ) طبقه های آسمانها. <BR><font color=\"Blue\">◄</font> طبقه های افلاک عالم مثال . رجوع به حکمت اشراق ص <span class=\"hlight\" dir=\"rtl\">٢٣٥</span> و عالم مثال شود.<br /></font></div>'),
(175971, 'طبقات الارض', '<span class=\"hlight\">طبقات الارض .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ تُل ْ اَ ]</font></b> (ع اِ مرکب ) زمین شناسی . ژئولوژی . چینه شناسی . (فرهنگستان ) <span class=\"hlight\">:</span> <br />در طبقات زمی افکند، بیم <br />زلزلةالساعة شی ٔ عظیم .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(175972, 'طبقات النیران', '<span class=\"hlight\">طبقات النیران .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ تُن ْ نی ]</font></b> (ع اِ مرکب ) از طبقات عالم مثال . رجوع به ص <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> حکمت اشراق شود.<br /></font></div>'),
(175973, 'طبقات جحیم', '<span class=\"hlight\">طبقات جحیم .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت ِ ج َ ]</font></b> (ترکیب اضافی، اِ مرکب ) از طبقه های عالم مثال است . ورجوع به حکمت اشراق ص <span class=\"hlight\" dir=\"rtl\">٢٣٥</span> و طبقات عالم مثال شود.<br /></font></div>'),
(175974, 'طبقات جنان', '<span class=\"hlight\">طبقات جنان .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت ِ ج َ ]</font></b> (ترکیب اضافی، اِ مرکب ) از طبقات عالم مثال است .رجوع به طبقات عالم مثال و حکمت اشراق ص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span> شود.<br /></font></div>'),
(175975, 'طبقات حکما', '<span class=\"hlight\">طبقات حکما.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت ِ ح ُ ک َ ]</font></b> (ترکیب اضافی، اِ مرکب ) سهروردی در حکمت اشراق طبقات حکما را بدینسان بیان کرده است : و ایشان را طبقاتی است بدینسان : حکیم الهی متوغل در تاله یعنی حکمت ذوقی بدون توغل در بحث یا حکمت بحثی . و حکیمی که در حکمت بحثی توغل دارد، ولی درحکمت تاله یا ذوقی او را دست نیست و حکیم الهی که هم در حکمت ذوقی (تاله ) و هم در حکمت بحثی توغل کرده باشد. دیگر حکیمی الهی که در حکمت ذوقی (تاله ) متوغل است، ولی در حکمت بحثی متوسط یا ضعیف است . دیگر حکیم متوغل در بحث و متوسط یا ضعیف در تاله . دیگر طالب تاله و بحث . یا فقط طالب تاله یا تنها طالب بحث . و اگر در روزگار حکیمی پدید آید که در تاله و بحث هر دومتوغل باشد، ریاست بدو اختصاص خواهد داشت و او خلیفه ٔ خدا خواهد بود. و اگر چنین کسی یافت نشود. پس حکیم متوغل در تاله و متوسط در بحث خلیفةاﷲ است و اگر چنین حکیمی هم یافت نشود، حکیم متوغل در تاله و بدون توغل در بحث این مقام را خواهد داشت . و زمین هرگز ازحکیم متوغل در تاله خالی نیست و هر آنکه در بحث متوغل باشد و در تاله توغلی نداشته باشد به ریاست اختصاص نمی یابد، زیرا عالم از متوغل در تاله خالی نمی ماندو او از کسی که فقط بحکمت بحثی میپردازد شایسته تر است . زیرا خلافت ناگزیر از تلقی است . و منظور من از این ریاست، این نیست که به غلبه و زور آنرا به دست آورند، بلکه گاهی ممکن است امام متاله که بر جهان مستولی است در ظاهر هم آشکار باشد و گاهی هم ممکن است از انظار ناپیدا گردد و این چنین کسی را کافه ٔ عارفان «قطب » مینامند، چه او را ریاست است هرچند در نهایت گمنامی باشد و هرگاه سیاست به دست وی افتد آن عصر و زمان نورانی خواهد بود و اگر زمان از تدبیر الهی خالی باشد، ظلمات و تیرگی بر جهان چیره خواهد بود و بهترین جویندگان، طالبان تاله و بحث و سپس طالبان تاله و آنگاه طالبان بحثند. (حکمت اشراق ص <span class=\"hlight\" dir=\"rtl\">١٢</span>). رجوع به همان کتاب ص <span class=\"hlight\" dir=\"rtl\">٣٠٦</span>، <span class=\"hlight\" dir=\"rtl\">٣٠٧</span> شود.<br /></font></div>'),
(175976, 'طبقات عالم مثال', '<span class=\"hlight\">طبقات عالم مثال .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت ِ ل َ م ِ م ِ]</font></b> (ترکیب اضافی، اِ مرکب ) این جهان (عالم مثال ) را طبقاتی است و در هر طبقه ٔ آن انواعی از آنچه در جهان ما یافت میشود وجود دارد. ولی آنها را نهایتی نیست و در برخی از آن طبقات گروهی از فرشتگان و نیکان و برگزیدگان بشر سکونت دارند و در طبقات دیگری دسته ای از فرشتگان و اهریمنانند و طبقات مزبور و آنچه در آنها هست بشمار نیاید و جز یزدان کس نداند و هر آنکه به طبقه ٔ برتر برسد آن را از طبقه ٔ پیش از آن لطیف تر ونیک منظرتر یابد و روحانیت فزونتر و لذات عظیمتری در آن بیند. و پایان طبقات که برترین آنهاست، مجاور انوار عقلی است و بسیار بدان انوار همانند است . و جز خدای کس شگفتیهای این جهان نداند. (از حاشیه ٔ حکمةالاشراق چ کربن ص <span class=\"hlight\" dir=\"rtl\">٢٤٠</span>). و در ص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span> آرد: و باید دانست که طبقات عالم مثال هرچند بسیار است و جز خدای و مبادی عالی هیچکس شماره ٔ آنها را نداند. ولی طبقات مزبوررا نهایت و پایانی است در صورتی که اشخاص و موجودات هر طبقه که هم از انواع موجودات جهان ما باشند و هم موجودات دیگری - غیرمتناهی اند و برخی از این طبقات اعلی شریف و نورانی است که عبارت از طبقات جنانند و از آنها نیکبختان متوسط برخوردارند و طبقات جنان نیزدر شرف متفاوتند و برخی از آنها تیره و مظلم اند و آنها طبقات جحیم میباشند که اهل آتش در آنها رنج میبرند و آنها هم در شدت ظلمت و وحشت متفاوتند. و برخی از این طبقات «جحیم » هم فروتر هستند. و طبقه ٔ سافله بسیار ظلمانی است و آن آخرین طبقه بشمار می آید و پیوسته به افق عالم حس است که در آن بزه کاران بشر و جن سکونت دارند. و باقی طبقاتی که میان دو طبقه ٔ عالی و سافلند بشمار نیایند و در هر طبقه قومی سکونت دارند که عدد آنها را نهایت نیست و این اقوام یا از فرشتگان و یا از جن و شیاطینند. (حاشیه ٔ حکمت اشراق ص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span>). و هم آرد: انوار مجرد به دو گونه تقسیم شوند: انوار قاهر که هیچ علاقه ای با برزخ ها ندارند نه ذاتاً و نه عملاً و در این انوار قاهر انواری برتر و انواری صوری وجود دارد که ارباب اصنامند، گونه ٔ دیگر انوار مجرد انوار مدبر برزخها باشند... و انوار قاهر برتر عبارت از طبقه ٔ طولی است که در نزول از مرتبه ٔ اعلی پایه به پایه است و برخی با بعضی دیگر از حیث نزول از بلندی تفاوت دارند و بعلت شدت نورانیت و نیروی گوهر و نزدیکی آن بوحدت حقیقی و کمی جهت ظلمانی هیچ جسمی از آن حاصل نمیشود و اگر از هر یک جسمی حاصل آید آن اجسام هم مانند ترتب علل خود بی تفاوت و بطور یکسان ترتب خواهند یافت . و درباره ٔ ارباب اصنام گوید: و آن طبقه ٔ عرضی برابر و غیرمترتب در نزول است . که عبارت ارباب اصنام نوعی جسمانی باشند و آنها بر دو گونه اندیکی از جهت مشاهدات حاصل آید و دیگری از جهت اشراقات و این مشاهدات و اشراقات از طبقه ٔ طولی حاصل گردد و از این رو که انوار حاصل از مشاهدات شریفتر از انوار حاصل از اشراقات است و هم جهان مثالی اشرف از عالم حسی است، پس اشرف علت اشرف و اخس علت اخس باشد بر حسب آنکه در هر یک از دو جهان همانندی است ؛ زیرا هرچه در عالم حس از قبیل : افلاک و ستارگان و مرکبات و نفوس متعلق به آنها وجود دارد، نظیر آن در عالم مثال نیز یافت میشود. و همچنانکه در انوار اشراقی ناگزیر باید نوری باشد که از لحاظ نورانیت و عشق از دیگر انوار عظیم تر باشد که آن را علت فلک برتر حسی میدانند. همچنین ناگزیر باید در انوار مشاهده ای نیز نوری عظیمتر باشد و آن علت فلک برتر مثالی است و همچنانکه فلک برتر بر هر دو عالم محیط است و هیچ چیز از اشیائی که فروتر از آن است با آن برابر و همانند نیست، بلکه فلک مزبور کاملترین اجسام اوست و نسبت به دیگر اجسام قاهر میباشد. همچنین حکم علت عقلی آن نسبت به ارباب اصنامی که در طبقه ٔ عرضی است بهمین قیاس است . رجوع به متن و حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span> و <span class=\"hlight\" dir=\"rtl\">١٤٦</span> و <span class=\"hlight\" dir=\"rtl\">١٥٥</span> همان کتاب شود.<br /></font></div>'),
(175977, 'طبقات عین', '<span class=\"hlight\">طبقات عین .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت ِ ع َ ]</font></b> (ترکیب اضافی، اِ مرکب ) صلبیه، مشیمیه، شبکیه، عنکبوتیه، قرنیه، ملتحمه . (از برهان ذیل هفت حجله ٔ نور). و صاحب غیاث ذیل هفت پرده ٔ چشم (هفت طبقه ) آرد: هفت پرده ٔ چشم از این قرار است : <span class=\"hlight\" dir=\"rtl\">١</span>- طبقه ٔ ملتحمه که از همه بیرون است و مماس با هواست . <span class=\"hlight\" dir=\"rtl\">٢</span>- قرنیه . <span class=\"hlight\" dir=\"rtl\">٣</span>- عنبیه و لون آن مختلف است در اشخاص . <span class=\"hlight\" dir=\"rtl\">٤</span>- عنکبوتیه . <span class=\"hlight\" dir=\"rtl\">٥</span>- شبکیه . <span class=\"hlight\" dir=\"rtl\">٦</span>- مشیمیه . <span class=\"hlight\" dir=\"rtl\">٧</span>- صلبیه . مابین عنبیه و عنکبوتیه رطوبتی است که بیضی نام دارد و مابین عنکبوتیه و شبکیه دو رطوبت اند: یکی جلیدی و دیگری زجاجی . (غیاث از حاشیه ٔ چهارمقاله چ معین ). و رجوع به پرده ٔ چشم شود.<br /></font></div>'),
(175978, 'طبقات نژادی', '<span class=\"hlight\">طبقات نژادی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت ِ ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) شعب مختلف از یک نژاد <span class=\"hlight\">:</span> طبقات نژادی عرب شش است : شعب : مانند مضر. قبیله : مانند کنانه . عماره : مانند قریش . بطن : مانند قصی . فخذ:مانند هاشم . فصیلة: مانند بنوعباس . (سمعانی ص <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(175979, 'طبقاماون', '<span class=\"hlight\">طبقاماون .</span> <font color=\"DarkGreen\"><b>[ طَ وَ ]</font></b> (معرب، اِ) لغت یونانی . ماهیت آن نباتی است، برگ آن شبیه به برگ انگور بستانی با شعبه های بسیار و گل آن سیاه و کوچک و تخم آن شبیه به جاورس است . (فهرست مخزن الادویه ).<br /></font></div>'),
(175980, 'طبقدار', '<span class=\"hlight\">طبقدار.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (نف مرکب ) حمالی که بار مردم را با طبق بخانه ٔ صاحبش برد.<br /></font></div>'),
(175981, 'طبقری', '<span class=\"hlight\">طبقری .</span> <font color=\"DarkGreen\"><b>[ طَ ق َ ]</font></b> (اِ) طبقچه را گویند. (برهان ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> بمعنی کنار و دامن هم هست . (برهان ). <BR><font color=\"Blue\">◄</font> جا و مقامی باشد غیرمعلوم . (برهان ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br />یکی نیشکر داشت بر طبقری <br />چپ و راست گردید بر مشتری .<br /><font color=\"Red\">سعدی (بوستان ).</font><br /></font></div>'),
(175982, 'طبقلو', '<span class=\"hlight\">طبقلو.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) دهی است از دهستان آتش بیک بخش سراسکند شهرستان تبریز، واقع در <span class=\"hlight\" dir=\"rtl\">٢٥</span>هزارگزی شمال باختری سراسکند و <span class=\"hlight\" dir=\"rtl\">١٦</span>هزارگزی شوسه ٔ تبریز به میانه . کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">١٥٥</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات و حبوبات . شغل اهالی زراعت و گله داری . راه آن مالرو است . (ازفرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(175983, 'طبقه بندی', '<span class=\"hlight\">طبقه بندی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ب َ ]</font></b> (حامص مرکب ) (در حیوان و نبات و غیره ) رده بندی . (فرهنگستان ). صف بندی . تبویب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبقه بندی کردن </span> ؛ رده بندی کردن . تبویب کردن .<br /></font></div>'),
(175984, 'طبقه ده', '<span class=\"hlight\">طبقه ده .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ق َ دِ ]</font></b> (اِخ ) موضعی است از میان درود در فرح آباد مازندران . (سفرنامه ٔ استرآباد و مازندران تألیف رابینو ص <span class=\"hlight\" dir=\"rtl\">١٢٠</span> بخش انگلیسی ).<br /></font></div>'),
(175985, 'طبقه کلا', '<span class=\"hlight\">طبقه کلا.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ق َ ک َ ]</font></b> (اِخ ) موضعی است از نیافت در هزارجریب مازندران . (سفرنامه ٔ استرآباد و مازندران تألیف رابینو ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span> بخش انگلیسی ).<br /></font></div>'),
(175986, 'طبقچه', '<span class=\"hlight\">طبقچه .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b>(اِمص ) طبق کوچک . طبق خرد. بشقاب خرد. (آنندراج ).<br /></font></div>'),
(175987, 'طبقگران', '<span class=\"hlight\">طبقگران .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ گ َ ]</font></b>(اِخ ) دروازه ٔ طبقگران در سیستان <span class=\"hlight\">:</span> بیرون شدن ملک مُعظم بدر شهر، دروازه ٔ طبقگران و ... منتصف ربیعالاَّخر سال <span class=\"hlight\" dir=\"rtl\">٦٦٠</span> هَ . ق . (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٤٠١</span>).<br /></font></div>'),
(175988, 'طبقی', '<span class=\"hlight\">طبقی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِ) نوعی جامه است <span class=\"hlight\">:</span> و کتان و طبقی باید پوشید (اندر فصل تابستان ) و کرباس نرم گازر شست که بتن بازنگیرد. (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(175989, 'طبل', '<span class=\"hlight\">طبل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) دهل زدن . (منتهی الارب ).<br /></font></div>'),
(175990, 'طبل', '<span class=\"hlight\">طبل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) دهل یک رویه باشد یا دورویه . (منتهی الارب ) (زمخشری ). تبیره . (فرهنگ اسدی خطی متعلق به نخجوانی ). شندف . (فرهنگ اسدی ). کوس . (دهار). نقاره . دبداب . کنارة. کبر. عرکل : عرطبه ؛ طبل یاطبل حبشی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نقاره ٔ کلان . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> نوعی نقاره ٔ خرد. (آنندراج ). ج، طبول، اطبال . <BR><font color=\"Blue\">◄</font> قسمی طبل در بنگاله <span class=\"hlight\">:</span> و سی زنند که هر روزی گرد این بت برآیند با طبل و دف و پای کوفتن . (حدود العالم ص <span class=\"hlight\" dir=\"rtl\">٤</span>).<br />چو برخیزد آواز طبل رحیل <br />به خاک اندر آید سر شیر و پیل .<br /> <font color=\"Red\">فردوسی .</font><br />بزد طبل و طغرل شد اندر هوا<br />شکیبا نبد مرغ فرمان روا.<br /> <font color=\"Red\">فردوسی .</font><br />چو خورشید بر چرخ بگشاد راز<br />سپهدار جنگی بزد طبل باز.<br /> <font color=\"Red\">فردوسی .</font><br />ناگاه صوت طبل قافله آمد (کذا)<br />گفتم آواز طبل نامد پر کس .<br /> <font color=\"Red\">غضایری (از فرهنگ اسدی خطی نخجوانی ).</font><br />رعد پنداری طبال همی طبل زند<br />بردر بوالحسن بن علی بن موسی .<br /> <font color=\"Red\">منوچهری .</font><br />امیر فرمود تا خلعت احمد راست کردند، طبل و علم و کوس و آنچه به آن رود که سالاران را دهند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٧٠</span>).<br />آن کس که زمین و چرخ وافلاک نهاد<br />بس داغ که او بر دل غمناک نهاد<br />بسیار لب چو لعل و زلفین چو مشک <br />در طبل زمین و حقه ٔ خاک نهاد.<br /> <font color=\"Red\">خیام .</font><br />آنجا طبل دید (روباه ) در پهلوی درختی افکنده . (کلیله و دمنه ).<br />بطبل نافه ٔ مستسقیان بخورد جراد<br />بنای روده ٔ قولنجیان بپشک ذباب .<br /> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٥٤</span>).</font><br /> <BR><font color=\"Blue\">◄</font> غولک سیم که بهندی کولک است . <BR><font color=\"Blue\">◄</font> خلق . یقال : ماادری ای الطبل هو؛ ای اَی ّالناس هو. (منتهی الارب ). مردم . <BR><font color=\"Blue\">◄</font> جامه ای است یمانی که نگار طبل دارد، یا جامه ٔ مصری است . جامه ٔ یمنی یا مصری مُوَشّی که بر آن صورت طبل منقوش است . <BR><font color=\"Blue\">◄</font> باج . و منه هو تحت الطبلیه ؛ ای دراهم الخراج (منتهی الارب ) (آنندراج ). قسط و نجمی از خراج . <BR><font color=\"Blue\">◄</font> بمعنی طبله ٔ عطار هم آمده است . طبق عطرفروشان <span class=\"hlight\">:</span> <br />دو زلفش را بمالیدم به دو دست <br />سرای از بوی اوشد طبل عطار.<br /> <font color=\"Red\">فرخی .</font><br />گفت بر پرنیان ریشیده <br />طبل عطار شد پریشیده .<br /> <font color=\"Red\">عنصری .</font><br />باغ همچون تخت بزازان پر از دیبا شود<br />باد همچون طبل عطاران پر از عنبر شود.<br /> <font color=\"Red\">عنصری .</font><br />به دیباها و زیورهای شهوار<br />ز تخت و طبل بزازان و عطار.<br /> <font color=\"Red\">ویس و رامین .</font><br />این جهان را کند از بوی چو طبل عطار<br />وین زمین را کند از رنگ چو تخت بزاز.<br /> <font color=\"Red\">امیرمعزی .</font><br />و رجوع به ترکیب طبل عطار شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دریده شدن طبل </span> ؛ کنایه از برملا افتادن راز کسی و رسوا گشتن . (از آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل از زیر گلیم برآمدن </span> ؛ کنایه از ظاهر شدن راز کسی . (غیاث اللغات ) (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل امان زدن </span> ؛ زنهار و امان خواستن <span class=\"hlight\">:</span> <br />روز میدان چون گذارد جرأتت پا در میان <br />میزند خصم از طپیدنهای دل طبل امان .<br /> <font color=\"Red\">شفیع اثر (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل ِ باز</span> ؛ طبلی باشد چون باز را بر مرغان آبی سر دهند دوال بر آن طبل میزنند، و از آن آواز مرغان میپرند، پس باز یکی از آنها را شکار میکند. میرشکاران و قراولان اسب دارند، و ترکان اکثر دارند. (آنندراج ). دهل خردی که پیش کوهه ٔ زین برای شکار کردن ملوک زنند <span class=\"hlight\">:</span> <br />ز شاهین و چرغ آسمان بسته ابر<br />زمان از غو طبل بازان هژبر.<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />طبل باز تو هر آنجاکه به آواز آید<br />نسر طائر کند از قله ٔ گردون پرواز<br />سلمان ساوجی (از فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span>).<br />بصحرائی که ترک من شکارانداز میگردد<br />دل قالب تهی گردید و طبل باز میگردد.<br /> <font color=\"Red\">میر معز فطرت (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل باز برای خود میزند</span> ؛ کنایه از آن است که حرف پوچ میزند، و کسی گوش نمیکند. (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل بازگشت </span> ؛ آن است که روزانه چون دو فوج با هم جنگ می کردند، وقت شام طبل بازگشت میزدند تا هر دو فوج بخیمه گاه روند. این معنی از قصه ٔ حمزه معلوم است بلکه آنجا دیده شده . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل به گلیم کشیدن </span> ؛کنایه از پنهان داشتن امری که بغایت آشکار بود <span class=\"hlight\">:</span> <br />طبلی به گلیم فقر درکش <br />کاقبال کلاه ازین نمد کرد.<br /> <font color=\"Red\">نورالدین ظهوری (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل بلخی </span> ؛ به اصطلاح لوطیان، مقعد. (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل بندار</span> ؛ قسط خراج در مصر: یک طبل بندار خراج گذاردن، یا دو، یا بیشتر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل پنهان زدن، طبل در زیر گلیم زدن یا کوفتن، طبل در گلیم زدن </span> ؛ هر سه کنایه از پنهان داشتن امری است که آن ظاهر و هویدا بود و شهرت یافته باشد. (برهان ). کاری که اثر آن بزودی هویدا گردد <span class=\"hlight\">:</span> <br />طبل پنهان چه زنی طشت من از بام افتاد.<br /> <font color=\"Red\">؟</font><br />نبینی که از ما غمی شد ز بیم <br />همی طبل کوبد بزیر گلیم .<br /> <font color=\"Red\">فردوسی .</font><br />طبلی بود در زیر گلیم میزدند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٥٢</span>).<br />خسروا شاها میرا ملکا دادگرا<br />پس از این طبل چرا باید زد زیر گلیم .<br /> <font color=\"Red\">ابوحنیفه ٔ اسکافی .</font><br />وگرت بست به بند قوی این دیو بزرگ <br />خامش و طبل مزن بیهده در زیر گلیم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />رعد و ابر است طبل زیر گلیم <br />چون بغرید موکب ظفرش .<br /> <font color=\"Red\">شهاب الدین غزنوی .</font><br />گاه طبلی زنم بزیر گلیم .<br />گاه تیغی کشم بزیر سپر.<br /> <font color=\"Red\">مسعودسعد (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٥٦</span>).</font><br />طبل بدخواه تو در زیر گلیم حادثه ست <br />تا ملک زد بی نیازی را علم بر بام تو.<br /> <font color=\"Red\">انوری .</font><br />صیت صداش مشرق و مغرب فروگرفت <br />دست نبوت تو چو زد طبل در گلیم .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />سیه گلیمی من شد ز عارض تو پدید<br />زند ازین پس حسن تو طبل زیر گلیم .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />بلی مه زند طبل زیر گلیم <br />چو خورشید تابان شود در غطا.<br /> <font color=\"Red\">کمال اسماعیل .</font><br />رعد از آن طبل زد بزیر گلیم <br />تا زند لاله خیمه در صحرا.<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />من نخواهم زد دگر از خوف و بیم <br />این چنین طبل هوا زیر گلیم .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل زیر گلیم </span> ؛ کنایه است از پوشیدن امری سخت آشکار و پنهانکاری ریاکارانه <span class=\"hlight\">:</span> <br />دلم گرفت زسالوس و طبل زیر گلیم <br />خوشا دمی که بمیخانه برکنم علمی .<br /> <font color=\"Red\">حافظ.</font><br />سپید مهره ٔ خورشید و کوس چرخ تراست <br />بطبل زیر گلیم از چه گشته ای مغرور.<br /> <font color=\"Red\">کاتبی .</font><br />عشق در پیران بود چون طبل در زیر گلیم <br />در جوانان عشق شورانگیز عشق روستاست .<br /> <font color=\"Red\">صائب .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل تهی </span> ؛ لاف بی معنی <span class=\"hlight\">:</span> <br />ز فریاد و فغان طبل تهی سیری نمیدارد<br />ندارد گوسفند آن کس که در بند شکم باشد.<br /> <font color=\"Red\">؟ (آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">فلان طبل تهی است </span> .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل جدال </span> ؛ طبل جنگ . طبلی که در روز جنگ نوازند <span class=\"hlight\">:</span> <br />مرا ستاره ٔ بختی که نیست پنداری <br />زده ست با افق این دیار طبل جدال .<br /> <font color=\"Red\">نورالدین ظهوری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل جنگ زدن </span> ؛ نواختن طبل در روز پیکار <span class=\"hlight\">:</span> <br />آسمان روزی که از خورشید طبل جنگ زد<br />صلح کل آمد به دامان دل ما چنگ زد.<br /> <font color=\"Red\">میرزا جلال اسیر. (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل حیدر رازی </span> ؛ فراهانی علیه الرحمة در شرح این بیت اوحدالدین انوری <span class=\"hlight\">:</span> <br />تیغ تو تیغ حیدر عربی <br />کوس تو طبل حیدر رازی <br />آورده که شخصی بوده از دیاری که همیشه لاف شجاعت زدی، و از برای اثبات این دعوی طبل برداشته، از شهر بیرون رفتی که من بجنگ شیر میروم . و اگر احیاناً شیری بلکه روباهی دیدی، طبل را از دوش فروگرفتی و آن طبل را با طبل شکم نواختی چون او را از نواختن این دو طبل سؤال کردندی، جواب دادی که نواختن طبل برای آن است که شیر بترسد، و نواختن طبل شکم را علت آن است که من نیز میترسم . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل در زیر گلیم بودن یا ماندن </span> ؛ کنایه از پوشیده ماندن راز کسی . (غیاث اللغات ).<BR>۩ کنایه از بی نام و نشان بودن باشد. (برهان ). بی نام و نشان ماندن، چه رسم است که چون پادشاهی یا امیری بمیرد، طبل و نقاره ٔ او را واژگون ساخته، و گلیمی بر آن انداخته، همراه تابوت او میبرند <span class=\"hlight\">:</span> <br />کوس شاه از فراز پیل زده <br />نه چو طبل عدوش زیر گلیم .<br /> <font color=\"Red\">ابوالفرج رونی .</font><br />کوس قدر تو فوق و تخت فلک <br />خصم تو طبل مانده زیر گلیم .<br /> <font color=\"Red\">انوری .</font><br />موافقان تو بر بام چرخ برده عَلَم <br />مخالفان ترا طبل مانده زیر گلیم .<br /> <font color=\"Red\">انوری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل رحیل </span> ؛ طبل کوچ . آن طبل که وقت کوچ کردن از منزل بزنند. (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل رسوائی زدن </span> ؛ کنایه از رسوائی آشکار کردن <span class=\"hlight\">:</span> <br />رمزی از بوالعجبیهای نظربازان است <br />طبل رسوا زدن و شیوه ٔپنهان دیدن .<br /> <font color=\"Red\">صائب (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل زدن </span> ؛ نواختن طبل . رجوع به همین ماده شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل سامعه </span> ؛ قسمتی از گوش .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل سکندر</span> ؛ طبل منسوب به اسکندر مقدونی <span class=\"hlight\">:</span> <br />گر صدائی میکنی گوش از تهی مغزی پر است <br />شوکت آوازه ٔ طبل سکندر هیچ نیست .<br /> <font color=\"Red\">میرزا جلال اسیر (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل سلیمانی </span> ؛ طبل منسوب به سلیمان نبی <span class=\"hlight\">:</span> <br />شکوه وحدتش روزی که زد طبل سلیمانی <br />دل موری طپید و اضطراب دهر پیدا شد.<br /> <font color=\"Red\">میرزا جلال اسیر (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل سوم زدن عسس </span> ؛ طبلی که نیم شب زنند برای امتناع سیر مردم در کوی و برزن <span class=\"hlight\">:</span> <br />ملک خفت و عسس طبل سوم زد<br />شدیم از زحمت اغیار فارغ .<br /> <font color=\"Red\">نظیری نیشابوری (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل صُبح </span> ؛ طبلی که در بامدادان برای بیداری سربازان زنند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل طغرل </span> ؛ طبلک بازیاران <span class=\"hlight\">:</span> <br />فتاده غو طبل طغرل در ابر<br />گریزان ز گرد سواران هزبر.<br /> <font color=\"Red\">؟ (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل عطار</span> ؛ طبق عطرفروشان <span class=\"hlight\">:</span> <br />باد شبگیری بر زلف سیاهش بوزید<br />طبل عطار شد از بوی همه لشکرگاه .<br /> <font color=\"Red\">فرخی .</font><br />طبل عطار است گوئی در میان گلستان <br />تخت بزّاز است گوئی در میان لاله زار.<br /> <font color=\"Red\">امیرمعزی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل فروکوفتن </span> ؛ به معنی طبل نواختن <span class=\"hlight\">:</span> <br />حسن تو هر جا که طبل عشق فروکوفت <br />بانگ برآمد که غارت دل و دین است .<br /> <font color=\"Red\">سعدی (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل واپس، طبل واپسین </span> ؛ هر دو بمعنی طبل ماتم است، یعنی طبلی که در عاشورا و ماتم نوازند. (برهان ) (آنندراج ). و کنایه از دم واپسین نیز میتوان گفت، چنانکه در شعرمیرزا صائب واقع شده . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل طبل عطار</span> ؛ خوشبو. مُعطر. فرح افزا.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل طبل میان تهی </span> ؛ اندرون خالی . کاواک .<BR>۩ بزرگ شکم . پرباد. متکبر <span class=\"hlight\">:</span> <br />تو چون طبلی که بانگت سهمناک است <br />ولیکن در میانت باد پاک است .<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">بزن بر طبل بیعاری که آن هم عالمی دارد</span> .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(175991, 'طبل', '<span class=\"hlight\">طبل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی است از بخش قشم شهرستان بندرعباس، واقع در <span class=\"hlight\" dir=\"rtl\">٩٠</span>هزارگزی باختر قشم و <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی جنوب راه مالرو قشم به باسعید.جلگه، گرمسیر و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٣٤٩</span> تن سکنه . آب آن از چاه و باران . محصول آنجا غلات . شغل اهالی صید ماهی . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(175992, 'طبل خواری', '<span class=\"hlight\">طبل خواری .</span><font color=\"DarkGreen\"><b>[ طَ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (حامص مرکب ) مفت خواری <span class=\"hlight\">:</span> <br />چون به انبازیست دنیا برقرار<br />هر کسی کاری گزیند زِ افتقار<br />طبل خواری در میانه شرط نیست <br />راه سُنت کار و مکسب کرد نیست .<br /> <font color=\"Red\">مولوی .</font><br />رجوع به طبل خوار شود.<br /></font></div>'),
(175993, 'طبل خوردن', '<span class=\"hlight\">طبل خوردن .</span> <font color=\"DarkGreen\"><b>[ طَ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ دَ ]</font></b> (مص مرکب ) کنایه از رم کردن و رمیدن باشد. (برهان ) (غیاث اللغات ). خود را کناره کردن . (غیاث اللغات ). رشیدی این مصراع را ازمولوی برای معنی رمیدن شاهد آورده است <span class=\"hlight\">:</span> <br />عمریست در عطای تو من طبل میخورم .<br />صاحب آنندراج پس از ذکر معنی گوید: چون صید از آواز طبل رم میخورد و به این علاقه بمعنی مأخوذ استعمال کرده اند <span class=\"hlight\">:</span> <br />از بحر یک نظاره ٔ او طبل میخورد<br />طاووس ِ کبک جلوه ٔ طوطی خرام ما.<br /> <font color=\"Red\">سعید اشرف (آنندراج ).</font><br />طبل از هجوم سنگ ملامت نمیخورم <br />چون کبک مست خنده به کهسارکرده ایم .<br /><font color=\"Red\">صائب (آنندراج ).</font><br /></font></div>'),
(175994, 'طبل زدن', '<span class=\"hlight\">طبل زدن .</span> <font color=\"DarkGreen\"><b>[ طَ زَ دَ]</font></b> (مص مرکب ) طبل فروکوفتن . طبل نواختن <span class=\"hlight\">:</span> <br />امشب سبکتر میزند این طبل بی هنگام را<br />یاوقت بیداری غلط بوده ست مرغ بام را.<br /> <font color=\"Red\">سعدی .</font><br />حیف بود آخر زدن بر طبل بدنامی دوال <br />کو مرا ناگه چنین افکند با سگ در جوال .<br /> <font color=\"Red\">ابن یمین .</font><br />شد بهار و ابر در فکر سرانجام گُل است <br />طبل شادی زن که فتح نوبه بر نام گل است .<br /> <font color=\"Red\">میرزا رضی دانش (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> دعوی کردن . بچیزی بالیدن <span class=\"hlight\">:</span> <br />بهاری ابر، به کف ّ تو نیک مانستی <br />به رعد اگر نزدی در زمانه طبل سخا.<br /><font color=\"Red\">(؟).</font><br /></font></div>'),
(175995, 'طبل زن', '<span class=\"hlight\">طبل زن .</span> <font color=\"DarkGreen\"><b>[ طَ زَ ]</font></b> (نف مرکب ) طبال . نقاره چی . دُهُل زن . (آنندراج ). طبلچی <span class=\"hlight\">:</span> <br />زیغبافان را با وشی بافان ننهند<br />طبلزن را ننشانند بر رودنواز.<br /> <font color=\"Red\">ابوالعباس .</font><br />بر لب آب، مطربان ترمذ و زنان ِ پایکوب و طبلزن، افزون سیصد تن دست به کار بردند.(تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٣٩</span>).<br /></font></div>'),
(175996, 'طبلاف', '<span class=\"hlight\">طبلاف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) رجوع به طبلاق شود.<br /></font></div>'),
(175997, 'طبلاق', '<span class=\"hlight\">طبلاق .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ترکی، اِ) اسم ترکی سُعد است . (تحفه ٔ حکیم مؤمن ). همین نام در فهرست مخزن الادویه بصورت «طبلاف » آمده است .<br /></font></div>'),
(175998, 'طبلاوی', '<span class=\"hlight\">طبلاوی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) او راست : شرحی بر شرح تصریف سعدالدین تفتازانی .<br /></font></div>'),
(175999, 'طبلباز', '<span class=\"hlight\">طبلباز.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) رجوع به محمد معروف به طبلباز شود.<br /></font></div>'),
(176000, 'طبلخانه', '<span class=\"hlight\">طبلخانه .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) نقاره خانه .<br /></font></div>'),
(176001, 'طبلخوار', '<span class=\"hlight\">طبلخوار.</span> <font color=\"DarkGreen\"><b>[ طَ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) مجان و رایگان خوار. مفتخوار. شکم خواره . شکم بنده . عبدُالبطن . پُرخوار. اکول <span class=\"hlight\">:</span> <br />جیفةاللیل است و بطال النهار<br />هرکه او شد غره ٔ این طبلخوار.<br /> <font color=\"Red\">مولوی .</font><br />لاف کیشی کاسه لیسی طبل خوار<br />بانگ طبلش رفته اطراف دیار.<br /> <font color=\"Red\">مولوی .</font><br />صوفیان طبلخوار لُقمه جو<br />سگدلان همچو گُربه روی شو.<br /> <font color=\"Red\">مولوی .</font><br />طبل و رایت هست ملک شهریار<br />سگ کسی که خواند او را طبلخوار.<br /> <font color=\"Red\">مولوی .</font><br />رایتان این بود و فرهنگ و نجوم <br />طبلخوارانید و مکارید و شوم .<br /> <font color=\"Red\">مولوی .</font><br />در حاشیه ٔ مثنوی چ علاءالدوله در شرح بیت ذیل از مثنوی <span class=\"hlight\">:</span> <br />کاندرین زندان بماند مستمر<br />یاوه تاز و طبلخوار است و مُضر.<br />نوشته است :طبل خوار رمیدن بود، میگوید: بیفایده ای بهر سو بتازد، و بی جنبش دست رمیدن گیرد، و زیان رساند - انتهی . مُفتخواری . رجوع به طبل خوردن شود.<br /></font></div>'),
(176002, 'طبلق', '<span class=\"hlight\">طبلق .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) دسته ٔ کاغذ. (آنندراج ). رجوع به طبق شود.<br /></font></div>'),
(176003, 'طبله', '<span class=\"hlight\">طبله .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) طبلة. صندوقچه ٔ کوچک . (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> سله ٔ عطار. بویدان : جونه ؛ طبل عطار. بیله، باله ؛ طبله ٔ عطار. قَسمة وقِسمة؛ طبله ٔ عطار. عتید؛ طبله یا حقه که در آن خوشبوی نهند. طبله ٔ مشک ؛ لطیمه ٔ مشک . ربعه ٔ عطار. دُرج ؛دوکدان و طبله ٔ زنان که در وی بوی خوش نهند. شریط؛ طبله ٔ زنان که در وی بوی خوش نهند. صونه ؛ طبله ای که در آن خوشبوی نگاه دارند. (منتهی الارب ) <span class=\"hlight\">:</span> <br />زین چو شود باغ طبله ٔ عطار<br />زآن شود راغ تخته ٔ بزاز.<br /> <font color=\"Red\">مسعودسعد.</font><br />هر آن چشمی که عشق از طبله ٔ خود سرمه ای دادش <br />سر آن تاجوربیند که بر خاکش قدم سازد.<br /> <font color=\"Red\">سنائی .</font><br />روی پرآژنگشان ازاشک خون مست آنچنانک <br />در میان طبله ٔ شنگرف پشت سوسمار.<br /> <font color=\"Red\">سنائی .</font><br />ای رنگ رخت گونه ٔ گلزار شکسته <br />یک موی تو صد طبله ٔ عطار شکسته .<br /> <font color=\"Red\">سوزنی .</font><br />به طبله های عقاقیر میر ابوالحارث <br />به میلهای بواسیر میر ابوالخطاب .<br /> <font color=\"Red\">خاقانی .</font><br />نیاساید مشام از طبله ٔ عود<br />بر آتش نِه که چون عنبر ببوید.<br /> <font color=\"Red\">سعدی .</font><br />دانا چو طبله ٔ عطار است، خاموش و هنرنمای . (گلستان ).<br /> <BR><font color=\"Blue\">◄</font> طبله ٔ بازیاری . چیزی است از مو بافته که قوشچیان بر دست دارند، چون آنرا مقابل باز بپرواز آمده حرکت دهند، باز بازآید و بر دست جای گیرد. (آنندراج ) <span class=\"hlight\">:</span> <br />آخر آن ترک شکارافکن به دام ما نشد<br />طبله از بال پری بستیم و رام ما نشد.<br /> <font color=\"Red\">سیدحسین جرأت بن سیدعلی سبزواری .</font><br /> <BR><font color=\"Blue\">◄</font> قسمی طبل در بنگاله .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">شکم طبله کردن </span> ؛ کنایه از شکم بارگی کردن . پر خوردن . طفیلی شدن <span class=\"hlight\">:</span> <br />اگر خودپرستی شکم طبله کن <br />دَرِ خانه ٔ این و آن قبله کن .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(176004, 'طبله خوار', '<span class=\"hlight\">طبله خوار.</span> <font color=\"DarkGreen\"><b>[ طَ ل َخوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) شعوری مترادف نخستین معنی طبلخوار آورده است، یعنی مفتخوار. (شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span>).<br /></font></div>'),
(176005, 'طبله نواز', '<span class=\"hlight\">طبله نواز.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ن َ ]</font></b> (نف مرکب ) طبل نواز. طباله : داربه ؛ زن ِ طبله نواز. (منتهی الارب ).<br /></font></div>'),
(176006, 'طبله کردن', '<span class=\"hlight\">طبله کردن .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ک َ دَ]</font></b> (مص مرکب ) آماس کردن گچ و امثال آن و فاصله پیدا شدن میان آن با دیوار یا سقف که مقدمه ٔ افتادن باشد.جدا شدن و آماس کردن و گونه شدن گچ یا کاهگل بنا.<br /></font></div>'),
(176007, 'طبلچی', '<span class=\"hlight\">طبلچی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص مرکب، اِ مرکب ) دُهُل زن . طبال .<br /></font></div>'),
(176008, 'طبلک', '<span class=\"hlight\">طبلک .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِمصغر) دُپلک . طبل خرد. (آنندراج ). کوبه . (مهذب الاسماء) (زمخشری ) عرطبه . (السامی ). دبدبة. دمامة. (زمخشری ): کوبه ؛ طبلک باریک میان . (منتهی الارب ). نقاره ٔ جُفتی . (ناظم الاطباء) <span class=\"hlight\">:</span> با وی طبلک میزدند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤١٤</span>).<br />سالها این مرگ طبلک میزند<br />گوش تو بیگاه جنبش میکند.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> بویدان . جونه . <BR><font color=\"Blue\">◄</font> کلاه و تاج درویشان . عصابه . (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبل و طبلک بازیاران </span> ؛ طبلی خُرد که برای برانگیختن مرغان شکاری بکار است : نقاره ٔ کوچک باشد که بازداران و میرشکاران همراه خود دارند هرگاه که صید برابر زمین نشسته یا در آب شناور ببیند، آن نقاره را میزنند تا از آواز آن صید از جای خود برخاسته بپرواز آید و ایشان باز را بر آن سر دهند. (غیاث اللغات ) (آنندراج ). طبلی است کوچک که نواختن آن بازهای شکاری را بسوی شکار حرکت میدهد <span class=\"hlight\">:</span> <br />چو در نالیدن آمد طبلک باز<br />درآمد مرغ صیدافکن به پرواز.<br /> <font color=\"Red\">نظامی .</font><br />در آن آماج کو کردی کمان باز<br />ز طبل زهره کردی طبلک باز.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(176009, 'طبلک نواز', '<span class=\"hlight\">طبلک نواز.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ن َ ]</font></b> (نف مرکب )آنکه طبلک نوازد: دردبی ؛ طبلک نواز. (منتهی الارب ).<br /></font></div>'),
(176010, 'طبلک نوازی', '<span class=\"hlight\">طبلک نوازی .</span> <font color=\"DarkGreen\"><b>[طَ ل َ ن َ ]</font></b> (حامص مرکب ) نواختن طبلک . شغل بازیار.<br /></font></div>'),
(176011, 'طبلی', '<span class=\"hlight\">طبلی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص نسبی ) منسوب به طبل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">استسقاء طبلی </span> ؛ نوعی از استسقاء، و آن بیماریی باشد که شکم بیمار بیاماسد و از هر سوی بکشد، و چون بر آن زنند آوای کوس کند.<br /></font></div>'),
(176012, 'طبلیة', '<span class=\"hlight\">طبلیة.</span> <font color=\"DarkGreen\"><b>[ طَ لی ی َ ]</font></b> (ع اِ) جامه ٔ یمنی یا مصری است مُوَشی که بر آن صورت طبل منقوش است . رجوع به طبل در این معنی شود.<br /></font></div>'),
(176013, 'طبن', '<span class=\"hlight\">طبن .</span> <font color=\"DarkGreen\"><b>[ طُ ب َ ]</font></b> (ع اِ) ج ِ طبنة. (منتهی الارب ).<br /></font></div>'),
(176014, 'طبن', '<span class=\"hlight\">طبن .</span> <font color=\"DarkGreen\"><b>[ طُ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ب ُن ن ]</font></b> (اِخ ) شهری در مغرب از سرزمین زاب که در منتهی الیه و پایان بلاد مغرب واقع است وگروهی از اعلام از این شهر برخاسته اند. و منسوب بدان طبنی است . (سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> ب ). رجوع به طبنة شود.<br /></font></div>'),
(176015, 'طبن', '<span class=\"hlight\">طبن .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ب َ ]</font></b> (ع مص ) فروپوشیدن آتش را تا نمیرد. (منتهی الارب ) (آنندراج ). آتش در زیر خاکستر پنهان کردن تا نمیرد. (تاج المصادر بیهقی ).<br /></font></div>'),
(176016, 'طبن', '<span class=\"hlight\">طبن .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ع اِمص ) زیرکی . (منتهی الارب ). طبانة و طبانیة و طبونة مثله . (آنندراج ).<br /></font></div>'),
(176017, 'طبن', '<span class=\"hlight\">طبن .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) طبانة. طبانیة. طبونة. زیرک شدن . (تاج المصادر بیهقی ) (منتهی الارب ). دانا گردیدن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176018, 'طبن', '<span class=\"hlight\">طبن .</span> <font color=\"DarkGreen\"><b>[ طَ ب ِ ]</font></b> (ع ص ) زیرک . دانا. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176019, 'طبن', '<span class=\"hlight\">طبن .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) گروه بسیار. (منتهی الارب ) (آنندراج ). یقال : ماادری ای الطبن هو؛ ای اَی ّالناس هو. (منتهی الارب ).<br /></font></div>'),
(176020, 'طبن', '<span class=\"hlight\">طبن .</span> <font color=\"DarkGreen\"><b>[طُ ]</font></b> (ع اِ) طنبور. (منتهی الارب ) (آنندراج ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> رباب . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176021, 'طبن', '<span class=\"hlight\">طبن .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طبنة.<br /></font></div>'),
(176022, 'طبن', '<span class=\"hlight\">طبن .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ <span class=\"hlight\" dir=\"rtl\">/</span> طُ ب َ ]</font></b> (ع اِ) بازیی است مر عربان را که بفارسی سدره نامند، و آن خطوطی است که بر زمین کشند. <BR><font color=\"Blue\">◄</font> مرداری که آنرا در دام کرکس و ددان اندازند برای صید. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176023, 'طبن', '<span class=\"hlight\">طبن .</span> <font color=\"DarkGreen\"><b>[ طِ ب َ ]</font></b> (ع اِ) ج ِ طبنة. (منتهی الارب ).<br /></font></div>'),
(176024, 'طبنة', '<span class=\"hlight\">طبنة.</span> <font color=\"DarkGreen\"><b>[ طُ ن َ ]</font></b> (ع اِ) آواز طنبور. <BR><font color=\"Blue\">◄</font> آواز رباب . <BR><font color=\"Blue\">◄</font> بازیچه ای است . (منتهی الارب ) (آنندراج ). ج، طُبَن، طُبْن .<br /></font></div>'),
(176025, 'طبنة', '<span class=\"hlight\">طبنة.</span> <font color=\"DarkGreen\"><b>[ طِ ن َ ]</font></b> (ع اِمص ) زیرکی .(منتهی الارب ) (آنندراج ) (مهذب الاسماء). ج، طِبَن .<br /></font></div>'),
(176026, 'طبنة', '<span class=\"hlight\">طبنة.</span> <font color=\"DarkGreen\"><b>[ طُ ن َ ]</font></b> (اِخ ) شهری است بر کرانه ٔ افریقیه نزدیک سرزمین مغرب کنار نهر زاب، این شهر به دست موسی بن نصیر گشوده شد و بیست هزار تن اسیر از آنجا گرفت، پادشاه آن که «کسیله » نام داشت گریخت . باروی این شهر با آجر بسیار سخت بنا شده، کوشک و حومه ای دارد. بین قیروان تا سجلماسة شهری از آن بزرگتر نیست . عمربن حفص هزار مرد المهدی بسال <span class=\"hlight\" dir=\"rtl\">٤٥٤</span> هَ . ق . بنای این شهر را نو ساخت . (معجم البلدان چ وستنفلدج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥١٥</span>). و آن مسقط گروهی از مشاهیر علماء و ادباء بوده است . رجوع به قاموس الاعلام ترکی و طبن شود.<br /></font></div>'),
(176027, 'طبند', '<span class=\"hlight\">طبند.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) دیهی است پهلوی اشنی از اعمال صعید مصر بر غربی رود نیل . و این محل را با اشنی بواسطه ٔ زیبائی که دارند، دو عروس نامند. (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨</span>).<br /></font></div>'),
(176028, 'طبندر', '<span class=\"hlight\">طبندر.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ دَ ]</font></b> (ع اِمص ) بدی . <BR><font color=\"Blue\">◄</font> فساد: یقال بینهم طبندر؛ ای شر. (منتهی الارب ).<br /></font></div>'),
(176029, 'طبنگ', '<span class=\"hlight\">طبنگ .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِ) طبقی است پهن وبزرگ از چوب که بقالان اجناس در آن کنند. (برهان ).<br /></font></div>'),
(176030, 'طبنی', '<span class=\"hlight\">طبنی .</span> <font color=\"DarkGreen\"><b>[ طُ ب ُن ْنی <span class=\"hlight\" dir=\"rtl\">/</span> طِ ]</font></b> (ص نسبی ) منسوب به «طُبن » یا «طِبن ». شهری در مغرب از سرزمین زاب که در منتهی الیه و پایان بلاد مغرب واقع است و گروهی از اعلام از این شهر برخاسته اند. (سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٦٨</span> ب ). رجوع به طبن و طبنة شود.<br /></font></div>'),
(176031, 'طبو', '<span class=\"hlight\">طبو.</span> <font color=\"DarkGreen\"><b>[ طَب ْوْ ]</font></b> (ع مص ) خواندن . یقال : طباه الیه طبواً؛خواند او را بسوی وی . (منتهی الارب ) (زوزنی ). <BR><font color=\"Blue\">◄</font> برگردانیدن کسی را از کاری : طباه عن الامر؛ برگردانید او را از آن کار. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176032, 'طبوس', '<span class=\"hlight\">طبوس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طبس، بمعنی گرگ . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span>).<br /></font></div>'),
(176033, 'طبوس', '<span class=\"hlight\">طبوس .</span><font color=\"DarkGreen\"><b>[ طَب ْ بو ]</font></b> (ع اِ) دبوس <span class=\"hlight\">:</span> اگر داند که ترکی به وی خواهد آمد، و وی را یک طبوس خواهد زد، از خوردن و خفتن لذت نیاورد، و باشد که آن ترک خود نیاید... و آمدن ملک الموت یقین است . و سختی جان کندن همانا صعبتر از طبوس ترکان بود. (کیمیای سعادت غزالی ).<br /></font></div>'),
(176034, 'طبوع', '<span class=\"hlight\">طبوع .</span> <font color=\"DarkGreen\"><b>[ طَب ْ بو ]</font></b> (ع اِ) جانورکی است زهردار. <BR><font color=\"Blue\">◄</font> قسمی از بوزینه که گزیدنش را درد سخت باشد. (منتهی الارب ) (آنندراج ). جنبنده ای است . گویند دیوه ای است . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> دانه ٔ سمی است که از گزیدن آن درد بسیار بهم میرسد. (فهرست مخزن الادویه ).<br /></font></div>'),
(176035, 'طبوع', '<span class=\"hlight\">طبوع .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طِبع.<br /></font></div>'),
(176036, 'طبول', '<span class=\"hlight\">طبول .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طبل .<br /></font></div>'),
(176037, 'طبونة', '<span class=\"hlight\">طبونة.</span> <font color=\"DarkGreen\"><b>[طَ ن َ ]</font></b> (ع اِمص ) زیرکی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176038, 'طبی', '<span class=\"hlight\">طبی .</span> <font color=\"DarkGreen\"><b>[ طَب ْی ْ ]</font></b> (ع مص ) بازگردانیدن : یقال طبیته عنه ؛ بازگردانیدم او را از وی . خواندن و کشیدن کسی را: طبیته الیه ؛ خواندم وی را بسوی وی کشیدم . (منتهی الارب ) (آنندراج ). خواندن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> نیک فروهشته و سست گردیدن سر پستان شتر ماده . یقال : طبیت الناقة طبیاً شدیداً. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176039, 'طبی', '<span class=\"hlight\">طبی .</span> <font color=\"DarkGreen\"><b>[ طُ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ]</font></b> (ع اِ)سر پستان مادیان و سِباع و خر و اسب و ناقه و جز آن . ج، اَطباء. (منتهی الارب ) (آنندراج ). و فی المثل : جاوَزَالحزام ُ الطبیین ؛ ای اشتد الامر و تفاقم . (منتهی الارب ). پستان چارپا. (غیاث اللغات ). پستان سباع . (دهار). پستان گوسفند و اشتر و سباع . (مهذب الاسماء).<br /></font></div>'),
(176040, 'طبی', '<span class=\"hlight\">طبی .</span> <font color=\"DarkGreen\"><b>[ طَ بی ی ]</font></b> (ع ص ) خِلف ُ طَبی ٌ؛ سر پستان مجیب که همواره شیر آید. (منتهی الارب ).<br /></font></div>'),
(176041, 'طبی', '<span class=\"hlight\">طبی .</span> <font color=\"DarkGreen\"><b>[ طِب ْ بی ]</font></b> (ص نسبی ) منسوب به «طِب » . لغت طِبی، کتاب فرهنگ کلمات مربوط به طب .<br /></font></div>'),
(176042, 'طبیب', '<span class=\"hlight\">طبیب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (... شیرازی ) رضاقلی هدایت آرد: نام شریفش آقا عبداﷲ، و از کمالات عقلیه و نقلیه آگاه . والدش حاج علی عسکر، و بمحامد صفات در آن شهر مشتهر، خود در خدمت علما وفضلا اکتساب کمالات نمود، در عقلیات تلمیذ ملا احمد یزدی و سایر الهیین و معاصرین بود، و حکمت طبیعی را درخدمت جناب فضیلت مآب حاج میرزا سیدرضی که الحق حکیمی عیسوی دم و طبیبی مبارک قدم بود اقتباس فرمود، پس از تکمیل کمالات بتحصیل حالات مایل شد، مدتی به تهذیب اخلاق و مجاهده ٔ نفسانیه سر آورد. و با فضلا و عرفا معاشرت کرد. غرض مردیست طالب ترک و تجرید و جاذب حال و توحید، بشوق صحبت فقیران و عزیزان از مصاحبت امرا و اعیان گریزان، غالب اوقاتش صرف تعبد و طاعات، و اکثر معالجاتش محضاللّه و الحسبات پاکی فطرتش از حصول قربت اهل دنیا مانع، و علو همتش بوصول معیشت مقرری قانع فقیر را بخدمتش کمال اخلاص است . این ابیات از اوست :<br />خوش گفت پیر عقلم دوش از سر کرامت <br />عشق بتان ندارد حاصل بجز ندامت <br />از حادثات گیتی ایمن شوی و فارغ <br />در کوی میفروشان سازی اگر اقامت .<br />بر هرچه نظر میکنم از وی اثری هست <br />واندر دل هر قطره ز بحرش گهری هست <br />بیهوده مرودر پی هر زاهد و واعظ<br />کز آن خبری نیست که با او خبری هست .<br />نکند حادثه ٔ دور فلک تأثیری <br />در دیاری که در آن خانه ٔ خماری هست .<br />غیر از گل حسرت از گل من <br />سر بر نزند گیاه دیگر.<br />ای آنکه ز هر ذره نمایان شده ای <br />از هر طرفی چو مهر تابان شده ای <br />در کعبه و دیر جمله را روی به توست <br />تو مقصد کافر و مسلمان شده ای .<br /> <font color=\"Red\">(ریاض العارفین ).</font><br />و هم او نویسد: نامش آقا عبداﷲ، خلف الصدق حاج علی اصغر جراح . مردی فاضل نکته دان و سالک صفوت بنیان بود. در اخلاق حسنه معروف و بصفات حمیده موصوف . در ایام توقف و توطن من بنده به شیراز که کمتر از قرنی نبود، غالب آن ایام با من قرین و منش همنشین . در ریاض العارفینش نام برده ام و بیتی چند از او آورده، سالی سه چار است که درگذشته . این ابیات از اوست (سپس دو بیت چهارم و پنجم را که در ریاض العارفین از وی آورده ذکر کرده است ). (مجمعالفصحا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span>).<br /></font></div>'),
(176043, 'طبیب', '<span class=\"hlight\">طبیب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) زیرک . <BR><font color=\"Blue\">◄</font> دانا. <BR><font color=\"Blue\">◄</font> نیک ماهر در کار خود. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) پزشک . (فرهنگستان ) (منتهی الارب ). پجشک . (دهار). طب . آسی . عرّاف . (منتهی الارب ). آنکه علاج بدن کند. دانا به دوا و علاج و دارو و درمان . حکیم . ج، اَطِبة، اطباء. (منتهی الارب ) (مهذب الاسماء) <span class=\"hlight\">:</span> <br />یکچند روز کار جهان دردمند بود<br />به شد که یافت بوی سمن را دوا طبیب .<br /> <font color=\"Red\">رودکی .</font><br />طبیب یداوی الناس و هو علیل ٌ<br />بسا طبیب که مایه نداشت درد فزود.<br /> <font color=\"Red\">منجیک .</font><br />هست طبیب بزرگ و هست منجم <br />فلسفی و هندسی و صاحب سودد.<br /> <font color=\"Red\">منوچهری .</font><br />بسیار طبیبانند که میگویند فلان چیز نباید خوردن ... آنگاه خود از آن بسیار خورند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٩٩</span>). این طبیبان را نیز داروهاست، و آن خرد است و تجارب پسندیده . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span>). روح را طبیبان و معالجان گزینند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span>). وی حاجتمند شود بطبیبی . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span>). ایشان را طبیبان اخلاق دانند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٩٩</span>). از طبیب پرسیدم، گفت : زار برآمده است . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>). در شهری مقام مکنید که در او حاکمی عادل، و پادشاهی قادر و قاهر، و بارانی دائم، و طبیبی عالم، و آبی روان نباشد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٨٦</span>). احمد و شکرخادم، تنی چند از خواص و طبیب و حاکم لشکر را بخواندند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٥٨</span>). طبیب چه تواند کرد با قضای آمده . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٠٤</span>). هر روز طبیب را میپرسید امیر، و وی می گفت : عارضه ای قوی افتاده . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٦٣</span>). طبیبی از سامانیان را صلتی نیکو داد پنجهزار دینار. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٦٣</span>). هر روز طبیب، امیر را نومید میکرد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>).طبیبک چون بند و طناب آورد، گفت : این پای بشکست . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٦٣</span>).<br />کجا عیسی طبیب آید کسی بیمار کی باشد.<br /> <font color=\"Red\">ادیب صابر.</font><br />چنین گوید برزویه ٔ طبیب، مقدم اطباء پارس که پدرمن از لشکریان بود. (کلیله و دمنه ). بدان التفات ننمائی که مردمان قدر طبیب ندانند. (کلیله و دمنه ).<br />خط بخون باز همی داد طبیب از پی جان <br />جان برون شد چه جوابیست خوش ار بازدهید.<br /> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span>).</font><br />مرا طبیب دل اندرزگونه ای کرده است <br />کز این سواد بترس از حوادث سودا.<br /> <font color=\"Red\">خاقانی .</font><br />طبیب ار چه داند مداوا نمود<br />چو مدت نماند مداوا چه سود.<br /> <font color=\"Red\">نظامی .</font><br />میباش طبیب عیسوی هُش <br />اما نه طبیب آدمی کش .<br /> <font color=\"Red\">نظامی .</font><br />وآن طبیب و آن منجم در لمع<br />دید تعبیرش بپوشد از طمع.<br /> <font color=\"Red\">مولوی .</font><br />بیمار عشق را بطبیب احتیاج نیست .<br /> <font color=\"Red\">سعدی .</font><br />چو به گشتی طبیب از خود میازار.<br /> <font color=\"Red\">سعدی .</font><br />دست بر هم زند طبیب ظریف <br />چون خرف بیند اوفتاده حریف .<br /> <font color=\"Red\">سعدی .</font><br />مرده و آنگه بطبیب آمده ای .<br /> <font color=\"Red\">خواجو.</font><br />کس نکند درد نهان از طبیب .<br />رجوع به امثال و حکم دهخدا شود.<br /></font></div>'),
(176044, 'طبیب', '<span class=\"hlight\">طبیب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (... اصفهانی ) رضاقلی هدایت آرد: نامش میرزا عبدالباقی . از اجله ٔ سادات موسوی، و در طبابتش دم عیسوی، فرزند میرزا محمد رحیم طبیب حکیم باشی شاه سلیمان صفوی بوده، و خود خدمت نادرشاه افشار را مینموده کمال جلال را داشته، بعد از نادر در اصفهان کلانتری کرده و برغبت طبع عالی خویش آن شغل بزرگ را به برادر کوچک خود، میرزا عبدالوهاب واگذاشته بفراغت پرداخته . و برادر مذکورش چندی نیز ایالت اصفهان کرده . علی الجمله وی در سنه ٔ <span class=\"hlight\" dir=\"rtl\">١١٦٨</span> هَ . ق . رحلت نمود. دیوانش دو سه هزار بیت و حاضر است . از اوست :<br />منزل بسی دور و بپا ما را شکسته خارها<br />واماندگان را مهلتی ای کاروانسالارها<br />گر باغبان روزی بما بندد در گلزارها<br />ما را نگاهی بس بود از رخنه ٔ دیوارها.<br />تا بر دلت از ناله غباری ننشیند<br />از بیم تو در سینه نهفتیم نفس را.<br />درین گلشن از آن شادم که نوپرواز مرغان را<br />رسد عهد گرفتاری چو بال و پر شود پیدا<br />نمیدانم زیان و سود بازار محبت را<br />همین دانم که کالای وفا کمتر شود پیدا.<br />حسرت مرغ اسیری کشدم کز دامی <br />کرده پرواز و به کنج قفسی افتاده ست .<br />بخدنگم چو زدی سینه ٔ گرمم بشکاف <br />که ز پیکان تو در دل اثری پیدا نیست <br />زورق اشکسته و امید سلامت دارم <br />در محیطی که ز ساحل اثری پیدا نیست .<br />تا کی نصیحتم که بخوبان مبند دل <br />ناصح ترا چکار دل من دل تو نیست .<br />دلخراش است دگر ناله ٔ مرغان چمن <br />در خَم ِ دام مگر تازه گرفتاری هست .<br />بر هم زدم از ذوق اسیری پر و بالی <br />ورنه سر پرواز ز کنج قفسم نیست .<br />ریخت گل از گلبن و آوخ که ما را باغبان <br />رخصت نظاره داد اکنون کز او آثار نیست .<br />منم که روز ازل از من آسمان و زمین <br />محبت پدری مهر مادری برداشت .<br />صیاد را نگر که چه بیداد میکند<br />نه میکشد مرا و نه آزاد میکند<br />خوش نغمه ٔ بلبلان چمن را چه شد که زاغ <br />بر شاخ گل نشسته و فریاد میکند<br />من ساده لوح و دلبر عاشق فریب من <br />هر دم به وعده ای دل من شاد میکند.<br />غمش در نهانخانه ٔ دل نشیند<br />بنازی که لیلی به محمل نشیند<br />مرنجان دلم را که این مرغ وحشی <br />ز بامی که برخاست مشکل نشیند<br />بنازم ببزم محبت که آنجا<br />گدائی بشاهی مقابل نشیند<br />خَلَد گر به پا خاری آسان برآرم <br />چه سازم بخاری که در دل نشیند.<br />ای وای بر آن مرغ گرفتار که از دام <br />پایش بگشایند و پریدن نگذارند.<br />عاشقان را مگر از خاره تنی ساخته اند<br />که به بیداد چنین دل شکنی ساخته اند.<br />خلق را بیم هلاک است و مرا غم که مباد<br />نشود کشتی ما غرق و بساحل برود.<br />در آن گلشن که گلچین در به روی باغبان بندد<br />نمیدانم به امید چه بلبل آشیان بندد.<br />از کین گر آن بیدادگر بر سینه ام خنجر زند<br />بادا بحل خون منش گر خنجر دیگر زند<br />شکرانه ٔ خواب خوشت مپسند بیرون درش <br />ناکرده خوابی صبحدم گر حلقه ای بر در زند.<br />قسمتم کاش بدان کوی کشد دیگر بار<br />که از آن مرحله من دل نگران بستم بار<br />بی تو بر سینه زنم هرچه درین ناحیه سنگ <br />بی تو بر دل شکنم هرچه درین بادیه خار.<br />هجران بسر رسید و دلم گرم ناله باز<br />پایان منزل است و جرس در فغان هنوز.<br />هرچند بر آن عارض گلگون نگرد کس <br />دل میکشدش باز که افزون نگرد کس .<br />چه دامست اینکه هر مرغی که میگردد گرفتارش <br />نمی آید بخاطر پرفشانیهای گلزارش .<br />از وصالم چه تمتع که تو ای آفت هوش <br />تا نشینی به کنارم ز میان برخیزم .<br />از ما نهفته با دگران یاربوده ای <br />ما غافل و تو همدم اغیار بوده ای <br />جائی که شب شدند حریفان تمام مست <br />باور که میکند که تو هشیار بوده ای .<br />شب چو بمیرم بسر کوی تو<br />زنده شوم صبحدم از بوی تو.<br />میروم دمبدم از خود بمن ای باد صبا<br />میتوان یافت که از دوست پیامی داری .<br />کردی چو شهیدم مکن آلوده بخونم <br />دامان که حریفان نشناسند کدامی .<br />تا عشق مرا فاش نمیدانستی <br />با من ره پرخاش نمیدانستی <br />در عاشقی خویش مرا شهره ٔ شهر<br />دانستی و ای کاش نمیدانستی .<br /> <font color=\"Red\">(مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span>).</font><br />و نیز رجوع به تاریخ ادبیات ادوارد براون ترجمه ٔ رشیدیاسمی ج <span class=\"hlight\" dir=\"rtl\">٤</span> و قاموس الاعلام ترکی شود.<br /></font></div>'),
(176045, 'طبیب', '<span class=\"hlight\">طبیب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) غلام مصطفی یکی از متأخران شعرای فارس و از اهالی هندوستان است، وی در جوانی درگذشته است . از اوست :<br />گر به اغیار وفا خواهی کرد<br />با که ای یار جفا خواهی کرد<br />بسمل از تیر نگه، ای کجباز<br />راست فرما که کرا خواهی کرد؟<br /><font color=\"Red\">(قاموس الاعلام ترکی ).</font><br /></font></div>'),
(176046, 'طبیب الدولتین', '<span class=\"hlight\">طبیب الدولتین .</span> <font color=\"DarkGreen\"><b>[ طَ بُدْ دَ ل َت َ ]</font></b> (اِخ ) رجوع به داودبن ناصر اغبری موصلی شود.<br /></font></div>'),
(176047, 'طبیب القلب', '<span class=\"hlight\">طبیب القلب .</span> <font color=\"DarkGreen\"><b>[ طَ بُل ْ ق َ ]</font></b> (ع ص مرکب، اِ مرکب )(اصطلاح تصوف ) شخصی را گویند که عارف بود بعلم توحید، و قادر باشد به ارشاد و تکمیل مریدان . کذا فی کشف اللغات . (کشاف اصطلاحات الفنون ) (آنندراج ). <BR><font color=\"Blue\">◄</font> زهره که مطربه ٔ فلک است . (آنندراج ) (شعوری ). <BR><font color=\"Blue\">◄</font> سرودگوی خوش الحان و خوب صورت و مطبوع طبع.<br /></font></div>'),
(176048, 'طبیب النفیس', '<span class=\"hlight\">طبیب النفیس .</span> <font color=\"DarkGreen\"><b>[ طَ بُن ْ ن َ ]</font></b> (اِخ ) رجوع به نفیس ابن عوض شود.<br /></font></div>'),
(176049, 'طبیب روحانی', '<span class=\"hlight\">طبیب روحانی .</span> <font color=\"DarkGreen\"><b>[ طَ ب ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) شیخ ِ عارف بدین گونه طب را گویند که بر تربیت و تکمیل روح توانا باشد. (از تعریفات جرجانی ).<br /></font></div>'),
(176050, 'طبیبانه', '<span class=\"hlight\">طبیبانه .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب ) به روش پزشکان .<br /></font></div>'),
(176051, 'طبیبة', '<span class=\"hlight\">طبیبة.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ع ص، اِ) مؤنث طبیب . زن بجشک . آسیة. <BR><font color=\"Blue\">◄</font> زمین دراز. <BR><font color=\"Blue\">◄</font> جامه ٔ دراز. <BR><font color=\"Blue\">◄</font> ابر دراز. <BR><font color=\"Blue\">◄</font> پوست . ج، طِباب . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176052, 'طبیبی', '<span class=\"hlight\">طبیبی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) یکی از شعرای عثمانی و از اهالی فلبه است . پیشه اش طبابت بوده و در قرن دهم هجری میزیسته است . (از قاموس الاعلام ترکی ).<br /></font></div>'),
(176053, 'طبیة', '<span class=\"hlight\">طبیة.</span> <font color=\"DarkGreen\"><b>[ طَ بی ی َ ]</font></b> (ع ص )کار عظیم و سخت . طَبواء. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176054, 'طبیخ', '<span class=\"hlight\">طبیخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) پختنی . (السامی فی الاسامی ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> نوعی از طعام عرب . <BR><font color=\"Blue\">◄</font> نوعی از شراب منصف که نیم جوشیده باشد. (منتهی الارب ) (آنندراج ) (بحر الجواهر). <BR><font color=\"Blue\">◄</font> گچ . <BR><font color=\"Blue\">◄</font> خشت پخته . (منتهی الارب ) (آنندراج ). و منه الحدیث : اذا اراداللّه ُ بعبد سوءً جعل ماله فی الطبیخین . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) منضج . جوشانده . آنچه جوشانیده و آب او را استعمال کنند.(فهرست مخزن الادویه ). آب چیز جوشانده شده . (غیاث اللغات ). آبی را گویند که چیزی اندر وی پخته باشند. (ذخیره ٔ خوارزمشاهی ). هذا النوع من المرکبات یطلب استعماله غالباً لمن عنده احتراق جل ما فیه من الفعل المطلوب لاجل الرطوبة البالة، و یعبر عن المطبوخات عند قوم بالمیاه، فیقال ماءُالزوفا ای طبیخها. و ربما ترجمت بالاشربة و هو خطاء لما سبق فی القوانین، و للاول وجه ٌ واضح ٌ و تطلب لذوی التحلیل و الحرارة و الضعف، فانها الطف لهم من اجرام الادویة، و قد تستعمل کالنقوع بعد ابتلاع نحوالحبوب للتحلیل . فان وقع فیها ما یسقط قواه بالطبخ . کالخیار شنبر و الترنجبین و الافتیمون، کفی مرسه بالماء. (تذکره ٔ داود انطاکی ). و اگر طبیخ بنفشه و خرمای هندی و خیار شنبر دهند با شیر خشت، صواب باشد. (ذخیره ٔ خوارزمشاهی ). و خداوند قولنج را (تریاق ) در طبیخ بادیان و زیره دهند. و از جهت بچه که در شکم مادر مرده باشد، طبیخ سداب دهند، یا در طبیخ مشکطرامشیع، یا در طبیخ ابهل و ترمس . (ذخیره ٔ خوارزمشاهی ). و از گل حکمت دیگها ساخته، اما فایده ٔ طبیخ آن جز بشام و چاشت آنها نرسید. (ذخیره ٔ خوارزمشاهی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبیخ الاصول </span> . رجوع به تذکره ٔ داود انطاکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٥</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبیخ الافتیمون </span> . رجوع به تذکره ٔ داود انطاکی ج <span class=\"hlight\" dir=\"rtl\">١</span>ص <span class=\"hlight\" dir=\"rtl\">٢٣٥</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبیخ الزوفا</span> . رجوع به تذکره ٔ داود انطاکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٧</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبیخ الصبر</span> . رجوع به تذکره ٔداود انطاکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٧</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبیخ الفواکه </span> . به تذکره ٔ داود انطاکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٦</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طبیخ ٌ من الشفاء</span> . رجوع به تذکره ٔ داود انطاکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٧</span> شود.<br /></font></div>'),
(176055, 'طبیخ', '<span class=\"hlight\">طبیخ .</span> <font color=\"DarkGreen\"><b>[ طِب ْ بی ]</font></b> (ع اِ) خربزه (لغة فی البطیخ ). (منتهی الارب ) (آنندراج ). بِطّیخ .<br /></font></div>'),
(176056, 'طبید', '<span class=\"hlight\">طبید.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) چیزی باشد که از جائی بجهد چون مرغی که بکشی بطپد. رجوع به طپید شود.<br /></font></div>'),
(176057, 'طبیدن', '<span class=\"hlight\">طبیدن .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b> (مص ) تپیدن باشد که حرکت کردن و برجستن است مر اعضای آدمی و حیوانات دیگر را بهنگام کشتن . (برهان ). لرزیدن . ضربان و حرکت کردن، مانند دل و رگ و نبض . (ناظم الاطباء).<br /></font></div>'),
(176058, 'طبیده', '<span class=\"hlight\">طبیده .</span> <font color=\"DarkGreen\"><b>[ طَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) گرم شده . تبیده . <BR><font color=\"Blue\">◄</font> مجازاً تبدار. باتب <span class=\"hlight\">:</span> <br />بطبع چون جگر عاشقان طبیده و گرم <br />برنگ چون علم کاویان خجسته بفال .<br /><font color=\"Red\">منجیک .</font><br /></font></div>'),
(176059, 'طبیره', '<span class=\"hlight\">طبیره .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) شهری است از بلاد اندلس و جمعی از فضلا از آن شهر برخاسته اند. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩</span>). رجوع به الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>، <span class=\"hlight\" dir=\"rtl\">٨٦</span>، <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> و نفح الطیب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٤١</span> و قاموس الاعلام ترکی شود.<br /></font></div>'),
(176060, 'طبیس', '<span class=\"hlight\">طبیس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) بحر طبیس ؛ دریای بسیارآب . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176061, 'طبیع', '<span class=\"hlight\">طبیع.</span> <font color=\"DarkGreen\"><b>[ طِب ْ بی ]</font></b>(ع اِ) میانه ٔ شکوفه ٔ نخستین خرمابن و لب آن . (منتهی الارب ) (آنندراج ). مغز طلع. (فهرست مخزن الادویه ).<br /></font></div>'),
(176062, 'طبیعت', '<span class=\"hlight\">طبیعت .</span><font color=\"DarkGreen\"><b>[ طَ ع َ ]</font></b> (ع اِ) طبیعة. سرشت که مردم بر آن آفریده شده . (منتهی الارب ) (آنندراج ). نهاد. آب و گِل . خوی .گوهر. (بحر الجواهر). سلیقه . فطرت . خلقت . طبع. ذات .طینت . جبلت . ضمیرة. غریزة. سجیة. جدیرة. خلیقة. اخذ. خلق . قریحه . عریکة. شیمة. شریة. تقن . توز. توس . سوس . بکلة. خشیبة. طِراز: لیس هذا من طرازک ؛ نیست این از طبیعت تو. (منتهی الارب ). قلیب . کیان <span class=\"hlight\">:</span> <br />چو کنعان را طبیعت بی هنر بود<br />پیمبرزادگی قدرش نیفزود.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> عنصر. طبایع اربعه : چهار عنصر خاک و آب و باد و آتش . <BR><font color=\"Blue\">◄</font> طبیعت پنجم نزد قدماء. طبیعت استحالت ناپذیر، و آن جوهر افلاک است، مقابل چهار طبیعت دیگر که خاک و آب و باد و آتش باشد. <BR><font color=\"Blue\">◄</font> مزاج : مزاج البدن ؛ آنچه اندام بدان سرشته شده از طبایع. (منتهی الارب ). ج، طبائع، طبایع <span class=\"hlight\">:</span> <br />چو کم خوردن طبیعت شد کسی را<br />چو سختی پیشش آید سهل گیرد.<br /> <font color=\"Red\">سعدی .</font><br />کنون بسختی و آسانیش بباید ساخت <br />که در طبیعت زنبور نوش باشد و نیش .<br /> <font color=\"Red\">سعدی .</font><br />هر که با بدان نشیند، اگر نیز طبیعت ایشان در او اثر نکند، بطریقت ایشان متهم گردد. سعدی (گلستان ).<br />تا بخواهد طبیعتت میخور<br />چون نخواهد دگر نشاید خورد.<br /> <font color=\"Red\">ابن یمین .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">طبیعت دزد است </span> ؛ یعنی اوضاع و اطوار همنشینان زود فراگیرد، کسی را که صحبت زود در او اثر کند، گویند: طبیعت دزدی دارد <span class=\"hlight\">:</span> <br />تا آنکه تو صاحب طبیعت شده ای <br />این حرف مثل شد که طبیعت دزداست .<br /> <font color=\"Red\">سعید اشرف (از آنندراج ).</font><br />کژدم از خبث طبیعت بزند سنگ به نیش .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> و در عرف علمای رسوم (تعریفات ) طبیعت یکی از قوای نفس کلی است ودر اجسام طبیعی سفلی ساریست و اجرام فاعل صور آن است که بر طبیعت سفلی منطبع میشوند. (از کشاف اصطلاحات الفنون ). عبارت از قوه ٔ ساریه در اجسام است که بدان جسم به کمال طبیعی خود می رسد. (از تعریفات جرجانی ). <BR><font color=\"Blue\">◄</font> (اصطلاح فلسفه ) قوه ٔ مدبره همه چیزهاست در عالم طبیعی که عبارت است از زیر فلک قمر تا مرکز زمین . (مفاتیح العلوم ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>). مبداء حرکت قوا که در او شعور باشد. طبیعت در اصطلاح علما بر معانی گوناگون اطلاق میشود از آنجمله مبداء اول حرکت چیزی است که بدان حرکت و سکون پدید می آید و سکون ذاتی است نه عرضی .و مراد به مبداء تنها مبداء فاعلی است و منظور از حرکت انواع چهارگانه آن است، از قبیل : اینیت و وضعیت و کمیت و کیفیت و مقصود از سکون چیزیست که مقابل همه ٔ انواع حرکات یاد کرده باشد، و حرکت بتنهائی ممکن نیست در آن واحد مبداء حرکت و سکون با هم باشد، بلکه باید به هر دو شرط متصف باشد و مراد از اینکه بدان حرکت و سکون پدید می آید، جسم است و بدان مبادی قسری وصناعی خارج میشود چه آنها مبادی حرکت و سکون با هم نیستند. و مقصود از «اول » پس از «مبداء اول » نفوس ارضی است چه در این نفوس مبادی حرکت و سکونند، مانند نمو کردن منتها این مبادی بوسیله ٔ استخدام طبایع و کیفیات و واسطه ٔ میل میان طبیعت و جسم هنگام تحرک است و آنها را از مبداء اول بودن خارج نمیکند، زیرا مبداء اول بمنزله ٔ آلت آنهاست و مقصود از ذاتی یکی از این دو معنی است نخست به قیاس نسبت به متحرک، یعنی به ذات خود تحرک دارد نه به سبب اینکه به حرکت قسری منجر گردد و دوم به قیاس نسبت به متحرک بدین معنی که جسم بذاته حرکت کند نه به سببی خارجی . و مراد از «نه عرضی » یکی از این دو معنی است : نخست به قیاس نسبت به متحرک که حرکت صادرشونده از آن به عرض صادر نشود، مانند حرکت کشتی . و دوم به قیاس نسبت به متحرک از این لحاظ که تحرک شی ٔ آن چیزیست که بعرض متحرک نباشد، مانند بت مسین، چه تحرک آن از حیث این است که آن بت است بالعرض نه بالذات . و معنی طبیعت از این نظر قریب معنی طبع است که شامل همه ٔ اجسام حتی فلک میشود و این گفتار محقق طوسی در شرح اشارات است . (از کشاف اصطلاحات الفنون ). رجوع به همان کتاب ذیل طبع و طبیعت شود. <BR><font color=\"Blue\">◄</font> (اصطلاح تصوف ) طبیعت، حقیقتی الهی است که فعاله ٔ همه ٔ صور باشد. و این حقیقت تفعیل صور اسمائی از حیث باطن آنها در ماده ٔ عمائی است، زیرا آفرینش و وجود یکیست و حقیقت آن جامع همه ٔ صور حقانی وجوبی و صور خلقی عالم هستی است، خواه روحانی باشد یا مثالی یا جسمانی بسیط یا مرکب . و صور در مرحله ٔ حقیقی کشفی علوی و سفلی است و علوی یا حقیقی است که همان صور اسماء ربوبیت است و حقایق وجوبی و ماده ٔ این صور و هیولای عماء و حقیقت فعاله برای آن یکی از مجموعه ٔ ذات الوهیت است . یا اضافی است که همان حقایق ارواح عقلی مهیمنیه و نفسیه است و ماده ٔ این صور روحانی نور است . و اما صور سفلی عبارت از حقایق امکانی است و آن هم به علوی و سفلی منقسم میشود. و از جمله ٔ علوی آن همان صور روحانی است که در پیش یاد کردیم و صور عالم مثال مطلق و مقید نیزاز آنجمله است و اما سفلی عبارت است از صور عالم اجسام غیرعنصری، مانند عرش و کرسی . و ماده ٔ آن جسم کل است همچنین صور عناصر و عالم عنصری از صور سفلی است و صور هوائی و ناری و صور مرکب از آنها از جمله ٔ عالم عنصری است و ماده ٔ این صور هوا و نار و هر چیزیست که از اختلاط آنها با دو عنصر ثقیل دیگر پدید آید. و نیز از جمله ٔ عالم سفلی صور سفلی حقیقی است که در پرورش دو عنصر سنگین یعنی زمین و آب حاصل میشوند و آنها سه صورتند: معدنی، نباتی و حیوانی . و هر یک از این عوالم بر صور جزئی دیگر مشتمل باشند که لایتناهی است و جز خدای کس شماره ٔ آنها را نداند. و حقیقت فعاله ٔالهی به باطن خود نسبت به صور آسمانی فاعل است و بظاهر طبیعت کلی است که مظهر آن صور کلیه ٔ عوالم است . (از کشاف اصطلاحات الفنون ) <span class=\"hlight\">:</span> <br />ببینی آن قامت چون سرو خرامان در خواب <br />که کند خرمن گل دست طبیعت بر سیم .<br /> <font color=\"Red\">ابوحنیفه ٔ اسکافی .</font><br />چوبد کردی مشو ایمن ز آفات <br />که واجب شد طبیعت را مکافات .<br /> <font color=\"Red\">ناصرخسرو.</font><br />طبیعت ندانم که باشد چه چیز<br />اگر توبدانی بگوئی رواست .<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> (اصطلاح پزشکی ) قوه ای که تدبیر بدن آدمی کندبی اراده و شعوری . <BR><font color=\"Blue\">◄</font> گاه اطلاق شود بر روانی و ناروانی شکم . (بحر الجواهر). <BR><font color=\"Blue\">◄</font> صاحب بحر الجواهر بنقل از علامه آرد: طبیعت در عرف طب برچهار معنی اطلاق شود: <span class=\"hlight\" dir=\"rtl\">١</span> - مزاج خاص . <span class=\"hlight\" dir=\"rtl\">٢</span> - هیئت ترکیبی . <span class=\"hlight\" dir=\"rtl\">٣</span> - قوه ٔ مدبره . <span class=\"hlight\" dir=\"rtl\">٤</span> - حرکت نفس . و پزشکان جمیع احوال بدن را به طبیعت مدبره ٔ بدن و فلاسفه به نفس نسبت میدهند و این طبیعت را قوه ٔ جسمانی مینامند. (از کشاف اصطلاحات الفنون ) <span class=\"hlight\">:</span> چند که این علامتها پدیدار آید، طبیعت را به تدبیرهائی پزاننده یاری باید داد. (ذخیره ٔ خوارزمشاهی ). <BR><font color=\"Blue\">◄</font> نفس چنانکه اطبا گویند طبیعت با مرض در بحران مقاومت میکند و مرادنفس ناطقه است . (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> صاحبان علم ادویه وقتی بالطبیعة گویند، مقابل بالخاصیة است، چنانکه مثلاً دوای مبردی برای محروری اَثَر او بالطبیعه است، ولی اگر حاری برای حروری نافع باشد، آن بالخاصیة است .<br /></font></div>'),
(176063, 'طبیعت شناس', '<span class=\"hlight\">طبیعت شناس .</span> <font color=\"DarkGreen\"><b>[ طَ ع َ ش ِ ]</font></b> (نف مرکب ) کنایه از طبیب و معالج باشد. (برهان ). طبیب حاذق <span class=\"hlight\">:</span> <br />امید عافیت آنگه بود موافق طبع<br />که نبض را به طبیعت شناس بنمائی .<br /> <font color=\"Red\">سعدی (از آنندراج ).</font><br />طبیعت شناسان هر کشوری <br />سخن گفت با هر یک از هر دری .<br /><font color=\"Red\">سعدی (بوستان ).</font><br /></font></div>'),
(176064, 'طبیعت کردن', '<span class=\"hlight\">طبیعت کردن .</span> <font color=\"DarkGreen\"><b>[ طَ ع َ ک َ دَ ]</font></b> (مص مرکب ) چون طفل رضیع خنده کند یا حرف زند، گویند طبیعت کرده است، یعنی طبیعت و استعدادی به هم رساند. و این محاوره است و سند این در نثر نعمت خان عالی دیده شده، در هند مستعمل است . (آنندراج ).<br /></font></div>'),
(176065, 'طبیعی', '<span class=\"hlight\">طبیعی .</span> <font color=\"DarkGreen\"><b>[ طَ عی ی ]</font></b> (ع ص نسبی ) منسوب به طبیعت . غریزی . جبلی . ذاتی . فطری . نهادی . سرشتی . گوهری . گُهری . خِلقی . مقابل ِ صناعی و عملی و مصنوعی و ساختگی و معمولی <span class=\"hlight\">:</span> <br />بخشش او طبیعی و گهریست <br />بخشش دیگران به روی و ریاست .<br /> <font color=\"Red\">فرخی .</font><br />چه بود عارض تو لاله ٔ طبیعی رنگ <br />نگه نمود مرا عنبر طبیعی خم .<br /> <font color=\"Red\">مسعودسعد.</font><br /><BR><font color=\"Blue\">◄</font> مخلوق مقابل مصنوع <span class=\"hlight\">:</span> رود بر دو ضرب است : یکی طبیعی و دیگری صناعی .. رود طبیعی آن است که آبهائی بود بزرگ که از گداز برف و چشمه هائی که از کوه و روی زمین بگشاید و برود، و خویشتن را راه کند، و رودکده ٔ وی جائی فراخ شود و جائی تنگ همی رود تا به دریائی رسد یا به به طیحه ای .(حدود العالم ). <BR><font color=\"Blue\">◄</font> صاحب کشاف آرد: چیزیست که به ذات مستند باشد خواه استناد آن به نفس ذات یا جزء یا لازم آن باشد و خواه مساوی یا اعم باشد، پس طبیعت منسوب بدان در این هنگام بمعنی حقیقت است . (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> و نیز مراد از طبیعی چیزیست که به صورت نوعی مستند باشد و ما در لفظ خبردر این باره بحث کردیم وامور طبیعی چیزهایی است که وجود انسان بر آنها مبتنی است . رجوع به طبیعت شود.<br /></font></div>'),
(176066, 'طبیعی', '<span class=\"hlight\">طبیعی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص نسبی ) (علم ...) دانشی است که از احوال اجسام طبیعی بحث میکند و موضوع آن جسم است . (از کشف الظنون ). و صاحب کشاف اصطلاحات الفنون آرد: طبیعی بر یکی از علوم مدون حکمت نیز اطلاق شود چه علم حکمت به دو گونه ٔ عملی و نظری تقسیم گردد و حکمت نظری به دانش طبیعی ریاضی و الهی منقسم می شود که آنها را به نامهای مابعدالطبیعة و ماقبل الطبیعه نیز نامند و طبیعیون کسانی هستند که در دانش طبیعی ممارست میکنند و نیز طبیعیون بر فرقه ای اطلاق شود که طبایع چهارگانه، یعنی حرارت و برودت و رطوبت و یبوست را می پرستند چه آنها را اصل وجود دانند و بعقیده آنان جهان از آنها مرکب است و این فرقه را طبایعیه نیز خوانند. (انسان کامل از کشاف اصطلاحات الفنون ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">نفس طبیعی </span> ؛ قوتی است که اجزاء جسم را نگاه دارد تا از یکدیگر متلاشی نشود، و آن را دو خادم است که یکی را خفت و دیگری را ثقل گویند. خفت قوتی است مائل بمحیط و ثقل بر عکس او. (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(176067, 'طبیعیات', '<span class=\"hlight\">طبیعیات .</span> <font color=\"DarkGreen\"><b>[ طَ عی یا ]</font></b> (ع ص، اِ) ج ِ طبیعی . علم طبیعیات . و او علم چیزهاست که به حس تعلق دارد، و اندر جنبش و گردشند. (دانشنامه ٔ علائی ).<br /></font></div>'),
(176068, 'طبیعیة', '<span class=\"hlight\">طبیعیة.</span> <font color=\"DarkGreen\"><b>[ طَ عی ی َ ]</font></b> (ع ص نسبی ) تأنیث طبیعی : علوم طبیعیة.<br /></font></div>'),
(176069, 'طبیعیون', '<span class=\"hlight\">طبیعیون .</span> <font color=\"DarkGreen\"><b>[ طَعی یو ]</font></b> (ع ص، اِ) ج ِ طبیعی (در حال رفع). علمای علم طبیعی . رجوع به طبیعی و ضحی الاسلام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٥</span> شود.<br /></font></div>'),
(176070, 'طبیعیین', '<span class=\"hlight\">طبیعیین .</span> <font color=\"DarkGreen\"><b>[ طَ عی یی ]</font></b> (ع ص، اِ) ج ِ طبیعی (در حال نصب و جر). حکمای طبیعیین . مقابل حکمای الهیین . رجوع به ضحی الاسلام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٧</span>، <span class=\"hlight\" dir=\"rtl\">١٢١</span>، <span class=\"hlight\" dir=\"rtl\">١٢٦</span>، <span class=\"hlight\" dir=\"rtl\">١٣١</span> شود.<br /></font></div>'),
(176071, 'طبیق', '<span class=\"hlight\">طبیق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) زمانه ٔ دراز. یقال : قام عنده طبیقاً؛ ای زماناً طویلاً. <BR><font color=\"Blue\">◄</font> موافق . برابر. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176072, 'طبیق', '<span class=\"hlight\">طبیق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ساعتی از شب . (منتهی الارب ) (آنندراج ). ج، طُبق .<br /></font></div>'),
(176073, 'طتو', '<span class=\"hlight\">طتو.</span> <font color=\"DarkGreen\"><b>[ طُ ت ُوو ]</font></b> (ع مص ) رفتن . یقال : طتا طُتواً. (منتهی الارب ).<br /></font></div>'),
(176074, 'طث', '<span class=\"hlight\">طث .</span> <font color=\"DarkGreen\"><b>[ طَث ث ]</font></b> (ع اِ) نوعی از بازیچه ٔ کودکان که می افکنند چوب مدور را. (منتهی الارب ) (آنندراج ). بازیی است کودکان را. و آن چنان است که چوبی مدور میاندازند، و از هم میربایند، و آن چوب را مطمثه گویند. (منتخب اللغات ). چکز.<br /></font></div>'),
(176075, 'طثر', '<span class=\"hlight\">طثر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص )سطبر گردیدن شیر و روغن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176076, 'طثر', '<span class=\"hlight\">طثر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) بطنی است از ازد. (منتهی الارب ).<br /></font></div>'),
(176077, 'طثرج', '<span class=\"hlight\">طثرج .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع اِ) مورچه . (منتهی الارب ) (آنندراج ). اسم نملی کوچک است . (فهرست مخزن الادویه ). مورچه ٔ زرد کوچک را گویند. (برهان ) (اختیارات بدیعی ). بچه ٔ مورچه .<br /></font></div>'),
(176078, 'طثره', '<span class=\"hlight\">طثره .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) نام وادیی است در دیار بنی اسد. (معجم البلدان ).<br /></font></div>'),
(176079, 'طثریة', '<span class=\"hlight\">طثریة.</span> <font color=\"DarkGreen\"><b>[ طَ ث َ ری ی َ ]</font></b> (اِخ ) نام مادر یزیدبن طثریة شاعر قشیری . (منتهی الارب ). و منوچهری به سکون ثاء آورده است ضرورت را <span class=\"hlight\">:</span> <br />بلبل نگوید این زمان لحن و سرود تازیان <br />قمری نگرداند زبان بر شعر ابن طثریه .<br /> <font color=\"Red\">منوچهری (دیوان چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>).</font><br />رجوع به ابن طثریه شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(176080, 'طثن', '<span class=\"hlight\">طثن .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِمص ) سبکی نشاط. <BR><font color=\"Blue\">◄</font> شادی . تنعم . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176081, 'طثو', '<span class=\"hlight\">طثو.</span> <font color=\"DarkGreen\"><b>[ طُ ث ُوو ]</font></b> (ع مص ) بازی کردن به غوک چوب . (منتهی الارب ). مترادف ِ طث ء. رجوع به طث ّ و طث ء شود.<br /></font></div>'),
(176082, 'طثور', '<span class=\"hlight\">طثور.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) ماست شدن شیر. (زوزنی ) (تاج المصادر بیهقی ). رجوع طَثر شود.<br /></font></div>'),
(176083, 'طثی', '<span class=\"hlight\">طثی .</span> <font color=\"DarkGreen\"><b>[ طَثا ]</font></b> (ع اِ) چوبهای خُرد. (منتهی الارب ). ج، طثیة.<br /></font></div>'),
(176084, 'طثیار', '<span class=\"hlight\">طثیار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) شیربیشه . <BR><font color=\"Blue\">◄</font> پشه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176085, 'طثیة', '<span class=\"hlight\">طثیة.</span><font color=\"DarkGreen\"><b>[ طَ ی َ ]</font></b> (ع اِ) الطثیةُ: شجرة تسمو نحوالقامة، شوکة من اصلها الی اعلاها، شوکها غالب علی ورقها، و ورقُها صغارٌ، و لها نُویَرَةٌ بیضاء تجرسها النحل و جمعها طثی کذا فی المحکم . (تاج العروس در مستدرکات ).<br /></font></div>'),
(176086, 'طثیثا', '<span class=\"hlight\">طثیثا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) جایگاهی است در مصر. (معجم البلدان ).<br /></font></div>'),
(176087, 'طجرسامن', '<span class=\"hlight\">طجرسامن .</span><font color=\"DarkGreen\"><b>[ طَ ج َ م ِ ]</font></b> (اِخ ) دهی است از دهستان سامن شهرستان ملایر، واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی جنوب باختری شهر ملایر و <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی باختر راه شوسه ٔ ملایر به بروجرد. جلگه، معتدل و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٨٠٥</span> تن سکنه . آب آن از قنات . محصول آن غلات، صیفی و لبنیات . شغل اهالی زراعت و گله داری . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(176088, 'طجرشت', '<span class=\"hlight\">طجرشت .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (اِخ ) تجریش . قصبه ٔ بلوک شمیران به قصران بیرونی به در ری <span class=\"hlight\">:</span> به دیه طجرشت از جهت خستگی هوا نزول فرمود چه حرارت هوابغایت بود. (راحةالصدور ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>). و متوجه دارالملک ری شد، تا آنجا زفاف سازد، و عروس مراد را در کنار آرد. چون بنزدیک مقصود رسید، در دیه طجرشت جهت دفع اذاء حرارت هوا بفضاء آن صحرا فرودآمد. (از العراضه ).<br /></font></div>'),
(176089, 'طجرعلوی', '<span class=\"hlight\">طجرعلوی .</span> <font color=\"DarkGreen\"><b>[ طَ ج َ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان ترک شهرستان ملایر، در <span class=\"hlight\" dir=\"rtl\">٢٧</span>هزارگزی شمال شهر ملایر، کنار راه اتومبیل رو علوی به گوجک . جلگه، معتدل و مالاریائی با <span class=\"hlight\" dir=\"rtl\">١١٤٤</span> تن سکنه . آب آن از قنات . محصول آنجا غلات، انگور و صیفی . شغل اهالی زراعت . صنایع دستی زنان قالی بافی است . راه آن اتومبیل رو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(176090, 'طجن', '<span class=\"hlight\">طجن .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) بریان کردن گوشت و جز آن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176091, 'طجنة', '<span class=\"hlight\">طجنة.</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (اِخ ) تحریفی است از طنجه . رجوع به طنجه شود. (المعرب حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">٢٢٣</span>).<br /></font></div>'),
(176092, 'طح', '<span class=\"hlight\">طح .</span> <font color=\"DarkGreen\"><b>[ طَح ح ]</font></b> (ع مص ) گُستردن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> به پاشنه خراشیدن . (منتهی الارب ) (آنندراج ) (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> مالیدن . <BR><font color=\"Blue\">◄</font> کوفتن چیزی را. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176093, 'طحا', '<span class=\"hlight\">طحا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) (بقصر) زمین فراخ و گشاده . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176094, 'طحاب', '<span class=\"hlight\">طحاب .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) موضعی است، ومر آن موضع را روزیست عظیم . (منتهی الارب ) (آنندراج ). جایگاهی است که چون واقعه ای در آن محل برای اعراب رخ داد، روز وقوع آن را یکی از روزهای تاریخی محسوب میدارند، و آن روز را به «یوم طحاب حومل » و «یوم ملیحة» نیز میخوانند. (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>).<br /></font></div>'),
(176095, 'طحار', '<span class=\"hlight\">طحار.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِمص ) نوعی از پیچاک شکم که در آن تنفس سخت باشد. <BR><font color=\"Blue\">◄</font> ژخیدن . (منتهی الارب ). سخت دم زدن .<br /></font></div>'),
(176096, 'طحاف', '<span class=\"hlight\">طحاف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) ابر بالارفته . لغة فی الخاء. (منتهی الارب ). رجوع به طخاف شود.<br /></font></div>'),
(176097, 'طحال', '<span class=\"hlight\">طحال .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) سپرز. (منتهی الارب ) (آنندراج ) (زمخشری ). اسپرز. ج، طُحُل . گویند اسب سپرز ندارد، و این مثل است در شتابروی، چنانکه گویند: شتر مراره ندارد؛ یعنی بددل است . (منتهی الارب ). اسبل . رجوع به سپرز شود. شیخ الرئیس گوید: طِحال : عضویست غیرحساس . (قانون چ تهران ص <span class=\"hlight\" dir=\"rtl\">١٧</span>، <span class=\"hlight\" dir=\"rtl\">٧٢</span>). نیکوترین سپرز آن بود که از حیوان فربه گیرند، از بهر آنکه بدی بوی آن کمتر از لاغر بود. شیخ الرئیس گوید: بهترین سپرزها سپرز خوک بود. معذلک کیموس وی بد بود و طبیعت وی گرم و خشک بود، و در وی قبض بود، و خون سودائی ازوی متولد شود، و وی دیر هضم شود، سبب عفونتی که دارد اولی آن بود که با روغن بسیار و پیه پخته کنند، و بر سر وِی شراب صافی و رقیق یا سرکه و کبر خورند. (اختیارات بدیعی ). غلیظ و کثیف و مولد سودا، و ذرور خون او که خشک کرده باشند، قاطع نزف الدم جراحات تازه است . (تحفه ٔ حکیم مؤمن ). طحال بپارسی سپرز و بترکی طلاق گویند. بهترینش آن بود که از حیوان فربه گیرند. طبیعتش گرم است در اول و گویند سرد و خشک است در دوم، شکم ببندد و خون سوداوی از او تولد کند، و مصلحش روغن و سرکه ٔ کبر است . طحال را به پارسی سپرز و بهندی تِلّی نامند. ماهیت آن : معروف است که عضوی است نرم سخیف کبودرنگ واقع در جانب چپ زیر قلب، و آن ادویه ٔ سودا متولد در کبد است برای ریختن قدری از آن بعد دفعفضول از معده بر فم معده، و از معده جهت انتباه آن به جوع برای دباغت معده، و داخل شدن قدری از آن در خون برای تغذیه ٔ بعض اعضاء صلبیه، چنانچه بتفصیل در کلیات فن طب مذکور است، و تکون آن از دم سوداوی است وآنچه میگویند فرس طحال ندارد، نیست چنین، مانند آنکه میگویند که شتر زهره ندارد، آن مثل است برای سرعت و جلادت فرس، و عدم جرأت و جسارت شتر، بهترین آن (طحال ) حیوان فربه جوان اهلی است . جهت آنکه ردائت آن کمتر است از حیوان پیربری . و شیخ الرئیس گفته : بهترین همه ٔ طحال خنزیر است . و طحال طیور بدترین همه . طبیعت آن : بارد یابس . افعال و خواص آن بطی ءالهضم، ردی ءالکیموس مولد خون سوداوی و ذرور و خشک خون آن ملصق و قاطع نزف الدم جراحات تازه، مصلح ردائت آن خالص کردن از عروق، و با روغن بسیار دنبه و پیه پختن، و بالای آن شراب رقیق آشامیدن است . بدان که از اعضای مفرده است، یعنی در بدن هر حیوانی از یک طحال بیش نیست، ولکن اطبای فرنگ میگویند که بندرت متعدد نیز دیده شده، و دربدن بعضی حیوانات تا پنج عدد. شنیده شده که اطبای فرنگ شکم سگی را شکافتند در جوف آن پنج عدد طحال یافتند و نیز شنیده شده که طحال سگی را بریده برآوردند، و باز آنرا ملتئم ساختند و آن سگ تا مدتی زنده بود. (مخزن الادویه ). باردٌ یابس فی الثالثة. یکون عن الخلط السوداوی، ردی الغذاء، فاسدالکیموس، لایتناول منه الاماله فائدةٌ مخصوصة، و هو مذکور عند اصوله . (ضریر انطاکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٧</span>). رجوع به همان کتاب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٤</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عِظَم ِ طحال </span> ؛ بزرگ شدن سپرز.<br /></font></div>'),
(176098, 'طحال', '<span class=\"hlight\">طحال .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) بیماریی است که در سپرز بهم رسد. (آنندراج ) (غیاث اللغات ) (اقرب الموارد).<br /></font></div>'),
(176099, 'طحال', '<span class=\"hlight\">طحال .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b>(ع اِ) نام گیاهی است .<br /></font></div>'),
(176100, 'طحال', '<span class=\"hlight\">طحال .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) نام سگی است . (منتهی الارب ).<br /></font></div>'),
(176101, 'طحال', '<span class=\"hlight\">طحال .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) موضعی است مر بنی غبر را. منه المثل : ضیعت البکار علی طِحال ؛ در حق شخصی گویند که طلب کند حاجت را از شخصی که بدی رسانده باشد او را. اصله ان سویدبن ابی کاهل، عیر بنی عبر بقوله :<br />من سره النیک بغیر مال <br />فالغبریات علی طحال .<br />ثم اسرسوید، فطلب الی بنی غبران یعینوه فی فکاکه، فقالوا له ذلک . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پشته ای است در حمی ضریة. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span>ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>).<br /></font></div>'),
(176102, 'طحالب', '<span class=\"hlight\">طحالب .</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ ]</font></b> (ع اِ) ج ِ طُحلب . (دهار).<br /></font></div>'),
(176103, 'طحالی', '<span class=\"hlight\">طحالی .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ص نسبی ) منسوب به طحال . <BR><font color=\"Blue\">◄</font> طحالی شکل . مانند سپرز.<br /></font></div>'),
(176104, 'طحالیه', '<span class=\"hlight\">طحالیه .</span> <font color=\"DarkGreen\"><b>[ طِ لی ی َ ]</font></b> (ع ص نسبی ) عضله ٔ طُحالیه . مستطیل و مسطح در جزء خلفی عنق و فوقی ظهر واقع شده . اتصالات از فوق در فاصله ٔ پست و بلندی که در میان دو خط منحنی است به قمحدوه و بسطح خلفی زائده ٔ حلمه ای و بزوائد اجنحه ٔ دو یا سه فقره ٔ اول عنق پیوسته، پس تارهای آن به تحت و انسی رفته بجزء تحتی رباط عنقی خلفی و بزوائد شوکیه دو فقره ٔ پائینی عنق و پنج فقره ٔ بالائی ظهر ملتصق میشود. مجاورات از خلف به ذوزنقه و مضرس کوچک فوقانی و مربع معین و زاویه ٔ وقصی حمله از قدام بمختلط و عضله ٔ طویل ظهر و عضله ٔ اجنحه مجاور است . عمل - اگر زوجا منقبض شوند، سررا منبسط مینمایند و اگر یکی منقبض شود، سر و گردن را بطرف خود برمیگرداند. (تشریح میرزا علی ص <span class=\"hlight\" dir=\"rtl\">٢٤٦</span>).<br /></font></div>'),
(176105, 'طحامر', '<span class=\"hlight\">طحامر.</span> <font color=\"DarkGreen\"><b>[ طُ م ِ ]</font></b> (ع ص ) کلان شکم . (منتهی الارب ).<br /></font></div>'),
(176106, 'طحان', '<span class=\"hlight\">طحان .</span> <font color=\"DarkGreen\"><b>[ طَح ْ حا ]</font></b> (اِخ ) بنابر گفته ٔ سمعانی جمعی از مشاهیر و افاضل رجال به نام طحان معروف بوده اند و بدین اسم نسبت داده میشده اند. (انساب سمعانی ).<br /></font></div>'),
(176107, 'طحان', '<span class=\"hlight\">طحان .</span> <font color=\"DarkGreen\"><b>[طَح ْ حا ]</font></b> (ع ص ) آسیابان . (منتهی الارب ) (آنندراج ). آسیاگر. <BR><font color=\"Blue\">◄</font> المنبسط من الارض . (اقرب الموارد). زمین خوار و هموار.<br /></font></div>'),
(176108, 'طحانة', '<span class=\"hlight\">طحانة.</span> <font color=\"DarkGreen\"><b>[ طَح ْ حا ن َ ]</font></b> (ع اِ) شتر بسیار.(منتهی الارب ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> آس اشتر.(مهذب الاسماء). آسیا که با شتر گردد. ستور آس . آسیاکه به ستور گردد. <BR><font color=\"Blue\">◄</font> آس که به آب گردد.<br /></font></div>'),
(176109, 'طحانة', '<span class=\"hlight\">طحانة.</span> <font color=\"DarkGreen\"><b>[ طِ ن َ ]</font></b> (ع اِمص ) آسیاگری . (منتهی الارب ) (آنندراج ). آسیابانی .<br /></font></div>'),
(176110, 'طحانة', '<span class=\"hlight\">طحانة.</span> <font color=\"DarkGreen\"><b>[ طَح ْ حا ن َ ]</font></b> (ع ص ) مؤنث طحان است . زنی که پیشه ٔ او آسیاگری باشد.<br /></font></div>'),
(176111, 'طحاوه', '<span class=\"hlight\">طحاوه .</span> <font color=\"DarkGreen\"><b>[ طَ وَ ]</font></b> (اِخ ) دهی است بمصر. (منتهی الارب ).<br /></font></div>'),
(176112, 'طحاوی', '<span class=\"hlight\">طحاوی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نظامی عروضی در چهارمقاله در ضمن مقاله ٔ دوم که بقای نام پادشاهان و بزرگان عصر را وابسته ٔ به نظم رائع و شعر شائع شعرا دانسته، طحاوی نامی را در ردیف شعرای آل سامان، مانند رودکی و هم طبقگان وی اسم برده، و محمد قزوینی در تعلیقاتی که بر چهارمقاله نوشته اند تذکر داده اند که : کذا فی النسخ الثلاثة، و معلوم نشد کیست . (متن ص <span class=\"hlight\" dir=\"rtl\">٢٨</span> و تعلیقات ص <span class=\"hlight\" dir=\"rtl\">١٣٠</span>). در نسخه ٔ س از لغت نامه ٔ اسدی که یکی از مآخذ طبع و نشر لغت نامه ٔ مزبور بوسیله ٔ عباس اقبال بود دو بیت ذیل را به طحاوی نسبت داده است :<br />لبت گوئی که نیم کفته گُل است <br />می و نوش اندرو نهفتستی <br />زلف گوئی ز لب نهازیده ست <br />به گله سوی چشم رفتستی .<br />ظاهراً طخاری باشد و این تصحیف از دست کتاب ناشی شده . رجوع به لغت نامه ٔ اسدی چ اقبال ص <span class=\"hlight\" dir=\"rtl\">١٠٥</span> و تعلیقات چهارمقاله چ معین شود.<br /></font></div>'),
(176113, 'طحاوی', '<span class=\"hlight\">طحاوی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) محمدبن حسن . او راست : شرح بر کتاب الاَّثار. (کشف الظنون ).<br /></font></div>'),
(176114, 'طحاوی', '<span class=\"hlight\">طحاوی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) احمد عبدالرحیم . ولادت وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٣٣</span> هَ . ق . و وفات او بسال <span class=\"hlight\" dir=\"rtl\">١٣٠٢</span>. هَ . ق .او راست : نهایةالمقصد و التوسل لفهم قولة الدور و التسلسل . و آن شرحی است در مبحث دور و تسلسل از حاشیه ٔ امیر بر شرح عبدالسلام که بر جوهرة تألیف پدر خویش ابراهیم لقانی نوشته و در بولاق مصر در سال <span class=\"hlight\" dir=\"rtl\">١٣٠٣</span> هَ . ق . بطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٣٤</span>).<br /></font></div>'),
(176115, 'طحاوی', '<span class=\"hlight\">طحاوی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابوجعفر احمدبن محمدبن سلمةبن سلامةبن عبدالملک الازدی الطحاوی . وی از قریه ٔ طحا که یکی از قرای مصر است میباشد. ولادت او بسال <span class=\"hlight\" dir=\"rtl\">٢٢٩</span> هَ .ق . و وفات وی در سال <span class=\"hlight\" dir=\"rtl\">٣٢١</span> هَ . ق . بوده، خواهرزاده ٔ مزنی فقیه شافعی است . خود از مذهب شافعی به مذهب حنفی بازگشت و با احمدبن طولون معاصر بوده است . مردی بینوا بود، و چندی از دستمزدی که برای کتابت جهت قاضی ابوعبیداﷲ محمدبن عبده دریافت میداشت، زندگانی و گذران میکرد تا مالی بدست آورد و عاقبت ریاست حنفیان درمصر بدو محول شد. سنش بهشتاد رسید، کتب بسیاری در فقه حنفی تألیف کرده و در تاریخ نیز او را تألیفی است . رجوع به فهرست ابن الندیم ص <span class=\"hlight\" dir=\"rtl\">٢٩٢</span> شود. یاقوت در معجم البلدان در ضمن ماده ٔ «طحا» بعد از ذکر نسب ابوجعفر گوید: و لیس من نفس طحا، و انما هو من قریة قریبه منها یقال لها طحطوط، فکره ان یقال طحطوطی، فنظن انه منسوب الی الضراط. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>). زرکلی در الاعلام کتب زیر را به طحاوی نسبت داده است : <span class=\"hlight\" dir=\"rtl\">١</span> - بیان السنة مطبوع رساله ای است . <span class=\"hlight\" dir=\"rtl\">٢</span> - المحاضر و السجلات . <span class=\"hlight\" dir=\"rtl\">٣</span> - شرح مشکل احادیث رسول اﷲ قریب یکهزار ورقه . <span class=\"hlight\" dir=\"rtl\">٤</span> - احکام القرآن . <span class=\"hlight\" dir=\"rtl\">٥</span> - الاختلاف بین الفقهاء، کتابی است بزرگ ولی توفیق اتمام آن نیافته است . (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>). مؤلف معجم المطبوعات العربیه از سیوطی نقل کرده، گوید: ابوجعفر طحاوی از طحطوحه میباشد که دهی است به نزدیک طحاو، و از قریه ٔ طحا نیست . و کتب زیر رااز وی نامبرده است : عقیدةالطحاوی با شرح آن از عمربن اسحاق الحنفی الهندی متوفی بسال <span class=\"hlight\" dir=\"rtl\">٧٧٢</span> هَ . ق . که درقازان بسال <span class=\"hlight\" dir=\"rtl\">١٣١١</span> بطبع رسیده . مشکل الاَّثار، در حدیث در چهار مجلد در حیدرآباد دکن به سال <span class=\"hlight\" dir=\"rtl\">١٣٣٣</span> چاپ شده است . شرح معانی الاَّثار، آن نیز در حدیث و در دو مجلد بسال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> در لکنهور هند طبع گردیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٣٢</span>). رجوع به ابوجعفر طحاوی و احمدبن محمدبن سلمة در همین لغت نامه و قاموس الاعلام ترکی شود.<br /></font></div>'),
(176116, 'طحاوی', '<span class=\"hlight\">طحاوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (ع ص نسبی ) منسوب به قریه ٔ طحاوه ٔ مصر.یا منسوب به طحاء یکی از چهار موضعی که در مصر بدین نام معروف میباشند. (منتهی الارب ) (انساب سمعانی ).<br /></font></div>'),
(176117, 'طحث', '<span class=\"hlight\">طحث .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) راندن چیزی رابدست . دفع کردن چیزی را. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176118, 'طحح', '<span class=\"hlight\">طحح .</span> <font color=\"DarkGreen\"><b>[ طُ ح ُ ]</font></b> (ع ص، اِ) خراشیده . <BR><font color=\"Blue\">◄</font> آنچه بدان خراشند. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176119, 'طحر', '<span class=\"hlight\">طحر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) بیرون انداختن چشم و چشمه خاشاک را. <BR><font color=\"Blue\">◄</font> راندن . <BR><font color=\"Blue\">◄</font> آرامش با زن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> ازبن بریدن حجام غلاف سر نره را در ختنه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) پاره ای از ابر تنک . طحرة و طحرور و طحرورة و طحریة مثله . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176120, 'طحر', '<span class=\"hlight\">طحر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) کنایه است از آرامش کردن با زن . (منتهی الارب ). رجوع به کتاب المعرب ص <span class=\"hlight\" dir=\"rtl\">٢٢٣</span> شود.<br /></font></div>'),
(176121, 'طحر', '<span class=\"hlight\">طحر.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (ع اِ) پاره ای از ابر تنک . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176122, 'طحرب', '<span class=\"hlight\">طحرب .</span> <font color=\"DarkGreen\"><b>[ طِ رِ ]</font></b> (ع اِ) آب آورد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176123, 'طحربة', '<span class=\"hlight\">طحربة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ب َ ]</font></b> (ع مص ) پر کردن مشک را. یقال : طحرب القربة طحربة. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> مالیدن چیزی را تا نرم شود و گشاده گردد. <BR><font color=\"Blue\">◄</font> نیک پر کردن . <BR><font color=\"Blue\">◄</font> سیراب گردانیدن . <BR><font color=\"Blue\">◄</font> جنبانیدن خنور و جز آن تا نیک پر شود. <BR><font color=\"Blue\">◄</font> سخت دویدن . <BR><font color=\"Blue\">◄</font> تیز دادن . (منتهی الارب ).<br /></font></div>'),
(176124, 'طحربة', '<span class=\"hlight\">طحربة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> طِ رِ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> طُ رَ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> طَرِ ب َ ]</font></b> (ع اِ) لته پاره . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176125, 'طحربة', '<span class=\"hlight\">طحربة.</span> <font color=\"DarkGreen\"><b>[ طُ رُ ب َ ]</font></b> (ع اِ) لته پاره . (منتهی الارب ) (آنندراج ).و قیل خاص بالجحد. یقال : ما علیه طحربة؛ ای شی ٔ من اللباس . (منتهی الارب ). و منه حدیث القیامة: تدنو الشمس من رؤس الناس و لیس علی احد منهم یومئذ طحربة و ما فی السماء طحربة؛ ای شی ٔ من غیم . (منتهی الارب ).<br /></font></div>'),
(176126, 'طحرف', 'ابر تنک . <BR><font color=\"Blue\">◄</font> طحرفة مثله فی الکل . (منتهی الارب ).<br /><span class=\"hlight\">طحرف .</span> <font color=\"DarkGreen\"><b>[ طِ رِ ]</font></b> (ع اِ) آشامیدنی است تنک جز تبابه . <BR><font color=\"Blue\">◄</font> شوربای تنک . <BR><font color=\"Blue\">◄</font> مسکه ٔ تنک . <br /></font></div>'),
(176127, 'طحرفة', '<span class=\"hlight\">طحرفة.</span> <font color=\"DarkGreen\"><b>[ طِ رِ ف َ ]</font></b> (ع اِ) آشامیدنی است تنک جز تبابه . <BR><font color=\"Blue\">◄</font> شوربای تنک . <BR><font color=\"Blue\">◄</font> مسکه ٔ تنک . <BR><font color=\"Blue\">◄</font> ابر تنک . (منتهی الارب ).<br /></font></div>'),
(176128, 'طحرمة', '<span class=\"hlight\">طحرمة.</span> <font color=\"DarkGreen\"><b>[ طِ رِ م َ ]</font></b> (ع اِ) ما علیه طحرمة؛ نیست بر وی چیزی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176129, 'طحرمة', '<span class=\"hlight\">طحرمة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ م َ ]</font></b> (ع مص ) پر کردن مشک را. <BR><font color=\"Blue\">◄</font> زه کردن کمان را. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176130, 'طحرور', '<span class=\"hlight\">طحرور.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) پاره ای از ابر تنک . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176131, 'طحریة', '<span class=\"hlight\">طحریة.</span> <font color=\"DarkGreen\"><b>[ طِ ی َ ]</font></b> (ع اِ) پاره ای از ابرتنک . <BR><font color=\"Blue\">◄</font> لباس . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176132, 'طحس', '<span class=\"hlight\">طحس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) طحس الجاریة طحساً؛ آرامید با کنیزک . (منتهی الارب ). رجوع به المعرب ص <span class=\"hlight\" dir=\"rtl\">٢٢٣</span> شود.<br /></font></div>'),
(176133, 'طحطاح', '<span class=\"hlight\">طحطاح .</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176134, 'طحطاح', '<span class=\"hlight\">طحطاح .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع مص ) شکستن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176135, 'طحطاوی', '<span class=\"hlight\">طحطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) الطهاوی . احمدبن محمدبن اسماعیل الطحاوی الحنفی . ولادت وی در شهر طهطا نزدیک اسیوط از توابع مصر بوده، و بسال <span class=\"hlight\" dir=\"rtl\">١١٨١</span> هَ . ق . به قاهره پایتخت مصر آمده داخل مدرسه ٔ جامع ازهر شد، و همه روزه برای فراگرفتن علم فقه نزد اساتید فقه، از قبیل : شیخ احمد حماتی، مقدسی، حریری و شیخ مصطفی طائی و شیخ عبدالرحمن عریشی حضور می یافت، کتاب الدرالمختار را از آغاز تا کتاب بیوع نزد عریشی فراگرفت، و از بیوع تا آخر کتاب را با سایر هم طبقگان خود نزد پدر عبدالرحمن جبرتی بپایان رسانید، زیرا عبدالرحمن عریشی به صوب دارالسلطنه عزیمت کرد... و چون شیخ ابراهیم حریری وفات یافت، ریاست و پیشوائی حنفیان بصاحب ترجمه واگذار گردید. وی راست : حاشیه بر مراقی الفلاح شرح نورالایضاح در فقه حنفی . این کتاب در بولاق بسالهای <span class=\"hlight\" dir=\"rtl\">١٢٦٩</span> و <span class=\"hlight\" dir=\"rtl\">١٢٧٩</span> و <span class=\"hlight\" dir=\"rtl\">١٢٩٠</span> و <span class=\"hlight\" dir=\"rtl\">١٣١٨</span> هَ . ق . به طبع رسید، و دو نوبت نیز بسالهای <span class=\"hlight\" dir=\"rtl\">١٣٢٧</span> و <span class=\"hlight\" dir=\"rtl\">١٣٢٩</span> هَ . ق . در مطبعه ٔ عبدالرزاق، در استانبول چاپ شد و مراقی الفلاح را هم که از شرنبلاوی است در حاشیه ٔ کتاب مزبور طبع کرده اند. دیگر حاشیه ای است بر دُرالمختار شرح تنویرالابصار، آن نیز در فقه حنفی است، این کتاب یک نوبت در سال <span class=\"hlight\" dir=\"rtl\">١٢٥٤</span> هَ . ق . در بولاق در چهار مجلد، و نوبت دیگر بسال <span class=\"hlight\" dir=\"rtl\">١٢٦٩</span> هَ . ق . نیز در همان مطبعه در سه مجلد و یک نوبت دیگر بسال <span class=\"hlight\" dir=\"rtl\">١٢٨٣</span> (بدون ذکر مطبعه ) در چهار مجلد به طبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٣</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣٣</span>).<br /></font></div>'),
(176136, 'طحطاوی', '<span class=\"hlight\">طحطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (شیخ ) محمد اسماعیل الانصاری الطحاوی . از بزرگان قرن سیزدهم هجری . او راست :نظم اللاَّلی الغرر فی سلک العقود و الدُرر در توحید، و این کتاب شرحی است بر منظومه ٔ جد صاحب ترجمه در عقاید، در سال <span class=\"hlight\" dir=\"rtl\">١٢٦٩</span> هَ . ق . شرح مزبور را بپایان رسانده است کتاب مزبور بسال <span class=\"hlight\" dir=\"rtl\">١٢٩٩</span> هَ . ق . در مطبعه ٔ شرفیه بطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣٤</span>).<br /></font></div>'),
(176137, 'طحطحة', '<span class=\"hlight\">طحطحة.</span> <font color=\"DarkGreen\"><b>[ طَ طَح َ ]</font></b> (ع مص ) شکستن . طِحطاح، مثله . <BR><font color=\"Blue\">◄</font> جداکردن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> پریشان کردن جهت هلاک . پراکنده کردن و هلاک کردن . (مصادر زوزنی ) (منتهی الارب ) (آنندراج ). عام است . <BR><font color=\"Blue\">◄</font> خندیدن . دندان سپید کردن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176138, 'طحطحة', '<span class=\"hlight\">طحطحة.</span> <font color=\"DarkGreen\"><b>[ طِ طِح َ ]</font></b> (ع اِ) چیزی . (منتهی الارب ) (آنندراج ). موئی . (منتهی الارب ) (آنندراج ). یقال : ما علیه طحطحةٌ؛ یعنی نیست بر وی چیزی یا موئی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176139, 'طحطوط', '<span class=\"hlight\">طحطوط.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) و آن را طحطوطالحجارة نیز نامند. دهی است بزرگ در صعید مصر بر مشرق نیل نزدیک فُسطاط، واقع در صعید ادنی و ابوجعفر طحاوی فقیه معروف از این قریه است نه از قریه ٔ طحا، چنانکه قبلاً گذشت . (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١</span>).<br /></font></div>'),
(176140, 'طحل', '<span class=\"hlight\">طحل .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) ابوعوف . ملخ نر. <BR><font color=\"Blue\">◄</font> اُم عوف ؛ ملخ ماده . (المرصع).<br /></font></div>'),
(176141, 'طحل', '<span class=\"hlight\">طحل .</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (ع مص ) دردمند سپرز گردیدن . <BR><font color=\"Blue\">◄</font> کلان شدن سپرز، طُحل کذلک . <BR><font color=\"Blue\">◄</font> تباه شدن آب . بوی گرفتن از لای . <BR><font color=\"Blue\">◄</font> سپرزرنگ گردیدن . <BR><font color=\"Blue\">◄</font> بر سپرز کسی زدن . <BR><font color=\"Blue\">◄</font> پر کردن چیزی را. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176142, 'طحل', '<span class=\"hlight\">طحل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) بر سپرز کسی زدن . <BR><font color=\"Blue\">◄</font> پر کردن چیزی را. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176143, 'طحل', '<span class=\"hlight\">طحل .</span> <font color=\"DarkGreen\"><b>[ طُ ح ُ ]</font></b> (ع اِ) ج ِ طِحال . رج-وع ب-ه طحال شود.<br /></font></div>'),
(176144, 'طحل', '<span class=\"hlight\">طحل .</span> <font color=\"DarkGreen\"><b>[ طَ ح ِ ]</font></b> (ع ص ) خشمناک . <BR><font color=\"Blue\">◄</font> پُر. <BR><font color=\"Blue\">◄</font> آب چغزلاوه برآورده . <BR><font color=\"Blue\">◄</font> سیاه . <BR><font color=\"Blue\">◄</font> رجُل ٌ طحل ؛ مرد کلان سپرز. مرد دردمندسپرز مطحول . <BR><font color=\"Blue\">◄</font> شراب ٌ طَحِل ؛ شراب نه تیره نه روشن . غُراب ٌ طَحل ؛ زاغ نه تیره نه روشن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176145, 'طحلب', '<span class=\"hlight\">طحلب .</span><font color=\"DarkGreen\"><b>[ طُ ل ُ ]</font></b> (ع اِ) چغزلاوه که بجهت دورماندگی آب پیدا شود. (منتهی الارب ). سبزی که بر روی آب استاده جمع شود، بهندی کائی گویند. (آنندراج ). طِحلِب . (منتهی الارب ) (آنندراج ). سبزابه . (تفلیسی ). جامه ٔ غوک . (دهار). چیزیست که بر سر آب آیدچون نمد بسته، و سبزرنگ است . (مهذب الاسماء). سبزی که بر کنار و روی حوضها و جویها بندد چون پشمی بر روی آب افکنده . خزه . بزغ سمه . جُل وزغ . ثورالماء. عرمض . عدس الماء، و بر سر آب سبزئی ایستاده باشد... و آن سبزی را به تازی طُحلب گویند. (ذخیره ٔ خوارزمشاهی ). خُروءالضفادع است، و آنرا به پارسی جامه خواب پک گویند طبیعت آن سرد بود در سوم و گویند در دوم، و تر بود در دوم، خون را ببندد و طلا کردن بر ورمهای گرم و نقرس گرم و حُمره و درد مفاصل گرم، بغایت مفید بود، و چون در زیت کهن بجوشانند عصب را نرم گرداند، و اگر ضماد کنند بر قیله ٔ امعاء کودکان نافع بود. (اختیارات بدیعی ). به پارسی پشم وزغ نامند، و به اصفهان جُل وزغ گویند، و آن جسمی است سبز که بر روی آبهای ایستاده و کنار جویها متکون میشود آنچه مستدیر و متفرق باشد، مسمی به خزازالماء است، و طحلب لیفی و غزل الماء آن است که مانند رشتها باشد، و هرچه متراکم مثل نمد باشد، خروءالضفادع است . در دوم سرد و تر، و ضماد آن بتنهائی و با آرد جو جهت باد سرخ و اورام حاره و نقرس وقیله و فتق اطفال نافع، و شرب خشک او حابس اسهال مراری، و چون در روغن زیتون بجوشانند، در تلیین عصب قوی الاثر است . و هرچه بر روی سنگهای دریا متکون شود بسیار قابض، و طلای او حابس سیلان خون اعضاء است . و چون طحلب را بلع کرده، درساعت آب گرم آشامیده قی کنند، دراخراج زلوی که به گلو چسبیده باشد مجرب است . (تحفه ٔحکیم مؤمن ). پارسیان آن را جامه ٔ غوک گویند. ارجّانی گوید: طُحلب سرد است و به این معنی ورمها (را) که از گرمی باشد منفعت کند. و علت نقرس را سود دارد، ودرد پیوندها دفع کند، و پی ها را نرم گرداند، چون باپیه جوشیده شود، و بر مفاصل ضماد کرده آید. (ترجمه ٔصیدنه ٔ ابوریحان ). یتولد من تراکم الرطوبات المائیة، و ینعقد بالبرد، و هو اما حب متفاصل الاجزاء و یسمی خروءالمائی، او خیوط متصلة، و یسمی غزل الماء، اولابدٌ بالاحجار، و یمسی خروءالضفادع، و هو اجودها مطلقاً.بارد رطب فی الثانیة، محلل للاورام کلها، و الحمیات الحارة، و ما فی الانثیین، و من اکله و شرب علیه الماء الحار فوراً و اخرجه بالقی، اخرج العلق الناشب فی الحلق مجرب . و الملبد بالاحجار یزیل الحرارة و امراضها ضماداً. (تذکره ٔ داود انطاکی ). به پارسی کشش جوی گویند، طبیعتش سرد است در سوم و تر است در دوم . چون بر پیشانی طلا کنند، رعاف را دفع کند، و چون بر ورم گرم و نقرس گرم و وجعالمفاصل گرم گذارند سودمند آید.<br /></font></div>'),
(176146, 'طحلب', '<span class=\"hlight\">طحلب .</span> <font color=\"DarkGreen\"><b>[ طِ ل ِ ]</font></b> (ع اِ) چغزلاوه که بجهت ماندگی آب پیدا شود. (منتهی الارب ). رجوع به طُحلُب شود.<br /></font></div>'),
(176147, 'طحلب البحر', '<span class=\"hlight\">طحلب البحر.</span> <font color=\"DarkGreen\"><b>[ طُ ل ُ بُل ْ ب َ ]</font></b> (ع اِمرکب ) چغزلاوه ٔ دریائی .<br /></font></div>'),
(176148, 'طحلب الصخر', '<span class=\"hlight\">طحلب الصخر.</span> <font color=\"DarkGreen\"><b>[ طُ ل ُ بُص ْ ص َ ]</font></b> (ع اِ مرکب ) خزازالصخر.<br /></font></div>'),
(176149, 'طحلبا', '<span class=\"hlight\">طحلبا.</span> <font color=\"DarkGreen\"><b>[ طُل ُ ]</font></b> (اِ) سریانی طحلب است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176150, 'طحلبة', '<span class=\"hlight\">طحلبة.</span> <font color=\"DarkGreen\"><b>[ طِ ل ِ ب َ ]</font></b> (ع اِ) شی ٔ اندک و حقیر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> موی . یقال : ما علیه ِ طحلبةٌ؛ ای شعرة. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176151, 'طحلبة', '<span class=\"hlight\">طحلبة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ب َ ]</font></b> (ع مص ) چغزلاوه برآوردن آب . (آنندراج ) (منتهی الارب ). طلحلب العین کذلک . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بزغ سمه کردن آب . <BR><font color=\"Blue\">◄</font> بریدن پشم شتران را. <BR><font color=\"Blue\">◄</font> کشتن کسی را. <BR><font color=\"Blue\">◄</font> سبز شدن زمین از نبات (بصیغه ٔ مجهول ). (منتهی الارب )<br /></font></div>'),
(176152, 'طحلة', '<span class=\"hlight\">طحلة.</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (ع اِمص ) سپرزرنگی و آن رنگی است میان تیرگی و سیاهی با اندک سپیدی . (منتهی الارب ) (آنندراج ). لون بین الغبرة و البیاض . (مهذب الاسماء).<br /></font></div>'),
(176153, 'طحلمة', '<span class=\"hlight\">طحلمة.</span> <font color=\"DarkGreen\"><b>[ طِ ل ِ م َ ]</font></b> (ع اِ) ابر. <BR><font color=\"Blue\">◄</font> ابر پاره : یقال ما فی السماء طحلمة؛ ای غیم او قطعة منه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176154, 'طحمة', '<span class=\"hlight\">طحمة.</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (ع اِ) طحمةالوادی ؛ بهترین جای از وادی و معظم آن . <BR><font color=\"Blue\">◄</font> طحمةالسیل و طحمةاللیل کذلک ویُثلّث فی الکل . <BR><font color=\"Blue\">◄</font> گروه مردم . <BR><font color=\"Blue\">◄</font> طحمةالفتنة؛ دوادوش مردمان در وقت فتنه . <BR><font color=\"Blue\">◄</font> طحمة ابلیس ؛ افساد اوست . <BR><font color=\"Blue\">◄</font> گیاهی است . <BR><font color=\"Blue\">◄</font> نوعی از گیاه شور. (منتهی الارب ).<br /></font></div>'),
(176155, 'طحمة', '<span class=\"hlight\">طحمة.</span> <font color=\"DarkGreen\"><b>[ طُ ح َ م َ ]</font></b> (ع ص ) سخت کارزارکننده . <BR><font color=\"Blue\">◄</font> (اِ) شتران بسیار. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176156, 'طحمیر', '<span class=\"hlight\">طحمیر.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ابر پاره . یقال : ما فی السماء طحمیر؛ ای لطخ من السحاب . <BR><font color=\"Blue\">◄</font> طحمریرة.<br /></font></div>'),
(176157, 'طحمیل', '<span class=\"hlight\">طحمیل .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) بعربی اسم دیک است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176158, 'طحن', '<span class=\"hlight\">طحن .</span> <font color=\"DarkGreen\"><b>[ طُ ح َ ]</font></b> (ع اِ) جانورکی است . <BR><font color=\"Blue\">◄</font> شیر بیشه . <BR><font color=\"Blue\">◄</font> مرد کوتاه بالا. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بعربی غنم را گویند. <BR><font color=\"Blue\">◄</font> حربا. (فهرست مخزن الادویه ).<br /></font></div>'),
(176159, 'طحن', '<span class=\"hlight\">طحن .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) آرد کردن گندم . (منتهی الارب ) (آنندراج ). کذا طحنت الرحی . (منتهی الارب ). آسیا کردن . <BR><font color=\"Blue\">◄</font> طحنت الافعی ؛ گرد گردید مار. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> خردکردن و طاحونه که آسیا باشد مسمی به اسم لازم است .<br /></font></div>'),
(176160, 'طحن', '<span class=\"hlight\">طحن .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) آرد. و فی المثل : اسمع جعجعة و لااری طحنا؛ یعنی آواز آسیا میشنوم و نمی بینم آرد را. (منتهی الارب ) (آنندراج ). دقیق . <BR><font color=\"Blue\">◄</font> گرد. (دهار).<br /></font></div>'),
(176161, 'طحو', '<span class=\"hlight\">طحو.</span> <font color=\"DarkGreen\"><b>[ طَح ْوْ ]</font></b> (ع مص ) گستردن . (منتهی الارب ) (آنندراج ). گسترانیدن . (دهار). بگسترانیدن . (تاج المصادربیهقی ). مثل الدحو. (زوزنی ). <BR><font color=\"Blue\">◄</font> گسترده شدن . <BR><font color=\"Blue\">◄</font> به درازا کشیدن . <BR><font color=\"Blue\">◄</font> خفتن بر پهلوی چپ . <BR><font color=\"Blue\">◄</font> خفتن . <BR><font color=\"Blue\">◄</font> رفتن . یقال : ماادری این طحا؛ ای ذهب َ. <BR><font color=\"Blue\">◄</font> بردن چیزی دل کسی را. <BR><font color=\"Blue\">◄</font> دور گردیدن . <BR><font color=\"Blue\">◄</font> هلاک شدن . <BR><font color=\"Blue\">◄</font> اندوهگین گردیدن . <BR><font color=\"Blue\">◄</font> بر روی افکندن مردم را. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> و الطحی لغةٌ فیه . (منتهی الارب ).<br /></font></div>'),
(176162, 'طحور', '<span class=\"hlight\">طحور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) چشم و چشمه ٔ بیرون اندازنده ٔ چرک و خاشاک را. طحورة، مثله . <BR><font color=\"Blue\">◄</font> شتابنده . <BR><font color=\"Blue\">◄</font> کمان دورانداز. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176163, 'طحوم', '<span class=\"hlight\">طحوم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) بسیار راننده . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176164, 'طحون', '<span class=\"hlight\">طحون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) مقدار سه صد گوسفند. <BR><font color=\"Blue\">◄</font> لشکر گران . (منتهی الارب ) (آنندراج ). لشکر شکننده ٔ همه چیز را. (مهذب الاسماء). الکتیبة العظیمة. (قاموس ). قال الجوهری : تطحن مالقیت، و هو مجاز. (تاج العروس ). <BR><font color=\"Blue\">◄</font> لشکر. <BR><font color=\"Blue\">◄</font> کارزار. <BR><font color=\"Blue\">◄</font> شتر بسیار. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> الابل الکثیرة کالطحانة. (قاموس ). و قیل : الطحانة و الطحون الابل اذا کانت رفاقاً و معها اهلها. (تاج العروس ). <BR><font color=\"Blue\">◄</font> در دونسخه ٔ خطی از مهذب الاسماء: الطحون ؛ شتر بسیارشیر.<br /></font></div>'),
(176165, 'طحک', '<span class=\"hlight\">طحک .</span> <font color=\"DarkGreen\"><b>[ طُح ْ ح َ ]</font></b> (ع ص، اِ) شتری که هنوز فروخوابیدن نیاموخته باشد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176166, 'طحی', '<span class=\"hlight\">طحی .</span> <font color=\"DarkGreen\"><b>[ طَح ْی ْ ]</font></b> (ع مص ) لغتی است در طحو. رجوع به طحو شود.<br /></font></div>'),
(176167, 'طحی', '<span class=\"hlight\">طحی .</span> <font color=\"DarkGreen\"><b>[ طُ ح َ ]</font></b> (اِخ ) موضعی است که در شعرملیح هذلی آمده است . (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣١</span>).<br /></font></div>'),
(176168, 'طحیة', '<span class=\"hlight\">طحیة.</span> <font color=\"DarkGreen\"><b>[ طَ ی َ ]</font></b> (ع اِ) طحیة من السحاب ؛ ابر پاره . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176169, 'طحیر', '<span class=\"hlight\">طحیر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) نوعی از پیچاک شکم که در آن تنفس سخت باشد. (منتهی الارب ) (آنندراج ). زحیر. (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> (مص ) رخیدن . سخت دم زدن . طحار مثله فی الکل . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176170, 'طحین', '<span class=\"hlight\">طحین .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ)آرد. (منتهی الارب ) (آنندراج ). دقیق . گندم ِ آس شده .<br /></font></div>'),
(176171, 'طحینة', '<span class=\"hlight\">طحینة.</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (ع ص، اِ) سمسم مطحون ؛ یعنی کنجد سائیده شده . (فهرست مخزن الادویه ).اَردَه ؛ یعنی کنجد در روغن نشسته . (مهذب الاسماء).<br /></font></div>'),
(176172, 'طخ', '<span class=\"hlight\">طخ .</span> <font color=\"DarkGreen\"><b>[ طَخ خ ]</font></b> (ع مص ) دور کردن . <BR><font color=\"Blue\">◄</font> آرامش با زن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176173, 'طخاران', '<span class=\"hlight\">طخاران .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) محله ای است . یاقوت گوید: گمان من آن است که این محله در مرو باشد. (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣١</span>).<br /></font></div>'),
(176174, 'طخارستان', '<span class=\"hlight\">طخارستان .</span> <font color=\"DarkGreen\"><b>[ طُ رِ ]</font></b> (اِخ ) (ملوک ...) طایفه ای از ملوک غور که پایتخت آنان بامیان بود.<br /></font></div>'),
(176175, 'طخارستان', '<span class=\"hlight\">طخارستان .</span> <font color=\"DarkGreen\"><b>[ طُ رِ ]</font></b> (اِخ ) طخیرستان نیز گویند، ولایتی است وسیع و بزرگ که شامل چندین شهر میباشد. و من حیث المجموع از نواحی وتوابع خراسان بشمار می رود. این ولایت به دو قسمت منقسم است : طخارستان عُلیا، طخارستان سفلی . طخارستان علیا، واقع در شرقی بلخ و غربی جیحون است، و بین آن و بلخ بیست وهشت فرسنگ مسافت میباشد. طخارستان سفلی نیزدر غربی نهر جیحون واقع شده، ولی فاصله آن تا بلخ، بیش از فاصله ٔ طخارستان علیا تا بلخ است، و تمایلش بشرق بلخ نیز افزونتر از طخارستان علیا است . اصطخری گوید: بزرگترین شهرهای طخارستان طالقان است که در زمین هموار و مسطح واقع شده و فاصله ٔ آن تا کوهستان تیرپرتابی بیش نیست . (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣١</span>).<br />در جغرافی کیهان از معجم البلدان نقل کرده گوید: اراضی فارس پیشین و قبل از اسلام میانه ٔ شهر بلخ تا آذربایجان و ارمنستان و فرات تا عربستان و عمان و مکران و کابل و طخارستان بوده و قریب یکصدوپنجاه فرسخ طول و همین اندازه عرض داشته است . (کیهان سیاسی حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">٢١٤</span>). طخارستان در قسمت شمالی غور و پایتخت آن شهر بامیان بوده است . قال الکندی : انه (یعنی اللعل ) ظهر اولاً فی جبل الراهون ثم ظهر له معدن بین «وخان » و «شگتان » فی موضعیُدعی بدخشان من اطراف طخارستان و هذا هو اللعل . (الجماهر ص <span class=\"hlight\" dir=\"rtl\">٨٨</span>). محمد معین در مقدمه ٔ برهان قاطع ص <span class=\"hlight\" dir=\"rtl\">٢٤</span> مینویسد: تخارستان (طخارستان ) چنانکه از نام آن برمی آید، اسم ناحیه ای است مشتق از نام قومی که در آنجا سکونت داشتند . ناحیه ٔ تخارستان بین بلخ و بدخشان است و در عصر تسلط عرب و زمان ساسانیان این ایالت از ساحل آمودریا تا معابر هندوکش وسعت داشته است . بقول یاقوت دو طخارستان وجود داشته : طخارستان علیا و طخارستان سفلی ولی بنظر نمیرسدکه قدما از این تقسیم حدود مشخصی در ذهن داشته باشند. طخارستان علیا ظاهراً در مشرق بلخ و مغرب جیحون (آمودریا) بود و طخارستان سفلی نیز در مغرب جیحون واقع بود منتهی از سمت مشرق دورتر از طخارستان علیا قرار داشت تخاریان مردمی قوی و نیرومند بودند. تخارستان تا نهضت مردمان شمالی جزو پادشاهی یونانی بلخ (باکتریا) بشمار میرفت . و عاقبت آنان با اقوام دیگر دولت مزبور را منقرض کردند هپتال ها (هیاطله ) در اواخر ایام یزدگرد دوم شاهنشاه ساسانی (متوفی <span class=\"hlight\" dir=\"rtl\">٤٣٨</span> م .) تخارستان را تسخیر کردند . دوره ٔ محاربات عرب با شاهان محلی و آخرین افراد خاندان ساسانی و ترکان برای تملک تخارستان، از ملک تخارستان به نام جبغو (جبغویه : طبری ص <span class=\"hlight\" dir=\"rtl\">١٢٠٦</span>) یاد میشود. این منازعات اندکی پیش از سال <span class=\"hlight\" dir=\"rtl\">٧٤٠</span> م . بنفع عرب خاتمه یافت . بعدها تخارستان بخشی از حکومت غوریان، یعنی خاندان غوریه که در بامیان حکومت میکردند گردید. بنظر میرسد که از قرن هفتم هجری (سیزدهم میلادی ) نام کشور تخارستان از استعمال افتاده باشد. صاحب قاموس الاعلام آرد: نام خطه ٔ بزرگی است در مشرق بلخ و این سوی مجرای جیحون و به دو نام وصفی علیا و سفلی منقسم میگردید. بزرگترین شهرش را طالقان مینامیدند و معموره های دیگری، مانند خلم، سمنجان، بغلان، سکاکند و زوالین داشته، وطن جمعی کثیر از مشاهیر علما بوده است . امروز این نام متروک و مجهول است و خطه ٔمزبور تابع افغانستان است - انتهی <span class=\"hlight\">:</span> <br />خوار باد و خسته دل بدخواه جاه و دولتش <br />گر ببغداد است و ری یا در طخارستان و بُست .<br /> <font color=\"Red\">سوزنی .</font><br />و رجوع به نزهةالقلوب چ لیدن ص <span class=\"hlight\" dir=\"rtl\">١٥٥</span>، <span class=\"hlight\" dir=\"rtl\">١٥٦</span> و مجمل التواریخ و القصص چ تهران ص <span class=\"hlight\" dir=\"rtl\">٤٨٧</span> و ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٥٨</span> و <span class=\"hlight\" dir=\"rtl\">٢٥٥٧</span> و لباب الالباب عوفی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢١</span> و فهرست حبیب السیر چ خیام و ایران در زمان ساسانیان صص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span> - <span class=\"hlight\" dir=\"rtl\">٣٦١</span> و التفهیم ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٤</span> و تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٢٧</span>، <span class=\"hlight\" dir=\"rtl\">٢١٥</span>، <span class=\"hlight\" dir=\"rtl\">٢١٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٤١</span> و عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٠</span> و فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٩٤</span> و اخبار الدولة السلجوقیه ص <span class=\"hlight\" dir=\"rtl\">٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٧</span>، <span class=\"hlight\" dir=\"rtl\">٥٨</span> شود.<br /></font></div>'),
(176176, 'طخارستانی', '<span class=\"hlight\">طخارستانی .</span> <font color=\"DarkGreen\"><b>[ طُ رِ ]</font></b> (ص نسبی ) منسوب به طخارستان .<br /></font></div>'),
(176177, 'طخارم', '<span class=\"hlight\">طخارم .</span><font color=\"DarkGreen\"><b>[ طُ رِ ]</font></b> (ع ص ) خشمناک . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176178, 'طخاری', '<span class=\"hlight\">طخاری .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) قومی از ایرانیان باستان که در حدود طخارستان میزیسته اند. رجوع به ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٦٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٦٥</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٦٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٧٧</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٥٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٥٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٥٩</span> شود. <BR><font color=\"Blue\">◄</font> لهجه ای که مردم طخارستان بدان تکلم میکردند. زبان تخاری در تداول غالب زبان شناسان امروز، زبانی است هند و اروپائی و شامل دو لهجه که عادتاً آنها را لهجه ٔ <span class=\"hlight\" dir=\"rtl\">A</span> و لهجه ٔ <span class=\"hlight\" dir=\"rtl\">B</span> مینامند . این زبان از حیطه ٔ زبانهای ایرانی خارج است، ولی گاه در کتب اسلامی نام زبان تخاری (طخاریه ) به زبانی ایرانی اطلاق شده است، از آنجمله ابوریحان بیرونی در آثارالباقیه «آذرخش » را از «ایام الطخاریة» نام میبرد و مقدسی گوید: زبان طخارستان بزبان بلخی نزدیک است . بنونیست نیز بر این عقیده است که زبان ایران به نام تخاری در تخارستان متداول بوده است . (مقدمه ٔ برهان قاطع چ معین ص <span class=\"hlight\" dir=\"rtl\">٢٥</span>).<br /></font></div>'),
(176179, 'طخاریة', '<span class=\"hlight\">طخاریة.</span> <font color=\"DarkGreen\"><b>[ طَ ی َ ]</font></b> (ع ص ) اتان ٌ طخاریةٌ؛ خر ماده ٔ نجیب و اصیل . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176180, 'طخاریر', '<span class=\"hlight\">طخاریر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) ج ِ طخرور. یقال : جأه طخاریر؛ یعنی آمدند او را مردم درآمیخته از هر جنس . یا آمدند او را متفرق و پریشان . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176181, 'طخاطخ', '<span class=\"hlight\">طخاطخ .</span> <font color=\"DarkGreen\"><b>[ طُ طِ ]</font></b> (ع اِ) تاریکی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176182, 'طخاف', '<span class=\"hlight\">طخاف .</span> <font color=\"DarkGreen\"><b>[طِ ]</font></b> (ع ص، اِ) ج ِ طخفة. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176183, 'طخاف', '<span class=\"hlight\">طخاف .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص، اِ) ابر تُنک که ازخلال آن آسمان دیده شود. (منتهی الارب ) (آنندراج ). ابر تُنک که آسمان ورای آن دیده شود. (منتخب اللغات ).<br /></font></div>'),
(176184, 'طخاف', '<span class=\"hlight\">طخاف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) ابر تُنک بالارفته . (منتهی الارب ) (آنندراج ). ابر دور از زمین . (مهذب الاسماء). ابر بلند. (منتخب اللغات ).<br /></font></div>'),
(176185, 'طخام', '<span class=\"hlight\">طخام .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) کوهی است نزدیک آبی که متعلق به بنی شمجی از طایفه ٔ طی ّ میباشد و آن کوه را موفق مینامند. (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢</span>).<br /></font></div>'),
(176186, 'طخر', '<span class=\"hlight\">طخر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ)ابر سیاه . <BR><font color=\"Blue\">◄</font> ابرِ تُنک . (منتهی الارب ).<br /></font></div>'),
(176187, 'طخربة', '<span class=\"hlight\">طخربة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ب َ ]</font></b> (ع اِ) لته پاره . <BR><font color=\"Blue\">◄</font> ابرپاره . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176188, 'طخروذ', '<span class=\"hlight\">طخروذ.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُ ]</font></b> (اِخ ) قریه ای است از قرای نیشابور. (نقل از سمعانی ). رجوع به طخورذ شود.<br /></font></div>'),
(176189, 'طخروذی', '<span class=\"hlight\">طخروذی .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُ ]</font></b> (ص نسبی ) منسوب به طخروذ از دیه های نیشابور. (سمعانی ). رجوع به طخورذی شود.<br /></font></div>'),
(176190, 'طخرور', '<span class=\"hlight\">طخرور.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) پاره ٔ ابر تُنک . ج، طخاریر. <BR><font color=\"Blue\">◄</font> مرد غریب . <BR><font color=\"Blue\">◄</font> آنکه نه چُست باشد و نه سُست . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176191, 'طخز', '<span class=\"hlight\">طخز.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) دروغ . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176192, 'طخس', '<span class=\"hlight\">طخس .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) بُن و بیخ هر چیزی . یقال : هو طخس ُ شَرّ؛ ای نهایةٌ فیه، او اصل و باعث ٌ علیه . (منتهی الارب ) (آنندراج ). اصل . (مهذب الاسماء).<br /></font></div>'),
(176193, 'طخش', '<span class=\"hlight\">طخش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی است در دو فرسنگی مرو. (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢</span>). یقال : لها تخح <font color=\"DarkGreen\"><b>[ ظ: تخج ]</font></b>. (سمعانی ).<br /></font></div>'),
(176194, 'طخش', '<span class=\"hlight\">طخش .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ خ َ ]</font></b> (ع مص ) تاریک شدن چشم . یقال : طخشت عینه طخشاً و طَخَشاً. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176195, 'طخش', '<span class=\"hlight\">طخش .</span> <font color=\"DarkGreen\"><b>[ طَ خ َ ]</font></b> (ع اِ) ابن البیطار گوید: درختی است که در اسپانیا از آن کمان کنند. مردمان گویند که آن «از ملک » است، لکن یقین نیست و برخی گویند که «مران » است و بعضی گمان برند که طخش «شوحط» است . و بدو نیز بسی ماننده است . برگ آن تقریباً همانند برگ بید است و ثمری سبز دارد که چون پخته شد سرخ گردد، و آن را هسته ای است که از آن روغن گیرند و بطعم عفص است . و نیز همین شروح را در باب درختی که سمی است داده اند که تنها با درخت پیشین در اسم شریک است و من این درخت را نشناسم . لکلرک در ترجمه گوید: با این اختلافات مرادف آنرا در یونانی و لاتینی تعیین کردن ممکن نباشد، تنها میتوان گفت که این نام شبیه به طخوس لاتینی است .<br /></font></div>'),
(176196, 'طخشی', '<span class=\"hlight\">طخشی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص نسبی ) منسوب به طخش . (سمعانی ).<br /></font></div>'),
(176197, 'طخشیقون', '<span class=\"hlight\">طخشیقون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) صاحب برهان گوید: نام داروئی است بلغت رومی که آنرا از مُلک ارمن آرند و پیکان تیر و بیشتر اسلحه ٔ جنگ را بدان زهرآلود سازند - انتهی . ظاهراً اصل این کلمه طخیقون یا طخسیقون یونانی بمعنی مطلق سم است، و شاید وقتی این کلمه معنی خاص سم محصول ارمنیه و مخصوص زهراب دادن پیکان و جز آن میداده است . و طفشیقون نیز گویند. و تأویل آن قوسی بود، از بهر آنکه آن دوائی است که اهل ارمن پیکان را به وی زهرآلود کنند و در جنگها بکار برند و حلتیت پادزهر وی است . (اختیارات بدیعی ). دوای سمی است که بلاد ارمن پیکان را به آن آب داده و زخم آن کشنده باشد، از جمله ٔ یتوعات است، و برگش شبیه به برگ کبر و پرشیر و بغایت تند، و ضمادش جهت قوبا نافع است . (تحفه ٔ حکیم مؤمن ). حلتیت پادزهر آن است شرباً، و ضماد بموضع جراحت آن . (مخزن الادویه ). و طخسیقون با سین هم آمده است، و آن ماده ای است که قدما تیر را بدان زهرآگین میکردند و این بیشتر معمول مردم ارمینیه بود.<br /></font></div>'),
(176198, 'طخطاخ', '<span class=\"hlight\">طخطاخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b>(ع اِ) آواز زیور. <BR><font color=\"Blue\">◄</font> (ص ) مرد بدخلق . <BR><font color=\"Blue\">◄</font> ابرِ تو بر تو. (منتهی الارب ) (آنندراج ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(176199, 'طخطاخ', '<span class=\"hlight\">طخطاخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام مردی است . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176200, 'طخف', '<span class=\"hlight\">طخف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) اندوه یا غم که دل را فراگیرد. <BR><font color=\"Blue\">◄</font> شیر ترش زبان گز. <BR><font color=\"Blue\">◄</font> ابر تُنک بالارفته . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176201, 'طخفة', '<span class=\"hlight\">طخفة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (ع ص، اِ) ابر تنکی که آسمان از خلال آن دیده شود. (اقرب الموارد). ج، طخاف .<br /></font></div>'),
(176202, 'طخفة', '<span class=\"hlight\">طخفة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (اِخ ) کوهی است سرخ دراز و در برابر آن چاههاست . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> آبخوری است در حمای ضریة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نام جائی است . از آن است : یوم طخفة مر بنی یربوع را با قابوس بن منذر ابن ماءالسماء. (منتهی الارب ). یاقوت در معجم البلدان آورده : شغل ردافة یکی از مشاغل درباری ملوک حیره و آن چنان بود که چون پادشاه سوار شدی کسی که شغل ردافة داشتی، موظف بودی پشت سر پادشاه سوار شود. وبهمین طریق، چون پادشاه در مجلس شراب نشستی ردیف درجانب راست وی می نشست، و جز ردیف دیگری را روا نبودی که بعد از آنکه پادشاه شراب نوشید بلافاصله شراب نوشد. ابن عبدربه شرح واقعه ٔ یوم طخفة را بدین سیاق آورده است : در عهد نعمان بن منذر شغل ردافة با قیس بن عتاب بود، حاجب ابن زرارة از نعمان استدعا کرد که شغل ردافة را به حرث بن مرطبن سفیان بن مجاشع محول دارد، نعمان سران قبیله ٔ بنی یربوع را که این شغل همواره به یکی از افراد آن قبیله مفوض بود بخواند و گفت : نیکو آن است که شغل ردافة را نوبت نهید، چندی با شما بوده، از این پس چندی نیز برادران خویش از سایر اعراب را در این شغل سهیم قرار دهید، بنی یربوع گفتند: برادران ما را بدین شغل نیازی نیست، حاجب ابن زرارة از طریق حسد این استدعا را از پادشاه کرده است، و بکلی از پذیرفتن این امر ابا کردند. حرث بن شهاب که در آن مجلس حاضر بود، گفت : محال است که بنی یربوع برای قبول این امر تن دردهند، چون حاجب بن زرارة از بنی یربوع نومیدشد، نعمان را گفت : اگر ما را لشکری به مدد فرستی، بدان وسیله بنی یربوع را برای تسلیم شغل ناگزیر سازیم، و آنان نیز از فرمان تو سر بازپیچند، نعمان قابوس پسر خویش و حسان برادر خود را با لشکری از اهالی حیره و گروهی دیگر از اعراب خارج از حیره روانه داشت، حسان با مقدمةالجیش و قابوس با لشکریان روانه شدند، چون به طخفة رسیدند، جنگ بین بنی یربوع و قابوس درگرفت و قابوس و یاران هزیمت شدند. طارق بن عمیرة اسب قابوس را پی کرد، و خواست موی پیشانی او را هم ببرد، قابوس گفت : این عمل با ابناء ملوک سزا نیست، طارق دست ازوی بازداشت و او را مجهز کرد و نزد نعمان روانه ساخت . حسان نیز به دست بشیربن عمرو اسیر شد، اما بشیر بر او منت نهاده وی را رها کرد. مالک بن نویرة را در این واقعه اشعاری است که این ابیات از آن جمله است :<br />و نحن عقرنا مهر قابوس بعدما<br />رأی القوم منه و الخیول تلهب <br />علیه دلاص ذات نسج و سیفه <br />جراز من الهندی ابیض مقضب <br />طلبنا بها انا مداریک قبلها<br />اذا طلب الشأو البعید المقرب .<br /> <font color=\"Red\">(از معجم البلدان و عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٨٧</span>).</font><br />یاقوت در معجم البلدان علت انتزاع شغل ردافة را از بنی یربوع بدین نحو ذکر کرده که شغل ردافة در عهد نعمان با عتاب بود، چون وی بمرد و پسر او عوف کودک بود، حاجب نعمان استدعا کرد که این شغل به کسی که خارج از قبیله ٔ بنی یربوع است واگذار شود. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢</span>). و رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢</span>، <span class=\"hlight\" dir=\"rtl\">٨٦</span>، <span class=\"hlight\" dir=\"rtl\">٨٨</span>، <span class=\"hlight\" dir=\"rtl\">٩١</span> و عیون الاخبار (ردافة) ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٨</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٦</span> شود.<br /></font></div>'),
(176203, 'طخم', '<span class=\"hlight\">طخم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) بزرگ منشی کردن . تکبر کردن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176204, 'طخمة', '<span class=\"hlight\">طخمة.</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (ع اِ) گله ٔ بزان . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176205, 'طخمة', '<span class=\"hlight\">طخمة.</span> <font color=\"DarkGreen\"><b>[ طُ م َ ]</font></b> (ع اِ) سیاهی نوک بینی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176206, 'طخمة', '<span class=\"hlight\">طخمة.</span> <font color=\"DarkGreen\"><b>[ طِ م َ ]</font></b> (اِخ ) نام والد حوشب تابعی . (منتهی الارب ).<br /></font></div>'),
(176207, 'طخمورث', '<span class=\"hlight\">طخمورث .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (اِخ ) طهمورث . تهمورث . ملکی بود از ملوک فارس که هفتصد سال سلطنت کرد. (منتهی الارب ). رجوع به طهمورث شود.<br /></font></div>'),
(176208, 'طخمیل', '<span class=\"hlight\">طخمیل .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) خروس . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176209, 'طخنة', '<span class=\"hlight\">طخنة.</span> <font color=\"DarkGreen\"><b>[ طُ خ َ ن َ ]</font></b> (ع ص ) سخت کوتاه . (مهذب الاسماء). این لغت در سه نسخه ٔ خطی از مهذب الاسماء بدین صورت در «باب الطاء المضمومة مع الخاء» ثبت شده، ولی صاحب تاج العروس در ماده ٔ طحن در ضمن مستدرکات گوید: قال الزجاج : الطخته، القصیر فیه لوثة. و نقل الازهری عن ابن الاعرابی اذا کان الرجل نهایة فی القصر، فهو الطخته . (و در تاج العروس کلمه ٔ طختة بدون اعراب است ).<br /></font></div>'),
(176210, 'طخوخ', '<span class=\"hlight\">طخوخ .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِمص ) دشوارخوئی . بدصحبتی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176211, 'طخورذ', '<span class=\"hlight\">طخورذ.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) دهی است از قرای نیشابور. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>). رجوع به طخروذ شود.<br /></font></div>'),
(176212, 'طخورذی', '<span class=\"hlight\">طخورذی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ص نسبی ) منسوب به طخورذ. رجوع به طخروذی شود.<br /></font></div>'),
(176213, 'طخوم', '<span class=\"hlight\">طخوم .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) حد فاصل میان دوزمین . (منتهی الارب ) (آنندراج ). سرحد. مرادف تخوم .<br /></font></div>'),
(176214, 'طخی', '<span class=\"hlight\">طخی .</span> <font color=\"DarkGreen\"><b>[ طُ خ َی ی ]</font></b> (ع اِ) خروس . (منتهی الارب ) (آنندراج ). دیک است که به فارسی خروس نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(176215, 'طخیة', '<span class=\"hlight\">طخیة.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ <span class=\"hlight\" dir=\"rtl\">/</span> طُ ی َ ]</font></b> (ع اِ) ابرپاره . <BR><font color=\"Blue\">◄</font> تاریکی . <BR><font color=\"Blue\">◄</font> (ص ) مرد گول . (منتهی الارب ) (آنندراج ). ج، طخیون .<br /></font></div>'),
(176216, 'طخیرستان', '<span class=\"hlight\">طخیرستان .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) لغتی است در طخارستان . یاقوت در ذیل کلمه ٔ طخارستان گوید: و یقال طخیرستان . (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣١</span>) <span class=\"hlight\">:</span> و خبر ورود او <font color=\"DarkGreen\"><b>[ ایلک ]</font></b> بطخیرستان، بسلطان رسید. (ترجمه ٔ تاریخ یمینی خطی نسخه ٔ کتابخانه ٔ مؤلف ص <span class=\"hlight\" dir=\"rtl\">٢٦٦</span> و چاپی ص <span class=\"hlight\" dir=\"rtl\">٢٩٧</span>). رجوع به ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٥٧</span> شود.<br /></font></div>'),
(176217, 'طخیفة', '<span class=\"hlight\">طخیفة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (ع اِ) نوعی از آش . و آن چنان باشد که پاره های گوشت دردیگ انداخته، آب بسیار در آن ریخته، بر آتش نهند چون پخته شود فرودآرند. (منتهی الارب ). آبگوشت . یخنی .<br /></font></div>'),
(176218, 'طخیم', '<span class=\"hlight\">طخیم .</span> <font color=\"DarkGreen\"><b>[ طُ خ َ ]</font></b> (اِخ ) ابن ابی الطخماء. شاعری است . (منتهی الارب ).<br /></font></div>'),
(176219, 'طخیم', '<span class=\"hlight\">طخیم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) گوشت خشک که به سیاهی زند. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176220, 'طخیون', '<span class=\"hlight\">طخیون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) ج ِ طخیة.<br /></font></div>'),
(176221, 'طدان', '<span class=\"hlight\">طدان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) موضع بالبادیه فی شعر البحتری . کذا ذکره الزمخشری، و لاادری ما صحته . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>).<br /></font></div>'),
(176222, 'طر', '<span class=\"hlight\">طر.</span> <font color=\"DarkGreen\"><b>[ طَرر ]</font></b> (ع مص ) نیک راندن . <BR><font color=\"Blue\">◄</font> گرد آوردن شتران از اطراف و جوانب وقت راندن . <BR><font color=\"Blue\">◄</font> تیز کردن کارد و جز آن . (منتهی الارب ) (آنندراج ). تیز کردن سنان . (تاج المصادر بیهقی ) (زوزنی ) (دهار). <BR><font color=\"Blue\">◄</font> کفانیدن . (منتهی الارب ) (آنندراج ). شکافتن . (غیاث اللغات ). بریدن . (منتهی الارب ) (آنندراج ). منه : کان یطر شاربه ؛ ای یقصه . (منتهی الارب ). بریدن و شکافتن کیسه . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> به گل اندودن حوض را. <BR><font color=\"Blue\">◄</font> افتادن دست بر خم شمشیر. <BR><font color=\"Blue\">◄</font> بلند ساختن بنا. <BR><font color=\"Blue\">◄</font> دمیدن گیاه . دمیدن بروت . <BR><font color=\"Blue\">◄</font> روشن شدن . یقال : طرت النجوم ؛ اذا اضأت . طرور، مثله . <BR><font color=\"Blue\">◄</font> ربودن . <BR><font color=\"Blue\">◄</font> طپانچه زدن . <BR><font color=\"Blue\">◄</font> افتادن . <BR><font color=\"Blue\">◄</font> (اِ) پشم نو برآمده . <BR><font color=\"Blue\">◄</font> موی خر که بعد از ریختن برآمده باشد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176223, 'طر', '<span class=\"hlight\">طر.</span> <font color=\"DarkGreen\"><b>[ طُرر ]</font></b> (ع اِ) همه : جأوا طراً؛ آمدند همه . (منتهی الارب ). جمیع. کلا.همگی . جمیعاً. کافةً. قاطِبة. گِشت . همگان . کلمه ٔ طر در زبان عرب جز به صورت حال بصورت دیگر استعمال نشده، یعنی همیشه بمعنی همه و بصورت طرّاً آمده است .<br /></font></div>'),
(176224, 'طرء', '<span class=\"hlight\">طرء.</span> <font color=\"DarkGreen\"><b>[طَرْءْ ]</font></b> (ع مص ) از جائی و شهری آمدن کسی را. (منتهی الارب ). یا ناگاه بدرآمدن از جائی بر کسی . یقال : طراءَ علیهم ؛ اذا اتاهم من مکان، او خرج علیهم منه فجاءَة. (منتهی الارب ). آمدن از جائی . (آنندراج ). از جائی و شهری برآمدن . (صراح ). از شهری به شهری برآمدن .<br /></font></div>'),
(176225, 'طرآن', '<span class=\"hlight\">طرآن .</span> <font color=\"DarkGreen\"><b>[ طُرْ ]</font></b> (ع اِ) راه و کار منکر و بد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176226, 'طرآن', '<span class=\"hlight\">طرآن .</span> <font color=\"DarkGreen\"><b>[ طُرْ ]</font></b> (اِخ ) کوهی است که کبوتر بسیار در آنجا باشد. (منتهی الارب ) (آنندراج ). و منظور از حمام الطرآنی، کبوتر منسوب بدان کوه است . ابوحاتم گفته که عامه ٔ مردم طرانی راطورانی تلفظ میکنند و آن ناصواب است از ابوحاتم پرسیدند که منظور ذوالرمة از طوریون در این بیت چیست :<br />اعاریب طوریون عن کل قریة<br />یحیدون عنها من حذارالمقادر.<br />ابوحاتم گفت : از ماده ٔ طرء نیست، چه اگر از آن ماده بودی، بایستی طرئیون گفتی، پرسیدند: پس معنی آن چه باشد، گفت : مراد ذوالرمه آن بوده است که بفهماند تازیان بدوی از تازیان بلاد طور یعنی خطه ٔ شام بوده اند، چنانکه عجاج رجزسرای معروف گفته :<br />دانی جناحیه من الطور فمر.<br />اراد انه جاء من الشام .<br /><font color=\"Red\">(معجم البلدان ).</font><br /></font></div>'),
(176227, 'طرآنی', '<span class=\"hlight\">طرآنی .</span> <font color=\"DarkGreen\"><b>[ طُرْ ]</font></b> (ع ص ) آنچه معلوم نشد از کجا رسیده . (منتهی الارب ) (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امر طرآنی </span> ؛ کاری که معلوم نشود از کجا رسیده . (منتهی الارب ) (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">حمام طرآنی </span> ؛ مثله . (منتهی الارب ). کبوتری که معلوم نشود از کجا رسیده . (آنندراج ). و در معجم البلدان بمعنی کبوتر منسوب به کوه «طرآن » آمده . رجوع به طرآن شود.<br /></font></div>'),
(176228, 'طرا', '<span class=\"hlight\">طرا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) آنچه غیر از خلقت زمین باشد. یعنی طری غیر ثری است . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> چیزی که در احاطه ٔ عدد درنیاید از آفرینش یقال هم اکثر من الطرا و الثری . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176229, 'طرا', '<span class=\"hlight\">طرا.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) قریه ای است در شرقی نیل نزدیک فسطاط از ناحیه ٔ صعید مصر. (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>). رجوع به عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠١</span> شود.<br /></font></div>'),
(176230, 'طراء', '<span class=\"hlight\">طراء.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) طراءَة. تر و تازه گردیدن تره . یقال : طراءالبقل . خلاف ذوی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176231, 'طراب', '<span class=\"hlight\">طراب .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) ابل طراب ؛ شتران مایل به وطن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176232, 'طرابرزن', '<span class=\"hlight\">طرابرزن .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) این صورت در سفرنامه ٔ ناصرخسرو آمده است و چنین : پس از این شهر<font color=\"DarkGreen\"><b>[ طرابلس ]</font></b> برفتم همچنان بر طرف دریا رو سوی جنوب به یکی فرسنگی حصاری دیدم که آنرا قلمون میگفتند. چشمه ای آب در اندرون آن بود. از آنجا برفتم بشهر طرابرزن و از طرابلس تا آنجا پنج فرسنگ بود. (سفرنامه ٔ ناصرخسرو چ برلن ص <span class=\"hlight\" dir=\"rtl\">١٨</span>). اما در کتب جغرافیا دیده نشد.<br /></font></div>'),
(176233, 'طرابزنده', '<span class=\"hlight\">طرابزنده .</span><font color=\"DarkGreen\"><b>[ طَ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِخ ) (بحر...) دریای سیاه . بحر اسود. (دمشقی ). بحرالروس . بحر بنطس . (تاج العروس ).<br /></font></div>'),
(176234, 'طرابزون', '<span class=\"hlight\">طرابزون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ولایتی است از ولایات ترکیه ٔ آسیا، محدود است شمالاً به بحر اسود، جنوباً به ارض روم و سیواس، و شرقاً به ارض روم و قفقاز وغرباً به قسطمونی . مساحت آن دوازده هزار میل مربع، وجمعیت آن یک میلیون و یکصدهزار تن است که از اجناس مختلف مردم تشکیل یافته است و همگی دلیر و پردل میباشند. ولایت طرابزون کوهستانی است و دارای درختان بسیار از هر نوع میوه است . این ولایت چهار متصرفیه و بیست ودو مرکز قضاء و بیست وهفت ناحیه دارد. بندر آن طرابزون است که بر ساحل بحر اسود واقع شده و نزدیک به چهل هزار تن سکنه دارد و لنگرگاه تجارتی وسیعی میباشد. مشهورترین شهرهای این ولایت صامسون است که خود بر بحر اسود لنگرگاهی است، و کشتیهای بسیار با ماشین بخار بدانجا لنگر افکنند. (ذیل معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩١</span>).<br /></font></div>'),
(176235, 'طرابلس', '<span class=\"hlight\">طرابلس .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ل ُ ]</font></b> (اِخ ) شهری است به شام . (منتهی الارب ) (آنندراج ). طرابلس شام . در اقلیم چهارم واقع، طولش <span class=\"hlight\" dir=\"rtl\">٦٠</span> درجه و <span class=\"hlight\" dir=\"rtl\">٣٥</span> دقیقه، و عرض آن <span class=\"hlight\" dir=\"rtl\">٣٤</span> درجه میباشد. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>). و آن نامی یونانی است بمعنی سه شهر. (دمشقی ). لغت شامیه و اصل آن اطرابلس بهمزه، یا لغت رومی است معنی آن سه شهر. (منتهی الارب )(آنندراج ). شهریست ساحلی و عاصمه ٔ طرابوزان شهریست مشهور بر ساحل دریای شام، بین لاذقیه و عکا. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٣</span>). بندری است در شام بر ساحل بحرالروم واقع در شمال بیروت و دارای چهل هزار سکنه، و از آنجا چرم و اسفنج خیزد. شهر طرابلس شام یکی از بلاد سوریه و بر کنار بحر ابیض متوسط <span class=\"hlight\" dir=\"rtl\">٣٤</span> درجه و <span class=\"hlight\" dir=\"rtl\">٢٦</span> دقیقه و <span class=\"hlight\" dir=\"rtl\">٣٦</span> ثانیه از عرض شمالی و <span class=\"hlight\" dir=\"rtl\">٣٥</span> درجه و <span class=\"hlight\" dir=\"rtl\">٤٤</span> دقیقه و <span class=\"hlight\" dir=\"rtl\">٢٠</span> ثانیه از طول شرقی بر دو کناره ٔ نهر ابی علی واقع است . سابقاً این شهر در رأس زبانه ٔ داخل در دریائی که امروز لنگرگاه واقع است بنا شده بود، ولی پس از آنکه این شهر به دست مسلمانان گشوده شد، شهر قدیم خراب گردید و بجای آن بمسافت میلی دور از آن شهر دیگری بنا کردند و نام شهر کهنه را بدان نهادند. بنیان عمارات این شهر تمامی از سنگ و دارای خانه های ساخته شده از یک طبقه و دو طبقه میباشد، و بناهای زیبا و مدارس متعدد و مساجد بسیار و مطبعه و روزنامه های جالب توجه دارد. گرمابه هائی دارد که در تمامی اطراف و جوانب آن لوله کشی شده و آب فراوان در هر لحظه که خواهند روان است . درخت و اشجار میوه در این شهر بسیار و باغات مصفاو رزستان و بساتین طرب انگیز اطراف و جوانب شهر را فراگرفته است . خاک این شهر برای کشت و تربیت اشجار و نباتات استعداد کامل دارد، میوه های متنوع، از قبیل : پرتقال، لیمو، نارنج و گلابی در این شهر نیک بعمل آیدو انواع و اقسام شکوفه ها و گلها بویژه گل سرخ بسیاراست . هوای این شهر مرطوب است اهالی آن در غایت ظرافت و نهایت مهربانی نسبت بمردم رفتار میکنند. در تحصیل فنون و آداب خصوصاً در تشحیذ قریحه ٔ شعری حرص و ولعی دارند تا بحدی که نظم اشعار را یک نوع سلیقه میشمارند. اهل شهامت و عزت نفس و شدت بأس و کرم میباشند. مناظره و رقابت با اقران و همسران خود را دوست دارند. علی الخصوص در مورد مناصب عالی . در پرورش کرم ابریشم اهتمام بسیار مبذول میدارند و در بافتن جامه های ابریشمین بسیار ماهرند. بازرگانی در این شهر رواج کامل دارد. بزرگترین محصول آن حریر، صابون، اسفنج، مازو، تنباکو، پرتقال، لیمو و سایر میوه هاست . جمعیت این شهر از بیست هزار تن افزون باشد که قسمت عمده ٔ آن مسلمانان و بقیه عیسویان از طوایف مختلف رومیها و مارونیها، کمی از یهودان و سایر ادیان میباشند. لنگرگاه کنونی این شهر در مرکز قدیمی خود واقع و اکثر مراکز تجارتی در آنجاست و قریب ده هزار تن جمعیت آن میباشد.مسیحیان چندین بار این شهر را در حصار گرفتند و زیان و خسارت بسیار بدان وارد آوردند و کتابخانه ٔ آنجا را که دارای سیصدهزار مجلد از کتب زبانهای عربی و پارسی و یونانی بود طعمه ٔ حریق ساختند. سلطان صلاح الدین ایوبی اگرچه مدتی آنجا را در سال <span class=\"hlight\" dir=\"rtl\">٥٨٤</span> هَ . ق . محاصره کرد، ولی موفق به اخراج مسیحیان و فتح شهر نگردید.بعد از سلطان صلاح الدین یکی از ملوک مصر آنجا را بگشود و خلقی بسیار از اهالی آنجا را بکشت، معذلک پادشاه قبرس در <span class=\"hlight\" dir=\"rtl\">٧٦٨</span> هَ . ق . شهر مزبور را بازستاند و آن شهر را آتش زد و ویران ساخت . چند بنا از آثار قدیم آنجا باقی است، از آن جمله شش برج برای محافظت و نگهبانی شهر بر کنار دریا از جهت شمال زبانه ٔ سابق الذکر برپاست . (ذیل معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٢</span>). و صاحب قاموس الاعلام آرد: طرابلس شام . نام شهر مرکزی ایالتی تابع بیروت در ساحل شام است و در <span class=\"hlight\" dir=\"rtl\">٦٥</span>هزارگزی شمال شرقی بیروت، بر نهر ابوعلی و سه هزارگزی بالای مصب نهر مذکور و در دامنه ٔ کوه منفردی واقع است . اسکله ای در مصب رودخانه و ساحل بحر دارد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٤٠٠٠</span> تن است و دارای یک قلعه مربوط به زمان اهل صلیب میباشد. <span class=\"hlight\" dir=\"rtl\">١٧</span> جامع، <span class=\"hlight\" dir=\"rtl\">٢٨</span> مدرسه و کتابخانه، <span class=\"hlight\" dir=\"rtl\">١٥</span> تکیه و مدارس ابتدائی و متوسطه دارد و دارای دوازده کلیسا و دیر دارالحکومه ٔ منتظم، بازار زیبای پر جوش وخروش، کارخانه های ابریشمی متعدد و دباغخانه های بسیار است، کمربندهای حریری بنام طرابلس، قماشهای ابریشمی برای چادرشب و غیره از ساخته های مخصوص آن شهر است .صابون پزخانه ها، کارگاههای عطرسازی، باغ ها و باغچه های بسیار زیبا و باصفای پرتقال و لیموی لطیف و نیکو در آن شهر وجود دارد. تجارت آن دارای رونق مخصوصی است چه در سایه ٔ دایر بودن اسکله تجارت جهات حما و حمص روز به روز رو به تزاید و ترقی است و نیز شهر طرابلس مرکز تجارت اسفنج میباشد که در آنجا صید میگردد. <span class=\"hlight\" dir=\"rtl\">١٥٠٠٠</span> تن از اهالی آن مسلمان و بقیه نصاری هستند که به جماعات گوناگون منقسم میشوند و همه بزبان عربی تکلم میکنند. طرابلس شام شهر قدیمی است و بوسیله ٔ مهاجران صور و صیدا و ارواد تأسیس شده و از سه محله ترکیب یافته بود گرداگرد هر یک را سوری احاطه میکرد و از این رو آنرا تریبولیس (یعنی سه بلده ) نامیده اند، این شهر در زمان رومیان و امپراتوران قسطنطنیه نیز بسیار معمور و آباد بوده است . مسلمانان پیرایه هایی هم برآن بستند و آن را آبادتر کردند. یک کتابخانه ٔ بسیاربزرگ در اینجا تأسیس کرده بودند، بدبختانه اهل صلیب این کتابخانه را آتش زدند با وجود سوء اداره ٔ آن زمانها با کشورهای اروپا مناسبات تجارتی پیدا کرده بود و کارخانه های بسیار حریر و شیشه و غیره در آن بکارافتاد. صلااح الدین ایوبی و بیبرس اینجا را دربندان کردند و سرانجام به دست قلاوون فتح و مسترد گردید. شهرقدیم در ساحل واقع است و در اطراف اسکله آثار عتیقه فراوان مشاهده میشود. در زمان یاور سلطان سلیم خان با دیگر ممالک شام به کشور عثمانی ملحق شد و مدت مدیدی مرکز ایالتی بشمار میرفت . و رجوع به مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٤٨٠</span> و نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٢٥٣</span> و <span class=\"hlight\" dir=\"rtl\">٢٦٨</span> و فهرست حبیب السیر چ خیام و ایران باستان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٣٢</span> و عقدالفرید چ سعید عریان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٤</span> و تاریخ مغول اقبال ص <span class=\"hlight\" dir=\"rtl\">٢١٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٦٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٧٦</span> و سفرنامه ٔ ناصرخسرو چ برلن ص <span class=\"hlight\" dir=\"rtl\">١٧</span>، <span class=\"hlight\" dir=\"rtl\">١٨</span> و <span class=\"hlight\" dir=\"rtl\">٢٨</span> و کلمه ٔ اطرابلس شود.<br /></font></div>'),
(176236, 'طرابلس شام', '<span class=\"hlight\">طرابلس شام .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ل ُ س ِ ]</font></b>(اِخ ) مؤلف قاموس الاعلام گوید: نام قضائی است در ولایت بیروت و عبارت است از قسم جنوب غربی سنجاق، از طرف شمال و شرق با قضای عکامحدود میباشد، و <span class=\"hlight\" dir=\"rtl\">٩١</span> قریه دارد و مشتمل است بر <span class=\"hlight\" dir=\"rtl\">٥</span> ناحیه و اراضی عشیره ٔ عرب الجحیش و عده ٔ نفوس آن بر <span class=\"hlight\" dir=\"rtl\">٤١٨٧١</span> تن بالغ گردد و <span class=\"hlight\" dir=\"rtl\">٣٠٣٣٦</span> تن از اینان مسلمانند - انتهی . امروزه دارای <span class=\"hlight\" dir=\"rtl\">٤٠٠٠٠</span> سکنه است . <BR><font color=\"Blue\">◄</font> طرابلس شام (سنجاق ...) مؤلف قاموس الاعلام ترکی آرد: یکی از ایالتهای پنجگانه ٔ ولایت بیروت است ؛ از طرف جنوب به سنجاق جبال لبنان، از سمت مشرق به سنجاق حما از ولایت سوریه، از سوی شمال به سنجاق لاذقیه و از جانب مغرب به دریای سفید محدود میباشد. اراضی آن ناهموار و پرعارضه است، دامنه های جبل لبنان و جبل نصیریه در اندرون سنجاق پخش شده، انهار بسیاری دارد و از همه بزرگتر در میان دو سلسله ٔ مزبور جاری و موسوم به نهر کبیرمیباشد، و خاک آن بسیار حاصلخیز و پرمحصول و هوای سواحل آن بی اندازه گرم و نقاط مرتفع داخله ٔ آن خنک و بطور کلی معتدل و سالم است . محصولات عمده ٔ آن عبارت از: گندم، جو، ذرت، ارزن، نخود، عدس باقلا و حبوبات دیگر و نیز تنباکو و سیب زمینی و غیره و میوه های بسیار از قبیل : پرتقال، لیمو، انار، انجیر، انگور، زیتون فراوان هم دارد، روغن زیتون بمیزان کلی حاصل شود، زنبور و کرم ابریشم آن نیز فراوان است و انگبین و نوغان جزو صادرات سنجاق است، و در اندرون لوا به پرورش دام نیز توجه بسیار میشود. سالانه بیش از <span class=\"hlight\" dir=\"rtl\">٣٠٠٠٠٠</span> اوقه پشم حاصل گردد. مقدار جنگلهای سنجاق به <span class=\"hlight\" dir=\"rtl\">١٥٧٠٠٠</span> دونم بالغ میشود و درختان بزرگ و گوناگون صنعتی دارند. اکتشافاتی برای کشف معادن هنوز بعمل نیامده، نفوس لوابه <span class=\"hlight\" dir=\"rtl\">١٢٤٧٨٥</span> تن بالغ گردد که قریب <span class=\"hlight\" dir=\"rtl\">٩١١٨٣</span> تن مسلم سنی و نصیری و بقیه غیرمسلم روم، مارونی، کاتولیک، ارمنی، پروتستان و یهودی میباشند و <span class=\"hlight\" dir=\"rtl\">١٥٤</span> باب جوامع و مساجدو مکاتب و معابد دیگر دارد. <span class=\"hlight\" dir=\"rtl\">٥٦٧</span> قریه در این سنجاق موجود است و به چهار قضا و <span class=\"hlight\" dir=\"rtl\">٥</span> ناحیه مقسم گشته است .<br /></font></div>'),
(176237, 'طرابلس غرب', '<span class=\"hlight\">طرابلس غرب .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ل ُ س ِ غ َ ]</font></b> (اِخ ) شهری است بمغرب . (منتهی الارب ) (آنندراج ). شهری است در پایان سرزمین برقةو ابتدای زمین افریقیه . (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٥</span>). از مشاهیر بلاد افریقیه مملکتی است از اقلیم دوم و سوم و بلاد مشهورش فزان و ولایت بسیار دارد. (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٢٦٤</span> و <span class=\"hlight\" dir=\"rtl\">٢٦٩</span>). این ناحیت در قدیم حد غربی مملکت ایران بوده، در ساحل بحرالروم و شمال افریقیه میان تونس و مصر واقع و به نام کرسی افریقا (طری پولی تن ) معروف گردیده، و دارای هفتادهزار جمعیت است . یاقوت گوید: و آنرا طرابلس گویند و از گفتار ابن بشیر آورده است : طرابلس به رومیه و افریقیه بمعنی سه شهر است و یونانیان آنرا طرابلیطة نام نهادند. و این لفظ در لغت آنان افاده ٔ معنی سه شهر کند، زیرا طرا بلغت آنان بمعنی سه و بلیطة بمعنی شهر باشد و نیز ابن بشیر در کتاب خود آورده که قیصر روم اشباروس اول کسی است که طرابلس را بنا کرد. و این شهر را بشهر اناس نیز مینامند. شهر طرابلس را حصاری است از سنگهای سخت و بزرگ، با بنائی جلیل، این شهر بر کنار دریا واقع است و مسجد جامع آن نیکوترین جوامع شهرها است، بازارهای شهر بسیار معتبر و همواره مملو از مردم است که در کار معامله و داد و ستد میباشند. مسجدی نیز دراین شهر هست که آن را مسجدالشعاب خوانند، و مورد توجه اهالی شهر است . در اطراف و جوانب شهر گروهی از نبطیان را قرارگاههائی است که از جانب شرق و غرب مسافت سه روز راه امتداد دارد تا بموضع معروف به بنی السایری . و از جانب قبله مسافت دو روز راه ممتد است تا بحد هواره رسد، و در میان برابر آن حدود کسانی یافت می شوند که بزبان نبطیان سخن میگویند. در این شهر چندین رباط ساخته شده که صلحا و اهل اﷲ را پناهگاه و محط رحالست و مشهورترو معمورتر از همگی آن رباطات مسجدالشعاب است . لنگرگاه کشتیها در این شهر از بادهای مخالف پیوسته ایمن است . میوه ها و انواع نعمتها و خیرات دراین شهر فراوان است، در جانب مشرق شهر باغها و بساتین بسیار می باشد، صحرای شوره ناک بزرگی بشهر پیوسته است که نمک بسیاری از آنجا برداشت می کنند. در داخل شهر چاهی است موسوم و معروف به بئر ابی الکنود که اهالی آن چاه را زشت شمارند و هرکه از آب آن نوشد گول و نادان شود و اگر از کسی امری ناملایم سرزند گویند بر تو حرجی نیست، چه بیگمان از آب چاه ابی الکنود نوشیده ای، و این امر بر اثر نوشیدن آن آب از تو ناشی شده است . گواراترین آب های این شهر آب بئرالقبه است . لیث بن سعد گوید: عمروبن العاص در سال <span class=\"hlight\" dir=\"rtl\">٢٣</span> هَ . ق . بغزای طرابلس شد تا به قبه ای که در بلندی جهت شرقی شهر واقع بود فرودآمد و با آنکه در آنجا مدت دو ماه شهر را در حصار داشت کاری از پیش نتوانست برد. مردی از لشکریان عمرو که از طایفه ٔ بنی مدلج بود، روزی با هفت تن از همکاران خود بعزم شکار از لشکرگاه خارج و بجانب غربی شهر روانه گردید و در آنجا جمع شدند. اتفاقاً روزی سخت گرم بود و تاب گرما نتوانستند آورد، عازم بازگشت به جایگاه خود شدند و بر کنار دریا که به شهر اتصال داشت راه خویش پیش گرفته میرفتند، چون بین دریا و شهر دیوار و حاجزی نبود و کشتی بانان نیز مشغول لنگر انداختن بودند که به خانه های خود شوند، مدلجی و همراهان ملتفت شدند و در همان اثنا آب دریا از ناحیه ٔ شهر فرونشست، آنان نیز فرصت غنیمت شمردند و از همان جانب که آب فرونشسته بود داخل شهر شدند تا به کلیسای شهررسیدند، در آنجا بالاتفاق آواز به تکبیر بلند ساختند، رومیان در آن حال پناهگاهی جز کشتیهای خود نداشتند، عمرو عاص نیز با لشکریان به شهر هجوم آورد و بر رومیان بتاختند، رومیان همین قدر توانستند آنچه از حیث وزن سبک و حمل و نقلش آسان بود با خود از معرکه بدربرند و عمرو با کمال فراغت خاطر شهر را فتح کرد و آنچه در شهر یافت بغنیمت برد هرثمةبن اعین در اوقاتی که به حکومت طرابلس برقرار بود، فرمان داد تا بین دریا و شهر دیواری بنا کردند و در کتاب ابن عبدالحکم آمده است که عمروبن العاص شهر طرابلس غرب را بقهر و غلبه گشود و بدانچه در آن شهر بود دست یافت . (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>). از ایالات دولت عثمانی در افریقیه و از بلاد مغرب است نزدیک شط بحری واقع است بمسافت <span class=\"hlight\" dir=\"rtl\">٨٠٠</span> میل محدود است شمالاً ببحر ابیض متوسط و جنوباً بصحرای کبیر و شرقاً بخدیویه ٔ مصریه و غرباً به ایالت تونس و اقلیم الجزائر. مساحت آن قریب یک میلیون کیلومتر مربع و جمعیت آن یک میلیون و پانصد هزار تن میباشد که یک ثلث آنان در بنی غازی و یک ثلث در برقه و باقی آنان در سایر ولایات ایالت سکنی دارند، و بیشتر آنان از نژاد عرب و قریب یکصدهزار تن هم یهوداند واندکی نیز از ترکان و اروپائیان در بین آنان هست . اکثر اهالی متمایل به صحرانشینی میباشند، از این رو ایالت طرابلس را شهرستان و ده کم است و در زمان قدیم اراضی آنجا بسیار حاصلخیز بوده و از چاهها و قنوات وچشمه های طبیعی مشروب میشده و بیشه و درخت بسیار داشته که اینک بواسطه ٔ کمی آبها و نباریدن باران، اراضی اغلب خشک و بی حاصل است و اگر جائی هم استعداد کشت وزرع داشته باشد، بواسطه ٔ فقدان نهر جاری و چشمه ٔ طبیعی مشروب ساختن آن اراضی با آبهای بارانی است که درانبارهای بزرگ ذخیره نهاده اند، ولی در نواحی شمال غربی بلاد برقه و بنی غازی چشمه ها و چراگاههائی یافت می گردد و با آن چشمه ها و مراتع گندم و ذرت میکارند. و از محصول این بلاد روغن، زیتون، خرما، خرنوب (نباتی است بری خاردار)، پرتقال، لیمو، زعفران، زبدة (سرشیر)، عسل، و غیرهاست و معدنی قابل ذکر ندارد، ولی از بعض نواحی آن کبریت و گچ استخراج میکنند و از معدن مزبور تخته سنگهای بزرگ جهت بنای عمارت بیرون می آورند. تجارت این ایالت با سودان و مصر و اروپاست صادرات آن عبارت است از اقسام پوستها و گوسپند. حیوانات آن اسب، استر، میش، بُز، آهو و درندگان و کفتار و شغال است .معارف در این ایالت کم پیشرفته است . تعلیمات لشکری بین همگی قبائل و عشائر دائر است و قبائل وابسته به این ایالت را اقبال شایانی به آموختن آن میباشد. مخزنهای لشکری طرابلس مشحون و مملو از آلات و ادوات حربیه است و استحکامات سواحل در نهایت استواری است . در این ایالت پایگاههائی موجود است که به توپهای قوی مسلح و به سنگرهای بسیار محکم ترتیب داده شده و هر نوع ذخائر جنگی در آن سنگرها فراهم باشد، این ایالت در زیر فرمان یک والی از جانب دولت عثمانی اداره میشود . این ایالت به پنج متصرفیه منقسم است : متصرفیه ٔ اول، متصرفیه طرابلس است، مرکزو والی نشین آن نیز به نام طرابلس خوانده میشود و مقر رئیس پادگان در آنجاست و این مرکز بر زبانه ٔ دریا واقع و به باروئی استوار استحکام یافته و لنگرگاهی بس نیکوست، ولی عمق آن کم میباشد و در واقع بندر صادرات و واردات است . دارای چندین دبستان عمومی و لشکری است . متصرفیه دوم، فزان است و آن بزرگترین بخشهای این ایالت است و در جنوب این ایالت واقع شده، و طول آن از شرق به غرب <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> میل و معظم عرض آن از شمال به جنوب <span class=\"hlight\" dir=\"rtl\">٢٥٥</span> میل و هوای آن گرم و بارانش کم و سکان آن اغلب در واحه های کوچک زندگانی می کنند و اغلب اعتماد و پشتیبانی آنان به درخت خرماست، معذلک از حبوبات و انجیر و انار و پرتقال نیز بی بهره نیستند، قاعده ٔ آن شهر مرزوق و دارای یکصدهزار تن جمعیت میباشد. سوم متصرفیه ٔ آن، جبل غربیه است . مرکز آن شهر غدامِس است و غدامس در جنوب غربی طرابلس واقع است و تا آنجا پانزده روز مسافت راه است . متصرفیه ٔ چهارم، خس است . مرکز آن سوکنه است . متصرفیه ٔ پنجم، بنی غازی است و آن بندرگاهی است بر دریای متوسط، ایستگاه کشتیها در ساحل آنجا پوشیده شده از رمل است و برای داخل شدن در بندر مستعد نیست . از شهرهای این متصرفیه، درنه، برقه، و اوجله است که مسلمانان در سال <span class=\"hlight\" dir=\"rtl\">٢٣</span> هَ . ق . بفتح آن موفق گشتند، عمروبن العاص و زبیربن العوام در خلافت عثمان بن عفان شهر اوجله را فتح کردند و دولت عثمانی در روزگار سلطان سلیم دوم بر این شهر استیلا یافت بسال <span class=\"hlight\" dir=\"rtl\">٩٥٨</span> هَ . ق . و پیش از آن تاریخ شهر مزبور در تحت تصرف دولت بنی حفص بود، سپس اسپانیولیها آن شهر را اشغال کردند و چندان نسبت به اهالی آن شهر جور و ستم کردند که به فریاد و فغان آمدند و به ایتالیا پناه بردند و خود را تسلیم سلطه و نفوذ آن دولت ساختند، مشروط بر آنکه فقط حصون و استحکامات را به ایتالیا تفویض کنند و در ازاء این امر ایتالیا از دخالت در امور داخلی آنها اغماض و خودداری کند. ولی دولت ایتالیا به پیمان خود وفا نکرد و در امور داخلی آنان به دخالت پرداخت و بالنتیجه کار به جنگ کشید و مردم طرابلس دست بسوی دولت عثمانی دراز کردند و از آن دولت یاری خواستند و هیئتی بدان کشور گسیل داشتند که تقاضا کنند شهر آنان را از زیر بار ستم برهاند. دولت عثمانی مسؤول آنان را اجابت کرد و نیروی دریائی خود را بسوی طرابلس فرستاد و مردم آن شهر را از ستمگری ایتالیا آزاد ساخت ؛ ولی با داشتن استقلال داخلی تابع عثمانی گردید تا آنکه یوسف پاشا قیام کرد و دولت عثمانی با او به نبردپرداخت و در سال <span class=\"hlight\" dir=\"rtl\">١٢٥١</span> هَ . ق . کاملاً آن شهر را جزو متصرفات خود قرار داد. (ذیل معجم البلدان ص <span class=\"hlight\" dir=\"rtl\">٢٩٤</span>). و صاحب قاموس الاعلام آرد: طرابلس غرب نام اسکله و شهری است در ساحل شمالی افریقا، در بحر ابیض و مرکز ولایت بزرگ موسوم به همین اسم میباشد و در <span class=\"hlight\" dir=\"rtl\">١٦٠٠</span> کیلومتری جنوب غربی استانبول و <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> کیلومتری جنوب شرقی تونس در<span class=\"hlight\" dir=\"rtl\">٣٣</span> درجه و <span class=\"hlight\" dir=\"rtl\">٥٤</span> ثانیه و <span class=\"hlight\" dir=\"rtl\">١٠</span> درجه و <span class=\"hlight\" dir=\"rtl\">٥٠</span> دقیقه و <span class=\"hlight\" dir=\"rtl\">٣٥</span> ثانیه عرض شمالی با طول شرقی دیده میشود، و شماره ٔ نفوس آن به <span class=\"hlight\" dir=\"rtl\">٣٥٠٠٠</span> تن بالغ گردد و قریب پنج شش هزار تن از اینان یهودی، مالتی و اجنبی و بقیه مسلمانند. بازارهای پرمعامله، جوامع و مساجد متعدد، سور، قلعه و بعضی استحکامات و یک کاخ وسیع دولتی و یک نورافکن دارد ونیز یک باب جامع محتشم و پر نقش و نگار از طرف طغورت پاشا در این شهر بنا شده و مکان وسیع مسمی به منیشه دارد، در اینجا باغها و باغچه های پر از درختان لیموو پرتقال و نخلهای تناور و تعداد بسیار قصور و عمارات بزرگ دیده میشود. لنگرگاهش باز و تنگ است و جهت غربیش با یک دماغه ٔ طویل مشتمل بر بعض استحکامات محفوظ میباشد. بر این لنگرگاه چند جزیره ٔ کوچک خودنمائی میکنند که در صورت پر کردن بین آنها محافظت آن سخت آسان خواهد بود. در حال حاضر مدخلش تنگ و میانش پر و از این رو برای ورود سفاین بزرگ نامساعد و گرفتار امواج است و با این وصف طرابلس غرب در بین سودان و اروپا موقع بس مهمی دارد، تجارت پرحرارتی در این دیار حکمفرماست، آمد و شد سفائن بسیار میباشد و از راه غدامس و فزان به برنوح، وادی، و تمبکتو و همه ٔ نقاط سودان کاروانهای منظم ایاب و ذهاب دارند. مقدار وارداتش سالانه از <span class=\"hlight\" dir=\"rtl\">١٠</span>میلیون و صادراتش سالانه از <span class=\"hlight\" dir=\"rtl\">١٨</span>میلیون فرانک تجاوز نماید، واردات عمده اش عبارت است از منسوجات آبی رنگ و اقمشه ٔ دیگر و نیز قهوه، شکر و غیره . و گاو و حیوانات دیگر، نمک، دوخ (حلفا)، پوست، پر شترمرغ و دندان فیل که از سودان می آید، اقلام صادراتی شهر مزبور را تشکیل میدهد. خانه های شهر بشکل مدرسه است، یعنی حیاط دارد و پنجره ها رو به حیاط باز میشوند، بطرف کوچه پنجره ندارند، کویهایش بسی تنگ و در اکثر نقاط هوا در مضیقه است و جریان لازم را ندارد و معالوصف هوایش معتدل و بسیار سالم میباشد، بتقدیر تعمیر و تجدید بندرگاه بسرعت رو بترقی تجارت و آبادی خواهد رفت، بلکه در اندک زمانی با اسکندریه در تجارت خواهد توانست رقابت کند. در این شهر حصیرهای زیبا و حوله های قشنگ بعمل می آورند و نیز بعضی معمولات ظریف از عاج میسازند. شهر طرابلس غرب یکی از بلاد بسیار قدیم است . به اعتقاد بربرها اسم باستانی آن وایه یا وایات بوده، اما در کتب غربی بشکل بناره ضبط شده است . این شهر به دست فینیقیان افتاد و آنان آبادش کردند، رومیان آنرا به نام «اویا» خواندند و آن خطه را تریپولیس نامیدند که معرب آن بشکل طرابلس درآمده، بعدها نام خطه را بشهر هم اطلاق کردند. بسال <span class=\"hlight\" dir=\"rtl\">٢٣</span> هَ . ق . عمروبن عاص این شهر را فتح کرد و ضمیمه ٔ ممالک اسلامی ساخت، در ادوار اولیه ٔ اسلام معمور بود و مسقط رأس بعضی از علماو مشاهیر است در اوائل قرن شانزدهم میلادی، اسپانیولیها و بعدها شوالیه های مالط این سرزمین را تحت تصرف خویش درآوردند و بسال <span class=\"hlight\" dir=\"rtl\">٩٥٧</span> هَ . ق . در عصر سلطان سلیمان قانونی طغورت پاشای مشهور اینجا را ضبط و بممالک عثمانی ملحق ساخت پادشاه مذکور جامع محتشمی در این شهر بنا کرد که مقبره اش هم در حظیره ٔ آن دیده میشود.<br /></font></div>'),
(176238, 'طرابلسی', '<span class=\"hlight\">طرابلسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ل ُ ]</font></b> (اِخ ) علی علاءالدین ابوالحسن علی بن خلیلی الطرابلسی الحنفی، قاضی القدس الشریف . ولادتش بسال <span class=\"hlight\" dir=\"rtl\">٨٤٤</span> هَ .ق . بوده، او راست : معین الحکام فیما یتردد بین الخصمین من الاحکام (فقه حنفی ) این کتاب بر سه بخش و تمامی در علم قضاء است . <span class=\"hlight\" dir=\"rtl\">١</span> - در مقدمات این علم که احکام مبتنی بر آن است . <span class=\"hlight\" dir=\"rtl\">٢</span> - در دلایلی که قضایا را از یکدیگر متمایز میسازد. <span class=\"hlight\" dir=\"rtl\">٣</span> - در احکام سیاست شرعیه . یک نوبت در بولاق بسال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> هَ . ق . و نوبتی هم در مطبعه ٔ میمنیه بسال <span class=\"hlight\" dir=\"rtl\">١٣١٠</span> هَ . ق . و در حاشیه ٔ آن نیز کتاب لسان الحکام فی معرفةالاحکام از تألیفات ابوالولیدبن شحنة بطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣٦</span>).<br /></font></div>'),
(176239, 'طرابلسی', '<span class=\"hlight\">طرابلسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ل ُ ]</font></b> (اِخ ) القاضی سعدالدین عزالمؤمنین ابوالقاسم عبدالعزیزبن تحریربن عبدالعزیزبن البراج . رجوع به ابن برّاج شود.<br /></font></div>'),
(176240, 'طرابلسی', '<span class=\"hlight\">طرابلسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ل ُ ]</font></b> (اِخ ) الشیخ عبدالغنی الفاروقی الطرابلسی . او راست : اشراق الانوار فی اطلاق العذار.این کتاب در ادب است که بسال <span class=\"hlight\" dir=\"rtl\">١٢٦٨</span> هَ . ق . تألیف وطبع هم شده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٨٧</span>).<br /></font></div>'),
(176241, 'طرابلسی', '<span class=\"hlight\">طرابلسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ل ُ ]</font></b> (اِخ ) السید محمدبن ابراهیم الحسینی الطرابلسی . او راست : تفسیر الحسینی که جزء اول آن به آخر سوره ٔ بقره پایان یافته، و در طرابلس شام بسال <span class=\"hlight\" dir=\"rtl\">١٣٣٢</span> هَ . ق . چاپ شده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">١</span> ستون <span class=\"hlight\" dir=\"rtl\">٧٧٤</span>).<br /></font></div>'),
(176242, 'طرابلسی', '<span class=\"hlight\">طرابلسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ل ُ ]</font></b> (اِخ ) مصطفی بن محمدبن ابراهیم بن ذکری الطرابلسی المغربی . او راست : دیوان شعری که در مطبعه ٔ عبدالرزاق بسال <span class=\"hlight\" dir=\"rtl\">١٣١٠</span> هَ . ق . بطبع رسیده است . دیگر شرح قصیده ٔ ابن ذکری که در علم میقات است و آن در شهر فاس چاپ شده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">١</span> ستون <span class=\"hlight\" dir=\"rtl\">١٠٦</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣٦</span>).<br /></font></div>'),
(176243, 'طرابلسی', '<span class=\"hlight\">طرابلسی .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ل ُ ]</font></b> (اِخ ) برهان الدین ابراهیم بن ابی بکربن الشیخ علی الطرابلسی الحنفی نزیل القاهرة. ولادت او بسال <span class=\"hlight\" dir=\"rtl\">٨٤٣</span> هَ . ق . و وفات وی در <span class=\"hlight\" dir=\"rtl\">٩٢٢</span> هَ . ق . بوده است . او راست : الاسعاف فی الاحکام الاوقاف (فقه حنفی ) مختصری است که دو کتاب وقف هلال و خصاف را در آن گرد آورده و در بولاق به طبع رسیده است بسال <span class=\"hlight\" dir=\"rtl\">١٢٩٢</span> هَ . ق . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣٥</span>).<br /></font></div>'),
(176244, 'طرابلیس', '<span class=\"hlight\">طرابلیس .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ]</font></b> (اِخ ) (... شام ) رجوع به طرابلس شام شود. تری پولیس نزدیک جبل لبنان و در مصب رودی واقع است که به دریای مغرب میریزد. بعدها شهر مزبور در موقع جنگهای صلیب به دست فرانکها افتاد، و پس از آن مسلمین شهری در نزدیکی تری پولیس قدری دورتر از دریا ساختند که موسوم به طرابلیس شرق گردید. (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٦٨</span>). رجوع به ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢٨</span> شود.<br /></font></div>'),
(176245, 'طرابلیس', '<span class=\"hlight\">طرابلیس .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ]</font></b> (اِخ ) (... غرب ) رجوع به طرابلس غرب و ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٥٤</span> شود.<br /></font></div>'),
(176246, 'طرابنش', '<span class=\"hlight\">طرابنش .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ن ُ ]</font></b> (اِخ ) نام شهری است به جزیره ٔ صقلیه . (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br /></font></div>'),
(176247, 'طرابوزان', '<span class=\"hlight\">طرابوزان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) رجوع به طرابزون و تاریخ مغول اقبال آشتیانی ص <span class=\"hlight\" dir=\"rtl\">٤٥٩</span>، <span class=\"hlight\" dir=\"rtl\">٥٦٩</span>، <span class=\"hlight\" dir=\"rtl\">٥٧٠</span>، <span class=\"hlight\" dir=\"rtl\">٥٧٢</span>، <span class=\"hlight\" dir=\"rtl\">٥٧٤</span> و ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٧٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٣٨</span> و ترجمه ٔ تاریخ ادبیات براون ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٣١</span>، <span class=\"hlight\" dir=\"rtl\">٤٤٨</span>، <span class=\"hlight\" dir=\"rtl\">٤٥٠</span>، <span class=\"hlight\" dir=\"rtl\">٤٥١</span>، <span class=\"hlight\" dir=\"rtl\">٤٥٤</span>، <span class=\"hlight\" dir=\"rtl\">٤٥٥</span>و تاریخ ادبیات براون ترجمه ٔ رشیدیاسمی ص <span class=\"hlight\" dir=\"rtl\">٣٧</span> شود.<br /></font></div>'),
(176248, 'طرابوزن', '<span class=\"hlight\">طرابوزن .</span> <font color=\"DarkGreen\"><b>[ طَ زَ ]</font></b> (اِخ ) رجوع به طرابزون و ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٩٥</span>، <span class=\"hlight\" dir=\"rtl\">١٠٨٩</span>، <span class=\"hlight\" dir=\"rtl\">١٩٠٠</span>، <span class=\"hlight\" dir=\"rtl\">١٥١٠</span> شود.<br /></font></div>'),
(176249, 'طرابیة', '<span class=\"hlight\">طرابیة.</span> <font color=\"DarkGreen\"><b>[ طَ ب ِ ی َ ]</font></b> (اِخ ) از نواحی حوف مصر است و ذکر آن در اخبار آمده است . (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤</span>).<br /></font></div>'),
(176250, 'طرابیة', '<span class=\"hlight\">طرابیة.</span> <font color=\"DarkGreen\"><b>[ طُ ب ِ ی َ ]</font></b> (اِخ ) شهرستانی است به مصر، یا آن ضرابیه است . (منتهی الارب ).<br /></font></div>'),
(176251, 'طرابیشی', '<span class=\"hlight\">طرابیشی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) شیخ محمد طرابیشی او راست کتابی بنام تبصرةالاخوان فی بیان اضرار التبغ المعروف بالدخان که در مصر بطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٣٦</span>).<br /></font></div>'),
(176252, 'طرابیل', '<span class=\"hlight\">طرابیل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) این نام به این صورت و صورت طَرایل در تاریخ سیستان آمده و او سالار هندوان یعقوبی بود. رجوع به تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٠٧</span>، <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>، <span class=\"hlight\" dir=\"rtl\">٣١١</span> شود.<br /></font></div>'),
(176253, 'طرابیل', '<span class=\"hlight\">طرابیل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طربال . (اقرب الموارد).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرابیل الشام </span> ؛ صومعه های شام .<br /></font></div>'),
(176254, 'طرابیون', '<span class=\"hlight\">طرابیون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به یونانی علک البطم است . (فهرست مخزن الادویه ). رجوع به طرامیلس شود.<br /></font></div>'),
(176255, 'طرات', '<span class=\"hlight\">طرات .</span> <font color=\"DarkGreen\"><b>[ طُ ر ر ]</font></b> (ع اِ) ج ِ طُرّة.<br /></font></div>'),
(176256, 'طراثوث', '<span class=\"hlight\">طراثوث .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) طراثیث است و گفته اند اسمی است مشترک میان اشترغار و اشق . (فهرست مخزن الادویه ).<br /></font></div>'),
(176257, 'طراثیث', '<span class=\"hlight\">طراثیث .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) بمعنی طرثوث است و آن میوه ای است که به فارسی بل گویند. (برهان ). هیور، بیخ گیاهی است سرد به درجه ٔ دوم و خشک بسوم تقویت اعضا دهد و خون شکم دفع کند. (نزهةالقلوب خطی ). نام میوه ای است . (غیاث اللغات ). طرثوث نیز گویند. بشیرازی بل شیرین خوانند سرخ و سفید بود، بهترین وی سفید بود، طبیعت وی سرد و خشک بود در سیم، قطع خون رفتن کند از مقعد و مجموع اعضا و رحم و شکم ببندد و قوت مفاصل و جگر و معده دهد و چون با روغن گاویا شیر بز پاره ای بپزند و بیاشامند استرخاء معده رامفید بود و مقدار مأخوذ از وی یک مثقال بود و اسحاق گوید: مضر بود بسفل و مصلح وی گلنار است . و بدل وی جفت بلوط بوزن آن و گویند نیم وزن آن پوست تخم مرغ سوخته ٔ شسته (کذا) و چهار دانگ وزن آن قرط و شش یک آن عفص و ده یک آن صمغ عربی است . (اختیارات بدیعی ). بمعنی زُب الارض و زب الریاح است . و آن نباتی است خشبی شبیه به قطر و در زمین فرورفته و سرخ و سفید میباشد و گیاه او مثل برگ پیچیده و بیشتر در نخودزار و زیر درختها میروید و قسم سرخ او شیرین و مأکول است و باقبض و سفید او تلخ میباشد، در سیم سرد و خشک و بسیار قابض و قاطع اسهال و سیلان خون و عرق و مقوی معده و جهت اعیا و ردع مواد حاره نافع و مضر ریه و مصلحش شکر و شربتش تا دو درهم و بدلش سدس وزن او عفص و بوزن اوصمغ عربی . (تحفه ٔ حکیم مؤمن ). صاحب مخزن الادویه آرد: پس از ذکر ماهیت و طبیعت طراثیث و نقل عین بیانات تحفه ٔ حکیم مؤمن، در ذکر افعال و خواص آن گوید: بسیار قابض و قاطع و حابس اسهال و سیلان خون و عرق و مقوی کبد و معده و دابغ و دافع استرخای آن و جهت اعیا و ردع مواد حاره . و تحلیل صلابات و تقویت مفاصل مسترخیه شرباً و ضماداً و چون با شیر تازه دوشیده طبخ دهند و یا با دوغ ماست گاو بیاشامند، جهت استرخای معده و کبد نافع. مضر به ریه، مصلح آن شکر و مخشن جلد و مصلح آن بزرقطونا، مقدار شربت آن تا دو درم، بدل آن ثلث وزن آن عفص و دو ثلث آن قرط و نصف وزن آن قشر بیض محترق و عشر وزن آن و بقولی بوزن آن صمغ عربی است واقاقیا بوزن آن نیز گفته اند. (مخزن الادویه ). در سیستان او را خیسرو و هسیرو هم گویند. ارجانی گوید: طراثیث سرد است در دو درجه و خشک است در سه درجه و هیئت او آن است که چوب بارها کژ بود بمقدار انگشت، و سرخ و تیره رنگ باشد و منبت او در بادیه باشد و طعم او دلالت قبض بود و استرخای معده را دفع کند و معده را دباغت کند. محمد زکریا گوید: بدل طراثیث در بستن شکم ورفتن خون از شکم نیم جزو از پوست بیضه سوخته است و نیم جزو او مازو. ارجانی گوید: سُدس او مازو است و عشر او صمغ است . (ترجمه ٔ صیدنه ٔ ابوریحان ). طراثیث، یسمی زب الارض و زب الریاح و هو نبت ٌ یرتفع کالورقة الملفوفة و اصله قطعٌ حمرٌ خشبیة کالقطر الی قبض و غضاضةبارد یابس فی الثانیة، یحبس و یقطع الاسهال المزمن شرباً و العرق ضماداً و یحلل الصلابات طلاءً و یمنع الاعیاء و هو یضر الرئة یصلحه السکر و یخشن الجلد، و یُصلحه البزرقطونا. (تذکره ٔ داود انطاکی ) <span class=\"hlight\">:</span> بگیرند خرما و مویز و مازو و اقاقیا و شب ّ یمانی و طراثیث، بکوبند و بر زهار نهند. (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(176258, 'طراثیث', '<span class=\"hlight\">طراثیث .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طُرْثوث . (منتهی الارب ) (تفلیسی ) (آنندراج ).<br /></font></div>'),
(176259, 'طراج', '<span class=\"hlight\">طراج .</span> <font color=\"DarkGreen\"><b>[ طُرْ را ]</font></b> (ع اِ) دُرّاج . رجوع به دراج شود.<br /></font></div>'),
(176260, 'طراح', '<span class=\"hlight\">طراح .</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (اِخ ) از اعلام است . (منتهی الارب ).<br /></font></div>'),
(176261, 'طراح', '<span class=\"hlight\">طراح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) جای دور. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176262, 'طراح', '<span class=\"hlight\">طراح .</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (ع ص ) بیرنگ گر. گرده ریز. نقشه ریز. آنکه طرح افکند. نقاش .<br /></font></div>'),
(176263, 'طراح', '<span class=\"hlight\">طراح .</span> <font color=\"DarkGreen\"><b>[ طُرْ را ]</font></b> (اِخ ) دهی از دهستان نهرهاشم بخش مرکزی شهرستان اهواز، واقع در <span class=\"hlight\" dir=\"rtl\">٣٤</span>هزارگزی شمال باختری اهواز کنار کرخه، کنار راه شوسه ٔ اهواز به سوسن گرد. دشت، گرمسیر با <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه . آب آن از رودخانه ٔ کرخه . محصول آنجا غلات . شغل اهالی زراعت و گله داری . راه آن در تابستان اتومبیل رو است . ساکنین از طایفه ٔ حلاف هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(176264, 'طراحا', '<span class=\"hlight\">طراحا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) به سریانی صمغ قتاد است که کتیرا نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(176265, 'طراحة', '<span class=\"hlight\">طراحة.</span> <font color=\"DarkGreen\"><b>[ طَرْ را ح َ ]</font></b> (ع اِ) فرشی است . یک قسم گستردنی است : فقد ذکر ان اتابک سلطان دمشق، طلب محتسباً، فذکر له رجل من اهل العلم، فامر باحضاره، فلما نظره، قال انی ولیتک امر الحسبة علی الناس بالامر بالمعروف و النهی عن المنکر، قال ان کان الامر علی کذلک، فقم عن هذه الطراحة و ارفع هذا المسند، فانهما حریرٌ و اخلع هذا الحاتم فانه ذهب ٌ و قد قال صلی اﷲ علیه و آله و سلم هذان حرامان علی ذکور امتی . (معالم القربة). ج، طراریح . فراش ٌ مربعٌ یجلس علیه (عامیةٌ). (دزی ).<br /></font></div>'),
(176266, 'طراحودوطیس', '<span class=\"hlight\">طراحودوطیس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) رجوع به طراخودوطیس شود.<br /></font></div>'),
(176267, 'طراحی', '<span class=\"hlight\">طراحی .</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (حامص ) عمل و شغل طراح . بیرنگ گری . نقشه ریزی . نقشه بنائی را بر کاغذ، با حبر یا مداد و یا بر زمین با گچ و مانند آن کردن . نقاشی . (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(176268, 'طراحی', '<span class=\"hlight\">طراحی .</span> <font color=\"DarkGreen\"><b>[ طُ حی ی ]</font></b> (ع ص ) سیرٌ طُراحی ٌ؛ سیر دور و دراز. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176269, 'طراحی کردن', '<span class=\"hlight\">طراحی کردن .</span> <font color=\"DarkGreen\"><b>[طَرْ را ک َ دَ ]</font></b> (مص مرکب ) نقشه ریختن . طرح کردن .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(176270, 'طراخنة', '<span class=\"hlight\">طراخنة.</span> <font color=\"DarkGreen\"><b>[ طَ خ ِ ن َ ]</font></b> (ع اِ) ج ِ طرخان . (منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span> فقال یحیی بن خالد البرمکی، یا امیرالمؤمنین ... و علی بن عیسی، قتل صنادید اهل خراسان و طراخنتها... (آداب الوزراء جهشیاری ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span>). رجوع به ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٥٧</span> شود.<br /></font></div>'),
(176271, 'طراخودوطیس', '<span class=\"hlight\">طراخودوطیس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) جربی است در باطن جفن که سخت درشت شده باشد. (بحر الجواهر نسخه ٔ خطی کتابخانه ٔ مؤلف ). و در بحر الجواهر چاپی «طراحودوطیس » آمده است .<br /></font></div>'),
(176272, 'طراخیس', '<span class=\"hlight\">طراخیس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به یونانی خذروس است . (فهرست مخزن الادویه ). و در تحفه ٔ حکیم مؤمن همین کلمه را طراخینس آورده است .<br /></font></div>'),
(176273, 'طراخینس', '<span class=\"hlight\">طراخینس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) اسم یونانی خندروس است . (تحفه ٔ حکیم مؤمن ). و در فهرست مخزن الادویه چاپی این کلمه را بصورت طراخیس ذکر کرده است .<br /></font></div>'),
(176274, 'طراد', '<span class=\"hlight\">طراد.</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (اِخ ) موضعی است . (منتهی الارب ) (آنندراج ). نام جایگاهی است که ذکر آن در شعر اسودبن یعفر آمده است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧</span>).<br /></font></div>'),
(176275, 'طراد', '<span class=\"hlight\">طراد.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع مص ) حمله آوردن بر یکدیگر. (منتهی الارب ) (آنندراج ). مطاردة <span class=\"hlight\">:</span> و از آنجا بر نیت ترتیب جهاد، با مردان جلاد، ابنای طعان و طراد روان شد. (جهانگشای جوینی ). <BR><font color=\"Blue\">◄</font> (اِ) جنگ . حمله . (دزی ).<br /></font></div>'),
(176276, 'طراد', '<span class=\"hlight\">طراد.</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (اِخ ) نام جماعتی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176277, 'طراد', '<span class=\"hlight\">طراد.</span> <font color=\"DarkGreen\"><b>[ طُرْ را ]</font></b> (اِخ ) ابن علی بن عبدالعزیز، ابوفراس السلمی الدمشقی، المعروف بالبدیع. وی نحوی و نویسنده ای ادیب و در نظم و نثر سرآمد بود. از اشعار اوست :<br />قیل لی لم جلست فی آخر القو<br />م ِ و انت البدیعرب القوافی <br />قلت آثرته لان المنادیَ -<br />ل یری طرزها علی الاطراف <br />و نیز او راست :<br />یا صاح آنسنی دهری و اوحشنی <br />منهم و اضحکنی دهری و ابکانی <br />قد قلت ارض ٌ بارض بعد فرقتهم <br />فلاتقل لی جیران بجیران <br />و همو راست :<br />یا نسیماً هب مسکاً عبقا<br />هذه انفاس ریا جلقا<br />کف عنی و الهوی مازادنی <br />برد انفاسک الاحرقا<br />لیت شعری نقضوااحبابنا<br />یا حبیب النفس ذاک الموثقا<br />یا ریاح الشوق سوقی نحوهم <br />عارضاً من سُحب دمعی غدقا<br />و انثری عقد دموعی طالما<br />کان منظوماً بایام اللقا<br />و هم از گفته های وی است :<br />هکذا فی حُبکم استوجب <br />کبداً حرّاً و قلباً یجب <br />و جزا من سهرت اجفانه <br />حجة تمضی و اخری تعقب <br />زفرات ٌ فی الحشا محرقة<br />و جفون دمعها ینسکب <br />قاتل اﷲ عذولی ما دَری <br />ان فی الاعین اسداً تثب <br />لااری لی عن حبیبی سلوة<br />فدعونی و غرامی و اذهبوا.<br />و نیز گوید:<br />ان کنت عنی فی العیان مغیباً<br />فما انت عن سمعی و قلبی بغائب <br />اذا اشتاقت العینان منک لنظرة<br />تمثلت لی فی القلب من کل ّ جانب .<br />وفات او بسال <span class=\"hlight\" dir=\"rtl\">٥٢٤</span> هَ . ق . بوده است . (معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٥</span>). صاحب فوات الوفیات گوید: وی در هنگام مرگ در مصر متولی بود، و در نظم و نثر آیتی بود ووقتی قطعه ای را که بدین بیت آغاز میشود: یا نسیماً هب ّ مسکاً عبقاً الخ، سرود قطعه شهرتی یافت و دستاویز خنیاگران گردید و در مجالس بدان اشعار تغنی میکردند. یکی از افاضل گوید: روزی در یکی از کویهای قاهره میگذشتم، دیدم شتر بسیاری که بار آنها سیب فتحی محصول شام است در آن کوی نمودار شد و بوی خوش آن سیبها فضای آن محل را معطر ساخت، من دیرگاهی متحیرانه متوجه ٔ شتران شدم، در آن حال زنی از برابرم گذر میکرد و ملتفت شد که بوی سیبها مرا به دهشت انداخته و بحال حیرت به اَحمال شتران مینگرم، آن زن اشارتی بسوی من کرد و این مصراع از قطعه ٔ طراد معروف به بدیع را سخت بهنگام فروخواند مصراع :<br />هذه انفاس ریاجلقا.<br />این قطعه را درباره ٔ ابونصربن قاضی الصعید گوید:<br />حاکمکم بهیمة<br /><font color=\"Red\">لیس یساوی العلفا</font><br />و لیس فیه مضغة<br /> <font color=\"Red\">طیبه الا القفا</font><br />قاضی در ازاء بدگوئی وی را بزندان فرستاد طراد نوبت دیگر این قطعه در هجا قاضی سرود:<br />اصبحت بین مصائب <br /> <font color=\"Red\">من کید ذات حرسمین </font><br />انا یوسف امرت بسجَ<br /> <font color=\"Red\">َنی زوجةالقاضی المکین .</font><br /><font color=\"Red\">(فوات الوفیات ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٦</span>).</font><br /></font></div>'),
(176278, 'طراد', '<span class=\"hlight\">طراد.</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (اِخ ) ابن دُبیس الاسدی . از فرمانروایانی بود که فرمانروائی جزیره ٔ دبیسیه ٔ (نزدیک خوزستان ) را از پدران خویش بطریق ارث داشته، منصوربن حسین الاسدی را با وی محاربه ای پیش آمد و از این رو در امرفرمانروائی او سستی رخ داد و از جزیره ٔ مزبوره بیرون شد، و مدتی نگذشت که پس از آن محاربه بسال <span class=\"hlight\" dir=\"rtl\">٤١٨</span> هَ . ق . جهان را بدرود کرد. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٦</span>).<br /></font></div>'),
(176279, 'طراد', '<span class=\"hlight\">طراد.</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (اِخ ) ابن محمدبن علی الهاشمی الزینبی البغدادی العباسی الهاشمی . وفات وی بسال <span class=\"hlight\" dir=\"rtl\">٤٩١</span> هَ . ق . بوده . او راست : کتابی به نام عوالی که معروف است به عوالی ابوالفوارس . (کشف الظنون ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(176280, 'طراد', '<span class=\"hlight\">طراد.</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (اِخ ) اسعدبن ابراهیم . وی بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٥</span> م . در بیروت قدم به عرصه ٔ وجودنهاد و در مدرسه ٔ امریکائیان به آموختن علوم پرداخت و با شیخ ناصیف یازجی رفت و آمد بسیار داشت . او را چندین قصیده است که در روانی و استواری آن قصائد را به پیروی و سبک شیخ مزبور ساخته و پرداخته است . در سال <span class=\"hlight\" dir=\"rtl\">١٨٧٢</span> م . به کشور مصر آمد و در اسکندریه و زفتی و منصوره بشغل بازرگانی مشغول شد و هم در این شغل بود تا در سال <span class=\"hlight\" dir=\"rtl\">١٨٩١</span> م . وفات یافت . وی را اشعار بسیاری است که معظم آن را یکی از خویشان او بعد از مرگش در دیوانی گرد آورد. مقالات ادبیه ٔ وی در مجله ٔ الجنان که مدیر آن معلم پطرس بستانی بود نشر شده است . دیوان وی که در زندگانی خویش به معیت برادرزاده اش فضل اﷲ طرادگردآوری شده و قریب به پانصد بیت میباشد، بوسیله ٔ نجیب ابراهیم طراد در بیروت طبع و نشر شده است . و نیزاندکی دیگر از اشعار وی در سال <span class=\"hlight\" dir=\"rtl\">١٨٩٩</span> م . به اسکندریه بطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣٦</span>).<br /></font></div>'),
(176281, 'طراد', '<span class=\"hlight\">طراد.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) نیزه ای کوتاه که بدان شکار کنند. (منتهی الارب ). نیزه ای خُرد. یا عام است . (منتهی الارب ) (آنندراج ): بر اثر ایشان صدوسی غلام ... بگذشتند، با سه سرهنگ سرای و سه علامت شیر، و طِرادها برسم غلامان سرای بر اثر ایشان . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٧٢</span>). فرمود تا طرادها غلامان سرای از دور بزدند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٤٤</span>).<br /></font></div>'),
(176282, 'طراد', '<span class=\"hlight\">طراد.</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (ع ص، اِ) کشتی خرد شتابرو. (منتهی الارب ) (آنندراج ). سخت راننده . <BR><font color=\"Blue\">◄</font> قایق (بیضی شکل بخلاف قُفَّه که مدور است ). <BR><font color=\"Blue\">◄</font> جای فراخ . سطح هموار وسیع. <BR><font color=\"Blue\">◄</font> آنکه قرائت را بر مردمان دراز کند که گویا طول قرائت مردمان را میراند. (منتهی الارب ) (آنندراج ). من یطول علی الناس القراءة حتی یطردهم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> روز دراز. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176283, 'طراد', '<span class=\"hlight\">طراد.</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (اِخ ) نجیب بن ابراهیم بن متری طراد. خانواده ٔ طراد بتوانگری در مال و رجال از عهدی قدیم در بیروت شهرتی بسزا داشتند نجیب ابراهیم بسال <span class=\"hlight\" dir=\"rtl\">١٨٩٥</span> م . در بیروت ولادت یافت و مبادی لغت عرب را در مدرسه ٔ القدیس جاورجیوس که مؤسسه ٔ روم ارتودکس میباشد فراگرفت و سپس داخل مدرسه ٔ امریکائیان شد، پس از چندی ترک تحصیل کرده به امر بازرگانی اشتغال ورزید و چون در این شغل پیروزی نیافت، کرت دیگر فراگرفتن دانش را وجهه ٔ همت خویش ساخت و در این بار شب و روز همگی اوقات خود را مصروف درس و مطالعه داشت، در این اثنا وی را برای آموزگاری به شهر حمص دعوت کردند و در یکی از مدارس آن شهر به آموزگاری اشتغال ورزید، سپس زعیم فرقه ٔ بابیه عباس بن بهأاﷲ وی را برای تعلیم اولاد خویش بخواند، چندی پس از آن به اسکندریه مسافرت کرد و در اداره ٔ جریده ٔ (الاهرام ) مقالات می نوشت و از آن پس در اداره ٔ راه آهن مصر سمت نویسندگی یافت و بعداً در وزارت جنگ داخل شد، در شورش عرابی پاشا نیز حاضر بود و بعد از پایان شورش هم هنگام محاکمه ٔ عرابی پاشا به مترجمی وی تعیین گردید، آنگاه بسال <span class=\"hlight\" dir=\"rtl\">١٨٩٨</span> م . جریده ای به نام (الرقیب ) ایجاد کرد و پس از مدتی از جریده نگاری کناره جست و به بیروت بازگشت و در آنجا اقامت گزید، تا بسال <span class=\"hlight\" dir=\"rtl\">١٩١١</span> م . جهان را بدرود گفت . او راست : تاریخ الدولة المکدونیة و الممالک التی انفصلت عنها و تاریخ الرومانیین که هر دو در مطبعه ٔ لبنانیه ٔ بیروت بسال <span class=\"hlight\" dir=\"rtl\">١٨٨٦</span> م . به طبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣٧</span>).<br /></font></div>'),
(176284, 'طراده چی', '<span class=\"hlight\">طراده چی .</span> <font color=\"DarkGreen\"><b>[ طَرْ را دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) (از: طراده + چی، مزید مؤخر ترکی ) آنکه طراده راند. راننده ٔ کرجی . قایق ران .<br /></font></div>'),
(176285, 'طراده کش', '<span class=\"hlight\">طراده کش .</span> <font color=\"DarkGreen\"><b>[ طَرْرا دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) علمدار. بیرقدار.<br /></font></div>'),
(176286, 'طرار', '<span class=\"hlight\">طرار.</span> <font color=\"DarkGreen\"><b>[طَرْ را ]</font></b> (ع ص ) کیسه بر. (منتهی الارب ) (مجمل اللغة).بمعنی عیار است که کیسه بر باشد. (برهان ). گره بر. (غیاث اللغات ) (آنندراج ). دزد. (غیاث اللغات ). دزد که آستین تا گریوان بشکافد. (مهذب الاسماء) <span class=\"hlight\">:</span> <br />آنکه طرار است زر و سیم برد و این جهان <br />عمر برد و پس چنین جای دگر طرار نیست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دزدی طرار ببردت ز راه <br />پره بر آن خائن طرار کن .<br /> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">٣٧٥</span>).</font><br />گرچه طراری و عیار جهان از تو<br />عالم الغیب کجا خواهد طراری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />در کارهای دینی و دنیائی <br />جز همچنان مباش که بنمائی <br />زنهار تا بسیرت طراران <br />ارزن نموده ریگ نپیمائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کز دو بال سریش کرده نشد<br />هیچ طرار جعفرطیار.<br /> <font color=\"Red\">سنائی (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٢١</span>).</font><br />شاه از بهر دفع ستمکاران است وشحنه برای خونخواران و قاضی مصلحت جوی طراران . (گلستان ).<br />شاه وسرهنگ ره بدان نبرد<br />دزد و طرارش از میان نبرد.<br /> <font color=\"Red\">اوحدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">شبرو طرارخیزد چون بیارامد عسس </span> .<br /> <font color=\"Red\">ظهیر فاریابی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طره ٔ طرار</span> ؛ موی پیشانی که دل رباید <span class=\"hlight\">:</span> <br />تا غمزه ٔ خونخوار تو با ما چه کند<br />تا طره ٔ طرار تو با ما چه کند.<br /> <font color=\"Red\">؟(از نسخه ٔ خطی از لغت نامه ٔ اسدی ).</font><br /><BR><font color=\"Blue\">◄</font> گربز. (صحاح الفرس ). <BR><font color=\"Blue\">◄</font> تیززبان . (غیاث اللغات ).<br /></font></div>'),
(176287, 'طرار', '<span class=\"hlight\">طرار.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ج ِ طرة.<br /></font></div>'),
(176288, 'طرار', '<span class=\"hlight\">طرار.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) شهرکی است <font color=\"DarkGreen\"><b>[ بماوراءالنهر ]</font></b> که اندر وی مسلمانان و ترکانند و جای بازرگانان است . (حدود العالم ). مخفف اطرار و رجوع به طراربند و اطرار شود <span class=\"hlight\">:</span> <br />ای بی بصر حکایت بختنصر مگوی <br />وز سامری هزار سمر یادگار گیر<br />بغداد را به طرفه ٔ بغداد باز ده <br />واندر کمین بصره نشین و طرار گیر.<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(176289, 'طرار', '<span class=\"hlight\">طرار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی است از دهستان وزرق بخش داران شهرستان فریدن، واقع در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی جنوب داران متصل به راه داران به سمندگان . دامنه ٔ کوه، سردسیر با <span class=\"hlight\" dir=\"rtl\">٣٢٩</span> تن سکنه . آب آن از قنات و چشمه . محصول آنجا غلات، حبوبات . شغل اهالی زراعت . راه آن مالرو است و دبستان دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(176290, 'طراران بالا', '<span class=\"hlight\">طراران بالا.</span> <font color=\"DarkGreen\"><b>[ طَرْ را ن ِ ]</font></b> (اِخ ) دهی است جزء دهستان تفرش بخش طرخوران شهرستان اراک، واقع در <span class=\"hlight\" dir=\"rtl\">٣</span>هزارگزی شمال باختری طرخوران، کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> تن سکنه . آب آن از قنات . محصول آنجا غلات، بنشن، گردو و بادام . شغل اهالی زراعت و صنایع دستی آنان قالی بافی است . راه مالرو دارد. مزرعه ٔ قوامیه جزء این ده منظور شده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(176291, 'طراربند', '<span class=\"hlight\">طراربند.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b>(اِخ ) شهری است از پس سیحون در پایان بلادشاش از جهتی پیوسته ٔ به ترکستان و آنجا سرحد و آخر بلاد اسلام درماوراءالنهر محسوب میشده، اهل این شهر جزء آخر این کلمه را بیفکنند و طرار و گاهی هم اطرار گویند. این شهر از اقلیم پنجم و طول آن <span class=\"hlight\" dir=\"rtl\">٩٧</span> و نیم درجه و عرض آن <span class=\"hlight\" dir=\"rtl\">٣٩</span> درجه و <span class=\"hlight\" dir=\"rtl\">٣٥</span> دقیقه است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧</span>).<br /></font></div>'),
(176292, 'طرارغرن', '<span class=\"hlight\">طرارغرن .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی فوتینج بری است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176293, 'طراری', '<span class=\"hlight\">طراری .</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (حامص ) عیّاری . کیسه بری . <BR><font color=\"Blue\">◄</font> گربزی .<br /></font></div>'),
(176294, 'طراریدن', '<span class=\"hlight\">طراریدن .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b> (مص ) تفحص کردن . تفتیش کردن . (آنندراج ).<br /></font></div>'),
(176295, 'طراز', '<span class=\"hlight\">طراز.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِ) کارگاه بت . (فقط در یک نسخه ٔ خطی از فرهنگ اوبهی ).<br /></font></div>'),
(176296, 'طراز', '<span class=\"hlight\">طراز.</span> <font color=\"DarkGreen\"><b>[ طُرْ را ]</font></b> (اِخ ) تارجه . شهری است از شهرهای اسپانیا .<br /></font></div>'),
(176297, 'طراز', '<span class=\"hlight\">طراز.</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (ع ص ) نگارگر جامه . زینت کننده . این صنعت در میان بنی اسرائیل در وقتی که از مصر بیرون آمد معروف بود. (خرو <span class=\"hlight\" dir=\"rtl\">٢٨</span>، <span class=\"hlight\" dir=\"rtl\">٣٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٥</span>، <span class=\"hlight\" dir=\"rtl\">٣٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٣</span>) (قاموس کتاب مقدس ).<br /></font></div>'),
(176298, 'طراز', '<span class=\"hlight\">طراز.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (معرب، اِ) نگار جامه . (منتهی الارب ). معرب است .(منتهی الارب ) (صحاح ). اصل این کلمه تراز فارسی و معرب است، سیوطی در کتاب «المزهر» گوید: فممّا اخذوه (ای العرب ) من الفارسیة، الطراز. زوزنی در کتاب المصادر خویش گوید: التطریز بر جامه طراز کردن . طراز جامه .(قوافی امیر علیشیر). علم ثوب . (زمخشری ) (صحاح ). علم جامه . (اوبهی ). نقش و نگار جامه . نگار علم . (مهذب الاسماء). نقش . علم . (مجمل ). علم جامه و مطلق آرایش و زینت مجاز است . و با لفظ آوردن و دادن و کشیدن و نهادن و بستن و انگیختن مستعمل . (آنندراج ) <span class=\"hlight\">:</span> <br />نگه کرد زال آنگهی از فراز<br />ز سیمرغ دیدش هوا پرطراز.<br /> <font color=\"Red\">فردوسی .</font><br />باد علمدار گشت، ابر عَلم شد سیاه <br />برق چنانچون ز زر یک دو طراز علم .<br /> <font color=\"Red\">منوچهری .</font><br />و بر سکه ٔ درم و دینار و طراز جامه نخست نام ما نویسند، آنگاه نام برادر. (تاریخ بیهقی ). قبای سقلاطون بغدادی بود سپیدی سپید، سخت خرد نقش پیداو عمامه ٔ قصب بزرگ، اما بغایت باریک و مرتفع و طرازی سخت باریک . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٥٠</span>). و نام رضاعلیه السلام بر درم و دینار و طراز جامها نبشتند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span>).<br />بسخنهای من پدید آید<br />بر تن و آستین حق طراز.<br /> <font color=\"Red\">ناصرخسرو.</font><br />یکی خوب دیبا شمر دین حق را<br />که علمست و پرهیز نقش طرازش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ماه ترکستان طراز مشک بر دیبا کشید.<br /> <font color=\"Red\">عثمان مختاری .</font><br />صنما آن خط مشکین که فرازآوردی <br />بر گل از غالیه گوئی که طراز آوردی .<br /> <font color=\"Red\">امیرمعزی .</font><br />و سیرت پادشاهان این دولت، طراز محاسن عالم و جمال مفاخر بنی آدم شده . (کلیله و دمنه ).<br />به سکه و به طراز ثنای او که بر آن <br />خدیو اعظم خاقان اکبر است القاب .<br /> <font color=\"Red\">خاقانی .</font><br />شاه عراقین طراز کز پی توقیعاو<br />کاغذ شامیست صبح خامه ٔ مصری شهاب .<br /> <font color=\"Red\">خاقانی .</font><br />بر تن ناقصان قبای کمان <br />بطراز هنر ندوخته اند.<br /> <font color=\"Red\">خاقانی .</font><br />القاب میمون او طراز خطبه و سکه ٔ آن نواحی شد. (ترجمه ٔ تاریخ یمینی خطی ابوالحرث احمدبن محمد). غره ٔ دولت و جمال جمله و طراز حله ٔ ایشان بود. (ترجمه ٔ تاریخ یمینی خطی ).<br />طراز نو انگیزم اندر جهان <br />که خواهد ز هرکشوری نو رهان .<br /> <font color=\"Red\">نظامی .</font><br />فلک نیست یکسان همآغوش تو<br />طرازش دو رنگست بر دوش تو.<br /><font color=\"Red\">نظامی .</font><br />آن کس که لباس وجود او به طراز سعادت مطرز است . (جهانگشای جوینی ).<br />پیش در شد آن دقوقی در نماز<br />قوم همچون اطلس آمد او طراز.<br /> <font color=\"Red\">مولوی .</font><br />هرکه طراز تو به بازو نهاد<br />نقد دو عالم به ترازو نهاد.<br /> <font color=\"Red\">امیرخسرو.</font><br />طراز پیرهن زرکشم مبین چون شمع<br />که سوزهاست نهانی درون پیرهنم .<br /> <font color=\"Red\">حافظ.</font><br />یکی گفتا همانا سحرسازی <br />ز سحرش بسته بر دامن طرازی .<br /> <font color=\"Red\">جامی .</font><br />بر قبای دولتت بادا طراز سرمدی <br />دامن جاه و جلالت ایمن از گردِ فتن .<br /> <font color=\"Red\">نظام قاری .</font><br />طراز آستی شرع رکن دین مسعود<br />که هست دامن جاهش بری ز گرد فتور.<br /> <font color=\"Red\">نظام قاری .</font><br />حدیث ای جامه پرداز از طراز و شرب زرکش گو<br />که نقشی در خیال ما ازین خوشتر نمی گیرد.<br /> <font color=\"Red\">نظام قاری </font><br />زهی به صفحه ٔ علم ازل ز روی شرف <br />طراز داده به نامت خدای عنوان را.<br /> <font color=\"Red\">درویش واله هروی .</font><br />و گویا طراز و نقش جامه را به قرمز میکرده اند <span class=\"hlight\">:</span> <br />هوا روی زمین را شد مطرز<br />بصافی آب دریا نی بقرمز.<br /> <font color=\"Red\">بدائعی بلخی .</font><br /> <BR><font color=\"Blue\">◄</font> یراق . حاشیه . فراویز. سجاف . لبه . کناره ٔ جامه که به رنگ خارج از رنگ متن میکرده اند <span class=\"hlight\">:</span> <br />فلک مر جامه ای را ماند ازرق <br />مر او را چون طراز خوب کرکم .<br /> <font color=\"Red\">بهرامی (از لغت نامه اسدی ص <span class=\"hlight\" dir=\"rtl\">٣٥٠</span>).</font><br />فروهشته بر سر و سیمین طراز<br />برنگ شب تیره زلف دراز.<br /> <font color=\"Red\">فردوسی .</font><br />چهل تخت دیبای پیکر بزر<br />طرازش همه گونه گونه گهر.<br /> <font color=\"Red\">فردوسی .</font><br />طرازنامه ٔ شاهان همی بینم به نام تو.<br /> <font color=\"Red\">فرخی .</font><br />ای نکو رسم تو بر جامه ٔ فرهنگ طراز<br />وی نکو نام تو بر نامه ٔ شاهی عنوان .<br /> <font color=\"Red\">فرخی .</font><br />وز پی آنکه بدانند مر او را بنشان <br />سرنگون گردد بر جامه ٔ او نقش طراز.<br /> <font color=\"Red\">فرخی .</font><br />ای سخنهای تو اندر کتب علم نکت <br />وی هنرهای تو بر جامه ٔ فرهنگ طراز.<br /> <font color=\"Red\">فرخی .</font><br />غزلی خوان چو حله ای که بود<br />نام صاحب بر او بجای طراز.<br /> <font color=\"Red\">فرخی .</font><br />بناگوشش چو دیبای بر گل <br />طرازی کرده بر دیبا ز سنبل .<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br />که دار ملک ترا جز به نام ما ناید<br />طراز کسوه ٔ آفاق و سکه ٔ دینار.<br /> <font color=\"Red\">ابوحنیفه ٔ اسکافی .</font><br />ز زر پیرهن سی وشش بافته <br />بهم پود با تار برتافته .<br />طراز همه درّ بر زرّ ناب <br />گریبان زیاقوت و در خوشاب .<br /> <font color=\"Red\">اسدی (گرشاسبنامه ).</font><br />چو بر تیره شعر شب دیریاز<br />سپیده کشید از سپیدی طراز.<br /> <font color=\"Red\">اسدی (گرشاسبنامه ).</font><br />زلفین سیاه آن بت زیبا<br />گشته ست طراز روی چون دیبا.<br /> <font color=\"Red\">مسعودسعد.</font><br />نام تو بر نگین دولت نقش <br />جاه تو بر لباس ملک طراز.<br /> <font color=\"Red\">مسعودسعد.</font><br />ای دل چو طراز هوا نگاری <br />بر جامه ٔ مهر بت طرازی .<br /> <font color=\"Red\">مسعودسعد.</font><br />زین خرابات برفشان دامن <br />تا شوی بر لباس فخر طراز.<br /> <font color=\"Red\">سنائی .</font><br />کسوت عُمر ترا تا دوره ٔ آخرزمان <br />از بزرگی نام توبر آستین بادا طراز.<br /> <font color=\"Red\">سوزنی .</font><br />کسوت دولت ترا در ملک <br />باد باقی طراز طره ٔ ملک .<br /> <font color=\"Red\">سوزنی .</font><br />تا ابد نامه ٔ عمر تو مقید به دوام <br />در ازل جامه ٔ جاه تو مزین به طراز.<br /> <font color=\"Red\">انوری .</font><br />تا کی جوئی طراز آستی من <br />نیست مرا آستین چه جای طراز است .<br /> <font color=\"Red\">خاقانی .</font><br />طاق ایوان جهانگیر و وثاق پیرزن <br />از نکونامی طراز فرش ایوان دیده اند.<br /> <font color=\"Red\">خاقانی .</font><br />ز گفته ٔ قدما شعری از رهی بشنو<br />که هست تضمین بر آستین شعر طراز.<br /> <font color=\"Red\">کمال اسماعیل .</font><br /><BR><font color=\"Blue\">◄</font> کتابت و خطی که نساجان بر طرف جامه نگارند <span class=\"hlight\">:</span> عبدالجلیل را ریاست نیشابور داد هم بر آن خط و طراز که حسنک را داد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٦٢٣</span>). آستین جامه ٔ شقاوتش این طراز دارد که و ان ّ علیک لعنتی الی یوم الدین . (هزلیات منسوب به سعدی ). <BR><font color=\"Blue\">◄</font> جای بافتن جامه های نیکو و جید. (منتهی الارب ) (آنندراج ). هر کجا که در آن جامه های قیمتی و فاخر بافند عموماً. (برهان ). هر جا که در آن جامه های خوب بافند. (ازهری ). آنجا که جامه های فاخر و گرانمایه بافند. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> کارگاه دیبابافی را گویند خصوصاً. (برهان ). کارگاه دیباباف . (اوبهی ). کارگاه دیبا. (تفلیسی ). کارخانه و کارگاه جامه های نیکو <span class=\"hlight\">:</span> <br />همه شهر از آذین دیبا و ساز<br />بیاراست چون کارگاه طراز.<br /> <font color=\"Red\">اسدی (گرشاسبنامه ).</font><br />امّا چون سوگند در میان است، از جامه خانه ٔ خاص، برای تشریف و مباهات یک تخت جامه از طراز خوزستان ... برگیرم . (کلیله و دمنه ).<br />در طراز ازلی عرض تو را<br />کسوت عمر ابد بافته شد.<br /> <font color=\"Red\">سوزنی .</font><br />حبش را زلف بر طمغاج بندد<br />طراز شوشتر بر عاج بندد.<br /> <font color=\"Red\">نظامی .</font><br />گشاد از گنج در هرکنج رازی <br />ز دیبا گشت هر کوئی طرازی .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> جامه ای است که برای سلطان بافند. <BR><font color=\"Blue\">◄</font> گستردنی . <BR><font color=\"Blue\">◄</font> لیس هذا من طِرازک ؛ یعنی از دل و طبیعت تو نیست . (منتهی الارب ) (آنندراج ). در پارسی نیز گویند: این گفته از طراز فلان نیست ؛ یعنی از مال او نیست . طرز گفتار او نیست . از قریحه ٔ او نیست . <BR><font color=\"Blue\">◄</font> طرز. روش . قاعده . قانون . نمط. (برهان ). طریقه . گونه . باب (همه در معنیهای مجازی ) <span class=\"hlight\">:</span> <br />توانگر بود بر مدیح تو مادح <br />ز علم و نکت وز طراز معانی .<br /> <font color=\"Red\">فرخی .</font><br />قیمت یکتا طرازش از طراز افزون بود<br />در جهان هرگز شنیدستی طرازی زین طراز.<br /> <font color=\"Red\">منوچهری .</font><br />کسوت عدل ملک باکسوت عدل عمر<br />در طراز دادورزی بر یکی منوال باد.<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> طبقه . نوع . قسم : از طراز اول ؛ از طبقه ٔ اول، از درجه ٔ اول، از مرتبه ٔ اول، از نمط اول، از باب اول : شم ّالانوف من الطراز الاول و الطرز و الطراز، فارسی، معرب ٌ و قد تکلمت به العرب . قال حسان : شم الانوف من الطراز الاول . (المعرب ص <span class=\"hlight\" dir=\"rtl\">٢٢٣</span>) <span class=\"hlight\">:</span> پیری آخرسالار را با مقدمی چند بفرستادند بدم هزیمتیان، ایشان برفتند کوفته، با سوارانی هم از این طراز. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٥٨٨</span>). بوبکر حصیری و منگیتراک بر این جمله برفتند، و سه خیلتاش مُسرع را نیز هم از این طراز بغزنین فرستادند. (تاریخ بیهقی چ غنی و فیاض ص <span class=\"hlight\" dir=\"rtl\">٤</span>). <BR><font color=\"Blue\">◄</font> تار ریسمان . (فرهنگ خطی ). رشته . ریسمان خام <span class=\"hlight\">:</span> <br />سوی خانه برد آن طرازی که رشت <br />دل مام او شد چو خرم بهشت .<br /> <font color=\"Red\">فردوسی .</font><br />چنان شد که گوئی طراز نخ است <br />و یا پیش آتش نهاده یخ است .<br /> <font color=\"Red\">فردوسی .</font><br />گدازیده همچون طراز نخم <br />تو گوئی که در پیش آتش یخم .<br /> <font color=\"Red\">فردوسی .</font><br />من از اختر گرم چندان طراز<br />بریسم که نیزم نباشد نیاز.<br /> <font color=\"Red\">فردوسی .</font><br />شبانگه شدندی سوی خانه باز<br />شده پنبه شان ریسمان طراز.<br /> <font color=\"Red\">فردوسی .</font><br />گر بگردانی بگردد ور برانگیزی رود<br />بر طراز عنکبوت و حلقه ٔ ناخن پرای .<br /> <font color=\"Red\">منوچهری .</font><br />بر طراز آخته پویه کند چون عنکبوت <br />بر بَدَستی جای بر، جولان کند چون بابزن .<br /> <font color=\"Red\">منوچهری .</font><br />بجهد گر بجهانی ز سر کوه به کوه <br />بدود گر بدوانی ز بر تار طراز.<br /> <font color=\"Red\">منوچهری .</font><br />برکشد تار طراز عنبرین از کام خویش <br />چون برآرد عنکبوت از کام خود تار طراز.<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> مجازاً مُوی <span class=\"hlight\">:</span> <br />قیمت یکتا طرازش از طراز افزون بود<br />در جهان هرگز شنیدستی طرازی زین طراز.<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> کارگاه شکر بود در ولایت خوزستان و گرمسیر. (صحاح الفرس ). کارگاه شکر<span class=\"hlight\">:</span> <br />شکرلبی و دهان شکر چو طراز<br />کار دل عاشقان بیچاره بساز.<br /> <font color=\"Red\">اسدی (از فرهنگ خطی متعلق به نخجوانی ).</font><br /> <BR><font color=\"Blue\">◄</font> نیشکر. <BR><font color=\"Blue\">◄</font> آراستن و پیراستن و ساختن چیزها بود به اصطلاح بعضی از اهل خراسان . (برهان ). <BR><font color=\"Blue\">◄</font> زیب و زینت . (برهان ) (آنندراج ). و در فرهنگی خطی برای معنی اخیر بیت ذیل را از خلاق المعانی کمال اسماعیل شاهد آورده است <span class=\"hlight\">:</span> <br />ره سلامت اگر میروی مجرد شو<br />که جز غنا نفزاید ترا لباس و طراز.<br /> <font color=\"Red\">(برهان ).</font><br /> <BR><font color=\"Blue\">◄</font> آلتی مرکب از لوله ای از شیشه که اندرون آن مقداری آب دارد، و از سه سوی میان تخته ای مسطح یا روی آن جای گرفته و آنرا برای دانستن همواری و ناهمواری سطح بکار برند. آلتی که بنایان و نجاران همواری و ناهمواری و برابری و نابرابری را بدان آزمایند . تراز. ترازو. <BR><font color=\"Blue\">◄</font> مقسم آب را نیز گفته اند، یعنی جائی که آب رودخانه و چشمه از آنجا بر چند قسمت می شود و هر قسمتی بطرفی میرود. (برهان ). بخشش گاه آب باشد در بعضی ولایات خراسان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به طراز دادن گوسفند و بز و جز آن </span> ؛ دادن آن به دهقان تا پشم و روغن و بره ٔ آن هر ساله بدهد و اگر حیوان بمیرد بجای آن دیگری بخرد.<br /> <BR><font color=\"Blue\">◄</font> هم کفو. هم طراز. هم ترازو <span class=\"hlight\">:</span> <br />بدو گفت ای بهار مهربانان <br />بچهره آفتاب دلستانان <br />طراز نیکوان سالار شاهان <br />بهشت دلبران اورنگ ماهان .<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br />پرستار صف زد دوصف ماهروی <br />طراز بتان طرازنده موی .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> خوب از چیزی . <BR><font color=\"Blue\">◄</font> بنگاشته . (تفلیسی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چینی طراز</span> ؛ طراز چینی <span class=\"hlight\">:</span> <br />همی چاره جست آن بت دیریاز<br />چو خورشید بنمود چینی طراز.<br /> <font color=\"Red\">فردوسی .</font><br />یعنی چون آفتاب اشعه ٔ زرین خود بر جهان افکند.<br />رجوع به لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٥</span> و <span class=\"hlight\" dir=\"rtl\">٢٦٥</span> و فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرازچرخ </span> ؛ در بیت ذیل کنایه از آفتاب است، چه هنگام ایستادن برابر قبله، آفتاب از جانب چپ برآید <span class=\"hlight\">:</span> <br />چون به دست چپ طراز چرخ دید<br />نقش والفجرش نشان برکرد صبح .<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طراز چین یا طراز چینی </span> ؛ رنگ آمیزی و نقش و نگار نگارگران چین است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طراز خراسان </span> ؛ پارچه ٔ بافت خراسان <span class=\"hlight\">:</span> از جامه های قصاره زده و طراز خراسان، خروش برخاسته بود. (نظام قاری ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طراز شوشتر</span> ؛ دیبای بافته ٔ در کارگاه دیبابافی شوشتر <span class=\"hlight\">:</span> <br />هست بر هر بام گوئی صد بهار قندهار<br />هست در هر کوی گوئی صد طراز شوشتر.<br /><font color=\"Red\">قطران .</font><br /></font></div>'),
(176299, 'طراز', '<span class=\"hlight\">طراز.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (نف مرخم ) طرازنده . نظم و ترتیب و آرایش دهنده <span class=\"hlight\">:</span> <br />هیچ شه را چنین وزیر نبود<br />مملکتدار و کار ملک طراز.<br /> <font color=\"Red\">فرخی .</font><br />بیشتر درترکیب های به کار رود: عنوان طراز، خنده ٔ طراز، و غیره .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دین طراز</span> ؛ طرازنده ٔ دین <span class=\"hlight\">:</span> <br />قطعه ای کز ثنا فرستادم <br />بجهانجوی دین طراز فرست .<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مدح طراز</span> ؛ مدیح طراز <span class=\"hlight\">:</span> <br />تو به صدر اندر بنشسته به آئین ملوک <br />همچنین مدح نیوشنده و من مدح طراز.<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مدیح طراز</span> ؛ طرازنده ٔ مدیح <span class=\"hlight\">:</span><br />فلک ز شرم پر تیر برنهد هرگه <br />که نوک خامه ٔ بنده شود مدیح طراز.<br /> <font color=\"Red\">کمال اسماعیل .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ملک طراز</span> ؛ طرازنده ٔ پادشاهی .<br /></font></div>'),
(176300, 'طراز', '<span class=\"hlight\">طراز.</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (اِخ ) مُعرّب تِراز که نام شهری است در ترکستان . (آنندراج ). شهریست نزدیک به اسپیجاب . (منتهی الارب ). درپایان اقلیم پنجم واقع شده، طول آن یکصد درجه و نیم و عرض چهل درجه و بیست وپنج دقیقه است . ابوالفتح این کلمه را به فتح اول دانسته، و سایر علمای فن آنرا به کسر طا نام برده اند. شهریست نزدیک به اسپیجاب از سرحدهای ترکستان و بطراز بند نیز نزدیک است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧</span>). در مغرب فرغانه مسلمانان را در برابر ترکستان خرلخیه سرحدی است که طراز نام دارد و بر کنار رود سیحون واقع شده است . (نخبةالدهر دمشقی ). شهری است سخت سرد و خوبان آنجا به نیکوئی در زبان شعرامثلند. نام شهریست از ترکستان شرقی (کاشغرستان ) و شعرا خوبان را بدان شهر نسبت کنند و از آنجا مشک خیزد. شهر نیکوان است از چین . (صحاح الفرس ) <span class=\"hlight\">:</span> <br />از سرشنی و طراز است مادر و پدرت <br />مگر نبیره ٔ خان و نواسه ٔ نرمی .<br /> <font color=\"Red\">حقوری .</font><br />وز آن بهره نیمی شب دیریاز<br />نشستی همی با بتان طراز.<br /> <font color=\"Red\">فردوسی .</font><br />گسارنده ٔ باده و رود ساز<br />سیه چشم گلرخ بتان طراز.<br /> <font color=\"Red\">فردوسی .</font><br />شدند اندر ایوان بتان طراز<br />نشستند و گفتند با ماه راز.<br /> <font color=\"Red\">فردوسی .</font><br />سپه را به مرگ اندر آمد نیاز<br />ز خلخ پر از درد شد تا طراز.<br /> <font color=\"Red\">فردوسی .</font><br />همه شب ببودند با کام و ناز<br />به پیش اندرونشان بتان طراز.<br /> <font color=\"Red\">فردوسی .</font><br />بسی خوب چهره بتان طراز<br />گرانمایه اسبان و هر گونه ساز.<br /> <font color=\"Red\">فردوسی .</font><br />پریروی گلرخ بتان طراز<br />برفتند و بردند پیشش نماز.<br /> <font color=\"Red\">فردوسی .</font><br />به نخجیر یوزان و پرنده باز<br />می مشکبوی و بتان طراز.<br /> <font color=\"Red\">فردوسی .</font><br />همه نارسیده بتان طراز<br />که بسْرشتشان ایزد از شرم و ناز.<br /> <font color=\"Red\">فردوسی .</font><br />به آواز گفتند کای سرفراز<br />ستوده بچین و بروم و طراز.<br /> <font color=\"Red\">فردوسی .</font><br />بفرمایم اکنون که جویند باز<br />ز روم وز چین و ز هند و طراز.<br /> <font color=\"Red\">فردوسی .</font><br />مادرش گشته سمر همچو صبوره بجهان <br />از طراز اندر تا شام و ختن تا حد چین .<br /> <font color=\"Red\">قریع.</font><br />گمان که برد که هرگز کسی ز راه طراز<br />بسومنات برد لشکر و چنین لشکر.<br /> <font color=\"Red\">فرخی .</font><br />حجاز او گر ترا بخشد خداوند حجاز است او<br />وگر گوئی طرازم ده خداوندطراز است او.<br /> <font color=\"Red\">فرخی .</font><br />همچنین عید بشادی صد دیگر بگذار<br />با بتان چگل و غالیه زلفان طراز.<br /> <font color=\"Red\">فرخی .</font><br />شکر شاهیت از طراز گذشت <br />می خور از دست لعبتان طراز.<br /> <font color=\"Red\">فرخی .</font><br />آفرین زین هنری مرکب فرخ پی تو<br />که به یک شب ز بَلاساغون آید به طراز.<br /> <font color=\"Red\">منوچهری .</font><br />آسمان فعلی که هست از رفتن او برحذر<br />هم قَدِرخان در بَلاساغون و هم خان در طراز.<br /> <font color=\"Red\">منوچهری .</font><br />ذاکر فضل تو و مرتهن برّ تواند<br />چه طرازی بطراز و چه حجازی بحجاز.<br /> <font color=\"Red\">منوچهری .</font><br />طرازی ظن برد کو از طراز است <br />حجازی نیز گویدکز حجاز است .<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br />چهل خادم از ریدگان طراز<br />هزار اسب خنگی زرینه ساز.<br /> <font color=\"Red\">اسدی (گرشاسبنامه ).</font><br />نیم از آن کاینها بر دین محمد کردند<br />گرظفر یابد بر ما نکند ترک طراز.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و وی بهمین تاریخ، به حرب به طراز رفت، و بسیار رنج دید و آخر امیر طراز بیرون آمد و اسلام آورد و طراز گشاده شد. (تاریخ بخارا).<br />همه را رو به سوی کعبه ولیک <br />دل سوی دلبران چین و طراز.<br /> <font color=\"Red\">سنایی .</font><br />چه سرو، سرو سهی و چه ماه، ماه تمام <br />چه مشک، مشک طراز و چه ماه، ماه پری .<br /> <font color=\"Red\">سوزنی .</font><br />عدل تو گیتی چنانکه بام به بام <br />به بیت مقدس بتوان شدن ز چین و طراز.<br /> <font color=\"Red\">سوزنی .</font><br />تا زنند از حسن خوبان طراز چین مَثَل <br />از نکویان مجلس بزم تو چین باد و طراز.<br /> <font color=\"Red\">سوزنی .</font><br />دل ما تنگتر از پسته ٔ خوبان ختن <br />جان ما تیره تر از طره ٔ ترکان طراز.<br /> <font color=\"Red\">انوری .</font><br />لؤلؤ و مشک اگر به کارت نیست <br />هر دو با قلزم و طراز فرست .<br /> <font color=\"Red\">خاقانی .</font><br />و به استحضار تمامت ملوک و امرا و کتبه چنانکه فرمان بود، ایلچیان برفتند، چون بحدود طراز رسیدند. (جهانگشای جوینی ).<br />طراز و خلخ اگرچند خرم است و خوش است <br />مرا مقام درین خاک طبعساز به است <br />هر آن زمین که در آن یک نفس بیاسودی <br />بنزد عقل ز صد خلخ و طراز به است .<br /> <font color=\"Red\">؟ (از صحاح الفرس ).</font><br /> <BR><font color=\"Blue\">◄</font> نام یکی از ولایات بدخشان و آن ولایت نیز بخوبان اشتهار دارد. (برهان ). و ظاهراً با طراز مذکور خلط شده است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ترک طراز</span> ؛ کنایه از معشوق است <span class=\"hlight\">:</span><br />دل من تیره تر از گیسوی خوبان ختن <br />دل شب تنگ تر از دیده ٔ ترکان طراز.<br /> <font color=\"Red\">انوری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">شمع طراز</span> ؛ کنایه از محبوب است <span class=\"hlight\">:</span> <br />پیش شاهنشاه بردش خوش بناز<br />تا بسوزد بر سر شمع طراز.<br /> <font color=\"Red\">مولوی .</font><br />چون بمردی گشت جان کندن دراز<br />مات شو در صبح ای شمع طراز.<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کمان طراز</span> ؛ کمان منسوب به شهر طراز <span class=\"hlight\">:</span> <br />دو ابر و بسان کمان طراز<br />برو توز پوشیده از مشک ناز.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کوه طراز</span> ؛ در این بیت منوچهری آمده است و نسخه بدل ِ آن «خراز» است <span class=\"hlight\">:</span> <br />قامت کوتاه دارد رفتن شیر دژم <br />گونه ٔ بیمار دارد قوت کوه طراز.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">لعبت طراز</span> ؛ خوبروی از اهل طراز <span class=\"hlight\">:</span> <br />شکر شاهیت از طراز گذشت <br />می خور از دست لعبتان طراز.<br /> <font color=\"Red\">فرخی .</font><br />و رجوع به مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٤٢١</span> و <span class=\"hlight\" dir=\"rtl\">٤٨٠</span> و تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٧٢</span> و <span class=\"hlight\" dir=\"rtl\">٥٣٦</span> و لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span> و <span class=\"hlight\" dir=\"rtl\">٣٢١</span>و <span class=\"hlight\" dir=\"rtl\">٣٢٢</span> و <span class=\"hlight\" dir=\"rtl\">٣٤١</span> و نزهةالقلوب چ لیدن ص <span class=\"hlight\" dir=\"rtl\">٢٦١</span> و تاریخ مغول اقبال ص <span class=\"hlight\" dir=\"rtl\">٥</span> شود.<br /></font></div>'),
(176301, 'طراز کردن', '<span class=\"hlight\">طراز کردن .</span> <font color=\"DarkGreen\"><b>[ طِ ک َ دَ ]</font></b> (مص مرکب ) هموار کردن . برابر کردن . مسطح کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طراز کردن جامه </span> ؛ نقش و علم کردن . (مجمل اللغة): تطریز؛ طراز کردن جامه . (دهار).<br /></font></div>'),
(176302, 'طراز کوه', '<span class=\"hlight\">طراز کوه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی است جزء دهستان حومه ٔ بخش مرکزی شهرستان رشت، واقع در <span class=\"hlight\" dir=\"rtl\">٤٠</span>هزارگزی شمال باختری رشت و <span class=\"hlight\" dir=\"rtl\">٣</span>هزارگزی شمال شوسه ٔ رشت به فومن . جلگه، معتدل مرطوب مالاریائی با <span class=\"hlight\" dir=\"rtl\">٤٤٧</span> تن سکنه . آب آن از استخر. محصول آنجا برنج، توتون، سیگار و صیفی . شغل اهالی زراعت . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(176303, 'طراز یزدی', '<span class=\"hlight\">طراز یزدی .</span> <font color=\"DarkGreen\"><b>[ طَ زِ ی َ ]</font></b> (اِخ ) هدایت آرد: نامش میرزا عبدالوهاب . فاضل ادیب و با خطی لایق و فضلی فایق است، اما ملاقاتش میسر نشده <font color=\"DarkGreen\"><b>[ و ]</font></b> استماع افتاده که در این اوان رحلت یافته است . از اوست :<br />گفتم که مار بوده نگهبان گنج زر<br />داری نگاهبان ز چه بر گنج حسن مار<br />گفتا که فرق ننهد ترسم ز حرص جود<br />هنگام گنج بخشی گنجور شهریار.<br /> <font color=\"Red\"># # #</font><br />آنچه معلوم شد از کار خرابات این است <br />که علاج غم دیرینه می دیرین است <br />باده را عیب نگفتند بجز تلخی طعم <br />بی خبر کز کف شیرین دهنان شیرین است <br />نقطه ٔ عشق بود مرکز پرگار وجود<br />آنچه بیرون بود از دایره ٔ عقل این است .<br /> <font color=\"Red\"># # #</font><br />اینهمه لطف کلام و حسن شمائل <br />خون شود آن دل که شد بغیر تو مائل <br />گرنه بجنگست چشم مست تو با ما<br />تیغ چرا ز ابروان فکنده حمائل <br />منع کسان چون توان ز طوف در دوست <br />کس نتواند ز قبله منع قبائل .<br /> <font color=\"Red\"># # #</font><br />چه حاجت سیر بستانم قدم گر رنجه فرمائی <br />که هر دم از رخ گلگون بهاری تازه بنمائی <br />از آن زلف سیه مشکل که شامم را سحر باشد<br />مگر زآن چاک پیراهن دری از صبح بگشائی .<br /><font color=\"Red\">(مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span>).</font><br /></font></div>'),
(176304, 'طرازالاخضر', '<span class=\"hlight\">طرازالاخضر.</span> <font color=\"DarkGreen\"><b>[ طِ زُل ْ اَ ض َ ]</font></b> (اِخ )سلسلةالجبال لبنان . (دمشقی ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٨</span>، <span class=\"hlight\" dir=\"rtl\">٢١٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٠</span>).<br /></font></div>'),
(176305, 'طرازان', '<span class=\"hlight\">طرازان .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (نف، ق ) در حال طرازیدن .<br /></font></div>'),
(176306, 'طرازبند', '<span class=\"hlight\">طرازبند.</span> <font color=\"DarkGreen\"><b>[ طُ ب َ ]</font></b> (اِخ ) در مجمل التواریخ و القصص یکی از شهرهای اقلیم پنجم را بنام طرازبند آورده، ولی در حاشیه ٔ کتاب مذکور از کتاب اعلاق النفیسة ابن رسنه کلمه ٔ نامبرده را به «طراربند» تصحیح نموده است . رجوع به طراربند شود. (مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٤٨٠</span>).<br /></font></div>'),
(176307, 'طرازخاکی', '<span class=\"hlight\">طرازخاکی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش فریمان شهرستان مشهد، واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی جنوب خاوری فریمان و <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی جنوب باختری شوسه ٔعمومی فریمان به تربت جام . جلگه، معتدل با <span class=\"hlight\" dir=\"rtl\">١٥٩</span> تن سکنه . آب آن از قنات . محصول آنجا غلات، بنشن و چغندر. شغل اهالی زراعت . راه آن مالرو است و در تابستان اتومبیل از آن میرود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176308, 'طرازدان', '<span class=\"hlight\">طرازدان .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (معرب، اِ مرکب ) غلاف میزان . معرب است . (منتهی الارب ) (آنندراج ). ترازودان .<br /></font></div>'),
(176309, 'طرازناهید', '<span class=\"hlight\">طرازناهید.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) طراز نائین . دهی است جزء دهستان حومه ٔ بخش مرکزی شهرستان ساوه، واقع در <span class=\"hlight\" dir=\"rtl\">١٢٠٠٠</span>گزی خاور ساوه سر دوراهی ماشین رو ساوه، قم، تهران . جلگه، معتدل مالاریائی با <span class=\"hlight\" dir=\"rtl\">١١٨٤</span> تن سکنه . آب آن از رودخانه ٔ قره چای . محصول آنجا غلات، بنشن، پنبه، چغندرقند و یونجه . شغل اهالی زراعت و گله داری و صنایع دستی آنان جاجیم، پلاس و قالیچه بافی است . کنار راه شوسه واقع است . دبستان و پاسگاه ژاندارمری دارد. مزرعه ٔ طرازناهید کهنه و اسکندرآباد جزء این ده است . این ده قشلاق چند خانوار از ایل شاهسون بغدادی است و شغل آنها ساربانی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(176310, 'طرازنده', '<span class=\"hlight\">طرازنده .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) آرایش دهنده . پیرایش کننده . (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br />پرستار صف زد دوصد ماهروی <br />طراز بتان طرازنده موی .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> نظم دهنده . ناظم <span class=\"hlight\">:</span> <br />تا طرازنده ٔ مدیح تو دقیقی درگذشت <br />ز آفرین تو دل آگنده چنان کز دانه نار.<br /> <font color=\"Red\">فرخی .</font><br />مِه از پیل گردیست سالارشان <br />طرازنده ٔ رزم و پیکارشان .<br /> <font color=\"Red\">اسدی .</font><br />بدی صدهزاران سران سترگ <br />طرازنده گردش سپاهی بزرگ .<br /><font color=\"Red\">اسدی (گرشاسب نامه ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span>).</font><br /></font></div>'),
(176311, 'طرازندگی', '<span class=\"hlight\">طرازندگی .</span> <font color=\"DarkGreen\"><b>[ طِ<span class=\"hlight\" dir=\"rtl\">/</span> طَ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) حالت و چگونگی طرازنده .<br /></font></div>'),
(176312, 'طرازوج', '<span class=\"hlight\">طرازوج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی است جزء دهستان حومه ٔ بخش مرکزی شهرستان زنجان، واقع در <span class=\"hlight\" dir=\"rtl\">٣٣</span>هزارگزی شمال خاوری زنجان . کوهستانی، سردسیر با <span class=\"hlight\" dir=\"rtl\">٤٣٤</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و انگور. شغل اهالی زراعت و صنایع دستی آنان گلیم و جاجیم بافی است . وراه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(176313, 'طرازک', '<span class=\"hlight\">طرازک .</span> <font color=\"DarkGreen\"><b>[ طِ زَ ]</font></b> (اِخ ) شهری وسط است (از بلاد خوزستان ). در آنجا نیشکر بهتر و بیشتر از دیگر مواضع خوزستان و عظیم و فراوان باشد. (نزهةالقلوب چ لیدن ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>). و رجوع به تاریخ مغول اقبال آشتیانی ص <span class=\"hlight\" dir=\"rtl\">٤٤٩</span> و تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٥٤٩</span> شود.<br /></font></div>'),
(176314, 'طرازگر', '<span class=\"hlight\">طرازگر.</span> <font color=\"DarkGreen\"><b>[ طِ گ َ ]</font></b> (ص مرکب ) آرایش دهنده . پیرایش کننده . (آنندراج ). نگارگر جامه . و رجوع به فرهنگ شعوری ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span> شود.<br /></font></div>'),
(176315, 'طرازی', '<span class=\"hlight\">طرازی .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (ص نسبی ) منسوب به شهر طراز. (سمعانی ) (اقرب الموارد). اهل طراز یا متعلق به آنجا <span class=\"hlight\">:</span> <br />همه آزمایش همه پرنمایش <br />همه پردرایش چو گرگ طرازی .<br />ابوالطیب المصعبی (از تاریخ بیهقی چ غنی و فیاض ).<br />کمان بابلیان دیدم و طرازی تیر<br />که برکشیده شود به ابروان تو ماند.<br /> <font color=\"Red\">دقیقی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٩٩</span>).</font><br />بجای باد رفتار اسب تازی <br />گرفته کم بها اسب طرازی .<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br />پرستار پنجاه و خادم چهل <br />طرازی دوصد ریدک دل گسل .<br /> <font color=\"Red\">اسدی .</font><br />ز خلق خوش توست شرمنده دائم <br />چه مشک طرازی چه باز حجازی .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(176316, 'طرازی', '<span class=\"hlight\">طرازی .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ص نسبی ) هذه النسبة لمن یستعمل الثیاب المطرزة او یستعملها. (انساب سمعانی ). رقام . مطرز. آنکه علم جامه کند. <BR><font color=\"Blue\">◄</font> جامه ٔ طرازی ؛ جامه ای که سلطان را بافند.<br /></font></div>'),
(176317, 'طرازی', '<span class=\"hlight\">طرازی .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) (الویکنت ) فیلیب (فیلیپ ) ابن نصراﷲبن آنطون بن نصراﷲبن الیاس بن بطرس دی طرازی . بسال <span class=\"hlight\" dir=\"rtl\">١٨٦٥</span> م . در بیروت تولد یافت . وی از عائله ٔ کونت دو طرازی از خانواده های معروف و از نجبای اهالی سوریه بشمار است . (رجوع به کتاب سلاسل التاریخیة شود. شرح حال این خانواده در آن کتاب مبسوطاًذکر شده است ). یازده نشان از پادشاهان عصر خود و ازفرمانروایان و مجامع علمیه دریافت داشت و وی را در تأسیس کتابخانه ٔ عمومی در بیروت بر دیگران فضل تقدم است . کتب ذیل از تألیفات وی است : <span class=\"hlight\" dir=\"rtl\">١</span> - تاریخ الصحافة العربیة، این کتاب شامل اطلاعات راجع به تمامی مجلات و جرائد عربیی است که در جهان متمدن (شرق و غرب ) طبع و نشر گردیده، محتوی دو جلد و دارای عکس مدیران هریک از مجلات و جراید و بسال <span class=\"hlight\" dir=\"rtl\">١٩١٣</span> م . در بیروت بطبع رسیده است . <span class=\"hlight\" dir=\"rtl\">٢</span> - السلاسل التاریخیة فی اساقفةالابرشیات -السریانیة، این کتاب دارای تصاویر بسیار است و در بیروت بسال <span class=\"hlight\" dir=\"rtl\">١٩١٠</span> م . در مطبعه ٔ ادبیه چاپ شده است . <span class=\"hlight\" dir=\"rtl\">٣</span> -القلادّه النفیسة فی فقیدالعلم و الکنیسة، و آن کتابی است در ترجمه ٔ احوال و تاریخ زندگانی مطران اقلیمیس یوسف داود سریانی و آنچه در مرثیه ٔ فقید مزبور به بیست زبان سروده شده بود، در این مجموعه گرد آورده است . <span class=\"hlight\" dir=\"rtl\">٤</span>- مجموع البراآت الباباویة فی تثبیت البطارکة السریانیة، از سال <span class=\"hlight\" dir=\"rtl\">١٧٨٣</span> م . تا زمان حاضر را گرد آورده است . این مجموعه بزبان عربی و لاتینی در بیروت بطبع رسیده است . <span class=\"hlight\" dir=\"rtl\">٥</span> - نبذة مختصرة فی الصحف العربیة المصورة، این مختصر بسال <span class=\"hlight\" dir=\"rtl\">١٩١٣</span> م . در مطبعه ٔ یسوعیان بیروت چاپ شده است . صاحب ترجمه را جز کتابهای مذکور در تاریخ و ادب و شعر نیز تألیفاتی است که هنوز به طبع نرسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣٧</span> - <span class=\"hlight\" dir=\"rtl\">١٢٣٨</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(176318, 'طرازیدن', '<span class=\"hlight\">طرازیدن .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ دَ ]</font></b> (مص ) آرایش دادن . پیرایش کردن . (آنندراج ). آراستن . پیراستن . <BR><font color=\"Blue\">◄</font> راست کردن . ترتیب کردن . تنظیم کردن . ساختن <span class=\"hlight\">:</span> <br />خود برآورد و باز ویران کرد<br />خود طرازید و باز خود بفترد .<br /> <font color=\"Red\">خسروی .</font><br />خان همی گفت همه روزه که سبحان اﷲ<br />این چه مرد است که محمود فرستاد ایدر<br />آب ترکستان این مرد بیکباره ببرد<br />بطرازیدن جنگ و بفدا کردن زر.<br /> <font color=\"Red\">فرخی .</font><br />کار هر کس بطرازی و بسازی چو نگار<br />چه بکردار نکوی و چه بدان دو کف راد.<br /> <font color=\"Red\">فرخی .</font><br />شاعران را ملکان خواسته آنگاه دهند<br />که بدیشان بطرازند مدیحی چو درر.<br /> <font color=\"Red\">فرخی .</font><br />اگر این شعرکه گفتم چو گلابست بطبع<br />اندر آن باریکی شعر طرازم چو شکر.<br /> <font color=\"Red\">فرخی .</font><br />شعر در تهنیت شاهی من دانم گفت <br />تو در آن شعر که فردا بطرازم بنگر.<br /> <font color=\"Red\">فرخی .</font><br />بنده آمد که ترا مژده دهد از نوروز<br />مژده بپذیر و بده خلعت و کارش بطراز.<br /> <font color=\"Red\">فرخی .</font><br />رخ دولت بفروز آتش فتنه بنشان <br />دل حکمت بزدای آلت ملکت بطراز.<br /> <font color=\"Red\">منوچهری .</font><br />آن گردن مخروط هر آنگه که بیازند<br />وز گوش و سر و تیر و کمانی بطرازند.<br /> <font color=\"Red\">منوچهری (دیوان چ <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٥</span>).</font><br />بفرمود کاورشن و برزهم <br />طرازند لشکر طلایه بهم .<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />عذر طرازی که میر توبه ام اشکست <br />نیست دروغ ترا خدای خریدار<br />راست نگردد دروغ و مکر بچاره <br />معصیتت را بدین دروغ میاچار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />نماند کار دنیا جز ببازی <br />بقائی نیستش هر چون طرازی .<br /><font color=\"Red\">ناصرخسرو.</font><br />از من نثار شکر و جواب مفصلت <br />آنرا که از سؤال طرازد نثار من .<br /> <font color=\"Red\">ناصرخسرو.</font><br />یکی دیبا طرازیدم نگاریده بحکمتها<br />که هرگزنآمد و ناید چنین از روم دیبائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دانش آموز و سر از گرد جهالت بفشان <br />راستی ورز و بکن طاعت و حیلت مطراز.<br /> <font color=\"Red\">ناصرخسرو.</font><br />هم مقصر باشی ای دل گر بمدح مصطفی <br />معنی از گوهر طرازی لفظ از شکر کنی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تا کی بود این بنا طرازیدن <br />چون خوابگه دوام نطرازی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />خوب دیبائی طرازیدم حکیمان را که او<br />تا قیامت جز سعادت را نبیند کس روا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چو روی دهرزی بازی طرازیدن همی بینی <br />سزد گر زو بتابی روی و کار خویش بطرازی .<br /> <font color=\"Red\">ناصرخسرو (دیوان چ مینوی ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).</font><br />قصه ای را که نظم خواهد کرد<br />برطرازد سخن بدین هنجار.<br /> <font color=\"Red\">مسعودسعد (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٦١</span>).</font><br />چو آب و آتش باشد ز لشکر تو دو فوج <br />دو صف طرازد بر مرغزار از آتش و آب .<br /> <font color=\"Red\">مسعودسعد.</font><br />هر گونه چرا داستان طرازم <br />کامروز بهر گونه داستانم .<br /> <font color=\"Red\">مسعودسعد.</font><br />گه دست یازیدم همی زلفش طرازیدم همی <br />گه نرد بازیدم همی یک بوسه بود و دو ندب .<br /> <font color=\"Red\">سنائی .</font><br />آن کار را بطرازید. (چهارمقاله ).<br />ای در آبدار نهان کرده در شکر<br />وی مشک تابدار طرازیده بر قمر.<br /> <font color=\"Red\">سیدحسن غزنوی .</font><br />از بهر تو میطرازد ایام <br />منجوق ز صبح و پرچم از شام .<br /> <font color=\"Red\">خاقانی .</font><br />کار من آن به که این و آن نطرازند<br />کآنکه مرا آفرید کارطراز است .<br /> <font color=\"Red\">خاقانی .</font><br />از بس که بصنعتش طرازید<br />نقاش طراز ساحری ساخت .<br /> <font color=\"Red\">خاقانی .</font><br />گل که عیساش طرازد مرغ است <br />نی که ادریس نشاند قلم است .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> به کارگاه بافتن دیبا و امثال آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرازیدن آب </span> ؛ طرازکردن آب . برابر کردن آن <span class=\"hlight\">:</span> <br />طلب کردن جای و تدبیر مسکن <br />طرازیدن آب و تقدیر بنیان .<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> نیکو کردن . برازیدن . (حاشیه ٔ فرهنگ اسدی نخجوانی ). و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span> و کلمه ٔ ترازیدن در همین لغت نامه شود.<br /></font></div>'),
(176319, 'طرازیدنی', '<span class=\"hlight\">طرازیدنی .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ دَ ]</font></b> (ص لیاقت ) شایسته ٔ آرایش . لایق آراستن و پیراستن .<br /></font></div>'),
(176320, 'طرازیده', '<span class=\"hlight\">طرازیده .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) آراسته . نگاریده . نگارشده <span class=\"hlight\">:</span> <br />فرازش درفشی درفشان چو شید<br />به پیکر طرازیده پیل سپید.<br /> <font color=\"Red\">اسدی .</font><br />طرازش یکی نغز طاووس نر<br />طرازیده از گونه گونه گهر.<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />طرازیده برپیل اورنگ اوی <br />ز گوهر گرفته جهان رنگ اوی .<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />بدادش ز بیجاده تختی دگر<br />طرازیده بر پشت شیری ز زر.<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />فراوان در او مرغ و نخجیر گور<br />طرازیده از سیم و زر و بلور.<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرازیده موی </span> ؛ گیسوآراسته <span class=\"hlight\">:</span> <br />پرستار صف زد دوصد ماهروی <br />طرازی بتان طرازیده موی .<br /><font color=\"Red\">اسدی (گرشاسب نامه ).</font><br /></font></div>'),
(176321, 'طرازیدگی', '<span class=\"hlight\">طرازیدگی .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) آرایش . پیرایش . حالت و چگونگی طرازیده . آراستگی .<br /></font></div>'),
(176322, 'طرازین', '<span class=\"hlight\">طرازین .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) دزی در لغتنامه ٔ خود برای شاهد استعمال این کلمه ٔ عبارت ذیل را از الف لیلة و لیله چاپ پرسلا ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span> سطر <span class=\"hlight\" dir=\"rtl\">١</span> و <span class=\"hlight\" dir=\"rtl\">٢</span> آورده است : فدخل الی مقصورة من مقاصیر الحمام و رمی فیها طرازین و زینها من الجانبین : ثم انه صورالطرازین صورة مارات العیون احسن منها و هی صورة لاروح فیهاو هی صورة ماریه بنت ملک بغداد ثم ان ّالفقیر لما تم الصورة، مضی الی حال سبیله . پس از نقل عبارت فوق گوید: معنی کلمه ٔ مزبور را ندانستم . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>).<br /></font></div>'),
(176323, 'طراسا', '<span class=\"hlight\">طراسا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی نوعی از درخت بلوط است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176324, 'طراسولن', '<span class=\"hlight\">طراسولن .</span><font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) طالیفراست . (فهرست مخزن الادویه ).<br /></font></div>'),
(176325, 'طراشنه', '<span class=\"hlight\">طراشنه .</span> <font color=\"DarkGreen\"><b>[ طَ ش ِ ن َ ]</font></b> (ع اِ) عشبةالعجوز. عشبةالعجول . طرشة. جعفریة و آن گیاهی است که چون سرمه برای ستردن سفیدی (بیاض العین ) بکار است .این نام در اصل «طرسنة» بوده است . (لکلرک ص <span class=\"hlight\" dir=\"rtl\">٤٠٧</span>).<br /></font></div>'),
(176326, 'طراشولی', '<span class=\"hlight\">طراشولی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) بقول زُنتهایمر اسم اندلسی قسم صغیر صامر بوما است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(176327, 'طراعس', '<span class=\"hlight\">طراعس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) عنب الثعلب است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176328, 'طراعنون', '<span class=\"hlight\">طراعنون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) نباتی است که منبت او در زمین اقریطش باشد و جز آن موضع در موضع دیگر نبود و او را گلی است و میوه ای و صمغی که در ادویه بکار شود، او دو نوع است : یکنوع از نبات او باقوت قبض در غایت کمال است . (ترجمه ٔ صیدنه ). مصحف طراغیون . رجوع به طراغیون شود.<br /></font></div>'),
(176329, 'طراعودیا', '<span class=\"hlight\">طراعودیا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ)این صورت در اساس الاقتباس خواجه نصیر چ تهران آمده است و مصحف «طراغوذیا» است . رجوع به همین کلمه شود.<br /></font></div>'),
(176330, 'طراعیس', '<span class=\"hlight\">طراعیس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) رازی گفته از جنس نخود سیاه است و گفته اند حبی است کوچک سیاه که در باقلا بهم میرسد و گفته اند خندروس است و سلت را نیز گفته اند. (فهرست مخزن الادویه ).<br /></font></div>'),
(176331, 'طراغافیثا', '<span class=\"hlight\">طراغافیثا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) اسم یونانی کتیرا است . (فهرست مخزن الادویه ) (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(176332, 'طراغلودس', '<span class=\"hlight\">طراغلودس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) طرغودس . به یونانی طائری است که به فرنگی صفرغون نامند. (فهرست مخزن الادویه ). صاحب تحفه این کلمه را طرغلودیس ضبط کرده و گوید طرغلودیس صفراقون است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(176333, 'طراغوبوغن', '<span class=\"hlight\">طراغوبوغن .</span> <font color=\"DarkGreen\"><b>[ طِغ ُ ]</font></b> (معرب، اِ) قومینی .قومین . مثلث . نوعی از گیاهان از خانواده ٔ مرکبان، شامل پنجاه نوع که در قاره ٔ قدیم یافته شود. (در فرانسه پنج قسم آن وجود دارد). این گیاه را رازی یاد کرده و آنرا قوسی نامیده است . دیسقوریدوس در دوم گوید: و برخی آنرا قومسی خوانده اند. و آن نی کوتاهی است دارای برگی شبیه به برگ گیاه زعفران و ریشه ٔ آن درازاست و بر ساقه ٔ آن سر بزرگی است که در کناره ٔ آن میوه ٔ سیاهی دیده میشود. این گیاه بمصرف خوردن نیز میرسد. غافقی گوید: رازی گفته است قومسی گیاهی است که در گندم زارها و جز آن می روید و آنرا مثلث نامند. و صاحب «کتاب » الفلاحة گوید: ساقه ٔ آن کوتاه است که چه بسا بر آن برگهای دراز باریک می روید که گوئی نسبت به خود گیاه سبزی برگها شدیدتر است و گاهی هم ساقه ٔ مزبور بی برگ است و آنرا ریشه ٔ دراز درشتی است برنگ خاکی که دارای پوست غلیظی است و در سر آن باری است شبیه به غوزه ٔ پنبه و در درون آن تخمی است که مأکول و لذیذ و خوشبو است و ریشه ٔ آن بسیار شیرین است . مردم آنرا با ساقه میخورند و برای بسیاری اشک آوردن چشم سودمند است و هم بوی بد دهان را رفع کند. (از مفردات ابن البیطار). و رجوع به ترجمه ٔ ابن البیطار لکلرک شود.<br /></font></div>'),
(176334, 'طراغودیعاس', '<span class=\"hlight\">طراغودیعاس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) طراغوریفایس . به یونانی فوتینج جبلی است . (فهرست مخزن الادویه ). و صاحب تحفه این لفظ را طراغوریغاس ضبط کرده و گوید:طراغوریغاس، فودنج جبلی است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(176335, 'طراغوذیا', '<span class=\"hlight\">طراغوذیا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) معرب تراگویتا، تراژدی . این صورت در قسمت منطق از کتاب الشفای ابن سینا آمده است و خواجه نصیرالدین دراساس الاقتباس آرد: و یونانیان را اغراضی محدود بوده است مشتمل بر ذکر خبر و اخبار و تخلص به مدح یکی از آن طایفه که آنرا طراعودیا خوانده اند و آن بهترین انواع بوده است و آنرا وزنی بغایت لذیذ بود. (اساس الاقتباس خواجه نصیر ص <span class=\"hlight\" dir=\"rtl\">٥٩٠</span>).<br /></font></div>'),
(176336, 'طراغوریغانس', '<span class=\"hlight\">طراغوریغانس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) نوعی از صعتر .<br /></font></div>'),
(176337, 'طراغوریغایس', '<span class=\"hlight\">طراغوریغایس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی صنفی از صعتر است . (فهرست مخزن الادویه ). در اختیارات بدیعی (در نسخه ٔ خطی ) طراغوریغایش ضبط شده و گوید: فودنج جبلی است . (اختیارات بدیعی ).<br /></font></div>'),
(176338, 'طراغوس', '<span class=\"hlight\">طراغوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) مثلث . طیفا . حنطه ٔ صغار.<br /></font></div>'),
(176339, 'طراغیس', '<span class=\"hlight\">طراغیس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) سلت است . (فهرست مخزن الادویه ) (تحفه ٔ حکیم مؤمن ). به لغت یونانی دوائی است که آن را بفارسی جو برهنه، و برهنه جو و به عربی سلت گویند. و آن چیزی باشد مانند گندمی که پوست آنرا کنده باشند و به این معنی طراقیس هم آمده است که بجای غین قاف باشد. (برهان ) (آنندراج ).<br /></font></div>'),
(176340, 'طراغیون', '<span class=\"hlight\">طراغیون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) نام نباتی است و صمغ آن مانند صمغ عربی میباشد. یک مثقال آن سنگ گرده را بریزاند و حیض را بگشاید. (برهان ).نباتی است که در جزیره ٔ اقریطش روید و صمغ وی مانندصمغ عربی بود و حرارت ورق وی و صمغ وی در اول درجه سیم بود، سنگ گرده را بریزاند و حیض براند، چون یک مثقال از وی بیاشامند و این نبات بغیر از جزیره ٔ اقریطش نروید و درخت وی مانند درخت مصطکی بود. (اختیارات بدیعی ). اسم یونانی بمعنی شبیه به «بیش » است، آن دوقسم میباشد: یکی را برگ و شاخ بزرگ و مانند اسقولوقندریون و با اندک زغب و صمغ او مانند صمغ عربی و در جزیره ٔ اقریطش بسیار است و یکی کوچکتر و در ساحل دریا بهم میرسد بی ساق و بر شاخهای او دانه ها بقدر گندمی و هر دو سر آن باریک و سرخ . و در سیم گرم و خشک و مدر حیض و جذاب و مخرج خار و پیکان از بدن و مفتت حصاة و یک مثقال او با شراب مخرج جنین است شرباً و حمولاً. (تحفه ٔ حکیم مؤمن ) شجرةالتیس . لکلرک گوید: اشپرنگل طراغیون اول را مترادف هیپریکوم هیرسینوم این دو کلمه را زنتهایمر مترادف میداند ولی فرااس رد میکند و با شک و تردید آنرامترادف اریگانوم مارو میداند. اشپرنگل طراغیون دوم را مترادف تراژیوم کولمنو . طراغیون را در حاشیه ٔ ترجمه ٔ عربی دیسقوریدوس چنین تعبیر کرده اند: تأویله التیس (یعنی مربوط و متعلق به بُز). طراغیون دیگر؛ سقوربیون، طرغانن . رجوع به طرغانن شود. ابن البیطار آرد: دیسقوریدوس در چهارم گوید: برخی آنرا سقرینوس و گروهی طرغاین نامیده اند؛ درختچه ای است که بر روی زمین گسترده میشود. درازی آن به اندازه ٔ یک وجب یا کمی بیشتر است . در سواحل دریائی میروید. دارای برگ است و بر شاخه های آن باری است مانند دانه ٔ انگور سرخ رنگ و بسیار خرد به اندازه ٔ دانه ٔ گندم است دو نوک آن تیز و پرگره و قابض میباشد و هرگاه از میوه این گیاه بمقدار ده دانه شربتی بسازند و بنوشند بیماریهای اسهال مزمن و سیلان رطوبت مزمن رحم را سودمند بود و برخی از مردم دانه ٔ آنرا میکوبند و از آن قرص میسازند و هنگام حاجت به کار میبرند. (از مفردات ابن البیطار).<br /></font></div>'),
(176341, 'طراف', '<span class=\"hlight\">طراف .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) خرگاه ادیم . ج، طُرَف . (منتهی الارب ) (آنندراج ). خیمه ٔ ادیمین . (مهذب الاسماء). خیمه ٔ چرمین . خیمه ای از چرم . ابنیةالعرب طراف ٌ او اخبیةٌ. فالطرف من ادم، و الخباء من صوف او وبر. <BR><font color=\"Blue\">◄</font> آنچه از اطراف کشت و نواحی آن گیرند. <BR><font color=\"Blue\">◄</font> یقال : توارثوا المجد طرافاً؛ یعنی بزرگی و شرافت را میراث یافتند. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (مص ) سباب . (اقرب الموارد). دشنام به یکدیگر دادن .<br /></font></div>'),
(176342, 'طراف', '<span class=\"hlight\">طراف .</span> <font color=\"DarkGreen\"><b>[ طَرْ را ]</font></b> (اِخ ) از اعلام است . (منتهی الارب ).<br /></font></div>'),
(176343, 'طرافة', '<span class=\"hlight\">طرافة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (ع مص ) نو شدن . تازه گردیدن .<br /></font></div>'),
(176344, 'طرافش', '<span class=\"hlight\">طرافش .</span> <font color=\"DarkGreen\"><b>[ طُ ف ِ ]</font></b> (ع ص ) دشوارخوی . <BR><font color=\"Blue\">◄</font> بدسرشت از مردم و شتر. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176345, 'طرافل', '<span class=\"hlight\">طرافل .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ ]</font></b> (معرب، اِ) اطریفل . هندی معرب، اصلش تیر پهله، یعنی سه بار وآن عبارت از هلیله و بلیله و آمله است <span class=\"hlight\">:</span> <br />اگر ز علت کین تو دل ضعیف شود<br />نه از طرافل سودش بود نه از جلاب .<br /> <font color=\"Red\">امیرمعزی .</font><br />و میتواند که اطریفل معرب طریفل بدون همزه ٔ اماله ٔ طرافل بود، پس طرافل معرب ترپهله یا تری پهل باشد، نه معرب اطریفل . واﷲ اعلم بحقیقة الحال . (آنندراج ).<br /></font></div>'),
(176346, 'طراق', '<span class=\"hlight\">طراق .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) از قصور قفصه ٔ افریقا در نیمه ٔ راه قفصه بسوی فنج الحمام واقع است برای کسی که عازم قیروان باشد. شهری بزرگ و آباد است، دارای مسجد جامع و بازار معمور و کساء طراقی که جامه ای است مرغوب از صادرات آن شهر است و بیشتر بمصر میفرستند. این شهر پسته ٔ بسیار دارد. (معجم البلدان چ مصر ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨</span>). و در شرح کلمه ٔ قفصه باز در معجم البلدان آمده : از قصور قفصه شهر «طراق »است شهری است بسیارحصین . حصاری از خشتهای بس بزرگ بر گرد آن ساخته اند؛ هر یک پاره ٔ خشت آن به درازای ده وجب است . یوسف بن عبدالمؤمن از سلسله ٔ موحدین بر اثر نافرمانی اهالی آن شهر را با خاک یکسان ساخت . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٨</span>). و رجوع به فرهنگ شعوری شود.<br /></font></div>'),
(176347, 'طراق', '<span class=\"hlight\">طراق .</span> <font color=\"DarkGreen\"><b>[ طِرْ را ]</font></b> (معرب، اِ) تریاق . (منتهی الارب ). لغةٌ فی الدریاق، و هو رومی ٌ معرب ٌ. (المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٣</span>). اسم تریاق است، و آن مرکبی است معروف .(فهرست مخزن الادویه ). رجوع به تریاق و تریاک شود.<br /></font></div>'),
(176348, 'طراق', '<span class=\"hlight\">طراق .</span> <font color=\"DarkGreen\"><b>[طَ ]</font></b> (اِ صوت ) بر وزن رواق صدا و آوازی باشد که از کوفتن و شکستن چیزی همچون استخوان و چوب و مانند آن برآید. (برهان ). آوازی که از زدن تازیانه برآید. (غیاث اللغات ). آواز صعب که بر سبیل توالی خیزد از شکستن چوب و استخوان و مقرعه، و لولی (کذا) <span class=\"hlight\">:</span> <br />از دل شیر و پلنگ آید آنگاه طراق <br />گر بشست تو برآید ز کمان تو ترنگ .<br /> <font color=\"Red\">(آنندراج ).</font><br />تراک . طراقه . آواز افتادن چیزی گران بر زمین و مانند آن . آواز ترکیدن چیزی گران بر زمین و مانند آن . آواز ترکیدن چیزی . آواز. رجوع به طراقه و طراک شود <span class=\"hlight\">:</span> <br />طراقی برآمد ز حلقوم اوی <br />که لرزان شد آن کنده و بوم اوی .<br /> <font color=\"Red\">فردوسی .</font><br />چوب را بشکنی طراق کند<br />آن طراق از سر فراق کند.<br /> <font color=\"Red\">سنائی .</font><br />ساعتی توقف کرد، طراقی در آن کوه افتاد، چنانکه کوه از هیبت آن آواز بلرزید. (اسرارالتوحید ص <span class=\"hlight\" dir=\"rtl\">٨١</span>).<br />طراق مقرعه بر خاک و بر سنگ <br />ادب کرده زمین را چند فرسنگ .<br /> <font color=\"Red\">نظامی .</font><br />خلیفه بر تخت بود و ارکان دولت حواشی نشسته بودند، طراقی در آن سرای افتاد و خلیفه با ارکان دولت به یک بار بر زمین فروشدند. (تذکرةالاولیاء عطار).<br />چون زدش سیلی برآمد یک طراق <br />گفت صوفی هی هی ای قواد عاق .<br /> <font color=\"Red\">مولوی .</font><br />تو ناز کنی ویار تو ناز<br />چون ناز دو شد طلاق خیزد<br />یار است نه چوب مشکن او را<br />گر بشکنیش طراق خیزد.<br /> <font color=\"Red\">مولوی .</font><br />رجوع به فرهنگ شعوری شود.<br /></font></div>'),
(176349, 'طراق', '<span class=\"hlight\">طراق .</span> <font color=\"DarkGreen\"><b>[ طُرْ را ]</font></b> (ع ص، اِ) ج ِطارق . فال سنگک زنندگان . (مهذب الاسماء). فال سنگ گیرنده . (منتهی الارب ). و الطراق ؛ المتکهنون . و هن الطوارق . (تاج العروس ). از این رو طُرّاق ج ِ مذکر طارق وطوارق، طارقات ج ِ مؤنث طارقة باشد. (اقرب الموارد). دل . کاهنان . (منتخب اللغات ). آنکه فال سنگک گیرد.<br /></font></div>'),
(176350, 'طراق', '<span class=\"hlight\">طراق .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) آهنی که پهن کرده سپس آن را گرد ساخته خود و مانند آن سازند. (منتهی الارب ) (آنندراج ).<BR><font color=\"HotPink\">♦ </font>طراق النعل ؛ پاره ای نعل که بر موزه زنند و هر پاره ای برابر یکدیگر باشد. (منتهی الارب ) (آنندراج ). صندل هم لخت . (مهذب الاسماء در دو نسخه ٔ خطی ). <BR><font color=\"Blue\">◄</font> هر پیشه ای که برابر چیزی باشد. <BR><font color=\"Blue\">◄</font> پوست پاره ای که گرد کرده بر سپر چفسانند. <BR><font color=\"Blue\">◄</font> ریش ٌ طراق ٌ؛ پر بر هم نشسته . <BR><font color=\"Blue\">◄</font> داغیست میان دو گوش گوسپند. ج، طرق . (منتهی الارب ) (آنندراج ). و رجوع به تاج العروس شود.<br /></font></div>'),
(176351, 'طراق تپه', '<span class=\"hlight\">طراق تپه .</span> <font color=\"DarkGreen\"><b>[ طُ ت َپ ْ پ َ ]</font></b> (اِخ ) دهی است از دهستان سرشیو بخش مریوان شهرستان سنندج، واقع در <span class=\"hlight\" dir=\"rtl\">٥٥</span>هزارگزی شمال خاوری دژ شاهپور و <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی خاور گویله . کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">١٥٠</span>تن سکنه . آب آن از چشمه ها. محصول آنجا غلات، لبنیات و حبوبات . شغل اهالی زراعت و گله داری . راه آن مالرو و صعب العبور است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(176352, 'طراقاطراق', '<span class=\"hlight\">طراقاطراق .</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (اِ صوت مرکب ) آوازها و صداهای پی در پی را گویند <span class=\"hlight\">:</span> <br />چو خورشید سر برزندزین نطاق <br />برآید ز دریا طراقاطراق .<br /> <font color=\"Red\">نظامی .</font><br />طراقاطراق گران سنگها<br />همی رفت هر سو بفرسنگها.<br /><font color=\"Red\">هاتفی (از شعوری ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span>).</font><br /></font></div>'),
(176353, 'طراقای', '<span class=\"hlight\">طراقای .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) پنجمین پسر از پسران هلاکوخان، و مادر او یورقچین و قما بود. (حبیب السیر چ خیام ). اقبال در تاریخ مغول این اسم را طرغای ضبط کرده و گوید: در سال <span class=\"hlight\" dir=\"rtl\">٦٩٥</span> هَ . ق . قریب ده هزار نفر از مغول از طایفه ٔ اویرات به ریاست طرغای از خوف غازان به پناه مسلمین آمدند و طرغای (چنانکه سابقاً گفتیم ) با بایدو در قتل کیخاتو دست یکی کرده بود، و چون غازان به سلطنت رسید، مصمم شد که او را بگیرد و از او انتقام قتل کیخاتو را بکشد. طرغای و مغولان اویرات بشام آمده از الملک العادل کتبغا تقاضای حمایت کردند کتبغا هم ایشان را محترم داشته، خلعت و پول داد و در بلاد خود سکونت داد. (تاریخ مغول عباس اقبال آشتیانی ص <span class=\"hlight\" dir=\"rtl\">٢٧٠</span>).<br /></font></div>'),
(176354, 'طراقه', '<span class=\"hlight\">طراقه .</span> <font color=\"DarkGreen\"><b>[ طَ ق َ ]</font></b> (اِ صوت ) تراک . (حاشیه ٔ فرهنگ اسدی نخجوانی ). رجوع به طراق و طراک شود.<br /></font></div>'),
(176355, 'طراقی ترک', '<span class=\"hlight\">طراقی ترک .</span> <font color=\"DarkGreen\"><b>[ طَ ت ُ ]</font></b> (اِخ ) دهی است از دهستان نوده چناران بخش حومه ٔ شهرستان بجنورد، واقع در <span class=\"hlight\" dir=\"rtl\">٢٣</span>هزارگزی جنوب خاوری بجنورد و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی جنوب راه قدیم بجنورد به قوچان . کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٧٤٨</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات، بنشن و باغات انگور. شغل اهالی زراعت و مالداری . راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176356, 'طراقی کرد', '<span class=\"hlight\">طراقی کرد.</span> <font color=\"DarkGreen\"><b>[ طَ ک ُ ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش حومه ٔ شهرستان بجنورد، واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی جنوب خاوری بجنورد و <span class=\"hlight\" dir=\"rtl\">٤</span>هزارگزی جنوب شوسه ٔ قدیمی بجنورد به قوچان . کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">١٣٥٠</span> تن سکنه . آب آن از چشمه و رودخانه . محصول آنجا غلات، بنشن و میوه ها. شغل اهالی زراعت و مالداری . راه آن عرابه رو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176357, 'طراقیه', '<span class=\"hlight\">طراقیه .</span> <font color=\"DarkGreen\"><b>[ طَ ی َ ]</font></b> (اِخ ) دهی است از دهستان خدابنده لو بخش قروه ٔ شهرستان سنندج، واقع در <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی شمال خاور گز تپه و <span class=\"hlight\" dir=\"rtl\">٨</span>هزارگزی خاور علی سرد. تپه ماهور، سردسیر با <span class=\"hlight\" dir=\"rtl\">٨٠٠</span> تن سکنه . آب آن از چشمه و قنات . محصولات آنجا غلات، انگور، صیفی، لبنیات و حبوبات . شغل اهالی زراعت و گله داری . راه آن مالرو است و در تابستان از طریق گل تپه و سراب و کبودرآهنگ اتومبیل میتوان برد. قلعه ٔ قدیمی دارد. دوکیلومتری باغ معروف به باغ وزیرجزء این ده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(176358, 'طرالوی', '<span class=\"hlight\">طرالوی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) و اندر دریای هند از جزیره های آباد و بیران هزار و سیصد و هفتاد جزیره است ویکی عظیم تر است که آنرا طرالوی خوانند. سه هزار میل است با قصی بحر، برابر زمین هندوان از ناحیت شرق، و آنجا کوههای عظیم و نهرهای بسیار است که از آنجا یاقوت سرخ و دیگر لونها بیرون آید و جوهرها نیکو و پیرامون آن نوزده جزیره است وشهرها و سراندیب و کوه راهون که آدم علیه السلام از بهشت بر آنجا افتاد. (مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٤٧١</span>).<br /></font></div>'),
(176359, 'طرالینوس', '<span class=\"hlight\">طرالینوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) از پزشکان است که پیش از عصر جالینوس میزیسته و گویند وی همان اسکندروس پزشک معروف است .او راست : کتاب علل العین و علاجها که محتوی بر سه مقاله میباشد. کتاب البرسام . کتاب الضبان و الحیات التی تتولد فی البطن و الدیدان . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br /></font></div>'),
(176360, 'طرامة', '<span class=\"hlight\">طرامة.</span> <font color=\"DarkGreen\"><b>[ طُ م َ ]</font></b> (ع اِ) کبودی دندان . (منتهی الارب ) (آنندراج ). سبزی دندان .(مهذب الاسماء). <BR><font color=\"Blue\">◄</font> آنچه در میان دندان بماند از طعام و جز آن . (منتهی الارب ) (آنندراج ). و نص اللحیانی بقیةاللحم . (تاج العروس ). <BR><font color=\"Blue\">◄</font> خیو خشک شده ٔ بر لب . (مهذب الاسماء). و قال غیره : هو الرقیق الیابس علی الفم من العطش . و قیل هو یجف علی فم الرجل من الریق من غیر ان یقید بالعطش . (تاج العروس ).<br /></font></div>'),
(176361, 'طرامیلس', '<span class=\"hlight\">طرامیلس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) علک البطم . (فهرست مخزن الادویه ). رجوع به طرابیون شود.<br /></font></div>'),
(176362, 'طران', '<span class=\"hlight\">طران .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) جایگاهی است که ذکر آن در اشعار عرب آمده است (مراصد). (معجم البلدان ).<br /></font></div>'),
(176363, 'طران زلوانیا', '<span class=\"hlight\">طران زلوانیا.</span> <font color=\"DarkGreen\"><b>[ طِ زِ ]</font></b> (اِخ ) یکی از ایلات رومانیا است . رجوع به ترانسیلوانی شود.<br /></font></div>'),
(176364, 'طران نویان', '<span class=\"hlight\">طران نویان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) در جامعالتواریخ رشیدی چ بلوشه ص <span class=\"hlight\" dir=\"rtl\">٥٦٩</span> آمده : و ملک تیمور بجای او دختر طران نویان پسرزاده ٔ اولاد قرنویان از چلا بربستد... و در حاشیه ٔ همان صفحه آمده : نسخه ٔ طانی، طران ؛ طای (دای ) معروف کلمه ٔ چینی تهای که دهای تلفظ میشد و در عصر مغول بمعنی بزرگ بود.<br /></font></div>'),
(176365, 'طرانه', '<span class=\"hlight\">طرانه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) در ابن البیطار چ مصر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٩</span> در شرح کلمه ٔ جثجاث آمده : «و هی علی طریق الطرانة» و لکلرک در ترجمه ٔ ابن البیطار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٧</span> این نام را «طارنه » یاد کرده است . رجوع به طارنه شود.<br /></font></div>'),
(176366, 'طرانیدن', '<span class=\"hlight\">طرانیدن .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b> (مص ) طرازیدن <span class=\"hlight\">:</span> <br />درِ مخزن و حجره ها باز کرد<br />طرانیدن حجله آغاز کرد.<br /> <font color=\"Red\">میرنظمی (شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span>).</font><br />(احتمالاً دگرگون شده ٔ طرازیدن باشد).<br /></font></div>'),
(176367, 'طراوت', '<span class=\"hlight\">طراوت .</span> <font color=\"DarkGreen\"><b>[ طَ وَ ]</font></b> (ع مص ) طراء، طراءَة، طراوة؛ تر و تازه شدن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِمص ) تازگی . (مهذب الاسماء) <span class=\"hlight\">:</span> <br />همه خشکی بود طراوت تو<br />که چو رویم مباد رویت تر.<br /> <font color=\"Red\">مسعودسعد.</font><br />طراوت خلافت به جمال انصاف و کمال معدلت باز بسته است . (کلیله و دمنه ). بلکه هر روز زیادت و طراوت گیرد. (کلیله و دمنه ).<br />لطافت حرکات فلک بگاه سماع <br />طراوت نفحات ملک بگاه ندا.<br /> <font color=\"Red\">خاقانی .</font><br />با طراوت جوانی و مقتبل شباب در اقران و اتراب خویش بی نظیر است . (ترجمه ٔ تاریخ یمینی چاپی ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>) چهره های زیبا چون برگ خزان، طراوت فروریخت . (ترجمه ٔ تاریخ یمینی ). در مروّت و علوّ همت او نقصانی نیامد و رونق حال و طراوت جاه او کم نشد. (ترجمه ٔ تاریخ یمینی ).<br />خدای داد بملک زمانه دیگر بار<br />طراوتی نه به اندازه ٔ قیاس و شمار.<br /> <font color=\"Red\">کمال اسماعیل (از آنندراج ).</font><br />و با لفظ دادن و چکیدن مستعمل <span class=\"hlight\">:</span> <br />میچکد گرچه طراوت ز تو چون سرو بهشت <br />قامتی تشنه ٔ آغوش کشیدن داری .<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br />تازگی . (از منتخب ). نه بمعنی تری . (غیاث اللغات ). شادابی، ترّی . غضاضة.<br /></font></div>'),
(176368, 'طراوتناک', '<span class=\"hlight\">طراوتناک .</span> <font color=\"DarkGreen\"><b>[ طَ وَ ]</font></b> (ص مرکب ) تازه و پر آب <span class=\"hlight\">:</span> <br />بُتا گر عنبری با زلف، با رخسار گر آتش <br />چسان داری طراوتناک عنبر را تو بر آتش .<br /><font color=\"Red\">ابونصر نصیرای بدخشانی (از آنندراج ).</font><br /></font></div>'),
(176369, 'طراوه', '<span class=\"hlight\">طراوه .</span> <font color=\"DarkGreen\"><b>[ طَ وَ ]</font></b> (اِخ ) کوهی است معروف در نجد. <BR><font color=\"Blue\">◄</font> جایگاهی است که در شعر ذکر آن آمده است . (مراصدالاطلاع ).<br /></font></div>'),
(176370, 'طراوه', '<span class=\"hlight\">طراوه .</span> <font color=\"DarkGreen\"><b>[طَ وَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) جامه ای باشد ابریشمی که بر سر سنان نیزه و علم بندند. (برهان ). جامه ٔ ابریشمی و رنگین که بر سر سنان نیزه و علم بندند و در مؤید بجای واو، دال مهمله نوشته . (آنندراج ) (غیاث اللغات ). رجوع به فرهنگ شعوری ص <span class=\"hlight\" dir=\"rtl\">١٦٨</span> و طراده در معنی عَلَم شود.<br /></font></div>'),
(176371, 'طراک', '<span class=\"hlight\">طراک .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ صوت ) بمعنی طراق است که آواز کوفتن و شکستن چیزها باشد. (برهان ) (آنندراج ). رجوع به طراق و طراقه شود.<br /></font></div>'),
(176372, 'طرایانس', '<span class=\"hlight\">طرایانس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) یکی از پادشاهان روم : مملکت وی نوزده سال بوده است . وی را هیچ ذکر نیافته ایم بعد از قدر. (مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>). او همان تراژان امپراتور روم است از سال <span class=\"hlight\" dir=\"rtl\">٩٨</span> تا <span class=\"hlight\" dir=\"rtl\">١١٧</span> م .و متولد در ایتالیکا ست (در اسپانیا) بسال <span class=\"hlight\" dir=\"rtl\">٥٢</span> م . وی برپارتیان (ایران ) غلبه کرد (<span class=\"hlight\" dir=\"rtl\">١٠١</span> - <span class=\"hlight\" dir=\"rtl\">١٠٥</span> م .). در نظم امور مهارت داشت و ابنیه ٔبسیار بنا کرد و مسیحیان را مورد ایذاء قرار داد.<br /></font></div>'),
(176373, 'طرایف', '<span class=\"hlight\">طرایف .</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ ]</font></b> (ع ص، اِ) ج ِ طریفة. چیزهای لطیف و خوش . طرائف . <BR><font color=\"Blue\">◄</font> مالهای نو و تازه . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> میوه های نادر و غیر آن . (منتهی الارب ). هر شی ٔ نادر <span class=\"hlight\">:</span> <br />ببردند سیصد شترسرخ موی <br />طرایف بسی بود چینی بروی .<br /> <font color=\"Red\">فردوسی .</font><br />طرایف که باشد به چین اندرون <br />بیاراست از هر دری صد هیون .<br /> <font color=\"Red\">فردوسی .</font><br />بر اثر ایشان هزار کنیزک ترک آمد و بدست هر یکی جامی زرین یا سیمین پر از مشک و کافور و عنبر و اصناف عطر و طرایف شهرها. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٢٤</span>). چندان جامه و طرایف و زرینه و سیمینه و غلام و کنیزک و مشک و کافور... بود. بتعجب ماندند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤١٩</span>). بسیار زر و جواهر و طرایف آنجا بردند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٠٢</span>). و رسول را بازگردانیدند و طرایف انداختند که حد نبود. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٧٨</span>). به بازارها درم و دینار و شکر و طرایف نثار کردند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٧٥</span>). مردم بلخ بسیار شادی کردند و بسیار درم و دینار و طرایف و هر چیزی برافشاندند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٩٣</span>). آخر پس از آمد و شدن بسیار بر آن قرار گرفت که آن خلعت که حسنک ستده بود و آن طرایف که نزد سلطان محمود فرستاده بودند، آن مصریان با رسول ببغدادفرستد تا بسوزند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٧٩</span>). به دشت شابهار آمد با تکلفی سخت عظیم از پیلان و جنیبتیان، چنانکه سی اسب با ساختهای مرصع بجواهر و پیروزه و پشم (کذا فی جمیعالنسخ ) و طرایف دیگر. (تاریخ بیهقی چ فیاض ص <span class=\"hlight\" dir=\"rtl\">٢٧١</span>).<br />ز برگ و ز شمشیر و از درع نیز<br />همیدون طرایف ز هر گونه چیز.<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />و قطران تبریزی در بیت زیر طرایف را جمع طرفه آورده است <span class=\"hlight\">:</span> <br />دشت شد از باغ پرظرایف عمان <br />باغ شد از ابر پرطرائف بغداد.<br />رجوع به طرفه ٔ بغداد در امثال و حکم دهخدا شود.<br />با پیشکشی ز هر طرایف <br />آورده ز روم و چین و طایف .<br /> <font color=\"Red\">نظامی </font><br />گزید از غنیمت طرایف بسی <br />کزآن سان نبیند طرایف کسی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(176374, 'طرایف کش', '<span class=\"hlight\">طرایف کش .</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) که طرایف کشد. حاملان طرایف <span class=\"hlight\">:</span> <br />طبقهای بلور و خوانهای لعل <br />طرایف کشان را بفرسود نعل .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(176375, 'طرایف گر', '<span class=\"hlight\">طرایف گر.</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ گ َ]</font></b> (ص مرکب ) ترتیب دهنده ٔ طرایف . طرایفی <span class=\"hlight\">:</span> <br />گه معصفرپوش گردد گه طبرخون تن شود<br />گاه دیباباف گردد گه طرایف گر شود.<br /><font color=\"Red\">قطران (در وصف ِ آتش سده ).</font><br /></font></div>'),
(176376, 'طرایفی', '<span class=\"hlight\">طرایفی .</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ ]</font></b> (ص نسبی ) طرائفی . این لفظ نسبتی است که به فروشنده ٔ اشیای طرفه و نادر از قبیل اشیای زیبائی که از چوب و تخته و مانند آن بدقت میسازند داده شده، همچنین فروشنده ٔ شراب طرفه و نادر را نیز طرائفی گویند. عین متن عبارت سمعانی برای مزید استبصار نقل میگردد: هذه النسبة الی بیعالطرائف و شرابها و هی الاشیاء الملیحة من الخشب . (سمعانی ص <span class=\"hlight\" dir=\"rtl\">٣٦٩</span>). طرفه فروش .<br /></font></div>'),
(176377, 'طرایق', '<span class=\"hlight\">طرایق .</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ ]</font></b> (ع اِ) طرائق . ج ِ طریقة. راهها. یقال : هذا طریقة قومهم و طرائق قومهم . (منتهی الارب ) <span class=\"hlight\">:</span> چه تنفیذ شرایع دین و اظهار طرایق ... بی سیاست پادشاه دیندار صورت نبندد. (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> هؤلاء طرائق ُ قومهم، للرجال الاشراف . (تاج العروس ). <BR><font color=\"Blue\">◄</font> قوله تعالی <span class=\"hlight\">:</span> کنا طرائق قدداً؛ ای فرقاً مختلفةٌ اهوائنا (منتهی الارب )؛ ای اهواء مختلفة، و فرقاً شتی : ما بر هوای مختلف بوده ایم و بر راههای پراکنده، بهری مؤمن و بهری کافر، بهری منافق . (قرآن <span class=\"hlight\" dir=\"rtl\">١١/٧٢</span>، از تفسیر ابوالفتوح رازی ). <BR><font color=\"Blue\">◄</font> (ص ) ثوب طرائق ؛ جامه ٔ کهنه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) طرائق البیض ؛ خطوطه التی تسمی الحبک . (تاج العروس ).<br /></font></div>'),
(176378, 'طرایله', '<span class=\"hlight\">طرایله .</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ ل َ ]</font></b> (اِ) غافث . (فهرست مخزن الادویه ).<br /></font></div>'),
(176379, 'طرب', '<span class=\"hlight\">طرب .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (اِخ ) نام اسب حضرت پیغمبر صلی اﷲ علیه و آله و سلم . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176380, 'طرب', '<span class=\"hlight\">طرب .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع اِمص ) شادمانی .(منتهی الارب ) (آنندراج ). فرح . فیریدگی . کروز. کروژ.نشاط. رامش . خوشی . خوشدلی . سرور. نشاط کردن و شاد شدن و شادی و نشاط و با لفظ کردن مستعمل <span class=\"hlight\">:</span> <br />با دوست به خرگاه طرب کردن عُشاق <br />خوشتر بود اکنون و طرب کردن گلزار.<br /> <font color=\"Red\">امیرمعزی (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> سبک شدن از غایت شادی . (مجمل اللغة). سبک شدن از غایت شادی یا از غایت اندوه . (تاج المصادربیهقی ). سبک شدن از غایت شادی و یا از غایت اندوه یا از غایت آرزو. (زوزنی ) (دهار). شوق . لهو. ملهی <span class=\"hlight\">:</span> <br />بنزدیک برزو بود روز و شب <br />به آواز او باشد او را طرب .<br /> <font color=\"Red\">فردوسی .</font><br />یکی هفته با جشن و با باده بود<br />شب و روز جام طرب میفزود.<br /> <font color=\"Red\">فردوسی .</font><br />جوان را چه باید به گیتی طرب <br />که نی مرگ را هست پیری سبب .<br /> <font color=\"Red\">فردوسی .</font><br />بوستان بانا حال و خبر بستان چیست <br />و اندرین بستان چندین طرب مستان چیست .<br /> <font color=\"Red\">منوچهری .</font><br />امیری شدم آن زمان زآن سبیل <br />ز لهو و طرب گرد من لشکری .<br /> <font color=\"Red\">منوچهری .</font><br />گاه آن است که از محنت و سختی برهند<br />جای آن است که امروز کنم من طربی .<br /> <font color=\"Red\">منوچهری (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٦٢</span>).</font><br />تا طرب و مطربست مشرق وتا مغربست <br />تا یمن و یثرب است آمل و استارباد.<br /> <font color=\"Red\">منوچهری .</font><br />دیگران در لهو و طرب بدو اقتدا میکنند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٩٣</span>). امیر با ندیمان نشاط شراب کرد و ننمودبس طربی که دلش سخت مشغول بود. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٣١</span>). در شهر چندان شادی و طرب و گشتن و شراب خوردن و مهمانی رفتن و خواندن بود که کس یاد نداشت . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٥٦</span>).<br />بهیچ چیز نباشند عاشقان خرسند<br />نه شان بهجر شکیب و نه شان بوصل طرب .<br /> <font color=\"Red\">قطران .</font><br />علم و حکمت را طلب کن گر طرب جوئی همی <br />تا بشاخ علم و حکمت پرطرب یابی رطب .<br /> <font color=\"Red\">ناصرخسرو.</font><br />داری طرب کن، نداری طلب کن . (خواجه عبداﷲ انصاری ).<br />آری چو پیش آید قضا مروا شود چون مرغوا<br />جای شجر گیرد گیا جای طرب گیرد سجن .<br /> <font color=\"Red\">امیرمعزی .</font><br />روز می خوردن و شادی و نشاط و طرب است <br />ناف هفته است اگر غره ٔ ماه رجب است .<br /> <font color=\"Red\">انوری .</font><br />هر طرب را برابر است کرب <br />هر یمین را مقابل است یسار.<br /> <font color=\"Red\">خاقانی .</font><br />در شکرریز طرب بر عده داران رزان <br />از پی کاوین بهای کاویان افشانده اند.<br /> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">١٠٥</span>).</font><br />همه شبهای غم آبستن روز طربست <br />یوسف روز بچاه شب یلدا بینند.<br /> <font color=\"Red\">خاقانی .</font><br />با بزمت اجتماع طرب سال و مه چنانک <br />از باده ٔ هلال لب ساغر آفتاب .<br /> <font color=\"Red\">خاقانی .</font><br />اشتر بشعر عرب در حالتست و طرب <br />گر ذوق نیست ترا کژطبع جانوری .<br /> <font color=\"Red\">سعدی (گلستان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">در طرب نارد کسی را دف ّ تر</span> .<br /> <font color=\"Red\">سوزنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عمله ٔ طرب </span> ؛ هیأت مطربان . گروهی که با تغنی و نواختن آلات موسیقی ایجاد طرب کنند. رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span> شود.<br /><BR><font color=\"Blue\">◄</font> اندوه . از لغات اضداد است . حزن . غم . سوک . <BR><font color=\"Blue\">◄</font> سبکی نشاط یا اندوه .مختص به شادمانی نیست . <BR><font color=\"Blue\">◄</font> میل بسوی چیزی . <BR><font color=\"Blue\">◄</font> جنبش . (منتهی الارب ) (آنندراج ). حرکت . <BR><font color=\"Blue\">◄</font> (اصطلاح تصوف ) طرب عبارت است از انس با حق تعالی کما فی بعض الرسائل . (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> بطرب آوردن، اطراب . (منتهی الارب ) (زوزنی ).<br /></font></div>'),
(176381, 'طرب آباد', '<span class=\"hlight\">طرب آباد.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) دهی از دهستان دربقاضی بخش حومه ٔ شهرستان نیشابور، واقع در <span class=\"hlight\" dir=\"rtl\">٣</span>هزارگزی جنوب نیشابور. جلگه و معتدل با <span class=\"hlight\" dir=\"rtl\">٢١٣</span> تن سکنه . آب آن از قنات . محصول آنجا غلات . شغل اهالی زراعت . راه آن ارابه رو است . تپه ٔ معروف الب ارسلان در این ده واقع است که آثار باستانی دارد و امریکائیها کاوش کرده اند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176382, 'طرب آباد', '<span class=\"hlight\">طرب آباد.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِ مرکب ) جایگاه شادی و سرور. (آنندراج ).<br /></font></div>'),
(176383, 'طرب آرا', '<span class=\"hlight\">طرب آرا.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (نف مرکب ) آراینده ٔ انجمن . ایجاد سرور و خوشحالی کننده <span class=\"hlight\">:</span> <br />با طرب دارم و مرد طرب آرایت <br />با سماع خوش و با بربط و با نایت .<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(176384, 'طرب آشیان', '<span class=\"hlight\">طرب آشیان .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِ مرکب ) مکان سرور و طرب <span class=\"hlight\">:</span> <br />سِزَدَم چو ابر بهمن که بر این چمن بگریم <br />طرب آشیان بلبل بنگر که زاغ دارد.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(176385, 'طرب افزای', '<span class=\"hlight\">طرب افزای .</span> <font color=\"DarkGreen\"><b>[ طَ رَ اَ ]</font></b> (نف مرکب ) که طرب افزون کند. که شادی فزاید <span class=\"hlight\">:</span> <br />با سیه روی خوشدلی بهم است <br />طرب افزای سرخ روی کم است .<br /> <font color=\"Red\">سنائی .</font><br />هستند ببزم تو کمربسته قلم وار<br />بیجاده لبان طرب افزای تعب کاه .<br /> <font color=\"Red\">سوزنی .</font><br />رجوع به طرب فزای شود.<br /></font></div>'),
(176386, 'طرب انگیز', '<span class=\"hlight\">طرب انگیز.</span> <font color=\"DarkGreen\"><b>[ طَ رَ اَ ]</font></b> (نف مرکب ) که طرب انگیزد. طرب خیز.(آنندراج ). شادی و فرخ انگیز. نشاطآور <span class=\"hlight\">:</span> <br />مطربان طرب انگیز نوازنده نوا<br />ما نوازنده ٔ مدح ملک خوب خصال .<br /> <font color=\"Red\">فرخی .</font><br />مطرب آماده ٔ دردیست که خوش مینالد<br />مرغ عاشق طرب انگیز بود آوازش .<br /> <font color=\"Red\">سعدی .</font><br />غالب گفتار سعدی طرب انگیز است و طیبت آمیز. (گلستان ).<br />خاک مصر طرب انگیز نبینی که همان <br />خاک مصر است ولی بر سر فرعون و جنود.<br /> <font color=\"Red\">سعدی .</font><br />بهار و گل طرب انگیز گشت و توبه شکن <br />بشادی رخ گل بیخ غم ز دل برکن .<br /> <font color=\"Red\">حافظ.</font><br />برگیر شراب طرب انگیز و بیا<br />پنهان ز رقیب سفله بستیز و بیا.<br /> <font color=\"Red\">(منسوب به حافظ).</font><br /><BR><font color=\"Blue\">◄</font> (اِ مرکب ) سازی زهی . نام ذات اوتاری ایرانی که با کمان نوازند که چهار دسته و چهار کاسه دارد و هر دسته ای را پنج زه باشد. در فرانسوی نیز طرب انگیز گویند. رجوع به لاروس کبیر شود. قسمی ساز نواختنی .<br /></font></div>'),
(176387, 'طرب خانه', '<span class=\"hlight\">طرب خانه .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) طرب سرای . طرب گاه . جایگاه شادی و طرب <span class=\"hlight\">:</span> <br />روی خاکی و نم چشم مرا خوار مدار<br />چرخ فیروزه طربخانه ازین کهگل کرد.<br /> <font color=\"Red\">حافظ.</font><br />در زوایای طربخانه ٔ جمشید فلک <br />ارغنون ساز کند زهره به آهنگ سماع .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(176388, 'طرب خواستن', '<span class=\"hlight\">طرب خواستن .</span> <font color=\"DarkGreen\"><b>[ طَ رَ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ت َ]</font></b> (مص مرکب ) استطراب . (منتهی الارب ). شادی طلبیدن .<br /></font></div>'),
(176389, 'طرب خیز', '<span class=\"hlight\">طرب خیز.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (نف مرکب ) طرب انگیز. که طرب آورد. رجوع به طرب انگیز شود.<br /></font></div>'),
(176390, 'طرب سرا', '<span class=\"hlight\">طرب سرا.</span> <font color=\"DarkGreen\"><b>[ طَ رَ س َ ]</font></b> (اِ مرکب ) طربخانه .<br /></font></div>'),
(176391, 'طرب سرای', '<span class=\"hlight\">طرب سرای .</span> <font color=\"DarkGreen\"><b>[ طَ رَ س َ ]</font></b> (اِ مرکب ) طربخانه <span class=\"hlight\">:</span> <br />طرب سرای محبت کنون شود معمور<br />که طاق ابروی یار مَنَش مهندس شد.<br /> <font color=\"Red\">حافظ.</font><br />طرب سرای وزیر است ساقیا مگذار<br />که غیر جام می آنجا کند گرانجانی .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(176392, 'طرب سنج', '<span class=\"hlight\">طرب سنج .</span> <font color=\"DarkGreen\"><b>[ طَ رَس َ ]</font></b> (نف مرکب ) که طرب سنجد. شادی آزما <span class=\"hlight\">:</span> <br />بمیخانه از شام تا صبحدم <br />طرب سنج احیا چو اهل حرم .<br /><font color=\"Red\">ملاطغرا (از آنندراج ).</font><br /></font></div>'),
(176393, 'طرب شکار', '<span class=\"hlight\">طرب شکار.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (نف مرکب ) که شادی شکرد. که ایجاد طرب کند <span class=\"hlight\">:</span> <br />آن جام طرب شکار بر دستم نه <br />وآن ساغر چون نگار بر دستم نه .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(176394, 'طرب شیرازی', '<span class=\"hlight\">طرب شیرازی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ب ِ ]</font></b> (اِخ ) محمد رفیعخان بن ربیعخان . ضابط خفرک و مرودشت، از معارف عمال فارس و در شیراز مکرر صحبتش اتفاق افتاده، عاملی کامل و ضابطی کافی بوده . از اشعار اوست :<br />ز بیم انتقام وصل یاراز هجر خشنودم <br />که نتواند فلک یک لحظه هرگز با منت بیند.<br />چه غم از اینکه بود مایلت دل همه کس <br />خدا کند که نباشی تو مایل همه کس .<br />نمودم عجزی و گفتم شوم از عجز دمسازش <br />چه عجزی بودکافزودم از آن با خویشتن نازش .<br />گر قصد تو این نیست که از رشک بمیرم <br />گوئی ز چه بودم بر اغیار و نبودی .<br /><font color=\"Red\">(مجمعالفحصاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٤</span>).</font><br /></font></div>'),
(176395, 'طرب فزای', '<span class=\"hlight\">طرب فزای .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف َ ]</font></b> (نف مرکب ) طرب افزای . شادی و نشاط انگیز <span class=\"hlight\">:</span> خداوند حمی یوم غبی را به حکایتهای خنده ناک و بازیهای عجب والحان طرب فزای، دل خوش کند. (ذخیره ٔ خوارزمشاهی ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(176396, 'طرب نایینی', '<span class=\"hlight\">طرب نایینی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ب ِ ]</font></b> (اِخ ) اصفهانی . نامش میرزا محمدجعفر فرزند میرزا محمد حسین نائینی، برادر میرزا محمدمنشی باشی رحمةاﷲ علیه است . مولدش شهر اصفهان، در سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٢٢٣</span> هَ . ق . که موکب همایون حضرت خاقان صاحبقران فتحعلیشاه قاجار طاب ثراه بجانب عراق حرکت کرد، بتوسط فخرالمرسلین و المتکلمین ابوالمعالی معتمدالدوله میرزا عبدالوهاب نشاط اصفهانی رحمةاﷲ علیه سعادت حضور اعلی یافت و قصیده ای مدیحه معروض داشت و مطبوع افتاد و بتربیت وی اشارت رفت و بتوجه خاطر خطیر اعلی بشارت یافت و به تکمیل کمالات مأمور شد. در خدمت ملا محمدعلی عقدائی یزدی به صرف و نحو، منطق، معانی و بیان و تفسیر پرداخت و علوم حکمیه را در نزد ملا اسماعیل واحدالعین که واسطه ٔ عقد تلامذه ٔ جناب حکیم نوری ملاعلی بود تلمذ کرد، و از معالم ذوق و معرفت در جناب ملاولی اﷲ هزارجریبی که از کُمّلین عهد بود، حظهای موفور حاصل کرد و مراتب عروض و قوافی را از آقا محمد کاظم واله فراگرفت و طریقه ٔ انشاء را از کتاب وصاف اقتباس کرد و به اندک مدتی مستجمع فضائل آمده و در سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٢٢٥</span> هَ . ق . به طهران وارد شد و کتابی که بسوق و صاف نگاشته بود بنظر معتمدالدوله رسانید و پسند افتاد و در صحبت عم خود میرزا باقر ناظر بسلطانیه رفته و به ملازمت خدمات نواب شاهزاده معظم محمدولی میرزا حکمران یزد مخصوص آمد و در دیوان انشاء ریاست یافته تا غایت ایام ایالت در یزد بود، علی الجمله از نجبای عهد ومترسلین معاصرین بوده است و دیوانی مشتمل بر نظم و نثر عربی و فارسی و ترکی مسمی به خزینه ٔ طرب دارد که به سه حقه منقسم است و هر حقه محتوی بر پنج عقد و مفصلاً به نظر رسیده . از قصائد و غزلیات فارسی اوست :<br />در مدحت نواب نایب السلطنه عباس میرزا نوراﷲ مرقده :<br />فروزان گشت شمع ماه اندر محفل گردان <br />هزاران لعبت سیمین شد اندر یکزمان پیدا<br />به دامان فلک انجم چو اشک دیده ٔ وامق <br />به اوج آسمان مه همچو عکس عارض عذرا<br />میان باغ گلهای چمن با عارض نیکو<br />کنار جوی سروان سهی با قامت رعنا<br />گلستان آنچنان گردیده روح افزا و جان پرور<br />که گفتی شد شبیه بزم عیش زاده ٔ دارا<br />ولیعهد زمان شهزاده عباس آنکه مانندش <br />جلالتمند فرزندی نزایدمادر دنیا<br />زهی اسمش بفرمان مروت بهترین عنوان <br />خهی رسمش بتوقیع فتوت خوشترین طغرا<br />شد ار پیر و جوان از جان مطیع او عجب نبود<br />که او را رأی پیران حاصلست و طالع برنا.<br />در مدح ولیعهد مغفور مبرور گوید:<br />گرنه عکس رأی شاه کامکار است آفتاب <br />از چه رو مصباح بزم روزگار است آفتاب <br />قهرمان عباس شه کز رشک مهر رایتش <br />تا ابد چون ماه نو از غم نزار است آفتاب <br />گر شود در پرده ٔ مغرب نهان هر شب رواست <br />کز صفای رای دارا شرمسار است آفتاب <br />دست جودش تا به نَهب کان کمر بست استوار<br />از غم پروردگان در زینهار است آفتاب <br />ملک شه کیوان حصار استوارش آسمان <br />کوتوالی اندرین نیلی حصار است آفتاب <br />مطبخ احسان او را مرتفع دودیست چرخ <br />واندر آن دود مصعد یک شرار است آفتاب <br />راستی شه را یک از کند اوران باشداز آن <br />دائم از خط شعاعی نیزه دار است آفتاب .<br />در ستایش حضرت خاقان صاحبقران مغفور طاب ثراه :<br />بنامیزد بتی دارم سمن سیما و سیمین بر<br />سهی بالا و بزم آرا و روح افزای و جان پرور<br />لب و چشم و تن و زلف و قد و گیسوی مشکینش <br />عقیق و عبهر و عاج و عبیر و سرو و سیسنبر<br />مجاور روز و شب رخسار و زلف مشکفامش را<br />بهار زینت و زیب و شکنج و حلقه و چنبر<br />میان و ساعد و سرپنجه و چشمش خلاف هم <br />علیل و ناتوان و زورمند و فربه و لاغر<br />رخ زیباو خدِّ دلربای و لعل کام او<br />یکی خلد و یکی طوبی یکی حیوان یکی کوثر<br />جز آن هندوی خال و ترک چشم و غمزه ٔ جادو<br />بعهد شه که دیده رهزن و خونریز و غارتگر<br />خدیو قهرمان فتحعلی شاه آنکه میباشد<br />جهانگیر و جهان بخش و جهاندار و جهان داور.<br />ایضاً در لغز قلم :<br />بگو چیست آن عاشق زار لاغر<br />سرشکش روان دایم از دیده ٔ تر<br />گهی همچو سیمین بران مخطط<br />ز خط گرد رویش عیان مشک اذفر<br />دگر گاه چون منظر ساده رویان <br />تراشنده تیغش کند صاف منظر<br />بطفلی نمایش در آجام شیران <br />به پیری سرایش مکانی محقر<br />چو ماهش مکان است گاهی به گردون <br />چو ماهیش گه جا به بحر مدور<br />گهی هست در آب چون رود عمران <br />گهی هست در نار چون پور آزر<br />گهی جا بظلمات مانند خضرش <br />گهش جای بر تخت همچون سکندر<br />سخن چین و نمام و ساعی و واشی <br />فسونساز و غماز راز و فسونگر<br />خطش چون خط نوخطان خطائی <br />قدش چون قد سروقدان کشمر<br />اگر نیست مرتاض صافی ضمیری <br />چرا هست آگاه از سرمضمر<br />عجب آنکه هم ناقص است و هم اجوف <br />عجبتر که هم ابکم و هم سخنور<br />گهی هست در پویه و گاه ساکن <br />گهی هست آسوده و گاه مضطر<br />سخنگوی چون عاقلان سخندان <br />هنرپیشه چون کاملان هنرور.<br />از دیگر اشعار او:<br />مفشان بچهره زلف شب آسا خدای را<br />یکسان روا مدار چنین صبح و شام ما.<br />حلقه بر دل میزند غمهای دوست <br />گنج میجوید همی ویرانه را.<br />شمع را گو رخ نیفروزد چنین <br />چند منع از سوختن پروانه را.<br />فرصت لذت نداری از خدنگ دیگرم <br />ای خدنگ افکن بنازم زور بازوی ترا.<br />برای مدعی پر کرده گویا یار جام امشب <br />که جام دیده ام خالی نگردد از مدام امشب .<br />فاش ترسم کند آخر رخ زردم غم عشق <br />تا برد زردی او دیده ٔ خونبار کجاست <br />آنکه از تیغ جفا کشت طرب را و برفت <br />کاش میگفت دگر وعده ٔ دیدار کجاست .<br />ای قوم که سر منزلتان دجله ٔ آب است <br />گر دست من تشنه بگیرید ثواب است .<br />گر کند بلهوسی منع من از عشق چه باک <br />در نظر عشق من او را هوسی می آید.<br />سرمستی جاودان کسی راست <br />کان لعل لبان مکیده باشد<br />بیزار ز هرچه شادی آن دل <br />کز شهد غمت چشیده باشد<br />با دوست میسر است پیوند<br />آن را که ز خود بریده باشد<br />آن راست طرب که زیر تیغش <br />افتاده بخون طپیده باشد.<br />تو شکرفروش را گو که سر شکر بپوشد<br />که مگس نمیتواند که ببیند و نجوشد<br />سر قتل عام دارد نگهت ز فرط مستی <br />تو به این سیاه دل گو که می اینقدر ننوشد.<br />درد غم هجر تو بهرکس که بگفتم <br />از بهر هلاک من بیچاره دعا کرد.<br />آغاز خواب کرد که بیرون روم ز بزم <br />بیداریش نگر که چِسانم بخواب کرد.<br />فغان که میکشم اکنون جفای پادشهی <br />که درگهش ز جفاها مرا پناهی بود.<br />دلم پروانه سان هر شب از آن سوخت <br />که شمعش زینت هر محفلی بود<br />طرب را در میان اشک دیدم <br />غریقی در میان ساحلی بود.<br />زید چون زنده شمع دل که خوبان <br />عنانش را به دست باد دادند<br />امان صید دل را راه جستم <br />نشانم خانه ٔ صیاد دادند<br />لبم از شکوه گر بستند او را<br />زبان بیزبانی یاد دادند.<br />ناصح بنصیحت من و من <br />فریاد همی زنم که خاموش .<br />تو ازین چه چاره داری که گذر کنی بخاکم <br />ز نخست چون بدین شرط قرار شد هلاکم .<br />من طاقت هجران تو مه پاره ندارم <br />جز اینکه بمیرم به برت چاره ندارم <br />در پرده و بی پرده بود روی تو یکسان <br />از شرم چو من طاقت نظاره ندارم .<br />سر خاک شد براهت و خواهم که بعد ازین <br />در گوشه ای نشینم و خاکی بسر کنم .<br />چه رویست این که گرمن هر زمانش یک نظر بینم <br />هنوزم چشم آن باشد که یکبار دگر بینم .<br />فغان و ناله ام بیرحم تر کرد آن جفاجو را<br />غلط بود اینکه گفتم ناله ٔ بیحاصلی دارم .<br />لذت حسرت رویش نبرم تا با خویش <br />وقت مردن نه عجب آید اگر بر سر من .<br />به بالین زودتر آرید غمخواران طبیب من <br />که میترسم نگردد دیرتر وصلش نصیب من .<br />ساقیا از چه نه در جام شراب اندازی <br />کشت ما را نه ثوابست گر آب اندازی .<br />ساحلی لجه ٔ غم را نبود خوشتر از آنک <br />کشتی جام به دریای شراب اندازی .<br />باید دوباره در حشر مردن ز شرم قاتل <br />دزدیده زیر تیغش از دل کشیدم آهی <br />بهر ثبوت قتلم هستند گرچه خونخوار<br />عادلتر از دو چشمت نبود مرا گواهی .<br />آخر نه کم ای دوست ز دشنام و عتابی <br />صد نامه نویسم ندهی از چه جوابی <br />تفسیده جگر سوخته دل بر سر راهت <br />ای ابر عطا! منتظرم قطره ٔ آبی .<br />بر آتش آن رخ اگر ای زلف نه دودی <br />بر چشم ترم اینهمه اشک از چه فزودی ؟<br />غم ندانم ز چه در حلقه گرفته ست دلم را<br />گوئی آگاه نباشد که تواش نقش نگینی .<br /><font color=\"Red\">(مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>).</font><br /></font></div>'),
(176397, 'طرب همدانی', '<span class=\"hlight\">طرب همدانی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ب ِ هََ م َ ]</font></b> (اِخ ) هدایت آرد: نام شریفش میرزا یوسف، برادر کهتر میرزا ابوالقاسم همدانی و شیخ الاسلام آن شهر بوده، شاهزاده ٔ مغفور معظم دولتشاه طاب ثراه به وی مرحمتها میفرمود، و فاضلی دانشمند و دبیری بیمانند، در جودت طبع و حدت ذهن و استقامت سلیقه و بذله های دلکش و سخنان خوش مشهور، و در عهد دولت قطب السلاطین محمدشاه ثانی قاجار طاب ثراه رحلت نموده . از اشعار آن جناب است :<br />نه جان بهر نثار او نه تاب شرمساریها<br />پس از مردن نیایدکاش بر خاکم ز یاریها<br />مرابر روی او دیدن نباشد درخور طاقت <br />عبث با پرده دارم شکوه است از پرده داریها.<br />امیدوار وصل تو جان داد در فراق <br />تا کامیاب وصل ترا انتقام چیست .<br />حلقه بر در آشنا ناکرده در بگشاد دوش <br />گوئیا پنداشت آن ناآشنا بیگانه ام .<br />ای جرس رهبر ما گمشدگان چون نشوی <br />رهزنان را ز کمینگاه خبردار مکن .<br />جان من آب حیات از غم دهرت نرهاند<br />زینهار ار عوض باده دهندت نستانی .<br /><font color=\"Red\">(مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٤</span>).</font><br /></font></div>'),
(176398, 'طرب کردن', '<span class=\"hlight\">طرب کردن .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ک َ دَ ]</font></b> (مص مرکب ) شادی کردن . خوشدلی کردن . فیریدن <span class=\"hlight\">:</span> اگر داری طرب کن و اگر نداری طلب کن . (خواجه عبداﷲ انصاری ).<br />با دوست به خرگاه طرب کردن عشاق <br />خوشتر بود اکنون و طرب کردن گلزار.<br /><font color=\"Red\">امیرمعزی (از آنندراج ).</font><br /></font></div>'),
(176399, 'طربال', '<span class=\"hlight\">طربال .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) قریه ای است در بحرین . (معجم البلدان ). <BR><font color=\"Blue\">◄</font> مناره ای است در منجشانیه . یاقوت از ابن شمیل نقل کرده گوید: الطربال بناء یبنی علما للغایة التی یستبق الخیل الیها، منه ما هو مثل المنارة. و بالمنجشانیة و احد منها. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨</span>).<br /></font></div>'),
(176400, 'طربال', '<span class=\"hlight\">طربال .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) مناره ٔ بلند مبنی بر کوه . <BR><font color=\"Blue\">◄</font> هر بنای بزرگ و بلند . (منتهی الارب ) (آنندراج ). باره ٔ دیوار بلند. پاخسه بر بُن دیوار. <BR><font color=\"Blue\">◄</font> در میان شهر (فیروزآباد فارس ) آنجا که مثلاً نقطه ٔ پرگار باشد دکه ای انباشته برآورده است و نام آن ایران گرده و عرب آنرا طِربال گوید. (ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٣٨</span>). <BR><font color=\"Blue\">◄</font> هر پاره ای از کوه . <BR><font color=\"Blue\">◄</font> دیوار دراز در هوا. (منتهی الارب ) (آنندراج ). منه الحدیث : اذا مراحد کم بطربال مائل، فلیسرع المشی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سنگ بلند بزرگ در کوه . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> صومعه . (تفلیسی ). صومعه ٔ بلند. (آنندراج ) (غیاث اللغات ). صومعه ٔ بزرگ . (مهذب الاسماء). صومعه ٔ بزرگ ترسایان شام .<br /></font></div>'),
(176401, 'طربرود', '<span class=\"hlight\">طربرود.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِ مرکب ) گویا از ابزار موسیقی بوده است <span class=\"hlight\">:</span> <br />برسر سرو بانگ فاختگان <br />چون طربرود دلنواختگان .<br /> <font color=\"Red\">نظامی .</font><br />کدو برکشیده طربرود را<br />گلوگیر گشته به امرود را.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(176402, 'طربزون', '<span class=\"hlight\">طربزون .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) از معظم بلاد ارمنیةالاکبر است و از آنجا هر سال سه تومان بر سبیل خراج به ایران میدهند. و ارمنیةالاکبر داخل ایران است . (نزهة القلوب چ لیدن ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span>). رجوع به طرابزون شود.<br /></font></div>'),
(176403, 'طربلة', '<span class=\"hlight\">طربلة.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ل َ ]</font></b> (ع مص ) بالا انداختن کمیز را. یقال : طربل بوله طربلة؛ بالا انداخت کمیز را. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176404, 'طربنامه', '<span class=\"hlight\">طربنامه .</span> <font color=\"DarkGreen\"><b>[ طَ رَ م َ ]</font></b> (اِ مرکب ) نامه ای که از شادی و شوق حکایت کند. مکتوب حاکی از نشاط و سرور <span class=\"hlight\">:</span> <br />حافظ آن روز طربنامه ٔ عشق تو نوشت <br />که قلم بر سر اسباب دل خرم زد.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(176405, 'طربناک', '<span class=\"hlight\">طربناک .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ص مرکب ) شادمان . خوشحال . بانشاط: رجل ٌ مطراب ٌ؛ مرد طربناک . (منتهی الارب ).<br />این طربناکی و چالاکی او هست کنون <br />از موافق شدن دولت با بوالحسنا.<br /> <font color=\"Red\">منوچهری .</font><br />سال امسالین نوروز طربناکتر است <br />پار و پیرار همی دیدم اندوهگنا.<br /> <font color=\"Red\">منوچهری .</font><br />در طربناک میزبانی بخت <br />نهمت او عزیز مهمان باد.<br />گرچه این قصرها طربناک است <br />چون بگردون نمی رسد خاک است .<br /> <font color=\"Red\">اوحدی .</font><br />خیز و در کاسه ٔ زر آب طربناک انداز<br />پیشتر ز آنکه شود کاسه ٔ سر خاک انداز.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(176406, 'طربناک ساختن', '<span class=\"hlight\">طربناک ساختن .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ت َ ]</font></b> (مص مرکب ) خوشحال و مسرور کردن : شجاه شجواً؛ طربناک ساخت او را. (منتهی الارب ).<br /></font></div>'),
(176407, 'طربوزان', '<span class=\"hlight\">طربوزان .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِ) نوعی توتون سیگار.<br /></font></div>'),
(176408, 'طربوزان', '<span class=\"hlight\">طربوزان .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b>(اِخ ) رجوع به طرابوزان و طرابزون و طرابوزن شود.<br /></font></div>'),
(176409, 'طربگاه', '<span class=\"hlight\">طربگاه .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِ مرکب ) طربخانه . طرب سرای . محل شادی . جایگاه طرب <span class=\"hlight\">:</span> <br />خویشتن را زتنگنای دلم <br />به طربگاه دل براندازد.<br /> <font color=\"Red\">عرفی (از آنندراج ).</font><br />گوش مخالفش به طربگاه عافیت <br />مغز فغان شنیده ز نی های استخوان .<br /><font color=\"Red\">ملا طغرا (از آنندراج ).</font><br /></font></div>'),
(176410, 'طربیداس', '<span class=\"hlight\">طربیداس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (معرب، اِ) ابن سینا در ضمن بحث از تشریح حیوانات دریائی سخن را به طربیداس میکشاند که دارای جثه ای عظیم و پاهای بسیار است و طول پاهای آن را پنج ذراع مینویسد. رجوع به مقاله ٔ چهارم از فن هشتم کتاب الشفا چ تهران ص <span class=\"hlight\" dir=\"rtl\">٣٩٩</span> شود. این کلمه از طرپدو لاتینی است که فرانسویان از آن طرپی یا ترپی و ایتالیهائیها طرپیلا ساخته اند. و رجوع به طرپی شود.<br /></font></div>'),
(176411, 'طربیل', '<span class=\"hlight\">طربیل .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (معرب، اِ) نوره که بدان خرمن را کوبند. (منتهی الارب ) (آنندراج ). نورج . ابزار خرمن کوبی . این کلمه از لاتینی تریبولوم گرفته شده است .<br /></font></div>'),
(176412, 'طرتان', '<span class=\"hlight\">طرتان .</span> <font color=\"DarkGreen\"><b>[ طُرْ رَ ]</font></b> (ع اِ) تثنیه ٔ طرة. دو خط پشت خر و گاو دشتی که بر دو شانه باشد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176413, 'طرتقس', '<span class=\"hlight\">طرتقس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی سداب را گویند. (فهرست مخزن الادویه ).<br /></font></div>'),
(176414, 'طرتون', '<span class=\"hlight\">طرتون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) طرخون .(فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٥</span>). ظاهراً مصحف «طرخون » است .<br /></font></div>'),
(176415, 'طرث', '<span class=\"hlight\">طرث .</span> <font color=\"DarkGreen\"><b>[طِ ]</font></b> (ع اِ) کرانه ٔ تندی لب شرم زن . (منتهی الارب ) (آنندراج ). طرف ختنه گاه از شرم زن . (ترجمه ٔ قاموس ).<br /></font></div>'),
(176416, 'طرث', '<span class=\"hlight\">طرث .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) هر بنای تازه و نو. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176417, 'طرثمة', '<span class=\"hlight\">طرثمة.</span><font color=\"DarkGreen\"><b>[ طَ ث َ م َ ]</font></b> (ع مص ) سر فروافکندن . <BR><font color=\"Blue\">◄</font> خاموش بودن از خشم یا تکبر. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176418, 'طرثوث', '<span class=\"hlight\">طرثوث .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) گیاهی است باریک شاخ مایل به سرخی شیرین بار، خورده میشود. ج، طراثیث . (منتهی الارب ) (آنندراج ). بلغت یونانی میوه ای است که آن را به فارسی بل گویند و آن را طَراثیث نیز خوانند. (برهان ). شترغاز. (تفلیسی ). اشترغاز. (مهذب الاسماء). رافه .(دهار) (صراح در لفظ نقع). و شکوفه ٔ آن را نکعةالطرثوث نامند، و بر آن را ثعرور نامند. طراثیث است . (تحفه ٔ حکیم مؤمن ). صمغ آن را وشق و فارسیان وشک و قزاونه وشه خوانند و بعضی عجم کرم گویند. (نزهةالقلوب ).صمغ آن اشق یعنی لزاق الذهب است . رجوع به اشق شود. ترش . صمغ آن اشق است، و این صمغ را لزاق الذهب نیز نامند: هالوک ؛ نوعی از گیاه طرثوث است . (منتهی الارب ).<br /></font></div>'),
(176419, 'طرثیث', '<span class=\"hlight\">طرثیث .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) شهری کوچک است و به گرمی مایل، قاضی ابوبکر صاحب «شکر و شکایت » از آنجا است . (نزهةالقلوب چ اروپا ذیل بلاد غزنین ص <span class=\"hlight\" dir=\"rtl\">١٤٧</span>).<br /></font></div>'),
(176420, 'طرجالة', '<span class=\"hlight\">طرجالة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b>(اِخ ) حصنی است از حصون اقلیم بجایه در اسپانیا. (الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥</span>).<br /></font></div>'),
(176421, 'طرجد', '<span class=\"hlight\">طرجد.</span> <font color=\"DarkGreen\"><b>[ طَ ج َ ]</font></b> (اِخ ) دهی از دهستان اصفاک بخش بشرویه ٔ شهرستان فردوس، در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی شمال باختری بشرویه، سر راه مالرو عمومی بشرویه به زین آباد. دامنه و گرم، <span class=\"hlight\" dir=\"rtl\">٦٦</span> تن سکنه، آب آن از قنات و محصول آنجا غلات و پنبه و ارزن و میوه جات و پیله و تریاک . شغل اهالی زراعت و کرباس بافی و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176422, 'طرجلة', '<span class=\"hlight\">طرجلة.</span> <font color=\"DarkGreen\"><b>[ طَ ج َ ل َ ]</font></b> (اِخ ) شهر کوچکی است به اندلس از نواحی ریة. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨</span>).<br /></font></div>'),
(176423, 'طرجهالة', '<span class=\"hlight\">طرجهالة.</span> <font color=\"DarkGreen\"><b>[ طَ ج َ ل َ ]</font></b> (معرب، اِ) پنگانچه . کاسه ٔ خرد. (منتهی الارب ). طرجهارة. (آنندراج ). قیف . فنجانه . تکاو. طرجهارة. <BR><font color=\"Blue\">◄</font> نوعی از پنگانهای روئین است . (ذخیره ٔ خوارزمشاهی ). طرجهارة. این کلمه معرب «ترکهار» است . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>).<br /></font></div>'),
(176424, 'طرجهالی', '<span class=\"hlight\">طرجهالی .</span> <font color=\"DarkGreen\"><b>[ طَ ج َ ]</font></b> (ص نسبی، اِ) (غضروف ...) غضروفی است ازغضروفهای نای گلو، پیوسته به آن غضروف که نام آن لااسم له است . (بحر الجواهر). غضروف مکبی . (ذخیره ٔ خوارزمشاهی ). رجوع به مکبی (غضروف ...) شود. غضروفی است چون مکبه (سرپوش ) که بر سر چیزی نهند و طرجهاله نوعی از پنگانهاء روئین است و این را با غضروف لااسم له بند گشادی است و اندر مکبی دو مغاک است و از لااسم له دو زیادت بیرون داشته است به اندازه ٔ دو مغاک و هر دو زیادتند اندر هر دو مغاک نشسته، و آن را رباطی استوار است، و این مکبی بدین بند گشاد حرکت میکند و به غضروف درقی رسد... و مکبی بر سر درقی و لااسم له چون مکبه نهاده تا طعام بر پشت او بگذرد و به راه طعام فروشوداز بهر آنکه حلقوم که راه دم زدن و آواز دادن است اندر پیش نهاده است و مری که راه طعام و شراب است اندر پیش او نهاده است و طعام و شراب را بر پشت مکبی بباید گذشت تا به مری فرورود، هرگاه که مردم اندر طعام خوردن ناگاه سخنی بگوید، مکبه برداشته شود و حنجره باز شود، اگر چیزی در حلقوم افتد که راه دم زدن است قوت دافعه مردم را به سرفه آرد تا وقتی که آن چیز رانیز بدر اندازد و از بهر آنکه هرچه بر این راه فرورود وی را گذری دیگر نیست که بگذرد مگر که هم از این راه برآید، آفریدگار تبارک و تعالی مکبی را از بهر آن آفرید تا راه حنجره و حلقوم فروگرفته دارد تا چیزی اندر وی نیوفتد. (ذخیره ٔ خوارزمشاهی نسخه ٔ خطی مؤلف ص <span class=\"hlight\" dir=\"rtl\">١٨</span>). و در تشریح میرزا علی آمده : دو غضروف طرجهالی صغیر منشوری مثلث و عموداً بطرف خلف و فوقی حنجره ممتد و در آنها دیده میشود. سطح خلفی عریض مقعر و محل اتصال عضله ٔ طرجهالی است . سطح قدامی محدب مقابل عضله ٔ درقی طرجهالی و رشته ٔ صوت فوقانی است . سطح داخلی که از غشاء مخاطی حنجره مستور است . قاعده ٔ این غضروف به غضروف حلقوی پیوسته، زائده ٔ قُدّامی آن محل اتصال رشته ٔ صوت تحتانی و از وحشی زائده ٔ خلفیی دارد که محل اتصال عضله ٔ حلقوی طرجهالی طرفی و خلفی است . رأس که در آن دانه ٔ صغیر غضروفیی است که گاهی آزاد و گاهی به غضروف طرجهالی ملتئم و موسوم به غضروف قرنی یا دانه ٔ سانترینی است . (تشریح میرزا علی ص <span class=\"hlight\" dir=\"rtl\">٥٩٨</span>). فاعلم ان ّ داخل الفم منفذین، احدهما مجری الهواء، و اولها رأس الحنجرة من ثلاثة غضاریف، احدها الترس، مستدیر غیرتام و مقابله غضروف یعرف بالذی لااسم له، و الثالث یسمی الطرجهان (ظ: طرجهالة) ینطبق علیها عند الحاجة. (تذکره ٔ داود ضریر انطاکی ). و رجوع به ترس شود.<br /></font></div>'),
(176425, 'طرح', '<span class=\"hlight\">طرح .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع مص ) زشت گردیدن خوی :طرح طرحاً؛ زشت گردید خوی او. <BR><font color=\"Blue\">◄</font> نیک مرفه الحال شدن . فراخ عیش شدن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176426, 'طرح', '<span class=\"hlight\">طرح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) خُچ . درختی است که میوه ٔ آن قابل استفاده میباشد و از آن در جنگلهای ایران موجود است .<br /></font></div>'),
(176427, 'طرح', '<span class=\"hlight\">طرح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) انداختن : طرحه و طرح به ؛ انداخت او را. دور گردانیدن . (منتهی الارب ) (آنندراج ). بیوکندن . (زوزنی ). افکندن . بیرون انداختن . نبذ. ترک . واگذاشتن . بگذاشتن . گذاشتن . بینداختن . <BR><font color=\"Blue\">◄</font> گستردن . انداختن . پهن کردن . کناره گرفتن از کاری . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> و خواجه سخت بزرگ بودی در روزگار، اکنون خواجگی طرح شده است و این ترتیب گذشته است . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٥٣</span>). <BR><font color=\"Blue\">◄</font> فروختن جنسی بزور به رعایا. (غیاث اللغات و آنندراج هر دو از چراغ هدایت ). رسمی است مقرر که حکام ظالم جنس خود را قیمت افزوده به رعایا و زیردستان دهند. (غیاث اللغات و آنندراج هر دو از خیابان ). نام نوعی خراج که در پیش از قراء میگرفته اند. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>) <span class=\"hlight\">:</span> بسیار بره و مرغ بر خوان نهادی، چندانکه کسی از حشم نتوانستی خورد تا شاگردان مطبخ به بازار بردندی و به طرح بفروختندی، چنانکه هرچه به دیناری خریده بودی به درمی به بازار بفروختندی . (تاریخ سیستان ). ظالمی را حکایت کنند که هیزم درویشان خریدی به حیف و توانگران را دادی به طرح . (گلستان ). <BR><font color=\"Blue\">◄</font> انداختن حروف معجم یا مهمل است از شعر یا انشا به حیثیتی که آن حروف اصلاً در کلام نیاید و این سه قسم است : یکی معطل، و آن عطلت شعر و نثر است از حروف معجم به حیثیت مذکور. مثال از کلام میرزا بیدل :<br />علمها محو در اطوار رسوم <br />حاصل مردم عالم معلوم <br />همه را درس سلوک اطوار<br />کوک در درک حصول اسرار.<br />مثال نثر: «موارد الکلام سواطع الالهام » فیضی فیاضی است که نهایت شهرت دارد، و به از آن این صنعت دیگری را نداده اند. دوم منقوطه، مقابل معطل که قاطبةً الفاظ منقوطه در کلام آید و غیرمنقوطه اصلاً در کلام نباشد و این صنعت مشکلترین صنایع است . مثالش در نظم از میرزا بیدل :<br />بجنبش تیغزن چین جبینش <br />غضب پشتی نشین نقش چینش .<br />سوم ترک حرفی از حروف تهجی خواه معجم خواه مهمل . مثالش چند بیت از قطعه ٔ سلمان ساوجی که به حذف الف انشاء کرده :<br />صنعت صدر مسند دستور<br />میبرد زینت بهشت برین <br />میکند بخششت به بذل درم <br />همچو روی سپهر پشت زمین <br />شد ز روی تو پشت شرع قوی <br />شد به عدل تو حبل ملک متین .<br /> <font color=\"Red\">(از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> نزد محاسبان اطلاق میشود بر افکندن عدد کمتر نوبتی بعد از دیگری از عدد اکثر، چنانکه از اصطلاحات محاسبان مستفاد میگردد. (کشاف اصطلاحات الفنون ). افکندن عددی از دیگری، اگر عدد <span class=\"hlight\" dir=\"rtl\">٢٢</span> را چهار بار پنج پنج طرح کنی، دو ماند. <BR><font color=\"Blue\">◄</font> قائم کردن بنای مکان . (آنندراج ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> (اِ) انگاره . <BR><font color=\"Blue\">◄</font> شالوده . گرده . بیرنگ . اختطاط. نشان بنا برکشیدن . (زوزنی ). نمونه ٔ عمارت نو. <BR><font color=\"Blue\">◄</font> نقاشی . (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> و بمعنی صورت و پیکر مجاز است و با لفظ نگاشتن و زدن و افکندن و انداختن و افشاندن و ریختن و کشیدن و کردن مستعمل . (آنندراج ) <span class=\"hlight\">:</span> <br />نبود نقش دو عالم که رنگ الفت بود<br />زمانه طرح محبت نه این زمان انداخت .<br /> <font color=\"Red\">حافظ (دیوان چ قزوینی ص <span class=\"hlight\" dir=\"rtl\">١٣</span>).</font><br />بهار آنقدر بوستان طرح کرد<br />که نتوان چو اقسام گل شرح کرد.<br /> <font color=\"Red\">ملا طغرا.</font><br />زمان گرچه بس طرح مجلس کشید<br />به ترتیب بزم تو بزمی ندید.<br /> <font color=\"Red\">ظهوری .</font><br />خون ارباب وفا از خنجر بیداد ریز<br />خاکها گِل کن به خون، طرح بنای داد ریز.<br /> <font color=\"Red\">ظهوری .</font><br />در سینه طرح خلوت رازش فکنده ایم <br />فرش نیاز در ره نازش فکنده ایم .<br /> <font color=\"Red\">طالب آملی .</font><br />طرح خورشید رخت تا زده بر لوح وجود<br />چهره پرداز جهان بر سر ایجاد نرفت .<br /> <font color=\"Red\">طالب آملی .</font><br />ای خوش آن شب که بر سر کویش <br />طرح آه و فغان بیفشانی .<br /> <font color=\"Red\">طالب آملی (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> سرباری ؛ در تداول بقالان که هنگام خریدن کالا و خواربار از کشاورزان مقداری اضافه بر کالای وزن شده بر آن می افزایند. صاحب معالم القربه آرد: و اما الکیالون فلاخیر فیهم لاسیما فی هذا الزمان فان اکثرهم یکتال ما یقبضه زایداً و یسمی عندهم الغزر و الطرح . (معالم القربة ص <span class=\"hlight\" dir=\"rtl\">٨٦</span>). <BR><font color=\"Blue\">◄</font> مدد. نام فوجی است ورای میمنه و میسره و آن امداد و اعانت جمیع افواج است تا بهر فوجی که غنیم زور آورد به مدد برسد، از کتب تواریخ معلوم شد و سند آن در «شرباشران » گذشت . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرح دو کس با (به ) هم افتادن </span> ؛ کنایه از موافقت و دمسازی <span class=\"hlight\">:</span> <br />من این مرقع الوان بیفکنم روزی <br />که طرح رندی و تقوی به هم نمی افتد.<br /> <font color=\"Red\">نظیری نیشابوری (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرح ِ روی آب </span> ؛ کنایه از نقش بی ثبات . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرح سینه دادن </span> ؛ کنایه از سینه واکردن <span class=\"hlight\">:</span> <br />مطلب بجز شکستن بازار ماه نیست <br />خوبان که طرح سینه به مهتاب داده اند.<br /> <font color=\"Red\">سیدحسین خالص (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرح قانون </span> ؛ نوعی از اتوکشی که خطوط اتو مثل تار قانون دراز و بهم پیوسته باشد <span class=\"hlight\">:</span> <br />میان نغمه سنجان راز دل از پرده میگویم <br />فغان چون تار دارم از قبای طرح قانونش .<br /> <font color=\"Red\">مفید بلخی (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> پیشنهاد جمعی از نمایندگان به مجلسین (شوری و سنا) (آنچه را دولت پیشنهاد کند اصطلاحاً لایحه می گویند).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرح کلامی، یا طرح مسئله ای، یا طرح کردن مسئله ای را</span> ؛ به میان درافکندن سخنی یا مسئله ای را.<br /></font></div>'),
(176428, 'طرح', '<span class=\"hlight\">طرح .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع ص ) جای دور. <BR><font color=\"Blue\">◄</font> نیة طرح ؛ قصد دور و بعید. <BR><font color=\"Blue\">◄</font> افکنده شده . بمعنی مطروح . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) فضله . پلیدی <span class=\"hlight\">:</span> و من سقی شیئاً من طرح الاسد، بغض الشراب من ساعته . (ابن البیطار).<br /></font></div>'),
(176429, 'طرح', '<span class=\"hlight\">طرح .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) جای دور. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176430, 'طرح', '<span class=\"hlight\">طرح .</span> <font color=\"DarkGreen\"><b>[ طُرْ رَ ]</font></b> (ع ص ) مکان بعید. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176431, 'طرح افکندن', '<span class=\"hlight\">طرح افکندن .</span> <font color=\"DarkGreen\"><b>[ طَ اَ ک َ دَ ]</font></b> (مص مرکب ) پی افکندن . بنیاد نهادن <span class=\"hlight\">:</span> <br />پادشاهی که طرح ظلم افکند<br />پای دیوار ملک خویش بکند.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرح عمارت افکندن </span> ؛ بنیان نهادن بنا.<br />و رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">٢٣٩</span> شود.<br /></font></div>'),
(176432, 'طرح برداشتن', '<span class=\"hlight\">طرح برداشتن .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت َ ]</font></b> (مص مرکب ) نقل برداشتن، مثلاً خانه ای را دیده، مثل آن خانه ای سازند، گویند از خانه ٔ فلان کس طرح برداشته ایم <span class=\"hlight\">:</span> <br />ما صنمخانه ٔ عشقیم خلیلی باشد<br />که ز بتخانه ٔ ما طرح حرم بردارد.<br /><font color=\"Red\">سالک یزدی (از آنندراج ).</font><br /></font></div>'),
(176433, 'طرح بندی', '<span class=\"hlight\">طرح بندی .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (حامص مرکب ) نقشه کشی . نظم و ترتیب دادن خیابانها <span class=\"hlight\">:</span> طرح بندی خیابان اول در هندوستان نمودار شد والا در هندوستان پیش از این طرح بندی خیابان نبود. (تاریخ شاهی ص <span class=\"hlight\" dir=\"rtl\">١٢٠</span>).<br /></font></div>'),
(176434, 'طرح دادن', '<span class=\"hlight\">طرح دادن .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b> (مص مرکب ) رو گردانیدن . اعراض کردن . علامی فهامه در اکبرنامه نوشته : «مناسب دولت قاهره است که جنگ را طرح داده از آب نربده بگذریم و به هند نفسی راست کنیم و مردم تازه زور فراهم آوریم ». و بمعنی اول مسیح کاشی گوید <span class=\"hlight\">:</span> <br />داو نخست هر دو جهان باختم ولی <br />در نرد عشق طرح به لیلاج میدهیم .<br />گر به گلشن کند آن سرو پریچهر خرام <br />سنبلستان به چمن طرح دهد گیسویش .<br /> <font color=\"Red\">محسن تأثیر (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> در بازی شطرنج، طرح دادن، یا طرح کردن، عبارت است از در کنار نهادن و معزول از عمل کردن حریف قوی یک یا چند از سواران خود را تا حریف ضعیف با او برابری تواند کرد و بیشتر این کار برای تحقیر حریف کنند <span class=\"hlight\">:</span> واضع آن <font color=\"DarkGreen\"><b>[ یعنی شطرنج ]</font></b> به اسرار جبر و قدر سخت بینا بوده است و از کار تقدیر آفریدگار و تدبیر آفریدگان آگاه، آن را بنهاد و در نهادن آن فرانمودکه صاحب آن عمل با غایت چابک دستی و به بازی و زیرک دلی، اگرچه رخی یا فرسی بر خصم طرح دهد، شاید که به وقت باختن از آن حریف کنددست بدباز نادان، بازیی آید که دست خصم را فروبندد و در مضیقی افتد که هیچ چاره جز دست بازچیدن و به قائم ریختن نداند. (مرزبان نامه ).و رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">٤٤</span> شود.<br /></font></div>'),
(176435, 'طرح ریختن', '<span class=\"hlight\">طرح ریختن .</span> <font color=\"DarkGreen\"><b>[ طَ ت َ ]</font></b> (مص مرکب ) نقشه کشیدن . پی ریزی کردن . پی افکندن . طرح ریزی نمودن .<br /></font></div>'),
(176436, 'طرح ریزی', '<span class=\"hlight\">طرح ریزی .</span> <font color=\"DarkGreen\"><b>[طَ ]</font></b> (حامص مرکب ) پی ریزی . رجوع به طرح ریختن شود.<br /></font></div>'),
(176437, 'طرح فروش', '<span class=\"hlight\">طرح فروش .</span> <font color=\"DarkGreen\"><b>[ طَ ف ُ ]</font></b> (نف مرکب ) خوب صورت و زیبا و زیباپیکر، از عالم ِ نازفروش . (آنندراج ) <span class=\"hlight\">:</span> <br />برد سودای مه طرح فروشی بازم <br />عشق او ورزم و طرح دگری اندازم .<br /><font color=\"Red\">سیفی (از آنندراج ).</font><br /></font></div>'),
(176438, 'طرح فروچیدن', '<span class=\"hlight\">طرح فروچیدن .</span> <font color=\"DarkGreen\"><b>[ طَ ف ُ دَ ]</font></b> (مص مرکب ) طرح چیزی فروچیدن ؛ بساط آن را درنوردیدن . به کنار گذاشتن آن را <span class=\"hlight\">:</span> <br />چو عرفی با خیال آن صنم خوش عشرتی دارم <br />برو جای دگر ای غم فروچین طرح صحبت را.<br /><font color=\"Red\">عرفی (از آنندراج ).</font><br /></font></div>'),
(176439, 'طرح کردن', '<span class=\"hlight\">طرح کردن .</span> <font color=\"DarkGreen\"><b>[ طَ ک َ دَ ]</font></b> (مص مرکب ) فکندن . افکندن . دور انداختن <span class=\"hlight\">:</span> و او مأمون را فرا آن آورد که رایات سیاه و لباس سیاه طرح کرد و رایات و لباس سبز کرد. (کتاب النقض ص <span class=\"hlight\" dir=\"rtl\">٤١٧</span>). <BR><font color=\"Blue\">◄</font> به زور و تکلف دادن <span class=\"hlight\">:</span> <br />در غنای است جهان از کرم او که زکات <br />عامل از عجز همی طرح کند بر ایتام .<br /> <font color=\"Red\">انوری (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> طرح ریختن . طرح افکندن . بنای چیزی انداختن . (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(176440, 'طرح کش', '<span class=\"hlight\">طرح کش .</span> <font color=\"DarkGreen\"><b>[ طَ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) مغلوب . زبون . <BR><font color=\"Blue\">◄</font> مصور. نقاش . (آنندراج ) <span class=\"hlight\">:</span> <br />سالک همیشه طرح کش عشق ظالمم <br />آن جان و دل که میدهم امروز باج نیست .<br /> <font color=\"Red\">سالک قزوینی .</font><br />وصال شاهد معنی بوقت خود دریاب <br />مباش طرح کش نظم آبدار عبث .<br /> <font color=\"Red\">میرزا رضی دانش (از آنندراج ).</font><br />و رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">٤٣</span> شود.<br /></font></div>'),
(176441, 'طرحان', '<span class=\"hlight\">طرحان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) موضعی است نزدیک ضَیْمَرَة. (منتهی الارب ). محلی است در ارض جبل و بین آن و صیمره پلی بس شگفت آور و دو برابر پل حُلوان است . (معجم البلدان ). موضعی نزدیک صیمره به نواحی بصره، نام محلی در <span class=\"hlight\" dir=\"rtl\">٨٠٠٠٠</span>متری خرم آباد.<br /></font></div>'),
(176442, 'طرحة', '<span class=\"hlight\">طرحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (ع اِ) چادر. (منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span> <br />گل از شقه ٔ غنچه پیوسته خندان <br />چو از طرحه ٔ مهد یکروزه کودک .<br /> <font color=\"Red\">؟ (از جنگی خطی مورخ بسال <span class=\"hlight\" dir=\"rtl\">٦٤١</span>هَ . ق .).</font><br /><BR><font color=\"Blue\">◄</font> طیلسان ایرانیان . (فرائدالدریة).<br /></font></div>'),
(176443, 'طرحسمین', '<span class=\"hlight\">طرحسمین .</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (معرب، اِ) کبسیکج است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176444, 'طرحشقوق', '<span class=\"hlight\">طرحشقوق .</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (معرب، اِ) الهندباء. (تذکره ٔ داود انطاکی ص <span class=\"hlight\" dir=\"rtl\">٢٣٨</span>). کاسنی . رجوع به طرخشقون شود.<br /></font></div>'),
(176445, 'طرحفی', '<span class=\"hlight\">طرحفی .</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (ع اِ) شمع است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176446, 'طرحماطیقون', '<span class=\"hlight\">طرحماطیقون .</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (معرب، اِ) نوعی از سرمه است . (اختیارات بدیعی ). اسم کحلی است . (تحفه ٔحکیم مومن ). به یونانی بمعنی شیاف ُالعین است و شیافات عین در مرکبات مذکور شد و بمعنی کحل نیز آمده است . (فهرست مخزن الادویه ). و رجوع به طرخماطیقون شود.<br /></font></div>'),
(176447, 'طرحوم', '<span class=\"hlight\">طرحوم .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص ) دراز. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> آب ِ رنگ و مزه برگشته .(منتهی الارب ). آب برگردیده رنگ و مزه . (آنندراج ).<br /></font></div>'),
(176448, 'طرخ', '<span class=\"hlight\">طرخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) مخفف ِ اصطرخ (اصطخر). تالاب . اصطرخ آب . (مهذب الاسماء) <span class=\"hlight\">:</span> <br />بدان تا نهند از بَرِ چاه چرخ <br />کشند آب از چاه چندی به طرخ .<br /> <font color=\"Red\">فردوسی .</font><br />رجوع به فهرست ولف و فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٢</span> و طرخة شود.<br /></font></div>'),
(176449, 'طرخ آباد', '<span class=\"hlight\">طرخ آباد.</span> <font color=\"DarkGreen\"><b>[طَ ]</font></b> (اِخ ) دهی است به جرجان . (منتهی الارب ). بلده ای به جرجان . قریه ای است از قراء جرجان و شاید طرخ نام کسی که آن را بنا کرده بوده است . (معجم البلدان ).<br /></font></div>'),
(176450, 'طرخ آبادی', '<span class=\"hlight\">طرخ آبادی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص نسبی ) منسوب به طرخ آباد که از قرای جرجان است . (سمعانی ).<br /></font></div>'),
(176451, 'طرخان', '<span class=\"hlight\">طرخان .</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) ترخان . اسم است مر رئیس شریف را.(منتهی الارب ). شریف . (مفاتیح العلوم خوارزمی ). رئیس شریف در قوم خویش . و آن لغت خراسانی است . (تاج العروس از ملا علی قاری ). سرکرده و مرد بزرگوار و این لفظخراسانی است و جمع آن طراخنه . (شرح قاموس قزوینی ). <BR><font color=\"Blue\">◄</font> آنکه پادشاهان قلم تکلیف از وی بردارندو بر گناه او را مؤاخذه نکنند. لغت خراسانی است . (منتهی الارب ) (آنندراج ) (برهان ). ظاهراً اصل کلمه ترکی است و طرخان معرب ترخان است . رجوع به برهان قاطع چ معین ذیل «ترخان » شود. <BR><font color=\"Blue\">◄</font> سالار پنجهزار مرد. (تاج العروس ). مرتبه ای از مراتب سپاهیان روم بعداز مرتبه ٔ بطریق، و طرخان رئیس پنجهزار تن است . (مفاتیح العلوم خوارزمی ). <BR><font color=\"Blue\">◄</font> پادشاه ترکستان .(لغت فرس ). پادشاه ترکان بود. (اوبهی ) <span class=\"hlight\">:</span> <br />کنون باشد که برخوانم به پیش شعرتو اندر <br />هرآنچه تو به خاقانان و طرخانان و خان کردی .<br /> <font color=\"Red\">مجلدی گرگانی (از لغت فرس ).</font><br /> <BR><font color=\"Blue\">◄</font> نام عام امرای سمرقند. <BR><font color=\"Blue\">◄</font> قومی از ترکان را نیز طرخان گویند. (برهان ) (آنندراج ) <span class=\"hlight\">:</span> در قلعه ٔباب الابواب آن روز هزار مرد بودند از طرخانان که خاقان ایشان را آنجا گذاشته بود، مسلمه ایشان را نیازردو به حصین شد. (ترجمه ٔ طبری بلعمی ). خاقان چون روی مسلمه بدید روی به طرخانان و مبارزان کرد و گفت : اگرما امروز بر ایشان دست نیابیم هرگز نیابیم، پس طرخانی بیرون آمد با خیلی بزرگ و روی به مسلمانان نهاد. (ترجمه ٔ طبری بلعمی ). سعید از بردع به بیلقان شد و آنجا فرودآمد، مردی از روستا بیامد و گفت : اصلح اﷲ الامیر، من مردی ام محنت رسیده، سخن من بشنوید، آنکه بارجیک بن خاقان جراح را بکشت، طرخانی ازآن ِ خود بدین روستاها فرستاد، و او یاران خویش را اندر این دیه ها بپراکند و دختران مرا بگرفت و ببرد. (ترجمه ٔ بلعمی ). و رجوع به نزهةالقلوب چ لیدن ص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرخان خاقان </span> ؛ لقب پادشاهان ناحیت خزران بوده است . (حدود العالم ). لقب پادشاه خزران بوده که مستقرش آتل نام داشته .<br /><BR><font color=\"Blue\">◄</font> نوعی از سبزی خوردنی هم هست . (برهان ) (آنندراج ). و آن را طرخون هم گویند. رجوع به طرخون شود.<br /></font></div>'),
(176452, 'طرخان', '<span class=\"hlight\">طرخان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) لقب حمیدبن ابی حمید طویل است . (منتهی الارب ).<br /></font></div>'),
(176453, 'طرخان', '<span class=\"hlight\">طرخان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام قهرمانی تورانی در شاهنامه . (فهرست ولف ) <span class=\"hlight\">:</span> <br />سرافراز طرخان بیامد دوان <br />بدین روی دژ با یکی ترجمان .<br /> <font color=\"Red\">فردوسی .</font><br />به طرخان چنین گفت کای سرفراز<br />برو تیز بالشکر رزم ساز.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(176454, 'طرخان', '<span class=\"hlight\">طرخان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) والد سلیمان تیمی است . (منتهی الارب ). رجوع به ابوالمعتمر سلیمان شود.<br /></font></div>'),
(176455, 'طرخان', '<span class=\"hlight\">طرخان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ )نام پدر فیلسوف بزرگ ابومحمدبن طرخان فارابی است .<br /></font></div>'),
(176456, 'طرخان', '<span class=\"hlight\">طرخان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام پدر محمد حافظ بیکندی است .<br /></font></div>'),
(176457, 'طرخان', '<span class=\"hlight\">طرخان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام پدر ابوالینبغی عباس از قدیمترین شاعران ایران که در قرن دوم میزیسته است . رجوع به ابوالینبغی در احوال و اشعار رودکی تألیف سعید نفیسی ج <span class=\"hlight\" dir=\"rtl\">٣</span> و فهرست تاریخ ادبیات صفا شود.<br /></font></div>'),
(176458, 'طرخان', '<span class=\"hlight\">طرخان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نیزک طرخان پادشاه بادغیس بوده و در حدود <span class=\"hlight\" dir=\"rtl\">٨٧</span> هَ . ق . که قتیبه با پادشاه شومان صلح کرد نیزک طرخان بعضی اسرا از تازیان نزد خود داشت و قتیبه بدو نوشت و آن اسرا را بخواست و او را در نامه ٔ خود بیم داد. نیزک ازاو بهراسید و آن اسرا را رها کرد و نزد قتیبه فرستاد. رجوع به احوال و اشعار رودکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٧</span> و <span class=\"hlight\" dir=\"rtl\">٢٦٦</span> شود <span class=\"hlight\">:</span> و هم در این سال (<span class=\"hlight\" dir=\"rtl\">٨٧</span> هَ . ق .) قتیبه صلح کرد با طرخان ملک ترک . (ترجمه ٔ طبری بلعمی ).<br /></font></div>'),
(176459, 'طرخانی', '<span class=\"hlight\">طرخانی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص نسبی ) منسوب به طرخان که نام یکی از اجداد صاحب این نسبت است . (سمعانی ).<br /></font></div>'),
(176460, 'طرخسمی', '<span class=\"hlight\">طرخسمی .</span> <font color=\"DarkGreen\"><b>[ طَ خ َ ]</font></b> (معرب، اِ) به یونانی طرسیمی است، و آن هندباء است . (فهرست مخزن الادویه ). ظاهراً این کلمه هم تحریفی از طرخشقون باشد. رجوع به طرخشقون شود.<br /></font></div>'),
(176461, 'طرخشفوق', '<span class=\"hlight\">طرخشفوق .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ش َ ]</font></b> (معرب، اِ) رجوع به طرخشقون شود.<br /></font></div>'),
(176462, 'طرخشقوس', '<span class=\"hlight\">طرخشقوس .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ش َ ]</font></b> (معرب، اِ) رجوع به طرخشقون شود.<br /></font></div>'),
(176463, 'طرخشقوق', '<span class=\"hlight\">طرخشقوق .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ش َ ]</font></b> (معرب، اِ) رجوع به طرخشقون شود.<br /></font></div>'),
(176464, 'طرخشقون', '<span class=\"hlight\">طرخشقون .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ش َ ]</font></b> (معرب، اِ) طرشقون . هندبای بَرّی است . رجوع به هندبا شود. (از مفردات ابن البیطار). دزی گوید: کلمه ٔ مزبوربه صورتهای : طرخشقوق و طلحشقوق و طرشقوق نیز آمده است . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>). و حکیم مؤمن نیز ذیل طرخشقوق و طرشقون آرد: نام هندباء بَرّی است . (تحفه ). و صاحب ذخیره ذیل طرخشقوق آرد: کاسنی دشتی باشد. (ذخیره ٔ خوارزمشاهی نسخه ٔ خطی ). کسنه (کاسنی ) را به تازی هندبا گویند، بوستانی باشد و دشتی باشد و دشتی را طرخشقوق گویند. (ذخیره ٔ خوارزمشاهی ). و در اختیارات بدیعی ذیل طرخشقوق آمده است : و طرشقوق نیز گویند و هندبای بَرّی بود. و صاحب مخزن الادویه نیز همین معنی را ذیل دوکلمه ٔ مزبور آورده است . و صاحب برهان ذیل طرخشقون آرد: کاسنی صحرائی را گویند و آن را طرخشقوق هم گفته اند که بجای نون قاف باشد. و صاحب آنندراج ذیل طرخشقون آرد: هندبای بَرّی است . و در بعضی کتب طرخشقوس آمده است . و رجوع به طرشقون و طرخشقوق و طلخشقوق شود.<br /></font></div>'),
(176465, 'طرخف', '<span class=\"hlight\">طرخف .</span> <font color=\"DarkGreen\"><b>[ طِ خ ِ ]</font></b> (ع اِ) مسکه ٔتنک که روان باشد. <BR><font color=\"Blue\">◄</font> مسکه ٔ هیچکاره و بدترین مسکه ها. طرخفة مثله . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176466, 'طرخفة', '<span class=\"hlight\">طرخفة.</span> <font color=\"DarkGreen\"><b>[ طِ خ ِ ف َ]</font></b> (ع اِ) مسکه ٔ هیچکاره . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176467, 'طرخماطیقون', '<span class=\"hlight\">طرخماطیقون .</span> <font color=\"DarkGreen\"><b>[ طَ خ َ ]</font></b> (معرب، اِ) شیافاتی است که در بیماری جرب چشم بکار دارند. و رجوع به طرحماطیقون شود.<br /></font></div>'),
(176468, 'طرخوران', '<span class=\"hlight\">طرخوران .</span> <font color=\"DarkGreen\"><b>[ طَ خ ُ ]</font></b> (اِخ ) فَم و طرخوران از معظمات دهات تفرش است، هوایش معتدل است و آبش از چشمه ها و کاریز که از آن کوهها برمیخیزد و ارتفاعاتش پنبه و غله و میوه بود و اکثر اوقات آنجا ارزانی بود و مردم آنجا شیعی اثناعشری اند. حقوق دیوانیش ششهزار دینار است . (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٦٨</span>). و در فرهنگ جغرافیائی ایران آمده است : نام یکی از بخشهای چهارگانه ٔ شهرستان اراک . این بخش از شمال به بخش نوبران ساوه و از طرف خاور و جنوب خاوری به بخش دستجرد شهرستان قم و از طرف جنوب و باختر به بخش فرمهین شهرستان اراک محدود است . بطور کلی منطقه ای است کوهستانی . هوای دهستانهای تفرش، آشتیان و نقاط مرتفع سردسیر سالم و کناررودخانه ٔ قره چای حدود دهستان رودبار معتدل است . این بخش از <span class=\"hlight\" dir=\"rtl\">٣</span> دهستان بنام تفرش، آشتیان، رودبار تشکیل شده . جمع قراء بخش <span class=\"hlight\" dir=\"rtl\">٨٣</span> آبادی بزرگ و کوچک و جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">٤٥</span> هزار نفر است . مرکز بخش قصبه ٔ طرخوران واقع در مرکز دهستان تفرش میباشد. از راه شوسه ٔ قم به اراک در حدود صالح آباد جزء دهستان راهجرد راه فرعی آشتیان منشعب پس از عبور از آشتیان و گرکان از طریق گردنه ٔ نقره کمر به طرخوران منتهی و همه روزه اتومبیل رفت و آمد مینماید. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(176469, 'طرخوران', '<span class=\"hlight\">طرخوران .</span> <font color=\"DarkGreen\"><b>[ طَ خ ُ]</font></b> (اِخ ) قصبه ٔ مرکز بخش طرخوران و دهستان تفرش شهرستان اراک، <span class=\"hlight\" dir=\"rtl\">٧٢</span>هزارگزی شمال خاوری اراک . کوهستانی، سردسیر خوش آب و هوا. مختصات جغرافیائی آن بدین شرح است : طول <span class=\"hlight\" dir=\"rtl\">٥٠</span> درجه و <span class=\"hlight\" dir=\"rtl\">٢٠</span> ثانیه و عرض <span class=\"hlight\" dir=\"rtl\">٣٤</span> درجه و <span class=\"hlight\" dir=\"rtl\">٤٠</span> دقیقه و <span class=\"hlight\" dir=\"rtl\">٣٠</span> ثانیه . <span class=\"hlight\" dir=\"rtl\">١٩٨٠</span> متر از سطح دریا مرتفعتر است . جمعیت قصبه <span class=\"hlight\" dir=\"rtl\">٥٧٥٠</span> تن . آب آن از <span class=\"hlight\" dir=\"rtl\">١٢</span> رشته قنات . محصول آنجا غلات و انواع میوه جات و صیفی . شغل مردان زراعت و جزئی گله داری و کسب و نجاری . اکثر مردان برای تأمین معاش به تهران رفته و برمیگردند. صنایع دستی زنان قالیچه بافی . ادارات بخشداری، بهداری، پست و تلفن و آمار بخش در این قصبه قرار دارد و در حدود <span class=\"hlight\" dir=\"rtl\">٥٠</span> باب دکاکین مختلف و دبستان دارد. بوسیله ٔ تلفن با اراک و ساوه و تهران مربوط است . مزارع مبارک آباد، بادقوچی، منصورآباد جزء این قصبه است . تاریخ تعمیر مسجد قدیمی آن <span class=\"hlight\" dir=\"rtl\">١٢٦٠</span> هَ . ق . است و زیارتگاهی نیز دارد. از طریق گردنه ٔنقره کمر، گرکان، آشتیان به اراک و تهران راه شوسه دارد. این راه در صالح آباد به شوسه ٔ قم و اراک متصل میگردد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>) <span class=\"hlight\">:</span> <br />حرکت مشکل است بر بنده <br />گرچه از فَم به طرخوران باشد.<br /><font color=\"Red\">؟</font><br /></font></div>'),
(176470, 'طرخوران', '<span class=\"hlight\">طرخوران .</span> <font color=\"DarkGreen\"><b>[ طَ خ ُ ]</font></b> (اِخ ) دهی جزء دهستان حومه ٔ بخش مرکزی شهرستان ساوه، در <span class=\"hlight\" dir=\"rtl\">٩٠٠٠</span>گزی جنوب ساوه . جلگه، معتدل، مالاریائی . <span class=\"hlight\" dir=\"rtl\">٧٠</span> تن سکنه دارد. آب آن از رودخانه ٔ وفرقان . محصول آنجا غلات، پنبه، بنشن . شغل اهالی زراعت، گله داری و جاجیم و گلیم بافی و راه آن مالرو است . این ده قشلاق چند خانوار از ایل شاهسون بغدادی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(176471, 'طرخولی', '<span class=\"hlight\">طرخولی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) طرخون است . (فهرست مخزن الادویه ). رجوع به طرخون شود.<br /></font></div>'),
(176472, 'طرخون', '<span class=\"hlight\">طرخون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) گیاهی است، معرب ترخ، بیخ ریشه های آن عاقرقرحا است، قاطع شهوت است . (منتهی الارب ). گفته اند که عاقرقرحا بیخ طرخون کوهی است . (ذخیره ٔ خوارزمشاهی ). کوهیش را عاقرقرحا خوانند. (نزهةالقلوب ). ابوعلی در مفردات قانون گوید: گویند عاقرقرحا ریشه ٔ طرخون جبلی است . نباتی است که اصل عروق آن عاقرقرحا باشد. علفی است که عاقرقرحا بیخ آن است . (برهان ) (آنندراج ). رجوع به عاقرقرحا شود. تره ای است بشکل تره ٔ میره، ارجانی گوید که او گرم است و خشک در دو درجه و در معده دیر هضم شود و تریها را که در مزاج معده مانده باشد خشک کند و ناپدید گرداند، و چنین گفته اند که عاقرقرحا بیخ طرخون کوهی است . (صیدنه ). به شیرازی طرخونی گویند، و نیکوترین آن بستانی تازه بود و طبیعت آن گرم و خشک بود در دویم و در وی قوتی مخدر بود. ابن ماسویه گوید: گرم و خشک بود در وسط درجه ٔ سیم، و گویند سرد است، مجفف رطوبات بود و نشف تری بکند و قلاع را نافع بود، چون بخایند و زمانی نیک دردهان نگاه دارند و چون بخایند پیش از خوردن داروی مسهل کریه طعم آن احساس نکند بسبب تخدر و معده را قوت دهد و درد حلق آورد و دشوار هضم شود و قطع شهوت باه بکند، تشنگی آورد و مصلح وی کرفس بود، از بهر آنکه منع ضرر آن بکند و زود بگذراند و هضم کند. تمیمی گوید: آب آن با آب رازیانه در شراب هندی کنند که آن را شراب کاوی و کدر گویند و بیاشامند منع آبله و حصبه کند خاصه آب طرخون این فعل میکند و منع حدوث علل وبا میکند. (اختیارات بدیعی ). به فارسی ترخوانی نامند و از سبزیهای معروف است و بیخ بری او عاقرقرحا است، درسیم گرم و خشک و مجفف و مقوی معده و مخدر و مغیر ذائقه و مشهی و خوشبوکننده ٔ دهان و محلل ریاح و اخلاط لزجه و مفتح سدد و مصلح هوای وبائی و طاعون و خائیدن وی جهت قلاع نافع و اکثار آن محرق خون و قاطع باه و مصلح آن بقول بارده و مخدر و مخشن سینه و مصلحش عسل وبطی ءالهضم و مصلح آن کرفس است و مقوی فعل او رازیانه است . (تحفه ٔ حکیم مؤمن ). و رجوع به تذکره ٔ داود انطاکی و مفردات ابن بیطار شود. <BR><font color=\"Blue\">◄</font> نوعی ازسبزی خوردنی هم هست . (برهان ). ترخون . ذعلوق . (مهذب الاسماء). ازنبیژ (؟). (السامی فی الاسامی ص <span class=\"hlight\" dir=\"rtl\">١٠١</span>). نام سبزیی است خوشبوی . ریحانی، یعنی اسپرمی است که با نان خام خورند و در طعامها نیز کنند. غرمانوش . رُعْلول . ترخان . تلخون . و آن بر دو گونه است : بابلی و رومی، بابلی برگهای دراز و رومی برگهای گرد دارد. <BR><font color=\"Blue\">◄</font> در سراج نوشته که بید سرخ است . (آنندراج ) (غیاث اللغات ). و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٥</span> شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(176473, 'طرخون', '<span class=\"hlight\">طرخون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ )لقب عام ملوک سمرقند. (الاَّثار الباقیه چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٠١</span>). نام ملک سغد. رجوع به طرخان شود <span class=\"hlight\">:</span> و از آنجا ما را نامه ای نوشتند، به ملک طرخون . (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٤٩٠</span>). در ماوراءالنهر... هر خاندانی لقبی و عنوان سلطنتی داشته که تمام افراد آن خاندان بدان مشهور بوده اند چنانکه پادشاهان کش «بندون » و پادشاهان فرغانه «اخشید» و... پادشاهان سمرقند «طرخون » و... نامیده میشدند . (از احوال و اشعار رودکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٦</span>). نام ملک سغد. صاحب تاریخ بخارا آرد (ص <span class=\"hlight\" dir=\"rtl\">٥٢</span>، <span class=\"hlight\" dir=\"rtl\">٥٧</span>): و این حیان مردی بزرگ بود و باقدر، به خراسان رفت و میان قتیبةبن مسلم و طرخون ملک سغد بوقتی که قتیبه کافران را بدر بخارا در میان گرفته بود صلح انداخت . و رجوع به احوال و اشعار رودکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٨٦</span> و ص <span class=\"hlight\" dir=\"rtl\">٢٤٢</span> و <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> و <span class=\"hlight\" dir=\"rtl\">٢٥١</span> و <span class=\"hlight\" dir=\"rtl\">٢٦٢</span> و <span class=\"hlight\" dir=\"rtl\">٢٦٧</span> شود.<br /></font></div>'),
(176474, 'طرخونی', '<span class=\"hlight\">طرخونی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص نسبی ) منسوب به طرخان که نام یکی از اجداد صاحب این نسبت است . (سمعانی ).<br /></font></div>'),
(176475, 'طرد', '<span class=\"hlight\">طرد.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع مص ) مروسیدن به شکار. (منتهی الارب ). خوی گرفتن به شکار. شکارکردن . <BR><font color=\"Blue\">◄</font> دور کردن . طَرْد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) بچه ٔ زنبور عسل . (ذیل اقرب الموارد از اللسان ). <BR><font color=\"Blue\">◄</font> دسته ٔ زنبور عسل . <BR><font color=\"Blue\">◄</font> پرواز بچه های زنبور عسل . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤</span>).<br /></font></div>'),
(176476, 'طرد', '<span class=\"hlight\">طرد.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) آمدن قوم را و درگذشتن از ایشان . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> راندن . دور کردن . (منتهی الارب ) (تاج المصادر بیهقی ) (اقرب الموارد). و استعمالش اکثر در گریزانیدن هوام باشد مانند مگس و زنبور و موش و پشه و مار. (آنندراج ). <BR><font color=\"Blue\">◄</font> نفی کردن سلطان کسی را از شهر خویش . (اقرب الموارد). اخراج . اطراد. تبعید. دفع. ذود. ذیاد. تذوید. ظأف <span class=\"hlight\">:</span> <br />نمی بینی که ابلیسیت خودبین <br />پدید آمد سزای طرد و نفرین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />امیرابوالمظفر نصر، به طرد سواد و حصد فساد ایشان قیام نمود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٦٦</span>). فریغون ابن محمد را با چهل علم از افراد امراء، به طرد سواد و حصد فساد او فرستاد. (ترجمه ٔ تاریخ یمینی خطی ص <span class=\"hlight\" dir=\"rtl\">١٩١</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرد وحش </span> ؛ راندن حیوانات وحشی .<br /> <BR><font color=\"Blue\">◄</font> اجرا کردن خلاف در مسئله . (ذیل اقرب الموارد از مصباح ). <BR><font color=\"Blue\">◄</font> فراهم آوردن شتران از اطراف و نواحی آن . یقال : طردت الابل طرداً؛ اذا ضممتها من نواحیها. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> مقابل عکس . رجوع به طرد و عکس شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرداً للباب </span> ؛ بر حسب موقع. به مناسبت کار پیش . (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرد علت </span> ؛ علت را به تمام معلومات آن مطرد کردن . (اصول فقه ).<br /><BR><font color=\"Blue\">◄</font> کلمه ٔ طرد در اصطلاح اصول فقه، گاهی در باب معرف و گاه در باب علل استعمال می شود.اما در قسمت نخستین صاحب التلویح در تعریف اصول فقه گوید: طرد صدق کردن محدود بر چیزی است که حد بر آن بطور مطرد کلی صدق کند و این معنی گفتار اصولیان است که میگویند: هرچه در حد یافت شود در محدود نیز هست و اطراد مانع دخول غیرمحدود در حد میشود، اما عکس رابعضی بر حسب مفهوم عرفی آن بکار برده اند چنانکه گویند: هر انسانی خندان است و بعکس عرفی یعنی هر خندانی انسان است و در هر انسانی حیوان است عکس صدق نمیکندیعنی هر حیوانی انسان نیست . و بنا بر اینکه گویند: هرچه حد بر آن صدق کند محدود نیز بر آن صدق کند عکس آن این است که هرچه محدود بر آن صدق کند حد نیز بر آن صدق خواهد کرد. پس طرد حکمی کلی است نسبت به محدودبر حد و عکس حکمی کلی است نسبت به حد بر محدود. و برخی آن را چنین تفسیر کرده اند که عکس اثبات نفی است و بنابراین هرچه حد را نفی کند محدود را نیز نفی کندیعنی هرچه بر آن صدق نکند محدود هم بر آن صدق ننماید. پس عکس حکمی کلی است نسبت به آنچه محدود نباشد حدهم نیست و حاصل هر دو تعبیر یکی است و آن این است که حد بطور کلی جامع افراد محدود است - انتهی . اما ازنظر دوم یعنی طردی که در باب علل بکار میرود عبارت از دوران است . رجوع به دور شود. و آن را اطراد و طردو عکس نیز مینامند. رجوع به طرد و عکس شود. (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> (اِ) طرد بن ؛ کیسه ٔبزرگ قهوه . <BR><font color=\"Blue\">◄</font> طرد بضاعه ؛ بسته ٔ بزرگ مال التجاره . <BR><font color=\"Blue\">◄</font> در مصر نام پارچه ای ابریشمی بوده است . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>).<br /></font></div>'),
(176477, 'طرد', '<span class=\"hlight\">طرد.</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (ع ص ) آب باران به بول ستوران آمیخته از کثرت آمد و شد آنها. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176478, 'طرد و عکس', '<span class=\"hlight\">طرد و عکس .</span> <font color=\"DarkGreen\"><b>[ طَ دُ ع َ ]</font></b> (ترکیب عطفی، اِ مرکب ) طرد و عکس این است که سخنی را به ترتیبی برانند و آنگاه آن را معکوس کنند، چنانکه گویند: هر آتشی گوهری تابنده و سوزنده است و هر گوهری تابنده و سوزنده آتش است . (از تاج العروس ). در نزد اصولیان دوران است . (از کشاف اصطلاحات الفنون ). رجوع به دورشود. <BR><font color=\"Blue\">◄</font> در تداول علمای معانی از انواع اطناب زیاده است و آن چنان است که دو سخن آرند بدانسان که منطوق سخن نخستین مفهوم دوم را بیان کند و برعکس، مانند این آیه : «لایعصون اﷲ ما امرهم و یفعلون ما یؤمرون » . و آیه ٔ «لیستأذنکم الذین ملکت ایمانکم و الذین لم یبلغوا الحلم منکم ثلاث مرات » تا «لیس علیکم ولا علیهم جناح بعدهن » که منطوق امر به استیذان در این اوقات خاصه ای است که مفهوم عدم گناه را در خبر آن مقرر میدارد و بالعکس و گویند در برابر این نوع اطناب در ایجاز نوع اختباک است . و این گفتار صاحب اتقان در نوع ایجاز و اطناب است و فایده ٔ طرد و عکس تنصیص بر حکم مفهوم از سخن نخستین و تصریح بدان است . و بعضی از اهل معانی این را بر عکس اطلاق کنند و در جامعالصنایع گوید: طرد و عکس ؛ این صنعت چنان است که سخنی را به ترتیبی براند بعده بازگرداند. مثاله (شعر):<br />حسن ابروت ماه نو دارد<br />نه، که ابروت حسن ماه نو است .<br />و آنکه در اصطلاح گویند: «کلام الملوک ملوک الکلام » هم از این قبیل است - انتهی کلامه . و همچنین است این مثال : عادات السادات، سادات العادات . (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> جامعیت و مانعیت . جامع مانع در تعریف . <BR><font color=\"Blue\">◄</font> رو و وارو.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خواندن به طرد و عکس </span> ؛ چنانکه هست یا وارونه خواندن . بعضی طلاب در قدیم الفیه ٔ ابن مالک و نصاب ابونصر فراهی را به طرد وعکس از بر داشتند، یعنی هم از اول تا ته مرتب میخواندند، و هم از آخر تا به اول .<br /></font></div>'),
(176479, 'طرد کردن', '<span class=\"hlight\">طرد کردن .</span> <font color=\"DarkGreen\"><b>[ طَ ک َ دَ ]</font></b> (مص مرکب ) راندن . دور کردن . نفی کردن . رجوع به طرد شود.<br /></font></div>'),
(176480, 'طردان', '<span class=\"hlight\">طردان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) دانه ٔ کوچک سیاهی که در میان گندم یافت میشود. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤</span>).<br /></font></div>'),
(176481, 'طردجرد', '<span class=\"hlight\">طردجرد.</span> <font color=\"DarkGreen\"><b>[ طَ ج ِ ]</font></b> (اِخ ) از معظم قراء ساوه است . (نزهةالقلوب چ اروپا ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٣</span>).<br /></font></div>'),
(176482, 'طردسة', '<span class=\"hlight\">طردسة.</span> <font color=\"DarkGreen\"><b>[ طَ دَ س َ ]</font></b> (ع مص ) استوار کردن . محکم ساختن . (منتهی الارب ) (آنندراج ): طردسه طردسةً؛ استوار و محکم ساخت وی را. (منتهی الارب ).<br /></font></div>'),
(176483, 'طردغادوطس', '<span class=\"hlight\">طردغادوطس .</span> <font color=\"DarkGreen\"><b>[ طَ دَ غا طِ ]</font></b> (معرب، اِ) به یونانی عصفورالسباع و عصفورالشوکة را نیزنامند و آن عصفوری است کوچک . (فهرست مخزن الادویة).<br /></font></div>'),
(176484, 'طردغلوطیقی', '<span class=\"hlight\">طردغلوطیقی .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b> (معرب، اِ) رجوع به طرغلودیس شود.<br /></font></div>'),
(176485, 'طردوقولا', '<span class=\"hlight\">طردوقولا.</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (معرب، اِ) غری الجلود است . (فهرست مخزن الادویة).<br /></font></div>'),
(176486, 'طردیة', '<span class=\"hlight\">طردیة.</span> <font color=\"DarkGreen\"><b>[ طَ دی ی َ ]</font></b> (ع اِ) شعر درباره ٔ شکار. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤</span>).<br /></font></div>'),
(176487, 'طردیس', '<span class=\"hlight\">طردیس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) یکی از ملوک روم که یک سال پادشاهی کرد. (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(176488, 'طردیلن', '<span class=\"hlight\">طردیلن .</span> <font color=\"DarkGreen\"><b>[ طُ ل ُ ]</font></b> (معرب، اِ) سیسالیوس است . (فهرست مخزن الادویه ) (تحفه ٔ حکیم مؤمن ). و رجوع به طرذیلون شود.<br /></font></div>'),
(176489, 'طردیلون', '<span class=\"hlight\">طردیلون .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (معرب، اِ) رجوع به طردیلن شود.<br /></font></div>'),
(176490, 'طردیمن', '<span class=\"hlight\">طردیمن .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی کاشم است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176491, 'طردین', '<span class=\"hlight\">طردین .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) طعامی است مر اکراد را. (منتهی الارب ).<br /></font></div>'),
(176492, 'طرذیلون', '<span class=\"hlight\">طرذیلون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به لغت یونانی انگدان باشد، و آن درختی است که صمغ آن انگوزه است و بعضی انگوزه را نیز طرذیلون خوانند که حلتیت باشد. (برهان ). سیسالیوس است . (اختیارات بدیعی ) (تحفه ٔحکیم مؤمن ). طُردیلُن . طُردیلون . انجدان . انگژه .<br /></font></div>'),
(176493, 'طرر', '<span class=\"hlight\">طرر.</span> <font color=\"DarkGreen\"><b>[ طُ رَ ]</font></b> (ع اِ) ج ِ طُرّة. موی پیشانیها. <BR><font color=\"Blue\">◄</font> کرانه های هر چیز و وادیها. <BR><font color=\"Blue\">◄</font> نقوش جامه . <BR><font color=\"Blue\">◄</font> کناره های بام . (غیاث اللغات ) (آنندراج ) (در دیوان خاقانی چ عبدالرسولی ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>لفظ طرر بمعنی دیگری آمده و آن مصحف است و تحقیق آن در ضمن شرح معنی طزر آمده است . رجوع به طزر شود).<br /></font></div>'),
(176494, 'طرز', '<span class=\"hlight\">طرز.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) هیئت و شکل چیزی . (منتهی الارب ). جوالیقی آرد: فارسی معرب است . عرب میگوید طرز فلان طرز نیکی است ؛ یعنی زی و هیئت او. و این کلمه در جید هر چیز بکار برده شده است . رؤبة گوید: فاخترت من جید کل شی ٔ. (المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٤</span>). <BR><font color=\"Blue\">◄</font> خوب از هر چیزی . <BR><font color=\"Blue\">◄</font> طور و طریقه . (آنندراج ). قاعده . روش . (برهان ). مؤلف آنندراج آرد: وبا لفظ نمودن و ریختن و آموختن مستعمل <span class=\"hlight\">:</span> <br />چشمت به فسون بسته غزالان ختن را<br />آموخته نطق نگهت طرز سخن را.<br /> <font color=\"Red\">کلیم (از آنندراج ).</font><br />شیوه . طریقه ای در عمل . طراز. نمط. اسلوب .طریق . سان . گونه . گون . لون . ترتیب <span class=\"hlight\">:</span> البته هیچ سوی من <font color=\"DarkGreen\"><b>[ احمدبن ابی دواد ]</font></b> ننگریست <font color=\"DarkGreen\"><b>[ افشین ]</font></b>، فراایستادم، و از طرزی دیگر سخن پیوستم . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٧١</span>). سلوک کن بر طبق ستوده تر اطوار خود، و راه نماینده تر اخلاق خود...، و کریمتر طرزهای خود، در رعایت آنچه ما آن را در نظر تو زینت داده ایم . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣١٣</span>). ازآن ِ این خداوند از آن طرز است، سود نخواهد داشت . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٦٣٠</span>). ج، طرز، طروز، اطراز. <BR><font color=\"Blue\">◄</font> قلاب دوزی . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>). <BR><font color=\"Blue\">◄</font> در رشته کشیدن مروارید. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>). <BR><font color=\"Blue\">◄</font> خانه ٔ بدرازا. ازهری گوید: معرب از فارسی ترز. خانه ٔ تابستانی . و نیز رجوع به طزر و فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span> و <span class=\"hlight\" dir=\"rtl\">١٦٧</span> شود. <BR><font color=\"Blue\">◄</font> در اصطلاح بلغا مقصدی را گویند از مقاصد نظم که به صفتی ازاوصاف نظم مخصوص گردانیده باشند، و این را طریق نیزگویند و جمله ٔ طرزها نُه طرز باشند: اول طرز حکیمانه، و آن طرز حکیم سنائی است، مشکل و مشتمل بر مواعظ و تشبیه و امثال و معرفت سلوک و متعلقات آن و کلام اوجامع است و خوب . دوم طبعانه، و آن طرز خاقانی است، و تعریف آن غلو در مشکلات نظم است، چنانچه اغلاقات و اغراقات و تشبیهات بدیع و تحمیلات لطیف و کنایات و تصویرات غریب و عبارات لائقه . سوم فاضلانه، و آن طرز انوری است . و این طرز مشتمل است بر الفاظ معتبر به استغراق و بلاغت و ابداع علوی است معتبر. چهارم مترسلانه، وآن طرز ظهیر فاریابی است و عبارت است از تصرفات در ایهام ذوالمعنیین و تشبیهات نو و اغراقات بلیغ. پنجم محققانه، و آن طرز عبدالواسع جبلی است . و تعریف آن ملایمت و جزالت است در ایراد مطابقات و مشابهات و تقسیمات و تفسیرات و تفصیل الفاظ و سیاقت . ششم ندیمانه، و آن طرز فردوسی و نظامی است، مشتمل بر بیان قصص و حکایات و تواریخ و فصاحت معانی بدیع و تشبیهات عجیب .هفتم عاشقانه، و آن طرز سعدی است و آن حاوی ملایمت وذوق است . هشتم خسروانه، و آن طرز حضرت امیرخسرو دهلوی است و آن جامع جمیع لطائف نظم و محتوی تمام کمالات سخن است . نهم باحفصانه، و آن کلامی است مشتمل بر الفاظی که آنها را در استعمال مهجور داشته اند و گفته اندکه اگر زبان پخته ٔ فارسی را از الفاظ عربی چاشنی دهند، اگر گوارا بود مترسلانه خوانند و اگر ناگوار آید باحفصانه خوانند. و حضرت امیرخسرو دهلوی فرموده که دانش پنج است، و آن چون پنج گنج حکیمانه و فاضلانه و عاشق خوش طبعانه و شاعرانه یک ثمره اند. و محققانه و مدققانه را شاعرانه گفته اند. و ندیمانه ٔ خوب طبعانه را نام نهاده اند. کذا فی جامعالصنایع. (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(176495, 'طرز', '<span class=\"hlight\">طرز.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع مص ) صورت گرفتن سپس ثِخانت وسطبری . <BR><font color=\"Blue\">◄</font> نیکخوی گردیدن سپس زشتخوئی . (منتهی الارب ) (آنندراج ). خوش خلق شدن . <BR><font color=\"Blue\">◄</font> لباس پسندیده و فاخر پوشیدن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176496, 'طرز', '<span class=\"hlight\">طرز.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی از بخش راور شهرستان کرمان، در <span class=\"hlight\" dir=\"rtl\">٣٨</span>هزارگزی شمال باختری راور، کنار راه فرعی کوهبنان به راور. کوهستانی سردسیر با <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> تن سکنه . آب آن از چشمه و محصول آنجا غلات و تریاک و پنبه و شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(176497, 'طرزیدن', '<span class=\"hlight\">طرزیدن .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b>(مص ) بمعنی طرازیدن است . (فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span>).<br /></font></div>'),
(176498, 'طرس', '<span class=\"hlight\">طرس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) محو کردن . <BR><font color=\"Blue\">◄</font> حک ساختن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> وزش . رجوع به دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٨</span> ذیل طاروش شود.<br /></font></div>'),
(176499, 'طرس', '<span class=\"hlight\">طرس .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) نامه . <BR><font color=\"Blue\">◄</font> صحیفه ای که محو کرده باز بر آن نویسند. (منتهی الارب ) (آنندراج ). کاغذ. ج، اَطراس، طروس : اقام الناس ببغداد سنین لایکتبون الا فی الطروس، لأن الدواوین نهبت فی ایام محمدبن زبیدة، و کانت فی جلود، فکانت تمحا و یکتب فیها. (ابن الندیم ).<br /></font></div>'),
(176500, 'طرسا', '<span class=\"hlight\">طرسا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) نوعی از بلوط است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176501, 'طرستوج', '<span class=\"hlight\">طرستوج .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (معرب، اِ) نوعی از ماهی دریائی باشد. گویند خوردن آن شبکوری ببرد. (برهان )(آنندراج ). ترستوج نیز گویند، و آن ماهی دریائی بود، و به یونانی طریقلا خوانند، و اهل آندلس آن را مل نامند. دیسقوریدس گوید: ادمان خوردن وی کردن، شبکوری آورد و باریکی چشم آورد. و چون بشکافند و بر گزندگی تنّین بحری و عقرب و عنکبوت نهند شفا یابد. (اختیارات بدیعی ). معرب ترستوج است، به یونانی طریغلا نامند وبه عجمی اندلس مل، و آن صنفی از ماهی بحری است که آدمیان را اکل آن مورث شبکوری و غشاوه ٔ چشم است . (فهرست مخزن الادویة). ترستوج . درستوج . طریغلا. مل . مول . ورجوع به حیوةالحیوان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٣</span> و دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span> شود.<br /></font></div>'),
(176502, 'طرسمة', '<span class=\"hlight\">طرسمة.</span> <font color=\"DarkGreen\"><b>[ طَ س َ م َ ]</font></b> (ع مص ) سر فروبردن . <BR><font color=\"Blue\">◄</font> برگردیدن از جنگ و جز آن . (منتهی الارب ) (آنندراج ). و رجوع به طلسمة شود.<br /></font></div>'),
(176503, 'طرسمین', '<span class=\"hlight\">طرسمین .</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (اِخ ) نام ادریس علیه السلام : و او <font color=\"DarkGreen\"><b>[ ادریس ]</font></b> در میان یونانیان به طرسمین و ارمس مشهور است . (حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(176504, 'طرسن', '<span class=\"hlight\">طرسن .</span> <font color=\"DarkGreen\"><b>[ طُ س ُ ]</font></b> (اِخ ) طرسن بیک . مورخ عثمانی . وی فتح قسطنطینیه را مشاهده کرد و در حملات سلطان محمد دوم در جنگ ضد روملی شرکت جسته است . او راست : تاریخی ابوالفتح (<span class=\"hlight\" dir=\"rtl\">١٤٩٧</span> م .) که در آن، تاریخ محمد دوم و بایزید دوم را گرد آورده است . (اعلام المنجد).<br /></font></div>'),
(176505, 'طرسنه', '<span class=\"hlight\">طرسنه .</span> <font color=\"DarkGreen\"><b>[ طَ س َ ن َ ]</font></b> (ع اِ) رجوع به طراشنه شود.<br /></font></div>'),
(176506, 'طرسوج', '<span class=\"hlight\">طرسوج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) سیسالیوس است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(176507, 'طرسوس', '<span class=\"hlight\">طرسوس .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (اِخ ) شهری است مر مسلمانان را که بسیار ارزانی و فراخ سالی دارد، در دست ارامنه بود، باز در دست مسلمانان افتاد. (منتهی الارب ) (آنندراج ). نام شهری به ساحل بحرالشام، واقع در جنوب شرقی آسیةالصغری، نزدیک مرسین . شهری از ترکیه بر ساحل سیحون به مغرب اذنه و این موطن قدیس بلس حواری است، دارای <span class=\"hlight\" dir=\"rtl\">٢٢</span> هزار سکنه .<br />شهری است <font color=\"DarkGreen\"><b>[ به شام ]</font></b> بزرگ و آبادان و بانعمت، گرد وی دو باره است از سنگ و مردمان جنگی دلاور. (حدود العالم ). یاقوت از صاحب الزیج نقل کرده گوید: طول طرسوس <span class=\"hlight\" dir=\"rtl\">٥٨</span> درجه و نیم، و عرض آن <span class=\"hlight\" dir=\"rtl\">٣٦</span> درجه و ربع است . از اقلیم چهارم است . این شهر بنام طرسوس بن الروم بن الیفزبن سام بن نوح علیه السلام نامیده شده، برخی گفته اند بانی این شهر سلیمان نامی از خدام هارون الرشید بوده و آن را بسال یکصد و نود و اند هجری قمری بنا کرده است، و این گفتار احمدبن محمد الهمدانی است . (ابن الفقیه ). طرسوس از ثغور شام و بین انطاکیه و حلب و بلادالروم واقع است . احمدبن الطیب السرخسی گوید: از مصیصة به آهنگ عراق کوچ کردیم، نخست بسوی اذنة، و از اذنة به طرسوس که شش فرسنگ بود روان شدیم، بین راه اذنة و طرسوس، فندق (مهمانسرا) بغا و فندق جدید واقع است . طرسوس دارای دو حصار است و خندقی وسیع و شش دروازه دارد، نهر بردان شهر را دو نیمه کرده و از وسط آن میگذرد، قبر مأمون عبداﷲبن الرشید هم در آنجاست . هنگامی که بقصد غزای رومیان بدان شهر ورود کرد، مرگش فرارسید. شاعری در این باب گفته :<br />هل رأیت النجوم اغنت عن الماء-<br />مون فی عز ملکه الماسوس <br />غادروه بعرصتی طرسوس <br />مثل ما غادروا اباه بطوس .<br />این شهر همواره جایگاه صلحا و زهاد بود از این رو که از سرحدهای بلاد اسلام شمرده میشد، و تا سال <span class=\"hlight\" dir=\"rtl\">٣٥٤</span> هَ . ق . نیز مسلمانان در آن شهر به نیکوترین حالی میزیستند، ولی بر اثر تجاوز و حملات نقفور از سلاطین روم شرقی که نخست بر مصیصه و سپس بر طرسوس تاخت آورد، و به قلع و قمع ریشه ٔ مسلمانی و مسلمانان پرداخت، مسلمانان طرسوس تاب مقاومت نیاورده، جمع کثیری از آنان جلای وطن اختیار کردند. (نقل به اختصار از معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> صص <span class=\"hlight\" dir=\"rtl\">٣٥</span> - <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br />حمداﷲ مستوفی گوید: طرسوس از اقلیم سوم است و از توابع شام، عمر عبدالعزیز مروانی ساخت، و بعد از خرابی هارون الرشید تجدید عمارتش کرد، و آن را بارو کشید. هوایش معتدل است و به گرمی مایل . ارتفاعش غله و میوه باشد. (نزهةالقلوب چ اروپا ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٠</span>). و غار اصحاب کهف در کوهی به حدود طرسوس بوده . (نزهةالقلوب چ اروپا ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٩</span>). شهر معروف و مشهوری است که مسقطالرأس پولس حواری بود (کتاب اعمال رسولان <span class=\"hlight\" dir=\"rtl\">٩</span>:<span class=\"hlight\" dir=\"rtl\">١١</span>، و <span class=\"hlight\" dir=\"rtl\">٣٠</span> و <span class=\"hlight\" dir=\"rtl\">١١</span>:<span class=\"hlight\" dir=\"rtl\">٢٥</span> و <span class=\"hlight\" dir=\"rtl\">٢١</span>:<span class=\"hlight\" dir=\"rtl\">٣٩</span> و <span class=\"hlight\" dir=\"rtl\">٢٢</span>:<span class=\"hlight\" dir=\"rtl\">٣</span>) و در کیلیکیای که در آسیای صغیر است واقع میباشد، و طرسوس بر ساحل وسیعی که به مسافت <span class=\"hlight\" dir=\"rtl\">١٢</span> میل به بحر متوسط و کوه طوروس مسافت دارد واقع میباشد، و در قدیم الایام بر دو طرف رود سدنس واقع بوده است، لکن باید دانست که مجرای رود مسطور تغییر یافته است، و سابق در دهنه ٔ رود مذکور بندری بوده که اجناس و مال التجاره ٔ بسیاری در آنجا وارد میشده است . و برخی بر آنند که ترشیش مذکور در کتاب مقدس همان طرسوس است . گویند مؤسس و بانی طرسوس سردناپالس بوده است، و در وقتی که در میانه ٔ اهالی جنگی روی داد، اسباب خرابی طرسوس گردید و از آن پس اغسطوس آنجا را شهر رومانی خوانده و میدانهای وسیع از برای بازی قرار داد، و مدرسه ای تأسیس کرد و بعد از اطینا و اسکندریه، طرسوس شهر سومین بود که در تمام دنیا معروف گشت، و برای خانواده ٔ امپراطور معلمان و مؤدبان از این شهر تعیین میشد. و پولس نه تنها در شهری که برای تجارت معروف بود تعلیم یافت بلکه در علوم و فنون معروفه ٔ آن زمان شهرت تام داشت، و همواره از آن وقت تا به حال به طرسوس موسوم است، لکن در این روزها شهر کوچکی شده که عدد نفوسش در زمستان سی هزار و در تابستان از چهارصد الی پانصد و متجاوز از اهالی به ییلاقات میروند چونکه گرما شدت میکند. (قاموس کتاب مقدس ). و صاحب المنجد آرد: شهری است در ترکیه (قیلیقیا)، دارای <span class=\"hlight\" dir=\"rtl\">٢٢٠٠٠</span> تن سکنه . سابقاً در زمره ٔ مراکز و پایتختها بشمار میرفته است . پولس قدیس در آن متولد شده است . این شهر را مأمون بسال <span class=\"hlight\" dir=\"rtl\">٧٨٨</span> م . فتح کرده و در آن مدفون شده است . ورجوع به تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">١٨٣</span> و مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٣٥٥</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٦</span> - <span class=\"hlight\" dir=\"rtl\">٣٥٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٨٠</span>، <span class=\"hlight\" dir=\"rtl\">٤٥٣</span>، <span class=\"hlight\" dir=\"rtl\">٤٧٣</span> و عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٤</span> و عیون الاخبار ابن قتیبة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦٥</span> و ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span> والتفهیم ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span> و <span class=\"hlight\" dir=\"rtl\">٣٣٥</span> و ضحی الاسلام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span> و ترجمه ٔتاریخ ادبیات براون ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩٩</span> و تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٧٨</span> و <span class=\"hlight\" dir=\"rtl\">٣١٦</span> و تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span> و کامل ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٩</span> شود.<br /></font></div>'),
(176508, 'طرسوس', '<span class=\"hlight\">طرسوس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (قضاء...) شهرستانی است در سوریه (ساخلو لاذقیه )، مرکز آن طرسوس است و <span class=\"hlight\" dir=\"rtl\">٣٠٦٧٦</span> تن سکنه دارد، بر ساحل است و جزیره ٔ ارواد مقابل آن واقع است . عبادةبن صامت آن را بسال <span class=\"hlight\" dir=\"rtl\">٦٣٨</span> م . فتح کرده است، سپس صلیبیان آن را بسال <span class=\"hlight\" dir=\"rtl\">١٠٩٩</span> م . تصرف کرده و کلیسای سلطنتی که هم اکنون نیز باقی است در آن بنیان نهاده اند. (اعلام المنجد).<br /></font></div>'),
(176509, 'طرسوسی', '<span class=\"hlight\">طرسوسی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (ص نسبی ) منسوب به شهر طرسوس است که از شهرهای مرزی شام است . (سمعانی ).<br /></font></div>'),
(176510, 'طرسوسی', '<span class=\"hlight\">طرسوسی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (اِخ ) او راست : کشف القناع عن مسألةالسماع . السراج الوهاج . ردالنصاری . (کشف الظنون ).<br /></font></div>'),
(176511, 'طرسوسی', '<span class=\"hlight\">طرسوسی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (اِخ ) ابراهیم بن عمادالدین حنفی . بسال <span class=\"hlight\" dir=\"rtl\">١٣٤٥</span> م . در دمشق سمت قضاء حنفی را داشته است و در حدود <span class=\"hlight\" dir=\"rtl\">١٣٥٦</span> م . درگذشته . او راست : انفعالوسائل الی تحریرالمسائل در فروع که نسخه ٔ خطی آن در استنبول موجود است . (اعلام المنجد).<br /></font></div>'),
(176512, 'طرسوسی', '<span class=\"hlight\">طرسوسی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (اِخ ) محمدبن احمدبن محمد الطرسوسی . او راست : تقریرات علی کتاب المراءة در اصول فقه حنفی که در آستانه (اسلامبول ) بسال <span class=\"hlight\" dir=\"rtl\">١٣٠٤</span> هَ . ق . به چاپ رسیده است . دیگر حاشیه ای که بنام حاشیه ٔطرسوسی معروف است . این حاشیه را بر کتاب مرقاةالوصول ملا خسرو نوشته، و آن نیز بسال <span class=\"hlight\" dir=\"rtl\">١٣٠٩</span> هَ . ق . در آستانه طبع شده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣٨</span>).<br /></font></div>'),
(176513, 'طرسوسی کردن', '<span class=\"hlight\">طرسوسی کردن .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ک َ دَ ]</font></b> (مص مرکب ) چپاول و غارت کردن، چون مطابق اسناد تاریخی هنگامی که رومیان شرقی برشهر طرسوس چیرگی و تسلط یافتند، از هیچ نوع نهب و غارت نسبت به اموال مسلمانان دریغ نکردند. ظاهراً در عصر شیخ ابوسعید ابوالخیر هر نوع چپاول را به چپاول رومیان در طرسوس منسوب میداشتند، و مثل گونه ای مورد استعمال واقع میشده است <span class=\"hlight\">:</span> صوفیان را فتوحی بوده است، طرسوسی کرده اند .ما حصه ٔ شما اینجا نهاده ایم . (اسرارالتوحید ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>).<br /></font></div>'),
(176514, 'طرسوطوس', '<span class=\"hlight\">طرسوطوس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) سنگی سبز است، طبعش مانند دهنج و توتیا، و در معدن نقره و مس میباشد. (نزهةالقلوب ).<br /></font></div>'),
(176515, 'طرسولن', '<span class=\"hlight\">طرسولن .</span> <font color=\"DarkGreen\"><b>[ طَ ل ُ ]</font></b> (معرب، اِ) طالیسفر است . (فهرست مخزن الادویة).<br /></font></div>'),
(176516, 'طرسونة', '<span class=\"hlight\">طرسونة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ن َ ]</font></b> (اِخ ) از بلاد اندلس وچهار فرسنگ بین آن و تطیلة مسافت است و از اعمال تطیلة بشمار میرود. در آغاز جایگاه و محل سکونت عمال ولشکریان اسلامی بود تا رومیان شرقی بر آنجا غلبه و دست یافتند و تا این تاریخ هم شهر مزبور در تصرف آنهاست . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span>). و رجوع به نفح الطیب و الحلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥</span>، <span class=\"hlight\" dir=\"rtl\">١٧٢</span>، <span class=\"hlight\" dir=\"rtl\">١٧٤</span> شود.<br /></font></div>'),
(176517, 'طرسک', '<span class=\"hlight\">طرسک .</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (اِخ ) دهی از دهستان کیدقان بخش ششتمد شهرستان سبزوار، در <span class=\"hlight\" dir=\"rtl\">١٣</span>هزارگزی جنوب ششتمد، سر راه مالرو عمومی ششتمد به کاشمر. کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">٩٠٧</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و شغل اهالی زراعت و کرباس بافی و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176518, 'طرسک', '<span class=\"hlight\">طرسک .</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (اِ) خس الکلب است که ویناقوس نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(176519, 'طرسیقوس', '<span class=\"hlight\">طرسیقوس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) نام زاهدی و حکیمی بوده از نصاری، و بعضی گویند نام پادشاهی است از نصاری . (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br />کنم در پیش طرسیقوس اعظم <br />ز روح القدس و ابن و اب مجارا.<br /> <font color=\"Red\">خاقانی .</font><br />و طروسیقوس نیز آمده است . رجوع به طروسیقوس شود. مینورسکی گوید: چنین عنوانی در فهرست مقامات (روحانی ) بیزانسی در آثارالباقیه ٔ بیرونی ص <span class=\"hlight\" dir=\"rtl\">٢٩٠</span> (ترجمه ص <span class=\"hlight\" dir=\"rtl\">٢٨٤</span>) وجود ندارد، مگر بگوئیم که «طرسیقوس » قرائت غلط استراتگوس (اصرذیقوس )باشد. (حاشیه ٔ برهان قاطع چ معین : طرسیقوس ).<br /></font></div>'),
(176520, 'طرسیمی', '<span class=\"hlight\">طرسیمی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به یونانی هندباء است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176521, 'طرش', '<span class=\"hlight\">طرش .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع مص ) کر شدن . <BR><font color=\"Blue\">◄</font> (اِمص ) کری . <BR><font color=\"Blue\">◄</font> یا اندک کری . لغت مولد است . (منتهی الارب ) (آنندراج ). جوالیقی آرد: طرش عربی محض نیست بلکه از سخنان مولدان است و آن به منزله ٔ کری باشد... و بقول حربی طرش کمتر از کری یعنی سنگینی گوش باشد و گوید گمان میکنم این کلمه فارسی است . رجوع به المعرب ص <span class=\"hlight\" dir=\"rtl\">٢٢٤</span> شود. نقصان سمع. و در کشاف اصطلاحات الفنون آمده است که طرش نقصان شنوائی است و گاه بر آفت گوش استعمال شود چنانچه در بحر الجواهر گفته است و در آقسرائی گوید: آفت سمع گاهی بسبب عدم تجویفی است که در داخل گوش وجود دارد و این تجویف مشتمل بر هوای راکدی است که بعلت تموج آن آواز شنیده میشود و آن را صمم نامند. و گاه آفت مزبور بسبب چیزی است که قوه ٔ سامعه را باطل میکند در عین اینکه عضو سالم است و آن را وقر خوانند. و گاهی آفت سمع در نتیجه ٔ چیزی است که مایه ٔ نقصان آن میشود و آن را طرش گویند، مانند آنکه از نزدیک بشنوند و بر شنیدن آواز دورقادر نباشند. و گاه بر دو گونه ٔ اخیر صمم اطلاق کنند. و گاهی هم طرش را در معنی مطلق آفت سمع بکار میبرند، خواه این آفت بسبب فساد آلت شنوائی باشد یا جز آن و خواه بطلان شنوائی باشد یا نقصان آن - انتهی . (از کشاف اصطلاحات الفنون ). و رجوع به تذکره ٔ داود ضریر انطاکی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٥</span> شود. <BR><font color=\"Blue\">◄</font> (مص ) قطره چکاندن . <BR><font color=\"Blue\">◄</font> کسی را لجن مال کردن . <BR><font color=\"Blue\">◄</font> دیواری را با گچ سفید کردن : رواق بالرخام مطروش (مفروش ). <BR><font color=\"Blue\">◄</font> به بالا رفتن . <BR><font color=\"Blue\">◄</font> استفراغ کردن . از حلق برآوردن . <BR><font color=\"Blue\">◄</font> عجله کردن . شتاب کردن . <BR><font color=\"Blue\">◄</font> طرش الضبة؛ کشیدن چفت و کشو در. <BR><font color=\"Blue\">◄</font> بستن در: قفلت الباب و طرشت الضبة. طرش الباب امروز در مراکش معنی معکوس دارد یعنی شکستن دروقتی که کلید گم شده باشد. <BR><font color=\"Blue\">◄</font> گیج کردن . تصدیع دادن . <BR><font color=\"Blue\">◄</font> (اِ) بازیچه ای بشکل فرفره که با تسمه ای بدان میزنند تا بچرخد. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>).<br /></font></div>'),
(176522, 'طرش', '<span class=\"hlight\">طرش .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) ج ِ اَطْرَش و طَرْشاء. جماعت کران . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176523, 'طرش', '<span class=\"hlight\">طرش .</span> <font color=\"DarkGreen\"><b>[ طُرْ رُ ]</font></b> (اِخ ) ناحیه ای است به اندلس و دارای قراء چندی است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span>). و رجوع به الحلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span> شود.<br /></font></div>'),
(176524, 'طرشان', '<span class=\"hlight\">طرشان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) ناشنوا. کر. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br /></font></div>'),
(176525, 'طرشان', '<span class=\"hlight\">طرشان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) ج ِ اَطْرَش . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br /></font></div>'),
(176526, 'طرشت', '<span class=\"hlight\">طرشت .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) نام موضعی خوش آب و هوا از ملک ری که طهران دارالسلطنه ٔ آن است <span class=\"hlight\">:</span> <br />نازد به آه و اشک دلم کوی او سلیم <br />چون ملک ری به آب و هوای طرشت ما.<br /> <font color=\"Red\">محمدقلی سلیم (از آنندراج ).</font><br />در تداول «درشت » گویند. دهی جزء بخش کن شهرستان تهران، در <span class=\"hlight\" dir=\"rtl\">٢٠٠٠</span>گزی باختری تهران و <span class=\"hlight\" dir=\"rtl\">١٠٠٠٠</span>گزی جنوب خاوری کن و <span class=\"hlight\" dir=\"rtl\">١٠٠٠</span>گزی شمال راه شوسه ٔ تهران -کرج . دامنه، معتدل، با <span class=\"hlight\" dir=\"rtl\">١٤٥٧</span> تن سکنه . قسمتی از سکنه در تهران سکونت کرده اند. آب آن از قنات و در بهار از رودخانه ٔ کن . محصول آنجاغلات و انار و انجیر و صیفی و مختصر میوه . شغل اهالی زراعت است . دبستان، پاسگاه ژاندارمری موقت و راه فرعی دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(176527, 'طرشحة', '<span class=\"hlight\">طرشحة.</span> <font color=\"DarkGreen\"><b>[ طَ ش َ ح َ ]</font></b> (ع اِمص ) فروهشتگی . (منتهی الارب ) (آنندراج ). سستی . <BR><font color=\"Blue\">◄</font> (مص ) سست کردن . یقال : ضربه حتی طَرْشَحَه ُ؛ ای اَرخاه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176528, 'طرشقون', '<span class=\"hlight\">طرشقون .</span> <font color=\"DarkGreen\"><b>[ طَ ش َ ]</font></b> (معرب، اِ) هندبای بری بود. (اختیارات بدیعی ). کاسنی بری و یقال طرخشقوق، هو الهندباء البری مبرد، مفتح، عصاریة ینفع من الاستسقاء جداً و یفتح سددالکبد و یقاوم السموم خصوصاً الزنبور. (بحر الجواهر). و رجوع به طرخشفوق و طرخشقوس و طرخشقوق و طرخشقون شود.<br /></font></div>'),
(176529, 'طرشمة', '<span class=\"hlight\">طرشمة.</span><font color=\"DarkGreen\"><b>[ طَ ش َ م َ ]</font></b> (ع مص ) تاریک شدن شب . (منتهی الارب ).<br /></font></div>'),
(176530, 'طرشول', '<span class=\"hlight\">طرشول .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (معرب، اِ) (معرب از اسپانیایی ) چرخ یا باز نر. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>). و رجوع به طرشون شود.<br /></font></div>'),
(176531, 'طرشولی', '<span class=\"hlight\">طرشولی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به اندلسی صامریومای صغیر است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176532, 'طرشون', '<span class=\"hlight\">طرشون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) نوعی از باز یا صقر. ج، طراشن . این کلمه تحریفی از طرشول است . رجوع به طرشول شود. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br /></font></div>'),
(176533, 'طرشیز', '<span class=\"hlight\">طرشیز.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ )لغتی است در طریثیث . و در این زمان این شهر در دست تصرف ملاحده ٔ اسماعیلیه است و آن را ترشاش مینامند، به نیشابور نزدیک میباشد و بنابراین شهر مزبور دارای سه نام است، شهری بزرگ و دارای دیه های بسیاری است . (مراصدالاطلاع ). رجوع به طریثیث و کاشمر و ترشیز شود.<br /></font></div>'),
(176534, 'طرط', '<span class=\"hlight\">طرط.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع اِمص ) گولی . بیعقلی . <BR><font color=\"Blue\">◄</font> سبکی موی پلک و ابرو. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176535, 'طرط', '<span class=\"hlight\">طرط.</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (ع ص ) مرد گول . نادان . <BR><font color=\"Blue\">◄</font> طَرِطُالحاجبین ؛ مرد کم موی ابرو، و لا بد من ذکر الحاجبین و قد یترک قلیلاً. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176536, 'طرطاب', '<span class=\"hlight\">طرطاب .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) نان تاوه . (مهذب الاسماء). خبز طابق . (فهرست مخزن الادویة).<br /></font></div>'),
(176537, 'طرطان', '<span class=\"hlight\">طرطان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) کِرم خاکی . الحیوانات المتولدة فی الارض من قبل خمج او عفونة مثل الدود. این کلمه بر حسب گفته ٔ سیمونه مأخوذ از کلمه ٔ لاتینی تردینس است که جمع آن تردو میباشد. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br /></font></div>'),
(176538, 'طرطانش', '<span class=\"hlight\">طرطانش .</span> <font color=\"DarkGreen\"><b>[ طَ ن ِ ]</font></b> (اِخ ) ناحیه ای است به اندلس از اقلیم اکشونیه . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span>).<br /></font></div>'),
(176539, 'طرطانیوش', '<span class=\"hlight\">طرطانیوش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام جزیره ای است در میان دریا و عذرا در آن جزیره افتاد و خلاص شد. (برهان ) (آنندراج ). نام آن جزیره است که عذرا آنجا افتاد و خلاص یافت . عنصری گوید <span class=\"hlight\">:</span> <br />همی از پس رنجهای دراز<br />به طرطانیوش اندر آمد فراز.<br /> <font color=\"Red\">(از فرهنگ اسدی چ تهران ص <span class=\"hlight\" dir=\"rtl\">٢٢٥</span>).</font><br />بشد از پس رنجهای دراز<br />به یکی جزیره رسیدند باز<br />کجا نام آن بود طرطانیوش <br />در او پادشا نام او نوکیوش .<br /> <font color=\"Red\">عنصری (از فرهنگ اوبهی ).</font><br />و رجوع به فرهنگ شعوری ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span> شود.<br /></font></div>'),
(176540, 'طرطب', '<span class=\"hlight\">طرطب .</span> <font color=\"DarkGreen\"><b>[ طُ طُ <span class=\"hlight\" dir=\"rtl\">/</span> طُ طُب ب ]</font></b> (ع ص، اِ) پستان کلان فروهشته . طُرطُبی واحدآن است، در قول شخصی که ثَدی را مؤنث گوید. (منتهی الارب ) (آنندراج ). به عربی پستان طویل را گویند. (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> زن بزرگ پستان : یقال اِمراءة طُرطُبی . <BR><font color=\"Blue\">◄</font> شرم مرد. <BR><font color=\"Blue\">◄</font> در وقت فسوس گویند: دُهْدُرَّیْن ِ و طُرْطُبَّیْن ِ. (منتهی الارب ) (آنندراج ). رجوع به دُهْدُرَّیْن شود.<br /></font></div>'),
(176541, 'طرطبانیة', '<span class=\"hlight\">طرطبانیة.</span> <font color=\"DarkGreen\"><b>[ طُ طُ نی ی َ ]</font></b> (ع ص ) بمعنی طُرطُبة و طُرطُبّة است . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176542, 'طرطبة', '<span class=\"hlight\">طرطبة.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ب َ ]</font></b> (ع مص، اِمص )آواز صفیر دو لب دوشنده ٔ بُز. <BR><font color=\"Blue\">◄</font> جنبش آب در شکم . <BR><font color=\"Blue\">◄</font> خواندن گوسفندان را برای دوشیدن تا فراهم آیند. <BR><font color=\"Blue\">◄</font> و قال بعض اهل اللغة:طَرطَب الرجل ؛ اذا فَرَّ. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176543, 'طرطبة', '<span class=\"hlight\">طرطبة.</span> <font color=\"DarkGreen\"><b>[ طُ طُ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> طُ طُب ْ ب َ ]</font></b> (ع ص ) درازپستان از ماده بز و جز آن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176544, 'طرطبیس', '<span class=\"hlight\">طرطبیس .</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (ع ص، اِ) آب بسیار. <BR><font color=\"Blue\">◄</font> گنده پیر فروهشته اندام . <BR><font color=\"Blue\">◄</font> شترماده ٔ بسیارشیررام و نرم نزدیک دوشیدن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176545, 'طرطر', '<span class=\"hlight\">طرطر.</span> <font color=\"DarkGreen\"><b>[ طُ طُ ]</font></b> (ع اِ فعل ) فعل امر است جهت همسایگی بیت اﷲ الحرام و همیشگی بر آن . (منتهی الارب ). امرٌ بمجاورة البیت الحرام و الدوام علیها. (اقرب الموارد).<br /></font></div>'),
(176546, 'طرطر', '<span class=\"hlight\">طرطر.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (اِخ ) موضعی است به شام . (منتهی الارب ). قریه ای است به وادی بُطنان که همان وادی بُزاعه ٔ نزدیک حلب باشد، و آن را طلطل نیز گویند، و طرطر در شعر امروءالقیس آمده است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٦١</span>).<br /></font></div>'),
(176547, 'طرطری هندی', '<span class=\"hlight\">طرطری هندی .</span> <font color=\"DarkGreen\"><b>[ طَ طَ ی ِ هَِ ]</font></b> (اِخ ) هدایت آرد: از حکما و بلغای هندوستان است . تقی اوحدی نوشته که در مجموعه ای شش هفت قصیده ٔ نیکو به اسم او دیده ام . بهر حال از او میباشد:<br />هست گوئی عارض آن ترک زیبا آفتاب <br />گر بود ممکن که دارد برج دیبا آفتاب <br />وصل او خواهد ز ایزد مهر او ورزد بجان <br />هرکه را باید رونده سرو و گویا آفتاب <br />نیست با سیمین سرین و لاله گون رخسار سرو<br />نیست با زلف سیاه و چشم شهلا آفتاب <br />دوش نزدیک من آمد آفتاب نیکوان <br />چون برون زدموکب از میدان مینا آفتاب <br />در صفات آفتاب و آسمان ماندم عجب <br />چون برآمد ناگهان از روی دریا آفتاب <br />گفتی از روی مَثل بود این جهان موسی و بود<br />آستینش آسمان و دست بیضا آفتاب <br />روشن و تابان ز دریا روی بر بالا نهاد<br />رای شاهنشاه عادل بود مانا آفتاب <br />شاه رکن الدین که دولت را مهیا دارد او<br />همچو باغ نوبهاری را مهنا آفتاب <br />آنچنان کو هست بر مردم توانا روز جنگ <br />نیست گاه نور بر انجم توانا آفتاب <br />رزمگاه از خون بدخواهان کند گاه خزان <br />همچو در اردیبهشت از لاله صحرا آفتاب <br />با بد و با نیک یکسان است جود او مدام <br />نور یکسان افکند بر خار و خرما آفتاب <br />آفتاب اعداش را از نور دارد بی نصیب <br />هست بر اعدای شه گوئی که اعدا آفتاب .<br />و له ایضاً:<br />رخ و بر و لب آن دلفریب تازه نگار<br />یکی گل است و دویم سوسن و سیم گلنار<br />لبش به بوسه و زلفش به مهر و چشم به عهد<br />یکی بخیل و دویم جابر و سیم قهار<br />ز گور و آهوی و کبک دری ستد گوئی <br />یکی سرین و دویم دیده و سیم رفتار<br />ترا چو چشمه ٔ حیوان و لاله و شکر است <br />یکی دهان و دویم چهره و سیم گفتار<br />به دیده و دل وجان از تو من خریدارم <br />یکی کنار و دویم بوسه و سیم دیدار.<br /><font color=\"Red\">(مجمعالفصحا ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٧</span>).</font><br /></font></div>'),
(176548, 'طرطفا', '<span class=\"hlight\">طرطفا.</span> <font color=\"DarkGreen\"><b>[طَ طَ ]</font></b> (ع اِ) انجدان است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176549, 'طرطق', '<span class=\"hlight\">طرطق .</span> <font color=\"DarkGreen\"><b>[ طَ طَ]</font></b> (ع اِ) دُرد. لرد. دُردی . ثفل . حثاله . رسوب . طرطیر. ج، طراطق . و رجوع به طرطیر شود. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧</span>).<br /></font></div>'),
(176550, 'طرطوانش', '<span class=\"hlight\">طرطوانش .</span> <font color=\"DarkGreen\"><b>[ طَ طَ ن ِ ]</font></b> (اِخ ) از اعمال باجه واقع در اندلس است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span>).<br /></font></div>'),
(176551, 'طرطور', '<span class=\"hlight\">طرطور.</span> <font color=\"DarkGreen\"><b>[ طُ]</font></b> (ع ص ) باریک دراز. (منتهی الارب ) (آنندراج ). دراز باریک . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> کلاه باریک دراز. <BR><font color=\"Blue\">◄</font> ناکس ضعیف . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176552, 'طرطوس', '<span class=\"hlight\">طرطوس .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (اِخ ) شهری است به شام مشرف بر دریا و نزدیک مرقب و عکا. یاقوت گوید: در این تاریخ در دست فرنگیان است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span>). نام دهی پررونق . (آنندراج ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br />صندوقچه ٔ عدل تو مانده ست به طرطوس <br />دستورچه ٔ جور تو در پیش و کنار است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />در شعر بالا در دیوان ناصرخسرو ص <span class=\"hlight\" dir=\"rtl\">٥٥</span> این لفظ بصورت فوق آمده و در زیر صفحه معنی کرده اند که نام شهری است به اندلس، و آقای مجتبی مینوی در ضمن تعلیقات در ص <span class=\"hlight\" dir=\"rtl\">٦٢٨</span> دیوان مزبور تذکر داده اند که شهری که در اندلس است طرطوشه نام دارد، و ظاهراً اینجا طرسوس یا طرطوس بر وزن قربوس (که در حالت ضرورت شعر اسکان راء رواست ) صواب باشد که هر دو نام شهری از شام است . و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span> شود.<br /></font></div>'),
(176553, 'طرطوس', '<span class=\"hlight\">طرطوس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام پهلوانی . (آنندراج ) (غیاث اللغات ). نام مبارزی از لشکر روس . (شمس اللغات ). و بزبان رومی رستم را گویند (؟). (هفت قلزم ).<br /></font></div>'),
(176554, 'طرطوس', '<span class=\"hlight\">طرطوس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) نوعی کفش (؟) <span class=\"hlight\">:</span> گفت مادرت کهنه طرطوسی دارد گاهگاهی به پا درمیکشم . (هزلیات سعدی ).<br /></font></div>'),
(176555, 'طرطوسی', '<span class=\"hlight\">طرطوسی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (اِخ ) ابوالحسن طرطوسی از مشایخ بوده است . رجوع به تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٧٩٥</span> شود.<br /></font></div>'),
(176556, 'طرطوسی', '<span class=\"hlight\">طرطوسی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ]</font></b> (اِخ ) ابوطاهربن حسین بن علی بن موسی، مؤلف کتابی در ترجمه ٔ احوال ابومسلم خراسانی بنام «ابومسلم نامه »که از میان رفته و صاحب تجارب الامم چند بار از آن نقل کرده . رجوع به ابومسلم خراسانی صاحب الدعوة شود.<br /></font></div>'),
(176557, 'طرطوسی', '<span class=\"hlight\">طرطوسی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (ص نسبی ) منسوب به شهر طرطوس . (سمعانی ).<br /></font></div>'),
(176558, 'طرطوسی', '<span class=\"hlight\">طرطوسی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (اِخ ) رجوع به خلف بن افلح بن قاسم شود. (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>).<br /></font></div>'),
(176559, 'طرطوشی', '<span class=\"hlight\">طرطوشی .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ص نسبی ) منسوب به طرطوشه، آخرین شهر از بلاد مسلمانان در اندلس است . (سمعانی ).<br /></font></div>'),
(176560, 'طرطوشی', '<span class=\"hlight\">طرطوشی .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ )محمدبن الولیدبن محمد القرشی الفهری، کنیتش ابوبکر، معروف به طرطوشی و نیز مشهور به ابن ابی رندقه . وی ادیبی است از فقهای حفاظ. نشو و نمای وی در طرطوشه (واقع در شرق اندلس ) بود و در آن شهر فقه آموخت، سپس بسوی عراق، مصر، فلسطین و لبنان سفری کرد و در اسکندریه سکونت گزید و چندان در آن شهر مشغول تدریس گردید تا عمرش سر آمد. مردی زاهد بود و به هیچ چیز دنیا دلبستگی نداشت . از کتب او یکی سراج الملوک است که چاپ شده است . دیگر تعلیقه ای است در خلافیات محتوی بر پنج جزء. دیگر کتابی که به روش احیاءالعلوم غزالی نوشته . دو کتاب دیگر یکی بنام برالوالدین و دیگری بنام الفتن نیز به وی نسبت داده اند. (اعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩٩٩</span>).<br />حاجی خلیفه درباره ٔ سراج الملوک وی آرد:<br />این کتاب در مواعظ و اندرزهایی است که از سیر پیمبران و آثار اولیاء و پندهای دانشمندان و حِکم حکماء ونوادر خلفاء گرد آورده و به زیباترین ترتیب آن را به رشته ٔ تألیف آورده است، به نحوی که پس از پایان یافتن آن هر پادشاهی که وصف آن بشنید فرمان داد تا ازآن نسخه بردارند و هر وزیری که از وجود آن آگاه شد، نسخه ای از آن را با خود همراه میداشت و در دیباچه ٔ کتاب امیر ابوعبداﷲ اموی را یادآور شده است و این کتاب محتوی بر شصت وچهار باب میباشد. (کشف الظنون ). و صاحب معجم المطبوعات گوید: کتاب مذکور نوبتی بسال <span class=\"hlight\" dir=\"rtl\">١٢٨٩</span>هَ . ق . در مطبعه ٔ بولاق مصر و نوبتی در مطبعه ٔ وطنیه به اسکندریه بسال <span class=\"hlight\" dir=\"rtl\">١٢٩٩</span> هَ . ق . و به حاشیه ٔ آن نیزالتبر المسبوک فی نصیحةالملوک تصنیف غزالی و نوبتی هم در حاشیه ٔ مقدمه ٔ ابن خلدون بسال <span class=\"hlight\" dir=\"rtl\">١٣٠٦</span> هَ . ق . و هم بسال <span class=\"hlight\" dir=\"rtl\">١٣١٩</span> در مطبعه ٔ خیریه ٔ مصر به طبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣٩</span>). و رجوع به ابن ابی رندقه و محمدبن الولید و عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٣</span> و تاریخ الخلفا ص <span class=\"hlight\" dir=\"rtl\">٢٨٩</span> و شدالازار ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span> و فهرست غزالی نامه و وفیات الاعیان ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٥٣</span> - <span class=\"hlight\" dir=\"rtl\">٥٤</span> شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(176561, 'طرطیر', '<span class=\"hlight\">طرطیر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به عربی دُردی خمر است . (فهرست مخزن الادویه ) (تحفه ٔ حکیم مؤمن ). طرطق .<br /></font></div>'),
(176562, 'طرطینة', '<span class=\"hlight\">طرطینة.</span> <font color=\"DarkGreen\"><b>[ طِ طَ ن َ ]</font></b> (معرب، اِ) در لاتینی : لومبریکوس . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br /></font></div>'),
(176563, 'طرعب', '<span class=\"hlight\">طرعب .</span> <font color=\"DarkGreen\"><b>[ طَ ع َ ]</font></b> (ع ص ) دراز به درازی زشت . (منتهی الارب ) (آنندراج ). الطویل القبیح الطول . (اقرب الموارد).<br /></font></div>'),
(176564, 'طرعمیسا', '<span class=\"hlight\">طرعمیسا.</span> <font color=\"DarkGreen\"><b>[ طَ ع َ ]</font></b> (معرب، اِ) به سریانی یا به یونانی صمغ قتاد است که کتیرا باشد. (فهرست مخزن الادویة).<br /></font></div>'),
(176565, 'طرغان بستن', '<span class=\"hlight\">طرغان بستن .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت َ ]</font></b> (مص مرکب ) بر حسب گمان سر دنیسن راس کلمه ٔ طرغان گویا از مصدر طیرمک مشتق است که معنی آن گرد کردن است و طرغان یا طرگن بمعنی انبوه و جمعیت باشد و «چریک طرگنی » بمعنی انبوه لشکر در قوداتقو بیلیک یافت میشود. پس طرغان بستن گویا بمعنی لشکر گرد کردن است . (از حاشیه ٔ محمد اقبال بر راحةالصدور چ تهران ص <span class=\"hlight\" dir=\"rtl\">٥٠٨</span>) <span class=\"hlight\">:</span> اتابک قزل ارسلان با لشکری گران روی به دارالملک همدان نهاد و سلطان طرغان بست و کندهای آب بداشتند و بندگان چالش میکردند و هر لحظه آوازه ٔ مصاف میبود. (راحةالصدور چ تهران ص <span class=\"hlight\" dir=\"rtl\">٣٤٧</span>).<br /></font></div>'),
(176566, 'طرغانن', '<span class=\"hlight\">طرغانن .</span> <font color=\"DarkGreen\"><b>[ طَ ن ُ ]</font></b> (معرب، اِ) سقوربیون . طراغیون آخر. رجوع به طرغاین شود.<br /></font></div>'),
(176567, 'طرغای', '<span class=\"hlight\">طرغای .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) پسر هلاکو که در قتل کیخاتو پسر اباقا شرکت داشت . رجوع به تاریخ مغول تألیف اقبال ص <span class=\"hlight\" dir=\"rtl\">٢٥١</span>، <span class=\"hlight\" dir=\"rtl\">٢٧٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٧١</span> و رجوع به طراقای شود.<br /></font></div>'),
(176568, 'طرغاین', '<span class=\"hlight\">طرغاین .</span><font color=\"DarkGreen\"><b>[ طَ ی ُ ]</font></b> (معرب، اِ) یکی از انواع طراغیون است . (فهرست مخزن الادویة). رجوع به طرغانن و طراغیون شود.<br /></font></div>'),
(176569, 'طرغلة', '<span class=\"hlight\">طرغلة.</span> <font color=\"DarkGreen\"><b>[ طَ غ َل ْ ل َ ]</font></b> (اِخ ) شهری است به اندلس از ناحیه ٔ اکشونیه . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>).<br /></font></div>'),
(176570, 'طرغلودیس', '<span class=\"hlight\">طرغلودیس .</span> <font color=\"DarkGreen\"><b>[ طَ غ َ ]</font></b> (معرب، اِ) به یونانی مرغی باشد به بزرگی گنجشک و در بال او پر زردی میباشد و پیوسته در کناره های آب نشیند و دُم جنباند، آن را به عربی عصفورالشوک و عصفورالسیاح خوانند و طروغلودیس و طروغلودقس هم گفته اند. گوشت وی سنگ گرده را بریزاند و منع آن هم کند که دیگر بهم نرسد. (برهان ) (آنندراج ). طریقلودقطس است . (اختیارات بدیعی ). خردترین بنجشکان است و خاصةً در زمستان پیدا آید، رنگ غالب بر پر آن مزجی ازخاکستری و زرد باشد و بر بال پرهای زرین دارد و نوک آن باریک بود و بر دُم ِ او خجک های سیاه است و دم خود را دائم جنباند، پیوسته آواز دهد و کم پرد و گوشت او را در ریزانیدن سنگ مثانه و بازداشتن از پیدایش سنگ خاصیتی شگفت است . و در حاوی گوید: آن را به افریقیه صفراغون خوانند و دیسقوریدس گوید: گرم است در دوم و اندکی از درون وی تفتیت حصاة کند. (ذخیره ٔ خوارزمشاهی ). دمتک . دم جنبانک .<br /></font></div>'),
(176571, 'طرف', '<span class=\"hlight\">طرف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) چشم . (منتهی الارب ) (آنندراج ). منه قوله تعالی <span class=\"hlight\">:</span> لایرتد الیهم طرفهم . (قرآن <span class=\"hlight\" dir=\"rtl\">٤٣/١٤</span>). و قال اﷲ تعالی : قبل ان یرتد الیک طرفک . (قرآن <span class=\"hlight\" dir=\"rtl\">٤٠/٢٧</span>). و هو اسم جامع للبصر، لایثنی ولایجمع و قیل جمعه اطراف . (منتهی الارب ) <span class=\"hlight\">:</span> <br />اینهمه جوها ز دریایی است ژرف <br />جزو را بگذار و بر کل دار طرف .<br /> <font color=\"Red\">مولوی .</font><br />گر بمعنی رفت، غافل شد ز حرف <br />پیش و پس یک دم نبیند هیچ طرف .<br /> <font color=\"Red\">مولوی .</font><br />خویشتن افکند در دریای ژرف <br />که نیابد حد آن را هیچ طرف .<br /> <font color=\"Red\">مولوی .</font><br />کسی کو روی گل بیند به طرفا طرف نندازد<br />کسی کو توتیا یابد، کشد در دیده خاکش را.<br /> <font color=\"Red\">بدر جاجرمی .</font><br /> <BR><font color=\"Blue\">◄</font> مژه . <BR><font color=\"Blue\">◄</font> گوشه و کنار چشم . (برهان ). <BR><font color=\"Blue\">◄</font> در دو نسخه ٔ خطی مهذب الاسماء متعلق به کتابخانه ٔ مؤلف طرف بمعنی آسیرک آمده و در نسخه ٔ سوم ایضاً متعلق به کتابخانه ٔ مؤلف اسبرک . <BR><font color=\"Blue\">◄</font> پشک <span class=\"hlight\">:</span> <br />فان تسلم الهلبا من الطرف لم یزل <br />بنجران منها قبة و عروش .<br /> <font color=\"Red\">؟</font><br />الهلبا جنس من البرّ. (منتهی الارب ) . <BR><font color=\"Blue\">◄</font> جوانمرد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> معرب ترف است که به ترکی قراقروت نامند که رُخبین باشد. (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> منتها و پایان هر چیزی . (منتهی الارب ). انتهاء. <BR><font color=\"Blue\">◄</font> طرف در لغت نهایت باشد، تثنیه ٔ آن طرفان و جمع اطراف، و معنی طرف صباحی و طرف مسائی در ذکر معنی عرض وراب خواهدآمد. (کشاف اصطلاحات الفنون ).<br /><BR><font color=\"Blue\">◄</font> (اِخ ) منزلی است از منازل قمر و آن دو ستاره است درمقدم جبهه که عین الاسد نامندش بدان جهت که هر دو چشم اسد است . (منتهی الارب ) (آنندراج ). عین الاسد. منزلی از منازل قمر و آن دو ستاره است در پیش جبهه ٔ منزل نهم است از منازل ماه پس از نثره و پیش از جبهه و آن دو ستاره است بر گردن اسد و عرب آن را بر دو چشم اسد شمارد. طرفة. بیرونی در التفهیم آورده : طرف ای چشم شیر و دو ستاره اند میان ایشان چند ارش بدیدار، یکی ازصورت اسد است، و دیگر بیرون از وی . (التفهیم فارسی چ همائی ص <span class=\"hlight\" dir=\"rtl\">١٠٩</span>). از منازل قمر است و آن دو ستاره ٔ خفی است که در پیش جبهه به یکدیگر مقترنند و آنها را ازاین رو بدین نام خوانده اند که موقع آنها به منزله ٔ موقع دو چشم شیر است و در روبروی آنها شش ستاره ٔ کوچک است که عرب آنها را اشفار مینامد و از این شش ستاره دو عدد آنها در نسق و به موازات طرف اند و چهار عدددیگر در مقدم آن باشند. (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٨</span>). و رجوع به طرفان شود. <BR><font color=\"Blue\">◄</font> طرف در اصطلاح هیئت و علم فلک، عبارت است از برج سرطان .<br /></font></div>'),
(176572, 'طرف', '<span class=\"hlight\">طرف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) برگردانیدن چیزی را از چیزی . یقال : شخص ببصره فماطرف . (منتهی الارب ) (آنندراج ). رد نمودن . <BR><font color=\"Blue\">◄</font> بر یکدیگر نهادن پلکها را. <BR><font color=\"Blue\">◄</font> جنبانیدن هر دو پلک را. (منتهی الارب )(آنندراج ). چشم بر هم زدن . <BR><font color=\"Blue\">◄</font> بر چشم کسی زدن چیزی را که آب روان شود از چشم و رسیدن چیزی به چشم که اشک از آن روان شود. (منتهی الارب ) (آنندراج ). رسیده شدن چشم و اشک ریختن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نگریستن بسوی کسی . <BR><font color=\"Blue\">◄</font> طپانچه زدن کسی را. (منتهی الارب ) (آنندراج ). و منه الحدیث : کان محمدبن عبدالرحمن اصلع، فطرف له طرفةً؛ ای ضرب علی رأسه و اصل الطرف الضرب علی طرف العین ثم نقل الی غیرها. (منتهی الارب ). زدن به دست . (شرح قاموس ). اللطم بالید علی طرف العین ثم نقل الی الضرب علی الرأس . (تاج العروس ). طرفه طرفاً؛ لطمه بیده . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> و مابقیت منهم عین تَطْرِف ُ؛ یعنی همه مردند و کشته شدند. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> در استعمال فارسی بمعنی کلیچه ٔ کمر که برای آرایش بندند. (غیاث اللغات ) (برهان ) (آنندراج ). گل کمر. <BR><font color=\"Blue\">◄</font> بند نقره . (برهان ). بند زر و نقره که بر کمر بندند. (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br />مانا که رخم زرین کردی ز فراقت <br />کردی ز رخم طرف و نشاندی به کمر بر.<br /> <font color=\"Red\">مسعودسعد.</font><br />که اگر میخواهی این لعل را طرف کمر ایمان کنی، صواب آن باشد. (کتاب النقض عبدالجلیل قزوینی ).<br />صبح نهدطرف زر بر کمر آسمان <br />آب کند دانه هضم در شکم آسیاب .<br /> <font color=\"Red\">خاقانی .</font><br />تاجوران را ز لعل طرف نهی بر کمر<br />شیردلان را ز جزْع داغ نهی بر سُرین .<br /> <font color=\"Red\">خاقانی .</font><br />لعل تو طرف زر است بر کمر آفتاب <br />وصل تو مهره ٔ تب است در دهن اژدها.<br /> <font color=\"Red\">خاقانی .</font><br />هر شب برای طرف کمرهای خادمانش <br />دریای چرخ لؤلؤ لالا برافکند.<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> کمربند. (برهان ). <BR><font color=\"Blue\">◄</font> گوشه و کنار. (برهان ) (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرف ابرو بلند کردن </span> ؛ در محل تعظیم می باشد <span class=\"hlight\">:</span> <br />مریض عشق چو آید اجل به بالینش <br />کند بلند به تعظیم طرف ابرویی .<br /> <font color=\"Red\">طالب آملی (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرف بام </span> ؛ گوشه ٔ بام . کناره ٔبام .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرف برقع</span> ؛ گوشه ٔ برقع.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرف چمن </span> ؛ گوشه ٔ چمن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرف دامن </span> ؛ گوشه ٔ دامن . (آنندراج ) <span class=\"hlight\">:</span> <br />ز بس دامن از این گلشن به رنگ غنچه برچیدم <br />رسانیدم به معراج گریبان طرف دامن را.<br /> <font color=\"Red\">خان خالص (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرف دستار</span> ؛گوشه ٔ دستار <span class=\"hlight\">:</span> <br />اگر بلبل هزاران نغمه های دلگشا دارد<br />نخواهد گل شکفتن تا نبیند طرف دستارش .<br /> <font color=\"Red\">ابوطالب کلیم (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرف کلاه (کُلَه )</span> ؛ گوشه ٔ کلاه . کلاه گوشه . کُلَه گوشه <span class=\"hlight\">:</span> <br />نه هرکه طرف کُلَه کج نهاد و تند نشست <br />کلاه داری و آیین سروری داند.<br /> <font color=\"Red\">حافظ (دیوان چ قزوینی ص <span class=\"hlight\" dir=\"rtl\">١٢٠</span>).</font><br />یک روز دور طرف کلاهی ندیده ام <br />عیدی نکرده ابروی ماهی ندیده ام .<br /> <font color=\"Red\">سالک یزدی (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> ساخت اسب . (آنندراج ). ساز و برگ اسب . زین و برگ اسب . <BR><font color=\"Blue\">◄</font> آهن جامه ٔ صندوق را هم گفته اند. (برهان ) (آنندراج ).<br /></font></div>'),
(176573, 'طرف', '<span class=\"hlight\">طرف .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع اِ) کرانه . (منتهی الارب ) (آنندراج ). جانب و سو. سوی . کناره . بر. کنار. انتها. نوک دست . سمت . اوب . (منتهی الارب ): طرف راست ؛ دست راست . سمت راست <span class=\"hlight\">:</span> <br />لاله مشکین دل عقیقین طرف است <br />چون آتش اندراوفتاده به خَف است .<br /> <font color=\"Red\">منوچهری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرف الارض </span> ؛ کرانه . ناحیه ٔ دورتر زمین . قال اسعد <span class=\"hlight\">:</span> <br />قد کان ذوالقرنین جدی قد اتی <br />طرف البلاد من المکان الابعد.<br /> <font color=\"Red\">(منتهی الارب ) (آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> ناحیه . (منتهی الارب ) (آنندراج ). طنب . (منتهی الارب ) <span class=\"hlight\">:</span> <br />برابر کشیدندلشکر دو صف <br />مبارز روان گشت از هر طرف .<br /> <font color=\"Red\">فردوسی .</font><br />اگر به طرفی خدمتی باشد و مرا فرموده آید تا سالار و پیشرو باشم آن خدمت بسر برم . (تاریخ بیهقی ). از روی قیاس آن است که استخوان اندر سختی به طرفی است و گوشت اندر نرمی به طرفی است ورگها و شریانها میان این و آن است <font color=\"DarkGreen\"><b>[ یعنی در سختی ونرمی ]</font></b>. (ذخیره ٔ خوارزمشاهی ). و مثال آن چون ابر بهاری است که در میان آسمان بپراکند و در هر طرف قطعه ای نماید. (کلیله و دمنه ). همه را الزام کرد تا در دوطرف از روز ملازمت دیوان او می نمایند. (ترجمه ٔ تاریخ یمینی چاپی ص <span class=\"hlight\" dir=\"rtl\">٤٣٨</span>). هارون گفت ای پسر کرم آن است که عفو کنی و گر نتوانی تو نیزش دشنام مادر ده نه چندانکه انتقام از حد درگذرد، پس آنگه ظلم از طرف ما باشدو دعوی از قِبل خصم . (گلستان ). آفتاب از کدام طرف برآمده است که ... <BR><font color=\"Blue\">◄</font> طرف من البدن ؛ هر دو دست و پای و سر، و نیز انگشتان . مواضع وضو. و منه الحدیث : یتوضؤن علی اطرافهم ؛ ای یصبون الماء. <BR><font color=\"Blue\">◄</font> پاره ای از هر چیزی . گروه از هر چیزی . (منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span> سزد که چون مور کمر خدمت ببندم و بدین خط چون پای ملخ جزوی نویسم، و در آن طرفی از اخبار و اسمار ملوک و تواریخ پادشاهان درج کنم و به حضرت عالی تحفه برم . (ترجمه ٔ تاریخ یمینی خطی ص <span class=\"hlight\" dir=\"rtl\">٦</span>). آن طرف به عدل و انصاف او آراسته گشت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٩١</span>). القصه شنیدم که طرفی از خبائث نفس او معلوم کردند. (گلستان ). لقمان حکیم اندر آن قافله بود، یکی گفتش از کاروانیان مگر اینان را <font color=\"DarkGreen\"><b>[ دزدان را ]</font></b> نصیحتی کنی ... تا طرفی از مال ما دست بدارند. (گلستان ). خشکسالی در اسکندریه پدید آمده بود... در چنین سالی مخنثی که یک طرف از نعت او شنیدی . (گلستان ). <BR><font color=\"Blue\">◄</font> جوانمرد. ج، اطراف . <BR><font color=\"Blue\">◄</font> طرف من الارض ؛ اشراف و دانشمندان زمین . <BR><font color=\"Blue\">◄</font> طرف من الرجل ؛ پدران، برادران و اعمام و هر قریب و محرم وی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> و یقال : لایدری ای طرفیه اطول ؛ یعنی دانسته نمیشود که شرم او درازتر است یا زبان وی، یا نسبت پدری یا مادری وی . <BR><font color=\"Blue\">◄</font> و فی الحدیث : مارأیت اقطع طرفاً من عمروبن العاص ؛ ای امضی لساناً منه . (منتهی الارب ). کناره ٔ زبان . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> و فلان لایملک طرفیه ؛ ای فمه و استه، وقتی که دارو خورد، یا مست شراب گردد، و در قی و اسهال معاً مبتلا باشد. <BR><font color=\"Blue\">◄</font> و کذا: لایدری ای طرفیه اسرع ؛ ای حلقه او دبره . <BR><font color=\"Blue\">◄</font> و فی الحدیث : کان اذا اشتکی احد من اهله لم تزل البرمة علی النار حتی یأتی علی احد طرفیه ؛ یعنی صحت یا موت، که هر دو نهایت مریض است . <BR><font color=\"Blue\">◄</font> و قول اﷲ عزّ و جل <span class=\"hlight\">:</span> اَقم الصلوة طرفی النهار (قرآن <span class=\"hlight\" dir=\"rtl\">١١٤/١١</span>)؛ یعنی نماز دو طرف روز، اول نماز صبح، وفاقاً، و دوم بر اختلاف، قال الحسن : صلوةالعصر، و قال مجاهد: صلوة العصر و الظهر و قال ابن عباس : صلوةالمغرب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> صاحب آنندراج آرد: حریف و فارسیان بمعنی مقابل و هم پیشه استعمال نمایند و به همین مناسبت، منکوحه را نیز گویند، چنانکه گویند: امروز طرف فلان کس مرد <span class=\"hlight\">:</span> <br />رمز بر نکته دقیق و طرف بخت عوام <br />گر گلو پاره کنم کس به سخن وانرسد.<br /> <font color=\"Red\">سنجر کاشی .</font><br />ناشسته روست آینه، با او طرف شدن <br />هرگز نزیبد از تو به زیبائیت قسم .<br /> <font color=\"Red\">نورالعین واقف .</font><br />منعم و درویش همدوشند در دیوان عدل <br />در ترازو سنگ بی قیمت بود باراز طرف .<br /> <font color=\"Red\">محمدرفیع واعظ قزوینی .</font><br />طرف صحبت من یک طرف افتاد و برفت <br />بلبلی نیست چه لذت ز غزلخوانی من .<br /> <font color=\"Red\">محسن تأثیر.</font><br /> <BR><font color=\"Blue\">◄</font> فائده <span class=\"hlight\">:</span> <br />صراط عشق خطرناک، میلی و تو زبون <br />ترا امید طرف زین صراط برطرف است .<br /> <font color=\"Red\">محمدقلی میلی هروی (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> و بمعنی وقت و هنگام مجاز است، چون طرف صبح و طرف شام . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">برطرف کردن </span> ؛ از میان بردن . معدوم کردن . و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بطرف </span> ؛ خارج . بیرون . منحرف <span class=\"hlight\">:</span> <br />در جهان دشمن جان تو نباشد الا<br />خارجی مذهب وز مذهب سنت بطرف .<br /> <font color=\"Red\">سوزنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">صاحب طرف </span> ؛ مرزبان . کنارنگ . سرحددار. نگاهبان مرز.<br /></font></div>'),
(176574, 'طرف', '<span class=\"hlight\">طرف .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع مص ) جداگانه بر کرانه چرا کردن ناقه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176575, 'طرف', '<span class=\"hlight\">طرف .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (ع ص ) رجل ٌ طَرِف ٌ؛ آنکه بر یک زن و یک صاحب و یار ثبات و قرار نگیرد. <BR><font color=\"Blue\">◄</font> آنکه میان او و جد اکبر وی پدران بسیار باشند. <BR><font color=\"Blue\">◄</font> مرد کریم الطرفین . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176576, 'طرف', '<span class=\"hlight\">طرف .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) ج ِ طَریف . رجوع به طریف شود.<br /></font></div>'),
(176577, 'طرف', '<span class=\"hlight\">طرف .</span> <font color=\"DarkGreen\"><b>[ طُ رَ ]</font></b> (ع ص، اِ) ج ِ طُرفة. رجوع به طُرفة شود.<br /></font></div>'),
(176578, 'طرف', '<span class=\"hlight\">طرف .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص، اِ) مرد کریم الطرفین . ج، اطراف، و در صفت غیر مردم بر طُروف جمع شود اکثر. <BR><font color=\"Blue\">◄</font> اسب گرامی نژاد نجیب الاطراف . یا صفت مذکر است خاصةً. ج، طُروف، اطراف . (منتهی الارب ) (آنندراج ). اسب گوهری . (مهذب الاسماء) <span class=\"hlight\">:</span> <br />هزاران طرف زرین طوق بسته <br />همه میخ درستکها شکسته .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> جوانمرد و کریم . <BR><font color=\"Blue\">◄</font> گیاه نودمیده . <BR><font color=\"Blue\">◄</font> مال نو. <BR><font color=\"Blue\">◄</font> آنکه از جهت ملالت طبیعت سر صحبت احدی ثابت نماند. <BR><font color=\"Blue\">◄</font> شتری که از چراگاهی به چراگاهی نقل کند. <BR><font color=\"Blue\">◄</font> رجل طرف فی نسبه ؛ یعنی مرد شرف و مجد نوپیدا. کأنه مخفف من طَرِف . <BR><font color=\"Blue\">◄</font> مرد حریص چشم که هرچه بیند مایل آن شود و خواهش کند که آن را باشد. <BR><font color=\"Blue\">◄</font> امراءة طرف الحدیث ؛ زن خوش کلام که هر سامع را خوش آید. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176579, 'طرف', '<span class=\"hlight\">طرف .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) واقدی گوید: آبی است نزدیک مرقی پائین نخیل، در سی وشش میلی مدینه . محمدبن اسحاق گفته است : ناحیه ای است از عراق و در تاریخ غزوات پیغمبر صلی اﷲعلیه و آله و سلم، ذکر آن آمده است . و طرف القدوم ذکرش در جایگاه خود بگذشت . عرام گفته است برای مسافری که عازم مدینه باشد، بطن نخل و اسود، و طرف را سه کوه احاطه میکند، یکی ظلم است و آن کوهی است بلند و سیاه رنگ که هیچ نوع گیاهی در آن نروید، و دیگری حزم بنی عوال است که هر دو کوه متعلق به قبیله ٔ غطفان میباشد. (یاقوت از سومین کوه نامی نبرده است ). (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>). از مدینه تا طرف که در او آب روان است سی وپنج میل، از او تا بطن نخل که در او آب باران است بیست ودو میل . (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٧٠</span>). از قرعا تا واقصه بیست وچهار میل، در او چاههاست و از جمله، چاه قرون که سلطان ملکشاه سلجوقی حفر کرده، پانزده گزدر پانزده گز است، در عمق چهارصد گز در سنگ کنده اند، و متعشی به طرف است . (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>).<br /></font></div>'),
(176580, 'طرف الاغر', '<span class=\"hlight\">طرف الاغر.</span> <font color=\"DarkGreen\"><b>[ طَ فُل ْ اَ غ َرر ]</font></b> (اِخ ) شهری است به اسپانیا. رجوع به ترافالگار و الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span> و <span class=\"hlight\" dir=\"rtl\">٣٣١</span> شود.<br /></font></div>'),
(176581, 'طرف البرک', '<span class=\"hlight\">طرف البرک .</span> <font color=\"DarkGreen\"><b>[ طَ فُل ْ ب ُ ]</font></b>(اِخ ) موضعی است نزدیک کوه مطاع بر دوفرسنگی مکه .<br /></font></div>'),
(176582, 'طرف الظل', '<span class=\"hlight\">طرف الظل .</span> <font color=\"DarkGreen\"><b>[ طَ رَ فُظْ ظِل ل ]</font></b> (ع اِ مرکب ) در تداول عارفان کنایه ازمفارقت هیولی از صورت است : و صارت الشمس فوق رؤوسنا اذ وصلنا الی طرف الظل ...؛ و آفتاب بالای سر ما شد؛ یعنی عمر به تنگی رسید، صورت مبدل شد «چون » به کنار سایه رسیدیم یعنی هیولا نیز خواست از صورت منفک شدن ودلیل بر آن که «از» شمس و ظل هیولا و صورت خواهد قوله عز و جل : «اء لم تر الی ربک کیف مد الظل و لو شاء لجعله ساکناً ثم جعلنا الشمس علیه دلیلاً» (قرآن <span class=\"hlight\" dir=\"rtl\">٤٥/٢٥</span>)؛ یعنی اگر آفتاب دلیل نبودی یعنی صورت که به فعل است - این سایه را - یعنی هیولای اعتباری وجود نبودی یعنی امری است عدمی . (از رساله ٔ قصة الغربة الغربیة وترجمه ٔ آن تألیف شیخ شهاب الدین سهروردی چ کربن ).<br /></font></div>'),
(176583, 'طرف العارض', '<span class=\"hlight\">طرف العارض .</span> <font color=\"DarkGreen\"><b>[ طَ فُل ْ رِ ]</font></b> (اِخ ) موضعی است به بلاد بنی تمیم و در محلی واقع است که آن را قرنین نامند و در آنجا حد طرف العارض که جلو مهب باد شمال است پایان می یابد. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٩٣</span>).<br /></font></div>'),
(176584, 'طرف العرف', '<span class=\"hlight\">طرف العرف .</span> <font color=\"DarkGreen\"><b>[ طَ فُل ْ ع ُ ]</font></b> (اِخ ) کوهی است بلند در داخل دریا واقع در ضلع دوم اندلس و قریب چهل میل از دریا را فراگرفته و کنیسةالغراب معروف بر آن کوه واقع است . (الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>).<br /></font></div>'),
(176585, 'طرف القیطال', '<span class=\"hlight\">طرف القیطال .</span> <font color=\"DarkGreen\"><b>[ طَ فُل ْ ]</font></b> (اِخ ) از جزیره ٔ فیران تا طرف القیطال مسافت <span class=\"hlight\" dir=\"rtl\">١٢</span> میل است . (الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(176586, 'طرف الناظور', '<span class=\"hlight\">طرف الناظور.</span> <font color=\"DarkGreen\"><b>[ طَ فُن ْ نا ]</font></b> (اِخ ) شهری است در اسپانیا. (الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(176587, 'طرف بربستن', '<span class=\"hlight\">طرف بربستن .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ب َ ت َ ]</font></b> (مص مرکب ) طرف بستن . کنایه از نفع یافتن و چیزی حاصل کردن باشد از کسی و جائی . (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br />بغیر آنکه بشد دین و دانش از دستم <br />دگر بگو که ز مِهرت چه طرف بربستم .<br /> <font color=\"Red\">حافظ.</font><br />پیداست ازآن میان چه بربست کمر<br />تا من ز کمر چه طرف خواهم بربست .<br /> <font color=\"Red\">حافظ.</font><br />چو شاخ بارور از باغ دهر اهل تمیز<br />بجز شکستگی خود چه طرف بربستند.<br /> <font color=\"Red\">طاهر وحید.</font><br />عمر ار کنی همه صرف زو برنبندی طرف <br />کاری است سخت شگرف باری است سخت گران .<br /> <font color=\"Red\">رعدی آذرخشی .</font><br /> <BR><font color=\"Blue\">◄</font> مقابل طرف شدن <span class=\"hlight\">:</span> <br />که پیش راه تو گیرد که طرف بربندد<br />چو بر سپاه مخالف روان کنی یکران .<br /><font color=\"Red\">سنجر کاشی .</font><br /></font></div>'),
(176588, 'طرف برداشتن', '<span class=\"hlight\">طرف برداشتن .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت َ ]</font></b> (مص مرکب ) بمعنی طرف بستن <span class=\"hlight\">:</span> <br />با اهل سخن نشین و طرفی بردار<br />از کیسه ٔ عمر نقد صرفی بردار<br />در معرکه ٔ هنر به نیروی سخن <br />با تیغزبانی سر حرفی بردار.<br /><font color=\"Red\">محسن تأثیر (از آنندراج ).</font><br /></font></div>'),
(176589, 'طرف بستن', '<span class=\"hlight\">طرف بستن .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ت َ ]</font></b> (مص مرکب ) طرف بربستن . حاصل کردن و فائده و نفع برداشتن، چه طرف بمعنی کلیچه ٔ کمر است و بستن آن موجب زینت است . (غیاث اللغات ) (آنندراج ). لکن اکثر بدین معنی به صله ٔ «از» آید و بعضی محققین و غیره بدین معنی بفتحتین بسته اند. در صحت آن تأمل است . (آنندراج ). سود بردن . پهلو یافتن از کسی <span class=\"hlight\">:</span> <br />طوطیان خاص را قندی است ژرف <br />طوطیان عام از این خود بسته طرف .<br /> <font color=\"Red\">مولوی .</font><br />نبندی زان میان طرفی کمروار<br />اگر خود را ببینی در میانه .<br /> <font color=\"Red\">حافظ.</font><br />کس به دور نرگست طرفی نبست از عافیت <br />به که نفروشند مستوری به مستان شما.<br /> <font color=\"Red\">حافظ.</font><br />طرف کرم ز کس نبست این دل پرامید من <br />گرچه سخن همی برد قصه ٔ من به هر طرف .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(176590, 'طرف ثغلال', '<span class=\"hlight\">طرف ثغلال .</span> <font color=\"DarkGreen\"><b>[ طَ ف ُ ث ِ ]</font></b> (اِخ ) جایگاهی است در اندلس . رجوع به الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩</span> شود.<br /></font></div>'),
(176591, 'طرف جنب الاسد', '<span class=\"hlight\">طرف جنب الاسد.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف ُ جَم ْ بِل ْ اَ س َ ]</font></b> (اِخ ) جای ستاره ٔ صرفه نزد منجمان .<br /></font></div>'),
(176592, 'طرف شام', '<span class=\"hlight\">طرف شام .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف ِ ]</font></b> (ترکیب اضافی، ق مرکب ) مرادف تنگ ِ شام . گیراگیر شام . تنگ غروب <span class=\"hlight\">:</span> <br />پیران تلاش رزق فزون از جوان کنند<br />حرص گدا شود طرف شام بیشتر.<br /><font color=\"Red\">صائب (از آنندراج ).</font><br /></font></div>'),
(176593, 'طرف شدن', '<span class=\"hlight\">طرف شدن .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ش ُ دَ ]</font></b> (مص مرکب ) مقابل و حریف شدن . (غیاث اللغات ). مقابل شدن <span class=\"hlight\">:</span> <br />ماه انداخت سپر تا طرف روی تو شد<br />کاست از غیرت و هم چشم به ابروی تو شد.<br /> <font color=\"Red\">طاهر غنی (از آنندراج ).</font><br />پیش مژگان درازت که هدف خواهد شد<br />چون تو بر طرف گر اُفتی که طرف خواهد شد.<br /><font color=\"Red\">طاهر غنی (از آنندراج ).</font><br /></font></div>'),
(176594, 'طرف صباحی', '<span class=\"hlight\">طرف صباحی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف ِ ص َ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به عرض وراب شود. (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(176595, 'طرف صبح', '<span class=\"hlight\">طرف صبح .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف ِ ص ُ ]</font></b> (ترکیب اضافی، ق مرکب ) مقابل طرف شام . صبح صادق . (آنندراج ).<br /></font></div>'),
(176596, 'طرف صحبت', '<span class=\"hlight\">طرف صحبت .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف ِ ص ُ ب َ ]</font></b> (ترکیب اضافی، اِ مرکب ) مصاحب و رفیق که با او اختلاط کنند. (آنندراج ).<br /></font></div>'),
(176597, 'طرف مثبت', '<span class=\"hlight\">طرف مثبت .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف ِ م ُ ب ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) در دعاوی حقوقی یا در مناظرات بر کسی اطلاق شود که مدعی است و میخواهد موضوع را به ثبوت رساند.<br /></font></div>'),
(176598, 'طرف منفی', '<span class=\"hlight\">طرف منفی .</span><font color=\"DarkGreen\"><b>[ طَ رَ ف ِ م َ ]</font></b> (ترکیب وصفی، اِ مرکب ) در مناظرات و دعاوی حقوقی بر کسی اطلاق شود که منکر موضوع است .<br /></font></div>'),
(176599, 'طرف گردیدن', '<span class=\"hlight\">طرف گردیدن .</span><font color=\"DarkGreen\"><b>[ طَ رَ گ َ دی دَ ]</font></b> (مص مرکب ) طرف شدن <span class=\"hlight\">:</span> <br />کار مردان نیست با نامرد گردیدن طرف <br />ورنه دستم از گریبان فلک کوتاه نیست .<br /><font color=\"Red\">صائب .</font><br /></font></div>'),
(176600, 'طرف گرفتن', '<span class=\"hlight\">طرف گرفتن .</span> <font color=\"DarkGreen\"><b>[ طَ گ ِ رِ ت َ ]</font></b> (مص مرکب ) مرادف طرف بستن از چیزی <span class=\"hlight\">:</span> <br />در ته سایه ٔ زلفی ننشینم هرگز<br />هیچ طرفی دلم از طرف کلاهی نگرفت .<br /><font color=\"Red\">علیقلی بیگ خراسانی (از آنندراج ).</font><br /></font></div>'),
(176601, 'طرف گرفتن', '<span class=\"hlight\">طرف گرفتن .</span> <font color=\"DarkGreen\"><b>[ طَرَ گ ِ رِ ت َ ]</font></b> (مص مرکب ) کنایه از حمایت کردن باشد.(برهان ) (غیاث اللغات ). جانب داری کردن <span class=\"hlight\">:</span> <br />وقت است که تابند رخ از جانب آتش <br />گیرند خلایق طرف ابروی آن را.<br /> <font color=\"Red\">جمال الدین سلمان (از آنندراج ).</font><br />نگرفته ز انصاف تو در معرکه ٔ لاف <br />شادی طرف شادی و غم جانب غم را.<br /> <font color=\"Red\">محمد عرفی .</font><br /><BR><font color=\"Blue\">◄</font> گوشه نشینی . (برهان ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> سرحدگیری . (برهان ).<br /></font></div>'),
(176602, 'طرف گیر', '<span class=\"hlight\">طرف گیر.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (نف مرکب ) آنکه طرف کسی نگاه دارد. طرفدار. حامی . حمایت کن .<br /></font></div>'),
(176603, 'طرف گیری', '<span class=\"hlight\">طرف گیری .</span> <font color=\"DarkGreen\"><b>[ طَ رَ گی ]</font></b> (حامص مرکب ) جانب داری . حمایت . طرفداری .<br /></font></div>'),
(176604, 'طرف یافتن', '<span class=\"hlight\">طرف یافتن .</span> <font color=\"DarkGreen\"><b>[ طَ ت َ ]</font></b> (مص مرکب ) طرف بستن . موفق شدن . سود بردن <span class=\"hlight\">:</span> چند بار آن مخاذیل نیرو کردند در حمله، اما هیچ طرفی نیافتند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٩</span>).<br /></font></div>'),
(176605, 'طرفات', '<span class=\"hlight\">طرفات .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) پسران عدی ّبن حاتم که طریف و طرفة و مطرف بودند و در جنگ صفین کشته شدند. (منتهی الارب ).<br /></font></div>'),
(176606, 'طرفاس', '<span class=\"hlight\">طرفاس .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) پاره ای از ریگ، یا ریگ پاره ای که در پهلوی درخت باشد. طرفسان مثله فیهما. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176607, 'طرفان', '<span class=\"hlight\">طرفان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) شهری است از بلاد ختا. رجوع به حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> شود. شهری است به حدود ختا. (فهرست ).<br /></font></div>'),
(176608, 'طرفان', '<span class=\"hlight\">طرفان .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) نزد فقهاء حنفیه عبارت از ابوحنیفه و محمد باشند و بدین نام نامیده شده اند برای آنکه یکی از آنان در طرف استادی و دیگری در طرف شاگردی واقع شده اند. (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(176609, 'طرفان', '<span class=\"hlight\">طرفان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دو ستاره اند درمقدم جبهه . (اقرب الموارد). و رجوع به طَرْف شود.<br /></font></div>'),
(176610, 'طرفان', '<span class=\"hlight\">طرفان .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع اِ) یکی از القاب بیست ودوگانه ٔ زحاف اشعار عرب که در اشعار عجم مستعمل است . و اگر از دو طرف فاعلاتن الف و نون بیفتد به معاقبت ماقبل و مابعد، آن را طرفان خوانند. (المعجم چ تهران ص <span class=\"hlight\" dir=\"rtl\">٣٥</span> و <span class=\"hlight\" dir=\"rtl\">٤٧</span>).<br /></font></div>'),
(176611, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (اِخ ) نام زنی بوده است معروفه <span class=\"hlight\">:</span> <br />از شمار تو کس طرفه بمهر است هنوز<br />وز شمار دگران چون در تیم دودر است .<br /><font color=\"Red\">لبیبی .</font><br /></font></div>'),
(176612, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (ع اِمص ) زخم رسیدگی چشم . اسم است مصدر را. <BR><font color=\"Blue\">◄</font> نوی مال . اسم است طریف و طارف و مطرف را که مال نو است . <BR><font color=\"Blue\">◄</font> (ص، اِ)طُرفه . شگفت و نادر از هر چیزی . طرافة مصدر است از آن . (منتهی الارب ) (آنندراج ). چیزی که کسی ندیده باشدو بنظر خوش آید و در مقام تعجب نیز گویند خواه دیده شود و خواه شنیده گردد. (برهان ): اِطراف ؛ طرفه آوردن . (تاج المصادر بیهقی ). استطراف ؛ طرفه شمردن . (منتهی الارب ) (تاج المصادر بیهقی ). نادر. امر عجیب . بلعجبی . بوالعجبی . شعبده . <BR><font color=\"Blue\">◄</font> بازیگر. (آنندراج ). مشعبد. بلکنجک . بوالکنجک . (فرهنگ اسدی ). <BR><font color=\"Blue\">◄</font> کودک خوش آینده . <BR><font color=\"Blue\">◄</font> مجازاً بمعنی معشوق . (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> مال نو. (منتهی الارب ) (آنندراج ). هر چیز نو و خوش <span class=\"hlight\">:</span> <br />ای طرفه ٔ خوبان من ای شهره ٔ ری <br />لب را به سر دزک بکن پاک از می .<br /> <font color=\"Red\">رودکی .</font><br />و این تُبع فُرودین که از پس او به ملک بنشست، کُنیت او ابوکرب بود، چون ملک یمن بر وی راست شد، آهنگ پادشاهی دیگر کرد و هر جائی که بودی پیروز آمدی و هر پادشاهی که خواستی بگرفتی ... ملک هند بدو رسول و هدیه فرستاد، پرنیان و عود و عنبر، و چیزهای طرفه که او چنان ندیده بود. آن رسول را گفت اینهمه چیزهای طرفه از زمین هندوستان خیزد... (ترجمه ٔ طبری بلعمی ).<br />برون کرد ز انگشتش انگشتری <br />نگینی بر اوطرفه چون مشتری .<br /> <font color=\"Red\">فردوسی .</font><br />یکی تلنگ بخواهم زدن به شعر کنون <br />که طرفه باشد از شاعران خاص تلنگ .<br /> <font color=\"Red\">روزبه (از حاشیه ٔ فرهنگ اسدی نخجوانی ).</font><br />چندین هزار نامه کز او یادگار ماند<br />وآن نامه های طرفه کز او یادگار ماند.<br /> <font color=\"Red\">فرخی .</font><br />باده ٔ لعل به دست اندر چون لعل عقیق <br />ساقی طرفه به پیش اندر چون طرفه صنم .<br /> <font color=\"Red\">فرخی .</font><br />استادم بونصر دو نسخت کرد این دو نامه را... و طُرفه آن بود که از عراق گروهی را با خویشتن بیاورده بودند... و ایشان را میخواستند که بر روی استادم برکشند که ایشان فاضلترند. (تاریخ بیهقی ). طرفه آن بود که با وزیر عتاب کرد که خوارزم در سر پسرت شد و وزیر را جز خاموشی روی نبود. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٦٩٦</span>). طرفه آنکه افاضل و مردمان هنرمند از سعایت و بطرایشان در رنجند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤١٥</span>). و دیگرروز از آنجا برداشت و طرفه آن آمد که آب هم نبود. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٦٣٠</span>). سالار بکتغدی گفت : طرفه آن است که در سرایهای محمودی خامل ذکرتر از این دو کس نبوده . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٢٠</span>). بر ما طرفه تر آن است که من خود از چنین کارها سخت دورم چنین که بینی وآلتونتاش اینهمه در گردن من <font color=\"DarkGreen\"><b>[ احمد حسن ]</font></b> کند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٢٢</span>). و طرفه تر آن آمد که بر خواجه عبدالصمد امیر بدگمان شد، به آن خدمتهای پسندیده که وی کرده بود. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٨٥</span>). طرفه تر آن بود که هم فرونمی ایستاد از استبداد و فرو توانست ایستاد که تقدیر آفریدگار جل جلاله در کمین نشسته بود. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٥٧٥</span>).<br />کس ندیده ست چنین طرفه زناشوئی <br />نه زنی هرگز زاده ست بدین آئین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />این طرفه ترکه روز و شبان میکنم طلب <br />من زندگی ایشان و ایشان دمار من .<br /> <font color=\"Red\">ناصرخسرو.</font><br />به مرغزار قضا از درخت یأس و امل <br />دو شاخ طرفه دمد برگ و بار از آتش و آب .<br /> <font color=\"Red\">مسعودسعد.</font><br />طرفه مردی ام چندین چه غم عمر خورم <br />چون یقینم که سرانجام من از عمرفناست .<br /><font color=\"Red\">مسعودسعد.</font><br />آتش ار هیزم کند کم در طبیعت طرفه نیست <br />آتشی کو هیزم افزاید همی این طرفه تر.<br /> <font color=\"Red\">سنایی .</font><br />دوش سرمست نگارین من آن طرفه پسر<br />با یکی پیرهن زورقی طرفه بسر<br />از سر کوی فرودآمد متواری وار<br />کرده از غایت دلتنگی ازاین گونه خطر.<br /> <font color=\"Red\">سنایی .</font><br />می نخوانی مرا و طرفه تر آنک <br />نامه ٔ نانوشته میخوانی .<br /> <font color=\"Red\">مکی طولانی .</font><br />هر روز دجله دجله ببارم من از دو چشم <br />کو طرفه طرفه گل شکفاند به بوستان .<br /> <font color=\"Red\">ادیب صابر.</font><br />رنگ است رنگ رنگ همه کوه و کوهسار<br />طرفه است طرفه طرفه همه جوی و جویبار.<br /> <font color=\"Red\">عمعق .</font><br />منظر ماه منیر بر سر سرو سهی <br />طرفه و نادر بود خاصه به مشکین کمند.<br /> <font color=\"Red\">سوزنی .</font><br />دی جانب زرغون به یکی راه گذر بر<br />افتاد دو چشمم به یکی طرفه پسر بر.<br /> <font color=\"Red\">سوزنی .</font><br />جوجو شدی برابر آن مشک و طرفه آنک <br />هرجا که مشک بینی جوجو برابر است .<br /> <font color=\"Red\">خاقانی .</font><br />نای چو زاغ کنده پر نغزنوا چو بلبلان <br />زاغ که بلبلی کند طرفه نوای نو زند.<br /> <font color=\"Red\">خاقانی .</font><br />جام پری در آهن است از همه طرفه تر ولی <br />نقش پری به شیشه بین سحرنمای زندگی .<br /> <font color=\"Red\">خاقانی .</font><br />خواجه اسعد چو می خورد پیوست <br />طرفه شکلی شود چو گردد مست .<br /> <font color=\"Red\">خاقانی .</font><br />چون منوچهر از جهان شه طرفه نیست <br />کز جهان شاه اخستان خواهد گشاد.<br /> <font color=\"Red\">خاقانی .</font><br />عبارتش همه چون آفتاب و طرفه تر آن <br />که نعش و پروین چون آفتاب شد پیدا.<br /> <font color=\"Red\">خاقانی .</font><br />ازآدمی چه طرفه که ماهی در آب نیز<br />جان را ز حرص در سر کار دهان کند.<br /> <font color=\"Red\">خاقانی .</font><br />زآن بنا کاصل آن خیالی بود<br />طرفش آمد که طرفه خالی بود.<br /> <font color=\"Red\">نظامی .</font><br />طرفه آن شد که دختری است چو ماه <br />نرم و نازک چو خز و قاقم شاه .<br /> <font color=\"Red\">نظامی .</font><br />نخست ارچه لب بود و آنگاه دندان <br />ببین تا چه طرفه است این حال یارب .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />حرفهای طرفه بر لوح خیال <br />برنوشته چشم و ابرو خط و خال .<br /> <font color=\"Red\">مولوی .</font><br />طرفه کور دوربین تیزچشم <br />لیک از اشتر نبیند غیر پشم .<br /> <font color=\"Red\">مولوی .</font><br />این طرفه حکایتی است بنگر<br />روزی مگر از قضا سکندر<br />میرفت و همه سپاه با او<br />صد حشمت و ملک و جاه با او.<br /> <font color=\"Red\">سیدحسینی سادات .</font><br />طرفه باشد چو موی بر دیبا<br />ناز کردن ز روی نازیبا.<br /> <font color=\"Red\">اوحدی .</font><br />از رنج کسی به گنج وصلت نرسد<br />وین طرفه که بی رنج کس آن گنج ندید.<br /> <font color=\"Red\">(از بهارستان جامی ).</font><br />بیا ای بریشم زن طرفه روی <br />که هم طرفه روئی و هم طرفه موی .<br /> <font color=\"Red\">هاتفی .</font><br />عالم بیخبری طرفه بهشتی بوده ست <br />حیف و صد حیف که ما دیر خبردار شدیم .<br /> <font color=\"Red\">صائب .</font><br />خلقی ز پی بهشت بی آرامند<br />وین طرفه که نیست جز در آرام بهشت .<br /> <font color=\"Red\">؟</font><br />آدمیزاده طرفه معجونی است <br />کز فرشته سرشته وز حیوان .<br /> <font color=\"Red\">؟</font><br />و رجوع به فرهنگ شعوری ص <span class=\"hlight\" dir=\"rtl\">١٦٩</span> شود. <BR><font color=\"Blue\">◄</font> نزد بلغاء آن است که خارق عادت و یا اخلاق معتاد را ذکر کند، بر وجهی که متضمن حسن و لطافت باشد و لفظ طرفه و عجب و آنچه بمعنی اوست آوردن لازم است، لفظاً یا تقدیراً. مثاله <span class=\"hlight\">:</span> <br />قبه ها آراسته دیوارها از جزو و کل <br />مفرش از دیبابساط از پرنیان آورده اند<br />نخل ز ابریشم گل از زر بار از در و گهر<br />نوبهار طرفه از فصل خزان آورده اند.<br />کذا فی جامع الصنایع. (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(176613, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طَ رِ ف َ ]</font></b> (ع ص ) ناقةٌ طرفة؛ شتر ماده ای که بر یک چراگاه قرار نگیرد. <BR><font color=\"Blue\">◄</font> ناقه ای که فروریخته باشد نوک دهن او از پیری . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> اشتری که بر کناره ٔ مرغزار چرا کند. (مهذب الاسماء).<br /></font></div>'),
(176614, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (ع اِ) یک بار جنبانیدن پلک چشم را. یقال : هو اسرع من طرفة عین . (منتهی الارب ) (آنندراج ). یک چشم بهم زدن . یک زخم چشم .<br /></font></div>'),
(176615, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (ع اِ) نقطه ٔسرخی از خون بسته در چشم که از ضربت و جز آن حادث گردد. (منتهی الارب ) (آنندراج ). نقطه ای سرخ باشد یا کبود که بر سپیده ٔ چشم افتد. (ذخیره ٔ خوارزمشاهی ). و آن سرخی باشد که اندر چشم پدید آید بسبب زخمی و رنجی که به چشم رسد. (ذخیره ٔ خوارزمشاهی ). تورک و آن نقطه ٔ سرخ است که در بیماریهای چشم یا در پی ضربتی به ظاهر چشم افتد. نقطه ای سرخ در چشم، از ضربتی یا جز آن . و رجوع به تذکره ٔ داود ضریر انطاکی و قانون شیخ الرئیس چ تهران کتاب سوم ص <span class=\"hlight\" dir=\"rtl\">٦٦</span> شود. <BR><font color=\"Blue\">◄</font> گل مُژه . <BR><font color=\"Blue\">◄</font> داغی است مانا به خط که اطراف ندارد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176616, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف َ ]</font></b> (ع اِ) یک درخت گز، واحد طرفاء است . و بها لقب طرفةبن العبد. (منتهی الارب ).<br /></font></div>'),
(176617, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (اِخ ) ستاره ای است . (منتهی الارب ) (آنندراج ). دو کوکب خرد است، یکی از صورت اسد است و ماه برابر آن رسد و جنوبی او را بپوشاند و عرب گویند که این طرف اسد است که ایشان را از کواکب پنجگانه ٔ اسد خوانند و آن منزل نهم است از منازل قمر و رقیب آن سعدبلع است . (جهان دانش ص <span class=\"hlight\" dir=\"rtl\">١١٨</span>). مجموع دو کوکب که یکی بر پای جنوبی خرچنگ و دیگری بر بینی اسد جای دارد و آن منزل نهم از منازل بیست وهشتگانه ٔ ماه و از رباط اول است . نام کوکبی از کواکب صورت برج اسد است و آن از قدر اول است . (از جهان دانش ). منزل نهم است از منازل قمر و آن از آخر نثره است تا بیست وپنج درجه و چهل ودو دقیقه و پنجاه ویک ثانیه از سرطان و نزد احکامیان منزلی نحس است و بعضی گفته اند سعد است <span class=\"hlight\">:</span> <br />نثره به نثار گوهرافشان <br />طرفه طرفی دگر زرافشان .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(176618, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (اِخ ) دختر عبداﷲ مادر احمد. (منتهی الارب ).<br /></font></div>'),
(176619, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف َ ]</font></b> (اِخ ) مسجدی است به قرطبه از بلاد اندلس . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>). مسجد طرفة در قرطبة است . (منتهی الارب ).<br /></font></div>'),
(176620, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف َ ]</font></b> (اِخ ) ابن الاةبن نضرةالفلتان بن منذر. شاعری بوده است . (منتهی الارب ).<br /></font></div>'),
(176621, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف َ ]</font></b> (اِخ ) خزیمی، ازبنی خزیمةبن رواحة. شاعری بوده است . (منتهی الارب ).<br /></font></div>'),
(176622, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[طَ رَ ف َ ]</font></b> (اِخ ) خضرمی . محدث است . (منتهی الارب ).<br /></font></div>'),
(176623, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف َ ]</font></b> (اِخ ) عامری، از بنی عامربن ربیعه . شاعری بوده است . (منتهی الارب ).<br /></font></div>'),
(176624, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف َ ]</font></b> (اِخ ) لقب عمروبن العبد عبدی . شاعری بوده که بر اثر گفتن این شعر:<br />لاتعجلا بالبکاء الیوم مطرفا<br />ولا امیریکما بالدار اذ وقفا<br />وی را طرفة لقب نهادند. (منتهی الارب ). وی از شعراء جاهلیت و سراینده ٔ دومین قصیده از قصائد معلقات سبع است و از قبیله ٔ ربیعه بوده است . و وی را دیوانی است . در تاج العروس نسب طرفة العبدی را بدین سیاق آورده است : طرفةبن العبدبن سفیان بن سعدبن مالک بن ضبیعةبن قیس بن ثعلبةالحصن، و اسمه عمرو. لکن در معجم المطبوعات بدین نحو نسب او را آورده است : هو ابن عمر، طرفةبن عمربن بکر وائل بن ربیعةبن اخت جریربن عبدالمسیح المعروف بالمتلمس . صاحب بلوغ الارب گوید:وی نیکوترین شعرای قصیده سرای است و جز قصیده ٔ معلقه وی را شعر نیکو باشد، اما در نزد روات اشعار از گفته های وی و اشعار عبیدبن الابرص، جز اندکی یافت نشود. در سن بیست وشش سالگی کشته شد و قاتل او عمروبن هند یکی از پادشاهان حیره بود و افسانه ٔ کشته شدن وی را ابن قتیبه در کتاب الشعر و الشعراء آورده است . و ابن السکیت در شرح دیوان طرفه این قصه را از ابن قتیبه مبسوطتر ذکر کرده است . گویند نخستین شعری که طرفه گفت آن بود که وقتی با عم خویش سفری کرد، در یکی از منازل بین راه دامی بر پا داشت هنگام کوچ این ارجوزه بگفت :<br />یا لک من قبرة بمعمر<br />خلا لک الجو فبیضی و اصفری !<br />و نقری ما شئت ان تنقری <br />قد رفع الفخ فماذا تحذری <br />لابد یوماً ان تصادی فاصبری .<br />و از اشعار وی که در حکم مَثَل سائر است این بیت است :<br />سَتُبْدی لک الایام ُ ما کنت َ جاهلاً<br />و یأتیک بالاخبار مَن لم تُزَوّدِ.<br />و از مثلهائی که در نکوهش دوستان گفته این دو بیت است :<br />کل خلیل کنت خاللته <br />لاترک اﷲ له واضحه ْ<br />کلهم اروغ من ثعلب <br />ما اشبه اللیلةَ بالبارحه ْ.<br />و باز از امثال سائره ٔ اوست که به عمروبن هند خطاب کرده گوید:<br />ابامنذر افنیت فاستبق بعضنا<br />حنانیک بعض الشر اهون من بعض .<br /> <font color=\"Red\">(بلوغ الارب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١١٠</span>).</font><br />صاحب معجم المطبوعات آورده که : طرفه شاعری جاهلی است و نبوغ او در شعر ازآغاز جوانی نمودار گشت تا به حدی که در همان فصل اززندگانی در ردیف اولین طبقه ٔ شعرا بشمار میرفت، در کودکی به میخوارگی و لهو و لعب اشتغال داشت و آنچه داشت در آن راه صرف میکرد. آثار او: <span class=\"hlight\" dir=\"rtl\">١</span> - دیوان وی در غریفسوالد بسال <span class=\"hlight\" dir=\"rtl\">١٨٦٩</span> م . و در برلین بسال <span class=\"hlight\" dir=\"rtl\">١٨٩٥</span> م . با شرح اعلم الشنتمری و در شالون بسال <span class=\"hlight\" dir=\"rtl\">١٩٠٠</span> به همت پروفسور سِلگسون به طبع رسیده و با طبع شالون ترجمه ٔ فرانسه نیز ضمیمه است، نوبتی هم بسال <span class=\"hlight\" dir=\"rtl\">١٩٠٩</span> در قازان دیوان وی که به روایت ابن السکیت بوده با شرحی از شیخ احمدبن الامین الشنقیطی چاپ شده است . <span class=\"hlight\" dir=\"rtl\">٢</span> - قصیده ٔ معلقه ٔوی با شرح زوزنی به اعتناء و جهد ریسکی و وولرس بسال <span class=\"hlight\" dir=\"rtl\">١٨٢٩</span> در بن به طبع رسیده و نخست قسمتی از این قصیده بسال <span class=\"hlight\" dir=\"rtl\">١٧٤٢</span> بوسیله ٔ ریسکی در لیدن چاپ شده بود که شروحی بزبان لاتین و لامیةالعجم طغرائی را هم ضمیمه داشت . <span class=\"hlight\" dir=\"rtl\">٣</span> - معلقه ٔ طرفةبن العبد با شرح زوزنی نوبتی دیگردر بن بسال <span class=\"hlight\" dir=\"rtl\">١٨٢٩</span> به طبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">١</span> ستون <span class=\"hlight\" dir=\"rtl\">١٣٩</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٣٩</span>). و رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٦</span> و فهرست اعلام عقدالفرید و الموشح ص <span class=\"hlight\" dir=\"rtl\">١٧</span>، <span class=\"hlight\" dir=\"rtl\">٥٤</span>، <span class=\"hlight\" dir=\"rtl\">٥٥</span>، <span class=\"hlight\" dir=\"rtl\">٥٧</span>، <span class=\"hlight\" dir=\"rtl\">٥٨</span>، <span class=\"hlight\" dir=\"rtl\">٧٦</span>، <span class=\"hlight\" dir=\"rtl\">٧٧</span>، <span class=\"hlight\" dir=\"rtl\">٨٧</span>، <span class=\"hlight\" dir=\"rtl\">٨٩</span>، <span class=\"hlight\" dir=\"rtl\">١٨٥</span>، <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> و لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣</span> و المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٣٨</span>، <span class=\"hlight\" dir=\"rtl\">٣٩</span>، <span class=\"hlight\" dir=\"rtl\">٥٤</span> و عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٩</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٣</span>، <span class=\"hlight\" dir=\"rtl\">١٩٠</span> و ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨</span> شود.<br /></font></div>'),
(176625, 'طرفة', '<span class=\"hlight\">طرفة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف َ ]</font></b> (اِخ ) ابن عرفجة. صحابی است . اصیب انفه ُ یوم الکلاب فاتخذها من ورق فأنتن، فرخص له فی الذهب . (منتهی الارب ). و رجوع به الاصابة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٤</span> شود.<br /></font></div>'),
(176626, 'طرفدار', '<span class=\"hlight\">طرفدار.</span> <font color=\"DarkGreen\"><b>[ طَ رَ]</font></b> (نف مرکب، اِ مرکب ) کنایه از پادشاهان است . (برهان ). پادشاه عظیم الشأن . (غیاث اللغات ) (آنندراج ). و طرفدار عالم چهار بودند: اول کیومرث، دوم کیقباد، سوم کیکاوس، چهارم کیخسرو. (آنندراج ). <BR><font color=\"Blue\">◄</font> حاکم . (آنندراج ). حکام . (برهان ). حاکم سرحدنشین . (غیاث اللغات ). سرحدنشین . (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br />طرفداران ز سقسین تا سمرقند<br />به نوبتگاه درگاهش کمربند.<br /> <font color=\"Red\">نظامی .</font><br />طرفدار مغرب به مردانگی <br />قدرخان مشرق به فرزانگی .<br /> <font color=\"Red\">نظامی .</font><br />طرفها به شاهان گرفتار کن <br />به هر سو یکی راطرفدار کن .<br /> <font color=\"Red\">نظامی .</font><br />خرامان شده خسرو خسروان <br />طرفدار چین در رکابش روان .<br /><font color=\"Red\">نظامی .</font><br />طرفدار چون شد به فرمان تو<br />طرف بر طرف هست ملک آن تو.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> جاگیردار. زمین دار. (برهان ) (آنندراج ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br />صفدر و بر ستاره صفدارت <br />باج شاهان خورد طرفدارت .<br /> <font color=\"Red\">طالب آملی .</font><br /><BR><font color=\"Blue\">◄</font> جانب دار. آنکه جانب کسی نگه دارد. حامی <span class=\"hlight\">:</span> مانند یک نفر طرفدار و خبره ٔ صنعت شناس به او نگاه کرد. (سایه روشن صادق هدایت ص <span class=\"hlight\" dir=\"rtl\">١٦</span>).<br /></font></div>'),
(176627, 'طرفدار انجم', '<span class=\"hlight\">طرفدار انجم .</span> <font color=\"DarkGreen\"><b>[ طَ رَ رِ اَ ج ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از آفتاب عالمتاب است . (برهان ) (آنندراج ) (انجمن آرای ناصری ). و رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">١٣</span> شود.<br /></font></div>'),
(176628, 'طرفدار پنجم', '<span class=\"hlight\">طرفدار پنجم .</span> <font color=\"DarkGreen\"><b>[ طَ رَ رِ پ َ ج ُ ]</font></b> (اِخ ) کنایه از ستاره ٔ مریخ است، چه فلک پنجم جای اوست . (برهان ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> پادشاه ترکستان را نیز گویند، بسبب آنکه اقلیم پنجم در تصرف اوست . (برهان ) (آنندراج ) (انجمن آرای ناصری ) <span class=\"hlight\">:</span> <br />جهان خسروا زیر هفت آسمان <br />طرفدار پنجم توئی بی گمان .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(176629, 'طرفداری', '<span class=\"hlight\">طرفداری .</span> <font color=\"DarkGreen\"><b>[ طَرَ دا ]</font></b> (حامص مرکب ) جانب داری . حمایت . (آنندراج ).<br /></font></div>'),
(176630, 'طرفسان', '<span class=\"hlight\">طرفسان .</span> <font color=\"DarkGreen\"><b>[ طِ ف ِ]</font></b> (ع اِ) پاره ای از ریگ . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> ریگ بزرگ . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> ریگ پاره ای که در پهلوی درخت باشد. <BR><font color=\"Blue\">◄</font> تاریکی . (منتهی الارب ) (آنندراج ). و رجوع به طرفاس شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(176631, 'طرفسة', '<span class=\"hlight\">طرفسة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ س َ]</font></b> (ع مص ) تیز نگریستن . <BR><font color=\"Blue\">◄</font> بشکستن نگاه را. <BR><font color=\"Blue\">◄</font> پوشیدن جامه های بسیار. <BR><font color=\"Blue\">◄</font> تاریک گردیدن شب : طرفس اللیل . <BR><font color=\"Blue\">◄</font> تیره گشتن آبخور: طرفس المورد. <BR><font color=\"Blue\">◄</font> بسیار شدن آیندگان بر آبخور: طرفس الماء. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176632, 'طرفلیان', '<span class=\"hlight\">طرفلیان .</span> <font color=\"DarkGreen\"><b>[ طِ ف ِل ْ لیا ]</font></b> (اِخ ) قومی بودند که از آشور فرستاده شدند تا سامره را متأهل سازند (عزرا <span class=\"hlight\" dir=\"rtl\">٤</span>:<span class=\"hlight\" dir=\"rtl\">٩</span>). (قاموس کتاب مقدس ).<br /></font></div>'),
(176633, 'طرفها داشتن حرف', '<span class=\"hlight\">طرفها داشتن حرف .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ت َن ِ ح َ ]</font></b> (مص مرکب ) آن است که یکی کلمه چند معانی و کنایه داشته باشد. آقا اسماعیل کاشف صفاهانی راست :<br />آویخته زلف مشکبواز چپ و راست <br />این مصرع رنگین چه طرفها دارد.<br />پوشیده نماند که زلف را مصرع رنگین گفتن خالی از غرابت نیست بلی اگر مصرع پیچیده می بست طرف لطف داشت . (آنندراج ).<br /></font></div>'),
(176634, 'طرفوزن', '<span class=\"hlight\">طرفوزن .</span> <font color=\"DarkGreen\"><b>[ طَ زَ ]</font></b> (نف مرکب ) کنایه از چوبدار و چاوش و یساولی باشد که پیش پیش امرا و سلاطین رود و مردم را از میان راه به طرفی نهیب دهد. (برهان ). این کلمه تصحیفی است از «طرقوازن » که جزء اول آن فعل امر مخاطب صیغه ٔ جمع مذکر از تطریق یعنی بر کنار و دور شوید و جزء دوم آن مخفف زننده است که من حیث المجموع «دورباش گو» به صیغه ٔ فاعلی معنی دهد. رجوع به طرقوازن شود.<br /></font></div>'),
(176635, 'طرفک', '<span class=\"hlight\">طرفک .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (اِخ ) کوهی است در اطراف و نواحی طارم گیلان . (ذیل جامعالتواریخ رشیدی ص <span class=\"hlight\" dir=\"rtl\">١٤</span>).<br /></font></div>'),
(176636, 'طرفگاه', '<span class=\"hlight\">طرفگاه .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ مرکب ) مراد از دنیا.(آنندراج از فرهنگ اسکندرنامه ٔ نظامی ) <span class=\"hlight\">:</span> <br />دو پروانه بینم در این طرفگاه <br />یکی روسپید است و دیگر سیاه .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(176637, 'طرفگی', '<span class=\"hlight\">طرفگی .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (حامص ) بازیگری <span class=\"hlight\">:</span> <br />شهید طرفگی خوی گلعذارانم <br />صبا به مشهدم آردز لاله زار چراغ .<br /> <font color=\"Red\">سلطان علی بهی .</font><br />کنند خال و خطت از برای بردن دل <br />هزار طرفگی و صد هزار بوالعجبی .<br /> <font color=\"Red\">بدیعی سمرقندی (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> شگرفی .<br /></font></div>'),
(176638, 'طرفی', '<span class=\"hlight\">طرفی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف َ ]</font></b> (ع اِ) طرفین . دو طرف و بدین صورت در حال اضافه آورند، مانند: طرفی النقیض <span class=\"hlight\">:</span> بطرفی افراط و تفریط. (شمس قیس در المعجم ).<br /></font></div>'),
(176639, 'طرفیت', '<span class=\"hlight\">طرفیت .</span> <font color=\"DarkGreen\"><b>[ طَ رَ فی ی َ ]</font></b> (ع مص جعلی، اِمص ) روبارو و مقابل و مواجه شدن . طرف بودن .<br /></font></div>'),
(176640, 'طرفین', '<span class=\"hlight\">طرفین .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ف َ ]</font></b> (ع اِ) تثنیه ٔ طرف . دو طرف . دو کرانه . (فرهنگستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کریم الطرفین </span> ؛ نیک اصل از پدر و مادر. (مهذب الاسماء).<br /><BR><font color=\"Blue\">◄</font> دو طرف . دو حد. مقدمتین قیاس که مشترک بین آن دو نباشد.<br /></font></div>'),
(176641, 'طرق', '<span class=\"hlight\">طرق .</span> <font color=\"DarkGreen\"><b>[ طُ رُ ]</font></b> (اِخ ) دهی از دهستان تکاب بخش ریوش شهرستان کاشمر، در سه هزارگزی باختر ریوش، سر راه مالرو عمومی ریوش به بردسکن . کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">١٤١٥</span> تن سکنه . شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176642, 'طرق', '<span class=\"hlight\">طرق .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام کتابی هندی که به عربی نقل شده است . (فهرست ابن الندیم ).<br /></font></div>'),
(176643, 'طرق', '<span class=\"hlight\">طرق .</span> <font color=\"DarkGreen\"><b>[ طُ رُ ]</font></b> (ع اِ) ج ِ طریق . راهها.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">وزارت طرق </span> ؛ وزارتی که اداره ٔ شاهراه ها کند به ساختن و ترمیم . وزارت راه . (فرهنگستان ).<br /><BR><font color=\"Blue\">◄</font> نحوه ها. نمطها <span class=\"hlight\">:</span> ارتفاعات آن را حاصل میکند و به سبل و طرق آن میرساند. (تاریخ بیهقی ). و اوقاف اجداد و آباء ایشان هم از پرگار افتاده، و طرق و سبل آن بگردیده . (تاریخ بیهقی ). از اوقاف این تربت نیکو اندیشه باید داشت تا به طرق و سبل رسد. (تاریخ بیهقی ).<br /></font></div>'),
(176644, 'طرق', '<span class=\"hlight\">طرق .</span> <font color=\"DarkGreen\"><b>[طَ رِ ]</font></b> (ع ص ) فال سنگک گیرنده . رجوع به طرقات شود.<br /></font></div>'),
(176645, 'طرق', '<span class=\"hlight\">طرق .</span> <font color=\"DarkGreen\"><b>[ طُ رُ ]</font></b> (اِخ ) قصبه ٔمرکز شهرستان طرق رود بخش نطنز شهرستان کاشان در <span class=\"hlight\" dir=\"rtl\">٣٢</span>هزارگزی جنوب باختری نطنز و یکهزارگزی شمال شوسه ٔ نطنز به مورچه خورت . کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٤٤٣٠</span> تن سکنه .آب آن از <span class=\"hlight\" dir=\"rtl\">١٧</span> رشته قنات . محصول آنجا غلات و میوه جات وحبوبات و انگور. شغل مردان زراعت و گله داری است و عده ای برای تأمین معاش به تهران رفته برمیگردند. صنایع دستی آن گیوه چینی و تخت کشی است . تلفن و دبستان و راه فرعی به شوسه دارد. قلعه ٔ خرابه و مسجد آن قدیمی است . مزارع یحیی آباد و باقرآباد و هنجوه و ایل آباد جزء این قصبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>). و یاقوت آرد: قریه ای است از اعمال اصبهان نزدیک نطنزة، جایی است بزرگ مانند شهری، بین آن و اصبهان بیست فرسنگ مسافت میباشد. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>). طرق درجنوب نطنز و در کنار راه نطنز به مورچه خورت میان یاهپود و گردنه ٔ طرق در <span class=\"hlight\" dir=\"rtl\">٣٣٣٠٠</span>گزی نطنز واقع شده است .<br /></font></div>'),
(176646, 'طرق', '<span class=\"hlight\">طرق .</span> <font color=\"DarkGreen\"><b>[ طُ رُ ]</font></b> (اِخ ) نام محلی در <span class=\"hlight\" dir=\"rtl\">١٦٤٠٠</span>متری مشهد، بین مشهد و جیم آباد، کنارراه مشهد به کاریز و برای کسی که از طریق نیشابور عازم مشهد باشد، میان باج ساروق و مشهد و در <span class=\"hlight\" dir=\"rtl\">٩٠٨٩٠٠</span>متری طهران و در جنوب مشهد واقع است . و هر گاه از مشهدعازم تربت حیدریه باشند طرق میان مشهد و باج ساروق واقع و <span class=\"hlight\" dir=\"rtl\">١١٠٥٠</span>متری مشهد است . قریه ای است به دوفرسنگی مشهد رضا علیه السلام بین راه طهران و مشهد. و رجوع به تروق و حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٣</span> و <span class=\"hlight\" dir=\"rtl\">٣١٤</span> و تاریخ افشاریه و زندیه موسوم به مجمل التواریخ ص <span class=\"hlight\" dir=\"rtl\">٩٥</span> و <span class=\"hlight\" dir=\"rtl\">٣١٦</span> شود. دهی از دهستان تبادکان بخش حومه ٔ شهرستان مشهد در <span class=\"hlight\" dir=\"rtl\">٧٠</span>هزارگزی جنوب مشهد سر راه شوسه ٔ شهنه به نیشابور. جلگه، معتدل، با <span class=\"hlight\" dir=\"rtl\">٥٥٤١</span> تن سکنه . آب آن از رودخانه، محصول آنجا غلات و شغل اهالی زراعت و مالداری و راه آن اتومبیل رو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176647, 'طرق', '<span class=\"hlight\">طرق .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع مص ) نوشیدن آب مکدر را. یقال : طرق طرقاً. <BR><font color=\"Blue\">◄</font> توبرتو شدن پر مرغ . (منتهی الارب ). بر هم نشستن پر مرغ . (زوزنی ) (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> (اِمص ) سستی زانوی شتر. (منتهی الارب ). ضعف الرکبتین . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> کجی در ساق شتر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> از عیوب بدنی اسب است چنانکه دو زانوی آن باز وگشاده مانند دو کمانه باشد و آن عیب فاحشی است . (ازصبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦</span>). <BR><font color=\"Blue\">◄</font> (اِ) نورد مشک . <BR><font color=\"Blue\">◄</font> نورد شکم . ج، اطراق . <BR><font color=\"Blue\">◄</font> جای گرد آمدن آب . <BR><font color=\"Blue\">◄</font> دام صیاد. (منتهی الارب ).<br /></font></div>'),
(176648, 'طرق', '<span class=\"hlight\">طرق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) زدن . <BR><font color=\"Blue\">◄</font> زدن به مطرقه . کوفتن . <BR><font color=\"Blue\">◄</font> فال سنگک زدن کاهن . (منتهی الارب ) (آنندراج ). سنگ فال زدن . سنگ زدن کاهن . (زوزنی ). و اصله الضرب، و منه سمیت المطرقة. (زوزنی ) <span class=\"hlight\">:</span> الطرق و الطیرة و العیافة من الجبت ؛ سنگک زدن و تشأم کردن به چیز و زجر مرغ ازجمله ٔ جبت است . (تفسیر ابوالفتوح رازی ). <BR><font color=\"Blue\">◄</font> برکندن موی . <BR><font color=\"Blue\">◄</font> بول انداختن ستور در آب ایستاده . <BR><font color=\"Blue\">◄</font> فرودآمدن غم کسی را به شب . <BR><font color=\"Blue\">◄</font> (اِ) پشم . <BR><font color=\"Blue\">◄</font> (مص ) پشم زدن به چوب جهت واخیدن . (منتهی الارب ) (آنندراج ). دو معنی اخیر را صاحب تاج العروس بدین سیاق آورده : و الطرق ؛ نتف الصوف او الشعر، او ضربه بالقضیب لینتفش . از این رو از لفظ طرق در تاج العروس استنباط معنی مطلق پشم نمیشود. پنبه و پشم به چوب زدن تا واخیده گردد. (زوزنی ). به چوب زدن پشم . (دهار). <BR><font color=\"Blue\">◄</font> آمیختن جادوگر پنبه را با پشم وقت جادوگری . <BR><font color=\"Blue\">◄</font> برجستن گشن بر ماده . (منتهی الارب ) (آنندراج ). گشنی کردن شتر. (زوزنی ). <BR><font color=\"Blue\">◄</font> به شب آمدن کسی را. طروق مثله فیهما. <BR><font color=\"Blue\">◄</font> سست عقل شدن . یقال : طُرِق َ الرجل مجهولاً. <BR><font color=\"Blue\">◄</font> (اِمص ) سستی عقل . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) آب گشن اشتر.(مهذب الاسماء). ماءالفحل . (تاج العروس ). آب منی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> گشن . سمی بالمصدر. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> هر آواز یانغمه ٔ رباب و مانند آن طرقهای جداگانه است . یقال : تضرب هذه الجاریة لک هکذا طرقاً. <BR><font color=\"Blue\">◄</font> خرمابن . لغت طائی است . <BR><font color=\"Blue\">◄</font> یک بار. یقال : اختضبت المراءة طرقاً، او طرقین، و طرقةً او طرقتین ؛ ای مرةً، او مرتین . (منتهی الارب ) (آنندراج ). و یُضَمّان . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دام و مانند آن . (منتهی الارب ) (آنندراج ). و یُکْسَر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> طرق آب شور. <BR><font color=\"Blue\">◄</font> آب باران و جز آن که در وی شتران کمیز انداخته باشند، و منه قول ابراهیم : الوضوء بالطرق احب الی ّ من التیمم . (منتهی الارب ) (آنندراج ). آب ستوردررفته و میزک کرده . (مهذب الاسماء).<br /></font></div>'),
(176649, 'طرق', '<span class=\"hlight\">طرق .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) آبی است مر بنی وقبی را. (منتهی الارب ). موضعی است که تا وقباء پنج میل راه باشد. (معجم البلدان ).<br /></font></div>'),
(176650, 'طرق', '<span class=\"hlight\">طرق .</span> <font color=\"DarkGreen\"><b>[ طُ رَ ]</font></b> (ع اِ) ج ِ طرقة.<br /></font></div>'),
(176651, 'طرق', '<span class=\"hlight\">طرق .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) پیه . (منتهی الارب ) (آنندراج ). به عربی شحم است . (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> (اِمص ) توانائی . (منتهی الارب ) (آنندراج ). قوت . <BR><font color=\"Blue\">◄</font> فربهی . (منتهی الارب ) (آنندراج ). چاقی . سمن .<br /></font></div>'),
(176652, 'طرق', '<span class=\"hlight\">طرق .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طراق و طریق . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ اطرق . (اقرب الموارد).<br /></font></div>'),
(176653, 'طرق رود', '<span class=\"hlight\">طرق رود.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام یکی از دهستانهای بخش نطنز شهرستان کاشان است . این دهستان در جنوب نطنز در دامنه و دره های کوه کرکس در طول و طرفین جاده ٔ شوسه ٔ اردستان به مورچه خورت واقع است . هوای آن سردسیر، آب آن از چشمه سار و زه آب رودخانه و قنوات .محصول عمده ٔ آن انگور و غلات و حبوبات و انواع میوه جات سردسیری است . این دهستان از <span class=\"hlight\" dir=\"rtl\">١٥</span> آبادی و چندین مزرعه تشکیل شده و جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">١٤</span> هزار تن و قراء مهم آن بشرح زیر است : قصبه ٔ طرق کلهرود، سه، طار، کنته، ابیازن، نیه . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(176654, 'طرقات', '<span class=\"hlight\">طرقات .</span> <font color=\"DarkGreen\"><b>[ طُ رُ ]</font></b> (ع اِ) ج ِ طُرُق . جج ِ طریق .<br /></font></div>'),
(176655, 'طرقات', '<span class=\"hlight\">طرقات .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (ع ص، اِ) ج ِ طَرِقة. زنان فال سنگک گیر <span class=\"hlight\">:</span> قال جالینوس : ان طب اسقلبیوس کان طباً الهیاً و قال ان قیاس الطب الالهی الی طبنا قیاس طبنا الی طب الطرقات . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٥</span>، <span class=\"hlight\" dir=\"rtl\">٣١</span>). اطباء طرقات . (ابن البیطار در کلمه ٔ شبرم ).<br /></font></div>'),
(176656, 'طرقاق', '<span class=\"hlight\">طرقاق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (مغولی، ص، اِ)محافظ. نگهبان . مراقب . پاسدار. (جهانگشای جوینی ).<br /></font></div>'),
(176657, 'طرقانیدن', '<span class=\"hlight\">طرقانیدن .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b> (مص ) ترکانیدن <span class=\"hlight\">:</span> چهارم بادی که از اندرون رگها تولد کند و رگ را بطرقاند. (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(176658, 'طرقای', '<span class=\"hlight\">طرقای .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) از شاهزادگان مغول است . رجوع به جامعالتواریخ چ بلوشه ص <span class=\"hlight\" dir=\"rtl\">٦٦</span> شود.<br /></font></div>'),
(176659, 'طرقبه', '<span class=\"hlight\">طرقبه .</span> <font color=\"DarkGreen\"><b>[ طُ ق َ ب َ ]</font></b> (اِخ ) قصبه ٔ مرکز بخش طرقبه ٔ شهرستان مشهد در <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی شمال باختری مشهد. کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">٢٩٣٨</span> نفر سکنه . آب آن از رودخانه و محصول آنجا انواع میوه جات، خشکبار، تریاک، بنشن، ابریشم و غلات است . شغل اهالی باغداری و قالیچه بافی و کسب تجارت و راه آن اتومبیل رو است . بواسطه ٔ مرکزیت و موقعیت طبیعی که دارد از سایر دهات اطراف خود پرجمعیت تر و وسایل ایاب و ذهاب و زندگی بهتر است . تابستان بیشتر اهالی مشهد در این قصبه زندگی مینمایند. دارای یک خیابان جدیدالاحداث در دست اقدام و چندین شاهراه عمومی و سه میدان که در اطراف آنها دکاکین متعدد اغذیه فروشی است میباشد. ادارات دولتی بخشداری، شهرداری، نمایندگی دارائی، آمار، دفتر ازدواج و طلاق و دبستان و پاسگاه ژاندارمری دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176660, 'طرقبه', '<span class=\"hlight\">طرقبه .</span> <font color=\"DarkGreen\"><b>[ طُ ق َ ب َ ]</font></b> (اِخ ) دهستان مرکزی بخش طرقبه ٔ شهرستان مشهد که در قسمت شمال باختری مشهد واقع و نفوس آن در حدود <span class=\"hlight\" dir=\"rtl\">٩٧٠٩</span> نفر و متشکل از <span class=\"hlight\" dir=\"rtl\">١٤</span> آبادی بزرگ و کوچک و قراء مهم آن جاغرق با <span class=\"hlight\" dir=\"rtl\">١٦٢٨</span> تن سکنه و عنبران با <span class=\"hlight\" dir=\"rtl\">٦٩٨</span> نفر جمعیت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176661, 'طرقبه', '<span class=\"hlight\">طرقبه .</span> <font color=\"DarkGreen\"><b>[ طُ ق َ ب َ ]</font></b> (اِخ ) نام یکی از بخشهای شهرستان مشهد، محدود است از طرف خاوربه بخش حومه، از باختر به کوه بینالود، از شمال به کوه تخت رستم، از جنوب به دهستان پیوه ژن . بطور کلی این بخش در دامنه ٔ کوه بینالود و داخل رودخانه های پرآب که از کوه سرچشمه گرفته واقع است . بینالود بواسطه ٔازدیاد چشمه سار رودخانه و غرس اشجار، اغلب آبادیها بهم اتصال پیدا کرده که در بعضی نقاط طول آنها از <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزار گز تجاوز میکند. مناظر طبیعی عبارتند از چشمه سبز، بندطرق، گلستان، زشک، محله زشک، وکیل آباد، شاندیز، گلمکان، دولت آباد، ابرده بالا و پائین که اغلب آنها بهم متصل هستند و مورد توجه شهرنشینان و خارجیان میباشند و تابستان تفرجگاه ایشان است . بواسطه ٔ وفور آب و لطافت هوا دارای انواع میوه جات شاداب و قابل توجه میباشد لیکن بواسطه ٔ کوهستانی بودن محصول زمینی آنها کم، حاصل غله بقدری است که اغلب سالها تکافوی خوراک سالیانه ٔ آنها را نمینماید. از همین مختصر زمین مزروعی نیز بیشتر استفاده ٔ تریاک کاری میشود. اهالی مشهد برای ییلاق و شرکتهای کمپوت سازی و خشکبار برای تجارت در تابستان به این منطقه می آیند. شغل ساکنین بخش باغداری، کسب و زراعت است و از صنایع دستی هم بی بهره نیستند. در بیشتر قراء قالی و قالیچه بافی متداول است . این منطقه علاوه بر مناظر طبیعی و منابع زراعتی از منابع زیرزمینی هم بی بهره نبوده معادن زیادی دارد که مورد توجه است مانند سرب ِ جاغرق، زغال سنگ ِ نقندر، مرمر الوان در شاندیز، زغال سنگ حوض . اردمه معادن زیادی نیز دارد که تاکنون استخراج نشده است . در بیشتر آبادیهای بخش راه شوسه و فرعی احداث و عبور و مرور بسهولت انجام میگیرد. این بخش از چهار دهستان بنام گلمکان، شاندیز، اردمه و دهستان مرکزی که شامل <span class=\"hlight\" dir=\"rtl\">٩٨</span> آبادی بزرگ و کوچک است تشکیل شده و مجموع نفوس آن در حدود <span class=\"hlight\" dir=\"rtl\">٢٩٠٣٩</span> نفر است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176662, 'طرقطی', '<span class=\"hlight\">طرقطی .</span> <font color=\"DarkGreen\"><b>[ طُ ق َ ]</font></b> (اِخ ) دهی است از دهستان قلعه نو بخش کلات شهرستان مشهد در <span class=\"hlight\" dir=\"rtl\">٦٥</span>هزارگزی جنوب خاوری کبودگنبد. دره . محصول آنجا غلات و سیب زمینی . شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176663, 'طرقل درکوه', '<span class=\"hlight\">طرقل درکوه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) حمداﷲ مستوفی در اثناء شرح سلسلةالجبال البرز آورده : چون به حدود عراق و گیلان رسد، آن را طرقل درکوه خوانند. (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span>).<br /></font></div>'),
(176664, 'طرقلة', '<span class=\"hlight\">طرقلة.</span> <font color=\"DarkGreen\"><b>[ طَ ق َ ل َ ]</font></b> (اِخ ) شهری است به مغرب از نواحی بربر که در بر اعظم واقع، و همان قصبه ٔ سوس الاقصی است . (معجم البلدان ص <span class=\"hlight\" dir=\"rtl\">١٧٤</span>).<br /></font></div>'),
(176665, 'طرقه', '<span class=\"hlight\">طرقه .</span> <font color=\"DarkGreen\"><b>[طُ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (اِ) مرغی است . نوعی مرغ است سیاه، دوچند گنجشکی و سخن گوی . قسمی مرغ که پرهای آن به سیاهی گراید و مانند طوطی تقلید صوت شنوده کند. شارک . شارو. شار. شحرور. قره طاوق . توکا. چاله خوس . چاله خسب .<br /></font></div>'),
(176666, 'طرقه', '<span class=\"hlight\">طرقه .</span> <font color=\"DarkGreen\"><b>[ طُ ق َ ]</font></b> (اِخ ) از توابع خراسان، و دارای معدن زغال سنگ است . (جغرافی اقتصادی کیهان ص <span class=\"hlight\" dir=\"rtl\">٤٠</span>).<br /></font></div>'),
(176667, 'طرقه بازی', '<span class=\"hlight\">طرقه بازی .</span> <font color=\"DarkGreen\"><b>[ طَ رَق ْ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (حامص مرکب ) بازی کردن با طرقه یا ترقه که بازیچه ٔ کودکان است . رجوع به ترقه شود.<br /></font></div>'),
(176668, 'طرقوا', '<span class=\"hlight\">طرقوا.</span> <font color=\"DarkGreen\"><b>[ طَرْ رِ قو ]</font></b> (ع فعل امر) صیغه ٔ امر حاضر است، بمعنی راه دهید، و یکسو شوید. معمول است که نقیبان عرب پیش سلاطین، طرقوا، طرقوا میگویند. (غیاث اللغات )(آنندراج ). برد. رجوع به بَرد شود. در آخر این کلمه در موقع کتابت بر حسب ضرورت مراعات قواعد عربیت الفی برای علامت جمع مینهند ولی در تلفظ باید طرقو، بدون الف خواند. طرقوا امر است از تطریق، بمعنی رو بسوی خانه کردن و یکسو شدن، و راه دهید گفتن <span class=\"hlight\">:</span> <br />چون به انجم سپهر کرد آرام <br />طرقوا زد چو چاوشان بهرام .<br /> <font color=\"Red\">امیرخسرو (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طرقواگویان </span> ؛ دورباش گویان <span class=\"hlight\">:</span> ظفر در پیش طرقواگویان و نصرت بر یمین و یسار پویان . (جهانگشای جوینی ).<br /></font></div>'),
(176669, 'طرقوازن', '<span class=\"hlight\">طرقوازن .</span> <font color=\"DarkGreen\"><b>[ طَرْ رِ قو زَ ]</font></b> (نف مرکب ) نقیب و چوبدار. (غیاث اللغات ). آنکه پیشاپیش شاه، یا زن او، یا امیری، یا زنی محترمه، «راه دهید» گوید. رشیدی این کلمه را در فرهنگ خود بصورت طرقوازنان آورده گوید: یعنی چاوشان و چوبداران که پیش پیش ملوک و سلاطین روند و مردم را از راه دور کنند و طرقواگویان نیز گویند. (فرهنگ رشیدی ) <span class=\"hlight\">:</span> <br />با سایه ٔ رکاب محمد عنان درآر<br />تا طرقوازنان تو گردند اصفیا.<br /> <font color=\"Red\">خاقانی .</font><br />رجوع به طرقوا شود.<br /></font></div>'),
(176670, 'طرقچی', '<span class=\"hlight\">طرقچی .</span> <font color=\"DarkGreen\"><b>[ طُ رَ ]</font></b> (اِخ ) دهی از دهستان لاله آباد بخش مرکزی شهرستان بابل، در<span class=\"hlight\" dir=\"rtl\">١٩</span>هزارگزی جنوب باختری بابل و در یک هزارگزی شوسه ٔ بابل به آمل . دشت معتدل و مرطوب و مالاریائی با <span class=\"hlight\" dir=\"rtl\">١٧٥</span> تن سکنه . آب آن از رودخانه ٔ کاری و محصول آنجا برنج و مختصر غلات و کنف و پنبه و صیفی . شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(176671, 'طرقچی محله', '<span class=\"hlight\">طرقچی محله .</span> <font color=\"DarkGreen\"><b>[ طَ رَ م َ ح َل ْ ل َ ]</font></b> (اِخ ) از محال لعل آباد توابع بارفروش است . (سفرنامه ٔ مازندران رابینو ص <span class=\"hlight\" dir=\"rtl\">١١٨</span> بخش انگلیسی ).<br /></font></div>'),
(176672, 'طرقی', '<span class=\"hlight\">طرقی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی از دهستان فاروج بخش حومه ٔ شهرستان قوچان در <span class=\"hlight\" dir=\"rtl\">٣٠</span>هزارگزی شمال باختری قوچان و <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی جنوب شوسه ٔ قوچان به شیروان . جلگه و معتدل با <span class=\"hlight\" dir=\"rtl\">٥٦</span> تن سکنه . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176673, 'طرقی', '<span class=\"hlight\">طرقی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابوالعباس احمدبن ثابت بن محمد طرقی اصفهانی . متوفی بسال <span class=\"hlight\" dir=\"rtl\">٥٢٠</span> هَ . ق . حافظی ماهر و محدثی آگاه بوده است . رجوع به انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧٠</span> الف شود.<br /></font></div>'),
(176674, 'طرقی', '<span class=\"hlight\">طرقی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b>(ص نسبی ) منسوب به طرق که قریه ای است شهرک مانند و تا اصفهان بیست فرسنگ مسافت دارد. (الانساب سمعانی ).<br /></font></div>'),
(176675, 'طرقیدن', '<span class=\"hlight\">طرقیدن .</span> <font color=\"DarkGreen\"><b>[ طَ رَ دَ ]</font></b> (مص ) ترکیدن <span class=\"hlight\">:</span> خدای عز و جل به عظمت خویش امر خویش بر کوه افکند و از هیبت خدای عز و جل بطرقید و شش پاره شد و از زمین به زمین حجاز افتاد. (ترجمه ٔ طبری بلعمی ). جرجیس برفت و آهنگ آن بتخانه کرد، پس چون درآمد آنهمه بتان را گفت همه در پیش من بروی افتید، بتان همه بروی درافتادند، و طراقی از افلون <font color=\"DarkGreen\"><b>[ نام بت بزرگ ]</font></b> برآمد و زمین بطرقید و آن بتان به زمین فروشدند. (ترجمه ٔ طبری بلعمی ). گفت خداوند را بر منظر باید نشست و یحیی و پسرانش و دیگر بندگان را بنشانند و بایستانند، تا هدیه ها پیش آرند و دلهای آل برمک بطرقد. (تاریخ بیهقی ). و از جبن این حاجب را زهره بطرقید. (تاریخ بیهقی ). و گاه باشد که بسبب عظیمی آماس پلک بطرقد و خونی رقیق بپالاید. (ذخیره ٔ خوارزمشاهی ). اندر طرقیدن پاشنه و انگشتان پای . (ذخیره ٔ خوارزمشاهی ). و اگر سوءالمزاج خشک باشد پیوسته لبها میطرقد و پوستکهاء باریک از وی برخیزد. (ذخیره ٔ خوارزمشاهی ). حق تعالی بیواسطه به دلش فروگفت که ای رابعه در خون هیجده هزار عالم میشوی، ندیدی که موسی دیدار خواست، چند ذره تجلی به کوه افکندیم، به چهل پاره بطرقید، اینجا به اسمی قناعت کن . (تذکرةالاولیاء عطار). و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span> شود.<br /></font></div>'),
(176676, 'طرقیون', '<span class=\"hlight\">طرقیون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی جزء دهستان سیاه رود بخش افجه ٔشهرستان تهران، در <span class=\"hlight\" dir=\"rtl\">١٦٠٠٠</span>گزی جنوب گلندوک و در <span class=\"hlight\" dir=\"rtl\">٦٠٠٠</span>گزی جنوب راه شوسه ٔ دماوند-طهران . کوهستان کنار رود جاجرود، سردسیر، با <span class=\"hlight\" dir=\"rtl\">٧١</span> تن سکنه، آب آن از رودخانه و محصول آنجا غلات، بنشن و قلمستان . شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(176677, 'طرلاب', '<span class=\"hlight\">طرلاب .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی جزء دهستان زاهجرد بخش دستجرد خلجستان شهرستان قم، در <span class=\"hlight\" dir=\"rtl\">٢٧٠٠٠</span>گزی خاور دستجرد، سر راه شوسه ٔ قم به اراک در دامنه . معتدل با <span class=\"hlight\" dir=\"rtl\">٦٦</span> تن سکنه، آب آن از قنات و محصول آنجا غلات و شغل اهالی زراعت است . و در کنار راه شوسه قرار دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(176678, 'طرلان', '<span class=\"hlight\">طرلان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) مرغی است حرام گوشت و از جمله ٔ طیور وحشی میباشد.<br /></font></div>'),
(176679, 'طرلان', '<span class=\"hlight\">طرلان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی جزء دهستان بزچلو بخش وفس شهرستان اراک، در <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی شمال باختری کمیجان، <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی راه مالرو عمومی . کوهستانی، سردسیر، با <span class=\"hlight\" dir=\"rtl\">٥٢٨</span> تن سکنه . آب آن از قنات و محصول آنجا غلات و انگور و میوه جات و شغل اهالی زراعت و گله داری و قالی بافی و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(176680, 'طرلیدون', '<span class=\"hlight\">طرلیدون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی عنب الثعلب است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176681, 'طرم', '<span class=\"hlight\">طرم .</span> <font color=\"DarkGreen\"><b>[ طُ رُ ]</font></b> (اِ صوت ) بانگ دهل و نقاره باشد. (برهان ) (آنندراج ).<br /></font></div>'),
(176682, 'طرم', '<span class=\"hlight\">طرم .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) کوره ٔ آتش . (منتهی الارب ) (آنندراج ). کانون آتش . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> درختی است . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176683, 'طرم', '<span class=\"hlight\">طرم .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (ع اِ) انگبین با موم . (منتهی الارب ) (آنندراج ). انگبین . (مهذب الاسماء). عسل . (دهار). شهد غلیظ. (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> مسکه و انگبین که خانه را پر کرده باشد. (منتهی الارب ) (آنندراج ). مسکه و عسل راگویند. (برهان ). زبد است و عسل را نیز نامند. و گفته اند غذای مرکب از زبد و عسل است . (فهرست مخزن الادویه ). اسم مرکب عسل و مسکه است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(176684, 'طرم', '<span class=\"hlight\">طرم .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع مص ) کبود گردیدن دندانها. یقال : طَرِمَت ْاسنانه طَرَماً. <BR><font color=\"Blue\">◄</font> روان و جاری گردیدن انگبین از خانه ٔ مگس و پر شدن آن از آن . (منتهی الارب )(آنندراج ). روان شدن شهد از شان . (منتخب اللغات ).<br /></font></div>'),
(176685, 'طرم', '<span class=\"hlight\">طرم .</span> <font color=\"DarkGreen\"><b>[ طُ رُ ]</font></b> (فرانسوی، اِ) نوعی بازی ورق است .<br /></font></div>'),
(176686, 'طرم', '<span class=\"hlight\">طرم .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (اِخ ) ابن بری گفته است موضعی است . ابن مأنوس گوید <span class=\"hlight\">:</span> <br />طرقت فُطَیْمَةُارحل السفر<br />بالطرم بات خیالها یسری .<br />صاحب اللسان گوید: به خط شیخ رضی الدین شاطبی حاشیه ای دیدم که نوشته بود: طرم بفتح شهر وهشوذان است که عضدالدوله ٔ فناخسرو آن را منهزم کرد. و این گفتار ابوعبید بکری است که در معجم ما استعجم آورده است . (از تاج العروس ). و یاقوت آرد: طرم بکسر گمان میکنم فارسی است، در سخن عرب نظیر آن را بر مسکه و برخی از آنان هم بر انگبین اطلاق کنند... شاعر در معنی مسکه گوید: و منهن مثل الشهد قد شیب بالطرم . و آن قلعه ای است در فارس در حدود کرمان . شهرکی است که به زبان محلی آن را تارم گویند و گمان میکنم این کلمه معرب شده است زیرا در لهجه ٔ آنان حرف ط نیست . اعزبن مأنوس یشکری گوید:<br />طرقت فطیمة ان ّ کل السّفَْ<br />َرِ بات َ خیالها یسری .<br /> <font color=\"Red\">(معجم البلدان ).</font><br />و عجب این است که بر حسب نقل یاقوت در شعر کلمه ٔ طرم نیست ! و رجوع به تارم و طارم شود. و یاقوت ذیل طرم بفتح آرد:ناحیه ٔ بزرگی است در جبال مشرف بر قزوین در طرف بلاددیلم و من آن ناحیه را دیدم و در آن مزارع و قرای کوهستانی فراوان یافتم و حتی یک فرسنگ در آن صحرا مشاهده نمیشود جز اینکه پر آب و گیاه و دارای دهکده های بسیار است و چه بسا که مردم آن ناحیه را به لهجه ٔ محلی «ترم » میخوانند و شاید پنبه ٔ نرم موصوف به این لفظ منسوب به یکی از این دو موضع باشد و این همان ناحیه ای است که وهشوذان فرمانده سپاهیان رکن الدولةبن بویه آن را منهزم ساخت و بهمین سبب متنبی در ضمن مدح عضدالدوله گوید <span class=\"hlight\">:</span> <br />ماکانت الطرم فی عجاجتها<br />الا بعیراً اضله ناشد<br />تسأل اهل القلاع عن ملک <br />قدمسخته نعامةٌ شارد.<br /> <font color=\"Red\">(از معجم البلدان ).</font><br />و رجوع به تجارب الامم ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٩</span> و <span class=\"hlight\" dir=\"rtl\">١١٨</span> شود. و نیز رجوع به طارم شود.<br /></font></div>'),
(176687, 'طرماج', '<span class=\"hlight\">طرماج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) موضعی است در قول ابووجزه ٔ سعدی آنجا که گوید <span class=\"hlight\">:</span> <br />کأن َّ صوت حداها و القرین بها<br />ترجیع مغترب نشوان لجلاج <br />نعب ُ الاشاهیب فی الأخبار یجمعها<br />و اللیل ساقطة اوراقه داج <br />حتی اذاما ایالات ٌ جرت برحاً<br />و قد ربعن الشوی عن ماء طرماج .<br /><font color=\"Red\">(از معجم البلدان ).</font><br /></font></div>'),
(176688, 'طرماح', '<span class=\"hlight\">طرماح .</span> <font color=\"DarkGreen\"><b>[ طِ رِم ْ ما ]</font></b> (ع ص ) مردبزرگ نسب مشهور. <BR><font color=\"Blue\">◄</font> مرد بلندنظر. <BR><font color=\"Blue\">◄</font> مرد پیش بین در امور. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176689, 'طرماح', '<span class=\"hlight\">طرماح .</span> <font color=\"DarkGreen\"><b>[ طِ رِم ْ ما ]</font></b> (اِخ ) ابن الجهم . شاعری است . (منتهی الارب ). و فی نسخة: ابوالجهم . (تاج العروس ).<br /></font></div>'),
(176690, 'طرماح', '<span class=\"hlight\">طرماح .</span> <font color=\"DarkGreen\"><b>[ طِ رِم ْ ما ]</font></b> (اِخ ) ابن الحکیم . شاعری است . (منتهی الارب ). المکنی بأبی ضَبّة و یقال اسمه حکم بن الحکیم، وُلد بالشام و انتقل الی الکوفة. قال الجاحظ: کان یؤدّب الاطفال، فیخرجون من عنده کأنما جالسوا العلماء. (تاج العروس ). او را دیوانی است که ابوسعید سکری و طوسی و جماعتی دیگر آن را گرد آورده اند.(فهرست ابن الندیم ). وفاتش به روزگار یزیدبن عبدالملک اموی بوده است . (کشف الظنون ). ابن قتیبه در کتاب خویش نسب وی را بدین سیاق آورده که هو ابن حکیم من طی و یکنی ابانفر و کان جده قیس بن جحدر، اَسرَه بعض ملوک بنی جفته، فدخل علیه حاتم الطائی فاستوهبه و قال :<br />فککت عدیّاً کلها من اسارها<br />فافضل و شفعنی بقیس بن جحدر<br />ابوه ابی و الاُم من اُمهاتنا<br />فانعم فدتک الیوم نفسی و معشری .<br /> <font color=\"Red\">(الشعر و الشعراء ص <span class=\"hlight\" dir=\"rtl\">٢٢٨</span>).</font><br />ابن عبدربه گوید: بنی نماره <font color=\"DarkGreen\"><b>[ یکی از بطون لخم ]</font></b> از رهط طرماح بوده اند. و برخی گفته اند طرماح خود از قبیله ٔ طی بوده است . (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥١</span>). نکوهیده تر هجوی که از عرب شنیده شده، ابیات ذیل است که طرماح گوید:<br />تمیم بطرق اللؤم اهدی من القطا<br />ولو سلکت سُبل المکارم ضلت <br />ولو ان برغوثاً علی ظهر قملة<br />رأتها تمیم یوم زحف لولت <br />ولو ان عصفوراً یمد جناحه <br />لقامت تمیم تحته و استظلت <br />ولوجمعت یوماً تمیم جموعها<br />علی ذرة معقولة لاستقلت .<br />(عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٣</span> و <span class=\"hlight\" dir=\"rtl\">٢٩٠</span> و ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٥١</span>).<br />مرزبانی در کتاب الموشح از ابوعمروبن العلاء روایت میکند که گفت : طرماح را به سواد کوفه دیدم که کلماتی نبطی می آموخت و آنها را در شعر خود می آورد، پرسیدم چه میکنی و از این عمل چه منظور داری ؟ گفت : الفاظ نبطی را اصلاح میکنم و در شعر خود می آورم .و نیز مرزبانی به اسناد خود از شعبةبن الحجاج روایت کرده که او گفته است از طرماح پرسیدم نشأتت از کجاست ؟ گفت : به سواد کوفه . و اصمعی بر صحت این گفتار مصراع ذیل را از سخن طرماح گواه آورده است : «طال فی شطنهروان اغتماضی ». و نیز مرزبانی به اسناد خود از اصمعی روایت کند که اصمعی گفته است کمیت بن زید و طرماح هیچیک در شعر و لغت حجت نیستند، چه هر دو مولد میباشند و هم از اصمعی آورده که گفته است کُمیت با آنکه علم نحو آموخته بود در شعر حجت نیست و همچنین طرماح، چه هر لفظی را که این دو تن می شنیدند هرچند هم فهم معنی آن لفظ نمیکردند از ایراد آن الفاظ در اشعار خود دریغ نداشتند، چنانکه رؤبةبن العجاج میگفت : کمیت و طرماح معانی لغات غریبه ٔ اشعار خویش را از من میپرسیدند. بر این شعر طرماح که در صفت ناقه ای سروده اساتید فن اعتراض کرده اند، میگوید:<br />تمسح الارض بمعنونس <br />مثل مئلاة النیاح القیام .<br />مُعنونس دُم ِ دراز است، و مئلاة، مفرد مآلی است که عبارت است از ژنده ای چند که زنان هنگام برخاستن برای نوحه گری در دست گیرند، خواسته است بگوید که ماده شتر دمش به زمین میرسید و تشبیهی سخت ناپسند آورده است . (الموشح ص <span class=\"hlight\" dir=\"rtl\">١٠٨</span> و <span class=\"hlight\" dir=\"rtl\">١٠٩</span>). زرکلی در الاعلام آورده که وفات وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٨٠</span> هَ . ق . بوده . شاعری است اسلامی و فحل . در شام نشو و نما یافت و بعد به کوفه شد و در آنجا رحل اقامت افکند. پیرو کیش شراة از مذهب ازارقه بود، با خالدبن عبداﷲ القسری پیوستگی یافت، خالد بدو اکرام و اشعار وی را تحسین میکرد.طرماح شاعری هجوسرا و با کمیت همعصر و دوست بود و کمتر اتفاق می افتاد که بین آنان جدائی افتد. جاحظ گفته است وی مرد قحطانی متعصبی بوده است . وی را دیوانی است خُرد که چاپ شده است . (الاعلام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>). و رجوع به الجماهر ص <span class=\"hlight\" dir=\"rtl\">١٨٣</span> و عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٥١</span> و ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٢</span> و عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span>، <span class=\"hlight\" dir=\"rtl\">١٩٥</span>، <span class=\"hlight\" dir=\"rtl\">٣٠٧</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩٣</span>، <span class=\"hlight\" dir=\"rtl\">١٥٠</span> و المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>، <span class=\"hlight\" dir=\"rtl\">٩١</span>، <span class=\"hlight\" dir=\"rtl\">١٩٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٥</span>، <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>، <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>، <span class=\"hlight\" dir=\"rtl\">٣٩٣</span> و الموشح ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>، <span class=\"hlight\" dir=\"rtl\">١٩١</span>، <span class=\"hlight\" dir=\"rtl\">١٩٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٤</span>، <span class=\"hlight\" dir=\"rtl\">٣٢٢</span> و المرصع ص <span class=\"hlight\" dir=\"rtl\">٨٢</span> و ضحی الاسلام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٥</span> و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span> و شدالازار ص <span class=\"hlight\" dir=\"rtl\">٤١٥</span> شود.<br /></font></div>'),
(176691, 'طرماحی', '<span class=\"hlight\">طرماحی .</span> <font color=\"DarkGreen\"><b>[ طِ رِم ْ ما ]</font></b> (ص نسبی ) منسوب به طرماح که نام جدی بوده است . (سمعانی ).<br /></font></div>'),
(176692, 'طرماذ', '<span class=\"hlight\">طرماذ.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) مرد لافی . طرمذان مثله . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176693, 'طرماسیا', '<span class=\"hlight\">طرماسیا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به سریانی صمغ قتاد است که کتیرا نامند.<br /></font></div>'),
(176694, 'طرماوداس', '<span class=\"hlight\">طرماوداس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به سریانی بُخور مریم است . (فهرست مخزن الادویة).<br /></font></div>'),
(176695, 'طرمة', '<span class=\"hlight\">طرمة.</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (ع اِ) جگر. (منتهی الارب ).<br /></font></div>'),
(176696, 'طرمة', '<span class=\"hlight\">طرمة.</span> <font color=\"DarkGreen\"><b>[ طُ م َ ]</font></b> (ع اِ) کوره ٔ آتش . (منتهی الارب ). کانون . (تاج العروس ).<br /></font></div>'),
(176697, 'طرمة', '<span class=\"hlight\">طرمة.</span> <font color=\"DarkGreen\"><b>[طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ <span class=\"hlight\" dir=\"rtl\">/</span> طُ م َ ]</font></b> (ع اِ) گوی لب بالائین . (منتهی الارب ). و گوی لب پائین را تُرْفة نامند و طرمتان تثنیه ٔ آن است ولی لفظ طرمة را بجای تُرْفة غلبه داده اند و گویند طرمة آبله ای است که در وسط لب بالا پدید آید.در بعض کتب اصول لغت چنین است و در اساس آمده است که : هو ملیح الطرمتین . و آن دو سپیدی است در وسط دو لب که سپیدی لب پائین را طرمة و ازآن ِ لب بالا را تُرْفة گویند ولی طرمتین علم شده است . (از تاج العروس ).<br /></font></div>'),
(176698, 'طرمح', '<span class=\"hlight\">طرمح .</span> <font color=\"DarkGreen\"><b>[ طَم َ ]</font></b> (ع ص ) مرد فراخ گام . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176699, 'طرمحانیة', '<span class=\"hlight\">طرمحانیة.</span> <font color=\"DarkGreen\"><b>[ طَ م َ نی ی َ ]</font></b> (ع اِمص ) خودنمائی . بزرگ منشی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176700, 'طرمحة', '<span class=\"hlight\">طرمحة.</span> <font color=\"DarkGreen\"><b>[ طَ م َ ح َ ]</font></b> (ع مص ) نیک دراز کردن بنا را. (آنندراج ). یقال : طرمح بنائه . میم زائد است . (منتهی الارب ).<br /></font></div>'),
(176701, 'طرمذار', '<span class=\"hlight\">طرمذار.</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (ع ص ) مرد لافی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176702, 'طرمذان', '<span class=\"hlight\">طرمذان .</span> <font color=\"DarkGreen\"><b>[ طِ م ِ ]</font></b> (ع ص ) مرد لافی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176703, 'طرمز', '<span class=\"hlight\">طرمز.</span> <font color=\"DarkGreen\"><b>[ طُ م ُ ]</font></b> (روسی، اِ) رجوع به ترمز شود.<br /></font></div>'),
(176704, 'طرمسة', '<span class=\"hlight\">طرمسة.</span> <font color=\"DarkGreen\"><b>[ طَ م َ س َ ]</font></b> (ع مص ) ترنجیده شدن . گرفته شدن . ترش روی گردیدن . آژنگ افکندن میان دو ابرو. <BR><font color=\"Blue\">◄</font> سپسایکی رفتن . <BR><font color=\"Blue\">◄</font> سپسایکی برگشتن . <BR><font color=\"Blue\">◄</font> گریختن . <BR><font color=\"Blue\">◄</font> محو کردن . پاک کردن نبشته را. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176705, 'طرمطاز', '<span class=\"hlight\">طرمطاز.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (امیر...) پسر بایجوبخشی، از امرای عصر الجایتو. وی همان شخصی است که الجایتو را به مذهب شیعه متمایل ساخت و سبب آن بنابر گفته ٔ حافظ ابرو در مجمعالتواریخ آن بود که در تاریخ سنه ٔ اثنین و سبعمائة (<span class=\"hlight\" dir=\"rtl\">٧٠٢</span> هَ . ق .) که پادشاه غازان خان بود، روزی علوی در مسجد جامع بعد از ادای نماز جمعه نماز فرض را بازگذاشت و دعوی او آن بود که نماز در عقب این امامان درست نیست . جمعی عوام بر او غلو کرده بودند و آن علوی در میانه کشته شد. اقربا و اصحاب علوی مقتول به استغاثت پیش غازان رفته اند و آن حال عرضه داشته و صورت قضیه تقریر کرده، پادشاه از آن حرکت ناپسندیده بسیار رنجیده و گفته که بجهت کثرت نماز چون یکی را توان کشتن، خصوصاً علوی را و از آنجا حرکت فرموده به راه عانه و حدیثه روان شد، برعزیمت شام و پیوسته متفحص احوال دین و ملت میبود و آزادانه استفسار میفرمود. جمعی امراء و ایناق که میل به مذهب شیعه داشتند از آن جمله یکی طرمطاز بود، پسر بایجوبخشی که از کودکی باز در نزد حضرت غازان بزرگ شده بود و گستاخ و در ولایت ری در میان شیعیان نشو ونما یافته پیوسته در حضرت پادشاه غازان تقویت آن مذهب میکرد و چون خاطر پادشاه از آن غوغای عام متغیر شده بود، بدان سخنان که امیر طرمطاز گفتی گوش کردی و اکثر در محل قبول می افتاد و حکم رفت که چند عدد دارالسیادة در شهرهای بزرگ چون اصفهان و کاشان و سیواس وروم و غیر آن بنیاد نهادند و املاک بسیار بر آن وقف فرمودند و در مشهد امیرالمؤمنین و در شنب تبریز و غیره چنانکه هنوز اثر بعضی از آنها باقی است و پادشاه غازان خان را میلی تمام بدان طایفه بودی اما هرگز ازغایت کفایت اظهار نکردی، و رعایت مصلحت عام فرمودی، و کسی را زهره ٔ آنکه اظهار کند نبودی، تا غازان خان را واقعه ای رسید و چون سلطان سعید اولجایتو بر سریر سلطنت ممکّن شد جمعی از ائمه ٔ حنفی به وقتی که در خراسان بوده ملازم بوده اند و خاطر سلطان را بدان مذهب مایل گردانیده اند و چون سلطان از خراسان بیامد تقویت مذهب امام اعظم ابوحنیفه رضی اﷲ عنه میفرمود و آن طایفه را اعزاز و اکرام فرمودی و عظیم مایل بودی به مذهب اهل سنت و جماعت چنانکه نام خلفای اربعه بر زر و نقره فرمود نهادن و حنفیان عظیم مبالغت کردندی و تعصبات، چنانکه اکابر وزراء را از آن تعصبات رنجیدی و صاحب اعظم خواجه رشیدالدین رحمه اﷲ را مذهب شافعی داشت و سخت مایل بودی به ائمه و علمای شافعیه و مجالست و مباحثه ٔ او با این طایفه بودی و از تعصبات حنفیان بغایت ملول بودی، اما جهت خاطر پادشاه اظهار نکردی وبا آن درساختی و مولانا سعید قاضی القضاة نظام الدین عبدالملک مراغه ای که در علوم معقول و منقول یگانه ٔ جهان و سرآمد دوران بود به شرف علم و فضیلت و مباحثه ومناظره بر اهل علم فائق، خواجه رشیدالدین پیش پادشاه تعریف او کرد و او را طلب داشته ملازم سلطان گردانید و قضاء ممالک ایران بدو مفوض شد و منظور نظر سلطان گشت و آن یگانه ٔ جهان شافعی مذهب بگزاف با ائمه ٔ حنفیه در حضور سلطان مباحثات می افتاد و ایشان را الزام میفرمود و آن طایفه از مناظره ٔ مباحثه ٔ او عاجر میشدند و سلطان را تقریر و صحبت او خوش آمد و مستحسن داشت و از فحاوی مباحثات حقیقت مذهب امام شافعی فهم میفرمود. و این حکایت مشهور است که از مولانا قطب الدین شیرازی پرسیدند که اگر حنفی خواهد که شافعی شود چه کند؟ مولانا در جواب فرمود سهل باشد، میگوید: لااله الا اﷲ، محمد رسول اﷲ. فی الجمله سلطان مولانا نظام الدین را به انواع سیورغامشی خود مخصوص گردانید و یرلیغ و پائیزه و خلعت و دیگر عواطف پادشاهانه و ملازم شد، تا درسنه ٔ سبع و سبعمائة (<span class=\"hlight\" dir=\"rtl\">٧٠٧</span> هَ . ق .) پسر صدر جهان بخارا به حضرت سلطان آمد. جماعت حنفیان شکایت مولانا نظام الدین به او حکایت کردند که ما را او به عقیدت و مذهب در نظر پادشاه خوار گردانیده و به اهانت و استخفاف مشهور گردانیده و ایشان را استمالت داد و در روز جمعه به حضور سلطان روی به مولانا نظام الدین کرد و بر سبیل استهزاء و افسوس، مسئله ٔ نکاح محلوقة من ماءالزنا القاء کرده و سؤال نمود. مولانا در جواب روایتی بی فکر و تردد داد، گفت که این مسئله در مذهب امام شافعی رضی عنه بر این وجه نیست که شما تقریر میفرمائیدو معهذا معارض است به مسئله ٔ نکاح مادر و خواهر. میان فریقین نزاع متمادی شد، ایشان منکر شدند که در مذهب ابوحنیفه این مسئله نیست . نظام الدین از منظومه ای که ملخص ترین کتب فقه حنفیان باشد، این بیت بخواند:<br />و لیس فی اللواط من خدّ ولا<br />لوطی الاخت بعد فقد (کذا).<br />ایشان فروماندند و از آن مباحثات بیوجه سلطان و امرا و وزرا رنجیدند و زمانی خاموش شدند و به همدیگر می نگریدند. سلطان از سر غضب از آن مجلس برخاست و به وثاق رفت . قتلغشاه با دیگر امرا گفت که این چه کار بود که ما کردیم و یاسا و یسون چنگیزخان و پدران خود بگذاشتیم و به دین عرب درآمدیم که به چندین قسم منقسم است و این رسوائی میان ایشان قائم که با مادر و دختر این حرکت میکنند و ما به دین اسلاف خود میرویم و میان تمامت امرا و خوانین و اصحاب اردوها این خبر شائع شد. متنفر شدند و هرکه را از اصحاب عجایم میدیدند طنز و افسوس آغاز میکردند و طباع تمامت اتراک از این قضیه نفرت گرفت، و اتفاقاً هم در آن ایام به وقت مراجعت به گلستان رسید، بر کوشکی که غازان خان در آن حوالی عمارت فرموده به عشرت مشغول شد. شب رعد و برق و بارانی عظیم بود و چند کس از نزدیکان سلطان به صاعقه بمردند و سلطان از آن حالت مستشعر و مخوف گشت و برفور کوچ فرمود، بر عزیمت سلطانیه و بعضی امراء عرضه داشتند که بموجب قواعد مغول و یاسای چنگیزخان بر آتش میبایدگذشت، بخشیان را که صاحب این فن بودند حاضر کردند، بخشیان گفتند که این از شومی مسلمانی است، اگر پادشاه ترک آن گیرد، از آتش گذشتن منجح آید و در مدت سه ماه در فتور و تذبذب میبودند، سلطان در این فکر و تردد، با این ایناقان، وقتها میگفت که مدتی است در دین اسلام و ادرار طاعات و عبادات، کلفتی بسیار کشیدم، ترک اسلام بکلی نتوان کرد. در اثنای این تحیر طرمطاز عرضه داشت که غازان خان که از اعقل و اکمل جهانیان بود بسبب اعتقادات میل به مذهب شیعه فرمود، سلطان را همان اختیار میباید کرد. سلطان فرمود که مذهب شیعه کدام است ؟ طرمطاز گفت آنکه به رفض مشهور است . سلطان بانگ بر وی زد و گفت ای بدبخت مرا رافضی سازی . طرمطاز به تمهید عذر وی مشغول گشت و مذهب سلطان ترتیبی داد و او مردی فصیح و محیل بود به تمهیدی تمام، تزییف مذهب اهل سنت و جماعت میکرد، با سلطان گفت که شیعه آن است که میگویند پادشاهی بعد از چنگیزخان ازآن ِ اروق اوباشد، و سنی آن است که گویند پادشاهی چنگیزخان ازآن ِ امراء فراجو باشد که نزدیکان چنگیزخان باشند و از این جنس مزخرفاتی چند تقریر کرد و سلطان را در غایت نیکواعتقادی و میل طبیعت به دین اسلام و متابعت و محبت محمد رسول اﷲ میل بدان طرف شد. و در اثنای این حالت سیدتاج الدین آوجی با جمعی از ائمه ٔ شیعه به حضرت آمدند و زبان وقیعت در مذهب اهل سنت و جماعت کشیدند، دائماً پادشاه را تحریض کردند و مولانا نظام الدین عبدالملک با ایشان نیز به مجادله و مناظره برخاست و با ائمه ٔ شیعه بحث کردی، و قواعد مزیف ایشان را در نظر پادشاه آوردی و به سمع سلطان گذرانیدی و شیعیان را مالیده داشتی و ایشان را با او کمال معارضه و قدرت مناظره نبودی . اتفاقاً در آن زمستان بسبب کار اوقاف آذربایجان از حضرت غایب شد و پادشاه در این حال سنه ٔ تسع و سبعمائة (<span class=\"hlight\" dir=\"rtl\">٧٠٩</span> هَ . ق .) عزیمت بغداد کرد و چون بدانجا رسید به زیارت مشهد علی علیه السلام رفت . اتفاقاًآنجا خوابی دید که دلالت میکرد در تقویت دین مسلمانی . چون صورت واقعه با امراء بازگفت امراء متشیع که جمعی میل بدان طریقت داشتند سلطان را تحریض تمام کردندبر اختیار مذهب شیعه و سلطان مذهب شیعه اختیار فرمود و غلوی عظیم کردند در آن باب چنانکه سلطان با امراو ایناقان خود مبالغت میکردند که تمامت این مذهب اختیار کنند بعضی رعایت حال سلطان را و بعضی از کم اعتقادی و بعضی بطبع خود مایل بودند بیشتر آن مذهب اختیار کردند و شیعیان را کار بالا گرفت و امرای سعید چوپان و ایسن قتلغ رحمه اﷲ تعالی در مذهب اهل سنت صلب بودند و هرگز در اعتقاد ایشان هر دو فتوری ظاهر نشد، تابه حدی که امرای دیگر که میل کرده بودند به حضور ایشان در آن حتی مجال سخن نداشتند بلکه جماعت سادات و اهل شیعه که ملازم بندگی حضرت بودند از ایشان خایف بودند و به لطائف الحیل تدبیر چندانکه خواستندی که ایشان را میل بدان طرف پدید کنند، میسرشان نشد و حکم رفت که در تمامت ممالک ایران زمین تغییر کنند خطبه را و نام صحابه ٔ سه گانه رضی اﷲ عنهم از خطبه بیندازند و بر نام امیرالمؤمنین علی بن ابیطالب و حسن و حسین سلام اﷲ علیهم اختصار کنند و تغییر سکه کردند در سنه ٔ تسعو سبعمائة از نام صحابه با نام امیرالمؤمنین و حی علی خیرالعمل در اذان اظهار کردند، و در تمامت ممالک اولجایتو سلطان این معنی منتشر شد، الا در قزوین و مذهب شیعه رونقی و رواجی تمام گرفت و ائمه ٔ آن طایفه را از اطراف طلب داشتند. شیخ جمال الدین حسن بن المطهرالحلی به حضور آمد و او مردی دانشمند متبحر بود از تلامذه ٔ خواجه نصیرالدین ودر علوم معقول و منقول مشهور و یگانه ٔ جهان و تصنیفات بسیار ساخته و چون به حضرت سلطان آمد، دو نسخه بنام پادشاه تصنیف کرده برسم تحفه آورد، یکی «نهج الحق و کشف الغمة و الصدق » در علم کلام، و «منهاج الکرامة من باب الامامة» در مذهب شیعه، و این دو کتاب از کتب معظمه ٔ آن طایفه است . چون به حضرت سلطان رسید سلطان او را و پسرش را مولانا فخرالدین محمدبن جمال الدین سنجاری (؟) و غیرهم را اجازت فرمود که به وطن خود رفتند و میان شیخ جمال الدین بن المطهر و مولانا نظام الدین عبدالملک مناظرات بسیار واقع شد و مولانا نظام الدین او را احترام عظیم کردی و در تعظیم او مبالغت نمودی ومباحثات ایشان از جهت استفادت و افادت بودی نه بر طریق جدل و لجاج و عناد و شیخ جمال الدین حسن بن المطهرهرگز بر طریق تعصب بحث نکردی در توقیر و تعظیم صحابه رضوان اﷲ علیهم مبالغت فرمودی و اگر کسی در حق صحابه کلمه ای بد بگفتی ممانعت تمام فرمودی و رنجش کردی وبا سلطان سعید خلوت داشتی، و پسرش نیز در مجالس حاضر شدی، و سلطان را بر محبت صحابه و تعظیم ایشان تحریض فرمودی، و کلماتی را که شیعیان متعصب گویند، بغایت منکر بودی و منع کردی و به انواع عاطفت و مرحمت از ادرارات و مرسومات و مسامحات در ولایت حله مخصوص شد وتا تاریخ سنه ٔ اربع و عشرین و سبعمائة (<span class=\"hlight\" dir=\"rtl\">٧٢٤</span> هَ . ق .) در قید حیات بود. و سیدبدرالدین نقیب مشهور طوس باجمعی سادات ملازم سلطان شد و هرچند از سادات بزرگوارچیزی که لایق منصب و شرف ایشان نباشد صادر نشده اما جمعی فتانان اِنارت نائره ٔ فتنه میکردند و مسلمانان را در شهرها زحمت میدادند و اهل سنت و جماعت نیز از این معنی منفعل نشدند و بر اعتقاد پاک و محبت صحابه ٔمصطفی و مودت اهل بیت و تعظیم امیرالمؤمنین علی و فرزندان او صلوات اﷲ و سلامه علیه و علیهم اجمعین الی یوم الدین راسخ میبودند و هرچند از طرفین تعصبها قائم شد و به محاجات و محاکات و غیره رسید اما به جائی نرسید و سلطان سعید از غایت محبت دین اسلام و دوستی محمد رسول اﷲ و اهل بیت او دائماً با علما در مناظره و مباحثه میبود و اهل علم را رونقی تمام و چنان علم دوست بود که بفرمود به استصواب و فکر خواجه رشیدالدین تا مدرسه ای سیاره بساختند از خیمه های کرباس و دائماً با اردو میگردانیدند و در آنجا مدرسی چند تعیین فرمود، چنانکه شیخ جمال الدین حسن بن المطهر و مولانا نظام الدین عبدالملک و مولانا نورالدین تستری و مولانا عضدالدین آوجی و سیدبرهان الدین عبری و قرب صد طالب علم رادر آنجا اثبات کردند و ترتیب مأکول و ملبوس و اولاغ و دیگر مایحتاج ایشان مهیا فرمود تا دایم در بندگی حضرت میباشند و در سلطانیة در ابواب البر مبارک مدرسه ای انشاء فرمود و شانزده مدرس و معبد و دویست طالب علم را اثبات فرمود تا چنان شد که در زمان دولت او روز بازار علم و فضل رواجی تمام یافت و تمامت آن معانی به مساعی جمیله ٔ خواجه رشیدالدین بود که سلطان را در این معنی تحریض فرمودی تا چندان فاضل و عالم در آن زمان مبارک پیدا شدند که به وصف درنگنجد. (حاشیه ٔ صص <span class=\"hlight\" dir=\"rtl\">٤٨</span> - <span class=\"hlight\" dir=\"rtl\">٥١</span> از ذیل جامعالتواریخ رشیدی تألیف حافظ ابرو چ بیانی منقول از مجمعالتواریخ نسخه ٔ ملک ج <span class=\"hlight\" dir=\"rtl\">٣</span> ورق <span class=\"hlight\" dir=\"rtl\">٢٣٧</span>).<br /></font></div>'),
(176706, 'طرمطاس', '<span class=\"hlight\">طرمطاس .</span> <font color=\"DarkGreen\"><b>[ طُ رُ ]</font></b> (اِ) قسمی گاری و عرابه . نوعی دلیجان .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(176707, 'طرمطای', '<span class=\"hlight\">طرمطای .</span> <font color=\"DarkGreen\"><b>[ طُ رُ ]</font></b> (اِ) پرنده ای است مگس خوار.<br /></font></div>'),
(176708, 'طرمطراق', '<span class=\"hlight\">طرمطراق .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابوعبداﷲ محمدبن ابی بکر جرجانی، ملقب به طرمطراق . نویسنده و شاعری ظریف و فاضلی از اعیان عمال بخارا است و نام وی در ضمن ترجمه ٔ احوال هرثمی گذشت .<br />سیدابوجعفر موسوی این شعر را که ابوعبداﷲ در نزد وی انشاء کرده است برای او روایت کرده است :<br />نصیبنا من طول آمالنا<br />تعسف فی خدمة دائبة<br />و حاصل الذل بلاطائل <br />و الشأن فی منظر العاقبة.<br />و این ابیات از اشعار ظریف و ملیح وی درباره ٔ پسری از فرزندان موالی بخاراست که شاعر به عشق وی گرفتار بوده است :<br />انا و الصبر فقد بشرنی <br />نائب المسک بصفحات العتیق <br />سنة اخری و قد اخرجنی <br />شعر خدیک من العقد الوثیق .<br />و ابوسعد نصربن یعقوب این ابیات را از قصیده ٔ وی در وصف خرگاه برای من انشاد کرده است :<br />کأنه سحب من فضة ضربت <br />و زینت بدنانیر مفاصله <br />ان قر لیل کفی النیران ساکنه <br />او جاد غیث فلن یغشاه هاطله <br />لاتحذر الهدم فیه حین تنزله <br />اذا توالت علی بیت زلازله .<br /> <font color=\"Red\">(یتیمةالدهر ثعالبی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨</span>).</font><br />و رجوع به ص <span class=\"hlight\" dir=\"rtl\">٦١</span> همان جلد شود.<br /></font></div>'),
(176709, 'طرمطی', '<span class=\"hlight\">طرمطی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) از امرائی بود که در قرن ششم هجری به مقامات بلندی در دربار سلاطین سلجوقی کرمان نائل آمده است . رجوع به فهرست تاریخ افضل شود.<br /></font></div>'),
(176710, 'طرموث', '<span class=\"hlight\">طرموث .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) سست . ناتوان . <BR><font color=\"Blue\">◄</font> نان در خاکستر گرم پخته . (منتهی الارب ) (آنندراج ). گرده . (دهار). رجوع به طرموس شود. <BR><font color=\"Blue\">◄</font> جاهل (؟). (منتخب اللغات ).<br /></font></div>'),
(176711, 'طرموح', '<span class=\"hlight\">طرموح .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص ) بلندبالا. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176712, 'طرموس', '<span class=\"hlight\">طرموس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) نان که در خاکستر گرم پخته باشند. کوماج . (منتهی الارب ) (آنندراج ). نان که بر سنگ پزند. نان سگاره . ج، طرامیس . (مهذب الاسماء). رجوع به طرموث شود. <BR><font color=\"Blue\">◄</font> دروغ زن . (مهذب الاسماء).<br /></font></div>'),
(176713, 'طرموق', '<span class=\"hlight\">طرموق .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) شب پره . (منتهی الارب ) (آنندراج ). خفاش . (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویه ).<br /></font></div>'),
(176714, 'طرمولس', '<span class=\"hlight\">طرمولس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) حسک است . (فهرست مخزن الادویه ). رجوع به طرمولوس شود.<br /></font></div>'),
(176715, 'طرمولوس', '<span class=\"hlight\">طرمولوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) حسک است . (فهرست مخزن الادویه ). رجوع به طرمولس شود.<br /></font></div>'),
(176716, 'طرمولون', '<span class=\"hlight\">طرمولون .</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (معرب، اِ) بادآورده است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176717, 'طرمیس', '<span class=\"hlight\">طرمیس .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) بنا به گفته ٔ قفطی، به زبان یونانی نام حضرت ادریس است . (تاریخ الحکماء قفطی چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(176718, 'طرمیس', '<span class=\"hlight\">طرمیس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b>(اِخ ) از قراء دمشق است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥</span>).<br /></font></div>'),
(176719, 'طرمینس', '<span class=\"hlight\">طرمینس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به سریانی بطم است . (فهرست مخزن الادویه ) (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(176720, 'طرمینون', '<span class=\"hlight\">طرمینون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به لغت یونانی نوعی از سنگ یشب باشد و بهترین آن سبزرنگ است . گویند اگر بر بازو بندند از صاعقه ایمن باشند. (برهان ) (آنندراج ). حجر الیشف است . (تحفه ٔ حکیم مؤمن ). نوعی از حجر یشف است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176721, 'طرن', '<span class=\"hlight\">طرن .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) جامه ٔ ابریشم . (منتهی الارب ) (آنندراج ). نوعی از خز است . (فهرست مخزن الادویه ). خز. (منتخب اللغات ).<br /></font></div>'),
(176722, 'طرنابادا', '<span class=\"hlight\">طرنابادا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به سریانی نخاله ٔ حنطه است . (فهرست مخزن الادویة).<br /></font></div>'),
(176723, 'طرنب', '<span class=\"hlight\">طرنب .</span> <font color=\"DarkGreen\"><b>[ طُ رُمْب ْ ]</font></b> (اِ) بمعنی خودنمائی است و آن را طاق و طرنب نیز گویند، طمطراق هم به همین معنی است . وقتی در عالم صحبت گفته ام <span class=\"hlight\">:</span> <br />ای احمق تا به چندت این طاق و طرنب <br />چون دیو همی غریو و چون رعد غرنب <br />داری شکمی زیاده پر همچون خنب <br />گاوی به صفت ولی نداری سم و دنب .<br /> <font color=\"Red\">(از آنندراج ).</font><br />و رجوع به طاق و طرنب شود.<br /></font></div>'),
(176724, 'طرنباطی', '<span class=\"hlight\">طرنباطی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابوعبداﷲمحمدبن مسعود الطرنباطی العثمانی . وی از ابناء قرن <span class=\"hlight\" dir=\"rtl\">١٣</span> هجری است و او راست کتاب ارشادالمسالک الی فهم الفیة ابن مالک که در سال <span class=\"hlight\" dir=\"rtl\">١٢٠٦</span> هَ . ق . از اتمام آن فراغت یافت . کتاب مذکور دو نوبت در شهر فاس پایتخت سابق مراکش به طبع رسید، نوبتی بسال <span class=\"hlight\" dir=\"rtl\">١٣٠٥</span> و نوبت دیگر بسال <span class=\"hlight\" dir=\"rtl\">١٣١٥</span> هَ . ق . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٠</span>).<br /></font></div>'),
(176725, 'طرنة', '<span class=\"hlight\">طرنة.</span> <font color=\"DarkGreen\"><b>[ طُ ن َ ]</font></b> (ع اِ) بساطالغول . در بعضی نسخ طریه آمده . رجوع به دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢</span> و لکلرک ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤١٠</span> شود.<br /></font></div>'),
(176726, 'طرنجبین', '<span class=\"hlight\">طرنجبین .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ج َ ]</font></b> (معرب، اِ) معرب ترانگبین . (دهار) (مهذب الاسماء). و آن شیره ای است که از شترغار پدید آید مانند شهد، و در مدارک مذکور است که از آسمان همچو برف میبارید بر قوم مهتر موسی علیه السلام بوقت صبح و آن را به تازی مَن ّ خوانند. (آنندراج ). ترنجبین . عسل گزنکور. رجوع به ترانگبین شود.<br /></font></div>'),
(176727, 'طرنجوماتس', '<span class=\"hlight\">طرنجوماتس .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ت ِ ]</font></b> (معرب، اِ) طرنجومانس . طریخومانس . رجوع به فهرست مخزن الادویه و طرنجومانس شود.<br /></font></div>'),
(176728, 'طرنجومالیتس', '<span class=\"hlight\">طرنجومالیتس .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ت ِ ]</font></b> (معرب، اِ) کرکم است که زعفران باشد و گفته اند نوعی از هزارجشان است . (فهرست مخزن الادویة).<br /></font></div>'),
(176729, 'طرنجومانس', '<span class=\"hlight\">طرنجومانس .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ما ن ِ ]</font></b> (معرب، اِ) به یونانی دوایی است که آن را به فارسی پرسیاوشان و به عربی شعرالجن خوانند. (برهان ) (اختیارات بدیعی ). به یونانی شعرالغول است . (تحفه ٔ حکیم مؤمن ). اصل آن طریخومانس و یونانی است .<br /></font></div>'),
(176730, 'طرنجیدن', '<span class=\"hlight\">طرنجیدن .</span> <font color=\"DarkGreen\"><b>[ طُ رَ دَ ]</font></b> (مص ) چین و شکن یافتن . ترنجیدن . آژنگ افتادن <span class=\"hlight\">:</span> طرنجیدن، علامت خاصه ٔ لقوه ٔ تشنجی است که حاستها بر حال خویش باشد و پوست عضله ٔ روی سخت باشد. (ذخیره ٔ خوارزمشاهی ). و اگر عضله ٔ صدغ و عضله ٔ روی و عضله ٔ پیشانی را صلب و طرنجیده یابد... معلوم گردد که لقوه ٔ تشنجی است . (ذخیره ٔ خوارزمشاهی ). <BR><font color=\"Blue\">◄</font> کشیده شدن . تمدد. و رجوع به ترنجیدن شود.<br /></font></div>'),
(176731, 'طرنجیدگی', '<span class=\"hlight\">طرنجیدگی .</span> <font color=\"DarkGreen\"><b>[ طُ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) کشیدگی . ترنجیدگی <span class=\"hlight\">:</span> و تمدد را به پارسی طرنجیدگی گویند. (ذخیره ٔ خوارزمشاهی ). و خطها و شکنهای پوست پیشانی، بسبب طرنجیدگی پوست ناپیدا شود. (ذخیره ٔ خوارزمشاهی ). و این درست نیست، از بهر آنک اگر علت اندر جانب راست بودی نقصان حس و طرنجیدگی عضله ها اندر آن جانب بودی . (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(176732, 'طرنشول', '<span class=\"hlight\">طرنشول .</span> <font color=\"DarkGreen\"><b>[ طُ ن ُ ]</font></b>(معرب، اِ) به سریانی صامریوما نامند. (فهرست مخزن الادویه ). آفتاب گردان . آفتاب گردک . آفتاب پرست . تنوم . شجرةالیمام . ایلیوطرفیون طوماغا. طرنشولی در اصطلاح عوام اسپانیا. (ابن البیطار). رجوع به طرنشولی و طورناشولی و دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢</span> شود.<br /></font></div>'),
(176733, 'طرنشولی', '<span class=\"hlight\">طرنشولی .</span> <font color=\"DarkGreen\"><b>[ طُ ن ُ ]</font></b> (معرب، اِ) رجوع به طرنشول و طورناشولی شود.<br /></font></div>'),
(176734, 'طرنم', '<span class=\"hlight\">طرنم .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (اِ) نارجیل است . (فهرست مخزن الادویة).<br /></font></div>'),
(176735, 'طرنگ', '<span class=\"hlight\">طرنگ .</span> <font color=\"DarkGreen\"><b>[ طُ رِ]</font></b> (اِخ ) دهی از دهستان کوشک بخش بافت شهرستان سیرجان، در <span class=\"hlight\" dir=\"rtl\">٧٤</span>هزارگزی جنوب خاوری بافت و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی خاور راه فرعی بافت به اسفندقه . کوهستانی سردسیر با <span class=\"hlight\" dir=\"rtl\">٤٤٢</span> تن سکنه . آب آن از قنات و محصول آن غلات و حبوبات و شغل اهالی زراعت و راه آن مالرو است . مزرعه ٔ پشته ٔ آدوری جزء این ده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(176736, 'طرنگاد', '<span class=\"hlight\">طرنگاد.</span> <font color=\"DarkGreen\"><b>[ طُ رُ ]</font></b> (از لاتینی، اِ) این لفظ از کلمه ٔ درنگاریس لاتینی اخذ شده و آن عبارت است از رتبه ای که بطریقها به جانشینان خود اعطا کنند.صاحب بیان الادیان ذیل فرقه ٔ «الملکائیة» یکی از فِرَق مسیحیان آورده : ترتیب ایشان در دین و حرب، محتشم ترین ایشان بطریق باشند... و قیصر را... دوازده بطریق باشد... طرنگاد، از دست بطریق باشد، و او را فسطیار نیز گویند و هزار مرد فرمان بردارش باشد. (بیان الادیان صص <span class=\"hlight\" dir=\"rtl\">١٥</span> - <span class=\"hlight\" dir=\"rtl\">١٦</span>). و رجوع به حواشی بیان الادیان ص <span class=\"hlight\" dir=\"rtl\">٥٨</span> شود.<br /></font></div>'),
(176737, 'طرنگست', '<span class=\"hlight\">طرنگست .</span> <font color=\"DarkGreen\"><b>[ طَ رَ گ َ ]</font></b> (اِ) آوازه ٔ سازها که از اوتار باشد. (حاشیه ٔ لغت فرس اسدی نخجوانی ). آواز تار سازهای ذوی الاوتار.<br /></font></div>'),
(176738, 'طرنگشت', '<span class=\"hlight\">طرنگشت .</span> <font color=\"DarkGreen\"><b>[ طَ رَگ َ ]</font></b> (اِ) رجوع به طرنگست شود. (فرهنگ اسدی ص <span class=\"hlight\" dir=\"rtl\">٥١</span>).<br /></font></div>'),
(176739, 'طرنیانة', '<span class=\"hlight\">طرنیانة.</span> <font color=\"DarkGreen\"><b>[ طِ ن َ]</font></b> (اِخ ) شهری است به مغرب . (منتهی الارب ). شهری است به اندلس از ناحیه ٔ قبرة. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>).<br /></font></div>'),
(176740, 'طرنیلون', '<span class=\"hlight\">طرنیلون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) طالیسفر است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176741, 'طره', '<span class=\"hlight\">طره .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) دهی است از دهستان برزرود بخش نطنز شهرستان کاشان در <span class=\"hlight\" dir=\"rtl\">٣٥</span>هزارگزی شمال باختر نطنز و <span class=\"hlight\" dir=\"rtl\">١٤</span>هزارگزی باختر پل هنجن . کوهستانی و سردسیر. با <span class=\"hlight\" dir=\"rtl\">٧٤٠</span> تن سکنه . آب آن از <span class=\"hlight\" dir=\"rtl\">٩</span> رشته قنات است . محصول آنجا غلات و حبوبات و میوه جات و شغل اهالی زراعت و عده ای برای تأمین معاش برای کارگری به طهران میروند. <span class=\"hlight\" dir=\"rtl\">٣</span> مزرعه دارد. راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(176742, 'طره بازی', '<span class=\"hlight\">طره بازی .</span> <font color=\"DarkGreen\"><b>[ طُرْ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (حامص مرکب ) بازی که اطفال بازند و آن چنان است که کرباسی را مثل تازیانه تاب داده بر یکدیگر زنند و در محاوره هر چیز تاب داده را طره گویند و لهذا اطلاق آن بر تازیانه که در عرف هند کره خوانند نیز درست شده و اغلب که کره مغیر آن است <span class=\"hlight\">:</span> <br />اگرچه رفته بسر دور طره بازی مخلص <br />ولی چو طره ٔ زلف تو دید تاب ندارد.<br /> <font color=\"Red\">مخلص کاشی (از آنندراج ).</font><br />و در تداول محلی گناباد و بعضی نواحی دیگر آن را «درنه بازی » گویند. دُرنابازی .<br /></font></div>'),
(176743, 'طره بخاخ', '<span class=\"hlight\">طره بخاخ .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ب َخ ْ خا ]</font></b> (اِخ ) قصبه ای از دهستان بهمن شیر بخش مرکزی شهرستان آبادان در <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی جنوب خاوری آبادان و <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی خاوری شوسه ٔ خسروآباد به آبادان . دشت و گرمسیر و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٣٠٠٠</span> تن سکنه . آب آن از رود بهمن شیر. محصول آنجا خرما و سبزیجات . شغل اهالی زراعت و ماهی گیری و کارگری شرکت نفت . راه آن در تابستان اتومبیل رو است . ساکنین از طایفه ٔ محسنی هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(176744, 'طرهامال', '<span class=\"hlight\">طرهامال .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) غافث است . (فهرست مخزن الادویة). ظاهراً این کلمه مصحف ترهلان یا ترهلا باشد که درزبان بربر آن را بر غافث یا طباق اطلاق کنند. رجوع به مفردات ابن البیطار ذیل طباق و ترجمه ٔ لکلرک شود.<br /></font></div>'),
(176745, 'طرهان', '<span class=\"hlight\">طرهان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام طایفه ای است از ایلات کرد ایران که شامل دوازده شعبه بترتیب ذیل است : سوری، امرائی، گراوند، دماوند، کوشکی، آدینه وند، ازدج، رومیانی، چاواری، بوالی، آزادبخت، کرمان . تعداد خانوار ایل مزبور تقریباً <span class=\"hlight\" dir=\"rtl\">٧٠٠٠</span>و شماره ٔ نفوسش (قریب به ) <span class=\"hlight\" dir=\"rtl\">٤٠٠٠٠</span> تن است که محل سکونت آنان، جنوب غربی خرم آباد، جنوب دلفان، بین رود کشکان و صیمره، خاوه، طرهان میباشد. در ناحیه ٔ طرهان معدن زغال سنگ کشف شده است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>). و رجوع به تاریخ کرد تألیف رشیدیاسمی ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span> شود.<br /></font></div>'),
(176746, 'طرهان', '<span class=\"hlight\">طرهان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی است از دهستان طرهان بخش طرهان شهرستان خرم آباد، <span class=\"hlight\" dir=\"rtl\">٣٦</span>هزارگزی باختر شوسه ٔ فرعی خرم آباد به کوهدشت . کوهستانی، معتدل مالاریائی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> تن . آب آن از رودخانه ٔ خسروآباد. محصول آنجا غلات و تریاک و لبنیات . شغل اهالی زراعت و گله داری است و صنایع دستی زنان سیاه چادربافی و راه آن اتومبیل رو است . دبستان و<span class=\"hlight\" dir=\"rtl\">٦</span> باب دکان دارد. ساکنین از طایفه ٔ کوتانی اند و زمستان قشلاق میروند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(176747, 'طرهان', '<span class=\"hlight\">طرهان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) یکی از دهستانهای بخش طرهان شهرستان خرم آباد. این دهستان در باختر بخش واقع و محدود است از خاور به دهستان کوه دشت، از باختر به رودخانه ٔ صیمره، از شمال به بخش دلفان و رود صیمره، از جنوب به دهستان رومشکان . موقع طبیعی کوهستانی، هوا گرمسیر. آب آن از رودخانه ٔصیمره و چاه . مرتفعترین قلل جبال در این دهستان کوههای بلوران، سرآستان، خیاران، رودبار گور میباشد. مراتع مرغوبی در سینه و دامنه ٔ این کوهستان وجود دارد.از <span class=\"hlight\" dir=\"rtl\">٤٠</span> آبادی تشکیل گردیده . جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">٨٣٠٠</span> تن و قرای مهم آن عبارتند از: پشته گراب، قلعه بساطبیگی، گرخوشاب، کاوه . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(176748, 'طرهان', '<span class=\"hlight\">طرهان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) یکی از بخشهای شهرستان خرم آباد. این بخش در باختر شهرستان واقع و حدود آن بشرح زیر است : از خاور به رودخانه ٔکشکان و بخش چکنی، از باختر رود صیمره، از شمال به بخش دلفان، از جنوب به رود صیمره و رود کشکان . موقع طبیعی جلگه، کوهستانی و دامنه، گرمسیر و قسمتی معتدل . آب آن از رودخانه های کشکان، صیمره، نهر و چاه و محصول آنجا غلات و تریاک و لبنیات است . بقرار اظهار مطلعین محل، معادن نفت و گچ و نمک در این بخش وجود دارد. این بخش از سه دهستان و <span class=\"hlight\" dir=\"rtl\">١٤١</span> آبادی بشرح زیر تشکیل گردیده : دهستان کوهدشت <span class=\"hlight\" dir=\"rtl\">٦٨</span> آبادی جمعیت <span class=\"hlight\" dir=\"rtl\">٢٨٥٢</span> تن . دهستان رومشکان <span class=\"hlight\" dir=\"rtl\">٣٣</span> آبادی جمعیت <span class=\"hlight\" dir=\"rtl\">٧٩٢٠</span> تن . دهستان طرهان <span class=\"hlight\" dir=\"rtl\">٤٠</span>آبادی جمعیت <span class=\"hlight\" dir=\"rtl\">٨٢٥٦</span> تن . ساکنین این بخش از طوایف امرائی، گراوند، آزادبخت، زرونی، کومانی، سوری، آدینه وند، کوشکی میباشند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(176749, 'طرهانی بالا', '<span class=\"hlight\">طرهانی بالا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی است از دهستان حسنوند بخش سلسله ٔ شهرستان خرم آباد، در <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی جنوب باختری الشتر، کنار باختر شوسه ٔ خرم آباد به الشتر. جلگه و سردسیر و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٩٠</span> تن سکنه . آب آن از سراب عمارت . محصول آنجا غلات و تریاک و حبوبات و لبنیات و پشم . شغل اهالی زراعت و گله داری و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(176750, 'طرو', '<span class=\"hlight\">طرو.</span> <font color=\"DarkGreen\"><b>[ طُ رُوو ]</font></b> (ع مص ) از دور درآمدن . (منتهی الارب ) (آنندراج ). یقال : طرا طُرُوّاً؛ از دور درآمد. (منتهی الارب ). آمدن از جای دور. (منتخب اللغات ).<br /></font></div>'),
(176751, 'طرواخا', '<span class=\"hlight\">طرواخا.</span> <font color=\"DarkGreen\"><b>[ طُرْ ]</font></b> (اِخ ) قریه ای است از قرای بخارا. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>).<br /></font></div>'),
(176752, 'طرواخی', '<span class=\"hlight\">طرواخی .</span> <font color=\"DarkGreen\"><b>[ طِرْ ]</font></b> (ص نسبی ) منسوب به طرواخ که از قرای بخاراست و عامه ٔاهل این قریه آن را طِرواخی تلفظ کنند. (سمعانی ).<br /></font></div>'),
(176753, 'طروان', '<span class=\"hlight\">طروان .</span> <font color=\"DarkGreen\"><b>[ طُرْ ]</font></b> (اِ) مؤلف فرهنگ شعوری آن را بمعنی غاشیه گرفته بیتی نادرست از میرنظمی نقل میکند. رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٨</span> شود.<br /></font></div>'),
(176754, 'طروب', '<span class=\"hlight\">طروب .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طَرَب . شادیها. (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(176755, 'طروب', '<span class=\"hlight\">طروب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) مرد بسیارطرب . (منتهی الارب ). شادمان . (غیاث اللغات ) (آنندراج ). آنکه پیوسته شاد بُوَد <span class=\"hlight\">:</span> <br />گندم و جو را و باقی حُبوب <br />تو توانی خورد نی من ای طَروب .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(176756, 'طروبیون', '<span class=\"hlight\">طروبیون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به یونانی انجدان است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176757, 'طروج', '<span class=\"hlight\">طروج .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) حمداﷲ مستوفی در نزهةالقلوب ذیل ذکر انهار آذربایجان آورده : آب تغتو، از کوههای کردستان به حدود گریوه ٔ سیناء برمیخیزد و به آب جغتو، جمع شده به دریای شور طروج میریزد، طولش پانزده فرسنگ باشد. آب جغتو، از کوههای کردستان به حدود ده سیاه کوه برمیخیزد و بر ولایت مراغه گذشته، به آب صافی و آب تغتو در دریای شور طروج میریزد، طولش بیست فرسنگ باشد. و نیز در ذیل ذکر بحیرات ایران آورده که : بحیره ٔ چیچست، به ولایت آذربایجان، آن را دریا شور گویند، بلاد ارومیه و اشنویه و دهخوارقان و طروج و سلماس بر ساحل اوست و در میانش جزیره ای و بر آنجا کوهی است که مدفن پادشاهان مغول است، آبهای تغتو و جغتو و صافی و سراورود در او میریزد، دورش چهل وچهار فرسنگ باشد. (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٢٢٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٤١</span>).<br /></font></div>'),
(176758, 'طروح', '<span class=\"hlight\">طروح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) جای دور. <BR><font color=\"Blue\">◄</font> قوس ٌ طروح ٌ؛ کمان تیردورانداز. <BR><font color=\"Blue\">◄</font> خُرمابن درازشاخ . <BR><font color=\"Blue\">◄</font> مرد که در هر آرامش با زن وی را باردار سازد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176759, 'طرود', '<span class=\"hlight\">طرود.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) دهی جزء دهستان مرکزی بخش فیروزکوه شهرستان دماوند در <span class=\"hlight\" dir=\"rtl\">٢٠٠٠٠</span> گزی خاور فیروزکوه و در <span class=\"hlight\" dir=\"rtl\">٥٠٠٠٠</span> گزی شمال راه شوسه ٔ فیروزکوه به سمنان . کوهستان سردسیر با <span class=\"hlight\" dir=\"rtl\">٦٩٠</span> تن سکنه . آب آن از چشمه سار و محصول آنجا غلات و بنشن و سیب زمینی و جزئی بیدستان و لبنیات . شغل اهالی زراعت و مکاری و گلیم و جاجیم بافی . راه آن مالرو است و تا نزدیکی آبادی ماشین میرود. مزرعه ٔ ارو و کلارخان جزء این ده است . در تابستان ایل سنگسری به حدود این ده می آیند. بین طرود و میرشکار معدن زغال سنگ وجود دارد. از آثار قدیم قلعه ٔ خرابه ٔ لاجوردی بین کلارخان و طرود واقع اخیراً به اجازه ٔ وزارت فرهنگ شروع به کاوش شده است . نام این قلعه در شاهنامه جائی که یزدگرد موقع عقب نشینی دستور نگاهداری چند قلعه را برای حفظ بنه میدهد برده شده است (دژ گنبدان و دژ چرمنه، دژ لاجوردی برای بنه ). قلعه ٔ خرابه ٔ آرو در شمال طرود و قلعه ٔ خرابه ای نیز در خود آبادی وجود دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(176760, 'طرود', '<span class=\"hlight\">طرود.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) دهستانی است از بخش مرکزی شهرستان شاهرود. این دهستان تقریباً در <span class=\"hlight\" dir=\"rtl\">١٥٠</span>هزارگزی جنوب باختری شاهرودو <span class=\"hlight\" dir=\"rtl\">١٠٠</span>هزارگزی جنوب خاوری دامغان در حاشیه ٔ دشت کویرواقع شده . هوای آن زمستان معتدل و تابستان گرم . آب قرای آن از قنوات تأمین میشود. محصول عمده ٔ آن ارزن و جو و ذرت و شلغم و مختصر گندم و صیفی است . این دهستان از <span class=\"hlight\" dir=\"rtl\">٨</span> آبادی و چندین مزرعه تشکیل شده و جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">٣٥٠٠</span> تن است . مرکز دهستان قریه ٔ طرود میباشد. قراء مهم آن عبارتند از بیدستان و سطوه . راه دهستان مالرو میباشد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(176761, 'طرود', '<span class=\"hlight\">طرود.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) قصبه ٔ مرکز دهستان طرود بخش مرکزی شهرستان شاهرود در <span class=\"hlight\" dir=\"rtl\">١٠٢</span>هزارگزی جنوب شاهرود. دشت کویر، تابستان گرم، زمستان معتدل . سکنه ٔ آن در حدود <span class=\"hlight\" dir=\"rtl\">٢٠٠٠</span> تن است . آب آن از قنات مهم کمی لب شور. محصول آن جو، ارزن، مختصر گندم و پنبه و شلغم، خربزه و هندوانه . شغل اهالی زراعت و گله داری و راه آن مالرو است . مزارع چشمه سفید، تنگ قلی، مهابیا، سعدا، شش بالا وسط و پائین، صحن، گرگاب، انجیرود، مرزه، دله، چاه موش (مسی ) درویش سالاران، علیخان، قنوره، اورگاره، بجارآباد، دره دائی جزء قصبه ٔ طرود است . دبستان دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(176762, 'طرود', '<span class=\"hlight\">طرود.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن فَهْم بن عمرو. از قبیله ٔ قیس عیلان، عدنانیه، یکی از اجداد جاهلیان . شاعری از پسران وی بنام اعشی طرود در شعرای تازی نام برده شده است . منازل بنی طرود در زمین نجد بوده است و از آنجا به افریقیه داخل شدند. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>).<br /></font></div>'),
(176763, 'طرور', '<span class=\"hlight\">طرور.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) روشن شدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رُستن نبات . <BR><font color=\"Blue\">◄</font> دمیدن سبلت . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> تیز کردن سنان . (منتخب اللغات ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) بُریدگی است در مقدم پیشانی دختر، مانند زیر تاج و گاهی از رامک (که بوی خوشی است ) سازند. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176764, 'طروز', '<span class=\"hlight\">طروز.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طَرْز.<br /></font></div>'),
(176765, 'طروس', '<span class=\"hlight\">طروس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طِرس .<br /></font></div>'),
(176766, 'طروسیقوس', '<span class=\"hlight\">طروسیقوس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) رجوع به طرسیقوس و آنندراج و غیاث اللغات شود.<br /></font></div>'),
(176767, 'طروطلون', '<span class=\"hlight\">طروطلون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی سلق است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176768, 'طروغلودقس', '<span class=\"hlight\">طروغلودقس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) رجوع به طرغلودیس شود.<br /></font></div>'),
(176769, 'طروغلودقطس', '<span class=\"hlight\">طروغلودقطس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) رجوع به طرغلودیس شود.<br /></font></div>'),
(176770, 'طروغلودوطس', '<span class=\"hlight\">طروغلودوطس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) رجوع به طرغلودیس شود.<br /></font></div>'),
(176771, 'طروغلودیس', '<span class=\"hlight\">طروغلودیس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) رجوع به طرغلودیس شود.<br /></font></div>'),
(176772, 'طروغلودیطس', '<span class=\"hlight\">طروغلودیطس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) رجوع به طرغلودیس شود.<br /></font></div>'),
(176773, 'طروغلوطس', '<span class=\"hlight\">طروغلوطس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی نوعی از مرو خوش بو است . (فهرست مخزن الادویة).<br /></font></div>'),
(176774, 'طروغلوقطس', '<span class=\"hlight\">طروغلوقطس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) عصفورالشوک است و عصفورالسیاح نیز گویند و آن مرغی است بمقدار گنجشک و در بال وی پر زرد بود، نقطی سیاه بر دنبال وی بود و بر لب آب نشیند و دمی دراز دارد و مدام دم حرکت دهد. به شیرازی دمتک تاکیک گویند و منفعت وی آن است که سنگ مثانه بریزاند و منع آن کند و رها نکند که دیگر جمع شوددر مثانه . دیسقوریدوس گوید: چون از جوف او اندک بخورند سنگ بریزاند. وی را صفراغون و طروغلودیس نیز گویند. (اختیارات بدیعی ). ظاهراً مصحف طروغلودیس است .<br /></font></div>'),
(176775, 'طروغلونفطس', '<span class=\"hlight\">طروغلونفطس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) صفراغون است .(فهرست مخزن الادویة). ظاهراً مصحف طروغلودیس است .<br /></font></div>'),
(176776, 'طروغلیطوس', '<span class=\"hlight\">طروغلیطوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ)به یونانی بزر سداب بری است . (فهرست مخزن الادویة).<br /></font></div>'),
(176777, 'طروف', '<span class=\"hlight\">طروف .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طرف .<br /></font></div>'),
(176778, 'طروفس', '<span class=\"hlight\">طروفس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی دُردی خمر است . (فهرست مخزن الادویه ). رجوع به طروکس شود.<br /></font></div>'),
(176779, 'طروفوقون', '<span class=\"hlight\">طروفوقون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی زعروراست که طریفوقون نیز نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(176780, 'طروق', '<span class=\"hlight\">طروق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) راهرو. سالک <span class=\"hlight\">:</span> <br />هر طروقی این فروقی کی شناخت <br />چون دقوقی کاو در این دولت بتاخت .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(176781, 'طروق', '<span class=\"hlight\">طروق .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) برجستن گشن بر ماده . (منتهی الارب ). گشنی کردن شتر. (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> به شب آمدن کسی را. (منتهی الارب ). به شب آمدن . (تاج المصادر بیهقی ) (زوزنی ). آمدن به شب . <BR><font color=\"Blue\">◄</font> طلوع .<br /></font></div>'),
(176782, 'طروقوقون', '<span class=\"hlight\">طروقوقون .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (معرب، اِ) طریقوقن گویند. و سیلقون قاونیا نیز گویند. و آن زعرور است . (اختیارات بدیعی ). به لغت یونانی میوه ای است صحرائی که آن را به عربی زعرور و در خراسان علف شیران گویند و آن را طریقوقن هم خوانده اند و بعضی گویند زعرور هم یونانی است . (برهان ) (آنندراج ). این کلمه مصحف طریکوکوس یونانی است . رجوع به طریقوقن و طریقوقون شود.<br /></font></div>'),
(176783, 'طروقومون', '<span class=\"hlight\">طروقومون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) زعرور است . (تحفه ٔ حکیم مؤمن ). مصحف طروقوقون که مصحف طریکوکوس است . رجوع به طروقوقون شود.<br /></font></div>'),
(176784, 'طروقون', '<span class=\"hlight\">طروقون .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (معرب، اِ) به یونانی گلی است که آن را بستان افروز و تاج خروس گویند. (برهان ) (آنندراج ). برطانیقی است . (اختیارات بدیعی ) (تحفه ٔ حکیم مؤمن ). برطانیقس است وبعضی بستان افروز دانسته اند. (فهرست مخزن الادویه ).<br /></font></div>'),
(176785, 'طرون', '<span class=\"hlight\">طرون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) از مشاهیر بلاد ارمنیةالصغری است . (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٢٦٤</span>). موضعی است به ارمینیه . (منتهی الارب ). جایگاهی است به ارمینیه که بحتری شاعر عرب نام آن را در این بیت خود که از قصیده ای که در مدیحه ٔ محمدبن یوسف سرود آورده است :<br />و لا عز للاشراک من بعدما التقت <br />علی السفح من علیا طرون عساکره .<br /><BR><font color=\"Blue\">◄</font> و نیز حصاری است بین بیت المقدس و رمله که آن حصار هم از فتوحات صلاح الدین ایوبی بسال <span class=\"hlight\" dir=\"rtl\">٥٨٣</span> هَ . ق . در تواریخ ثبت است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>).<br /></font></div>'),
(176786, 'طروکس', '<span class=\"hlight\">طروکس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی دُردی خمر است . رجوع به طروفس شود.<br /></font></div>'),
(176787, 'طرپی', '<span class=\"hlight\">طرپی .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (فرانسوی، اِ) ترپی . نوعی از ماهی پهن که شبیه به سفره ماهی است و در سر آن عضوی دارای قوه ٔ برق است و با آن دستی را که بخواهد آن را بگیرد بیحس میکند و سایر ماهیها را با آن میکشد. <BR><font color=\"Blue\">◄</font> آلت جنگی که با آن در زیر آب انفجار تولید میکنند. و رجوع به طربیداس و ترپی و ترپیل شود.<br /></font></div>'),
(176788, 'طرکسو', '<span class=\"hlight\">طرکسو.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) تربد است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176789, 'طرکونه', '<span class=\"hlight\">طرکونه .</span> <font color=\"DarkGreen\"><b>[ طَرْ رَ ن َ ]</font></b> (اِخ ) شهری است به اندلس . (منتهی الارب ). یاقوت آرد: شهری است به اندلس متصل به اعمال طرطوشه و آن میان طرطوشه و برشلونه واقع است و میان طرکونه و هر یک از دوشهر مزبور <span class=\"hlight\" dir=\"rtl\">١٧</span> فرسخ مسافت است . (از معجم البلدان ). وصاحب الحلل السندسیه آرد: طرکونه شهری دریائی است که ساکنان آن هم اکنون بیش از <span class=\"hlight\" dir=\"rtl\">٢٥</span> هزار تن نیست، در صورتی که شهر مزبور در روزگار رومیان دارای یک میلیون تن بوده است . این شهر یکی از مراکز اسقفهاست و اسقف آن را مانند اسقف طلیطله بریماط اسپانیا مینامند. جایگاه اسقف ها در بلندترین نقطه ٔ خاوری شهر در محل قلعه ٔ قدیم واقع است و کنیسه ٔبزرگ نیز در همان محل است . این شهر به دو قسمت قدیم و جدید تقسیم میشود. ناحیه ٔ بلند آن را بخش قدیم تشکیل میدهد و در آن بقایا و آثار بسیار و سنگ نبشته هائی از روزگار رومیان است و قسمت جدید شهر دارای خیابانهای مستقیم است و همین بخش است که در کنار دریا واقع میباشد. و باره های طرکونه از سه سوی نمودار است و تنها باره ٔ جانب باختری آن منهدم گردیده است . این شهر در روزگار ایبریها بنیان نهاده شده است و گویند نخستین کسانی که در آن سکونت گزیده اند یکی از قبایل ایبری موسوم به سیسیتان بوده اند که مسکوکاتی هم از آنان به یادگار مانده است و همین قبیله نیز باره های شهر را در سال <span class=\"hlight\" dir=\"rtl\">٢٦٧</span> ق .م . بنا کرده اند و هنگامی که میان کارتاژها و رومیان جنگ روی داد سرداران رومی از قبیل سیبیون و همراهانش به شهرهجوم آوردند و بر آن استیلا یافتند و در آن بندر و باره های بلندی بنیان نهادند و از آن پس شهر مزبور جزومهمترین مستعمرات رومیان در اسپانیا بشمار میرفت . واین واقعه یعنی تصرف شهر به دست رومیان پس از سال <span class=\"hlight\" dir=\"rtl\">٢١٨</span> ق .م . روی داده است . آنگاه در سال <span class=\"hlight\" dir=\"rtl\">٢٦</span> اگوست قیصر روم بدین شهر رفت و در آنجا سکونت گزید و در آن هیکلی <font color=\"DarkGreen\"><b>[ معبدی ]</font></b> عظیم و بناهای باشکوهی بنیان نهاد و والیان روم نیز از روش وی پیروی میکردند و دلبستگی و توجه خاصی بدین امر مبذول میداشتند و آثار عظیم ایشان در این عصر نیز همچنان گواه نموداری است . در سال <span class=\"hlight\" dir=\"rtl\">٤٧٥</span> م . گت ها بر طرکونه استیلا یافتند و تازیان بسال <span class=\"hlight\" dir=\"rtl\">٧١٣</span> م . آن شهر را متصرف شدند وهنگامی که مسیحیان در سال <span class=\"hlight\" dir=\"rtl\">١٨١٨</span> م . طرکونه را از تازیان بازستدند مرکز اسقف ها را بار دیگر بنیان نهادند ولی شهر مزبور آن اهمیت تجارتی را که در گذشته داشت به دست نیاورد بلکه بازرگانی اسپانیا در جهت شمال به بارسلن و در جهت جنوب به بلنسیه ٔ عربی انتقال یافت .و نیز باید دانست که بندر طرکونه در دوران عرب بجز بندر کنونی بوده است بلکه بندر مزبور در پائین آبادیهای ساحلی بندر جدید قرار داشته است، آنگاه کتلان در اواخر قرن پانزدهم بندر دیگری بنیان نهادند و آنها سنگهای تماشاخانه ٔ رومی را در این بندر بکار بردند.<br />مشهورترین خیابانهای طرکونه عبارتند از: رمله ٔ سان جوان و رمله ٔ سان کارلوس و کنیسه ٔ بزرگ را بر روی پایه های هیکل <font color=\"DarkGreen\"><b>[ معبد ]</font></b> رومی و پایه های مسجد جامع زمان قدرت عرب بنیان نهاده اند و همینکه در سال <span class=\"hlight\" dir=\"rtl\">١٨١٨</span> عرب را از طرکونه راندند بیدرنگ مسجد را به کنیسه تبدیل کردند و طول این عبادتگاه یکصد و چهار متر است و دارای برجی است که ارتفاع آن <span class=\"hlight\" dir=\"rtl\">٦٥</span> متر است و در آن از نامورترین نقاشان و مجسمه سازان تصاویر و مجسمه هائی وجود دارد و قبر ژاک اول آراگونی ملقب به فاتح و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٢٧٦</span>م . در آن کنیسه واقع است . و در شهر طرکونه موزه ٔ مخصوص نگهداری آثار باستانی است که در آن مجسمه ها و تابوتها و تکه های کاشی بسیار متعلق به عهد رومیان و جز آنان وجود دارد و نیز در موزه ٔ مزبور انواع سلاحهاو سکه های ایبری و فینیقی و رومی یافت میشود و از جمله یادگارهای مشهور طرکونه قنات معلق رومی است که درآن از رود غیه آب جاری ساخته اند. این قنات دارای دو طبقه است، طبقه ٔ پائین آن دارای یازده کمانه و طبقه ٔ بالای آن دارای <span class=\"hlight\" dir=\"rtl\">٢٥</span> کمانه است . طول طبقه ٔ نخستین <span class=\"hlight\" dir=\"rtl\">٧٣</span> متر و طول طبقه ٔ دوم <span class=\"hlight\" dir=\"rtl\">٢١٧</span> متر است و محل جریان آب از آغاز سرچشمه ٔ آن بطول <span class=\"hlight\" dir=\"rtl\">٣٥</span> کیلومتر است . در روزگار فرمانروائی عرب طرکونه را شهر یهود میگفتند زیرا گروه بسیاری از یهودیان در آن سکونت داشتند چنانکه در غرناطه نیز اقوام یهود بسیار بودند. در دائرة المعارف اسلام آمده است که : عرب بسال <span class=\"hlight\" dir=\"rtl\">٧٢٤</span> م . طرکونه را ویران کردند و بر آن استیلا یافتندو شهر مزبور تا پایان فرمانروائی دولت اموی اندلس همچنان در تصرف عرب بود لیکن پس از سقوط خلافت اموی درقرطبه و ظهور دوران ملوک طوایف، لویس حاکم اکیطانیه بدان شهر لشکر کشید و آن را متصرف شد، آنگاه عرب بدان لشکر کشیدند و آن را بازگرفتند. و بار دیگر رامون بیرانجه بدان شهر تاخت وبر آن استیلا یافت و باز عرب آن را بازستد و سرانجام در سال <span class=\"hlight\" dir=\"rtl\">١١٢٠</span> م . شهر مزبور به دست مسیحیان سقوط کرد و برای همیشه به تصرف آنان درآمد. و نیز در دائرة المعارف اسلام ذکر پنجره ٔ مرمر بدینسان آمده است که بر آن نام عبدالرحمان سوم مکتوب است و پنجره ٔ مزبور در رواق کنیسه ٔ بزرگ است . و در این رواق پنجره ٔ کوچکی بر دیواری است که بر آن تاریخی به خط کوفی نوشته شده و هم نام خلیفه الناصر بر آن مکتوب است و تاریخ مزبور سال <span class=\"hlight\" dir=\"rtl\">٣٤٧</span> هَ . ق . است . ولی صاحب دائرة المعارف مینویسد که تاریخ مزبور سال <span class=\"hlight\" dir=\"rtl\">٣٤٩</span> است ... و در پیرامون طرکونه جلگه ٔ پهناور آبادی است که دارای تاکستانها و درختان زیتون و گردو و بادام فراوان است . این دشت را خط آهنی که از شهر و دهکده های بسیار میگذرد قطع میکنداز قبیل شهرهای «رویس » و«سلبه » و «مونت بلانش » که شهر اخیر بر کنار رود «فرنکولی » واقع است و دارای باره ها و برجهای قدیمی است و مردم از شهر مزبور به دیدن آثار دیر معروف به دیر «سان پوبله » میروند و این دیر به مردی موسوم به پوبله منسوب است که عرب زمام امور ناحیه ٔ هاردیتا را به وی سپرده بود. و در این دیر مقبره ای متعلق به ملوک آراگون بوده است و دیر مزبور بعلت فتنه هائی که بین سالهای <span class=\"hlight\" dir=\"rtl\">١٨٢٨</span> و <span class=\"hlight\" dir=\"rtl\">١٨٣٥</span> روی داده منهدم گردیده است و قبور نیز ویران شده است لیکن آثار آنها همچنان نمودار است و خط آهنی که از طرکونه به لارده میرود نخست در امتداد رود جریان دارد سپس از آن دور میشود و شارات برادس را قطع میکند و همچنان از جانب شرقی شارات بالا میرود تا به جایگاهی میرسدکه ارتفاع آن بیش از هزار متر است . مقبره ٔ ملوک بسمت پائین و نشیب میگراید و پس از گذشتن از شهرهائی مانند وینکسا و فلورستا و برجاس و ژیندا به لارده میرسد و میان طرکونه و لارده بیش از صد کیلومتر مسافت است . اما خط آهن طرکونه به طرطوشه، از سمت راست مشرف بر دشت طرکونه و از سمت شمال مشرف بر دریاست و از ناحیه ای میگذرد که در آنجا اشجار خرنوب و بادام و نخلستان های بسیاری است . و بر مسافت <span class=\"hlight\" dir=\"rtl\">١٩</span>کیلومتری طرکونه شهری است موسوم به کامبریلس و بر مسافت <span class=\"hlight\" dir=\"rtl\">٣٣</span>کیلومتری آن شهر هسپیتاله واقع است که شهر مزبور در قدیم یکی از منازل مسافران بوده است و زمین های این ناحیه آهکی است و از این رو در آن بجز درختان کمیابی نمیروید وکوههای آن تهی از درخت و گیاه و مشرف بر دریا میباشند. و در همین ناحیه شهری است موسوم به امتیله که شغل مردم آن شکار ماهی است و بر ساحل دریا دولابهائی وجود دارد که بوسیله ٔ آنها زمین را آبیاری میکنند و در <span class=\"hlight\" dir=\"rtl\">٧١</span>کیلومتری طرکونه شهر امپوله واقع است که بر خلیجی موسوم به خلیج سان ژرژ مشرف است . این شهر دارای موقع زیبایی است، چه از آن منظره ٔ رود ابره مشاهده میشود و از رود مزبور شعب بسیاری برای آبادیهای گوناگون منشعب میگردد. و در سمت خاور این شهر مناره یا فانوسی دریائی است که آن را مناره ٔ فنگال مینامند و در جنوب شرقی آن مناره ٔ دیگری است که در بالای طرطوشه و نزدیک شهر کوچکی موسوم به امپوسته واقع است و در سمت جنوب امپوسته قناتی است که بسوی بندر روان است و آن را سان گارلوس رابطه میخوانند و مصب نهر ابرة کبیردر اینجا واقع است که به دو شعبه تقسیم میشود و جزیره ٔ موسوم به بودا دو شعبه ٔ مزبور را از یکدیگر جدا میکند و شهر طرطوشه در <span class=\"hlight\" dir=\"rtl\">٨٤</span>کیلومتری طرکونه بر ساحل رود ابره واقع است و میان شهر رویس و بارسلن بیش از صد کیلومتر مسافت است . و شهر رویس دارای <span class=\"hlight\" dir=\"rtl\">٢٦</span> هزار سکنه میباشد و آن شهری صنعتی است که در دامنه ٔ کوه واقع است و دارای حصنهای قدیمی بوده است که هم اکنون ویران شده اند و در جایگاه آنها اکنون دهکده های جدیدی بنا شده است و کنیسه ٔ «سان بدور» در این شهر واقع است که دارای برجی است به ارتفاع <span class=\"hlight\" dir=\"rtl\">٦٦</span> متر و در این شهر برخی از بازرگانان انگلیس در اوائل قرن گذشته کارخانه های ریسندگی تأسیس کرده اند که در آنها پنج هزار نورد است . رفته رفته صنعت در این شهر پیشرفت کرده و کارخانه های حریربافی و چرمسازی و صابون پزی و انواع کارخانه های مشروبات الکلی در آن تأسیس یافته است و در نتیجه شهر رویس دومین شهر صنعتی در ناحیه ٔ کتلونی بشمار میرود و در مسیر خط آهن میان رویس و بارسلن شهر صنعتی دیگری موسوم به والس واقع است که دارای <span class=\"hlight\" dir=\"rtl\">١٣</span> هزار جمعیت و باروها و برج های قدیمی است و نزدیک شهر والس در وادی غایه دیری است که آن را رامون بیرانجه ٔ چهارم بسال <span class=\"hlight\" dir=\"rtl\">١١٥٧</span> م . بنا کرده است . این دیر از لحاظ حسن صنعت کتلانی شبیه به دیر پوبله بوده است که در سابق آن را یاد کردیم ولی دیر رامون در آشوب سال <span class=\"hlight\" dir=\"rtl\">١٨٣٥</span> منهدم گردیده است و در آن قبور پادشاهان بسیاری قرار داشته است از قبیل : بتره ٔ سوم ملک آراگون متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٢٨٥</span> م . و جیمس دوم متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٣٢٧</span> م . و همسرش ملکه ٔ بلاش دانجو و همچنین قبر روجیر لوریا که در عهد بتره ٔ سوم فرمانده ناوگان بود.وی همان فرماندهی است که در واقعه ٔ ناپل ناوگان فرانسه را درهم شکست و هم قبور رامون غیلر و مونکادا در آن دیر واقع است و این دو تن در واقعه ٔ استیلای اسپانیول بر میورقه بسال <span class=\"hlight\" dir=\"rtl\">١٢٢٩</span>هنگامی که اعراب را از اسپانیا خارج میکردند کشته شدند. دیگر از شهرهائی که در مسیر خط آهن بین رویس و بارسلن واقعاند شهر سان فنسنت کالدرس است که محل تلاقی دو شعبه ٔ راه آهن فرعی است : یکی به طرکونه و دیگری به بارسلن . و در اینجا دروازه ٔ رومی عظیمی است که آن را پرتال باره میگویند و نیز قریه ای موسوم به روضه باره در آنجا واقع است .همچنین در مسیر این خط قصبه ای است موسوم به ویلانیواگلتری دارای دوازده هزار تن و بازرگانی آن قابل اهمیت است . همچنین موزه ای داردکه مشتمل بر آثار قدیم مصری و رومی است . و در مسیر این خط در آن جهت که محاذی دریاست قریه ای است بنام سیتغس که از دهکده های زیبابشمار میرود و بیش از سه هزار تن جمعیت دارد و دارای لنگرگاهی برای کشتیهاست و نیز موزه ای موسوم به موزه ٔ روزینبون دارد که در آن آثار هنری گرانبهائی یافت میشود و این مصنوعات را از مواد معدنی و فلزات ساخته اند. (از الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٢٦٣</span> - <span class=\"hlight\" dir=\"rtl\">٢٧١</span>). و رجوع به فهرست ج <span class=\"hlight\" dir=\"rtl\">١</span> و <span class=\"hlight\" dir=\"rtl\">٢</span> همان کتاب و تاراگون شود.<br /></font></div>'),
(176790, 'طرکونه', '<span class=\"hlight\">طرکونه .</span> <font color=\"DarkGreen\"><b>[ طَرْ رَ ن َ ]</font></b> (اِخ ) شهری است به مغرب . (منتهی الارب ). و یاقوت آرد: موضع دیگری است به اندلس از اعمال لبلة. (معجم البلدان ). رجوع به ماده ٔ بعد شود.<br /></font></div>'),
(176791, 'طرکیدن', '<span class=\"hlight\">طرکیدن .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b> (مص ) از هم شکافتن و پاره شدن . (آنندراج ). صورتی است از ترکیدن و طرقیدن . و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span> شود.<br /></font></div>'),
(176792, 'طری', '<span class=\"hlight\">طری .</span> <font color=\"DarkGreen\"><b>[ طُرْ را ]</font></b> (ع ص ) خرماده ٔ رانده . خر ماده ٔ دورکرده شده . (منتهی الارب ).<br /></font></div>'),
(176793, 'طری', '<span class=\"hlight\">طری .</span> <font color=\"DarkGreen\"><b>[ طَ را ]</font></b> (ع مص ) پیش آمدن . <BR><font color=\"Blue\">◄</font> گذشتن و رفتن . یقال : طَرِی َ طَری ً. (منتهی الارب ).<br /></font></div>'),
(176794, 'طری', '<span class=\"hlight\">طری .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ناحیتی خرد است از بجه، میان حدود نوبه و سودان و اندر وی دو صومعه است و گویند که اندر وی دوازده هزار مرد است راهب . (حدود العالم ).<br /></font></div>'),
(176795, 'طری', '<span class=\"hlight\">طری .</span> <font color=\"DarkGreen\"><b>[ طَ ری ی ]</font></b> (ع ص ) تازه و تر. (منتهی الارب ) (آنندراج ). گویند معرب تری است که تازگی و رطوبت باشد. (برهان ). شاداب . باطراوت <span class=\"hlight\">:</span> <br />تا چو نوروز درآرد سپه خویش به باغ <br />باغ پر لاله ٔ نو گردد و گلهای طری .<br /> <font color=\"Red\">فرخی .</font><br />هر زمان گوئی بر دو رخ و بر عارض من <br />قمر است و سمن تازه ٔ خوشبوی طری .<br /> <font color=\"Red\">فرخی .</font><br />از نرگس طری و بنفشه حسد برد<br />کآن هست از دو چشم و دو زلف بتی نشان .<br /> <font color=\"Red\">منوچهری .</font><br />برگ گل مُوَرَّدِ بشکفته ٔ طری <br />چون روی دلربای من آن ماه سعتری .<br /> <font color=\"Red\">منوچهری .</font><br />چون بهم کردی بسیار بنفشه ٔ طبری <br />باز برگرد و به بستان شو چون کبک دری <br />تا کجا بیش بود نرگس خوشبوی طری <br />که به چشم تو چنان آید چون درنگری <br />که ز دینار درآویخت کسی چند پری <br />همه را دسته کن و بسته کن و پیش من آر.<br /> <font color=\"Red\">منوچهری .</font><br />وآنچ او ز دور مرده کند زنده <br />بس زنده و طری بود و زیبا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />گلی جزسخن دید هرگز کسی <br />که بی آب و بی نم همیشه طری است ؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />باغی است پر از گل طری لیکن <br />بنهفته بزیر هر گلی خاری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />حجت دینی به سخنهای من <br />شد چو به قطره ٔ سحری گل طری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گرچه گلی چونت آب روی بود<br />تو نه گِلی توطری و تازه گُلی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />همچو ورد طری بتاب و بخند<br />همچو سرو سهی ببال و بناز.<br /> <font color=\"Red\">مسعودسعد.</font><br />ای سوزنی به مدح شه از بوستان طبع<br />دم با نسیم ورد طری زن ز حلق و نای .<br /> <font color=\"Red\">سوزنی .</font><br />رخ احباب تو طری است چو گل <br />رخ شیرین تر از گلاب و گلاج .<br /> <font color=\"Red\">سوزنی .</font><br />لیک کو آن قربت شاخ طری <br />که ثمار پخته از وی میبری .<br /> <font color=\"Red\">مولوی .</font><br />میزند بر روش ریحان که طری است <br />او ز کوری گوید این آسیب چیست ؟<br /> <font color=\"Red\">مولوی .</font><br />خار کو مادر گلبرگ طری است <br />زآنکه آزار کند سوختنی است .<br /> <font color=\"Red\">سلمان ساوجی .</font><br /><BR><font color=\"Blue\">◄</font> تازه و نو. (آنندراج ). ثوب طری ؛ جامه ٔ نو. (مهذب الاسماء). و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span> شود.<br /></font></div>'),
(176796, 'طریادفلان', '<span class=\"hlight\">طریادفلان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی ساذج است . (فهرست مخزن الادویه ). در مفردات ابن البیطار نام یونانی ساذج مالابتروم یا مالابترن است .<br /></font></div>'),
(176797, 'طریاس', '<span class=\"hlight\">طریاس .</span> <font color=\"DarkGreen\"><b>[ طَ رُ ]</font></b> (اِخ ) شهری از روم قدیم . رجوع به عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧</span> س <span class=\"hlight\" dir=\"rtl\">٦</span> و <span class=\"hlight\" dir=\"rtl\">٢٧</span>شود. امروزه طریاس حصارلیق نامیده میشود، و در آسیای صغیر به مسافت یک هزار گز از کنار دریا آثار آن موجود است . جنگ ده ساله ٔ با یونان که موضوع اشعار رزمی هومر میباشد معروف است . (یسنا پورداود ص <span class=\"hlight\" dir=\"rtl\">٩٢</span> حاشیه ٔ <span class=\"hlight\" dir=\"rtl\">١</span>). و رجوع به تروا شود.<br /></font></div>'),
(176798, 'طریاق', '<span class=\"hlight\">طریاق .</span> <font color=\"DarkGreen\"><b>[ طِرْ ]</font></b> (معرب، اِ) تریاق است وزناً و معناً. (منتهی الارب ) (آنندراج ). طراق . (منتهی الارب ). به فارسی تریاک گویند. (فهرست مخزن الادویه ). جوالیقی گوید: لغتی است در دریاق (که در حرف دال ذکر شد). و نیز در حرف دال آورده : دریاق لغتی است در تریاق . و آن رومی و معرب است . قال الراجز:<br />ریقی و دریاقی شفاءالسم .<br />و دریاقة شراب باشد. حسان گوید:<br />من خمر بیسان تخیرتها<br />دریاقة توشک فترالعظام .<br /> <font color=\"Red\">(از المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">١٤٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٥</span>).</font><br />و رجوع به تریاق و تریاک شود.<br /></font></div>'),
(176799, 'طریان', '<span class=\"hlight\">طریان .</span> <font color=\"DarkGreen\"><b>[ طِرْ ریا ]</font></b> (ع اِ) خوان ها. (منتهی الارب ) (آنندراج ). تریان . ج، طریانات . (مهذب الاسماء). طَبَق . (برهان ).<br /></font></div>'),
(176800, 'طریان', '<span class=\"hlight\">طریان .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (ع مص ) حادث شدن . (غیاث اللغات ) (آنندراج ). نو درآمدن . (کنزاللغات ). <BR><font color=\"Blue\">◄</font> وارد شدن چیزی در چیزی . (غیاث اللغات ) (آنندراج ). بر سر چیزی درآمدن . (کنزاللغات ).<br /></font></div>'),
(176801, 'طریانة', '<span class=\"hlight\">طریانة.</span> <font color=\"DarkGreen\"><b>[ طِ ن َ ]</font></b> (اِخ ) یکی از بلاد اشبیلیه است . (معجم البلدان ). و رجوع به الحلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٩</span> شود.<br /></font></div>'),
(176802, 'طریانوس', '<span class=\"hlight\">طریانوس .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) تراژان . یکی از قیاصره ٔ روم قدیم که بسال <span class=\"hlight\" dir=\"rtl\">٥٢</span> م . در ایطالیکا یکی از بلاد اسپانی به دنیا آمد و از سال <span class=\"hlight\" dir=\"rtl\">٩٨</span> تا سال <span class=\"hlight\" dir=\"rtl\">١١٧</span> م . در روم پادشاهی کرد و از سال <span class=\"hlight\" dir=\"rtl\">١٠١</span> تا <span class=\"hlight\" dir=\"rtl\">١٠٥</span> م . با داسها و پارتها جنگید تا سرانجام بر هر دو غلبه یافت و آنان را تحت فرمان خود آورد. پادشاهی بود بسیار مدیر و دوستدار عمران و آبادی و نسبت به مسیحیان جفاکار. و رجوع به تاریخ الحکمای قفطی صص <span class=\"hlight\" dir=\"rtl\">١٢٦</span> - <span class=\"hlight\" dir=\"rtl\">١٢٧</span> و تراژان شود.<br /></font></div>'),
(176803, 'طریبله', '<span class=\"hlight\">طریبله .</span> <font color=\"DarkGreen\"><b>[ طِ ب ُ ل َ ]</font></b> (معرب، اِ) طریفلن است . (اختیارات بدیعی ) (تحفه ٔ حکیم مؤمن ). نام دارویی است که آن را حندقوقه و به فارسی اندقوقو گویند. اگر طفلی دیر به حرکت آید و حرکت اعضای مردم کم شود آب برگ آن را گرفته با روغن کنجد بجوشانندبعد از آن بر اعضا مالند به حرکت آید. تخم آن قوت باه دهد. (برهان ) (آنندراج ). و رجوع به طریفلن شود.<br /></font></div>'),
(176804, 'طریبیل', '<span class=\"hlight\">طریبیل .</span> <font color=\"DarkGreen\"><b>[ طُ رَ ]</font></b> (اِخ ) از دهات هَجر است که مرکز فرمانروای بحرین است . (مراصد). صیغه ٔمصغر است و آن از قرای هجر باشد. (معجم البلدان ).<br /></font></div>'),
(176805, 'طریة', '<span class=\"hlight\">طریة.</span> <font color=\"DarkGreen\"><b>[ طُرْ ی َ ]</font></b> (ع اِ) صورتی دیگر از طرنة (بساطالغول ) که در بعضی نسخ از مفردات ابن البیطار آمده است .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(176806, 'طریة', '<span class=\"hlight\">طریة.</span> <font color=\"DarkGreen\"><b>[طَ ری ی َ ]</font></b> (ع ص ) تأنیث طَری ّ، بمعنی تر و تازه .<br /></font></div>'),
(176807, 'طریة', '<span class=\"hlight\">طریة.</span> <font color=\"DarkGreen\"><b>[ طَ ری ی َ ]</font></b> (اِخ ) دهی است به یمن . (منتهی الارب ).<br /></font></div>'),
(176808, 'طریثیث', '<span class=\"hlight\">طریثیث .</span> <font color=\"DarkGreen\"><b>[ طُ رَ ]</font></b> (اِخ ) دهی است به نیشابور. (منتهی الارب ). طرشیز. ترشیز. دهات بسیاری است از اعمال نیشابور که طریثیث قصبه ٔ آنجاست . این ناحیه تا سال <span class=\"hlight\" dir=\"rtl\">٥٣٠</span> هَ . ق . همواره منبع افاضل و موطن علماء از اهل دین و صلاح بود، تا آنکه طایفه ٔ باطنیه ازفرقه ٔ ملاحده در همان سال بر نواحی قهستان و زوزن تاختن آوردند، عمید منصوربن منصور الزورآبادی که پدر بر پدر بر آن ناحیت ریاست داشت، از بیم آنکه مبادا ملاحده بر طریثیث نیز دست یابند، از ترکان استمداد کرد تا به کمک آنان حریم و اموال مسلمانان را از دستبرد و غارت باطنیه در امان دارد، گروهی از ترکان به یاری عمید آمدند اما بر حسب عادت جاریه ٔ خویش با اهالی بنای بدرفتاری گذاشته و جز اعمال اغراض شخصی چیزی از نهب و غارت فروگذار نکرده، از جانب دیگر عمید نیز که با ملاحده سخت سؤمعاملت داشت و در قتل آنان زیاده روی میکرد همینکه سود از وجود ترکان نبرد و تحمل رفتارنابهنجار آنان را بر خود ناهموار یافت ترکان را از خود دور ساخت و به ملاحده پناه برد، از این رو ناحیه ٔطریثیث از حیث ظاهر و باطن ترکان پاک شد و قلاع و ضیاع و املاک آنجا کاملاً تحت تصرف و اختیار عمید درآمد.وی مردی فقیه و مُناظر و نیک اعتقاد و شافعی مذهب بود، معذلک ضرورت وقت ایجاب کرد که خویش را تحت الحمایه ٔملاحده قرار دهد. چون مرگ وی فرارسید مردی شافعی را وصیت کرد که در تغسیل و تجهیز وی اقدام کند و نیز به پسرش علاءالدین محمود سفارش اکید کرد که در اظهار دعوت وی و احیاء معالم و سُنن اسلامی سعی و کوشش ورزد، پسر نیز در <span class=\"hlight\" dir=\"rtl\">٥٤٥</span> وصیت پدر را اجرا کرد و مردم را به پوشیدن جامه ٔ سیاه و اداء خطبه در جامع طریثیث فرمان داد اما عمو و اقربای وی با او مخالفت ورزیده، منبر را بشکستند، و خطیب را بکشتند، محمود نامه به نیشابوریان فرستاد و از آنان مدد طلبید، جواب مُساعد از احدی نشنید، علاءالدین محمود خود طریثیث را ترک گفته به نیشابور رفت، ملاحده نیز میدان را خالی یافته بر طریثیث دستی قوی یافتند و تا این زمان آنجا تحت سلطه و اقتدار ملاحده باقی است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>). و رجوع به تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٤</span> و <span class=\"hlight\" dir=\"rtl\">١١٨</span> و طرشیز و ترشیز شود.<br /></font></div>'),
(176809, 'طریثیثی', '<span class=\"hlight\">طریثیثی .</span> <font color=\"DarkGreen\"><b>[ طُ رَ ]</font></b> (ص نسبی ) منسوب به طریثیث که ناحیه ای است از نیشابور. (سمعانی ).<br /></font></div>'),
(176810, 'طریجومانس', '<span class=\"hlight\">طریجومانس .</span> <font color=\"DarkGreen\"><b>[ طَ ن ِ ]</font></b> (معرب، اِ) پرسیاوشان است . (فهرست مخزن الادویه ).تحریفی از طریخومانس است . رجوع به طریخومانس شود.<br /></font></div>'),
(176811, 'طریح', '<span class=\"hlight\">طریح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) جای دور. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> انداخته شده . (منتخب اللغات ). بمعنی مطروح . <BR><font color=\"Blue\">◄</font> (اِخ ) از اعلام است . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176812, 'طریح', '<span class=\"hlight\">طریح .</span> <font color=\"DarkGreen\"><b>[ طُ رَ ]</font></b> (اِخ ) الثقفی ابن اسماعیل بن عُبیدبن اسیدبن علاج بن ابی سلمةبن عبدالعزی . مادر وی خزاعیة دختر عبداﷲبن سباع ابوالصلت، شاعر مشهور عرب بوده است . در دولت بنی امیه نشو و نما یافت، همه ٔ قریحه ٔ خویش را در مدح ولیدبن یزید بکار برد. وی مخضرم شناخته میشود، زیرا دولتین اموی و عباسی را ادراک کرده است . وفات وی در روزگار مهدی خلیفه بسال <span class=\"hlight\" dir=\"rtl\">١٦٥</span> هَ . ق . بود. از اشعار برگزیده ٔ اوست :<br />اء لم تر المرء نصباً للحوادث ما<br />تنفک فیه سهام الدهر تنتضل ُ<br />ان یعجل الموت یحمله علی وضح <br />لجب موارده مسلوکةٌ ذُلل ُ<br />و ان تحادث به الایام فی عُمر<br />یخلق کما رث ّ بعد الجدة الحلل ُ<br />و یستمر الی ان یستقل به <br />ریب المنون و لو طالت به الطیل ُ<br />و الدّهر لیس بناج من دوائره <br />حی جبان و لا مستأسد بطل ُ<br />ولا دفین غیابات له نفق <br />تحت التراب و لا حوت و لا وعل ُ<br />بل کل شی ٔ سیبلی الدهر جدته <br />حتی یبید و یبقی اﷲ و العمل ُ.<br /> <font color=\"Red\">(معجم الادباءج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٦</span>).</font><br />در نکوهش قومی گفته است :<br />ان یعلموا الخیر یخفوه وان علموا<br />شراً اذیع و ان لم یعلموا کذبوا.<br /> <font color=\"Red\">(عیون الاخبار ابن قتیبة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨</span>).</font><br />زرکلی درالاعلام آورده : طریح ثقفی، شاعر و دوست مصاحب ولیدبن یزید اموی بود و پیش از آنکه ولید به خلافت رسد بدو پیوست و پیوستگی خویش را ادامه داد و بیشتر از اشعار او در مدیحه ٔ ولید میباشد. علاقه ٔ ولید به وی تا به حدی بود که نخستین کسی که در مجلس ولید حضور می یافت وآخرین کس که از محضر وی پای بیرون مینهاد طریح بود و هنگام پیش آمد مشکلات با طریح مشورت میکرد. وفات طریح در حدود سال بوده است .(الاعلام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>). و رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٨</span> و ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٤</span> و عیون الاخبار ابن قتیبة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٠</span> شود.<br /></font></div>'),
(176813, 'طریحة', '<span class=\"hlight\">طریحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (ع ص ) گوشت بر آتش افکنده . (نسخه ای خطی از مهذب الاسماء متعلق به کتابخانه ٔ مؤلف ). در یک نسخه ٔ دیگر خطی از مهذب الاسماء (نیز متعلق به کتابخانه ٔ مؤلف ) این لفظ را طرائحة ضبط کرده، با همان معنی بالا. «طریحة، گوشت بریان به آتش است که به فارسی کباب آتشی نامند». (فهرست مخزن الادویة). ظاهراً این لفظ بدین معنی مولد باشد.<br /></font></div>'),
(176814, 'طریحی', '<span class=\"hlight\">طریحی .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) (الشیخ الَ ...) نسب فخرالدین بن محمد معروف به شیخ طریحی . رجوع به روضات الجنات و معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٠</span> و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>، <span class=\"hlight\" dir=\"rtl\">٧٦٨</span> و الارشاد ص <span class=\"hlight\" dir=\"rtl\">١٠</span>، <span class=\"hlight\" dir=\"rtl\">١١</span>، <span class=\"hlight\" dir=\"rtl\">١٣</span> ترجمه ٔ احوال صاحب بن عباد شود.<br /></font></div>'),
(176815, 'طریخ', '<span class=\"hlight\">طریخ .</span> <font color=\"DarkGreen\"><b>[ طِرْ ری ]</font></b> (ع اِ) ماهیی است خرد که آن را نمک زده گذارند. (منتهی الارب ) (آنندراج ). نوعی از ماهی کوچک باشد که از طرف آذربایجان آورند. (برهان ). نوعی از ماهی کوچک است و گفته اند که از طرف آذربایجان می آورند و از طرف تبریز و این مؤلف گوید: آن را از لجه ٔ دریای قلزم گیرند و در آنجاآن را شاه ماهی خوانند، بهترین آن بود که کهن باشد، و طبیعت آن گرم و خشک بود، طبع براند، اندکی از وی ملطف بود سودا را در تبهای ربع، و وی مضر بود به سپرزو معده و مصلح وی روغن بسیار بود. (اختیارات بدیعی )<span class=\"hlight\">:</span> در آنجا <font color=\"DarkGreen\"><b>[ بحیره ٔ ارجیش به ولایت ارمن ]</font></b> ماهی طریخ بغایت خوب میباشد و از آنجا به ولایت دور برند. (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٢٤١</span>). نوعی ماهی است و آن ماهی باشد با گوشتی نهایت لذیذ و آن در دریاچه ٔ ارجیش باشد. ماهی خردی است که نمک سود کنند (و بسفایج را) در ماهی طریخ باید خوردن . (ذخیره ٔ خوارزمشاهی ). و ماهی طریخ نمک سود بر آتش نهند تا سرخ شود و بسوزد. (ذخیره ٔ خوارزمشاهی ). محمدبن عبدون گوید: طریخ ماهیی باشد کوچک چون بدستی و از دریاچه ٔ ارجیش صید کنند و از آنجا به بغداد آرند. صاحب منهاج گوید: بهترین این ماهی آن است که تازه گرفته باشند. گرم و خشک است و شکم براند و کمی از آن در تب ربع تلطیف سودا کند و مضر طحال باشد و اصلاح آن با روغن بسیار بود. (ابن البیطار). و لکلرک گوید: شاید اصل این کلمه طاریخای یونانی باشد، لکن در همه ٔ لغت نامه ها طریخ آمده است . و رجوع به بحر الجواهر شود.<br /></font></div>'),
(176816, 'طریخ', '<span class=\"hlight\">طریخ .</span> <font color=\"DarkGreen\"><b>[ طِرْ ری ]</font></b> (اِخ ) (بحیره ٔ...) یا دریاچه ٔ طریخ . دریاچه ٔ وان است که آن را دریاچه ٔ «ارجیش » نیز نامند. رجوع به «اِثریر» شود.<br /></font></div>'),
(176817, 'طریخومالس', '<span class=\"hlight\">طریخومالس .</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ ]</font></b> (معرب، اِ)تحریفی از طریخومانس است . رجوع به طریخومانس شود.<br /></font></div>'),
(176818, 'طریخومانس', '<span class=\"hlight\">طریخومانس .</span> <font color=\"DarkGreen\"><b>[ طَ ن ِ ]</font></b> (معرب، اِ) شعرالغول است . (مفردات ابن البیطار) . و رجوع به شعرالغول شود.<br /></font></div>'),
(176819, 'طرید', '<span class=\"hlight\">طرید.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) رانده شده . نفی و دور کرده شده . (منتهی الارب ) (آنندراج ). شرید. رانده . مطرود. اخراج بلدشده . <BR><font color=\"Blue\">◄</font> تنه ٔ درخت کج شده ٔ بی شاخ و برگ مانده . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> روز دراز. (منتهی الارب ) (آنندراج ). الطرید من الایام ؛ الطویل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنکه بعد دیگری زاده شده باشد و اول هم طرید ثانی است . (منتهی الارب ) (آنندراج ). الذی یولد بعدک و انت ایضاً طریده . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> صید.(مهذب الاسماء). رجوع به طریدة شود. <BR><font color=\"Blue\">◄</font> آنندراج گوید: خیرالمدققین میفرمایند که فعیل است بمعنی فاعل، از طرد که به معنی دور ساختن و گریزانیدن هوام و غیره است و آن کنایه از حمله باشد <span class=\"hlight\">:</span> <br />طریدی نیاورد و زنگی نمود<br />که پرگار بر نقطه تنگی نمود.<br /> <font color=\"Red\">نظامی .</font><br />و در این بیت <span class=\"hlight\">:</span> <br />طریدی برآورد و با روس گفت <br />که خواهی همین لحظه در خاک خفت <br />مراد از طرید آن کلام است که سامع از استماع آن هیبتی در دل گیرد و بیدل شود و از پیش حریف بگریزد <span class=\"hlight\">:</span> <br />که در عرصه ٔ فکر صیدی کنم <br />رجزخوان به میدان طریدی کنم (!).<br /> <font color=\"Red\">ظهوری (از آنندراج ).</font><br />چه مرکبان را بر هم زندطرید و نبرد<br />چه سرکشان را در هم کند طعان و ضراب .<br /> <font color=\"Red\">مسعودسعد.</font><br />رجوع به طریدة شود. <BR><font color=\"Blue\">◄</font> شعوری (ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span> ب ) به معنی بازی در میدان آورده با این شاهد از میر نظمی <span class=\"hlight\">:</span> <br />درآمد به میدان خرامان دگر<br />نماید طرید و بلعب و هنر(!).<br /></font></div>'),
(176820, 'طرید', '<span class=\"hlight\">طرید.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (... رسول اﷲ) لقب حکم بن ابی العاص است . رجوع به حکم بن ابی العاص و عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٢</span>ص <span class=\"hlight\" dir=\"rtl\">١٦٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٤</span> و ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١١٦</span> و ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠</span>، <span class=\"hlight\" dir=\"rtl\">٦٣</span> شود.<br /></font></div>'),
(176821, 'طریدان', '<span class=\"hlight\">طریدان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) تثنیه ٔ طرید. شب و روز. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176822, 'طریدن', '<span class=\"hlight\">طریدن .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b> (مص ) ظاهراًبمعنی راهزنی کردن و دزدی و عیاری است <span class=\"hlight\">:</span> <br />مر او را خود ز جنس خود رهاندی <br />که شد طرار در ایمان طریدن .<br /> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">٣٦٦</span>).</font><br />و رجوع به تریدن شود.<br /></font></div>'),
(176823, 'طریر', '<span class=\"hlight\">طریر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) مرد با منظر نیکو و دیداری . (منتهی الارب ). مرد خوب صورت و خوش لقا و دیداری . (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> غلام طریر؛ کودک نوخط. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> سنان ٌ طریرٌ؛ سنانی تیز. (منتهی الارب ) (آنندراج ) (مهذب الاسماء).<br /></font></div>'),
(176824, 'طریزآباد', '<span class=\"hlight\">طریزآباد.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی است جزء دهستان رودبار بخش طرخوران شهرستان اراک در <span class=\"hlight\" dir=\"rtl\">٣٦</span>هزارگزی شمال باختر طرخوران و <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی فرک . کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">١٧٨</span> تن سکنه . آب آن از رودخانه ٔ قره چای، محصول آنجا غلات و بنشن و پنبه و انگور، شغل اهالی زراعت و گله داری و قالیچه و گلیم و جاجیم بافی است . راه آن مالرو است و از طریق نوبهار اتومبیل میتوان برد. از آثار قدیم پل مخروبه ای است بر روی رودخانه ٔ قره چای . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(176825, 'طریطاوس', '<span class=\"hlight\">طریطاوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) علامه گوید: معنی آن به یونانی مثلثه است وشیخ گوید: طریطاوس ربع دائره است . (بحر الجواهر).<br /></font></div>'),
(176826, 'طریعن', '<span class=\"hlight\">طریعن .</span><font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) اسیوش است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176827, 'طریغاسا', '<span class=\"hlight\">طریغاسا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) نوعی از سمک بحری است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176828, 'طریغان', '<span class=\"hlight\">طریغان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) نوعی از کاسنی باشد و آن مانند گُل خسک زرد و خاردار می باشد و به عربی قرطم بری خوانند و بجای غین فا نیز آمده است . (برهان ) (آنندراج ).<br /></font></div>'),
(176829, 'طریغلا', '<span class=\"hlight\">طریغلا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) ترستوج . طرستوج . مول . قسمی ماهی . رجوع به طرستوج و دزی شود.<br /></font></div>'),
(176830, 'طریغودون', '<span class=\"hlight\">طریغودون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به یونانی رماد است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176831, 'طریغون', '<span class=\"hlight\">طریغون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به یونانی نام مرغی است که آن را بوتیمار گویند و به این معنی بجای غین قاف هم به نظر آمده است . (برهان ) (آنندراج ). شفنین بری است . (تحفه ٔ حکیم مؤمن ). بوتیمار است که به هندی بگله و کبوت نامند و به عربی یمام و شفنین نیز گویند. (فهرست مخزن الادویه ). غمخورک .<br /></font></div>'),
(176832, 'طریغیوس', '<span class=\"hlight\">طریغیوس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به یونانی سداب بری است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176833, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن یزید الحنفی . تابعی است و از ابوموسی روایت دارد. (تاج العروس ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span>).<br /></font></div>'),
(176834, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن مجالد، ابوتمیمه ٔ هجیمی . تابعی است . (منتهی الارب ). در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٩٥</span> وبقولی <span class=\"hlight\" dir=\"rtl\">٩٧</span> هَ . ق . درگذشت . (تاج العروس ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span>).<br /></font></div>'),
(176835, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن شهاب .ضعیف الروایة است . (منتهی الارب ). کنیتش ابوسفیان و ملقب به السعدی و تابعی است . رجوع به ابوسفیان شود.<br /></font></div>'),
(176836, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن مالک بن جدعان . از قبیله ٔ طی ٔ و از بطن قحطان . وی نیز جد جاهلیان است و جبلةبن رافع از نسل وی میباشد. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>). و رجوع به الموشح ص <span class=\"hlight\" dir=\"rtl\">٩٨</span> شود.<br /></font></div>'),
(176837, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن عمروبن قعین . از طایفه ٔ قیس عیلان و از بطن عدنان . وی جد جاهلیان است و فقعس ومنقذ از نسل وی میباشند. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>).<br /></font></div>'),
(176838, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) مؤلف الاعلام مینویسد: بی آنکه نسبی برای وی تعیین شده باشد طریف خود از بطن جذام و از طایفه ٔ قحطانیه بشمار میرفته است . بنوعجرمة و بنومهدی، اعراب سکنه ٔ بلقاء شام از نسل وی میباشند. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>).<br /></font></div>'),
(176839, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) مال نو. (منتهی الارب ) (آنندراج ). خلاف تلید. ج، طُرف . (منتهی الارب ) (آنندراج ). مال مستحدث . خلاف تالده . <BR><font color=\"Blue\">◄</font> آنکه او را تا جدّ اکبر او پدران بسیار در میان باشند. (منتهی الارب ) (آنندراج ). خلاف ِ قعدد. <BR><font color=\"Blue\">◄</font> نادر از ثمر و غیر آن . (منتهی الارب ) (آنندراج ). غریب . نادر. شگفت . <BR><font color=\"Blue\">◄</font> نوزاده . (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) ذُرة است و طعام متخذ از آن را نیز نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(176840, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) شهری است به اسپانیا. (نفح الطیب ). بندری به اسپانیا. (دمشقی ). جزیره ٔ طریف در اسپانیا. این جزیره بنام طریف بربری که با لشکر اسلام در جنگ با اندلسیان همراه و در فتوحات نیز با آنان سهیم بوده نامیده شده است . رجوع به الحلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٨٨</span>، <span class=\"hlight\" dir=\"rtl\">٣١٣</span>، <span class=\"hlight\" dir=\"rtl\">٣١٤</span>، <span class=\"hlight\" dir=\"rtl\">٣١٦</span>، <span class=\"hlight\" dir=\"rtl\">٣١٨</span>، <span class=\"hlight\" dir=\"rtl\">٣١٩</span> شود.<br /></font></div>'),
(176841, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طُ رَ ]</font></b> (اِخ ) نام مردی است . (منتهی الارب ).<br /></font></div>'),
(176842, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طُ رَ ]</font></b> (اِخ ) موضعی است به بحرین . (منتهی الارب ) (معجم البلدان ).<br /></font></div>'),
(176843, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طِرْ ی َ ]</font></b> (اِخ ) موضعی است به یمن . (منتهی الارب ). ناحیه ای است به یمن و اعراب را در آنجا وقعه ای بوده است . (معجم البلدان ).<br /></font></div>'),
(176844, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن شراحیل . از افراد قبیله ٔ بنی ربیعه است . در «یوم غول الاول » کشته شد. رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٩٤</span> شود.<br /></font></div>'),
(176845, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) بدون ذکری از پدر یا نسب وی . یکی از تابعیان و ازابن عباس صاحب روایت است . (تاج العروس ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span>).<br /></font></div>'),
(176846, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (... البزار) تابعی است و از ابی هریرة روایت دارد. (تاج العروس ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span>).<br /></font></div>'),
(176847, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (... العکی ) تابعی است و از امیرالمؤمنین علی علیه السلام روایت کند. (تاج العروس ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span>).<br /></font></div>'),
(176848, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن بکتوت، ملقب به زین الدولة. از بخشندگان نامور عرب بشمار میرفت چنانکه گویند در روزگار تنگسالی و گرانی هر روز دوازده هزار تن در مهمانسرای وی پذیرائی میشدند. (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٢</span>).<br /></font></div>'),
(176849, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (اِخ ) ابن تمیم العنبری . شاعر بوده است . (منتهی الارب ). وی در یوم مبایض یکی از ایام مشهوره ٔ عرب با حمصیصة الشیبانی روبرو شد و با آنکه شجعان عرب در ایام عکاظ با قناع داخل میدان میشدند طریف در آن روز بدون قناع وارد میدان شده بود و چون طریف قاتل شراحیل یکی از بنی ذهل بن شیبان بود، طایفه ٔ بکربن وائل حمصیصه را خبر دادند که طریف به میدان آمده . حمصیصه گفت او را به من نشان دهید. طریف را به حمصیصه نشان دادند. وی به خونخواهی شراحیل با طریف مبارزه کرد و او رابکشت . رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٦</span> صص <span class=\"hlight\" dir=\"rtl\">٦٥</span> - <span class=\"hlight\" dir=\"rtl\">٦٧</span>، <span class=\"hlight\" dir=\"rtl\">٩٤</span> شود.<br /></font></div>'),
(176850, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن خلف بن محارب . ازطایفه ٔ قیس عیلان و از بطن عدنان و جد جاهلیان محسوب میگردد. دو قبیله ٔ ذهل و غنم از نسل وی میباشند و آنان را ابناء و مالک نیز مینامند و فرزندان طریف را بنام حصر نیز نام برده اند. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>).<br /></font></div>'),
(176851, 'طریف', '<span class=\"hlight\">طریف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن سلیمان، ابوعاتکه . تابعی است . رجوع به ابوعاتکه شود.<br /></font></div>'),
(176852, 'طریفان', '<span class=\"hlight\">طریفان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) نباتی است که در بهار روید و گل او مانند خسک بود و زرد و گرد بر گرد گل خارداشته باشد و به شیرازی انگویر و آن قرطم برّی بود و منفعت وی آن است که اگر طبیخ وی بر گزیدگی افعی ریزند درد ساکن کند و اگر بر عضو سلیم ریزند همان درجه زحمت پیدا کند که از گزندگی افعی بهم رسد. (اختیارات بدیعی ). طریفولیون است و گویند قرطم بری است . (تحفه ٔ حکیم مؤمن ). طریفولیون است و قرطم بری را نیز نامند و شیخ الرئیس در قانون گفته : نباتی است ربیعی، تخم آن شبیه به عصفر، طبیخ آن را چون بر نهش افاعی بریزند تسکین وجع آن دهد و چون بر عضو سلیم بریزند احداث وجعی مانند وجع نهش افعی کند. (فهرست مخزن الادویه ). و رجوع به طریفولیون و طریفایون و طریفیلون شود.<br /></font></div>'),
(176853, 'طریفایون', '<span class=\"hlight\">طریفایون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) و طریفیلون نیز گویند. جالینوس حکیم گوید: حکماء یونان او را به نامهای مختلف تعریف کرده اند و بوی او به بوی قفرالیهود مشابهت دارد و اگر کسی را افعی بگزد او را در آب بپزند و آن آب در موضع جراحت بریزند مضرت زهر افعی را دفع کند و اگر به عضوی تندرست ریخته شود همان عمل کند که زهر افعی کرد، فالحاصل در صحت عضو مضرت او چون زهر افعی است در حال مضرت زهر افعی تریاق است اززهر او. دیسقوریدس گوید نبات او مقدار یک گز بود، او را خنجهای باریک باشد و لون خنجها سیاه بود و به نبات اذخر مشابهت دارد و بر هر شاخی از او سه برگ باشد، چون از زمین بروید به مشام بوی شراب رسد و چون بزرگ شود بوی قفر به مشام رسد و شکوفه ٔ او بنفسجی باشدو تخم او به پهنی مایل باشد و پهن تمام نبود و بر یک طرف او زغبها بود به شبه خط، چنانکه بعضی از نباتها را باشد، چنانکه نبات خیار و مانند آن . (ترجمه ٔ صیدنه ٔ ابوریحان ). و رجوع به طریفیلون و طریفان شود.<br /></font></div>'),
(176854, 'طریفة', '<span class=\"hlight\">طریفة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (ع ص ) گیاه نصی که سپید یا انبوه و تمام گوالیده کرده باشد. (منتهی الارب ) (آنندراج ). نبات چون سپید شود. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> طریفه ناک . رجوع به همین کلمه شود.<br /></font></div>'),
(176855, 'طریفة', '<span class=\"hlight\">طریفة.</span> <font color=\"DarkGreen\"><b>[ طُ رَ ف َ ]</font></b> (اِخ ) نام مردی . (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢</span>).<br /></font></div>'),
(176856, 'طریفة', '<span class=\"hlight\">طریفة.</span> <font color=\"DarkGreen\"><b>[ طُ رَ ف َ ]</font></b> (اِخ ) ابن حاجز. صحابی است . (منتهی الارب ). و رجوع به الاصابة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٥</span> شود.<br /></font></div>'),
(176857, 'طریفة', '<span class=\"hlight\">طریفة.</span> <font color=\"DarkGreen\"><b>[ طُ رَ ف َ ]</font></b> (اِخ ) آبکی است در اسفل ارمام . (منتهی الارب ). آبی است مر بنی جذیمةبن مالک بن نصربن قعین بن الحارث بن ثعلبةبن دودان بن اسد را در اسفل ارمام . و درمحلی دیگر نیز طریفة آبی است مر بنی شاکربن نضله را که از قبیله ٔ بنی اسد می باشند و هم طریفة قریه و آب ونخلستانی است مر احمال را که به بنوحمل معروفند از طایفه ٔ بنی حنظله و نصر گفته است که طریفة صحرای بی آب و علفی است که پس از دو یا سه روز به پایان ارمام میرسند و در آنجا به آبی گوارا برمیخورند که به بنی جذیمه تعلق دارد و برخی گفته اند آب مزبور بنی خالدبن نضلةبن حجوان بن فقعس راست . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٨</span>).<br /></font></div>'),
(176858, 'طریفة', '<span class=\"hlight\">طریفة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (اِخ ) نام زنی کاهنه به روزگار جاهلیت که خرابی سد مأرب را پیشگوئی کرده بود. (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">١٥٠</span>). و رجوع به تاج العروس ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١١١</span> شود.<br /></font></div>'),
(176859, 'طریفل', '<span class=\"hlight\">طریفل .</span> <font color=\"DarkGreen\"><b>[ طِ ف ِ ]</font></b> (معرب، اِ) مخفف اطریفل است . رجوع به اطریفل و طرافل شود.<br /></font></div>'),
(176860, 'طریفلا', '<span class=\"hlight\">طریفلا.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (معرب، اِ) طرسطوج . طرذیلون . سیسالیوس است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(176861, 'طریفلة', '<span class=\"hlight\">طریفلة.</span> <font color=\"DarkGreen\"><b>[ طِ ف ُ ل َ ]</font></b> (معرب، اِ) به یونانی حندقوقی است . (فهرست مخزن الادویه ). رجوع به طریبله شود.<br /></font></div>'),
(176862, 'طریفلن', '<span class=\"hlight\">طریفلن .</span> <font color=\"DarkGreen\"><b>[ طِ ف ُ ل ُ ]</font></b> (معرب، اِ) اسم یونانی و بمعنی ذوثلاثة اوراق است و مشترک است در حندقوقا و نبات خصیةالثعلب و به عربی مراد از او حومانه است و آن نباتی است قریب به ذرعی و شاخهای او باریک و سیاه و شبیه به اذخر و برگش مثل برگ حندقوقا و در هر شعبه سه عدد و گلش بنفش و رایحه ٔ او شبیه به عصفر و بیخش دراز و صلب و تخمش مایل به پهنی و با زغب و مستعمل از او تخم و برگ است . در سیم گرم و خشک و مُدِرّ بول و حیض و مقوی معده و جگر و مفتح و با سکنجبین جهت سموم هوام و سپرز و با آب سرد جهت عسر بول وصرع و ابتداء استسقاء و درد رحم، و بیخ او از ادویه ٔ کبار تریاقیه است، و شربتش دو درهم و مضر گرده و مصلحش کتیرا است . و گویند سه عدد برگ و سه عدد تخم اوجهت تب مثلثه و چهار عدد از هر یک جهت ربع بالخاصیةمؤثر است . و نطول طبیخ او رافع الم گزیدن هوام و مقرح جلد و مصلحش لعاب بزرقطونا است . (تحفه ٔ حکیم مؤمن ). معنی آن به یونانی ذوثلاثة اوراق بود و این اسم مشترک است بر حندقوقی و آن گفته شد و بر نبات خصی الثعلب و آن نیز گفته شد و دیگر بر دوائی که مخصوص است به این اسم و آن حومانه است و به یونانی نام بسیار دارد. بعضی وی را سواس خوانند و بعضی اسقلیطس و بعضی فیقن و بعضی اکسون فیلن و آن نباتی است که درازی قد وی یک گز بود یا بیشتر و قضبان وی باریک بود و سیاه مانند اذخر، در ابتدا بوی سداب کند و در آخر بوی قفر و گل وی جرجیری بود و طبیعت وی گرم و خشک بود در سیم، مانند قفرالیهود و تخم وی و ورق وی چون به آب بیاشامند نافع بود به شوصیه و عسرالبول و صرع و ابتداء استسقاء و درد رحم و حیض و براند بول را و باید که ازتخم وی سه درم و از ورق حبها بخورند و ورق چون با سکنجبین بیاشامند نافع بود جهت گزندگی جانوران و بعضی گویند طبیخ نبات وی چون با بیخ وی بود و بر موضع گزندگی جانوران نهند، درد ساکن گردد و بعضی مردمان در تب مثلثه سه ورق و سه حب از وی با شراب بیاشامند زایل کند و بیخ وی از ادویه های معاجین بود. (اختیارات بدیعی ). دوایی است که آن را اندقوقو گویند و حندقوقو همان است و آن اسپست باشد و به عربی ذوثلاثة الوان و ذوثلاثة اوراق خوانند و معنی آن هم به یونانی ذوثلاثة اوراق است و گیاه خصی الثعلب را نیز گویند. (برهان ) (آنندراج ). شبدر. حندقوقا. خصی الثعلب . حومانة . نام مشترکی است ولی هرگاه بطور مطلق آن را بکار برند مراد جرمانه باشد و آن مانند حندقوقا دارای سه برگ است .در سوم گرم و خشک است، درد اضلاع و سدد را بهبود بخشد و مدر بود، خستگی و عسر بول و سپرز را سودمند باشدو سه برگ آن با سه دانه تب مثلث را شفا بخشد و چهارعدد از هر یک برای ربع مفید است و مقرح است و مصلح آن لعابهاست . (از تذکره ٔ داود ضریر انطاکی ص <span class=\"hlight\" dir=\"rtl\">٢٣٨</span>).<br /></font></div>'),
(176863, 'طریفه', '<span class=\"hlight\">طریفه .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (اِخ ) ده کوچکی است از دهستان میربچه ٔ بخش رامهرمز شهرستان اهواز، در <span class=\"hlight\" dir=\"rtl\">٧</span>هزارگزی شمال باختری رامهرمز کنار راه شوسه ٔ رامهرمز به هفتگل با <span class=\"hlight\" dir=\"rtl\">٣٥</span> تن سکنه . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(176864, 'طریفه ناک', '<span class=\"hlight\">طریفه ناک .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (ص مرکب ) زمین طریفه ناک ؛ زمین که در آن نصی بسیار روید. ارض مطروفة.<br /></font></div>'),
(176865, 'طریفوقون', '<span class=\"hlight\">طریفوقون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) رجوع به طروفوقون شود.<br /></font></div>'),
(176866, 'طریفولیون', '<span class=\"hlight\">طریفولیون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) در تحفه ٔ حکیم مؤمن و متن عربی ابن البیطار طریقولیون است، ولی لکلرک آن را بصورت تریفولیون تصحیح کرده است . ابن البیطار آرد: برخی آن را «تربد» پنداشته اند ولی طریفولیون بجز تربد است . دیسقوریدوس در چهارم گوید: گیاهی است که در سواحل دریا در نقاطی میروید که هرگاه آب طغیان کند آن را فروپوشد. اما گیاه مزبور نه در درون آب و نه در خشکی دور از ساحل هیچکدام پرورش نمی یابد. برگ آن شبیه به برگ گیاهی است که آن را اساطیس گویند و آن گیاه نیل است لیکن از برگ نیل درشت تر است و آن راساقی است که طول آن قریب یک وجب است و قسمت بالای آن کنگره دار است . و برخی گفته اند که گل این گیاه در هرروز سه بار تغییر رنگ دهد چنانکه هنگام بامداد سپیدو موقع ظهر بنفش و شب هنگام سرخ تیره باشد. ریشه ٔ آن سپید و خوشبو است و هرگاه آن را بچشند زبان را گرم کند. آشامیدن دو درهم از شربت آن مسهل و مدر است و گاه آن را مانند دیگر پازهرها برای دفع سموم بکار برند. جالینوس این گیاه را در مفردات خود یاد نکرده است . (از مفردات ابن البیطار). و حکیم مؤمن آرد: نباتی است بقدر شبری، برگش شبیه به برگ ثیل و از آن غلیظترو گلش در طرف صباح سفید و در نصف روز بنفش و در شب سرخ تیره میباشد، و بیخش خوشبو و سفید و به طعم زنجبیل، در اول و سیم گرم، و در آخر آن خشک و قاطع اخلاط بارده، و مقوی معده و جگر و مدر بول و مسهل اخلاط لزجه و بجهت خفقان و رفع سموم نافع و شربتش تا دو درهم و مضر سفل و مصلحش کتیرا است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(176867, 'طریفون', '<span class=\"hlight\">طریفون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) فوةالضبع. (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> شفنین . (تذکره ٔ انطاکی ). به این معنی مفرد طریقون است . رجوع به طریقون شود.<br /></font></div>'),
(176868, 'طریفیلون', '<span class=\"hlight\">طریفیلون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) رجوع به طریفایون و طریفان شود.<br /></font></div>'),
(176869, 'طریق', '<span class=\"hlight\">طریق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) راه . ج، اَطْرُق، طُرُق، طُرْق، اَطْرِقاء، اَطْرِقَة. جج، طُرُقات . (منتهی الارب ) (آنندراج ). سبیل . صراط. رَوِش . وجه . نحو. مبقرة. بوری . بوریّة. باری . باریة. باریاء. بوریاء. صاحب غیاث اللغات و آنندراج آرند: طریق مأخوذ است از طرق بمعنی کوفتن، چون پای روندگان راه را میکوبد، لهذا راه را طریق گفتند - انتهی . و با لفظ سپردن و گرفتن مستعمل است <span class=\"hlight\">:</span> <br />فلک چون بیابان دمد چون مسافر<br />منازل منازل، مجره طریق .<br /> <font color=\"Red\">منوچهری .</font><br />نه خیره گردد چشم من از شب تاری <br />نه سست گردد پای من از طریق دراز.<br /> <font color=\"Red\">مسعودسعد.</font><br />علاجی در وهم راه نیابد که موجب صحت اصلی تواند بود و بدان از یک علت مثلاً ایمنی کلی حاصل تواند آمد، چنانکه طریق مراجعت آن بسته ماند. (کلیله و دمنه ). بدو <font color=\"DarkGreen\"><b>[ به مرجع ]</font></b> باید پیوست ... آنگاه ... انابت مفید نباشد، نه راه بازگشتن مهیا... و نه طریق توبت آسان . (کلیله و دمنه ). می بینم که کارهای زمانه میل به ادبار دارد... و افعال ستوده و اقوال پسندیده مدروس گشته ... و راه راست بسته و طریق ضلالت گشاده . (کلیله و دمنه ).<br />گردباد از من طریق بادپیمائی گرفت <br />وحشت ازمجنون ما آهوی صحرائی گرفت .<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br />بسپرده طریق پیشوائی <br />شایان چو پدر به مقتدائی .<br /> <font color=\"Red\">درویش واله هروی (از آنندراج ).</font><br />و رجوع به شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span> شود. <BR><font color=\"Blue\">◄</font> مسلک . مذهب . روش دینی <span class=\"hlight\">:</span> <br />زین کور و کر لشکر بیزاری <br />گر بر طریق حیدر کراری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />هرکه بوی داروی من یابد از تو بی گمان <br />گویدت تو بر طریق ناصر دین خسروی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />وآن کو نه بر این طریق باشد<br />او کافر و رافضی است بی دین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گر ندانی که این مثل بر کیست <br />بروی بر طریق ملعون پیل .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چند پرسی بر طریق کیستی <br />بر طریق وملت پیغمبرم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />پس به طریق تو خدای جهان <br />بیشک در ماش و جو و لوبیاست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چنین گفتند رو بشناس خود را<br />طریق کفر و دین و نیک و بد را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />طریق برهمنان دیده ای که چون باشد<br />زنان و مردان خوش روزگار از آتش و آب .<br /> <font color=\"Red\">مسعودسعد.</font><br />صوفی ابن الوقت باشد ای رفیق <br />نیست فردا گفتن از شرط طریق .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> روش . شیوه . رسم . طرز. اسلوب . نمط. هنجار. وجه . نحوه <span class=\"hlight\">:</span><br />می گیر و عطا بخش و نکو گوی و نکو خواه <br />این است کریمی و طریق ادب این است .<br /> <font color=\"Red\">منوچهری .</font><br />آنچه مثال وی نگاه داشتند و آنچه بر طریق استبداد رفتند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٠٢</span>). تا سنت پیغمبر بجای آورده باشیم و طریقی که پدران ما بر آن رفته اند نگاه داشته آید.(تاریخ بیهقی چ ادیب ). ملاقات کن نبشته را به آن طریقی که تعظیم کنی آن را. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣١٤</span>). و روبرو میشود با واقعه ای به آن طریق که رضا به قضا میدهد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٠٨</span>).<br />چنین طریق ز شاهان که را بود که تراست <br />به حلم و عفو درنگ و به جنگ و جود شتاب .<br /> <font color=\"Red\">مسعودسعد.</font><br />تازه در خسروی به حل و به عقد<br />صد طریق ستوده بنهادی .<br /> <font color=\"Red\">مسعودسعد.</font><br />طریق دست آمدن چه باشد؟ (کلیله و دمنه ). و فرضیت مجاهدت هم از روی شرع و هم از طریق خرد ثابت گشت . (کلیله و دمنه ). یکی از ایشان قاضیی که در امضای احکام شرع از طریق دیانت و قضیت امانت نگذرد. (کلیله و دمنه ). و نوبت جهانداری هم از وجه ارث و هم از طریق اکتساب بدو رسانده . (کلیله و دمنه ). به چه طریق قدم در این مهم خواهی نهاد؟ (کلیله و دمنه ). طریق آن است که به حیلت در پی کار او ایستیم . (کلیله و دمنه ). لکن هرچه بدین فضایل متحلی باشد، اگر در همه ابواب رضای او جسته آید، ... از طریق کرم و خرد دور نیفتد. (کلیله و دمنه ). چه اگر از این طریق عدول افتد، هر روز مکروهی یابد. (کلیله و دمنه ). بعضی به طریق ارث دست در شاخی ضعیف زده . (کلیله و دمنه ). چندانکه بدو <font color=\"DarkGreen\"><b>[ گاو ]</font></b>رسیدم، سخن به طریق اکفاء میگفتم . (کلیله و دمنه ). و احداث متعلمان به طریق تحصیل علم و موعظت نگرند. (کلیله و دمنه ). طریق آن است که این مرهم هم از ایشان طلبی و این عذر هم از درگاه ایشان خواهی . (ترجمه ٔ تاریخ یمینی خطی ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span>). طریق آن است که از این مقام برخیزی و به جانب دیگر تحویل کنی . (ترجمه ٔ تاریخ یمینی خطی ص <span class=\"hlight\" dir=\"rtl\">٤١</span>). اگر چنانک اتفاقاً ظفر و نصرت که مرا افتاده ترا افتادی و من در دست تو اسیر گشتمی با من چه طریق خواستی سپردن . (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی کتابخانه ٔ مؤلف ص <span class=\"hlight\" dir=\"rtl\">١٧٤</span>). گفتا طریق چیست ؟ گفتم برای نزهت ناظران و فسحت حاضران، کتاب گلستانی بشاید تصنیف کردن . (سعدی ).<br />غضبی کز طریق دانش خاست <br />عقل و دین عذر آن تواند خواست .<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> حال . حالت . <BR><font color=\"Blue\">◄</font> عادت . خو. دأب . <BR><font color=\"Blue\">◄</font> پیشه . کار. حرفه <span class=\"hlight\">:</span> <br />انجم گردون شمردن کی طریق اعور است .<br /> <font color=\"Red\">امیر علیشیر نوائی .</font><br /> <BR><font color=\"Blue\">◄</font> خجل . (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> دراصطلاح رمل، شکلی از اشکال شانزده گانه ٔ رمل است . (غیاث اللغات ). و نزد اهل رمل شکلی است که در آن فقط نقطه هاست بدینسان : <br /> <span class=\"hlight\">.... (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> در نزد فقیهان بر دو گونه است : طریق عام و آن را نافذ هم نامند و طریق خاص که آن را نیز بهمین نام و هم بنام طریق غیرنافذ خوانند. و ذیل لفظ سکه در این باره گفتگو شد. <BR><font color=\"Blue\">◄</font> در نزد اهل قرائت قسمی از احوال اسناد است . رجوع به اسناد شود. <BR><font color=\"Blue\">◄</font> در نزد شاعران، مرادف طرز و سبک است . رجوع به طرز شود. (از کشاف اصطلاحات الفنون ) _(:</span> <span class=\"hlight\" dir=\"rtl\">k٠٥l</span>)_<br />بر آن طریق بنا کردم این قصیده که گفت <br />سخن که نظم دهند آن درست باید و راست . <br /> <font color=\"Red\">مسعودسعد.</font><br />هست طریق غریب اینکه من آورده ام <br />اهل سخن را سزد گفته ٔ من پیشوا.<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> در نزد متکلمان و دانشمندان علم اصول، طریق وسیله ای است که با نظر صحیح در آن بتوان به مطلوب رسید، اگر مطلوب تصور باشد طریق آن را معرف گویندو اگر تصدیق باشد طریق آن را دلیل خوانند. علت اینکه «امکان رسیدن » در تعریف قید شده بدان سبب است که با عدم توصل یا رسیدن طریق تحقق نمی پذیرد و بهمین سبب فقط امکان توصل در نظر گرفته شده است . و قید «نظر صحیح » در تعریف از این رو است که نظر فاسد مطلوب را ایجاب نمیکند و ممکن نیست بوسیله ٔ آن به مطلوب رسید زیرا در ماهیت آن وسیله ای برای رسیدن به مطلوب نیست وتعریف مزبور در لفظ «دلیل » نیز توضیح داده شد. (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> در نزد اهل حقیقت «تصوف » عبارت از مراسم خدای تعالی و احکام تکلیفی مشروعی است که در آنها رخصت راه نیابد زیرا جستجوی رخصت ها سبب پدید آمدن طبیعتی میشود که مقتضی وقفه و فترت در طریق است . در جرجانی چنین است . (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> ج ِ طریقة. (منتهی الارب ) (اقرب الموارد). و رجوع به طریقت و طریقة شود.<br /></font></div>'),
(176870, 'طریق', '<span class=\"hlight\">طریق .</span> <font color=\"DarkGreen\"><b>[ طُ رَ ]</font></b> (ع اِ) نخله ای است حجازی . (منتهی الارب ). نخلة حجازیة. (اقرب الموارد). اُطیرق مثله . (منتهی الارب ). نوعی نخل حجاز.<br /></font></div>'),
(176871, 'طریق', '<span class=\"hlight\">طریق .</span> <font color=\"DarkGreen\"><b>[ طِرْ ری ]</font></b> (ع ص ) نیک خاموش . <BR><font color=\"Blue\">◄</font> (اِ) کروان نر که چوبینه باشد. (منتهی الارب ).به عربی کروان نر را نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(176872, 'طریق الزنبجیار', '<span class=\"hlight\">طریق الزنبجیار.</span> <font color=\"DarkGreen\"><b>[ طَ قُزْ زَم ْ ب َج ْ ]</font></b> (اِخ ) یکی از جاده های عمومی مسافرتی بین اشبیلیه و قرطبه است . (الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(176873, 'طریق العنصل', '<span class=\"hlight\">طریق العنصل .</span> <font color=\"DarkGreen\"><b>[ طَ قُل ْ ع ُ ص ُ ]</font></b> (اِخ ) راهی است بین بصره و یمامه . (منتهی الارب ).<br /></font></div>'),
(176874, 'طریق المنکدر', '<span class=\"hlight\">طریق المنکدر.</span> <font color=\"DarkGreen\"><b>[ طَ قُل ْ م ُ ک َ دِ ]</font></b> (اِخ ) راهی است از یمامه سوی مکه . (منتهی الارب ).<br /></font></div>'),
(176875, 'طریق الوادی', '<span class=\"hlight\">طریق الوادی .</span> <font color=\"DarkGreen\"><b>[ طَ قُل ْ ]</font></b> (اِخ ) جاده ای است بین اشبیلیه و قرطبه . (الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(176876, 'طریق خراسان', '<span class=\"hlight\">طریق خراسان .</span> <font color=\"DarkGreen\"><b>[ طَ ق ِ خ ُ ]</font></b> (اِخ ) ولایتی معتبر است (از عراق عرب ) و شهرش قصبه ٔ بعقوبا و آن را دختری از تخم کسری قوبانام ساخت و بیعت (بیعة) قوبا خواند، به مرور زمان بعقوبا شد. بر کنار آب نهروان است وجویی از آن در میان شهر میگذرد و تمامت دیه ها بر آن نهر زراعت میکنند، باغستان و نخلستان بسیار دارد، نارنج و ترنج بیشمار میباشد، چنانچه سیصد و چهارصد نارنج به یک درهم میدهند. هوای آن مانند بغداد است، اما بسبب بسیاری نخلستان به عفونت مایل است و شهرهای باجسران و شهر ابان که دختری ابان نام از تخم کسری ساخت و اعمال طابق و مهرود از توابع آن عمل است و آن اعمال هشتاد پاره دیه است، حقوق دیوانی آن شانزده تومان و چهار هزار دینار در دفتر مثبت است . (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٤٢</span>). و رجوع به فهرست تجارب الامم ج <span class=\"hlight\" dir=\"rtl\">٢</span> شود.<br /></font></div>'),
(176877, 'طریق طریق', '<span class=\"hlight\">طریق طریق .</span> <font color=\"DarkGreen\"><b>[ طِرْ ری طِرْ ری ]</font></b> (ع صوت مرکب ) بجای طرقواکه فعل امر است استعمال کنند. رجوع به طرقوا شود.<br /></font></div>'),
(176878, 'طریق گشته', '<span class=\"hlight\">طریق گشته .</span> <font color=\"DarkGreen\"><b>[ طَ گ َ ت َ <span class=\"hlight\" dir=\"rtl\">/</span>ت ِ ]</font></b> (ن مف مرکب ) یعنی شرمنده شده . مؤلف گوید که طریق در اصل بمعنی کوفته و مضروب است، خاطر آدم خجل و شرمنده نیز کوفته میباشد. (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(176879, 'طریقان', '<span class=\"hlight\">طریقان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) گیاهی است . مستوفی گوید:گلش مانند معصفر است، پخته بر افعی گزیده نهند، درد ساکن کند و زهر برآورد. نزهةالقلوب خطی در تحت عنوان «الادویة» گوید قرطم بری است . رجوع به طریفان شود.<br /></font></div>'),
(176880, 'طریقت', '<span class=\"hlight\">طریقت .</span> <font color=\"DarkGreen\"><b>[ طَ ق َ ]</font></b> (ع اِ) طریقة. روش . وتیره . <BR><font color=\"Blue\">◄</font> مسلک . مذهب . سیرت <span class=\"hlight\">:</span> دزد گفت : میخواهم ... آداب طریقت آموزم . (کلیله و دمنه ). اقوال پسندیده مدروس گشته ... و ضایع گردانیدن احکام خِرد طریقتی مشروع . (کلیله و دمنه ).<br />سری دگر به کف آور که در طریقت عشق <br />سزاست این سر سگسار سنگساری را.<br /> <font color=\"Red\">خاقانی .</font><br />هرکه با بدان نشیند، اگر نیز طبیعت ایشان در او اثر نکند به طریقت ایشان متهم گردد. (گلستان سعدی ). <BR><font color=\"Blue\">◄</font> در اصطلاح سالکان، تزکیه ٔ باطن و شریعت تزکیه ٔ ظاهر است . (غیاث اللغات ) (آنندراج ). دومین منزل از منازل سه گانه ٔ ارباب سلوک که عبارت است از: شریعت، طریقت، حقیقت . مسلک صوفیه . صاحب کشاف آرد: در اصطلاح صوفیان، طریقی است که رساننده ٔ کسان بسوی خدای تعالی است چنانکه شریعت راهی است که انسان را به بهشت میرساند و طریقت اخص از شریعت است زیرا طریقت هم مشتمل بر احکام شریعت است از قبیل اعمال صالح بدنی و اجتناب از محرمات و مکروهات عمومی و هم مشتمل بر احکام خاصی است مانند اعمال قلبی و اجتناب از همه ٔ ماسوی اﷲ. این است آنچه در شرح قصیده ٔ فارضیه آمده است و حاصل کلام این است که طریقت سیرتی است مختص به سالکان و رهروان بسوی خدای تعالی هم مشتمل بر اعمال و ریاضتها و عقاید مخصوص به آنهاست و هم بر احکام شریعت مشتمل است و بنابرین طریقت از شریعت اخص است زیرا بر هر دو مشتمل گردد. این است آنچه در اصطلاحات صوفیه آمده است . و در لطائف اللغات گوید: طریقت در اصطلاح صوفیه عبارت است از سیرت مصطفوی که مختص است به سالکان الی اﷲ و باللّه و فی اﷲ از قطع منازل وترقی در مقامات و در مجمع السلوک گوید: شریعت نگاه داشتن معاملات است و طریقت تزکیه ٔ باطن است از خصال ذمیمه و کدورات بشریه . بدان که مجموعه ٔ آدمی سه چیز است : نفس و دل و روح . پس شریعت راه نفس است و طریقت راه دل و حقیقت راه روح . و پاره ای دیگر گفته اند حقیقت عبارت از توحید است و شریعت پیروی احکام و شرایع کیش مسلمانی است، اما باید دانست که هرکه را حقیقت باشد پس از مرگ حقیقت او باقی است، ولی شریعت آنچنان نیست و قشیری در رساله ٔ خویش آورده که : شریعت الزام عبودیت و حقیقت مشاهده ٔ ربوبیت باشد و هر شریعتی که به توفیق و تأیید حقیقت توأم نبود غیرمقبول است و هرحقیقتی هم که غیرمؤید به شریعت باشد غیرمحصول خواهد بود زیرا حقیقت جز بوسیله ٔ شریعت حصول نپیوندد، ازاین رو شریعت و حقیقت لازم و ملزوم یک دیگر باشند، پس چون دانستی که : الشریعة اقوالی و الطریقة افعالی و الحقیقة احوالی باید که سالک از علم شریعت آنچه مالابدمنه است بیاموزد و از علم طریقت جمله بجای آرد تا به نور حقیقت رسد و هرکه میکند آنچه پیغمبر صلی اﷲ علیه و آله و سلم فرموده است وی از اهل شریعت است، و هرکه میکند آنچه او صلواةاﷲ علیه کرده است وی از اهل طریقت است، و هرکه بیند آنچه او علیه الصلوة والسلام دیده است وی از اهل حقیقت است . و للّه دَرﱡ من قال (شعر):<br />طریقت بی شریعت راست ناید<br />حقیقت بی طریقت کی گشاید<br />شریعت در نماز و روزه بودن <br />طریقت در جهاد اندر فزودن <br />حقیقت روی در دلدار کردن <br />نظر اندر جمال یار کردن .<BR><font color=\"HotPink\">♦ </font>انتهی ما فی مجمعالسلوک . (کشاف اصطلاحات الفنون ) <span class=\"hlight\">:</span> <br />مباش در پی آزار و هرچه خواهی کن <br />که در طریقت ماغیر از این گناهی نیست .<br /> <font color=\"Red\">حافظ.</font><br />در طریقت هرچه پیش سالک آید خیر اوست <br />در صراط مستقیم ای دل کسی گمراه نیست .<br /> <font color=\"Red\">حافظ.</font><br />تکیه بر تقوی و دانش در طریقت کافری است <br />راهرو گر صد هنر دارد توکل بایدش .<br /> <font color=\"Red\">حافظ.</font><br />ز مشکلات طریقت عنان متاب ای دل <br />که مرد راه نیندیشد از نشیب وفراز.<br /> <font color=\"Red\">حافظ.</font><br />نصیحتی کنمت یاد گیر و در عمل آر<br />که این حدیث ز پیر طریقتم یاد است .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">اهل طریقت، رهروان طریقت </span> ؛ صوفیان . فقراء اِلی اﷲ <span class=\"hlight\">:</span> <br />از کوی رهزنان طبیعت ببر قدم <br />وز خوی رهروان طریقت طلب وفا.<br /> <font color=\"Red\">خاقانی .</font><br />و رجوع به طریق و طریقة شود.<br /></font></div>'),
(176881, 'طریققن', '<span class=\"hlight\">طریققن .</span> <font color=\"DarkGreen\"><b>[ طَ ق ُ ق ُ ]</font></b> (معرب، اِ) ذوثلاث حبات . مسبیلس . زعرور. ارونیا. ذوثلاث نویات . رجوع به طریقوقن و طریقوقون و طروقوقون شود.<br /></font></div>'),
(176882, 'طریقلونس', '<span class=\"hlight\">طریقلونس .</span> <font color=\"DarkGreen\"><b>[ طَ ن ِ ]</font></b> (معرب، اِ) به یونانی ذوثلاثة نبات <font color=\"DarkGreen\"><b>[ ظ: اوراق ]</font></b> است که مراد زعرور است . (فهرست مخزن الادویه ). مصحف طریقوقن است . رجوع به طریقوقون شود.<br /></font></div>'),
(176883, 'طریقوقن', '<span class=\"hlight\">طریقوقن .</span> <font color=\"DarkGreen\"><b>[ طَ ق ُ ]</font></b> (معرب، اِ) طریققن . زعرور است . (فهرست مخزن الادویه ). رجوع به طروقوقون و ماده ٔ ذیل شود.<br /></font></div>'),
(176884, 'طریقوقون', '<span class=\"hlight\">طریقوقون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) زعرور است . (فهرست مخزن الادویه ). رجوع به طروقوقون و طریققن و طریقوقن شود.<br /></font></div>'),
(176885, 'طریقولیون', '<span class=\"hlight\">طریقولیون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) مصحف طریفولیون است که در تحفه و متن عربی مفردات ابن البیطار بدین صورت آمده است . رجوع به طریفولیون شود.<br /></font></div>'),
(176886, 'طریقون', '<span class=\"hlight\">طریقون .</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) شفنین است . (اختیارات بدیعی ). به یونانی خوذرومی است . (فهرست مخزن الادویه ). قمری . بوتیمار. مالک الحزین . غمخورک . یمام . رجوع به طریغون شود. مصحف آن طریفون است .<br /></font></div>'),
(176887, 'طریقون بالاسیا', '<span class=\"hlight\">طریقون بالاسیا.</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ مرکب ) شفنین بحری است . (فهرست مخزن الادویه ). مصحف «طریقون تالاسیا» (ماده ٔ ذیل ) است .<br /></font></div>'),
(176888, 'طریقون تالاسیا', '<span class=\"hlight\">طریقون تالاسیا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b>(معرب، اِ مرکب ) شفنین بحری . ابرق . یمامةالبحر .<br /></font></div>'),
(176889, 'طریقی', '<span class=\"hlight\">طریقی .</span> <font color=\"DarkGreen\"><b>[ طَ قی ی ]</font></b> (ع ص نسبی ) منسوب به طریق . سمعانی گوید: از استاد خویش ابوالقاسم اسماعیل بن محمدبن الفضل در اصبهان پرسیدم : از چه روی علی بن المنذر الطریقی را طریقی خوانده اند؟ گفت : کان ولد فی الطریق فنسب الیها. (سمعانی ).<br /></font></div>'),
(176890, 'طریل', '<span class=\"hlight\">طریل .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام موضعی است که در مجمل التواریخ والقصص بدینسان آمده است : و ابوبکر احمدبن صالح بن شیرزاد و از اهل طریل . در معجم البلدان و انساب سمعانی این کلمه دیده نشد. رجوع به مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٣٦٦</span> شود.<br /></font></div>'),
(176891, 'طریم', '<span class=\"hlight\">طریم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) خشم . یقال : طار طریمه ؛ یعنی خشم گرفت . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176892, 'طریم', '<span class=\"hlight\">طریم .</span> <font color=\"DarkGreen\"><b>[ طِرْ ی َ ]</font></b> (ع ص، اِ) انگبین . (منتهی الارب ) (آنندراج ).عسل . <BR><font color=\"Blue\">◄</font> ابر سطبر توبرتو. (منتهی الارب ) (آنندراج ). ابر ستبر. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> (ص ) رجل طریم ؛ مرد درازبالا. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176893, 'طریمة', '<span class=\"hlight\">طریمة.</span> <font color=\"DarkGreen\"><b>[ طَرْ ی َ م َ ]</font></b> (ع مص ) پلید شدن آب . <BR><font color=\"Blue\">◄</font> چغزلاوه برآمدن بر آب . <BR><font color=\"Blue\">◄</font> برگردیدن رنگ آب . <BR><font color=\"Blue\">◄</font> موافق شدن چیزی به چیزی . (منتهی الارب ) (اقرب الموارد).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(176894, 'طرین', '<span class=\"hlight\">طرین .</span> <font color=\"DarkGreen\"><b>[ طِرْ ی َ ]</font></b> (ع ص، اِ) گل تنک . (منتهی الارب ). طین رقیق . (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> لای تنک . <BR><font color=\"Blue\">◄</font> خشم . یقال : اَتی بالطرین و الغرین ؛ ای غضب . (منتهی الارب ).<br /></font></div>'),
(176895, 'طرینا', '<span class=\"hlight\">طرینا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به یونانی سرمق است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176896, 'طرینة', '<span class=\"hlight\">طرینة.</span> <font color=\"DarkGreen\"><b>[ طَرْ ی َ ن َ ]</font></b> (ع مص ) باهم آمیختن و اختلاط کردن شرابخواران از مستی . یقال : طرین الشرب . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(176897, 'طرینوس', '<span class=\"hlight\">طرینوس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (البیوس ...) یکی از قیاصره ٔ روم که مدت نوزده سال پادشاهی کرد و انطاکیه را از ایرانیان بازپس گرفت و جالینوس در سال دهم از پادشاهی او قدم به عرصه ٔ هستی نهاد. (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٢</span>، <span class=\"hlight\" dir=\"rtl\">٧٥</span>).<br /></font></div>'),
(176898, 'طزر', '<span class=\"hlight\">طزر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) راندن به لگد. (منتهی الارب ).<br /></font></div>'),
(176899, 'طزر', '<span class=\"hlight\">طزر.</span> <font color=\"DarkGreen\"><b>[ طَ زَ ]</font></b> (معرب، اِ) گیاهی است که در تابستان روید. معرب تزر. (منتهی الارب ) (آنندراج ). صاحب قاموس گفته : و البیت الصیفی، معرب تزر. در تاج العروس نیز با گفته ٔ فیروزآبادی موافق است . حتماً در نسخه ای که صاحب منتهی الارب در دست داشته تصحیفی روی داده و البیت الصیفی را النبت الصیفی نوشته اند و به همان نحو هم ترجمه شده است . یاقوت در معجم البلدان از لیث نقل کرده که طزر، خانه ٔ تابستانی را گویند و سپس از ابومنصور ازهری آورده که طزر معرب و اصل آن تزر است، و آن شهری است در مرج القلعة که از آنجا تا جاده ٔ عمومی خراسان یک مرحله (یک منزل ) مسافت است . این شهر در صحرائی پهناور واقع شده و در آن صحرا ایوانی رفیعالبناء میباشد که از آثار خسروجردبن شاهان است و در آن صحرا جز ایوان مذکور اثر و نشانه ٔ دیگری نیست و بر جانب یمین شهر مزبور ماسبدان و مهرجان قدق واقع است که نعمان بن مقرن در موقع پیکار با ایرانیان نخست بدانجا فرودآمد و سپس از آنجا به نهاوند رفت و با ایرانیان جنگید. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>). صاحب تاج العروس در ماده ٔ طزر گوید: و مما یستدرک علیه الطزر بیت ٌ الی الطول فارسی معرب، و قیل هو البیت الصیفی، قال الازهری : اراه معرباً و اصله تزر. چون یاقوت نیز در ذکر ماده ٔ طزر عین بیانات ابومنصور ازهری را ایراد کرده معلوم میشودنسخه ای را که صاحب تاج العروس در دست داشته در اصل ماده تحریفی شده و «طَزر» بصورت «طَرز» نوشته شده، وصاحب تاج العروس هم بدان صورت نقل کرده است و بعدهادر کتب لغت بجای طزر، طرز متداول شده و معنی آن نیزاز زمستانی به تابستانی تغییر یافته است . شگفتی در اینجاست که کلمه ٔ طزر در دیوان خاقانی صورت دیگری بخود گرفته و بشکل «طَرَر» درآمده است . خاقانی گوید:<br />باد غم جست درِ لهو و طرب بربندید<br />موج خون خاست در بهو و طرر بگشائید.<br />ونیز گوید:<br />هرچه دارم بنه و سکنه بسوزم ز پست <br />پیشتر سوختن از بهوو طرر درگیرم <br />در صورتی که این کلمه در دیوان بصورت «طَزَر» بوده و در آن تصحیف رخ داده است . اینک برای روشن شدن وضع و معنی این کلمه گوئیم که در زبان پارسی خانه ٔ زمستانی را تجر گویند و چون مطابق قواعد معموله جیم به «چ » و «ژ» و «ز» نیز تبدیل میشود، پس تجر وتژر و تزر هر سه به یک معنی و مستعمل خواهند بود و چون مطابق گفته ٔ یاقوت در مرج القلعه ایوانی از ابنیه ٔ سلاطین ایران باقی و گوید در قدیم آنجا شهری بوده بنام «تزر»، ناگزیر همینکه این کلمه داخل زبان عرب گردیده، تاء آن به طاء تبدیل و بصورت طزر استعمال شده است . مرحوم مشیرالدوله در جلد دوم ایران باستان در ذیل شرح قصر صدستون گوید: «تچر» قصر کوچک داریوش که در ضلع شمالی صحن (صحن قصر صدستون ) بپا شده، بنابر کتیبه های بالای دو جرز رواق به تچر موسوم است . لفظ تچر، تجر یا طزر پارسی جدید، اصلاً بمعنی قصر زمستانی است، فی الحقیقه در میان تمام ابنیه ٔ صفه تنها این بنا رو به جنوب میباشد و این کیفیت در چنین آب و هوائی پرمعنی است، سطح قصر مربع مستطیلی است که بطول قرار گرفته و کف آن قریب سه متر بالاتر از کف صحن است . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٨٩</span>). آقای پورداود در کتاب فرهنگ ایران باستان گوید: اما طزر را که یاقوت بنقل از لیث وابومنصور آن را معرب از تزر فارسی دانسته و بمعنی خانه ٔ تابستانی گرفته چنین تعریف کرده است : شهری است از ناحیه ٔ مرج القلعه و یک منزل از راه بزرگ خراسان مسافت دارد و در میان دشتی واقع است . قصر یزید را جغرافیانویسان طزر هم خوانده اند، یعنی یک شهر را بدو نام کرده اند و این طزر معرب از تزر بی شک همان لفظ فرس هخامنشی تچر (<span class=\"hlight\" dir=\"rtl\">Tacara</span>) میباشد که بمعنی کوشک (= قصر) است، در زبان ارمنی تچر بمعنی سرای و پرستشگاه، از زبان ایرانی گرفته شده است و همین لفظ است که در فارسی تجر شده . نزاری قهستانی گفته :<br />میان این تجر و گنبد فلک فرق است <br />که هست این به ثبات آن نباشد آرامش .<br />و در فرهنگهای فارسی چنین یاد شده : تجر خانه ٔ زمستانی را گویند که در آن تنور و بخاری باشد. (فرهنگ ایران باستان ص <span class=\"hlight\" dir=\"rtl\">٢٩٤</span>). و مؤید گفته ٔ آقای پورداود لفظ «بهو» است که در شعر خاقانی آمده، چه بهو بمعنی صفه (السامی فی الاسامی )، و صفه به فارسی خم (مهذب الاسماء)، و خم بمعنی خانه ٔ زمستانی است . (مجمعالفرس ). و رجوع به برهان قاطع شود.<br /></font></div>'),
(176900, 'طزر', '<span class=\"hlight\">طزر.</span> <font color=\"DarkGreen\"><b>[ طَ زَ ]</font></b> (اِخ ) شهری است در مرج القلعة که از آنجا تا جاده ٔ عمومی خراسان یک مرحله (منزل ) مسافت است . (از معجم البلدان ). و رجوع به معنی اسمی همین کلمه شود.<br /></font></div>'),
(176901, 'طزر', '<span class=\"hlight\">طزر.</span> <font color=\"DarkGreen\"><b>[ طَ زَ ]</font></b> (اِخ ) دهی است از دهستان کاه بخش داورزن شهرستان سبزوار در <span class=\"hlight\" dir=\"rtl\">٣٧</span>هزارگزی خاور داورزن و <span class=\"hlight\" dir=\"rtl\">٣</span>هزارگزی جنوب جاده ٔ شوسه ٔ عمومی . جلگه، معتدل با <span class=\"hlight\" dir=\"rtl\">٣٢٧</span> تن سکنه . آب آن از قنات و رودخانه و محصول آنجا غلات و پنبه و تریاک و شغل اهالی زراعت و راه آن اتومبیل رو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176902, 'طزرج', '<span class=\"hlight\">طزرج .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) دهی است از دهستان بلورد بخش مرکزی شهرستان سیرجان در<span class=\"hlight\" dir=\"rtl\">٥٠</span>هزارگزی خاور سعیدآباد و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی خاور راه مالرو بلورد - مشیز. کوهستانی و سردسیر با<span class=\"hlight\" dir=\"rtl\">٨٠</span> تن سکنه . آب آن از چشمه و محصول آنجا غلات و حبوبات و لبنیات و شغل اهالی زراعت و گله داری و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(176903, 'طزرج', '<span class=\"hlight\">طزرج .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) ده کوچکی است از دهستان جوزم و دهج بخش بابک شهرستان یزد در <span class=\"hlight\" dir=\"rtl\">٥٣</span>هزارگزی شمال شهر بابک، کنار راه مالرو طزرج به شهر بابک . کوهستانی، معتدل و مالاریایی با<span class=\"hlight\" dir=\"rtl\">٦٤</span> تن سکنه . آب آن از قنات، محصول آنجا غلات، و شغل اهالی زراعت است . صنایع دستی زنان قالی بافی است و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(176904, 'طزرجان', '<span class=\"hlight\">طزرجان .</span> <font color=\"DarkGreen\"><b>[ طَ زَ ]</font></b> (اِخ ) دهی است از دهستان میانکوه بخش مهریز شهرستان یزد در <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی باختر مهریز. کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">٢٦٧٦</span> تن سکنه . آب آن از قنات، چشمه و رودخانه ٔ محلی . محصول آنجا غلات و شغل اهالی زراعت و صنایع دستی نساجی و کرباس بافی است . راه فرعی و دبستان دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(176905, 'طزرق', '<span class=\"hlight\">طزرق .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) دهی است از دهستان زمج بخش ششتمد شهرستان سبزوار در <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی شمال باختری ششتمد، سر راه مالرو عمومی استاج . کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">٤٢٦</span> تن سکنه . آب آن از رودخانه و قنات و محصول آنجا غلات و پنبه و بادام و میوه . شغل اهالی زراعت و باغداری و کرباس و چادرشب بافی و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176906, 'طزره', '<span class=\"hlight\">طزره .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) دهی است از دهستان دامنکوه بخش حومه ٔ شهرستان دامغان در <span class=\"hlight\" dir=\"rtl\">٤٢</span>هزارگزی شمال خاوری دامغان و <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی شمال شوسه ٔ دامغان به شاهرود. کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٧٠٥</span> تن سکنه . آب آن از قنات و محصول آنجا غلات و حبوبات و لبنیات و مختصر میوه . شغل اهالی زراعت و گله داری است و عده ای برای تأمین معاش زمستان به مازندران میروند. صنایع دستی زنان کرباس بافی . از طریق مهماندوست و بق اتومبیل میتوان برد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(176907, 'طزرکش', '<span class=\"hlight\">طزرکش .</span> <font color=\"DarkGreen\"><b>[ طَ زَ ک َ ]</font></b> (اِخ ) دهی است جزء دهستان قاقازان بخش ضیأآباد شهرستان قزوین در <span class=\"hlight\" dir=\"rtl\">١٠٠٠٠</span>گزی شمال ضیأآباد و <span class=\"hlight\" dir=\"rtl\">١٠٠٠</span>گزی راه عمومی . کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">٤٦٦</span> تن سکنه . آب آن از چشمه و رودخانه ٔ محلی و محصول آنجا غلات و عدس و گاودانه و انگور و گردو وبادام و زردآلو و سیب . شغل اهالی زراعت و گلیم و جاجیم و جوراب بافی . راه آن ماشین رو است . از آثار قدیمی بقعه ٔ امام زاده ای بنام اسماعیل است که میگویند برادر امام رضا است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(176908, 'طزع', '<span class=\"hlight\">طزع .</span> <font color=\"DarkGreen\"><b>[ طَ زِ ]</font></b> (ع ص ) مرد بی غیرت . (منتهی الارب ) (آنندراج ). مرد بی رشک . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> حریص بی خیر. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> مرد مفلس و بی چیز. من لا غناء له . (اقرب الموارد).<br /></font></div>'),
(176909, 'طزع', '<span class=\"hlight\">طزع .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) آرامش کردن با زن . <BR><font color=\"Blue\">◄</font> پس ماندن و تقاعد ورزیدن لشکری از جنگ . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176910, 'طزع', '<span class=\"hlight\">طزع .</span> <font color=\"DarkGreen\"><b>[ طَ زَ ]</font></b> (ع مص ) لغةٌفی طَسَع. (منتهی الارب ). حریص گردیدن . آزمندی کردن . <BR><font color=\"Blue\">◄</font> شوخ چشم شدن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نکاح . (اللسان از ذیل اقرب الموارد).<br /></font></div>'),
(176911, 'طزعة', '<span class=\"hlight\">طزعة.</span> <font color=\"DarkGreen\"><b>[ طُ ع َ ]</font></b> (اِخ ) شهری است بکنار صقلیه برابر جزیره ٔ یابسة. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(176912, 'طزیان', '<span class=\"hlight\">طزیان .</span> <font color=\"DarkGreen\"><b>[ طُزْ ]</font></b> (اِخ ) از قرای دیاربکر است . (معجم البلدان ). و منسوب بدان طزیانی است .<br /></font></div>'),
(176913, 'طزیع', '<span class=\"hlight\">طزیع.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) بمعنی طَزِع است . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176914, 'طس', '<span class=\"hlight\">طس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) قاقله است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176915, 'طس', '<span class=\"hlight\">طس .</span> <font color=\"DarkGreen\"><b>[ طَس س ]</font></b> (معرب، اِ) تشت . (منتهی الارب ) (آنندراج ). طشت . طَسّة و طِسّة مثله . (منتهی الارب ) (آنندراج ). ج، طُسوس، طِساس، طَسیس، طَسّات . و رجوع به کتاب المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٢٢١</span> شود.<br /></font></div>'),
(176916, 'طس', '<span class=\"hlight\">طس .</span> <font color=\"DarkGreen\"><b>[ طَس س ]</font></b> (ع مص ) غالب آمدن کسی را در خصومت و ساکت و خاموش کردن او را. (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فروبردن کسی را در آب . غوطه دادن کسی را در آب . <BR><font color=\"Blue\">◄</font> رفتن . یقال : ماادری این طس هُوَ؛ نمیدانم کجا رفت او. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> طس َّ القوم الی المکان ؛ ابعدوا فی السیر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مجامعه ٔ با زن . (ذیل اقرب الموارد از تاج ).<br /></font></div>'),
(176917, 'طس', '<span class=\"hlight\">طس .</span> <font color=\"DarkGreen\"><b>[ طا سین ْ ]</font></b> (اِخ ) سورتی است از قرآن . جمع آن ذوات طس است نه طواسین . (منتهی الارب ). و طس آغاز سوره ٔ نمل را مفسرین گفته اند سوگند است یعنی سوگند به خدای لطیف و سمیع. (تفسیر ابوالفتوح ). سوگند به طول و سناء حق .<br /></font></div>'),
(176918, 'طسا', '<span class=\"hlight\">طسا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) طساء. رجوع به طساء شود.<br /></font></div>'),
(176919, 'طساء', '<span class=\"hlight\">طساء.</span> <font color=\"DarkGreen\"><b>[ طَ س َءْ ]</font></b> (ع مص ) ناگوارد شدن و دل گرفتن از روغن و چربش . <BR><font color=\"Blue\">◄</font> شرم داشتن . (منتهی الارب ) (آنندراج ). یقال : طَسَاءَ فلان ؛ اذا استحیی . (منتهی الارب ).<br /></font></div>'),
(176920, 'طسات', '<span class=\"hlight\">طسات .</span> <font color=\"DarkGreen\"><b>[ طَس ْ سا ]</font></b> (ع اِ) ج ِ طَس ّ و طَسّة و طِسّة.<br /></font></div>'),
(176921, 'طساس', '<span class=\"hlight\">طساس .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ج ِ طَس ّ و طَسّة و طِسّة و طَسْت .<br /></font></div>'),
(176922, 'طساس', '<span class=\"hlight\">طساس .</span> <font color=\"DarkGreen\"><b>[ طَس ْ سا ]</font></b> (ع ص ) تشتگر. (منتهی الارب ) (آنندراج ). سازنده ٔ تشت . رجوع به طس شود.<br /></font></div>'),
(176923, 'طساس', '<span class=\"hlight\">طساس .</span> <font color=\"DarkGreen\"><b>[ طَس ْ سا ]</font></b> (اِخ ) نسبتی است که به ابوالفضل بن زیاد البغدادی داده اند از آن جهت که تشتگر بود و معروف گردید به طساس بغدادی . (سمعانی ).<br /></font></div>'),
(176924, 'طساسة', '<span class=\"hlight\">طساسة.</span> <font color=\"DarkGreen\"><b>[ طِ س َ ]</font></b> (ع اِمص ) تشتگری . (منتهی الارب ) (آنندراج ). طشت سازی . رجوع به طس شود.<br /></font></div>'),
(176925, 'طساسیج', '<span class=\"hlight\">طساسیج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طسوج .<br /></font></div>'),
(176926, 'طسالیا', '<span class=\"hlight\">طسالیا.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) منطقه ای است از مناطق یونان . رجوع به تسالی شود.<br /></font></div>'),
(176927, 'طسام', '<span class=\"hlight\">طسام .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) کثیر. بسیار. یقال : رأیته فی طسام الغبار؛ ای فی کثیره . طَسام و طَسّام مثله . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176928, 'طسام', '<span class=\"hlight\">طسام .</span> <font color=\"DarkGreen\"><b>[ طَس ْ سا ]</font></b> (ع ص، اِ) کثیر. بسیار. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176929, 'طسام', '<span class=\"hlight\">طسام .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) کثیر. بسیار. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176930, 'طسان', '<span class=\"hlight\">طسان .</span> <font color=\"DarkGreen\"><b>[ طَس ْ سا ]</font></b> (ع ص، اِ) گرد بالارفته . (منتهی الارب ).<br /></font></div>'),
(176931, 'طسبه', '<span class=\"hlight\">طسبه .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (ع اِ) قرع است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176932, 'طسة', '<span class=\"hlight\">طسة.</span> <font color=\"DarkGreen\"><b>[ طَس ْ س َ <span class=\"hlight\" dir=\"rtl\">/</span> طِس ْ س َ ]</font></b> (معرب، اِ) تشت . (منتهی الارب ) (آنندراج ). طَس ّ. طَسْت . طشت .<br /></font></div>'),
(176933, 'طست', '<span class=\"hlight\">طست .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی است از بخش بزمان شهرستان ایرانشهر در <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی جنوب بزمان و <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی باختر راه مالرو ایرانشهر به بزمان . کوهستانی و گرمسیر و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٧٥</span> تن سکنه . آب آن از چشمه و محصول آنجا غلات و خرما و لبنیات . شغل اهالی زراعت و گله داری و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(176934, 'طست', '<span class=\"hlight\">طست .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) تشت . و هو طَس ّ، ابدل احدی السینین تاء للاستثقال، فاذا جمعت او صغرت، ردت السین لانک فصلت بینهما بواو او الف او یاء، فقلت طسوس و طساس فی الجمع و طسیس فی التصغیر. (منتهی الارب ) (آنندراج ). طشت ؛ سیطل . طست . فارسی معرب . (جمهره ٔ ابن درید از سیوطی در المزهر). و اصل آن تشت است <span class=\"hlight\">:</span> <br />نگه کن سحرگاه بر طست سیمین <br />به زر اندرون دُرّشهوار دارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و رجوع به کتاب المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٨٦</span>، <span class=\"hlight\" dir=\"rtl\">١٩٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٢١</span> شود.<br /></font></div>'),
(176935, 'طستی', '<span class=\"hlight\">طستی .</span> <font color=\"DarkGreen\"><b>[ طَ تی ی ]</font></b> (ع ص نسبی ) منسوب به طست و کسانی را بدین نسبت خوانند که به شغل تشت سازی یا تشتگری معروف بوده اند. (سمعانی ).<br /></font></div>'),
(176936, 'طسرمالیا', '<span class=\"hlight\">طسرمالیا.</span> <font color=\"DarkGreen\"><b>[ طَ س َ]</font></b> (معرب، اِ) اسم یتوع است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176937, 'طسع', '<span class=\"hlight\">طسع.</span> <font color=\"DarkGreen\"><b>[ طَ س ِ ]</font></b> (ع ص ) مرد شوخ چشم . <BR><font color=\"Blue\">◄</font> بی غیرت . <BR><font color=\"Blue\">◄</font> حریص بی خیر. طسیع مثله فی الکل . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176938, 'طسع', '<span class=\"hlight\">طسع.</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (ع مص ) شوخ چشم شدن . <BR><font color=\"Blue\">◄</font> بی غیرت گردیدن بر زنان . <BR><font color=\"Blue\">◄</font> آزمند شدن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176939, 'طسع', '<span class=\"hlight\">طسع.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) آرامش کردن با زن . <BR><font color=\"Blue\">◄</font> رفتن درشهرها. (منتهی الارب ) (آنندراج ). رجوع به طزع شود.<br /></font></div>'),
(176940, 'طسفونج', '<span class=\"hlight\">طسفونج .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (اِخ ) دهی است بزرگ در شرقی دجله مقابل نعمانیه، بین بغداد و واسط. آثار دیرینه و ویرانی در آن ده میباشد. حمزه گوید: اصل این کلمه طوسفون بوده و در تعریب به طیسفون و طیسفونج درآمده است، معهذا عامه ٔ مردم آن را بدون یاء و طسفونج تلفظ میکنند و گروهی این محل را یکی از مدائن اَکاسره میشمارند. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(176941, 'طسق', '<span class=\"hlight\">طسق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) بغادده (بغدادیان ) بغلط بکسر خوانند. (منتهی الارب ). پیمانه ای است . <BR><font color=\"Blue\">◄</font> مقداری از خراج که به حساب سر جریب بر زمین و زراعت و جز آن گیرند. (منتهی الارب ) (آنندراج ). و منه قول عمر حیث کتب الی عامل له فی رجلین اسلما: ارفع الجزیة من رؤسهما و خذ الطسق من ارضهما. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> یا مانند ضریبه است که در جزیه گرفته شود. لغت معرب یا مولد است . (منتهی الارب ) (آنندراج ). معرب تشک، فارسی است و معنی آن وظیفه ای است که بر اصناف و زروع نهند بر هر جریبی و آن را به فارسی تشک گویند، یعنی اجرت . (مفاتیح خوارزمی ص <span class=\"hlight\" dir=\"rtl\">٣٩</span>). وظیفه ای از خراج مقرر بر زمین . ج، طسوق . خراج که به اقسام کشت و زرع نهادندی بهر جریب . لیث گوید: معرب از فارسی است (از تسکی ) بمعنی خراج از اراضی . شاید از لفظ تسک که بمعنی صدقه و زکوة و سهم و بخش اندک آمده باشد، چنانکه در تداول عامه، باجی تسکم ده، باجی تسکی بده، شنیده شده است .<br /></font></div>'),
(176942, 'طسق آسیا', '<span class=\"hlight\">طسق آسیا.</span> <font color=\"DarkGreen\"><b>[ طِ ق ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) وجه معینی که آسیابان به سرکارشاه ایران رساند و این از جمله ٔ باجهای آنجاست . شفیع اثر در هجو نجفقلیخان صدر ایران گوید <span class=\"hlight\">:</span> <br />نارسته تخم کشت هنوز از زمین وقف <br />بر زارعان حواله کند طسق آسیا.<br /> <font color=\"Red\">(از آنندراج ).</font><br />رجوع به طسق شود.<br /></font></div>'),
(176943, 'طسل', '<span class=\"hlight\">طسل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) آب روان بر روی زمین . <BR><font color=\"Blue\">◄</font> (مص ) درخشیدن سراب در صحرا. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) درخش سراب . (منتهی الارب ).<br /></font></div>'),
(176944, 'طسم', '<span class=\"hlight\">طسم .</span> <font color=\"DarkGreen\"><b>[ طا سین ْ میم ْ ]</font></b>(اِخ ) در مفتتح سوره های الشعراء و القصص از حروف مقطعه ٔ اوایل پاره ای از سوره های قرآن است، و مفسران رادر معنی آن اختلافات بسیار است . ابوالفتوح رازی در تفسیر خویش آورده که والبی گوید: نامی است از نامهای خدا. عکرمه گفته که علما از تفسیر آن اظهار عجز کرده اند. مجاهد گفته : نام سوره است . ابوروق گفته : نامی است از نامهای قرآن . محمدبن کعب گفته : طاء طول و سین سناء و میم ملک خدای است . امیرالمؤمنین علی بن ابیطالب علیه السلام فرمود: طاء طور سینا و سین اسکندریه و میم مکه است . امام جعفر صادق علیه السلام گفته : طاء درخت طوبی و سین درخت سدرةالمنتهی و میم اشاره به محمدمصطفی صلی اﷲ علیه و آله و سلم است که بدین نامها خدای تعالی سوگند یاد فرموده است . (ابوالفتوح رازی ).<br /></font></div>'),
(176945, 'طسم', '<span class=\"hlight\">طسم .</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (ع مص ) ناگوار گردیدن . <BR><font color=\"Blue\">◄</font> نفخ کردن شکم . <BR><font color=\"Blue\">◄</font> (اِ) تیرگی و تاریکی اول شب . <BR><font color=\"Blue\">◄</font> تاریکی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176946, 'طسم', '<span class=\"hlight\">طسم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) مثل الطمس . (زوزنی ). ناپدید گردیدن . طسوم . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176947, 'طسم', '<span class=\"hlight\">طسم .</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) قبیله ای است از عاد و آن از اولاد طسم بن لاوی بن سام بن نوح علیه السلام بود. (منتهی الارب ) (آنندراج ). قومی از عرب بائده و ایشان بنوطسم بن لاوذبن ارم بن سام بن نوح علیه السلام اند و جوهری گوید: از عاد باشند و منزلشان احقاف یمن بود. و صاحب عبر گوید: دیارآنان یمامه است و در جنگهائی که میان آنان با جدیس درگرفت نسلشان برافتاد. حصن مشقر واقع بین نجران و بحرین بقولی از بناهای طسم است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>). و رجوع به البیان و التبیین جاحظ صص <span class=\"hlight\" dir=\"rtl\">١٦٤</span> - <span class=\"hlight\" dir=\"rtl\">١٦٦</span> و عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٢</span> و مجمل التواریخ و القصص صص <span class=\"hlight\" dir=\"rtl\">١٤٧</span>- <span class=\"hlight\" dir=\"rtl\">١٤٨</span> و الاعلام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٨</span> و صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٤</span> شود.<br /></font></div>'),
(176948, 'طسوج', '<span class=\"hlight\">طسوج .</span> <font color=\"DarkGreen\"><b>[ طَس ْ سو ]</font></b> (معرب، اِ) مأخوذ از تسوی فارسی . معرب است . کرانه . <BR><font color=\"Blue\">◄</font> ناحیه . <BR><font color=\"Blue\">◄</font> چهاریک دانگ که دو حبه باشد. ج، طساسیج .(منتهی الارب ) (آنندراج ). تسو، یعنی چهار جو. (دهار). سه ثمن مثقال . (مفاتیح خوارزمی ). تسوی . (زمخشری ). مقدار دو جو میانه . ربع دانگ . بیست وچهاریک مثقال . و در رساله ٔ اوزان نوشته که طسوج بیست وچهارم حصه ٔ هر چیز را گویند. (غیاث اللغات ). درهم . درم، و هو فارسی معرب و وزن آن شش دانگ است و دانگ دو قیراط باشد و قیراط دو طسوج و طسوج دو جو میانه ... (منتهی الارب ):<br />تو بگوئی نک دل آوردم به تو<br />گویدت این دل نیرزد یک تسو.<br /> <font color=\"Red\">مولوی .</font><br />و رجوع به تسو و استان و الجماهر ص <span class=\"hlight\" dir=\"rtl\">٤٩</span> و فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٢</span> و کتاب المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٧٦</span> شود.<br /></font></div>'),
(176949, 'طسوج', '<span class=\"hlight\">طسوج .</span> <font color=\"DarkGreen\"><b>[ طَس ْ سو ]</font></b> (اِخ ) مرکز بلوک انزاب مرند.<br /></font></div>'),
(176950, 'طسوج', '<span class=\"hlight\">طسوج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی از دهستان چرام بخش کهکیلویه ٔ شهرستان بهبهان در <span class=\"hlight\" dir=\"rtl\">٣٣</span>هزارگزی جنوب خاوری چرام مرکز دهستان در <span class=\"hlight\" dir=\"rtl\">٣٤</span>هزارگزی شمال خاوری شوسه ٔ آرو به بهبهان . کوهستانی و سردسیر و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٩٠</span> تن سکنه . آب آن از چشمه و محصول آنجا غلات و حبوبات و لبنیات و میوه و عسل . شغل اهالی زراعت و حشم داری است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(176951, 'طسوج', '<span class=\"hlight\">طسوج .</span> <font color=\"DarkGreen\"><b>[ طَس ْ سو ]</font></b> (اِخ ) در ساحل شمالی دریاچه ٔ ارومیه قصبه ای است بر دو مرحله ٔ تبریز بجانب غربی و درشمالی بحیره ٔ چیچست افتاده است، باغستان بسیار داردو میوه هاش بسیار و نیکو بود، هواش از تبریز گرمتر است و بجهت قرب بحیره ٔ چیچست به عفونت مائل و آبش از رودی که از آن جبال آید و از عیون، سکانش از ترک و تاجیک ممزوجند، حقوق دیوانیش کمابیش پنجهزار دینار به دفتر درآمده است و به وقف ابواب البر ابوسعیدی تعلق دارد. (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٨٠</span>). آب مرورود از کوه سهند برمیخیزد و بر ولایت مراغه گذشته به دره ٔ کاودوان با آب جغتو ضم شده، به دریای شور طسوج میریزد. طولش هشت فرسنگ باشد. (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٢٢٣</span>). آب تغتو از کوههای کردستان بحدود کریوه ٔ سینا برمیخیزد و به آب جغتو جمع می شود و به دریای شور طسوج میریزد. طولش پانزده فرسنگ باشد. (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٢٢٤</span>).<br /></font></div>'),
(176952, 'طسوج', '<span class=\"hlight\">طسوج .</span> <font color=\"DarkGreen\"><b>[ طَس ْ سو ]</font></b> (اِخ ) از بلوکات ناحیه ٔ دشتی، در جنوب شرقی دهدشت، طول <span class=\"hlight\" dir=\"rtl\">٥٤</span> و عرض <span class=\"hlight\" dir=\"rtl\">١٥</span> کیلومتر، حد شمالی فراشبند، حد جنوبی سناوشنبد، حد شرقی محال چهارگانه، حد غربی بلوک، هوای آن گرم و اراضی آن بی آب و بیحاصل . مرکز و ناحیه ٔ آن تنگ باغ . (جغرافیای سیاسی کیهان صص <span class=\"hlight\" dir=\"rtl\">٨٠</span> - <span class=\"hlight\" dir=\"rtl\">٨١</span>). میانه ٔ شمال و شرق کاکی است، درازی آن از سیرگاه تا قریه ٔ درتک یازده فرسنگ و پهنای آن از نیم فرسنگ نگذرد. کشت کار این ناحیه دیمی است . با آنکه هوائی گرم دارد و رودخانه از آن میگذرد، هیچ درختی جز کُنار (در آنجا) یافت نشود و در کناره ٔ رودخانه ٔ آن دراج فراوان باشد. محدود است از جانب مغرب و جنوب به ناحیه ٔ ستارشنبه و قصبه ٔ ناحیه ٔ طسوج تنگ باغ است . دوازده فرسنگ در جانب مشرق کاکی است و این ناحیه مشتمل است بر یازده قریه ٔ آباد. (فارسنامه ٔ ناصری ).<br /></font></div>'),
(176953, 'طسوس', '<span class=\"hlight\">طسوس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طَس ّ، بمعنی تشت .<br /></font></div>'),
(176954, 'طسوشی', '<span class=\"hlight\">طسوشی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) عنوان پادشاهان ایشان <font color=\"DarkGreen\"><b>[ ملوک چین ]</font></b> به میزان جاه و جلال و بزرگی شهرهای زیر فرمان پادشاه وابستگی دارد، از این رو پادشاهی را که بر شهر کوچکی فرمانروا باشد طسوشی مینامند و معنی طسوشی این است که در شهر اقامت گزید. (از اخبار الصین و الهند ص <span class=\"hlight\" dir=\"rtl\">١٧</span>).<br /></font></div>'),
(176955, 'طسوق', '<span class=\"hlight\">طسوق .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طَسق . رجوع به طسق شود.<br /></font></div>'),
(176956, 'طسوم', '<span class=\"hlight\">طسوم .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) ناپدید گردیدن : طسم الشی ٔ طُسوماً. کذا فی طسم الطریق . لغةٌ فی طمس، علی القلب . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> طسمته ؛ ناپدید کردم او را. (منتهی الارب ).<br /></font></div>'),
(176957, 'طسومالو', '<span class=\"hlight\">طسومالو.</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (معرب، اِ) اسم یتوع است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176958, 'طسومالون', '<span class=\"hlight\">طسومالون .</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (معرب، اِ) اسم یتوع است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176959, 'طسومالیومالس', '<span class=\"hlight\">طسومالیومالس .</span> <font color=\"DarkGreen\"><b>[ طَ ل ِس ْ ]</font></b> (معرب، اِ) اسم یتوع است . (فهرست مخزن الادویه ). ظاهراً سه کلمه ٔ مزبور مصحف یکدیگرند و در متون دیگر نظیر آنها مشاهده نشد.<br /></font></div>'),
(176960, 'طسک', '<span class=\"hlight\">طسک .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) طسق است وزناً و معنی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176961, 'طسی', '<span class=\"hlight\">طسی ٔ.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) مرد دل گرفته . مرد تخمه زده از روغن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176962, 'طسیس', '<span class=\"hlight\">طسیس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طَس ّ. رجوع به طس شود.<br /></font></div>'),
(176963, 'طسیع', '<span class=\"hlight\">طسیع.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) مرد شوخ چشم بی غیرت . <BR><font color=\"Blue\">◄</font> مرد حریص بی خیر. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176964, 'طسیم', '<span class=\"hlight\">طسیم .</span> <font color=\"DarkGreen\"><b>[ طُ س َ ]</font></b> (اِخ ) فی المثل : اورده میاه َ طسیم ؛ در حق کسی گویند که در گمراهی و ضلالت باشد و به صواب چیزی نرسد. (منتهی الارب ).<br /></font></div>'),
(176965, 'طسیمان', '<span class=\"hlight\">طسیمان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) شبرم است . (فهرست مخزن الادویه ).<br /></font></div>'),
(176966, 'طش', '<span class=\"hlight\">طش .</span> <font color=\"DarkGreen\"><b>[ طِش ش ]</font></b> (ع ص، اِ) در لهجه ٔ عامیانه ٔ عرب گویند: فلان طِش ٌّ؛ وقتی که یک کودک پس از همه ٔ فرزندان دیگر شخص متولد شده باشد. <BR><font color=\"Blue\">◄</font> یا طش را بر کودکی اطلاق کنند که هنگام بازی آخرین نوبت با او باشد. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(176967, 'طش', '<span class=\"hlight\">طش .</span> <font color=\"DarkGreen\"><b>[ طَش ش ]</font></b> (ع مص ) باران ریزه باریدن ابر. یقال : طَشَّت السماء طشاً و طشیشاً. (منتهی الارب ) (آنندراج ). باران نرم باریدن . (تاج المصادر بیهقی ). اندک باریدن . (مصادر زوزنی ). <BR><font color=\"Blue\">◄</font> طُشّه زده شدن . یقال : طُش َّ الرجل ُ (بصیغه ٔ مجهول ). <BR><font color=\"Blue\">◄</font> طُشَّت الارض ُ (بصیغه ٔ مجهول )؛ باران ضعیف رسید زمین را. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) دیگ بزرگی است که از آن بانگی برخیزدمانند بانگی که آن را قشیش گویند. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(176968, 'طش', '<span class=\"hlight\">طش .</span> <font color=\"DarkGreen\"><b>[ طَش ش ]</font></b> (ع اِ) باران ریزه ٔ زائد از رذاذ. طشیش . (منتهی الارب ) (آنندراج ). باران خرد. باران ضعیف . (دهار).<br /></font></div>'),
(176969, 'طشاش', '<span class=\"hlight\">طشاش .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) بیماریی است مانند زکام . طشة مثله . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176970, 'طشاش', '<span class=\"hlight\">طشاش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) چکیده های اشک و آب و جز آن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176971, 'طشانة', '<span class=\"hlight\">طشانة.</span> <font color=\"DarkGreen\"><b>[ طَش ْ شا ن َ ]</font></b> (اِخ ) یکی از بلاد اندلس که از اقلیم بحیرة بشمار میرود. (الحلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>).<br /></font></div>'),
(176972, 'طشت', '<span class=\"hlight\">طشت .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) لغتی است در طست . (اقرب الموارد). ابوعبیده گوید: فارسی است . ثعالبی گفته که فارسی و معرب است، معرب تشت معروف . (غیاث اللغات ) (آنندراج ). لگن . (دهار). لقن . (دهار). مُعرب است . لگن . (اقرب الموارد). ابوالایس . ابوکامل . (المرصع). ابومالک . (المرصع) (السامی فی الاسامی ): رَهْرَه ْ؛ طشت فراخ که قریب القعر بُوَد. سَیْطَل ؛ طشت خُرد. مِخْضَب ؛ طشت شمع. (دهار) <span class=\"hlight\">:</span> <br />پرستنده را دل پراندیشه گشت <br />بدان تا دگرباره بنهاد طشت .<br /> <font color=\"Red\">فردوسی .</font><br />پرستنده ای را بفرمود شاه <br />که طشت آور و آب برکش ز چاه .<br /> <font color=\"Red\">فردوسی .</font><br />یکی طشت زرین بیاورد پیش <br />نگفت این سخن با پرستار خویش .<br /> <font color=\"Red\">فردوسی .</font><br />دو کودک بدیدند مرده به طشت <br />ز ایوان به کیوان فغان برگذشت .<br /> <font color=\"Red\">فردوسی .</font><br />یکی طشت بنهاد زرین برش <br />به خنجر جدا کرد از تن سرش .<br /> <font color=\"Red\">فردوسی .</font><br />چنان بُد که دینار بر سر به طشت <br />اگر پیرمردی ببردی به دشت <br />نکردی به دینار او کس نگاه <br />ز نیک اختر روزو از داد شاه .<br /> <font color=\"Red\">فردوسی .</font><br />کنیزک ببرد آب و دستار و طشت <br />ز دیدار مهمان همی خیره گشت .<br /> <font color=\"Red\">فردوسی .</font><br />چو دیده نعمت بیند به کف درم نبود<br />سر بریده بود در میان زرین طشت .<br /> <font color=\"Red\">فرخی .</font><br />مرا آن طشت زرین نیست درخور<br />که دشمن خون من ریزد بدو در.<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br />ز عدل تست که نرگس به تیره شب در دشت <br />نهاده بر سر پیوسته طشت زر دارد.<br /> <font color=\"Red\">مسعودسعد.</font><br />اول مجلس که باغ شمع گل اندرفروخت <br />نرگس با طشت زر کرد به مجلس شتاب .<br /> <font color=\"Red\">خاقانی .</font><br />چون طشت بیسرند و چو در جنبش آمدند<br />الا شناعتی و دریده دهن نیند.<br /> <font color=\"Red\">خاقانی .</font><br />چو پرخون شد آن طشت زنگی چه کرد<br />بخوردش چو آبی و آبی بخورد.<br /> <font color=\"Red\">نظامی .</font><br />بجز خون شاهان در این طشت نیست <br />بجز خاک خوبان در این دشت نیست .<br /> <font color=\"Red\">؟ (از تاریخ گیلان مرعشی ).</font><br />یک چراغی هست در دل وقت گشت <br />وقت خشم و حرص اندر زیر طشت .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طشت آتش بر سر ریخته شدن </span> ؛ کنایه از تحت تأثیر واقع شدن هنگام مشاهده ٔ امری ناگوار، یا شنیدن خبری بر خلاف توقع و انتظار است که در آن حال گویند: از مشاهده ٔ فلان چیز یا از شنیدن فلان خبر، گوئی طشتی آتش به سر من ریختند <span class=\"hlight\">:</span> چون بر آن واقف گشتم، گوئی طشتی بر سر من ریختند از آتش . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٣٠</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طشت آتش به سر داشتن </span> ؛ عذر خواستن، چه در زمان قدیم هر کس که از او جرمی صادر میشد، طشت پُرآتش به سر گرفته می ایستاد، و این علامت عجز و انکسار است . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طشت کسی از بام افتادن </span> ؛ رازوی فاش شدن . رسوا شدن . فاش شدن راز کسی . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br />طبل پنهان چه زنم طشت من از بام افتاد.<br /> <font color=\"Red\">؟ (از امثال و حکم ).</font><br />مرا به عشق تو طشت ای پسر ز بام افتاد<br />چه راز ماند طشتی بدین خوش آوازی .<br /> <font color=\"Red\">سوزنی (ازامثال و حکم ).</font><br />و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٢</span> شود.<br /></font></div>'),
(176973, 'طشت', '<span class=\"hlight\">طشت .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) آبهای دریاچه ٔ بختگان فارس بواسطه ٔ دو تنگه ٔ پیچاپیچ به دریاچه ٔ دیگری موسوم به نرگس یا طشت متصل میشود. (جغرافیای طبیعی کیهان ص <span class=\"hlight\" dir=\"rtl\">٩٠</span>).<br /></font></div>'),
(176974, 'طشت زر', '<span class=\"hlight\">طشت زر.</span> <font color=\"DarkGreen\"><b>[ طَ ت ِ زَ ]</font></b> (ترکیب اضافی، اِ مرکب ) معروف است که طشت طلا و لگن طلا باشد. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از آفتاب عالمتاب هم هست . (برهان ) (رشیدی ) (آنندراج ) (انجمن آرای ناصری ). <BR><font color=\"Blue\">◄</font> جام طلا را نیز گویند. (برهان ) (آنندراج ).<br /></font></div>'),
(176975, 'طشت نگون', '<span class=\"hlight\">طشت نگون .</span> <font color=\"DarkGreen\"><b>[ طَ ت ِ ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از آسمان است . (برهان ) (آنندراج ) (انجمن آرای ناصری ).<br /></font></div>'),
(176976, 'طشت و سبو', '<span class=\"hlight\">طشت و سبو.</span> <font color=\"DarkGreen\"><b>[ طَ ت ُ س َ ]</font></b> (ترکیب عطفی، اِ مرکب ) پنگان . گری . گریال .<br /></font></div>'),
(176977, 'طشت و طبق', '<span class=\"hlight\">طشت و طبق .</span> <font color=\"DarkGreen\"><b>[ طَ ت ُ طَ ب َ ]</font></b> (ترکیب عطفی، اِ مرکب ) از اتباع : طشت و طبقی نچیده ایم .<br /></font></div>'),
(176978, 'طشت و طبق چیدن', '<span class=\"hlight\">طشت و طبق چیدن .</span> <font color=\"DarkGreen\"><b>[ طَ ت ُ طَ ب َ دَ ]</font></b> (مص مرکب ) از فعلهای اتباعی است . تهیه و تدارک دیدن .<br /></font></div>'),
(176979, 'طشتانیة', '<span class=\"hlight\">طشتانیة.</span> <font color=\"DarkGreen\"><b>[ طَ نی ی َ ]</font></b> (معرب، اِ) (از ریشه ٔ لاتین تستینیا که از تستا مشتق است ) طشطانة. کلاه خود. مغفر. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(176980, 'طشتجان', '<span class=\"hlight\">طشتجان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی از دهستان جوخواه بخش طبس شهرستان فردوس در <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی شمال باختری طبس سر راه مالرو عمومی طبس به یزد. جلگه و گرمسیر با <span class=\"hlight\" dir=\"rtl\">١٨٤</span> تن سکنه .آب آن از قنات و محصول آنجا غلات و خرما و پنبه و ارزن و زردک و شلغم و تنباکو. شغل اهالی زراعت و راه آن اتومبیل رو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(176981, 'طشتخاناه', '<span class=\"hlight\">طشتخاناه .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ مرکب ) (از: طشت + خانه ) جایگاهی که در آن پارچه های معینی را برای پوشش و لباس سلطان نگهداری میکنند، یا در آن اشیاء مختلفی ازقبیل جواهر، مهرها، شمشیرها و دیگر اشیاء مانند اینها را حفظ میکنند. <BR><font color=\"Blue\">◄</font> رختشوی خانه . طشتخانه . تشتخانه . و رجوع به طشتخانه شود. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(176982, 'طشتخانه', '<span class=\"hlight\">طشتخانه .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) تشتخانه . طشتخاناه <span class=\"hlight\">:</span> <br />آنجاکه طشتخانه ٔ قدرت کنند باز<br />تن دردهد وطای ملایک به مفرشی .<br /> <font color=\"Red\">اثیر اخسیکتی .</font><br />و خوارزم درآن روزگار در عداد وظیفه ٔ طشتخانه بود. (جهانگشای جوینی ). و رجوع به تشتخانه و طشتخاناه شود.<br /></font></div>'),
(176983, 'طشتخوان', '<span class=\"hlight\">طشتخوان .</span> <font color=\"DarkGreen\"><b>[ طَ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (اِ مرکب ) تشتخوان . دیسق . (دهار). فاثور. (ربنجنی ): دیسق ؛ خوان نقره یا معرب طشتخوان است . (منتهی الارب ). سینی . مجموعه . رجوع به تشتخوان شود.<br /></font></div>'),
(176984, 'طشتدار', '<span class=\"hlight\">طشتدار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) لقب احمد معتمد. رجوع به تاریخ بیهقی چ فیاض ص <span class=\"hlight\" dir=\"rtl\">٧٢</span> شود.<br /></font></div>'),
(176985, 'طشتدار', '<span class=\"hlight\">طشتدار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (نف مرکب ) نگهبان و متصدی طشتخاناه یاطشتخانه . <BR><font color=\"Blue\">◄</font> مستخدم محافظ رخت کن یا جایگاه البسه . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>): انوشتکین، طشتدار ملکشاه بن الب ارسلان و شحنه ٔ خوارزم بود. رجوع به تشتدار شود.<br /></font></div>'),
(176986, 'طشتداری', '<span class=\"hlight\">طشتداری .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (حامص مرکب ) عمل و شغل طشتدار <span class=\"hlight\">:</span> نام انوشتکین بود و رسم طشتداری داشت . (جهانگشای جوینی ). و رجوع به تشتداری شود.<br /></font></div>'),
(176987, 'طشتداریة', '<span class=\"hlight\">طشتداریة.</span> <font color=\"DarkGreen\"><b>[ طَ ری ی َ ]</font></b> (معرب، ص نسبی، اِ مرکب ) بقول دزی جمعِ طشتدار یا منسوب به طشتدار است . رجوع به طشتدار شود.<br /></font></div>'),
(176988, 'طشتنة', '<span class=\"hlight\">طشتنة.</span> <font color=\"DarkGreen\"><b>[ طَ ت َن َ ]</font></b> (ع مص ) از کلمه ٔ اسپانیایی تستن بمعنی کباب کردن . (لغت ابن الجزار) (زادالمسافر): کامون مقلی یعنی مطشطن . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(176989, 'طشتون', '<span class=\"hlight\">طشتون .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (معرب، اِ) عمل طشتون در اسپانیایی بمعنی آماده کردن وسیله ٔ «تستن » یا کباب کردن است اما این کلمه دارای معانی دیگری نیز هست . ویکتور معتقد است که ترکیب پان تستن مرادف هجلدر است و بر نوعی نان شیرینی مورق اطلاق میشود، نوعی شیرینی سبک و نازک که بین دو قالب آهنی خانه خانه می پزند. و در نزد نونز تستن عبارت از نخود برشته است و هم بر نوعی سوپ اطلاق میشود که آن را با نان برشته و روغن تازه تهیه میکنند. (از دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(176990, 'طشتچه', '<span class=\"hlight\">طشتچه .</span> <font color=\"DarkGreen\"><b>[ طَ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ مصغر) تشت خرد. تشتک . لگنچه .<br /></font></div>'),
(176991, 'طشتک', '<span class=\"hlight\">طشتک .</span> <font color=\"DarkGreen\"><b>[ طَ ت َ ]</font></b> (اِ مصغر) آوندی که خبازان آرد در آن خمیر کنند. تشتک . تغارچه .<br /></font></div>'),
(176992, 'طشتگر', '<span class=\"hlight\">طشتگر.</span> <font color=\"DarkGreen\"><b>[ طَ گ َ ]</font></b> (ص مرکب ) شخصی را گویند که طشت میسازد. (برهان ) (آنندراج ): طَسّاس ؛ طشتگر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِخ ) نام سازنده و مطربی هم بوده است . (برهان ) (آنندراج ). سازنواز که در سابق بوده . (غیاث اللغات ). نام مطربی . خاقانی گوید <span class=\"hlight\">:</span> <br />آن راه که طشتگر نوا کرد<br />آن قول که کاسه گر ادا کرد.<br /> <font color=\"Red\">(از مجمعالفرس ).</font><br />و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span> شود.<br /></font></div>'),
(176993, 'طشطانة', '<span class=\"hlight\">طشطانة.</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (معرب، اِ) رجوع به طشتانیة شود. کلاه خود. مغفر. کلاه جنگیان از آهن .<br /></font></div>'),
(176994, 'طشور', '<span class=\"hlight\">طشور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) طیرانه است . (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویه ). و رجوع به طشیر شود.<br /></font></div>'),
(176995, 'طشک', '<span class=\"hlight\">طشک .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام دهی است از توابع آباده و دو فرسخ کمتر در مغربی آباده است . (فارسنامه ٔ ناصری ). دهی است از دهستان آباده طشک بخش نی ریز شهرستان فسا در <span class=\"hlight\" dir=\"rtl\">١٢٨</span>هزارگزی شمال باختری نیریز. جلگه و گرمسیر و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٢٩٦</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و پنبه و تریاک است . شغل اهالی زراعت و قالی بافی و راه آن فرعی است ولی در زمستان بعلت طغیان دریاچه ٔ بختگان عبور غیرمقدور است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(176996, 'طشکر', '<span class=\"hlight\">طشکر.</span> <font color=\"DarkGreen\"><b>[ طِ ک َ ]</font></b> (اِخ ) حصاری است بس استوار در شهرستان جیان از اعمال اندلس و بر زبر آن نتوان شدن مگر با نردبان . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>). حصنی به اسپانیا، نزدیک شهر بسطة.<br /></font></div>'),
(176997, 'طشیر', '<span class=\"hlight\">طشیر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) طیرانه است . (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویه ). و رجوع به طشور شود.<br /></font></div>'),
(176998, 'طشیش', '<span class=\"hlight\">طشیش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) طَش ّ. باران ریزه ٔ زائد از رذاذ. (منتهی الارب ). باران ضعیف . (مهذب الاسماء). باران ِ خرد. باران ریزه . (آنندراج ). <BR><font color=\"Blue\">◄</font> (مص ) باران ریزه باریدن ابر. یقال : طَشَّت السماءُ طشیشاً. <BR><font color=\"Blue\">◄</font> طُشةزده شدن . یقال : طُش َّ الرَّجل ُ (به صیغه ٔمجهول ). (منتهی الارب ) (آنندراج ). رجوع به طشة شود. <BR><font color=\"Blue\">◄</font> باران ضعیف رسیدن زمین را. یقال : «طُشت الارض » (به صیغه ٔ مجهول ). (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(176999, 'ططار', '<span class=\"hlight\">ططار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) معرب تتار. ططر. تتر. تاتار. رجوع به تاتار شود.<br /></font></div>'),
(177000, 'ططر', '<span class=\"hlight\">ططر.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (اِخ ) ططار. معرب تتر و تتار و تاتار. و رجوع به تاتار شود.<br /></font></div>'),
(177001, 'ططرا', '<span class=\"hlight\">ططرا.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (معرب، عدد، ص، اِ) مأخوذ از کلمه ٔ یونانی طِطارا بمعنی چهار.<br /></font></div>'),
(177002, 'ططراملس', '<span class=\"hlight\">ططراملس .</span> <font color=\"DarkGreen\"><b>[ طِ م ِ ل ِ]</font></b> (معرب، اِ) درخت بطم است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177003, 'ططرامیلس', '<span class=\"hlight\">ططرامیلس .</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ ]</font></b> (معرب، اِ) علک الانباط است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177004, 'ططرطین', '<span class=\"hlight\">ططرطین .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (معرب، اِ) وزنی معادل چهار نوات .<br /></font></div>'),
(177005, 'ططرقیرقوس', '<span class=\"hlight\">ططرقیرقوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) مرهم باسلیقون است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177006, 'ططرلبوس', '<span class=\"hlight\">ططرلبوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی فقاع الکرم است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177007, 'ططق', '<span class=\"hlight\">ططق .</span> <font color=\"DarkGreen\"><b>[ طُ طُ ]</font></b> (اِ) تتق . (حاشیه ٔ فرهنگ اسدی نخجوانی ). رجوع به تتق شود.<br /></font></div>'),
(177008, 'ططماج', '<span class=\"hlight\">ططماج .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِ) رشته ٔ گردبریده . رجوع به تتماج وحاشیه ٔ برهان قاطع چ معین ذیل کلمه ٔ «تتماج » شود.<br /></font></div>'),
(177009, 'ططوس', '<span class=\"hlight\">ططوس .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) پسر اسفیانوس ملک روم، تقریباً چهل سال پس از ارتفاع عیسی بن مریم، بیت المقدس (اورشلیم ) را گرفت، و سنگی بر سنگی باقی نگذاشت . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٤٧</span> و <span class=\"hlight\" dir=\"rtl\">٢٥٤٨</span>). و نیز رجوع به مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٤٣٧</span> شود. تیتوس امپراتور روم از سال <span class=\"hlight\" dir=\"rtl\">٧٩</span> تا <span class=\"hlight\" dir=\"rtl\">٨١</span> م . رجوع به تیتوس شود.<br /></font></div>'),
(177010, 'ططیگس', '<span class=\"hlight\">ططیگس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) زنجره . جیغاله . مطیلس .<br /></font></div>'),
(177011, 'طع', '<span class=\"hlight\">طع.</span> <font color=\"DarkGreen\"><b>[ طَع ع ]</font></b> (ع مص ) لیسیدن . (منتهی الارب ).<br /></font></div>'),
(177012, 'طعام', '<span class=\"hlight\">طعام .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b>(اِخ ) (دَرِ...) یکی از دروازه های شهر زرنج بوده است و محمدبن وصیف شاعر یعقوب بن لیث گوید <span class=\"hlight\">:</span> <br />دَرِ آکار تَن ِ او، سَر او باب طعام .<br />اصطخری گوید: شهر بزرگ سیستان را زرنج نامند و زرنج را شارستانی است و ربضی و شارستان را حصنی و خندقی است و ربض را نیز باروئی است . شارستان زرنج را پنج دروازه است، یکی دَرِ جدید، دیگر دَرِ عتیق که از آن دو دروازه بسوی فارس بیرون شوند و به یکدیگر نزدیکند، و دَرِ سوم دَرِ کرکویه است که از آن به خراسان بیرون شوند، چهارم دَرِ نیشک است که از آن به بست روند و دَرِ پنجم به دَرِ طعام معروف است که از آن به روستاها بروند و معمورترین این دروازه ها همانا دَرِ طعام است و این درها همه از آهن است . (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">١٥٨</span>). و نیز رجوع به فهرست تاریخ سیستان شود.<br /></font></div>'),
(177013, 'طعام', '<span class=\"hlight\">طعام .</span> <font color=\"DarkGreen\"><b>[ طَع ْ عا ]</font></b> (ع ص ) بسیار طعام دهنده .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177014, 'طعام', '<span class=\"hlight\">طعام .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) خوردنی . (منتهی الارب ) (ترجمان علامه ٔ جرجانی ص <span class=\"hlight\" dir=\"rtl\">٦٧</span>). مقابل شراب، آشامیدنی . خورش آدمی . (دهار). مطعوم . خورد. خوراک . خور. غذا. طعم . مأکل . اُکله . طعمة. هر چیز خوردنی . خلفه . (منتهی الارب ). سکر. حید. صمالخی . اکال . مائدة. لوس . عروض . علاس . ج، اطعمة. جج، اطعمات . (منتهی الارب ): طعام شبانگاه ؛ عشاء. (دهار). اندک از طعام ؛ جحفة. طعام خوش مزه ؛ ترفه . طعامی که بر آن کثرت خورندگان باشد؛ طعام مشفوه . طعام ماتم ؛وضیمة. طعام بابرکت ؛ نزل، نزیل . مقداری معلوم از طعام ؛ فتر. طعام خورده شده ؛ نهل . طعام سخت در خائیدن ؛ عالک، علک . طعام نرم ؛ غلول . طعام پیوسته و آماده ؛ معکود. (منتهی الارب ) <span class=\"hlight\">:</span> و طعام ایشان <font color=\"DarkGreen\"><b>[ مجفری ]</font></b>ماهی باشد و بدان زندگانی گذرانند. (حدود العالم ). و طعام ایشان <font color=\"DarkGreen\"><b>[ کیماکیان ]</font></b> به تابستان شیر است و به زمستان گوشت قدید. (حدود العالم ). نفس آرزو به وی است دوستی طعام و شراب و دیگر لذتها. (تاریخ بیهقی ).<br />شکری بگزار علم و دینش را<br />زآن به که شراب یا طعامش را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />رهی درازت پیش است و سهمگین که در او<br />طعام و آب نشاید مگر ز علم و عمل .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ببین که بهره ٔ آن پادشاه ز نعمت خویش <br />چو بهره ٔ تو ضعیف از طعام یک شکم است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بی زن نخورد طعام هرگز<br />از بس لطف و ز مهربانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و آن را که سبب بسیاری طعام و شراب باشد از آن باز باید داشت . (ذخیره ٔ خوارزمشاهی ). طعامی که معده از هضم و قبول آن امتناع کند... خلاص از رنج آن صورت نبندد مگر به قذف . (کلیله و دمنه ).<br />خوان ددان را به کاسه ٔ سر اعدا<br />ز آتش شمشیر تو طعام برآمد.<br /> <font color=\"Red\">خاقانی .</font><br />به روزی دو بارم بباید طعامی <br />به ماهی دو وقتم بباید جماعی .<br /> <font color=\"Red\">خاقانی .</font><br />باقی نه ماه بعد از طعام نهاری بیرون بارگاه بر کرسی نشستی و انواع اجناسی که در جهان موجود بودی ... (جهانگشای جوینی ).<br />چون به مقام خویش آمد، سفره خواست تا تناول کند، پسری صاحب فراست داشت گفت ای پدر باری به مجلس سلطان در طعام نخوری . (سعدی ).<br />اندرون از طعام خالی دار<br />تا در او نور معرفت بینی <br />تهی از حکمتی بعلت آن <br />که پُری از طعام تا بینی .<br /> <font color=\"Red\">سعدی .</font><br />با آنکه ازوجود طعام است حظ نفس <br />رنج آورد طعام که بیش از قدر بود.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> گندم . (منتهی الارب ) <span class=\"hlight\">:</span> و طعام الذین اوتوا الکتاب حل لکم و طعامکم حل لهم (قرآن <span class=\"hlight\" dir=\"rtl\">٥/٥</span>)؛ این طعام ... مراد حبوب است و لفظ طعام در کلام عرب بر گندم و جو غالب باشد. (تفسیر ابوالفتوح سوره ٔ مائده آیه ٔ <span class=\"hlight\" dir=\"rtl\">٥</span>). و بعضی تمام حبوب مأکول را طعام گویند و بعضی گندم را خاصةً، به دلیل حدیث ابی سعید: کنا نخرج صدقة الفطر فی عهد رسول اﷲ صلی اﷲ علیه و آله و سلم صاعاً من الطعام، او صاعاً من الشعیر. (منتهی الارب ) (آنندراج ). به عربی اسم مأکولاتی است که در آن غذائیت غالب باشد و نزد گرسنگی انسان بخورد، و بعضی نیز اطلاق بر گندم میکنند. (فهرست مخزن الادویه ). نامی است خاص گندم را. (مهذب الاسماء). غلات (در فقه ). صاحب کشاف اصطلاحات الفنون بنقل از بحرالرائق فی شرح کنزالدقائق آرد: در عرف سابق، گندم و آرد آن را طعام میگفتند و به همین سبب مصنف گفته است : کیل کردن در خریدن طعام بر گندم و آرد آن اطلاق شود. و در مصباح آمده است : طعام در نزد اهل حجاز بویژه بر گندم اطلاق گردد و در عرف به هر چیز خوردنی طعام و به هر چیزآشامیدنی شراب گویند. و منظور از گفتار مصنف «و یباع الطعام کیلاً و جزافاً» کلیه ٔ حبوب بجز گندم تنهاست و منظور از هر چیز خوردنی نیست به قرینه ٔ «کیلاً و جزافاً»... و بعضی از مشایخ گفته اند: طعام در عرف ما بر هرچه خوردن آن ممکن باشد اطلاق میشود یعنی آنچه عادةً برای خوردن است مانند گوشت پخته و کباب شده . و صدر شهید گفته است : بنابرین گندم و آرد و نان داخل این تعریف نیست . (از کشاف اصطلاحات الفنون ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">اول طعام آخر کلام </span> ؛ اصطلاحی است که شکمبارگان بر سبیل مزاح هنگام گسترده شدن سفره اگر کسی اراده ٔ سخن گفتن کند گویند. و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٥</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طعام الاثیم </span> ؛ قوله تعالی <span class=\"hlight\">:</span> ان شجرةالزقوم . طعام الاثیم ؛ درخت زقوم طعام آنکس کنیم که اثیم و بزهکار است . (قرآن <span class=\"hlight\" dir=\"rtl\">٤٣/٤٤</span> و <span class=\"hlight\" dir=\"rtl\">٤٤</span> از تفسیر ابوالفتوح رازی ). زقوم ؛ درختی است در دوزخ . قال ابن عباس لما نزل ان ّ شجرةالزقوم طعام الاثیم، قال ابوجهل : التمر بالزبدنترقمه، فانزل اﷲ تعالی : انها شجرة تخرج فی اصل الجحیم . طلعها کأنه رؤس الشیاطین . (قرآن <span class=\"hlight\" dir=\"rtl\">٣٧</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">٦٤</span> و <span class=\"hlight\" dir=\"rtl\">٦٥</span>). (منتهی الارب ). طعام دوزخیان . (منتهی الارب ).<br />هزار کاسه طعام الاثیم دادندش <br />هزار کاسه حمیم از پی طعام اثیم .<br /> <font color=\"Red\">سوزنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طعام بنا</span> ؛ میهمانی که پس از اتمام بنائی دهند. اِعذار. عِذار. عَذیر. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طعام ٌ حامزٌ</span> ؛ طعامی زبان گز. (مهذب الاسماء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طعام حشب ٌ</span> ؛ طعامی بی نان خورش . (مهذب الاسماء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طعام خِتان </span> ؛ عِذار. اِعذار. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طعام مأقوط</span> ؛ آنکه در آن قروت آمیخته باشند. (منتهی الارب ).<br /><BR><font color=\"Blue\">◄</font> آب . <BR><font color=\"Blue\">◄</font> آب زمزم . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177015, 'طعام خوردن', '<span class=\"hlight\">طعام خوردن .</span> <font color=\"DarkGreen\"><b>[ طَ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ دَ ]</font></b> (مص مرکب ) غذا خوردن . طعام خواری .<br /></font></div>'),
(177016, 'طعام دادن', '<span class=\"hlight\">طعام دادن .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b> (مص مرکب ) اطعام . (ترجمان القرآن ) (تاج المصادر بیهقی ).اقضاء. ارفاف . (تاج المصادر). مید. (منتهی الارب ).<br /></font></div>'),
(177017, 'طعان', '<span class=\"hlight\">طعان .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع مص ) نیزه زدن با یکدیگر. (منتهی الارب ) (زوزنی ). مطاعنه . (زوزنی ) <span class=\"hlight\">:</span> نه مرد شرابی که مرد ضرابی <br />نه مرد طعامی که مرد طعانی .<br /> <font color=\"Red\">منوچهری .</font><br />چو باد و خاک نجوئی مگر شتاب و درنگ <br />چو رمح و سیف ندانی مگر طعان و ضراب .<br /> <font color=\"Red\">مسعودسعد.</font><br />چه مرکبان را بر هم زند طرید و نبرد<br />چه سرکشان را در هم کند طعان و ضراب .<br /> <font color=\"Red\">مسعودسعد.</font><br />چرخ بدوزد چو تیر صبح بسوزد چو مهر<br />رمح تو گاه طعان تیغ تو گاه ضراب .<br /> <font color=\"Red\">خاقانی .</font><br />در علمش میر نحل، نیزه کشیده چونخل <br />غرقه ٔ صد نیزه خون اهل طعان و ضراب .<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> عیب کردن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> (ص، اِ)نیزه زنندگان، به این معنی جمع طاعن است . (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(177018, 'طعان', '<span class=\"hlight\">طعان .</span> <font color=\"DarkGreen\"><b>[ طَع ْ عا ]</font></b> (ع ص ) بسیار نیزه زننده . <BR><font color=\"Blue\">◄</font> بسیار طعن کننده و عیبجوی مردم را. (منتهی الارب ) (آنندراج ). و منه الحدیث : لایکون المؤمن طعاناً؛ ای فی اعراض الناس . (منتهی الارب ). بسیار طعنه زن . رجل ٌ طعان ٌ؛ آنکه مردمان را بد گوید. (مهذب الاسماء).<br /></font></div>'),
(177019, 'طعانة', '<span class=\"hlight\">طعانة.</span> <font color=\"DarkGreen\"><b>[ طَع ْ عا ن َ ]</font></b> (ع ص ) تأنیث طَعّان . رجوع به طَعّان شود.<br /></font></div>'),
(177020, 'طعب', '<span class=\"hlight\">طعب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) مزه . (منتهی الارب ) (آنندراج ). طعم . <BR><font color=\"Blue\">◄</font> بوی خوش . (منتهی الارب ) (آنندراج ). اریج . یقال : ما به من الطعب شی ٔ؛ ای من اللذة و الطیب . (منتهی الارب ).<br /></font></div>'),
(177021, 'طعثنة', '<span class=\"hlight\">طعثنة.</span> <font color=\"DarkGreen\"><b>[ طَ ث َ ن َ ]</font></b> (ع ص ) زن بدخوی . <BR><font color=\"Blue\">◄</font> غنم طعثنة؛ گوسفند بسیار. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177022, 'طعج', '<span class=\"hlight\">طعج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) نکاح . (تاج العروس ).<br /></font></div>'),
(177023, 'طعر', '<span class=\"hlight\">طعر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) آرامش با زن . <BR><font color=\"Blue\">◄</font> اجبار قاضی کسی را بر حکم . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177024, 'طعزبة', '<span class=\"hlight\">طعزبة.</span> <font color=\"DarkGreen\"><b>[ طَ زَ ب َ ]</font></b> (ع مص ) فسوس کردن . (منتهی الارب ) (آنندراج ). استهزاء کردن . <BR><font color=\"Blue\">◄</font> (اِمص ) فسوس . سخریه . (منتهی الارب ) (آنندراج ). لاغ .<br /></font></div>'),
(177025, 'طعس', '<span class=\"hlight\">طعس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) آرامش کردن با زن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177026, 'طعسبة', '<span class=\"hlight\">طعسبة.</span> <font color=\"DarkGreen\"><b>[ طَ س َ ب َ ]</font></b> (ع مص ) دویدن و سعی کردن در بیراهی . تعسف . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177027, 'طعسفة', '<span class=\"hlight\">طعسفة.</span> <font color=\"DarkGreen\"><b>[ طَ س َ ف َ ]</font></b> (ع مص ) سخت پای زدن بر زمین . <BR><font color=\"Blue\">◄</font> ناراست و ناهموار رفتن . (منتهی الارب ) (آنندراج ). یقال : مر یُطَعْسِف ُ فی الارض ؛ اذا مر یخبطها. لغت متروک و نامرغوب است . (منتهی الارب ).<br /></font></div>'),
(177028, 'طعشب', '<span class=\"hlight\">طعشب .</span> <font color=\"DarkGreen\"><b>[ طَ ش َ ]</font></b> (اِخ ) نام مردی است . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177029, 'طعطع', '<span class=\"hlight\">طعطع.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b>(ع ص ) زمین هموار و پست . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177030, 'طعل', '<span class=\"hlight\">طعل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص )طعن کردن در انساب مردم . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177031, 'طعم', '<span class=\"hlight\">طعم .</span> <font color=\"DarkGreen\"><b>[ طَ ع ِ ]</font></b> (ع ص ) مرد نیکوحال در خورش . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177032, 'طعم', '<span class=\"hlight\">طعم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) شیرینی و تلخی و آنچه مابین آنهاست و ترشی و نمکینی در خوردنی و نوشیدنی . ج، طُعوم . مزه . (منتهی الارب ) (آنندراج ). چشش . یقال : لیس له طعم ٌ و ما هو بذی طعم . (منتهی الارب ). لذت . (غیاث اللغات ). آنچه حیوان یابد بوسیله ٔ ظاهر روی زبان و اطراف آن به قوه ٔ ذائقه، از شیرینی و تلخی و شوری و ترشی و گسی و تیزی و دِبشی و میخوشی و ملسی و جز آن . شیخ الرئیس در قانون گوید طعوم اگر بیمزگی یعنی تفه را به حساب نیاوریم هشت است، و آن : حلاوت است (شیرینی ) و مرارت (تلخی ) و حرافت (تیزی ) و ملوحت (شوری ) و حموضت (ترشی ) و عفوصت (گسی ) و قبض و دسومت (چربی ). طعوم را نُه شمرده اند: شیرینی، ترشی، شوری، تیزی، تلخی، دسومت، عفوصت، قبض، تفاهت . و رجوع به طعوم شود. (از اساس ). و صاحب بحر الجواهر آرد:طعم چیزی است که حس ذوق بر آن حکم کند و بر نُه گونه است : چربی، شیرینی، تلخی، شوری، تیزی، ترشی، دبشی، گسی و بیمزگی (تفه ). (از بحر الجواهر) <span class=\"hlight\">:</span> <br />به طعم شکر بودم به طبع مازریون <br />چنان شدم که ندانم ترنگبین از ماز.<br /> <font color=\"Red\">مخلدی (از حاشیه ٔ فرهنگ اسدی نخجوانی ).</font><br />دفلی است دشمن من و من شهد جان نواز<br />چون شهد طعم حنظل و خوره کجا بود.<br /> <font color=\"Red\">فرخی .</font><br />که بیوسد ز زهر طعم شکر<br />نکند میل بی هنر به هنر.<br /> <font color=\"Red\">عنصری .</font><br />چون ز دلبر طعم شکر یافتم <br />دل چو عود از طعم شکر سوختم .<br /> <font color=\"Red\">عطار.</font><br />ترکیب ها:<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بدطعم </span> . بی طعم . ترش طعم . خوش طعم .<br /></font></div>'),
(177033, 'طعم', '<span class=\"hlight\">طعم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) خوردن چیزی را. (منتهی الارب ) (آنندراج ). طعمه طعماً و طعاماً؛ خورد آن را. (مجمل اللغه ). خوردن آب را. یقال : طعم الماء. (منتهی الارب ). چشیدن . (مجمل اللغة) (آنندراج ). <BR><font color=\"Blue\">◄</font> وصل پذیرفتن شاخ به شاخ دیگر: طعم الغصن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> مذاق <span class=\"hlight\">:</span> <br />خار با خرما بگاه طعم کس کی کرد جفت <br />لعل با خرمهره اندر عِقد کس کی کرد یار.<br /> <font color=\"Red\">سنائی .</font><br />و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٥</span> شود.<br /></font></div>'),
(177034, 'طعم', '<span class=\"hlight\">طعم .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) خوردنی . یقال : فلان قل طعمه ؛ ای اکله . (منتهی الارب ) (آنندراج ). طعام است .(فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> طعمه ٔ مرغ . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> توانائی . <BR><font color=\"Blue\">◄</font> چیزی که از خوردن آن سیری آید. و منه الحدیث فی زمزم : انها طعام ٌ طعم و شفاء سقم . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177035, 'طعم', '<span class=\"hlight\">طعم .</span> <font color=\"DarkGreen\"><b>[ طُ ع َ ]</font></b> (ع اِ) ج ِ طعمة.<br /></font></div>'),
(177036, 'طعم', '<span class=\"hlight\">طعم .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص )چشیدن . <BR><font color=\"Blue\">◄</font> قادر شدن بر چیزی . یقال : طعم علیه طعماً. توانستن . <BR><font color=\"Blue\">◄</font> مغز بهم رسانیدن استخوان . <BR><font color=\"Blue\">◄</font> و گویند: مایطعم آکل ُ هذا؛ یعنی سیر نمیشود خورنده ٔ آن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177037, 'طعم داشتن', '<span class=\"hlight\">طعم داشتن .</span> <font color=\"DarkGreen\"><b>[ طَ ت َ ]</font></b> (مص مرکب ) مزه داشتن <span class=\"hlight\">:</span> <br />آن کوزه بر کفم نه کآب حیات دارد<br />هم طعم نار دارد هم رنگ ناردانه .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(177038, 'طعمة', '<span class=\"hlight\">طعمة.</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (ع مص ) یک بار چشیدن . (منتخب اللغات ) (غیاث اللغات ).<br /></font></div>'),
(177039, 'طعمة', '<span class=\"hlight\">طعمة.</span> <font color=\"DarkGreen\"><b>[ طُ م َ ]</font></b> (ع اِ) طعمه . خورش . یقال : جعلت ضیعتی طعمة له . ج، طُعَم . (منتهی الارب ) (آنندراج ). خوراک . طُعم . غذا. خوردنی . <BR><font color=\"Blue\">◄</font> روزی . (زمخشری ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br />ملکان مرغ شکارندو فلک باز سپید<br />تا جهان بود و بوَد مرغ بوَد طعمه ٔ باز.<br /> <font color=\"Red\">فرخی .</font><br />این قوم را چنان صورت بسته است که این ناحیت طعمه ٔ ایشان است، غارت باید کرد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٦٤٩</span>).<br />شکمها را حریص طعمه کردی <br />شب و روز از پی نعمت دویدن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />طعمه ٔ شیر کی شود راسو<br />مُسته ٔ چرخ کی شود عصفور.<br /> <font color=\"Red\">مسعودسعد.</font><br />ملک را فریفته نباید شد بدانچه گوید او <font color=\"DarkGreen\"><b>[ گاو ]</font></b> طعمه ٔ من است . (کلیله و دمنه ). ما بر درگاه این ملک آسایش داریم و طعمه می یابیم . (کلیله و دمنه ). هرکه به ملوک نزدیکی جوید برای طعمه و قوت نباشد. (کلیله و دمنه ). هرکه همت اوبرای طعمه است در زمره ٔ بهایم معدود. (کلیله و دمنه ). طعمه ٔ او <font color=\"DarkGreen\"><b>[ شیر ]</font></b> فرونماند. (کلیله و دمنه ). شتربه طعمه ٔ من است . (کلیله و دمنه ).<br />طمع مدار که از بهر طعمه ٔ ارکان <br />عنان جان خرد را به حرص بسپارم .<br /> <font color=\"Red\">خاقانی .</font><br />زین سیه کاسه دست کفچه کنیم <br />طعمه ای بی بهانه بستانیم .<br /> <font color=\"Red\">خاقانی .</font><br />بی طعمه و طمع بسر آور چو کرم بید<br />چون کرم پیله سر چه کنی در سر دهان .<br /> <font color=\"Red\">خاقانی .</font><br />سنگ بر شیشه ٔ دل چون فکنم <br />روح را طعمه ٔ ارکان چه کنم .<br /> <font color=\"Red\">خاقانی .</font><br />آتشی کز دل شجر زاید<br />طعمه ٔ او هم از تن شجر است .<br /> <font color=\"Red\">خاقانی .</font><br />بس کن که هر مرغ ای پسر کی خوش خورد انجیر تر<br />شد طعمه ٔ طوطی شکر وان زاغ را چامین خر.<br /> <font color=\"Red\">مولوی .</font><br />بر سماع راست هر کس چیر نیست <br />طعمه ٔ هر مرغکی انجیر نیست .<br /> <font color=\"Red\">مولوی .</font><br />خزینه ٔ بیت المال لقمه ٔ مساکین است نه طعمه ٔ اخوان الشیاطین . (گلستان ). عابد از طعمه های لطیف خوردن گرفت و کسوتهای نظیف پوشیدن . (گلستان ).<br />نشد خاموش کبک کوهساری <br />از آن شد طعمه ٔ باز شکاری .<br /> <font color=\"Red\">وحشی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">به گنجشکان نشاید طعمه ٔ باز</span> .<br /> <span class=\"hlight\">هر کجا طعمه ای بود مگسی است </span> .<br /><BR><font color=\"Blue\">◄</font> وجه کسب . (منتهی الارب ) (آنندراج ). یقال : فلان عفیف الطعمة و خبیث الطعمة؛ ای الکسب . (منتهی الارب ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> ضیعه ای که حکومت واگذار کند به کسی تا آن را آبادان کند و عُشر محصول را بپردازد و به مرگ آنکس ضیعه به حکومت بازگردد و وارث را حقی بر آن نباشد. <BR><font color=\"Blue\">◄</font> (اصطلاح فقه ) سُدسی که به غیر وارث داده میشود. با بودن ابوین اجداد ارث نمیبرند، ولی در صورتی که سهم هر یک از ابوین ثلث یا بیشتر شد مستحب است که به اجداد طعمه بدهند.<br /></font></div>'),
(177040, 'طعمة', '<span class=\"hlight\">طعمة.</span> <font color=\"DarkGreen\"><b>[ طِ م َ ]</font></b> (ع اِ) روش خوردن .یقال : فلان حسن الطعمة؛ ای حسن السیرة فی الاکل . (منتهی الارب ) (آنندراج ). روش و سیرت در خوردن <span class=\"hlight\">:</span> <br />ز جغد و بوم به دیدار شوم تر صد ره <br />ولی به طعمه و خیتال جخج گوی همای .<br /> <font color=\"Red\">سوزنی .</font><br /><BR><font color=\"Blue\">◄</font> حرص در خوردن . (منتخب اللغات ).<br /></font></div>'),
(177041, 'طعمه خور', '<span class=\"hlight\">طعمه خور.</span> <font color=\"DarkGreen\"><b>[ طُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (نف مرکب ) خورنده ٔ طعمه . آنکه قوت خورد <span class=\"hlight\">:</span> <br />کرکس و شیر فلک طعمه خوران در مصاف <br />ماهی و گاو زمین لرزه کنان زیر بار.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(177042, 'طعمه دادن', '<span class=\"hlight\">طعمه دادن .</span> <font color=\"DarkGreen\"><b>[ طُ م َ <span class=\"hlight\" dir=\"rtl\">/</span>م ِ دَ ]</font></b> (مص مرکب ) غذا دادن . قوت دادن <span class=\"hlight\">:</span> <br />از آتش طعمه خواهم داد دل را<br />چو دل خرسند شد گو خاک خور تن .<br /> <font color=\"Red\">خاقانی .</font><br />ناگزیر است مرا طعمه ٔ موران دادن <br />گر نه موران به سر کان شدنم نگذارند.<br /> <font color=\"Red\">خاقانی .</font><br />آسمان هر دم کشد و آنگه دهد<br />کشتگان را طعمه ٔ اجرام خویش .<br /> <font color=\"Red\">خاقانی .</font><br />هجر توام که خون جگر طعمه می دهد<br />گر تو به خوان وصلش مهمان نمیکنی .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(177043, 'طعمه ساختن', '<span class=\"hlight\">طعمه ساختن .</span> <font color=\"DarkGreen\"><b>[ طُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ت َ ]</font></b> (مص مرکب ) غذا قرار دادن . خوردن <span class=\"hlight\">:</span> <br />آنکس که طعمه سازد سی سال خون مردم <br />نه آخرش به طاعون صورت شود مبتر.<br /> <font color=\"Red\">خاقانی .</font><br />چون شرر شد قوی همه عالم <br />طعمه سازد چه حاجت تبر است .<br /> <font color=\"Red\">خاقانی .</font><br />من نی خشکم وگرچه طعمه ٔ آتش نی است <br />طعمه ٔ این خشک نی زان آتش تر ساختند.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(177044, 'طعمه کردن', '<span class=\"hlight\">طعمه کردن .</span> <font color=\"DarkGreen\"><b>[ طُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ک َ دَ]</font></b> (مص مرکب ) غذا قرار دادن . قوت ساختن <span class=\"hlight\">:</span> <br />همای کُش تر از این کرکسان جیفه نهاد<br />ندیده ام که ز عنقا کنند طعمه عقاب .<br /> <font color=\"Red\">خاقانی .</font><br />مست مکن عقل ادب ساز را<br />طعمه ٔ گنجشک مکن باز را.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(177045, 'طعن', '<span class=\"hlight\">طعن .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) زدن به نیزه کسی را. (منتهی الارب ) (آنندراج ). لَزّ. (منتهی الارب ). نیزه زدن . (ترجمان علامه ٔ جرجانی ص <span class=\"hlight\" dir=\"rtl\">٦٧</span>). خستن . (دهار) <span class=\"hlight\">:</span> <br />تو حمله آری چون آب و آتش از چپ و راست <br />به ضرب و طعن برآری دمار از آتش و آب .<br /><font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> کلان سال گردیدن : طعن فی السن ّ. (منتهی الارب ) (آنندراج ). پیر شدن . سالخورده گردیدن . <BR><font color=\"Blue\">◄</font> رفتن : طعن فی المفازة؛ رفت در بیابان . طعن اللیل ؛ همه شب رفت . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> رنجانیدن کسی را به سخن : طعن فیه بالقول طعناً و طعناناً. (منتهی الارب ) (آنندراج ). عیب کردن . (ترجمان علامه ٔ جرجانی ص <span class=\"hlight\" dir=\"rtl\">٦٧</span>) (مصادر زوزنی ). به بد یاد کردن . (تاج المصادر بیهقی ). عیب کردن در کار کسی . (غیاث اللغات ). قَدْح . بیغاره . گواژه گفتن <span class=\"hlight\">:</span> اگر خرج آن بیوجه کند پشیمانی آرد و زبان طعن در وی گشاده شود. (کلیله و دمنه ).<br />چنان استاده ام پیش و پس طعن <br />که استاده ست الفهای اطعنا.<br /> <font color=\"Red\">خاقانی .</font><br />چو مریم سر فکنده زیرم ازطعن <br />سرشکم چون دم عیسی مصفا.<br /> <font color=\"Red\">خاقانی .</font><br />ترسی ز طعن دشمن و گردی بلندنام <br />بینی غرور دوست شوی پست و مختصر.<br /><font color=\"Red\">خاقانی .</font><br />کوته نظران را بدین علت زبان طعن دراز گردد. (گلستان ).<br />غمناک نباید بود از طعن حسود ای دل <br />شاید که چو وابینی خیر تو دراین باشد.<br /> <font color=\"Red\">حافظ.</font><br />هست طعن زبان بدگهران <br />برتر از ضرب خنجر بُرّان .<br /> <font color=\"Red\">مکتبی .</font><br /><BR><font color=\"Blue\">◄</font> قَدْح کردن در حسب و دین کسی . (از منتهی الارب ) (از آنندراج ). قوله تعالی <span class=\"hlight\">:</span> طعناً فی الدین (قرآن <span class=\"hlight\" dir=\"rtl\">٤٦/٤</span>)؛ طعن قدح باشد، و اصل او طعن لسان است، آنکه طعن به زبان را به آن تشبیه کرده اند. (از تفسیر ابوالفتوح ): طعن کردن حسب و آبروی کسی را؛مزق عِرض اخیه مزقاً. کرظ فی عرضه کرظاً. مرد مرداً. طعن کردن در حسب کسی ؛ طعن فیه بالقول طعناً و طَعناناً. بسیار طعن کننده ؛ مطعان . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> طاعون رسیدن به کسی : طُعِن َ طعناً (مجهولاً). (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> گام زدن اسب . نیکو رفتن اسب چون عنان را بکشی . (منتهی الارب ) (آنندراج ). پای دراز نهادن . و الفرس یطعن فی العنان ؛ اذا مده و ینشط فی السیر. (تاج المصادر بیهقی ).<br /></font></div>'),
(177046, 'طعن', '<span class=\"hlight\">طعن .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) ج ِ طعین، به معنی طاعون زده .<br /></font></div>'),
(177047, 'طعن آمیز', '<span class=\"hlight\">طعن آمیز.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ن مف مرکب ) آمیخته به سرزنش .<br /></font></div>'),
(177048, 'طعن زدن', '<span class=\"hlight\">طعن زدن .</span> <font color=\"DarkGreen\"><b>[ طَ زَ دَ ]</font></b> (مص مرکب ) سرزنش کردن . نکوهش کردن <span class=\"hlight\">:</span> <br />زده کنگرش طعنها بر فلک <br />رسیده سر تیغ او بر ملک .<br /> <font color=\"Red\">فردوسی .</font><br />در تاریخی که میکنم سخنی نرانم که آن به تعصبی و میلی کشد... بلکه آن گویم که تا خوانندگان با من اندر این موافقت کنند و طعنی نزنند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٧٥</span>).<br />اگر طعنی زند بر وی خسیسی <br />بجزوحشت مباد او را انیسی .<br /> <font color=\"Red\">نظامی .</font><br />رجوع به طعنه زدن شود.<br /></font></div>'),
(177049, 'طعن و دق', '<span class=\"hlight\">طعن و دق .</span> <font color=\"DarkGreen\"><b>[ طَ ن ُ دَق ق <span class=\"hlight\" dir=\"rtl\">/</span> دَ ]</font></b> (ترکیب عطفی، اِ مرکب ) از اتباع است . رجوع به طعن و رجوع به دق شود <span class=\"hlight\">:</span> <br />کی زنم بر آلت حق طعن و دق .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(177050, 'طعن و طنز', '<span class=\"hlight\">طعن و طنز.</span> <font color=\"DarkGreen\"><b>[ طَ ن ُ طَ ]</font></b> (ترکیب عطفی، اِ مرکب ) از اتباع است . رجوع به طعن و رجوع به طنز شود.<br /></font></div>'),
(177051, 'طعن و لعن', '<span class=\"hlight\">طعن و لعن .</span> <font color=\"DarkGreen\"><b>[ طَ ن ُ ل َ ]</font></b> (ترکیب عطفی، اِ مرکب ) از اتباع است . سرزنش و نفرین . رجوع به طعن و رجوع به لعن شود.<br /></font></div>'),
(177052, 'طعن کردن', '<span class=\"hlight\">طعن کردن .</span> <font color=\"DarkGreen\"><b>[ طَ ک َ دَ ]</font></b> (مص مرکب ) عیب کردن . سرزنش کردن . ملامت کردن . جرح . (منتهی الارب ) (ترجمان القرآن ). اغتماز. اغماز. لدغ . تلداغ . کرظ. (منتهی الارب ). و رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">٢٣٦</span> شود <span class=\"hlight\">:</span> سلطان محمود گفت : مذهب راست ازآن ِ امام ابوحنیفه ... تبانیان دارند و شاگردان ایشان چنانکه در ایشان هیچ طعن نتوان کرد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span>).<br />گر ترا طعنی کنند زیشان مگیر از بهرآنک <br />مردم بیمار باشد یافه گوی و هرزه لا.<br /> <font color=\"Red\">سنائی .</font><br />طعنم مکن که چیست به خاکستر الفتت <br />این مستمند سوخته بیمار آتش است .<br /><font color=\"Red\">درویش واله هروی (از آنندراج ).</font><br /></font></div>'),
(177053, 'طعنان', '<span class=\"hlight\">طعنان .</span> <font color=\"DarkGreen\"><b>[ طَ ع َ ]</font></b> (ع مص ) طَعن . رنجانیدن کسی رابه سخن : طعن فیه بالقول طعناً و طعناناً. <BR><font color=\"Blue\">◄</font> طعن کردن در حسب کسی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177054, 'طعنة', '<span class=\"hlight\">طعنة.</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (ع مص ) طعنه . یک بار نیزه زدن . (غیاث اللغات ) (آنندراج ). طعنةٌ سلکی ؛ نیزه زدنی راست . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> عیب جوئی کردن . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> مجازاً، بیغاره . سرزنش . ملامت . گواژه . (حاشیه ٔ فرهنگ اسدی نخجوانی ). زخم . (صراح ). فسوس . (ناظم الاطباء). تفش . (مجمعالفرس ). و بمعنی بد گفتن کسی را مجاز است و با لفظ کشیدن و بردن و زدن و کردن و داشتن و فروختن و باریدن مستعمل . (آنندراج ). و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span> شود <span class=\"hlight\">:</span> <br />غلام و جام می را دوست دارم <br />نه جای طعنه و جای ملام است .<br /> <font color=\"Red\">منوچهری .</font><br />هرچه وزیر میگفت به طعنه جواب میداد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٨٦</span>).<br />گر مخالف معسکری سازد<br />طعنه ای در برابر اندازد.<br /> <font color=\"Red\">خاقانی .</font><br />با لذت طعنه ٔ تو دل را<br />فرموش شد آرزوی مرهم .<br /> <font color=\"Red\">خاقانی .</font><br />بدانکه نیست کفم چون دهان گل پرزر<br />به دست طعنه چرا هر خسی نهد خارم .<br /> <font color=\"Red\">خاقانی .</font><br />لیکن از روی طعنه ٔ خصمان <br />آمدن هیچ رو نمیدارد.<br /> <font color=\"Red\">خاقانی .</font><br />دو بیوه بهم گفتگو ساختند<br />سخن را به طعنه درانداختند.<br /> <font color=\"Red\">نظامی .</font><br />هر هنری طعنه ٔ شهری بود<br />هر شکری زحمت زهری بود.<br /> <font color=\"Red\">نظامی .</font><br />یکی از بزرگان گفت پارسائی را چه گویی درحق فلان عابد که دیگران در حق او به طعنه سخنها گفته اند. (گلستان ). ملاح بیمروت از او به خنده برگردید، جوان را دل از طعنه ٔ ملاح بهم برآمد. (گلستان ).<br />مسلمانی اگر کعبه پرستی است <br />پرستاران بت را طعنه از چیست .<br /> <font color=\"Red\">شبستری .</font><br />ای که ز بت طعنه به هندو بری <br />هم ز وی آموز پرستشگری .<br /><font color=\"Red\">امیرخسرو (از آنندراج ).</font><br />دو دوست با هم اگر یکدلند در همه کار<br />هزار طعنه ٔ دشمن به نیم جو نخرند.<br /> <font color=\"Red\">ابن یمین .</font><br />یکی را بود طعنه درلفظ او<br />یکی را سخن در معانی بود.<br /><font color=\"Red\">ابن نصیر.</font><br /></font></div>'),
(177055, 'طعنه', '<span class=\"hlight\">طعنه .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (اِخ ) دهی است از دهستان آتابای بخش آق قلعه ٔ شهرستان گنبد قابوس در <span class=\"hlight\" dir=\"rtl\">١/٥</span>هزارگزی خاور آق قلعه، جنوب رودخانه ٔ گرگان . دشت و معتدل و مرطوب و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٨٠٠٠</span> تن سکنه . آب آن از رودخانه ٔ گرگان بوسیله ٔ موتور برداشته میشود. محصول آنجا غلات و صیفی و حبوبات و لبنیات . شغل اهالی زراعت وگله داری . صنایع دستی زنان قالیچه بافی است . راه فرعی به آق قلعه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(177056, 'طعنه آمیز', '<span class=\"hlight\">طعنه آمیز.</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ن مف مرکب ) سخنی آمیخته به سرزنش و بیغاره .<br /></font></div>'),
(177057, 'طعنه آوردن', '<span class=\"hlight\">طعنه آوردن .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ وَ دَ ]</font></b> (مص مرکب ) طعنه زدن . نکوهش کردن <span class=\"hlight\">:</span> <br />میار طعنه در آن کش سموم بادیه سوخت <br />که آن سفر ز عذاب سقر فزون آمد.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(177058, 'طعنه تراش', '<span class=\"hlight\">طعنه تراش .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ت َ ]</font></b> (نف مرکب ) آنکه زبانش پیوسته به عیب دیگران گویا باشد <span class=\"hlight\">:</span> <br />زبان تیشه ٔ فرهاد همچنان تیز است <br />هنوز طعنه تراش از برای پرویز است .<br /><font color=\"Red\">نورالدین ظهوری (از آنندراج ).</font><br /></font></div>'),
(177059, 'طعنه داشتن', '<span class=\"hlight\">طعنه داشتن .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ت َ ]</font></b> (مص مرکب ) توبیخ و سرزنش کردن . طعنه زدن <span class=\"hlight\">:</span> <br />گشته تا بیت الشرف از مقدمت کاشانه ام <br />طعنه بر خورشید دارد خشت فرش خانه ام .<br /><font color=\"Red\">مخلص کاشی (از آنندراج ).</font><br /></font></div>'),
(177060, 'طعنه زدن', '<span class=\"hlight\">طعنه زدن .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ زَ دَ]</font></b> (مص مرکب ) عیبجوئی کردن . <BR><font color=\"Blue\">◄</font> مجازاً، توبیخ و سرزنش کردن . بد گفتن . خرده گرفتن <span class=\"hlight\">:</span> <br />به دل کین همی داشت <font color=\"DarkGreen\"><b>[ گرزم ]</font></b> ز اسفندیار<br />ندانم چه شان بود ز آغاز کار<br />هر آنجا که آواز او آمدی <br />از او زشت گفتی و طعنه زدی .<br /> <font color=\"Red\">دقیقی (از شاهنامه ).</font><br />ما را بدان لب تو نیاز است در جهان <br />طعنه مزن که با دو لب من چرا چخی .<br /> <font color=\"Red\">کسائی .</font><br />چه زنی طعنه که با هیزان هیزند همه <br />که توئی هیز و توئی مسخره و شنگ و مشنگ .<br /> <font color=\"Red\">خطیری .</font><br />به یتیمی و دوروئیت همی طعنه زنند<br />نه گل است آنکه دوروی و نه دُر است آنکه یتیم .<br /> <font color=\"Red\">اسکافی (از تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٨٩</span>).</font><br />چند زنی طعنه ٔ باطل که تو<br />مرتبت یاران را منکری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />طعنه چه زنی مر مرا بدان کم <br />از خانه براندند اهل عصیان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ز رغم آنکه به خاقانی تو طعنه زنند<br />غم تو شادی من شد که شادمان بادی .<br /> <font color=\"Red\">خاقانی .</font><br />ای طعنه زده به دیگرانم <br />در کاهش جان من فزوده .<br /> <font color=\"Red\">خاقانی .</font><br />بر طرز عنصری رَوَد و خصم عنصری است <br />کاندر قصیده هاش زند طعنه های چست .<br /> <font color=\"Red\">خاقانی .</font><br />از دست عشق چون به سفالی شراب خورد<br />طعنه نخست در گهر جام جم زند.<br /> <font color=\"Red\">خاقانی .</font><br />مرا طعنه مزن در عشق فرهاد<br />به نیکی کن غریب مرده را یاد.<br /> <font color=\"Red\">نظامی .</font><br />چه طعنه زنی مرا که من نیز<br />در سوختنم به بی قراری .<br /> <font color=\"Red\">عطار.</font><br />که صواب این است و راه این است و بس <br />کی زند طعنه مرا جز هیچکس .<br /> <font color=\"Red\">مولوی .</font><br />آنکه میلرزد ز بیم رد او<br />آنکه طعنه میزند بر جد او.<br /> <font color=\"Red\">مولوی .</font><br />طعنه بر عیب دیگران مزنید.<br /> <font color=\"Red\">(گلستان ).</font><br />همه حمال عیب خویشتنیم <br />طعنه بر عیب دیگران چه زنیم .<br /> <font color=\"Red\">سعدی .</font><br />یاسمین روئی که سرو قامتش <br />طعنه بر بالای عرعر میزند.<br /> <font color=\"Red\">سعدی .</font><br />چون صدف پروردم اندر سینه دُرّ معرفت <br />تا به جوهر طعنه بر دُرهای دریائی زدم .<br /> <font color=\"Red\">سعدی .</font><br />طعنه برحیرت سعدی نه به انصاف زدی <br />کس چنین روی نبیند که نه حیران ماند.<br /> <font color=\"Red\">سعدی .</font><br />به طعنه ای زده باد آنکه بر تو خواهد بد<br />که بار دیگرش از سینه برنیاید وای .<br /><font color=\"Red\">سعدی .</font><br />کجائی ای که تعنت کنی و طعنه زنی <br />تو بر کناری و ما اوفتاده در غرقاب .<br /> <font color=\"Red\">سعدی .</font><br />ترا آسمان خطبه مسجد نوشت <br />مزن طعنه بر دیگری در کنشت .<br /> <font color=\"Red\">سعدی .</font><br />یکی طعنه میزد که درویش بین <br />زهی پارسایان پاکیزه دین .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />طعنه بر من مزن به صورت زشت <br />ای تهی از فضیلت انصاف <br />تن بود چون غلاف و جان شمشیر<br />کار شمشیر میکند نه غلاف .<br /> <font color=\"Red\">جامی (بهارستان ).</font><br />سزد گر طعنه حیوانی زند بر زاهدان طالب <br />که باز از دست ساقی جرعه ای نوشید و آدم شد.<br /> <font color=\"Red\">طالب آملی (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">گذشت آنکه عرب طعنه بر عجم میزد</span> .<br /></font></div>'),
(177061, 'طعنه زن', '<span class=\"hlight\">طعنه زن .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ زَ ]</font></b> (نف مرکب ) ملامتگر. عیبجو. بدگو <span class=\"hlight\">:</span> <br />گر طعنه زنش معاف کردی <br />با موکب خود مصاف کردی .<br /> <font color=\"Red\">نظامی .</font><br />به جان آید از دست طعنه زنان <br />که خود را بیاراست همچون زنان .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />خاکش طعنه زن گوی عنبرآکنده و ریگش طیره ده مروارید پراکنده . (ترجمه ٔ محاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br /></font></div>'),
(177062, 'طعنه زنان', '<span class=\"hlight\">طعنه زنان .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ زَ ]</font></b> (نف مرکب، ق مرکب ) در حال طعنه زدن و عیبجوئی <span class=\"hlight\">:</span> خواجه شادی کنان که پسرم عاقل است و پسر طعنه زنان که پدرم فرتوت . (گلستان ).<br /></font></div>'),
(177063, 'طعنه زننده', '<span class=\"hlight\">طعنه زننده .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ زَ ن َن ْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) که طعنه زند. که ملامت کند: مِلْدَغ ؛ طعنه زننده مردم را. (منتهی الارب ).<br /></font></div>'),
(177064, 'طعنه و تعریض', '<span class=\"hlight\">طعنه و تعریض .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ وُ ت َ ]</font></b> (ترکیب عطفی، اِ مرکب ) از اتباع است . به کنایه سخن گفتن : سخن به طعنه و تعریض گفت . رجوع به تعریض شود.<br /></font></div>'),
(177065, 'طعنه کردن', '<span class=\"hlight\">طعنه کردن .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ک َ دَ ]</font></b> (مص مرکب ) طعنه زدن . عیبجوئی و بدگوئی کردن <span class=\"hlight\">:</span> <br />آن گل که برنگ طعنه در می کرده ست <br />با عارض تو برابری کی کرده ست .<br /> <font color=\"Red\">خاقانی .</font><br />نه ابلیس در حق ما طعنه کرد<br />کز اینان نیاید بجز کار بد.<br /> <font color=\"Red\">سعدی .</font><br />چنین که تازه غزل سر زند ز طبع نصیر<br />شگفت نیست اگر طعنه بر هزار کند.<br /><font color=\"Red\">ابونصر نصیرای بدخشانی (از آنندراج ).</font><br /></font></div>'),
(177066, 'طعنه کشیدن', '<span class=\"hlight\">طعنه کشیدن .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) تحمل کردن سرزنش دیگران را. توبیخ رسیدن به کسی <span class=\"hlight\">:</span> <br />طعنه ٔ خامی همان صائب ز مردم میکشم <br />گرچه میریزد شرار از سوز گفتارم چو شمع.<br /><font color=\"Red\">صائب .</font><br /></font></div>'),
(177067, 'طعنه گر', '<span class=\"hlight\">طعنه گر.</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ گ َ ]</font></b> (ص مرکب ) که پیشه اش عیبجوئی باشد. صاحب آنندراج این لفظ را بدون بیان معنی آن در فرهنگ خویش با بیت بدر چاچی شاهد استعمال آورده است <span class=\"hlight\">:</span> <br />صحن تو بادجلوه گر روضه ٔ هشت باب را<br />خلق تو باد طعنه گر بوی خوش بهار را.<br /></font></div>'),
(177068, 'طعوم', '<span class=\"hlight\">طعوم .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طَعْم . مزه ها. (از منتهی الارب ). صاحب کشاف اصطلاحات الفنون آرد: حکما گفته اند طعوم (مزه ها) بر دوگونه اند: بسیط و مرکب . و مزه های بسیط نُه قسم اند که از ضرب سه در سه حاصل آیند زیرا فاعل یا گرم و یا سرد و یا معتدل است، و قابل نیز یا لطیف و یا کثیف و یا معتدل باشد، چنانکه گرم کیفیت غیرملایمی در اجسام پدید آرد، چه خاصیت آن تفریق است از این رو در جسم کثیف کیفیت کثیفی که غایةً غیرملایم است ایجاد میکند که مرارت (تلخی ) است و در جسم لطیف خاصیتی فروتر از آن تولید میکند که حرافت (تیزی ) است و در معتدل ملوحت (شوری ) ایجاد کند که حد میانه ٔ دو خاصیت مزبور یعنی تلخی و تیزی است . و سرد نیز کیفیت غیرملایمی پدید می آورد، چه خاصیت تکثیف است که با اجسام سازگار نیست لیکن ناسازگاری آن از عدم تفریق کمتر است، چنانکه در جسم کثیف عفوصت (گسی ) تولید کند، چه مزه ٔ مزبور تکثیف را متضاعف کند و در لطیف حموضت (ترشی ) ایجاد کند زیرا ناسازگاری آن بینابین است و فاعل به سردی و آن را کثیف کند و به لطافت در آن فرورود. و در معتدل قبض بوجود آورد که فروتر از گسی و برتر از ترشی است زیرا گسی هم ظاهر و هم باطن زبان را قبض میکند ولی قابض تنها ظاهر زبان را به قبض دچار میسازد و معتدل تأثیر ملایم و سازگاری بخشد، چنانکه در کثیف حلاوت (شیرینی ) و در لطیف دسومت (چربی ) و در معتدل تفاهت (بیمزگی ) تولید کند. اینها مزه های بسیطاند و از هر یک از مزه های مزبور طعم های گوناگونی ترکیب میشود که میتوان گفت آنها را نهایتی نیست . و این گونه مزه های گوناگون یا بر حسب ترکیب و یا بر حسب ترک اسباب است، چنانکه برخی از آنها دارای نام جداگانه ای باشند مانند بشاعت که از تلخی و قبض مرکب است و در حُضَض وجود دارد.و همچون زعوقت که از شوری و تلخی مرکب است و در حالت تب دست میدهد و گاهی به مزه ها کیفیت لمسی پیوسته میشود چنانکه حس آن کیفیت و کیفیت طعمی را از یکدیگر بازنمیشناسد و مجموع آن دو کیفیت طعم واحدی را تشکیل میدهد مانند اجتماع تفریق و حرارت با یکی از طعم ها که مجموع آنها را حرافت (تیزی ) پندارند یا همچون اجتماع تکثیف و تجفیف با یکی از طعم ها که مجموع آنها را عفوصت (گسی ) گمان کنند. (از کشاف اصطلاحات الفنون از شرح مواقف ) <span class=\"hlight\">:</span> <br />جزکه صاحب ذوق که شناسد طعوم <br />شهد را ناخورده کی داند ز موم .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(177069, 'طعوم', '<span class=\"hlight\">طعوم .</span> <font color=\"DarkGreen\"><b>[طَ ]</font></b> (ع ص ) شتر با مغز استخوان و با پیه . <BR><font color=\"Blue\">◄</font> جزورٌ طعوم ؛ شتر کشتنی که نه لاغر باشد نه فربه . مذکر و مؤنث در وی یکسان است . (منتهی الارب ) (آنندراج ). جزورٌ طعیم مثله . (منتهی الارب ). یقال : جزورٌ طعوم ٌ و طعیم ٌ؛ ای بین الغث و السمین . (مهذب الاسماء).<br /></font></div>'),
(177070, 'طعومة', '<span class=\"hlight\">طعومة.</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (ع ص، اِ) گوسپند که جهت خوردن نگاه دارند. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177071, 'طعیم', '<span class=\"hlight\">طعیم .</span> <font color=\"DarkGreen\"><b>[ طُ ع َ ]</font></b> (اِخ ) نام مردی . (منتهی الارب ).<br /></font></div>'),
(177072, 'طعیم', '<span class=\"hlight\">طعیم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) جزورٌ طعیم ٌ؛ شتر کشتنی که نه لاغر باشد نه فربه . (منتهی الارب ). یقال : جزورٌ طعوم ٌ و طعیم ٌ؛ ای بین الغث و السمین . (مهذب الاسماء).<br /></font></div>'),
(177073, 'طعین', '<span class=\"hlight\">طعین .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) مجروح و درخسته ٔ به نیزه . ج، طُعن . <BR><font color=\"Blue\">◄</font> طاعون زده . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177074, 'طغ', '<span class=\"hlight\">طغ.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام یکی از قبایل قوم قبچاق بوده است . رجوع به نخبةالدهر دمشقی ص <span class=\"hlight\" dir=\"rtl\">٢٦٤</span> شود.<br /></font></div>'),
(177075, 'طغ', '<span class=\"hlight\">طغ.</span> <font color=\"DarkGreen\"><b>[ طَغ غ ]</font></b> (ع اِ) گاو نر. (منتهی الارب ) (آنندراج ). طُغیا. (منتهی الارب ). به عربی اسم ثور است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177076, 'طغا', '<span class=\"hlight\">طغا.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) (امیر...) از امرای دوران مغول معاصر کیخاتوخان بن ابقاخان بن هولاکوخان که در قرن هفتم میزیسته است . رجوع به تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٥٩٠</span> شود.<br /></font></div>'),
(177077, 'طغات', '<span class=\"hlight\">طغات .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) طُغاة.ج ِ طاغی <span class=\"hlight\">:</span> فی الجمله چون آن حدود از طُغات پاک شد. (جهانگشای جوینی ). و آن حدود را چندانک از طغات پاک کند، او را مسلم باشد. (جهانگشای جوینی ). و خراسان از طغاة و عداة پاک گشت . (جهانگشای جوینی ).<br /></font></div>'),
(177078, 'طغاترکان', '<span class=\"hlight\">طغاترکان .</span> <font color=\"DarkGreen\"><b>[ طُ ت َ ]</font></b> (اِخ ) طغای ترکان . یکی از دختران میرزا الغبیک گورکان . رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤٢</span> شود.<br /></font></div>'),
(177079, 'طغاتیمور', '<span class=\"hlight\">طغاتیمور.</span> <font color=\"DarkGreen\"><b>[ طُ ت َ ]</font></b> (اِخ ) چهاردهمین پسر هلاکوخان که مادرش در سلک قمکان انتظام داشت . رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٣</span> شود.<br /></font></div>'),
(177080, 'طغاتیمور', '<span class=\"hlight\">طغاتیمور.</span> <font color=\"DarkGreen\"><b>[ طُ ت َ ]</font></b> (اِخ ) از امرای غازان بوده است که در جنگ با مصر و شام منهزم شد. رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٦</span> شود.<br /></font></div>'),
(177081, 'طغاتیمورخان', '<span class=\"hlight\">طغاتیمورخان .</span> <font color=\"DarkGreen\"><b>[ طُ ت َ ]</font></b> (اِخ ) وی از نبیره زادگان جوجی قسار برادر چنگیزخان بود. پس از استیلای امیر شیخ حسن ایلکانی بر آذربایجان جمعی از امرای ابوسعیدبا او از در دشمنی درآمده، به همراهی هم از آذربایجان و عراق گریخته به خراسان آمدند و حکمران خراسان یعنی امیر شیخعلی قوشچی را به مخالفت با امر شیخ حسن تحریک کردند و این مخالفین که اهم ایشان امیر پیرحسین پسر امیر محمودبن امیر چوپان و امیر ارغونشاه پسر امیر نوروز مشهور و امیر عبداﷲ پسر امیر مولای و امیرعلی جعفر بودند به کمک امیر شیخعلی یکی از شاهزادگان خاندان چنگیزی را که در مازندران اقامت داشت و از نبیره زادگان یکی از برادران چنگیزخان بود و طغاتیمورخوانده میشد به ایلخانی برگزیدند و در مقابل محمدخان و امیر شیخ حسن آلتی جهت اجرای مقاصد خود تراشیدند. بعد از اعلان ایلخانی طغاتیمورخان امرای سرکش او رابرداشته بطرف آذربایجان حرکت کردند و در حدود این مملکت موسی خان آلت امیر علی پادشاه هم که از چنگ امیرشیخ حسن ایلخانی گریخته بود به ایشان ملحق شد و طرفداران طغاتیمور و موسی چنین قرار گذاشتند که پس از دفع امیر شیخ حسن خراسان طغاتیمور را باشد و عراق و آذربایجان موسی خان را. جنگ بین اردوی متحدین و لشکریان امیر شیخ حسن در نیمه ٔ ذی القعده ٔ سال <span class=\"hlight\" dir=\"rtl\">٧٣٧</span> هَ . ق . در نزدیکی مراغه اتفاق افتاد، طغاتیمور گریخت و موسی خان به چنگ امیر شیخ حسن افتاده، در دهم ذی الحجه ٔ آن سال مقتول شد و از قضا در همان روز امیر ارغونشاه هم امیر شیخعلی را در خراسان به قتل رساند و در یک روز، دو دشمن امیر شیخ حسن از میان رفتند. امیر شیخ حسن آذربایجان و عراق را مسخر خویش کرد و طغاتیمورخان هم به خراسان آمده به کمک بقیه ٔ امرای موافق خود در آن مملکت به ایلخانی مشغول شد. بعد از قتل موسی خان وفرار طغاتیمور به خراسان برای ممالک ایلخانی دو نفرمدعی باقی ماند، اول طغاتیمورخان که جرجان و خراسان را تحت اطاعت خود داشت، دوم محمدخان آلت مقاصد شیخ حسن بزرگ . در سال <span class=\"hlight\" dir=\"rtl\">٧٣٩</span> شانزده نفر از بازماندگان شیخ حسن چوپانی از وی خواستند که یکی از افراد خاندان هلاکو را به ایلخانی انتخاب کند، چون مردی نامی از آن خاندان باقی نبود امرای هزاره ها و چوپانیان ساتی بیک دختر الجایتو و خواهر ابوسعید را که با امیر شیخ حسن بزرگ صفائی نداشت به این مقام برداشتند... و آذربایجان و اران تحت امر ساتی بیک و شیخ حسن کوچک درآمد، ولی از سایر نقاط ایران و عراق هر قسمت آن را امیری ازامراء سابق اولجایتو و ابوسعید یا خاندانی از خاندانهای مطیع ایشان تحت حکم داشتند... از آن جمله قسمتی از خراسان با جرجان را طغاتیمور تحت اختیار داشت .<br />... در این اثنا دو امیر شیخ حسن بزرگ و کوچک خواستند با یکدیگر عقد صلح و اتفاقی بازبندند و چون این صلح اگر دوام میکرد دیگر برای شیخ حسن بزرگ حیثیتی باقی نمیگذاشت و از جانب او در حکم تصدیق سیادت امیر شیخ حسن کوچک و خاندان چوپانی بود بهمین نظر شیخ حسن بزرگ یکی از خواص خود را به خراسان فرستاده، طغاتیمورخان را به آمدن به عراق تحریک نمود، طغاتیمورخان هم به همراهی امیر ارغونشاه و خواجه علاءالدین محمود وزیر از خراسان حرکت کرده در ماه رجب <span class=\"hlight\" dir=\"rtl\">٧٣٩</span> به ساوه آمد و در آنجا شیخ حسن بزرگ به خدمت او رسیده، مراسم استقبال بعمل آورد، ولی کمی بعد ملتفت خبط خود شد و دید که امرای خراسان همه مطیع رأی خواجه علاءالدین وزیرند و به اواعتنائی ندارند، اما چون چاره ای نداشت تحمل کرد و در این ضمن خبر حرکت شیخ حسن چوپانی و ساتی بیک و امیرسیورغان از ارّان به عزم دفع طغاتیمورخان رسید.<br />... امیر شیخ حسن چوپانی برای درهم پاشیدن اساس اردوی طغاتیمور و شیخ حسن بزرگ به فکر حیله افتاد و بظاهرطلب صلح کرد، طغاتیمور هم سوابق دوستی پدر خود را با امیر چوپان به یاد آورده، از دو طرف قرار مصالحه داده شد و شیخ حسن کوچک به طغاتیمور پیغام داد که اگراو در دفع شیخ حسن بزرگ مساعدت نماید ساتی بیک به عقد او خواهد درآمد و عموم چوپانیان خدمت او را کمر خواهند بست . طغاتیمور ساده لوح، این پیغام مزورانه ٔ شیخ حسن کوچک را پذیرفت و وثیقه نامه ای به خط خود در میناب نوشته پیش شیخ حسن بزرگ فرستاد و خیالات طغاتیمور را به اطلاع او رساند. امیر ایلکانی از این بابت در حیرت شد و طغاتیمور را از قضیه آگاه ساخت . طغاتیمور از خجالت سر بزیر افکنده به خراسان برگشت و شیخ حسن ایلکانی نیز به خدمت ساتی بیک آمده دست خاتون را بوسیدو پس از عذرخواهی با اردو به اوجان آمد.<br />طغاتیمورخان بعد از شکستهائی که او و برادرش امیرعلی کاون در عراق خوردند به همان جرجان و خراسان قناعت کرده بود و تا تاریخ قیام سربداران خراسان را بتوسط عمال خویش به وضعی ناگوار اداره میکرد و ارغونشاه جانی قربانی از جانب او در نیشابور اقامت داشت .<br />... بعد از آنکه ارغونشاه به دست سربداران به قتل رسید و آوازه ٔ اقتدار این طایفه در خراسان پیچید طغاتیمورخان لشکری فراهم کرده ایشان را به همراهی برادر خود امیر علی از جرجان به سبزوار روانه کرد. امیر مسعود و شیخ حسن جوری در سال <span class=\"hlight\" dir=\"rtl\">٧٤١</span> به جلو آن اردوشتافتند، سربداران امیر علی برادر طغاتیمورخان را در معرکه ٔ قتال کشتند و بعد از جنگ سختی بر سپاهیان طغاتیمورخان غلبه یافته ایشان را منهزم ساختند و با غنایم بسیار به سبزوار برگشتند و این فتح بیش از پیش ایشان را در خراسان مشهور کرد و بر عدد تبعه ٔ سربداران افزود. امیر وجیه الدین مسعود و شیخ حسن جوری بعد از کشتن امیر علی کاون و مغلوب کردن لشکر جرجان به قصد طغاتیمورخان حرکت کردند و در لب آب اترک او را نیز مغلوب ساختند و طغاتیمورخان بطرف لار و رودبار قصران گریخت و خراسان و جرجان بکلی از تصرف او خارج شد. در سال <span class=\"hlight\" dir=\"rtl\">٧٤٩</span> شمس الدین فضل اﷲ سربدار به سلطنت رسید و پس از هفت ماه چون مردی درویش مسلک و گوشه گیر بود قریب به چهار هزار خروار ابریشم از خزانه ٔ سربداران برداشته خود را از سلطنت خلع نمود و چون شنید طغاتیمورخان مصمم انتقام کشیدن از سربداران است بکلی کناره جست .<br />پس از شمس الدین فضل اﷲ شمس الدین علی چشمی به پادشاهی نشست . وی به فراست و دانائی و کفایت اشتهار داشت .... با طغاتیمور صلح کرد و ولایاتی را که امیر مسعود از او گرفته بود به طغاتیمور مسترد داشت . در سال <span class=\"hlight\" dir=\"rtl\">٧٥٤</span> طغاتیمورخان خواجه یحیی کرابی را که بعد از شمس الدین علی چشمی به سلطنت برقرار شده بود به خدمت خود خواند واز او خواست که نسبت به پادشاه جرجان قبول ایلی کند، خواجه یحیی زیر بار نرفت و بعد از آنکه دو سه بار بین طرفین مکاتبه و تبادل سفرا شد خواجه یحیی با سیصد سوار به ملاقات طغاتیمورخان رفت و در ظاهر غرض او اطاعت و ایلی بود. در اردوی طغاتیمورخان او و خواجه یحیی به مذاکره ٔ مصالح خراسان مشغول شدند و چون همراه طغاتیمورخان چندان کسی نبود یکی از امرای خواجه یحیی تبری بر فرق طغاتیمور زد و خواجه یحیی سر او را از تن جدا ساخت . مؤلف حبیب السیر قاتل طغاتیمورخان را «حافظ شغانی » نام برده گوید: ناگاه حافظ شغانی تبری بر فرق پادشاه زد چنانچه به روی درافتاد، و خواجه یحیی سرش از تن جدا کرد. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span>). رابینو در سفرنامه ٔ خود به مازندران گوید: طغاتیمور حاکم استراباد، به دست یحیی کرابی به قتل رسید و علی بوالقلندر بجای وی به امر پهلوان حسن حاکم آن ولایت گردید. (سفرنامه ٔ رابینو ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span>). و سربداران در همراهان طغاتیمورخان افتاده ایشان را متفرق ساختند و روزگار سلطنت طغاتیمور در خراسان و جرجان به دست سربداران بدین شکل به انجام رسید. دوره ٔسلطنت و پادشاهی او فقط در حدود خراسان و جرجان از <span class=\"hlight\" dir=\"rtl\">٧٣٧</span> تا <span class=\"hlight\" dir=\"rtl\">٧٥٤</span> هفده سال امتداد داشت . رجوع به تاریخ مغول تألیف اقبال ص <span class=\"hlight\" dir=\"rtl\">٣٥٤</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>، <span class=\"hlight\" dir=\"rtl\">٣٦٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>، <span class=\"hlight\" dir=\"rtl\">٤٥٨</span>، <span class=\"hlight\" dir=\"rtl\">٤٦٨</span>، <span class=\"hlight\" dir=\"rtl\">٤٧٠</span>، <span class=\"hlight\" dir=\"rtl\">٤٧٣</span>، <span class=\"hlight\" dir=\"rtl\">٤٧٥</span>، <span class=\"hlight\" dir=\"rtl\">٤٧٧</span>، <span class=\"hlight\" dir=\"rtl\">٤٧٨</span> و حبیب السیر چ خیام فهرست ج <span class=\"hlight\" dir=\"rtl\">٣</span> و ذیل جامعالتواریخ رشیدی ص <span class=\"hlight\" dir=\"rtl\">١٥٥</span>، <span class=\"hlight\" dir=\"rtl\">١٥٦</span>، <span class=\"hlight\" dir=\"rtl\">١٥٩</span> - <span class=\"hlight\" dir=\"rtl\">١٦٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٤</span> و ترجمه ٔ تاریخ ادبیات ایران براون ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٧</span> و <span class=\"hlight\" dir=\"rtl\">٢٥٣</span>شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177082, 'طغاث', '<span class=\"hlight\">طغاث .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام یکی از نیاکان سامانیان . رجوع به احوال و اشعار رودکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٦</span> شود.<br /></font></div>'),
(177083, 'طغاجار', '<span class=\"hlight\">طغاجار.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) (امیر...) یکی از امرای مغول که از سال <span class=\"hlight\" dir=\"rtl\">٦٧٨</span> تا <span class=\"hlight\" dir=\"rtl\">٦٩٤</span> هَ . ق . پیوسته مرجع مهام امور بود. وی مردی ناسپاس بود وپیوسته با اولیاء نعمت خود خیانت میورزید و با دشمنان آنها سازش میکرد و بسا که بر اثر سازش با دشمنان اولیاء نعم خویش آنان را فانی و معدوم میساخت . در <span class=\"hlight\" dir=\"rtl\">٦٧٨</span> از جانب آباقا مأموریت یافت که با سیدعمادالدین به شیراز رفته به حساب عمال سوغنجاق رسیده مالی را که سیدعمادالدین بر عهده گرفته بود وصول کند. طغاجار ونایب او صدرالدین احمد خالدی زنجانی به همراهی سیدعمادالدین به شیراز آمدند و به کشیدن حساب عمال فارس مخصوصاً نظام الدین پرداختند و در نتیجه ٔ انواع سختگیریها مالی فراوان گرد آوردند و چون خبر مرگ آباقا و جلوس سلطان احمد رسید، طغاجار و سیدعمادالدین وجوه حاصله را برداشته به اردو شتافتند. شهاب الدین عبداﷲ وصاف الحضرة مؤلف تاریخ وصاف، یکی از خواص خواجه صدرالدین احمد خالدی زنجانی نایب طغاجار در فارس بشمار میرفت و وی را در حق این خواجه که به وزارت کیخاتون هم رسید اشعار و مدایح بسیار است . (تاریخ مغول اقبال ص <span class=\"hlight\" dir=\"rtl\">٣٩٣</span> و <span class=\"hlight\" dir=\"rtl\">٤٨٧</span>). در <span class=\"hlight\" dir=\"rtl\">٦٨١</span> هنگامی که فیمابین ارغون و سلطان احمد تکودار تولید اختلاف شد، ارغون جماعتی از قراولان مغولی آباقا را تحت امر خود آورد و طغاجار را به فرماندهی آنان برگماشت . (تاریخ مغول اقبال ص <span class=\"hlight\" dir=\"rtl\">٢٢٥</span>). در این مورد صاحب حبیب السیر گوید: ارغون پسر آباقا طغاجار نویان را منظور نظر عاطفت تربیت گردانید و لشکر فراوتاس را که بی باکترین اقوام مغول بودند تابین او کرد. (حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span>). در <span class=\"hlight\" dir=\"rtl\">٦٨٢</span> سلطان احمد امر داد که عساکر مقیم حدود دیاربکر سران سپاهی ارغون را که در حوالی بغداد مقیمند دستگیر ساخته و ایشان را که امیر طغاجار نیز از آن جمله بود در بند آهنین مقید کردند. بعد از قتل سلطان احمد خواتین و شاهزادگان و امرای مغول مخصوصاً اولجای خاتون و طغاجار وبوقا شاهزاده ٔ ارغون بن اباقا را در <span class=\"hlight\" dir=\"rtl\">١٧</span> جمادی الاولی سال <span class=\"hlight\" dir=\"rtl\">٦٨٣</span> در آبشور محال هشترود تبریز به ایلخانی برداشتند. در این اثنا ارغون را مرضی عارض شد که به همان مرض وفات یافت . سعدالدوله دانست که اگر ارغون از بین برود مدافعی نخواهد داشت، به احضار غازان از خراسان فرمان داد. امراء مخالف سعدالدوله نیز در خانه ٔ طغاجار مجلسی تشکیل داده متفقاً تصمیم گرفته و رأی دادند که جمیع فتنه جویان را بکشند و به همین نیت آن جمعرا کشتند و سعدالدوله را نیز در سلخ صفر <span class=\"hlight\" dir=\"rtl\">٦٩٠</span> در خانه ٔ طغاجار به قتل رسانیدند. بعد از فوت ارغون اکثر امرا کیخاتو را ایلخان کردند ولی طغاجار و سایر امراءدر صدد بودند که بایدو بدین سمت انتخاب شود. کیخاتودر چهارم رمضان <span class=\"hlight\" dir=\"rtl\">٦٩٠</span> برای نشاندن فتنه ٔ ترکمانان و یونانیان بر علیه لشکریان مغول به روم رفت، و پس از ده ماه با فتح و پیروزی بازگشت و امیر اق بوقا را امیرالامرائی داد و امر کرد سنکتور و طغاجار تحت فرمان اوباشند. در <span class=\"hlight\" dir=\"rtl\">٦٩٣</span> که به امر کیخاتو معامله با زر و سیم ممنوع و بجای آن چاو معمول گردید طغاجار مأموریت یافت که به تبریز رفته چاو را در آن شهر رواج دهد. کیخاتو در دوره ٔ سلطنت کوتاه خود بر اثر تعرض به عرض وناموس مردم همه را از خود رنجانده بود، از طرف دیگرشبی در حال مستی بر بایدو بتندی خشم راند، بایدو هرچند در ظاهر اظهار کدورت و دلتنگی نکرد، ولی در باطن با امراء هم عهد شد که سال دیگر که به اردوی ایلخان می آید به دستیاری امرا کار کیخاتو را بسازد. کیخاتو از این تصمیم مطلع و اغلب امرا را دستگیر و رأی به قتل آنها داد ولی طغاجار که باطناً با همان امرا هم قول شده بود کیخاتو را از قتل آنان منصرف و راضی ساخت که آنها را به زندان بفرستد و قرار شد که کیخاتو بایدو را احضار کند و با حضور او پس از تحقیق بدخواهان را به یاسا رساند. طغاجار که خود مأمور محافظ امراء زندانی بود پنهانی رسولی نزد بایدو فرستاد که با قشون خویش بطرف اردو حرکت کند تا پس از ورود او به اتفاق امراء محبوس یکجا کار کیخاتو را انجام دهد. چون خبر حرکت بایدو به کیخاتو رسید لشکری به تعداد <span class=\"hlight\" dir=\"rtl\">٢٥</span> هزار تن فراهم آورد، پنجهزار تن از آنان را برسم مقدمةالجیش از راه همدان و بیستهزار تن دیگر به سرداری اقبوقا و طغاجار در عقب آن عده فرستاد و ایلخان خود درسوم جمادی الاولی سال <span class=\"hlight\" dir=\"rtl\">٦٩٤</span> از آلاتاغ به تبریز آمد. مقدمةالجیش لشکریان ایلخان با قشون بایدو جنگیدند و مقداری از ایشان را کشته، در انتظار کمک توقف کردند، اما لشکریان طغاجار علم طغیان برافراشته و طغاجار هم علناً خود را حامی بایدو خواند و از امر آقبوقا سر پیچید، لشکریان آقبوقا هم جانب او را گرفتند و آقبوقا با چند تن از موافقان پیش ایلخان گریخت . چون این خبرمنتشر شد، لشکریان از دور کیخاتو متفرق و امرای محبوس به امر طغاجار آزاد گشتند و کیخاتو به موغان گریخت و در آنجا به دست امرای یاغی گرفتار و روز پنجشنبه ششم جمادی الاولی سال <span class=\"hlight\" dir=\"rtl\">٦٩٤</span> به قتل رسید. بعد از قتل کیخاتو، امیر طغاجار و امرای دیگر بایدو را به ایلخانی برگزیدند، امیر طغاجار به سمت امیرالامرائی و تعهد امور لشکری برقرار شد و بعلاوه بایدو خواست مانند عهد آباقا هر یک از ممالک را به امیری و شاهزاده ای بسپارد، از آن جمله بلاد روم را هم به طغاجار سپرد. غازان خان که در خراسان بود چون خبر قتل کیخاتو بشنید و اوضاع کشور بایدو را پریشان دید، به اندیشه ٔ مصاف با بایدو افتاد و از جانب خراسان به دامغان حرکت کرد. بایدو در هشترود تبریز خبر حرکت غازان را شنید، چاره جزآن ندید که طغاجار را با عده ای دیگر از امرا با اردو برای جلوگیری غازان بفرستد. اردوی طرفین پنجشنبه ٔ پنجم رجب سال <span class=\"hlight\" dir=\"rtl\">٦٩٤</span> در نواحی قربان شیره نزدیکی رودخانه ٔ شیرگیران (در سرچشمه ٔ رود قزل اوزن جزء ولایت مراغه )با یکدیگر مقابله کردند، چون بایدو آثار شکست در جبهه ٔ سران سپاه خود دید برای صلح حاضر شد، غازان پیشنهاد او را پذیرفت ... در آن هنگام که غازان با بایدو شرایط صلح را تنظیم کرد بدون اجازه ٔ بایدو بازگشت و امیر نوروز را از جانب خود با جمعی دیگر از سران سپاه جهت دریافت فرمان حکومت عراق و فارس (از جمله شرایط صلح ) در اردوی بایدو گذاشت . امیر نوروز و امرای دیگر غازانی با امیر طغاجار که امتحانات بسیار بد از بدعهدی خود نسبت به مخدومین خویش داده بود در خفیه بایکدیگر ساختند که بساط سلطنت بایدو را برچینند و به خدمتگذاری غازان و رساندن او به سلطنت کمر همت ببندند. طغاجار به آسانی این تکلیف بپذیرفت . امیر نوروز که بر حسب امر بایدو جرات بازگشت نزد غازان را نداشت نزد بایدو قسم یاد کرد که اگر ایلخان او را رخصت مراجعت دهد غازان را دست بسته به خدمت او بیاورد. بایدوپذیرفت و امیر نوروز نجات یافته، بسرعت خود را نزد غازان و شرح واقعه و مواضعه ٔ خود را با طغاجار به اطلاع او رسانید. در اواخر سال <span class=\"hlight\" dir=\"rtl\">٦٩٤</span> غازان اطلاع یافت که مأمورین فارس با وجود حکم بایدو از پرداخت عایدات به نمایندگان او سر پیچیده اند. این واقعه غضب او را تحریک کرد و تصمیم گرفت که به آذربایجان یورش برد. دراین اثنا خواجه صدرالدین زنجانی هم که بایدو او را از صدارت خلع و مقام او را به خواجه جمال الدین دستجردانی داده و به نیابت طغاجار مأمور بلاد روم کرده بود از این پیش آمد خشمناک و پیوسته مترصد انتقام بود، چون احوال ایلخان را مختل و دل مخدوم خود طغاجار را به غازان متمایل دید با طغاجار برای مساعدت با غازان دست یکی کرد، محرمانه به غازان پیغام فرستاد که اگرغازان به آذربایجان حرکت کند غالب امرای مقتدر جانب او را خواهند گرفت و کار بایدو را یک طرفی خواهند ساخت و خود نیز در هفتم شوال <span class=\"hlight\" dir=\"rtl\">٦٩٤</span> در گیلان به اردوی غازان پیوست و پس از آنکه غازان به او وعده ٔ صدارت داد امیر نوروز را با عده ای سپاهی برداشته بعنوان مقدمه ٔقشون غازانی در جمعه <span class=\"hlight\" dir=\"rtl\">١٥</span> شوال عازم آذربایجان شدند، و غازان نیز در عقب ایشان حرکت کرد. با رسیدن امیر نوروز طغاجار و باقی امرای بایدو که باطناً به غازان گرویده بودند از ایلخان رو گرداندند. بایدو چون از این واقعه خبر یافت از کنار قزل اوزن که محل اردوی او بود به اوجان و مرند و از آنجا بطرف گرجستان گریخت ولی امیر نوروز سرعت به خرج داد بایدو را نزدیکی نخجوان گرفت و او را پیش غازان که در آن ایام در اوجان بود برد و غازان بایدو را در <span class=\"hlight\" dir=\"rtl\">٢٣</span> ذی القعده ٔ سال <span class=\"hlight\" dir=\"rtl\">٦٩٤</span> به قتل رسانید. غازان در آغاز سلطنت خود به قراباغ (اران ) رفت و در آنجا قوریلتائی تشکیل داد و رسماً به سلطنت جلوس کرد و در همین قوریلتای در مناصب امرا تغییراتی داده از آن جمله کمی بعد طغاجار نویان را هم برای دور داشتن از اردو و جلوگیری از دخالتهای احتمالی او به سرداری اردوی مقیم بلاد روم فرستاد و چندی بعد یک نفر ایلچی بدنبال او فرستاد و امر داد او را کشتند. رجوع به فهرست حبیب السیر چ خیام و ترجمه ٔ تاریخ ادبیات ایران براون ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span> و تاریخ مغول اقبال ص <span class=\"hlight\" dir=\"rtl\">٢٢٥</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٧</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٥</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٥١</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٥</span>، <span class=\"hlight\" dir=\"rtl\">٢٥٧</span>، <span class=\"hlight\" dir=\"rtl\">٢٦١</span> و فهرست تاریخ گزیده شود.<br /></font></div>'),
(177084, 'طغاجر', '<span class=\"hlight\">طغاجر.</span> <font color=\"DarkGreen\"><b>[ طُ ج َ ]</font></b> (اِخ ) صورتی از طوغاجار نویان است . رجوع به ترجمه ٔتاریخ ادبیات ایران براون ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨</span> و طغاجار شود.<br /></font></div>'),
(177085, 'طغاخان', '<span class=\"hlight\">طغاخان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) یکی از امراء ترکستان به روزگارمحمود غزنوی . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٨٥</span>). در تعلیقات آخر تاریخ بیهقی چ فیاض ص <span class=\"hlight\" dir=\"rtl\">٦٩٥</span> آمده است : این شخص برادر علی تگین است که در ص <span class=\"hlight\" dir=\"rtl\">٥٢٦</span> <font color=\"DarkGreen\"><b>[ در چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٥٣٦</span> ]</font></b> طغان با نون آمده است . حذف نون آخر در مورد بعضی اسمهای ترکی در سکه ها دیده میشود، مثل یغان که در سکه ها یغاست . (ترکستان بارتلد ص <span class=\"hlight\" dir=\"rtl\">٢٨٤</span>). رجوع به تعلیقات بر تاریخ بیهقی چ فیاض ص <span class=\"hlight\" dir=\"rtl\">٦٩٥</span> و رجوع به طغان بن علی شود.<br /></font></div>'),
(177086, 'طغاخان', '<span class=\"hlight\">طغاخان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) نام یکی از امراء و فرماندهان لشکر هنددر عصر محمود نبیره ٔ فیروزشاه از سلسله ٔ تغلقیه . (طبقات سلاطین اسلام لین پول ص <span class=\"hlight\" dir=\"rtl\">٢٦٩</span>). وی با امیر تیمور گورکان مصاف داد و در آن مصاف میسره ٔ لشکر هند با طغاخان و میر علی موجه ای بود و پس از مقابله ٔ دو لشکر امیرزاده پیرمحمد از برانغار لشکر تیموری بر جرانغار مخالفان تاخته شمشیر به فیل سواری طغای خان رسانید، و وی را که در برابرش بود منهزم گردانید، تقریباً در حدود سال <span class=\"hlight\" dir=\"rtl\">٧٩٥</span> هَ . ق . (حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٤</span>).<br /></font></div>'),
(177087, 'طغاخان', '<span class=\"hlight\">طغاخان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) (... مرغینان ) پدرزن پیغوملک والی مرغینان و کاشان از بلاد مشهور فرغانه . وی در مدح طغاخان پدرزن خویش قصیده ای دارد که در لباب الالباب عوفی ج <span class=\"hlight\" dir=\"rtl\">١</span> (باب پنجم ) چند بیتی از آن درج و مصدَّر بدین بیت است :<br />فرمان نافذ او بر حکمها دلیل <br />دست تصرف او بر ملکها دراز.<br /><font color=\"Red\">(لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٥</span>).</font><br /></font></div>'),
(177088, 'طغار', '<span class=\"hlight\">طغار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) تغار. طشت گِلین <span class=\"hlight\">:</span> گل و شکر به طشتی یا لاکی چوبین یاطغاری سفالین در کنند، یک تو گل، یک تو شکر <font color=\"DarkGreen\"><b>[ در ساختن گلشکر ]</font></b>. (ذخیره ٔ خوارزمشاهی ). تا شما را از غرقاب هلاکت و طغار خون بیرون کشم . (جهانگشای جوینی ). و مؤمنان را چون شتران ماهار زده، ده ده و بیست بیست دریک رسن قطار میکردند، و در طغار خون می انداخت، تا زیادت از صد هزار را شهید کردند. (جهانگشای جوینی ).<br /></font></div>'),
(177089, 'طغام', '<span class=\"hlight\">طغام .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) ناکس و فرومایه از مردم . (منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span> روزی رندی با طعام طغام و اوباش مشغول بود. (جهانگشای جوینی ). <BR><font color=\"Blue\">◄</font> هیچکاره . (منتهی الارب ) (آنندراج ). فرومایگان . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> فرومایه از مرغان . (منتهی الارب ) (آنندراج ). مرغان زبون . (منتخب اللغات ). طغامة یکی . مذکر و مؤنث و واحد و جمع در آن یکسان است . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177090, 'طغامی', '<span class=\"hlight\">طغامی .</span> <font color=\"DarkGreen\"><b>[ طَ ما ]</font></b> (اِخ ) قریه ای است از سواد بخارا. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(177091, 'طغان', '<span class=\"hlight\">طغان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (از ع، اِمص ) مخفف طغیان آمده . (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(177092, 'طغان', '<span class=\"hlight\">طغان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ترکی، اِ) طوغان . نوعی از باز. ارکک .<br /></font></div>'),
(177093, 'طغان', '<span class=\"hlight\">طغان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) نام یکی از پادشاهان ترک . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br />خوش نخسبند همه از فزعش زانسوی آب <br />نه قدرخان نه طغان خان نه ختاخان نه تکین .<br /> <font color=\"Red\">فرخی .</font><br />و رسولان طغان خان ملک ترک حاضر بودندو همه اقرار کردند که آن جنس در حوصله ٔ ظنون نگنجد و خزانه ٔ قارون به عشر آن نرسد <font color=\"DarkGreen\"><b>[ منظور نفائس ذخایری است که از قلعه ٔ بهیم ثغر هند مفتوح به دست سلطان محمود به غنیمت آورده بودند ]</font></b> . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٠٥</span>). و طغان خان میلی به جانب سلطان میکرد. (ترجمه ٔتاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٣١</span>).<br /></font></div>'),
(177094, 'طغان', '<span class=\"hlight\">طغان .</span> <font color=\"DarkGreen\"><b>[ طُ]</font></b> (اِخ ) از امرای ابقا (اباقاخان پسر هلاکو) که در سال <span class=\"hlight\" dir=\"rtl\">٦٧٥</span> هَ . ق . با تنی چند از امرای دیگر به سیستان لشکر کشید. رجوع به تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٤٠٥</span> و <span class=\"hlight\" dir=\"rtl\">٤٠٦</span> شود.<br /></font></div>'),
(177095, 'طغان', '<span class=\"hlight\">طغان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) مؤلف ترجمه ٔ تاریخ یمینی آرد: طغان نامی والی بست بود، و دیگری بایتوزنام این ولایت بقهر از دست او بیرون کرد و طغان طاقت مقاومت او نداشت، ناچار آن ناحیه بازگذاشت، و در کنف اهتمام و حمایت ناصرالدین گریخت و از او مدد خواست تا ولایت خویش از دست خصم بیرون آرد، و خدمتها پذیرفت، و قدری معین را ملتزم شد که هر سال بر طریق حمل به خزانه ٔ او فرستد، و به هر وقت که حاجت افتد، در زمره ٔ اعوان و انصار او مستحضر باشد، و به مراسم خدمات قیام نماید، و فرزندی بنوا در خدمت ناصرالدین مقیم دارد. از آنجا که اریحیت طبع و کرم نهاد آن پادشاه بود، این دعوت را اجابت کرد، و به اسعاف طلب و انجاح حاجت او زبان داد، و با لشکری تمام به ظاهر بست نزول نمود، و از جانبین در آن محاربت جد بلیغ نمودند، و امیر ناصرالدین از قلب لشکر خویش حمله کرد، خصم را در مضایق محلهای شهر ریخت و خلقی بسیار از ایشان به زخم شمشیر آورد، و دیگران به هزیمت شدند، و طغان با مقر ملک خویش رسید، و به زبان شکر ایادی و حسن اضطلاع و یمن اصطناع ناصرالدین میگفت، و در وعده ای که داده بود و خدمتی که پذیرفته بود، مدافعت و مماطلت میداد، و اندیشه ٔ نقض عهد و خلاف وعد میکرد، تا دلائل غدر و مخایل خدیعت و مکر او ظاهر گشت، و روزی که بر صحرا مجتمع بودند، ناصرالدین او را تقاضای سخت کرد و او جوابی نالایق داد، و آن مقاولت به مجادلت کشید، و بدان رسید که طغان دست به شمشیر کرد، و دست ناصرالدین را مجروح گردانید، و چون ناصرالدین آن بیحفاظی مشاهدت کرد، دست زخم رسیده به شمشیر یازید و طغان را زخمی عظیم زد و خواست تا دیگر بار زخمی زند، لشکر در هم افتادند، و غلبه و ازدحام فریقین مانع شد و ناصرالدین بفرمود تا اتباع و حشم او از آن خطه بیرون کردند، و آن عرصه را از خبث و فساد آن غداران پاک گردانید، و در مقدار یک ساعت از روز، آن نواحی مستخلص شد، و طغان و بایتوز به ناحیت کرمان فتادند، و دیگر در خواب خیال آن نواحی ندیدند و اندیشه ٔ آن اعمال در خاطر نگذرانیدند. (ترجمه ٔ تاریخ یمینی صص <span class=\"hlight\" dir=\"rtl\">٢٧</span>-<span class=\"hlight\" dir=\"rtl\">٢٩</span>). و رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٢</span> و تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٠٨</span>، <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٣٣</span> شود.<br /></font></div>'),
(177096, 'طغان', '<span class=\"hlight\">طغان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) (امیر...) یکی از امراء مغول که بسال <span class=\"hlight\" dir=\"rtl\">٧١١</span> هَ .ق . از جانب سلطان محمد خدابنده برای سرکوبی گیلانیان مأموریت یافت . (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٤</span>). و نیز رجوع به ذیل جامعالتواریخ رشیدی ص <span class=\"hlight\" dir=\"rtl\">١١</span>، <span class=\"hlight\" dir=\"rtl\">١٤</span>، <span class=\"hlight\" dir=\"rtl\">٥٣</span> شود.<br /></font></div>'),
(177097, 'طغان', '<span class=\"hlight\">طغان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ )جبال طغان . رجوع به نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٢٢٧</span> شود.<br /></font></div>'),
(177098, 'طغان', '<span class=\"hlight\">طغان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) یکی از دهات توابع بارفروش «بابل ». (سفرنامه ٔ رابینو چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١١٨</span>). و در فرهنگ جغرافیایی ایران آمده است : دهی از دهستان لاله آباد بخش مرکزی شهرستان بابل در <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی باختر بابل . دشت و معتدل و مرطوب و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٢٠٥</span> تن سکنه . آب آن از رودخانه ٔ کاری، محصول آنجا برنج و مختصر غلات و پنبه و صیفی و کنف . شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(177099, 'طغان', '<span class=\"hlight\">طغان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) دهی جزء دهستان بهنام عرب بخش ورامین شهرستان تهران در <span class=\"hlight\" dir=\"rtl\">٧٤٠٠٠</span>گزی جنوب خاوری ورامین و <span class=\"hlight\" dir=\"rtl\">٣٠٠٠</span>گزی جوادآباد. جلگه و معتدل و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٤٤٧</span> تن سکنه . آب آن از قنات و شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(177100, 'طغان', '<span class=\"hlight\">طغان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) دهی از دهستان ماروسک بخش سرولایت شهرستان نیشابور در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی جنوب خاوری چکنه ٔ بالا. کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">١٠٢</span> تن سکنه . آب آن از قنات و محصول آنجا غلات و تریاک و شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(177101, 'طغان', '<span class=\"hlight\">طغان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) ابن علی . وی چهارمین تن ازسلسله ٔ ملوک ایلکخانیه ٔ ترکستان بوده و شرف الدوله لقب داشته و از سال <span class=\"hlight\" dir=\"rtl\">٤٠٣</span> تا <span class=\"hlight\" dir=\"rtl\">٤٠٨</span> هَ . ق . فرمانروائی کرده است . (طبقات سلاطین اسلام لین پول ص <span class=\"hlight\" dir=\"rtl\">١٢١</span>). مورخان وی را بنام طغان خان در تواریخ نام میبرند. وی برادر ایلک خان است که در <span class=\"hlight\" dir=\"rtl\">٤٠٣</span> هَ . ق . بدرود زندگانی کرد، و پس از وی طغان خان قائم مقام او گشت . (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٨</span>). علامه ٔ فقید، مرحوم میرزا محمدخان قزوینی در چهارمقاله ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span> بنقل از کلمان هوارت مینویسد که نام اسلامی طغان خان، احمدبن علی بن موسی بن ستق بوده، وایلک خان برادر وی نیز نصر نام داشته . در ترجمه ٔ تاریخ یمینی آورده که : از جانب چین <font color=\"DarkGreen\"><b>[ ترکستان شرقی ]</font></b> لشکری با صد هزار خرگاه به مخاصمت او <font color=\"DarkGreen\"><b>[ طغانخان ]</font></b> و قصد بلاد اسلام بیرون آمدند که در مدت عهد اسلام کس چنان کثرت در روی زمین نشان نداده بود، بر عزم اطفاء نور اسلام و اِعلاء قصور اصنام، و ندانستند که تأیید دین محمدی، رایت گردن هر طاغی نگونسار کند، و سر هر یاغی به خاک اندازد. طغان خان از بهر مدافعت ایشان از اطراف ممالک اسلام لشکر خواند، و انصار دین و مطوعه ٔ اسلام صد هزار مرد جمع کرد، و در دل اهل اسلام از آن ندای هائل و بنای مائل، روعی عظیم حادث شد، و امداد التیاع و ارتیاع در ضمائر متمکن گشت، و اهل صلاح در مساجدو معابد دستها به دعا برداشتند، و همتها برگماشتند، و طغان خان به مجاهدت آن جمع روان شد، و دل بر استقبال اجل قرار داد، و نیت بر ادراک درجه ٔ شهادت مقصور گردانید، بر امید وعده ٔ باریتعالی در نصرت دین و اِعلای کلمه ٔ یقین، چنانچه نص ّ قرآن مجید بدان وارد است :انا لننصر رسلنا و الذین آمنوا فی الحیوة الدنیا، و چند روز... نائره ٔ حرب فیمابین دو لشکر بسختی در اشتعال بود. اما از آنجا که باریتعالی بندگان مخلص خویش را در حرز امان میگرفت، و به تمکین و اید متین تأیید میداد، و کلمه ٔ نجوم دین و رجوم شیاطین کلمه ٔ علیا میگردانید، تا یک روز آتش حرب بالا گرفت، و بهرام نطاق بگشاد، و دور دوستگانی طعن و ضرب در میان فریقین بداد، و اولیای دین در شکر باریتعالی و طرب طلب زلفت و انتشاق نسیم جنت و اشتیاق به لقای منازل رحمت، چون فحول هایج و بحور مایج، از وقت لمعه ٔ فلق تا وقت مسقط شفق، با طلائع مرگ به بازی درآمدند، و با ملأ اعلی به نیازی هرچه تمامترهمرازی کردند، لاجرم از حضرت قدس مدد توفیق برسید، واز مهب لطف نسیم نصرت بوزید، و قرب صد هزار مرده ٔ کفار بر فضای آن مصاف بر زمین انداختند، سرها وداع تن کرده و جانها به عتاب قالب طالب مفارقت شده، و غراب تیغها از جیفه ٔ کفار غذای تمام یافتند، و ضباع و سباع از خصب آن مراتع به فراخی رسیده، و قرب صد هزار برده از ذراری و جواری ایشان که در حسن با ماه برابری میکردند، و در نور از لؤلؤ منثور گرو میبردند، به دست اهل اسلام افتاد، و از مواشی و غنائم اغنام ایشان چندان حاصل شد که در فضای صحرا و اقطار بیدا نمیگنجید، و بقایای آن مدابیر برمیدند و راه هزیمت گرفتند. بشارت این فتح عظیم و نجح جسیم، به جملگی دیار اسلام برسید، و دلها بدان بیارامید، جانها بیاسود، و زبانها به شکر باریتعالی روان شد. و بر عقب این فتح، طغان خان را عمر به آخر رسید، و روح او در جمله ٔ ارواح شهدا به جنةالمأوی تحویل کرد، و ملک او بر برادر وی که در تقوی و مراقبت جانب الهی و اهتمام به امور دینی، موافق سیرت و مطابق سریرت او بود قرار گرفت . (دراین مورد در حاشیه نوشته : و ورث مکانه اخوه ارسلانخان، ابومنصور الاصم . و ظاهراً عین عبارت عتبی است که از تاریخ یمینی نقل کرده است ). (ترجمه ٔ تاریخ یمینی صص <span class=\"hlight\" dir=\"rtl\">٣٩٢</span>-<span class=\"hlight\" dir=\"rtl\">٣٩٥</span>). و رجوع به طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span> شود.<br /></font></div>'),
(177102, 'طغان تیمور', '<span class=\"hlight\">طغان تیمور.</span> <font color=\"DarkGreen\"><b>[ طُ ت َ ]</font></b> (اِخ ) یازدهمین از سلسله ٔ یوئن . از سال <span class=\"hlight\" dir=\"rtl\">٧٣٢</span> تا <span class=\"hlight\" dir=\"rtl\">٧٧١</span> هَ . ق . سلطنت کرده است . رجوع به تاریخ طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">١٩١</span> شود.<br /></font></div>'),
(177103, 'طغان حاجب', '<span class=\"hlight\">طغان حاجب .</span> <font color=\"DarkGreen\"><b>[ طُ ن ِ ج ِ ]</font></b> (اِخ ) یکی از امرای عصر امیر نوح سامانی که بفرمان امیر مزبور وی را کشتند. (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦١</span>). و رجوع به تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٠٣</span> شود.<br /></font></div>'),
(177104, 'طغان خان', '<span class=\"hlight\">طغان خان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) حاکم لکنوتی که سلطان مسعود از سلاطین سلسله ٔ مملوک بسال <span class=\"hlight\" dir=\"rtl\">٦٤١</span> هَ . ق . وی را از حکومت لکنوتی برکنار کرد و قرابیک تیمورخان را بجای او به حکومت برقرار داشت . (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢٣</span>).<br /></font></div>'),
(177105, 'طغان خان', '<span class=\"hlight\">طغان خان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) رجوع به عزالدین طغرل طغانخان هشتمین سلطان از سلاطین بنگاله شود. (طبقات سلاطین اسلام لین پول ص <span class=\"hlight\" dir=\"rtl\">٢٧٥</span>).<br /></font></div>'),
(177106, 'طغان خان', '<span class=\"hlight\">طغان خان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) حاکم فرغانه بوده است . رجوع به جهانگشای جوینی چ اوقاف گیب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span> شود.<br /></font></div>'),
(177107, 'طغان شاه', '<span class=\"hlight\">طغان شاه .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) نام پادشاه عظیم القدر از اولاد افراسیاب . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br />شه طغان عقل را نائب منم نِعْم َ الوکیل <br />نوعروس فضل را صاحب منم نِعْم َ الفتی .<br /><font color=\"Red\">خاقانی .</font><br />بل نائبان یاوگیان ولایتند<br />زیرا که شه طغان جهان سخن نیند.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(177108, 'طغان شاه', '<span class=\"hlight\">طغان شاه .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) پدر پهلوان اسد نامی است که در عصر پنجمین پادشاه از آل مظفر، شاه شجاع، به دست وی به حکومت کرمان برقرار گردید، تقریباً در حدود سال <span class=\"hlight\" dir=\"rtl\">٧٧٥</span> هَ . ق . (تاریخ مغول اقبال ص <span class=\"hlight\" dir=\"rtl\">٤٣١</span>).<br /></font></div>'),
(177109, 'طغان شاه', '<span class=\"hlight\">طغان شاه .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) ابن الب ارسلان محمدبن جغری بیک بن میکائیل . لقب وی شمس الدوله و کنیتش ابوالفوارس است . به روزگار الب ارسلان حکومت خراسان داشت، و مستقر وی هرات بود. ازرقی از مداحان اوست، و او غیر از طغانشاه بن مؤید آی ابه است که پس از سلطان سنجر بر خراسان استیلا یافت . و طغرل بیک، عم ّ پدر طغانشاه بن الب ارسلان است . علامه ٔ مرحوم میرزا محمدخان قزوینی در حواشی چهارمقاله مینویسد: ازرقی از مداحان خاص وی بود، و در قصاید خود تصریح به اسم و لقب و نسب و مقر حکومت وی میکند، از جمله در قصیده ای گوید:<br />آسمان داد و همت، آفتاب تاج و تخت <br />نور جان میر چغری، شمع شاه الب ارسلان <br />مفخر سلجوقیان سیف امیرالمؤمنین <br />شمس دولت، زین ملت، کهف امت، شه طغان .<br />در جای دیگر گوید:<br />گزیده شمس دول، شهریار و زین ملل <br />ستوده کهف امم، پادشاه خوب خصال <br />طغانشه بن محمد که خواندش گردون <br />خدایگان عجم، آسمان جود و جلال .<br />در قصیده ای دیگر گوید:<br />ابوالفوارس، خسرو طغانشه، آن ملکی <br />که آسمان فخار است و آفتاب هنر<br />چو رایت تو بجنبد شها ز قلب سپاه <br />ز بیم زرد شود در کف یلان خنجر<br />به غره مریخ اندر فلک همی گوید<br />زِه ای طغانشه الب ارسلان شیرشکر.<br />اما در اینکه پای تخت اوهرات بوده، در همین قصیده گوید:<br />هری که حضرت شاه تو بود چونان بود<br />کزو زنند مثل زیب را به هر محضر.<br />دیگر در قصیده ای که مطلعش این است :<br />خوش و نکوز پی هم رسید عید و بهار<br />بسی نکوتر و خوشتر ز پار وز پیرار<br />یکی ز جشن عجم جشن خسرو افریدون <br />یکی زدین عرب دین احمد مختار<br />در مدیحه گوید:<br />حدیث میر خراسان و قصه ٔ توزیع<br />بگفت رودکی از روی فخر در اشعار<br />بدانچه داده بُد اورا هزار دیناری <br />به ناوجوب بهم کرده از صغار و کبار<br />تو در هری به شبی خسروا ببخشیدی <br />زر مدور صافی دو بار بیست هزار.<br />و عجب این است که این طغانشاه بکلی مجهول الحال است و احدی از مورخین (بجز مصنف در اینجا) ذکری از او نکرده است و فقط بواسطه ٔ اشعار ازرقی است که نام او بر السنه و افواه افتاده است، وبه همین جهت یعنی بواسطه ٔ اغفال مورخین، هیچیک از ارباب تذکره بطور تحقیق نشناخته اند که او که بوده و سهوهای غریب درباره ٔ او کرده اند، بسیاری از ایشان از جمله مجمعالفصحاء او را با طغانشاه بن مؤید آی آبه (سنه ٔ <span class=\"hlight\" dir=\"rtl\">٥٦٩</span> - <span class=\"hlight\" dir=\"rtl\">٥٨١</span> هَ . ق .) که بعد از سلطان سنجر بر خراسان استیلا یافت یکی فرض کرده اند، و آن سهو واضح است، اولاً بدلیل تصریح ازرقی در اشعار خود به اسم و نسبت او، و همچنین تصریح نظامی عروضی در اینجا (چ براون ص <span class=\"hlight\" dir=\"rtl\">٤٣</span> س <span class=\"hlight\" dir=\"rtl\">١٩</span>)، ثانیاً معرفی در لباب الالباب که گوید: ازرقی به مدت سابق بر معزی بوده است، و وفات معزی در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٥٤٢</span> هَ . ق . است، پس محال است که ازرقی زمان طغان شاه بن مؤید آی آبه را که در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٥٦٩</span> جلوس نمود دریافته باشد. ثالثاً یکی از ممدوحین ازرقی امیرانشاه بن قاوردبن جغری بیک بن میکائیل بن سلجوق، از شاهزادگان سلجوقیه ٔ کرمان است، و وفات امیرانشاه قبل از سنه ٔ <span class=\"hlight\" dir=\"rtl\">٤٧٧</span> واقع شده است، پس چگونه ممکن است ازرقی که معاصر امیرانشاه بوده، عصر طغانشاه را که در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٥٦٩</span> (یعنی بعد از <span class=\"hlight\" dir=\"rtl\">٩٢</span> سال دیگر) جلوس نموده درک کرده باشد. دولتشاه سمرقندی در تذکرةالشعراء، و امین احمد رازی در تذکره ٔ هفت اقلیم، و حاجی خلیفه در کشف الظنون در تحت «الفیّه » گفته اند که در خاندان سلجوق، دو طغانشاه بوده اند، یکی طغانشاه بن مؤید، و یکی طغانشاه قدیم، ممدوح ازرقی که طغرل بیک خال او بود، و مقر سلطنت او نیشابور بوده است، و تمام این فقرات کلمه به کلمه خطاست، زیرا که طغانشاه بن مؤید آی آبه از خاندان سلجوق نیست، و طغرل بیک عم پدر طغانشاه بن الب ارسلان است نه خال او، و نیشابور مقر سلطنت طغانشاه بن مؤید بوده است نه طغانشاه بن الب ارسلان و مقر حکومت این اخیر هرات بوده است نه نیشابور. واﷲ الهادی الی الصواب . (حواشی چهارمقاله چ براون صص <span class=\"hlight\" dir=\"rtl\">١٧٠</span>-<span class=\"hlight\" dir=\"rtl\">١٧٣</span>).<br />عوفی در لباب الالباب آورده که : ازرقی از مخصوصان حضرت شمس الدولة و الدین طغانشاه بود... و شمس الدولة از ملوک آل سلجوق در علم و حیاو وقار و وفا مستثنی بوده است . (لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٧</span>). و ممدوح او <font color=\"DarkGreen\"><b>[ ازرقی ]</font></b> شمس الدوله طغانشاه بن محمد السلجوقی، باغی بهشت ساحت اردیبهشت راحت ساخت و قصری رفیعنهاد بدیع نهاد، و او را در صفت آن باغ، چند قصیده ٔ غرّاست . آن روزگار که شاه بدان عمارت و سرای نقل کرد، این قصیده بخواند:<br />به فال همایون و فرخنده اختر<br />به بخت موفی و سعد موفر<br />به وقتی که هست اندر او فال خوبی <br />به روزی که هست اندر او سعد اکبر<br />به بزم نو اندر سرای نوآمد<br />خداوند فرزانه شاه مظفر<br />سخی شمس دولت، گزین کهف ملت <br />ملک بوالفوارس، طغانشاه صفدر. الخ .<br /> <font color=\"Red\">(لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٨</span>).</font><br />ابوالفوارس خسرو طغانشه آن ملکی <br />که شاهی از اثر جاه او برد مقدار.<br /> <font color=\"Red\">ازرقی .</font><br />و نیز رجوع به لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٨</span> شود.<br /></font></div>'),
(177110, 'طغان شاه', '<span class=\"hlight\">طغان شاه .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) ابن المؤید آی آبه . در لباب الالباب نام وی را بدین طرز آورده است : «ملک طغانشه بن محمد المؤید»، ولی علامه ٔ مرحوم میرزا محمدخان قزوینی در ضمن حواشی که بر کتاب مزبور نوشته گوید: «محمد المؤید» غلط است و صحیح اسقاط محمد است، چه اسم پدر طغانشاه به اتفاق مورخین آی آبه بوده است، و لقبش مؤید، و هیچکس نام پدر او را محمد ننوشته است . و آی آبه لفظی است ترکی، مرکب از آی بمعنی ماه، و ابه و هر یک از دو کلمه علیحده در اعلام ترکی دیگر یافت میشود مانند آیتگین (آی تگین ) و آیدُغدی (آی دغدی، آی تغدی )، و قُتلغابه، و ارسلان ابه، و بک ابه .(حواشی لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٢</span>). شاهی که قواعد فضل و اساس هنر به ایام همایون او استحکام یافت، و سرو جویبار ریاست که به ذبول جور انحنا پذیرفته بود، به روزمبارک او سر افراشت . اخلاق حمیده ٔ او فهرست اعمال پسندیده و آثار محموده ٔ او بر صحائف اعمال سردفتر مناقب ستوده، و با اینهمه مکنت و دولت او را شعری بوده است عذب و دلاویز طرب انگیز و ابیات او مشهور است، و میان او و میان ملک تاج الدین تمران مکاتبات و مشاعرات است . اما از لطائف طبع او یکی آن است که کافی خراسان که او را کافرک خوانند، او را قطعه ای گفت، و از وی نان خواست، و این قطعه در غایت لطافت است . میگوید:<br />خسروا تیغ تو مانند اجل شد گه قهر<br />که نگردد شکم پرگهرش از جان سیر<br />گر سر هوش بر تیغ گهردارت را<br />جان ببیند شکم خاک شود از جان سیر<br />بنده را زی زنکی با شکمی چون دهلی <br />جفت افتاده که هرگز نشود از نان سیر<br />گفتم ای دول چنین معده نگردد هرگز<br />جز به صابون و شخار و نمک و اشنان سیر<br />معده ای را که در او سنگ همی بگدازد<br />کی توان کرد چنین معده چنان آسان سیر<br />گر ز نان سیر نمیگردد این هم نوعی است <br />کاشکی میشودی این جلب از حمدان سیر<br />خسرو شرق در این واقعه فریادم رس <br />زآنکه شد خاطرم از فکرت بی پایان سیر<br />به طریق کرمم نقد بده نان چندانک <br />می خورد قرب دو سال این جلب حیران سیر.<br />چون این قطعه در حضرت ملک طغانشاه عرضه داشت، او دواتی و قلمی خواسته و بر ظَهر مسوده بنوشت، رباعی :<br />حاشا که زنت را چو تو ما سیر کنیم <br />یاکام دل میسرش دیر کنیم <br />تو پای برون نه از میان تا وی را<br />از هر دو به دستوری تو سیر کنیم .<br />رباعی :<br />گل دوش بهنگام سحر خاسته بود<br />خود را چو عروس نو بیاراسته بود<br />مشتی زر ریزه ریزه در کف کرده <br />زو نیز مگر که یار زر خواسته بود.<br />هم او راست در فصد، رباعی :<br />دی چون خبر فصد تو اندردادند<br />بر جان و دلم بار دگر بنهادند<br />دست تو چو چشم من مگر عاشق بود<br />برچهره ٔ تو که خون از او بگشادند.<br />هم او گفته است رباعی :<br />با چشم لبش به طعنه گفت ای سرمست <br />با لب چشمش خصومتی درپیوست <br />زلفش به صوابدیدایشان برخاست <br />تا بر روی تو نگونسر آخر بنشست .<br />و او را ابیات و اشعار بسیار است و با ملک تاج الدین تمران مشاعره کرده اند و ابیات ایشان شهرتی دارد. و چون آن پادشاه داعی حق را سماع، و ملک دنیا را وداع کرده، و آفتاب جمال او به کسوف زوال تیره گشت، و چشم بخت او از غبار حدثان خیره شد، دختر کاشغری که از مغنیات خاصه بود و در تحریک انامل و تمزیج آهنگ، زهره ٔ زهرا را در مقام خجالت نشانیدی، و چون زلف چنگ به چنگ آوردی، زاهد قبه ٔ ششم را از عشق روی بروی کردی، در مرثیت این پادشاه رباعی گفته است در غایت لطافت است و در نهایت سلاست . میگوید:<br />از مرگ تو ای شاه سیه شد روزم <br />بی روی تو دیدگان خود بردوزم <br />تیغ تو کجاست ای دریغا تا من <br />خون ریختن از دیده بدو آموزم .<br /> <font color=\"Red\">(لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٤٦</span>-<span class=\"hlight\" dir=\"rtl\">٤٨</span>).</font><br />طغانشاه بن مؤید پس از سلطان سنجر برخراسان مستولی شد، و از سال <span class=\"hlight\" dir=\"rtl\">٥٦٩</span> تا <span class=\"hlight\" dir=\"rtl\">٥٨١</span> در نیشابور که مقر فرمانروائی بود حکمرانی کرد، و باید دانست که وی از خاندان سلجوقیان نبوده است . و نیز رجوع به حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٢</span> و لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٧٨</span>، <span class=\"hlight\" dir=\"rtl\">٣٢٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٦١</span> شود.<br /></font></div>'),
(177111, 'طغانجق', '<span class=\"hlight\">طغانجق .</span> <font color=\"DarkGreen\"><b>[ طُج ِ ]</font></b> (اِخ ) والی سرخس در زمان سلطان محمود. در ترجمه ٔ تاریخ یمینی آمده است : و در آن هنگام که ابوابراهیم منتصر، اسماعیل بن نوح سامانی، از برابر لشکر سلطان محمود فراراً به قهستان شد، طغانجق با نصربن ناصرالدین و ارسلان جاذب والی طوس، وی را در قهستان تعاقب کرده او نیز ناگزیر از راه جومند به بسطام گریخت . و این واقعه بسال <span class=\"hlight\" dir=\"rtl\">٣٩٤</span> هَ . ق . رخ داد. طغانجق نوبتی هم با امام ابوالطیب محمدبن سهل بن سلیمان الصعلوکی به سفارت از طرف سلطان محمود به خواستگاری دختر ایلک خان مأموریت یافت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٣٣</span> و <span class=\"hlight\" dir=\"rtl\">٢٧٦</span>).<br /></font></div>'),
(177112, 'طغای', '<span class=\"hlight\">طغای .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) (امیر...) یکی از پسران دانشمند بهادر معاصر سلطان اولجایتو. رجوع به فهرست ذیل جامعالتواریخ رشیدی و حبیب السیر چ خیام ص <span class=\"hlight\" dir=\"rtl\">٣٧٢</span> و <span class=\"hlight\" dir=\"rtl\">٣٧٣</span> شود.<br /></font></div>'),
(177113, 'طغای', '<span class=\"hlight\">طغای .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) (امیر حاجی ...) از امرای عصر چوپانیان . رجوع به حبیب السیر چ خیام ص <span class=\"hlight\" dir=\"rtl\">٢٢٥</span> شود.<br /></font></div>'),
(177114, 'طغای بوقاشیخ', '<span class=\"hlight\">طغای بوقاشیخ .</span> <font color=\"DarkGreen\"><b>[ طُ ش َ ]</font></b> (اِخ ) (امیر...) از امرای عصر مغول بوده است . رجوع به ذیل جامعالتواریخ رشیدی ص <span class=\"hlight\" dir=\"rtl\">٢٣٨</span> شود.<br /></font></div>'),
(177115, 'طغای ترکان آغا', '<span class=\"hlight\">طغای ترکان آغا.</span> <font color=\"DarkGreen\"><b>[طُ ت ُ ]</font></b> (اِخ ) از قوم قراختای و یکی از سراری امیر تیمور و مادر شاهرخ میرزا که بعد از امیر تیمور به سلطنت رسید بوده است . (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤٢</span>).<br /></font></div>'),
(177116, 'طغای ترکان خاتون', '<span class=\"hlight\">طغای ترکان خاتون .</span> <font color=\"DarkGreen\"><b>[ طُ ت ُ ]</font></b> (اِخ ) یکی از بانوان حرم امیر حسین (رقیب امیر تیمور) که بعد از کشته شدن امیرحسین با سایر بانوان حرم او در حرم سرای امیر تیمور پذیرائی شدند. (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤١٨</span> و <span class=\"hlight\" dir=\"rtl\">٥٤٢</span>).<br /></font></div>'),
(177117, 'طغای توقا بهادر', '<span class=\"hlight\">طغای توقا بهادر.</span> <font color=\"DarkGreen\"><b>[ طُ ب َ دُ ]</font></b> (اِخ ) یکی از امرای عصر تیموری است . (حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span>).<br /></font></div>'),
(177118, 'طغای تیمور', '<span class=\"hlight\">طغای تیمور.</span> <font color=\"DarkGreen\"><b>[ طُ ت َ ]</font></b> (اِخ ) (امیر...) یکی از امرای عصر سلطان اولجایتو، پسر سوتای . (ذیل جامعالتواریخ ص <span class=\"hlight\" dir=\"rtl\">٣٤</span> و <span class=\"hlight\" dir=\"rtl\">٣٥</span>).<br /></font></div>'),
(177119, 'طغای خان', '<span class=\"hlight\">طغای خان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) برادر ترکان خاتون و سرکرده ٔ قشون خوارزمشاه در مصاف با چنگیزخان به سمرقند. (تاریخ مغول اقبال ص <span class=\"hlight\" dir=\"rtl\">٣١</span>).<br /></font></div>'),
(177120, 'طغای کورکان', '<span class=\"hlight\">طغای کورکان .</span> <font color=\"DarkGreen\"><b>[ طُ ی ِ ]</font></b> (اِخ ) یکی از امرای عصر سلطان اولجایتو. (ذیل جامعالتواریخ رشیدی ص <span class=\"hlight\" dir=\"rtl\">١٤</span>، <span class=\"hlight\" dir=\"rtl\">٥٣</span>، <span class=\"hlight\" dir=\"rtl\">٦٣</span>).<br /></font></div>'),
(177121, 'طغایرک', '<span class=\"hlight\">طغایرک .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ازامرای عصر سلجوقیان . رجوع به کتاب تاریخ الدولة السلجوقیه تألیف علی بن ناصربن علی الحسینی ص <span class=\"hlight\" dir=\"rtl\">١٠٨</span> شود.<br /></font></div>'),
(177122, 'طغایی بیک', '<span class=\"hlight\">طغایی بیک .</span> <font color=\"DarkGreen\"><b>[ طُ ب َ ]</font></b> (اِخ ) از امرای ظهیرالدین محمد بابرشاه که در جنگ سمرقند اسیر میرزا جهانگیر شد. رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٥</span> و <span class=\"hlight\" dir=\"rtl\">٢٦٩</span> شود.<br /></font></div>'),
(177123, 'طغتکین', '<span class=\"hlight\">طغتکین .</span> <font color=\"DarkGreen\"><b>[ طُ ت َ ]</font></b> (اِخ ) ابن خلکان آرد: کنیتش ابوالفوارس، پسر ایوب بن شاذی بن مروان، ملقب به الملک العزیزظهیرالدین صاحب الیمن، لقب دیگرش سیف الاسلام است . سلطان صلاح الدین برادر وی به روزگاری که بر دیار مصر پادشاهی داشت، برادر دیگر خویش، شمس الدولة تورانشاه را مالک بلاد یمن ساخت و پس از مدتی بسال <span class=\"hlight\" dir=\"rtl\">٥٧٧</span> هَ . ق . شمس الدولة از یمن بازگشت، و سیف الاسلام طغتکین را فرمانروائی یمن داد. طغتکین مردی پُردل و بزرگوار و نیکورفتار و نیکوسیاست بود و چندان در نیکی و بخشایش شهرت یافته بود که حضرتش محط رحال و کعبه ٔ آمال مردم بلاد دور و نزدیک گردید. وقتی شرف الدین ابوالمحاسن بن عنین الدمشقی قصیده ای چند در مدح وی بساخت و نزد وی بشد، طغتکین نسبت به ابن عنین نیکی بسیار کرد و وی را صله ای جزیل بخشید و در نتیجه وی را مالی فراوان فراهم آمد. چون شاعر با آن مال فراوان از یمن بیرون رفت به مصر که در آن تاریخ الملک العزیز عمادالدین عثمان بن السلطان صلاح الدین در آنجا سلطنت میکرد وارد شد، عُمال دیوان زکوة از شاعر مزبور مطالبه ٔ زکوة اموالی که در این سفر سود برده بود کردند، شاعر مزبور در این باب این قطعه را سرود و برای الملک العزیز بفرستاد:<br />ما کل ما یتسمی بالعزیز لها<br />اهل و لا کُل برق سحبه غدقه ْ<br />بین العزیزین بون فی فعالهما<br />هذاک یعطی و هذا یأخذ الصدقه ْ.<br />وفات سیف الاسلام طغتکین به نوزدهم ماه شوال <span class=\"hlight\" dir=\"rtl\">٥٩٣</span> در شهرمنصوره از بلاد یمن که از مستحدثات وی بود اتفاق افتاد. یاقوت در معجم البلدان گوید قرارگاه سیف الاسلام درتمام مدت فرمانروائی در بلاد یمن، در شهر منصوره بود، سرانجام همانجا به خاک سپرده شد، و شاعر او «اُبی ّ» در این باب میگوید:<br />احسنت فی فعالها المنصوره ْ<br />و اقامت لنا من العدل صوره ْ<br />رام تشییدها العزیز فأعطتَْ<br />َه ُ الی وسطقبره دستوره ْ.<br /> <font color=\"Red\">(معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span>).</font><br />و ابن خلکان گوید: بعد از مرگ سیف الاسلام، فرزند او الملک المعز فتح الدین اسماعیل جانشین وی گردید. (ابن خلکان چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٨</span>). و رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٨</span> شود.<br /></font></div>'),
(177124, 'طغتکین', '<span class=\"hlight\">طغتکین .</span> <font color=\"DarkGreen\"><b>[ طُ ت َ ]</font></b> (اِخ ) سیف الاسلام، ظهیرالدین طغتکین . سرسلسله ٔاتابکان دمشق که به آل بوری نیز اشتهار دارند. وی ازسال <span class=\"hlight\" dir=\"rtl\">٤٩٧</span> تا <span class=\"hlight\" dir=\"rtl\">٥٢٢</span> هَ . ق . در شام پادشاهی کرد. رجوع به اتابکان دمشق شود. وی از رجال درباری تاج الدوله تتش بشمار میرفت و تا زمانی که تاج الدوله تتش برای جنگ و پیکار با برادرزاده ٔ خویش برکیاروق به ری اقامت داشت، طغتکین نیز با او همراه بود، پس از کشته شدن تتش، به دمشق بازگشت، و در تمام مدت فرمانروائی دقاق پسر تتش، طغتکین اتابک وی میبود. طغتکین مردی باشهامت و سهمگین و با تبهکاران بسیار سختگیر بود، و دیرگاهی در شام فرمانروائی کرد، تا در سال <span class=\"hlight\" dir=\"rtl\">٥٢٢</span> در هفتم صفردنیا را بدرود گفت، و در مسجد الحدید دمشق، بجانب قبله ٔ مصلی او را به خاک سپردند. ابن القلانسی گوید: مصحف شریفی را که عثمان بن عفان خلیفه ٔ سوم از مدینه ٔ منوره به طبریه ٔ شام انتقال داده بود، طغتکین از مسجدطبریه به جامع اموی دمشق نقل کرد. و پس از وفات طغتکین تاج الملوک بوری جانشین او گردید. (اخبارالدول قرمانی ص <span class=\"hlight\" dir=\"rtl\">٢٨١</span>). گویند اتابک طغتکین بوری، محتسبی میطلبید، عالمی را بدو نام بردند، و او وی را بخواست، و گفت من ترا تولیت امر حسبه دادم که امر به معروف بر مردم و نهی از منکر کنی، عالم گفت اگر چنین است حالی از این بالش و این مسند برخیز، چه این دو ابریشمین است، و این انگشتری از انگشت بیرون کن، چه از زر باشد از آنکه رسول صلوات اﷲ و سلامه علیه، فرموده است که این دو بر زنان امت او روا و بر مردان حرام باشد. طغتکین در حال از بالش و مسند برخاست، و انگشتری بیرون کرد، و گفت امر شرطه نیز ترا سپردم و مردم محتسب بهیبت تر از او ندیدند. (معالم القربة ص <span class=\"hlight\" dir=\"rtl\">١٣</span>). (در معالم القربة اسمی از طغتکین نبرده است ). در دائرة المعارف اسلام که به فرانسه تألیف شده سرسلسله ٔ آل بوری را بدین طریق نام برده است : «طغتکین بن عبداﷲ، امین الدوله، ظهیرالدین، ابومنصور». ابن الاثیر در حوادث سال <span class=\"hlight\" dir=\"rtl\">٥٢٢</span> میگوید: در هشتم صفر این سال اتابک طغتکین وفات یافت . وی غلام تتش بود، مردی دانا و نیکخواه و مجاهد در راه اسلام بویژه در برابر فرنگیان و با رعایا نیک رفتار بود و با آنان به عدل و داد معاملت میکرد، لقبش ظهیرالدین . با تصریح ابن اثیر به اینکه ظهیرالدین لقب طغتکین بوده، و با تصریح ابن خلکان به اینکه طغتکین بن ایوب سیف الاسلام لقب داشته احتمال میرود ظهیرالدین بین هر دو مشترک، و سیف الاسلام مختص طغتکین بن ایوب بوده است و در تهذیب تاریخ ابن عساکر (ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>) آمده است : طغتکین، ابومنصور المعروف باتابک، بی آنکه لقبی برای او ذکر کند. و رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٥٠</span> و اخبار الدولة السلجوقیة چ محمد اقبال ص <span class=\"hlight\" dir=\"rtl\">١٩٦</span> شود.<br /></font></div>'),
(177125, 'طغتکین', '<span class=\"hlight\">طغتکین .</span> <font color=\"DarkGreen\"><b>[ طُ ت َ ]</font></b> (اِخ ) (الامیر...) در اخبار الدولة السلجوقیه آورده : الب ارسلان در اوایل ربیعالاول سال <span class=\"hlight\" dir=\"rtl\">٤٥٣</span> هَ . ق . از ری به قصد غزای روم حرکت کرد... چون با لشکریان به مرند رسید در آنجا چند روزی اقامت گزید، امیر طغتکین نامی که در طریق روم با جماعتی از ترکمانان در آن جاده همواره موجبات رنج و مزاحمت رومیان را فراهم آوردی واز این رو از رومیان بیم داشت، به الب ارسلان پناه برد، و رهنمائی وی و لشکریانش را به مضایق و معابر سخت آن جاده تعهد کرد. (تاریخ الدولة السلجوقیة ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>).<br /></font></div>'),
(177126, 'طغر', '<span class=\"hlight\">طغر.</span> <font color=\"DarkGreen\"><b>[ طُ غ َ ]</font></b> (ع اِ) مرغی است . ج، طِغْران . (منتهی الارب ) (آنندراج ). اسم طائری است معروف و جمع او طِغْران .<br /></font></div>'),
(177127, 'طغر', '<span class=\"hlight\">طغر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) درآمدن بر کسی . یقال : طَغَرَ علیهم ؛ اذا دَغَرَ. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> دفع کردن . (منتخب اللغات ).<br /></font></div>'),
(177128, 'طغرا', '<span class=\"hlight\">طغرا.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) تخلص شاعری است از مشهد مقدس، صاحب دیوان و مثنوی و منشآت که اکثر اشعارش در این کتاب به طریق استناد مذکور است . (آنندراج ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177129, 'طغرا', '<span class=\"hlight\">طغرا.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) طُغْری ̍. القابی باشد که بر سر فرمان پادشاهان مینویسند، و در قدیم خطی بوده است منحنی که بر سر احکام ملوک میکشیده اند. (برهان ). نوعی از خط پیچیده ٔ حروف که به آن خط بر فرمان پادشاهان القاب نویسند. ظاهراً این لفظ ترکی است، در مناظرالانشاء نوشته که : طغرا خط سطبری باشد بخط پیچیده که القاب و اسم سلطان باشد، مثل السلطان الاعظم الاعدل جلال الدین اکبر پادشاه غازی . (غیاث اللغات ) (آنندراج ). خطی است که در عهد ملوک قدیم بالای امثله و مناشیر ایشان میکشیده اند بر شکل کمانی . (صحاح الفرس ) <span class=\"hlight\">:</span> <br />اعدل اقطار شرق و غرب کز القاب او<br />بر مناشیر امور عدل طغرا کرده اند.<br /> <font color=\"Red\">هندوشاه نخجوانی .</font><br />طره ای است که بر بالای نامه پیش از بسمله نوشته می شود با قلم درشت، و مضمون آن نعوت پادشاه فرستنده ٔ نامه است، و لفظ اعجمی است . (ابن خلکان در ترجمه ٔ طغرائی اصفهانی ). صورتی مرکب از چند خط عمودی منتهی به قوس گونه ای تودرتو و متوازی، محتوی نام و لقب سلطان یا امیری، و آن را بر سر احکام و فرمانها مینگاشتند، و کار نگاشتن طغرا بیشتر منصب و شغلی خاص بوده بیرون از منصب و شغل کاتب، و گماشته ٔ بدین کار را طغرانویس و گاه طغرائی مینامیدند و طغرا بمنزله ٔ امضاء شاه یا امیر و حاکم بود. هی الطرة التی تکتب فی اعلی المناشیر بالقلم الجلی، تتضمن اسم الملک و القابه، وهی کلمة اعجمیة محرفة من الطرة. (معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥١</span>). مؤلف آنندراج در فرهنگ خود آورده که : طغرا القابی است که به طرز مخصوص بر سر فرامین به آب طلا یا شنجرف نویسند، و بر رقمهای نادرشاه به مرکب نوشته دیده شده، و بعضی گویند در قدیم خطی بوده منحنی که بر سرفرمان میکشیده اند. ملاطغرا در توحید <span class=\"hlight\">:</span> <br />به طغرانویس گل سرخ رنگ <br />رسانیده شنجرف می بیدرنگ .<br />درویش واله هروی :<br />در کشور صفحه کلک یکتا<br />بر نام سخن کشید طغرا.<br />خواجه جمال الدین سلمان :<br />ما مثال عزل عقل از ملک دین برخوانده ایم <br />تا کشیدستند بر منشور ما طغرای عشق .<br /> <font color=\"Red\">(از آنندراج ).</font><br />طغرای نکونامی و منشور سعادت <br />نزد ملک العرش به توقیع تو بردم .<br /> <font color=\"Red\">برهانی .</font><br />به دست همت طغرای بی نیازی دار<br />که هر دو کون تو داری چو داری این طغرا.<br /> <font color=\"Red\">خاقانی .</font><br />گفتم احسان شما بگذشت و احسان رهی <br />جاودان مانده ست و این طغرای اقبال شماست .<br /> <font color=\"Red\">خاقانی .</font><br />از نقاب قیرگون بر صبح کرده سایبان <br />و آن غلاله ٔ عنبرین بر ماه طغرا ساخته .<br /> <font color=\"Red\">؟ (از صحاح الفرس ).</font><br />همچو والا در این صفت قاری <br />بر سر حکم شاه طغرائیم .<br /> <font color=\"Red\">نظام قاری .</font><br />و در این بیت خواجه حافظ <span class=\"hlight\">:</span> <br />صاحب دیوان ما گوئی نمیداند حساب <br />کاندر این طغرا نشان حِسْبةً للّ̍ه نیست <br />معلوم نیست که آیا میان طغرا «حِسْبةً للّ̍ه » نقش بوده، یا رمزی مانند «ح » و امثال آن که حکایت از آن جمله میکرده است ؟ <BR><font color=\"Blue\">◄</font> نوعی از خط نسخ که آن را توقیع نیز نامند. <BR><font color=\"Blue\">◄</font> و نیز شعرا ابروی شاهدان را به طغرا تشبیه کنند. قوامی رازی در صفت طغرای فرمان ممدوح گوید <span class=\"hlight\">:</span> <br />تو از تیزی قلم سازی کمانی را که بردارد<br />همه احکام این تیر و کمان چرخ مینائی <br />فلک با قدرتش بر زه نداند کرد چرخی را<br />که هر ساعت کشند آن را به یک انگشت تنهائی <br />خطا گفتم کمان چون باشد این خطی که پنداری <br />خط دلبند ترکان است گرد روی زیبائی .<br /> <font color=\"Red\">قوامی .</font><br />طغرای هلالیش دریغ است به کاغذ<br />آن ابروی پیروزی بر روی قمر باد.<br /> <font color=\"Red\">سیدحسن غزنوی .</font><br />به طاق آن دو ابروی خمیده <br />مثالی زان دو طغرا برکشیده .<br /> <font color=\"Red\">نظامی .</font><br />هلالی شد تنم زین غم که با طغرای ابرویش <br />که باشد مه که بنماید ز طاق آسمان ابرو.<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> کمانچه ٔ ابرو، به استعاره <span class=\"hlight\">:</span> <br />امید هست که منشور عشقبازی من <br />از آن کمانچه ٔ ابرو رسد به طغرائی .<br /> <font color=\"Red\">حافظ.</font><br /><BR><font color=\"Blue\">◄</font> نشان . و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٨</span> شود.<br /></font></div>'),
(177130, 'طغرالجرد', '<span class=\"hlight\">طغرالجرد.</span> <font color=\"DarkGreen\"><b>[ طُ ج ِ ]</font></b> (اِخ ) نام یکی از <span class=\"hlight\" dir=\"rtl\">٨</span> دهستان بخش زرند شهرستان کرمان . محدود است از شمال به دهستان کوهبنان، از خاور به دهستان دشت خاک، از جنوب به دهستان حومه ٔ زرند، از باختر به دهستان سیریز. موقعیت آن کوهستانی و سردسیر است . از <span class=\"hlight\" dir=\"rtl\">٢٥</span> آبادی بزرگ و کوچک تشکیل شده . جمعیت آن <span class=\"hlight\" dir=\"rtl\">١٨٩٠</span> تن است .راه فرعی زرند - راور از این دهستان میگذرد، بقیه ٔ راه ها مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(177131, 'طغران', '<span class=\"hlight\">طغران .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ج ِ طغر. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177132, 'طغرانویس', '<span class=\"hlight\">طغرانویس .</span> <font color=\"DarkGreen\"><b>[ طُ ن ِ ]</font></b> (نف مرکب ) طغراکش . طغرائی <span class=\"hlight\">:</span> <br />مطبوع تر ز نقش تو صورت نبست باز<br />طغرانویس ابروی همچون هلال تو.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(177133, 'طغراکش', '<span class=\"hlight\">طغراکش .</span> <font color=\"DarkGreen\"><b>[ طُ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) آنکه امر طغرا کشیدن بر سر فرامین و احکام برعهده ٔ او محول باشد. طغرانویس . طغرائی <span class=\"hlight\">:</span> <br />ای که انشاء عطارد صفت شوکت تست <br />عقل کل چاکر طغراکش دیوان تو باد.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(177134, 'طغرای تبریزی', '<span class=\"hlight\">طغرای تبریزی .</span> <font color=\"DarkGreen\"><b>[ طُ ی ِ ت َ ]</font></b> (اِخ ) وی را ملاطغرا نیز میخوانده اند. صاحب تذکره ٔ نصرآبادی آرد: شخصی میگفت که مشهدی است . در هند میباشد. در نظم و نثر کمال قدرت دارد چنانکه منشآت او به نظر فقیر رسید طورش غرابتی دارد در کمال پاکی و کلامش مرغوب و خیالاتش محبوب، با وجود آرام وحشت تخلص دارد. مدتی در هند به اعتبار قرابت با میر محمدسعید میر جمله بود، بنابر حب وطن مراجعت نموده به بلای کدخدائی مبتلا شده بعد از مدتی طالعش مدد نموده زوجه اش فوت شده باز بیعلاج یک سال قبل از حالت تحریر به هند رفت، امید که سلامت مراجعت نماید. این اشعار از منشآت اوست :<br />فضای لامکانی بارگاهش <br />هجوم بی نیازیها سپاهش <br />ندارد ایزد از یک رنگیی عار<br />بود اﷲ را تشدید در کار<br />نگردد بی خیالش آب راهی <br />دمی بی خارخارش نیست ماهی .<br />رجوع به تذکره ٔ نصرآبادی ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span> شود.<br /></font></div>'),
(177135, 'طغرد', '<span class=\"hlight\">طغرد.</span> <font color=\"DarkGreen\"><b>[ طُ رُ ]</font></b> (ترکی، اِ) به ترکی اسم طائری است از طیور صید از جنس صقور.(فهرست مخزن الادویه ). ظاهراً تحریفی است از طغرل .<br /></font></div>'),
(177136, 'طغرل', '<span class=\"hlight\">طغرل .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ]</font></b> (اِخ ) ابن محمدبن ملکشاه ابوطالب رکن الدین طغرل بن محمدبن ملکشاه یمین امیرالمؤمنین (طغرل ثانی ) (<span class=\"hlight\" dir=\"rtl\">٥٢٦</span> تا <span class=\"hlight\" dir=\"rtl\">٥٢٨</span> هَ . ق .). سلطان طغرل از سلاطین عهد خویش به عدل و شجاعت و بذل و سخاوت ممتاز بود و به خلق رضی و کرم جبلی از میان خسروان جهان مستثنی، از هزل و ملاهی و فواحش و مناهی اجتناب نمودی و به مقتضای اشارت لایوجدالعجول محموداً تأنی و وقار در همه کار از واجبات دانستی . فسانه های فریدون را آیات دادگستری او ناسخ بود و قواعد نَصَفت و عدل پروری انوشروان حکایات او منسوخ کرد و چون سلطان محمود از مضایق دار دنیی به حدائق فردوس اعلی رفت و رخت دولت از مدارج سرای سفلی به معارج عالم علوی برد سلطان سنجر که عم طغرل بود بنابر رعایت حقوق خویشی و محافظت مراسم یگانگی ولیعهدی و قائم مقامی به وی تفویض کرد و زمام بسط و قبض و عنان ابرام و نقض کلیات و جزئیات امور طول و عرض ممالک بسط ارض به وی سپرد و چون از خدمت سلطان مراجعت کرد و به عراق آمد میان او و برادرش مسعود خصومتی بادید آمد و حسدی که از لوازم جهانداری است با سوابق حقدی که از خصائص خویشی است متلاحق شد و به وضع اساس بیگانگی برخاستند و به رفع قاعده ٔ یگانگی میان دربست و روزگار غدار روزی طغرل را مقبل میخواند و زمانی برادرش را طالع مسعود می بخشید، هنگامی خول و خدم طغرل طعمه ٔ سنان قهر مسعود میشدند و عَلَم اقبالش نگونسار میگشت و گاهی خیل و حشم مسعود ذلیل و خوار آیت فرار میخواندند، بلی آخرالامر فتح اصلی و ظفر کلی مسعود را بود و به مراد و مقصود برسید و منهی تقدیر نداء شعر:<br />اذا لم یعنک الجد فالجد باطل <br />و سعیک فیما لم یقدر مضیع<br />بیت :<br />به کوشش بزرگی نیاید بجای <br />مگر بخت نیکش بود رهنمای <br />به سمع طغرل رسانید و در شهر همدان در محرم سنه ٔ تسع و عشرین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٢٩</span> هَ . ق .) آفتاب عمرش منکسف شد وماه جاهش منخسف گشت و به روضه ٔ رضوان و قصور جنان رفت . بیت :<br />چرخ از دهنش نواله در خاک افکند<br />دولت قدحش پیش لب آورد و بریخت .<br />سال عمرش از بیست وپنج نگذشت و زیادت از سه سال بر تخت سلطنت قرار نگرفت . وزراء او قوام الدین ابوالقاسم و شرف الدین علی بن رجاء بودند. توقیعش اعتضدت باللّه وحده . (از العراضه صص <span class=\"hlight\" dir=\"rtl\">١١٥</span> - <span class=\"hlight\" dir=\"rtl\">١١٦</span>).<br />صاحب حبیب السیر آرد: چون سلطان محمود به ملک عقبی توجه فرمود ناصر وزیر خواست که به موجب وصیت محمود پسرش داود را بر مسند سلطنت نشاند، اما سران سپاه بر طبق اشارت سلطان سنجر عروس مملکت عراق را با طغرل عقد بستند و مراسم متابعت بجای آورده دل داود را به خار عدم التفات خستند. طغرل پادشاهی بود به عدل و سیاست مشهور و از ارتکاب مناهی و ملاهی مهجور و به کرم و شجاعت موصوف و به حیا و مروت معروف، اما زمان کامرانیش مانند گل اندک بقا بود و چون سه سال به اقبال گذرانید درهمدان به ریاض جنت خرامید. این صورت در ماه محرم <span class=\"hlight\" dir=\"rtl\">٥٢٩</span> به وقوع انجامید. مدت حیاتش در بیست وپنج سالگی به نهایت رسید. (حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨١</span>). در همین سال (<span class=\"hlight\" dir=\"rtl\">٥١٩</span>) میان مسترشد خلیفه و دبیس بن صدقه غبار کدورت و نزاع ارتفاع یافته بقصد یکدیگر حرکت کردند و حربی صعب اتفاق افتاد، خلیفه را فتح و نصرت دست داد و مسترشد به بغداد بازگشت و دبیس پیش سلطان طغرل بن محمدبن ملکشاه رفته او را بر آن داشت که در سنه ٔ تسععشر و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥١٩</span> هَ . ق .) بعزم تسخیر بغداد متوجه گردد و خلیفه نیز لشکری فراهم آورده روی به وی نهاد و طغرل و دبیس از نهضت خلیفه خبر یافته طغرل بطرف بغدادکوچ نمود و دبیس خواست که در برابر خلیفه درآید، دراین اثنا تب محرق بر ذات طغرل طاری گشته بارانی عظیم باریدن گرفت چنانچه سلجوقیان را مجال حرکت نماند ودبیس شبی بقصد خلیفه ایلغار کرده راه گم کرد و تا صباح اسب رانده در غایت ماندگی به صحرائی منزل گزید واز غرائب اتفاقات آنکه چون سپاه بغداد از عزیمت سلطان طغرل خبر یافتند طریق فرار مسلوک داشته پراکنده گشتند و مسترشد در وقت گریز با معدودی چند بر سر دبیس بن صدقه که در آن صحرا به خواب رفته بود رسیده دبیس سراسیمه برجسته روی نیاز بر زمین نهاد. خلیفه از وی عفو نموده بجانب بغداد توجه فرمود و دبیس به طغرل ملحق گشته به همدان شتافت . (حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١١</span>). ابن الاثیر نیز در تاریخ کامل الحاق دبیس بن صدقه را به طغرل در سال <span class=\"hlight\" dir=\"rtl\">٥١٩</span> شرح داده، ولی صاحب تاریخ تجارب السلف گوید: میان حله و بغداد بین لشکریان خلیفه و دبیس بن صدقه جنگی عظیم درگرفت و دبیس شکسته شد و بسیار کس از اکابر لشکر او اسیر شدند و دبیس خود را در آب فرات انداخت و از طرفی دیگر بیرون رفت و روی به بادیه نهاده اما عرب او را معاونت نکردند و گفتند ما به روی خلیفه شمشیر نکشیم . چون دبیس از پیش ایشان نومید شد پیش سلطان مسعود رفت . (تجارب السلف ص <span class=\"hlight\" dir=\"rtl\">٢٩٤</span>).<br />لین پول در طبقات سلاطین اسلام مطابق ارقامی که برای طول مدت پادشاهی هر پادشاهی تعیین کرده برای این سلطان فقط یک سال سلطنت قائل شده، در صورتی که به اتفاق مورخین سلطنت او سه سال بوده . به طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span> مراجعه شود، و ظاهراً این اشتباه از مطبعه ناشی شده است . و رجوع به مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٤١١</span>، <span class=\"hlight\" dir=\"rtl\">٤١٣</span>، <span class=\"hlight\" dir=\"rtl\">٤١٥</span>، <span class=\"hlight\" dir=\"rtl\">٤٢٩</span>، <span class=\"hlight\" dir=\"rtl\">٤٦٥</span> و لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٦٥</span> و حبیب السیر چ خیام فهرست ج <span class=\"hlight\" dir=\"rtl\">٢</span> و تاریخ الدولة السلجوقیة تألیف علی بن ناصربن علی الحسینی چ محمد اقبال ص <span class=\"hlight\" dir=\"rtl\">٨٢</span>، <span class=\"hlight\" dir=\"rtl\">٩٠</span>، <span class=\"hlight\" dir=\"rtl\">٩٨</span>، <span class=\"hlight\" dir=\"rtl\">٩٩</span>، <span class=\"hlight\" dir=\"rtl\">١٠٥</span>، <span class=\"hlight\" dir=\"rtl\">١٠٦</span>، <span class=\"hlight\" dir=\"rtl\">١٢٢</span>، <span class=\"hlight\" dir=\"rtl\">١٦٩</span> و تاریخ مغول اقبال صص <span class=\"hlight\" dir=\"rtl\">١٢٥</span>-<span class=\"hlight\" dir=\"rtl\">١٢٧</span> شود.<br /></font></div>'),
(177137, 'طغرل', '<span class=\"hlight\">طغرل .</span> <font color=\"DarkGreen\"><b>[ طُ رِ<span class=\"hlight\" dir=\"rtl\">/</span> رُ ]</font></b> (ترکی، اِ) نام مرغی است شکاری <span class=\"hlight\">:</span> <br />الا تا بانگ درّاج است و قمری <br />الا تانام سیمرغ است و طغرل .<br /> <font color=\"Red\">منوچهری .</font><br />دل تیهو از چنگ طغرل بداغ <br />رباینده باز از دل میغ ماغ .<br /> <font color=\"Red\">اسدی .</font><br /> <BR><font color=\"Blue\">◄</font> در لغات شاهنامه تألیف ولف، بمعنی شاهین نیز آمده است .رشیدی در فرهنگ خود آورده که این لفظ ترکی است (به استناد نسخه ٔ میرزا) و مولانا سروری گفته که از ترکان پرسیده شد، گفتند ترکی نیست، و ظاهراً ترکی مغولستان است . (رشیدی ). بعضی گویند باز است و بعضی شاهین، ومیرزا ابراهیم گفته که این لفظ ترکی است . (فرهنگ خطی ). پرنده ای است شکاری از جنس زردچشم . مؤلف بازنامه ٔ ناصری گوید: هرچند من با همه ٔ گردش و احتیاط طغرل را ندیده ام، اما از صفاتی که شنیده و در کتب دیده شده از نوع زردچشم است . بعد حکایت یک طغرل را نقل میکند که از چین برای بهرام گور آورده بودند. (فرهنگ نظام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٤٣</span>). صاحب مجمعالفرس و حافظ اوبهی و مؤلف برهان و صاحب غیاث اللغات و آنندراج در فرهنگ خود لفظطغرل را بضم راء ضبط کرده اند. مؤلف آنندراج در فرهنگ خود آورده که : طغرل ؛ جانور شکاری و پادشاهی است واین ترکی است و بعضی گویند از ترکان تحقیق شده ترکی نیست . ظاهراً ترکی مغولستانی است . حکیم زلالی <span class=\"hlight\">:</span> <br />ز بیمش اشک سیمابند در گل <br />طغان و سنجر و بهرام وطغرل .<br />خواجه سلمان :<br />در جاه گرفتم که شدی طغرل و سنجر<br />بنگر که کجایند کنون سنجر و طغرل .<br /> <font color=\"Red\">(از بهار عجم ).</font><br />و در غیاث نوشته که طغرل نام پادشاهی از پادشاهان سلجوقی و بر وزن بلبل جانوری است شکاری طائر مثل باز وعقاب . (از برهان و مدار و سراج ). و در چهار شربت نوشته که تغرل به تای فوقانی در ترکی بهری را گویند که طائر شکاری معروف است . مؤلف گوید که طغرل مبدل همین است . (آنندراج ). ولف در فرهنگ شاهنامه گوید: ماکان در شاهنامه که طبع کرده همه جا طغرل را بفتح راء ضبط کرده است <span class=\"hlight\">:</span> <br />بزد طبل و طغرل شد اندر هوا<br />شکیبا نشد مرغ فرمانروا.<br /> <font color=\"Red\">فردوسی .</font><br />که طغرل به شاخی برآویخته ست <br />کنون بازدارش بگیرد به دست .<br /> <font color=\"Red\">فردوسی .</font><br />ز دیدارشان چشم او خیره گشت <br />ز باز و ز طغرل دلش تیره گشت .<br /> <font color=\"Red\">فردوسی .</font><br />به برزین چنین گفت شاه جهان <br />که امروز طغرل ز ما شد نهان .<br /> <font color=\"Red\">فردوسی .</font><br />ابا بازداران صدوشصت باز<br />دوصد چرخ و شاهین گردن فراز<br />پس اندر یکی مرغ بودی سیاه <br />گرامی تر آن بود در چشم شاه <br />سیاهش دو چنگ و به منقار زرد<br />چو زرّدرخشنده بر لاجورد<br />همی خواندندیش طغرل بنام <br />دو چشمش چنان چون پر از خون دو جام .<br /> <font color=\"Red\">فردوسی .</font><br />دوصد باز و افزون ز سیصد خشین <br />صدوشصت طغرل همه به گزین .<br /> <font color=\"Red\">اسدی (گرشاسب نامه ص <span class=\"hlight\" dir=\"rtl\">٣٠٤</span>).</font><br />سرش طغرل و تنش یکسر ز زر<br />ز یاقوت چشم از زبرجدش پر.<br /> <font color=\"Red\">اسدی (گرشاسب نامه ص <span class=\"hlight\" dir=\"rtl\">٣١٣</span>).</font><br />بلی خجل شود آن باشه ای که ناگاهان <br />به آشیانه ٔ او میهمان رسد طغرل <br />ز جاه صاحب عادل ملک بگرداناد<br />گزند چشم بدو طعن حاسد و عاذل .<br /> <font color=\"Red\">سوزنی .</font><br />و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٥</span> شود.<br /></font></div>'),
(177138, 'طغرل', '<span class=\"hlight\">طغرل .</span> <font color=\"DarkGreen\"><b>[ طُرِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ]</font></b> (اِخ ) نام اونگ حاکم قبیله ٔ کرایت . صاحب حبیب السیر از جامعالتواریخ نقل میکند که در قدیم الایام در میان ترکان، پادشاهی بود و هشت پسر سیاه فام داشته، و بجهت سواد لون ایشان را کرایت میگفتند، یعنی گوشت سیاه و تمامی قوم کرایت که اونگ حاکم ایشان بوداز ذریت آن جماعتند، و معنی اونگ خان والی یک ولایت است و نام اونگ طغرل بود. (حبیب السیر چ خیام ص <span class=\"hlight\" dir=\"rtl\">١٩</span>).<br /></font></div>'),
(177139, 'طغرل', '<span class=\"hlight\">طغرل .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ]</font></b> (اِخ ) رجوع به عزالدین طغرل طغانخان و رجوع به طغان خان شود.<br /></font></div>'),
(177140, 'طغرل', '<span class=\"hlight\">طغرل .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ]</font></b> (اِخ ) ابن ارسلان، السلطان الاعظم رکن الدنیا و الدین معز الاسلام و المسلمین، ابوطالب طغرل بن ارسلان قسیم امیرالمؤمنین (طغرل ثالث ) (<span class=\"hlight\" dir=\"rtl\">٥٧٣</span> تا <span class=\"hlight\" dir=\"rtl\">٥٩٠</span> هَ . ق .).کمال دولت و کامیاری و وفور حشمت و بختیاری سلطان ماضی طغرل سلجوقی از آن زیادت بود که دست عبارت به دامن شرح اندکی از آن رسد یا عشری از معشار آن در حیز وصف آید. به تأیید الهی و عنایت لایزالی که مستدعی سعادت ابدی و مقتضی دولت سرمدی است اختصاص یافته بی تکاپوی جنگ، چنگ در دامن مراد زد و بی تعب طلب، عروس مملکت را در کنار گرفت و بی زحمت غرس، میوه ٔ سلطنت از درخت دولت بچید و در رعایت رعیت نام نیک اندوخت و در اشاعت خیرات و انعام درباره ٔ رعایا و رعاة و دفع ظلمه و سد اطماع مستأکله و رفع رسوم اهل عدوان و احسان در حق عامه ٔ عالمیان مشارالیه گشت . و در احیاء قواعد اجداد و تجدید مراسم اسلاف سعی بلیغ نمود، و در عهد پادشاهی او کژی جز در زلف دلبران چین به دست نمی آمد، و فتنه جز از چشم خوبان نازنین برنمیخاست . ذاتش مستجمع کمالات نفسانی و خصایص جهانبانی بود. صورت پسندیده و سیرت گزیده داشت و به علم و هنر آراسته و به عقل و فضل پیراسته بود. در سخندانی موی شکافتی، و شعری روان چون آب حیوان گفتی، تعظیم علما و انعام درباره ٔ فضلا علی الدوام فرمودی، و التفات خاطر ایشان سبب ازدیاد رونق امور و اتمام مناهج جمهور دانستی، در حق شیخ الاسلام ربانی بایزید ثانی، ظهیرالدین بلخی که درعهد خویش با کمال علم و غزارت فضل مذکور بود و به تقوی و دینداری مشهور، اعتقادات صادقانه و صفای صوفیانه داشت، و شبها به قدم ارادت جهت استراحت به زاویه ٔشیخ رفتی و مصالح ملک و دین با وی مشورت کردی و امراء دولت را این معنی گلوگیر می آمد و از چاره و تدبیرعاجز آمدند و به اتفاق با سلطان نفاق آغاز نهادند وبه عهود و مواثیق مقرر کردند که یداً واحداً باشند و در قصد سلطان بکوشند و شیخ به فراست و قرائن قولی و فعلی بدانست و به حکم رخصت ذکر مساوی الشخص لمصلحةالغیر بنابر رعایت حقوق مصاحبت با سلطان بگفت . شعر:<br />چو کاری بی فضول من برآید<br />مرا در وی سخن گفتن نشاید<br />وگر بینم که نابینا و چاه است <br />اگر خاموش بنشینم گناه است .<br />سلطان با امرا بیعنایت گشت و اثر آن به ظهور رسانید. امرا گرد هر حیلت و مکر برآمدند تا مگر از خشم سلطان امان یابند و مکتوبات به قتلغ اینانج که ساکن ری بود نوشتند به شکایت سلطان و آنکه او اکثر اوقات به خانه ٔ ظهیرالدین بلخی میباشد و در کل قضایا مخالفت از صواب دید او خطا می پندارد و ما را پشت پای زده و کالعدم انگاشته، و التماس کردند تا اوموافقت نماید و اجازت دهد تا ایشان به مشورت سیدعلأالدوله همدان سلطان را بگیرند و این مکتوبات در میان عصائی تعبیه کردند و به دست قاصدی دادند تا به ری برد و بدین تدبیر قناعت نکردند و شبها رنود و اوباش وشرارالناس را بر سر راهها می نشاندند تا باشد که بدان طریق سلطان را هلاک توانند کرد و چون آن تدبیر موافق تقدیر نیامد سلطان از آن آگاه شد و به احتیاط ترددمیفرمود. شعر:<br />یرید الجاهدون لیطفئوه <br />و یأبی اﷲ الا ان یتمه .<br />و قاصد به ری رفت و در اثناءراه با پسر سراج الدین قتلغآبه شرابی دچار خورد و اواز قاصد تعرف هر جائی میکرد و قاصد از بی طالعی چنانچه شیوه ٔ بددولتان باشد ملالتی بنمود و التفاتی کماینبغی نکرد. پسر سراج الدین از آن بی التفاتی برنجید، گرزی گران که بر دست داشت براند تا بر آن نادان زند، او محافظت نفس را عصا در مقابل صدمه ٔ گرز بداشت و گرزبر عصا آمد و عصا خرد و ناچیز شد و مکتوبات هر یک بر طرفی افتاد. شعر:<br />تعبیه ها بین که روزگار برآرد<br />تا ز دل بیدلی دمار برآرد.<br />پسر سراج الدین مکتومات بخواند و چون بر حال اطلاع یافت در رفتن شتاب کرد و به حضرت سلطان رفت و نوشته ها عرض کرد و آن قصد منجح و آن تجارت مربح نیامد. سلطان روز دیگر که ارکان دولت بر معتاد عادت به حضرت آمدند، بیرون نیامد و سیدفخرالدین علاءالدوله را که بدان کبیره متهم و با آن جماعت همدم بود به خلوت طلب داشت و او را بنابر آنکه از خاندان نبوت و دودمان رسالت بود و به شرف سیادت و انتما به خانواده ٔ ولایت ممتاز خلعت عفو پوشانید وجرعه ٔ لطف نوشانید. و قصه ٔ حال بر رای رزین او عرض کرد و بعد از آن خواجه عزیز وزیر و پسران او موفق وکیل در و ظهیر منشی و شهاب چک نویس و قتلغ طشتدار و چند کس دیگر را که در این کار با ایشان همراز بودند طلب کرد و هر یک را نوشته ٔ خویش میداد و میگفت : اقراء کتابک کفی بنفسک الیوم علیک حسیباً . شعر:<br />اگر بار خار است خود کشته ای <br />وگر پرنیان است خود رشته ای .<br />ایشان با خار غم، چار و ناچار دوچار خوردند و دُردی دردی بیدوا نوش کردند، و در آن روز که «یوم تبلی السرائرُ» صفت آن بود، در غرقاب حیرت و مذلت افتادند، و به امر سلطان جهان آن عاصیان را در قلعه ٔ همدان مقید و محبوس کردند. بعد از آن متحیران بادیه ٔ محنت و مجاوران زندان مشقت، طوعاً او کرهاً التجا به جناب مجد و معالی شیخ الاسلام بلخی کردند، و گفتند اگر سلطان بر این چند بی دولت که چون مرغ نیم بسمل در اضطراب و از نظر مشتری سعادت در حجاب آمده، و به باد نکبت از اعلی علیین به تحت التراب افتاده ببخشد، و رقم عفو بر زلت ما کشد ما آنچه از املاک و اموال که لولاه ُ لم تقطع یمین ُ سارق، ایثار کنیم و از اَعراض دنیوی بیکبار اعراض نمائیم، و حکم أنیبوا الی ربِکم، منقاد شویم، و امرِ توبوا الی اﷲ، امتثال کنیم، و موتوا قبل أن تموتوا بر نفس سرکش خوانیم، و ترک محرمات و منهیات از لوازم شمریم، و چون دیگر مریدان ملازمت گوشه ٔ سجاده ٔ مقدسه بر خود فرض گردانیم، تا از این میدان مردان، بو که سر بیرون بریم .شیخ الاسلام آن سخن به حضرت سلطان عرضه کرد، و گفت اگرمُجرمان عاصی و خاطیان ساهی، بر معاصی و مناهی اقدام ننمایند، پادشاهان لذت صواب و الکاظمین الغیظ و العافین عن الناس، از کجا یابند، و اگر مُجرمان مرتکب جرائم نگردند، ذوق اجر فمن عفی و اصلح، به کام خسروان زمانه چگونه رسد؟ شعر:<br />ترفق ایها المولی علیهم <br />فان الرفق بالجافی عتاب .<br />چون هست جهان بی وفا برگذران <br />گرهست ترا دسترسی برگذران <br />از هرکه گناه دیده ای عذر پذیر<br />وز هرکه جفا شنیده ای درگذران .<br />و سلطان در این باب اندیشه فرمود و در آن بود که جریمه ٔایشان را عفو کند، اتفاقاً در این میانه روزی جهت ملاحظت عمارت به قلعه رفت، و قتلغ طشتدار را هوس جان باختن و بر سر دار وطن گرفتن بر سر آمد، و زبان برگشاد، و ناسزا گفتن آغاز کرد، و گفت من در تدبیر آن بودم که دمار از نهاد تو برآرم، و به پدرت ملحق گردانم، چون دولت تو بیدار بود، و بخت من در خواب، فرصت نداد، اکنون توقف در کشتن من چراست . بیت :<br />وعده ای می ندهم، هین من و قتال و طناب <br />مهلتی می ننهم، هان من و جلادو دوال .<br />سر من برگیر و چنین و چنان کن، و الیأس ُ احدی الراحتین و دیر است تا گفته اند، بیت :<br />هرکه دست از جان بشوید<br />هرچه خواهد آن بگوید.<br />سلطان گفت با پدرم که نعم این جهانی به تو داد، و ترا از بندگی به خداوندی رسانید، چه کینه داشتی، و در حق آن ولینعمت چه اندیشه کرده بودی ؟ گفت به اشارت اتابک محمد سیدعلاءالدوله ده هزار دینار زر سرخ به من داد تاپدرت را در حَمام، حِمام دادم، و حَمام روحش را از قفس کالبد به صحرای ممات فرستادم . سلطان از این سخن عظیم در خشم رفت، و چشم مرحمت درهم نهاد، و به قتل آن محبوسان حکم فرمود، مثل : ان البلاء موکل ٌ بالمنطق، و هرچند سیدعلاءالدوله در جریمه ٔ اول معفو بود، بلی چون این کبیرة ضمیمه ٔ قضیه ٔ اول شد، و از میان آن قوم، اول الجریدة، و واسطةالقلادة، و سرالمسئلة، و بیت القصیدة او بود زلةالعالم یضرب بها الطبل، در تدبیر فوات او مشغول شد، و چون قتل چنان سیدی، مصراع : هم نبوت در نسب هم پادشاهی در حسب، از دینداری و نیکوکاری بعید بود در آن تلعمی میکرد، و توقفی میفرمود، و در آن وقت که از همدان بیرون میرفت، التماس کرد تا به مسافرت با وی موافقت کند و از وطن اصلی مهاجرت نماید، سیدعلاءالدوله تمارضی ساخت، و تکاسلی مینمود، اما چون سلطان در مبالغت افراط میکرد و در ارادت مصاحبت با وی الحاح میفرمود از مطاوعت چاره ندید و چون دو منزل از همدان بیرون شدند شیطان رجیم سلطان رحیم را از راه صواب بگردانید و بر آن داشت که به هلاک آن سید کریم اشارت کرد و او را زه برنهادند و مرقدش به همدان فرستاد و این حرکت مذموم بر سلطان مبارک نیامد و بدان واسطه کار و بار سلطنت و روز بازار مملکت بهم برآمدو سلطان مدتی در ششدره ٔ بلیت و بادیه ٔ نکبت افتاد واتابک ارسلان از آذربایجان به جنگ برخاست و سلطان تختگاه بگذاشت و روی به آذربایجان بنهاد و اتابک ارسلان از عقب سلطان برفت و اسباب و اموال بیشمار به تاراج داد و سلطان بعد از هزار حیله بجست و به قفچاق رفت و از دارالخلافه به اسم اتابک تشریفی و منشوری بفرستادند و کار مملکت بر او مقرر گشت و بعد از مدتی سلطان به همدان آمد اسباب پادشاهی را پشت پای زده و تخت فرماندهی بگذاشته و روی از عروس دنیی بدمهر، شعر:<br />شئوم مَلول ٌ لایدوم لصاحب <br />نشوزٌ فروک ٌ لایجیب لخاطب <br />بگردانیده و بر سر تربت اسلاف و اجداد خود که پادشاهان دین دار و کامکاران نیکوکار و منصفان ظالم برانداز و منتصفان مظلوم نوازبودند مقیم شده و بعد ذلک به مشورت و اشارت اتابک ارسلان امراء عراق و معتکفان خانه ٔ نفاق مخربان اساس وفاق از پی سلطان آفاق بیامدند و گفتند: به حکم سوابق حقوق سالفه و تربیت گذشته از اتابک ارسلان کرانه کرده ایم و از او برگشته و به خدمت آمده، اگر سلطان گناه ما ببخشد و ما را خلعت عفونا عما سلف پوشاند تا کمرخدمت بر میان جان بندیم و ملازم حضرت شویم . سلطان ازبدطالعی آن کلمات مجوف به توجه بشنید و بر ایشان مغلظه ٔ اَیمان که مخالفت آن محل مخالف ایمان باشد عرض کرد و وعده کرد که به میدان سورین عمد (؟) ملاقات مجدد گردانند و چون به میدان رسیدند امرا گرد چتر سلطان حلقه زدند و فخرالدین قتلغ که ننگ هر سگ دین بود شمشیری بر چتر سلطان زد و به اتفاق سلطان را بگرفتند وکردند آنچه کردند. فی الجمله زحمت و ناکامی سلطان متضاعف شد و محنت و بددولتی متزاید گشت و بنابر آنکه مصراع : برگ گل آسیب دندان برندارد بیش از این، فریادیا موت ان الحیوة ذمیمة، میزد و میگفت مصراع :<br />سیرم ز حیات محنت آگنده ٔ خویش .<br />و چون خبر این حادثه مشهور شد، اتابک ارسلان به همدان آمد، و ملک سنجربن سلیمان را از قلعه بخواند تا بر تخت سلطنت نشاند، ناگاه از دارالخلافه ملطفه ای به اتابک فرستادند، مشتمل بر آنکه ترا خود بر تخت سلطنت میباید نشست، به دیگری چه ضرورت، و به قبله ٔ دیگر چه حاجت، اتابک ارسلان را خود نیم اشارت تمام بود، و این اشارت بشارتی دانست، و به کاری که بدان منصوب بود، و به شغلی که بدان منسوب قناعت نکرد، و خود بر تخت سلطنت قرار گرفت و اذا اراد اﷲ هلاک نملة انبت لها جناحین . امراء عراق که در قصد و ایذاء ولینعمت اتفاق کرده بودند و هر یک خود را به مرتبه ای به اتابک مساوی بل راجح میدانستند و دم از نخوت میزدند با یکدیگر مشورت کردند و گفتند چون ما با سلطان طغرل با وجود حق نعمت و انتما به خانواده ٔ سلطنت بیمروتی کردیم و کمر کسر حال او بر میان بستیم دیگر بر ما چه اعتماد کند و کدام کس دوستی ما را وزنی نهد و مبادا که اتابک چون به مخالصت ما وثوقی ندارد در هلاک ما سعی کند و خواهد که غلامان خود را به منصب ما منسوب گرداند و به اتفاق برفتند و اتابک را بگرفتند و به قتل آوردند و روز دیگر مملکتی که مستحقی چون سلطان طغرل داشت بی خداوند پنداشتند و مانند میراث پدر و مادر بر خود قسمت کردند و هر یک مملکتی را در تحت حکم خویش گرفتند و بر عراق حاکم و فرمانروا گشتند. بیت :<br />بر بزرگان زمانه شده خردان سالار<br />بر کریمان جهان گشته لئیمان مهتر<br />بر در دونان احرار حزین و نالان <br />در کف رندان ابرار اسیر و مضطر.<br />و بعد از آنکه اتابک را کشته بودند رسولان اطراف به عزم دیدار او کالبرق الخاطف میرسیدند که می پنداشتند که بناء مملکت او برقرار است و اساس سلطنتش استوار و ندانستند که هر قاعده که بر خلاف اصل باشد دیر نپاید و هر بنا که بنیاد آن به باد هوس نهاده باشد زوداز پای درآید، مثل : ان للبطال حولة ثم یضمحل . و چون حال بدین منوال میدیدند متعجب و متحسر بازمیگردیدندو در اثناء راه آیندگان را میگفت بیت :<br />آن مصر مملکت که تو دیدی خراب شد<br />وآن نیل مکرمت که شنیدی سراب شد.<br />فی القصه مملکت عراق بر فخرالدین قتلغ و امرا قرار گرفت و صارت البئر المعطلة قصراًمشیداً و گمان بردند که الی ان یرث اﷲ الارض آن طول و عرض بخواهد ماند و الی قیام الساعة و ساعةالقیام، توسن فلک بدرام لگام کام و مرام در دست آن مغروران ایام بخواهد گذاشت . خود به زمانی اندک آن کار و بار بهم برآمد و بازار آن جمعیت آشفته شد. و سبب آن بود که اسفهسالار حسام الدین دزماری و چند کس دیگر که حقگذاری نعم و ایادی سلطان منقرض دانستند و شکر منعم عقلاً و شرعاً متحتم میشناختند جان بر کف نهاده و صاحب الحق احق به متاعه، برخواندند و سلطان را از قلعه بیرون آوردند و با لشکری چیده برچیده مصراع :<br />بدان امید که سعی فلک کند مشکور<br />روی به عراق نهادند و به در قزوین میان هر دو قوم اتفاق ملاقات افتاد و اسبان عراقیان گندم خورده بودند و از چاه نکبت سیراب شده و بدین واسطه قوت مصاف نداشتند و سلطانیان هست و نیست ایشان به تاراج ببردند. و عروس مملکت که یار قدیم سلطان بود برقع انداخت و کدخدای قضا و قدر در کشورجد و پدر بر سلطان دادگر برگشاد. بیت :<br />و الحمد ﷲ علی فضله <br />اذ رجع الحق الی اصله .<br />صداء گنبد پیروزه میدهد آواز<br />که آمد آب معالی به جوی دولت باز.<br />و سلطان بر تخت سلطنت قرار گرفت و بر سریر مملکت جای یافت و به زبان شکر میگفت : یا لیت قومی یعلمون . بما غفر لی ربی و جعلنی من المکرمین . و بفرمود تا فخرالدین قتلغ را بر دار کردند و در سنه ٔ تسع و ثمانین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٨٩</span> هَ . ق .) خواجه معین الدین کاشی را بردست وزارت نشاند و او را در حل و عقد امور مملکت نافذالامر گردانید و به فصل بهار به ری رفت و طبرک را بستد و خراب کرد و طمغاج خوارزمی را که از قِبَل ِ خوارزمشاه کوتوال قلعه بود کشته به تحفه به خوارزم فرستاد و ملک را از زحمت هر گدائی و مداخلت هر بی سروپائی خلاص داد و از اطراف و اکناف جهان روی به درگاه سلطان نهادند و طایفه ای از خدم و خول که همیشه میخواستندکه ملازم آستان معدلت آشیان سلطان باشند و در شدت و رخا یار غار و از پادشاه باسزا به زاری و نیاز و روزه و نماز حشمت و ملکداری و سلطنت و شهریاری او مسئلت میکردند و به حکم شعر:<br />وانی لارجو ان یعود زماننا<br />بوصل فمن بعد الشتاء ربیع<br />انجاح مقصود را منتظرمیبودند و میگفت بیت :<br />این دولت سرمستش هشیار شود روزی <br />وین بخت گران خوابش بیدار شود روزی <br />به حضرت سلطان آمدند و تختگاه رونقی تازه ورفعتی بی اندازه یافت و در محرم سنه ٔ تسعین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٩٠</span> هَ . ق .) جمعی از راه حسد و کوتاه همتی و حقد و فرعون طبعی تقبیح حال معین الدین کاشی بر حضرت سلطان ماضی بکردند و وزارت به خواجه فخرالدین پسر صفی الدین ورامینی تفویض فرمود و معین الدین را بگرفت و فخرالدین را به تمکینی هرچه تمامتر بر مسند تدبیر نشاند وخوارزمشاه تکش که کفران نعمت کار او و پیشه ٔ پدر بود و کابراً عن کابر به میراث یافته به مهمی روی به عراق نهاد و اتفاقاً در آن چند روز سلطان مقبل مقبول به عیش و طرب مشغول بود و از تدبیر کار ملک ملول و آمدن خوارزمشاه را وقعی ننهاد و ندانست که شرالسمک یکدر الماء و چون کارد به استخوان رسید و حکایت در تقویت جان و تخریب خان و مان میرفت سلطان لشکر آماده کرد و از همدان بیرون آمد و این دو بیت در آن وقت در سلک نظم آورد:<br />رباعی :<br />رو جوشن من بیار تا درپوشم <br />کاین کار مرا فتاد تا خود کوشم <br />تا هست به کف گرز و سپر بر دوشم <br />من ملک عراق را به جان نفروشم .<br />و یوم التقی الجمعان در شهر جمادی الاخری سنه ٔ تسع و ثمانین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٨٩</span> هَ . ق .) بود وچون از طرفین جنگ درپیوست و حمله کردند جمله ٔ امراءسلطان عصابه ٔ عقوق بر پیشانی ادبار بازبستند و جوشن بی حمیتی درپوشیدند و خود بیمروتی بر سر نهادند و سلطان به حکم آنکه گفته اند بیت :<br />چو مرد بر هنر خویش ایمنی دارد<br />شود بدیده ٔ دشمن به جستن پیکار<br />به نفس خویش مصراع :<br />علی مرکب کالریح تجری الموامیا<br />در میان میدان دشمنان رفت به امید آنکه مصراع :<br />مگر بخت نیکش بود رهنمای .<br />و لشکر از راه ستیز طریق گریز برگرفتند و سلطان را فریداً وحیداً بگذاشتند و چون سلطان پریشان حال گشت، و از دلیران کارزار و شیران آدمیخوار غایب ماند، جمله روی به وی نهادند و او را در حکم قید خویش آوردند و قتلغ اینانج قصد کشتن وی کرد و سلطان ظن برد که مگر او را یقین شود که او کیست به فوات او نکوشد و در آن کار عنان اختیار به دست شیطان بدکار مکار ندهد و خود از سر برگرفت مصراع :<br />فریاد ز دست خویش فریاد.<br />کالباحث عن حتفه بظلفه و الجادع مآرن انفه بکفه . قتلغ اینانج خود اورا میطلبید شمشیر عدوان از غلاف عصیان برکشید و از سر جهل با نفس بداصل گفت مصراع :<br />باری چو گنه کنی کبیره <br />و سلطان را شهید کردو به تحفه نزد خوارزمشاه برد. خوارزمشاه چون خصم راکشته دید و مقصود به حصول پیوسته یافت از اسب پیاده گشت و سجده ٔ شکر گزارد و سر سلطان به بغداد فرستاد و تن نازنین آن سپهدار تاجدار را در بازار ری بر دارکرد. بیت :<br />پادشاهی پادشاهی ایزد است، ایرا که او<br />جاودانه کامکار و پایدار و پادشاست .<br />گویند در میان معرکه کمال الدین شاعر را که از ندماء حضرت و مادحان درگاه سلطنت بود بگرفتند و پیش نظام الملک مسعود وزیر آوردند. وزیر باتدبیر با شاعر نیک تقریر گفت : آنهمه آوازه ٔ قوت و شجاعت و شوکت و مبارزت طغرل که در جهان افتاده بود خود این بود؟ کمال الدین برفور جواب داد که بیت :<br />ز بیژن فزون بود هومان بزور<br />هنر عیب گردد چو برگشت هور.<br /> <font color=\"Red\">(از العراضه صص <span class=\"hlight\" dir=\"rtl\">١٦٣</span> - <span class=\"hlight\" dir=\"rtl\">١٧٧</span>).</font><br />در ذیل تاریخ سلجوقنامه ٔ ظهیری نیشابوری تألیف ابوحامد محمدبن ابراهیم که بسال <span class=\"hlight\" dir=\"rtl\">٥٩٩</span> تألیف شده آورده : بعدما که هشت سال و دو ماه از واقعه ٔ سلطان طغرل بن ارسلان گذشته فریاد از نهادش <font color=\"DarkGreen\"><b>[ مؤلف ]</font></b> برآمد و این بیت از گفته ٔ سنائی در قلم آمد:<br />سر الب ارسلان دیدی ز رفعت رفته بر گردون <br />به مرو آ تا به خاک اندر تن الب ارسلان بینی .<br />سلطان طغرل پادشاهی با عدل و سیاست بود که در آل سلجوق ایزدتعالی در خلق و عدل و عفت و هنر و فرهنگ هیچ چیز از او دریغ نداشته بود. در مردی حیدر وقت و رستم عهد بود، در عدالت و سخاوت و بلاغت یگانه ٔ دهر، عالم دوست و درویش نواز. او را یک عیب بود که بر ساقه و مهانه و دمامه دولت افتاد و با تقدیر کوشش سود نمیداشت . تا اتابک محمد پهلوان در حیات بود سلطان و خلق عالم در رفاهیت و آسایش بودند و چون در ذی الحجه ٔ احدی و ثمانین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٨١</span> هَ . ق .) اتابک محمد ایلدگز متوفی شد به شهر ری و طغرل به ساوه بود با بعضی امرا و بعضی به ری در خدمت قتلغ اینانج و جمال ایبه چاشنی گیر و سیف الدین روس به اصفهان بودند، سلطان خواست که کار ملک به قواعد گذشته بازآورد چنانکه سلاطین بر دست امرا در خفیه و ملا کس میفرستادند به استدعای اتابک قزل ارسلان تا قزل با لشکری گران به در همدان آمد و به کوشک باغ ملاقات افتاد. زمره ٔ بدگویان و فتانان عراق او را بر سر سلطان و سلطان را بر او ناایمن کردند و کار سلطنت به وجود اتابک از دست برفت و اتابک کار سلطان بیکبارگی فروگرفت و بی حضور و مشورت طمع در ملک سلطان کرد. بعضی خواص سلطان را محبوس کرد و بعضی را به مال بفریفت و کار معاش بر سلطان تنگ گرفت بقول صاحب اغراض و جمال الدین ایبه و سیف الدین روس به مجاهر عصیان ظاهر کردند و در خفیه احوال با سلطان مینمودند، پس اتابک با سلطان روی به اصفهان نهادند و ایشان قصد ری کردند. اتابک بر اثر ایشان به ساوه رفت و آنجا الملک خاتون بنت اینانج در حباله ٔ عقد نکاح آورد و از آنجا به ری شدند و در محافظت سلطان اهتمام تمام میکردند و جمال ایبه و روس به سمنان شدند تا یک شب سلطان فرصتی یافت در جمادی الاولی ثلاث و ثمانین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٨٣</span> هَ . ق .) با خواص خویش از سر دولاب سوار شد و پیش ایبه و روس رفت به سمنان، اتابک و جمله لشکر بعقب او رفت یک روز فریقین مصاف روی باروی داد و اتابک با کثرت حشم و سپاه انبوه شکسته شد به ری بازآمد و سلطان دیه دایه که ملاحده داشتند حصار داد وبستد و خراب کرد. بعد از آن به مازندران شد و ملک آنجا خدمتی پسندیده تقدیم میداشت . بدگویان سلطان را متوحش گردانیدند تا یک روز که سلطان را مهمان خواست کردن سلطان بی آگاهی ملک برنشست و به راه ری به سمنان آمد. ملک متغیر و منفعل شد، کس فرستاد و تمهید عذر نمود و بیگناهی او بظاهر سلطان قبول کرد و اتابک در رمضان ثلاث و ثمانین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٨٣</span> هَ . ق .) به شهر آمد و امراء عراق آغاز مخالفت آغالیدن میکردند و به اراجیف آوازه ٔ سلطان می افکندند که می آید اتابک ناامید شد در چهارم رمضان سنه ٔ ثلاث و ثمانین و خمسمائة درشب ناگاه عزم آذربایجان کرد و بنه جمله برجای بماندند به در همدان و در آن وقت امیر ابوبکر به شهر بروجرد بود و سراج الدین قیماز به اصفهان به تعجیل برآمد و در نهم رمضان به همدان آمد و قتلغ اینانج از راه زنجان به محروسه ٔ ری شد و امیر ایاز به قلعه ٔ بهستان و در چهارم رمضان این سال وزارت به عزالدین تفویض افتاد و سراج الدین قیماز از اصفهان بیامد و با امیر ابوبکر متفق شد و روی به آذربایجان نهادند، در این وقت طغرل از راه بیابانک به ساوه آمد، فصل زمستان بود وامیر علمدار به همدان چون خبر مسیر ابوبکر شنیدند سلطان با جمعی جوانان و بزرگزادگان جهان نادیده در محرم اربع و ثمانین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٨٤</span> هَ . ق .) کرکهری رفت و راه ایشان بگرفت . امیر علمدار کشته شد با جمعی جوانان اکابر و چون فصل بهار درآمد قتلغ اینانج از ری پیش سلطان آمد و با هم متوجه آذربایجان شدند. اراجیف آوازه ٔ آمدن اتابک به عراق میدادند. در آخر صفر این سال خبر متواتر شد که وزیر بغداد با پانزده هزار سوار بقصد ملک عراق و مدد اتابک میرسند. سلطان از کنارسپیدرود به تاختن به دو شبانروز به دای مرج آمد ششم ربیعالاول اربع و ثمانین و خمسمائة با او سپاهی قلیل مانده بود، با لشکر بغداد مصاف داد و ایشان را بفور بشکست و وزیر ابن یوسف را بگرفت و چون خبر عساکر بغداد در افواه میدادند اتابک میخواست به عراق راند، چون سلطان به همدان آمد اتابک به یک منزلی رسیده بود، سلطان به کوشک مهران فرودآمد و اتابک به کوشک کهن نزول کرد و مدت یک ماه کمابیش میان ایشان جنگ قائم بود و کار بر لشکر اتابک تنگ شد، باز به اراجیف آوازه ٔ لشکر بغداد میدادند. اتابک بدان سبب برخاست و به ولایت اسدآباد رفت و سلطان در جمادی الاولی این سال به کوشک کهن، ایبه و ازابه که دو بنده ٔ بزرگ قدیمی بودند بکشت بجهت استیلا که میکردند و بدین سبب قتلغ اینانج مستوحش و منکر شد. علاءالدین تلاس بِرس و قتلغ اینانج برنشستند و به ری شدند بی اذن سلطان و سلطان جهت مراقبت خاتون بُنه ٔ او را از پس او بفرستاد و علاءالدین رااستمالت و استعطاف فرمود و یکی از پسران خویش به وی داد و دستوری داد تا روان شد و سلطان به آذربایجان شد و ملک ارمن به خدمت شتافت و امیر علم را از قلعه خلاص داد. اتابک با لشکر بغداد و اسدآباد به همدان آمدند و در ماه رجب این سال خطبه و سکه ٔ ممالک بنام سنجربن سلیمان شاه کردند و بعد از یک چند میان اتابک و سپاه بغداد وحشتی خاست . اتابک عزم آذربایجان کرد و بغادده بازگشتند. سلطان روی به عراق نهاد و در هفتم ذی الحجه ٔ این سال چون زمستان درآمد سلطان خواجه عزیز را با دو پسر موفق و حیدر و قتلغ بفرمود تا هلاک کردند و قتلغ اینانج در این تاریخ به اصفهان آمد با لشکرگران، از قِبَل ِ سلطان ازدمر شحنه ٔ اصفهان بود چنانچه معهود اصفهانیه است در شهر دوهوایی ظاهر شد و یک چند جنگ و جدل قائم بود پس ازدمر مستغاث و فریادنامه به سلطان مینویسد و سلطان بسبب زمستان تأخیر و تقصیر میکرد در رفتن تا در صفر خمس و ثمانین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٨٥</span> هَ . ق .) شهر که ازدمر داشت بستدند و او را بکشتند. سلطان اول بهار قصد اصفهان کرد. قتلغ اینانج بالشکر خویش از پیش برخاست و سلطان از پس میرفت تا اززنگان بگذشتند و قتلغ اینانج پیش عم خویش قزل ارسلان میرفت و او را بزودی با لشکر بسیار به عراق آورد و سلطان را حشم اندک بود خواست که به اصفهان رود جماعتی غدر کردند و در نهان ملطفه ها مینوشتند، و عزم سلطان از اصفهان باطل کرد تا اتابک به همدان رسید سلطان به راه بروجرد برون شد و اتابک با لشکر بسیار در عقب سلطان میرفت . سلطان را دوهوائی لشکر خویش معلوم شد، مصاف نداد، همچنان میرفت و اتابک در پی او تا جمله ٔ بنه و خزانه و اسباب و آلات از او بازماندند و لشکریان بعضی پیش اتابک گریختند و دیگران دست از هم بدادند. سلطان با زمره ٔ خواص رو به آذربایجان نهاد و در میان خیل عزالدین قفچاق رفت و با او وصلتی و پیوندی کرد تا باز لشکر و اسباب مهیا شد کار سلطان بالا گرفت، رسولی به دارالخلافه فرستاد و عذر مقاومتی که وزیر بااو کرده بود بخواست و چون رسول بازآمد درخواست کرده بودند که پسری ازآن ِ خویش اینجا فرستد، جهت دیوان عزیز پسری آنجا فرستاد و بعد از آن به اختیار حسن قبچاق روی به آذربایجان نهاد و چون سلطان رفت اتابک به همدان آمد و سنجربن سلیمان را بر تخت نشاند. بعد از یک چند خبر آمد که سلطان با ده هزار سوار قفچاق به آذربایجان رسید و خرابی میکند. اتابک مستشعر شد و عزم آذربایجان کرد و به مقابله ٔ سلطان فرودآمد اما طاقت مقاومت نداشت، حیله کرد و رسولان آمدوشد نمودند و عهدی میان ایشان برفت که فیمابعد اتابک قصد قبچاق نکندو به سلطان گذارد بدین شرط مغلظه تمهید یافت و چون سلطان ایمن شد لشکر قفچاق را پراکنده کرد در ولایات واجازه داد و اتابک منتهز فرصت بود ناگاه بر سر سلطان تاختند و او را هزیمت کرد. او روی به همدان نهاد ودر آن زمان اندک مایه تکسری داشت تا به همدان رسیدن چند جایگاه با اتابک جنگ کرده بود و مصاف داده با صد مرد به همدان رسید. اتابک حشمی ساخته بر اثر او بفرستاد تا راه اصفهان نگاه دارد تا اتابک برسید سلطان از سر ضرورت و مصلحت وقت رسم استقبال تمهید نمود حالی که به اتابک رسید از گرد راه سلطان را فروگرفتند در رمضان ست و ثمانین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٨٦</span> هَ . ق .) و بعداز دو روز او را و ملکشاه پسرش را به آذربایجان فرستاد به قلعه ٔ کهران به ولایت جبال بر کنار آب ارس موازی کران و ابراهیم آباد و اتابک را جمله بلاد عراق مستخلص گشت و بر جلوس او به سلطنت قرار افتاد، رسوم سلطنت آل سلجوق منقطع و منخفض شد و چون اسباب سلطنت تمام بساخت و از حل و عقد امور بپرداخت در شوال سبع و ثمانین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٨٧</span> هَ .ق .) به کوشک کهن به در همدان اتابک قزل را کشته یافتند پنجاه زخم کارد بر اندام او زده . لشکریان از جنگ دست بداشتند و چون خبر واقعه ٔ اتابک قزل به آذربایجان منتشر شد اتابک ابوبکر همان شب به آذربایجان شد وتعزیه ٔ قزل بداشتند. قتلغ اینانج و والده اش با ری شدند و والی همدان بدرالدین قراکر اتابکی بود و رئیس مجدالدولةبن علاءالدولة قلعه ٔ همدان عمارت کردند و دراثنای آن خبر رسید که طغرل از قلعه خلاص یافته است . چون خبر محقق شد مجدالدوله امیدوار شد، بشارت بزد و خواست که قراکر را از شهر بیرون کند چهار روز محله ٔ اتابکیان با قراکر تا محلات مجدالدوله جنگ کردند و بعد از آن زلزله ای صعب پیدا شد بدین سبب دست از جنگ بداشتند و چون خبر واقعه ٔ اتابک قزل منتشر شد کوتوال قلعه ٔ کهران به معاونت محمود ایاسغلی و بدرالدین دزماری سلطان را از بند خلاص دادند تا از آنجا به تبریز آمد و هر روز از جوانب سپاه بر او جمع میشدند. سلطان روی به عراق نهاد با سه هزار مرد و نورالدین قرابادی و عمر پسر شرف الدوله به سرخه سوار بود و قتلغ اینانج با دوازده هزار سوار همه مردان شیردل و مبارزان صف گسل روی بدو نهادند و به ظاهر قزوین روز آدینه پانزدهم جمادی الاَّخرة <span class=\"hlight\" dir=\"rtl\">٥٨٨</span> مصاف دادند. سلطان ظفر یافت و قتلغ اینانج منهزم شد و سلطان به همدان رفت . خوارزمشاه تکش بن ارسلان بن اتسزبن محمدبن نوشتکین آگاه شد، غیرت و حمیت در نهاد او سر زد و خواست که حقگزاری نعمت خاندان سلجوقی کند و مدد فرستد اما چون محبوس بود در توقف داشت و نیز او را با برادر خویش سلطانشاه محمودبن ایل ارسلان مناقشت و معاتبت قائم بود نتوانست معاونه ٔ او کردن . چون اتابک را واقعه افتاد ملک معطل و مهمل ماند، سلطان خوارزمشاه هم به طلب و هم به حقگزاری روی به عراق نهاد و چون به ری رسید سلطان از قید خلاص یافته بود و قتلغ اینانج را شکسته و جوانب لشکرها به وی پیوسته، در این وقت قتلغ اینانج با مادر خود خاتون به ری آمد از پیش لشکر خوارزم به قلعه ٔ سرجهان پناهید و سلطان با لشکر فراوان به درِ ری به سردولاب فرودآمد و در جمادی الاَّخره ٔ ثمان و ثمانین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٨٨</span> هَ . ق .) خوارزمشاه چون کار به نوعی دیگر دید و با طغرل لشکری تمام نبودطمع در ملک عراق کرد به طغرل پیغام فرستاد که در جمله ٔ عراق باید که سکه و خطبه بنام ما باشد، بعد از ذکر خلیفه ذکر من کنند. چند بار رسولان آمدوشد کردند، قرار شد که به خوارزمشاه بازگذارد بر این عهد و قرارخوارزمشاه بازگشت و جماعت اتابکیان قرآن خوان و قراگز و میاق و قتانه و شمله کش در این وقت به ولایت جرفادقان بودند. چون خوارزمشاه بازگشت این جماعت بر اثر او نرفتند و او را بر نقض عهد و میثاق بازداشتند. خوارزمشاه برگشت سلطان والده ٔ قتلغ اینانج را در عقد نکاح خویش درآورد و در رمضان ثمان و ثمانین و خمسمائة او را از قلعه ٔ سرجاهان به همدان آورد و قتلغ اینانج به آذربایجان رفت و لشکر از اطراف رو به وی نهادند، با برادر خود ابوبکر مقاومت کرد، بعد از سه چهار مصاف ابوبکر مظفر آمد و در محرم تسع و ثمانین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٨٩</span> هَ . ق .) طغانشاه بن مؤید از لشکر خوارزم منهزم شده پیش سلطان آمد و در ربیعالاول این سال معین الدین وزیر را فروگرفتند بسبب آنکه ملطفه ای به بغداد نوشته بود و چون نقض عهد خوارزمیان به مظان رسید به ری رفت . خوارزمیان بر قلعه گریختند، حصار داد و بستد، بعضی را بکشتند و دیگران بگریختند و در شعبان این سال سلطان بفرمود تا آن قلعه خراب کردند و وزارت باز به معین دادند و سلطان بیمار شد و به همدان آمد و شحنه با وزیر به ری بگذاشت و در این حال قتلغ اینانج منهزم از آذربایجان به قزوین آمد و مظفرالدین باردار با او متفق شد، قصد ری کرد، شحنه و وزیر با ساوه آمدند و از آنجا به همدان شدند. سلطان امیر علم را در شوال این سال با چهار هزار سوار به ری فرستاد. قتلغ اینانج منهزم شد و به دامغان رفت . بعد از یک چند امیر علم بیمار شد. قتلغ اینانج انتهاز فرصت یافته به خوارزمیان پناهید و سلطان به ساوه آمد. امیر علم را در محفه ای به همدان بردند و سلطان در ذی الحجه ٔ این سال عزم ری کرد با سپاهی جرار. قتلغ اینانج به دامغان رفت بر پی او به جوار <font color=\"DarkGreen\"><b>[ خوار ؟ ]</font></b> ری آمد. قتلغ اینانج را هفت هزار سوار خوارزمی از سلطان تکش مدد آمد. در چهارم محرم سنه ٔ تسعین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٩٠</span> هَ . ق .) به درِ ری مصاف دادند. قتلغ اینانج و خوارزمیان شکسته شدو بسیار گرفتار شدند. قتلغ اینانج به گرگان رفت و در این فتح این دو بیت گفته اند:<br />ای پیش عزیزان تو خوارزمی خوار<br />وی خنجر برّان تو خوارزمی خوار<br />زین بیش نیارد که ببیند در خواب <br />از جمله ٔ سمنان توخوارزمی خوار.<br />طغرل به ری آمد و معین الدین وزیر را بگرفت . آوازه ٔ آمدن خوارزمشاه متواتر شد و از اتفاق بد و قضای آسمانی سلطان همه روزه شراب میخورد و لشکریان در استجماع تهاون میکردند و امراء معروف بعضی ملطفات به خوارزمشاه مینوشتند و او را بقصد سلطان اغراء میکردند تا در منافصه ٔ (ظ: مناصفه ٔ) روز پنجشنبه ٔ آخر ربیعالاول سنه ٔتسعین و خمسمائة خوارزمشاه تکش با لشکری بی حد و عدّ و حشمی بی حصر و ومد (کذا ؟) به دروازه ٔ ری فروآمد. طغرل از تهور و قضاء بد و با اندک مایه ٔ حشم مصاف داد بر قلب مقدمه ٔ سپاه خوارزم زد بتنها بی معاونت وموافقت سپاه، او را بتنها در میان گرفتند و چون نفس معدوده به آخر رسید هیچ حیله ای او را دفع نکند اعداء و اضداد او را بر آن داشتند تا سر او را از تن جداکرد و به بغداد فرستاد و تن او را در میان بازار ری بیاویخت . بزرگی در آن روز گفته :<br />امروز شها زمانه چون دل تنگ است <br />فیروزه ٔ چرخ هر زمان یک رنگ است <br />دی از سر تو تا به فلک یک گز بود<br />امروز ز سر تا بدنت فرسنگ است .<br />و بعد از او در عراق هیچ آفریده ای رفاهیت و آسایش و معدلت نیافت و خاندانهای قدیم برافتادند. شعر:<br />خلق است همه معجب و صدرنگ اکنون <br />دوری است تهی ز صلح و بر <font color=\"DarkGreen\"><b>[ پُر ؟ ]</font></b> جنگ اکنون <br />از تنگی انصاف و فراخی ستم <br />یارب چه فراخ است دل تنگ اکنون .<br /> <font color=\"Red\">(نقل از مجله ٔ مهر سال <span class=\"hlight\" dir=\"rtl\">٢</span> شماره ٔ <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٢٤١</span> - <span class=\"hlight\" dir=\"rtl\">٢٤٤</span>).</font><br />عوفی آرد: السلطان الشهید طغرل سقی اﷲ ثراه، سلطان ممالک آفاق و خسرو تمامت عراق، پادشاهی که توسن ایام رام زین امکان او بود و ابلق روزگار مرتاض حکم و فرمان او، چون بر سریر مملکت استقرار یافت دانست که دولت معشوقی بیوفاست و عمر حریفی گریزپاست، خواست که داد از روزگار بستاند و آن اندک حیات مستعار را به خوشی و خرمی گذراند، روی به تعاطی اعقار آورد و شب و روز با شاهدان تیراندازبادام تیغزن غمزه ٔ زره پوش زلف شکرفروش لب به عشرت و تماشا مشغول شده بزم را بر رزم اختیار کرد، لاجرم اختلال در کار پادشاهی پدید آمد و سلک دولت از نظام بگسیخت و اتابک قزل ارسلان که از بنده زادگان او بود بر وی برون آمد و او را مقید گردانید و ملک فروگرفت . در آن حالت این رباعی در نظم آورده است سخت مطبوع و لطیف است . میگوید:<br />در بند غمم گره گشایا مپسند<br />وین کاهش جاه جان فزایا مپسند<br />وز بنده و بنده زاده ای چندین ظلم <br />بر خواجه ٔ خویشتن خدایا مپسند.<br />و در آن وقت که ملک مؤید به حرب او رفت و ناگاه به سر او رسید و او را اعلام دادند برفور به سلاح دار اشارت کرد و گفت :<br />آن جوشن من بیار تا درپوشم <br />کاین کار مرا فتاد هم درکوشم <br />تا در تنم است جان و سر بر دوشم <br />من ملک عراق را به سر نفروشم .<br />و در وقت استخلاص بلاد ارمن و ارّان گفت :<br />ای دل به هوای ارمن ارمن باشم <br />بیرون نکنم حزن ز دل زن باشم <br />وی چرخ اگر به حیله بیرون نکنم <br />گاو تو از آن خرمن خر من باشم .<br />و او را ابیات لطیف بسیاراست اما اینقدر بر خاطر بود ایراد کرده آمد. (لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٤١</span>-<span class=\"hlight\" dir=\"rtl\">٤٢</span>). و نیز رجوع به لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٦</span>، <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>، <span class=\"hlight\" dir=\"rtl\">٣٦٠</span> و تتمه ٔ صوان الحکمة حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span>و تاریخ الدولة السلجوقیة تألیف علی بن ناصربن علی الحسینی چ محمد اقبال ص <span class=\"hlight\" dir=\"rtl\">١٦٩</span>، <span class=\"hlight\" dir=\"rtl\">١٧١</span>، <span class=\"hlight\" dir=\"rtl\">١٩٤</span>، <span class=\"hlight\" dir=\"rtl\">١٩٥</span>، <span class=\"hlight\" dir=\"rtl\">١٩٦</span>، <span class=\"hlight\" dir=\"rtl\">١٩٧</span> و حبیب السیر چ خیام فهرست ج <span class=\"hlight\" dir=\"rtl\">٢</span> شود.<br /></font></div>'),
(177141, 'طغرل', '<span class=\"hlight\">طغرل .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ]</font></b> (اِخ ) ابن سنقربن مودود. چهارمین تن از اتابکان سلغری (<span class=\"hlight\" dir=\"rtl\">٥٩١</span> تا <span class=\"hlight\" dir=\"rtl\">٥٩٩</span> هَ . ق .). لقب وی قطب الدین است . پادشاهی هنرپرور و معدلت گستر بود و در بعضی از حدود عراق حکومت میکرد اما تأییدی نداشت زیرا که چند نوبت به جنگ تکله مبادرت نموده هر بار انهزام یافت و آخرالامر گرفتار شده به قتل رسید. (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٦٠</span>). اتابکی طغرل نُه سال طول کشیدو تمام آن صرف زد و خورد با سعدبن زنگی پسرعم او گردید و سعدبن زنگی سرانجام در سال <span class=\"hlight\" dir=\"rtl\">٥٩٩</span> هَ . ق . بر اتابک طغرل غلبه یافت و طغرل را دستگیر کرد و خود اتابک فارس گردید. (تاریخ مغول اقبال صص <span class=\"hlight\" dir=\"rtl\">٣٨٢</span>-<span class=\"hlight\" dir=\"rtl\">٣٨٣</span>، <span class=\"hlight\" dir=\"rtl\">٣٩٩</span>).<br /></font></div>'),
(177142, 'طغرل', '<span class=\"hlight\">طغرل .</span> <font color=\"DarkGreen\"><b>[طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ]</font></b> (اِخ ) بهاءالدین . صاحب حبیب السیر در ذیل وقایع ایام سلطنت سلطان غیاث الدین غوری گوید: بهاءالدین طغرل یکی از غلامان سنجری بود و در هرات حکومت مینمود. رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٠٦</span> شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177143, 'طغرل برار', '<span class=\"hlight\">طغرل برار.</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ب َ ]</font></b> (اِخ )رجوع به طغرل غاصب و تتمه ٔ صوان الحکمة ص <span class=\"hlight\" dir=\"rtl\">١٨٣</span> شود.<br /></font></div>'),
(177144, 'طغرل بیک', '<span class=\"hlight\">طغرل بیک .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ب َ ]</font></b> (اِخ ) (طغرل اول ) محمدبن میکائیل بن سلجوق بن دقاق، ملقب به رکن الدین و الدوله، المکنی به ابوطالب (<span class=\"hlight\" dir=\"rtl\">٤٢٩</span> تا <span class=\"hlight\" dir=\"rtl\">٤٥٥</span> هَ . ق .). درراحةالصدور آورده که : در شهور سنه ٔ اربع و عشرین و اربعمائة سلطنت آغاز کرد و سیر حمیده ٔ ملوک پیش گرفت و آئین جهانداری و رسوم شهریاری ظاهر کرد. حکمت : قال اردشیربن بابک : حقیق ٌ علی کل ملک أن ْ یتفقد وزیره و ندیمه و کاتبه و حاجبه فان وزیره قوام ملکه و ندیمه بیان عقله و کاتبه برهان فضله و حاجبه دلیل سیاسته ؛ اردشیر بابک گفت : پادشاه باید که وزیری را به دست آرد و حاجبی را بگمارد وندیمی را بدارد و دبیری را بیارد که وزیر قوام مملکت بود و ندیم نشان عقل شود و دبیر زبان دانش او باشدو حاجب سیاست افزاید. بر قضیت این اثر و ترجمت این خبر سلطان طغرل بک و جمله ٔ سلاطین، وزرا و حُجّاب و اصحاب مناصب داشتند، وزرای او سالار بوژگان ابوالقاسم الکوبانی و ابواحمد الدهستانی عمروک و عمیدالملک ابونصر الکندری، حُجّاب او الحاجب عبدالرحمن الب زن الاَّغاجی، توقیع او فی شکل چماقی، مدت ملکش بیست وشش سال . چون ملک تعالی بنده ای را سعادت ابدی کرامت خواهد کرد و در دنیا و عقبی منزلت اخیار و ابرار ارزانی داشتن او را بر اِعلای معالم شریعت حریص گرداند و در جوهر مطهر و سینه ٔ پاک او حرصی نهد بر تقدیم آنچه از برکات آن ملک عالم در قبضه ٔ اقتدار او آید و عالمیان غریق و رهین احسان او گردند و مُثنی و شاکر عدل و انصاف او شوند و رایات ملک اسلام از رای صائب او نصرت یابد و آفتاب جاه و حشمت او بر کافّه ٔ خلایق مشرق و مغرب تابد و هرچند رُبع مسکون است از بسیط زمین به امارات و ابنیه ٔ خیرات سلاطین آل سلجوق آراسته است و هیچ شهری از شهرهای اسلام از آن زینت و حلیت خالی و عاطل نمانده است و تقدیم آن بر اُمهات مهمات واجب دانسته اند. شنیدم که چون سلطان طغرلبک به همدان آمد از اولیا سه پیر بودند، باباطاهر و باباجعفر و شیخ حمشا، کوهکی است بر در همدان آن را خضر خوانند، بر آنجا ایستاده بودند. نظر سلطان بر ایشان آمد، کوکبه ٔ لشکر بداشت وپیاده شد و با وزیر ابونصر الکندری پیش ایشان آمد ودستهاشان ببوسید. باباطاهر پاره ای شیفته گونه بودی، او را گفت ای تُرک با خلق خدا چه خواهی کرد؟ سلطان گفت آنچه تو فرمائی . بابا گفت آن کن که خدا می فرماید، آیة: ان اﷲ یأمر بالعدل و الاحسان . سلطان بگریست و گفت چنین کنم . بابا دستش بستد و گفت از من پذیرفتی ؟ سلطان گفت آری . بابا سر ابریقی شکسته که سالها از آن وضو کرده بود در انگشت داشت بیرون کرد و در انگشت سلطان کرد و گفت مملکت عالم چنین در دست تو کردم، بر عدل باش . سلطان پیوسته آن در میان تعویذها داشتی و چون مصافی پیش آمدی آن در انگشت کردی . اعتقاد پاک و صفای عقیدت او چنین بود و در دین محمدی صلی اﷲ علیه و آله و سلم از او دیندارتر و بیدارتر نبود. شعر :<br />در آن بخشش که رحمت عام کردند<br />دو صاحب رامحمد نام کردند<br />یکی ختم نبوت گشت ذاتش <br />یکی ختم ممالک در حیاتش <br />یکی بُرج عرب را تا ابد ماه <br />یکی ملک عجم را جاودان شاه <br />یکی دین را ز ظلم آزاد کرده <br />یکی دنیا به عدل آباد کرده <br />زهی نامی که کرد از چشمه ٔ نوش <br />دو عالم را دو میمش حلقه در گوش <br />ز رشک نام او عالم دو نیم است <br />که عالم را یکی او را دو میم است <br />به ترکان قلم از نسخ تاراج <br />یکی میمش قلم بخشد یکی تاج .<br />چون سلطنت او مقرر شد و عظمت او هرروز در زیادت بود خبر به مسعود رسید، به تن خویش ازغزنین بیامد با لشکری و عُدّتی تمام و به راه بُست و تکیناباد به خراسان آمد تا انتقام لشکر کشد. مثل : لیس من عادةالکرام سرعةالانتقام و لا من شرطالکرم ازالةالنعم ؛ سرعت انتقام از عادت کرام نیست و ازالت نِعَم از شرط کرم دور است، و در این حال طغرلبک به طوس بود از برادر جدا سلطان مسعود خواست که تاختن برد و نگذارد که برادران به هم پیوندند. چون شب آمد بر ماده پیلی سبک رو و با لشکری جریده روی به طوس نهاد، بیست وپنج فرسنگ مسافت بود، بر پشت پیل در خواب شد. مصراع :<br />ترسم چو تو بیدار شوی روز بود.<br />کس نیارست او را بیدار کردن و پیل را تند راندن . چون روز شد خبر رسید که طغرل بک بگذشت و به برادر چغری بک پیوست . سلطان پیلبان را سیاست فرمود. مثل : و الفائت لایستدرک . مسعود از آنجا بازگشت و جنگ بساخت و در بیابانی که میان سرخس و مرو است با سلجوقیان مصاف داد و در آن بیابان چند جا آب بود سلجوقیان آب برداشته بودند و چاه انباشته . مثل : نظر العاقل بقلبه و خاطره و نظر الجاهل بعینه و ناظره ؛ دانا به دل و خاطر نگرد و نادان ظاهر بیند. لشکر مسعود و ستوران از تشنگی به ستوه آمدند و با زخم شمشیر ایشان نمی شگیفتند، عاقبت پشت بدادند. مثل : من رضی بالمقدور قنع بالمیسور. و مسعود چون خود را تنها دید عنان بگردانید و با پیل نشست که اسب او را به دشخواری کشیدی و روی به هزیمت نهاد و خزانه و بنه و ثقل و اسباب و تجمل بجای ماند و خود براند. شعر:<br />که داند که چندین نشیب و فراز<br />پدید آرد این روزگار دراز<br />تک روزگار از درازی که هست <br />همی بگذراند سخنها ز دست <br />بکندیم دل زین سرای سپنج <br />ز بس درد و سختی و اندوه و رنج <br />سزد گر بگویم یکی داستان <br />که باشد خردمند همداستان <br />مسای ایچ با آز و با کینه دست <br />زمنزل مکن جایگاه نشست <br />سرای سپنج است پُر آی و رو<br />یکی شد کهن دیگر آرند نو<br />یکی اندرآید دگر بگذرد<br />زمانی به منزل چمد یا چرد<br />جهان را چنین است ساز و نهاد<br />از این دست بستد به دیگر بداد.<br />چون سلطان مسعود به هزیمت میرفت ترکمانی چند بر اثر او میراند، مسعود از پیل بر اسب نشست و حمله برد و گرز بر سر سواری زد و او را و اسبش را بر جای خرد بشکست . هر فوج لشکر که بدانجا میرسید و آن زخم میدید از آنجا نمیگذشت . مثل : الفضل بالعقل و الادب لا بالاصل و النسب ؛ که را با فضل و ادب اصل و نسب جمع باشد دهان روزگار از او خندد و دور فلکش پسندد. شخصی در آن حال مسعود را گفت ای خداوند کسی را که این زخم بود هزیمت رود؟ مسعود گفت : زخم این است اما اقبال نیست . مثل : عداوةالعاقل خیر من صداقةالجاهل . شعر:<br />چو دشمن که دانا بود به ز دوست <br />ابا دشمن و دوست دانش نکوست .<br />و سلجوقیان چون این مصاف بشکستند بیکبارگی قوت گرفتند و لشکرهای پراکنده در اطراف خراسان بدیشان پیوست و در دلها وقعی تمام پدید آمد و ملک مقرر و جهان مسخر شد و سزاواری جهانداری داشتند. شعر:<br />قضی اﷲ امراً و جف ّ القلم <br />و فیما قضی ربنا ماظلم .<br />پس هر دو برادر چغری بک و طغرلبک و عم ایشان موسی بن سلجوق که او را یبغو کلان گفتندی و عمزادگان و بزرگان خویشان و مبارزان لشکر بهم بنشستند و عهدی بستند در موافقت با یکدیگر و شنیدم که طغرل بک تیری به برادر داد و گفت بشکن . او بدانچه مبالات نمود خُرد کرد، دو بر هم نهاد همچنان کرد، سه بداد دشخوار می شکست، چون به چهار رسید شکستن متعذر شد. طغرل بک گفت مثل ما همچنین است، تا جداگانه باشیم هر کمتری قصد شکستن ما کند و به جمعیت کس بر ما ظفر نیابد و اگر در میان خلافی پدید آید جهان نگشاید و خصم چیره شود و ملک از دست ما برود. شعر:<br />اگر دو برادر نهد پشت پشت <br />تن کوه را سنگ ماند به مشت <br />دلی کو ز درد برادر شخود<br />علاج پزشکان نداردش سود.<br />مثل : لا سایس مثل العقل و لا حارس مثل العدل و لا سیف مثل الحق و لا قول مثل الصدق ؛ چو عقل سایسی و بهتر از عدل حارسی نیست و حق شمشیری قاطع است و صدق برهانی ساطع. آنگه به اتفاق بر مقتضای عقل و کفایت نامه ای نبشتند به امیرالمؤمنین القائم بامراﷲ که ما بندگان آل سلجوق گروهی بودیم همواره مطیع و هواخواه دولت وحضرت مقدس نبوی و پیوسته به غزو و جهاد کوشیده ایم وبر زیارت کعبه ٔ معظم مداومت نموده و ما را عمّی بوددر میان ما مقدم و محترم اسرائیل بن سلجوق، یمین الدوله محمودبن سبکتکین او را بی جرمی و جنایتی بگرفت و به هندوستان به قلعه ٔ کالنجر فرستاد و هفت سال در بند داشت تا آن جایگه سپری شد و بسیاری پیوستگان و خویشان ما را به قلاع بازداشت و چون محمود درگذشت و پسرش مسعود بجای او بنشست به مصالح ملک قیام نمینمود و به لهو و تماشا مشغول میبود. مثل : من آثر اللهو ضاعت رعیته و من آثر الشرب فسدت رویته ؛ هرکه لهو برگزیند رعیت را نبیند و هرکه مداومت شرب کند رویتش تباه شود. لاجرم اعیان و مشاهیر خراسان از ما درخواستند تا به حمایت ایشان قیام نمائیم . لشکر او روی به ما نهادند، میان ما کر و فر و هزیمت و ظفر میبود تا عاقبت بخت نیک روی نمود و دست بازپسین مسعود به نفس خویش با لشکری گران روی به ما نهاد. به یاری خدای عزوجل و به اقبال حضرت مقدس مطهر نبوی دست ما غالب آمد و مسعود شکسته و خاکسار و عَلَم نگوسار پشت برگاشت و اقبال ودولت به ما گذاشت . مثل : من اطاع اﷲ ملک و من اطاع هواه هلک ؛ مطیع خدا مالک گردد و مطیع هوا هالک شود. شکر این موهبت و سپاس این نصرت را عدل و انصاف گستردیم و از راه بیداد و جور کرانه کردیم و میخواهیم که این کار بر نهج دین و فرمان امیرالمؤمنین باشد. مثل :من جعل ملکه خادماً لدینه انقاد له کل سلطان و من جعل دینه خادماً لملکه طمع فیه کل انسان ؛ هرکه ملک ازبرای دین جوید سلاطین منقاد او شوند و هرکه دین فدای ملک کند هر کس بدو طمع کند. و این نوشته بر دست معتمد ابواسحاق الفقاعی بفرستادند و در آن وقت وزیر و پیشکار و دستور و کارگزار سالار بوژگان بود. چون این نامه روانه شد ولایت قسمت کردند و هر یکی از مقدمان به طرفی نامزد شد، چغری بک که برادر مهتر بود مرو را دارالملک ساخت و خراسان بیشتر خاص کرد و موسی یبغو کلان به ولایت بُست و هرات و سیستان و نواحی آن چندانکه تواند گشود نامزد شد و قاورد پسر مهین چغری بک به ولایت طبسین و نواحی کرمان و طغرلبک بسوی عراق آمده و ابراهیم ینال که برادرش بود از مادر، و پسر برادر امیر یاقوتی بن چغری بک داود، و پسرعمش قتلمش بن اسرائیل در خدمت او بودند. چون ری مستخلص کرد و آنجا دارالملک ساخت ابراهیم ینال را به همدان فرستاد و امیر یاقوتی را به ابهر و زنگان و نواحی آذربایجان و قتلمش را به ولایت گرگان و دامغان فرستاد. حکمت : ای ّ ملک احسن الی کفاته و اعوانه استظهر بملکه و سلطانه ؛ هر ملک که نیکی کند با دانایان و اعوان لشکرش مستظهر شود به ملک و سلطنت کشورش . و الب ارسلان محمدبن چغری بک داود برادرزاده ٔ او در خدمت بود و در مهمات و معضلات ایثار رضا و تحری فراغ او جستی و گفتی . شعر:<br />رضاک رضای َ الذی اُوثر<br />و سرک سری فمااُظْهِر.<br />چو نامه ٔ ایشان به دارالخلافه رسید امیرالمؤمنین القائم بامراﷲ هبةاﷲبن محمد المامونی را با رسول پیش طغرلبک فرستاد به ری و پیغامهای خوب داد و هبةاﷲ را که سِمَت اختصاص و صفت اخلاص داشت فرمود که نزدیک او باشد تا او را به بغداد آرد و بغداد را تشریف حضور او حاصل کند که فرصت وصال چون زمان خیال گذرنده است . هبةاﷲ مدت سه سال آنجا بماند بحکم آنکه طغرلبک را از ناحیتها و گرفتن ولایتها فراغت بغداد نبود ودر سنه ٔ سبع و ثلثین و اربعمائة امیرالمؤمنین بفرمود تا بر منابر بغداد بنام طغرلبک خطبه کردند و نام او بر سکه نقش کردند و القاب بگفتند: السلطان رکن الدوله ابوطالب طغرلبک محمدبن میکائیل یمین امیرالمؤمنین . مثل : من شرف ذاته کثرحسناته ؛ ذات نیک حسنات افزاید. و بعد از نام او نام و القاب ملک رحیم ابونصربن ابی الهیجاء سلطان الدوله .و هم در این سال ماه رمضان طغرلبک به بغداد رفت و امیرالمؤمنین او را بسیار نثارها و نزلها فرستاد و ملک رحیم به نهروان آمد به استقبال، او را بگرفت و بند کرد و به طبرک ری فرستاد. مثل : من عفا عمن یستوجب العقوبة کان کمن عاقب من یستوجب المثوبة؛ هرکه عفو کند آن را که مستوجب عقوبت باشد همچنان باشد که عقوبت کند آن را که مستوجب مثوبت باشد. بدین حرکت رعیت بیاسودند و در دعا بیفزودند. مثل : من صار لرعیته اباً صار لجنده رباً. و چون به شهر برسید نخست به در حرم و سُدّه ٔ شریفه ٔ نبوی آمد و شرط تعظیم و خدمت بجای آورد و چون بازگشت و به نوبتی فرودآمد امیرالمؤمنین بسیار تکلفها کرد و نثارها و نعمتهای فراوان فرستاد.شعر:<br />خلیفه چون از آن مقدم خبر یافت <br />به خدمت کردن شاهانه بشتافت <br />به استقبال شه فرمود پرواز<br />سپاهی ساخته با برگ و با ساز<br />گرامی نزلهای خسروانه <br />فرستاد از ادب سوی خزانه <br />ز دیبا و غلام و گوهر و گنج <br />دبیران را قلم در خط شد از رنج <br />مر او را در حرم کُرسی نهادند<br />نشست او و دگر قوم ایستادند<br />خلیفه بازپرسیدش که چونی <br />که بادت نوبنو عیشی فزونی <br />به مهمان خواندمت تا نیک دانی <br />مبادت دردسر زین میهمانی <br />هوای گرمسیر است این طرف را<br />فراخیها بود آب و علف را<br />وطن خوش جست رخت آنجا نهادند<br />ملک را تاج و تخت آنجا نهادند<br />خلیفه از برای آن جهانگیر<br />نکرد از هیچ خدمت هیچ تقصیر.<br />و کار ولایت عالم بر او تقریر کرد وسلطنت او بر ممالک عراقین و کهستان مقرر گشت . حکمت :اذا ولیت فَوَل ّ الوفی الملی الذی تحسن کفایته و غناؤه، و تجمل رعایته و وفاؤه، و یعلم بواطن الامور وظواهرها، فاترک الرعایة، و اطلب الکفایة، فالرعایة توجب العنایة، و الکفایة توجب الولایة، فالولاة ارکان الملک و حصون الدولة و عیون الدعوة بهم تستقیم الاعمال و تجتمع الاموال و یقوی السلطان و تعمر البلدان فان استقاموا استقامت الامور و ان اضطربوا اضطربت الجمهور؛ شعر:<br />چون ولایت دهی کسی را ده <br />که وفا و کفایتش باشد<br />و حسن رعایت و غنا دارد و باطن و ظاهر امور بداند و چون کفایت باشد عنایت و رعایت از لوازم آن باشد، کفایت ولایت آورد و ولات حصون دولت باشند، اعمال بدیشان استقامت پذیرد و اموال جمعیت پذیرد. و چون طغرلبک از بغداد بازگشت بساسیری که اسفهسلار لشکر بغداد بود در سنه ٔ تسع و اربعین و اربعمائة (<span class=\"hlight\" dir=\"rtl\">٤٤٩</span> هَ . ق .) بر خلیفه بیرون آمد. امیرالمؤمنین رسول فرستاد به طغرلبک و او را به تعجیل به بغداد خواند. چون طغرلبک روی به بغداد نهاد بساسیری و آن لشکر مخالف سوی شام گریختند، در راه ابراهیم اینال از سلطان بازگشت و به همدان رفت بقصد ملک، سلطان بر اثر او بازگشت تا او را بکشت . مثل : من علامات الدولة قلةالغفلة؛ قلت غفلت نشان دولت است . و چون خبر بازگشتن سلطان به بساسیری رسید به بغداد بازآمد. مثل : من اشد النوازل دولة الاراذل ؛ سخت ترین نوازل و مصائب دولت اراذل پرمعایب باشد. و قرواش بن المقلد پادشاه موصل و پسر مزید جدّ دبیس و قریش بن بدران با او ضم شدند و خلیفه را به حرم در حصار گرفتند و اسیر کردند و رئیس الرؤسارا که پیشکار بود و شخصی بکمال فضل و نبل و کرم و کفایت آراسته بود به زاریی زار بکشتند و خلیفه را به عانه فرستادند و به عربی مهارش نام بسپردند و یک سال در بغداد خطبه ٔ مصریان کردند. مثل : من شرّالاختیار مودةالاشرار و من خیرالاختیار صحبةالاخیار؛ دوستی بدان از اتفاقات بد بود و صحبت نیکان از اختیارات نیک باشد. و چون این واقعه افتاد دشمنی بساسیری در دلها راسخ بود. مثل : من طال تعدّیه کثر اعادیه . مصراع :<br />هرکه را ظلم بیش دشمن بیش .<br />ایتگین سلیمانی که شحنه ٔ بغداد بود بگریخت و به حلوان آمد و از خلیفه ملطفه ای بدورسید فرموده که آن را به سلطان رساند. نبشته بود که : اﷲ اﷲ مسلمانی را دریاب که دشمن لعین مستولی شد و شعار قرمطیان ظاهر گردانید. چون این ملطفه با نوشته ٔایتگین به سلطان رسید برنجید و فرمود که چنین حرکات نشان حرامزادگی باشد. مثل : من رضی من نفسه بالاسائة شهد علی اصله بالدنائة؛ هرکه به بد کردن رضا دهد بر بدگوهری خود گواه بود. سلطان عمیدالملک ابونصر الکندری را فرمود که جوابی مختصر به ایتگین نویس تا راههانگاه دارد و مترصد وصول ما باشد که ما اینک آمدیم بر اثر و فرمود که ایتگین باید که جواب نامه به خلیفه فرستد تا او را سکونی حاصل بود. عمیدالملک صفی ابوالعلاء حسول را که بقیت کُتّاب فاضل بود بخواند و نامه ٔ ایتگین بدو داد و صورت حال بگفت و فرمود که این راجوابی مختصر مفید میباید چنانک اگر بر خلیفه عرض افتد به وصول ما بر اثر با لشکر واثق باشد. مثل : قوةالیقین من صحةالدین و حسن التقی ̍ من فضل النهی ̍. صفی ابوالعلا نامه ٔ ایتگین بستد و این آیت بر پشت نامه نبشت، آیة: ارجع الیهم فلنأتینهم بجنود لا قبل لهم بها ولنخرجنهم منها اذلةً و هم صاغرون . چون عمیدالملک این جواب بر سلطان عرض کرد و معنی بازگفت سلطان را سخت خوش آمد و گفت : فالی خوب است ان شاء اﷲ کار چنین برآید و صفی ابوالعلا را استری از بارگیران خاص بفرمود و دستی جامه . مثل : خیرالاموال ما استرق ّ حراً و خیرالاعمال ما استحق شکراً؛ بهترین مالها آن است که حُرّی را بنده گیرد و نیکوترین کارها آن است که استحقاق شکر پذیرد. شعر:<br />خردمند باید که باشد دبیر<br />چو باشد بر پادشه ناگزیر<br />بلاغت چو با خط گرد آیدش <br />به اندیشه معنی بیفزایدش <br />به پیش مهان ارجمند آن بود<br />که با او لب شاه خندان بود.<br />پس سلطان روی به عراق نهاد با لشکری که از وطأت ایشان زمین میلرزید و کوه میشکوهید. مثل : من نصر الحق قهر الخلق ؛ هرکه نصرت حق کند قهر خلق به دستش آسان بود. چون به بغداد رسید آن حادثه را دریافت و بساسیری را بگرفت و سر او بر جانبی بغداد اشهار کرد. مثل : من عدل زاد قدره و من ظلم نقص عمره ؛ هرکه عدل کند قدرش بیفزاید و هرکه ظلم کند عمرش بکاهد. مثل : من زرع العدوان حصد الخسران ؛ هرکه عدوان کارَد خسران درود، چه از تخم ظلم زیان روید. طغرل بک امیرالمؤمنین را از عانه در ذوالحجة سنه ٔ احدی و خمسین و اربعمائة (<span class=\"hlight\" dir=\"rtl\">٤٥١</span> هَ . ق .) به مقر خلافت و منزل امامت بازآورد و چون به در بغداد رسید پیاده شد و در پیش مهد برفت امیرالمؤمنین فرمود که ارکب یا رکن الدین و بر او ثنای جمیل گفت، لقبش از دولت به دین بدل شد. مثل : من حسنت سیرته وجبت طاعته و من سأت سیرته زالت قدرته ؛ هرکه را سیرت نیک بود طاعت او واجب آید و سیرت بد ازالت قدرت کند. سلطان را نیت نیکو برافراشت و اعدا را فعل بد در کنج ادبار بداشت و فرا هیچ خیر نگذاشت و بعد از چند روز عمیدالملک را بخواند و به خلیفه پیغام میداد که مرا هر وقت از برای مصالح دین و ملک به بغداد حرکت میباید کردن و با من عددی بسیار و لشکری بیشمار است در نواحی بغداد از جهت من نانی تعیین فرمائی که اخراجات ما را از آن مددی باشد. عمیدالملک گفت دور نبود که خلیفه خود این التماس از تو کنداما بحکم فرمان من بروم . حکمت : انصح الوزراء من یحفظک من المآثم و یبعثک علی المکارم و یعد ملکک امواله و یجمل فیک آماله ؛ بهترین وزراء آن است که پادشاه را از وزر و وبال نگاه دارد و بر سر مکارم اخلاق آرد ومال پادشاه جمع آرد و بدو امید نیکو دارد. چون عمیدالملک روی به سرای خلیفه نهاد در راه وزیر خلیفه می آمد و گفت به پیغامی پیش سلطان میروم . عمیدالملک با او بازگشت و ننمود که من به چه می آمدم . مثل : من کتم سرّه احکم امره ؛ هرکه راز نهان دارد کار آن دارد. و پیشتر به حضرت سلطان آمد و گفت وزیر خلیفه به پیغامی آمده است و ظن بنده چنان است که از جهت خلیفه نان پاره میخواهد، اگر از این معنی سخنی گوید جواب ده که منت دارم و من خود در این اندیشه بودم، خواجه را بگویم تا این ترتیب بکند. مثل : من امارة الدول انشاء الحیل ؛ زیرکی و حیلت نشان دولت است . چون وزیر به حضرت سلطان آمد همین پیغام آورد. سلطان چنانکه ملقن بود جواب داد. بعد از آن عمیدالملک کتاب قانون بغداد بخواست و سلطانیات با قلم دیوان گرفت و نان خلیفه معین کردو سلطان بجانب آذربایجان کوچ فرمود و به تبریز آمد و عمیدالملک را به بغداد گذاشت و وکیل کرد تا سیدةالنساء خواهر خلیفه را در حباله ٔ نکاح او آورد، خلیفه در آن مضایقتی میکرد، عمیدالملک دست نواب خلیفه بربست و معایش موقوف کرد تا خلیفه به اجابت کردن مضطر شد. مثل : من علامةالاقبال اصطناع الرجال ؛ از علامت اقبال پادشاه بود کارداران نیکو داشتن . آنگه خلیفه قاضی القضاة بغداد را در خدمت مهد سیده بفرستاد تا به تبریز خطبه خوانند. مثل : من عمل بالرأی غنم و من نظر فی العواقب سلم . شعر:<br />هرکه تدبیر کرد پیش از کار<br />گلش از خار جست و می ز خمار.<br />و مأذون بودند بر مهر چهارصد درم نقره و یک دینار زر مهر سیدةالنساء فاطمه ٔ زهرا علیها السلام و چون مهد سیده به تبریز رسید شهر آذین بستند و نثارهای فراوان کردند و قاضی القضاة بغداد خطبه ٔ نکاح بخواند. آیة: ذلک یوم ٌ مجموع ٌ له الناس و ذلک یوم ٌ مشهودٌ. آنگاه سلطان از تبریز سوی ری رفت تا زفاف به دارالملک باشد، اندک مایه رنج بر وی مستولی شد، به قصران بیرونی به درری به دیه طجرشت از جهت خنکی هوا نزول فرمود، چه حرارت هوا بغایت بود، رعاف بر او مستولی شد و به هیچ دارو امساک نپذیرفت تا قوت ساقط شد و از دنیا برفت دررمضان سنه ٔ خمس و خمسین و اربعمائة (<span class=\"hlight\" dir=\"rtl\">٤٥٥</span> هَ . ق .) وسیده را همچنان با مهر با بغداد بردند. مثل : کل یجری من عمره الی غایة تنتهی الیها مدة اجله و تنطوی علیها صحیفة عمله فزد فی حسناتک و انقص من سیئاتک قبل ان تستوفی مدةالاجل و تقصر عن الزیادة فی السعی و العمل . شعر:<br />همه را قوت هست در عالم <br />قوت مرگ است بچه ٔ آدم .<br />هر بنی آدمی را غایت عمری است که بدان اجل کشد و صحیفه ٔ عملش در آن برسد، باید که در حسنات افزاید، واز سیئات بکاهد پیش از آنکه مدت اجل برسد و از سعی در عمل بازماند. شعر:<br />چنین است رسم سرای فریب <br />فرازش بلند است و پستش نشیب <br />چه بندی دل اندر سرای فسوس <br />که ناگه به گوش آید آوای کوس <br />خروشی برآرد که بربند رخت <br />نبینی جز از تخته ٔ گور تخت <br />به کس بر نماند جهان جاودان <br />نه بر تاجدار ونه بر موبدان <br />روانت گر از آز فرتوت نیست <br />ترا جای جز تنگ تابوت نیست <br />ز هفتاد برنگذرد بس کسی <br />ز دوران چرخ آزمودم بسی <br />وگر بگذرد آنهمه بتریست <br />بر آن زندگانی بباید گریست <br />روان تو دارنده روشن کناد<br />خرد پیش چشم تو جوشن کناد.<br /> <font color=\"Red\">(راحةالصدور چ لیدن صص <span class=\"hlight\" dir=\"rtl\">٩٧</span>-<span class=\"hlight\" dir=\"rtl\">١١٣</span>).</font><br />ابن خلکان در وفیات الاعیان آورده که : طغرلبک بزرگترین پادشاهان سلاجقه و نخستین پادشاه از آن سلسله بود. برادرش داود بلخ را در تصرف و مسعود در غزنه اقامت داشت و در دوره ٔ سلطنت طغرلبک کار سلجوقیان بالا گرفت . خلیفه ٔ عصر القائم باللّه العباسی باب مکاتبه با وی مفتوح داشت و قاضی ابوالحسن علی بن محمدبن حبیب الماوردی را به رسالت نزد طغرلبک فرستاد، سپس در شانزدهم رمضان سال <span class=\"hlight\" dir=\"rtl\">٤٤٧</span> به پادشاهی بغداد و عراق سرافراز گشت و مردم را به تقوی و پرهیزکاری و عدل وداد نسبت به رعیت و مهربانی و نشر احسان بین یکدیگرسفارش کرد. وی مردی بردبار و بزرگوار بود و در محافظت نماز پنجگانه و اوقات آن و بویژه در اقامه ٔ نماز جماعت جد وافی مبذول میداشت . روزهای دوشنبه و پنجشنبه روزه داشتی و صدقات بسیار دادی و در بناء مساجد تاحدی اهتمام کردی که گفتی از حق عز اسمه شرم دارم که برای خود خانه ای بنا کنم و در جوار آن مسجدی نسازم و یکی از کارهای نیکی که از این پادشاه ثبت تواریخ گردید آن بود که ناصرالدین بن اسماعیل را نزد ملکه ٔ روم به رسالت گسیل داشت که از ملکه درخواهد تا اجازت دهد مسلمانان در جامع قسطنطنیه نماز پنجگانه را به نحو جماعت برپای دارند، ملکه نیز مسئول طغرلبک را به اجابت مقرون داشت و مسلمانان نیز از آن پس نماز جماعت در مسجد قسطنطنیه اقامه میداشتند و بنام القادر باللّه بر منبر خطبه میخواندند، در آن حال رسول المستنصر عبیدی صاحب مصر در مسجد حاضر بود و از اینکه خطبه بنام خلیفه ٔ عباسی خوانده شد حالش دگرگون گردید و همین امر سبب شد که روابط بین مصریان و رومیان تیره گردید. چون طغرل بر پادشاهی مستقر شد و بر عراقین استیلا یافت رسولی نزد خلیفه فرستاد و دختر خلیفه را خواستار شد. این تقاضا خلیفه را گران آمد و به رسول طغرل عدم قبول خویش اعلام داشت . رسول بازگشت و طغرل را ازپاسخ خلیفه آگاه ساخت . طغرل از پای ننشست و بگفته ٔ صاحب تاریخ شذورالذهب چندان به بارگاه خلافت نماینده و ایلچی فرستاد که خلیفه بسال <span class=\"hlight\" dir=\"rtl\">٤٥٣</span> خویشتن را به پذیرفتن خواهش طغرل ناگزیر دید و دختر خویش جهت طغرل تزویج کرد. عقد ازدواج در خارج شهر تبریز صورت گرفت و پس از اتمام عقد طغرل در سال <span class=\"hlight\" dir=\"rtl\">٤٥٥</span> عازم بغداد شد و چون به بغداد رسید و جشن عروسی را آماده شد گروهی را باصد هزار دینار برسم حمل و نقل جامه نزد دختر فرستادشب دوشنبه <span class=\"hlight\" dir=\"rtl\">١٥</span> صفر دختر در دارالخلافه با جامه ٔ زربفت بر تختی بنشست و سلطان طغرل نزد وی شد زمین خدمت دربرابر دختر بوسه داد و دختر همچنان روی بزیر برقع پوشیده داشت . طغرل تحف و هدایای بیرون از حد وصف تقدیم کرد و سپس شرط زمین بوس بجای آورد و با شادی و نشاطفراوان بازگشت ... طغرل روز جمعه هشتم رمضان بسال <span class=\"hlight\" dir=\"rtl\">٤٥٥</span> در ری به سن هفتادسالگی دنیا را بدرود گفت و جسد وی را از ری به مرو بردند و پهلوی برادرش داود به خاک سپردند. ابن الهمذانی در تاریخ خویش و سمعانی در ذیل کتاب انساب در ترجمه ٔ سنجر گفته اند که طغرلبک را درخاک ری دفن کردند. محمدبن منصور الکندری وزیر طغرل از گفتار طغرل نقل میکند که طغرل میگفت هنگامی که به خراسان بودم خواب دیدم که به آسمان بر شدم و گویا هوا را غباری بود که هیچ چیز نمیدیدم اما بوی خوشی به مشامم میرسید، در این اثنا آوازی شنیدم که به من میگفت وقت غنیمت شمار که بحق جلت قدرته نزدیک شده ای، نیاز خویش از آفریدگار طلب کن که برآورد. در دل این اندیشه گذشت که طول عمر خواهم، ندائی به گوشم رسید که عمر ترا به هفتاد رساندیم . گفتم پروردگارا مرا بسنده نیست . همان ندا نوبت دیگر به گوشم رسید. باز همان گفتار مکرر کردم و همان ندا شنیدم . و ابن الاثیر این حکایت در تاریخ ذکر کرده است . گویند چون مرگ طغرل دررسید گفت : من گوسپندی را مانم که چار دست و پای او رابرای پیرایش پشم بسته باشند و او گمان برد که او راخواهند کشتن از این رو مضطرب شود، چون پس از اتمام پیرایش رهایش کنند شادمان گردد، نوبت دیگر که برای ذبح دست و پای او بندند گمان برد که خواهند پشم او رابپیرایند از این رو جزع نکند و آرام گیرد اما نوبت آرامش او با قطع رشته ٔ زندگانی توأم باشد و این مرض که مراست در حکم آخرین نوبت بستن دست و پای گوسفند است برای قطع حیات او. طغرل از خود فرزند ذکور باقی نگذاشت . دختر القائم بامراﷲ جز ششماه در خانه ٔ طغرل نزیست و وی نیز بسال <span class=\"hlight\" dir=\"rtl\">٤٩٦</span> در ششم محرم دار دنیا را وداع گفت . (ابن خلکان چ تهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٣</span>).<br />طغرل بیک بگفته ٔ مافروخی علاوه بر آنکه نسبت به عموم مردم رؤوف و مهربان بود از آنجا که به شهر اصفهان علاقه ٔ مفرطی داشت با آنکه رعایا و اهالی اصفهان با او جنگیدند و سرپیچی و نافرمانی نسبت به او از حد وصف گذراندند معهذا همیشه اهالی اصفهان را تفقد و با آنان به حسن سلوک رفتار میکرد و دوازده سال در آنجا بالاستقلال سلطنت کرد و اگر بر حسب اتفاق چند سالی هم در سایر شهرستانهای تحت اختیار سلطنت خویش اقامت داشت حتماً همه ساله چند ماهی هم به اصفهان می آمد و از زندگانی درآن شهر بهشت مثال برخورداری می یافت و بر اثر همان محبت و عشق خاصی که به اصفهان داشت در حدود پانصدهزار دینار در آن شهر به مصرف بنای قصور و مساجد و غیره رساند. (محاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">١٠١</span>). طغرل بک ممدوح ناظم ویس ورامین و معاصر شه ملک پادشاه خوارزم بود که طغرل بیک او را بکشت و نیز معاصر ارسلان خان بود و در اصفهان خلعت خلیفه پوشید. و رجوع به تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>، <span class=\"hlight\" dir=\"rtl\">٣٦٦</span>، <span class=\"hlight\" dir=\"rtl\">٣٧٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٧٥</span>، <span class=\"hlight\" dir=\"rtl\">٣٧٨</span>، <span class=\"hlight\" dir=\"rtl\">٣٨٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٨٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٩٠</span> و تتمه ٔ صوان الحکمة ص <span class=\"hlight\" dir=\"rtl\">١٨٧</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٢</span> و لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨</span>، <span class=\"hlight\" dir=\"rtl\">٦٩</span> و اخبار الدولة السلجوقیة تألیف علی بن ناصربن علی الحسینی چ محمد اقبال ص <span class=\"hlight\" dir=\"rtl\">٤</span>، <span class=\"hlight\" dir=\"rtl\">٥</span>، <span class=\"hlight\" dir=\"rtl\">٨</span>، <span class=\"hlight\" dir=\"rtl\">٩</span>، <span class=\"hlight\" dir=\"rtl\">١٠</span>، <span class=\"hlight\" dir=\"rtl\">١٢</span>، <span class=\"hlight\" dir=\"rtl\">١٧</span>، <span class=\"hlight\" dir=\"rtl\">١٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٣</span>، <span class=\"hlight\" dir=\"rtl\">١٩٣</span>، <span class=\"hlight\" dir=\"rtl\">١٩٤</span>، <span class=\"hlight\" dir=\"rtl\">١٩٥</span> و حبیب السیر چ خیام فهرست ج <span class=\"hlight\" dir=\"rtl\">٢</span> و تاریخ مغول اقبال ص <span class=\"hlight\" dir=\"rtl\">٤٠١</span> شود.<br /></font></div>'),
(177145, 'طغرل خان', '<span class=\"hlight\">طغرل خان .</span><font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ]</font></b> (اِخ ) ابن یوسف خضرخان . اولین از امرای ایلک خانیه ٔ ترکستان شرقی که از <span class=\"hlight\" dir=\"rtl\">٤٣٩</span> تا <span class=\"hlight\" dir=\"rtl\">٤٥٥</span> هَ . ق . سلطنت کرده است . رجوع به طبقات سلاطین اسلام شود.<br /></font></div>'),
(177146, 'طغرل شدن', '<span class=\"hlight\">طغرل شدن .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ش ُ دَ ]</font></b> (مص مرکب ) مردن سلاطین جغتائی . (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(177147, 'طغرل غاصب', '<span class=\"hlight\">طغرل غاصب .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ل ِ ص ِ ]</font></b> (اِخ ) طغرل برار. غلامی از غلامان سلطان محمود غزنوی بود که در فاصله ٔ بین سلطنت مجدالدوله عبدالرشید و جمال الدوله فرخ زاد عَلَم طغیان برافراشت و بر غزنین استیلایافت و پس از اندک زمانی به دست نوشتکین شرابی کشته شد. در تاریخ گزیده آورد که : دختر جغری بیک به کین شوهر بقصد او <font color=\"DarkGreen\"><b>[ مجدالدوله عبدالرشید ]</font></b> لشکر آورد، از غلام محمودی شخصی طغرل نام که امیرالامراء بود با آن لشکر متفق شد، با عبدالرشید جنگ کردند و او را اسیر کردند و دختر جغری بیک او را به طغرل فرستاد و محبوس کرد، با خراسان مراجعت نمود. طغرل بر آن ملک مستولی شد. غزنویان او را طغرل کافرنعمت خوانند. ... بعد از مدتی طغرل کافرنعمت او را بکشت . چون بر تخت محمودی بنشست خواست دامن گرد کند نوشتگین شرابی با دو غلام تیغکشیدند و او را پاره پاره کردند. اهل غزنین به قتل او خرمیها نمودند. (تاریخ گزیده چ عکسی برون ص <span class=\"hlight\" dir=\"rtl\">٤٠٣</span>).<br />مؤلف تاریخ بیهق در ضمن ترجمه ٔ احوال بیهقی (ابوالفضل محمدبن الحسین الکاتب ) گوید: و او را از جهت مهر زنی قاضی در غزنی حبس فرمود، بعد از آن طغرل برار که غلام گریخته ٔ محمودیان بود ملک غزنی به دست گرفت و سلطان عبدالرشید را بکشت و خدم ملوک را به قلعه فرستاد و از آن جمله یکی ابوالفضل بیهقی بود که از زندان قاضی با حبس قلعه فرستاد. ابوالفضل در آن قلعه گوید:<br />کلما مر من سرورک یوم <br />مر فی الحبس من بلائی یوم <br />ما لبؤسی و ما لنَعمی دوام <br />لم یدم فی النعیم و البؤس قوم .<br />پس اندک مایه روزگار برآمد که طغرل برار بر دست نوشتکین زوبین دار کشته آمد و مدت استیلاء وی پنجاه وهفت روز بیش نبود و ملک با محمودیان افتاد و بر ولی نعمت بیرون آمدن مبارک نیاید و مدت دراز مهلت ندهد. (تاریخ بیهق چ تهران صص <span class=\"hlight\" dir=\"rtl\">١٧٧</span> - <span class=\"hlight\" dir=\"rtl\">١٧٨</span>).<br />در حبیب السیر ذیل «ذکر سلطنت ... عبدالرشید و بیان آنچه از طغرل نویان کافرنعمت به وقوع انجامید» آورده است : عبداﷲ به روایت روضةالصفا پسر مسعودبن سلطان محمود بوده و بقول صاحب گزیده ولد سلطان محمودبن سبکتکین بود و ابومنصور کنیت داشت، او را به حسب لقب مجدالدوله میگفتند و عبدالرشید بفرمان مودود در قلعه ای که میان بُست و غزنین است محبوس بود و عبدالرزاق وزیر بعد از استماع خبر فوت مودود عزیمت سیستان را فسخ نموده به نواحی آن قلعه شتافت و عبدالرشید را به سلطنت برداشته امرا و سران سپاه را فرمان بردار او گردانید، آنگاه عبدالرشید متوجه غزنین گشته علی بن مسعود بی دردسر نیزه و آمد و شد شمشیر تیز روی به گریز آورد و چون عبدالرشید در دارالملک غزنین فی الجمله مکنتی پیدا کرد و طغرل حاجب را که برادرزن مودود بود و اعتباری تمام داشت با هزار سوار جرار بصوب سیستان ارسال نموده طغرل در آن ولایت بر ابوالفضل و بیغو سلجوقی غلبه کرده به اندک زمانی در حکومت آن مملکت مستقل گشت و به خیال خلع نهال اقبال عبدالرشید متوجه غزنین شد و چون به پنج فرسخی شهر رسید نزد عبدالرشید غایت مکر و خدیعت او به وضوح پیوسته به قلعه گریخت و طغرل به غزنین درآمده رسل و رسایل نزد کوتوالان حصار فرستادو در باب وعد و وعید و تهدید آن مقدار مبالغه نمود که آن جماعت متوهم گشته عبدالرشید را با سایر اولاد محمود به وی سپردند و طغرل تمام شاهزادگان را به قتل آورد. دختر سلطان مسعودبن محمود را به اکراه تمام درحباله ٔ نکاح کشید لاجرم به طغرل کافرنعمت ملقب شد. وچون حرخیر که از اکابر امراء غزنین بود و در حدود هندوستان اقامت مینمود از این وقایع شنیعه آگاه گشته همت بر دفع آن غدار کافرنعمت مقصور داشته به دختر سلطان مسعود و اعیان غزنین مکتوبات نوشته ایشان را بر اغماض از اعمال قبیحه ٔ طغرل ملامت و سرزنش کرد و جمعی که کینه ٔ طغرل در دل داشتند از مطالعه ٔ آن مکاتیب دلیر شده چند پهلوان خنجرگذار در روزی که آن بوالفضول غدار بر تخت نشسته بود به پای جلادت پیش رفته به زخم تیغ تیز پیکر او را ریزریز کردند. (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩٥</span> و <span class=\"hlight\" dir=\"rtl\">٣٩٦</span>).<br /></font></div>'),
(177148, 'طغرل غلام', '<span class=\"hlight\">طغرل غلام .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ل ِ غ ُ ]</font></b> (اِخ ) وی غلام محمود و یوسف پسران ناصرالدین بود. بیهقی گوید: وی را عزیزتر از فرزندان داشتی . وی را بفریفتند بفرمان سلطان و تعبیه ها کردند تا بر وی مشرف باشد و هرچه رود می بازنماید تا ثمرات این خدمت بیابد به پایگاهی بزرگ که یابد و این ترک ابله این چربک بخورد و ندانست که کفران نعمت شوم باشد و قاصدان از قُصدار برکار کرد و میفرستاد سوی بلخ و غث و سمین می بازنمود عبدوس را پنهان و آن را به سلطان میرسانیدند و یوسف چه دانست که دل و جگر معشوقش بر وی مشرفند به هر وقتی و بیشتر در شراب میژکید. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٥٠</span>). و این طغرل غلامی بود که از میان دو هزار غلام چنو بیرون نیاید به دیدار و قد و رنگ و ظرافت و لیاقت و وی را از ترکستان ارسلان خاتون فرستاده بود بنام امیر محمود و این خاتون را عادت بود که سلطان محمود را غلامی نادر و کنیزکی دوشیزه ٔ نادره هر سالی فرستادی بر سبیل هدیه و امیر وی را دستارهای قصب و شار باریک و مروارید و دیبای رومی فرستادی . سلطان این طغرل را بپسندید و در جمله هفت و هشت غلام که ساقیان وی بودند پس از ایاز بداشت و سالی دو برآمد. یک روز چنان افتاد که امیر به باغ فیروزی شراب میخورد بر گل و چندان گل صدبرگ ریخته بودند که حد و اندازه نبود و این ساقیان ماهرویان عالم به نوبت دوگان دوگان می آمدند، این طغرل درآمد قبای لعل پوشیده و یار وی قبای فیروزه داشت و به ساقی گری مشغول شدند هر دو ماهروی و طغرل شرابی رنگین به دست بایستاد و امیر یوسف را شراب دریافته بود چشمش بر وی بماند و عاشق شد و هرچند کوشید و خویشتن را فراهم گرفت چشم از وی نتوانست بازداشت و امیر محمود دزدیده مینگریست و شیفتگی و بیهوشی برادرش میدید و به تغافل میزد تا آنکه ساعتی بگذشت پس گفت ای برادر تو از پدر کودک مانده بودی و گفته بود پدر ما بوقت مرگ عبداﷲ دبیر را که مقرر است که محمود ملک غزنین نگه دارد که اسماعیل مرد آن نیست محمود را از پیغام من بگوی که مرا دل به یوسف مشغول است، وی را به تو سپردم باید که وی را به خوی خویش برآری و چون فرزندان خویش عزیز داری و ما تا این غایت دانی که به راستای تو چند نیکوئی فرموده ایم و پنداشتیم که باادب برآمده ای و نیستی چنانکه ما پنداشته ایم در مجلس شراب در غلامان چرا نگاه میکنی تو را خوش آید که هیچکس در مجلس شراب در غلامان تو نگرد؟ چشمت ازدیرباز بر این طغرل بمانده است و اگر حرمت روان پدرم نبودی ترا مالشی سخت تمام رسیدی، این یک بار عفو کردم و این غلام را به تو بخشیدم که ما را چنو بسیار است، هوشیار باش تا بار دیگر سهوی چنین نیفتد که با محمود چنین بازیها نرود. یوسف متحیر گشت و برپای خاست و زمین بوسه داد و گفت : توبه کردم و نیز چنین خطا نرود. سلطان گفت بنشین . بنشست و آن حدیث فرابُرید و نشاط شراب بالا گرفت و یوسف را شراب دریافت و بازگشت . امیر محمود خادمی خاص که وی را صافی میگفتند و چنین غلامها به دست او بودند آواز داد و گفت : طغرل را به نزدیک برادرم فرست . بفرستاد و یوسف بسیار شادی کرد و بسیار چیز بخشید خادمان را و بسیار صدقه داد و این غلام را برکشید و حاجب او شد و عزیزتر از فرزندان داشت و چون شب سیاه به روز سپیدش تاختن آورد و آفتاب را کسوفی افتاد از خاندانی بانام زن خواست و در عقد نکاح و عروسی وی تکلفهای بی محل نمود چنانکه گروهی از خردمندان پسند نداشتند و جزا و مکافات آن مهتر آن آمد که بازنمودم . پس از گذشتن خداوندش چون درجه گونه ای یافت و نواختی از سلطان مسعود اما ممقوت شد هم نزدیک وی و هم نزدیک بیشتر از مردمان و ادبار در وی پیچید وگذشته شد به جوانی روزگارش در ناکامی و عاقبت کفران نعمت همین است . (تاریخ بیهقی چ ادیب صص <span class=\"hlight\" dir=\"rtl\">٢٥٠</span>-<span class=\"hlight\" dir=\"rtl\">٢٥٤</span>).<br /></font></div>'),
(177149, 'طغرل نزان', '<span class=\"hlight\">طغرل نزان .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span>رُ ن َ ]</font></b> (اِخ ) در کتاب اخبار الدولة السلجوقیة تألیف علی بن ناصربن علی الحسینی در ضمن خبر طغرل غاصب آورده که : و کان لسلاطین غزنة غلام ترکی یقال له طغرل نزان ففر منهم و التجاء الی الملوک السلجوقیة... <font color=\"DarkGreen\"><b>[ ظاهراً کلمه ٔ نزان تصحیفی از برار باشد؟ ]</font></b>. (تاریخ الدولة السلجوقیة صص <span class=\"hlight\" dir=\"rtl\">١٤</span> - <span class=\"hlight\" dir=\"rtl\">١٥</span>). رجوع به طغرل برار شود.<br /></font></div>'),
(177150, 'طغرل کافرنعمت', '<span class=\"hlight\">طغرل کافرنعمت .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ل ِ ف ِ ن ِ م َ ]</font></b> (اِخ ) رجوع به طغرل برار و طغرل غاصب و طغرل غلام و تاریخ بیهقی چ فیاض و تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٢٤٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٦٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٧١</span>، <span class=\"hlight\" dir=\"rtl\">٢٧٢</span> شود.<br /></font></div>'),
(177151, 'طغرلبک', '<span class=\"hlight\">طغرلبک .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ب َ ]</font></b> (اِخ ) (عزالدین ...) امیر اسفهسالار عزالدین طغرلبک . مولوی محمد شفیع ناشر تتمه ٔصوان الحکمة در ص <span class=\"hlight\" dir=\"rtl\">١٩٦</span> از جمله ٔ حواشی و زیاداتی که برکتاب مزبور نوشته ترجمه ٔ احوال شرف الدین ظهیرالملک علی بن الحسن البیهقی است که از کتاب تاریخ بیهق تألیف ابن فندق نقل کرده است و در اثناء ترجمه ٔ احوال مذکور آمده که اول عمل او که خطیر بود در عهد سلطان سنجر رحمةاﷲ علیه عمل هراة بود و از آنجا به وزارت امیر اسفهسالار عزالدین طغرلبک اثر ترقی یافت . با مراجعه به تواریخ موجود و کتبی که محتمل بود احوال این امیر اسفهسالار را روشن کند هویت و شخصیت وی نامعلوم ماند، ولی در تاریخ بیهق چ تهران ص <span class=\"hlight\" dir=\"rtl\">٢٢٦</span> بجای طغرلبک طغرلتکین است و شرح حال این طغرلتکین نیز معلوم نشد.<br /></font></div>'),
(177152, 'طغرلتگین', '<span class=\"hlight\">طغرلتگین .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ت َ ]</font></b> (اِخ ) ابن طغرل . دومین از امرای ایلک خانیه ٔ شرقی است در <span class=\"hlight\" dir=\"rtl\">٤٥٥</span> هَ . ق . <span class=\"hlight\">:</span> <br />آنکس که برخلاف تو آرد به رزم روی <br />او را بود نحوست و ادبار در قفا<br />ور بایدت گواهی از پار تا کنون <br />طغرلتگین بس است و قدرخان بر این گوا.<br /> <font color=\"Red\">امیر معزی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).</font><br />و رجوع به المعجم چ تهران ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span> شود.<br /></font></div>'),
(177153, 'طغرلتگین', '<span class=\"hlight\">طغرلتگین .</span><font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ت َ ]</font></b> (اِخ ) (عزالدین ...) رجوع به تاریخ بیهق چ تهران ص <span class=\"hlight\" dir=\"rtl\">٢٢٦</span>، و طغرلبک (عزالدین ...) شود.<br /></font></div>'),
(177154, 'طغرلشاه', '<span class=\"hlight\">طغرلشاه .</span> <font color=\"DarkGreen\"><b>[ طُ رِ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ]</font></b> (اِخ ) ابن محمد. از طبقه ٔ دوم سلاجقه، لقبش ملک مغیث الدین . بحکم وصیت پدر مالک تخت و افسر شد ودوازده سال حکومت کرد (در کرمان ) و در سنه ٔ اثنی و ستین و خمسمائة (<span class=\"hlight\" dir=\"rtl\">٥٦٢</span> هَ . ق .) وفات یافت . (حبیب السیرچ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٣٧</span>). لین پول در تاریخ طبقات سلاطین اسلام لقب محمد پدر طغرلشاه را مغیث الدین و لقب خود او را محیی الدین آورده است . (طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">١٣٦</span>).<br /></font></div>'),
(177155, 'طغرود', '<span class=\"hlight\">طغرود.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) قصبه ٔ مرکز دهستان طغرود بخش دستجرد خلجستان شهرستان قم در <span class=\"hlight\" dir=\"rtl\">٣٣٠٠٠</span>گزی شمال خاور دستجرد. کوهستان و سردسیر با <span class=\"hlight\" dir=\"rtl\">١٦٦٠</span> تن سکنه . آب آن از قنات و رودخانه و محصول آنجا غلات و انار و انجیر و میوه جات . شغل اهالی زراعت است و عده ٔ کمی پیله ور هستند و کرباس باف . چهار مزرعه جزء این ده بوده، پاسگاه ژاندارمری و دبستان دارد و ایل شاهسون در زمستان به اطراف این ده می آیند. راه فرعی دارد و همه روزه ماشین به قم رفت و آمد مینماید. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(177156, 'طغرکان', '<span class=\"hlight\">طغرکان .</span> <font color=\"DarkGreen\"><b>[ طَ غ َ ]</font></b> (اِخ ) ده کوچکی است از دهستان مسکون بخش جبال بارز شهرستان جیرفت در <span class=\"hlight\" dir=\"rtl\">٦٠</span>هزارگزی خاور مسکون و<span class=\"hlight\" dir=\"rtl\">٢٦</span>هزارگزی خاور شوسه ٔ سبزواران - بم، با <span class=\"hlight\" dir=\"rtl\">٤٠</span> تن سکنه . مزارع قلیجانی، گردو اسفید، محمد قنبری و جو سفیدی جزء این ده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(177157, 'طغری', '<span class=\"hlight\">طغری .</span> <font color=\"DarkGreen\"><b>[ طُ را ]</font></b> (ع اِ) طغرا. علامتی که با خط درشت بر طره ٔ احکام سلطانی کشند. صاحب تاج العروس گوید: این کلمه تتری است و اصل آن طورغای باشد و فارس و روم (مقصود ترک عثمانی است ) آن را استعمال کنند. ج، طغراوات . و آن را پس از طره و پیش از بسمله به منشور ملصق میکرده اند. <BR><font color=\"Blue\">◄</font> وُلف در لغات شاهنامه طغری را بمعنی شاهین یا مرغ شکاری دیگر دانسته و این بیت شاهنامه را نیز شاهد آورده است <span class=\"hlight\">:</span> <br />بزد طبل و طغری شد اندر هوا<br />شکیبانبد مرغ فرمانروا.<br /> <font color=\"Red\">(<span class=\"hlight\" dir=\"rtl\">٧٩٥</span> <span class=\"hlight\" dir=\"rtl\">٣٥</span>.<span class=\"hlight\" dir=\"rtl\">M</span>).</font><br /> <br />و رجوع به فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٩</span> و طغرا شود.<br /></font></div>'),
(177158, 'طغشیقون', '<span class=\"hlight\">طغشیقون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) رجوع به طخشیقون شود.<br /></font></div>'),
(177159, 'طغم', '<span class=\"hlight\">طغم .</span> <font color=\"DarkGreen\"><b>[ طَ غ َ ]</font></b> (ع اِ) دریا. <BR><font color=\"Blue\">◄</font> آب بسیار. (منتهی الارب ).<br /></font></div>'),
(177160, 'طغماچ', '<span class=\"hlight\">طغماچ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام ولایتی از ترکستان و این لفظ صحیح طمغاج است به تقدیم میم بر غین معجمه چنانچه در برهان و سراج است . (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> رباط طغماج یکی از منازل بین راه از بسطام تا خوارزم است ازطریق جرجان و دهستان . (نزهةالقلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span>).<br /></font></div>'),
(177161, 'طغماچ خان', '<span class=\"hlight\">طغماچ خان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) لقب پادشاه طغماج که ولایتی است از ترکستان . (تاریخ رشیدی ).<br /></font></div>'),
(177162, 'طغموس', '<span class=\"hlight\">طغموس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) دیو سرکش و خبیث از غول و جز آن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177163, 'طغو', '<span class=\"hlight\">طغو.</span> <font color=\"DarkGreen\"><b>[ طَغ ْوْ ]</font></b> (ع مص ) درگذشتن از حد. <BR><font color=\"Blue\">◄</font> نافرمانی کردن . (منتهی الارب ) (آنندراج ). طُغوان .<br /></font></div>'),
(177164, 'طغوی', '<span class=\"hlight\">طغوی .</span> <font color=\"DarkGreen\"><b>[ طَغ ْ وا ]</font></b> (ع اِمص ) اسم است مر طغیان را و منه <span class=\"hlight\">:</span> کذبت ثمود بطغویها. (قرآن <span class=\"hlight\" dir=\"rtl\">١١/٩١</span>). (منتهی الارب ) (آنندراج ). کذبت ثمود بطغویها؛ دروغ داشت ثمود و قبیله ٔ آن پیغمبر خود را که صالح بود به طغیان و عصیان خود. (تفسیر ابوالفتوح سوره ٔ الشمس آیه ٔ <span class=\"hlight\" dir=\"rtl\">١١</span>). بی فرمانی . (مهذب الاسماء). از حدّ درگذشتن . <BR><font color=\"Blue\">◄</font> گمراهی . (دهار). <BR><font color=\"Blue\">◄</font> (اِ) گاو وحشی کوچک را نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(177165, 'طغک', '<span class=\"hlight\">طغک .</span> <font color=\"DarkGreen\"><b>[ طَ غ َ ]</font></b> (اِ) نام درختی است مانند سرو و صنوبر. رجوع به زنزلخت و فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٥</span> شود.<br /></font></div>'),
(177166, 'طغی', '<span class=\"hlight\">طغی .</span> <font color=\"DarkGreen\"><b>[ طَ غا ]</font></b> (ع اِ) آواز. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177167, 'طغی', '<span class=\"hlight\">طغی .</span><font color=\"DarkGreen\"><b>[ طَ غا ]</font></b> (اِخ ) توقای برلاس . از امرای عصر تیموری . (حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤١</span>). و رجوع به طغا شود.<br /></font></div>'),
(177168, 'طغی', '<span class=\"hlight\">طغی .</span> <font color=\"DarkGreen\"><b>[ طَغ ْی ْ ]</font></b> (ع مص ) درگذشتن از اندازه . (منتهی الارب ) (آنندراج ). از حد درگذشتن . (تاج المصادر بیهقی ). زیاده روی . تجاوز از حد. تجاوز از قدر. اعتداء از حدود و مقادیر. <BR><font color=\"Blue\">◄</font> نافرمانی . <BR><font color=\"Blue\">◄</font> گمراهی . <BR><font color=\"Blue\">◄</font> بلند شدن و درگذشتن از حد کفر. زیادتی کردن در معاصی و ظلم . اسراف در ظلم و گناه . غلو در کفر. <BR><font color=\"Blue\">◄</font> موج زدن آب . برآمدن . بالا زدن آب رود و جز آن بیش از حد. به جوش آمدن . جوشیدن . به آشوب شدن دریا و رود و مانند آن . <BR><font color=\"Blue\">◄</font> جوشیدن خون . <BR><font color=\"Blue\">◄</font> بانگ کردن گاو. <BR><font color=\"Blue\">◄</font> بسیار آب آوردن سیل . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177169, 'طغیا', '<span class=\"hlight\">طغیا.</span> <font color=\"DarkGreen\"><b>[ طَغ ْ <span class=\"hlight\" dir=\"rtl\">/</span> طُغ ْ ]</font></b> (ع اِ) گاو ریزه . <BR><font color=\"Blue\">◄</font> عَلَم است مر گاو دشتی را. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177170, 'طغیان', '<span class=\"hlight\">طغیان .</span> <font color=\"DarkGreen\"><b>[ طُغ ْ ]</font></b> (ع مص ) درگذشتن از اندازه . (منتهی الارب ) (آنندراج ). از حد درگذشتن . (تاج المصادر بیهقی ) (مجمل اللغه ) <span class=\"hlight\">:</span> فمایزیدهم الا طغیاناً کبیراً. (قرآن <span class=\"hlight\" dir=\"rtl\">٦٠/١٧</span>)؛ <font color=\"DarkGreen\"><b>[ ترسانیدن ما ]</font></b> ایشان را نمیفزاید مگر طغیانی و عصیانی بزرگ و طغیان مجاوزةالحد باشد. (تفسیر ابوالفتوح سوره ٔ بنی اسرائیل آیه ٔ <span class=\"hlight\" dir=\"rtl\">٦٠</span>). زیاده روی . تجاوز از حد. تجاوز از قدر. اعتداء از حدود و مقادیر. <BR><font color=\"Blue\">◄</font> گمراهی . <BR><font color=\"Blue\">◄</font> بلند شدن و درگذشتن از حد کفر. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بطر. سرکشی کردن از حق . (منتهی الارب ). زیادتی کردن در معاصی و ظلم . (منتهی الارب ) (آنندراج ). اسراف در ظلم و گناه . غلو درکفر. و بعید نیست که اصل آن تورانز یونانی باشد و تیران فرانسه هم از آن است . و عرب هم که «ملک الروم »را در کتب تواریخ به لفظ طاغیه تعبیر میکنند در وجه تسمیه ٔ آن گویند: لکثرة طغیانه و فساده . رجوع به توران شود. <BR><font color=\"Blue\">◄</font> نافرمانی . سرکشی <span class=\"hlight\">:</span> <br />تجربت کوفته دلی است مرا<br />نه خطائی در او نه طغیانی .<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> موج زدن آب . (منتهی الارب ) (آنندراج ). برآمدن و بالا زدن آب رود و جز آن بیش از حد. به جوش آمدن . جوشیدن . آشوب شدن دریا و رود و مانند آن . <BR><font color=\"Blue\">◄</font> جوشیدن خون . <BR><font color=\"Blue\">◄</font> بانگ کردن گاو. <BR><font color=\"Blue\">◄</font> بسیار آب آوردن سیل . (منتهی الارب ) (آنندراج ). آب خیز. <BR><font color=\"Blue\">◄</font> (اِ) به عربی گاو وحشی کوچک را نامند. (فهرست مخزن الادویه ). (این معنی در عرب به لفظ طغیا آمده و افزودن نون ناشی از تحریف نساخ است ). <BR><font color=\"Blue\">◄</font> (اِمص ) مجازاً، بمعنی افزونی و کثرت استعمال این درافزونی چیزهای نامرغوب و از این باعث گاهی بمعنی ظلم و بی فرمانی آمده . (غیاث اللغات ) (آنندراج ). <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طغیان آبها</span> ؛ مقابل نقصان . افزون شدن آب . کثرت آب . غلبه ٔ آب .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">اشک کباب مایه ٔ طغیان آتش است </span> .<br />طغیان رونده بر قلم است <span class=\"hlight\">:</span> <br />مثل زنند که طغیان رونده بر قلم است <br />چرا برون نرود چون برون رود طغیان .<br /> <font color=\"Red\">ادیب صابر.</font><br />صاحب تیغ و قلم عالی علاءالملک آن که او<br />از قلم جز تیغ تیزش حرف طغیان برندارد.<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />با سر تیغ زبان تو خیال طغیان <br />از قلم دور نباشد که مر او را دو سر است .<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />تهمت طغیان نبندد هیچ عاقل بر قلم <br />گر به تلقین ضمیرت کار فرماید دبیر.<br /><font color=\"Red\">سیف اسفرنگ .</font><br /></font></div>'),
(177171, 'طغیان کردن', '<span class=\"hlight\">طغیان کردن .</span> <font color=\"DarkGreen\"><b>[طُغ ْ ک َ دَ ]</font></b> (مص مرکب ) موج زدن آب . جوشش سیل و دریا و جز آن . <BR><font color=\"Blue\">◄</font> نافرمانی کردن <span class=\"hlight\">:</span> <br />حرف زهرش گفته ام شکّر لبم را میگزد<br />درد طغیان میکند گر نام افیون میبرم .<br /><font color=\"Red\">ظهوری (از آنندراج ).</font><br /></font></div>'),
(177172, 'طغیانی', '<span class=\"hlight\">طغیانی .</span> <font color=\"DarkGreen\"><b>[ طُغ ْ ]</font></b> (حامص ) به زیادت یا در آخر لفظ طغیان ظاهراً درست نباشد چرا که طغیان خود مصدر است حاجت به یاء مصدری ندارد مگر آنکه گوئیم معمول فارسیان است که در آخر بعض مصادر یاء مصدری زاید کنند چنانچه فضول و فضولی و خلاص و خلاصی و سلامت و سلامتی . (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(177173, 'طف', '<span class=\"hlight\">طف .</span> <font color=\"DarkGreen\"><b>[ طَف ف ]</font></b> (ع مص ) برداشتن چیزی را به پای یابه دست . <BR><font color=\"Blue\">◄</font> نزدیک شدن چیزی به کسی . <BR><font color=\"Blue\">◄</font> بستن پای ناقه . (منتهی الارب ). ببستن دست و پای ناقه . (زوزنی ). <BR><font color=\"Blue\">◄</font> خذ ما طف ّ لک ؛ یعنی بگیر آنچه نزدیک تو رسید و آسان شد. (منتهی الارب ).<br /></font></div>'),
(177174, 'طف', '<span class=\"hlight\">طف .</span> <font color=\"DarkGreen\"><b>[ طَف ف ]</font></b>(اِخ ) موضعی است نزدیک کوفه و هر زمین عرب که مشرف بر زمین آبادان عراق است و منه حدیث مقتل الحسین رضی اﷲ عنه انه یُقتل بالطف و هو موضع بکربلاء سمی به لأنّه طرف البری یلی الفرات و کانت تجری یومئذ قریباً منه . (منتهی الارب ) (منتخب اللغات ). و یاقوت آرد: طف سرزمینی است از نواحی کوفه در طریق دشت که قتلگاه حسین بن علی رضی اﷲ عنه در آن بوده است . سرزمین مزبور دشتی است نزدیک آبادانی و در آن چندین چشمه جاری است از قبیل : صید و قطقطانه و رهیمة و عین جمل و غیره . (از معجم البلدان ). و صاحب عقدالفرید گوید: حسین رضی اﷲ عنه در روز جمعه یوم عاشورا بسال <span class=\"hlight\" dir=\"rtl\">٦١</span> هَ . ق . در طف از سواحل فرات در موضعی موسوم به کربلا کشته شد. (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٣</span>). یکی از شاعران گوید <span class=\"hlight\">:</span> <br />اَبک حسیناً لیوم مصرعه <br />بالطف بین الکتائب الخرس <br />اضحت بنات النبی اذ قتلوا<br />فی مأتم و السباع فی عرس .<br /><font color=\"Red\">(از عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٢</span>).</font><br /></font></div>'),
(177175, 'طف', '<span class=\"hlight\">طف .</span> <font color=\"DarkGreen\"><b>[ طَف ف ]</font></b> (ع اِ) طف المکوک و الاناء؛ پُری پیمانه تا سر آن . (منتهی الارب ). پُری پیمانه تا اطراف پیمانه . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آنچه بر سر پیمانه باشد بعد پُری یا آن جمام پیمانه است . رجوع به جمام شود. یا پُری آن . طَفَف و طَفاف مثله فی الکل . (منتهی الارب ). آنچه در پیمانه ماند بعد از دست کشیدن بر سر آن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> کناره ٔ دریا. (مهذب الاسماء). کرانه ٔ دریا. (منتخب اللغات ). کرانه . (منتهی الارب ). جانب و پهلو. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> هر زمین عرب که مشرف بر زمین آبادان عراق است . هر زمین بلند. <BR><font color=\"Blue\">◄</font> (ص ) فرس ٌ طف ؛ اسب سبک و تیزرو. فرس ٌ فف و فرس دف مثله . (منتهی الارب ).<br /></font></div>'),
(177176, 'طفاح', '<span class=\"hlight\">طفاح .</span> <font color=\"DarkGreen\"><b>[طِ ]</font></b> (ع اِ) طِفاح الارض ؛ پُری زمین . (منتهی الارب ).<br /></font></div>'),
(177177, 'طفاحة', '<span class=\"hlight\">طفاحة.</span> <font color=\"DarkGreen\"><b>[ طُ ح َ ]</font></b> (ع اِ) کف . زَبَد. کفک دیگ . (زمخشری ). کف دیگ . (مهذب الاسماء). سرآمد هر چیزی مانند کفک دیگ و جز آن . (منتهی الارب ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177178, 'طفاحة', '<span class=\"hlight\">طفاحة.</span> <font color=\"DarkGreen\"><b>[ طَف ْ فا ح َ ]</font></b> (ع ص ) ناقةٌ طَفّاحةالقوائم ؛ شتاب رو و سبکپای تیزقدم . (منتهی الارب ).<br /></font></div>'),
(177179, 'طفاسة', '<span class=\"hlight\">طفاسة.</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (ع مص ) طفس . چرکن و ریمناک شدن جامه . (منتهی الارب ). شوخگن شدن . (تاج المصادر).<br /></font></div>'),
(177180, 'طفاطف', '<span class=\"hlight\">طفاطف .</span> <font color=\"DarkGreen\"><b>[ طَ طِ ]</font></b> (ع اِ) ج ِ طَفطفة و طِفطفة. (منتهی الارب ).<br /></font></div>'),
(177181, 'طفاف', '<span class=\"hlight\">طفاف .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ]</font></b> (ع اِ) سیاهی شب . <BR><font color=\"Blue\">◄</font> طف . رجوع به طف شود. (منتهی الارب ) (منتخب اللغات ).<br /></font></div>'),
(177182, 'طفاف', '<span class=\"hlight\">طفاف .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) آنچه زائد و بر سر پیمانه باشد. طُفافة. طَفَفة. (منتهی الارب ). آنچه زیادت آید از پیمانه ٔ سر ظرف . (منتخب اللغات ).<br /></font></div>'),
(177183, 'طفاف', '<span class=\"hlight\">طفاف .</span> <font color=\"DarkGreen\"><b>[ طَف ْ فا ]</font></b> (ع ص ) فرس ٌ طفاف ؛ اسپ تیزرو. (منتهی الارب ). اسپی که سبک و جَلد باشد. <BR><font color=\"Blue\">◄</font> ظرفی که تا لبها رسیده باشد. (منتخب اللغات ).<br /></font></div>'),
(177184, 'طفاف', '<span class=\"hlight\">طفاف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) آبی است . (معجم البلدان ).<br /></font></div>'),
(177185, 'طفافة', '<span class=\"hlight\">طفافة.</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (ع اِ) آنچه زائد و بر سر پیمانه باشد. طفاف . طففة. <BR><font color=\"Blue\">◄</font> اندک کمتر از پُری پیمانه . (منتهی الارب ).<br /></font></div>'),
(177186, 'طفال', '<span class=\"hlight\">طفال .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص، اِ) ج ِ طَفْل . (منتهی الارب ).<br /></font></div>'),
(177187, 'طفال', '<span class=\"hlight\">طفال .</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) طُفال . گل و لای خشک . (منتهی الارب ).<br /></font></div>'),
(177188, 'طفال', '<span class=\"hlight\">طفال .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) طَفال . گل و لای خشک . (منتهی الارب ). طین یابس . (فهرست مخزن الادویه ).گل خشک . (منتخب اللغات ).<br /></font></div>'),
(177189, 'طفال', '<span class=\"hlight\">طفال .</span> <font color=\"DarkGreen\"><b>[ طَف ْ فا ]</font></b> (ع ص ) سمعانی آرد: این نسبت بر کسانی اطلاق شود که فروختن «طفل » را پیشه سازند و طفل نوعی گِل است که آن را میخورند. و در اصل لغت آن را «طفل سیاه » نامند، چه گِلی را که میخورند بعلت برشته کردن سیاه میشود و در کشور مصر فروشنده ٔ این نوع گِل را طفال میخوانند. (انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧</span>).<br /></font></div>'),
(177190, 'طفال', '<span class=\"hlight\">طفال .</span> <font color=\"DarkGreen\"><b>[طَف ْ فا ]</font></b> (اِخ ) ابوالحسن محمدبن حسین بن احمدبن سری بن مقری بن طفال، از مردم مصر. شیخی ثقه و صدوق بوده احادیث بسیار روایت کرده است . وی از ابوطاهر احمدبن عبداﷲبن نصر قاضی ذهلی و ابوالحسن بن جویه و ابومحمد حسن بن رسق عسکری که از اهالی مصر بوده سماع کرده و ابوبکر محمدبن اسماعیل بن احمد کسبی و ابوالفتح نصربن حسن بن قاسم سکنی و ابومحمد عبدالعزیزبن محمدبن محمد نخشبی حافظ از وی روایت دارند و ابومحمد حافظ نام وی را در معجم شیوخ خویش یاد کرده و گفته است وی در اصل از نیشابور بوده و پدرش در مصر سکونت گزیده و او در مصر متولد شده است ... (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧</span>).<br /></font></div>'),
(177191, 'طفالة', '<span class=\"hlight\">طفالة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع مص ) طفولة. نرم و نازپروریده گردیدن . <BR><font color=\"Blue\">◄</font> خرد و ریزه شدن . طفولة. طفولیة. (منتهی الارب ).<br /></font></div>'),
(177192, 'طفالة', '<span class=\"hlight\">طفالة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِخ )قصبه ای است در اندلس . (الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٤</span>).<br /></font></div>'),
(177193, 'طفالغو', '<span class=\"hlight\">طفالغو.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) طبرخون . (صحاح الفرس ). و رجوع به طبرخون شود.<br /></font></div>'),
(177194, 'طفان', '<span class=\"hlight\">طفان .</span><font color=\"DarkGreen\"><b>[ طَف ْ فا ]</font></b> (ع ص ) اناء طفان ؛ پیمانه ٔ برتر از لبهاپر شده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کوز طفان ؛ کوزه ٔ کهنه . (مهذب الاسماء).<br /></font></div>'),
(177195, 'طفانیة', '<span class=\"hlight\">طفانیة.</span> <font color=\"DarkGreen\"><b>[ طَی َ ]</font></b> (ع ص ) دشنام است مرد و زن را. (منتهی الارب ).<br /></font></div>'),
(177196, 'طفانین', '<span class=\"hlight\">طفانین .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) دروغ . <BR><font color=\"Blue\">◄</font> کلام بی خیر. <BR><font color=\"Blue\">◄</font> تخلف . <BR><font color=\"Blue\">◄</font> زندان . (منتهی الارب ).<br /></font></div>'),
(177197, 'طفاوی', '<span class=\"hlight\">طفاوی .</span><font color=\"DarkGreen\"><b>[ طُ وی ی ]</font></b> (اِخ ) ابوالمنذر محمدبن عبدالرحمان طفاوی . از ائمه ٔ بصره که از حمید طویل و اعمش و هشام بن عروة و ایوب سجستانی روایت کرده است و احمدبن حنبل و زهیربن حرب و علی بن مدینی و مقدمی و ابوالاشعث احمدبن مقدام عجلی و عمروبن محمد ناقد از وی روایت دارند... علی بن مدینی میگفت وی ثقه است . ابوالمنذر بسال <span class=\"hlight\" dir=\"rtl\">١٨٧</span>هَ . ق . درگذشته است . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧١</span>).<br /></font></div>'),
(177198, 'طفاوی', '<span class=\"hlight\">طفاوی .</span> <font color=\"DarkGreen\"><b>[ طُ وی ی ]</font></b> (ص نسبی ) نسبت است به طفاوة. (انساب سمعانی ). و این طفاوة چنانکه از عیون الاخبار نقل کردیم موضعی به بصره بوده است .<br /></font></div>'),
(177199, 'طفاوی', '<span class=\"hlight\">طفاوی .</span> <font color=\"DarkGreen\"><b>[ طُ وی ی ]</font></b> (اِخ ) ابوالمهلب هدیم بن عثمان بن عیسی بن هدیم بن عتیق طفاوی . از مردم بصره بوده است . اواز بندام بن مسکین و عبادةبن زادان و ابوهلال راسی و حمادبن سلمة و قاسم بن فضل حدانی و عبدالعزیزبن مسلم روایت دارد و ابوزرعه و ابوحاتم رازیان و گروه دیگری از وی روایت کرده اند. (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧١</span>).<br /></font></div>'),
(177200, 'طفاوی', '<span class=\"hlight\">طفاوی .</span> <font color=\"DarkGreen\"><b>[ طُ وی ی ]</font></b> (اِخ ) ابوالهول عطیة طفاوی . از تابعین بصره بوده است که از ابوعمر روایت کرده است و سلیمان تمیمی و خالد الحذا و عوف اعرابی از او روایت دارند. (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧١</span>).<br /></font></div>'),
(177201, 'طفاوی', '<span class=\"hlight\">طفاوی .</span> <font color=\"DarkGreen\"><b>[ طُ وی ی ]</font></b> (اِخ ) عبداﷲبن عیسی طفاوی . از مردم بصره بوده که در بغداد سکونت گزیده است و در آنجا از پدرش حدیث کرده است . وی از عاصم و یوسف بن عطیه ٔ صفار و عبیداﷲبن سمیطبن عجلان سماع دارد و ابراهیم بن عبداﷲبن جنید و حاتم بن لیث جوهری وعبداﷲبن احمدبن ابراهیم دورقی و ابوبکربن ابی الدنیااز او روایت کرده اند. (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧١</span>).<br /></font></div>'),
(177202, 'طفاوی', '<span class=\"hlight\">طفاوی .</span> <font color=\"DarkGreen\"><b>[ طُ وی ی ]</font></b> (اِخ ) مدرک بن عبدالرحمان طفاوی . از مردم بصره بوده و از حمیدطویل روایت کرده است . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧١</span>).<br /></font></div>'),
(177203, 'طفح', '<span class=\"hlight\">طفح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص )پر و لبالب گردیدن آوند و پر کردن آن (لازم و متعدی ). (منتهی الارب ). سرریز شدن . لبریز شدن . لبالب و پر شدن ظرف . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> پر شدن از شراب . <BR><font color=\"Blue\">◄</font> بر تمامی ایام بچه آوردن زن . <BR><font color=\"Blue\">◄</font> برداشتن باد پنبه را و بردن . (منتهی الارب ).<br /></font></div>'),
(177204, 'طفحان', '<span class=\"hlight\">طفحان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) اناء طفحان ؛ خنور لبریز. (منتهی الارب ).<br /></font></div>'),
(177205, 'طفحی', '<span class=\"hlight\">طفحی .</span> <font color=\"DarkGreen\"><b>[ طَ حا ]</font></b> (ع ص ) تأنیث طفحان : قصعةٌ طفحی ؛ خنور لبریز. (منتهی الارب ).<br /></font></div>'),
(177206, 'طفذ', '<span class=\"hlight\">طفذ.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ف َ ]</font></b> (ع اِ) گور. (منتهی الارب ).<br /></font></div>'),
(177207, 'طفذ', '<span class=\"hlight\">طفذ.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) دفن کردن . در گور کردن . (منتهی الارب ).<br /></font></div>'),
(177208, 'طفر', '<span class=\"hlight\">طفر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) طفور. طفرة. برجستن .<br /></font></div>'),
(177209, 'طفر', '<span class=\"hlight\">طفر.</span> <font color=\"DarkGreen\"><b>[ طَف ْ ف ِ ]</font></b> (اِخ ) بیابان موحشی است میان باعقوبا و دقوقا از اعمال راذان که در آن نه آب است و نه چراگاه و نه اثر ساکنی و نه نشان راهروی . یاقوت گوید:هنگام مسافرت از بغداد به اربل یک بار از آنجا گذشتیم و راهنمای ما به هدایت ستاره ٔ جدی پیش میرفت تا شب بسر آمد و آن بیابان قطع کردیم . (معجم البلدان ).<br /></font></div>'),
(177210, 'طفرآباذ', '<span class=\"hlight\">طفرآباذ.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) محلتی است به همدان . (معجم البلدان ).<br /></font></div>'),
(177211, 'طفراویسما', '<span class=\"hlight\">طفراویسما.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) طفردوسما. به سریانی اظفارالطیب است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177212, 'طفرجیل', '<span class=\"hlight\">طفرجیل .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِخ ) نام یکی از شهرهای مغرب . یاقوت گوید: ممکن است این نام را مرکب از دو کلمه ٔ طفر بمعنی بیابان و جیل بمعنی امت گرفت و لکن آن نامی است اعجمی . (معجم البلدان ).<br /></font></div>'),
(177213, 'طفردوسما', '<span class=\"hlight\">طفردوسما.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) طفرادیسما. به سریانی اظفارالطیب است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177214, 'طفرس', '<span class=\"hlight\">طفرس .</span> <font color=\"DarkGreen\"><b>[ طِ رِ ]</font></b>(ع ص ) نرم و سهل . (منتهی الارب ). مؤلف منتخب اللغات این لغت را که قاموس اللین السهل آورده بر اثر تحریف نساخ اللبن خوانده و «شیر گوارا» معنی کرده است .<br /></font></div>'),
(177215, 'طفس', '<span class=\"hlight\">طفس .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ ]</font></b> (ع ص ) پلید و نجس ازمردم و جز آن . (منتهی الارب ). پلید. (منتخب اللغات ). چرک . ریمناک . (منتهی الارب ). چرکین . (منتخب اللغات ).<br /></font></div>'),
(177216, 'طفس', '<span class=\"hlight\">طفس .</span> <font color=\"DarkGreen\"><b>[ طَف َ ]</font></b> (ع مص ) طفاسة. چرکین و ریمناک شدن جامه . (منتهی الارب ). شوخکن شدن . (تاج المصادر). <BR><font color=\"Blue\">◄</font> پلیدی مردم . <BR><font color=\"Blue\">◄</font> پلیدی کردن . (منتهی الارب ).<br /></font></div>'),
(177217, 'طفس', '<span class=\"hlight\">طفس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) آرمیدن با زن . (منتهی الارب ) (منتخب اللغات ).<br /></font></div>'),
(177218, 'طفسونج', '<span class=\"hlight\">طفسونج .</span> <font color=\"DarkGreen\"><b>[ طَن َ ]</font></b> (اِخ ) شهری است به کنار دجله . (منتهی الارب ).<br /></font></div>'),
(177219, 'طفسیا', '<span class=\"hlight\">طفسیا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) به یونانی سداب جبلی است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177220, 'طفسیقون', '<span class=\"hlight\">طفسیقون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) طخشیقون است و گویند سم شوکران است . (تحفه ). و رجوع به طفشیقون شود.<br /></font></div>'),
(177221, 'طفش', '<span class=\"hlight\">طفش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) آرمیدن با زن . (منتهی الارب ). نکاح . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> پلیدی کردن . (منتهی الارب ). پلیدی . (منتخب اللغات ).<br /></font></div>'),
(177222, 'طفشیر', '<span class=\"hlight\">طفشیر.</span> <font color=\"DarkGreen\"><b>[ طَ<span class=\"hlight\" dir=\"rtl\">/</span> طِ ]</font></b> (اِ) این کلمه بدین صورت در ترجمه ٔ تاریخ طبری آمده است و ظاهراً طفشیل یا محرف آن باشد <span class=\"hlight\">:</span> موسی علیه السلام دیگر روز از آنجای برفت تا به مصر آمد... چون به در خانه اندرآمد مادرش نشناخت که دوازده سال بود تا او رفته بود... او را اندر خانه جای کرد و طعام پیش آورد و هارون را گفت که با این مهمان بنشین و نان خور تا او را عزیز کرده باشی و به خبراندر ایدون گویند که آن خوردی که همی خوردند طفشیر بود... (ترجمه ٔ طبری بلعمی ). و رجوع به طفشیل شود.<br /></font></div>'),
(177223, 'طفشیقون', '<span class=\"hlight\">طفشیقون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) طخشیقون است و بعضی شوکران دانسته اند و اصلی ندارد. (فهرست مخزن الادویه ). نام دوایی است به لغت رومی که آن را از ملک ارمن آورند و پیکان تیر و بیشتر اسلحه ٔ جنگ را بدان زهرآلود سازند. و بجای حرف ثانی، خاء نقطه دار هم به نظر آمده است که طخشیقون باشد. (برهان ).<br /></font></div>'),
(177224, 'طفشیل', '<span class=\"hlight\">طفشیل .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (ع اِ) نوعی از طعام باشد و آن عدس مقشرکرده است که با سرکه پزند و خورند. (برهان ). عدس مقشر است که با سرکه پخته باشند و به فارسی عدسی نامند. (مخزن الادویه ). عدس مقشر است که در سرکه پخته باشند و از اغذیه ٔ قدیمیه و مقوی معده ٔ حاره و قلیل الغذا و جهت تبهای مرکبه ٔ بلغمی و صفراوی و قطع نمودن حیض و سلس البول و تسکین حدت خون و صفرا نافع و مضر امراض سوداوی و اعضای عصبانی و قاطع باه و مصلحش شیرینی هاست . (تحفه ٔ حکیم مؤمن ) <span class=\"hlight\">:</span> و طعام، طفشیل و کوک با سماق یا با زرشک فرمایند. (ذخیره ٔ خوارزمشاهی ). اگر قلاع (کودک ) سرخ است مادر را فصد و حجامت فرمایند و طعام او طفشیل از عدس مقشر فرمایند. (ذخیره ٔ خوارزمشاهی ). و از چیزهاء خنک که اندر این باب <font color=\"DarkGreen\"><b>[ باب تدبیر زنی که شیر او بسیارباشد و از آن پستانها را درد خیزد ]</font></b> سود دارد طفشیل است که از عدس و سرکه پزند. (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(177225, 'طفشیل کردن', '<span class=\"hlight\">طفشیل کردن .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ک َ دَ ]</font></b> (مص مرکب ) شوربا کردن <span class=\"hlight\">:</span> و عدس هرگاه که ... او را به آب ناردانک یا سماق یا زرشک طفشیل کنند طبع را خنک کند. (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(177226, 'طفطار', '<span class=\"hlight\">طفطار.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) سوسمار کلان سال بدسرشت بدخلقت . (منتهی الارب ).<br /></font></div>'),
(177227, 'طفطاف', '<span class=\"hlight\">طفطاف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b>(ع اِ) کرانه ٔ جوی و جانب آن . <BR><font color=\"Blue\">◄</font> اطراف وکرانه های درخت . (منتهی الارب ). کرانه های درخت . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> نبات نازک . (مهذب الاسماء).<br /></font></div>'),
(177228, 'طفطان', '<span class=\"hlight\">طفطان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) به عربی اطراف شجر است . (فهرست مخزن الادویه ). ظاهراً مصحف طفطاف است .<br /></font></div>'),
(177229, 'طفطفة', '<span class=\"hlight\">طفطفة.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ف َ ]</font></b> (ع مص ) نرم و فروتن گردیدن بر دوست و دشمن . (منتهی الارب ).<br /></font></div>'),
(177230, 'طفطفة', '<span class=\"hlight\">طفطفة.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ف َ ]</font></b> (ع اِ) تهیگاه . اطراف پهلو متصل اضلاع . (منتهی الارب ). گوشت پهلو. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> هر گوشت پاره ٔ مضطرب . گوشت پاره ٔ نرم از نرم جای شکم . ج، طفاطف . (منتهی الارب ).<br /></font></div>'),
(177231, 'طفغاج خان', '<span class=\"hlight\">طفغاج خان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) جغراتکین بن نصر، ملقب به عمادالدوله، مکنی به ابوالمظفر. از سلاطین ایلک خانیه ٔ ترکستان یا آل افراسیاب . رجوع به آل افراسیاب و ابوالمظفر عمادالدوله ابراهیم طفغاج شود.<br /></font></div>'),
(177232, 'طفف', '<span class=\"hlight\">طفف .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (ع اِ) طفاف . طف . پُری پیمانه تا سر آن . <BR><font color=\"Blue\">◄</font> آنچه بر سر پیمانه باشد بعد پُری، یا آن جمام پیمانه است، یا پُری آن . (منتهی الارب ).<br /></font></div>'),
(177233, 'طففة', '<span class=\"hlight\">طففة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ف َ ]</font></b> (ع اِ) طفافة. آنچه زائد و بر سر پیمانه باشد. (منتهی الارب ).<br /></font></div>'),
(177234, 'طفق', '<span class=\"hlight\">طفق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) نزدیک شدن . <BR><font color=\"Blue\">◄</font> شروع کردن در چیزی . طفوق . (منتخب اللغات ).<br /></font></div>'),
(177235, 'طفق', '<span class=\"hlight\">طفق .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (ع مص ) درایستادن در کاری . (دهار). در کاری ایستادن . (زوزنی ). درکاری کردن ایستادن . (تاج المصادر) . طفوق . (منتهی الارب ). کردن گرفتن . و منه <span class=\"hlight\">:</span> طفقا یخصفان علیهما من ورق الجنة (قرآن <span class=\"hlight\" dir=\"rtl\">٢٢/٧</span>)؛ یعنی دوختن گرفتند از برگ . و هو خاص بالاثبات فلایقال ماطفق . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شروع کردن . <BR><font color=\"Blue\">◄</font> نزدیک شدن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> به مراد رسیدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> به موضعی ماندن و بدانجا مقیم شدن . (منتخب اللغات ). لازم گرفتن جای را. (منتهی الارب ).<br /></font></div>'),
(177236, 'طفقاج', '<span class=\"hlight\">طفقاج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ظاهراً نام موضعی به ماوراءالنهر بوده است . در تذکره ٔ تقی الدین و نیز در سه نسخه ٔ سوزنی کهن که نزد من هست این کلمه بصورت فوق آمده است که معلوم میکند شهری از ماوراءالنهر است و شاید مشک خیز نیز بوده است . این لفظ را در معجم البلدان و ذیل آن منجم العمران نیافتم و در تاء منقوطه نیز نبود وبا هر دو تا با تبدیل فاء به میم نیز یافته نشد. ولی در نسخ دیوان سوزنی بدینسان آمده است <span class=\"hlight\">:</span> <br />گیسوی تو شهپر همای نبوی دان <br />بوینده چو مشک تبت و تنگت و طفقاج <br />گر مدعیان گیسوی مشکین تو بینند<br />دانند که نز جنس همای است غلیواج .<br /> <font color=\"Red\">سوزنی .</font><br />در وزنی دیگر کلمه ای شبیه به این سوزنی آورده است که ظاهراً مراد قفقاز است بدین صورت :<br />شاعرانی کم ارزو کم قیمت <br />از حد بصره تا حد کفغاج .<br />ولی در بیت اول تصور نمیتوان کرد که شاعر در ردیف تنگت و تبت قفقاز آورده باشد خاصه که این شاعر در امر لغت و اعلام بی عدیل است و آش طفقاج نیز ظاهراً منسوب به همین شهر بوده که گران و پرخرج و مخصوص متمولین بوده است <span class=\"hlight\">:</span> <br />صاحب بود آنکه آش طفقاج خورد<br />گوزینه و لوزینه وگلناج خورد<br />نی چون تو کسی که آش تتماج خورد<br />در مصطبه ها بغل زند کاج خورد.<br /> <font color=\"Red\">سوزنی .</font><br />محمود کاشغری در کتاب دیوان لغات الترک ذیل «تفغاج » (صورت دیگر طفقاج ) گوید: اسم ماچین است و آن بعد از چین است به مسافت چهار ماه راه و سپس می افزاید: اما چین سه بخش بوده است و در اصل یکی چین علیا در شرق تفقاج، دیگر چین وُسطی یا خطای و سوم چین سفلی یا بَرخان که این اخیر به کاشغر است، اما در این زمان (سال <span class=\"hlight\" dir=\"rtl\">٤٦٧</span> هَ . ق .) تفغاج را ماچین و خطای را چین دانند. (دیوان لغات الترک چ استانبول <span class=\"hlight\" dir=\"rtl\">١٣٣٣</span> هَ . ق . ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٨</span>). با اینهمه ممکن است محرف طمغاج باشد و آن نام شهری بوده است در اقصای ترکستان شرقی در حدود چین یا در داخل چین شمالی . به کلمه ٔ طمغاج رجوع شود. و ذکر آن در کتاب طبقات ناصری آمده بخصوص یک جا با کلمه ٔ تنگت استعمال شده و در اشعار شعرائی چون خاقانی و مختاری و دیگران ذکر گردیده و در کتبی چون سیرة جلال الدین منکبرنی و آثارالبلاد قزوینی و غیره نیز ثبت افتاده است .<br /></font></div>'),
(177237, 'طفقان', '<span class=\"hlight\">طفقان .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (ع مص ) در کاری کردن ایستادن . طفق . (تاج المصادر).<br /></font></div>'),
(177238, 'طفقان', '<span class=\"hlight\">طفقان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام کوهی است به تغزغز که در پیش آن قصبه ٔ جنیانجکث مستقر تغزغز است و از پس آن کوزارک، جملکت، بنجیکث، بارلغ، جامغر. (حدود العالم ).<br /></font></div>'),
(177239, 'طفل', '<span class=\"hlight\">طفل .</span> <font color=\"DarkGreen\"><b>[ طَف َ ]</font></b> (ع اِ) تاریکی . <BR><font color=\"Blue\">◄</font> باران . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> طفل العشی ؛ آخر روزنزدیک غروب . (منتهی الارب ). آخر روز بعد از نماز دیگر. (منتخب اللغات ). وقت فروشدن آفتاب . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> طفل الغداة؛ از صبح تا وقت غروب کردن آفتاب . (منتهی الارب ). هنگام چاشت . (منتخب اللغات ).<br /></font></div>'),
(177240, 'طفل', '<span class=\"hlight\">طفل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) اسم اندلسی طین قیمولیاست ونیز کمون بری را نامند. (فهرست مخزن الادویه ). یسمی طین قیمولیان و الطلیطلی و البکیوت . (تذکره ٔ ضریر انطاکی ). اسم اندلسی قیمولیاست . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(177241, 'طفل', '<span class=\"hlight\">طفل .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) بچه . نوزاد آدمی .زغلول . کودک . مولود. (منتخب اللغات ). نوزاد مردم و جانوران وحشی . (منتهی الارب ). کودک خرد. یکی را گویند و جماعتی را نیز گویند. (مهذب الاسماء). مسعودی گوید:طفل خردتر از صبی است . ج، اطفال . صاحب آنندراج گوید: زمان طفولیت از ولادت تا وقت بلوغ و عندالبعض تا وقت حرکت و نهوض، کذا فی بعض شروح نصاب و یتیم و بی مادر و بی زبان و بسته زبان و شیرمک و شیرمست و خاک نشین وبازی گوش و بدخو و بهانه جو و خودسر و خودرأی و شوخ و بیباک و زیرک و نی سوار و نورفتار و نوبپاآمده و بکرنگاه و زبان دان در فارسی از صفات اوست <span class=\"hlight\">:</span> <br />طفل را چون شکم به درد آمد<br />همچو افعی ز رنج او بربیخت <br />گشت ساکن ز درد چون دارو<br />زن به ماچوچه در دهانش ریخت .<br />پروین خاتون (از حاشیه ٔ فرهنگ اسدی نسخه ٔ خطی نخجوانی ).<br />پیر در دست طفل گردد اسیر<br />پشه گیرد چو باشه گردد پیر.<br /> <font color=\"Red\">سنائی .</font><br />طفلی هنوز بسته ٔ گهواره ٔ فنا.<br />مرد آن زمان شوی که شوی از همه جدا.<br /> <font color=\"Red\">خاقانی .</font><br />ما طفل وار سرزده و مرده مادریم <br />اقبال پهلوان عجم دایگان ماست .<br /> <font color=\"Red\">خاقانی .</font><br />چو آن عودالصلیب اندر بر طفل <br />صلیب آویزم اندر حلق عمدا.<br /> <font color=\"Red\">خاقانی .</font><br />هیچ طفلی در این دبستان نیست <br />که ورا سوره ٔ وفا ز بر است .<br /> <font color=\"Red\">خاقانی .</font><br />طفل می نالید یعنی قرص رنگین کوچک است <br />سگ دوید آن قرص زو بربود و آنک رفت راست .<br /> <font color=\"Red\">خاقانی .</font><br />نذر کردم که در مدت این فتنه و ایام این محنت جز در بیاض روز از خانه بیرون نیایم و پیش از طفل آفتاب بر سر آفتاب روم . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٢٩</span>). طفل بودم که بزرگی را پرسیدم از بلوغ . (گلستان ).<br />طفل چون صاحب احسان گردد<br />زود از داده پشیمان گردد.<br /> <font color=\"Red\">جامی .</font><br />غلام مذأب ؛ طفل باگیسو. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">طفل را به کاری فرست و خود از پی او برو</span> .<br /> <span class=\"hlight\">طفل عاقِل ز پیر جاهل بِه ْ</span> .<br /> <BR><font color=\"Blue\">◄</font> کوچک از هر چیز. (منتخب اللغات ). خرد و ریزه ٔ هر چیزی و هو واحد و جمع مثل الجنب . قوله تعالی <span class=\"hlight\">:</span> او الطفل الذین لم یظهروا. (قرآن <span class=\"hlight\" dir=\"rtl\">٣١/٢٤</span>). ج، اطفال . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> در اصطلاح نردبازان، مهره <span class=\"hlight\">:</span> <br />از پی سی طفل را در یک بساط<br />آن سه لعبت ز استخوان آخرکجاست .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> نیاز. <BR><font color=\"Blue\">◄</font> شب . <BR><font color=\"Blue\">◄</font> آفتاب قریب به غروب . <BR><font color=\"Blue\">◄</font> اخگر که از آتشزنه برافتد. <BR><font color=\"Blue\">◄</font> خرد وپاره ای از هر چیزی عین باشد یا حدث و معنی . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفلان آتش </span> ؛ کنایه ازشراره باشد <span class=\"hlight\">:</span> <br />دویدند قومی دلیران روم <br />چو طفلان آتش به تاراج موم .<br /> <font color=\"Red\">امیرخسرو (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفلان چمن </span> ؛ نباتات نورسته <span class=\"hlight\">:</span> <br />طفلان چمن را چو شرر نیست بقائی <br />در باغ خزان است که همزاد بهاراست .<br /> <font color=\"Red\">سلیم (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل بر در مسجد و به مسجد افکندن </span> ؛ چون زن فاحشه از نطفه ٔ حرام فرزندی بار آرد نهانی آن را بر در مسجد افکندتا هرکه به سروقتش رسد بردارد <span class=\"hlight\">:</span> <br />مرد خدا نمیشود گرچه زند کنار خود<br />بر در مسجد افکند طفل حرامزاده را.<br /> <font color=\"Red\">ملاطغرا (از آنندراج ).</font><br />طفل اشکی کز غم دنیا ز طبعت زاده است <br />شرم بادت گر ز چشم آن را به مسجد افکنی .<br /> <font color=\"Red\">شفیع اثر (از آنندراج ).</font><br />ریخت به خانه ٔ خدا اشک ریای زاهدان <br />قحبه به مسجد افکند طفل حرامزاده را.<br /> <font color=\"Red\">سعید اشرف (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل چهل روزه </span> ؛ اشاره به آدم صفی (ع ) است بسبب آنکه گِل او در چهل روز سرشته شد. (برهان ) (غیاث ) (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل خونی یا خونین </span> ؛ آفتاب <span class=\"hlight\">:</span> <br />برشکافد فلک مشیمه ٔشب <br />طفل خونین به خاور اندازد.<br /> <font color=\"Red\">خاقانی (از آنندراج ).</font><BR>۩ اشک را نیز گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل دبستان </span> ؛ کنایه از کسی که هیچ رتبه و قدری نداشته باشد. (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل در گریبان انداختن </span> ؛ رسم ولایت است خاتونی که پسر ندارد و خواهد که پسر یکی از اقربا به فرزندی گیرد پسر او را در گریبان کرده از دامن برمی آرد و در این شرط است به آنکه از من زاده است، پس عبارت مذکور بمعنی به پسری گرفتن باشد <span class=\"hlight\">:</span> <br />ز دل زائیده طفل اشک چشم ازخویش میداند<br />چو فرزندی که اندازند مردم در گریبانش .<br /> <font color=\"Red\">طاهر وحید (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل را از پستان بریدن و از شیر باز کردن و از شیر بریدن و از شیر واگرفتن </span> ؛ جدا کردن او را و بازداشتن از شیر و آن را به تازی فطام گویند <span class=\"hlight\">:</span> <br />رسید نوبت بیداربختیم وقت است <br />که طفل خواب ز شیر فسانه واگیرم .<br /> <font color=\"Red\">نورالدین ظهوری (از آنندراج ).</font><br />چو رفت ایام شیر و عهد نازش <br />به عادت دایه کرد از شیر بازش .<br /> <font color=\"Red\">بیانی (از آنندراج ).</font><br />ز شیر دختر رز تا بریدم طفل عادت را<br />به حکم دایه ٔ مشرب به خون توبه خو کردم .<br /> <font color=\"Red\">ابوطالب کلیم (از آنندراج ).</font><br />کلیم پیر شدی وقت آن هنوز نشد<br />که طفل طبع ز شیر هوس بریده شود.<br /> <font color=\"Red\">ابوطالب کلیم (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل رزان </span> ؛ شراب انگوری <span class=\"hlight\">:</span> <br />مینا ز می ناب تهی ماند و لب از حرف <br />خاموشی ما مرثیه ٔ طفل رزان است .<br /> <font color=\"Red\">درویش واله هروی (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل زبان دار</span> ؛ کودک زیرک .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل زبان دان </span> ؛ کودکی که سخن استاد زودبفهمد و یاد گیرد و به استاد بازگوید <span class=\"hlight\">:</span> <br />دل من پیر تعلیم است و من طفل زبان دانش .<br /> <font color=\"Red\">خاقانی (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل شب </span> ؛ ماه . (آنندراج ) (غیاث ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل شش روزه </span> ؛ عالم و آنچه در اوست که در شش روز آفریده شد به حکم خلق السموات و الارض فی ستة ایام . میرزا صائب راست <span class=\"hlight\">:</span> <br />ما حریفان کهن سال جهان ازلیم <br />طفل شش روزه ٔ عالم ندهد بازی ما.<BR>۩ و بعضی گویند کنایه از انسان است . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل ششماهه ٔ رز</span> ؛ شراب، چه بعداز شش ماه رسیده شود <span class=\"hlight\">:</span> <br />طفل ششماهه ٔ رز یک نفس آرام نیافت <br />تا نگردید به گهواره ٔ مینا در خواب .<br /> <font color=\"Red\">طغرا (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل شیر و طفل شیرخواره </span> ؛ بمعنی پس اضافت به اندک ملابسته باشد (کذا). و ملا طاهر وحید راست در تعریف میدان اصفهان <span class=\"hlight\">:</span> <br />ازاین سروران گشته گر طفل شیر<br />از آن سر چو برگشته برگشته پیر.<br /> <font color=\"Red\">(از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل مزاج و طفل مشرب </span> ؛ آنکه خوی کودک دارد. ساده لوح . ابوطالب کلیم راست <span class=\"hlight\">:</span> <br />بر طفل مزاجان جهان چون گذرد حال <br />امروز که پستان امل شیر ندارد.<br />میرزا صائب راست :<br />از طفل مشربی است که در کام ناقصان <br />این میوه های خام تمنا شود لذیذ.<br /> <font color=\"Red\">(از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل مشیمه </span>؛ شراب انگوری لعلی . (برهان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل مشیمه ٔ رزان </span> ؛ شراب انگوری . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل مکتب </span> ؛ مرادف طفل دبستان . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل هاله </span> ؛ طفل نوزاد که زیاده از دو سه روز بر او نگذشته باشد و گویند شش روزه و این از اهل زبان به تحقیق پیوسته است وبرخی گویند بدین معنی مسموع نیست، اما طفل حال چنانکه گویند فلانی طفل حال است ؛ فلان مقدمه به خاطرش نیست . راضی راست <span class=\"hlight\">:</span> <br />آن کمان ابرو چوطفل هاله بود از سرکشی <br />چون کمان حلقه ای با ماش ناچاقی بود.<br /> <font color=\"Red\">(از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفل هندو</span> ؛ مردمک چشم را گویند به اعتبار سیاهی . (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br />تانترسند این دو طفل هندو اندر مهد چشم <br />زیر دامن پوشم اژدرهای جان فرسای من .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(177242, 'طفل', '<span class=\"hlight\">طفل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) نازک و نازپرورد از هر چیزی . ج، طِفال، طُفول . یقال : بنان طفل و جاریةٌ طفلة و انما جاز ان یوصف البنان و هو جمع بالطفل و هو واحد لان کل جمعلیس بینه و بین واحده الا الهاء فانه یذکر و یؤنث . (منتهی الارب ). نازک و تازه از هر چیزی . (منتخب اللغات ). امراءةٌ طفل ؛ زنی نازک و نرم . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> سرانگشت نرم و نازک . (دهار). <BR><font color=\"Blue\">◄</font> (اِ) تاریکی . <BR><font color=\"Blue\">◄</font> باران . (منتهی الارب ).<br /></font></div>'),
(177243, 'طفل', '<span class=\"hlight\">طفل .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ف َ ]</font></b> (ع اِ) نوعی از خاک رس برای گرفتن چربی ماهوت . گِل سرشوی . این گل را در حمام برای شستن پوست بدن و مخصوصاً موی سر وهم بجای نوره بکار میبرند. ج، طُفول . و نیز آن را برای شستن جامه استعمال میکنند. (از دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(177244, 'طفل', '<span class=\"hlight\">طفل .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (ع مص ) خاک آلود گشتن نبات . <BR><font color=\"Blue\">◄</font> ناخوانده به مهمانی آمدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رسیدن خاک و گرد خانه را. (منتخب اللغات ).<br /></font></div>'),
(177245, 'طفل', '<span class=\"hlight\">طفل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) درآمدن تاریکی شب . (منتخب اللغات ). در شبانگاه درآمدن . (منتهی الارب ). میل کردن آفتاب به غروب . به غروب قریب شدن آفتاب به وقت غروب . (منتخب اللغات ). سرخی گرفتن آفتاب . (منتهی الارب ). به سرخی مایل شدن آفتاب قبل از غروب . (ازلغات اضداد است ). (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پروردن ناقه بچه را و نیکو اصلاح وی کردن . (منتهی الارب ).<br /></font></div>'),
(177246, 'طفلة', '<span class=\"hlight\">طفلة.</span> <font color=\"DarkGreen\"><b>[ طِ ل َ ]</font></b> (ع اِ) تأنیث طِفْل . دخترینه . ج، طفالة. (مهذب الاسماء). صاحب آنندراج گوید: مذکر و مؤنث در طفل یکسان است و نزد بعضی طفلة مؤنث است .<br /></font></div>'),
(177247, 'طفلة', '<span class=\"hlight\">طفلة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع ص ) تأنیث طَفْل . (منتهی الارب ).<br /></font></div>'),
(177248, 'طفله', '<span class=\"hlight\">طفله .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) شاهترج . شاهتره . (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویه ). به لغت اهل اندلس زیره ٔ صحرائی باشد و به عربی کمون البری خوانندش . (برهان ) (آنندراج ).<br /></font></div>'),
(177249, 'طفلک', '<span class=\"hlight\">طفلک .</span> <font color=\"DarkGreen\"><b>[ طِ ل َ ]</font></b> (اِ مصغر) طفل خردسال . حرف «ک » برای تحبیب است و از روی شفقت گویند <span class=\"hlight\">:</span> <br />کاف رحمت از پی تصغیر نیست <br />جد چو گوید طفلکم تحقیر نیست .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(177250, 'طفلک', '<span class=\"hlight\">طفلک .</span> <font color=\"DarkGreen\"><b>[ طِ ل َ ]</font></b> (اِخ ) دهی از بخش پشت آب شهرستان زابل در <span class=\"hlight\" dir=\"rtl\">١٤</span>هزارگزی جنوب خاوری بنجار و <span class=\"hlight\" dir=\"rtl\">٧</span>هزارگزی راه فرعی بندزهک به زابل . جلگه گرم معتدل با <span class=\"hlight\" dir=\"rtl\">٣٣٦</span> تن سکنه . آب آن از رودخانه ٔ هیرمند. محصول آنجا غلات و لبنیات . شغل اهالی زراعت و گله داری و کرباس بافی و راه آن فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(177251, 'طفلی', '<span class=\"hlight\">طفلی .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (حامص ) کودکی .<br /></font></div>'),
(177252, 'طفلی', '<span class=\"hlight\">طفلی .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِ) درخت مقل است . (تحفه ٔ حکیم مؤمن ).درخت مقل است که دوم نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(177253, 'طفلی', '<span class=\"hlight\">طفلی .</span> <font color=\"DarkGreen\"><b>[ طَ لی ی <span class=\"hlight\" dir=\"rtl\">/</span> طَ ف َ لی ی ]</font></b> (ع ص نسبی ) منسوب به طَفْل یا طَفَل به معنی خاک رس مخصوص . رجوع به دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span> شود.<br /></font></div>'),
(177254, 'طفلیة', '<span class=\"hlight\">طفلیة.</span> <font color=\"DarkGreen\"><b>[ طَ لی ی َ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ف َ لی ی َ ]</font></b> (ع مص جعلی، اِمص ) مشتق از طفل بمعنی خاک رس مخصوص . رجوع به طفل و دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span> شود.<br /></font></div>'),
(177255, 'طفلیل', '<span class=\"hlight\">طفلیل .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص، اِ) آنکه ناخوانده به مهمانی آید. (منتهی الارب ).<br /></font></div>'),
(177256, 'طفن', '<span class=\"hlight\">طفن .</span> <font color=\"DarkGreen\"><b>[طَ ]</font></b> (ع اِ) مرگ . <BR><font color=\"Blue\">◄</font> بند. (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> زندان . (منتهی الارب ).<br /></font></div>'),
(177257, 'طفنش', '<span class=\"hlight\">طفنش .</span> <font color=\"DarkGreen\"><b>[ طَ ف َن ْ ن َ ]</font></b> (ع ص ) آنکه صدر پای او فراخ باشد. (منتهی الارب ). آنکه پیش قدم وی فراخ بود. (مهذب الاسماء). کف پای فراخ . کف پای بزرگ .<br /></font></div>'),
(177258, 'طفنشل', '<span class=\"hlight\">طفنشل .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ش َ ]</font></b> (ع ص ) مرد ضعیف و ناتوان . (منتهی الارب ).<br /></font></div>'),
(177259, 'طفو', '<span class=\"hlight\">طفو.</span> <font color=\"DarkGreen\"><b>[ طَف ْوْ ]</font></b> (ع مص ) طُفُوّ. بالا برآمدن بر آب . (منتهی الارب ). بر سر آب آمدن چیزی . (المصادر زوزنی ). بر سر آب برآمدن چیزی . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> برگ بالای درخت ظاهر شدن . (منتخب اللغات ). ظاهر شدن برگ بر درخت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سخت دویدن آهو و سبک رفتن آن بر روی زمین . (منتخب اللغات ). سخت دویدن آهو. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مردن . (منتخب اللغات ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> داخل شدن در کاری . (منتخب اللغات ). در کاری درآمدن . <BR><font color=\"Blue\">◄</font> برآمدن و نمود گردیدن . (منتهی الارب ).<br /></font></div>'),
(177260, 'طفو', '<span class=\"hlight\">طفو.</span> <font color=\"DarkGreen\"><b>[ طُ ف ُوو]</font></b> (ع مص ) طَفْو. بالا برآمدن بر آب . (منتهی الارب ).<br /></font></div>'),
(177261, 'طفوان', '<span class=\"hlight\">طفوان .</span> <font color=\"DarkGreen\"><b>[ طَف ْ ]</font></b> (اِخ ) وادی طفوان ؛ مغاره ٔ طفوه ٔ راثق را گویند. (نزهةالقلوب ص <span class=\"hlight\" dir=\"rtl\">١٦٩</span>).<br /></font></div>'),
(177262, 'طفوح', '<span class=\"hlight\">طفوح .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) طفح . (منتهی الارب ). لبالب و پر شدن ظرف . (منتخب اللغات ). پر شدن . (تاج المصادر). لبالب شدن خنور. پر و لبالب گردیدن آوند و پر کردن آن را (لازم و متعدی ). (منتهی الارب ).<br /></font></div>'),
(177263, 'طفور', '<span class=\"hlight\">طفور.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) طفرة. (منتهی الارب ). برجستن . (منتخب اللغات ) (منتهی الارب ). بالا برجستن . (منتهی الارب ). از نشیب بر بالا برجستن . (زوزنی ). وثب . (تاج المصادر).<br /></font></div>'),
(177264, 'طفوس', '<span class=\"hlight\">طفوس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) مردن . (منتهی الارب ) (منتخب اللغات ).<br /></font></div>'),
(177265, 'طفوق', '<span class=\"hlight\">طفوق .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) کردن گرفتن . (منتهی الارب ). شروع کردن . آغازیدن . در کاری ایستادن . (زوزنی ). شروع کردن چیزی . <BR><font color=\"Blue\">◄</font> نزدیک شدن . (منتخب اللغات ).<br /></font></div>'),
(177266, 'طفول', '<span class=\"hlight\">طفول .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طفل . (منتهی الارب ).<br /></font></div>'),
(177267, 'طفولة', '<span class=\"hlight\">طفولة.</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (ع مص ) نرم و نازپرورده گردیدن . <BR><font color=\"Blue\">◄</font> خرد و ریزه شدن . (منتهی الارب ).<br /></font></div>'),
(177268, 'طفولیة', '<span class=\"hlight\">طفولیة.</span> <font color=\"DarkGreen\"><b>[ طُ لی ی َ ]</font></b> (ع مص ) طفولة. طفالة. خرد و ریزه شدن . (منتهی الارب ).<br /></font></div>'),
(177269, 'طفولیت', '<span class=\"hlight\">طفولیت .</span> <font color=\"DarkGreen\"><b>[ طُ لی ی َ ]</font></b> (ع اِمص ) کودکی . بچگی . صباوت . خردسالی . صبا <span class=\"hlight\">:</span> از عصر طفولیت به زمان شباب رسید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٩٧</span>). او در سن طفولیت ... موسم ضعف رای و نقصان رشد بود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span>). یاد دارم که در ایام طفولیت متعبد بودمی و شبخیز. (گلستان ).<br /></font></div>'),
(177270, 'طفی', '<span class=\"hlight\">طفی .</span> <font color=\"DarkGreen\"><b>[ طُ فا ]</font></b> (ع اِ) ج ِ طفیة. (منتهی الارب ).<br /></font></div>'),
(177271, 'طفیة', '<span class=\"hlight\">طفیة.</span> <font color=\"DarkGreen\"><b>[ طُف ْ ی َ ]</font></b> (ع اِ) برگ مقل . ج، طفی . (منتهی الارب ). خوصه ٔ مقل . (فهرست مخزن الادویه ). اسلم . شاخه های مقل . <BR><font color=\"Blue\">◄</font> ماری است خبیث که بر پشت دو خط سپید دارد مانند دو برگ مقل و منه الحدیث : اقتلوا ذوالطفیتین . (منتهی الارب ).<br /></font></div>'),
(177272, 'طفیشل', '<span class=\"hlight\">طفیشل .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ش َ ]</font></b> (ع اِ) نوعی از شوربا. (منتهی الارب ). ابوطفیشل . شوربای ابوهشام .<br /></font></div>'),
(177273, 'طفیشل کردن', '<span class=\"hlight\">طفیشل کردن .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ش َ ک َ دَ ]</font></b> (مص مرکب ) شورباکردن <span class=\"hlight\">:</span> و عدس هرگاه او را دو سه کرت به آب بجوشانند... و او را به آب ناردانگ یا سماق یا زرشک طفیشل کنند طبع را خشک کند. (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(177274, 'طفیف', '<span class=\"hlight\">طفیف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) اندک . (منتهی الارب ) (مهذب الاسماء) (منتخب اللغات ). ناقص . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ناتمام . (منتهی الارب ) (منتخب اللغات ).<br /></font></div>'),
(177275, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (اِخ ) ابن حارث بن عبدالمطلب بن هاشم صحابی قرشی . شوی نخستین زینب بنت خزیمه است و زینب را پس از درگذشتن طفیل بقولی برادر او عبیده و بقولی عبدبن جحش بخواست و پس از وفات زوج ثانی دررمضان سال سوم هجرت وی به عقد رسول اکرم درآمد. طفیل غزوه ٔ بدر و احد و دیگر مشاهد را درک کرد و خود ازشجعان و شرفاء عرب بود (<span class=\"hlight\" dir=\"rtl\">٣٨</span> قبل از هجرت - <span class=\"hlight\" dir=\"rtl\">٣٢</span> هَ . ق .). (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٧</span>) (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٨</span>).<br /></font></div>'),
(177276, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (ع اِ) آب مکدر باقی مانده ٔ در حوض . (منتهی الارب ).آب تیره و دُرد که در حوض بماند. (منتخب اللغات ).<br /></font></div>'),
(177277, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طِف ْ ی َ ]</font></b> (ع اِ) نوزاده . <BR><font color=\"Blue\">◄</font> (اِخ ) نام مردی است . (منتهی الارب ).<br /></font></div>'),
(177278, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (ع اِ مصغر) مصغر طِفل . رجوع به طِفل شود.<br /></font></div>'),
(177279, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (از ع، ص، اِ) شاید مخفف طفیلی باشد. رجوع به طفیلی شود که نام شخصی است از بنی امیه که در حالت عسرت و تنگدستی به شادیهای مردم بی طلب رفتی و او را طفیل العرایس گفتندی . فارسیان این لفظرا به دو معنی استعمال کنند، یکی مهمان ناخوانده و دوم همراه کسی رفتن بی طلب و ضیافت و بدین معنی به صله ٔ «با» و «از» هر دو استعمال کنند... و گاهی بمعنی مولدین یاء در آخر زائد کرده طفیلی گویند و گاهی لفظ طفیل در محاوره ٔ فارسیان مجازاً، بمعنی وسیله و ذریعه آید و گاهی یاء طفیلی مصدری باشد بمعنی طفیل شدن . (آنندراج ) <span class=\"hlight\">:</span> <br />دیده ام خلوت سرای دوست در مهمان سرا<br />تن طفیل و شاهد دل میهمان آورده ام .<br /> <font color=\"Red\">خاقانی .</font><br />کعبه ٔ سنگین مثال کعبه ٔ جان کرده اند<br />خاصگان این را طفیل دیدن آن دیده اند.<br /> <font color=\"Red\">خاقانی .</font><br />سرخیل توئی و جمله خیلند<br />مقصود توئی همه طفیلند.<br /> <font color=\"Red\">نظامی .</font><br />خود جهان آن یک کس است و باقیان <br />جمله اتباع وطفیلند ای فلان .<br /> <font color=\"Red\">مولوی .</font><br />که باشند مشتی گدایان خیل <br />به مهمان دارالسلامت طفیل .<br /> <font color=\"Red\">سعدی .</font><br />طفیل هستی عشقند آدمی و پری <br />ارادتی بنما تا سعادتی ببری .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(177280, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) طفیل و شامة دو کوهند به ده فرسنگی مکه . عرام گوید طفیل کوهک بسیار سیاهی است در میان پشته ای از ریگ متصل به هرشی . اصمعی در کتاب الجزیرة و رخمة گوید: آبی است خاصة مر بنی دئل را در کوهکی بنام طفیل و شامة کوهک دیگری است نزدیک آن . (از معجم البلدان ).<br /></font></div>'),
(177281, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (اِخ ) رودباری است میان تهامة و یمن . (معجم البلدان ).<br /></font></div>'),
(177282, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (اِخ ) قلعتی است به وادی موسی نزدیک بیت المقدس . (معجم البلدان ).<br /></font></div>'),
(177283, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (اِخ ) ابن ابی بن کعب انصاری . صحابی است .<br /></font></div>'),
(177284, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (اِخ ) ابن زلال کوفی . از اولاد عبداﷲبن غطفان بن سعد است و او را طفیل الاعراس و طفیل العرائس خواندندی بدانجهت که در طعام ولیمه ناخوانده آمدی . طفیلی ناخوانده به مهمانی آینده منسوب به وی است . نسب ذلک الفعل الی اول من فعله . (منتهی الارب ). رجوع به طفیلی و طفیل العرائس شود.<br /></font></div>'),
(177285, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (اِخ ) ابن عامربن واثلة الکنانی . یکی از شجعان و از سرشناسان قوم خود بود. وی با پدر خویش و ابن الاشعث در شورش بر حجاج دست داشت و در واقعه ٔ یوم الزاویة کشته شد (<span class=\"hlight\" dir=\"rtl\">٨٢</span> هَ . ق .) و پدر وی او را به قصیدتی رثاء گفت که مطلعش این است <span class=\"hlight\">:</span> <br />خلی طفیل علی الهم فانشعبا.<br /><font color=\"Red\">(الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٨</span>).</font><br /></font></div>'),
(177286, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (اِخ ) ابن عمروبن طریف بن العاص الدوسی الازدی، ملقب به ذوالنور. صحابی و از اشرف عرب به جاهلیت و اسلام و مردی شاعر و غنی و مهماندار و مطاع قوم بود و به یمامة کشته شد (<span class=\"hlight\" dir=\"rtl\">١١</span> هَ . ق .). (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٨</span>) (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٦</span>) (منتهی الارب ).<br /></font></div>'),
(177287, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (اِخ ) ابن عوف غنوی، ملقب به مجبر. از شعرای جاهلیت . اصمعی گوید: وی دروصف خیل قوی باشد. مرزبانی در الموشح گوید: خبر دادما را محمدبن الحسن بن درید و گفت آگاه ساخت ما را ابوحاتم و گفت حدیث کرد مرا اصمعی و گفت : طفیل الغنوی در برخی از اشعار اشعر از امروءالقیس است . و نیز گوید اصمعی گفت نابغه و زهیر و اوس نیکو وصف خیل نکردندی . طفیل غنوی لغت به نهایت رسانیده است و نیز مرزبانی گوید: خبر داد ما را ابن درید و گفت ابوحاتم ما را آگاه گردانید و گفت حدیث کرد مرا اصمعی و گفت : طفیل غنوی از زهیر به شعراء اولین اشبه بود. او راست :<br />ظعائن ابرقن الخریف وشمنه <br />و خفن الهمام ان تقاد قنابله .<br />و همو راست :<br />هجان البیاض اشربت لون صفرة<br />(عقیلة جوّ عازب لم یحلل ).<br />ان النساء متی یُنهین عن خُلق <br />فانّه واقعٌ لابُدّ مفعول .<br />قال طفیل یذکر الموت :<br />مضوا سلفاً قصدالسبیل علیهم <br />و صرف المنایا بالرجال تقلب .<br />و نیز او راست :<br />ان ّ النساء کاشجار نبتن معاً<br />منهاالمرار و بعض المرّ مأکول .<br />(الموشح ص <span class=\"hlight\" dir=\"rtl\">٣٤</span>، <span class=\"hlight\" dir=\"rtl\">٤١</span>، <span class=\"hlight\" dir=\"rtl\">٤٧</span>، <span class=\"hlight\" dir=\"rtl\">١٩٦</span>) (الجواهر ص <span class=\"hlight\" dir=\"rtl\">١١٨</span>) (عقدالفریدج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٠</span>) (عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٧</span> و ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>).<br /></font></div>'),
(177288, 'طفیل', '<span class=\"hlight\">طفیل .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (اِخ ) ابن مالک بن جعفربن کلاب بن ربیعةبن عامربن صعصعة. فارس قُرزُل . از مردان عرب و اسیرکننده ٔ معبدبن زرارة سید مضر در یوم رحرحان . او راست :<br />قضینا الحزن من عَبس و کانت <br />مَنیةُ مَعبد فینا هُزالا.<br />رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٨</span>، <span class=\"hlight\" dir=\"rtl\">٩</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٣</span> شود.<br /></font></div>'),
(177289, 'طفیل الخیل', '<span class=\"hlight\">طفیل الخیل .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ لُل ْ خ َ ]</font></b> (اِخ ) پدر بطنی از اعصر. رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> شود.<br /></font></div>'),
(177290, 'طفیل الکنانی', '<span class=\"hlight\">طفیل الکنانی .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ لُل ْ ک َ ]</font></b> (اِخ ) از شعرای محدثین است .<br /></font></div>'),
(177291, 'طفیل بجادی', '<span class=\"hlight\">طفیل بجادی .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ل ِ ب ِ ]</font></b> (اِخ ) شاعری است .<br /></font></div>'),
(177292, 'طفیلی', '<span class=\"hlight\">طفیلی .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (اِخ ) اصلش از ملوکان جهانشاه پادشاه است . اوقات به بنائی میگذرانید. این بیت از اوست :<br />در باغ نوشکفته نه آن غنچه ٔ گل است <br />بر چوب کرده گل سر خونین بلبل است .<br /><font color=\"Red\">(تحفه ٔسامی ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span>).</font><br /></font></div>'),
(177293, 'طفیلی', '<span class=\"hlight\">طفیلی .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ <span class=\"hlight\" dir=\"rtl\">/</span>ف ِ ]</font></b> (ص نسبی، اِ) مهمان ناخوانده . (دهار). ناخوانده ای که به همراه به مهمان خوانده درآید. آنکه بی دعوت همراه میهمانان درآید. آنکه ناخوانده به مهمانی رود. (منتخب اللغات ). منسوب به طفیل الاعراس یا طفیل العرائس یعنی طفیل بن زلال کوفی که به مهمانیها ناخوانده رفتی . انگل . سورچران . ضیفن . (دهار) (منتخب اللغات ). کاسه لیس . شولقی . قرواش . ابوصفر. مفت خوار <span class=\"hlight\">:</span> <br />بانوی شرق و غرب که چون خوان نهد به بزم <br />عنقا مگس مثال طفیلی ّ خوان اوست .<br /> <font color=\"Red\">خاقانی .</font><br />ما زله خوار مائده ٔ میر حاجبیم <br />نعمان روزگار طفیلی خوان ماست .<br /> <font color=\"Red\">خاقانی .</font><br />کریمان دوست تر دارند مهمان طفیلی را.<br /> <font color=\"Red\">صائب .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفیلی شراب </span> ؛ واغِل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طفیلی طعام </span> ؛ وارِش .<br /></font></div>'),
(177294, 'طفیلی ابدال', '<span class=\"hlight\">طفیلی ابدال .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ اَ ]</font></b> (اِخ ) از اتراک خراسان است . اول در کسوت ابدالان میگشت و الحال در خدمت یکی از امرا میباشد. این قطعه ٔ ترکی از اوست :<br />میر طفیلی که نمک وقتنه <br />سک لرنگ رستم دستانی در<br />هیأت رستمنه بنکر و لیک <br />بنعنه باخمه که خراسانی در.<br /><font color=\"Red\">(تحفه ٔ سامی ص <span class=\"hlight\" dir=\"rtl\">١٨٦</span>).</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177295, 'طفیلی قفیلی', '<span class=\"hlight\">طفیلی قفیلی .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ق ُ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (ص مرکب، از اتباع ) از اتباع است . قفیلی را همراه ناخوانده ٔ طفیلی تعبیر می کنند. رجوع به طفیلی شود.<br /></font></div>'),
(177296, 'طفیلی کردن', '<span class=\"hlight\">طفیلی کردن .</span> <font color=\"DarkGreen\"><b>[ طُ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ک َ دَ ]</font></b> (مص مرکب ) کلاشی . بر سر خوان کسی ناخوانده رفتن . تطفیل . (تاج المصادر) (دهار).<br /></font></div>'),
(177297, 'طق', '<span class=\"hlight\">طق .</span> <font color=\"DarkGreen\"><b>[طَ ]</font></b> (ع اِ صوت ) حکایت آواز سنگریزه . (منتهی الارب ).آواز سنگ . (منتخب اللغات ). اسم صوت، آواز خوردن چیزسخت بر چیز دیگر. آواز با هم زدن دو چیز. (غیاث ).<br /></font></div>'),
(177298, 'طق', '<span class=\"hlight\">طق .</span> <font color=\"DarkGreen\"><b>[ طَق ق ]</font></b> (ع اِ) مرگ بسیار سخت . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(177299, 'طق', '<span class=\"hlight\">طق .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ صوت ) آواز جَستن غوک در آب از کرانه ٔ نهر. (اقرب الموارد) (منتهی الارب ). آواز وزغ که بر کنار جوی کند. (منتخب اللغات ).<br /></font></div>'),
(177300, 'طقس', '<span class=\"hlight\">طقس .</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (معرب، اِ) طریقه، و بر طریقه ٔ دینی غلبه یافته است . (از اقرب الموارد). و رجوع به دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span> شود.<br /></font></div>'),
(177301, 'طقسوس', '<span class=\"hlight\">طقسوس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) سمیلقس . (مفردات ابن البیطار).<br /></font></div>'),
(177302, 'طقسیقون', '<span class=\"hlight\">طقسیقون .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (معرب، اِ) ابن البیطار در ضمن شرح «ابن عرس » از دیسقوریدوس آرد: و ابن عرس پازهر کشنده ای است که آن را طقسیقون گویند. گمان میکنم این کلمه همان طخشیقون و طفشیقون لغت نامه ها باشد و اصل آن تخیقون یا تکزیکن یونانی بمعنی مطلق زهر است . واﷲ اعلم .<br /></font></div>'),
(177303, 'طقطق', '<span class=\"hlight\">طقطق .</span> <font color=\"DarkGreen\"><b>[ طِ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ طَ ]</font></b> (اِ صوت ) آواز با هم زدن دو چیزسخت . (غیاث ). آوازی شبیه به صورت طقطق <span class=\"hlight\">:</span> <br />بر سر تختی شنید آن نیک نام <br />طقطقی و های و هوئی شب ز بام .<br /> <font color=\"Red\">مولوی .</font><br />صدا و آواز هر چیز باشد عموماً و صدای دندان بر هم خوردن را گویند خصوصاً. (برهان ). به فتح اول و ثالث به وزن و معنی تک تک به فوقانی بمعنی آواز پا و درقوسی آواز بر یکدیگر خوردن دندان و جز آن . (آنندراج ) <span class=\"hlight\">:</span> <br />استخوانها ز لرزه بر تن من <br />همه طقطق کنان چو دندان است .<br /> <font color=\"Red\">کمال اسماعیل .</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) نوعی از نان . میرزا طاهر وحید در تعریف خباز گوید <span class=\"hlight\">:</span> <br />رخش کرد در دلبری چون شتاب <br />دل از طقطق پای او گشت آب (؟!).<br />و در تعریف کاغذگر گوید:<br />چو طقطق بود کاغذ نان او<br />بر این نان جهانی است مهمان او.<br /><font color=\"Red\">(از آنندراج ).</font><br /></font></div>'),
(177304, 'طقطقی', '<span class=\"hlight\">طقطقی .</span> <font color=\"DarkGreen\"><b>[ طِ طَ ]</font></b> (اِخ ) محمدبن علی .<br /></font></div>'),
(177305, 'طقفة', '<span class=\"hlight\">طقفة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (اِخ ) ابن قیس غفاری . صحابی است . یا صواب طخفة به خاء معجمه، یا طغفة به غین معجمه، یا قیس بن طخفة، یا یعیش بن طخفة، یا عبداﷲبن طغفة، یا طخفةبن ابی ذر است . (منتهی الارب ).<br /></font></div>'),
(177306, 'طقو', '<span class=\"hlight\">طقو.</span> <font color=\"DarkGreen\"><b>[ طَق ْوْ ]</font></b> (ع مص ) شتافتن . شتابروی . (منتهی الارب ).<br /></font></div>'),
(177307, 'طل', '<span class=\"hlight\">طل .</span> <font color=\"DarkGreen\"><b>[ طَل ل ]</font></b> (اِخ ) دیهی است از دیههای غزه به فلسطین . (معجم البلدان ).<br /></font></div>'),
(177308, 'طل', '<span class=\"hlight\">طل .</span> <font color=\"DarkGreen\"><b>[ طِل ل ]</font></b> (ع اِ) حیه . (منتخب اللغات ). مار. (منتهی الارب ) (فهرست مخزن الادویه ).<br /></font></div>'),
(177309, 'طل', '<span class=\"hlight\">طل .</span> <font color=\"DarkGreen\"><b>[ طَل ل ]</font></b> (ع مص ) دیرداشت وام . امروز و فردا کردن غریم خود را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کمی شیر ناقة. (منتهی الارب ). کم شدن شیر ناقه . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> سخت راندن شتران را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> تر شدن زمین از شبنم . تر کردن شبنم زمین را. (منتخب اللغات ). باران رسیده شدن زمین . <BR><font color=\"Blue\">◄</font> رایگان شدن خون مقتول یا خون قصاص ناگرفته . (منتهی الارب ). قصاص ناگرفتن خون را. (منتهی الارب ). باطل شدن خون . (تاج المصادر). باطل و هدر کردن خون . (منتخب اللغات ). باطل کردن خون . (تاج المصادر). <BR><font color=\"Blue\">◄</font> کم کردن حق کسی را و ناچیز گردانیدن . <BR><font color=\"Blue\">◄</font> اندودن . <BR><font color=\"Blue\">◄</font> بازداشتن کسی را. (منتهی الارب ).<br /></font></div>'),
(177310, 'طل', '<span class=\"hlight\">طل .</span> <font color=\"DarkGreen\"><b>[ طَل ل ]</font></b> (ع اِ) باران ریزه . (منتهی الارب )(منتخب اللغات ). سبکترین و ضعیفترین باران . نم . (منتهی الارب ). شب نم . (منتخب اللغات ). فوق نم و کم از باران . (منتهی الارب ). مطر ضعیف . باران ضعیف . (منتخب اللغات ). باران نرم . (مهذب الاسماء). نرم باران . باران خردقطره . اسم عربی شبنم است که به هندی اؤس گویند وآن رطوبتی است که از آسمان شبها خصوص آخر شب فرودآید و بر زمین و اشجار و غیره نشیند. (فهرست مخزن الادویه ). تری . (منتخب اللغات ). ج، طلال، طلل <span class=\"hlight\">:</span> <br />روی سخا و فضل و سخندانی و شرف <br />دایم ز تست تازه چووَرد طری ز طل .<br /> <font color=\"Red\">سوزنی .</font><br />چون روغن طلق است طل، بحردمان زیبق عمل <br />خورشید در تصعید و حل، آتش در اعضا داشته .<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> آنچه بر درخت و گیاه نشیند مانند شیرخشت و بیدخشت و ترنجبین . مَن ّ. خشت <span class=\"hlight\">:</span> شیرخشت ؛ هو طل ّ یقع من السماء ببلاد العجم علی شجرالخلاف . (ابن البیطار). <BR><font color=\"Blue\">◄</font> چیز نیکو وخوش و خوش نما و معجب از شب و مو و آب و جز آن . (منتهی الارب ). چیزی خوب و شگفت آرنده از شب و آب و شعر و غیر آن . <BR><font color=\"Blue\">◄</font> شیر. (منتهی الارب ). شیر درنده . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> مرد سالخورده . (منتهی الارب ). مرد کلان سال . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> حیه . (منتخب اللغات ). مار.(منتهی الارب ).<br /></font></div>'),
(177311, 'طل', '<span class=\"hlight\">طل .</span> <font color=\"DarkGreen\"><b>[ طُل ل ]</font></b> (ع اِ) گردن . <BR><font color=\"Blue\">◄</font> یک خوردنی از شیر. (منتهی الارب ). ج، طلل . <BR><font color=\"Blue\">◄</font> شیر. (منتخب اللغات ). شیر. و منه یقال : ما بالناقة طل ؛ ای ما بها لبن ٌ. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> کمی شیر ناقه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خون . (منتهی الارب )(منتخب اللغات ). <BR><font color=\"Blue\">◄</font> پیه . (منتهی الارب ).<br /></font></div>'),
(177312, 'طل گرفتن', '<span class=\"hlight\">طل گرفتن .</span> <font color=\"DarkGreen\"><b>[ طُ گ ِ رِ ت َ ]</font></b> (مص مرکب ) این کلمه از طلاطله ٔ عربی آید که بمعنی لهات یا سقوط لهات است و امروز سد کردن دانه یا خرده ای از طعام است قسمت زیرین سوراخ کودک را.<br /></font></div>'),
(177313, 'طل گیر', '<span class=\"hlight\">طل گیر.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (نف مرکب ) زنی که علاج کودک طُل گرفته کند.<br /></font></div>'),
(177314, 'طلا', '<span class=\"hlight\">طلا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) قلعتی است به آذربایجان (این لفظ عجمی و اصل آن تلاست، چه در کلام عجم طاء و ظاء و ضاد و ثاء و حاء و صاد خالصه و جیم خالصه نیست ). (معجم البلدان ).<br /></font></div>'),
(177315, 'طلا', '<span class=\"hlight\">طلا.</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (از ع، اِ) زر (در اصطلاح فارسی ). زر سرخ . بکسر اول معروف است که به عربی ذهب خوانند. (برهان ). زر خالص و صاحب فرهنگ رشیدی نوشته که غالباً لفظ طلا معرب تله است که لفظ هندی است و بکسر فوقانی و تشدید لام بمعنی زر و بمعنی ملمع کردن و ملمع نیز آمده است و در سراج نوشته که طلا بمعنی زر سرخ در اصل به تای قرشت بود بسبب اختلاط عجم و عرب به طای مطبقه نوشته اند حتی که مطلا بمعنی زراندود استعمال کنند. (غیاث ) (آنندراج ). رجوع به زر طلا شود <span class=\"hlight\">:</span> <br />زمین را برنگ طلا رنگ داد <font color=\"DarkGreen\"><b>[ مهر ]</font></b><br />جهان را ز نو فر واورنگ داد.<br /> <font color=\"Red\">فردوسی .</font><br />وجود مردم دانا بسان زرّ طلاست <br />که هر کجا که رَوَد قدر و قیمتش دانند.<br /> <font color=\"Red\">سعدی .</font><br />از پی دیدن نهی گر به دم تیغ دست <br />زخم فشاند چو مهر در عوض خون طلا.<br /> <font color=\"Red\">حسین ثنائی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلای جعفری </span> . رجوع به زر جعفری شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلای دست افشار</span> . رجوع به زر دست افشار شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلای سفید</span> ؛ پلاتین . نوعی اززر که سفیدرنگ و گرانبهاتر از طلای زرد است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">طلا که پاک است چه محنتش (یا حاجتش، یا منتش ) به خاک است </span> .<br /></font></div>'),
(177316, 'طلا', '<span class=\"hlight\">طلا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) کوهکی است (چنین یافتم در شعر هذلیین و در شعر دیگران به ظاءمعجمه و آنجا واقعه ای بوده است ). (معجم البلدان ).<br /></font></div>'),
(177317, 'طلا', '<span class=\"hlight\">طلا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) آب دهان که از جهت بیماری و جز آن بسته باشد. طُلْوان . طُلُوان . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> به قطران اندوده . (منتخب اللغات ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بچه ٔ آهو. (مهذب الاسماء). بچه ٔ آهو وقت زائیدن . (منتهی الارب ). آهوی یکساله . (دهار). آهوبچه . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> بچه ٔ گاو و گوسفند. (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> بچه ٔ هر حیوان که زنگله دارد. (مهذب الاسماء). هر ستور که سم او شکافته باشد. (منتخب اللغات ). گوساله . <BR><font color=\"Blue\">◄</font> ریزه و خرد از هر چیزی . (منتهی الارب ). ج، اَطْلاء، طِلاء، طُلْیان، طِلْیان . <BR><font color=\"Blue\">◄</font> شخص . رجوع به طلی شود.<br /></font></div>'),
(177318, 'طلا کردن', '<span class=\"hlight\">طلا کردن .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ک َ دَ ]</font></b> (مص مرکب ) به اصطلاح اطبا آنچه بر اندام مالند رقیق آن را طلا و غلیظ آن را ضماد گویند و شعرا مطلق بر مالیدن و اندودن اطلاق کنند <span class=\"hlight\">:</span> <br />نارنج چو دو کفه ٔ سیمین ترازو<br />هر دو ز زر سرخ طلا کرده برونسو.<br /> <font color=\"Red\">منوچهری .</font><br />صداع اجل را دوا کرده اند<br />که بر حیه زین می طلا کرده اند.<br /> <font color=\"Red\">نورالدین ظهوری .</font><br />تفاخر به زرین قبا میکنی <br />طلائی بر آهن طلا میکنی .<br /> <font color=\"Red\">سعید اشرف (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلا کردن به بول </span> ؛ تعنیة. (تاج المصادر بیهقی ).<br /></font></div>'),
(177319, 'طلاء', '<span class=\"hlight\">طلاء.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ج ِ طلا. (منتهی الارب ).<br /></font></div>'),
(177320, 'طلاب', '<span class=\"hlight\">طلاب .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع مص ) مطالبه . خواستن حق خود را از کسی . بازجست کردن . (منتهی الارب ). درخواستن چیزی .<br /></font></div>'),
(177321, 'طلاب', '<span class=\"hlight\">طلاب .</span> <font color=\"DarkGreen\"><b>[ طُل ْ لا ]</font></b> (ع ص، اِ) ج ِ طالب . (منتهی الارب ).<br /></font></div>'),
(177322, 'طلاب', '<span class=\"hlight\">طلاب .</span> <font color=\"DarkGreen\"><b>[ طَل ْ لا ]</font></b> (ع ص ) بسیار جوینده . بسیار خواهنده . ج، طلابون . <BR><font color=\"Blue\">◄</font> (اِخ ) نام مردی است . (منتهی الارب ).<br /></font></div>'),
(177323, 'طلاباف', '<span class=\"hlight\">طلاباف .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (ن مف مرکب ) طلابافته . زربفت <span class=\"hlight\">:</span> <br />لباس صورت اگر واژگون کنم بیند<br />که خرقه ٔ خشنم جامه ٔ طلاباف است .<br /><font color=\"Red\">عرفی (از آنندراج ).</font><br /></font></div>'),
(177324, 'طلابخت', '<span class=\"hlight\">طلابخت .</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) نام یکی از دیههای استرابادرستاق . (سفرنامه ٔ مازندران و استرآباد رابینو ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span>).<br /></font></div>'),
(177325, 'طلابر', '<span class=\"hlight\">طلابر.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) دهی جزء دهستان رحمت آباد بخش رودبار شهرستان رشت . در <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی شمال خاوری رودبار و خاور سفیدرود. کوهستانی و معتدل و مالاریائی با <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه . آب آن از چشمه و محصول آنجا غلات و لبنیات و زیتون . شغل اهالی زراعت و گله داری و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(177326, 'طلابن', '<span class=\"hlight\">طلابن .</span> <font color=\"DarkGreen\"><b>[ طَ ب ُ ]</font></b> (اِخ ) نام یکی از دیههای تنکابن . (سفرنامه ٔ مازندران و استرآباد رابینو ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span>).<br /></font></div>'),
(177327, 'طلابون', '<span class=\"hlight\">طلابون .</span> <font color=\"DarkGreen\"><b>[ طَل ْ لا ]</font></b> (ع ص، اِ) ج ِ طَلاّب . (منتهی الارب ). رجوع به طلاب شود.<br /></font></div>'),
(177328, 'طلاح', '<span class=\"hlight\">طلاح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِمص ) فساد و تباهی . خلاف صلاح . (منتهی الارب ). ضد الصلاح . (تاج المصادر). <BR><font color=\"Blue\">◄</font> بد شدن . (زوزنی ).<br /></font></div>'),
(177329, 'طلاح', '<span class=\"hlight\">طلاح .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ج ِ طلح . (منتهی الارب ).<br /></font></div>'),
(177330, 'طلاح', '<span class=\"hlight\">طلاح .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) طلح است و نوعی از ام غیلان است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177331, 'طلاحة', '<span class=\"hlight\">طلاحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (ع مص ) مانده شدن . (تاج المصادر). مانده گردیدن . (منتهی الارب ).<br /></font></div>'),
(177332, 'طلاحی', '<span class=\"hlight\">طلاحی .</span> <font color=\"DarkGreen\"><b>[ طَ حا ]</font></b> (ع ص، اِ) ابل طلاحی ؛ شتران به درد شکم مبتلا شده از خوردن درخت طلح . (منتهی الارب ).<br /></font></div>'),
(177333, 'طلاحیة', '<span class=\"hlight\">طلاحیة.</span> <font color=\"DarkGreen\"><b>[ طُ حی ی َ <span class=\"hlight\" dir=\"rtl\">/</span> طِ حی ی َ ]</font></b> (ع ص، اِ) ابل طلاحیة؛ شتران طلح خوار. (منتهی الارب ).<br /></font></div>'),
(177334, 'طلادوز', '<span class=\"hlight\">طلادوز.</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (ن مف مرکب ) دوخته شده با طلا. چیزی که به تارهای طلا دوخته باشند. بابافغانی راست <span class=\"hlight\">:</span> <br />از رنگ دگر سوخت دل از دور چو دیدت <br />نقش کمر و تاج طلادوز ندانست .<br /> <font color=\"Red\">(از آنندراج ).</font><br />آنکه دستار طلادوز علم گردانید<br />کرد چون ریشه پریشان من سرگردان را.<br /> <font color=\"Red\">نظام قاری (دیوان البسه ص <span class=\"hlight\" dir=\"rtl\">٩٨</span>).</font><br /><BR><font color=\"Blue\">◄</font> (نف مرکب ) دوزنده با تارهای طلا.<br /></font></div>'),
(177335, 'طلادوزی', '<span class=\"hlight\">طلادوزی .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (حامص مرکب ) عمل طلادوز. به تارهای طلا چیزی را دوختن . <BR><font color=\"Blue\">◄</font> (ص نسبی ) زربفت . دوخته شده با تارهای طلا <span class=\"hlight\">:</span> <br />ز یمن کلفتن و بیرم طلادوزی <br />علم شدیم و سرآمد به شیوه ٔ اشعار.<br /> <font color=\"Red\">نظام قاری (دیوان البسه ص <span class=\"hlight\" dir=\"rtl\">٨١</span>).</font><br />به دستار طلادوزی و بیرمهای سلطانی <br />که ماه شمسی ای قاری چو کتان میبرد تابم .<br /><font color=\"Red\">نظام قاری (دیوان البسه ص <span class=\"hlight\" dir=\"rtl\">٩٨</span>).</font><br /></font></div>'),
(177336, 'طلاساز', '<span class=\"hlight\">طلاساز.</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (نف مرکب ) طلاکار. <BR><font color=\"Blue\">◄</font> کیمیاگر <span class=\"hlight\">:</span> <br />شود شمشه ٔ زر از این باده خس <br />طلاساز را دردش اکسیر بس .<br /><font color=\"Red\">ملاطغرا (از آنندراج ).</font><br /></font></div>'),
(177337, 'طلاسة', '<span class=\"hlight\">طلاسة.</span> <font color=\"DarkGreen\"><b>[ طَل ْ لا س َ ]</font></b> (ع اِ) لته ٔ پاک کردن لوح . (منتهی الارب ). تخته پاک کن . کهنه . رُکو که بدان لوح پاک کنند. کهنه که با آن نوشته ٔ لوح را سترند. هرچه بدان چیزی پاک کنند. (مهذب الاسماء).<br /></font></div>'),
(177338, 'طلاطل', '<span class=\"hlight\">طلاطل .</span> <font color=\"DarkGreen\"><b>[ طُ طِ ]</font></b> (ع اِ) مرگ . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بیماری مهلک که دوا نپذیرد. بیماری سخت . (منتهی الارب ).<br /></font></div>'),
(177339, 'طلاطل', '<span class=\"hlight\">طلاطل .</span> <font color=\"DarkGreen\"><b>[ طَ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طُ طِ ]</font></b> (ع اِ) بیماریی است در پشت خر که قطع کند آن را. طُلاطلة. (منتهی الارب ).<br /></font></div>'),
(177340, 'طلاطلة', '<span class=\"hlight\">طلاطلة.</span> <font color=\"DarkGreen\"><b>[ طُ طِ ل َ ]</font></b> (اِخ ) پدر مالک یکی از مستهزئان نبی صلی اﷲ علیه و سلم . (منتهی الارب ).<br /></font></div>'),
(177341, 'طلاطلة', '<span class=\"hlight\">طلاطلة.</span> <font color=\"DarkGreen\"><b>[ طُ طِ ل َ ]</font></b> (ع اِ) بیماری سخت عاجزکن اطباء. <BR><font color=\"Blue\">◄</font> بلا. گویند: رماه ُ اﷲ بالطلاطة؛ ای الداء العضال . داهیه . (منتهی الارب ) (مهذب الاسماء). طلطلة. طلطل . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گوشتپاره ای است در حلق یا در کرانه ٔ جای فروبردن لقمه و آن فروآمدن کام است که جهت آن طعام و شراب به سهولت فروبرده نشود. <BR><font color=\"Blue\">◄</font> بیماریی است در پشت خر که قطع کند آن را. طلاطل . <BR><font color=\"Blue\">◄</font> مرگ . (منتهی الارب ).<br /></font></div>'),
(177342, 'طلاع', '<span class=\"hlight\">طلاع .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع مص ) واقف گردیدن . <BR><font color=\"Blue\">◄</font> طالَعَ بالحال ؛ ظاهر کرد حال را. (منتهی الارب ).<br /></font></div>'),
(177343, 'طلاع', '<span class=\"hlight\">طلاع .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) طلاع الشی ٔ؛ پُری چیزی . ج، طُلْع. و منه حدیث عمر (رض ): لو ان لی طلاع الارض ذهباً لافتدیت به . (منتهی الارب ). پُری چیزی . (منتخب اللغات ). پُری . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> هرچه بر آن آفتاب تابد. (منتهی الارب ). طلاع الارض ؛ روی زمین که آفتاب بر آن تابد. (مهذب الاسماء).<br /></font></div>'),
(177344, 'طلاع', '<span class=\"hlight\">طلاع .</span> <font color=\"DarkGreen\"><b>[ طَل ْ لا ]</font></b> (ع ص ) رجل طلاع الثنایا و الانجد؛ مرد نیک آزماینده ٔ کارها. (منتهی الارب ) <span class=\"hlight\">:</span> <br />انا ابن جلا و طلاع ُالثنایا<br />متی اضع العمامة تعرفونی .<br /> <font color=\"Red\">(از خطبه ٔ حجاج بن یوسف در مسجد کوفه ).</font><br /><BR><font color=\"Blue\">◄</font> مرد درآینده و تصرف کننده ٔ در کارها. <BR><font color=\"Blue\">◄</font> مرد نیک ماهر و شناسا و تجربه کار و تیزفهم و زیرک . (منتهی الارب ). آنکه کارها آزموده باشد. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آنکه پیوسته همت او مایل به معالی امور باشد. (منتهی الارب ). آنکه قصد کارهای بزرگ کند. (مهذب الاسماء). آنکه اراده ٔ کارهای بزرگ کند و مرتکب امور عظیم گردد. (منتخب اللغات ).<br /></font></div>'),
(177345, 'طلافح', '<span class=\"hlight\">طلافح .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ ]</font></b> (ع ص، اِ) چیزهای پهن و عریض . کأنّه جمع طلفح . (منتهی الارب ).<br /></font></div>'),
(177346, 'طلافح', '<span class=\"hlight\">طلافح .</span> <font color=\"DarkGreen\"><b>[ طُ ف ِ ]</font></b> (ع ص ) مغز تنک . (منتهی الارب ).<br /></font></div>'),
(177347, 'طلافیون', '<span class=\"hlight\">طلافیون .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (معرب، اِ) (ازیونانی تله فی ین ) خرفه ٔ دشتی . بقلةالحمقاء بریة .<br /></font></div>'),
(177348, 'طلاق', '<span class=\"hlight\">طلاق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) رها شدن زن از قید نکاح . (منتهی الارب ) (منتخب اللغات ). رها شدن زن از عقد نکاح . (المصادر زوزنی ). رها کردن . (دهار). فسخ کردن عقد نکاح . سراح . (منتهی الارب ). بیزاری <span class=\"hlight\">:</span> هر زنی که در عقد من است یا بعد از این در عقد من خواهد آمد مطلقه است و طلاق باین که رجعت در او نگنجد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣١٨</span>).<br />لیک با ام الخبائث چون طلاقش واقع است <br />خسروش رجعت نفرماید به فتوای جفا.<br /> <font color=\"Red\">خاقانی .</font><br />صاحب آنندراج گوید: طلاق رها شدن زن از قید نکاح ... و به فارسی با لفظ افتادن و دادن و خوردن و گرفتن و بستن مستعمل <span class=\"hlight\">:</span> <br />از سر مستی دگر با شاهد عهد شباب <br />رجعتی می خواستم لیکن طلاق افتاده بود.<br /> <font color=\"Red\">حافظ.</font><br />پارسایان عهد با قدسی وشاقی بسته اند<br />دهر را بر گوشه ٔ چادر طلاقی بسته اند.<br /> <font color=\"Red\">سنجر کاشی .</font><br />دی طلاق رستگاری خورده ام <br />با بلا سوگند یاری خورده ام .<br /> <font color=\"Red\">سنجر کاشی .</font><br />صاحب قاموس کتاب مقدس آرد: طلاق در شریعت موسوی معمول و مجاز است لذا زوجات خود را به ادنی سبب و اقل جهتی طلاق میدادند تا اینکه مسیح آنها را ملامت و توبیخ نموده اذن طلاق را معلق به علت زنا فرمود. (قاموس کتاب مقدس ). طلاق در حقوق ساسانی یک امر استثنائی و امر غیرعادی بوده است . در دینکرد آمده است : اگر شوهری از روی سؤنیت بکوشد رابطه ٔ زناشوئی را قطع کند از او به محکمه شکایت خواهد شد و اگر بر طبق حکم صادره از دادگاه شوهر مجدداً وصلت را ادامه دهد دیگر به هیچ عنوان تنبیه نخواهد شد و به زندان نخواهد رفت . از این گفته چنین معلوم میگردد که طلاق امری استثنائی بوده و جز به حکم دادگاه ممکن نبوده است . البته دادگاه نیز حتی الامکان از طلاق احتراز میکرده است . و در فقه اسلام چنانکه علامه در تبصره آورده است در طلاق دهنده بلوغ و عقل و اختیار و قصد شرط میباشد و از برای ولی است طلاق دادن از طرف شوهر مجنون نه شوهر صغیر و شوهر مست و در طلاق داده شده خالی بودن از حیض و نفاس در صورتی که شوهر حاضرباشد و دخول به آن زن نموده باشد شرط میباشد و اگر شوهر غایب (مسافر) باشد به اندازه ٔ انتقال «گردیدن » زن از طهری (پاکی از حیض ) به طهر دیگری طلاق آن زن صحیح میباشد و اگرچه حائض بوده باشد و شرط میباشد طلاق دادن آن زن را در طهری که در آن به جماع نزدیکی با آن زن نکرده باشد مگر در زن صغیره و زن یائسه و مسترابه (زنی که حامله بودن او مورد شک و ریب واقع شده است ) سه ماه صبر میکند و طلاق جز به گفتن شوهر «انت طالق » واقع نمیشود، در حالی که این قول از شرط و صفت مجرد باشد و شنیدن (صیغه ٔ طلاق را) دو تن مرد عادل شرط است . رجوع به ترجمه و شرح تبصره ٔ علامه صص <span class=\"hlight\" dir=\"rtl\">٢٨٧</span> - <span class=\"hlight\" dir=\"rtl\">٢٩٣</span> و کشاف اصطلاحات الفنون و شرایع و سایر کتب فقهی شود. <BR><font color=\"Blue\">◄</font> (اِمص ) بضع. <BR><font color=\"Blue\">◄</font> گشاده زبانی .تیزی زبان . طلاقت . تیززبان شدن . <BR><font color=\"Blue\">◄</font> گشاده رویی . گشادگی . (غیاث ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلاق طبیعت </span> ؛ گشادگی طبیعت . (آنندراج ).<br /><BR><font color=\"Blue\">◄</font> روانی . آزادگی . <BR><font color=\"Blue\">◄</font> نشاط. (غیاث ).<br /></font></div>'),
(177349, 'طلاق', '<span class=\"hlight\">طلاق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) سوره ٔ شصت وپنجمین از قرآن کریم، و آن مدنیه و دوازده آیت است، پس از تغابن و پیش از تحریم .<br /></font></div>'),
(177350, 'طلاق بدعت', '<span class=\"hlight\">طلاق بدعت .</span> <font color=\"DarkGreen\"><b>[ طَ ق ِ ب ِ ع َ ]</font></b>(ترکیب اضافی، اِ مرکب ) طلاق حائض غیرآبستن یا نفساءاست با حضور زوج یا مسترابه بیش از سه ماه و سه طلاق مرسلاً (پشت سر هم ) بطوری که در شرط سوم از شرایط صیغه ٔ طلاق مذکور است . (از ترجمه ٔ تبصره ٔ علامه ص <span class=\"hlight\" dir=\"rtl\">٢٩٢</span>).<br /></font></div>'),
(177351, 'طلاق خلع', '<span class=\"hlight\">طلاق خلع.</span> <font color=\"DarkGreen\"><b>[ طَ ق ِ خ َ ]</font></b> (ترکیب اضافی، اِ مرکب ) نوعی طلاق و آن قطع علاقه ٔ زوجیت از طرف زوج است بر اثر بذل زوجه مالی را به او.رجوع به خلع شود. از یک قسمت از مادیکان هزار داستان چنین معلوم میشود که در حقوق ساسانی طلاقی شبیه به طلاق خلع وجود داشته و زن میتوانسته با واگذاری اموال خود به شوهر، خود را از رابطه ٔ زناشوئی آزاد کند. از روایات (چ هند) چنین برمی آید که طلاق در این موارد آزاد و مجاز بوده است : الف - زن مرتکب زنا شود. گویادر این صورت طلاق اجباری بوده است . ب - زن وضع مزاجی خود را از شوهر پنهان کرده باشد. ج - زن جادو کند یا به کسی جادو بیاموزد. د - زن سترون (عقیم ) باشد.<br /></font></div>'),
(177352, 'طلاق دادن', '<span class=\"hlight\">طلاق دادن .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b>(مص مرکب ) رها کردن زن . تسریح . (منتهی الارب ). تطلیق . (تاج المصادر). اِملاک . یقال : اُمْلِکَت امرَها (مجهولاً)؛ یعنی طلاق داده شد. (منتهی الارب ) <span class=\"hlight\">:</span> <br />هرکه مراو را طلاق داد بجویدش <br />دوست ندارد هگرز شوی حلاله .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و هرگاه که متقی در کار این جهان گذرنده تأملی کند هرآینه مقابح آن را به نظر بصیرت بیند... و به قضا رضا دهد تا غم کم خورد و دنیا را طلاق دهد. (کلیله و دمنه ).<br />شب طلاق خواب داده دیده بانان بصیر<br />تا شکرریز عروسان بیابان دیده اند.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(177353, 'طلاق رجعی', '<span class=\"hlight\">طلاق رجعی .</span> <font color=\"DarkGreen\"><b>[ طَ ق ِ رَ ]</font></b> (ترکیب وصفی، اِ مرکب ) طلاقی که بعد آن در میان مدت عدت رجوع کردن به زن بدون نکاح جائز باشد و آن یک بار یا دو بار لفظ طلاق گفتن است، بخلاف طلاق باین که رجوع کردن در آن بدون نکاح جائزنباشد و آن گفتن است زن را «انت بائنة» و آنچه در معنی این باشد و بخلاف طلاق مغلظه که در آن تا زن منکوحه ٔ شخص دیگر شده طلاق نیابد نکاح به آن زن شوهر اول را جایز نباشد و آن سه طلاق دادن است . (غیاث ) (آنندراج ). طلاقی که از برای مطلق رجوع از آن در ایام عدة موجود است . زوجی که زوجه ٔ خود را بعد از نزدیکی با او طلاق میدهد در حالتی که زوجه یائسه و صغیره نیست تا وقتی که ایام عده منتفی نشده است حق دارد از آن طلاق رجوع نموده و بعد از رجوع علاقه ٔ زوجیت عودت مینماید.<br /></font></div>'),
(177354, 'طلاق سنت', '<span class=\"hlight\">طلاق سنت .</span> <font color=\"DarkGreen\"><b>[ طَ ق ِ س ُن ْ ن َ ]</font></b> (ترکیب اضافی، اِ مرکب ) و آن دو نوع است : طلاق سنی بمعنی اعم ؛ طلاقی که بواسطه ٔ رعایت شرایط جایز است . طلاق سنی بمعنی اخص ؛ طلاقی که با رعایت شرایط صادر و زوج از حق رجوع خود در ایام عده استفاده ننماید.علامه گوید: طلاق (سنی ) بائن (برای شوهر حق رجوعی نیست ) و رجعی است (مقابل بائن ). (ترجمه ٔ تبصره ص <span class=\"hlight\" dir=\"rtl\">٢٩٣</span>).<br /></font></div>'),
(177355, 'طلاق سنی', '<span class=\"hlight\">طلاق سنی .</span> <font color=\"DarkGreen\"><b>[ طَ ق ِ س ُن ْنی ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به طلاق سنت شود.<br /></font></div>'),
(177356, 'طلاق نامه', '<span class=\"hlight\">طلاق نامه .</span> <font color=\"DarkGreen\"><b>[ طَ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) کاغذی که در آن وقوع طلاق زنی را نویسند. بیزاری نامه .<br /></font></div>'),
(177357, 'طلاق گرفتن', '<span class=\"hlight\">طلاق گرفتن .</span> <font color=\"DarkGreen\"><b>[ طَ گ ِ رِ ت َ ]</font></b> (مص مرکب ) هشتن شوی . رها شدن زن از قید زوجیت <span class=\"hlight\">:</span> <br />دختر رز که گرفته ست ز خصم تو طلاق <br />باد در عقد مدام تو ز فتوای هوا.<br /><font color=\"Red\">سنجر کاشی (از آنندراج ).</font><br /></font></div>'),
(177358, 'طلاق گفتن', '<span class=\"hlight\">طلاق گفتن .</span> <font color=\"DarkGreen\"><b>[ طَ گ ُ ت َ ]</font></b> (مص مرکب ) طلاق دادن . هشتن زن .<br /></font></div>'),
(177359, 'طلاقت', '<span class=\"hlight\">طلاقت .</span> <font color=\"DarkGreen\"><b>[ طَ ق َ ]</font></b> (ع مص ) گشادگی زبان . (مهذب الاسماء). ذلاقت . گشاده زبانی . فصاحت . گشاده زبان شدن . (زوزنی ) (منتخب اللغات ). تیزی زبان . زبان آوری . طلاق . تیززبان شدن . تیززبانی . لقلقه . (غیاث ) (آنندراج ). <BR><font color=\"Blue\">◄</font> گشاده روی شدن . (تاج المصادر) (منتخب اللغات ) (زوزنی ). گشاده و درخشان روی گردیدن . (منتهی الارب ). گشادگی . (دهار). <BR><font color=\"Blue\">◄</font> به اعتدال شدن روز و شب یعنی نه گرم و نه سرد. (منتهی الارب ). خوش و آرمیده گشتن شب و روز. (المصادر زوزنی ).<br /></font></div>'),
(177360, 'طلال', '<span class=\"hlight\">طلال .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) ذوطِلال ؛ آبی است یا موضعی است به بلاد بنی مُرّة. <BR><font color=\"Blue\">◄</font> اسب ابوسلمان بن ربیعة. (منتهی الارب ).<br /></font></div>'),
(177361, 'طلال', '<span class=\"hlight\">طلال .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ج ِ طَل ّ. (منتهی الارب ).<br /></font></div>'),
(177362, 'طلال', '<span class=\"hlight\">طلال .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) موضعی است در شعر ابوالصخر الهذلی <span class=\"hlight\">:</span> <br />یفیدون القیان مقینات <br />کاطلاءالنعاج بذی طَلال .<br /><font color=\"Red\">(از معجم البلدان ).</font><br /></font></div>'),
(177363, 'طلال الرشید', '<span class=\"hlight\">طلال الرشید.</span> <font color=\"DarkGreen\"><b>[ طَ لُرْ رَ ]</font></b> (اِخ ) طلال بن عبداﷲبن علی الرشید (<span class=\"hlight\" dir=\"rtl\">١٢٣٨</span>-<span class=\"hlight\" dir=\"rtl\">١٢٨٣</span> هَ . ق .). از امراء آل رشید نجد. پدرش وی را در امارت حائل جانشین خویش ساخت و وی بر جوف و خیبر وتیماء و قسمتی از قصیم مستولی شد و از عهده ٔ فرمانروائی نیکو برآمد و راهها ایمن گردانید. به روزگار وی علائق طاعت وی و قوم وی شمر نسبت به آل سعود سستی گرفت . گویند منتحراً درگذشت . (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٩</span>).<br /></font></div>'),
(177364, 'طلالة', '<span class=\"hlight\">طلالة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِمص ) خرمی . شادمانی . <BR><font color=\"Blue\">◄</font> نیکوئی حالت . خوبی هیأت . <BR><font color=\"Blue\">◄</font> (اِ) کالبد هر چیزی . گویند: حَیّا اﷲ طلالتک ؛ ای شخصک . <BR><font color=\"Blue\">◄</font> اثر سرای . جای خراب شده . (منتهی الارب ).<br /></font></div>'),
(177365, 'طلالة', '<span class=\"hlight\">طلالة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع مص ) شگفتی نمودن . <BR><font color=\"Blue\">◄</font> طُلَّت الارض ُ (مجهولاً)؛ باران ریزه بارید بر زمین . (منتهی الارب ).<br /></font></div>'),
(177366, 'طلام', '<span class=\"hlight\">طلام .</span> <font color=\"DarkGreen\"><b>[ طُل ْ لا ]</font></b> (ع اِ) شاهدانه . (منتهی الارب ). اسم شوم است که حب شهدانج باشد. (فهرست مخزن الادویه ).<br /></font></div>'),
(177367, 'طلاکار', '<span class=\"hlight\">طلاکار.</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (ص مرکب ) طلاساز. <BR><font color=\"Blue\">◄</font> چیزی که کار نقش و نگارش از طلا باشد و کرده باشند، چون خانه ٔ طلاکار و شمشیر طلاکار <span class=\"hlight\">:</span> <br />منزل مردان ز نقش عاریت کاری خوش است <br />خانه چون فانوس از مهمان طلاکاری خوش است .<br /><font color=\"Red\">محسن تأثیر (از آنندراج ).</font><br /></font></div>'),
(177368, 'طلاکاری', '<span class=\"hlight\">طلاکاری .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (حامص مرکب ) عمل طلاکار.<br /></font></div>'),
(177369, 'طلاکوب', '<span class=\"hlight\">طلاکوب .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (نف مرکب ) آنکه ورقهای طلا و نقره را بسازد. میرزا طاهر وحید راست :<br />دلم شیوه ٔ یار را پیشه کرد<br />که گشتم طلاکوب این رنگ زرد.<br />ملا طغرا راست <span class=\"hlight\">:</span><br />به کف دارم از پنجه خایسک درد<br />ز بهر طلاکوبی رنگ زرد.<br /><font color=\"Red\">(از آنندراج ).</font><br /></font></div>'),
(177370, 'طلاکوبی', '<span class=\"hlight\">طلاکوبی .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (حامص مرکب ) عمل طلاکوب .<br /></font></div>'),
(177371, 'طلای دوبتی', '<span class=\"hlight\">طلای دوبتی .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ی ِ دُ ب ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) اشرفی که هر دو رو صورت داشته باشد. محمد رفیع واعظ قزوینی راست <span class=\"hlight\">:</span> <br />قبله ٔ طاعت این قوم طلای دوبتی است <br />طاق درهای خسان نائب محراب بود.<br /><font color=\"Red\">(از آنندراج ).</font><br /></font></div>'),
(177372, 'طلای کشته', '<span class=\"hlight\">طلای کشته .</span> <font color=\"DarkGreen\"><b>[ طِ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ی ِ ک ُ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) از عالم سیماب کشته . علی رضای تجلی راست <span class=\"hlight\">:</span> <br />بی توبر من ماهتاب امشب شب دیگر شده ست <br />نور شمعم چون طلای کشته خاکستر شده ست .<br /><font color=\"Red\">(از آنندراج ).</font><br /></font></div>'),
(177373, 'طلایح', '<span class=\"hlight\">طلایح .</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ ]</font></b> (ع ص، اِ) طَلائح . ج ِ طَلیحة. (منتهی الارب ).<br /></font></div>'),
(177374, 'طلایع', '<span class=\"hlight\">طلایع.</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ ]</font></b> (ع اِ) ج ِ طلیعه . (منتهی الارب ). طلائع. بغایا. رجوع به طلیعه و طلایه شود<span class=\"hlight\">:</span> چاشتگاه طلایع مخالفان پدید آمد سواری سیصد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٨٣</span>). هر دو لشکر را که طلیعه بودند مدد رسید تا میان دو نماز لشکر فرودآمد و طلایع بازگشتند. (تاریخ بیهقی ). سلطان طلایع خویش را فرمود تاخود را در میان بیشه ها انداختند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤١٠</span>). از وقت لمعه ٔ فلق تا وقت مسقط شفق با طلایعمرگ به بازی درآمدند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٩٤</span>).<br /></font></div>'),
(177375, 'طلایم', '<span class=\"hlight\">طلایم .</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ ]</font></b> (اِخ ) اسم موضعی است که شاعول عساکر خود را آنجا جمع کرد و ایشان را قبل از هجوم بر بنی عمالیق سان دید. (قاموس کتاب مقدس ).<br /></font></div>'),
(177376, 'طلایه', '<span class=\"hlight\">طلایه .</span> <font color=\"DarkGreen\"><b>[ طَ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (از ع، اِ) جاسوس لشکر که پیش و پس را نگه دارد. گروهی که پیش فرستند تا از دشمن واقف شود. (منتخب اللغات ). پیش قراول . پیشرو لشکر. پیش جنگ . طلیعه . (السامی ). ماثد. (منتهی الارب ). طلایه ٔ جیش ؛ طلیعه ٔ آن . نگاهبان لشکر که به اطراف آن شب بگردند و تفحص لشکر بیگانه کنند. فوجی که به شب حفاظت شهر و لشکر کند و مردم اینجا (هند) که طلاوه گویند خطاست و صاحب بهار عجم در رساله ٔ جواهرالحروف نوشته است طلایه که بمعنی فوج محافظ لشکر است، در اصل طلایع بود جمع طلیعه، مگر فارسیان بمعنی مفرد استعمال کنند چنانکه بجای عجیب عجائب و بجای ملک ملائک ... (غیاث ) . در قوسی، جمعی از لشکر که شبها به کشیک دورادور لشکر برای پاس بگردند... طرایه مثله . کذا فی کشف اللغات و باید دانست که فارسیان چون خواهند که کلمه ٔ غیرفارسی را از جنس کلمات خود گردانند اگر آن کلمه ذات العین است آن عین را به هاء بدل کنند از جهت قرب مخرج چون لهفة و هفهف به وزن و معنی لعبت و عفعف و صیغه ٔ جمع عربی نزد ایشان حکم صیغه ٔ مفرد دارد چون ریاض و عجائب و ملایک و مشایخ و حور و غیر آن و بر این تقدیر طلایه مبدل مفرس طلاعه بود جمع طلیعه و طای مهمله از جهت رسم خطبود از عالم طلا و فوطه و غوطه و طپانچه ... (آنندراج ) <span class=\"hlight\">:</span> مهلب مردی بیدار و کاردان بود و شب و روز یزک و طلایه نگاه داشتی . (ترجمه ٔ طبری بلعمی ). خبربه مدینه آمد که ابوسفیان خود به جنگ آمد و طلایه ٔ او آمدند و دو تن از انصار کشتند و خرابی بسیار کردند. (ترجمه ٔ طبری بلعمی ). پس یک سوار خوشنواز پیش سوفرای آمد و سوفرای تیری بر پیشانی اسب او زد و اسب بیفتاد و بمرد. سوفرای آن مرد را اسیر کرد و او را پرسید که تو کیستی ؟ گفت : من یکی از طلایگان خوشنوازم . (ترجمه ٔ طبری بلعمی ). خوشنواز <font color=\"DarkGreen\"><b>[ پادشاه هیاطله ]</font></b> دانست که با وی <font color=\"DarkGreen\"><b>[ سوفرای سردار ایرانی ]</font></b> تاب ندارد، سپاه خویش را گرد کرد و بر جای همی بود و طلایه بیرون کرد وسوفرای نیز طلایه بیرون کرد. (ترجمه ٔ طبری بلعمی ).<br />طلایه ز یک سو مر او را ندید<br />چنین تا بنزدیک لشکر رسید.<br /> <font color=\"Red\">فردوسی .</font><br />طلایه شب و روز در جنگ بود<br />تو گفتی که گیتی به یک رنگ بود.<br /> <font color=\"Red\">فردوسی .</font><br />سپیده چو ازکوه سر برکشید<br />طلایه به پیش دهستان رسید.<br /> <font color=\"Red\">فردوسی .</font><br />چو خورشید تابان بیاراست گاه <br />طلایه بیامد ز نزدیک شاه .<br /> <font color=\"Red\">فردوسی .</font><br />زبهر طلایه یکی کینه توز<br />فرستاد با لشکری رزم یوز.<br /> <font color=\"Red\">فردوسی .</font><br />طلایه ز ترکان چو هشتادمرد<br />همی گشت بر گرد دشت نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />به ره بر فراوان طلایه بکشت <br />کسی کو نشد کشته بنمود پشت .<br /> <font color=\"Red\">فردوسی .</font><br />تو بی دیده بان وطلایه مباش <br />ز هر دانشی سست مایه مباش .<br /> <font color=\"Red\">فردوسی .</font><br />گرازه طلایه است با گستهم <br />که با بیژن گیو باشد بهم .<br /> <font color=\"Red\">فردوسی .</font><br />طلایه فرستاد هر سو به راه <br />همی داشت لشکر ز دشمن نگاه .<br /><font color=\"Red\">فردوسی .</font><br />شب و روز گرد طلایه بپای <br />سواران بادانش و رهنمای .<br /> <font color=\"Red\">فردوسی .</font><br />سپهبد طلایه به داراب داد<br />طلایه سنان را به زهر آب داد.<br /> <font color=\"Red\">فردوسی .</font><br />بدان نامداران افراسیاب <br />رسیدیم ناگه بهنگام خواب <br />از ایشان سوارطلایه نبود<br />کسی را ز اندیشه مایه نبود.<br /> <font color=\"Red\">فردوسی .</font><br />همیشه به پیش اندرون دار پیل <br />طلایه پراکنده بر چار میل .<br /> <font color=\"Red\">فردوسی .</font><br />بباید به هر گوشه ای دیده بان <br />طلایه به روز و به شب پاسبان .<br /> <font color=\"Red\">فردوسی .</font><br />همه کس فرستید و آگه کنید<br />طلایه پراکنده بر ره کنید.<br /> <font color=\"Red\">فردوسی .</font><br />به هشتم طلایه بیامد ز راه <br />به خسرو چنین گفت کآمد سپاه .<br /><font color=\"Red\">فردوسی .</font><br />چنانچون ببایست برساخته <br />ز هر سو طلایه برون تاخته .<br /> <font color=\"Red\">فردوسی .</font><br />طلایه بیامد ز ترکان به راه <br />بدیدند بهرام را با سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />طلایه چو گرد سپه دید رفت <br />بپیچید سوی فرامرز تفت .<br /> <font color=\"Red\">فردوسی .</font><br />برفتند کارآگهان ناگهان <br />نهفته بجستند کار جهان <br />چو دیدند هر گونه بازآمدند<br />بر شاه گردن فراز آمدند.<br /> <font color=\"Red\">فردوسی .</font><br />که قیصر ز می خوردن و از شکار<br />همی هیچ نندیشد از روزگار<br />نه روزش طلایه نه شب پاسبان <br />سپاه است همچون رمه بی شبان .<br /> <font color=\"Red\">فردوسی .</font><br />چنین تا بنزدیکی طیسفون <br />طلایه همی راند پیش اندرون .<br /> <font color=\"Red\">فردوسی .</font><br />طلایه برافکند بر گرد دشت <br />همه شب همی گرد لشکر بگشت .<br /> <font color=\"Red\">فردوسی .</font><br />چو یک بهره از تیره شب درگذشت <br />خروش طلایه برآمد ز دشت .<br /> <font color=\"Red\">فردوسی .</font><br />طلایه به هرمزد خرّاد داد<br />بسی گفت با او به بیداد و داد.<br /> <font color=\"Red\">فردوسی .</font><br />تهمتن گذشت از طلایه سوار<br />بیامد شتابان سوی کوهسار.<br /> <font color=\"Red\">فردوسی .</font><br />بدانست رستم کز ایران سپاه <br />به شب گیو باشد طلایه به راه .<br /> <font color=\"Red\">فردوسی .</font><br />برون کن طلایه ز پیش سپاه <br />به روز سپید و شبان سیاه .<br /> <font color=\"Red\">فردوسی .</font><br />چو نزدیکی زابلستان رسید<br />خروش طلایه به دستان رسید.<br /> <font color=\"Red\">فردوسی .</font><br />یک یک طلایگان شهنشاه بوده اند<br />سلطان ماضی و پدر او سبکتکین .<br /> <font color=\"Red\">فرخی .</font><br />و اینک بیامده ست به پنجاه روز پیش <br />جشن سده طلایه ٔ نوروز نامدار.<br /> <font color=\"Red\">منوچهری .</font><br />ملکی کو ملکان را سر و مایه شکند<br />لشکر چین و چگل را به طلایه شکند.<br /> <font color=\"Red\">منوچهری .</font><br />باد از سمنستان به تک آید به طلایه <br />تا حرب کند با سپه ابر نفایه .<br /> <font color=\"Red\">منوچهری .</font><br />اگر منوچهر این ناجوانمردی نکند امیر محمود هشیار و بیدار و گربز و بسیاردان است و بر خداوند نیز مشرفان و جاسوسان دارد و بر همه ٔ راهها طلایه گذاشته است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٣١</span>).<br />ز جنگ آرمیدند هر دو گروه <br />طلایه همی گشت بردشت و کوه .<br /> <font color=\"Red\">اسدی (گرشاسب نامه ص <span class=\"hlight\" dir=\"rtl\">٦١</span>).</font><br /> <BR><font color=\"Blue\">◄</font> دوائی که بدان طلا کنند. نورالدین ظهوری راست <span class=\"hlight\">:</span> <br />سرخ رویند عاشقان در هند<br />خون ناب است گر طلایه ٔ عشق .<br /><font color=\"Red\">(از آنندراج ).</font><br /></font></div>'),
(177377, 'طلایه', '<span class=\"hlight\">طلایه .</span> <font color=\"DarkGreen\"><b>[ طَ ی َ ]</font></b> (اِخ ) دهی از دهستان جانکی بخش لردگان شهرستان شهرکرد در <span class=\"hlight\" dir=\"rtl\">٤</span>هزارگزی جنوب خاوری لردگان . کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">٣٩٦</span> تن سکنه . آب آن از چشمه و محصول آنجا غلات و ارزن و تنباکو و کشمش و بادام و تریاک . شغل اهالی زراعت . صنایع دستی زنان جاجیم بافی و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(177378, 'طلایه دار', '<span class=\"hlight\">طلایه دار.</span> <font color=\"DarkGreen\"><b>[ طَ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (نف مرکب ) دیده بان <span class=\"hlight\">:</span> <br />هنوز میر خراسان به راه بود که بود<br />طلایه دار برآورده زان سپاه دمار.<br /> <font color=\"Red\">فرخی .</font><br />طلایه دار لشکر گر نشد لاله چرا زینسان <br />نشیند هر گلی بر دشت و او بر کوهسار آید.<br /> <font color=\"Red\">فرخی .</font><br />آری هرآنگهی که سپاهی شود به رزم <br />ز اول به چند روز بیاید طلایه دار.<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(177379, 'طلایه داری', '<span class=\"hlight\">طلایه داری .</span> <font color=\"DarkGreen\"><b>[ طَ ی َ <span class=\"hlight\" dir=\"rtl\">/</span>ی ِ ]</font></b> (حامص مرکب ) عمل طلایه دار. رجوع به طلایه شود.<br /></font></div>'),
(177380, 'طلایه کردن', '<span class=\"hlight\">طلایه کردن .</span> <font color=\"DarkGreen\"><b>[ طَ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ک َ دَ ]</font></b> (مص مرکب ) پیشقراولی کردن <span class=\"hlight\">:</span> <br />طلایه بر سپه روز کرد لشکر شب <br />ز راست فرقد و شِعری ̍ ز چپ سهیل یمن .<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(177381, 'طلایگی', '<span class=\"hlight\">طلایگی .</span> <font color=\"DarkGreen\"><b>[ طَ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (حامص ) طلایه بودن . عمل طلایه . پیش قراولی و نگهبانی لشکر <span class=\"hlight\">:</span> مسلم بن زیاد کس بنزدیک مهلب فرستاد و گفت بگوی تا برود و این لشکر بیند که به چه اندازه است و آنچه شرط طلایگی باشد بجا آورد. (تاریخ بخارا).<br /></font></div>'),
(177382, 'طلب', '<span class=\"hlight\">طلب .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) گروه طلب کنندگان . طُلب بالضم ؛ معرب تُلب بمعنی گروه مردم . (غیاث ) (آنندراج ). جماعتی و گروهی از مردمان را گویند که یک جا جمع شده و گرد آمده باشند. (برهان قاطع) <span class=\"hlight\">:</span> و چون خواهد که بجملگی حمله برد سواران را سوی راست و چپ دشمن درآرد و پیاده را هم بر آن تعبیه میبرد طُلب طُلب تا جایگاه از دشمن بستاند. (راحةالصدور راوندی ).<br />نوباوه ٔ باغ اولین صُلب <br />لشکرکش عهد آخرین طُلب .<br /> <font color=\"Red\">نظامی (لیلی و مجنون ).</font><br /> <br />جان پاکان طُلب طُلب و جوق جوق <br />آیدت از هر نواحی مست شوق .<br /> <font color=\"Red\">مولوی .</font><br />با دو صد اقبال او محظوظ ماست <br />با دو صد طُلب ملک محفوظ ماست .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(177383, 'طلب', '<span class=\"hlight\">طلب .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص، اِ) مرد خواهان زنان . <BR><font color=\"Blue\">◄</font> زن خواسته ٔ مرد و معشوق او. گویند: هو طلب النساء و هی طلبه . ج، اَطلاب، طِلبة. (منتهی الارب ).<br /></font></div>'),
(177384, 'طلب', '<span class=\"hlight\">طلب .</span> <font color=\"DarkGreen\"><b>[ طُ ل ُ ]</font></b> (ع ص، اِ) ج ِ طَلوب . (منتهی الارب ).<br /></font></div>'),
(177385, 'طلب', '<span class=\"hlight\">طلب .</span> <font color=\"DarkGreen\"><b>[ طُل ْ ل َ ]</font></b> (ع ص، اِ) ج ِ طالب . (منتهی الارب ).<br /></font></div>'),
(177386, 'طلب', '<span class=\"hlight\">طلب .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع ص، اِ) ج ِ طالب . و فی حدیث الهجرة: فاللّه لکما ان رد عنکما الطلب . جمع طالب است یا مصدر قائم مقام جمع یا به حذف مضاف ای اهل الطلب و کذا بعث الامیر الطلب . (منتهی الارب ) <span class=\"hlight\">:</span> ایشان مقدمه ٔ داوداند از بیم آنکه طلبی دُم ایشان نرود آن خبر افکنده بودند. (تاریخ بیهقی ).<br /></font></div>'),
(177387, 'طلب', '<span class=\"hlight\">طلب .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) در تداول عامه و تداول فارسی، مالی که داین را بر عهده ٔ مدیون است . وام که داده باشند. مقابل بده و بدهی . وام . فام <span class=\"hlight\">:</span> گفت ترا میبرند بکشند من وجوه به تو دهم آن را که طلب دارم بده . (قصص ص <span class=\"hlight\" dir=\"rtl\">١٧٦</span>). <BR><font color=\"Blue\">◄</font> (اِمص ) بازجست . اسم است مطالبه را. (منتهی الارب ). بجُستن . بازجُستن . جویائی . جویانی . جستجو کردن . جستجو. (منتخب اللغات ). جُستن . (المصادر زوزنی ) <span class=\"hlight\">:</span> و به طلب پدر ما نیامده بود از هندوستان . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span>). امیر مسعود... به طلب ایشان <font color=\"DarkGreen\"><b>[ طاووسها ]</font></b> بر بامها آمدی . (تاریخ بیهقی ).<br />طلب علمت فرمود رسول حق <br />گر سفر باید کردن به مثل تاچین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />همیشه در طلب باغ و راغ و گلشن و قصر<br />مدام در طلب جوهر و زر و زیور.<br /> <font color=\"Red\">ناصرخسرو.</font><br />زیر و زبر عالم بهر طلب است ارنه <br />تنگا که زمینستی، لنگا که زمانستی .<br /> <font color=\"Red\">سنائی .</font><br />طلب علم و ساختن توشه ٔ آخرت از مهمات است . (کلیله و دمنه ). و فرامی نمود که برای طلب علم هجرت کرده ام . (کلیله و دمنه ). و بدانکه چون بگریزد در طلب او نروی و جد ننمایی . (کلیله و دمنه ). در طلب زیادتی قدم نمیگذارم . (کلیله و دمنه ). زاهد... در طلب او <font color=\"DarkGreen\"><b>[ دزد ]</font></b> روی به شهر نهاد. (کلیله و دمنه ). شتربه را... انتعاشی حاصل آمد و در طلب چراخوری می پویید. (کلیله و دمنه ). ما از آن طبقه نیستیم که این درجات را موشح توانیم بود و در طلب آن قدم توانیم گذارد. (کلیله و دمنه ). و حرص تو در طلب علم و کسب هنر مقرر. (کلیله و دمنه ). چه هیچ خردمندتضییع عمر در طلب آن جایز نشمرد. (کلیله و دمنه ). وبه حال خردمند آن لایقتر که همیشه طلب آخرت را بر دنیا مقدم دارد. (کلیله و دمنه ).<br />امروز عدل بر در مختار دان و بس <br />ایدر طلب که این طلب ایدر نکوتر است .<br /> <font color=\"Red\">خاقانی .</font><br />گر ترا آنجا کشد نبود عجب <br />منگر اندر عجز بنگر در طلب .<br /> <font color=\"Red\">مولوی .</font><br />کاین طلب در تو گروگان خداست <br />زانکه هر طالب به مطلوبی سزاست .<br /> <font color=\"Red\">مولوی .</font><br />به پای طلب ره بدانجا بری <br />وز آنجا به بال محبت پری .<br /> <font color=\"Red\">سعدی .</font><br />گرچه بیرون ز رزق نتوان خورد<br />در طلب کاهلی نباید کرد.<br /> <font color=\"Red\">سعدی .</font><br />طلبت چون درست باشد و راست <br />هم به اول قدم مراد تراست .<br /> <font color=\"Red\">اوحدی .</font><br />افزون ز طلب چو یافت مردم <br />شک نیست که دست وپا کند گم .<br /> <font color=\"Red\">امیرخسرو دهلوی .</font><br /> <BR><font color=\"Blue\">◄</font> خواهش . التماس . درخواست . تقاضا. اطلاب . بازخواه . (زوزنی ).اقتضاء. خواستاری . خواستگاری . خواهانی . خواستن . درخواستن . خواست . اراده . خواسته . مطلوب . <BR><font color=\"Blue\">◄</font> صاحب کشاف اصطلاحات الفنون آرد: طلب در لغت دوست داشتن حصول چیزی بر وجهی است که سعی در تحصیل آن اقتضا کند اگر مانعی از قبیل استحالت و بعد در راه آن نباشد و مانند تمنی نباشد. و در نزد علمای صرف و نحو بر نوعی سخن انشائی اطلاق میشود که بر طلب مذکور دلالت کند چنانکه این معنی از «اطول » مستفاد میشود و گاه بر القای سخنی که دلالت کننده ٔ بر طلب است اطلاق گردد چنانکه انشاء بر القای سخن انشائی اطلاق شود و این گفتار چلبی و ابوالقاسم است . و بودن طلب از اقسام انشا بر حسب مذهب محققان است و برخی بر آنند که طلب واسطه میان خبر و انشاء است . سپس باید دانست که طلب بر حسب آنچه خطیب در تلخیص یاد کرده پنج گونه است : تمنی، استفهام، امر، نهی و نداء. و برخی ترجی را هم قسم ششم طلب دانسته اند و گروهی تمنی و نداء را از اقسام طلب خارج ساخته اند و این نظر آنان مبتنی بر این است که عاقل آنچه را که به استحالت آن داناست نمی طلبد و بنابرین تمنی طلب نیست و مورد لزوم نمیباشد، همچنین طلب روی آوردن به کسی از مفهوم نداء خارج است، چه نداء عبارت از صوتی است که کسی را بدان میخوانند هرچند مورد لزوم باشد. و ناگزیر باید دعاء و التماس را نیز از اقسام طلب شمرد. سپس باید دانست که اگر طلب به طریق علو باشد خواه حقیقةً عالی باشد یا نباشد آن را امر خوانند و اگر به طریق تسفل باشد خواه در واقع سافل باشد یا نباشد آن را دعا نامند و اگر به شیوه ٔ تساوی باشد التماس است، ولی عرفاً التماس جز در مقام تواضع بکار نمیرود. از نظر مطلوب باید دانست که اگر مطلوب ناشدنی باشد آن را تمنی گویند و اگر ممکن باشد چنانچه مقصود حصول امری در ذهن طالب باشد آن را استفهام خوانند و اگر منظور حصول امری در خارج باشد در این صورت هم چنانچه این امر انتفای فعلی باشد آن را نهی خوانند و اگر منظور ثبوت آن باشد در صورتی که با بکار بردن یکی از حروف صورت گیرد آن را ندا نامند وگرنه امر خواهد بود. این است گفتار ابوالبقا در کلیات . <BR><font color=\"Blue\">◄</font> طلب در اصطلاح سالکان آن را گویند که شب و روز در یاد او باشد، چه در خلأ و چه در ملأ، چه در خانه چه در بازار. اگر دنیا و نعمتش و اگر عقبی و جنتش به وی دهند قبول نکند، بلکه بلا و محنت دنیا قبول کند، همه خلق از گناه توبه کنند تا در دوزخ نیفتند و او توبه از حلال کند تا در بهشت نیفتد. همه عالم طلب مراد کنند و او طلب مولی و رؤیت او کند و قدم بر توکل نهد و سؤال از خلق شرک داند و از حق شرم و بلا و محنت و عطا و منع و رد و قبول خلق بر وی یکسان باشد. کذا فی کشف اللغات . و در لطایف اللغات میگوید که : طالب در اصطلاح سالکان آنکه از شهوات طبیعی و لذات نفسانی عبور نماید و پرده ٔ پندار از روی حقیقت بردارد و ازکثرت به وحدت رود تا انسان کامل گردد و این مقام رافناء فی اﷲ گویند که نهایت سیر طالبان است و حضرت شرف الدین یحیی منیری فرموده که : طالب را در هیچ منزل آرام نی بلکه در هر دو کون بر وی حرام است، که : السکون حرام علی قلوب الاولیاء - انتهی . (کشاف اصطلاحات الفنون ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">حسن طلب یا ادب طلب </span> ؛ صنعتی است در شعر. رجوع به حسن طلب شود.<br /><BR><font color=\"Blue\">◄</font> (مص ) دور شدن . دوری گزیدن . (منتهی الارب ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177388, 'طلب', '<span class=\"hlight\">طلب .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (نف مرخم ) در ترکیب به معنی طلبنده و طلب کننده آید.<br />ترکیب ها:<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آرزوطلب </span> . آزادی طلب . آشوب طلب . جاه طلب . حقیقت طلب . ریاست طلب . شرطلب . شهرت طلب .صلح طلب . غوغاطلب . فرصت طلب . مشروطه طلب . مقام طلب . هرج ومرج طلب . هنگامه طلب . رجوع به هر یک از این ترکیبات در جای خود شود.<br /></font></div>'),
(177389, 'طلب اشهاد', '<span class=\"hlight\">طلب اشهاد.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ب ِ اِ ]</font></b> (ترکیب اضافی، اِمرکب ) که آن را طلب تقریر نیز خوانند، در نزد فقها عبارت از اِشهاد شفیع است برای طلب شفعه ٔ خویش در نزد عقار چنانکه بگوید: ای مردم شهادت دهید که من در این عقار طلب شفعه کردم . (از کشاف اصطلاحات الفنون ).<br /></font></div>'),
(177390, 'طلب تقریر', '<span class=\"hlight\">طلب تقریر.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ب ِ ت َ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به طلب اشهاد شود.<br /></font></div>'),
(177391, 'طلب خصومت', '<span class=\"hlight\">طلب خصومت .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ب ِ خ ُ م َ ]</font></b> (ترکیب اضافی، اِ مرکب )در نزد فقیهان آن است که شفعه را در نزد قاضی بطلبند و این هنگامی است که مشتری عقار را به وی تسلیم نکند آن وقت به قاضی میگوید: فلان شخص عقاری خریده است که حدود آن چنان است ... و من شفیع وی هستم بسبب فلان حدود عقار، پس به وی امر کن که آن را به من تسلیم کند. (از کشاف اصطلاحات الفنون ). و رجوع به شفعه شود.<br /></font></div>'),
(177392, 'طلب مواثبه', '<span class=\"hlight\">طلب مواثبه .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ب ِ م ُ ث َ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) مواثبه در لغت بمعنی مسارعت است از وثوب و طلب مواثبه در نزد فقیهان عبارت از طلبیدن شفیع شفعه را در مجلسی که در آن به بیع آگاه شده است و وجه تسمیه ٔ آن این است که بر غایت تعجیل دلالت کند. (از کشاف اصطلاحات الفنون ).<br /></font></div>'),
(177393, 'طلب کردن', '<span class=\"hlight\">طلب کردن .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ک َ دَ ]</font></b> (مص مرکب ) جُستن . درخواستن . جستجو کردن . جستجو. ضرب . (منتهی الارب ذیل ضرب ) <span class=\"hlight\">:</span> <br />من نیابم نان خشک و سوخ شب <br />تو همی حلوا کنی هر شب طلب .<br /> <font color=\"Red\">کسائی .</font><br />برآراست کآید به ایران زمین <br />ز کشور طلب کرد گردان کین .<br /> <font color=\"Red\">فردوسی .</font><br />طلب کرد گرد دلاور یکی <br />ز بسیار گردان و یا اندکی .<br /> <font color=\"Red\">فردوسی .</font><br />از آن پس طلب کن همه لشکرت <br />همه نامداران این کشورت .<br /> <font color=\"Red\">فردوسی .</font><br />به میدان طلب کردیش نازنین <br />چو شیری زدی بر زمینش ز کین .<br /> <font color=\"Red\">فردوسی .</font><br />کسی که نام بزرگی طلب کند نشگفت <br />که کوه زر به بر چشم او نماید کاه .<br /> <font color=\"Red\">فرخی .</font><br />آنگاه فرمود بازگردید و طلب کنید درمملکت من خردمند مردمان را. (تاریخ بیهقی ).<br />یا خود نکنی طلب چو یاران <br />داد خود از این جهان ستانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گفتند طالوت ترا طلب میکند. (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">١٤٩</span>). بلقیس چون نامه بدید و آورنده مرغ بود بترسید و پیران را طلب کرد و آن نامه بخواندند. (قصص ص <span class=\"hlight\" dir=\"rtl\">١٦٥</span>). و گفت هر کدام قوی تراند بیایند و هر کدام ضعیفتراند آنجا بمانند تا وقتی که ایشان را طلب کنم . (قصص الانبیاء). پس چون آدم از حج بازآمد هابیل را طلب کرد نیافت، پرسید که هابیل کجاست . (قصص الانبیاء). انگشتری و نگین هر دو در حوض افتادند، هرچند کسانی فرورفتند و طلب کردند حوض از آب تهی کردند نگینه بازنیافتند. (نوروزنامه ).<br />طلب صحبت خسان نکنی <br />تکیه برعهد ناکسان نکنی .<br /> <font color=\"Red\">سنائی .</font><br />چو سائل از تو بزاری طلب کند چیزی <br />بده وگرنه ستمگر بزور بستاند.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br /> <BR><font color=\"Blue\">◄</font> خواستن که به محضر او آید. فراخواندن . خواندن <span class=\"hlight\">:</span> <br />طلب کرد نزدیک خود ماهروی <br />بیامد همانگاه نزدیک اوی .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> عملی بود که درویشان چند روز به عید نوروز مانده در در خانه ٔ رجال و اعیان میگردندو آن عبارت بود از چادر خردی (قلندری ) که بر پهلوی در خانه برمی افراشتند و به بوق و منتشا و پوست مزین میکردند و آن بوق را گاه گاهی میزدند و این عمل را چندین روز ادامه میدادند تا صاحب خانه مالی میداد.<br /></font></div>'),
(177394, 'طلبان', '<span class=\"hlight\">طلبان .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (نف، ق ) در حال طلبیدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلبان کردن </span> ؛ به صورت آئینی کسی را نزد خود خواستن . به مزاح گویند: بار اولی است که او مرا طلبان کرده است ؛ یعنی واخوانده است .<br /></font></div>'),
(177395, 'طلبان', '<span class=\"hlight\">طلبان .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِخ ) شهری است . (معجم البلدان ).<br /></font></div>'),
(177396, 'طلبة', '<span class=\"hlight\">طلبة.</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ ب َ ]</font></b> (ع اِ) خواسته . مطلوب . (منتهی الارب ).<br /></font></div>'),
(177397, 'طلبة', '<span class=\"hlight\">طلبة.</span> <font color=\"DarkGreen\"><b>[ طِ ل َ ب َ ]</font></b> (ع اِ) ج ِ طِلب . (منتهی الارب ).<br /></font></div>'),
(177398, 'طلبة', '<span class=\"hlight\">طلبة.</span> <font color=\"DarkGreen\"><b>[ طِ ب َ ]</font></b> (ع اِمص ) بازجست . اسم است طلاب را. <BR><font color=\"Blue\">◄</font> (اِ) زن ِ خواسته . معشوقه ٔ مرد. <BR><font color=\"Blue\">◄</font> ام طلبة؛ عقاب . (منتهی الارب ).<br /></font></div>'),
(177399, 'طلبة', '<span class=\"hlight\">طلبة.</span> <font color=\"DarkGreen\"><b>[ طُ ب َ ]</font></b> (ع اِ) فرشتگان که اعمال عباد را نویسند و نگاه دارند، خلاف سفره ٔ قریب که کرام الکاتبین اند. (منتهی الارب ).<br /></font></div>'),
(177400, 'طلبة', '<span class=\"hlight\">طلبة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ب َ ]</font></b> (ع ص، اِ) ج ِ طالب . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلبه ٔ علم </span> ؛ دانش پژوهان . جویندگان علم . و فارسی زبانان آن را به صورت مفرد بمعنی دانشجوی علوم قدیم بکار برند مانند عمله و تبعه .<br /></font></div>'),
(177401, 'طلبة', '<span class=\"hlight\">طلبة.</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ ب َ ]</font></b> (اِخ ) ابن قیس بن عاصم . از مردان عرب . این شعر از یکی از فرزندان اوست :<br />و کنت اذا خاصمت خصماً کببته <br />علی الوجه حتی خاصمتنی الدراهم <br />فلما تنازعنا الخصومة غلبت <br />علی و قالوا قم فانک ظالم .<br /><font color=\"Red\">(عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>).</font><br /></font></div>'),
(177402, 'طلبسة', '<span class=\"hlight\">طلبسة.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابن زیاد، از بنی ربیعة. کسی که در یوم وقیط، حنظلة المأمون بن شیبان بن علقمة را اسیر کرد. (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>).<br /></font></div>'),
(177403, 'طلبکار', '<span class=\"hlight\">طلبکار.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ص مرکب ) داین . غریم . بستانکار. وام ده . وام خواه . کسی که پول یا کالائی از دیگری باید به او برسد. <BR><font color=\"Blue\">◄</font> طلبنده . خواهان و آرزومند. زغبوت . (منتهی الارب ). خواستار <span class=\"hlight\">:</span> <br />روزی که جدا ماندمی از تو ز پی من <br />صد راه رسول آمده بودی و طلبکار.<br /> <font color=\"Red\">فرخی .</font><br />طلبکار باید صبور و حمول <br />که نشنیده ام کیمیاگر عجول .<br /><font color=\"Red\">سعدی .</font><br />طلبکار خیر است و امیدوار<br />خدایا امیدی که دارد برآر.<br /> <font color=\"Red\">سعدی .</font><br />به دیدار وی زی سپاهان شدم <br />به مهرش طلبکار و خواهان شدم .<br /> <font color=\"Red\">سعدی .</font><br />که و مه طلبکار عمرند و بس <br />کسی را به مردن نیاید هوس .<br /><font color=\"Red\">امیرخسرو.</font><br /></font></div>'),
(177404, 'طلبکاری', '<span class=\"hlight\">طلبکاری .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (حامص مرکب ) مطالبه . خواستن .<br /></font></div>'),
(177405, 'طلبی', '<span class=\"hlight\">طلبی .</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ بی ی ]</font></b> (ع ص نسبی ) با یاء نسبت . نزد علماء علم معانی عبارت است از سخنی که به کسی که متردد در حکمی است القاء شده باشد، مانند آنکه به شخص متردد گوئی : اِن زیداً قائم ٌ، و تأکید در مثل این چنین سخن نیکو باشد. هکذا یستفاد من الاطول فی باب الاسناد الخبری . (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(177406, 'طلبیدن', '<span class=\"hlight\">طلبیدن .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ دَ ]</font></b> (مص جعلی ) مصدر برساخته ای از طلب . دعوت کردن . خواندن . آواز کردن . <BR><font color=\"Blue\">◄</font> خواستن . درخواستن . ابتغاء. جُستن <span class=\"hlight\">:</span> <br />سرای و قصر بزرگان طلب تو در دنیا<br />چو مامه (؟) چند گزینی تو جای ویرانی .<br /> <font color=\"Red\">منجیک .</font><br />شهریاری که خلافت طلبد زود فتد<br />از سمنزار به خارستان وز کاخ به کاز.<br /> <font color=\"Red\">فرخی .</font><br />ای مایه ٔ طربم و آرام روز و شبم <br />من خنج تو طلبم تو رنج من طلبی .<br /> <font color=\"Red\">عنصری .</font><br />طاهر را مثال بود تا مال ضمان گذشته و آنچه اکنون ضمان کرده بودند بطلبد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٤٥</span>). حریص را راحت نیست زیرا که وی چیزی طلبد که شاید که وی را ننهاده اند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span>).<br />بیچاره زنده ای بود ای خواجه <br />آنک او ز مردگان طلبد یاری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آن می طلبد همی و آن گل <br />چون تو نه چنین و نه چنانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />حجت آری که همی جاه و بزرگی طلبی <br />کم بر آن سان که همه خلق جهان می طلبد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />مرا مکان به خراسان زمین به یمگان است <br />کسی چرا طلبد در سفر خراسان را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />شادی بطلب که حاصل عمر دمی است .<br /> <font color=\"Red\">خیام .</font><br />فرمود که مردی هنرمند باید طلبید. (کلیله و دمنه ). ماده گفت جائی باید طلبید. (کلیله و دمنه ). و جباران کامگار در حریم روزگار او امان طلبیدند. (کلیله و دمنه ). زاهد... منزلی دیگر طلبید. (کلیله و دمنه ). زاهد... جائی طلبید که پای افزار گشاید. (کلیله و دمنه ).<br />زمانه زو طلبد امر و نهی، نز گردون <br />کسی طلب نکند کارزرگر از جولاه .<br /> <font color=\"Red\">فلکی .</font><br />مرد که فردوس دید کی نگرد خاکدان <br />وانکه به دریا رسید کی طلبد پارگین .<br /> <font color=\"Red\">خاقانی .</font><br />نتوان طلبید نانهاده .<br /> <font color=\"Red\">کمال الدین اسماعیل .</font><br />ای نسخه ٔ اسرار الهی که توئی <br />وی آینه ٔ جمال شاهی که توئی <br />بیرون ز تو نیست هرچه در عالم هست <br />از خود بطلب هر آنچه خواهی که توئی .<br /> <font color=\"Red\">مولوی .</font><br />مطَلَب گر توانگری خواهی <br />جز قناعت که دولتی است هنی .<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />طریق صدق بیاموز و آب صافی دل <br />براستی طلب آزادگی ز سرو چمن .<br /> <font color=\"Red\">حافظ.</font><br />معیار دوستان دغل روز حاجت است <br />قرضی برای تجربه از دوستان طلب .<br /> <font color=\"Red\">صائب .</font><br />در دم طلبی قدم همی زد<br />دم می طلبید و دم نمی زد.<br /> <font color=\"Red\">ایرج .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گواهی طلبیدن </span> ؛ گواهی خواستن .<br /></font></div>'),
(177407, 'طلبیدنی', '<span class=\"hlight\">طلبیدنی .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ دَ ]</font></b> (ص لیاقت ) درخور طلب . سزاوار خواستن .<br /></font></div>'),
(177408, 'طلبیده', '<span class=\"hlight\">طلبیده .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) نعت مفعولی از طلبیدن . خواهان شده . خواسته <span class=\"hlight\">:</span> یک نفس را از چنگال مشقت خلاص طلبیده آید. (کلیله و دمنه ).<br /></font></div>'),
(177409, 'طلة', '<span class=\"hlight\">طلة.</span> <font color=\"DarkGreen\"><b>[ طَل ْ ل َ ]</font></b> (ع اِ) طلاء. می خوش مزه . (منتهی الارب ). شراب خوش طعم . ج، طَلاّت . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> باد خوش . <BR><font color=\"Blue\">◄</font> مرغزار باران رسیده . <BR><font color=\"Blue\">◄</font> زن مرد. (منتهی الارب ). زن . ج، طلات . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> (ص ) زن سالخورده . <BR><font color=\"Blue\">◄</font> زن بیهوده گوی . زن بدزبان . <BR><font color=\"Blue\">◄</font> دسترس در خوردنی و نوشیدنی . (منتهی الارب ).<br /></font></div>'),
(177410, 'طلة', '<span class=\"hlight\">طلة.</span> <font color=\"DarkGreen\"><b>[ طِل ْ ل َ ]</font></b> (ع ص، اِ) ج ِ طَلیل . (منتهی الارب ).<br /></font></div>'),
(177411, 'طلح', '<span class=\"hlight\">طلح .</span> <font color=\"DarkGreen\"><b>[ طُل ْ ل َ ]</font></b> (ع ص، اِ) ج ِ طالح . (منتهی الارب ). بدکرداران . رجوع به طالح شود.<br /></font></div>'),
(177412, 'طلح', '<span class=\"hlight\">طلح .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِخ ) نام موضعی است . اعشی گوید <span class=\"hlight\">:</span> <br />کم رأینا من اناس هلکوا<br />و رأینا المرء عَمْراً بطلح .<br /> <font color=\"Red\">(معجم البلدان ).</font><br />و گویند «ذوطلح » نام موضعی است که اعشی آنجا به خدمت عمرو رسید و شعری در مدح وی سرود که بیت فوق از آنجمله است و برخی معتقدند که اعشی در این شعر خویش از ذوطلح تیمناً به طلح بمعنی نعمت اکتفا کرده است . ابودواد الایادی گوید <span class=\"hlight\">:</span><br />تعرف الدار و رسماً قد مصح <br />و مغانی الحی فی نعف طلح .<br /> <BR><font color=\"Blue\">◄</font> و گویند «ذوطلح » موضعی است که حطیئه در شعر خویش ذکر وی آرد بدینگونه <span class=\"hlight\">:</span> <br />ماذا تقول لافراخ بذی طلح <br />حمرالحواصل لا ماء و لا شجر...<br />و نیز گفته اند «ذوطلح » موضعی است پائین طائف ازآن ِ بنی محرز و همان است که حطیئه ذکر وی آرد و هم گفته اند طلح موضعی است دیگر به بلاد بنی یربوع . و نیز گفته شده است که «ذوطلح » موضع دیگری است . (معجم البلدان ).<br /></font></div>'),
(177413, 'طلح', '<span class=\"hlight\">طلح .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) نعمت . (منتهی الارب ) <span class=\"hlight\">:</span> <br />کم رأینا من اناس هلکوا<br />و رأینا المرء عَمْراً بطلح .<br />ابن السکیت گوید: طلح در این شعراعشی اسم موضعی است، اما دیگران گویند که اعشی در موضعی بنام ذوطلح به خدمت عمرو رسید و در شعر خویش ازذوطلح تیمناً به طلح بمعنی نعمت اکتفا کرد. (معجم البلدان ). رجوع به ماده ٔ بعد شود. <BR><font color=\"Blue\">◄</font> (اِمص ) تازگی . <BR><font color=\"Blue\">◄</font> نازکی . <BR><font color=\"Blue\">◄</font> درد شکم ستور از خوردن طلح . (منتهی الارب ).<br /></font></div>'),
(177414, 'طلح', '<span class=\"hlight\">طلح .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (ع اِ) ج ِ طلحة. (دهار).<br /></font></div>'),
(177415, 'طلح', '<span class=\"hlight\">طلح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) مانده شدن . (زوزنی ) (تاج المصادر). طلاحة. مانده گردیدن شتر و منه حدیث اسلام عمر: فمابرح یقاتلهم حتی طلح ؛ ای اعیا. (منتهی الارب ). مانده کردن ستور و مانده شدن وی . (تاج المصادر). طلح زید بعیره ؛ مانده گردانید شتر را (لازم است و متعدی ). (منتهی الارب ). <BR><font color=\"Blue\">◄</font> لاغر کردن ستور. (زوزنی ). <BR><font color=\"Blue\">◄</font> خالی شکم گردیدن از خوردنی . (منتهی الارب ).<br /></font></div>'),
(177416, 'طلح', '<span class=\"hlight\">طلح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) یکی از بزرگترین درختان نوع عضاه . ام غیلان . (مهذب الاسماء). رجوع به ام غیلان شود. درخت خارآورد و گویند درخت ام غیلان . (مهذب الاسماء). مغیلان . خار مغیلان . درختی بزرگ و خاردار در ریگستان . (منتخب اللغات ). سمر. سمرة. (منتهی الارب ). قال بشربن ابی حازم <span class=\"hlight\">:</span> <br />للّه دَرﱡ بنی حداء من نفر<br />و کل جار علی جیرانه کلب <br />اذا عدوا و عصی الطلح ارجلهم <br />کما تنصب وسط البیعة الصلب .<br />(و انما یعنی انهم کانوا عرجاً فارجلهم کعصی الطلح و عصی الطلح معوجة). (البیان والتبیین ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٣</span>). العلفة؛ ثمرةالطلح .(البیان والتبیین ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>). <BR><font color=\"Blue\">◄</font> اقاقیا . <BR><font color=\"Blue\">◄</font> درخت کیله . (منتخب اللغات ). درخت موز که به هندی کیله گویند. (غیاث ). موز . (منتهی الارب ) (مهذب الاسماء) (دهار) (مجمل ). طلح منضود. موز. <BR><font color=\"Blue\">◄</font> شکوفه ٔ خرما که از غنچه پدید آید. کارد. (مهذب الاسماء). شکوفه ٔ خرما. (منتخب اللغات ). شکوفه ٔ نخستین خرمابن . طلع. (منتهی الارب ). کویلة. چگرد. رجوع به چگرد شود. <BR><font color=\"Blue\">◄</font> آب تیره ٔ باقی مانده ٔ در تک حوض . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) مرد گرسنه . (منتهی الارب ). خالی شکم از طعام . (منتخب اللغات ).<br /></font></div>'),
(177417, 'طلح الغباری', '<span class=\"hlight\">طلح الغباری .</span> <font color=\"DarkGreen\"><b>[ طَ حُل ْ ؟ ]</font></b>(اِخ ) موضعی است مر بنی سِنْبِس را. (منتهی الارب ).<br /></font></div>'),
(177418, 'طلحات', '<span class=\"hlight\">طلحات .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِخ ) ج ِ طلحة و طلحة نام شش تن است که به جود معروفند: <span class=\"hlight\" dir=\"rtl\">١</span>- طلحة الفیاض یا طلحةبن عبیداﷲ. <span class=\"hlight\" dir=\"rtl\">٢</span>- طلحةالجود یا طلحةبن عمربن عبیداﷲبن معمر التمیمی . <span class=\"hlight\" dir=\"rtl\">٣</span>- طلحةالدراهم یا طلحةبن عبداﷲبن عبدالرحمن بن ابی بکر الصدیق . <span class=\"hlight\" dir=\"rtl\">٤</span>- طلحةالخیر یا طلحةبن حسن بن علی بن ابیطالب . <span class=\"hlight\" dir=\"rtl\">٥</span>- طلحةالندی یا طلحةبن عبداﷲبن عوف الزهری . <span class=\"hlight\" dir=\"rtl\">٦</span>- طلحةالطلحات یا طلحةبن عبداﷲبن خلف الخزاعی .<br /></font></div>'),
(177419, 'طلحاف', '<span class=\"hlight\">طلحاف .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) زدن سخت . (منتهی الارب ). طلحیف . رجوع به طلحیف شود.<br /></font></div>'),
(177420, 'طلحام', '<span class=\"hlight\">طلحام .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) موضعی است . (منتهی الارب ) (مهذب الاسماء).<br /></font></div>'),
(177421, 'طلحام', '<span class=\"hlight\">طلحام .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) پیل ماده .(مهذب الاسماء). لغتی است در طلخام . (منتهی الارب ).<br /></font></div>'),
(177422, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن یزید الشامی . محدث است و ازبقیةبن الولید روایت کند. (عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٨</span>).<br /></font></div>'),
(177423, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن یزید کوفی، مکنی به ابوحمزه . تابعی است .<br /></font></div>'),
(177424, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن یحیی، مکنی به ابوسفیان . تابعی است .<br /></font></div>'),
(177425, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن یحیی . محدث است . وی از ابوبردة و او از ابوموسی حدیث کرده است که ابوموسی کتابی آورد و گفت اگر بیم آن نداشتم که در این کتاب نام خدای تعالی باشد میسوختمش . (المصاحف ص <span class=\"hlight\" dir=\"rtl\">١٩٥</span>).<br /></font></div>'),
(177426, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ]</font></b> (اِخ ) ابن محمد (گویند احمد) بن طلحه ٔ نعمانی، مکنی به ابومحمد. مردی فاضل و عارف به لغت و ادب و شعربود. به بغداد و خراسان درآمد و با حریری صاحب مقامات مکاتبه داشت و مردی بود بسیارحفظ و نیکوشعر و سریعالبدیهه . طلحة بسال <span class=\"hlight\" dir=\"rtl\">٥٢٠</span> هَ . ق . درگذشت . او راست :<br />اذا نالک الدهر بالحادثات <br />فکن رابطالجأش صعب الشکیمه <br />ولاتهن النفس عند الخطوب <br />اذا کان عندک للنفس قیمه <br />فواﷲ مالقی الشامتون <br />بأحسن من صبر نفس کریمه .<br /><font color=\"Red\">(معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٧</span>).</font><br /></font></div>'),
(177427, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) الاجل شهاب الدین ابوالحسن طلحة. از اهل مرو است و بقول امین احمد رازی در تذکره ٔ هفت اقلیم با سنجربن ملکشاه (<span class=\"hlight\" dir=\"rtl\">٥١١</span> - <span class=\"hlight\" dir=\"rtl\">٥٥٢</span> هَ . ق .) معاصر بوده است . عوفی گوید: در لطف طبع یگانه و در وفور هنر نادره ٔ زمانه، به آداب و فضائل قدوه ٔ سحبان وائل، ذات او بحر براعت بود. اما موج آن بحر لاَّلی معانی نفیس و قصر قدراو رشک اوج کیوان و برجیس، خِطه ٔ مرو به مکان او مفاخر و وفور فضل او بر اقران ظاهر، چون سمای سخن پروری از خورشید ذات سمائی خالی شد و آن یگانه به جوار رحمت آفریدگار رفت ابوالحسن او را مرثیتی گفت . قطعه :<br />ز بهر آنکه نبینم همی سمائی را<br />کنار من چو سمائی شد از ستاره ٔ اشک <br />به ژرف دریا ماند ز رنج فرقت او<br />کنار من که نبینی در او کناره ٔ اشک <br />چو اشک من ز صفا رنگ لفظ او دارد<br />کنم ز بهر تسلای دل نظاره ٔ اشک <br />ز اشک چاره همی جویم و همی دانم <br />که هم ز غایت بیچارگی است چاره ٔ اشک .<br />و اشعار او آنچه قصاید و مقطعات است نادر و کم یاب است، اما اکثر نظم او رباعیات بوده است و این رباعی چند از گفتار او در قلم آمد:<br /> <font color=\"Red\">رباعی </font><br />آن دل که بُدی فارغ و ساکن پیوست <br />برخاست چو اندر او هوای تو نشست <br />آن دست که بند چرخ را بگشادی <br />بند سر زلف تو به یک موی ببست .<br /> <font color=\"Red\">رباعی </font><br />گیرم که ز زلف حلقه ها بافته ای <br />وانگه به رخ چو ماه برتافته ای <br />الماس لطافت از کجا یافته ای <br />کآن لعل چنان به حیله بشکافته ای .<br /> <font color=\"Red\">رباعی </font><br />ای عشق پرآشوب، گناهم تو بسی <br />وی چهره ٔ یار، عذرخواهم تو بسی <br />بر روز جوانی که سیه شد ز فراق <br />ای موی سپید من گواهم تو بسی .<br /> <font color=\"Red\">رباعی </font><br />گفتم خونت بریزم ای بینائی <br />مانا که زبان به مهر می نگشائی <br />آن خون ز ره دیده بپالودم پاک <br />تا دست به خون چون منی نالائی .<br /> <font color=\"Red\">رباعی </font><br />هرچند غم من از جفا کردن تست <br />خون من از این حدیث در گردن تست <br />با اینهمه از مهر تو نزدیک رهی <br />کاری که مهمتر است غم خوردن تست .<br /> <font color=\"Red\">رباعی </font><br />تا از دل یکدگر خبر یافته ایم <br />از کینه و مهر هر دو دل تافته ایم <br />من در طلب رضا و او در پی خشم <br />انصاف بده که موی بشکافته ایم .<br /> <font color=\"Red\">رباعی </font><br />روزی به گلستان که خرامیدی مست <br />از رنگ رخ تو گل نیفتاد ز دست <br />نظاره ٔ روی تو بود گل پیوست <br />گل را تو چنان خوشی که ما را گل هست .<br /> <font color=\"Red\">رباعی </font><br />با درد شب دراز هم ساز منم <br />با سوخته دل ساخته هم راز منم <br />هر جانوری که در شب آواز دهد<br />با او به نیاز دل هم آواز منم .<br /> <font color=\"Red\">رباعی </font><br />نام لب تو نقش نگین باید کرد<br />زیر قدمت دیده زمین باید کرد<br />گفتی که سر تو دارم از عالم و بس <br />ترسم که سر اندر سر این باید کرد.<br /> <font color=\"Red\">رباعی </font><br />گر در دل من ندانی اندازه ٔ درد<br />ای دوست سرشک سرخ بین و رخ زرد<br />ور نیستی آگه که به من هجر چه کرد<br />برخیز و بیا گرم بپرس از دم سرد.<br /> <font color=\"Red\">رباعی </font><br />دوش از تو دلم شاد شد ای چشمه ٔ نوش <br />و امشب ز غم فراقت آمد به خروش <br />چیزی که قیاس آن نشاید کردن <br />یا محنت امشب است یا راحت دوش .<br /> <font color=\"Red\">رباعی </font><br />آن دل که کلید گنج هر شادی داشت <br />در هر کاری هزار استادی داشت <br />شد بنده ٔ تو بدان نمانست که او<br />هرگز روزی نشان آزادی داشت .<br /> <font color=\"Red\">رباعی </font><br />چون صبر رمیده شد پیام توچه سود<br />جان رفت ز پرسش و سلام تو چه سود<br />در آتش هجران تو ای جان جهان <br />دل سوخته شد وعده ٔ خام تو چه سود.<br /> <font color=\"Red\">رباعی </font><br />گه گوژ چو زلف دلستان تو منم <br />گه نیست شده همچو دهان تو منم <br />ای قد تو همچو تیر، آخرروزی <br />بر من گذری کن که کمان تو منم .<br /> <font color=\"Red\">رباعی </font><br />از هجر تو گر به گوشمال تو درم <br />گوئی ز خیالت به وصال تو درم <br />بر من سپه هجر ترا دستی نیست <br />تا من به حمایت خیال تو درم .<br /> <font color=\"Red\">رباعی </font><br />در عشق تو دل نکرد یاد از دگری <br />دیده ز وفا نشان نداد از دگری <br />گرچه ستم از تو دیده، داد از دگری <br />غمناک هم از تو به که شاد از دگری .<br /> <font color=\"Red\">رباعی </font><br />ز اندیشه ٔ تو دلم به محنت فرسود<br />دشمن ز تو ای دوست به من بر بخشود<br />گوئی که دلم یک نفس ای جان جهان <br />آنجا که فراغت دلی بود نبود.<br /> <font color=\"Red\">رباعی </font><br />چون هجر کیم بست به جنگ دل من <br />در دامن صبر دیده چنگ دل من <br />هان تا چه کنی تو با من ای صبر از آنک <br />در گردن تست نام و ننگ دل من .<br /><font color=\"Red\">(لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">١٥٣</span> - <span class=\"hlight\" dir=\"rtl\">١٥٦</span>).</font><br /></font></div>'),
(177428, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) حنفی بن اعلم . از مردم جیان اصفهان است .<br /></font></div>'),
(177429, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) عبداﷲبن عوف قُرشی . تابعی است .<br /></font></div>'),
(177430, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) عبداﷲبن عوف معاصر کثیر شاعر. احمدبن سلیمان طوسی گفت حدیث کرد ما رازبیربن بکار و گفت حدیث کرد مرا عثمان بن عبدالرحمان و گفت : در مجلس پدر تو ابوبکربن عبداﷲبن مصعب حاضر شدم و عبدالعزیزبن عمران الزهری آنجا بود و این عبدالعزیز شعر گفتی اما شعری ضعیف . ابوبکر وی را گفت یا اباعبدالرحمن ! با چنان خرد چگونه است که شعری چنین ضعیف میسرائی ؟ عبدالعزیز گفت خدا اصلاح کار تو کند. کثیر شاعر بر طلحة عبداﷲبن عوف این شعر خویش بخواند:<br />و انی علی سقمی باسماء و الذی <br />تُراجع منی النفس بعد اندمالها<br />لارتاح من اسماء للذکر قد خلا<br />و للربع من اسماء بعد احتمالها.<br />طلحة وی را گفت یا اباصخر این شعر تراست ؟ کُثیر به پاسخ گفت پندارم از نکوئی شعر با این مایه خرد که مراست به شگفت آمده ای . طلحه گفت همچنین است که میگوئی . کثیر گفت همانا عقل تو ترا توانائی شناختن شعر من نداده بلکه به معرفت خرد من نافذ ساخته است . آنگاه عبدالعزیز ابوبکر را گفت : عقل تو نیز ترا به شناخت خرد من قادر ساخته اما دیده ات را به شعر من ژرف بین نگردانیده است . (الموشح مرزبانی ص <span class=\"hlight\" dir=\"rtl\">٣٦٠</span>).<br /></font></div>'),
(177431, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن ابی قنان . محدث است . رجوع به ابوقنان طلحة... شود.<br /></font></div>'),
(177432, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن هرم . قاضی مکه به روزگار سلیمان بن عبدالملک خلیفه ٔ اموی . رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span> و <span class=\"hlight\" dir=\"rtl\">١٩١</span> شود.<br /></font></div>'),
(177433, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن سوار. صاحب تاریخ سیستان ذیل عنوان «عصیان آوردن خالدبن محمدبن یحیی » وی را از سرداران احمد قدام دانسته وگوید پس از هزیمت شدن احمد قدام از عبداﷲبن احمد «هندوان با احمد قدام به بست شدند و طلحةبن سوار را به طلیعه به دهک فرستادند...». (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>).<br /></font></div>'),
(177434, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن زید. محدث است . و از احوص روایت کند. (عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٩</span>).<br /></font></div>'),
(177435, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن حسن بن علی، معروف به طلحةالخیر. یکی از بخشندگان مشهور است . (المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span>).<br /></font></div>'),
(177436, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن جعفر، ملقب به الموفق . برادر المعتمد خلیفه ٔ عباسی . رجوع به ابواحمد الموفق طلحة و الموفق باللّه ... شود.<br /></font></div>'),
(177437, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن بُراء انصاری . صحابی است .<br /></font></div>'),
(177438, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن الخراش . تابعی است .<br /></font></div>'),
(177439, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن احمدبن طلحة النیسابوری . صاحب اخبار اصفهان آرد که وی مردی کهل، میانسال بود و به اصفهان درآمد و حدیث نوشت و از وی نیز روایت کرده اند. (اخبار اصفهان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span>).<br /></font></div>'),
(177440, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن طاهر ذوالیمینین بن حسین بن مُصعب بن زریق . دومین امیر از آل طاهر و حکمران خراسان از سال <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> تا سال <span class=\"hlight\" dir=\"rtl\">٢١٣</span> هَ . ق . طلحة به روزگارپدر حکومت سیستان داشت بدین تعبیر که طاهر پس از عزل محمدبن الحضین القوسی از حکومت سیستان بسال <span class=\"hlight\" dir=\"rtl\">٢٠٦</span> هَ. ق . سیستان پسر خویش را داد، طلحةبن طاهر و طلحة الیاس بن اسد را اینجا فرستاد . چون طاهربن الحسین به خراسان مأمون را خلع کرد اندر خطبه ٔ روز آدینه در سال دویست و هفت و همان شب به فجا بمرد طلحة از جانب مأمون به حکومت خراسان رسید و الیاس بن اسد را به حکومت سیستان فرستاد. پس از آن طلحة سیستان معدل بن الحضین القوسی برادر محمدبن الحضین را داد به خلافت برادر وی محمد و چون مردمان با الیاس ساخته تر بودند الیاس مردمان را بر معدل بن الحضین شوریده گونه همی داشت و محمدبن الحضین بر خوارج روی گرفت و بدیشان تقویت جست و بیرون شد و از حمزه سپاه خواست ... و خوارج با او یکجا و او با ایشان همی بودند و همه سواد سیستان او داشت، همیشه با خوارج ساخته بود و او را هیچ نیازردندی و طلحة سیستان محمدبن الاحوص را داد و پس از وی حکومت آنجا را به محمدبن شیب واگذارد و پس از وی محمدبن اسحاق بن سمره را عامل سیستان کرد و او یعنی محمدبن اسحاق محمدبن یزید را به خلیفتی خویش به سیستان فرستاد و خود نیز بر اثر وی بیامد. چون در این هنگام مردی از عیاران سیستان به بست بیرون شده بود، محمدبن اسحاق به حرب آن عیار بیرون رفت و در همین اوان طلحة حسن بن علی سیاری را عمل سیستان داد و پس از وی احمدبن خالد را به حکومت سیستان فرستاد و احمدبن خالد «محمدبن اسماعیل الذهلی را به سیستان فرستاد و روز چهارشنبه هفت روز مانده از ربیعالاَّخر سنه ٔ ثلث عشر و مائتی (<span class=\"hlight\" dir=\"rtl\">٢١٣</span> هَ . ق .) اندرآمد <font color=\"DarkGreen\"><b>[ به سیستان ]</font></b> و بر اثر وی احمدبن طاهر اندرآمد اندر ماه جمادی الاولی این سال، چون خواست کی به شهر اندرآید فوجی از یاران حمزه ٔ خارجی به تاختن او آمدند و او را اندر شهر نگذاشتند و حربی سخت کردند و احمدبن خالد به هزیمت باز خراسان شد. و حمزة الخارجی روز آدینه دوازده روز گذشته از جمادی الاَّخره ٔ سنه ٔ ثلث عشر و مائتی سهیش (؟)فرمان یافت ...» . از آنچه گفته شد معلوم گردید که واقعه ٔ مهم امارت طلحه جنگهای اوست با حمزةبن عبداﷲ خارجی یا حمزه ٔ آذرک شاری . اندکی پس از این جنگها و فیروزی طلحه روز یکشنبه چهار روز باقی مانده از ربیعالاوّل سنه ٔ ثلث عشر و مائتی فرمان یافت . صاحب حبیب السیر در ذکر طلحةبن طاهر گوید: در شهور سنه ٔ تسع و مأتین بموجب فرمان مأمون در ولایت خراسان بر سریر حکومت نشست و در زمان ایالت او حمزه نامی در سیستان خروج کرده طلحة بجانب او لشکر کشید و حمزه را مغلوب گردانید و به خراسان بازگردید و در سنه ٔ ثلاث عشر و مأتین طلحه وفات یافت و پسرش علی (؟) قایم مقام پدر شد .<br /></font></div>'),
(177441, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن ابی طلحه ٔ جویباری، منسوب به جویبار، موضعی به جرجان .<br /></font></div>'),
(177442, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن ابی طلحةبن ابی طلحة، ملقب به کبش الکتیبه . صاحب امتاع الاسماع گوید: نامش عبداﷲبن عبدالعزی بن عثمان بن عبدالداربن قصی است . وی کسی است که در روز بدر حامل یکی از سه رایت سپاه قریش بود و هموست که در جنگ احد حامل لوا بود وبه دست حضرت علی علیه السلام کشته شد. صاحب حبیب السیرگوید: «در لشکر کفار سه عَلَم بود: طلحةبن ابی طلحةبن ابی طلحة و ابوعزیزبن عمرو و نضربن الحارث که از بنی عبداﷲ بودند، در آن روز <font color=\"DarkGreen\"><b>[ روز بدر ]</font></b> به تحمل رایات نکبت آیات کفار قیام می نمودند...». و صاحب امتاع الاسماع نیز همین گوید، الا آنکه ابوعزیز را پسر هُمیر و برادر مصعب بن عُمیر نوشته است . صاحب حبیب السیر در واقعه ٔ اُحُد آرد: «... ابوسفیان نیز به ترتیب لشکر نکبت اثر پرداخته خالدبن ولید را والی میمنه گردانید وعکرمةبن ابی جهل به فرموده ٔ وی صاحب میسره گردید و عبداﷲبن ابی ربیعه را بر تیراندازان که صد نفر بودند امیر ساخت و لوا را به طلحةبن ابی طلحة داد و به میدان شتافت و مبارز طلبید <font color=\"DarkGreen\"><b>[ یعنی طلحه ]</font></b>. شیر بیشه ٔ هیجایعنی شاه اولیا اسداﷲ الغالب علی بن ابیطالب، نظم :<br />چو سیلی که آید ز بالا بزیر<br />بزد نعره مانند غرنده شیر<br />و بر سر آن بداختر تاخته به یک ضرب ذوالفقار کار او تمام ساخت و بعد از قتل طلحةبن ابی طلحه رایت قریش را برادرش مصعب برداشت و به زخم پیکان عاصم بن ثابت به قتل رسید، آنگاه برادرش عثمان عَلَم برگرفت، او نیز به تیر عاصم عازم سفر سقر شد و به روایتی عثمان به زخم تیغ حمزه رضی اﷲ عنه مقتول گردید...» . صاحب حبیب السیر به نذر سلافة بنت سعد اشاره کرده است و گفته به روایت اهل سیر در واقعه ٔ احد قرب سی نفر از مشرکان به قتل رسیدند، از این جمله به روایت محمدبن اسحاق دوازده نفر به ضرب تیغ امیرالمؤمنین حیدر کشته شدند: طلحةبن ابی طلحة، ابوسعیدبن طلحة، ابوالحکم بن الاخنس بن شریق السقفی، کلاةبن طلحة، عبداﷲبن جمیل بن زهرة، ولیدبن ابی حذیفةبن المغیرة و برادرش، امیةبن ارطاةبن شرحیل، هشام بن امیة، عمروبن عبداﷲ الجمحی، بشیربن مالک صوأب مولی بنی عبدالدار . رجوع به حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>، <span class=\"hlight\" dir=\"rtl\">١١٨</span>، <span class=\"hlight\" dir=\"rtl\">١٢٠</span>، <span class=\"hlight\" dir=\"rtl\">١٢٢</span> و امتاع الاسماع ص <span class=\"hlight\" dir=\"rtl\">٨١</span>، <span class=\"hlight\" dir=\"rtl\">١٢١</span>، <span class=\"hlight\" dir=\"rtl\">١٢٣</span>، <span class=\"hlight\" dir=\"rtl\">١٢٥</span>، <span class=\"hlight\" dir=\"rtl\">٤١١</span> شود.<br /></font></div>'),
(177443, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن ابراهیم بن تنّه . محدث است .<br /></font></div>'),
(177444, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) محدث است و از عطاء روایت کند. (امتاع الاسماع ص <span class=\"hlight\" dir=\"rtl\">٨٨</span> و <span class=\"hlight\" dir=\"rtl\">٧٤</span>).<br /></font></div>'),
(177445, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (ع اِ) یکی طلح . ج، طِلاح . (منتهی الارب ). درخت موز. (دهار).<br /></font></div>'),
(177446, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ ح َ ]</font></b> (ع ص ) ناقةٌ طلحة؛ ناقه ٔ مبتلای درد شکم از خوردن طلح . <BR><font color=\"Blue\">◄</font> ارض ٌ طلحة؛ زمین طلحناک . (منتهی الارب ).<br /></font></div>'),
(177447, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طِ ح َ ]</font></b> (ع اِ) تأنیث ِ طلح . (منتهی الارب ).<br /></font></div>'),
(177448, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن عدی . از کفار قریش و از قاصدین قتل پیغمبر اکرم است . صاحب حبیب السیر شرح واقعه را چنین آرد: «...ابوجهل ابن هشام گفت انسب و اولی چنان می نماید که از هر قبیله ای شخصی جَلد به سر محمد روند و بیکبار بر او تیغها کشیده رسانند تاخون او در قبایل پراکنده شود، چون بنی عبدمناف را قوت مقاومت با تمامت قبایل نباشد ناکام به دیت راضی گردند. پیر نجدی این رأی را تحسین نموده خاطر بر آن قرار یافت و قوم قریش متفرق شدند و همان لحظه جبرئیل نازل گشته آیت کریمه ٔ «و اذ یمکر بک الذین کفروا لیثبتوک او یقتلوک او یخرجوک و یمکرون و یمکر اﷲ و اﷲ خیر الماکرین » (قرآن <span class=\"hlight\" dir=\"rtl\">٣٠/٨</span>) بر سیدالمرسلین خواند و پیغام رب العالمین رسانید که شب در مقام معهود به استراحت نپردازد و روز دیگر متوجه مدینه گردد. چون لباس روزگار بسان قلوب اشرار کفار سیاه و تاریک شد رؤسای قریش مثل ابوجهل و ابولهب و ابی بن خلف و بنیه و ایه پسران حجاج و نضربن الحارث و عقبةبن ابی معیط و حکم بن العاص و طلحةبن عدی با فوجی دیگر از کفار چنانچه قرار داده بودند به قصد قتل سید ابرار صلی اﷲ علیه و آله الاخیار توجه نمودند...». (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(177449, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن نافع، مکنی به ابوسفیان . تابعی است .<br /></font></div>'),
(177450, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن مصرف الایامی، از اهل همدان، مکنی به ابوعبداﷲ.وفات او بسال <span class=\"hlight\" dir=\"rtl\">١٠٣</span> هَ . ق . و او را قرائتی است . زرکلی در الاعلام گوید: اقراء اهل کوفه به عصر خود بود و او را سیدالقراء گفتندی . وفات وی بسال <span class=\"hlight\" dir=\"rtl\">١١٢</span> هَ . ق . بوده است . صاحب المصاحف آرد : حدیث کرد ما را عبداﷲ وحسن بن احمد و مسکین از هارون از ابان بن تغلب از طلحة الایامی از مجاهد: «ان رسول اﷲ صلی اﷲ علیه و سلم کان آخذاً بید عمر فلما انتهی الی المقام قال : هذا مقام انبیا ابراهیم . فقال له النبی (ص ) نعم . قال اء فلانتخذ مصلی ؟ فانزل اﷲ عز و جل : «و اتخذوا من مقام ابراهیم مصلی ». (قرآن <span class=\"hlight\" dir=\"rtl\">١٢٥/٢</span>). صاحب عیون الاخبار گوید : قال طلحةبن مصرف لرجل : لولا انی علی وضوء لاخبرتک بما تقول الشیعة. رجوع به الفهرست ابن ندیم و المصاحف و الاعلام و عیون الاخبار شود.<br /></font></div>'),
(177451, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن مصرف بن عمروبن کعب، مکنی به ابوعبداﷲ و بقولی ابومحمد. تابعی و قاری اهل کوفه بود و بر وی قرائت قرآن کردندی . چون روزافزونی قارئین بدید مکروه داشت و بنزد اعمش شد و نزد وی قرائت آغاز کرد، مردمان نیز روی به اعمش نهادند و طلحة رافروگذاردند. طلحه گروهی از صحابه را درک کرد و از انس و عبداﷲبن الزبیر استماع حدیث کرد. وی با قراء کوفه در روزگار حج به جماجم بیرون شد و پس از آن بسال <span class=\"hlight\" dir=\"rtl\">١١٢</span> هَ . ق . درگذشت . (از صفةالصفوه ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٣</span> و <span class=\"hlight\" dir=\"rtl\">٥٤</span>).<br /></font></div>'),
(177452, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن محمدبن الصباح النیلی رحمه اﷲ از کبار اصحاب ابوعثمان حیری است . مات سنة اثنین و ثلثمائة (<span class=\"hlight\" dir=\"rtl\">٣٠٢</span> هَ . ق .). ابوعثمان مغربی وی را گفت خواهی ترا پندی دهم که پنجاه سال است تا خلق را پند میدهم و نمیپذیرند؟ گفت خواهم . گفت تهمت بر کردار خود نه تا باقیمت گردد و تهمت از خلق برگیر تا جنگ برخیزد. شیخ الاسلام گفت که صحبت با اﷲتعالی سه جزو است : دیدن فضل او و عیب خود و عذر خلق و این را چهارم نیست . عذر خلق بین که همه آن میرود که او میخواهد ایشان زیر قضا و قدر و حکم او مضطراند و عیب خودبین تا منت یاد آید. شیخ الاسلام گفت ابوعثمان نصیبی گفت که شبلی گفت که دست به سر ابویعقوب میدانی فرودآوردم در آن وقت که به مصر میرفتم گفتم خیرک اﷲ. هیچ موئی نبود بر تن او که نگفت آمین . (نفحات الانس ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>).<br /></font></div>'),
(177453, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن عمرو تیمی . تابعی است .<br /></font></div>'),
(177454, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن عمر. تابعی است و از عطاء واو از ابوهریره روایت کنند. (عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>).<br /></font></div>'),
(177455, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن عباس الصیرفی، از مردم بغداد، معاصر مرداویج زیاری . صاحب مجمل التواریخ گوید: بسال <span class=\"hlight\" dir=\"rtl\">٣١٩</span> هَ . ق . در بغداد فتنه و شورش پدید آمد و دادخواهان ولایتی که به تصرف مرداویج درآمده بود روی بدان شهر نهادند و هاشمیان و عامه ٔ بغداد با ایشان متفق شدند «پس سرای وزیر غارت کردند و مقتدر خاصگیان را به سرای خویش آورد به نگاه داشت و مردمان اصفهان به تظلم آمدند و خطیب حمزة<font color=\"DarkGreen\"><b>[ بن ]</font></b> ابوالقاسم را از اسپ اندرکشیدند و کلاه از سر<font color=\"DarkGreen\"><b>[ ش ]</font></b>برگرفتند و شغب از حد برفت و هاشمیان رویها سیاه کردند و از گرسنگی و قحط فریاد میکردند و می گفتند الجوع الجوع ! پس طلحةبن عباس الصیرفی از بهر ایشان خوردنی بسیار فرستاد...». (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٣٧٧</span>).<br /></font></div>'),
(177456, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن عبیداﷲبن محمدبن اسماعیل بصری . رجوع به طلحی ابواسحاق طلحة... شود.<br /></font></div>'),
(177457, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن عبیداﷲبن کریزبن الحداجیة الشاعر. نامش قیس بن عمرو از بطون خزاعه و مکنی به ابومطرف تابعی است . صاحب المصاحف گوید: حدیث کرد ما را عبداﷲ و یونس بن حبیب و ابوداود و عمران القطان از طلحةبن عبیداﷲبن کریز الخزاعی از زهری که پیغمبر (ص ) و ابوبکر و عمر و عثمان میخواندند: «مالِک ِ یَوم الدین ». رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٢</span> و المصاحف ص <span class=\"hlight\" dir=\"rtl\">٩٣</span> و عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span> شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177458, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن عبیداﷲبن عثمان بن عمروبن کعب بن سعدبن تیم بن مرة القرشی التیمی، معروف به طلحة الجواد یا طلحةالجود، مکنی به ابومحمد. صحابی جلیل و از کبار اصحاب رسول (ص ) و از عَشَره ٔ مبشره و یکی از اصحاب ششگانه ٔ شوری است و نسبت وی با پیغمبر اکرم در مُرة به هم پیوندد. ابن ندیم وی را یکی از خطبای عرب دانسته است . صاحب عقدالفرید وی را در عداد جماهیر بنی تیم بن مرة که عبارت از ابوبکر الصدیق و عمروبن عبداﷲبن معمر و عبداﷲبن جدعان و علی بن زیدبن عبداﷲبن ابی ملیکه و مهاجربن فهدبن عمربن جدعان و محمدبن المنکدربن عبداﷲبن الهدیر هستند آورده است و صاحب امتاع الاسماع وی را در زمره ٔ آن هشت تن که پیشی گرفتند در اسلام ذکر کرده و هم او را در عداد پنج تنی که به دست ابوبکر مسلمان شدند گفته و آن پنج تن اینانند: عثمان بن عفان، طلحةبن عبیداﷲ، سعدبن ابی وقاص، زبیربن العوام و عبدالرحمان بن عوف ... و صاحب الاصابه نیز بر همین قول رفته است . صاحب عقدالفرید گوید: اسلام ظهور کرد و بجز تنی چند در عرب کسی به نوشتن آشنا نبود و ایشان عبارت بودند از: علی بن ابیطالب کرم اﷲ وجهه و عمربن الخطاب و طلحةبن عبیداﷲ و عثمان و ابان بن سعیدبن خالدبن حذیفةبن عتبة و یزیدبن ابی سفیان و حاطب بن عمروبن عبدالشمس و علأبن الحضرمی و ابوسلمةبن عبدالاشهل و عبداﷲبن سعدبن ابی سرح و حویطب بن عبدالعزی و ابوسفیان بن حرب و معاویة ولده و جهیم بن الصلت بن مَخْرمة .<br />طلحه در برخی از غزوات پیغمبر اکرم چون اُحد و تبوک و غیره شرکت داشت و در غزوه ٔ بدر که بگفته ٔ صاحب حبیب السیر جهت سرانجام دادن بعضی از مهام با هفت تن دیگر فرستاده شده بود او را حضرت حکم حصار بدر داده حصه ٔ غنیمتش ارزانی داشت . طلحه در غزوه ٔ احد شرکت جست و فداکاری بسیار کرد.بگفته ٔ صاحب حبیب السیر از چهارده تن که پس از هجوم قریش در احد ملازمت حضرت اختیار کردند یکی طلحه بود از مهاجرین و از این چهارده کس هشت تن بر موت یکدیگر بیعت کردند و عهد بستند، سه تن از مهاجرین و پنج تن از انصار و یکی از این هشت کس نیز طلحه بود و چنانکه در اکثر کتب مسطور است در روز احد جمعی دیگر از صحابه مانند ابوعبیدةبن الجراح و طلحةبن عبیداﷲ و ابوطلحه ٔ انصاری نیز لوازم شجاعت و پردلی به تقدیم رسانیدند و انگشت طلحة به زخم تیغ ابن قیمه یا اصابت تیر مالک بن زهیر حبشی از کار بازماند . چون حضرت در گود افتاد و کعب بن مالک انصاری وی را شناخت طلحة بدان گود درآمده پشت خم کرد تا آن حضرت پای مبارک بر پشتش نهاد و علی دست همایون خیرالانام گرفت تا از آنجا بیرون شتافت .<br />طلحة در غزوه ٔ تبوک نیز حاضر بود و در میمنه جای داشت و مالی نیز مخارج این غزو را بداد و در حجةالوداع نیز همراهی رسول اکرم کرد و هدی مصحوب خویش بیاورد .<br />چنانکه گفتیم طلحة یکی از اصحاب ششگانه ٔ شورا بود که پس از قتل عمر برای تعیین خلیفه ٔ مسلمین تشکیل گردید. بلعمی در ترجمه ٔ طبری شرح آن چنین آرد: عمر را چون آن زخم برسید دانست که از آن زخم نرهد، پس اندیشه کرد که مسلمانان را به که سپارم، پس پنج تن را اختیار کرد و بخواند، امیرالمؤمنین علی (ع ) و عثمان و عبدالرحمن بن عوف و سعدبن ابی وقاص و زبیربن عوام و طلحه بن عبیداﷲ راطلب کرد و نیافت، پس گفت این کار از شما بیرون نیاید که پیغمبر صلی اﷲ علیه و سلم چون وفات کرد از شما خشنود بود، باید که شما طلحه بیابید و هر پنج، روز پنجم همه اتفاق بر یکی کنند و این کار اندر گردن وی کنند. ایشان گفتند یا عمر این کار ضائع شود، یکی را خلیفه کن همچنانکه ابوبکر ترا خلیفه کرد. گفت اگر ابوعبیده ٔ جراح زنده بودی او را خلیفه کردمی که از پیغمبر صلی اﷲ علیه و سلم شنیدم که گفت ابوعبیده امین است . پس مردی گفت یا عمر پسرت را خلیفه کن . عمر آن مردرا بانگ برزد و گفت خاموش باش واﷲ که این سخن که توگفتی نه مصلحت مسلمانان را بود و نه از بهر خدای گفتی، او را چون خلیفه کنم که او زن خویش را طلاق نتواند دادن . پس گفت شما شش تن گرد آیید که از شما فاضلترکس ندانم و یکدیگر را موافق باشید و این کار اندر گردن یکی کنید. پس عمر ابوطلیحه ٔ انصاری را گفت که ترا با پنجاه تن از انصار بر ایشان موکل کردم چون مرا دفن کنند این شش تن را گرد کنید و مگذارید تا سه روزبپراکنند، روز چهارم باید که بر یک تن بیعت کنند و مخالفت نکنند که اگر یک تن مخالفت کند او را بکش و مقدادبن اسود را بخواند و گفت ترا بر ابوطلیحه موکل کردم تا ایشان را گرد آری و صهیب بن سنان را بخواند و گفت تو این سه روز امام باش و پیش مردم نماز کن و عمر گفت اگر از این پنج تن یک تن مخالفت کند او را بکشند، اگر دو تن سه تن را مخالفت کنند بکشند آن دو تن را و اگر همه یکدیگر را مخالف شوند همه را بکشید... چون کار خلافت بر عثمان قرار گرفت طلحه با وی سخت از در مخالفت درآمد - انتهی .<br />و صاحب مجمل التواریخ آرد: پس از آنکه عثمان کارهای ناشایست بکرد و نامه ای که به عبداﷲبن سعدبن ابی سرح فرمانروای مصر نوشته بود مکشوف گردید مردمان کوفه وبصره بر در سرای وی اجتماع کردند و سرانجام او را در هجدهم ذی الحجه ٔ سال سی وپنجم هجرت بکشتند... مردمان مصر و مدینه سوی علی رفتند تا بیعت کنند، علی گفت به وقت آنک عمر خطاب کار به شوری افکند میخواستم که خلافت مرا باشد، چون بدیدم نخواهم، هر کس را که خواهیدبیعت کنید. ایشان بازگردیدند و مردمان همه پیش طلحه رفتند و او همچنین جواب داد و کوفیان بر زبیر آمدندو به اتفاق همه به آخر سوی مرتضی علی رفتند و او رابه مسجد آوردند که بیعت کنند، طلحه و زبیر حاضر نبودند، ایشان را نیز حاضر کردند و سخنها رفت تا بیعت کردند و نخستین همه طلحه پیش آمد به بیعت کردن و دست بر دست علی زد. اعرابیی آنجا حاضر بود گفت : «ید شلاء و بیعته لایتم ». و این سخن مثل گشت و از آن گفت که طلحه شل بود .<br />بلعمی در ترجمه ٔ تاریخ طبری شرح واقعه را چنین آرد: «آن روز که عثمان را به سرای گرفتند مؤذن بانگ نماز بکرد و او را به نماز خواند وگفت برو و علی را بگوی تا نماز کند. مؤذن سوی علی آمد و علی گفت ابوایوب انصاری را بگوی تا نماز کند وابوایوب روزی چند نماز بکرد، پس علی سهل بن حنیف را گفت نماز کن و نماز آدینه علی کردی . پس مردمان مصر سوی علی آمدند و گفتند دست بیرون آور تا ترا بیعت کنیم . علی گفت شتاب مکنید و با مسلمانان مشورت کنید. پس مردمان مدینه بیامدند و علی را گفتند مردمان را از امام چاره نیست، دست بیرون آر تا ترا بیعت کنیم . گفت آنگاه که اهل مدینه و یاران پیغمبر (ص ) گرد آمدند به وقت آنکه عمر کار به شوری افکند من همی خواستم که این کار مرا بود ولیکن اکنون بیازمودم هرکه را خواهید بدهید تا من او را متابع شوم . پس مصریان سوی طلحه آمدند و او اجابت نکرد زیرا که همی دانست که هنوز خلاف است . پس پنج روز برآمد این غریبان دانستند که این کار از ایشان برنیاید و اهل مدینه را گرد کردند و گفتند امروز پنج روز است تا جهان بی امام است، کسی بنگرید و بدین کار بپای کنید. همه گفتند جز علی کسی دیگررا نشاید... همه پیش علی آمدند و گفتند جهان بی امام است و از تو حق تر کسی نیست، هرچند گفتند اجابت نکرد، پس این غریبان گفتند اگر ما به شهر خویش بازشویم وامامی پدید نیامده باشد به جهان اندر فتنه ای خیزد که هرگز ننشیند. امیرالمؤمنین علی گفت یاران پیغمبر بیایند نخست مهاجر و انصار که ایشان ابتدا کنند. پس رفتند و یاران پیغمبر (ص ) را بیاوردند مگر طلحه و زبیر که ایشان پیغام فرستادند که هرکه مسلمانان پسندندما نیز پسندیم و چون مردمان بیعت کنند ما نیز بیعت کنیم . علی گفت نخست ایشان بیایند و خواست که برخیزد مردمان نگذاشتند پس مالک بن اشتر گفت من طلحه را بیاورم . چون مالک نزدیک طلحه شد گفت فردا مسلمانان را بی امام خواهی کردن و میان مسلمانان خلاف خواهی افکندن، مردمان بصره به در تو آمدند چرا بیعت نکردی، امروز که مردمان بر یک تن گرد آمده اند اختلاف کردن چراست . اگر با من بیرون نیایی سرت بردارم و حکم نیز همچنین گفت . زبیر و طلحه را بیاوردند پیش امیرالمؤمنین علی علیه السلام، پس علی گفت مرا اندر این کار رغبت نیست و مردمان بی امام مانده اند، هرکه از شما خواهید دست بازکنید تا من او را بیعت کنم و از همه تو ای طلحه دست باز کن تا ترا بیعت کنم . طلحه گفت معاذاﷲ آنجا که تو باشی و سابقیت تو من که باشم . پس مالک بن اشتر علی را گفت دست باز کن و نخستین کسی که دست بر دست علی نهاد طلحه بود و دست راست طلحه شل بود. مردی نامش حبیب بن ذویب گفت : یده شَلاّء بیعته لایتم ؛ گفت نخستین دستی شل ناقص بر دست وی آمد، هرگز این کار تمام نشود. پس زبیربن عوام بیعت کرد ویاران پیغمبر اکرم (ص ) و دیگر روز بیعت تمام شد و علی بر منبر شد و خطبه کرد و نماز آدینه کرد و آن روزبیست وپنجم بود از ذی الحجه ٔ سال سی وپنج از هجرت ...».<br />پس ازآنکه علی (ع ) عاملینی از جانب خود به شهرهای بصره وکوفه و یمن و مصر فرستاد و عمال خلیفه ٔ پیشین را معزول کرد مردم بصره و مصر سر به شورش برداشتند و «قیس از مصر نامه کرد به اختلاف اهل مصر و عثمان بن حنیف نامه کرد به اختلاف اهل بصره . علی علیه السلام طلحه و زبیر را بخواند و گفت این کار بشورید چه تدبیر کنم ؟ گفتند ما ترا گفتیم که ما را به بصره و کوفه فرست تا سپاه گرد کنیم نفرستادی اکنون این مردمان چشم همی دارند که ما با تو مخالف شویم، ما را به مکه فرست تا ماآنجا به عبادت مشغول شویم تا مردمان بدانند که ما را به هیچ چیز حاجت نیست و ترا منقاد شوند و کار از حرب گیر که جز به حرب میسر نشود. علی گفت تا بتوانم با این مردمان نیکویی کنم چون سود ندارد آنگاه حرب آخر کار است و طلحه و زبیر از بهر آن به مکه دستوری خواستند که خبر عایشه داشتند که او به مکه چه میکند و عایشه را با علی عصبیت بود از آنگاه که بر عایشه آن دروغ گفتند و پیغمبر (ص ) از آن تافته شد و امیرالمؤمنین آن حضرت را گفته بود در جهان زنان بسیار است اگر بر دلت یکی بد شد دیگری به زنی کن . عایشه از آنگاه با علی سخن نگفته بود و آنگاه که عایشه از مدینه برفت عثمان اندر حصار بود و عایشه با عثمان شوریده بودعثمان را گفت توبه کن و داد مسلمانان بده از خویش واز کارداران خویش و اگر نه از این کار بیرون آی تا خدای تعالی مسلمانان را بدلی دهد به از تو و ندانست که بیعت با علی کنند... ». چون عایشه از خلافت علی آگاه شد به خونخواهی عثمان برخاست، چه او خلافت را برای طلحه میخواست و طلحه و زبیر که از این واقعه آگاهی یافته بودند از راه بادیه خود را به مکه رسانیدند و با مردمان مکه که بخلاف علی گرد آمده بودند یکی شدند و بیعت بشکستند و خلق بسیاربر ایشان گرد آمدند و تدبیر رفتن شام کردند تا با معاویه یار شوند، عبداﷲبن عامر گفت به بصره باید شد که ما را بدانجا یاران بسیار است و به عایشه نیز تکلیف کردند که با ایشان همراه شود و مردمان را بر طلب خون عثمان تحریض کند.<br />بلعمی در ذکر خبر رفتن طلحه و زبیر و عایشه به بصره گوید: و عبداﷲبن عامر خواسته ای که داشت به طلحه و زبیر داد و یعلی بن منیه ششصد شتر بداد او را و او را اشتری بود نامش معسکر در یمن به هشتاد دینار خریده بود بداد تا هودج عایشه را بدان بنهادند و منادی بانگ کردند و هرکه را نفقه نبود بدادند و هزار مرد برفتند از ایشان ششصدبر اشتران بودند و چهارصد بر اسبان و علی میساخت که به مکه شود. چون از مکه برفتند ام الحرث بن حارث بن عبدالمطلب از مکه یکی را سوی علی فرستاد و نامه ای نوشت بدین خبر که ایشان به بصره رفتند. علی تافته شد و گفت اگر ایشان سوی بصره شوند کار تباه شود و از مدینه برفت که به راه پیش ایشان آید... بلعمی آنگاه در فصل «ذکر خبر گرفتن طلحه و زبیر بصریان را بخلاف علی » وپس از رسیدن طلحه و زبیر به بصره گوید: «پس دیگر روز عایشه سپاه برگرفت و به شهر اندر شد و میان بصره جایی است فراخ چون دشتی آن را مزید خوانند عایشه با لشکر آنجا بایستاد و او اندر هودج بود بر اشتر و سپاه گرداگرد او بودند و طلحه بر دست راست شتر بود و زبیر بر چپ او بود... پس طلحه سخن گفت و خطبه کرد و عثمان را یاد کرد و زبیر نیز همچنین بگفت، پس عایشه خطبه کرد و همچنین بگفت و مردمان بصره به دو گروه شدند...» و پس از آنکه سه روز میان ایشان و عثمان بن حنیف عامل علی بر بصره جنگ بود عایشه کس به عثمان فرستاد که «نه به خون ریختن و حرب آمده ایم، بدان آمده ایم تاصلح و نیکویی کنیم . عثمان گفت ما را با تو صلح نیست تا طلحه و زبیر را از خویشتن جدا نکنی که ایشان با امیرالمؤمنین علی بیعت کردند و بیعت بشکستند و ترا که حرم پیغمبر (ص ) بودی رسوای جهان کردند...» و پس از آنکه از مدینه به دستوری عایشه راجع به بیعت طلحه و زبیر به طوع یا به اکراه گواهی خواستند عثمان بن حنیف را موی روی بتراشیدند و نزد علی فرستادند «پس طلحه و زبیر بصره بگرفتند و در بیت المال بگشادند و دیگرروز به مزگت آمدند و بر منبر شدند و خطبه کردند و گفتند ای مردمان شما فضایل عثمان دانسته اید که هیچکس از وی نیازرده است و هر کس از کارداران او بیداد کرده اند ما خواستیم که بر او انکار کنیم، پس غوغا برخاست و او را بکشتند و ما امروز خون او طلب همی کنیم و کشندگان او بکشیم و طلحه و زبیر بر منبر بودند و هر دو پهلوی یکدیگر بودند و هرچه طلحه گفتی زبیر گفتی همچنین است . مردی از میان آن جمع گفت یا طلحه یا ابامحمد نامه های تو به ما از مدینه نه چنین همی آمد به حدیث عثمان که اکنون تو همی گویی . طلحه خجل شد. زبیر دیگرباره خطبه کرد و مدحها همی گفت عثمان را و علی را ذم همی کردند. پس مردی از بنی عبدالقیس برخاست و گفت شما با علی بیعت کردید اکنون عیب او همی کنید بی آنکه عیبی از او همی آید که تا بنشست هنوز حکمی نکرد که کسی بر او عیب کند. پس مردمان طلحه و زبیر شمشیر برگرفتند و از قبیله ٔ عبدالقیس مردم بسیار برخاستند و آهنگ ایشان کردند و فتنه برخاست . طلحه خواست که اندر آن خطبه علی را خلع کند و خود را به خلیفتی بنشاند. چون فتنه برخاست و طلحه و زبیر از منبر بزیر آمدند و به سرای سلطان شدند و گفتند طلب آن کسان کنید که به مدینه آمدند به کشتن عثمان و آنچه در بیت المال بود بر غوغا ببخشیدند و هر کسی بر یکدیگر غمز کردند که فلان بود و بدانجا همی شدند و او را همی کشتند. پس طلحه و زبیر به هر شهری نامه کردند که ما چنین کردیم به بصره شما نیز چنین کنید و خود به حرب علی خواهیم شدن و خون عثمان طلب کردن و آن مرد که در مسجد از بهر علی سخن گفته بود نامش حکیم بود او را همی جستند و نیافتند، پس از مردمان بیعت خواستند بر حرب امیرالمؤمنین و گفتند عثمان را علی کشت و طلحه و زبیر به مزگت شدند و از مردمان بیعت می ستانیدند حکیم از عبدالقیس با پسران و برادران و قبیله بیرون آمدند و اندربصره ایشان را همتا نبود به مردی و از در مزگت اندرآمدند و گفتند ای طلحه و زبیر بیعت علی بشکستید و درخدای تعالی عاصی شدید و قصد خاندان رسول (ص ) کردید وهمه مسلمانان همچون خویش مرتد همی کنید. طلحه گفت ای حکیم من ترا همی جویم و تو اندر بصره همی گردی و حکیم را قبیله ٔ بسیار بود نتوانستند او را گرفتن، از مزگت بیرون جست و مردی از لشکر طلحه شمشیر بزد بر زانوی حکیم و پای از پوست درآویخت، حکیم از جای خویش برجست و شمشیر بر گردن آن مرد زد و او را بفکند و طلحه و زبیر بیعت بصره تمام کردند و به هر شهری نامه کردند و سپاه خواستند... «ذکر خبر حرب جمل »... چون دو لشکر به یکدیگر رسیدند... «از پس سه روز امیرالمؤمنین علی بیرون آمد بر اسب نشسته و اندر میان لشکرگاه بایستاد و طلحه و زبیر را طلب کرد... هر دو بیرون آمدند و نزد یکدیگر ایستادند چنانکه سر اسبان ایشان به یکدیگر رسید. علی گفت ای برادران سپاه و سلاح راست کردید اگر خدای تعالی شما را از حرب من پرسد حجت توانید آوردن ؟ نه بیعت من اندر گردن دارید؟ و ما نه برادرانیم و مسلمانانیم ؟ و به یک جای از پس پیغمبر (ص ) نماز کردیم و با وی صحبت داشتیم ؟ اکنون چه کردم که خون من شما را حلال شد؟ طلحه گفت تو مردمان را گرد آوردی تا عثمان را بکشتند. امیرالمؤمنین علی گفت میان ماو شما جز خدای عز و جل نیست، تا دست به خدای برداریم و دعا کنیم و گوئیم یارب بر آنکس لعنت کن که به مرگ عثمان شاد شد ببینم که لعنت بر که آید. طلحه خاموش شد. علی گفت یا زبیر یاد داری آن روز که من نشسته بودم به مدینه به محلت بنی هاشم تو با پیغمبر بگذشتی وپیغمبر به من نگرید تو او را گفتی که هرگز از پسر ابوطالب دست بازندارم . پیغمبر (ص ) گفت روزی بود که توسپاه نزد او بری و تو ستمکار باشی . ای زبیر از خدای بترس . زبیر سر فرودافکند یک ساعت پس گفت یا علی مراگر این سخن یاد بودی هرگز اینجا نیامدمی، واﷲ که من با تو حرب نکنم و آب اندر چشم آورد و عنان بازگردانید و امیرالمؤمنین علی بازگردید و به لشکرگاه خویش آمد. زبیر سوی عایشه رفت و گفت من بازگردم و با علی حرب نکنم . برفت و به جای خویش شد. عایشه طلحه را و عبداﷲبن زبیر را بخواند و با ایشان حال زبیر بگفت . ایشان سوی زبیر آمدند و گفتند ما را خود اینجا نبایست آمدن اکنون بیامدیم و لشکر گرد کردیم و خلق را به حرب خواندیم و خون عثمان طلب کردیم و خلقی از بصره بکشتیم اکنون لشکر روی به روی آوردند و ما بازگردیم مردمان گویند این نه از بیم خدای است از بیم علی است و همی گفتند تا زبیر را سر برگردانیدند و او گفت سوگندرا چه کنم ؟ گفتند بنده آزاد کن . او را غلامی بود نامش مکحول، او را آزاد کرد و شاعری ایدون گفته :<br />و عین مکحول بصون دینه <br />کفارةاﷲ عن یمینه .<br />و مردمان بصره به سه گروه شدند گروهی با طلحه و زبیر بیعت کردند و گروهی سوی علی آمدند در شب و علی علیه السلام سپاه عرض کرد بیست هزارمرد و طلحه و زبیر عرض کردند سی هزار مرد هر دو به لشکرگاه آمدند و بر آن نهادند که صلح کنند و علی عبداﷲبن عباس را سوی طلحه و زبیر فرستاد و وعده ٔ صلح راست کردند که بامداد گرد آیند و صلح کنند و آن مردمان را که عثمان کشته بودند آن شب خواب نیامد و گرد آمدند و گفتند که صلح بر خون ما کنند، تدبیر ما آن است که حرب افکنیم میان این لشکر پیش از آنکه روز آید تاکس نداند که آن ما کردیم . چون سپیده دمید ایشان به سه گروه آمدند و برفتند و خویشتن را بر ایشان زدند ولشکر طلحه و زبیر بانگ کردند که برنشینید که ما دانستیم که پسر ابوطالب صلح نکند و روز روشن شد و حرب اندرگرفتند و آن مردمان که حرب اندرگرفتند چون مالک بن اشتر و عدی بن حاتم همه از لشکر بیرون رفته بودند پس سوی علی آمدند و گفتند ما را از لشکر بیرون کردی ازهوای طلحه و زبیر ما دانستیم که از ایشان جز غدر نیاید، امروز جانها پیش تو بدهیم و حمله کردند و حرب سخت شد و عایشه بفرمود تا هودج بر شتر نهادند و دو رویه برگستوان فروهشتند شتر را و هودج به زره اندر گرفتند و عایشه به هودج اندر نشست و شتر از پس حرب گاه بپای کرد و طلحه و زبیر در پیش لشکر بودند و حرب همی کردند و چون روز گرم گشت و حرب سخت شد.... و طلحه و زبیر هر دو به قلب اندر ایستادند و امیرالمؤمنین علی بانگ زد به لشکر اندر که شما را باد که حرب چگونه باید کردن که تا با شما حرب نکنند حرب مکنید و چون هزیمت شوند از پس مشوید و هرکه را جراحت رسد دیگرباره مزنید و نیت کشتن ایشان مکنید که خون و خواسته ٔ ایشان حلال نیست ولیکن چون آهنگ ایشان کنید بر آن کنید که از خویشتن بازدارید تا اگر کشته شوند خون به گردن شما نباشد. پس روز گرم شد و از هر دو گروه بسیار کشته شدند، پس به وقت نماز پیشین طلحه را تیری آمد و به پهلوی اسب اندر شد، طلحه آن تیر بیرون کشید و خون از وی همی رفت و او صبر اندر همی کرد اندر پری تا خون بسیار از وی برفت و سست شد، غلام را گفت مرا بازگردان . چون به در شهر آمد هرچه اندر تن او خون بود همه بیاسود و بر در شهر ویرانه ای بود او را بدان ویرانه برد و از اسب فرودآورد و طلحه هم آنگاه جان به حق تسلیم کرد و گور وی نیز امروز آنجاست ...». بگفته ٔ صاحب مجمل التواریخ و حدود العالم گور طلحه به بصره است و حمداﷲ مستوفی در نزهةالقلوب گوید: «و در آنجا <font color=\"DarkGreen\"><b>[ بصره ]</font></b> مزار طلحه و زبیر رضی اﷲ عنهما و آن را شهرت و شکوه تمام است و مزارات صحابه بسیار است ». طلحه مالی وافر داشت حاصل آن روزی هزار درم، چون وفات یافت چهار زن داشت و از ربع و ثمن هر یک را هشتاد هزار رسید. و رجوع به الاصابة ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩١</span> و عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٥</span> و عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span> و ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٧</span> شود.<br /></font></div>'),
(177459, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن عبیداﷲ التیمی، معروف به طلحةالفیاض . یکی از بخشندگان معروف است . وی را ابن الصعبة نیز گویند، چه صعبه دختر عبداﷲبن عماد الحضرمی و خواهر علأبن الحضرمی مادر اوست و خود صحابیه بوده است . رجوع به عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span> و ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> شود.<br /></font></div>'),
(177460, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن عبدالملک الایلی . محدث است . (سیرة عمربن عبدالعزیز ص <span class=\"hlight\" dir=\"rtl\">٣٧</span>).<br /></font></div>'),
(177461, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن عبداﷲبن عوف الزهری، معروف به طلحةالندی . یکی از بخشندگان متقدم است . زرکلی در الاعلام تولد وی را بسال <span class=\"hlight\" dir=\"rtl\">٢٥</span> و وفات او را بسال <span class=\"hlight\" dir=\"rtl\">٩٧</span> هَ . ق . هنگام اشتغال به شغل قضای مدینه آورده است . صاحب حبیب السیر گوید: در سنه ٔ مذکوره <font color=\"DarkGreen\"><b>[ یعنی <span class=\"hlight\" dir=\"rtl\">٩١</span> هَ . ق . و زمان سلیمان بن عبدالملک ]</font></b> طلحةبن عبداﷲبن عوف الزهری که به صفت زهادت و فقاهت اتصاف داشت و صحبت جمعی از اهل بدر را دریافته بود و قاضی مدینه بود ازعالم انتقال نمود. فرزدق را درباره ٔ طلحه مدحی است .رجوع به حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٧</span> و الاعلام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٠</span> شود.<br /></font></div>'),
(177462, 'طلحة', '<span class=\"hlight\">طلحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) ابن عبداﷲبن خلف بن السعد خزاعی . طلحةالطلحات و از بخشندگان بنام عرب در دوران اسلامی است . پدرش عبداﷲبن خلف مکنی به ابوطلحة در دیوان بصره شغل کاتبی عمروبن عثمان داشت و به روز جمل با عائشه بود و کشته شد. زرکلی در الاعلام گوید: طلحه اجود اهل بصره به روزگار خویش بود و به بنی امیه تمایلی داشت و وی را اکرام میکردند و گوید چشم وی به سمرقند از دست برفت . و حکومت وی بر سیستان از جانب زیادبن سلمة بوده است و او در حالی که والی سیستان بود درگذشت . و صاحب تاریخ سیستان شرح حکومت وی بدینگونه آرد: ...یزیدبن معاویه سلم بن زیادبن ابیه را به خراسان فرستاد و سیستان <font color=\"DarkGreen\"><b>[ و ]</font></b> سلم طلحةبن عبداﷲبن خلف الخزاعی که طلحةالطلحات گفتندی به سیستان فرستاد و سوی یزیدبن معاویه کس فرستاد و نامه کرد و دستوری خواست به فرستادن طلحة به سیستان . یزید عهد فرستاد طلحة را به سیستان و سلم عهد بدخوله از پس وی بفرستاد و هنوز به راه اندر بود که آن عهد به وی رسید، فرمان داده بود که برادر مرا به عهد بازخر. آمدن طلحةالطلحات به سیستان و عمر برادر او صاحب جیش بود. طلحة به سیستان آمد و برادرش عمر صاحب الجیش او بود و صاحب شُرط او مالک بن اوس الازدی و رسول فرستاد و بوعبیده ٔ زیاد را و اسیران که با او بودند به پانصد هزار درم بازخرید، باز به بست رفت و کار آن دیار بر نظام کرد و باز سیستان آمد. و مردی بزرگوار نیکوسیرت باخرد بود و هیچ کسی او را اندر شجاعت و سخاوت نظیرنبود و از سخاوت و عدل خویش چنان گشت که مردمان سیستان همه سوگند به جان او یاد کردندی از محبت او که به دلها جای گیر افتاد و چنان بود که شاعر گوید: شعر<br />یا طلح انت اخوالندی و عقیده <br />فبحیث بِت َّ من المنازل باتا<br />شهد الانام صغیرهم و کبیرهم <br />اَن الندی اِن ْ مات طلحة ماتا.<br />و به سخاوت بدان جایگاه بود که بوالاسد یکی بیامد قصد او را به سیستان و روزی چند به درگاه او بماند که او را نگفتند، آخر این بیتها بنوشت و پیش او فرستاد. شعر<br />ورد السقاة المعطشون فانهلوا<br />ریاً و طاب لهم لدیک المکرع <br />و وردت بحرک طامیاً متدفقاً<br />فرددت دلوی شنها یتقعقع<br />و اراک تقطر جانباً عن جانب <br />و محل بیتی عن سمائک بلقع.<br />چون خط و شعر او بدید خجل ماند و اندر وقت او را پیش خویش آورد و عذر خواست و دو یاقوت سرخ گرانمایه به دست همی گردانید، گفت یا بوالاسد بیست هزار درم دوستر داری یا از این یکی ؟ گفت من یک پاره سنگ اختیار نکنم، تا بیست هزار درم . بیست هزار درم را بیاورد و غلام خویش را گفت برگیر، پس گفت اگر امیر بیند یک پاره فرا من دهد تا بینم، هر دو پاره زی وی انداخت و گفت مردان را فریب نکنند بدین، به صد هزار درم خریده ام و بوالاسد به عراق برد و به صد و بیست هزار درم بداد. آمدن اسود سعید به سیستان . باز یزیدبن معاویه اسودبن سعید را به سیستان فرستاد اندر آخر سنه ٔ اثنی و ستین (<span class=\"hlight\" dir=\"rtl\">٦٢</span> هَ . ق .). چون روزی چند ببود، اندر عقب، عبداﷲبن طلحةالطلحات را به سیستان فرستاد اندر سنه ٔ ثلث و ستین (<span class=\"hlight\" dir=\"rtl\">٦٣</span> هَ . ق .). آمدن عبداﷲ طلحه به سیستان . و یک سال به سیستان بود، باز پدر وی <font color=\"DarkGreen\"><b>[ طلحه ]</font></b> را به سیستان فرستاد اندر سنه ٔ اربع و ستین (<span class=\"hlight\" dir=\"rtl\">٦٤</span> هَ . ق .) و او پسر خویش را عبداﷲ را خلیفت کرد که مردمان از نیکوئی سیرت وی شکر بسیار کردند و به سیستان ببود<font color=\"DarkGreen\"><b>[ یعنی خود طلحه ]</font></b> تا گاه وفات وی، پس وصیت کرد پسرخویش را که مرا هم اینجا دفن کن که این مردمان مرا دوست دارند تا ذکر من اینجا بماند میان دوستان من و مرا سالها یاد همی کنند که مردم چون او را همی یاد کنند مرده نباشد و آن سخن که کسی گوید که هزار سال ترا بقا باد آن نه بر خطا گویند، بقاء مرد ذکر نیکوئی اوست و من امید میدارم که از آن جمله باشم اندر این شهر بزرگوار و این بزرگان و آزادمردان . پس چون فرمان یافت پسرش فرمان او را کار بست و او را به تهل مهاجر دفن کرد و اکنون گور اومعروف است . شاعر گوید، و هو عبداﷲبن قیس الرقیات :<br />رحم اﷲ اعظماًدفنوها<br />بسجستان طلحةالطلحات .<br /> <font color=\"Red\">(تاریخ سیستان صص <span class=\"hlight\" dir=\"rtl\">١٠١</span>-<span class=\"hlight\" dir=\"rtl\">١٠٣</span>).</font><br />صاحب عقدالفرید گوید: اجواد اهل اسلام یازده تن بودند در عصری واحد و آنان را نظیری پیش از آن و پس از آن نبوده است، اما بخشندگان حجاز سه تن بودند در یک زمان : عبیداﷲبن العباس و عبداﷲبن جعفر و سعیدبن العاص و بخشندگان بصره پنج تن بودند به یک روزگار: عبداﷲبن عامربن کریز و عبیداﷲبن ابی بکرة مولی رسول اﷲ صلی اﷲ علیه و سلم و مسلم بن زیاد و عبیداﷲبن معمر القرشی ثم التیمی و طلحةالطلحات و هو طلحةبن عبداﷲبن خلف الخزاعی و شاعر درباره ٔ وی گوید:<br />نضر اﷲ اعظماً دفنوها<br />بسجستان طلحةالطلحات .<br />و بخشندگان کوفه سه تن بودند به یک زمان : عتاب بن ورقاء الریاحی و اسمأبن خارجة الفزاری و عکرمةبن ربعی الفیاض . طلحه ای را طلحةالطلحات بدان جهت گویند که مادرش صفیه دختر حارث بن طلحةبن ابی طلحةبن عبدمناف است و پیغمبر اکرم به روز احد طلحةبن عبیداﷲ را طلحةالخیر و به روز غزوه ٔ ذات العسرة طلحة الفیاض و به روز حنین طلحة الجواد نامید. و رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٤</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٣</span> و ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٣</span> و <span class=\"hlight\" dir=\"rtl\">٢٥٥</span> و ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٥</span> و <span class=\"hlight\" dir=\"rtl\">١٠٦</span> و مجمل التواریخ ص <span class=\"hlight\" dir=\"rtl\">٢٩٦</span> و تاریخ سیستان صص <span class=\"hlight\" dir=\"rtl\">١٠١</span> - <span class=\"hlight\" dir=\"rtl\">١٠٥</span> شود.<br /></font></div>'),
(177463, 'طلحتان', '<span class=\"hlight\">طلحتان .</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) از اصطلاحات مردم بصره این است که بنام کسی که قریه ای به وی نسبت میدهند الف و نونی می افزایند مانندطلحتان . و آن نهری است که به طلحةبن ابی رافع مولی طلحةبن عبیداﷲ منسوب است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٠</span>).<br /></font></div>'),
(177464, 'طلحف', '<span class=\"hlight\">طلحف .</span> <font color=\"DarkGreen\"><b>[ طِل ْ ل َ ]</font></b> (ع ص ) زدن سخت . لغتی است در طلحیف . (منتهی الارب ). رجوع به طلحیف شود.<br /></font></div>'),
(177465, 'طلحف', '<span class=\"hlight\">طلحف .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع ص ) زدن سخت . طلحیف . <BR><font color=\"Blue\">◄</font> گرسنگی سخت . (منتهی الارب ).<br /></font></div>'),
(177466, 'طلحفی', '<span class=\"hlight\">طلحفی .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ فا ]</font></b> (ع ص ) زدن سخت . لغتی است در طلحیف . (منتهی الارب ). رجوع به طلحیف شود.<br /></font></div>'),
(177467, 'طلحند', '<span class=\"hlight\">طلحند.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) پسر مای شاهزاده ٔ هندی . پدر وی مای برادر جمهور پادشاه هندوان بوده که بگفته ٔفردوسی از کشمیر تا مرز چین حکم او را گردن نهاده داشتند و به سندل نشستگاه داشت . مای پیش از رسیدن به سلطنت در دنبر مقر حکمرانی داشت و پس از جمهور جانشین وی گردید و زن برادر را نیز به عقد نکاح خویش آوردو از پیوند طلحند متولد گردید. پس از مای طلحند با برادر اُمی و پسرعم خویش گو بر سر جانشینی نبرد کرد و در هنگامه ٔ رزم بالای پیل جان سپرد. مادر طلحند از مرگ فرزند و فراق وی بیقرار شد و شکیب از کف بداد تاآنجا که گروهی از حکمای هند وضع شطرنج کردند و در مجلس وی باختند تا این زن بدان سرگرم گردد و شغل دلش برخیزد و اندوه مرگ فرزند از یاد ببرد. صاحب آنندراج گوید: صعةبن داهر که از حکمای هند بود وضع شطرنج کرد و صاحب برهان نام حکیم هندی مصه بن داهر گوید و دیگری نذربن داهر یا مصه نگاشته . فردوسی داستان طلحند وجنگ وی و وضع شطرنج را بدینگونه منظوم ساخته است :<br />چنین گفت فرزانه شاهوی پیر<br />ز شاهوی پیراین سخن یاد گیر<br />که در هند مردی سرافراز بود<br />که با گنج و با لشکر و ساز بود<br />خنیده به هر جای و جمهور نام <br />به مردی فزون کرده از فور نام <br />همان پادشا بود بر هندوان <br />خردمند و بینا و روشن روان <br />ورا بودکشمیر تا مرز چین <br />بر او خواندندی مهان آفرین <br />به مردی جهان را گرفته به دست <br />ورا سندلی بود جای نشست ...<br />زنی بودش اندرخور وهوشمند<br />هنرمند و بادانش و بی گزند<br />پسر زاد از آن شاه در شب یکی <br />که پیدا نبودش ز ماه اندکی <br />پدر چون بدید آن جهاندار نو<br />بفرمود تا نام کردند گو<br />بر این برنیامد بسی روزگار<br />که بیمار شد ناگهان شهریار<br />به کدبانو اندرز کرد و بمرد<br />جهانی پر از داد گو را سپرد<br />ز خردی نشایست گو تخت را<br />نه تاج و کمر بستن سخت را<br />سران را همه سر پر از گرد بود<br />ز جمهور دلشان پر از درد بود<br />سپاهی و شهری شدند انجمن <br />زن و کودک و مرد شد رایزن <br />که این خرد کودک نداند سپاه <br />نه داد و نه خشم و نه تخت و کلاه <br />همه پادشاهی شود پرگزند<br />اگر شهریاری نباشد بلند<br />یکی بد برادر مر آن شاه را<br />خردمند و شایسته ٔ گاه را<br />کجا نام آن نامور مای بود<br />به دنبر نشسته بت آرای بود<br />جهاندیدگان یک بیک شاه جوی <br />ز سندل به دنبر نهادند روی <br />بزرگان کشمیرتا مرز چین <br />به شاهی بر او خواندند آفرین <br />ز دنبر بیامد سرافراز مای <br />به تخت کیان اندرآورد پای <br />همان تاج جمهور بر سرنهاد<br />به داد و به بخشش سر اندرنهاد<br />چو بر گاه شد مام گو را بخواست <br />بپرورد و با جان همی داشت راست <br />پریچهره آبستن آمد ز مای <br />پسر زاد این نامور کدخدای <br />ورا پادشا نام طلحند کرد<br />روان را پر از مهرفرزند کرد<br />دوساله شد این خرد و گو هفت سال <br />دل آور گوی بود با فر و یال <br />بدان چند گه مای بیمار گشت <br />دل جفت پر درد و تیمار گشت <br />دو هفته برآمد بزاری بمرد<br />برفت و جهان دیگری را سپرد<br />همه سندلی خوار و گریان شدند<br />ز دود دل مای بریان شدند<br />نشستند یک ماه با سوک شاه <br />سر ماه یکسر بیامد سپاه <br />همه نامداران و گردان شهر<br />هر آنکس که او از خرد داشت بهر<br />سخن رفت هر گونه بر انجمن <br />چنین گفت فرزانه با رایزن <br />که این زن که او جفت جمهور بود<br />همیشه ز کردار بد دور بود<br />همه راستی خواستی زین دو شوی <br />نبود ایچ تا بود جز دادجوی ...<br />همان به که این زن بود شهریار<br />که این ماند از مهتران یادگار<br />به گفتار او رام گشت انجمن <br />فرستاده شد نزد آن پاک زن <br />که تخت دو فرزند خود را بگیر<br />فزاینده کاری است این ناگزیر<br />چو فرزند گردد سزاوار گاه <br />بدو ده بزرگی و گنج و سپاه <br />به گفتار ایشان زن نیک بخت <br />بیفروخت تاج و بیاراست تخت <br />فزون کرد پرهیز و خوبی و داد<br />همه پادشاهی بدو گشت شاد<br />بدیشان سپرد آن دو فرزند را<br />دو مهترنژاد خردمند را<br />نبودی از ایشان جدا یک زمان <br />به دیدار ایشان بُدی شادمان <br />چو نیرو گرفتند و دانا شدند<br />به هردانشی بر توانا شدند<br />زمان تا زمان یک ز دیگر جدا<br />شدندی بر مادر پارسا<br />که از ما کدام است شایسته تر<br />به دل برتر و نیز بایسته تر<br />چنین گفت مادر به هر دو پسر<br />که تا از شما با که یابم هنر<br />هنرمندی و رای و پرهیز و دین <br />زبان چرب و جوینده ٔ آفرین <br />چو دارید هر دو به شاهی نژاد<br />خرد باید و شرم و پرهیز و داد<br />چو تنها شدی سوی مادر یکی <br />چنین هم سخن راندی اندکی <br />که از ما دوفرزند کشور کراست <br />به شاهی و این تخت و افسر کراست <br />بدین مام گفتی که تخت آن ِ تست <br />خردمندی و رای و بخت آن ِ تست <br />به دیگر پسر هم بدینسان سخن <br />همی راندی تا سخن شد کهن <br />دل هر یکی شاد کردی به تخت <br />به گنج و سپاه وبه نام و به بخت <br />رسیدند هر دو به مردی به جای <br />بدآموز شد هر دو را رهنمای <br />ز رشک اوفتادند هر دو به رنج <br />برآشوفتند از پی تاج و گنج <br />همه شهرو لشکر به دو نیم گشت <br />دل نیک مردان پر از بیم گشت <br />ز گفت بدآموز جوشان شدند<br />بنزدیک مادر خروشان شدند<br />بگفتند کز ماکه زیباتر است <br />که بر نیک و بر بد شکیباتر است <br />چنین پاسخ آورد فرزانه زن <br />که با موبدی یکدل و رایزن <br />بباید نشستن شما را نخست <br />به آرام و با کام فرجام جست <br />وزان پس گزیده بزرگان شهر<br />هرآنکس که او دارد از رای بهر<br />یکایک بپرسید با رهنمون <br />نه خوب است گرمی به کار اندرون <br />کسی کو بجوید همی تاج و گاه <br />خرد باید و رای وگنج و سپاه <br />چو بیدادگر پادشاهی کند<br />جهان پر ز گرم و تباهی کند<br />به مادر چنین گفت فرزانه گو<br />کز این پرسش اندر میانه نرو<br />اگر کشور از من نگیرد فروغ <br />بگوی و مکن هیچ رای دروغ <br />به طلحند بسپار تخت و کلاه <br />من او را یکی کهترم نیکخواه <br />دگر من به سال و خرد مهترم <br />هم از پشت جمهور گندآورم <br />بدو گوی تا از پی تاج و تخت <br />نگیرد به بیدانشی کار سخت <br />بدو گفت مادر که تندی مکن <br />بر اندازه باید که رانی سخن <br />هرآنکس که بر تخت شاهی نشست <br />میان بسته باید گشاده دو دست <br />نگه داشتن پاک جان از بدی <br />به دانش سپردن ره بخردی <br />هم از دشمن آژیر بودن به جنگ <br />نگه داشتن بهره ٔ نام و ننگ ...<br />از این دودمان شاه جمهور بود<br />که رایش ز کردار بد دور بود<br />نه هنگام بُد مردن او را بمرد<br />جهان را به کهتر برادر سپرد<br />ز دنبر بیامد سرافراز مای <br />جوان بود بینادل و پاکرای <br />بیامد به تخت مهی برنشست <br />میان بسته بود و گشاده دو دست <br />مرا خواست انباز گشتیم و جفت <br />بدان تا بماند سخن در نهفت <br />پس اکنون که مهتر برادر توئی <br />به سال و خرد نیز برتر توئی <br />یکی از شما گر کنم من گزین <br />دگر گردد از من پر از درد و کین <br />مریزید خون از پی تاج و گنج <br />که بر کس نماند سرای سپنج <br />ز مادر چو بشنید طلحند پند<br />نیامدش گفتار او سودمند<br />چنین گفت زان پس به طلحند گو<br />که ای نیکدل مرد بازار نو<br />شنیدی که جمهور چندی ز مای <br />سرافرازتر بُد به سال و به رای <br />پدرْت آن گرانمایه ٔ نیکخوی <br />نکرد ایچ از تخت او آرزوی <br />نه ننگ آمدش هرگز از کهتری <br />نجست ایچ بر مهتران مهتری <br />نگر تا پسندد چنین دادگر<br />که من پیش کهتر ببندم کمر<br />نگفتست مادر سخن جز بداد<br />ترا دل چرا شد ز بیداد شاد<br />ز لشکر بخوانیم چندی مهان <br />خردمند و برگشته گرد جهان ...<br />بیامد دو فرزانه ٔ رهنمای <br />میانشان همی رفت هر گونه رای ...<br />همی این بر آن برزدی آن بر این <br />چنین تا دو مهتر گرفتند کین <br />نهادند از آن پس به ایوان دو تخت <br />نشسته بر او این دو فیروزبخت <br />دلاور دو فرزانه بر دست راست <br />همی هر یکی از جهان بهره خواست <br />گرانمایگان را همه خواندند<br />به ایوان چپ و راست بنشاندند<br />زبان برگشادند فرزانگان <br />که ای سرفرازان و مردانگان <br />از این نامداران فرخ نژاد<br />که دارید رسم پدرْشان به یاد<br />که خواهید بر خویشتن پادشا<br />که دارید از این دو جوان پارسا...<br />یکی ز انجمن سر برآورد راست <br />به آوا سخن گفت و برپای خاست <br />که از ما دو دستور و دو شهریار<br />چه یاریم گفتن که آید بکار<br />بسازیم فردا یکی انجمن <br />بگوییم یک با دگر تن بتن <br />وزان پس فرستیم یک یک پیام <br />مگرشهریاران بیابند کام <br />برفتند از ایوان ژکان و دژم <br />دهان پر ز باد و روان پر ز غم <br />یکی را ز گردان به گو بود رای <br />دگر سوی طلحند بُدرهنمای <br />یکی سوی طلحند پیغام کرد<br />زبان را ز گو پر ز دشنام کرد<br />دگر سوی گو رفت با گرز و تیغ<br />که از شاه من جان ندارم دریغ<br />پرآشوب شد کشور سندلی <br />بدان نیکخواهی و آن یکدلی <br />خردمند گوید که در یک سرای <br />چو فرمان دو گردد نماند بجای <br />پس آگاهی آمد به طلحند و گو<br />که هر برزنی را یکی پیشرو<br />همه شهر ویران کنند از هوا<br />نباید که دارند شاهان روا<br />ببودند از آن آگهی پرهراس <br />همی داشتندی شب و روز پاس <br />چنان بد که روزی دو شاه جوان <br />برفتند بی لشکر و پهلوان <br />زبان برگشادند یک با دگر<br />پرآژنگ روی و پر از جنگ سر<br />گو نامبردار شد پرخروش <br />از آن گفتها اندرآمد به جوش <br />به طلحند گفت ای برادر مکن <br />کز اندازه بگذشت ما را سخن <br />به بیهوده بر خیره چیزی مجوی <br />که فرزانگان آن نبینند روی ...<br />مکن ناسزا تخت شاهی مجوی <br />مکن روی کشور پر از گفتگوی <br />چنین داد طلحند پاسخ که بس <br />به افسون بزرگی نجستست کس <br />من این تاج و تخت از پدر یافتم <br />ز تخمی که او کشت بر یافتم <br />همی پادشاهی و گنج و سپاه <br />از این پس به شمشیر دارم نگاه ...<br />سرانشان پر از جنگ بازآمدند<br />به شهر اندرون رزم ساز آمدند...<br />نخستین بیاراست طلحند جنگ <br />نبودش به جنگ از دلیری درنگ <br />در گنجهای پدر برگشاد<br />سپه را همه ترک و جوشن بداد...<br />بپوشید طلحند جوشن نخست <br />به خون ریختن چنگها را بشست <br />بیاورد گو نیز خفتان و خود<br />همی داد جان پدر را درود<br />بدان تیزی از جای برخاستند<br />همه پشت پیلان بیاراستند<br />نهادند بر کوهه ٔ پیل زین <br />تو گفتی همی جنگ جوید زمین ...<br />به لشکرگه آمد دو شاه جوان <br />همه پیش بیشی نهاده روان ...<br />نگه کرد گو اندر آن دشت جنگ <br />هوا دید چون پشت جنگی پلنگ ...<br />به طلحند بر چند جانش بسوخت <br />خرد هم لب آز او بربدوخت <br />گزین کرد مردی سخنگوی گو<br />کز آن مهتران او بُدی پیشرو<br />که رو پیش طلحند و او را بگوی <br />که بیداد جنگ برادر مجوی <br />که هر خون که آید به کین ریخته <br />تو باشی بدان گیتی آویخته <br />یکی گوش بگشای بر پند گو<br />به گفتار بدگوی غره مشو<br />نباید که از ما بدین کارزار<br />نکوهش بود در جهان یادگار...<br />دل من بدین آشتی شاد کن <br />ز وام خرد گردن آزاد کن <br />به پیمان از این مرز تا مرزچین <br />ترا باد چندانکه خواهی زمین <br />همه مهر با جان برابر کنیم <br />ترا بر سر خویش افسر کنیم ...<br />فرستاده چون پیش طلحند شد<br />به پیغام شاه ازدر پند شد<br />چنین داد پاسخ که گو را بگوی <br />که در جنگ چندین بهانه مجوی <br />برادر نخوانم ترا من نه دوست <br />نه مغزی تو از دوده ٔ ما نه پوست <br />همی پادشاهی تو ویران کنی <br />چو آهنگ جنگ دلیران کنی <br />گنهکارهم پیش یزدان توئی <br />که بدنام و بدگوهر و بدخوئی <br />و دیگر که گفتی ببخشیم تاج <br />همین مرز باارز و این تخت عاج <br />هرآنگه که تو شهریاری کنی <br />مرا مرز بخشی و یاری کنی <br />نخواهم که جان باشد اندر تنم <br />اگر چشم بر تاج و تخت افکنم ...<br />غمی شد دل گو چو پاسخ شنید<br />که طلحند را هیچ دانش ندید...<br />ز درد برادر پر از آب روی <br />گزین کرد نیک اختری چرب گوی <br />بدو گفت رو سوی طلحند شو<br />بگویش که پر درد و رنج است گو...<br />اگرچند تندی و جنگ آوری <br />هم از گردش چرخ برنگذری <br />همه گرد بر گرد ما دشمن است <br />جهانی پر از مردم ریمن است ...<br />چه گویند کز بهر تخت و کلاه <br />چرا ساخت طلحند و گو رزمگاه ...<br />ز لشکر گر آئی بنزدیک من <br />درخشان کنی جان تاریک من ...<br />هم از دست من کشور و مهر و تاج <br />بیابی همان یاره و تخت عاج <br />ز مهتر برادر ترا ننگ نیست <br />مرا آرزو جستن جنگ نیست <br />فرستاده آمد چو آب روان <br />بنزدیک طلحند تیره روان <br />بگفت آنچه گو گفت و بفزود نیز<br />ز شاهی و از گنج و دینار و چیز<br />چو بشنید طلحند گفتار اوی <br />خردمندی و رای بیدار اوی <br />از آن کآسمان را دگر بود راز<br />به گفت ِ برادر نیامد فراز<br />چنین داد پاسخ که گو را بگوی <br />که هرگز نباشی بجزچاره جوی ...<br />از اندیشه دوری و از تاج و تخت <br />نخواند ترا دانشی نیک بخت <br />فرستاده آمد لبان پر ز باد<br />همه پاسخ پادشا کرد یاد<br />چنین تا شب تیره بنمود روی <br />فرستاده آمد همی زین بدوی ...<br />چو برزد سر از برج شیر آفتاب <br />زمین شد بکردار دریای آب ...<br />برآمد خروشیدن کرّنای <br />هم آوای کوس از دو پرده سرای ...<br />دو شاه سرافراز در قلبگاه <br />دو دستور فرزانه بر دست شاه ...<br />چو پیل ژیان شاهزاده ٔ دو شاه <br />براندند هر دو ز قلب سپاه <br />خروشی برآمد ز طلحند و گو<br />که ازباد ژوبین من دور شو<br />به جنگ برادر مکن دست پیش <br />نگه دار ازآزار من جان خویش <br />همی این بدان گفت و هم آن بدین <br />چو دریای خون شد سراسر زمین ...<br />بسی خواستند از یلان زینهار<br />بسی کشته شد در دم کارزار<br />پراکنده گشتند لشکر همه <br />رمه بی شبان شد شبان بی رمه <br />چو طلحند بر پیل تنها بماند<br />گو او را به آواز چندی بخواند<br />که رو ای برادر به ایوان خویش <br />نگه کن به ایوان و دیوان خویش <br />نیابی همانا بسی زنده تن <br />از این تیغزن نامدار انجمن <br />همه خوب کاری ز یزدان شناس <br />وز او دار تا زنده باشی سپاس <br />که زنده برفتی تو از دشت جنگ <br />نه هنگام رای است و روز درنگ <br />چو بشنید طلحند آواز اوی <br />شد از ننگ پیچان و پرآب روی <br />به مَرغ آمد از دشت آوردگاه <br />فرازآمدندش ز هر سوسپاه ...<br />ز درگاه طلحند برشد خروش <br />ز لشکر همه کشور آمد به جوش <br />سپه را همه سوی دریا کشید<br />وزان سو سپاه گو آمد پدید<br />برابر فرودآمدند آن دو شاه <br />که بودند یک با دگر کینه خواه ...<br />دو شاه گرانمایه پر درد و کین <br />نهادند بر پشت پیلان دو زین ...<br />هوا شد ز گرد سپاه آبنوس <br />ز نالیدن بوق و آوای کوس <br />ز زخم تبرزین و کوپال و تیغ<br />ز دریا برآمد یکی سرخ میغ<br />چو در پیش خورشید دامن کشید<br />چنان شدکه کس نیز کس را ندید...<br />ز دریا همی خاست از باد موج <br />سپاه اندرآمد همی فوج فوج <br />نگه کرد طلحند از پشت پیل <br />زمین دید برسان دریای نیل <br />همان باد بر سوی طلحند گشت <br />به آب و به نان آرزومند گشت <br />ز باد و ز خورشید و شمشیر تیز<br />نه آرام دید و نه راه گریز<br />برآن زین زرین بخفت و بمرد<br />همه کشور هند گو را سپرد...<br />ز قلب سپه چون نگه کرد گو<br />ندید آن درفش سپهدار نو<br />سواری فرستاد تا پشت پیل <br />بجوید بگردد همی میل میل <br />کجا شد که او نیست جویا نبرد<br />مگر چشم من تیره تر کرد گرد<br />سوار آمد وسربسر بنگرید<br />درفش سر نامداران ندید...<br />سپهبد فرودآمد از پشت پیل <br />پیاده همی رفت گریان دو میل <br />برادر چو طلحند را مرده یافت <br />رخ لشکر از درد پژمرده یافت ...<br />همی گفت زار ای نبرده جوان <br />برفتی پر از درد و خسته روان <br />ترا گردش اختر بد بکشت <br />وگرنه نزد بر تو بادی درشت <br />به چربی بسی رانده ام با تو پند<br />نیامد ترا پند من سودمند<br />چو فرزانه ٔ گو بدانجا رسید<br />جهانجوی طلحند رامرده دید<br />خروشان بغلطید در پیش گو<br />همی گفت زار ای جهاندار نو<br />از این زاری و سوگواری چه سود<br />چنین رفت و این بودنی کار بود<br />سپاس از جهان آفرینت یکی است <br />که طلحند بر دست تو کشته نیست ...<br />کنون کار طلحند بر باد گشت <br />به نادانی و تیزی اندرگذشت <br />سپاه است چندین پر از درد و خشم <br />سراسر همه بر تو دارند چشم <br />بیارام و ما را دل آرام ده <br />خرد را به آرام دل کام ده ...<br />ز دانا خردمند بشنید پند<br />خروشی ز لشکر برآمد بلند<br />که ای نامداران و گردان شاه <br />مباشید یک تن بدین رزمگاه <br />همه پاک در زینهار منید<br />وزان برمنش یادگار منید<br />پس آنگاه دانندگان را بخواند<br />به مژگان همه خون دل برفشاند<br />یکی تنگ تابوت کردش ز عاج <br />ز زرّ و ز پیروزه و چوب ساج ...<br />بپوشید رویش به دیبای سند<br />شد آن نامور نامبردار هند...<br />چو شاهان گزیدند جای نبرد<br />بشد مادر از خواب و آرام و خورد<br />همیشه به ره دیده بان داشتی <br />به تلخی همه روز بگذاشتی <br />چو از راه برخاست گرد سپاه <br />نگه کرد بینادل از دیده گاه <br />ز بالا درفش گو آمد پدید<br />همه روی کشور سپه گسترید<br />همی دیده بان بنگرید از دو میل <br />که بیند مگر تاج طلحند و پیل <br />نیامد پدید از میان سپاه <br />سواری برافکند از آن دیده گاه <br />که لشکر گذر کرد از این سوی کوه <br />گو و هرکه بودند با او گروه <br />نه طلحند پیدا نه پیل و درفش <br />نه آن نامداران زرینه کفش <br />ز مژگان فروریخت خون مادرش <br />فراوان به دیوار برزد سرش <br />وزان پس چو آمد بدو آگهی <br />که تیره شد آن فر شاهنشهی <br />جهانجوی طلحند بر زین بمرد<br />سر گاه شاهیش گو را سپرد<br />به ایوان او شد دوان مادرش <br />به خون اندرون غرق گشته سرش <br />همه جامه بدرید و رخ را بکند<br />به ایوان و گنج آتش اندرفکند<br />همی تاج و تخت بزرگی بسوخت <br />وزان پس بلند آتشی برفروخت <br />که سوزد تنش را به آیین هند<br />وزان سوک پیدا کند دین هند<br />چو از مادر آگاهی آمد به گو<br />برانگیخت آن باره ٔ تیزرو<br />بیامد ورا تنگ در بر گرفت <br />پر از خون مژه خواهش اندرگرفت <br />که ای مادر مهربان گوش دار<br />که ما بیگناهیم ازاین کارزار...<br />بدو گفت مادر که ای بدکنش <br />ز چرخ بلند آیدت سرزنش <br />برادر کشی از پی تاج و تخت <br />نخواند ترا نیک دل نیک بخت <br />چنین داد پاسخ که ای مهربان <br />نشاید که بر من شوی بدگمان <br />بیارام تا من ترا رزمگاه <br />نمایم همان کار شاه و سپاه ...<br />اگر چون نمایم نگردی تو رام <br />به دادار دارنده کو راست کام <br />که سوزم به آتش تن خویش را<br />کنم شاد جان بداندیش را<br />چو بشنید مادر سخنهای گو<br />دریغ آمدش برز و بالای گو<br />که سوزد به آتش دلیری جوان <br />هنر نابسوده تنش را روان <br />بدو گفت مادر که بنمای راه <br />که چون مُرد بر پیل طلحند شاه <br />مگر بر من این آشکارا شود<br />پرآتش دلم بر مدارا شود<br />پر از درد شد گو بر ایوان خویش <br />جهاندیده فرزانه را خواند پیش <br />نشستند هر دو بهم رایزن <br />گو و مرد فرزانه بی انجمن <br />بدو گفت فرزانه ٔ نیکخو<br />نگردد به ما راست این آرزو<br />ز هر جا بخوانیم برنا و پیر<br />کجا نامداری بود تیزویر...<br />(بازی شطرنج ساختن از بهر مادر طلحند)<br />سواران به هر سو برافکند گو<br />به جایی که بد موبدی پیشرو<br />سراسر به درگاه شاه آمدند<br />بدان نامور بارگاه آمدند<br />جهاندار بنشست با هندوان <br />بزرگان دانا و روشن روان <br />صفت کرد فرزانه آن رزمگاه <br />که چون رفت پیکار شاه و سپاه <br />ز دریا و از کنده و آبگیر<br />یکایک بگفتند با تیزویر<br />نخفتند از ایشان یکی تیره شب <br />نه بر یکدگر برگشادند لب <br />ز میدان چو برخاست آوای کوس <br />جهاندیدگان خواستند آبنوس <br />یکی تخت کردند از آن چارسو<br />دو مرد گرانمایه ٔ نیکخو<br />همانند آن کنده و رزمگاه <br />به روی اندر آورده روی سپاه <br />بر آن تخت صد خانه کرده نگار<br />خرامیدن لشکر و شهریار<br />پس آنگه دو لشکر ز ساج و ز عاج <br />دو شاه سرافراز با فر و تاج <br />پیاده پدید اندرون با سوار<br />دو صف کرده آرایش کارزار...<br />چو دیدی کسی شاه را در نبرد<br />به آواز گفتی که ای شاه برد<br />شه از خانه ٔ خویش برتر شدی <br />همی تا بر او جای تنگ آمدی <br />وزان پس ببستند بر شاه راه <br />رخ و اسپ و فرزین و پیل و سپاه <br />نگه کرد گرد اندرون چارسو<br />سپه دید افکنده چین در برو<br />ز آب و ز کنده بر او بسته راه <br />چپ و راست پیش و پس اندر سپاه <br />شه از رنج و از تشنگی شاه مات <br />چنین یافت از چرخ گردان برات <br />زشطرنج طلحند بود آرزوی <br />گو آن شاه آزاده ٔ نیکخوی <br />همی کرد مادر به بازی نگاه <br />پر از خون دل از درد طلحند شاه <br />نشسته شب و روز پر درد و خشم <br />به بازی شطرنج داده دو چشم <br />همه کام و رایش به شطرنج بود<br />ز شطرنج جانش پر از رنج بود<br />همیشه همی ریخت خونین سرشک <br />بدان درد، شطرنج بودش پزشک <br />بدین گونه بد نا چران و چمان <br />چنین تا برآمد بر او بر زمان .<br />رجوع به شاهنامه چ بروخیم ج <span class=\"hlight\" dir=\"rtl\">٨</span> صص <span class=\"hlight\" dir=\"rtl\">٢٤٧١</span> - <span class=\"hlight\" dir=\"rtl\">٢٥٠٠</span> شود.<br /></font></div>'),
(177468, 'طلحه', '<span class=\"hlight\">طلحه .</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) نسوی . از حکماء است . (ترجمه ٔ نزهةالارواح شهرزوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٤</span>).<br /></font></div>'),
(177469, 'طلحه', '<span class=\"hlight\">طلحه .</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (اِخ ) دهی است از دهستان بوشگان بخش خورموج شهرستان بوشهر در <span class=\"hlight\" dir=\"rtl\">٤٨</span>هزارگزی شمال خاوری خورموج و دامنه ٔ کوه سرخ . کوهستانی معتدل و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٨٨٢</span> تن سکنه . آب آن از چاه و قنات . محصول آنجا غلات و تنباکو و خرما. شغل اهالی زراعت و راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>). و صاحب فارسنامه گوید: دهی است چهارفرسنگی مغرب بشگان .<br /></font></div>'),
(177470, 'طلحوم', '<span class=\"hlight\">طلحوم .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) آب برگشته رنگ و مزه . (منتهی الارب ). آب طعم بگشته . (مهذب الاسماء).<br /></font></div>'),
(177471, 'طلحی', '<span class=\"hlight\">طلحی .</span> <font color=\"DarkGreen\"><b>[ طَ حی ی ]</font></b> (ع ص نسبی، اِ)نام قسمی کاغذ. (ابن الندیم ). نام قسمی کاغذ در قدیم منسوب به طلحةبن طاهر دومین امیر از امرای طاهری .<br /></font></div>'),
(177472, 'طلحی', '<span class=\"hlight\">طلحی .</span> <font color=\"DarkGreen\"><b>[ طَ حی ی ]</font></b> (ص نسبی ) منسوب به طلحةبن عبیداﷲ مشهور. (سمعانی ).<br /></font></div>'),
(177473, 'طلحی', '<span class=\"hlight\">طلحی .</span> <font color=\"DarkGreen\"><b>[ طَ حی ی ]</font></b> (اِخ ) ابواسحاق طلحةبن عبیداﷲبن محمدبن اسماعیل بصری . ندیم موفق خلیفه ٔ عباسی . متوفی بسال <span class=\"hlight\" dir=\"rtl\">٢٧١</span> هَ .ق . و کتاب المتیمین و کتاب جواهر الاخبار از اوست .<br /></font></div>'),
(177474, 'طلحیة', '<span class=\"hlight\">طلحیة.</span> <font color=\"DarkGreen\"><b>[ طَ حی ی َ ]</font></b>(ع اِ) ورقه ٔ کاغذ. لغت مولده است . (منتهی الارب ).<br /></font></div>'),
(177475, 'طلحیف', '<span class=\"hlight\">طلحیف .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) ضرب زدن سخت . یقال : ضربه ضرباً طِلْحیفاً؛ ای شدیداً. طِلْحاف . طَلَحْف . طِلَحْف . طِلَّحْف . طَلَحْفی ̍. (منتهی الارب ).<br /></font></div>'),
(177476, 'طلخ', '<span class=\"hlight\">طلخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) آلودن به گل و لای سیاه . سیاه کردن . و منه الحدیث : کان فی جنازة فقال ایکم یأتی المدینة فلایدع فیها وثناً الا کسره و لا صورة الا طلخها؛ ای لطخها بالطین حتی یطمسها. <BR><font color=\"Blue\">◄</font> تباه ساختن کتاب را. (منتهی الارب ). ضایع کردن نبشته . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آلودن پلیدی . خلیل گوید لطخ اعم است از طلخ . (منتهی الارب ).<br /></font></div>'),
(177477, 'طلخ', '<span class=\"hlight\">طلخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) لای سیل آورد که در آن کفچلیزها باقی باشند و بدانجهت کسی بر شرب آب رودبار قادر نشود. (منتهی الارب ).<br /></font></div>'),
(177478, 'طلخ', '<span class=\"hlight\">طلخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، ص ) تلخ . مر (اصلش تلخ است ) <span class=\"hlight\">:</span> و ماده ٔ نزله بعضی گرم و رقیق باشد و بعضی سرد و غلیظ، اما رقیق بعضی تیز و سوزاننده و طلخ باشد و بعضی ترش ... (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(177479, 'طلخاب', '<span class=\"hlight\">طلخاب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ )ظاهراً موضعی بوده است نزدیک سرخس . این نام سه بار در تاریخ بیهقی آمده است و مصحح آن کتاب گوید: «در کتابهای جغرافیا این نام نیامده و از محل نیز که تحقیق شد چیزی معلوم نگشت ».<br /></font></div>'),
(177480, 'طلخام', '<span class=\"hlight\">طلخام .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) طِلْحام . پیل ماده . (منتهی الارب ).<br /></font></div>'),
(177481, 'طلخام', '<span class=\"hlight\">طلخام .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) موضعی است در شعر لبید. (معجم البلدان ). لغتی است در طلحام . (منتهی الارب ).<br /></font></div>'),
(177482, 'طلخشقوق', '<span class=\"hlight\">طلخشقوق .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) یعضید. خس السلاطه . هندباء بری . کاسنی صحرائی : و اگر مقصود زدودن ریش باشد علف ایشان <font color=\"DarkGreen\"><b>[ علف آن جانوران که شیر آنان خورند ]</font></b> حاشا باید و حندقوقی و طلحشوق . (ذخیره ٔ خوارزمشاهی ). طلخشقوق و طلخشوق هم گویند. حمزه گوید: طلخشوق را به نامهای مختلف تعریف کرده اند چون حواالبقر و خاروکاودن این جمله نامهاست و ابوالخیر او را طرشقوق گوید. ارجانی گوید: طلخشوق سرد و خشک است در یک درجه و خشکی او غالب است بر سردی او و شربت او مضرت زهرها را دفع کند و اگر بر موضع گزیدگی مار و کژدم نهاده شود درد را تسکین دهد و ضرر زهر دفع کند و سده های جگر و معده را بگشاید و این هر دو عضو را تقویت کند از اعضاء رئیسه . (ترجمه ٔ صیدنه ٔ ابوریحان ). رجوع به طرخشقوق شود.<br /></font></div>'),
(177483, 'طلخشقوقا', '<span class=\"hlight\">طلخشقوقا.</span> <font color=\"DarkGreen\"><b>[ طَ خ َ ]</font></b> (معرب، اِ) طرخشقوق است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177484, 'طلخشوق', '<span class=\"hlight\">طلخشوق .</span> <font color=\"DarkGreen\"><b>[ طَ خ َ ]</font></b> (معرب، اِ) طلخشقوق است . (ترجمه ٔ صیدنه ٔ ابوریحان ). رجوع به طلخشقوق شود.<br /></font></div>'),
(177485, 'طلخف', '<span class=\"hlight\">طلخف .</span> <font color=\"DarkGreen\"><b>[ طِ ل َ ]</font></b> (ع ص ) زدگی سخت (لام زائد است ). (منتهی الارب ).<br /></font></div>'),
(177486, 'طلخه', '<span class=\"hlight\">طلخه .</span> <font color=\"DarkGreen\"><b>[ طَ خ َ ]</font></b> (معرب، اِ) رجوع به تلخه شود.<br /></font></div>'),
(177487, 'طلخوم', '<span class=\"hlight\">طلخوم .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) آب برگردیده رنگ و مزه . (منتهی الارب ). ماء اجن . (فهرست مخزن الادویه ).<br /></font></div>'),
(177488, 'طلخی', '<span class=\"hlight\">طلخی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (حامص ) تلخی . مرارت <span class=\"hlight\">:</span> <br />طلخی و شیرینیش آمیخته ست <br />کس نخورد نوش و شکر باهیون .<br />رودکی (از حاشیه ٔ فرهنگ اسدی نسخه ٔ نخجوانی ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177489, 'طلخیف', '<span class=\"hlight\">طلخیف .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) ضرب طلخیف ؛ زدن سخت و ضرب طلحیف (به حاء مهمله ) است در لغات و معانی . (منتهی الارب ).<br /></font></div>'),
(177490, 'طلس', '<span class=\"hlight\">طلس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی صلبه (؟) است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177491, 'طلس', '<span class=\"hlight\">طلس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) پاک کردن نوشته را و محو نمودن . <BR><font color=\"Blue\">◄</font> آوردن چیزی را. <BR><font color=\"Blue\">◄</font> کور گردیدن . <BR><font color=\"Blue\">◄</font> تیز دادن . <BR><font color=\"Blue\">◄</font> طُلِس َ به فی السجن (مجهولاً)؛ در زندان افکنده شد. (منتهی الارب ).<br /></font></div>'),
(177492, 'طلس', '<span class=\"hlight\">طلس .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) نامه . <BR><font color=\"Blue\">◄</font> نامه ٔ پاک کرده شده . <BR><font color=\"Blue\">◄</font> جامه ٔ ریمناک . (منتهی الارب ). جامه ٔ کهنه . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> پوست موی رفته ٔ ران شتر. <BR><font color=\"Blue\">◄</font> گرگ بیموی و کهنه . ج، اطلاس . (منتهی الارب ).<br /></font></div>'),
(177493, 'طلس', '<span class=\"hlight\">طلس .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) کوسه . به عرف عرب کسی را گویند که در روی وی اصلاً موی نباشد. سادات طلس چهار تن بوده اند: قیس بن سعد که درباره ٔ وی از انس بن مالک در سیرالسلف مروی است که گفت : منزلة قیس بن سعدبن عبادة من النبی کمنزلة صاحب الشرط من الامیر، عبداﷲ زبیر، احنف بن قیس، شریح قاضی . و یکی از اصحاب قیس می گفت که اگر خریدن لحیه به زر میسر بودی بدانچه ممکن می بود لحیه برای قیس میخریدم . (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span>).<br /></font></div>'),
(177494, 'طلس', '<span class=\"hlight\">طلس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) چادر سیاه . (منتهی الارب ).<br /></font></div>'),
(177495, 'طلس', '<span class=\"hlight\">طلس .</span><font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) ج ِ اطلس و طلساء. (منتهی الارب ).<br /></font></div>'),
(177496, 'طلس', '<span class=\"hlight\">طلس .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (ع اِ) ابر نازک . یقال : ما فی السماء طلسةٌ و طلس . (از ذیل اقرب الموارد).<br /></font></div>'),
(177497, 'طلسا', '<span class=\"hlight\">طلسا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) اسم صنفی از صدف کوچک است . طلیسا. (فهرست مخزن الادویه ).<br /></font></div>'),
(177498, 'طلسة', '<span class=\"hlight\">طلسة.</span> <font color=\"DarkGreen\"><b>[ طُ س َ ]</font></b> (ع اِ) رنگ خاکی که بسیاهی زند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ابرنازک . رجوع به طُلَس شود. (از ذیل اقرب الموارد).<br /></font></div>'),
(177499, 'طلسم', '<span class=\"hlight\">طلسم .</span> <font color=\"DarkGreen\"><b>[طِ ل ِ ]</font></b> (معرب، اِ) (از یونانی طلسما) دستگاهی به علم حیل کرده . آنچه خیالهای موهوم بشکل عجیب در نظر می آرند و نیز شکلی و صورتی عجیب که بر سر دفائن و خزائن تعبیه کنند. (از مؤیدو مدار و بهار عجم و کشف ). و از بعضی کتب دریافت شده که طلسم از اجزای ارضی و سماوی ساخته میشود یعنی از بعضی ادویه و ساعت مخصوصه و گاهی این صورت از آبگینه نیز سازند. فقیر مؤلف گوید که : ظاهراً طلسم لفظ یونانی است، عربی نیست، چه در تقدیر عربی بودن بکسرتین آمدن این لفظ وجهی ندارد چرا که این وزن در کلام عرب نیامده، اگر عربی بودی به کسر اول و فتح ثانی بر وزن قِمَطْر آمدی . (غیاث ) (آنندراج ). طلسم عبارت از تمزیج قوای فعاله ٔ سماوی به قوای منفعله ٔ ارضی است بوسیله ٔ خطوط مخصوصی که اهل این فن وهمی به کار میبرند تا بدان هر موذی را دفع کنند و چه بسا که این کلمه را بر خود خطوط اطلاق میکنند. این کلمه معرب تالِسْمُس است که بمعنی تکمیل میباشد. ج، طَلاسِم، طلسمات . (از اقرب الموارد). قطعه ٔ فلزی که بر روی آن نقشهای چند در ساعات برای حوائج معین رسم کنند. ج، طلاسم، طلسمات . و صاحب کشاف اصطلاحات الفنون آرد: عبدالعلی بیرجندی در شرح تذکره گوید: طلسم عبارت از خارقی است که مبداء آن قوای فعاله ٔ آسمانی آمیخته به قوابل زمینی منفعله است تا بدان امور شگفت و غریب پدید آورند، زیرا برای حدوث کائنات عنصری که اسباب آنها قوای آسمانی است شرایط مخصوصی است و بدین شرایط استعداد قابل کمال می پذیرد و از این رو کسی که احوال قابل و فاعل را بشناسد و بر جمع میان آنها قادر باشد میتواند به ظهور آثار عجیب و شگفتی پی برد. و در شرح مواقف آمده است که طلسم عبارت است از تمزیج قوای فعاله ٔ آسمانی با قوای منفعله ٔ زمینی و آنگاه بقیه ٔ گفتار بیرجندی را یاد میکند - انتهی <span class=\"hlight\">:</span> گفت <font color=\"DarkGreen\"><b>[ کیکاوس ]</font></b> مراچاره نیست تا بر آسمان روم و ستارگان و ماه و آفتاب را ببینم، پس طلسمی بکرد و لختی برشد و چند کس با کیکاوس برشدند و چون بدانجا رسیدند که ابر بود فروافتاد و همه بمردند مگر کیکاوس . (ترجمه ٔ طبری بلعمی ).<br />چو آمد بنزدیک تختش فراز<br />طلسم از بر تخت بردش نماز.<br /> <font color=\"Red\">فردوسی .</font><br />طلسم بزرگ آن چو آمد بجای <br />بر قیصر آمد یکی رهنمای .<br /> <font color=\"Red\">فردوسی .</font><br />بنزد طلسم آمد آن نامدار<br />گشاده دل و بر سخن کامگار.<br /> <font color=\"Red\">فردوسی .</font><br />همی بود پیشش زمانی دراز<br />طلسم فریبنده بردش نماز.<br /> <font color=\"Red\">فردوسی .</font><br />طلسمی است کآن رومیان ساختند<br />که بالوی و گستهم نشناختند.<br /> <font color=\"Red\">فردوسی .</font><br />نبینم همی جنبش جان به جسم <br />نباشد مگر فیلسوفی طلسم .<br /> <font color=\"Red\">فردوسی .</font><br />ز دانا چو بشنید قیصر برفت <br />به پیش طلسم آمد آنگاه تفت .<br /> <font color=\"Red\">فردوسی .</font><br />بسازند جای شگفتی طلسم <br />که کس بازنشناسد او را ز جسم .<br /> <font color=\"Red\">فردوسی .</font><br />طلسمی که ضحاک سازیده بود<br />سرش بآسمان برفرازیده بود.<br /> <font color=\"Red\">فردوسی .</font><br />تن و جان فدای سپهبد کنم <br />طلسم تن جادوان بشکنم .<br /> <font color=\"Red\">فردوسی .</font><br />آبی که در ولایت تو خیزد ای شگفت <br />گوئی ز هیبت تو طلسمی بود بر آن .<br /> <font color=\"Red\">فرخی .</font><br />زهی قلاعی در هر یکی هزار طلسم <br />که خیره گشتی ازاو چشم مردم هشیار.<br /> <font color=\"Red\">فرخی .</font><br />آب از حوض روان شدی و به طلسم بر بام خانه شدی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>).<br />طلسم و بند و زندان تو است این <br />بر او چشم خرد بگشای و خود بین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />در این گنج نامه ز راز جهان <br />کلید بسی گنج کردم نهان <br />کسی کآن کلید زر آرد به دست <br />طلسم بسی گنج داند شکست .<br /> <font color=\"Red\">نظامی .</font><br />آن دگر گفتی که سحر است و طلسم <br />کین رصد باشد عدو جان خصم .<br /> <font color=\"Red\">مولوی .</font><br />(در چاپ نیکلسون طلسم به کسر طاء و فتح لام ضبط شده است تا با قافیه ٔ خصم متوازن باشد، لکن طلسم در تداول فارسی زبانان به کسر طاء و کسر لام است و علاوه بر این، اصل این کلمه نیز که یونانی است مکسور بودن لام را تأیید میکند، چه یونانی آن نیز طِلِسْما است و از این رو گمان میکنم در شعر تصحیفی راه یافته است و اصل بدینگونه بود:<br />کین رصد باشد عدو جان و جسم <br />و تقابل جان با جسم نیز مؤید دیگر این مدعا است و مؤید دیگر آنکه با صورت مضبوط نیکلسن باید یک کلمه ٔ محذوف را نیز به قرینه قائل شد و آن کلمه جان بعد ازخصم است و چاپ علاءالدوله هرچند مطبوع نیست اقرب به صحت است و آن این است : که رصد بسته ست بهر جان و جسم .واﷲ اعلم . (یادداشت مؤلف ).<br />تدبیر عقل حل نکند عقده ٔ سپهر<br />بستند این طلسم زجاجی به نام عشق .<br /> <font color=\"Red\">سالک یزدی .</font><br />هیچکس معرکه ٔ شهرت مجنون نشکست <br />این طلسمی است که بر نام سلیمان بستند.<br /> <font color=\"Red\">سلیم .</font><br />هست حق با من اگر شکوه ز صیاد کنم <br />زآنکه ناحق به طلسم قفس انداخت مرا.<br /> <font color=\"Red\">ملاطغرا.</font><br />بفکن حجاب جسم که تا بشکنی طلسم <br />مردود خلق باشد مقبول ذوالمنن .<br /> <font color=\"Red\">قاآنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">یهودی طلسمش را آورده است </span> .<br /></font></div>'),
(177500, 'طلسم', '<span class=\"hlight\">طلسم .</span> <font color=\"DarkGreen\"><b>[ طِ ل ِ ]</font></b> (اِخ ) دهی از دهستان حومه ٔ بخش کرند شهرستان شاه آباد. در یک هزارگزی جنوب خاوری کرند و <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی جنوب شوسه ٔ شاه آباد. دشت و سردسیر با <span class=\"hlight\" dir=\"rtl\">١٧٠</span> تن سکنه . آب آن از چشمه و رودخانه ٔ کرند. محصول آنجا غلات و حبوبات و چغندرقند و لبنیات و شغل اهالی زراعت و گله داری است . تابستان از طریق علی آباد میتوان بدانجا اتومبیل برد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(177501, 'طلسم', '<span class=\"hlight\">طلسم .</span> <font color=\"DarkGreen\"><b>[ طِل ْ ل َ ]</font></b> (معرب، اِ) لغتی است در طلسم .<br /></font></div>'),
(177502, 'طلسم آگین', '<span class=\"hlight\">طلسم آگین .</span> <font color=\"DarkGreen\"><b>[ طِ ل ِ]</font></b> (ص مرکب ) چون طلسم . پُرطلسم . باطلسم <span class=\"hlight\">:</span> <br />من بدین راه طلسم آگین همی کردم نگاه <br />در تفکر خیره مانده همچو شخص بی روان .<br /><font color=\"Red\">فرخی .</font><br /></font></div>'),
(177503, 'طلسم زنگوله', '<span class=\"hlight\">طلسم زنگوله .</span> <font color=\"DarkGreen\"><b>[ طِ ل ِ م ِ زَ ل َ ]</font></b> (اِخ ) در افسانه های باستانی قلعه یا محلی صعب العبور بوده است که چون طلسم کرده بوده اند کس آن را گشودن نمیتوانست .<br /></font></div>'),
(177504, 'طلسم مزعفر', '<span class=\"hlight\">طلسم مزعفر.</span> <font color=\"DarkGreen\"><b>[ طِ ل ِ م ِ م ُ زَ ف َ ]</font></b> (ترکیب وصفی، اِ مرکب ) تعویذی که بزعفران نویسند <span class=\"hlight\">:</span> <br />اینک خزان معزم عید است بهر صبح <br />بر برگ رز نبشته طلسم مزعفرش .<br /><font color=\"Red\">خاقانی (از آنندراج ).</font><br /></font></div>'),
(177505, 'طلسمات', '<span class=\"hlight\">طلسمات .</span> <font color=\"DarkGreen\"><b>[ طِ ل ِ ]</font></b> (ع اِ) ج ِ طلسم <span class=\"hlight\">:</span> <br />به کیمیا و طلسمات میر ابومنصور<br />طلسمهای سکندر همی کند ویران .<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">علم طلسمات </span> ؛ دانشی است که از آن چگونگی درآمیختگی قوای فعاله ٔ عالیه بقوای منفعله ٔ سافله شناخته میشود تا بوسیله ٔ آن فعل غریبی در عالم کون و فساد پدید آید. (کشاف اصطلاحات الفنون ). حاجی خلیفه ذیل عنوان علم الطلسمات آرد: طلسم بمعنی گره لاینحل است و برخی گفته اند این کلمه مقلوب است و اصل آن مسلط است زیرا طلسم از قهر و بسط است . و آن دانشی است که از کیفیت ترکیب قوای فعاله ٔ آسمانی با قوای منفعله ٔ زمینی در ازمنه ٔ مناسب بحث میکند تا بدان خاصیت و تأثیر مقصود را به دست آورند و این عمل بکمک بخورات مقوی جالب انجام می یابد تا طلسم روحانی گردد ومنظور از آن پدید آوردن افعال شگفت آور در عالم کون و فساد است، و این فن نسبت بسحر و جادو آسان تر در دسترس قرار میگیرد زیرا مبادی و اسباب آن معلوم است . وفایده ٔ آن واضح است ولی طریق تحصیل آن پررنج میباشد. مجریطی قواعد این فن را در کتاب غایةالحکیم بسط داده و درین باره ابداع کرده است ولی وی راه اغلاق و دقت را برگزیده است، چه او در تعلیم آن بخل بسیار نشان میداده است . علامه سکاکی را نیز درین فن کتاب جلیلی است . همچنین ابن الوحشیة کتابی در این باره از نبطیان نقل کرده است . (از کشف الظنون ). و داود ضریر انطاکی گوید: برحسب نوشته ٔ برخی از مؤلفان علم طلسمات را ارشمیدس اختراع کرده است و برخی گفته اند نخستین چیزی که درین علم وضع گردیده مکعب افلاطون است و آن علمی است که ماده ٔ آن فلک و مولدات و صورت آن کمال هیاکل است و هدف و غایت آن تقلید از طبیعت اصلی است و فاعل آن حکیم است . درین علم به طب نیازمند میشوند زیرا برای دانستن احکام طبایع و اجزای بخورات و آنچه بموازین درجه ها وابسته است باید از طب استمداد کنند. سپس باید دانست که اگر موضوع مطلق علم روح در روح باشد آن را سحر خوانند و اگر جسد در جسد باشد آن را کیمیا نامند و اگر روح در جسد باشد آن را طلسم گویند. و علم طلسمات از لحاظ نسبت های عددی و اسرار فلکی قهراً مشابه طبیعیات است . رجوع به تذکره ٔ داود ضریر انطاکی ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span> قسمت دوم شود.<br /></font></div>'),
(177506, 'طلسمة', '<span class=\"hlight\">طلسمة.</span> <font color=\"DarkGreen\"><b>[ طَ س َ م َ ]</font></b> (ع مص ) در سر فرودافکندن .<br /></font></div>'),
(177507, 'طلسی', '<span class=\"hlight\">طلسی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b>(اِ) اسم هندی فرنجمشک است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177508, 'طلش', '<span class=\"hlight\">طلش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) کارد (مقلوب شلط). (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(177509, 'طلطل', '<span class=\"hlight\">طلطل .</span> <font color=\"DarkGreen\"><b>[ طُ طُ ]</font></b> (ع اِ) بیماری پیوسته . (منتهی الارب ).<br /></font></div>'),
(177510, 'طلطل', '<span class=\"hlight\">طلطل .</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (اِخ ) نام رودباری است نزدیک حلب . (معجم البلدان ).<br /></font></div>'),
(177511, 'طلطلة', '<span class=\"hlight\">طلطلة.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ل َ ]</font></b> (ع مص ) جنبانیدن چیزی را. (منتهی الارب ).<br /></font></div>'),
(177512, 'طلطین', '<span class=\"hlight\">طلطین .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (ع اِ) داهیه . (منتهی الارب ).<br /></font></div>'),
(177513, 'طلع', '<span class=\"hlight\">طلع.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) اسم است اطلاع را. و منه :اطلع طلع عدده . (منتهی الارب ). وقوف بر چیزی . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> جای بلند که از آن اطلاع یابند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کرانه (بفتح نیز آید). (منتهی الارب ) (منتخب اللغات ). ناحیه . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> جای که آفتاب از آنجا برآید. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> دیدار. (منتخب اللغات ) (دهار). <BR><font color=\"Blue\">◄</font> هر زمین پست و هموار. (منتهی الارب ). زمین پست . (منتخب اللغات ). زمین پشته ناک . (منتهی الارب ). زمینی که پشته های خاک دارد. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> مار. (منتخب اللغات ). مار دراز. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> راز. (منتخب اللغات ). سِرّ. گویند: اطلعته طلع امری ای اظهرته سری . (منتهی الارب ).<br /></font></div>'),
(177514, 'طلع', '<span class=\"hlight\">طلع.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طلاع . (منتهی الارب ).<br /></font></div>'),
(177515, 'طلع', '<span class=\"hlight\">طلع.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع مص ) برآمدن بر کوه . (منتهی الارب ).<br /></font></div>'),
(177516, 'طلع', '<span class=\"hlight\">طلع.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) جای بلند که از آن اطلاع یابند. <BR><font color=\"Blue\">◄</font> کرانه (به کسر نیز آید). (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اندازه و مقدار. یقال :الجیش طلع الف . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> شکوفه، و کنایه است از درخشندگی دندان . <BR><font color=\"Blue\">◄</font> شکوفه ٔ نخستین خرماست، پوست آن را کفری و چیز درونی آن را اغریض نامند جهت سپیدی آن . (منتهی الارب ). شکوفه ٔ نخستین که از درخت خرما برآید. (منتخب اللغات ). شکوفه ٔ درخت خرما. (دهار). اول بار خرما. اول میوه ٔ خرما که بهار خرما گویند. بزیم . طلح . کاشکلو(در خرما و مانند آن ). کویله . کاناز. گوزه مخ . ام غیلان . مغیلان . تاره . کارد. (مهذب الاسماء). آنچه اول از خرما ظاهر شود عرب طلع گوید و بعد از آن خلال و بعد از آن بسر و بعد از آن رطب و بعد از آن تمر. طلع النخل ؛ آنچه از خرمابن برآید مانند دو نعل برهم نهاده ٔ تیزاطراف و میان آن بار آن نهاده . (منتهی الارب ) <span class=\"hlight\">:</span> و از وی <font color=\"DarkGreen\"><b>[ از پارس ]</font></b> آب گل و آب بنفشه و آب طلع... خیزد. (حدود العالم ). و از وی <font color=\"DarkGreen\"><b>[ شهر گور بپارسی ]</font></b> آب طلع و آب قیصوم خیزد که بهمه ٔ جهان ببرند و جای دیگر نباشد. (حدود العالم ). بهندوی سوال گویند. ارجانی گوید طلع سرد و خشکست در سه درجه و در معده دیر هضم شود و باده قولنج است و دمش خون را که او را نفث الدم گویند بلغت تازی نافعاست . (ترجمه ٔ صیدنه ٔ ابوریحان ). شکوفه ٔ درخت خرماست که بعد از شکفتن گشن خرما از غلاف او حاصل شود مانندآرد و دقیق النخل نامند و بدون پاشیدن آن بر ثمر نخیل بار نمی بندد، در اول سرد و در دوم خشک و قابض طبع و مسکّن حرارت خون و مقوی معده و خشک او بقدر نیم وقیه رافع اسهال و جهت تشنگی و تبهای حار و نفث الدم و نزف الدم نافع و دیرهضم و اکثار او مولد قولنج و عسر بول و درد سینه و مصلح مطبوخ او روغن کنجد و خام او را مصلح چربیها و شیرینهاست و آرد او با حرارت لطیفه و بغایت محرک باه است . (تحفه ٔ حکیم مؤمن ). ابوحنیفه گوید: اول ثمر نخل را طلع خوانند و قشر وی کفری و جفری خوانند و آنچه در اندرون قشر وی بود ولیع خوانند بپارسی بهار خرما گویند، و طبیعت آن سرد است در اول و خشکست در دوم و گویند قبض در وی ممکن نیست، گویند تر بود و باقولی (یاقوتی ) گوید دقیق نخل ذکر بپارسی گشن خرما خوانند باه را نافع بود و مجامعت را قوت دهد، و ابن ماسویه گوید: خشکی بر وی غالب بود بر خشکی جمار و سردی مانند سردی جمار بود دیر از معده بگذرد و شکم ببندد بسیار خوردن وی درد معده پیدا کند و قولنج آورد و این فعل خاصیت وی است، و صاحب منهاج گوید: مصلح وی شهد است، و رازی گوید: مقوی معده بود و خشک کند و محروری مزاج را سود دهد و دفع مضرت وی از نفخ در معده و دیر از معده گذشتن بر زنجبیل مربا کنند یا به جوارشات گرم . ابن ماسویه گوید که : اگر مسلوق خورند باید که با خردل و مری (مروی ) و زیت و فلفل و کرویا و سراب و کرفس و نعناع و صعتر خورند و اگر خام خورند با طعامهای چرب مانند مرغ فربه و بزغاله ٔ فربه و مانند آن و بعد از آن شراب بر سر آن خورند. (اختیارات بدیعی ). و ابن البیطار آرد: ابن سمحون گوید: خلیل بن احمد گفته است، طلع از نخل بیرون آید و همچون دو نعل مطبق است که بار نخل میان آنها چیده شده باشد و انتهای آنها تیز است . ابوحنیفه گوید: طلع نخل ثمره ٔ آنست که در آغاز پدید آمدن آن آشکار میشود و پوست آن را کفری نامند و آنچه را در درون آن باشد ولیع و اغریض خوانند. و دندان سپید را بدان تشبیه کنند. و نیز ابن سمحون در فصل دیگری گوید: تلقیح نخل چنانست که خوشه ای از گل نر را بطور واژگون در درون خوشه ٔ ماده گذارند تا گرد و غبارآن در درون خوشه ٔ ماده پراکنده شود. (از مفردات ابن البیطار). و رجوع به تذکره ٔ داود ضریر انطاکی شود.<br /></font></div>'),
(177517, 'طلعت', '<span class=\"hlight\">طلعت .</span> <font color=\"DarkGreen\"><b>[ طَ ع َ ]</font></b> (ع اِ) طلعة. دیدار. یقال : حیااﷲ طلعته ؛ ای ابقا رؤیته او وجهه . (منتهی الارب ). روی . (مهذب الاسماء) (منتخب اللغات ). وجه <span class=\"hlight\">:</span> <br />ای از رخ تو یافته زیبائی او رنگ <br />افروخته از طلعت تو مسند و اورنگ .<br /> <font color=\"Red\">شهید.</font><br />در این تفکر بودندکآفتاب ملوک <br />شعاع طلعت کرد از سپهر مهد اظهار.<br /> <font color=\"Red\">ابوحنیفه ٔ اسکافی .</font><br />طلعت مستنصر از خدای جهان را<br />ماه منیر است و این جهان شب تار است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بر مرکبش از طلعت او دهر مقمر<br />وز مرکب او خاک زمین جمله مغبر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />با طلعت مبارک و مسعود او ز سعد<br />فالیست مشتری را در قوس طلعتش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />شد از نشاطبهار جمال طلعت تو<br />شکوفه ها را از خواب چهره ها بیدار.<br /> <font color=\"Red\">مسعودسعد.</font><br />چو چرخ گردان بر تارک معادی گرد<br />چو مهر تابان بر طلعت موالی تاب .<br /> <font color=\"Red\">مسعودسعد.</font><br />دایم تابنده باد بر فلک ملک <br />طلعت تابنده ٔ چو ماه تمامت .<br /> <font color=\"Red\">مسعودسعد.</font><br />کجا تواند دیدن گوزن طلعت شیر<br />چگونه یارد دیدن تذرو چهره ٔ باز.<br /> <font color=\"Red\">مسعودسعد.</font><br />چون طلعت خورشید عیان گشت بصحرا<br />آنجا چه بقا مانَد نور قمری را.<br /> <font color=\"Red\">سنایی .</font><br />ملک در خشم رفت و مر او را بسیاهی بخشید... هیکلی که صخر جنی از طلعت او برمیدی و عین القطر از بغلش بگندیدی . (گلستان ).<br />تا نهان شد آفتاب طلعتت در زیر خاک <br />هر سحر پیراهن شب در بر گیتی قباست .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />خود نشنیدی مگر که مایه ٔ عشرت <br />طلعت زیبا بود نه خلعت دیبا.<br /> <font color=\"Red\">قاآنی .</font><br /> <BR><font color=\"Blue\">◄</font> (مص ) دیدن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> مطلع. طلوع . برآمدن آفتاب و مانند آن <span class=\"hlight\">:</span> <br />درست گشت که بر چرخ رویت ای خورشید<br />بوقت طلعت پروین شود دوپاره شفق .<br /><font color=\"Red\">بدر چاچی .</font><br /></font></div>'),
(177518, 'طلعت', '<span class=\"hlight\">طلعت .</span> <font color=\"DarkGreen\"><b>[ طَ ع َ ]</font></b> (اِخ ) محمود افندی . رجوع به محمود طلعت در معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> شود.<br /></font></div>'),
(177519, 'طلعت', '<span class=\"hlight\">طلعت .</span> <font color=\"DarkGreen\"><b>[ طَ ع َ ]</font></b> (اِخ ) رجوع به محمد طلعت در معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> شود.<br /></font></div>'),
(177520, 'طلعت', '<span class=\"hlight\">طلعت .</span> <font color=\"DarkGreen\"><b>[طَ ع َ ]</font></b> (اِخ ) اصفهانی . هدایت گوید: اسمش آقا محمد، شغلش تجارت، وطنش اصفهان، فنش غزل سرائی . از اوست :<br />بقفس شادم و با درد گرفتاری خویش <br />نیست با نغمه سرایان چمن کار مرا.<br />باآنکه منزل کسی اندر دل تو نیست <br />نبود کسی که در دل او منزل تو نیست .<br />کس تواند یا رب از دیدار خوبان دیده پوشد<br />تا خریدار که باشد آنکه یوسف میفروشد.<br />مرا دیوانه کرد آن حلقه ٔ زلف <br />که زنجیر من دیوانه کردند.<br />گفتی که ز من شاد شود کی دل طلعت <br />آن روز که غیر از تو دلش شاد نباشد.<br />نهم ز حلقه ٔ رندان چگونه پا بیرون <br />که پند پیر مغان حلقه ای است در گوشم .<br />با همه محرومیم هر شب در آن بزمست جامی <br />میخورم خون دل اما خون به دلها میکنم .<br />بی تو شبها خواب را از دیده بیرون میکنم <br />تا نگیرد جا دگر جایش پر از خون میکنم .<br />بمستی یارم امشب خواند و جا در بزم وی دارم <br />نمیدانم ز وی این منت امشب یا ز می دارم .<br />حرفی که بارها ز لبت گوش کرده ام <br />بار دگر بگو که فراموش کرده ام .<br />نیاز و عجز و صبوری وفا و ناله و زاری <br />دلا بعشق نکویان چه کارها که نکردی .<br />ای بی تو ز زندگیم خشنودی نه <br />از درد توام امید بهبودی نه <br />آن روز که دور از تو شدم دانستم <br />غم میکُشدم ولی به این زودی نه .<br /><font color=\"Red\">(از مجمع الفصحا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٤</span>).</font><br /></font></div>'),
(177521, 'طلعت افندی', '<span class=\"hlight\">طلعت افندی .</span> <font color=\"DarkGreen\"><b>[ طَ ع َ اَ ف َ ]</font></b> (اِخ ) رجوع به یورغاکی افندی در معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> شود.<br /></font></div>'),
(177522, 'طلعت بک حرب', '<span class=\"hlight\">طلعت بک حرب .</span> <font color=\"DarkGreen\"><b>[ طَ ع َ ب َ ح َ ]</font></b> (اِخ ) محمد. از نویسندگان معاصر مصر است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(177523, 'طلعت پاشا', '<span class=\"hlight\">طلعت پاشا.</span> <font color=\"DarkGreen\"><b>[ طَ ع َ ]</font></b> (اِخ ) ثالث رجال سه گانه ٔ ترکیه که درجنگ عالمگیر ماقبل اخیر صاحب اختیار مطلق و مستبد ترکیه و هر سه از رؤسا بسیار معروف مقتدر حزب اتفاق وترقی بوده اند. در <span class=\"hlight\" dir=\"rtl\">١٥</span> مارس <span class=\"hlight\" dir=\"rtl\">١٩٢١</span> م . <span class=\"hlight\" dir=\"rtl\">/</span> پنجم رجب <span class=\"hlight\" dir=\"rtl\">١٣٣٩</span> هَ . ق . در برلین به دست یکی از ارامنه کشته شد. <br /></font></div>'),
(177524, 'طلغان', '<span class=\"hlight\">طلغان .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع ص ) آنکه مانده شود پس به رنجیدگی کار کند. گویند: هو یطلغ المهنة؛ ای عجز. (منتهی الارب ).<br /></font></div>'),
(177525, 'طلف', '<span class=\"hlight\">طلف .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ل َ ]</font></b> (ع ص ) رایگان . باطل . (منتهی الارب ). هدر. (منتخب اللغات ). یقال : ذهب دمه طلفاً؛ ای هدراً. (منتهی الارب ).<br /></font></div>'),
(177526, 'طلف', '<span class=\"hlight\">طلف .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) دهش . (منتهی الارب ) (منتخب اللغات ). عطا. (منتهی الارب ). بخشش . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> (ص ) آسان . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> زیاده از هر چیزی . (منتهی الارب ). زیاده و فاضل از هر چیزی . (منتخب اللغات ).<br /></font></div>'),
(177527, 'طلفان', '<span class=\"hlight\">طلفان .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع ص ) مانده ای که بعجز کار کند (و الصواب بالغین ). (منتهی الارب ). رجوع به طلغان شود.<br /></font></div>'),
(177528, 'طلفحة', '<span class=\"hlight\">طلفحة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ح َ ]</font></b> (ع مص ) تنک و سبک کردن چیزی را:طلفح الخبز؛ تنک و پهن کرد نان را. (منتهی الارب ).<br /></font></div>'),
(177529, 'طلفن', '<span class=\"hlight\">طلفن .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) اقحوان . (فهرست مخزن الادویه ).<br /></font></div>'),
(177530, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ ]</font></b> (ع ص ) خندان و تازه روی . (منتهی الارب ). روی گشاده . گشاده روی . صاحب چهره ٔ باز. منبسطالوجه . مُستبشر. خندان لب . تابان روی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلق اللسان </span> ؛ گشاده زبان . زبان آور. فصیح .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلق الوجه </span> ؛ خوشرو. بشاش .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">لسان ٌ طلق </span> ؛ زبان تیز. (منتهی الارب ).<br /><BR><font color=\"Blue\">◄</font> سخی . گشاده دست . <BR><font color=\"Blue\">◄</font> بی بند. رها. آزاد. <BR><font color=\"Blue\">◄</font> روشن . بی ابر.<br /></font></div>'),
(177531, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طُل ْ ل َ ]</font></b> (ع ص، اِ) ج ِ طالق . زنان آزاد از بند زوجیت . رجوع به طالق شود. (منتهی الارب ).<br /></font></div>'),
(177532, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) حلال . (منتهی الارب ) (منتخب اللغات ) (مهذب الاسماء). بی آمیغ. خالص . روا. گویند: هو لک طلقاً و اعطیته من طلق مالی ؛ یعنی خالص و جید. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلق ِ حلال باردان </span> ؛ مجموع بمعنی شراب، طلق بمعنی خالص و حلال بمعنی بیرون آمده و باردان به بای موحده صراحی باید دانست که بر معنی هر دو لفظاول کسب لغات معتبره گواهی نمیدهد، و دیگر آنکه شراب را که حرمت آن منصوص است حلال گفتن کفر است . فقیر مؤلف گوید که طِلق مجازاً بمعنی شراب و طلق حلال عبارت است از شراب مثلث که مباح است و آن شیره ٔ انگور باشد که دو ثلث آن به جوشیدن بسوزد و یک ثلث بماند سکرنمی آورد و منافع آن قریب بخمر است یا آن طلق (بکسر)بمعنی آنچه برآمده باشد از چیزی موصوف و حلال صفت آن، پس مجموع صفت و موصوف مضاف به سوی ناردان به نون که مخفف اناردانه است یعنی آب حلال که برآمده است از دانه های انار یا آنکه حلال یا تخفیف را مخفف حلال بتشدید گویند درست بتواند شد چرا که شراب گشاینده ٔ سده ها و مَسامات است . (غیاث ) (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ملک طلق </span> ؛ ملک حلال و خالص .<br /> <BR><font color=\"Blue\">◄</font> بری . بیرون . گویند: انت طلق ؛ ای خارج و بری . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلق اللسان </span> ؛ تیززبان . (منتهی الارب ). به گفته ٔ ابوحاتم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلق الوجه </span> ؛ خندان و گشاده روی . (منتهی الارب ).<br /><BR><font color=\"Blue\">◄</font> (اِ) سنگی سپید و براق که چون بکوبند توبرتو جدا شود (صحیح بفتح است ). رجوع به طَلْق شود.<br /></font></div>'),
(177533, 'طلق', '<span class=\"hlight\">طلق .</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) آهو. ج، اطلاق . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> سگ شکاری . <BR><font color=\"Blue\">◄</font> (ص ) ناقه ٔ بر سر خود گذاشته . (منتهی الارب ). شتر غیرمقید.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلق الوجه </span> ؛ خندان و گشاده روی . (منتهی الارب ). گشاده روی . (مهذب الاسماء). خوشرو. بشاش .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلق الیدین </span> ؛ جوانمرد گشاده دست . (منتهی الارب ). سخی : رجل ٌ طلق الیدین ؛ مردی گشاده دست . (مهذب الاسماء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلق اللسان </span> ؛ تیززبان . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">فرس طلق الیدالیمنی </span> ؛ اسب که در دست راست آن سپیدی نباشد. خلاف مُحَجّل . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">فرس طلق (ناقة طلق ) احدی القوائم </span> ؛ اسبی که دست و پای سفید دارد و یکی نه . (مهذب الاسماء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">لسان طلق </span> ؛ زبان تیز. زبان فصیح . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">لیل طلق </span> ؛ شب خوش نه گرم و نه سرد. (منتهی الارب ). روز و شب معتدل . (منتخب اللغات ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">یوم طلق </span> ؛ روز خوش هوا نه گرم و نه سرد. (منتهی الارب ). روزی نه گرم و نه سرد. (مهذب الاسماء).<br /></font></div>'),
(177534, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) پنبه ٔ کوهی . <BR><font color=\"Blue\">◄</font> دوائی است که ضماد آن نافع سوختگی است (و مشهور در آن سکون لام، یا آن غلط است ). معرب تلک . <BR><font color=\"Blue\">◄</font> ابوحاتم گوید: طلق (بکسر اول ) و آن سنگی است براق، بهندی ابرک و چون آن را بکوبند توبرتو جدا شود، و گاهی آن را در تابدانهای حمام بجای آبگینه بکار برند. اَجوده الیمانی ثم الهندی ثم الاندلسی و الحیلة فی حله ان یجعل فی خرقة مع حصوات و یدخل فی الماء الفاتر ثم یحرک برفق حتی ینحل و یخرج من الخرقة فی الماء ثم یصفی عنه الماء و یشمس لیجف . (منتهی الارب ). سنگی است سفید و براق که آن را ابرک گویند و چون بر چیزی بمالندآتش آن را نسوزد و اگر حل گردد و مانند آب شود اکسیر گردد چنانچه گفته اند. (منتخب اللغات ) <span class=\"hlight\">:</span> <br />لب تر مکن به آب که طلق است در قدح <br />دست از کباب دار که زهر است توأمان .<br /> <font color=\"Red\">خاقانی .</font><br />چشم و دلم چو پر شد از زیبق اشک و طلق غم <br />بس بود این گهر مرا از پی چرخ کیمیا.<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />گوهری باشد کانی . گویند هرکه حل کرده ٔ آن را بر بدن مالد آتش بر بدن او اثر نکند، و بعربی کوکب الارض خوانند. (برهان قاطع). بعربی ابهرکه را گویند. ارجانی گوید: طلق سرد است در یک درجه و خشکست در دو درجه، سیلان خون را که در رحم و مقعد پدید آید دفع کند و ریش روده را نیکو گرداند، چون به آب لسان الحمل بکار برده اند و آماسها و کرم که بر پستانها و رانهاو خصیتین بدید آید در ابتدای بدید آمدن منفعت کند وطلق حل کرده در منافع زیادت بود از حل ناکرده . (ترجمه ٔ صیدنه ٔ ابوریحان ). بعضی آن را کوکب الارض خوانند و دو نوع است : صافی البیاض غلیظجسم و از آن مروارید سازند چنانکه بغلط نتوان شناخت، و دیگر سرخ نیکورنگ که جسم نرمی دارد. (نزهة القلوب ). کوکب الارض . (ذخیره ٔ خوارزمشاهی ). عرق العروس . فتخ . و رجوع به طین شاموس شود. یکی از معانی آن چنانکه ابن البیطار گوید میکا است . نوعی از سنگ که سفید و براق و طبق برطبق باشد آن راابرق نیز گویند و چون ابرق محلول را بر چیزی بمالندآتش آن چیز را نسوزد، مجازاً بمعنی شراب آید بمناسبت آنکه ابرق محلول که مانند آب میشود اکسیر اعظم است، و شراب را نیز در فوائد قریب اکسیر دانند و بهمین جهت شراب را طلق روان نیز گویند. (غیاث ) <span class=\"hlight\">:</span> <br />درده کیمیای جان زآتش جام زیبقی <br />طلق حلال پرور آن طلق روان گوهری .<br /> <font color=\"Red\">خاقانی .</font><br />بعربی کوکب الارض گویند، سرد است در اول و خشک است در دوم . چون نیم مثقال از محلولش میل کنند طبیعت را قبض کند و خون ببندد و سنگ گرده و مثانه بریزاند و چون به آب لسان الحمل طلا کنند ورم ثدیین و ورم خلف اذنین را نفع دهد، و مضر است به سپرز و مصلحش کتیراست و طلق را چنان کنند که با سنگ ریزه ٔ چند در خریطه ٔ کرباس درشت کرده در آب نیم گرم اندازند و به آهستگی بجنبانند تا حل شود پس در آفتاب خشک سازند و نگاه دارند. و صاحب تحفه آرد: معروفست و آن سفید نقره مانند و زرد طلائی و یمانی و هندی و مغربی میباشد و بهترین او یمانیست که صفایح آن بسیار رقیق جدا شود و براق و صدفی رنگ باشد، در دوم سرد و در آخر سیُم خشک و مستعمل از او محلوب و محلول است و طریق حلب و اقسام حل او در دستورات مذکور میشود و چون به تنهائی نمیسوزد احتراق او را با نوشادر و کلس بیض ممکن دانسته اند و شرب او جهت اسهال و موی و کبدی و نزف الدم اعضا و تبهای حار و ریزانیدن سنگ گرده و مثانه و با عسل جهت سرفه ٔ حار و با آب بارتنگ جهت نفث الدم سینه و رحم و بواسیر بی عدیل و طلای او جهت قروح رطبه ٔ قضیب و اعضای عصبانی و حکه و جرب و جذام مقرح و آثار سیاه جلد و اورام حاره و بواسیر بغایت مفید و مضر سپرز و گرده و مصلحش کتیرا و تخم کرفس و شربتش نیم مثقال است، و شکر رفع تشبث او به اعضای باطنی میکند و چون محلوب او را مثل غبار سائیده و رفع نمک از شستن مکرر نموده با صمغ عربی و آب حل کنند در اعمال نقاشی و مانند آن بهتر از ورق نقره است و چون زعفران اضافه نمایند مثل ورق طلای محلول و با زنگار زمردی و با آب عصفر فستقی میشود و چون با شب ّ یمانی و خطمی و مغره و سرکه و سفیدی تخم بر اعضا طلا کنند مانع سوزانیدن آتش است، و اهل صناعة طلق را مطهر قلعی میدانند هرگاه با آب گداخته شود. (تحفه ٔ حکیم مؤمن ). صاحب اختیارات گوید: کوکب الارض خوانند و عرق العروس و به یونانی اسطولای کواکب یعنی کوکب الارض . رازی گوید سه نوعست، بحری و یمانی و اندلسی، و یمانی نکوتر بود و تنک و براق . و هندی بشکل یمانی بودولیکن عمل وی نکند و اندلسی صحیفه ٔ وی ستبر بود، و غافقی گوید آن نوعی از حشیش است معروف به عرق العروس، و ارسطو گوید که خاصیت طلق آنست که اگر بهاون یا به آهن و مطرقه و هر چیز که چیزها بدان توان کوفت، بکوبند، کوفته نگردد مگر بحجر الماس بشکنند و قطعاً وی را سحق نتوان کرد مگر وقتی که چند سنگ کوچک با وی منضم سازند و در خرقه ٔ خشن یا مویینه بندند و در آب می جنبانند تا جسم وی خرده خرده شود و بگدازد، و علی بن محمد گوید حل وی چنان کنند که در خرقه ای بندند با سنگی چند خرد و در آب نیم گرم اندازند و به آهستگی بجنبانند تا حل شود و از خرقه بیرون آید، پس آب از وی صافی کنند و در آفتاب نهند تا خشک شود، و این مؤلف گوید این عمل را حلب خوانند چنانچه طلقی را که عمل بر آن کرده باشند طلق محلوب گویند نه محلول، و شیخ الرئیس گوید خوردن وی خطرناک بود، و طبیعت وی سرد است در اول و خشک است در دوم، قابض بود و خون را ببندد و به آب لسان الحمل ورم ثدیین و ذکر و خلف اذنین و مجموع گوشتی که سست بود در ابتدا نافع بود و خون رحم و مقعدببندد و چون مغسول کنند و به آب لسان الحمل بیاشامندنفع وی ظاهر شود و طلا کردن ذوسنطاریا را نافع بود ونافع بود جهت ریشهائی که در اعضای مجذوبان پیدا گردد. و صاحب منهاج از قول اسحاق گوید که نیم مثقال از وی سنگ بریزاند، و گویند مضر بود بسپرز و مصلح وی کتیرا بود و وی سوخته نشود الا به حیله . (اختیارات بدیعی ). سنگی مطبق و درخشنده که کیمیاگران خلاصه ٔ آن را بحکمت می کشند و بکار میبرند و آن بشکل سیمان است و آن را طلق روان گویند. ابن البیطار آرد: محمدبن عبدون گوید: سنگ براقی است که میتوان آن را در زیر ضربه بصورت ورقه های کوچک و نازکی درآورد و آنها را برای پنجره ٔ روشنائی گرمابه بکار برد و بجای شیشه از آنها استفاده کرد، و بسریانی آن را فتخ و جیسما گویند. همچنین طلق را کوکب الارض و عرق العروس نیز خوانند. رازی در کتاب المدخل التعلیمی گوید: طلق را انواعی است از قبیل : بحری و یمانی و جبلی، و هرگاه آن را در زیر ضربه قرار دهند بصفحه های سپید باریک تقسیم شود که براق و درخشان میباشند. و هم رازی در کتاب علل المعادن گوید: طلق دارای دو گونه است، نوعی از آن ورقه ورقه میشود و از سنگ گچ تکوین میگردد و در جزیره ٔ قبرس وجود دارد. دیسقوریدوس گوید: طلق سنگی است که در قبرس یافت میشود شبیه به زاج یمانی است، هنگامی که آن را بشکنند توبرتو و ورقه ورقه است و صفحه های آن بسهولت از هم جدا میشوند. اگر ورقه های آن را در آتش افکنند شعله ور میشوند و در حالی که آنها را از آتش بیرون می آورندنیز همچنان برافروخته میباشند ولی ورقه های مزبور سوخته نمیشوند. غافقی گوید: این جنس طلق را جیپس گویند که عبارت از طلق اندلس است . و علی بن محمد گوید: طلق بر سه گونه است : یمانی وهندی و اندلسی، نوع یمانی گرانبهاترین و نوع اندلسی پست ترین آن میباشد و گونه ٔ هندی متوسط میان دو گونه ٔ مزبور است . گونه ٔ یمانی دارای ورقه هائی است که تا حد امکان نازک میباشد و به ورقه های نقره همانند است ولی رنگ آنها شبیه به رنگ صدف است . نوع هندی هم از لحاظ شکل مانند گونه ٔ یمانی است لیکن از نظر خاصیت پست تر از آنست . گونه ٔ اندلسی نیز ورقه ورقه میشود ولی ورقه های آن ضخیم و درشت است و آن را عرق العروس خوانند. ارسطوطالیس گوید: خاصیت طلق اینست که اگر آن را بوسیله ٔ ابزار آهنی و پتک و هاون و هر چیزی که بدان اجسام را نرم میکنند بکوبند به هیچ رو در آن تأثیری نمی بخشد ولی اگر با سنگ الماس آن را قطع کنند از همان محل قطع تبدیل به ورقه هائی میشود چنانکه یاد کردیم، وبرای حل کردن این سنگ هیچ چاره ای نیست جز اینکه آن را با سنگریزه هائی در کیسه ای موئین یا از پارچه ٔ خشنی دیگر داخل کنند و پیوسته با آن سنگریزه ها تکان دهند تا ذرات آن از هم بگسلد و رفته رفته سائیده شود. علی بن محمد گوید: حل کردن آن بسهولت امکان پذیر است بدین طریق که آن را در پارچه ٔ کهنه ای با سنگریزه ها گرد آورند و در آب سرد فروبرند سپس به نرمی آن را تکان دهند تا حل شود و از کهنه داخل آب گردد، آنگاه آن را تصفیه کنند و در آفتاب بگذارند تا خشک شود، درین هنگام در ته ظرف گردی از آن بجای ماند. رازی گوید: برای تأثیر نکردن آتش در اجسامی که نزدیک آنست روی اجسام مزبور طلق میمالند. ابن سینا گوید: نوشیدن شربت آن خطرناک است زیرا ذرات آن به پرزها و خملهای معده و حلق و مری می چسبد، و آن در اول سرد و در دوم خشک است، قابض و حابس خون باشد و برای ورم پستان و ذکر و پشت گوش و سایر عضلات سست سودمند است و شربت آن با آب لسان الحمل نفث الدم حبس کند و طلا و نوشیدن مغسول آن به آب لسان الحمل خون رحم و مقعد را حبس کند و نافع ذوسنطاریا باشد. غافقی گوید: برای قرحه هائی که در مجذوبان روی دهد نیکو است و آنها را اصلاح میکند و بهبود می بخشد. (از مفردات ابن البیطار). و رجوع به تذکره ٔ داود ضریر انطاکی شود. <BR><font color=\"Blue\">◄</font> در تداول اطفال، بچه کُنَک . رجوع به بچه کنک شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلق روان </span> ؛ یعنی شراب، چه طلق بمعنی ابرک است چون حل شود و آب گردد اکسیر شود، بدین مناسبت شراب را گویند طلق روان کنایه از شراب است و بعربی خمر گویند. (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br />طلق روانست آب بی عمل امتحان <br />زرّ خلاص است خاک بی اثر کیمیا.<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلق روان گوهری </span> ؛ کنایه از شراب انگوری است . (غیاث ) (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلق محلول </span> ؛ آنچه کیمیاگران بحکمت و ترکیبات ابرق را مثل آب میگردانند، و این اکسیر اعظم است . (غیاث ) (آنندراج ).<br /></font></div>'),
(177535, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن السمح بن شرحبیل اللخمی الاسکندرانی نفاط. وی به اسکندریه بسال <span class=\"hlight\" dir=\"rtl\">٢١١</span> هَ . ق . درگذشت . (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥١</span>).<br /></font></div>'),
(177536, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن حبیب غزی . تابعی است . (منتهی الارب ). به گفته ٔ صاحب حبیب السیر وی کسی است که با سعیدبن جُبیر و عطاردبن مجاهد و عمربن دینار از ستم حجاج بحرم کعبه پناه بردند و سرانجام نیز بتقاضای حجاج و موافقت ولید به سزا رسیدند. (از حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span>ص <span class=\"hlight\" dir=\"rtl\">٢٥٦</span>).<br /></font></div>'),
(177537, 'طلق', '<span class=\"hlight\">طلق .</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن خشاف . صحابی است . (منتهی الارب ).<br /></font></div>'),
(177538, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (اِخ ) ابن علی بن طلق . صحابی است . (منتهی الارب ).<br /></font></div>'),
(177539, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[طَ ]</font></b> (اِخ ) ابن غنام، مکنی به ابومحمد. محدث است .<br /></font></div>'),
(177540, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن معاویه، ابوغیاث . تابعی است .<br /></font></div>'),
(177541, 'طلق', '<span class=\"hlight\">طلق .</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن یزید. صحابی است . (منتهی الارب ).<br /></font></div>'),
(177542, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) رها شدن زن از عقد نکاح . (دهار). <BR><font color=\"Blue\">◄</font> به درد زه مبتلا گردیدن . <BR><font color=\"Blue\">◄</font> گشادن دست رابه نیکی . چیزی بکسی دادن و بخشیدن . (منتهی الارب ).<br /></font></div>'),
(177543, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) درد. <BR><font color=\"Blue\">◄</font> درد زه . درد زادن . (مهذب الاسماء). درد زه که در حین زادن زنان را پیدا میشود. (منتخب اللغات ) <span class=\"hlight\">:</span> <br />همچنین در طلق آن باد ولاد<br />گر نپاید بانگ درد آید که داد.<br /> <font color=\"Red\">مولوی .</font><br />آنچه میدانست تا پیدا نکرد<br />بر جهان ننهاد رنج طلق و درد.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(177544, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص ) طلق الوجه ؛ خندان و گشاده روی . <BR><font color=\"Blue\">◄</font> یقال : فلان حبس طُلقاً؛ یعنی بندی بلاقید گردید. (منتهی الارب ). آنکه بند نداشته باشد. (منتخب اللغات ).<br /></font></div>'),
(177545, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[طُ ل َ ]</font></b> (ع ص ) لسان طلق ؛ زبان تیز. (منتهی الارب ).<br /></font></div>'),
(177546, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طُ ل ُ ]</font></b> (ع ص ) لسان ٌ طُلق ؛ زبان تیز. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلق الیدین </span> ؛جوانمرد گشاده دست . (منتهی الارب ).<br /><BR><font color=\"Blue\">◄</font> شتر و ناقه ٔ بی پای بند. (منتخب اللغات ). یقال : فلان ٌ حُبس طُلقاً؛ یعنی بندی بلاقید گردید. (منتهی الارب ). از بند رسته : ناقه ٔ طُلق ؛ شتر رهاکرده شده .<br /></font></div>'),
(177547, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) بند از پوست خام، یا عام ّ است . و منه الحدیث الحیاء و الایمان مقرونان فی طلق ؛ ای هما مجتمعان فی حبل شدید الفتل . (منتهی الارب ). رسن تافته . <BR><font color=\"Blue\">◄</font> بند چوبین . (مهذب الاسماء) . <BR><font color=\"Blue\">◄</font> بهره . (منتهی الارب ). نصیب . حصه . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> شبرم . <BR><font color=\"Blue\">◄</font> گیاهی است که در رنگها بکار آید. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> تک ِ اسب . (مهذب الاسماء) (منتهی الارب ).گویند: عدا الفرس طلقاً او طلقین ؛ یعنی دوید اسب یک تک، و گویند: فلان ٌ حبس طَلَقاً (طُلُقاً)؛ یعنی بندی بلاقید گردید. <BR><font color=\"Blue\">◄</font> روده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کوه . (مهذب الاسماء) . <BR><font color=\"Blue\">◄</font> غلاف نره . ج، اطلاق . <BR><font color=\"Blue\">◄</font> سیر شب برای وارد شدن بر آب، و هو ان یکون بین الابل و بین الماء نیلتان فاللیلة الاولی الطلق لأن الراعی یجلبها الی الماء و یترکها مع ذلک ترعی فی سیرها و الابل بعد التجویز طوالق و فی اللیلة الثانیة قوارب . (منتهی الارب ). بهر دو شب بکنار آب بردن شتر. (منتخب اللغات ). آن شب که پیش از قرب بود. (مهذب الاسماء).<br /></font></div>'),
(177548, 'طلق', '<span class=\"hlight\">طلق .</span> <font color=\"DarkGreen\"><b>[طَ ل َ ]</font></b> (ع مص ) دور گردیدن و رفتن . (منتهی الارب ).<br /></font></div>'),
(177549, 'طلقان', '<span class=\"hlight\">طلقان .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِخ ) دهی است به زهراء و در آن گور جماعتی از صالحین است . مجدبن نجار حافظ آنجا سماع حدیث کرده است . (معجم البلدان ).<br /></font></div>'),
(177550, 'طلقی', '<span class=\"hlight\">طلقی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابومحمد عبداﷲبن ابراهیم بن احمد طلقی استرابادی، از مردم استراباد و جرجان . او در استراباد از ابوالحسن احمدبن عبداﷲ الاسترابادی سماع کرده است . (سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧١</span>).<br /></font></div>'),
(177551, 'طلل', '<span class=\"hlight\">طلل .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) اثر سرای . جای خراب . (منتهی الارب ). نشان سرای ویران شده . نشان سرای که پیدا بود. (دهار). نشان سرای که از پس ویرانی مانده بود. (مهذب الاسماء).نشانی خانه و سرای ویران شده که بجا مانده باشد. (منتخب اللغات ). اثر خانه ٔ ویران . آوار خانه ٔ ویران . نشان سرا و عمارت خراب . (برهان ). ج، اطلال <span class=\"hlight\">:</span> <br />رسم دار وقفت فی طلله <br />کدت اقضی الحیوة من جلله (اجله ).<br /> <font color=\"Red\">؟ (از منتهی الارب ).</font><br /><BR><font color=\"Blue\">◄</font> کالبد هر چیزی . (منتهی الارب ). شخص هر چیزی . (منتخب اللغات ): حیا اﷲ طللک ؛ ای شخصک . کالبد تن . (مهذب الاسماء). ج، اطلال، طلول . <BR><font color=\"Blue\">◄</font> دکان مانندی از سرای که بر آن نشینند. <BR><font color=\"Blue\">◄</font> تر و تازه از هر چیزی . <BR><font color=\"Blue\">◄</font> روی آب، گویند: مشی علی طلل الماء؛ ای علی ظهره . <BR><font color=\"Blue\">◄</font> طلل السفینة؛ بادبان کشتی . (منتهی الارب ).<br /></font></div>'),
(177552, 'طلل', '<span class=\"hlight\">طلل .</span> <font color=\"DarkGreen\"><b>[ طِ ل َ ]</font></b> (ع اِ) ج ِ طَل ّ. (منتهی الارب ).<br /></font></div>'),
(177553, 'طلل', '<span class=\"hlight\">طلل .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (ع اِ) ج ِ طُل ّ. (منتهی الارب ).<br /></font></div>'),
(177554, 'طلل', '<span class=\"hlight\">طلل .</span> <font color=\"DarkGreen\"><b>[ طُ ل ُ ]</font></b> (ع اِ) ج ِ طَلیل . (منتهی الارب ).<br /></font></div>'),
(177555, 'طلم', '<span class=\"hlight\">طلم .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) خوان نان نهادن . (منتهی الارب ).<br /></font></div>'),
(177556, 'طلم', '<span class=\"hlight\">طلم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) الضرب ببسط الکف . با کف دست زدن . <BR><font color=\"Blue\">◄</font> طلم الخبزة؛ برابر و درست ساخت نان را. (منتهی الارب ).<br /></font></div>'),
(177557, 'طلم', '<span class=\"hlight\">طلم .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) چرک دندان که از ناکردن مسواک گرد آید. (منتهی الارب ). چرک دندان را گویند. (فهرست مخزن الادویه ).<br /></font></div>'),
(177558, 'طلمة', '<span class=\"hlight\">طلمة.</span> <font color=\"DarkGreen\"><b>[ طُ م َ]</font></b> (ع اِ) نان کوماج . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شکار . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> صفیحة من حجارة لطابق یخبز علیها، و فی الحدیث انه علیه السلام مر برجل یعالج طلمة لأصحابه فی سفر قد عرق فقال لایصیبه حرجهنم ابداً. (منتهی الارب ).<br /></font></div>'),
(177559, 'طلمة', '<span class=\"hlight\">طلمة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ م َ ]</font></b> (ع ص، اِ) ج ِ طالم . (منتهی الارب ).<br /></font></div>'),
(177560, 'طلمسان', '<span class=\"hlight\">طلمسان .</span> <font color=\"DarkGreen\"><b>[ طِ ل ِ ]</font></b> (اِخ ) نام شهری بشمال غرب جزائر بنی مزعانه (الجزائر).<br /></font></div>'),
(177561, 'طلمسانة', '<span class=\"hlight\">طلمسانة.</span> <font color=\"DarkGreen\"><b>[ طِ م ِ ن َ ]</font></b> (ع ص ) شب تاریک . <BR><font color=\"Blue\">◄</font> ارض طلمسانة؛ زمین بی آب . (منتهی الارب ).<br /></font></div>'),
(177562, 'طلمسة', '<span class=\"hlight\">طلمسة.</span> <font color=\"DarkGreen\"><b>[ طَ م َ س َ ]</font></b> (ع مص ) روی ترش کردن . آژنگناک گردانیدن .<br /></font></div>'),
(177563, 'طلمسکو', '<span class=\"hlight\">طلمسکو.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) از ولایت مشهور خطاست . (نزهة القلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٢٥٨</span>).<br /></font></div>'),
(177564, 'طلمنکه', '<span class=\"hlight\">طلمنکه .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ م َ ک َ ]</font></b> (اِخ ) شهری است به اسپانیا. مساحت آن <span class=\"hlight\" dir=\"rtl\">١٢٣٢١</span> کیلومتر و جمعیت آن <span class=\"hlight\" dir=\"rtl\">٣٣٥</span>هزار تن است و خود شهر <span class=\"hlight\" dir=\"rtl\">٦٤</span>هزار جمعیت دارد. مردم آنجا آن را سالامانکا نامند و آن را امیر محمدبن عبدالرحمن اموی پی افکنده است . یاقوت گوید: شهری است به اندلس از اعمال افرنج که محمدبن عبدالرحمن بن الحکم بن هشام بن عبدالرحمن بن معاویةبن هشام بن عبدالملک آن را پی افکنده و از آنجا گروهی از دانشمندان بیرون آمده اند. و صاحب الحلل السندسیه درباره ٔ این شهر چنین آرد: عرب آن را به «ط» تلفظ کنند ومردم اسپانیا بجای «ط»، «س » آرند و گویند سالامانکا و آن شهر متوسطی است که <span class=\"hlight\" dir=\"rtl\">٢٥</span>هزار تن سکنه دارد و مرکز ناحیه و اسقف نشین است . این شهر از روزگار قدیم بسبب دانشگاهی که در آن وجود داشته شهرت یافته است . شهر طلمنکه در سرزمین جلگه و همواری بنیان نهاده شده و هوای آن دارای اختلاف شدیدی است و بیشتر شبیه به هوای برغش است چنانکه در زمستان مانند شهرهای برغش و آبله هوای آن بسیار سرد است و در تابستان گرمای تحمل ناپذیری دارد. نام این شهر در قدیم سالامانتیکا بوده است در سال <span class=\"hlight\" dir=\"rtl\">٢١٧</span> ق .م . آنیبال کارتاژی بر آن استیلا یافت، سپس در روزگار قدرت رومیان در شمار توابع ولایت لوزیطانی بود و هنگامی که عرب آن شهر را متصرف شد میان مردم اسپانیا و اعراب نبردهای شدیدی روی داد زیرا این شهر در سر راه شهرهائی بود که در تحت نفوذ و قدرت رومیان قرار داشتند، راهی که از مارده به استرقه منتهی میشد. مردم اسپانیا این شهر را نیز مانند دیگر شهرهای شمال اسپانیا از عرب بازستدند و آن را مرکز کشور لیون قرار دادند و الفونس ششم که بر طلیطله استیلا یافته بود آن را همچون دژ مستحکمی قرار داد، چه او گروه انبوهی از سپاهیان و نگهبانان بیگانه را که بیشتر آنان از مردم فرنگ بودند درآن شهر مستقر ساخت . اما عظمت و شهرت حقیقی طلمنکه از هنگامی آغاز میشود که الفونس نهم بسال <span class=\"hlight\" dir=\"rtl\">١٢٣٠</span> م . دانشگاه آن شهر را بنیان نهاد و پس از چندی دانشگاه مزبور بمنتهای ترقی و شهرت رسید و از بزرگترین دانشگاههای اروپا نظیر دانشگاه پاریس و اکسفورد بشمار می آمد چنانکه در دانشگاه مزبور در قرن <span class=\"hlight\" dir=\"rtl\">١٦</span> م . هفت هزار دانشجو تحصیل میکرده اند که از کشورهای مختلف بدان شهر هجوم آورده بودند. در راهنمای بدیگر آمده است که این دانشگاه معارف عرب را در بقیه ٔ شهرهای اروپا منتشر میکرد . انحطاط طلمنکه از روزگار فیلیپ دوم آغاز گردیدکه پایتخت خود را از طلیطله تغییر داد و مرکز اسقف ها را که تا آن دوران طلمنکه بود بشهر ولید نقل کرد. عامل مهمتری که در انحطاط آن تأثیری بسزا بخشید این بود که درین شهر گروه بسیاری از موریسک یا بقایای عرب بسر میبردند و چون در سال <span class=\"hlight\" dir=\"rtl\">١٦١٠</span> م . این گروه را به اجبار بیرون راندند خواهی نخواهی عمران شهر بی اندازه نقصان پذیرفت و در روزگار بوناپارت هنگامی که فرنسیس بر اسپانیا استیلا یافت طلمنکه را مرکز نظامی قرار دادند و درنتیجه بسیاری از بناهای آن منهدم گردید. درین شهر میدان عمومی مربعشکلی وجود دارد که از زیباترین میدانهای اسپانیا بشمار میرود. و هم درین شهر پلی قدیمی یافت میشود که از بناهای روزگار فرمانروائی رومیان است . همچنین کلیسیاهای مستحکم و زیبائی مانند سایر کلیسیاهای اسپانیا در طلمنکه دیده میشود. این شهر دارای کتابخانه ای است که <span class=\"hlight\" dir=\"rtl\">٨٠</span>هزار مجلد کتاب دارد ودر میان کتب مزبور نسخ خطی نفیسی یافت میشود، کتابخانه ٔ مزبور متعلق بدانشگاه میباشد ولی این دانشگاه اهمیتی را که در گذشته داشته از دست داده است و شماره ٔ دانشجویان آن بیش از <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن نیست . در طلمنکه آثار باستانی فراوان و بناهای باشکوه و سنگهای مرمر گوناگون دیده میشود. (از الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٥٠</span> - <span class=\"hlight\" dir=\"rtl\">٥٤</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177565, 'طلمنکی', '<span class=\"hlight\">طلمنکی .</span> <font color=\"DarkGreen\"><b>[ طَ م َ کی ی ]</font></b> (اِخ ) ابوعمرو یا ابوجعفر احمدبن محمدبن عبداﷲبن لب بن یحیی بن محمد معافری طلمنکی که در قرائت مهارت داشته و در آن تصانیفی کرده است . وی حدیث روایت کرده و نود سال زیسته است و محمدبن عبداﷲ خولانی از وی روایت دارد. (از معجم البلدان ). صاحب الحلل السندسیه آرد: ابوعمر طلمنکی از عالمان نامور اندلس بشمار میرود و کسانی که از وی حدیث و دانش فراگرفته اند خود را در زمره ٔ دانشمندان متبحر میشمرده اند و نام وی در تراجم علما بسیار آمده است . و رجوع به ابوبکر طلمنکی شود.<br /></font></div>'),
(177566, 'طلمنکی', '<span class=\"hlight\">طلمنکی .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ م َ کی ی ]</font></b> (اِخ ) ابوبکر عبداﷲبن ابی عمربن محمدبن عبداﷲبن لب معافری طلمنکی . فرزند ابوعمرو طلمنکی که مانند پدر در دانش و حدیث شهرتی بسزا داشته است . (از الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤</span>).<br /></font></div>'),
(177567, 'طلمون', '<span class=\"hlight\">طلمون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (... مظلوم ) شخصی لادی که رئیس دربانان هیکل بوده . (قاموس کتاب مقدس ).<br /></font></div>'),
(177568, 'طلمویة', '<span class=\"hlight\">طلمویة.</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ی َ ]</font></b> (اِخ ) شهرکی است بین برقه و اسکندریه . (معجم البلدان ).<br /></font></div>'),
(177569, 'طلمیثه', '<span class=\"hlight\">طلمیثه .</span> <font color=\"DarkGreen\"><b>[ طُ م َ ث َ ]</font></b> (اِخ ) شهری است نزدیک برقه در افریقا. (از فهرست نخبةالدهر دمشقی ).<br /></font></div>'),
(177570, 'طلنفح', '<span class=\"hlight\">طلنفح .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ف َ ]</font></b> (ع ص ) گرسنه . تهی شکم . (منتهی الارب ). خالی الجوف . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> مانده . کوفته . (منتهی الارب ).<br /></font></div>'),
(177571, 'طلنفی', '<span class=\"hlight\">طلنفی .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ فا ]</font></b> (ع ص ) مرد بسیارگوی بسیارسخن . طلنفاء. (منتهی الارب ).<br /></font></div>'),
(177572, 'طله', '<span class=\"hlight\">طله .</span> <font color=\"DarkGreen\"><b>[ طَل ْه ْ ]</font></b> (ع مص ) رفتن . <BR><font color=\"Blue\">◄</font> آهسته و نرم رفتن . (منتهی الارب ).<br /></font></div>'),
(177573, 'طله', '<span class=\"hlight\">طله .</span> <font color=\"DarkGreen\"><b>[ طُ ل َه ْ ]</font></b> (ع ص، اِ) ابر تنک، گویند: مافی السماء طلة؛ ای مارق من السحاب . (منتهی الارب ).<br /></font></div>'),
(177574, 'طله', '<span class=\"hlight\">طله .</span> <font color=\"DarkGreen\"><b>[ طُل ْه ْ ]</font></b> (ع اِ) ج ِ اَطْلَه ْ. (منتهی الارب ).<br /></font></div>'),
(177575, 'طلهة', '<span class=\"hlight\">طلهة.</span> <font color=\"DarkGreen\"><b>[ طُ هََ ]</font></b> (ع اِ) طلهة من المال ؛ باقی مانده ٔ از شتران . (منتهی الارب ).<br /></font></div>'),
(177576, 'طلهس', '<span class=\"hlight\">طلهس .</span> <font color=\"DarkGreen\"><b>[ طِ هَِ ]</font></b> (ع اِ) لشکر بسیار. (فرهنگ نفیسی ).<br /></font></div>'),
(177577, 'طلهیر', '<span class=\"hlight\">طلهیر.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) طرخشفوق است که هندبای بری باشد. (فهرست مخزن الادویه ).<br /></font></div>'),
(177578, 'طلهیس', '<span class=\"hlight\">طلهیس .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) لشکر بسیار. (منتهی الارب ).<br /></font></div>'),
(177579, 'طلهیس', '<span class=\"hlight\">طلهیس .</span> <font color=\"DarkGreen\"><b>[ طَ ل َهَْ ی َ ]</font></b> (ع اِ) تاریکی شب . لشکر بسیار. (منتهی الارب ).<br /></font></div>'),
(177580, 'طلو', '<span class=\"hlight\">طلو.</span> <font color=\"DarkGreen\"><b>[ طَل ْوْ ]</font></b> (ع مص )پای بچه ٔ چهارپایان بستن . (منتهی الارب ). ببستن پای بچه ٔ چهارپای که زنگله دارد. (تاج المصادر بیهقی ).<br /></font></div>'),
(177581, 'طلو', '<span class=\"hlight\">طلو.</span> <font color=\"DarkGreen\"><b>[ طَل ْوْ ]</font></b> (ع اِ) ریزه ٔ هر چیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آهوبره که نوزاده باشد. (منتخب اللغات ).<br /></font></div>'),
(177582, 'طلو', '<span class=\"hlight\">طلو.</span> <font color=\"DarkGreen\"><b>[ طُل ْوْ ]</font></b> (ع ص ) قابض باریک اندام . <BR><font color=\"Blue\">◄</font> (اِ) گرگ . (منتهی الارب ). (بکسر) بعربی اسم ذئب است و بفارسی مس را نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(177583, 'طلوان', '<span class=\"hlight\">طلوان .</span> <font color=\"DarkGreen\"><b>[ طُ ل ُ ]</font></b> (ع اِ) طلا. آب دهن که جهت بیماری و جز آن بسته باشد. (منتهی الارب ).<br /></font></div>'),
(177584, 'طلوب', '<span class=\"hlight\">طلوب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) طالب .بسیار خواهنده . ج، طُلب . (منتهی الارب ) <span class=\"hlight\">:</span> <br />اینچنین پیچیده مطلوب و طلوب <br />اندر این لعبند مغلوب و غلوب .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(177585, 'طلوب', '<span class=\"hlight\">طلوب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) چاهیست نزدیک سمیراء در راه حاج، آبی پاکیزه و نزدیک بسطح زمین دارد. (معجم البلدان ).<br /></font></div>'),
(177586, 'طلوبة', '<span class=\"hlight\">طلوبة.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (اِخ ) نام کوهی است . (منتهی الارب ). نام کوهکی است در شعر ابن مقبل . (معجم البلدان ).<br /></font></div>'),
(177587, 'طلوت', '<span class=\"hlight\">طلوت .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) نام یکی از دیههای بارفروش (بابل ) مازندران . (سفرنامه ٔ مازندران و استراباد رابینو ص <span class=\"hlight\" dir=\"rtl\">١١٩</span>). و در فرهنگ جغرافیائی ایران آمده است : دهی است از دهستان مشهد گنج افروز بخش مرکزی شهرستان بابل در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی جنوب بابل و یکهزارگزی خاور جاده ٔ فرعی بابل به بابل کنار. دشت، معتدل و مرطوب و مالاریائی با<span class=\"hlight\" dir=\"rtl\">٤٦٠</span> تن سکنه . آب آن از رودخانه ٔ بابل، محصول آنجابرنج و پنبه و غلات و نیشکر و صیفی . شغل اهالی زراعت و راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(177588, 'طلوث', '<span class=\"hlight\">طلوث .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) روان گشتن آب . (منتهی الارب ).<br /></font></div>'),
(177589, 'طلوح', '<span class=\"hlight\">طلوح .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ )ذوطلوح ؛ نام موضعی است . (معجم البلدان ). ... و طلح ایضاً موضع بین الیمامة و المکة... و یقال ذوطلوح .<br /></font></div>'),
(177590, 'طلور', '<span class=\"hlight\">طلور.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) نام یکی از کوههای سرن رستاق مازندران . (سفرنامه ٔ مازندران و استراباد رابینو ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span>).<br /></font></div>'),
(177591, 'طلورد', '<span class=\"hlight\">طلورد.</span> <font color=\"DarkGreen\"><b>[ طَ لُرْ ]</font></b> (اِخ ) دهی است از دهستان بازفت بخش ارول شهرستان شهرکرد، در <span class=\"hlight\" dir=\"rtl\">٦٥</span>هزارگزی شمال باختری ارول متصل براه عمومی مالرو. کوهستانی، جنگل بلوط و معتدل . <span class=\"hlight\" dir=\"rtl\">١٢٣</span> تن سکنه دارد. آب آن از چشمه، محصول آن غلات و پشم و روغن . شغل اهالی زراعت وگله داری و راه آن مالرو است . سکنه عشایر قشلاق در اطراف دزفول و مالامیر. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(177592, 'طلوع', '<span class=\"hlight\">طلوع .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) برآمدن آفتاب و مانند آن . (زوزنی ) (منتخب اللغات ) (تاج المصادر). دمیدن . سر برزدن . طالع شدن .برآمدن . برآمدن آفتاب و ماه و ستاره . مقابل افول و غروب . مقابل سقوط. برآمدن آفتاب و جز آن از ستارگان .بزدغ : طلع الکوکب طلوعاً و مطلعاً؛ مطلعاً، برآمد ستاره، و کذلک طلعت الشمس . (منتهی الارب ) <span class=\"hlight\">:</span> <br />تا نبود صبح را از سوی مغرب طلوع <br />روز بقای تو باد هفته ٔ یوم الحساب .<br /> <font color=\"Red\">خاقانی .</font><br />هنوز صبح نخستین روز دولت توست <br />در انتظار طلوع جمال خورشیدیم .<br /> <font color=\"Red\">همام .</font><br /> <BR><font color=\"Blue\">◄</font> ببالا برشدن . (زوزنی ). برآمدن بر سر کوه و جز آن . (منتخب اللغات ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آشکار شدن . <BR><font color=\"Blue\">◄</font> پنهان شدن . (منتخب اللغات ). غایب شدن در کسی . (تاج المصادر).از لغات اضداد است . <BR><font color=\"Blue\">◄</font> برآمدن دندان کودک . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> بنزدیک کسی شدن . (زوزنی ) (تاج المصادر). برآمدن شکوفه ٔ خرما. (منتخب اللغات ). شکوفه آوردن خرمابن . (منتهی الارب ). شکوفه ٔ خرما بیامدن . (تاج المصادر). <BR><font color=\"Blue\">◄</font> رسیدن بزمین . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> دانستن . (منتخب اللغات ). آگاه شدن بر کار. <BR><font color=\"Blue\">◄</font> آهنگ شهر خود کردن . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلوع شمس </span> ؛دمیدن خورشید.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلوع صبح </span> ؛ دمیدن بام .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلوع کوکبی </span> ؛ مقابل سقوط آنست . ابوریحان در التفهیم درباره ٔ طلوع منازل آرد: معنی طلوع منازل چیست ؟ معنی این طلوع نه برآمدن است از افق که این او را هر روزی بود یک بار ولکن مر کواکب منازل را پیدا شدن است همچون تشریق هر سه علوی که پیشتر یاد کردیم زیرا که چون آفتاب بکوکبی از ثابتات نزدیک آید او را بشعاع خویش بپوشاند و برآمدن او به روز گردد و فروشدن او بشب پیش از فروشدن شفق، و این حالت او را غیبت خوانند و ناپدید شدن بمغرب و همچنین باشدتا آفتاب از او بگذرد چندانک چون پیش از آفتاب برآید روشنایی سپیده او را غلبه نکند. پس اول این پدید آمدن طلوع او بود و او را نوء خوانند و هرگاه که منزلی بدین کردار پدید آید نظیر او چهاردهم است، فروشود و این را تازیان رقیب خوانند و فروشدن او وقت بامدادان سقوط گویند و میان طلوع منزلی و طلوع دیگر که بپهلوی اوست سیزده روز بود بتقریب نه بحقیقت زیرا که ستارگان منازل همه از یک عظم نیند و عرض ایشان یکی نیست و بیکی از دو ناحیت شمال و جنوب و نام انواء بر بارانها افتد و به وقت خویش بسقوط منازل بامدادان بمغرب منسوب دارند و نام بوارح بر بادها افتد و منسوب کرده آید نه به وقتهای باران، به طلوع منازل بامدادان از زیر شعاع آفتاب و اینهمه که تقدیر کردند مر زمین عرب راست، زیراک اندر بقعتهای یک بدیگر نزدیک اوقات باد و باران و سرما و گرما و هرچ اندر هوا پدید آید مختلف است پس بدان بقعتهای که یک از دیگر دور باشند بسیار مختلف تر و خاصه که یکی ببالا بود و یک فرو یا نهاد ایشان از کوهها و ریگها و شوره ها و دریاها و ماننده ٔ این مختلف باشد. (التفهیم ص <span class=\"hlight\" dir=\"rtl\">١١٤</span> و <span class=\"hlight\" dir=\"rtl\">١١٥</span>). و صاحب کشاف اصطلاحات الفنون آرد:این دو کلمه بر دو معنی اطلاق شوند: نخست آنکه طلوع عبارت از وقوع کوکب و مانند آنست مانند جزئی از فلک البروج در بالای افق خواه ظهور آن ابدی باشد یا نه و به این معنی گویند: هرگاه خورشید طلوع کند روز موجود است . و غروب عبارت از وقوع ستاره در زیر افق است خواه خفای آن ابدی باشد یا نه . دوم آنکه طلوع عبارت از انفصال ستاره ای از محیط افق است در حالی که متوجه بسوی بالاست خواه پیش از انفصال در زیر افق باشد یا نه و به این معنی گویند: طلوع کننده در فلان وقت فلان جزء از بروج است و غروب عبارت از انفصال ستاره از محیط افق است در حالی که متوجه بسوی پائین است و بدین معنی بستاره ای که ظهور آن ابدی است طالع نمیگویند همچنین ستاره ای را که خفای آن ابدی است غارب نخوانند. و باید دانست که منجمان طلوع و غروب را نسبت به افق حقیقی در نظر میگیرند و از اینرو هر طلوعی را که بالای افق حقیقی باشد طالع و آن را که در زیر افق یاد کرده باشد غارب نامند. ولی عامه آنها را نسبت به افق حسی بمعنی دوم تعبیر میکنند. آنگاه باید دانست که منجمان خروج منزل را از ضیاء فجر طلوع آن مینامند و هرگاه منزلی طلوع کند رقیب آن غایب شود و آن پانزدهمین است و علت نامیدن آن به رقیب اینست که آن را برقیبی تشبیه کرده اند که مترصد است تا هرگاه در مشرق ظاهر شود در مغرب سقوط کند. و غروب رقیب را در وقت صبح سقوط آن مینامند و منازلی را که طلوع آنها در هنگام بارانست انواء میخوانند. و رقبای آنها را هنگامی که در غیر موسم باران طلوع کنند بوارح نامند. و منجمان باران هارا به انواء و بادها را به بوارح نسبت دهند و اصل نوء سقوط یا طلوع و بارح باد گرم است و جایز شمرده اندمنزل را به این دو بنامند و برخی گفته اند نوء طلوع منزل و غروب رقیب آن با هم است ولی صحیح تر نظر نخستین است و برخی بارانها را به طلوع منازل و بادها را به سقوط آنها نسبت داده اند و هرگاه مدت سقوط یا طلوع بگذرد و بادی نوزد یا باران نبارد گویند فلان ستاره ثابت است . و باید دانست که طالع جزئی از منطقةالبروج است که در وقت مخصوصی بر افق شرقی باشد و اگر این وقت زمان ولادت شخصی باشد آن را طالع آن شخص میگویند و اگر آن وقت اول سال شمسی حقیقی باشد آن را طالع سال و طالع عالم خوانند و اگر وقت مزبور چیز دیگری باشد آن را بهمان چیز نسبت دهند و جزء مقابل طالع را غارب یا سابع نامند و منصف مابین طالع و غارب را که در بالای زمین بر نصف النهار است عاشر خوانند و آنچه را درزیر زمین در مقابل آن باشد رابع نامند. و این چهار را اوتاد چهارگانه در احوال مولود گویند. عبدالعلی بیرجندی گوید: شایسته است آنچه را که بر منطقةالبروج منطبق میشود ازین قسمت استثنا کرد زیرا طالع بر هیچ جزئی از آن اطلاق نمیشود و همچنین قسمت مزبور جزئی ازمنطقةالبروج بر نصف النهار در بالا یا در زیر زمین نمیباشد و سبب نامیدن آن به عاشر اینست که غالباً از برج دهم بروج طالع است و گاهی هم از برج نهم یا یازدهم بروج مزبور است . (از کشاف اصطلاحات الفنون ).<br /></font></div>'),
(177593, 'طلوع کردن', '<span class=\"hlight\">طلوع کردن .</span> <font color=\"DarkGreen\"><b>[ طُ ک َ دَ ]</font></b> (مص مرکب )برآمدن آفتاب و ماه و ستاره . سر برزدن . برآمدن آفتاب و مانند آن . طلوع . رجوع به طلوع شود <span class=\"hlight\">:</span> و صبح ملت حق بر آن نواحی طلوع کرد. (کلیله و دمنه ). در اقاصی آن ولایت بجائی رسید که هرگز رایت اسلام بر آن حدود طلوع نکرده بود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٤٨</span>).<br /></font></div>'),
(177594, 'طلوعات', '<span class=\"hlight\">طلوعات .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) طلوعات بر هر نوع ریش اطلاق شود خواه دارای خشک ریشه باشد یا نه و ازجمله ٔ طلوعات میتوان دبیلة و حمره و نمله را نام برد. (از تذکره ٔ ضریر انطاکی ص <span class=\"hlight\" dir=\"rtl\">١٥٦</span>).<br /></font></div>'),
(177595, 'طلوعین', '<span class=\"hlight\">طلوعین .</span> <font color=\"DarkGreen\"><b>[ طُ ع َ ]</font></b> (ع اِ) تثنیه ٔ طلوع که بر طلوع کاذب و طلوع صادق اطلاق شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بین الطلوعین </span> ؛ میان صبح کاذب و صادق .<br /></font></div>'),
(177596, 'طلول', '<span class=\"hlight\">طلول .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طَلل . (منتهی الارب ).<br /></font></div>'),
(177597, 'طلول', '<span class=\"hlight\">طلول .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) رایگان کردن خون کسی را. (منتهی الارب ).<br /></font></div>'),
(177598, 'طلوکنگو', '<span class=\"hlight\">طلوکنگو.</span> <font color=\"DarkGreen\"><b>[ طَ ک َ ]</font></b> (اِخ ) ده مخروبه ای است از بخش حومه ٔ شهرستان نائین . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(177599, 'طلویش', '<span class=\"hlight\">طلویش .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابن بیطة. یکی از پادشاهان قدیم اسپانیا. صاحب الحلل السندسیه آرد: آنگاه گروهی از اقوام بیگانه ٔ رم که آنها را پشتولکات میخواندند بر این اشبانیان داخل شدند و پادشاه ایشان را طلویش بن بیطه مینامیدند و این واقعه در روزگار بعثت عیسی بن مریم (ع ) بود. قوم مزبور از سوی رم به اندلس درآمدند و آنها در عین حال بر فرنگ نیز استیلا داشتند وعمال خود را بدان سوی گسیل میکردند. آنها شهر مارده را پایتخت اندلس قرار دادند و بر کشور اندلس استیلا یافتند و تا دیر زمانی برآن مملکت تسلط داشتند و <span class=\"hlight\" dir=\"rtl\">٢٧</span> تن از آنان متوالیاً بپادشاهی اندلس رسیدند تا سرانجام دودمان پشتولکات را گت ها منقرض ساختند... (از الحلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٢</span>).<br /></font></div>'),
(177600, 'طلی', '<span class=\"hlight\">طلی .</span> <font color=\"DarkGreen\"><b>[ طَ لا ]</font></b> (ع اِ) کالبد. (منتهی الارب ). شخص . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> قطران مالیده . <BR><font color=\"Blue\">◄</font> مرد نیک بیمار. ج، اطلاء. (منتهی الارب ). مرد سخت بیمار. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> خواهش نفس . گویند: قضا طلاه ؛ ای هواه . (منتهی الارب ).<br /></font></div>'),
(177601, 'طلی', '<span class=\"hlight\">طلی .</span> <font color=\"DarkGreen\"><b>[ طَل ْی ْ ]</font></b> (ع مص ) قطران مالیدن شتر را. (منتهی الارب ). اندودن . (دهار) (تاج المصادر) <span class=\"hlight\">:</span> و ماءالشعیر بیست وچهار گونه بیماری معروف را سود دارد و از آن ... طلی خایه وطلی سر و طلی سینه و طلی پهلو و طلی جگر و طلی شکستگی و طلی ضلع و طلی سوختگی و طلی نقرس ... را. (نوروزنامه ). فیقلعونه <font color=\"DarkGreen\"><b>[ یقلعون الانیون ]</font></b> و یطلونه علی ازجّة النشاب . (ابن البیطار). <BR><font color=\"Blue\">◄</font> بازداشتن . <BR><font color=\"Blue\">◄</font> پای بچه ٔ چهارپایان بستن . (دهار). گویند:طلیت الطلاء؛ اذا ربطته و جسته . <BR><font color=\"Blue\">◄</font> چرکین شدن دندان . (منتهی الارب ). زرد شدن دندان . (زوزنی ).<br /></font></div>'),
(177602, 'طلی', '<span class=\"hlight\">طلی .</span> <font color=\"DarkGreen\"><b>[ طُ لا ]</font></b> (ع اِ) ج ِ طُلیة.<br /></font></div>'),
(177603, 'طلی', '<span class=\"hlight\">طلی .</span> <font color=\"DarkGreen\"><b>[ طَ لی ی ]</font></b> (ع اِ) بچگان ریزه ٔ گوسفند. ج، طلیان . (منتهی الارب ). بزغاله . (مهذب الاسماء). بچه ٔ کوچک غنم که بفارسی بزغاله گویند. (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> بچه ٔ پای بسته . <BR><font color=\"Blue\">◄</font> چرک دندان . گویند: باسنانه طلی ؛ ای قلح . (منتهی الارب ). زردی دندان . (مهذب الاسماء) .<br /></font></div>'),
(177604, 'طلی', '<span class=\"hlight\">طلی .</span> <font color=\"DarkGreen\"><b>[ طُ لا ]</font></b> (ع اِ) یک نوشیدنی از شیر. (منتهی الارب ).<br /></font></div>'),
(177605, 'طلی', '<span class=\"hlight\">طلی .</span> <font color=\"DarkGreen\"><b>[ طِ لا ]</font></b> (ع اِ) لذت . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> طلا. زر (در اصطلاح فارسی ). رجوع به طلا شود <span class=\"hlight\">:</span> و بر او صفت کین افراسیاب ازاول تا به آخر به طلی نقش کرده . (تاریخ طبرستان ).<br />وجود مردم دانا مثال زرّ طلیست <br />که هر کجا که رود قدر وقیمتش دانند.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br /> <BR><font color=\"Blue\">◄</font> طلاء. اندودنی . مالیدنی . رجوع به طلاء شود <span class=\"hlight\">:</span><br />در زنخدان سَمَن، سیمین چاهی کندند<br />بر سر نرگس مخمور طلی پیوندند.<br /> <font color=\"Red\">منوچهری (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٨٦</span>).</font><br />و طلیهاء خنک و تر بر سینه می باید نهاد چون لعاب اسیغون و آب برگ خرفه ... (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(177606, 'طلی کردن', '<span class=\"hlight\">طلی کردن .</span> <font color=\"DarkGreen\"><b>[ طِ لا ک َ دَ ]</font></b> (مص مرکب ) اندودن . (زمخشری ). مالیدن . (زمخشری ). بیالودن . (دستور اللغة) <span class=\"hlight\">:</span> <br />نارنج چو دو کفّه ٔ سیمین ترازو<br />هر دو ز زر سرخ طلی کرده برونسو.<br /> <font color=\"Red\">منوچهری .</font><br />بگیرند برگ غارده درمسنگ، عاقرقرحا پنج درمسنگ ... و با ده ستیر زفت رومی بسرشند و بر کاغذ طلی کنند و بر آن موضع دوسانند. (ذخیره ٔ خوارزمشاهی ).<br />ماهی از دریا آید بسوی شست بطبع<br />گر طلی کرده بود بر سر آن شست فقاع .<br /> <font color=\"Red\">سوزنی .</font><br />چون به زر آب قدح کردند مژگان را طلی <br />میخ نعل مرکبان شاه کشور ساختند.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(177607, 'طلیاط', '<span class=\"hlight\">طلیاط.</span> <font color=\"DarkGreen\"><b>[ طَل ْ ]</font></b> (اِ) ترنجبین به لغت سودان . (تذکره ٔ ضریر انطاکی ).<br /></font></div>'),
(177608, 'طلیان', '<span class=\"hlight\">طلیان .</span> <font color=\"DarkGreen\"><b>[ طُل ْ ]</font></b> (ع اِ) ج ِ طَلی . (منتهی الارب ). رجوع به طَلی ّ شود.<br /></font></div>'),
(177609, 'طلیان', '<span class=\"hlight\">طلیان .</span> <font color=\"DarkGreen\"><b>[ طُل ْ <span class=\"hlight\" dir=\"rtl\">/</span> طِل ْ ]</font></b> (ع اِ) ج ِ طَلا. (منتهی الارب ).<br /></font></div>'),
(177610, 'طلیب', '<span class=\"hlight\">طلیب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) بسیار جوینده . ج، طُلباء. (منتهی الارب ).<br /></font></div>'),
(177611, 'طلیب', '<span class=\"hlight\">طلیب .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (اِخ ) ابن عمیربن وهب، از بنی قصی بن کلاب . صحابی قدیم الاسلام و از مردان بسیار شجاع و سخت و از مهاجرین به حبشه و سپس مدینه بود و بسیاری از وقایع را دریافت و در یوم اجنادین کشته شد. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥١</span>).<br /></font></div>'),
(177612, 'طلیة', '<span class=\"hlight\">طلیة.</span> <font color=\"DarkGreen\"><b>[ طُل ْ ی َ ]</font></b> (ع اِ) گردن . <BR><font color=\"Blue\">◄</font> بیخ گردن . ج، طلاء، و منه قول بعضهم : اللحیه لحلیة ما لم تطل عن الطلیه .(منتهی الارب ). پیش گردن . ج، طُلی . (مهذب الاسماء).<br /></font></div>'),
(177613, 'طلیة', '<span class=\"hlight\">طلیة.</span> <font color=\"DarkGreen\"><b>[ طَل ْ ی َ ]</font></b> (ع اِ) رکوی حیض . (مهذب الاسماء).<br /></font></div>'),
(177614, 'طلیح', '<span class=\"hlight\">طلیح .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (اِخ ) موضعی است به حجاز. (منتهی الارب ).<br /></font></div>'),
(177615, 'طلیح', '<span class=\"hlight\">طلیح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) شتر مانده . (منتهی الارب ) (مهذب الاسماء). شتر مانده از بار: ناقة طلیح المفار؛ یعنی مانده کرده ٔ سفرها. (منتهی الارب ).<br /><BR><font color=\"Blue\">◄</font> (اِ) کنه . (منتهی الارب ) (مهذب الاسماء).<br /></font></div>'),
(177616, 'طلیحا', '<span class=\"hlight\">طلیحا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ)بسریانی عدس بری است که عدس تلخ باشد. (فهرست مخزن الادویه ).<br /></font></div>'),
(177617, 'طلیحان', '<span class=\"hlight\">طلیحان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) تثنیه ٔ طلیح . سوار و شتر ماده بدان جهت که هر دو خسته میشوند. (منتهی الارب ).<br /></font></div>'),
(177618, 'طلیحة', '<span class=\"hlight\">طلیحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (ع ص ) تأنیث طلیح . (منتهی الارب ). رجوع به طلیح شود.<br /></font></div>'),
(177619, 'طلیحة', '<span class=\"hlight\">طلیحة.</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ح َ]</font></b> (اِخ ) الازدی . از مردان عرب و معاصر عمربن خطاب بوده است . رجوع به عقد الفرید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٣</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٤</span> شود.<br /></font></div>'),
(177620, 'طلیحة', '<span class=\"hlight\">طلیحة.</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ح َ ]</font></b> (اِخ ) ابن خویلد الاسدی . کسی که با بنی لمیم بر دعوی پیغمبری بود و خالد ولید در ایام ابوبکر وی را هزیمت کرد . صاحب مجمل التواریخ و القصص گوید: پیغامبر (ص ) بیمار بود که از حج بمدینه بازرسید اندرمحرم چون از کار اسود به یمن و مسیلمه به یمامه خبررسیدش از دلتنگی بیماری زیادت گشت و سوی ملوک یمن نامه فرستاد که اسود دروغ زنست بکشیدش و طلیحةبن خویلدالاسدی همچنین دعوی نبوت همی کرد و کس سوی پیغامبر فرستاده بود که صلح کنیم یا حرب، و پیغامبر او را لعنت کرده بود و گفته : قتلک اﷲ و حرمک الشهادة. و اندر ماه صفر خبر رسید از یمن که اسود را بکشتند، پس پیغامبر شاد گشت و سوی مسجد آمد و شکر کرد حق تعالی را درخطبه و مؤمنان را بشارت داد که اسود الکذاب را بکشتند و مسیلمه و طلیحه را نیز تا نه بس مدت کار سپری شد . بگفته ٔ صاحب امتاع الاسماع طلیحة قائد بنی اسد بود هنگام خروج احزاب برای جنگ با پیغمبر از غزوه ٔ خندق . صاحب حبیب السیر آرد :ارباب جمهور احبار اخبار نموده اند که چون واقعه ٔ انتقال سید اخیار (ص ) در اطراف بلاد و دیار اشتهار یافت اکثر قبایل عرب قدم در وادی ارتداد نهاده فرقه ای ادای زکوة را مکروه داشتند و طایفه ای تن آسانی اختیار کرده صوم و صلوة را بگذاشتند و مهم طلیحةبن خویلد اسدی و مسیلمه ٔ کذاب که دعوی نبوت میکردند قوت یافته جمع کثیر در ظل رایت نکبت آیت ایشان مجتمع گشتند، و طلیحه در زمان حیات سید کاینات ... بمدینه ٔ طیبه شتافته شرف صحبت آن حضرت را دریافت و ایمان آورده به قبیله ٔ خود بازگشت، آنگاه مرتد شده آغاز دعوی نبوت کرد و مردم را از نماز و روزه معاف داشته ربا را مباح انگاشت، بنابر تسویلات شیطانی مجموع بنی اسد ترک مسلمانی کردند و برسالت وی اقرار نمودند و عیینةبن حصین فزاری و عمروبن معدی کرب زبیدی با اقوام خویش بدو پیوستند.ابوبکر در اوایل سال دوازدهم هجرت خالدبن ولید را با سه هزار مرد شمشیرزن بقتال ارباب ردت نامزد کرد. خالد نخست متوجه طلیحه شد، طلیحه در آن وقت بنواحی آبی از میاه بنی اسد که آن را بزاخه میگفتند فرودآمده بود. خالد بعد از آنکه به معسکر او نزدیک رسید عکاشةبن محص اسدی و ثابت بن ارقم را که از کبار صحابه بودند دوچار خورده ٔ شهادت یافتند و روز دیگر خالدبن الولیدبه طلیحه رسیده نایره ٔ قتال مشتعل گردید و طلیحه کسائی بر سر انداخته در گوشه ای بنشست و بمردم گفت که محل نزول وحی است . عیینه ٔ حصین فزاری در اثنای جنگ چند نوبت نزد طلیحه رفت پرسید که جبرئیل نازل شده یا نی، هر کرت جواب شنید که هنوز نیامده مگر در نوبت آخرکه طلیحه گفت که جبرئیل نزول نمود که ان لک رحاء لاکرحاه و حدیثاً لاتنساه . صاحب مقصد این سخن را اینچنین ترجمه نوشته که تو را آسیائی همچو آسیای اوست و تو را حدیثی است که فراموش نخواهد شد، اما در ترجمه ٔ تاریخ احمدبن اعثم کوفی مذکور است که سخن طلیحه این بود که ان لک رجاء کرجاه و حدیثاً لاتنساه یعنی امید توبه امید خالد هم دوش نشود و میان شما حالتی است که تو را آن فراموش گردد، علی کلا التقدیرین عیینه بعد ازشنیدن این سخن آواز برآورد که ای بنی فزاره قرار بر فرار نمائید که این بدبخت دروغگوی است، آنگاه با قوم گریخته خالدبن ولید بر سایر سپاهیان که بنی اسد و غطفان بودند حمله کرد و ایشان از میدان ستیز روی به وادی گریز آورده طلیحه نیز بجانب شام شتافت و سرانجام به اسلام معاودت کرده در حرب نهاوند شربت شهادت چشید.و نیز صاحب حبیب السیر در ذکر فتوحات عراق و ممالک عجم گوید : «... سعد در قادسیه رحل اقامت انداخته تمامی سپاه بدو ملحق گشتند وعمر طلیحةبن خویلد اسدی و عمروبن معدیکرب الزبیدی وعاصم بن عمرو التمیمی و شرحبیل بن الکندی و فرات بن جنان را متعاقب یکدیگر با سپاهیان جلادت اثر بمدد سعد روان ساخت ... سعد بنابر اشاره ٔ عمر جمعی از اصحاب را که نعمان بن مقرن مزنی و جریربن عبداﷲ البجلی و طلحة (کذا) بن خویلد اسدی از آن جمله بودند نزد یزدجردبن شهریار فرستاد تا او را به اسلام دعوت نمایند...». و آنگاه در جنگ نهاوند آرد : «... و ازجمله ٔ شهدای نهاوند یکی طلیحةبن خویلد اسدی است و بروایت احمدبن اعثم عمروبن معدیکرب نیز در این معرکه ٔ نهاوند بعالم عدم شتافت ». زرکلی در الاعلام گوید : طلیحةبن خویلد الاسدی از اسد خزیمة، مدعی پیامبری و مردی شجاع بود و بروزگار پیغمبر اکرم ظاهر شد، فراربن الازور با وی مواجه گشت و بشمشیری وی را بزد تا بکشد، شمشیر کندی کرد و بدین واسطه میان مردم شایع گشت که شمشیر بر طلیحة کارگر نباشد. چون پیغمبر (ص ) درگذشت اتباع طلیحه از اسد و غطفان و طی روی بفزونی نهادند و طلیحه خود گفتی که جبریل بر من فرود همی آید، و بر مردم سجعهائی خواندی و ایشان را به ترک سجود در نماز واداشتی . طلیحه آرزوی تصرف مدینه داشت و برخی از یاران او نیز بدانجا هجوم بردند ولی مردم شهر بازپس راندندشان . ابوبکر خالدبن ولید را بغزای وی فرستاد و طلیحة از برابر وی بگریخت و به بزاخة (به ارض نجد) افتاد. مسکن وی در سمیراء (میان توزد الحاجر در راه مکه ) بود. خالد بمقاتله ٔ وی برخاست . طلیحه به شام گریخت، آنگاه اسلام آورد، پس از آنکه مردم اسد و غطفان بتمامی به اسلام گرویدند وی بنزد عمر آمد بمدینه و با وی بیعت کرد و بعراق بیرون شد و در جنگ نهاوند بشهادت رسید. وی مردی بود شجاع و فصیح . و رجوع به عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩</span> شود.<br /></font></div>'),
(177621, 'طلیحتان', '<span class=\"hlight\">طلیحتان .</span><font color=\"DarkGreen\"><b>[ طُ ل َ ح َ ]</font></b> (اِخ ) طلیحةبن خویلد اسدی و برادر او و ابوطلیحة قیس بن عاصم است بر قولی . (منتهی الارب ).<br /></font></div>'),
(177622, 'طلیحیون', '<span class=\"hlight\">طلیحیون .</span> <font color=\"DarkGreen\"><b>[ طَ حی یو ]</font></b> (اِخ ) بطنی از رزیق است . (صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٣</span>).<br /></font></div>'),
(177623, 'طلیس', '<span class=\"hlight\">طلیس .</span> <font color=\"DarkGreen\"><b>[ طِل ْ لی ]</font></b> (ع ص ) نابینا. (منتهی الارب ).<br /></font></div>'),
(177624, 'طلیسا', '<span class=\"hlight\">طلیسا.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِ) بلغت اهل شام نوعی از صدف کوچک است که از آن نمک میسازند و با نان میخورند، و بقول صاحب تحفه اسم حلزون است . اسم صنفی از صدف کوچک است . (فهرست مخزن الادویه ). نوعی از صدف کوچک و اهل شام وی را طلیس خوانند و اهل مصر دلینس، نمک سود با نان خورند. (اختیارات بدیعی ).نوعی از صدف باشد و آن کوچک می شود، نمک سود کرده با نان خورند. (برهان ). می خورند. (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(177625, 'طلیطلة', '<span class=\"hlight\">طلیطلة.</span> <font color=\"DarkGreen\"><b>[ طُ ل َ طُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> طُ ل َ طَل َ ]</font></b> (اِخ ) شهری است (دراندلس ) بر بر کوه، و رود تاجه از گرد وی برآید. (حدود العالم ). و از آن تا قرطبه هفت روز راه بوده است .این شهر را مسلمانان به سال نودویک از هجرت (مطابق <span class=\"hlight\" dir=\"rtl\">٧١٩</span> م .) متصرف شدند. (لین پول ). و آن دارای <span class=\"hlight\" dir=\"rtl\">٢٦</span>هزار تن سکنه است . حمداﷲ مستوفی گوید: طلیطله خوش شهری است بر سر کوهی بلند و اکثر عماراتش از سنگ کرده اند، بنزدیک نهر تاجه است و آن رود در بزرگی بدجله نزدیک بود، از اقلیم پنجم است و در بعض کتب آن را از بلاد اندلس نهاده اند و در چندین مملکت علی حده گفته اند، مواقع و نواحی فراوان از توابع اوست، و در صورالاقالیم گویددر آن ملک سمور بسیار است . (نزهةالقلوب ) . ثغر دانی . مدینة الاملاک . مقابل ثغر اعلی (سرقسطه و جهات آن ). صاحب مجمل التواریخ و القصص گوید : چنین روایتست که بمدینة الملوک (کذا) دو خانه بیافتند <font color=\"DarkGreen\"><b>[ یکی ]</font></b> بر بالا و یکی بزیر. در خانه ٔ بالائین در، بیست وچهار تاج نهاده بود که قیمت آن خدای دانست و نام خداوندش بر هر یکی نبشته و در دیگر خانه مایدت سلیمان بن داود علیهما السلام نهاده و خانه ٔ زیرین را بیست وچهار جایگاه قفل برنهاده بود و بودریق دراین وقت پادشاه بود بفرمود تا بازگشایند، بسیاری اسقفان و راهبان بیامدند و چیزها پذیرفتند و شفاعت کردند و گفتند هیچ پادشاه را این را قصد گشادن نکرد، قبول ننمود و باز فرمود گشادن . هیچ چیزی نیافتند مگر صورتهائی با عمامه ها و نیزه بر اسبان نگاشته و هیأت ایشان مانند عرب بود و همان سال عرب بقدرت خدای تعالی بدان زمین درآمدند و مسلمانی ظاهر گشت . یاقوت در معجم البلدان آرد: حمیدی آن را به ضم هر دو طا و فتح لام ضبط کرده ولی آنچه از مغربیان شنیده ام اکثر آن را به ضم طای نخست و فتح طای دوم تلفظ میکنند. شهر بزرگی است و دارای خصایص پسندیده ای که در اندلس یافت میشود، حدود آن پیوسته به نواحی وادی الحجاره است ولی طلیطله در جانب غربی مرز روم و میان شمال و خاور قرطبه است . این شهر پایتخت ملوک قرطبه بود. طلیطله بر ساحل نهر تاجه واقع است و بر روی این نهر پلی بنیان نهاده شده است که به وصف درنیاید. گروهی گفته اند طلیطله شهر دقیانوس پادشاه معاصر اهل کهف بوده است و متذکرشده اند که نزدیک آن موضعی است بنام «جنان الورد» که اجساد اصحاب کهف بی آنکه بپوسد همچنان تا امروز در آن باقی است، و خدا داناتر است . و برخی سخنانی جز این درباره ٔ آن گفته اند چنانکه درباره ٔ رقیم یاد کرده اندو این شهر را از لحاظ قدر و منزلت از مهمترین بلدان آورده اند، و گویند یکی از خصوصیتهای آن اینست که مواد خواربار و حبوب در انبارهای آن هفتاد سال باقی میماند بی آنکه تغییر پذیرد، و زعفران آن در نهایت خوبی است . و میان طلیطله و قرطبه هفت روز راه است که سواره آن را بپیمایند. این شهر از آغاز فتح اندلس به دست عرب در تصرف مسلمانان بود تا آنکه در سال <span class=\"hlight\" dir=\"rtl\">٤٧٧</span> هَ .ق . فرنگان آن را متصرف شدند. پادشاهی که این شهر راتسلیم فرنگان کرد یحیی بن یحیی بن ذی النون ملقب به القادر باﷲ بود و شهر مزبور هم اکنون نیز در تصرف فرنگان است . طلیطله را مدینه ٔ شاهان مینامیدند و چنانکه گفته اند <span class=\"hlight\" dir=\"rtl\">٧٢</span> زبان در آن رایج بود و سلیمان بن داود و عیسی بن مریم و ذوالقرنین و خضر (ع ) برحسب گمان مردم آن به طلیطله درآمده اند، و خدا داناتر است . (معجم البلدان ). و صاحب الحلل السندسیه آرد: شهر طلیطله چه درگذشته و چه در دوران جدید از بزرگترین شهرهای اسپانیا بشمار میرفته و این شهر در وسط اسپانیا واقع شده است هرچند بجنوب آن کشور نزدیکتر است، و اصل بنای آن بسیار کهن است . چنانکه گویند این شهر پایتخت کارپتنیان بوده است و نام آن درکتاب مورخ رومی «تیتلف » آمده و وی آن را «طلیطم » خوانده و متذکر شده است که طلیطم شهر کوچکی است لیکن دارای موقع طبیعی بسیار مناسبی است . رومیان بسال <span class=\"hlight\" dir=\"rtl\">١٩٢</span> ق .م . بر آن استیلا یافتند و در روزگار گت ها «اتانجلد» پادشاه آن طایفه در سال <span class=\"hlight\" dir=\"rtl\">٥٦٧</span> م . شهر مزبور را پایتخت خویش قرار داد و از آن پس تا دوران تسلط عرب طلیطله پایتخت اسپانیا بود. و هنگامی که در دین مسیح اختلاف روی داد و میان گروهی از کاتولیکها که قائل به الوهیت عیسی بودند و دسته ای از اریوسیان که با این عقیده مخالفت داشتند کشمکش و جدال رخ داد، در طلیطله نیز این اختلافات بمنتهای شدت رسید و مجامع و انجمنهای گوناگونی برای رفع اختلاف در آن شهر برپا شد و هر دو گروه از لحاظ نیرو و قدرت با هم برابر بودند لیکن چون پادشاه گت موسوم به ریکارید در سال <span class=\"hlight\" dir=\"rtl\">٥٥٧</span> م . مذهب اریوسی را انکار کرد از آن سبب کاتولیک های مزبور در اسپانیا قدرت کامل یافتند و عقیده ٔ خود را در سراسر آن کشور رواج دادند. دیری نگذشت که عرب اسپانیا را فتح کرد و بر طلیطله پایتخت آن استیلا یافت و غنائم بسیاری بچنگ آورد... لیکن تازیان برخلاف گتها طلیطله را پایتخت خویش قرار ندادند و هرچند آن شهر را نسبت بدیگر بلاد اسپانیا در مرکز آن کشور یافتند لیکن شهر مزبور نسبت بمقر فرمانروائی اعراب مرکزیت نداشت و آنها نمیتوانستند از افریقیه مسافتهای بسیاری دور شوند از اینرو مرکز امارت را نخست اشبیلیه و آنگاه قرطبه قرار دادند و شهر اخیر چندین قرن پایتخت اندلس بود. امابا همه ٔ این طلیطله در روزگار فرمانروائی عرب دارای اهمیت فراوانی بود و یکی از دژهای بزرگ اسپانیا بشمار میرفت و آن را «ثغر ادنی » مینامیدند و یکی از امرا از جانب خلیفه بسوی آن گسیل میشد و چه بسا که مدتها طلیطله از فرمانبری قرطبه سرپیچی میکرد و بنی امیه روزگار درازی لشکریان انبوهی بدان شهر میفرستادند و با همه ٔ این قادر بتصرف آن نمیشدند و غالباً خلفا بحیله و نیرنگ بر آن استیلا می یافتند... در اواخر فرمانروائی عرب که قرطبه دستخوش انقلاب و طغیان گردید و سررشته ٔ خلافت از هم گسیخت امرای بنی ذی النون بر طلیطله استیلا یافتند و در سال <span class=\"hlight\" dir=\"rtl\">١٠٣٥</span> م . در آن شهر دولت مستقلی تشکیل دادند. باری شهر طلیطله در همه ٔ ادوار مرکزدانش و هنر بوده و در آن بهترین کارخانه های اسلحه سازی و کارگاههای حریربافی و پشم بافی وجود داشته است . همچنین صنعت استخراج معادن در آن شهر رواج یافته بودکه هم اکنون نیز باقی است و اشیاء نفیسی که از راه این صنعت ساخته میشود در سراسر اروپا بفروش میرسد و اکنون در آن شهر نُه کارخانه برای تهیه ٔ صنایع مزبوردایر است و مردم توانگر با دلبستگی فراوان مصنوعات یدی مزبور را از قبیل ساعت و کیف و جام و عصا و قلم و کارد و جز اینها میخرند و همه ٔ این صنایع از دوران فرمانروائی عرب برای مردم طلیطله بیادگار مانده است . طلیطله از سال <span class=\"hlight\" dir=\"rtl\">٧١٢</span> تا <span class=\"hlight\" dir=\"rtl\">١٠٨٥</span> م . یعنی قریب <span class=\"hlight\" dir=\"rtl\">٤</span> قرن در تصرف عرب بوده است و شهر مزبور در تمام مدت فرمانروائی آنان همچون مشعل فروزانی انوار دانش و هنر را بجهان میپراکنده است . بااینکه تمدن عربی بر طلیطله استیلا یافته بود گروهی از مسیحیان آن شهر همچنان آئین خویش را حفظ میکردند لیکن زبان عرب و فرهنگ آن قوم را نیز فرامیگرفتند و نماز خود را که در اصطلاح آنان موسوم به «طقوس کنیسیه » است به هر دو زبان عربی و زبان گت ها ادا میکردند و مردم اسپانیا این گروه را «موزاراب » مینامیدند که محرف از«نصف عرب » است و شگفت اینست که مردم طلیطله پس از خارج شدن آن شهر از تصرف عرب باز هم بزبان و تمدن عرب شیفتگی نشان میدادند و اسناد معاملات و کلیه ٔ قباله ها و مدارک خود را تا سال <span class=\"hlight\" dir=\"rtl\">١٥٨٠</span> م . بزبان عربی مینوشتند، بعبارت دیگر آثار تمدن عرب تا سیصد سال پیش در آن شهر وجود داشته است و از بین رفتن آن هم درنتیجه ٔ فرمانهای مکرری بوده است که از طرف حکومت صادر میشده و کسانی را که بعربی سخن میگفته یا کتابت میکرده اند مورد بازخواست قرار میداده اند و اگر این سختگیری ها نمی بود چه بسا که زبان عرب تا امروز هم در آن شهر همچنان پایدار بود. «آنجل گونزالز پالانسیه » یکی از استادان ادبیات مادرید تحت عنوان «نصف عرب یا موزاراب طلیطله در قرن <span class=\"hlight\" dir=\"rtl\">١٢</span> و <span class=\"hlight\" dir=\"rtl\">١٣</span>» مقدار بسیاری اسناد و چکها گردآوری کرده که تا آن روزگار در طلیطله نوشته میشده است، اسناد عربی مزبور با ترجمه ٔ اسپانیولی آن بالغ بر سه مجلد و قریب هزار صفحه به قطع بزرگ است ... مسیو ژوسه صاحب جغرافیای مصور اسپانیا و پرتغال مینویسد: رسوبات تمدن بشری که در طلیطله پایدار مانده است این شهر را بمنزله ٔ یک موزه ٔ حقیقی قرار داده است و به هیچ رو با موزه های عادی که صاحبان آنها آثار نادر را گرد می آورند تا مردم آنها را تماشا کنند، قابل مقایسه نیست بلکه این موزه ٔ حقیقی عصرهای تاریخی بشر راکه بالغ بر بیست قرن است نمودار میکند و مردم هر عصری آثاری از خود در آن بیادگار گذاشته اند، از اینرو کسی که به اسپانیا برود و طلیطله را نبیند مانند آنست که اسپانیا را نشناخته است، چه طلیطله شهری اصیل وپایدار و بارز است و در آن از اشیاء معمولی که مایه ٔ افسردگی انسان میشود نمونه هائی نیست بلکه همه ٔ آثار آن از نمونه های اصیل و عالی است که نظر باستان شناس و اهل فن را بخود جلب میکند، این شهر بتنهائی شایستگی آن را دارد که جهانگردان بخاطر آن به اسپانیا سفرکنند. در مدخل شهر پلی بر نهر تاجه است که دارای یک دهانه میباشد و بر روی این پل برجی است که بر آن نوشته شده است : رود طغیان کرد و درنتیجه پل منهدم شد، ازینرو الفونس ملقب به حکیم در سال <span class=\"hlight\" dir=\"rtl\">١٢٥٢</span> م . آن را مرمت کرد آنگاه بر یماط اسپانیائی مطران تینوریو در سال <span class=\"hlight\" dir=\"rtl\">١٣٨٠</span> م . مجدداً بتکمیل آن پرداخت . این پل از روزگار فرمانروائی عرب و بلکه پیش از تسلط آنان نیز وجود داشته است . سالازار دو مندوزه نوشته ٔ عربی را که برسنگی درین پل منقور بوده بدینسان نقل کرده است : «اﷲاکبر و الصلاة و السلام علی جمیع من آمن باﷲ و رسوله محمد». و کنت دو موره نوشته ٔ دیگری را که در درون پل مدفون بوده چنین نقل کرده است : «بنی هذا الجسر بامر ملک طلیطلة العظیم محمد سوید المجاشعی بطلیطله حرسها اﷲ و انتهی سنة <span class=\"hlight\" dir=\"rtl\">٢٠٤</span> للهجرة ». (از الحلل السندسیةج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> و <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> و <span class=\"hlight\" dir=\"rtl\">٣٦٥</span> و <span class=\"hlight\" dir=\"rtl\">٣٦٦</span> و <span class=\"hlight\" dir=\"rtl\">٤٢١</span>). جمعیت طلیطله <span class=\"hlight\" dir=\"rtl\">٢٦٠٠٠</span> تن است، این شهر نزدیک مادرید است و طارق بن زیادبسال <span class=\"hlight\" dir=\"rtl\">٧١٤</span> هَ . ق . آن را فتح کرد، آنگاه الفونس پادشاه قشتاله شهر مزبور را در سال <span class=\"hlight\" dir=\"rtl\">١٠٨٥</span> هَ . ق . از عرب بازگرفت . رجوع بفهرست ج <span class=\"hlight\" dir=\"rtl\">١</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> الحلل السندسیه شود.<br /></font></div>'),
(177626, 'طلیطلی', '<span class=\"hlight\">طلیطلی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) طین قیمولیاست . (فهرست مخزن الادویه ).<br /></font></div>'),
(177627, 'طلیطلی', '<span class=\"hlight\">طلیطلی .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ طَ لی ی ]</font></b> (اِخ ) شرف الدین ابوعبداﷲ فخرالدین . او راست مستوجبة المجاهد فی شرح خاتم ابی حامد. و رجوع به شرف الدین ابوعبداﷲ شود.<br /></font></div>'),
(177628, 'طلیطلی', '<span class=\"hlight\">طلیطلی .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ طَ لی ی ]</font></b> (اِخ ) ابوعبداﷲ. وی کتاب مسلم بن حجاج را روایت کرده و روز چهارشنبه <span class=\"hlight\" dir=\"rtl\">١٢</span> صفرسال <span class=\"hlight\" dir=\"rtl\">٤٥٨</span> هَ . ق . درگذشته است . (از معجم البلدان ).<br /></font></div>'),
(177629, 'طلیطلی', '<span class=\"hlight\">طلیطلی .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ طُ لی ی ]</font></b> (اِخ ) صاعد اندلسی (<span class=\"hlight\" dir=\"rtl\">١٠٢٩</span>- <span class=\"hlight\" dir=\"rtl\">١٠٧٠</span>). در المریة اندلس تولد یافته و در قرطبه بتحصیل پرداخته و در طلیطله عهده دار امر قضا و در فقه و تاریخ و حساب و هیئت از مشاهیر بوده است . او راست : کتاب طبقات الامم و غیره .<br /></font></div>'),
(177630, 'طلیطلی', '<span class=\"hlight\">طلیطلی .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ طَ لی ی ]</font></b> (اِخ ) عیسی بن دینار واقد غافقی طلیطلی . در قرطبه سکونت گزید و از آنجا بسفر رفت و از ابوالقاسم سماع کرد و مصاحب وی گردید و به وی اعتماد کرد، آنگاه به اندلس رفت و در آن کشور صاحب فتوی گردید بدانسان که در آن هیچکس بر وی مقدم نبود... ابن فرضی گوید: یحیی بن مالک عائذ گفت از محمدبن عبدالملک بن ایمن شنیدم که میگفت عیسی بن دینار عالمی متقن بود، او کسی است که مسائل را بمردم عصر ما آموخت .او از یحیی بن یحیی با همه ٔ جلالت قدری که داشت فقیه تر بود و محمدبن عمربن لبابه میگفت : فقیه اندلس عیسی بن دینار و عالم آن عبدالملک بن حبیب و عاقل آن یحیی بن یحیی است ... طلیطلی بسال <span class=\"hlight\" dir=\"rtl\">٢١٢</span> هَ . ق . در طلیطله درگذشت و قبر وی در آنجا معروفست . (از معجم البلدان ).<br /></font></div>'),
(177631, 'طلیطلی', '<span class=\"hlight\">طلیطلی .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ طَ لی ی ]</font></b> (اِخ ) محمدبن عبداﷲبن عیشون طلیطلی مکنی به ابوعبداﷲ. از فقیهان بود. او راست : مختصری در فقه و کتابی در توجیه حدیث الموطاء. وی احادیث بسیار سماع کرده و آنها را روایت نموده است . ابوعبداﷲ سفری بمشرق رفته و در آنجا از جماعتی سماع کرده است . وی در طلیطله شب دهم صفرسال <span class=\"hlight\" dir=\"rtl\">٣٤١</span> هَ . ق . درگذشته است . (از معجم البلدان ).<br /></font></div>'),
(177632, 'طلیطم', '<span class=\"hlight\">طلیطم .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ طُ ]</font></b> (اِخ ) نامی است که تیتلیو (تیتلیف ) مورخ رومی در تاریخ خویش بشهر طلیطله داده است . (الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦٣</span>).<br /></font></div>'),
(177633, 'طلیع', '<span class=\"hlight\">طلیع.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) (اصطلاح فقه ) آنکه از طرف محارب دیده بان است .<br /></font></div>'),
(177634, 'طلیف', '<span class=\"hlight\">طلیف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) چیز گرفته . <BR><font color=\"Blue\">◄</font> ناچیز. <BR><font color=\"Blue\">◄</font> هدر. (منتهی الارب ).<br /></font></div>'),
(177635, 'طلیفیون', '<span class=\"hlight\">طلیفیون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) از یونانی تلفیون . گیاهی است . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>). ممکنست طیلافیون محرف این کلمه باشد. و رجوع به طیلافیون شود.<br /></font></div>'),
(177636, 'طلیق', '<span class=\"hlight\">طلیق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) خنده روی . (منتهی الارب ). گشاده روی . (منتهی الارب ) (دهار). <BR><font color=\"Blue\">◄</font> از قید رسته . (منتهی الارب ). رهاشده ٔ از بند. (منتخب اللغات ). رهاکرده . (منتهی الارب ). آزادکرده (پس از بردگی ). از بند رهاکرده . ج، طُلقاء. (مهذب الاسماء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">رجل طلیق الیدین </span> ؛ اذا کان سخیاً. (مهذب الاسماء). بخشنده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلیق الاله </span> ؛ باد است . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلیق اللسان </span> ؛ تیززبان . گشاده زبان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طلیق الوجه </span> ؛ خندان و گشاده روی . (منتخب اللغات ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">لسان طلیق </span> ؛ زبان فصیح . (منتهی الارب ).<br /></font></div>'),
(177637, 'طلیق', '<span class=\"hlight\">طلیق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) رجوع به مروان بن عبدالرحمن در الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥١</span> شود.<br /></font></div>'),
(177638, 'طلیق', '<span class=\"hlight\">طلیق .</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (اِخ ) ابن سفیان . صحابی است . (منتهی الارب ).<br /></font></div>'),
(177639, 'طلیق', '<span class=\"hlight\">طلیق .</span> <font color=\"DarkGreen\"><b>[ طِل ْ لی ]</font></b> (ع ص ) مرد بسیار طلاق دهنده . (منتهی الارب ).<br /></font></div>'),
(177640, 'طلیقان', '<span class=\"hlight\">طلیقان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام یکی از اقطاعات بصره بوده است، و الف و نون آن علامت نسبت است . اقطاع مزبور به فرزندان خالدبن طلیق بن محمدبن عمران بن حصین خزاعی منسوب بوده است و خالد امور قضای بصره را بر عهده داشته است . (از معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٠</span>).<br /></font></div>'),
(177641, 'طلیقون', '<span class=\"hlight\">طلیقون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) گیاهی است مانند خرفه دارای گل سپید و برگهائی که از میان آنها شاخه هائی منشعب میشود و این شاخه ها بیش از یک سال دوام نمی یابد، هرگاه آن را بمالند رطوبت لزجی از آن پدید می آید. در دوم گرم و در سوم خشک است . طلای آن بهق و برص و نشانه های زخم را سودمند بود و آن را در داخل بکار نبرند زیراسبب قرحه میشود و بیش از نیم روز معتدل آن را طلا نمیکنند، آنگاه ضماد آرد جو بکار میبرند. (از تذکره ٔ داود ضریر انطاکی ). رجوع به طلیفیون و طیلافیون شود.<br /></font></div>'),
(177642, 'طلیل', '<span class=\"hlight\">طلیل .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) منزلی در راه کرک که دارای گیاه دفلی فراوان بوده است . رجوع به عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣</span> شود.<br /></font></div>'),
(177643, 'طلیل', '<span class=\"hlight\">طلیل .</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (ع ص، اِ) خون رایگان رفته . <BR><font color=\"Blue\">◄</font> شیرین . <BR><font color=\"Blue\">◄</font> بوریا، یا از برگ درخت بوی جهودان یا ازشاخ نخل یا از پوست آن بافته . ج، اَطِلّة، طِلّة، طُلُل . (منتهی الارب ). حصیر. (مهذب الاسماء). حصیری که از برگ خرما و جز آن بافته باشند. (منتخب اللغات ).<br /></font></div>'),
(177644, 'طلیلیبس', '<span class=\"hlight\">طلیلیبس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) بیونانی خراطین است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177645, 'طلینا', '<span class=\"hlight\">طلینا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) نوعی از صدف خرد است که مردم شام آن را طلینس و اهل مصر دلینس میخوانند، نمکسود آن را با نان بعنوان نانخورش میخورند. ابن البیطار ذیل صدف نیزدرباره ٔ آن گفتگو کرده است . (از مفردات ابن البیطار). و رجوع به طلیسا شود.<br /></font></div>'),
(177646, 'طلینس', '<span class=\"hlight\">طلینس .</span> <font color=\"DarkGreen\"><b>[ طِل ْ لی ن َ ]</font></b> (اِ) طلینا. دلینس .<br /></font></div>'),
(177647, 'طم', '<span class=\"hlight\">طم .</span> <font color=\"DarkGreen\"><b>[ طَم م ]</font></b> (ع مص ) بسیار گردیدن آب . (منتهی الارب ) (منتخب اللغات ). طُموم . <BR><font color=\"Blue\">◄</font> پر کردن خنور. (منتهی الارب ). پر کردن ظرف . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> غالب آمدن . غلبه کردن . (دهار). بسیار شدن چیز بحد فوق شدن و غالب گردیدن . (منتهی الارب ). قوی و افزون شدن چیزی . (زوزنی ). دشوار گشتن . <BR><font color=\"Blue\">◄</font> موی بریدن . (تاج المصادر). بریدن مو. (منتخب اللغات ). بریدن موی را یا گره زدن . (منتهی الارب ). گره زدن و بافتن مو. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> بر درخت برآمدن مرغ . <BR><font color=\"Blue\">◄</font> سبک شدن . (منتخب اللغات ) (منتهی الارب ). طمیم . <BR><font color=\"Blue\">◄</font> نرم نرم رفتن . نرم نرم دویدن . طمیم . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بروی زمین رفتن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> انباشتن . (تاج المصادر). بسنگ گرفتن چاه . (منتخب اللغات ). چاه انباشتن . (زوزنی ). درانباشتن چاه و برابر کردن . <BR><font color=\"Blue\">◄</font> گُزیدن بعضی از چیز را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پیراستن . <BR><font color=\"Blue\">◄</font> بروز چیزی درآمدن . (زوزنی ).<br /></font></div>'),
(177648, 'طم', '<span class=\"hlight\">طم .</span> <font color=\"DarkGreen\"><b>[ طِم م ]</font></b> (ع اِ) آب . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آنچه بر آب گرد آید یا آب آورد. (منتهی الارب ). گیاهی که بر آب باشد و آب اورا بیرون اندازد. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> دریا. (دهار) (منتخب اللغات ) (مهذب الاسماء) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) کثیر. (منتهی الارب ). عدد بسیار.(منتخب اللغات ). <BR><font color=\"Blue\">◄</font> مال بسیار، و منه : جاء فلان بالطم و الرم ؛ ای بالمال الکثیر. <BR><font color=\"Blue\">◄</font> مرد رسا. (منتهی الارب ). زیرک . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> شگفت . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آنچه ازو شگفت آید. (منتخب اللغات ). در شگفت آورنده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شترمرغ نر. (منتهی الارب ) (منتخب اللغات ) (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> شرم کلان مرد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اسپ نیک . (منتخب اللغات ). اسپ نیکورو. (منتهی الارب ).<br /></font></div>'),
(177649, 'طم و رم', '<span class=\"hlight\">طم و رم .</span> <font color=\"DarkGreen\"><b>[ طِم ْ م ُرِم م <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (از ع، ترکیب عطفی، اِ مرکب ) آب و خاک . <BR><font color=\"Blue\">◄</font> خشک و تر. <BR><font color=\"Blue\">◄</font> کثیر و قلیل . مال بسیار. (غیاث ): جاء فلان بالطم و الرم ؛ ای بالمال الکثیر، و الظاهر ان ههنا یقصد بتمامه <span class=\"hlight\">:</span> <br />پس نبیند جمله را با طم و رم <br />حب» الاشیاء یعمی و یصم .<br /> <font color=\"Red\">مولوی .</font><br />عقل تو قسمت شده بر صد مهم <br />بر هزاران آرزو و طم و رم .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(177650, 'طما', '<span class=\"hlight\">طما.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) کوهی یا رودباری است نزدیکی اجاء. (معجم البلدان ).<br /></font></div>'),
(177651, 'طماثاوس', '<span class=\"hlight\">طماثاوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) یکی از ناقلین نصاری بزبان عربی . (ابن الندیم ).<br /></font></div>'),
(177652, 'طماح', '<span class=\"hlight\">طماح .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع مص ) بلند نگریستن بچیزی . (زوزنی ). طمح . منتهی الارب ). <BR><font color=\"Blue\">◄</font> سرکشی کردن . (منتخب اللغات ). طمح . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آرمیدن با زن . (منتخب اللغات ).<br /></font></div>'),
(177653, 'طماح', '<span class=\"hlight\">طماح .</span> <font color=\"DarkGreen\"><b>[ طَم ْ ما ]</font></b> (اِخ ) نام مردی از بنی اسد. بعثوه الی قیصر فمحل بامرءالقیس حتی سم . (منتهی الارب ).<br /></font></div>'),
(177654, 'طماح', '<span class=\"hlight\">طماح .</span> <font color=\"DarkGreen\"><b>[ طَم ْ ما ]</font></b> (ع ص )آزمند. حریص . (منتهی الارب ). شره . (منتخب اللغات ).<br /></font></div>'),
(177655, 'طماح', '<span class=\"hlight\">طماح .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِمص ) سرکشی، یُقال : فرس فیه طِماح . <BR><font color=\"Blue\">◄</font> نافرمانی زن از شوی . (منتهی الارب ).<br /></font></div>'),
(177656, 'طماحة', '<span class=\"hlight\">طماحة.</span> <font color=\"DarkGreen\"><b>[ طَم ْ ما ح َ ]</font></b> (ع ص ) تأنیث طماح . زنی که بشهوت بمردان نگرد. طامح .<br /></font></div>'),
(177657, 'طماحر', '<span class=\"hlight\">طماحر.</span> <font color=\"DarkGreen\"><b>[ طُ ح ِ ]</font></b> (ع ص ) کلان شکم . (منتهی الارب ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177658, 'طماحیة', '<span class=\"hlight\">طماحیة.</span> <font color=\"DarkGreen\"><b>[ طَم ْ ما حی ی َ ]</font></b> (اِخ ) آبیست بمشرق سُمیرا و منسوب بمردی طماح نام . (معجم البلدان ).<br /></font></div>'),
(177659, 'طماخ', '<span class=\"hlight\">طماخ .</span> <font color=\"DarkGreen\"><b>[ طم ْ ما ]</font></b> (اِخ ) نام قبیله ای است . (مهذب الاسماء).<br /></font></div>'),
(177660, 'طماخر', '<span class=\"hlight\">طماخر.</span> <font color=\"DarkGreen\"><b>[ طُ خ ِ ]</font></b> (ع اِ) شتر. (منتهی الارب ).<br /></font></div>'),
(177661, 'طماخس', '<span class=\"hlight\">طماخس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) شهرکیست از فرغانه بماوراءالنهر به براکوه نهاده . (حدود العالم ).<br /></font></div>'),
(177662, 'طمار', '<span class=\"hlight\">طمار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) کوهی است . <BR><font color=\"Blue\">◄</font> و گویند نام سور دمشق است . <BR><font color=\"Blue\">◄</font> قصری است در کوفه . (معجم البلدان ).<br /></font></div>'),
(177663, 'طمار', '<span class=\"hlight\">طمار.</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ع اِ) (کلمه ٔ غیرمنصرف ) جای بلند. گویند: انصب علیه من طَمارَ (بالفتح عن الکسائی وبالکسر عن الاصمعی )، و فی الحدیث : فلیزم نفسه من طمار؛ ای الموضع المرتفع، و قیل اسم جبیل ؛ ای لاینبغی ان یعرض نفسه للمهالک قائلاً قد توکلت . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ابنتاطمار</span> ؛ دو کوه پشته است بلند. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بنات طمار</span> ؛ سختی و داهیه . (منتهی الارب ).<br /></font></div>'),
(177664, 'طمار', '<span class=\"hlight\">طمار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) برجستن سوی هوا. (منتهی الارب ). برجستن . (منتخب اللغات ).<br /></font></div>'),
(177665, 'طماس', '<span class=\"hlight\">طماس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) هاید. از مترجمین غزلیات حافظ به لاتینی . (از سعدی تا جامی ص <span class=\"hlight\" dir=\"rtl\">٣٣١</span>).<br /></font></div>'),
(177666, 'طماس', '<span class=\"hlight\">طماس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) ایلدوچی .حامل نامه ٔ ایلخان (الجایتوسلطان ) نزد سلاطین عالیمقدار فرنگستان (فیلیپ ل ُ بِل، ادوارد دوم و پاپ کلمان پنجم ) و بطوری که دهسن در تاریخ خود (ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٩٠</span>) اشاره میکند این شخص در دربارهای اروپا بکلی این نکته را که ایلخان قبول دیانت اسلام نموده است مخفی ساخت زیرا مراسلاتی که از جانبین تبادل شده فعلاً موجود است و در آنجا هم ادوارد دوم در مراسله ٔ مورخه ٔ <span class=\"hlight\" dir=\"rtl\">٣٠</span> نوامبر <span class=\"hlight\" dir=\"rtl\">١٣٠٧</span> م . و هم کلمان پنجم پاپ روم در مکتوب مورخ اول مارس <span class=\"hlight\" dir=\"rtl\">١٣٠٨</span> م . بطور وضوح تقاضا نموده اند که الجایتوبا آنها یاری و مساعدت نموده پیروان محمد (ص ) را یکسره محو و نابود نمایند... (از سعدی تا جامی ص <span class=\"hlight\" dir=\"rtl\">٥٣</span>).<br /></font></div>'),
(177667, 'طماس', '<span class=\"hlight\">طماس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) لاو.شاعر انگلیسی (<span class=\"hlight\" dir=\"rtl\">١٧٨٥</span> م .). (از سعدی تا جامی ص <span class=\"hlight\" dir=\"rtl\">٣٢٩</span>).<br /></font></div>'),
(177668, 'طماسة', '<span class=\"hlight\">طماسة.</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (ع اِمص ) تخمین . دید. حرز.<br /></font></div>'),
(177669, 'طماسة', '<span class=\"hlight\">طماسة.</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (ع مص ) حرز کردن . اندازه نمودن . <BR><font color=\"Blue\">◄</font> نگاه داشتن چیزی را. (منتهی الارب ).<br /></font></div>'),
(177670, 'طماسلة', '<span class=\"hlight\">طماسلة.</span> <font color=\"DarkGreen\"><b>[ طَ س ِ ل َ ]</font></b> (ع اِ) ج ِ طمسل . (منتهی الارب ).<br /></font></div>'),
(177671, 'طماطم', '<span class=\"hlight\">طماطم .</span> <font color=\"DarkGreen\"><b>[ طَ طِ ]</font></b> (معرب، اِ) تمات . گوجه فرنگی . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٩</span>). طماطیس .<br /></font></div>'),
(177672, 'طماطم', '<span class=\"hlight\">طماطم .</span> <font color=\"DarkGreen\"><b>[ طَ طِ ]</font></b> (ع اِ) ج ِ طمطم . رجوع به طمطم شود.<br /></font></div>'),
(177673, 'طماطیس', '<span class=\"hlight\">طماطیس .</span> <font color=\"DarkGreen\"><b>[طُ ]</font></b> (معرب، اِ) طماطم . گوجه فرنگی . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٩</span>).<br /></font></div>'),
(177674, 'طماع', '<span class=\"hlight\">طماع .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) طماعیة. آزمند گردیدن و حریص گشتن . <BR><font color=\"Blue\">◄</font> امید داشتن . (منتهی الارب ).<br /></font></div>'),
(177675, 'طماع', '<span class=\"hlight\">طماع .</span> <font color=\"DarkGreen\"><b>[ طَم ْ ما ]</font></b> (ع ص ) بسیارحرص . (منتخب اللغات ). طمعکننده . (مهذب الاسماء). پرطمع. طمعکار <span class=\"hlight\">:</span> او را یعقوب جندی گفتندی، شریری طماعی نادرستی ... (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٨٥</span>).<br /></font></div>'),
(177676, 'طماعة', '<span class=\"hlight\">طماعة.</span> <font color=\"DarkGreen\"><b>[ طَ ع َ ]</font></b> (ع مص ) طمع کردن . (تاج المصادر). طماعیة. (منتخب اللغات ). طمع داشتن . (منتخب اللغات ).<br /></font></div>'),
(177677, 'طماعی', '<span class=\"hlight\">طماعی .</span> <font color=\"DarkGreen\"><b>[ طَ عا ]</font></b> (ع ص، اِ) ج ِ طَمِع. (منتهی الارب ).<br /></font></div>'),
(177678, 'طماعیة', '<span class=\"hlight\">طماعیة.</span> <font color=\"DarkGreen\"><b>[ طَ ی َ ]</font></b> (ع مص ) طماع . طمع داشتن . (منتهی الارب ) (منتخب اللغات ). طمع کردن . (تاج المصادر).<br /></font></div>'),
(177679, 'طماغه', '<span class=\"hlight\">طماغه .</span> <font color=\"DarkGreen\"><b>[ طُ غ َ <span class=\"hlight\" dir=\"rtl\">/</span> غ ِ ]</font></b> (ترکی، اِ) رجوع به طماقه شود.<br /></font></div>'),
(177680, 'طماقطر', '<span class=\"hlight\">طماقطر.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) ساذج است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177681, 'طماقه', '<span class=\"hlight\">طماقه .</span> <font color=\"DarkGreen\"><b>[ طُ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (ترکی، اِ) طماقه و طماقة هر دو یکی است به ابدال قاف و غین معجمه به معنی کلاه باز و جُرّه و غیره، و این لفظ ترکی است . (غیاث ) (آنندراج ).<br /></font></div>'),
(177682, 'طمالیخ', '<span class=\"hlight\">طمالیخ .</span> <font color=\"DarkGreen\"><b>[طَ ]</font></b> (ع اِ) ابر تنک سپید پراکنده . (منتهی الارب ).<br /></font></div>'),
(177683, 'طمام', '<span class=\"hlight\">طمام .</span> <font color=\"DarkGreen\"><b>[ طَ م ِ ]</font></b> (اِخ ) شهری است بنزدیکی حضرموت و آنجا کوهی است بلند و گویند بر چکاد آن شمشیری نهاده شده است، چون آدمی بسوی آن نگرد یا دست بدان یازد باکی نبود اما چون آهنگ بردن آن کند از همه جانب سنگسار شود تا آنگاه که شمشیر ازدست فروگذارد. یاقوت پس از نقل این داستان گوید که این حکایت از اکاذیب است و من آن را محض یادآوری مسائل شگفت انگیزی که آورند یاد کردم . (معجم البلدان ).<br /></font></div>'),
(177684, 'طمان', '<span class=\"hlight\">طمان .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) ابن احمد العاملی ممدوح محقق از شیخ شمس الدین محمدبن صالح و از سید فخازبن معد الموسوی و دیگر مشایخ خویش روایت کردی، و نیز گویند از سید فخار و شیخ نجیب الدین بن نماز و گروهی دیگرروایت کرد و بر سید رضی الدین علی بن طاوس قرائت کردی و این مرد بسال <span class=\"hlight\" dir=\"rtl\">٦٣٤</span> هَ . ق . او را اجازت عطا فرمود و هم بدین سال از جهان درگذشت . گویند شهید در برخی از اجازات خویش آورده که پدر جمال الدین ابا محمد الملکی رحمه اﷲ از شاگردان شیخ علامه ٔ فاضل نجم الدین طوغان و از مترددین نزد وی در سفر خویش بحجاز بوده است . وفات طمان بزمین طیبه ٔ مطهره (مدینه ) در حدود سال <span class=\"hlight\" dir=\"rtl\">٧٢٨</span> هَ . ق . اتفاق افتاده است . (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>).<br /></font></div>'),
(177685, 'طمانین', '<span class=\"hlight\">طمانین .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (از ع، اِمص ) آرام و آرامش . (غیاث ) (آنندراج ).<br /></font></div>'),
(177686, 'طماچه', '<span class=\"hlight\">طماچه .</span> <font color=\"DarkGreen\"><b>[ طَ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ) سیلی . طپانچه : سمال پدر قبیله ای بدان جهت که شخصی را به طماچه کور کرد. (منتهی الارب ). سالقة؛ زنی که در مصیبت بسیار بانگ کند و روی خود را طماچه زند. (منتهی الارب ).<br /></font></div>'),
(177687, 'طمة', '<span class=\"hlight\">طمة.</span> <font color=\"DarkGreen\"><b>[ طُم ْ م َ ]</font></b> (ع اِ) پلیدی . <BR><font color=\"Blue\">◄</font> پاره ای از گیاه خشک . (منتهی الارب ).<br /></font></div>'),
(177688, 'طمث', '<span class=\"hlight\">طمث .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) برداشتن دوشیزگی . بکارت بردن . (منتخب اللغات ). آرمیدن با زن . (زوزنی ) (منتهی الارب ) (دهار) (تاج المصادر). <BR><font color=\"Blue\">◄</font> ریمناکی . خلاف طُهر. ریمناک شدن . (منتهی الارب ). چرکین شدن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> حائض شدن زن . (منتهی الارب ) (زوزنی ) (تاج المصادر) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> (اِ) حیض . (مهذب الاسماء). خون حیض زنان به عادت قاعده <span class=\"hlight\">:</span> <br />نه کمی در شهوت و طمث و بعال <br />که زنان را آید از ضعفت ملال .<br /> <font color=\"Red\">مولوی .</font><br />طفل ماهیت نداند طمث را<br />جز که گوئی هست چون حلوا تو را.<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">احتباس طمث </span> ؛ بند آمدن خون حیض <span class=\"hlight\">:</span> و آنجا که سبب <font color=\"DarkGreen\"><b>[ دوار]</font></b> مشارکت رحم و مثانه باشد. احتباس طمث یا اختناق رحم پیش آرد. (ذخیره ٔ خوارزمشاهی ).<br /><BR><font color=\"Blue\">◄</font> (مص ) بسودن هر چیز که باشد، و منه : ماطمث ذا المرتع قبلنا احدٌ و ماطمث هذه الناقة حبل قطّ؛ ای مامسها عقال ٌ. (منتهی الارب ). مساس . دست بچیزی رسانیدن . <BR><font color=\"Blue\">◄</font> فاسد شدن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> فساد. (منتهی الارب ).<br /></font></div>'),
(177689, 'طمح', '<span class=\"hlight\">طمح .</span> <font color=\"DarkGreen\"><b>[ طِ م َ ]</font></b> (ع اِ)درختی است (گویند هو بالظاء و الخاء المعجمتین و غلط، ابن عباد). (منتهی الارب ). درختی است که بدان دباغی کنند پوست را و چرم بدان سرخ برآید، و آن را عرنه نیز گویند. <BR><font color=\"Blue\">◄</font> یکی از دو گونه ثمر جوذر.<br /></font></div>'),
(177690, 'طمح', '<span class=\"hlight\">طمح .</span> <font color=\"DarkGreen\"><b>[ طَم َ ]</font></b> (اِخ ) بنوالطمح ؛ قبیله ای است . (منتهی الارب ).<br /></font></div>'),
(177691, 'طمح', '<span class=\"hlight\">طمح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) بلند نگریستن بچیز و بلند شدن نظر کسی . (منتهی الارب ). طماح . (زوزنی ). <BR><font color=\"Blue\">◄</font> برآمدن زن از خانه ٔ شوی و رفتن نزد اهل خود بی اجازت شوی . <BR><font color=\"Blue\">◄</font> نگریستن زن سوی مردان جز شوی . <BR><font color=\"Blue\">◄</font> رفتن و بردن چیزی را. <BR><font color=\"Blue\">◄</font> دور رفتن . (منتهی الارب ).<br /></font></div>'),
(177692, 'طمحات', '<span class=\"hlight\">طمحات .</span> <font color=\"DarkGreen\"><b>[ طَ م َ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (ع اِ) سختی های زمانه . (منتهی الارب ).<br /></font></div>'),
(177693, 'طمحان', '<span class=\"hlight\">طمحان .</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (اِخ ) نام مردی . صاحب عیون الاخبار درباره ٔ وی آرد: طمحان نزد قومی رفت که نزد آنان رنجوری بازمیگشت . طمحان آن قوم را بدین امر تسلیت گفت . گفتند وی نمرده است، طمحان بازگشت و چند بار تکرار کرد: انشأاﷲ میمیرد. (از عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢</span>).<br /></font></div>'),
(177694, 'طمحریر', '<span class=\"hlight\">طمحریر.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (ع ص ) کلان شکم . (منتهی الارب ).<br /></font></div>'),
(177695, 'طمخ', '<span class=\"hlight\">طمخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) تکبر و بزرگ منشی کردن، گویند: طَمَخ َ بأنفه ؛ ای تکبر. (منتهی الارب ).<br /></font></div>'),
(177696, 'طمخریر', '<span class=\"hlight\">طمخریر.</span> <font color=\"DarkGreen\"><b>[ طَ خ َ ]</font></b> (ع ص ) کلان شکم . (منتهی الارب ).<br /></font></div>'),
(177697, 'طمر', '<span class=\"hlight\">طمر.</span> <font color=\"DarkGreen\"><b>[ طِ م ِرر ]</font></b> (ع ص ) اسب نجیب نیکورو. (منتهی الارب ). اسب جهنده بلند. (دهار). اسب خمیده . (مهذب الاسماء). اسب درچیده و گرداندام . (منتهی الارب ). اسپ تازی و آماده ٔ جستن و دویدن و گرداندام و دراز پا. (منتخب اللغات ). طمرة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِخ ) ابناطمر؛ دو کوه است . (منتهی الارب ). دو کوه معروفست در بطن نخلة. (معجم البلدان ).<br /></font></div>'),
(177698, 'طمر', '<span class=\"hlight\">طمر.</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (ع مص ) آماسیدن دست . (منتهی الارب ) (منتخب اللغات ).<br /></font></div>'),
(177699, 'طمر', '<span class=\"hlight\">طمر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) پوشیدن در زمین . (منتهی الارب ). پوشیدن . در زیر خاک کردن . (منتخب اللغات ). پنهان کردن . (منتهی الارب ) (دهار) (تاج المصادر). <BR><font color=\"Blue\">◄</font> برجستن . (زوزنی ). برجستن بسوی نشیب یا بسوی هوا. طمار. طمور. (منتهی الارب ). جستن ببالا یا بپائین . <BR><font color=\"Blue\">◄</font> آماس کردن زخم . (منتخب اللغات ). آماسیدن زخم . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پر کردن مطموره یعنی ته خانه از طعام و جز آن . (منتخب اللغات ). پر کردن مطموره از طعام و جز آن . <BR><font color=\"Blue\">◄</font> طُمِر فی ضریعه (مجهولاً)؛ درد کرد دندان او. (منتهی الارب ).<br /></font></div>'),
(177700, 'طمر', '<span class=\"hlight\">طمر.</span> <font color=\"DarkGreen\"><b>[طِ ]</font></b> (ع اِ) جامه ٔ کهنه . (منتهی الارب ) (منتخب اللغات ) (مهذب الاسماء). گلیم کهنه غیر صوف . (منتخب اللغات ). چادر کهنه ٔ غیر پشمین . ج، اطمار. (منتهی الارب ).<br /></font></div>'),
(177701, 'طمر', '<span class=\"hlight\">طمر.</span> <font color=\"DarkGreen\"><b>[ طُم ْ م َ ]</font></b> (ع اِ) بیخ و بن . طمور. (منتهی الارب ). اصل . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> (اِمص ) غفلت . <BR><font color=\"Blue\">◄</font> نادانی، گویند: انت فی طمرک الذی کنت ؛ ای غرتک و جهلک . (منتهی الارب ).<br /></font></div>'),
(177702, 'طمرا', '<span class=\"hlight\">طمرا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) بیدانجیر را گویند. آن دانه ای باشد که از آن روغن گیرند و بعربی خروع خوانند. (برهان ) (آنندراج ). خروع . کرچک . به رومی خروع است . (فهرست مخزن الادویه ). خروع است . (اختیارات بدیعی ). رجوع به دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦</span> شود.<br /></font></div>'),
(177703, 'طمراخ', '<span class=\"hlight\">طمراخ .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) لقب والد علی بن ابی هاشم . (منتهی الارب ).<br /></font></div>'),
(177704, 'طمرر', '<span class=\"hlight\">طمرر.</span> <font color=\"DarkGreen\"><b>[ طِ رِ ]</font></b> (ع ص ) اسپ نیکورو درچیده ٔ گرداندام . (منتهی الارب ).<br /></font></div>'),
(177705, 'طمرس', '<span class=\"hlight\">طمرس .</span> <font color=\"DarkGreen\"><b>[ طِ رِ ]</font></b> (ع ص ) دروغگوی . (منتهی الارب ) (منتخب اللغات ). دروغزن . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> ناکس . فرومایه . (منتهی الارب ).<br /></font></div>'),
(177706, 'طمرسة', '<span class=\"hlight\">طمرسة.</span> <font color=\"DarkGreen\"><b>[ طَ رَ س َ ]</font></b> (ع مص ) ترنجیدن . <BR><font color=\"Blue\">◄</font> سپسایگی رفتن . (منتهی الارب ).<br /></font></div>'),
(177707, 'طمرور', '<span class=\"hlight\">طمرور.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) شقراق . (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> مرغیست مختلف الالوان که اخیل نامند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> چادر کهنه که از پشم گوسفند نباشد. <BR><font color=\"Blue\">◄</font> (ص ) آنکه چیزی ندارد. <BR><font color=\"Blue\">◄</font> اسپ نجیب نیکورو. اسپ درازپای سبک اندام . اسپ آماده ٔ دویدن و برجستن . (منتهی الارب ).<br /></font></div>'),
(177708, 'طمروس', '<span class=\"hlight\">طمروس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) نان کوماج . <BR><font color=\"Blue\">◄</font> بره . <BR><font color=\"Blue\">◄</font> اسب کره ٔ ششماهه . <BR><font color=\"Blue\">◄</font> (ص ) مرد دروغگوی . (منتهی الارب ). سخت دروغزن . (مهذب الاسماء). دروغگوی . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> ناکس . (منتهی الارب ).<br /></font></div>'),
(177709, 'طمریر', '<span class=\"hlight\">طمریر.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) اسپ نیکورو. اسپ آماده ٔ جستن . (منتهی الارب ).<br /></font></div>'),
(177710, 'طمس', '<span class=\"hlight\">طمس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) ناپدید کردن . (زوزنی ) (دهار) (تاج المصادر). ناپیدا کردن . ناپدید کردن و ناپیدا شدن (لازم و متعدی ). (منتهی الارب ) <span class=\"hlight\">:</span> جبرئیل بادی در روی ایشان دمید طمس شدند، و طمس آن باشد که چشم و دهان و بینی یکی شود و روی ناپدید شود. فطمسنا اعینهم فذوقوا عذابی و نذر . (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>). نشان چیزی بردن . (منتخب اللغات ). ستردن . زدودن <span class=\"hlight\">:</span> <br />قصه ٔ شمس و تبسمهای شمس <br />وآن عروسان چمن را لمس و طمس .<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> از بیخ و بن برکندن چیزی را و ناپدید کردن نشان آنرا. و منه : اذا النجوم طمست و ربنا اطمس علی اموالهم ؛ ای اهلکها و استأصلها. (منتهی الارب ). محو کردن . (زوزنی ) (تاج المصادر). کور کردن و برابر و بی نشان کردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> هلاک کردن . <BR><font color=\"Blue\">◄</font> نظر دور کردن . (منتخب اللغات ). دور نگریستن . <BR><font color=\"Blue\">◄</font> دوری گزیدن . <BR><font color=\"Blue\">◄</font> روشنی بردن .(منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اصطلاح صوفیه ) ذهاب رسوم و عادات است بالکلیه در صفات حق تعالی و این انتهای مرتبه است . (غیاث ) (آنندراج ). صاحب کشاف اصلاحات الفنون گوید: نزد صوفیه عبارتست از رفتن سایر صفات بشریت در صفات انوار ربوبیت . کذا نقل عن شیخ عبدالرزاق الکاشی و هکذا فی کشف اللغات . <BR><font color=\"Blue\">◄</font> (اصطلاح عروض ) آنست که از فاع لاتن مفروق الوتد پس از اسقاط هر دو سبب عین نیز ساقط گردانی فا بماند. (المعجم ).<br /></font></div>'),
(177711, 'طمستان', '<span class=\"hlight\">طمستان .</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (اِخ ) (بلفظ تثنیه، شاید از طم و ستان مانند دهستان و مانند آن ) شهری است در فارس و گروهی از رواة بدانجا منسوبند. (معجم البلدان ).<br /></font></div>'),
(177712, 'طمسل', '<span class=\"hlight\">طمسل .</span> <font color=\"DarkGreen\"><b>[ طُ س ُ ]</font></b> (ع اِ) دزد. ج، طماسلة. (منتهی الارب ).<br /></font></div>'),
(177713, 'طمسلة', '<span class=\"hlight\">طمسلة.</span> <font color=\"DarkGreen\"><b>[ طَس َ ل َ ]</font></b> (ع مص ) عاجز گردیدن از زن . (منتهی الارب ).<br /></font></div>'),
(177714, 'طمسلی', '<span class=\"hlight\">طمسلی .</span> <font color=\"DarkGreen\"><b>[ طَ س َ لا ]</font></b> (ع اِ) بلا. سختی . گویند: هو یمشی الی الطمسلی ؛ ای الضراء. <BR><font color=\"Blue\">◄</font> (اِمص ) نقصان . (منتهی الارب ).<br /></font></div>'),
(177715, 'طمش', '<span class=\"hlight\">طمش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) مردم . گویند: ما ادری ای الطمش هو؛ ای ای ّ الناس ؛ یعنی ندانم که چه مرد است او. ج، طموش . گویند: وحش و لا طمش من الطموش . (منتهی الارب ).<br /></font></div>'),
(177716, 'طمطام', '<span class=\"hlight\">طمطام .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) میانه ٔ دریا. (منتهی الارب ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> معظم دریا. <BR><font color=\"Blue\">◄</font> معظم از هر چیز. (منتهی الارب ).<br /></font></div>'),
(177717, 'طمطراق', '<span class=\"hlight\">طمطراق .</span> <font color=\"DarkGreen\"><b>[ طُ طُ ]</font></b> (ع اِ) بمعنی طاق و ترنب است که کرو فر و خودنمائی باشد. (برهان ). کر و فر و شأن و تجمل . صاحب مؤید نوشته که طم بمعنی علو و طراق بمعنی آوازه ٔ خوش و طمطراق از این مرکبست . (غیاث ) (آنندراج ). این کلمه صورة عربیست . در قاموس نیافتم . کلمه ٔ طمطراک در بیت ذیل ِ بندار رازی آمده است <span class=\"hlight\">:</span> <br />مرا گویند زن کن زآنکه اندر دل هلاک آیی <br />عروسک پرجهیزک پر ز جامه طمطراک آیی .<br />گویی ازبهرحرمت علم است <br />اینهمه طمطراق و جنگ و سمند.<br /> <font color=\"Red\">سنائی .</font><br />مرا بمنزل الا الذین فرودآورد<br />فروگشای ز من طمطراق الشعرا.<br /> <font color=\"Red\">خاقانی .</font><br />گفتمی از لطف تو جزوی ز صد<br />گر نبودی طمطراق چشم بد.<br /> <font color=\"Red\">مولوی .</font><br />زین لسان الطیر علم آموختند<br />طمطراق سروری اندوختند.<br /> <font color=\"Red\">مولوی .</font><br />وز غلو خلق و مکث و طمطراق <br />تافت بر آن مار خورشید عراق .<br /> <font color=\"Red\">مولوی .</font><br />خود کسی کاین سعادتش باشد<br />هست شاهی و طمطراقش نیست .<br /> <font color=\"Red\">ابن یمین .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">ای خداوندان طاق و طمطراق نمی آزرد طلاق </span> .<br /></font></div>'),
(177718, 'طمطم', '<span class=\"hlight\">طمطم .</span> <font color=\"DarkGreen\"><b>[ طِ طِ ]</font></b> (ع ص ) رجل ٌ طمطم ؛ مرد سخن ناسره گوی . خلاف فصیح . رجل طمطمی .(منتهی الارب ). مرد غیرفصیح که زبانش درست نباشد. (منتخب اللغات ). بسته زبان . ج، طماطم . (مهذب الاسماء).<br /></font></div>'),
(177719, 'طمطم', '<span class=\"hlight\">طمطم .</span> <font color=\"DarkGreen\"><b>[طَ طَ ]</font></b> (اِ) تمتم که سماق باشد. (فهرست مخزن الادویه ). سماق . (اختیارات بدیعی ) (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(177720, 'طمطمانی', '<span class=\"hlight\">طمطمانی .</span> <font color=\"DarkGreen\"><b>[ طُ طُ نی ی ]</font></b> (ع ص ) رجل طمطمانی ؛ مرد کنکلاج . (منتهی الارب ).<br /></font></div>'),
(177721, 'طمطمانیة', '<span class=\"hlight\">طمطمانیة.</span> <font color=\"DarkGreen\"><b>[ طُ طُ نی ی َ ]</font></b> (ع اِ) (... حِمْیَر) سخنان زشت که در لغت حمیر است . (منتهی الارب ).<br /></font></div>'),
(177722, 'طمطمة', '<span class=\"hlight\">طمطمة.</span> <font color=\"DarkGreen\"><b>[ طَ طَ م َ ]</font></b> (ع مص ) شنا کردن . <BR><font color=\"Blue\">◄</font> سخن بزبان عجم گفتن . (منتهی الارب ).<br /></font></div>'),
(177723, 'طمطمی', '<span class=\"hlight\">طمطمی .</span> <font color=\"DarkGreen\"><b>[ طِ طِ می ی ]</font></b> (ع ص ) مرد سخن ناسره گوی . خلاف فصیح . رجل طمطم . (منتهی الارب ).<br /></font></div>'),
(177724, 'طمع', '<span class=\"hlight\">طمع.</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (ع مص )طماع . (منتهی الارب ). طماعیة. (منتهی الارب ) (تاج المصادر). آزمند گردیدن . حریص گشتن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> امید داشتن . (منتهی الارب ) (منتخب اللغات ). زعم . (دهار) (تاج المصادر). ازعام . (تاج المصادر).<br /></font></div>'),
(177725, 'طمع', '<span class=\"hlight\">طمع.</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (ع اِمص، اِ) بیوس . (مهذب الاسماء). انتظار. <BR><font color=\"Blue\">◄</font> روزی لشکر. (مهذب الاسماء). مرسوم سپاه . (منتخب اللغات ). مرسوم لشکر. (آنندراج ). گویند:امرهم الامیر باطماعهم . علوفه ٔ لشکر. <BR><font color=\"Blue\">◄</font> اوقات گرفتن مرسوم لشکر. <BR><font color=\"Blue\">◄</font> امید. (منتهی الارب ). امید داشتن (آنندراج ). چشمداشت و توقع. <BR><font color=\"Blue\">◄</font> حرص . (منتخب اللغات ). الچخت . آز. (منتهی الارب ) (آنندراج ). آزمند گردیدن و حریص گشتن . (آنندراج ). اشتها و میل بیحدی را گویند که در شخص یافت شود اگرچه آن میل نسبت به اشیاء جایز بوده باشد. (قاموس کتاب مقدس ). و در فارسی با لفظ بستن و کردن و داشتن و گسستن و بریدن مستعمل . (آنندراج ). این کلمه در اشعار فارسی گاه بفتح اول و سکون دوم بکار رود <span class=\"hlight\">:</span> <br />اگر شوخ بر جامه ٔ من بود<br />چه باشد دلم از طمع هست پاک .<br /> <font color=\"Red\">خسروی .</font><br />به طَمْع بزرگیم بِدْهی بباد<br />بدان اژدهاپیکر دیوزاد.<br /> <font color=\"Red\">فردوسی .</font><br />به طَمْع بزرگی نگه داردم <br />به ضحاک ناپاک بسپاردم .<br /> <font color=\"Red\">فردوسی .</font><br />اگر بدرگاه عالی پس از این هزار مهم افتد و طمع آن باشد که من به تن خویش بیایم نباید خواند که البته نیایم . (تاریخ بیهقی ). پس از وفات پدر بر آن جمله رفته است تا باد پادشاهی بر سر وی شد و طمع فرمان دادن . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢١٦</span>). اما بیرون از خواجه ٔ بزرگ احمد حسن وزراء نهانی بودند که صلاح کار نیکو نگاه نتوانستندی داشت و ازبهر طمع خود را کارها پیوستند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٥٧</span>).<br />طمع پیر و جوان باز چو شیطان رجیم .<br /> <font color=\"Red\">ابوحنیفه ٔ اسکافی .</font><br />مکن دزدی و چیز دزدان مخواه <br />تن از طَمْع مفکن بزندان و چاه .<br /> <font color=\"Red\">اسدی .</font><br />اگر خواهی از شمار آزادمردان باشی طمع را در دل خویش جای مده . (قابوسنامه ).<br />آزاد شوی چون الف اگرچند<br />امروز بزیر طمع چو دالی .<br /> <font color=\"Red\">ناصرخسرو</font><br />آزادگی و طمع بهم ناید<br />من کرده ام آزمون بصد مره .<br /> <font color=\"Red\">ناصرخسرو.</font><br />کآن مرد سوی اهل خردسست بود سخت <br />کز بهر طمع سست بود سخت کمانیش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مر باز جهان را به تن تذروی <br />مر یوز طمع را به دل غزالی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />با عقل مکن یار مر طمع را<br />شاید که نخواهی ز مار یاری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گر بلند است درِ میر تو سر پست مکن <br />بطمع گردن آزاد چنین سخت مبند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />گردن از بار طمع لاغر و باریک شود<br />این نوشته ست زرادشت سخندان در زند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />مرد غواص بدریای بزرگ اندر<br />جان شیرین بدهد بر طمع مرجان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چند گردی گرد این و آن به طَمْع جاه و مال <br />کز طمع هرگز نیابی چیز جز درد و بلا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />به طَمْع سود درطبع است نادان را زیان کردن .<br /> <font color=\"Red\">قطران .</font><br />طمع آسان ولی طلب صعب است <br />صعبی ِ یافت از طلب بتر است .<br /> <font color=\"Red\">خاقانی .</font><br />درآرد طمع مرغ و ماهی به بند.<br /><font color=\"Red\">سعدی .</font><br />بی طمع نشنیده ام از خاص و عام <br />من سلامی ای برادر والسلام .<br /> <font color=\"Red\">مولوی .</font><br />گر ترازو را طمع بودی بمال <br />راست چون گفتی تو را از وصف حال .<br /> <font color=\"Red\">مولوی .</font><br />هرکه را باشد طمع الکن شود<br />با طمع کی چشم دل روشن شود.<br /> <font color=\"Red\">مولوی .</font><br />هر جا طمع وجود ندارد بخیل نیست .<br /> <font color=\"Red\">صائب .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">طمع آرد بمردان رنگ زردی </span> .<br />طمعرا سه حرفست هر سه تهی .<br /> <font color=\"Red\">؟ (از آنندراج ).</font><br />لفظ طمع پساوند مانند به آخر برخی از کلمات ملحق شود و افاده ٔ معانی خاص کند چون بی طمع، پرطمع، خام طمع و...<br /></font></div>'),
(177726, 'طمع', '<span class=\"hlight\">طمع.</span> <font color=\"DarkGreen\"><b>[ طَ م ِ <span class=\"hlight\" dir=\"rtl\">/</span> م ُ ]</font></b> (ع ص ) آزمند. (منتهی الارب ). حریص . (منتهی الارب ) (منتخب اللغات ). مرد طامع. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> امیددارنده . ج، طَمِعون، طُمَعاء، طُماعی ̍. (منتهی الارب ). امیدوار. مرد بسیارآرزو. (دهار).<br /></font></div>'),
(177727, 'طمع آمدن', '<span class=\"hlight\">طمع آمدن .</span> <font color=\"DarkGreen\"><b>[ طَ م َ م َ دَ ]</font></b> (مص مرکب ) طمع کردن . طمع بستن . آزمند گردیدن <span class=\"hlight\">:</span> امیر را بر وی طمع آمد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>).<br /></font></div>'),
(177728, 'طمع افتادن', '<span class=\"hlight\">طمع افتادن .</span> <font color=\"DarkGreen\"><b>[ طَ م َ اُ دَ ]</font></b> (مص مرکب ) طمع کردن . طمع آمدن . آزمند گردیدن . امید بستن <span class=\"hlight\">:</span> و ما را <font color=\"DarkGreen\"><b>[ مسعود ]</font></b> چنان ماند از بیعدتی ولشکر که هر کسی را در ما طمع افتاد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢١٦</span>). امیر گفت علی تکین دشمن بزرگست و طمع وی که افتاده است محالست صواب آن باشد که وی را از ماوراءالنهر برکنده آید. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٤٣</span>).<br /></font></div>'),
(177729, 'طمع افکندن', '<span class=\"hlight\">طمع افکندن .</span> <font color=\"DarkGreen\"><b>[ طَ م َ اَک َ دَ ]</font></b> (مص مرکب ) اِطماع . تطمیع. (تاج المصادر).<br /></font></div>'),
(177730, 'طمع برداشتن', '<span class=\"hlight\">طمع برداشتن .</span> <font color=\"DarkGreen\"><b>[ طَ م َ ب َ ت َ ]</font></b> (مص مرکب ) طمع بریدن . ترک آز <span class=\"hlight\">:</span> <br />آنکه او انعام از من بازگیرد تو نه ای <br />و آنکه او از تو طمع بردارد آن هم من نیم .<br /><font color=\"Red\">مجیرالدین بیلقانی .</font><br /></font></div>'),
(177731, 'طمع بردن', '<span class=\"hlight\">طمع بردن .</span> <font color=\"DarkGreen\"><b>[ طَ م َ ب ُ دَ ]</font></b> (مص مرکب ) آزمند گردیدن . صاحب آنندراج آرد: در این بیت طمع بردن بمعنی حاجت بردن آمده <span class=\"hlight\">:</span> <br />طمع برد شوخی بصاحبدلی <br />نبود آن زمان در میان حاصلی .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(177732, 'طمع بریدن', '<span class=\"hlight\">طمع بریدن .</span> <font color=\"DarkGreen\"><b>[ طَ م َ ب ُ دَ ]</font></b> (مص مرکب ) امید برداشتن . ترک آز کردن . قطع امید کردن . ترک چشم داشت . طمع گسستن . رجوع به طمع گسستن شود <span class=\"hlight\">:</span> <br />از دانه طمع ببر که رستی از دام .<br />چون تو طمع از جهان بریدی <br />دانی که همه جهان کریمند.<br /> <font color=\"Red\">رودکی .</font><br /> <font color=\"Red\">(منسوب به بایزید بسطامی ).</font><br />اگر می خواهد که ازین قال و قیل برهد و طمع جهانیان از ولایت وی بریده گردد چرا بنام سلطان خطبه نکند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٦٨٥</span>).<br />طمع چون بریدم من از مال خواجه <br />زنش غرکه خود راکم از خواجه داند.<br /><font color=\"Red\">ابن یمین .</font><br /></font></div>'),
(177733, 'طمع بستن', '<span class=\"hlight\">طمع بستن .</span> <font color=\"DarkGreen\"><b>[ طَ م َ ب َ ت َ ]</font></b> (مص مرکب ) طمع دربستن . طمع کردن . آزمند گردیدن . طمع افتادن . طمع آمدن . حریص گردیدن <span class=\"hlight\">:</span> <br />بر در میرتو ای بیهده بستی طمعی <br />از طمع صعب تر آن را که نه قید است و نه بند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />طمع بند و دفتر ز حکمت بشوی .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(177734, 'طمع خام', '<span class=\"hlight\">طمع خام .</span> <font color=\"DarkGreen\"><b>[ طَ م َ ع ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) تمنای امری که ممکن نباشد. (غیاث ). کنایه از توقع داشتن بچیزی است که ممکن الحصول نباشد. (برهان ). هوس بی حاصل و تمنای امری که ممکن نباشد. (آنندراج ) <span class=\"hlight\">:</span> <br />عکس روی تو چو در آینه ٔ جام افتاد<br />عارف از خنده ٔ می در طمع خام افتاد.<br /> <font color=\"Red\">حافظ.</font><br />طمع خام بین که قصه ٔ فاش <br />از رقیبان نهفتنم هوس است .<br /> <font color=\"Red\">حافظ.</font><br />خاک دارد فلک از کاسه ٔ امّید دریغ<br />طمع خام ازو آب بقا میخواهد.<br /> <font color=\"Red\">طالب کلیم .</font><br />من کجا آرزوی وصل دلارام کجا<br />دل نومید کجا این طمع خام کجا.<br /> <font color=\"Red\">محمدقلی میلی .</font><br />ما دل به چین زلف دلارام بسته ایم <br />در باده ٔ لبش طمع خام بسته ایم .<br /><font color=\"Red\">شاهی سبزواری (از آنندراج ).</font><br /></font></div>'),
(177735, 'طمع داشتن', '<span class=\"hlight\">طمع داشتن .</span><font color=\"DarkGreen\"><b>[ طَ م َ ت َ ]</font></b> (مص مرکب ) آزمند بودن . چشم داشتن . حریص بودن . عسم . (فرهنگ اسدی خطی نخجوانی ) <span class=\"hlight\">:</span> <br />تو طمع زو مدار میوه و گل <br />یار بد هست بابت سرپل .<br /> <font color=\"Red\">سنایی .</font><br />بتبع سلف رستگاری طمع میدارد. (کلیله و دمنه ).<br />از نخشبی مدار طمع در جهان کرم <br />نخ نام دیو باشد و شب تیرگی و غم .<br /> <font color=\"Red\">؟ (از صحاح الفرس ).</font><br />طمع دارم که گر ناگه شگرفی <br />بخواند زین محبت نامه حرفی .<br /> <font color=\"Red\">جامی .</font><br />مدار از منزل آرایان طمع معماری دلها<br />که وسعت رفت از دست و دل مردم به منزلها.<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br />بد میکنی و نیک طمع میداری <br />خود بدباشد جزای بدکرداری .<br /><font color=\"Red\">؟</font><br /></font></div>'),
(177736, 'طمع دربستن', '<span class=\"hlight\">طمع دربستن .</span> <font color=\"DarkGreen\"><b>[ طَ م َ دَ ب َ ت َ ]</font></b> (مص مرکب ) رجوع به طمع بستن شود <span class=\"hlight\">:</span> روباه ... طمع دربست که گوشت و پوست او فراخور آواز باشد. (کلیله و دمنه ).<br /></font></div>'),
(177737, 'طمع کردن', '<span class=\"hlight\">طمع کردن .</span> <font color=\"DarkGreen\"><b>[ طَ م َ ک َ دَ ]</font></b> (مص مرکب ) حرص ورزیدن . آزمند گردیدن . چشم داشتن . امید بستن . طمع آمدن . طمع بستن . طمع افتادن . جعم . (تاج المصادر) (منتهی الارب ). عسم . (فرهنگ اسدی خطی نخجوانی ) <span class=\"hlight\">:</span> <br />به خارپشت نگه کن که از درشتی موی <br />به پوست او نکند طَمْع پوستین پیرای .<br /> <font color=\"Red\">کسائی .</font><br />شام کنی طَمْع چو گیری عراق <br />مصرت پیش است چو رفتی بشام .<br /> <font color=\"Red\">ناصرخسرو.</font><br />با محنتش به نعمتش اندر مکن طمع<br />زیرا ز نعمتش نشود دور محنتش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آنچه دی کاشته ای میکنی امروز درو<br />طمع خوشه ٔ گندم مکن از دانه ٔ جو.<br /> <font color=\"Red\">ظهیر.</font><br />طمع کرده بودم که کرمان خورم <br />بناگاه خوردند کرمان سرم .<br /> <font color=\"Red\">سعدی .</font><br />طمع در آن لب شیرین نکردنم اولی است <br />ولی چگونه مگس از پی شکر نرود.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(177738, 'طمع گسستن', '<span class=\"hlight\">طمع گسستن .</span> <font color=\"DarkGreen\"><b>[طَ م َ گ ُ س َس ْ ت َ ]</font></b> (مص مرکب ) طمع بریدن . قطع امید کردن . دل برداشتن . صرف نظر کردن . ترک آز <span class=\"hlight\">:</span> <br />سزد که بگسلم از یار سیم دندان طَمْع<br />سزد که او نکند طَمْع پیر دندان کَرْو.<br /> <font color=\"Red\">کسائی .</font><br />طمع بند و دفتر ز حکمت بشوی <br />طمع بگسل و هرچه خواهی بگوی .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(177739, 'طمعان', '<span class=\"hlight\">طمعان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (بنی ...) نام محلی به هفت فرسنگی موصل و هفت فرسنگی حدیثه، و حدیثه در سی وشش فرسنگی بغداد واقعست . (نزهة القلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span>).<br /></font></div>'),
(177740, 'طمعون', '<span class=\"hlight\">طمعون .</span> <font color=\"DarkGreen\"><b>[ طَ م ِ ]</font></b> (ع ص، اِ) ج ِ طَمِع. (منتهی الارب ).<br /></font></div>'),
(177741, 'طمغ', '<span class=\"hlight\">طمغ.</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (ع مص ) بسیار روان شدن خیم چشم .گویند: طمغت عینه ؛ اذا اکثر غمصها. (منتهی الارب ).<br /></font></div>'),
(177742, 'طمغا', '<span class=\"hlight\">طمغا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (مغولی، اِ) نقش نشان و مهر خاص شاه بر فرمانها. رجوع به آل تمغا و آل طمغی و تمغا شود <span class=\"hlight\">:</span> ملطفه ها را نزدیک امیر برد همه نشان طمغا داشت و به طغرل و داود و یبغو و ینالیان بود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٣٨</span>).<br /></font></div>'),
(177743, 'طمغاج', '<span class=\"hlight\">طمغاج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) حقیقت مسمای این کلمه به نحو یقین معین نشد ولی بطور تقریب معلوم است که طمغاج نام ناحیه یا شهری بوده در اقصی ترکستان شرقی در حدود چین یا در داخلی ِ چین شمالی <span class=\"hlight\">:</span> <br />خود دل و طبع او ز سیم و شکر<br />کان طمغاج و باغ شوشتر است .<br /> <font color=\"Red\">خاقانی .</font><br />صاحب کتاب طبقات ناصری اطلاعات ذیل را شفاهاً از سید اجل بهاءالدین رازی (سفیر خوارزمشاه به دربار چنگیز) گرفته و گوید: چون بحدود طمغاج و نزدیک دارالملک آلتون خان رسیدیم از مسافت دور پشته ٔ بلندی سپید «در نظر آمد...» . و جای دیگر کلمه ٔ طمغاج و تنگت را با هم آورده و گوید: «جماعتی از ثقات چنین روایت کرده اند که در تواریخ ماتقدم و ایام سالفه و قرون ماضیه دربلاد ترکستان و ممالک چین و تنگت و طمغاج هرگز پادشاهی کریم و نیکواخلاق تر از اکتای پای در رکاب نکرده است . <br />محمدبن احمد النسوی در سیره ٔ جلال الدین منکبرنی (چ پاریس صص <span class=\"hlight\" dir=\"rtl\">٤</span>-<span class=\"hlight\" dir=\"rtl\">٥</span>) گوید: حدثنی غیر واحد ممن یعتبر بقولهم ان ملک الصین ملک متسع دوره مسیرة ستة اشهر و قد قیل انه یحویه سور واحد و لم ینقطع الا عند الجبال المنیعة و الانهار الوسیعة و قدانقسم من قدیم الزمان الی ستة اجزاء منها مسیرة شهریتولی امره خان ای ملک بلغتهم نیابة عن خانهم الاعظم و کان خانهم الکبیر الذی عاصر السلطان محمد <font color=\"DarkGreen\"><b>[ بن تکش ]</font></b> التون خان توارثها کابراً عن کابر بل کافراً عن کافر و من عادتهم الاقامة بطمغاج و هی واسطة الصین و نواحیها...». و کمی پس از آن گوید: «فلما عاد آلتون خان الی مدینة المعروفة بطمغاج اخذ الحجاب علی عادتهم یعرضون کل یوم عدة قضایا مما حدث مدة غیبة...». در تقویم البلدان لابی الفداء در جدول بلاد چین نقلاً عن تاریخ النسوی المذکور می نویسد: و من تاریخ النسوی الذکری ذکر فیه اخبار خوارزم شاه و النهر (ظ: التتر) ان قاعدة ملک التتر بالصین اسمها طومحاج (ظ: طومخاج ).» زکریابن محمد قزوینی در آثار البلاد (چ ووستنفلد ص <span class=\"hlight\" dir=\"rtl\">٢٧٥</span>) گوید: طمغاج مدینة مشهورة کبیرة من بلاد الترک ذات قری ً کثیرة و قراها بین جبلین فی مضیق لا سبیل الیها الا من ذلک المضیق و لایمکن دخولها لو منع مانع فلایتعرض لها احد من ملوک الترک لعلمهم بأن قصدها غیرمفید و سلطانها ذو قدر و مکانة عند ملوک الترک و بها معدن الذهب فلذلک کثر الذهب عندهم حتی اتخذوا منها الظروف و الاوانی و اهلها زُعر لاشعر علی جسدهم و نساؤهم علی السواء فی ذلک ... و حکی الامیر ابوالمؤیدبن النعمان ان بها عینین . احدیهماعذب و الاخری ملح و هما تنصبان الی حوض و تمتزجان فیه، و تمتد من الحوض ساقیتان، احداهما عذب لا ملوحة فیه و الاخری ملح و ذکر انه من کرامات رجل صالح اسمه ملیح الملاح وصل الی ملک الدّیّار و دعا اهلها الی الاسلام و ظهر من کراماته امر هذا الحوض و السواقی فاسلم بعض اهلها و هم علی الاسلام الی الاَّن ». و خلاصه ٔ این کلمه در یکی از قصاید مختاری غزنوی در مدح علاءالدوله محمد ملقب به ارسلان خان از ملوک خانیه ٔ ماوراءالنهر مذکور است، مطلع قصیده اینست :<br />خرگه خاقان ترکستان شده مالک رقاب <br />آسمان است و جمال ارسلان شه آفتاب .<br />و در وصف مجلس بزم خاقان گوید: از جمله ابیاتی :<br />ساقیان نادره گوینده ٔ شیرین ادا<br />مطربان چابک طمغاجی حاضرجواب .<br /> <font color=\"Red\">(حواشی چهارمقاله ٔ عروضی چ لیدن ص <span class=\"hlight\" dir=\"rtl\">٩٤</span>).</font><br />احتمالاً کلمه ٔ طفقاج (تفغاج ) باشد که بر ماچین اطلاق می شده است . رجوع به طفقاج در دیوان لغات الترک محمود کاشغری چ استامبول <span class=\"hlight\" dir=\"rtl\">١٣٣٣</span> هَ . ق . ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٨</span> شود.<br /></font></div>'),
(177744, 'طمغاج', '<span class=\"hlight\">طمغاج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام ولیعهد تکش به ری . بگفته ٔ صاحب حبیب السیر، پس از آنکه میان سلطان تکش خوارزمشاه وطغرل سلجوقی صلح افتاد بنواحی ری و طغرل ولایت ری رابدیوان خوارزمشاه بازگذارد بدان شرط که تکش متعرض دیگر ولایات نگردد، خوارزمشاه این طمغاج را به ری ولیعهد خویش گردانید و روی به صوب خوارزم آورد. طغرل بسال <span class=\"hlight\" dir=\"rtl\">٥٨٩</span> هَ . ق . به ری رفت و قلعه ٔ طبرک را از طمغاج بستاند و وی را بقتل رسانید. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨٨</span>).<br /></font></div>'),
(177745, 'طمغاج خان', '<span class=\"hlight\">طمغاج خان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) بیشتر ملوک ترک معروف به خانیه که پیش از مغول در نواحی ناحیت یا شهر طمغاج سلطنت داشته اند ملقب به طمغاج خان باشند. شاید طمغاج خان بمعنی خان طمغاج باشد مانند بخاراخداه و امثال آن در فارسی . بگفته ٔ صاحب برهان و آنندراج و اسدی در فرهنگ، طمغاج خان نام پادشاه سمرقند بودو برخی گویند نام پادشاه تبت و یغماست <span class=\"hlight\">:</span> <br />تاج برْبود از سر مهراج زنگ <br />یاره ٔ طمغاج خان کرد آفتاب .<br /> <font color=\"Red\">خاقانی .</font><br />کیخسرو هدی که غلامانْش را خراج <br />طمغاج خان به تبت و یغما برافکند.<br /> <font color=\"Red\">خاقانی .</font><br />رجوع به توضیح طمغاج و طفقاج شود.<br /></font></div>'),
(177746, 'طمغاج خان', '<span class=\"hlight\">طمغاج خان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن بغراخان . خان ترکستان از معاصرین مسعود و محمود غزنوی و پدر تَرکان خاتون زوجه ٔ ملکشاه سلجوقی که سلطان سلجوقی بسال <span class=\"hlight\" dir=\"rtl\">٤٧١</span> هَ . ق . پس از فتح سمرقند وی را بحباله ٔ نکاح خویش آورد. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٣</span>).<br /></font></div>'),
(177747, 'طمغاج خان', '<span class=\"hlight\">طمغاج خان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (قلج ...) مسعودبن حسن . ممدوح سوزنی سمرقندی شاعر <span class=\"hlight\">:</span> <br />شاهنشه ملوک و سلاطین شرق و غرب <br />صاحبقران روی زمین خسرو زمان <br />طمغاج خان عادل سلطان گوهری <br />از نفس خویش تا ملک افراسیاب خان <br />خورشید ملک داران مسعودبن حسن <br />کز کاخ اوست مطلع خورشید آسمان .<br /> <font color=\"Red\">سوزنی .</font><br />آفرین گویان چو گویند آفرین در هر دیار<br />بر قلج طمغاج خان آن شاه اعدامال باد.<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(177748, 'طمغاج خان', '<span class=\"hlight\">طمغاج خان .</span> <font color=\"DarkGreen\"><b>[طَ ]</font></b> (اِخ ) از ملوک ترک ماوراءالنهر معروف به افراسیابیه و خانیه . رجوع به جهانگشای جوینی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤</span> شود.<br /></font></div>'),
(177749, 'طمغاجی', '<span class=\"hlight\">طمغاجی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ترکی، ص مرکب، اِ مرکب ) این کلمه صورتی از تمغاچی است که زننده ٔ تمغا بر فرمانها یا بارها و عدلها باشد و ظاهراً وقتی معنی مجازی نیز گرفته است بمعنی شوخ و عیار و فریبنده در صفت معشوقه <span class=\"hlight\">:</span> <br />ساقیان نادره گوینده ٔ شیرین ادا<br />مطربان چابک طمغاجی حاضرجواب .<br /><font color=\"Red\">مختاری غزنوی .</font><br /> <br />و کلمه مرکب از دو کلمه ٔ طمغا (تمغا) و چی حرف نسبت ترکی، و این نوع نقل در تداول ترکی و فارسی معمولست چنانکه گویند فلان قاطرچی است، یعنی سخت بی ادب و خشن است و شاید طمغاچیان به صفت تقلب و اختلاس و مانند آن موصوف بوده اند چنانکه گمرکچیان، و شایدتأیید میکند این حدس را بیتی که در آنندراج برای تمغاچی شاهد آمده است :<br />ز تمغاچی پسر داغ غلامی برجبین دارم <br />تلف شد نقد جان و حاصل و باقی همین دارم .<br /> <font color=\"Red\">سیفی .</font><br />رجوع به تمغا و تمغاچی شود.<br /></font></div>'),
(177750, 'طمغاجی', '<span class=\"hlight\">طمغاجی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (حاجب ) ممدوح عثمان مختاری . رجوع به توضیح مربوط به طمغاجی شود.<br /></font></div>'),
(177751, 'طمغان خان', '<span class=\"hlight\">طمغان خان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام پادشاه سمرقند.<br /></font></div>'),
(177752, 'طمغاچ', '<span class=\"hlight\">طمغاچ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام ولایتی از ترکستان . (برهان ) (آنندراج ) (غیاث ) <span class=\"hlight\">:</span> <br />چگل را زلف برطمغاچ بندم <br />طراز شوشتر بر چاچ بندم .<br /> <font color=\"Red\">نظامی .</font><br />این کلمه ظاهراً همان طمغاج است یا طفقاج . بدین دو کلمه رجوع شود.<br /></font></div>'),
(177753, 'طمل', '<span class=\"hlight\">طمل .</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (ع مص ) آفرینش . (منتهی الارب ). خلق عالم و آفریدگان . <BR><font color=\"Blue\">◄</font> سخت راندن ستور. (منتخب اللغات ). سخت راندن شتر. (منتهی الارب ). نیک راندن شتر. (تاج المصادر). <BR><font color=\"Blue\">◄</font> باریک بافتن بوریا و رشته ها در آن داخل کردن . (منتهی الارب ). بافتن حصیر و رشته ها درآن کردن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> سبزرنگ کردن جامه . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> باز و پهن کردن نان به مطمله . (منتهی الارب ) (منتخب اللغات ). گرده ٔ بزرگ وابردن . (تاج المصادر). <BR><font color=\"Blue\">◄</font> پهن و برابر کردن چیزی . <BR><font color=\"Blue\">◄</font> آلودن خون تیر را. (منتهی الارب ). آلوده شدن تیر بخون . آلوده شدن هر چیز بروغن یا بقیر. (منتخب اللغات ). آلوده شدن هر چیز بروغن و خون و قیر و نظائر آن . <BR><font color=\"Blue\">◄</font> در کار بد افتادن و آلوده شدن بدان . (منتهی الارب ).<br /></font></div>'),
(177754, 'طمل', '<span class=\"hlight\">طمل .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص، اِ) مرد پلیدزبان شوخ چشم بیباک . ج، طمول . (منتهی الارب ). مرد بدکار که از بد کردن باک ندارد. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آب تیره . <BR><font color=\"Blue\">◄</font> جامه ٔ سبزرنگ . <BR><font color=\"Blue\">◄</font> گلیم سیاه . <BR><font color=\"Blue\">◄</font> سیاه هرچه باشد. (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> ناکس . فرومایه . (منتهی الارب ). لئیم . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> گول . (منتهی الارب ). نادان . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> دزد. (منتهی الارب ). دزد بدکار. (منتخب اللغات ). بترین دزدان . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> نافرمان . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> جامه ٔ کهنه . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> گرگ تیره رنگ خفی الشخص . (منتهی الارب ). گرگ تیره رنگ که رنگش بسیاهی مایل بود. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> گرگ سخت حیله . <BR><font color=\"Blue\">◄</font> درویش بدخوی و بحال زشت و تنگ زندگانی و چرکن . مرد برهنه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گردن بند. (منتهی الارب ) (منتخب اللغات ).<br /></font></div>'),
(177755, 'طملال', '<span class=\"hlight\">طملال .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b>(ع ص، اِ) درویش بدخوی زشت حال و تنگ زیست . درویش برهنه . <BR><font color=\"Blue\">◄</font> گرگ تیره رنگ نهان ذات . <BR><font color=\"Blue\">◄</font> (اِخ ) اسبی مر بنی حارث بن ثعلبه را. (منتهی الارب ).<br /></font></div>'),
(177756, 'طملان', '<span class=\"hlight\">طملان .</span> <font color=\"DarkGreen\"><b>[ طُ م َ ]</font></b> (اِ) دنبلان . خایه ٔ چارپایان . خصی المواشی . <BR><font color=\"Blue\">◄</font> کماة . بنات الرعد. دنبلان .<br /></font></div>'),
(177757, 'طملة', '<span class=\"hlight\">طملة.</span> <font color=\"DarkGreen\"><b>[ طُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> طَ م َ ل َ ]</font></b> (ع اِ) لای تک ِ حوض . گویند: صار الماء طملة. <BR><font color=\"Blue\">◄</font> آب تیره که در تک حوض مانده باشد. (منتهی الارب ). باقی آب که بماند در بن حوض . (مهذب الاسماء). ماء کدر. (فهرست مخزن الادویه ).<br /></font></div>'),
(177758, 'طملة', '<span class=\"hlight\">طملة.</span> <font color=\"DarkGreen\"><b>[ طِ ل َ]</font></b> (ع ص، اِ) زنان ناتوان و سست . (منتهی الارب ). زن ضعیف . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> لای . <BR><font color=\"Blue\">◄</font> کار زشت . (منتهی الارب ).<br /></font></div>'),
(177759, 'طملة', '<span class=\"hlight\">طملة.</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (ع اِ) کار زشت و ناملایم . گویند: وقع فلان فی طملة؛ ای امر قبیح . (منتهی الارب ).<br /></font></div>'),
(177760, 'طملس', '<span class=\"hlight\">طملس .</span> <font color=\"DarkGreen\"><b>[ طَم َل ْ ل َ ]</font></b> (ع اِ) رَغیف ٌ طَمَلَّس ٌ؛ گرده ٔ خشک . گرده ٔ سبک تنک . (منتهی الارب ). نان خشک . (مهذب الاسماء).<br /></font></div>'),
(177761, 'طملسة', '<span class=\"hlight\">طملسة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ س َ ]</font></b> (ع مص ) رنج دیدن در سعی . <BR><font color=\"Blue\">◄</font> نرمی کردن . <BR><font color=\"Blue\">◄</font> پنهان شدن در چیزی . <BR><font color=\"Blue\">◄</font> کینه داشتن . (منتهی الارب ).<br /></font></div>'),
(177762, 'طملول', '<span class=\"hlight\">طملول .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص ) برهنه . <BR><font color=\"Blue\">◄</font> درویش سخت عیش . طملیل . (منتهی الارب ).<br /></font></div>'),
(177763, 'طملیل', '<span class=\"hlight\">طملیل .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) فاسق . <BR><font color=\"Blue\">◄</font> درویش سخت عیش . طملول . (منتهی الارب ).<br /></font></div>'),
(177764, 'طمن', '<span class=\"hlight\">طمن .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) آرامیده . ج، طمون . (منتهی الارب ). ساکن و آرمیده . (منتخب اللغات ).<br /></font></div>'),
(177765, 'طمو', '<span class=\"hlight\">طمو.</span> <font color=\"DarkGreen\"><b>[ طُ م ُوو ]</font></b> (ع مص ) پر شدن آب دریا. (منتهی الارب ) (منتخب اللغات ). برتر آمدن آب دریا و چاه و جوی . (زوزنی ). برتر آمدن آب دریا و رود. (تاج المصادر). برآمدن رود. (منتخب اللغات ). برآمدن و بلند گردیدن آب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بالیدن گیاه . <BR><font color=\"Blue\">◄</font> بلند گردیدن همت . (منتهی الارب ).<br /></font></div>'),
(177766, 'طموح', '<span class=\"hlight\">طموح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) اسپ لگدزن . (مهذب الاسماء). اسپ سرکش . (آنندراج ).<br /></font></div>'),
(177767, 'طمور', '<span class=\"hlight\">طمور.</span><font color=\"DarkGreen\"><b>[ طِم ْ م َ ]</font></b> (ع اِ) بیخ و بن . طمر. (منتهی الارب ).<br /></font></div>'),
(177768, 'طمور', '<span class=\"hlight\">طمور.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) بلند نگریستن . بلند نگریستن بچیزی .(زوزنی ). <BR><font color=\"Blue\">◄</font> بلند شدن . (منتخب اللغات ).<br /></font></div>'),
(177769, 'طمور', '<span class=\"hlight\">طمور.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) وثوب . طمر. (منتهی الارب ).برجستن . (تاج المصادر) (زوزنی ). جستن . (منتخب اللغات ). برجستن بسوی نشیب یا بسوی هوا. (منتهی الارب ). ازبالا بزیر جستن . (تاج المصادر). <BR><font color=\"Blue\">◄</font> رفتن . (منتهی الارب ) (منتخب اللغات ). سیر کردن در زمین . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> درگذشتن . (منتهی الارب ).<br /></font></div>'),
(177770, 'طموس', '<span class=\"hlight\">طموس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) ناپدید شدن راه و جز آن . (منتهی الارب ). ناپدید شدن . (تاج المصادر) (دهار) (زوزنی ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> محو و پاک گردیدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> محو کردن . امحاء. دروس . کهنه شدن . (منتخب اللغات ). کهنه شدن جامه . (زوزنی ). انمحاء. زوال اثر: طموس کواکب ؛ بشدن نور آنان .<br /></font></div>'),
(177771, 'طموش', '<span class=\"hlight\">طموش .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طمش . (منتهی الارب ).<br /></font></div>'),
(177772, 'طمول', '<span class=\"hlight\">طمول .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طمل . (منتهی الارب ).<br /></font></div>'),
(177773, 'طمول', '<span class=\"hlight\">طمول .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) مرد بدزبان بیباک . (منتهی الارب ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177774, 'طمولة', '<span class=\"hlight\">طمولة.</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (ع اِمص ) پلیدزبانی . <BR><font color=\"Blue\">◄</font> بیباکی . (منتهی الارب ). اسم است مصدر را.<br /></font></div>'),
(177775, 'طموم', '<span class=\"hlight\">طموم .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) بسیار گردیدن آب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> موی مرغول کردن . (تاج المصادر). تافتن موی . گره زدن موی . بریدن موی . (آنندراج ).<br /></font></div>'),
(177776, 'طموم', '<span class=\"hlight\">طموم .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) مصطفی . رجوع به مصطفی طموم شود. (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٢</span>).<br /></font></div>'),
(177777, 'طمون', '<span class=\"hlight\">طمون .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طمن . (منتهی الارب ).<br /></font></div>'),
(177778, 'طمویه', '<span class=\"hlight\">طمویه .</span> <font color=\"DarkGreen\"><b>[ طَ ی َ ]</font></b> (اِخ ) دوده ای است به مصر. (منتهی الارب ).<br /></font></div>'),
(177779, 'طمچی', '<span class=\"hlight\">طمچی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی است از دهستان درجزین بخش رزن شهرستان همدان . در <span class=\"hlight\" dir=\"rtl\">٥٧</span>هزارگزی جنوب خاوری قصبه ٔ رزن و <span class=\"hlight\" dir=\"rtl\">٩</span>هزارگزی جنوب رودخانه ٔ قره چای . کوهستانی، سردسیر، با <span class=\"hlight\" dir=\"rtl\">٢٠٦</span> تن سکنه . آب آن از قنات، محصولات آنجا غلات و حبوبات و لبنیات . شغل اهالی زراعت و گله داری و راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(177780, 'طمی', '<span class=\"hlight\">طمی .</span> <font color=\"DarkGreen\"><b>[ طَم ْی ْ ]</font></b> (ع مص ) طمو. بسیار شدن آب . فزودن آب . <BR><font color=\"Blue\">◄</font> گوالیدن و دراز گردیدن گیاه . <BR><font color=\"Blue\">◄</font> بلند گشتن قصد وهمت . <BR><font color=\"Blue\">◄</font> پر شدن دریا. برآمدن آب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شتافتن . (تاج المصادر بیهقی ).<br /></font></div>'),
(177781, 'طمیة', '<span class=\"hlight\">طمیة.</span> <font color=\"DarkGreen\"><b>[ طَ می ی َ ]</font></b> (اِخ ) در کتاب نصر آمده که طمیه پشته ای است . (معجم البلدان ).<br /></font></div>'),
(177782, 'طمیة', '<span class=\"hlight\">طمیة.</span> <font color=\"DarkGreen\"><b>[ طَ می ی َ ]</font></b> (اِخ ) اصمعی گوید از بلاد فزاره است . (معجم البلدان ).<br /></font></div>'),
(177783, 'طمیة', '<span class=\"hlight\">طمیة.</span> <font color=\"DarkGreen\"><b>[طَ می ی َ ]</font></b> (اِخ ) و نیز اصمعی آورده که طمیه کوهی است ببادیه در بلاد مرةبن عوف . شاعر گوید <span class=\"hlight\">:</span> <br />اتین علی طمیة و المطایا<br />اذا استحثثن اتعبن الجرورا.<br /><font color=\"Red\">(از معجم البلدان ).</font><br /></font></div>'),
(177784, 'طمیة', '<span class=\"hlight\">طمیة.</span> <font color=\"DarkGreen\"><b>[ طَ می ی َ ]</font></b> (اِخ ) کوهی است بنی فزاره را و آن از نواحی نجد است . (معجم البلدان ).<br /></font></div>'),
(177785, 'طمیة', '<span class=\"hlight\">طمیة.</span> <font color=\"DarkGreen\"><b>[ طَ می ی َ ]</font></b> (اِخ ) در کتاب اصمعی آمده که طمیه کوهی است سخت و بلند و بر آن جز از یک جا نتوان برشدن، و آن را چکاوی تیز و سیاه رنگ است عرقوة نام . (معجم البلدان ).<br /></font></div>'),
(177786, 'طمیة', '<span class=\"hlight\">طمیة.</span> <font color=\"DarkGreen\"><b>[ طَ می ی َ ]</font></b> (اِخ ) زمین غربی نیل برابر فسطاط. از متنزهات مردم مصر است در ایام نیل . (معجم البلدان ).<br /></font></div>'),
(177787, 'طمیة', '<span class=\"hlight\">طمیة.</span> <font color=\"DarkGreen\"><b>[ طَ می ی َ ]</font></b> (اِخ )کوهی است در راه مکه برابر فاید. (معجم البلدان ).<br /></font></div>'),
(177788, 'طمیة', '<span class=\"hlight\">طمیة.</span> <font color=\"DarkGreen\"><b>[ طَ می ی َ ]</font></b> (اِخ ) تپه ای است بین سمیراء و توز. (معجم البلدان ).<br /></font></div>'),
(177789, 'طمیدر', '<span class=\"hlight\">طمیدر.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام کوهی حصین . ابن البلخی درفارسنامه گوید: چون این خبر (خبر فرتوت گشتن لهراسب ) به ارجاسف رسید شاد شد و فرصت نگاه داشت و قصد بلخ کرد و جوهرمز را بمقدمه فرستاد و بلخ بگرفت و لهراسب را بکشت و آتشکده ها را خراب کرد و آتش پرستان را بکشت و دو دختر ازآن ِ وشتاسف ببرد وشتاسف را طلب کرد او در کوه طمیدر پنهان شد و کوهی حصین است و کس نتوانست او را به دست آوردن .<br /></font></div>'),
(177790, 'طمیدیوس', '<span class=\"hlight\">طمیدیوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) طیطوس طمیدیوس . نام یکی از سلاطین روم است و بلیناس حکیم صاحب طلسمات بزمان وی بوده است . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>).<br /></font></div>'),
(177791, 'طمیرخان', '<span class=\"hlight\">طمیرخان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام دهی بزرگ بحوالی مرغزار آورد معروف به کوشک زرد از مرغزارهای فارس . (نزهة القلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(177792, 'طمیس', '<span class=\"hlight\">طمیس .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طَم ْ می ]</font></b> (اِخ ) تمیسه . شهری است بطبرستان، یا آن طُمیسه است و یا طَمیسه . (منتهی الارب ). شهری است از نقاط جلگه ٔ طبرستان به شانزده فرسنگی ساری در آخر حدود طبرستان از جانب خراسان و جرجان و بر آن دروازه ای عظیم است و کسی نتواند از طمیس بجرجان بیرون شود مگر آنکه از این دروازه بگذرد چه از کوهسار بدریا کشیده و بگچ و آجر برآورده اند، و کسری انوشروان بساخته تا طبرستان از آسیب و غارت ترکان مصون ماند. سعیدبن العاص بسال سی هجری بروزگار عثمان بن عفان آن را بگشود. طمیس را مردم بسیار و مسجد جامع و سرداری است که دوهزار سپاهی بزیر فرمان اوست، و عجم تمیسه نامندش . و سمعانی آرد: طمیسة بضم ط و فتح میم قریه ای است بمازندران و من یک شب در آن بسر بردم . این کلمه باید معرب تمیسه باشد.<br /></font></div>'),
(177793, 'طمیس', '<span class=\"hlight\">طمیس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) کور و نابینا. (منتهی الارب ).<br /></font></div>'),
(177794, 'طمیسه', '<span class=\"hlight\">طمیسه .</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (اِخ ) تمیسه . رجوع به طمیس شود. تمیشه (؟).<br /></font></div>'),
(177795, 'طمیسی', '<span class=\"hlight\">طمیسی .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) ابواسحاق ابراهیم بن محمد طمیسی، منسوب به طمیس یا طمیسه . از ابوعبداﷲ محمدبن محمد سکسکی روایت کرده است و ابواسحاق ابراهیم بن محمد جنادی و دیگران از او روایت دارند. (از معجم البلدان ) (انساب سمعانی ).<br /></font></div>'),
(177796, 'طمیل', '<span class=\"hlight\">طمیل .</span> <font color=\"DarkGreen\"><b>[ طُ م َ ]</font></b> (ع ص ) برهنه از جامه ها. (منتخب اللغات ).<br /></font></div>'),
(177797, 'طمیل', '<span class=\"hlight\">طمیل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) پنهان حال . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) بزغاله ٔ نر و ماده . (منتهی الارب ) (منتخب اللغات ). جدی و عناق . (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> بوریا. (منتهی الارب ). حصیر. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آب و لای آمیخته . (منتهی الارب ). لای تک ِ حوض . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> خار خرمابن .(منتهی الارب ). <BR><font color=\"Blue\">◄</font> پیکان پهن . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> گردن بند بدان جهت که به بوی خوش بیالایند آنرا. <BR><font color=\"Blue\">◄</font> (ص ) نان فراخ و پهن . <BR><font color=\"Blue\">◄</font> تیر خون آلود. (منتهی الارب ).<br /></font></div>'),
(177798, 'طمیلة', '<span class=\"hlight\">طمیلة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) بزغاله . (منتهی الارب ).<br /></font></div>'),
(177799, 'طمیم', '<span class=\"hlight\">طمیم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) اسپ نیکورو سریع و شتاب . (منتهی الارب ). اسب نیک تیزرو. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> (اِ) نوعی جامه و پارچه ٔ فاخر <span class=\"hlight\">:</span> هزار قبای اطلس معدنی و ملکی و طمیم و نسیج و ممزج و مقراضی و اکسون . (چهارمقاله ٔ عروضی ص <span class=\"hlight\" dir=\"rtl\">٢٠</span>). اطلس و نسیج و اکسون انواع جامه های گرانبهااند و معانی آنها در کتب لغت مذکور است و ممزج بصیغه ٔ اسم مفعول بر وزن معظم گویا جامه ای بوده که از زر ممزوج یا چیز دیگر می بافته اند. ابن الاثیر در ذیل حوادث سنه ٔ <span class=\"hlight\" dir=\"rtl\">٥١٢</span> هَ . ق . گوید: «و فی هذه السنة اسقط المسترشد باﷲ من الاقطاع المختص به کل جور و امر ان لایؤخذ الا ماجرت به العادة القدیمة و اطلق ضمان غزل الذهب و کان صناع السقلاطون و الممزج و غیرهم ممن یعمل منه <font color=\"DarkGreen\"><b>[ ای من الذهب ]</font></b> یلقون شدة من العمال علیها و اذی عظیماً...». و مقراضی نیز چنانکه از سیاق عبارت آتیه استفاده میشود از جامه های گرانبهای فاخر بوده است ولی جنس آن معلوم نیست . در رساله ٔ محاسن اصفهان للمافروخی در عرض کلامی گوید: «فقال فی وصایاه لتتخذ اکفانی من ثوب مقراضی رومی و عمامة قصب مذهبة و ثوب دبیقی مصری فقیل له مه فانه لایصلح للاکفان غیر الثیاب البیض القطنیة فقال العیاذ باﷲ عاشرت خلقه ستین سنة و کنت احضرهم فی الدیباج و الحریر و القصب و انا الاَّن مواف خالقی و رازقی اادثر فی اکفان من هذا الضرب الردی ». اما معدنی و ملکی اگرچه جائی یافت نشد ولی در ضبط آنها اشکالی نیست، اشکالی که هست در کلمه ٔ طمیم است که نه ضبط آن معین است و نه معلوم است از چه لغتی است و هیاءة بکلمه ٔ عربی مینماید ولی در هیچیک از کتب لغت یافت نشد . (حواشی چهارمقاله ٔ عروضی چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١١٠</span>).<br /></font></div>'),
(177800, 'طمیم', '<span class=\"hlight\">طمیم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) سبک گردیدن . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> نرم نرم رفتن . (منتهی الارب ). نرم دویدن . (منتخب اللغات ) (تاج المصادر). نرم نرم دویدن . (منتهی الارب ).<br /></font></div>'),
(177801, 'طمین', '<span class=\"hlight\">طمین .</span> <font color=\"DarkGreen\"><b>[ طِم ْ می ]</font></b> (اِخ ) شهری است به روم . (منتهی الارب ) (منتخب اللغات ). جائیست ببلاد روم و آن بنام بانی آنجا طمین بن الروم بن الیفزبن بن سام بن نوح موسوم گشته است . ابوتمام ذکر آن در شعر خویش آرد در قصیدتی بمدح خالدبن یزیدبن مزید <span class=\"hlight\">:</span> <br />و لما رأی ̍ توفیل آیاتک التی <br />اذاما اتلأبّت لایقاومها الصلب <br />تولی و لم یأل الردی فی اتباعه <br />کأن الردی فی قصده هائم صب <br />کأن بلاد الروم عمت بصیحة<br />فضمت حشاها او رغا وسطها السقب <br />بصاغرة القصوی و طمین و اقتری <br />بلاد قرنطاؤوس وابلک السکب .<br /><font color=\"Red\">(از معجم البلدان ).</font><br /></font></div>'),
(177802, 'طن', '<span class=\"hlight\">طن .</span> <font color=\"DarkGreen\"><b>[ طِن ن ]</font></b> (ع اِ) خرمای تر سرخ نیک شیرین . (منتهی الارب ). رطب سرخ بسیار شیرین . (منتخب اللغات ) (فهرست مخزن الادویه ).<br /></font></div>'),
(177803, 'طن', '<span class=\"hlight\">طن .</span> <font color=\"DarkGreen\"><b>[ طُن ن ]</font></b> (ع اِ) اندام . ج، اطنان، طِنان . (منتهی الارب ). بدن انسان و غیر آن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> سربار که بالای دو عدل نهند. (منتهی الارب ). سربار میان دو لنگ بار. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> پشتواره ٔ نی و هیزم و مانند آن . (منتهی الارب ). دسته ٔ نی . (منتخب اللغات ).<br /></font></div>'),
(177804, 'طن', '<span class=\"hlight\">طن .</span> <font color=\"DarkGreen\"><b>[ طَن ن ]</font></b> (ع مص ) به بانگ آوردن تشت و جز آن . (منتهی الارب ). به بانگ آمدن تشت (لازم است و متعدی ). (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آواز کردن مگس و طشت و گوش و جز آن . (منتخب اللغات ). گوش بانگ کردن . (زوزنی ).<br /></font></div>'),
(177805, 'طن تارس', '<span class=\"hlight\">طن تارس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) از اعمال غرناطه به اسپانیا.<br /></font></div>'),
(177806, 'طناء', '<span class=\"hlight\">طناء.</span> <font color=\"DarkGreen\"><b>[ طَ ن َءْ ]</font></b> (ع مص ) چفسیدن سپرز بر پهلوی وی . (منتهی الارب ). واگرفتگی سپرز پهلو. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> آشکار نکردن جهت شرم آنچه در دل دارد. <BR><font color=\"Blue\">◄</font> شرم داشتن . (منتهی الارب ).<br /></font></div>'),
(177807, 'طناب', '<span class=\"hlight\">طناب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) رشته ٔ خیمه . (مهذب الاسماء). بند. حبل . رسن . رسن کلفت . رژه . رشته ٔ کلفت . ریسمان خیمه . (غیاث ). طنب . (منتهی الارب ) <span class=\"hlight\">:</span> <br />درختی که دارد سر اندر سحاب <br />ستاره رده برکشیده طناب .<br /> <font color=\"Red\">فرخی .</font><br />هر گه که او سست شد و بیفتاد نه خیمه ماندو نه طناب . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٨٦</span>). چون خیمه محکم بیک ستون است برداشته و طنابهای آن بازکشیده . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٨٦</span>). خیمه ملک است و ستون پادشاه و طناب و میخها رعیت است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٨٦</span>).<br />گر ندیدی طنابهاش ببین <br />جملگی خاک و باد و آتش و آب .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ببر طناب هوی پیش از آنکه ایامت <br />چهارمیخ کند زیر خیمه ٔ خضرا.<br /> <font color=\"Red\">خاقانی .</font><br />وی مشتری ردا نبد از سر که طیلسان <br />در گردن محمد یحیی طناب شد.<br /> <font color=\"Red\">خاقانی .</font><br />چون خیمه ٔ ابیات چهل پنج شد از نظم <br />بگسست طناب سخن از غایت اطناب .<br /> <font color=\"Red\">خاقانی .</font><br />وز طناب خیمه ها بر گرد لشکرگاه حاج <br />صد هزار اشکال اقلیدس ببرهان آمده .<br /> <font color=\"Red\">خاقانی .</font><br />گردن من بطنابست که چون گاوخراس <br />سوی روغنکده مهمان شدنم نگذارند.<br /> <font color=\"Red\">خاقانی .</font><br />گر نه بکار آمدی خیمه ٔ حاجی تو را<br />صبح نکردی عمود خور نتنیدی طناب .<br /> <font color=\"Red\">خاقانی .</font><br />سخن که خیمه زند در ضمیر خاقانی <br />طناب او همه حبل اللَّه آید از اطناب .<br /> <font color=\"Red\">خاقانی .</font><br />وَاندر گلوی دشمن دولت کند چو میخ <br />فراش او طناب در بارگاه را.<br /> <font color=\"Red\">سعدی .</font><br />قبه ای برساختستی از حباب <br />آخر آن خیمه ست بس واهی طناب .<br /> <font color=\"Red\">مولوی .</font><br />گدائیم ز تو یک دیدن و تو رخ ننمائی <br />بیا ز خیمه ببیرون ببر طناب گدائی .<br /> <font color=\"Red\">کاتبی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">با طناب پوسیده در چاه چهل ذرعی رفتن و بعشق عمر مار گرفتن </span> .<br /></font></div>'),
(177808, 'طناب باز', '<span class=\"hlight\">طناب باز.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (نف مرکب ) آنکه با طناب بازی کند.<br /></font></div>'),
(177809, 'طناب بازی', '<span class=\"hlight\">طناب بازی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (حامص مرکب ) عمل طناب باز.<br /></font></div>'),
(177810, 'طناب خور', '<span class=\"hlight\">طناب خور.</span> <font color=\"DarkGreen\"><b>[ طَ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (اِ مرکب ) گودی . عمق (در چاه ): طناب خور این چاه ده گز است .<br /></font></div>'),
(177811, 'طناب خوردن', '<span class=\"hlight\">طناب خوردن .</span> <font color=\"DarkGreen\"><b>[ طَ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (مص مرکب ) کنایه است از پیموده شدن . نورالدین ظهوری راست <span class=\"hlight\">:</span> <br />بمباحث چو تخم کارد دماغ ؟<br />سینه از آه غم طناب خورد.<br /><font color=\"Red\">(از آنندراج ).</font><br /></font></div>'),
(177812, 'طناب زدن', '<span class=\"hlight\">طناب زدن .</span> <font color=\"DarkGreen\"><b>[ طَ زَ دَ ]</font></b> (مص مرکب ) کنایه از پیمودن . (آنندراج ).<br /></font></div>'),
(177813, 'طناب شدن', '<span class=\"hlight\">طناب شدن .</span> <font color=\"DarkGreen\"><b>[ طَ ش ُ دَ ]</font></b> (مص مرکب ) طناب شدن دکان و مانند آن ؛ خط کشیده شدن، ظهوری در تعریف نورس گوید: در هر دکان راسته بازارش که به تار شعاعی طنابی شده کار هزار سود و سودا راست آمده . (آنندراج ).<br /></font></div>'),
(177814, 'طناب صبح', '<span class=\"hlight\">طناب صبح .</span> <font color=\"DarkGreen\"><b>[ طَ ب ِ ص ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از خطوط شعاعی . اوحدالدین انوری راست <span class=\"hlight\">:</span> <br />باش تا صبح دولتت پس از این <br />تیغ خورشید برکشد ز نیام <br />تا کنی از طناب صبح طناب <br />تا کنی از خیام چرخ خیام .<br /><font color=\"Red\">(از آنندراج ).</font><br /></font></div>'),
(177815, 'طناب قورق', '<span class=\"hlight\">طناب قورق .</span> <font color=\"DarkGreen\"><b>[ طَ ب ِ ق ُ رُ ]</font></b> (ترکیب اضافی، اِ مرکب ) طنابی که گرد خیمه ٔ سلاطین کشند ودر سواری سلاطین و حکام بندند از جهت امتناع آمدورفت مردم عوام از عالم باره که در هندوستان مرسوم است ودر آن زبان جالی گویند. شفیع اثر راست <span class=\"hlight\">:</span> <br />ز چین جبه فرومایگان دنیادار<br />کشیده اند طناب قورق برای فقیر.<br />و له <span class=\"hlight\">:</span> <br />بر سر راه او طناب قورق <br />بسته از چله ٔ کمان باشد.<br /><font color=\"Red\">(از آنندراج ).</font><br /></font></div>'),
(177816, 'طناب نهادن', '<span class=\"hlight\">طناب نهادن .</span> <font color=\"DarkGreen\"><b>[ طَ ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) کنایه از پیمودن . میرمعزی راست <span class=\"hlight\">:</span> <br />برین حدیث شها شهر تو دلیل بس است <br />که از عمارت او ملک یافت رونق و آب <br />بدولت تو منجم بر او کشیده رقم <br />بهمت تو مهندس بر او نهاده طناب .<br /><font color=\"Red\">(از آنندراج ).</font><br /></font></div>'),
(177817, 'طناب پیچ', '<span class=\"hlight\">طناب پیچ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ن مف مرکب ) پیچیده با طناب . کالا و متاعی که با طناب پیچیده شده باشد.<br /></font></div>'),
(177818, 'طنابرس', '<span class=\"hlight\">طنابرس .</span> <font color=\"DarkGreen\"><b>[ طَ ب ِ ]</font></b> (اِخ ) (رود...) (ابوالفدا). دنیپر. رودی در روسیه . رجوع به دنیپر شود.<br /></font></div>'),
(177819, 'طنابی', '<span class=\"hlight\">طنابی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) طنَبی . ایوان که توی ایوان کلان باشد. ملاطغرا راست <span class=\"hlight\">:</span> <br />از موج رطوبت گل نوخیز چمن را<br />گر خانه بود تنگ شود قصر طنابی .<br /> <font color=\"Red\">(از آنندراج ).</font><br />و رجوع به طنبی شود.<br /></font></div>'),
(177820, 'طنابیب', '<span class=\"hlight\">طنابیب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طنبوب . (دهار).<br /></font></div>'),
(177821, 'طنابیر', '<span class=\"hlight\">طنابیر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طنبور. (مهذب الاسماء) (اقرب الموارد).<br /></font></div>'),
(177822, 'طناجیر', '<span class=\"hlight\">طناجیر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طِنجیر. (دهار).<br /></font></div>'),
(177823, 'طناجیری', '<span class=\"hlight\">طناجیری .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص نسبی ) نسبت به طناجیر ج ِ طنجیراست . (انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٢٧١</span>). رجوع به طنجیر شود.<br /></font></div>'),
(177824, 'طناجیری', '<span class=\"hlight\">طناجیری .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابوالفتح حسن بن علی بن عبداﷲبن محمدبن ثابت بن جعفربن عبدالکریم طناجیری بغدادی . شاید یکی از اجداد وی بکار ساختن طنجیر (پاتیل ) مشغول بوده است . وی از مردم نیکوکار و دیندار بشمار میرفته است و از ابوالحسن علی بن عبدالرحمن بکای کوفی و محمدبن زیدبن مروان کوفی و محمدبن مظفر حافظ و ابوحفص بن شاهین و محمدبن نصر نجاس و ابوبکربن شاذان و جمعی ازین طبقه سماع کرده است . ابوبکر خطیب در تاریخ خودنام وی را آورده و گفته است : وی مردی متدین و پارساو ثقه و راستگو بوده و شنیدم میگفت من امالی ابن مالک قطیعی را نوشته ام ولی گم شده است و اکنون از وی چیزی در دست ندارم . ولادت وی در ذیحجه ٔ سال <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> هَ . ق . بوده و در سلخ ذیقعده ٔ سال <span class=\"hlight\" dir=\"rtl\">٤٣٩</span> درگذشته و در مقبره ٔ باب مدفون شده است . (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧١</span> ب ).<br /></font></div>'),
(177825, 'طناح', '<span class=\"hlight\">طناح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی به مصر. (منتهی الارب ).<br /></font></div>'),
(177826, 'طناز', '<span class=\"hlight\">طناز.</span> <font color=\"DarkGreen\"><b>[ طَن ْ نا ]</font></b> (ع ص ) بسیار فسوس کننده . (منتهی الارب ). فسوس دارنده . (دهار). افسونگر. (مهذب الاسماء). که سخریه کند. که دست اندازد. (صحاح الفرس ). بسیارسخن به رموز گوینده . (غیاث ) (آنندراج ) <span class=\"hlight\">:</span> <br />به چنگ باز گیتی در، چو بازت گشت سرپیسه <br />کنونت باز باید گشت ازین بازی و طنازی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />شده از من موافقان رنجور<br />شده بر من مخالفان طناز.<br /> <font color=\"Red\">مسعودسعد.</font><br />سر متاب از طریق تا نشوی <br />هدف تیر طعنه ٔ طناز.<br /> <font color=\"Red\">سنائی .</font><br />از جوانمردی بر جود و سخای تو کند<br />دو کف راد تو بر حاتم طی طنازی .<br /> <font color=\"Red\">سوزنی .</font><br />سپر نیفکنم از خصم طاعن طناز<br />که خصم نبود بی طاعنی و طنازی .<br /> <font color=\"Red\">سوزنی .</font><br /><BR><font color=\"Blue\">◄</font> نازکننده و رفتار به ناز کننده و شوخ . (غیاث ) (آنندراج ). به ناز خرامنده . کش خرام .<br /></font></div>'),
(177827, 'طناف', '<span class=\"hlight\">طناف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) طناب، در تداول عامیانه .<br /></font></div>'),
(177828, 'طنافة', '<span class=\"hlight\">طنافة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b>(ع مص ) طنوفة. طنف . بدباطن گردیدن . (منتهی الارب ).<br /></font></div>'),
(177829, 'طنافس', '<span class=\"hlight\">طنافس .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ ]</font></b> (ع اِ) ج ِ طنفسة. (منتهی الارب ) (دهار). رجوع به طنفسه شود.<br /></font></div>'),
(177830, 'طنافسی', '<span class=\"hlight\">طنافسی .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ ]</font></b> (اِخ ) محدث است . ابوسهل ویزداذ از وی و وی از منکدربن محمد روایت کند.رجوع به عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣١</span> و <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> شود.<br /></font></div>'),
(177831, 'طنافسی', '<span class=\"hlight\">طنافسی .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ ]</font></b> (اِخ ) سمعانی آرد: این کلمه نسبت به طنفسه است و سه برادر بدان منسوبند:<br /><span class=\"hlight\" dir=\"rtl\">١</span> - ابوحفص عمربن عبیدبن ابی امیة طنافسی حنفی کوفی . وی از ابواسحاق سبعی و سماک بن حرب روایت دارد و اسحاق بن ابراهیم و اهل عراق از وی روایت کرده اند. عمر بسال <span class=\"hlight\" dir=\"rtl\">١٨٧</span> هَ . ق . درگذشته است .<br /><span class=\"hlight\" dir=\"rtl\">٢</span> - ابوعبداﷲ محمدبن ابی عبیدبن ابی امیه موسوم به عبدالرحمن ایادی طنافسی کوفی احدب مولی ابوحنیفه برادر عمرو یعلی . وی از هشام بن عروة و محمدبن اسحاق بن یسار و سلیمان اعمش و عبداﷲبن عمر و مسعربن کدام (کذا) و اسماعیل بن ابی خالد ودیگران سماع کرده است .<br /><span class=\"hlight\" dir=\"rtl\">٣</span> - ابویوسف یعلی بن عبیدبن ابی امیة طنافسی ایادی حنفی کوفی . از ثقات بوده است . وی از اعمش و اسماعیل بن ابی خالد و عبدالملک بن ابی سلیمان روایت کرده است و محمدبن عبداﷲبن نمیر و ابوبکر و عثمان بن ابی شیبه از او روایت دارند. رجوع به انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧١</span> ب و برگ <span class=\"hlight\" dir=\"rtl\">٣٧٢</span> الف شود.<br /></font></div>'),
(177832, 'طنان', '<span class=\"hlight\">طنان .</span> <font color=\"DarkGreen\"><b>[ طَن ْ نا ]</font></b> (ع ص ) بلندآوازه : لفلان ذِکرها طنان ؛ ای مشهور. (ذیل اقرب الموارد) <span class=\"hlight\">:</span> <br />بروزگار تو شادم اگرچه محرومم <br />از آن بزرگی طنان و طلعت وضاح .<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(177833, 'طنان', '<span class=\"hlight\">طنان .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) ج ِ طُن . (منتهی الارب ). رجوع به طن شود.<br /></font></div>'),
(177834, 'طنان', '<span class=\"hlight\">طنان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) از اعیان قراء مصر نزدیک فسطاط، دارای بستانهای بسیار. محصول آن ده هزار دینار است به هر سالی . (معجم البلدان ).<br /></font></div>'),
(177835, 'طنانة', '<span class=\"hlight\">طنانة.</span> <font color=\"DarkGreen\"><b>[ طَن ْ نا ن َ ]</font></b> (ع ص ) تأنیث طنان .<br /></font></div>'),
(177836, 'طناک بالا', '<span class=\"hlight\">طناک بالا.</span> <font color=\"DarkGreen\"><b>[ طَ ک ِ ]</font></b> (اِخ ) دهی از دهستان مؤمن آباد بخش درمیان شهرستان بیرجند در <span class=\"hlight\" dir=\"rtl\">٣٨</span> هزارگزی باختر درمیان و <span class=\"hlight\" dir=\"rtl\">١٧</span> هزارگزی جنوب باختری شوسه ٔ بیرجند به درح . جلگه وگرمسیر. <span class=\"hlight\" dir=\"rtl\">١٥</span> تن سکنه دارد. آب آن از قنات، محصول آنجا غلات و تریاک و شلغم . شغل اهالی زراعت و مالداری و راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(177837, 'طنب', '<span class=\"hlight\">طنب .</span> <font color=\"DarkGreen\"><b>[ طُ ن ُ ]</font></b> (ع اِ) طناب که سراپرده های خیمه بدان بسته شود.(منتهی الارب ). رسن خیمه . (دهار). رشته های خیمه . حبل طوال . (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> میخ . ج، اطناب، طنبة. <BR><font color=\"Blue\">◄</font> دوال که به زه کمان پیوندند سپس آن بر چوبک پیچند. دوال که بر قبضه ٔ کمان بندند. (منتهی الارب ). دوال که به چله ٔ کمان وصل کنند. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> پی اعلای سینه . <BR><font color=\"Blue\">◄</font> بیخ و عروق درخت . (منتهی الارب ). عِرق شجر. <BR><font color=\"Blue\">◄</font> عصب بدن . (فهرست مخزن الادویه ). پی اندام . <BR><font color=\"Blue\">◄</font> طرف و ناحیه، و منه الحدیث : ما بین طنبی المدینة احوج منی الیها؛ ای طرفیها. (منتهی الارب ).<br /></font></div>'),
(177838, 'طنب', '<span class=\"hlight\">طنب .</span> <font color=\"DarkGreen\"><b>[ طُ ن ُ ]</font></b> (اِخ ) منزلی است از منازل حاج بصرة بین ماویه و ذات العشر، و آن آبیست بنی العنبر را. (معجم البلدان ).<br /></font></div>'),
(177839, 'طنب', '<span class=\"hlight\">طنب .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (ع اِمص ) کجی نیزه . (منتهی الارب ) (مهذب الاسماء) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> درازی پا با سستی و نرمی . (منتهی الارب ). درازی هر دو پا با سستی و استرخاء. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> درازی پشت، و آن عیب است . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> (اِ) صفه ٔ مشبک . (غیاث ).<br /></font></div>'),
(177840, 'طنبار', '<span class=\"hlight\">طنبار.</span> <font color=\"DarkGreen\"><b>[ طِم ْ ]</font></b> (معرب، اِ) طنبور. (منتهی الارب ) (مهذب الاسماء) (المعرب ). سازی است معروف، معرب دنبره، یعنی دنب بره جهت شباهت آن به دم بره . (منتخب اللغات ). دریج . (السامی ).<br /></font></div>'),
(177841, 'طنباط', '<span class=\"hlight\">طنباط.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) بلغت سودان ترنجبین است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(177842, 'طنبذ', '<span class=\"hlight\">طنبذ.</span> <font color=\"DarkGreen\"><b>[ طُم ْ ب ُ ]</font></b> (اِخ ) دهی به مصر. یاقوت در مشترک آورده که طنبذة دو موضعند، یکی از آن شهری است در صعید و دیگری موضعی است در اقلیم محمدیه به تونس . (منتهی الارب ). رجوع به طنبذة شود.<br /></font></div>'),
(177843, 'طنبذی', '<span class=\"hlight\">طنبذی .</span> <font color=\"DarkGreen\"><b>[ طُم ْ ب ُ ]</font></b> (اِخ ) ابوعثمان مسلم بن یسار طنبذی، منسوب به طنبذ است که یکی از قرای مصر در بهسنه میباشد... وی از ابوهریره سماع کرده است . رجوع به انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧٢</span> الف شود.<br /></font></div>'),
(177844, 'طنبرانی', '<span class=\"hlight\">طنبرانی .</span> <font color=\"DarkGreen\"><b>[ طَم ْ ب ُ نی ی ]</font></b> (ع ص نسبی ) طنبورزن . (السامی ).<br /></font></div>'),
(177845, 'طنبریز', '<span class=\"hlight\">طنبریز.</span> <font color=\"DarkGreen\"><b>[ طَم ْ ب َ ]</font></b> (ع اِ) شرم زن . (از منتهی الارب ).<br /></font></div>'),
(177846, 'طنبسة', '<span class=\"hlight\">طنبسة.</span> <font color=\"DarkGreen\"><b>[ طَم ْ ب َ س َ ]</font></b> (ع اِ)گستردنی است و جامه و بوریا مانندی از شاخ خرما بر پهن یک گز، بعربی طنفسه خوانند. (آنندراج ). طنفسه .<br /></font></div>'),
(177847, 'طنبل', '<span class=\"hlight\">طنبل .</span> <font color=\"DarkGreen\"><b>[ طَم ْ ب َ ]</font></b> (اِخ ) دهی به مصر. (منتخب اللغات ).<br /></font></div>'),
(177848, 'طنبل', '<span class=\"hlight\">طنبل .</span> <font color=\"DarkGreen\"><b>[ طَم ْ ب َ ]</font></b> (ع ص ) کند. احمق . وخم . ثقیل . بلید. (تاج ). <BR><font color=\"Blue\">◄</font> (اِ) نام نوعی از ماهی است . (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> طبلک و دهل . (فرهنگ نفیسی ).<br /></font></div>'),
(177849, 'طنبلة', '<span class=\"hlight\">طنبلة.</span> <font color=\"DarkGreen\"><b>[ طَم ْ ب َ ل َ ]</font></b> (ع مص ) گولی نمودن بعدِ عاقلی . (منتهی الارب ).<br /></font></div>'),
(177850, 'طنبوب', '<span class=\"hlight\">طنبوب .</span><font color=\"DarkGreen\"><b>[ طُم ْ ]</font></b> (ع اِ) استخوان ساق . ج، طنابیب . (دهار).<br /></font></div>'),
(177851, 'طنبور', '<span class=\"hlight\">طنبور.</span> <font color=\"DarkGreen\"><b>[ طَم ْ <span class=\"hlight\" dir=\"rtl\">/</span> طُم ْ ]</font></b> (معرب، اِ) یکی از آلات مهتز است از ذوات الاوتار. و صاحب نفایس الفنون گوید: طنبور همان است که اکنون به کمانچه مشهور است . قسمی ماندولینا از ذوات الاوتار و آن در ایران و بلغارستان و میان عرب متداول است . از آلات موسیقی و از ذوات الاوتار است، قسمی از آن را شش تا گویند که شش تار دارد و قسمی دیگر را سه تا که سه تاردارد. در قدیم دو وتر بر آن بوده و امروز تا شش وترنیز بر آن کنند. نوعی از رودجامه ها. معربست، اصله دنبه ٔ بره شبه بالیة الحمل . (منتهی الارب ). سازی است معروف، معرب دنبره یعنی دنب بره جهت شباهت آن به دم بره . (منتخب اللغات ). الطنبور، الذی یلعب به، معرب و قد استعمل فی لفظ العربیة و روی ابوحاتم عن الاصمعی الطنبور دخیل ٌ و انما شبه بالیة الحمل و هی بالفارسیةدنب بره فقیل طنبور و الطنبار لغة فیه . (المعرب جوالیقی ). طنبار. (منتهی الارب ). دوتای . (زمخشری ). عرطبة. ابواللهو. کنارة. طبن . قنین . (منتهی الارب ). دریج . (منتهی الارب ) (السامی ). ج، طنابیر. (مهذب الاسماء). صاحب آنندراج گوید: ساز معروف و این معرب تونبره که لغت هندی است بمعنی کدوی تلخ و چون این ساز در اصل ازکدو ساخته اند بمجاز نام شهرت گرفته، از عالم تسمیة الشی ٔ باسم مادته . و رشیدی گوید: معرب دمبره زیرا که شبیه است به دم بره و الاول هو الحق بهر تقدیریننا. انگشت از تشبیهات اوست . کریتنس در کتاب ایران در زمان ساسانیان گوید: «... مسعودی نام آلات موسیقی ایرانیان را چنین آورده است : عود، نای، طنبور، مزمار، چنگ و گوید مردم خراسان بیشترآلتی را در موسیقی بکار میبردند که هفت تار داشت و آن را زنگ (زنج <span class=\"hlight\" dir=\"rtl\">zang</span>) میخواندند اما مردم ری و طبرستان و دیلم طنبور را دوست تر داشتند و این آلت نزد همه ٔ فرس مقدم بر سایر آلات بوده است . شکارگاه خسرو در طاق بستان ظاهراً حاکی از اینست که در آن عصر چنگ آلت درجه ٔ اول موسیقی ساسانی بوده است اما آلت دیگر که مطابق آثار آن عصر مسلماً در عهد پرویز وجود داشته عبارتند از شیپور و طنبور و نای ... نام عده ٔ کثیری از آلات موسیقی در رساله ٔ خسرو و غلامش مسطور است از جمله عود هندی موسوم به ون و عود متداول موسوم به دارو بربط و چنگ طنبور و سنطور موسوم به کنار و نای و قره نی موسوم به مار و طبل کوچکی موسوم به دمبلگ و آلتی بنام رنگ که دارای هفت تار بوده است » <span class=\"hlight\">:</span> <br />بوی برانگیخت گل چو عنبر اشهب <br />بانگ برانگیخت مرغ با ژخ طنبور.<br /> <font color=\"Red\">منجیک .</font><br />ابا می یکی نغز طنبور بود<br />بیابان چنان خانه ٔ سور بود.<br /> <font color=\"Red\">فردوسی .</font><br />یکی ساخته نغز طنبور ساخت <br />همی رزم را پیش خود سور ساخت .<br /> <font color=\"Red\">فردوسی .</font><br />همانگاه طنبور در بر گرفت <br />سرائیدن ازکام دل درگرفت .<br /> <font color=\"Red\">فردوسی .</font><br />خورد سیلی زند بسیار طنبور<br />دهد تیز او بتازی همچو تندور.<br /> <font color=\"Red\">طیّان .</font><br />گهی سماع زنی گاه بربط و گه چنگ <br />گهی چغانه و طنبور و شوشک و عنقا.<br /> <font color=\"Red\">زینتی یا فرخی .</font><br />دراج کشد شیشم و قالوس همی <br />بی پرده ٔ طنبور و بی رشته ٔ چنگ .<br /> <font color=\"Red\">منوچهری .</font><br />شاخ امرود گوئی و امرود<br />دسته و گردنای طنبور است .<br /> <font color=\"Red\">ابوالفرج رونی .</font><br />طنبوری هشت رود ساخته بودند همی زدند و سرود همی گفتند و نشاط همی کردند. (مجمل التواریخ و القصص ).<br />عدو چو تو نشود هیچوقت و خودنسزد<br />که با براق برابر شود خر طنبور.<br /> <font color=\"Red\">اخسیکتی .</font><br />بشد ز خاطرم اندیشه ٔ می و معشوق <br />برفت از سرم آواز بربط و طنبور.<br /> <font color=\"Red\">ظهیر.</font><br />بخنده گفت که سعدی سخن دراز مکن <br />میان تهی و فراوان سخن چوطنبوری .<br /> <font color=\"Red\">سعدی .</font><br />وگر فاسقی چنگ بردی بدوش <br />بمالیدی او را چو طنبور گوش .<br /> <font color=\"Red\">سعدی (بوستان چ یوسفی بیت <span class=\"hlight\" dir=\"rtl\">٢١٦٥</span>).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">در چهل سالگی طنبور می آموزد در گور استاد خواهد شد</span> .<br /></font></div>'),
(177852, 'طنبور السودانی', '<span class=\"hlight\">طنبور السودانی .</span> <font color=\"DarkGreen\"><b>[ طَم ْ <span class=\"hlight\" dir=\"rtl\">/</span> طُم ْ رُس ْ سو نی ی ]</font></b> (ع اِ مرکب ) ننغا. نانغا. <br /></font></div>'),
(177853, 'طنبور زدن', '<span class=\"hlight\">طنبور زدن .</span> <font color=\"DarkGreen\"><b>[ طَم ْ <span class=\"hlight\" dir=\"rtl\">/</span> طُم ْ زَ دَ ]</font></b> (مص مرکب ) زدن طنبور.نواختن طنبور <span class=\"hlight\">:</span> سخت خوش سخن مردی بود که امیر و همه ٔ اعیان لشکر وی را دوست داشتندی و طنبور زدی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٦٠</span>). عزف . (تاج المصادر بیهقی ).<br /></font></div>'),
(177854, 'طنبور میزانی', '<span class=\"hlight\">طنبور میزانی .</span> <font color=\"DarkGreen\"><b>[ طَم ْ <span class=\"hlight\" dir=\"rtl\">/</span> طُم ْ رِ ]</font></b> (ترکیب وصفی، اِ مرکب ) طنبور بغدادی درازگردن . (مفاتیح ).<br /></font></div>'),
(177855, 'طنبورانی', '<span class=\"hlight\">طنبورانی .</span> <font color=\"DarkGreen\"><b>[ طَم ْ <span class=\"hlight\" dir=\"rtl\">/</span> طُم ْ نی ی ]</font></b> (ع ص نسبی )کسی که طنبور نوازد. (آنندراج ). طنبورزن . (دهار).<br /></font></div>'),
(177856, 'طنبورزن', '<span class=\"hlight\">طنبورزن .</span> <font color=\"DarkGreen\"><b>[طَم ْ <span class=\"hlight\" dir=\"rtl\">/</span> طُم ْ زَ ]</font></b> (نف مرکب ) نوازنده ٔ طنبور. طنبوری . طنبرانی . (السامی ). طنبورانی . (دهار) <span class=\"hlight\">:</span> <br />کبک ناقوس زن و شارک سنتورزن است <br />فاخته نای زن و بط شده طنبورزنا.<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(177857, 'طنبورنواز', '<span class=\"hlight\">طنبورنواز.</span> <font color=\"DarkGreen\"><b>[ طَم ْ <span class=\"hlight\" dir=\"rtl\">/</span> طُم ْ ن َ ]</font></b> (نف مرکب ) نوازنده ٔ طنبور. طنبورزن <span class=\"hlight\">:</span> <br />می نیست چو در کاسه مرا رعشه بر اعضاست <br />دستم به نظر پنجه ٔ طنبورنواز است .<br /><font color=\"Red\">ملا طاهر غنی (آنندراج ).</font><br /></font></div>'),
(177858, 'طنبوره', '<span class=\"hlight\">طنبوره .</span> <font color=\"DarkGreen\"><b>[ طَم ْ <span class=\"hlight\" dir=\"rtl\">/</span> طُم ْ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (معرب، اِ) طنبور. رجوع به طنبور شود <span class=\"hlight\">:</span> <br />درّاج کشد شیشم وقالوس همی <br />بی پرده ٔ طنبوره و بی رشته ٔ چنگ .<br /> <font color=\"Red\">منوچهری .</font><br />خول طنبوره تو گوئی زند و لاسکوی <br />از درختی به درختی شود و گوید آه .<br /> <font color=\"Red\">منوچهری .</font><br />آن بلبل کاتوره برجسته ز مطموره <br />چون دسته ٔ طنبوره گیردشجر از چنگل .<br /> <font color=\"Red\">منوچهری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طنبوره (طنبور) از غلاف بیرون آوردن (بیرون کردن، از جوال بیرون کردن )</span> ؛ کنایه از فاش کردن راز است <span class=\"hlight\">:</span> <br />آمدم با سخن که نتوان کرد<br />از جوال شره برون طنبور.<br /> <font color=\"Red\">انوری .</font><br />و در بعضی نسخ است <span class=\"hlight\">:</span> <br />آمدم با سخن که طیره شوند<br />از غلاف اربرون کنم طنبور.<br /><font color=\"Red\">(از آنندراج ).</font><br /></font></div>'),
(177859, 'طنبوری', '<span class=\"hlight\">طنبوری .</span> <font color=\"DarkGreen\"><b>[ طَم ْ <span class=\"hlight\" dir=\"rtl\">/</span> طُم ْ ]</font></b> (ص نسبی ) طنبورزن . طنبورنواز.<br /></font></div>'),
(177860, 'طنبول', '<span class=\"hlight\">طنبول .</span> <font color=\"DarkGreen\"><b>[ طَم ْ ]</font></b> (اِخ ) دوده ای است به مصر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دهی است به مصر. (منتخب اللغات ).<br /></font></div>'),
(177861, 'طنبک', '<span class=\"hlight\">طنبک .</span> <font color=\"DarkGreen\"><b>[ طُم ْ ب َ ]</font></b> (معرب، اِ) دهلی باشد دم دراز که آن را از چوب و گاهی از سفال نیز سازند و بازیگران و سرآوازه خوانان در زیر بغل گرفته نوازند و خوانند. (برهان ). نوعی از دهل کوچک، معرب تنبک . (غیاث ) (آنندراج ). رجوع به تنبک شود.<br /></font></div>'),
(177862, 'طنبی', '<span class=\"hlight\">طنبی .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ن َ ]</font></b> (اِ) طنابی . ایوانی که توی ایوان کلان باشد. (آنندراج ). بادغر. (صحاح الفرس ). بادغرد. (صحاح الفرس ) <span class=\"hlight\">:</span> <br />به نیم جو نخرم طاق خانقاه و رباط<br />مرا که مصطبه ایوان و پای خم طنبیست .<br /> <font color=\"Red\">حافظ (دیوان چ قزوینی ص <span class=\"hlight\" dir=\"rtl\">٤٥</span>).</font><br />ز اطلس فلکم پرده ٔ در طنبیست <br />زبان خموش ولیکن دهان پر از عربیست . <br /> <font color=\"Red\">نظام قاری (دیوان البسه ).</font><br />به رختخانه ٔ قاری خرام و زینت بین <br />که متکای مهش گرد بالش طنبیست .<br /> <font color=\"Red\">نظام قاری (دیوان البسه ).</font><br />و گلشن سرای ترکان را دو طبقه کرد و طنبی عالی بر دست صفه ٔ بزرگ ساز داد. (تاریخ جدید یزد). و در باغچه طنبی و بادگیری بساخت و حوض وسیع راست کرد. (تاریخ جدید یزد). و چاه خانه و زیر زمین که آب در آن جاری است و طنبی عالی منقش و دور شاهنشین مقابل او کاشی تراشیده و جامه های الوان و بر کنار طنبی توحیدی عربی از گفته ٔ مولانا مشارالیه نوشته . (تاریخ جدید یزد). و هم متقارب این خانه، خانه ٔ دیگر ساخته و سرابستان و حیاضی و طنبی و آب نرسو باد در آن جاری است . (تاریخ جدید یزد).<br />سنجر کاشی راست <span class=\"hlight\">:</span> <br />فتاد برف بخاری سبک برافروزیم <br />که وقت صحبت شبها و گوشه ٔ طنبی است .<br /></font></div>'),
(177863, 'طنبی', '<span class=\"hlight\">طنبی .</span> <font color=\"DarkGreen\"><b>[ طُ ن ُ ]</font></b> (ص نسبی )منسوب به طنب که موضعی است در راه مکه . (سمعانی ).<br /></font></div>'),
(177864, 'طنبی', '<span class=\"hlight\">طنبی .</span> <font color=\"DarkGreen\"><b>[ طُ ن ُ ]</font></b> (اِخ ) زینب بن ثعلبة عنبری تمیمی طنبی . ابن ابوحاتم گوید: زینب بصری است ولی نزیل طنب در طریق مکه بود، وی از پیامبر (ص ) روایت کرده است و پسرانش ردحین بن زینب و عدوربن ردحین از وی روایت دارند. (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧٢</span> الف ).<br /></font></div>'),
(177865, 'طنت', '<span class=\"hlight\">طنت .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) از دیههای مصر. (معجم البلدان ).<br /></font></div>'),
(177866, 'طنتثنا', '<span class=\"hlight\">طنتثنا.</span> <font color=\"DarkGreen\"><b>[ طَ ت َ ]</font></b> (اِخ ) از دیههای مصر بکنار نیل . (معجم البلدان ).<br /></font></div>'),
(177867, 'طنج', '<span class=\"hlight\">طنج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) رستاقی است به خراسان نزدیک مروالروذ. (معجم البلدان ).<br /></font></div>'),
(177868, 'طنجران', '<span class=\"hlight\">طنجران .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی جزء دهستان رستاق بخش خمین شهرستان محلات در <span class=\"hlight\" dir=\"rtl\">٤٠٠٠</span>گزی خاور خمین . جلگه و معتدل با<span class=\"hlight\" dir=\"rtl\">٤٣٠</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و تریاک و چغندر و پنبه و انگور و بادام . شغل اهالی زراعت و قالیچه بافی است . راه فرعی به خمین دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(177869, 'طنجه', '<span class=\"hlight\">طنجه .</span> <font color=\"DarkGreen\"><b>[ طَ ج َ ]</font></b> (اِخ ) نام محلی خوش آب و هواست به رأس غین بکنار چشمه ای که الملک الاشرف بدانجا خانه و قصری عظیم ساخته است . (معجم البلدان ).<br /></font></div>'),
(177870, 'طنجور', '<span class=\"hlight\">طنجور.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) دهی از دهستان چالان چولان شهرستان بروجرد در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی جنوب باختری بروجرد و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی خاور شوسه ٔ بروجرد در جلگه، گرمسیر با <span class=\"hlight\" dir=\"rtl\">٣٥٤</span> تن سکنه . آب آن از رودخانه و قنوات . محصول آنجا غلات و تریاک . شغل اهالی زراعت . راه آن شوسه است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>)<br /></font></div>'),
(177871, 'طنجی', '<span class=\"hlight\">طنجی .</span> <font color=\"DarkGreen\"><b>[ طَ جی ی ]</font></b> (ص نسبی ) منسوب بشهر طنجه . (سمعانی ).<br /></font></div>'),
(177872, 'طنجیر', '<span class=\"hlight\">طنجیر.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (معرب، اِ) دیگ فراخ دهن حلواپزی (معربست )، بفارسی پاتیله . (منتهی الارب ). پاتله . (نصاب ). پاتیله . پاتیل . دیگ . (منتهی الارب ). پاتله که آوند معروفست . (آنندراج ) (غیاث ). هلکاره . (ملخص اللغات حسن خطیب ). هرکاره . (دهار). ج، طناجیر. (مهذب الاسماء). پاتیله، و این در اصل فارسی و معرب تنجیر است . (منتخب اللغات ).<br /></font></div>'),
(177873, 'طنجیره', '<span class=\"hlight\">طنجیره .</span> <font color=\"DarkGreen\"><b>[ طِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (معرب، اِ) پاتیله . (لغت فرس اسدی ص <span class=\"hlight\" dir=\"rtl\">٥٠٣</span>).<br /></font></div>'),
(177874, 'طنح', '<span class=\"hlight\">طنح .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (ع مص ) ناگوارد گردیدن شتران . <BR><font color=\"Blue\">◄</font> فربه شدن شتران . (منتهی الارب ).<br /></font></div>'),
(177875, 'طنخ', '<span class=\"hlight\">طنخ .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (ع مص ) ناگوارد گردیدن . (منتهی الارب ). ناگوار شدن . (منتخب اللغات ). ناگوارد گرفتن . (تاج المصادر). <BR><font color=\"Blue\">◄</font> دل گرفته شدن از چربش . (منتهی الارب ). دل گرفتن از چربی و خورش . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> فربه و پرگوشت شدن . (منتهی الارب ).<br /></font></div>'),
(177876, 'طنخ', '<span class=\"hlight\">طنخ .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع اِ) پاره ای از شب . گویند: مر طنخ من اللیل ؛ ای طائفة منها. (منتهی الارب ).<br /></font></div>'),
(177877, 'طنز', '<span class=\"hlight\">طنز.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) فسوس کردن .(منتهی الارب ) (منتخب اللغات ). فسوس داشتن . (دهار). افسوس داشتن . (زوزنی ). افسوس کردن . (تاج المصادر). <BR><font color=\"Blue\">◄</font> بر کسی خندیدن . <BR><font color=\"Blue\">◄</font> عیب کردن . (زوزنی ). <BR><font color=\"Blue\">◄</font> لقب کردن . (زوزنی ). <BR><font color=\"Blue\">◄</font> سخن به رموز گفتن . (غیاث ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِمص ) طعنه . (غیاث ) (آنندراج ). سخریه <span class=\"hlight\">:</span> آنچه دیده و شنیده از احوال نوخاستگان و حرکات ایشان و سخنان باطنز که میگفتند بازراند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٩٩</span>). بزرگان طنز فرانستانند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٩٢</span>).<br />زبون تر از مه سی روزه ام مهی سی روز<br />مرا بطنز چو خورشید خواند آن جوزا.<br /> <font color=\"Red\">خاقانی .</font><br />سالها جستم ندیدم زو نشان <br />جز که طنز و تسخر این سرخوشان .<br /> <font color=\"Red\">مولوی .</font><br />قهقهه زد آن جهود سنگدل <br />ازسر افسوس و طنز و غش و غل .<br /> <font color=\"Red\">مولوی .</font><br />عقلم بطنز گفت که انظر الی الابل <br />کاندر ابل عجایب صنع خدا بسی است .<br /> <font color=\"Red\">سلمان ساوجی .</font><br /><BR><font color=\"Blue\">◄</font> ناز. (غیاث ) (آنندراج ).<br /></font></div>'),
(177878, 'طنز', '<span class=\"hlight\">طنز.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ )(شارع ...) ببغداد است بنهر طابق . (معجم البلدان ).<br /></font></div>'),
(177879, 'طنز کردن', '<span class=\"hlight\">طنز کردن .</span> <font color=\"DarkGreen\"><b>[ طَ ک َ دَ ]</font></b> (مص مرکب ) طعنه زدن . عیبجوئی . تمسخر کردن .<br /></font></div>'),
(177880, 'طنزکنان', '<span class=\"hlight\">طنزکنان .</span> <font color=\"DarkGreen\"><b>[ طَ ک ُ ]</font></b> (نف مرکب، ق مرکب ) نازکنان . در حال ناز و کرشمه <span class=\"hlight\">:</span> <br />گه گه آید برِ من طنزکنان آن رعنا<br />همچوخورشید که با سایه درآید بطرب .<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(177881, 'طنزی', '<span class=\"hlight\">طنزی .</span> <font color=\"DarkGreen\"><b>[ طَ زی ی ]</font></b> (ص نسبی ) منسوب به طنزة که قریه ای است بجزیره ای در نواحی میافارقین . (سمعانی ).<br /></font></div>'),
(177882, 'طنس', '<span class=\"hlight\">طنس .</span> <font color=\"DarkGreen\"><b>[طَ ن َ ]</font></b> (ع اِ) تاریکی ِ سخت تاریک . (منتهی الارب ).<br /></font></div>'),
(177883, 'طنطاری', '<span class=\"hlight\">طنطاری .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابوالنقیب . رجوع به معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٣</span> شود.<br /></font></div>'),
(177884, 'طنطان', '<span class=\"hlight\">طنطان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) رجل ذوطَنْطان ؛ مرد با فریاد و فغان . (منتهی الارب ).<br /></font></div>'),
(177885, 'طنطاوی', '<span class=\"hlight\">طنطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b>(اِخ ) مرسی شاکر. (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٥</span>).<br /></font></div>'),
(177886, 'طنطاوی', '<span class=\"hlight\">طنطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (اِخ ) (الشیخ ...) جوهری . از نویسندگان و شعرای نیکوسخن این عصر و از استادان مدرسه ٔ دارالعلم قاهره و متولد بسال <span class=\"hlight\" dir=\"rtl\">١٢٨٧</span> هَ . ق . و صاحب تصانیف بسیار است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٣</span>).<br /></font></div>'),
(177887, 'طنطرانی', '<span class=\"hlight\">طنطرانی .</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (اِخ )معین الدین ابوالنصر احمدبن عبدالرزاق الطنطرانی . استاد مدرسه ٔ نظامیه ٔ بغداد. او را قصیدتی است در مدح نظام الملک وزیر معروف بقصیده ٔ طنطرانیة بدین مطلع:<br />یا خلی ّ البال قد بلبلت بالبلبال بال <br />بالندی زلزلتنی و العقل فی الزلزال زال .<br />رجوع به احمدبن عبدالرزاق شود. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>) (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٥</span>).<br /></font></div>'),
(177888, 'طنطنانی', '<span class=\"hlight\">طنطنانی .</span> <font color=\"DarkGreen\"><b>[ طَ طَ ]</font></b> (اِ) نوعی حلوا. یا تعبیری از چیزی شیرین و مطبوع .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">حلوای طنطنانی تا نخوری ندانی </span> .<br /></font></div>'),
(177889, 'طنطنة', '<span class=\"hlight\">طنطنة.</span> <font color=\"DarkGreen\"><b>[ طَ طَ ن َ ]</font></b> (ع مص ) به آواز آوردن تشت و جز آن .(منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) بانگ رود و بربط. (مهذب الاسماء). بانگ رود. (دهار). حکایت آواز طنبور و مانند آن . (منتخب اللغات ) (منتهی الارب ). آواز رباب و بربط و رود و امثال آنها را گویند. (برهان ). آوازطنبوره و رود و بربط... و بمعنی آواز نقاره و کوس نیز مستعمل شده زیرا که از هر دو نقاره یکی زیر باشد و دیگر بم، پس آواز زیر را طنطنه نامند و آواز بم رادمدمه . (غیاث ) (آنندراج ). <BR><font color=\"Blue\">◄</font> آوازه . (منتهی الارب ). کرّ و فرّ. (غیاث ) (آنندراج ) <span class=\"hlight\">:</span> <br />گرگ بیچاره اگرچه گرسنه ست <br />متهم باشد که او در طنطنه ست .<br /> <font color=\"Red\">مولوی .</font><br />طنطنه ٔ ادراک و بینائی نداشت <br />دمدمه ٔ روبه بر او سکته گماشت .<br /> <font color=\"Red\">مولوی .</font><br />آنجا که عشق طنطنه ٔ الرحیل زد<br />خود را سیاه مست بدریای نیل زد.<br /><font color=\"Red\">ملا قاسم مشهدی .</font><br /></font></div>'),
(177890, 'طنف', '<span class=\"hlight\">طنف .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (ع اِ) دوال . (منتهی الارب ). دوالها. پوستها. پوست پاره ٔ سرخ که بر جامه دانها باشد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> تهمت . (منتهی الارب ) (منتخب اللغات ) (مهذب الاسماء). بهتان . (منتخب اللغات ).<br /></font></div>'),
(177891, 'طنف', '<span class=\"hlight\">طنف .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> طُ ن ُ ]</font></b> (ع اِ) تندی از کوه بیرون برآمده . <BR><font color=\"Blue\">◄</font> آنچه بر آید از کوه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گردن . (منتخب اللغات ). آنچه از گردن بلندی و برآمدگی داشته باشد. (منتخب اللغات ). سر کوه .ج، اطناف، طنوف . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> هرچه بلند و بیرون آمده باشد از بنا. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کرانه های دیوار به خشت فروگرفته . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> پوشش در سرا. (منتهی الارب ). پوشش در سرای که از بنا پیش آمده باشد و از بالا درگذشته باشد. (منتخب اللغات ).<br /></font></div>'),
(177892, 'طنف', '<span class=\"hlight\">طنف .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) رجوع به طَنْف شود.<br /></font></div>'),
(177893, 'طنف', '<span class=\"hlight\">طنف .</span> <font color=\"DarkGreen\"><b>[ طُ ن ُ ]</font></b> (ع اِ) رجوع به طَنْف شود.<br /></font></div>'),
(177894, 'طنف', '<span class=\"hlight\">طنف .</span> <font color=\"DarkGreen\"><b>[ طَ ن ِ ]</font></b> (ع ص ) کم خوار. <BR><font color=\"Blue\">◄</font> متهم . <BR><font color=\"Blue\">◄</font> بدنیت . (منتهی الارب ).<br /></font></div>'),
(177895, 'طنفة', '<span class=\"hlight\">طنفة.</span> <font color=\"DarkGreen\"><b>[ طَ ن ِ ف َ ]</font></b> (ع ص ) تأنیث طَنِف . (منتهی الارب ). رجوع به طنف شود. <BR><font color=\"Blue\">◄</font> بددل . <BR><font color=\"Blue\">◄</font> تباه رأی . (منتهی الارب ).<br /></font></div>'),
(177896, 'طنفس', '<span class=\"hlight\">طنفس .</span> <font color=\"DarkGreen\"><b>[ طِ ف ِ ]</font></b> (ع ص ) هیچکاره . (منتهی الارب ). زبون . <BR><font color=\"Blue\">◄</font> بد. (منتخب اللغات ). ناخوش منظر. زشت روی . (منتهی الارب ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177897, 'طنفسة', '<span class=\"hlight\">طنفسة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ف َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> طُ ف َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ف ِ س َ ]</font></b>(معرب، اِ) گستردنی . (منتهی الارب ): زیلو، فرش پیشگاه ؛ طنفسه ای بود که پیش خانه بازافکنند از فرش . (لغت نامه ٔ اسدی ). بوریامانندی از شاخ خرما بر پهن یک گز. ج، طنافس . (منتهی الارب ). از فارسی تبسه، حصیری از سعف که عرض آن ذراعی است . مصلای مانند حصیر که از برگ خرما بافند. (منتخب اللغات ). نهالی . (دهار). نهالی از ابریشم . (مهذب الاسماء). توشک . بساط. (تفلیسی ). <BR><font color=\"Blue\">◄</font> جامه . (منتهی الارب ) <span class=\"hlight\">:</span> و از وی <font color=\"DarkGreen\"><b>[ از ناحیت روم ]</font></b> جامه ٔ دیباو سندس و میسانی و طنفسه و جورب و شلواربندهای با قیمت بسیار خیزد. (حدود العالم ). طنفسه، روی جامه از ابریشم . (مهذب الاسماء).<br /></font></div>'),
(177898, 'طنفسة', '<span class=\"hlight\">طنفسة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ س َ ]</font></b> (ع مص ) زشت خوی گردیدن بعدِ نیکخوئی . <BR><font color=\"Blue\">◄</font> پوشیدن جامه های بسیار. (منتهی الارب ).<br /></font></div>'),
(177899, 'طنفش', '<span class=\"hlight\">طنفش .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ]</font></b> (ع ص ) مرد سست و ناتوان . طنفشی ّ. (منتهی الارب ).<br /></font></div>'),
(177900, 'طنفشی', '<span class=\"hlight\">طنفشی .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ شی ی ]</font></b> (ع ص ) طنفش . مرد سست و ناتوان . (منتهی الارب ).<br /></font></div>'),
(177901, 'طنو', '<span class=\"hlight\">طنو.</span> <font color=\"DarkGreen\"><b>[ طَن ْوْ ]</font></b> (ع اِ) گستردنی . (منتهی الارب ).<br /></font></div>'),
(177902, 'طنو', '<span class=\"hlight\">طنو.</span> <font color=\"DarkGreen\"><b>[ طُن ْوْ ]</font></b> (ع اِمص ) نافرمانی . (منتهی الارب ).<br /></font></div>'),
(177903, 'طنوج', '<span class=\"hlight\">طنوج .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) نوعهای کتاب . <BR><font color=\"Blue\">◄</font> اجزاء کتاب . (منتهی الارب ).<br /></font></div>'),
(177904, 'طنوس الشدیاق', '<span class=\"hlight\">طنوس الشدیاق .</span> <font color=\"DarkGreen\"><b>[ طَن ْ نو سُش ْ ش ِدْ ]</font></b> (اِخ ) ابن یوسف الشدیاق الحدثی المارونی مورخ (متوفی بسال <span class=\"hlight\" dir=\"rtl\">٢٧٦</span> هَ . ق .). در حدث لبنان بدنیا آمد و خدمت امرای شهابیین کرد و سپس قاضی نصارای لبنان شد. او راست «اخبار الاعیان فی جبل لبنان » و «مختصر تاریخ البطریرک اسطفان الدویهی الاهدنی ». (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٢</span>).<br /></font></div>'),
(177905, 'طنوف', '<span class=\"hlight\">طنوف .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طنف . (منتهی الارب ).<br /></font></div>'),
(177906, 'طنک', '<span class=\"hlight\">طنک .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) صدا و آواز. (غیاث ) (آنندراج ).<br /></font></div>'),
(177907, 'طنی', '<span class=\"hlight\">طنی .</span> <font color=\"DarkGreen\"><b>[ طِن ْی ْ ]</font></b> (ع اِمص ) نافرمانی . اسم است طنی را. <BR><font color=\"Blue\">◄</font> (اِخ ) نام آبی است . (منتهی الارب ).<br /></font></div>'),
(177908, 'طنی', '<span class=\"hlight\">طنی .</span> <font color=\"DarkGreen\"><b>[ طَن ْی ْ ]</font></b> (ع اِ) تهمت . <BR><font color=\"Blue\">◄</font> خاکستر سرد. <BR><font color=\"Blue\">◄</font> بیماری . <BR><font color=\"Blue\">◄</font> چغزلاوه . <BR><font color=\"Blue\">◄</font> (مص ) خریدن درخت خرما یا بار آن . <BR><font color=\"Blue\">◄</font> فروختن بار درخت خاصة. <BR><font color=\"Blue\">◄</font> زنا کردن . <BR><font color=\"Blue\">◄</font> درگذشتن در فجور و تمادی کردن در آن . <BR><font color=\"Blue\">◄</font> درچفسیدن سپرز در پهلوی چپ کسی از تشنگی . (منتهی الارب ). سپرز پهلو دوسیدن از تشنگی . (زوزنی ). <BR><font color=\"Blue\">◄</font> به شدن از گزیدگی کژدم . (منتهی الارب ).<br /></font></div>'),
(177909, 'طنی', '<span class=\"hlight\">طنی .</span> <font color=\"DarkGreen\"><b>[ طُ نی ی ]</font></b> (ع ص ) مرد تندار پرگوشت . (منتهی الارب ).<br /></font></div>'),
(177910, 'طنیاط', '<span class=\"hlight\">طنیاط.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) به لغت اهل سودان ترنجبین است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177911, 'طنین', '<span class=\"hlight\">طنین .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) آواز مگس . (منتهی الارب ). بانگ مگس . (منتخب اللغات ) (مهذب الاسماء). آواز کردن مگس . (تاج المصادر). وزوز. بانگ پشه . (مهذب الاسماء). بانگ گوش . (مهذب الاسماء) (دهار). آواز گوش . (منتخب اللغات ). بانگ تشت . (مهذب الاسماء) (منتهی الارب ). آواز طشت و طاس . (منتخب اللغات ). بانگ طنبور. (مهذب الاسماء). بانگ بط و جز آن .(منتهی الارب ). آواز کردن بط. (تاج المصادر). بانگ پنگان . (منتهی الارب ). بانگ کردن رویینه و مس . (زوزنی ). و صاحب کشاف اصطلاحات الفنون آرد، در لغت صدای مگس باشد. و در عرف پزشکی، آوازی است که بگوش آدمی رسد ولی نه از خارج . و فرق بین طنین و دوی آنست که آهنگ طنین تیزتر و لطیفتر و صدای دوی، نرمتر و ستبرتر است .کذا فی بحر الجواهر <span class=\"hlight\">:</span> و اندر دماغ آوازها افتد همچون آواز حرکت درختان یا آواز جلاجل یا آواز آسیا و مانند آن، و این آوازها را بتازی طنین و دوی گویند. (ذخیره ٔ خوارزمشاهی ). و علاج طنین و دوی و آوازهاء دروغین شنیدن . (ذخیره ٔ خوارزمشاهی ). بیخ حنظل رااندر روغن بجوشانند و بگوش اندر چکانند، آوازها که اندر گوش افتاده باشد برود، و آن آوازها را به تازی طنین گویند و دوی نیز گویند. (ذخیره ٔ خوارزمشاهی ).<br />زبان مرغان خواهی طنین چرخ شنو<br />در سلیمان جوئی به صدر خواجه شتاب .<br /> <font color=\"Red\">خاقانی .</font><br />مرا ز هاتف همت رسد بگوش خطاب <br />کزین رواق طنینی که میرود دریاب .<br /> <font color=\"Red\">خاقانی .</font><br />اشکمش گفتی جواب بی طنین <br />که اباد اﷲ کید الکافرین .<br /> <font color=\"Red\">مولوی .</font><br />کیمیاسازان گردون را ببین <br />بشنو از میناگران هر دم طنین .<br /> <font color=\"Red\">مولوی .</font><br />کی از طنین ذبابی پلنگ راست زیان <br />کی از حنین حبابی نهنگ راست خطر.<br /> <font color=\"Red\">قاآنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طنین الاذن </span> ؛ الریح فی الاذن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طنین ذوالاربع</span> ؛ در سامعه سه قسمت میشود، دو قسمت در نسبت <span class=\"hlight\" dir=\"rtl\">٨٩</span> که آنها را طنینی گویند و «ط» علامت آنست، و یک قسمت را که کوچکتر است درنسبت <span class=\"hlight\" dir=\"rtl\">٢٠٢١</span> بقیه نامند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طنین صوت </span> ؛ (اصطلاح فیزیک ) عبارتست از طرز ترکیب اصوات اصلیه با اصوات فرعیه .<br /></font></div>'),
(177912, 'طه', '<span class=\"hlight\">طه .</span> <font color=\"DarkGreen\"><b>[ طاها ]</font></b> (اِخ ) ابن مهنا الجبرینی الشافعی المحتد الحلبی المولد، العالم الفاضل المتقن العلامة المحقق واحدالدهر فی الفضائل . وی مفسرو محدث و بعلوم عقلی و نقلی محیط و مردی تیزخاطر و صاحب هوشی سرشار بود. در غور بمطالب بسی عمیق و مدقق بود با زهد و عفافی مفرط. در سال <span class=\"hlight\" dir=\"rtl\">١٠٨٤</span> هَ . ق . قدم بعرصه ٔ وجود نهاد و بالفطره در عالم آفرینش خواهان دانش به دنیا آمد. از دانشمندان عصر خویش به فراگرفتن علوم مشغول گردید و تا سن بلوغ دست از طلب علم بازنداشت و تا سال <span class=\"hlight\" dir=\"rtl\">١١٣١</span> سعی و کوشش او در تحصیل ادامه پیدا کرد و در آن سال مسافرتی بحجاز کرد. صحیح بخاری را نزد شارح آن المتقن الضابط ابومحمد عبداﷲبن سالم البصری استماع کرد و از وی اجازه ٔ روایت صحیح بخاری وسایر کتب به دست آورد. علوم عربیت را نزد شیخ عبد مصری فراگرفت . شیخ تاج الدین قلعی و شیخ عبدالقادر که هر دو مفتی مکه بوده اند از مشایخ صاحب ترجمه بشمار میروند، همچنین نزد شیخ یونس مصری و شیخ ابوالحسن السندی ثم المدنی نیز استفاده ها برد و سپس به وطن خویش بازگشت و اشتغل بالافادة و الحق الاحفاد بالاجداد وز آن پس بحجاز بازگشت بسال <span class=\"hlight\" dir=\"rtl\">١١٦١</span> و در مکه نزدیک به دو سال اقامت گزید و پس از آن به وطن خویش مراجعت کرد. بر صحیح بخاری تا باب مغازی تعلیقاتی نوشته و تراجم احوال کسانی را که در غزوه ٔ بدر با حضرت پیغمبر صلواة اﷲ علیه و آله همراه بوده کتابی فراهم آورده، و جز آنچه نام برده شد نیز تحریراتی دارد. خلقی بیشمار از دانش وی استفاده ها کردند. با دوستان خویش همواره مزاح و مداعبه داشت . و کان یعانی حرفة الالاجة ینسج و تباع . (ظ. منظور الیجه بافی است که میبافته و بفروش میرسانده، و بعد از این جمله هم جمله ٔ دیگری آورده که ترجمه اش این است : برای وی غیر ازین راه طریق دیگری جهت زندگانی نبود). وی شعر نیز میگفت و این قصیده در وصف شمائل حضرت ختمی مرتبت صلی اﷲ علیه و آله از اوست :<br />یا اهیل النقا لقدهمت وجدا<br />فی هواکم و قد جفا الجفن سهدا<br />ماتناسیت للربوع لسلع<br />سل من الرکب من تناسیت عهدا<br />کیف انسی و فیکم ُ من تسامی <br />فی سماء السماء فخراً و مجدا<br />خاتم الرسْل سید الکون طه <br />من غدا فی شمائل الحسن فردا<br />ذوجبین سما الهلال و وجه <br />اخجل البدر بالبها اذ تبدی ̍<br />فی اساریره سنا الشمس تجری <br />من سناه اهتدی الذی ضل رشدا<br />اهدب الجفن فوق خد اسیل <br />اکحل العین بالنفوس مفدی ̍<br />افرق السن ان تبسم تلقی <br />مثل حب الغمام والدر نضدا<br />ازهراللون انفه کان اقنی <br />بالقنا للعدی ابادو اردی ̍<br />شثن الکف للکرادیس ضخم <br />راحتاه جوداً من البحر اندی ̍<br />ربعة کان ان مشی یتکفاء<br />رجل الشعر لیس سبطاً و جعدا<br />کان فخماً مفخماً یتلألأ<br />خافض الطرف اکثر الخلق حمدا<br />بین کتفیه مثل بیض حمام <br />خاتم الانبیاء للخلق مبدا<br />و مغیث لمن اتی مستجیراً<br />من ذنوب فاضت علی البحر مدّا<br />و صریخ ٌ لمستریح خطوب <br />قد توالت علیه عکساً و طردا<br />ورؤف ٌ بنا و ایضاً رحیم ٌ<br />کم حبانی فضلاً و للخیر اسدی ̍<br />یا رسول الوری سمیک طه <br />قد سعی فی الهوی مکباً مجدّا<br />کلما کان یستعد لرشد<br />اخرته القیود عما استعدا<br />وَ هْوَ قد حل فی حماک و حاشا<br />ان ینال المنیخ ُ بالباب ردّا<br />و صلوة الاله فی کل آن <br />مَعْ سلام الی ضریحک یهدی ̍<br />و الی الاَّل و الصحاب جمیعاً<br />ما سنا کوکب بأفْق تبدی .<br />وفات ابن مهنا هنگام چاشتگاه روز پنجشنبه بیست وچهارم ربیعالاول بسال <span class=\"hlight\" dir=\"rtl\">١١٧٨</span> به وقوع پیوست . در اواخر ماه صفر مریض و بستری شد و قریب ده روز در منزل متوقف بود، و در ایام بیماری اختلالی در مشاعرش رخ داد. پسری و دختری از وی باقی ماند. در بیرون باب المقام بطرف مغرب اورا بخاک سپردند و مدفن او در شمالی ِ قبةالعوامید واقع شده است . از مرگ وی مردم همگی قرین غم و اندوه و مصیبت زده بودند. یکی از نویسندگان که ترجمه ٔ احوالی از وی نوشته، ضمناً گوید: بامداد روز وفات وی در حالی که جماعتی از خویشان و اقارب نزد وی نشسته و از آن جمله خواهرزادگان و گروهی از زنان صالحه ٔ سالخورده ٔخانواده ٔ وی نیز حاضر بودند، مرغی سبزرنگ از هوا فرودآمده دوری چند بر گرد وی بگشت و سپس بر روی سینه ٔ وی بنشست و بسوی آسمان برپرید. سید عبداﷲ یوسفی حلبی در ماده ٔ تاریخ وفات وی این ابیات را سروده است <span class=\"hlight\">:</span> <br />بُشری لطه حیث حا-<br />زَ فضائلاً عقلاً و نقلا<br />لقد ارتضاه و قد حبا-<br />ه ُ اﷲ مغفرةً و فضلا<br />لما غداالفردوس فی <br />دار البقاء له محلا<br />ارّخته بعلی الجنا-<br />ن ِ مُحدِث ُ الشهباء حلا.<br /> <font color=\"Red\">(سبک الدُرر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٩</span>).</font><br />وی راست شرحی بر ترجمه ٔ احوال اهل بدر (کسانی که درغزوه ٔ بدر در راه اسلام جهاد میکرده اند) که بسال <span class=\"hlight\" dir=\"rtl\">١١٦٤</span> هَ . ق . از تألیف آن فراغت یافت . متن این کتاب ازشیخ عبداللطیف البقاعی است و شرح مزبور بسال <span class=\"hlight\" dir=\"rtl\">١٢٩٤</span> هَ . ق . در بولاق بطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">١</span> ستون <span class=\"hlight\" dir=\"rtl\">٢٥٩</span>). و نیز رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٢</span> شود. محمد راغب طباخ، در تاریخ حلب بنقل از تاریخ ابن میرو، اشعار ذیل را به طه ابن مُهنا نسبت داده است :<br />قم الی روضة الحبیب و باکر<br />و اغتنم فرصة الزمان فبادر<br />ان ّ مرعی الشباب یعشو سریعاً<br />و ربیع السرور کالطیف زائر<br />و الثم الثغر و ارتشف ریق حب <br />ان ّ لثم الثغور یجلو الخواطر<br />فی زمان الربیع و النهر جار<br />فی حیاض الریاض و الزهر زاهر<br />باختلاف الالوان یزهو و یزکو<br />باصفرار منه تسر النواظر<br />و احمرارٌ کحمرة من عقیق <br />مَعْ بیاض کالدر للعقل باهر<br />و طیورٌ علی الغصون تغنی <br />کل الف منها لالف تناظر.<br />قال و هی قصیده طویلة.<br /><font color=\"Red\">(اعلام النبلا ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤</span>).</font><br /></font></div>'),
(177913, 'طه', '<span class=\"hlight\">طه .</span> <font color=\"DarkGreen\"><b>[طا ها ]</font></b> (اِخ ) (افندی ) انور. وی صرّاف محکمه ٔ ملّی اسکندریه بود. او راست مختصری لطیف و تألیفی عالی در قواعد چهار عمل اصلی علم حساب برای دبستانهای ملی، و بصورت پرسش و پاسخ است و بسال <span class=\"hlight\" dir=\"rtl\">١٣٠٧</span> هَ . ق . در مصر چاپ گردیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٣</span>).<br /></font></div>'),
(177914, 'طه', '<span class=\"hlight\">طه .</span> <font color=\"DarkGreen\"><b>[ طا ها ]</font></b> (اِخ ) الاسکندری . وی آموزگار علوم عربی در مدرسه ٔ خلیل آغا درقاهره ٔ مصر و از خدام مقام حضرت ابراهیم علیه السلام واقع در مصر بوده است . او راست المقاصد الوفیة فی قواعد علم العربیه، این کتاب بجمله ٔ: صرف اللهم (ظ: صرف ُ الهم ّ نحو حمداﷲ) من اعظم النعم آغاز شده و در مصر بطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٣</span>).<br /></font></div>'),
(177915, 'طه', '<span class=\"hlight\">طه .</span> <font color=\"DarkGreen\"><b>[ طاها ]</font></b> (اِخ ) ابن محمد الدمیاطی . وی در سابق مصحح چاپخانه ٔ بولاق بوده و بسال <span class=\"hlight\" dir=\"rtl\">١٣٢٥</span> هَ . ق . وفات یافته است . او راست کتابی بنام «کفایة المستکفی من الفن الصرفی » و این کتاب منظوم است و بسال <span class=\"hlight\" dir=\"rtl\">١٣١١</span> هَ . ق . در بولاق بطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٣</span>).<br /></font></div>'),
(177916, 'طه', '<span class=\"hlight\">طه .</span> <font color=\"DarkGreen\"><b>[ طا ها ]</font></b> (اِخ ) ابن محمد البیقونی . رجوع به «عمر» (الشیخ طه البیقونی ) در معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٣</span> شود.<br /></font></div>'),
(177917, 'طه', '<span class=\"hlight\">طه .</span> <font color=\"DarkGreen\"><b>[ طا ها ]</font></b> (اِخ ) ابن ابراهیم الاربلی . صاحب فوات الوفیات در ذیل نام وی به ایراد دو بیت ازاشعار او بسنده کرده و گوید «من شعره » <span class=\"hlight\">:</span> <br />دع النجوم لطرقی یعیش بها<br />و انهض بعزم صحیح ایها الملک <br />ان النبی و اصحاب النبی نهوا<br />عن النجوم و قدعاینت ما ملکوا.<br /><font color=\"Red\">(از فوات الوفیات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٥</span>).</font><br /></font></div>'),
(177918, 'طه', '<span class=\"hlight\">طه .</span> <font color=\"DarkGreen\"><b>[ طا ها ]</font></b> (اِخ ) نام سوره ٔ بیستم از قرآن کریم . شماره ٔ آیات آن یکصدوسی وپنج و نزول آن در مکه ٔ معظمه است و قبل از سوره ٔ انبیاء و پس از سوره ٔ مریم واقع است . و طه اسم فعل است، یعنی آرام کن . یا به معنی «یا رجل » است، به لغت حبشیه . (منتهی الارب ) (آنندراج ). و من قراء طه باشباع الفتحتین، فحرفان عنده من الهجاء. (منتهی الارب ). کوفیان طه را آیتی شمردند، و دیگران نشمردند. ابوعمرو بفتح طا و اماله ٔ «ها» خواند، و حمزه و کسائی و خلف و ابوبکر الاعشی و عبدالرحمن، به اماله ٔ هر دو طِه ِ خواندند. اهل شام و مدینه بین بین خواندند هر دو، و باقی قراء به تفخیم هر دو.و عیسی بن عمر در شاذ برعکس قرائت ابوعمرو خواند و حسن بصری در شاذ خواند طَه ْ، باسکان الهاء و گفت تفسیرش آن باشد که : ای مرد. مفسران در معنیش خلاف کرده اند، عبداﷲ عباس گفت قسم است بنامی از نامهای خدای تعالی که به او قسم کرد و مجاهد و حسن بصری و عطا و ضحاک گفتند: معنی این کلمه آن است که : یا رجل، ای مردا. عکرمه گفت هو بلسان الحبشه یا رجل . سعید جبیر گفت به نبطی هم این معنی دارد. سدی و ابامالک گفتند: یا فلان . کلبی گفت بلغت عک «یا رجل » باشد. قال <span class=\"hlight\">:</span> <br />ان السفاهة طه فی خلایقکم <br />لاقدس اﷲ ارواح الملاعین .<br />و قال آخر <span class=\"hlight\">:</span> <br />هتفت بطه فی القتال فلم یجب <br />فحقت لعمری ان یکون صوائلا.<br />مقاتل گفت معنی طه آن است که طاء الارض بقدمیک . وگفت سبب آن بود که رسول علیه السلام در نماز یک پای برگرفتی و بر یک پای بایستادی تا رنج بیش بودی و ثواب بیشتر، خدای تعالی این آیت فرستاد و گفت : هر دو پای بر زمین نه . محمدبن کعب القرظی گفت : خدای تعالی قسم کرد بطول و هدایتش و مقسم علیه که جواب قسم است، قوله :ماانزلنا علیک القرآن َ لتشقی . جعفربن محمد الصادق علیه السلام گفت : طه طهارت اهل بیت رسول است . آنگه این آیت برخواند: انما یرید اﷲ لیذهب عنکم الرجس اهل البیت و یطهرکم تطهیراً. (تفسیر ابوالفتوح رازی سوره ٔ <span class=\"hlight\" dir=\"rtl\">٣٣</span> (الاحزاب ) از آیه ٔ <span class=\"hlight\" dir=\"rtl\">٣٣</span>). هندوشاه نخجوانی در نعت خاتم الانبیاء صلواة اﷲ و سلامه علیه گفته <span class=\"hlight\">:</span> <br />پیشوای دو جهان قافله سالار وجود<br />کوست مقصود ز یاسین و مراد از طه .<br /> <font color=\"Red\">هندوشاه نخجوانی .</font><br /> <BR><font color=\"Blue\">◄</font> کنایه از آل رسول (ص ) است . آل طه . رجوع به آل طه شود. <BR><font color=\"Blue\">◄</font> پیغمبر اسلام (ص ) <span class=\"hlight\">:</span> <br />کید حسود بدنسب با چون تو شاه دین طلب <br />خاریست جفت بولهب در راه طه ریخته .<br /><font color=\"Red\">خاقانی (دیوان چ عبدالرسولی <span class=\"hlight\" dir=\"rtl\">٣٩٢</span>).</font><br /></font></div>'),
(177919, 'طه حسین', '<span class=\"hlight\">طه حسین .</span> <font color=\"DarkGreen\"><b>[ طا ها ح ُس َ ]</font></b> (اِخ ) (دکتر) در <span class=\"hlight\" dir=\"rtl\">١٤</span> نوامبر <span class=\"hlight\" dir=\"rtl\">١٨٨٩</span> م . در ماقاقا (مصر علیا) متولد شده است . در سن سه سالگی به بیماری تورّم چشم مبتلا گردیده و نابینا گشته است . تحصیلات ابتدائی او در مدرسه ٔ دهکده برای فراگرفتن قرآن آغاز گردید. در سال <span class=\"hlight\" dir=\"rtl\">١٩٠٢</span> پدرش او را بدانشگاه الازهر فرستاد. در آنجا به تحصیل زبان عربی و ادبیات و تمدن اسلامی و حکمت الهی پرداخت و در سال <span class=\"hlight\" dir=\"rtl\">١٩١٢</span> ناگزیر شد الازهر را بدون گرفتن هیچ گونه مدرک علمی ترک کند. استادان او چنین قضاوت کردند که اعطای دیپلم به کسی که طبعی چنان سرکش و خودرای دارد کار خطرناکی است . وی با روزنامه نگاری اولین فعالیت خود را آغاز کرد، سپس بدانشگاه مصر وارد گردید و پایان نامه ٔ مشهور و ممتاز خود رادرباره ٔ شاعر فیلسوف بنام «ذِکْری ̍ ابی العلاء» نوشت .در سال <span class=\"hlight\" dir=\"rtl\">١٩١٤</span> دانشگاه او را مأمور مطالعات علمی نمود و به فرانسه فرستاد. سالهای اول جنگ را ابتدا در شهر مونپولیه و بعد در پاریس گذرانید. در آنجا به تحصیل زبانهای لاتین و یونانی پرداخت و لیسانسیه در ادبیات شد و سپس به اخذ دیپلم در تحصیلات عالی نائل آمد و پایان نامه ٔ تحصیلی خود را که درباره ٔ اصول عقاید اجتماعی ابن خلدون بنام «فلسفه ٔ اجتماعی ابن خلدون » نوشته بود در سوربن گذرانید. در سال <span class=\"hlight\" dir=\"rtl\">١٩١٧</span> با دختر محصلی که با او در سوربن تحصیل میکرد ازدواج نمود و دارای یک پسر و یک دختر شد.<br />مشاغل : در سال <span class=\"hlight\" dir=\"rtl\">١٩١٩</span> طه حسین به مصر برگشت و به سمت استادی دانشکده ٔ ادبیات منصوب گردید و فعالیت های روزنامه نگاری خود را تعقیب کرد. در سال <span class=\"hlight\" dir=\"rtl\">١٩٣٢</span> بریاست دانشکده ٔ ادبیات (دانشگاه قاهره ) انتخاب شد ولی چون در اوامر دیکتاتوری ملک فؤاد اول مقاومت میکرد و با دستورهای او مخالفت میورزید از خدمت برکنار شد. در سال <span class=\"hlight\" dir=\"rtl\">١٩٣٦</span> به مقام سابق دوباره منصوب گشت . در سال <span class=\"hlight\" dir=\"rtl\">١٩٤٢</span> به مقام معاونت وزارت فرهنگ برگزیده شد و سپس ریاست دانشگاه اسکندریه به او محول گردید و آن راتأسیس کرد. در سال <span class=\"hlight\" dir=\"rtl\">١٩٥٠</span> وزیر فرهنگ شد و تعلیمات مجانی دوره ٔ مقدماتی و ابتدائی و متوسطه را برقرار کرد و سپس به تأسیس دانشگاه آسیوت (ناحیه ای در مصر علیا) پرداخت . علاوه بر این، تأسیس انستیتوی تحصیلات اسلامی در مادرید و ایجاد کرسی در شهر نیس و تأسیس مدرسه ٔ زبان های مختلف در قاهره از اموری است که در تحت توجهات او انجام گرفت .<br />در سال <span class=\"hlight\" dir=\"rtl\">١٩٥٥</span> به ریاست انجمن رجال ادب مصر انتخاب گردید و در سال <span class=\"hlight\" dir=\"rtl\">١٩٥٦</span> به عضویت شورای عالی ادب و هنرهای زیبای مصر منصوب شد. و به عضویت فرهنگستان مصر و فرهنگستان ادبی پاریس و فرهنگستان تاریخی مادرید پذیرفته شد. طه حسین عضو فرهنگستان های مایانس (آلمان ) و دمشق و طهران و بغداد و رم نیز بوده و به اخذ دیپلم دکترای افتخاری دانشگاه های مونپولیه، و لیون و آتن و رم و اکسفورد و مادرید نائل آمده است .<br />امتیازات و مدال ها و نشانها: دارنده ٔ مدالهای متعدد ازدولت مصر و لبنان و سوریه و عراق و فرانسه و اسپانیا و بلژیک و یونان است .<br />مسافرتها: بصورت رسمی و یا خصوصی به ممالک فرانسه، انگلستان، هلند، بلژیک، سویس، اتریش، ایتالیا، اسپانیا، یونان، لبنان، سوریه، فلسطین، عربستان مسافرت کرده است . در تمام کنگره های مستشرقین شرکت کرده و نماینده ٔ کشور مصر در کنفرانس های یونسکو بوده است .<br />آثارش : کتاب مشهورش که «روزها» نام دارد به بیشتر از دوازده زبان از جمله فرانسه، انگلیسی، آلمانی، ایتالیائی، اسپانیولی، روسی، فارسی و چینی و غیره ترجمه شده است . آثار متعددش متجاوز از چهل جلد میشود از جمله نوول های بسیار و مطالعات اجتماعی و ادبی مختلف را میتوان نام برد و انتقادهای تاریخی، و نیز او را ترجمه های متعدد است از جمله از یونانی قدیم (سوفکل ) و از زبان فرانسه ترجمه ٔ بعضی آثار راسین و آندره ژید که دوست عزیز او بود آثاری دارد. کتاب «آینده ٔ تعلیم و پرورش در مصر» او بزبان انگلیسی ترجمه شده و در امریکا انتشار یافته است .<br />نام طه حسین مکرر برای جایزه ٔ نوبل پیشنهادشده است . طه حسین هر هفته در الجمهوریه مهمترین روزنامه ٔ مصر مقالاتی مینگاشت و در دانشگاه تدریس می کرد.کتابی درباره ٔ دموکراسی تألیف کرده است . رجوع به معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٣</span> و ترجمه ٔ تاریخ ادبیات ایران تألیف برون ص <span class=\"hlight\" dir=\"rtl\">٥٢٣</span> شود.<br /></font></div>'),
(177920, 'طهاء', '<span class=\"hlight\">طهاء.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b>(ع ص، اِ) ابر برآمده . <BR><font color=\"Blue\">◄</font> ابر تنک برآمده . (منتهی الارب ) (آنندراج ). ابر بلند. (مهذب الاسماء).<br /></font></div>'),
(177921, 'طهات', '<span class=\"hlight\">طهات .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) ج ِ طاهی، بمعنی گوشت پز. بریان ساز. نان پز. پزنده ٔ هر نوع خوردنی . (آنندراج ).<br /></font></div>'),
(177922, 'طهارت', '<span class=\"hlight\">طهارت .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (از ع، مص ) پاک گردیدن . یقال : طهر طهراً و طهارة. (منتهی الارب ). پاک شدن . (آنندراج ) (دهار). پاکی . (آنندراج ) <span class=\"hlight\">:</span> <br />تقوای نفس ما بطواف ِ پیاله است <br />جائی که باده نیست طهارت نمی کنم .<br /> <font color=\"Red\">علیقلی بیک ترکمان (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> نمازی بودن . منقطع شدن حیض زن . یقال : طهرت المراءة. <BR><font color=\"Blue\">◄</font> غسل آوردن به انقطاع خون و جز آن . (منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span><br />برو نخست طهارت کن از جماع الاثم <br />که کس جنب نگذارند در جناب خدا.<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِمص ) وضو. (آنندراج ) (غیاث اللغات ). آبدست . رجوع به آبدست شود. استنجاء. (آنندراج ) (غیاث اللغات ) <span class=\"hlight\">:</span> چون وقت طهارت شد، موسی گفت یوشع را در بن این سنگ بنشین . (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span>). موسی را عادت بود که چون طهارت کردی از خلق دور شدی . (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span>). روزی تا بشب رفته بودم و شبانگه پای حصاری خفته که دزد بی توفیق ابریق رفیق برداشت که بطهارت میرود و بغارت میرفت . (گلستان سعدی ). <BR><font color=\"Blue\">◄</font> نظافت و پاکیزگی، و ضد آن دنس باشد در لغت، و شرعاً نظافت مخصوصی را گویند که انواع آن عبارتست از وضوء، غسل، تیمم، غسل بدن، و شست وشوی جامه و مانند آن، کما فی الدُرر. (کشاف اصطلاحات الفنون ). طهارت در لغت بمعنی پاکیزگی است و در شرع عبارتست از شست وشوی اعضای مخصوص بصفتی مخصوص . (تعریفات جرجانی ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>). استعمال چیزی که وسیله ٔ تطهیر است و تحقق این معنی در خارج متوقف بر نیت باشد. و اقسام طهارت عبارتست از: وضوء، غسل، تیمم که اولی و دومی را طهارت مائیه، و سومی را طهارت تُرابیه مینامند. رجوع به طهارت ترابیة و طهارت مائیة شود.<br />و صاحب نفایس الفنون آرد: بدان که طهارت بدن و جامه و جای نماز، از نجاست به آب واجب است، و نجاست دو قسم است : یکی عینی و دوم حکمی . و نجاست عینی بمذهب ابوحنیفه دو نوع است : یکی غلیظ همچو خمر و خون و ریم و بول و غایط و هرچیزی که گوشت او را نشاید خورد شرعاً، و از اینجا تا بمقدار ربع درمی بیش در نماز معفو است، اما زیاده را زایل باید کرد تا نماز درست باشد. دوم نجاست خفیفه همچو بول آنچه گوشت او را شرعاً توان خورد، و از اینجا تا بمقدار ربع جامه رسیدن پیش او معفو است . امابمذهب شافعی و احمد حنبل و مالک اندک و بسیار هر نجاستی مانع نماز است و ازاله ٔ آن واجب و مذهب صادق (ع ) نیز همین است، الا در پیش او در بول و روث ما یؤکل لحمه دو روایتست . و فقاع و منی مطلقاً نجسند. پس مکلف باید که بدن و جامه و جای نماز خود را از هرچه پیش مجتهدی نجس است پاک گرداند تا نماز او باتفاق درست باشد. و نجاست حکمی دو نوع است : یکی مغلظه که بموجب غسلست و دوم غیرمغلظه که موجب وضوء است . اما آنچه موجب غسل است پیش اکثر فقها سه چیز است : جنابت حیض و نفاس . و پنج چیز است در پیش صادق (ع ) این سه، و استحاضه مع غمس القطة، و مس میت آدمی پیش از غسل او. و فرض در غسل جنابت پیش ابوحنیفه سه چیز است : یکی مضمضه، دوم استنشاق، سوم شستن جمله ٔ اعضاء ظاهر بدن و بن مویها. و پیش شافعی دو چیز است : یکی نیت و دوم شستن جمله ٔ اعضاء ظاهر بدن با مویها و نهایت آن . و پیش مالک و احمد پنچ چیز است : نیت، مضمضه، استنشاق، رسیدن آب بهمه ٔ اعضا و دست مالیدن بر اندامها هنگام غسل . وپیش صادق (ع ) چهار چیز است : نیت با استدامت آن و رسانیدن آب بظاهر جمیع بدن و بن مویها و تخلیل مواضعی که آب بدون تخلیل بدانجا نرسد، و ترتیب یعنی اول سر بشوید، و بعد از آن جانب راست، و بعد آن جانب چپ . پس غسل صحیح بهمه ٔ مذهب آن باشد که مستجمع نیت بود برسبیل استدامت، و مضمضه استنشاق و شستن جمیع ظاهر بدن با مویها و منابت آن و مالیدن دست بر جمیع اندام اگرآب بدشواری آنجا رسد و اگر به آسانی، یا ترتیب و نیت برین وجه کند که : نویت الغسل، یا اغتسل من الجنابةلرفع الحدث و استباحة الصلوة قربة الی اﷲ. و اگر این معنی در دل بگذرانند جایز بود. اما بهتر آن بود که با عقد قلبی تلفظ نیز کنند. و بحث در غسل های دیگر همین است که در غسل جنابت گفته شد الا آنکه پیش احمد در غسل حیض موی گشادن واجبست و در جنابت نیست . اما نجاست غیر مغلظه که موجب وضوء است بمذهب ابوحنیفه هرچه از میلین (؟) بیرون آید و از غیر نیز اگر نجس باشد چون خون و ریم و قی ملاءالفم و اغما و جنون و خواب اگر به مضطجع باشد یا متکی یا مستند، نه آنکه ایستاده باشد یا در رکوع باشد یا در سجده، و قهقهه اگر نماز بود بمذهب شافعی خروج غیر منی از موضع معتاد یا ثقبه که زیر معده باشد اگر موضع معتاد بسته شود. و در زوال عقل به اغما یا جنون یا مستی یا خواب که غیر ممکن المقعد باشد بر زمین و تلاقی بشره ٔ مرد و زن که بیکدگر محرم نباشد، و شوهر هم درین صورت غیرمحرم است و مَس ّ فرج اگر قبل باشد یا بر مرد یا بر زن، صغیره یا کبیره، مرده یا زنده، و محل جنب همان حکم دارد. و بمذهب احمد همین است، مگر آنکه خواب اگرچه ممکن المقعدنباشد ناقض است و بمذهب صادق (ع ) بول است و غائط و باد از موضع معتاد و هر آنچه از آنجا بیرون آید متلطخ بنجاست همچو کرم و استحاضه ٔ قلیله، بخلاف وذی و مذی، و کرمی که متلطخ نباشد، و خوابی که مبطل سمع و بصرباشد، خواه ایستاده و خواه نشسته ممکن المقعد باشد یا غیر آن و هرچه عقل را زایل کند. و مذهب مالک نیز همین است . پس احتیاط آن باشد که چون یکی از اینها که بمذهبی از مذاهب ناقض است حاصل شود بی آنکه وضو سازدو نماز بگذارد. و فرایض وضوء بمذهب ابوحنیفه چهار چیز است : غسل وجه و یدین تا مرفقین و مسح مقدار ربعی از سر و غسل رجلین تا کعبین . و مذهب شافعی شش چیز است : نیت که مقارن اول غسل وجه باشد و یدین تا مرفقین و مسح بعضی از سر اگرچه یک موی باشد، و بقولی دیگر سه موی و غسل رجلین تا کعبین و ترتیب نگاه داشتن . و بمذهب مالک این شش است با زیادتی موالاة. و بمذهب احمداین هفت با زیادتی مضمضه و استنشاق، الا باید که نیت مقارن اول مضمضه باشد. و پیش مالک و احمد مسح جمیع سر فرض است . و بمذهب صادق (ع ) هفت چیز است : اول نیت با استدامت آن حکماً تا آخر وضوء، دوم غسل وجه، سوم غسل یدین، چهارم مسح سر بما یسمی مسحاً، پنجم مسح هردو پای به بقیه ٔ نداوت بی آنکه آب نو بردارد، و غسل پیش از مسح مبطل وضو باشد، و مسح بر موزه بدون ضرورت جایز نباشد، ششم ترتیب، هفتم موالات . پس وضوی صحیح بجمیع مذاهب آن باشد که مشتمل بود بر مضمضه و استنشاق و نیتی مقارن با اول مضمضه با استدامت آن تا آخر وضوء و غسل یدین تا مرفقین و مسح جمیع بر بقیه ٔ نداوت بی آنکه آب نو بر دارد زیرا که چون در غسل یدین تثنیه یا تثلیت واقع شده باشد آب نو برداشتن ازبرای مسح بهیچ مذهب فرض نیست و مسح رجلین همچنین و بعد از آن غسل آن با رعایت ترتیب و موالات در این افعال و ترک مسح بر موزه الاعلی الضرورة. اگر گویند زیادتی مسح بر مقدار معین و غسل رجلین به مذهب صادق (ع ) بدعت است، وبدعت موجب خلل در طاعت، گوئیم اتیان بدان مظنه خلل است در ثواب و ترک آن مظنه بطلان عمل، پس اتیان بدان اولی بود از ترک، اگر گویند جمع میان مسح و غسل بفرضیت هر دو یا به احدی برسبیل فرضیت با دیگری برسبیل ندبیت خلاف اجماع است، گوئیم جمع میان هر دو بنابر تحصیل واجبست بیقین چنانکه به وقت اشتباه تقدم احدی الجمعتین میان جمعه و ظهر جمع کند، و به وقت اشتباه قبله یک نماز را به دو جهت یا زیاده گذارند بنابر عدم غلبه ٔ ظن بجهتی معین و در وقت اشتباه منکوحه یا جنبیه از هر دو اجتناب نمایند برسبیل وجوب . پس اگر بعد ازمسح غسل بجای آرند به وجهی که یاد کرده شد تحصیلاً للمأموربه یقیناً وجوب هر دو یا وجوب احدی و ندبیت دیگری لازم نیاید. (قسم اول نفایس الفنون ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>). و رجوع به شرایع ص <span class=\"hlight\" dir=\"rtl\">١</span> و النهایه فی مجرد الفقه و الفتاوی ص <span class=\"hlight\" dir=\"rtl\">١</span>شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طهارت پاکی </span> ؛ این حکم رسماً و شرعاً در شریعت موسوی ازبرای اوقات مختلف وارد گشته بتوسط پاشیدن آب و شست وشو و یا غسل معمولی میگشت، و در ناپاکی و نجاسات مهم، طهارت با گذرانیدن ذبایح و قربانیها در بیت اﷲ بعمل میآمد. (سفر لاویان <span class=\"hlight\" dir=\"rtl\">١٢</span>: <span class=\"hlight\" dir=\"rtl\">١٥</span>، سفر اعداد <span class=\"hlight\" dir=\"rtl\">١٩</span>، لوقا <span class=\"hlight\" dir=\"rtl\">٢</span>: <span class=\"hlight\" dir=\"rtl\">٢٢</span> - <span class=\"hlight\" dir=\"rtl\">٢٤</span>). و نتیجه ٔ حقیقی و روحانی که از این مطلب به دست می آمد آن است که انسان ازبرای پاکی از عصیان و طهارت از ناپاکی گناه قربانی رفع گناهی لازم دارد. (اشعیا سفر خروج <span class=\"hlight\" dir=\"rtl\">٣٦</span>:<span class=\"hlight\" dir=\"rtl\">٢٥</span>، ذکریا <span class=\"hlight\" dir=\"rtl\">١٣</span>:<span class=\"hlight\" dir=\"rtl\">١</span>، عبرانیان <span class=\"hlight\" dir=\"rtl\">٩</span>:<span class=\"hlight\" dir=\"rtl\">١</span> و <span class=\"hlight\" dir=\"rtl\">١٣</span> و <span class=\"hlight\" dir=\"rtl\">١٤</span> و <span class=\"hlight\" dir=\"rtl\">١٩</span> و <span class=\"hlight\" dir=\"rtl\">٢٣</span> و <span class=\"hlight\" dir=\"rtl\">١٠</span>:<span class=\"hlight\" dir=\"rtl\">٢٢</span>). اما بعد از مراجعت بنی اسرائیل از اسیری رسوم طهارت علاوه بر آنچه شریعت امر فرموده بود فزون گردید. بخصوص فریسیان که آن رسوم نجاتبخش معمول میداشتندو ابداً در فکر معانی روحانی آنها نبودند. (مرقس <span class=\"hlight\" dir=\"rtl\">٧</span>:<span class=\"hlight\" dir=\"rtl\">١</span> - <span class=\"hlight\" dir=\"rtl\">٨</span> و <span class=\"hlight\" dir=\"rtl\">١٨</span>:<span class=\"hlight\" dir=\"rtl\">٢٣</span>) (قاموس کتاب مقدس ).<br /></font></div>'),
(177923, 'طهارت ترابیه', '<span class=\"hlight\">طهارت ترابیه .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ت ِ ت ُ بی ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) رکن سوم ازکتاب طهارت است و آن را چهار مبحث است : <span class=\"hlight\" dir=\"rtl\">١</span> - در آنچه تیمم با آن صحیح است و آن بر سه گونه است : الف - نبودن آب، ب - نرسیدن به آب، ج - خوف . <span class=\"hlight\" dir=\"rtl\">٢</span> - در آنچه رواست بدان تیمم کنند. رجوع به تیمم شود. <span class=\"hlight\" dir=\"rtl\">٣</span> - در کیفیت تیمم . <span class=\"hlight\" dir=\"rtl\">٤</span> - در اَحکام تیمم . رجوع به شرایع ص <span class=\"hlight\" dir=\"rtl\">١٢</span> شود.<br /></font></div>'),
(177924, 'طهارت جای', '<span class=\"hlight\">طهارت جای .</span><font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِ مرکب ) مبرز. بربخ . مبال . کنیف . آبریز. مرحاض . آبخانه . بیت الخلاء. آبشتنگاه . متوضَّاء. کنایه از متوضی، و پسین مستعمل ِ بعضی متأخرین است . (آنندراج ) <span class=\"hlight\">:</span> بسیار نشستن بر سر چاه طهارت جای زیان دارد (بیماری بواسیر را). (ذخیره ٔ خوارزمشاهی ).<br />عقل در دست یک رمه خودرای <br />چون چراغ است در طهارت جای .<br /> <font color=\"Red\">سنائی .</font><br />نقل است که شیخ چهل سال در مسجد مجاور بود، جامه ٔ مسجد جدا داشتی و جامه ٔ خانه جدا، و جامه ٔ طهارت جای جدا. (تذکرة الاولیاء عطار).<br /></font></div>'),
(177925, 'طهارت خانه', '<span class=\"hlight\">طهارت خانه .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ن َ<span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) رجوع به طهارت جای و آبخانه شود.<br /></font></div>'),
(177926, 'طهارت شکن', '<span class=\"hlight\">طهارت شکن .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ش ِ ک َ ]</font></b> (نف مرکب ) آنچه غسل و وضو و تیمم را باطل کند.<br /></font></div>'),
(177927, 'طهارت کردن', '<span class=\"hlight\">طهارت کردن .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ک َ دَ ]</font></b>(مص مرکب ) پاک ساختن آدمی کالبد یا عضوی از اعضاء خویشتن را یا چیزهای دیگری را از پلیدیهای آشکارا و ظاهری : طَهور؛ طهارت کردن . (منتهی الارب ) <span class=\"hlight\">:</span> <br />نماز در خم آن ابروان محرابی <br />کسی کند که بخون جگر طهارت کرد.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(177928, 'طهارت گاه', '<span class=\"hlight\">طهارت گاه .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِ مرکب ) مبرز. و رجوع به طهارت جای شود <span class=\"hlight\">:</span> موسی را عادت بود که چون طهارت کردی از خلق دور شدی و آن سنت شدی چون طهارت گاه رفت . (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span>).<br /></font></div>'),
(177929, 'طهاری', '<span class=\"hlight\">طهاری .</span> <font color=\"DarkGreen\"><b>[ طَ را ]</font></b> (ع ص، اِ) ج ِ طاهر (بر غیر قیاس ): ثیاب طهاری . <BR><font color=\"Blue\">◄</font> ج ِ طهیر.<br /></font></div>'),
(177930, 'طهاطه', '<span class=\"hlight\">طهاطه .</span> <font color=\"DarkGreen\"><b>[ طَ طِه ْ ]</font></b> (ع اِ) طهاطه الخیل ؛ آواز اسبان . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177931, 'طهاف', '<span class=\"hlight\">طهاف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) ابر بلندبرآمده . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177932, 'طهافة', '<span class=\"hlight\">طهافة.</span> <font color=\"DarkGreen\"><b>[ طُ ف َ ]</font></b> (ع اِ) پوست تُنک مانند سرشیر. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177933, 'طهامل', '<span class=\"hlight\">طهامل .</span> <font color=\"DarkGreen\"><b>[ طَ م ِ ]</font></b> (ع ص، اِ) ج ِ طَهْمَل .<br /></font></div>'),
(177934, 'طهب', '<span class=\"hlight\">طهب .</span> <font color=\"DarkGreen\"><b>[ طَ هََ ]</font></b> (ع اِ) از اسماء اشجار صغار است . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177935, 'طهبلة', '<span class=\"hlight\">طهبلة.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ل َ]</font></b> (ع مص ) رفتن در شهرها. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177936, 'طهر', '<span class=\"hlight\">طهر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) دور کردن چیزی را. (منتهی الارب ) (آنندراج ). یقال : طهره طهراً. (منتهی الارب ).<br /></font></div>'),
(177937, 'طهر', '<span class=\"hlight\">طهر.</span> <font color=\"DarkGreen\"><b>[ طَ هَِ ]</font></b> (ع ص ) پاک . (منتهی الارب ) (آنندراج ). پاکیزه . طاهر. ج، طَهِرون .<br /></font></div>'),
(177938, 'طهر', '<span class=\"hlight\">طهر.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع مص ) پاک گردیدن . <BR><font color=\"Blue\">◄</font> منقطع شدن حیض زن . <BR><font color=\"Blue\">◄</font> غسل آوردن به انقطاع خون و جز آن . <BR><font color=\"Blue\">◄</font> (اِمص ) پاکی از حیض و جز آن . ج، اطهار.(منتهی الارب ) (آنندراج ). قرء. خلاف طمث <span class=\"hlight\">:</span> <br />آب بهر عام اصل و فرع را<br />ازبرای طهر و بهر کرع را.<br /> <font color=\"Red\">(مثنوی ).</font><br />پاک کو از حوض مهجور اوفتاد<br />او ز طهر خویش هم دور اوفتاد.<br /> <font color=\"Red\">(مثنوی ).</font><br /><BR><font color=\"Blue\">◄</font> (اِمص ) بی نمازی . حیض . <BR><font color=\"Blue\">◄</font> پاکی (از اضداد است ).<br /></font></div>'),
(177939, 'طهر', '<span class=\"hlight\">طهر.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) طَرَخْشَقوق است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177940, 'طهر مثواه', '<span class=\"hlight\">طهر مثواه .</span> <font color=\"DarkGreen\"><b>[ طَ هََ رَ م َث ْ ]</font></b> (ع جمله ٔ فعلیه ٔ دعایی ) به معنی پاکیزه باد جایگاه وی، و آن را هنگام درود فرستادن بسوی مردگان ادا کنند.<br /></font></div>'),
(177941, 'طهران', '<span class=\"hlight\">طهران .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص، اِ) ج ِ طَهیر.<br /></font></div>'),
(177942, 'طهران', '<span class=\"hlight\">طهران .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) دهیست به اصفهان . (منتهی الارب ) (آنندراج ). از قراء اصفهانست و جماعتی از محدثان از آنجا برخاسته اند. (معجم البلدان ). در مشرق فریدن واقع است . و حمداﷲ مستوفی نیز در نزهة القلوب، طهران را یکی از قراء ناحیت جی اصفهان شمرده است . (نزهةالقلوب چ لیدن ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>). و رجوع به طیران شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177943, 'طهران', '<span class=\"hlight\">طهران .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) دهیست به ری . (منتهی الارب ) (آنندراج ). یاقوت در معجم البلدان آورده که :از مردی اهل ری که محل وثوق و اعتماد بود، شنیدم که : طهران دیهی است بزرگ و بنای این دیه تمامی در زیر زمین واقع است و احدی را یارای آن نیست که بدان دیه راه یابد، مگر آنکه اهالی آنجا اجازت ورود دهند. مکرر مردم آنجا بر پادشاه وقت شوریدند، و چاره ای ندیدندجز آنکه با ساکنین آنجا به مدارات رفتار کنند. طهران را دوازده محلت است که پیوسته اهالی هر محلت با اهالی محلت دیگر در جنگ و جدال میباشند و مردم محلتی با مردم دیگر محلت معاشرت و رفت وآمد نکنند. طهران باغ و بوستان پردرخت و جنگل مانند بسیار دارد که همان نیز سبب محفوظ ماندن اهالی از شر اشرار میباشد. راوی میگفت برزیگران طهران با وصف مناعت و حصانت مسکن و مأوای خویش مانند سایر برزیگران، اراضی را بوسیله گاوهای کاری و آلات و ادوات برزیگری شیار و زراعت نکنند، بلکه بمرور تخمی افشانند و محصولی بردارند، چه از دشمنان خویش بیمناکند و ترسند که گاوهای کاری و ادوات برزیگری دستخوش یغما و تاراج اشرار گردد. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>). طهران، قصبه ای معتبر است و آب و هوایش خوشتر از ری است، و در حاصل مانند آن، و در ماقبل اهل آنجا کثرتی عظیم داشته اند. و از معظم ناحیت غار است . (نزهة القلوب چ لیدن ص <span class=\"hlight\" dir=\"rtl\">٥٥</span> و <span class=\"hlight\" dir=\"rtl\">٥٣</span>). طهران، لقب آن دارالخلافه و دارالخلافه ٔ ناصری و دارالسلطنه بوده، در <span class=\"hlight\" dir=\"rtl\">٧١٠٠٠</span> متری ایوانکی و <span class=\"hlight\" dir=\"rtl\">٢٢٦٥٠٠</span> متری سمنان و <span class=\"hlight\" dir=\"rtl\">٤٢٦٠٠</span> متری ورامین و <span class=\"hlight\" dir=\"rtl\">٤٢٣٠٠</span> متری کرج و <span class=\"hlight\" dir=\"rtl\">١٤٧٠٠٠</span> متری قزوین و <span class=\"hlight\" dir=\"rtl\">٥٩٠٠٠</span> متری شمشک و <span class=\"hlight\" dir=\"rtl\">٢١٠٣٠٠</span> متری چالوس واقع شده است . صاحب مرآة البلدان ناصری بنقل از زینة المجالس گوید: شهرری از زمان قتل عام مغول تاکنون خراب مانده و الحال طهران و ورامین شهر آنجاست . آب و هوای طهران از سایر ولایات ری نیکوتر است، در قدیم قصبه بود، و حضرت پادشاه مغفور، در عمارت آن کوشیده و باروئی دور آن کشیده که تقریباً یک فرسخ دوره ٔ آن است (مقصود از پادشاه، شاه طهماسب است ). این شهر اکنون معمور و آبادان، و از ارتفاعاتش غله و میوه نیکو می آید از جمله خربزه و انگور و انجیر او نهایت لطیف می آید، اما خورنده ٔمیوه ها از تب و لرز مصون نیست - انتهی . و نیز از صاحب ریاض السیاحه نقل کرده است که طهران شهری است مشهور و بخوبی آب و هوا موصوف . حبوباتش ارزان، و فواکهش فراوان و اکثر میوه جات آنجا خاصه خربزه و انگور و انجیر ممتاز است . و در قدیم این شهر قصبه ای بوده بتدریج رو بعمارت نهاد، شاه طهماسب بن شاه اسماعیل صفوی در وسعت و عظمت آن کوشید، و بر آن حصاری حصین کشید، کریمخان زند نیز بعمارت آن افزود، و در اتساع آن سعی نمود، شهر در زمین هموار اتفاق افتاده و سمت شمالش فی الجمله گرفته و سایر اطرافش گشاده است - انتهی . و نیز از جام جم تألیف معتمدالدوله فرهادمیرزا نقل کرده که در ضمن احوال ری مرقوم فرموده اند که در شمالی ِ رَی طهران آباد شده و قدیماً قریه ای بود، و شاه طهماسب بزرگ سوری بر دور او کشید و در دولت قاجاریه آبادتر گشت، و اکنون پای تخت دولت ابدمدت است، و جمعیت آن اکنون تخمیناً صدوپنجاه هزار تن میشود و روزبروز بحلیه ٔ آبادی درمی آید و عمارات رفیعه و مساجد و مدارس عالیه و باغات بهجت انگیز در دولت قاجاریه طرح افکنده اند - انتهی . و نیز مؤلف مزبور بعد از نقل اقوال مذکور گوید: در نگارش احوال طهران دو چیز نگارنده را موجب تردید بود که آیا این لفظ را به تاء مؤلّف و در ضمن آن حرف نگارد، یا بتاء منقوطه و درین موضع ثبت نماید. یکی نگارش علمای جغرافی قدیم عرب و عجم و ارباب لغت که اغلب صریح به تاء منقوطه نوشته و آنهائی که به طاء مؤلف نگاشته باز اِشعار کرده اند که به تاء منقوطه نیز صحیح و وجه رجحانی هم برای تاء منقوطه ایراد کرده اند، دیگر فارسی بودن لفظ و کثرت تداول تاء منقوطه در لغت عجم و دیری درین تردید بود تا وجود و استدراک مرجح را از نواب والا وزیر علوم اعتضاد السلطنة العلیه العالیة، که اقوال حقیقت مآل ایشان سندی صحیح و معتمدٌعلیه جمیع فضلای عصر است تحریراً مشورت نمودم، جوابی مرقوم فرمودند که همان موجب رجحان تاء منقوطه گردیده آن را اختیار کرد، و برای مزید اعتماد واستبصار مطالعه کنندگان، عین آن رقیمه را ثبت کرد:<br />(صورت جواب نواب والا اعتضادالسلطنه وزیر علوم دامت افاضاته ) درباب طهران به تاء منقوطه نوشته اند و صحیح است . در آثارالبلاد بعد از بیهق که در ردیف باء است تبریز را نوشته، و بعد از تبریز طهران را به تاء منقوطه نگاشته، در معجم البلدان نیز به تاء منقوطه متوجه شده (در صورتی که در معجم البلدان چ مصر جلد <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٧٤</span> با طاء مؤلف آورده ) درین کتاب صراحةً و در آثارالبلاد کنایةًوجه تسمیه ٔ آن را به این نحو معین کرده است که چون اهل آنجا در وقتی که دشمن برای آنها بهم میرسید در زیر زمین پنهان میشدند، ازین جهت به این اسم موسوم شده است که «ته ران » یعنی زیر زمین میرفته اند. چون کتابی از معجم البلدان و آثارالبلاد معتبرتر نمیباشد، دیگر لازم نیست بخود زحمت بدهید و بسایر کتب رجوع کنید، بخصوص کتاب شما فارسی است و تاء منقوطه هم در فارسی استعمال شده است، زحمت شما را دوستدار کم کرد - انتهی .<br />مؤلف گوید پس از تمسک و استناد بچنین سندی متین اظهار میدارد که این شهر که اکنون دارالخلافه و پای تخت ایران، و محل سریر مهرمسیر اعلیحضرت مالک الرقاب و ولی نعمت کل ممالک محروسه است واقع در عراق عجم و سابق بر این قریه ای بوده از قراء ری که فاصله ٔ مابین هردو زیاده از یک فرسخ نبوده . هوای طهران به اتفاق جمیع علمای جغرافی سالم تر است از ری، و همان میوه جات که در ری یافت میشد درین شهر بعمل می آمده . اینکه ابتدا این آبادی را بانی کیست و چند قریه بوده مجهول است . از مسافرین عرب ابن حوقل و مسعودی که نهصد سال قبل بسمت ایران مسافرت نموده و ری را مفصلاً دیده و سیاحت کرده و وضع و هیئت شهر و حومه را نوشته از طهران اسمی نبرده اند، کتب جغرافی عرب که ذکری از طهران در آن شده منحصر است به آثارالبلاد و معجم البلدان و چنانکه ذکر کرده اند در زمان این دو نفر بیوتات این شهر در زیر زمین بوده، چندی بعد از این دو نفر قاضی عمادالدین ابویحیی زکریابن محمدبن محمود الانصاری که در ششصدوهشتادودو هَ . ق . وفات کرده کتابی موسوم بعجائب البلدان تصنیف نموده، در آن کتاب همین قدر ذکر مینماید که : طهران قریه ای است معظم جزو ایالت ری دارای باغات زیاد و در آن باغات اشجار میوه دار غرس شده و سکنه در خانه های سرداب مانند متوطنند، همین که دشمنی به ایشان حمله آرد بدان خانه های تحتانی پناه جسته و هر قدر محصور بودن آنها امتداد یابد بسبب کثرت آذوقه که از فرط احتیاط ذخیره کرده اند آسوده اند و بیرون آوردن ایشان از آن اماکن غیرمقدور است و چون دشمن مأیوس شد و معاودت کرد از زیر زمین بیرون آمده اطراف و جوانب شهر بلکه شوارع و طرق عام را که محل عبور و مرور قوافل و مترددین است فروگرفته به راهزنی و قتل و غارت مشغول میشوند، و دائماً بسلطان عصر یاغی و با عساکر او در زد و خوردند و مالیات خود را به زر مسکوک نیمپردازند، بلکه در عوض نقود و وجوه رایج خروس و مرغ میپردازند و با آنها باید برفق و مدارا حرکت کرد نه تسلط و حکم . زراعت آنها با بیل است با گاو زمین را شخم نمیکنند بلکه مطلق دواب و اغنام و احشام نگه نمیدارند که مبادا وقت محصور شدن بغارت برند.<br />حاجی خلیفه موسوم بمصطفی بن عبداﷲ چلبی ملقب بکاتب در جهان نامه ٔ خود شرحی از طهران نوشته و اهالی آن را وحشی و بیرحم خوانده است . یاقوت حموی و عبدالرشیدبن صالح بن نوری معروف به باکوئی و حمداﷲ مستوفی و احمد رازی صاحب تذکره ٔ هفت اقلیم که از مصنفات سنه ٔ هزارودو هَ . ق . است از میوه جات طهران توصیف کرده اند. احمدرازی در همین کتاب یعنی در تذکره ٔ هفت اقلیم گوید طهران بواسطه ٔ انهار جاریه و کثرت اشجار مثمره و باغات منزهه نظیر بهشت است خاصه بلوک شمیران که در شمال این قریه واقع است و از کمال خضرت و صفا و نضرت و بهااز حیز توصیف بیرون است . بلوک شمیران که به شمع ایران معروف بوده و بهترین ِ ییلاقات دنیاست . و نیز احمد رازی گوید: در دوفرسخی طهران قریه ای است معروف به کن سولقان که از زیادتی آبهای جاری و فواکه لطیفه و لطافت هوا ببستان پریان بیشتر شبیه است . بهترین میوه جات کن و سولقان گلابی و هلو است و احمد رازی مبالغه درتوصیف این دو میوه کرده بلکه میگوید بقدری که زبان برای دهان لازم، خوردن گلابی و هلوی کن و سولقان هم بهمان اندازه لزوم دارد. خلاصه اغلب مسافرین مسطور اراضی طهران را حاصلخیز و دارای باغات میوه خوب نوشته اند.<br />این شهر که الاَّن مقر خلافت عظمی است در زمان شاه طهماسب صفوی ابن شاه اسماعیل بواسطه ٔ کثرت میاه و اشجار و مکانتی که داشت محل توجه شده شاه طهماسب در سنه ٔ نهصدوشصت ویک هَ . ق . حکم کرد باروئی دور او بنا کردند که ششهزار گام دوره ٔ او بود و بعدد سور مبارکه ٔ قرآنی صدوچهارده برج برای بارو قرار دادند و در هر برجی یک سوره از سور قرآن مجید دفن کردند. چهار دروازه برای شهر ساختند و خندق دور بارو اتصال یافت با اراضی رمل زار و چون خاک خندق کفایت ساختن قلعه و بروج را نکرد از دو چال خاک برداشتند، چال میدان و چال حصار و از همان وقت این دو محل به این دو اسم موسوم شد. و دروازه ٔ دولت دروازه ٔ ارگ است که از بناهای افاغنه میباشد به این معنی که هر جا در ممالک محروسه ارگ بنا شده افغان بنا کرده ویک طرف آن را بصحرا وصل کرده که راه گریز باشد. امادر زمان سلطنت صفویه عمارت سلطنتی درین شهر ساخته نشد بلکه شاه عباس بزرگ سفری که بخراسان میرفت در طهران مریض شد و لعنت کرد کسی را که از خارج شهر طهران داخل این شهر شود و شب را در آن بیتوته کند. بعضی مورخین بر اینند که این لعن شاه عباس نه برای مریض شدن در طهران بوده بلکه بعلت وحشیگری و پذیرائی بد مردم این سرزمین از شاه عباس بوده . بهرحال اول پادشاهی که بیگلربیگی برای طهران و بلوکات او تا فیروزکوه معین کرد شاه عباس بود. پیرو دلاواله که در سال هزاروششصدوهجده م . مطابق هزاروبیست وهشت هَ . ق . به ایران سفرکرد و اول مسافر فرنگی است که از طهران عبور کرده مینویسد طهران از کاشان بزرگتر ولی تعداد سکنه ٔ آن کمتر از سکنه ٔ کاشان است . یک ثلث از زمین داخل حصار بیوتات و دو ثلث دیگر باغاتست . در قسمت بیوتات نیز در جمیع کوچه ها خیابان مانند درخت چنار غرس کرده اند و دور دائره ٔ تنه ٔ چنار بقدری است که چهار نفر که دست بهم بدهند به اِشکال میتوانند یک درخت را بغل کنند. این مسافر مینویسد: چنانکه اسلامبول بواسطه ٔ زیادتی درختهای سرو نزد بعضی مسافرین به سروستان معروفست طهران نیز باید به چنارستان موسوم باشد. این مسافر در طهران ابنیه ٔ عالیه ندیده که در سیاحتنامه ٔ خود ثبت کند... رضاقلیخان صاحب روضة الصفای ناصری، رَوَّح َ اﷲ روحه، مختصری از تاریخ طهران را در کتاب مسطور نگاشته، ما همان را بعینه بی رعایت سجع و قافیه مینگاریم :<br />طهران و مهران دو قریه بودند، بعد از خرابی ری، بازماندگان آن ناحیه بطهران جمع شده سکنی گرفتند، شاه طهماسب بن شاه اسماعیل صفوی که قزوین را پای تخت خود قرار داده بود، چون جد اعلای صفویه سیدحمزه در جوار حضرت عبدالعظیم حسنی نَوَّرَ اﷲ مرقده، مدفون بود گاه گاه بزیارت آن مراقد شریفه تشرف میجست، و حین عبور و مرور در حوالی طهران شکار میکرد، و کم کم به آبادی طهران رغبت کرده، باروی محکمی دور طهران کشید، پس از انقراض صفویه و افشاریه کریمخان زند بواسطه ٔ منازعه با سلطان محمدحسن شاه و نزدیک بودن این شهر بطبرستان و مازندران و استراباد که مقرسلطنت آن پادشاه بود صلاح خود را در توقف بطهران ندید ولی در آبادی آن کوشید...<br />توضیح، قنات مهرگرد که در ارگ جاری و دهنه ٔ آن در عمارت معروف به سرچشمه است متعلق بقلعه ٔ مهران و خیلی آباد بوده، گرد در لغت قدیم بمعنی آباد و معرب میشود به جرد، مثل : داراب گرد و داربجرد. روز یکشنبه ٔ یازدهم جمادی الاولای هزارودویست هَ. ق . که روز نوروز بود، حضرت آقامحمدشاه قاجار، در طهران جلوس کرد، سکه زدند و خطبه خواندند... و از آن وقت این شهر را دارالخلافه خواندند، و پایتخت سلسله ٔابدپیوند قاجاریه گردید.<br />در سال یکهزارودویست وبیست ودو هَ . ق . ژاک موریه نایب بسفارت انگلیس بایران آمد. این مسافر در سفرنامه ٔ خود مینویسد: پایتخت حالیه ٔ ایران طهرانست . دور باروی این شهر از چهار میل و نیم الی پنج میل است . این شهررا شش دروازه است که سردر و جوانب آنها را کاشی کاری کرده صورت ببر و حیوانات دیگر را در کاشیها نقش کرده اند، در سمت شمال غربی طهران بعضی یکه برجها در حوالی باروست که در یکی از آنها یک لوله ٔ توپ و یک زنبورک دیدم . شهر طهران ببزرگی شیراز ولی بیوتات و ابنیه ٔ آن کمتر از شیراز است . عمارات طهران چندان خوب نیست، زیرا که غالباً با خشت خام بنا شده و شباهت آنها به ابنیه ٔ عالیه کمتر است . تنها بنائی که قابل ملاحظه و تعریف است مسجد شاه میباشد که ناتمام است، و غیر از این مسجد شش مسجد کوچک در طهران هست که قابل ذکر نیست . این شهر سه چهار مدرسه ٔ بزرگ بیشتر ندارد. افواهاً میگویند صدوپنجاه کاروانسرا و بهمین شماره حمام در طهران هست . دو میدان بزرگ یکی در شهر و یکی در ارگ طهران است . دو عمارت ییلاقی سلطنتی این شهر راست، یکی قصر قاجار یکی نگارستان که تازه بنا مینمایند. هوای طهران بجهت نزدیکی آن بکوه البرز و دریای خزر که پشت کوه البرز است مختلف میباشد و در تابستان نهایت ناسازگاری را دارد. زمین شهری است و بارطوبت و شوره زار است . فصل گرما جز عجایز و عجزه در شهر نمیمانند. آب طهران نیز تعریفی ندارد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٥٠٨</span>-<span class=\"hlight\" dir=\"rtl\">٥٣٢</span> که آنچه در طی <span class=\"hlight\" dir=\"rtl\">٢٤</span> صفحه بود راجع به جغرافیا و آبادی طهران ثبت گردید).<br />آقای میرزا عبداﷲخان مستوفی در کتاب «شرح زندگانی من » آورده : برای انتخاب این شهر ده بیست هزار نفری جهت پای تخت جز نزدیکی این شهر به بلوکات نسبةً حاصلخیز و قرب جوار آن به مسکن ایل افشار ساوجبلاغ و عرب ورامین که هواخواهان او <font color=\"DarkGreen\"><b>[ شاه طهماسب ]</font></b> بوده اند و همچنین نزدیکی به استراباد ومازندران که در حقیقت ستاد نیروی او بوده است راهی نمیتوان فکر کرد... خندق و دیوار دور عمارت سلطنتی که حد شمالی آن میدان سپه و شرقی آن خیابان ناصرخسرو و جنوبی آن خیابان بوذرجمهری و غربی آن خیابان جلیل آباد (خیام ) بوده و پشت خندق دیوار قطور بلندی از گل داشته است شاید از کارهای آقامحمدخان باشد. دوره ٔ شهر طهران دیواری از زمان شاه طهماسب دوم صفوی داشته است . کندن خندق و بزرگ کردن طهران از کارهای آقامحمدخان است . درهرحال حدود آن از سمت شمال خیابان برق و سپه و از سمت غرب خیابان شاهپور و از جنوب خیابان اسماعیل بزاز (مولوی ) و از مشرق خیابان ری بوده است .<br />در اواسط سلطنت ناصرالدین شاه، احتیاج به بزرگ کردن شهر پیدا شد و خندق از سمت شمال بخیابان شاهرضا و ازسمت مغرب بخیابان سی متری تغییر یافته است، چون در سمت مشرق و جنوب بجای خندق ناصری خیابانی هنور کشیده نشده، تحدید آن به اسم و رسم ممکن نیست، ولی اجمالاً انبار غله از طرف جنوب نزدیک بخندق بوده و حد مشرقی شهر به اکبرآباد امروز منتهی میشده است که در دوره ٔ پهلوی خندقها پُر و شهر طهران بعظمت امروزه ٔ خود رسیده است . (تاریخ زندگانی من ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٢٥</span> - <span class=\"hlight\" dir=\"rtl\">٢٦</span>). و نیز از آثار حاج میرزا آقاسی گوید: یکی از کارهای مهم فلاحتی حاج میرزا آقاسی کشیدن نهری از رودخانه ٔ کرج برای یافت آباد و وسفنارد است که بعدها موجب آبادی کلاک و گرم دره و میان جوب و عده ٔ زیادی از دهات که امروزه ازین نهر مشروب میشوند شده است . این نهر را حاج میرزا آقاسی بوسیله ٔ سربازی فوج خلج قم کنده است . آبی هم که امروز از کرج بطهران می آید، تا سه چهار کیلومتر از همین نهر است و بعد به نهر علیحده میافتد و بالاخره از مجرای زیرزمینی بشهر طهران میرسد. آوردن این آب بطهران هم یکی از کارهای بسیار بسزای دوره ٔ رضاشاه است که طهران را به این عظمت رسانده است . از رودخانه ٔ جاجرود هم نهری برای امین آباد نزدیک شهرری کنده که در دامنه ٔ کوههای شمالی بهنام پازکی ورامین آثار آن باقی است ولی این نهر بواسطه ٔ گود بودن کف ِ دهنه ٔ رودخانه ٔ جاجرود آبی نشده <font color=\"DarkGreen\"><b>[ ظ: آفتابی نشده ]</font></b> و معلوم میشود حاجی خیال داشته سدی جلو دهنه ببندد که آب بالا بیاید و به نهر بنشیند که روزگار مجالش نداده و کار نیمه تمام مانده است . (شرح زندگانی من ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩</span>). و نیز درکتاب مزبور در موضعی دیگر گوید، بازار و سرای امیر از بناهای میرزا تقیخان امیرنظام است، در ایالات و ولایات نیز از عمارات دولتی تعمیر بسزائی کرده و هر جا بساختمان جدید حاجت داشته است ساخته و در داخله ٔ شهرها قراولخانه های زیاد برای توقف سرباز در سر چهارراهها بنا کرده است که هر یک گنجایش بیست نفر سرباز داشت که با افسر خود همیشه مواظب حفظ نظم در محله باشند. (شرح زندگانی من ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span>).<br />و نیز در ج <span class=\"hlight\" dir=\"rtl\">٣</span> همان کتاب در شرح آثار رضاشاه پهلوی آورده که : اول کار اساسی که برای آبادی شهر <font color=\"DarkGreen\"><b>[ تهران ]</font></b> کردند، آوردن آب کرج بطهران بود. من در ضمن کارهای فلاحتی حاج میرزا آقاسی در ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩</span> اشاره ای به این کار شایان تحسین دوره ٔ رضاشاه کرده ام و خواننده ٔ عزیز میداند که مقداری بر آب یافت آباد احداثی حاج میرزا آقاسی افزودند و بعد از سه چهار کیلومتر این نهر را دو شاخ کرده، شاخه ٔ جدید را برای شهر طهران تخصیص دادند و بعد از طی دو سه کیلومتر آب این نهر را بمجرای زیرزمینی انداختند و از شمال شهر وارد طهران کردند.<br />طهران، قنواتی که اکثر آنها مثل سرچشمه و حاج محمدعلی و نظامیه و سنگلج و قنات شاه وقف بر محلات شهر بود از قدیم داشت، ولی از زمان ناصرالدین شاه، بشرحی که در ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦</span> و <span class=\"hlight\" dir=\"rtl\">٣٥٠</span>نوشته ام که شهر را بزرگ کرده بودند، قنات تازه ای ایجاد نشده بود. درست است که باغاتی مانند لاله زار و نگارستان و سردار که از خود قنات داشتند نیز متروک شده بود ولی آب این قنوات همین قدر بود که خانه هائی را که در اراضی همان باغات ساخته بودند مشروب کنند و مابقی شهر جدید بی آب بود. بعضی مانند امین الدوله و قنات معینیه قنات خرابه هائی در شمیران پیدا کرده و آنهارا دائر نموده و بشهر آوردند ولی باز هم کفایت شهر را نمیداد، و حتی محله های داخل شهر قدیم هم بواسطه ٔ مزاحمتهای ساختمانهای جدید که گاهی از قنوات قدیم استفاده و شلتاق میکردند گرفتار تنگ آبی شده بودند. این نهر وزیرسو که شصت هفتاد سنگ آب از کرج به طهران میرساند، مایه ٔ آبادی محلات خارج شهر قدیم، و موجب ایجادخانه های جدید در ریگستانهای شمال شهر شد. خندق ناصرالدین شاهی را پر کردند و طهران بعظمت امروز رسید سهل است، این عمل موجب رفاه مزارع و باغات شمال شهر که در شمال نهر آب کرج واقعند نیز گردید، زیرا دیگر اهالی شهر احتیاجی به آب نداشتند که به زور پول و با رضایت مالکین آنها را خشکانده آب آنها را بشهر بیاورند.<br />بعد از این اقدام اساسی نوبت به وسیع کردن خیابانهای سابق و ایجاد خیابانهای جدید رسید. جزقدرت و اراده ٔ پهلوی با هیچ زور و زری ممکن نبود این توسیع و ایجاد صورت بگیرد. خانه ٔ اعیان بود یا خانه ٔ بیوه زن، مسجد بود یا مدرسه، متعلق بداخله بود یا خارجه، باغ سفارت بود یا عمارت دولتی، همین که داخل خط فرضی خیابان واقع میشد بخرابی مبتلا میگردید و بهرکیفیتی که بود، مقصود که گشایش خیابان تازه یا وسعت دادن خیابان سابق باشد حاصل میگشت .<br />بعد از اینها به اسفالت ریزی سنگفرش خیابان ها پرداختند و از میدان توپخانه که تغییر اسم داد و بمیدان سپه معروف گشته بود کاررا شروع کردند و خیابانها یکی بعد از دیگری اسفالت شد، اسفالت ریزی به خیابانهای فرعی و بعضی از معابر وکوچه ها هم رسید، حتی از شهر هم گذشت و از جانب جنوب تا کهریزک و از جانب مغرب تا نزدیکی کرج و از سمت شمال در دو خط تا تجریش راههای خارج شهر را هم اسفالت ریزی کردند.<br />برای ساختمانهای طرفین خیابانها هم مقرراتی وضع شد که تخلف از آنها برای احدی امکان پذیر نبود. ابتدا تصور میکردند این ساختمانها اگر متحدالشکل باشد بهتر است، ساختمانهای دوطبقه ٔ خیابان برق با ایوانهای فوقانی که نزدیک میدان سپه روبروی بانک انگلیس ساخته شد نتیجه ٔ این تصور خطای بوذرجمهری رئیس شهرداری وقت بود، بعد که بزشتی یک نواختی برخوردند، صاحب ملکها را در انتخاب اسلوب آزاد گذاشتند، و همین آزادی و رقابت جبلی بشری موجب شد که هرچه تاریخ ساختمان جلوتر می آید بناها زیباتر میشود. بناهای خیابان شاهرضا که از همه جدیدالاحداث تر است دلیل این گفته میباشد.<br />عمارات زیاد سلطنتی در خیابان کاخ و حول و حوش ساختمانهای دولتی مانند کاخ دادگستری و کاخ مالیه و عمارات وزارت داخله و صحیه و اداره ٔ ارزاق، ثبت اسناد و شهربانی و ابنیه ٔ وزارت جنگ و باشگاه افسران و بانک ملی و وزارت کشاورزی و اپرا و عمارت وزارت خارجه و ساختمان بیمه ٔ ایران و دهها بنای عالی دیگر که همه به امر این پادشاه ساخته شده است برای سایرین سرمشق شد.<br />امروز اگر در پس کوچه های پائین شهر هم بخواهند عمارت کهنه ای را خراب و بجای آن ساختمانی کنند اسلوب جدید را حکماً رعایت مینمایند و بسا دیده میشود که در میان خانه های خشتی یک طبقه ٔ قدیمی عمارات دو سه طبقه ٔ آجری و حتی سیمانی ساخته و افراخته شده است، بطوری که میتوان به ضرس قاطع گفت ولو در محله های پائین شهر هم دیگر هیچکس خانه ٔ جدید با خشت و گل نمیسازد وحدّاقل مصالح ساختمانهای امروزه آجر و گچ شده و کمتر بنای تازه ای است که بام آن کاهگلی باشد. در داخل ابنیه هم لوله کشی آب و برق از لوازم زندگی و تمام این بهبودیها در زندگی شخصی مرهون همین اقدام شاه سابق است . (شرح زندگانی من ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٣٢٤</span>-<span class=\"hlight\" dir=\"rtl\">٣٢٦</span>).<br />و نیز در ج <span class=\"hlight\" dir=\"rtl\">٣</span> همین کتاب آورده که : دیگر از کارهای خوب و شهرداریهای دوره ٔ رضاشاه، درختکاری خیابانهاست . خیابانهای قدیم عرض و طول و پیاده و سواره روی نداشت که در آنهادرختی کاشته شود، بر فرض اگر خیابانی مثل خیابان دروازه ٔ دوشان تپه و امیریه نسبةً عریض هم بود آبی نبودکه منظماً بدرختی بدهند بر فرض آنکه پاره ای از صاحبخانه ها عنایتی مبذول میداشتند و درختی میکاشتند، شاگرد خرکدارها که برای راندن خرهای خود حاجت به چوبدستی داشتند با بچه های ولگرد که میخواستند با اسب چوبی سوار شوند نهالهای کاشته ٔ صاحبخانه را نمیگذاشتند بزرگ شود، بر فرض اینکه از صد تا صاحبخانه یکی به درختکاری در حریم خانه ٔ خود اقدام میکرد و از صد تا درخت کاشته ٔ او یکی سایه افکن میشد، تازه گرفتار تطاول و تعدی سپورهای دوره ٔ مشروطه می گردید که تسمه از گرده ٔآنها کشیده، درختهای سایه افکن را بهیزم تبدیل میکردند.<br />رضاشاه پهلوی، عنایت خاصی به درختکاری داشت . هر سال در فصل بهار بلدیه مکلف بود آنچه از درختهای کاشته ٔ سال قبل بواسطه ٔ بی توجهی رفتگرها خشک شده بود و سالی نبود که در یکی دو سه تا از خیابانهای عقب مانده یا جدیدالاحداث درختکاری اولیه صورت نگیرد. این درختکاری بخیابانهای خارجی شهر هم رسید و خیابان از طهران به شمیران که یکی به سعدآباد و دیگری به تجریش میرود و در سرپل بهم می پیوندد. و در طرفین دو نهر تنگ درز درختکاری شده مخصوصاً خیابان پهلوی که بفاصله ٔ هر دو متر یک درخت چنار و بعلاوه در هر سی چهل ذرع فاصله، یک بوته ٔ گل سرخ کاشتند. مواظبت این پادشاه در این امر بقدری بود که در زمستان <span class=\"hlight\" dir=\"rtl\">١٣١٩</span> امر داد بلدیه پای درختهای خیابان پهلوی را از سمت بیرون نهر بعمق یک متر و نیم گودبرداری، و با کامیون از طهران کود حمل و کنده ها را پر کردند. (قسمت <span class=\"hlight\" dir=\"rtl\">١</span> از ج <span class=\"hlight\" dir=\"rtl\">٣</span> شرح زندگانی من صص <span class=\"hlight\" dir=\"rtl\">٣٢٧</span> - <span class=\"hlight\" dir=\"rtl\">٣٢٨</span>). آقای کیهان در ج <span class=\"hlight\" dir=\"rtl\">٢</span> جغرافیای خویش که مخصوص قسمت جغرافیای سیاسی است مینویسد:این ایالت <font color=\"DarkGreen\"><b>[ ایالت طهران ]</font></b> از شمال محدود است به مازندران، و از مشرق به سمنان و از جنوب به قم و کویر و از مغرب به قزوین و ساوه، طول آن از مشرق به مغرب (غرق آباد تا فیروزه کوه ) <span class=\"hlight\" dir=\"rtl\">٢٦٠</span> و عرض آن از شمال بجنوب (از گردنه ٔ کندوان تا دریاچه ٔ قم ) <span class=\"hlight\" dir=\"rtl\">١٢٠</span> کیلومتر، و مساحت آن در حدود <span class=\"hlight\" dir=\"rtl\">٣١٠٠٠</span> کیلومتر مربع است .<br />خلاصه ٔ اوضاع طبیعی : در شمال طهران کوه البرز از مغرب به مشرق امتداد یافته و از شمال غربی شعبه ای از کوههای مرکزی تا شمال دریاچه ٔ قم ممتد شده و از مشرق از فیروزکوه رشته ٔ دیگری تا کویر امتداد یافته و بین این سه رشته جلگه ٔ وسیعی است که ولایات طهران را تشکیل داده و آبادیهای آن در زاویه های شمال غربی و شمال شرقی و دامنه های شمالی واقع شده است . بطور کلی طهران را از نظر طبیعی میتوان به دو قسمت تقسیم کرد: اول - قسمت کوهستانی، دوم - قسمت جلگه ای که دنباله ٔ آن بزمینهای بیحاصل و کویر محدود میشود.<br /><span class=\"hlight\" dir=\"rtl\">١</span> - قسمت کوهستانی : از سرچشمه ٔ رودهای حبله رود و جاجرود و کرج شروع شده و به جلگه ٔ طهران ختم میشود ولی آب بعضی قسمت های کوهستانی که فعلاً جزء ایالت طهرانست وارد بحر خزر میشود مانند طالقان و دره ٔ لار.<br /><span class=\"hlight\" dir=\"rtl\">٢</span> - جلگه ٔ طهران : از رسوبات رودهای فوق تشکیل یافته و در آن شعبی از جبال شمالی بجنوب پیش رفته مانند کوه های قره گچ و کوه نمک و کوه سه کوه در مشرق سه پایه و بی بی شهربانو در مرکز کوههای بقادر و کوه نمک نزدیک رباطکریم و کوه حسن آباد که بعضی قسمتهای آنها تا کویر پیش میرود. در قسمت غربی این جلگه دره ٔ طویلی است که از حوالی قزوین شروع شده و رودهائی ماند ابهررود کردان کرج و غیره ازشمال غربی به جنوب شرقی در آن جاری و بواسطه ٔ رسوبات خود نواحی زراعتی ساوجبلاغ و شهریار و غار و قسمتی از ورامین را تشکیل داده اند، در ورامین و خوار رسوبات رودهای مذکور ضمیمه ٔ جاجرود میگردد.<br />آب و هوای ناحیه ٔ کوهستانی سرد و دارای بارندگی بیشتر و بهمین واسطه هوای آن در تابستان لطیف است . ناحیه ٔ جلگه را میتوان به دو قسمت کرد: قسمت شمالی آن که در دامنه ٔ کوهها واقع است دارای آب و هوای معتدل و تا حدی از بارانهای کوهستانی بهره مند میشود. قسمت جنوبی که بکلی خشک و باران آن کم و فقط از آب رودها استفاده میکند، بنابراین از قسمت کوهستانی شمالی رودها و جویبارهای متعدد تشکیل شده بسمت جنوب میروند و مهم ترین آنها و از مشرق بمغرب عبارتند از: حبله رود که از فیروزکوه سرچشمه گرفته خوار را مشروب میکند. جاجرود که از کلون بسته سرچشمه گرفته و پس از ضمیمه شدن به رود دماوند جلگه ٔ ورامین را مشروب میکند. رود کرج که سرچشمه ٔآن نیز از کلون بسته است و قسمتی از آب آن بطرف شهرطهران رسیده ولی بستر طبیعی آن بطرف شهریار و پشاپویه متوجه است . ابهررود از جنوب قزوین شروع شده و به اسم رود شور وارد مسیله میشود.<br />تقسیمات حکومتی طهران از قرار ذیل است : <span class=\"hlight\" dir=\"rtl\">١</span>- طهران و حومه <span class=\"hlight\" dir=\"rtl\">٢</span> - فیروزکوه <span class=\"hlight\" dir=\"rtl\">٣</span> - دماوند <span class=\"hlight\" dir=\"rtl\">٤</span> - لواسان و رودبار و لورا و شهرستانک <span class=\"hlight\" dir=\"rtl\">٥</span> - طالقان <span class=\"hlight\" dir=\"rtl\">٦</span> - خوار <span class=\"hlight\" dir=\"rtl\">٧</span>- ورامین <span class=\"hlight\" dir=\"rtl\">٨</span> - غار و پشاپویه <span class=\"hlight\" dir=\"rtl\">٩</span> - شمیران <span class=\"hlight\" dir=\"rtl\">١٠</span> - کن و سولقان وارنگه <span class=\"hlight\" dir=\"rtl\">١١</span> - ساوجبلاغ <span class=\"hlight\" dir=\"rtl\">١٢</span> - شهریار.<br /><span class=\"hlight\" dir=\"rtl\">١</span> - طهران و حومه : از شمال محدود است بشمیران و از مشرق و جنوب به غار و از مغرب به کن . طول آن از شمال بجنوب <span class=\"hlight\" dir=\"rtl\">١٢</span> و عرض آن از مغرب بمشرق <span class=\"hlight\" dir=\"rtl\">١٨</span> کیلومتر و مرکز آن شهر طهران پای تخت ایران است .<br />جغرافیای تاریخی طهران : وجه تسمیه ٔ آن معلوم نیست و نویسندگانی هم که راجع به کلمه ٔ طهران تحقیقاتی نموده اند اغلب بعقیده ٔ خود اظهاراتی کرده که هیچکدام مأخذ صحیحی ندارد، همین قدر معلوم است که طهران یکی از قرای کوچک ری بوده . اصطخری و ابن حوقل و مسعودی اسم طهران را در کتب خود ذکر کرده اند. در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٥٦١</span> هَ . ق . مادر ارسلان سلجوقی در موقع حرکت از ری به نخجوان در دولاب که نزدیک دولاب است توقف کرده است .<br />نویسندگان مذکور طهران را دارای باغ های میوه و خانه های پست و زیرزمینهای متعدد دانسته اند. اهمیت تهران از وقتی شروع شده که شهرهای مهم مجاور آن مانند ری (که در سال <span class=\"hlight\" dir=\"rtl\">٦١٧</span> هَ . ق . به دست مغول ویران شد) خراب گردیده در موقع کشمکش تیموریان و غیره تهران چندان اهمیتی نداشت و فقط از زمان صفویه یعنی در دوره ٔ شاه طهماسب اول دیواری بر اطراف که دارای چهار دروازه و چهارده برج بود کشیده شد و بازاری ساخته شد برای بنای ارگ اولیه از دو نقطه ٔ شهر که اسم خود را به دو محله ٔ شهر داده اند خاک برداشته شد، یکی چال میدان و دیگری چال حصار در <span class=\"hlight\" dir=\"rtl\">٩٩٨</span> هَ . ق . شاه عباس کبیر در موقعی که به سرکوبی عبدالمؤمن خان ازبک میرفت در تهران مریض شد و مرض او مانع حرکتش گردیده ازبکها مشهد را مسخر کردند و شاه عباس بهمین جهت از طهران متنفر گردید معهذا باغی در آن بنا کرد موسوم به چهارباغ ارگ فعلی تهران قبل از هجوم افغانها شاه سلطان حسین مدتی در تهران توقف کرد ولی همین که افغانها نزدیک شدند بمازندران گریخت و تهران مقاومت شدیدی کرد و عده ای از افغانها کشته شدند.<br />پس از شکست اشرف در مهماندوست افغانهائی که در تهران بودند، شهر را غارت کردند و عده ٔ کثیری را کشتند و به اصفهان فرار کردند و شاه طهماسب به طهران آمد.<br />در <span class=\"hlight\" dir=\"rtl\">١١٥٤</span> هَ . ق . نادرشاه تهران را به پسر خود رضاقلی میرزا به تیول داد و در <span class=\"hlight\" dir=\"rtl\">١١٧١</span> محمدحسنخان قاجار پس از شکست از کریم خان زند به طهران آمد و قشون او بکلی متفرق شد و کریمخان یکی از سردارهای خود موسوم به شیخعلی خان را با کمک محمدحسن خان دولو به تعقیب او فرستاد و محمدحسن خان قاجار مغلوب و مقتول شده کریم خان با قشونش در <span class=\"hlight\" dir=\"rtl\">١١٧٢</span> وارد تهران شد و با احترامات کافی محمد حسنخان را در حضرت عبدالعظیم بخاک سپرد. سال بعد امر داده شد که عمارتی برای دارالحکومه بسبک ساسانیان و دیوانخانه و قراولخانه ساخته شود، و بنای باغ جنت را به کریمخان نسبت میدهند. ظاهراً کریمخان درصدد آن بوده است که تهران را پای تخت خود قرار دهدو در همین محل آغامحمدخان قاجار را از مازندران بحضور کریمخان آوردند و با کمال رأفت و مهربانی با او رفتار کرد ولی آغامحمدخان بعدها بجای این بلندهمتی از شدت قساوت جسد کریمخان را از شیراز به طهران منتقل کرده در پای یکی از پله های عمارت خود دفن کرد که هرروز آن را لگدکوب کند. ولی در عهد پهلوی به پاس احترام خدمات کریمخان استخوانهای او را با احترام بیرون آورده و در حضرت عبدالعظیم دفن کردند. در <span class=\"hlight\" dir=\"rtl\">١١٧٦</span> کریمخان از پای تخت نمودن طهران منصرف شده و حکومت آن را به غفورخان داده و شیراز را پای تخت قرار داد. از کتب قدیم جغرافیائی چنین استنباط میشود که شهر طهران ابتدا در قسمت جنوبی بنا شده و خانه های پستی داشته که شبیه به غار بوده است و بعدها کم کم از طرف شمال توسعه یافته و منازل را بیشتر به سرچشمه ٔ قناتها نزدیک کرده اند. از بناهای قدیم قبل از زندیه و متعلق به آن چیزی باقی نمانده و بنای این شهر بیشتر از زمان قاجاریه باقی مانده و <span class=\"hlight\" dir=\"rtl\">١١٧٥</span> هَ .ش . شهر تقریبا از نو ساخته شده و ابتدا بصورت مربعی بوده، مساحتش قریب به پنج کیلومتر مربع، ولی نصف آن بیشتر دارای ساختمان نبوده، و جمعیت آن با نظامیان فقط <span class=\"hlight\" dir=\"rtl\">١٥٠٠٠</span> تن بوده، در زمان آغامحمدخان قصوری در ارگ ساخته شد و تخت مرمر که بیشتر اثاثه و مصالح آن را از قصر کریمخانی شیراز آورده بودند در آن موقع ساخته شد، پانزده سال بعد از آن تاریخ، طهران توسعه یافته و جمعیت آن به پنجاه هزار نفر رسید و محیط شهر هفت الی هشت کیلومتر شد، ولی بواسطه ٔ گرمای فوق العاده ٔ تابستانی جمعیت آن در موقع تابستان فقط <span class=\"hlight\" dir=\"rtl\">١٠٠٠٠</span> تن و بقیه به کوهستانات شمالی میرفتند، در این وقت شهر دارای حصار و خندقی بوده، ولی این حصار از نظر دفاع با اسلحه ٔ جدید نمیتوانسته است مقاومت نماید، همچنین شش دروازه و سی مسجد و مدرسه وسیصد حمام داشته . در <span class=\"hlight\" dir=\"rtl\">١١٩٥</span> هَ . ق . سه دروازه به آن اضافه شد و جمعیت آن به <span class=\"hlight\" dir=\"rtl\">٧٠٠٠٠</span> تن بالغ گردید. در زمان فتحعلیشاه ابنیه ٔ دیگری ساخته شد، در <span class=\"hlight\" dir=\"rtl\">١٢٢٣</span> هَ . ق .قطر شهر از مشرق بمغرب <span class=\"hlight\" dir=\"rtl\">٣٨٠٠</span> متر، و از شمال بجنوب <span class=\"hlight\" dir=\"rtl\">٩٠٠</span> تا<span class=\"hlight\" dir=\"rtl\">٢٤٥٠</span> متر، و مساحت آن قدری بیش از هشت کیلومتر مربع میشده، دیوار ارگ در قسمت شمالی بدیوار شهر متصل میشده، و در خارج دیوار باغهای وسیع بوده، و پرجمعیت ترین محلات در جنوب شرقی ارگ در محلی که امروز موسوم به دروازه ٔ شاه عبدالعظیم میباشد، بوده است . دروازه های شهر درین دوره، شش باب و یک میدان موسوم بمیدان شاه در جنوب ارگ داشته و بناهای مهم آن، مسجد شاه، و امامزاده زید، و امامزاده یحیی بوده . تاریخ اتمام مسجد شاه، در <span class=\"hlight\" dir=\"rtl\">١٢٢٤</span> هَ . ق . و کتیبه های آن بخط محمد مهدی است، بنای آن قریب <span class=\"hlight\" dir=\"rtl\">٣١</span> سال طول کشید. در <span class=\"hlight\" dir=\"rtl\">١٢٢٦</span> هَ .ش . جمعیت در تابستان <span class=\"hlight\" dir=\"rtl\">٨٠٠٠٠</span> و در زمستان <span class=\"hlight\" dir=\"rtl\">١٢٠٠٠٠</span> تن بوده است . از <span class=\"hlight\" dir=\"rtl\">١٢٤٨</span> تا <span class=\"hlight\" dir=\"rtl\">١٢٥٣</span> شهر تغییرات کلی یافت و ازهمه طرف وسعت پیدا کرد، خندق قدیمی و دیوارها را برداشتند و خندق جدیدی بشکل هشت ضلعی حفر شد و این خندق از روی خندق شهر پاریس ایجاد گردید ولی استفاده ٔ نظامی بهیچوجه از آن نشد، فقط دروازه های آن برای تفتیش ورود و خروج مسافرین و حیوانات و خندق آن برای جلوگیری سیلهای ناگهانی البرز بسیار مفید بوده است . دروازه های اصلی شهر دوازده باب و دروازه ٔ قدیمی تا مدتی در داخل شهر باقی بوده، ولی اسامی آنها را به دروازه های جدید اطلاق کردند. محیط خندق شهر <span class=\"hlight\" dir=\"rtl\">١٩٥٩٦</span> متر و مساحت داخلی خندق <span class=\"hlight\" dir=\"rtl\">١٩٥</span> کیلومتر مربع است . در نزدیک دروازه دولت قدیم میدان توپخانه (میدان سپه فعلی ) بطول <span class=\"hlight\" dir=\"rtl\">٢٤٧</span> و عرض <span class=\"hlight\" dir=\"rtl\">١١٠</span> متر ساخته شد که سابقاً در قسمت تحتانی دارای انبارهای توپ و در قسمت فوقانی محل توپچی ها بوده ولی فعلاً در شمال آن عمارت بلدیه، در مشرق عمارت بانک شاهنشاهی، در جنوب عمارت پست و تلگراف، و در مغرب آن عمارت نظمیه است . در مرکز میدان مزبور سابقاً باغچه و حوضی بوده و در اطراف آن توپهائی که از پرتغالیها در زمان صفویه گرفته شده بود قرار داده بودند ولی فعلاً بجای آن باغچه ٔ مصفائی یا گلخانه ٔ بلدی و فواره ها ایجاد شده، و در اطراف این میدان سابقاً شش دروازه بوده که به شش خیابان مربوط میشده ولی آن دروازه ها را برداشته و خیابانهای شرقی و غربی و جنوبی آن را عریض نموده اند.<br />تفرجگاههائی که سابقاً از دروازه ٔ بیرون بوده، پس از حفر خندق جدید جزء شهر شده مانند باغ لاله زار و باغ وحش و باغ سردار و نگارستان و پس از توسعه ٔ سفارتخانه های خارجی که سابقاً در مرکز شهر بوده به قسمت شمالی منتقل شدند ولی بازار همان در محل اصلی یعنی در جنوب ارگ باقی ماند.<br />از بناهای قابل ذکر تهران مسجد سپهسالار از بناهای حاج میرزا حسینخان سپهسالار است که مجلس شورای ملی به آن متصل و اصلاً از بناهای سپهسالار بوده و تغییراتی جزئی در آن داده شده، مسجد شاه و مسجد جامع و مسجد شیخ عبدالحسین و مدارس قدیمه از قبیل مسجد مروی و مدرسه ٔ صدر و مدرسه ٔ مادر شاه و غیره هم از بناهای بالنسبه معتبر است . از بناهای جدید که اخیراً ساخته شده بنای بانک شاهنشاهی است که سردر آن را با کمال زیبائی کاشی کاری کرده اند. ترقیات اخیر تهران از حیث مؤسسات جدید عبارتست از مؤسسات بلدی مانند: صحیه و معاونت عمومی مریضخانه ها، دارالمجانین، پستهای امدادی، پرورشگاههای کودکان، مدرسه ٔ صنعتی، آسایشگاه ناتوانان، دارالرضاعه، ساختمانها و گردشگاههای عمومی مانند: باغ ملی (در محل میدان مشق ) و باغ فردوس (در محل قبرستان سرقبر آقا) و مخصوصاً تهیه و تأمین آب شهر که شرح آن مفصلاً بقرار ذیل است : آب مشروبی طهران، قبل از تشکیلات بلدیه ٔ فعلی (سال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> هَ . ش .) مسؤولیت شرب شهر را اشخاص غیرمسؤول عهده دار بودند و هیج قاعده و قانونی در امور شرب منظور نمیشد، و در واقع منازل و باغات اقویاء و صاحبان نفوذ اغلب سیراب، و ضعفاءو طبقه ٔ متوسطه همیشه در زحمت بودند. حق الشربی که از مردم گرفته میشد مطابق هیچ روش عادلانه ای نبود، بعداز آنکه بلدیه مسؤولیت شرب شهر را تقبل کرد با اعتراضات حق و باطلی مواجه شد و همیشه درصدد بود که از روی اصول صحیحی آب مشروب شهر و وضع تقسیم و اخذ حق الشرب را تصحیح کند تا آنکه در برج عقرب <span class=\"hlight\" dir=\"rtl\">١٣٠٣</span> هَ . ش . کمیسیونی مرکب از نمایندگان فنی وزارت فوائد عامه و قشون و بلدیه انعقاد یافت و بهترین طریقه ٔ علمی و عملی را که برای اخذ حق الشرب تشخیص دادند مساحی محلهای مشروبی شهر بود. درنتیجه ٔ این تصمیم دوازده دسته مساح و معمار از <span class=\"hlight\" dir=\"rtl\">١٤</span> قوس <span class=\"hlight\" dir=\"rtl\">١٣٠٣</span> تا اواسط فروردین <span class=\"hlight\" dir=\"rtl\">١٣٠٤</span> هَ. ش . کلیه ٔ نقاط شهر را مساحت نمودند.<br />آب شهر در قرن اخیر: مجرای کرج، قریب نود سال است که موضوع آب تهران نظر اولیای امور را جلب کرده و در هر تاریخ درصدد تهیه ٔ آن بوده اند. در اواسط سلطنت محمدشاه (تقریباً <span class=\"hlight\" dir=\"rtl\">١٢٥٥</span>) حاج میرزا آقاسی دو نهر بزرگ از رودخانه ٔ کرج جدا کرده بطهران آورد: یکی نهری که همه جا از دامنه ٔ البرز عبور کرده و از شمال قریه ٔ طرشت گذشته به عباس آباد منتهی میشد و هنوز آثار کرت و مرز درآنجا باقی است و باز هم ممکن است قابل استفاده شود ولی پس از فوت حاج میرزا آقاسی بکلی بی استفاده گردید.دیگری نهری است که همه جا از زیر جاده ٔ کنونی قزوین گذشته و به قریه ٔ یافت آباد میرسد و تا حال دائر است .<br />بعدها آب مشروب شهر منحصر شد بچند رشته ٔ قنات وقفی و فاضل قنات شاه، و وضع آب طهران بحالت بسیار خرابی درآمد، تاآنکه مرحوم میرزا عیسی وزیر، خطر تشنگی پایتخت را بخوبی احساس کرد و باآنکه وضع مالی او اجازه نمیداد با زحمت قنوات بسیار حفر کرد که هنوز هم باقی و در تصرف اشخاص است و برای هر رشته اسمی گذارده اند.<br />در اواخر دوره ٔ ناصرالدینشاه چند نفر خارجی امتیاز حفر چاههای آرتزین را گرفته در شمال طهران مشغول حفاری شدند اما در حین کار مته ٔ چاه کنی شکست و بواسطه ٔ نبودن طرق شوسه و اشکالات دیگر پس از تحمل خسارت از تعقیب مقصود مأیوس و منصرف گردیدند. پس از سلطنت ناصرالدین شاه و زمان شاهان دیگر قاجاریه هم اقدامی برای آوردن آب بعمل نیامد.<br />پس از تشکیل دولت فعلی که پایتخت ایران بمفهوم حقیقی دارای بلدیه ای شد (سال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span>) این مؤسسه در ضمن اصلاحات دیگر تهیه و تنظیم آب شهر را منظور خود قرار داد، از طرفی قنوات موجوده را از چنگال میرابها خارج و با کمی آب امر شرب شهر را صورتی داد و از طرفی درصدد تهیه ٔ آب بمقدار کافی از خارج برآمده، یک نفر مستشار مهندس را مأمور تحقیق و انجام این امر کرد، و او پس از مطالعات زیاد پیشنهاد بنای سد و ایجاد منبع آب در جاجرود را تهیه و تقدیم کرد، و او در این پیشنهاد پیش بینی مخارج آن بالغ بر <span class=\"hlight\" dir=\"rtl\">١٧٠٠٠٠٠</span> تومان میشد و بعلت فقدان سرمایه و علل دیگر این پیشنهادموقوف ماند، بعدها دوباره بلدیه درصدد تهیه ٔ آب و قوه ٔ برق برآمده، و در سال <span class=\"hlight\" dir=\"rtl\">١٣٠٦</span> هیئتی مأمور مطالعات در بستن سد جاجرود کرد و هیئت مزبور هم نتیجه ٔ مطالعات خود را تقدیم کرد. عملی شدن این پیشنهاد تقریباًچهارصدهزار تومان خرج داشت ولی ممکن بود تا حدود صدوپنجاه هزار چراغ شانزده شمعی به شهر بدهد، از طرفی عایدات سالیانه ٔ این امر هم بطریقی که پیش بینی شده بودتقریباً در حدود پانصدوشصت هزار تومان بود و از همه حیث تکافو مخارج ضروری بلدیه را می کرد، متأسفانه این فکر هم عملی نشد.<br />سرانجام متعاقب خشکسالی <span class=\"hlight\" dir=\"rtl\">١٣٠٦</span> هَ . ش . و خطر تشنگی، بلدیه تصمیم گرفت بهر زحمت و قیمتی هست آب برای طهران تهیه نماید، و چند تن را مأمور تحقیقات و تفتیشات جدید نمود و آنها پیشنهاد دیگری راجع به حفر مجرای کرج تهیه و تقدیم کردند که موقع قبول واقع و فوراً بموقع اجرا گذارده شد. بند مجرای کرج بالای قریه ٔ سرجوب تقریباً مقابل بیلقان و مظهر آن در طهران، نزدیکی جمشیدآباد واقع است . طول مجرای مزبور <span class=\"hlight\" dir=\"rtl\">٥٢</span> کیلومتر است که <span class=\"hlight\" dir=\"rtl\">٢٠</span> کیلومتر آن زیرزمینی و <span class=\"hlight\" dir=\"rtl\">٣٢</span> کیلومتر دیگر آن روباز است . از اول بند الی انتهای اراضی کلاک که تقریباً <span class=\"hlight\" dir=\"rtl\">١٥</span> کیلومتر است تمام آب کرج از یک نهر روباز بطرف طهران جریان دارد. در انتهای کلاک تمام آب وارد دو مجری میشود که بطور متوازی بفاصله ٔ <span class=\"hlight\" dir=\"rtl\">٢٥</span> الی <span class=\"hlight\" dir=\"rtl\">٤٠</font></div>'),
(177944, 'طهرانی', '<span class=\"hlight\">طهرانی .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ص نسبی ) منسوب به طهران، خواه طهران اصفهان و خواه طهران ری، و شهرت به این نسبت در مورد طهران ری بیشتر از طهران اصفهانست . (سمعانی ). و رجوع به ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٩٤</span> شود.<br /></font></div>'),
(177945, 'طهرانی', '<span class=\"hlight\">طهرانی .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) رجوع به محمدتقی بن عبدالرحیم الطهرانی الرازی در الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٧٤</span> شود.<br /></font></div>'),
(177946, 'طهرانی', '<span class=\"hlight\">طهرانی .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) رجوع به محمدحسین بن عبدالرحیم الطهرانی الرازی در الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٩١</span> شود.<br /></font></div>'),
(177947, 'طهرانی رازی', '<span class=\"hlight\">طهرانی رازی .</span> <font color=\"DarkGreen\"><b>[ طِ ی ِ ]</font></b> (اِخ )قفطی در اخبار الحکما گوید: «کتاب المسائل قصرانی منجم را بخط طهرانی رازی خود دیده ام ». (قفطی ص <span class=\"hlight\" dir=\"rtl\">٢٦٥</span>).<br /></font></div>'),
(177948, 'طهرتن', '<span class=\"hlight\">طهرتن .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) یکی از فرمانروایان ارزنجان در عصر تیموری . حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٠</span> و رجوع به فهرست همان جلد ذیل کلمات ارزنجان و طهرتن شود.<br /></font></div>'),
(177949, 'طهرجان', '<span class=\"hlight\">طهرجان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) صورتی از طمرجان، یا طحوان، یا طیم جان، یا طمیرخان که دیهی است از حوالی مرغزار آورد (معروف به کوشک زرد)از مرغزارهای فارس . (نزهةالقلوب چ لیدن ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(177950, 'طهرس', '<span class=\"hlight\">طهرس .</span> <font color=\"DarkGreen\"><b>[ طِ رِ ]</font></b> (ع اِ) بعربی اسم لبن است . (فهرست مخزن الادویه ) (بحرالجواهر).<br /></font></div>'),
(177951, 'طهرمس', '<span class=\"hlight\">طهرمس .</span> <font color=\"DarkGreen\"><b>[ طُ هَُ م ُ ]</font></b> (اِخ ) دهیست به مصر. (مراصد الاطلاع ) (منتهی الارب ) (معجم البلدان ).<br /></font></div>'),
(177952, 'طهرمسی', '<span class=\"hlight\">طهرمسی .</span> <font color=\"DarkGreen\"><b>[ طُ هَُ م ُ ]</font></b> (ص نسبی ) منسوب به طهرمس از قراء مصر. (انساب سمعانی ).<br /></font></div>'),
(177953, 'طهرون', '<span class=\"hlight\">طهرون .</span><font color=\"DarkGreen\"><b>[ طَ هَِ ]</font></b> (ع ص، اِ) ج ِ طَهِر. رجوع به طهر شود.<br /></font></div>'),
(177954, 'طهس', '<span class=\"hlight\">طهس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) درآمدن در زمین به استواری یا سستی . یقال : طهس فی الارض . ماادری این طهس ؛ نمی دانم به کجا رفت . و کذا ماادری این طهس به، مجهولاً. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177955, 'طهش', '<span class=\"hlight\">طهش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) تباه کردن کار. تباه کردن مرد کار شروع کرده ٔ خود را از دست خود یا به دست غیر. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177956, 'طهطا', '<span class=\"hlight\">طهطا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) شهری است در مصر (جرجا) نزدیک آن در کنار نیل لنگرگاهی برای کشتیهاست . (از اعلام المنجد).<br /></font></div>'),
(177957, 'طهطاه', '<span class=\"hlight\">طهطاه .</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) اسب خوش منظر بشگفت آورنده از خوبی و جمال . <BR><font color=\"Blue\">◄</font> جوان فربه پرگوشت . (منتهی الارب ).<br /></font></div>'),
(177958, 'طهطاوی', '<span class=\"hlight\">طهطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (اِخ ) رجوع به رفاعةبن بدوی در الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٢</span> و معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٧</span> شود.<br /></font></div>'),
(177959, 'طهطاوی', '<span class=\"hlight\">طهطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (اِخ ) احمدبن عبدالرحیم الطهطاوی . او راست منظومه ٔ کتاب «المقصود» که درعلم صرف است، و منظومه ٔ مزبور بدین بیت آغاز شده :<br />یقول بعد حمدی ذی الجلال <br />مصلیاً علی النبی و الاَّل .<br />محمد علیش این منظومه را شرح کرده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">١</span> ستون <span class=\"hlight\" dir=\"rtl\">٣٧٣</span>).<br /></font></div>'),
(177960, 'طهطاوی', '<span class=\"hlight\">طهطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (اِخ ) شیخ احمدبن محمد اسماعیل الطهطاوی الحنفی . او راست کتب ذیل :<br /><span class=\"hlight\" dir=\"rtl\">١</span> - حاشیة الطهطاوی بر کتاب الدر المختار، شرح تنویر الابصار، که در فقه حنفی و در چهار مجلد دربولاق مصر بطبع رسیده است . <span class=\"hlight\" dir=\"rtl\">٢</span> - حاشیة الطهطاوی بر مراقی الفلاح، شرح نور الایضاح که متن و شرح هر دو از حسن شرنبلالی و در فقه حنفی تألیف و در بولاق مصر بسال <span class=\"hlight\" dir=\"rtl\">١٢٩٠</span> هَ . ق . چاپ شده است . (ج <span class=\"hlight\" dir=\"rtl\">٢</span> معجم المطبوعات ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٦</span>).<br /></font></div>'),
(177961, 'طهطاوی', '<span class=\"hlight\">طهطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (اِخ ) احمد افندی عبید. او راست : الروض الازهر فی تاریخ بطرس الاکبر و امپراطور مسکو (منظور پطر کبیر امپراطور سابق روسیه است ). این کتاب را که به یکی از زبانهای اروپائی تألیف شده تعریب کرده و بسال <span class=\"hlight\" dir=\"rtl\">١٢٦٦</span> هَ . ق . در بولاق مصربطبع رسانده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٧</span>).<br /></font></div>'),
(177962, 'طهطاوی', '<span class=\"hlight\">طهطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (اِخ ) احمد رافعبن محمدبن عبدالعزیز رافع الحسینی القاسمی الحنفی الطهطاوی . وی بسال <span class=\"hlight\" dir=\"rtl\">١٢٧٥</span> هَ . ق . بشهر طهطا از بخش جرجا (مصر) تولد و در همان شهر نشو و نما یافت . سپس در جامع ازهر از سال <span class=\"hlight\" dir=\"rtl\">١٢٨٧</span> تا مدت دوازده سال نزد دانشمندان بزرگ و اساتید مانند محمد علیش و محمد حضری و شمس الدین انبابی و دیگران بکسب دانش اشتغال ورزیدو تا سال <span class=\"hlight\" dir=\"rtl\">١٣٤٤</span> هَ . ق . در قید حیات بود. وی راست :<br /><span class=\"hlight\" dir=\"rtl\">١</span> - بلوغ السئول بتفسیر لقد جأکم رسول . یا حمد الاوبة بخاتمة التوبة، و این کتاب مختصری است در تفسیر آیه ٔ مزبور و بدین جمله آغاز شده است : الحمدﷲالذی ارسل رسوله من نفس بیوت العرب، الخ . و بسال <span class=\"hlight\" dir=\"rtl\">١٣٠٥</span> هَ . ق . از تألیف کتاب مزبور فراغت یافت و بهمان سال هم تألیف وی در مصر بطبع رسید.<br /><span class=\"hlight\" dir=\"rtl\">٢</span> - الثغر الباسم فی مناقب سیدی ابی القاسم . موضوع این کتاب ذکر مناقب نیای مؤلف جلال الدین ابوالقاسم الطهطاوی است . این کتاب در مطبعة الرغائب بچاپ رسیده است .<br /><span class=\"hlight\" dir=\"rtl\">٣</span> - رفع الغواشی عن معضلات المطول الحواشی، جلد اول این کتاب در مصر بسال <span class=\"hlight\" dir=\"rtl\">١٣٣٣</span> هَ . ق . چاپ شده است .<br /><span class=\"hlight\" dir=\"rtl\">٤</span> - القول الایجابی، فی ترجمة العلامة شمس الدین محمد الانبابی که در مطبعه ٔ شرف بسال <span class=\"hlight\" dir=\"rtl\">١٣١٤</span> هَ . ق . بطبع رسیده است .<br /><span class=\"hlight\" dir=\"rtl\">٥</span> - کمال العنایة بتوجیه ما فی لیس کمثله شی ٌٔ من الکنایة. این کتاب در فن بلاغت و حاوی مسائل بسیاری از فن بیان و مباحث فلسفه و علم کلام (راجع بتوحید) میباشد، ودر مطبعه ٔ محمد مصطفی بسال <span class=\"hlight\" dir=\"rtl\">١٣١٣</span> هَ . ق . بطبع رسیده است . (معجم المطبوعات ). و رجوع به اعلام المنجد شود.<br /></font></div>'),
(177963, 'طهطاوی', '<span class=\"hlight\">طهطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (اِخ ) شیخ سعید عبداﷲ. وی یکی از دانشمندان جامع ازهر و مدرس ورزش و جغرافیای آنجاست . او راست : الخلاصة السنیة فی الجغرافیة الازهریة (این کتاب جزء برنامه ٔ سال سوم جامع ازهر میباشد) که در مطبعه ٔ شرکت رغائب بسال <span class=\"hlight\" dir=\"rtl\">١٣٢٩</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٩١١</span> م . بطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٧</span>).<br /></font></div>'),
(177964, 'طهطاوی', '<span class=\"hlight\">طهطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (اِخ ) عبدالرحیم عنبر. او راست : هدیة الباری الی ترتیب احادیث البخاری، این کتاب عبارتست از ترتیب «التجرید الصریح لاحادیث الجامع الصحیح » که به «مختصر الزبیدی لصحیح البخاری » نیز معروف میباشد. کتاب هدایة الباری با اِعراب و شَکل کامل در دو مجلد بسال <span class=\"hlight\" dir=\"rtl\">١٣٣٠</span> هَ . ق . درمصر چاپ شده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٧</span>).<br /></font></div>'),
(177965, 'طهطاوی', '<span class=\"hlight\">طهطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (اِخ ) شیخ محمدبن رفاعةبن عنبر الطهطاوی . او راست : جامع البحار و روضة العقول و الانظار. این کتاب در علم عروض و علم قوافی است و دو رساله ٔ دیگر هم بدان افزوده که یکی موسوم به «مفتاح المنطق » و در علم منطق است و دیگری نامش «نهایة الایجاز فی التشبیه و الکنایة و الایجاز» و در علم بیان میباشد و این دو رساله ٔ اخیر نیز از تألیفات محمدبن رفاعه است . و این مجموعه در مطبعه ٔ علمیه بسال <span class=\"hlight\" dir=\"rtl\">١٣١٨</span> هَ . ق . بطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٧</span>).<br /></font></div>'),
(177966, 'طهطاوی', '<span class=\"hlight\">طهطاوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (اِخ ) رجوع به محمد اسماعیل الانصاری الطهطاوی شود. (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٧</span>).<br /></font></div>'),
(177967, 'طهف', '<span class=\"hlight\">طهف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) گیاهیست نرم و سست که در یمن کارند و دانه ٔ آن را که در رنگ و کوچکی به خردل سرخ ماند به وقت تنگدستی و سختی بخورند. گرم و یابس است . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> در عربی بمعنی ذرت باشد، و آن نوعی از غله است (فارسی آن ارزن ). (آنندراج ) (برهان ). فراء گوید: طهف، نانی باشد که از ذرة است و گویند طعامیست که از ذرة سازند. (اختیارات بدیعی ). بعضی گویند طعامیست که از ذرة پزند. (برهان ). ذُرة است و گویند طعامیست که از ذرة ترتیب دهند. (تحفه ٔ حکیم مؤمن ). بعربی اسم نان دخن است، و گفته اند ذُرة است، و گفته اند طعام متخذ از آنست . (فهرست مخزن الادویه ). نان ارزنین . (مهذب الاسماء). نان ارزن .<br /></font></div>'),
(177968, 'طهفة', '<span class=\"hlight\">طهفة.</span> <font color=\"DarkGreen\"><b>[ طِ ف َ ]</font></b> (ع اِ) پاره ای از هر چیزی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177969, 'طهفة', '<span class=\"hlight\">طهفة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (اِخ ) ابن قیس الغفاری . رجوع به طقفةبن قیس الغفاری شود.<br /></font></div>'),
(177970, 'طهفة', '<span class=\"hlight\">طهفة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (اِخ ) ابن ابی زهیر النهدی . صحابی است . (منتهی الارب ). این اسم در کتاب الاصابه بدین صورت آمده : طهیةبن زهیر النهدی، و در عقد الفرید بدین صورت : طهیةبن ابی زهیر النهدی . رجوع به طهیةبن ابی زهیر النهدی شود.<br /></font></div>'),
(177971, 'طهفة', '<span class=\"hlight\">طهفة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (ع اِ) صلیان بلند و دراز. <BR><font color=\"Blue\">◄</font> سراآن، و آن گیاهی است که در تابستان روید و بفارسی آن را زبوده نامند. <BR><font color=\"Blue\">◄</font> (ص )زبدةٌ طهفةٌ؛ مسکه ٔ تنک . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177972, 'طهفلة', '<span class=\"hlight\">طهفلة.</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ل َ ]</font></b> (ع مص ) خوردن نان ارزن را و مداومت کردن بر آن . (منتهی الارب ).<br /></font></div>'),
(177973, 'طهق', '<span class=\"hlight\">طهق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) شتافتن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177974, 'طهل', '<span class=\"hlight\">طهل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) برگشتن رنگ و مزه ٔ آب . یقال : طهل الماءُ طهلاً؛ برگردیده رنگ و مزه شد آب . (منتهی الارب ) (آنندراج ). بدبو شدن آب . (منتخب اللغات ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(177975, 'طهل', '<span class=\"hlight\">طهل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) آب برگردیده رنگ و مزه . (منتهی الارب ) (آنندراج ). آب بدبو. (منتخب اللغات ).<br /></font></div>'),
(177976, 'طهلا', '<span class=\"hlight\">طهلا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) اسم یونانی ماهودانه است . (فهرست مخزن الادویه ).<br /></font></div>'),
(177977, 'طهلبة', '<span class=\"hlight\">طهلبة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ب َ ]</font></b> (ع مص ) رفتن در بلاد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177978, 'طهلة', '<span class=\"hlight\">طهلة.</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (ع اِ) گیاه اندک . <BR><font color=\"Blue\">◄</font> تره ای است نازک . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(177979, 'طهلس', '<span class=\"hlight\">طهلس .</span> <font color=\"DarkGreen\"><b>[ طِ ل ِ ]</font></b> (ع ص ) لشکر گران . طلهس، مثله . (منتهی الارب ) (آنندراج ). لشکر بزرگ . (مهذب الاسماء).<br /></font></div>'),
(177980, 'طهلیدج', '<span class=\"hlight\">طهلیدج .</span> <font color=\"DarkGreen\"><b>[ طِ دَ ]</font></b> (معرب، اِ) نام گیاهی است، و کلمه ٔ مزبور مأخوذ از فارسی است و بمعنی یک نوع کاسنی یا هندبا است . (از دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>).<br /></font></div>'),
(177981, 'طهلیزج', '<span class=\"hlight\">طهلیزج .</span> <font color=\"DarkGreen\"><b>[ طِ زَ ]</font></b> (معرب، اِ) گیاه تلخی است که یهودیان هنگام عید فصح میخورند. (از دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>).<br /></font></div>'),
(177982, 'طهم', '<span class=\"hlight\">طهم .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُ ]</font></b> (ع اِ) ماادری ای الطهم هو؛ یعنی نمیدانم که کیست آن . (منتهی الارب ).<br /></font></div>'),
(177983, 'طهماس آباد', '<span class=\"hlight\">طهماس آباد.</span> <font color=\"DarkGreen\"><b>[طَ ]</font></b> (اِخ ) دهی جزء دهستان سلطانیه ٔ بخش مرکزی شهرستان زنجان در <span class=\"hlight\" dir=\"rtl\">٦٠</span> هزارگزی زنجان و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی راه نیمه شوسه ٔ سلطانیه به قیدار. کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٢٠٢</span> تن سکنه . آب آن از چشمه و محصول آنجا غلات و بنشن . شغل اهالی زراعت و قالیچه و گلیم و جاجیم بافی . راه آن مالرو است . عده ای از سکنه زمستان جهت تأمین معاش به رشت و تهران میروند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(177984, 'طهماسب', '<span class=\"hlight\">طهماسب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) تهماسپ . نام یکی از پادشاهان ایران بوده است . گویند هفت سال خراج تمام ایران رابخشید و پنجاه سال پادشاهی کرد. (برهان قاطع). طهماسب پدر «زو» است و «زو» پس از نوذر پنج سال پادشاهی کرده است . رجوع به شاهنامه ٔ فردوسی شود <span class=\"hlight\">:</span> <br />ز تخم فریدون بجستند چند<br />یکی شاه زیبای تخت بلند<br />ندیدند جز پور طهماسب زو<br />که زور کیان داشت و فرهنگ گو.<br /> <font color=\"Red\">فردوسی .</font><br />بلعمی در ترجمه ٔ تاریخ طبری آورده است که منوچهر را پسری بود نام وی طهماسب و منوچهر بر وی خشم گرفت ازبهر گناهی را و خواست که مردی را بکشد، پس مهتران گردآمدند و او را از پدرش بخواستند، پدر وی را بدیشان بخشید و باز بفرمود تا آن طهماسب را از شهر بیرون کردند و به ترکستان افکندند و آن دختر را که به زنی بدو داده بود تا به کوشک اندر بازداشتندش و نام آن دخترک مادرک بود، پس طهماسب حیله کرد و او را که زن او بود بدزدید و با خویشتن ببرد، پس این طهماسب را از آن دختر پسری آمد نام او «زو» کرد. پس چون منوچهر آمدن «زو» بشنید از طهماسب خشنود شد و مر او را بازخواند، پس طهماسب بمرد و منوچهر هم بمرد و آن پسر بماند و سخت خرد بود و ملک را نشایست، پس افراسیاب ملک ترک بیامد و پادشاهی منوچهر بگرفت و بر مردمان عجم ستم کرد و شهرها ویران کرد. و چون پنج سال برآمد قحطشان افتاد و عجم اندر آن قحط و ستم ترکان دوازده سال بماندند، پس این «زو» بزرگ شد و خروش آمد و سپاه بر خویشتن عرضه کرد سپاه پدر و آن ِ جدش منوچهر بدو گرد آمدند و با افراسیاب حرب کرد و افراسیاب را از زمین عجم بیرون کرد تا بهزیمت ترکستان بازشد و آن روز روز آبان بود و عجم این روز را روز عید دارند. (ترجمه ٔ طبری بلعمی خطی ورق <span class=\"hlight\" dir=\"rtl\">١٠٨</span>). صاحب مجمل التواریخ و القصص آرد: و فرزندش <font color=\"DarkGreen\"><b>[ منوچهر ]</font></b> طهماسب بود که پدر بوده است «زاب » را و پارسیان او را «زو» خوانند و «زه » نیز گفته اند و بعضی گویند پسر نوذر بود و حقیقت آن است که پسر طهماسب ابن منوچهر بود. (مجمل التواریخ و القصص صص <span class=\"hlight\" dir=\"rtl\">٢٧</span>-<span class=\"hlight\" dir=\"rtl\">٢٨</span>). ابن البلخی نام پدر طهماسب را «کنجهوبرز» ثبت کرده است . (فارسنامه چ تهران ص <span class=\"hlight\" dir=\"rtl\">١٣</span>). و رجوع به فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٤</span> و تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٧</span> شود.<br /></font></div>'),
(177985, 'طهماسب', '<span class=\"hlight\">طهماسب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (شاه طهماسب اول ) ابن شاه اسماعیل صفوی . وی از سلسله ٔ صفویه دومین پادشاه است که از سال <span class=\"hlight\" dir=\"rtl\">٩٣٠</span> الی <span class=\"hlight\" dir=\"rtl\">٩٨٤</span>هَ . ق . سلطنت کرده است . تولد وی بنابر روایت اسکندربیک منشی در تاریخ عالم آرای عباسی بسال <span class=\"hlight\" dir=\"rtl\">٩١٩</span> در قریه ٔ شاه آباد از اعمال اصفهان بوده و در سن یازده سالگی بعد از فوت پدرش شاه اسماعیل اول بسال <span class=\"hlight\" dir=\"rtl\">٩٣٠</span> بر تخت پادشاهی بنشست و در روز پانزدهم صفر سال <span class=\"hlight\" dir=\"rtl\">٩٨٤</span> دار دنیا را وداع گفت . مدت سلطنتش <span class=\"hlight\" dir=\"rtl\">٥٣</span> سال و کسری بود و عمر وی به شصت وچهار سال رسید. ادوارد برون در ج <span class=\"hlight\" dir=\"rtl\">٤</span> تاریخ ادبیات ایران گوید: طهماسب ارشد اولاد شاه اسماعیل روزی که جانشین پدر شد بیش از ده سال نداشت، مدت پنجاه ودوسال و شش ماه بر ایران حکمرانی کرد و در <span class=\"hlight\" dir=\"rtl\">١٤</span> می <span class=\"hlight\" dir=\"rtl\">١٥٧٦</span>م . جهان را بدرود گفت . مورخین آن زمان او را شاه دین پناه میخوانند. تاریخ جلوسش در این قطعه ثبت است :<br />طهماسب شاه عالم کز نصرت الهی <br />جا بعد شاه غازی بر تخت زر گرفتی <br />جای پدر گرفتی کردی جهان مسخر<br />تاریخ سلطنت شد جای پدر گرفتی .<br />اخلاق طهماسب : سر جان ملکم نظر خوبی نسبت به اخلاق او اظهار داشته گوید: «مهربان و جوانمرد بود»، و در جای دیگر مینویسد «بنظر میرسد که صاحب حزم و هوش بوده، و اگرچه خصال حسنه و همت عالی خیلی امتیازنداشته در عوض از رذائل و ذمایم بزرگ مبری و منزه بوده است ». آنتونی جنکینسن که حامل سفارشنامه از طرف ملکه الیزابت بود در ماه نوامبر <span class=\"hlight\" dir=\"rtl\">١٥٦٢</span> م . در قزوین بخدمت رسید، ولی خیلی خوب پذیرائی نشد. سفیر ونیز موسوم به وینسِنتیو دِ الساندری که در <span class=\"hlight\" dir=\"rtl\">١٥٧١</span> م . مقیم دربار بود شاه را «در سال شصت وچهارم عمر، و پنجاه ویکم سلطنت » چنین وصف میکند: «قدش میانه و خوش ترکیب است، چهره اش پسندیده و قدری مایل به تیرگی است، لبانی ضخیم و ریشی خاکستری رنگ دارد». و نیز گوید: «بیش از هر چیز از اخلاق او حزن و مالیخولیا قابل ملاحظه است، علامات این حالت بسیار است، مثلاً یازده سال از قصر سلطنتی بیرون نیامد و برخلاف انتظار مردم به شکار و سایر اعمال خود را سرگرم نکرد». در جای دیگر مینویسد: «متکبر و متنفر از جنگ و بسیار کم دل است، توجه او بیشتر نگاهداشت خاطر زنان و نگاهداری زر و سیم است، تا وضع و اجرای قوانین و بسط و نشر عدالت . لئیم و خسیس است و در بیع و شری مانند تاجری حقیر زیرکی دارد». و در خاتمه گوید: «با وجود مطالبی که فوقاً نوشته شد، و در حقیقت هم میبایستی اسباب تنفر میشد. احترام ملت نسبت بپادشاه بحدی است که باور نمیتوان کرد، بمناسبت نسب او که به علی (ع ) معبود خاص ایرانیان منتهی میشودمردم او را نه مثل شاه بلکه مانند خدا پرستش میکنند». و مثلی چند از اقسام این تعظیم و تبجیل، یا عبادت و پرستش را که به عوام الناس انحصار نداشته و در میان اعضای خانواده ٔ سلطنتی و درباریان و سکنه ٔ دورترین نقطه ٔ مملکت نیز متداول و مرسوم بوده است ذکر مینماید. یکی از کارهای زمان سلطنت این پادشاه تخفیف مالیات سنگینی است که بر رعایا تحمیل گشته و سفیر ونیز سبب آن را اعتقاد به خواب میداند و میگوید: «اعتقاد شاه طهماسب به خواب، شبی ملائکه حلقوم او را فشرده و به وی خطاب کردند: آیا از پادشاهی که عاقل لقب دارد واز دودمان علی (ع ) است سزاوار است که خانه ٔ ملت را خراب کند تا خزانه ٔ خود را آباد سازد؟ بعد شاه امر دادند که مردم را از این مالیات ها معاف نماید». این قضیه برای معرفی شاه طهماسب کافی است، زیرا که خودش نیز در تذکره ٔ احوال خویش چندین رؤیا را ذکر میکند وبطوری که معلومست به آنها اهمیت بسیار میداده است، مثلاً در یک خواب (در حدود سال <span class=\"hlight\" dir=\"rtl\">١٥٢٨</span> م .) علی (ع ) او را به غلبه ٔ بر ازبکیه امیدوار میسازد، و یک سال و دوسال بعد در هرات به او امر میدهد که بار دیگر به جنگ برود و در این باب خود گوید: «اعتقاد این بنده ٔ ضعیف، طهماسب الصفوی الموسوی الحسینی این است که هر کس که حضرت امیرالمؤمنین صلوات اﷲ علیه را در خواب بیند، آنچه ایشان فرمایند همان میشود». دفعه ٔ دیگر در بیست سالگی دو خواب پی درپی در رؤیای دوم امام علی الرضا (ع ) تصدیق و تأیید رؤیای اول را طلب کرد و بمقصود رسید و از شراب و دیگر مناهی تائب شد و شرابخانه ها و بوزخانه ها و بیت اللطف خانه ها را در تمام قلمرو خود بست، و این رباعی را بمناسبت آن واقعه انشا کرد:<br />یک چند پی زمرد سوده شدیم <br />یک چند بیاقوت تر آلوده شدیم <br />آلودگیی بود بهر رنگ که بود<br />شستیم به آب توبه آسوده شدیم .<br />توبه ٔ شاه طهماسب : این توبه و استغفار شاه طهماسب در احسن التواریخ در ضمن وقایع سال <span class=\"hlight\" dir=\"rtl\">٩٣٩</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٣٢</span> - <span class=\"hlight\" dir=\"rtl\">١٥٣٣</span> م . مذکور است .<br />تباهی لشکر عثمانی از برف بی هنگام : در همین ایام لشکر سلطان سلیمان عثمانی که حسب المعمول سرگرمی ایران را به جنگ ازبکیه و دفع حملات مکرره ٔ آنها از ولایات شمال شرقی مغتنم شمرده بود به آذربایجان وارد و در این ایالت گرفتار برفی سخت و بیموقع شد و جمعی کثیر از سپاه عثمانی تلف گردید (این واقعه در ماه اکتبر اتفاق افتاد). شاه طهماسب این تباهی لشکر خصم قدیم خود را از «مرحمت الهی و شفقت حضرات معصومین صلوات اﷲ علیهم میداند». این واقعه در رباعی متکلفانه ٔ ذیل ثبت شده و در احسن لتواریخ و عالم آرای عباسی مسطور است :<br />رفتم سوی سلطانیه آن طرف چمن <br />دیدم دوهزار مرده بی گور و کفن <br />گفتم که بکشت این همه عثمانی را<br />باد سحر از میانه برخاست که من .<br />مشاهدات دیگر: چند رؤیای دیگر را هم شاه طهماسب به دقت تمام در تذکره ٔ خود ثبت نموده است . در اردبیل شیخ صفی الدین جدش بر وی ظاهر شده و با وی صحبت داشته است . در موقع دیگر روح شیخ شهاب الدین او را نوید داده تقویت میکند. چندین خواب دیگر به طریق ابهام در ذیل وقایع سنه ٔ <span class=\"hlight\" dir=\"rtl\">٩٥٧</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٥٠</span> م . و سنه ٔ <span class=\"hlight\" dir=\"rtl\">٩٦١</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٥٤</span> م . ذکر شده است .<br />روابط ناگوار زندگی : شاه طهماسب از حیث روابط خانوادگی چندان خوشبخت نبود، هرچند پادشاهان آسیائی آن عصر خاصه سلاطین عثمانی را از او خوش اقبال تر نمیتوان دانست، طهماسب سه برادر کوچک تر از خود داشت : سام (که در شعر مهارتی داشته، و تذکرةالشعرائی نوشته است )، بهرام و القاس . از این سه برادر اولی و سومی بر وی شوریدند.<br />سام میرزا در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٩٦٩</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٦١</span> - <span class=\"hlight\" dir=\"rtl\">١٥٦٢</span> م . بزندان افکنده شد، و در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٩٨٤</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٧٦</span> - <span class=\"hlight\" dir=\"rtl\">١٥٧٧</span> م . به دست جانشین شاه طهماسب بقتل رسید. قضیه ٔ القاس میرزا خیلی بدتر ازین شد، زیرا که مشارالیه هم یاغی بود و هم خائن، و نه تنها بسلطان سلیمان پناه برد و به قسطنطنیه رفت، بلکه او را واداشت که به ایران حمله کند و خود با جد و سعی تمام در جنگ با مملکت خویش شرکت کرد. در همدان خانه ٔ زن برادر خود، بهرام میرزا را در سال <span class=\"hlight\" dir=\"rtl\">٩٥٥</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٤٨</span> م . غارت کرد، بعد بطرف یزدخواست رهسپار شده سکنه ٔ آنجا را قتل عام نمود، اما در سال بعد برادرش بهرام او را شکست داد و بشاه طهماسب تسلیم کرد. شاه او را در قلعه ٔ الموت محبوس ساخت .<br />این روایت بنابر روایت تذکره ٔ شاه طهماسب است اما صاحب احسن التواریخ محبس او را قلعه ٔ قهقهه دانسته است، و گوید: پس از یک هفته در آنجا هلاک شد. شاه طهماسب در ذکر این واقعه گوید: «بعد از چند روز دیدم که از من ایمن نیست و دائم بتفکر است . او را همراه ابراهیم خان و حسن بیک یوزباشی کرده بقلعه فرستادم، ایشان او را بقلعه ٔ الموت برده حبس کرده آمدند، بعد ازشش روز جمعی که در قلعه او را نگاه میداشتند، غافل گردیده دو سه نفر در آنجا بودند که القاس پدر ایشان را کشته بود، ایشان هم بقصاص پدر خود او را از قلعه بزیر انداختند، بعد از مردن او عالم امن شد». اگر فرض کنیم که شاه طهماسب خودش مقدمه ٔ وقوع این امر را فراهم نکرده، بزحمت میتوان تصور کرد که بی رضای او انجام گرفته باشد. در همین سال بهرامشاه در سن <span class=\"hlight\" dir=\"rtl\">٣٣</span> سالگی وفات یافت .<br />بیوفائی نسبت به بایزید پسر شاه عثمانی : از این بدتر قضیه ٔ شاهزاده بایزید بدبخت پسر سلطان سلیمان عثمانی است . این جوان از حکومت ولایت کوتاهیه معزول شد و بواسطه ٔ سعایت زن پدرش که زنی روسی موسوم به خرم بود (و مقصودش فقط ولیعهد ساختن پسر خود سلیم بود که بعدها به احمق ملقب گشت ) از وطن رانده شد و در سال <span class=\"hlight\" dir=\"rtl\">٩٦٧</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٥٩</span> - <span class=\"hlight\" dir=\"rtl\">١٥٦٠</span> م . بدرگاه شاه طهماسب پناه برد. هیئتی از جانب سلطان عثمانی به قزوین رفت و تقاضای تسلیم بایزید و اطفال او را کرد. بنابر قول آنتونی جنکینسن این هیئت چهار روز قبل از ورود او یعنی چهارم اکتبر <span class=\"hlight\" dir=\"rtl\">١٥٦٢</span> م . وارد شد، طهماسب قدری از ترس دولت عثمانی و قدری بواسطه ٔ رشوه عهدی را که بسته بود شکسته و امر داد یا راضی شد که شاهزاده ٔ بدبخت ترک با چهار پسر کوچکش کشته شوند. و بنابر قول آنتونی جنکینسن «سر او را مانندارمغان بسیار مطلوبی بپدر قسی القلب بدطینتش ارسال داشت ».<br />شاه طهماسب دغدغه ٔ خاطر و احساس ندامتی را که از قصد خیانت بمهمان و تسلیم او به دشمن در قلبش ظهور یافته بود خفه کرد و عهد و پیمان را شکسته و شاهزاده را حتی مستقیماً به پدرش نسپرد بلکه به فرستادگان برادرش سلیم تسلیم کرد. از روی تذکره ٔ خود شاه طهماسب هم معلوم میشودکه این رفتار چقدر بد بوده است .<br />شرح کامل این واقعه در پایان تذکره ٔ مزبور بقرار ذیل دیده میشود، شرحی که خود شاه طهماسب ازین بدرفتاری نوشته است : «در این تاریخ علی آقا نزد حضرت خواندگار آمد و امرا و جماعت هر کس ارمغانی که فرستاده بودند در برابر تحفه ٔ هر کس (تحفه ٔ آمد) غیر از پیشکش و ارمغان ما که در این مرتبه نیز درجه ٔ قبول نیافته بود و کتابتی سراسر کنایه و گله آمیز نوشته بودند من گفتم این است که سلطان بایزید را با چهار پسر گرفته و جهت خاطر حضرت خواندگار و سلیمخان نگاه داشتم و چون گفته بودم که سلطان بایزید را به خواندگار ندهم موقوف همین که چون اشارت خواندگار برسد و فرستادگان حضرت سلیم برسند ایشان را تسلیم فرستادگان سلطان سلیم کنم که نقض عهد نکرده باشم . بعد که فرستادگان خواندگار آمدند فرمودم پاشا حضرتلری و حسن آقا شما خوش آمدید و صفا آوردید، آنچه فرموده ٔ حضرت خواندگار است چنان میکنم و از اشارت ایشان تجاوز نمیکنم و بهر خدمت که میفرمایند ایستادگی دارم اما در برابر این نوع خدمت کلی از حضرت خواندگار و سلیم خان جائزه و جلدوئی که لایق ایشان باشد میخواهم و در عالم دوستی از خواندگار توقع دارم که اذیت بسلطان بایزید و فرزندان او نرسد». حاجت بذکر نیست که این نیت نیکو ابداً مجاری این واقعه ٔ خونین را تغییری نداد لکن موافقت و تسلیم پادشاه شیعه با تقاضای آمرانه ٔ سلطان سبب شد که بطورموقت روابط عثمانی استحکام یافته دوستانه شود. انعکاس این صلح و سلام هم در نوشته های جنکینسن و هم در مراسلات سیاسیه که جلد اول منشآت فریدون بیک را خاتمه میدهد بنظر میرسد. درین مکاتیب سلطان برای اولین بار با ادب و احترام بشاه طهماسب چیز نوشته است، ولی اشاره ٔ صریحه به واقعه ٔ مزبور دیده نمیشود.<br />همایون امپراطور هند در ایران : واقعه ای که بیشتر معلوم و قابل اعتماد است ورود همایون پسر بابر امپراطور دهلی است که از مملکت خود رانده شد و در سال <span class=\"hlight\" dir=\"rtl\">١٥٤٤</span> م . بدربار شاه طهماسب پناه آورد. سر جان ملکم شرح پذیرائی او را با وجد و شعف تمام نقل میکند اما ارسکین مدارک و اسناد رسمی را بقدر «افسانه ٔ ساده و بی زینت » جوهر ملازم همایون اهمیت نداده و با ذکر امثال چند اینطور اظهار عقیده میکند که «همایون در این سفر خیلی اهانت دید و مشقت کشید». حقیقةً خیلی فشار بر او وارد شد که بقبول مذهب شیعه مجبور گشت و اگر بواسطه ٔ شفاعت سلطان خانم خواهر پادشاه و قاضی جهان وزیر و نورالدین طبیب نبود خیلی بیشترزحمت میدید. و امروز یکی از تصاویر قصر معروف به چهل ستون اصفهان مجلس ملاقات طهماسب و همایون را نشان میدهد.<br />روابط خارجی ایران درعهد شاه طهماسب : شاه طهماسب مثل پدرش با سه دولت خارجی رابطه داشت : عثمانی و ازبکیه ٔ ماوراءالنهر و خاندان سلاطین دهلی معروف بمغول کبیر. در قسمت بزرگی از سلطنت او (یعنی تا سال <span class=\"hlight\" dir=\"rtl\">٩٧٤</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٦٦</span> - <span class=\"hlight\" dir=\"rtl\">١٥٦٧</span> م .) سلطان سلیمان بزرگ بر تخت عثمانی قرار داشت . از این تاریخ سلیم خان تا دو سال قبل از وفات طهماسب بر عثمانی حکمرانی نمود. و در دو سال اخیر زندگانی او (<span class=\"hlight\" dir=\"rtl\">٩٨٢</span> - <span class=\"hlight\" dir=\"rtl\">٩٨٤</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٧٤</span> - <span class=\"hlight\" dir=\"rtl\">١٥٧٦</span> م .) سلطان مراد سوم فرمانفرمای عثمانی بود. اما حکمرانان ازبکیه عبیدخان تا سنه ٔ <span class=\"hlight\" dir=\"rtl\">٩٤٦</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٣٩</span> - <span class=\"hlight\" dir=\"rtl\">١٥٤٠</span> م .) که سال وفات اوست، از دشمنی شاه طهماسب کوتاهی نکرد و پس از آن تاریخ، دین محمدخان خود را از بزرگترین دشمنان او معرفی کرد، این شخص از مغشوش کردن ولایات شرقی و ترکان عثمانی از غارت حدود غربی ایران هیچ فروگذار نکرد.<br />از سلاطین «مغول کبیر» بابر (متوفی در <span class=\"hlight\" dir=\"rtl\">٩٢٧</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٣٠</span> - <span class=\"hlight\" dir=\"rtl\">١٥٣١</span> م .) و همایون (متوفی در <span class=\"hlight\" dir=\"rtl\">٩٦٢</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٥٥</span> م .) و اکبر معاصر شاه طهماسب بوده اند. چنانکه دیدیم، آنتونی جنکینسن در سال <span class=\"hlight\" dir=\"rtl\">١٥٦١</span> م . با ورقه ٔ اعتبار از طرف الیزابت ملکه ٔ انگلستان بدربار او آمد، و سیزده سال تقریباً بعد از جنکینسن یعنی در اواخر ایام سلطنت شاه طهماسب بنابر قول صاحب احسن التواریخ که در ضمن وقایع سال <span class=\"hlight\" dir=\"rtl\">٩٨٢</span>هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٧٤</span> - <span class=\"hlight\" dir=\"rtl\">١٥٧٥</span> م . قید کرده است هیئتی از جانب دن سباستیان به ایران وارد شد، اما بد پذیرائی گشت .<br />جنگ با عثمانی : در این عهد که ایران مابین دو دشمن واقع بود، یعنی ترکان از جانب غرب، و ازبکیه از سوی شرق، چندان روی صلح و آسایش ندید و جنگهائی در سرحدات شمال شرق و شمال غرب پی درپی پیش می آمد که هرچند از حیث نتیجه با یکدیگر مختلف بودند اما از لحاظ وضع و تربیت بهیچوجه تغییری در آنها ملاحظه نمیشد. مهمترین جنگهای سلطان سلیمان در سنوات ذیل اتفاق افتاد: در <span class=\"hlight\" dir=\"rtl\">٩٤٠</span> - <span class=\"hlight\" dir=\"rtl\">٩٤٢</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٣٤</span> - <span class=\"hlight\" dir=\"rtl\">١٥٣٦</span>) محض گرفتن بغداد از دست ایرانیان و فتح آذربایجان . در <span class=\"hlight\" dir=\"rtl\">٩٥٠</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٤٣</span> - <span class=\"hlight\" dir=\"rtl\">١٥٤٤</span> و <span class=\"hlight\" dir=\"rtl\">٩٥٣</span> - <span class=\"hlight\" dir=\"rtl\">٩٥٥</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٤٦</span> - <span class=\"hlight\" dir=\"rtl\">١٥٤٨</span> هنگام پناه بردن القاس برادر شاه طهماسب بعثمانیان، در <span class=\"hlight\" dir=\"rtl\">١٥٥٢/٩٥٩</span> وقتی که ایرانیان ارجیش را دوباره تصرف کردند، و در <span class=\"hlight\" dir=\"rtl\">١٥٥٤/٩٦١</span> در موقعی که سلیمان نخجوان را آتش زد و در چهارمین کرت به آذربایجان هجوم آورد. قوای نظامی عثمانیان در این وقت در دوره ٔ ترقی قرار داشت و نه تنها برای ایران بلکه برای دول معظمه ٔ اروپا نیز خطرناک بود. و دول اروپا از ایران متشکر بودند که گاه گاه قوای دولت عثمانی را تجزیه کرده و پراکنده ومشغول میسازد. بوسبک سفیر فردیناند در دربار سلیمان اظهار میکرد که : «میان ما و ورطه ٔ هلاک فقط ایرانیان فاصله اند». کریزی شرحی از «کثرت عده ٔ لشکر و کمال و مهیائی توپخانه ٔ عثمانیان در این زمان » وصف میکندو میگوید: «همین ملاحظات و اوصاف راجع میشود بمهارت و چابکی آنها در سنگرسازی و سایر شعب هندسی و نظامی ». با اینکه ایرانیان از حیث نظم قشون و آراستگی سلاح خیلی از عثمانیها پست تر بودند باید بر آنها تحسین کرد که به این خوبی در مقابل قوای ترک مقابل ورزیدند، خاصه پس از ملاحظه ٔ این نکته که سیاست عثمانی در آن زمان چنان بود که همواره ازبکیه و ترکمانان و سایر طوائف سنی را دعوت میکرد که در موقع حرکت قشون ترک بر قزلباش اوباش حمله ور شوند. از مکاتیب سیاسیه که در عهد سلیمان و پدرش سلطان سلیم مانده است بخوبی رَوِش مزبور معلوم و استنباط میگردد، مثلاً نامه ای که در اواخر سال <span class=\"hlight\" dir=\"rtl\">١٥٥٣/٩٦٠</span> به یکی از رؤسای ترکمانان خطاب شده و در صص <span class=\"hlight\" dir=\"rtl\">٦١٢</span> - <span class=\"hlight\" dir=\"rtl\">٦١٣</span> منشآت فریدون بیک مندرج است چهارنفر ایلچی موسوم به محمد میر ابوتراب، میر طوطی، و سندوک حامل این مکتوب بودند و در مراجعت پس از طواف کعبه بدربار سلطان رفته او را از اقداماتی که بر ضد ایران کرده بودند مسرور ساختند.<br />جنگ با ازبکیه : جنگهائی که با ازبکیه میشد همچنین تسلسل داشت، خاصه تا وفات عبیدخان که قائدی خطرناک و هراس انگیز و پسر سیبک خان و یکی از اعقاب چنگیزبود. این شخص در سال <span class=\"hlight\" dir=\"rtl\">٩٤٦</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٣٩</span> - <span class=\"hlight\" dir=\"rtl\">١٥٤٠</span> بسن پنجاه وسه سالگی پس از سی سال حکمرانی وفات یافت . بنابر قول صاحب احسن التواریخ در هفت جنگی که با ایرانیان کرد فقط در یکی از آنها شکست خورد.<br />کشتار در راه مذهب : طوس و مشهد خاصه هرات در این لشکرکشیهابسیار خسارت دیدند زیرا که تقریباً در هر مورد قتل عام مذهبی نیز با آنها همراه بود. هلالی شاعر در سال <span class=\"hlight\" dir=\"rtl\">٩٣٥</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٢٨</span> - <span class=\"hlight\" dir=\"rtl\">١٥٢٩</span> در هرات قتیل تعصب اُزبکان سُنی شد چنانکه بنائی شاعر در فارس در سال <span class=\"hlight\" dir=\"rtl\">٩١٨</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥١٢</span> - <span class=\"hlight\" dir=\"rtl\">١٥١٣</span> فدای سختگیری و تعصب شیعیان گردید. در احسن التواریخ در ضمن وقایع سال <span class=\"hlight\" dir=\"rtl\">٩٤٢</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٣٥</span> - <span class=\"hlight\" dir=\"rtl\">١٥٣٦</span> بشرح و صورت ذیل از قتل عام شیعیان که در <span class=\"hlight\" dir=\"rtl\">٢٠</span> رجب <span class=\"hlight\" dir=\"rtl\">٩٤٢</span> مطابق <span class=\"hlight\" dir=\"rtl\">١٤</span> ژانویه ٔ <span class=\"hlight\" dir=\"rtl\">١٥٣٦</span> هنگام غلبه ٔ عبیدخان بر هرات اتفاق افتادمسطور است : «هر روز بحکم آن خان بی ایمان پنج شش کس بواسطه ٔ تشیع به اقوال جُهال در چهارسوق هرات کُشته میشدند و روستائیان بی دیانت و شهریان باخیانت با هر کس که عداوتی داشتند او را گرفته نزد قاضی میبردند که این مرد در زمان قزلباش لعن ابوبکر و عثمان کرده است بسخن آن دو گواه جاهل قاضی بقتل آن مظلوم حکم میکرد و او را کشان کشان به چهارسوق هرات میبردند و بقتلش می آوردند و از شومی ایشان امواج محن و افواج فتن بدرجه ٔ اعلی رسید و سلب و نهب در اطراف خراسان واقع گردید.<br />حرب با گرجیان : ایرانیان درین عهد لاینقطع با گرجیان نیز جنگ داشتند خاصه در سنوات <span class=\"hlight\" dir=\"rtl\">٩٤٧</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٤٠</span> - <span class=\"hlight\" dir=\"rtl\">١٥٤١</span>، <span class=\"hlight\" dir=\"rtl\">٩٥٠</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٤٣</span> - <span class=\"hlight\" dir=\"rtl\">١٥٤٤</span>، <span class=\"hlight\" dir=\"rtl\">٩٥٨</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٥١</span>، <span class=\"hlight\" dir=\"rtl\">٩٦١</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٥٤</span>، <span class=\"hlight\" dir=\"rtl\">٩٦٣</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٥٦</span>، <span class=\"hlight\" dir=\"rtl\">٩٦٨</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٦٠</span> - <span class=\"hlight\" dir=\"rtl\">١٥٦١</span> و <span class=\"hlight\" dir=\"rtl\">٩٧٦</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٦٨</span> - <span class=\"hlight\" dir=\"rtl\">١٥٦٩</span> این جنگها هم در کمال خشونت و قساوت انجام میگرفت . و این نکته قابل نوشتن است که نویسندگان ایرانی آن عصر گرجیان عیسوی را گبر (که نام پیروان زردشت است ) میخواندند، چنانکه در بیت ذیل که در شرح نخستین جنگ از حربهای سابق الذکر سروده شده مذکور است :<br />در آن سنگلاخ آن ددان کرده جای <br />وطنگاه گبران مردم رُبای .<br />بنابر قول صاحب احسن التواریخ در این سفر گرجیانی که قبول دین اسلام کردندعفو شدند و آنانکه خودداری کردند عرضه ٔ شمشیر گشتند. و همچنین در ذکر جنگ <span class=\"hlight\" dir=\"rtl\">١٥٥١/٩٥٨</span> مورخ مزبور میگوید: «غازیان ظفرشعار پست و بلند دیار کفار فجار را احاطه فرمودند و هر کوه و کمر که گریزگاه آن گمراه بود ازلگدکوب دلاوران با هامون یکسان شد، و یک متنفس از آن مشرکین از دائره ٔ قهر و کین و اﷲ محیط بالکافرین، جان بسلامت بیرون نبرد و اهل و عیال و اموال به ارث شرعی از مقتولان بقاتلان انتقال کرد.<br />جنگهای کوچک و اغتشاشات داخلی : از این جنگهای بزرگ گذشته جدالهای دیگر نیز دولت ایران را مشغول میداشت از قبیل لشکرکشی که برای قلع و قمع حکام مستقل گیلان و آخرین شخص خاندان قدیم شروانشاهیان که مدعی بودند نسبشان به انوشروان میرسد، ولی در این عهد رو بانحطاط و زوال گذارده بود. هرچند آخرین عضو این دودمان موسوم بشاهرخ بن سلطان بن سلطان فرح بن شیخ شاه بن فرخ یسار در سال <span class=\"hlight\" dir=\"rtl\">٩٤٦</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٣٩</span> - <span class=\"hlight\" dir=\"rtl\">١٥٤٠</span> بفرمان شاه طهماسب بقتل رسید. نه سال بعد برهان نام شخصی از بازماندگان این سلسله با اسماعیل میرزا بنای ضدیت گذاشت . در گیلان خان احمدنام که یازدهمین شخص خاندانی بود که دویست وپنجاه سال سمت حکمرانی داشت شکست خورد. و در سال <span class=\"hlight\" dir=\"rtl\">٩٧٥</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٦٧</span> - <span class=\"hlight\" dir=\"rtl\">١٥٦٨</span> در قلعه ٔ قهقهه محبوس گردید. در سال <span class=\"hlight\" dir=\"rtl\">٩٨١</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٧٣</span> - <span class=\"hlight\" dir=\"rtl\">١٥٧٤</span> جماعتی از اوباش بر تبریز دست یافتند و تا صدوپنجاه نفر از آنان بقتل نرسید سر به اطاعت فرودنیاوردند سیاستها و تنبیه های وحشیانه بسیار دیده میشد.<br />سیاستهای وحشیانه : مظفر سلطان حاکم رشت متهم بخیانت شد، شهر تبریز را آئین بستند، مشارالیه را در میان خنده و استهزاء عوام الناس در کوچه و بازار گردش دادند و بالاخره در قفس آهنین او را آتش زدند و امیر سعدالدین عنایت اﷲ خوزانی نیز زیر قفس آهنی آویخته شدو بطرزی خاص و وحشیانه طعمه ٔ حریق گردید. خواجه کلان غوربانی که در تسنن بسیار متعصب بود و از عبیدخان ازبک استقبال کرده و متهم شده بود که شاه را به خفت واهانت نام برده است در میدان هرات پوست کنده و بر داری آویخته شد. رکن الدین مسعود کازرونی که از اجله ٔ علما و اطبا بود مورد سخط سلطان شده و به آتش افکنده گشت . محمدصالح که ممدوح شعرا و حافظ ادبا بود و حیرتی که قصیده ای در مدح او ساخته است بجرم توهین بپادشاه متهم گردید دهان او را دوخته و در خمی جای داده از مناری عظیم فروافکندند.<br />ضعف و عیب شاه طهماسب : بنابر قول صاحب احسن التواریخ شاه طهماسب در ایام جوانی خیلی بخط و نقاشی و سواری خران مصری میل داشت، در نتیجه خرسواری مرسوم شد و هر کس در تزئین مرکوب و تهیه ٔ افسار و پالان زرین بر دیگران سبقت میجست . راجع به این مزاج مخصوص یکی از شعراء پست و گمنام که تخلصی عجیب داشت (بوق العشق ) او را در شعر ذیل هجو کرده است :<br />بی تکلف خوش ترقی کرده اند<br />کاتب و نقاش و قزوینی و خر.<br />شاه خیلی اظهار تقدس میکرد، او بیشتر چیزها را نجس میدانست و غالباً لقمه ٔ نیم خورده را از دهان بیرون کرده در آب یا در آتش میافکند» و بهمین ملاحظه جای خرسندی است که «میل نداشت در میان مردم صرف غذا کند». درگرفتن ناخن و یک روز استراحت پس از حمام اهتمام و دقت کامل مبذول میداشت .<br />طهماسب در سه شنبه <span class=\"hlight\" dir=\"rtl\">١٥</span> صفر<span class=\"hlight\" dir=\"rtl\">٩٨٤</span> (<span class=\"hlight\" dir=\"rtl\">١٤</span> می <span class=\"hlight\" dir=\"rtl\">١٥٧٦</span>) به سن <span class=\"hlight\" dir=\"rtl\">٦٤</span> سالگی بعد از پنجاه وسه سال و شش ماه سلطنت وفات یافت، بنابر قول صاحب احسن التواریخ، مدت پادشاهی او از تمام سلاطین اسلام درازتر بوده است به استثنای المنتصر باﷲ خلیفه ٔ عباسی . (ترجمه ٔ تاریخ ادبیات ایران تألیف برون ج <span class=\"hlight\" dir=\"rtl\">٤</span> صص <span class=\"hlight\" dir=\"rtl\">٦٧</span> - <span class=\"hlight\" dir=\"rtl\">٧٨</span>).<br />نظر به اینکه شاه طهماسب دارای قریحه ٔ شعری بوده، تذکره نویسانی که بعد از وی بترجمه ٔ احوال شعرا پرداخته اند هر یک بنوبه ٔ خویش نامی از وی برده و بیتی چند از او ثبت کرده اند، من جمله صادقی افشار در مجمعالخواص که تذکره ای است بزبان ترکی، و به تتبع مجالس النفائس امیر علیشیر نوائی نوشته و اخیراًعبدالرسول خیام پور معلم دانشگاه تبریز کتاب مزبور را بفارسی ترجمه و در تبریز طبع و نشر کرده، آورده است که : این پادشاه مرحوم مانند نیاکان خود دلیر بود وهمت بلند داشت . پنجاه وسه سال سلطنت کرد و در نیمه ٔ اول آن بهر کشوری که سوی می آورد دشمن در برابر وی تاب مقاومت در خود نمیدید و اگر ایستادگی میکرد شکست میخورد. و در نیمه ٔ دوم معارضان هند و روم با پای خودبدرگاهش میشتافتند و بدانجا پناهنده میشدند و بزرگان ترکستان و فرنگستان برای وی تحف و هدایا میفرستادند. چنان استعداد ذاتی داشت که سخنانش از سر تا پا لطایف و ظرائف بود و اگر میخواست میتوانست در تمام عمربکلام موزون سخن گوید. منظومه ٔ ذیل را در مدح امیر بیک مهر بالبدیهه گفته است :<br />ای بلند اختر سپهرشرف <br />وی گرامی دُرِ خجسته صدف <br />رانده در قلزم وزارت فُلک <br />کارفرمای صد نظام الملک <br />نیست در زیر چرخ چون تو وزیر<br />شرف روزگار بنده امیر.<br />از اینگونه ابیات که بالبدیهه گفته است زیاد دارد. استاد ما استاد مظفرعلی نقاش شاهی که نوه ٔ خواهر استاد بهزاد است فضل و کمال خود را بعد از استاد مزبور به آموزش و پرورش این پادشاه مدیون بود.<br />مرحوم بعلما وصلحا و فضلا خیلی التفات داشت و چنان پرهیزگار بود که در مدتی متجاوز از چهل سال گناه کبیره و یا صغیره ای قولاً یا فعلاً از او سر نزد.<br />بذل و کرمش چنان بود که بازرگانان را از پرداخت عوارض که درآمد آن هرساله بر هشت هزار تومان بالغ میشد معاف داشت و با برداشتن تحصیلداران که در راهها راهزنی میکردند و مانع عبور و مرور میشدند گرد کدورت را از رهگذر دلها بزدود.<br />گرچه همیشه شعر نمیگفت ولی گوهرهائی که گاه گاه از دریای طبعش بیرون میافتاد افکار جهانیان را آویزه ٔ گوش و گردن میگشت، رباعی ذیل از اوست (چون ادوارد برون در ضمن اعتقاد طهماسب به خواب، رباعی مزبور را نقل کرده از تکرار آن صرف نظر شد). (مجمع الخواص صص <span class=\"hlight\" dir=\"rtl\">٨</span> - <span class=\"hlight\" dir=\"rtl\">٩</span>).<br />آذر بیگدلی در آتشکده گوید: صیت عدالتش لرزه بزنجیر نوشیروان افکنده، سیادت نسب با سعادت حسب جمع کرده، مفصل احوال ایشان در کتاب تواریخ مضبوطو بمراتب سخنوری و سخن شناسی مربوط و نظر به استحضارسلطنت چند بیتی در شرح حال اهل چند ولایت گفته قلمی و ثبت گردید:<br />ز تبریزی بجزحیزی نبینی <br />همان بهتر که تبریزی نبینی .<br />اصفهان جنتیست پرنعمت <br />اصفهانی در آن نمیباید.<br />سگ کاشی به از اکابر قم <br />با وجودی که سگ به از کاشی است .<br />این رباعی نیز به اسم ایشان نوشته شده که در حال توبه از بنگ و شراب فرموده ... (آتشکده ٔ آذر ص <span class=\"hlight\" dir=\"rtl\">١٧</span>). مرحوم هدایت در مجمع الفصحا تخلص شاه طهماسب را عادل ثبت کرده و گوید: نام شریفش شاه طهماسب و فرزند ارشد اکبر شاه اسماعیل ماضی صفوی رَحِمَه ُ اﷲ بوده از صغر سن مبارک بسلطنت ایران رسیده در یازده سالگی بجای بدر برنشست، بعد از رفع اختلاف امرا قصد استیصال عبیداﷲخان بن محمود برادرزاده ٔ شاهی بیکخان شیبانی کرد، در زورآباد جام شکستی فاحش به ازبکیه داد و ایشان را از جیحون بازگردانید و با پادشاهان روم و گرجستان مصافها داد و شیروانات بگرفت و سلطان سلیمانخان عثمانی مصالحه کرد. سلاطین هند و ترکستان و روم باوی موالات ورزیدند. یکصدوچهارده هزار سپاه جرار داشت و بیست وچهارهزار اسب و استر بجهت اسفار. در بیست سالگی از جمیع معاصی توبه کرد و از عدل و انصاف او اصناف خلایق آسوده بودند و ایران معمور گردید. مدت عمرش شصت وچهار سال و شش ماه، مدت سلطنتش پنجاه وپنج سال و کسری بوده، رحلتش در شهر صفر <span class=\"hlight\" dir=\"rtl\">٩٨٤</span> هَ . ق . در اغلب کمالات وحید بود و گاهی شعری میفرمود، از آن جمله است : درمجمع الفصحا عین اشعاری را که در آتشکده ثبت است آورده فقط یک بیت در وصف اصفهان افزوده است و آن این است که :<br />اصفهان جنتی است پرنعمت <br />هرچه در وی گمان بری شاید.<br />و بیتی را هم که در آتشکده در وصف اصفهان و اصفهانی آورده به طریق ذیل نقل کرده است :<br />همه چیزش نکوست الا آنک <br />اصفهانی در آن نمی باید.<br /> <font color=\"Red\">(از مجمع الفصحا ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩</span>).</font><br />شاه طهماسب اول روی سکه ها نامهای مبارکه ائمه ٔ اطهار سلام اﷲ علیهم را با القاب هر یک فرمان میداد نقش میکردند بدین صورت : علی المرتضی . حسن الرضا، حسین الشهید، علی زین العابدین . محمد الباقر، جعفر الصادق ... الخ .<br />القاب این سلطان گاهی بر روی سکه ها بدین سیاق نقش بود: السلطان العادل الکامل <font color=\"DarkGreen\"><b>[ الهادی ]</font></b> <font color=\"DarkGreen\"><b>[ الوالی ]</font></b> ابوالمظفر شاه طهماسب بهادرخان <font color=\"DarkGreen\"><b>[ الصفوی ]</font></b> خلد اﷲ <font color=\"DarkGreen\"><b>[ تعالی ]</font></b> ملکه و <font color=\"DarkGreen\"><b>[ سلطانه ]</font></b>. و گاهی به روش ذیل : السلطان العادل الکامل الهادی الوالی ابوالمظفر <font color=\"DarkGreen\"><b>[ شاه ]</font></b> طهماسب بهادرخان <font color=\"DarkGreen\"><b>[ الصفوی ]</font></b> الحسینی خلد اﷲ <font color=\"DarkGreen\"><b>[ تعالی ]</font></b> ملکه و <font color=\"DarkGreen\"><b>[ سلطانه ]</font></b> . وگاهی بدین صورت : السلطان العادل الکامل الهادی الوالی ابوالمظفر سلطان طهماسب ... الخ . و گاهی بدین طریق : السلطان الهادی شاه طهماسب بهادرخان <font color=\"DarkGreen\"><b>[ الصفوی ]</font></b> الحسینی خلد اﷲ ملکه و سلطانه . و گاه احساسات مذهبی این پادشاه بر روی سکه ها بصورت زیرین نمودار بود: غلام امام مهدی علیه السلام السلطان العادل ابومظفر پادشاه طهماسب الصفوی خلد اﷲ ملکه . غلام علی بن ابیطالب علیه السلام . السلطان العادل الهادی <font color=\"DarkGreen\"><b>[ الوالی ]</font></b> ابوالمظفر پادشاه طهماسب الصفوی <font color=\"DarkGreen\"><b>[ یا شاه طهماسب الحسینی الصفوی ]</font></b> خلد اﷲ ملکه .<br />سجع مُهرش گاه سلطان کشوردین طهماسب شاه عادل، و گاه در متن این مصرع : بنده ٔشاه ولایت طهماسب . و در حاشیه ٔ اسامی و القاب ائمه ٔ اطهار سلام اﷲ علیهم بشرحی که در پیش ذکر شد نقش بود.(مسکوکات رابینو صص <span class=\"hlight\" dir=\"rtl\">٣</span> - <span class=\"hlight\" dir=\"rtl\">٢٩</span>).<br /></font></div>'),
(177986, 'طهماسب', '<span class=\"hlight\">طهماسب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (شاه طهماسب دوم ) ابن شاه سلطان حسین صفوی . وی دهمین پادشاه از پادشاهان سلسله ٔ صفویه بوده و از سال <span class=\"hlight\" dir=\"rtl\">١١٣٥</span> تا <span class=\"hlight\" dir=\"rtl\">١١٤٤</span> هَ . ق . پادشاهی کرده است . مدت ده سال ِ سلطنت وی شش سالش در زمان غلبه ٔ افغان و چهار سال دیگرش هم در بحبوحه ٔ اقتدار طهماسب قلیخان افشار (نادرشاه ) گذشت و در واقع رشته ٔ امور سلطنت را طهماسب قلیخان در دست داشت و برای شاه طهماسب دوم جز نام پادشاهی چیزی باقی نمانده بود. محمدحسنخان صنیعالدوله در کتاب تاریخ سلاطین ایران آورده که : چون خبر قتل شاه سلطان حسین (<span class=\"hlight\" dir=\"rtl\">١١٣٤</span> هَ . ق .) در قزوین بشاه طهماسب رسید خود را پادشاه خواند، به آذربایجان رفت و رسولی نزد پادشاه روس فرستاد و امداد خواست و لشکر روس بگیلان و آذربایجان آمدند و سپاه عثمانی نیز که با اشرف مصالحه کرده بودند به آذربایجان روان شدند و شاه طهماسب و کسانش به ری آمدند و لشکری که داشتند در قم برای جلوگیری افغان گذاشتند و بهر طرف نامه ای نوشته کمک خواستند و فتحعلیخان قاجار با رنجشی که از شاه سلطان حسین داشت با لشکر خود به ری آمد و اشرف که این شنید با لشکر زیادی به ری شتافت و چون دانست که لشکر آماده ٔ شاه طهماسب همین است که در قم است جمعی را به جنگ آنها گذاشته و خود با اغلب از لشکریانش رو بشاه طهماسب نهادو چون به ری رسید شاه طهماسب به لارجان رفته بود، فتحعلیخان با سپاه ترکمانان و قاجار بمحاربه ٔ اشرف مشغول شده و چند بار جنگ سختی فرمود ولی چون از شاه طهماسب خبر نداشت که کجاست بمازندران شتافت و در اشرف بشاه طهماسب پیوست و او را از رسیدن اشرف خبر داد، اوجز توسل به آن شهریار چاره ندیده بدو متوسل گردیده از او استمداد کرد، فتحعلیخان شاه طهماسب را بگرگان آورده به جمعآوری لشکر پرداخت . در آن حال ندرقلی افشار که نادرشاه شد و نسب و حالت او را مورخین ضبط کرده اند بسبب دامادی باباعلی بیک افشار قوتی پیدا کرده وخروج نموده با ملک محمود سیستانی که در خراسان بود زدوخوردها نموده کارش بالا گرفته کلات را متصرف شد. همین که آمدن شاه طهماسب را بگرگان شنید از روی حزم پیشکشی نزد او و فتحعلیخان فرستاده اظهار بندگی کرد و ایشان نسبت به او تلطف کرده حکمرانی متصرفات او بدو واگذاشتند تا آنکه فتحعلیخان با لشکر قاجار و ترکمان که در ولایات مازندران داشت و آماده کرده بود با شاه طهماسب به گرفتن مشهد مقدس روانه شدند و در نزدیکی مشهد نادرقلیخان با جمعی نزد شاه طهماسب آمده شاه طهماسب را از وی خوش آمد و او را ملقب به طهماسبقلیخان و امیرکبیر کرد و گاهگاه به دور مشهد به تاخت وتاز میرفت و چون قصد پادشاهی و انجام کار شاه طهماسب داشت و با بودن فتحعلیخان این کار ممکن نبود، به غدر، اسباب قتل آن شهریار را فراهم آورده و آن بزرگوار به دست یکی از قجرهای دولو شهادت یافت و بزرگان را که ملازم حضرت او بودند محبوس کرد و لشکر قاجار و ترکمان به استرآباد بازگشتند و با محمدحسن شاه بتعزیت آن شهریار مشغول شدند و چون ملک محمود از فتحعلیخان نهایت بیم را داشت شاد و آسوده شده در خواجه ربیع به جنگ شاه طهماسب شتافت . نادر نیز با لشکریان او را استقبال کرد و جنگ سختی کردند و ملک محمود بشهر مشهد گریخت و دروازه ها را بست و حصاری شد و نادر شهر را محاصره کرد و پس از چند روز کسان محمود با نادر سازش کرده شهررا دست دادند و نادرشاه طهماسب را بشهر مشهد آورده بود و به ولایات خراسان لشکر فرستاده آن نواحی را مسلم کرد. و اگرچه در آن اوقات میان شاه طهماسب و نادر رنجشی پیدا شده چون نادر تسلط تام داشت حکام و غیره از او خائف بودند، شاه طهماسب کاری نمیتوانست کرد و دست نشانده ٔ او بود و نادر هر کار که میخواست میکرد ونیز رضاقلیخان پسر خود را با زنان بمشهد فرستاده آن شهر را برای مسکن خود اختیار کرد و سان لشکر را دیده، شصت هزار بودند، بیست هزار را بمحارست شهر مشهد گذاشت و چهل هزار را برداشته بهرات رفت و آن بلده را گرفته بهرات باز گشت اشرف افغان که استیلاء نادر بشنید با لشکر خود رو بخراسان نهاد و دور شهر سمنان را بگرفت و نادر با شاه طهماسب و سپاه رو بجانب او نهاده، در محل معروف به مهماندوست بدو رسید و آن روز لشکر نادر شصت هزار سوار و پیاده بود. توپخانه را در بلندی جا داده که مشرف بمحل جنگ باشد و لشکر را سه قسمت کرده قسمتی را به دست راست و قسمتی را به دست چپ و خودنادر با شاه طهماسب در میان قسمت سوم بایستاد و پیادگان را در جلو و سواران را از عقب واداشت و بسرداران فرمان داد که تا لشکر دشمن نزدیک نشود دست بتفنگ وشمشیر نبرند و توپچیان را گفت همین که لشکر دشمن درمیان میدان آمد بنای توپ اندازی گذارند. اشرف و افغانان که سپاه ایران را بیکاره فرض کرده بودند از این لشکرآرائی نترسیده بیباکانه رو به جنگ آوردند و همین که بمیان میدان رسیدند توپچیان شلیک کردند و زنبورکخانه که به دست آنها و در جلو لشکرشان بود با جمعی از سواران از پای درآمدند و بقیه پس نشستند، اشرف چون چنین دید با غضب زیاده دست بشمشیر کرده بطرف مقابل تاخت . باز توپچیان شلیک کردند و جمعی از لشکر اشرف تلف شدند و طایفه ای نزدیک لشکر نادر رسیدند، آنوقت تفنگیان بفرمان سرکردگان شلیک کردند، بسیاری از افغانان نیز آنجا از پای درآمدند و اشرف و بازماندگان بگریختند و لشکر نادر ایشان را دنبال کرده و خود نیز تا نزدیک اصفهان نگذاشت ساعتی اشرف بیاساید و همه جا اورا دنبال کرده تا به مورچه خورت رسید. چون اشرف از سردار لشکر عثمانی که در همدان بود کمک خواسته جمعی از لشکر عثمانی در مورچه خورت به اشرف پیوستند. وی به یاری آنها مستظهر شده سر راه بر نادر بگرفت و در آنجا نیز جنگ سختی کردند و بسیاری از لشکر عثمانی مقتول و اشرف به اصفهان گریخت و از آنجا بشیراز رفت . نادرنیز شاه طهماسب را به اصفهان آورده خود بدنبال اشرف روان شد و در زرفون نیز جنگی کرده نادر ظفر یافت و تا شیراز او را تعاقب کرد و در فسا طایفه ای از بزرگان افغان بچنگ لشکریان او افتاده و هرچه جستجو کرد ازاشرف نشانی نیافت و به اصفهان بازگردید و اشرف از راه سیستان بقندهار رفت و پسر محمود به خونخواهی پدر او را بکشت . و چون بسیاری از اصقاع ایران را یا روس متصرّف شده بود یا عثمانی، نادر، عربستان و لرستان وبروجرد و همدان و کردستان و گیلان و بیشتر بلاد آذربایجان را مستخلص کرد و شاه طهماسب و بزرگان از او خائف شدند و تاج و کمر شاهی برای او فرستادند و نوشتند که خراسان اغتشاش دارد و افغانان دست اندازی میکنند، بهتر آن است که بدان جانب شتابی و آنجا را منظم نمائی، نادر را اگرچه این فقره مطبوع نیفتاده ولی لابد روبخراسان نهاد و آنجا را منظم کرد و هرات و قندهار را بگرفت و بخراسان بازگشت . و در آن اوقات شاه طهماسب و بزرگان ساده لوح او عزم جنگ عثمانی کردند و لشکر عثمانی از بغداد بصوب همدان رسید و شاه طهماسب با لشکر نیز بدان ساحت رسیده محاربه اتفاق افتاد و شکست فاحشی بلشکر شاه طهماسب وارد آمد و بسیار مقتول گردیدند و بازماندگان به اصفهان رسیده ناچار با آن دولت صلح کردند و مملکتهائی که نادر از ایشان گرفته بود بازبدیشان واگذار کردند. نادر که از این معنی آگاه شد زیاد متغیر گردیده نامه ای بشاه طهماسب نوشته پس از ملامت دستورالعمل داد که لشکر فارس و عمان را جمعآوری نمائید تا من نیز با سپاه خراسان و مازندران و گرگان به اصفهان آیم و تلافی کار عثمانی کنم . شاه طهماسب پذیرفته ولی چون نادر به قم رسید باز نزدیکان شاه طهماسب او را از آمدن نادر به اصفهان ترسانیده لهذا لشکر جمعآورده را شاه طهماسب بقم فرستاد و حکم داد که نادر از همانجا بجنگ عثمانی شتابد، نادر با عجز بسیارالتماس شرفیابی کرده معروض داشت که لازم است لشکر خراسان را در حضور شاه سان دهم، شاه طهماسب ناچار او را طلبیده نادر به اصفهان آمد و در حضور شاه طهماسب تملقات فوق العاده اظهار داشت و به درخواست شاه طهماسب را بهزار جریب که معسکر او بود ببازدید لشکر برد و شب را نیز شاه طهماسب را در آن محل به رسم مهمانی نگاه داشت و هر گونه اسباب طرب برای او حاضر و او مشغول عیش و حرکات ناپسند شد. نادر بزرگان و سرکردگان ایران و افغانستان را پشت سراپرده برده حرکات شاه طهماسب را مشهود ایشان نمود و ایشان از او تبرا کرده و به نادر گرویدند و با نادر هم عهد شدند و صبح شاه طهماسب را خلع کردند و نادر او را از راه یزد بخراسان نزد پسر خود رضاقلیخان فرستاد و او را چندی در مشهد نگاه داشته بعد بسبزوار فرستادند و در آن حدود مقتول گردید. پادشاهیش ده سال بود و در این ده سال شش سال مخذول افغانان و چهار سال دست نشانده ٔ نادر بود. (خلاصه ٔ تاریخ ایران از اقدم زمان تا عصر ناصرالدینشاه ).<br />سکه های عصر شاه طهماسب دوم :<br />گاه بر روی سکه ها خود را بدین مصراع معرفی کرده که :<br />غلام شاه دین طهماسب ثانی <br />و گاه بر روی سکه ها این بیت منقوش است :<br />بگیتی سکه ٔ صاحبقرانی <br />زد از توفیق حق طهماسب ثانی <br />و گاه این بیت :<br />سکه زد طهماسب ثانی بر زر کامل عیار<br />لا فتی الا علی لا سیف الا ذوالفقار.<br />و سکه ای هم دو سال قبل از خلع خویش از پادشاهی زده است که بیت ذیل روی آن نقش است :<br />از خراسان سکه بر زر شد بتوفیق خدا<br />نصرت و امدادشاه دین علی موسی رضا<br />سجع مُهر وی نیز مصراع ذیل بوده است : بنده ٔ شاه ولایت طهماسب (<span class=\"hlight\" dir=\"rtl\">١١٣٩</span>). (مسکوکات رابینو ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(177987, 'طهماسب قلیخان', '<span class=\"hlight\">طهماسب قلیخان .</span> <font color=\"DarkGreen\"><b>[ طَ ق ُ ]</font></b> (اِخ ) (طهماسبقلی جلایر) سردار کابل که در قیام مردم سیستان بر ضد نادر با علی قلی خان برادرزاده ٔ نادرشاه همدست شد و سر از فرمان نادر باززد. رجوع به مجمل التواریخ گلستانه ص <span class=\"hlight\" dir=\"rtl\">١٠</span> شود.<br /></font></div>'),
(177988, 'طهماسب میرزا', '<span class=\"hlight\">طهماسب میرزا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) از خوانین افشاریه، فرزند نادرمیرزا. رجوع به مجمل التواریخ گلستانه ص <span class=\"hlight\" dir=\"rtl\">٣٣٣</span> شود.<br /></font></div>'),
(177989, 'طهماسب میرزا', '<span class=\"hlight\">طهماسب میرزا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابوالفتح طهماسب میرزا. یکی از فرزندان شاه اسماعیل صفوی بوده است . رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٣١</span> و فهرست آن جلد شود.<br /></font></div>'),
(177990, 'طهماسبقلی', '<span class=\"hlight\">طهماسبقلی .</span> <font color=\"DarkGreen\"><b>[ طَ ق ُ ]</font></b> (اِخ ) (طهماسبقلی افشار) لقب نادرشاه افشار است . رجوع به نادر شود.<br /></font></div>'),
(177991, 'طهماسبقلی', '<span class=\"hlight\">طهماسبقلی .</span> <font color=\"DarkGreen\"><b>[ طَ ق ُ ]</font></b> (اِخ ) دهی از دهستان ییلاق بخش قروه ٔ شهرستان سنندج در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی باختر قروه کنارشوسه ٔ قروه به سنندج . جلگه و سردسیر با <span class=\"hlight\" dir=\"rtl\">٢٥٥</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات و توتون و لبنیات . شغل اهالی زراعت و گله داری است . دبستان و یک قهوه خانه در کنار شوسه دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(177992, 'طهمان', '<span class=\"hlight\">طهمان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) مولی سعیدبن العاص . صحابی است، یا طهمان ذکوان و ابراهیم بن طهمان که هر دو از ائمه ٔ اسلامند بر اختلاف اقوال . (منتهی الارب ). در الاصابه ذیل ترجمه ٔ طهمان آورده است که : مولی آل سعیدبن العاص . سپس گوید: در ذکر ذکوان گذشت . آنگاه در ترجمه ٔ ذکوان گوید: ذکوان، مولی بنی امیة. عبدالرزاق گوید: عمروبن حوشب از اسماعیل بن امیه از پدرش ازجدش بما خبر داد و گفت ما را غلامی است که او را ذکوان یا طهمان گویند. و رجوع به الاصابة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span> شود.<br /></font></div>'),
(177993, 'طهمان', '<span class=\"hlight\">طهمان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام یکی از موالی حضرت پیغمبرصلی اﷲ علیه و آله و سلم است که وی را بنامهای متعدد نام برده اند، از آن جمله : ذکوان، کیسان، مهران، هرمز. در کتاب الاصابه در ضمن ترجمه ٔ طهمان شرح احوال او را به ترجمه ٔ ذکوان ارجاع می دهد و در ترجمه ٔ ذکوان میگوید: «موالی رسول اﷲ صلی اﷲ علیه و آله و سلم ». ابن حیان وی را در زمره ٔ صحابه یاد کرده است . رجوع به الاصابة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span> و حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣٩</span> شود.<br /></font></div>'),
(177994, 'طهمان', '<span class=\"hlight\">طهمان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) رجوع به ابوالمنبه طهمان شود.<br /></font></div>'),
(177995, 'طهمان', '<span class=\"hlight\">طهمان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن عمرو الکلابی . او راست دیوان شعری که بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٩</span> م . جزو مجموعه ای بنام حرزة الحاطب و تحفة الطالب در شهر لیدن بطبع رسیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٤٧</span>).<br /></font></div>'),
(177996, 'طهمانی', '<span class=\"hlight\">طهمانی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص نسبی ) منسوب به ابراهیم بن طهمان . (انساب سمعانی ).<br /></font></div>'),
(177997, 'طهمانیة', '<span class=\"hlight\">طهمانیة.</span> <font color=\"DarkGreen\"><b>[ طَ نی ی َ ]</font></b> (اِخ ) قریه ای است منسوب بمردی طهمان نام . (از معجم البلدان ) (مراصد).<br /></font></div>'),
(177998, 'طهمة', '<span class=\"hlight\">طهمة.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) غذای مطبوع لذت بخش که مردم خوش خوراک در خوردن آن افراط کنند. (از دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>).<br /></font></div>'),
(177999, 'طهمة', '<span class=\"hlight\">طهمة.</span> <font color=\"DarkGreen\"><b>[ طَ هَِ م َ ]</font></b> (ع ص ) امرأه ٌ طَهِمَةٌ؛ زنی که رخسار او کم گوشت باشد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178000, 'طهمة', '<span class=\"hlight\">طهمة.</span> <font color=\"DarkGreen\"><b>[طُ م َ ]</font></b> (ع اِ) سیاه زردی مایل یا تیره با اندک سیاهی یا سرخ که بسپیدی زند. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178001, 'طهمل', '<span class=\"hlight\">طهمل .</span> <font color=\"DarkGreen\"><b>[ طَ م َ ]</font></b> (ع اِ) چیزی که از لمس آن حجم او بزودی محسوس نشود. <BR><font color=\"Blue\">◄</font> (ص ) زن باریک تن . <BR><font color=\"Blue\">◄</font> مرد فربه زشت خلقت . <BR><font color=\"Blue\">◄</font> مرد بدسرشت .(منتهی الارب ) (آنندراج ). طهمله، مؤنث . ج، طهامل .<br /></font></div>'),
(178002, 'طهملة', '<span class=\"hlight\">طهملة.</span> <font color=\"DarkGreen\"><b>[ طَ م َ ل َ ]</font></b> (ع ص ) تأنیث طهمل . ج، طهامل .<br /></font></div>'),
(178003, 'طهملی', '<span class=\"hlight\">طهملی .</span> <font color=\"DarkGreen\"><b>[ طَم َ لی ی ]</font></b> (ع ص ) کوتاه بالا. (منتهی الارب ) (ناظم الاطباء) <BR><font color=\"Blue\">◄</font> سیاه فام . (منتهی الارب ) (آنندراج ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178004, 'طهمورث', '<span class=\"hlight\">طهمورث .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (اِخ ) نام پادشاهی بود از نبیره های هوشنگ . گویند ابلیس را مرکوب ساخته بود و سوار میشد و مدت پادشاهی او را بعضی سی سال و بعضی هزار سال نوشته اند. (برهان ). قهندز مرو را او کرده است . (حدود العالم ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>). وی سومین پادشاه از طبقه ٔ پیشدادیان و لقب او زیناوند است یعنی شاکی السلاح (یعنی مرد باسلاح و چست و چابک ). (مفاتیح العلوم خوارزمی ). نسب او را به دو روایت نوشته اند، بعضی گفته اند: طهمورث بن ابونجهان بن اینکهدبن هوشهنگ . و بعضی گفته اند: طهمورث بن ایونجهان بن انکهدبن اینکهدبن اشکهندبن هوشهنگ . چنانکه بروایت اول به سه پدر با هوشنگ میرود و بروایت دوم، پنجم پدر او هوشهنگ است اما موافقند بر آنکه ولی عهد هوشهنگ بود و هوشهنگ چندان بزیست که در عهد او چهل سال پادشاهی همه جهان کرد. و طهمورث پیش از آنکه شاه شد همه در جنگ متمردان و دیوان بود، و او را دیوبند گفتندی . (از فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٠</span>). وی پادشاهی بود با علم و عدل و در روزگار او هیچکس بقوت او نبود و طاعت ایزدی عزّ ذکره نیکو داشتی و در دادگستری ومراعات اهل صلاح و قمع مفسدان سیرت جدّش هوشنگ سپردی . و آثار او آن است که اول کسی او بود که خط پارسی نهاد و زینت پادشاهان ساخت از اسبان برنشستن و بارها بر چهارپایان نهادن و اشکرها ازبهر نخجیر به دست آوردن و از پشم و موی جامه و فرش ساختن . و کهندز مرو اوبنا کرده است و در اصفهان همچنین دو بناء قدیم است که از آثار اوست : یکی مهرین که امروز ناحیتی را بدان بازمیخوانند، دویم سارویه و اکنون اصفهانیان آن را هفت ملکه گویند که بناء آن در میان شهرستان اصفهان مانده است و در میان آبیست شیرین و خوش که هیچکس نداندکه منبع آن از کجاست و رکن الدوله خمارتکین سر آن بنا را بکند و بر آن کوشکی ساخت . و در روزگار طهمورث بت پرستی آغاز شد و سبب آن بود که وبائی عظیم پدید آمدپس هرکه را عزیزی کناره میشد صورتی میساخت مانند اوتا بدیدار او خرسند میگشت، پس این معنی عادت و مستمر شد و فرزندان که آن را از مادر و پدر می دیدند به روزگار آن را همچون سنتی داشتندی و چنان شد که بتان را پرستش کردند و گفتند که ایشان شفیعان مااند بخدای عزوجل و این معنی ببلاد هند بیشتر بود و همچنین پارسیان گفته اند که : آغاز روزه داشتن هم از روزگار او بودو سبب آن بود که در آن ایام قحطی سخت عظیم بود، پس کسانی که منعم تر بودند درویشان را میداشتند و از دو بار طعام و غذا خوردن با یک بار کردند و یک بار بدرویشان دادند. و این مانند عبادتی بود. پس چون پیغمبران مرسل علیهم السلام بیامدند آن را فرض کردند بفرمان ایزدی عز ذکره و ازبهر تخفیف بندگان را سال بسال بفرمودند و بروزی چند شمرد در هر ملتی تعیین افتاد. و سی سال پادشاهی همه جهان کرد و در پادشاهی کناره شد و نسل نداشت و پادشاهی ببرادرش رسید. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٢٨</span>-<span class=\"hlight\" dir=\"rtl\">٢٩</span>). و نیز رجوع به ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>، <span class=\"hlight\" dir=\"rtl\">١٢٥</span>، <span class=\"hlight\" dir=\"rtl\">٦٣</span> فارسنامه ٔ ابن البلخی شود. و در حبیب السیر آورده که طهمورث بروایت بعضی از مورخان پسر صلبی هوشنگ است و زمره ای را اعتقاد آنکه پسرزاده ٔ اوست ... و از گفتار صاحب متون الاخبار نقل کرده که : طهمورث در اقالیم سبعه رایت سلطنت برافراخت ... و از قول صاحب تاریخ معجم گوید که :طهمورث از کرم ابریشمی استخراج کرد و به الهام الهی معلوم ِ او شد که خورش او برگ توت است . و هم از تاریخ جعفری آورده که مدت حیات طهمورث هشتصد سال و مدت پادشاهی وی به قول طبری چهارصد سال بوده است . (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span>). و پورداود در ج <span class=\"hlight\" dir=\"rtl\">٢</span> یشتها از ادبیات مزدیسنا راجع بطهمورث چنین آورده است : طهمورث (در فقره ٔ رام یشت )، در کتب تواریخ راجع به تهمورث روایات مختلف ذکر شده بطوری که نمیتوان میان آنها الفتی داد، مثلاً طبری و پس از او تقریباً همه ٔ مورخین نوشته اند که : در عهد طهمورث بوداسف ظهور کرد که مذهب صابئین آورد، همچنین غالباً نوشته اند که : در عهد طهمورث طوفان به وقوع پیوست و این پادشاه کتب را در اصفهان بزیر خاک پنهان کرد تا از آسیب طوفان محفوظ ماند.<br />چنانکه میدانیم بوداسف یا بودای هندی (رجوع بمقاله ٔ کئوتم شود) محققاً در اواسط قرن ششم ق .م . تولد یافت و طوفان نوح بنابه مندرجات تورات در دوهزاروپانصد سال پیش از مسیح بوقوع پیوست و مذهب صابئین که در قرآن هم از آنان اسم برده شده و هنوز یک جمعیت تقریباً پنجهزارنفری از آنان در عراق و چند خانواده در جنوب ایران موجود است و نگارنده در سال <span class=\"hlight\" dir=\"rtl\">١٣٠٦</span> هَ . ش . مفصلاً با آنان صحبت داشتم ابداً مربوط به آئین بودا نیست . همچنین آنچه مسعودی مینویسد که : ایرانیان پیش از زرتشت مذهب صابئین داشته اند بکلی بی اساس است . از این روایات نقیض و درهم برهم چنین برمی آید که در هر دوره و عهدی داستان نوی بداستان طهمورث افزوده شده، امروزه ازبرای ما ممکن نیست که بمآخذ اصلی پی برده وجه مناسبت آنها را بیان کنیم . چون از ذکرمناسبات منطقی عاجزیم درین مقاله لزومی بذکر آن روایات هم نمی بینم، چه در تاریخ کبیر طبری، مروج الذهب مسعودی و تاریخ سنی ملوک الارض و الانبیاء حمزه ٔ اصفهانی و آثارالباقیه ٔ بیرونی و مجمل التواریخ و غیره مفصلاً این روایات مندرج است . در کتب برخی از مستشرقین کلیه ٔ داستان طهمورث جمع گردیده و کمابیش شرح و توضیحاتی هم برای آنها نوشته شده است . در آخر این مقاله صورت آن کتب را خواهیم نگاشت . در این مقاله آنچه در اوستا و کتب پهلوی در خصوص طهمورث آمده و آن مقداری از مندرجات مورخین و فردوسی که ازبرای فهم مطلب لازم باشد، ذکر خواهد شد. همچنین در این داستان بمسائلی خواهیم پرداخت که در آنها فائده ٔ لغوی باشد.<br />اینک گوئیم : طهمورث در اوستا تخمو اوروپ َ آمده، جزء اول این اسم مرکب که تخم باشد، در فرس هخامنشی و گاتها و سایر قسمتهای اوستا بمعنی دلیر و پهلوانست . این کلمه به این معنی جداگانه مکرراً در اوستا استعمال شده است . در پهلوی و فارسی تهم شده چنانکه فردوسی گفته است :<br />تهم هست در پهلوانی زبان <br />بمردی فزون زاژدهای دمان .<br />در شاهنامه تهمتن لقبی است که به رستم داده شده یعنی بزرگ پیکر و قوی اندام، در واقع معنی کلمه ٔ رستم است، چه رستم نیز مرکب است از دو جزء نخست از کلمه ٔ رئوذ که بمعنی بالش و نمو است از همین کلمه است، روی در فارسی که بمعنی چهره و صورت ظاهراست . کلمه ٔ مذکور از ریشه ٔ فعل رئوذ که بمعنی بالیدن است میباشد، از همین کلمه است رستن و روئیدن . دوم از کلمه ٔ تهم بنابراین رستم درست بمعنی تهمتن است . یعنی کشیده بالا و بزرگ تن و قوی پیکر. بسا در فرهنگها رستهم ضبط شده که بخوبی جزءدوم اسم محفوظ است . در اسم گستهم نیز کلمه ٔ تهم بهیئت اصلی خود باقیست . یکی از سرداران داریوش بزرگ که در کتیبه ٔ بیستون از او اسم برده شده موسوم بوده به تخم سپاد یعنی دارنده ٔ سپاه دلیر. در تفسیر پهلوی اوستا تخم به «تگ » ترجمه شده است .<br />معنی جزء دوم که اوروپ باشد بطور تحقیق معلوم نیست، برخی از مستشرقین معنیی ازبرای آن حدس زده اند که چندان قابل توجه نیست .کلمه ٔ اوروپی جداگانه دراوستا استعمال شده و بمعنی یک قسم سگی است چنانکه در فرگرد <span class=\"hlight\" dir=\"rtl\">١٣</span> وندیداد فقره ٔ <span class=\"hlight\" dir=\"rtl\">١٦</span> و فرگرد <span class=\"hlight\" dir=\"rtl\">٥</span> فقره ٔ <span class=\"hlight\" dir=\"rtl\">٣٣</span>. درکتب تواریخ دو صفت ازبرای طهمورث ذکر کرده اند، اولی دیوبند که معنی آن معلوم است و بمناسبت در بند کردن وی دیوها را، بچنین صفتی متصف شده است . دومی ریباوند یا دیباوند، این کلمه که به اشکال دیگر هم ضبط شده خواه بواسطه ٔ خود مؤلفین که پی به ترکیب اصلی کلمه نبرده اند و خواه به دست نُساخ بواسطه ٔ کم و بیش گذاشتن نقاط از تلفظ و هیئت اصلی خود منحرف شده است . اما معنی آن را درست نوشته اند، در مجمل التواریخ که درعهد سلطان سنجر در سال <span class=\"hlight\" dir=\"rtl\">٥٢٠</span> هَ . ق . تألیف شده ریباوند چنین معنی شده است «آنکه سلاح تمام دارد». در روضة الصفا اینطور معنی شده «یعنی تمام سلاح ». حمزه ٔ اصفهانی مینویسد «طهمورث زیباوند، معنی زیباوند، انه شاکی السلاح ». این صفت باید در فارسی زیناوند نوشته شود، در اوستا مکرراً بصفت زئننگهونت یا ازینونت برمیخوریم، بسا این صفت برای خود طهمورث آمده چنانکه در آفرین زرتشت فقره ٔ <span class=\"hlight\" dir=\"rtl\">٢</span> زئننگهونت صفت اوست و معنی آن دارنده ٔ زین یا مسلح میباشد، چه این صفت از کلمه ٔ زئن که معنی سلاح است ساخته شده است، زین فارسی که بمعنی یراق و زین اسب است با لغت اوستائی زئن یکی است . لغت مذکور در قدیم در هیچ جابمعنی یراق اسب نیامده بلکه همیشه بمعنی اسلحه و آلات جنگ است . متقدمین از شعرا کلمه ٔ زین افزار را بمعنی ادوات جنگ گرفته اند چنانکه فرخی گفته است :<br />از آن کرانه کمان برگرفت و اندرشد<br />میان آب روان با سلیح و زین افزار.<br />زین در زبان ارمنی که از فارسی بعاریت گرفته شده بهمان معنی اصلی خود باقی و بمعنی سلاح است . در کتاب ائوگمدئچا بنابر صواب زیناوند صفت طهمورث ضبط شده است . در آفرین پیغمبر زرتشت حضرت زرتشت به کی گشتاسب دعا کرده گوید: بشود که تو مانند طهمورث مسلح (زیناوند) شوی . در شاهنامه این صفت ازبرای طهمورث نیامده است . در اوستادو بار از طهمورث یاد شده، نخست در فقرات <span class=\"hlight\" dir=\"rtl\">١١</span> - <span class=\"hlight\" dir=\"rtl\">١٣</span> رام یشت، دوم در فقرات <span class=\"hlight\" dir=\"rtl\">٢٨</span> - <span class=\"hlight\" dir=\"rtl\">٢٩</span> زامیادیشت در فقرات مذکور رام یشت آمده است «طهمورث زیناوند از فرشته ٔ هوا چنین درخواست کرد که وی را بهمه ٔ دیوها و مردمان و جادوان و پریها چیر سازد که وی اهریمن را به پیکر اسبی درآورده بر او سوار گشته تا به دو انتهای زمین براند». در فقرات مذکور زامیادیشت آمده است : «فر کیانی مدت زمانی بطهمورث زیناوند تعلق داشت، از پرتو آن او در روی هفت کشور شهریاری کرد، به دیوها و مردمان و جادوان و پریها و کاویها و کرپانها دست یافت و اهریمن را به پیکر اسبی درآورده در مدت سی سال به دو کرانه ٔ زمین همی تاخت ». متأسفانه در اوستا مختصراً از طهمورث یاد شده .<br />اما آنچه در کتاب مقدس مندرج است مطابق مندرجات کتب متأخرین است . مورخین طهمورث را دومین پادشاه پیشدادی ذکر کرده اند. از رام یشت هم اینطور برمی آید که طهمورث دومین شهریاراین خاندان باشد، چه اسم او پس از هوشنگ نخستین پادشاه پیشدادی و پیش از جمشید سومین شهریار این سلسله ذکر شده است . دیگر اینکه در اکثر کتب تواریخ سلطنت وی سی سال مندرج است و در رامیادیشت همین مدت را برای او قائل شده اند، چه او در مدت سی سال اهریمن را مطیع خود داشته بر او مستولی بود. در اوستا اسم پدر طهمورث معین نشده اما حمزه ٔ اصفهانی او را پسر نوبجهان (ویونجهان ) پسر ایونکهند پسر هونکهند پسر اوشهنج ذکرکرده و جمشید را برادرش دانسته است، و در مجمل التواریخ هم اینطور مسطور است مگر اینکه ابورکهند و هورکهند بجای ایونکهند و هونکهند نقل شده است . مسعودی طهمورث را پسر نوبجهان (ویونجهان ) پسر ارفخشدش پسر هوشنگ نوشته است . در آثار الباقیة طهمورث پسر ویجهان پسر اینکهد پسر اوشهنگ و لقبش زیباوند ضبط شده است . بندهش در فصل <span class=\"hlight\" dir=\"rtl\">٣١</span> فقرات <span class=\"hlight\" dir=\"rtl\">٢</span> و <span class=\"hlight\" dir=\"rtl\">٣</span> مطابق ابوریحان نقل میکند: «طهمورث پسر ویونگهان پسر یکهد پسر هوشنگ بوده است . جم و طهمورث و نرس برادر بوده اند. بنابه اتفاق روایات صواب این است که طهمورث را پسر ویونگهان و برادرجمشید بدانیم و بنابه سلسله ٔ نسبی که ازبرای او نوشته اند او را نوه یا نبیره ٔ هوشنگ بشماریم نه اینکه چنانکه بخطا در شاهنامه آمده او را پسر هوشنگ و پدر جمشید بخوانیم . در کتب تواریخ نیز مانند اوستا داستان رام کردن طهمورث اهریمن را، مفصلاً نقل شده است . در سنت، شکست اهریمن به دست طهمورث در روز خرداد در ماه فروردین روی داد. در تاریخ نسبی مسطور است : «خدای عزّوجل او را چنان نیرو داده بود که ابلیس را و دیوان را فرمانبردار خود کرده بود و ایشان را فرموده بود که از میان خلق بیرون شوند و همه را از آبادانی بیرون کرد به بیابانها و دریاها فرستاد و شأن و زینت ملوک و اسب نشستن و زین برنهادن او آورد و اشتر بجهان او آورد و خر بر اسب او افکند تا استر آمد و استر رابار برنهاد و یوز را شکار او آموخت و پارسی را او افکند و خط او نوشت ». در شاهنامه آمده است :<br />برفت اهرمن را به افسون ببست <br />چو بر تیزرَو بارگی برنشست <br />زمان تا زمان زینْش برساختی <br />همی گرد گیتیش برتاختی .<br />در یک روایت منظوم که مستشرق مرحوم اشپیگل در کتاب خود موسوم به ادبیات پارسیان طبع کرده این داستان مفصلاً نقل شده و خلاصه اش این است : «طهمورث اهریمن را در مدت سی سال در بندداشت، بر او زین نهاده بر پشت او سوار شده هر روز سه بار گرد گیتی میگشت و بر سرش گرز پولادین میکوفت و با او دریا و کوه و فراز و نشیب البرز را می پیمود، وقتی که از گردش برمیگشت او را در بند کرده جز زخم گران آشام و خوراکی نداشت . زن طهمورث واقعه ٔ اسب بی خواب و خوراک را از شوهرش بازپرسید، طهمورث در پاسخ گفت : من خود نیز از کار این اهریمن در شگفت بودم، راز کار از او جویا شده بمن چنین گفت که : خوراک من از گناه مردم است . هر آن روزی که از مردمان گناه بیشتر سرزند من بیشتر خورش یافته شاد و خرم شوم، هر آن روزی که کمتر بدی کنند من در رنج گرسنگی دچار گردم . اهریمن سالها در بند بود تا اینکه ازبرای رهائی خود چاره ای اندیشید و به زن طهمورث وعده ٔ بخشیدن انگبین و ابریشم داد، تحفه هائی که در جهان کسی ندیده بود در صورتی که او از شوهرش بپرسید که در هنگام تاخت وتاز در فراز و نشیب البرز در کجا از سرعت سیر من او را هراس فراگیرد. زن طهمورث بنابه دستور اهریمن قضیه را از شوهرش درخواست کرد، طهمورث در جواب گفت : هنگامی که اواز البرز بتندی سر سوی نشیب نهد مرا بیم فراگیرد و گرز پیاپی بسرش میکوبم تا از گزند جان بدربرم . زن طهمورث آنچه از شوهرش شنیده بود به اهریمن بازگفت و عسل و ابریشم دریافت . روز دیگر در بامداد بنابه عادت طهمورث بر پشت اهریمن اسب پیکر برآمده گرد گیتی همی تاخت تا فراز البرز برآمد و از آنجا روی به نشیب نهاد.آنگاه اهریمن سرکشی کرد و خیرگی آغاز کرد، هرچند طهمورث گرز نواخت و خروش برآورد و بر مرکب نهیب زد سودی نبخشید، اهریمن او را از زین بزمین بیفکند و دم درکشیده او را فروبرد و روی بگریز نهاد. آنگاه سروش شاه جمشید را از مرگ طهمورث آگاه ساخت و بدو تدبیری آموخت که چگونه لاشه ٔ طهمورث را از شکم اهریمن بیرون تواند کشید. جمشید آنچنان که سروش گفته بود بجای آورد و اهریمن را بجرم غلامبارگی فریفته لاشه ٔ طهمورث از شکمش بیرون کشیده و شست وشو داده به استودان نهاده، بنای استودان از آن روز است ».<br />در کتب مورخین بنای چندین شهر چنانکه حمزه مینویسد به طهمورث منسوبست . از آن قبیل بابل و قهندز مرو وکردینداد که یکی از شهرهای مداین بوده است . دیگر از اعمال مشهور طهمورث رام کردن دیوهاست که در اوستا هم اشاره به آن شده است . میرخواند در روضة الصفا از تاریخ جعفری نقل کرده مینویسد که «طهمورث به دست خود یکهزاروچهارصدوهشتاد دیو بکشت و هشتصد سال عمراو بود و سی سال سلطنت کرد و در دیار بلخ مدفون گشت ». دیگر از اعمال مشهور طهمورث به وجود آوردن خط است که در اوستا ذکری از آن نیست اما در یکی از قطعات اوستائی معروف به «ائوگمدئچا» فقره ٔ <span class=\"hlight\" dir=\"rtl\">٩١</span> آمده است : «طهمورث زیناوند ویونگهان که دیو دیوان اهریمن را به بار داشت هفت قسم دبیری (خط) از او آورد». همچنین در مینوخرد فصل <span class=\"hlight\" dir=\"rtl\">٣٧</span> فقره ٔ <span class=\"hlight\" dir=\"rtl\">٢١</span> آمده «برتری طهمورث نیک آئین در این بود او اهریمن را در مدت سی سال به بار داشت و هفت قسم دبیری را (خط را) که اهریمن پنهان کرده بود آشکار ساخت ». در شاهنامه مندرج است : دیوها در جنگ طهمورث شکست یافته گرفتار بند وی شدند، از او درخواستند که آنان را نکشد تا در عوض هنر نوشتن به او بیاموزند:<br />نوشتن بخسرو بیاموختند<br />دلش را بدانش برافروختند<br />نوشتن یکی نه که نزدیک سی <br />چه رومی چه تازی و چه پارسی <br />چه هندی و چینی و چه پهلوی <br />نگاریدن آن کجا بشنوی .<br />چنانکه ملاحظه میشود فردوسی میگوید: تقریباً سی قسم خط بیاموختند اما فقط از شش قسم خط اسم میبرد. دیگر اینکه از شاهنامه برمی آید که خط صنعت اهریمنی است بی شک سهوی است چنانکه از مندرجات ائوگمدئچا و مینوخرد صراحةً مفهوم میشود باید خط را هنر ایزدی و آفریده ٔ سپنت مینو یا خرد مقدس دانست، لکن چندی اهریمن آن را پنهان کرده بشر را از آن محروم داشت . در انجام متذکر میشویم که طهمورث در آئین مزدیسنا از پارسایان و از خداپرستان بشمار است و برخلاف آنچه حمزه ٔ اصفهانی نوشته که در عهد طهمورث بت پرستی را رواج گرفت در کتاب هفتم دینکرد فصل <span class=\"hlight\" dir=\"rtl\">١</span> فقره ٔ <span class=\"hlight\" dir=\"rtl\">١٩</span> مندرج است که :طهمورث بت پرستی را برانداخت و مردم را بستایش پروردگار امر کرد. (ادبیات مزدیسنا تألیف پورداود ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">١٣٨</span> - <span class=\"hlight\" dir=\"rtl\">١٤٤</span>). مؤلف مجمل التواریخ و القصص مرگ طهمورث را مرگ طبیعی دانسته و گوید: بمرگ خود از جهان برفت . رجوع به ص <span class=\"hlight\" dir=\"rtl\">٣٩</span> کتاب مزبور شود. و نیز راجع به آرامگاه طهمورث از حمزه ٔ اصفهانی نقل کرده گوید حمزه در کتاب اصفهان چنین آرد که : این کوه را که اکنون آتشگاه خوانند از جمله بیوت عبادات بوده است در عهد طهمورث و آن را مینودز خوانده اند و بتان نهاده بودندی بسیارچنانکه از جمله ٔ شهرهاء مشرق آنجا آمدندی بحج کردن تا روزگار گشتاسب اسفندیار بفرمان پدر آن را از بتان خالی کرد و آتشگاه کرد و هم بر آن بماند تا شاه اسکندر آن را خراب کرد، و چنان آورده اند که طهمورث آنجانهاده است . رجوع به ص <span class=\"hlight\" dir=\"rtl\">٤٦١</span> و <span class=\"hlight\" dir=\"rtl\">٤٦٢</span> کتاب مزبور شود <span class=\"hlight\">:</span> <br />پسر بُد مر او را یکی هوشمند<br />گرانمایه طهمورث دیوبند.<br /> <font color=\"Red\">فردوسی .</font><br />جهاندار شاه اخستان کز طبیعت <br />کیومرث طهمورث امکان نماید.<br /> <font color=\"Red\">خاقانی .</font><br />و رجوع به ص <span class=\"hlight\" dir=\"rtl\">١٣</span>، <span class=\"hlight\" dir=\"rtl\">٢٤</span>، <span class=\"hlight\" dir=\"rtl\">٢٦</span>، <span class=\"hlight\" dir=\"rtl\">٤٧</span>، <span class=\"hlight\" dir=\"rtl\">٨٩</span>، <span class=\"hlight\" dir=\"rtl\">١٨٩</span>، <span class=\"hlight\" dir=\"rtl\">٤١٦</span>، <span class=\"hlight\" dir=\"rtl\">٤١٧</span> کتاب مجمل التواریخ و القصص و ص <span class=\"hlight\" dir=\"rtl\">٢٣١</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ادبیات مزدیسنا و ج <span class=\"hlight\" dir=\"rtl\">٢</span> از کتاب مزبور ص <span class=\"hlight\" dir=\"rtl\">٢٣٥</span> و <span class=\"hlight\" dir=\"rtl\">٣١٦</span> و ص <span class=\"hlight\" dir=\"rtl\">٣</span>، <span class=\"hlight\" dir=\"rtl\">٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٠</span> تاریخ سیستان و ص <span class=\"hlight\" dir=\"rtl\">١١٥</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span> لباب الالباب و ص <span class=\"hlight\" dir=\"rtl\">٣٧</span>، <span class=\"hlight\" dir=\"rtl\">٤٤</span>، <span class=\"hlight\" dir=\"rtl\">٤٨</span>، <span class=\"hlight\" dir=\"rtl\">٥٠</span>، <span class=\"hlight\" dir=\"rtl\">٦٧</span>، <span class=\"hlight\" dir=\"rtl\">٦٩</span>، <span class=\"hlight\" dir=\"rtl\">١٢٥</span>، <span class=\"hlight\" dir=\"rtl\">١٢٦</span>، <span class=\"hlight\" dir=\"rtl\">١٤٨</span>، <span class=\"hlight\" dir=\"rtl\">١٥٥</span>، <span class=\"hlight\" dir=\"rtl\">١٥٦</span>، <span class=\"hlight\" dir=\"rtl\">١٦٠</span>، <span class=\"hlight\" dir=\"rtl\">١٦١</span> نزهة القلوب چ اروپا و ص <span class=\"hlight\" dir=\"rtl\">١٦٢</span> از ج <span class=\"hlight\" dir=\"rtl\">٢</span> شعوری و فهرست نخبةالدهر دمشقی شود.<br /></font></div>'),
(178005, 'طهمورث', '<span class=\"hlight\">طهمورث .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (اِخ ) دهی از دهستان خسروآباد شهرستان بیجار در <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی جنوب بیجار. نزدیک کوه سنگ پا. تپه ماهور و سردسیر با <span class=\"hlight\" dir=\"rtl\">٤٧٠</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات و انگور و لبنیات . شغل اهالی زراعت و گله داری و قالیچه و گلیم و جاجیم بافی . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(178006, 'طهمورث آباد', '<span class=\"hlight\">طهمورث آباد.</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (اِخ ) دهی جزء دهستان رودبار بخش معلم کلایه ٔ شهرستان قزوین در <span class=\"hlight\" dir=\"rtl\">٥٠٠٠٠</span> هزارگزی معلم کلایه و <span class=\"hlight\" dir=\"rtl\">٣٣٠٠٠</span> گزی راه عمومی . کوهستان و معتدل با <span class=\"hlight\" dir=\"rtl\">٨٠</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات و لبنیات . شغل اهالی زراعت . راه آن مالرو و صعب العبور است . چناری کهن سال دارد که معروف به هفت خانه است . ساکنین از تیره ٔ کماسی طایفه ٔ غیاثوند بوده اکثر آنان در تابستان بحدود یشام در <span class=\"hlight\" dir=\"rtl\">١٠٠٠٠</span>گزی جنوب ده میروند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(178007, 'طهمورثات', '<span class=\"hlight\">طهمورثات .</span> <font color=\"DarkGreen\"><b>[ طَرِ ]</font></b> (اِخ ) دهی از دهستان رودشت بخش کوهپایه ٔ شهرستان اصفهان در <span class=\"hlight\" dir=\"rtl\">٢٥</span> هزارگزی جنوب خاوری کوهپایه و <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزارگزی شوسه ٔ اصفهان به یزد. جلگه و معتدل با <span class=\"hlight\" dir=\"rtl\">١٢٨</span> تن سکنه . آب آن از رودخانه . محصول آنجا غلات و پنبه . شغل اهالی زراعت . صنایع دستی زنان کرباس بافی و پنبه ریسی . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(178008, 'طهمورثی', '<span class=\"hlight\">طهمورثی .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (ص نسبی ) منسوب به طهمورث <span class=\"hlight\">:</span> <br />ز بس های و هوی و جرنگ درای <br />بکردار طهمورثی کرّنای .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(178009, 'طهنبی', '<span class=\"hlight\">طهنبی .</span> <font color=\"DarkGreen\"><b>[ طَ هَم ْ با ]</font></b> (ع ص ) سخت استوار. (منتهی الارب ): بعیرٌ طهنبی ؛ شدیدٌ قوی ٌ. (قُطر المحیط).<br /></font></div>'),
(178010, 'طهنة', '<span class=\"hlight\">طهنة.</span> <font color=\"DarkGreen\"><b>[ طِ ن َ ]</font></b> (اِخ ) قریه ای است در صعید مصر، شرقی ِ نیل . (مراصد).<br /></font></div>'),
(178011, 'طهنه', '<span class=\"hlight\">طهنه .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (اِخ ) دهی از دهستان ماهیدشت بالا از بخش مرکزی شهرستان کرمانشاه در <span class=\"hlight\" dir=\"rtl\">٢٢</span> هزارگزی جنوب کرمانشاه و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی سروناو. دشت و سردسیر با <span class=\"hlight\" dir=\"rtl\">٦٥</span> تن سکنه . آب آن از رودخانه ٔ مرگ . محصول آنجا غلات و حبوبات و تریاک و صیفی و چغندرقند و لبنیات . شغل اهالی زراعت و گله داری و مکاری . درسه محل بفاصله ٔ یک هزار گز واقع و به علیا - وسطی مشهور و سکنه ٔ آنجا بترتیب <span class=\"hlight\" dir=\"rtl\">٢٨٤</span> و <span class=\"hlight\" dir=\"rtl\">٢٤٥</span> و <span class=\"hlight\" dir=\"rtl\">١٢٣</span> نفر است . طهنه ٔ سفلی دارای خرابه ای است که فعلاً بارانداز مکاری های عثمانوند میباشد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(178012, 'طهنه', '<span class=\"hlight\">طهنه .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ ]</font></b> (اِخ ) دهی جزء دهستان قزقان چای بخش فیروزکوه شهرستان دماوند در <span class=\"hlight\" dir=\"rtl\">٢٩٠٠٠</span> گزی خاور فیروزکوه و <span class=\"hlight\" dir=\"rtl\">١٢٠٠٠</span> گزی شمال راه شوسه ٔفیروزکوه به تهران . کوهستان و سردسیر با<span class=\"hlight\" dir=\"rtl\">٣٥٠</span> تن سکنه . و آب آن از قنات و چشمه . محصول آنجا غلات و بنشن و عسل . شغل اهالی زراعت و مکاری و زمستان جهت خیاطی و سفیدگری بمازندران میروند. راه آن مالرو است . مزرعه ٔدریابیگ جزء این ده است و ایل اصانلو در تابستان به حدود این ده می آیند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(178013, 'طهنهور', '<span class=\"hlight\">طهنهور.</span> <font color=\"DarkGreen\"><b>[ طَ هََ هو ]</font></b> (اِخ ) قریه ای است بر ساحل غربی نیل در صعیدکه آن را طهنهور السدر گویند. (از معجم البلدان ).<br /></font></div>'),
(178014, 'طهو', '<span class=\"hlight\">طهو.</span> <font color=\"DarkGreen\"><b>[ طَهَْ وْ ]</font></b> (ع اِ) کار. و منه حدیث ابی هریرة حین روی حدیثاً، فقیل له : اسمعت من رسول اﷲ صلی اﷲ علیه و آله و سلم، فقال : فما طهوی اذاً؛ ای فما عملی ان لم احکم ذلک . (منتهی الارب ) (آنندراج ). ابوعبیدة و هذا مثل ضربه ُ فی احکامه للحدیث و اتقانه ایاه کالطاهی المجید و المنضج لطعامه یقول : فماکان عملی ان کنت لم احکم هذه الروایة التی رویتها، کاحکام الطاهی للطعام . (تاج العروس ). <BR><font color=\"Blue\">◄</font> (مص ) کار کردن . <BR><font color=\"Blue\">◄</font> رفتن در زمین . سفر کردن . (منتهی الارب ). در زمین بشدن . (تاج المصادر بیهقی ).<br /></font></div>'),
(178015, 'طهو', '<span class=\"hlight\">طهو.</span> <font color=\"DarkGreen\"><b>[ طَهَْ وْ <span class=\"hlight\" dir=\"rtl\">/</span> طُ هَُ وو ]</font></b> (ع مص ) گوشت پختن . (منتهی الارب ). بریان کردن . (منتهی الارب ) (تاج المصادر بیهقی ).<br /></font></div>'),
(178016, 'طهور', '<span class=\"hlight\">طهور.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ملک جزیره ٔ ماسلاماجین (؟) (مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٢٧</span>).<br /></font></div>'),
(178017, 'طهور', '<span class=\"hlight\">طهور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) طهارت کردن . (منتهی الارب ). پاک کردن . پاکیزه ساختن . <BR><font color=\"Blue\">◄</font> (اِ) آب دستی آنچه بدان طهارت کنند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) پاک کننده . (منتهی الارب ) (آنندراج ). آب پاک کننده . (مهذب الاسماء) <span class=\"hlight\">:</span> و انزلنا من السماء ماءً طهوراً؛ و از آسمان فرستادیم آبی پاک و پاک کننده یعنی آب باران و آن آبی بود هم پاک و هم پاک کننده و طهور گفتند بمعنی مطهِّر است و این حکم آب باران است مادام تا چیزی به او نرسد که او را پلید کند، و به او رفع حدث توان کردن و ازاله ٔ نجاست . (قرآن <span class=\"hlight\" dir=\"rtl\">٢٥</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">٤٨</span>، از تفسیر ابوالفتوح رازی ). و سَقاهم ربهم شراباًطهوراً؛ شرابی پاکیزه یعنی آلوده نشود آبش به آنچه آلوده شود آبهای دنیا از چیزهائی که آن را از حکم پاکی ببرد. گفتند خمرش پاکیزه باشد از آنکه مستی کند وخمار آورد و داعی بقبایح . و گفتند: معنی آنست که پاک بود به وقت دویم، مستحیل نشود ببول بل از اندام ایشان جدا شود بمانند عرق که بوی مشک دارد. ابوقلابة گفت : خدای تعالی هر مردی را از اهل بهشت چندانی شهوت و نهمت و قوت بدهد که صد مرد را از اهل دنیا. چون طعامی که خواهند بخورند ایشان را شرابی دهند که شکم ایشان مطیب شود و به وقت هضم طعام و شراب و رشحی شود و از اندام ایشان بیاید بمانند مشک اذفر، باز دیگرباره شکم ایشان تهی شود و بشهوت طعام بازآید. و گفتند شراب طهور یعنی شرابی مطهِّر پاک کننده ایشان را از ادناس و انجاس پاک کند و ایشان را چنان کند که صلاحیت مقام بهشت دارند. (قرآن <span class=\"hlight\" dir=\"rtl\">٧٦</span> <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">٢١</span>، از تفسیر ابوالفتوح ).<br />بساقی گری گر کند جلوه حور<br />نگیرم ز دستش شراب طهور.<br /><font color=\"Red\">ظهوری (از شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span>).</font><br /></font></div>'),
(178018, 'طهوش', '<span class=\"hlight\">طهوش .</span> <font color=\"DarkGreen\"><b>[ طَهَْ وَ ]</font></b> (اِخ ) نام مردی . (منتهی الارب ).<br /></font></div>'),
(178019, 'طهوی', '<span class=\"hlight\">طهوی .</span> <font color=\"DarkGreen\"><b>[ طُ وی ی ]</font></b> (ص نسبی ) نسبت است به طهیة از بنوطهیة. رجوع به طُهَیّة دختر عبدشمس شود.<br /></font></div>'),
(178020, 'طهوی', '<span class=\"hlight\">طهوی .</span> <font color=\"DarkGreen\"><b>[ طُ هََ وی ی ]</font></b> (ص نسبی ) منسوب به طُهَیَّة که قبیله ای است . (منتهی الارب ).<br /></font></div>'),
(178021, 'طهی', '<span class=\"hlight\">طهی .</span> <font color=\"DarkGreen\"><b>[ طُ ها ]</font></b> (ع اِ) گرگ . <BR><font color=\"Blue\">◄</font> (ص ) پخته هرچه باشد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178022, 'طهی', '<span class=\"hlight\">طهی .</span> <font color=\"DarkGreen\"><b>[ طَهَْ ی ْ ]</font></b> (ع مص ) گوشت پختن . بریان کردن . (منتهی الارب ) (آنندراج ). طهو. طُهی ّ.<br /></font></div>'),
(178023, 'طهی', '<span class=\"hlight\">طهی .</span> <font color=\"DarkGreen\"><b>[ طُ هی ی ]</font></b> (ع مص ) گوشت پختن .بریان کردن . (منتهی الارب ) (آنندراج ). طهو. طَهْی .<br /></font></div>'),
(178024, 'طهی', '<span class=\"hlight\">طهی .</span> <font color=\"DarkGreen\"><b>[ طَ ها ]</font></b> (ع اِ) کاه ریزه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178025, 'طهیان', '<span class=\"hlight\">طهیان .</span> <font color=\"DarkGreen\"><b>[ طَهَْ <span class=\"hlight\" dir=\"rtl\">/</span> طَ هََ ]</font></b> (اِخ ) کوهی است . (منتهی الارب ). نام قله ٔ کوهی است در یمن . (از معجم البلدان ).<br /></font></div>'),
(178026, 'طهیان', '<span class=\"hlight\">طهیان .</span> <font color=\"DarkGreen\"><b>[ طَ هََ ]</font></b> (ع اِ) سرکوه . <BR><font color=\"Blue\">◄</font> تراشه ٔ چوب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کوزه آویز. (مهذب الاسماء در سه نسخه ٔ خطی ).<br /></font></div>'),
(178027, 'طهیایة', '<span class=\"hlight\">طهیایة.</span> <font color=\"DarkGreen\"><b>[ طَهَْ ی َ ]</font></b> (ع مص ) گوشت پختن . بریان کردن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178028, 'طهیة', '<span class=\"hlight\">طهیة.</span> <font color=\"DarkGreen\"><b>[ طُ هََ ی ْ ی َ ]</font></b> (اِخ ) قبیله ای است . (منتهی الارب ). و رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٨</span> و ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٨</span> و <span class=\"hlight\" dir=\"rtl\">٦٦</span> و <span class=\"hlight\" dir=\"rtl\">٦٩</span> شود.<br /></font></div>'),
(178029, 'طهیة', '<span class=\"hlight\">طهیة.</span> <font color=\"DarkGreen\"><b>[ طُ هََ ی ْ ی َ ]</font></b> (اِخ ) دختر عبدشمس بن سعد از طائفه ٔ تمیم عدنانیه یا جاهلیه است از ابناء عدنانیه که به «بنوطهیة» معروفند و نسبت به وی طهوی بسکون هاء میباشد. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٢</span>).<br /></font></div>'),
(178030, 'طهیة', '<span class=\"hlight\">طهیة.</span> <font color=\"DarkGreen\"><b>[ طُ هََ ی ْ ی َ ]</font></b> (اِخ ) ابن ابی زهیر الهندی . رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٨</span> و الاصابه ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٩٧</span> شود.<br /></font></div>'),
(178031, 'طهیر', '<span class=\"hlight\">طهیر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) پاک . (منتهی الارب ) (آنندراج ). ج، طُهران، طهاری . <BR><font color=\"Blue\">◄</font> پاک کننده . (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(178032, 'طهیلة', '<span class=\"hlight\">طهیلة.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ]</font></b> (ع اِ) طِهْلِئة. طئهلة. گل و لای که در حوض فروریزد بعد از آنکه اندوده باشند آنرا. (منتهی الارب ) (آنندراج ). گل که در بن حوض بماند. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> (ص ) احمق بی خیر. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178033, 'طهیلة', '<span class=\"hlight\">طهیلة.</span> <font color=\"DarkGreen\"><b>[ طَهَْ ی َ ل َ ]</font></b> (ع مص ) تره ٔ طهله خوردن . (منتهی الارب ).<br /></font></div>'),
(178034, 'طهیوفیع', '<span class=\"hlight\">طهیوفیع.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) اسم ترنجبین است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178035, 'طو', '<span class=\"hlight\">طو.</span> (ترکی، اِ) طوی . ضیافت . عروسی <span class=\"hlight\">:</span> <br />دائماً خاقان ما کرده ست طو<br />گوش مارا می کشد لاتقنطوا.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(178036, 'طو', '<span class=\"hlight\">طو.</span> <font color=\"DarkGreen\"><b>[ طَ وِن ْ ]</font></b> (ع ص ) گرسنه . طاو. طاوی . (منتهی الارب ).<br /></font></div>'),
(178037, 'طوا', '<span class=\"hlight\">طوا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام دیهی از استرآبادرستاق . (مازندران و استرآباد رابینو ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).<br /></font></div>'),
(178038, 'طواب', '<span class=\"hlight\">طواب .</span> <font color=\"DarkGreen\"><b>[ طَوْ وا ]</font></b> (ع ص ) خشت پز. (آنندراج ).<br /></font></div>'),
(178039, 'طوابق', '<span class=\"hlight\">طوابق .</span> <font color=\"DarkGreen\"><b>[ طَ ب ِ ]</font></b> (ع اِ) ج ِ طابق . (منتهی الارب ).<br /></font></div>'),
(178040, 'طوابیق', '<span class=\"hlight\">طوابیق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طابق . (منتهی الارب ).<br /></font></div>'),
(178041, 'طواحن', '<span class=\"hlight\">طواحن .</span> <font color=\"DarkGreen\"><b>[ طَ ح ِ ]</font></b> (ع اِ) ج ِ طاحنه ج ِ طاحونة. دندانهای بزرگ . (منتهی الارب ). دندانهای بزرگ پهن که طعام بدان سائیده شود و بفارسی آسیادندان گویند. (منتخب اللغات ). دندانهای آسیا. اضراس . دوازده دندان که از پس ضواحک بود. (مهذب الاسماء). از پس انیاب شانزده دندانست دیگر، هشت زیر و هشت زَبَر. از هر سو چهار همه گرد و سرهاء آنها پهن است و درشت است آن را دندانهاء آسیا گویند و به تازی طواحن و اضراس نیز گویند و طواحن را آنچه زبرین است بیخها به سه شاخ است و آنچه زیرین است به دو شاخ . (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(178042, 'طواحی', '<span class=\"hlight\">طواحی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) کرکسان بر هوا گرد مردار گردنده . (منتهی الارب ).<br /></font></div>'),
(178043, 'طواحین', '<span class=\"hlight\">طواحین .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طاحونة. (دهار).<br /></font></div>'),
(178044, 'طواحین', '<span class=\"hlight\">طواحین .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) موضعی است بسرزمین فلسطین نزدیک رمله، و وقعه ٔمشهور بین خمارویه بن طولون و المعتضد باﷲ بسال <span class=\"hlight\" dir=\"rtl\">٢٧١</span> هَ . ق . نزدیک این مکان بوده است . (معجم البلدان ).<br /></font></div>'),
(178045, 'طواخ', '<span class=\"hlight\">طواخ .</span> <font color=\"DarkGreen\"><b>[ طَوْ وا ]</font></b> (ع ص ) تهمت زننده به کسی در قول یا فعل . (از اقرب الموارد).<br /></font></div>'),
(178046, 'طوار', '<span class=\"hlight\">طوار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) حد و نهایت چیزی . مساوی آن چیز. <BR><font color=\"Blue\">◄</font> طَوار الدار و طِوار الدار؛ درازی و فراخی سرای . (منتهی الارب ). فراخی و درازی خانه . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> گرداگرد سرای . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> مادینه از جوارح طیور (در بازیاری ).<br /></font></div>'),
(178047, 'طوار', '<span class=\"hlight\">طوار.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) حد هر چیزی . <BR><font color=\"Blue\">◄</font> مقدار. (منتهی الارب ).<br /></font></div>'),
(178048, 'طواران', '<span class=\"hlight\">طواران .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) شهرستانیست بزرگ بسند و قصبه ٔ آن قزدار واز شهرهای آن قندبیل و غیره است . (معجم البلدان ).<br /></font></div>'),
(178049, 'طوارف', '<span class=\"hlight\">طوارف .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (ع ص، اِ) ج ِ طارف . <BR><font color=\"Blue\">◄</font> چشمها، گویند: لاتراه الطوارف . (منتهی الارب ). چشمان . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> دد که برباید شکار را. <BR><font color=\"Blue\">◄</font> خیمه و خرگاه دامنها درواکرده جهت نگریستن ماوراء آن . (منتهی الارب ). خیمه که دامن او برداشته شود تا بیرون نظر کرده شود. (منتخب اللغات ).<br /></font></div>'),
(178050, 'طوارق', '<span class=\"hlight\">طوارق .</span> <font color=\"DarkGreen\"><b>[ طَ رِ]</font></b> (ع اِ) ج ِ طارقه . (منتهی الارب ). حادثه های سوء بشب . بلاها که بشب رسد <span class=\"hlight\">:</span> از طوارق ایام و حوادث روزگار مصون و محروس مانده . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤١٠</span>). حواشی ممالک از سوابق خلل و طوارق زیغ و زلل پاک کرد. (ترجمه تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٦٥</span>). از دست تصاریف زمان و طوارق حدثان در امان بودند. (جهانگشای جوینی ).<br /></font></div>'),
(178051, 'طوارم', '<span class=\"hlight\">طوارم .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (ع اِ) ج ِ طارم .<br /></font></div>'),
(178052, 'طواره', '<span class=\"hlight\">طواره .</span> <font color=\"DarkGreen\"><b>[ طَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b>(اِ) بیش . بیخی باشد مانند ماه پروین گویند با ماه پروین یک جا روید لیکن سم قاتل است . (برهان ) (آنندراج ). نام گیاهی که سم الساعة است و تریاق آن انتله است که با وی در یک جا روید. (ابن البیطار در کلمه ٔ انطله ٔ سوداء). به لغت اندلس گیاهی است که نزدیک انتله میروید مانند بیش که با جدوار میروید و آن بیش اندلسی است و سم است و انتله تریاق . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178053, 'طواری', '<span class=\"hlight\">طواری .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طارئة، بمعنی داهیة، حادثه، مصیبت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طواری شهادت </span> ؛ اصناف و الوان آن . رجوع به شرایع کتاب الشهادات شود.<br /></font></div>'),
(178054, 'طواز', '<span class=\"hlight\">طواز.</span> <font color=\"DarkGreen\"><b>[ طَوْ وا ]</font></b> (ع ص ) نرم . <BR><font color=\"Blue\">◄</font> کلانسال از مردم و جز آن . (منتهی الارب ).<br /></font></div>'),
(178055, 'طوازج', '<span class=\"hlight\">طوازج .</span> <font color=\"DarkGreen\"><b>[ طَ زِ ]</font></b> (معرب، اِ) ج ِ طازجة. (منتهی الارب ).<br /></font></div>'),
(178056, 'طواس', '<span class=\"hlight\">طواس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام جایگاهی است . (معجم البلدان ).<br /></font></div>'),
(178057, 'طواس', '<span class=\"hlight\">طواس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) شبی از شبهای محاق . <BR><font color=\"Blue\">◄</font> تشت که بدان آب خورند. (منتهی الارب ).<br /></font></div>'),
(178058, 'طواسیم', '<span class=\"hlight\">طواسیم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ)بعضی از سورتهای قرآن (جمعت علی غیر القیاس و الصواب ان یجمع هو و الطواسین و الحوامیم بذوات و تضاف الی واحد فیقال ذوات طسم و ذوات حم ). (منتهی الارب ).<br /></font></div>'),
(178059, 'طواسین', '<span class=\"hlight\">طواسین .</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (ع اِ) ج ِ طس (ج ِ طس، صواب ذوات طواسین است ). (منتهی الارب ). سورتهای مسمی به طس یعنی الطاء اشارت است به طهارت قدس الهی و السین عبارت است از سنائی لایتناهی ̍ و قیل الطاء طلب روندگان راه و السین سلامت قلوب از ماسوی اﷲ، و یقول ایزد سبحانه و تعالی سوگند یاد کرده به طوبی، درخت بهشت و سدرةالمنتهی . (آنندراج ).<br /></font></div>'),
(178060, 'طواش', '<span class=\"hlight\">طواش .</span> <font color=\"DarkGreen\"><b>[ طَوْ وا ]</font></b> (ص، اِ) اصطلاحی است در بندرلنگه و نواحی بمعنی آنکه معامله و تجارت مروارید کند.<br /></font></div>'),
(178061, 'طواشی', '<span class=\"hlight\">طواشی .</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (ع ص ) خصی . خایه برکنده . اخته . مخنث . (آنندراج ).<br /></font></div>'),
(178062, 'طواشی', '<span class=\"hlight\">طواشی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) والی کرک از قبل ملک ناصر داود از امرای ایوبی . (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠٩</span>).<br /></font></div>'),
(178063, 'طواط', '<span class=\"hlight\">طواط.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص ) مرد شجاع . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) بعربی باشق است و خفاش را نیز نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(178064, 'طواعیة', '<span class=\"hlight\">طواعیة.</span> <font color=\"DarkGreen\"><b>[ طَ ی َ ]</font></b> (ع اِمص ) طاعت و بندگی . گویند: فلان ٌ حسن الطواعیة لک ؛ ای حسن الطاعة. (منتهی الارب ). فرمانبرداری . (دهار) <span class=\"hlight\">:</span> و دیار آن را از جور و ظلم ظلمه ٔ ختائی مصفی چه از طواعیت ِ طواغیت پرستان ملول گشته بودند. (جهانگشای جوینی ). در اظهار ایلی و طواعیت و استظهار بمتابعت و مبایعت بندگی حضرت . (جهانگشای جوینی ). و فرّ دولت روزافزون جباران و متکبران طواغیت را در قبضه ٔ طواعیت و فرمان منقاد. (جهانگشای جوینی ). تامگر بمدارا و مجاملت پیش آید و انقیاد و طواعیت را از تصاریف زمان سایه بان سازد. (جهانگشای جوینی ). این دلیلی تمام است بر قهر و تنفیذ احکام و طواعیت لشکرو انقیاد عسکر. (جهانگشای جوینی ). و در امثله ای که به اطراف میفرستاده است و ایشان را به طواعیت میخوانده چنانکه رسم جبابره بوده است . (جهانگشای جوینی ).<br /></font></div>'),
(178065, 'طواعین', '<span class=\"hlight\">طواعین .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طاعون . (منتهی الارب ). رجوع به طاعون شود.<br /></font></div>'),
(178066, 'طواغ', '<span class=\"hlight\">طواغ .</span> <font color=\"DarkGreen\"><b>[ طَ غِن ْ ]</font></b> (ع اِ) ج ِ طاغوت . (منتهی الارب ).<br /></font></div>'),
(178067, 'طواغون', '<span class=\"hlight\">طواغون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به رومی لحیةالتیس است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178068, 'طواغی', '<span class=\"hlight\">طواغی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص، اِ) ج ِ طاغیة. (منتهی الارب ).<br /></font></div>'),
(178069, 'طواغیت', '<span class=\"hlight\">طواغیت .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طاغوت . (منتهی الارب ). رجوع به طاغوت شود <span class=\"hlight\">:</span> چه از طواعیت طواغیت پرستان ملول گشته بودند. (جهانگشای جوینی ). و فرّ دولت روزافزون جباران و متکبران طواغیت را در قبضه ٔ طواعیت و فرمان منقاد. (جهانگشای جوینی ). <BR><font color=\"Blue\">◄</font> بتخانه ها.<br /></font></div>'),
(178070, 'طواف', '<span class=\"hlight\">طواف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) طوف . طوفان . تطواف . (منتهی الارب ). گرد گشتن . گرد چیزی گشتن . (منتخب اللغات ). گرد برآمدن . (تاج المصادر). گرد بر چیزی برآمدن . دور زدن . گردگردی . گشت . گرد درآمدن . (زوزنی ). شوط. تحلس . گرد چیزی گشتن و گردیدن ... وبا لفظ زدن و داشتن مستعمل . (آنندراج ) <span class=\"hlight\">:</span> <br />نوروز روز خرمی بیعدد بود<br />روز طواف ِ ساقی خورشیدخد بود.<br /> <font color=\"Red\">منوچهری .</font><br />طوافی زد بر آن فیروزه گلشن <br />میان گلشن آبی دید روشن .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> بطرز خاص گرد خانه ٔ کعبه گشتن است . گرد و پیرامون کعبه گشتن . (منتهی الارب ). طواف، از اعمال حج ّ است و در آن رعایت این امور: از حجر اسود آغاز کردن و خانه ٔ کعبه را در طرف چپ قرار دادن و هفت مرتبه دور زدن لازم است <span class=\"hlight\">:</span> <br />گفت نی گفتمش به وقت طواف <br />که دویدی به هروله چو ظلیم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عاشقان اول طواف کعبه ٔ جان کرده اند<br />پس طواف کعبه ٔ تن فرض فرمان دیده اند.<br /> <font color=\"Red\">خاقانی .</font><br />در طواف کعبه ٔ جان ساکنان عرش را<br />چون حلی ّ دلبران در رقص و افغان دیده اند.<br /> <font color=\"Red\">خاقانی .</font><br />و صاحب کشاف اصطلاحات الفنون آرد: طواف در لغت گردش در اطراف چیزی است و شرعاً گردش در اطراف خانه ٔ کعبه است . و صاحب النهایه آرد: و چون طوف خواهد کردن (حجگزار) ابتدا از حجرالاسود کند و چون نزدیک رسد هر دو دست بردارد و حمد کند خدای تعالی را و ثنا گوید و صلوات فرستد بر پیغمبر (ص ) و از خدای تعالی درخواهد تا از وی قبول کند و سنگ را در برگیرد و بوسه بر وی دهد، پس اگر نتواند دست درمالد، پس اگر نتواند به دست اشارت کند و بگوید امانتی ادیتها و میثاقی تعاهدته لتشهد لی بالموافاة اللهم تصدیقاً بکتابک تا به آخر دعا و پس طواف خانه کند هفت بارو در طواف بگوید: اللهم انی اسئلک باسمک الذی یمشی به علی طلل الماء کما یمشی به علی جدد الارض، تا آخر دعا و هر وقت که به دور کعبه میرسی صلوات میفرستی به پیغمبر (ص ) و دعا همی گوئی و چون به پس کعبه رسی و آن مستجار است به پیش رکن یمانی در گردش هفتم دستها بر <font color=\"DarkGreen\"><b>[ دیوار ]</font></b> بگستری و رویت و شکمت بخانه بازنهی و بگوئی اللهم هذا البیت بیتک و العبد عبدک تا آخر دعا.پس اگر نتواند کردن بر وی چیزی نبود. اگر از آنجا بگذشته باشد و پس یادش آید که بدان جایگاه التزام نکرد بر وی نباشد بازپس گشتن و باید که ختم طواف بسنگ سیاه بکند همچنانکه ابتدا از آنجا کرد و مستحب است وی را که همه ٔ رکنها را در بر گیرد و مستحب تر در آنکه مؤکد است در بر گرفتن آن رکن است که حجر در وی است و از پس آن رکن یمانیست که با حال اختیار در بر گرفتن هر دو رکن ترک نکند و اگر کسی را دست بریده باشند سنگ در بر گیرد بدان جایگاه که بریده باشند، پس اگر از ارشنه بریده باشد به دست چپ استلام کُند و باید که طواف خانه در میان مقام و خانه بود و از آنجا تجاوز نکند که اگر از مقام تجاوز کند یا دور شود از وی آن طواف چیزی نبود و باید که طواف بر ساکنی بود نه تیز رود و نه کُند و اگر کسی شش بار کرده باشد و فراموش کرده باشد و بازگشته باشد باید که یکبار دیگر با آن مضاف کند و بر وی چیزی نبود و اگر یادش نیاید تا آنگاه که باز خانه آید بفرماید کسی را تا ازبهر وی یک طواف بکند و اگر یادش آیدکه وی طواف کمتر از هفت بار کرده است و در حال سعی یادش آید باید که بازگردد و طواف تمام بکند. اگر طواف چهار شوط یا بیشتر بوده باشد که اگر کمتر از آن بوده باشد طواف با سر باید گرفتن و پس با سر سعی آید و تمام کند و اگر کسی را در طواف شک اوفتد و نداند که چند کرده است شش یا هفت و وی در حال طواف بود اگر طواف وی فریضه بود با سر گیرد و اگر نافله بود بر آن کمتر بنا کند و بتمامی هفت کند و اگر شک وی پس از آن بود باز وی ننگرد و بر طواف بگذرد و حکم در آنکه کمتر از شش شوط بود چون شک افتد همان حکم است که گفتیم راست در آنکه چون طواف فریضه بود باز سر گیرد وگر طواف نافله بود بر کمتر بنا کند چنانکه گفتیم و اگر هشت باز طواف کند متعمداً بر وی باشد طواف با سر گرفتن و اگر بنسیان کرده شش بار دیگر با آن مضاف بکند و با وی چهار رکعت نماز کنددو رکعت چون از طواف فریضه بپردازد و از آنجا بصفا شود و سعی از میان صفا و مروه بکند و اگر کسی را در گردش هشتم یاد آید پیش از آنکه به رکن برسد که وی هفت بار طواف کرده است طواف ببرد پس اگر یادش نیاید تاآنکه بر رکن برسد که وی هفت بار طواف کرده است طواف ببرد پس اگر یادش نیاید تا آنکه بر رکن بگذرد بتمامی چهارده گردش کند چنانکه در پیش گفتیم و اگر کسی بشک افتد و نداند که هفت بار طواف کرده است یا هشت طواف ببرد و دو رکعت نماز بگزارد و بر وی چیزی نبود و اگر بشک افتد و نداند که شش کرده است یا هفت یا هشت طواف با سر گیرد تا بیقین داند که هفت کرده است و روانبود که دو طواف فریضه در هم پیوندد. و اما در نوافل باکی نبود اگرچه فاضلتر آنست که فصل کند از میان دو طواف بنمازی وگر در حال تقیه بود باکی نبود که در طواف چندانکه خواهد بپیوندد و اگر کسی بیشتر از هفت بار در طواف نافله بگردد فاضلتر آن بود وی را که بر طاق بگردد و بر جفت نگردد مثلاً که بر دو هفت بگردد باید که به سر هفت کند و اگر کسی بی وضو طواف کند یا جنب باشد اگر طواف فریضه باشد وضو بازکند یا غسل کندو طواف باز سر گیرد و اگر نافله بود غسل کند یا وضوو نماز کند و بر وی نبود طواف باز سر گرفتن و اگر کسی در طواف فریضه حدثی کند که وضو را بشکافد و از طواف بعضی کرده باشد اگر از نیمه درگذشته باشد وضو بازکند و باقی طواف تمام کند پس اگر حدث وی پیش از آن بود به نیمه رسد بر وی بود طواف با سر گرفتن و اگر کسی طواف فریضه کرد و نماز کرد و پس پیدا شود وی را که نه بر وضو بوده است وضو بازکند و طواف با سر گیرد واگر طواف نافله باشد وضو بازکند و نماز باز سر گیردو اگر کسی طواف دربرد بدانکه در خانه شود یا بحاجتی آن خویش با آن کسی بشود اگر از نیمه بگذشته باشد برآن بنا کند و اگر از نیمه نگذشته باشد و طواف فریضه بود طواف با سر گیرد و اگر نافله بود بر آن بنا کندبر همه حالی و اگر کسی در طواف بود و وقت نماز درآید که طواف برد و نماز کند و پس طواف تمام کند از آنجا که به وی رسیده بود و همچنین اگر کسی را در حال طواف وقت وتر بر وی تنگ شود و نزدیک فجر باشد یا فجر برآمده باشد وتر کند و نماز فجر کند و پس بنا کند بر طواف و هر آن بیماری که طهارت بتواند داشتن به وی طواف بکنند و از وی طواف نکنند پس اگر بیماری وی از آن بود که طهارت نتواند داشتن منتظر میباشند اگر به شود طواف کند وی بنفس خویش و اگر به نشود و ازبهر وی طواف کنند و وی دو رکعت نماز کند و روا بود وی را و اگر کسی چهار شوط طواف کرده باشد و پس بیمار شود منتظر میباشند یک روز یا دو روز اگر به شود طواف خویش تمام کند و اگر به نشود بفرماید تا کسی ازبهر وی هفت بار طواف کند و ازبهر خویش نیز نیت طواف کند روا بود از وی آن طواف و روا نبود مرد را که طواف کند و در جامه ٔ وی نجاستی بود پس اگر ندانسته باشد و در حال طواف بیند بازگردد و جامه بشوید و پس با سر طواف شود وتمام کند وگر پس از آن که از طواف بپرداخته باشد بداند آن طواف از وی جایز باشد و نماز با جامه پاکیزه کند و مکروه است سخن گفتن در حال طواف الا ذکر خدای تعالی و قرآن خواندن و اگر کسی طواف الزیاره فراموش کند تا آنکه باز خانه آید و اهلش را مواقعه کند واجب آیدبر وی اشتری و باز مکه شدن و قضاء طواف الزیاره کردن و اگر طواف النساء باشد و پس از آنکه باز خانه آمده باشد یادش آید روا بود که کسی را به نیابت خویش فرودآرد تا ازبهر وی طواف کند وگر مرگ وی را دریابد ولی وی ازبهر وی قضاء آن طواف کند و اگر کسی طواف خانه کند روا بود وی را که سعی را تأخیر کند تا پس یک ساعت و روا نبود که با فردا روز افکند و روا نبود از نخست سعی کردن و پس طواف که اگر کسی چنین کند بر وی بود که طواف کند و پس سعی میان مروه و صفا کند و اگر طواف خانه کند باری چند و پس فراموش کند و دربرد و سعی میان صفا و مروه بکند بر وی بود که طواف تمام بکندو بر وی نبود با سر گرفتنش پس اگر یادش آید که وی طواف تمام نکرده بود و بعضی سعی نکرده باشد سعی دربردو بازآید و طواف تمام کند و پس سعی تمام کند و آن کس که حج متمتع کند چون لبیک بحج بزد روا نبود که طواف کند و سعی کند الا از پس آنکه به منا شود و بهر دو موقف بایستد الا که پیری پیر بود که باز مکه نتواند آمدن یا بیماری بود یا زنی بود که از حیض ترسد و منع کند حیض وی را از طواف کردن آنگه باکی نبود ایشان راکه طواف حج و سعی از پیش کند اما مفرد و قارن را باکی نبود که هر دو طواف از پیش آنکه بعرفات آیند بکنند و اما روا نبود طواف زنان کردنش الا پس از آنکه از منا باز گردند با اختیار پس اگر آنجا ضرورتی بود که با مکه نتواند آمدن یا زنی بود که از حیض ترسد روا بود ایشان را طواف زنان از پیش کردن و پس به منا آیندو به موقفها بایستند و همه مناسکها بگذارند آنجا و هر جا که خواهند روند و روا نبود طواف زنان پیش سعی کردن که اگر کسی طواف زنان پیش از سعی کند بر وی بودبا سر گرفتن طواف زنان و اگر فراموش کرده باشد یا سهو افتاده باشد بر وی چیزی نبود و روا بود و باکی نبود که مرد معول خویش بر صاحب خویش بکند بر شمردن طواف و اگر بنفس خویش تولی آن کند فاضلتر بود و اگر هر دو بشک افتند در عدد طواف هر دو با سر گیرند و روا نبود مرد را که طواف کند و کلاهی برطله بر سر وی بود و مستحب است که مردم سیصدوشصت طواف کرده باشد بخانه و اگر نتواند سیصدوشصت شوطبکند پس اگر نتواند چندانکه تواند و خوار آید بر وی طواف کند و اگر کسی نذر کند که وی بهر دو دست و هر دو پای طواف بکند بر وی طواف لازم آید هفت بار ازبهر دو دست و هفت بار از هر دو پای و چون مردم از طواف بپردازد بمقام ابراهیم (ع ) آید و دو رکعت نماز کند و در رکعت اول الحمد و قل هو اﷲ بخواند و در دوم الحمدو قل یا ایها الکافرون . و این هر دو رکعت فریضه است همچنانکه طواف راست و جایگاه مقام هم آنجاست که اکنون هست و اگر کسی دو رکعت فراموش کند یا نه بمقام دربکند و پس یادش آید باید که با مقام شود و دو رکعت کند و روا نبود این دو رکعت کردن بجز در مقام و اگر از مکه بیرون شده باشد و دو رکعت طواف را فراموش کرده باشد و ممکن باشد وی را باز مکه شدن با مکه شود و دو رکعت در مقام کند پس اگر ممکنش نبود با مکه شدن هر کجا که یادش آید نماز کند و بر وی چیزی نبود و اگربجایگاه مقام زحام بود باکی نبود که در پس مقام نماز کند پس اگر نتواند باکی نبود که در برابر مقام نماز کند و وقت دو رکعت طواف آن وقت است که از طواف بپرداخت هر وقت که بود اگر شب بود و اگر روز و اگر از پس نماز دیگر بود و چه از پس نماز بامداد الا که طواف نافله باشد اگر چنین باشد و از پس نماز بامداد طواف کرده باشد یا از پس نماز دیگر نماز و طواف با آنگه افکند که آفتاب برآمده باشد و از نماز دیگر با آنگه افکند که از نماز شام بپرداخته باشد و اگر کسی دو رکعت طواف را فراموش کرده باشد و مرگ وی را دریابد پیش از آنکه طواف کرده باشد بر وی باشد قضا کردن از وی . (از النهایه ٔ شیخ طوسی صص <span class=\"hlight\" dir=\"rtl\">١٥٧</span> - <span class=\"hlight\" dir=\"rtl\">١٦٢</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178071, 'طواف', '<span class=\"hlight\">طواف .</span> <font color=\"DarkGreen\"><b>[ طَوْ وا ]</font></b> (ع ص ) خادم که بنرمی و عنایت خدمت کند. (منتهی الارب ). خادم که بمهربانی خدمت کند. <BR><font color=\"Blue\">◄</font> بسیار طوف کننده . (منتخب اللغات ). طوف زن <span class=\"hlight\">:</span> <br />زهی هوا را طواف و چرخ را مساح <br />که جسم تو ز بخار است و پرّ تو ز ریاح .<br /> <font color=\"Red\">مسعودسعد (در صفت ابر).</font><br /> <BR><font color=\"Blue\">◄</font> دوره گرد. آنکه میوه و بُقول و تره در کوی و برزن گرداند فروختن را <span class=\"hlight\">:</span> <br />مرد سخن ویست بتحقیق و ما همه <br />طواف ریش و سبلت و حمال خایگان .<br /> <font color=\"Red\">سوزنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طواف ِ سرکش </span> ؛ شخصی را گویند که میوه و امثال آن را بر سرگرفته گرد کوچه و بازار بگرداند و بفروشد، و عسس و شبرو را نیز گویند و بمعنی دزد و راهزن هم آمده است .(برهان ).<br /><BR><font color=\"Blue\">◄</font> آب غالب و بسیار. (منتهی الارب ).<br /></font></div>'),
(178072, 'طواف', '<span class=\"hlight\">طواف .</span> <font color=\"DarkGreen\"><b>[ طَوْ وا]</font></b> (اِخ ) ذوالطواف ؛ وائل حضرمی است . (منتهی الارب ).<br /></font></div>'),
(178073, 'طواف', '<span class=\"hlight\">طواف .</span> <font color=\"DarkGreen\"><b>[ طَوْ وا ]</font></b> (اِخ ) ابن غلاق (متوفی بسال <span class=\"hlight\" dir=\"rtl\">٥٨</span> هَ . ق .). از زعماء خوارج ببصره و مردی شجاع و پاکیزه و پرهیزگار بود. وی با هفتاد کس از بنی عبدالقیس بر عبیداﷲبن زیاد خروج کرد، عبیداﷲ کسان بمقاتله ٔ وی گماشت و طواف ظفر یافت و ببصره درآمد و با مردم آنجا ولشکریان بجنگ برخاست و سپس ِ آنکه بیشتر یارانش کشته شدند، مقتول و مصلوب گشت . (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span>).<br /></font></div>'),
(178074, 'طواف آخرالعهد', '<span class=\"hlight\">طواف آخرالعهد.</span> <font color=\"DarkGreen\"><b>[ طَ ف ُ خ ِ رِل ْ ع َ ]</font></b> (ع اِ مرکب ) رجوع به طواف صدر شود.<br /></font></div>'),
(178075, 'طواف الرکن', '<span class=\"hlight\">طواف الرکن .</span> <font color=\"DarkGreen\"><b>[ طَ فُرْ رُ ]</font></b> (ع اِ مرکب ) رجوع به طواف رکن شود.<br /></font></div>'),
(178076, 'طواف القدوم', '<span class=\"hlight\">طواف القدوم .</span> <font color=\"DarkGreen\"><b>[ طَفُل ْ ق ُ ]</font></b> (ع اِ مرکب ) آن را طواف التحیة و طواف اللقاء و طواف اول عهد نیز خوانند. طوافیست که موقع دخول به مکه معمول میدارند. (از کشاف اصطلاحات الفنون ).<br /></font></div>'),
(178077, 'طواف اول عهد', '<span class=\"hlight\">طواف اول عهد.</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ اَوْ وَ ل ِ ع َ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به طواف القدوم شود.<br /></font></div>'),
(178078, 'طواف رکن', '<span class=\"hlight\">طواف رکن .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ رُ ]</font></b> (ترکیب اضافی، اِ مرکب ) طواف الرکن . عبارت از گردش در اطراف خانه ٔ کعبه است در یکی از ایام ماه قربان هفت نوبت . (از کشاف اصطلاحات الفنون ).<br /></font></div>'),
(178079, 'طواف زنان', '<span class=\"hlight\">طواف زنان .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ زَ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به طواف نساء شود.<br /></font></div>'),
(178080, 'طواف زیارت', '<span class=\"hlight\">طواف زیارت .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ رَ ]</font></b> (ترکیب اضافی، اِ مرکب ) طواف الزیارة. آن را طواف فرض نیز گویند، عبارت از گردش اطراف خانه ٔ کعبه است در یکی از ایام ماه قربان هفت نوبت . این طواف یکی از ارکان حج بشمار میرود. (از کشاف اصطلاحات الفنون ). و رجوع به طواف شود.<br /></font></div>'),
(178081, 'طواف صدر', '<span class=\"hlight\">طواف صدر.</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ ص َ ]</font></b> (ترکیب اضافی، اِ مرکب ) طواف بازگشتن از حج . (مهذب الاسماء) و آن را طواف وداع و طواف آخرالعهد نیز گویند، عبارت از طواف خانه ٔ کعبه است در موقع بازگشت از آنجا و این طواف سنت باشد. و رجوع به حج و رجوع به طواف شود. (از کشاف اصطلاحات الفنون ).<br /></font></div>'),
(178082, 'طواف عمره', '<span class=\"hlight\">طواف عمره .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ ع ُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ترکیب اضافی، اِ مرکب ) گرد خانه ٔ کعبه گشتن هفت بار است بشرایط مخصوص و آن یکی از اعمال عمره است . رجوع به حج و عمره و طواف شود.<br /></font></div>'),
(178083, 'طواف فرض', '<span class=\"hlight\">طواف فرض .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ ف َ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به طواف زیارت و حج شود.<br /></font></div>'),
(178084, 'طواف فریضه', '<span class=\"hlight\">طواف فریضه .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ ف َ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به طواف و طواف زیارت شود.<br /></font></div>'),
(178085, 'طواف قدوم', '<span class=\"hlight\">طواف قدوم .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ ق ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به طواف القدوم و حج شود.<br /></font></div>'),
(178086, 'طواف لقا', '<span class=\"hlight\">طواف لقا.</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ ل ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) طواف اللقاء. رجوع به طواف القدوم شود.<br /></font></div>'),
(178087, 'طواف وداع', '<span class=\"hlight\">طواف وداع .</span> <font color=\"DarkGreen\"><b>[ طَ ف ِ وِ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به طواف صدر شود.<br /></font></div>'),
(178088, 'طوافه', '<span class=\"hlight\">طوافه .</span> <font color=\"DarkGreen\"><b>[ طَوْ وا ف َ ]</font></b> (ع اِ) گربه . ج، طوافات . (مهذب الاسماء).<br /></font></div>'),
(178089, 'طواق', '<span class=\"hlight\">طواق .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) اطواق است که به هندی سیندهی و تاری نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(178090, 'طواقیطوس', '<span class=\"hlight\">طواقیطوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) قرطم بری است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178091, 'طوال', '<span class=\"hlight\">طوال .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع ص ) دراز. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوال الدهر</span> . رجوع به طَوال الدهر ذیل طَوال شود.<br /></font></div>'),
(178092, 'طوال', '<span class=\"hlight\">طوال .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص، اِ) ج ِ طویل . (منتهی الارب ). رجوع به طویل شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سبع طوال </span> ؛ هفت سوره ٔ درازتر قرآن از اول و آن بقره و آل عمران و نساء و مائده و انعام و اعراف و انفال و توبه باشد چنانکه رسول (ص ) گفت اعطیت مکان التوریة السبع الطوال .<br /></font></div>'),
(178093, 'طوال', '<span class=\"hlight\">طوال .</span> <font color=\"DarkGreen\"><b>[ طَوْ وا ]</font></b> (ع ص ) نیک دراز. (منتهی الارب ). سخت دراز. بسیار دراز. (منتخب اللغات ).<br /></font></div>'),
(178094, 'طوال', '<span class=\"hlight\">طوال .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) غایت زمانه . گویند: لااتیک طوال الدهر (و یضم ) و یقال طال طوالک و طیالک (بالکسر) ایضاً؛ ای عمرک او مکثک او غیبتک . (منتهی الارب ). عمر. <BR><font color=\"Blue\">◄</font> درنگ . (منتخب اللغات ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوال الدار</span> ؛ صحن دراز. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوال الدهر</span> ؛ هرگز. هیچوقت .<br /></font></div>'),
(178095, 'طوالب', '<span class=\"hlight\">طوالب .</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ ]</font></b> (ع ص، اِ) ج ِ طالب .<br /></font></div>'),
(178096, 'طوالة', '<span class=\"hlight\">طوالة.</span> <font color=\"DarkGreen\"><b>[ طَوْ وا ل َ ]</font></b> (ع ص ) تأنیث طَوّال . (معجم البلدان ).<br /></font></div>'),
(178097, 'طوالة', '<span class=\"hlight\">طوالة.</span> <font color=\"DarkGreen\"><b>[ طُ ل َ ]</font></b> (اِخ ) موضعی است . <BR><font color=\"Blue\">◄</font> چاهی است . (منتهی الارب ). موضعی است ببرقان و درآن چاهی است . قال ثعلب فی قول الحطیئة <span class=\"hlight\">:</span> <br />و فی کل ممسی لیلة و معرس <br />خیال یوافی الرکب من ام معبد<br />فحیاک ودّ ما هداک لفتیة<br />و خوص باعلی ذی طوالة هجّد.<br />نصر گوید: طواله چاهی است در دیار فزارة ازآن بنی مرة و غطفان . شماخ گوید <span class=\"hlight\">:</span> <br />کلا یومی طوالةوصل اروی <br />ظنون ٌ آن مطّرِح الظنون .<br /> <font color=\"Red\">(از معجم البلدان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">یوم طوالة</span> ؛ از ایام عرب است . (معجم البلدان ).<br /></font></div>'),
(178098, 'طوالش', '<span class=\"hlight\">طوالش .</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ ]</font></b> (اِ)ج ِ طالش فارسی به قاعده ٔ عربی . رجوع به طالش شود.<br /></font></div>'),
(178099, 'طوالش', '<span class=\"hlight\">طوالش .</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ ]</font></b>(اِخ ) نام یکی از شهرستانهای استان یکم کشور. مشخصات آن بطور خلاصه بشرح زیر است : حدود از طرف شمال به بخش آستارا از شهرستان اردبیل، از جنوب به دهستان ماسوله از شهرستان فومن، از خاور به دریای خزر، از جنوب خاوری به دهستان کسگرات شهر فومن، از باختر به خطالرأس سلسله ٔ جبال البرز که مقسم المیاه آن حد طبیعی این شهرستان با شهرستان خلخال محسوب است . عرض و طول جغرافیائی : طول <span class=\"hlight\" dir=\"rtl\">٤٨</span> درجه و <span class=\"hlight\" dir=\"rtl\">٣٠</span> دقیقه الی <span class=\"hlight\" dir=\"rtl\">٤٩</span> درجه و <span class=\"hlight\" dir=\"rtl\">١٤</span> دقیقه، عرض <span class=\"hlight\" dir=\"rtl\">٣٧</span> درجه و <span class=\"hlight\" dir=\"rtl\">١٨</span> دقیقه الی <span class=\"hlight\" dir=\"rtl\">٣٨</span> درجه و <span class=\"hlight\" dir=\"rtl\">١٦</span> دقیقه . مساحت شهرستان در حدود چهارهزار کیلومتر مربع است . آب و هوای شهرستان طوالش مانند سایر نقاط گیلان مرطوب معتدل و بارندگی آن بسیار ولی بواسطه ٔ مجاورت باکوهستان و وجود استخر و مزارع برنج هوای آن ناسالم است و به این مناسبت اکثر سکنه تابستان به ییلاقات کوچ می نمایند. وضعیت کلی طبیعی : شهرستان طوالش از نظر طبیعی به دو قسمت مشخص تقسیم میگردد: <span class=\"hlight\" dir=\"rtl\">١</span> - جلگه : این قسمت در کنار دریا واقع است، عرض آن در جنوب شهرستان در حدود <span class=\"hlight\" dir=\"rtl\">١٥</span>هزار و در قسمت شمال <span class=\"hlight\" dir=\"rtl\">٣</span>هزار گز است یعنی هر قدر که از جنوب به شمال نزدیک میشود جلگه کم عرض تر میگردد. این منطقه ٔ جنگل زار بمرور زمان تبدیل به مزارع برنجکاری شده فعلاً بطور تقریب نصف اراضی جنگل و نصف دیگر مزرعه است .قسمت دوم کوهستانی : سلسله ٔ جبال البرز در این قسمت موازی با کرانه ٔ دریا و تقریباً شمالی جنوبی است . فاصله ٔ تقریبی خطالرأس اصلی سلسله با دریا در جنوب شهرستان تقریباً <span class=\"hlight\" dir=\"rtl\">٥٠</span>هزار و در قسمت شمال <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزار گز مربع است . کوهستان مزبور تا ارتفاع <span class=\"hlight\" dir=\"rtl\">١٢٠٠</span> متر بطور تقریب پوشیده از اشجار و جنگل و انبوه است که جز از راههای محدود در خطالقعر دره ها عبور از نقاط دیگر غیرممکن و از ارتفاع <span class=\"hlight\" dir=\"rtl\">١٢٠٠</span> گز به بعد از فشردگی اشجار کم شده بتدریج جنگل تمام میشود بنابراین قسمت های مرتفع سلسله ٔ جبال عاری از جنگل و علت اصلی آن برودت زیاد است . ارتفاع متوسط قلل این کوهستان از <span class=\"hlight\" dir=\"rtl\">٢</span>هزار و پانصد تا <span class=\"hlight\" dir=\"rtl\">٣</span>هزار گز است . رودخانه : رودخانه های شهرستان از جنوب بشمال بشرح زیر است و عموماً از ارتفاعات مذکور سرچشمه گرفته، در قسمت جلگه پس از مشروب نمودن قراء شهرستان بدریای خزر منتهی می گردند و عبارتند از رودخانه های ماسال، شاندرمن، چاف رود، شفارود، دنیاچال، دیکاسرا، کیلاسرا، ناورود، گرگانرود، هره دشت، خطبه سرا، شیرآباد، حویق، چوبر، لمر. طویل ترین و پرآبترین رودخانه ٔ شهرستان شفارود و گرگان رود است .<br />سازمان اداری شهرستان : در زمانهای قدیم شهرستان طوالش به خمسه ٔ طوالش معروف بود، منظور از خمسه همان بلوک پنجگانه ٔ گرگانرود، اسالم طالشدولاب، شاندرمن، ماسال میباشند ولی فعلاً طبق سازمان وزارت کشور شهرستان طوالش از <span class=\"hlight\" dir=\"rtl\">٣</span> بخش بنام :<br /><span class=\"hlight\" dir=\"rtl\">١</span> - بخش مرکزی (دهستانهای گرگانرود شمالی و جنوبی لیسار هره دشت و اسالم )<br /><span class=\"hlight\" dir=\"rtl\">٢</span> - بخش رضوانده (دهستانهای پسره سر، میانده، خشابر، گیل دولاب )<br /><span class=\"hlight\" dir=\"rtl\">٣</span> - بخش ماسال شاندرمن (دهستانهای شاندرمن ماسال ) تشکیل گردیده است . جمیع قراء شهرستان <span class=\"hlight\" dir=\"rtl\">١٥٥</span> آبادی بزرگ و کوچک و جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">٧٨</span>هزار تن است . زبان و مذهب : زبان مادری سکنه ٔ شهرستان به استثنای دهستان گیل دولاب که گیلگی است طالشی (زبان طالشی یکی از شعب فارسی است ) ولی چون از طرفی بخلخال و از طرف دیگر به گیلان متصل است و با سکنه ٔ آن حدود معاشرت دارند بزبان ترکی و گیلکی آشنا هستند. مرکز شهرستان : طبق سازمان شفارود مرکز شهرستان بوده ولی چون خارج از راه شوسه و کنار دریا واقع شده چندی مرکز شهرستان به آبادی پونل و اخیراً به هشت پر منتقل شده است . راه شوسه ٔ اسفالته ٔ بندر انزلی به آستارا تقریباً از وسط بخشهای رضوانده و مرکزی عبور می نماید، فقط بخش ماسال شاندرمن فاقد راه شوسه است .<br />محصولات : اراضی جلگه ٔ شهرستان طوالش مانند سایر نقاط گیلان است ولی از حیث برداشت محصولات بعلت ناسالم بودن هوا و در نتیجه ییلاق رفتن سکنه جز برنج و مختصر ابریشم محصولات دیگری ندارد. ولی نگاهداری اغنام و احشام قابل ملاحظه است و همه سال در فصل تابستان گله داران به ییلاق کوچ مینمایند. در اغلب آبادیهای شهرستان فقط چند تن برای آبیاری برنج و نگهبانی اماکن باقی میمانند.<br />ییلاق سکنه تقریباً سرچشمه ٔ رودخانه های مذکوربوده و تقریباً از ارتفاع <span class=\"hlight\" dir=\"rtl\">١٢٠٠</span> متر بالا است، چشمه سارهای کوهستانی ییلاقات بهمان نام قراء قشلاقی نامیده میشود و برخی از قراء ییلاقی مانند آق اولر در گرگانرودو آق مسجد در طالشدولاب و غیره در زمستان چند خانوار سکنه دارند. در آبادیهای ساحلی زیر شعبات شیلات دائر است و در فصول مقتضی به صید ماهی میپردازند: شفارود، دنیاچال، سیاه چال، گرگانرود، هره دشت، خطبه سرا، حویق، چلمه سرا. مراکز بازرگانی : در شهرستان طوالش مانند سایر نواحی گیلان همه هفته در روزهای معین در نقطه ای بازار عمومی دایر میگردد و زارعین محصولات خود را در آن بازار بفروش رسانیده و احتیاجات خودشان را از پیله وران سیار خریداری مینمایند. روزهای شنبه بازار ماسال و سه شنبه بازار پره سر، چهارشنبه بازار (بین رضوانده و ارده جان )، پنجشنبه بازار (بین سید شرفشاه و رضوانده )، جمعه بازار شاندرمن و بعلاوه در هشت پر، ناورودلیسار، خطبه سرا و حویق بازار دائمی وجود دارد. بخش مرکزی شهرستان طوالش از دهستان های گرگانرود، اسالم، لیسار، هره دشت تشکیل گردیده است . این بخش در قسمت شمالی شهرستان واقع شده . جمع قراء بخش <span class=\"hlight\" dir=\"rtl\">٤٨</span> آبادی بزرگ وکوچک و جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">٤٠</span>هزار تن است . خلاصه ٔ اطلاعات درباره ٔ بخشها و دهستانهای این شهرستان در جای خود شرح داده شده است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(178100, 'طوالع', '<span class=\"hlight\">طوالع.</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ ]</font></b> (ع ص، اِ) ج ِ طالع و طالعة. (آنندراج ) (غیاث ). <BR><font color=\"Blue\">◄</font> صاحب کشاف اصطلاحات الفنون گوید: طوالع عبارت از درجه ٔ برابری است که به ازاء مطالع است چنانکه یاد کردیم . <BR><font color=\"Blue\">◄</font> طوالع در اصطلاح صوفیه اول چیزی که پیداشود از تجلیات اسماء الهیه بر باطن بنده و آراسته گرداند اخلاق او را به نور باطن . کذا فی کشف اللغات .<br /></font></div>'),
(178101, 'طوالق', '<span class=\"hlight\">طوالق .</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ ]</font></b> (ع ص، اِ) ج ِ طالقة. زن های وارسته از قید نکاح . رجوع به طالقه شود.<br /></font></div>'),
(178102, 'طواله', '<span class=\"hlight\">طواله .</span><font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِخ ) دهی از دهستان درجزین بخش رزن شهرستان همدان در <span class=\"hlight\" dir=\"rtl\">٢٧</span>هزار گزی جنوب قصبه ٔ رزن و <span class=\"hlight\" dir=\"rtl\">١١</span> هزارگزی خاور شوسه ٔ رزن به همدان . جلگه و سردسیر و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٢٢٧</span> تن سکنه . آب آن از قنات، محصول آنجا غلات و حبوبات و صیفی و لبنیات و شغل اهالی زراعت و گله داری و راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(178103, 'طوالیش', '<span class=\"hlight\">طوالیش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) طوالش . رجوع به طوالش (اِ) و رجوع به طالش شود.<br /></font></div>'),
(178104, 'طوامس', '<span class=\"hlight\">طوامس .</span> <font color=\"DarkGreen\"><b>[ طَ م ِ ]</font></b> (ع ص، اِ) ج ِ طامس . (منتهی الارب ).<br /></font></div>'),
(178105, 'طوامیر', '<span class=\"hlight\">طوامیر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طومار. (منتهی الارب ). رجوع به طومار شود <span class=\"hlight\">:</span> و تقریر عشر عشیر آن بتحریر طوامیر تیسیر نپذیرد. (جهانگشای جوینی ).<br /></font></div>'),
(178106, 'طوان', '<span class=\"hlight\">طوان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ظاهراً نام محلی بوده بحوالی بغداد. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٨</span>).<br /></font></div>'),
(178107, 'طوانة', '<span class=\"hlight\">طوانة.</span> <font color=\"DarkGreen\"><b>[ طُ ن َ ]</font></b> (اِخ ) شهری است بمرز مصیصة. یزیدبن معاویه گوید <span class=\"hlight\">:</span> <br />و ماابالی بما لاقت جموعهم <br />یوم الطوانة من حمی و من موم <br />اذا اتکأت ُ علی الانماط مرتفعا<br />بدیر مران عندی أم کلثوم .<br /> <font color=\"Red\">(از معجم البلدان ).</font><br />از بلاد روم است .<br /></font></div>'),
(178108, 'طواویس', '<span class=\"hlight\">طواویس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طاووس . (منتهی الارب ). رجوع به طاووس شود.<br /></font></div>'),
(178109, 'طواویس', '<span class=\"hlight\">طواویس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام دیهی است ببخارا. (منتهی الارب ). شهرکیست از ماوراءالنهر به بخارا بر سرحد سغد و اندر وی هر سالی یک روز بازار است که خلق بسیار اندروی گرد آیند. (حدود العالم ). نام ناحیتی از اعمال بخارا میان آن و سمرقند و آن شهری است بسیاربستان و آبهای جاری و نعمت فراوان و آن را قندز و جامعی است وداخل حائط بخار است . (معجم البلدان ). قریه ای است درهشت فرسنگی بخارا. (سمعانی ). و رجوع به طوایس شود.<br /></font></div>'),
(178110, 'طواویسی', '<span class=\"hlight\">طواویسی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ص نسبی ) منسوب به طواویس که قریه ای است در هشت فرسنگی بخارا. (سمعانی ).<br /></font></div>'),
(178111, 'طوایح', '<span class=\"hlight\">طوایح .</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ ]</font></b> (ع اِ) رجوع به طوائح شود.<br /></font></div>'),
(178112, 'طوایس', '<span class=\"hlight\">طوایس .</span> <font color=\"DarkGreen\"><b>[ طَ ی ِ ]</font></b> (اِخ ) طواویس . شهرکی است نام او ارقود است و در وی مردمانی بوده اند با نعمت و تجمل و از تجمل هر کسی در خانه یکی و دو طاوس می داشته اند و عرب پیش از این طاوس ها ندیده بوده اند چون در بخارا طاوس بسیار دیدند آن دیه را ذات الطوایس نام کردند و نام اصلی او برخاست و بعد از آن ذات را نیز رها کردند و طوایس گفتند و در وی مسجدجامع است و شارستانی عظیم دارد و در ایام قدیم آنجا بازار بوده است و بفصل تیرماه ده روز رسم آن بازار چنان بوده است که هرچه آخریان معیوب بودی از برده و ستور و دیگر آخریان با عیب همه بدین بازار فروختندی و بازار رد کردن امکان و سامان نبودی و هیچ شرطی نپذیرفتی نه فروشنده و نه خرنده را و هر سالی بدین بازار ده هزار کس بیشتر حاضر آمدی از بازرگانان و اصحاب حوائج چنانکه از فرغانه و چاچ و جایهای دیگر بیامدندی و با منفعت بسیار بازگشتندی و بدین سبب اهل این دیه توانگر بوده اند و سبب توانگری ایشان کشاورزی نبوده است و بر شاهراه سمرقند است و تا بخارا هفت فرسنگ است . (تاریخ بخارا ص <span class=\"hlight\" dir=\"rtl\">١٣</span> و<span class=\"hlight\" dir=\"rtl\">١٤</span>). و رجوع به طواویس شود.<br /></font></div>'),
(178113, 'طوایف', '<span class=\"hlight\">طوایف .</span> <font color=\"DarkGreen\"><b>[ طَی ِ ]</font></b> (ع اِ) طوائف . ج ِ طایفه . رجوع به طایفه شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوایف پشتکوه </span> ؛ از ایلات کرد ایران و از طوایف متعدد ترکیب یافته است . جمعیت آن چهل هزار خانوار که محل سکونتشان جنوب کرمانشاه، رودخانه ٔ سیمره دزفول، بین النهرین است . در منطقه ٔ این طوایف جنگلهای بلوط انبوه یافت میشود. و رجوع به پشتکوه شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوایف فارس </span> ؛ ییلاق آنها در کوه نارو میانه و بلوک میمند و فرابا و صیمکان و میمند است . زندگانی آنها از گوسفند و بز و خر است . و رجوع به فارس شود.<br /></font></div>'),
(178114, 'طوب', '<span class=\"hlight\">طوب .</span> (اِخ ) (قصر الَ ...) موضعی است به افریقیه . (معجم البلدان ).<br /></font></div>'),
(178115, 'طوب', '<span class=\"hlight\">طوب .</span> (اِخ ) موضعی است درگذرگاه اردن که یفتاح بدانجا گریخت ... و دور نیست که همان طیبه حوران حالیه باشد. (قاموس کتاب مقدس ).<br /></font></div>'),
(178116, 'طوب', '<span class=\"hlight\">طوب .</span> (ع اِ) خشت پخته . (منتخب اللغات ) (مهذب الاسماء). خشت پخته به لغت اهل مصر. (منتهی الارب ). به لغت اهل مصر آجر است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178117, 'طوب', '<span class=\"hlight\">طوب .</span> (معرب، اِ) توپ . گوی . رجوع به دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٣</span> و کلمه ٔ طوبه شود.<br /></font></div>'),
(178118, 'طوبا', '<span class=\"hlight\">طوبا.</span> (اِخ ) طوبی . درختی در بهشت . رجوع به طوبا شود <span class=\"hlight\">:</span> <br />پشت این مشت مقلد کی شدی خم از رکوع <br />گرنه در جنت امید سایه ٔ طوباستی .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(178119, 'طوبار', '<span class=\"hlight\">طوبار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) از شاگردان مورولو اسپانیائی که در قرن <span class=\"hlight\" dir=\"rtl\">١٧</span> م . میزیسته و در نقاشی از طبیعت تقلید میکرده است . رجوع به الحلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٣</span> شود.<br /></font></div>'),
(178120, 'طوبار', '<span class=\"hlight\">طوبار.</span> (اِ) نوعی از ماهی . رجوع به طوبان و دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span> شود.<br /></font></div>'),
(178121, 'طوبال', '<span class=\"hlight\">طوبال .</span> (ع اِ) میش نر را طوبال نامند. (فهرست مخزن الادویه ). و لایقال للکبش طوبال . (منتهی الارب ) (مهذب الاسماء).<br /></font></div>'),
(178122, 'طوبال', '<span class=\"hlight\">طوبال .</span> (اِخ ) ابن یافث بن نوح . کسی که بسرزمین اسپانیا درآمد و بدین مناسبت آنجا اندلس نام یافت . (الحلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣</span> از نفح الطیب ).<br /></font></div>'),
(178123, 'طوبالات', '<span class=\"hlight\">طوبالات .</span> (ع اِ) ج ِ طوبالة. (منتهی الارب ).<br /></font></div>'),
(178124, 'طوبالة', '<span class=\"hlight\">طوبالة.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ع اِ) میش . ج، طوبالات (و لایقال للکبش طوبال ). (منتهی الارب ).<br /></font></div>'),
(178125, 'طوبالیس', '<span class=\"hlight\">طوبالیس .</span> (معرب، اِ) اشترخار. شترخار. خارشتر. مغیلان . خار مغیلان . طرثوث . (از دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>).<br /></font></div>'),
(178126, 'طوبان', '<span class=\"hlight\">طوبان .</span> (اِخ ) حصنی است از اعمال حمص یا حماة. (معجم البلدان ).<br /></font></div>'),
(178127, 'طوبان', '<span class=\"hlight\">طوبان .</span> (اِ) نوعی از ماهی (قزوینی نوعی از طوبار آورده است ). (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>).<br /></font></div>'),
(178128, 'طوبانیة', '<span class=\"hlight\">طوبانیة.</span> <font color=\"DarkGreen\"><b>[ نی ی َ ]</font></b>(اِخ ) شهری است از نواحی فلسطین . (معجم البلدان ).<br /></font></div>'),
(178129, 'طوبة', '<span class=\"hlight\">طوبة.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ع اِ) نام ماهیست در تاریخ قبط قدیم . (کشاف اصطلاحات الفنون ).<br /></font></div>'),
(178130, 'طوبة', '<span class=\"hlight\">طوبة.</span> <font color=\"DarkGreen\"><b>[ طَ ب َ ]</font></b> (معرب، اِ) کلمه ای است ماخوذ از لغت توپو اسپانیولی که در آن زبان تنها بمعنی موش کور است اما در عربی که آن را با «ب » نوشته اند بمعنی مطلق موش است . رجوع به دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span> شود.<br /></font></div>'),
(178131, 'طوبة', '<span class=\"hlight\">طوبة.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ع اِ) تأنیث طوب، آجر. لغتی است شامی و گمان میکنم رومی باشد . (المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span>). <BR><font color=\"Blue\">◄</font> کلوخه ٔ کنده شده از زمین که سخت و خشک باشد: جاء لعندی و هو مقطع الحوائج منتوف اللحیة و هو یدق علی صدره بطوبتین، از یادداشتی که درین باره آمده است معلوم میشود که طبقه ٔ عامی عرب هنگامی که دچار اندوه و مصیبتی میشوند دو کلوخ سخت و خشک را که از زمین برمیگیرند بر سینه ٔ خود میزنند (مخصوصاً آجر). <BR><font color=\"Blue\">◄</font> انجیرهای خشک متراکم و توده شده که بشکل مربع آنها را تهیه کنند، این توده ها شبیه به آجر میباشند و آنها را خشک میکنند و بقدری سفت میشوند که برای شکستن آنها باید تبر بکار برد. <BR><font color=\"Blue\">◄</font> نانی که از انجیر خشک سازند. <BR><font color=\"Blue\">◄</font> این کلمه معنی اصلی خود را از دست داده و آن را بمعنی انجیر سبز وتازه نیز بکار میبرند. <BR><font color=\"Blue\">◄</font> (معرب، اِ) توپ بازی (در ترکی ). طابه هوا، لعب الطابة. ج، طابة. گوی «بازی ». گلوله ٔ «بازی ». گوی چوگان . توپ بزرگ چوگان .بازی چوگان . <BR><font color=\"Blue\">◄</font> گلوله ٔ نخ . کلاف . (همچنین طابة خیط). کلمه ٔ طوبة در معنی گوی و توپ گمان میکنم از کلمه ٔ ترکی طوب (توپ ) گرفته شده که بمعنی هر گلوله ٔ گردی است که بدان بازی کنند. (از دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>).<br /></font></div>'),
(178132, 'طوبجی', '<span class=\"hlight\">طوبجی .</span> (معرب، اِ) (ترکی : طبجی ) توپچی . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>).<br /></font></div>'),
(178133, 'طوبرطوق', '<span class=\"hlight\">طوبرطوق .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) جعده ٔ بری است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178134, 'طوبی', '<span class=\"hlight\">طوبی .</span> <font color=\"DarkGreen\"><b>[ با ]</font></b> (ع ص ) ج ِ طیبة. (منتهی الارب ).<br /></font></div>'),
(178135, 'طوبی', '<span class=\"hlight\">طوبی .</span> <font color=\"DarkGreen\"><b>[ با <span class=\"hlight\" dir=\"rtl\">/</span> بی ]</font></b> (اِخ ) نام درختی است در بهشت . (منتهی الارب ) (مهذب الاسماء). نام درختی است در بهشت که بهر خانه از اهل جنت شاخی از آن باشد و میوه های گوناگون و خوشبوئی از آن حاصل آید... و هندیان آن را کلپ برچهه خوانند. (غیاث ) (آنندراج ) <span class=\"hlight\">:</span> <br />بباغی در او سایه ٔ شاخ طوبی <br />بباغی در او چشمه ٔ آب کوثر.<br /> <font color=\"Red\">فرخی .</font><br />درختی ساختم مانند طوبی خرم و زیبا<br />که هر لفظیش دیناریست هر معنیش خرمائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />سایه و مایه که دولت را و نعمت را از اوست <br />از درخت طوبی و از چشمه ٔ کوثر گرفت .<br /> <font color=\"Red\">مسعودسعد.</font><br />نهاد گوئی رضوان بشاهراهش بر<br />میان هر دو سه گامی نهالی از طوبی .<br /> <font color=\"Red\">ابوالفرج رونی .</font><br />چو طعنه هاست که اطفال باغ می نزنند<br />به گونه گونه بلاغت بلوغ طوبی را.<br /> <font color=\"Red\">انوری .</font><br />تحفه ٔ بزم اوست مریم وار<br />هرچه طوبی به نوبر افشاند.<br /> <font color=\"Red\">خاقانی .</font><br />فیض هزار کوثر و زین ابر یک سرشک <br />برگ هزار طوبی و زین باغ یک گیا.<br /> <font color=\"Red\">خاقانی .</font><br />آن کس که یافت طوبی و طرف ریاض خلد<br />طرفه بود که چشم به طرفا برافکند.<br /> <font color=\"Red\">خاقانی .</font><br />بر آتش هرکه مدح تو خواند <br />جز طوبی و ضیمران ندیده ست .<br /> <font color=\"Red\">خاقانی .</font><br />هر جا که عدل سایه کند رخت دین بنه <br />کاین سایبان ز طوبی اخضر نکوتر است .<br /> <font color=\"Red\">خاقانی .</font><br />بی منت نامیه درختت <br />افراخته تر ز شاخ طوبی .<br /> <font color=\"Red\">سیف اسفرنگی .</font><br />صاحب آنندراج گوید: طوبی قامت و طوبی قد از اسمای محبوب است . خواجه آصفی راست <span class=\"hlight\">:</span> <br />ز طوبی قامتان بس باشدم سرو خرامانم <br />چرا قمری صفت هر لحظه بر شاخی دگر باشم .<br />و نیز آصفی راست <span class=\"hlight\">:</span> <br />آصفی طوبی قدان را نشئه ای میشد بلند<br />التماس جرعه ای زآن مجلس عالی کنم .<br /><BR><font color=\"Blue\">◄</font> بهشت به لغت هندیه . (منتهی الارب ) (المعرب ). نامی است بهشت را. (مهذب الاسماء).<br /></font></div>'),
(178136, 'طوبی', '<span class=\"hlight\">طوبی .</span> <font color=\"DarkGreen\"><b>[ با ]</font></b> (ع ص ) تأنیث اَطیب . پاک . پاکیزه . <BR><font color=\"Blue\">◄</font> رام . <BR><font color=\"Blue\">◄</font> حُسنی ̍. نیکو. <BR><font color=\"Blue\">◄</font> برگزیده . <BR><font color=\"Blue\">◄</font> سُخ . خوش . (منتخب اللغات ) <span class=\"hlight\">:</span> <br />نبید پیش من آمد بشاطی برکه <br />بخنده گفتم طوبی لمن یری عکه .<br /> <font color=\"Red\">منوچهری .</font><br />طوبی بر آن قلم که بعنوان نامه بر<br />بوحرب بختیار محمد کند همی .<br /> <font color=\"Red\">منوچهری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوبی لَک َ، طوبی لَک ِ</span> ؛ سُخ تو. خنک تو را. خوش بحال تو. خوشا بحال تو.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوبی لکم، طوبی لکن </span> ؛ سُخ شما را. خنک شما را. خوش بحال شما. خوشا بحال شما.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوبی لنا</span> ؛ خنک ما را. خوش بحال ما. خوشا به حال ما.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوبی لهم، طوبی لهن </span> ؛ خنک آنان را. خوش بحال آنان . خوشا بحال آنان <span class=\"hlight\">:</span> <br />بخوان تو آیه ٔ طوبی لهم ز حسن مآب .<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوبی لی </span> ؛ خنک مرا.خوش به حال من . خوشا بحال من .<br /></font></div>'),
(178137, 'طوبی', '<span class=\"hlight\">طوبی .</span> (ص نسبی ) منسوب به قصر الطوب . (سمعانی ).<br /></font></div>'),
(178138, 'طوبیا', '<span class=\"hlight\">طوبیا.</span> (اِخ ) غلام عمونی که پیشوای مخالفان بنای هیکل ثانی بود. چون وی از دختران اعیان و اشراف در سلک ازدواج خود میداشت بدان لحاظ همواره با بزرگان یهود مراسله و مکاتبه همی نمود و نحمیا را تهدید میکرد و در غیاب نحمیا منزل و مقام خود را در یکی از غرفات هیکل قرار داد و چون نحمیا مراجعت کرد وی را از آنجا رانده منزل وی را تطهیر فرمود. (قاموس کتاب مقدس ).<br /></font></div>'),
(178139, 'طوبیا', '<span class=\"hlight\">طوبیا.</span> (اِخ ) لاوی که یهوشافاط برای تعلیم به یهودا ببلاد یهودا فرستاد. (قاموس کتاب مقدس ).<br /></font></div>'),
(178140, 'طوبیا', '<span class=\"hlight\">طوبیا.</span> (اِخ ) شخصی که اولاده اش از بابل به ازروبابل مراجعت نمود اما نتوانست نسب خود را معین نماید که اسرائیلی میباشند زیرا که نسب نامه ٔ خانواده ٔ آبای خود را گم کرده بودند. (از قاموس کتاب مقدس ).<br /></font></div>'),
(178141, 'طوبیقا', '<span class=\"hlight\">طوبیقا.</span> (معرب، اِ) جدل . از یونانی توپیکو (موضع) گرفته شده و مبحث ششم از منطق ارسطو در جدل است . حاجی خلیفه در کشف الظنون آرد: کتاب جدل که در لغت یونان به طوبیقا موسوم است دارای هشت مقاله است . این کتاب تألیف ارسطاطالیس است که اسحاق بن حنین آن را بسریانی نقل کرده و آنگاه یحیی بن عدی کتاب مزبور را از سریانی بعربی برگردانده است ... رجوع به کتاب الجدل در کشف الظنون شود. ابن ابی اصیبعة آرد: جدل عبارت از قوانینی است که بدان گفتارها و کیفیت سؤال و جواب جدلی را بیازمایند و خلاصه، قوانین اموری است که بدان صناعت جدل را تنظیم کنند وبسبب آن قوانین افعال مناظر کاملتر و بهتر و نافذترشود و آن در عربی عبارت از کتاب مواضع جدلی است و بیونانی آن را طوبیقا خوانند. (از عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٩</span>). و رجوع به جدل شود.<br /></font></div>'),
(178142, 'طوبین', '<span class=\"hlight\">طوبین .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) از کلمه ٔ اسپانیائی توپو. موش کور. ج، طوابین . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>).<br /></font></div>'),
(178143, 'طوتو', '<span class=\"hlight\">طوتو.</span> <font color=\"DarkGreen\"><b>[ طُ <span class=\"hlight\" dir=\"rtl\">/</span> طَ ]</font></b> (ترکی، اِ) در ترکی بمعنی آنست که کسی بخانه ٔ حاکم برای مال گذاری و غیره، پسر و غیره را بگذارد و آن را یوغمال نیز گویند و در هندی به فتح اول خوانند بواو مجهول . (بهار عجم ).<br /></font></div>'),
(178144, 'طوثرس', '<span class=\"hlight\">طوثرس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام کسی است که جالینوس کتاب نبض صغیر را بر وی و دیگر متعلمان عنوان کرده و منظور جالینوس از رساله ٔ مزبور وصف اموری است که متعلمان در نبض بدان نیازمندند. ابن ابی اصیبعه این کلمه را بصورت طوثرس آورده ولی قفطی در ذیل کتب ششگانه ای که قبطیان متوالیاً آنها را قرائت میکنند آرد: کتاب <font color=\"DarkGreen\"><b>[ الی ]</font></b> طوثرن فی النبض نقل حنین . رجوع به عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩١</span> و تاریخ الحکماء قفطی ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span> شود.<br /></font></div>'),
(178145, 'طوثرن', '<span class=\"hlight\">طوثرن .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) رجوع به طوثرس شود.<br /></font></div>'),
(178146, 'طوج', '<span class=\"hlight\">طوج .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) لغتی در تور. حمزه ٔ اصفهانی یکی از فرزندان فریدون را که در کتب ماتور مینویسند طوج آورده است : و قسم فریدون مملکته بین ثلثة اولاده و هم سلم و طوج و ایرج . (سنی ملوک الارض حمزه ٔ اصفهانی ).<br /></font></div>'),
(178147, 'طوجان جیرفت', '<span class=\"hlight\">طوجان جیرفت .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِخ ) دهی از دهستان سبزواران بخش مرکزی شهرستان جیرفت در <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی جنوب باختری سبزواران و یک هزارگزی راه سبزواران به بم . جلگه و گرمسیر و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٣٨٢</span> تن سکنه . آب آن از رودخانه ٔ هلیل . محصول آنجا غلات . شغل اهالی زراعت . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(178148, 'طوجول', '<span class=\"hlight\">طوجول .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) تیر. ناوک . خدنگ . بیلک . سهم . چیزی که به شکل تیر باشد. ج، طواجل . (از دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>).<br /></font></div>'),
(178149, 'طوح', '<span class=\"hlight\">طوح .</span> <font color=\"DarkGreen\"><b>[ طَ وَ ]</font></b> (ع ص ) نیة طوح ؛ قصد دور و دراز. (منتهی الارب ).<br /></font></div>'),
(178150, 'طوح', '<span class=\"hlight\">طوح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) هلاک گردیدن یا قریب بهلاک شدن . (منتهی الارب ). هلاک شدن یا مشرف بر هلاک شدن . (منتخب اللغات ). هلاک شدن و هلاک کردن . (زوزنی ). <BR><font color=\"Blue\">◄</font> رفتن . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> ساقط گردیدن در جهان . (منتهی الارب ). در زمین افتادن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> سرگشته شدن . (منتهی الارب ). سرگردان و حیران شدن . (منتخب اللغات ).<br /></font></div>'),
(178151, 'طوخ', '<span class=\"hlight\">طوخ .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) چهارده موضع است بمصر. (منتهی الارب ) (منتخب اللغات ).دهی است در صعید مصر، غربی ِ نیل . (معجم البلدان ).<br /></font></div>'),
(178152, 'طوخ', '<span class=\"hlight\">طوخ .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) طوخ الخیل ؛ قریه ٔ دیگری است به صعید غربی نیل و بدان طوخ بیت یمون گویند و طوة نیز خوانند. (معجم البلدان ).<br /></font></div>'),
(178153, 'طوخ', '<span class=\"hlight\">طوخ .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی است به حوف غربی و آن را طوخ مزید گویند. (معجم البلدان ).<br /></font></div>'),
(178154, 'طوخ', '<span class=\"hlight\">طوخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) تهمت کردن کسی را به قول یا به فعل . (منتهی الارب ). تهمت کردن به چیزی بد از گفتار و کردار. (منتخب اللغات ).<br /></font></div>'),
(178155, 'طوخیطس', '<span class=\"hlight\">طوخیطس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) اذخر بابلی . رجوع به اذخر شود.<br /></font></div>'),
(178156, 'طود', '<span class=\"hlight\">طود.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) کوه . (منتهی الارب ). کوه بزرگ . (منتهی الارب ) (دهار) (منتخب اللغات ) (مهذب الاسماء). کوه کلان . (غیاث ). ج، اطواد، طودة <span class=\"hlight\">:</span> اگرچه در رزانت وقار طود اسم بود لطمه ٔ موج خشم او از بحر خضم حکایت میکرد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٦٩</span>). <BR><font color=\"Blue\">◄</font> ریگ توده ٔ بلندبرآمده . (منتهی الارب ). توده ٔ بلند از ریگ . (منتخب اللغات ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ابن الطود</span> ؛ خرسنگ که از کوه برافتد. (منتهی الارب ).<br /></font></div>'),
(178157, 'طود', '<span class=\"hlight\">طود.</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) پاییدن . قرار گرفتن . (منتهی الارب ).<br /></font></div>'),
(178158, 'طود', '<span class=\"hlight\">طود.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام کوهی که مشرف است بر عرفه بجانب صنعاء کشیده شود و بسبب بلندی بدان سراة نیز نام دهند و سراة هر چیز پشت آن چیز باشد. (معجم البلدان ).<br /></font></div>'),
(178159, 'طود', '<span class=\"hlight\">طود.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) شهرکی به صعید اعلی، فرازِ قوص و فرودِ اسوان دارای مناظر و بستانها، آن را امیر درباس الکردی معروف به احول، به روزگار الملک الناصر صلاح الدین یوسف بن ایوب بساخته است . (معجم البلدان ).<br /></font></div>'),
(178160, 'طودماج', '<span class=\"hlight\">طودماج .</span> (اِ) تتماج . توتماج . لاکچه . لاخشه . لخشک . جون عمه .<br /></font></div>'),
(178161, 'طودی', '<span class=\"hlight\">طودی .</span> (اِخ ) ده کوچکیست از دهستان سنگان بخش میرجاوه ٔ شهرستان زاهدان در <span class=\"hlight\" dir=\"rtl\">٥٥</span> هزارگزی جنوب میرجاوه کنار راه فرعی میرجاوه به خاش با <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(178162, 'طودیش', '<span class=\"hlight\">طودیش .</span> (اِخ ) نخستین پادشاه گتهای غربی در اسپانیا که بسال <span class=\"hlight\" dir=\"rtl\">٥٣١</span> م . در آن کشور بسلطنت رسیده است . (از الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span>).<br /></font></div>'),
(178163, 'طور', '<span class=\"hlight\">طور.</span> (اِ) دام . شبکه (یعنی جامه ای از رسن یا طناب مشبک ). شبکه که بدان ماهی گیرند. شبکه ٔ صیاد. طور ماهیگیران . بیاحه . دام ماهیگیری . <BR><font color=\"Blue\">◄</font> قسمی پارچه ٔ دیداری .<br /></font></div>'),
(178164, 'طور', '<span class=\"hlight\">طور.</span> (ع اِ) پیرامون سرای . (منتهی الارب ). فنای خانه . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> حد و نهایت چیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کوه . (منتهی الارب ) (منتخب اللغات ) (دهار).<br /></font></div>'),
(178165, 'طور', '<span class=\"hlight\">طور.</span> (اِخ ) سوره ٔ پنجاه ودومین از قرآن کریم، مکیه و آن چهل ونه آیت است، پس از ذاریات و پیش از نجم .<br /></font></div>'),
(178166, 'طور', '<span class=\"hlight\">طور.</span> (اِخ ) از حدود و نواحی بیضاست به فارس به چهارفرسنگی بیضا بر سر راه شیراز به سمیرم . (فارسنامه ٔ ابن البلخی چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span> و <span class=\"hlight\" dir=\"rtl\">١٦١</span>).<br /></font></div>'),
(178167, 'طور', '<span class=\"hlight\">طور.</span> (اِخ ) دهی جزء دهستان فراهان پائین بخش فرمهین شهرستان اراک در <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی جنوب باختری فرمهین و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی راه مالرو عمومی . کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٣٢٣</span> تن سکنه . آب آن از قنات و چشمه و محصول آنجا غلات و انگور و میوه جات . شغل اهالی زراعت و گله داری و گلیم و جاجیم بافی . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(178168, 'طور', '<span class=\"hlight\">طور.</span> (اِخ ) کوهی که موسی بر آن بمناجات شد. نام کوهی که موسی علیه السلام بر آن بمناجات شدی . طور سیناء در شبه جزیره ٔ سیناء . رجوع به طور سینا شود <span class=\"hlight\">:</span> <br />هرکه در مصر شود یوسف چاهی نشود<br />هرکه بر طور شود موسی عمران نشود.<br /> <font color=\"Red\">سنائی .</font><br />آب پیراهن سنگ ار بشود نیست عجب <br />که دم آتش طور از ید بیضا شنوند.<br /> <font color=\"Red\">خاقانی .</font><br />نشگفت اگر ز هوش شود موسی آن زمان <br />کایزد به طور نور تجلی برافکند.<br /> <font color=\"Red\">خاقانی .</font><br />مهر و مه گوئی بباغ از طورنور آورده اند<br />بر سر شروانشه موسی بنان افشانده اند.<br /> <font color=\"Red\">خاقانی .</font><br />بر اسب چون بدیدش با رمح گفت گردون <br />دیدم پس محمد موسی و طور و ثعبان .<br /> <font color=\"Red\">الملک المعظم پیغو (از لباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤</span>).</font><br />چه دهر پرتو رایت بدید بیش نکرد<br />حدیث آتش موسی که تافت از کُه طور<br /> <font color=\"Red\">رضی الدین نیشابوری (از لباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٦</span>).</font><br />آنچه بخشند چه بسیار و چه کم <br />نیست برگشتن از آن طور کرم .<br /> <font color=\"Red\">جامی .</font><br />چو رسی به طور سینا ارنی نگفته بگذر<br />که نیرزد این تمنا بجواب لن ترانی . ؟<br />کوهی است نزدیک ابله (صحیح : ایلة) منسوب بسوی سینا و سینین و کوهی است بشام منسوب به سینا به قولی . (منتهی الارب ). و دیگر کوه طور است که ایزدتعالی با موسی علیه السلام مناجات کرد و آنجا آتش و نور دید که بر اثر آن برفت و پیغامبری یافت و تا بر سر قله شدن ششهزار و ششصد و شش پایه بر باید شدن مانند نردبان از سنگ خارا و بر آنجا درختی است و کنیسه ها یکی ازآن ِ ایلیای پیغمبر علیه السلام و دیگر ازآن ِ موسی پیغامبر علیه السلام از رخام ساخته و سقف صنوبر و درهاء آهنین و روی به صحیفه های رصاص کرده و این کنیسه ها بدان جایگاه است که حق تعالی با موسی پیغامبر علیه السلام سخن گفت و ششهزار صومعه و دویست ازآن ِ رهبان و مقیمان از آنجا بوده است و بوقتی خراج ملک مصر بنام و رسم ایشان بکرده بود و اکنون هفتاد صومعه ازآن ِ زهاد و عباد مانده است و مقیمان مانده اند و همه کوه درخت بادام و میوه ها و سروستانست و بر دامن کوه دیری هست ازآن ِ ترسایان سخت بتکلف و درخت علیق آنک موسی پیغامبر علیه السلام از آن نور دید هنوز آنجا بجای است . (مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٤٦٨</span>). یاقوت گوید: طور، در کلام عربی بمعنی کوه است و برخی از اهل لغت گویند، جبل را طور گویند مگر آنکه بر آن درخت رسته باشد و گویند بسبب نام بطوربن اسماعیل مالک آن طور نامیده شده و باء از اول کلمه بعلت سنگینی افتاده است وجمیع بلاد شام را طور خوانند و شواهد آن در کلمه ٔ طرآن گذشت و برخی از دانشمندان گویند که طور، آن کوه مشرف بر نابلس است و بدین سبب سامریان حج ّ آن کنند و یهودیان را در وی اعتقادی عظیم است و پندارند که ابراهیم پیغامبر آنجا بذکر اسماعیل فرمان یافت و ایشان از توراة ذبیح را اسحاق علیه السلام دانند... و آن نزدیک مصر بجایگاهی است بنام مدین . (از معجم البلدان ). <BR><font color=\"Blue\">◄</font> و نیز طور، کوهی است که از صالحین خالی نبود و سنگریزه ٔ آن چون شکسته شود صورت درخت علیق برآید و بر آن بود دومین خطاب بموسی علیه السلام هنگام برون آمدن وی از مصر بجانب بنی اسرائیل و بزبان نبط هر کوهی را طور گویند و چون بر آن درخت یا گیاه بود طور سینا خوانند. (معجم البلدان ). کوهی است بقدس بطرف راست مسجد و کوهی دیگر است جانب قبله ٔ مسجد و در آنست قبر هارون (ع ). (منتهی الارب ). رجوع به طور زیتا شود. <BR><font color=\"Blue\">◄</font> و نیز طور کوهی است مشرف بر طبریه ٔاردن و میان آن دو چهار فرسنگ است و بر فراز آن کنشتی است بزرگ و استوار... و الملک المعظم عیسی بن ملک العادل ابی بکربن ایوب قلعه ٔ محکمی آنجا بساخت و مال بسیار بر آن خرج کرد و بغایت استوار گردانید. چون فرنگیان بسال <span class=\"hlight\" dir=\"rtl\">٦١٥</span> هَ . ق . عزم تسخیر بیت المقدس کردند آن کنیسه نیز ویران گشت و تا بدین روزگار ویرانست . (معجم البلدان ). <BR><font color=\"Blue\">◄</font> و نیز طور کوهی است نزدیک شهری مشتمل بر قرای بسیار بهمین نام بمصر جنوبی و کوه فاران نزدیک آن واقع است . (معجم البلدان ).<br /></font></div>'),
(178169, 'طور', '<span class=\"hlight\">طور.</span> (اِخ ) شهری است بنواحی نصیبین . (منتهی الارب ). رجوع به طور عبدین شود.<br /></font></div>'),
(178170, 'طور', '<span class=\"hlight\">طور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) طوران . نزدیک شدن بچیزی . (منتهی الارب ): لا اطور به ؛ ای لا اقربه . (تاج المصادر). <BR><font color=\"Blue\">◄</font> پیرامون چیزی گردیدن . (منتهی الارب ). گرد چیزی گردیدن . (منتخب اللغات ).<br /></font></div>'),
(178171, 'طور', '<span class=\"hlight\">طور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) یک بار. ج، اطوار. قال اﷲ تعالی : خلقکم اطواراً ؛ قال الاخفش ای طَوراً نطفةً و طَوراً عَلقةً و طوراً مُضغةً. (منتهی الارب ). کرت . بار. <BR><font color=\"Blue\">◄</font> مساوی چیزی .مقابل چیزی . (منتهی الارب ). آنچه بر طرف چیزی یا مقابل چیزی باشد. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> حد و قدر و نهایت چیز. گویند: فلان عدا طوره ؛ ای حدّه . (منتهی الارب ). عدا طوره ؛ از حد بگذشت . (مهذب الاسماء). مقدار. حد فاصل میان دو چیز. (منتهی الارب ). فاصله ٔ میان دو چیز. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> نوع و صنف، گویند: الناس اطواراً؛ ای اصناف مختلفون . (منتهی الارب ). حال . گونه . حالت . چگونگی . سان . طرز. روش . نوع . قاعده و قانون . (برهان ): بطوری . بطوری که . بدین طور.<br /></font></div>'),
(178172, 'طور ثابور', '<span class=\"hlight\">طور ثابور.</span> (اِخ ) رجوع به ثابور شود.<br /></font></div>'),
(178173, 'طور زیتا', '<span class=\"hlight\">طور زیتا.</span> <font color=\"DarkGreen\"><b>[ رِ زَ ]</font></b> (اِخ ) کوهی است نزدیک رأس عین نزدیک پل خابور و بر فراز آن درخت زیتونی است که از باران آب خورد و بدین جهت آن کوه را طور زیتا نامیده اند... و از فضایل بیت المقدس آنست که طور زیتا بدانجاست و آنجا هفتادهزار پیغمبر از گرسنگی و برهنگی و شپش بمرده اند و آن مشرف بر مسجد اقصی است و میان آن دو وادی جهنم واقع است و از آنجا عیسی بن مریم بر آسمان شده و صراط نیز بر آن استوار است و عمربن خطاب بدانجا نماز گذارده و قبور انبیا هم آنجاست . بشاری گوید: جبل زیتا مشرف بر مسجد اقصی و شرقی وادی شلوان است که وادی جهنم باشد. (معجم البلدان ).<br /></font></div>'),
(178174, 'طور سینا', '<span class=\"hlight\">طور سینا.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) کوهی که موسی علیه السلام بدان بمناجات شد. نام کوهی که موسی بر آن با خدای تعالی بمناجات شدی . رجوع به طور شود <span class=\"hlight\">:</span> <br />بازآمدند و گفتند آن امتان موسی (موشا)<br />کایزد بُد آن نه موسی (موشا) بر کوه طور سینا.<br /><font color=\"Red\">دقیقی .</font><br />کوه طور سینا از مشاهیر جبال جهان است و ذکرش در قرآن بسیار آمده و موسی پیغمبر (ع ) در آنجا نور الهی را بر سردرخت دید و شرف تکلیم یافت . (نزهة القلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٩٨</span>). سیناء، بکسر سین و بفتح آن نیز آمده و در هر دو صورت ممدود. کوهی است . ابواسحاق گوید: سیناء حجاره ای است ... آن کوهی است نزدیک ایلة و نزدیک آن شهرکی است که بروزگار پیغمبر اکرم و بسال نهم از هجرت فتح شد... جوهری گوید: طور سیناء کوهی است بشام و کلمه ٔ طور در این مورد بکلمه ٔ سیناء بمعنی درخت اضافه گردیده و بهمین گونه است طور سینین . و اخفش گوید: سینین درختی است و مفرد آن سینینه باشد. (معجم البلدان ).<br /></font></div>'),
(178175, 'طور سینین', '<span class=\"hlight\">طور سینین .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) رجوع به طور و طور سینا شود.<br /></font></div>'),
(178176, 'طور عبدین', '<span class=\"hlight\">طور عبدین .</span> <font color=\"DarkGreen\"><b>[ رِ ع َ ]</font></b> (اِخ ) شهرکی است از اعمال نصیبین به کمره ٔ کوهی مشرف بر آن و متصل بکوه جودی و آن قصبه ٔ (مرکز) شهری است بدانجای . شاعر گوید <span class=\"hlight\">:</span> <br />ملک الحضر و الفرات الی دجَ<br />َلة طرّاً و الطور من عبدین .<br /> <font color=\"Red\">(معجم البلدان ).</font><br />طور عبدین را امروزه طور عابدین خوانند. (فرهنگ ایران باستان پورداود ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span>). آب هرماس چشمه ای است بحدود نصیبین از طور عبدین برمیخیزد و مقدار دو آسیا آب میدهد. (نزهة القلوب ص <span class=\"hlight\" dir=\"rtl\">٢٢٦</span>).<br /></font></div>'),
(178177, 'طور هارون', '<span class=\"hlight\">طور هارون .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) کوهی که هارون برادر موسی بدانجا مدفونست . (برهان ). کوهیست بلند در جنوب بیت المقدس و قبر هارون بدانجاست . وی یا برادر خود موسی بر فراز آن شد و بازنگشت از اینرو بنی اسرائیل موسی را بقتل وی متهم ساختند و وی خدا را بخواند تا تابوت او را مردم در آسمان بر فراز قله ٔ آن کوه بدیدند و سپس از دیده ٔ ایشان نهان گشت ... طور هارون بدین سبب خوانندش . (معجم البلدان ).<br /></font></div>'),
(178178, 'طوران', '<span class=\"hlight\">طوران .</span> (اِخ ) ناحیتی از سند که قصبه ٔ آن قصدار است و آن شهری باشد کوچک و آن ناحیه را روستاها و دیهها و شهرهاست . (معجم البلدان ). ناحیتی است بسند با نعمت و چهارپای بسیار و اندر وی مسلمانند و گبرکان بسیار و مستقرپادشاه طوران کیجکانان است و محالی و مندان و شوره از شهرهای ناحیت طوران است . (حدود العالم )... آن قسمت بین مکران و سیستان و غزنه از مملکت سند که در نقشه های قدیم آن را طوران نویسند و اکنون جزء بلوچستان انگلیس و ایالت غزنین افغانستان واقع شده است . (تاریخ سیستان حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span>).<br /></font></div>'),
(178179, 'طوران', '<span class=\"hlight\">طوران .</span> (اِخ ) ناحیه ٔ مداین راگویند. زهرةبن حویه گوید در ایام فتوح <span class=\"hlight\">:</span> <br />الا بلغا عنی اباحفص آیة<br />و قولا له قول الکمی المغاور<br />بانا اثرنا ان ّ طوران کلهم <br />لدی مظلم یهفو بحمر الصراصر<br />قریناهم ُ عند اللقاء بَواتراً<br />تلالا و یسبو عند تلک الحرائر.<br /><font color=\"Red\">(از معجم البلدان ).</font><br /></font></div>'),
(178180, 'طوران', '<span class=\"hlight\">طوران .</span> (اِخ ) از دیههای هرات . (معجم البلدان ).<br /></font></div>'),
(178181, 'طوران', '<span class=\"hlight\">طوران .</span> <font color=\"DarkGreen\"><b>[ طَ وَ ]</font></b> (ع مص ) طور. پیرامون چیزی گردیدن . (منتهی الارب ). گرد بر چیزی گشتن . <BR><font color=\"Blue\">◄</font> نزدیک شدن آب . (زوزنی ).<br /></font></div>'),
(178182, 'طورانی', '<span class=\"hlight\">طورانی .</span> <font color=\"DarkGreen\"><b>[نی ی ]</font></b> (ع ص ) مرغ و کبوتر وحشی . <BR><font color=\"Blue\">◄</font> (اِ) مردم، یقال : ما بها طورانی ؛ ای احدٌ. (منتهی الارب ).<br /></font></div>'),
(178183, 'طوربد', '<span class=\"hlight\">طوربد.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) به سریانی تربد است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178184, 'طورخوانان', '<span class=\"hlight\">طورخوانان .</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا]</font></b> (اِ) جامه ها به کاغذ پیچیده . (نظام قاری ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>).<br /></font></div>'),
(178185, 'طوردان', '<span class=\"hlight\">طوردان .</span> (اِ) اسب و استر و شتربزرگ بارکش و رونده را گویند. (برهان ) (آنندراج ).<br /></font></div>'),
(178186, 'طوردزلاس', '<span class=\"hlight\">طوردزلاس .</span> <font color=\"DarkGreen\"><b>[ زِل ْ لا ]</font></b> (اِخ ) شهری به اسپانیا . (الحلل السندسیه ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178187, 'طورزن', '<span class=\"hlight\">طورزن .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) دهی از دهستان پائین بخش حومه ٔ شهرستان اردستان در <span class=\"hlight\" dir=\"rtl\">٤٥</span> هزارگزی خاور اردستان و<span class=\"hlight\" dir=\"rtl\">٣٥</span> هزارگزی شمال خاوری راه شهراب به نائین . جلگه، معتدل با<span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و خشکبار و پشم و روغن . شغل اهالی زراعت . راه آن فرعی است . دبستان دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(178188, 'طورس', '<span class=\"hlight\">طورس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی جبن است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178189, 'طورسرا', '<span class=\"hlight\">طورسرا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی سکر است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178190, 'طورسون', '<span class=\"hlight\">طورسون .</span> (اِخ ) ابن مراد. بر شرح وقایه ٔ صدرالشریعه ٔ ثانی تعلیقه ای دارد.<br /></font></div>'),
(178191, 'طورسیقوس', '<span class=\"hlight\">طورسیقوس .</span> (اِخ ) طرسیقوس است که نام زاهدی و حکیمی و پادشاهی بوده از نصاری . (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br />کنم در پیش طورسیقوس اعظم <br />ز روح القدس و ابن واب مدارا.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(178192, 'طورغای', '<span class=\"hlight\">طورغای .</span> (اِخ ) نام ایالتی بشمال ایالت «سیردریا» بساحل شرقی سیحون در حوالی بحیره ٔ خوارزم (دریاچه ٔ آرال حالیه ). (جهانگشای جوینی چ اروپا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span> و <span class=\"hlight\" dir=\"rtl\">١٠١</span>).<br /></font></div>'),
(178193, 'طورغوزیان', '<span class=\"hlight\">طورغوزیان .</span> (اِخ )از حکمرانان مجاور خطه ٔ فرمانروائی دولت عثمانی هنگام سلطنت شاهرخ و سلطان محمد اول، پادشاه عثمانی . (از سعدی تا جامی ص <span class=\"hlight\" dir=\"rtl\">٤٤٠</span>). نیز رجوع به تورغوذیان شود.<br /></font></div>'),
(178194, 'طورغولیطر', '<span class=\"hlight\">طورغولیطر.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) بسریانی و یا رومی مرد ابیض است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178195, 'طورق', '<span class=\"hlight\">طورق .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b>(اِخ ) نام دیهی از نواحی ابیورد. (معجم البلدان ).<br /></font></div>'),
(178196, 'طورقوزآباد', '<span class=\"hlight\">طورقوزآباد.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی جزء دهستان غار بخش ری شهرستان تهران در <span class=\"hlight\" dir=\"rtl\">٢٠٠٠</span> گزی جنوب باختر شهرری و <span class=\"hlight\" dir=\"rtl\">٥٠٠٠</span> گزی باختر راه شوسه ٔ تهران به قم . جلگه و معتدل با <span class=\"hlight\" dir=\"rtl\">٧٧٩</span> تن سکنه . آب آن از قنات و رودخانه ٔ کن و محصول آنجا غلات و صیفی و یونجه و چغندرقند. شغل اهالی زراعت . راه از طریق شریف آباد ماشین رو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(178197, 'طورمان بالا', '<span class=\"hlight\">طورمان بالا.</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (اِخ )دهی از دهستان القورات بخش حومه ٔ شهرستان بیرجند در<span class=\"hlight\" dir=\"rtl\">٤٠</span> هزارگزی شمال بیرجند. کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">٢٣٤</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و میوه جات و شغل اهالی زراعت . راه آن مالرو است . مزرعه ٔ طورمان پائین جزء این ده است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(178198, 'طورمس', '<span class=\"hlight\">طورمس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نهری است به اسپانیا واقع در شهر طلمنکه که پلی عظیم به سبک رومی بر روی آن بنیان نهاده شده است . رجوع به الحلل السندسیه ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥١</span> و <span class=\"hlight\" dir=\"rtl\">٥٣</span> شود.<br /></font></div>'),
(178199, 'طورناشولی', '<span class=\"hlight\">طورناشولی .</span> (معرب، اِ) رجوع به طرنشولی و طرنشول شود: و یسمی باللطینی العامی عندنا طورناشولی . (از دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢</span> از ابن بیطار و ابن جلجل ).<br /></font></div>'),
(178200, 'طورنشولی', '<span class=\"hlight\">طورنشولی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) رقیب الشمس . صامرتوما.<br /></font></div>'),
(178201, 'طوره', '<span class=\"hlight\">طوره .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) دهی جزء دهستان کزاز پائین بخش سربند شهرستان اراک در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی شمال باختری آستانه سر راه شوسه ٔ اراک به ملایر. کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">١٣٦٦</span> تن سکنه . آب آن از رودخانه ٔ نهرمیان . محصولات آنجا غلات و بنشن و چغندرقند و انگور و میوه و قلمستان . شغل اهالی آنجا زراعت و قالیچه بافی . راه آن اتومبیل رو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(178202, 'طوروس', '<span class=\"hlight\">طوروس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (جبل ...). (ابن البیطار در کلمه ٔ افسنتین ). کوهی است .<br /></font></div>'),
(178203, 'طوروس', '<span class=\"hlight\">طوروس .</span> (معرب، اِ) به یونانی جبن است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178204, 'طورک', '<span class=\"hlight\">طورک .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) بگفته ٔ صاحب برهان و آنندراج نام یکی از سرداران ضحاک، ولی پیداست که آن را به اشتباه بر وزن خوبک ضبط کرده اند. رجوع به طُوُرگ شود.<br /></font></div>'),
(178205, 'طورک', '<span class=\"hlight\">طورک .</span><font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِخ ) نام کوچه ای به بلخ . (معجم البلدان ).<br /></font></div>'),
(178206, 'طورگ', '<span class=\"hlight\">طورگ .</span> <font color=\"DarkGreen\"><b>[ طُ وُ ]</font></b> (اِخ ) نام میراسفهسالاری بود ازآن ِ ضحاک . اسدی گوید <span class=\"hlight\">:</span> <br />شد آن لشکرگشن پیش طورگ <br />رمان چون رمه ٔ میش در پیش گرگ .<br /> <font color=\"Red\">(لغت نامه ٔ اسدی ).</font><br />این تعریف اشتباه است، چه اسدی در گرشاسبنامه طورک را پسرشیداسب و نواده ٔ جم دانسته و بشرح زندگانی وی پرداخته و شعر فوق نیز از آنجاست و ممکن نیست که یک تن رادر کتابی نواده ٔ جم بداند و هم آن کس را در لغت نامه ٔ خویش اسفهسالار ضحاک معرفی کند و پیداست که این قسمت بعدها بمتن لغت نامه اضافه گشته و از اینکه مؤلف نیز در استشهاد بشعر خویش بلفظ «اسدی گوید» افاده ٔ مقصود کند، الحاقی بودن آن آشکار گردد چه قدما در این گونه موارد با عبارت : «من گویم » از گفته ٔ خویش شاهد آوردندی . نکته ٔ دیگر اینکه ضبط شعر گرشاسب نامه بعنوان شاهد در لغت نامه هر گونه تصور تعدد شخصین را مرتفعمیسازد. باری چنانکه گفتیم طورگ جد سوم گرشاسب و نواده ٔ جمشید و شرح سلسله ٔ نسب بنقل از مجمل التواریخ و القصص چنین است ... فرزند جمشید ثور بود از پریچهره دختر زابل شاه ... و از ثور شیداسب بزاد و طورگ پسر شیداسب بود و شم پسر طورگ و اثرط پسر شم ... پس گرشاسف از اثرط بزاد... در گرشاسبنامه داستان طورگ به اختصار چنین آمده است <span class=\"hlight\">:</span> <br />بر اورنگ بنشست شیداسب شاد<br />به شاهی درِداد و بخشش گشاد<br />یکی پورش آمد ز تخمی بزرگ <br />به رسم نیا کرد نامش تورگ .<br />چو شه سرکش و گرد و دهساله گشت <br />بزور از نیا وز پدر درگذشت <br />یلی شد که در خَم ّ خام کمند<br />گسستی سر زنده پیلان ز بند<br />کس آهنگ پرتاب او درنیافت <br />ز گردان کسی گرز او برنتافت <br />ز بالای مه نیزه بفراشتی <br />ز پهنای کُه خشت بگذاشتی ...<br />پدرْش از پی کینه روزی پگاه <br />همی خواست بردن بکابل سپاه <br />چو دید او گرفت آرزو ساختن <br />که من با تو آیم بکین تاختن <br />پدر گفت کاین رای پدرام نیست <br />تو خردی تو را رزم هنگام نیست <br />هنوزت نگشته ست گهواره تنگ <br />چگونه کشی از بر باره تنگ ...<br />پرآژنگ رخ داد پاسخ تورگ <br />که گر کوچکم هست کارم بزرگ ...<br />اگر کوچکم کار مردان کنم <br />ببینی چو آهنگ میدان کنم <br />مر آن گرگ را مرگ به از رمه <br />که بی خورد ماند میان رمه ...<br />پدر شادمان شد گرفتش به بر<br />زره خواست با تَرک و رویین سپر...<br />درفشی ز شیر سیه پیکرش <br />همائی ز یاقوت و زر بر سرش <br />بدو داد و کردش سپهدار نو<br />بخواهید گفت اسب سالار نو<br />غو کوس بر چرخ مه برکشید<br />به پیکار دشمن سپه برکشید<br />وز آن روی کابل شه از مرغ و مای <br />جهان کرد پر گرد رزم آزمای <br />بُد او را یکی پور نامش سرند<br />که زخمش ز پولاد کردی پرند<br />درفش و سپه دادش و پیل و ساز<br />فرستادش ازبهر کین پیش باز<br />دو لشکر چو در هم رسیدند تنگ <br />رده برکشیدند و برخاست جنگ ...<br />چو شد سخت بر مرد پیکار کار<br />روان گشت از تیغ چون نار نار<br />به پیش پدر شد تورگ دلیر<br />بپرسید کای بر هنر گشته چیر<br />سرند از میان سران سپاه <br />کجا جای دارد بدین رزمگاه <br />کدامست از جنگیان چپ وراست <br />سلیحش چه چیز و درفشش کجاست <br />که گر هست بر زین کُه ِ کینه کش <br />هم اکنون کشان آرمش زیر کش <br />بدو گفت آنک بقلب اندرون <br />ستاده ست و برکتف رومی ستون ...<br />دلاور ز گفت ِ پدر چون هزبر<br />برآهیخت گلرنگ تازنده ببر<br />چنان تاخت ارغون پولادسم <br />که در گنبد از گرد شه ماه گم ...<br />بهر جمله خیلی فکندی نگون <br />بهر زخم جوئی براندی ز خون ...<br />شد آن لشکر گشن پیش تورگ <br />رمان چون رمه ٔ میش در پیش گرگ ...<br />سرند از کران دید دیوی بجوش <br />بزیر اژدهائی پلنگینه پوش <br />ز آسیبش افتاده بر پیل پیل <br />سواران رمان گشته بر میل میل <br />برانگیخت که پیکر بادپای <br />بگرز گران اندر آمد ز جای <br />چنان زَدْش بر تَرک گرز ای شگفت <br />که گرزش ز ترک آتش اندرگرفت <br />تورگ دلاور نشد هیچ کند<br />عقاب نبردی برانگیخت تند<br />بیاویخت از بارویش گرز جنگ <br />بزد بر کمربندش از باد چنگ <br />ز زین بر ربود و همی تاختش <br />به پیش پدر برد و بنداختش <br />چنین گفت کاین هدیه ٔ کابلی <br />نگه دار ار این کودک زابلی ...<br />سپه چون سپهبد نگون یافتند<br />هزیمت سوی راه بشتافتند...<br />تورگ و دلیران زابل به دم <br />برفتند چندانکه سود اسب سم ...<br />چو پیروز گشتند از آن رزمگاه <br />سوی زابل اندر گرفتند راه ...<br />چو بگذشت ازین کار یک چند گاه <br />به شیداسب بر تیره شد هور و ماه <br />گرفت از پسش پادشاهی تورگ <br />سرافراز شد بر شهان بزرگ <br />یکی پورش آمد بخوبی چو جم <br />نهاد آن دلارای را نام شم <br />زشم زآن سپس اسرت آمد پدید<br />وزین هر دو شاهی به اسرت رسید...<br />چو بختش به هرکار منشور داد<br />سپهرش یکی نامور پور داد<br />بدان پورش آرام بفزود و کام <br />گرانمایه را کرد گرشاسب نام .<br /></font></div>'),
(178207, 'طورگ', '<span class=\"hlight\">طورگ .</span> <font color=\"DarkGreen\"><b>[ طُ وُ ]</font></b> (اِخ ) نام یکی از پهلوانان افراسیاب تورانی، آنکه پذیره ٔ زنگه ٔ شاوران رفت . فردوسی در این باره گوید <span class=\"hlight\">:</span> <br />بشد زنگه با نامور صد سوار<br />گروگان ببرد ازدرِ شهریار<br />ببردش همه خواسته هرچه بود<br />که از پیش گرسیوز آورده بود<br />چه در شهر سالار ترکان رسید<br />خروش آمد و دیدبانش بدید<br />پذیره شدش نامداری بزرگ <br />کجا نام او بود جنگی طورگ <br />چو شد زنگه ٔ شاوران نزد شاه <br />سپهدار برخاست از پیشگاه .<br /><font color=\"Red\">(شاهنامه چ بروخیم ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨٦</span>).</font><br /></font></div>'),
(178208, 'طورگ', '<span class=\"hlight\">طورگ .</span> <font color=\"DarkGreen\"><b>[ طُ وُ ]</font></b> (اِخ ) نام سپهسالار خاقان ترک معاصر خسرو پرویز ساسانی، آنکه به دست گردیه خواهر بهرام چوبینه کشته گشت . فردوسی پس از فرار گردیه از مرو و فرستادن خاقان طورگ را از پس وی شرح کشته شدن او چنین آرد <span class=\"hlight\">:</span> <br />بیامد سپهدار با ششهزار<br />گزیده ز ترکان جنگی سوار<br />به روز چهارم بدیشان <font color=\"DarkGreen\"><b>[ گردیه و سپاه او ]</font></b> رسید<br />زن شیردل چون سپه را بدید...<br />سلیح برادر بپوشید زن <br />نشست از بر باره ٔ گامزن ...<br />به پیش سپاه اندر آمد طورگ <br />که خاقان ورا خواندی پیر گرگ <br />به ایرانیان گفت کآن پاک زن <br />مگر نیست با این بزرگ انجمن <br />چو بد گردیه با سلیح گران <br />میان بسته برسان جنگ آوران <br />دلاور طورگش ندانست باز<br />بزد پاشنه رفت پیشش فراز...<br />بدو گردیه گفت کاینک منم <br />که بر شیر درّنده اسپ افکنم <br />چو بشنید آواز او را طورگ <br />بر آن اسب جنگی چو شیر سترگ <br />شگفت آمدش گفت خاقان چین <br />تو را کرد ازین پادشاهی گزین ...<br />بدو گردیه گفت کز رزمگاه <br />بیک سو شویم از میان سپاه <br />سخن هرچه گفتی تو پاسخ دهم <br />تو را اندرین رای فرخ نهم <br />ز پیش سپاه اندر آمد طورگ <br />بیامد برِ نامدار سترگ <br />چو تنها بدیدش زن چاره جوی <br />از آن مغفر تیره بگشاد روی <br />بدو گفت بهرام را دیده ای <br />سواری و رزمش پسندیده ای ...<br />مرا بود هم مادر و هم پدر<br />کنون روزگار وی آمد بسر<br />کنون من تو را آزمایش کنم <br />یکی سوی رزمت گرایش کنم <br />گرم از در شوی یابی بگوی <br />همانا مرا خود پسندی تو شوی <br />بگفت این وز آن پس برانگیخت اسپ <br />پس ِ او همی تاخت ایزدگشسپ <br />یکی نیزه زد بر کمربند اوی <br />که بگذاشت خفتان و پیوند اوی <br />چو از پشت باره درآمد نگون <br />همه ریگ شد زیر او جوی خون ...<br /><font color=\"Red\">(شاهنامه چ بروخیم ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٣٧</span> و <span class=\"hlight\" dir=\"rtl\">٢٨٣٨</span>).</font><br /></font></div>'),
(178209, 'طوری', '<span class=\"hlight\">طوری .</span> (اِ) توری . قسمی پارچه . <BR><font color=\"Blue\">◄</font> لیف . <BR><font color=\"Blue\">◄</font> کیسه مانندی کوچک شبیه طور که در برخی از چراغها که با نفت سوزد بکار رود.<br /></font></div>'),
(178210, 'طوری', '<span class=\"hlight\">طوری .</span> <font color=\"DarkGreen\"><b>[ ری ی ]</font></b> (ع ص، اِ) وحشی از مردم و مرغ و کبوتر. (منتهی الارب ). وحشی . (مهذب الاسماء). اسم طیور وحشی است و حمام را نیز گویند. (فهرست مخزن الادویه ). رمیدگی و وحشت . (برهان ) (آنندراج ).<br /></font></div>'),
(178211, 'طوری باف', '<span class=\"hlight\">طوری باف .</span> (نف مرکب ) آنکه طور بافد. و رجوع به توری شود.<br /></font></div>'),
(178212, 'طوریس', '<span class=\"hlight\">طوریس .</span> (اِخ ) (جبل ...)سلسله ٔ جبال آسیای صغیر بین کیلیکیه و کاپادوکیه .<br /></font></div>'),
(178213, 'طورین', '<span class=\"hlight\">طورین .</span> (اِخ ) دهی است به ری . (منتهی الارب ). دیهی است از دیههای ری . (معجم البلدان ).<br /></font></div>'),
(178214, 'طورینوس', '<span class=\"hlight\">طورینوس .</span> (اِخ ) فرزندمنی سارخوس برادر فیثاغورس . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨</span>).<br /></font></div>'),
(178215, 'طورینی', '<span class=\"hlight\">طورینی .</span> (ص نسبی ) منسوب به طورین که از دیههای ری است . (سمعانی ).<br /></font></div>'),
(178216, 'طوریوس', '<span class=\"hlight\">طوریوس .</span> (اِخ ) از فلاسفه ٔ طبیعیین . کتاب الرؤیااز اوست . (ابن الندیم ) (تاریخ الحکماء قفطی ص <span class=\"hlight\" dir=\"rtl\">٢١٨</span>).<br /></font></div>'),
(178217, 'طوزآغاچ', '<span class=\"hlight\">طوزآغاچ .</span> (اِخ ) شهری وسط است (از اعمال روم ). حقوق دیوانیش شانزده هزار و پانصد دینار است . (نزهة القلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٩٩</span>).<br /></font></div>'),
(178218, 'طوزلق', '<span class=\"hlight\">طوزلق .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ناحیه ای در مغرب ارمنیه .<br /></font></div>'),
(178219, 'طوس', '<span class=\"hlight\">طوس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ماه . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> (اِمص ) خوبی و تازگی چهره بعدِ بیماری . (منتهی الارب ). خوبی رو وتازگی آن بعد از رستن از بیماری . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> (مص ) خوبرو شدن . <BR><font color=\"Blue\">◄</font> پاسپر کردن . (منتهی الارب ). زیر پای مالیدن . (منتخب اللغات ).<br /></font></div>'),
(178220, 'طوس', '<span class=\"hlight\">طوس .</span> (ع اِمص ) دوام و همیشگی چیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) دوائی که جهت حفظ صحت خورند. (منتهی الارب ). داروئی که برای حفظ آشامیده شود. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> (مص ) بپوشانیدن . (تاج المصادر).<br /></font></div>'),
(178221, 'طوس', '<span class=\"hlight\">طوس .</span> (اِخ ) از دیههای بخارا. (معجم البلدان ).<br /></font></div>'),
(178222, 'طوس', '<span class=\"hlight\">طوس .</span> (اِخ ) ناحیتی است (به خراسان ) و اندر وی شهرکهاست چون طوران و نوقان و بروغون و رایکان و بنواذه و اندر میان کوههاست و اندر کوههای وی معدن پیروزه است و معدن مس است و سرب و سرمه و شبه و <font color=\"DarkGreen\"><b>[ از وی ]</font></b> دیگ سنگین و سنگ فسان و شلواربند و جورب خیزد وبه نوقان مرقد مبارک علی بن موسی الرضاست و آنجا مردمان به زیارت شوند و هم آنجا گور هارون الرشید است . (حدود العالم ). چند شهری است اندر ایران مرتفعتر از همه بهتر و سازنده تر از خوشی آب و هوا گنجه ٔ پرگنج در اران، صفاهان در عراق در خراسان مرو و طوس در روم باشد اقسرا. (از نزهة القلوب ص <span class=\"hlight\" dir=\"rtl\">٩١</span> و <span class=\"hlight\" dir=\"rtl\">٩٢</span>). طوس، از اقلیم چهارم، طولش از جزایر خالدات «صب لب » و عرض از خطاستوا «لز». جمشید پیشدادی ساخت بعد از خرابیش طوس نوذر تجدید عمارتش کرده بنام خود منسوب گردانید و ازمزار عظما قبر امام معصوم علی بن موسی الرضا رضی اﷲ عنهمابن جعفر در دیه سناباد به چهارفرسنگی طوس است وقبر هارون الرشید خلیفه ٔ عباسی در مشهد مقدس آن حضرت است و مشهد طوس از مشاهیر مزارات متبرکه است و آن موضع اکنون شهرچه شده و از مشهد تا زاوه ٔ سنجان پانزده فرسنگ است ... و در جانب قبلی طوس دروازه ای است که سه هزار ولی ابوبکرنام در مزارات این دروازه ٔ رودبارآسوده اند و در جانب شرقی او قبر امام حجةالاسلام محمدغزالی و احمد غزالی و مزار فردوسی و معشوق طوسی هم آنجا است . مردم طوس نیکوسیرت و پاک اعتقاد و غریب دوست باشند و از میوه های آنجا انگور و انجیر و بسیار شیرین باشد و در حوالی طوس مرغزاری است آن را مرغزار رایکان گویند. (نزهة القلوب چ اروپا صص <span class=\"hlight\" dir=\"rtl\">١٥٠</span>-<span class=\"hlight\" dir=\"rtl\">١٥١</span>). گروهی از بزرگان چون جابربن حیان پدر شیمی، فردوسی، خواجه نظام الملک، محمدبن اسلم، امام محمد غزالی، خواجه نصیرالدین از آنجا باشند. یاقوت در معجم البلدان گوید:شهری است به خراسان، میان آن و نیشابور قریب ده فرسنگ است و آن مشتمل بر دو بَلْده باشد، یکی را طابران گویند و دیگری را نوقان و آن دو را فزون از ده هزار دیه باشد. فتح طوس بروزگار عثمان بود و قبر علی بن موسی الرضا و هارون بدانجاست . مسعربن مهلهل گوید: طوس چهار شهر است که دو شهر آن بزرگ و دو کوچکند و در آن آثار بناهای اسلامی مهمی وجود دارد، همچنین خانه ٔ حمیدبن قحطبه در آن شهر است که مساحت آن یک میل در یک میل است و آرامگاه علی بن موسی الرضا و قبر رشید در برخی از بوستان های آن خانه است و میان طوس و نیشابور قصر باشکوه عظیمی است که آن را بنیانی بس استوار است و من به بلندی دیوارها و استواری بنیان آن قصری ندیده ام و در داخل آن کاخ مقصوره هائی است که زیبائی آنها مایه ٔ حیرت و شگفتی است . همچنین در درون قصر مزبورنوعی عمارت طولانی و دراز و رواقها و گنجینه ها و خلوتخانه هاست . من از چگونگی آن کاخ پرسیدم و دیدم مردم شهر به اجماع معتقدند که بنای مزبور یادگار یکی از تبابعه است که از یمن بقصدتسخیر کشور چین حرکت کرده است و چون بدین جایگاه رسیده است بر آن شده است که حرمسرا و گنجینه ها و ذخایرخود را در محلی بگذارد و خود سبک تر به سیر خود ادامه دهد بدین منظور این کاخ را بنیان نهاده و نهر بزرگی در آن جاری ساخته است که آثار آن نمودار است، آنگاه گنجها و ذخایر و حرمسرای خود را در آنجا گذارده و خود به چین رهسپار شده و پس از رسیدن بمقصود خود بدین جایگاه بازگشته است . و آنگاه برخی از ذخایری را که در کاخ به ودیعت سپرده است با خود به یمن برده و بسیاری از آنها را هم در همان کاخ باقی گذارده است ولی جایگاه گنجها و ذخایر مزبور را از نظرها نهان ساخته و صفات مواضع آنها را با آنها نوشته است و در زیر خاک مدفون ساخته است و این وضع بر این کیفیت همچنان باقی بوده است، کاروان ها و مسافران بدان کاخ فرودمی آمده اند و از ذخایر و گنجینه های نهفته در آن بهیچرو آگاه نبوده اند تا سرانجام این راز آشکار میشود و اسعدبن ابی یعفر صاحب کحلان در روزگار ما این گنجینه ها را بیرون می آورد، چه وی از صفات گنجینه ها آگاه میشود و بیدرنگ گروهی را برای بیرون آوردن آنها بدان سوی گسیل میدارد و آنها گنجینه ها را به یمن نزد وی میبرند.<br />یاقوت گویداهل خراسان مردم طوس را گاو خوانند و سبب آن ندانستم چیست . و بدین دو بیت مردی نظام الملک را هجا گوید:<br />لقد خرّب الطوسی بلدة غزنة<br />فصب علیه اﷲ مقلوب بَلدته <br />هو الثور قرن الثور فی حِر امه ِ<br />و مقلوب اسم الثور فی جوف لحیته .<br />و دعبل بن علی را قصیدتی است در مدح آل علی که در آن ذکر قبر علی بن موسی ورشید را به طوس کند:<br />اربع بطوس علی قبر الزکی به <br />ان کنت تربع من دین علی وطری <br />قبران فی طوس خیر الناس کلهم ِ<br />و قبر شرّهم ِ هذا من العبر<br />ما ینفع الرجس من قرب الزکی و لا<br />علی الزکی بقرب الرجس من ضرر<br />هیهات کل امری ٔ رهن بما کسبت <br />یداه حقاً فخذ ما شئت او فذر.<br /> <font color=\"Red\">(از معجم البلدان ).</font><br />بارتولد در کتاب نفیس جغرافیای تاریخی ایران آرد: «... کلمه ٔ طوس در قرن دهم م . به یک ولایت تمام اطلاق میشد که شهر نوقان و شهر طابران و قریه ٔ سناباد که بسال <span class=\"hlight\" dir=\"rtl\">٨٠٩</span> م . هارون الرشید و بسال <span class=\"hlight\" dir=\"rtl\">٨١٨</span> م . علی بن موسی الرضا از ائمه ٔ آل علی در آن مدفون گردیدند در ولایت طوس بودند. مأمون برای خوش آیند شیعیان امام رضا را وارث تاج و تخت اعلام کرد ولی بعد بطوری که میگفتند امر داد مسمومش ساختند. شرح و توصیف طوس قرون وسطی را ما در دست نداریم . در زمان جغرافیانویسان عرب شهر طوس بواسطه ٔ رونق و ترقی نیشابور اهمیت بزرگی نداشت . طوس هم مانند نیشابور به دست تولوی پسر چنگیزخان خراب و در زمان اوغدی (اوکتای ) جانشین چنگیز بتجدید عمارتش پرداختند و از آن ببعد چند مرتبه مقر فرمانروایان مغول شد. بعد از سقوط مغولهای ایران طوس با قوچان و کلات و ابیورد و نسا و واحه ٔ مرو در جزو قلمرو دولت کوچکی که امیر ارغونشاه رئیس طائفه ٔ جون غربانی تشکیل داده بود درآمد، بعد از ارغونشاه پسرانش محمدبیگ و علی بیگ جانشین پدر شدند. (حافظ ابرو: <span class=\"hlight\" dir=\"rtl\">a</span> <span class=\"hlight\" dir=\"rtl\">٢٧٦</span>). علی بیگ در سال <span class=\"hlight\" dir=\"rtl\">١٣٨٢</span> م . مجبور به اطاعت از تیمور شده بعد وی را به فرغانه اعزام و در سال بعد مقتول ساختند. در سال <span class=\"hlight\" dir=\"rtl\">١٣٨٩</span> م : بعد از شورشی که پیشرفت نداشت طوس را قتل عام کردند و قریب به ده هزار نفر کشته شد. پای دروازه های شهر برحسب معمول برجهائی از کله ٔ کشتگان ساخته بودند. (شرف الدین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٦٩</span>). تجدید عمارت قلعه ٔ طوس بعد از فوت تیمور و در سال <span class=\"hlight\" dir=\"rtl\">١٤٠٥</span> م . انجام گرفت . در دوره های بعد اسم طوس را با نام مشهد یکجا میبرند، مشهد تدریجاً بواسطه ٔ اهمیت مذهبی خود شهر مجاور را تحت الشعاع قرار داده و پایتخت خراسان گردید. سیاح هندی که معاصر نادرشاه بوده از مهاجرت تدریجی سکنه ٔ طوس بمشهد سخن میراند و صنیعالدوله وزیر ایران (که بعدها ملقب به اعتمادالسلطنه گردید) قول سیاح هندی را در کتاب خود مسمی به مطلعالشمس نقل کرده و وضع کنونی خرابه های طوس را مفصلاً در این کتاب شرح داده است . در بین خرابه ها هیچگونه آثاری که دارای تاریخ باشد دیده نمی شود. صنیعالدوله دیوارهای شهر را که یک فرسخ دور آن است و ارگی را که در قسمت شمال شرقی بوده و عمارت بزرگی را که شاید مسجد و داخل شهر بوده تعریف میکند. در همه جا طول و عرض و ارتفاع دیوارها و برجها و خرابه های سایر عمارات ذکر شده . در داخل ارگ قلعه ٔ کوچکی بوده که بر روی تپه ٔ مصنوعی ساخته بودند، در کتاب مزبور تصویر مسجد نیز ترسیم یافته، این عمارت در نزد ایرانیان به نقاره خانه معروفست .فرزر در ضمن تعریف طوس از مناره ٔ کوچکی (در نزدیکی مسجد) و گنبد کوچکی در بالای قبر فردوسی که در بیرون شهر نزدیکی دروازه ٔ جنوب شرقی واقع بوده سخن میراند بطوری که نقل میکنند ساختمان این گنبد را به عبیداﷲخان بخارائی که در قرن شانزدهم م . زمامدار بوده نسبت میدهند. در سال <span class=\"hlight\" dir=\"rtl\">١٨٥٨</span> م . که خانیک اف به این سرزمین بسیاحت آمده بود دیگر آن گنبد نبود و محل روی قبر گندم کاشته بودند. پرفسور ژوکوفسکی به سال <span class=\"hlight\" dir=\"rtl\">١٨٩٠</span> م . بمحل مزبور رفته و فقط تپه ای دیده بود که در آن کاوشهائی شده و این تپه از آجر و نیمه و قطعات کاشی که بلاشک از بنای خراب شده باقی مانده بودند تشکیل یافته و شایداین همان بنائی باشد که فرزر مشاهده کرده بود. بطوری که دهاقین تعریف کرده بودند تپه ٔ مزبور را آصف الدوله حاکم سابق خراسان کنده و دور محوطه ای که تشکیل یافته بود آجر گرفته و دیواری در اطراف تپه کشیده میخواست بنائی روی آن بسازد لیکن قبل از اتمام کار بدرودزندگانی گفت . زمانی بود که قبور امامین یعنی امام احمد و امام محمد غزالی که دومی مؤلف کتاب شهیر احیاءالعلوم است نزدیکی قبر فردوسی بود، قبر محمد غزالی در قرن چهاردهم م . در ضمن شرح سیاحت ابن بطوطه (<span class=\"hlight\" dir=\"rtl\">٣</span> - <span class=\"hlight\" dir=\"rtl\">٧٧</span>) مذکور گردیده لیکن در این زمان از بین رفته و اثری از آن نمانده است . طوس در سمت شمالی کشف رود واقع است . در نزدیکی دروازه ٔ جنوب شرقی طوس در سر راه مشهد پل هشت چشمه ای از روی رودخانه ساخته بودند، پل مزبور در این زمان بحال نیمه خراب باقی است . فرزر و صنیعالدوله هر یک شرحی در توصیف این پل نگاشته اند، مخصوصاً صنیعالدوله فاصله ٔ هر یک از چشمه ها را هم ذکر کرده، پلی که بر روی کشف رود قدری پائین تر بر سر راه کلات و مشهد (بفاصله ٔ پنج میل از مشهد) ساخته اند و دارای یازده چشمه است به وضع بهتر باقی مانده ولی نه بطوری که کاملاً بی عیب باشد. پل مزبور به «پل شاه » معروفست . (جغرافیای تاریخی ایران تألیف بارتولد ترجمه ٔ سردادور صص <span class=\"hlight\" dir=\"rtl\">١٦٠</span>-<span class=\"hlight\" dir=\"rtl\">١٦٢</span>).<br /></font></div>'),
(178223, 'طوس', '<span class=\"hlight\">طوس .</span> (اِخ ) نام یکی از شاهان مصر که پس از شورش آنجا در زمان داریوش دوم بسلطنت رسیده اند. ابوریحان در آثارالباقیه (چ لیپزیک <span class=\"hlight\" dir=\"rtl\">١٩٢٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩١</span>)نام ایشان را چنین نوشته است : آمرطیوس، نافرطاس، اوخرس، فساموث، موثاطوس، ناقاطانباس، طوس، ناقاطانباس .این کلمه ظاهراً مصحف تاخس باشد چنانکه اسامی دیگر شاهان که تصحیف شده بترتیب چنین است : آمیرته، نفریت، آخریس، فسمتیخ، نکتانب . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٤١</span>).<br /></font></div>'),
(178224, 'طوس', '<span class=\"hlight\">طوس .</span> (اِخ ) پسر نوذر. وی در دربار چند شاهنشاه ایران، کیقباد و کاوس و کیخسرو، مقام اسپهبدی داشته است . رجوع به توس در همین لغت نامه و آنندراج و فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٤٤</span> و شاهنامه ٔ فردوسی شود.<br /></font></div>'),
(178225, 'طوس خیمه', '<span class=\"hlight\">طوس خیمه .</span> <font color=\"DarkGreen\"><b>[ خ َم َ ]</font></b> (اِخ ) ده کوچکی است از دهستان طیبی گرمسیری بخش کهکیلویه ٔ شهرستان بهبهان در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی جنوب باختری لنده مرکز دهستان و <span class=\"hlight\" dir=\"rtl\">٥٤</span> هزارگزی شمال بهبهان به آغاجاری با <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178226, 'طوس نوذر', '<span class=\"hlight\">طوس نوذر.</span> <font color=\"DarkGreen\"><b>[ س ِن َ ذَ ]</font></b> (اِخ ) رجوع به طوس (پسر نوذر) و توس شود.<br /></font></div>'),
(178227, 'طوسان', '<span class=\"hlight\">طوسان .</span> (اِخ ) نام محلی که برحسب روایت، طوس نوذر سردار کیخسرو ساخت در محلی که کوسان نام داشت و آن در ناحیه ٔ پنجاه هزار مازندران است . (مازندران و استراباد رابینو ص <span class=\"hlight\" dir=\"rtl\">١٦٠</span> بخش انگلیسی ).<br /></font></div>'),
(178228, 'طوسان', '<span class=\"hlight\">طوسان .</span> (اِخ ) قریتی است به دوفرسنگی مرو شاهجان . (معجم البلدان ).<br /></font></div>'),
(178229, 'طوسانی', '<span class=\"hlight\">طوسانی .</span> (ص نسبی ) منسوب به طوسان که دیهی است به مرو. (سمعانی ).<br /></font></div>'),
(178230, 'طوسطس', '<span class=\"hlight\">طوسطس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به رومی اذخر است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178231, 'طوسقرون', '<span class=\"hlight\">طوسقرون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) قنطوریون صغیر است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178232, 'طوسن', '<span class=\"hlight\">طوسن .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b>(اِخ ) دیهی است از دیههای بخارا. (معجم البلدان ).<br /></font></div>'),
(178233, 'طوسول', '<span class=\"hlight\">طوسول .</span> (اِخ ) ناحیتی است بزرگ <font color=\"DarkGreen\"><b>[ از هندوستان ]</font></b>بچین پیوسته و میانشان کوهی است و ایشان مردمانی اسمرند و جامه ٔ ایشان از پنبه است و این ناحیت را با چینیان حرب است و چینیان مهتر آیند. (حدود العالم ).<br /></font></div>'),
(178234, 'طوسک', '<span class=\"hlight\">طوسک .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ) نوعی از خار است که آن را بعربی شوکةالدراجین و خس الکلب ومشطالراعی خوانند. گویند اگر قدری از گل آن بکوبند و در شیر مالند شیر بسته گردد و اگر بجوشانند و بر موضعی که خواهند قطع کردن ِ ضماد کنند بی حس گرداند. (برهان ) (آنندراج ). مشطالراعی . (فهرست مخزن الادویه ).<br /></font></div>'),
(178235, 'طوسکاچال', '<span class=\"hlight\">طوسکاچال .</span> (اِخ ) دهی از دهستان کوهسارات بخش مینودشت شهرستان گرگان در <span class=\"hlight\" dir=\"rtl\">١٩</span> هزارگزی جنوب خاوری مینودشت . کوهستانی معتدل با <span class=\"hlight\" dir=\"rtl\">١٩٠</span> تن سکنه . آب آن از چشمه سار. محصول آنجا غلات و ارزن و لبنیات و ابریشم . شغل اهالی زراعت و گله داری . صنایع دستی زنان بافتن پارچه ٔ ابریشمی و شال . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(178236, 'طوسکلا', '<span class=\"hlight\">طوسکلا.</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) نام موضعی در حوالی ساری مازندران . (مازندران و استراباد رابینو ص <span class=\"hlight\" dir=\"rtl\">٥٩</span> بخش انگلیسی ). دهی از دهستان قره طغان بخش بهشهر شهرستان ساری در<span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی شمال نکادشت . معتدل و مرطوب مالاریائی با <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن سکنه . آب آن از رودخانه ٔ نکا. محصول آن برنج و غلات و پنبه و مختصر مرکبات و صیفی . شغل اهالی زراعت . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(178237, 'طوسی', '<span class=\"hlight\">طوسی .</span> (اِخ ) علاءالدین علی . رجوع به علاءالدین ... شود.<br /></font></div>'),
(178238, 'طوسی', '<span class=\"hlight\">طوسی .</span> (اِخ ) نصیرالدین . رجوع به نصیرالدین طوسی (خواجه ...) شود.<br /></font></div>'),
(178239, 'طوسی', '<span class=\"hlight\">طوسی .</span> (اِخ ) محمدبن الحسن . رجوع به ابوجعفر طوسی محمدبن حسن شود.<br /></font></div>'),
(178240, 'طوسی', '<span class=\"hlight\">طوسی .</span> (ص نسبی، اِ) رنگ میان سبزو سرخ . رنگی مقابل سوسنی . رنگ سبز که بسپیدی زند.<br /></font></div>'),
(178241, 'طوسی', '<span class=\"hlight\">طوسی .</span> (اِخ ) محمدبن محمد. رجوع به ابوحامد غزالی شود.<br /></font></div>'),
(178242, 'طوسی', '<span class=\"hlight\">طوسی .</span> (اِخ ) عبدالعزیزبن محمدبن علی طوسی . رجوع به عبدالعزیز... شود.<br /></font></div>'),
(178243, 'طوسی', '<span class=\"hlight\">طوسی .</span> (اِخ ) رجوع به فردوسی و ابوالقاسم شود.<br /></font></div>'),
(178244, 'طوسی', '<span class=\"hlight\">طوسی .</span> (اِخ ) ابوالحسن علی بن عبداﷲبن سنان التیمی . عالم روایه ٔ قبائل و اشعار فحول، و درک مصاحبت مشایخ کوفیین و بصریین کرده است و بیشتر مجالست و اخذ او از ابن الاعرابی بوده است و او را نیز پسری بوده که در علم راه پدر میرفته است . و طوسی را با ابن السکیت دشمنی بود، چه هر دو از نصران خراسانی کسب علم کرده بودندو پس از مرگ در کتب او اختلاف کردند. (ابن الندیم ).<br /></font></div>'),
(178245, 'طوسی', '<span class=\"hlight\">طوسی .</span> (اِخ ) ابوجعفر، محمدبن الحسن بن علی الطوسی، ملقب به شیخ الطائفه . رجوع به ابوجعفر طوسی ... شود.<br /></font></div>'),
(178246, 'طوسی', '<span class=\"hlight\">طوسی .</span> (اِخ ) نام شاعری که در اوان کودکی امیر علیشیر نوائی درگذشته و این امیر ذکر وی در مجلس اول از تذکره ٔ مجالس النفائس آورده و گوید: مولانا طوسی مثل گوی و شعرش عام فریب بود، سال عمرش به صد رسید و این مطلعش مشهور است، مطلع:<br />زهی نوش لب لعلت حیات جاودان من <br />بدندان میگزی لب را چه میخواهی زجان من ؟<br />این مطلع هم از اوست :<br />بمن باشید ای خوبان خدا را<br />خدا رادارم و باقی شما را .<br /></font></div>'),
(178247, 'طوسی', '<span class=\"hlight\">طوسی .</span> (اِ) نوعی از شال . پتو و برک غلاف کمان هم گویند <span class=\"hlight\">:</span> <br />صلیب همه ٔ کافران سوختم <br />که طوسی بدین رشته دردوختم .<br /> <font color=\"Red\">نظام قاری (دیوان البسه ص <span class=\"hlight\" dir=\"rtl\">١٩٤</span>).</font><br /><BR><font color=\"Blue\">◄</font> غلاف کمان <span class=\"hlight\">:</span> به اسم مسمای اوکمان طوسی پوش و زره داودی بعشق زیور حلقه در گوش (؟). نظام قاری، (دیوان البسه ص <span class=\"hlight\" dir=\"rtl\">١٣٦</span>).<br /></font></div>'),
(178248, 'طوسی', '<span class=\"hlight\">طوسی .</span> (ص نسبی ) منسوب به طوس، شهری به خراسان . <BR><font color=\"Blue\">◄</font> منسوب به طوس از قرای بخارا، ابوجعفررضوان بن عمران الطوسی از آنجاست . (معجم البلدان ).<br /></font></div>'),
(178249, 'طوسیس', '<span class=\"hlight\">طوسیس .</span> (معرب، اِ) به قول مؤلف حاوی فقاح اذخر است . فقاح اذخر. (فهرست مخزن الادویه ).<br /></font></div>'),
(178250, 'طوسیطیس', '<span class=\"hlight\">طوسیطیس .</span> (معرب، اِ) قسم متوسط اِذخر. اذخر بابلی .<br /></font></div>'),
(178251, 'طوش', '<span class=\"hlight\">طوش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b>(ع اِمص ) سبکی عقل . (منتهی الارب ) (منتخب اللغات ).<br /></font></div>'),
(178252, 'طوط', '<span class=\"hlight\">طوط.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) طیوط. تیزشهوت گردیدن گشن . بانگ کردن گشن . (منتهی الارب ).<br /></font></div>'),
(178253, 'طوط', '<span class=\"hlight\">طوط.</span> (ع اِ) مار. (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> پنبه . (منتهی الارب ) (منتخب اللغات ) (مهذب الاسماء). قطن . (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> قطن بردی . لوئی . <BR><font color=\"Blue\">◄</font> (ص ) مرد بلندبالا. (منتهی الارب ). مرد دراز. (مهذب الاسماء). دراز. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> (اِ) باشه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شب پره . (منتهی الارب ) (منتخب اللغات ). خفاش . <BR><font color=\"Blue\">◄</font> (ص ) خُرد. (منتهی الارب ) (منتخب اللغات ). ریزه . <BR><font color=\"Blue\">◄</font> مرد سخت پیکار. (منتهی الارب ). شدیدالخصومة. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> دلیر. (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> گشن تیزشهوت . (منتهی الارب ). شتر مست و بیقرار برای گشنی . (منتخب اللغات ). ج، اطواط.<br /></font></div>'),
(178254, 'طوطاق اغریوس', '<span class=\"hlight\">طوطاق اغریوس .</span> <font color=\"DarkGreen\"><b>[ اِ ]</font></b> (معرب، اِ مرکب ) لغتی است یونانی و معنی آن بعربی حماض البری است و آن رستنی باشد که حماض البقر و سلق بری هم گویند و آن را حماض اغریون هم خوانند که بجای سین نون باشد. (برهان ) (آنندراج ). و رجوع به ماده ٔ بعد شود.<br /></font></div>'),
(178255, 'طوطاق اغریون', '<span class=\"hlight\">طوطاق اغریون .</span> <font color=\"DarkGreen\"><b>[ اِ ]</font></b> (معرب، اِ مرکب ) به یونانی حماض بری است و جبلی را نیز گفته اند و سلق بری و سلق جبلی نیز گفته اند، و معروف نزد اهل شیراز باطلیموس است . (فهرست مخزن الادویه ). حماض جبلی است و آن نوعی از سلق بری بود. (اختیارات بدیعی ). حماض جبلی است . (تحفه ٔ حکیم مؤمن ). و رجوع به طوطاق اِغریوس شود.<br /></font></div>'),
(178256, 'طوطاوس', '<span class=\"hlight\">طوطاوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) کلمه ٔ مصحف است . رجوع به ایمیطریطاوس شود.<br /></font></div>'),
(178257, 'طوطر', '<span class=\"hlight\">طوطر.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) حبةالخضراست . (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویه ).<br /></font></div>'),
(178258, 'طوطرفع', '<span class=\"hlight\">طوطرفع.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) به سریانی تودری است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178259, 'طوطلة', '<span class=\"hlight\">طوطلة.</span> <font color=\"DarkGreen\"><b>[ طو طَ ل َ ]</font></b> (اِخ ) تطیله . شهری به اسپانیا. (نخبة الدهر دمشقی ص <span class=\"hlight\" dir=\"rtl\">٢٤٥</span>).<br /></font></div>'),
(178260, 'طوطلون', '<span class=\"hlight\">طوطلون .</span> (معرب، اِ) به یونانی سلق است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178261, 'طوطلی', '<span class=\"hlight\">طوطلی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) طایفه ای از ایلات ممسنی فارس .<br /></font></div>'),
(178262, 'طوطک', '<span class=\"hlight\">طوطک .</span> <font color=\"DarkGreen\"><b>[ طو طَ ]</font></b> (اِ) طوطی . ببغاء. اسم عامی طوطی است که بعربی ببغاء نامند. (فهرست مخزن الادویه )<span class=\"hlight\">:</span> و اندر دشتها و بیابانهای وی <font color=\"DarkGreen\"><b>[ هندوستان ]</font></b> جانوران گوناگونند، چون پیل و گرگ و طاووس و کرکوی و طوطک و شارک و آنچه بدین ماند. (حدود العالم ).<br />بر الواح ایوان کیوان مثالش <br />سپیدآب قمری و زنگار طوطک .<br /> <font color=\"Red\">؟ (از جُنگی خطی مورخ به <span class=\"hlight\" dir=\"rtl\">٦٥١</span> هَ . ق .).</font><br /> <BR><font color=\"Blue\">◄</font> نام سازی است و در عرف الغوزه خوانند. میرنجات راست <span class=\"hlight\">:</span> <br />ارغنون و نی و قانون برد از دل شک را<br />کوک کن توتک و طنبور و دف و تنبک را.<br /> <font color=\"Red\">(از آنندراج ).</font><br />و در تداول محلی گناباد بر سازی دهنی که از گل پخته سازند اطلاق شود و در شمار بازیچه های کودکان است . رجوع به مقاله ٔ آلات موسیقی ایران قدیم در مجله ٔ موسیقی شماره ٔ <span class=\"hlight\" dir=\"rtl\">٦</span> دوره ٔ <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٧</span> شود.<br /></font></div>'),
(178263, 'طوطک', '<span class=\"hlight\">طوطک .</span> <font color=\"DarkGreen\"><b>[ طو طَ ]</font></b> (اِخ ) دهی از دهستان بوانات بخش بوانات و سرچهان شهرستان آباده در <span class=\"hlight\" dir=\"rtl\">٤٨</span> هزارگزی جنوب خاوری سوریان . کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">١٢٥</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و تریاک . شغل اهالی زراعت . راه آن فرعی است . پاسگاه ژاندارمری دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(178264, 'طوطک بلا', '<span class=\"hlight\">طوطک بلا.</span> <font color=\"DarkGreen\"><b>[ طو طَ ک ِ ب َ]</font></b> (اِخ ) از معاصرین سلطان الجایتو و از خاصان امیر دانشمند بهادر. چون الجایتو قصد تصرف هرات کرد و امیر دانشمند بهادر را برای تصرف آن شهر و بدرگاه آوردن امیر فخرالدین فرستاد این طوطک بلا چند کرت به پیام و سفارت از جانب مخدوم خود امیر دانشمند بهادر نزد امیر فخرالدین و محمد سام رفته است . رجوع به ذیل جامعالتواریخ رشیدی ص <span class=\"hlight\" dir=\"rtl\">٢٠</span>، <span class=\"hlight\" dir=\"rtl\">٢١</span>، <span class=\"hlight\" dir=\"rtl\">٢٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٨</span>، <span class=\"hlight\" dir=\"rtl\">٢٩</span>، <span class=\"hlight\" dir=\"rtl\">٣٥</span>، <span class=\"hlight\" dir=\"rtl\">٣٦</span> شود.<br /></font></div>'),
(178265, 'طوطکان', '<span class=\"hlight\">طوطکان .</span> <font color=\"DarkGreen\"><b>[ طو طَ ]</font></b> (اِخ ) قریه ای است هشت فرسنگی میانه ٔ جنوب و مشرق سوریان . (فارسنامه ناصری ).<br /></font></div>'),
(178266, 'طوطی', '<span class=\"hlight\">طوطی .</span> (اِخ ) دهی از بخش شیب آب شهرستان زابل در <span class=\"hlight\" dir=\"rtl\">١٠</span> هزارگزی باختر سکوهه و <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی شوسه ٔ زاهدان به زابل . جلگه و گرم و معتدل با <span class=\"hlight\" dir=\"rtl\">٣٤٠٠</span> تن سکنه . آب آن از رودخانه ٔ هیرمند. محصول آنجا غلات و لبنیات و پنبه و صیفی . شغل اهالی زراعت و گله داری و قالیچه، گلیم و کرباس بافی . راه آن فرعی است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(178267, 'طوطی', '<span class=\"hlight\">طوطی .</span> (اِخ ) (مولانا...) در سلک شعراء مشهور قرن نهم هجری انتظام داشت . وی ترشیزی الاصل بود و میرزا ابوالقاسم بابر نسبت به او التفات و عنایات بسیار می نمود. و این مطلع از نتایج طبع نقاد اوست که، بیت :<br />جهان که حجره ٔ شش طاق و خانه ٔ دودر است <br />ز چار رکن بساطش فغان الحذر است .<br />مولانا طوطی در اوان جوانی بجهان جاودانی نقل فرمود (سنه ٔ ست و ستین و ثمانمائه، <span class=\"hlight\" dir=\"rtl\">٨٦٦</span> هَ . ق .) و مقرب حضرت سلطانی امیر علیشیر جهت ضبط تاریخ وفاتش این قطعه نظم نمود. قطعه <span class=\"hlight\">:</span> <br />فصیح زمان طوطی آن شاعری <br />که بودش ز بکر معانی عروس <br />چو طوطی برفت این عجب طرفه بود<br />که تاریخ شدفوت او را خروس .<br /><font color=\"Red\">(از حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٨</span>).</font><br /></font></div>'),
(178268, 'طوطی', '<span class=\"hlight\">طوطی .</span> (اِخ ) (ملک ...). عوفی در لباب الالباب گوید: مخدوم انوری، از افاضل جهان و اعیان خراسان و میان او و اوحدالدین انوری مکاتبات و مشاعرات است ...گویند به سمع سلطان علاءالدین ملک الجبال رسانیدند که انوری تو را هجا گفته است و پای از حد خود فراتر نهاده و زبان به مثالب تو برگشاده بنزدیک ملک طوطی نبشت تا آن بلبل بستان فصاحت را بخدمت او فرستد و لطف مجاملت در میان آورد و چنان مینمود که او را بجهت تعهد و تلطف استدعا میکند و در ضمیر داشت که چون بر وی دست یابد اورا نکال گرداند و امیر عمید فخرالدین (از دوستان انوری ) را از آن حال علم بود و صورت حال بنزدیک او نمیتوانست نبشت، چه از سطوت قهر سلطان علاءالدین می اندیشید... بنزدیک او نامه ای نبشت، مطلع آن نامه این که :<br />هی الدنیا تقول بمل ء فیها<br />حذار حذار من بطشی و فتکی ...<br />انوری ازین بیت استدلال نمود که در ضمن آن ملاطفت ناکامی هست ... شفیعان انگیخت تا ملک طوطی را از سر آن دور کردند و چون ملک علأالدین را از آن حال معلوم شد رسولی دیگر فرستاد و گفت هزار سر گوسپند میدهم اگر او را بنزدیک من فرستی، ملک طوطی انوری را موکل کرد که ناکام ساخته باید شد و به غور رفت چه هزار گوسپند بمقابله ٔ تو میدهد، انوری گفت ای ملک اسلام چون من مردی را بهزار سر گوسپند می ارزد پادشاه را برایگان نمی ارزد، بگذار تا باقی عمر در سلک خدم تو منخرط باشم و به دست بیان دُر مدایح در پای تو باشم، ملک طوطی را خوش آمد و او را نگاه داشت ...<br /></font></div>'),
(178269, 'طوطی', '<span class=\"hlight\">طوطی .</span> (اِخ ) آذربایجانی . نام شریفش ابوالفتح خان و خلف الصدق ابراهیم خلیل خان بن پناه خان حکمران شوشی است . همیشه در ایل جوانشیر ریاست و بزرگی داشته اند، معزی الیه بفضل و کمال و مناعت و جلال معروف و محمدصادق خان دنبلی مخاطب سلام عام حضرت خاقان مغفور همشیره زاده ٔ ایشان بوده . این بیت از اوست :<br />دارم اندر هوس وصل خیال عجبی <br />چه خیال عجبی فکر محال عجبی .<br /><font color=\"Red\">(از مجمع الفصحا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٤</span>).</font><br /></font></div>'),
(178270, 'طوطی', '<span class=\"hlight\">طوطی .</span>(اِ) پرنده ای است سبزرنگ از طایفه ٔ پسیتاسیده . و بمناسبت سهولت تقلید آوای آدمی قابل ملاحظه است . طوطیان عموماً در نواحی گرم و رطوبی افریقا و هند زیست میکنند. ببغاء. طوطک . معرب توته ٔ هندی است . (فهرست مخزن الادویه ). معرب توتی و آن طائری است سبز که بعرف آن را طوطا نامند و شکرشکن، شکرفشان، شکرمقال، شکرین مقال، شیرین زبان، شیرین سخن، شیرین تکلم، شیرین گفتار، خوش نوا و خوش حرف از صفات اوست . (آنندراج ) <span class=\"hlight\">:</span> <br />در کف لاله ٔ خودروی نهد سرخ قدح <br />زاغ همچون پر طوطی شود از سبز گیاه .<br /> <font color=\"Red\">فرخی .</font><br />الا تا درآیند طوطی و سارک (شارک )<br />الا تا سرایند قمری و ساری .<br /> <font color=\"Red\">زینتی .</font><br />بلی نعامه و طوطی دو طایرند ولیک <br />غذای آن شکر آمد غذای این اخگر.<br /> <font color=\"Red\">ازرقی .</font><br />طوطی گفتا سمن به بود از سبزه کو<br />بوی ز عنبر گرفت رنگ ز کافور ناب .<br /> <font color=\"Red\">خاقانی .</font><br />ای عندلیب گلشن جان زارنال زار<br />کزشاخ شرع طوطی حاضرجواب شد.<br /> <font color=\"Red\">خاقانی .</font><br />طوطی آمد با دهانی پرشکر<br />در لباس فستقی با طوق زر.<br /> <font color=\"Red\">عطار.</font><br />مرحبا ای طوطی طوبی نشین <br />پوششت حیله ست و طوقت آتشین .<br /> <font color=\"Red\">عطار.</font><br />اگر طوطی زبان می بست در کام <br />نه خود را در قفس میدید و نه دام .<br /> <font color=\"Red\">وحشی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">طوطی ز زبان خویش در دام افتاد</span> .<br /> <font color=\"Red\">؟</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوطی پس آینه </span> ؛ شخصی که در پس آئینه نشسته حرفها زند برای تعلیم دادن طوطی کذائی بنوعی که منظور است و این طوطی کذائی که مقابل و مواجه آئینه است عکس خود را در آن آئینه مشاهده کرده گمان برد که این حرف حریف اوست غافل از آن طوطی که پس آئینه است، و همین مقصود است درین بیت خواجه ٔ شیراز <span class=\"hlight\">:</span> <br />در پس آینه طوطی صفتم داشته اند<br />آنچه استاد ازل گفت بگو میگویم .<br />و هم او راست <span class=\"hlight\">:</span> <br />در لباس بشرٌ مثلکم ارشاد رسول <br />فضل من بهرتو طوطی ّ پس آینه است .<br /> <font color=\"Red\">(از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوطی خط</span> ؛ کنایه از جوان سبزخط. ملا سالک قزوینی راست <span class=\"hlight\">:</span> <br />طوطی خطی که طعنه زند بر شکر لبش <br />دارم سری چو فاخته بر دور غبغبش .<br /> <font color=\"Red\">(از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوطی زرین نفس </span> ؛ کنایه از قلم است . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوطی صاحب سلامت گو</span> ؛ طوطی که آن را صاحب سلامت تعلیم کرده باشند و اکثر اوقات اینچنین میگفته باشد. ملا قاسم مشهدی راست <span class=\"hlight\">:</span> <br />در میان نوخطان باقی همه نیرنگ توست <br />طوطی صاحب سلامت گو خط شبرنگ توست .<br /> <font color=\"Red\">(از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوطی صحرا</span> ؛ کنایه از سبزه است .(آنندراج ) (برهان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوطیَک </span> ؛ مصغر طوطی <span class=\"hlight\">:</span> <br />ماه نو منخسف در گلوی فاخته ست <br />طوطیکان با حدیث قمریکان با انین .<br /> <font color=\"Red\">منوچهری .</font><br />هر طوطیکی سبزقبائی دارد<br />هر آهوکی چَرا به راغی دارد.<br /> <font color=\"Red\">منوچهری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوطی مقال </span> ؛ کنایه از فصیح است . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوطی نوائی </span> ؛ بمعنی طوطی مقال که کنایه از فصیح است . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوطی وار آموختن (از بر کردن ) مطلبی </span> ؛ بی تعقل و اندیشه در فهم مقصود و مفهوم به آموختن یا از بر کردن لفظ بسنده کردن . از بر کردن الفاظ بی درک معانی آنها. چون طوطی سخنی را از بر کرده گفتن بی دانستن معنی آن .<br /></font></div>'),
(178271, 'طوطی سمرقندی', '<span class=\"hlight\">طوطی سمرقندی .</span> <font color=\"DarkGreen\"><b>[ ی ِ س َ م َ ق َ ]</font></b> (اِخ ) ملا طوطی سمرقندی . نام وی در تذکره ٔ نصرآبادی آمده که به اسم سلطان بابر معمای ذیل را سروده است <span class=\"hlight\">:</span> <br />مهر رویش را چو لطف بی حد و پایان بود<br />در مه رخسار او بیند دل و حیران بود.<br />از مهر سین مراد است و لطف که پایان اوان باشد سلطانست، ودر مصرع ثانی از در، باب، خواسته و از ماه رخسار را. (تذکره ٔ نصرآبادی ص <span class=\"hlight\" dir=\"rtl\">٥٢٤</span>).<br /></font></div>'),
(178272, 'طوطیا', '<span class=\"hlight\">طوطیا.</span> (اِ) معرب توتیا. (فهرست مخزن الادویه ). رجوع به توتیا شود <span class=\"hlight\">:</span> <br />خس طبع را چه مال دهی و چه معرفت <br />بی دیده را چه میل کشی و چه طوطیا.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(178273, 'طوطیانوش', '<span class=\"hlight\">طوطیانوش .</span> (اِخ )نام دبیر اسکندر بود و او را در لشکر پادشاه زنگ بقتل آوردند و خون او را خوردند. (برهان ) <span class=\"hlight\">:</span> <br />کشیده دمش طوطیان را به دام <br />سخن پروری طوطیانوش نام .<br /><font color=\"Red\">نظامی (از حاشیه ٔ برهان چ معین ).</font><br /></font></div>'),
(178274, 'طوطیانیوش', '<span class=\"hlight\">طوطیانیوش .</span> (اِخ ) همان طوطیانوش است که دبیر و منشی سکندر باشد. (برهان ).<br /></font></div>'),
(178275, 'طوطیه', '<span class=\"hlight\">طوطیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) دهی از دهستان جمیل آباد بخش بافت شهرستان سیرجان . در <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی شمال راه فرعی بافت به سیرجان . کوهستانی، سردسیر با <span class=\"hlight\" dir=\"rtl\">٩٣</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و حبوبات و تریاک .شغل اهالی آنجا زراعت . راه آن مالرو است . ساکنین ازطایفه ٔ افشار هستند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(178276, 'طوع', '<span class=\"hlight\">طوع .</span> <font color=\"DarkGreen\"><b>[ طُوْ وَ ]</font></b> (ع ص، اِ) ج ِ طائع. (منتهی الارب ). رجوع به طائع شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178277, 'طوع', '<span class=\"hlight\">طوع .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص، اِمص ) فرمان برداری . فرمان برداری کردن . (زوزنی ) (تاج المصادر) (منتهی الارب ). فرمان بردن . (منتخب اللغات ). فرمان کردن . (دهار). منقاد شدن . (منتهی الارب ). اطاعت . فرمانبری . اختیار: بالطوع و الرغبة. مقابل کره . دلخواه <span class=\"hlight\">:</span> <br />هنوز پیشرو روسیان بطوع نکرد<br />رکاب او را نیکو به دست خویش بشار.<br /> <font color=\"Red\">فرخی .</font><br />فلک چو دید قرار جهانیان بر تو<br />قرار کرد و جهانت بطوع کرد اقرار.<br /> <font color=\"Red\">؟ (از تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٧٩</span>).</font><br />خطی داده اند بطوع و رغبت که سیصدهزار دینار بخزانه ٔ معمور خدمت کنند. (تاریخ بیهقی ). یک یک ضیاع را نام بر او<font color=\"DarkGreen\"><b>[ حسنک ]</font></b> خواندند اقرار کرد به فروختن آن به طوع و رغبت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span>). خطی داده اند <font color=\"DarkGreen\"><b>[ حصیری و پسرش ]</font></b> بطوع و رغبت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span>). گفت آنچه نسخت کرده شده است خواستنی است از آمل تنها اگر بطوع پذیرفتند فبها و نعم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٦٩</span>). اندیشم که اگر بطوع خطبه نکنم الزام کند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٨٥</span>). یا چنان بطوع و رغبت که نهاده بودند خطبه باید و یا نثاری و هدیه ای بتمام باید فرستاد چنانکه فراخور ما باشد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٨٩</span>).<br />چرا ورا کت او کرد این بلند ایوان <br />به طوع و رغبت ای هوشیارنَپْرستی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گیتی او را بجان رهین گشتی <br />دولت او را بطوع رام شدی .<br /> <font color=\"Red\">مسعودسعد.</font><br />به طوع و طبع کند ناصر تو را یاری <br />بجان و تن ندهد حاسد تو را زنهار.<br /> <font color=\"Red\">مسعودسعد.</font><br />وآن کس که راه خدمت و طوع تو نسپرد<br />جان و تنش به تیر بلا پی سپر شود.<br /> <font color=\"Red\">مسعودسعد.</font><br />زهی جهان هنر کز جهان هنرمندان <br />همی کنند بطوع آستان تو بالین .<br /> <font color=\"Red\">سوزنی .</font><br />بعضی از فیلان ایشان به دست آوردند و بعضی بطوع با رابط سلطان می آمدند و ایشان را خدای آور نام نهادند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤١٨</span>).<br />این چهل روزش بده مهلت بطوع <br />تا سکالد مکرها او نوع نوع .<br /> <font color=\"Red\">مولوی .</font><br />نیست تخصیص خدا کس را بکار<br />مانع طوع و مراد و اختیار.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> (ص ) فرمانبردار: هو طوع ٌ لک ؛ او مطیع و فرمانبردار توست . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوعاً اَم ْ کُرْهاً</span> ؛ خواه و ناخواه . قدری خوش و قدری ناخوش . ترجمه ٔ خواه و ناخواه . (آنندراج ) <span class=\"hlight\">:</span> حکم سما را چه توان کرد که طوعاً او کرهاً واقع و مجری ... (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٥٦</span>). وزیر این سخن بشنید طوعاً و کرهاً بپسندید. (گلستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوع الجناب </span> ؛ اسپ فرمانبردار. (مهذب الاسماء). سلس القیاد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوع العنان </span> ؛ اسپ نرم عنان . (منتخب اللغات ). اسپ نرم و رام . (منتهی الارب ) <span class=\"hlight\">:</span> و جمعی را به خلع و عزل او دعوت کردند و همه را سمح القیاد و طوع العنان یافتند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>).<br /><BR><font color=\"Blue\">◄</font> فراخ علف شدن چراگاه . (منتهی الارب ). فراخ شدن علف در چراگاه .(منتخب اللغات ).<br /></font></div>'),
(178278, 'طوعة', '<span class=\"hlight\">طوعة.</span> <font color=\"DarkGreen\"><b>[ طُ وَ ع َ ]</font></b> (ع ص ) مرد فرمانبر هر کس . <BR><font color=\"Blue\">◄</font> (اِمص ) طاعت و بندگی . <BR><font color=\"Blue\">◄</font> (اِ) از اعلام زنان . (منتهی الارب ).<br /></font></div>'),
(178279, 'طوعة', '<span class=\"hlight\">طوعة.</span> <font color=\"DarkGreen\"><b>[ طَ ع َ ]</font></b> (اِخ ) نام زنی که مسلم بن عقیل بخانه ٔ اوپناه برد. رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span> شود.<br /></font></div>'),
(178280, 'طوغ', '<span class=\"hlight\">طوغ .</span> (ترکی، اِ) لفظ ترکی بمعنی نشان فوج، و طاء مبدل از تای فوقانی است . (غیاث ) (آنندراج ).<br /></font></div>'),
(178281, 'طوغاب', '<span class=\"hlight\">طوغاب .</span> (اِخ ) شهری است به ارزن روم . (منتهی الارب ). رجوع به طوغان شود.<br /></font></div>'),
(178282, 'طوغات', '<span class=\"hlight\">طوغات .</span> (اِخ ) شهر و قلعتی از نواحی ارمنستان از اعمال ارزن روم . (معجم البلدان ).<br /></font></div>'),
(178283, 'طوغاجار', '<span class=\"hlight\">طوغاجار.</span> (اِخ ) از سران مغول و معاصر گیخاتوخان . رجوع به طُغاجار و رجوع به طغاجارنویان شود. (ادوارد برون ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨</span>).<br /></font></div>'),
(178284, 'طوغان', '<span class=\"hlight\">طوغان .</span> (ترکی، اِ) قسمی از باز شکاری . شاهباز. طُغان .<br /></font></div>'),
(178285, 'طوغان', '<span class=\"hlight\">طوغان .</span> (اِ) نامی که چون عمرو و زید (در عربی ) و پیِر و پُل (در فرانسه ) استعمال شودچنانکه درین شعر با تگین یکجا یاد شده <span class=\"hlight\">:</span> <br />پند از هر کس که گوید گوش دار<br />گر مثل طوغانش گوید یا تگین .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(178286, 'طوغان', '<span class=\"hlight\">طوغان .</span> (اِخ ) از سران لشکری اولجایتو سلطان و ظاهراً پسر امیر دانشمند بهادر سردار اولجایتوست . وی در فتح گیلان (<span class=\"hlight\" dir=\"rtl\">٧٠٦</span> هَ . ق .) همراه سلطان بود و نیز پس از کشته شدن امیر دانشمند بهادر به نیرنگ غوریان در پای قلعه ٔ اختیارالدین به دست جلال الدین محمد سام از نوکران خاصه ٔ ملک فخرالدین (صفر <span class=\"hlight\" dir=\"rtl\">٧٠٦</span>) و بهنگام گسیل داشتن اولجایتو امیر یساول و بوجای پسر دانشمند بهادر را بهرات برای سرکوبی ملک فخرالدین این طوغان با بقیه ٔ سپاه امیر دانشمند در طوس ببرادر پیوسته است و بشرحی که در حبیب السیر آمده ملک فخرالدین در اثنای جنگ درگذشته و محمدسام نیز سرانجام بدستور امیر یساول و به دست بوجای کشته شده است . رجوع به تاریخ مغول ص <span class=\"hlight\" dir=\"rtl\">٣٧٦</span> و <span class=\"hlight\" dir=\"rtl\">٣١١</span> شود.<br /></font></div>'),
(178287, 'طوغان', '<span class=\"hlight\">طوغان .</span> (اِخ ) شحنه ٔ قهستان و از امرای سخن سنج و زیرک مغول و از مقربین درگاه ارغون و همان کسی است که خواجه وجیه الدین هنگام حساب خواستن ارغون از او به صوابدید ناصحان ابیات ذیل را به وی نوشت :<br />چون ز نو بردم جوابی گردش گردون پیر<br />مشک من کافور گشت وارغوانم شد زریر<br />آه من سرد است چون باد خزان نبود عجب <br />چون بهار عمر ما را درستد ایام پیر<br />ماه و مهر و تیر با من سخت بدمهر اوفتاد<br />ای مسلمانان فغان از جور ماه و مهر و تیر<br />قامت چون تیر من چاچی کمان شد زآن سبب <br />یار دورانداز و از نزدیک خود ما را چو تیر<br />گوشمال حادثاتم داد گردون چون رباب <br />همچو چنگم لاجرم می آید از رگها نفیر<br />آنچه با من کرد گردون کرد با بسیار کس <br />بامدادی میر بودم در شبانگاهی اسیر<br />صاحب اعظم وجیه الدین بُدم دیروز من <br />ملک را فرمانده و شاه ممالک را وزیر<br />زر نهاده گنجها ازبهر دفع روز رنج <br />رنج من زر میفزود و زر نبودم دستگیر<br />تکیه بر مال کسان هرگز کسی چون من نکرد<br />مال من چون بازگشت و من بسان مالگیر<br />چون عزیز مصر بودم خوار گشتم همچو خاک <br />از من و دور فلک گر عقل داری پند گیر<br />سر بر آوردی بدولت پایمردی کن بلطف <br />دسترس دادت خدای افتادگان را دست گیر<br />کاین همان دهر است کز شاه اردوان بربود تاج <br />وین همان چرخست کز نوشیروان بستد سریر.<br />طوغان در جواب او نوشت :<br />سالها جام جم به دست تو بود<br />چون تو نشناختی کسی چه کند<br />گوهر شبچراغ بودت لیک <br />چون خود انداختی کسی چه کند<br />اسب رهوار بود و میدان خوش <br />چون تو بد تاختی کسی چه کند<br />برده بودی و نقشت آمده بود<br />چون تو کژ باختی کسی چه کند .<br />طوغان سرحلقه ٔ مخالفان جدی بوقا وزیر ارغون بود و دشمنان این وزیر دائماً پیش ایلخان از وی سعایت میکردند و طوغان وقتی حکایت خیانت بوقا را نسبت به سلطان احمد بگوش ارغون کشید و او را از استبداد چنین وزیری که همه قسم قدرت و قوت دارد ترساند...چون سرانجام به امر ارغون جوشکاب نواده ٔ هلاکو بوقا را گردن زد و پس از قتل وی کوکب سعادت سعدالدوله ٔ یهودی اوج گرفت و به وزارت ارغون رسید طوغان شحنه ٔ قهستان با وی نیز از در مخالفت درآمد، چه وی در فتنه ٔ امیر نوروز از طرف ایلخان مأمور حدود خراسان شد تا امیر نوروز را سرکوبی کند ولی وصول وی بخراسان با فرار امیر نوروز مصادف گردید و طوغان مراجعت کرد، سعدالدوله بدستیاری بعضی از دشمنان طوغان بر او اعتراض کرد که چرا زیادتر از آنچه حکم داشته اولاغ در اختیار خود گرفته است و برحسب یاسای چنگیزی امر داد تا او راهفده چوب زدند و این توهین که از جانب سعدالدوله درحضور جمعی از امرا بطوغان وارد آمد او را بر سعدالدوله خشمناک کرد و بیش از پیش در برانداختن او ساعی شد ولی چون ایلخان به وزیر خود کمال اعتماد داشت و هیچکس نمیتوانست از او پیش ارغون سخن بگوید چاره ای نبود جز آنکه مخالفین وزیر در انتظار فرصت بنشینند و جفاهای او را به خفّت تمام تحمل کنند. پس از فوت ارغون و بتخت نشستن گیخاتو (رجب <span class=\"hlight\" dir=\"rtl\">٦٩٠</span> هَ . ق .) و کشته شدن سعدالدوله ٔ یهودی، این سلطان امرائی را که در اواخر عهد ارغون و قبل از جلوس او راه خلاف رفته بودند سیاست کرد و مشاغل محوله ٔ به ایشان را به امرای دیگر سپرد و از میان ایشان فقط طوغان را به اولاد یکی از امراکه بسعی او بقتل رسیده بود سپرد تا بقصاص پدر کشتندش . رجوع به تاریخ مغول ص <span class=\"hlight\" dir=\"rtl\">٢٣٦</span> و <span class=\"hlight\" dir=\"rtl\">٢٤١</span> و <span class=\"hlight\" dir=\"rtl\">٢٤٦</span> شود.<br /></font></div>'),
(178288, 'طوغان', '<span class=\"hlight\">طوغان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی از دهستان اسفندآباد بخش قروه ٔ شهرستان سنندج در <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزارگزی شمال خاوری قروه و <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی شمال باختر دلبران . تپه ماهور و سردسیر با <span class=\"hlight\" dir=\"rtl\">٣٠٢</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات، لبنیات و حبوبات . شغل اهالی زراعت و گله داری . راه آن مالرو است و تابستان از طریق دلبران اتومبیل میتوان برد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(178289, 'طوغان پلوسرکان', '<span class=\"hlight\">طوغان پلوسرکان .</span> <font color=\"DarkGreen\"><b>[ طَ پ ُ س َ ]</font></b> (اِخ ) ده کوچکی است از دهستان اسفندآباد بخش قروه ٔ شهرستان سنندج نزدیک پلوسرکان . سکنه <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(178290, 'طوغلا', '<span class=\"hlight\">طوغلا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام رودخانه ای است . رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٢</span> شود.<br /></font></div>'),
(178291, 'طوغون', '<span class=\"hlight\">طوغون .</span> (اِخ ) پسر ایلکای نویان سردار مغولی اباقا که در جنگ ابلستین (ناحیتی به مشرق قیساریه ) میان لشکر مغول و معین الدین پروانه از یک سو و بیبرس از سوی دیگر روز جمعه ٔ دهم ذی القعده ٔ سال <span class=\"hlight\" dir=\"rtl\">٦٧٥</span> هَ . ق . اتفاق افتاد کشته شد. (تاریخ مغول ص <span class=\"hlight\" dir=\"rtl\">٢١٣</span>).<br /></font></div>'),
(178292, 'طوف', '<span class=\"hlight\">طوف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) طواف . طوفان .تطواف . (منتهی الارب ). مطاف . تجلس . گشت . شوط. دور گردیدن . گرد گردیدن . گرد برآمدن . (تاج المصادر). گرد ورآمدن . (زوزنی ). گرداگرد چیزی گردیدن . مطلق سیر و گشت . (غیاث ) (آنندراج ). گرد و پیرامون کعبه گشتن . (منتهی الارب ). گرد چیزی گشتن . (منتخب اللغات ) <span class=\"hlight\">:</span> و تاش بدان عزم است که حالی طوفی کند تا حشمتی افتد و هزاهزی در عراق افتاده است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٦٧</span>).<br />طوف کردم گرد کوی او برای روی او<br />ناگهان از چشمه های چشم من طوفان گرفت .<br /> <font color=\"Red\">سوزنی .</font><br />عید ایشان کعبه وز ترتیب پنج ارکان حج <br />رکن پنجم هفت طوف چار ارکان دیده اند.<br /> <font color=\"Red\">خاقانی .</font><br />پس از میقات حج ّ و طوف کعبه <br />حجار سعی و لبیک و مصلی .<br /> <font color=\"Red\">خاقانی .</font><br />هست به پیرامنش طوف کنان آسمان <br />آری بر گرد قطب چرخ زند آسیاب .<br /> <font color=\"Red\">خاقانی .</font><br />به وقت حاجت پیرامن آن طواف کرده و تضرع و زاری نموده ... (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤١٥</span>). <BR><font color=\"Blue\">◄</font> بقضا حاجت شدن . (تاج المصادر) (زوزنی ). رفتن بیرون برای قضای حاجت . (منتخب اللغات ). غائط کردن . ریستن . به حاجت گاه شدن . پلیدی انداختن . <BR><font color=\"Blue\">◄</font> دور کردن برزنان و آن کنایه از آرمیدن باشد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آمدن خیال در خواب .<br /></font></div>'),
(178293, 'طوف', '<span class=\"hlight\">طوف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) شناخ و آن مشکهای دم کرده با هم بسته مانند سطح ساخته که به وی از آن گذرند و اسباب خود را برند. (منتهی الارب ). مشکی چند که باد در آن دمند و با یکدیگر استوار ببندند چنانکه بصورت سطح هموار شود و برآن سوار شوند و از آب بگذرند. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> عسس . گاو نری که بر گرد گاو دیگر در خرمن کوبی حرکت کند. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پلیدی . ومنه الحدیث : لایصلین احدکم و هو یدافع الطوف و البول . (منتهی الارب ). غایط. (منتخب اللغات ). حدث مردم . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> قِلْد. (اقرب الموارد).<br /></font></div>'),
(178294, 'طوف', '<span class=\"hlight\">طوف .</span> (ع اِ) اخذه بطوف رقبته وبطاف رَقبته، و قد مر فی الصاد فی لغة الصوف . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن گنده ٔ پیر. (اوبهی ). زنی را گویند که بغایت پیر و کهنه شده باشد. (آنندراج ).<br /></font></div>'),
(178295, 'طوف شیرین', '<span class=\"hlight\">طوف شیرین .</span> (اِخ ) قصبه ای از دهستان حومه ٔ بخش هفتگل شهرستان اهواز در <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی جنوب هفتگل کنار شوسه ٔ هفتگل به طوف شیرین . جلگه، گرمسیر با <span class=\"hlight\" dir=\"rtl\">٢٠٠٠</span> تن سکنه . آب آن از لوله . محصول آنجا غلات . شغل اهالی کارگری شرکت نفت و زراعت و گله داری . دبستان دارد. ساکنین از طایفه ٔ هفت لنگ بختیاری هستند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178296, 'طوفال', '<span class=\"hlight\">طوفال .</span> (اِخ ) دهی از دهستان احمدآباد بخش فریمان شهرستان مشهد در <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی شمال باختری فریمان . دامنه و معتدل با <span class=\"hlight\" dir=\"rtl\">٤٤١</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و تریاک . شغل اهالی زراعت . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(178297, 'طوفان', '<span class=\"hlight\">طوفان .</span> (ع اِ)انقلاب سخت هوا. <BR><font color=\"Blue\">◄</font> باران سخت . (منتهی الارب ) (منتخب اللغات ). باران که همه جا رسد. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> آب بسیار که همه را بپوشد. (منتهی الارب ). آب که همه چیز را فراگیرد. آب که از زمین برآید و همه را غرق کند. سیل غرق کننده . (منتخب اللغات ). سیل یا آب که از زمین برآید و همه را غرق کند. و منه : فاخذهم الطوفان و قیل الغرق و قیل کثرة الماء و قیل العذاب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> هر چیز بسیار که احاطه کند تمام جماعت را. (منتهی الارب ). هر چیزی که بسیار و غالب باشد و همه را فروگیرد. (منتخب اللغات ). هر چیز بسیار و غالب باشد و همه را فروگیرد، چون طوفان باد و طوفان آتش و غیر آن . (آنندراج ). شدت باد تند. (غیاث ): طوفان دریا؛ آشوب آن <span class=\"hlight\">:</span> <br />علی بر جان جباران عالم <br />ببارید از سر صمصام طوفان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بسا شیران گردن کش بسا پیلان گردون وش <br />همه کوشنده چون آتش همه جوشنده چون طوفان .<br /> <font color=\"Red\">عبدالواسع جبلی .</font><br />هر دلی کز قبل شادی او شاد بود<br />گرْش طوفان غمان بارد غمگین نکند.<br /> <font color=\"Red\">سوزنی .</font><br />حج ما آدینه و ما غرق طوفان کرم <br />خود بعهد نوح هم آدینه طوفان دیده اند.<br /> <font color=\"Red\">خاقانی .</font><br />در تنور آن جای طوفان دیده وَاندر چشم دل <br />هم تنور غصه هم طوفان احزان دیده اند.<br /> <font color=\"Red\">خاقانی .</font><br />معصوم کی شوند ز طوفان لفظ من <br />کز نوح عصمت الا فرزند و زن نیند.<br /> <font color=\"Red\">خاقانی .</font><br />روز و شب بر خشک کشتی رانده ام <br />گرچه دایم غرق طوفان می زیم .<br /> <font color=\"Red\">عطار.</font><br />هرکه با نوح نشیند چه غم از طوفانش .<br /> <font color=\"Red\">سعدی .</font><br />غرقه در بحر چه اندیشه کند طوفان را.<br /> <font color=\"Red\">سعدی .</font><br />بود قطره ٔ آب طوفان مور.<br /> <font color=\"Red\">امیرخسرو.</font><br />ما که دادیم دل و دیده بطوفان بلا<br />گو بیا سیل غم و خانه ز بنیاد ببر.<br /> <font color=\"Red\">حافظ.</font><br />طوفان بچشم من نگر از این و آن مپرس <br />با دیده اعتبار نباشد شنفته را.<br /> <font color=\"Red\">قاآنی .</font><br /> <BR><font color=\"Blue\">◄</font> مرگ شتاب و سریع. (منتهی الارب ). مردن .(منتخب اللغات ). مرگی سخت . (مهذب الاسماء). قتل زود.(منتهی الارب ). کشتن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> سختی و تاریکی شب . (مهذب الاسماء). شب . شب بسیار تاریک . (منتهی الارب ).<br />طوفان خروش و طوفان خیز و طوفان دیده و طوفان رسیده و طوفان زای و طوفان زده و طوفان طرازو طوفان کده از ترکیبات اوست . (آنندراج ) <span class=\"hlight\">:</span> <br />یک لحظه نیست کاین مژه طوفان طراز نیست <br />وین دل چو شمع طعمه ٔ سوز و گداز نیست .<br /> <font color=\"Red\">طالب آملی .</font><br />دیده را سامان یک شبنم کلیم اول نبود<br />این زمانش موج حسن یار طوفان خیز کرد.<br /> <font color=\"Red\">کلیم .</font><br />زابراهیم ادهم پرس قدر ملک درویشی <br />که طوفان دیده از آسایش ساحل خبر دارد.<br /> <font color=\"Red\">صائب .</font><br />از ما حدیث زلف و رخ دلستان مپرس <br />طوفان رسیده را ز کنار و میان مپرس .<br /> <font color=\"Red\">صائب .</font><br />طاقت کجاست روی عرقناک دیده را<br />آرام نیست کشتی طوفان رسیده را.<br /> <font color=\"Red\">صائب .</font><br />داغ ناسور است نقش ماهی دریای عشق <br />تیغ سیراب است موج بحر طوفان زای عشق .<br /> <font color=\"Red\">صائب .</font><br />منم آن سیل که دریا نکند خاموشم <br />کوه را کشتی طوفان زده سازد جوشم .<br /> <font color=\"Red\">صائب .</font><br />چون کشتی طوفان زده آرام ندارم <br />هرچند که عاشق بشکیبائی من نیست .<br /> <font color=\"Red\">صائب .</font><br />کیفیت طوفان کده ٔ گریه مپرسید<br />از هر غم اشکم بنظر عالم آب است .<br /> <font color=\"Red\">بیدل .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوفان کردن </span> ؛ کنایه از کار بزرگ کردن . (آنندراج ) <span class=\"hlight\">:</span> <br />فیض مردان در زمان بیخودی افزونتر است <br />تیغ چون گردید عریان بیشتر طوفان کند.<br /> <font color=\"Red\">صائب .</font><br />میتوان دیدن ز کشتی اضطراب بحر را<br />حسن طوفان بیشتر در خانه ٔ زین میکند.<br /> <font color=\"Red\">صائب .</font><br />مگر آن خرمن گل تنگ خود را در بغل دارد<br />که طوفان میکند در مغز ما بوی گلاب امشب .<br /><font color=\"Red\">صائب .</font><br /></font></div>'),
(178298, 'طوفان', '<span class=\"hlight\">طوفان .</span> <font color=\"DarkGreen\"><b>[ طَ وَ ]</font></b> (ع مص ) طوف . گرد و پیرامون کعبه گشتن . (منتهی الارب ). گرد ورآمدن . (زوزنی ). گرد برآمدن . (تاج المصادر). گرد چیزی گشتن . (منتخب اللغات ).<br /></font></div>'),
(178299, 'طوفان مازندرانی', '<span class=\"hlight\">طوفان مازندرانی .</span> <font color=\"DarkGreen\"><b>[ ن ِ زَ دَ ]</font></b> (اِخ ) اسمش میرزا طیب و اصلش از ملک هزارجریب من توابع دارالمرز مازندران بوده . پس از تحصیل کمالات و کسب مقالات مهاجرتی و مسافرتی بعراق عجم پذیرفته، در صفاهان اهاجی رکیکه گفته و شنفته از معاصرین حاج لطفعلی بیگ آذر و سایر شعرای آن عهد بمزید ظرافت و لطافت طبع با امتیاز آمده سرانجام از اهاجی نادم شده و در عراق عرب و نجف مسوده ٔ هزلیات را به آب انابت شسته و در نعت و منقبت ائمه ٔ هدی خاصه حضرت ولی خدا طریق رستگاری جسته . در سنه ٔ<span class=\"hlight\" dir=\"rtl\">١١٩٠</span> هَ . ق . از تن رسته و بعالم ارواح پیوسته . هفت هزار بیت دیوان دارد و غالب آن غزلیاتست، بعضی از خیالاتش که فصاحتی دارد منظور میشود، از غزلیات اوست :<br />در خلوتی و سوزم ازین غم که برویت <br />چشم است همه رخنه ٔ دیوار در آنجا.<br />نبود نکوئیی که در آب و گل تو نیست <br />در حیرتم که رحم چرا در دل تونیست .<br />ز رحم نیست گر از خاکم آسمان برداشت <br />مرا براه تو افتاده دید از آن برداشت .<br />زین غم چه کنم کز سخن بوالهوسی چند<br />تو میروی و مانده ز عمرم نفسی چند<br />رحم آر بمرغان گرفتار و بیندیش <br />زین پیش که خالی بتو ماند قفسی چند.<br />دل گرفت از من و بشکست خدایا برسان <br />دل دیگر که ز من گیرد و دیگر شکند.<br />نمیدانم بمحشرحال آن عاشق چه خواهد شد<br />که نتوانست اینجا دست کس در دامنت بیند.<br />چنین کز کین به تیغم زد چنین کز شوق جان دادم <br />نه من خواهم شد از یادش نه او خواهد شد از یادم .<br />عقده ٔ مشکل من نیست بغیر از دل من <br />تا دلم خون نشود حل نشود مشکل من .<br />میل یاری داشت یار من به من <br />کرد خصمی روزگار من به من <br />تیغ نازد در کنار او به او<br />زخم گرید در کنار من بمن .<br />ای زآتش عشقت بدلم سوز امروز<br />وی سوز تو در جان غم اندوز امروز<br />گفتی که کدام روز خونت ریزم <br />قربان سر تو گردم امروز امروز.<br />در مدح حضرت شاه ولایت :<br />گر ز بحر فیض تو برداشتی یک قطره آب <br />تا قیامت کوکب رخشنده باریدی سحاب <br />در نقابت خلق دیدند وخدایت خوانده اند<br />خود خدا داند چه خوانندت چو بگشائی نقاب <br />بس که شورانگیز بد اشکم جدا از درگهت <br />یافتم از ساکنان هر بلد طوفان خطاب <br />تا نشستم با سگ کوی تو رفت از یاد من <br />چهره های نیمرنگ و دیده های نیمخواب <br />آن یکی زایر یکی خادم یکی مداح توست <br />من سگ کوی توام و اﷲ اعلم بالصواب .<br />در تتبع قصیده ٔ خاقانی و مدح شاه اولیا گوید:<br />جرمم آنجا که لنگر اندازد<br />گردش از چرخ اخضر اندازد<br />روزگار از گناه من هر دم <br />طرح سد سکندر اندازد<br />بحر عصیانم ار بجوش آید<br />شور در هفت کشور اندازد<br />با همه جرم خوشدلم که خدا<br />کار محشر به حیدر اندازد<br />بیشتر زآنکه باب دشمن او<br />نطفه در بطن مادر اندازد<br />آسمان طالعش کند جوزا<br />تا ز تیغش دوپیکر اندازد<br />این نه مدح تو شد که میگویند<br />بدو انگشت خیبراندازد<br />میرسد قدرت تو را که ز نو<br />طرح گردون دیگراندازد.<br />و هم او راست :<br />به خلق اگر نشوم رام عذر من بپذیر<br />زخودرمیده نگیرد بدیگری آرام <br />جهانیان همه را صبح و شام روز و شب است <br />چه از سفید و سیاه وچه ناتمام و تمام <br />نه من هم اهل جهانم کجا توانم گفت <br />که روز من همه شب گشت و صبح من همه شام <br />ز چرخ کام ندارم طمع که میدانم <br />چو من بکام رسم عالمی شود ناکام .<br />در مدح بتول عذرا:<br />مدح کسی کنم که بسوزد مرا زبان <br />اول بهفت آب بشویم اگر دهان <br />از شب هزار پرده برخسار روز بست <br />تا نام او ز دل بزبان برد آسمان <br />خیرالنسا بهار نبی گلشن ولی <br />ام الائمه فخر جهان و جهانیان .<br /><font color=\"Red\">(از مجمع الفصحا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤١</span> و <span class=\"hlight\" dir=\"rtl\">٣٤٢</span>).</font><br /></font></div>'),
(178300, 'طوفان نوح', '<span class=\"hlight\">طوفان نوح .</span> <font color=\"DarkGreen\"><b>[ ن ِ نو ]</font></b> (اِخ ) مصیبت و بلیه ای که بر بنی نوع بشر آمده و هیچ یک از بنی نوع بشر جز هشت نفر خانواده ٔ نوح رهائی نیافتند. (قاموس کتاب مقدس ). فروگرفتن قسمتی بزرگ یا همه ٔ زمین در زمان نوح . صاحب مرآت جهان نما آورده که : اهل تاریخ از سه طوفان نشان داده اند، اول طوفانی که پیش از آدم علیه السلام سانح شد چنانکه صاحب تاریخ حکما گفته که ظهور آدم علیه السلام در دوره ٔ اول اتفاق افتاده بود بعد از خرابی عالم بطوفان، و طوفان دوم در زمان نوح علیه السلام بود که از کوفه شروع شد وجهان را درگرفت، و طوفان سوم در زمانی که خاص به اهل مصر بوده و جم ّ غفیر از مفسران و جمعی کثیر از مورخان طوفان نوح علیه السلام را بهمه ٔ عالم نسبت میدهند و همین قول بر حق است و ظاهراً آیات قرآنی به این معنی ناطق است لیکن مغان انکار طوفان کنند و سکان خطا و سکنه ٔ چین به وقوع و شمول آن همه ٔ جهان را غلط انگارند و دانایان هنود از براهمه و سیوره و کهتری و سودر از حادثه ٔ طوفان انکار دارند و از وقوع آن منکرند. (آنندراج ). بلعمی در ترجمه ٔ تاریخ طبری آرد: «زندگانی نوح پیغمبر هزار سال بود کم پنجاه سال و چون پنجاه سال برآمد خدای عز و جل نوح را پیغمبری داد، نهصدوپنجاه سال خلق را بخدای عز و جل همی خواند چنانکه فرمود و لقد ارسلنا نوحاً الی قومه فلبث فیهم الف سنةالا خمسین عاماً، و بدین سالها اندر هیچ کس بر او نگروید تا آن روز که وقت طوفان بود، پس از هنگام نوح با آنکه به وی بگرویده بودند بکشتی اندر نشستند همه زن و مرد هشتاد تن بودند ومر نوح را پیغمبری بود بر همه ٔ اهل زمین و او پیغمبری مرسل بود و بدین نهصدوپنجاه سال اندر سه قرن مردم بجهان اندر فراز رسیدند و بروزگار نوح کودک از مادربیامدی و بزرگ شدی، پدر او را دست بگرفتی و پیش نوح بردی و نوح را به وی نمودی و گفتی این مرد دیوانه است و جادوگر، چون بالغ گردی بدو نگروی و اگر تو را فرزند باشد همچنین وصیت کن، نوح مر آن هنگامی که خلق را بخدای عز و جل خواندی مر او را بزدندی و خوار کردندی و صبر همی کردی، و نوح را زنی بود کافر چنانکه خدای تبارک و تعالی فرمود ضرب اﷲ مثلاً للذین کفروا امراءة نوح و امراءة لوط . از آن زن چهار پسر داشت، یکی سام و دوم حام و سیوم یافث، چهارم کنعان، و مادرشان کافر بود و بنوح بنگرویده بود، و چون سالیان ازین برآمد و نوح را صبر نماند و طاقتش برسید دعا کرد بهلاک قومش و ایدون گفت چنانکه خدای عزوجل فرمود به قرآن اندر چنین : و قال نوح رب لاتذر علی الارض من الکافرین دیاراً تا آخر سوره . پس خویشتن را دعا کرد و گفت : رب اغفر لی و لوالدی و لمن دخل بیتی مؤمناً و للمؤمنین و المؤمنات تا آخر آیه . و گفت یا رب ازین کافران هیچ خلق را بر پشت زمین دست بازمدار و همه را هلاک گردان و این فرزندان نیزکه از ایشان همی آیند و کافر همی گردند. پس پسر خویش را و مادر و پدر خویش را با آنکه مؤمن باشند آمرزش خواست و گفت مفزای برین کافران مگر هلاک . خدای تعالی دعایش مستجاب گردانید و مر او را بفرمود که ساج بنشان تا من این خلق را هلاک گردانم، و درخت ساج بچهل سال فرازرسید و نوح دانست که ایشان را تا چهل سال عذاب نیاید، نوح درخت ساج بنشاند و خلق را بخدای عزوجل خواند و صبر همی کرد با ایشان، چون درخت فرازرسید و چهل سال سپری شد ایزدتعالی وحی فرستاد سوی نوح و گفت من این خلق را به آب هلاک خواهم کردن، از زمین آب عذاب بر خواهم کشیدن و از آسمان آب عذاب فرودآورم، و نوح بزمین کوفه نشستی و در خانه ٔ وی یک تنور بود، آهنی که ازآن ِ آدم بوده بود و گفته بود که علامت عذاب این قوم آنست که آب از پره ٔ تنور بیرون آید، خدای عزوجل فرمود فاذا جاء امرنا و فار التنور . چون آب از تنور برجوشید نوح ترسید که اونیز هلاک شود، گفت نجّنی و من معی من المؤمنین . گفت یا رب من با این مؤمنان برهان . و خدای تعالی او را وعده کرد که تو را و اهل تو را برهانم و بس، خدای عزوجل بفرمودش که درخت ساج بیفکن و از وی تخته ها کن و جبرئیل فرمان داد تا بیامد و کشتی کردن مر نوح پیغمبر را علیه السلام بیاموخت . خدای عزوجل فرمود و اصنع الفلک باعیننا و وحینا و لاتخاطبنی فی الذین ظلموا انهم مغرقون . نوح کشتی بساخت و خلق بر وی همی گذشتند وکافران همی رسیدند که همی چه کنی، نوح گفتی که کشتی کنم که خدای عزوجل این خلق را به آب هلاک خواهد کردن، و ایشان را بر وی سخره و افسوس کردندی و سنگ انداختندی و نوح ایشان را پاسخ کردی و گفتی چنانکه بر من سخریه همی کنید من با این مؤمنان فردا با شما افسوس همی کنیم، خدای تبارک و تعالی فرمود: و یصنع الفلک و کلما مر علیه ملأ من قومه سخر و امنه تا آخر آیه . پس <font color=\"DarkGreen\"><b>[ آنگاه ]</font></b> نوح آن کشتی بچهل روز چوب کرد و درازی آن هزارودویست ارش بود و بالای دیوار کشتی سیصد ارش بود و آن را سه طبقه کرده بود، زیرین چهارپایان را و میانگی آدمیان و زبرین مرغان را چنانکه خدای عزوجل فرمود: قلنا احمل فیها من کل زوجین اثنین تا آخر آیه . چون هنگام طوفان بود خدای تبارک و تعالی بفرمود تا بیت المعمور را از جای برداشتند و به آسمان بردند وبجای خانه کوهی بنهاد تا آب عذاب بر آن جایگاه برنیاید و نیز فرمود مر نوح را تا استخوانهای آدم و حوا برداشت و بکشتی اندر آورد، پس نوح با مؤمنان که با وی بودند و بگرویده بودند بکشتی اندر آمدند و همه چهل مرد بودند و چهل زن چنانکه خدای عزوجل فرمود: و جعلنا ذرّیته هم الباقین تاآخر آیه . پس چهل شبان روز آب از زمین همی برآمد و ازآسمان همی فروبارید تا آب غلبه گرفت و کشتی از جای برداشت، پس نوح مر پسر را گفت : یا بنی ارکب معنا . و این پسر نوح شبان بود، گفت سآوی الی جبل یعصمنی من الماء. نوح گفت لا عاصم الیوم من امر اﷲ الا من رحم . بدین مناظره اندر بود که آب درآمد و او را غرقه کرد چنانکه خدای عزّوجل فرمود: و حال بینهما الموج و کان من المغرقین . نوح او را آواز داد چنانکه خدای تبارک و تعالی فرمود: و نادی نوح ربه فقال : رب ان ابنی من اهلی و اًن ّ وعدک الحق و انت احکم الحاکمین . قال اﷲ تعالی : یا نوح انه لیس من اهلک انه عمل غیر صالح تا آخر آیه . پس نوح گفت : رب انی اعوذ بک ان اسئلک ما لیس لی به علم تا آخرآیه . پس آنگاه خدای تبارک و تعالی باد را بفرمود تاهمه ٔ پرندگان را سوی نوح حشر کرد تا نوح از هر یک جفتی بگرفت و در کشتی با خویشتن بداشت و چون خر خواست که بکشتی اندر آید ابلیس بجست و دم خر را بگرفت و باز همی کشید هرچند او را همی زدند و براندند همی در نتوانست شدن از آنکه ابلیس او را باز عقب همی کشید تا نوح گفت اندررو یا ملعون، پس خر به کشتی اندر شد وابلیس با وی اندر شد، چون نوح مر ابلیس را بدید گفت ملعون تو بگفتار که اندرآمدی، ابلیس گفت بفرمان تو که من دم خر گرفته بودم و همی نگذاشتم تا وی اندررفتی، چون تو گفتی که یا ملعون اندرشو آن ملعون من بودم، اندرآمدم . پس آبها از آسمان بگشاد چنانکه خدای تعالی فرمود: ففتحنا ابواب السماء بماء منهمر و فجرنا الارض عیوناً تا آخر آیه . چون نوح دانست که کشتی بر سر آب آمد و به رفتن ایستادو گفت : بسم اﷲ مجریها و مرسیها . چندانی آب از روی زمین برآمد و از آسمان بگشاد که هرچه اندر جهان کوهی بود که از آن بلندتر نبودآب از سر آن کوه چهل ارش برگذشت از جهت آنکه کنعان بن نوح گفته بود و پنداشته که آن سیلی است چون دیگر بارانها از آنکه شبانی کردی و هرگاه که باران آمدی وی بکوه برشدی، آب او را گزند نتوانستی کردن و بدو رسیدن . این بار نیز پنداشت که همچنان است، چون نوح گفت :یا بنی ارکب معنا . کنعان گفت : سآوی الی جبل یعصمنی من الماء . و نوح شش ماه به کشتی اندر بود و بدین شش ماه اندر آب از آسمان و زمین بگسیخت و کشتی بدین شش ماه بجهان اندر همی گشت و بدانگه نوح از کوفه به کشتی اندر نشست و کشتی بمکه اندر شد و گرد حرم برگشت و طواف بکرد و باز بسوی مشرق شد و باز بزمین شام آمد، چون تمامی شش ماه ببود بایستاد بر سر آب برابر کوه جودی و خدای عزوجل آب از آسمان بازگرفت از پس ششماه که بزمین جنبنده نمانده بود مگر آنکه به کشتی اندر بودند، پس خدای عزوجل بفرمود مر چشمه های زمین را که آب فروبرید و آسمان را گفت آب بازگیر چنانکه خدای عزوجل فرمود و قیل یا ارض ابلعی مأک و یا سماء اقلعی و غیض الماء . و بدان که ابلعی فروبردن بود و اقلعی آب بازگرفتن بود و آن آب کمتر شد و کشتی بر سر کوه جودی بایستاد چنانکه خدای عزوجل فرمود: و قضی الامر و استوت علی الجودی و قیل بُعْداً للقوم الظالمین . یعنی القوم بدین فرمان خدای تعالی برفت بهلاک ایشان، چون نوح از کشتی بیرون آمد نگاه کرد جهان همه آب دید و آن همه مردم از کشتی بیرون آمده بودند و خلق افزونی و نوح خدای را سپاس داری کرد و گفت : الحمد ﷲ الذی نجانا من القوم الظالمین . و دیگر گفت رب انزلنی منزلاً مبارکاً و انت خیر المنزلین . و آن روز عاشورا بود وروز دهم بود از ماه محرم که بیرون آمدند و روز دهم از ماه رجب که به کشتی نشسته بودند، پس نوح بفرمود تا آن کس که با وی به کشتی اندر بودند آن روز روزه داشتند و این دو خلق زیادت که از کشتی بیرون آمده بودند یکی خوک بود و یکی گربه، اینان بزمین بر نبودند پیش از طوفان و خدای تعالی ایشان را بکشتی اندر آفرید زیرا که در کشتی سرگین یا پلیدی مردم بسیار شد و گند خواست و مردمان بیطاقت شدند، نزدیک نوح رفتند و گفتند که ما را اندرین گند طاقت نماند، دست به پشت پیل فرومالید خوک از کون بیرون جست و آن پلیدیها همه بخورد و آن گند بشر پس یکچند، ببود موش در کشتی بسیار گردید و طعامهاشان بخوردن گرفت و پلیدی همی کردند، پس مردمان باز سوی نوح شدند و گفتند از برکت تو از آن یک محنت برستیم اکنون موش ما را رنجه میدارد و جامه هامان همی برند و طعام ها همی پلید کنند و بخورند و بسیار گله کردند از موش، نوح دست به پشت شیر فرومالید، شیر یک عطسه بداد گربه ای از بینی او بیرون آمد و آن موشان را بخوردن گرفت و چون نوح از کشتی بیرون آمد وبر سر کوه جودی چهل شبان روز آنجا ببود تا آن آب عذاب بدریا افتاد، اکنون این آب تلخ و شور که بدریا اندر است از آن آب عذاب است که بروزگار طوفان آنجا افتاده ست و نوح مر زاغ را گفت که برو و بر زمین پای درنه و بنگر که آب چند مانده است، این زاغ بیامد و به ره اندر مرداری یافت بدان مشغول شد و بنزدیک نوح نشد، نوح را از آن اندوه آمد، دعای بد کردش، گفت خدای عزوجل تو را بچشم مردمان خوار کناد و طعامت جز مردار مباد، پس مر کبوتر را بفرمود رفتن، کبوتر هیچ جای درنگ نکرد و زود بیامد و پای به آب اندر نهاد، آب عذاب تلخ و شور بود، پای کبوتر بسوخت و موی از پایش بریخت و پوست بشد، اکنون این کبوتر را پای تا بدانجایگه که سرخست و موی برنیاید بدان که از نسل آن کبوتر است که بنزدیک نوح آمد و پای خویش وی را بنمود گفت آب تا آنجا مانده است، پس نوح بر وی دعا کرد و گفت خدای تعالی تو را به دل مردم شیرین گرداناد، اکنون از آنست که کبوتر به دل خلق اندر شیرین است، پس نوح بر زمین با آن کسان که با وی بودند «فرودآمد» و اندر همه ٔ جهان از مشرق تا مغرب هیچ بنا نمانده بود که نه همه خراب شده بود، پس نوح دیهی بنا کرد آن هشتاد تن که با وی بیرون آمدند بر سر کوه جودی بودند، هر یکی را خانه ای بنا کردند تا هشتاد خانه در آنجا برآورده آمد و هر یکی بدان خانه اندر شدند چنانکه یاد کردیم، خدای تبارک و تعالی فرمود و من آمن و ماآمن معه الا قلیل و این قلیل آن هشتاد تن را خواست و آن دیهی شد بزرگ و امروز آن ده آبادان است واین کوه جودی است و گروهی آن ده نوح خوانند و گروهی نیز سوق الثمانین خوانند، نوح از پس طوفان سیصد سال بزیست، و بدان که از گاه آدم علیه السلام تا گاه طوفان نوح دوهزارودویست سال بود، پس خدای عزوجل این خلق را از آن هشتاد بیرون آورد. و همه ٔ خلق جهان جهود و ترسا و مسلمان مقرند بطوفان نوح علیه السلام مگر مغان که ایشان نوح را نشناسند و نه طوفان دانند، و این مغان خود گویند که این جهان تا همه بوده است همیشه بوده است و از گاه آدم تا گاه یزدجردبن شهریار که پادشاهی عجم بر دست وی بشد به ایام عمربن الخطاب و جز ایشان پیداست در هر صحفی که از آسمان آمده است چون صحف ابراهیم و توریة موسی و انجیل عیسی و فرمان محمد (ص ) اندرین همه خبر طوفان و هلاک شدن قوم نوح و بودن نوح بزمین بابل پیداست، و نیز بعضی گویند که این طوفان خود آنجا بوده است، و بقرآن اندر چنانست که این طوفان بهمه جهان بوده است چنانکه خدای تبارک و تعالی فرمود و فجرنا الارض عیوناً، گفت از همه زمین آب بیرون آوردم و نگفت و فجرنا بعض الارض، تا بدانی که این طوفان بهمه جهان بوده است ...<br />و در مجمل التواریخ و القصص چنین آمده است : نوح النبی، خداوند سبحانه و تعالی او را به قوم فرستاد و نهصدوپنجاه سال دعوت کرد، روایتست که سوی بیوراسپ آمد بدعوت، و اوپادشاهی قاهر بود و اندر آن مدت هنوز هشتاد مرد و زن بدو ایمان آورده بودند تا ستوه گشت عظیم و به خدای تعالی دعا کرد و گفت : رب لاتذر علی الارض من الکافرین دیاراً . خدای تعالی دعوت او را مستجاب کرد و بفرمود تا درخت ساج بکشت و بعد چهل سال که برسید، سفینه بساخت، و نوح را پسران بودند چون سام و حام و یافث و کنعان و او کافر بود، پس چون وقت طوفان فرازرسید ایزدتعالی بیت المعمور را به آسمان چهارم برد و بجای آن کوهی بلند بیافرید آنجا که اکنون کعبه ٔ معظمه است تا آب عذاب آن را نرنجاند و بدانجا نرسد، نخستین آب بکوفه برآمد از آن تنور که علامت آن بود تا نوح در کشتی نشیند و داند که طوفان خواهد رسید، و اثر آن تنور اندر جامع کوفه بجایست، و قوله تعالی : و فار التنور، پس طوفان برآمدن گرفت از بالا و زیر، پسر نوح کنعان و بدیگر روایتی نام او یام گوید در کشتی ننشست با خود گفت چون آب غلبه گیرد بر کوه گریزم، نوح گفت : لا عاصم الیوم من امر اﷲ الا من رحم . اندرین سخن بود که موج آب طوفان او را درگردانیدو همه ٔ جانوران هلاک شدند، مگر آنکه با نوح علیه السلام در سفینه بودند از هر جنسی چنانکه حق تعالی فرمود: من کل زوجین اثنین، و آب چهل گز بالای کوه ها ایستاده بود و عوج عناقه را تا ساق بود، و اﷲ اعلم . و بیرون تاریخ خوانده ام که از بخار آب و تاریکی، روز از شب پیدا نبود و خداوند تعالی دو جوهر یکی سفید و دیگر سیاه نوح را داد که نور سفید به روز بر سیاه غلبه کردی و شب سیاه بر آن غالب شدی و از آن تأثیر روز از شب بازشناختی، و دو جانور زیادت آمد، گربه و خوک در سفینه که از موش و پلیدیها سرگین ستوه شدند و نوح دست بر روی شیر فرودآورد گربه از بینی وی اندرافتاد و از موش برستند و دست به روی فیل فرودآورد خوک همچنان از بینی وی بیفتاد و این هر دو جانور عظیم مانند بشیر و فیلند و پیش از طوفان نبودند، و گویند ابلیس علیه اللعنه دم خر بگرفت و در سفینه رفت نمی گذاشتندش تا نوح پیغامبر ضجر گشت و گفت ای ملعون ایذر چه کنی ؟ ابلیس گفت بفرمان تو آمدم که گفتی درآی ملعون و آن منم، پس ایزدتعالی تقدیر کرد که طوفان بنشیند چنانک گفت، قوله تعالی : و قیل یا ارض ابلعی مأک و یا سماء اقلعی و غیض الماء و قضی الامر و استوت علی الجودی . و اندر کتاب سیَر چنین خواندم که از سخونت آب عذاب، قیر کشتی همی گداخت، پس خدای تعالی نامی از نامهای بزرگ بیاموختش و آن نام : یاهیا و هم این نام ابراهیم علیه السلام همی خواند تا آتش بر او سرد گشت، پس نوح این نام میگفت و قیر می فشرد و از آن است که اکنون در نفطباشد و گویند یاهیا چون نوح از کشتی بیرون آمد نخستین عمارتی که بر زمین کردند دیهی بود که آن را سوق الشمامین خوانند نزدیک کوه جودی و همه هشتاد تن بودند و همه عمارت ...». (مجمل التواریخ ص <span class=\"hlight\" dir=\"rtl\">١٨٤</span> و <span class=\"hlight\" dir=\"rtl\">١٨٥</span> و <span class=\"hlight\" dir=\"rtl\">١٨٦</span>).صاحب تاریخ سیستان ذیل فصل «در فضیلت سیستان بر دیگر شهرها» گوید:... فضل دیگر آنست که بگاه غرق نوح علیه السلام که اندر کشتی گرد آفاق همی گشت کشتی آنجا <font color=\"DarkGreen\"><b>[ سیستان ]</font></b> بایستانید و کبوتر را بفرستاد تا خبر آورد نزدیک وی که عذاب برخاست و آب کمتر شد و آنجا دو رکعت نماز کرد اندر کشتی و کبوتر را دعا کرد که یا رب این عزیز گردان و آن بقعه را دعا کرد ببرکت و اکنون تا رستاخیز همیشه آن برکت بر آن مردمان باشد و بر آن ولایت . (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٩</span> و <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(178301, 'طوفریوس', '<span class=\"hlight\">طوفریوس .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (معرب، اِ) نوعی از کماذریوس است . طوقوریوس . (فهرست مخزن الادویه ). نوعی از کماذریون است . (تحفه ٔ حکیم مؤمن ). نوعی از کمادریوس است و آن گیاهی باشد سبزرنگ بسیار تلخ و بشیرازی زبان داروی تلخ گویند. (برهان ).<br /></font></div>'),
(178302, 'طوفی', '<span class=\"hlight\">طوفی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) صادقی گوید: مولانا طوفی، از اهل تبریز است، چون شاعری نداشت به سراجی اشتغال میورزید. گویند اکنون در آن ولایت ارباب نظم مسلمش دارند. در واقع شخصی صاحب سلیقه و افتاده است . در شهر لاهیجان به وی برخوردم، اوقاتش را بکیمیاگری میگذرانید و در آن فن رساله ای هم نوشته بود ولی نمی فهمید. بعنوان آزمایش از من پرسید: «حجری چند کلس دارد؟» گفتم تو حجر را بیان کن تا بگویم چند کلس دارد و معلوم شد که معنی حجر را نمیداند. شخصی بسیار ساده لوح است . بهرحال اشعار خوبی دارد و این ابیات از آن جمله است :<br />محبت یاد گیر ای بیمروت از خیال خود<br />که نگذارد مرا دور از تو یک ساعت بحال خود<br />به دست عجز جرأت کرده میکوبم در صلحی <br />که درشرم ابد دارد مرا فکر محال خود<br />جوان باید که عاشق دوست درددل شنو باشد<br />نه بدخوئی که با او عرض نتوان کرد حال خود.<br />تیر تغافل تو بجان خورده میروم <br />دانسته باش کز تو دل آزرده میروم <br />بدخوی التفاتم و عادت پذیر لطف <br />تاب تغافل تو نیاورده میروم .<br />ببین چه بیگنهم کز پی تلافی جور<br />به آشتی است هوس خوی تیزجنگ تو را.<br />در تب غم از عرق شستیم داغ خویش را<br />آب دادیم آتشین گلهای باغ خویش را.<br />بمحشر مایه ٔ رشک دگر باشد رقیبان را<br />که خواهند از تو ایشان داد و من خاموش بنشینم .<br />از حرف تهمتی که تو آزرده خاطری <br />طوفی خبر ندارد از آنها بجان تو.<br />بازم شکاف سینه ز تیغ نگاه کیست <br />روز دلم سیاه ز چشم سیاه کیست <br />دل در وفا و عهد تو بستن گناه من <br />بیگانگی و عهد شکستن گناه کیست <br />از راه عهد پای وفا چون کشید یار<br />چشم امیدواری طوفی براه کیست .<br />گریه بیش از همه برکشته و عشق تو کنند<br />گربدانند که بسمل شده ٔ خنجر کیست .<br />ترا محبت من گرم کرده میدانم <br />که اختلاط تو با من به اختیار تو نیست <br />تو از کجا و محبت کجا و مهر کجا<br />بمن گذار که کار من است کار تو نیست .<br />شود هر گلبنی رشک نهال وادی ایمن <br />گر از خاکسترم گردی صبا بر گلشن افشاند.<br />(از مجمع الخواص تألیف صادقی کتابدار ص <span class=\"hlight\" dir=\"rtl\">١٧٠</span> و <span class=\"hlight\" dir=\"rtl\">١٧١</span>).<br /></font></div>'),
(178303, 'طوق', '<span class=\"hlight\">طوق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) هرچه گِرد گیرد چیزی را. (منتهی الارب ). هرچه مدور بوده و گرد چیزی برآمده باشد. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> گردن بند. (منتهی الارب ) (منتخب اللغات ). هرچه در گردن افکنند. (مهذب الاسماء). زیوری که گرد گردن برآرند. حلقه ٔ زر و غیره که بدان گردن را زینت دهند. قلاده که زنان به گردن کنند و بر آن جواهر و سکه های زر آویزند. حلقه . (منتخب اللغات ). گردن بند که به رشته نباشد بلکه از یک پاره ٔ فلز و امثال آن بود. (در تداول فارسی طوق متصل واحد است و گردن بند به رشته کرده است ). پرگر. <BR><font color=\"Blue\">◄</font> طوق مرصعی که ملوک پیشین در گردن میکرده اند و گاه بگردن اسب می انداخته اند. (برهان ). در سابق از زر میساخته اند ومردم بزرگ گردن خود را بدان می آراستند <span class=\"hlight\">:</span> <br />بیک گردش بشاهنشاهی آرد<br />دهد دیهیم وطوق و گوشوارا.<br /> <font color=\"Red\">رودکی .</font><br />بدو گفت بی تو نخواهم جهان <br />نه اورنگ و نه تاج و طوق شهان .<br /> <font color=\"Red\">فردوسی .</font><br />ابا طوق زرین پرستنده شست <br />یکی جام زرهر یکی را به دست .<br /> <font color=\"Red\">فردوسی .</font><br />شهنشه به رستم قبائی بزر<br />ابا طوق زرین و تاج و کمر.<br /> <font color=\"Red\">فردوسی .</font><br />همان یاره و تاج و انگشتری <br />همان طوق و هم تخت گندآوری .<br /> <font color=\"Red\">فردوسی .</font><br />غلام و پرستار رومی هزار<br />یکی طوق پر گوهر شاهوار.<br /> <font color=\"Red\">فردوسی .</font><br />بیاراسته طوق یوز از گهر<br />بدو اندر افکنده زنجیر زر.<br /> <font color=\"Red\">فردوسی .</font><br />فرنگیس را گلشن زرنگار<br />بیاراست باطوق و با گوشوار.<br /> <font color=\"Red\">فردوسی .</font><br />ابا یاره و طوق و با گوشوار<br />به دست اندرون گرزه ٔ گاوسار.<br /> <font color=\"Red\">فردوسی .</font><br />یکی خلعت آراست پرمایه شاه <br />ز زرین وسیمین و اسب و کلاه <br />چه زرین کمرهای گوهرنگار<br />هم از یاره و طوق و از گوشوار...<br />بنزدیک خاقان فرستاد شاه <br />دو منزل همی بود با او براه .<br /> <font color=\"Red\">فردوسی .</font><br />غلامان رومی وچینی هزار<br />همه پاک با طوق و با گوشوار.<br /> <font color=\"Red\">فردوسی .</font><br />اَبَر پشت پیلانْش بر تخت زر<br />ز گوهر همه طوق شیران نر.<br /> <font color=\"Red\">فردوسی .</font><br />بزرگان که با طوق و افسر بدند<br />جهانجوی و از تخم نوذر بدند.<br /> <font color=\"Red\">فردوسی .</font><br />غلامان همه با کلاه و کمر<br />پرستنده با یاره و طوق زر.<br /> <font color=\"Red\">فردوسی .</font><br />ابا تاج و با طوق و با گوشوار<br />چنانچون بود درخور شهریار.<br /> <font color=\"Red\">فردوسی .</font><br />رخ دختران را بیاراستند<br />سر زلف بر گل بپیراستند<br />مگر مادرت بر سر افسر نداشت <br />همان یاره و طوق و زیور نداشت .<br /> <font color=\"Red\">فردوسی .</font><br />بیاراست زرین یکی زیر گاه <br />یکی طوق فرمود و زرین کلاه .<br /> <font color=\"Red\">فردوسی .</font><br />همی راند با تاج و با گوشوار<br />به زر بافته جامه ٔ شهریار.<br /> <font color=\"Red\">فردوسی .</font><br />ابا یاره و طوق زرین کمر<br />بهر مهره ای درنشانده گهر.<br /> <font color=\"Red\">فردوسی .</font><br />پرستار باشد ده ودوهزار<br />همه پاک با طوق و باگوشوار.<br /> <font color=\"Red\">فردوسی .</font><br />پرستار با طوق و با گوشوار<br />همان یاره و تاج گوهرنگار.<br /> <font color=\"Red\">فردوسی .</font><br />همه طوق بربسته و گوشوار<br />به بر بر همه جامه ها زرنگار.<br /> <font color=\"Red\">فردوسی .</font><br />ز یاقوت و پیروزه ٔ شاهوار<br />چه از طوق و از تاج و از گوشوار.<br /> <font color=\"Red\">فردوسی .</font><br />چون خلعتها بپوشید <font color=\"DarkGreen\"><b>[ مسعود ]</font></b> و تاج و طوق و آنچه رسم بود از آنجای آوردن اولیا و حشم نثارها پیش تخت بنهاد. (تاریخ بیهقی ). این بیعت که طوق گردن من است، عهد خداست . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣١٧</span>). تلک را بنواخت و خلعت بپوشانید از زر و طوق زرین مرصع بجواهر بگردن وی افکند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤١٤</span>). تاج مرصع بجواهر و طوق و یاره ٔ مرصع همه پیش بردند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٧٨</span>). سلطان خزینه دار را گفت طوق بیار مرصع بجواهر... بستد و تلک را پیش خواند و آن طوق به دست عالی خویش در گردن وی افکند و نیکوئیها گفت بخدمت ها که کرده بود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٠٥</span>).<br />عهد و بیان بس است تو را طوق و گوشوار<br />این هر دو یافتی چو شدی گوشدار من .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دل درویش را گو هوشیاری <br />ز دانش طوق ساز از هوش یاره .<br /> <font color=\"Red\">ناصرخسرو.</font><br />در گردن (خود) طوقش ارنداری <br />بر خشک بحیره مران سُماری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عدل و احسان تو طوقست درین گردن <br />غرقه ٔ عدل تو و بنده ٔ احسانم .<br /><font color=\"Red\">ناصرخسرو.</font><br />میسرایم ثنا و مدحت تو<br />طوق مهرت فکنده بر گردن .<br /> <font color=\"Red\">مسعودسعد.</font><br />و تخت و تاج و یاره و طوق و انگشتری، او <font color=\"DarkGreen\"><b>[ جمشید ]</font></b> کرد. (نوروزنامه ).<br />نه مرا بادحشمت و میری <br />نه مرا اسب و طوق سلطانی .<br /> <font color=\"Red\">سوزنی .</font><br />آن درخور او نیست ولی از پی ذوق <br />مرغک دهمش زاغ و سر فاخته طوق .<br /> <font color=\"Red\">سوزنی .</font><br />طوق و داغ تو را نماز برند<br />فلک از گردن و جهان ز سرین .<br /> <font color=\"Red\">انوری .</font><br />جان بدستار چه دهیم آنرا<br />کز غیب طوق در بر اندازد.<br /> <font color=\"Red\">خاقانی .</font><br />از آن نهاد تو چون پاک شد ببوته ٔ خاک <br />نه طوق و تاج شود چون ز بوته گشت جدا.<br /> <font color=\"Red\">خاقانی .</font><br />لیک من در طوق خدمت چون کبوتر بددلم <br />پیش شهبازی چنان زنهار چون باشد مرا.<br /> <font color=\"Red\">خاقانی .</font><br />دستارچه بین ز برگ شمشاد<br />طوق غیب سمنبران را.<br /> <font color=\"Red\">خاقانی .</font><br />ای که مردان عجم پیشت چو طفلان عرب <br />طوق در حلقند و نامت تاج مفخر ساختند.<br /> <font color=\"Red\">خاقانی .</font><br />کف در آن ساغر معلق زن چو طفل غازیان <br />کز بلور لوریانش طوق و چنبر ساختند.<br /> <font color=\"Red\">خاقانی .</font><br />نیمه ٔ قندیل عیسی بود یا محراب روح <br />تا مثال طوق اسب شاه صفدر ساختند.<br /> <font color=\"Red\">خاقانی .</font><br />طوق شمامت بعارض او محیط شد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٩٧</span>). چون طوق پیرامن شهر کات که نشیمن خوارزمشاه بود درآمدند و از هر جای فوجی کمین بگشادند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٦١</span>).<br />پس بفرمودش که برسازد ز زر<br />از سوار و طوق و خلخال و کمر.<br /> <font color=\"Red\">مولوی .</font><br />اگر از خدمتت دورم بجان شرمندگی دارم <br />چو قمری طوق بر گردن نشان بندگی دارم .<br /> <font color=\"Red\">؟</font><br />معروف چنانکه در پیدایش (سِفْر) مذکور است که فرعون محض احترام طوقی از طلا در گردن یوسف نهاد.(قاموس کتاب مقدس ). اطباق ؛ طوق بر افکندن . تطوق ؛ طوق در گردن خویش کردن . (تاج المصادر). کبر عن الطوق ؛ در حق شخصی گویند که ملابس چیزی گردد که کمتر از مرتبه ٔ او باشد و هو عمروبن عدی نصر ملک من ملوک حمیر و کان خاله جذیمة الابرش جمع غلماناً من ابناء الملوک، یخدمونه منهم عدی و کان جمیلاً فعشقته رقاش اخت جذیمةفقالت له اذا سقیت الملک فسکر فاخطبنی الیه فسقی عدی جذیمه و الطف له فلما سکر قال له سلنی ما احببت قال زوجنی رقاش اختک قال قد فعلت فعلمت رقاش انه سینکراذا افاق فقالت للغلام ادخل علی اهلک ففعل فاصبح فی ثیاب جدد و طیب فلما رآه جذیمة، قال ما هذا، قال انکحتنی اختک البارحة، قال ما فعلت و جعل یضرب وجهه و رأسه و اقبل علی رقاش و قال :<br />حدثینی و انت غیر کذوب <br />اء بِحُرّ زنیت ام بهجیز<br />ام بعبد و انت اهل لعبد<br />ام بدون و انت اهل لدون .<br />قال بل زوجتنی کفواً کریماً من ابناء الملوک فاطرق جذیمة فلما علم عدی، بذلک خاف فهرب و لحق بقومه و قام هنا لک و علقت منه رقاش و اتت بابن سماء جذیمة عمراً و تبناه و احبه حباً شدیداً و کان لایولد له فلما ترعرع کان یخرج مع الخدم یجتنبون للملک الکماة فکانوا اذا وجدوا کماة خیاراً اکلوها و اتوا بالباقی الی الملک و کان عمرٌو لایأکل منه و یأتی کما هو یقول :<br />هذا جنای و خیاره فیه <br />اذ کل جان یده الی فیه .<br />ثم انه خرج یوماً و علیه حُلی و ثیاب فاستطیرففقد زماناً فضرب فی الاَّفاق فلم یُوجد ثم وجده مالک ٌو عقیل ٌ ابنافارج رجلان من بُلقین کانا متوجهین الی جذیمة بهدایا فبینماهما بواد فی السماوة انتهی الیهما عمروبن عدی فسئلاه من انت، فقال ابن التنوخیه، فقالا لجاریة معهما اطعمینا فاطعمتها فاشار عمرو الیها ان اطعمینی فاطعمته ثم سقتهما فقال عمرو اسقینی فقالت الجاریة لانطعم العبد للراع فیطمع فی الدراع ثم انهما حملاه الی جذیمة فعرفه و ضمه و قبله و قال لهما حکمکما فسألاه منادمته فلم یزالا ندیمیه و بعث عمرو الی امه فادخلته الحمام و البسة و طوقته طوقاً کان له من ذهب فلما رآه جذیمة قال کبر عمرو عن الطوق، فذهبت مثلاً. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوق کسی بر گردن داشتن </span> ؛ کنایه از مطیع وی بودن . بندگی وی را بر عهده داشتن .<br /> <BR><font color=\"Blue\">◄</font> خطی چون حلقه ای بر گرد گردن کبوتر و امثال آن . دایره ای از پر برنگی جز رنگ سایر پرها گرد گردن پاره ای از مرغان <span class=\"hlight\">:</span> <br />طوق کبوتر است سر زلف آن نگار<br />من همچو باز در طلبش پر همی زنم .<br /> <font color=\"Red\">معزی .</font><br />جاه تو طوق فاختگان راگهر کند<br />گر مدحت تو فاختگان را ز بر شود.<br /> <font color=\"Red\">مسعودسعد.</font><br />تیغ سیم از دهن طوطی گویا بکنید<br />طوق مشک از گلوی قمری نر بگشائید.<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> حلقه ٔ آهنی متصل به زنجیر که بر گردن اسیران نهند <span class=\"hlight\">:</span> <br />تا غل ّ و طوق و بند که بر من نهاد<br />در دست و پا و گردن شیطان کنم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />همتش کاجری مسیح دهد<br />طوق در حلق قیصر اندازد.<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> رسنی که بدان بر بالای درخت خرما برآیند. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> طاقت . (منتخب اللغات ) (تاج المصادر). توان . توانائی . (منتهی الارب ) (دهار) (منتخب اللغات ). توانستن . وسع. گشادگی . (منتهی الارب ). تاب . ذرع . <BR><font color=\"Blue\">◄</font> نامی است که در رشت و رودبار به ابوطیلون دهند. رجوع به ابوطیلون شود. <BR><font color=\"Blue\">◄</font> زه گریبان . (مهذب الاسماء).طوقه . <BR><font color=\"Blue\">◄</font> چیزی از عالم عَلَم که شکل پنجه بر آن نصب کنند. (غیاث ). از عالم عَلَم که شکل پنجه بر آن نصب کنند، و در آئین کبری نوشته که آن بر دو گونه است، یکی چتر طوق از عالم علم است کوتاه تر از او قطاسی چند برافزایند، دوم تومان طوق هم از آن عالم لیکن از او درازتر در علمها این را پایه برتر نهند و آخرین به برزگ نوئینان اختصاص یابد. اگرچه طوق بدین معنی به طای دسته دار موسوم شده لیکن بعدِ تحقیق ثابت گشت . (آنندراج ).<br /></font></div>'),
(178304, 'طوق', '<span class=\"hlight\">طوق .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ )پدر مالک . دعبل در حق مالک بن طوق گوید <span class=\"hlight\">:</span> <br />الناس کلهم یسعی لحاجته <br />مابین ذی فرح منهم و مهموم <br />ومالک ظل ّ مشغولاً بنسبته <br />یرُم ّ منها خراباً غیر مرموم <br />یبنی بیوتاًخراباً لا انیس بها<br />مابین طوق الی عمروبن کلثوم .<br /> <font color=\"Red\">(از عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٧</span>).</font><br />مالک بن طوق، صاحب رحبه ٔ فرات که در زمان هارون الرشید بود. (منتهی الارب ).<br /></font></div>'),
(178305, 'طوق انداختن', '<span class=\"hlight\">طوق انداختن .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُو اَ ت َ ]</font></b> (مص مرکب ) سرخ یا سیاه شدن اطراف و پیرامون ریش و قرحه . سرخ یا سیاه شدن پیرامون چشم از لاغری یا بیماری .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178306, 'طوق باز', '<span class=\"hlight\">طوق باز.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُو]</font></b> (نف مرکب ) ظاهر آنست که از عالم شمشیرباز باشد، یعنی بازی کننده ٔ بطوق . خواجه نظامی راست <span class=\"hlight\">:</span> <br />سر زلف معشوق را طوق ساز<br />درافکن به این گردن طوق باز.<br />گردنی که بقید عشق خو کرده است و به طوق بازی عمر صرف نموده . (آنندراج ).<br /></font></div>'),
(178307, 'طوق بردن', '<span class=\"hlight\">طوق بردن .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُو ب ُ دَ ]</font></b> (مص مرکب ) آنست که مبارزان هنرمند بر سر نیزه یا مناره حلقه نصب میکنند و از دور تیر می اندازند بقصد آنکه از درون حلقه بگذرد، پس هرکه تیرش از حلقه گذر کرد این حلقه ازآن ِ وی باشد و از جمله ٔ اهل فن حلقه را او برده باشد، و گاهی این عمل به نیزه نیز کنند و این را حلقه ربائی نیز گویند. (آنندراج ) <span class=\"hlight\">:</span> <br />ز سیمین زنخ گوی انگیخته <br />بر او طوقی از غبغب آویخته <br />بدان طوق و گوی آن بت مهرجوی <br />ز مه طوق برده ز خورشید گوی .<br /><font color=\"Red\">نظامی (از آنندراج ).</font><br /></font></div>'),
(178308, 'طوق بهار', '<span class=\"hlight\">طوق بهار.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُو ق ِ ب َ ]</font></b> (ترکیب اضافی، اِ مرکب ) قوس قزح بود. (فرهنگ اوبهی ). آزفنداک . آفنداک . تیراژه . کمر رستم . کمردون . کمان رستم . نوشه . سریر. (حاشیه ٔ فرهنگ اسدی نخجوانی ). رخش . انطلیسون . نوشه . رنگین کمان . (لغت مصوب فرهنگستان ).<br /></font></div>'),
(178309, 'طوق سبز', '<span class=\"hlight\">طوق سبز.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُو ق ِس َ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از خط نودمیده .<br /></font></div>'),
(178310, 'طوق عنبر', '<span class=\"hlight\">طوق عنبر.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُو ق ِ عَم ْ ب َ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از نودمیدگی خط خوبان . (برهان ) (آنندراج ).<br /></font></div>'),
(178311, 'طوق عنبرینه', '<span class=\"hlight\">طوق عنبرینه .</span> <font color=\"DarkGreen\"><b>[ طَ<span class=\"hlight\" dir=\"rtl\">/</span> طُو ق ِ عَم ْ ب َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) طوق عنبر. کنایه از نودمیدگی خط خوبان . (آنندراج ).<br /></font></div>'),
(178312, 'طوق ماه', '<span class=\"hlight\">طوق ماه .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُو ق ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) هاله و خرمن ماه است و آن دائره ای باشد که در برخی از شبها از بخار بر دور ماه بهم میرسد. (برهان ) (آنندراج ).<br /></font></div>'),
(178313, 'طوقات', '<span class=\"hlight\">طوقات .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) رجوع به توقات شود.<br /></font></div>'),
(178314, 'طوقاتی', '<span class=\"hlight\">طوقاتی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) عمر صالح الفیضی التوقاتی . رجوع به توقاتی در معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٥٢</span> شود.<br /></font></div>'),
(178315, 'طوقدار', '<span class=\"hlight\">طوقدار.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُو ]</font></b> (نف مرکب، اِ مرکب ) اسم عامی فارسی قمری است . (فهرست مخزن الادویه ). کنایه از قمری و فاخته و کبوتر و مانند آن . (آنندراج ). قمری را نیز گویند. (برهان ) <span class=\"hlight\">:</span> <br />قمریَک طوقدار گویی سر در زده ست <br />درشبه گون خاتمی حلقه ٔ او بی نگین .<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> دارنده ٔ طوق .دارنده ٔ گردن بند <span class=\"hlight\">:</span> <br />همه طوقداران ابا گوشوار<br />سراپرده آراسته شاهوار.<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> کنایه از پسر امرد مخطط باشد. (برهان ). کنایه از جوان مخطط است . (آنندراج ). <BR><font color=\"Blue\">◄</font> بنده . اسیر. (برهان ) (آنندراج ). گرفتار. (برهان ).<br /></font></div>'),
(178316, 'طوقریوس', '<span class=\"hlight\">طوقریوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) حشیشةالطحال . رجوع به حشیشةالطحال شود. بنثریقه . یربه ٔ اسبلینی .<br /></font></div>'),
(178317, 'طوقلس', '<span class=\"hlight\">طوقلس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی اذخر است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178318, 'طوقلی داغ', '<span class=\"hlight\">طوقلی داغ .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام کوهی، و عین الفرات بدانجاست .<br /></font></div>'),
(178319, 'طوقه', '<span class=\"hlight\">طوقه .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُو ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (اِ) (اصطلاح گیاه شناسی ) منطقه ٔ فاصله ٔ میان ریشه و کونه با ساقه ٔ گیاه . <BR><font color=\"Blue\">◄</font> چرخه . قواره .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوقه ٔ چاه </span> ؛ حلقه ٔ آن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوقه ٔ یقه </span> ؛ زه گریبان .<br /></font></div>'),
(178320, 'طوقو', '<span class=\"hlight\">طوقو.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) بسریانی اسم دوقو است که تخم جزر بری باشد. (فهرست مخزن الادویه ).<br /></font></div>'),
(178321, 'طوقوریوس', '<span class=\"hlight\">طوقوریوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) نوعی از کماذریوس است . (فهرست مخزن الادویه ). طوفریوس . طوقریوس .<br /></font></div>'),
(178322, 'طوقی', '<span class=\"hlight\">طوقی .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طُو ]</font></b> (ص نسبی ) منسوب بطوق . طوقدار. <BR><font color=\"Blue\">◄</font> (اِ) قسمی انار.<br /></font></div>'),
(178323, 'طول', '<span class=\"hlight\">طول .</span> (ع مص ) دراز شدن . (منتهی الارب ) (منتخب اللغات ) (زوزنی ) (تاج المصادر).<br /></font></div>'),
(178324, 'طول', '<span class=\"hlight\">طول .</span> <font color=\"DarkGreen\"><b>[ طَ وَ ]</font></b> (ع اِمص ) درازی لفج برین شتر، یا عام است . (منتهی الارب ). درازی در لب بالائین شتر. (منتخب اللغات ).<br /></font></div>'),
(178325, 'طول', '<span class=\"hlight\">طول .</span> <font color=\"DarkGreen\"><b>[ طِ وَ ]</font></b> (ع اِ) طیل . پای بند ستور. رسن دراز که بدان ستور را بعلف بندند. گویند: ارخ للفرس طوله ؛ یعنی دراز کن رسن آن را. و طال طولک و طیلک ؛ یعنی دراز شدعمر تو یا درنگی یا غیبت تو. (منتهی الارب ). رسن که بدان پای چارپا بندند. رسن دراز که ستور را بدان بندند و سر دهند که بچرد. (منتخب اللغات ). رسن که بر پای ستور کنند و فروگذارند تا میچرد. (مهذب الاسماء).<br /></font></div>'),
(178326, 'طول', '<span class=\"hlight\">طول .</span> <font color=\"DarkGreen\"><b>[ طُوْ وَ ]</font></b> (ع اِ) مرغی است . (مهذب الاسماء). مرغیست آبی درازپا. (منتهی الارب ) (منتخب اللغات ). اسم طائری است پاهای آن طولانی . (فهرست مخزن الادویه ). درازپا (از مرغان ). <br /></font></div>'),
(178327, 'طول', '<span class=\"hlight\">طول .</span> <font color=\"DarkGreen\"><b>[ طُ وَ ]</font></b> (ع اِ) عمر. <BR><font color=\"Blue\">◄</font> دیری . <BR><font color=\"Blue\">◄</font> غیبت . <BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ طولی ̍. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سبع طول (در قرآن )</span> ؛ هفت سوره ٔ طویل قرآن و آن بقره و آل عمران و نساء و مائده و انعام و اعراف باشد، و در هفتمی خلاف کرده اند، بعضی سوره ٔ یونس گفته اند و بعضی سوره ٔ انفال و براءة را معاً یک سوره شمرده و جزء سبع طول نهاده اند. رجوع به سبع طوال شود.<BR>۩ سبع طُوَل (در شعر)؛ معلقه ٔ امروءالقیس و زهیر و عمرو و لبید و طَرَفة و حارث و عنترة.<br /></font></div>'),
(178328, 'طول', '<span class=\"hlight\">طول .</span> (ع اِمص، اِ) زیادت . فزونی . (منتهی الارب ) افزونی . (مهذب الاسماء). فضل . <BR><font color=\"Blue\">◄</font> علو. <BR><font color=\"Blue\">◄</font> سعه . فراخی . (منتهی الارب ) (منتخب اللغات ). دستگاه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> توانگری . (منتهی الارب )(منتخب اللغات ). غنی ̍. توانائی . (منتهی الارب ). قدرت . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> نیکوئی . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> من ّ: ذو الطول و المن <span class=\"hlight\">:</span> <br />جمال ملکت ایران و توران <br />مبارک سایه ٔ ذوالطول والمن .<br /> <font color=\"Red\">منوچهری .</font><br /><BR><font color=\"Blue\">◄</font> طُوَل . (منتهی الارب ). رجوع به طُوَل شود. طیل . <BR><font color=\"Blue\">◄</font> عمر. زندگانی . <BR><font color=\"Blue\">◄</font> غیبت .درنگی . (منتهی الارب ). گویند: طال طولک و طیلک ؛ ای مکثک او عمرک او غیبتک . <BR><font color=\"Blue\">◄</font> و یقال : لاآتیک طول الدهر؛ ای مدته . (مهذب الاسماء). طال طولک ؛ ای مدتک . (مهذب الاسماء).<br /></font></div>'),
(178329, 'طول', '<span class=\"hlight\">طول .</span> (ع اِمص، اِ) عمر. <BR><font color=\"Blue\">◄</font> غیبت . <BR><font color=\"Blue\">◄</font> درنگی . (منتهی الارب ). طُوَل . رجوع به طُوَل شود. طیل . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پهلوی مربع. (التفهیم ص <span class=\"hlight\" dir=\"rtl\">٢٥</span>). <BR><font color=\"Blue\">◄</font> درازی . (مهذب الاسماء). درازنا. بالا. بلندی . امتداد. استطاله . خلاف عرض . خلاف قصر. نقیض قصر. یکی ازسه بعد جسم که از دوی دیگر درازتر است . درازا <span class=\"hlight\">:</span> و عادت مردمان چنان رفته است که درازترین بعدی را طول نام کنند، ای درازا. (التفهیم ). اسکندر مردی بوده است با طول و عرض و بانگ و برق و صاعقه چنانکه در بهار و تابستان ابر باشد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٩١</span>).<br />گر طول وعرض همت او داردی سپهر<br />خورشید کی رسیدی هرگز بباختر.<br /> <font color=\"Red\">مسعودسعد.</font><br />مگر از طول ایام و امتداد مقام به ستوه آیند و از آن مقاتلت و منازلت روی بتابند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٥٠</span>).<br />و صاحب کشاف اصطلاحات الفنون گوید: طول بر معانی چندی اطلاق شود: نخست، امتداد واحدبطور مطلق یعنی بی آنکه با آن قیدی در نظر گرفته شود، و به این معنی گویند هر خطی فی نفسه طویل است یعنی آن خط فی نفسه بعد واحد و امتداد واحدی است . دوم، امتداد مفروض اول و آن یکی از ابعاد سه گانه ٔ جسمی است ودر مقابل آن عرض است که امتداد مفروض دوم است و عمق آن است که امتداد مفروض سوم باشد چنانکه در جسم مربع چنین است . سوم، از دو امتداد متقاطع در سطح آنچه طویل تر است طول باشد و این مفهوم میان جمهور علما مشهور است، و بدین معنی گویند: سطح چیزی است که دارای طول و عرض باشد. چهارم، امتدادی که از سر انسان به قدم او منتهی شود و امتدادی که از رأس چهارپایان به مؤخر آنها برسد چنانکه عرض را به امتدادی گویند که از یمین انسان یا چهارپایان به شمال آنها برسد و عمق را بر امتدادی اطلاق کنند که از سینه ٔ انسان به پشت او و از سینه ٔ چهارپایان به زمین برسد. در شرح مواقف در مباحث «کم » چنین است، و در شرح طوالع آمده است که : بعدی که از سر انسان بقدم او برسد طول انسان است وبعدی که از پشت چهارپایان به اسفل آنها برسد طول آنها باشد و بعدی را که از سمت راست انسان به سمت چپ او برسد عرض انسان خوانند و بعدی را که از سر حیوان به دم او منتهی گردد عرض آن خوانند.<br /></font></div>'),
(178330, 'طول', '<span class=\"hlight\">طول .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) منت نهادن بر کسی . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> فزونی کردن بر کسی . فخر نمودن . (منتهی الارب ). با کسی فضل کردن . (زوزنی ). در فضل غلبه کردن . (تاج المصادر). غالب آمدن در فضل . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> غالب آمدن در درازی، و منه فی حدیث استسقاء عمر فطال العباس عمر؛ ای غلبه فی طول القامة و کان عمر طویلاً و کان العباس اطول منه . (منتهی الارب ). بدرازی غلبه کردن . (تاج المصادر). <BR><font color=\"Blue\">◄</font> احسان کردن . (منتهی الارب ).<br /></font></div>'),
(178331, 'طول', '<span class=\"hlight\">طول .</span> (ع ص، اِ) ج ِ اطول و طولی ̍.<br /></font></div>'),
(178332, 'طول آرام', '<span class=\"hlight\">طول آرام .</span> (اِخ ) دهی از دهستان کوهسارات بخش مینودشت شهرستان گرگان در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی جنوب خاوری مینودشت . دامنه، معتدل مالاریائی با <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه . آب آن از چشمه سار. محصول آنجا غلات و ابریشم . شغل اهالی زراعت و گله داری و صنایع دستی زنان بافتن پارچه ٔ ابریشمی و چادر شب . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(178333, 'طول امل', '<span class=\"hlight\">طول امل .</span> <font color=\"DarkGreen\"><b>[ ل ِ اَ م َ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از حرص دنیاست . (غیاث ) (آنندراج ) <span class=\"hlight\">:</span> <br />با چنین کوتهی عمر بیان نتوان کرد<br />قصه ٔ طول امل را که سخن طولانی است .<br /><font color=\"Red\">محمدقلی سلیم .</font><br /></font></div>'),
(178334, 'طول اوسط', '<span class=\"hlight\">طول اوسط.</span> <font color=\"DarkGreen\"><b>[ ل ِ اَ <span class=\"hlight\" dir=\"rtl\">/</span> اُو س َ ]</font></b>(ترکیب وصفی، اِ مرکب ) طول معدل . دوری مرکز تدوین را از اوج طول اوسط خوانند و مقدار او آن زاویه است بر مرکز معدل المسیر که یکی خط را به اوج همی رسد و دیگر بمرکز تدویر و چون این زاویه بر مرکز عالم باشد مقدار طول معدل بود و فضله ٔ میان هر دو طول تعدیل طول باشد و اندازه ٔ او آن زاویه است که بر مرکز تدویر بود، از دو خطی که از مرکز معدل المسیر وز مرکز عالم آیند و همچند تعدیل خاصه ٔ نخستین باشد و بود که گاهگاه طول را مرکز نام کنند تا دانی . (التفهیم ص <span class=\"hlight\" dir=\"rtl\">١٢٥</span>).<br /></font></div>'),
(178335, 'طول بلد', '<span class=\"hlight\">طول بلد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ب َ ل َ ]</font></b> (ترکیب اضافی، اِ مرکب ) بُعدِ آن باشد از مشرق یا مغرب . بعدش است از نهایت آبادانی، خواهی این بعد را به معدل النهار با خط استوا گیر و خواهی بدان مدار که ایشان را موازی است زیرا که پاره های متشابه یک از دیگرنیابت دارند وز قبل آنکه منجمان زمین ما اصلهای یونانیان بکار همی دارند و سپس ِ رأی ایشان همی روند و یونانیان بنهایت مغربی از آبادانی نزدیکتر بودند و طول جایها از آنجا گرفتند، طول شهر بعدش گشت از نهایت آبادانی بمغرب ولکن اندرین نهایت میان ایشان خلاف است زیرا که گروهی از ایشان آغاز طول از لب دریای اوقیانوس همی کنند و گروهی آغاز او از جزیره های سعادت کنند و آن را نیز جزائر خالدات خوانند و این شش جزیره است برابر شهرهای مغرب از لب دریای اوقیانوس اندرون برفته بمقدار دویست فرسنگ و این هیچ زیان ندارد، هرگه که همه ٔ طولها از یک جای گرفته بود ولکن اندر کتابها، طول پاره ای از شهرها از لب دریا گرفته بود و پاره ای از جزائر سعد و تا مردم را فطنتی تیز نبود و بدین صناعت درست دانش آن را یک از دیگر جدا نتواند کردن . (التفهیم ص <span class=\"hlight\" dir=\"rtl\">١٧٢</span> و <span class=\"hlight\" dir=\"rtl\">١٧٣</span>). و صاحب کشاف اصطلاحات الفنون گوید: در نزد اهل هیئت عبارت از قوسی است از معدل النهار یک شهر و نصف نهار یکی از دو طرف آبادانی شرقاً یا غرباً، و توضیح آن اینست که دائره ٔ نصف النهار در مبداء آبادانی بسمت رأس اهلة میگذرد و معدل النهاررا بر نقطه ای قطع میکند و دائره ٔ نصف النهار در بلد مفروض بسمت رأس اهله میگذرد و معدل را بر نقطه ٔ دیگری قطع میکند و بنابراین قوس محصورشده از معدل میان دو نصف النهار واقع میشود که آن را طول آن بلد نامند.و مقصود از «یکی از دو طرف آبادانی » طرفی است که مبداء آبادانی است و منظور از «شرقاً و غرباً» اشاره به اختلاف در مبداء آبادانی است زیرا حکمای هند مبداء آبادانی را آخر آبادانی در جهت شرق در نظر گرفته اند، از اینرو که به آنان نزدیک است، و یونانیان آخر آبادانی را در جهت مغرب در نظر گرفته اند بعلت آنکه به آنها نزدیک است و بنابراین از نظر اول طول بلاد از مبداء به جهت شرق است و از نظر دوم به جهت غرب . و عبدالعلی بیرجندی در شرح تذکره آورده است که تعریف مذکور غیرمانع است زیرا هر دایره نصف النهار نخستین را بر دو موضع متقابل قطع میکند و ازینرو میان دو دایره ٔ مذکور چهار قوس از معدل به وجود می آید و طول بلد هم بجز یکی از چهار قوس مزبور نیست، همچنین تعریف یادشده غیرجامع است زیرا طول نهایت آبادانی از آن خارج میشود، چه نصف نهار آن با نصف نهار مبداء اتحاد دارد مگراینکه تغایر اعتباری را در نظر گیرند. و صواب اینست که بگویند: طول بلد عبارت از قوسی است از معدل النهار که از تقاطع آن با نصف ظاهر نصف نهار مبداء آبادانی آغاز میگردد و به تقاطع آن با نصف ظاهر از نصف نهار آن بلد منتهی میشود بشرط آنکه اگر مبداء جانب غرب باشد از ابتدا بر توالی شروع شود و اگر مبداء جانب شرق باشد برخلاف توالی آغاز گردد، سپس باید دانست بلدی را که زیر نصف نهار مبداء واقع است طولی نیست، همچنین اعتبار آن ممکن نیست چون عرض آن نود است و از اینرو که در اینجا نصف النهار تعیین نشده است - انتهی .<br /></font></div>'),
(178336, 'طول دادن', '<span class=\"hlight\">طول دادن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص مرکب ) امرار وقت کردن . به تأخیر انداختن .<br /></font></div>'),
(178337, 'طول عمر', '<span class=\"hlight\">طول عمر.</span> <font color=\"DarkGreen\"><b>[ ل ِ ع ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) درازی عمر. عمر دراز.<br /></font></div>'),
(178338, 'طول لات', '<span class=\"hlight\">طول لات .</span> (اِخ ) دهی جزء دهستان رحیم آباد بخش رودسر شهرستان لاهیجان در <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی جنوب باختری رحیم آباد کنار رودخانه ٔپلرود با <span class=\"hlight\" dir=\"rtl\">٩٥</span> تن سکنه . آب آن از پلرود. محصول آنجا برنج و لبنیات . شغل اهالی زراعت است . سر راه عمومی مالرو اشکور قرار دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(178339, 'طول معدل', '<span class=\"hlight\">طول معدل .</span> <font color=\"DarkGreen\"><b>[ ل ِ م ُ ع َدْ دَ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به طول اوسط شود.<br /></font></div>'),
(178340, 'طول و تفصیل', '<span class=\"hlight\">طول و تفصیل .</span> <font color=\"DarkGreen\"><b>[ ل ُ ت َ ]</font></b> (ترکیب عطفی، اِ مرکب ) از اتباع است . شرح و بسط.<br /></font></div>'),
(178341, 'طول و عرض قرار دادن', '<span class=\"hlight\">طول و عرض قرار دادن .</span> <font color=\"DarkGreen\"><b>[ ل ُ ع َ ق َ دَ ]</font></b> (مص مرکب ) چیز بی رتبه را عظیم القدر قرار دادن و مقرر کردن . (آنندراج ).<br /></font></div>'),
(178342, 'طول کشیدن', '<span class=\"hlight\">طول کشیدن .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) ادامه یافتن . بدرازا کشیدن .<br /></font></div>'),
(178343, 'طول کلام', '<span class=\"hlight\">طول کلام .</span> <font color=\"DarkGreen\"><b>[ ل ِ ک َ ]</font></b> (ترکیب اضافی، اِ مرکب ) اِطناب . درازی سخن .<br /></font></div>'),
(178344, 'طول کوکب', '<span class=\"hlight\">طول کوکب .</span> <font color=\"DarkGreen\"><b>[ ل ِ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> کُو ک َ ]</font></b> (ترکیب اضافی، اِ مرکب ) (اصطلاح هیئت ) عبارت از قوسی است از فلک البروج که از اول حمل شروع میشود و بمکان کوکب میرسد و آن را تقویم کوکب نیز نامند چنانکه اگر مکان کوکب حقیقی باشد طول حقیقی خواهد بود و اگر مرئی باشد طول هم مرئی خواهد بود. و اگر مکان کوکب بر نفس اول حمل باشد درین هنگام آن را تقویمی نخواهد بودو حرکتی را که بدان کوکب قوس موسوم به طول را قطع میکند، حرکت تقویمی و حرکت طولی نامند و گاهی طول بر این حرکت نیز اطلاق شود، و معنی مکان کوکب در ذیل کلمه ٔ مکان یاد خواهد شد انشأاﷲ. آنچه از تصانیف فاضل عبدالعلی بیرجندی مستفاد میشود چنین است . و در توضیح التقویم مسطور است که طول کوکب را چنانچه مسمی به تقویم کوکب کنند مسمی بهیئت کوکب نیز کنند - انتهی .<br /></font></div>'),
(178345, 'طولابی', '<span class=\"hlight\">طولابی .</span> (اِخ ) دهی از دهستانهای هرسم بخش مرکزی شهرستان شاه آباد در جنوب خاوری شاه آباد و <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی باختر هرسم . دشت و سردسیر با <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن سکنه . آب آن از سراب هرسم و محصول آنجا غلات و حبوبات و چغندرقندو توتون و لبنیات . شغل اهالی زراعت و گله داری . راه آن مالرو است و تابستان از طریق چشمه سنگی و پلنگ گرد اتومبیل میتوان برد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(178346, 'طولادای نویان', '<span class=\"hlight\">طولادای نویان .</span> (اِخ ) از سران لشکر گیخاتوخان مغول . وی در فتنه ٔ افراسیاب بن یوسفشاه لر از جانب گیخاتو با ده هزار سوار بدفع این اتابک لر رفت و پس از محاربه وی را دستگیر کرد و نزد گیخاتوآورد. طولادای را هنگام قتل گیخاتو و بسلطنت رساندن بایدو بزندان افکندند. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٧</span> و <span class=\"hlight\" dir=\"rtl\">١٠٣</span>).<br /></font></div>'),
(178347, 'طولارود', '<span class=\"hlight\">طولارود.</span> (اِخ ) دهی جزء دهستان گرگانرود جنوبی بخش مرکزی شهرستان طوالش در <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی جنوب طوالش کنار راه شوسه ٔ هشت پر به انزلی . جلگه، معتدل و مرطوب و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٢٠٩٤</span> تن سکنه . آب آن از رودخانه ٔ گرگانرود و طولارود. محصول آنجا غلات و برنج و عسل و به . شغل اهالی زراعت و شال بافی است . دو قهوه خانه سر راه شوسه دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(178348, 'طولازده', '<span class=\"hlight\">طولازده .</span> <font color=\"DarkGreen\"><b>[ دِه ْ ]</font></b> (اِخ ) دهی جزء دهستان مرکزی بخش لنگرود شهرستان لاهیجان در یکهزارگزی جنوب باختری لنگرود کنار راه فرعی لیلاکوه . جلگه و معتدل و مرطوب و مالاریائی با <span class=\"hlight\" dir=\"rtl\">١٦٩</span> تن سکنه .آب آن از استخر. محصول آنجا برنج و ابریشم و صیفی . شغل اهالی زراعت است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(178349, 'طولاس', '<span class=\"hlight\">طولاس .</span> (اِخ ) نام ناحیتی است به خزران و مردمان آن جنگی و با سلاح بسیار. (حدود العالم ).<br /></font></div>'),
(178350, 'طولان', '<span class=\"hlight\">طولان .</span> (اِخ ) طولن . رجوع به تولان جربی شود. (تاریخ جهانگشای ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١١</span>).<br /></font></div>'),
(178351, 'طولانی', '<span class=\"hlight\">طولانی .</span> (از ع، ص نسبی ) دیر. <BR><font color=\"Blue\">◄</font> دراز. بسیار دراز. طویل . بطول . کثیرالطول <span class=\"hlight\">:</span> <br />قلم به ختم سخن لب گزید یعنی بس <br />که دلنشین نبود گفتگوی طولانی .<br /><font color=\"Red\">درویش واله هروی .</font><br /></font></div>'),
(178352, 'طولدای', '<span class=\"hlight\">طولدای .</span> (اِخ ) از سران لشکر ارغون سلطان مغولی . پس از قتل گیخاتو از جانب بایدو تومانات عراق عجم به وی سپرده گشت . (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span> و <span class=\"hlight\" dir=\"rtl\">٤٨</span>).<br /></font></div>'),
(178353, 'طولس الاسکندرانی', '<span class=\"hlight\">طولس الاسکندرانی .</span> <font color=\"DarkGreen\"><b>[ ؟ سُل ْ اِ ک َ دَ ]</font></b> (اِخ ) از حکمای زمان فترت بین ابقراط و جالینوس . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br /></font></div>'),
(178354, 'طولع', '<span class=\"hlight\">طولع.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) قی . (منتهی الارب ).<br /></font></div>'),
(178355, 'طولمبه', '<span class=\"hlight\">طولمبه .</span> <font color=\"DarkGreen\"><b>[ ل ُ ب َ<span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ) نوعی از دهل و ساز معروف . (آنندراج ).<br /></font></div>'),
(178356, 'طولنبی', '<span class=\"hlight\">طولنبی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) الثمانی الطولنبی . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٥٢</span>).<br /></font></div>'),
(178357, 'طولندره پی', '<span class=\"hlight\">طولندره پی .</span> <font color=\"DarkGreen\"><b>[ ل َ دَرْ رَ پ َ ]</font></b> (اِخ ) نام دیهی در بخش بالاتجن از بارفروش . (مازندران و استرآباد تألیف رابینو ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>).<br /></font></div>'),
(178358, 'طوله', '<span class=\"hlight\">طوله .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِ) اسم اندلسی قیطل است که بیونانی سفیددلیون نامند. (فهرست مخزن الادویه ). فیطل . و رجوع به دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> شود.<br /></font></div>'),
(178359, 'طوله سرا', '<span class=\"hlight\">طوله سرا.</span> <font color=\"DarkGreen\"><b>[ ل َ س َ ]</font></b> (اِخ ) دهی از دهستان دابو از بخش مرکزی شهرستان آمل در <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی شمال خاوری آمل . دشت و معتدل و مرطوب و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٦٥</span> تن سکنه . آب آن از رودخانه ٔ هراز. محصول آنجا برنج و صیفی . شغل اهالی زراعت . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(178360, 'طوله کلا', '<span class=\"hlight\">طوله کلا.</span> <font color=\"DarkGreen\"><b>[ ل َ ک َ ]</font></b> (اِخ ) نام دیهی از توابع آمل مازندران . (مازندران و استراباد تألیف رابینو ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>). دهی است از دهستان دشت سر بخش مرکزی شهرستان آمل در <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی خاور آمل . دشت و معتدل و مرطوب و مالاریائی با <span class=\"hlight\" dir=\"rtl\">١٦</span> تن سکنه . آب آن از رودخانه ٔ هراز. محصول آنجا برنج و حبوبات و صیفی . شغل اهالی زراعت . راه آن مالرو است . این ده از دو محل بالا و پائین تشکیل شده است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(178361, 'طولواغریون', '<span class=\"hlight\">طولواغریون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) خربق ابیض است . (فهرست مخزن الادویه ). به یونانی خربق سفید است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178362, 'طولون', '<span class=\"hlight\">طولون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی عرطنیثا است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178363, 'طولون', '<span class=\"hlight\">طولون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) وزنی معادل نُه اوقیه، و آن را قوطول و اسکرجه ٔ کبیره نیز گویند. (مفاتیح ).<br /></font></div>'),
(178364, 'طولون', '<span class=\"hlight\">طولون .</span> (اِخ ) از غلامان امرای سامانی که حکمران سامانی بخاراوی را بعنوان هدیه نزد مأمون ببغداد فرستاد و او آنجا بمناصب عالیه رسید و پسرش احمد که در <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> هَ . ق . حائز مقام پدر شد و در <span class=\"hlight\" dir=\"rtl\">٢٥٤</span> به نیابت حکومت مصر مأمور گشت و مؤسس دولت بنی طولون شد. (ترجمه ٔ طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>). و رجوع به سفرنامه ٔ ناصرخسرو شود.<br /></font></div>'),
(178365, 'طولونی', '<span class=\"hlight\">طولونی .</span> (اِخ ) حسن بن حسین بن احمد الطولونی الحنفی (متولد بسال <span class=\"hlight\" dir=\"rtl\">٨٣٢</span> هَ . ق .). صاحب النزهة السنیة فی اخبار الخلفاء و الملوک المصریة. (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٥٢</span>).<br /></font></div>'),
(178366, 'طولونیه', '<span class=\"hlight\">طولونیه .</span> <font color=\"DarkGreen\"><b>[ نی ی َ ]</font></b> (اِخ ) (دولت طولون یا بنی طولون ) در مصر از <span class=\"hlight\" dir=\"rtl\">٢٥٤</span> تا <span class=\"hlight\" dir=\"rtl\">٢٩٢</span> هَ . ق . مؤسس آن احمدبن طولون . این سلسله را حکام خلفای عباسی برانداختند.<br /></font></div>'),
(178367, 'طولگیلان', '<span class=\"hlight\">طولگیلان .</span> (اِخ ) نام اراضیی که طایفه ٔ طولگیلان در آن ساکن هستند، جزء دهستان گرگانرود بخش مرکزی شهرستان طوالش در <span class=\"hlight\" dir=\"rtl\">٢</span> تا <span class=\"hlight\" dir=\"rtl\">٦</span> کیلومتری شمال هشت پر.جلگه و معتدل و مرطوب و مالاریائی با <span class=\"hlight\" dir=\"rtl\">١١٧٩</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات و برنج و لبنیات و عسل و گیلاس و سیب و به . شغل اهالی زراعت و شال بافی است . تابستان اهالی به ییلاق میروند و محل ییلاقی نیز بهمان نام نامیده میشود. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(178368, 'طولی', '<span class=\"hlight\">طولی .</span> <font color=\"DarkGreen\"><b>[ لا]</font></b> (ع ن تف ) تأنیث اطول . زن درازتر. ج، طُوَل . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِمص ) حالت و مرتبه ٔ بلند.<br /></font></div>'),
(178369, 'طولی', '<span class=\"hlight\">طولی .</span> (ص نسبی ) عمودی . مقابل عرضی و افقی . <br /></font></div>'),
(178370, 'طولیاب', '<span class=\"hlight\">طولیاب .</span> <font color=\"DarkGreen\"><b>[ طول ْ ]</font></b> (نف مرکب، اِ مرکب ) نوعی از طراز که در تعیین بلندی وپستی و همواری و ناهمواری زمین و دیوار بکار رود.<br /></font></div>'),
(178371, 'طولیدون', '<span class=\"hlight\">طولیدون .</span> (معرب، اِ) عنب الثعلب است . (اختیارات بدیعی ) (تحفه ). به یونانی دوائیست که بفارسی روباه تربک و بعربی عنب الثعلب خوانند. (برهان ) (آنندراج ).<br /></font></div>'),
(178372, 'طولیطون', '<span class=\"hlight\">طولیطون .</span> (معرب، اِ) قنطوریون صغیر است . (فهرست مخزن الادویه ) (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178373, 'طومار', '<span class=\"hlight\">طومار.</span> (ع اِ) قسمی خط عربی از نوع ثقال . (ابن الندیم ). <BR><font color=\"Blue\">◄</font> نامه . (منتهی الارب ) (منتخب اللغات ). نامه ٔ دراز. (تفلیسی ). ج، طوامیر. <BR><font color=\"Blue\">◄</font> دفتر. (منتهی الارب ). صحیفه . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> کاغذ نوشته، و امروز نوشته های لوله کرده را گویند. لوله ٔ کاغذ. لوله ٔ کاغذی و امثال آن که درنوردیده باشند. این کلمه یونانی است و آن را در مصر از پاپیروس می کرده اند و عرض آن بیش از بدستی و درازا گاه تا سی ذراع بوده است <span class=\"hlight\">:</span> ثم صاحت فی الدار یا جواری دواة وقرطاساً، و شمرت عن صاعدین کأنهما طومارا فضة، ثم حملت القلم و کبت . (المحاسن و الاضداد جاحظ ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span>).<br />اگرچه اندر وقتی زمانه را دیدم <br />که باز کرد نیارم ز بیم طی طومار.<br /> <font color=\"Red\">ابوحنیفه ٔ اسکافی .</font><br />آب خرد جوی و بدان آب شوی <br />خط بدی پاک زطومار خویش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />صد سالت اگر ز مکر او گویم <br />خوانده نشود خطی ز طوماری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مر خرد را بعلم یاری ده <br />که خرد علم را خریدار است .<br />نیک و بد زو بدان پدید آید<br />که خرد چون سپید طومار است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />طومار ندامت است طلع من <br />حرفی است هر آتشی ز طومارم .<br /> <font color=\"Red\">مسعودسعد.</font><br />گرچه صد بار بازگردد یار<br />سوی او بازگرد چون طومار.<br /> <font color=\"Red\">سنائی .</font><br />هر یکی را تیغ و طوماری به دست <br />در هم افتادند چون پیلان مست .<br /> <font color=\"Red\">مولوی .</font><br />آسمانها مثل طوماری پیچیده خواهند شد. (کتاب اشعیا <span class=\"hlight\" dir=\"rtl\">٣٤</span>:<span class=\"hlight\" dir=\"rtl\">٤</span>). به اصطلاح ارباب دفاتر از عالم برات و مانند آن بود که درازی داشته باشد، طوامیر جمع، و اطلاق آن بر نامه و کتاب و دفتر مجاز است . (آنندراج ). و رجوع به طامور شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طومار تصرف </span> ؛ کاغذی که رعایا و عمله و فعله محال جاگیر تصرف عمال را در آن نوشته میدهند تا به دست آویز آن زر منصرف را از آنها فهمیده بگیرند، و از همین عالم است طومار واصلات . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل طومار در هم پیچیدن </span> ؛ منهزم کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">یک طومار</span> ؛ سخت دراز.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">یک طومار گفتن </span> ؛بسیار گفتن .<br /></font></div>'),
(178374, 'طومار مصری', '<span class=\"hlight\">طومار مصری .</span> <font color=\"DarkGreen\"><b>[ رِ م ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به پیزر شود. ظاهراً همان قرطاس مصری است که از بردی یعنی لوخ و پاپیروس کردندی : و الروم تکتب فی الحریر الابیض و الرق و غیره و فی الطومار المصری و الفلجان . (ابن الندیم ).<br /></font></div>'),
(178375, 'طومارنویس', '<span class=\"hlight\">طومارنویس .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (نف مرکب ) حساب نویس . (آنندراج ).<br /></font></div>'),
(178376, 'طوماری', '<span class=\"hlight\">طوماری .</span> (ص نسبی ) منسوب به طومار. <BR><font color=\"Blue\">◄</font> خط و قلم جلی . مقابل غباری .<br /></font></div>'),
(178377, 'طوماری', '<span class=\"hlight\">طوماری .</span> (اِخ ) عیسی بن محمدبن احمدبن عمربن عبدالملک بن عبدالعزیربن جریج، مکنی به ابوعلی (<span class=\"hlight\" dir=\"rtl\">٢٦٢</span> - <span class=\"hlight\" dir=\"rtl\">٣٦٠</span> هَ . ق .). اهل بغداد است و چون صحبت ابوالفضل بن طومار هاشمی دریافت به طوماری مشهور گشت . وی از ثعلب و مبرد روایت کند. (المعرب جوالیقی حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br /></font></div>'),
(178378, 'طوماس', '<span class=\"hlight\">طوماس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) از حواریون عیسی (ع ). (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٣٣</span>).<br /></font></div>'),
(178379, 'طوماس', '<span class=\"hlight\">طوماس .</span> <font color=\"DarkGreen\"><b>[ طُ]</font></b> (اِخ ) آرتسرونی . مورخ قرن دهم م . (ترجمه ٔ ایران در زمان ساسانیان ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>).<br /></font></div>'),
(178380, 'طوماس', '<span class=\"hlight\">طوماس .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (اِخ ) مرگائی . مؤلف کتاب حکام که در<span class=\"hlight\" dir=\"rtl\">٨٤٠</span> م . نگاشته است و از روابط فرقه ٔ نسطوری با پادشاهان ایران بحث میکند و تاریخ عهد هرقل خسرو دوم را شرح میدهد. (ترجمه ٔ ایران در زمان ساسانیان ص <span class=\"hlight\" dir=\"rtl\">٤٧</span>).<br /></font></div>'),
(178381, 'طوماطالن', '<span class=\"hlight\">طوماطالن .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی عرطنیثاست . (فهرست مخزن الادویه ).<br /></font></div>'),
(178382, 'طوماغا', '<span class=\"hlight\">طوماغا.</span> (معرب، اِ) قنطوریون کبیر است . (فهرست مخزن الادویه ) (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178383, 'طومة', '<span class=\"hlight\">طومة.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (ع اِ) مرگ . <BR><font color=\"Blue\">◄</font> سختی . <BR><font color=\"Blue\">◄</font> سنگ پشت ماده . (منتهی الارب ). سلحفاة. (فهرست مخزن الادویه ).<br /></font></div>'),
(178384, 'طومخاج', '<span class=\"hlight\">طومخاج .</span> (اِخ ) کرسی ملک تاتار در چین . رجوع به طمغاج و طفقاج شود.<br /></font></div>'),
(178385, 'طومرا', '<span class=\"hlight\">طومرا.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) دهی از دهستان فارغان بخش سعادت آباد شهرستان بندرعباس . در <span class=\"hlight\" dir=\"rtl\">٤٠</span> هزارگزی خاور حاجی آباد و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی باختر راه سیاهو. کوهستانی و گرمسیر با<span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه . آب آن از چشمه . محصول آنجا خرما و غلات . شغل اهالی زراعت . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(178386, 'طومقرون', '<span class=\"hlight\">طومقرون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) قنطوریون صغیر است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178387, 'طونسلس', '<span class=\"hlight\">طونسلس .</span> <font color=\"DarkGreen\"><b>[ ن ُ ل ُ ]</font></b> (معرب، اِ) به یونانی گیاهی است خوشبوی که آن را بفارسی کاه مکه و بعربی اذخر خوانند. (برهان ) (آنندراج ).<br /></font></div>'),
(178388, 'طونیان', '<span class=\"hlight\">طونیان .</span> (اِخ ) دهی جزء دهستان طارم پائین بخش سیردان شهرستان زنجان در <span class=\"hlight\" dir=\"rtl\">٧٥</span>هزارگزی خاور سیردان و <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی راه مالرو عمومی . کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٣٤٧</span> تن سکنه . آب آن از چشمه و رود محلی . محصول آنجا غلات و گردو. شغل اهالی زراعت وگله داری و قالیچه و گلیم و جاجیم بافی است . راه آن مالرو و صعب العبورست . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(178389, 'طوپ', '<span class=\"hlight\">طوپ .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span>طُو ]</font></b> (ترکی، اِ) بترکی توپ را گویند. (آنندراج ).<br /></font></div>'),
(178390, 'طوپنار', '<span class=\"hlight\">طوپنار.</span> <font color=\"DarkGreen\"><b>[ طَ پ َ ]</font></b> (اِ) موش کور. ج، طوپنارات . رجوع به دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span> شود.<br /></font></div>'),
(178391, 'طوکثیر', '<span class=\"hlight\">طوکثیر.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) طباشیر. (فهرست مخزن الادویه ).<br /></font></div>'),
(178392, 'طوی', '<span class=\"hlight\">طوی .</span> <font color=\"DarkGreen\"><b>[ طَ وا ]</font></b> (ع اِ) خیک . <BR><font color=\"Blue\">◄</font> (مص، اِمص ) گرسنگی . (منتهی الارب ).گرسنه شدن . <BR><font color=\"Blue\">◄</font> باریک میان شدن . (زوزنی ).<br /></font></div>'),
(178393, 'طوی', '<span class=\"hlight\">طوی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) طَو. طاو. مرد لاغرشکم . شاعر گوید <span class=\"hlight\">:</span> <br />فقام فادنی من وسادی وساده <br />طوی البطن ممشوق الذراعین شرحب .<br /> <font color=\"Red\">؟ (ازمنتهی الارب ).</font><br />رجل ٌطوی البطن ؛ مرد باریک میان . (مهذب الاسماء).<br /></font></div>'),
(178394, 'طوی', '<span class=\"hlight\">طوی .</span> <font color=\"DarkGreen\"><b>[ طُ وا <span class=\"hlight\" dir=\"rtl\">/</span> طِ وا ]</font></b> (اِخ ) نام وادیی که موسی علیه السلام بدان وادی کلام حق تعالی بیواسطه شنید. (مهذب الاسماء). وادیی است که آن را وادی ایمن و وادی مقدس گویند. (منتخب اللغات ). موضعی است بشام نزدیک طور. (معجم البلدان ). یاقوت گوید: نامی عجمی است برای وادیی که در قرآن کریم مذکور است و در تلفظ آن چهار وجه جایز است : طوی بضم اول هم بی تنوین و هم با تنوین و اگر با تنوین خوانده شود نام وادیی است و مذکر باشد بر وزن فُعَل مانند عُظَم و صُرَد، و اگر با تنوین خوانده نشود غیرمنصرف خواهد بود چون دو سبب منع صرف در آن وجود دارد: یکی عدل یعنی از «طاو» معدول است و آنوقت مانند عمر است که معدول از عامر باشد، و دیگر اینکه نام علم برای بقعه باشد... و بکسر خوانده شود مانند مِعی ً <font color=\"DarkGreen\"><b>[ م ِعَن ْ ]</font></b> و طِلی ً <font color=\"DarkGreen\"><b>[ طِ لَن ْ ]</font></b>، و آنکه بتنوین نخواند آن را اسم مبالغه داند. رجوع به معجم البلدان شود.<br /></font></div>'),
(178395, 'طوی', '<span class=\"hlight\">طوی .</span> <font color=\"DarkGreen\"><b>[ طُ وا <span class=\"hlight\" dir=\"rtl\">/</span> طَ وا ]</font></b> (اِخ ) ذوطوی ؛ موضعی است نزدیک مکه . شاعر گوید <span class=\"hlight\">:</span> <br />اذا جئت اعلی ذی طوی قف و نادها<br />علیک سلام اﷲ یا ربة الخدر<br />هل العین ریا منک ام انا راجع<br />بهم ّ مقیم لایریم عن الصدر.<br /> <font color=\"Red\">(از معجم البلدان ).</font><br />و رجوع به ذوطوی شود.<br /></font></div>'),
(178396, 'طوی', '<span class=\"hlight\">طوی .</span> <font color=\"DarkGreen\"><b>[ طَ وا ]</font></b> (اِخ ) وادیی است به مکه . داودی گوید: آن ابطح است، و چنین نیست که گفته . (معجم البلدان ).<br /></font></div>'),
(178397, 'طوی', '<span class=\"hlight\">طوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (اِخ ) کوهی و چاههائی است بدیار محارب و آن کوه را قرن الطوی خوانند و عنتره و زُهیر ذکر آن در شعر خویش بکرده . زُبیربن ابی بکر گوید: طوی، چاهیست که عبدشمس بن عبدمناف بکند بالای مکه ... و سبیعة دختر وی بسرود <span class=\"hlight\">:</span> <br />ان الطوی اذا ذکرتم مأها<br />صوب ُ السحاب عذوبة و صفاء.<br /><font color=\"Red\">(از معجم البلدان ).</font><br /></font></div>'),
(178398, 'طوی', '<span class=\"hlight\">طوی .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی ]</font></b> (ع اِ) چاه از سنگ و جز آن برآورده . (منتهی الارب ). چاه پیراسته . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> پشتواره از سلاح و متاع . <BR><font color=\"Blue\">◄</font> ساعتی از شب . (منتهی الارب ).<br /></font></div>'),
(178399, 'طوی', '<span class=\"hlight\">طوی .</span> <font color=\"DarkGreen\"><b>[ طَ وا ]</font></b> (ع مص ) بی اراده نخوردن چیزی را. (منتهی الارب ).<br /></font></div>'),
(178400, 'طوی', '<span class=\"hlight\">طوی .</span> <font color=\"DarkGreen\"><b>[ طُی ْ ]</font></b> (ترکی، اِ) طو. عروسی <span class=\"hlight\">:</span> برادرزادگان با تو جمعیتی بزرگ ساختند و روزها طوی کردند. (جهانگشای جوینی ). چون بحدود آلمالیغرسیدند اورغنه خاتون به استقبال آمد و طویهای متواترکرد. (رشیدی ). و دیگر شهزادگان باتفاق موافقت نموده بهارگاه در قراقروم همچنین طویها کردند. (رشیدی ).<br /></font></div>'),
(178401, 'طوی دراز', '<span class=\"hlight\">طوی دراز.</span> <font color=\"DarkGreen\"><b>[ طُ دِ ]</font></b> (اِخ ) دهی است به سه فرسنگی مغرب کاکی، و طوی بمعنی چاه است . (فارسنامه ٔ ناصری ). و رجوع به طویل دراز شود.<br /></font></div>'),
(178402, 'طویة', '<span class=\"hlight\">طویة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) حصنی است به اسپانیا.<br /></font></div>'),
(178403, 'طویت', '<span class=\"hlight\">طویت .</span> <font color=\"DarkGreen\"><b>[ طَ وی ی َ ]</font></b> (ع اِ) راز. (منتهی الارب ). اندیشه . (دهار) (دستوراللغة). نیت . ضمیر. (منتخب اللغات ). دل . (مهذب الاسماء). درون <span class=\"hlight\">:</span> وجوه لشکر و اعیان و حشم را بخواند و گفت شما عادت من در خلوص عبودیت و صفای عقیدت و طویت و یکدلی و مناصحت و عرفان حق نعمت این پادشاه شناخته اید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٨١</span>). <BR><font color=\"Blue\">◄</font> قصد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> چاه . (منتخب اللغات ). چاه برآورده از سنگ . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پیچیدگی . (غیاث ) (آنندراج ).<br /></font></div>'),
(178404, 'طویجات', '<span class=\"hlight\">طویجات .</span> <font color=\"DarkGreen\"><b>[ طُ وَ ]</font></b> (اِخ ) دهی از دهستان رویسی بخش مرکزی شهرستان خرمشهر در <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی جنوب خرمشهر و یکهزار گزی باختر اتومبیل رو خرمشهر به آبادان . دشت، گرمسیر و مالاریائی . ساکنین از طایفه ٔ فیصلی هستند. <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. آب آن از شطالعرب است . محصول آن خرماست . شغل اهالی تربیت نخل و ماهیگیری . راه آن در تابستان اتومبیل رو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178405, 'طویجیه', '<span class=\"hlight\">طویجیه .</span> <font color=\"DarkGreen\"><b>[ طُ وَ جی ی َ ]</font></b> (اِخ ) دهی از دهستان جراحی بخش شادگان شهرستان خرمشهر در <span class=\"hlight\" dir=\"rtl\">٣٢</span> هزارگزی شمال خاوری شادگان و کنار رودخانه ٔ جراحی و کنار راه فرعی شادگان به خلف آباد. دشت و گرمسیر و مالاریائی با<span class=\"hlight\" dir=\"rtl\">٧٠</span> تن سکنه آب آن از رودخانه ٔ جراحی . محصول آنجا غلات . شغل اهالی زراعت و حشم داری است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178406, 'طویدره', '<span class=\"hlight\">طویدره .</span> <font color=\"DarkGreen\"><b>[ طَ دَ رَ ]</font></b> (اِخ ) دهی از دهستان مرکزی بخش کلاردشت شهرستان نوشهر در <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی شمال باختری حسن کیف . کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٤٦٠</span> تن سکنه، از ایل خواجوند. آب آن از چشمه . محصول آنجا غلات و لبنیات .شغل اهالی گله داری و زراعت و تهیه ٔ زغال و چوب . صنایع دستی زنان قالیچه و شال و جاجیم بافی . راه آن مالرو است . دبستان دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(178407, 'طویر', '<span class=\"hlight\">طویر.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) عبداﷲبیک (<span class=\"hlight\" dir=\"rtl\">١٨٦٦</span> - <span class=\"hlight\" dir=\"rtl\">١٩١٥</span> م .). صاحب روایة واقعة البرامکة. (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٥٣</span>).<br /></font></div>'),
(178408, 'طویرانی', '<span class=\"hlight\">طویرانی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) حسن حسنی باشا (<span class=\"hlight\" dir=\"rtl\">١٢٦٦</span> - <span class=\"hlight\" dir=\"rtl\">١٣١٥</span> هَ . ق .). منشی جریدة النیل و مجلات الشمس و الزراعة و المعارف بقاهره و صاحب تصانیف عدیده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٣</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٥٣</span>).<br /></font></div>'),
(178409, 'طویری', '<span class=\"hlight\">طویری .</span> <font color=\"DarkGreen\"><b>[ طُ وَ ]</font></b> (اِخ ) دهی از دهستان عمدادی بخش لنگه ٔ شهرستان لار در <span class=\"hlight\" dir=\"rtl\">١٢٢</span> هزارگزی شمال باختری لنگه و دامنه ٔ شمالی کوه چیرو. معتدل و مرطوب و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٥٦</span> تن سکنه . آب آن ازچاه و باران . محصول آنجا غلات و خرما. شغل اهالی زراعت . راه آن فرعی است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(178410, 'طویس', '<span class=\"hlight\">طویس .</span> <font color=\"DarkGreen\"><b>[ طُ وَ ]</font></b> (ع اِ مصغر) مصغر طاووس . (منتهی الارب ). طاووس خُرد.<br /></font></div>'),
(178411, 'طویس', '<span class=\"hlight\">طویس .</span> <font color=\"DarkGreen\"><b>[ طُ وَ ]</font></b> (اِخ ) عیسی بن عبداﷲ مکنی به ابوعبدالنعیم . مردی ظریف و عالم به تاریخ مدینه و انساب مردم آن بوده و دف نیکو می نواخت و از مشهورترین علماء فن غنا در صدر اسلام بود. مخنثی از عرب و او به شآمت مشهور بوده چه بشب وفات رسول (ص ) ولادت او (<span class=\"hlight\" dir=\"rtl\">١١</span> هجری ) و به روز مرگ ابوبکر از شیر بازگرفتن او و به روز قتل عمر بحد مردان رسیدن او و به روز قتل عثمان زن کردن او و به روز قتل علی (ع ) فرزند آوردن اوست، و مَثل «اشأم من طویس » از اینجاست . ابوالفتح بُستی گوید <span class=\"hlight\">:</span> <br />اء لم تَرَ ما اتاه ابوعلی <br />و کنت رآه ذا رأی و کیس <br />عَصی السلطان فابتدرت الیه <br />رجال یقلعون اباقبیس <br />و صَیَّرَ طوس معقله فصارت <br />علیه الطوس اشأم من طویس .<br />طویس تا روزگار مروان بن حکم بزیست و پس به سویداء (مکانی بفاصله ٔ دو شب راه بشمال مدینه ) نقل کرد و آنجا ببودتا درگذشت (<span class=\"hlight\" dir=\"rtl\">٩٢</span> هَ . ق .). رجوع به عقد الفرید ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥١</span> و ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩</span> و<span class=\"hlight\" dir=\"rtl\">٣٠</span> و <span class=\"hlight\" dir=\"rtl\">٣١</span> و <span class=\"hlight\" dir=\"rtl\">٦١</span> و عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢١</span> و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥٢</span> و مجمع الامثال میدانی ذیل مثل «اخنث من طویس » و اغانی و وفیات الاعیان و فهرست اعلام مقدمه ٔ ابن خلدون ترجمه ٔ محمدِ پروین گنابادی شود.<br /></font></div>'),
(178412, 'طویشه', '<span class=\"hlight\">طویشه .</span> <font color=\"DarkGreen\"><b>[ طُ وَ ش َ ]</font></b> (اِخ ) ده کوچکی است از دهستان بهمن شیر بخش مرکزی شهرستان خرمشهر در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی جنوب خاوری خرمشهر و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی باختری راه اتومبیل رو شادگان به آبادان با <span class=\"hlight\" dir=\"rtl\">١٠</span> تن سکنه . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(178413, 'طویع', '<span class=\"hlight\">طویع.</span> <font color=\"DarkGreen\"><b>[ طُ وَ ]</font></b> (اِخ ) ابوزیاد گوید: طوعة و طویع، از آبهای بنی العجلان است . شاعر گوید <span class=\"hlight\">:</span> <br />نظرت و دوننا علماً طویع<br />و منقاد المخارم من ذقان .<br /><font color=\"Red\">(از معجم البلدان ).</font><br /></font></div>'),
(178414, 'طویل', '<span class=\"hlight\">طویل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی از دهستان باوی بخش مرکزی شهرستان اهواز در <span class=\"hlight\" dir=\"rtl\">٢٢</span> هزارگزی جنوب اهواز و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی باختر راه آهن بندر شاهپور به اهواز. دشت و گرمسیر با <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه . آب از چاه . محصول آنجا غلات . شغل اهالی زراعت و گله داری . راه آن در تابستان اتومبیل رو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178415, 'طویل', '<span class=\"hlight\">طویل .</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی از دهستان مزرج بخش حومه ٔ شهرستان قوچان در <span class=\"hlight\" dir=\"rtl\">٣٥</span> هزارگزی شمال خاوری قوچان و <span class=\"hlight\" dir=\"rtl\">٣٢</span> هزارگزی خاور شوسه ٔ عمومی قوچان به باجگیران . کوهستانی و معتدل با <span class=\"hlight\" dir=\"rtl\">١٦٢</span> تن سکنه . آب آن از رود اترک . محصول آنجا غلات و تریاک . شغل اهالی زراعت و مالداری و قالیچه بافی . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(178416, 'طویل', '<span class=\"hlight\">طویل .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع ص ) دراز. ج، طِوال، طیال . (منتهی الارب ). بلند. نقیض قصیر. خلاف قصیر <span class=\"hlight\">:</span> <br />پیراهن قصیر بود زشت بر طویل <br />پیراهن طویل بود زشت بر قصیر.<br /> <font color=\"Red\">منوچهری .</font><br /> <BR><font color=\"Blue\">◄</font> دیریاز (شب ). <BR><font color=\"Blue\">◄</font> (اصطلاح طب ) قسمی از نبض و آن قوی و در طول ساعد باشد. <BR><font color=\"Blue\">◄</font> (اِ) خانه ٔ پنجم نرد از هفت بازی . <BR><font color=\"Blue\">◄</font> (اصطلاح عروض ) بحری از شعر. صاحب تاج العروس گوید: وزن آن هشت بار فعولن مفاعیلن، بر وزن این بیت امرءالقیس است :<br />الا انعم صباحاً ایها الطلل البالی <br />و هل ینعمن من کان فی العصر الخالی .<br />از بحور پانزده گانه و خاص عربست و شعرفارسی کمیاب است درین بحر، چرا که مطبوع نیست . شمس قیس در المعجم گوید : بدان که عجم را بر پنج بحر از بحور پانزده گانه شعر عذْب نیست و آن طویل است و مدید و بسیط و وافر و کامل و ما بیتی چند از اشعار قدما که در نظم آن تقیل به شعراء عرب کرده اند و برای اظهار مهارت خویش در علم عروض گفته، بیاریم تا ثقل آن معلوم گردد و دوری آن از طبع سلیم روشن شود:<br />ابیات طویل، بیت مقبوض ْ عروض سالم ْ ضرب که درین بحر تمامترین اشعار عربست :<br />بکاری چرا کوشی کز آن کار مر تو را<br />فعولن مفاعیلن فعولن مفاعلن <br />همی عاقبت خواهد رسیدن پشیمانی <br />فعولن مفاعیلن فعولن مفاعیلن .<br />بیت مقبوض ْ ضرب و عروض :<br />بدین عاشقی هرکو دهد پند مر مرا<br />فعولن مفاعیلن فعولن مفاعلن <br />همی گوز بر گنبد فشاند به ابلهی <br />فعولن مفاعیلن فعولن مفاعلن .<br />بیت مقبوض محذوف :<br />نگاری کجا همتا بخوبی ندانمش <br />فعولن مفاعیلن فعولن مفاعلن <br />چه گویی که را باشد بعشقش صبوری <br />فعولن مفاعیلن فعولن فعولن .<br />و صاحب کشاف اصطلاحات الفنون گوید:نزد عروضیان نام بحری است از بحور مختصه ٔ بتازیان وآن عبارتست از چهار بار فعولن مفاعیلن . و عروض این بحر پیوسته مقبوض استعمال شود. کذا فی عنوان الشرف . وجه تسمیه ٔ آن به طویل آنست که یک بیت آن چهل وهشت حرف می آید و هیچ بحر دیگر به چهل وهشت حرف مستعمل نمیشود، و بعضی گویند طویل از آنجهت گویند که مجزوء نمیآید و هرگز از هشت رکن کمتر نیست برخلاف بحور دیگر. و بعضی عکس طویل را، یعنی مفاعیلن فعولن چهار بار، عریض مقلوب طویل نامند. مثال طویل (شعر):<br />دلارام ما را گر به وعده وفا بودی .<br />بنوعی بدی کآخر تسلی ّ ما بودی .<br />کذا فی عروض سیفی، تمثیل آن به بیت فارسی منافی اختصاص آن بکلام عربی نبود، چه این بحر مستعمل در مجاورت اهل فارس کمتر است . و بعضی معانی طویل در لفظ طول مذکور شد.<br /></font></div>'),
(178417, 'طویل الباع', '<span class=\"hlight\">طویل الباع .</span> <font color=\"DarkGreen\"><b>[ طَ لُل ْ ]</font></b> (ع ص مرکب ) درازدست . (مفاتیح خوارزمی ). و رجوع به باع شود.<br /></font></div>'),
(178418, 'طویل البنات', '<span class=\"hlight\">طویل البنات .</span> <font color=\"DarkGreen\"><b>[ طَ لُل ْ ب َ ]</font></b> (اِخ ) کوهی میان یمامه و حجاز (طویل النبات بتقدیم نون بر باء نیز آمده است ). (معجم البلدان ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178419, 'طویل الزندین', '<span class=\"hlight\">طویل الزندین .</span> <font color=\"DarkGreen\"><b>[ طَ لُزْ زَ دَ ]</font></b> (ع ص مرکب ) آنکه استخوانهای هر دو ذراع آن بلند و بزرگ باشد. (منتهی الارب ).<br /></font></div>'),
(178420, 'طویل العمر', '<span class=\"hlight\">طویل العمر.</span> <font color=\"DarkGreen\"><b>[طَ لُل ْ ع ُ ]</font></b> (ع ص مرکب ) دراززندگانی . بسیارزیست .<br /></font></div>'),
(178421, 'طویل العولق', '<span class=\"hlight\">طویل العولق .</span> <font color=\"DarkGreen\"><b>[ طَ لُل ْ ع َ ل َ ]</font></b> (ع ص مرکب ) درازدم، و منه : هذا الکلام طویل العولق ؛ ای طویل الذنب . (منتهی الارب ).<br /></font></div>'),
(178422, 'طویل النبات', '<span class=\"hlight\">طویل النبات .</span> <font color=\"DarkGreen\"><b>[ طَ لُن ْ ن َ ]</font></b> (اِخ ) رجوع بطویل البنات شود.<br /></font></div>'),
(178423, 'طویل دراز', '<span class=\"hlight\">طویل دراز.</span> <font color=\"DarkGreen\"><b>[ طَ دِ ]</font></b> (اِخ ) دهی از دهستان چغاپور بخش خورموج شهرستان بوشهر در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی جنوب خورموج و دامنه ٔ خاوری کوه مند. جلگه و معتدل و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٤٧٢</span> تن سکنه . آب آن از چاه . محصول آنجا غلات و خرما. شغل اهالی زراعت . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(178424, 'طویلان', '<span class=\"hlight\">طویلان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی از دهستان کلیائی بخش اسدآباد شهرستان همدان در <span class=\"hlight\" dir=\"rtl\">٢٧</span> هزارگزی باختر قصبه ٔ اسدآباد و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی میوله . کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٩٦٠</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و لبنیات و توتون و صیفی و قلمستان . شغل اهالی زراعت و گله داری . صنایع دستی زنان گلیم و قالی بافی . راه آن مالرو است . در دو محل بفاصله ٔ <span class=\"hlight\" dir=\"rtl\">٤</span> هزار گز واقعند. و طویلان بالا و پائین نامیده می شوند. سکنه ٔبالا <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> تن است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(178425, 'طویلع', '<span class=\"hlight\">طویلع.</span> <font color=\"DarkGreen\"><b>[ طُ وَ ل ِ ]</font></b> (اِخ ) نام آبی بنی تمیم و پس از ایشان ازآن ِ بنی یربوع را. (معجم البلدان ).<br /></font></div>'),
(178426, 'طویلع', '<span class=\"hlight\">طویلع.</span> <font color=\"DarkGreen\"><b>[ طُ وَ ل ِ ]</font></b> (اِخ ) آبشخوری است به صمان . و در کتاب نصر آمده که طویلع وادیی است در راه بصره به یمامه میان دوّ و صمان . و در جامع الغوری آن موضعی است به نجد. اعرابی در رثاء کسی گفته <span class=\"hlight\">:</span> <br />و ای ّ فتی ً ودّعت یوم طویلع<br />عشیة سلمنا علیه و سلما<br />رمی بصدور العیس منحرف الفلا<br />فلم یدر خلق بعدها این یمما<br />فیا جازی الفتیان بالنعم اجزه <br />بنعماه نعمی و اعف ان کان ظالما.<br /><font color=\"Red\">(از معجم البلدان ).</font><br /></font></div>'),
(178427, 'طویلع', '<span class=\"hlight\">طویلع.</span> <font color=\"DarkGreen\"><b>[ طُ وَ ل ِ ]</font></b> (اِخ ) چاهی است کهنه در سواد شواجن که آب نزدیک و شیرین دارد. (منتهی الارب ). و رجوع به معجم البلدان شود.<br /></font></div>'),
(178428, 'طویلع', '<span class=\"hlight\">طویلع.</span> <font color=\"DarkGreen\"><b>[ طُ وَ ل ِ ]</font></b> (اِخ ) پشته ای است بمکه و بر آن خانه ها و مساکن اهل مکه است . (معجم البلدان ).<br /></font></div>'),
(178429, 'طویله', '<span class=\"hlight\">طویله .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِخ ) ده کوچکی است از دهستان بهمئی گرمسیر بخش کهکیلویه ٔ شهرستان بهبهان در <span class=\"hlight\" dir=\"rtl\">١٣</span> هزارگزی شمال باختری لک لک مرکزدهستان و <span class=\"hlight\" dir=\"rtl\">٤٢</span> هزارگزی شمال خاوری شوسه ٔ جایزان به آغاجاری با <span class=\"hlight\" dir=\"rtl\">٤٠</span> تن سکنه . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178430, 'طویله', '<span class=\"hlight\">طویله .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِخ ) دهی از دهستان جاوید بخش فهلیان و ممسنی شهرستان کازرون در <span class=\"hlight\" dir=\"rtl\">٦٤</span> هزارگزی خاور فهلیان و دامنه ٔ خاوری کوه طویله . معتدل و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٢٨٠</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات و حبوبات . شغل اهالی زراعت و قالی بافی . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(178431, 'طویله', '<span class=\"hlight\">طویله .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ<span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (از ع، ص ) تأنیث طویل . زن درازبالا. (منتهی الارب ): قصیره ای از طویله ؛ مختصری از مطول . خرمائی ازخرمابنی . <BR><font color=\"Blue\">◄</font> (اِ) رشته . سمط <span class=\"hlight\">:</span> <br />دوات راغرضی بود و همچنین غرض است <br />در آن طویله ٔ گوهر که یافتی ز پدر.<br /> <font color=\"Red\">فرخی .</font><br />ز رنگ و بوی همه خیره گشته دیده ٔ عقل <br />ز بس طویله ٔ یاقوت و بیضه ٔ عنبر.<br /> <font color=\"Red\">عنصری .</font><br />بر یاسمین عصابه ٔ درّ مرصع است <br />بر ارغوان طویله ٔ یاقوت معدنی .<br /> <font color=\"Red\">منوچهری .</font><br />مدار امید ز دهر دورنگ یکرنگی <br />که در طویله ٔ او با شبه ست مروارید.<br /> <font color=\"Red\">سنائی .</font><br />مرگ آخر آن طویله ٔ گوهر فروگسست <br />کز وی ستاره دید همی آسمان تر.<br /> <font color=\"Red\">سنائی .</font><br />ز صد طویله درّ یتیم یک شبه به <br />که ریزد از سر کلک تو بر صحیفه ٔ سیم .<br /> <font color=\"Red\">سوزنی .</font><br />از آل برهان ابیات من بقیمت عدل <br />اگرنه بیش کم از رشته ٔ درر نبود<br />طویله کردم و در گردن ملیح افکند<br />ملیح را به از این جنس زیب و فر نبود.<br /> <font color=\"Red\">سوزنی .</font><br />شده کیسه داردلها لبش از طویله ٔ دُر<br />زده کاروان جانها مهش از میان عقرب .<br /> <font color=\"Red\">اثیر اخسیکتی .</font><br />طویله ٔ سخنش سی ویک جواهر داشت <br />نهادمش ببهای هزارویک اسما.<br /> <font color=\"Red\">خاقانی .</font><br />ز درّ مدح تو صدرا طویله ها دارم <br />که عشر قیمت آن نیست در یسار کرم .<br /> <font color=\"Red\">رضی الدین نیشابوری .</font><br />کرده ٔ تو صحیفه ٔ خیر است <br />گفته ٔ تو طویله ٔ درر است .<br /> <font color=\"Red\">ظهیر.</font><br />و زمره ای را بر طویله ٔ اشقیا بسته . (جهانگشای جوینی ). <BR><font color=\"Blue\">◄</font> در استعمال فارسی بمعنی اصطبل، آخور، پایگاه و پایگه، پاگاه . مجازاً بمعنی مکان و عمارتی که در آن اسپان را نگاه دارند و آن عمارت اکثر جا طویل باشد که در آن چند اسب را مقام باشد، و کسانی که طویله را به یاء مجهول خوانند خطاست مگر آنکه این از تصرف فارسیان دانند چنانکه مدهوش و غوطه که هر دو لفظ به واو معروف است فارسیان به واو مجهول خوانند. (غیاث ) (آنندراج ) <span class=\"hlight\">:</span> <br />هست هر اسبی طویله ٔ او جدا.<br /> <font color=\"Red\">مولوی .</font><br />همی گریختم از مردمان بکوه و بدشت <br />که از خدای نبودم بدیگری پرداخت <br />قیاس کن که چه حالم بود در این ساعت <br />که در طویله ٔ نامردمم بباید ساخت .<br /> <font color=\"Red\">سعدی .</font><br />آن شنیدی که لاغری دانا<br />گفت باری به ابلهی فربه <br />اسپ تازی اگر ضعیف بود<br />همچنان از طویله ای خر به .<br /> <font color=\"Red\">سعدی .</font><br />دو فدائی را بطویله ٔ معین الدین فرستادند... تا هر کدام مناسب داند بطویله ٔ سلطان فرستند. (دستور الوزراء ص <span class=\"hlight\" dir=\"rtl\">١٩٨</span>).<br />گردید چون طویله حدیث رهی دراز<br />از بس که بستمش به یمین و یسار اسب .<br /> <font color=\"Red\">کاتبی .</font><br />در ورود به اردو خود را بطویله رسانید در سر کمند نشست . میرآخورباشی حقیقت را بعرض رسانید. (تاریخ گلستانه ).<br />اسب تازی در طویله گر ببندی پیش خر<br />رنگشان همگون نگردد طبعشان همگون شود.<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> رسنی که پای چارپای بدان بندند. (منتخب اللغات ).رسنی که بدان پای ستوران بندند. (منتهی الارب ). رسن دراز که بر پای اسبان بندند. (دستور اللغة). رسنی که پای چارپا به یک طرف آن بندند و سرش دهند تا بچرد. (منتخب اللغات ). رسن دراز که ستور را در علف بندند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اصطبل سر طویله ٔ جایگاه چارپایان در خانه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">میخ طویله </span> ؛ میخ بزرگ <span class=\"hlight\">:</span> <br />شاخ کَرگانْشان بود میخ طویله در سفر<br />چنگ شیرانْشان بود تعویذ اسبان در شکار.<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">هم طویله </span> ؛ همپایه <span class=\"hlight\">:</span> <br />ز اشک خاک رهم شد پر از طویله ٔ در<br />که هم طویله ٔ باد آمده ست پیمانت .<br /><font color=\"Red\">عمادالدین شهریاری .</font><br /></font></div>'),
(178432, 'طویله بستن', '<span class=\"hlight\">طویله بستن .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ب َ ت َ ]</font></b> (مص مرکب ) خیمه زدن . (آنندراج ).<br /></font></div>'),
(178433, 'طویله درق', '<span class=\"hlight\">طویله درق .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ دَ رَ ]</font></b> (اِخ ) دهی است جزء دهستان حومه ٔ بخش مرکزی شهرستان زنجان در <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی زنجان کنار راه مالرو قیدار. کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٢٢٢</span> تن سکنه . آب آن از چشمه .محصولات آنجا غلات و انگور. شغل اهالی زراعت و قالی وگلیم و جاجیم بافی . راه آن مالرو است و در فصل خشکی اتومبیل می توان برد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(178434, 'طویله ها', '<span class=\"hlight\">طویله ها.</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِخ ) از چهار آبادی کوچک بنام طویله ٔ بزرگ، طویله ٔ کوچک و کواکب و سادات تشکیل شده که در نزدیکی هم واقع و تابع بخش مرکزی شهرستان اهواز میباشند، در <span class=\"hlight\" dir=\"rtl\">٤٨</span> هزارگزی شمال خاوری اهواز و <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی جنوب راویس به هفتگل . دشت و گرمسیر با <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> تن سکنه . آب آن از چاه . محصول آنجا غلات . شغل اهالی زراعت و گله داری . راه آن در تابستان اتومبیل رو است . در اراضی طویله ٔ کوچک آثار ابنیه ٔ قدیمی وجود دارد که معروف به قصر است . ساکنین از طایفه ٔ جهود هستند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178435, 'طویله گاه', '<span class=\"hlight\">طویله گاه .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِخ ) دهی از دهستان کنگاور بخش کنگاور شهرستان کرمانشاه در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی باختر کنگاور و<span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی شمال شوسه ٔ کنگاور به کرمانشاه . دره و سردسیر با <span class=\"hlight\" dir=\"rtl\">٧٢</span> تن سکنه . آب آن از چشمه و نهر کبوترلانه . محصول آنجا غلات دیمی و آب و قلمستان . شغل اهالی زراعت . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(178436, 'طویله گاه', '<span class=\"hlight\">طویله گاه .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِخ ) دهی از دهستان هرسم بخش مرکزی شهرستان شاه آباد در <span class=\"hlight\" dir=\"rtl\">٣٢</span> هزارگزی خاور هرسم و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی تالاندشت . دشت و دامنه و سردسیر با <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> تن سکنه . آب آن از چاه .محصول آنجا غلات دیمی و لبنیات . شغل اهالی زراعت و گله داری . راه آن مالرو است و از انجیرک تابستان ممکن است اتومبیل برد. چادرنشین هستند و ساختمان ندارند وزمستان بحدود بخش ارکواز شهرستان ایلام میروند، و ازطایفه ٔ چوبین هستند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(178437, 'طپان', '<span class=\"hlight\">طپان .</span> <font color=\"DarkGreen\"><b>[طَ ]</font></b> (نف، ق ) بیقرار. بی آرام . مضطرب . طپنده . در حال طپیدن . ضجر. هلوع . (منتهی الارب ). تپان <span class=\"hlight\">:</span> <br />طپان ماده بفتاد و نر برپرید<br />بیامد همانجا که بد آرمید.<br /><font color=\"Red\">اسدی (گرشاسبنامه ).</font><br />شب دیده بر سپهر و بر انجم گماشتم <br />تا خود نظیر نجم کله دوز من کدام <br />دیدم همه طپان و بی آرام و شوخ چشم <br />او بازآرمیده و پرشرم و کش خرام .<br /> <font color=\"Red\">سوزنی .</font><br />دل اندر برطپان از بهر یارش <br />چو شب تاریک گشته روزگارش .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(178438, 'طپاندن', '<span class=\"hlight\">طپاندن .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b> (مص ) فروبردن . فروکردن .<br /></font></div>'),
(178439, 'طپانچه', '<span class=\"hlight\">طپانچه .</span> <font color=\"DarkGreen\"><b>[ طَ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ) طبانچه . اصلش تپانچه است . سیلی . چک . طپنچه . لطمة. زخم با کف دست . توگوشی . بناغوشی . بناگوشی (در تداول گناباد). طماچه <span class=\"hlight\">:</span> <br />خان بزاری و بخواری بازگشت <br />از طپانچه لعل کرده روی و ران .<br /> <font color=\"Red\">فرخی .</font><br />گشت بناخن چو پیرهنش مرا روی <br />شد ز طپانچه مرا چو معجر او بر.<br /> <font color=\"Red\">مسعودسعد.</font><br />نرگس او شد ز دیده همچو نیلوفر در آب <br />وز طپانچه دو رخ من رنگ نیلوفر گرفت .<br /> <font color=\"Red\">مسعودسعد.</font><br />از طپانچه گشته رخسارش چو نار و پس بر او<br />قطره های اشک بر چون دانه های ناردان .<br /><font color=\"Red\">وطواط.</font><br /></font></div>'),
(178440, 'طپانچه خوردن', '<span class=\"hlight\">طپانچه خوردن .</span> <font color=\"DarkGreen\"><b>[ طَ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ دَ ]</font></b> (مص مرکب ) سیلی خوردن . چک خوردن . طپنچه خوردن . لطمه خوردن . زخم با کف دست خوردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طپانچه از روزگار خوردن </span> ؛ رنج و تعب کشیدن . رجوع به مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">١٨١</span> شود.<br /></font></div>'),
(178441, 'طپانچه خوری', '<span class=\"hlight\">طپانچه خوری .</span> <font color=\"DarkGreen\"><b>[ طَ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ خوَ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ ]</font></b> (حامص مرکب ) طپانچه خوردن <span class=\"hlight\">:</span> <br />چو از نان طبلی تهی شد تنم <br />چو طبل از طپانچه خوری نشکنم .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(178442, 'طپانچه زدن', '<span class=\"hlight\">طپانچه زدن .</span> <font color=\"DarkGreen\"><b>[ طَ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ زَ دَ ]</font></b> (مص مرکب ) سیلی زدن کسی را. چک زدن . طپنچه زدن . لطمه زدن . زخم با کف دست زدن . ضفد. خمش . طرف . ذح . سفع. سفق . لفخ . لظه . لطس . لخ . لمه .طر. لخم . لدم . لخب . لهط. موج . (منتهی الارب ): سفق، مطس ؛ طپانچه بر روی کسی زدن . لباخ، تلاطم، ملاطمة، لطام، ملامخه، لماخ ؛ طپانچه با هم زدن و یکدیگر را طپانچه زدن . لطع؛ طپانچه زدن بر چشم . لطم ؛ طپانچه زدن بر رخسار و اندام . فشخ ؛ طپانچه زدن بر سر کسی . (منتهی الارب ) <span class=\"hlight\">:</span> بناطوش کس فرستاد سوی کسری که بندوی را سوی من فرست تا دستش ببرم که وی طپانچه بر روی من زد و اگر نه جنگ را بیارای . (ترجمه ٔ طبری بلعمی ).<br />به یکی گرم طپانچه که بر آن آلرتو<br />برزدم جنگ چه سازی چکنی بانگ ژغار.<br />بوالمثل بخاری (از حاشیه ٔ فرهنگ اسدی نخجوانی ).<br />ز گفتار هر دو پشیمان شدند<br />طپانچه به رخسارگان برزدند.<br /> <font color=\"Red\">فردوسی .</font><br />ز بس طپانچه که هر شب به روی برزدمی <br />بروز بودی بر روی من هزار نشان .<br /> <font color=\"Red\">فرخی .</font><br />مادر موسی طپانچه بر روی خود زد. (قصص الانبیاءص <span class=\"hlight\" dir=\"rtl\">٩٠</span>).<br />خود از در ریغ بر زمین زد<br />بسیار طپانچه بر جبین زد.<br /> <font color=\"Red\">نظامی .</font><br />زنم چندان طپانچه بر سر و روی <br />که یارب یاربی خیزد ز هر موی .<br /> <font color=\"Red\">نظامی .</font><br />لیلیش چنان طپانچه ای زد<br />کافتاد برو چو مرده بیخود.<br /> <font color=\"Red\">نظامی .</font><br />و طپانچه ای بر گردن من زدند. (انیس الطالبین نسخه ٔ خطی کتابخانه ٔ مؤلف ص <span class=\"hlight\" dir=\"rtl\">٢٢١</span>، <span class=\"hlight\" dir=\"rtl\">٢٢٤</span>).<br />که نه وقت آن سماع است که دف خلاص یابد<br />بطپانچه ای و بربط برهد بگوشمالی .<br /> <font color=\"Red\">سعدی .</font><br />گه عارض سیمین یکی را طپانچه زدی . (گلستان ).<br />ولی دو مهره چو هم پشت یکدگر گردند<br />دگر طپانچه ٔ خصمان بهیچ رو نخرند.<br /> <font color=\"Red\">ابن یمین .</font><br />خواجه مرا نزدیک خود کشیدند، و طپانچه بر گردن من زدند. (انیس الطالبین بخاری ).<br /></font></div>'),
(178443, 'طپانچه زنان', '<span class=\"hlight\">طپانچه زنان .</span> <font color=\"DarkGreen\"><b>[ طَ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ زَ ]</font></b> (نف مرکب، ق مرکب ) در حال طپانچه زدن . طپانچه زننده <span class=\"hlight\">:</span> <br />بفریاد از ایشان برآمد خروش <br />طپانچه زنان بر سر و روی و دوش .<br /><font color=\"Red\">سعدی (بوستان ).</font><br /></font></div>'),
(178444, 'طپانچه کردن', '<span class=\"hlight\">طپانچه کردن .</span> <font color=\"DarkGreen\"><b>[ طَ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ک َ دَ ]</font></b> (مص مرکب ) سیلی زدن . <BR><font color=\"Blue\">◄</font> مجازاً پیکار و زد و خورد کردن <span class=\"hlight\">:</span> <br />روبه که کند طپانچه با شیر<br />دانی که به دست کیست شمشیر.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(178445, 'طپش', '<span class=\"hlight\">طپش .</span> <font color=\"DarkGreen\"><b>[طَ پ ِ ]</font></b> (اِمص ) تپش . عمل طپیدن ؛ خفقان طپش دل . (منتهی الارب ). اضطراب . ضربان قلب . طپش قلب . <BR><font color=\"Blue\">◄</font> نشستن و برخاستن آتش . <BR><font color=\"Blue\">◄</font> حرارت . گرمی . سوزش و التهاب <span class=\"hlight\">:</span> <br />سیاوش بدو گفت انده مدار<br />کزینسان بود گردش روزگار<br />بنیروی یزدان نیکی دهش <br />ازین کوه آتش نیابم طپش .<br /> <font color=\"Red\">فردوسی .</font><br />کجا تره کان کاسنی خواندش <br />طپش خواست کز مغز بنشاندش .<br /><font color=\"Red\">فردوسی .</font><br />دل کز طپش هیبت او تافته گردد<br />گر ز آهن و روی است، چه آن دل چه زگالی .<br /> <font color=\"Red\">فرخی .</font><br />آتشی از آسمان فرودآمد، و رعدو برق غریدن گرفت، چنانکه طپش بدیشان رسید. (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">١٩١</span>).<br />دریا کشم زچاه غمت گر برآرم آه <br />سوزد نهنگ را طپش آه زیر آب .<br /> <font color=\"Red\">خاقانی .</font><br />احمد مرسل که کرد از طپش و زخم تیغ<br />تخت سلاطین ز گال گرده ٔ شیران کباب .<br /> <font color=\"Red\">خاقانی .</font><br />از طپش عشق تو در روش مدح شاه <br />خاطر خاقانی است سحر حلال آفرین .<br /> <font color=\"Red\">خاقانی .</font><br />بگیرد از طپش تیغ و ز امتلای خلاف <br />دل زمین خفقان ودم زمانه فواق .<br /> <font color=\"Red\">خاقانی .</font><br />و رجوع به تبش شود.<br /></font></div>'),
(178446, 'طپطاب', '<span class=\"hlight\">طپطاب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) رجوع به طبطاب و شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦١</span> شود.<br /></font></div>'),
(178447, 'طپق زدن', '<span class=\"hlight\">طپق زدن .</span> <font color=\"DarkGreen\"><b>[ طُ پ ُ زَ دَ ]</font></b> (مص مرکب ) طپق زدن اسب . از مچ پای لغزیدن . به هم سائیدن دو مچ پای از داخل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طپق زدن زبان </span> ؛ حرفی را بجای حرفی دیگر ادا کردن، چنانکه «لام » را بجای «را».<br /></font></div>'),
(178448, 'طپنده', '<span class=\"hlight\">طپنده .</span> <font color=\"DarkGreen\"><b>[ طَ پ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) که بطپد. مضطرب . خافق . طپان . تپنده .<br /></font></div>'),
(178449, 'طپندگی', '<span class=\"hlight\">طپندگی .</span> <font color=\"DarkGreen\"><b>[ طَ پ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) حالت طپنده .<br /></font></div>'),
(178450, 'طپنچه', '<span class=\"hlight\">طپنچه .</span> <font color=\"DarkGreen\"><b>[ طَ پ َ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ) طپانچه . تپانچه . سیلی . لطمه : الملاطمة واللطام ؛ با کسی طپنچه زدن . (مصادر زوزنی ): اکنون او را طپنچه بر روی زد. (تفسیر ابوالفتوح چ <span class=\"hlight\" dir=\"rtl\">١</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٦٠</span>). عمر طپنچه بر روی او زد. (تفسیر ابوالفتوح ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٥</span>).<br /></font></div>'),
(178451, 'طپولی', '<span class=\"hlight\">طپولی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ده کوچکی است از دهستان هندیجان بخش ایذه ٔ شهرستان اهواز، واقع در <span class=\"hlight\" dir=\"rtl\">١٩</span>هزارگزی باختر ایذه . دارای <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178452, 'طپید', '<span class=\"hlight\">طپید.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) چیزی باشد که از جایی جهد. طبید. رجوع به طبید شود.<br /></font></div>'),
(178453, 'طپیدن', '<span class=\"hlight\">طپیدن .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b> (مص ) اصلش تپیدن است، و یک مصدر بیش ندارد در اصل بمعنی گرم شدن است، چون کمال گرمی رابیقراری لازم است، لهذا مجازاً بمعنی غلطیدن می آید. (آنندراج ). <BR><font color=\"Blue\">◄</font> تلواسه کردن . اضطراب . اضطراب داشتن . مضطرب گشتن . بی آرامی کردن . تبعرض . لعلعة. هیع. ترجرج . رجراج . لیعان . (منتهی الارب ) <span class=\"hlight\">:</span> <br />کنون که نام گنه میبری دلم بطپد<br />چنان کجا دل بد دل طپد بروز جدال .<br /> <font color=\"Red\">آغاجی (از لغت فرس چ اقبال ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>).</font><br />تا سحر هر شب چنان چون میطپم <br />جوزه ٔ زنده طپد بر بابزن .<br /> <font color=\"Red\">آغاجی .</font><br />یکایک به برف اندرون ماندند<br />ندانم بدانجای چون ماندند<br />زمانی طپیدند در زیر برف ...<br />بر آن کوه خارا زمانی طپید<br />پس از کین و آوردگه آرمید.<br /> <font color=\"Red\">فردوسی .</font><br />به مجلس اندر تا ایستاده ای، دل من <br />همی طپد که مگر مانده گردی ای دلخواه .<br /> <font color=\"Red\">فرخی .</font><br />من شعر بیش گویم، تا شاه را خوش آید<br />الفاظهای نیکو ابیاتهای جاری <br />گر تو بهر مدیحی چندین طپید خواهی <br />نهمار ناصبوری نهمار بیقراری .<br /> <font color=\"Red\">منوچهری .</font><br />شیر از درد و خشم یک جست کرد، چنانکه بقفای پیل آمد و می طپید. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٢١</span>). اسبان از آن خمر خوردند، همه بیفتادند، سمردون از آنجا رفت و همه را در هم بست، چون با خود آمدند، یکزمان بطپیدند. (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span>).<br />مر مرا گویی توآنچت خوش نیاید همچنان <br />ور بگویم از جواب من چرا باید طپید.<br /> <font color=\"Red\">ناصرخسرو.</font><br />حایض او، من شده به گرمابه <br />ماهی او، من طپیده در تابه .<br /> <font color=\"Red\">سنائی .</font><br />کرده ست مرا زمانه در تاب امشب <br />حیران شده می طپم چو سیماب امشب .<br /> <font color=\"Red\">سیدحسن غزنوی .</font><br />مردی پیر و مقبول القول را پیش بهرام و فرامرز فرستاد و گفت : بسیار مطپید، و دست از بوالعجبی بدارید و همینجا بخانه بنشینید... تا من بشوم و چنانکه بباید کار بسازم، و بجهت شما نان پدید کنم . (تاریخ طبرستان ).<br />نوبت به اولیا چو رسید آسمان طپید<br />زآن ضربتی که بر سر شیر خدا زدند.<br /> <font color=\"Red\">محتشم .</font><br /> <BR><font color=\"Blue\">◄</font> از جای جهیدن . (صحاح الفرس ). <BR><font color=\"Blue\">◄</font> دست و پا زدن . پر و بال زدن <span class=\"hlight\">:</span> و هرچ فرشته بر کافری زدی همه اندامش شکسته شدی، کافر بیفتادی و همی طپیدی، و هیچ جای جراحت پیدا نبودی . (ترجمه ٔ طبری بلعمی ).<br />تن کشته با مرده یکسان شود<br />طپد یک زمان پس تن آسان شود.<br /> <font color=\"Red\">فردوسی .</font><br />بچنگ و بمنقار چندی طپید<br />چو نیرو بشد زآن سپس آرمید.<br /> <font color=\"Red\">فردوسی .</font><br />رزبان آمد و حلقوم همه بازبرید...<br />نه بنالید از ایشان کس و نه کس بطپید.<br /> <font color=\"Red\">منوچهری .</font><br />چو ماهی بسینه درون جان تو<br />چنان می ز بهر رهایش طپد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />ماهی از دریا چو در صحرا فتد<br />میطپد تا باز در دریا فتد.<br /> <font color=\"Red\">(از اختیارات شیخعلی همدانی از کتب عطار).</font><br />در راه اشتیاقت جانها ز انتظارت <br />چون مرغ نیم بسمل در خاک و خون طپیده .<br /> <font color=\"Red\">عطار.</font><br />ز غمت چو مرغ بسمل شب و روز میطپیدم <br />چو بلب رسید جانم پس از این دگر تو دانی .<br /> <font color=\"Red\">عطار.</font><br />تشنگان لبت ای چشمه ٔ حیوان مردند<br />چند چون ماهی بر خشک توانند طپید.<br /> <font color=\"Red\">سعدی .</font><br />مؤمن بدر مرگ چو آن عالم آنرا ببیند بطپد، و بر خود زند، چنانکه مرغ از قفس درخت سبز را ببیند و در آزادی آن پر و بال زند. (کتاب المعارف ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">برطپیدن، و دل برطپیدن </span> ؛ اضطراب . لرزیدن . هراسیدن . پریشانی <span class=\"hlight\">:</span> <br />چو آگاهی کشتن او رسید<br />به بر در دلش درزمان برطپید.<br /> <font color=\"Red\">فردوسی .</font><br />چو اغریرث پرهنر آن بدید<br />دل اندر بر او همی برطپید.<br /> <font color=\"Red\">فردوسی .</font><br />سخن چون به گوش سپهبد رسید<br />ز شادی دل اندر برش برطپید.<br /> <font color=\"Red\">فردوسی .</font><br />چو ارجاسب پیکار از آن گونه دید<br />ز غم سُست گشت و دلش برطپید.<br /> <font color=\"Red\">فردوسی .</font><br />نرنجم ز خصمان اگر برطپند<br />کزین آتش پارسی در تبند.<br /> <font color=\"Red\">(بوستان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">درطپیدن </span> ؛ در خود طپیدن . جنبیدن و اضطراب شدید دل در حال تأثری نیک یابد <span class=\"hlight\">:</span> <br />حسودی که یک جو خیانت ندید<br />ز کارش چو گندم به خود درطپید.<br /> <font color=\"Red\">سعدی (بوستان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طپیدن دل یا دل طپیدن </span> ؛ ضربان قلب خفق و خفقان . (منتهی الارب ) (ذخیره ٔ خوارزمشاهی ). وجیف . (ترجمان القرآن ) (منتهی الارب ) (تاج المصادر بیهقی ) (دهار) <span class=\"hlight\">:</span> <br />کنون که نام کنیسه برد دلم بطپد<br />چنان کجا دل بددل طپد به روز جدال .<br /> <font color=\"Red\">آغاجی .</font><br />همی دلت بطپد زو بسان ماهی از آنک <br />ز منزل دل تو قصد زی سفر دارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />شبی پای عمرش فروشد بگل <br />طپیدن گرفت از ضعیفیش دل .<br /> <font color=\"Red\">سعدی .</font><br />چنانم ز افعال و اعمال بد<br />که از هول دل دربرم می طپد.<br /> <font color=\"Red\">نزاری قهستانی (دیوان چ روسیه ص <span class=\"hlight\" dir=\"rtl\">٤٧</span>).</font><br />رواست در بر اگر می طپد کبوتر دل <br />که دید در ره خود تاب و پیچ دام و نشد.<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طپیدن کشته </span>؛ سهف . طپیدن کشته در خون . شحط. شحوط. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طپیدن مرغ </span> ؛ پر و بال زدن چنانکه در قفس، یا پس از بسمل شدن در خون .<br /></font></div>'),
(178454, 'طپیدنی', '<span class=\"hlight\">طپیدنی .</span> <font color=\"DarkGreen\"><b>[ طَ دَ ]</font></b> (ص لیاقت ) قابل طپیدن .<br /></font></div>'),
(178455, 'طپیده', '<span class=\"hlight\">طپیده .</span> <font color=\"DarkGreen\"><b>[ طَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) به همه ٔ معانی رجوع به طپیدن شود.<br /></font></div>'),
(178456, 'طپیدگی', '<span class=\"hlight\">طپیدگی .</span> <font color=\"DarkGreen\"><b>[ طَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) حالت طپیده . تپش . طپش . اضطراب . لرزه . لجاجة: طپیدگی از گرسنگی . (منتهی الارب ).<br /></font></div>'),
(178457, 'طژن', '<span class=\"hlight\">طژن .</span> <font color=\"DarkGreen\"><b>[ طَ ژَ ]</font></b> (اِخ ) تحریف یا تقریبی از تجن است . رجوع به تجن و حبیب السیر چ تهران ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>، <span class=\"hlight\" dir=\"rtl\">٢٤٩</span> و چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٤١</span> و ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١١٨</span> شود.<br /></font></div>'),
(178458, 'طی', '<span class=\"hlight\">طی .</span> <font color=\"DarkGreen\"><b>[ طَی ی ]</font></b> (ع مص ) درنوردیدن . درنوشتن نامه را. یقال : طوی الصحیفة طیاً. (منتهی الارب ). پیچیدن . (آنندراج ). درپیچیدن . لوله کردن . نوردیدن . نوشتن . طومار کردن : طی کتاب ؛ طومار کردن آن، یعنی درنوردیدن آن . خلاف نشر که بمعنی گستردن است . طی ّ لسان ؛ بمعنی نوردیدن زبان . مراد از آن خاموشی است و گاهی کنایه از استعداد گفتن باشد. (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br />اگرچه اندر وقتی زمانه را دیدم <br />که باز کرد نیارم ز بیم طی طومار.<br />ابوحنیفه ٔ اسکافی (از تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٨١</span>).<br />درده بیاد حاتم طی جام یکمنی <br />تا نامه ٔ سیاه بخیلان کنیم طی .<br /> <font color=\"Red\">حافظ.</font><br />حافظ ورق شکوه گذاری طی کن <br />وین خامه ٔ تزویر و ریائی پی کن .<br /> <font color=\"Red\">حافظ.</font><br />افسوس که نامه ٔ جوانی طی شد<br />وین باغ و نشاط کامرانی طی شد.<br /> <font color=\"Red\">حافظ.</font><br />سخا نماند سخن طی کنم بیا ساقی <br />بیار باده بشادی بیاد حاتم طی .<br /> <font color=\"Red\">حافظ.</font><br />خسرو آفاق بخشی کز صفا<br />نام حاتم در زمانش گشت طی .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> پنهان کردن کار را. یقال : طوی کشحه علی امر. (منتهی الارب ). قال اﷲ تبارک و تعالی <span class=\"hlight\">:</span> یوم نطوی السماء کطی السجل ؛ ابوالفتوح رازی در تفسیر خویش هر دو معنی مذکور را در تفسیر این آیت ایراد کرده و گوید: این طی را بر دو وجه تفسیر کردند: یکی طی که خلاف نشر باشد، یعنی ما آسمان را درنوردیدیم پس از آنکه افراخته باشیم . و وجه دیگر آنکه : طی عبارت باشد از کتم و اخفاء و مراد اعدام، یقال : طویت هذا الامر عن فلان ؛ ای کتمته عنه، یعنی ما آسمان را بعدم بریم از وجود، کما بدأنا اول خلق نعیده .(قرآن <span class=\"hlight\" dir=\"rtl\">١٠٤/٢١</span>، از تفسیر ابوالفتوح ). <BR><font color=\"Blue\">◄</font> (اِ) لا. نورد. شکن چین . غرّ. لف . مطوی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">در طی ِ</span> ؛ در لای ِ. در نوردِ. در شکن ِ. در چین ِ. در لف ِ. کلمه ٔ «در طی ِ» با تمام کلمات مذکوره مترادف و مستعمل است و گاه معنی در ضمن و در اثناء از آن منظورباشد که این دو لفظ نیز با الفاظ مسطوره متقارب المعنی میباشند، چنانچه در طی ّ صحبت، معنی در ضمن صحبت دهد، و در طی ّ راه، معنی در اثناء راه از آن مفهوم است <span class=\"hlight\">:</span> در طی ِّ آن مرثیه نامه تقریر جمله ٔ خصال آن زبده ٔ رجال مندرج و مندمج است . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٤٢</span>).<br /> <BR><font color=\"Blue\">◄</font> (مص ) روی گردانیدن و مفارقت گزیدن از کسی . یقال : طوی کشحه عنی . (منتهی الارب ). اعراض کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طی کشح </span> ؛ کنایه است از اعراض .<br /> <BR><font color=\"Blue\">◄</font> پوشیدن سخن را. یقال : طوی الحدیث . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طی حدیث </span> ؛ پوشانیدن خبر و کلام <span class=\"hlight\">:</span> این حدیث طی باید کرد که بی حشمت وی علی تکین را بر نتوان انداخت . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٤٢</span>).<br /> <BR><font color=\"Blue\">◄</font> نشستن با کسی . یقال : طوی القوم ؛ یعنی نشست با آنها و یا آمد نزد ایشان و یا تجاوز کرد از ایشان . <BR><font color=\"Blue\">◄</font> طی کردن زمین را. یقال : طوی البلاد. (منتهی الارب ). راه پیمودن <span class=\"hlight\">:</span> در طی آن منازل و مراحل بمضیقی رسیدند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٩٤</span>). بیابانی هائل در طی ّ آن منازل بازپس گذاشت که مرغ در هوای آن پر بریزد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٥٤</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوی اﷲ البعد لنا</span> ؛ نزدیک کرد. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طوی اﷲ عمره </span> ؛ تمام و فنا کرد عمر او را. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طی طریق </span> ؛ راهنوردی . راه سپاری . رهنوردی . رهسپری .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طی مسافت </span> ؛بریدن آن .<br /><BR><font color=\"Blue\">◄</font> گرسنه داشتن خود را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اصطلاح عروض ) افکندن ساکن چهارم از مستفعلن و مفعولات ُ. (منتهی الارب ).در المعجم آورده که : طی، اسقاط حرف چهارم جزء است چون ساکن باشد و چون از مستفعلن فا بیندازی مستعلن بماند مفتعلن بجای آن بنهند. و مفتعلن چون از مستفعلن خیزد آن را مطوی ّ خوانند، یعنی درنوردیده برای آنکه حرفی از میان آن کم کرده اند چنانکه از میان جامه، پاره ای درنوردند. (المعجم چ تهران ص <span class=\"hlight\" dir=\"rtl\">٤٠</span>). و صاحب کشاف آرد: طی، نزد عروضیان حذف حرف چهارم از جزء است . کذا فی عنوان الشرف . و در رساله ٔ قطب الدین سرخسی آمده که : هو اسقاط الرابع الساکن . و هکذا فی عروض سیفی . و جزئی را که عمل طی ّ در آن بکار برده شده مطوی ّ نامند.و در پاره ای از رسائل عروض عربی آورده که : الطی اسقاط الرابع الساکن اذا کان ثانی سببه . و قید آخر برای احتراز از چارمین ساکن در مُس تف عِلن در بحر خفیف و مجتث ّ باشد چه درین دو بحر عمل طی ّ غیرجائز است و ازینرو در دو بحر مذکور تَفْعِ را وتد مفروق معتبر دانسته و آن را جدا نوشته اند. (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> صاحب غیاث اللغات و آنندراج یکی از معانی طی را گرسنگی نوشته اند در صورتی که صاحب منتهی الارب این معنی را برای «طوی » آورده است، چنانکه در محل خود ثبت گردید. <BR><font color=\"Blue\">◄</font> نام علتی است که از آن موی حلقه دار میشود. (غیاث اللغات ) (آنندراج ) (از منتخب اللغات و مؤید الفضلاء و لطائف اللغات و شمس اللغات ). <BR><font color=\"Blue\">◄</font> ببریدن چاه . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> خواندن . (مصادر زوزنی ). <BR><font color=\"Blue\">◄</font> طی بساط؛ کنایه است از خروج .<br /></font></div>'),
(178459, 'طی', '<span class=\"hlight\">طی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ )نامش جلهم بن اددبن زیدبن یشحب صالح بن افحشدبن سام بن نوح . نیای قبیله ٔ طی و نسبت بدان طائی است و گویند ازین قبیله سه تن پدید آمده اند که هر یک در شیوه ٔ خود بی نظیر بوده اند، حاتم در جود و داود در فقه و زهد و ابوتمام در شعر. (از انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> «ب »).<br /></font></div>'),
(178460, 'طی', '<span class=\"hlight\">طی .</span> <font color=\"DarkGreen\"><b>[ طَی ی ]</font></b> (اِخ ) ابن حسن بن اتش صنعانی انباری . محدث است .<br /></font></div>'),
(178461, 'طی الارض', '<span class=\"hlight\">طی الارض .</span> <font color=\"DarkGreen\"><b>[ طَی ْ یُل ْ اَ ]</font></b> (ع اِ مرکب ) نوردیدن زمین . نوعی کرامت که بجای گام برداشتن و رفتن زمین در زیر پای آدمی بتندی پیچیده شود و او بمقصد خویش هرچند دور باشد در مدتی بسیار کم رسد: و یذکر ان الارض تطوی له <font color=\"DarkGreen\"><b>[ میمون القداح ]</font></b> فیمضی الی این احب فی اقرب مدة. (ابن الندیم ).<br /></font></div>'),
(178462, 'طی کردن', '<span class=\"hlight\">طی کردن .</span> <font color=\"DarkGreen\"><b>[ طَی ی <span class=\"hlight\" dir=\"rtl\">/</span> طِی ی <span class=\"hlight\" dir=\"rtl\">/</span> طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِک َ دَ ]</font></b> (مص مرکب ) سپردن . بسپردن . بگذاشتن . پیمودن .قطع کردن . بریدن راهی را: شبح المفازة؛ طی کرد بیابان را. (منتهی الارب ). طوی البلاد طیاً؛ طی کرد زمین را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نوردیدن . درنوردیدن . نَوشتن . درنَوشتن . درپیچیدن . لوله کردن <span class=\"hlight\">:</span> <br />سزد که چون کف او نشر کرده نشره ٔ جود<br />روان «حاتم طی » طی کند بساط سخا.<br /> <font color=\"Red\">خاقانی .</font><br />مصادر فوق مجازاً در موردراه نیز مستعمل است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طی کردن قیمت چیزی </span> ؛ بریدن بها.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طی کردن نامه </span> ؛ درپیچیدن آن .<br /><BR><font color=\"Blue\">◄</font> در تداول فارسی، مردن . نفس آخر درکشیدن .<br /></font></div>'),
(178463, 'طی کش', '<span class=\"hlight\">طی کش .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) روزه دارنده ٔ طی، و روزه ٔ طی چنان باشد که بعد سه روز طعام خورند اگرچه به وقت شام به سه چهار قطره آب افطار میکنند. (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(178464, 'طیا', '<span class=\"hlight\">طیا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) بلغت یونانی نشادر پیکانی را گویند و آن چیزی است شبیه به نمک . (برهان ) (اختیارات ) (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویه ) (آنندراج ).<br /></font></div>'),
(178465, 'طیاب', '<span class=\"hlight\">طیاب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b>(ع اِ) صافی . صفا. صفوت . رجوع به دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨</span> شود.<br /></font></div>'),
(178466, 'طیاب', '<span class=\"hlight\">طیاب .</span> <font color=\"DarkGreen\"><b>[ طُی ْ یا]</font></b> (ع ص، اِ) بوی خوش . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> شی ٌٔ طُیاب ؛ نیک خوش . نیک پاک . نیک پاکیزه .(منتهی الارب ) (آنندراج ). و شاید مأخوذ از طیبت که فارسیان آن را در مورد خوشگوئی و خوش سخنی استعمال میکنند باشد، چه یاقوت در ج <span class=\"hlight\" dir=\"rtl\">٢</span> از معجم الادباء در ترجمه ٔاحمدبن محمد ملقب به جراب الدوله که از بذله گویان معروف عصر المقتدر باﷲ عباسی بوده گوید: «و کان طنبوریاً احد الظرفاء الطیاب ... و له کتاب ترویح الارواح و مفتاح السرور و الافراح، لم یصنف فی فنه مثله اشتمالاً علی فنون الهزل و المضاحک ». (معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٣</span>).<br /></font></div>'),
(178467, 'طیاب', '<span class=\"hlight\">طیاب .</span> (اِخ ) خرمابنی است در بصره . (منتهی الارب ).<br /></font></div>'),
(178468, 'طیاب', '<span class=\"hlight\">طیاب .</span> <font color=\"DarkGreen\"><b>[ طَی ْ یا ]</font></b> (ع اِ) پیشخدمت حمام . دلاک . رجوع به دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨</span> شود.<br /></font></div>'),
(178469, 'طیاب', '<span class=\"hlight\">طیاب .</span> <font color=\"DarkGreen\"><b>[ طَی ْ یا ]</font></b> (اِخ ) ابن ابراهیم بن ماهان بن بهمن بن نسک المعروف بالموصلی . اصل این خانواده از ارجان فارس بوده اند و بعداً معروف بموصلی شدند. ابن الندیم گوید: از فرزندان ابراهیم جز اسحاق و طیاب دیگران پیرامون فن غناء نگشتند. (الفهرست چ مصر ص <span class=\"hlight\" dir=\"rtl\">٢٠١</span>).<br /></font></div>'),
(178470, 'طیات', '<span class=\"hlight\">طیات .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) جنسی از نخل که در مصر میشود. (فهرست مخزن الادویه ). در فرهنگ نفیسی آمده : قسمی از خرمابن در بصره .<br /></font></div>'),
(178471, 'طیاتیرا', '<span class=\"hlight\">طیاتیرا.</span> (اِخ ) شهری از مقاطعات لیدیا در آسیای صغیر میباشد که فعلاً آن را آق حصار گویند و بر دشت وسیعی که بر یکی از فروع رود لیکوس است بطرف جنوب شرقی ازمیر در میانه ٔ ساردس و پرغاموس واقع میباشد و یکی از هفت کلیسا که در مکا <span class=\"hlight\" dir=\"rtl\">١</span>:<span class=\"hlight\" dir=\"rtl\">١١</span> مذکور میباشد در آنجا بود. و لیدیه ٔ جدیدالایمان که پولس رسول او را تعمید داد از اهل همین شهر بود و فعلاً دارای هزار خانوار است لکن بجز قلعه ٔ حاکم نشین، خانه ای که لایق ذکر باشد ندارد و معبد سمیث نیز از قدیم الایام در اینجا بوده و در بیرون شهر واقع است و دور نیست که سمیث همان نبلیه باشد که در مکا<span class=\"hlight\" dir=\"rtl\">٢</span>:<span class=\"hlight\" dir=\"rtl\">٢٠</span> - <span class=\"hlight\" dir=\"rtl\">٢٢</span> مسطور است . (از قاموس کتاب مقدس ص <span class=\"hlight\" dir=\"rtl\">٥٨٤</span>).<br /></font></div>'),
(178472, 'طیاجن', '<span class=\"hlight\">طیاجن .</span> <font color=\"DarkGreen\"><b>[ طَ ج ِ]</font></b> (معرب، اِ) ج ِ طیجن . (دهار). رجوع به طیجن شود.<br /></font></div>'),
(178473, 'طیاح', '<span class=\"hlight\">طیاح .</span><font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) آثار. خرابه ها. بقایا. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨</span>).<br /></font></div>'),
(178474, 'طیادی', '<span class=\"hlight\">طیادی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b>(ع ص، اِ) ج ِ طادیة، بمعنی دیرینه . (منتهی الارب ).<br /></font></div>'),
(178475, 'طیار', '<span class=\"hlight\">طیار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) نظم و ترتیب . <BR><font color=\"Blue\">◄</font> زینت . <BR><font color=\"Blue\">◄</font> زیور (به جواهر آراسته ). (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>).<br /></font></div>'),
(178476, 'طیار', '<span class=\"hlight\">طیار.</span> <font color=\"DarkGreen\"><b>[ طَی ْ یا ]</font></b> (اِخ ) لقب جعفربن ابیطالب بن عبدالمطلب عم ّ حضرت پیغمبر صلواة اﷲ و سلامه علیه، و علت این لقب آن است که چون در غزوه ٔ موته هر دو دست مبارک وی را کُفار قطع کردند و وی درفش لشکر اسلام را همچنان با دو بازوی خویش برافراشته داشت پیغمبر اکرم فرمود: لقد ابدله اﷲ بیدیه جناحان یطیر بهما فی الجنة فسمی الطیار. (سمعانی ). وی را ذوالجناحین نیز خوانده اند. رجوع به جعفربن ابیطالب شود.<br /></font></div>'),
(178477, 'طیار', '<span class=\"hlight\">طیار.</span><font color=\"DarkGreen\"><b>[ طَی ْ یا ]</font></b> (ع ص ) فرس ٌ طیارٌ؛ اسب تیزخاطر. اسب چست و چالاک . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) پرنده . (مهذب الاسماء). و النوع الطیارات منها <font color=\"DarkGreen\"><b>[ من الذریح ]</font></b> یسمی «ازغلال ». (ابن البیطار) <span class=\"hlight\">:</span> <br />چو مرکبیست بزیر تو آن مبارک خنگ <br />که نگذرد به گه تاختن از او طیار.<br /> <font color=\"Red\">فرخی .</font><br />آراسته ای از شرف و جود همیشه <br />چون شاخ زطیار و چو افلاک ز سیار.<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> زبانه ٔ ترازو. ترازوی راست (در نسخه ای از مهذب الاسماء خطی ). ترازوئی است (در دو نسخه ٔ خطی دیگر از همان کتاب ). قپان و به این معنی فارسی است . (منتخب اللغات ) <span class=\"hlight\">:</span> اگر اساس جهانداری بر قاعده ٔ انصاف نهید و به طیار راستی ستانید و دهید کار شما هر روز طراوت تزاید پذیرد. (بدایع الازمان تاریخ سلاجقه ٔ کرمان ).<br />عطای او از آن بگذشت کآن را<br />توان سختن بشاهین و به طیار.<br /> <font color=\"Red\">فرخی .</font><br />طرار بریده سر چو طیار<br />آویخته بیزبان ببینم .<br /> <font color=\"Red\">خاقانی .</font><br />دین و دولت هر دوچون در کفه ٔ عدلش نشست <br />کار عالم راست از عدلش چو طیار ایستد.<br /> <font color=\"Red\">سیدحسن غزنوی .</font><br /> <BR><font color=\"Blue\">◄</font> نوعیست از کشتی . (مهذب الاسماء) <span class=\"hlight\">:</span> <br />چو رودهائی هر یک چنان کجا افتد<br />که گذشتن از او هر دو بازوی طیار.<br /> <font color=\"Red\">فرخی .</font><br />اذ لیس فی الباب بواب لدولتکم <br />و لا حمار و لا فی الشط طیار.<br /> <font color=\"Red\">؟ (از یتیمة الدهر ثعالبی ).</font><br />غوغا بدیوان رفتند ودوات از پیش وزیر برگرفتند و سر و پای برهنه وزیر بجست و خود را در طیار افکند. (مجمل التواریخ و القصص ). <BR><font color=\"Blue\">◄</font> (ص ) فراهم آورده . آماده . مهیا: تعابی ؛ میل کردن یکی بجانب قومی و دیگری بجانب قومی دیگر، و این وقتی باشد که هر دو قوم برای هر یکی از آن دوطعامی طیار کرده باشند. (منتهی الارب ). در غیاث اللغات و آنندراج آمده که : فارسیان لفظ طیار را مجازاً بمعنی مهیا و آماده و مستعد استعمال کنند و تحقیق آنست که این لفظ در اصل اصطلاح قوشچیان یعنی میرشکاران است که چون جانوران شکاری از گریز برآمده مستعد و آماده ٔ پرواز و شکاراندازی میشوند گویند این جانور طیارشد، چون به این معنی شهرت گرفته مجازاً هر شی ٔ مهیارا طیار گویند و به تاء فوقانی نوشتن فارسی بودن این لفظ محل تأمل است . از بهار عجم و چراغ هدایت و سراج . (غیاث اللغات ) (آنندراج ). مؤلف غیاث اللغات گوید: به معنی جلدرفتار و جهنده و مواج است، چنانکه در منتخب و صراح . پس بمعنی درست و مهیا مجاز باشد از معنی لغوی و تفصیلش در باب تای فوقانی نوشته ام . (غیاث اللغات ). ملاطغرا خطاب بمحبوب <span class=\"hlight\">:</span> <br />چو طیار کردی خدنگ نگاه <br />به استادیت تیرگر شد گواه .<br />محمدسعید اشرف <span class=\"hlight\">:</span> <br />میپزد باز از هوای عشق او رنگ رخم <br />گرچه با زنجیرموج باده طیارش کنم .<br /> <font color=\"Red\">(از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> (اِ) تیار. بزرگترین نوعی از انجیر. <BR><font color=\"Blue\">◄</font> (ص )مشهور و معروف در همه جا. و این اصطلاحی است مترادف سیار ولی در معنی اشد از سیر. عبدالواحد مراکشی در تاریخ خود که بهمت دزی در لیدن طبع و نشر گردیده گوید: و من شعره السیار بل الطیار قوله الخ . <BR><font color=\"Blue\">◄</font> (اِمص ) سیر در نهر یا در دریا بر ضد جریان آب . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>).<br /></font></div>'),
(178478, 'طیارات', '<span class=\"hlight\">طیارات .</span> <font color=\"DarkGreen\"><b>[ طَی ْ یا ]</font></b> (ع اِ) ج ِ طَیّاره . رجوع به طَیّارة شود. درآمد دیوانی حاصل از جریمه ٔ مختلس یا مال بلا و ارث یا مال گمشده و یا مال غائب مفقودالاثر بلاوارث <span class=\"hlight\">:</span> و طیارات دیوان و توفیرات خزانه الا برخصتی شرعی از وجهی مرضی بخودراه نمیدهد. (المعجم چ طهران ص <span class=\"hlight\" dir=\"rtl\">١١</span>). و آنچه از مملکت پادشاهان قدیم یابد، مال پادشاهی بود. و اما آنچه از رعیت ستاند از چهار قوم باشد: از اهل زراعت و از اهل تجارت و از چهارپای داران و از طیارات . و اما طیارات از چهار گونه بود: اول مالی که او را هیچ میراث خوار نبود. دوم کسی که مال پادشاه خورده باشد با رشوت ستده و از او بسبب آن چیزی بستانند. سوم بلارغو و چیزهای گم شده و تلف . چهارم غائبانه کسی که مرگ و زندگانی ایشان معلوم نباشد و ایشان را وارث نبود. و این هردو چون خداوند مال بازآید عوض مال او با او دهند و این مال مصالح پادشاهی باشد. (نقل از رساله ٔ خواجه نصیر، رساله ٔ مالیات و خراج ). <BR><font color=\"Blue\">◄</font> ج ِ طیاره در تداول امروز بمعنی هواپیما. رجوع به طیاره شود.<br /></font></div>'),
(178479, 'طیارنوش', '<span class=\"hlight\">طیارنوش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) صاحب حبیب السیر آرد: در سال چهارم از سلطنت وسطانس ملوک فرس انطاکیه را فتح کردند. و او عزم رزم فارسیان نمود. و در آن ایام بیمار شده بعد از وجدان صحت یکی از یونانیان راکه طیارنوش نام داشت ولیعهد گردانیده بار دیگر ملک روم از فرنگیان به اهالی یونان انتقال یافت . حمزه ٔ اصفهانی گوید که : قیاصره ٔ فرنگ سیزده نفر بودند و دویست وچهل ودو سال و شش ماه پادشاهی نمودند و بقول خواجه رشید طبیب عدد آن جماعت بهفده رسید و اوقات سلطنت ایشان دویست وچهل سال و شش ماه و نه روز ممتد گردید. بعد از آن طبانوس بقولی هفت سال و بروایتی چهار سال پادشاهی نمود، چون رایت دولت تاج فلک رفعت بر سر اونهاد میان او و سلاطین عجم محاربات به وقوع انجامید و در بعض اوقات صورت فتح و ظفر در نظرش جلوه گر گشت (و در تحفة الملکیه مسطور است که طبانوس در وقت جهانبانی در قصر خود گنجی یافت و تمامی آن نقود و اجناس را بر فرقه ٔ انام تقسیم نمود). و در سال چهارم از فرمانفرمائی دختر خود را به بطریقی موربقی عقد بست و داماد را ولیعهد ساخت . موربقی به سیرت حمیده و پسندیده اتصاف داشت و همواره ابواب تصدقات بر روی روزگار ارباب احتیاج و افتقار میگشود و در سال چهارم از سلطنت او در قسطنطنیه قریب چهارصدهزار کس بعلت طاعون گذران از جهان شدند و خسرو پرویز در وقتی که از بهرام چوبین بگریخت جهت استمداد نزد موربقی رفته و دختر او مریم را در حباله ٔ نکاح خود درآورد و چون قواعد مصالحت مؤکد شد و خسرو بر تخت سلطنت مدائن متمکن گردید موربقی علوفات متجنده راکم کرد و بطارقه خاطر بر مخالفت قرار داده در مدینه ٔ هرقلیه مجتمع شدند و موربقی خود را از مقاومت آن جماعت عاجز دیده بگریخت و بطارقه متعاقب او اسب برانگیخته جمعی بدو رسیدند و رشته ٔ حیاتش را بتیغ تیز بریدند. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>). و رجوع به طباریوس شود.<br /></font></div>'),
(178480, 'طیاره', '<span class=\"hlight\">طیاره .</span> <font color=\"DarkGreen\"><b>[ طَی ْ یا رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (از ع، اِ) کشتی سریع تیزرو. (منتهی الارب ) (دهار) (آنندراج ). نوعیست از کشتی . ج، طیارات . (مهذب الاسماء). کشتی و جهاز تیزرو را گویند. (برهان ). <BR><font color=\"Blue\">◄</font> ترازوی راست . (مهذب الاسماء). قسمی ترازو. <BR><font color=\"Blue\">◄</font> (ص ) کنایه از اسب تیزرفتار، و این مجاز است . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br />درآمد به طیاره ٔ کوهکن <br />فرس پیل بالا و شه پیلتن .<br /> <font color=\"Red\">نظامی (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) در این بیت نظامی <span class=\"hlight\">:</span> <br />نکیسا چون زد این طیاره بر چنگ <br />ستای باربد برداشت آهنگ .<br />برای طیاره برحسب ظاهر معنیی جز مضراب نمیتوان یافت در صورتی که در هیچیک از کتب لغت برای طیاره معنی مضراب نیاورده اند. ولی مرحوم وحید در شرح لغات خمسه فال نیک آورده است . <BR><font color=\"Blue\">◄</font> ودر این بیت اسدی که در گرشاسب نامه آورده <span class=\"hlight\">:</span> <br />ز شاهین وطیاره بر هر گروه <br />همی سنگ بارید چون کوه کوه .<br />اسدی (گرشاسبنامه نسخه ٔ خطی کتابخانه ٔ مؤلف ص <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>).<br />از طیاره معنی منجنیق مفهوم میشود، و این معنی نیز در کتب لغت یافت نشد. <BR><font color=\"Blue\">◄</font> هواپیما. از آلات ناقله ٔ هوائی که بر فراز هوا پرواز میکند. این آلت ناقله دارای ماشینی است که بواسطه ٔ حرکت ملخی که در قسمت قدامی آن واقع است در هوا پیش میرود و علت عدم سقوط آن فشاری است که از هوا بر بالهای آن که بطور سطح مورب است وارد می آید. دلیل صعود آن این است که درنتیجه ٔ فشاری که بر بالها وارد میشود و عمود بر سطح آن است به دو قوه تجزیه میگردد: یکی در امتداد خطقائم و یکی در خلاف جهت حرکت . آنکه در خلاف جهت حرکت است و بواسطه ٔ کشش ملخ خنثی میشود و آنکه در امتداد خط قائم ولی بطرف بالاست با قوه ٔ ثقل معارضه میکند و همین که بر آن فزونی یافت طیاره بطرف بالا صعود میکند. <BR><font color=\"Blue\">◄</font> سایبان . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>). <BR><font color=\"Blue\">◄</font> رواق . <BR><font color=\"Blue\">◄</font> بادبادک . نوعی از ادوات بازی کودکان که هنگام وزیدن باد بوسیله ٔ ریسمانی آن را بهوا برکنند. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>). <BR><font color=\"Blue\">◄</font> در اصطلاح بافندگان، چرخ دوک . <BR><font color=\"Blue\">◄</font> (ص ) قافله ٔ طیاره ؛ کاروانی که در راه پیمائی در هیچ منزلگاهی اقامت نکند و پیوسته در سیر باشد. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>). و رجوع به ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span> شعوری شود.<br /></font></div>'),
(178481, 'طیاری', '<span class=\"hlight\">طیاری .</span> <font color=\"DarkGreen\"><b>[ طَی ْ یا ]</font></b> (حامص ) طیار و آماده و مهیّا بودن . <BR><font color=\"Blue\">◄</font> اصطلاحی بوده است . تریاک مالی .<br /></font></div>'),
(178482, 'طیاریة', '<span class=\"hlight\">طیاریة.</span> <font color=\"DarkGreen\"><b>[ طَی ْ یا ری ی َ ]</font></b> (اِخ ) فرقه ای از غالیه ٔ تناسخیه که قائل بتناسخ و منسوب بجعفربن ابیطالب عم پیمبر اکرم صلواة اﷲ و سلامه علیه میباشد. (مفاتیح خوارزمی ص <span class=\"hlight\" dir=\"rtl\">١٩</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178483, 'طیاش', '<span class=\"hlight\">طیاش .</span> <font color=\"DarkGreen\"><b>[ طَی ْ یا ]</font></b> (ع ص ) مرد سبک . (منتهی الارب ) (آنندراج ). سرسبک . (زمخشری ) (مهذب الاسماء).سبک . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آنکه آهنگ مختلف دارد و بر یک اراده نرود. (منتهی الارب ) (آنندراج ). آنکه قصد یک چیز نداشته باشد و سرگردان و حیران باشد. (منتخب اللغات ). آنکه بیک سوی قصد نکند از سبکی .<br /></font></div>'),
(178484, 'طیاطر', '<span class=\"hlight\">طیاطر.</span> (معرب، اِ) طِآطْر. تآتر. نمایش . (از دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>). و رجوع به تآتر شود.<br /></font></div>'),
(178485, 'طیاف', '<span class=\"hlight\">طیاف .</span> (ع اِ) گرانی و سنگینی را گویند که در خواب بر مردم افتد و بعربی کابوس گویند. (برهان ) (آنندراج ). بختک .<br /></font></div>'),
(178486, 'طیافیر', '<span class=\"hlight\">طیافیر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طیفور <span class=\"hlight\">:</span> و بین ایدیهن طیافیر الذهب و الفضه مملوة بحب الملوک . (رحله ٔ ابن بطوطة). و رجوع به طیفور شود.<br /></font></div>'),
(178487, 'طیال', '<span class=\"hlight\">طیال .</span> (ع ص، اِ) ج ِ طویل . (منتهی الارب ).<br /></font></div>'),
(178488, 'طیالسة', '<span class=\"hlight\">طیالسة.</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ س َ ]</font></b> (ع اِ) ج ِ طیلسان . (منتهی الارب ) (آنندراج ). رجوع به طیلسان شود.<br /></font></div>'),
(178489, 'طیالسی', '<span class=\"hlight\">طیالسی .</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ سی ی ]</font></b> (اِخ ) ابوداود سلیمان بن داودبن الجارود الطیالسی . اصل وی از فارس بود ولی در بصره اقامت گزید.پدر وی از موالی قریش و مادر وی نیز بنده ای بود بنی نصربن معویه را. وی از شعبه و ثوری و هشام و ستوائی و همام بن یحیی و زیادبن یزید و ابوعوانه و غیر آنان و نیز از اهل عراق روایت کرده . او را مسندی است که از صحابه گرد آورده است . ولادتش بسال <span class=\"hlight\" dir=\"rtl\">١٣٣</span> و وفات وی بسال <span class=\"hlight\" dir=\"rtl\">٢٠٣</span> هَ . ق . در ماه ربیعالاول بوده است . (سمعانی ).<br /></font></div>'),
(178490, 'طیالسی', '<span class=\"hlight\">طیالسی .</span> <font color=\"DarkGreen\"><b>[ طَ ل ِ سی ی ]</font></b> (ص نسبی ) سمعانی در انساب آورده است : این نسبت به طیالسه است و آن جامه ای است که بالای عمامه باشد. (از انساب سمعانی ).<br /></font></div>'),
(178491, 'طیالیفون', '<span class=\"hlight\">طیالیفون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی بنطافلن است . (مخزن الادویه ).<br /></font></div>'),
(178492, 'طیان', '<span class=\"hlight\">طیان .</span> (اِ) دیگی بزرگ . تیان : سکاره ؛ طیانهای حمامها، قدور الحمامات .<br /></font></div>'),
(178493, 'طیان', '<span class=\"hlight\">طیان .</span> (اِخ ) دهی از دهستان حشمت آباد بخش دورود شهرستان بروجرد در <span class=\"hlight\" dir=\"rtl\">٤٢</span> هزارگزی جنوب خاوری دورود کنار راه مالرو کرجیان بقطعه ٔ رستم . کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">١٠٨</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و تریاک . شغل اهالی زراعت . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178494, 'طیان', '<span class=\"hlight\">طیان .</span> (اِخ ) دهی از دهستان کشور بخش پاپی شهرستان خرم آباد در <span class=\"hlight\" dir=\"rtl\">٥٣</span> هزارگزی جنوب باختری سپیددشت و <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی باختر ایستگاه کشور. جلگه و گرمسیر مالاریائی با <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه . آب آن از چشمه ها. محصول آن غلات و لبنیات . شغل اهالی زراعت و گله داری . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178495, 'طیان', '<span class=\"hlight\">طیان .</span> <font color=\"DarkGreen\"><b>[ طَی ْ یا]</font></b> (ع ص ) رجل ٌ طیان ٌ؛ مرد گرسنه . (منتهی الارب ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> گل گر. (مهذب الاسماء). بناء. گلیگر. راز. گلکار. کلال . (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(178496, 'طیان', '<span class=\"hlight\">طیان .</span> <font color=\"DarkGreen\"><b>[طَی ْ یا ]</font></b> (اِخ ) از اعلام است که جمعی از آنها چون بنا بوده اند خود را منسوب بدان ساخته اند. (سمعانی ).<br /></font></div>'),
(178497, 'طیان', '<span class=\"hlight\">طیان .</span> <font color=\"DarkGreen\"><b>[ طَی ْ یا ]</font></b> (اِخ ) ابوالعباس احمدبن محمدبن یوسف بن اسحاق السخی (ظ: الشیخی ) الطیان الشاعر بالعجمیة. وی اهل قریه ٔ شیخ بوده . بیشتر اشعار او در سحق و مطاینه (ظ : مطایبه ) میباشد. دیوان وی در مرو شهرتی دارد. در آخر توبه کرد و دیگر دهان و زبان به گفتار شعر نیالود، و چون بصنعت بنائی آشنا بود بدان پیشه اشتغال ورزید و گویند مناره ای که بر در جامع مدینه و جامع قریه ٔ شیخ برپاست از بناهای اوست . از ابورجاء محمدبن حمدویه الشیخی الهورقانی روایت دارد و ابوعلی الحسین بن علی البردعی السمرقندی نیز از وی روایت کرده است . (سمعانی ).<br />هدایت در مجمع الفصحاء آورده که : طیان حکیمی دانا و شاعری توانا و بلیغی تیززبان وفصیحی شیرین بیان بوده . از بم است که قلعه ای محکم است در حدود کرمان و ثغور سجستان . بهر صورت طیان را ژاژخا لقب کرده اند و ژاژ طیان مشهور است لکن معلوم نشدکه جهت آن چیست، همانا اعداء این لقب بر او بسته اندو خاطرش خسته . صاحب دیوان بوده اما به دست نمی آید. و از اشعارش نوشته شد:<br />چو نیست روی سعادت گمان برم که مگر<br />قضا مزاج زحل داد سعد کبری را<br />چه گویم از غم گیتی که هرچه میگویم <br />بسوزد آتش اندوه لفظ و معنی را<br />من قصائده فی الشتائیة:<br />روزی که بر زمین و کُه از سردی هوا<br />بارد سحاب خُرده ٔ کافور بیحساب .<BR><font color=\"HotPink\">♦ </font>انتهی <span class=\"hlight\">:</span> <br />قافیتهای طیانی که مرا حاصل شد<br />همه بربستم در مدح و کنون وقت دعاست .<br /> <font color=\"Red\">مسعودسعد.</font><br />از نصرت و فتح مطلع و مخلص <br />طیان و بدیع و مقطع و مبدا.<br /> <font color=\"Red\">مسعودسعد.</font><br />رفیق و مونس من هزلهای طیانست <br />حکایت خوش من خرزه نامه ٔ حکاک .<br /> <font color=\"Red\">سوزنی .</font><br />خجسته خواجه نجیبی خطیری و طیان <br />قریع و عمعق و حکاک و فرد یافه درای <br />اگر بعهد منندی و در زمانه ٔ من <br />مراستی ز میانْشان همه برای و درای .<br /> <font color=\"Red\">سوزنی .</font><br />زآنکه مقبول مصطفی نشود<br />آنچه طیان ژاژخای آرد.<br /> <font color=\"Red\">انوری .</font><br />ملک منطق الطیر طیار داند<br />نه ژاژ مبتر که طیان نماید.<br /> <font color=\"Red\">خاقانی .</font><br />صاحب مجمع الفصحاء او را بمی و کرمانی می گوید و از لقب ژاژخای که بدو میدهند تعجب می کند و جهت آن را نمیداند و اشعار بسیاری نیز از او نقل می کند. لکن در لغت نامه ٔ اسدی و لغت نامه های دیگر فردها و قطعه هائی که از او نقل میشود با اشعاری که صاحب مجمع الفصحاء از او نقل می کند شاید قریب سه چهار قرن فاصله را نشان میدهد یعنی طیان لغت نامه ها در طرز اداء با اقدم شعرای فارسی همزبان و همزمان می نماید و شعرهای مجمعمنتهی به اشعار اواخر دوره ٔ سلجوقی شبیه است و ژاژخای بودن او هم از همان فردها و قطعه های لغت نامه نیک آشکار است و شاید طیان مجمع الفصحاء طیان دیگریست یااشعار شاعری دیگر بنام طیان ضبط شده است . اینک تک بیت ها و قطعات او که از لغت نامه ٔ اسدی گردآوری شده است :<br />در لغت کلابه :<br />اگر بیند بخواب اندر قرابه <br />زنی را بشکند میخ کلابه .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٤٥٧</span>).</font><br />در لغت «کراسه »:<br />ای عن فلان قال چنان دان که پیش من <br />آرایش کراسه و تمثال دفتر است .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٤٨٩</span>).</font><br />در لغت «خلاشمه »:<br />ریشیش بس فرخج ز گردن برون دمید<br />گوئی خلاشمه ست ز گردن برآمده .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٤٩٦</span>).</font><br />در لغت «کوغاده »:<br />ای بت خیز کیر آخر تا کی از کوغاده کی ؟<br />تا چو من صاحب نیابی سخت کیر و چاپلوس .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٥٠٨</span>).</font><br />در لغت «غوشای »:<br />یکی ز راه همی زرّ برندارد و سیم <br />یکی ز دشت به نیمه همی چِنَد غوشای .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٥١٦</span>).</font><br />در لغت «سل »:<br />دلم تنوره و عشق آتش و فراق تو داغ <br />جگر معلق و بریان و سل ّ بوده کباب .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٣٣٤</span>).</font><br />در لغت «آنین »:<br />سبود و ساغر و آنین و غولین <br />حصیر و جایروب وخیم و پالان .<br />هم طیان گفت :<br />دوغم ای دوست در آنین تو میخواهم ریخت <br />تاکنم روغن از آن دوغ همی جنبانم .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٣٧٢</span>).</font><br />در لغت «پینو»:<br />شعر ژاژ از دهان من شکر است <br />شعر نیک از دهان تو پینو.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٤٠٧</span>).</font><br />در لغت «کابیله »:<br />خایگان تو چو کابیله شده ست <br />رنگ او چون کون پاتیله شده ست .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٤٣٠</span>).</font><br />در لغت «لکانه »:<br />من شاعر حلیمم با کودکان سلیمم <br />زیرا که جعل ایشان دوغست یا لکانه .<br />هم طیان گوید:<br />گر زآنکه لکانه ست آرزویت <br />اینک بمیان ْ ران من لکانه .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٤٣٢</span>).</font><br />در لغت «خرفه »:<br />کسی را کو تو بینی درد سرفه <br />بفرمایش تو آب دوغ و خرفه .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٤٥٢</span>).</font><br />در لغت «لوش »:<br />زن چو این بشنید شه خاموش بود<br />کفشگر کانا و مردی لوش بود.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٢١٣</span>).</font><br />در لغت «لاش »:<br />به لاش عشق من آن نوجوان بسان کلاب <br />حوال و جبه ٔ من لاش کرد و کیسه خراب .<br /><font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٢٢٥</span>).</font><br />در لغت «زوباغ »:<br />زو باغ وقف کرده بر آن مُرزت <br />... خر و مناره ٔ اسکندر.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٢٤٢</span>).</font><br />در لغت «غاوشنگ »:<br />مرد را نهمار خشم آمد از این <br />غاوشنگی را بکف کردش گزین .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٢٦٨</span>).</font><br />در لغت «پوک »:<br />غله کردی به زیر پوک نهان <br />چون برانند پوک بر سر تو (کذا).<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٢٧١</span>).</font><br />در لغت «غساک »:<br />از دهان تو همی آید غساک <br />پیر گشتی ریخت مویت از هباک .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٢٧٦</span>).</font><br />در لغت «گوال »:<br />بزرگان گنج سیم و زر گوالند<br />تو از آزادگی مردم گوالی .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٣٢٧</span>).</font><br />در لغت «سرهال »:<br />بدان منگر که سرهالم بکار خویش محتالم <br />شب تاری بدشت اندر پی جرلاب خرکالم .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٣٣١</span>).</font><br />در لغت «بازخمید»:<br />مردم نه ای آخر به چه میماند رویت <br />چون بوزنه ای کو بکسی باز خماند.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">١٢٠</span>).</font><br />در لغت «کیفر»:<br />شیر غاش است وبه پستان در جغرات شده ست <br />چشم دارد که فروریزد در کیفر تو.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">١٣١</span>).</font><br />در لغت «تندُر» و «تندَر»:<br />خورد سیلی زند بسیار طنبور<br />دهد تیزی ببازی همچو تندور.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">١٣٨</span>).</font><br />در لغت «کاوکلور»:<br />ور تو دو دانگ نداری که دهی <br />رو مدارا کن با کاوکلور.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span>).</font><br />در لغت « دانشگر»:<br />چو دانشگر این قولها بشنود<br />پس آنگه زمانی فروآرمد.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>).</font><br />در لغت «فوز»:<br />شبان تاری بیمار چاکر از غم عشق <br />گهی بگرید و گاهی بریش برفوزد.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">١٨٧</span>).</font><br />در لغت «موز»:<br />موز مکّی اگرچه دارد نام <br />نکنندش چو شکّر اندر جام .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span>).</font><br />در لغت «خراس »:<br />خراس و آخر و خنبه ببردند<br />نبود از چنگشان بس چیز پنهان .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">١٩٨</span>).</font><br />در لغت «فلخ »:<br />مرا زندگانی بدینجای طلخ <br />همه جای دیگر کنندم ز فلخ .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٨٣</span>).</font><br />در لغت «فلغند»:<br />تا نکردی خاک را با آب تر<br />چون نهی فلغند بر دیوار بر.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>).</font><br />درلغت «شتاوند»:<br />جهان جای بقا نیست به آسانی بگذار<br />به ایوان چه بری رنج و به کاخ و به ستاوند.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٩٩</span>).</font><br />در لغت «لاند»:<br />با دفتر اشعار بَرِ خواجه شدم دی <br />من شعر همی خواندم و او ریش همی لاند<br />صد کلج پر از گوه عطا کرد بر آن ریش <br />گفتم که بر آن ریش که دی خواجه همی شاند.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span>).</font><br />در لغت «نُهازید»:<br />لَبْت گوئی که نیم کفته کل است <br />می و نوش اندر او نهفتستی <br />زلف گوئی ز لب نُهازیده ست <br />بگله سوی چشم رفتستی .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">١٠٥</span>).</font><br />در لغت «فلخود»:<br />موی زیر بغلش گشته دراز<br />وز قفا موی پاک فلخیده .<br /><font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span>).</font><br />در لغت «فخمید»:<br />جوان بودم و پنبه فخمیدمی <br />چو فخمیدمی پنبه برچیدمی .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">١١٩</span>).</font><br />ور همه زندگان ترینه شوند<br />تو کُبیتای کُنجدین منی .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٧</span>).</font><br />در لغت «کتب »:<br />زمانه کرد مرا مبتلی بگردش او<br />گهی بنای گلونه گهی بپای کنب .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٣١</span>).</font><br />در لغت «جبغوت »:<br />چون یکی جغبوت پستان بند اوی <br />شیر دوشی زو به روزی یک سبوی .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٤٢</span>).</font><br />در لغت «جبغوت »:<br />غم عیال نبود و غم تبار نبود<br />دلم براش بیاگنده بود چون جبغوت .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).</font><br />در لغت «تلاج »:<br />شب بیامد در برم دربان باج <br />در بجنبانید با بانگ و تلاج .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٥٤</span>).</font><br />در لغت «کلج »:<br />صد کلج پر از گوه عطا کرده بر آن ریش <br />گفتم که بر آن ریش که دی خواجه همی شاند.<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٦١</span>).</font><br />در لغت «لخج »:<br />بینی آن زلفین او چون چنبر بالان نجم <br />گر بلخج اندر زنی ایدون بود چون آبنوس .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٦١</span>).</font><br />در لغت «لنج »:<br />کسی را کو تو بینی درد کولنج <br />به کافش پُشت و زو سرگین برون لِنج .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٦٤</span>).</font><br />در لغت «نخج »:<br />دست و کف ّ پای پیران پرکلخج <br />ریش پیران زرد از بس دود نخج .<br /> <font color=\"Red\">(ص <span class=\"hlight\" dir=\"rtl\">٧٠</span>).</font><br />از غایت احسان تو بر هر ذاتی <br />بر جان تو صدهزار جان میلرزد<br />در حالت بیماری ممدوح خود عرض کرده :<br />گر تیغ تو یک دم از میان برخیزد<br />عصمت همه را ز خانمان برخیزد<br />از بستر غم که جای بدخواه تو باد<br />برخیز سبک ورنه جهان برخیزد.<br /> <font color=\"Red\">(از مجمع الفصحاء ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span> - <span class=\"hlight\" dir=\"rtl\">٣٣٩</span>).</font><br />میرزا محمدخان قزوینی در ضمن تعلیقاتی که بر ج <span class=\"hlight\" dir=\"rtl\">١</span> لباب الالباب نوشته گوید: طیان شاعری است از متقدمین و در السنه ٔ شعراء معروفست به «ژاژخای »، خود گوید:<br />شعر ژاژ ازدهان من شکر است <br />شعر نیک از دهان تو پینو.<br />انوری گوید <span class=\"hlight\">:</span> <br />طبع حسان مصطفائی کو<br />تاثناهای غمزدای آرد<br />زآنکه مقبول مصطفی نشود<br />آنچه طیان ژاژخای آرد.<br /> <font color=\"Red\">(از لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٥</span>).</font><br />اینک برخی از اشعار دیگر طیان که بتفاریق در لغتنامه ٔ اسدی و فرهنگهای دیگر درج است در ذیل ثبت میگردد:<br />در کلمه ٔ «کُبیتا»:<br />شمس دنیا تو فخر و زین منی <br />فخر دنیا تو شمس دین منی <br />ور همه زندگان ترینه شوند<br />تو کبیتای گندمین منی .<br /> <font color=\"Red\">(لغتنامه ٔ اسدی ص <span class=\"hlight\" dir=\"rtl\">٧</span>).</font><br />سرورا یک سخن اصغا کن و انصاف بده <br />خود روا نیست کز انصاف کسی درگذرد<br />هر دم از بنده برنجی که هجا میگوئی <br />ور مدیحی بتو آورد عطائی نبرد<br />شاعری گرسنه در کُنج سرائی خالی <br />از تو آزرده اگر گُه نخورد پس چه خورد.<br />اُلاغ خواسته :<br />صاحبا هر لحظه گردون مینهد<br />از حوادث بر دلم صد گونه داغ <br />پیش لعب این سپهر نیلگون <br />کار من بگذشته از بازی و لاغ <br />در میان زُمره ٔ رذلم چنانک <br />بازنشناسند طوطی از کلاغ <br />خود تو دانی تنگ زندانی بود<br />بلبل خوش نغمه را مأوای زاغ <br />هم مگر زین قوم بِرْهاند مرا<br />ذات مُعطی ّ تو از یک سر الاغ .<br />در اظهار ارادت و اشتیاق :<br />نیست در حیز امکان که توان دادن شرح <br />اشتیاقی که بدیدار همایون دارم <br />چون بگویم بزبان قلم سرگردان <br />که دل از غیبت جانکاه شما چون دارم <br />در دل و دیده گواه است خدایم که همه <br />آرزومندی آن غُرّه ٔ میمون دارم .<br />بجهت بیماری سلطان :<br />از بیم تکسرت جهان میلرزد<br />از لفظ ملالتت زبان میلرزد.<br />جهد آن کن که نمانی ز سعادت محروم <br />کارخود ساز که اینجا دو سه روزی است مقام .<br />هستم چو باد سرسبک آری غریب نیست <br />خاشاک اگر بساحل عمان همی برم <br />مینا نثار معدن فیروزه میکنم <br />بسد بنزد کان بدخشان همی برم .<br />به وقت صبح که خورشید چرخ آینه فام <br />همی زدود ز روی زمانه زنگ ظلام <br />سپاه زنگ هزیمت گرفت از عالم <br />چو شاه روم برافراخت از افق اعلام <br />پدید شد ز شب تیره روشنائی صبح <br />چو گل ز غنچه ٔ تیغ از نیام و مه ز غمام <br />به نیم حمله ٔ خورشید بر رواق سپهر<br />اثر نماند تو گفتی ز هستی اجرام <br />بزیر پرده ٔ کحلی که نام او فلک است <br />نهان شدند همه لعبتان سیم اندام .<br />مرصع است درخت و معطر است چمن <br />بسعی ابر بهاری و باد فروردین <br />ز بس شکوفه ٔ لعبت نهاد پنداری <br />که هست عرصه ٔ بستان نگارخانه ٔ چین .<br />بخت برگشت از من سرگشته تا محروم ماند<br />روی من از ساحت آن حضرت گردون پناه <br />لحظه ای خالی نبودم هرگز از اندوه و غم <br />ساعتی فارغ نگشتم هرگز از فریاد و آه .<br />در عذر ممدوحی که بعد از مدیح گفتن او را هجو گفته و او رنجیده :<br />دمبدم باشد ز رنگ و بوی او میخواره را<br />لاله و گل در جبین و مشک و عنبر در مشام <br />فاش گردد سرّها از لوح محفوظ ار فتد<br />پرتو برق و صفای او درین فیروزه جام <br />چون وصال یار جان بخش و چو رویش دلفریب <br />چون جواب یار تلخ و چون لبش یاقوت فام <br />شادی طبع جوان و دافع اندوه پیر<br />آفت مال کرام و مایه ٔ جود لئام <br />در نصیحت و حکمت و موعظت گوید:<br />ای بغفلت گذرانیده همه عمر عزیز<br />تا چه کردی و چه داری عملت کو و کدام <br />توشه ٔ آخرتت چیست درین راه دراز<br />که تو را موی سفید از اجل آورد پیام <br />وای اگر پرده برافتد که ز بس خجلت و شرم <br />همه بر جای عرق خون دل آید ز مسام <br />دل بر این گنبد خونخواره ٔ گردنده منه <br />که بسی همچو تو دیده ست و ببیند ایام <br />آفریننده ٔ خود را تو اگر بشناسی <br />طی شود در نظر همتت این سبز خیام <br />کام جان از شکر معرفتش شیرین کن <br />تا تو را زهر اجل شهد نماید در کام <br />میتوانی که فرشته شوی از علم و عمل <br />لیکن از همت دون ساخته ای با دد و دام <br />چون شوی همدم حوران بهشتی که تو را<br />همه در آب و گیاهست نظر چون انعام .<br />ایمن شود زمانه ز بدخواه شوربخت <br />خالی شود زمین ز بداندیش خاکسار.<br />فی اللغز:<br />چیست آن اختر رخشان رخ روشن دیدار<br />که بجزدر شب تاریک نباشد بیدار<br />طرفه مرغیست که هم ساکن و هم سیار است <br />باز روشن تن و سیمین دم و زرین منقار<br />عاشق آساست از آنروی که سوزی دارد<br />لیک جان بخش بود بوسه ٔ او چون لب یار<br />همچو مرغیست که در دام طپیدن گیرد<br />قصد بالا کند و بسته دو پایش ناچار<br />گلی از باغ خلیل است و به یک دم چو مسیح <br />مرده را زنده کند لعل لبش دیگر بار<br />افعیی در گلویش کژدم پیچان پیچان <br />در دهانش ملخ سرخ و ملخ افعی خوار<br />گرچه نار است بگلنار همی ماند راست <br />دیده ای میوه که هم نار بود هم گلنار.<br />چو نیم دایره از زرّ ناب پیدا شد<br />هلال عید همایون ز گُنبد ازرق <br />بعکس آنکه نماید ز جام باده ٔ لعل <br />نمود ساغر ماه نو از میان شفق .<br />آن زمان کز دوست پیغام آورد باد صبا<br />خاک در چشم غم افکن زآب آتش رنگ جام <br />باده ای خور کز فروغ او توان دیدن بشب <br />خون مرطوب از عروق و مغز محرور از عظام <br />آسمان را از فروغ قصر مرفوعت مدار<br />اختران را در حریم صحن میمونت مسیر<br />از تماثیل تو نقاش طبیعت منفعل <br />وز تصاویر تو گردون ثوابت با نفیر<br />دور نبود کز خجالت با عُلوّ سده ات <br />روی چرخ لاژوردی زرد گردد چون زریر<br />پُرعجایب چون سپهری پربدایع چون بهشت <br />بلکه باشد این و آن با نسبت قصرت قصیر<br />آن هوای معتدل داری که هستی جاودان <br />چون بهشت ایمن ز سردی ّ دی و گرمی ّ تیر.<br />حُله باف بوستان شد باد نوروزی دگر<br />باغ ازو جنت صفت گشت وجهان دوزخ اثر<br />کسوت زربفت پوشیده ست پنداری چمن <br />پرنیان سبز گسترده ست گوئی بر شمر<br />نقشبندی میکند در بوستان ابر بهار<br />عطرسائی میکند در گُلستان باد سحر<br />گَه نسیم مشکبو از دشت میبارد عبیر<br />گه سحاب نیلگون بر خاک میریزد گهر.<br />روزی سه چار اگر بضرورت مشوش است <br />احوال روزگار نه بر وفق اختیار<br />چندان بود ولی که ضمیر خدایگان <br />حاصل کند فراغت کلی ز گیر و دار<br />گردد ز دشمنان شکم خاک ممتلی <br />گیرد زمین ز خون عدو رنگ لاله زار.<br />حرباصفت ز غایت سرما شود بجان <br />خفاش روزگار طلبکارآفتاب <br />خواهد که چون سمندر زآتش وطن کند<br />مرغابی آن زمان که بود در میان آب .<br />امید مهر و وفا از زمانه عین خطاست <br />از آنکه عادت گیتی همیشه جور و جفاست <br />مباش غره بدین روزگار مردفریب <br />چو کار و بار جهان آگهی که جمله هباست <br />کدام گل بشکفت از چمن که تازه بماند<br />کدام ماه منور تمام شد که نکاست <br />اطراف باغ گشت ز آثار نامیه <br />مینای لعل پرور و دیبای زرنگار<br />بیجاده گون همی شود از لاله بوستان <br />پیروزه رنگ گردد از سبزه جویبار<br />شنگرف ریختند تو گوئی به گلستان <br />زنگار بیختند تو گوئی بمرغزار<br />نسرین ز سیم خام بپوشید پیرهن <br />گلبن ز زرّ پخته برآورد گوشوار<br />تا باغ برگرفت سر طبله ٔ حلی <br />بگشاد باد صبح در نافه ٔ تتار.<br />ای چو گردون سقف تو در شکل و هیأت مستدیر<br />چشم گردونت نخواهد دید در عالم نظیر<br />قبه ٔافلاک نزد طارمت نامرتفع<br />روضه ٔ فردوس نزد ساحتت نادلپذیر.<br /></font></div>'),
(178498, 'طیان', '<span class=\"hlight\">طیان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ) یاسمن صحرائی را گویند و آن مانند لبلاب بر یکدیگر پیچیده و بر شاخه های آن خار میباشد مانند خار گل وآن را بعربی عشبةالنار خوانند. (برهان ) (آنندراج ). یاسمین بری است . (فهرست مخزن الادویه ). یاسمن دشتی .<br /></font></div>'),
(178499, 'طیانة', '<span class=\"hlight\">طیانة.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b>(ع اِمص ) گلکاری کردن . (منتهی الارب ) (آنندراج ). بنائی کردن . پیشه ٔ راز. حرفه ٔ بنائی . گل کاری . (دهار).<br /></font></div>'),
(178500, 'طیانه', '<span class=\"hlight\">طیانه .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) دهی از دهستان بیلوار بخش کامیاران شهرستان سنندج در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی باختر کامیاران و یکهزارگزی شمال سراب کام . دامنه، سردسیر با <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه . آب آن از چشمه . محصول آن غلات و لبنیات . شغل اهالی زراعت و گله داری . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(178501, 'طیانچه', '<span class=\"hlight\">طیانچه .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ]</font></b> (اِ مصغر) طیان خرد. تیانچه . رجوع به طیان شود.<br /></font></div>'),
(178502, 'طیاهیج', '<span class=\"hlight\">طیاهیج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) ج ِ طَیْهوج . (مهذب الاسماء) (دهار). تیهو. رجوع به تیهو شود.<br /></font></div>'),
(178503, 'طیب', '<span class=\"hlight\">طیب .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) ابن عبداﷲبن احمد مکنی به ابومحمد. او راست : قلائد النحر فی وفیات اعیان الدهر که ترجمه ٔ احوال را بترتیب سنوات تا سال <span class=\"hlight\" dir=\"rtl\">٩٢٧</span> هَ. ق . تدوین کرده است . (کشف الظنون چ اسلامبول ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(178504, 'طیب', '<span class=\"hlight\">طیب .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) ابن محمد الخسروانی، کنیت وی ابوطاهر است . عوفی در تذکره ٔ خویش آورده است : خسروانی نوای ثنای او راه انقطاع اسم زدی و مخدرات خاطر او دل مخالف و موافق ربودی .از اماثل شعرای آل سامان بوده در دولت ایشان با عیشی تن آسان . در قصیده ای میگوید در آخر عمر و شدت مرض :<br />چهار گونه کس از من بعجز بنشستند<br />کز آن چهار بمن ذره ای شفا نرسید<br />طبیب و زاهد و اخترشناس و افسونگر<br />به دارو و بدعا و بطالع و تعویذ.<br />و در معنی قناعت و رفض آز گفته است و به الماس بیان گوهر موعظه سفته :<br />تا باز کردم از دل زنگار آز و طَمْع<br />زی هر دری که روی نهم در فراز نیست <br />جاه است و قدر و منفعه آن را که طَمْع نیست <br />عز است و صدر و مرتبه آن را که آز نیست .<br /> <font color=\"Red\">(از لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠</span>).</font><br />و رجوع به خسروانی شود.<br /></font></div>'),
(178505, 'طیب', '<span class=\"hlight\">طیب .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) لقب مرّةبن شراحیل بن الطیب مُکنی به ابواسماعیل است . چون پیوسته بعبادت مشغول بودی و زهد ورزیدی بدین لقب ملقب گردید. (انساب سمعانی برگ <span class=\"hlight\" dir=\"rtl\">٣٧٦</span>).<br /></font></div>'),
(178506, 'طیب', '<span class=\"hlight\">طیب .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) بامخرمة. رجوع به بامخرمه طیب بن عبداﷲبن احمد شود.<br /></font></div>'),
(178507, 'طیب', '<span class=\"hlight\">طیب .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) ابن اسماعیل بن ابراهیم الذهلی، کنیتش ابومحمد و معروف به ابوحمدون دلال و یکی از مشاهیر قُراء و صلحاء زهاد بوده . از کسائی قرائت روایت میکرد، همچنین از یعقوب حضرمی، و نیز از مُسیب بن شریک و سفیان بن عُیَیْنة و شعیب بن حرب حدیث روایت میکرد. ابوالعباس احمدبن مسروق گوید: شنیدم از ابوحمدان مُقری که میگفت : شبی در اثناء نماز حرفی را به ادغام قرائت کردم، در آن شب خواب دیدم که نوری سخت گریبان مرا گرفت و گفت : بینی و بینک اﷲ. من پرسیدم تو کیستی ؟ گفت من آن حرفی هستم که مرا به ادغام قرائت کردی . گفتم ازین پس این عمل از من ناشی نشود، و از آنگاه دیگر حرفی را به ادغام قرائت نکردم . از ابومحمد الحسن بن علی بن صلیح روایت است که گفت : ابوحمدون الطیب بن اسماعیل چشمش نابینا شد، عصاکش او وی را بمسجد برد، چون بمسجد رسیدند عصاکش او را گفت : پای افزار بیرون کن، ابوحمدون پرسید برای چه ؟ گفت : لان ّ فیها اذی . ابوحمدون ازین سخن اندوهناک شد دست بدعا بلند ساخت و دعائی خواند و سپس دست بروی خویش مالید، حق تعالی بینائی بخشید او را، او براه افتاد.<br />ابوعبداﷲبن الخطیب گوید: ابوحمدون راصحیفه ای بود که نام سیصد تن از یاران وی در آن ثبت بود و هر شب برای یکایک آنان دعای خیر میکرد، شبی بنام یاران نیفتاد و خواب وی را درربود، در خواب شنید که او را میگویند امشب چراغهای تو روشن نیست . ابوحمدون از خواب برخاست و نشست و چراغ را روشن کرده صحیفه را برداشت و یکایک یاران را از روی صحیفه بدعای خیریاد کرد تا فراغت یافت . ابوالحسن بن المنادی گوید: ابوحمدون از برگزیدگان زهاد و مشاهیر قُراء بود. پیوسته بمحلهائی که خلوت بود و بجایهائی که کسی در آنجا دیده نمیشد میرفت . مردم را قرائت می آموخت و چندان درطرز آموختن جد میورزید که شاگردان را حافظ کلام اﷲ میساخت و سپس بتعلیم و آموزش دسته ای دیگر از شاگردان میپرداخت . و کان یلتقط المنبوذ کثیراً. (صفة الصفوة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span>).<br /></font></div>'),
(178508, 'طیب', '<span class=\"hlight\">طیب .</span> (ع ص، اِ) بوی خوش . (منتهی الارب ) (مهذب الاسماء). خوشبوی . عطر. بوی . داود ضریر انطاکی گوید: طیب، بر هر شی ٔ که بوی خوش داشته باشد اطلاق میگردد مانند مشک و عنبر و غالیه و مانند آن . (تذکره ٔ داود ضریر انطاکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٠</span>). طیب، ادویه ٔ خوشبوی است مانند مشک و عنبر و عود، وعطر را نیز نامند و آن غذای روح و مقوی قُوا و زیادکننده ٔ سرور و معاشرت با دوستان است و از احب اشیاء است مر جناب حضرت رسالتمآب را صلی اﷲ علیه و آله و سلم . چنانچه فرموده اند: حبب اِلَی َّ من دنیاکم ثلاث النساء و الطیب و قرة عینی فی الصلوة، و آن جناب بسیار خوشبوی استعمال مینموده اند و از بدبوی ناخوش بودند وتطیب بمشک میفرمودند و احادیث بسیار در فضیلت و تحریض بخوشبوئی و خوشبو داشتن لباس و احتراز از کثافت وبدبوئی وارد است . (فهرست مخزن الادویه ) <span class=\"hlight\">:</span> <br />آمد بهار خرم با رنگ و بوی طیب <br />با صدهزار زینت و آرایش عجیب .<br /> <font color=\"Red\">رودکی .</font><br />و آنچه اندرخور این هفده غلام بود از طرائف و طیب و جواهر. (ترجمه ٔ طبری بلعمی ). و از وی <font color=\"DarkGreen\"><b>[ هندوستان ]</font></b> طیبهای گوناگون خیزد و مشک و عود و عنبر و کافور. (حدود العالم ). و همه طیبی که آنجا <font color=\"DarkGreen\"><b>[ به اهواز ]</font></b> بری از هوای وی بوی او برود. (حدود العالم ).<br />بدرگاه بردند چندی صلیب <br />نسیم گُلان آمد و بوی طیب .<br /> <font color=\"Red\">فردوسی .</font><br />در ورقی دیدم نبشته بفرمان امیرالمؤمنین نزدیک امیر ابوالفضل ...برده آمد از زر چندین ... و طیب ... مبلغش سی بار هزارهزار درم بود. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٩١</span>). و مشک و عنبر و کافور و زعفران و عود و دیگر طیبها او به دست آورد. (نوروزنامه ).<br />غرس معالی او بلطف تربیت و طیب آب و تربت شاخها کشیده . (ترجمه ٔ تاریخ یمینی چاپی ص <span class=\"hlight\" dir=\"rtl\">٢٥٥</span>).<br />این کعبه ناف عالم و از طیب ساختش <br />آفاق وصف نافه ٔ مشک تتار کرد.<br /> <font color=\"Red\">خاقانی .</font><br />الزباد، نوع من الطیب . (ابن البیطار).<br />شبی در جوانی و طیب نعم ...<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />چنین صفتها که بیان کردم ای پسر در سفر موجب جمعیت خاطر است، و داعیه طیب عیش . (گلستان ). و رجوع به شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span> شود. <BR><font color=\"Blue\">◄</font> پاک . پاکیزه . <BR><font color=\"Blue\">◄</font> حلال . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خوش مزه . (آنندراج ). ج، اطیاب . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به طیب نفس </span> ؛ به میل خود. بی عنف و کره . بی اکراه . بی اجبار. به رضا و رغبت . بطیب خاطر. با خواست خویش . یقال : فعلت ذلک بطیب نفسی ؛ و طیبة نفسی، یعنی کردم این کار را به خوشی خویش بی اکراه دیگری . (منتهی الارب ).<br /><BR><font color=\"Blue\">◄</font> بهترین از چیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (مص ) خوش شدن . <BR><font color=\"Blue\">◄</font> خوشبوی شدن . پاکیزه شدن .(تاج المصادر بیهقی ) (مصادر زوزنی ). <BR><font color=\"Blue\">◄</font> حلال شدن . <BR><font color=\"Blue\">◄</font> گیاه ناک گردیدن زمین . <BR><font color=\"Blue\">◄</font> پاک و پاکیزه ساختن . (آنندراج ).<br /></font></div>'),
(178509, 'طیب', '<span class=\"hlight\">طیب .</span> (اِخ ) شهری است میان واسط و تستر. (منتهی الارب ). یاقوت در معجم البلدان آورده که : طیب شهرکی است بین واسط و خوزستان و اهالی آن تا زمان حاضر نبطی بوده و هستند و بزبان قوم نبط سخن گویند. خبر داد مرا داودبن احمدبن سعید الطیبی التاجر که آنچه در میان ما معروف و متداول است آنست که شهر طیب از بناهای شیث بن آدم علیهماالسلام است و تا زمان ظهور اسلام نیز مردم آنجا بکیش ملت شیث (مذهب صائبه ) باقی بودند، چون اسلام ظهور یافت قبول اسلام کردند. درین شهر از انواع طلسمات چیزهای شگفت بوده که پاره ای از آنها باطل گردیده و برخی دیگر تا حال باقی است، از آن جمله آنست که زنبور در آن شهر از نعمت زندگانی بی بهره است و بمجردی که زنبوری بدان شهر داخل شود میمیرد، و تا نزدیک زمان ما در آن شهر مار و کژدم یافت نمیشد و تا این تاریخ نیز در آن شهر زاغی که پرهای آن سیاه و سپید (پیسه ) باشد دیده نشده است، همچنین عقعق (عکه، مرغیست ابلق ) درین شهر نایابست . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>).<br />شهری است خرم و آبادان <font color=\"DarkGreen\"><b>[ از خوزستان ]</font></b> و از وی شلواربند خیزد سخت نیکو همچون ارمینی . (حدود العالم ). نام مدینه ای بخوزستان . (اقرب الموارد). و رجوع به تاریخ الحکماء قفطی ص <span class=\"hlight\" dir=\"rtl\">٣٦٠</span> شود.<br /></font></div>'),
(178510, 'طیب', '<span class=\"hlight\">طیب .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (ع ص ) پاک . (منتهی الارب ) (غیاث اللغات ). پاکیزه . طاهر. قوله تعالی <span class=\"hlight\">:</span> و هدوا الی الطیب من القول (قرآن <span class=\"hlight\" dir=\"rtl\">٢٤/٢٢</span>) و ایشان را راه نمائید بگفتار پاک، و هو قول لااله الااﷲ. (تفسیر ابوالفتوح ). ایضاً قوله تعالی : الیه یصعد الکلم الطیب (قرآن <span class=\"hlight\" dir=\"rtl\">١٠/٣٥</span>)؛ و صعود کند، یعنی بخدای و مراد آن بجانبی شود که آنجا حکم جز خدای رانباشد و آن آسمان است چنانکه : رفعت فلاناً الی الحاکم و الی السلطان، یعنی بجائی که حکم حاکم را باشد یاسلطان را. مفسران گفتند: آن کلمه ٔ پاکیزه، گفتن لا اله الااﷲ است و ابوهریره روایت کرد از رسول صلی اﷲ علیه و آله و سلم که او گفت : هو قول سبحان اﷲ و الحمدﷲ ولااله الااﷲ و اﷲاکبر، چون بنده این کلمات بگوید فرشته بیاید و این کلمات بر آسمان برد و به آن خدای را تحیت کنند. و چون عمل صالح با آن یار نباشد از او قبول نکنند. (تفسیر ابوالفتوح ). حلال، خلاف خبیث . (منتهی الارب ) (غیاث اللغات ). مباح . خوش، مقابل نَتِن که ناخوش باشد. لذیذ. ضد خبیث، و چون وصف برای حق تعالی واقعشود مراد آن باشد که ذات پاک او تعالی و تقدس از هرعیب و نقصی منزه است . و از هر گونه آفات و آلایش آفرینش مبری است . و هرگاه برای بنده صفت واقع گردد منظور آنست که بنده از رذائل اخلاق عاری و از اعمال زشت پاکیزه و بزیور صفات حسنه متحلی است . و چون برای اموال صفت آورده شود یعنی آن مال حلال و بی شبهه است، کذا فی شرح المصابیح للقاضی فی اول کتاب البیع. و در ترجمه ٔ مشکوة میگوید: طیب ضد خبیث است بمعنی طاهر نظیف .(کشاف اصطلاحات الفنون ). و گاهی مأخوذ از طیب نفس است . و گاهی از طیب رائحه آید. <BR><font color=\"Blue\">◄</font> و بمعنی حلال نیز آید. <BR><font color=\"Blue\">◄</font> و گاهی اطلاق میکنند بر اخص از حلال که پاک و بی شبهه ٔ کراهت باشد - انتهی . (کشاف اصطلاحات الفنون ). ج، طیبون (در حال رفع)، طیبین (در حال نصب و جرّ). <BR><font color=\"Blue\">◄</font> خوش . (قاموس ). <BR><font color=\"Blue\">◄</font> خوش بوی . بویا. عبق . مُعطر. طیب الرائحه .<br /></font></div>'),
(178511, 'طیب', '<span class=\"hlight\">طیب .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) ابن محمد رسول اﷲ (ص ). صاحب «الاصابة» در قسم سوم حرف طاء آورده که : الطیب ولد رسول اﷲ صلی اﷲ علیه و آله و سلم ... تقدم فی الطاهر. و سیأتی زیادة فی عبداﷲ. (الاصابة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠١</span>). در ذیل ترجمه ٔ طاهر گوید: الطاهربن سید الخلق محمدبن عبداﷲبن عبدالمطلب بن هاشم . مادر طاهر خدیجه بنت خویلد بود. زبیربن بکار در ترجمه ٔ خدیجه در کتاب نسب گوید: خبر داد مرا پسرعمم مصعب که خدیجه از حضرت پیغمبر صلوة اﷲ و سلامه علیه دو پسرآورد، قاسم و طاهر که وی را طیب نیز میخواندند. ولادت طاهر بعد از بعثت پیغمبر (ص ) واقع شد و در کودکی برفت از دنیا و نام وی عبداﷲ بود. مصعب پس از ذکر این خبر به ذکر اسامی چهار دختر حضرت پیغمبر پرداخت . یزیدبن عیاض نیز بروایت از زهری از ذکر اولاد ذکور آن حضرت فقط به بیان نام قاسم و عبداﷲ اکتفا کرده است . زبیربن بکار نیز از محمد، از محمدبن حسن از محمدبن فلیح از یزیدبن عیاض همین خبر را بنحوی دیگر روایت کرده و گفته است که خبر داد مرا ابراهیم بن حمزه و گفت که خدیجه از پیغمبر فقط قاسم و طاهر را آورد، و برخی هم میگویند اولاد ذکور از خدیجه عبداﷲ و طیب بوده، و سپس نام چهار دختر حضرت پیغمبر را بیان کرد و نیز ازطریق ابن لهیعه از ابوالاسود معروف به یتیم عروه روایت شده که گفت خدیجه چهار فرزند ذکور آورد که نام آنها بدین سیاق است : قاسم، طیب، طاهر، عبداﷲ. و سپس نام دختران مولوده ٔ از خدیجه را بیان کرد و نیز از طریق ابوحمزه از ابوبکربن عثمان روایتست که خدیجه چهار پسر و چهار دختر آورد و اسامی هر هشت مولود را بیان کرد، سپس گفت : اما اولاد ذکور خدیجه همگی در مکه بکودکی درگذشتند و اما فرزندان اناث خدیجه هر چهار تن به شوی رفتند و هر کدام فرزند آوردند. راوی خبر مذکور گوید: خبر داد مرا محمدبن فضالة که گفت : خدیجه از حضرت پیغمبر سه فرزند ذکور آورد، قاسم و طاهر و عبداﷲ.قال و حدثنی علی بن صالح عن جدی عبداﷲبن مصعب بن الزبیر کنته امه صفیه اباالطاهر باسم بن اخیها الطاهر و به کان یکنی اخوها ابنها الزبیر و کان ابنه من اظرف الفتیان بمکه و به سمی رسول اﷲ صلی اﷲ علیه و آله و سلم ابنه . و در موفقیات نیز بهمین نحو بیان شده و تصریح گردیده که طاهر پسر زبیر در شعب بدنیا آمد و حضرت پیغمبر هم پسر خویش را بنام پسر زبیر مسمی فرمود. (الاصابة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٩</span>). و نیز صاحب الاصابة در ذیل ترجمه ٔ عبداﷲبن سیدالبشر آورده که : تقدم ذکره فی ترجمة الطاهرو جزم هشام بن الکلبی بان ّ عبداﷲ و الطیب و الطاهر واحد، اسمه عبداﷲ و الطیب و الطاهر لقبان له . (الاصابةج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>). و رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٧</span> و طاهر شود.<br /></font></div>'),
(178512, 'طیب', '<span class=\"hlight\">طیب .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) ابن محمد الباهلی . مرزبانی در کتاب «الموشح » در چندین مورد نام وی را برده و از مطاوی کتاب مذکور چنین استنباط میشود که وی یکی از روات اشعار و علمای نقدالشعر بوده است . رجوع به ص <span class=\"hlight\" dir=\"rtl\">٤٢</span>، <span class=\"hlight\" dir=\"rtl\">١٠٥</span>، <span class=\"hlight\" dir=\"rtl\">١٨٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٠٨</span>، <span class=\"hlight\" dir=\"rtl\">٢١٥</span> کتاب الموشح چ مصر شود.<br /></font></div>'),
(178513, 'طیب آباد', '<span class=\"hlight\">طیب آباد.</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) دهی از دهستان جاپلق بخش الیگودرز شهرستان بروجرد در <span class=\"hlight\" dir=\"rtl\">٣٨</span> هزارگزی شمال الیگودرز و <span class=\"hlight\" dir=\"rtl\">٣٢</span>هزارگزی شوسه ٔ ازنا به دورود. جلگه و معتدل با <span class=\"hlight\" dir=\"rtl\">٧٧٣</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و لبنیات و تریاک و چغندر و پنبه . شغل اهالی زراعت و گله داری . راه آن اتومبیل رو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178514, 'طیب الریح', '<span class=\"hlight\">طیب الریح .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ بُرْ ری ]</font></b> (ع اِ مرکب ) رشته هائی که در میان گل فاخور است .<br /></font></div>'),
(178515, 'طیب العرب', '<span class=\"hlight\">طیب العرب .</span> <font color=\"DarkGreen\"><b>[ بُل ْ ع َ رَ ]</font></b> (ع اِ مرکب ) اذخر است . (اختیارات بدیعی ) (ریاض الادویة). <BR><font color=\"Blue\">◄</font> تبن مکی .<br /></font></div>'),
(178516, 'طیب المشاش', '<span class=\"hlight\">طیب المشاش .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ بُل ْ م ُ ]</font></b> (ع ص مرکب ) کریم النفس . یقال : فلان ٌ طیب المشاش ؛ ای کریم النفس . (منتهی الارب ).<br /></font></div>'),
(178517, 'طیب سای', '<span class=\"hlight\">طیب سای .</span> (نف مرکب، اِ مرکب ) سنگی که بدان عطریات از قبیل مشک و غالیه وغیر آن سایند: قسطناس ؛ سنگ طیب سای . (منتهی الارب ).<br /></font></div>'),
(178518, 'طیب شاه', '<span class=\"hlight\">طیب شاه .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) لقبش جلال الدین و نهمین پادشاه از ملوک شبانکاره است که از سال <span class=\"hlight\" dir=\"rtl\">٦٦٤</span> تا <span class=\"hlight\" dir=\"rtl\">٦٨١</span> هَ . ق . در فارس فرمانروائی داشته است .<br /></font></div>'),
(178519, 'طیب شاه', '<span class=\"hlight\">طیب شاه .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) ملقب به امیر. از امرای عصر امیر پیر حسین چوپانی که با چند تن از همراهان دیگر وی مانند شمس الدین صاین قاضی سمنانی و امی زاده علی پیلتن یکباره از امیر پیرحسین گریخت وبملک اشرف که با امیر پیر حسین نبرد میکرد، پیوست . رجوع به حبیب السیر چ تهران جزو <span class=\"hlight\" dir=\"rtl\">٢</span> از ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩١</span> شود.<br /></font></div>'),
(178520, 'طیب نفس', '<span class=\"hlight\">طیب نفس .</span> <font color=\"DarkGreen\"><b>[ ب ِ ن َ ]</font></b>(ترکیب اضافی، اِ مرکب ) (اصطلاح احکام نجوم ) آن است که کوکب در فرح یا در شرف خود باشد و علاوه کوکب نهاری در روز تحت الارض و کوکب لیلی در شب فوق الارض باشد.<br /></font></div>'),
(178521, 'طیب و طاهر', '<span class=\"hlight\">طیب و طاهر.</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ب ُ هَِ ]</font></b> (ترکیب عطفی، ص مرکب ) از اتباع است . پاک و پاکیزه .<br /></font></div>'),
(178522, 'طیب و مطیب', '<span class=\"hlight\">طیب و مطیب .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ب ُ م ُ طَی ْ ی ِ ]</font></b> (اِخ ) هر دو پسران نبی صلی اﷲ علیه و آله و سلم . و در مردم نام ایشان طیب و طاهر مشهور است . (غیاث اللغات ) (آنندراج ). رجوع به طیب بن محمد (ص ) شود.<br /></font></div>'),
(178523, 'طیب کسب', '<span class=\"hlight\">طیب کسب .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (ترکیب اضافی، اِ مرکب ) زهد. (منتهی الارب ).<br /></font></div>'),
(178524, 'طیبات', '<span class=\"hlight\">طیبات .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) نام مرکز بلوک پائین ولایت باخرز از ولایت باخرز و خواف خراسان واقع در جنوب کاریز. (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١٩٨</span>). درفرهنگ جغرافیائی ایران آمده است : نام یکی از بخشهای تابعه ٔ شهرستان مشهد. محدود است از طرف خاور بدشت خدنگ هریرود و مرز ایران و افغانستان، از باختر به بخش حومه ٔ تربت حیدریه، از شمال بکوه بیزک و بخش تربت جام، از جنوب بکوههای باخرز. این بخش در جنوب شهرستان مشهد و آخرین حد ایران و افغانستان سر راه هرات واقعشده، از نظر تجارت قابل اهمیت میباشد زیرا کلیه ٔ واردات و صادرات و متبادله ٔ جنسی بین ایران و افغانستان در گمرکات این بخش صورت میگیرد. دو رشته ارتفاعات معروف بکوه بیزک و باخرز بواسطه ٔ مجاورت با خاک افغانستان محل دستبرد دزدان و سارقین است زیرا بواسطه ٔ نداشتن آب کافی عبور و مرور کمتر است و علاوه بر آن تنگه ها و گدارهای خطرناکی وجود دارد که عبور از آنها خالی از اشکال نیست . هوای بخش بواسطه ٔ مجاورت با کویر لوت گرم و دارای وزش بادهای شدید خشک و سوزان است که از سمت دشت ناامید و سیستان از اوایل خرداد تا مردادماه جریان دارد. آب بخش از قنوات تأمین میشود. محصول عمده غلات، تریاک، زیره ٔ سبز، منداب و میوه جات است . شغل اهالی زراعت و تجارت، کسب مالداری و قالیچه بافی است . راه شوسه ٔ هرات از این بخش عبور میکند. از طریق شهرنو به تربت حیدریه اتومبیل رو است و به اغلب آبادی ها قسمتهای مرزی جاده ٔ فرعی احداث شده است . این بخش از سه دهستان بنام یوسف آباد، پائین ولایت باخرز، مشهد ریزه، میان ولایت باخرز، شهرنو، بالاولایت باخرز که دارای <span class=\"hlight\" dir=\"rtl\">١٠٥</span> آبادی هستند تشکیل یافته و جمیع نفوس آن درحدود <span class=\"hlight\" dir=\"rtl\">٤٧٢٢٧</span> نفر است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(178525, 'طیبات', '<span class=\"hlight\">طیبات .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (ع ص، اِ) ج ِ طیبة که تأنیث طیب است . یعنی خوشیها، و در تمام معانی با طَیّب متفق میباشد. چیزهای پاکیزه، و قوله تعالی <span class=\"hlight\">:</span> و رزقکم من الطیبات ؛ روزی کرد (خدای تعالی ) شما را از ملاذ و مشهیات حلال و پاکیزه . (قرآن <span class=\"hlight\" dir=\"rtl\">٧٢/١٦</span>، از تفسیر ابوالفتوح ).کلوا من طیبات ما رزقناکم <font color=\"DarkGreen\"><b>[ قرآن <span class=\"hlight\" dir=\"rtl\">٥٧/٢</span> ]</font></b>؛ بخورید این نعمتهای پاک که شما را روزی کرده ایم . (قصص العلما ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>). <BR><font color=\"Blue\">◄</font> زنان پاک . زنان پارسا. قوله تعالی : الخبیثات للخبیثین و الخبیثون للخبیثات ؛ ابن زید گفت معنی آنست که : زنان ناپارسا مردان ناپارسا را شایند، و مردان ناپارسا زنان ناپارسا را شایند و معنی بر این وجه چنان بود: الزانی لاینکح الا زانیة او مشرکة و الزانیةُ لاینکحها الازان . (قرآن <span class=\"hlight\" dir=\"rtl\">٣/٢٤</span>) او مشرک چه ایشان لایق یکدیگر باشند. و کذلک القول فی الطیبات . (از تفسیر ابوالفتوح ). <BR><font color=\"Blue\">◄</font> خوش طبعیها. ظرافتها. (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> چیزهای خوش مطبوع <span class=\"hlight\">:</span> <br />زهر از قبل تو نوشداروست <br />فحش از دهن تو طیبات است .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِخ ) نام قسمتی از غزلیات سعدی <span class=\"hlight\">:</span> <br />چند خواهی گفت سعدی طیبات .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(178526, 'طیبات', '<span class=\"hlight\">طیبات .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) قصبه ٔ مرکز بخش طیبات شهرستان مشهد در <span class=\"hlight\" dir=\"rtl\">١٤٤</span> هزارگزی جنوب مشهد سر راه هرات . جلگه و گرمسیر با <span class=\"hlight\" dir=\"rtl\">٤٧٠٨</span> تن سکنه . آب آن از قنات . محصول آنجا غلات و تریاک و زیره ٔ سبز، منداب و میوه جات .شغل اهالی زراعت و تجارت و مالداری . راه آن اتومبیل رو است . دبستان و <span class=\"hlight\" dir=\"rtl\">٧٥</span> باب مغازه ٔ مختلف دارد. دارای کارخانه ٔ برق است . ادارات دولتی، گمرک، ژاندارمری، پست و تلگراف، کلانتر مرز، آمار ثبت املاک و دفتر ازدواج و طلاق، دارائی، بخشداری و شهرداری دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>). و رجوع به طایباد و تایباد شود.<br /></font></div>'),
(178527, 'طیباد', '<span class=\"hlight\">طیباد.</span> (اِخ ) قریه ای است از توابع آمل . (سفرنامه ٔ مازندران رابینو ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(178528, 'طیباریوس', '<span class=\"hlight\">طیباریوس .</span> (اِخ ) دومین شاهنشاه و قیصر روم، پسر لیوی و پسرخوانده ٔ اگوست . مردی باقابلیت و پادشاهی متنور و مُحتاط بود لکن بواسطه ٔ آنکه وزیروی (سِژان ) وی را سخت زیر نفوذ خویش داشت خصلت بدگمانی در طبیعت وی رسوخ یافته بود و در آخر به بدترین ستمگری عمرش به پایان رسید. تولد وی <span class=\"hlight\" dir=\"rtl\">٤٢</span> سال پیش از میلاد مسیح علیه السلام و وفاتش <span class=\"hlight\" dir=\"rtl\">٣٧</span> سال بعد از میلاد رخ داد. (ترجمه از پُتی لاروس ایلوستره ). نام کامل وی طیباریوس کلودیوس نیرون بود. بعد از اوغسطس قیصر شد (<span class=\"hlight\" dir=\"rtl\">١</span> و <span class=\"hlight\" dir=\"rtl\">٢</span>: و <span class=\"hlight\" dir=\"rtl\">٣</span>:<span class=\"hlight\" dir=\"rtl\">١</span>) و با وجودی که بعضی از اخلاق حسنه و صفات حمیده داشت بیحیا و ظالم بود. و اغلب زندگانی و زیست مسیح در ایام حکومت وی بود. برخی را گمان چنان است که وی دیوانه بود و ابتدای سلطنتش در سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٤</span> بعد از مسیح بوده، مدت <span class=\"hlight\" dir=\"rtl\">٢٣</span> سال ملک راند. (قاموس کتاب مقدس ). رجوع به طباریس و ص <span class=\"hlight\" dir=\"rtl\">٧٣</span> و <span class=\"hlight\" dir=\"rtl\">٧٥</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> عیون الانباء شود.<br /></font></div>'),
(178529, 'طیبة', '<span class=\"hlight\">طیبة.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) مدینة الرسول صلی اﷲ علیه و آله و سلم . قبل انما سمیت بطیبة بنت قیداربن اسماعیل وکانت تسکنها. (منتهی الارب ). مدینه . یثرب . طابة. شهری که پیغمبر صلواة اﷲ علیه و آله بدانجا هجرت کرد.<br /></font></div>'),
(178530, 'طیبة', '<span class=\"hlight\">طیبة.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ع ص ) حلال . <BR><font color=\"Blue\">◄</font> روا. <BR><font color=\"Blue\">◄</font> شراب صافی و خالص آن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (مص ) حلال شدن . (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> خوش شدن . <BR><font color=\"Blue\">◄</font> خوش بوی شدن . <BR><font color=\"Blue\">◄</font> پاکیزه شدن . (تاج المصادر بیهقی ).<br /></font></div>'),
(178531, 'طیبة', '<span class=\"hlight\">طیبة.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) بنت العجاج المجاشعی، عیال فرزدق شاعر. رجوع به حاشیه ٔ ج <span class=\"hlight\" dir=\"rtl\">٤</span> عیون الاخبار ابن قتیبه چ دار الکتب المصریه شود.<br /></font></div>'),
(178532, 'طیبة', '<span class=\"hlight\">طیبة.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) دهیست نزد زرود. <BR><font color=\"Blue\">◄</font> نام زمزم . <BR><font color=\"Blue\">◄</font> نام مدینه ٔ منوره . یثرب . مدینةالسلام . رجوع به طابة شود. (منتهی الارب ).<br /></font></div>'),
(178533, 'طیبة', '<span class=\"hlight\">طیبة.</span> <font color=\"DarkGreen\"><b>[ ی َ ب َ ]</font></b> (ع ص ) کار بی دغا و فریب . یقال : سبی ٌ طیبة، ای بلا غدر و نقض عهد. (منتهی الارب ). برده ای که در او هیچ شبهت نباشد. (مهذب الاسماء).<br /></font></div>'),
(178534, 'طیبة', '<span class=\"hlight\">طیبة.</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ب َ ]</font></b> (ع ص ) تأنیث طیب، و در تمام معانی با طیب برابر است . ج، طیبات . مقابل خبیثة. قوله تعالی <span class=\"hlight\">:</span> اء لم تر کیف ضرب اﷲ مثلاً کلمةً طیبةً کشجرة طیبة (قرآن <span class=\"hlight\" dir=\"rtl\">٢٤/١٤</span>)؛ نمی بینی ای محمدیعنی نمیدانی که چگونه مثل زد خدای تعالی که گفت کلمتی پاکیزه چون درختی پاک است . مفسران گفتند: مراد بکلمه ٔ پاک گفتن لااله الااﷲ است . (تفسیر ابوالفتح ). و نیز قوله تعالی : و جرین بهم بریح طیبة (قرآن <span class=\"hlight\" dir=\"rtl\">٢٢/١٠</span>)؛ وکشتیها ببرد ایشان را بباد خوش چون باد نرم باشد کشتی خوش رود و راست و آسان رود. (تفسیر ابوالفتوح ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ارواح طیبة</span> ؛ روانهای پاک . در برابر ارواح خبیثة (روانهای پلید و ناپاک ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خمسه ٔ طیبة</span>؛ محمد و علی و فاطمه و حسن و حسین صلوة اﷲ و سلامه علیهم اجمعین .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">طیبةالرائحة</span> ؛ خوشبوی . معطر.<br /></font></div>'),
(178535, 'طیبة', '<span class=\"hlight\">طیبة.</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ب َ ]</font></b> (اِخ ) نام مدینه ٔ رسول صلی اﷲ علیه و آله و سلم . <BR><font color=\"Blue\">◄</font> دوده ای است به مصر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نام قریه ٔعرض از توابع شام که واقع بین تدمر و حلب میباشد.<br /></font></div>'),
(178536, 'طیبة', '<span class=\"hlight\">طیبة.</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ب َ ]</font></b> (اِخ ) شهری است میان واسط و عراق و کوره ٔ اهواز، و دعبل شاعر شیعی خزاعی بدانجا درگذشت . و رجوع به روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٢٧٧</span> شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178537, 'طیبت', '<span class=\"hlight\">طیبت .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ع اِمص ) مزاح . خوش طبعی . (غیاث اللغات ) (آنندراج ). خوش منشی . خوش مزگی . بازی . شوخی <span class=\"hlight\">:</span> <br />طیبتی شاعرانه کردم من <br />تا نبندی دل اندرین زنهار.<br /> <font color=\"Red\">مسعودسعد.</font><br />ز روی طیبت گفتم بزرگواری کن <br />جواب گوی و ز طیبت مشو دل آزرده .<br /> <font color=\"Red\">سوزنی .</font><br />با تو بر روی بساط انبساط<br />نرد طیبت باخت خادم یک ندب .<br /> <font color=\"Red\">سوزنی .</font><br />هیچ شعری نَبُوَد اندر شعر خوش من <br />کاندر او طیبتکی نَبْوَد و زیج و بازی .<br /> <font color=\"Red\">سوزنی .</font><br />زن بسی گفتش که آخر ای امیر<br />گر مزاحی کردم از طیبت مگیر.<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به طیبت نفس </span> ؛ به طیب نفس . به طیب خاطر <span class=\"hlight\">:</span> <br />خراج اگر نگذارد کسی به طیبت نفس <br />بقهر از او بستانند و قهر سرهنگی .<br /> <font color=\"Red\">سعدی (گلستان ).</font><br /><BR><font color=\"Blue\">◄</font> (اِ) نام ماهیست در تاریخ یهود، و آن را طیبث نیز گویند. رجوع به طیبث شود.<br /></font></div>'),
(178538, 'طیبت آمیز', '<span class=\"hlight\">طیبت آمیز.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ن مف مرکب ) سخنی آمیخته با شوخی . کلامی که آمیخته با مزاح و خوش منشی باشد <span class=\"hlight\">:</span> غالب گفتار سعدی طرب انگیز است و طیبت آمیز. (گلستان سعدی ).<br /></font></div>'),
(178539, 'طیبث', '<span class=\"hlight\">طیبث .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِ) نام ماهیست در تاریخ یهود. یکی از ماههای معروف قوم یهود است . ملاحظه در ماه استر <span class=\"hlight\" dir=\"rtl\">٢</span>:<span class=\"hlight\" dir=\"rtl\">١٦</span>. اسم ماه دهم سال مقدس ملی عبرانیان است که با هلال جینوری یا سلخ دیسمبرماه فرنگی شروع میکند. روز هشتم و نهم و دهم این ماه روزهای مخصوص روزه بود. (قاموس کتاب مقدس ).<br /></font></div>'),
(178540, 'طیبرس', '<span class=\"hlight\">طیبرس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابن عبداﷲ الجندی النحوی، ملقب به علأالدین و الکاتب الرئیس . او راست منظومه ای در علم نحومشتمل بر<span class=\"hlight\" dir=\"rtl\">٩٠٠</span> بیت که مطالب الفیه ٔ ابن مالک و مقدمه ٔابن حاجب را در آن گنجانیده و خود نیز بر آن مطالبی افزوده و سپس بشرح آن پرداخته است . (کشف الظنون ).<br /></font></div>'),
(178541, 'طیبط', '<span class=\"hlight\">طیبط.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ع اِ) مرغی از درازپایان . ابوطیط. رجوع به «ابوطیط» شود.<br /></font></div>'),
(178542, 'طیبغا', '<span class=\"hlight\">طیبغا.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) علاءالدین دوادار بکلیتی . وی مبتکر آلتی است که در علم نجوم بکار میرود. نام آن آلت «ربعکاری بر مقنطرات خط استواء» است . وی را رساله ای است که در آن آلت بحث میکند.<br /></font></div>'),
(178543, 'طیبوث', '<span class=\"hlight\">طیبوث .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) کرم شب تاب . (تذکره ٔ داود ضریر انطاکی : حباحب ).<br /></font></div>'),
(178544, 'طیبی', '<span class=\"hlight\">طیبی .</span> (اِخ ) (الَ ...) احمدبن احمد الطیبی . از فضلاء دمشق بوده . او راست کتابی در «خُطب »، و «مناسک الحج » را بنظم آورده، دیگر کتابی بنام «المفید» در علم تجوید فراهم آورده است . شغل وی تدریس و وعظو تذکیر بود و از عوائد اوقاف بنی منجک اعاشه میکرد.وفات وی بسال <span class=\"hlight\" dir=\"rtl\">٩٨١</span> هَ . ق . بوده است . نقل از تراجم الاعیان بورینی که مخطوط است . (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>).<br /></font></div>'),
(178545, 'طیبی', '<span class=\"hlight\">طیبی .</span> (اِ) بهشت به لغت هندی . (منتهی الارب ). طوبی ̍.<br /></font></div>'),
(178546, 'طیبی', '<span class=\"hlight\">طیبی .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) یکی از طوایف ایل قشقائی فارس که مرکب از <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> خانوار است و در حوالی سمیرم مسکن دارند. (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٨٢</span>).<br /></font></div>'),
(178547, 'طیبی', '<span class=\"hlight\">طیبی .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) ناحیه ٔ ایل طیبی، از ایلات لیراوی کوه و در شماره نزدیک به دوهزار خانوار باشند و بر چندین تیره قسمت شده اند: اولاد تاج طیب، تاحسین شاهی، تارضائی، تاعین علی، تاماولی، تامرادی، تاویسی، چارگاهی، خواجه دزکی، سل شهر وسماعیلی، عالی طیب، قنبری، گرائی، گیوه چرمی ناصرطبیب . و این جماعت چندین محل از بلاد شاپور و ناحیه ٔ رون را تصرف کرده بنام ناحیه ٔ طیبی شهرت داده اند. و این ناحیه ٔ طیبی میانه ٔ شمال و مشرق بهبهان است . در ازای آن از سه گنبدان تا قلعه ٔ رئیسی هشت فرسخ پهنای آن، از قریه ٔ ترو تا المان شش فرسخ و قشلاق زمستانه ٔ ایل طیبی در محال بلاد شاپور است و ییلاق آنها از محال رون است . کشت و زرع آنها در بلاد شاپور گندم و جو و پنبه و برنج و کنجد. آبش از رودخانه و چشمه است و قصبه ٔ این ناحیه لنده است . ده فرسخ از بلده ٔ بهبهان و پنج فرسخ از قصبه ٔ ده دشت دور است . (فارسنامه ٔ ناصری ).<br /></font></div>'),
(178548, 'طیبی', '<span class=\"hlight\">طیبی .</span> (ص نسبی ) نسبتی است که به مقیمان شهر طیب که بین واسطو کوره ٔ اهواز واقع شده، میدهند. (انساب سمعانی ).<br /></font></div>'),
(178549, 'طیبی', '<span class=\"hlight\">طیبی .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b>(ص نسبی ) نسبتی است که به اولاد ابوطیبة عیسی بن سلیمان یکی از محدثین که از امام جعفر صادق علیه السلام و از کرزبن وبرة و سلیمان اعمش روایت دارد، داده شده است و خانواده ٔ طیبی عموماً در جرجان مقیم و در آنجا دارای ضیاع و عقار بسیار میباشند. (انساب سمعانی ).<br /></font></div>'),
(178550, 'طیبی', '<span class=\"hlight\">طیبی .</span> (اِخ ) (الَ ...) محمدبن علی بن عبدالرحمن الطیبی الدمشقی الشافعی، مُفتی حوران (<span class=\"hlight\" dir=\"rtl\">١٢٤١</span>-<span class=\"hlight\" dir=\"rtl\">١٣١٧</span> هَ . ق .). علم فقه را نزد پدر وجد خویش فراگرفت و سپس هم ّ خویش را در فرائض و حساب مصروف و مشغول ساخت، چندی نیز در ربع و اسطرلاب و اندکی در هندسه کار کرد و مدت زمانی امور فتوی و تقسیم مواریث و آبها در دمشق به امانت وی محول گردید و بسال <span class=\"hlight\" dir=\"rtl\">١٢٨٨</span> هَ . ق . بسمت مفتی حوران منتخب شد. وی را رساله ای است در فن مساحت که بطبع نرسیده . دیگر کتابی بنام خلاصة الترجیع للدین الصحیح که به مصر در مطبعه ٔ سنگی چاپ شده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٥٤</span>).<br /></font></div>'),
(178551, 'طیبی', '<span class=\"hlight\">طیبی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ )(الََ ...) نامش حسین بن محمدبن عبداﷲ الطیبی . وی ازعلماء حدیث و تفسیر و بیان بود. ثروتی فراوان از ارث پدر و تجارت به دست آورده و تمامی را بمصارف خیریه رساند بحدی که در پایان عُمر فقیر و نیازمند شد. مردی فروتن و با ارباب بدعت سخت مخالف بود. پیوسته ملازم تعلیم طُلاب بود و نسبت به بینوایان آن طبقه انفاق و احسان میکرد. در استخراج دقائق از کلام حق و سنت پیمبر آیتی بود. وی را ضعف باصره عارض شده بود. از تألیفات وی یکی «التبیان فی المعانی و البیان » است که بطبع نرسیده . دیگر شرح کشاف در تفسیر و شرح مشکاة المشکاة در حدیث است . وفات وی بسال <span class=\"hlight\" dir=\"rtl\">٧٤٣</span> هَ . ق . بوده است . نقل از الدرر الکامنة. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٩</span>).<br /></font></div>'),
(178552, 'طیبی سرحدی', '<span class=\"hlight\">طیبی سرحدی .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ی ِ س َ ح َدْ دی ]</font></b> (اِخ ) نام یکی از دهستانهای بخش کهکیلویه ٔ شهرستان بهبهان است . این دهستان بین دهستان بهمئی گرمسیر، بهمئی سردسیر، طیبی گرمسیر، دشمن زیاری، در جنوب رودخانه ٔ کارون واقع گردیده است . موقع طبیعی کوهستانی و هوای آن سردسیر و مالاریائی است . از <span class=\"hlight\" dir=\"rtl\">٤٦</span> آبادی بزرگ و کوچک تشکیل شده . جمعیت آن در حدود پنجهزار تن میباشد. قراء مهم آن عبارتند از فارتق که دارای <span class=\"hlight\" dir=\"rtl\">١٥٠٠</span> تن جمعیت است و قلعه ٔ رئیسی که مرکز دهستان میباشد. آب مصرفی سکنه از چشمه تأمین میگردد. محصول عمده غلات دیمی، پشم، لبنیات و پوست میباشد. شغل اهالی زراعت و حشم داری . صنایع دستی زنان قالی، قالیچه و جوال بافی است . راههای دهستان مالرو و صعب العبور است . ساکنین قراء از تیره های مختلف طیبی هستند. اهالی این دهستان تابستانها به ارتفاعات شمالی زردکوه عزیمت و در پائیز مراجعت مینمایند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178553, 'طیبی شاهی', '<span class=\"hlight\">طیبی شاهی .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ی ِ ]</font></b> (اِخ ) دهی از دهستان حومه ٔ بخش میناب شهرستان بندرعباس در <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی جنوب میناب و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی خاور راه مالرو سیریک به میناب . جلگه و گرمسیر و مالاریائی با <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن سکنه . آب آن از رودخانه . محصول آنجا خرما و مرکبات . شغل اهالی زراعت و مکاری . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(178554, 'طیبی گرمسیر', '<span class=\"hlight\">طیبی گرمسیر.</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ی ِ گ َ ]</font></b> (اِخ ) نام یکی از دهستانهای بخش کهکیلویه ٔ شهرستان بهبهان است . این دهستان بین دهستانهای بویراحمد سردسیر، دشمن زیاری، طیبی سرحدی، بهمئی سردسیر و دهستان حومه ٔ بهبهان واقع شده است . موقع طبیعی دهستان کوهستانی، هوای آن اغلب گرم و مالاریائی است . از <span class=\"hlight\" dir=\"rtl\">٧٨</span> آبادی بزرگ و کوچک تشکیل شده . جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">١٧</span>هزار تن میباشد. قراء مهم آن عبارتند از سوق، دیل، برم سبز، کتک . مرکز دهستان قصبه ٔ لنده است . آب مصرفی دهستان از رود و چشمه و چاه تأمین میشود. محصول عمده غلات دیمی، پشم و لبنیات است . شغل مردان زراعت و حشم داری .صنایع دستی زنان قالی، قالیچه، جوال و گلیم بافی است . راههای دهستان بطور کلی مالرو است . ساکنین از طوایف مختلف طیبی هستند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178555, 'طیبین', '<span class=\"hlight\">طیبین .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) نام کوهی است در شام . قلقشندی آرد: و در کوه معروف به طیبین شام فرقه ای از قبیله ٔ همدانست . (صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٨</span>).<br /></font></div>'),
(178556, 'طیبین', '<span class=\"hlight\">طیبین .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (ع ص، اِ) ج ِ طیب (در حال نصب و جرّ). رجوع به طیب شود.<br /></font></div>'),
(178557, 'طیة', '<span class=\"hlight\">طیة.</span> <font color=\"DarkGreen\"><b>[ طی ی َ ]</font></b> (ع اِ) نورد دراز. <BR><font color=\"Blue\">◄</font> هیئت نورد. یقال : انه لحسن الطیة. <BR><font color=\"Blue\">◄</font> نیت . قصد. یقال : مضی لطیته ای لنیته التی انتواها. <BR><font color=\"Blue\">◄</font> جائی که قصد بدان دارد. یقال : وَ بعدَت عنا طیته ُ؛ ای مقصده و منزله الذی انتواه . (منتهی الارب ). منزل . مقصد. آنجا که قصد کرده باشند. (مهذب الاسماء). موضعی که قصد آن داشته باشند. <span class=\"hlight\" dir=\"rtl\">٣٩٦٥</span>(منتخب اللغات ).<br /></font></div>'),
(178558, 'طیثار', '<span class=\"hlight\">طیثار.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) شیر بیشه . اسد. <BR><font color=\"Blue\">◄</font> بیشه . (منتهی الارب ) (مهذب الاسماء). طَثْیار. <BR><font color=\"Blue\">◄</font> (ص ) رجل طَیْثار؛ مرد بیباک . طثیار. (منتهی الارب ).<br /></font></div>'),
(178559, 'طیثال', '<span class=\"hlight\">طیثال .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ناحیتی است <font color=\"DarkGreen\"><b>[ در هندوستان ]</font></b> به هیتال پیوسته، میانشان کوهیست صعب ... و جائی کم نعمت است . (حدود العالم ).<br /></font></div>'),
(178560, 'طیجن', '<span class=\"hlight\">طیجن .</span> <font color=\"DarkGreen\"><b>[ طَ ج َ ]</font></b> (معرب، اِ) طاجن . معرب تاوه . تابه که در آن بریان کنند. (منتهی الارب ) (آنندراج ). رجوع به طاجن شود. تابه ٔ روغن . (دهار). تابه ٔ نان پزی . (فهرست مخزن الادویة). تابه ٔ روغن جوش . ج، طیاجن . سیوطی در المزهر بنقل از جمهره ٔ ابن درید گوید: فمما اخذوه (ای العرب ) من الفارسیة: الطیجن و الطاجن . و اصله طابق . و الطابق و الطاجن الفارسیة. قال ابن درید: و «الطیجن » و هو المقلی بالفارسیة و قد تکلمت به العرب . (المعرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span>). ناشر کتاب المعرب در حاشیه ٔ کتاب گوید: نص عبارت ابن درید در الجمهرة (ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>) این است : «الطیجن، الطابق، لغةٌ شامیةٌ و احسبها سریانیة او رومیة». آنگاه گوید: و علل الجوهری التعریب بان ّ الطاءو الجیم لایجتمعان فی کلام العرب، و نص فی اللسان و المعیار علی ان فارسیة الکلمة «تابه » و رجح اَدّی شیرعلی ان الاصل یونانی ٌ. (حاشیه ٔ <span class=\"hlight\" dir=\"rtl\">٢</span> از ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span> المعرب ).<br /></font></div>'),
(178561, 'طیح', '<span class=\"hlight\">طیح .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) چوب که در بن فدان باشد. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (مص ) بیوفتیدن . <BR><font color=\"Blue\">◄</font> هلاک شدن . <BR><font color=\"Blue\">◄</font> سرگشته شدن در زمین . (تاج المصادر بیهقی ). و زعم الخلیل ان طاح یطیح من ذوات الواو، لقولهم : طوحته . (تاج المصادر بیهقی ).<br /></font></div>'),
(178562, 'طیحة', '<span class=\"hlight\">طیحة.</span> <font color=\"DarkGreen\"><b>[ طَ ح َ ]</font></b> (ع ص، اِ) امور دشوار که دوری اندازد میان قوم، یقال : اصابتهم طیحةٌ؛ ای امور فرّقت بینهم . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178563, 'طیخ', '<span class=\"hlight\">طیخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) آلوده گردیدن بکار زشت . یقال : طاخ طیخاً. (منتهی الارب ) (آنندراج ). آلوده شدن . (تاج المصادر بیهقی ). آلوده شده به عیبی . (زوزنی ). <BR><font color=\"Blue\">◄</font> آلوده کردن . (تاج المصادر بیهقی ) (زوزنی ): طاخ فلاناً؛ آلوده کرد او را بزشتی . <BR><font color=\"Blue\">◄</font> بزرگ منشی کردن . (منتهی الارب ). تکبر کردن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> ستیهیدن در کار باطل و غرق شدن در آن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178564, 'طیخ', '<span class=\"hlight\">طیخ .</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (ع اِ) صوت حکایت خنده . قالوا: طیخ ِطیخ ِ، مبنی بر کسر، یعنی قهقهه کردند. <BR><font color=\"Blue\">◄</font> (اِمص ) تکبر. بزرگ منشی . (منتهی الارب ) (آنندراج ). و قیل بالحاء. (منتهی الارب ).<br /></font></div>'),
(178565, 'طیخ', '<span class=\"hlight\">طیخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) جائیست در پائین ذوالمروة، و ذوالمروة بین خشب و وادی القری واقع است . (از معجم البلدان ).<br /></font></div>'),
(178566, 'طیخ طیخ', '<span class=\"hlight\">طیخ طیخ .</span> <font color=\"DarkGreen\"><b>[ خ ِ خ ِ ]</font></b> (ع اِصوت ) صوت حکایت آواز خندنده . (منتهی الارب ).<br /></font></div>'),
(178567, 'طیخور', '<span class=\"hlight\">طیخور.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ )دهی جزء دهستان کوهپایه ٔ بخش آبیک شهرستان قزوین در<span class=\"hlight\" dir=\"rtl\">٢٤٠٠٠</span> گزی شمال باختری آبیک و <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی راه شوسه .کوهستانی معتدل با <span class=\"hlight\" dir=\"rtl\">٤٢٤</span> تن سکنه . آب آن از چشمه . در بهار از رودخانه ٔ محلی . محصول آنجا غلات و بنشن و انگور و میوه جات . شغل اهالی زراعت و گلیم بافی و گیوه چینی . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(178568, 'طیر', '<span class=\"hlight\">طیر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (الَ ...) نام محلی که آن را رکن هم میگفته اند. رجوع به الجماهر بیرونی ص <span class=\"hlight\" dir=\"rtl\">٢٧١</span> شود.<br /></font></div>'),
(178569, 'طیر', '<span class=\"hlight\">طیر.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) پریدن . (منتهی الارب ) (آنندراج ). یقال : طار طیراً و طیراناً و طیرورةً؛ پرید. <BR><font color=\"Blue\">◄</font> شتافتن . (زوزنی ). <BR><font color=\"Blue\">◄</font> (اِ) مقابل وحش . پرنده . مرغ . طائر. پَروَر. ج، طیور، اطیار. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ج ِ طائر. (منتهی الارب ) (زمخشری ). مرغان . (غیاث اللغات ) (آنندراج ). این لفظ جمع و مفرد هر دو آمده است . و در شکرستان نوشته که : طیر اسم جمع است . احیاناً بر واحد نیز اطلاق کنند. (غیاث اللغات ). و فی الحدیث : و کان علی رؤسهم الطیر؛ ای ساکنون هیبة، و اصله ان الغراب یقع علی رأس البعیر فیلقط منه القراد فلایتحرک البعیر لئلاینفر عنه الغراب . (منتهی الارب ). و رجوع به طائر شود. قوله تعالی : و ارسل علیهم طیراً ابابیل ؛ بر ایشان فرستاد مرغان، و لفظ او هم جنس است و جمع را بشاید، واحدها طائر علی طریقة راکب و رکب و صاحب و صحب . (از الفیل تفسیر ابوالفتوح ). طیر ابادید؛ مرغان پراکنده . (مهذب الاسماء). اسم جنس حیوان پرنده است و جمع آن طیور و اطیار آمده و از آنچه صاحب حوصله و قانصه است و عقب پای آن خار دارد و مابین انگشتان پای آن پرده دار باشد مانند پای مرغابی و بط و در حین پرواز دف آن زیاده از صف آن باشد یعنی پرها را بسیار حرکت دهند و با هم زنند، حلال گوشت است و باقی همه حرام . (فهرست مخزن الادویه ) <span class=\"hlight\">:</span> <br />نماند جانور از وحش و طیر و ماهی و مور<br />که بر فلک نشداز بیمرادی افغانش .<br /> <font color=\"Red\">(گلستان ).</font><br /><BR><font color=\"Blue\">◄</font> چتر. شطر: و السلطان هنالک یعرف بالشطر <font color=\"DarkGreen\"><b>[ چتر ]</font></b> الذی یرفع فوق رأسه . (رحلة ابن بطوطة). <BR><font color=\"Blue\">◄</font> (اِخ ) دَبَران . (ستاره ) الطیر . و رجوع به شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span> شود.<br /></font></div>'),
(178570, 'طیر', '<span class=\"hlight\">طیر.</span> (اِخ ) موضعی است . (منتهی الارب ). جایگاهی است که عرب را در آن محل واقعه ای رخ داده و روز واقعه یکی از ایام تاریخی عرب بشمار است . (معجم البلدان ).<br /></font></div>'),
(178571, 'طیرا', '<span class=\"hlight\">طیرا.</span> (اِخ ) قریه ای است از قراء اصفهان . (معجم البلدان ). رجوع به طیری ̍ شود.<br /></font></div>'),
(178572, 'طیرالتمساح', '<span class=\"hlight\">طیرالتمساح .</span> <font color=\"DarkGreen\"><b>[ طَرُت ْ ت ِ ]</font></b> (ع اِ مرکب ) قطقاط. تورم . مرغیست که در دندانهای نهنگ چینه چیند. رجوع به «ابوظفر» و «تَورَم » شود. (اقرب الموارد).<br /></font></div>'),
(178573, 'طیرالجنة', '<span class=\"hlight\">طیرالجنة.</span> <font color=\"DarkGreen\"><b>[ طَ رُل ْ ج َن ْن َ ]</font></b> (ع اِ مرکب ) مرغ بهشتی . <BR><font color=\"Blue\">◄</font> فلک . <br /></font></div>'),
(178574, 'طیرالعراقیب', '<span class=\"hlight\">طیرالعراقیب .</span> <font color=\"DarkGreen\"><b>[ طَرُل ْ ع َ ]</font></b> (ع اِ مرکب ) شقراق . مقطعالظهر. دارکوب .<br /></font></div>'),
(178575, 'طیران', '<span class=\"hlight\">طیران .</span> (اِخ ) مافروخی در کتاب محاسن اصفهان در دو مورد این اسم را ایراد کرده، یکی در مورد ذکر قصور معروف اصفهان که گوید: و قصر صخربن سدوس بطیران . (چ طهران ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>). دیگر درمورد ذکر جوامع اصفهان که گوید: و الجامعان الکبیر العتیق البدیع الانیق بنی اصله القدیم عرب قریة طیران و هم التیم . (محاسن اصفهان مافروخی چ طهران ص <span class=\"hlight\" dir=\"rtl\">٨٤</span>).<br />و شاید «طیرا» که یاقوت حموی از قراء اصفهان شمرده با طیران هر دو یک موضع باشد و معلوم نیست ضبط کدام یک از این دو لفظ اصح است . و نیز رجوع به طهران شود.<br /></font></div>'),
(178576, 'طیران', '<span class=\"hlight\">طیران .</span> <font color=\"DarkGreen\"><b>[ طَ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ]</font></b> (ع مص ) پریدن . (منتهی الارب ). پرواز کردن . <BR><font color=\"Blue\">◄</font> شتافتن . (زوزنی ). پرش . پرواز. طیران (بسکون یاء نیز آمده، مگر اصل اول است ). (غیاث اللغات ) (آنندراج ). و با لفظ کردن مستعمل است . (آنندراج ) <span class=\"hlight\">:</span> <br />این کبوتر که نیارد زبر کعبه پرید<br />طیرانش نه ببالا که بپهنا بینند.<br /> <font color=\"Red\">خاقانی .</font><br />طیران مرغ دیدی تو ز پای بند غفلت <br />بدرآی تا ببینی طیران آدمیت .<br /> <font color=\"Red\">(گلستان ).</font><br />چهارم خوش آوازی که بحنجره ٔ داودی آب از جریان و مرغ از طیران بازدارد. (گلستان ).<br />از گلیم خویش نگذارد برون پا مرد عشق <br />دل کند هرچند طیران در فضای خود بود.<br /> <font color=\"Red\">ملا قاسم مشهدی .</font><br />با والد ماجدم بسی سال <br />کردی طیران به یک پر و بال .<br /> <font color=\"Red\">درویش واله هروی (در مدح میر حسن اوبهی ).</font><br /><BR><font color=\"Blue\">◄</font> دراز گردیدن چیزی . (آنندراج ).<br /></font></div>'),
(178577, 'طیرانس', '<span class=\"hlight\">طیرانس .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) (کتاب اعمال رسولان <span class=\"hlight\" dir=\"rtl\">١٩</span>:<span class=\"hlight\" dir=\"rtl\">٩</span>). مدرس فلسفه ٔ یونان بود در افسس، و پولس حواری در مدت دو سال در مدرسه ٔ او تعلیم میداد لکن مدرسه ٔ مرقوم مثل سایر مدارس نبود چنانکه بعضی گمان دارند بلکه محلی بود که روزها در اوقات معین در آنجا فراهم آمده مشغول درس میشدند. (اول تاریخ ایام <span class=\"hlight\" dir=\"rtl\">٤</span>:<span class=\"hlight\" dir=\"rtl\">١٤</span>) (قاموس کتاب مقدس ).<br /></font></div>'),
(178578, 'طیرانه', '<span class=\"hlight\">طیرانه .</span> <font color=\"DarkGreen\"><b>[ طَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ازع، اِ) نوعی از فطر و از آن بزرگتر. و تازه ٔ او سفید و زرد و خشک او سرخ است و در زیر درخت بلوط و زیتون میروید، و از سموم قتاله است حتی بوئیدن آن . (تحفه ٔ حکیم مؤمن ). نباتیست مانند فطر و بزرگتر از آن و در شب مانند چراغ میدرخشد و تر و تازه ٔ آن سفید و زرد و خشک آن سرخ رنگ . منقطع میگردد از طروف مانند اسفنج قطعهای سرخ . و رطوبت آن بد بود. منبت آن اکثر زیر درخت بلوط و زیتون است و در سالی که باران بسیار بارد بیشتر میروید. طبیعت آن گرم و خشک در چهارم . افعال و خواص آن : نفعی تا حال از آن ظاهر نشده و از سموم قتاله ٔ قوی است حتی بوئیدن و لمس نمودن آن و اجتناب از آن واجب . (مخزن الادویه ص <span class=\"hlight\" dir=\"rtl\">٣٨٠</span>). و آن را طیشر و طشور نیز خوانند. رجوع به تذکره ٔ انطاکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٩</span> شود.<br /></font></div>'),
(178579, 'طیرانی', '<span class=\"hlight\">طیرانی .</span> (ص نسبی ) کسی که اهل قریه ٔ طیرا از قراء اصفهان باشد. منسوب به طیرا. (سمعانی ).<br /></font></div>'),
(178580, 'طیرطاوس', '<span class=\"hlight\">طیرطاوس .</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (معرب، اِ) تب صفرائی .<br /></font></div>'),
(178581, 'طیرمطراق', '<span class=\"hlight\">طیرمطراق .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) رجوع به طرمطراق شود.<br /></font></div>'),
(178582, 'طیرمینوس', '<span class=\"hlight\">طیرمینوس .</span> (معرب، اِ) بطم است و آن را حبةالخضراء نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(178583, 'طیره', '<span class=\"hlight\">طیره .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) چندین قریه بدین نام در دمشق هست که هر یک به قبیله ای علیحده منسوب میباشند. (مراصد الاطلاع ص <span class=\"hlight\" dir=\"rtl\">٢٦٩</span>). دهیست به دمشق . (منتهی الارب ).<br /></font></div>'),
(178584, 'طیره شدن', '<span class=\"hlight\">طیره شدن .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ش ُ دَ ]</font></b> (مص مرکب ) خشم آوردن <span class=\"hlight\">:</span> حجام طیره شد و استره در تاریکی شب بر او انداخت . (کلیله و دمنه ).<br /></font></div>'),
(178585, 'طیره کردن', '<span class=\"hlight\">طیره کردن .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ک َ دَ ]</font></b> (مص مرکب ) آغالیدن، چنان باشد که کسی را بر کسی طیره کنند تا تند شود. برانگیختن . <BR><font color=\"Blue\">◄</font> خشمگین و غضبناک ساختن .<br /></font></div>'),
(178586, 'طیره گر', '<span class=\"hlight\">طیره گر.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ گ َ ]</font></b> (ص مرکب ) خشمگر. خشمگن . خشمگین <span class=\"hlight\">:</span> <br />گفتا چو منی را چه دهی دیده ٔ طیره <br />نفرین بچنین طیره گر خیره نگر بر.<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(178587, 'طیره گرفتن', '<span class=\"hlight\">طیره گرفتن .</span> <font color=\"DarkGreen\"><b>[طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ گ ِ رِ ت َ ]</font></b> (مص مرکب ) خشم گرفتن <span class=\"hlight\">:</span> و آنگه دو عرب بدان کنیسه حدث کردند و در محراب مالیدند و ابرهه طیره گرفت . (مجمل التواریخ ).<br /></font></div>'),
(178588, 'طیره گری', '<span class=\"hlight\">طیره گری .</span> <font color=\"DarkGreen\"><b>[ طَ<span class=\"hlight\" dir=\"rtl\">/</span> طِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ گ َ ]</font></b> (حامص مرکب ) خشمگنی <span class=\"hlight\">:</span> <br />چند من از بی توئی زارگری و گری <br />طیره گری را تو زآن گریه ٔ من خندخند.<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(178589, 'طیرهانی', '<span class=\"hlight\">طیرهانی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) عمربن متی . یکی از دانشمندان نساطرة در قرن شانزدهم م . بوده . او راست ترجمه ٔ کتاب «الجدل » تألیف ماری بن سلیمان دانشمند نسطوری قرن دوازدهم م . که بزبان کلدانی سریانی نوشته و عمربن متی الطیرهانی بمشارکت صلبیابن یوحنا الموصلی آن کتاب را نقل و ترجمه بزبان عربی کرده اند. کتاب مذکور با ترجمه ٔ لاتینی آن به اهتمام و عنایت اَب جسمندی برم از سال <span class=\"hlight\" dir=\"rtl\">١٨٩٦</span> تا سال <span class=\"hlight\" dir=\"rtl\">١٨٩٩</span> م . بطبع رسیده، موضوع کتاب تواریخ بطارکه ٔ نساطره تا سال <span class=\"hlight\" dir=\"rtl\">٣١٧</span> م . است . رجوع بکتاب الاَّداب السریانیه تألیف اَب روبنس دودوال شود . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٥٥</span>).<br /></font></div>'),
(178590, 'طیروب', '<span class=\"hlight\">طیروب .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام مردی است . (منتهی الارب ).<br /></font></div>'),
(178591, 'طیرگی', '<span class=\"hlight\">طیرگی .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (حامص ) خدوک . (فرهنگ اسدی خطی متعلق به آقای نخجوانی ) <span class=\"hlight\">:</span> <br />او را بدین هجا بدف اندر همی زنند<br />از طیرگی ورا چو دف تر همی کنم .<br /> <font color=\"Red\">سوزنی .</font><br />سخنهائی که او را بود در دل <br />فشاند از طیرگی چون دانه در گل .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(178592, 'طیری', '<span class=\"hlight\">طیری .</span> <font color=\"DarkGreen\"><b>[ را ]</font></b> (اِخ ) دهیست به اصفهان . طیرانی منسوب به وی . (منتهی الارب ). یاقوت در معجم البلدان حرف آخر این کلمه را بصورت الف ضبط کرده نه بصورت یاء چنانکه گذشت . رجوع به طیرا شود.<br /></font></div>'),
(178593, 'طیری', '<span class=\"hlight\">طیری .</span> <font color=\"DarkGreen\"><b>[ ری ی ]</font></b> (اِخ ) منسوب به طیرة که از ضیاع دمشق است . (سمعانی ).<br /></font></div>'),
(178594, 'طیری', '<span class=\"hlight\">طیری .</span> <font color=\"DarkGreen\"><b>[ طَ]</font></b> (اِخ ) منسوب به طیر که لقب ابوالفرج محمدبن محمدبن احمدبن الطیر القصری الطیری المقری البغدادی (<span class=\"hlight\" dir=\"rtl\">٤٦٦</span>-<span class=\"hlight\" dir=\"rtl\">٥٤٠</span> هَ . ق .) بوده که پس از وی اخلاف او خود را به وی منسوب داشته و خویشتن را طیری خواندند. (سمعانی ).<br /></font></div>'),
(178595, 'طیریز ناهید', '<span class=\"hlight\">طیریز ناهید.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) از دهات ساوه است . (نزهة القلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٦٢</span>).<br /></font></div>'),
(178596, 'طیزن آباد', '<span class=\"hlight\">طیزن آباد.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) طیزناباد. موضعیست بین کوفه و قادسیه بر مسیر جاده ٔ حاج، و بین آن و قادسیه یک میل مسافت است و تیول اشعث بن قیس بن عُمربن الخطاب بوده . مصفی ترین مواضع بوده و رزستان بسیار معمور و خانات عالی و محلهائی جهت فشردن انگور داشته است و یکی از اماکن عمومی لهو و بطالت بوده است و الاَّن <font color=\"DarkGreen\"><b>[ عصر یاقوت حموی ]</font></b> خراب است و نشانه ای از آنجا باقی نیست مگر قبه هائی چند که معروفند به قبه های ابونواس . و مردمان بیسامان ولگرد را در آن محل افسانه هائیست که ذکر آن باعث طول کلام گردد. (معجم البلدان ). و چنانکه از گفته ٔ ابن ابی اصیبعه که نقل خواهد شد برمی آید شراب آن معروف بوده است : و صب علیه خمراً من خمر طیزناباد. (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span>).<br /></font></div>'),
(178597, 'طیزنرود', '<span class=\"hlight\">طیزنرود.</span> <font color=\"DarkGreen\"><b>[ طَ زَ ن َ ]</font></b> (اِخ ) از دهات میان دورود توابع مازندران است . (سفرنامه ٔ استرآباد و مازندران رابینو ص <span class=\"hlight\" dir=\"rtl\">١٤٦</span>).<br /></font></div>'),
(178598, 'طیس', '<span class=\"hlight\">طیس .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) بسیار گردیدن . (منتهی الارب ). فراوان شدن . زیاد گردیدن . <BR><font color=\"Blue\">◄</font> (اِ) عدد بسیار. <BR><font color=\"Blue\">◄</font> هرچه بر زمین باشد از خس و خاشاک . <BR><font color=\"Blue\">◄</font> هر مخلوق کثیرالنسل مانند مور و مگس و هوام . <BR><font color=\"Blue\">◄</font> خاکریزها. <BR><font color=\"Blue\">◄</font> دریاها. طیسل در همه ٔ معانی . رجوع به طیسل شود. <BR><font color=\"Blue\">◄</font> بسیاری ِ هر چیزی از ریگ و آب و جز آن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178599, 'طیس', '<span class=\"hlight\">طیس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (بندر...) از بنادر قدیم و معتبر بوده است <font color=\"DarkGreen\"><b>[ در بلوچستان ]</font></b> و بمرور دهور خراب و معدوم الاثر شده بود. در سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٢٨٢</span> هَ . ق . از خوانین مکران به وکیل الملک مرحوم اطلاع دادند که چنین بندری در لب دریا واقع است، وکیل الملک این بنده را در فصل تابستان در عین شدت و حرارت هوا بطور چاپاری روانه نمودند. عاجلاً به مکران رفته، میر عبداﷲخان ضابط مکران را به اتفاق خود برده، همان محل را دیده، به اجازه ٔ مرحوم وکیل الملک محض تصرف دولت روزافزون قلعه ٔ مختصری بنا نموده و بیست خانوار هم از اهالی دشت در آن جا سکنا داده شد که از دست اندازی و تطاول اغیار محفوظباشد، و سکنه ٔ مزبور هنوز در آن جا متوقفند، و چون بندر مزبور در واقع بهتر و شایسته تر از چاه بهار است ومرتع هم دارد، برحسب امر و اجازه ٔ اولیاء دولت علّیه، وکیل الملک غیر از قلعه ٔ سابق، قلعه ای محکم و عمارات خوب و مرغوب از نو بنا گذاشته اند بمباشری میرزا محمدحسین کرمانی ساخته شده، و در هذه السنه (<span class=\"hlight\" dir=\"rtl\">١٢٩٤</span> هَ . ق .) که این بنده بسیاحت بلوچستان مأمور بود، مخصوصاً یک روز در آن جا توقف کرده سیر قلعه و تعمیرات آن جا را کرد، بسیار قلعه ٔ خوبیست، و یک سمت بدنه ٔ قلعه وصل بدریاست، قدری ناتمامی دارد که بنا و عمله در میان آن مشغول کارند، من بعد آبادی آن جا بهتر و جمعیتش افزونتر خواهد شد. آب آن جا نیز از چاه است لکن شیرین تر و گواراتر از چاه بهار است . دیوار بزرگی از سمت دریا کشیده اند برای بارانداز و غیره . حصن معتبری است، و اصل قلعه ٔ نو در روی تپه ٔ مرتفعی ساخته شده، از قبیل اشجار که در چاه بهار هست قلیلی هم در اینجا پیدامی شود. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٩</span>). جائی نزدیک چاه بهار. و در فرهنگ جغرافیائی ایران آمده است : دهی از دهستان کنارک شهرستان چاه بهار در <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی شمال چاه بهارکنار شوسه ٔ چاه بهار به ایرانشهر. کوهستانی گرمسیر مالاریائی با<span class=\"hlight\" dir=\"rtl\">٣٥٠</span> تن سکنه . آب آن از چاه و باران . محصول آنجا غلات و خرما و لبنیات . شغل اهالی زراعت و گله داری . راه آن شوسه است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(178600, 'طیس کیان', '<span class=\"hlight\">طیس کیان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) محلی در جنوب مُکران .<br /></font></div>'),
(178601, 'طیسانیة', '<span class=\"hlight\">طیسانیة.</span> <font color=\"DarkGreen\"><b>[ طَ نی ی َ ]</font></b> (اِخ ) شهری است به اشبیلیه . (منتهی الارب ). از شهرهای اندلس و از اعمال اشبیلیه محسوبست .(معجم البلدان ). و رجوع به ص <span class=\"hlight\" dir=\"rtl\">٦٥</span> روضات الجنات شود.<br /></font></div>'),
(178602, 'طیسبون', '<span class=\"hlight\">طیسبون .</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (اِخ ) صورتیست از طیسفون بنابر قاعده ٔ جواز تبدیل باء به فاء و بالعکس . رجوع به طیسفون و ص <span class=\"hlight\" dir=\"rtl\">٧١</span>، <span class=\"hlight\" dir=\"rtl\">٧٢</span>، <span class=\"hlight\" dir=\"rtl\">٧٥</span>، <span class=\"hlight\" dir=\"rtl\">١٠٨</span>، <span class=\"hlight\" dir=\"rtl\">١٠٩</span> فارسنامه ٔ ابن البلخی شود.<br /></font></div>'),
(178603, 'طیسر', '<span class=\"hlight\">طیسر.</span> <font color=\"DarkGreen\"><b>[طَ س َ ]</font></b> (ع ص، اِ) آب بسیار. طیسل . (منتهی الارب ).<br /></font></div>'),
(178604, 'طیسطوس', '<span class=\"hlight\">طیسطوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) یکی از پادشاهان روم که مدت دو سال جهانبانی کرد. (حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>).<br /></font></div>'),
(178605, 'طیسع', '<span class=\"hlight\">طیسع.</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (ع ص ) جای فراخ . <BR><font color=\"Blue\">◄</font> مرد آزمند. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178606, 'طیسفون', '<span class=\"hlight\">طیسفون .</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (اِخ ) پای تخت کسری و محلی بوده که ایوان معروف در آنجا ساخته شده، تا بغداد سه فرسنگ بُعد مسافت دارد. حمزه (اصفهانی ) گوید: اصل این کلمه طوسفون، و هنگام تعریب واو نخستین را به یاء تبدیل کرده اند. (معجم البلدان ). این محل مرکب از دو قسمت بوده، یک قسمت آن را طیسفون و قسمت دیگر را سلوکیا مینامیدند. طیسفون در سال <span class=\"hlight\" dir=\"rtl\">١٤</span> هجرت تسخیر شد و بتصرف مسلمانان درآمد. شهری از ایران زمین که اقامتگاه پادشاهان کشور ایران بوده، بعضی گفته اند نام مداین است واین اصح است و بعضی بجای فا، قاف گفته اند و برخی گفته اند این کلمه تیسپون به تاء قرشت و باء فارسی بوده و طیسفون معرب آن است . (فرهنگ رشیدی ). نام شهر قدیم در مغرب ایران و ساحل شرقی دجله که پای تخت ساسانیان بوده و عرب آنجا را مداین نام داد. تلفظ نام این شهر به پهلوی تیسپون بوده و خارجیها کتسیفون گفته اند. قصر ساسانی که محل ویرانه های طاق کسری از بقایای آنست در این شهر بوده است . (لغات شاهنامه ) <span class=\"hlight\">:</span> <br />نشسته شبی شاه در طیسفون <br />خردمند موبد به پیش اندرون .<br /> <font color=\"Red\">فردوسی .</font><br />زمستان بدی جای او طیسفون <br />ابا لشکر و موبد رهنمون .<br /> <font color=\"Red\">فردوسی .</font><br />همه یاد کرد این به نامه درون <br />فرستاده آمد سوی طیسفون .<br /> <font color=\"Red\">فردوسی .</font><br />وز آنجایگه شد سوی طیسفون <br />سر بخت بدخواه کرده نگون .<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به ص <span class=\"hlight\" dir=\"rtl\">٧١</span> الجماهرو ص <span class=\"hlight\" dir=\"rtl\">٤٠</span>، <span class=\"hlight\" dir=\"rtl\">٥٥</span>، <span class=\"hlight\" dir=\"rtl\">٦٧</span>، <span class=\"hlight\" dir=\"rtl\">٦٨</span>، <span class=\"hlight\" dir=\"rtl\">٤٦٤</span> مجمل التواریخ و القصص و ص <span class=\"hlight\" dir=\"rtl\">٤٤</span> نزهة القلوب ج <span class=\"hlight\" dir=\"rtl\">٣</span> چ اروپا و فهرست ترجمه ٔ ایران در زمان ساسانیان و ص <span class=\"hlight\" dir=\"rtl\">٤١٣</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> یشتها شود.<br /></font></div>'),
(178607, 'طیسفون', '<span class=\"hlight\">طیسفون .</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (اِخ ) نام دیهیست در مرو. (معجم البلدان ).<br /></font></div>'),
(178608, 'طیسفونی', '<span class=\"hlight\">طیسفونی .</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (ص نسبی ) منسوب به طیسفون از توابع مرو. (سمعانی ).<br /></font></div>'),
(178609, 'طیسقون', '<span class=\"hlight\">طیسقون .</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (اِخ ) صورتیست از طیسفون . نام شهری است در ایران زمین و آن پای تخت پادشاهان ایران بوده . (برهان ) (شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>).<br /></font></div>'),
(178610, 'طیسل', '<span class=\"hlight\">طیسل .</span> <font color=\"DarkGreen\"><b>[ طَ س َ ]</font></b> (ع اِ) سراب . <BR><font color=\"Blue\">◄</font> باد، یا باد سخت . <BR><font color=\"Blue\">◄</font> غبار. (منتهی الارب ) (آنندراج ). گرده . گرد بسیار. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> جماعت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) شب تاریک . <BR><font color=\"Blue\">◄</font> بسیار از هر چیزی . (منتهی الارب ) (آنندراج ): ماء طیسل ؛ آب بسیار. نعم طیسل ؛ ای کثیر. <BR><font color=\"Blue\">◄</font> عدد بسیار. <BR><font color=\"Blue\">◄</font> (اِ) هرچه بر زمین باشد از خس و خاشاک . <BR><font color=\"Blue\">◄</font> هر مخلوق کثیرالنسل مانند مور و مگس و هوام . <BR><font color=\"Blue\">◄</font> خاکریزها. <BR><font color=\"Blue\">◄</font> دریا. <BR><font color=\"Blue\">◄</font> تشت . (منتهی الارب ). سیطل . طیس . رجوع به طیس شود.<br /></font></div>'),
(178611, 'طیسلة', '<span class=\"hlight\">طیسلة.</span> <font color=\"DarkGreen\"><b>[ طَ س َ ل َ ]</font></b> (ع مص ) سفر نزدیک کردن و زیاد گردیدن شتران مسافر. (منتهی الارب ). سافر قریباً فکثر ماله . (قطر المحیط).<br /></font></div>'),
(178612, 'طیسمانیة', '<span class=\"hlight\">طیسمانیة.</span> <font color=\"DarkGreen\"><b>[ طَ س َ نی ی َ ]</font></b> (اِخ ) شهری است به اندلس . (منتهی الارب ).<br /></font></div>'),
(178613, 'طیسه', '<span class=\"hlight\">طیسه .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ) بستر و بالین را گویند.(برهان ) (آنندراج ). و رجوع به ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span> شعوری شود.<br /></font></div>'),
(178614, 'طیش', '<span class=\"hlight\">طیش .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِمص ) سبکی . (منتهی الارب ) (آنندراج ). سبک سری .سبک مغزی . سبکساری . خفت عقل . سبک طبعی . (زمخشری ) <span class=\"hlight\">:</span> و چون امیر محمود بشرب و عیش و اتلاف و طیش چنانکه شیوه ٔ میراثیان باشد. (جهانگشای جوینی ). <BR><font color=\"Blue\">◄</font> تندمزاجی . خشم و غضب . <BR><font color=\"Blue\">◄</font> اضطراب . <BR><font color=\"Blue\">◄</font> شتابزدگی . <BR><font color=\"Blue\">◄</font> مجازاً بمعنی غصه و بیدماغی . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> و گردش زمان عیش ربیع او را به طیش خریف مبدل نکند. (گلستان ). <BR><font color=\"Blue\">◄</font> (مص ) سبک گردیدن . (منتهی الارب )(غیاث اللغات ). سبکسار گردیدن . (تاج المصادر) (زوزنی ). <BR><font color=\"Blue\">◄</font> رفتن عقل . <BR><font color=\"Blue\">◄</font> خطا کردن تیر از نشانه . (منتهی الارب ) (غیاث اللغات ). بگشتن تیراز نشانه . (زوزنی ) (تاج المصادر بیهقی ). کله کردن تیر، یعنی جواز تیر از هدف . <BR><font color=\"Blue\">◄</font> غضب کردن .<br /></font></div>'),
(178615, 'طیشان', '<span class=\"hlight\">طیشان .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِمص ) الخفة و الحرکة. (قطر المحیط). سبکی . اضطراب . <BR><font color=\"Blue\">◄</font> (مص ) غضب کردن . طیش .<br /></font></div>'),
(178616, 'طیشی', '<span class=\"hlight\">طیشی .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نسبتی است که به فرزندان یزدادبن موسی بن حمیدبن السبال بن الطیشة الطیشی که از محدثین بغداد بوده، داده شده است . (سمعانی ).<br /></font></div>'),
(178617, 'طیط', '<span class=\"hlight\">طیط.</span> (ع ص ) طوط. مرد درازبالا. <BR><font color=\"Blue\">◄</font> احمق . نادان . <BR><font color=\"Blue\">◄</font> گشن تیزشهوت . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) بعربی باشق است و خفاش را نیز نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(178618, 'طیطا', '<span class=\"hlight\">طیطا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی نوره است که بفارسی آهک گویند. (فهرست مخزن الادویه ). طیطالوس .<br /></font></div>'),
(178619, 'طیطاق', '<span class=\"hlight\">طیطاق .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی از دهستان سارال بخش دیواندره ٔ شهرستان سنندج در <span class=\"hlight\" dir=\"rtl\">٢٥</span> هزارگزی جنوب باختری دیواندره و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی کانی کبود. کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٩٥</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات و توتون . شغل اهالی زراعت و گله داری . راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(178620, 'طیطالوس', '<span class=\"hlight\">طیطالوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی نوره است که بفارسی آهک گویند. (فهرست مخزن الادویه ). طیطا.<br /></font></div>'),
(178621, 'طیطان', '<span class=\"hlight\">طیطان .</span> (ع اِ) گندنای بری است . (منتهی الارب ) (آنندراج ). نباتیست . (مهذب الاسماء). طیطانة، یکی . (منتهی الارب ) (آنندراج ). کراث بری است . (فهرست مخزن الادویه ). تره ٔ صحرائی . به لغت سریانی گندنای صحرائی را گویند. (برهان ) (اختیارات ). کراث البر.<br /></font></div>'),
(178622, 'طیطان سر', '<span class=\"hlight\">طیطان سر.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) دهی از دهستان میربیک بخش دلفان شهرستان خرم آباد در <span class=\"hlight\" dir=\"rtl\">٣٤</span> هزارگزی باختر نورآباد و <span class=\"hlight\" dir=\"rtl\">٢٥</span> هزارگزی باختر شوسه ٔ خرم آباد به کرمانشاه . جلگه و جنگلی، سردسیر و مالاریائی با<span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات و تریاک و لبنیات و پشم . شغل اهالی زراعت و گله داری . صنایع دستی زنان سیاه چادر و قالی بافی . راه آن مالرو است . ساکنین از طایفه ٔ کوسه و مال مومه هستند وزمستان قشلاق میروند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(178623, 'طیطانة', '<span class=\"hlight\">طیطانة.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (ع اِ)یکی طیطان که کراث بری است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178624, 'طیطر', '<span class=\"hlight\">طیطر.</span> <font color=\"DarkGreen\"><b>[ طی طَ ]</font></b> (ع اِ) یرفاقه .لوره . غار اسکندرانی . رجوع به غار اسکندرانی شود.<br /></font></div>'),
(178625, 'طیطس', '<span class=\"hlight\">طیطس .</span> <font color=\"DarkGreen\"><b>[ طی طَ ]</font></b> (ع اِ) شادنج بری است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178626, 'طیطو', '<span class=\"hlight\">طیطو.</span> (اِ) نوعی از مرغابی باشد، و طیتو نیز گفته اند. (برهان ) (آنندراج ). مرغ آبی . (حاشیه ٔ فرهنگ اسدی نخجوانی ) <span class=\"hlight\">:</span> <br />پادشا سیمرغ دریا را ببرد<br />خانه و بچه بدان طیطو سپرد.<br /> <font color=\"Red\">رودکی .</font><br />و در حاشیه ٔ برهان چ معین آمده است : طیطو، طیطوی = تیتو، از سانسکریت «تیتیبها» (مرغی است ). این کلمه توسط برزویه مترجم کلیله و دمنه به پهلوی، وارد زبان مزبور شد و در فارسی بصورت تیتو درآمد. <BR><font color=\"Blue\">◄</font> نوعی طیطوی . قطای بلندپا. سنگخوارک .<br /></font></div>'),
(178627, 'طیطوانه', '<span class=\"hlight\">طیطوانه .</span> <font color=\"DarkGreen\"><b>[ طی طَ ن َ ]</font></b> (اِخ ) شهری است از اعمال ارمینیه (ارمنستان ). (معجم البلدان ).<br /></font></div>'),
(178628, 'طیطوس', '<span class=\"hlight\">طیطوس .</span> (اِخ ) از قیاصره ٔ روم بعداز مسیح پسر امپراطور وسپاسپن است . مدت سلطنتش دو سال بود. (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>). وی چهل سال پس از ارتفاع مسیح با یهودیها جنگید و زیاد کشت و اسیر کرد. (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٦٦</span>). و رجوع به ص <span class=\"hlight\" dir=\"rtl\">٥٩</span> و <span class=\"hlight\" dir=\"rtl\">١٤٠</span> مجمل التواریخ و القصص و ص <span class=\"hlight\" dir=\"rtl\">٢٥٦٩</span> و <span class=\"hlight\" dir=\"rtl\">٢٤٧٠</span> ایران باستان شود.<br /></font></div>'),
(178629, 'طیطوی', '<span class=\"hlight\">طیطوی .</span> (اِ) طوطی .<br /></font></div>'),
(178630, 'طیطوی', '<span class=\"hlight\">طیطوی .</span> <font color=\"DarkGreen\"><b>[ طی طَ وا ]</font></b> (ع اِ) نوعی از مرغ سنگخوار یاغیر آن است . (منتهی الارب ). قسمی از قطا بلندپای یا مرغی دیگر. (قاموس ). ضرب من القطا او غیره و قیل هو طائر لایفارق الاَّجام و کثرة المیاه . (قطر المحیط). ارسطاطالیس گفته است در کتاب «النعوت » که آن مرغیست که هیچگاه در غیر بیشه و آب فراوان زیست نکند، چه این پرنده گیاه و گوشت نخورد و قوت آن از کرمهای متولد از کثافات کنار بیشه ها میباشد. باز شکاری از آنجا که درنتیجه ٔ تولید حرارت در کبد غالباً بیمار گردد در جستجوی طیطوی افتد، چون آن را آشکار کند کبد وی را بخورد و بهبود یابد. هنگام آواز کردن آرام باشد و هیچگاه از موضع خود دور نشود مگر هنگامی که باز در جستجوی وی بود که در آن وقت از جای خود فرار کند و محل خویش را تغییر دهد. چون شب درآید فریاد و فرار کند امادر روز هنگام فرار آواز نکند و خود را میان گیاهها پنهان سازد. (حیوة الحیوان ) <span class=\"hlight\">:</span> زعموا ان ّ طائراً من طیور البحر یقال له الطیطوی کان وطنه ساحل البحر. (کلیله و دمنه ٔ ابن المقفع). و او راست <font color=\"DarkGreen\"><b>[ مریخ را ]</font></b> شب پرو طیطوی و هر مرغی که سرخ باشد. (التفهیم ). آورده اند که نوعیست از مرغان آب، طیطوی گویند. (ترجمه ٔ کلیله ٔ بهرامشاهی ). رجوع به طیطو و تیتو شود.<br /></font></div>'),
(178631, 'طیع', '<span class=\"hlight\">طیع.</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (ع ص ) طائع. فرمانبردار. <BR><font color=\"Blue\">◄</font> خواهان . (منتهی الارب ).<br /></font></div>'),
(178632, 'طیع', '<span class=\"hlight\">طیع.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) فرمانبرداری کردن . طوع . (منتهی الارب ) (آنندراج ). رجوع به طوع شود.<br /></font></div>'),
(178633, 'طیف', '<span class=\"hlight\">طیف .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (ع اِ) خیال . <BR><font color=\"Blue\">◄</font> وسوسه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178634, 'طیف', '<span class=\"hlight\">طیف .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) خشم . غضب . <BR><font color=\"Blue\">◄</font> جنون . دیوانگی . <BR><font color=\"Blue\">◄</font> خیال . خیالة. (منتهی الارب ) (آنندراج ). پیکر خیالی محسوس غیرقابل لمس . شبح . صورت که به خواب بینند. (السامی )(مهذب الاسماء). <BR><font color=\"Blue\">◄</font> وسوسه . و منه : اذا مسهم طیف من الشیطان . (منتهی الارب ) (آنندراج ). بداندیشی . <BR><font color=\"Blue\">◄</font> شکل حاصل از تأثیر مغناطیس بر براده های آهن و الوان حاصل از تجزیه ٔ نور. رجوع به طیف شمس و طیف نور و طیف مغناطیسی شود. <BR><font color=\"Blue\">◄</font> (مص ) آمدن خیال در خواب . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نموده شدن خیال در خواب . (زوزنی ). <BR><font color=\"Blue\">◄</font> گرد چیزی گردیدن . لغة فی الطوف، مطاف مثله فیما. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178635, 'طیف شمس', '<span class=\"hlight\">طیف شمس .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ف ِ ش َ ]</font></b> (ترکیب اضافی، اِ مرکب ) نوار رنگینی است که از تجزیه ٔ نور خورشید بوسیله ٔ منشور (موشور) بلوری به دست می آید. علت این امر آن است که زاویه ٔ انکسار الوان مختلف متفاوت است، لذا نور خورشید به الوان مشکله ٔ آن که عبارتست از قرمز، نارنجی، زرد، سبز، آبی، نیلی و بنفش تجزیه میشود. تمیز سرحدات رنگها مشکل است .<br /></font></div>'),
(178636, 'طیف مغناطیسی', '<span class=\"hlight\">طیف مغناطیسی .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ف ِ م ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) شکل مخصوصی است که براده های آهن که در روی صفحه ریخته شده است بر اثر قرار دادن آهن ربائی در زیر صفحه بخود میگیرند، از جریان الکتریک نیز آن شکل پیدا میشود.<br /></font></div>'),
(178637, 'طیف نما', '<span class=\"hlight\">طیف نما.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ ]</font></b> (نف مرکب، اِ مرکب ) اسپکترسکپ . دستگاهی که در تجزیه نور و تحقیق طیف به کار رود.<br /></font></div>'),
(178638, 'طیف نور', '<span class=\"hlight\">طیف نور.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ف ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) رنگهای حاصل از تجزیه ٔ نور بوسیله ٔ بلور یا منشور.<br /></font></div>'),
(178639, 'طیفا', '<span class=\"hlight\">طیفا.</span> (معرب، اِ) سلت . طراغوس .<br /></font></div>'),
(178640, 'طیفسون', '<span class=\"hlight\">طیفسون .</span> <font color=\"DarkGreen\"><b>[ طَ ف َ ]</font></b> (اِخ ) صورتیست از طیسفون . رجوع به «طیسفون » و نیز رجوع به ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span> شعوری شود.<br /></font></div>'),
(178641, 'طیفور', '<span class=\"hlight\">طیفور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (...قلعه ) قلعه ای است از قلاع ارجان از کوره ٔ قبادخره ٔ فارس . (نزهة القلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٣٠</span>).<br /></font></div>'),
(178642, 'طیفور', '<span class=\"hlight\">طیفور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام ابوطاهر والد ابوالفضل احمدبن ابی طاهر مرورودی که از مصنفین نامی و مشهور عربست . رجوع به احمدبن ابی طاهر طیفور در معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٥٥</span> و ص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span> الفهرست ابن الندیم و ص <span class=\"hlight\" dir=\"rtl\">٨٠</span>، <span class=\"hlight\" dir=\"rtl\">١٥٠</span>، <span class=\"hlight\" dir=\"rtl\">١٥٢</span> (حاشیه )، <span class=\"hlight\" dir=\"rtl\">١٦٦</span>، <span class=\"hlight\" dir=\"rtl\">١٧٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٣٦</span> کتاب ضحی الاسلام ج <span class=\"hlight\" dir=\"rtl\">٢</span> شود.<br /></font></div>'),
(178643, 'طیفور', '<span class=\"hlight\">طیفور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) (ملک ...) انجدانی . برادر مهتر ملا داعی انجدانی است و از تلامذه ٔ شیخ عبدالعال و مولانا فتح اﷲ معز است و اول ِ حال کسری تخلص میکرده بعد از آن مدتی در قزوین مانده و ملک تخلص میکرده . بهر حال این یک بیت ممتاز از او ملاحظه شد. گویند بعد از آنکه میرزا ملک قمی بهندوستان رفته بود جمعی این شعر را به او اسناد میدادند، ملک طیفور قاصدی به این خصوص بهند فرستاده از میرزا ملک قمی حجتی صادر کرده مدعیان را ساکت ساخته و شعر را مالک شد. این است :<br />خون چکان است ملک تیغ ستم میترسم <br />که پی آخر به در خانه ٔ قاتل برود.<br /> <font color=\"Red\">(آتشکده ٔ آذر).</font><br />و نیز رجوع به ص <span class=\"hlight\" dir=\"rtl\">٨٨</span>، <span class=\"hlight\" dir=\"rtl\">١٦٩</span>، <span class=\"hlight\" dir=\"rtl\">١٧٠</span>، <span class=\"hlight\" dir=\"rtl\">١٧٧</span> ترجمه ٔ ج <span class=\"hlight\" dir=\"rtl\">٤</span> تاریخ ادبیات ایران از رشید یاسمی شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178644, 'طیفور', '<span class=\"hlight\">طیفور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام بایزید بسطامی شیخ صوفیه است . (منتهی الارب ) (آنندراج ). و هو طیفوربن عیسی بن سروشان البسطامی الملقب بسلطان العارفین . رجوع به «ابویزید طیفوربن عیسی » و ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٢</span> حبیب السیر و ص <span class=\"hlight\" dir=\"rtl\">٦١</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span> نامه ٔ دانشوران و ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span> روضات الجنات و بایزید بسطامی شود.<br /></font></div>'),
(178645, 'طیفور', '<span class=\"hlight\">طیفور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) ابن عیسی بن آدم بن عیسی بن علی الزاهد البسطامی الاصغر المکنی بابی یزید (و ظاهراً بایزید اصغر برادرزاده ٔ بایزید اکبر است ). رجوع به ص <span class=\"hlight\" dir=\"rtl\">٩٣</span> از ج <span class=\"hlight\" dir=\"rtl\">٤</span> صفة الصفوة لابن الجوزی و نیز رجوع به ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span> معجم البلدان و ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span> روضات الجنات شود.<br /></font></div>'),
(178646, 'طیفور', '<span class=\"hlight\">طیفور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام موضعی است . (مراصد الاطلاع ).<br /></font></div>'),
(178647, 'طیفور', '<span class=\"hlight\">طیفور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) نام جانورکی است . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> مطلق پرنده را گویند اعم از مرغ و ملخ و امثال آن . (برهان ). <BR><font color=\"Blue\">◄</font> مرغی است . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> مرغیست خرد. طائرٌ صغیرٌ. (قطر المحیط) <span class=\"hlight\">:</span> <br />همچو پروانه ٔ چراغ شود<br />در شبستان وقت او طیفور.<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />همیشه تا سپه صبح نقش خسرو روز<br />دهند عرض بدین نخل سبز چون طیفور.<br /> <font color=\"Red\">کاتبی .</font><br />بوستانها ز برگها اکنون <br />بر طبقهای زرّ طیفور است .<br /> <font color=\"Red\">؟</font><br /><BR><font color=\"Blue\">◄</font> یکی از ثوانی نجوم است و بعقیده ٔ قدما آن بخاری است که از زمین متصاعد شده در کره ٔ نار محترق گشته و تا کره ٔ زمین چون دیواری اتصال داشته باشد، و شاید مراد قدما اورربرآل باشد. <BR><font color=\"Blue\">◄</font> ظرفی که اندرون آن گود باشد. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span>) <span class=\"hlight\">:</span> ثم جاء بعد صلاة المغرب و معه طیفوران کبیران احدهما بالطعام و الاَّخر بالفاکهة و خریطة فیها دراهم . (ابن بطوطة). و امر باحضار صینیّة من ذهب و هی مثل الطیفور الصغیر و امر ان یأتی فیها الف دینار من الذهب و اخذها السلطان بیده فصبها علیه و قال : هی لک مع الصینیة. (ابن بطوطة). ثم اتوا بطیفور ذهب فیه الفاکهة الیابسة و بطیفور مثله فیه الجلاب و طیفور ثالث فیه التنبول، و من عادتهم ان الذی یخرج له ذلک یأخذ الطیفور بیده و یجعله علی کاهله ثم یخدم بیده الاخری الی الارض، فاخذ الوزیر الطیفور بیده قصداً ان یعلمنی کیف افعل أیناساً منه و تواضعاً و مبرةً جزاه اﷲ خیراً ففعلت کفعله . (ابن بطوطة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥</span>).<br /></font></div>'),
(178648, 'طیفور', '<span class=\"hlight\">طیفور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) رجوع به «ابومنصور طیفور طیب » شود.<br /></font></div>'),
(178649, 'طیفور', '<span class=\"hlight\">طیفور.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) پسر سلطان اولجایتو که در خردی نماند. (ذیل جامع التواریخ رشیدی ص <span class=\"hlight\" dir=\"rtl\">٧٠</span>، <span class=\"hlight\" dir=\"rtl\">٧١</span>).<br /></font></div>'),
(178650, 'طیفورآباد', '<span class=\"hlight\">طیفورآباد.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دیهی است از دهات اصفهان . <BR><font color=\"Blue\">◄</font> محله ای است از محلات همدان . (معجم البلدان ).<br /></font></div>'),
(178651, 'طیفوری', '<span class=\"hlight\">طیفوری .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) اسرائیل بن زکریا الطیفوری . وی طبیب فتح بن خاقان و در صناعت پزشکی پیشوا و جلیل القدر و نزد خلفاء و ملوک سخت ارجمند بودو در خدمت فتح بن خاقان بکارهای پزشکی اختصاص داشت واز جانب وی مقرری و نعمتهای بسیار به اسرائیل عاید میشد. متوکل عباسی برای وی ارزش بسیاری قائل بود و نسبت به وی اعتماد فراوان داشت و وی را نزد متوکل منزلتی بلند بود. از آن جمله اسحاق بن علی الرهاوی در کتاب ادب الطبیب حکایت کند که : نوبتی متوکل بدون اجازه ٔ اسرائیل حجامت کرد، چون اسرائیل آگاه شد خشم گرفت و متوکل سه هزار دینار با یک قطعه زمینی که در سال محصولش پنجاه هزار درهم بود به وی بخشید و خشمش را بازخرید. عیسی بن ماسة حکایت کند و گوید: دیدم متوکل را روزی که بعیادت اسرائیل طیفوری که به غشی مبتلا بود رفته دست خویش را بجای مخده زیر سر اسرائیل نهاده بود و به وزیر گفت یا عبداﷲ زندگانی من بزندگانی اسرائیل وابسته است، اگر وی از دنیا برود حیات من نیز به ممات مبدل خواهد شد و در مدت بیماری وی متوکل دربان خویش سعیدبن صالح و کاتب خود موسی بن عبدالملک را بعیادت وی می فرستاد. از تاریخی نقل کرده ام که فتح بن خاقان را عنایتی خاص درباره ٔ اسرائیل بود، وی را نزد متوکل برد و ملازم دربار خلیفه گردانید و روزبروز خلیفه نسبت به اسرائیل انس و الفت یافت و وی را با بختیشوع همرتبه ساخت و مردی عظیم القدر گردید تا بحدی که هرگاه سوار شدی مانند موکب امراء و سرکردگان عظیم الشأن پیشاپیش وی چند تن چماقدار حرکت میکردند و متوکل در سرمن رأی قطعه زمینی به تیول به اسرائیل بخشید و فرمان داد که صقلاب و ابن الخبیری با وی سوار شوند و بمعیت وی تمامی شهر سرمن رأی را بگردند تا مکانی را که اسرائیل برای اقامتگاه خویش بپسندد برگزیند، آنان نیزخلیفه را فرمان بردند و چندان بگردیدند تا به اراضی حیز رسیدند و اسرائیل راآن محل خوش آمد و پنجاه هزار گز از اراضی آنجا برگزید و بر آن اراضی نشانه ای نهادند و از جانب متوکل نیزمبلغ سیصدهزار درهم برای هزینه ٔ ساختن عمارت در آنجا به اسرائیل تسلیم کردند. (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span>).<br /></font></div>'),
(178652, 'طیفوری', '<span class=\"hlight\">طیفوری .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) جدّ ابوجعفر محمدبن یزیدبن طیفور البغدادی المعروف بالطیفوری است و وی منسوب به طیفور از محدثان بغداد باشد. (سمعانی ).<br /></font></div>'),
(178653, 'طیفوری', '<span class=\"hlight\">طیفوری .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) نام دیگر از رودخانه ٔ گرگان است که مقدسی نیز ذکری از آن میکند. (سفرنامه ٔ مازندران رابینو ص <span class=\"hlight\" dir=\"rtl\">٩١</span>).<br /></font></div>'),
(178654, 'طیفوری', '<span class=\"hlight\">طیفوری .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) مردی طبیب بود. حنین بن اسحاق چندین کتاب از وی در فن پزشکی یاد و نقل کرده . از پیشوایان پزشکان و فاضلی در فن خویش حاذق بود و عبداﷲ نام داشت . وی جدّ اسرائیل بن زکریا الطیفوری است که طبیب فتح بن خاقان بود و چون عبداﷲ پزشک مخصوص طیفور غلام خیزران مادر هادی و رشید بود ملقب به طیفوری شد. وی بدربار هادی خلیفه نیز منزلتی بسزا داشت و از همسران خویش پیش بود. یوسف بن ابراهیم مولی ابراهیم بن المهدی حکایت کرده گوید: از طیفوری پرسیدم آیا اینکه در افواه عوام شایع است که هادی خلیفه چون دهان گشاید تا کسی که موکل به اوست نگوید دهان بسته دار دهان خویش نبندد مقرون بصحت است ؟ طیفوری در جواب سخت منکر گردید و سوگند یاد کرد که احدی را در خوشروئی و گفتار و خاموشی و تبسم با هادی مانند وهمطراز ندیدم . فحدثت بهذا الحدیث مولی ابراهیم بن المهدی فقال صدق الطیفوری . (تاریخ الحکماء قفطی ص <span class=\"hlight\" dir=\"rtl\">٢١٨</span>).خردی نیکو و گفتاری سخت پاکیزه داشت ولی از لکنت اهل سواد آن هم بشدت بی بهره نبود زیرا مولد وی در دیهی از دیهات کسکر (شهری از خوزستان ) بوده و در دربار هادی خلیفه بر همگی اقران خویش برتر و دارای مقامی بالاتر بود. یوسف بن ابراهیم گوید: خبر داد مرا طیفوری وگفت : که وی طبیب طیفورنامی بوده که به قولی برادر خیزران و به قولی دیگر که اکثریت با آن است غلام خیزران بوده است . هنگامی که منصور خلیفه مهدی را برای محاربه ٔ سنقار به ری روانه داشت مهدی خیزران را با خود همراه برد و در آن هنگام خیزران موسی را در شکم داشت، بود و طیفور نیز با خیزران از خانه ٔ خویش بیرون آمد و مرا هم با خود همراه ساخت . خیزران از اینکه بار وی از جنس ذکور است یا اناث بیخبر بود، عیسی صیدلانی معروف به ابوقریش در لشکر مهدی بود، همین که خیزران عادت زنانه را در مدت مقرر از خود مرتفع دید قاروره ٔخویش را به پیرزنی بسپرد و بدو دستور داد که قاروره را بهمگی پزشکان اردو نشان دهد. در آن هنگام مهدی ولشکریان بهمدان رحل اقامت افکنده بودند، پیرزن دستور خیزران را اجرا کرد و در اثناء اجرای دستور بخیمه ٔعیسی صیدلانی رسید، دید گروهی از غلامان لشکری برای ارائه ٔ قاروره بر در آن خیمه منتظرند، پیرزن نخواست بدون ارائه ٔ قاروره از خیمه ٔ عیسی بگذرد، قاروره به وی نیز نشان داد، چون عیسی بدان قاروره نظر افکند، گفت این قاروره از زنیست که بپسری حامل است . پیرزن بازگشت و آنچه از عیسی شنیده بود برای خیزران نقل کرد، خیزران خدای را سجده کرد و شکر گفت و چندین غلام آزادساخت و نزد مهدی شد و مژده ٔ این خبر بدو داد، مهدی نیز بیش از خیزران از شنیدن این خبر مسرور گردید و فرمان داد تا عیسی را حاضر ساختند و از وی صدق یا کذب قول پیرزن را استعلام کرد، عیسی گفتار پیرزن را تصدیق کرد، آنگاه مهدی و خیزران هر دو عیسی را صلتی گرانبها و مالی فراوان بخشیدند و در پایان امر او را به برچیدن بساط صیدلانی و التزام خدمت دربار توصیه و سفارش کردند. طیفوری گوید: در این موقع طیفور خواست مرانیز از جانب مهدی و خیزران سودی رساند، برای خیزران پیغام فرستاد که طبیب من نیز در صناعت پزشکی ماهر است، قاروره ٔ خویش را نزد وی بفرست تا وی نیز معاینه کند و نظر خویش را اعلام دارد. دیگر روز خیزران گفته ٔطیفور را کار بست و قاروره ٔ خویش را نزد طیفوری فرستاد و هرچند طیفور تأکید کرد که تو نیز آنچه را عیسی صیدلانی درباره ٔ قاروره ٔ خیزران گفت بگوی من نپذیرفتم و بطیفور فهماندم که قاروره ٔ خیزران را بمن نشان داده اند اما تمیز ذکور یا اناث بودن حمل از من ساخته نیست . طیفور کرّت دیگر کوشش کرد که مرا راضی سازد تا با عیسی صیدلانی موافقت نظر حاصل کنم و نتیجه ٔ معاینه ٔ قاروره را چنانچه عیسی گفته من نیز بهمان وتیره پاسخ فرستم، سر باززدم و گفتم برای آنکه دامان خویش را از دروغ و مخرقه پاک نگاه دارم چنین گفتاری از خود اظهار نکنم . طیفور نظریه ٔ مرا به خیزران رسانید، خیزران هزار درهم بمن بخشید و فرمان داد تا ملازم وی باشم . چون به ری رسید هادی در آنجا از بطن خیزران قدم بعرصه ٔ وجود نهاد. چون بر اثر آزمایشهای دقیقی بر مهدی ثابت گردیده بود که عیسی صیدلانی عنین است باعث خوشحالی وی شد و او را بر سایر همکاران وی از خوابگاه و غلامان مقدم داشت و همین امر موجب رونق کار من گردیده از بستگان خاص موسی خلیفه شدم و مرا پزشک مخصوص وی خواندند، و موسی در آن هنگام کودکی شیرخوار بود که بتازگی وی را از شیر گرفته بودند، سپس هارون الرشیدنیز به ری متولد شد و گوئی مولد او بر هادی شوم آمدزیرا اقبال و نصیب بتمامی یا بیشتر آن به هارون روی آوردند و از هادی روی برتافتند و این امر موجب شد که جاه و منزلت مرا زیان رسید و کثرت دخل مرا نکسی عاید شد و روزگار بدین منوال بگذشت تا آنکه مهدی بالیدن گرفت و از قضیه آگاه شد و همان سبب گردید که بر جاه و مرتبت من افزود و نسبت بمن خوشبین شده بیش از آنچه از جانب خیزران بمن میرسید، میرساند، این بود که قضیه ٔ محاربه ٔ با سنقار پیش آمد و فتح نصیب مهدی شد و سنقار را بکشت ... سپس هادی بحد بلوغ رسید و خلافت بمهدی محول شد و کار از نو بمن پیوستگی یافت و منزلت و رتبتم رفیع گردید، چه در آن هنگام طبیب ولیعهد خلیفه بشمار میرفتم، در همان اوقات هادی امة العزیز را مالک شد و وی را از دو دیده ٔ خویش گرامی تر میداشت . امة العزیز مادر جعفر و عبداﷲ و اسماعیل و اسحاق و عیسی معروف بجرجانی و موسی اعمی و ام عیسی عیال مأمون و ام محمد و عبیداﷲ دختران هادی بوده است . از آن پس هادی فرزندان خویش را پسرخوانده ٔ من ساخت و به امة العزیز اعلام داشت که من به طیفوری تبرک میجویم و ازینرو آرزوهای من در سایه ٔ مهربانیهای امة العزیز بیشتر مقرون به نجاح گردید تا اوقاتی که تفقدات هادی بر من سایه افکن بود. آنگاه هادی درصدد برآمد که تدبیری کند تا برای پسرش جعفر جهت ولایت عهد خلافت از مردم بیعت گیرد. یک روز پیش از اخذ بیعت مرا بخواند، در آن روز مرا خلعتی بخشید، مرا بر چارپائی از چارپایان خاصه سوار کرد با همان زین و لگام مخصوص سواری خویش و یکصدهزار (دینار یا درهم ) در آن روز بمن عطا فرمود که تمامی را به خانه ٔ خویش حمل کردم، سپس مرا گفت که چون بخانه رسی بقیه ٔ ساعات امروز و همگی شب و بیشتر ازساعات فردا را هم ملازم خانه باش و بیرون میا تا من از کار اخذ بیعت جهت جعفر پسرت فارغ گردم، اینک بسرای خویش بازگرد در حالی که شریف ترین مردم بشمار میروی، چه توئی که در پرورش پسر خلیفه چندان کوشیدی تا وی را شایسته ٔ ولایت عهد و جلوس بر مسند خلافت ساختی و اینک هم فرزند او را بر اثر تربیت و پرورشی که درباره ٔ وی کرده ای بمقامی رسانده ای که نامزد ولایت عهد شده است . این خبر به امة العزیز رسید، وی نیز مانند هادی مرا به صلات و خلعتهای فاخر مفتخر کرد و آنها را بسرای من فرستاد و من همچنان آن روز را از سرای خویش که واقع در محله ٔ عیسی آباد بود تا طلوع آفتاب روز بعد بیرون نشدم، آنگاه هادی در دارالخلافه بنشست در حالی که تمام افراد بنی هاشم را احضار کرده و در محضر آنان برای جعفر پسرش از همگی بیعت گرفت و در همان محضر تمامی هم سوگند شدند که رشید را از خلافت خلع کرده و بیعت جعفر را نقض نکنند. پس از بنی هاشم آل زائده با جعفر بیعت و رشید را از خلافت خلع کردند، و نخستین کسی که از آل زائده بدین امر اقدام ورزید یزیدبن مزید بود، سپس شراحیل بن معن بن زائدة الشیبانی و خانواده ٔ او، آنگاه سعیدبن سلم بن قتیبةبن مسلم و بعد از وی آل مالک و اولین کس از ایشان عبداﷲ و یاران وی و سایر مشایخ و در پایان همه فرماندهان لشکری اقدام به اخذ بیعت با جعفر و خلع رشید کردند، و هنوز نیمه روز نشده بود که بیشتر فرماندهان از اخذ بیعت فارغ گردیده بودند. و در بین فرماندهان هرثمةبن اعین که به مشئوم ملقب بود و فرماندهی پانصد تن لشکری را داشت و در مدت فرماندهی وی بر اثر سستی اکثر یاران او از لشکریان مرده بودند و بجای نفرات متوفی اخذ نفر نکرده بود به وی نیز امر کردند که با جعفر بیعت و رشید را خلع کند، هرثمة روی بهادی کرده گفت : یا امیرالمؤمنین، با که بیعت کنم، دست راست من به بیعت با امیرالمؤمنین مشغول است و دست چپم به بیعت هارون الرشید، در این صورت باچه و با که بیعت توانم کرد. هادی گفت : رشید را خلع و با جعفر بیعت کن، هرثمة گفت من گروگان پند تو و پیشوایان از خانواده ٔ تو میباشم، بخدا سوگند که اگر برای گفتن حرف راست مرا بترسانی و به آتشم بسوزانی جز گفتار راست از من کلمتی نخواهی شنید، یا امیرالمؤمین بیعت جز سوگند چیز دیگری نیست، من برای هارون سوگند یاد کرده ام بهمان نحوی که میخواهی برای جعفر سوگندیاد کنم درین صورت اگر امروز هارون را خلع کنم باشدکه فردا هم جعفر را خلع سازم و هر کس هم که برای هارون سوگند یاد کرده در حکم من باشد و این خود خیانت و غدری است روشن . هادی از خشم برافروخت و فرمان داد تا هرثمة را گردن زنند. بمجرد آنکه این گفتار از دهان خلیفه بیرون آمد گروهی از غلامان و فرماندهان بشتابی تمام با گرزهای آهنین و عمودها از جای بجستند، هادی آنان را از اقدام بازداشت و کرتی دیگر بهرثمة تکلیف و امر به بیعت کرد، هرثمة گفت یا امیرالمؤمنین، سخن همانست که گفتم، هادی هرثمة را از دربار براند و گفت بیرون شو بنفرین خدای دچار شوی تا هزار سال نخواهم تو و یارانت بیعت کنی . سپس فرمان داد تا وی را ازدربار بمحله ٔ عیسی آباد اخراج و فرماندهی را از وی منتزع ساختند و گفت بهلید تا بهر جائی که خواهد رود، حق او را یار و همراه نباشد. آنگاه هادی قریب نیم ساعت خاموش گشت و امر و نهیی نراند ولی سپس خاموشی سر برداشت و به یندون خادم گفت درحال خود را بدان نابکار برسان، یندون پرسید وقتی بدو رسیدم چه کنم، گفت : وی را نزد من آر. یندون فرمان برد و در پی او شد و وی را مابین دروازه ٔ خراسان و دروازه ٔ بردان نزدیک موضع معروف به باب النقب دریافت و در حالتی که عازم خانه ٔ خویش که بر نهر مهدی اشراف داشت، بود و از همانجا وی را بازگردانید چون دیده ٔ هادی بر وی افتاد گفت : ای حائک ! تو با خانواده ٔ امیرالمؤمنین از قبیل عم جدو عم پدر و برادران و سایر خویشاوندان وی و با وجوه و اعیان عرب و موالی و سرداران بیعت میکنی و از بیعت با جعفر خودداری میکنی ؟ هرثمة گفت یا امیرالمؤمنین، با آنچه از بیعت با اشراف و وجوه و اعیان عرب یادکردی تو را به بیعت با حائک نیازی نخواهد بود، قضیه هم همان است که گفتم، امروز هیچکس حاضر نخواهد بود که هارون را خلع کند و فردا برای بیعت با جعفر حاضر گردد. طیفوری گوید: چون این سخن از دهان هرثمة بیرون آمد هادی رو بحضار مجلس کرده گفت : شاهت الوجوه، بخدای سوگند که هرثمة راست گفت و شما فریبنده هستید، آنگاه در ازاء سخن هرثمة مبلغ پنجاه هزار دینار به وی بخشید و همان موضع نزدیک به باب النقب را که یندون آنجا بهرثمة برخورد کرده بود بهرثمة بعنوان تیول اعطا کرد و از آن تاریخ تاکنون آن موضع را به عسکر هرثمة مینامند، آنگاه مجلس بر هم خورد و مردم همگی با حالت پریشانی بازگشتند... آنگاه هادی نزد امة العزیز شد، وی بهادی گفت : یا امیرالمؤمنین، گمان نمیبرم احدی آنچه را ما دیدیم و شنیدیم دیده یا شنیده باشد، چه مادر بامداد تصور میکردیم که درباره ٔ این جوان (جعفر)بمنتهی آرزوی خویش خواهیم رسید و حال آنکه در شامگاه نسبت بهمان جوان بیمناک میباشیم . هادی گفت چنان است که میگوئی و من تو را بر آنچه دانی معلوماتی علاوه کنم، امة العزیز پرسید آن چیست، هادی گفت من هرثمةبن اعین را فرمان دادم بازگردانند تا وی را گردن زنند، اما همین که در مقابل من بایستاد گوئی چیزی بین من و او حائل واقع شد تا حدی که ناگزیر شدم او را صلتی بخشم و تیولی به وی اعطا کنم و هنوز هم در صدد هستم که نسبت به وی احسان بیشتری روا دارم و پایه اش را بلند گردانم و نامش را معروف و مشهور سازم . امة العزیزاز سخن هادی بگریه درافتاد، هادی گفت : از خداوند تعالی امیدوارم که همواره تو را قرین شادی دارد، امة العزیز و تمامی کسانی که گرداگرد وی بودند تصور کردندکه منظور هادی از این سخن آنست که نسبت به رشید سوءقصدی اندیشیده و باشد که وی را مسموم گرداند، اتفاقاً روزگار مهلتی نداد و شبی چند بیش نگذشت که هادی از دنیا رفت و خلافت به هارون الرشید انتقال یافت و خدای داناست که تا چه اندازه نسبت بجعفر احسان و نیکی مبذول میداشت و تا چه حد بر نعمت و ثروت وی بیفزود و دختر خویش اُم محمد را نیز بکابین جعفر درآورد. یوسف بن ابراهیم از ابومسلم از حمید طائی معروف به طوسی نقل کرده گوید که : ابومسلم گفت : ابوغانم پدر مرا بیماریی سخت عارض و طیفوری طبیب متصدی معالجه ٔ وی شد، بیماری وی عبارت بود از حالتی عصبانی که اغلب بی سببی همنشینان و یاران خویش را بد میگفت و نسبت به آنان امور ناپسندی را مرتکب میشد. روزی من بالای سر پدر خود ایستاده بودم ... در آن حال طیفوری طبیب ورود کرد، نبض وی بگرفت و بقاروره ٔ وی نظری افکند، آنگاه آهسته در گوش وی سخنی گفت که من ندانستم چه گفت . ابوغانم گفت ... دروغ گفتی . طیفوری در پاسخ وی گفت : اعض اﷲ اکذبنا بکذا... من با خود گفتم واﷲ طیفوری در فنای خود کوشید، ابوغانم بسخن خود ادامه داد و گفت یا ابن الکافرة، دلیری و تهور بخرج دادی، چگونه جرأت کردی با من چنین گفتگو کنی، طیفوری گفت بخدای سوگند هیچ گاه باآقا و مولای خود هادی روبرو متحمل سخن درشت نشده ام، اگر مرا دشنامی میداد عیناً به وی بازپس میدادم، با اینحال از تو سگی بدزبان و فحاش چگونه تحمل خواهم کرد. ابومسلم اینجا میگوید و قسم یاد میکند که پدرم رادر این موقع هم خندان و هم گریان دیدم بدین معنی که در پاره ای از خطوط چهره ٔ پدرم آثار خنده و در بعضی دیگر آثار گریه هویدا بود، سپس پدرم به طیفوری گفت که تو دشنام خلیفه را بازپس میدادی ؟ گفت ای واﷲ. پدرم گفت اینک از تو میپرسم، تو را بخدای بازگوی که هنگامی که من تو را دشنام دادم تو چرا دهان بعرض حمید گشودی سپس ابوغانم بر هادی بسیار گریست . یوسف بن ابراهیم گوید: از طیفوری چگونگی جریان خبر ابومسلم را پرسیدم، او نیز چندان گریست و جزع کرد که مرا وحشت دست داد و بیم مرگ وی میرفت وقتی که نام حمید را شنید، آنگاه ابومسلم گفت : بخدای سوگند که بعد از هادی احدی را در معاشرت خون گرم تر و بزرگنهادتر و خوش برخوردتر و منصف تر از حمید ندیدم، یگانه نقصی که ممکن بود در وجود او بیابند آن بود که وی از لشکریان بود و چنانکه لشکریان با یکدیگر گرم هستند وی نیز با آنان گرم حسن سلوک بود، اما وقتی که با دوستان و برادران خویش مصاحبت می کرد گوئی با مردمی که از آنان بریده و ترک مصاحبت کرده رفتار میکند نه با رفقا و همنشینان خود.<br />یوسف بن ابراهیم از طیفوری نقل کرده گوید: مرا خبر داد طیفوری که گفت به حمید طوسی در قصر ابن هبیرة بودیم، در آن هنگام که ابن هبیره بر بغداد چیرگی یافته بود. در این اثنا جماعتی از جبل طی بر حمید وارد شدند، ایشان را رئیسی بود که وی را سخت ارجمند و بر خویش مقدم میداشتند و بر تقدم وی در فضل و بزرگواری بر خودشان معترف بودند، حمید در آن مجلس که حکم درباری داشت بدانها اذن دخول داد تا بر آن جماعت کثرت جمعیت و اتباع خویش را بازنماید. سپس رئیس آنان را مخاطب ساخته پرسید یا ابن عم، سبب آمدن شما چیست، رئیس قوم گفت آمدم تا تو را یاری کنم ... گفت من از احدی توقع یاری و مدد نکنم جز آنکه بدلیری و چالاکی وی وثوق یابم و پردلی و بردباری او را بیازمایم و میزان استقامت او را در سختیها بسنجم، ناگزیرم که تو را نیز بمعرض آزمایش درآورم، اگر از امتحان نیک درآمدی تو را پذیرفتارم وگرنه از همان ره که آمده ای بازگرد. رئیس قوم گفت اینک بهر نحو که خواهی مرا بیازمای . حمید از زیر مصلای خویش عمودی بیرون آورد و رئیس قوم بازو بگشاد، حمید عمود را بروی شانه ٔ خود بلند ساخته و ببازوی رئیس خواست فرودآورد، همین که ببازوی وی نزدیک شد رئیس بازوی خویش بر کنار برد، حمید خمشگین شد و گفت دست مرا بازپس زدی، رئیس قوم ترضیه خواست و خواهان تجدید آزمایش گردید، حمید کرت دیگر گفت بازو گشاده دار، فرمان برد، حمید عمود بلند ساخت که بر بازوی وی فرودآورد، همین که عمود نزدیک ذراع رئیس شد، مانند نوبت اول بازوی خویش را بازپس برد، چون حمید چنین دید فرمان داد که وی را بزندان برند، فراشان وی را کشان کشان از مجلس بیرون بردند، سپس حمید فرمان داد تا همگی چارپایان رئیس طایفه ٔ همراهان او را ضبط کردند و وی را با اتباعش از لشکرگاه بیرون ساختند و جملگی ناگزیر گردیده پیاده راه قبیله ٔ خویش پیش گرفتند. طیفوری گوید: من حمید را بر این اقدامی که کرد سرزنش کردم، وی خندید، سپس گفتم سخنی بر خلاف ذوق و سلیقه ٔ تو در حضور تو گفتم که مورد انکار تو واقع گردید، اما امور فرماندهی کارهائیست که تو را در آن بهره و نصیبی نیست، در این صورت اگر رای مرابا رأی خویش مختلف بینی البته نباید در شگفتی و انکار اصرار ورزی . آنگاه مرا گفت که، من مردی هستم از اهل یمن و پیمبر صلی اﷲ علیه و آله و سلم مُضَری بودو اینک هم خلافت در چنگ مُضَریهاست، چنانکه من اقرباء خویشتن را دوست دارم خلفاء نیز نزدیکان خود را دوست دارند، اگر من بعضی اوقات نسبت به خویشاوندان خود تمایلی ابراز و یا از کسی که از حیث قرابت بخلافت بیش از من علاقه و بستگی داشته باشد اعراض کنم، برای من شک و تردیدی نیست که اگر بحقیقت امر غوری شود تمایل خلافت بسوی ایشان خواهد بود. خلق بسیاری از مردم قبیله ٔ نزار با من متحد میباشند، وقتی تنی از خویشان نزدمن می آمدند من بیم داشتم و پنهان میکردم بواسطه ٔ آنکه مبادا مراوده ٔ آنان تولید مفسده ای در قلوب آنان که آنها را آزموده ام کند، و این نظریه را من در قبیله ٔ نزاریه آزمودم و نمیدانم شاید هر کس از عشیره ٔ من که نزد من می آیند مساوی با یک مرد از قبیله ٔ نزاریه نباشند، از اینرو خواستم دل همراهان و کسانی را که با من دم از یگانگی و اتحاد میزنند بسوی خود جلب کرده باشم و بالعکس هر یک از عشیره ٔ خود را که نزد من می آمدند از خود دور کنم و بیمناک بازگردانم نه امیدوار، چه اگر بیمناک بازگردند ماده ٔ فساد آنان از ما بریده و قطع خواهد شد و چنانچه امیدوار از خانه ٔ من بازگردند کسانی از آنان نزد من خواهند آمد که آنچه از ثروت سواد عراق در تحت اختیار من است چاره ٔ مرض آز و ولع ایشان را نتواند کرد. طیفوری در پایان این خبر گوید: پس از بیانات حمید طوسی بر من روشن شد که حمید در سیاست و تدبیر اصابت رای دارد و امور خویش را بر پایه ای که بنا نهاده بخطا نرفته است . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٩</span>).<br /></font></div>'),
(178655, 'طیفوری', '<span class=\"hlight\">طیفوری .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) زکریابن الطیفوری . یوسف بن ابراهیم گوید: خبر داد مرا زکریابن الطیفوری که هنگام محاربه ٔ بابک خرمی با افشین در لشکرگاه بودم که فرمان داد تعداد همگی تجار و دکاکین و پیشه ٔ هر یک از آنان را که در لشکرگاه میباشند تعیین و صورتی از آنان تنظیم کرده از نظر افشین بگذرانند، و مأمورین فرمان برده صورت را حاضر کرده بحضور افشین آوردند، چون شروع به خواندن اسامی آنان شد همین که بنام صیادله (دوافروشان ) رسیدند افشین گفت : یا زکریا ثبت و ضبط اسامی دوافروشان برای ما نیکوتر و سودمندتر از اسامی سایر پیشه وران است، هر یک از آنان را باید بمعرض آزمایش گذاری تا بین آنها خیرخواهان از بدخواهان و دیانت پیشگان از بی دینان متمایز شوند. من گفتم حق تعالی امیر راگرامی داراد، یوسف لقوه ای کیمیائی اغلب در مجلس مأمون حضور می یافت و در همان مجلس هم به امور فنی خویش میپرداخت . روزی مأمون به وی گفت : یا یوسف در صناعت کیمیا چیزی نیست، یوسف گفت : آری یا امیرالمؤمنین اما آفت آن دوافروشانند، مأمون گفت : ویحک چگونه دوافروشان را آفت کیمیا شناختی، گفت : صیادله را عادت بر آن جاری است که هر کس از ایشان داروئی طلبد خواه در دکان وی آن دارو موجود باشد یا نباشد، گوید آن دارو دارم و از متاعی که در مخزن خویش دارد اندکی به وی دهد، و گوید این همان داروی منظور توست . اینک اگر امیرالمؤمنین صواب بیند نامی غیرمعروف برگزیند و بچند تن فرمان دهد که نزد داروفروشان رفته آن نام را بر هر یک از داروفروشان عرضه دارد و بگوید که بدین دارو نیازمند هستم، مأمون گفت : آن نام برگزیدم و آن «سقطیثا» است که مفهوم حقیقی آن ضیعه ای است نزدیک بغداد.آنگاه چند تن مأمور کرد که ببازار داروفروشان بروند و خواهان آن شوند. فرستادگان فرمان بردند و بهر داروفروشی که میگفتند سقطیثا داری، میگفت : آری، آنگاه از دکان خویش چیزی به دست فرستاده میداد و در مقابل وجهی میگرفت . فرستادگان هر یک بنوبت خود نزد مأمون آمد و چیزهای گوناگون از قبیل آنکه یکی دانه ای چند از تخم گیاهی، دیگری پاره ای از جنس سنگ، سه دیگر خرده ٔ ابریشم نزد مأمون نهادند. خلیفه بر پیشنهاد یوسف لقوه ای آفرین خواند و قطعه ٔ زمینی را که در جوار نهرکلبه بود به رسم تیول به وی بخشید و تاکنون آن قطعه زمین در دست ورثه ٔ یوسف لقوه ای باقی است و از محصول آنجا اعاشه میکنند. اگر امیر نیز مانند مأمون داروفروشان را آزمایش فرماید مقرون بصواب است . افشین دفتری از دفاتر اسروشنه طلب کرد و قریب بیست اسم از اسامی ادویه از آن بیرون ساخت و هر نامی را به یک تن سپرد که نزد داروفروشان رفته خریداری کند. مأمورین بنابر دستور نزد داروفروشان رفته و اسامی به آنان عرضه داشته، بعضی بکلی منکر شناختن دارو شدند و پاره ای دیگر گفتند ما این دارو را داریم و وجهی از حامل آن اسم گرفته و از دکان خویش چیزی به وی میدادند. چون مأمورین نزد افشین بازگشتند و هر یک گزارش خویش را تقدیم داشت افشین جمیع داروفروشان را احضار کرد و آنان را که منکر شناسائی داروها شده بودند بوسیله ٔ منشوری اجازت داد که در لشکرگاه مقیم و مشغول کار خود باشند و مابقی داروفروشان را از لشکرگاه بیرون ساخت و اجازه ٔ اقامت در معسکر بدیشان نداد و منادی در لشکر روانه داشت که بنفی و تبعید آنان از لشکر ندا دردهد واعلام دارد که هر یک از تبعیدشدگان احیاناً در لشکرگاه دیده شوند خونشان مباح باشد، و نامه ای بمعتصم خلیفه بنوشت که چند تن داروفروش متدین و باامانت جهت لشکر اعزام و همچنین پزشکی چند حاذق روانه دارد. معتصم نیز پس از تحسین و آفرین افشین آنچه را استدعا کرده بود مقرون به اجابت داشت . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span>).<br /></font></div>'),
(178656, 'طیفوریان', '<span class=\"hlight\">طیفوریان .</span><font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) فرقه ای از صوفیه بر طریقت ابویزید طیفوربن عیسی بن سروشان بسطامی . (کشف المحجوب هجویری ).<br /></font></div>'),
(178657, 'طیفوریة', '<span class=\"hlight\">طیفوریة.</span> <font color=\"DarkGreen\"><b>[ طَ ری ی َ ]</font></b> (اِخ ) نام سلسله ای از صوفیه منسوب به بایزید بسطامی . رجوع به طیفوریان شود.<br /></font></div>'),
(178658, 'طیفوریة', '<span class=\"hlight\">طیفوریة.</span> <font color=\"DarkGreen\"><b>[ طَ ری ی َ ]</font></b> (ع اِ) ظرف توگود. (دزی ). رجوع به طیفور شود <span class=\"hlight\">:</span> فاتی علی الزله، و رفع الطیفوریة فازعةً. (معجم الادباء مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠٠</span>).<br /></font></div>'),
(178659, 'طیفوس', '<span class=\"hlight\">طیفوس .</span> (معرب، اِ) معرب تیفوس . رجوع به تیفوس شود.<br /></font></div>'),
(178660, 'طیفوس الشکل', '<span class=\"hlight\">طیفوس الشکل .</span> <font color=\"DarkGreen\"><b>[ سُش ْ ش َ ]</font></b> (ع اِ مرکب ) شبه طیفوس . تیفوئید .<br /></font></div>'),
(178661, 'طیفکان', '<span class=\"hlight\">طیفکان .</span> (اِخ ) دهی است از دهستان سیاهو از بخش مرکزی شهرستان بندرعباس در <span class=\"hlight\" dir=\"rtl\">١٠٤</span> هزارگزی شمال خاوری بندرعباس و <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی شمال راه مالرو گهره به سیاهو. کوهستانی و گرمسیر با <span class=\"hlight\" dir=\"rtl\">٣٠٩</span> تن سکنه . آب آن از چشمه . محصول آنجا خرما و مرکبات . شغل اهالی زراعت . راه آن مالرو است . مزرعه ٔ اتاسین جزء این ده است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(178662, 'طیفی', '<span class=\"hlight\">طیفی .</span> <font color=\"DarkGreen\"><b>[ فا ]</font></b> (معرب، اِ) دادی . انثیلی . صاحب اختیارات بدیعی و ابن البیطار این لفظرا با قاف و یاء ضبط کرده اند، و ظاهراً اگر هم کتابت آن با یاء درست باشد یاء آن در تلفظ به الف تبدیل میشود زیرا در فرانسه نیز این نام را طیفا تلفظ کنند. گفته اند حب بَلسان است و گفته اند نباتیست برگ آن شبیه ببرگ سعد و ساق آن املس و گل آن سفید پیچیده مانند موی و منبت آن نیزارهاو آبهای ایستاده است . (فهرست مخزن الادویه ). طیقی .<br /></font></div>'),
(178663, 'طیقان', '<span class=\"hlight\">طیقان .</span> (ع اِ) ج ِ طاق . (دهار). رفها.<br /></font></div>'),
(178664, 'طیقی', '<span class=\"hlight\">طیقی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) طیفی نیز گویند، و آن دادی است . (تحفه ٔ حکیم مؤمن ) (اختیارات بدیعی ). حبی باشد سرخ رنگ مانند سماق بغدادی، و بعضی گویند حب بَلَسان است . (برهان ) (آنندراج ). رجوع به طیفی شود.<br /></font></div>'),
(178665, 'طیل', '<span class=\"hlight\">طیل .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) پای بند ستور یا رسن دراز که بدان ستور را بعلف بندند. یقال : ارخ للفرس طیله ؛ یعنی دراز کن رسن آن را. <BR><font color=\"Blue\">◄</font> (اِمص، اِ) عمر. <BR><font color=\"Blue\">◄</font> درنگی . <BR><font color=\"Blue\">◄</font> غیبت، یقال : طال طیلک . (منتهی الارب ). درازی . یقال : طال طیلک ؛ ای مدتک . (مهذب الاسماء).<br /></font></div>'),
(178666, 'طیل', '<span class=\"hlight\">طیل .</span> (ع اِمص، اِ) درنگی . مکث، یقال : طال طیلک ؛ ای مکثک . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> زندگانی . (آنندراج ). گویند: طال طیلک ؛ای عمرک . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> غیبت . گویند: طال طیلک ؛ ای غیبتک . (منتهی الارب ) (آنندراج ). طول .<br /></font></div>'),
(178667, 'طیلا', '<span class=\"hlight\">طیلا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) عقیدالعنب . رب انگور . خلیل بن احمد فراهیدی گوید طیلا نوعی قطرانست که شراب منصف را بدو ماننده کرده و شراب منصف را نیز طیلا نامیده اند. و احمدبن داود گوید: بعضی عرب رب انگور را طیلا نامند. مطبوخ .<br /></font></div>'),
(178668, 'طیلادن', '<span class=\"hlight\">طیلادن .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی آذریون است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178669, 'طیلافیون', '<span class=\"hlight\">طیلافیون .</span> <font color=\"DarkGreen\"><b>[طَ ف َ ]</font></b> (معرب، اِ) نوعی از حی العالم است که بستان افروز باشد، و بعضی تخم بستان افروز را گفته اند. (برهان ) (آنندراج ). جالینوس گوید: طبیعت آن گرم بود در اول و خشک بود در دوم تا سوم، جراحتهای عفن را نافع بود و بر بهق و برص طلا کردن مفید بود. دیسقوریدس گوید: ورق وی چون ضماد کنند و بر برص شش ساعت رها کنند برص را بغایت نافع بود و باید که بعد از آن آرد جو ضماد کنند و چون بکوبند و باسرکه بیامیزند و در آفتاب بر بهق مالند و رها کنند تا خشک شود بهق را زایل گرداند. (اختیارات بدیعی ).<br />به یونانی اسم گیاهی است شبیه به گیاه خرفه و مابین برگها شاخه های ریزه ٔ زیاده بر شش عدد نمیروید و برگ شاخه ها انبوه و سطبر چون به دست بمالند رطوبت لزجی از آن ظاهر می شود و گلش سفیدو منبتش مزارع و زیر تاک انگور است . در اول گرم و در دوم خشک و مخرج جنین و مشیمه . و طلای او را بجهت برص و بهق سفید مجرب یافته اند. مورث جراحت جلد و مصلحش طلا کردن آرد جو است بعد از شستن آن . (تحفه ٔ حکیم مؤمن ). تاج خروس . خرفه ٔ بری . بقلةالحمقا بریة. ایلیقبرا . حشیشةالبرص . اندرخنی اغریا . ایزون . میشیار. میشهار. و رجوع به طلیفیون شود.<br /></font></div>'),
(178670, 'طیلاقیون', '<span class=\"hlight\">طیلاقیون .</span> (معرب، اِ) محرف طیلافیون است . رجوع به طیلافیون شود.<br /></font></div>'),
(178671, 'طیلان', '<span class=\"hlight\">طیلان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ده کوچکی است از بخش رامیان شهرستان گرگان با <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(178672, 'طیلة', '<span class=\"hlight\">طیلة.</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ل َ ]</font></b> (ع ص ) طیلةُ الریح ؛ باد نَیّحة، مقابل باد نسیجه . رجوع به «نَیّحة» و «نسیجة» شود.<br /></font></div>'),
(178673, 'طیلة', '<span class=\"hlight\">طیلة.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ع اِمص، اِ) عمر. زندگانی . <BR><font color=\"Blue\">◄</font> غیبت . <BR><font color=\"Blue\">◄</font> درنگی . (منتهی الارب ).<br /></font></div>'),
(178674, 'طیلس', '<span class=\"hlight\">طیلس .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b>(معرب، اِ) چادر. (منتهی الارب ) (آنندراج ). طیلسان . ابوالاشبال احمد محمد شاکر ناشر کتاب «المعرب جوالیقی » ذیل کلمه ٔ طیلسان گوید: و در طیلسان دو لغت دیگر نیز هست، یکی «الطیلس » و دیگری «الطالسان »، و در معیار این لغت را بدین نحو معنی و تفسیر کرده که : «جامه ای است که بر دوش افکنند»، و نیز گفته که : «جامه ای است که بدن را احاطه میکند و برای پوشیدن میبافند عاری از تفصیل و دوزندگی »، وادی شیر گفته که «آن پوششی است مدور و سبز بدون دامان که تار یا پود آن که از پشم است و خواص از علما و مشایخ آن را پوشند و آن پوشش پارسیان بوده است ». (المعرب چ مصر مطبعة دار الکتب المصریه <span class=\"hlight\" dir=\"rtl\">١٣٦١</span>هَ . ق .).<br /></font></div>'),
(178675, 'طیلس', '<span class=\"hlight\">طیلس .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (ع اِ) طالس است که حلبه نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(178676, 'طیلسان', '<span class=\"hlight\">طیلسان .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (معرب، اِ) بفتح طاء و تثلیث لام، از قول عیاض و غیر او، چادر. معرب است، اصله تالشان . (منتهی الارب ) (المغرب للمطرزی ). اعجمی معرب و الجمع طیالسه بالهاء و قد تکلمت به العرب . (المعرب جوالیقی ). و در تهذیب و نیز ارموی معرب تالشان با شین ضبط کرده اند ولی اصمعی معرب از تالسان با سین مهمله دانسته و ممکن است منسوب به تالش باشد. <BR><font color=\"Blue\">◄</font> و یقال فی الشتم «یا ابن الطیلسان »؛ یعنی تو عجمی هستی . ج، طیالسة. (منتهی الارب ). و الهاء فی الطیالسة للعجمه فلو رخمت هذا فی النداء لم یجز لانه لیس فی کلامهم فیعل الا معتلاً کسید و میت . <BR><font color=\"Blue\">◄</font> نوعی از رداء فوطه که عربان و خطیبان و قاضیان بر دوش اندازند. (برهان ) (آنندراج ). چادر قاضی . (دهار). فَرَجی ِ بی آستین . چادر یا ردائی که مردم تالش پوشند از پشم درشت . بت طیلسان خز و صوف و مانند آن . (منتهی الارب ). سدوس طیلسان . (منتهی الارب : الطاق ؛ طیلسان . (دهار) <span class=\"hlight\">:</span> بجان من که برخیزی و این جامه ٔ من بپوشی و طیلسان من اندر سر کشی . (ترجمه ٔ تاریخ طبری بلعمی ). و از نواحی ری طیلسانهای پشمین نیکو خیزد. (حدود العالم ).<br />ابر آمد از بیابان چون طیلسان رهبان <br />برق از میانْش تابان چون بسدین چلیپا.<br /><font color=\"Red\">کسائی .</font><br />ابر آمد بر شاخ و بر درخت <br />گسترد رداهای طیلسان .<br /> <font color=\"Red\">ابوالعباس عباسی .</font><br />درخت سیب را گوئی ز دیبا طیلسانستی <br />جهان گوئی همه پُروشّی و پُرپَرنیانستی .<br /> <font color=\"Red\">فرخی .</font><br />من <font color=\"DarkGreen\"><b>[ احمدبن ابی دؤاد ]</font></b> اسب تاختن گرفتم چنانکه ندانستم که بر زمینم یا در آسمان، طیلسان از من جدا شده و من آگاه نه . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٧١</span>).<br />نشان مدبریت این بس که هرگز<br />چو عباسی نشوئی طیلسانت .<br /> <font color=\"Red\">ناصرخسرو.</font><br />زآنکه نجوئی همی ز علم و ز دین بل <br />در طلب اسب و طیلسان وردائی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بر این بلند منبر با بانگ قال و قیل <br />ازبهر طیلسان وْعِمامه وْ ردا شده ست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />به اسب و جامه ٔ نیکو چرا شدی مشغول <br />سخنْت نیکو باید نه طیلسان و ردی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />وَاکنون چوبلبل است خطیب العجب مرا<br />گلبن ز گل همی همه شب طیلسان کند.<br /> <font color=\"Red\">مسعودسعد.</font><br />طیلسان و ردا کمال بود<br />کیسه و صره اصل مال بود.<br /> <font color=\"Red\">سنائی (در تعبیر رؤیا).</font><br />طیلسان موسی و نعلین هارونت چه سود<br />چون بزیر یک ردا فرعون داری صدهزار.<br /> <font color=\"Red\">سنائی .</font><br />کند بساط سخن طی بسان اهل هنر<br />چنو بگسترد از فضل طیلسان سخن .<br /> <font color=\"Red\">سوزنی .</font><br />گر خضر گردم بر آن غمرالردا<br />هم ردا هم طیلسان خواهم فشاند.<br /> <font color=\"Red\">خاقانی .</font><br />این چو مگس خونخور ودستاردار<br />وآن چون خره سرزن و باطیلسان .<br /> <font color=\"Red\">خاقانی .</font><br />بدل سازم به زنار و به برنس <br />ردا و طیلسان چون پور سقا.<br /> <font color=\"Red\">خاقانی .</font><br />وی مشتری ردا بنه از سر که طیلسان <br />درگردن محمد یحیی طناب شد.<br /> <font color=\"Red\">خاقانی .</font><br />در گوش گوشوار سمعنا کشد عراق <br />بر دوش طیلسان اطعنا برافکند.<br /> <font color=\"Red\">خاقانی .</font><br />بر قدحهای آسمان زنار<br />مشتری طیلسان دراندازد.<br /> <font color=\"Red\">خاقانی .</font><br />گر شیردلتر از تو شناسیم هیچ مرد<br />مندیل حیض سگ صفتان طیلسان ماست .<br /> <font color=\"Red\">خاقانی .</font><br />سبحه داران از پس سبوح گفتن در صبوح <br />بر سر زنار ساغر طیلسان افشانده اند.<br /> <font color=\"Red\">خاقانی .</font><br />مستان صبح چهره مطرا به می کنند<br />کاین پیر طیلسان مطرا برافکند.<br /> <font color=\"Red\">خاقانی .</font><br />ازو خلعت تربیت تا نبودش <br />نشد طیلسان دار برجیس خاطب .<br /> <font color=\"Red\">نظام قاری (دیوان البسه ).</font><br />قضا را سجاده مگر با ردا<br />دگر خرقه و طیلسان و عصا.<br /> <font color=\"Red\">نظام قاری (دیوان البسه ).</font><br />به طیلسان چه کند فخر مشتری کاو را<br />سپهر کرده به سجاده داریش مأمور.<br /> <font color=\"Red\">نظام قاری (دیوان البسه ).</font><br />که ردای دعای استسقاست <br />میکنندش به طیلسان احبار.<br /> <font color=\"Red\">نظام قاری (دیوان البسه ).</font><br />و رجوع به ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span> فرهنگ شعوری شود.<br /></font></div>'),
(178677, 'طیلسان', '<span class=\"hlight\">طیلسان .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (اِخ ) اقلیمی است وسیع در نواحی دیلم . (منتهی الارب ) (آنندراج ). رجوع به «طالش » شود. اقلیمی است پهناور دارای شهرستان بسیار از نواحی دیلم یا خزر که ولیدبن عقبة آن را بسال <span class=\"hlight\" dir=\"rtl\">٣٥</span> هجری بگشود. (معجم البلدان ). ولایت طالش در دیلمستان . معرب طالشان و نام طایفه ای از دیلم . و رجوع به ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> البیان و التبیین چ مطبعة الرحمانیه بمصر و تصحیح «حسن سندوبی » شود.<br /></font></div>'),
(178678, 'طیلسان دار', '<span class=\"hlight\">طیلسان دار.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ل َ ]</font></b> (نف مرکب، اِ مرکب ) کنایه از پیر و مرشد <span class=\"hlight\">:</span> <br />طیلسان داران دین بودند آنجا نعره زن <br />خانقه داران جان بودند آنجا جامه در.<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(178679, 'طیلسان مزعفر', '<span class=\"hlight\">طیلسان مزعفر.</span> <font color=\"DarkGreen\"><b>[ طَ<span class=\"hlight\" dir=\"rtl\">/</span> طِ ل َ ن ِ م ُ زَ ف َ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از شعاع آفتاب است . (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br />تا زمین بر کتف ز خلعت روز<br />طیلسان مُزَعْفَر اندازد.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(178680, 'طیلسان مطرا', '<span class=\"hlight\">طیلسان مطرا.</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ل َ ن ِ م ُ طَرْ را ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از شب است که بعربی لیل خوانند. (برهان ) (آنندراج ).<br /></font></div>'),
(178681, 'طیلقان', '<span class=\"hlight\">طیلقان .</span> <font color=\"DarkGreen\"><b>[ طَ ل َ ]</font></b> (معرب، اِ) نمد. ساکیز. لبد. لبده . پلاس . کلاه نمد. کلاه نمدی . رجوع به طالقانی شود. (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨١</span>).<br /></font></div>'),
(178682, 'طیلون', '<span class=\"hlight\">طیلون .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع اِ) غوک . قورباغه . وزغ . ج، طوالین . (دزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨١</span>).<br /></font></div>'),
(178683, 'طیلیلس', '<span class=\"hlight\">طیلیلس .</span> <font color=\"DarkGreen\"><b>[ لی ل ِ ]</font></b> (معرب، اِ) به یونانی خراطین است . (فهرست مخزن الادویه ). طیلیاس .<br /></font></div>'),
(178684, 'طیلیلیس', '<span class=\"hlight\">طیلیلیس .</span> (معرب، اِ) رجوع به طیلیلس شود.<br /></font></div>'),
(178685, 'طیم', '<span class=\"hlight\">طیم .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) سرشتن خدای کسی را بر نیکوئی . یقال : طامه اﷲ علی الخیر. (منتهی الارب ) (آنندراج ). مصدر «طامه اﷲ علی الخیر»؛ ای جبله . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> نیکوکار شدن . یقال : طام فلان . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(178686, 'طیماثاوس', '<span class=\"hlight\">طیماثاوس .</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (اِخ ) از نقله و مفسرین علوم قدیم است .<br /></font></div>'),
(178687, 'طیماثیوس', '<span class=\"hlight\">طیماثیوس .</span> (اِخ ) جاثلیقی از ملت نصاری در عصر هارون الرشید خلیفه ٔ عباسی . (تاریخ الحکماء قفطی چ لیبسیک ص <span class=\"hlight\" dir=\"rtl\">٣٨٣</span>). و این نام درعیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٤</span> طیمانیوس الجاثلیق آمده است .<br /></font></div>'),
(178688, 'طیماذ', '<span class=\"hlight\">طیماذ.</span> (اِخ ) یوسف بن ابراهیم گوید: چون ابوسهل بن نوبخت بر اثر ضعف مزاج از دربار منصور کناره جست منصور به احضار پسر وی فرمان داد تا بجای پدرخدمت گذارد. چون پسر وی حضور یافت منصور نام وی پرسید، گفت نام من خرخشاذماه طیماذاه ماذریاد خسروا بهمشاذ است، منصور گفت آیا راست و حقیقت میگوئی که نام تو بدین تفصیل است ؟ گفت آری . منصور گفت باید نام خودتغییر دهی یا فقط طیماذ تنها را اختیار کن و یا بجای آن ابوسهل را کُنیت خویش قرار ده . وی ابوسهل را برگزید و نام پیشین ترک گفت . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٢</span>).<br /></font></div>'),
(178689, 'طیمارخس', '<span class=\"hlight\">طیمارخس .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (اِخ ) یک تن از اوصیاء ارسطاطالیس . (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٠</span>) (تاریخ الحکماء قفطی چ لیبسیک ص <span class=\"hlight\" dir=\"rtl\">٣٨</span>).<br /></font></div>'),
(178690, 'طیماناناوس', '<span class=\"hlight\">طیماناناوس .</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (اِخ ) نام فیلسوفی از یونان (از اسحاق بن حنین ) که در ایام فترت بین افلاطون و اسقلبیوس میزیسته . (فهرست ابن الندیم ص <span class=\"hlight\" dir=\"rtl\">٣٩٩</span>).<br /></font></div>'),
(178691, 'طیماناوس', '<span class=\"hlight\">طیماناوس .</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (اِخ ) استاد آموزگار سقراط حکیم بود. روزی سقراط در کودکی که نزد وی دانش میجست وی را گفت از چه روی مرا از ثبت و تدوین آنچه از تو فرامیگیرم مانع میشوی ؟ طیماناوس به وی گفت تا چند تو رابه پوست چارپایان مردار وثوق و اعتماد است و از دلهای زنده کناره جوی میباشی، چنین بیندیش که وقتی کسی تو را در اثناء راه و گذر در معبری ملاقات کرد و چیزی از دانشی از تو پرسید، آیا در آن هنگام سزاوار است که وی را گوئی درنگ کن تا بخانه بازگردم و به کتابهای خویش نظر افکنم ؟ پس اگر چنین عملی را ناسزا میشماری بر تو باد که آنچه را از دانش فرامیگیری در سینه و خاطر خویش محفوظ بداری و پیوسته ملازم حفظ کردن باشی .سقراط از آن تاریخ مادام العمر پند استاد خویش را کار بست تا رسید بدانچه رسید. (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>).<br /></font></div>'),
(178692, 'طیماناوس', '<span class=\"hlight\">طیماناوس .</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (اِخ ) یکی از فیلسوفان و شاگردان افلاطون و معاصر با دیسقوریدس . (از اسحاق بن حنین ) (عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>). درتتمه ٔ کتاب صوان الحکمه از ابونصر فارابی کتابی بنام «کتاب طیماناوس » یاد کرده و مولی محمد شفیع پنجابی ناشر کتاب تتمه ٔ صوان الحکمه در تعلیقی که بر کتاب مذکور نوشته، مینویسد نام صحیح کتاب فارابی طیماؤس است - انتهی . و نخستین کسی که بنام طیماؤس کتابی تألیف کرده افلاطون فیلسوف معروف است که دأب وی آن بود که کتب مصنفه ٔ خود را در هر موضوعی که فراهم آورده نام کتاب را بشخصی که در آن موضوع نظریه ٔ مخصوصی داشته نسبت میداده است چنانچه طیماوس نام یکی از فلاسفه است که در علوم طبیعی تخصص داشته و افلاطون طیماؤس را بنام آن فیلسوف تصنیف کرده است . (ابن الندیم ص <span class=\"hlight\" dir=\"rtl\">٣٤٤</span>). و رجوع به ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>، <span class=\"hlight\" dir=\"rtl\">٥٠</span>، <span class=\"hlight\" dir=\"rtl\">٥٣</span>، <span class=\"hlight\" dir=\"rtl\">١٠٠</span>، <span class=\"hlight\" dir=\"rtl\">١٠١</span>، <span class=\"hlight\" dir=\"rtl\">٣١٩</span> ج <span class=\"hlight\" dir=\"rtl\">١</span> عیون الانباء و ص <span class=\"hlight\" dir=\"rtl\">١٣١</span>، <span class=\"hlight\" dir=\"rtl\">٢٧٥</span> تاریخ الحکماء قفطی چ لیبسیک شود.<br /></font></div>'),
(178693, 'طیمرجان', '<span class=\"hlight\">طیمرجان .</span><font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دیهیست از دهات مرغزار اورد که از مرغزارهای معروف پارس است . (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٥٤</span>).<br /></font></div>'),
(178694, 'طیمرخس', '<span class=\"hlight\">طیمرخس .</span> <font color=\"DarkGreen\"><b>[ م َ خ ُ ]</font></b> (اِخ ) یکی از اوصیاء ارسطو بوده است . (فهرست ابن الندیم ) (تاریخ الحکماء قفطی چ لیبسیک ص <span class=\"hlight\" dir=\"rtl\">٣٢</span>).<br /></font></div>'),
(178695, 'طیموخارس', '<span class=\"hlight\">طیموخارس .</span> (اِخ ) وی اهل یونان و ازدانشمندان ریاضی و دانا بهیئت افلاک و در صناعت رصدبندی ستارگان بصیر و ماهر بود. در عصر وی رصد ستارگان بسته شد و مواضع هر ستاره ای محقق گشت . بطلمیوس در کتاب مجسطی رصدهای وی را نام برده و ضمناً یادآور شده است که عصر طیموخارس <span class=\"hlight\" dir=\"rtl\">٤٢٠</span> سال پیش از زمان خود بطلمیوس بوده است . (تاریخ الحکماء قفطی چ لیبسیک ص <span class=\"hlight\" dir=\"rtl\">٢١٨</span>). تاریخ رصد بستن وی بنابر قول حاجی خلیفه مؤلف کشف الظنون <span class=\"hlight\" dir=\"rtl\">٥٥٤</span> سال گذشته از سلطنت بخت نصر بوده که برابر است با <span class=\"hlight\" dir=\"rtl\">٩١٥</span> سال قبل از هجرت . (کشف الظنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٧٤</span>).<br /></font></div>'),
(178696, 'طیمورث', '<span class=\"hlight\">طیمورث .</span> <font color=\"DarkGreen\"><b>[ طَ رِ ]</font></b> (اِخ ) صورتی است از طهمورث <span class=\"hlight\">:</span> <br />نشستم برِ تخت فرخ پدر<br />بر آئین طیمورث دادگر.<br /> <font color=\"Red\">فردوسی .</font><br />ورجوع به طهمورث شود.<br /></font></div>'),
(178697, 'طیموس', '<span class=\"hlight\">طیموس .</span> (معرب، اِ) غده ٔ زائده . طیموس گوساله .<br /></font></div>'),
(178698, 'طین', '<span class=\"hlight\">طین .</span> (اِخ ) (عقبة الطین ) اسم موضعی است به فارس . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٩١</span>).<br /></font></div>'),
(178699, 'طین', '<span class=\"hlight\">طین .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (ع مص ) نیک کردن کار گِل را. یقال : طان طیناً. (منتهی الارب ) (آنندراج ). به گِل کردن . (تاج المصادر بیهقی ) (زوزنی ). <BR><font color=\"Blue\">◄</font> مهر کردن کتاب را به گِل . (منتهی الارب ) (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> اندود کردن بام را. یقال : طان السطح . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سرشتن خدای کسی رابر نیکی . یقال : طانه اﷲ علی الخیر. (منتهی الارب ).<br /></font></div>'),
(178700, 'طین', '<span class=\"hlight\">طین .</span> (ع اِ) گل . (منتهی الارب ) (آنندراج ). طینة اخص ّ است از آن . خاک <span class=\"hlight\">:</span> و اذقلنا للملئکة اسجدوا لاَّدم َ فسجدوا الاّ ابلیس قال اءاسجد لمن خلقت طیناً (قرآن <span class=\"hlight\" dir=\"rtl\">٦١/١٧</span>)؛ یاد کن ای محمد چون ما گفتیم فرشتگان را که سجده کنید آدم را، سجده کردند مگر ابلیس که او گفت : من سجده کنم کسی را که تو او را از گل آفریدی ؟ (از تفسیر ابوالفتوح رازی ).<br />گر تو خواهی ظاهر و باطنْت گردد همچو تیر<br />در سحرگه دیده ات برروی طین باید نهاد.<br /> <font color=\"Red\">سنائی .</font><br />ابا جدّ تو بوده بر انبیا شه <br />پدیدار تا آمده آدم از طین .<br /> <font color=\"Red\">سوزنی .</font><br />چون مخمر کرد طین خلقت او کردگار<br />بخل را زآن گل برون آورد چون موی ازخمیر.<br /> <font color=\"Red\">سوزنی .</font><br />بنگر که چیست بسته درین زندان <br />زنده وْ روان به چیست چنین این طین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />آن چنان که جان بپرّد سوی طین <br />نامه پرّد از یسار و از یمین .<br /> <font color=\"Red\">مولوی .</font><br />دید طین آدم و دینش ندید<br />این جهان دید آن جهان بینش ندید.<br /> <font color=\"Red\">مولوی .</font><br />کلوخ . خاک نمناک . (غیاث اللغات ): قِدرٌ من طین ؛ دیگ سفالین . <BR><font color=\"Blue\">◄</font> مجموع گِلها مبرد و مجفف بود. (اختیارات بدیعی ). طین به لغت عربست و بپارسی گل گویند و به هندی ماتی گویند. ارجانی گوید: جمله گلها سرد و خشک است، بهترین خاکها خاک خالص از ریگ و شوره ٔ گوگرد است و طین الحر نامند از جهت پاکی او و بفارسی خاک رست گویند و اقسام خاکها بعد از احراق و شستن سردتر و لطیفتر و در افعال ثابت تر میباشند. جمیع خاکهای خالص سرد و خشکند سوای طین بلد المصطکی، و لطیف ترین خاکها آنست که در آبهای شیرین جاری ته نشین شده باشد و طین مصری که از آب نیل حاصل میشود بهتر از اقسام آن و مجموع او رادع اورام حاره و مقوی اعضاء سست و رافع حرارات مقعد و اعیاء که از سواری بسیار و حرکات حادث شده باشد. و چون خاک خالص رادر آبهای مغشوش و شور ریخته بگذارند تا ته نشین شود اصلاح آن میکند و چون با آب تلخ و شور مخلوط کرده عرق بکشند شیرین میشود و مجربست . و خاکهای غیرخالص در افعال شبیه به جزو مخلوط اوست و خاک که همیشه آفتاب بر او تابیده باشد، طلای او با سرکه جهت گزیدن هوام بی عدیل است و آنچه آتش بسیار دیده باشد بغایت مجفف و منقی بشره و جالی بهق و رافع خشونت بدن و حکه با سرکه جهت گزیدن زنبور و خاک شور یا نمک و سرکه جهت کچلی سر اطفال مجرب و جمیع خاکها مسدد و رافع آن انیسون است و بوی کاهگل کهنه که آب و گلاب بر وی بپاشند، مقوی دل و روح نفسانی و رافع غشی و التهاب و ضماد او با سرکه جهت گزیدن هوام و رادع اورام حاره و عرق او که با گلاب و عرق گاوزبان و امثال آن بکشند، جهت خفقان وتقویت دل و ضعف معده ٔ حاره بسیار مفید است . (تحفه ٔ حکیم مؤمن ).<br />در قانون و شریعت اسلام هیچ نوع خاکی خوردن آن جائز نیست مگر خاک گردآمده بر ضریح مقدس امام حسین علیه السلام که از اندرون ضریح به دست آورند آنهم مشروط به آنکه مقدار تربت زیاده از وزن دانه ای از باقلاء مصریه نباشد. بروایتی استعمال و خوردن گل ارمنی نیز مجاز است و این تساهل برای آن است که ممکن است این نوع از خاک یک نوع تسکینی در پاره ای از مواقع در بیماریها ایجاد کند. (دکری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٦</span>). و رجوع به تذکره ٔ انطاکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٩</span> و «گِل » و انواع آن شود.<br /></font></div>'),
(178701, 'طین احمر', '<span class=\"hlight\">طین احمر.</span> <font color=\"DarkGreen\"><b>[ ن ِ اَ م َ ]</font></b> (ترکیب وصفی، اِ مرکب ) گِل سرخ . اسم مغره است . (اختیارات بدیعی ) (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178702, 'طین ارضی', '<span class=\"hlight\">طین ارضی .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَ ]</font></b> (ترکیب وصفی، اِ مرکب ) نام سنگی است . حمداﷲ مستوفی در نزهة القلوب در ضمن احجار معدنی این نام آورده گوید: سرد است بدرجه ٔ اول و خشک به دوم . ریش امعا و رفتن خون از زخم و خون برآمدن از ریش دهن و مرض سبل را مفید است . (نزهة القلوب خطی ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(178703, 'طین ارمنی', '<span class=\"hlight\">طین ارمنی .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَ م َ]</font></b> (ترکیب وصفی، اِ مرکب ) گِل ارمنی . سرد است در درجه ٔ اول و خشک است در دو درجه و ریشهاء امعاء را نیکو گرداند و راندن شکم را دفع کند و دمش خون را و سیلان منع کند و ریشهاء عفن راکه در دهان پدید آید چون سرکه بهم آمیخته شود و بکار برده آید منفعت کند و به آن سبب که در آن خاصیتی که ریشهاء شش را نیکو گرداند و رطوبتی ناشایسته را که در آن بود خشک گرداند و نزله را سود دارد و شربت و طلاء آن طاعونها را دفع گرداند. (ترجمه ٔ صیدنه ). گِلی است سرخ رنگ که به تیرگی زند، اسحاق بن عمران گوید که : سرخی است بسیاهی زند و خوشبوی و مذاق وی ترابی بودو بزبان بچفسد و طبیعت وی سرد است در اول و خشک است در دوم، و گویند سرد و خشکست در اول . و بهترین آن دردی است که در وی رمل نبود چون سحق کنند و چون بر زبان نهند بچسبد خون را ببندد و طاعون را طلا کردن و خوردن نافع بود و جراحتها و قلاع را مفید بود و نزله ای که از سینه بریزد و از آن ضیق النفس پیدا شود هیچ دوائی به از وی نبود. مقدار یک مثقال استعمال کردن سل را مفید بود بسبب آن که ریش وی را خشک گرداند و جهت تب وبائی عظیم نافع بود، چنانکه گویند که در زمین ارمن وقتی وبائی بود که چند تن از آن بماندند و آن چند کس را چون تحقیق کردند همیشه این گل را اندکی خوردندی و این خاصیت را از آنجا معلوم کردند و ازبهر آنست که اطباء بشراب و گلاب فرمایند و اگر تب بود بگلاب و آب سرد. و شکستگی استخوان را بغایت مفید بود با اقاقیاطلا کردن و پوست بواسیر از مقعد بیرون آورد. و گویندمضر بود به سپرز و مصلح وی گلاب بود. و اسحاق بن عمران گوید: بدل وی طین حجازی بود که در اندلس معروف به انجبار است . و گویند بدل آن مغر است و بعضی گویند طین لاکی است . (اختیارات بدیعی ). گلی است که از بلاد ایروان آرند، سرخ تیره ٔ جگری و با نرمی و اندک چربی میباشد، در دوم سرد و در آخر او خشک و در رفع وبا و طاعون و ردع اورام و قطع سیلان خون اعضا و اسهال مثل گل مختوم و جهت ضیق النفس و سل بغایت مفید و مضر سپرز و مصلحش مصطکی و گلاب بدلش طین حجازی تا دو درهم است . (تحفه ٔ حکیم مؤمن ). بپارسی گل ارمنی گویند، طبیعتش سرد و خشک است در اول چون به شربت انجبار میل کشد خون ببندد و طاعون را نفع دهد و نزله و ضیق النفس را سودمند آید و ریش شش را سودمند آید و خشک گرداند و تبهای وبائی را نافع بود و شربتی از آن نیم مثقال است .<br /></font></div>'),
(178704, 'طین اصفر', '<span class=\"hlight\">طین اصفر.</span> <font color=\"DarkGreen\"><b>[ ن ِ اَ ف َ ]</font></b> (ترکیب وصفی، اِ مرکب ) طین الصنم خوانند و آن در موضعی نزدیک قسطنطنیه است از میان دو کوه آرند و لون آن زرد تیره رنگ و در آنجا رهبانانند که بر این گل مهر مینهند و آن طلسم کسی نتواند خواندن و نداند که چیست بغیر از ایشان و اگر کسی دیگر بسازد و آن طلسم بشناسد آن عزیز بود. و طبیعت آن سرد و خشک بود و بر ورمهای گرم طلا کردن سودمند بود و خون رفتن بازدارد و خوردن وی در بستن خون از همه ٔ طینها بقوت تر بود و فاضلتر. (اختیارات بدیعی ). از میان دو کوه حوالی قسطنطنیه به هم میرسد، زرد مایل به تیرگی و بر آن صورت بت نقش است . سرد و خشک و در رفع نزف الدّم و نفث الدّم و اسهال دموی و چرکدار از اکثر خاکها بهتر است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178705, 'طین اصفهانی', '<span class=\"hlight\">طین اصفهانی .</span> <font color=\"DarkGreen\"><b>[ ن ِ اِ ف َ ]</font></b>(ترکیب وصفی، اِ مرکب ) طین نیشابوری است . (فهرست مخزن الادویه ). طین خراسانی است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178706, 'طین اقروطون', '<span class=\"hlight\">طین اقروطون .</span> <font color=\"DarkGreen\"><b>[ ن ِ اِ ]</font></b> (ترکیب اضافی، اِ مرکب ) طین اقریطس است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178707, 'طین اقریطس', '<span class=\"hlight\">طین اقریطس .</span> <font color=\"DarkGreen\"><b>[ ن ِ اِ طِ ]</font></b> (ترکیب اضافی، اِ مرکب ) گِلی که آن را از خزینه ٔ اقریطس به اطراف برند و آن موضع را بلد مصطکی نیز گویند. شوینده ٔ هر جراحتهاست و گوشت تازه برویاند. (ترجمه ٔ صیدنه ). آن را اقرقرطون و قریطون نیز نامند، خاکیست خاکستری رنگ با خشونت و به انگشت شکسته گردد و در قوت شبیه به شَب ّ است و از آن بسیار ضعیفتر و فرق میان هر دو به چشیدن معلوم میگردد و تجفیف این به آن حد نیست و غالب بر آن اجزای هوائیه است . طبیعت آن گرم و خشک است . جالی بی لذع و جهت قروح چشم نافع و تعلیق آن جهت حفظ جنین و منع از اسقاط مؤثر، و گفته اند مسهل ولادت است و نقاشان جهت ثبات رنگ آن در نقاشی مستعمل دارند. (مخزن الادویه ). مضعفترین طینها بود که یاد کرده شد و مضعف حواس بود و ریشهای چشم را نافع بود. چون زن آبستن از خود بیاویزد بچه نگاه دارد. و وی جلا دهد بغیر لذع . (اختیارات بدیعی ).<br /></font></div>'),
(178708, 'طین اندلسی', '<span class=\"hlight\">طین اندلسی .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَ دُ ل ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) سیاه و کثیف میباشد و در ضمادات استعمال او جائز است . (تحفه ٔ حکیم مؤمن ). طین سیاه کثیف است که از سموم قتاله است و از داخل غیرمستعمل و داخل ضمادات و اطلیه کرده میشود. (فهرست مخزن الادویه ).<br /></font></div>'),
(178709, 'طین اکل', '<span class=\"hlight\">طین اکل .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَ ]</font></b> (ترکیب اضافی، اِ مرکب ) طین خراسانی است . طین نیشابوری . طین حُرّ. گِل خوراکی . و آن را طین مأکول نیز نامند.<br /></font></div>'),
(178710, 'طین بحری', '<span class=\"hlight\">طین بحری .</span> <font color=\"DarkGreen\"><b>[ ن ِ ب َ ]</font></b> (ترکیب وصفی، اِ مرکب ) طین مختوم است . (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویه ).<br /></font></div>'),
(178711, 'طین بلد مصطکی', '<span class=\"hlight\">طین بلد مصطکی .</span> <font color=\"DarkGreen\"><b>[ ن ِ ب َ ل َ دِ م َ طَ ]</font></b> (ترکیب اضافی، اِ مرکب ) و آن را طین جزیرة مصطکی نیز نامند و نیز طین خیا و خیوس هم خوانند. دیسقوریدس گوید: نیکوترین آن بود که رنگش سفید بود و به لون رقیق بود و صفائح داشته باشد و پاره های مختلف و چون در حمام خود را بدان شویند روی و مجموع بدن را جلادهد و فاضلترین ادویه بود که جهت ریشها که از سوختگی آتش بود استعمال کنند. (اختیارات بدیعی ). خاکی است خاکستری رنگ و باصفائح و ثقیل الوزن و در آب زود حل میشود و از جزیره ٔ خیوس که مصطکی حاصل میشود می آرند، و در دویم گرم و خشک و جالی و مفتح و جاذب خون بظاهرجلد و نیکوکننده ٔ رخسار است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178712, 'طین جلود', '<span class=\"hlight\">طین جلود.</span> <font color=\"DarkGreen\"><b>[ ن ِ ج ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) خاکی است که پوست را بدان رنگ میکنند و سرخ مایل بزردی میشود با قوت قابضه و محلله و ضماد اوجهت اسهال و اورام نافع است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178713, 'طین حجازی', '<span class=\"hlight\">طین حجازی .</span> <font color=\"DarkGreen\"><b>[ ن ِ ح ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) انجبار. (ابن البیطار).<br /></font></div>'),
(178714, 'طین حر', '<span class=\"hlight\">طین حر.</span> <font color=\"DarkGreen\"><b>[ ن ِ ح ُرر ]</font></b> (ترکیب وصفی، اِ مرکب ) محمدبن عبدون گوید: طین حر طین علک خالص از رمل بود. مؤلف گوید: گِلی است نزدیک در شیراز و بشیرازی گل کوفی (کرنی ؟ کربی ؟) خوانند و در طبیعت نزدیک به وی بود و آن را نیز بدین اسم خوانند و آن گل بغایت سبزرنگ است وچون بپوست بادام دخان کنند ازبهر خوردن لون را سرخ کند و طعم آن خوش بود و کمتر بریان ناکرده خورند. و علی بن ربن گوید: طین حر سرد و خشک بود به اعتدال نیکوبود جهت همه جراحتها. و اگر با سرکه بر گزندگی زنبور طلا کنند درد ساکن گرداند. (اختیارات بدیعی ). طین نیشابوری . طین اکل . گل خالص بی ریگ . (بحر الجواهر). شامل طین اندلس و فارسی دانسته اند و مراد از آن خاک خالص است . طین قیمولیا .<br /></font></div>'),
(178715, 'طین حکمت', '<span class=\"hlight\">طین حکمت .</span> <font color=\"DarkGreen\"><b>[ ن ِ ح ِ م َ ]</font></b> (ترکیب اضافی، اِ مرکب ) بپارسی گِل حکمت خوانند و صفت آن بسیار است . مؤلف گوید: بهترین این نوع است که گل زرد پاک چهار من بکوبد و بپزد و یک من کاغذ و نیم من نمک در آن کند وبه دست بمالد تا حل شود، بعد از آن گل بر سر آن کندو چهاریکی موی سر آدمی بمقراض چیده چهاریکی سرگین اسب به گژدمی بیخته بر سر آن کند و نیک بمالد و چندانکه بیشتر مالد نیکوتر بود، آنگاه غنده غنده بنهد تا خشک گردد و هر زمان که خواهد بکوبد و به آب صافی خمیرکند و استعمال کند. بهترین انواع گل حکمت این بود که گفته شد. نوعی دیگر صاحب منهاج گوید: یک جزو گل و یک جزو نمک و یک جزو خطمی و موی چیده بسرشند و نیک نیک بمالند تا مستعمل شود. (اختیارات بدیعی ). از مرکبات است و اقسام او در دستورات مرقوم بجهت شدّ و وصل و نگاه داشتن ظروف و شیشه ها از ضرر آتش ترتیب داده اند و ضماد او جهت شکستگی اعضا و تقویت استخوان و عصب مؤثر است . (تحفه ٔ حکیم مؤمن ). صفتش آن است که یک من کاغذ و نیم من نمک شب در آب گذاشته صباح دست بمالند تا حل شود و صاف کنند و چهار من گل زرد پاک کوفته و بیخته و چهاریکی موی سر آدمی که مقراض کرده باشند و مثلش سرگین اسب بیخته اضافه کنند و به دست بمالند تا نیک بهم سرشته شود، پس گلوله ها کرده بگذارند تا خشک شود هرگاه که خواهند بکوبند و بپزند و به آب صافی خمیر کرده بکار برند. (فهرست مخزن الادویه ). و اما رماد العقارب فید بریان تطین قارورة سخینة بطین الحکمة ثم یجعل فیها العقارب فی تنور حارة ... (ابن البیطار). و یوضعان <font color=\"DarkGreen\"><b>[ الکبریت و الزئبق فی عمل الزنجفر ]</font></b> فی قدر و یستوثق من فمه لئلایطیر الزئبق بغطاء و یطین بطین الحکمة و یدفن فی نارالسرجین . (ابن البیطار). لکلرک این قسمت را از ترجمه حذف کرده، یا در نسخه ٔ وی از اصل عربی نبوده است .<br /></font></div>'),
(178716, 'طین حیا', '<span class=\"hlight\">طین حیا.</span> <font color=\"DarkGreen\"><b>[ ن ِ ح َ ]</font></b> (ترکیب اضافی، اِ مرکب ) صورتیست از طین خیا. رجوع به طین بلد مصطکی شود.<br /></font></div>'),
(178717, 'طین حیوس', '<span class=\"hlight\">طین حیوس .</span> <font color=\"DarkGreen\"><b>[ ن ِ ح َ ]</font></b> (ترکیب اضافی، اِ مرکب ) صورتی است از طین خیوس . رجوع به طین بلد مصطکی شود.<br /></font></div>'),
(178718, 'طین ختم', '<span class=\"hlight\">طین ختم .</span> <font color=\"DarkGreen\"><b>[ ن ِ خ َ ]</font></b> (ترکیب اضافی، اِ مرکب )گِل مهر. گِل سرخ . و رجوع به غیاث ذیل ختام و ختامه و همین لغت نامه ذیل لک و لاک و طین مختوم و مقدمه ٔ ابن خلدون ترجمه ٔ محمدِ پروین گنابادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٨٦</span> شود.<br /></font></div>'),
(178719, 'طین خراسانی', '<span class=\"hlight\">طین خراسانی .</span> <font color=\"DarkGreen\"><b>[ ن ِ خ ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) طین نشابوری است که گفته شد. (اختیارات بدیعی ). گلی است بسیار سفید و خوشبو و خوش طعم و با اندک شوری، و ضرر خوردن او کمتر از سایر خاکهاست و بعضی که عادت به خوردن گل داشته باشند بجهت کمی ِ مضرت از آن میخورند و شرب آن بعد از خوردن چربیها و چیزهای رطوبت دار که قی آرند مانع قی میگردد و جهت سیلان آب دهن و جوع کلبی و هیضه ٔ مهلکه که با قی و اسهال باشد ومنع نزلات مفید است خصوصاً که مخلوط باشد با اشنه و گلاب و سعد و اذخر و کبابه و قاقله، و قدر شربتش تا سه مثقال است و در دفع هیضه دو وقیه برشته کرده ٔ او راسه بار با آب سیب ترش باید بنوشند و بدستور با آب سرد و طبیخ سعد همین اثر دارد. (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178720, 'طین خیا', '<span class=\"hlight\">طین خیا.</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به طین بلد مصطکی شود.<br /></font></div>'),
(178721, 'طین خیوس', '<span class=\"hlight\">طین خیوس .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به طین بلد مصطکی شود.<br /></font></div>'),
(178722, 'طین داغستانی', '<span class=\"hlight\">طین داغستانی .</span> <font color=\"DarkGreen\"><b>[ ن ِ غ ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) قسمی از او زرد کاهی کم رنگ و قسمی مغسول و سفید و مصنوع بشکل قرصی و قسمی مایل بکبودی است و مجموع آن خوشبو خصوصاً مغسول سفید او و از داغستان حوالی شیروان آرند. در جمیع افعال بهتر و قویتر از گل مختوم و مفرح قوی و دافع سمیت اخلاط و تب غشی و خفقان است . حقیر مکرر تجربه نموده است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178723, 'طین دقوقی', '<span class=\"hlight\">طین دقوقی .</span> <font color=\"DarkGreen\"><b>[ ن ِ دَ ]</font></b> (ترکیب وصفی، اِ مرکب ) از ناحیه ٔ دقوقای بلاد حلب آرند. کبودرنگ و بسیار املس و با ملاست و سرد و خشک و رافع اسهال و طلای او جهت بردن چرک بدن و موی و رفع اورام حاره مؤثر است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178724, 'طین راهب', '<span class=\"hlight\">طین راهب .</span> <font color=\"DarkGreen\"><b>[ ن ِ هَِ ]</font></b> (ترکیب اضافی، اِ مرکب ) طین مختوم است . (تحفه ٔ حکیم مؤمن ). طین اصفر است که آن را طین صنم نیز نامند، و کسانی که آن را طین مختوم دانسته اند توهم کرده اند. (فهرست مخزن الادویه ). رجوع به طین مختوم شود.<br /></font></div>'),
(178725, 'طین رومی', '<span class=\"hlight\">طین رومی .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) مجفف و مقبض بود، منع ورمی که در جفون پیدا شود کند، با آب کاسنی طلا کنند و خون که از چشم آید بازدارد. (اختیارات بدیعی ). سرخ نیم رنگ و سفید ومایل بکبودی خوشبو میباشد و یک نوع طین قبرسی اوست و در افعال مثل گل ارمنی است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178726, 'طین سجلات', '<span class=\"hlight\">طین سجلات .</span> <font color=\"DarkGreen\"><b>[ ن ِ س ِ ج ِل ْ لا]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به طین مختوم شود.<br /></font></div>'),
(178727, 'طین شاموس', '<span class=\"hlight\">طین شاموس .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) استاد احمد فرج اندر کتاب خویش میگوید: طین شاموس طلق است و خواجه ابوعلی سینا رَحِمَه ُاﷲ میگوید: همانا که او طلق نیست و بزبان یونان طین شاموس را نامیست که ترجمه ٔ آن کوکب الارض است و بیشتری اهل روزگار خاصه اهل صنعت کوکب الارض طلق را شناسند. (ذخیره ٔ خوارزمشاهی ). آن را طین شامس و کوکب ساموس نیز خوانند. بهترین آن بود که سفید و سبک بود و بغایت بزبان چسبد مانند دلق و چون در آب نهند زود حل شود. از بلاد یونان و جزیره ٔ قبرس خیزد و وی خشک تر از طین مختوم بود. وی را غسل حاجت نیست و در بستن خون قائم مقام طین مختوم بود و بر ورم ثدیین طلا کردن نافع بود و ساکن گرداند. در ابتداء نقرس طلا کردن سود دهد و در نفث دم و درمداوای قرحه ٔ امعا پیش از آن که متعفن شود حقنه کنند به ماءالعسل بعد از آنکه به نمک آب پس به آب لسان الحمل حقنه کردن سودمند بود و اگر با سرکه ٔ ممزوج به آب بیاشامند نافع بود جهت ورمهای گرم خاصه چون بر آن عضو رطوبت زیاده بود و سست باشد مانند ثدیین و خُصیتین و مجموع گوشتها که معروف به غدد بود و قطع نزف دم و طمث دائم بکند چون با گلنار بری بخورند، چون به آب و روغن گُل بمالند خصیتین و ثدیین که در آن ورمی گرم بود ورم آن ساکن گرداند و قطع عرق بکند و چون با شراب بیاشامند گزندگی جانوران و ادویه ٔ کشنده را مفید بود. (اختیارات بدیعی ). به واو و بی واو و کوکب الارض نیز گویند. قسمی از آن سفید و ناصاف و باصفایح و شبیه به حجرالمسن و با اندک براقی میباشد و قسمی بسیار سفید و رقیق و سبک و بر زبان می چسبد و هر دو قسم در آب رود حل میشوند. و از بلاد قبرس و صقالبه آرند. در طبع و فعل قریب به گل مختوم و یک مثقال مغسول او با مثل آن گلنار قاطع حیض دائم و عرق و با شراب بجهت سموم حاره و با ادویه ٔ مناسبه جهت نفث الدم و سیلان خون جمیع اعضاء و حقنه ٔ او با آب و روغن گُل جهت اورام حاره و نقرس حار مفید است . (تحفه ٔ حکیم مؤمن ). طین شاموس و تحذف الواو و یقال کوکب الارض . صفائح تحکی المسن و منه دقیق ابیض و کله سریعالانحلال فی الماء. و هذا الطین یجلب من اواخر قبرس و یقال انه یوجد بصقلیه و هو بارد یابس فی الثانیة یقاوم السموم کلها و ینفع من الاستطلاق و الزحیر و قروح المعاء و حرارة الکبد و الدم حیث کان شرباً و الاورام و الترهل ضماداً و کذا للنقرس الحار. (تذکره ٔ ضریر انطاکی ص <span class=\"hlight\" dir=\"rtl\">٢٣٩</span>). کوکب الارض . کوکب شاموس . گِلی است که از جزیره ٔ ساموس آرند سپید و در آن لزوجتی است .<br /></font></div>'),
(178728, 'طین شفا', '<span class=\"hlight\">طین شفا.</span> <font color=\"DarkGreen\"><b>[ ن ِ ش ِ <span class=\"hlight\" dir=\"rtl\">/</span> ش َ ]</font></b> (ترکیب اضافی، اِ مرکب ) نزد اهل سنت خاک قبر امام حنبل است . و نزد بعضی تراب مدینه ٔ طیبه و نزد شیعه ٔ امامیه طین قبر حضرت سیدالشهداء امام حسین بن علی بن ابیطالب علیهم السلام است . (فهرست مخزن الادویة).<br /></font></div>'),
(178729, 'طین صعیدی', '<span class=\"hlight\">طین صعیدی .</span> <font color=\"DarkGreen\"><b>[ ن ِ ص َ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به طین صغدی شود.<br /></font></div>'),
(178730, 'طین صغدی', '<span class=\"hlight\">طین صغدی .</span> <font color=\"DarkGreen\"><b>[ ن ِ ص ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) ابوریحان در الجماهر در ضمن بحث استخراج یاقوت آرد: و چه بسا که یاقوت را از آتش استخراج کنند و آن هنگامی است که کاملاً خالص نباشد... ازاینرو یاقوت را میان دو بوته از طین صغدی داغ میکنند، و طین صغدی گِل سفیدی است که طاقت آتش را دارد. رجوع به الجماهر ص <span class=\"hlight\" dir=\"rtl\">٤٢</span> شود.<br /></font></div>'),
(178731, 'طین صنم', '<span class=\"hlight\">طین صنم .</span> <font color=\"DarkGreen\"><b>[ ن ِ ص َ ن َ ]</font></b> (ترکیب اضافی، اِ مرکب ) طین راهب است که طین اصفر باشد. (اختیارات بدیعی ) (فهرست مخزن الادویة).<br /></font></div>'),
(178732, 'طین صوفی حمید', '<span class=\"hlight\">طین صوفی حمید.</span> <font color=\"DarkGreen\"><b>[ ن ِ ح َ ]</font></b> (ترکیب اضافی، اِ مرکب ) خاکیست سفید و خوشبو که ازبلاد شیروان از بقعه ٔ صوفی حمید آرند. نگاه داشتن او مانع گزیدن مار و هوام و از مجرباتست . و به دستور، طلای او بر موضع گزیده و شرب او همین اثر دارد. و در سایر افعال مثل گِل قبرسی است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178733, 'طین علک', '<span class=\"hlight\">طین علک .</span> <font color=\"DarkGreen\"><b>[ ن ِ ع َ ل َ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به طین حر شود.<br /></font></div>'),
(178734, 'طین فارسی', '<span class=\"hlight\">طین فارسی .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) بهترین وی سرخ بود و بشیرازی وی را گل سرشوی گویند و طبیعت وی سرد و خشک بود و درد شُش را ساکن گرداند. چون دو مثقال از وی استعمال کنندگویند مضر بود بمثانه و مصلح وی سرطانات بود. (اختیارات بدیعی ). گل شیرازی است و گل سرشوی گویند مایل بزردی و خوشبو، جالی جلد و رافع چرک و در افعال قریب به گل ارمنی است و بعضی طین حر را مخصوص او میدانند.(تحفه ٔ حکیم مؤمن ). به هروی گل سرشوی گویند، بهترینش آن بود که سرخ رنگ باشد. طبیعتش سرد و خشک است در اول . چون به آب گشنیز تر یا لعاب اسپغول طلا کنند ورم های دموی را سودمند آید. گل سرشوی . (بحر الجواهر).<br /></font></div>'),
(178735, 'طین قبرسی', '<span class=\"hlight\">طین قبرسی .</span> <font color=\"DarkGreen\"><b>[ ن ِ ق ُ رُ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ رِ ]</font></b> (ترکیب وصفی، اِ مرکب ) گِل قبرسی . در قوت به گل ارمنی مشابهت تمام دارد جز آنکه قبرسی را قوت قبض و خشک کردن جراحتها زیاد است . (ترجمه ٔ صیدنه ). گلی است سرخ و گلگون و چون در دست بمالند سرخی آن در دست بماند و چون بشکند در اندرون وی رگهای زرد بود و چون بزبان نهند بچسبد بغایت چنانکه بحیله باز توان زد از زبان . و طبیعت وی سرد و خشک بود و در وی قبضی معتدل بود سودمند جهت مجموع جراحتها و ورمها را طلا کردن بغایت سودمند بود و مقدار مأخوذ از وی پنج درم بود و سحج معائی و کبدی را سودمند بود و نفث دم و قرحه ٔ امعاء آشامیدن و حقنه کردن نافع بود. جهت دفع ادویه ٔ قتاله چون یک درم از وی بیاشامند به آب سرد و مطبوخ سودمند بود و بدل آن طین مختوم بود. (اختیارات بدیعی ). سرخ درخشنده و خوشبو است وبر زبان بسیار میچسبد و در جمیع افعال قائم مقام گل مختوم است . (تحفه ٔ حکیم مؤمن ). گلیست که چون به دست بمالند سرخی او در دست بماند و چون بشکنند در درونش رگهای زرد باشد. طبیعتش سرد و خشک است در اول چون به گلاب و روغن گل طلا کنند شکستگی اعضا را نفع دهد و چون ده درم از او تا سه درم رغبت کنند سحج و نفث الدم را دفع کند و ذوسنطاریای کبدی و معوی را سودمند آید.گِلی است به رنگ گِل سرخ که از جزیره ٔ قبرس آرند.<br /></font></div>'),
(178736, 'طین قریطس', '<span class=\"hlight\">طین قریطس .</span> <font color=\"DarkGreen\"><b>[ ن ِ ق ِ طِ ]</font></b> (ترکیب اضافی، اِ مرکب ) طین اقریطس است .<br /></font></div>'),
(178737, 'طین قیملس', '<span class=\"hlight\">طین قیملس .</span> <font color=\"DarkGreen\"><b>[ ن ِ ؟ ]</font></b> (ترکیب اضافی، اِ مرکب ) طین مختوم به خواتیم بحیره است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178738, 'طین قیمولیا', '<span class=\"hlight\">طین قیمولیا.</span> <font color=\"DarkGreen\"><b>[ ن ِ ؟ ]</font></b> (ترکیب اضافی، اِ مرکب ) حجرالرخام هم خوانند و آن مانند صفایح رخام بود سفید و براق و خشبوی و گویند از وی بوی کافور آید چون تازه بود و آن نازک بود مانند جبسین و آن نوعی از رخام است . دیسقوریدس گوید آن دو نوع باشد یکی سفید و دیگر فرفیری ... و جالینوس گوید: قوه ٔ وی مرکب بود و در وی تحلیلی و تدبیری بود ازبهر آنکه چون مغسول کنند جزو محلل از وی دور شود و طبیعت وی سرد و خشک است . و چون با قدری سرکه و آب طلا کنند سوختگی آتش را نافع بود و آنچه خالص بود بسیار منفعت دارد. و چون با سرکه طلا کنند بر مجموع ورمهای گرم و ورم شیب معده نافع بود و ریشهای بسیار رحم چون بسوزانند و شسته و استعمال کنند زود بحال صحت آورد. مؤلف گوید:در کوهستان یزد میباشد و زنان جهت جلاء روی استعمال میکنند. ابن سمحون گوید: بدل وی طین مصری است . و ابن حسان گوید اهل بصره طین قیمولیا را طین الحر خوانندو اصناف وی بسیار است : ارمنی، سجلماسی و وی فاضل تر از اندلسی بود در معالجه و آن بغایت سفید بود و جرم وی صلب بود و زود شکسته نگردد و در آب حل نشود تا دیر زمان و چون حل شود در وی لزوجت بیشتر بود که در غیر وی . و اندلسی دو نوع بود یکی سفید و یکی سیاه، آنچه بغایت سفید بود در معالجه مستعمل کنند و آنچه سیاه بد بود تصرف در آن نشاید کردن . (اختیارات بدیعی ).<br />قسمی از آن سفید و قسمی مایل به بنفشی و چرب و بالزوجت و دیرشکن و در آب دیر حل میشوند و از بلاد اندلس و ارمن خیزد و قسم سیاه اندلسی زبون است . سرد و خشک و با قوت محلله و در افعال ضعیفتر از طین شاموس است . و بدلش طین مصری است . (تحفه ٔ حکیم مؤمن ).<br />الواحی باشد چون الواح رخام خوشبوی که از آن بوی کافور آید و آن برنگ سفید و نیز برنگ سرخ باشد و آن اندلسی و ارمنی باشد. طین قیمولیا را طین الحر نیز گفته اند.<br /></font></div>'),
(178739, 'طین لانی', '<span class=\"hlight\">طین لانی .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) طین ارمنی است . (فهرست مخزن الادویة).<br /></font></div>'),
(178740, 'طین مختوم', '<span class=\"hlight\">طین مختوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ م َ ]</font></b> (ترکیب وصفی، اِ مرکب ) با زهر مقاومت و مقابله کند و مضرت اورا دفع کند و زخم دندان و نیش گزندگان را دفع کند وآماسها را که ماده ٔ او از گرمی باشد سود دارد در وقتی که ابتدای او باشد و بادهای غلیظ را که به پاها فرودآید و جمله ٔ علتها را که در اعضا پدید آید نیکو گرداند و بر ریشی که بواسطه ٔ سوخته شدن آتش پدید آید نیکو گرداند چون با آب نباتی که او را لسان الحمل گویند با هم آمیخته شود. و اگر با طراثیث که صفت کردیم آمیخته شود زهری را که در مبرئت و غیر آن بکسی داده باشند بطریق قی دفع کند، و نیکوتر از همه ٔ انواع آن است که بوی او به بوی زاک یمانی مشابهت دارد. و اگر دردها داشته باشد رفتن خون را بازدارد و در او غشی می آمیزند و بهیچ طریق آن غشی را معلوم نمیتوان کرد. وهیئت او آن است که قرصها باشد و لون او سرخ بود و اجزای او بر یکدیگر مشابهت دارد و بر آن قرصها باشد. (ترجمه ٔ صیدنه ). بپارسی گل مختوم گویند. بهترینش آن است که از او بوی شبت آید و چون نزدیک دهان برند به لب بچسبد و طبیعتش نزدیک است به اعتدال، چون به شیر تازه میل کنند دفع ضرر جمیع زهرهای کشنده کند و چون به شیره ٔ خرفه یا شربت انجبار خورند نفث الدّم و سجح و ذوسنطاریای کبدی و معوی را سودمند آید. و دل و دماغ را قوت دهد و شربتی از او یک درم تا دو درم است .<br />گِلی سرخ رنگ است بغایت نرم و از تل بحیره آرند و گویند در آن زمین قطعاً نبات و حشیش نیست و سنگ نیز در آنجا نبود و قبری در آنجا هست و آن گل را مغره ٔ لمنیه و مغره ٔ لمانی و طین الکاهن خوانند ازبهر آنکه زنی ساحر آن گل یافته است و خواتیم لُمنیه نیز گویند. صورت ارطامس بر آن ایستاده .دیسقوریدس گوید: گلی است از جزیره ٔ لُمنیوس که بخون بز کوهی میسرشند و آن صورت بر آن مینهند و خواتیم الملک و ختم الملک ازبهر آن گویند که صورت ارطامس بر آن بود و اقوال بسیار آورده اند درین گل . جالینوس گوید:نیکوترین آن بود که از وی بوی شبت آید، خون را ببندد و چون در دهان گیرند بر زبان بچسبد. مؤلف گوید: امتحان آن چنان کنند که اول بر لب نهند، اگر نچسبد دیگر با زبر لب نهند تا بیقین معلوم گردد، و بغایت املس بود و براق . و گویند آن زمین که گل مختوم از وی آورند از زمین یونان بود و این زمان آنجا را آب گرفته است . و شیخ الرئیس گوید: طبیعت وی معتدل بود و گرمی وسردی مانند مزاج آدمی لکن خشکی وی زیادت از تری بودو در وی رطوبت فضلی هست که ممتزج باشد به یبوست و در وی خاصیتی عجب بود در تقویت دل و تفریح آن و تریاق مطلق بود و مقاومت با مجموع زهرها بکند. مؤلف گوید: کودکی قریب دو مثقال دیک بردیک که از سموم قتاله است خورده بود و درزمان قدری از طین مختوم با شیر مادربه وی دادند، آغاز قی کردن گرفت و مجموع برآمد، بعداز آن قدری هم با شیر مادر به وی دادند، دیگر قی کرد و یک دو مجلس نیز طبیعت مدد کرد از آن زهر کشنده خلاص یافت بفرمان خدای عزوجل . و بر مجموع ریشها که خون از وی روانه بود چون بر آن پاشند بسته گردد. و حقنه کردن بدان ذوسنطاریا را نافع بود و مقدار مأخوذ ازوی تا دو درم بود و جهت گزندگی جانوران کشنده و افعی و سگ دیوانه با شراب بیاشامند یا با سرکه طلا کنند نافع بود. کسی را که ذراریح خورده باشد یا ارنب بحری و گل مختوم بیاشامد در حال قی کند و دفع همان بکند و حب الغار نیز همین عمل کند در دفع سموم . و مسیح گوید: سحق کرده بیاشامند و وی در نان دفع وبا کند. و اسحاق گوید: مضر به شُش و مصلح وی گلاب بود و بدل آن درقبض خون گل رومی بود یا گل ارمنی که بخون بز کوهی سرشته باشند و گویند بدل وی مغره است در قبض لکن در تریاق بدل وی نیست . (اختیارات بدیعی ).<br />از جزیره ٔ لمیون بحر مغرب خیزد ودر قدیم زنی از تل خاک آنجا نقل به بقعه ٔ راهبی مینموده و بعد از شستن، قرصها میساخته و صورت راهب را در آن نقش میکرده و از این جهت طین الراهب نیز گویند. و دیسقوریدس و جالینوس را اعتقاد آنکه خاکیست بخون بز نر سرشته و بالفعل از جهت احاطه ٔ دریا بجزیره ٔ مذکور موجود نیست و بجای آن سایر خاکها را استعمال میکنند و بهترین او در غایت سرخی میباشد و در بوی شبیه به شبت و گویا بچربی آلوده شده و بر زبان چسبد و پاشیدن او درساعت قطع خون زخم تازه کند. در دوم سرد و خشک و تریاق جمیع سموم و مقوی دل و مفرح و رافع مضرت هوای وبائی و اسهال دموی و چرک و قرحه ٔ امعاء و تبهای حاره و نزف الدم اعضای ظاهر و باطن . و با شراب و آب گرم و شبت مقیی ٔ سموم و طلای او جهت تسکین التهاب و تحلیل صلابات و التیام جراحات تازه و کهنه و قروح خبیثه و زخم سگ دیوانه گزیده و شکستگی اعضا و ضربه و سقطه نافع و مضر ریه و مصلحش عسل و مضر سپرز و مصلح آن کتیرا و شربتش تا یک مثقال است و بدلش نزد حقیر گِل داغستانی است . و در امور مذکوره قویتر از آن است . (تحفه ٔ حکیم مؤمن ). مغرة لمنیة . خواتیم لمنیة . گلی باشد سخت چسبنده ٔ سرخ که از حیره آرند. (بحر الجواهر).در جزیره کیوش باشد. خاک و گلی است سرخ رنگ و از ادویه ٔ طبی قدیم <span class=\"hlight\">:</span> <br />طین مختوم و تخم ریحان بس <br />مار و مرغم که خاک و دانه خورم .<br /> <font color=\"Red\">خاقانی .</font><br />وآن را طین سجلات نیز نامند. و رجوع بمقدمه ٔ ابن خلدون ترجمه ٔ محمدِ پروین گنابادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥١</span> شود.<br /></font></div>'),
(178741, 'طین مصری', '<span class=\"hlight\">طین مصری .</span> <font color=\"DarkGreen\"><b>[ ن ِ م ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) ابلیز خوانند. جالینوس گوید: مطحولان و مستسقیان بسیار دیدم در اسکندریه طلا کردند نافع آمد، و بر ورمهای کهن و دردهای مزمن و بواسیر طلا کردن بغایت مفید بود. (اختیارات بدیعی ).<br /></font></div>'),
(178742, 'طین مصطکی', '<span class=\"hlight\">طین مصطکی .</span> <font color=\"DarkGreen\"><b>[ ن ِ م َ طَ ]</font></b> (ترکیب اضافی، اِ مرکب ) گِلی را که او را از خزینه ٔ <font color=\"DarkGreen\"><b>[ ظ : جزیره ٔ ]</font></b> اقریطس به اطراف برند، آن موضع را بلد المصطکی نیز گویند. شوینده ٔ هر جراحتهاست و گوشت تازه برویاند. (ترجمه ٔ صیدنه ). خاکیست خاکستری رنگ و باصفائح و ثقیل الوزن و در آب زود حل میشود و از جزیره ٔ خیوس که مصطکی حاصل می شود می آرند. در دوم گرم و خشک و جالی و مفتح و جاذب خون بظاهرجلد و نیکوکننده ٔ رخسار است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178743, 'طین مغره', '<span class=\"hlight\">طین مغره .</span> <font color=\"DarkGreen\"><b>[ ن ِ م َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ترکیب اضافی، اِ مرکب ) مغره است که بهندی کیرو نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(178744, 'طین مقلو', '<span class=\"hlight\">طین مقلو.</span> <font color=\"DarkGreen\"><b>[ ن ِ م َ ل ُوو ]</font></b> (ترکیب وصفی، اِ مرکب ) گِل بریان است که طین مأکول و طین نیشابوری نامند. (فهرست مخزن الادویه ). گل بریان .<br /></font></div>'),
(178745, 'طین منتقل', '<span class=\"hlight\">طین منتقل .</span> <font color=\"DarkGreen\"><b>[ ن ِ م ُ ت َ ؟ ]</font></b> (ترکیب وصفی، اِ مرکب ) طین نیشابوری است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178746, 'طین نیشابوری', '<span class=\"hlight\">طین نیشابوری .</span> <font color=\"DarkGreen\"><b>[ ن ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) طین مأکول خوانند و آن گِلی است که خام و بریان کرده خورندو بدان تنقل کنند و وی نوعی از طین الحر بود و لون وی بغایت سفید بود مانند اسفیداج و بشیرازی گل سفید خوانند. طبیعت وی سرد و خشک بود و گویند گرم بود بسبب شوری که دارد. قوت فم معده را بدهد و غشی را نافع بود و منع قی بکند و تری معده زایل کند. و مقدار مأخوذ از وی یک درم بود تا یک مثقال و زیاده ازین مفسد مزاج بود و سده آورد و سنگ در گرده پیدا کند و ضرر آن انیسون و تخم کرفس کم گرداند و ناخوردن وی اولی بود ازبهر آنکه فساد وی زیادت از صلاح وی بود. و آب رفتن از دهان در وقت خواب شهوت کلبیه را بغایت مفید بودو غثیان و کرب هیضه را سودمند بود. (اختیارات بدیعی ). طین خراسانیست . (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویه ). طین حرّ. طین مأکول . طین اکل . گل خوراکی .<br /></font></div>'),
(178747, 'طین کاهن', '<span class=\"hlight\">طین کاهن .</span> <font color=\"DarkGreen\"><b>[ ن ِ هَِ ]</font></b> (ترکیب اضافی، اِ مرکب ) طین مختوم است . (تحفه ٔ حکیم مؤمن ). گفته اند طین مختوم است و تحقیق آن است که طین اصفر است که طین صنم باشد. و رجوع به طین ختم و طین مختوم و ماده ٔ بعد شود.<br /></font></div>'),
(178748, 'طین کاهنی', '<span class=\"hlight\">طین کاهنی .</span> <font color=\"DarkGreen\"><b>[ ن ِ هَِ ]</font></b> (ترکیب وصفی، اِ مرکب ) طین مختوم را طین کاهنی هم گویند و آن بجز طین ارمنی است . (از حاشیه ٔ مقدمه ٔ ابن خلدون ترجمه ٔ محمدِپروین گنابادی ص <span class=\"hlight\" dir=\"rtl\">٣٥١</span> از قانون ابن سینا چ اروپا ص <span class=\"hlight\" dir=\"rtl\">١٨٤</span>). و رجوع به طین کاهن و طین ختم و طین مختوم شود.<br /></font></div>'),
(178749, 'طین کبوش', '<span class=\"hlight\">طین کبوش .</span> <font color=\"DarkGreen\"><b>[ ن ِ ک َ ]</font></b> (ترکیب اضافی، اِ مرکب ) مصطکی است .<br /></font></div>'),
(178750, 'طین کرمی', '<span class=\"hlight\">طین کرمی .</span> <font color=\"DarkGreen\"><b>[ ن ِ ک َ ]</font></b> (ترکیب وصفی، اِ مرکب ) انبالیطس فرماقیطس . به یونانی اساطیلس خوانند و معنی این اسم کرمی بود و بعضی فونافیطس خوانند و این اسم مشتق از فرمان بود و معنی آن دوا بود و این گل از مدینه ٔ سلوقیا از بلاد سوریا بود و نیکوترین وی آن بود که سیاه بود مانند فحم که از چوب صنوبر گیرند و آنچه خاکسترین رنگ بود بد بود. جالینوس گوید: بدان سبب طین کرمی خوانند که در فصل بهار در اول آنکه درخت کرم ورق بیرون کند این طین بر درخت وی بمالند کرمی که ورق انگور میخورد و چشمهای آن درخت سیاه میشود بکشد. دیسقوریدس گوید: وی قابض و ملین و سرد و در کحلها مستعمل کنند، موی مژه برویاند و جالینوس گوید که جوهر وی نزدیک به حجر بود. (اختیارات بدیعی ). خاکی است که از بلاد سوریا آرند سیاه و کریه الرائحة و مبرد و محلل است چون در ابتداء نمو تاک انگور بر آن بمالند تاک را از آفات نگاه دارد و به این جهت طین کرمی نامیده اند. جالی بدن و جهت حکه بسیار نافع و در اکتحال مستعمل است . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(178751, 'طین کواکب', '<span class=\"hlight\">طین کواکب .</span> <font color=\"DarkGreen\"><b>[ ن ِ ک َ ک ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) طین شاموس است . (فهرست مخزن الادویة).<br /></font></div>'),
(178752, 'طینة', '<span class=\"hlight\">طینة.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) شهری است نزدیک دمیاط (از توابع مصر). (منتهی الارب ) (آنندراج ). شهر کوچکی است بین فرما و تنیس بخاک مصر. (معجم البلدان ).<br /></font></div>'),
(178753, 'طینت', '<span class=\"hlight\">طینت .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (از ع، اِ)طینة. سرشت . (منتهی الارب ) (آنندراج ). فطرت، جبلت، خلقت، طبع، طبیعت، خمیره، آب و گل، گل آدمی، غریزه، نهاد، عنبرسرشت از صفات اوست . (آنندراج ) <span class=\"hlight\">:</span> <br />عدل را در طینت آدم مخمر کرد حق <br />تا برآری خلق را از ظلم چون موی از خمیر.<br /> <font color=\"Red\">سوزنی .</font><br />مرکب عزمش بگذشت و اثر کرد و گذاشت <br />طینت هفت زمین زآن اثر آمیخته اند.<br /> <font color=\"Red\">خاقانی .</font><br />همگنان گفته اند طینت آل سامان به آب کرم و لطف سرشت و عفو و اغتفار و اغماض ملوک ایشان ... متعارف بوده است . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span>). سلطان از سرگرمی که در طینت پاک او مجبول بود اورا امان داد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span>).<br />هر کسی بر طینت خود می تند.<br /> <font color=\"Red\">مولوی .</font><br />آن روی نمایدش که در طینت اوست <br />آئینه ٔ کج جمال ننماید راست .<br /> <font color=\"Red\">سعدی .</font><br />و رجوع به ج <span class=\"hlight\" dir=\"rtl\">٢</span> شعوری ص <span class=\"hlight\" dir=\"rtl\">١٦٨</span> شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بدطینت </span> ؛ بدنهاد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خُبث ِ طینت </span> ؛ ناپاکی سرشت .<br /><BR><font color=\"Blue\">◄</font> خوی . (منتهی الارب ) (آنندراج ). شیمة. <BR><font color=\"Blue\">◄</font> اندکی از گِل . (غیاث اللغات ) (آنندراج ). یکی از گِل . <BR><font color=\"Blue\">◄</font> سفالیست بی آب . (آنندراج ). <BR><font color=\"Blue\">◄</font> (اصطلاح فلسفه ) هیولی . ماده . عنصر. یکی از نامهای علت مادیه است . (کشاف اصطلاحات الفنون ). اُسطقس . مایه . <BR><font color=\"Blue\">◄</font> مقیاسی است از نقدینه ٔ طلا. بیرونی در کتاب الجماهر گوید: یک طینه ٔ طلا مساوی است با <span class=\"hlight\" dir=\"rtl\">١٦</span> ماشجه که هر ماشجه عبارتست از چهار دانگ طلا (اربع دوانیق ذهب ). (الجماهر چ حیدرآباد ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br /></font></div>'),
(178754, 'طینقروس البابلی', '<span class=\"hlight\">طینقروس البابلی .</span> <font color=\"DarkGreen\"><b>[ ق َ سِل ْ ب ِ ]</font></b> (اِخ ) یکی از سدنه ٔ سبعه ٔ بیوت کواکب سبعه به بابل . ابن الندیم گوید گمان میکنم او سادن خانه ٔ مریخ بوده . او راست : کتاب الموالیدعلی الوجود و الحدود. (الفهرست ابن الندیم ) (تاریخ الحکماء قفطی چ لیبسیک ص <span class=\"hlight\" dir=\"rtl\">٢١٨</span>). رجوع به تینگلوس شود.<br /></font></div>'),
(178755, 'طینوث', '<span class=\"hlight\">طینوث .</span> <font color=\"DarkGreen\"><b>[ طَ <span class=\"hlight\" dir=\"rtl\">/</span> طِ ]</font></b> (اِ) حیوانی باشد مانند ذَراریح لکن کوچکتر از اوست و فعل ذراریح از او می آید، و ذراریح جانوری است از مگس بزرگتر و عروسک همان است . (برهان ) (آنندراج ). حباحب است . (تحفه ٔ حکیم مؤمن ). حیوانیست مانند ذراریح لکن کوچکتر و گردتر بود و همان فعل ِ ذراریح کند. مؤلف گوید: وی را بشیرازی عروسک خوانند و بدل ذراریح بود و گویند کرمی سبز است در درخت صنوبر و آن بقوت ذراریح بود. (اختیارات بدیعی ). بپارسی موزه دوزک خوانند و آن حیوانیست سرخ که بر او نقطه های سیاه بود و از ذراریح خردتر باشد و در وقت انگور بر خوشه ٔ انگور نشیند. در خاصیت به ذراریح نزدیک است . موزه دوزک . کفشدوز (در تداول گناباد). کفشدوزک . پینه دوز.<br /></font></div>'),
(178756, 'طینوج', '<span class=\"hlight\">طینوج .</span> (اِخ ) دهی جزء دهستان حومه ٔ بخش دستجرد خلجستان شهرستان قم در <span class=\"hlight\" dir=\"rtl\">٣٠٠٠</span> گزی خاور دستجرد. کوهستانی و کنار رودخانه و سردسیر با <span class=\"hlight\" dir=\"rtl\">٩٦٧</span> تن سکنه . آب آن از قنات و رودخانه . محصول آنجا غلات و بنشن وانگور و گردو و زردآلو و بادام . شغل اهالی زراعت است . دبستان، پل آجری روی رود جهرود و کاروانسرای شاه عباسی قدیمی دارد. راه قدیمی کاروان رو قم به همدان ازاین ده میگذشته است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(178757, 'طینوری', '<span class=\"hlight\">طینوری .</span> (اِ) ظاهراً نوعی از ظروف چوبین است <span class=\"hlight\">:</span> و از وی <font color=\"DarkGreen\"><b>[ از آمل به طبرستان ]</font></b> آلاتهای چوبین خیزد چون کفچه و شانه و شانه نیام و ترازوخانه و کاسه و طَبَق و طینوری و آنچ بدین ماند. (حدود العالم ).<br /></font></div>'),
(178758, 'طینوس', '<span class=\"hlight\">طینوس .</span> (اِ) حباحب است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178759, 'طینوش', '<span class=\"hlight\">طینوش .</span> (اِخ ) نام پسر قیدافه (پادشاه اندلس ) که داماد فور هندی و معاصر اسکندر بود. فردوسی از زبان قیدافه به اسکندر خطاباً گوید <span class=\"hlight\">:</span> <br />چنان دان که طینوش فرزندمن <br />کم اندیشه از دانش و پند من <br />یکی بادسار است و داماد فور<br />نباید که داند ز نزدیک و دور.<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> نام سفیری رومی نزد یزدگرد. (لغات شاهنامه ٔ رضازاده ٔ شفق ).<br /></font></div>'),
(178760, 'طینی', '<span class=\"hlight\">طینی .</span> <font color=\"DarkGreen\"><b>[ نی ی ]</font></b> (ع ص نسبی ) منسوب بفروشنده ٔگِل ِ شور که مردم آن را میخورند. (انساب سمعانی ).<br /></font></div>'),
(178761, 'طیهااوجیوس', '<span class=\"hlight\">طیهااوجیوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی قاتل الکلب است و خانق الکلب نیز نامند. (فهرست مخزن الادویه ).<br /></font></div>'),
(178762, 'طیهوج', '<span class=\"hlight\">طیهوج .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (معرب، اِ) معرب تیهو است، و آن مرغی باشد شبیه به کبک لکن از کبک کوچکتر است . (برهان ) (غیاث اللغات ). بعضی گویند که بهندی آن را لوا نامند. (غیاث اللغات ) (آنندراج ). تیهو نر. (منتهی الارب ). ج، طَیاهیج . (مهذب الاسماء). بپارسی تیهو گویند و بزبان اندلسی دریس . بهترین وی نر فربه بود که در زمان خریف گیرند و طبیعت وی معتدل بود، شکم ببندد و ناقهان را بغایت مفید بود و نشاید که اصحا ادمان اکل وی کنند خصوصاً اصحاب ریاضت، و اولی آن بود که در هریسه بپزند ازبهر آنکه غذاء وی غلیظ بود. (اختیارات بدیعی ). بفارسی تیهو نامند. از کبک کوچکتر و در رنگ مثل اوست و در جمیع افعال مانند آن و جهت ناقهین و ضعیف الاحشاء بغایت نافع است . (تحفه ٔ حکیم مؤمن ). در طبیعت با کبک برابر و منافع آن نیز با منافع کبک مساوی است اما رنگ تیهو بزردی مایل و زیر بالهای وی سیاه رنگ میباشد. (تذکره ٔ داود ضریر انطاکی ). معرب تیهو فارسی است و جمع آن طیاهیج است و بفارسی فرفور نیز نامند و به اندلسی ضریس به ضاد و ذریس به ذال نیز گویند. مرغی است کوهی کوچکتر از کبک و در رنگ شبیه بدان و زیر بال آن سیاه با سفیدی . بهترین آن فربه جوان قریب به معموره است . رازی گفته آن مرغیست بقدر کبک، گردن و منقار آن سرخ، طبیعت و افعال و خواص آن مانند کبک است و جهت ناقهین و ضعیف الاحشاء بغایت نافع. (مخزن الادویه ) <span class=\"hlight\">:</span> و طعام او <font color=\"DarkGreen\"><b>[ خداوند معده ٔ گرم ]</font></b> گوشت بزغاله و مرغ خانگی و تذرو وطیهوج ... (ذخیره ٔ خوارزمشاهی ). رجوع به تیهو شود.<br /></font></div>'),
(178763, 'طیوب', '<span class=\"hlight\">طیوب .</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طیب . عطرها. عطریات : و هو <font color=\"DarkGreen\"><b>[ ساداوران ]</font></b> یدخل فی الطیوب و الغوالی . (ابن البیطار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(178764, 'طیودیجیزل', '<span class=\"hlight\">طیودیجیزل .</span> <font color=\"DarkGreen\"><b>[ ی ُ دی زِ ]</font></b> (اِخ ) دومین پادشاه گتهای غربی در اسپانیا که بسال <span class=\"hlight\" dir=\"rtl\">٥٤٨</span> م . در آن کشور به سلطنت رسیده است . (از الحلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span>).<br /></font></div>'),
(178765, 'طیور', '<span class=\"hlight\">طیور.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِ) ج ِ طیر. پرندگان . مرغان . جج ِ طائر <span class=\"hlight\">:</span> الا آنک او را باد و دیو و پری و وحوش و طیور در فرمان بود و مرا نیست . (ترجمه ٔ طبری بلعمی ).<br />بدام زلف تو گه آدمی و گاه ملک <br />گهی وحوش گرفتار و گه طیورانند.<br /><font color=\"Red\">حکیم حاذق (آنندراج ).</font><br /></font></div>'),
(178766, 'طیور', '<span class=\"hlight\">طیور.</span> <font color=\"DarkGreen\"><b>[ طَی ْ یو ]</font></b> (ع ص ) تیزرو. <BR><font color=\"Blue\">◄</font> چالاک . یقال : هو طیورٌ فیورٌ؛ ای حدیدٌ سریعالفیئة. (منتهی الارب ). ای سریعالتحول من امر الی آخر. (قُطر المحیط).<br /></font></div>'),
(178767, 'طیور سدره', '<span class=\"hlight\">طیور سدره .</span> <font color=\"DarkGreen\"><b>[ طُ رِ س ِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ترکیب اضافی، اِ مرکب )کنایه از فرشتگان آسمان باشد. (برهان ) (آنندراج ).<br /></font></div>'),
(178768, 'طیوری', '<span class=\"hlight\">طیوری .</span> <font color=\"DarkGreen\"><b>[ طُ ری ی ]</font></b> (ع ص نسبی ) مرغ فروش . (مهذب الاسماء). بائع الطیر. (قطر المحیط).<br /></font></div>'),
(178769, 'طیوسا', '<span class=\"hlight\">طیوسا.</span> (اِ) خربق است . (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(178770, 'طیوط', '<span class=\"hlight\">طیوط.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ع اِمص ) سختی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (مص ) تیزشهوت گردیدن گُشن و بانگ کردن . یقال : طاطَ الفحل طُیوطاً. (منتهی الارب ) (تاج المصادر بیهقی ).<br /></font></div>'),
(178771, 'طیوقون', '<span class=\"hlight\">طیوقون .</span> (معرب، اِ) تاج خروس . بوستان افروز.<br /></font></div>'),
(178772, 'طیولا', '<span class=\"hlight\">طیولا.</span> (اِخ ) دهی است جزء دهستان اشکور پائین بخش رودسر شهرستان لاهیجان در <span class=\"hlight\" dir=\"rtl\">٤٢</span> هزارگزی جنوب رودسر و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی باختر سی پل . کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٩٥</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات و بنشن و ارزن و فندق و گردو و لبنیات . و شغل اهالی زراعت و گله داری و کرباس و شال بافی . راه آن مالرو و صعب العبور. این ده از دومحله ٔ بالا و پائین که فاصله ٔ آن دو آبادی یک کیلومتر است تشکیل شده است و اکثر سکنه زمستان برای تأمین معاش به گیلان میروند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(178773, 'طیومالس', '<span class=\"hlight\">طیومالس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی برشیان دارو است . (فهرست مخزن الادویه ).<br /></font></div>'),
(178774, 'طیون', '<span class=\"hlight\">طیون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) برنوف . رجوع به برنوف شود.<br /></font></div>');
